## 2. `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: calendar.startOfDay(for: date), habit: self)
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completionDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while completionDays.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }
}
```

