import SwiftUI

struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    var body: some View {
        HStack(spacing: 12) {
            Circle()
                .fill(Color(hex: habit.colorHex))
                .frame(width: 14, height: 14)

            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)

                if !habit.detail.isEmpty {
                    Text(habit.detail)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Text("Streak: \(habit.currentStreak()) day\(habit.currentStreak() == 1 ? "" : "s")")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Button {
                toggleToday(for: habit)
            } label: {
                Image(systemName: habit.isCompleted(on: Date()) ? "checkmark.circle.fill" : "circle")
