                    .foregroundStyle(habit.isCompleted(on: Date()) ? .green : .gray)
            }
            .buttonStyle(.plain)
        }
        .padding(.vertical, 4)
    }

    private func toggleToday(for habit: Habit) {
        habit.toggleCompletion(for: Date())

        do {
            try modelContext.save()
        } catch {
            print("Failed to toggle completion: \(error)")
        }
    }
