## 6. `HabitDetailView.swift`

```swift
import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    private let calendar = Calendar.current

    var sortedCompletions: [HabitCompletion] {
        habit.completions.sorted { $0.date > $1.date }
    }

    var body: some View {
        List {
            Section("Overview") {
                HStack {
                    Text("Name")
                    Spacer()
                    Text(habit.name)
                        .foregroundStyle(.secondary)
                }

                if !habit.detail.isEmpty {
                    HStack {
                        Text("Description")
                        Spacer()
                        Text(habit.detail)
                            .foregroundStyle(.secondary)
                    }
                }

                HStack {
                    Text("Current Streak")
                    Spacer()
                    Text("\(habit.currentStreak())")
                        .foregroundStyle(.secondary)
                }

                HStack {
                    Text("Completed Today")
                    Spacer()
                    Image(systemName: habit.isCompleted(on: Date()) ? "checkmark.circle.fill" : "xmark.circle")
                        .foregroundStyle(habit.isCompleted(on: Date()) ? .green : .red)
                }
            }

            Section("Actions") {
                Button(habit.isCompleted(on: Date()) ? "Mark Incomplete Today" : "Mark Complete Today") {
                    habit.toggleCompletion(for: Date())
                    save()
                }
            }

            Section("Completion History") {
                if sortedCompletions.isEmpty {
                    Text("No completions yet")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(sortedCompletions) { completion in
                        HStack {
                            Text(formattedDate(completion.date))
                            Spacer()
                            Image(systemName: "checkmark")
                                .foregroundStyle(.green)
                        }
                    }
                    .onDelete(perform: deleteCompletions)
                }
            }
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }

    private func deleteCompletions(at offsets: IndexSet) {
        for index in offsets {
            let completion = sortedCompletions[index]
            modelContext.delete(completion)
        }
        save()
    }

    private func save() {
        do {
            try modelContext.save()
        } catch {
            print("Failed to save: \(error)")
        }
    }

    private func formattedDate(_ date: Date) -> String {
        date.formatted(date: .abbreviated, time: .omitted)
    }
}
```

