# 6. `Utilities/HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func hasEntryToday(for habit: Habit) -> Bool {
        let today = Date().startOfDayLocal
        return habit.entries.contains { $0.date.isSameDay(as: today) }
    }

    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.habitCalendar
        let uniqueDays = Set(habit.entries.map { $0.date.startOfDayLocal })

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var currentDay = Date().startOfDayLocal

        if !uniqueDays.contains(currentDay) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay),
                  uniqueDays.contains(yesterday.startOfDayLocal) else {
                return 0
            }
            currentDay = yesterday.startOfDayLocal
        }

        while uniqueDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay.startOfDayLocal
        }

        return streak
    }

    static func completionCount(for habit: Habit) -> Int {
        Set(habit.entries.map { $0.date.startOfDayLocal }).count
    }
}
```

