# 9. `Views/HabitDetailView.swift`

```swift
import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var sortedEntries: [HabitEntry] {
        habit.entries.sorted { $0.date > $1.date }
    }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                headerCard

                Button {
                    toggleToday()
                } label: {
                    HStack {
                        Image(systemName: HabitStats.hasEntryToday(for: habit) ? "checkmark.circle.fill" : "circle")
                        Text(HabitStats.hasEntryToday(for: habit) ? "Completed Today" : "Mark Complete Today")
                            .fontWeight(.semibold)
                    }
                    .frame(maxWidth: .infinity)
                    .padding()
                    .background(Color(hex: habit.colorHex).opacity(0.15))
                    .foregroundStyle(Color(hex: habit.colorHex))
                    .clipShape(RoundedRectangle(cornerRadius: 14))
                }

                VStack(alignment: .leading, spacing: 12) {
                    Text("History")
                        .font(.headline)

                    if sortedEntries.isEmpty {
                        Text("No completions yet.")
                            .foregroundStyle(.secondary)
                    } else {
                        ForEach(sortedEntries) { entry in
                            HStack {
                                Image(systemName: "checkmark.circle.fill")
                                    .foregroundStyle(.green)
                                Text(entry.date, style: .date)
                                Spacer()
                            }
                            .padding(.vertical, 6)

                            Divider()
                        }
                    }
                }
            }
            .padding()
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }

    private var headerCard: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Circle()
                    .fill(Color(hex: habit.colorHex))
                    .frame(width: 16, height: 16)

                Text(habit.name)
                    .font(.title2.bold())
            }

            if !habit.detail.isEmpty {
                Text(habit.detail)
                    .foregroundStyle(.secondary)
            }

            HStack(spacing: 16) {
                statView(title: "Current Streak", value: "\(HabitStats.currentStreak(for: habit))")
                statView(title: "Total Completions", value: "\(HabitStats.completionCount(for: habit))")
                statView(title: "Today", value: HabitStats.hasEntryToday(for: habit) ? "Done" : "Open")
            }
        }
        .padding()
        .background(.thinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 18))
    }

    private func statView(title: String, value: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(value)
                .font(.headline)
            Text(title)
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func toggleToday() {
        let today = Date().startOfDayLocal

        if let existing = habit.entries.first(where: { $0.date.isSameDay(as: today) }) {
            modelContext.delete(existing)
        } else {
            let entry = HabitEntry(date: today, habit: habit)
            modelContext.insert(entry)
            habit.entries.append(entry)
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to save toggle: \(error)")
        }
    }
}
```

