# 2. Data Models

## `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4CAF50",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: date)
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let sortedDates = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        if !sortedDates.contains(checkDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: checkDate),
                  sortedDates.contains(yesterday) else {
                return 0
            }
            checkDate = yesterday
        }

        while sortedDates.contains(checkDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: checkDate) else {
                break
            }
            checkDate = previous
        }

        return streak
    }
}
```

