    func isCompleted(on date: Date) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }

    func completionForDate(_ date: Date) -> HabitCompletion? {
        let day = Calendar.current.startOfDay(for: date)
        return completions.first { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }

    func currentStreak(asOf date: Date = Date()) -> Int {
        let calendar = Calendar.current
        let sortedDays = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDays.isEmpty else { return 0 }

        var streak = 0
        var cursor = calendar.startOfDay(for: date)

        if !sortedDays.contains(where: { calendar.isDate($0, inSameDayAs: cursor) }) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: cursor),
                  sortedDays.contains(where: { calendar.isDate($0, inSameDayAs: yesterday) }) else {
                return 0
            }
            cursor = yesterday
        }

        while sortedDays.contains(where: { calendar.isDate($0, inSameDayAs: cursor) }) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: cursor) else { break }
            cursor = previous
        }

        return streak
    }

