import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade) var logs: [HabitLog]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4CAF50",
        createdAt: Date = Date(),
        logs: [HabitLog] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.logs = logs
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        logs.contains { calendar.isDate($0.date, inSameDayAs: date) }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = logs.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            logs.removeAll { $0.id == existing.id }
        } else {
            let log = HabitLog(date: calendar.startOfDay(for: date))
            logs.append(log)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completedDays = Set(logs.map { calendar.startOfDay(for: $0.date) })
        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while completedDays.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        logs.count
    }
}

@Model
final class HabitLog {
    var id: UUID
    var date: Date

    init(id: UUID = UUID(), date: Date) {
        self.id = id
        self.date = date
    }
}
