@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            completions.append(HabitCompletion(date: calendar.startOfDay(for: date)))
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completionDays = Set(completions.map { calendar.startOfDay(for: $0.date) })
        guard !completionDays.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while completionDays.contains(day) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }

    func totalCompletions() -> Int {
