# 4. Habit business logic

## `Habit+Logic.swift`

```swift
import Foundation

extension Habit {
    func isCompleted(on date: Date = Date()) -> Bool {
        completions.contains { $0.isSameDay(as: date) }
    }

    func toggleCompletion(for date: Date = Date()) {
        if let index = completions.firstIndex(where: { $0.isSameDay(as: date) }) {
            completions.remove(at: index)
        } else {
            completions.append(date.startOfDayLocal)
            completions.sort()
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completions.map { calendar.startOfDay(for: $0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(day) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: day),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            day = yesterday
        }

        while uniqueDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }

        return streak
    }

    var totalCompletions: Int {
        Set(completions.map { Calendar.current.startOfDay(for: $0) }).count
    }
}
```

