## C. Add Weekly Progress

You can compute the last 7 days:

```swift
func completionsLast7Days(calendar: Calendar = .current) -> [Date: Bool] {
    var result: [Date: Bool] = [:]

    for offset in 0..<7 {
        if let date = calendar.date(byAdding: .day, value: -offset, to: Date()) {
            let day = calendar.startOfDay(for: date)
            result[day] = isCompleted(on: day, calendar: calendar)
        }
    }

    return result
}
```

