# 5. Habit Row View

Create `HabitRowView.swift`:

```swift
import SwiftUI

struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                VStack(alignment: .leading, spacing: 4) {
                    Text(habit.name)
                        .font(.headline)

                    if !habit.detail.isEmpty {
                        Text(habit.detail)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }

                Spacer()

                Button {
                    toggleTodayCompletion()
                } label: {
                    Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                        .font(.title2)
                        .foregroundStyle(isCompletedToday ? .green : .gray)
                }
                .buttonStyle(.plain)
            }

            HStack {
                Label("\(currentStreak) day streak", systemImage: "flame.fill")
                    .foregroundStyle(.orange)

                Spacer()

                Text(isCompletedToday ? "Done today" : "Not done today")
                    .font(.caption)
                    .foregroundStyle(isCompletedToday ? .green : .secondary)
            }
            .font(.subheadline)
        }
        .padding(.vertical, 4)
    }

    private var isCompletedToday: Bool {
        let calendar = Calendar.current
        return habit.completionDates.contains { calendar.isDateInToday($0) }
    }

    private var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(
            habit.completionDates.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    private func toggleTodayCompletion() {
        let calendar = Calendar.current

        if let index = habit.completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            habit.completionDates.remove(at: index)
        } else {
            habit.completionDates.append(Date())
        }

        try? modelContext.save()
    }
}
```

