# 2. Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var sortedCompletionDates: [Date] {
        completionDates
            .map { Calendar.current.startOfDay(for: $0) }
            .sorted()
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains {
            Calendar.current.isDate($0, inSameDayAs: today)
        }
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let index = completionDates.firstIndex(where: {
            calendar.isDate($0, inSameDayAs: today)
        }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        let uniqueDays = Array(Set(sortedCompletionDates))
            .sorted(by: >)

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !calendar.isDate(uniqueDays[0], inSameDayAs: currentDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  calendar.isDate(uniqueDays[0], inSameDayAs: yesterday) else {
                return 0
            }
            currentDate = yesterday
        }

        for date in uniqueDays {
            if calendar.isDate(date, inSameDayAs: currentDate) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                    break
                }
                currentDate = previous
            } else if date < currentDate {
                break
            }
        }

        return streak
    }

    func totalCompletions() -> Int {
        let uniqueDays = Set(completionDates.map { Calendar.current.startOfDay(for: $0) })
        return uniqueDays.count
    }
}
