## Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var colorHex: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    var sortedCompletions: [HabitCompletion] {
        completions.sorted { $0.date < $1.date }
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            completions.append(HabitCompletion(date: calendar.startOfDay(for: date)))
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(currentDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            currentDate = yesterday
        }

        while uniqueDays.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        let uniqueDays = Set(completions.map { Calendar.current.startOfDay(for: $0.date) })
        return uniqueDays.count
    }
}
