                    Spacer()
                    Button(habit.isCompleted(on: Date()) ? "Yes" : "No") {
                        habit.toggleCompletion(for: Date())
                        try? modelContext.save()
                    }
                    .buttonStyle(.borderedProminent)
                }

                HStack {
                    Label("Current Streak", systemImage: "flame.fill")
                    Spacer()
                    Text("\(habit.currentStreak()) days")
                }

                HStack {
                    Label("Longest Streak", systemImage: "trophy.fill")
                    Spacer()
                    Text("\(habit.longestStreak()) days")
                }

                HStack {
                    Label("Total Completions", systemImage: "number.circle.fill")
                    Spacer()
                    Text("\(habit.completions.count)")
                }
            }

            if !habit.detail.isEmpty {
                Section("Notes") {
                    Text(habit.detail)
                }
            }

            Section("Completion History") {
                if habit.sortedCompletions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.sortedCompletions.reversed()) { completion in
                        HStack {
                            Image(systemName: "checkmark.circle.fill")
                                .foregroundStyle(.green)
                            Text(formattedDate(completion.date))
                        }
                    }
                    .onDelete(perform: deleteCompletions)
                }
            }
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }

    private func deleteCompletions(at offsets: IndexSet) {
        let reversed = habit.sortedCompletions.reversed()
        let items = Array(reversed)

        for index in offsets {
            let completion = items[index]
            if let actualIndex = habit.completions.firstIndex(where: { $0.id == completion.id }) {
                habit.completions.remove(at: actualIndex)
            }
        }

        try? modelContext.save()
    }

    private func formattedDate(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = calendar
        formatter.dateStyle = .medium
        formatter.timeStyle = .none
        return formatter.string(from: date)
    }
}
