```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completionDates = completionDates
    }
}

extension Habit {
    func isCompleted(on date: Date = Date(), calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    func toggleCompletion(for date: Date = Date(), calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    func totalCompletions(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )
        return normalizedDates.count
    }
}
