        } catch {
            print("Failed to save habit: \(error)")
        }
    }

    func deleteHabit(_ habit: Habit, context: ModelContext) {
        context.delete(habit)

        do {
            try context.save()
        } catch {
            print("Failed to delete habit: \(error)")
        }
    }

    func toggleHabitToday(_ habit: Habit, context: ModelContext) {
        habit.toggleTodayCompletion()

        do {
            try context.save()
        } catch {
            print("Failed to toggle completion: \(error)")
        }
    }
}
