```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func markCompletedToday(calendar: Calendar = .current) {
        guard !isCompletedToday(calendar: calendar) else { return }
        completionDates.append(Date())
    }

    func unmarkCompletedToday(calendar: Calendar = .current) {
        completionDates.removeAll { calendar.isDateInToday($0) }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while uniqueDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }

    func totalCompletions(calendar: Calendar = .current) -> Int {
        Set(completionDates.map { calendar.startOfDay(for: $0) }).count
    }
}
```

