# 5. Streak Logic + Color Helper

You referenced `HabitStats.currentStreak` and `Color.fromHex`, so here are those helpers.

## `Utilities/HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let completionDays = Set(habit.completions.map { calendar.startOfDay(for: $0.date) })

        guard !completionDays.isEmpty else { return 0 }

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        if !completionDays.contains(currentDay) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay),
                  completionDays.contains(yesterday) else {
                return 0
            }
            currentDay = yesterday
        }

        while completionDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }
}
```

## `Utilities/Color+Hex.swift`

```swift
import SwiftUI

extension Color {
    static func fromHex(_ hex: String) -> Color {
        let cleaned = hex.trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "#", with: "")

        guard cleaned.count == 6, let int = Int(cleaned, radix: 16) else {
            return .indigo
        }

        let red = Double((int >> 16) & 0xFF) / 255.0
        let green = Double((int >> 8) & 0xFF) / 255.0
        let blue = Double(int & 0xFF) / 255.0

        return Color(red: red, green: green, blue: blue)
    }
}
```

