struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Circle()
                    .fill(colorFromHex(habit.colorHex))
                    .frame(width: 12, height: 12)

                VStack(alignment: .leading, spacing: 2) {
                    Text(habit.name)
                        .font(.headline)

                    if !habit.habitDescription.isEmpty {
                        Text(habit.habitDescription)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }

                Spacer()

                Button {
                    toggleTodayCompletion()
                } label: {
                    Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                        .font(.title2)
                        .foregroundStyle(isCompletedToday ? .green : .secondary)
                }
                .buttonStyle(.plain)
            }

            HStack {
                Label("\(currentStreak) day streak", systemImage: "flame.fill")
                    .font(.caption)
                    .foregroundStyle(.orange)

                Spacer()

                Text(isCompletedToday ? "Done today" : "Not done today")
                    .font(.caption)
                    .foregroundStyle(isCompletedToday ? .green : .secondary)
            }
        }
        .padding(.vertical, 4)
    }

    private var isCompletedToday: Bool {
        habit.completions.contains { $0.date.isSameDay(as: Date()) }
    }

    private var currentStreak: Int {
        let completionDays = Set(habit.completions.map { $0.date.startOfDay })
        var streak = 0
        var date = Date().startOfDay

        if !completionDays.contains(date) {
            date = date.addingDays(-1)
        }

        while completionDays.contains(date) {
            streak += 1
            date = date.addingDays(-1)
        }

        return streak
    }

    private func toggleTodayCompletion() {
        let today = Date().startOfDay

        if let existing = habit.completions.first(where: { $0.date.isSameDay(as: today) }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: today, habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to toggle completion: \(error)")
        }
    }

    private func colorFromHex(_ hex: String) -> Color {
        let cleaned = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: cleaned).scanHexInt64(&int)

        let a, r, g, b: UInt64
        switch cleaned.count {
        case 8:
            (a, r, g, b) = (
                (int >> 24) & 0xFF,
                (int >> 16) & 0xFF,
                (int >> 8) & 0xFF,
                int & 0xFF
            )
        case 6:
            (a, r, g, b) = (255, (int >> 16) & 0xFF, (int >> 8) & 0xFF, int & 0xFF)
        default:
            (a, r, g, b) = (255, 79, 70, 229)
        }

        return Color(
            .sRGB,
            red: Double(r) / 255,
            green: Double(g) / 255,
            blue: Double(b) / 255,
            opacity: Double(a) / 255
        )
    }
}
