# 5. Habit Row View

## `Views/HabitRowView.swift`

```swift
import SwiftUI
import SwiftData

struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                VStack(alignment: .leading, spacing: 4) {
                    Text(habit.name)
                        .font(.headline)

                    if !habit.habitDescription.isEmpty {
                        Text(habit.habitDescription)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }

                Spacer()

                Button {
                    incrementToday()
                } label: {
                    Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                        .font(.title2)
                        .foregroundStyle(isCompletedToday ? .green : .gray)
                }
                .buttonStyle(.plain)
            }

            HStack {
                Label("Today: \(todayCount)/\(habit.targetPerDay)", systemImage: "sun.max")
                Spacer()
                Label("Streak: \(currentStreak)", systemImage: "flame.fill")
                    .foregroundStyle(.orange)
            }
            .font(.caption)
            .foregroundStyle(.secondary)

            ProgressView(value: progressToday)
                .tint(.green)
        }
        .padding(.vertical, 6)
    }

    private var todayCompletion: HabitCompletion? {
        habit.completions.first(where: { $0.date.isSameDay(as: Date()) })
    }

    private var todayCount: Int {
        todayCompletion?.count ?? 0
    }

    private var isCompletedToday: Bool {
        todayCount >= habit.targetPerDay
    }

    private var progressToday: Double {
        min(Double(todayCount) / Double(habit.targetPerDay), 1.0)
    }

    private var sortedCompletionDays: [Date] {
        habit.completions
            .filter { $0.count > 0 }
            .map { $0.date.startOfDayLocal }
            .sorted(by: >)
    }

    private var currentStreak: Int {
        let calendar = Calendar.habitCalendar
        let uniqueDays = Array(Set(sortedCompletionDays)).sorted(by: >)

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var expectedDay = Date().startOfDayLocal

        if !calendar.isDate(uniqueDays[0], inSameDayAs: expectedDay) {
            let yesterday = expectedDay.addingDays(-1)
            guard calendar.isDate(uniqueDays[0], inSameDayAs: yesterday) else {
                return 0
            }
            expectedDay = yesterday
        }

        for day in uniqueDays {
            if calendar.isDate(day, inSameDayAs: expectedDay) {
                streak += 1
                expectedDay = expectedDay.addingDays(-1)
            } else if day < expectedDay {
                break
            }
        }

        return streak
    }

    private func incrementToday() {
        if let completion = todayCompletion {
            completion.count += 1
        } else {
            let completion = HabitCompletion(date: Date(), count: 1, habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to update completion: \(error)")
        }
    }
}
```

