```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completions = completions
    }

    var sortedCompletions: [HabitCompletion] {
        completions.sorted { $0.date < $1.date }
    }

    func isCompleted(on date: Date) -> Bool {
        let target = Calendar.current.startOfDay(for: date)
        return completions.contains {
            Calendar.current.isDate($0.date, inSameDayAs: target)
        }
    }

    func markCompleted(on date: Date = Date()) {
        guard !isCompleted(on: date) else { return }
        completions.append(HabitCompletion(date: Calendar.current.startOfDay(for: date)))
    }

    func unmarkCompleted(on date: Date = Date()) {
        completions.removeAll {
            Calendar.current.isDate($0.date, inSameDayAs: date)
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let completionDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while completionDays.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previous
        }

        return streak
    }

    var totalCompletions: Int {
        Set(completions.map { Calendar.current.startOfDay(for: $0.date) }).count
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date

    init(id: UUID = UUID(), date: Date) {
        self.id = id
        self.date = date
    }
}
