```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var completedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current

        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !normalizedDates.contains(currentDate) {
            currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        while normalizedDates.contains(currentDate) {
            streak += 1
            currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        return streak
    }
}
```

