import Foundation

@MainActor
final class HabitViewModel: ObservableObject {

    func isCompletedToday(_ habit: Habit) -> Bool {
        let calendar = Calendar.current
        return habit.completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleTodayCompletion(for habit: Habit) {
        let calendar = Calendar.current

        if let index = habit.completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            habit.completionDates.remove(at: index)
        } else {
            habit.completionDates.append(Date())
        }
    }

    func currentStreak(for habit: Habit) -> Int {
