# 3. Analytics Utility

## `Utilities/HabitAnalytics.swift`

```swift
import Foundation

enum HabitAnalytics {
    static func isCompletedToday(_ habit: Habit) -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completions.contains {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }
    }

    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let completionDays = Set(habit.completions.map { calendar.startOfDay(for: $0.date) })

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while completionDays.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    static func completedCountThisWeek(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let now = Date()
        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: now) else {
            return 0
        }

        return habit.completions.filter { completion in
            weekInterval.contains(completion.date)
        }.count
    }

    static func completionRateThisWeek(for habit: Habit) -> Double {
        guard habit.targetPerWeek > 0 else { return 0 }
        return min(Double(completedCountThisWeek(for: habit)) / Double(habit.targetPerWeek), 1.0)
    }

    static func toggleToday(for habit: Habit) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            calendar.isDate($0.date, inSameDayAs: today)
        }) {
            if let index = habit.completions.firstIndex(where: { $0.id == existing.id }) {
                habit.completions.remove(at: index)
            }
        } else {
            let completion = HabitCompletion(date: today, habit: habit)
            habit.completions.append(completion)
        }
    }
}
```

