                    Text(habit.habitDescription)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Text("Streak: \(currentStreak) day\(currentStreak == 1 ? "" : "s")")
                    .font(.caption)
                    .foregroundStyle(.secondary)
