# 9. Habit Stats Helper

You referenced `HabitStats` and `Color(hex:)`, so here are those helpers too.

## `Utilities/HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current

        let completedDays = Set(
            habit.completions
                .filter { $0.count >= habit.targetPerDay }
                .map { calendar.startOfDay(for: $0.date) }
        )

        guard !completedDays.isEmpty else { return 0 }

        var streak = 0
        var date = calendar.startOfDay(for: Date())

        if !completedDays.contains(date) {
            date = calendar.date(byAdding: .day, value: -1, to: date) ?? date
        }

        while completedDays.contains(date) {
            streak += 1
            date = calendar.date(byAdding: .day, value: -1, to: date) ?? date
        }

        return streak
    }
}
```

