# 2. Habit Model

## `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !normalizedDates.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !normalizedDates.contains(currentDate) {
            currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        for date in normalizedDates {
            if calendar.isDate(date, inSameDayAs: currentDate) {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if date < currentDate {
                break
            }
        }

        return streak
    }

    func markCompletedToday() {
        guard !isCompletedToday else { return }
        completedDates.append(Date())
    }

    func unmarkCompletedToday() {
        completedDates.removeAll { Calendar.current.isDateInToday($0) }
    }
}
```

