# 2. Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]
    var colorHex: String

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = [],
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
        self.colorHex = colorHex
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalized = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var date = calendar.startOfDay(for: Date())

        if !normalized.contains(date) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: date),
                  normalized.contains(yesterday) else {
                return 0
            }
            date = yesterday
        }

        while normalized.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else {
                break
            }
            date = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        let calendar = Calendar.current
        let normalized = Set(completionDates.map { calendar.startOfDay(for: $0) })
        return normalized.count
    }
}
```

