# File: `Extensions/Habit+Stats.swift`

```swift
import Foundation

extension Habit {
    func isCompleted(on date: Date) -> Bool {
        completions.contains { $0.date.isSameDay(as: date) }
    }

    func toggleCompletion(for date: Date) {
        let day = date.startOfDayLocal

        if let existing = completions.first(where: { $0.date.isSameDay(as: day) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: day, habit: self)
            completions.append(completion)
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completions.map { calendar.startOfDay(for: $0.date) })

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var cursor = calendar.startOfDay(for: Date())

        while uniqueDays.contains(cursor) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: cursor) else {
                break
            }
            cursor = previous
        }

        return streak
    }

    var totalCompletions: Int {
        Set(completions.map { $0.date.startOfDayLocal }).count
    }
}
