# 2. `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var completedToday: Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDateInToday($0) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(completionDates.map { calendar.startOfDay(for: $0) })
        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    var totalCompletions: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(completionDates.map { calendar.startOfDay(for: $0) })
        return normalizedDates.count
    }

    func toggleToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
```

