# 3. Utils/HabitStats.swift

```swift
import Foundation

struct HabitStats {
    static func completionRateThisWeek(for habit: Habit, calendar: Calendar = .current) -> Double {
        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: Date()) else {
            return 0
        }

        let completedDays = Set(
            habit.completionDates
                .filter { weekInterval.contains($0) }
                .map { calendar.startOfDay(for: $0) }
        ).count

        return Double(completedDays) / 7.0
    }
}
