import Foundation

extension Habit {
    func completion(for date: Date) -> HabitCompletion? {
        let day = date.startOfDay
        return completions.first { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }

    func completedCount(for date: Date) -> Int {
        completion(for: date)?.count ?? 0
    }

    func isCompletedToday() -> Bool {
        completedCount(for: Date()) >= targetPerDay
    }

    func incrementToday() {
        let today = Date().startOfDay
        if let existing = completion(for: today) {
            existing.count += 1
        } else {
            let newCompletion = HabitCompletion(date: today, count: 1, habit: self)
            completions.append(newCompletion)
        }
    }

    func decrementToday() {
        let today = Date().startOfDay
        guard let existing = completion(for: today) else { return }
        existing.count = max(0, existing.count - 1)
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        let sortedDays = completions
            .filter { $0.count >= targetPerDay }
            .map { $0.date.startOfDay }
            .sorted(by: >)

        guard !sortedDays.isEmpty else { return 0 }

        var streak = 0
        var cursor = Date().startOfDay

        for day in sortedDays {
            if calendar.isDate(day, inSameDayAs: cursor) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: cursor) else { break }
                cursor = previous
            } else if day < cursor {
                break
            }
        }

        return streak
    }
}
