# 2. Models

## `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date
    var targetPerDay: Int
    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        targetPerDay: Int = 1,
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.targetPerDay = max(1, targetPerDay)
        self.completions = completions
    }

    func completions(on date: Date) -> [HabitCompletion] {
        let calendar = Calendar.current
        return completions.filter { calendar.isDate($0.date, inSameDayAs: date) }
    }

    func completionCount(on date: Date) -> Int {
        completions(on: date).count
    }

    func isCompletedToday() -> Bool {
        completionCount(on: Date()) >= targetPerDay
    }

    func markCompletedToday() {
        guard completionCount(on: Date()) < targetPerDay else { return }
        let completion = HabitCompletion(date: Date(), habit: self)
        completions.append(completion)
    }

    func unmarkCompletedToday() {
        let todayCompletions = completions(on: Date())
        guard let last = todayCompletions.sorted(by: { $0.date > $1.date }).first else { return }
        if let index = completions.firstIndex(where: { $0.id == last.id }) {
            completions.remove(at: index)
        }
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        var streak = 0
        var date = calendar.startOfDay(for: Date())

        while true {
            let count = completionCount(on: date)
            if count >= targetPerDay {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else { break }
                date = previous
            } else {
                break
            }
        }

        return streak
    }
}
```

