# 8. Color Hex Helper

Add this helper because `Color.toHex()` is not built in.

## `Utilities/Color+Extensions.swift`

```swift
import SwiftUI
import UIKit

extension Color {
    func toHex() -> String? {
        let uiColor = UIColor(self)
        guard let components = uiColor.cgColor.components else { return nil }

        let r, g, b, a: CGFloat

        switch components.count {
        case 2:
            r = components[0]
            g = components[0]
            b = components[0]
            a = components[1]
        case 4:
            r = components[0]
            g = components[1]
            b = components[2]
            a = components[3]
        default:
            return nil
        }

        return String(
            format: "#%02lX%02lX%02lX%02lX",
            lroundf(Float(a * 255)),
            lroundf(Float(r * 255)),
            lroundf(Float(g * 255)),
            lroundf(Float(b * 255))
        )
    }
}
```

