@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completionDates: [Date]

    init(name: String, createdAt: Date = Date(), completionDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday() {
        let calendar = Calendar.current

        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func streakCount() -> Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while uniqueDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }
}
