```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(name: String, createdAt: Date = Date()) {
        self.name = name
        self.createdAt = createdAt
        self.completions = []
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDateInToday($0.date) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDateInToday($0.date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: Date(), habit: self)
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completedDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while completedDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else {
                break
            }
            day = previous
        }

        return streak
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date
    var habit: Habit?

    init(date: Date, habit: Habit? = nil) {
        self.id = UUID()
        self.date = date
        self.habit = habit
    }
}
