import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade) var completions: [HabitCompletion]

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.createdAt = Date()
        self.completions = []
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let completionDays = Set(completions.map { calendar.startOfDay(for: $0.date) })

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while completionDays.contains(day) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completions.contains { calendar.isDate($0.date, inSameDayAs: today) }
    }

    func toggleToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: today) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            completions.append(HabitCompletion(date: today))
        }
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date

    init(date: Date) {
        self.id = UUID()
        self.date = date
    }
}
