```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade) var completions: [HabitCompletion]

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.createdAt = Date()
        self.completions = []
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDateInToday($0.date) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDateInToday($0.date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            completions.append(HabitCompletion(date: Date()))
        }
    }

    func totalCompletions() -> Int {
        completions.count
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while uniqueDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else {
                break
            }
            day = previous
        }

        return streak
    }
}
```

