```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completionDates: [Date]

    init(name: String, createdAt: Date = Date(), completionDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current

        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func totalCompletions() -> Int {
        completionDates.count
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(day) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: day),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            day = yesterday
        }

        while uniqueDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else {
                break
            }
            day = previous
        }

        return streak
    }
}
```

