# 8. Repository

## `BankRepository.kt`
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.TransferRequest
import com.example.bankapp.data.remote.BankApi
import com.example.bankapp.data.remote.LoginRequest
import com.example.bankapp.security.SecureTokenStorage
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor(
    private val api: BankApi,
    private val tokenStorage: SecureTokenStorage
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val response = api.login(LoginRequest(username, password))
            tokenStorage.saveToken(response.token)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts() = api.getAccounts()

    suspend fun getTransactions() = api.getTransactions()

    suspend fun transfer(request: TransferRequest): Result<Unit> {
        return try {
            api.transfer(request)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        tokenStorage.clearToken()
    }
}
