package com.example.bankapp.ui.transfer

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.model.TransferRequest
import com.example.bankapp.data.repository.BankRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class TransferUiState(
    val fromAccountId: String = "",
    val toAccountNumber: String = "",
    val amount: String = "",
    val note: String = "",
    val isLoading: Boolean = false,
    val success: Boolean = false,
    val error: String? = null
)

@HiltViewModel
class TransferViewModel @Inject constructor(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState

    fun updateFromAccount(value: String) {
        _uiState.value = _uiState.value.copy(fromAccountId = value)
    }

    fun updateToAccount(value: String) {
        _uiState.value = _uiState.value.copy(toAccountNumber = value)
    }

    fun updateAmount(value: String) {
        _uiState.value = _uiState.value.copy(amount = value)
    }

    fun updateNote(value: String) {
        _uiState.value = _uiState.value.copy(note = value)
    }

    fun submitTransfer() {
        val amount = _uiState.value.amount.toDoubleOrNull()
        if (amount == null || amount <= 0.0) {
            _uiState.value = _uiState.value.copy(error = "Invalid amount")
            return
        }

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)
            val result = repository.transfer(
                TransferRequest(
                    fromAccountId = _uiState.value.fromAccountId,
                    toAccountNumber = _uiState.value.toAccountNumber,
                    amount = amount,
                    note = _uiState.value.note
                )
            )
            _uiState.value = if (result.isSuccess) {
                _uiState.value.copy(isLoading = false, success = true)
            } else {
                _uiState.value.copy(isLoading = false, error = "Transfer failed")
            }
        }
    }
}
