```kotlin
package com.example.bankapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.runtime.*
import androidx.hilt.navigation.compose.hiltViewModel
import com.example.bankapp.ui.dashboard.DashboardScreen
import com.example.bankapp.ui.dashboard.DashboardViewModel
import com.example.bankapp.ui.login.LoginScreen
import com.example.bankapp.ui.login.LoginViewModel

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            var loggedIn by remember { mutableStateOf(false) }

            if (!loggedIn) {
                val vm: LoginViewModel = hiltViewModel()
                val state by vm.uiState.collectAsState()

                LaunchedEffect(state.isLoggedIn) {
                    if (state.isLoggedIn) loggedIn = true
                }

                LoginScreen(
                    state = state,
                    onUsernameChange = vm::onUsernameChange,
                    onPasswordChange = vm::onPasswordChange,
                    onLoginClick = vm::login
                )
            } else {
                val vm: DashboardViewModel = hiltViewModel()
                val state by vm.uiState.collectAsState()

                LaunchedEffect(Unit) {
                    vm.loadData()
                }

                DashboardScreen(state = state)
            }
        }
    }
}
