## 8. Repository
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.AccountSummary
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.model.TransactionItem
import com.example.bankapp.data.remote.BankApiService
import com.example.bankapp.security.SecureTokenStorage
import javax.inject.Inject

class BankRepository @Inject constructor(
    private val api: BankApiService,
    private val tokenStorage: SecureTokenStorage
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return runCatching {
            val response = api.login(LoginRequest(username, password))
            tokenStorage.saveTokens(response.accessToken, response.refreshToken)
        }
    }

    suspend fun getAccounts(): Result<List<AccountSummary>> {
        return runCatching { api.getAccounts() }
    }

    suspend fun getTransactions(accountId: String): Result<List<TransactionItem>> {
        return runCatching { api.getTransactions(accountId) }
    }

    fun logout() {
        tokenStorage.clear()
    }
}
