# 7. Repository

```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.remote.BankApiService
import com.example.bankapp.data.remote.LoginRequest
import com.example.bankapp.domain.model.Account
import com.example.bankapp.domain.model.Transaction
import com.example.bankapp.security.SecureStorage
import javax.inject.Inject

class BankRepository @Inject constructor(
    private val api: BankApiService,
    private val secureStorage: SecureStorage
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val response = api.login(LoginRequest(username, password))
            secureStorage.saveToken(response.token)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            Result.success(api.getAccounts())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(accountId: String): Result<List<Transaction>> {
        return try {
            Result.success(api.getTransactions(accountId))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        secureStorage.clearToken()
    }
}
