```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.api.BankApi
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.security.SecureStorage
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor(
    private val api: BankApi,
    private val secureStorage: SecureStorage
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val response = api.login(LoginRequest(username, password))
            secureStorage.saveTokens(response.accessToken, response.refreshToken)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            Result.success(api.getAccounts())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(accountId: String): Result<List<Transaction>> {
        return try {
            Result.success(api.getTransactions(accountId))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        secureStorage.clear()
    }
}
