import com.example.bankapp.ui.accounts.AccountsViewModel
import com.example.bankapp.ui.login.LoginScreen
import com.example.bankapp.ui.login.LoginViewModel
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        setContent {
            val navController = rememberNavController()

            NavHost(navController = navController, startDestination = "login") {
                composable("login") {
                    val vm: LoginViewModel = hiltViewModel()
                    val state by vm.uiState.collectAsState()

                    if (state.isLoggedIn) {
                        navController.navigate("accounts") {
                            popUpTo("login") { inclusive = true }
                        }
                    }

                    LoginScreen(
                        uiState = state,
                        onUsernameChange = vm::onUsernameChange,
                        onPasswordChange = vm::onPasswordChange,
                        onLoginClick = vm::login
                    )
                }

                composable("accounts") {
                    val vm: AccountsViewModel = hiltViewModel()
                    val state by vm.uiState.collectAsState()

                    androidx.compose.runtime.LaunchedEffect(Unit) {
                        vm.loadAccounts()
                    }

                    AccountsScreen(
                        uiState = state,
                        onAccountClick = { account ->
                            navController.navigate("transactions/${account.id}")
                        }
                    )
                }
            }
        }
    }
}
