                val transactions = repository.getTransactions()
                uiState = DashboardUiState(
                    accounts = accounts,
                    transactions = transactions
                )
            } catch (e: Exception) {
                uiState = DashboardUiState(error = e.message ?: "Failed to load dashboard")
            }
        }
