```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.repository.BankingRepository
import kotlinx.coroutines.launch

data class TransferUiState(
    val isLoading: Boolean = false,
    val successMessage: String? = null,
    val error: String? = null
)

class TransferViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    var uiState by mutableStateOf(TransferUiState())
        private set

    fun transfer(toAccount: String, amountText: String) {
        val amount = amountText.toDoubleOrNull()
        if (amount == null) {
            uiState = TransferUiState(error = "Enter a valid amount")
            return
        }

        uiState = uiState.copy(isLoading = true, error = null, successMessage = null)

        viewModelScope.launch {
            val result = repository.transfer(toAccount, amount)
            uiState = result.fold(
                onSuccess = {
                    TransferUiState(successMessage = "Transfer completed successfully")
                },
                onFailure = { error ->
                    TransferUiState(error = error.message ?: "Transfer failed")
                }
            )
        }
    }
}
