# Important note: current issue in this starter

Right now, each ViewModel creates its own `BankingRepository()` instance:

```kotlin
private val repository: BankingRepository = BankingRepository()
```

That means login state is **not actually shared** across screens. For example, transfer may fail with `"User not authenticated"` even after login.

## Quick fix

Use a shared singleton repository for this starter.

### Replace `BankingRepository.kt` with:

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.User
import kotlinx.coroutines.delay

object BankingRepository {

    private var loggedIn = false

    suspend fun login(username: String, password: String): Result<User> {
        delay(800)
        return if (username == "demo" && password == "password") {
            loggedIn = true
            Result.success(
                User(
                    id = "u1",
                    fullName = "Alex Johnson",
                    email = "alex@example.com"
                )
            )
        } else {
            Result.failure(Exception("Invalid username or password"))
        }
    }

    fun isLoggedIn(): Boolean = loggedIn

    suspend fun getAccounts(): List<Account> {
        delay(500)
        return listOf(
            Account("a1", "Checking Account", "**** 1234", 5240.75, "USD"),
            Account("a2", "Savings Account", "**** 9876", 12890.10, "USD")
        )
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(500)
        return listOf(
            Transaction("t1", "Coffee Shop", "2026-09-10", 5.75, "USD", false),
            Transaction("t2", "Payroll", "2026-09-09", 2500.00, "USD", true),
            Transaction("t3", "Electric Bill", "2026-09-08", 120.40, "USD", false),
            Transaction("t4", "Grocery Store", "2026-09-07", 84.22, "USD", false)
        )
    }

    suspend fun transfer(toAccount: String, amount: Double): Result<Unit> {
        delay(1000)
        return when {
            !loggedIn -> Result.failure(Exception("User not authenticated"))
            toAccount.isBlank() -> Result.failure(Exception("Destination account is required"))
            amount <= 0 -> Result.failure(Exception("Amount must be greater than zero"))
            else -> Result.success(Unit)
        }
    }
}
```

Then update ViewModels to use:

```kotlin
private val repository: BankingRepository = BankingRepository
```

