# 7. Navigation

## `ui/navigation/AppNavGraph.kt`

```kotlin
package com.example.bankapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankapp.data.repository.BankRepository
import com.example.bankapp.ui.screen.DashboardScreen
import com.example.bankapp.ui.screen.LoginScreen
import com.example.bankapp.ui.screen.TransferScreen
import com.example.bankapp.ui.viewmodel.AuthViewModel
import com.example.bankapp.ui.viewmodel.BankViewModel
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider

sealed class Screen(val route: String) {
    data object Login : Screen("login")
    data object Dashboard : Screen("dashboard")
    data object Transfer : Screen("transfer")
}

@Composable
fun AppNavGraph(
    repository: BankRepository,
    navController: NavHostController = rememberNavController()
) {
    val authViewModel: AuthViewModel = viewModel(
        factory = simpleFactory { AuthViewModel(repository) }
    )
    val bankViewModel: BankViewModel = viewModel(
        factory = simpleFactory { BankViewModel(repository) }
    )

    NavHost(
        navController = navController,
        startDestination = if (authViewModel.user == null) Screen.Login.route else Screen.Dashboard.route
    ) {
        composable(Screen.Login.route) {
            LoginScreen(
                authViewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(Screen.Dashboard.route) {
                        popUpTo(Screen.Login.route) { inclusive = true }
                    }
                }
            )
        }

        composable(Screen.Dashboard.route) {
            DashboardScreen(
                authViewModel = authViewModel,
                bankViewModel = bankViewModel,
                onTransferClick = {
                    navController.navigate(Screen.Transfer.route)
                },
                onLogout = {
                    authViewModel.logout()
                    navController.navigate(Screen.Login.route) {
                        popUpTo(0)
                    }
                }
            )
        }

        composable(Screen.Transfer.route) {
            TransferScreen(
                bankViewModel = bankViewModel,
                onBack = { navController.popBackStack() }
            )
        }
    }
}

fun <T : ViewModel> simpleFactory(create: () -> T): ViewModelProvider.Factory {
    return object : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <VM : ViewModel> create(modelClass: Class<VM>): VM {
            return create() as VM
        }
    }
}
