## Important note about this initial implementation

There is one architectural issue in the code above:

- `AuthViewModel` and `BankViewModel` each create their own `BankRepository()`
- that means they do not share the same app state instance

For a real app, you should use:
- dependency injection with Hilt, or
- a shared singleton repository, or
- a custom `ViewModelProvider.Factory`

For a quick initial fix, you can make the repository a singleton.

---

## Quick singleton fix

Replace `BankRepository.kt` with:

```kotlin
package com.example.bankapp.data

import com.example.bankapp.model.Transaction
import com.example.bankapp.model.TransactionType
import com.example.bankapp.model.UserAccount
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

object BankRepository {

    private val _account = MutableStateFlow(
        UserAccount(
            accountName = "John Doe",
            accountNumber = "1234567890",
            balance = 5250.75
        )
    )
    val account: StateFlow<UserAccount> = _account.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction(UUID.randomUUID().toString(), "Salary", 3000.00, "2026-09-01", TransactionType.CREDIT),
            Transaction(UUID.randomUUID().toString(), "Groceries", 120.45, "2026-09-03", TransactionType.DEBIT),
            Transaction(UUID.randomUUID().toString(), "Electric Bill", 89.99, "2026-09-05", TransactionType.DEBIT),
            Transaction(UUID.randomUUID().toString(), "Coffee", 5.75, "2026-09-06", TransactionType.DEBIT)
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun transfer(recipient: String, amount: Double): Result<Unit> {
        val current = _account.value
        return when {
            recipient.isBlank() -> Result.failure(IllegalArgumentException("Recipient is required"))
            amount <= 0 -> Result.failure(IllegalArgumentException("Amount must be greater than zero"))
            amount > current.balance -> Result.failure(IllegalArgumentException("Insufficient funds"))
            else -> {
                _account.value = current.copy(balance = current.balance - amount)
                _transactions.value = listOf(
                    Transaction(
                        id = UUID.randomUUID().toString(),
                        title = "Transfer to $recipient",
                        amount = amount,
                        date = "2026-09-16",
                        type = TransactionType.DEBIT
                    )
                ) + _transactions.value
                Result.success(Unit)
            }
        }
    }
}
```

