                            Text(transaction.title, style = MaterialTheme.typography.titleMedium)
                            Text(transaction.date)
                        }

                        Text(
                            text = formatSignedAmount(transaction.amount),
                            color = if (transaction.type == TransactionType.CREDIT) Color(0xFF2E7D32) else MaterialTheme.colorScheme.error
                        )
                    }
                }
            }
        }

        item {
            HorizontalDivider()
        }
    }
}

private fun formatCurrency(amount: Double, currency: String): String {
    val formatter = NumberFormat.getCurrencyInstance(Locale.US)
    return formatter.format(amount).replace("$", "$currency ")
}

private fun formatSignedAmount(amount: Double): String {
    return if (amount > 0) "+$%.2f".format(amount) else "-$%.2f".format(kotlin.math.abs(amount))
}
