```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.User
import com.example.bankingapp.data.repository.AuthRepository

data class AuthUiState(
    val isLoading: Boolean = false,
    val user: User? = null,
    val error: String? = null
)

class AuthViewModel(
    private val authRepository: AuthRepository = AuthRepository()
) : ViewModel() {

    var uiState by mutableStateOf(AuthUiState())
        private set

    fun login(username: String, password: String) {
        uiState = uiState.copy(isLoading = true, error = null)

        val result = authRepository.login(username, password)

        uiState = result.fold(
            onSuccess = { user ->
                uiState.copy(isLoading = false, user = user, error = null)
            },
            onFailure = { throwable ->
                uiState.copy(isLoading = false, user = null, error = throwable.message)
            }
        )
    }

    fun logout() {
        uiState = AuthUiState()
    }
}
