```kotlin
package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.bankingapp.ui.screen.AccountsScreen
import com.example.bankingapp.ui.screen.LoginScreen
import com.example.bankingapp.ui.screen.TransactionsScreen
import com.example.bankingapp.ui.viewmodel.AccountsViewModel
import com.example.bankingapp.ui.viewmodel.AuthViewModel

object Routes {
    const val LOGIN = "login"
    const val ACCOUNTS = "accounts"
    const val TRANSACTIONS = "transactions"
}

@Composable
fun AppNavGraph() {
    val navController = rememberNavController()
    val authViewModel: AuthViewModel = viewModel()
    val accountsViewModel: AccountsViewModel = viewModel()

    NavHost(
        navController = navController,
        startDestination = Routes.LOGIN
    ) {
        composable(Routes.LOGIN) {
            LoginScreen(
                uiState = authViewModel.uiState,
                onLogin = { username, password ->
                    authViewModel.login(username, password)
                }
            )

            LaunchedEffect(authViewModel.uiState.user) {
                if (authViewModel.uiState.user != null) {
                    navController.navigate(Routes.ACCOUNTS) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            }
        }

        composable(Routes.ACCOUNTS) {
            LaunchedEffect(Unit) {
                accountsViewModel.loadAccounts()
            }

            AccountsScreen(
                uiState = accountsViewModel.uiState,
                onAccountClick = { accountId ->
                    navController.navigate("${Routes.TRANSACTIONS}/$accountId")
                },
                onLogout = {
                    authViewModel.logout()
                    navController.navigate(Routes.LOGIN) {
                        popUpTo(0)
                    }
                }
            )
        }

        composable(
            route = "${Routes.TRANSACTIONS}/{accountId}",
            arguments = listOf(navArgument("accountId") { type = NavType.StringType })
        ) { backStackEntry ->
            val accountId = backStackEntry.arguments?.getString("accountId").orEmpty()

            LaunchedEffect(accountId) {
                accountsViewModel.loadTransactions(accountId)
            }

            TransactionsScreen(
                transactions = accountsViewModel.uiState.transactions,
                onBack = { navController.popBackStack() }
            )
        }
    }
}
