        composable(Routes.DASHBOARD) {
            val vm: DashboardViewModel = viewModel(
                factory = DashboardViewModel.factory(bankRepository)
            )
            DashboardScreen(
                viewModel = vm,
                onViewTransactions = {
                    navController.navigate(Routes.TRANSACTIONS)
                }
            )
        }

        composable(Routes.TRANSACTIONS) {
            TransactionsScreen(bankRepository = bankRepository)
        }
    }
}
