package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User

class BankingRepository {

    fun login(username: String, password: String): Result<User> {
        return if (username == "user" && password == "password") {
            Result.success(User(username = username, fullName = "John Doe"))
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    fun getAccounts(): List<Account> {
        return listOf(
            Account(
                id = "1",
                accountName = "Checking Account",
                accountNumber = "****1234",
                balance = 2450.75,
                currency = "USD"
            ),
            Account(
                id = "2",
                accountName = "Savings Account",
                accountNumber = "****5678",
                balance = 10250.00,
                currency = "USD"
            )
        )
    }

    fun getTransactions(): List<Transaction> {
        return listOf(
            Transaction("1", "Coffee Shop", "2026-09-10", -5.75, TransactionType.DEBIT),
            Transaction("2", "Salary", "2026-09-09", 2500.00, TransactionType.CREDIT),
            Transaction("3", "Electric Bill", "2026-09-08", -120.40, TransactionType.DEBIT),
            Transaction("4", "Transfer In", "2026-09-07", 300.00, TransactionType.CREDIT)
        )
    }

    fun transfer(amount: Double, recipient: String): Result<String> {
        return if (amount > 0 && recipient.isNotBlank()) {
            Result.success("Transfer of $$amount to $recipient completed")
        } else {
            Result.failure(Exception("Invalid transfer details"))
        }
    }
}
