# 5. ViewModels

## `AuthViewModel.kt`

```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.User
import com.example.bankingapp.data.repository.BankingRepository

class AuthViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    var username by mutableStateOf("")
    var password by mutableStateOf("")
    var currentUser by mutableStateOf<User?>(null)
        private set
    var errorMessage by mutableStateOf<String?>(null)
        private set

    fun login(onSuccess: () -> Unit) {
        val result = repository.login(username, password)
        result.onSuccess {
            currentUser = it
            errorMessage = null
            onSuccess()
        }.onFailure {
            errorMessage = it.message
        }
    }

    fun logout() {
        currentUser = null
        username = ""
        password = ""
    }
}
```

## `BankingViewModel.kt`

```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.repository.BankingRepository

class BankingViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    var accounts by mutableStateOf<List<Account>>(emptyList())
        private set

    var transactions by mutableStateOf<List<Transaction>>(emptyList())
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    init {
        loadDashboard()
    }

    fun loadDashboard() {
        accounts = repository.getAccounts()
        transactions = repository.getTransactions()
    }

    fun makeTransfer(amount: String, recipient: String) {
        val parsedAmount = amount.toDoubleOrNull()
        if (parsedAmount == null) {
            transferMessage = "Invalid amount"
            return
        }

        val result = repository.transfer(parsedAmount, recipient)
        result.onSuccess {
            transferMessage = it
            loadDashboard()
        }.onFailure {
            transferMessage = it.message
        }
    }
}
```

