# 5. `data/BankRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.User
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

class BankRepository {

    private val _currentUser = MutableStateFlow<User?>(null)
    val currentUser: StateFlow<User?> = _currentUser.asStateFlow()

    private val _accounts = MutableStateFlow(
        listOf(
            Account("1", "Checking", "****1234", 2450.75),
            Account("2", "Savings", "****5678", 10200.00)
        )
    )
    val accounts: StateFlow<List<Account>> = _accounts.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction("1", "1", "Coffee Shop", 5.75, "2026-09-10", false),
            Transaction("2", "1", "Payroll", 1500.00, "2026-09-09", true),
            Transaction("3", "2", "Interest", 12.50, "2026-09-08", true),
            Transaction("4", "1", "Groceries", 82.30, "2026-09-07", false)
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(email: String, password: String): Boolean {
        return if (email.isNotBlank() && password.isNotBlank()) {
            _currentUser.value = User("u1", "Alex Johnson", email)
            true
        } else {
            false
        }
    }

    fun logout() {
        _currentUser.value = null
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        if (fromAccountId == toAccountId) {
            return Result.failure(IllegalArgumentException("Accounts must be different"))
        }
        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        val accounts = _accounts.value
        val from = accounts.find { it.id == fromAccountId }
        val to = accounts.find { it.id == toAccountId }

        if (from == null || to == null) {
            return Result.failure(IllegalArgumentException("Invalid account selection"))
        }

        if (from.balance < amount) {
            return Result.failure(IllegalStateException("Insufficient funds"))
        }

        _accounts.update { current ->
            current.map {
                when (it.id) {
                    fromAccountId -> it.copy(balance = it.balance - amount)
                    toAccountId -> it.copy(balance = it.balance + amount)
                    else -> it
                }
            }
        }

        val newTransactions = listOf(
            Transaction(
                id = System.currentTimeMillis().toString() + "_debit",
                accountId = fromAccountId,
                title = "Transfer to ${to.number}",
                amount = amount,
                date = "2026-09-16",
                isCredit = false
            ),
            Transaction(
                id = System.currentTimeMillis().toString() + "_credit",
                accountId = toAccountId,
                title = "Transfer from ${from.number}",
                amount = amount,
                date = "2026-09-16",
                isCredit = true
            )
        )

        _transactions.update { current -> newTransactions + current }

        return Result.success(Unit)
    }
}
