    }

    fun logout() {
        repository.logout()
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        return repository.transfer(fromAccountId, toAccountId, amount)
    }

    fun getTransactionsForAccount(accountId: String): List<Transaction> {
        return transactions.value.filter { it.accountId == accountId }
    }

    fun getTotalBalance(): Double {
        return accounts.value.sumOf { it.balance }
    }
