@Composable
fun TransferScreen(
    viewModel: BankViewModel
) {
    val accounts by viewModel.accounts.collectAsState()

    var fromAccountId by remember { mutableStateOf(accounts.firstOrNull()?.id.orEmpty()) }
    var toAccountId by remember { mutableStateOf(accounts.getOrNull(1)?.id.orEmpty()) }
    var amount by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Text("Transfer Money", style = MaterialTheme.typography.headlineSmall)

        OutlinedTextField(
            value = fromAccountId,
            onValueChange = { fromAccountId = it },
            label = { Text("From Account ID") },
            modifier = Modifier.fillMaxWidth()
        )

        OutlinedTextField(
            value = toAccountId,
            onValueChange = { toAccountId = it },
            label = { Text("To Account ID") },
            modifier = Modifier.fillMaxWidth()
        )

        OutlinedTextField(
            value = amount,
            onValueChange = { amount = it },
            label = { Text("Amount") },
            modifier = Modifier.fillMaxWidth()
        )

        Button(
            onClick = {
                val amountValue = amount.toDoubleOrNull()
                if (amountValue == null) {
                    message = "Enter a valid amount"
                } else {
                    val result = viewModel.transfer(fromAccountId, toAccountId, amountValue)
                    message = result.exceptionOrNull()?.message ?: "Transfer successful"
                }
            },
            modifier = Modifier.fillMaxWidth()
        ) {
            Text("Submit Transfer")
        }

        if (message.isNotBlank()) {
            Text(
                text = message,
                color = if (message == "Transfer successful") {
                    MaterialTheme.colorScheme.primary
                } else {
                    MaterialTheme.colorScheme.error
                }
            )
        }
    }
