package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.model.TransactionType
import kotlinx.coroutines.delay
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor() {

    suspend fun login(username: String, password: String): Result<Boolean> {
        delay(1000)
        return if (username == "user" && password == "password") {
            Result.success(true)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    suspend fun getAccounts(): List<Account> {
        delay(500)
        return listOf(
            Account(
                id = "1",
                name = "Checking Account",
                accountNumberMasked = "****1234",
                balance = 2450.75,
                currency = "USD"
            ),
            Account(
                id = "2",
                name = "Savings Account",
                accountNumberMasked = "****5678",
                balance = 10200.00,
                currency = "USD"
            )
        )
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(500)
        return listOf(
            Transaction("1", "Coffee Shop", "2026-09-10", -5.75, TransactionType.DEBIT),
            Transaction("2", "Salary", "2026-09-09", 2500.00, TransactionType.CREDIT),
            Transaction("3", "Electric Bill", "2026-09-08", -120.40, TransactionType.DEBIT)
        )
    }

    suspend fun transfer(toAccount: String, amount: Double): Result<Boolean> {
        delay(1000)
        return if (toAccount.isNotBlank() && amount > 0) {
            Result.success(true)
        } else {
            Result.failure(Exception("Invalid transfer details"))
        }
    }
}
