package com.example.bankapp.ui.transfer

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.repository.BankRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class TransferUiState(
    val toAccount: String = "",
    val amount: String = "",
    val isLoading: Boolean = false,
    val successMessage: String? = null,
    val error: String? = null
)

@HiltViewModel
class TransferViewModel @Inject constructor(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState.asStateFlow()

    fun onToAccountChange(value: String) {
        _uiState.value = _uiState.value.copy(toAccount = value)
    }

    fun onAmountChange(value: String) {
        _uiState.value = _uiState.value.copy(amount = value)
    }

    fun submitTransfer() {
        viewModelScope.launch {
            val amountValue = _uiState.value.amount.toDoubleOrNull()
            if (amountValue == null) {
                _uiState.value = _uiState.value.copy(error = "Invalid amount")
                return@launch
            }

            _uiState.value = _uiState.value.copy(isLoading = true, error = null, successMessage = null)
            val result = repository.transfer(_uiState.value.toAccount, amountValue)

            _uiState.value = if (result.isSuccess) {
                _uiState.value.copy(
                    isLoading = false,
                    successMessage = "Transfer completed successfully",
                    toAccount = "",
                    amount = ""
                )
            } else {
                _uiState.value.copy(
                    isLoading = false,
                    error = result.exceptionOrNull()?.message
                )
            }
        }
    }
}
