import com.example.bankapp.ui.transactions.TransactionsViewModel
import com.example.bankapp.ui.transfer.TransferScreen
import com.example.bankapp.ui.transfer.TransferViewModel

@Composable
fun BankNavGraph() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = Routes.LOGIN
    ) {
        composable(Routes.LOGIN) {
            val viewModel: LoginViewModel = hiltViewModel()
            LoginScreen(
                viewModel = viewModel,
                onLoginSuccess = {
                    navController.navigate(Routes.ACCOUNTS) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.ACCOUNTS) {
            val viewModel: AccountsViewModel = hiltViewModel()
            AccountsScreen(
                viewModel = viewModel,
                onViewTransactions = { navController.navigate(Routes.TRANSACTIONS) },
                onTransfer = { navController.navigate(Routes.TRANSFER) }
            )
        }

        composable(Routes.TRANSACTIONS) {
            val viewModel: TransactionsViewModel = hiltViewModel()
            TransactionsScreen(viewModel = viewModel)
        }

        composable(Routes.TRANSFER) {
            val viewModel: TransferViewModel = hiltViewModel()
            TransferScreen(viewModel = viewModel)
        }
    }
}
