## `data/local/BankDao.kt`

```kotlin
package com.example.bankapp.data.local

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface BankDao {

    @Query("SELECT * FROM accounts")
    fun getAccounts(): Flow<List<AccountEntity>>

    @Query("SELECT * FROM transactions WHERE accountId = :accountId ORDER BY date DESC")
    fun getTransactionsForAccount(accountId: Long): Flow<List<TransactionEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertAccounts(accounts: List<AccountEntity>)

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertTransactions(transactions: List<TransactionEntity>)

    @Query("UPDATE accounts SET balance = balance - :amount WHERE id = :fromAccountId")
    suspend fun debitAccount(fromAccountId: Long, amount: Double)

    @Query("UPDATE accounts SET balance = balance + :amount WHERE id = :toAccountId")
    suspend fun creditAccount(toAccountId: Long, amount: Double)
}
