# 6. Repository

## `data/repository/BankRepository.kt`

```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.local.BankDao
import com.example.bankapp.data.local.AccountEntity
import com.example.bankapp.data.local.TransactionEntity
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor(
    private val dao: BankDao
) {
    fun getAccounts(): Flow<List<Account>> {
        return dao.getAccounts().map { entities ->
            entities.map {
                Account(
                    id = it.id,
                    name = it.name,
                    numberMasked = it.numberMasked,
                    balance = it.balance,
                    currency = it.currency
                )
            }
        }
    }

    fun getTransactions(accountId: Long): Flow<List<Transaction>> {
        return dao.getTransactionsForAccount(accountId).map { entities ->
            entities.map {
                Transaction(
                    id = it.id,
                    accountId = it.accountId,
                    title = it.title,
                    amount = it.amount,
                    date = it.date,
                    type = it.type
                )
            }
        }
    }

    suspend fun seedData() {
        dao.insertAccounts(
            listOf(
                AccountEntity(1, "Checking Account", "****1234", 2450.75, "USD"),
                AccountEntity(2, "Savings Account", "****5678", 10200.00, "USD")
            )
        )

        dao.insertTransactions(
            listOf(
                TransactionEntity(1, 1, "Coffee Shop", -5.75, "2026-09-01", "debit"),
                TransactionEntity(2, 1, "Salary", 2500.00, "2026-09-01", "credit"),
                TransactionEntity(3, 2, "Interest", 15.00, "2026-09-02", "credit")
            )
        )
    }

    suspend fun transferFunds(fromAccountId: Long, toAccountId: Long, amount: Double) {
        dao.debitAccount(fromAccountId, amount)
        dao.creditAccount(toAccountId, amount)

        val timestamp = System.currentTimeMillis()
        dao.insertTransactions(
            listOf(
                TransactionEntity(
                    id = timestamp,
                    accountId = fromAccountId,
                    title = "Transfer to account $toAccountId",
                    amount = -amount,
                    date = timestamp.toString(),
                    type = "debit"
                ),
                TransactionEntity(
                    id = timestamp + 1,
                    accountId = toAccountId,
                    title = "Transfer from account $fromAccountId",
                    amount = amount,
                    date = timestamp.toString(),
                    type = "credit"
                )
            )
        )
    }
}
```

