# 4. Repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlin.math.absoluteValue

class BankingRepository {

    private val fakeUser = User(
        id = "1",
        name = "Alex Johnson",
        username = "alex"
    )

    private val _account = MutableStateFlow(
        Account(
            id = "acc_1",
            accountName = "Checking Account",
            accountNumberMasked = "****1234",
            balance = 2450.75
        )
    )
    val account: StateFlow<Account> = _account.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction("t1", "Salary", "2026-09-01", 3200.00, TransactionType.CREDIT),
            Transaction("t2", "Grocery Store", "2026-09-03", -85.40, TransactionType.DEBIT),
            Transaction("t3", "Electric Bill", "2026-09-05", -120.00, TransactionType.DEBIT),
            Transaction("t4", "Coffee Shop", "2026-09-06", -6.75, TransactionType.DEBIT)
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): User? {
        return if (username == "alex" && password == "password123") {
            fakeUser
        } else {
            null
        }
    }

    fun transfer(toAccount: String, amount: Double): Result<Unit> {
        val current = _account.value

        if (toAccount.isBlank()) {
            return Result.failure(IllegalArgumentException("Recipient account is required"))
        }

        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        if (current.balance < amount) {
            return Result.failure(IllegalStateException("Insufficient funds"))
        }

        _account.value = current.copy(balance = current.balance - amount)

        val newTransaction = Transaction(
            id = "t${System.currentTimeMillis()}",
            title = "Transfer to $toAccount",
            date = "2026-09-16",
            amount = -amount.absoluteValue,
            type = TransactionType.DEBIT
        )

        _transactions.value = listOf(newTransaction) + _transactions.value

        return Result.success(Unit)
    }
}
```

