## `data/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.User
import kotlinx.coroutines.delay

class BankingRepository {

    private val demoUser = User(
        id = "u1",
        fullName = "Alex Johnson",
        email = "alex@example.com"
    )

    private val accounts = mutableListOf(
        Account(
            id = "a1",
            name = "Everyday Checking",
            type = "Checking",
            balance = 2450.75,
            accountNumberMasked = "**** 1024"
        ),
        Account(
            id = "a2",
            name = "Savings Plus",
            type = "Savings",
            balance = 10200.00,
            accountNumberMasked = "**** 7788"
        )
    )

    private val transactions = mutableListOf(
        Transaction("t1", "a1", "Coffee Shop", -5.75, "2026-09-10", "Food"),
        Transaction("t2", "a1", "Payroll Deposit", 1800.00, "2026-09-09", "Income"),
        Transaction("t3", "a1", "Electric Bill", -120.40, "2026-09-08", "Utilities"),
        Transaction("t4", "a2", "Interest Payment", 12.15, "2026-09-01", "Interest")
    )

    suspend fun login(username: String, password: String): Result<User> {
        delay(800)
        return if (username == "demo" && password == "password") {
            Result.success(demoUser)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    suspend fun getAccounts(): List<Account> {
        delay(300)
        return accounts.toList()
    }

    suspend fun getTransactions(accountId: String? = null): List<Transaction> {
        delay(300)
        return if (accountId == null) {
            transactions.toList()
        } else {
            transactions.filter { it.accountId == accountId }
        }
    }

    suspend fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        delay(500)

        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        val fromIndex = accounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = accounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) {
            return Result.failure(Exception("Invalid account selection"))
        }

        val from = accounts[fromIndex]
        val to = accounts[toIndex]

        if (from.balance < amount) {
            return Result.failure(Exception("Insufficient funds"))
        }

        accounts[fromIndex] = from.copy(balance = from.balance - amount)
        accounts[toIndex] = to.copy(balance = to.balance + amount)

        transactions.add(
            0,
            Transaction(
                id = "t${transactions.size + 1}",
                accountId = from.id,
                title = "Transfer to ${to.name}",
                amount = -amount,
                date = "2026-09-16",
                category = "Transfer"
            )
        )

        transactions.add(
            0,
            Transaction(
                id = "t${transactions.size + 1}",
                accountId = to.id,
                title = "Transfer from ${from.name}",
                amount = amount,
                date = "2026-09-16",
                category = "Transfer"
            )
        )

        return Result.success(Unit)
    }
}
