## `ui/viewmodel/BankingViewModel.kt`

```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.BankingRepository
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class BankingUiState(
    val isLoading: Boolean = false,
    val accounts: List<Account> = emptyList(),
    val transactions: List<Transaction> = emptyList(),
    val selectedAccountId: String? = null,
    val transferMessage: String? = null,
    val error: String? = null
)

class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(BankingUiState())
    val uiState: StateFlow<BankingUiState> = _uiState.asStateFlow()

    init {
        refreshData()
    }

    fun refreshData() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)

            val accounts = repository.getAccounts()
            val transactions = repository.getTransactions()

            _uiState.value = _uiState.value.copy(
                isLoading = false,
                accounts = accounts,
                transactions = transactions
            )
        }
    }

    fun selectAccount(accountId: String?) {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(
                isLoading = true,
                selectedAccountId = accountId,
                error = null
            )

            val transactions = repository.getTransactions(accountId)

            _uiState.value = _uiState.value.copy(
                isLoading = false,
                transactions = transactions
            )
        }
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double) {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(
                isLoading = true,
                transferMessage = null,
                error = null
            )

            val result = repository.transfer(fromAccountId, toAccountId, amount)

            if (result.isSuccess) {
                val accounts = repository.getAccounts()
                val transactions = repository.getTransactions()

                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    accounts = accounts,
                    transactions = transactions,
                    transferMessage = "Transfer completed successfully"
                )
            } else {
                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    error = result.exceptionOrNull()?.message ?: "Transfer failed"
                )
            }
        }
    }

    fun clearMessage() {
        _uiState.value = _uiState.value.copy(
            transferMessage = null,
            error = null
        )
    }
}
