# 6. Simple ViewModel factory support

## `BankingApp.kt`

```kotlin
package com.example.bankingapp

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.bankingapp.data.BankingRepository
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.BankingViewModel

class AppContainer {
    val repository = BankingRepository()
}

@Composable
fun rememberAppContainer(): AppContainer = remember { AppContainer() }

class BankingViewModelFactory(
    private val container: AppContainer
) : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        return when {
            modelClass.isAssignableFrom(AuthViewModel::class.java) ->
                AuthViewModel(container.repository) as T
            modelClass.isAssignableFrom(BankingViewModel::class.java) ->
                BankingViewModel(container.repository) as T
            else -> throw IllegalArgumentException("Unknown ViewModel class")
        }
    }
}

@Composable
inline fun <reified T : ViewModel> appViewModel(container: AppContainer): T {
    return viewModel(factory = BankingViewModelFactory(container))
}
