package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.AppContainer
import com.example.bankingapp.appViewModel
import com.example.bankingapp.ui.screen.AccountsScreen
import com.example.bankingapp.ui.screen.DashboardScreen
import com.example.bankingapp.ui.screen.LoginScreen
import com.example.bankingapp.ui.screen.TransactionsScreen
import com.example.bankingapp.ui.screen.TransferScreen
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.BankingViewModel

object Routes {
    const val LOGIN = "login"
    const val DASHBOARD = "dashboard"
    const val ACCOUNTS = "accounts"
    const val TRANSACTIONS = "transactions"
    const val TRANSFER = "transfer"
}

@Composable
fun AppNavGraph(
    container: AppContainer,
    navController: NavHostController = rememberNavController()
) {
    val authViewModel: AuthViewModel = appViewModel(container)
    val bankingViewModel: BankingViewModel = appViewModel(container)

    val authState by authViewModel.uiState.collectAsStateWithLifecycle()
    val bankingState by bankingViewModel.uiState.collectAsStateWithLifecycle()

    NavHost(
        navController = navController,
        startDestination = if (authState.isLoggedIn) Routes.DASHBOARD else Routes.LOGIN
    ) {
        composable(Routes.LOGIN) {
            LoginScreen(
                state = authState,
                onLogin = { username, password ->
                    authViewModel.login(username, password)
                },
                onLoginSuccess = {
                    navController.navigate(Routes.DASHBOARD) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.DASHBOARD) {
            DashboardScreen(
                authState = authState,
                bankingState = bankingState,
                onAccountsClick = { navController.navigate(Routes.ACCOUNTS) },
                onTransactionsClick = { navController.navigate(Routes.TRANSACTIONS) },
                onTransferClick = { navController.navigate(Routes.TRANSFER) },
                onLogout = {
                    authViewModel.logout()
                    navController.navigate(Routes.LOGIN) {
                        popUpTo(0)
                    }
                }
            )
        }

        composable(Routes.ACCOUNTS) {
            AccountsScreen(
                state = bankingState,
                onBack = { navController.popBackStack() }
            )
        }

        composable(Routes.TRANSACTIONS) {
            TransactionsScreen(
                state = bankingState,
                onSelectAccount = bankingViewModel::selectAccount,
                onBack = { navController.popBackStack() }
            )
        }

        composable(Routes.TRANSFER) {
            TransferScreen(
                state = bankingState,
                onTransfer = bankingViewModel::transfer,
                onDismissMessage = bankingViewModel::clearMessage,
                onBack = { navController.popBackStack() }
            )
        }
    }
}
