# 5. Repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.local.AccountDao
import com.example.bankingapp.data.local.AccountEntity
import com.example.bankingapp.data.local.TransactionDao
import com.example.bankingapp.data.local.TransactionEntity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch

class BankingRepository(
    private val accountDao: AccountDao,
    private val transactionDao: TransactionDao
) {
    fun getAccounts() = accountDao.getAccounts().map { entities ->
        entities.map {
            com.example.bankingapp.data.model.Account(
                id = it.id,
                name = it.name,
                number = it.number,
                balance = it.balance
            )
        }
    }

    fun getTransactions(accountId: Int) = transactionDao.getTransactionsForAccount(accountId).map { entities ->
        entities.map {
            com.example.bankingapp.data.model.Transaction(
                id = it.id,
                accountId = it.accountId,
                title = it.title,
                amount = it.amount,
                timestamp = it.timestamp,
                type = it.type
            )
        }
    }

    suspend fun transfer(fromAccountId: Int, toAccountNumber: String, amount: Double): Result<Unit> {
        val from = accountDao.getAccountById(fromAccountId) ?: return Result.failure(Exception("Source account not found"))

        if (amount <= 0) return Result.failure(Exception("Amount must be greater than zero"))
        if (from.balance < amount) return Result.failure(Exception("Insufficient funds"))

        val newBalance = from.balance - amount
        accountDao.updateBalance(fromAccountId, newBalance)

        transactionDao.insert(
            TransactionEntity(
                accountId = fromAccountId,
                title = "Transfer to $toAccountNumber",
                amount = -amount,
                timestamp = System.currentTimeMillis(),
                type = "DEBIT"
            )
        )

        return Result.success(Unit)
    }

    fun seedData() {
        CoroutineScope(Dispatchers.IO).launch {
            if (accountDao.count() == 0) {
                accountDao.insertAll(
                    listOf(
                        AccountEntity(1, "Checking Account", "****1234", 2450.75),
                        AccountEntity(2, "Savings Account", "****5678", 10200.00)
                    )
                )

                transactionDao.insertAll(
                    listOf(
                        TransactionEntity(accountId = 1, title = "Salary Deposit", amount = 3000.0, timestamp = System.currentTimeMillis() - 86400000, type = "CREDIT"),
                        TransactionEntity(accountId = 1, title = "Coffee Shop", amount = -5.75, timestamp = System.currentTimeMillis() - 43200000, type = "DEBIT"),
                        TransactionEntity(accountId = 2, title = "Interest", amount = 12.50, timestamp = System.currentTimeMillis() - 172800000, type = "CREDIT")
                    )
                )
            }
        }
    }
}
```

