class TransferViewModel(
    private val repository: BankingRepository
) : ViewModel() {
    val toAccount = mutableStateOf("")
    val amount = mutableStateOf("")
    val status = mutableStateOf<String?>(null)

    fun submitTransfer(fromAccountId: Int) {
        val parsedAmount = amount.value.toDoubleOrNull()
        if (parsedAmount == null) {
            status.value = "Invalid amount"
            return
        }

        viewModelScope.launch {
            val result = repository.transfer(fromAccountId, toAccount.value, parsedAmount)
            status.value = result.fold(
                onSuccess = { "Transfer successful" },
                onFailure = { it.message ?: "Transfer failed" }
            )
        }
    }
}

