```kotlin
package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalContext
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.*
import com.example.bankingapp.BankingApp
import com.example.bankingapp.ui.screens.AccountsScreen
import com.example.bankingapp.ui.screens.LoginScreen
import com.example.bankingapp.ui.screens.TransactionsScreen
import com.example.bankingapp.ui.screens.TransferScreen
import com.example.bankingapp.ui.viewmodel.*

object Routes {
    const val LOGIN = "login"
    const val ACCOUNTS = "accounts"
    const val TRANSACTIONS = "transactions"
    const val TRANSFER = "transfer"
}

@Composable
fun BankingNavGraph() {
    val navController = rememberNavController()
    val app = LocalContext.current.applicationContext as BankingApp

    NavHost(navController = navController, startDestination = Routes.LOGIN) {
        composable(Routes.LOGIN) {
            val vm: AuthViewModel = viewModel()
            LoginScreen(
                viewModel = vm,
                onLoginSuccess = {
                    navController.navigate(Routes.ACCOUNTS) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.ACCOUNTS) {
            val vm: AccountsViewModel = viewModel(
                factory = AccountsViewModelFactory(app.repository)
            )
            AccountsScreen(
                viewModel = vm,
                onAccountClick = { accountId ->
                    navController.navigate("${Routes.TRANSACTIONS}/$accountId")
                },
                onTransferClick = { accountId ->
                    navController.navigate("${Routes.TRANSFER}/$accountId")
                }
            )
        }

        composable(
            route = "${Routes.TRANSACTIONS}/{accountId}",
            arguments = listOf(navArgument("accountId") { type = NavType.IntType })
        ) { backStackEntry ->
            val accountId = backStackEntry.arguments?.getInt("accountId") ?: 0
            val vm: TransactionsViewModel = viewModel(
                factory = TransactionsViewModelFactory(app.repository, accountId)
            )
            TransactionsScreen(viewModel = vm)
        }

        composable(
            route = "${Routes.TRANSFER}/{accountId}",
            arguments = listOf(navArgument("accountId") { type = NavType.IntType })
        ) { backStackEntry ->
            val accountId = backStackEntry.arguments?.getInt("accountId") ?: 0
            val vm: TransferViewModel = viewModel(
                factory = TransferViewModelFactory(app.repository)
            )
            TransferScreen(
                viewModel = vm,
                accountId = accountId,
                onTransferDone = { navController.popBackStack() }
            )
        }
    }
}
```

