# 5. Repository

## BankingRepository.kt

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

class BankingRepository {

    private val _account = MutableStateFlow(
        Account(
            id = "1",
            holderName = "John Doe",
            accountNumberMasked = "****1234",
            balance = 2500.00
        )
    )
    val account: StateFlow<Account> = _account.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction(UUID.randomUUID().toString(), "Salary", 3000.00, "2026-09-01", TransactionType.CREDIT),
            Transaction(UUID.randomUUID().toString(), "Groceries", 120.50, "2026-09-03", TransactionType.DEBIT),
            Transaction(UUID.randomUUID().toString(), "Electric Bill", 75.25, "2026-09-05", TransactionType.DEBIT)
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun transfer(recipient: String, amount: Double): Result<Unit> {
        val current = _account.value
        if (recipient.isBlank()) {
            return Result.failure(IllegalArgumentException("Recipient is required"))
        }
        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }
        if (amount > current.balance) {
            return Result.failure(IllegalArgumentException("Insufficient balance"))
        }

        _account.value = current.copy(balance = current.balance - amount)
        _transactions.value = listOf(
            Transaction(
                id = UUID.randomUUID().toString(),
                title = "Transfer to $recipient",
                amount = amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        ) + _transactions.value

        return Result.success(Unit)
    }
}
```

