package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.data.repository.BankingRepository
import com.example.bankingapp.ui.screen.DashboardScreen
import com.example.bankingapp.ui.screen.LoginScreen
import com.example.bankingapp.ui.screen.TransferScreen
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.AuthViewModelFactory
import com.example.bankingapp.ui.viewmodel.BankingViewModel
import com.example.bankingapp.ui.viewmodel.BankingViewModelFactory

@Composable
fun AppNavGraph() {
    val navController = rememberNavController()
    val repository = remember { BankingRepository() }

    val authViewModel: AuthViewModel = viewModel(
        factory = AuthViewModelFactory(repository)
    )
    val bankingViewModel: BankingViewModel = viewModel(
        factory = BankingViewModelFactory(repository)
    )

    NavHost(
        navController = navController,
        startDestination = Destinations.LOGIN
    ) {
        composable(Destinations.LOGIN) {
            LoginScreen(
                authViewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(Destinations.DASHBOARD) {
                        popUpTo(Destinations.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Destinations.DASHBOARD) {
            DashboardScreen(
                bankingViewModel = bankingViewModel,
                onTransferClick = {
                    navController.navigate(Destinations.TRANSFER)
                }
            )
        }

        composable(Destinations.TRANSFER) {
            TransferScreen(
                bankingViewModel = bankingViewModel,
                onBack = { navController.popBackStack() }
            )
        }
    }
}
