package com.example.bankingapp.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.repository.BankingRepository
import kotlinx.coroutines.flow.StateFlow

class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    val account: StateFlow<Account> = repository.account
    val transactions: StateFlow<List<Transaction>> = repository.transactions

    fun transfer(recipient: String, amountText: String): Result<Unit> {
        val amount = amountText.toDoubleOrNull()
            ?: return Result.failure(IllegalArgumentException("Enter a valid amount"))

        return repository.transfer(recipient, amount)
    }
}

class BankingViewModelFactory(
    private val repository: BankingRepository
) : ViewModelProvider.Factory {
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        return BankingViewModel(repository) as T
    }
}
