import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import kotlin.math.roundToInt

data class Transaction(
    val id: Int,
    val title: String,
    val amount: Double,
    val date: String
)

data class Account(
    val username: String,
    val password: String,
    var balance: Double,
    val transactions: MutableList<Transaction>
)

class BankRepository {
    private val accounts = mutableStateListOf(
        Account(
            username = "alice",
            password = "1234",
            balance = 2500.0,
            transactions = mutableListOf(
                Transaction(1, "Salary", 3000.0, "2026-09-01"),
                Transaction(2, "Groceries", -120.0, "2026-09-03"),
                Transaction(3, "Electric Bill", -80.0, "2026-09-05")
            )
        ),
        Account(
            username = "bob",
            password = "1234",
            balance = 1000.0,
            transactions = mutableListOf(
                Transaction(1, "Initial Deposit", 1000.0, "2026-09-01")
            )
        )
    )

    fun login(username: String, password: String): Account? {
        return accounts.find { it.username == username && it.password == password }
    }

    fun transfer(from: Account, toUsername: String, amount: Double): String {
        val to = accounts.find { it.username == toUsername }
            ?: return "Recipient not found"

        if (from.username == to.username) return "Cannot transfer to same account"
        if (amount <= 0.0) return "Amount must be greater than zero"
        if (from.balance < amount) return "Insufficient funds"

        from.balance -= amount
        to.balance += amount

        val date = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault()).format(Date())
        val fromTxId = from.transactions.size + 1
        val toTxId = to.transactions.size + 1

        from.transactions.add(
            Transaction(fromTxId, "Transfer to ${to.username}", -amount, date)
        )
        to.transactions.add(
            Transaction(toTxId, "Transfer from ${from.username}", amount, date)
        )

        return "Transfer successful"
    }
}

@Composable
fun BankApp() {
    val navController = rememberNavController()
    val repository = remember { BankRepository() }

    NavHost(navController = navController, startDestination = "login") {
        composable("login") {
            LoginScreen(
                onLogin = { username, password ->
                    val account = repository.login(username, password)
                    account?.let {
                        navController.navigate("dashboard/${it.username}")
                    }
                }
            )
        }

        composable(
            route = "dashboard/{username}",
            arguments = listOf(navArgument("username") { type = NavType.StringType })
        ) { backStackEntry ->
            val username = backStackEntry.arguments?.getString("username") ?: ""
            val account = repository.login(username, "1234") // minimal demo lookup

            if (account != null) {
                DashboardScreen(
                    account = account,
                    onTransfer = { toUser, amount ->
                        repository.transfer(account, toUser, amount)
                    },
                    onLogout = {
                        navController.navigate("login") {
                            popUpTo("login") { inclusive = true }
                        }
                    }
                )
            }
        }
    }
}

