package com.example.bankapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.bankapp.ui.screens.HomeScreen
import com.example.bankapp.ui.screens.LoginScreen
import com.example.bankapp.ui.screens.TransferScreen

enum class Screen {
    LOGIN, HOME, TRANSFER
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            MaterialTheme {
                Surface {
                    val viewModel: BankViewModel = viewModel()
                    var currentScreen = if (viewModel.isLoggedIn) Screen.HOME else Screen.LOGIN

                    when (currentScreen) {
                        Screen.LOGIN -> LoginScreen(
                            error = viewModel.loginError,
                            onLogin = { username, password ->
                                viewModel.login(username, password)
                            },
                            onLoginSuccessCheck = {
                                if (viewModel.isLoggedIn) {
                                    currentScreen = Screen.HOME
                                }
                            }
                        )

                        Screen.HOME -> HomeScreen(
                            account = viewModel.account,
                            transactions = viewModel.transactions,
                            onTransferClick = { currentScreen = Screen.TRANSFER },
                            onLogoutClick = {
                                viewModel.logout()
                                currentScreen = Screen.LOGIN
                            }
                        )

                        Screen.TRANSFER -> TransferScreen(
                            error = viewModel.loginError,
                            onBack = { currentScreen = Screen.HOME },
                            onTransfer = { recipient, amount ->
                                if (viewModel.transfer(recipient, amount)) {
                                    currentScreen = Screen.HOME
                                }
                            }
                        )
                    }
                }
            }
        }
    }
}
