import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

data class Transaction(
    val title: String,
    val amount: Double,
    val date: String
)

class BankingViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var username by mutableStateOf("")
        private set

    var balance by mutableStateOf(1250.00)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction("Coffee Shop", -4.50, "2026-09-10"),
            Transaction("Salary", 2500.00, "2026-09-09"),
            Transaction("Groceries", -76.20, "2026-09-08")
        )
    )
        private set

    fun login(user: String, password: String): Boolean {
        return if (user.isNotBlank() && password == "password") {
            username = user
            isLoggedIn = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn = false
        username = ""
    }

    fun transfer(recipient: String, amountText: String): String {
        val amount = amountText.toDoubleOrNull()
            ?: return "Invalid amount"

        if (recipient.isBlank()) return "Recipient required"
        if (amount <= 0) return "Amount must be greater than 0"
        if (amount > balance) return "Insufficient funds"

        balance -= amount

        val date = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
        transactions = listOf(
            Transaction("Transfer to $recipient", -amount, date)
        ) + transactions

        return "Transfer successful"
    }
}
