# 5. Fake repository

## `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

class FakeBankRepository {

    private val _account = MutableStateFlow(
        Account(
            accountNumber = "1234567890",
            accountHolder = "John Doe",
            balance = 2500.00
        )
    )
    val account: StateFlow<Account> = _account.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction("1", "Grocery Store", -54.20, "2026-09-10"),
            Transaction("2", "Salary", 3200.00, "2026-09-09"),
            Transaction("3", "Electric Bill", -120.75, "2026-09-08")
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun transfer(recipient: String, amount: Double): Boolean {
        val current = _account.value
        if (recipient.isBlank() || amount <= 0 || amount > current.balance) {
            return false
        }

        _account.value = current.copy(balance = current.balance - amount)

        val updatedTransactions = listOf(
            Transaction(
                id = System.currentTimeMillis().toString(),
                title = "Transfer to $recipient",
                amount = -amount,
                date = "2026-09-16"
            )
        ) + _transactions.value

        _transactions.value = updatedTransactions
        return true
    }
}
```

