```kotlin
package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.FakeBankRepository
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import kotlinx.coroutines.flow.StateFlow

class BankViewModel : ViewModel() {
    private val repository = FakeBankRepository()

    val account: StateFlow<Account> = repository.account
    val transactions: StateFlow<List<Transaction>> = repository.transactions

    var isLoggedIn by mutableStateOf(false)
        private set

    var loginError by mutableStateOf<String?>(null)
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    fun login(username: String, password: String) {
        if (repository.login(username, password)) {
            isLoggedIn = true
            loginError = null
        } else {
            loginError = "Invalid credentials"
        }
    }

    fun transfer(recipient: String, amountText: String) {
        val amount = amountText.toDoubleOrNull()
        if (amount == null) {
            transferMessage = "Invalid amount"
            return
        }

        val success = repository.transfer(recipient, amount)
        transferMessage = if (success) {
            "Transfer successful"
        } else {
            "Transfer failed"
        }
    }

    fun clearTransferMessage() {
        transferMessage = null
    }
}
