package com.example.bankingapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.ui.DashboardScreen
import com.example.bankingapp.ui.LoginScreen
import com.example.bankingapp.ui.TransferScreen

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                Surface {
                    val navController = rememberNavController()
                    val viewModel: BankViewModel = viewModel()

                    NavHost(
                        navController = navController,
                        startDestination = "login"
                    ) {
                        composable("login") {
                            LoginScreen(
                                onLogin = { user, pass ->
                                    val success = viewModel.login(user, pass)
                                    if (success) {
                                        navController.navigate("dashboard") {
                                            popUpTo("login") { inclusive = true }
                                        }
                                    }
                                    success
                                }
                            )
                        }

                        composable("dashboard") {
                            DashboardScreen(
                                username = viewModel.username,
                                balance = viewModel.balance,
                                transactions = viewModel.transactions,
                                onTransferClick = {
                                    navController.navigate("transfer")
                                },
                                onLogoutClick = {
                                    viewModel.logout()
                                    navController.navigate("login") {
                                        popUpTo("dashboard") { inclusive = true }
                                    }
                                }
                            )
                        }

                        composable("transfer") {
                            TransferScreen(
                                onSubmit = { recipient, amount ->
                                    viewModel.transfer(recipient, amount)
                                },
                                onBack = {
                                    navController.popBackStack()
                                }
                            )
                        }
                    }
                }
            }
        }
    }
}
