```kotlin
package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.User

class BankingViewModel : ViewModel() {

    private val demoUser = User(
        username = "user",
        password = "1234",
        fullName = "John Doe",
        accountNumber = "1234567890",
        balance = 5000.0
    )

    var isLoggedIn by mutableStateOf(false)
        private set

    var currentUser by mutableStateOf<User?>(null)
        private set

    var balance by mutableStateOf(demoUser.balance)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction(1, "Grocery Store", -54.25, "2026-09-10"),
            Transaction(2, "Salary", 2500.00, "2026-09-09"),
            Transaction(3, "Electric Bill", -120.75, "2026-09-08")
        )
    )
        private set

    var loginError by mutableStateOf<String?>(null)
        private set

    fun login(username: String, password: String) {
        if (username == demoUser.username && password == demoUser.password) {
            currentUser = demoUser
            balance = demoUser.balance
            isLoggedIn = true
            loginError = null
        } else {
            loginError = "Invalid username or password"
        }
    }

    fun logout() {
        isLoggedIn = false
        currentUser = null
        loginError = null
    }

    fun transfer(recipient: String, amountText: String): Boolean {
        val amount = amountText.toDoubleOrNull()
        if (recipient.isBlank() || amount == null || amount <= 0 || amount > balance) {
            return false
        }

        balance -= amount
        val newTransaction = Transaction(
            id = transactions.size + 1,
            title = "Transfer to $recipient",
            amount = -amount,
            date = "2026-09-16"
        )
        transactions = listOf(newTransaction) + transactions
        return true
    }
}
