# 6) `BankViewModel.kt`

```kotlin
package com.example.minibank

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import kotlin.math.round

class BankViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var account by mutableStateOf(
        Account(
            accountNumber = "1234567890",
            holderName = "Alex Johnson",
            balance = 2500.00
        )
    )
        private set

    var transactions by mutableStateOf(
        listOf(
            TransactionItem(1, "Salary", 3000.00, TransactionType.CREDIT),
            TransactionItem(2, "Groceries", 120.50, TransactionType.DEBIT),
            TransactionItem(3, "Electric Bill", 75.25, TransactionType.DEBIT)
        )
    )
        private set

    fun login(username: String, password: String): Boolean {
        val success = username == "user" && password == "pass123"
        isLoggedIn = success
        return success
    }

    fun logout() {
        isLoggedIn = false
    }

    fun transfer(recipient: String, amount: Double): Boolean {
        if (recipient.isBlank()) return false
        if (amount <= 0.0) return false
        if (amount > account.balance) return false

        val newBalance = round((account.balance - amount) * 100) / 100
        account = account.copy(balance = newBalance)

        val newTransaction = TransactionItem(
            id = transactions.size + 1,
            title = "Transfer to $recipient",
            amount = amount,
            type = TransactionType.DEBIT
        )
        transactions = listOf(newTransaction) + transactions
        return true
    }
}
