package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.UUID

class BankingViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var username by mutableStateOf("")
        private set

    var account by mutableStateOf(
        Account(
            id = "1",
            name = "Checking Account",
            accountNumber = "****1234",
            balance = 2450.75
        )
    )
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction("t1", "Coffee Shop", -4.50, "2026-09-10 09:15"),
            Transaction("t2", "Salary", 2500.00, "2026-09-09 08:00"),
            Transaction("t3", "Electric Bill", -120.25, "2026-09-08 18:20")
        )
    )
        private set

    fun login(inputUsername: String, inputPassword: String): Boolean {
        return if (inputUsername.isNotBlank() && inputPassword == "password") {
            username = inputUsername
            isLoggedIn = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn = false
        username = ""
    }

    fun transfer(to: String, amount: Double): Result<Unit> {
        if (to.isBlank()) return Result.failure(Exception("Recipient is required"))
        if (amount <= 0) return Result.failure(Exception("Amount must be greater than zero"))
        if (amount > account.balance) return Result.failure(Exception("Insufficient funds"))

        account = account.copy(balance = account.balance - amount)

        val formatter = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
        val timestamp = formatter.format(Date())

        val newTransaction = Transaction(
            id = UUID.randomUUID().toString(),
            title = "Transfer to $to",
            amount = -amount,
            timestamp = timestamp
        )

        transactions = listOf(newTransaction) + transactions
        return Result.success(Unit)
    }
}
