package com.example.bankingapp.data

class FakeBankRepository {
    private val demoUser = User(
        username = "user",
        password = "pass123",
        fullName = "Alex Johnson"
    )

    private val account = Account(
        accountNumber = "1234567890",
        balance = 2450.75,
        transactions = mutableListOf(
            Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
            Transaction(2, "Salary", 3200.00, "2026-09-09"),
            Transaction(3, "Groceries", -82.30, "2026-09-08")
        )
    )

    fun login(username: String, password: String): User? {
        return if (username == demoUser.username && password == demoUser.password) {
            demoUser
        } else {
            null
        }
    }

    fun getAccount(): Account = account

    fun transfer(toAccount: String, amount: Double): Boolean {
        if (toAccount.isBlank() || amount <= 0 || amount > account.balance) return false

        account.balance -= amount
        account.transactions.add(
            0,
            Transaction(
                id = account.transactions.size + 1,
                title = "Transfer to $toAccount",
                amount = -amount,
                date = "2026-09-16"
            )
        )
        return true
    }
}
