```kotlin
package com.example.bankingapp.ui

import androidx.compose.runtime.*
import androidx.navigation.compose.*
import com.example.bankingapp.data.FakeBankRepository
import com.example.bankingapp.data.User

@Composable
fun BankingApp() {
    val repository = remember { FakeBankRepository() }
    var currentUser by remember { mutableStateOf<User?>(null) }

    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = "login"
    ) {
        composable("login") {
            LoginScreen(
                onLogin = { username, password ->
                    val user = repository.login(username, password)
                    if (user != null) {
                        currentUser = user
                        navController.navigate("dashboard") {
                            popUpTo("login") { inclusive = true }
                        }
                    }
                }
            )
        }

        composable("dashboard") {
            currentUser?.let { user ->
                DashboardScreen(
                    user = user,
                    account = repository.getAccount(),
                    onTransferClick = {
                        navController.navigate("transfer")
                    }
                )
            }
        }

        composable("transfer") {
            TransferScreen(
                onBack = { navController.popBackStack() },
                onTransfer = { toAccount, amount ->
                    val success = repository.transfer(toAccount, amount)
                    if (success) {
                        navController.popBackStack()
                    }
                    success
                }
            )
        }
    }
}
