```kotlin
package com.example.bankingapp.data

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction

object BankRepository {
    var isLoggedIn = mutableStateOf(false)
    var currentUser = mutableStateOf("")

    var account = mutableStateOf(
        Account(
            accountNumber = "1234567890",
            accountName = "Demo User",
            balance = 2500.00
        )
    )

    val transactions = mutableStateListOf(
        Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
        Transaction(2, "Salary", 1500.00, "2026-09-09"),
        Transaction(3, "Groceries", -62.30, "2026-09-08")
    )

    fun login(username: String, password: String): Boolean {
        return if (username == "demo" && password == "password") {
            currentUser.value = username
            isLoggedIn.value = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn.value = false
        currentUser.value = ""
    }

    fun transfer(recipient: String, amount: Double): Boolean {
        val current = account.value
        if (recipient.isBlank() || amount <= 0 || amount > current.balance) return false

        account.value = current.copy(balance = current.balance - amount)
        transactions.add(
            0,
            Transaction(
                id = transactions.size + 1,
                title = "Transfer to $recipient",
                amount = -amount,
                date = "2026-09-16"
            )
        )
        return true
    }
}
