# 8) `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

class FakeBankRepository {

    private var currentUser: User? = null

    private val transactions = mutableListOf(
        Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
        Transaction(2, "Salary", 2500.00, "2026-09-09"),
        Transaction(3, "Electric Bill", -75.20, "2026-09-08")
    )

    fun login(username: String, password: String): Boolean {
        return if (username == "user" && password == "pass") {
            currentUser = User(
                username = username,
                fullName = "John Doe",
                balance = 3420.30
            )
            true
        } else {
            false
        }
    }

    fun getCurrentUser(): User? = currentUser

    fun getTransactions(): List<Transaction> = transactions.toList()

    fun transfer(to: String, amount: Double): Result<User> {
        val user = currentUser ?: return Result.failure(Exception("Not logged in"))

        if (to.isBlank()) {
            return Result.failure(Exception("Recipient is required"))
        }

        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        if (amount > user.balance) {
            return Result.failure(Exception("Insufficient funds"))
        }

        val updatedUser = user.copy(balance = user.balance - amount)
        currentUser = updatedUser

        transactions.add(
            0,
            Transaction(
                id = transactions.size + 1,
                title = "Transfer to $to",
                amount = -amount,
                date = "2026-09-16"
            )
        )

        return Result.success(updatedUser)
    }
}
