                    transactions = transactions,
                    onTransfer = { to, amount ->
                        val result = repository.transfer(to, amount)
                        result.onSuccess {
                            user = it
                            transactions = repository.getTransactions()
                        }.onFailure {
                            loginError = it.message ?: "Transfer failed"
                        }
                    },
                    message = loginError
                )
