```kotlin
package com.example.bankingapp

import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.FakeBankRepository
import com.example.bankingapp.model.Transaction
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

data class BankUiState(
    val isLoggedIn: Boolean = false,
    val username: String = "",
    val balance: Double = 0.0,
    val transactions: List<Transaction> = emptyList(),
    val error: String? = null,
    val transferMessage: String? = null
)

class BankViewModel : ViewModel() {
    private val repository = FakeBankRepository()

    private val _uiState = MutableStateFlow(BankUiState())
    val uiState: StateFlow<BankUiState> = _uiState.asStateFlow()

    fun login(username: String, password: String) {
        val success = repository.login(username, password)
        if (success) {
            _uiState.value = BankUiState(
                isLoggedIn = true,
                username = username,
                balance = repository.getBalance(),
                transactions = repository.getTransactions()
            )
        } else {
            _uiState.value = _uiState.value.copy(error = "Invalid credentials")
        }
    }

    fun transfer(toAccount: String, amount: Double) {
        val result = repository.transfer(toAccount, amount)
        if (result.isSuccess) {
            _uiState.value = _uiState.value.copy(
                balance = repository.getBalance(),
                transactions = repository.getTransactions(),
                transferMessage = "Transfer successful",
                error = null
            )
        } else {
            _uiState.value = _uiState.value.copy(
                transferMessage = result.exceptionOrNull()?.message ?: "Transfer failed"
            )
        }
    }

    fun logout() {
        repository.logout()
        _uiState.value = BankUiState()
    }
}
