# 5) `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Transaction
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.UUID

class FakeBankRepository {
    private var loggedIn = false
    private var balance = 1250.75

    private val transactions = mutableListOf(
        Transaction("1", "Coffee Shop", -4.50, "2026-09-10"),
        Transaction("2", "Salary", 2500.00, "2026-09-01"),
        Transaction("3", "Electric Bill", -120.25, "2026-08-28")
    )

    fun login(username: String, password: String): Boolean {
        loggedIn = username == "user" && password == "password"
        return loggedIn
    }

    fun logout() {
        loggedIn = false
    }

    fun getBalance(): Double = balance

    fun getTransactions(): List<Transaction> = transactions.reversed()

    fun transfer(toAccount: String, amount: Double): Result<Unit> {
        if (!loggedIn) return Result.failure(Exception("Not logged in"))
        if (toAccount.isBlank()) return Result.failure(Exception("Recipient required"))
        if (amount <= 0) return Result.failure(Exception("Amount must be greater than zero"))
        if (amount > balance) return Result.failure(Exception("Insufficient funds"))

        balance -= amount

        val date = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
        transactions.add(
            Transaction(
                id = UUID.randomUUID().toString(),
                description = "Transfer to $toAccount",
                amount = -amount,
                date = date
            )
        )

        return Result.success(Unit)
    }
}
