## `surveyRepository.js`

```javascript
import { runQuery } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey({ title, notes, latitude, longitude }) {
  const id = uuidv4();
  const updatedAt = Date.now();

  await runQuery(
    `INSERT INTO surveys (id, title, notes, latitude, longitude, updatedAt, deleted, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, 0, 'pending')`,
    [id, title, notes, latitude, longitude, updatedAt]
  );

  return id;
}

export async function updateSurvey(id, updates) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const merged = {
    ...existing,
    ...updates,
    updatedAt: Date.now(),
    syncStatus: 'pending',
  };

  await runQuery(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [
      merged.title,
      merged.notes,
      merged.latitude,
      merged.longitude,
      merged.updatedAt,
      merged.syncStatus,
      id,
    ]
  );
}

export async function deleteSurvey(id) {
  await runQuery(
    `UPDATE surveys
     SET deleted = 1, updatedAt = ?, syncStatus = 'pending'
     WHERE id = ?`,
    [Date.now(), id]
  );
}

export async function getSurveyById(id) {
  const result = await runQuery(`SELECT * FROM surveys WHERE id = ? LIMIT 1`, [id]);
  return result.rows.length ? result.rows.item(0) : null;
}

export async function getAllActiveSurveys() {
  const result = await runQuery(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function getPendingSurveys() {
  const result = await runQuery(
    `SELECT * FROM surveys WHERE syncStatus = 'pending'`
  );
  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function upsertSurveyFromServer(record) {
  const existing = await getSurveyById(record.id);

  if (!existing) {
    await runQuery(
      `INSERT INTO surveys (id, title, notes, latitude, longitude, updatedAt, deleted, syncStatus)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced')`,
      [
        record.id,
        record.title,
        record.notes,
        record.latitude,
        record.longitude,
        record.updatedAt,
        record.deleted ? 1 : 0,
      ]
    );
    return;
  }

  if (record.updatedAt >= existing.updatedAt) {
    await runQuery(
      `UPDATE surveys
       SET title = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, deleted = ?, syncStatus = 'synced'
       WHERE id = ?`,
      [
        record.title,
        record.notes,
        record.latitude,
        record.longitude,
        record.updatedAt,
        record.deleted ? 1 : 0,
        record.id,
      ]
    );
  }
}

export async function markSurveysSynced(ids) {
  if (!ids.length) return;

  const placeholders = ids.map(() => '?').join(',');
  await runQuery(
    `UPDATE surveys SET syncStatus = 'synced' WHERE id IN (${placeholders})`,
    ids
  );
}

export async function getMetadata(key) {
  const result = await runQuery(`SELECT value FROM metadata WHERE key = ? LIMIT 1`, [key]);
  return result.rows.length ? result.rows.item(0).value : null;
}

export async function setMetadata(key, value) {
  await runQuery(
    `INSERT INTO metadata (key, value)
     VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}
