## `syncService.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingSurveys,
  upsertSurveyFromServer,
  markSurveysSynced,
  getMetadata,
  setMetadata,
} from './surveyRepository';

const API_URL = 'http://YOUR_SERVER_IP:3000';

let syncInProgress = false;

export async function syncNow() {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const netState = await NetInfo.fetch();
    if (!netState.isConnected) return;

    const pending = await getPendingSurveys();
    const lastSync = Number(await getMetadata('lastSync') || 0);

    const response = await fetch(`${API_URL}/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        lastSync,
        changes: pending.map(r => ({
          id: r.id,
          title: r.title,
          notes: r.notes,
          latitude: r.latitude,
          longitude: r.longitude,
          updatedAt: r.updatedAt,
          deleted: !!r.deleted,
        })),
      }),
    });

    if (!response.ok) {
      throw new Error(`Sync failed: ${response.status}`);
    }

    const data = await response.json();

    for (const record of data.changes) {
      await upsertSurveyFromServer(record);
    }

    await markSurveysSynced(pending.map(p => p.id));
    await setMetadata('lastSync', String(data.serverTime));
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncInProgress = false;
  }
}

export function startSyncListener() {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncNow();
    }
  });
}
