```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/health', (req, res) => {
  res.json({ ok: true });
});

app.post('/sync', (req, res) => {
  const { lastSync = 0, changes = [] } = req.body;
  const now = Date.now();

  for (const incoming of changes) {
    const existing = surveys.get(incoming.id);

    if (!existing || incoming.updatedAt >= existing.updatedAt) {
      surveys.set(incoming.id, {
        id: incoming.id,
        title: incoming.title ?? '',
        notes: incoming.notes ?? '',
        latitude: incoming.latitude ?? 0,
        longitude: incoming.longitude ?? 0,
        updatedAt: incoming.updatedAt ?? now,
        deleted: !!incoming.deleted,
      });
    }
  }

  const changedSinceLastSync = [];
  for (const survey of surveys.values()) {
    if (survey.updatedAt > lastSync) {
      changedSinceLastSync.push(survey);
    }
  }

  res.json({
    serverTime: now,
    changes: changedSinceLastSync,
  });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Sync server listening on port ${PORT}`);
});
