## `surveyRepository.ts`

```ts
import { getDb } from './db';
import { Survey } from './types';
import { v4 as uuidv4 } from 'uuid';

export function createSurvey(data: {
  title: string;
  location?: string;
  notes?: string;
}): Promise<Survey> {
  const db = getDb();
  const survey: Survey = {
    id: uuidv4(),
    title: data.title,
    location: data.location || '',
    notes: data.notes || '',
    updatedAt: Date.now(),
    deleted: 0,
    syncStatus: 'pending_create',
  };

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, title, location, notes, updatedAt, deleted, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          survey.deleted,
          survey.syncStatus,
        ]
      );
    }, reject, () => resolve(survey));
  });
}

export function updateSurvey(
  id: string,
  updates: Partial<Pick<Survey, 'title' | 'location' | 'notes'>>
): Promise<void> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ?`,
        [id],
        (_, result) => {
          if (result.rows.length === 0) {
            reject(new Error('Survey not found'));
            return true;
          }

          const current = result.rows.item(0) as Survey;
          const nextTitle = updates.title ?? current.title;
          const nextLocation = updates.location ?? current.location;
          const nextNotes = updates.notes ?? current.notes;
          const nextUpdatedAt = Date.now();
          const nextSyncStatus =
            current.syncStatus === 'pending_create'
              ? 'pending_create'
              : 'pending_update';

          tx.executeSql(
            `UPDATE surveys
             SET title = ?, location = ?, notes = ?, updatedAt = ?, syncStatus = ?
             WHERE id = ?`,
            [
              nextTitle,
              nextLocation,
              nextNotes,
              nextUpdatedAt,
              nextSyncStatus,
              id,
            ]
          );
        }
      );
    }, reject, () => resolve());
  });
}

export function deleteSurvey(id: string): Promise<void> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ?`,
        [id],
        (_, result) => {
          if (result.rows.length === 0) {
            reject(new Error('Survey not found'));
            return true;
          }

          const current = result.rows.item(0) as Survey;

          if (current.syncStatus === 'pending_create') {
            tx.executeSql(`DELETE FROM surveys WHERE id = ?`, [id]);
          } else {
            tx.executeSql(
              `UPDATE surveys
               SET deleted = 1, updatedAt = ?, syncStatus = 'pending_delete'
               WHERE id = ?`,
              [Date.now(), id]
            );
          }
        }
      );
    }, reject, () => resolve());
  });
}

export function listSurveys(): Promise<Survey[]> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`,
        [],
        (_, result) => {
          const items: Survey[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
          return true;
        }
      );
    }, reject);
  });
}

export function getPendingSurveys(): Promise<Survey[]> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE syncStatus != 'synced'`,
        [],
        (_, result) => {
          const items: Survey[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
          return true;
        }
      );
    }, reject);
  });
}

export function markAsSynced(ids: string[], serverUpdatedAtMap?: Record<string, number>): Promise<void> {
  if (ids.length === 0) return Promise.resolve();
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      ids.forEach(id => {
        const serverUpdatedAt = serverUpdatedAtMap?.[id] ?? Date.now();
        tx.executeSql(
          `UPDATE surveys
           SET syncStatus = 'synced', updatedAt = ?
           WHERE id = ?`,
          [serverUpdatedAt, id]
        );
      });
    }, reject, () => resolve());
  });
}

export function purgeDeletedSynced(ids: string[]): Promise<void> {
  if (ids.length === 0) return Promise.resolve();
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      ids.forEach(id => {
        tx.executeSql(`DELETE FROM surveys WHERE id = ?`, [id]);
      });
    }, reject, () => resolve());
  });
}

export function upsertFromServer(surveys: Survey[]): Promise<void> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      surveys.forEach(survey => {
        tx.executeSql(
          `SELECT * FROM surveys WHERE id = ?`,
          [survey.id],
          (_, result) => {
            if (result.rows.length === 0) {
              tx.executeSql(
                `INSERT INTO surveys (id, title, location, notes, updatedAt, deleted, syncStatus)
                 VALUES (?, ?, ?, ?, ?, ?, 'synced')`,
                [
                  survey.id,
                  survey.title,
                  survey.location || '',
                  survey.notes || '',
                  survey.updatedAt,
                  survey.deleted,
                ]
              );
            } else {
              const local = result.rows.item(0) as Survey;

              // Do not overwrite unsynced local changes
              if (local.syncStatus !== 'synced') return true;

              tx.executeSql(
                `UPDATE surveys
                 SET title = ?, location = ?, notes = ?, updatedAt = ?, deleted = ?, syncStatus = 'synced'
                 WHERE id = ?`,
                [
                  survey.title,
                  survey.location || '',
                  survey.notes || '',
                  survey.updatedAt,
                  survey.deleted,
                  survey.id,
                ]
              );
            }
            return true;
          }
        );
      });
    }, reject, () => resolve());
  });
}

export function getMetadata(key: string): Promise<string | null> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT value FROM metadata WHERE key = ?`,
        [key],
        (_, result) => {
          if (result.rows.length === 0) resolve(null);
          else resolve(result.rows.item(0).value);
          return true;
        }
      );
    }, reject);
  });
}

export function setMetadata(key: string, value: string): Promise<void> {
  const db = getDb();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO metadata (key, value) VALUES (?, ?)`,
        [key, value]
      );
    }, reject, () => resolve());
  });
}
