## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingSurveys,
  markAsSynced,
  purgeDeletedSynced,
  upsertFromServer,
  getMetadata,
  setMetadata,
} from './surveyRepository';
import { Survey } from './types';

const API_URL = 'http://YOUR_SERVER_IP:3000';

let syncInProgress = false;

type PushPayload = {
  changes: Survey[];
};

type PushResponse = {
  applied: { id: string; updatedAt: number; deleted: boolean }[];
  conflicts: { id: string; reason: string }[];
};

type PullResponse = {
  changes: Survey[];
  serverTime: number;
};

export async function syncNow() {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    await pushLocalChanges();
    await pullRemoteChanges();
  } finally {
    syncInProgress = false;
  }
}

async function pushLocalChanges() {
  const pending = await getPendingSurveys();
  if (pending.length === 0) return;

  const payload: PushPayload = { changes: pending };

  const res = await fetch(`${API_URL}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    throw new Error(`Push failed: ${res.status}`);
  }

  const data: PushResponse = await res.json();

  const syncedIds: string[] = [];
  const deletedIds: string[] = [];
  const updatedAtMap: Record<string, number> = {};

  for (const item of data.applied) {
    updatedAtMap[item.id] = item.updatedAt;
    if (item.deleted) deletedIds.push(item.id);
    else syncedIds.push(item.id);
  }

  await markAsSynced(syncedIds, updatedAtMap);
  await purgeDeletedSynced(deletedIds);

  if (data.conflicts.length > 0) {
    console.warn('Conflicts detected', data.conflicts);
  }
}

async function pullRemoteChanges() {
  const lastSync = await getMetadata('lastSync');
  const since = lastSync ? Number(lastSync) : 0;

  const res = await fetch(`${API_URL}/sync/pull?since=${since}`);
  if (!res.ok) {
    throw new Error(`Pull failed: ${res.status}`);
  }

  const data: PullResponse = await res.json();

  await upsertFromServer(data.changes);
  await setMetadata('lastSync', String(data.serverTime));
}

export function startSyncListener() {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncNow().catch(err => console.error('Sync error:', err));
    }
  });

  return unsubscribe;
}
