app.use(express.json());

const surveys = new Map(); 
// id -> { id, title, location, notes, updatedAt, deleted }

function now() {
  return Date.now();
}

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  const applied = [];
  const conflicts = [];

  for (const incoming of changes) {
    const existing = surveys.get(incoming.id);

    if (!existing) {
      const record = {
        id: incoming.id,
        title: incoming.title,
        location: incoming.location || '',
        notes: incoming.notes || '',
        updatedAt: now(),
        deleted: !!incoming.deleted,
      };
      surveys.set(incoming.id, record);
      applied.push({
        id: record.id,
        updatedAt: record.updatedAt,
        deleted: record.deleted,
      });
      continue;
    }

    // Simple last-write-wins conflict handling
    if (incoming.updatedAt >= existing.updatedAt) {
      existing.title = incoming.title;
      existing.location = incoming.location || '';
      existing.notes = incoming.notes || '';
      existing.deleted = !!incoming.deleted;
      existing.updatedAt = now();

      surveys.set(existing.id, existing);
      applied.push({
        id: existing.id,
        updatedAt: existing.updatedAt,
        deleted: existing.deleted,
      });
    } else {
      conflicts.push({
        id: incoming.id,
        reason: 'Server has newer version',
      });
    }
  }

  res.json({ applied, conflicts });
});

app.get('/sync/pull', (req, res) => {
  const since = Number(req.query.since || 0);
  const changes = [];

  for (const survey of surveys.values()) {
    if (survey.updatedAt > since) {
      changes.push(survey);
    }
  }

  res.json({
    changes,
    serverTime: now(),
  });
});

app.get('/surveys', (_, res) => {
  res.json(Array.from(surveys.values()).filter(s => !s.deleted));
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

