## `src/db.js`

This sets up IndexedDB with two stores:

- `surveys`: local survey records
- `outbox`: pending sync operations

```javascript
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains('outbox')) {
      const outboxStore = db.createObjectStore('outbox', {
        keyPath: 'queueId',
        autoIncrement: true,
      });
      outboxStore.createIndex('status', 'status');
      outboxStore.createIndex('createdAt', 'createdAt');
    }

    if (!db.objectStoreNames.contains('meta')) {
      db.createObjectStore('meta', { keyPath: 'key' });
    }
  },
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function getSurvey(id) {
  const db = await dbPromise;
  return db.get('surveys', id);
}

export async function saveSurveyLocally(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function deleteSurveyLocally(id) {
  const db = await dbPromise;
  const existing = await db.get('surveys', id);
  if (!existing) return;

  await db.put('surveys', {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
  });
}

export async function addToOutbox(operation) {
  const db = await dbPromise;
  return db.add('outbox', {
    ...operation,
    status: 'pending',
    createdAt: new Date().toISOString(),
    retries: 0,
  });
}

export async function getPendingOutboxItems() {
  const db = await dbPromise;
  return db.getAllFromIndex('outbox', 'status', 'pending');
}

export async function markOutboxItemDone(queueId) {
  const db = await dbPromise;
  const item = await db.get('outbox', queueId);
  if (!item) return;
  item.status = 'done';
  await db.put('outbox', item);
}

export async function markOutboxItemFailed(queueId) {
  const db = await dbPromise;
  const item = await db.get('outbox', queueId);
  if (!item) return;
  item.retries += 1;
  item.lastTriedAt = new Date().toISOString();
  await db.put('outbox', item);
}

export async function getMeta(key) {
  const db = await dbPromise;
  const row = await db.get('meta', key);
  return row?.value;
}

export async function setMeta(key, value) {
  const db = await dbPromise;
  await db.put('meta', { key, value });
}
```

