const API_BASE = 'http://localhost:4000';

export async function pushSurveyChange(change) {
  const response = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(change),
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Push failed: ${text}`);
  }

  return response.json();
}

export async function pullSurveyChanges(since) {
  const url = new URL(`${API_BASE}/sync/pull`);
  if (since) url.searchParams.set('since', since);

  const response = await fetch(url.toString());
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Pull failed: ${text}`);
  }

  return response.json();
}
