## `src/sync.js`

Core sync engine.

```javascript
import {
  getPendingOutboxItems,
  markOutboxItemDone,
  markOutboxItemFailed,
  saveSurveyLocally,
  setMeta,
  getMeta,
} from './db';
import { pushSurveyChange, pullSurveyChanges } from './api';

let syncInProgress = false;

export async function syncNow() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    // 1. Push local pending changes
    const pending = await getPendingOutboxItems();

    for (const item of pending) {
      try {
        await pushSurveyChange({
          operation: item.operation,
          record: item.record,
          clientUpdatedAt: item.clientUpdatedAt,
        });
        await markOutboxItemDone(item.queueId);
      } catch (err) {
        console.error('Failed to push outbox item', item.queueId, err);
        await markOutboxItemFailed(item.queueId);
      }
    }

    // 2. Pull remote changes
    const lastSync = await getMeta('lastSync');
    const result = await pullSurveyChanges(lastSync);

    for (const survey of result.changes) {
      await saveSurveyLocally(survey);
    }

    await setMeta('lastSync', result.serverTime);
  } finally {
    syncInProgress = false;
  }
}

export function setupSyncListeners() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncNow();
  });
}
```

