## `src/surveyService.js`

Local-first CRUD methods.

```javascript
import { v4 as uuidv4 } from 'uuid';
import {
  saveSurveyLocally,
  deleteSurveyLocally,
  addToOutbox,
  getAllSurveys,
} from './db';
import { syncNow } from './sync';

export async function listSurveys() {
  const surveys = await getAllSurveys();
  return surveys.filter((s) => !s.deleted);
}

export async function createSurvey(data) {
  const now = new Date().toISOString();
  const survey = {
    id: uuidv4(),
    ...data,
    createdAt: now,
    updatedAt: now,
    deleted: false,
    version: 1,
  };

  await saveSurveyLocally(survey);

  await addToOutbox({
    operation: 'upsert',
    record: survey,
    clientUpdatedAt: now,
  });

  syncNow();
  return survey;
}

export async function updateSurvey(id, updates) {
  const surveys = await getAllSurveys();
  const existing = surveys.find((s) => s.id === id);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...updates,
    updatedAt: new Date().toISOString(),
    version: (existing.version || 1) + 1,
  };

  await saveSurveyLocally(updated);

  await addToOutbox({
    operation: 'upsert',
    record: updated,
    clientUpdatedAt: updated.updatedAt,
  });

  syncNow();
  return updated;
}

export async function removeSurvey(id) {
  await deleteSurveyLocally(id);

  await addToOutbox({
    operation: 'delete',
    record: { id },
    clientUpdatedAt: new Date().toISOString(),
  });

  syncNow();
}
```

