## `server.js`

This is a simple in-memory backend for demo purposes. In production, use PostgreSQL, MongoDB, etc.

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

// Push local client changes to server
app.post('/sync/push', (req, res) => {
  const { operation, record, clientUpdatedAt } = req.body;

  if (!operation || !record) {
    return res.status(400).send('Invalid payload');
  }

  if (operation === 'upsert') {
    const existing = surveys.get(record.id);

    // Simple last-write-wins conflict resolution
    if (!existing || new Date(record.updatedAt) >= new Date(existing.updatedAt)) {
      surveys.set(record.id, {
        ...existing,
        ...record,
        serverUpdatedAt: new Date().toISOString(),
      });
    }

    return res.json({ ok: true });
  }

  if (operation === 'delete') {
    const existing = surveys.get(record.id);

    if (existing) {
      surveys.set(record.id, {
        ...existing,
        deleted: true,
        updatedAt: clientUpdatedAt || new Date().toISOString(),
        serverUpdatedAt: new Date().toISOString(),
      });
    } else {
      surveys.set(record.id, {
        id: record.id,
        deleted: true,
        updatedAt: clientUpdatedAt || new Date().toISOString(),
        serverUpdatedAt: new Date().toISOString(),
      });
    }

    return res.json({ ok: true });
  }

  return res.status(400).send('Unknown operation');
});

// Pull server changes since last sync
app.get('/sync/pull', (req, res) => {
  const since = req.query.since;
  const sinceDate = since ? new Date(since) : null;

  const changes = Array.from(surveys.values()).filter((survey) => {
    if (!sinceDate) return true;
    return new Date(survey.serverUpdatedAt) > sinceDate;
  });

  res.json({
    changes,
    serverTime: new Date().toISOString(),
  });
});

app.listen(4000, () => {
  console.log('Sync server running on http://localhost:4000');
});
```

