import { getDB } from './db';
import { uuid, now } from './utils';

export async function createSurvey({ title, location, notes }) {
  const db = getDB();
  const id = uuid();
  const updatedAt = now();
  const version = 1;

  await db.executeSql(
    `INSERT INTO surveys (id, title, location, notes, updatedAt, version, deleted)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [id, title, location, notes, updatedAt, version]
  );

  await enqueueChange({
    entityType: 'survey',
    entityId: id,
    operation: 'upsert',
    payload: { id, title, location, notes, updatedAt, version, deleted: 0 }
  });

  return id;
}

export async function updateSurvey(id, updates) {
  const db = getDB();

  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) throw new Error('Survey not found');

  const current = result.rows.item(0);
  const updated = {
    ...current,
    ...updates,
    updatedAt: now(),
    version: current.version + 1
  };

  await db.executeSql(
    `UPDATE surveys
     SET title = ?, location = ?, notes = ?, updatedAt = ?, version = ?, deleted = ?
     WHERE id = ?`,
    [
      updated.title,
      updated.location,
      updated.notes,
      updated.updatedAt,
      updated.version,
      updated.deleted || 0,
      id
    ]
  );

  await enqueueChange({
    entityType: 'survey',
    entityId: id,
    operation: 'upsert',
    payload: updated
  });
}

export async function deleteSurvey(id) {
  const db = getDB();

  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) return;

  const current = result.rows.item(0);
  const updatedAt = now();
  const version = current.version + 1;

  await db.executeSql(
    `UPDATE surveys SET deleted = 1, updatedAt = ?, version = ? WHERE id = ?`,
    [updatedAt, version, id]
  );

  await enqueueChange({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { ...current, deleted: 1, updatedAt, version }
  });
}

export async function listSurveys() {
  const db = getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function enqueueChange({ entityType, entityId, operation, payload }) {
  const db = getDB();
  const queueId = uuid();

  await db.executeSql(
    `INSERT INTO sync_queue (id, entityType, entityId, operation, payload, timestamp, synced)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [queueId, entityType, entityId, operation, JSON.stringify(payload), now()]
  );
}
