## `syncService.js`

```javascript
import axios from 'axios';
import NetInfo from '@react-native-community/netinfo';
import { getDB } from './db';

const API_URL = 'http://YOUR_SERVER_IP:3000';

let syncing = false;

export async function getLastSync() {
  const db = getDB();
  const [result] = await db.executeSql(`SELECT value FROM metadata WHERE key = 'lastSync'`);
  if (result.rows.length === 0) return 0;
  return parseInt(result.rows.item(0).value, 10) || 0;
}

export async function setLastSync(timestamp) {
  const db = getDB();
  await db.executeSql(
    `INSERT OR REPLACE INTO metadata (key, value) VALUES ('lastSync', ?)`,
    [String(timestamp)]
  );
}

export async function getPendingChanges() {
  const db = getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue WHERE synced = 0 ORDER BY timestamp ASC`
  );

  const changes = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    changes.push({
      ...row,
      payload: JSON.parse(row.payload)
    });
  }
  return changes;
}

export async function markChangesSynced(ids) {
  if (!ids.length) return;
  const db = getDB();
  const placeholders = ids.map(() => '?').join(',');
  await db.executeSql(
    `UPDATE sync_queue SET synced = 1 WHERE id IN (${placeholders})`,
    ids
  );
}

export async function applyServerChanges(changes) {
  const db = getDB();

  for (const change of changes) {
    if (change.entityType !== 'survey') continue;
    const s = change.payload;

    const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [s.id]);

    if (result.rows.length === 0) {
      await db.executeSql(
        `INSERT INTO surveys (id, title, location, notes, updatedAt, version, deleted)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [s.id, s.title, s.location, s.notes, s.updatedAt, s.version, s.deleted ? 1 : 0]
      );
    } else {
      const local = result.rows.item(0);

      if ((s.updatedAt || 0) > (local.updatedAt || 0)) {
        await db.executeSql(
          `UPDATE surveys
           SET title = ?, location = ?, notes = ?, updatedAt = ?, version = ?, deleted = ?
           WHERE id = ?`,
          [s.title, s.location, s.notes, s.updatedAt, s.version, s.deleted ? 1 : 0, s.id]
        );
      }
    }
  }
}

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    const pending = await getPendingChanges();
    const lastSync = await getLastSync();

    const response = await axios.post(`${API_URL}/sync`, {
      lastSync,
      changes: pending.map(c => ({
        id: c.id,
        entityType: c.entityType,
        entityId: c.entityId,
        operation: c.operation,
        payload: c.payload,
        timestamp: c.timestamp
      }))
    });

    const { ackedChangeIds, serverChanges, serverTime } = response.data;

    await applyServerChanges(serverChanges || []);
    await markChangesSynced(ackedChangeIds || []);
    await setLastSync(serverTime || Date.now());
  } catch (err) {
    console.error('Sync failed:', err.message);
  } finally {
    syncing = false;
  }
}

export function startSyncListener() {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncNow();
    }
  });
}
```

