## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const surveys = new Map();
const changeLog = [];

function recordChange(entityType, entityId, operation, payload) {
  const timestamp = Date.now();
  const change = {
    id: `${entityId}-${timestamp}`,
    entityType,
    entityId,
    operation,
    payload,
    timestamp
  };
  changeLog.push(change);
  return change;
}

app.post('/sync', (req, res) => {
  const { lastSync = 0, changes = [] } = req.body;
  const ackedChangeIds = [];

  for (const change of changes) {
    if (change.entityType !== 'survey') continue;

    const incoming = change.payload;
    const existing = surveys.get(incoming.id);

    if (!existing || incoming.updatedAt > existing.updatedAt) {
      surveys.set(incoming.id, incoming);
      recordChange(change.entityType, change.entityId, change.operation, incoming);
    }

    ackedChangeIds.push(change.id);
  }

  const serverChanges = changeLog.filter(c => c.timestamp > lastSync);
  const serverTime = Date.now();

  res.json({
    ackedChangeIds,
    serverChanges,
    serverTime
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()).filter(s => !s.deleted));
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

