import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet, Alert } from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';

const db = SQLite.openDatabase('survey.db');
const API_URL = 'http://YOUR_SERVER_IP:3000';

function executeSql(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
}

async function initDb() {
  await executeSql(`
    CREATE TABLE IF NOT EXISTS surveys (
      localId INTEGER PRIMARY KEY AUTOINCREMENT,
      serverId TEXT,
      title TEXT NOT NULL,
      latitude REAL,
      longitude REAL,
      notes TEXT,
      updatedAt TEXT NOT NULL,
      syncStatus TEXT NOT NULL
    );
  `);

  await executeSql(`
    CREATE TABLE IF NOT EXISTS sync_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      operation TEXT NOT NULL,
      localId INTEGER NOT NULL,
      payload TEXT NOT NULL,
      createdAt TEXT NOT NULL
    );
  `);
}

async function getAllSurveys() {
  const result = await executeSql(
    `SELECT * FROM surveys ORDER BY datetime(updatedAt) DESC;`
  );
  return result.rows._array;
}

async function insertSurveyLocally({ title, latitude, longitude, notes }) {
  const updatedAt = new Date().toISOString();

  const result = await executeSql(
    `INSERT INTO surveys (serverId, title, latitude, longitude, notes, updatedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?);`,
    [null, title, latitude, longitude, notes, updatedAt, 'pending']
  );

  const localId = result.insertId;

  const payload = {
    type: 'upsert',
    localId,
    serverId: null,
    title,
    latitude,
    longitude,
    notes,
    updatedAt,
  };

  await executeSql(
    `INSERT INTO sync_queue (operation, localId, payload, createdAt)
     VALUES (?, ?, ?, ?);`,
    ['upsert', localId, JSON.stringify(payload), updatedAt]
  );

  return localId;
}

async function updateLocalSurveyAfterSync(localId, serverRecord) {
  await executeSql(
    `UPDATE surveys
     SET serverId = ?, title = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncStatus = ?
     WHERE localId = ?;`,
    [
      serverRecord.id,
      serverRecord.title,
      serverRecord.latitude,
      serverRecord.longitude,
      serverRecord.notes,
      serverRecord.updatedAt,
      'synced',
      localId,
    ]
  );
}

async function removeQueueItem(queueId) {
  await executeSql(`DELETE FROM sync_queue WHERE id = ?;`, [queueId]);
}

async function getPendingQueue() {
  const result = await executeSql(
    `SELECT * FROM sync_queue ORDER BY id ASC;`
  );
  return result.rows._array;
}

async function applyServerPull(records) {
  for (const record of records) {
    const existing = await executeSql(
      `SELECT * FROM surveys WHERE serverId = ? LIMIT 1;`,
      [record.id]
    );

    if (existing.rows.length > 0) {
      const local = existing.rows.item(0);
      if (new Date(record.updatedAt) > new Date(local.updatedAt)) {
        await executeSql(
          `UPDATE surveys
           SET title = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncStatus = ?
           WHERE serverId = ?;`,
          [
            record.title,
            record.latitude,
            record.longitude,
            record.notes,
            record.updatedAt,
            'synced',
            record.id,
          ]
        );
      }
    } else {
      await executeSql(
        `INSERT INTO surveys (serverId, title, latitude, longitude, notes, updatedAt, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          record.id,
          record.title,
          record.latitude,
          record.longitude,
          record.notes,
          record.updatedAt,
          'synced',
        ]
      );
    }
  }
}

async function syncData() {
  const queue = await getPendingQueue();
  const changes = queue.map(item => ({
    queueId: item.id,
    ...JSON.parse(item.payload),
  }));

  const response = await fetch(`${API_URL}/sync`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ changes }),
  });

  if (!response.ok) {
    throw new Error('Sync failed');
  }

  const data = await response.json();

  for (const ack of data.acknowledged) {
    await updateLocalSurveyAfterSync(ack.localId, ack.record);
    await removeQueueItem(ack.queueId);
  }

  await applyServerPull(data.serverRecords || []);
}

export default function App() {
  const [title, setTitle] = useState('');
  const [latitude, setLatitude] = useState('');
  const [longitude, setLongitude] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const loadSurveys = useCallback(async () => {
    const rows = await getAllSurveys();
    setSurveys(rows);
  }, []);

  const handleSave = async () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    await insertSurveyLocally({
      title: title.trim(),
      latitude: latitude ? parseFloat(latitude) : null,
      longitude: longitude ? parseFloat(longitude) : null,
      notes: notes.trim(),
    });

    setTitle('');
    setLatitude('');
    setLongitude('');
    setNotes('');
    await loadSurveys();
  };

  const runSync = useCallback(async () => {
    if (!isOnline || isSyncing) return;

    try {
      setIsSyncing(true);
      await syncData();
      await loadSurveys();
    } catch (err) {
      console.log('Sync error:', err.message);
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, isSyncing, loadSurveys]);

  useEffect(() => {
    (async () => {
      await initDb();
      await loadSurveys();
    })();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);
    });

    return () => unsubscribe();
  }, [loadSurveys]);

  useEffect(() => {
    if (isOnline) {
      runSync();
    }
  }, [isOnline, runSync]);

  return (
    <View style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Status: {isOnline ? 'Online' : 'Offline'} {isSyncing ? '(Syncing...)' : ''}
      </Text>

      <TextInput
        style={styles.input}
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
      />
      <TextInput
        style={styles.input}
        placeholder="Latitude"
        value={latitude}
        onChangeText={setLatitude}
        keyboardType="numeric"
      />
      <TextInput
        style={styles.input}
        placeholder="Longitude"
        value={longitude}
        onChangeText={setLongitude}
        keyboardType="numeric"
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />

      <Button title="Save Survey" onPress={handleSave} />
      <View style={{ height: 12 }} />
      <Button title="Manual Sync" onPress={runSync} disabled={!isOnline || isSyncing} />

      <FlatList
        style={styles.list}
        data={surveys}
        keyExtractor={item => String(item.localId)}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.cardTitle}>{item.title}</Text>
            <Text>Lat: {item.latitude ?? '-'}</Text>
            <Text>Lng: {item.longitude ?? '-'}</Text>
            <Text>Notes: {item.notes || '-'}</Text>
            <Text>Updated: {item.updatedAt}</Text>
            <Text>Sync: {item.syncStatus}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 20,
    paddingTop: 60,
    backgroundColor: '#fff',
  },
  header: {
    fontSize: 24,
    fontWeight: '700',
    marginBottom: 8,
  },
  status: {
    marginBottom: 16,
    color: '#555',
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 10,
    marginBottom: 10,
    borderRadius: 6,
  },
  list: {
    marginTop: 20,
  },
  card: {
    padding: 12,
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 8,
    marginBottom: 10,
  },
  cardTitle: {
    fontWeight: '700',
    marginBottom: 4,
  },
});
