# Server Code

## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const { randomUUID } = require('crypto');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync', (req, res) => {
  const { changes = [] } = req.body;
  const acknowledged = [];

  for (const change of changes) {
    if (change.type === 'upsert') {
      let record;

      if (change.serverId && surveys.has(change.serverId)) {
        const existing = surveys.get(change.serverId);

        if (new Date(change.updatedAt) >= new Date(existing.updatedAt)) {
          record = {
            ...existing,
            title: change.title,
            latitude: change.latitude,
            longitude: change.longitude,
            notes: change.notes,
            updatedAt: change.updatedAt,
          };
          surveys.set(record.id, record);
        } else {
          record = existing;
        }
      } else {
        const id = randomUUID();
        record = {
          id,
          title: change.title,
          latitude: change.latitude,
          longitude: change.longitude,
          notes: change.notes,
          updatedAt: change.updatedAt,
        };
        surveys.set(id, record);
      }

      acknowledged.push({
        queueId: change.queueId,
        localId: change.localId,
        record,
      });
    }
  }

  const serverRecords = Array.from(surveys.values());

  res.json({
    acknowledged,
    serverRecords,
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

