# 3. Local database setup

## `db/database.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDatabase = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        location TEXT,
        notes TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        syncStatus TEXT NOT NULL
      );`
    );

    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        recordId TEXT NOT NULL,
        action TEXT NOT NULL,
        payload TEXT NOT NULL,
        createdAt TEXT NOT NULL
      );`
    );
  });
};

export const insertSurvey = survey => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, title, location, notes, createdAt, updatedAt, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.createdAt,
          survey.updatedAt,
          survey.syncStatus,
        ],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );

      tx.executeSql(
        `INSERT INTO sync_queue (recordId, action, payload, createdAt)
         VALUES (?, ?, ?, ?);`,
        [
          survey.id,
          'CREATE',
          JSON.stringify(survey),
          new Date().toISOString(),
        ]
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY createdAt DESC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getPendingQueue = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY createdAt ASC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const markSurveySynced = recordId => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET syncStatus = 'SYNCED', updatedAt = ? WHERE id = ?;`,
        [new Date().toISOString(), recordId],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const removeQueueItem = queueId => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?;`,
        [queueId],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export default db;
```

