# 5. Sync hook

## `hooks/useSync.js`

This hook:

- watches network state
- syncs queued records when online
- updates local sync status

```javascript
import { useEffect, useRef, useState } from 'react';
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingQueue,
  markSurveySynced,
  removeQueueItem,
} from '../db/database';
import { pushSurveyToServer } from '../api/syncApi';

export const useSync = () => {
  const [isOnline, setIsOnline] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const syncingRef = useRef(false);

  const syncPendingData = async () => {
    if (syncingRef.current) return;

    syncingRef.current = true;
    setIsSyncing(true);

    try {
      const queue = await getPendingQueue();

      for (const item of queue) {
        const payload = JSON.parse(item.payload);

        try {
          if (item.action === 'CREATE') {
            await pushSurveyToServer(payload);
            await markSurveySynced(item.recordId);
            await removeQueueItem(item.id);
          }
        } catch (err) {
          console.log('Sync failed for item:', item.id, err.message);
          break;
        }
      }
    } catch (err) {
      console.log('Sync process error:', err.message);
    } finally {
      syncingRef.current = false;
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      const connected = !!state.isConnected;
      setIsOnline(connected);

      if (connected) {
        syncPendingData();
      }
    });

    NetInfo.fetch().then(state => {
      const connected = !!state.isConnected;
      setIsOnline(connected);
      if (connected) syncPendingData();
    });

    return () => unsubscribe();
  }, []);

  return {
    isOnline,
    isSyncing,
    syncPendingData,
  };
};
```

