## `App.js`

```javascript
import React, { useEffect, useState, useCallback } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';

const db = SQLite.openDatabase('survey.db');
const API_URL = 'http://YOUR_SERVER_IP:3000/api/surveys';

export default function App() {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [records, setRecords] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadRecords();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);

      if (online) {
        syncPendingRecords();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction((tx) => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          local_id TEXT,
          name TEXT,
          location TEXT,
          notes TEXT,
          created_at TEXT,
          synced INTEGER DEFAULT 0
        );`,
        [],
        () => console.log('Database initialized'),
        (_, error) => {
          console.log('DB init error', error);
          return false;
        }
      );
    });
  };

  const loadRecords = () => {
    db.transaction((tx) => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY id DESC;',
        [],
        (_, { rows }) => {
          setRecords(rows._array);
        },
        (_, error) => {
          console.log('Load error', error);
          return false;
        }
      );
    });
  };

  const saveRecord = () => {
    if (!name || !location) {
      Alert.alert('Validation', 'Name and location are required.');
      return;
    }

    const localId = `local-${Date.now()}`;
    const createdAt = new Date().toISOString();

    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys (local_id, name, location, notes, created_at, synced)
         VALUES (?, ?, ?, ?, ?, 0);`,
        [localId, name, location, notes, createdAt],
        () => {
          setName('');
          setLocation('');
          setNotes('');
          loadRecords();

          if (isOnline) {
            syncPendingRecords();
          }
        },
        (_, error) => {
          console.log('Insert error', error);
          return false;
        }
      );
    });
  };

  const syncPendingRecords = useCallback(() => {
    if (syncing) return;

    setSyncing(true);

    db.transaction((tx) => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0;',
        [],
        async (_, { rows }) => {
          const pending = rows._array;

          if (pending.length === 0) {
            setSyncing(false);
            return;
          }

          for (const record of pending) {
            try {
              await axios.post(API_URL, {
                local_id: record.local_id,
                name: record.name,
                location: record.location,
                notes: record.notes,
                created_at: record.created_at,
              });

              db.transaction((innerTx) => {
                innerTx.executeSql(
                  'UPDATE surveys SET synced = 1 WHERE id = ?;',
                  [record.id]
                );
              });
            } catch (error) {
              console.log('Sync failed for record', record.id, error.message);
            }
          }

          loadRecords();
          setSyncing(false);
        },
        (_, error) => {
          console.log('Pending fetch error', error);
          setSyncing(false);
          return false;
        }
      );
    });
  }, [syncing]);

  const renderItem = ({ item }) => (
    <View style={styles.recordCard}>
      <Text style={styles.recordTitle}>{item.name}</Text>
      <Text>Location: {item.location}</Text>
      <Text>Notes: {item.notes}</Text>
      <Text>Status: {item.synced ? 'Synced' : 'Pending'}</Text>
    </View>
  );

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Network: {isOnline ? 'Online' : 'Offline'} {syncing ? '(Syncing...)' : ''}
      </Text>

      <TextInput
        style={styles.input}
        placeholder="Surveyor Name"
        value={name}
        onChangeText={setName}
      />
      <TextInput
        style={styles.input}
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />

      <Button title="Save Survey" onPress={saveRecord} />

      <View style={{ marginTop: 20 }}>
        <Button title="Manual Sync" onPress={syncPendingRecords} />
      </View>

      <FlatList
        data={records}
        keyExtractor={(item) => item.id.toString()}
        renderItem={renderItem}
        contentContainerStyle={{ paddingVertical: 20 }}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    marginTop: 30,
  },
  header: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 12,
  },
  status: {
    marginBottom: 12,
    color: '#444',
  },
  input: {
    borderWidth: 1,
    borderColor: '#bbb',
    padding: 10,
    marginBottom: 10,
    borderRadius: 6,
  },
  recordCard: {
    borderWidth: 1,
    borderColor: '#ddd',
    padding: 12,
    borderRadius: 8,
    marginBottom: 10,
  },
  recordTitle: {
    fontWeight: 'bold',
    fontSize: 16,
  },
});
