# 3. Backend API Example

This backend accepts survey records and prevents duplicates using `local_id`.

## Install

```bash
mkdir survey-server
cd survey-server
npm init -y
npm install express cors
```

---

## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = [];

app.post('/api/surveys', (req, res) => {
  const { local_id, name, location, notes, created_at } = req.body;

  if (!local_id || !name || !location) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const exists = surveys.find((s) => s.local_id === local_id);
  if (exists) {
    return res.status(200).json({ message: 'Already synced', survey: exists });
  }

  const survey = {
    id: surveys.length + 1,
    local_id,
    name,
    location,
    notes,
    created_at,
    received_at: new Date().toISOString(),
  };

  surveys.push(survey);

  res.status(201).json({
    message: 'Survey saved',
    survey,
  });
});

app.get('/api/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

