If you want a more production-style local save, here is a queue-based insert helper:

```javascript
const saveRecordWithQueue = () => {
  if (!name || !location) {
    Alert.alert('Validation', 'Name and location are required.');
    return;
  }

  const localId = `local-${Date.now()}`;
  const now = new Date().toISOString();
  const payload = JSON.stringify({
    local_id: localId,
    name,
    location,
    notes,
    created_at: now,
    updated_at: now,
  });

  db.transaction((tx) => {
    tx.executeSql(
      `INSERT INTO surveys (local_id, name, location, notes, created_at, updated_at, sync_status)
       VALUES (?, ?, ?, ?, ?, ?, 'pending');`,
      [localId, name, location, notes, now, now]
    );

    tx.executeSql(
      `INSERT INTO sync_queue (entity_type, entity_local_id, operation, payload, status, created_at)
       VALUES ('survey', ?, 'create', ?, 'pending', ?);`,
      [localId, payload, now]
    );
  }, (error) => {
    console.log('Transaction error', error);
  }, () => {
    setName('');
    setLocation('');
    setNotes('');
    loadRecords();
    if (isOnline) syncQueue();
  });
};
