# 8. Example Queue Sync Function

```javascript
const syncQueue = () => {
  if (syncing) return;
  setSyncing(true);

  db.transaction((tx) => {
    tx.executeSql(
      `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY id ASC;`,
      [],
      async (_, { rows }) => {
        const jobs = rows._array;

        for (const job of jobs) {
          try {
            const payload = JSON.parse(job.payload);

            if (job.operation === 'create' && job.entity_type === 'survey') {
              await axios.post(API_URL, payload);
            }

            db.transaction((innerTx) => {
              innerTx.executeSql(
                `UPDATE sync_queue SET status = 'done' WHERE id = ?;`,
                [job.id]
              );
              innerTx.executeSql(
                `UPDATE surveys SET sync_status = 'synced' WHERE local_id = ?;`,
                [job.entity_local_id]
              );
            });
          } catch (error) {
            db.transaction((innerTx) => {
              innerTx.executeSql(
                `UPDATE sync_queue
                 SET retry_count = retry_count + 1, last_error = ?
                 WHERE id = ?;`,
                [error.message, job.id]
              );
            });
          }
        }

        loadRecords();
        setSyncing(false);
      }
    );
  });
};
```

