      updated_at: now
    };

    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys 
          (local_id, title, latitude, longitude, notes, created_at, updated_at, synced)
         VALUES (?, ?, ?, ?, ?, ?, ?, 0)`,
        [
          localId,
          title,
          latitude,
          longitude,
          notes,
          now,
          now
        ],
        () => {
          tx.executeSql(
            `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at)
             VALUES (?, ?, ?, ?, ?)`,
            ['survey', localId, 'create', JSON.stringify(payload), now],
            () => resolve(payload),
            (_, err) => reject(err)
          );
        },
        (_, err) => reject(err)
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY created_at DESC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const markSurveySynced = (localId, serverId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1, server_id = ?, updated_at = ? WHERE local_id = ?`,
        [serverId, new Date().toISOString(), localId],
        (_, result) => resolve(result),
        (_, err) => reject(err)
      );
    });
  });
};

export const getPendingQueue = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY created_at ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const removeQueueItem = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
