## `syncService.js` — sync engine

```javascript
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { getPendingQueue, removeQueueItem, markSurveySynced } from './surveyService';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

let syncing = false;

export const syncPendingData = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const netState = await NetInfo.fetch();
    if (!netState.isConnected) {
      syncing = false;
      return;
    }

    const queue = await getPendingQueue();

    for (const item of queue) {
      const payload = JSON.parse(item.payload);

      try {
        if (item.entity_type === 'survey' && item.action === 'create') {
          const response = await axios.post(`${API_BASE_URL}/surveys`, payload);

          await markSurveySynced(payload.local_id, response.data.server_id);
          await removeQueueItem(item.id);
        }
      } catch (err) {
        console.log('Sync failed for queue item:', item.id, err.message);
      }
    }
  } finally {
    syncing = false;
  }
};

export const startSyncListener = () => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingData();
    }
  });
};
```

