export async function getDb() {
  if (dbInstance) return dbInstance;

  dbInstance = await SQLite.openDatabase({
    name: 'survey_app.db',
    location: 'default',
  });

  await dbInstance.executeSql(`
    CREATE TABLE IF NOT EXISTS surveys (
      localId TEXT PRIMARY KEY NOT NULL,
