# 6. Sync queue repository

## `src/db/syncQueueRepo.ts`

```ts
import { getDb } from './database';
import { SyncQueueItem, SyncAction } from '../types/sync';

export async function enqueueSync(
  entityLocalId: string,
  action: SyncAction,
  payload: unknown
): Promise<void> {
  const db = await getDb();
  await db.executeSql(
    `INSERT INTO sync_queue (
      entityType, entityLocalId, action, payload, createdAt, retryCount, lastError
    ) VALUES (?, ?, ?, ?, ?, 0, NULL)`,
    [
      'survey',
      entityLocalId,
      action,
      JSON.stringify(payload),
      new Date().toISOString(),
    ]
  );
}

export async function getPendingQueueItems(): Promise<SyncQueueItem[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY id ASC`
  );

  const items: SyncQueueItem[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i) as SyncQueueItem);
  }
  return items;
}

export async function removeQueueItem(id: number): Promise<void> {
  const db = await getDb();
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function incrementRetry(id: number, error: string): Promise<void> {
  const db = await getDb();
  await db.executeSql(
    `UPDATE sync_queue
     SET retryCount = retryCount + 1, lastError = ?
     WHERE id = ?`,
    [error, id]
  );
}
```

