    longitude: survey.longitude,
    createdAt: survey.createdAt,
    updatedAt: survey.updatedAt,
  });

  return response.data; // expected: { id: string, ... }
}

export async function updateSurveyRemote(survey: Survey) {
  if (!survey.serverId) {
    throw new Error('Cannot update remote survey without serverId');
  }

  const response = await apiClient.put(`/surveys/${survey.serverId}`, {
    title: survey.title,
    notes: survey.notes,
    latitude: survey.latitude,
    longitude: survey.longitude,
    updatedAt: survey.updatedAt,
  });

  return response.data;
}

export async function deleteSurveyRemote(serverId: string) {
  const response = await apiClient.delete(`/surveys/${serverId}`);
  return response.data;
}
