# 8. Sync service

This is the core logic.

## `src/services/syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingQueueItems, incrementRetry, removeQueueItem } from '../db/syncQueueRepo';
import {
  deleteSurveyPermanently,
  getSurveyByLocalId,
  markSurveyFailed,
  markSurveySynced,
} from '../db/surveyRepo';
import {
  createSurveyRemote,
  deleteSurveyRemote,
  updateSurveyRemote,
} from '../api/syncApi';
import { SyncQueueItem } from '../types/sync';

let syncInProgress = false;

export async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected;
}

export async function syncPendingData(): Promise<void> {
  if (syncInProgress) return;

  const online = await isOnline();
  if (!online) return;

  syncInProgress = true;

  try {
    const queue = await getPendingQueueItems();

    for (const item of queue) {
      try {
        await processQueueItem(item);
        if (item.id != null) {
          await removeQueueItem(item.id);
        }
      } catch (error: any) {
        if (item.id != null) {
          await incrementRetry(item.id, error?.message || 'Unknown sync error');
        }
        await markSurveyFailed(item.entityLocalId);
      }
    }
  } finally {
    syncInProgress = false;
  }
}

async function processQueueItem(item: SyncQueueItem): Promise<void> {
  const survey = await getSurveyByLocalId(item.entityLocalId);

  if (item.action === 'DELETE') {
    if (!survey) {
      if (item.id != null) {
        await removeQueueItem(item.id);
      }
      return;
    }

    if (survey.serverId) {
      await deleteSurveyRemote(survey.serverId);
    }

    await deleteSurveyPermanently(survey.localId);
    return;
  }

  if (!survey) {
    throw new Error(`Survey not found for localId ${item.entityLocalId}`);
  }

  if (item.action === 'CREATE') {
    const remote = await createSurveyRemote(survey);
    await markSurveySynced(survey.localId, remote.id);
    return;
  }

  if (item.action === 'UPDATE') {
    if (!survey.serverId) {
      const remote = await createSurveyRemote(survey);
      await markSurveySynced(survey.localId, remote.id);
      return;
    }

    await updateSurveyRemote(survey);
    await markSurveySynced(survey.localId, survey.serverId);
    return;
  }

  throw new Error(`Unsupported action ${item.action}`);
}
```

