# 12. Important improvement: deduplicate queue items

The above works, but in real use, repeated edits while offline can create many queue entries for the same record.

A better approach is:
- if a CREATE exists and user edits again, do not enqueue UPDATE separately; just keep CREATE
- if UPDATE exists already, replace payload instead of adding another UPDATE
- if DELETE happens, remove prior CREATE/UPDATE queue items and keep only DELETE

Here’s a better queue upsert strategy.

## Replace `enqueueSync` with smarter logic

```ts
import { getDb } from './database';
import { SyncAction } from '../types/sync';

export async function enqueueSyncSmart(
  entityLocalId: string,
  action: SyncAction,
  payload: unknown
): Promise<void> {
  const db = await getDb();

  const [existingResult] = await db.executeSql(
    `SELECT * FROM sync_queue
     WHERE entityType = 'survey' AND entityLocalId = ?
     ORDER BY id ASC`,
    [entityLocalId]
  );

  const existingItems = [];
  for (let i = 0; i < existingResult.rows.length; i++) {
    existingItems.push(existingResult.rows.item(i));
  }

  const payloadJson = JSON.stringify(payload);
  const now = new Date().toISOString();

  if (action === 'CREATE') {
    if (existingItems.length === 0) {
      await db.executeSql(
        `INSERT INTO sync_queue
         (entityType, entityLocalId, action, payload, createdAt, retryCount)
         VALUES ('survey', ?, 'CREATE', ?, ?, 0)`,
        [entityLocalId, payloadJson, now]
      );
    }
    return;
  }

  if (action === 'UPDATE') {
    const createItem = existingItems.find((x: any) => x.action === 'CREATE');
    if (createItem) {
      await db.executeSql(
        `UPDATE sync_queue SET payload = ? WHERE id = ?`,
        [payloadJson, createItem.id]
      );
      return;
    }

    const updateItem = existingItems.find((x: any) => x.action === 'UPDATE');
    if (updateItem) {
      await db.executeSql(
        `UPDATE sync_queue SET payload = ?, createdAt = ? WHERE id = ?`,
        [payloadJson, now, updateItem.id]
      );
      return;
    }

    await db.executeSql(
      `INSERT INTO sync_queue
       (entityType, entityLocalId, action, payload, createdAt, retryCount)
       VALUES ('survey', ?, 'UPDATE', ?, ?, 0)`,
      [entityLocalId, payloadJson, now]
    );
    return;
  }

  if (action === 'DELETE') {
    await db.executeSql(
      `DELETE FROM sync_queue WHERE entityType = 'survey' AND entityLocalId = ?`,
      [entityLocalId]
    );

    await db.executeSql(
      `INSERT INTO sync_queue
       (entityType, entityLocalId, action, payload, createdAt, retryCount)
       VALUES ('survey', ?, 'DELETE', ?, ?, 0)`,
      [entityLocalId, payloadJson, now]
    );
  }
}
```

Use `enqueueSyncSmart` instead of `enqueueSync`.

