## Merge logic sketch

```ts
import { fetchRemoteSurveys } from '../api/syncApi';
import { getDb } from '../db/database';

export async function pullRemoteChanges(lastSyncAt?: string) {
  const remoteSurveys = await fetchRemoteSurveys(lastSyncAt);
  const db = await getDb();

  for (const remote of remoteSurveys) {
    await db.executeSql(
      `INSERT OR REPLACE INTO surveys
       (localId, serverId, title, notes, latitude, longitude, createdAt, updatedAt, syncStatus, deleted)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'synced', ?)`,
      [
        remote.localId,
        remote.id,
        remote.title,
        remote.notes,
        remote.latitude,
        remote.longitude,
        remote.createdAt,
        remote.updatedAt,
        remote.deleted ? 1 : 0,
      ]
    );
  }
}
```

Then call `pullRemoteChanges()` after pushing pending queue items.

