import express from 'express';
import bodyParser from 'body-parser';
import { randomUUID } from 'crypto';

const app = express();
app.use(bodyParser.json());

const surveys: any[] = [];

app.post('/surveys', (req, res) => {
  const survey = {
    id: randomUUID(),
    ...req.body,
  };
  surveys.push(survey);
  res.json({ id: survey.id });
});

app.put('/surveys/:id', (req, res) => {
  const idx = surveys.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Not found' });

  surveys[idx] = { ...surveys[idx], ...req.body };
  res.json(surveys[idx]);
});

app.delete('/surveys/:id', (req, res) => {
  const idx = surveys.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Not found' });

  surveys.splice(idx, 1);
  res.json({ success: true });
});

app.get('/surveys', (_req, res) => {
  res.json(surveys);
});

app.listen(3000, () => {
  console.log('API running on port 3000');
});
