# 2. Client: IndexedDB local storage

## `client/src/db.js`

```javascript
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'localId' });
      surveyStore.createIndex('by_updatedAt', 'updatedAt');
      surveyStore.createIndex('by_syncStatus', 'syncStatus');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const queueStore = db.createObjectStore('syncQueue', {
        keyPath: 'queueId',
        autoIncrement: true,
      });
      queueStore.createIndex('by_createdAt', 'createdAt');
    }
  },
});

export async function saveSurveyLocally(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function getSurvey(localId) {
  const db = await dbPromise;
  return db.get('surveys', localId);
}

export async function deleteSurvey(localId) {
  const db = await dbPromise;
  await db.delete('surveys', localId);
}

export async function enqueueSyncAction(action) {
  const db = await dbPromise;
  await db.add('syncQueue', {
    ...action,
    createdAt: Date.now(),
  });
}

export async function getQueuedActions() {
  const db = await dbPromise;
  return db.getAll('syncQueue');
}

export async function removeQueuedAction(queueId) {
  const db = await dbPromise;
  await db.delete('syncQueue', queueId);
}

export async function updateSurveySyncStatus(localId, syncStatus, serverId = null, lastSyncedAt = null) {
  const db = await dbPromise;
  const survey = await db.get('surveys', localId);
  if (!survey) return;

  survey.syncStatus = syncStatus;
  if (serverId) survey.serverId = serverId;
  if (lastSyncedAt) survey.lastSyncedAt = lastSyncedAt;

  await db.put('surveys', survey);
}
