# 4. Client: Sync engine

## `client/src/sync.js`

```javascript
import {
  getQueuedActions,
  removeQueuedAction,
  updateSurveySyncStatus,
  getSurvey,
  saveSurveyLocally,
} from './db';
import { pushSurveyToServer, fetchServerSurveys } from './api';

let syncInProgress = false;

export async function syncPendingChanges() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    const queued = await getQueuedActions();

    for (const action of queued) {
      try {
        if (action.type === 'UPSERT_SURVEY') {
          const localSurvey = await getSurvey(action.localId);
          if (!localSurvey) {
            await removeQueuedAction(action.queueId);
            continue;
          }

          const result = await pushSurveyToServer(localSurvey);

          await updateSurveySyncStatus(
            localSurvey.localId,
            'synced',
            result.serverId,
            Date.now()
          );

          await removeQueuedAction(action.queueId);
        }
      } catch (err) {
        console.error('Failed syncing action', action, err);
      }
    }

    await pullLatestServerData();
  } finally {
    syncInProgress = false;
  }
}

export async function pullLatestServerData() {
  if (!navigator.onLine) return;

  try {
    const serverSurveys = await fetchServerSurveys();

    for (const serverSurvey of serverSurveys) {
      const localId = serverSurvey.localId || `server-${serverSurvey.id}`;
      const existing = await getSurvey(localId);

      if (!existing || existing.syncStatus === 'synced') {
        await saveSurveyLocally({
          ...serverSurvey,
          localId,
          serverId: serverSurvey.id,
          syncStatus: 'synced',
          lastSyncedAt: Date.now(),
        });
      }
    }
  } catch (err) {
    console.error('Pull failed', err);
  }
}

export function setupOnlineSync() {
  window.addEventListener('online', () => {
    syncPendingChanges();
  });
}
```

