# 8. Mock backend server

## `server/server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

let surveys = [];
let nextId = 1;

app.get('/surveys', (req, res) => {
  res.json(surveys);
});

app.post('/surveys/sync', (req, res) => {
  const incoming = req.body;

  let existing = null;
  if (incoming.serverId) {
    existing = surveys.find((s) => s.id === incoming.serverId);
  }

  if (!existing) {
    existing = surveys.find((s) => s.localId === incoming.localId);
  }

  if (existing) {
    if ((incoming.updatedAt || 0) >= (existing.updatedAt || 0)) {
      Object.assign(existing, incoming, { id: existing.id });
    }
    return res.json({
      success: true,
      serverId: existing.id,
      updatedAt: existing.updatedAt,
    });
  }

  const newSurvey = {
    ...incoming,
    id: nextId++,
  };

  surveys.push(newSurvey);

  res.json({
    success: true,
    serverId: newSurvey.id,
    updatedAt: newSurvey.updatedAt,
  });
});

app.listen(4000, () => {
  console.log('Server listening on http://localhost:4000');
});
