import { getDB } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey({ title, description, latitude, longitude }) {
  const db = getDB();
  const id = uuidv4();
  const updatedAt = new Date().toISOString();

  await db.executeSql(
    `INSERT INTO surveys (id, title, description, latitude, longitude, updated_at, sync_status)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [id, title, description, latitude, longitude, updatedAt, 'pending']
  );

  return {
    id,
    title,
    description,
    latitude,
    longitude,
    updated_at: updatedAt,
    sync_status: 'pending',
  };
}

export async function updateSurvey(id, updates) {
  const db = getDB();
  const updatedAt = new Date().toISOString();

  await db.executeSql(
    `UPDATE surveys
     SET title = ?, description = ?, latitude = ?, longitude = ?, updated_at = ?, sync_status = ?
     WHERE id = ?`,
    [
      updates.title,
      updates.description,
      updates.latitude,
      updates.longitude,
      updatedAt,
      'pending',
      id,
    ]
  );
}

export async function getAllSurveys() {
  const db = getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys ORDER BY updated_at DESC`);
  const rows = [];

  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }

  return rows;
}

export async function getPendingSurveys() {
  const db = getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE sync_status = 'pending'`
  );

  const rows = [];
  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }

  return rows;
}

export async function markSurveySynced(id) {
  const db = getDB();
  await db.executeSql(
    `UPDATE surveys SET sync_status = 'synced' WHERE id = ?`,
    [id]
  );
}

export async function markSurveyFailed(id) {
  const db = getDB();
  await db.executeSql(
    `UPDATE surveys SET sync_status = 'failed' WHERE id = ?`,
    [id]
  );
}
