## `syncService.js` — sync pending records
```javascript
import axios from 'axios';
import { getPendingSurveys, markSurveySynced, markSurveyFailed } from './surveyRepository';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

export async function syncPendingSurveys() {
  const pending = await getPendingSurveys();

  if (!pending.length) {
    console.log('No pending surveys to sync');
    return;
  }

  try {
    const response = await axios.post(`${API_BASE_URL}/sync`, {
      surveys: pending,
    });

    const { syncedIds, failedIds } = response.data;

    for (const id of syncedIds) {
      await markSurveySynced(id);
    }

    for (const id of failedIds) {
      await markSurveyFailed(id);
    }

    console.log('Sync complete');
  } catch (error) {
    console.error('Sync failed:', error.message);
  }
}
```

