## `server.js`
```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// In-memory store for demo purposes
const surveys = new Map();

/**
 * Expected payload:
 * {
 *   surveys: [
 *     {
 *       id,
 *       title,
 *       description,
 *       latitude,
 *       longitude,
 *       updated_at,
 *       sync_status
 *     }
 *   ]
 * }
 */
app.post('/sync', (req, res) => {
  const incoming = req.body.surveys || [];
  const syncedIds = [];
  const failedIds = [];

  for (const survey of incoming) {
    try {
      const existing = surveys.get(survey.id);

      // Last-write-wins conflict strategy
      if (!existing || new Date(survey.updated_at) >= new Date(existing.updated_at)) {
        surveys.set(survey.id, {
          id: survey.id,
          title: survey.title,
          description: survey.description,
          latitude: survey.latitude,
          longitude: survey.longitude,
          updated_at: survey.updated_at,
        });
      }

      syncedIds.push(survey.id);
    } catch (err) {
      failedIds.push(survey.id);
    }
  }

  res.json({
    syncedIds,
    failedIds,
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

