  syncStatus: 'synced' | 'pending';
};
```

A sync queue item:

```ts
type SyncQueueItem = {
  id?: number;
  recordId: string;
  operation: 'upsert' | 'delete';
  payload: SurveyRecord;
  enqueuedAt: string;
};
```

