# 4. Local data service

## `surveyService.js`

```javascript
import { dbPromise } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function saveSurveyLocally(data) {
  const db = await dbPromise;
  const now = new Date().toISOString();

  const record = {
    id: data.id || uuidv4(),
    siteName: data.siteName,
    inspector: data.inspector,
    latitude: data.latitude,
    longitude: data.longitude,
    notes: data.notes || '',
    createdAt: data.createdAt || now,
    updatedAt: now,
    deleted: false,
    syncStatus: 'pending',
  };

  await db.put('surveys', record);

  await db.add('syncQueue', {
    recordId: record.id,
    operation: 'upsert',
    payload: record,
    enqueuedAt: now,
  });

  return record;
}

export async function deleteSurveyLocally(id) {
  const db = await dbPromise;
  const existing = await db.get('surveys', id);
  if (!existing) return;

  const now = new Date().toISOString();
  const deletedRecord = {
    ...existing,
    deleted: true,
    updatedAt: now,
    syncStatus: 'pending',
  };

  await db.put('surveys', deletedRecord);

  await db.add('syncQueue', {
    recordId: id,
    operation: 'delete',
    payload: deletedRecord,
    enqueuedAt: now,
  });
}

export async function markSurveySynced(id) {
  const db = await dbPromise;
  const record = await db.get('surveys', id);
  if (!record) return;

  await db.put('surveys', {
    ...record,
    syncStatus: 'synced',
  });
}

export async function getPendingQueueItems() {
  const db = await dbPromise;
  return db.getAll('syncQueue');
}

export async function removeQueueItem(queueId) {
  const db = await dbPromise;
  await db.delete('syncQueue', queueId);
}

export async function getLastSyncTime() {
  const db = await dbPromise;
  const meta = await db.get('meta', 'lastSyncTime');
  return meta?.value || null;
}

export async function setLastSyncTime(value) {
  const db = await dbPromise;
  await db.put('meta', { key: 'lastSyncTime', value });
}

export async function upsertServerRecord(record) {
  const db = await dbPromise;
  const local = await db.get('surveys', record.id);

  // Simple conflict strategy:
  // If local record is pending, keep local version.
  if (local && local.syncStatus === 'pending') {
    return;
  }

  await db.put('surveys', {
    ...record,
    syncStatus: 'synced',
  });
}
```

