## `syncService.js`

```javascript
import {
  getPendingQueueItems,
  removeQueueItem,
  markSurveySynced,
  getLastSyncTime,
  setLastSyncTime,
  upsertServerRecord,
} from './surveyService';

const API_BASE = 'http://localhost:4000/api';

export async function syncAll() {
  if (!navigator.onLine) {
    console.log('Offline, skipping sync');
    return;
  }

  try {
    await pushLocalChanges();
    await pullRemoteChanges();
    await setLastSyncTime(new Date().toISOString());
    console.log('Sync complete');
  } catch (err) {
    console.error('Sync failed:', err);
  }
}

async function pushLocalChanges() {
  const queueItems = await getPendingQueueItems();

  for (const item of queueItems) {
    try {
      const response = await fetch(`${API_BASE}/surveys/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(item),
      });

      if (!response.ok) {
        throw new Error(`Push failed for record ${item.recordId}`);
      }

      await markSurveySynced(item.recordId);
      await removeQueueItem(item.id);
    } catch (err) {
      console.error('Error syncing queue item:', item, err);
      // Stop here to preserve order and retry later
      break;
    }
  }
}

async function pullRemoteChanges() {
  const lastSyncTime = await getLastSyncTime();
  const url = new URL(`${API_BASE}/surveys/changes`);

  if (lastSyncTime) {
    url.searchParams.set('since', lastSyncTime);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    throw new Error('Failed to pull remote changes');
  }

  const records = await response.json();

  for (const record of records) {
    await upsertServerRecord(record);
  }
}
```

