# 8. Backend API

Now the server side.

## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

// Seed example
const seedId = uuidv4();
surveys.set(seedId, {
  id: seedId,
  siteName: 'Initial Site',
  inspector: 'Admin',
  latitude: 10.123,
  longitude: 20.456,
  notes: 'Seed record',
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  deleted: false,
});

app.post('/api/surveys/sync', (req, res) => {
  const item = req.body;
  const incoming = item.payload;

  if (!incoming || !incoming.id) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  const existing = surveys.get(incoming.id);

  // Last-write-wins conflict strategy
  if (!existing || new Date(incoming.updatedAt) >= new Date(existing.updatedAt)) {
    surveys.set(incoming.id, {
      ...incoming,
      deleted: item.operation === 'delete' ? true : incoming.deleted || false,
      updatedAt: incoming.updatedAt || new Date().toISOString(),
    });
  }

  return res.json({ success: true });
});

app.get('/api/surveys/changes', (req, res) => {
  const since = req.query.since;
  let results = Array.from(surveys.values());

  if (since) {
    const sinceDate = new Date(since);
    results = results.filter(r => new Date(r.updatedAt) > sinceDate);
  }

  res.json(results);
});

app.get('/api/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(4000, () => {
  console.log('Server listening on http://localhost:4000');
});
