## `surveyRepository.ts` — local CRUD

```ts
// surveyRepository.ts
import { getDb } from './db';

export type SurveyRecord = {
  id: string;
  title: string;
  notes: string;
  latitude: number | null;
  longitude: number | null;
  updatedAt: string;
  deleted: number;
  dirty: number;
};

const db = getDb();

export function getAllSurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
}

export function getDirtySurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(
    `SELECT * FROM surveys WHERE dirty = 1`
  );
}

export function upsertSurveyLocal(record: SurveyRecord) {
  db.runSync(
    `
    INSERT INTO surveys (id, title, notes, latitude, longitude, updatedAt, deleted, dirty)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      title = excluded.title,
      notes = excluded.notes,
      latitude = excluded.latitude,
      longitude = excluded.longitude,
      updatedAt = excluded.updatedAt,
      deleted = excluded.deleted,
      dirty = excluded.dirty
    `,
    [
      record.id,
      record.title,
      record.notes,
      record.latitude,
      record.longitude,
      record.updatedAt,
      record.deleted,
      record.dirty,
    ]
  );
}

export function markSurveySynced(id: string) {
  db.runSync(`UPDATE surveys SET dirty = 0 WHERE id = ?`, [id]);
}

export function markManySynced(ids: string[]) {
  if (ids.length === 0) return;
  const placeholders = ids.map(() => '?').join(',');
  db.runSync(
    `UPDATE surveys SET dirty = 0 WHERE id IN (${placeholders})`,
    ids
  );
}

export function softDeleteSurvey(id: string) {
  db.runSync(
    `UPDATE surveys SET deleted = 1, dirty = 1, updatedAt = ? WHERE id = ?`,
    [new Date().toISOString(), id]
  );
}

export function getLastUpdatedAt(): string {
  const row = db.getFirstSync<{ lastUpdatedAt: string }>(
    `SELECT MAX(updatedAt) as lastUpdatedAt FROM surveys`
  );
  return row?.lastUpdatedAt || '1970-01-01T00:00:00.000Z';
}
```

