## `syncService.ts` — push/pull sync logic

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import {
  getDirtySurveys,
  markManySynced,
  upsertSurveyLocal,
  getLastUpdatedAt,
  SurveyRecord,
} from './surveyRepository';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

export async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
}

export async function pushLocalChanges() {
  const dirtyRecords = getDirtySurveys();
  if (dirtyRecords.length === 0) return;

  const response = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ records: dirtyRecords }),
  });

  if (!response.ok) {
    throw new Error('Push sync failed');
  }

  const data = await response.json();
  markManySynced(data.syncedIds || []);
}

export async function pullRemoteChanges() {
  const since = getLastUpdatedAt();

  const response = await fetch(
    `${API_BASE}/sync/pull?since=${encodeURIComponent(since)}`
  );

  if (!response.ok) {
    throw new Error('Pull sync failed');
  }

  const data = await response.json();

  const records: SurveyRecord[] = data.records || [];
  for (const record of records) {
    upsertSurveyLocal({
      ...record,
      dirty: 0,
    });
  }
}

export async function syncAll() {
  const online = await isOnline();
  if (!online) return;

  await pushLocalChanges();
  await pullRemoteChanges();
}
```

