// App.tsx
import React, { useEffect, useState } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import { v4 as uuidv4 } from 'uuid';
import * as Location from 'expo-location';
import NetInfo from '@react-native-community/netinfo';

import { initDb } from './db';
import {
  getAllSurveys,
  upsertSurveyLocal,
  softDeleteSurvey,
  SurveyRecord,
} from './surveyRepository';
import { syncAll } from './syncService';

export default function App() {
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [online, setOnline] = useState(false);

  useEffect(() => {
    initDb();
    refresh();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const isConnected = !!state.isConnected && !!state.isInternetReachable;
      setOnline(isConnected);

      if (isConnected) {
        syncAll()
          .then(refresh)
          .catch((err) => console.error('Auto-sync failed:', err));
      }
    });

    return () => unsubscribe();
  }, []);

  function refresh() {
    setSurveys(getAllSurveys());
  }

  async function addSurvey() {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    let latitude: number | null = null;
    let longitude: number | null = null;

    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status === 'granted') {
        const loc = await Location.getCurrentPositionAsync({});
        latitude = loc.coords.latitude;
        longitude = loc.coords.longitude;
      }
    } catch (e) {
      console.warn('Location unavailable', e);
    }

    const record: SurveyRecord = {
      id: uuidv4(),
      title,
      notes,
      latitude,
      longitude,
      updatedAt: new Date().toISOString(),
      deleted: 0,
      dirty: 1,
    };

    upsertSurveyLocal(record);
    setTitle('');
    setNotes('');
    refresh();

    if (online) {
      try {
        await syncAll();
        refresh();
      } catch (e) {
        console.error('Sync after add failed', e);
      }
    }
  }

  async function deleteSurvey(id: string) {
    softDeleteSurvey(id);
    refresh();

    if (online) {
      try {
        await syncAll();
        refresh();
      } catch (e) {
        console.error('Sync after delete failed', e);
      }
    }
  }

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Status: {online ? 'Online' : 'Offline'}
      </Text>

      <TextInput
        style={styles.input}
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
      />

      <TextInput
        style={[styles.input, styles.notes]}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        multiline
      />

      <Button title="Add Survey" onPress={addSurvey} />
      <View style={{ height: 12 }} />
      <Button
        title="Sync Now"
        onPress={async () => {
          try {
            await syncAll();
            refresh();
            Alert.alert('Success', 'Sync completed');
          } catch (e) {
            Alert.alert('Sync failed', String(e));
          }
        }}
      />

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.cardTitle}>{item.title}</Text>
            <Text>{item.notes}</Text>
            <Text>
              {item.latitude && item.longitude
                ? `${item.latitude}, ${item.longitude}`
                : 'No GPS'}
            </Text>
            <Text>Updated: {item.updatedAt}</Text>
            <Text>{item.dirty ? 'Pending sync' : 'Synced'}</Text>
            <Button title="Delete" onPress={() => deleteSurvey(item.id)} />
          </View>
        )}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
