## `server.js`

This example uses in-memory storage for simplicity. In production, use PostgreSQL, MySQL, or MongoDB.

```js
// server.js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

/**
 * In production, replace this with a real database.
 * Keyed by record id.
 */
const surveys = new Map();

/**
 * Push local dirty records from client to server.
 * Last-write-wins using updatedAt.
 */
app.post('/sync/push', (req, res) => {
  const records = req.body.records || [];
  const syncedIds = [];

  for (const incoming of records) {
    const existing = surveys.get(incoming.id);

    if (!existing) {
      surveys.set(incoming.id, {
        id: incoming.id,
        title: incoming.title,
        notes: incoming.notes,
        latitude: incoming.latitude,
        longitude: incoming.longitude,
        updatedAt: incoming.updatedAt,
        deleted: incoming.deleted || 0,
      });
      syncedIds.push(incoming.id);
      continue;
    }

    const incomingTime = new Date(incoming.updatedAt).getTime();
    const existingTime = new Date(existing.updatedAt).getTime();

    if (incomingTime >= existingTime) {
      surveys.set(incoming.id, {
        id: incoming.id,
        title: incoming.title,
        notes: incoming.notes,
        latitude: incoming.latitude,
        longitude: incoming.longitude,
        updatedAt: incoming.updatedAt,
        deleted: incoming.deleted || 0,
      });
      syncedIds.push(incoming.id);
    } else {
      // server has newer version; do not overwrite
    }
  }

  res.json({ syncedIds });
});

/**
 * Pull records changed since a timestamp.
 */
app.get('/sync/pull', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const sinceTime = new Date(since).getTime();

  const records = Array.from(surveys.values()).filter((record) => {
    return new Date(record.updatedAt).getTime() > sinceTime;
  });

  res.json({ records });
});

app.get('/health', (_, res) => {
  res.json({ ok: true });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Survey sync server running on port ${PORT}`);
});
```

