# 6. Survey local CRUD service

## `services/surveyService.js`

```javascript
import { getDb } from '../db/database';

function generateId() {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function getAllSurveys() {
  const db = getDb();
  return db.getAllSync(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updated_at DESC`
  );
}

export function getSurveyById(id) {
  const db = getDb();
  return db.getFirstSync(`SELECT * FROM surveys WHERE id = ?`, [id]);
}

export function createSurvey({ title, location, notes }) {
  const db = getDb();
  const id = generateId();
  const now = Date.now();

  const survey = {
    id,
    server_id: null,
    title,
    location: location || '',
    notes: notes || '',
    updated_at: now,
    sync_status: 'pending',
    deleted: 0,
  };

  db.withTransactionSync(() => {
    db.runSync(
      `INSERT INTO surveys (id, server_id, title, location, notes, updated_at, sync_status, deleted)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        survey.id,
        survey.server_id,
        survey.title,
        survey.location,
        survey.notes,
        survey.updated_at,
        survey.sync_status,
        survey.deleted,
      ]
    );

    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        survey.id,
        'create',
        JSON.stringify(survey),
        now,
      ]
    );
  });

  return survey;
}

export function updateSurvey(id, updates) {
  const db = getDb();
  const existing = getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const now = Date.now();
  const updated = {
    ...existing,
    ...updates,
    updated_at: now,
    sync_status: 'pending',
  };

  db.withTransactionSync(() => {
    db.runSync(
      `UPDATE surveys
       SET title = ?, location = ?, notes = ?, updated_at = ?, sync_status = ?
       WHERE id = ?`,
      [
        updated.title,
        updated.location,
        updated.notes,
        updated.updated_at,
        updated.sync_status,
        id,
      ]
    );

    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        id,
        'update',
        JSON.stringify(updated),
        now,
      ]
    );
  });

  return updated;
}

export function deleteSurvey(id) {
  const db = getDb();
  const existing = getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const now = Date.now();
  const deletedRecord = {
    ...existing,
    deleted: 1,
    updated_at: now,
    sync_status: 'pending',
  };

  db.withTransactionSync(() => {
    db.runSync(
      `UPDATE surveys
       SET deleted = 1, updated_at = ?, sync_status = ?
       WHERE id = ?`,
      [now, 'pending', id]
    );

    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        id,
        'delete',
        JSON.stringify(deletedRecord),
        now,
      ]
    );
  });

  return true;
}
```

