# 7. Sync service

This processes queued operations in order.

## `services/syncService.js`

```javascript
import { getDb } from '../db/database';
import {
  createSurveyRemote,
  updateSurveyRemote,
  deleteSurveyRemote,
} from './api';

let syncing = false;

export async function syncPendingChanges() {
  if (syncing) return;
  syncing = true;

  const db = getDb();

  try {
    const queueItems = db.getAllSync(
      `SELECT * FROM sync_queue
       WHERE processed = 0
       ORDER BY created_at ASC`
    );

    for (const item of queueItems) {
      const payload = JSON.parse(item.payload);
      const localSurvey = db.getFirstSync(
        `SELECT * FROM surveys WHERE id = ?`,
        [item.entity_id]
      );

      try {
        if (item.entity_type === 'survey') {
          if (item.action === 'create') {
            const remote = await createSurveyRemote({
              title: payload.title,
              location: payload.location,
              notes: payload.notes,
              client_id: payload.id,
              updated_at: payload.updated_at,
            });

            db.withTransactionSync(() => {
              db.runSync(
                `UPDATE surveys
                 SET server_id = ?, sync_status = ?
                 WHERE id = ?`,
                [remote.id, 'synced', payload.id]
              );

              db.runSync(
                `UPDATE sync_queue SET processed = 1 WHERE id = ?`,
                [item.id]
              );
            });
          }

          if (item.action === 'update') {
            if (!localSurvey?.server_id) {
              continue;
            }

            await updateSurveyRemote(localSurvey.server_id, {
              title: payload.title,
              location: payload.location,
              notes: payload.notes,
              updated_at: payload.updated_at,
            });

            db.withTransactionSync(() => {
              db.runSync(
                `UPDATE surveys SET sync_status = ? WHERE id = ?`,
                ['synced', payload.id]
              );

              db.runSync(
                `UPDATE sync_queue SET processed = 1 WHERE id = ?`,
                [item.id]
              );
            });
          }

          if (item.action === 'delete') {
            if (localSurvey?.server_id) {
              await deleteSurveyRemote(localSurvey.server_id);
            }

            db.withTransactionSync(() => {
              db.runSync(
                `DELETE FROM surveys WHERE id = ?`,
                [payload.id]
              );

              db.runSync(
                `UPDATE sync_queue SET processed = 1 WHERE id = ?`,
                [item.id]
              );
            });
          }
        }
      } catch (err) {
        console.error('Failed to sync queue item', item.id, err);
      }
    }
  } finally {
    syncing = false;
  }
}
```

