# 13. Better sync queue compaction example

Here’s an improved helper to avoid excessive queue growth.

## Add to `services/surveyService.js`

```javascript
function enqueueOrMerge(entityId, action, payload) {
  const db = getDb();

  const pending = db.getAllSync(
    `SELECT * FROM sync_queue
     WHERE entity_id = ? AND entity_type = 'survey' AND processed = 0
     ORDER BY created_at ASC`,
    [entityId]
  );

  const now = Date.now();

  if (pending.length === 0) {
    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      ['survey', entityId, action, JSON.stringify(payload), now]
    );
    return;
  }

  const first = pending[0];

  if (first.action === 'create' && action === 'update') {
    db.runSync(
      `UPDATE sync_queue SET payload = ? WHERE id = ?`,
      [JSON.stringify(payload), first.id]
    );
    return;
  }

  if (action === 'delete') {
    db.runSync(
      `DELETE FROM sync_queue WHERE entity_id = ? AND entity_type = 'survey' AND processed = 0`,
      [entityId]
    );

    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      ['survey', entityId, 'delete', JSON.stringify(payload), now]
    );
    return;
  }

  db.runSync(
    `INSERT INTO sync_queue (entity_type, entity_id, action, payload, created_at, processed)
     VALUES (?, ?, ?, ?, ?, 0)`,
    ['survey', entityId, action, JSON.stringify(payload), now]
  );
}
```

Then replace direct queue inserts in create/update/delete with `enqueueOrMerge(...)`.

