## `surveyService.js` — local CRUD + queueing

```javascript
import { db } from "./db";
import { v4 as uuidv4 } from "uuid";

export async function createSurvey(data) {
  const now = new Date().toISOString();

  const survey = {
    id: uuidv4(),
    title: data.title || "",
    notes: data.notes || "",
    latitude: data.latitude || null,
    longitude: data.longitude || null,
    photoUri: data.photoUri || null,
    deleted: false,
    version: 1,
    updatedAt: now,
    serverUpdatedAt: null,
    syncStatus: "pending"
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(survey);
    await db.syncQueue.add({
      entityId: survey.id,
      operation: "upsert",
      createdAt: now
    });
  });

  return survey;
}

export async function updateSurvey(id, updates) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const updated = {
    ...existing,
    ...updates,
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
    syncStatus: "pending"
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(updated);
    await db.syncQueue.add({
      entityId: id,
      operation: "upsert",
      createdAt: updated.updatedAt
    });
  });

  return updated;
}

export async function deleteSurvey(id) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const updated = {
    ...existing,
    deleted: true,
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
    syncStatus: "pending"
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(updated);
    await db.syncQueue.add({
      entityId: id,
      operation: "delete",
      createdAt: updated.updatedAt
    });
  });
}

export async function listSurveys() {
  return db.surveys.where("deleted").equals(false).toArray();
}

export async function listPendingSurveys() {
  return db.surveys.where("syncStatus").equals("pending").toArray();
}
