## `syncService.js` — sync engine

This:

- pushes local pending changes
- pulls remote changes since last sync
- retries when online again

```javascript
import { db } from "./db";

const API_BASE = "http://localhost:4000";

async function getLastSyncTime() {
  const record = await db.meta.get("lastSyncTime");
  return record?.value || null;
}

async function setLastSyncTime(value) {
  await db.meta.put({ key: "lastSyncTime", value });
}

export async function pushPendingChanges() {
  const queue = await db.syncQueue.orderBy("createdAt").toArray();

  for (const item of queue) {
    const survey = await db.surveys.get(item.entityId);
    if (!survey) {
      await db.syncQueue.delete(item.id);
      continue;
    }

    try {
      const response = await fetch(`${API_BASE}/surveys/sync`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!response.ok) {
        throw new Error(`Push failed: ${response.status}`);
      }

      const serverSurvey = await response.json();

      await db.transaction("rw", db.surveys, db.syncQueue, async () => {
        await db.surveys.put({
          ...survey,
          ...serverSurvey,
          syncStatus: "synced"
        });
        await db.syncQueue.delete(item.id);
      });
    } catch (err) {
      await db.surveys.update(survey.id, { syncStatus: "failed" });
      console.error("Push error", err);
      break;
    }
  }
}

export async function pullRemoteChanges() {
  const lastSyncTime = await getLastSyncTime();

  const url = new URL(`${API_BASE}/surveys`);
  if (lastSyncTime) {
    url.searchParams.set("since", lastSyncTime);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    throw new Error("Pull failed");
  }

  const remoteSurveys = await response.json();

  await db.transaction("rw", db.surveys, async () => {
    for (const remote of remoteSurveys) {
      const local = await db.surveys.get(remote.id);

      if (!local) {
        await db.surveys.put({
          ...remote,
          syncStatus: "synced"
        });
        continue;
      }

      // Simple conflict rule:
      // If local is pending and newer, keep local.
      // Otherwise accept server.
      const localPending = local.syncStatus === "pending" || local.syncStatus === "failed";
      const localNewer =
        new Date(local.updatedAt).getTime() > new Date(remote.updatedAt).getTime();

      if (localPending && localNewer) {
        continue;
      }

      await db.surveys.put({
        ...local,
        ...remote,
        syncStatus: "synced"
      });
    }
  });

  await setLastSyncTime(new Date().toISOString());
}

export async function syncAll() {
  if (!navigator.onLine) return;

  try {
    await pushPendingChanges();
    await pullRemoteChanges();

    const failed = await db.surveys.where("syncStatus").equals("failed").toArray();
    for (const item of failed) {
      await db.surveys.update(item.id, { syncStatus: "pending" });
      await db.syncQueue.add({
        entityId: item.id,
        operation: item.deleted ? "delete" : "upsert",
        createdAt: new Date().toISOString()
      });
    }
  } catch (err) {
    console.error("Sync failed", err);
  }
}

export function setupAutoSync() {
  window.addEventListener("online", () => {
    console.log("Back online, syncing...");
    syncAll();
  });

  setInterval(() => {
    if (navigator.onLine) {
      syncAll();
    }
  }, 30000);
}
```

