## `server.js`

This is a simple in-memory backend. In production, replace with PostgreSQL / MongoDB.

```javascript
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * POST /surveys/sync
 * Upsert survey from client
 */
app.post("/surveys/sync", (req, res) => {
  const incoming = req.body;
  const existing = surveys.get(incoming.id);

  if (!existing) {
    const saved = {
      ...incoming,
      serverUpdatedAt: new Date().toISOString()
    };
    surveys.set(incoming.id, saved);
    return res.json(saved);
  }

  const existingTime = new Date(existing.updatedAt).getTime();
  const incomingTime = new Date(incoming.updatedAt).getTime();

  // Last-write-wins strategy
  if (incomingTime >= existingTime) {
    const saved = {
      ...existing,
      ...incoming,
      serverUpdatedAt: new Date().toISOString()
    };
    surveys.set(incoming.id, saved);
    return res.json(saved);
  }

  return res.json(existing);
});

/**
 * GET /surveys?since=timestamp
 */
app.get("/surveys", (req, res) => {
  const since = req.query.since ? new Date(req.query.since).getTime() : 0;

  const result = Array.from(surveys.values()).filter((s) => {
    const updated = new Date(s.serverUpdatedAt || s.updatedAt).getTime();
    return updated > since;
  });

  res.json(result);
});

app.listen(4000, () => {
  console.log("Sync server running on http://localhost:4000");
});
```

