# 3) Survey repository

## `src/db/surveyRepo.ts`

```ts
import { getDb } from './database';
import { Survey } from '../types/survey';

export const surveyRepo = {
  getAll(): Survey[] {
    const db = getDb();
    return db.getAllSync<Survey>(
      `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
    );
  },

  getById(id: string): Survey | null {
    const db = getDb();
    const row = db.getFirstSync<Survey>(
      `SELECT * FROM surveys WHERE id = ?`,
      [id]
    );
    return row ?? null;
  },

  upsert(survey: Survey) {
    const db = getDb();
    db.runSync(
      `
      INSERT INTO surveys (
        id, title, notes, latitude, longitude,
        createdAt, updatedAt, deletedAt, syncStatus
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        title = excluded.title,
        notes = excluded.notes,
        latitude = excluded.latitude,
        longitude = excluded.longitude,
        createdAt = excluded.createdAt,
        updatedAt = excluded.updatedAt,
        deletedAt = excluded.deletedAt,
        syncStatus = excluded.syncStatus
      `,
      [
        survey.id,
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.createdAt,
        survey.updatedAt,
        survey.deletedAt,
        survey.syncStatus,
      ]
    );
  },

  markDeleted(id: string, deletedAt: string) {
    const db = getDb();
    db.runSync(
      `
      UPDATE surveys
      SET deletedAt = ?, updatedAt = ?, syncStatus = 'pending'
      WHERE id = ?
      `,
      [deletedAt, deletedAt, id]
    );
  },

  markSyncStatus(id: string, syncStatus: 'synced' | 'pending' | 'failed') {
    const db = getDb();
    db.runSync(
      `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
      [syncStatus, id]
    );
  },

  removeHardDeleted(id: string) {
    const db = getDb();
    db.runSync(`DELETE FROM surveys WHERE id = ?`, [id]);
  },
};
```

