# 4) Sync queue repository

## `src/db/syncRepo.ts`

```ts
import { getDb } from './database';
import { SyncQueueItem } from '../types/survey';

export const syncRepo = {
  enqueue(item: SyncQueueItem) {
    const db = getDb();
    db.runSync(
      `
      INSERT INTO sync_queue (
        id, entityType, entityId, action, payload,
        createdAt, retryCount, lastError
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `,
      [
        item.id,
        item.entityType,
        item.entityId,
        item.action,
        item.payload,
        item.createdAt,
        item.retryCount,
        item.lastError,
      ]
    );
  },

  getPending(limit = 50): SyncQueueItem[] {
    const db = getDb();
    return db.getAllSync<SyncQueueItem>(
      `
      SELECT * FROM sync_queue
      ORDER BY createdAt ASC
      LIMIT ?
      `,
      [limit]
    );
  },

  remove(id: string) {
    const db = getDb();
    db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
  },

  incrementRetry(id: string, error: string) {
    const db = getDb();
    db.runSync(
      `
      UPDATE sync_queue
      SET retryCount = retryCount + 1,
          lastError = ?
      WHERE id = ?
      `,
      [error, id]
    );
  },

  hasPendingForEntity(entityId: string): boolean {
    const db = getDb();
    const row = db.getFirstSync<{ count: number }>(
      `SELECT COUNT(*) as count FROM sync_queue WHERE entityId = ?`,
      [entityId]
    );
    return (row?.count ?? 0) > 0;
  },
};
```

