# 6) Sync engine

This is the heart of the offline-first behavior.

## `src/sync/syncEngine.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { surveyRepo } from '../db/surveyRepo';
import { syncRepo } from '../db/syncRepo';
import { pullSurveys, pushSurveyCreateOrUpdate, pushSurveyDelete } from './api';
import { Survey, SyncQueueItem } from '../types/survey';

let isSyncing = false;
let lastPulledAt: string | null = null;

function shouldReplaceLocal(local: Survey | null, remote: Survey): boolean {
  if (!local) return true;

  // Simple conflict strategy: latest updatedAt wins
  return new Date(remote.updatedAt).getTime() > new Date(local.updatedAt).getTime();
}

async function processQueueItem(item: SyncQueueItem) {
  const payload = JSON.parse(item.payload);

  if (item.entityType === 'survey') {
    if (item.action === 'create' || item.action === 'update') {
      await pushSurveyCreateOrUpdate(payload as Survey);
      surveyRepo.markSyncStatus(item.entityId, 'synced');
      syncRepo.remove(item.id);
      return;
    }

    if (item.action === 'delete') {
      await pushSurveyDelete(item.entityId);
      surveyRepo.removeHardDeleted(item.entityId);
      syncRepo.remove(item.id);
      return;
    }
  }

  throw new Error(`Unsupported queue item: ${item.entityType}/${item.action}`);
}

export async function syncNow() {
  if (isSyncing) return;
  isSyncing = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    // 1. Push local changes
    const pending = syncRepo.getPending(100);
    for (const item of pending) {
      try {
        await processQueueItem(item);
      } catch (err: any) {
        syncRepo.incrementRetry(item.id, err?.message ?? 'Unknown sync error');
        surveyRepo.markSyncStatus(item.entityId, 'failed');
      }
    }

    // 2. Pull remote changes
    const remoteSurveys = await pullSurveys(lastPulledAt ?? undefined);

    for (const remote of remoteSurveys) {
      const local = surveyRepo.getById(remote.id);

      // If local has pending changes, skip overwrite for now
      const localHasPending = syncRepo.hasPendingForEntity(remote.id);
      if (localHasPending) continue;

      if (shouldReplaceLocal(local, remote)) {
        surveyRepo.upsert({
          ...remote,
          syncStatus: 'synced',
        });
      }
    }

    lastPulledAt = new Date().toISOString();
  } finally {
    isSyncing = false;
  }
}
```

