# 7) Local mutation service

This ensures all writes are local-first and queued for sync.

## `src/db/localSurveyService.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import { surveyRepo } from './surveyRepo';
import { syncRepo } from './syncRepo';
import { Survey, SyncAction } from '../types/survey';

function enqueueSurveyAction(survey: Survey, action: SyncAction) {
  syncRepo.enqueue({
    id: uuidv4(),
    entityType: 'survey',
    entityId: survey.id,
    action,
    payload: JSON.stringify(survey),
    createdAt: new Date().toISOString(),
    retryCount: 0,
    lastError: null,
  });
}

export const localSurveyService = {
  create(input: {
    title: string;
    notes: string;
    latitude?: number | null;
    longitude?: number | null;
  }): Survey {
    const now = new Date().toISOString();

    const survey: Survey = {
      id: uuidv4(),
      title: input.title,
      notes: input.notes,
      latitude: input.latitude ?? null,
      longitude: input.longitude ?? null,
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
      syncStatus: 'pending',
    };

    surveyRepo.upsert(survey);
    enqueueSurveyAction(survey, 'create');
    return survey;
  },

  update(
    id: string,
    updates: Partial<Pick<Survey, 'title' | 'notes' | 'latitude' | 'longitude'>>
  ): Survey | null {
    const existing = surveyRepo.getById(id);
    if (!existing || existing.deletedAt) return null;

    const updated: Survey = {
      ...existing,
      ...updates,
      updatedAt: new Date().toISOString(),
      syncStatus: 'pending',
    };

    surveyRepo.upsert(updated);
    enqueueSurveyAction(updated, 'update');
    return updated;
  },

  delete(id: string): boolean {
    const existing = surveyRepo.getById(id);
    if (!existing) return false;

    const deletedAt = new Date().toISOString();
    surveyRepo.markDeleted(id, deletedAt);

    const deletedSurvey: Survey = {
      ...existing,
      deletedAt,
      updatedAt: deletedAt,
      syncStatus: 'pending',
    };

    enqueueSurveyAction(deletedSurvey, 'delete');
    return true;
  },
};
```

