import React, { useEffect, useState } from 'react';
import { View, TextInput, Button, Alert } from 'react-native';
import { surveyRepo } from '../db/surveyRepo';
import { localSurveyService } from '../db/localSurveyService';
import { syncNow } from '../sync/syncEngine';

export function SurveyFormScreen({ route, navigation }: any) {
  const id = route.params?.id;

  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (id) {
      const survey = surveyRepo.getById(id);
      if (survey) {
        setTitle(survey.title);
        setNotes(survey.notes);
      }
    }
  }, [id]);

  const save = async () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    if (id) {
      localSurveyService.update(id, { title, notes });
    } else {
      localSurveyService.create({ title, notes });
    }

    await syncNow();
    navigation.goBack();
  };

  const remove = async () => {
    if (!id) return;
    localSurveyService.delete(id);
    await syncNow();
    navigation.goBack();
  };

  return (
    <View style={{ flex: 1, padding: 16, gap: 12 }}>
      <TextInput
        placeholder="Survey title"
        value={title}
