# Example: queue deduplication improvement

You can replace enqueue logic with a smarter version:

```ts
import { getDb } from './database';
import { SyncQueueItem } from '../types/survey';

export function enqueueOrReplace(item: SyncQueueItem) {
  const db = getDb();

  const existing = db.getFirstSync<SyncQueueItem>(
    `
    SELECT * FROM sync_queue
    WHERE entityType = ? AND entityId = ?
    ORDER BY createdAt DESC
    LIMIT 1
    `,
    [item.entityType, item.entityId]
  );

  if (existing && item.action === 'update' && existing.action === 'update') {
    db.runSync(
      `
      UPDATE sync_queue
      SET payload = ?, createdAt = ?, lastError = NULL
      WHERE id = ?
      `,
      [item.payload, item.createdAt, existing.id]
    );
    return;
  }

  db.runSync(
    `
    INSERT INTO sync_queue (
      id, entityType, entityId, action, payload,
      createdAt, retryCount, lastError
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.action,
      item.payload,
      item.createdAt,
      item.retryCount,
      item.lastError,
    ]
  );
}
```

