```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        location TEXT,
        notes TEXT,
        updatedAt INTEGER NOT NULL,
        synced INTEGER NOT NULL
      );`
    );
  });
};

export const insertSurvey = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
          (id, title, location, notes, updatedAt, synced)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          survey.synced ? 1 : 0
        ],
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updatedAt DESC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE synced = 0 ORDER BY updatedAt ASC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const markSurveysSynced = (ids) => {
  if (!ids.length) return Promise.resolve();

  const placeholders = ids.map(() => '?').join(',');
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id IN (${placeholders});`,
        ids,
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};
```

