## `syncService.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getUnsyncedSurveys, markSurveysSynced } from './db';

const API_URL = 'http://YOUR_SERVER_IP:3000/api/sync';

let syncing = false;

export const syncSurveys = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const netState = await NetInfo.fetch();
    if (!netState.isConnected) {
      syncing = false;
      return;
    }

    const unsynced = await getUnsyncedSurveys();
    if (!unsynced.length) {
      syncing = false;
      return;
    }

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ surveys: unsynced })
    });

    if (!response.ok) {
      throw new Error(`Sync failed: ${response.status}`);
    }

    const data = await response.json();

    if (data.syncedIds?.length) {
      await markSurveysSynced(data.syncedIds);
    }
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncing = false;
  }
};

export const subscribeToNetworkChanges = () => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncSurveys();
    }
  });
};
```

