```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/api/sync', (req, res) => {
  const incoming = req.body.surveys || [];
  const syncedIds = [];

  for (const survey of incoming) {
    const existing = surveys.get(survey.id);

    if (!existing || survey.updatedAt >= existing.updatedAt) {
      surveys.set(survey.id, survey);
    }

    syncedIds.push(survey.id);
  }

  res.json({
    success: true,
    syncedIds
  });
});

app.get('/api/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
