import { getUnsyncedSurveys, markSurveysSynced, upsertSurvey } from './db';
import AsyncStorage from '@react-native-async-storage/async-storage';

const CHANGES_URL = 'http://YOUR_SERVER_IP:3000/api/changes';
const LAST_SYNC_KEY = 'lastSyncTime';

export const pullChanges = async () => {
  const lastSync = Number(await AsyncStorage.getItem(LAST_SYNC_KEY)) || 0;

  const response = await fetch(`${CHANGES_URL}?since=${lastSync}`);
  const data = await response.json();

  for (const survey of data.changes) {
    await upsertSurvey({
      ...survey,
      synced: 1
    });
  }

  await AsyncStorage.setItem(LAST_SYNC_KEY, String(data.serverTime));
};

export const fullSync = async () => {
  await syncSurveys();
  await pullChanges();
};
