// db.js
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  db.transaction(tx => {
    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        title TEXT,
        notes TEXT,
        latitude REAL,
        longitude REAL,
        updated_at TEXT,
        sync_status TEXT
      );
    `);

    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        record_id TEXT NOT NULL,
        operation TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at TEXT NOT NULL,
        status TEXT NOT NULL
      );
    `);
  });
};

export const insertSurvey = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
         (id, title, notes, latitude, longitude, updated_at, sync_status)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.title,
          survey.notes,
          survey.latitude,
          survey.longitude,
          survey.updated_at,
          survey.sync_status || 'pending'
        ],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updated_at DESC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const addToQueue = ({ record_id, operation, payload }) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (record_id, operation, payload, created_at, status)
         VALUES (?, ?, ?, ?, ?)`,
        [
          record_id,
          operation,
          JSON.stringify(payload),
          new Date().toISOString(),
          'pending'
        ],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const getPendingQueueItems = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY created_at ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const markQueueItemSynced = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE sync_queue SET status = 'synced' WHERE id = ?`,
        [id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const markSurveySynced = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET sync_status = 'synced' WHERE id = ?`,
        [id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export default db;
```

