## `sync.js` — sync engine

```javascript
// sync.js
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingQueueItems,
  markQueueItemSynced,
  markSurveySynced,
  insertSurvey
} from './db';
import { pushSurvey, fetchServerUpdates } from './api';

let syncInProgress = false;

export const syncPendingData = async () => {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const queueItems = await getPendingQueueItems();

    for (const item of queueItems) {
      const payload = JSON.parse(item.payload);

      if (item.operation === 'upsert') {
        await pushSurvey(payload);
        await markQueueItemSynced(item.id);
        await markSurveySynced(item.record_id);
      }
    }
  } catch (err) {
    console.error('Sync failed:', err.message);
  } finally {
    syncInProgress = false;
  }
};

export const startSyncListener = () => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingData();
    }
  });
};
```

