## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

// Upsert survey
app.post('/sync/survey', (req, res) => {
  const survey = req.body;

  if (!survey.id) {
    return res.status(400).json({ error: 'Missing survey id' });
  }

  const existing = surveys.get(survey.id);

  if (!existing || new Date(survey.updated_at) >= new Date(existing.updated_at)) {
    surveys.set(survey.id, survey);
  }

  return res.json({
    success: true,
    survey: surveys.get(survey.id)
  });
});

// Fetch updates since timestamp
app.get('/sync/updates', (req, res) => {
  const { lastSyncAt } = req.query;

  const since = lastSyncAt ? new Date(lastSyncAt) : new Date(0);

  const updated = Array.from(surveys.values()).filter(
    s => new Date(s.updated_at) > since
  );

  res.json({
    success: true,
    updates: updated
  });
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

