# 3. Frontend: IndexedDB wrapper

Use IndexedDB for robust offline persistence.

## `db.js`

```js
const DB_NAME = 'fieldSurveyDB';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const QUEUE_STORE = 'syncQueue';
const META_STORE = 'meta';

export function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;

      if (!db.objectStoreNames.contains(SURVEY_STORE)) {
        const surveyStore = db.createObjectStore(SURVEY_STORE, { keyPath: 'id' });
        surveyStore.createIndex('updatedAt', 'updatedAt', { unique: false });
        surveyStore.createIndex('pendingSync', 'pendingSync', { unique: false });
      }

      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        const queueStore = db.createObjectStore(QUEUE_STORE, { keyPath: 'id' });
        queueStore.createIndex('createdAt', 'createdAt', { unique: false });
      }

      if (!db.objectStoreNames.contains(META_STORE)) {
        db.createObjectStore(META_STORE, { keyPath: 'key' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function txComplete(tx) {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

export async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SURVEY_STORE, 'readonly');
    const store = tx.objectStore(SURVEY_STORE);
    const req = store.getAll();
    req.onsuccess = () => resolve(req.result.filter(s => !s.deleted));
    req.onerror = () => reject(req.error);
  });
}

export async function getSurvey(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SURVEY_STORE, 'readonly');
    const store = tx.objectStore(SURVEY_STORE);
    const req = store.get(id);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function putSurvey(survey) {
  const db = await openDB();
  const tx = db.transaction(SURVEY_STORE, 'readwrite');
  tx.objectStore(SURVEY_STORE).put(survey);
  await txComplete(tx);
}

export async function bulkPutSurveys(surveys) {
  const db = await openDB();
  const tx = db.transaction(SURVEY_STORE, 'readwrite');
  const store = tx.objectStore(SURVEY_STORE);
  surveys.forEach(s => store.put(s));
  await txComplete(tx);
}

export async function addQueueItem(item) {
  const db = await openDB();
  const tx = db.transaction(QUEUE_STORE, 'readwrite');
  tx.objectStore(QUEUE_STORE).put(item);
  await txComplete(tx);
}

export async function getQueueItems() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readonly');
    const store = tx.objectStore(QUEUE_STORE);
    const req = store.getAll();
    req.onsuccess = () => {
      const items = req.result.sort(
        (a, b) => new Date(a.createdAt) - new Date(b.createdAt)
      );
      resolve(items);
    };
    req.onerror = () => reject(req.error);
  });
}

export async function deleteQueueItem(id) {
  const db = await openDB();
  const tx = db.transaction(QUEUE_STORE, 'readwrite');
  tx.objectStore(QUEUE_STORE).delete(id);
  await txComplete(tx);
}

export async function setMeta(key, value) {
  const db = await openDB();
  const tx = db.transaction(META_STORE, 'readwrite');
  tx.objectStore(META_STORE).put({ key, value });
  await txComplete(tx);
}

export async function getMeta(key) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(META_STORE, 'readonly');
    const store = tx.objectStore(META_STORE);
    const req = store.get(key);
    req.onsuccess = () => resolve(req.result?.value ?? null);
    req.onerror = () => reject(req.error);
  });
}
```

