# 4. Frontend: survey repository

## `surveyRepository.js`

```js
import {
  putSurvey,
  getAllSurveys,
  addQueueItem,
  getQueueItems,
  deleteQueueItem,
  bulkPutSurveys,
  getMeta,
  setMeta
} from './db';

function uuid() {
  return crypto.randomUUID();
}

function now() {
  return new Date().toISOString();
}

export async function createSurvey(data) {
  const survey = {
    id: uuid(),
    title: data.title,
    location: data.location,
    notes: data.notes,
    updatedAt: now(),
    deleted: false,
    pendingSync: true
  };

  await putSurvey(survey);

  await addQueueItem({
    id: uuid(),
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    createdAt: now(),
    retryCount: 0
  });

  return survey;
}

export async function updateSurvey(existing, updates) {
  const updated = {
    ...existing,
    ...updates,
    updatedAt: now(),
    pendingSync: true
  };

  await putSurvey(updated);

  await addQueueItem({
    id: uuid(),
    entityId: updated.id,
    operation: 'update',
    payload: updated,
    createdAt: now(),
    retryCount: 0
  });

  return updated;
}

export async function deleteSurvey(existing) {
  const deleted = {
    ...existing,
    deleted: true,
    updatedAt: now(),
    pendingSync: true
  };

  await putSurvey(deleted);

  await addQueueItem({
    id: uuid(),
    entityId: deleted.id,
    operation: 'delete',
    payload: deleted,
    createdAt: now(),
    retryCount: 0
  });

  return deleted;
}

export async function listSurveys() {
  return getAllSurveys();
}

export async function syncSurveys(apiBaseUrl) {
  if (!navigator.onLine) return { synced: 0, skipped: true };

  const queue = await getQueueItems();
  let synced = 0;

  for (const item of queue) {
    try {
      const res = await fetch(`${apiBaseUrl}/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(item)
      });

      if (!res.ok) {
        throw new Error(`Sync failed: ${res.status}`);
      }

      const serverSurvey = await res.json();

      await putSurvey({
        ...serverSurvey,
        pendingSync: false
      });

      await deleteQueueItem(item.id);
      synced++;
    } catch (err) {
      console.error('Queue item sync failed', item, err);
      break;
    }
  }

  const lastPulledAt = await getMeta('lastPulledAt');
  const pullRes = await fetch(
    `${apiBaseUrl}/surveys?since=${encodeURIComponent(lastPulledAt || '')}`
  );

  if (pullRes.ok) {
    const remoteChanges = await pullRes.json();
    const normalized = remoteChanges.map(s => ({
      ...s,
      pendingSync: false
    }));
    await bulkPutSurveys(normalized);
    await setMeta('lastPulledAt', now());
  }

  return { synced };
}
```

