import React, { useEffect, useState } from 'react';
import {
  createSurvey,
  listSurveys,
  syncSurveys
} from './surveyRepository';

const API_BASE_URL = 'http://localhost:4000';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({
    title: '',
    location: '',
    notes: ''
  });
  const [status, setStatus] = useState(navigator.onLine ? 'online' : 'offline');
  const [syncMessage, setSyncMessage] = useState('');

  async function refresh() {
    const items = await listSurveys();
    setSurveys(items);
  }

  useEffect(() => {
    refresh();

    const onOnline = async () => {
      setStatus('online');
      setSyncMessage('Syncing...');
      const result = await syncSurveys(API_BASE_URL);
      setSyncMessage(`Synced ${result.synced} item(s)`);
      await refresh();
    };

    const onOffline = () => {
      setStatus('offline');
      setSyncMessage('Offline mode');
    };

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    const interval = setInterval(async () => {
      if (navigator.onLine) {
        try {
          await syncSurveys(API_BASE_URL);
          await refresh();
        } catch (e) {
          console.error(e);
        }
      }
    }, 15000);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      clearInterval(interval);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();
    await createSurvey(form);
    setForm({ title: '', location: '', notes: '' });
    await refresh();

    if (navigator.onLine) {
      await syncSurveys(API_BASE_URL);
      await refresh();
    }
  }

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{status}</strong></p>
      <p>{syncMessage}</p>

      <form onSubmit={handleSubmit} style={{ marginBottom: 20 }}>
        <input
          placeholder="Title"
          value={form.title}
          onChange={e => setForm({ ...form, title: e.target.value })}
          required
        />
        <br /><br />
        <input
          placeholder="Location"
          value={form.location}
          onChange={e => setForm({ ...form, location: e.target.value })}
          required
        />
        <br /><br />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={e => setForm({ ...form, notes: e.target.value })}
        />
        <br /><br />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map(s => (
          <li key={s.id}>
            <strong>{s.title}</strong> - {s.location}
            {s.pendingSync ? ' (pending sync)' : ''}
            <br />
            <small>{s.notes}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
