# 6. Backend: Express sync server

This is a simple in-memory example. In production, use PostgreSQL, MongoDB, etc.

## `server.js`

```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

function now() {
  return new Date().toISOString();
}

app.post('/sync', (req, res) => {
  const item = req.body;
  const incoming = item.payload;
  const existing = surveys.get(incoming.id);

  if (!existing) {
    surveys.set(incoming.id, {
      ...incoming,
      pendingSync: false,
      serverUpdatedAt: now()
    });
    return res.json(surveys.get(incoming.id));
  }

  const incomingTime = new Date(incoming.updatedAt).getTime();
  const existingTime = new Date(existing.updatedAt).getTime();

  if (incomingTime >= existingTime) {
    const merged = {
      ...existing,
      ...incoming,
      pendingSync: false,
      serverUpdatedAt: now()
    };
    surveys.set(incoming.id, merged);
    return res.json(merged);
  }

  return res.json(existing);
});

app.get('/surveys', (req, res) => {
  const since = req.query.since ? new Date(req.query.since).getTime() : 0;

  const changed = Array.from(surveys.values()).filter(s => {
    const t = new Date(s.serverUpdatedAt || s.updatedAt).getTime();
    return t > since;
  });

  res.json(changed);
});

app.listen(4000, () => {
  console.log('Sync server listening on http://localhost:4000');
});
```

