## `surveyRepository.ts`

```ts
import { getDb } from './db';

export type Survey = {
  id: string;
  title: string;
  notes: string;
  latitude: number | null;
  longitude: number | null;
  updatedAt: string;
  deleted: boolean;
  syncStatus: 'synced' | 'pending_create' | 'pending_update' | 'pending_delete';
};

const db = getDb();

export function getAllSurveys(): Survey[] {
  const rows = db.getAllSync(`SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`);
  return rows.map(mapRow);
}

export function getPendingSurveys(): Survey[] {
  const rows = db.getAllSync(`
    SELECT * FROM surveys
    WHERE syncStatus IN ('pending_create', 'pending_update', 'pending_delete')
    ORDER BY updatedAt ASC
  `);
  return rows.map(mapRow);
}

export function getSurveyById(id: string): Survey | null {
  const row = db.getFirstSync(`SELECT * FROM surveys WHERE id = ?`, [id]);
  return row ? mapRow(row) : null;
}

export function insertSurvey(survey: Survey) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, title, notes, latitude, longitude, updatedAt, deleted, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.updatedAt,
      survey.deleted ? 1 : 0,
      survey.syncStatus,
    ]
  );
}

export function updateSurveyLocal(
  id: string,
  updates: Partial<Pick<Survey, 'title' | 'notes' | 'latitude' | 'longitude'>>
) {
  const existing = getSurveyById(id);
  if (!existing) return;

  const updatedAt = new Date().toISOString();
  const nextSyncStatus =
    existing.syncStatus === 'pending_create' ? 'pending_create' : 'pending_update';

  db.runSync(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [
      updates.title ?? existing.title,
      updates.notes ?? existing.notes,
      updates.latitude ?? existing.latitude,
      updates.longitude ?? existing.longitude,
      updatedAt,
      nextSyncStatus,
      id,
    ]
  );
}

export function softDeleteSurveyLocal(id: string) {
  const existing = getSurveyById(id);
  if (!existing) return;

  const updatedAt = new Date().toISOString();
  const nextSyncStatus =
    existing.syncStatus === 'pending_create' ? 'pending_delete' : 'pending_delete';

  db.runSync(
    `UPDATE surveys
     SET deleted = 1, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [updatedAt, nextSyncStatus, id]
  );
}

export function markSurveySynced(id: string, updatedAt: string) {
  db.runSync(
    `UPDATE surveys
     SET syncStatus = 'synced', updatedAt = ?
     WHERE id = ?`,
    [updatedAt, id]
  );
}

export function applyRemoteSurvey(survey: Omit<Survey, 'syncStatus'>) {
  const local = getSurveyById(survey.id);

  if (!local) {
    db.runSync(
      `INSERT INTO surveys
        (id, title, notes, latitude, longitude, updatedAt, deleted, syncStatus)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced')`,
      [
        survey.id,
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.updatedAt,
        survey.deleted ? 1 : 0,
      ]
    );
    return;
  }

  // Do not overwrite local pending changes
  if (local.syncStatus !== 'synced') return;

  db.runSync(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, deleted = ?, syncStatus = 'synced'
     WHERE id = ?`,
    [
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.updatedAt,
      survey.deleted ? 1 : 0,
      survey.id,
    ]
  );
}

export function getMetadata(key: string): string | null {
  const row = db.getFirstSync(`SELECT value FROM metadata WHERE key = ?`, [key]) as { value: string } | null;
  return row?.value ?? null;
}

export function setMetadata(key: string, value: string) {
  db.runSync(
    `INSERT OR REPLACE INTO metadata (key, value) VALUES (?, ?)`,
    [key, value]
  );
}

function mapRow(row: any): Survey {
  return {
    id: row.id,
    title: row.title,
    notes: row.notes,
    latitude: row.latitude,
    longitude: row.longitude,
    updatedAt: row.updatedAt,
    deleted: !!row.deleted,
    syncStatus: row.syncStatus,
  };
}
```

