## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingSurveys,
  applyRemoteSurvey,
  markSurveySynced,
  setMetadata,
  getMetadata,
  Survey,
} from './surveyRepository';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

type PushPayload = {
  changes: Array<{
    id: string;
    title: string;
    notes: string;
    latitude: number | null;
    longitude: number | null;
    updatedAt: string;
    deleted: boolean;
  }>;
};

type PullResponse = {
  changes: Array<{
    id: string;
    title: string;
    notes: string;
    latitude: number | null;
    longitude: number | null;
    updatedAt: string;
    deleted: boolean;
  }>;
  serverTime: string;
};

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  await pushLocalChanges();
  await pullRemoteChanges();
}

async function pushLocalChanges() {
  const pending = getPendingSurveys();
  if (pending.length === 0) return;

  const payload: PushPayload = {
    changes: pending.map(stripSyncStatus),
  };

  const res = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    throw new Error(`Push failed: ${res.status}`);
  }

  const data: { applied: Array<{ id: string; updatedAt: string }> } = await res.json();

  for (const item of data.applied) {
    markSurveySynced(item.id, item.updatedAt);
  }
}

async function pullRemoteChanges() {
  const lastSync = getMetadata('lastSync') || '1970-01-01T00:00:00.000Z';

  const res = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(lastSync)}`);
  if (!res.ok) {
    throw new Error(`Pull failed: ${res.status}`);
  }

  const data: PullResponse = await res.json();

  for (const survey of data.changes) {
    applyRemoteSurvey(survey);
  }

  setMetadata('lastSync', data.serverTime);
}

function stripSyncStatus(survey: Survey) {
  return {
    id: survey.id,
    title: survey.title,
    notes: survey.notes,
    latitude: survey.latitude,
    longitude: survey.longitude,
    updatedAt: survey.updatedAt,
    deleted: survey.deleted,
  };
}

let unsubscribe: (() => void) | null = null;

export function startSyncListener() {
  unsubscribe = NetInfo.addEventListener((state) => {
    if (state.isConnected) {
      syncNow().catch(console.error);
    }
  });
}

export function stopSyncListener() {
  if (unsubscribe) unsubscribe();
}
```

