## `server.js`

```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

/**
 * Demo in-memory store:
 * {
 *   [id]: {
 *     id, title, notes, latitude, longitude, updatedAt, deleted
 *   }
 * }
 */
const surveys = {};

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: 'Invalid changes payload' });
  }

  const applied = [];

  for (const incoming of changes) {
    const existing = surveys[incoming.id];

    // Last-write-wins by updatedAt
    if (!existing || new Date(incoming.updatedAt) >= new Date(existing.updatedAt)) {
      const serverUpdatedAt = new Date().toISOString();

      surveys[incoming.id] = {
        id: incoming.id,
        title: incoming.title,
        notes: incoming.notes,
        latitude: incoming.latitude,
        longitude: incoming.longitude,
        updatedAt: serverUpdatedAt,
        deleted: !!incoming.deleted,
      };

      applied.push({
        id: incoming.id,
        updatedAt: serverUpdatedAt,
      });
    } else {
      applied.push({
        id: existing.id,
        updatedAt: existing.updatedAt,
      });
    }
  }

  res.json({ applied });
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const sinceDate = new Date(since);

  const changes = Object.values(surveys).filter(
    (survey) => new Date(survey.updatedAt) > sinceDate
  );

  res.json({
    changes,
    serverTime: new Date().toISOString(),
  });
});

app.get('/surveys', (req, res) => {
  res.json(Object.values(surveys).filter((s) => !s.deleted));
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Sync server running on port ${PORT}`);
});
```

