```ts
import { openDB } from 'idb';
import { SurveyRecord } from './types';

const DB_NAME = 'offline-survey-db';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const META_STORE = 'meta';

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains(SURVEY_STORE)) {
      const store = db.createObjectStore(SURVEY_STORE, { keyPath: 'id' });
      store.createIndex('syncStatus', 'syncStatus');
      store.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains(META_STORE)) {
      db.createObjectStore(META_STORE);
    }
  },
});

export async function saveSurvey(record: SurveyRecord) {
  const db = await dbPromise;
  await db.put(SURVEY_STORE, record);
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const db = await dbPromise;
  return db.getAll(SURVEY_STORE);
}

export async function getPendingSurveys(): Promise<SurveyRecord[]> {
  const db = await dbPromise;
  return db.getAllFromIndex(SURVEY_STORE, 'syncStatus', 'pending');
}

export async function getFailedSurveys(): Promise<SurveyRecord[]> {
  const db = await dbPromise;
  return db.getAllFromIndex(SURVEY_STORE, 'syncStatus', 'failed');
}

export async function deleteSurvey(id: string) {
  const db = await dbPromise;
  await db.delete(SURVEY_STORE, id);
}

export async function setMeta(key: string, value: any) {
  const db = await dbPromise;
  await db.put(META_STORE, value, key);
}

export async function getMeta<T>(key: string): Promise<T | undefined> {
  const db = await dbPromise;
  return db.get(META_STORE, key);
}
```

