import { SurveyRecord } from './types';

const API_BASE = 'http://localhost:4000';

export interface PushPayload {
  records: SurveyRecord[];
}

export interface PushResponse {
  success: Array<{
    localId: string;
    serverId: string;
    updatedAt: string;
  }>;
  failed: Array<{
    localId: string;
    error: string;
  }>;
}

export async function pushSurveys(records: SurveyRecord[]): Promise<PushResponse> {
  const response = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ records }),
  });

  if (!response.ok) {
    throw new Error(`Push failed: ${response.status}`);
  }

  return response.json();
}

export async function pullSurveys(since?: string): Promise<SurveyRecord[]> {
  const url = new URL(`${API_BASE}/sync/pull`);
  if (since) url.searchParams.set('since', since);

  const response = await fetch(url.toString());

  if (!response.ok) {
    throw new Error(`Pull failed: ${response.status}`);
  }

  return response.json();
}
