## `sync.ts`

This handles reconnect sync.

```ts
import { getAllSurveys, getMeta, getPendingSurveys, saveSurvey, setMeta } from './db';
import { pullSurveys, pushSurveys } from './api';
import { SurveyRecord } from './types';

let syncInProgress = false;

export async function syncAll() {
  if (syncInProgress) return;
  if (!navigator.onLine) return;

  syncInProgress = true;

  try {
    await pushPendingChanges();
    await pullRemoteChanges();
  } catch (err) {
    console.error('Sync failed', err);
  } finally {
    syncInProgress = false;
  }
}

async function pushPendingChanges() {
  const pending = await getPendingSurveys();
  if (pending.length === 0) return;

  try {
    const result = await pushSurveys(pending);

    const all = await getAllSurveys();
    const byId = new Map(all.map(r => [r.id, r]));

    for (const item of result.success) {
      const record = byId.get(item.localId);
      if (!record) continue;

      record.serverId = item.serverId;
      record.updatedAt = item.updatedAt;
      record.syncStatus = 'synced';
      await saveSurvey(record);
    }

    for (const item of result.failed) {
      const record = byId.get(item.localId);
      if (!record) continue;

      record.syncStatus = 'failed';
      await saveSurvey(record);
    }
  } catch (error) {
    console.error('Push error', error);
    throw error;
  }
}

async function pullRemoteChanges() {
  const lastSync = await getMeta<string>('lastSync');
  const remoteRecords = await pullSurveys(lastSync);

  for (const remote of remoteRecords) {
    const localRecords = await getAllSurveys();
    const local = localRecords.find(r => r.serverId === remote.serverId);

    if (!local) {
      await saveSurvey({
        ...remote,
        id: remote.id,
        syncStatus: 'synced',
      });
      continue;
    }

    // naive conflict resolution: latest updatedAt wins,
    // but don't overwrite local pending changes
    if (local.syncStatus === 'pending') continue;

    if (new Date(remote.updatedAt) > new Date(local.updatedAt)) {
      await saveSurvey({
        ...local,
        ...remote,
        id: local.id,
        syncStatus: 'synced',
      });
    }
  }

  await setMeta('lastSync', new Date().toISOString());
}

export function setupSyncListeners() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncAll();
  });
}
```

