## `App.tsx`

A simple UI for creating and listing surveys.

```tsx
import React, { useEffect, useState } from 'react';
import { getAllSurveys, saveSurvey } from './db';
import { setupSyncListeners, syncAll } from './sync';
import { SurveyRecord } from './types';

function generateId() {
  return crypto.randomUUID();
}

export default function App() {
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [online, setOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const all = await getAllSurveys();
    all.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
    setSurveys(all);
  }

  useEffect(() => {
    loadSurveys();
    setupSyncListeners();

    const onOnline = () => setOnline(true);
    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    syncAll();

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function createSurvey() {
    const now = new Date().toISOString();

    let latitude: number | null = null;
    let longitude: number | null = null;

    if ('geolocation' in navigator) {
      try {
        const position = await new Promise<GeolocationPosition>((resolve, reject) =>
          navigator.geolocation.getCurrentPosition(resolve, reject, {
            enableHighAccuracy: true,
            timeout: 5000,
          })
        );
        latitude = position.coords.latitude;
        longitude = position.coords.longitude;
      } catch {
        console.warn('Could not get location');
      }
    }

    const record: SurveyRecord = {
      id: generateId(),
      title,
      notes,
      latitude,
      longitude,
      createdAt: now,
      updatedAt: now,
      syncStatus: 'pending',
    };

    await saveSurvey(record);
    setTitle('');
    setNotes('');
    await loadSurveys();

    if (navigator.onLine) {
      await syncAll();
      await loadSurveys();
    }
  }

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif', maxWidth: 700, margin: '0 auto' }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{online ? 'Online' : 'Offline'}</strong></p>

      <div style={{ display: 'grid', gap: 8, marginBottom: 20 }}>
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Survey title"
        />
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Survey notes"
          rows={4}
        />
        <button onClick={createSurvey} disabled={!title.trim()}>
          Save Survey
        </button>
      </div>

      <h2>Saved Surveys</h2>
      <ul style={{ padding: 0, listStyle: 'none' }}>
        {surveys.map((survey) => (
          <li
            key={survey.id}
            style={{
              border: '1px solid #ccc',
              borderRadius: 8,
              padding: 12,
              marginBottom: 10,
            }}
          >
            <div><strong>{survey.title}</strong></div>
            <div>{survey.notes}</div>
            <div>
              Lat/Lng: {survey.latitude ?? 'N/A'} / {survey.longitude ?? 'N/A'}
            </div>
            <div>Updated: {survey.updatedAt}</div>
            <div>Sync: {survey.syncStatus}</div>
          </li>
        ))}
      </ul>
    </div>
  );
}
