## `server/index.ts`

```ts
import express from 'express';
import cors from 'cors';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(express.json());

type SurveyRecord = {
  id: string; // local id from client
  serverId?: string;
  title: string;
  notes: string;
  latitude: number | null;
  longitude: number | null;
  createdAt: string;
  updatedAt: string;
  syncStatus?: 'pending' | 'synced' | 'failed';
  deleted?: boolean;
};

type ServerSurveyRecord = {
  serverId: string;
  clientLocalId?: string;
  title: string;
  notes: string;
  latitude: number | null;
  longitude: number | null;
  createdAt: string;
  updatedAt: string;
  deleted?: boolean;
};

const surveys = new Map<string, ServerSurveyRecord>();

app.post('/sync/push', (req, res) => {
  const records: SurveyRecord[] = req.body.records ?? [];

  const success: Array<{ localId: string; serverId: string; updatedAt: string }> = [];
  const failed: Array<{ localId: string; error: string }> = [];

  for (const record of records) {
    try {
      if (!record.title?.trim()) {
        failed.push({ localId: record.id, error: 'Title is required' });
        continue;
      }

      const serverId = record.serverId || uuidv4();
      const updatedAt = new Date().toISOString();

      surveys.set(serverId, {
        serverId,
        clientLocalId: record.id,
        title: record.title,
        notes: record.notes,
        latitude: record.latitude,
        longitude: record.longitude,
        createdAt: record.createdAt,
        updatedAt,
        deleted: record.deleted,
      });

      success.push({
        localId: record.id,
        serverId,
        updatedAt,
      });
    } catch (error) {
      failed.push({
        localId: record.id,
        error: 'Unexpected server error',
      });
    }
  }

  res.json({ success, failed });
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since ? new Date(String(req.query.since)) : null;

  let records = Array.from(surveys.values());

  if (since && !isNaN(since.getTime())) {
    records = records.filter(r => new Date(r.updatedAt) > since);
  }

  res.json(
    records.map(r => ({
      id: r.clientLocalId || r.serverId,
      serverId: r.serverId,
      title: r.title,
      notes: r.notes,
      latitude: r.latitude,
      longitude: r.longitude,
      createdAt: r.createdAt,
      updatedAt: r.updatedAt,
      syncStatus: 'synced',
      deleted: r.deleted,
    }))
  );
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

