## `src/sync.ts`

```ts
import { db, SurveyRecord } from "./db";
import { syncBatch } from "./api";

let syncing = false;

export async function enqueueSurveyOperation(
  operation: "create" | "update" | "delete",
  survey: SurveyRecord
) {
  await db.syncQueue.add({
    entityType: "survey",
    entityId: survey.id,
    operation,
    payload: survey,
    createdAt: new Date().toISOString(),
    retryCount: 0
  });
}

export async function syncPendingData() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const queue = await db.syncQueue.orderBy("createdAt").toArray();
    if (queue.length === 0) return;

    const operations = queue.map((item) => ({
      queueId: item.id,
      entityType: item.entityType,
      entityId: item.entityId,
      operation: item.operation,
      payload: item.payload
    }));

    const result = await syncBatch(operations);

    await db.transaction("rw", db.surveys, db.syncQueue, async () => {
      for (const processed of result.processed) {
        const local = await db.surveys.get(processed.clientId);

        if (processed.status === "ok") {
          if (processed.record?.deleted) {
            await db.surveys.delete(processed.clientId);
          } else if (processed.record) {
            await db.surveys.put({
              ...local,
              ...processed.record,
              id: processed.clientId,
              syncStatus: "synced"
            });
          }

          if (processed.queueId) {
            await db.syncQueue.delete(processed.queueId);
          }
        } else if (processed.status === "conflict") {
          if (local) {
            await db.surveys.put({
              ...local,
              syncStatus: "conflict"
            });
          }
        } else {
          if (local) {
            await db.surveys.put({
              ...local,
              syncStatus: "failed"
            });
          }
        }
      }
    });
  } catch (err) {
    console.error("Sync error", err);
  } finally {
    syncing = false;
  }
}

export function setupSyncListeners() {
  window.addEventListener("online", () => {
    syncPendingData();
  });
}
```

