import { useEffect, useState } from "react";
import { db, SurveyRecord } from "./db";

export function useSurveys() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      const data = await db.surveys.where("deleted").notEqual(1 as any).toArray();
      if (mounted) {
        setSurveys(data.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
      }
    };

    load();

    const interval = setInterval(load, 1000);
    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, []);

  return surveys;
}
