import { useState } from "react";
import { v4 as uuid } from "uuid";
import { db, SurveyRecord } from "../db";
import { enqueueSurveyOperation, syncPendingData } from "../sync";

type Props = {
  existing?: SurveyRecord;
  onDone: () => void;
};

export default function SurveyForm({ existing, onDone }: Props) {
  const [title, setTitle] = useState(existing?.title ?? "");
  const [location, setLocation] = useState(existing?.location ?? "");
  const [notes, setNotes] = useState(existing?.notes ?? "");
  const [status, setStatus] = useState<"draft" | "submitted">(
    existing?.status ?? "draft"
  );

  async function save() {
    const now = new Date().toISOString();

    const survey: SurveyRecord = {
      id: existing?.id ?? uuid(),
      serverId: existing?.serverId,
      title,
      location,
      notes,
      status,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
      version: (existing?.version ?? 0) + 1,
      serverVersion: existing?.serverVersion,
      syncStatus: "pending",
      deleted: false
    };

    await db.surveys.put(survey);
    await enqueueSurveyOperation(existing ? "update" : "create", survey);

    if (navigator.onLine) {
      await syncPendingData();
    }

    onDone();
  }

  return (
    <div style={{ border: "1px solid #ccc", padding: 16, marginBottom: 16 }}>
      <h3>{existing ? "Edit Survey" : "New Survey"}</h3>

      <div>
        <label>Title</label>
        <br />
        <input value={title} onChange={(e) => setTitle(e.target.value)} />
      </div>

      <div>
