  const [editing, setEditing] = useState<SurveyRecord | undefined>();
  const [showForm, setShowForm] = useState(false);
  const [online, setOnline] = useState(navigator.onLine);

  useEffect(() => {
    setupSyncListeners();
    syncPendingData();

    const onOnline = () => {
      setOnline(true);
      syncPendingData();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ maxWidth: 800, margin: "0 auto", padding: 24 }}>
      <h1>Field Survey App</h1>
      <p>Network: {online ? "Online" : "Offline"}</p>

      <button
        onClick={() => {
          setEditing(undefined);
          setShowForm(true);
        }}
      >
        New Survey
      </button>

      <button onClick={() => syncPendingData()} style={{ marginLeft: 8 }}>
        Sync Now
      </button>

      {showForm && (
        <SurveyForm
          existing={editing}
          onDone={() => {
            setEditing(undefined);
            setShowForm(false);
          }}
        />
      )}

      <SurveyList
        surveys={surveys}
        onEdit={(survey) => {
          setEditing(survey);
          setShowForm(true);
        }}
      />
    </div>
  );
}
