## `server/index.js`

```js
const express = require("express");
const cors = require("cors");
const { v4: uuid } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get("/surveys", (req, res) => {
  res.json(Array.from(surveys.values()).filter((s) => !s.deleted));
});

app.post("/sync", (req, res) => {
  const operations = req.body.operations || [];
  const processed = [];

  for (const op of operations) {
    const payload = op.payload;
    const clientId = payload.id;

    if (op.operation === "create") {
      const serverId = payload.serverId || uuid();
      const record = {
        ...payload,
        serverId,
        serverVersion: 1,
        syncStatus: "synced"
      };
      surveys.set(serverId, record);

      processed.push({
        queueId: op.queueId,
        clientId,
        status: "ok",
        record
      });
    }

    if (op.operation === "update") {
      const existing = payload.serverId ? surveys.get(payload.serverId) : null;

      if (!existing) {
        const serverId = payload.serverId || uuid();
        const record = {
          ...payload,
          serverId,
          serverVersion: 1,
          syncStatus: "synced"
        };
        surveys.set(serverId, record);

        processed.push({
          queueId: op.queueId,
          clientId,
          status: "ok",
          record
        });
        continue;
      }

      if (
        payload.serverVersion !== undefined &&
        payload.serverVersion !== existing.serverVersion
      ) {
        processed.push({
          queueId: op.queueId,
          clientId,
          status: "conflict",
          serverRecord: existing
        });
        continue;
      }

      const updated = {
        ...existing,
        ...payload,
        serverVersion: existing.serverVersion + 1,
        syncStatus: "synced"
      };

      surveys.set(existing.serverId, updated);

      processed.push({
        queueId: op.queueId,
        clientId,
        status: "ok",
        record: updated
      });
    }

    if (op.operation === "delete") {
      const existing = payload.serverId ? surveys.get(payload.serverId) : null;

      if (!existing) {
        processed.push({
          queueId: op.queueId,
          clientId,
          status: "ok",
          record: { ...payload, deleted: true }
        });
        continue;
      }

      if (
        payload.serverVersion !== undefined &&
        payload.serverVersion !== existing.serverVersion
      ) {
        processed.push({
          queueId: op.queueId,
          clientId,
          status: "conflict",
          serverRecord: existing
        });
        continue;
      }

      const deleted = {
        ...existing,
        deleted: true,
        serverVersion: existing.serverVersion + 1
      };

      surveys.set(existing.serverId, deleted);

      processed.push({
        queueId: op.queueId,
        clientId,
        status: "ok",
        record: deleted
      });
    }
  }

  res.json({ processed });
});

app.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

