## `App.js`
```javascript
import React, { useEffect, useState, useCallback } from 'react';
import {
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
  TouchableOpacity,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { v4 as uuidv4 } from 'uuid';

const db = SQLite.openDatabase('surveys.db');
const API_BASE = 'http://YOUR_SERVER_IP:3000';

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected;
      setIsOnline(online);
      if (online) {
        syncPendingChanges();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction(tx => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          title TEXT,
          location TEXT,
          notes TEXT,
          updatedAt TEXT,
          syncStatus TEXT
        );
      `);
    });
  };

  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE syncStatus != ? OR syncStatus IS NULL ORDER BY updatedAt DESC;',
        ['pending_delete'],
        (_, result) => {
          setSurveys(result.rows._array);
        }
      );
    });
  };

  const addSurvey = () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    const id = uuidv4();
    const updatedAt = new Date().toISOString();

    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, title, location, notes, updatedAt, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [id, title, location, notes, updatedAt, 'pending_create'],
        () => {
          setTitle('');
          setLocation('');
          setNotes('');
          loadSurveys();
          if (isOnline) syncPendingChanges();
        }
      );
    });
  };

  const updateSurvey = (item) => {
    const updatedAt = new Date().toISOString();
    const newNotes = item.notes + ' (edited)';

    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET notes = ?, updatedAt = ?, syncStatus = ?
         WHERE id = ?;`,
        [
          newNotes,
          updatedAt,
          item.syncStatus === 'pending_create' ? 'pending_create' : 'pending_update',
          item.id,
        ],
        () => {
          loadSurveys();
          if (isOnline) syncPendingChanges();
        }
      );
    });
  };

  const deleteSurvey = (item) => {
    db.transaction(tx => {
      if (item.syncStatus === 'pending_create') {
        tx.executeSql('DELETE FROM surveys WHERE id = ?;', [item.id], loadSurveys);
      } else {
        tx.executeSql(
          `UPDATE surveys SET syncStatus = ?, updatedAt = ? WHERE id = ?;`,
          ['pending_delete', new Date().toISOString(), item.id],
          () => {
            loadSurveys();
            if (isOnline) syncPendingChanges();
          }
        );
      }
    });
  };

  const getPendingSurveys = () =>
    new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          `SELECT * FROM surveys
           WHERE syncStatus IN ('pending_create', 'pending_update', 'pending_delete')
           ORDER BY updatedAt ASC;`,
          [],
          (_, result) => resolve(result.rows._array),
          (_, err) => reject(err)
        );
      });
    });

  const markSynced = (id) =>
    new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          `UPDATE surveys SET syncStatus = ? WHERE id = ?;`,
          ['synced', id],
          () => resolve(),
          (_, err) => reject(err)
        );
      });
    });

  const removeLocal = (id) =>
    new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          `DELETE FROM surveys WHERE id = ?;`,
          [id],
          () => resolve(),
          (_, err) => reject(err)
        );
      });
    });

  const syncPendingChanges = useCallback(async () => {
    if (syncing) return;
    setSyncing(true);

    try {
      const pending = await getPendingSurveys();

      for (const survey of pending) {
        if (survey.syncStatus === 'pending_delete') {
          await axios.delete(`${API_BASE}/surveys/${survey.id}`);
          await removeLocal(survey.id);
        } else {
          await axios.put(`${API_BASE}/surveys/${survey.id}`, {
            id: survey.id,
            title: survey.title,
            location: survey.location,
            notes: survey.notes,
            updatedAt: survey.updatedAt,
          });
          await markSynced(survey.id);
        }
      }

      loadSurveys();
    } catch (err) {
      console.log('Sync failed:', err.message);
    } finally {
      setSyncing(false);
    }
  }, [syncing]);

  return (
    <View style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text>Status: {isOnline ? 'Online' : 'Offline'} {syncing ? '(Syncing...)' : ''}</Text>

      <TextInput
        style={styles.input}
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
      />
      <TextInput
        style={styles.input}
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />
      <Button title="Add Survey" onPress={addSurvey} />

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.title}>{item.title}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text style={styles.meta}>Status: {item.syncStatus}</Text>
            <View style={styles.row}>
              <TouchableOpacity style={styles.action} onPress={() => updateSurvey(item)}>
                <Text>Edit</Text>
              </TouchableOpacity>
              <TouchableOpacity style={styles.action} onPress={() => deleteSurvey(item)}>
                <Text>Delete</Text>
              </TouchableOpacity>
            </View>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, paddingTop: 60 },
  header: { fontSize: 24, fontWeight: 'bold', marginBottom: 10 },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    marginBottom: 10,
    padding: 10,
    borderRadius: 6,
  },
  card: {
    borderWidth: 1,
    borderColor: '#ddd',
    padding: 12,
    marginTop: 10,
    borderRadius: 8,
  },
  title: { fontWeight: 'bold', fontSize: 16 },
  meta: { color: '#666', marginTop: 6 },
  row: { flexDirection: 'row', marginTop: 10 },
  action: {
    marginRight: 12,
    padding: 8,
    backgroundColor: '#eee',
    borderRadius: 6,
  },
});
```

