```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.get('/surveys/:id', (req, res) => {
  const survey = surveys.get(req.params.id);
  if (!survey) return res.status(404).json({ error: 'Not found' });
  res.json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const { id, title, location, notes, updatedAt } = req.body;

  if (!id || id !== req.params.id) {
    return res.status(400).json({ error: 'ID mismatch' });
  }

  const existing = surveys.get(id);

  const survey = {
    id,
    title,
    location,
    notes,
    updatedAt,
    serverUpdatedAt: new Date().toISOString(),
  };

  if (existing) {
    surveys.set(id, { ...existing, ...survey });
  } else {
    surveys.set(id, survey);
  }

  res.json(surveys.get(id));
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  res.status(204).send();
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

