```ts
import { openDB } from 'idb';
import type { DBSchema, IDBPDatabase } from 'idb';
import type { SurveyRecord, PendingOperation } from '../types/survey';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: SurveyRecord;
  };
  pendingOps: {
    key: string;
    value: PendingOperation;
  };
}

let dbPromise: Promise<IDBPDatabase<SurveyDB>> | null = null;

export function getDb() {
  if (!dbPromise) {
    dbPromise = openDB<SurveyDB>('offline-survey-db', 1, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('surveys')) {
          db.createObjectStore('surveys', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('pendingOps')) {
          db.createObjectStore('pendingOps', { keyPath: 'opId' });
        }
      },
    });
  }
  return dbPromise;
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const db = await getDb();
  return db.getAll('surveys');
}

export async function saveSurvey(record: SurveyRecord): Promise<void> {
  const db = await getDb();
  await db.put('surveys', record);
}

export async function deleteSurvey(id: string): Promise<void> {
  const db = await getDb();
  await db.delete('surveys', id);
}

export async function addPendingOp(op: PendingOperation): Promise<void> {
  const db = await getDb();
  await db.put('pendingOps', op);
}

export async function getPendingOps(): Promise<PendingOperation[]> {
  const db = await getDb();
  return db.getAll('pendingOps');
}

export async function removePendingOp(opId: string): Promise<void> {
  const db = await getDb();
  await db.delete('pendingOps', opId);
}
