import type { SurveyRecord } from '../types/survey';

const API_BASE = 'http://localhost:4000';

export async function pushCreate(record: SurveyRecord): Promise<void> {
  const res = await fetch(`${API_BASE}/surveys`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(record),
  });

  if (!res.ok) {
    throw new Error(`Create failed: ${res.status}`);
  }
}

export async function pushUpdate(record: SurveyRecord): Promise<void> {
  const res = await fetch(`${API_BASE}/surveys/${record.id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(record),
  });

  if (!res.ok) {
    throw new Error(`Update failed: ${res.status}`);
  }
}

export async function pushDelete(recordId: string): Promise<void> {
  const res = await fetch(`${API_BASE}/surveys/${recordId}`, {
    method: 'DELETE',
  });

  if (!res.ok) {
    throw new Error(`Delete failed: ${res.status}`);
  }
}

export async function fetchServerSurveys(): Promise<SurveyRecord[]> {
  const res = await fetch(`${API_BASE}/surveys`);
  if (!res.ok) {
    throw new Error(`Fetch failed: ${res.status}`);
  }
  return res.json();
}
