# 5. Sync engine

This is the core offline-first behavior:
- save locally first
- queue operations
- sync when online

## `client/src/sync/syncEngine.ts`

```ts
import {
  getPendingOps,
  removePendingOp,
  saveSurvey,
  deleteSurvey,
  getAllSurveys,
} from '../db/indexedDb';
import { pushCreate, pushUpdate, pushDelete, fetchServerSurveys } from '../api/serverApi';
import type { SurveyRecord, PendingOperation } from '../types/survey';

function sortOps(ops: PendingOperation[]) {
  return ops.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
}

export async function syncPendingOperations(): Promise<void> {
  if (!navigator.onLine) return;

  const ops = sortOps(await getPendingOps());

  for (const op of ops) {
    try {
      if (op.type === 'create' && op.payload) {
        await pushCreate(op.payload);
      } else if (op.type === 'update' && op.payload) {
        await pushUpdate(op.payload);
      } else if (op.type === 'delete') {
        await pushDelete(op.recordId);
      }

      await removePendingOp(op.opId);
    } catch (err) {
      console.error('Sync failed for op', op, err);
      break;
    }
  }

  // Optional: refresh local cache from server after sync
  try {
    const serverRecords = await fetchServerSurveys();
    for (const record of serverRecords) {
      await saveSurvey({ ...record, syncStatus: 'synced' });
    }

    const localRecords = await getAllSurveys();
    const serverIds = new Set(serverRecords.map(r => r.id));

    for (const local of localRecords) {
      if (local.syncStatus === 'synced' && !serverIds.has(local.id)) {
        await deleteSurvey(local.id);
      }
    }
  } catch (err) {
    console.error('Failed to refresh local cache', err);
  }
}
```

