# 6. App UI

This is a minimal survey form and list.

## `client/src/App.tsx`

```tsx
import React, { useEffect, useState } from 'react';
import {
  getAllSurveys,
  saveSurvey,
  deleteSurvey,
  addPendingOp,
} from './db/indexedDb';
import { syncPendingOperations } from './sync/syncEngine';
import type { SurveyRecord, PendingOperation } from './types/survey';

function generateId() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(navigator.onLine);
  const [syncing, setSyncing] = useState(false);

  async function loadSurveys() {
    const records = await getAllSurveys();
    setSurveys(records.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
  }

  useEffect(() => {
    loadSurveys();

    const onOnline = async () => {
      setOnline(true);
      setSyncing(true);
      await syncPendingOperations();
      await loadSurveys();
      setSyncing(false);
    };

    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    if (navigator.onLine) {
      setSyncing(true);
      syncPendingOperations()
        .then(loadSurveys)
        .finally(() => setSyncing(false));
    }

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function createSurvey() {
    if (!title.trim()) return;

    const now = new Date().toISOString();
    const record: SurveyRecord = {
      id: generateId(),
      title,
      location,
      notes,
      createdAt: now,
      updatedAt: now,
      syncStatus: 'pending',
    };

    const op: PendingOperation = {
      opId: generateId(),
      type: 'create',
      recordId: record.id,
      payload: record,
      createdAt: now,
    };

    await saveSurvey(record);
    await addPendingOp(op);
    await loadSurveys();

    setTitle('');
    setLocation('');
    setNotes('');

    if (navigator.onLine) {
      setSyncing(true);
      await syncPendingOperations();
      await loadSurveys();
      setSyncing(false);
    }
  }

  async function removeSurvey(id: string) {
    const existing = surveys.find(s => s.id === id);
    if (!existing) return;

    const now = new Date().toISOString();

    await deleteSurvey(id);

    const op: PendingOperation = {
      opId: generateId(),
      type: 'delete',
      recordId: id,
      createdAt: now,
    };

    await addPendingOp(op);
    await loadSurveys();

    if (navigator.onLine) {
      setSyncing(true);
      await syncPendingOperations();
      await loadSurveys();
      setSyncing(false);
    }
  }

  return (
    <div style={{ maxWidth: 700, margin: '0 auto', padding: 24, fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>

      <div
        style={{
          padding: 12,
          marginBottom: 16,
          borderRadius: 8,
          background: online ? '#e8fff0' : '#fff4e5',
          border: `1px solid ${online ? '#8fd19e' : '#f0b35a'}`
        }}
      >
        <strong>Status:</strong> {online ? 'Online' : 'Offline'}
        {syncing && ' • Syncing...'}
      </div>

      <div style={{ display: 'grid', gap: 8, marginBottom: 24 }}>
        <input
          placeholder="Survey title"
          value={title}
          onChange={e => setTitle(e.target.value)}
        />
        <input
          placeholder="Location"
          value={location}
          onChange={e => setLocation(e.target.value)}
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
        />
        <button onClick={createSurvey}>Save Survey</button>
      </div>

      <h2>Saved Surveys</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {surveys.map(survey => (
          <li
            key={survey.id}
            style={{
              border: '1px solid #ddd',
              borderRadius: 8,
              padding: 12,
              marginBottom: 12
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
              <div>
                <strong>{survey.title}</strong>
                <div>{survey.location}</div>
                <div style={{ color: '#555', marginTop: 6 }}>{survey.notes}</div>
                <small>
                  Updated: {new Date(survey.updatedAt).toLocaleString()} • {survey.syncStatus}
                </small>
              </div>
              <button onClick={() => removeSurvey(survey.id)}>Delete</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

