import express from 'express';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

type SyncStatus = 'pending' | 'synced' | 'failed';

interface SurveyRecord {
  id: string;
  title: string;
  location: string;
  notes: string;
  createdAt: string;
  updatedAt: string;
  syncStatus: SyncStatus;
}

const surveys = new Map<string, SurveyRecord>();

app.get('/surveys', (_req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/surveys', (req, res) => {
  const record: SurveyRecord = {
    ...req.body,
    syncStatus: 'synced',
  };
  surveys.set(record.id, record);
  res.status(201).json(record);
});

app.put('/surveys/:id', (req, res) => {
  const id = req.params.id;
  if (!surveys.has(id)) {
    return res.status(404).json({ error: 'Not found' });
  }

  const record: SurveyRecord = {
    ...req.body,
    id,
    syncStatus: 'synced',
  };

  surveys.set(id, record);
  res.json(record);
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  res.status(204).send();
});

app.listen(4000, () => {
  console.log('Server listening on http://localhost:4000');
});
