## `client/app.js`

```javascript
const DB_NAME = 'offlineSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';
const API_URL = 'http://localhost:3000/api/surveys';

let db;

function updateConnectionStatus() {
  const statusEl = document.getElementById('connectionStatus');
  statusEl.textContent = navigator.onLine ? 'Online' : 'Offline';
  statusEl.style.color = navigator.onLine ? 'green' : 'red';
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'localId', autoIncrement: true });
        store.createIndex('synced', 'synced', { unique: false });
      }
    };

    request.onsuccess = (event) => {
      db = event.target.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function updateSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(survey);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

async function renderSurveys() {
  const list = document.getElementById('surveyList');
  list.innerHTML = '';

  const surveys = await getAllSurveys();
  surveys.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const survey of surveys) {
    const li = document.createElement('li');
    li.innerHTML = `
      <div><strong>${escapeHtml(survey.surveyorName)}</strong></div>
      <div>Location: ${escapeHtml(survey.location)}</div>
      <div>Observation: ${escapeHtml(survey.observation)}</div>
      <div>Coords: ${survey.latitude ?? '-'}, ${survey.longitude ?? '-'}</div>
      <div>Created: ${new Date(survey.createdAt).toLocaleString()}</div>
      <div class="${survey.synced ? 'synced' : 'pending'}">
        ${survey.synced ? 'Synced' : 'Pending Sync'}
      </div>
    `;
    list.appendChild(li);
  }
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (m) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[m]));
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter(s => !s.synced);

  for (const survey of pending) {
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (!response.ok) {
        throw new Error(`Sync failed with status ${response.status}`);
      }

      const result = await response.json();
      survey.synced = true;
      survey.serverId = result.id;
      survey.syncedAt = new Date().toISOString();

      await updateSurvey(survey);
    } catch (error) {
      console.error('Failed to sync survey', survey.localId, error);
    }
  }

  await renderSurveys();
}

async function handleSubmit(event) {
  event.preventDefault();

  const survey = {
    surveyorName: document.getElementById('surveyorName').value.trim(),
    location: document.getElementById('location').value.trim(),
    observation: document.getElementById('observation').value.trim(),
    latitude: parseFloat(document.getElementById('latitude').value) || null,
    longitude: parseFloat(document.getElementById('longitude').value) || null,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addSurvey(survey);
  document.getElementById('surveyForm').reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
}

async function init() {
  updateConnectionStatus();
  window.addEventListener('online', async () => {
    updateConnectionStatus();
    await syncPendingSurveys();
  });
  window.addEventListener('offline', updateConnectionStatus);

  document.getElementById('surveyForm').addEventListener('submit', handleSubmit);
  document.getElementById('syncBtn').addEventListener('click', syncPendingSurveys);

  await openDB();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
}

init();
```

