```javascript
import { openDB } from 'idb';

const DB_NAME = 'survey-db';
const DB_VERSION = 1;
const SURVEYS_STORE = 'surveys';

export async function initDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(SURVEYS_STORE)) {
        const store = db.createObjectStore(SURVEYS_STORE, { keyPath: 'localId' });
        store.createIndex('synced', 'synced');
        store.createIndex('updatedAt', 'updatedAt');
      }
    }
  });
}

export async function saveSurveyLocally(survey) {
  const db = await initDB();
  await db.put(SURVEYS_STORE, survey);
}

export async function getAllSurveys() {
  const db = await initDB();
  return db.getAll(SURVEYS_STORE);
}

export async function getUnsyncedSurveys() {
  const db = await initDB();
  return db.getAllFromIndex(SURVEYS_STORE, 'synced', 0);
}

export async function markSurveySynced(localId, serverId) {
  const db = await initDB();
  const survey = await db.get(SURVEYS_STORE, localId);
  if (!survey) return;

  survey.synced = 1;
  survey.serverId = serverId;
  survey.lastSyncedAt = new Date().toISOString();

  await db.put(SURVEYS_STORE, survey);
}
```

