## `client/src/sync.js`

This handles syncing unsynced records when online.

```javascript
import { getUnsyncedSurveys, markSurveySynced } from './db';

const API_URL = 'http://localhost:4000/api/surveys';

export async function syncSurveys() {
  if (!navigator.onLine) {
    console.log('Offline, skipping sync');
    return;
  }

  const unsynced = await getUnsyncedSurveys();
  if (!unsynced.length) {
    console.log('No unsynced surveys');
    return;
  }

  for (const survey of unsynced) {
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(survey)
      });

      if (!response.ok) {
        throw new Error(`Sync failed: ${response.status}`);
      }

      const result = await response.json();
      await markSurveySynced(survey.localId, result.id);
      console.log(`Synced survey ${survey.localId}`);
    } catch (error) {
      console.error(`Failed to sync survey ${survey.localId}`, error);
    }
  }
}

export function setupSyncListeners() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncSurveys();
  });
}
```

