```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 4000;

// In-memory store for initial implementation
// Replace with a real DB in production
const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id: string,
 *   title: string,
 *   location: string,
 *   notes: string,
 *   createdAt: string,
 *   updatedAt: string
 * }
 */

// Health check
app.get('/health', (req, res) => {
  res.json({ ok: true });
});

// Get all surveys
app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

// Bulk sync endpoint
app.post('/sync', (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: 'records must be an array' });
  }

  const accepted = [];
  const rejected = [];

  for (const record of records) {
    if (!record.id || !record.title) {
      rejected.push({
        id: record.id || null,
        reason: 'Missing required fields'
      });
      continue;
    }

    const existing = surveys.get(record.id);

    if (!existing) {
      surveys.set(record.id, {
        id: record.id,
        title: record.title,
        location: record.location || '',
        notes: record.notes || '',
        createdAt: record.createdAt || new Date().toISOString(),
        updatedAt: record.updatedAt || new Date().toISOString()
      });
      accepted.push(record.id);
    } else {
      // Last-write-wins using updatedAt
      const incomingTime = new Date(record.updatedAt || 0).getTime();
      const existingTime = new Date(existing.updatedAt || 0).getTime();

      if (incomingTime >= existingTime) {
        surveys.set(record.id, {
          ...existing,
          ...record
        });
        accepted.push(record.id);
      } else {
        rejected.push({
          id: record.id,
          reason: 'Server has newer version'
        });
      }
    }
  }

  res.json({
    accepted,
    rejected,
    serverCount: surveys.size
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

