## `client/src/db.js`
```js
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const STORE_NAME = 'surveys';

export async function initDB() {
  return openDB(DB_NAME, 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('by_synced', 'synced');
        store.createIndex('by_updatedAt', 'updatedAt');
      }
    }
  });
}

export async function getAllSurveys() {
  const db = await initDB();
  return db.getAll(STORE_NAME);
}

export async function saveSurvey(survey) {
  const db = await initDB();
  await db.put(STORE_NAME, survey);
  return survey;
}

export async function getUnsyncedSurveys() {
  const db = await initDB();
  return db.getAllFromIndex(STORE_NAME, 'by_synced', false);
}

export async function markSurveySynced(id) {
  const db = await initDB();
  const survey = await db.get(STORE_NAME, id);
  if (!survey) return;
  survey.synced = true;
  await db.put(STORE_NAME, survey);
}

export async function bulkMarkSynced(ids) {
  const db = await initDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  for (const id of ids) {
    const survey = await tx.store.get(id);
    if (survey) {
      survey.synced = true;
      await tx.store.put(survey);
    }
  }
  await tx.done;
}
```

