## `client/src/sync.js`
```js
import { getUnsyncedSurveys, bulkMarkSynced } from './db';
import { syncRecords } from './api';

let syncInProgress = false;

export async function syncPendingSurveys() {
  if (syncInProgress) return { skipped: true };
  if (!navigator.onLine) return { offline: true };

  syncInProgress = true;

  try {
    const unsynced = await getUnsyncedSurveys();

    if (unsynced.length === 0) {
      return { synced: 0 };
    }

    const result = await syncRecords(
      unsynced.map(({ synced, ...rest }) => rest)
    );

    if (result.accepted?.length) {
      await bulkMarkSynced(result.accepted);
    }

    return {
      synced: result.accepted?.length || 0,
      rejected: result.rejected || []
    };
  } finally {
    syncInProgress = false;
  }
}
```

