  longitude: number | null;
  updatedAt: string;
  createdAt: string;
  syncStatus: 'pending' | 'synced' | 'failed';
  deleted?: boolean;
};
```

A sync queue item:

```ts
type SyncQueueItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  createdAt: string;
  retryCount: number;
};
```

