## `server/index.js`

```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 4000;

// In-memory DB for initial implementation
const surveys = new Map();

/**
 * Upsert survey
 */
app.post('/api/surveys/sync', (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: 'records must be an array' });
  }

  const results = [];

  for (const record of records) {
    const existing = surveys.get(record.id);

    // Simple last-write-wins conflict resolution
    if (
      !existing ||
      new Date(record.updatedAt).getTime() >= new Date(existing.updatedAt).getTime()
    ) {
      if (record.deleted) {
        surveys.delete(record.id);
      } else {
        surveys.set(record.id, record);
      }

      results.push({
        id: record.id,
        status: 'synced'
      });
    } else {
      results.push({
        id: record.id,
        status: 'conflict',
        serverRecord: existing
      });
    }
  }

  res.json({ results });
});

/**
 * Fetch all surveys
 */
app.get('/api/surveys', (req, res) => {
  res.json({
    records: Array.from(surveys.values())
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

