  await db.put('syncQueue', item);
}

export async function getSyncQueueItems() {
  const db = await dbPromise;
  return db.getAll('syncQueue');
}

export async function removeSyncQueueItem(id) {
  const db = await dbPromise;
  await db.delete('syncQueue', id);
}

export async function markSurveySynced(id) {
  const db = await dbPromise;
  const survey = await db.get('surveys', id);
  if (!survey) return;

  if (survey.deleted) {
    await db.delete('surveys', id);
  } else {
    await db.put('surveys', {
      ...survey,
      syncStatus: 'synced'
    });
  }
}

export async function markSurveyFailed(id) {
  const db = await dbPromise;
  const survey = await db.get('surveys', id);
  if (!survey) return;

  await db.put('surveys', {
    ...survey,
    syncStatus: 'failed'
  });
}
