# 6. Sync service

This is the core offline sync logic.

## `client/src/sync.js`

```js
import {
  getSyncQueueItems,
  removeSyncQueueItem,
  markSurveySynced,
  markSurveyFailed
} from './storage';

const API_BASE = 'http://localhost:4000/api';

let syncInProgress = false;

export async function syncPendingChanges() {
  if (syncInProgress || !navigator.onLine) return;

  syncInProgress = true;

  try {
    const queueItems = await getSyncQueueItems();
    if (queueItems.length === 0) return;

    // Send queued payloads as records
    const records = queueItems.map((item) => item.payload);

    const response = await fetch(`${API_BASE}/surveys/sync`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ records })
    });

    if (!response.ok) {
      throw new Error(`Sync failed with status ${response.status}`);
    }

    const data = await response.json();

    for (const result of data.results) {
      const queueItem = queueItems.find((q) => q.entityId === result.id);
      if (!queueItem) continue;

      if (result.status === 'synced') {
        await markSurveySynced(result.id);
        await removeSyncQueueItem(queueItem.id);
      } else if (result.status === 'conflict') {
        await markSurveyFailed(result.id);
      }
    }
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncInProgress = false;
  }
}

export function setupSyncListeners() {
  window.addEventListener('online', () => {
    syncPendingChanges();
  });
}
```

