# 7. Survey operations

## `client/src/surveyService.js`

```js
import { v4 as uuidv4 } from 'uuid';
import {
  saveSurvey,
  addToSyncQueue,
  deleteSurveyLocal
} from './storage';
import { syncPendingChanges } from './sync';

export async function createSurvey({ title, notes, latitude, longitude }) {
  const now = new Date().toISOString();

  const record = {
    id: uuidv4(),
    title,
    notes,
    latitude,
    longitude,
    createdAt: now,
    updatedAt: now,
    syncStatus: 'pending'
  };

  await saveSurvey(record);

  await addToSyncQueue({
    id: uuidv4(),
    entityType: 'survey',
    entityId: record.id,
    operation: 'create',
    payload: record,
    createdAt: now,
    retryCount: 0
  });

  if (navigator.onLine) {
    syncPendingChanges();
  }

  return record;
}

export async function updateSurvey(existing, updates) {
  const updated = {
    ...existing,
    ...updates,
    updatedAt: new Date().toISOString(),
    syncStatus: 'pending'
  };

  await saveSurvey(updated);

  await addToSyncQueue({
    id: uuidv4(),
    entityType: 'survey',
    entityId: updated.id,
    operation: 'update',
    payload: updated,
    createdAt: new Date().toISOString(),
    retryCount: 0
  });

  if (navigator.onLine) {
    syncPendingChanges();
  }

  return updated;
}

export async function deleteSurvey(record) {
  await deleteSurveyLocal(record.id);

  await addToSyncQueue({
    id: uuidv4(),
    entityType: 'survey',
    entityId: record.id,
    operation: 'delete',
    payload: {
      ...record,
      deleted: true,
      updatedAt: new Date().toISOString()
    },
    createdAt: new Date().toISOString(),
    retryCount: 0
  });

  if (navigator.onLine) {
    syncPendingChanges();
  }
}
```

