# 8. React UI

## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from 'react';
import { getAllSurveys } from './storage';
import { createSurvey, deleteSurvey } from './surveyService';
import { setupSyncListeners, syncPendingChanges } from './sync';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const records = await getAllSurveys();
    setSurveys(records.filter((r) => !r.deleted));
  }

  useEffect(() => {
    loadSurveys();
    setupSyncListeners();

    const onOnline = () => {
      setOnline(true);
      syncPendingChanges().then(loadSurveys);
    };

    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    if (navigator.onLine) {
      syncPendingChanges().then(loadSurveys);
    }

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function handleCreate(e) {
    e.preventDefault();

    await createSurvey({
      title,
      notes,
      latitude: null,
      longitude: null
    });

    setTitle('');
    setNotes('');
    await loadSurveys();
  }

  async function handleDelete(record) {
    await deleteSurvey(record);
    await loadSurveys();
  }

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{online ? 'Online' : 'Offline'}</strong></p>

      <form onSubmit={handleCreate} style={{ marginBottom: 20 }}>
        <div>
          <input
            placeholder="Survey title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
          />
        </div>
        <div>
          <textarea
            placeholder="Notes"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul>
          {surveys.map((survey) => (
            <li key={survey.id} style={{ marginBottom: 12 }}>
              <strong>{survey.title}</strong>
              <div>{survey.notes}</div>
              <div>
                Sync status: <em>{survey.syncStatus}</em>
              </div>
              <button onClick={() => handleDelete(survey)}>Delete</button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
