## `client/src/db.js`

```js
import { openDB } from "idb";

const DB_NAME = "survey-offline-db";
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      const surveyStore = db.createObjectStore("surveys", { keyPath: "id" });
      surveyStore.createIndex("updatedAt", "updatedAt");
    }

    if (!db.objectStoreNames.contains("outbox")) {
      const outboxStore = db.createObjectStore("outbox", { keyPath: "opId" });
      outboxStore.createIndex("synced", "synced");
      outboxStore.createIndex("timestamp", "timestamp");
    }

    if (!db.objectStoreNames.contains("meta")) {
      db.createObjectStore("meta", { keyPath: "key" });
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll("surveys");
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  const survey = await db.get("surveys", id);
  if (!survey) return;
  survey.deleted = true;
  survey.updatedAt = Date.now();
  survey.version = (survey.version || 0) + 1;
  await db.put("surveys", survey);
}

export async function addOutboxItem(item) {
  const db = await dbPromise;
  await db.put("outbox", item);
}

export async function getPendingOutboxItems() {
  const db = await dbPromise;
  const all = await db.getAll("outbox");
  return all
    .filter((item) => !item.synced)
    .sort((a, b) => a.timestamp - b.timestamp);
}

export async function markOutboxItemSynced(opId) {
  const db = await dbPromise;
  const item = await db.get("outbox", opId);
  if (!item) return;
  item.synced = true;
  await db.put("outbox", item);
}

export async function getMeta(key) {
  const db = await dbPromise;
  const value = await db.get("meta", key);
  return value?.value;
}

export async function setMeta(key, value) {
  const db = await dbPromise;
  await db.put("meta", { key, value });
}

export async function upsertManySurveys(surveys) {
  const db = await dbPromise;
  const tx = db.transaction("surveys", "readwrite");
  for (const survey of surveys) {
    await tx.store.put(survey);
  }
  await tx.done;
}
```

