## `client/src/sync.js`

```js
import {
  getPendingOutboxItems,
  markOutboxItemSynced,
  upsertManySurveys,
  getMeta,
  setMeta
} from "./db";
import { pushChanges, pullChanges } from "./api";

let syncInProgress = false;

export async function syncNow() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    const pending = await getPendingOutboxItems();

    if (pending.length > 0) {
      const pushResult = await pushChanges(pending);

      for (const opId of pushResult.appliedOpIds || []) {
        await markOutboxItemSynced(opId);
      }

      if (pushResult.serverRecords?.length) {
        await upsertManySurveys(pushResult.serverRecords);
      }
    }

    const lastPulledAt = await getMeta("lastPulledAt");
    const pullResult = await pullChanges(lastPulledAt || 0);

    if (pullResult.records?.length) {
      await upsertManySurveys(pullResult.records);
    }

    await setMeta("lastPulledAt", pullResult.serverTime || Date.now());
  } catch (err) {
    console.error("Sync failed:", err);
  } finally {
    syncInProgress = false;
  }
}
```

