import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import SurveyForm from "./components/SurveyForm";
import SurveyList from "./components/SurveyList";
import {
  getAllSurveys,
  saveSurvey,
  deleteSurveyLocal,
  addOutboxItem
} from "./db";
import { useOnlineStatus } from "./hooks/useOnlineStatus";
import { syncNow } from "./sync";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const online = useOnlineStatus();

  async function loadSurveys() {
    const data = await getAllSurveys();
    setSurveys(data);
  }

  useEffect(() => {
    loadSurveys();
  }, []);

  useEffect(() => {
    if (online) {
      syncNow().then(loadSurveys);
    }
  }, [online]);

  const handleSave = async ({ title, location, notes }) => {
    const now = Date.now();
    const survey = {
      id: uuidv4(),
      title,
      location,
      notes,
      status: "draft",
      createdAt: now,
      updatedAt: now,
      deleted: false,
      version: 1
    };

    await saveSurvey(survey);

    await addOutboxItem({
      opId: uuidv4(),
      type: "upsert",
      surveyId: survey.id,
      payload: survey,
      timestamp: now,
      synced: false
    });

    await loadSurveys();

    if (navigator.onLine) {
      await syncNow();
      await loadSurveys();
    }
  };

  const handleDelete = async (id) => {
    await deleteSurveyLocal(id);

    const surveys = await getAllSurveys();
    const survey = surveys.find((s) => s.id === id);

    await addOutboxItem({
      opId: uuidv4(),
      type: "delete",
      surveyId: id,
      payload: survey,
      timestamp: Date.now(),
      synced: false
    });

    await loadSurveys();

    if (navigator.onLine) {
      await syncNow();
      await loadSurveys();
    }
  };

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Connection status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>
      <SurveyForm onSave={handleSave} />
      <SurveyList surveys={surveys} onDelete={handleDelete} />
    </div>
  );
}
```

