## `server/index.js`

```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

function mergeSurvey(existing, incoming) {
  if (!existing) return incoming;

  // Basic last-write-wins using updatedAt
  if ((incoming.updatedAt || 0) >= (existing.updatedAt || 0)) {
    return { ...existing, ...incoming };
  }

  return existing;
}

app.post("/sync/push", (req, res) => {
  const { changes } = req.body;
  const appliedOpIds = [];
  const serverRecords = [];

  for (const change of changes || []) {
    const { opId, type, surveyId, payload } = change;
    const existing = surveys.get(surveyId);

    if (type === "upsert") {
      const merged = mergeSurvey(existing, payload);
      surveys.set(surveyId, merged);
      appliedOpIds.push(opId);
      serverRecords.push(merged);
    }

    if (type === "delete") {
      const deletedRecord = mergeSurvey(existing, {
        ...(existing || payload || { id: surveyId }),
        id: surveyId,
        deleted: true,
        updatedAt: payload?.updatedAt || Date.now(),
        version: (existing?.version || payload?.version || 0) + 1
      });

      surveys.set(surveyId, deletedRecord);
      appliedOpIds.push(opId);
      serverRecords.push(deletedRecord);
    }
  }

  res.json({
    appliedOpIds,
    serverRecords,
    serverTime: Date.now()
  });
});

app.get("/sync/pull", (req, res) => {
  const since = Number(req.query.since || 0);

  const records = Array.from(surveys.values()).filter(
    (survey) => (survey.updatedAt || 0) > since
  );

  res.json({
    records,
    serverTime: Date.now()
  });
});

app.get("/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

