```js
import express from "express";
import cors from "cors";
import { v4 as uuidv4 } from "uuid";

const app = express();
const PORT = 4000;

app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id,
 *   title,
 *   location,
 *   notes,
 *   createdAt,
 *   updatedAt
 * }
 */

app.get("/api/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post("/api/surveys", (req, res) => {
  const { id, title, location, notes, createdAt, updatedAt } = req.body;

  const surveyId = id || uuidv4();
  const now = new Date().toISOString();

  const survey = {
    id: surveyId,
    title: title || "",
    location: location || "",
    notes: notes || "",
    createdAt: createdAt || now,
    updatedAt: updatedAt || now
  };

  surveys.set(surveyId, survey);
  res.status(201).json(survey);
});

app.put("/api/surveys/:id", (req, res) => {
  const id = req.params.id;
  const existing = surveys.get(id);

  if (!existing) {
    return res.status(404).json({ error: "Survey not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id,
    updatedAt: new Date().toISOString()
  };

  surveys.set(id, updated);
  res.json(updated);
});

app.post("/api/sync", (req, res) => {
  const { operations } = req.body;

  if (!Array.isArray(operations)) {
    return res.status(400).json({ error: "operations must be an array" });
  }

  const results = [];

  for (const op of operations) {
    if (op.type === "create") {
      const survey = {
        ...op.data,
        id: op.data.id || uuidv4(),
        createdAt: op.data.createdAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      surveys.set(survey.id, survey);
      results.push({ success: true, type: "create", id: survey.id, survey });
    } else if (op.type === "update") {
      const existing = surveys.get(op.id);
      if (!existing) {
        results.push({ success: false, type: "update", id: op.id, error: "Not found" });
        continue;
      }

      const updated = {
        ...existing,
        ...op.data,
        id: op.id,
        updatedAt: new Date().toISOString()
      };
      surveys.set(op.id, updated);
      results.push({ success: true, type: "update", id: op.id, survey: updated });
    } else {
      results.push({ success: false, error: "Unknown operation type" });
    }
  }

  res.json({ success: true, results });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

