# 4. IndexedDB local database

## `client/src/db.js`

```js
import { openDB } from "idb";

const DB_NAME = "field-survey-db";
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      db.createObjectStore("surveys", { keyPath: "id" });
    }

    if (!db.objectStoreNames.contains("syncQueue")) {
      db.createObjectStore("syncQueue", { keyPath: "queueId", autoIncrement: true });
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll("surveys");
}

export async function saveSurveyLocally(survey) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function enqueueSyncOperation(operation) {
  const db = await dbPromise;
  await db.add("syncQueue", {
    ...operation,
    queuedAt: new Date().toISOString()
  });
}

export async function getQueuedOperations() {
  const db = await dbPromise;
  return db.getAll("syncQueue");
}

export async function clearQueuedOperation(queueId) {
  const db = await dbPromise;
  await db.delete("syncQueue", queueId);
}

export async function replaceLocalSurveys(surveys) {
  const db = await dbPromise;
  const tx = db.transaction("surveys", "readwrite");
  await tx.store.clear();
  for (const survey of surveys) {
    await tx.store.put(survey);
  }
  await tx.done;
}
```

