# 6. Sync logic

## `client/src/sync.js`

```js
import {
  getQueuedOperations,
  clearQueuedOperation,
  replaceLocalSurveys
} from "./db";
import { syncOperations, fetchRemoteSurveys } from "./api";

let syncing = false;

export async function runSync() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const queued = await getQueuedOperations();

    if (queued.length > 0) {
      const payload = queued.map(({ queueId, ...rest }) => rest);
      const result = await syncOperations(payload);

      for (const item of queued) {
        await clearQueuedOperation(item.queueId);
      }

      console.log("Sync result:", result);
    }

    const remoteSurveys = await fetchRemoteSurveys();
    await replaceLocalSurveys(remoteSurveys);
  } catch (err) {
    console.error("Sync failed:", err);
  } finally {
    syncing = false;
  }
}

export function setupAutoSync() {
  window.addEventListener("online", () => {
    runSync();
  });
}
```

