import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import {
  getAllSurveys,
  saveSurveyLocally,
  enqueueSyncOperation
} from "./db";
import { fetchRemoteSurveys } from "./api";
import { runSync, setupAutoSync } from "./sync";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [status, setStatus] = useState(navigator.onLine ? "Online" : "Offline");

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)));
  }

  async function initialLoad() {
    await loadLocal();

    if (navigator.onLine) {
      try {
        const remote = await fetchRemoteSurveys();
        setSurveys(remote.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)));
      } catch (err) {
        console.error("Remote fetch failed, using local data", err);
      }
    }
  }

  useEffect(() => {
    initialLoad();
    setupAutoSync();

    const goOnline = () => setStatus("Online");
    const goOffline = () => setStatus("Offline");

    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);

    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const survey = {
      id: uuidv4(),
      title,
      location,
      notes,
      createdAt: now,
      updatedAt: now
    };

    await saveSurveyLocally(survey);
    await enqueueSyncOperation({
      type: "create",
      data: survey
    });

    setTitle("");
    setLocation("");
    setNotes("");

    await loadLocal();

    if (navigator.onLine) {
      await runSync();
      await loadLocal();
    }
  }

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif", maxWidth: 800, margin: "0 auto" }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{status}</strong></p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 12, marginBottom: 24 }}>
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Survey title"
          required
        />
        <input
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          placeholder="Location"
          required
        />
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Notes"
          rows={4}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {surveys.map((survey) => (
            <li
              key={survey.id}
              style={{
                border: "1px solid #ccc",
                padding: 12,
                borderRadius: 8,
                marginBottom: 12
              }}
            >
