import React, { useEffect, useState } from 'react';
import { addSurvey, getAllSurveys, getUnsyncedSurveys, markSurveySynced } from './db';
import { syncSurveyToServer } from './api';

function App() {
  const [form, setForm] = useState({
    surveyor: '',
    location: '',
    notes: '',
  });
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [syncing, setSyncing] = useState(false);

  async function loadSurveys() {
    const all = await getAllSurveys();
    all.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setSurveys(all);
  }

  useEffect(() => {
    loadSurveys();

    const handleOnline = async () => {
      setOnline(true);
      await syncPendingSurveys();
    };

    const handleOffline = () => {
      setOnline(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      localId: crypto.randomUUID(),
      surveyor: form.surveyor,
      location: form.location,
      notes: form.notes,
      createdAt: new Date().toISOString(),
      synced: false,
    };

    await addSurvey(survey);
    setForm({ surveyor: '', location: '', notes: '' });
    await loadSurveys();

    if (navigator.onLine) {
      await syncPendingSurveys();
    }
  }

  async function syncPendingSurveys() {
    if (syncing) return;
    setSyncing(true);

    try {
      const unsynced = await getUnsyncedSurveys();

      for (const survey of unsynced) {
        try {
          const result = await syncSurveyToServer(survey);
          await markSurveySynced(survey.localId, result.id);
        } catch (err) {
          console.error('Sync failed for survey', survey.localId, err);
        }
      }

      await loadSurveys();
    } finally {
      setSyncing(false);
    }
  }

  return (
    <div style={{ maxWidth: 700, margin: '0 auto', padding: 20, fontFamily: 'Arial' }}>
      <h1>Field Survey App</h1>

      <div style={{ marginBottom: 16 }}>
        <strong>Status:</strong>{' '}
        <span style={{ color: online ? 'green' : 'red' }}>
          {online ? 'Online' : 'Offline'}
        </span>
      </div>

      <form onSubmit={handleSubmit} style={{ marginBottom: 24 }}>
        <div style={{ marginBottom: 8 }}>
          <input
            type="text"
            placeholder="Surveyor name"
            value={form.surveyor}
            onChange={(e) => setForm({ ...form, surveyor: e.target.value })}
            required
            style={{ width: '100%', padding: 8 }}
          />
        </div>

        <div style={{ marginBottom: 8 }}>
          <input
            type="text"
            placeholder="Location"
            value={form.location}
            onChange={(e) => setForm({ ...form, location: e.target.value })}
            required
            style={{ width: '100%', padding: 8 }}
          />
        </div>

        <div style={{ marginBottom: 8 }}>
          <textarea
            placeholder="Notes"
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
            rows={4}
            style={{ width: '100%', padding: 8 }}
          />
        </div>

        <button type="submit" style={{ marginRight: 8 }}>
          Save Survey
        </button>

        <button type="button" onClick={syncPendingSurveys} disabled={!online || syncing}>
          {syncing ? 'Syncing...' : 'Sync Now'}
        </button>
      </form>

      <h2>Saved Surveys</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {surveys.map((survey) => (
          <li
            key={survey.localId}
            style={{
              border: '1px solid #ccc',
              padding: 12,
              marginBottom: 10,
              borderRadius: 6,
            }}
          >
            <div><strong>Surveyor:</strong> {survey.surveyor}</div>
            <div><strong>Location:</strong> {survey.location}</div>
            <div><strong>Notes:</strong> {survey.notes}</div>
            <div><strong>Created:</strong> {new Date(survey.createdAt).toLocaleString()}</div>
            <div>
              <strong>Sync:</strong>{' '}
              <span style={{ color: survey.synced ? 'green' : 'orange' }}>
                {survey.synced ? 'Synced' : 'Pending'}
              </span>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

