import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const queueStore = db.createObjectStore('syncQueue', { keyPath: 'id' });
      queueStore.createIndex('synced', 'synced');
      queueStore.createIndex('createdAt', 'createdAt');
    }

    if (!db.objectStoreNames.contains('meta')) {
      db.createObjectStore('meta', { keyPath: 'key' });
    }
  },
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  return db.put('surveys', survey);
}

export async function getSurvey(id) {
  const db = await dbPromise;
  return db.get('surveys', id);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  const survey = await db.get('surveys', id);
  if (!survey) return;
  survey.deleted = true;
  survey.updatedAt = new Date().toISOString();
  survey.version = (survey.version || 0) + 1;
  return db.put('surveys', survey);
}

export async function addQueueItem(item) {
  const db = await dbPromise;
  return db.put('syncQueue', item);
}

export async function getPendingQueueItems() {
  const db = await dbPromise;
  const tx = db.transaction('syncQueue', 'readonly');
  const index = tx.store.index('synced');
  return index.getAll(false);
}

export async function markQueueItemSynced(id) {
  const db = await dbPromise;
  const item = await db.get('syncQueue', id);
  if (!item) return;
  item.synced = true;
  return db.put('syncQueue', item);
}

export async function setMeta(key, value) {
  const db = await dbPromise;
  return db.put('meta', { key, value });
}

export async function getMeta(key) {
  const db = await dbPromise;
  const result = await db.get('meta', key);
  return result?.value;
}
