## 3.3 Sync engine

### `src/sync.js`

```javascript
import {
  getPendingQueueItems,
  markQueueItemSynced,
  saveSurvey,
  setMeta,
  getMeta,
} from './db';
import { pushChanges, pullChanges } from './api';

let syncInProgress = false;

export async function syncNow() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    const pending = await getPendingQueueItems();

    if (pending.length > 0) {
      const pushResult = await pushChanges(pending);

      for (const acknowledgedId of pushResult.acknowledged || []) {
        await markQueueItemSynced(acknowledgedId);
      }

      for (const serverSurvey of pushResult.updatedRecords || []) {
        await saveSurvey(serverSurvey);
      }
    }

    const lastSync = await getMeta('lastSync');
    const pullResult = await pullChanges(lastSync);

    for (const survey of pullResult.changes || []) {
      await saveSurvey(survey);
    }

    if (pullResult.serverTime) {
      await setMeta('lastSync', pullResult.serverTime);
    }
  } catch (err) {
    console.error('Sync failed:', err);
  } finally {
    syncInProgress = false;
  }
}

export function registerSyncListeners() {
  window.addEventListener('online', () => {
    syncNow();
  });
}
```

