## 3.4 Survey service

### `src/surveyService.js`

```javascript
import { v4 as uuidv4 } from 'uuid';
import { saveSurvey, addQueueItem, deleteSurveyLocal } from './db';
import { syncNow } from './sync';

export async function createSurvey({ title, location, notes }) {
  const now = new Date().toISOString();

  const survey = {
    id: uuidv4(),
    title,
    location,
    notes,
    updatedAt: now,
    version: 1,
    deleted: false,
  };

  await saveSurvey(survey);

  await addQueueItem({
    id: uuidv4(),
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    createdAt: now,
    synced: false,
  });

  syncNow();
  return survey;
}

export async function updateSurvey(existingSurvey, updates) {
  const updated = {
    ...existingSurvey,
    ...updates,
    updatedAt: new Date().toISOString(),
    version: (existingSurvey.version || 0) + 1,
  };

  await saveSurvey(updated);

  await addQueueItem({
    id: uuidv4(),
    entityType: 'survey',
    entityId: updated.id,
    operation: 'update',
    payload: updated,
    createdAt: updated.updatedAt,
    synced: false,
  });

  syncNow();
  return updated;
}

export async function deleteSurvey(surveyId) {
  await deleteSurveyLocal(surveyId);

  await addQueueItem({
    id: uuidv4(),
    entityType: 'survey',
    entityId: surveyId,
    operation: 'delete',
    payload: { id: surveyId },
    createdAt: new Date().toISOString(),
    synced: false,
  });

  syncNow();
}
