## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

function nowIso() {
  return new Date().toISOString();
}

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;
  const acknowledged = [];
  const updatedRecords = [];

  for (const change of changes || []) {
    const { id: queueId, operation, payload, entityId } = change;

    if (operation === 'create' || operation === 'update') {
      const existing = surveys.get(entityId);

      if (!existing || payload.version >= existing.version) {
        const serverRecord = {
          ...payload,
          updatedAt: nowIso(),
        };
        surveys.set(entityId, serverRecord);
        updatedRecords.push(serverRecord);
      }
    }

    if (operation === 'delete') {
      const existing = surveys.get(entityId);
      if (existing) {
        existing.deleted = true;
        existing.updatedAt = nowIso();
        existing.version = (existing.version || 0) + 1;
        surveys.set(entityId, existing);
        updatedRecords.push(existing);
      }
    }

    acknowledged.push(queueId);
  }

  res.json({
    acknowledged,
    updatedRecords,
  });
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since;
  const all = Array.from(surveys.values());

  const changes = since
    ? all.filter(record => record.updatedAt > since)
    : all;

  res.json({
    changes,
    serverTime: nowIso(),
  });
});

app.listen(4000, () => {
  console.log('Sync server listening on http://localhost:4000');
});
```

