## `surveyRepository.js` — local CRUD

```javascript
// surveyRepository.js
import { getDb } from './db';
import { randomUUID } from 'expo-crypto';

function now() {
  return new Date().toISOString();
}

export function createSurvey({ title, description, latitude, longitude }) {
  const db = getDb();
  const localId = crypto.randomUUID ? crypto.randomUUID() : String(Date.now());

  const survey = {
    local_id: localId,
    server_id: null,
    title,
    description: description || '',
    latitude: latitude ?? null,
    longitude: longitude ?? null,
    updated_at: now(),
    sync_status: 'pending',
  };

  db.runSync(
    `INSERT INTO surveys
      (local_id, server_id, title, description, latitude, longitude, updated_at, sync_status)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.local_id,
      survey.server_id,
      survey.title,
      survey.description,
      survey.latitude,
      survey.longitude,
      survey.updated_at,
      survey.sync_status,
    ]
  );

  enqueueSync('survey', localId, 'upsert', survey);
  return survey;
}

export function updateSurvey(localId, updates) {
  const db = getDb();

  const existing = db.getFirstSync(
    `SELECT * FROM surveys WHERE local_id = ?`,
    [localId]
  );

  if (!existing) throw new Error('Survey not found');

  const merged = {
    ...existing,
    ...updates,
    updated_at: now(),
    sync_status: 'pending',
  };

  db.runSync(
    `UPDATE surveys
     SET title = ?, description = ?, latitude = ?, longitude = ?, updated_at = ?, sync_status = ?
     WHERE local_id = ?`,
    [
      merged.title,
      merged.description,
      merged.latitude,
      merged.longitude,
      merged.updated_at,
      merged.sync_status,
      localId,
    ]
  );

  enqueueSync('survey', localId, 'upsert', merged);
  return merged;
}

export function listSurveys() {
  const db = getDb();
  return db.getAllSync(
    `SELECT * FROM surveys ORDER BY updated_at DESC`
  );
}

export function markSurveySynced(localId, serverId, updatedAt) {
  const db = getDb();
  db.runSync(
    `UPDATE surveys
     SET server_id = ?, sync_status = 'synced', updated_at = ?
     WHERE local_id = ?`,
    [serverId, updatedAt, localId]
  );
}

export function upsertServerSurvey(serverSurvey) {
  const db = getDb();

  const existing = db.getFirstSync(
    `SELECT * FROM surveys WHERE server_id = ?`,
    [serverSurvey.id]
  );

  if (existing) {
    db.runSync(
      `UPDATE surveys
       SET title = ?, description = ?, latitude = ?, longitude = ?, updated_at = ?, sync_status = 'synced'
       WHERE server_id = ?`,
      [
        serverSurvey.title,
        serverSurvey.description,
        serverSurvey.latitude,
        serverSurvey.longitude,
        serverSurvey.updated_at,
        serverSurvey.id,
      ]
    );
  } else {
    const localId = `server-${serverSurvey.id}`;
    db.runSync(
      `INSERT INTO surveys
       (local_id, server_id, title, description, latitude, longitude, updated_at, sync_status)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced')`,
      [
        localId,
        serverSurvey.id,
        serverSurvey.title,
        serverSurvey.description,
        serverSurvey.latitude,
        serverSurvey.longitude,
        serverSurvey.updated_at,
      ]
    );
  }
}

export function enqueueSync(entityType, entityLocalId, operation, payload) {
  const db = getDb();
  db.runSync(
    `INSERT INTO sync_queue
     (entity_type, entity_local_id, operation, payload, created_at)
     VALUES (?, ?, ?, ?, ?)`,
    [entityType, entityLocalId, operation, JSON.stringify(payload), now()]
  );
}

export function getPendingQueueItems() {
  const db = getDb();
  return db.getAllSync(
    `SELECT * FROM sync_queue ORDER BY created_at ASC`
  );
}

export function removeQueueItem(id) {
  const db = getDb();
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function getMetadata(key) {
  const db = getDb();
  const row = db.getFirstSync(`SELECT value FROM metadata WHERE key = ?`, [key]);
  return row?.value ?? null;
}

export function setMetadata(key, value) {
  const db = getDb();
  db.runSync(
    `INSERT INTO metadata (key, value)
     VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}
```

