## `syncService.js` — sync engine

```javascript
// syncService.js
import axios from 'axios';
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingQueueItems,
  removeQueueItem,
  markSurveySynced,
  upsertServerSurvey,
  getMetadata,
  setMetadata,
} from './surveyRepository';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

let syncing = false;

export async function isOnline() {
  const state = await NetInfo.fetch();
  return !!state.isConnected;
}

export async function syncAll() {
  if (syncing) return;
  syncing = true;

  try {
    const online = await isOnline();
    if (!online) return;

    await pushLocalChanges();
    await pullRemoteChanges();
  } catch (err) {
    console.error('Sync failed:', err.message);
  } finally {
    syncing = false;
  }
}

async function pushLocalChanges() {
  const queue = getPendingQueueItems();
  if (!queue.length) return;

  const payload = queue.map((item) => ({
    queueId: item.id,
    entityType: item.entity_type,
    entityLocalId: item.entity_local_id,
    operation: item.operation,
    data: JSON.parse(item.payload),
  }));

  const response = await axios.post(`${API_BASE_URL}/surveys/sync`, {
    changes: payload,
  });

  const results = response.data.results || [];

  for (const result of results) {
    if (result.success) {
      markSurveySynced(
        result.entityLocalId,
        result.serverId,
        result.updatedAt
      );
      removeQueueItem(result.queueId);
    }
  }
}

async function pullRemoteChanges() {
  const lastSync = getMetadata('lastPulledAt') || '1970-01-01T00:00:00.000Z';

  const response = await axios.get(
    `${API_BASE_URL}/surveys/since/${encodeURIComponent(lastSync)}`
  );

  const surveys = response.data.surveys || [];
  for (const survey of surveys) {
    upsertServerSurvey(survey);
  }

  setMetadata('lastPulledAt', new Date().toISOString());
}
```

