## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const { Pool } = require('pg');
const { randomUUID } = require('crypto');

const app = express();
app.use(cors());
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://postgres:postgres@localhost:5432/fieldsurvey',
});

async function initDb() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS surveys (
      id UUID PRIMARY KEY,
      client_local_id TEXT,
      title TEXT NOT NULL,
      description TEXT,
      latitude DOUBLE PRECISION,
      longitude DOUBLE PRECISION,
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
  `);
}

app.get('/surveys/since/:timestamp', async (req, res) => {
  try {
    const { timestamp } = req.params;
    const result = await pool.query(
      `SELECT * FROM surveys WHERE updated_at > $1 ORDER BY updated_at ASC`,
      [timestamp]
    );
    res.json({ surveys: result.rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch surveys' });
  }
});

app.post('/surveys/sync', async (req, res) => {
  const changes = req.body.changes || [];
  const results = [];

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    for (const change of changes) {
      if (change.entityType !== 'survey' || change.operation !== 'upsert') {
        results.push({
          queueId: change.queueId,
          entityLocalId: change.entityLocalId,
          success: false,
          error: 'Unsupported change type',
        });
        continue;
      }

      const data = change.data;
      let serverId = data.server_id;

      if (serverId) {
        const updateResult = await client.query(
          `UPDATE surveys
           SET title = $1,
               description = $2,
               latitude = $3,
               longitude = $4,
               updated_at = NOW()
           WHERE id = $5
           RETURNING *`,
          [
            data.title,
            data.description,
            data.latitude,
            data.longitude,
            serverId,
          ]
        );

        if (updateResult.rows.length) {
          results.push({
            queueId: change.queueId,
            entityLocalId: change.entityLocalId,
            serverId,
            updatedAt: updateResult.rows[0].updated_at,
            success: true,
          });
          continue;
        }
      }

      serverId = randomUUID();
      const insertResult = await client.query(
        `INSERT INTO surveys
         (id, client_local_id, title, description, latitude, longitude, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, NOW())
         RETURNING *`,
        [
          serverId,
          change.entityLocalId,
          data.title,
          data.description,
          data.latitude,
          data.longitude,
        ]
      );

      results.push({
        queueId: change.queueId,
        entityLocalId: change.entityLocalId,
        serverId,
        updatedAt: insertResult.rows[0].updated_at,
        success: true,
      });
    }

    await client.query('COMMIT');
    res.json({ results });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error(err);
    res.status(500).json({ error: 'Sync failed' });
  } finally {
    client.release();
  }
});

initDb().then(() => {
  app.listen(3000, () => {
    console.log('Server listening on port 3000');
  });
});
```

