## `App.js`
```javascript
import React, { useEffect, useState, useCallback } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';

const db = SQLite.openDatabaseSync('surveys.db');
const API_URL = 'http://YOUR_LOCAL_IP:3000';

function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      location TEXT NOT NULL,
      notes TEXT,
      createdAt TEXT NOT NULL,
      synced INTEGER NOT NULL DEFAULT 0
    );
  `);
}

function generateId() {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isConnected, setIsConnected] = useState(false);
  const [syncing, setSyncing] = useState(false);

  const loadSurveys = useCallback(() => {
    try {
      const result = db.getAllSync(
        'SELECT * FROM surveys ORDER BY datetime(createdAt) DESC;'
      );
      setSurveys(result);
    } catch (err) {
      console.error('Load surveys error:', err);
    }
  }, []);

  const saveSurveyLocally = useCallback(() => {
    if (!title.trim() || !location.trim()) {
      Alert.alert('Validation', 'Title and location are required.');
      return;
    }

    const survey = {
      id: generateId(),
      title: title.trim(),
      location: location.trim(),
      notes: notes.trim(),
      createdAt: new Date().toISOString(),
      synced: 0
    };

    try {
      db.runSync(
        `INSERT INTO surveys (id, title, location, notes, createdAt, synced)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.createdAt,
          survey.synced
        ]
      );

      setTitle('');
      setLocation('');
      setNotes('');
      loadSurveys();

      if (isConnected) {
        syncPendingSurveys();
      }
    } catch (err) {
      console.error('Save survey error:', err);
      Alert.alert('Error', 'Could not save survey locally.');
    }
  }, [title, location, notes, isConnected, loadSurveys]);

  const markSurveySynced = useCallback((id) => {
    db.runSync('UPDATE surveys SET synced = 1 WHERE id = ?;', [id]);
  }, []);

  const syncPendingSurveys = useCallback(async () => {
    if (syncing) return;

    try {
      setSyncing(true);

      const pending = db.getAllSync(
        'SELECT * FROM surveys WHERE synced = 0 ORDER BY datetime(createdAt) ASC;'
      );

      for (const survey of pending) {
        try {
          const response = await fetch(`${API_URL}/surveys`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(survey)
          });

          if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
          }

          markSurveySynced(survey.id);
        } catch (err) {
          console.error(`Failed to sync survey ${survey.id}:`, err);
          break;
        }
      }

      loadSurveys();
    } catch (err) {
      console.error('Sync error:', err);
    } finally {
      setSyncing(false);
    }
  }, [syncing, loadSurveys, markSurveySynced]);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const connected = !!state.isConnected && !!state.isInternetReachable;
      setIsConnected(connected);

      if (connected) {
        syncPendingSurveys();
      }
    });

    NetInfo.fetch().then((state) => {
      const connected = !!state.isConnected && !!state.isInternetReachable;
      setIsConnected(connected);
      if (connected) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, [loadSurveys, syncPendingSurveys]);

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Network: {isConnected ? 'Online' : 'Offline'} | Sync: {syncing ? 'In Progress' : 'Idle'}
      </Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Survey title"
          value={title}
          onChangeText={setTitle}
        />
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={location}
          onChangeText={setLocation}
        />
        <TextInput
          style={[styles.input, styles.notes]}
          placeholder="Notes"
          value={notes}
          onChangeText={setNotes}
          multiline
        />
        <Button title="Save Survey" onPress={saveSurveyLocally} />
        <View style={{ height: 10 }} />
        <Button title="Sync Now" onPress={syncPendingSurveys} />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.item}>
            <Text style={styles.itemTitle}>{item.title}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text style={styles.meta}>
              {item.createdAt} | {item.synced ? 'Synced' : 'Pending'}
            </Text>
          </View>
        )}
        ListEmptyComponent={<Text>No surveys yet.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    marginTop: 40
  },
  header: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 8
  },
  status: {
    marginBottom: 16
  },
  form: {
    marginBottom: 20
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 10,
    marginBottom: 10,
    borderRadius: 6
  },
  notes: {
    height: 80,
    textAlignVertical: 'top'
  },
  item: {
    padding: 12,
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 6,
    marginBottom: 10
  },
  itemTitle: {
    fontWeight: 'bold',
    fontSize: 16
  },
  meta: {
    marginTop: 6,
    color: '#666',
    fontSize: 12
  }
});
```

