## client/src/sync.js

This handles syncing pending records to the backend.

```javascript
import { db } from "./db";

const API_BASE = "http://localhost:4000";

export async function enqueueSync(entityType, entityId, action) {
  await db.syncQueue.add({
    entityType,
    entityId,
    action,
    createdAt: new Date().toISOString()
  });
}

export async function syncPendingData() {
  if (!navigator.onLine) return;

  const queueItems = await db.syncQueue.toArray();

  for (const item of queueItems) {
    try {
      if (item.entityType === "survey") {
        const survey = await db.surveys.get(item.entityId);
        if (!survey) {
          await db.syncQueue.delete(item.id);
          continue;
        }

        const response = await fetch(`${API_BASE}/api/surveys/sync`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify(survey)
        });

        if (!response.ok) {
          throw new Error(`Sync failed with status ${response.status}`);
        }

        await db.surveys.update(survey.id, {
          syncStatus: "synced",
          lastSyncedAt: new Date().toISOString()
        });

        await db.syncQueue.delete(item.id);
      }
    } catch (error) {
      console.error("Sync error:", error);
      break;
    }
  }
}

export function setupAutoSync() {
  window.addEventListener("online", () => {
    console.log("Back online. Syncing...");
    syncPendingData();
  });
}
```

