import { useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { db } from "./db";
import { enqueueSync, syncPendingData } from "./sync";

export default function SurveyForm({ onSaved }) {
  const [form, setForm] = useState({
    location: "",
    observer: "",
    notes: ""
  });

  async function handleSubmit(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const survey = {
      id: uuidv4(),
      location: form.location,
      observer: form.observer,
      notes: form.notes,
      createdAt: now,
      updatedAt: now,
      syncStatus: "pending"
    };

    await db.surveys.put(survey);
    await enqueueSync("survey", survey.id, "upsert");

    if (navigator.onLine) {
      await syncPendingData();
    }

    setForm({ location: "", observer: "", notes: "" });
    onSaved?.();
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>New Survey</h2>

      <div>
        <label>Location</label>
        <input
          value={form.location}
          onChange={(e) => setForm({ ...form, location: e.target.value })}
