## `sync.js` — sync engine

```js
// sync.js
import { getAll, put, remove } from "./db";

const API_BASE = "http://localhost:4000";

export async function enqueueOperation(op) {
  await put("syncQueue", op);
}

export async function syncAll() {
  if (!navigator.onLine) {
    console.log("Offline, skipping sync");
    return;
  }

  const queue = await getAll("syncQueue");

  for (const op of queue) {
    try {
      const res = await fetch(`${API_BASE}/sync/response`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(op.payload),
      });

      if (!res.ok) throw new Error("Sync failed");

      const syncedResponse = {
        ...op.payload,
        syncStatus: "synced",
      };

      await put("responses", syncedResponse);
      await remove("syncQueue", op.id);
    } catch (err) {
      console.error("Failed syncing op", op.id, err);
      await put("responses", {
        ...op.payload,
        syncStatus: "failed",
      });
    }
  }

  await pullLatestResponses();
}

export async function pullLatestResponses() {
  if (!navigator.onLine) return;

  const res = await fetch(`${API_BASE}/responses`);
  if (!res.ok) return;

  const responses = await res.json();
  for (const response of responses) {
    await put("responses", {
      ...response,
      syncStatus: "synced",
    });
  }
}
```

