## `surveyService.js` — local-first response creation

```js
// surveyService.js
import { put } from "./db";
import { enqueueOperation } from "./sync";

function uuid() {
  return crypto.randomUUID();
}

export async function saveResponseLocally({ surveyId, respondentName, answers }) {
  const now = Date.now();

  const response = {
    id: uuid(),
    surveyId,
    respondentName,
    answers,
    createdAt: now,
    updatedAt: now,
    syncStatus: "pending",
  };

  await put("responses", response);

  await enqueueOperation({
    id: uuid(),
    entityType: "response",
    operation: "create",
    payload: response,
    createdAt: now,
  });

  return response;
}
```

