import React, { useEffect, useState } from "react";
import { getAll, put } from "./db";
import { saveResponseLocally } from "./surveyService";
import { syncAll } from "./sync";
import { useOnlineStatus } from "./useOnlineStatus";

const sampleSurvey = {
  id: "survey-1",
  title: "Field Site Inspection",
  updatedAt: Date.now(),
  questions: [
    { id: "q1", type: "text", label: "Site name" },
    { id: "q2", type: "number", label: "Temperature" },
    { id: "q3", type: "choice", label: "Condition", options: ["Good", "Fair", "Poor"] },
  ],
};

export default function App() {
  const [survey, setSurvey] = useState(null);
  const [responses, setResponses] = useState([]);
  const [form, setForm] = useState({});
  const online = useOnlineStatus();

  useEffect(() => {
    async function init() {
      await put("surveys", sampleSurvey);
      setSurvey(sampleSurvey);
      const localResponses = await getAll("responses");
      setResponses(localResponses);
    }
    init();
  }, []);

  useEffect(() => {
    if (online) {
      syncAll().then(refreshResponses);
    }
  }, [online]);

  async function refreshResponses() {
    const localResponses = await getAll("responses");
    setResponses(localResponses);
  }

  async function handleSubmit(e) {
    e.preventDefault();
    await saveResponseLocally({
      surveyId: survey.id,
      respondentName: form.respondentName || "",
      answers: {
        q1: form.q1 || "",
        q2: Number(form.q2 || 0),
        q3: form.q3 || "",
      },
    });
    setForm({});
    await refreshResponses();
  }

  if (!survey) return <div>Loading...</div>;

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>{survey.title}</h1>
      <div>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </div>

      <form onSubmit={handleSubmit} style={{ marginTop: 20 }}>
        <div>
          <label>Respondent Name</label>
          <br />
          <input
            value={form.respondentName || ""}
            onChange={(e) => setForm({ ...form, respondentName: e.target.value })}
          />
        </div>

        <div>
          <label>Site name</label>
          <br />
          <input
            value={form.q1 || ""}
            onChange={(e) => setForm({ ...form, q1: e.target.value })}
          />
        </div>

        <div>
          <label>Temperature</label>
          <br />
          <input
            type="number"
            value={form.q2 || ""}
            onChange={(e) => setForm({ ...form, q2: e.target.value })}
          />
        </div>

        <div>
          <label>Condition</label>
          <br />
          <select
            value={form.q3 || ""}
            onChange={(e) => setForm({ ...form, q3: e.target.value })}
          >
            <option value="">Select</option>
            <option value="Good">Good</option>
            <option value="Fair">Fair</option>
