## `server.js`

```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const responses = new Map();

app.post("/sync/response", (req, res) => {
  const response = req.body;

  if (!response.id || !response.surveyId) {
    return res.status(400).json({ error: "Invalid response payload" });
  }

  const existing = responses.get(response.id);

  if (!existing || response.updatedAt >= existing.updatedAt) {
    responses.set(response.id, {
      ...response,
      serverReceivedAt: Date.now(),
    });
  }

  return res.json({ success: true });
});

app.get("/responses", (req, res) => {
  res.json(Array.from(responses.values()));
});

app.listen(4000, () => {
  console.log("Sync server running on http://localhost:4000");
});
```

