## `src/db/database.js`

This sets up local SQLite tables for surveys and sync queue.

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  db.transaction(tx => {
    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        location TEXT,
        notes TEXT,
        updatedAt TEXT NOT NULL,
        synced INTEGER NOT NULL
      );
    `);

    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        surveyId TEXT NOT NULL,
        action TEXT NOT NULL,
        payload TEXT NOT NULL,
        createdAt TEXT NOT NULL
      );
    `);
  });
};

export const insertSurvey = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys (id, title, location, notes, updatedAt, synced)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location || '',
          survey.notes || '',
          survey.updatedAt,
          survey.synced ? 1 : 0
        ],
        (_, result) => resolve(result),
        (_, err) => reject(err)
      );
    });
  });
};

export const getSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updatedAt DESC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const addToSyncQueue = ({ surveyId, action, payload }) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (surveyId, action, payload, createdAt)
         VALUES (?, ?, ?, ?);`,
        [surveyId, action, JSON.stringify(payload), new Date().toISOString()],
        (_, result) => resolve(result),
        (_, err) => reject(err)
      );
    });
  });
};

export const getSyncQueue = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY createdAt ASC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const clearSyncQueueItem = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?;`,
        [id],
        (_, result) => resolve(result),
        (_, err) => reject(err)
      );
    });
  });
};

export const markSurveySynced = (surveyId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?;`,
        [surveyId],
        (_, result) => resolve(result),
        (_, err) => reject(err)
      );
    });
  });
};
```

