## `src/services/surveyService.js`

Handles local survey creation and queueing sync actions.

```javascript
import { v4 as uuidv4 } from 'uuid';
import { insertSurvey, addToSyncQueue, getSurveys } from '../db/database';

export const createSurvey = async ({ title, location, notes }) => {
  const survey = {
    id: uuidv4(),
    title,
    location,
    notes,
    updatedAt: new Date().toISOString(),
    synced: false
  };

  await insertSurvey(survey);
  await addToSyncQueue({
    surveyId: survey.id,
    action: 'upsert',
    payload: survey
  });

  return survey;
};

export const listSurveys = async () => {
  return await getSurveys();
};
