## `src/services/syncService.js`

Pushes queued records to the backend when online.

```javascript
import NetInfo from '@react-native-community/netinfo';
import {
  getSyncQueue,
  clearSyncQueueItem,
  markSurveySynced
} from '../db/database';

const API_URL = 'http://YOUR_SERVER_IP:3000';

export const syncPendingSurveys = async () => {
  const netState = await NetInfo.fetch();
  if (!netState.isConnected) {
    return { synced: 0, skipped: true };
  }

  const queue = await getSyncQueue();
  let syncedCount = 0;

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      const response = await fetch(`${API_URL}/sync`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          action: item.action,
          survey: payload
        })
      });

      if (!response.ok) {
        continue;
      }

      await markSurveySynced(item.surveyId);
      await clearSyncQueueItem(item.id);
      syncedCount++;
    } catch (err) {
      console.log('Sync failed for queue item', item.id, err);
    }
  }

  return { synced: syncedCount, skipped: false };
};
```

