## `server.js`

This is a simple in-memory implementation. For production, use PostgreSQL, MySQL, or MongoDB.

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/sync', (req, res) => {
  const { action, survey } = req.body;

  if (!survey || !survey.id) {
    return res.status(400).json({ error: 'Invalid survey payload' });
  }

  if (action === 'upsert') {
    const existing = surveys.get(survey.id);

    if (!existing || new Date(survey.updatedAt) >= new Date(existing.updatedAt)) {
      surveys.set(survey.id, survey);
    }

    return res.json({ success: true, surveyId: survey.id });
  }

  return res.status(400).json({ error: 'Unsupported action' });
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

