## `db.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  db.transaction(tx => {
    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        server_id TEXT,
        title TEXT,
        location TEXT,
        notes TEXT,
        updated_at INTEGER,
        sync_status TEXT
      );
    `);

    tx.executeSql(`
      CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        survey_id TEXT NOT NULL,
        action TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at INTEGER NOT NULL
      );
    `);
  });
};

export const insertSurvey = (survey) =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
         (id, server_id, title, location, notes, updated_at, sync_status)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.server_id || null,
          survey.title,
          survey.location,
          survey.notes,
          survey.updated_at,
          survey.sync_status,
        ],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });

export const getSurveys = () =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updated_at DESC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => reject(error)
      );
    });
  });

export const enqueueSync = ({ survey_id, action, payload }) =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (survey_id, action, payload, created_at)
         VALUES (?, ?, ?, ?)`,
        [survey_id, action, JSON.stringify(payload), Date.now()],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });

export const getQueueItems = () =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY created_at ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => reject(error)
      );
    });
  });

export const removeQueueItem = (id) =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });

export const updateSurveySyncStatus = (id, sync_status, server_id = null) =>
  new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET sync_status = ?, server_id = COALESCE(?, server_id)
         WHERE id = ?`,
        [sync_status, server_id, id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });

export default db;
```

