## `syncService.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import {
  getQueueItems,
  removeQueueItem,
  updateSurveySyncStatus,
} from './db';

const API_BASE_URL = 'http://YOUR_LOCAL_IP:3000';

let syncing = false;

export const syncPendingData = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected) {
      syncing = false;
      return;
    }

    const queue = await getQueueItems();

    for (const item of queue) {
      const payload = JSON.parse(item.payload);

      try {
        const response = await axios.post(`${API_BASE_URL}/sync/survey`, {
          action: item.action,
          data: payload,
        });

        const { server_id } = response.data;

        await updateSurveySyncStatus(item.survey_id, 'synced', server_id);
        await removeQueueItem(item.id);
      } catch (err) {
        console.log('Sync failed for item', item.id, err.message);
        break;
      }
    }
  } finally {
    syncing = false;
  }
};

export const subscribeToNetworkChanges = () => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingData();
    }
  });
};
```

