export const updateSurvey = async (survey) => {
  const updated = {
    ...survey,
    updated_at: Date.now(),
    sync_status: survey.server_id ? 'pending_update' : 'pending_create',
  };

  await insertSurvey(updated);
  await enqueueSync({
    survey_id: updated.id,
    action: updated.server_id ? 'update' : 'create',
    payload: updated,
  });

  return updated;
};

export const listSurveys = async () => {
  return await getSurveys();
};
