## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync/survey', (req, res) => {
  const { action, data } = req.body;

  if (!data || !data.id) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  let existing = null;
  for (const [serverId, survey] of surveys.entries()) {
    if (survey.client_id === data.id) {
      existing = { serverId, survey };
      break;
    }
  }

  if (action === 'create') {
    if (existing) {
      return res.json({
        success: true,
        server_id: existing.serverId,
      });
    }

    const serverId = uuidv4();
    surveys.set(serverId, {
      ...data,
      client_id: data.id,
      server_updated_at: Date.now(),
    });

    return res.json({
      success: true,
      server_id: serverId,
    });
  }

  if (action === 'update') {
    if (!existing) {
      const serverId = uuidv4();
      surveys.set(serverId, {
        ...data,
        client_id: data.id,
        server_updated_at: Date.now(),
      });

      return res.json({
        success: true,
        server_id: serverId,
      });
    }

    surveys.set(existing.serverId, {
      ...existing.survey,
      ...data,
      server_updated_at: Date.now(),
    });

    return res.json({
      success: true,
      server_id: existing.serverId,
    });
  }

  return res.status(400).json({ error: 'Unknown action' });
});

app.get('/surveys', (req, res) => {
  const all = Array.from(surveys.entries()).map(([server_id, survey]) => ({
    server_id,
    ...survey,
  }));
  res.json(all);
});

app.listen(3000, () => {
  console.log('Backend listening on port 3000');
});
```

