## client/src/sync.js
This handles syncing pending queue items when online.

```javascript
import {
  getPendingQueueItems,
  markQueueItemSynced,
  updateSurveySyncStatus
} from './db';
import { syncSurveyToServer } from './api';

let syncing = false;

export async function syncPendingData() {
  if (syncing || !navigator.onLine) return;

  syncing = true;

  try {
    const pendingItems = await getPendingQueueItems();

    for (const item of pendingItems) {
      try {
        if (item.type === 'UPSERT_SURVEY') {
          await syncSurveyToServer(item.payload);
          await markQueueItemSynced(item.queueId);
          await updateSurveySyncStatus(item.payload.id, 'synced');
        }
      } catch (err) {
        console.error('Sync failed for item', item.queueId, err);
      }
    }
  } finally {
    syncing = false;
  }
}

export function setupOnlineSync() {
  window.addEventListener('online', () => {
    console.log('Back online. Syncing...');
    syncPendingData();
  });
}
```

