  if (!survey.id || !survey.location || !survey.observer) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const existing = surveys.get(survey.id);

  if (!existing || new Date(survey.updatedAt) >= new Date(existing.updatedAt)) {
    surveys.set(survey.id, {
      ...survey,
      serverReceivedAt: new Date().toISOString()
    });
  }

  res.json({
    success: true,
    survey: surveys.get(survey.id)
  });
});

app.listen(4000, () => {
