## `src/sync.js`

This manages syncing queued records.

```javascript
import { db } from './db';
import { syncSurveyToServer } from './api';

export async function processSyncQueue() {
  const queueItems = await db.syncQueue.orderBy('createdAt').toArray();

  for (const item of queueItems) {
    try {
      if (item.operation === 'create' || item.operation === 'update') {
        const survey = await db.surveys.get(item.entityId);
        if (!survey) {
          await db.syncQueue.delete(item.queueId);
          continue;
        }

        await syncSurveyToServer(survey);

        await db.surveys.update(survey.id, {
          syncStatus: 'synced',
          lastSyncedAt: new Date().toISOString()
        });

        await db.syncQueue.delete(item.queueId);
      }
    } catch (error) {
      console.error('Sync error for item', item, error);
      break;
    }
  }
}
```

