## `client/app.js`

```js
const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const listEl = document.getElementById("surveyList");

function updateOnlineStatus() {
  statusEl.textContent = navigator.onLine ? "Online" : "Offline";
  statusEl.className = "status " + (navigator.onLine ? "synced" : "pending");
}

window.addEventListener("online", async () => {
  updateOnlineStatus();
  await syncPendingSurveys();
  await renderSurveys();
});

window.addEventListener("offline", updateOnlineStatus);

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurveyLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function markSurveySynced(id) {
  const db = await openDB();
  return new Promise(async (resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(id);

    getReq.onsuccess = () => {
      const survey = getReq.result;
      if (survey) {
        survey.synced = true;
        store.put(survey);
      }
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await markSurveySynced(survey.id);
      }
    } catch (err) {
      console.error("Sync failed for survey", survey.id, err);
    }
  }
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  listEl.innerHTML = "";

  surveys.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const survey of surveys) {
    const div = document.createElement("div");
    div.className = "card";
    div.innerHTML = `
      <div><strong>${survey.name}</strong></div>
      <div>${survey.location}</div>
      <div>${survey.notes || ""}</div>
      <div>${new Date(survey.createdAt).toLocaleString()}</div>
      <div class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending sync"}
      </div>
    `;
    listEl.appendChild(div);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
    await renderSurveys();
  }
});

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("./sw.js")
    .then(() => console.log("Service worker registered"))
    .catch(console.error);
}

updateOnlineStatus();
renderSurveys().then(syncPendingSurveys).then(renderSurveys);
```

