```js
const API_URL = "http://localhost:3000";

const form = document.getElementById("surveyForm");
const statusEl = document.getElementById("status");
const pendingList = document.getElementById("pendingList");
const serverList = document.getElementById("serverList");
const syncBtn = document.getElementById("syncBtn");

const LOCAL_KEY = "offline-surveys-pending";

function getPendingSurveys() {
  return JSON.parse(localStorage.getItem(LOCAL_KEY) || "[]");
}

function savePendingSurveys(data) {
  localStorage.setItem(LOCAL_KEY, JSON.stringify(data));
}

function updateStatus() {
  if (navigator.onLine) {
    statusEl.textContent = "Online";
    statusEl.className = "status online";
  } else {
    statusEl.textContent = "Offline";
    statusEl.className = "status offline";
  }
}

function renderPending() {
  const items = getPendingSurveys();
  pendingList.innerHTML = "";

  if (items.length === 0) {
    pendingList.innerHTML = "<li>No pending surveys</li>";
    return;
  }

  items.forEach((item) => {
    const li = document.createElement("li");
    li.textContent = `${item.name} - ${item.location} - ${item.timestamp}`;
    pendingList.appendChild(li);
  });
}

async function loadServerSurveys() {
  if (!navigator.onLine) return;

  try {
    const res = await fetch(`${API_URL}/surveys`);
    const data = await res.json();

    serverList.innerHTML = "";

    if (data.length === 0) {
      serverList.innerHTML = "<li>No synced surveys yet</li>";
      return;
    }

    data.forEach((item) => {
      const li = document.createElement("li");
      li.textContent = `${item.name} - ${item.location} - ${item.timestamp}`;
      serverList.appendChild(li);
    });
  } catch (err) {
    console.error("Failed to load server surveys:", err);
  }
}

async function syncPendingSurveys() {
  const pending = getPendingSurveys();

  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when reconnected.");
    return;
  }

  if (pending.length === 0) {
    alert("No pending surveys to sync.");
    return;
  }

  try {
    const res = await fetch(`${API_URL}/surveys`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(pending)
    });

    if (!res.ok) {
      throw new Error("Sync failed");
    }

    savePendingSurveys([]);
    renderPending();
    await loadServerSurveys();
    alert("Pending surveys synced successfully.");
  } catch (err) {
    console.error("Sync error:", err);
    alert("Sync failed. Data remains stored locally.");
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    timestamp: new Date().toISOString()
  };

  const pending = getPendingSurveys();
  pending.push(survey);
  savePendingSurveys(pending);

  form.reset();
  renderPending();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
});

syncBtn.addEventListener("click", syncPendingSurveys);

window.addEventListener("online", async () => {
  updateStatus();
  await syncPendingSurveys();
  await loadServerSurveys();
});

window.addEventListener("offline", updateStatus);

updateStatus();
renderPending();
loadServerSurveys();
```

