## `client/app.js`

```js
const API_URL = 'http://localhost:3000/api/surveys';
const STORAGE_KEY = 'offline-surveys';

const form = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const networkStatus = document.getElementById('networkStatus');
const syncBtn = document.getElementById('syncBtn');

function loadLocalSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveLocalSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function renderSurveys() {
  const surveys = loadLocalSurveys();
  surveyList.innerHTML = '';

  if (surveys.length === 0) {
    surveyList.innerHTML = '<li>No surveys saved yet.</li>';
    return;
  }

  surveys.forEach((survey) => {
    const li = document.createElement('li');
    li.className = survey.synced ? 'synced' : 'pending';
    li.innerHTML = `
      <strong>${survey.name}</strong><br>
      Lat: ${survey.latitude}, Lng: ${survey.longitude}<br>
      Notes: ${survey.notes || '-'}<br>
      Status: ${survey.synced ? 'Synced' : 'Pending sync'}
    `;
    surveyList.appendChild(li);
  });
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
}

function createSurvey(data) {
  return {
    id: crypto.randomUUID(),
    ...data,
    createdAt: new Date().toISOString(),
    synced: false
  };
}

async function syncSurveys() {
  if (!navigator.onLine) {
    alert('You are offline. Sync will happen when reconnected.');
    return;
  }

  const surveys = loadLocalSurveys();
  const pending = surveys.filter((s) => !s.synced);

  if (pending.length === 0) {
    return;
  }

  try {
    const response = await fetch(`${API_URL}/sync`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) {
      throw new Error('Sync failed');
    }

    const result = await response.json();
    const acceptedIds = new Set(result.accepted);

    const updated = surveys.map((survey) =>
      acceptedIds.has(survey.id)
        ? { ...survey, synced: true }
        : survey
    );

    saveLocalSurveys(updated);
    renderSurveys();
  } catch (error) {
    console.error('Sync error:', error);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = createSurvey({
    name: document.getElementById('name').value,
    latitude: parseFloat(document.getElementById('latitude').value),
    longitude: parseFloat(document.getElementById('longitude').value),
    notes: document.getElementById('notes').value
  });

  const surveys = loadLocalSurveys();
  surveys.push(survey);
  saveLocalSurveys(surveys);

  form.reset();
  renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

syncBtn.addEventListener('click', syncSurveys);

window.addEventListener('online', async () => {
  updateNetworkStatus();
  await syncSurveys();
});

window.addEventListener('offline', updateNetworkStatus);

updateNetworkStatus();
renderSurveys();
```

