```js
import { openDB } from "idb";

const DB_NAME = "offline-survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

export async function getDb() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, {
          keyPath: "clientId"
        });
        store.createIndex("synced", "synced");
      }
    }
  });
}

export async function saveSurvey(record) {
  const db = await getDb();
  await db.put(STORE_NAME, record);
}

export async function getAllSurveys() {
  const db = await getDb();
  return db.getAll(STORE_NAME);
}

export async function getUnsyncedSurveys() {
  const db = await getDb();
  return db.getAllFromIndex(STORE_NAME, "synced", 0);
}

export async function markSynced(clientId) {
  const db = await getDb();
  const record = await db.get(STORE_NAME, clientId);
  if (!record) return;
  record.synced = 1;
  await db.put(STORE_NAME, record);
}
```

## `client/src/sync.js`

```js
import { getUnsyncedSurveys, markSynced } from "./db";

const API_URL = "http://localhost:4000";

export async function syncSurveys() {
  if (!navigator.onLine) {
    return { success: false, message: "Offline" };
  }

  const unsynced = await getUnsyncedSurveys();

  if (unsynced.length === 0) {
    return { success: true, message: "Nothing to sync" };
  }

  const response = await fetch(`${API_URL}/sync`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ records: unsynced })
  });

  if (!response.ok) {
    throw new Error("Sync failed");
  }

  const result = await response.json();

  for (const record of unsynced) {
    await markSynced(record.clientId);
  }

  return {
    success: true,
    message: `Synced ${result.syncedCount} record(s)`
  };
}
```

## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import { getAllSurveys, saveSurvey } from "./db";
import { syncSurveys } from "./sync";

function App() {
  const [form, setForm] = useState({
    surveyor: "",
    location: "",
    notes: ""
  });
  const [records, setRecords] = useState([]);
  const [status, setStatus] = useState("Idle");
  const [online, setOnline] = useState(navigator.onLine);

  async function loadRecords() {
    const all = await getAllSurveys();
    all.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setRecords(all);
  }

  useEffect(() => {
    loadRecords();

    const handleOnline = async () => {
      setOnline(true);
      setStatus("Back online. Syncing...");
      try {
        const result = await syncSurveys();
        setStatus(result.message);
        await loadRecords();
      } catch (err) {
        setStatus("Sync error");
      }
    };

    const handleOffline = () => {
      setOnline(false);
      setStatus("Offline mode");
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    if (navigator.onLine) {
      syncSurveys()
        .then((result) => setStatus(result.message))
        .catch(() => setStatus("Initial sync failed"));
    } else {
      setStatus("Offline mode");
    }

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const record = {
      clientId: crypto.randomUUID(),
      surveyor: form.surveyor,
      location: form.location,
      notes: form.notes,
      createdAt: new Date().toISOString(),
      synced: 0
    };

    await saveSurvey(record);
    setForm({ surveyor: "", location: "", notes: "" });
    await loadRecords();

    if (navigator.onLine) {
      try {
        setStatus("Syncing...");
        const result = await syncSurveys();
        setStatus(result.message);
        await loadRecords();
      } catch {
        setStatus("Saved locally; sync failed");
      }
    } else {
      setStatus("Saved locally; waiting for connection");
    }
  }

  return (
    <div className="app">
      <h1>Field Survey App</h1>

      <div className={`banner ${online ? "online" : "offline"}`}>
        {online ? "Online" : "Offline"}
      </div>

      <form onSubmit={handleSubmit} className="card">
        <h2>New Survey</h2>

        <label>
          Surveyor
          <input
            value={form.surveyor}
            onChange={(e) => setForm({ ...form, surveyor: e.target.value })}
            required
          />
        </label>

        <label>
          Location
          <input
            value={form.location}
            onChange={(e) => setForm({ ...form, location: e.target.value })}
            required
          />
        </label>

        <label>
          Notes
          <textarea
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
          />
        </label>

        <button type="submit">Save Survey</button>
      </form>

      <div className="card">
        <h2>Status</h2>
        <p>{status}</p>
      </div>

      <div className="card">
        <h2>Local Records</h2>
        {records.length === 0 ? (
          <p>No surveys yet.</p>
        ) : (
          <ul className="records">
            {records.map((r) => (
              <li key={r.clientId}>
                <strong>{r.location}</strong> by {r.surveyor}
                <div>{r.notes}</div>
                <small>
                  {new Date(r.createdAt).toLocaleString()} ·{" "}
                  {r.synced ? "Synced" : "Pending sync"}
                </small>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default App;
```

