# 5. `public/app.js`

```js
const form = document.getElementById('surveyForm');
const statusEl = document.getElementById('status');
const pendingList = document.getElementById('pendingList');
const syncedList = document.getElementById('syncedList');

const PENDING_KEY = 'pendingSurveys';
const SYNCED_KEY = 'localSyncedSurveys';

function getPending() {
  return JSON.parse(localStorage.getItem(PENDING_KEY) || '[]');
}

function setPending(data) {
  localStorage.setItem(PENDING_KEY, JSON.stringify(data));
}

function getLocalSynced() {
  return JSON.parse(localStorage.getItem(SYNCED_KEY) || '[]');
}

function setLocalSynced(data) {
  localStorage.setItem(SYNCED_KEY, JSON.stringify(data));
}

function render() {
  const pending = getPending();
  const synced = getLocalSynced();

  pendingList.innerHTML = '';
  syncedList.innerHTML = '';

  pending.forEach(item => {
    const li = document.createElement('li');
    li.textContent = `${item.name} @ ${item.location} (${item.timestamp})`;
    pendingList.appendChild(li);
  });

  synced.forEach(item => {
    const li = document.createElement('li');
    li.textContent = `${item.name} @ ${item.location} (${item.timestamp})`;
    syncedList.appendChild(li);
  });
}

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'status online';
    syncPending();
    fetchServerSurveys();
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'status offline';
  }
}

async function saveSurvey(survey) {
  if (!navigator.onLine) {
    const pending = getPending();
    pending.push(survey);
    setPending(pending);
    render();
    return;
  }

  try {
    const res = await fetch('/api/surveys', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(survey)
    });

    if (!res.ok) throw new Error('Failed to save');

    const data = await res.json();
    const synced = getLocalSynced();
    synced.push(data.survey);
    setLocalSynced(synced);
    render();
  } catch (err) {
    const pending = getPending();
    pending.push(survey);
    setPending(pending);
    render();
  }
}

async function syncPending() {
  const pending = getPending();
  if (!pending.length) return;

  const remaining = [];
  const synced = getLocalSynced();

  for (const survey of pending) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error('Sync failed');

      const data = await res.json();
      synced.push(data.survey);
    } catch (err) {
      remaining.push(survey);
    }
  }

  setPending(remaining);
  setLocalSynced(synced);
  render();
}

async function fetchServerSurveys() {
  if (!navigator.onLine) return;

  try {
    const res = await fetch('/api/surveys');
    const data = await res.json();
    setLocalSynced(data);
    render();
  } catch (err) {
    console.error('Failed to fetch server surveys', err);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(),
    name: document.getElementById('name').value,
    location: document.getElementById('location').value,
    notes: document.getElementById('notes').value,
    timestamp: new Date().toISOString()
  };

  await saveSurvey(survey);
  form.reset();
});

window.addEventListener('online', updateOnlineStatus);
window.addEventListener('offline', updateOnlineStatus);

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js')
    .catch(err => console.error('SW registration failed', err));
}

render();
updateOnlineStatus();
```

