## `client/app.js`

```js
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000";

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function saveEntry(entry) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(entry);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllEntries() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function renderEntries() {
  const entries = await getAllEntries();
  const list = document.getElementById("entriesList");
  list.innerHTML = "";

  entries.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const entry of entries) {
    const li = document.createElement("li");
    li.className = entry.synced ? "synced" : "pending";
    li.innerHTML = `
      <strong>${entry.name}</strong> - ${entry.location}<br/>
      <small>${entry.createdAt}</small><br/>
      <div>${entry.notes}</div>
      <em>${entry.synced ? "Synced" : "Pending sync"}</em>
    `;
    list.appendChild(li);
  }
}

function updateNetworkStatus() {
  const el = document.getElementById("networkStatus");
  el.textContent = navigator.onLine ? "Online" : "Offline";
  el.style.color = navigator.onLine ? "green" : "red";
}

async function syncEntries() {
  if (!navigator.onLine) return;

  const entries = await getAllEntries();
  const pending = entries.filter((e) => !e.synced);

  if (pending.length === 0) return;

  try {
    const res = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ entries: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    const data = await res.json();
    const acceptedIds = new Set(data.accepted);

    for (const entry of pending) {
      if (acceptedIds.has(entry.id)) {
        entry.synced = true;
        await saveEntry(entry);
      }
    }

    await renderEntries();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

function makeId() {
  return crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random());
}

async function init() {
  await openDB();
  updateNetworkStatus();
  await renderEntries();

  document.getElementById("surveyForm").addEventListener("submit", async (e) => {
    e.preventDefault();

    const entry = {
      id: makeId(),
      name: document.getElementById("name").value,
      location: document.getElementById("location").value,
      notes: document.getElementById("notes").value,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveEntry(entry);
    e.target.reset();
    await renderEntries();

    if (navigator.onLine) {
      await syncEntries();
    }
  });

  document.getElementById("syncBtn").addEventListener("click", syncEntries);

  window.addEventListener("online", async () => {
    updateNetworkStatus();
    await syncEntries();
  });

  window.addEventListener("offline", updateNetworkStatus);
}

init();
```

