# 5. `public/app.js`

```js
const DB_NAME = 'survey-db';
const STORE_NAME = 'surveys';
const dbVersion = 1;

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, dbVersion);

    request.onupgradeneeded = (event) => {
      const database = event.target.result;
      if (!database.objectStoreNames.contains(STORE_NAME)) {
        const store = database.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('synced', 'synced', { unique: false });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function updateSurvey(survey) {
  return addSurvey(survey);
}

async function renderSurveys() {
  const list = document.getElementById('recordsList');
  const surveys = await getAllSurveys();

  list.innerHTML = '';

  if (surveys.length === 0) {
    list.innerHTML = '<li>No local records yet.</li>';
    return;
  }

  surveys.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const survey of surveys) {
    const li = document.createElement('li');
    li.textContent = `${survey.name} - ${survey.location} - ${survey.synced ? 'Synced' : 'Pending sync'}`;
    list.appendChild(li);
  }
}

function updateNetworkStatus() {
  const el = document.getElementById('networkStatus');
  if (navigator.onLine) {
    el.textContent = 'Online';
    el.className = 'status online';
  } else {
    el.textContent = 'Offline';
    el.className = 'status offline';
  }
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        survey.synced = true;
        await updateSurvey(survey);
      }
    } catch (err) {
      console.error('Sync failed for survey', survey.id, err);
      break;
    }
  }

  await renderSurveys();
}

async function init() {
  await openDB();
  updateNetworkStatus();
  await renderSurveys();

  const form = document.getElementById('surveyForm');
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const survey = {
      id: crypto.randomUUID(),
      name: document.getElementById('name').value.trim(),
      location: document.getElementById('location').value.trim(),
      notes: document.getElementById('notes').value.trim(),
      createdAt: new Date().toISOString(),
      synced: false
    };

    await addSurvey(survey);
    form.reset();
    await renderSurveys();
    await syncPendingSurveys();
  });

  document.getElementById('syncBtn').addEventListener('click', syncPendingSurveys);

  window.addEventListener('online', async () => {
    updateNetworkStatus();
    await syncPendingSurveys();
  });

  window.addEventListener('offline', updateNetworkStatus);

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/sw.js')
      .then(() => console.log('Service worker registered'))
      .catch((err) => console.error('SW registration failed', err));
  }
}

init();
