## `server/server.js`

```js
import express from "express";
import cors from "cors";

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

/**
 * In-memory storage for demo purposes.
 * Replace with a real DB in production.
 */
const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id: string,
 *   name: string,
 *   location: string,
 *   notes: string,
 *   updatedAt: number
 * }
 */

app.get("/api/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post("/api/sync", (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: "records must be an array" });
  }

  const accepted = [];

  for (const record of records) {
    if (!record.id) continue;

    const existing = surveys.get(record.id);

    // Minimal conflict handling: latest updatedAt wins
    if (!existing || (record.updatedAt || 0) >= (existing.updatedAt || 0)) {
      surveys.set(record.id, record);
      accepted.push(record.id);
    }
  }

  res.json({
    success: true,
    accepted,
    serverCount: surveys.size
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

