## `client/app.js`

```js
const DB_NAME = "offlineSurveyDB";
const DB_VERSION = 1;
const STORE_NAME = "surveys";
const API_BASE = "http://localhost:3000/api";

let db;

async function init() {
  db = await openDB();
  updateNetworkStatus();
  await renderSurveys();
  await updatePendingCount();

  window.addEventListener("online", async () => {
    updateNetworkStatus();
    await syncPending();
  });

  window.addEventListener("offline", updateNetworkStatus);

  document.getElementById("surveyForm").addEventListener("submit", saveSurvey);
  document.getElementById("syncBtn").addEventListener("click", syncPending);
  document.getElementById("refreshBtn").addEventListener("click", renderSurveys);
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
      store.createIndex("synced", "synced", { unique: false });
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function tx(storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

function promisifyRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function getAllSurveys() {
  return await promisifyRequest(tx(STORE_NAME).getAll());
}

async function getPendingSurveys() {
  return await promisifyRequest(tx(STORE_NAME).index("synced").getAll(false));
}

async function putSurvey(survey) {
  return await promisifyRequest(tx(STORE_NAME, "readwrite").put(survey));
}

async function saveSurvey(event) {
  event.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    updatedAt: Date.now(),
    synced: false
  };

  await putSurvey(survey);

  event.target.reset();
  await renderSurveys();
  await updatePendingCount();

  if (navigator.onLine) {
    await syncPending();
  }
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  const list = document.getElementById("surveyList");
  list.innerHTML = "";

  surveys.sort((a, b) => b.updatedAt - a.updatedAt);

  for (const survey of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${escapeHtml(survey.name)}</strong><br>
      Location: ${escapeHtml(survey.location)}<br>
      Notes: ${escapeHtml(survey.notes)}<br>
      Updated: ${new Date(survey.updatedAt).toLocaleString()}<br>
      Synced: ${survey.synced ? "Yes" : "No"}
    `;
    list.appendChild(li);
  }
}

async function updatePendingCount() {
  const pending = await getPendingSurveys();
  document.getElementById("pendingCount").textContent = pending.length;
}

function updateNetworkStatus() {
  document.getElementById("networkStatus").textContent =
    navigator.onLine ? "Online" : "Offline";
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (pending.length === 0) {
    await updatePendingCount();
    return;
  }

  try {
    const response = await fetch(`${API_BASE}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) {
      throw new Error("Sync failed");
    }

    const result = await response.json();

    for (const survey of pending) {
      if (result.accepted.includes(survey.id)) {
        survey.synced = true;
        await putSurvey(survey);
      }
    }

    await renderSurveys();
    await updatePendingCount();
  } catch (error) {
    console.error("Sync error:", error);
  }
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (char) => {
    const map = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      "\"": "&quot;",
      "'": "&#039;"
    };
    return map[char];
  });
}

init();
```

