```js
const API_URL = "http://localhost:3000/surveys";
const DB_NAME = "survey-db";
const STORE_NAME = "surveys";

function updateOnlineStatus() {
  const status = document.getElementById("status");
  if (navigator.onLine) {
    status.textContent = "Online";
    status.className = "synced";
  } else {
    status.textContent = "Offline";
    status.className = "pending";
  }
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurveyLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllLocalSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function markSurveySynced(id) {
  const db = await openDB();
  const surveys = await getAllLocalSurveys();
  const survey = surveys.find((s) => s.id === id);
  if (!survey) return;

  survey.synced = true;

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderSurveys() {
  const list = document.getElementById("surveyList");
  const surveys = await getAllLocalSurveys();
  list.innerHTML = "";

  surveys.forEach((survey) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}
      <br />
      ${survey.notes || ""}
      <br />
      <span class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending sync"}
      </span>
    `;
    list.appendChild(li);
  });
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllLocalSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await markSurveySynced(survey.id);
      }
    } catch (err) {
      console.error("Sync failed:", err);
      break;
    }
  }

  await renderSurveys();
}

document.getElementById("surveyForm").addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value,
    location: document.getElementById("location").value,
    notes: document.getElementById("notes").value,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  await renderSurveys();
  await syncSurveys();

  e.target.reset();
});

window.addEventListener("online", async () => {
  updateOnlineStatus();
  await syncSurveys();
});

window.addEventListener("offline", updateOnlineStatus);

(async function init() {
  updateOnlineStatus();
  await renderSurveys();
  await syncSurveys();
})();
```

