# 6. `public/app.js`

```js
const STORAGE_KEY = 'offline-surveys';

const surveyForm = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const serverSurveyList = document.getElementById('serverSurveyList');
const networkStatus = document.getElementById('networkStatus');
const syncStatus = document.getElementById('syncStatus');
const refreshServerBtn = document.getElementById('refreshServerBtn');

function getLocalSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveLocalSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function renderLocalSurveys() {
  const surveys = getLocalSurveys();
  surveyList.innerHTML = '';

  if (surveys.length === 0) {
    surveyList.innerHTML = '<li>No local surveys yet.</li>';
    return;
  }

  surveys.forEach(survey => {
    const li = document.createElement('li');
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}<br/>
      ${survey.notes || ''}<br/>
      <small>${survey.synced ? '✅ Synced' : '🕓 Pending sync'}</small>
    `;
    surveyList.appendChild(li);
  });
}

async function renderServerSurveys() {
  try {
    const res = await fetch('/api/surveys');
    const surveys = await res.json();

    serverSurveyList.innerHTML = '';

    if (surveys.length === 0) {
      serverSurveyList.innerHTML = '<li>No synced surveys on server.</li>';
      return;
    }

    surveys.forEach(survey => {
      const li = document.createElement('li');
      li.innerHTML = `
        <strong>${survey.name}</strong> - ${survey.location}<br/>
        ${survey.notes || ''}
      `;
      serverSurveyList.appendChild(li);
    });
  } catch (err) {
    serverSurveyList.innerHTML = '<li>Unable to load server surveys.</li>';
  }
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? '🟢 Online' : '🔴 Offline';
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = getLocalSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (pending.length === 0) {
    syncStatus.textContent = 'All changes synced';
    return;
  }

  syncStatus.textContent = `Syncing ${pending.length} survey(s)...`;

  try {
    const res = await fetch('/api/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(pending)
    });

    if (!res.ok) throw new Error('Sync failed');

    const result = await res.json();
    const acceptedIds = result.accepted || [];

    const updated = surveys.map(s =>
      acceptedIds.includes(s.id) ? { ...s, synced: true } : s
    );

    saveLocalSurveys(updated);
    renderLocalSurveys();
    renderServerSurveys();
    syncStatus.textContent = 'Sync complete';
  } catch (err) {
    syncStatus.textContent = 'Sync failed; will retry when online';
  }
}

surveyForm.addEventListener('submit', (e) => {
  e.preventDefault();

  const name = document.getElementById('name').value.trim();
  const location = document.getElementById('location').value.trim();
  const notes = document.getElementById('notes').value.trim();

  const surveys = getLocalSurveys();

  surveys.push({
    id: crypto.randomUUID(),
    name,
    location,
    notes,
    createdAt: new Date().toISOString(),
    synced: false
  });

  saveLocalSurveys(surveys);
  renderLocalSurveys();
  surveyForm.reset();

  if (navigator.onLine) {
    syncSurveys();
  }
});

window.addEventListener('online', () => {
  updateNetworkStatus();
  syncSurveys();
});

window.addEventListener('offline', () => {
  updateNetworkStatus();
  syncStatus.textContent = 'Offline: changes saved locally';
});

refreshServerBtn.addEventListener('click', renderServerSurveys);

updateNetworkStatus();
renderLocalSurveys();
renderServerSurveys();
syncSurveys();
```

