## `client/app.js`

```js
const DB_NAME = "survey-app-db";
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000";

let db;

function updateNetworkStatus() {
  const status = document.getElementById("networkStatus");
  status.textContent = navigator.onLine ? "Online" : "Offline";
  status.style.color = navigator.onLine ? "green" : "red";
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
      db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "localId" });
      }
    };

    request.onsuccess = (event) => {
      db = event.target.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addRecord(record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(record);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllRecords() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function deleteRecord(localId) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.delete(localId);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderRecords() {
  const records = await getAllRecords();
  const list = document.getElementById("recordsList");
  list.innerHTML = "";

  if (records.length === 0) {
    list.innerHTML = "<li>No local records</li>";
    return;
  }

  records.forEach((record) => {
    const li = document.createElement("li");
    li.textContent = `${record.surveyor} @ ${record.location} - ${record.notes} [${
      record.synced ? "synced" : "pending"
    }]`;
    list.appendChild(li);
  });
}

async function syncRecords() {
  if (!navigator.onLine) return;

  const records = await getAllRecords();
  const unsynced = records.filter((r) => !r.synced);

  if (unsynced.length === 0) return;

  try {
    const response = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ records: unsynced })
    });

    if (!response.ok) throw new Error("Sync failed");

    const result = await response.json();

    for (const record of unsynced) {
      await deleteRecord(record.localId);
    }

    for (const saved of result.saved) {
      await addRecord({
        ...saved,
        localId: saved.localId,
        synced: true
      });
    }

    await renderRecords();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

function generateId() {
  return crypto.randomUUID
    ? crypto.randomUUID()
    : Date.now().toString() + Math.random().toString(16).slice(2);
}

async function init() {
  await openDB();
  updateNetworkStatus();
  await renderRecords();

  document.getElementById("surveyForm").addEventListener("submit", async (e) => {
    e.preventDefault();

    const surveyor = document.getElementById("surveyor").value;
    const location = document.getElementById("location").value;
    const notes = document.getElementById("notes").value;

    const record = {
      localId: generateId(),
      surveyor,
      location,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await addRecord(record);
    e.target.reset();
    await renderRecords();

    if (navigator.onLine) {
      await syncRecords();
    }
  });

  document.getElementById("syncBtn").addEventListener("click", syncRecords);

  window.addEventListener("online", async () => {
    updateNetworkStatus();
    await syncRecords();
  });

  window.addEventListener("offline", updateNetworkStatus);
}

init();
```

