# 3. `server.js`

```js
const express = require('express');
const path = require('path');

const app = express();
const PORT = 3000;

// In-memory storage for synced surveys
const surveys = [];

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Receive synced survey entries
app.post('/api/surveys', (req, res) => {
  const survey = req.body;

  if (!survey || !survey.id || !survey.name || !survey.location || !survey.notes) {
    return res.status(400).json({ error: 'Invalid survey payload' });
  }

  surveys.push({
    ...survey,
    receivedAt: new Date().toISOString()
  });

  console.log('Received survey:', survey);

  res.json({ success: true, id: survey.id });
});

// View all synced surveys
app.get('/api/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

