# 6. `public/app.js`

```js
const STORAGE_KEY = 'offline-surveys';

const form = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const serverSurveyList = document.getElementById('serverSurveyList');
const statusEl = document.getElementById('status');
const syncBtn = document.getElementById('syncBtn');
const refreshServerBtn = document.getElementById('refreshServerBtn');

function loadSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function renderSurveys() {
  const surveys = loadSurveys();
  surveyList.innerHTML = '';

  if (surveys.length === 0) {
    surveyList.innerHTML = '<li>No local surveys yet.</li>';
    return;
  }

  surveys.forEach(survey => {
    const li = document.createElement('li');
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}<br/>
      ${survey.notes}<br/>
      <small>${survey.createdAt}</small><br/>
      <span class="${survey.synced ? 'synced' : 'pending'}">
        ${survey.synced ? 'Synced' : 'Pending sync'}
      </span>
    `;
    surveyList.appendChild(li);
  });
}

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'status online';
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'status offline';
  }
}

async function syncSurveys() {
  if (!navigator.onLine) {
    alert('You are offline. Sync will happen when connection returns.');
    return;
  }

  const surveys = loadSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (pending.length === 0) {
    alert('No pending surveys to sync.');
    return;
  }

  for (const survey of pending) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error('Sync failed');

      survey.synced = true;
    } catch (err) {
      console.error('Failed to sync survey', survey.id, err);
    }
  }

  saveSurveys(surveys);
  renderSurveys();
}

async function fetchServerSurveys() {
  try {
    const res = await fetch('/api/surveys');
    const data = await res.json();

    serverSurveyList.innerHTML = '';

    if (data.length === 0) {
      serverSurveyList.innerHTML = '<li>No surveys on server yet.</li>';
      return;
    }

    data.forEach(survey => {
      const li = document.createElement('li');
      li.innerHTML = `
        <strong>${survey.name}</strong> - ${survey.location}<br/>
        ${survey.notes}<br/>
        <small>Created: ${survey.createdAt}</small><br/>
        <small>Received: ${survey.receivedAt}</small>
      `;
      serverSurveyList.appendChild(li);
    });
  } catch (err) {
    console.error('Failed to fetch server surveys', err);
  }
}

form.addEventListener('submit', (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById('name').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  const surveys = loadSurveys();
  surveys.push(survey);
  saveSurveys(surveys);
  renderSurveys();

  form.reset();

  if (navigator.onLine) {
    syncSurveys();
  }
});

syncBtn.addEventListener('click', syncSurveys);
refreshServerBtn.addEventListener('click', fetchServerSurveys);

window.addEventListener('online', () => {
  updateOnlineStatus();
  syncSurveys();
});

window.addEventListener('offline', updateOnlineStatus);

updateOnlineStatus();
renderSurveys();
fetchServerSurveys();
```

