```js
const API_URL = "http://localhost:3000";
const STORAGE_KEY = "offline-surveys";

const surveyForm = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const networkStatus = document.getElementById("networkStatus");
const syncBtn = document.getElementById("syncBtn");

function loadSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
}

function saveSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function renderSurveys() {
  const surveys = loadSurveys();
  surveyList.innerHTML = "";

  surveys.forEach((survey) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.surveyor}</strong> - ${survey.location}
      <br />
      ${survey.notes || ""}
      <br />
      <small class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending sync"}
      </small>
    `;
    surveyList.appendChild(li);
  });
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? "Online" : "Offline";
  networkStatus.className = navigator.onLine ? "synced" : "pending";
}

function createSurvey(data) {
  return {
    id: crypto.randomUUID(),
    surveyor: data.surveyor,
    location: data.location,
    notes: data.notes,
    createdAt: new Date().toISOString(),
    synced: false
  };
}

surveyForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const survey = createSurvey({
    surveyor: document.getElementById("surveyor").value,
    location: document.getElementById("location").value,
    notes: document.getElementById("notes").value
  });

  const surveys = loadSurveys();
  surveys.push(survey);
  saveSurveys(surveys);
  renderSurveys();
  surveyForm.reset();

  if (navigator.onLine) {
    syncSurveys();
  }
});

async function syncSurveys() {
  const surveys = loadSurveys();
  const pending = surveys.filter((s) => !s.synced);

  if (pending.length === 0) return;

  try {
    const res = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ surveys: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    const updated = surveys.map((s) =>
      pending.find((p) => p.id === s.id) ? { ...s, synced: true } : s
    );

    saveSurveys(updated);
    renderSurveys();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

syncBtn.addEventListener("click", syncSurveys);

window.addEventListener("online", () => {
  updateNetworkStatus();
  syncSurveys();
});

window.addEventListener("offline", updateNetworkStatus);

updateNetworkStatus();
renderSurveys();

if (navigator.onLine) {
  syncSurveys();
}
```

