```js
const API_URL = "http://localhost:3000/surveys";
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";

let db;

function updateStatus() {
  const statusEl = document.getElementById("status");
  if (navigator.onLine) {
    statusEl.textContent = "Online";
    statusEl.className = "status online";
  } else {
    statusEl.textContent = "Offline";
    statusEl.className = "status offline";
  }
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "localId" });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function saveSurveyLocally(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function renderSurveys(surveys) {
  const list = document.getElementById("surveyList");
  list.innerHTML = "";

  surveys.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  for (const survey of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}<br/>
      ${survey.notes}<br/>
      <small>${survey.timestamp}</small><br/>
      <span class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending sync"}
      </span>
    `;
    list.appendChild(li);
  }
}

async function refreshUI() {
  const surveys = await getAllLocalSurveys();
  renderSurveys(surveys);
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllLocalSurveys();
  const pending = surveys.filter(s => !s.synced);

  for (const survey of pending) {
    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!response.ok) throw new Error("Sync failed");

      survey.synced = true;
      await saveSurveyLocally(survey);
    } catch (err) {
      console.error("Failed to sync survey:", survey.localId, err);
    }
  }

  await refreshUI();
}

document.getElementById("surveyForm").addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById("name").value,
    location: document.getElementById("location").value,
    notes: document.getElementById("notes").value,
    timestamp: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  await refreshUI();

  document.getElementById("surveyForm").reset();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

window.addEventListener("online", async () => {
  updateStatus();
  await syncSurveys();
});

window.addEventListener("offline", updateStatus);

async function init() {
  updateStatus();
  await openDB();
  await refreshUI();

  if (navigator.onLine) {
