## `client/app.js`

```js
const DB_NAME = "offlineSurveyDB";
const DB_VERSION = 1;
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000/surveys";

const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("syncBtn");

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "localId" });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function updateSurvey(survey) {
  return addSurvey(survey);
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = "";

  surveys.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const survey of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}
      <br/>
      <small>${survey.notes || ""}</small>
      <br/>
      <span class="${survey.synced ? "synced" : "pending"}">
        ${survey.synced ? "Synced" : "Pending sync"}
      </span>
    `;
    surveyList.appendChild(li);
  }
}

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = "Online";
    statusEl.className = "status online";
  } else {
    statusEl.textContent = "Offline";
    statusEl.className = "status offline";
  }
}

async function saveSurveyLocally(data) {
  const survey = {
    localId: crypto.randomUUID(),
    name: data.name,
    location: data.location,
    notes: data.notes,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addSurvey(survey);
  await renderSurveys();
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter(s => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error("Sync failed");

      survey.synced = true;
      await updateSurvey(survey);
    } catch (err) {
      console.error("Failed to sync survey", survey.localId, err);
    }
  }

  await renderSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const data = {
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim()
  };

  if (!data.name || !data.location) return;

  await saveSurveyLocally(data);
  form.reset();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

syncBtn.addEventListener("click", syncSurveys);

window.addEventListener("online", async () => {
  updateOnlineStatus();
  await syncSurveys();
});

window.addEventListener("offline", updateOnlineStatus);

(async function init() {
  await openDB();
  updateOnlineStatus();
  await renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
})();
```

