# 6. `public/app.js`

This is the offline-first logic:

- save every survey locally
- add unsynced items to queue
- sync automatically when online
- update UI

```js
const STORAGE_KEY = 'offline_surveys';
const QUEUE_KEY = 'sync_queue';

const form = document.getElementById('surveyForm');
const statusEl = document.getElementById('status');
const surveyList = document.getElementById('surveyList');
const queueList = document.getElementById('queueList');

function getLocalSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveLocalSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function getQueue() {
  return JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]');
}

function saveQueue(queue) {
  localStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
}

function updateStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'status online';
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'status offline';
  }
}

function render() {
  const surveys = getLocalSurveys();
  const queue = getQueue();

  surveyList.innerHTML = '';
  queueList.innerHTML = '';

  surveys.forEach((survey) => {
    const li = document.createElement('li');
    li.textContent = `${survey.name} @ ${survey.location} - ${survey.notes || 'No notes'} (${survey.timestamp}) ${survey.synced ? '✅' : '⏳'}`;
    surveyList.appendChild(li);
  });

  queue.forEach((item) => {
    const li = document.createElement('li');
    li.textContent = `${item.name} @ ${item.location} (${item.timestamp})`;
    queueList.appendChild(li);
  });
}

function createSurvey(data) {
  return {
    id: crypto.randomUUID(),
    name: data.name,
    location: data.location,
    notes: data.notes,
    timestamp: new Date().toISOString(),
    synced: false
  };
}

function addSurveyLocally(survey) {
  const surveys = getLocalSurveys();
  surveys.push(survey);
  saveLocalSurveys(surveys);

  const queue = getQueue();
  queue.push(survey);
  saveQueue(queue);
}

async function syncQueue() {
  if (!navigator.onLine) return;

  let queue = getQueue();
  if (queue.length === 0) return;

  const remaining = [];

  for (const item of queue) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(item)
      });

      if (!res.ok) throw new Error('Sync failed');

      const surveys = getLocalSurveys().map((survey) =>
        survey.id === item.id ? { ...survey, synced: true } : survey
      );
      saveLocalSurveys(surveys);
    } catch (err) {
      remaining.push(item);
    }
  }

  saveQueue(remaining);
  render();
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = createSurvey({
    name: document.getElementById('name').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim()
  });

  addSurveyLocally(survey);
  render();
  form.reset();

  if (navigator.onLine) {
    await syncQueue();
  }
});

window.addEventListener('online', async () => {
  updateStatus();
  await syncQueue();
});

window.addEventListener('offline', updateStatus);

updateStatus();
render();

if (navigator.onLine) {
  syncQueue();
}
```

