# 6. `public/app.js`

```js
const STORAGE_KEY = 'offline-surveys';

const form = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const syncBtn = document.getElementById('syncBtn');
const networkStatus = document.getElementById('networkStatus');

function getLocalSurveys() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveLocalSurveys(surveys) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
}

function renderSurveys() {
  const surveys = getLocalSurveys();
  surveyList.innerHTML = '';

  if (surveys.length === 0) {
    surveyList.innerHTML = '<li>No surveys saved yet.</li>';
    return;
  }

  surveys.forEach(survey => {
    const li = document.createElement('li');
    li.className = survey.synced ? 'synced' : 'pending';
    li.textContent = `${survey.surveyor} @ ${survey.location} - ${survey.notes} [${
      survey.synced ? 'Synced' : 'Pending'
    }]`;
    surveyList.appendChild(li);
  });
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
  networkStatus.style.color = navigator.onLine ? 'green' : 'red';
}

function createSurvey(data) {
  return {
    id: crypto.randomUUID(),
    surveyor: data.surveyor,
    location: data.location,
    notes: data.notes,
    createdAt: new Date().toISOString(),
    synced: false
  };
}

form.addEventListener('submit', e => {
  e.preventDefault();

  const survey = createSurvey({
    surveyor: document.getElementById('surveyor').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim()
  });

  const surveys = getLocalSurveys();
  surveys.push(survey);
  saveLocalSurveys(surveys);
  renderSurveys();
  form.reset();

  if (navigator.onLine) {
    syncSurveys();
  }
});

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = getLocalSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (pending.length === 0) return;

  try {
    const res = await fetch('/api/surveys/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(pending)
    });

    if (!res.ok) {
      throw new Error('Sync failed');
    }

    const result = await res.json();
    const syncedIds = new Set(result.syncedIds);

    const updated = surveys.map(s =>
      syncedIds.has(s.id) ? { ...s, synced: true } : s
    );

    saveLocalSurveys(updated);
    renderSurveys();
  } catch (err) {
    console.error('Sync error:', err);
  }
}

syncBtn.addEventListener('click', syncSurveys);

window.addEventListener('online', () => {
  updateNetworkStatus();
  syncSurveys();
});

window.addEventListener('offline', updateNetworkStatus);

updateNetworkStatus();
renderSurveys();

// Try syncing on app load too
if (navigator.onLine) {
  syncSurveys();
}
```

