## `client/app.js`

```js
const API_URL = "http://localhost:3000/surveys";
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";

const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");
const networkStatus = document.getElementById("networkStatus");

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? "Online" : "Offline";
  networkStatus.style.color = navigator.onLine ? "green" : "red";
}

window.addEventListener("online", async () => {
  updateNetworkStatus();
  await syncSurveys();
});

window.addEventListener("offline", updateNetworkStatus);

updateNetworkStatus();

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "localId" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurveyLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllLocalSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function deleteLocalSurvey(localId) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).delete(localId);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function renderSurveys(surveys) {
  surveyList.innerHTML = "";
  surveys.forEach((survey) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${survey.name}</strong> - ${survey.location}<br/>
      ${survey.notes || ""}<br/>
      <small>${survey.synced ? "Synced" : "Pending sync"}</small>
    `;
    surveyList.appendChild(li);
  });
}

async function refreshUI() {
  const surveys = await getAllLocalSurveys();
  renderSurveys(surveys);
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById("name").value,
    location: document.getElementById("location").value,
    notes: document.getElementById("notes").value,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  form.reset();
  await refreshUI();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

syncBtn.addEventListener("click", syncSurveys);

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllLocalSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error("Sync failed");

      // Mark as synced locally
      await saveSurveyLocally({ ...survey, synced: true });
    } catch (err) {
      console.error("Failed to sync survey", survey.localId, err);
    }
  }

  await refreshUI();
}

refreshUI();
```

