const express = require("express");
const auth = require("../middleware/auth");
const Message = require("../models/Message");
const Notification = require("../models/Notification");

const router = express.Router();

router.get("/:userId", auth, async (req, res) => {
  try {
    const myId = req.user.id;
    const otherId = req.params.userId;

    const messages = await Message.find({
      $or: [
        { sender: myId, receiver: otherId },
        { sender: otherId, receiver: myId }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/", auth, async (req, res) => {
  try {
    const { receiver, content, isPremiumMessage } = req.body;

    const message = await Message.create({
      sender: req.user.id,
      receiver,
      content,
      isPremiumMessage: !!isPremiumMessage
    });

    const notification = await Notification.create({
      user: receiver,
      type: "message",
      message: `New message from ${req.user.username}`,
      meta: { senderId: req.user.id, messageId: message._id }
    });

    const io = req.app.get("io");
    io.to(receiver).emit("new_message", message);
    io.to(receiver).emit("new_notification", notification);

    res.json(message);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

module.exports = router;
