## `server/routes/payments.js`

```js
const express = require("express");
const auth = require("../middleware/auth");
const Stripe = require("stripe");
const User = require("../models/User");
const Subscription = require("../models/Subscription");

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post("/create-checkout-session", auth, async (req, res) => {
  try {
    const { priceId } = req.body;

    const user = await User.findById(req.user.id);

    let customerId = user.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "subscription",
      customer: customerId,
      line_items: [
        {
          price: priceId,
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/premium?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/premium?canceled=true`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];

  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  try {
    if (event.type === "checkout.session.completed") {
      const session = event.data.object;

      const customerId = session.customer;
      const subscriptionId = session.subscription;

      const user = await User.findOne({ stripeCustomerId: customerId });
      if (user) {
        user.isPremium = true;
        await user.save();

        await Subscription.create({
          user: user._id,
          stripeSubscriptionId: subscriptionId,
          status: "active",
          plan: "premium"
        });
      }
    }

    if (event.type === "customer.subscription.deleted") {
      const subscription = event.data.object;

      const subDoc = await Subscription.findOne({
        stripeSubscriptionId: subscription.id
      });

      if (subDoc) {
        subDoc.status = "canceled";
        await subDoc.save();

        await User.findByIdAndUpdate(subDoc.user, { isPremium: false });
      }
    }

    res.json({ received: true });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

module.exports = router;
```

