## `client/src/pages/Chat.js`

```js
import React, { useContext, useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import { AuthContext } from "../context/AuthContext";
import Navbar from "../components/Navbar";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";

export default function Chat() {
  const { user } = useContext(AuthContext);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    if (user) {
      socket.emit("join", user.id);
      fetchUsers();
    }
  }, [user]);

  useEffect(() => {
    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.sender === selectedUser._id || message.sender === selectedUser.id) &&
        (message.receiver === user.id || message.receiver === user._id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off("new_message");
  }, [selectedUser, user]);

  const fetchUsers = async () => {
    const res = await api.get("/users");
    setUsers(res.data);
  };

  const loadMessages = async (otherUser) => {
    setSelectedUser(otherUser);
    const res = await api.get(`/messages/${otherUser._id}`);
    setMessages(res.data);
  };

  const sendMessage = async ({ content, isPremiumMessage }) => {
    if (!selectedUser) return;

    const res = await api.post("/messages", {
      receiver: selectedUser._id,
      content,
      isPremiumMessage
    });

    setMessages((prev) => [...prev, res.data]);

    socket.emit("send_message", {
      ...res.data,
      sender: user.id,
      senderName: user.username,
      receiver: selectedUser._id
    });
  };

  return (
    <div>
      <Navbar />
      <div style={{ display: "flex", padding: 20 }}>
        <div style={{ width: 250, borderRight: "1px solid #ddd", paddingRight: 10 }}>
          <h4>Users</h4>
          {users.map((u) => (
            <div
              key={u._id}
              onClick={() => loadMessages(u)}
              style={{ padding: 8, cursor: "pointer", background: selectedUser?._id === u._id ? "#eee" : "transparent" }}
            >
              {u.username} {u.isPremium ? "⭐" : ""}
            </div>
          ))}
        </div>

        <div style={{ flex: 1, paddingLeft: 20 }}>
          {selectedUser ? (
            <>
              <h4>Chat with {selectedUser.username}</h4>
              <MessageList messages={messages} currentUser={user} />
              <MessageInput onSend={sendMessage} canSendPremium={user?.isPremium} />
            </>
          ) : (
            <p>Select a user to start chatting</p>
          )}
        </div>
      </div>
    </div>
  );
}
```

