## `src/App.js`
```js
import React, { useEffect, useState } from "react";
import api from "./api";
import socket from "./socket";

function App() {
  const [user, setUser] = useState(null);
  const [recipientId, setRecipientId] = useState("");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);
  const [notification, setNotification] = useState(null);

  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      const parsed = JSON.parse(storedUser);
      setUser(parsed);
      socket.emit("register-user", parsed.id);
    }

    socket.on("new-message", (payload) => {
      setMessages((prev) => [...prev, payload.message || payload]);
    });

    socket.on("notification", (notif) => {
      setNotification(notif);
      setTimeout(() => setNotification(null), 3000);
    });

    return () => {
      socket.off("new-message");
      socket.off("notification");
    };
  }, []);

  const register = async () => {
    const res = await api.post("/auth/register", {
      username: "demoUser",
      email: "demo@example.com",
      password: "password123"
    });

    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setUser(res.data.user);
    socket.emit("register-user", res.data.user.id);
  };

  const login = async () => {
    const res = await api.post("/auth/login", {
      emailOrUsername: "demo@example.com",
      password: "password123"
    });

    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setUser(res.data.user);
    socket.emit("register-user", res.data.user.id);
  };

  const sendMessage = async () => {
    const res = await api.post("/messages", {
      recipientId,
      text
    });

    setMessages((prev) => [...prev, res.data]);

    socket.emit("send-message", {
      senderId: user.id,
      recipientId,
      message: res.data
    });

    setText("");
  };

  const subscribe = async () => {
    const res = await api.post("/payments/create-checkout-session");
    window.location.href = res.data.url;
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Social Messaging App</h1>

      {!user ? (
        <div>
          <button onClick={register}>Register Demo User</button>
          <button onClick={login}>Login Demo User</button>
        </div>
      ) : (
        <div>
          <p>
            Logged in as <strong>{user.username}</strong>
            {user.isPremium ? " (Premium)" : ""}
          </p>

          {!user.isPremium && (
            <button onClick={subscribe}>Upgrade to Premium</button>
          )}

          <div style={{ marginTop: 20 }}>
            <input
              placeholder="Recipient User ID"
              value={recipientId}
              onChange={(e) => setRecipientId(e.target.value)}
            />
            <input
              placeholder="Message"
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            <button onClick={sendMessage}>Send</button>
          </div>

          {notification && (
            <div style={{ marginTop: 20, color: "green" }}>
              <strong>{notification.title}</strong>: {notification.body}
            </div>
          )}

          <div style={{ marginTop: 20 }}>
            <h3>Messages</h3>
            {messages.map((msg, idx) => (
              <div key={idx}>
                <strong>{msg.sender?.username || msg.senderId}:</strong> {msg.text || msg.message?.text}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
```

