```js
import express from "express";
import { authMiddleware } from "../auth.js";
import { Message, User } from "../db.js";
import { sendPushNotification } from "../notifications.js";

export default function messageRoutes(io, onlineUsers) {
  const router = express.Router();

  router.post("/", authMiddleware, async (req, res) => {
    try {
      const { recipientId, text } = req.body;

      if (!recipientId || !text?.trim()) {
        return res.status(400).json({ error: "recipientId and text are required" });
      }

      const message = await Message.create({
        sender: req.user.userId,
        recipient: recipientId,
        text: text.trim()
      });

      const populated = await message.populate("sender recipient", "username");

      const recipientSocketId = onlineUsers.get(recipientId);
      if (recipientSocketId) {
        io.to(recipientSocketId).emit("message:new", populated);
      } else {
        const recipient = await User.findById(recipientId);
        const sender = await User.findById(req.user.userId);
        await sendPushNotification(
          recipient?.pushToken,
          `New message from ${sender?.username}`,
          text.trim()
        );
      }

      res.json(populated);
    } catch (err) {
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  router.get("/:userId", authMiddleware, async (req, res) => {
    try {
      const otherUserId = req.params.userId;
      const myId = req.user.userId;

      const messages = await Message.find({
        $or: [
          { sender: myId, recipient: otherUserId },
          { sender: otherUserId, recipient: myId }
        ]
      })
        .sort({ createdAt: 1 })
        .populate("sender recipient", "username");

      res.json(messages);
    } catch {
      res.status(500).json({ error: "Failed to fetch messages" });
    }
  });

  return router;
}
```

