## `server/src/routes/messages.js`

```js
import express from 'express';
import { prisma } from '../db.js';
import { authMiddleware } from '../middleware/auth.js';
import { createNotification } from '../services/notificationService.js';

const router = express.Router();

export default function messageRoutes(io) {
  router.get('/:userId', authMiddleware, async (req, res) => {
    const otherUserId = Number(req.params.userId);

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: req.user.id, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: req.user.id }
        ]
      },
      orderBy: { createdAt: 'asc' }
    });

    res.json(messages);
  });

  router.post('/', authMiddleware, async (req, res) => {
    try {
      const { receiverId, content, isPaid = false, priceCents = null } = req.body;

      if (!receiverId || !content) {
        return res.status(400).json({ error: 'receiverId and content are required' });
      }

      if (isPaid && !priceCents) {
        return res.status(400).json({ error: 'Paid messages require priceCents' });
      }

      const message = await prisma.message.create({
        data: {
          senderId: req.user.id,
          receiverId,
          content,
          isPaid,
          priceCents
        }
      });

      io.to(`user:${receiverId}`).emit('message:new', message);

      const notification = await prisma.notification.create({
        data: {
          userId: receiverId,
          type: 'message',
          message: `New message from user ${req.user.username}`
        }
      });

      createNotification(io, receiverId, notification);

      res.json(message);
    } catch (err) {
      res.status(500).json({ error: 'Failed to send message', details: err.message });
    }
  });

  return router;
}
```

