```js
import express from 'express';
import { authMiddleware } from '../middleware/auth.js';
import { prisma } from '../db.js';
import { stripe } from '../services/stripeService.js';

const router = express.Router();

router.post('/create-subscription-checkout', authMiddleware, async (req, res) => {
  try {
    const user = await prisma.user.findUnique({ where: { id: req.user.id } });

    let customerId = user.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        metadata: { userId: String(user.id) }
      });

      customerId = customer.id;

      await prisma.user.update({
        where: { id: user.id },
        data: { stripeCustomerId: customerId }
      });
    }

    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      customer: customerId,
      payment_method_types: ['card'],
      line_items: [
        {
          price: 'price_subscription_id_here',
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/premium?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/premium?canceled=true`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: 'Failed to create subscription checkout', details: err.message });
  }
});

router.post('/create-message-purchase-checkout', authMiddleware, async (req, res) => {
  try {
    const { messageId } = req.body;

    const message = await prisma.message.findUnique({
      where: { id: messageId }
    });

    if (!message || !message.isPaid) {
      return res.status(400).json({ error: 'Invalid paid message' });
    }

    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: `Unlock message #${message.id}`
            },
            unit_amount: message.priceCents
          },
          quantity: 1
        }
      ],
      metadata: {
        userId: String(req.user.id),
        messageId: String(message.id)
      },
      success_url: `${process.env.CLIENT_URL}/chat?purchase=success`,
      cancel_url: `${process.env.CLIENT_URL}/chat?purchase=cancel`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: 'Failed to create purchase checkout', details: err.message });
  }
});

router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  let event;

  try {
    const signature = req.headers['stripe-signature'];
    event = stripe.webhooks.constructEvent(
      req.body,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  try {
    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;

      if (session.mode === 'subscription') {
        const customerId = session.customer;

        const user = await prisma.user.findFirst({
          where: { stripeCustomerId: customerId }
        });

        if (user) {
          await prisma.user.update({
            where: { id: user.id },
            data: { isPremium: true }
          });

          await prisma.subscription.create({
            data: {
              userId: user.id,
              stripeSubscriptionId: session.subscription,
              status: 'active'
            }
          });
        }
      }

      if (session.mode === 'payment' && session.metadata?.messageId) {
        await prisma.purchase.create({
          data: {
            userId: Number(session.metadata.userId),
            messageId: Number(session.metadata.messageId),
            stripePaymentId: session.payment_intent,
            amountCents: session.amount_total
          }
        });
      }
    }

    res.json({ received: true });
  } catch (err) {
    res.status(500).json({ error: 'Webhook processing failed', details: err.message });
  }
});

export default router;
```

