import React, { useEffect, useState } from 'react';
import API from '../api';
import { createSocket } from '../socket';
import MessageList from '../components/MessageList';
import MessageInput from '../components/MessageInput';
import NotificationBell from '../components/NotificationBell';

export default function Chat({ onOpenPremium }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const s = createSocket();
    setSocket(s);

    s.on('message:new', (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => s.disconnect();
  }, [selectedUser]);

  useEffect(() => {
    API.get('/users').then((res) => setUsers(res.data));
  }, []);

  async function loadMessages(user) {
    setSelectedUser(user);
    const res = await API.get(`/messages/${user.id}`);
    setMessages(res.data);
  }

  async function unlockMessage(messageId) {
    const res = await API.post('/payments/create-message-purchase-checkout', { messageId });
    window.location.href = res.data.url;
  }

  return (
    <div style={{ display: 'flex', gap: 24 }}>
      <div>
        <h3>Users</h3>
        <button onClick={onOpenPremium}>Go Premium</button>
        {users.map((user) => (
          <div key={user.id}>
            <button onClick={() => loadMessages(user)}>
              {user.username} {user.isPremium ? '⭐' : ''}
            </button>
          </div>
        ))}
      </div>

      <div>
        <h3>Chat</h3>
        <NotificationBell socket={socket} />
        {selectedUser ? (
          <>
            <MessageList messages={messages} onUnlock={unlockMessage} />
            <MessageInput
              selectedUser={selectedUser}
              onMessageSent={(msg) => setMessages((prev) => [...prev, msg])}
            />
          </>
        ) : (
          <p>Select a user to start chatting</p>
        )}
      </div>
    </div>
  );
}
