## `server/src/server.js`
```js
require('dotenv').config();
const express = require('express');
const http = require('http');
const cors = require('cors');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Stripe = require('stripe');
const { Server } = require('socket.io');
const pool = require('./db');
const authMiddleware = require('./middleware/auth');

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ['GET', 'POST']
  }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(cors({
  origin: process.env.CLIENT_URL
}));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

function signToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username, email: user.email },
    process.env.JWT_SECRET,
    { expiresIn: '7d' }
  );
}

/**
 * AUTH
 */
app.post('/api/auth/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;

    if (!username || !email || !password) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const existing = await pool.query(
      'SELECT id FROM users WHERE email = $1 OR username = $2',
      [email, username]
    );

    if (existing.rows.length > 0) {
      return res.status(409).json({ error: 'User already exists' });
    }

    const password_hash = await bcrypt.hash(password, 10);

    const customer = await stripe.customers.create({
      email,
      name: username
    });

    const result = await pool.query(
      `INSERT INTO users (username, email, password_hash, stripe_customer_id)
       VALUES ($1, $2, $3, $4)
       RETURNING id, username, email, subscription_status`,
      [username, email, password_hash, customer.id]
    );

    const user = result.rows[0];
    const token = signToken(user);

    res.status(201).json({ token, user });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Registration failed' });
  }
});

app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    const result = await pool.query(
      'SELECT * FROM users WHERE email = $1',
      [email]
    );

    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const valid = await bcrypt.compare(password, user.password_hash);

    if (!valid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = signToken(user);

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        email: user.email,
        subscription_status: user.subscription_status
      }
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Login failed' });
  }
});

/**
 * USERS / CONVERSATIONS
 */
app.get('/api/me', authMiddleware, async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT id, username, email, subscription_status FROM users WHERE id = $1',
      [req.user.id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch profile' });
  }
});

app.post('/api/conversations', authMiddleware, async (req, res) => {
  try {
    const { memberIds } = req.body;

    if (!Array.isArray(memberIds) || memberIds.length === 0) {
      return res.status(400).json({ error: 'memberIds required' });
    }

    const convoResult = await pool.query(
      'INSERT INTO conversations DEFAULT VALUES RETURNING *'
    );

    const conversation = convoResult.rows[0];
    const allMembers = [...new Set([req.user.id, ...memberIds])];

    for (const userId of allMembers) {
      await pool.query(
        'INSERT INTO conversation_members (conversation_id, user_id) VALUES ($1, $2)',
        [conversation.id, userId]
      );
    }

    res.status(201).json(conversation);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create conversation' });
  }
});

app.get('/api/conversations/:conversationId/messages', authMiddleware, async (req, res) => {
  try {
    const { conversationId } = req.params;

    const membership = await pool.query(
      'SELECT 1 FROM conversation_members WHERE conversation_id = $1 AND user_id = $2',
      [conversationId, req.user.id]
    );

    if (membership.rows.length === 0) {
      return res.status(403).json({ error: 'Access denied' });
    }

    const result = await pool.query(
      `SELECT m.*, u.username
       FROM messages m
       JOIN users u ON u.id = m.sender_id
       WHERE conversation_id = $1
       ORDER BY created_at ASC`,
      [conversationId]
    );

    res.json(result.rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

app.get('/api/notifications', authMiddleware, async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM notifications WHERE user_id = $1 ORDER BY created_at DESC',
      [req.user.id]
    );
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch notifications' });
  }
});

app.post('/api/notifications/:id/read', authMiddleware, async (req, res) => {
  try {
    const { id } = req.params;
    await pool.query(
      'UPDATE notifications SET is_read = TRUE WHERE id = $1 AND user_id = $2',
      [id, req.user.id]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to update notification' });
  }
});

/**
 * STRIPE SUBSCRIPTIONS
 */
app.post('/api/billing/create-checkout-session', authMiddleware, async (req, res) => {
  try {
    const userResult = await pool.query(
      'SELECT * FROM users WHERE id = $1',
      [req.user.id]
    );
    const user = userResult.rows[0];

    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      customer: user.stripe_customer_id,
      line_items: [
        {
          price: 'price_your_subscription_price_id',
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/billing/success`,
      cancel_url: `${process.env.CLIENT_URL}/billing/cancel`
    });

    res.json({ url: session.url });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create checkout session' });
  }
});

app.post('/api/billing/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      req.headers['stripe-signature'],
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  try {
    if (event.type === 'customer.subscription.created' || event.type === 'customer.subscription.updated') {
      const subscription = event.data.object;
      await pool.query(
        'UPDATE users SET subscription_status = $1 WHERE stripe_customer_id = $2',
        [subscription.status, subscription.customer]
      );
    }

    if (event.type === 'customer.subscription.deleted') {
      const subscription = event.data.object;
      await pool.query(
        'UPDATE users SET subscription_status = $1 WHERE stripe_customer_id = $2',
        ['free', subscription.customer]
      );
    }

    res.json({ received: true });
  } catch (err) {
    console.error(err);
    res.status(500).send('Webhook handling failed');
  }
});

/**
 * SOCKET.IO
 */
io.use((socket, next) => {
  try {
    const token = socket.handshake.auth.token;
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.user = decoded;
    next();
  } catch (err) {
    next(new Error('Unauthorized'));
  }
});

io.on('connection', (socket) => {
  const userId = socket.user.id;
  onlineUsers.set(userId, socket.id);

  socket.on('join_conversation', async (conversationId) => {
    const membership = await pool.query(
      'SELECT 1 FROM conversation_members WHERE conversation_id = $1 AND user_id = $2',
      [conversationId, userId]
    );

    if (membership.rows.length > 0) {
      socket.join(`conversation:${conversationId}`);
    }
  });

  socket.on('send_message', async ({ conversationId, content }) => {
    try {
      const membership = await pool.query(
        'SELECT 1 FROM conversation_members WHERE conversation_id = $1 AND user_id = $2',
        [conversationId, userId]
      );

      if (membership.rows.length === 0) return;

      const msgResult = await pool.query(
        `INSERT INTO messages (conversation_id, sender_id, content)
         VALUES ($1, $2, $3)
         RETURNING *`,
        [conversationId, userId, content]
      );

      const userResult = await pool.query(
        'SELECT username FROM users WHERE id = $1',
        [userId]
      );

      const message = {
        ...msgResult.rows[0],
        username: userResult.rows[0].username
      };

      io.to(`conversation:${conversationId}`).emit('new_message', message);

      const members = await pool.query(
        `SELECT user_id FROM conversation_members
         WHERE conversation_id = $1 AND user_id != $2`,
        [conversationId, userId]
      );

      for (const member of members.rows) {
        const notificationResult = await pool.query(
          `INSERT INTO notifications (user_id, type, content)
           VALUES ($1, $2, $3)
           RETURNING *`,
          [member.user_id, 'message', `New message from ${message.username}`]
        );

        const targetSocketId = onlineUsers.get(member.user_id);
        if (targetSocketId) {
          io.to(targetSocketId).emit('new_notification', notificationResult.rows[0]);
        }
      }
    } catch (err) {
      console.error('send_message error', err);
    }
  });

  socket.on('disconnect', () => {
    onlineUsers.delete(userId);
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

