  }, []);

  const joinConversation = async () => {
    if (!conversationId || !socket) return;
    socket.emit('join_conversation', conversationId);
    const res = await API.get(`/conversations/${conversationId}/messages`);
    setMessages(res.data);
  };

  const sendMessage = () => {
    if (!content || !socket) return;
    socket.emit('send_message', { conversationId, content });
    setContent('');
  };

  const markRead = async (id) => {
    await API.post(`/notifications/${id}/read`);
    setNotifications(prev =>
      prev.map(n => n.id === id ? { ...n, is_read: true } : n)
    );
  };

  const subscribe = async () => {
    const res = await API.post('/billing/create-checkout-session');
    window.location.href = res.data.url;
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>Chat App</h2>
      {me && (
        <div>
          <p>Logged in as <b>{me.username}</b></p>
          <p>Plan: <b>{me.subscription_status}</b></p>
          {me.subscription_status === 'free' && (
            <button onClick={subscribe}>Upgrade</button>
          )}
        </div>
      )}

      <div style={{ marginTop: 20 }}>
        <input
          placeholder="Conversation ID"
          value={conversationId}
          onChange={e => setConversationId(e.target.value)}
        />
        <button onClick={joinConversation}>Join</button>
      </div>

      <div style={{ border: '1px solid #000', minHeight: 200, marginTop: 20, padding: 10 }}>
        {messages.map(msg => (
          <div key={msg.id}>
            <b>{msg.username}:</b> {msg.content}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 10 }}>
        <input
          placeholder="Type message"
          value={content}
          onChange={e => setContent(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>

      <Notifications notifications={notifications} markRead={markRead} />
    </div>
  );
}

function Home() {
  return (
    <div style={{ padding: 20 }}>
      <h1>Social Messaging App</h1>
      <Link to="/register">Register</Link> | <Link to="/login">Login</Link>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/register" element={<Register />} />
        <Route path="/login" element={<Login />} />
        <Route path="/chat" element={<Chat />} />
        <Route path="/billing/success" element={<div>Subscription successful</div>} />
        <Route path="/billing/cancel" element={<div>Subscription canceled</div>} />
      </Routes>
    </BrowserRouter>
  );
}
