const express = require('express');
const Stripe = require('stripe');
const auth = require('../middleware/auth');
const Purchase = require('../models/Purchase');
const User = require('../models/User');
const Notification = require('../models/Notification');

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

// Create checkout session
router.post('/create-checkout-session', auth, async (req, res) => {
  try {
    const { productType } = req.body;

    let line_item;
    let amount = 0;

    if (productType === 'premium') {
      amount = 999;
      line_item = {
        price_data: {
          currency: 'usd',
          product_data: { name: 'Premium Upgrade' },
          unit_amount: amount
        },
        quantity: 1
      };
    } else if (productType === 'coins') {
      amount = 499;
      line_item = {
        price_data: {
          currency: 'usd',
          product_data: { name: '100 Coins Pack' },
          unit_amount: amount
        },
        quantity: 1
      };
    } else {
      return res.status(400).json({ message: 'Invalid product type' });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [line_item],
      mode: 'payment',
      success_url: `${process.env.CLIENT_URL}/payment-success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.CLIENT_URL}/payment-cancelled`,
      metadata: {
        userId: req.user.id,
        productType
      }
    });

    await Purchase.create({
      user: req.user.id,
      stripeSessionId: session.id,
      productType,
      amount,
      status: 'pending'
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Confirm payment manually for demo
router.post('/confirm-session', auth, async (req, res) => {
  try {
    const { sessionId } = req.body;

    const purchase = await Purchase.findOne({ stripeSessionId: sessionId, user: req.user.id });
    if (!purchase) return res.status(404).json({ message: 'Purchase not found' });

    if (purchase.status === 'paid') {
      return res.json({ message: 'Already processed' });
    }

    const user = await User.findById(req.user.id);

    if (purchase.productType === 'premium') {
      user.isPremium = true;
    } else if (purchase.productType === 'coins') {
      user.coins += 100;
    }

    await user.save();

    purchase.status = 'paid';
    await purchase.save();

    const notification = await Notification.create({
      user: req.user.id,
      type: 'purchase',
      content: `Purchase successful: ${purchase.productType}`,
      meta: { purchaseId: purchase._id }
    });

    const io = req.app.get('io');
    io.to(req.user.id).emit('new_notification', notification);

    res.json({
      message: 'Payment confirmed',
      user: {
        id: user._id,
        isPremium: user.isPremium,
        coins: user.coins
      }
    });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

module.exports = router;
