# 5. Stripe Webhook Example

For production, replace manual confirmation with a webhook.

## Add route in `routes/monetization.js`

```js
const express = require('express');
const Stripe = require('stripe');
const Purchase = require('../models/Purchase');
const User = require('../models/User');
const Notification = require('../models/Notification');

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];

  try {
    const event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;
      const { userId, productType } = session.metadata;

      const purchase = await Purchase.findOne({ stripeSessionId: session.id });
      if (purchase && purchase.status !== 'paid') {
        const user = await User.findById(userId);

        if (productType === 'premium') {
          user.isPremium = true;
        } else if (productType === 'coins') {
          user.coins += 100;
        }

        await user.save();

        purchase.status = 'paid';
        await purchase.save();

        await Notification.create({
          user: userId,
          type: 'purchase',
          content: `Purchase successful: ${productType}`,
          meta: { purchaseId: purchase._id }
        });
      }
    }

    res.json({ received: true });
  } catch (err) {
    res.status(400).send(`Webhook Error: ${err.message}`);
  }
});

module.exports = router;
```

