## `server/routes/messages.js`

```js
const express = require('express');
const auth = require('../middleware/auth');
const Message = require('../models/Message');
const User = require('../models/User');

module.exports = function (io, onlineUsers) {
  const router = express.Router();

  router.get('/:userId', auth, async (req, res) => {
    try {
      const myId = req.user.id;
      const otherId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: myId, recipient: otherId },
          { sender: otherId, recipient: myId }
        ]
      }).sort({ createdAt: 1 });

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: 'Failed to fetch messages' });
    }
  });

  router.post('/', auth, async (req, res) => {
    try {
      const { recipientId, text } = req.body;
      const senderId = req.user.id;

      const sender = await User.findById(senderId);

      if (!sender.isPremium && text.length > 200) {
        return res.status(403).json({
          message: 'Free users can only send messages up to 200 characters'
        });
      }

      const message = await Message.create({
        sender: senderId,
        recipient: recipientId,
        text
      });

      const populatedMessage = await Message.findById(message._id)
        .populate('sender', '_id username')
        .populate('recipient', '_id username');

      const recipientSocketId = onlineUsers.get(recipientId);

      if (recipientSocketId) {
        io.to(recipientSocketId).emit('new_message', populatedMessage);
        io.to(recipientSocketId).emit('notification', {
          type: 'message',
          title: 'New Message',
          body: `${sender.username} sent you a message`
        });
      }

      res.json(populatedMessage);
    } catch (err) {
      res.status(500).json({ message: 'Failed to send message', error: err.message });
    }
  });

  return router;
};
```

