```js
const express = require('express');
const Stripe = require('stripe');
const auth = require('../middleware/auth');
const User = require('../models/User');
const Purchase = require('../models/Purchase');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post('/create-checkout-session', auth, async (req, res) => {
  try {
    const { mode } = req.body; // 'subscription' or 'payment'
    const user = await User.findById(req.user.id);

    let customerId = user.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        metadata: { userId: user._id.toString() }
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      payment_method_types: ['card'],
      mode,
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: mode === 'subscription' ? 'Premium Plan' : 'Message Boost'
            },
            recurring:
              mode === 'subscription'
                ? { interval: 'month' }
                : undefined,
            unit_amount: mode === 'subscription' ? 999 : 299
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}?payment=success`,
      cancel_url: `${process.env.CLIENT_URL}?payment=cancelled`
    });

    await Purchase.create({
      user: user._id,
      stripeSessionId: session.id,
      type: mode === 'subscription' ? 'subscription' : 'one_time',
      status: 'pending',
      amount: mode === 'subscription' ? 999 : 299,
      currency: 'usd'
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: 'Payment session creation failed', error: err.message });
  }
});

router.post(
  '/webhook',
  express.raw({ type: 'application/json' }),
  async (req, res) => {
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers['stripe-signature'],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;

      const purchase = await Purchase.findOne({ stripeSessionId: session.id }).populate('user');

      if (purchase) {
        purchase.status = 'completed';
        purchase.stripePaymentIntentId = session.payment_intent || null;
        await purchase.save();

        if (purchase.type === 'subscription') {
          const user = await User.findById(purchase.user._id);
          user.isPremium = true;
          await user.save();
        }
      }
    }

    res.json({ received: true });
  }
);

module.exports = router;
```

