import React, { useEffect, useState } from 'react';
import API from '../api';
import socket from '../socket';
import PremiumBanner from './PremiumBanner';

export default function Chat({ user }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);

  useEffect(() => {
    socket.emit('register_user', user.id);

    socket.on('new_message', (message) => {
      if (
        selectedUser &&
        (message.sender._id === selectedUser._id ||
          message.recipient._id === selectedUser._id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on('notification', (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    socket.on('online_users', (list) => {
      setOnlineUsers(list);
    });

    return () => {
      socket.off('new_message');
      socket.off('notification');
      socket.off('online_users');
    };
  }, [selectedUser, user.id]);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const res = await API.get('/users');
    setUsers(res.data);
  };

  const loadMessages = async (otherUser) => {
    setSelectedUser(otherUser);
    const res = await API.get(`/messages/${otherUser._id}`);
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!selectedUser || !text.trim()) return;

    const res = await API.post('/messages', {
      recipientId: selectedUser._id,
      text
    });

    setMessages((prev) => [...prev, res.data]);
    setText('');
  };

  return (
    <div style={{ display: 'flex', gap: 20, padding: 20 }}>
      <div style={{ width: 250 }}>
        <PremiumBanner user={user} />
        <h3>Users</h3>
        {users.map((u) => (
          <div
            key={u._id}
            onClick={() => loadMessages(u)}
            style={{
              cursor: 'pointer',
              padding: 8,
              border: '1px solid #ccc',
              marginBottom: 6
            }}
          >
            {u.username} {onlineUsers.includes(u._id) ? '🟢' : '⚪'}
            {u.isPremium ? ' ⭐' : ''}
          </div>
        ))}

        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i} style={{ borderBottom: '1px solid #eee', padding: 6 }}>
            <strong>{n.title}</strong>
            <div>{n.body}</div>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>
          Chat {selectedUser ? `with ${selectedUser.username}` : ''}
        </h3>

        <div
          style={{
            minHeight: 300,
            border: '1px solid #ccc',
            padding: 12,
            marginBottom: 12
          }}
        >
          {messages.map((m) => (
            <div key={m._id} style={{ marginBottom: 8 }}>
              <strong>
                {m.sender._id === user.id ? 'You' : m.sender.username}:
              </strong>{' '}
              {m.text}
            </div>
          ))}
        </div>

        {selectedUser && (
          <>
            <textarea
              rows="4"
              style={{ width: '100%' }}
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type your message..."
            />
            <button onClick={sendMessage}>Send</button>
          </>
        )}
      </div>
    </div>
  );
}
