import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import Conversation from "../models/Conversation.js";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";

const router = express.Router();

router.post("/conversation", authMiddleware, async (req, res) => {
  try {
    const { participantId } = req.body;

    let conversation = await Conversation.findOne({
      participants: { $all: [req.user.id, participantId], $size: 2 }
    });

    if (!conversation) {
      conversation = await Conversation.create({
        participants: [req.user.id, participantId]
      });
    }

    res.json(conversation);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.get("/conversation/:conversationId", authMiddleware, async (req, res) => {
  try {
    const messages = await Message.find({
      conversationId: req.params.conversationId
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.get("/conversations", authMiddleware, async (req, res) => {
  try {
    const conversations = await Conversation.find({
      participants: req.user.id
    })
      .populate("participants", "username email avatar")
      .sort({ updatedAt: -1 });

    res.json(conversations);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.post("/", authMiddleware, async (req, res) => {
  try {
    const { conversationId, text, recipientId } = req.body;

    const message = await Message.create({
      conversationId,
      sender: req.user.id,
      text,
      readBy: [req.user.id]
    });

    await Conversation.findByIdAndUpdate(conversationId, {
      lastMessage: text
    });

    const notification = await Notification.create({
      user: recipientId,
      type: "message",
      title: "New message",
      body: text,
      meta: { conversationId, senderId: req.user.id }
    });

    const io = req.app.get("io");
    io.to(recipientId).emit("new_message", message);
    io.to(recipientId).emit("new_notification", notification);
    io.to(conversationId).emit("conversation_message", message);

    res.json(message);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

export default router;
