## `server/src/routes/billing.js`

```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import User from "../models/User.js";
import Subscription from "../models/Subscription.js";
import Notification from "../models/Notification.js";
import { stripe } from "../config/stripe.js";

const router = express.Router();

router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const user = await User.findById(req.user.id);

    let customerId = user.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username,
        metadata: { userId: user._id.toString() }
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "subscription",
      customer: customerId,
      line_items: [
        {
          price: process.env.STRIPE_PRICE_ID,
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/billing?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/billing?canceled=true`
    });

    res.json({ url: session.url });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.post(
  "/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;

    try {
      const signature = req.headers["stripe-signature"];
      event = stripe.webhooks.constructEvent(
        req.body,
        signature,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    try {
      if (event.type === "checkout.session.completed") {
        const session = event.data.object;

        const customerId = session.customer;
        const subscriptionId = session.subscription;

        const customer = await stripe.customers.retrieve(customerId);
        const userId = customer.metadata.userId;

        const stripeSub = await stripe.subscriptions.retrieve(subscriptionId);

        await Subscription.findOneAndUpdate(
          { user: userId },
          {
            user: userId,
            stripeSubscriptionId: subscriptionId,
            stripeCustomerId: customerId,
            status: stripeSub.status,
            currentPeriodEnd: new Date(stripeSub.current_period_end * 1000)
          },
          { upsert: true, new: true }
        );

        await User.findByIdAndUpdate(userId, { isPremium: true });

        const notification = await Notification.create({
          user: userId,
          type: "subscription",
          title: "Subscription activated",
          body: "Your premium subscription is now active."
        });

        global.io?.to(userId).emit("new_notification", notification);
      }

      if (event.type === "customer.subscription.deleted") {
        const sub = event.data.object;

        const existing = await Subscription.findOne({
          stripeSubscriptionId: sub.id
        });

        if (existing) {
          await Subscription.findByIdAndUpdate(existing._id, {
            status: sub.status
          });

          await User.findByIdAndUpdate(existing.user, { isPremium: false });

          const notification = await Notification.create({
            user: existing.user,
            type: "subscription",
            title: "Subscription canceled",
            body: "Your premium subscription has ended."
          });

          global.io?.to(existing.user.toString()).emit("new_notification", notification);
        }
      }

      res.json({ received: true });
    } catch (error) {
      res.status(500).send(error.message);
    }
  }
);

export default router;
```

