```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import API from "../api";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ goBilling }) {
  const user = JSON.parse(localStorage.getItem("user"));
  const socket = useMemo(() => io("http://localhost:5000"), []);
  const [users, setUsers] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [typing, setTyping] = useState("");

  useEffect(() => {
    socket.emit("join_user_room", user._id);

    API.get("/users").then((res) => setUsers(res.data));
    API.get("/messages/conversations").then((res) => setConversations(res.data));

    socket.on("conversation_message", (message) => {
      if (message.conversationId === activeConversation?._id) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("typing", ({ userId }) => {
      setTyping(`${userId} is typing...`);
    });

    socket.on("stop_typing", () => {
      setTyping("");
    });

    return () => {
      socket.disconnect();
    };
  }, [socket, user._id, activeConversation?._id]);

  const startConversation = async (participantId) => {
    const res = await API.post("/messages/conversation", { participantId });
    setActiveConversation(res.data);
    socket.emit("join_conversation", res.data._id);

    const msgRes = await API.get(`/messages/conversation/${res.data._id}`);
    setMessages(msgRes.data);
  };

  const sendMessage = async () => {
    if (!text || !activeConversation) return;

    const recipient = activeConversation.participants.find((p) => p !== user._id);

    await API.post("/messages", {
      conversationId: activeConversation._id,
      text,
      recipientId: recipient
    });

    socket.emit("stop_typing", {
      conversationId: activeConversation._id,
      userId: user._id
    });

    setText("");
  };

  return (
    <div style={{ display: "flex", padding: 20, gap: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u._id}>
            <button onClick={() => startConversation(u._id)}>{u.username}</button>
          </div>
        ))}

        <hr />
        <NotificationBell socket={socket} />
        <hr />
        <button onClick={goBilling}>Upgrade</button>
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 10 }}>
          {messages.map((m) => (
            <div key={m._id}>
              <b>{m.sender === user._id ? "Me" : "Them"}:</b> {m.text}
            </div>
          ))}
          <div>{typing}</div>
        </div>

        <input
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            if (activeConversation) {
              socket.emit("typing", {
                conversationId: activeConversation._id,
                userId: user.username
              });
            }
          }}
          placeholder="Type a message"
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
