## `server/src/routes/messages.js`

```js
import express from 'express';
import { prisma } from '../db.js';
import { authMiddleware } from '../middleware/auth.js';

export default function messageRoutes(io, onlineUsers) {
  const router = express.Router();

  router.get('/:conversationId', authMiddleware, async (req, res) => {
    try {
      const { conversationId } = req.params;

      const member = await prisma.conversationMember.findFirst({
        where: {
          conversationId,
          userId: req.user.userId
        }
      });

      if (!member) {
        return res.status(403).json({ error: 'Not a conversation member' });
      }

      const messages = await prisma.message.findMany({
        where: { conversationId },
        include: {
          sender: {
            select: { id: true, username: true }
          }
        },
        orderBy: { createdAt: 'asc' }
      });

      res.json(messages);
    } catch (err) {
      res.status(500).json({ error: 'Failed to fetch messages', details: err.message });
    }
  });

  router.post('/', authMiddleware, async (req, res) => {
    try {
      const { conversationId, content } = req.body;

      if (!conversationId || !content?.trim()) {
        return res.status(400).json({ error: 'conversationId and content required' });
      }

      const membership = await prisma.conversationMember.findFirst({
        where: {
          conversationId,
          userId: req.user.userId
        }
      });

      if (!membership) {
        return res.status(403).json({ error: 'Not a conversation member' });
      }

      const sender = await prisma.user.findUnique({
        where: { id: req.user.userId }
      });

      const memberCount = await prisma.conversationMember.count({
        where: { userId: req.user.userId }
      });

      if (sender.subscriptionStatus === 'FREE' && memberCount > 3) {
        return res.status(402).json({
          error: 'Premium required to message in more than 3 conversations'
        });
      }

      const message = await prisma.message.create({
        data: {
          content,
          senderId: req.user.userId,
          conversationId
        },
        include: {
          sender: {
            select: { id: true, username: true }
          }
        }
      });

      const recipients = await prisma.conversationMember.findMany({
        where: {
          conversationId,
          NOT: { userId: req.user.userId }
        }
      });

      for (const recipient of recipients) {
        const notification = await prisma.notification.create({
          data: {
            userId: recipient.userId,
            type: 'NEW_MESSAGE',
            content: `New message from ${message.sender.username}: ${message.content.slice(0, 50)}`
          }
        });

        const socketId = onlineUsers.get(recipient.userId);
        if (socketId) {
          io.to(socketId).emit('notification:new', notification);
          io.to(socketId).emit('message:new', message);
        }
      }

      res.json(message);
    } catch (err) {
      res.status(500).json({ error: 'Failed to send message', details: err.message });
    }
  });

  return router;
}
```

