```jsx
import { useEffect, useState } from 'react';
import { api } from '../api';

export default function Chat({ socket, conversationId }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState('');
  const [typingUsers, setTypingUsers] = useState({});

  useEffect(() => {
    if (!conversationId) return;
    loadMessages();

    if (!socket) return;

    socket.emit('conversation:join', conversationId);

    socket.on('message:new', (message) => {
      if (message.conversationId === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on('typing:start', ({ userId, username, conversationId: cid }) => {
      if (cid === conversationId) {
        setTypingUsers((prev) => ({ ...prev, [userId]: username }));
      }
    });

    socket.on('typing:stop', ({ userId, conversationId: cid }) => {
      if (cid === conversationId) {
        setTypingUsers((prev) => {
          const copy = { ...prev };
          delete copy[userId];
          return copy;
        });
      }
    });

    return () => {
      socket.emit('conversation:leave', conversationId);
      socket.off('message:new');
      socket.off('typing:start');
      socket.off('typing:stop');
    };
  }, [conversationId, socket]);

  async function loadMessages() {
    const res = await api.get(`/messages/${conversationId}`);
    setMessages(res.data);
  }

  async function sendMessage() {
    if (!content.trim()) return;
    await api.post('/messages', { conversationId, content });
    setContent('');
    socket.emit('typing:stop', { conversationId });
  }

  function handleTyping(e) {
    setContent(e.target.value);
    socket.emit('typing:start', { conversationId });

    clearTimeout(window.typingTimeout);
    window.typingTimeout = setTimeout(() => {
      socket.emit('typing:stop', { conversationId });
    }, 1000);
  }

  return (
    <div>
      <h3>Chat</h3>
      <div>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.sender.username}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div>
        {Object.values(typingUsers).length > 0 && (
          <small>{Object.values(typingUsers).join(', ')} typing...</small>
        )}
      </div>

      <input value={content} onChange={handleTyping} placeholder="Type a message..." />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
