require("dotenv").config();
const express = require("express");
const http = require("http");
const cors = require("cors");
const jwt = require("jsonwebtoken");
const bcrypt = require("bcryptjs");
const { Server } = require("socket.io");
const Stripe = require("stripe");
const { PrismaClient } = require("@prisma/client");

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: "No token" });

  const token = authHeader.split(" ")[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/auth/register", async (req, res) => {
  try {
    const { email, username, password } = req.body;
    const passwordHash = await bcrypt.hash(password, 10);

    const user = await prisma.user.create({
      data: { email, username, passwordHash }
    });

    const token = jwt.sign(
      { userId: user.id, username: user.username },
      process.env.JWT_SECRET,
      { expiresIn: "7d" }
    );

    res.json({ token, user });
  } catch (err) {
    res.status(400).json({ error: "Registration failed", details: err.message });
  }
});

app.post("/auth/login", async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) return res.status(400).json({ error: "Invalid credentials" });

    const valid = await bcrypt.compare(password, user.passwordHash);
    if (!valid) return res.status(400).json({ error: "Invalid credentials" });

    const token = jwt.sign(
      { userId: user.id, username: user.username },
      process.env.JWT_SECRET,
      { expiresIn: "7d" }
    );

    res.json({ token, user });
  } catch (err) {
    res.status(500).json({ error: "Login failed" });
  }
});

app.post("/conversations", authMiddleware, async (req, res) => {
  try {
    const conversation = await prisma.conversation.create({ data: {} });
    res.json(conversation);
  } catch (err) {
    res.status(500).json({ error: "Could not create conversation" });
  }
});

app.get("/conversations/:id/messages", authMiddleware, async (req, res) => {
  try {
    const messages = await prisma.message.findMany({
      where: { conversationId: req.params.id },
      orderBy: { createdAt: "asc" }
    });
    res.json(messages);
  } catch {
    res.status(500).json({ error: "Could not fetch messages" });
  }
});

app.post("/messages", authMiddleware, async (req, res) => {
  try {
    const { conversationId, content } = req.body;

    const message = await prisma.message.create({
      data: {
        content,
        conversationId,
        senderId: req.user.userId
      }
    });

    io.to(conversationId).emit("new_message", message);
    io.to(conversationId).emit("notification", {
      type: "message",
      conversationId,
      text: "New message received"
    });

    res.json(message);
  } catch (err) {
    res.status(500).json({ error: "Could not send message" });
  }
});

app.post("/billing/create-subscription", authMiddleware, async (req, res) => {
  try {
    const { paymentMethodId, priceId } = req.body;

    let subscriptionRecord = await prisma.subscription.findFirst({
      where: { userId: req.user.userId }
    });

    let customerId = subscriptionRecord?.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        payment_method: paymentMethodId,
        email: req.user.username,
        invoice_settings: { default_payment_method: paymentMethodId }
      });
      customerId = customer.id;
    }

    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{ price: priceId }],
      expand: ["latest_invoice.payment_intent"]
    });

    await prisma.subscription.upsert({
      where: { id: subscriptionRecord?.id || "new-id-placeholder" },
      update: {
        stripeCustomerId: customerId,
        stripeSubscriptionId: subscription.id,
        status: subscription.status
      },
      create: {
        userId: req.user.userId,
        stripeCustomerId: customerId,
        stripeSubscriptionId: subscription.id,
        status: subscription.status
      }
    });

    res.json(subscription);
  } catch (err) {
    res.status(500).json({ error: "Subscription creation failed", details: err.message });
  }
});

io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("Unauthorized"));

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.user = decoded;
    next();
  } catch {
    next(new Error("Unauthorized"));
  }
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.user.username);

  socket.on("join_conversation", (conversationId) => {
    socket.join(conversationId);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.user.username);
  });
});

server.listen(process.env.PORT, () => {
  console.log(`Server running on port ${process.env.PORT}`);
});
