import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";

const API_URL = "http://localhost:4000";
const socket = io(API_URL, {
  autoConnect: false
});

export default function App() {
  const [token, setToken] = useState("");
  const [conversationId, setConversationId] = useState("");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notification, setNotification] = useState("");

  useEffect(() => {
    if (token) {
      socket.auth = { token };
      socket.connect();

      socket.on("new_message", (message) => {
        setMessages((prev) => [...prev, message]);
      });

      socket.on("notification", (data) => {
        setNotification(data.text);
        setTimeout(() => setNotification(""), 3000);
      });
    }

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, [token]);

  const register = async () => {
    const res = await fetch(`${API_URL}/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: "test@example.com",
        username: "testuser",
        password: "password123"
      })
    });
    const data = await res.json();
    setToken(data.token);
  };

  const createConversation = async () => {
    const res = await fetch(`${API_URL}/conversations`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      }
    });
    const data = await res.json();
    setConversationId(data.id);
    socket.emit("join_conversation", data.id);
  };

  const sendMessage = async () => {
    await fetch(`${API_URL}/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({
        conversationId,
        content
      })
    });
    setContent("");
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Social Messaging App</h1>

      {!token && <button onClick={register}>Register Demo User</button>}

      {token && (
        <>
          <button onClick={createConversation}>Create Conversation</button>
          <p>Conversation ID: {conversationId}</p>

          {notification && (
            <div style={{ background: "#ffd", padding: 10, marginBottom: 10 }}>
              {notification}
            </div>
          )}

          <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 200 }}>
            {messages.map((msg) => (
              <div key={msg.id}>
                <strong>{msg.senderId}</strong>: {msg.content}
              </div>
            ))}
          </div>

          <input
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={sendMessage}>Send</button>
        </>
      )}
    </div>
  );
}
```

