# 12. Billing routes

Create `src/routes/billing.js`:

```js
const express = require('express');
const Stripe = require('stripe');
const prisma = require('../db');
const authMiddleware = require('../middleware/auth');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post('/create-checkout-session', authMiddleware, async (req, res) => {
  try {
    const { mode } = req.body; // "subscription" or "credits"

    const prices = {
      subscription: 'price_subscription_id',
      credits: 'price_credits_id'
    };

    if (!prices[mode]) {
      return res.status(400).json({ error: 'Invalid billing mode' });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      mode: mode === 'subscription' ? 'subscription' : 'payment',
      line_items: [
        {
          price: prices[mode],
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/billing/success`,
      cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
      metadata: {
        userId: req.user.userId,
        mode
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: 'Failed to create checkout session', details: err.message });
  }
});

router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  let event;
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      req.headers['stripe-signature'],
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const mode = session.metadata.mode;

    if (mode === 'credits') {
      await prisma.user.update({
        where: { id: userId },
        data: { credits: { increment: 10 } }
      });
    }

    if (mode === 'subscription') {
      await prisma.subscription.update({
        where: { userId },
        data: {
          status: 'active',
          stripeCustomerId: session.customer,
          stripeSubId: session.subscription
        }
      });
    }
  }

  res.json({ received: true });
});

module.exports = router;
```

