# 9. Messaging routes with real-time notifications

## `server/src/routes/messages.js`

```js
import express from 'express';
import prisma from '../lib/prisma.js';
import { authMiddleware } from '../middleware/auth.js';
import { getIO, getUserSocketId } from '../lib/socket.js';

const router = express.Router();

router.post('/', authMiddleware, async (req, res) => {
  try {
    const { receiverId, content } = req.body;

    if (!receiverId || !content?.trim()) {
      return res.status(400).json({ error: 'receiverId and content are required' });
    }

    const message = await prisma.message.create({
      data: {
        senderId: req.user.id,
        receiverId,
        content: content.trim()
      }
    });

    const notification = await prisma.notification.create({
      data: {
        userId: receiverId,
        type: 'message',
        content: `New message from ${req.user.username}`
      }
    });

    const io = getIO();
    const receiverSocketId = getUserSocketId(receiverId);

    if (io && receiverSocketId) {
      io.to(receiverSocketId).emit('new_message', message);
      io.to(receiverSocketId).emit('new_notification', notification);
    }

    res.json({ message });
  } catch (err) {
    res.status(500).json({ error: 'Failed to send message', details: err.message });
  }
});

router.get('/:userId', authMiddleware, async (req, res) => {
  try {
    const currentUserId = req.user.id;
    const otherUserId = req.params.userId;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: currentUserId, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: currentUserId }
        ]
      },
      orderBy: { createdAt: 'asc' }
    });

    res.json({ messages });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages', details: err.message });
  }
});

router.get('/notifications/all', authMiddleware, async (req, res) => {
  try {
    const notifications = await prisma.notification.findMany({
      where: { userId: req.user.id },
      orderBy: { createdAt: 'desc' }
    });

    res.json({ notifications });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch notifications', details: err.message });
  }
});

router.patch('/notifications/:id/read', authMiddleware, async (req, res) => {
  try {
    const notification = await prisma.notification.update({
      where: { id: req.params.id },
      data: { read: true }
    });

    res.json({ notification });
  } catch (err) {
    res.status(500).json({ error: 'Failed to update notification', details: err.message });
  }
});

export default router;
```

