```jsx
import React, { useEffect, useState } from 'react';
import API from '../api';
import socket from '../socket';

export default function Chat({ currentUser, selectedUser }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState('');

  useEffect(() => {
    if (!selectedUser) return;

    API.get(`/messages/${selectedUser.id}`)
      .then((res) => setMessages(res.data.messages))
      .catch(console.error);
  }, [selectedUser]);

  useEffect(() => {
    const handleNewMessage = (message) => {
      const isRelevant =
        (message.senderId === selectedUser?.id && message.receiverId === currentUser.id) ||
        (message.senderId === currentUser.id && message.receiverId === selectedUser?.id);

      if (isRelevant) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on('new_message', handleNewMessage);

    return () => {
      socket.off('new_message', handleNewMessage);
    };
  }, [selectedUser, currentUser]);

  const sendMessage = async () => {
    if (!content.trim() || !selectedUser) return;

    const res = await API.post('/messages', {
      receiverId: selectedUser.id,
      content
    });

    setMessages((prev) => [...prev, res.data.message]);
    setContent('');
  };

  return (
    <div>
      <h2>Chat with {selectedUser?.username}</h2>
      <div style={{ border: '1px solid #ccc', height: 300, overflowY: 'auto', padding: 10 }}>
        {messages.map((msg) => (
          <div key={msg.id} style={{ marginBottom: 8 }}>
            <strong>{msg.senderId === currentUser.id ? 'You' : selectedUser.username}:</strong> {msg.content}
          </div>
        ))}
      </div>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
