## backend/src/controllers/billing.controller.js

```js
const prisma = require("../lib/prisma");
const stripe = require("../lib/stripe");
const { createNotification } = require("../services/notification.service");
const { STRIPE_WEBHOOK_SECRET } = require("../config/env");

exports.createCheckoutSession = async (req, res, next) => {
  try {
    const { type } = req.body;

    let line_item;

    if (type === "credits_pack") {
      line_item = {
        price_data: {
          currency: "usd",
          product_data: { name: "10 Message Credits" },
          unit_amount: 500
        },
        quantity: 1
      };
    } else if (type === "premium_subscription") {
      line_item = {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Subscription" },
          unit_amount: 999,
          recurring: { interval: "month" }
        },
        quantity: 1
      };
    } else {
      return res.status(400).json({ message: "Invalid billing type" });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: type === "premium_subscription" ? "subscription" : "payment",
      line_items: [line_item],
      success_url: "http://localhost:5173/billing?success=true",
      cancel_url: "http://localhost:5173/billing?canceled=true",
      metadata: {
        userId: req.user.id,
        type
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    next(err);
  }
};

exports.handleWebhook = async (req, res, next) => {
  try {
    const stripe = require("../lib/stripe");
    const sig = req.headers["stripe-signature"];

    const event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      STRIPE_WEBHOOK_SECRET
    );

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;
      const type = session.metadata.type;

      await prisma.payment.create({
        data: {
          userId,
          stripePaymentId: session.payment_intent || session.id,
          amount: session.amount_total || 0,
          currency: session.currency || "usd",
          status: "SUCCEEDED",
          type
        }
      });

      if (type === "credits_pack") {
        await prisma.user.update({
          where: { id: userId },
          data: { credits: { increment: 10 } }
        });
      }

      if (type === "premium_subscription") {
        await prisma.user.update({
          where: { id: userId },
          data: { subscriptionStatus: "PREMIUM" }
        });
      }

      await createNotification(
        userId,
        "PAYMENT",
        "Payment successful",
        `Your purchase of ${type} was successful`
      );
    }

    res.json({ received: true });
  } catch (err) {
    next(err);
  }
};
```

