## frontend/src/pages/ChatPage.jsx

```jsx
import React, { useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import ChatWindow from "../components/ChatWindow";
import NotificationBell from "../components/NotificationBell";
import BillingPage from "./BillingPage";

export default function ChatPage() {
  const [me, setMe] = useState(null);
  const [otherUserId, setOtherUserId] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [showBilling, setShowBilling] = useState(false);

  useEffect(() => {
    const init = async () => {
      const meRes = await api.get("/users/me");
      setMe(meRes.data);

      const notifRes = await api.get("/notifications");
      setNotifications(notifRes.data);

      socket.connect();
      socket.emit("register", meRes.data.id);

      socket.on("message:new", (message) => {
        if (
          message.senderId === otherUserId ||
          message.receiverId === otherUserId
        ) {
          setMessages((prev) => [...prev, message]);
        }
      });

      socket.on("notification:new", (notification) => {
        setNotifications((prev) => [notification, ...prev]);
      });
    };

    init();

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
      socket.disconnect();
    };
  }, [otherUserId]);

  const loadConversation = async () => {
    const res = await api.get(`/messages/${otherUserId}`);
    setMessages(res.data);
  };

  if (!me) return <div>Loading...</div>;

  return (
    <div style={{ padding: 24 }}>
      <h2>Welcome, {me.username}</h2>
      <p>
        Subscription: {me.subscriptionStatus} | Credits: {me.credits}
      </p>

      <NotificationBell
        notifications={notifications}
        onRead={async (id) => {
          await api.patch(`/notifications/${id}/read`);
          setNotifications((prev) =>
            prev.map((n) => (n.id === id ? { ...n, isRead: true } : n))
          );
        }}
      />

      <button onClick={() => setShowBilling(!showBilling)}>
        {showBilling ? "Hide Billing" : "Show Billing"}
      </button>

      {showBilling && <BillingPage />}

      <div style={{ marginTop: 20 }}>
        <input
          placeholder="Enter other user ID"
          value={otherUserId}
          onChange={(e) => setOtherUserId(e.target.value)}
        />
        <button onClick={loadConversation}>Load Chat</button>
      </div>

      <ChatWindow
        me={me}
        otherUserId={otherUserId}
        messages={messages}
        onMessageSent={(message) => setMessages((prev) => [...prev, message])}
      />
    </div>
  );
}
