# 6. Important Fix for Stripe Webhook Parsing

There is one subtle issue in Express apps: **Stripe webhook routes must receive the raw body**, not JSON-parsed body.

A safer `app.js` is:

```js
const express = require("express");
const cors = require("cors");
const authRoutes = require("./routes/auth.routes");
const userRoutes = require("./routes/user.routes");
const messageRoutes = require("./routes/message.routes");
const notificationRoutes = require("./routes/notification.routes");
const billingRoutes = require("./routes/billing.routes");
const errorHandler = require("./middleware/errorHandler");
const { CLIENT_URL } = require("./config/env");
const billingController = require("./controllers/billing.controller");

const app = express();

app.use(cors({ origin: CLIENT_URL, credentials: true }));

app.post(
  "/api/billing/webhook",
  express.raw({ type: "application/json" }),
  billingController.handleWebhook
);

app.use(express.json());

app.use("/api/auth", authRoutes);
app.use("/api/users", userRoutes);
app.use("/api/messages", messageRoutes);
app.use("/api/notifications", notificationRoutes);
app.use("/api/billing", billingRoutes);

app.use(errorHandler);

module.exports = app;
```

And then remove webhook registration from `billing.routes.js`:

```js
const router = require("express").Router();
const auth = require("../middleware/auth");
const controller = require("../controllers/billing.controller");

router.post("/checkout", auth, controller.createCheckoutSession);

module.exports = router;
```

This is the preferred version.

