## `backend/src/routes/messages.js`

```js
import express from "express";
import { prisma } from "../db.js";
import { authMiddleware } from "../middleware/auth.js";

export default function messageRoutes(io, onlineUsers) {
  const router = express.Router();

  router.get("/:userId", authMiddleware, async (req, res) => {
    const otherUserId = req.params.userId;
    const currentUserId = req.user.userId;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: currentUserId, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: currentUserId }
        ]
      },
      orderBy: { createdAt: "asc" }
    });

    res.json(messages);
  });

  router.post("/", authMiddleware, async (req, res) => {
    try {
      const { receiverId, content, isPaid = false, priceCents = null } = req.body;
      const senderId = req.user.userId;

      const message = await prisma.message.create({
        data: {
          senderId,
          receiverId,
          content,
          isPaid,
          priceCents
        }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: receiverId,
          type: "message",
          content: `New message from ${req.user.username}`
        }
      });

      const receiverSocketId = onlineUsers.get(receiverId);

      if (receiverSocketId) {
        io.to(receiverSocketId).emit("new_message", message);
        io.to(receiverSocketId).emit("new_notification", notification);
      }

      res.json(message);
    } catch {
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  return router;
}
```

