import React, { useEffect, useState } from "react";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";

export default function App() {
  const [view, setView] = useState(localStorage.getItem("token") ? "chat" : "login");

  useEffect(() => {
    if (!localStorage.getItem("token")) {
      setView("login");
    }
  }, []);

  if (view === "login") {
    return <Login onSwitch={() => setView("register")} onSuccess={() => setView("chat")} />;
  }

  if (view === "register") {
    return <Register onSwitch={() => setView("login")} onSuccess={() => setView("chat")} />;
  }

  return <Chat onLogout={() => setView("login")} />;
}
