```js
import React, { useEffect, useState } from "react";
import API from "../api";
import { socket } from "../socket";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ onLogout }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  const currentUser = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    socket.connect();
    socket.emit("register", currentUser.id);

    fetchUsers();

    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off("new_message");
      socket.disconnect();
    };
  }, [selectedUser]);

  async function fetchUsers() {
    const res = await API.get("/users");
    setUsers(res.data);
  }

  async function fetchMessages(userId) {
    const res = await API.get(`/messages/${userId}`);
    setMessages(res.data);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;

    const res = await API.post("/messages", {
      receiverId: selectedUser.id,
      content
    });

    setMessages(prev => [...prev, res.data]);
    setContent("");
  }

  async function sendPaidMessage() {
    if (!selectedUser || !content.trim()) return;

    const res = await API.post("/messages", {
      receiverId: selectedUser.id,
      content,
      isPaid: true,
      priceCents: 199
    });

    setMessages(prev => [...prev, res.data]);
    setContent("");
  }

  function logout() {
    localStorage.clear();
    onLogout();
  }

  return (
    <div>
      <h2>Chat</h2>
      <NotificationBell />
      <button onClick={logout}>Logout</button>

      <div style={{ display: "flex", gap: "20px" }}>
        <div>
          <h3>Users</h3>
          {users.map(user => (
            <div
              key={user.id}
              onClick={() => {
                setSelectedUser(user);
                fetchMessages(user.id);
              }}
              style={{ cursor: "pointer", padding: "8px", border: "1px solid #ccc" }}
            >
              {user.username}
            </div>
          ))}
        </div>

        <div>
          <h3>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h3>
          <div style={{ minHeight: "300px", border: "1px solid #ccc", padding: "10px" }}>
            {messages.map(msg => (
              <div key={msg.id}>
                <strong>{msg.senderId === currentUser.id ? "You" : selectedUser?.username}:</strong>{" "}
                {msg.content}
                {msg.isPaid && <span> 💎 ${((msg.priceCents || 0) / 100).toFixed(2)}</span>}
              </div>
            ))}
          </div>

          {selectedUser && (
            <>
              <input
                placeholder="Type a message"
                value={content}
                onChange={e => setContent(e.target.value)}
              />
              <button onClick={sendMessage}>Send</button>
              <button onClick={sendPaidMessage}>Send Paid Message</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
```

