## backend/src/services/billing.service.ts

```ts
import Stripe from "stripe";
import { env } from "../config/env";
import { prisma } from "../lib/prisma";
import { createNotification } from "./notification.service";

const stripe = new Stripe(env.STRIPE_SECRET_KEY);

export async function createCheckoutSession(userId: string) {
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) throw new Error("User not found");

  let customerId = user.stripeCustomerId;

  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email,
      metadata: { userId: user.id }
    });

    customerId = customer.id;

    await prisma.user.update({
      where: { id: user.id },
      data: { stripeCustomerId: customerId }
    });
  }

  const session = await stripe.checkout.sessions.create({
    customer: customerId,
    mode: "subscription",
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: "Premium Subscription"
          },
          recurring: {
            interval: "month"
          },
          unit_amount: 999
        },
        quantity: 1
      }
    ],
    success_url: `${env.CLIENT_URL}/billing/success`,
    cancel_url: `${env.CLIENT_URL}/billing/cancel`
  });

  return session;
}

export async function handleStripeWebhook(rawBody: Buffer, signature: string) {
  const stripeEvent = stripe.webhooks.constructEvent(
    rawBody,
    signature,
    env.STRIPE_WEBHOOK_SECRET
  );

  if (stripeEvent.type === "checkout.session.completed") {
    const session = stripeEvent.data.object as Stripe.Checkout.Session;

    const customerId = session.customer as string;

    const user = await prisma.user.findFirst({
      where: { stripeCustomerId: customerId }
    });

    if (user) {
      await prisma.user.update({
        where: { id: user.id },
        data: { subscriptionStatus: "ACTIVE" }
      });

      await createNotification(user.id, "PAYMENT", "Your premium subscription is now active.");
    }
  }

  return stripeEvent;
}
```

