## `client/src/pages/Chat.jsx`

```jsx
import { useEffect, useState } from "react";
import API from "../api";
import { createSocket } from "../socket";
import Sidebar from "../components/Sidebar";
import ChatWindow from "../components/ChatWindow";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ user, token }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    API.get("/users").then((res) => setUsers(res.data));
    API.get("/users/notifications").then((res) => setNotifications(res.data));

    const s = createSocket(token);
    setSocket(s);

    s.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    s.on("new_notification", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    s.on("wallet_updated", ({ amount }) => {
      alert(`Wallet updated by $${(amount / 100).toFixed(2)}`);
    });

    s.on("typing", ({ from }) => {
      if (selectedUser && from === selectedUser.id) {
        console.log("Typing...");
      }
    });

    return () => s.disconnect();
  }, [token, selectedUser]);

  const selectUser = async (u) => {
    setSelectedUser(u);
    const res = await API.get(`/messages/${u.id}`);
    setMessages(res.data);
  };

  const sendMessage = async (content) => {
    if (!selectedUser || !content.trim()) return;
    const res = await API.post("/messages", {
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
  };

  return (
    <div>
      <NotificationBell notifications={notifications} />
      <div style={{ display: "flex" }}>
        <Sidebar users={users} onSelectUser={selectUser} notifications={notifications} />
        <ChatWindow
          selectedUser={selectedUser}
          messages={messages}
          onSend={sendMessage}
          socket={socket}
          currentUser={user}
        />
      </div>
    </div>
  );
}
```

