# 6. Payments / Monetization

This MVP supports **wallet top-up / purchases**.

## `backend/src/routes/payments.js`

```js
import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";
import { authMiddleware } from "../middleware/auth.js";

const router = express.Router();
const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const { amount } = req.body;

    const purchase = await prisma.purchase.create({
      data: {
        userId: req.user.id,
        amount,
        status: "pending"
      }
    });

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Wallet Top-up"
            },
            unit_amount: amount
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/wallet?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=true`,
      metadata: {
        purchaseId: purchase.id
      }
    });

    await prisma.purchase.update({
      where: { id: purchase.id },
      data: { stripeRef: session.id }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: "Payment session failed", error: err.message });
  }
});

export default router;
```

