## `frontend/src/pages/ChatPage.jsx`

```jsx
import React, { useEffect, useState } from "react";
import API from "../api";
import { socket } from "../socket";
import NotificationBell from "../components/NotificationBell";

export default function ChatPage() {
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState([]);

  useEffect(() => {
    API.get("/users").then((res) => setUsers(res.data));

    socket.connect();
    socket.emit("register", currentUser.id);

    socket.on("newMessage", (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off("newMessage");
      socket.disconnect();
    };
  }, [selectedUser]);

  const loadMessages = async (userId) => {
    setSelectedUser(users.find((u) => u.id === userId));
    const res = await API.get(`/messages/${userId}`);
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!selectedUser || !text.trim()) return;

    const res = await API.post("/messages", {
      receiverId: selectedUser.id,
      content: text,
      isPaid: false
    });

    setMessages((prev) => [...prev, res.data.message]);
    socket.emit("sendMessage", res.data.message);
    setText("");
  };

  return (
    <div style={{ display: "flex", padding: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Users</h3>
        <NotificationBell />
        {users.map((user) => (
          <div key={user.id}>
            <button onClick={() => loadMessages(user.id)}>{user.username}</button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, marginLeft: 20 }}>
        <h3>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 10 }}>
          {messages.map((msg) => (
            <div key={msg.id}>
              <strong>{msg.senderId === currentUser.id ? "Me" : "Them"}:</strong> {msg.content}
            </div>
          ))}
        </div>
        {selectedUser && (
          <div style={{ marginTop: 10 }}>
            <input value={text} onChange={(e) => setText(e.target.value)} />
            <button onClick={sendMessage}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
}
