## Payment routes

### `server/src/routes/payments.js`

```js
import express from "express";
import Stripe from "stripe";
import Purchase from "../models/Purchase.js";
import User from "../models/User.js";
import { authMiddleware } from "../middleware/auth.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const { productType } = req.body;

    let line_item;
    let amount = 0;

    if (productType === "premium") {
      amount = 999;
      line_item = {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Upgrade" },
          unit_amount: amount
        },
        quantity: 1
      };
    } else if (productType === "coins") {
      amount = 499;
      line_item = {
        price_data: {
          currency: "usd",
          product_data: { name: "100 Coins Pack" },
          unit_amount: amount
        },
        quantity: 1
      };
    } else {
      return res.status(400).json({ message: "Invalid product type" });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [line_item],
      success_url: `${process.env.CLIENT_URL}/chat?payment=success`,
      cancel_url: `${process.env.CLIENT_URL}/chat?payment=cancel`,
      metadata: {
        userId: req.user.id,
        productType
      }
    });

    await Purchase.create({
      user: req.user.id,
      stripeSessionId: session.id,
      productType,
      amount,
      status: "pending"
    });

    res.json({ url: session.url });
  } catch (error) {
    res.status(500).json({ message: "Failed to create checkout session", error: error.message });
  }
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      req.headers["stripe-signature"],
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const { userId, productType } = session.metadata;

    const purchase = await Purchase.findOne({ stripeSessionId: session.id });
    if (purchase) {
      purchase.status = "paid";
      await purchase.save();
    }

    const user = await User.findById(userId);
    if (user) {
      if (productType === "premium") user.premium = true;
      if (productType === "coins") user.coins += 100;
      await user.save();
    }
  }

  res.json({ received: true });
});

export default router;
```

