```jsx
import React, { useEffect, useState } from "react";
import API from "../api";
import socket from "../socket";
import NotificationBell from "../components/NotificationBell";

export default function Chat() {
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);

  useEffect(() => {
    socket.connect();
    socket.emit("register", currentUser.id);

    socket.on("receive_message", (message) => {
      if (
        selectedUser &&
        (message.sender === selectedUser._id || message.sender === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("notification", (notification) => {
      setNotifications((prev) => [...prev, notification]);
    });

    socket.on("presence:update", (online) => {
      setOnlineUsers(online);
    });

    return () => {
      socket.off("receive_message");
      socket.off("notification");
      socket.off("presence:update");
      socket.disconnect();
    };
  }, [selectedUser, currentUser.id]);

  useEffect(() => {
    API.get("/users").then((res) => {
      setUsers(res.data.filter((u) => u._id !== currentUser.id));
    });
  }, [currentUser.id]);

  const loadMessages = async (user) => {
    setSelectedUser(user);
    const res = await API.get(`/messages/${user._id}`);
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!selectedUser || !text.trim()) return;

    const res = await API.post("/messages", {
      recipient: selectedUser._id,
      content: text
    });

    const outgoing = {
      ...res.data,
      senderName: currentUser.username
    };

    setMessages((prev) => [...prev, outgoing]);

    socket.emit("send_message", {
      recipientId: selectedUser._id,
      message: outgoing
    });

    setText("");
  };

  const buyPremium = async () => {
    const res = await API.post("/payments/create-checkout-session", {
      productType: "premium"
    });
    window.location.href = res.data.url;
  };

  const buyCoins = async () => {
    const res = await API.post("/payments/create-checkout-session", {
      productType: "coins"
    });
    window.location.href = res.data.url;
  };

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Users</h3>
        <NotificationBell notifications={notifications} />
        {users.map((user) => (
          <div
            key={user._id}
            onClick={() => loadMessages(user)}
            style={{ cursor: "pointer", marginBottom: 10 }}
          >
            {user.username} {onlineUsers.includes(user._id) ? "🟢" : "⚪"}
            {user.premium ? " ⭐" : ""}
          </div>
        ))}
        <hr />
        <button onClick={buyPremium}>Buy Premium</button>
        <button onClick={buyCoins}>Buy 100 Coins</button>
      </div>

      <div style={{ flex: 1 }}>
        <h3>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 10 }}>
          {messages.map((m) => (
            <div key={m._id}>
              <strong>{String(m.sender) === currentUser.id ? "Me" : selectedUser?.username}:</strong> {m.content}
            </div>
          ))}
        </div>

        {selectedUser && (
          <div style={{ marginTop: 10 }}>
            <input
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type message"
            />
            <button onClick={sendMessage}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
}
