## backend/src/services/messaging.service.ts

```ts
import { prisma } from "../lib/prisma";
import { createNotification } from "./notification.service";
import { io } from "../sockets";

export async function createConversation(userIds: string[]) {
  const conversation = await prisma.conversation.create({
    data: {
      participants: {
        create: userIds.map((userId) => ({
          userId
        }))
      }
    },
    include: {
      participants: true
    }
  });

  return conversation;
}

export async function sendMessage(
  senderId: string,
  conversationId: string,
  content: string
) {
  const membership = await prisma.conversationUser.findFirst({
    where: { userId: senderId, conversationId }
  });

  if (!membership) {
    throw new Error("Not a participant in this conversation");
  }

  const message = await prisma.message.create({
    data: {
      senderId,
      conversationId,
      content
    }
  });

  const participants = await prisma.conversationUser.findMany({
    where: { conversationId }
  });

  io.to(`conversation:${conversationId}`).emit("message:new", message);

  await Promise.all(
    participants
      .filter((p) => p.userId !== senderId)
      .map((p) =>
        createNotification({
          userId: p.userId,
          type: "MESSAGE",
          title: "New message",
          body: content.slice(0, 120),
          metadata: { conversationId, senderId, messageId: message.id }
        })
      )
  );

  return message;
}
```

