export async function createSubscriptionCheckout(userId: string, priceId: string) {
  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId }
  });

  return session;
}

export async function createOneTimeCheckout(
  userId: string,
  priceId: string,
  type: "TIP" | "BOOST"
) {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId, type }
  });

  return session;
}

export async function upsertSubscriptionFromStripe(data: {
  userId: string;
  stripeCustomerId?: string;
  stripeSubscriptionId: string;
  status: "ACTIVE" | "CANCELED" | "PAST_DUE" | "INCOMPLETE";
  currentPeriodEnd?: Date;
}) {
  return prisma.subscription.upsert({
    where: { stripeSubscriptionId: data.stripeSubscriptionId },
    update: {
      status: data.status,
      currentPeriodEnd: data.currentPeriodEnd,
      stripeCustomerId: data.stripeCustomerId
    },
    create: {
      userId: data.userId,
      stripeCustomerId: data.stripeCustomerId,
      stripeSubscriptionId: data.stripeSubscriptionId,
      status: data.status,
      currentPeriodEnd: data.currentPeriodEnd
    }
  });
}

export async function createPurchaseFromStripe(data: {
  userId: string;
  stripePaymentIntentId: string;
  type: "TIP" | "BOOST";
  amount: number;
  currency: string;
  status: string;
}) {
  return prisma.purchase.create({
