import { Response } from "express";
import { z } from "zod";
import { AuthRequest } from "../middleware/auth";
import { createConversation } from "../services/messaging.service";
import { prisma } from "../lib/prisma";

export async function createConversationController(req: AuthRequest, res: Response) {
  const schema = z.object({
    participantIds: z.array(z.string()).min(1)
  });

  const parsed = schema.parse(req.body);
  const userId = req.user!.userId;

  const uniqueIds = Array.from(new Set([userId, ...parsed.participantIds]));
  const conversation = await createConversation(uniqueIds);

  res.json(conversation);
}

export async function listConversations(req: AuthRequest, res: Response) {
  const userId = req.user!.userId;

  const conversations = await prisma.conversation.findMany({
    where: {
      participants: {
        some: { userId }
      }
    },
    include: {
      participants: {
        include: { user: { select: { id: true, username: true, email: true } } }
      },
      messages: {
        orderBy: { createdAt: "desc" },
        take: 1
      }
    },
    orderBy: { updatedAt: "desc" }
  });

  res.json(conversations);
}
