export async function sendMessageController(req: AuthRequest, res: Response) {
  const schema = z.object({
    conversationId: z.string(),
    content: z.string().min(1).max(5000)
  });

  const parsed = schema.parse(req.body);
  const senderId = req.user!.userId;

  const message = await sendMessage(senderId, parsed.conversationId, parsed.content);
  res.json(message);
}

export async function listMessages(req: AuthRequest, res: Response) {
  const conversationId = req.params.conversationId;
  const userId = req.user!.userId;

  const membership = await prisma.conversationUser.findFirst({
    where: { conversationId, userId }
  });

  if (!membership) {
    return res.status(403).json({ error: "Forbidden" });
  }

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    take: 100
  });

  res.json(messages);
}
