## backend/src/controllers/webhook.controller.ts

```ts
import { Request, Response } from "express";
import Stripe from "stripe";
import { env } from "../config/env";
import { stripe } from "../lib/stripe";
import {
  createPurchaseFromStripe,
  upsertSubscriptionFromStripe
} from "../services/billing.service";
import { createNotification } from "../services/notification.service";

function mapSubscriptionStatus(status: string): "ACTIVE" | "CANCELED" | "PAST_DUE" | "INCOMPLETE" {
  switch (status) {
    case "active":
      return "ACTIVE";
    case "canceled":
    case "unpaid":
      return "CANCELED";
    case "past_due":
      return "PAST_DUE";
    default:
      return "INCOMPLETE";
  }
}

export async function stripeWebhook(req: Request, res: Response) {
  const sig = req.headers["stripe-signature"] as string;

  const event = stripe.webhooks.constructEvent(
    req.body,
    sig,
    env.STRIPE_WEBHOOK_SECRET
  );

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as Stripe.Checkout.Session;
    const userId = session.metadata?.userId;

    if (userId && session.mode === "payment") {
      await createPurchaseFromStripe({
        userId,
        stripePaymentIntentId: String(session.payment_intent),
        type: (session.metadata?.type as "TIP" | "BOOST") || "TIP",
        amount: session.amount_total || 0,
        currency: session.currency || "usd",
        status: "completed"
      });

      await createNotification({
        userId,
        type: "PURCHASE",
        title: "Purchase successful",
        body: "Your purchase has been completed."
      });
    }
  }

  if (
    event.type === "customer.subscription.created" ||
    event.type === "customer.subscription.updated"
  ) {
    const subscription = event.data.object as Stripe.Subscription;
    const userId = subscription.metadata?.userId;

    if (userId) {
      await upsertSubscriptionFromStripe({
        userId,
        stripeCustomerId: String(subscription.customer),
        stripeSubscriptionId: subscription.id,
        status: mapSubscriptionStatus(subscription.status),
        currentPeriodEnd: new Date(subscription.items.data[0]?.current_period_end * 1000)
      });

      await createNotification({
        userId,
        type: "SUBSCRIPTION",
        title: "Subscription updated",
        body: `Subscription status: ${subscription.status}`
      });
    }
  }

  res.json({ received: true });
}
```

