import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { getToken } from "./auth";
import { LoginPage } from "./pages/LoginPage";
import { RegisterPage } from "./pages/RegisterPage";
import { ChatPage } from "./pages/ChatPage";
import { BillingPage } from "./pages/BillingPage";

export default function App() {
  const [page, setPage] = useState<"login" | "register" | "chat" | "billing">(
    getToken() ? "chat" : "login"
  );

  const socket = useMemo(() => {
    const token = getToken();
    if (!token) return null;
    return io("http://localhost:4000", {
      auth: { token }
    });
  }, [page]);

  useEffect(() => {
    return () => {
      socket?.disconnect();
    };
  }, [socket]);

  if (page === "login") {
    return <LoginPage onSuccess={() => setPage("chat")} onRegister={() => setPage("register")} />;
  }

  if (page === "register") {
    return <RegisterPage onSuccess={() => setPage("chat")} onLogin={() => setPage("login")} />;
  }

  if (page === "billing") {
    return <BillingPage onBack={() => setPage("chat")} />;
  }

  return <ChatPage socket={socket} onBilling={() => setPage("billing")} />;
}
