## `backend/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum NotificationType {
  MESSAGE
  PAYMENT
  SYSTEM
}

enum TransactionType {
  TIP
  SUBSCRIPTION
  CREDIT_PURCHASE
}

model User {
  id             String         @id @default(cuid())
  email          String         @unique
  username       String         @unique
  passwordHash   String
  createdAt      DateTime       @default(now())
  sentMessages   Message[]      @relation("SentMessages")
  receivedMessages Message[]    @relation("ReceivedMessages")
  notifications  Notification[]
  sentTransactions Transaction[] @relation("SenderTransactions")
  receivedTransactions Transaction[] @relation("ReceiverTransactions")
}

model Message {
  id          String   @id @default(cuid())
  content     String
  senderId    String
  receiverId  String
  createdAt   DateTime @default(now())
  readAt      DateTime?

  sender      User     @relation("SentMessages", fields: [senderId], references: [id])
  receiver    User     @relation("ReceivedMessages", fields: [receiverId], references: [id])
}

model Notification {
  id          String           @id @default(cuid())
  userId      String
  type        NotificationType
  title       String
  body        String
  read        Boolean          @default(false)
  createdAt   DateTime         @default(now())

  user        User             @relation(fields: [userId], references: [id])
}

model Transaction {
  id          String            @id @default(cuid())
  senderId    String?
  receiverId  String?
  amount      Int
  currency    String            @default("usd")
  type        TransactionType
  stripeRef   String?
  createdAt   DateTime          @default(now())

  sender      User?             @relation("SenderTransactions", fields: [senderId], references: [id])
  receiver    User?             @relation("ReceiverTransactions", fields: [receiverId], references: [id])
}
```

