## `backend/src/routes/payments.js`

```js
import express from "express";
import { PrismaClient } from "@prisma/client";
import { authMiddleware } from "../middleware/auth.js";
import { stripe } from "../services/paymentService.js";
import { createNotification } from "../services/notificationService.js";

const router = express.Router();
const prisma = new PrismaClient();

router.post("/create-tip-session", authMiddleware, async (req, res) => {
  try {
    const { receiverId, amount } = req.body;

    if (!receiverId || !amount || amount < 50) {
      return res.status(400).json({ error: "Invalid payment request" });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "User Tip"
            },
            unit_amount: amount
          },
          quantity: 1
        }
      ],
      success_url: "http://localhost:5173/wallet?success=1",
      cancel_url: "http://localhost:5173/wallet?canceled=1",
      metadata: {
        senderId: req.user.userId,
        receiverId,
        type: "TIP"
      }
    });

    res.json({ url: session.url });
  } catch {
    res.status(500).json({ error: "Failed to create payment session" });
  }
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  let event;

  try {
    const sig = req.headers["stripe-signature"];
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const { senderId, receiverId, type } = session.metadata;

    await prisma.transaction.create({
      data: {
        senderId,
        receiverId,
        amount: session.amount_total,
        currency: session.currency,
        type,
        stripeRef: session.payment_intent
      }
    });

    await createNotification(
      receiverId,
      "PAYMENT",
      "You received a tip",
      "A user sent you a payment"
    );
  }

  res.json({ received: true });
});

export default router;
```

