```jsx
import { useEffect, useState } from "react";
import { api } from "../api";
import { socket } from "../socket";
import { useAuth } from "../context/AuthContext";

export default function ChatWindow({ selectedUser }) {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!selectedUser) return;
    api(`/messages/${selectedUser.id}`).then(setMessages).catch(console.error);
  }, [selectedUser]);

  useEffect(() => {
    socket.on("message:new", (message) => {
      if (
        message.senderId === selectedUser?.id ||
        message.receiverId === selectedUser?.id
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off("message:new");
  }, [selectedUser]);

  async function sendMessage() {
    if (!content.trim() || !selectedUser) return;

    const message = await api("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content
      })
    });

    setMessages((prev) => [...prev, message]);
    setContent("");
  }

  if (!selectedUser) return <div style={{ padding: 20 }}>Select a user to chat</div>;

  return (
    <div style={{ flex: 1, padding: 12 }}>
      <h3>Chat with {selectedUser.username}</h3>
      <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 8 }}>
        {messages.map((m) => (
          <div
            key={m.id}
            style={{
              textAlign: m.senderId === user.id ? "right" : "left",
              margin: "8px 0"
            }}
          >
            <span
              style={{
                display: "inline-block",
                padding: 8,
                background: m.senderId === user.id ? "#d1ffd6" : "#f1f1f1",
                borderRadius: 8
              }}
            >
              {m.content}
            </span>
          </div>
        ))}
      </div>

      <div style={{ marginTop: 12, display: "flex", gap: 8 }}>
        <input
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message"
          style={{ flex: 1 }}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
