import { Server } from 'socket.io';

export let io: Server;

export function initSocket(server: any) {
  io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true
    }
  });

  io.on('connection', (socket) => {
    socket.on('join:user', (userId: string) => {
      socket.join(`user:${userId}`);
    });

    socket.on('join:conversation', (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });
  });

  return io;
}
```

### `backend/src/services/message.service.ts`

```ts
import { prisma } from '../lib/prisma';
import { io } from '../lib/socket';
import { createNotification } from './notification.service';

export async function createOrGetConversation(userA: string, userB: string) {
  const conversations = await prisma.conversation.findMany({
    where: {
      participants: {
        some: { userId: userA }
      }
    },
    include: {
      participants: true
    }
  });

  const existing = conversations.find((c) => {
    const ids = c.participants.map((p) => p.userId).sort();
    return ids.length === 2 && ids[0] === [userA, userB].sort()[0] && ids[1] === [userA, userB].sort()[1];
  });

  if (existing) return existing;

  return prisma.conversation.create({
    data: {
      participants: {
        create: [{ userId: userA }, { userId: userB }]
      }
    },
    include: {
      participants: true
    }
  });
}

export async function sendMessage(senderId: string, conversationId: string, content: string) {
  const message = await prisma.message.create({
    data: {
      senderId,
      conversationId,
      content
    },
    include: {
      sender: {
        select: {
          id: true,
          username: true
        }
      }
    }
  });

  io.to(`conversation:${conversationId}`).emit('message:new', message);

  const participants = await prisma.conversationParticipant.findMany({
    where: { conversationId }
  });

  for (const participant of participants) {
    if (participant.userId !== senderId) {
      await createNotification(
        participant.userId,
        'NEW_MESSAGE',
        `You received a new message`
      );
    }
  }

  return message;
}
```

