```ts
import Stripe from 'stripe';
import { prisma } from '../lib/prisma';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '');

export async function createCheckoutSession(userId: string) {
  const session = await stripe.checkout.sessions.create({
    mode: 'subscription',
    payment_method_types: ['card'],
    line_items: [
      {
        price: process.env.STRIPE_PRICE_ID!,
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/subscribe?success=true`,
    cancel_url: `${process.env.CLIENT_URL}/subscribe?canceled=true`,
    metadata: {
      userId
    }
  });

  return session;
}

export async function createTipPaymentIntent(userId: string, amount: number) {
  const paymentIntent = await stripe.paymentIntents.create({
    amount,
    currency: 'usd',
    metadata: {
      userId,
      type: 'TIP'
    }
  });

  return paymentIntent;
}

export async function handleCheckoutCompleted(session: Stripe.Checkout.Session) {
  const userId = session.metadata?.userId;
  if (!userId) return;

  await prisma.subscription.create({
    data: {
      userId,
      stripeCustomerId: session.customer?.toString(),
      stripeSubscriptionId: session.subscription?.toString(),
      status: 'active'
    }
  });
}

export async function handlePaymentSucceeded(paymentIntent: Stripe.PaymentIntent) {
  const userId = paymentIntent.metadata.userId;
  if (!userId) return;

  await prisma.purchase.create({
    data: {
      userId,
      stripePaymentId: paymentIntent.id,
      type: 'TIP',
      amount: paymentIntent.amount,
      currency: paymentIntent.currency
    }
  });
}
```

