## `frontend/components/ChatWindow.tsx`

```tsx
'use client';

import { useEffect, useState } from 'react';
import { apiFetch } from '../lib/api';
import { socket } from '../lib/socket';
import MessageInput from './MessageInput';
import { getUser } from '../lib/auth';

export default function ChatWindow({ conversation }: { conversation: any }) {
  const [messages, setMessages] = useState<any[]>([]);

  useEffect(() => {
    if (!conversation) return;

    apiFetch(`/messages/${conversation.id}`).then(setMessages);

    socket.connect();
    socket.emit('join:conversation', conversation.id);

    const onNewMessage = (message: any) => {
      if (message.conversationId === conversation.id) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on('message:new', onNewMessage);

    return () => {
      socket.off('message:new', onNewMessage);
    };
  }, [conversation]);

  async function send(content: string) {
    const user = getUser();
    const optimistic = {
      id: `temp-${Date.now()}`,
      content,
      sender: { id: user.id, username: user.username },
      conversationId: conversation.id
    };

    setMessages((prev) => [...prev, optimistic]);

    await apiFetch('/messages', {
      method: 'POST',
      body: JSON.stringify({
        conversationId: conversation.id,
        content
      })
    });
  }

  if (!conversation) {
    return <div style={{ padding: 24 }}>Select a conversation</div>;
  }

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: 12, borderBottom: '1px solid #ddd' }}>
        Chat
      </div>
      <div style={{ flex: 1, padding: 12, overflowY: 'auto' }}>
        {messages.map((m) => (
          <div key={m.id} style={{ marginBottom: 8 }}>
            <strong>{m.sender?.username || 'Unknown'}:</strong> {m.content}
          </div>
        ))}
      </div>
      <MessageInput onSend={send} />
    </div>
  );
}
