## `frontend/src/pages/ChatPage.jsx`

```js
import React, { useEffect, useState } from "react";
import API from "../api";
import { socket } from "../socket";
import ChatList from "../components/ChatList";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";
import NotificationBell from "../components/NotificationBell";

export default function ChatPage() {
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    API.get("/users").then((res) => {
      setUsers(res.data.filter((u) => u.id !== currentUser.id));
    });

    socket.connect();
    socket.emit("join", currentUser.id);

    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("new_notification", (notification) => {
      setNotifications((prev) => [...prev, notification]);
    });

    return () => {
      socket.off("new_message");
      socket.off("new_notification");
      socket.disconnect();
    };
  }, [selectedUser]);

  const loadMessages = async (user) => {
    setSelectedUser(user);
    const res = await API.get(`/messages/${user.id}`);
    setMessages(res.data);
  };

  const sendMessage = async (content) => {
    if (!selectedUser) return;
    const res = await API.post("/messages", {
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
  };

  return (
    <div style={{ padding: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h2>Chat</h2>
        <NotificationBell count={notifications.filter((n) => !n.read).length} />
      </div>
      <div style={{ display: "flex" }}>
        <ChatList users={users} selectedUser={selectedUser} onSelect={loadMessages} />
        <div style={{ flex: 1 }}>
          {selectedUser ? (
            <>
              <h3 style={{ paddingLeft: 10 }}>{selectedUser.username}</h3>
              <MessageList messages={messages} currentUserId={currentUser.id} />
              <MessageInput onSend={sendMessage} />
            </>
          ) : (
            <p>Select a user to start chatting</p>
          )}
        </div>
      </div>
    </div>
  );
}
```

