# 8. Message sending with monetization guard

## `server/src/routes/messages.ts`

```ts
import { Router } from 'express';
import { prisma } from '../lib/prisma';
import { authMiddleware, AuthedRequest } from '../middleware/auth';

const router = Router();
router.use(authMiddleware);

async function canSendMessage(userId: string) {
  const subscription = await prisma.subscription.findUnique({
    where: { userId },
  });

  if (subscription?.status === 'ACTIVE') return true;

  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);

  const sentToday = await prisma.message.count({
    where: {
      senderId: userId,
      createdAt: {
        gte: startOfDay,
      },
    },
  });

  return sentToday < 20;
}

router.get('/:conversationId', async (req: AuthedRequest, res) => {
  const { conversationId } = req.params;
  const userId = req.userId!;

  const participant = await prisma.conversationParticipant.findFirst({
    where: { conversationId, userId },
  });

  if (!participant) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: 'asc' },
  });

  res.json(messages);
});

router.post('/', async (req: AuthedRequest, res) => {
  const { conversationId, content } = req.body;
  const userId = req.userId!;

  if (!content?.trim()) {
    return res.status(400).json({ error: 'Message content required' });
  }

  const participant = await prisma.conversationParticipant.findFirst({
    where: { conversationId, userId },
    include: {
      conversation: {
        include: {
          participants: true,
        },
      },
    },
  });

  if (!participant) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const allowed = await canSendMessage(userId);
  if (!allowed) {
    return res.status(402).json({
      error: 'Free message limit reached. Upgrade to premium.',
      code: 'MESSAGE_LIMIT_REACHED',
    });
  }

  const message = await prisma.message.create({
    data: {
      conversationId,
      senderId: userId,
      content,
    },
  });

  await prisma.conversation.update({
    where: { id: conversationId },
    data: { updatedAt: new Date() },
  });

  const recipients = participant.conversation.participants.filter(
    (p) => p.userId !== userId
  );

  for (const recipient of recipients) {
    await prisma.notification.create({
      data: {
        userId: recipient.userId,
        type: 'MESSAGE',
        title: 'New message',
        body: content.slice(0, 120),
      },
    });
  }

  res.json(message);
});

router.post('/:messageId/read', async (req: AuthedRequest, res) => {
  const { messageId } = req.params;
  const userId = req.userId!;

  const message = await prisma.message.findUnique({
    where: { id: messageId },
    include: {
      conversation: {
        include: {
          participants: true,
        },
      },
    },
  });

  if (!message) {
    return res.status(404).json({ error: 'Not found' });
  }

  const isParticipant = message.conversation.participants.some(
    (p) => p.userId === userId
  );

  if (!isParticipant) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const updated = await prisma.message.update({
    where: { id: messageId },
    data: { readAt: new Date() },
  });

  res.json(updated);
});

export default router;
```

