# 10. Stripe subscription routes

## `server/src/routes/billing.ts`

```ts
import { Router } from 'express';
import { authMiddleware, AuthedRequest } from '../middleware/auth';
import { prisma } from '../lib/prisma';
import { stripe } from '../lib/stripe';
import express from 'express';

const router = Router();

router.post('/create-checkout-session', authMiddleware, async (req: AuthedRequest, res) => {
  const userId = req.userId!;

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { subscription: true },
  });

  if (!user) return res.status(404).json({ error: 'User not found' });

  let customerId = user.subscription?.stripeCustomerId;

  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email,
      metadata: { userId },
    });
    customerId = customer.id;

    await prisma.subscription.update({
      where: { userId },
      data: { stripeCustomerId: customerId },
    });
  }

  const session = await stripe.checkout.sessions.create({
    mode: 'subscription',
    customer: customerId,
    line_items: [
      {
        price: process.env.STRIPE_PRICE_ID!,
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: { userId },
  });

  res.json({ url: session.url });
});

router.post(
  '/webhook',
  express.raw({ type: 'application/json' }),
  async (req, res) => {
    const sig = req.headers['stripe-signature'] as string;

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET!
      );
    } catch (err: any) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object as any;
      const userId = session.metadata.userId;

      await prisma.subscription.update({
        where: { userId },
        data: {
          status: 'ACTIVE',
        },
      });

      await prisma.notification.create({
        data: {
          userId,
          type: 'SUBSCRIPTION',
          title: 'Premium activated',
          body: 'Your premium subscription is now active.',
        },
      });
    }

    if (event.type === 'customer.subscription.deleted') {
      const subscription = event.data.object as any;

      await prisma.subscription.updateMany({
        where: { stripeSubscriptionId: subscription.id },
        data: {
          status: 'CANCELED',
        },
      });
    }

    res.json({ received: true });
  }
);

export default router;
```

