# 11. Socket.IO real-time notifications

## `server/src/sockets/index.ts`

```ts
import { Server, Socket } from 'socket.io';
import { verifyToken } from '../lib/jwt';
import { prisma } from '../lib/prisma';

interface AuthedSocket extends Socket {
  userId?: string;
}

export function registerSocketHandlers(io: Server) {
  io.use((socket: AuthedSocket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error('Unauthorized'));

    try {
      const payload = verifyToken(token);
      socket.userId = payload.userId;
      next();
    } catch {
      next(new Error('Unauthorized'));
    }
  });

  io.on('connection', (socket: AuthedSocket) => {
    const userId = socket.userId!;
    socket.join(`user:${userId}`);

    socket.on('join_conversation', async (conversationId: string) => {
      const participant = await prisma.conversationParticipant.findFirst({
        where: { conversationId, userId },
      });

      if (participant) {
        socket.join(`conversation:${conversationId}`);
      }
    });

    socket.on('send_message', async ({ conversationId, content }) => {
      const participant = await prisma.conversationParticipant.findFirst({
        where: { conversationId, userId },
        include: {
          conversation: {
            include: { participants: true },
          },
        },
      });

      if (!participant || !content?.trim()) return;

      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId: userId,
          content,
        },
      });

      await prisma.conversation.update({
        where: { id: conversationId },
        data: { updatedAt: new Date() },
      });

      io.to(`conversation:${conversationId}`).emit('new_message', message);

      const recipients = participant.conversation.participants.filter(
        (p) => p.userId !== userId
      );

      for (const recipient of recipients) {
        const notification = await prisma.notification.create({
          data: {
            userId: recipient.userId,
            type: 'MESSAGE',
            title: 'New message',
            body: content.slice(0, 120),
          },
        });

        io.to(`user:${recipient.userId}`).emit('new_notification', notification);
      }
    });
  });
}
```

