## 2.7 Messaging controller

### backend/src/controllers/messageController.ts

```ts
import { Response } from "express";
import { z } from "zod";
import { prisma } from "../config/prisma";
import { AuthRequest } from "../middleware/auth";

export const createConversation = async (req: AuthRequest, res: Response) => {
  try {
    const schema = z.object({
      participantId: z.string()
    });

    const { participantId } = schema.parse(req.body);
    const userId = req.user!.userId;

    if (participantId === userId) {
      return res.status(400).json({ message: "Cannot create conversation with yourself" });
    }

    const conversation = await prisma.conversation.create({
      data: {
        members: {
          create: [
            { userId },
            { userId: participantId }
          ]
        }
      },
      include: {
        members: true
      }
    });

    return res.status(201).json(conversation);
  } catch (error: any) {
    return res.status(400).json({ message: error.message || "Failed to create conversation" });
  }
};

export const getConversations = async (req: AuthRequest, res: Response) => {
  const userId = req.user!.userId;

  const conversations = await prisma.conversation.findMany({
    where: {
      members: {
        some: { userId }
      }
    },
    include: {
      members: {
        include: {
          user: {
            select: { id: true, username: true, email: true }
          }
        }
      },
      messages: {
        orderBy: { createdAt: "desc" },
        take: 1
      }
    },
    orderBy: { updatedAt: "desc" }
  });

  return res.json(conversations);
};

export const getMessages = async (req: AuthRequest, res: Response) => {
  const userId = req.user!.userId;
  const { conversationId } = req.params;

  const member = await prisma.conversationMember.findFirst({
    where: { conversationId, userId }
  });

  if (!member) {
    return res.status(403).json({ message: "Forbidden" });
  }

  const messages = await prisma.message.findMany({
    where: { conversationId },
    include: {
      sender: {
        select: { id: true, username: true }
      }
    },
    orderBy: { createdAt: "asc" }
  });

  return res.json(messages);
};

export const sendMessage = async (req: AuthRequest, res: Response) => {
  try {
    const schema = z.object({
      conversationId: z.string(),
      content: z.string().min(1).max(2000)
    });

    const { conversationId, content } = schema.parse(req.body);
    const senderId = req.user!.userId;

    const member = await prisma.conversationMember.findFirst({
      where: { conversationId, userId: senderId },
      include: {
        conversation: {
          include: {
            members: true
          }
        }
      }
    });

    if (!member) {
      return res.status(403).json({ message: "Forbidden" });
    }

    const message = await prisma.message.create({
      data: {
        conversationId,
        senderId,
        content
      },
      include: {
        sender: {
          select: { id: true, username: true }
        }
      }
    });

    await prisma.conversation.update({
      where: { id: conversationId },
      data: { updatedAt: new Date() }
    });

    const recipients = member.conversation.members.filter(m => m.userId !== senderId);

    for (const recipient of recipients) {
      await prisma.notification.create({
        data: {
          userId: recipient.userId,
          type: "MESSAGE",
          content: `New message: ${content.slice(0, 80)}`
        }
      });
    }

    return res.status(201).json({
      message,
      recipientIds: recipients.map(r => r.userId)
    });
  } catch (error: any) {
    return res.status(400).json({ message: error.message || "Failed to send message" });
  }
};
```

