## 2.9 Stripe monetization controller

### backend/src/controllers/billingController.ts

```ts
import { Request, Response } from "express";
import Stripe from "stripe";
import { prisma } from "../config/prisma";
import { AuthRequest } from "../middleware/auth";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export const createCheckoutSession = async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.user!.userId;
    const { mode, credits } = req.body;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: { subscription: true }
    });

    if (!user) {
      return res.status(404).json({ message: "User not found" });
    }

    let customerId = user.subscription?.stripeCustomerId;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        metadata: { userId: user.id }
      });

      customerId = customer.id;

      await prisma.subscription.upsert({
        where: { userId: user.id },
        update: { stripeCustomerId: customerId },
        create: {
          userId: user.id,
          stripeCustomerId: customerId,
          status: "FREE"
        }
      });
    }

    let session;

    if (mode === "subscription") {
      session = await stripe.checkout.sessions.create({
        mode: "subscription",
        customer: customerId,
        line_items: [
          {
            price: process.env.STRIPE_PRICE_PREMIUM_MONTHLY!,
            quantity: 1
          }
        ],
        success_url: `${process.env.CLIENT_URL}/billing/success`,
        cancel_url: `${process.env.CLIENT_URL}/billing/cancel`
      });
    } else if (mode === "credits") {
      const quantity = Number(credits || 10);
      const unitAmount = 100;

      session = await stripe.checkout.sessions.create({
        mode: "payment",
        customer: customerId,
        line_items: [
          {
            price_data: {
              currency: "usd",
              product_data: {
                name: "Message Credits"
              },
              unit_amount: unitAmount
            },
            quantity
          }
        ],
        success_url: `${process.env.CLIENT_URL}/billing/success`,
        cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
        metadata: {
          type: "credits",
          credits: String(quantity),
          userId
        }
      });
    } else {
      return res.status(400).json({ message: "Invalid billing mode" });
    }

    return res.json({ url: session.url });
  } catch (error: any) {
    return res.status(400).json({ message: error.message || "Billing failed" });
  }
};

export const stripeWebhook = async (req: Request, res: Response) => {
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);
  const sig = req.headers["stripe-signature"] as string;

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as Stripe.Checkout.Session;

    if (session.mode === "subscription") {
      const customerId = session.customer as string;
      const subscriptionId = session.subscription as string;

      const subscription = await stripe.subscriptions.retrieve(subscriptionId);

      await prisma.subscription.updateMany({
        where: { stripeCustomerId: customerId },
        data: {
          stripeSubscriptionId: subscriptionId,
          status: "ACTIVE",
          currentPeriodEnd: new Date(subscription.current_period_end * 1000)
        }
      });
    }

    if (session.mode === "payment" && session.metadata?.type === "credits") {
      const userId = session.metadata.userId;
      const credits = Number(session.metadata.credits || 0);

      await prisma.wallet.update({
        where: { userId },
        data: {
          credits: {
            increment: credits
          }
        }
      });

      await prisma.purchase.create({
        data: {
          userId,
          stripePaymentId: session.payment_intent as string,
          type: "credits",
          amount: session.amount_total || 0,
          currency: session.currency || "usd",
          status: "completed"
        }
      });

      await prisma.notification.create({
        data: {
          userId,
          type: "PAYMENT",
          content: `Your purchase of ${credits} credits was successful.`
        }
      });
    }
  }

  return res.json({ received: true });
};
```

