## 2.13 Server entrypoint with real-time message emission

### backend/src/index.ts

```ts
import http from "http";
import { Server } from "socket.io";
import app from "./app";
import { setupSocket, emitToUser } from "./sockets/socket";
import { prisma } from "./config/prisma";

const PORT = process.env.PORT || 4000;

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST", "PATCH"]
  }
});

setupSocket(io);

// Monkey patch pattern for MVP only.
// Better approach: use service layer / event bus.
const originalCreate = prisma.message.create.bind(prisma.message);
prisma.message.create = (async (args: any) => {
  const result = await originalCreate(args);

  const fullMessage = await prisma.message.findUnique({
    where: { id: result.id },
    include: {
      sender: {
        select: { id: true, username: true }
      },
      conversation: {
        include: {
          members: true
        }
      }
    }
  });

  if (fullMessage) {
    for (const member of fullMessage.conversation.members) {
      emitToUser(io, member.userId, "message:new", fullMessage);
    }
  }

  return result;
}) as any;

const originalNotificationCreate = prisma.notification.create.bind(prisma.notification);
prisma.notification.create = (async (args: any) => {
  const result = await originalNotificationCreate(args);
  emitToUser(io, result.userId, "notification:new", result);
  return result;
}) as any;

server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

