import { useEffect, useState } from "react";
import { apiFetch } from "./api/client";
import { useSocket } from "./hooks/useSocket";

function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [email, setEmail] = useState("");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [messageInput, setMessageInput] = useState("");
  const [participantId, setParticipantId] = useState("");

  const loadConversations = async () => {
    const data = await apiFetch("/messages/conversations");
    setConversations(data);
  };

  const loadNotifications = async () => {
    const data = await apiFetch("/notifications");
    setNotifications(data);
  };

  const loadMessages = async (conversationId) => {
    const data = await apiFetch(`/messages/conversations/${conversationId}/messages`);
    setMessages(data);
  };

  useSocket(token, {
    onMessage: (msg) => {
      if (msg.conversationId === selectedConversation?.id) {
        setMessages((prev) => {
          const exists = prev.some((m) => m.id === msg.id);
          return exists ? prev : [...prev, msg];
        });
      }
      loadConversations();
    },
    onNotification: (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    }
  });

  useEffect(() => {
    if (token) {
      loadConversations();
      loadNotifications();
    }
  }, [token]);

  const register = async () => {
    const data = await apiFetch("/auth/register", {
      method: "POST",
      body: JSON.stringify({ email, username, password })
    });
    localStorage.setItem("token", data.token);
    setToken(data.token);
  };

  const login = async () => {
    const data = await apiFetch("/auth/login", {
      method: "POST",
      body: JSON.stringify({ email, password })
    });
    localStorage.setItem("token", data.token);
    setToken(data.token);
  };

  const createConversation = async () => {
    const data = await apiFetch("/messages/conversations", {
      method: "POST",
      body: JSON.stringify({ participantId })
    });
    setParticipantId("");
    await loadConversations();
    setSelectedConversation(data);
    await loadMessages(data.id);
  };

  const sendMessage = async () => {
    if (!selectedConversation || !messageInput.trim()) return;

    await apiFetch("/messages/messages", {
      method: "POST",
      body: JSON.stringify({
        conversationId: selectedConversation.id,
        content: messageInput
      })
    });

    setMessageInput("");
  };

  const buyCredits = async () => {
    const data = await apiFetch("/billing/checkout", {
      method: "POST",
      body: JSON.stringify({ mode: "credits", credits: 10 })
    });
    window.location.href = data.url;
  };

  const subscribePremium = async () => {
    const data = await apiFetch("/billing/checkout", {
      method: "POST",
      body: JSON.stringify({ mode: "subscription" })
    });
    window.location.href = data.url;
  };

  if (!token) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Social Messaging App</h1>
        <input placeholder="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <br />
        <input placeholder="username (register only)" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <br />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", padding: 16, gap: 16 }}>
      <div style={{ width: 300, borderRight: "1px solid #ccc", paddingRight: 16 }}>
        <h2>Conversations</h2>
        <input
          placeholder="Participant user ID"
          value={participantId}
          onChange={(e) => setParticipantId(e.target.value)}
        />
        <button onClick={createConversation}>Start Chat</button>

        <ul>
          {conversations.map((conv) => (
            <li key={conv.id}>
              <button
                onClick={async () => {
                  setSelectedConversation(conv);
                  await loadMessages(conv.id);
                }}
              >
                {conv.members.map((m) => m.user.username).join(", ")}
              </button>
            </li>
          ))}
        </ul>

        <h2>Notifications</h2>
        <ul>
          {notifications.map((n) => (
            <li key={n.id}>
              {n.content} {n.read ? "" : "(new)"}
            </li>
          ))}
        </ul>

        <h2>Monetization</h2>
        <button onClick={buyCredits}>Buy 10 Credits</button>
        <button onClick={subscribePremium}>Go Premium</button>
      </div>

      <div style={{ flex: 1 }}>
        <h2>Messages</h2>
        {selectedConversation ? (
          <>
            <div style={{ height: "80vh", overflowY: "auto", border: "1px solid #ccc", padding: 12 }}>
