## `backend/routes/messages.js`

```js
const express = require("express");
const Message = require("../models/Message");
const User = require("../models/User");
const auth = require("../middleware/auth");

const router = express.Router();

router.get("/users", auth, async (req, res) => {
  try {
    const users = await User.find({ _id: { $ne: req.user.id } }).select("_id username premium");
    res.json(users);
  } catch (err) {
    res.status(500).json({ message: "Failed to fetch users" });
  }
});

router.get("/:userId", auth, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user.id, receiver: req.params.userId },
        { sender: req.params.userId, receiver: req.user.id }
      ]
    }).sort({ createdAt: 1 });

    await Message.updateMany(
      { sender: req.params.userId, receiver: req.user.id, read: false },
      { $set: { read: true } }
    );

    res.json(messages);
  } catch (err) {
    res.status(500).json({ message: "Failed to fetch messages" });
  }
});

router.post("/", auth, async (req, res) => {
  try {
    const { receiver, content } = req.body;

    const message = await Message.create({
      sender: req.user.id,
      receiver,
      content
    });

    const populatedMessage = await message.populate("sender receiver", "username");

    const io = req.app.get("io");
    io.to(receiver).emit("new_message", populatedMessage);
    io.to(receiver).emit("notification", {
      type: "message",
      from: req.user.id,
      content: "You received a new message"
    });

    res.json(populatedMessage);
  } catch (err) {
    res.status(500).json({ message: "Failed to send message" });
  }
});

module.exports = router;
```

