## `frontend/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import ChatWindow from "../components/ChatWindow";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ user, setUser }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    socket.connect();
    socket.emit("join", user.id);

    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.sender._id === selectedUser._id || message.sender === selectedUser._id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    socket.on("notification", (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    loadUsers();

    return () => {
      socket.off("new_message");
      socket.off("notification");
      socket.disconnect();
    };
  }, [selectedUser]);

  const loadUsers = async () => {
    const res = await api.get("/messages/users");
    setUsers(res.data);
  };

  const loadMessages = async (otherUser) => {
    setSelectedUser(otherUser);
    const res = await api.get(`/messages/${otherUser._id}`);
    setMessages(res.data);
  };

  const sendMessage = async (content) => {
    if (!selectedUser) return;
    const res = await api.post("/messages", {
      receiver: selectedUser._id,
      content
    });
    setMessages(prev => [...prev, res.data]);
  };

  const buyCoins = async () => {
    const res = await api.post("/monetization/create-payment-intent", {
      amount: 500,
      type: "coins"
    });

    await api.post("/monetization/confirm", {
      purchaseId: res.data.purchaseId
    });

    const updatedUser = { ...user, coins: user.coins + 100 };
    localStorage.setItem("user", JSON.stringify(updatedUser));
    setUser(updatedUser);
  };

  const logout = () => {
    localStorage.clear();
    setUser(null);
  };

  return (
    <div style={{ display: "flex", padding: 20 }}>
      <div style={{ width: 250 }}>
        <h3>{user.username}</h3>
        <p>Coins: {user.coins}</p>
        <p>Premium: {user.premium ? "Yes" : "No"}</p>
        <button onClick={buyCoins}>Buy Coins</button>
        <button onClick={logout}>Logout</button>
        <NotificationBell notifications={notifications} />
        <hr />
        <h4>Users</h4>
        {users.map(u => (
          <div
            key={u._id}
            onClick={() => loadMessages(u)}
            style={{ cursor: "pointer", marginBottom: 8 }}
          >
            {u.username} {u.premium ? "⭐" : ""}
          </div>
        ))}
      </div>

      <div style={{ flex: 1, marginLeft: 20 }}>
        {selectedUser ? (
          <ChatWindow
            selectedUser={selectedUser}
            messages={messages}
            onSend={sendMessage}
            currentUser={user}
          />
        ) : (
          <p>Select a user to start chatting</p>
        )}
      </div>
    </div>
  );
}
```

