## 3.10 Messaging routes

`server/src/routes/messages.ts`

```ts
import { Router } from "express";
import { prisma } from "../lib/prisma";
import { requireAuth, AuthRequest } from "../middleware/auth";
import { NotificationType } from "@prisma/client";

export function createMessageRouter(io: any, onlineUsers: Map<string, string>) {
  const router = Router();

  router.post("/send", requireAuth, async (req: AuthRequest, res) => {
    const senderId = req.user!.userId;
    const { receiverId, content } = req.body;

    if (!receiverId || !content) {
      return res.status(400).json({ error: "receiverId and content required" });
    }

    let conversation = await prisma.conversation.findFirst({
      where: {
        participants: {
          every: {
            userId: { in: [senderId, receiverId] }
          }
        }
      },
      include: { participants: true }
    });

    if (!conversation || conversation.participants.length !== 2) {
      conversation = await prisma.conversation.create({
        data: {
          participants: {
            create: [{ userId: senderId }, { userId: receiverId }]
          }
        },
        include: { participants: true }
      });
    }

    const message = await prisma.message.create({
      data: {
        conversationId: conversation.id,
        senderId,
        receiverId,
        content
      }
    });

    const notification = await prisma.notification.create({
      data: {
        userId: receiverId,
        type: NotificationType.MESSAGE,
        title: "New message",
        body: content.slice(0, 100),
        metadata: { senderId, conversationId: conversation.id, messageId: message.id }
      }
    });

    const receiverSocketId = onlineUsers.get(receiverId);

    if (receiverSocketId) {
      io.to(receiverSocketId).emit("message:new", message);
      io.to(receiverSocketId).emit("notification:new", notification);
    }

    res.json({ message, conversationId: conversation.id });
  });

  router.get("/conversations", requireAuth, async (req: AuthRequest, res) => {
    const userId = req.user!.userId;

    const conversations = await prisma.conversation.findMany({
      where: {
        participants: {
          some: { userId }
        }
      },
      include: {
        participants: {
          include: {
            user: {
              select: { id: true, username: true, avatarUrl: true }
            }
          }
        },
        messages: {
          orderBy: { createdAt: "desc" },
          take: 1
        }
      },
      orderBy: { updatedAt: "desc" }
    });

    res.json(conversations);
  });

  router.get("/conversations/:id", requireAuth, async (req: AuthRequest, res) => {
    const conversationId = req.params.id;

    const messages = await prisma.message.findMany({
      where: { conversationId },
      orderBy: { createdAt: "asc" }
    });

    res.json(messages);
  });

  return router;
}
```

