## 4.2 Prisma schema

`server/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum NotificationType {
  MESSAGE
  FOLLOW
  PAYMENT
  SUBSCRIPTION
  SYSTEM
}

enum SubscriptionStatus {
  INACTIVE
  ACTIVE
  PAST_DUE
  CANCELED
}

model User {
  id               String           @id @default(cuid())
  email            String           @unique
  username         String           @unique
  passwordHash     String
  displayName      String?
  bio              String?
  avatarUrl        String?
  createdAt        DateTime         @default(now())
  updatedAt        DateTime         @updatedAt

  sentMessages     Message[]        @relation("SentMessages")
  receivedMessages Message[]        @relation("ReceivedMessages")

  followers        Follow[]         @relation("FollowingRelation")
  following        Follow[]         @relation("FollowerRelation")

  notifications    Notification[]
  subscriptions    Subscription[]
  sentTips         Tip[]            @relation("SentTips")
  receivedTips     Tip[]            @relation("ReceivedTips")
}

model Follow {
  id           String   @id @default(cuid())
  followerId   String
  followingId  String
  createdAt    DateTime @default(now())

  follower     User     @relation("FollowerRelation", fields: [followerId], references: [id])
  following    User     @relation("FollowingRelation", fields: [followingId], references: [id])

  @@unique([followerId, followingId])
}

model Message {
  id           String   @id @default(cuid())
  senderId     String
  receiverId   String
  content      String
  createdAt    DateTime @default(now())
  readAt       DateTime?

  sender       User     @relation("SentMessages", fields: [senderId], references: [id])
  receiver     User     @relation("ReceivedMessages", fields: [receiverId], references: [id])
}

model Notification {
  id           String           @id @default(cuid())
  userId       String
  type         NotificationType
  title        String
  body         String
  isRead       Boolean          @default(false)
  metadata     Json?
  createdAt    DateTime         @default(now())

  user         User             @relation(fields: [userId], references: [id])
}

model Subscription {
  id                    String              @id @default(cuid())
  userId                 String
  stripeCustomerId       String?             @unique
  stripeSubscriptionId   String?             @unique
  status                 SubscriptionStatus  @default(INACTIVE)
  plan                   String?
  currentPeriodEnd       DateTime?

  user                   User                @relation(fields: [userId], references: [id])
}

model Tip {
  id                    String   @id @default(cuid())
  senderId              String
  receiverId            String
  amount                Int      // cents
  currency              String   @default("usd")
  stripePaymentIntentId String?  @unique
  createdAt             DateTime @default(now())

  sender                User     @relation("SentTips", fields: [senderId], references: [id])
  receiver              User     @relation("ReceivedTips", fields: [receiverId], references: [id])
}
