## 4.14 Stripe webhook

`server/src/routes/webhooks.ts`

```ts
import { Router } from "express";
import Stripe from "stripe";
import { prisma } from "../lib/prisma";
import { createNotification } from "../services/notificationService";
import { NotificationType, SubscriptionStatus } from "@prisma/client";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: "2024-06-20",
});

router.post("/stripe", async (req, res) => {
  const sig = req.headers["stripe-signature"] as string;

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  switch (event.type) {
    case "checkout.session.completed": {
      const session = event.data.object as Stripe.Checkout.Session;

      if (session.mode === "payment") {
        const senderId = session.metadata?.senderId!;
        const receiverId = session.metadata?.receiverId!;
        const amount = Number(session.metadata?.amount || 0);

        await prisma.tip.create({
          data: {
            senderId,
            receiverId,
            amount,
            stripePaymentIntentId: session.payment_intent as string,
          },
        });

        await createNotification({
          userId: receiverId,
          type: NotificationType.PAYMENT,
          title: "You received a tip",
          body: `You received $${(amount / 100).toFixed(2)}`,
          metadata: { senderId, amount },
        });
      }

      break;
    }

    case "customer.subscription.updated":
    case "customer.subscription.created": {
      const sub = event.data.object as Stripe.Subscription;
      const customerId = sub.customer as string;

      await prisma.subscription.updateMany({
        where: { stripeCustomerId: customerId },
        data: {
          stripeSubscriptionId: sub.id,
          status: SubscriptionStatus.ACTIVE,
          currentPeriodEnd: new Date((sub as any).current_period_end * 1000),
          plan: sub.items.data[0]?.price.id,
        },
      });

      break;
    }

    case "customer.subscription.deleted": {
      const sub = event.data.object as Stripe.Subscription;

      await prisma.subscription.updateMany({
        where: { stripeSubscriptionId: sub.id },
        data: {
          status: SubscriptionStatus.CANCELED,
        },
      });

      break;
    }
  }

  res.json({ received: true });
});

export default router;
```

