type Message = {
  id: string;
  senderId: string;
  receiverId: string;
  content: string;
  createdAt: string;
};

type Notification = {
  id: string;
  title: string;
  body: string;
  isRead: boolean;
};

export default function AppPage() {
  const [me, setMe] = useState<any>(null);
  const [targetUserId, setTargetUserId] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    apiFetch("/users/me").then(setMe).catch(() => {
      window.location.href = "/";
    });

    apiFetch("/notifications").then(setNotifications);

    const socket = getSocket();

    socket.on("message:new", (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("notification:new", (notification: Notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
    };
  }, []);

  async function loadMessages() {
    const data = await apiFetch(`/messages/${targetUserId}`);
    setMessages(data);
  }

  async function sendMessage() {
    const message = await apiFetch("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: targetUserId,
        content,
      }),
    });

    setMessages((prev) => [...prev, message]);
    setContent("");
  }

  async function subscribe() {
    const data = await apiFetch("/billing/create-checkout-session", {
      method: "POST",
    });
    window.location.href = data.url;
  }

  async function tipUser() {
    const data = await apiFetch("/billing/create-tip-session", {
      method: "POST",
      body: JSON.stringify({
        receiverId: targetUserId,
        amount: 500,
      }),
    });
    window.location.href = data.url;
  }

  return (
    <main style={{ padding: 24 }}>
      <h1>Welcome {me?.username}</h1>

      <section style={{ marginTop: 24 }}>
        <h2>Notifications</h2>
        {notifications.map((n) => (
          <div key={n.id} style={{ border: "1px solid #ccc", marginBottom: 8, padding: 8 }}>
            <strong>{n.title}</strong>
            <div>{n.body}</div>
          </div>
        ))}
      </section>

      <section style={{ marginTop: 24 }}>
        <h2>Messaging</h2>
        <input
          placeholder="Target user ID"
          value={targetUserId}
          onChange={(e) => setTargetUserId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Chat</button>

        <div style={{ marginTop: 16, border: "1px solid #ccc", padding: 12, minHeight: 200 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.senderId === me?.id ? "Me" : "Them"}:</strong> {m.content}
            </div>
          ))}
        </div>

        <div style={{ marginTop: 16 }}>
          <input
            placeholder="Type message"
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </section>

      <section style={{ marginTop: 24 }}>
        <h2>Monetization</h2>
        <button onClick={subscribe}>Subscribe to Premium</button>
        <button onClick={tipUser} style={{ marginLeft: 12 }}>
          Tip Current User ($5)
        </button>
      </section>
    </main>
  );
}
```

