# 4. Database Schema with Prisma

Here’s a solid MVP schema.

## `server/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum SubscriptionStatus {
  FREE
  ACTIVE
  PAST_DUE
  CANCELED
}

enum NotificationType {
  MESSAGE
  MESSAGE_REQUEST
  PAYMENT
  SYSTEM
}

model User {
  id                String           @id @default(cuid())
  email             String           @unique
  username          String           @unique
  passwordHash      String
  displayName       String?
  avatarUrl         String?
  bio               String?
  createdAt         DateTime         @default(now())
  updatedAt         DateTime         @updatedAt

  sentMessages      Message[]        @relation("SentMessages")
  conversationUsers ConversationUser[]
  notifications     Notification[]
  subscriptions     Subscription[]
  creditTransactions CreditTransaction[]
  sentMessageRequests MessageRequest[] @relation("Requester")
  receivedMessageRequests MessageRequest[] @relation("Recipient")
}

model Conversation {
  id                String             @id @default(cuid())
  createdAt         DateTime           @default(now())
  updatedAt         DateTime           @updatedAt
  lastMessageAt     DateTime?

  participants      ConversationUser[]
  messages          Message[]
}

model ConversationUser {
  id                String        @id @default(cuid())
  userId            String
  conversationId    String
  joinedAt          DateTime      @default(now())
  lastReadAt        DateTime?

  user              User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  conversation      Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)

  @@unique([userId, conversationId])
}

model Message {
  id                String        @id @default(cuid())
  conversationId    String
  senderId          String
  content           String
  createdAt         DateTime      @default(now())
  readAt            DateTime?

  conversation      Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender            User          @relation("SentMessages", fields: [senderId], references: [id], onDelete: Cascade)
}

model Notification {
  id                String            @id @default(cuid())
  userId            String
  type              NotificationType
  title             String
  body              String
  data              Json?
  isRead            Boolean           @default(false)
  createdAt         DateTime          @default(now())

  user              User              @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model Subscription {
  id                String              @id @default(cuid())
  userId            String
  stripeCustomerId  String?
  stripeSubId       String?             @unique
  stripePriceId     String?
  status            SubscriptionStatus  @default(FREE)
  currentPeriodEnd  DateTime?

  user              User                @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model CreditTransaction {
  id                String      @id @default(cuid())
  userId            String
  amount            Int         // positive = add credits, negative = spend
  reason            String
  metadata          Json?
  createdAt         DateTime    @default(now())

  user              User        @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model MessageRequest {
  id                String      @id @default(cuid())
  requesterId       String
  recipientId       String
  initialMessage    String
  creditsCharged    Int
  accepted          Boolean?
  createdAt         DateTime    @default(now())

  requester         User        @relation("Requester", fields: [requesterId], references: [id], onDelete: Cascade)
  recipient         User        @relation("Recipient", fields: [recipientId], references: [id], onDelete: Cascade)
}
