# 8. Messaging Routes

## `server/src/routes/conversations.ts`

```ts
import { Router } from "express";
import { prisma } from "../lib/prisma";
import { authMiddleware, AuthedRequest } from "../middleware/auth";

const router = Router();

router.post("/", authMiddleware, async (req: AuthedRequest, res) => {
  const { participantId } = req.body;
  const userId = req.user!.userId;

  if (!participantId || participantId === userId) {
    return res.status(400).json({ error: "Invalid participant" });
  }

  const existing = await prisma.conversation.findFirst({
    where: {
      participants: {
        every: {
          userId: { in: [userId, participantId] }
        }
      }
    },
    include: {
      participants: true
    }
  });

  if (existing && existing.participants.length === 2) {
    return res.json(existing);
  }

  const conversation = await prisma.conversation.create({
    data: {
      participants: {
        create: [{ userId }, { userId: participantId }]
      }
    },
    include: {
      participants: true
    }
  });

  return res.json(conversation);
});

router.get("/", authMiddleware, async (req: AuthedRequest, res) => {
  const userId = req.user!.userId;

  const conversations = await prisma.conversation.findMany({
    where: {
      participants: {
        some: { userId }
      }
    },
    include: {
      participants: {
        include: {
          user: {
            select: {
              id: true,
              username: true,
              displayName: true,
              avatarUrl: true
            }
          }
        }
      },
      messages: {
        orderBy: { createdAt: "desc" },
        take: 1
      }
    },
    orderBy: { lastMessageAt: "desc" }
  });

  res.json(conversations);
});

router.get("/:id/messages", authMiddleware, async (req: AuthedRequest, res) => {
  const userId = req.user!.userId;
  const conversationId = req.params.id;

  const membership = await prisma.conversationUser.findUnique({
    where: {
      userId_conversationId: {
        userId,
        conversationId
      }
    }
  });

  if (!membership) {
    return res.status(403).json({ error: "Forbidden" });
  }

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    take: 100
  });

  res.json(messages);
});

export default router;
```

