# 10. Monetization Routes

## `server/src/routes/payments.ts`

```ts
import { Router } from "express";
import Stripe from "stripe";
import { authMiddleware, AuthedRequest } from "../middleware/auth";
import { prisma } from "../lib/prisma";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "");

router.post("/create-checkout-session", authMiddleware, async (req: AuthedRequest, res) => {
  const { priceId, mode } = req.body;
  const userId = req.user!.userId;

  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) return res.status(404).json({ error: "User not found" });

  const session = await stripe.checkout.sessions.create({
    mode, // "subscription" or "payment"
    payment_method_types: ["card"],
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: {
      userId
    }
  });

  res.json({ url: session.url });
});

router.post("/webhook", async (req, res) => {
  // In production use raw body + signature verification
  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata?.userId;

    if (userId) {
      if (session.mode === "subscription") {
        await prisma.subscription.upsert({
          where: { userId },
          update: {
            stripeCustomerId: session.customer,
            status: "ACTIVE"
          },
          create: {
            userId,
            stripeCustomerId: session.customer,
            status: "ACTIVE"
          }
        });
      }

      if (session.mode === "payment") {
        await prisma.creditTransaction.create({
          data: {
            userId,
            amount: 100,
            reason: "credit_purchase",
            metadata: { stripeSessionId: session.id }
          }
        });

        await prisma.notification.create({
          data: {
            userId,
            type: "PAYMENT",
            title: "Credits added",
            body: "100 credits were added to your account."
          }
        });
      }
    }
  }

  res.json({ received: true });
});

