# 11. Message Request / Paid Messaging

This is where monetization becomes native to the social product.

## `server/src/routes/messageRequests.ts`

```ts
import { Router } from "express";
import { prisma } from "../lib/prisma";
import { authMiddleware, AuthedRequest } from "../middleware/auth";

const router = Router();
const MESSAGE_REQUEST_COST = 10;

async function getCredits(userId: string) {
  const agg = await prisma.creditTransaction.aggregate({
    where: { userId },
    _sum: { amount: true }
  });
  return agg._sum.amount || 0;
}

router.post("/", authMiddleware, async (req: AuthedRequest, res) => {
  const requesterId = req.user!.userId;
  const { recipientId, initialMessage } = req.body;

  if (!recipientId || !initialMessage) {
    return res.status(400).json({ error: "Missing fields" });
  }

  const credits = await getCredits(requesterId);
  if (credits < MESSAGE_REQUEST_COST) {
    return res.status(400).json({ error: "Insufficient credits" });
  }

  const request = await prisma.$transaction(async (tx) => {
    await tx.creditTransaction.create({
      data: {
        userId: requesterId,
        amount: -MESSAGE_REQUEST_COST,
        reason: "message_request_fee",
        metadata: { recipientId }
      }
    });

    const created = await tx.messageRequest.create({
      data: {
        requesterId,
        recipientId,
        initialMessage,
        creditsCharged: MESSAGE_REQUEST_COST
      }
    });

    await tx.notification.create({
      data: {
        userId: recipientId,
        type: "MESSAGE_REQUEST",
        title: "New message request",
        body: initialMessage.slice(0, 100),
        data: { requestId: created.id, requesterId }
      }
    });

    return created;
  });

  res.json(request);
});

router.post("/:id/respond", authMiddleware, async (req: AuthedRequest, res) => {
  const recipientId = req.user!.userId;
  const { accepted } = req.body;

  const request = await prisma.messageRequest.findUnique({
    where: { id: req.params.id }
  });

  if (!request || request.recipientId !== recipientId) {
    return res.status(404).json({ error: "Request not found" });
  }

  const updated = await prisma.messageRequest.update({
    where: { id: request.id },
    data: { accepted }
  });

  if (accepted) {
    const conversation = await prisma.conversation.create({
      data: {
        participants: {
          create: [{ userId: request.requesterId }, { userId: request.recipientId }]
        },
        messages: {
          create: {
            senderId: request.requesterId,
            content: request.initialMessage
          }
        },
        lastMessageAt: new Date()
      }
    });

    return res.json({ updated, conversation });
  }

  res.json({ updated });
});

export default router;
```

