# 12. Real-Time Messaging with Socket.IO

## `server/src/sockets/index.ts`

```ts
import { Server, Socket } from "socket.io";
import { verifyToken } from "../lib/jwt";
import { prisma } from "../lib/prisma";

const onlineUsers = new Map<string, string>(); // userId -> socketId

export function initSockets(io: Server) {
  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const decoded = verifyToken(token);
      (socket as any).userId = decoded.userId;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket: Socket) => {
    const userId = (socket as any).userId as string;
    onlineUsers.set(userId, socket.id);

    socket.join(`user:${userId}`);

    socket.on("conversation:join", async (conversationId: string) => {
      const membership = await prisma.conversationUser.findUnique({
        where: {
          userId_conversationId: {
            userId,
            conversationId
          }
        }
      });

      if (membership) {
        socket.join(`conversation:${conversationId}`);
      }
    });

    socket.on("message:send", async (payload, cb) => {
      try {
        const { conversationId, content } = payload;

        const membership = await prisma.conversationUser.findUnique({
          where: {
            userId_conversationId: {
              userId,
              conversationId
            }
          }
        });

        if (!membership) {
          return cb?.({ error: "Forbidden" });
        }

        const message = await prisma.message.create({
          data: {
            conversationId,
            senderId: userId,
            content
          }
        });

        await prisma.conversation.update({
          where: { id: conversationId },
          data: { lastMessageAt: new Date() }
        });

        const participants = await prisma.conversationUser.findMany({
          where: { conversationId }
        });

        for (const p of participants) {
          if (p.userId !== userId) {
            await prisma.notification.create({
              data: {
                userId: p.userId,
                type: "MESSAGE",
                title: "New message",
                body: content.slice(0, 100),
                data: { conversationId, messageId: message.id }
              }
            });

            io.to(`user:${p.userId}`).emit("notification:new", {
              type: "MESSAGE",
              title: "New message",
              body: content.slice(0, 100),
              data: { conversationId, messageId: message.id }
            });
          }
        }

        io.to(`conversation:${conversationId}`).emit("message:new", message);
        cb?.({ ok: true, message });
      } catch (e) {
        cb?.({ error: "Failed to send message" });
      }
    });

    socket.on("conversation:read", async (conversationId: string) => {
      await prisma.conversationUser.update({
        where: {
          userId_conversationId: {
            userId,
            conversationId
          }
        },
        data: {
          lastReadAt: new Date()
        }
      });

      io.to(`conversation:${conversationId}`).emit("conversation:read", {
        conversationId,
        userId,
        readAt: new Date()
      });
    });

    socket.on("disconnect", () => {
      onlineUsers.delete(userId);
    });
  });
}
```

