"use client";

import { useEffect, useState } from "react";
import { api } from "../../lib/api";
import { createSocket } from "../../lib/socket";

export default function ChatPage() {
  const [me, setMe] = useState<any>(null);
  const [conversations, setConversations] = useState<any[]>([]);
  const [activeConversation, setActiveConversation] = useState<any>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    let socket: any;

    async function init() {
      const meData = await api("/users/me");
      setMe(meData);

      const convos = await api("/conversations");
      setConversations(convos);

      const notif = await api("/notifications");
      setNotifications(notif);

      socket = createSocket();

      socket.on("notification:new", (n: any) => {
        setNotifications((prev) => [n, ...prev]);
      });

      socket.on("message:new", (msg: any) => {
        setMessages((prev) => [...prev, msg]);
      });
    }

    init();

    return () => socket?.disconnect();
  }, []);

  async function openConversation(conversation: any) {
    setActiveConversation(conversation);
    const msgs = await api(`/conversations/${conversation.id}/messages`);
    setMessages(msgs);

    const socket = createSocket();
    socket.emit("conversation:join", conversation.id);
    socket.emit("conversation:read", conversation.id);
  }

  function sendMessage() {
    const socket = createSocket();
    socket.emit(
      "message:send",
      {
        conversationId: activeConversation.id,
        content
      },
      (response: any) => {
        if (!response.error) {
          setContent("");
        }
      }
    );
  }

  return (
    <main style={{ display: "grid", gridTemplateColumns: "300px 1fr 300px", height: "100vh" }}>
      <aside style={{ borderRight: "1px solid #ccc", padding: 16 }}>
        <h3>{me?.displayName || me?.username}</h3>
        <p>Credits: {me?.credits ?? 0}</p>
        <p>Plan: {me?.subscription?.status ?? "FREE"}</p>

        <h4>Conversations</h4>
        {conversations.map((c) => (
          <button
            key={c.id}
            style={{ display: "block", marginBottom: 8 }}
            onClick={() => openConversation(c)}
          >
            {c.participants
              .map((p: any) => p.user.displayName || p.user.username)
              .join(", ")}
          </button>
        ))}
      </aside>

      <section style={{ padding: 16 }}>
        <h3>Chat</h3>
        <div style={{ minHeight: 400, border: "1px solid #ccc", padding: 8 }}>
          {messages.map((m) => (
            <div key={m.id} style={{ marginBottom: 8 }}>
              <strong>{m.senderId}</strong>: {m.content}
            </div>
          ))}
        </div>

        {activeConversation && (
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <input
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Type a message"
              style={{ flex: 1 }}
            />
            <button onClick={sendMessage}>Send</button>
          </div>
        )}
      </section>

      <aside style={{ borderLeft: "1px solid #ccc", padding: 16 }}>
        <h4>Notifications</h4>
        {notifications.map((n, i) => (
          <div key={n.id || i} style={{ marginBottom: 12 }}>
            <strong>{n.title}</strong>
            <p>{n.body}</p>
          </div>
        ))}
      </aside>
    </main>
  );
}
