## Messages Controller

## `backend/src/controllers/messages.controller.js`

```js
import prisma from '../config/prisma.js';
import { createNotification } from '../services/notification.service.js';
import { getIO, getUserSocket } from '../services/socket.js';

export const sendMessage = async (req, res) => {
  try {
    const { receiverId, content } = req.body;
    const senderId = req.user.userId;

    const message = await prisma.message.create({
      data: {
        senderId,
        receiverId,
        content
      }
    });

    const io = getIO();
    const receiverSocket = getUserSocket(receiverId);

    if (receiverSocket) {
      io.to(receiverSocket).emit('message:new', message);
    }

    await createNotification({
      userId: receiverId,
      type: 'message',
      content: `New message from user ${senderId}`
    });

    res.status(201).json(message);
  } catch (error) {
    res.status(500).json({ message: 'Failed to send message', error: error.message });
  }
};

export const getConversation = async (req, res) => {
  try {
    const currentUserId = req.user.userId;
    const { userId } = req.params;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: currentUserId, receiverId: userId },
          { senderId: userId, receiverId: currentUserId }
        ]
      },
      orderBy: { createdAt: 'asc' }
    });

    res.json(messages);
  } catch (error) {
    res.status(500).json({ message: 'Failed to fetch conversation' });
  }
};
```

