    onLogin(res.data.user);
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>{isRegister ? 'Register' : 'Login'}</h1>
      <input
        placeholder="Email"
        value={form.email}
        onChange={(e) => setForm({ ...form, email: e.target.value })}
      />
      {isRegister && (
        <input
          placeholder="Username"
          value={form.username}
          onChange={(e) => setForm({ ...form, username: e.target.value })}
