import React, { useEffect, useState } from 'react';
import API from '../api.js';

export default function ChatWindow({ socket, currentUser, selectedUser }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState('');

  useEffect(() => {
    if (!selectedUser) return;

    API.get(`/messages/${selectedUser.id}`).then((res) => setMessages(res.data));
  }, [selectedUser]);

  useEffect(() => {
    socket.on('message:new', (message) => {
      if (
        message.senderId === selectedUser?.id ||
        message.receiverId === selectedUser?.id
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off('message:new');
  }, [socket, selectedUser]);

  const send = async () => {
    if (!content.trim() || !selectedUser) return;

    const res = await API.post('/messages', {
      receiverId: selectedUser.id,
      content
    });

    setMessages((prev) => [...prev, res.data]);
    setContent('');
  };

  if (!selectedUser) return <div>Select a user to chat</div>;

  return (
    <div>
      <h2>Chat with {selectedUser.username}</h2>
      <div style={{ border: '1px solid #ccc', minHeight: 300, padding: 10 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === currentUser.id ? 'You' : selectedUser.username}:</b> {m.content}
          </div>
        ))}
      </div>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type message"
      />
      <button onClick={send}>Send</button>
    </div>
  );
}
