```js
import React, { useEffect, useState } from 'react';
import api from './api';
import socket from './socket';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import ChatPage from './pages/ChatPage';

export default function App() {
  const [view, setView] = useState('login');
  const [user, setUser] = useState(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setUser(parsed);
      setView('chat');
      socket.connect();
      socket.emit('register', parsed.id);
    }
  }, []);

  const handleAuth = (authData) => {
    localStorage.setItem('token', authData.token);
    localStorage.setItem('user', JSON.stringify(authData.user));
    setUser(authData.user);
    setView('chat');
    socket.connect();
    socket.emit('register', authData.user.id);
  };

  if (user) {
    return <ChatPage user={user} onLogout={() => {
      localStorage.clear();
      setUser(null);
      setView('login');
      socket.disconnect();
    }} />;
  }

  return (
    <div>
      {view === 'login' ? (
        <LoginPage onLogin={handleAuth} onSwitch={() => setView('register')} />
      ) : (
        <RegisterPage onRegister={handleAuth} onSwitch={() => setView('login')} />
      )}
    </div>
  );
}
```

