            {u.username}
          </div>
        ))}
        <button onClick={onLogout}>Logout</button>
      </div>

      <div>
        <NotificationBell notifications={notifications} />
        {selectedUser ? (
          <ChatWindow currentUser={user} selectedUser={selectedUser} />
        ) : (
          <p>Select a user to chat</p>
        )}
