```js
import React, { useEffect, useState } from 'react';
import api from '../api';
import socket from '../socket';
import MessageList from './MessageList';
import MessageInput from './MessageInput';

export default function ChatWindow({ currentUser, selectedUser }) {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    api.get(`/messages/${selectedUser.id}`).then((res) => {
      setMessages(res.data);
    });

    const onNewMessage = (message) => {
      if (
        (message.senderId === selectedUser.id && message.receiverId === currentUser.id) ||
        (message.senderId === currentUser.id && message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on('message:new', onNewMessage);

    return () => {
      socket.off('message:new', onNewMessage);
    };
  }, [selectedUser.id, currentUser.id]);

  const sendMessage = async (content) => {
    const res = await api.post('/messages', {
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
  };

  return (
    <div>
      <h3>Chat with {selectedUser.username}</h3>
      <MessageList messages={messages} currentUser={currentUser} />
      <MessageInput onSend={sendMessage} />
    </div>
  );
}
