const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcrypt");
const jwt = require("jsonwebtoken");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const PORT = 3000;
const JWT_SECRET = "dev_secret_change_me";

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const db = new sqlite3.Database("./app.db");

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE,
      password_hash TEXT,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER,
      receiver_id INTEGER,
      content TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      type TEXT,
      content TEXT,
      is_read INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function auth(req, res, next) {
  const header = req.headers.authorization;
  if (!header) return res.status(401).json({ error: "Missing token" });

  const token = header.split(" ")[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

const onlineUsers = new Map(); // userId -> socket.id

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const hash = await bcrypt.hash(password, 10);
  db.run(
    "INSERT INTO users (username, password_hash) VALUES (?, ?)",
    [username, hash],
    function (err) {
      if (err) return res.status(400).json({ error: "Username already exists" });
      res.json({ success: true, userId: this.lastID });
    }
  );
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  db.get("SELECT * FROM users WHERE username = ?", [username], async (err, user) => {
    if (err || !user) return res.status(401).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.password_hash);
    if (!ok) return res.status(401).json({ error: "Invalid credentials" });

    const token = jwt.sign(
      { id: user.id, username: user.username, premium: !!user.premium },
      JWT_SECRET
    );

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        premium: !!user.premium
      }
    });
  });
});

app.get("/api/users", auth, (req, res) => {
  db.all(
    "SELECT id, username, premium FROM users WHERE id != ? ORDER BY username",
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.get("/api/messages/:otherUserId", auth, (req, res) => {
  const me = req.user.id;
  const other = Number(req.params.otherUserId);

  db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC, id ASC
    `,
    [me, other, other, me],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.post("/api/messages", auth, (req, res) => {
  const senderId = req.user.id;
  const { receiverId, content } = req.body;

  if (!receiverId || !content?.trim()) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  db.run(
    "INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)",
    [senderId, receiverId, content.trim()],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      const message = {
        id: this.lastID,
        sender_id: senderId,
        receiver_id: receiverId,
        content: content.trim(),
        created_at: new Date().toISOString()
      };

      db.run(
        "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
        [receiverId, "message", `New message from user ${senderId}`]
      );

      const receiverSocket = onlineUsers.get(String(receiverId));
      if (receiverSocket) {
        io.to(receiverSocket).emit("message:new", message);
        io.to(receiverSocket).emit("notification:new", {
          type: "message",
          content: `New message from user ${senderId}`
        });
      }

      res.json(message);
    }
  );
});

app.get("/api/notifications", auth, (req, res) => {
  db.all(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC, id DESC",
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.post("/api/monetize/premium", auth, (req, res) => {
  db.run(
    "UPDATE users SET premium = 1 WHERE id = ?",
    [req.user.id],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      db.run(
        "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
        [req.user.id, "premium", "Premium unlocked"]
      );

      const socketId = onlineUsers.get(String(req.user.id));
      if (socketId) {
        io.to(socketId).emit("notification:new", {
          type: "premium",
          content: "Premium unlocked"
        });
      }

      res.json({ success: true, premium: true });
    }
  );
});

io.on("connection", (socket) => {
  socket.on("auth", (token) => {
    try {
      const user = jwt.verify(token, JWT_SECRET);
      onlineUsers.set(String(user.id), socket.id);
      socket.user = user;
    } catch {}
  });

  socket.on("disconnect", () => {
    if (socket.user) {
      onlineUsers.delete(String(socket.user.id));
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
