# 4) `public/app.js`

```js
let token = localStorage.getItem("token") || "";
let currentUser = JSON.parse(localStorage.getItem("user") || "null");
let selectedUser = null;
let socket = null;

function api(path, options = {}) {
  return fetch(path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {})
    }
  }).then((r) => r.json());
}

async function register() {
  const username = document.getElementById("regUsername").value;
  const password = document.getElementById("regPassword").value;
  const res = await api("/api/register", {
    method: "POST",
    body: JSON.stringify({ username, password })
  });
  alert(res.error || "Registered");
}

async function login() {
  const username = document.getElementById("loginUsername").value;
  const password = document.getElementById("loginPassword").value;

  const res = await api("/api/login", {
    method: "POST",
    body: JSON.stringify({ username, password })
  });

  if (res.error) return alert(res.error);

  token = res.token;
  currentUser = res.user;
  localStorage.setItem("token", token);
  localStorage.setItem("user", JSON.stringify(currentUser));

  initApp();
}

function logout() {
  localStorage.removeItem("token");
  localStorage.removeItem("user");
  token = "";
  currentUser = null;
  selectedUser = null;
  if (socket) socket.disconnect();
  document.getElementById("authSection").classList.remove("hidden");
  document.getElementById("appSection").classList.add("hidden");
}

async function initApp() {
  document.getElementById("authSection").classList.add("hidden");
  document.getElementById("appSection").classList.remove("hidden");
  document.getElementById("me").textContent =
    `Logged in as ${currentUser.username}${currentUser.premium ? " ⭐" : ""}`;

  await loadUsers();
  await loadNotifications();

  socket = io();
  socket.emit("auth", token);

  socket.on("message:new", (msg) => {
    if (selectedUser && (msg.sender_id === selectedUser.id || msg.receiver_id === selectedUser.id)) {
      appendMessage(msg);
    }
  });

  socket.on("notification:new", (n) => {
    const li = document.createElement("li");
    li.textContent = `${n.type}: ${n.content}`;
    document.getElementById("notifications").prepend(li);
  });
}

async function loadUsers() {
  const users = await api("/api/users");
  const ul = document.getElementById("users");
  ul.innerHTML = "";

  users.forEach((u) => {
    const li = document.createElement("li");
    li.innerHTML = `<button>${u.username}${u.premium ? " ⭐" : ""}</button>`;
    li.querySelector("button").onclick = async () => {
      selectedUser = u;
      document.getElementById("chatWith").textContent = `Chat with ${u.username}`;
      await loadMessages();
    };
    ul.appendChild(li);
  });
}

async function loadMessages() {
  if (!selectedUser) return;
  const messages = await api(`/api/messages/${selectedUser.id}`);
  const box = document.getElementById("messages");
  box.innerHTML = "";
  messages.forEach(appendMessage);
}

function appendMessage(msg) {
  const box = document.getElementById("messages");
  const div = document.createElement("div");
  div.className = "message " + (msg.sender_id === currentUser.id ? "mine" : "theirs");
  div.textContent = msg.content;
  box.appendChild(div);
  box.scrollTop = box.scrollHeight;
}

async function sendMessage() {
  if (!selectedUser) return alert("Select a user first");
  const input = document.getElementById("messageInput");
  const content = input.value.trim();
  if (!content) return;

  const msg = await api("/api/messages", {
    method: "POST",
    body: JSON.stringify({
      receiverId: selectedUser.id,
      content
    })
  });

  if (msg.error) return alert(msg.error);
  appendMessage(msg);
  input.value = "";
}

async function loadNotifications() {
  const notifications = await api("/api/notifications");
  const ul = document.getElementById("notifications");
  ul.innerHTML = "";
  notifications.forEach((n) => {
    const li = document.createElement("li");
    li.textContent = `${n.type}: ${n.content}`;
    ul.appendChild(li);
  });
}

async function unlockPremium() {
  const res = await api("/api/monetize/premium", {
    method: "POST"
  });

  if (res.error) return alert(res.error);
  currentUser.premium = true;
  localStorage.setItem("user", JSON.stringify(currentUser));
  document.getElementById("me").textContent =
    `Logged in as ${currentUser.username} ⭐`;
  await loadUsers();
  alert("Premium unlocked");
}

if (token && currentUser) {
  initApp();
}
