## 3. `server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(cors());
app.use(express.json());
app.use(express.static("public"));

/**
 * In-memory storage
 * Minimal only — replace with DB/auth in production
 */
const users = new Map(); 
// username -> { username, password, coins, unlockedMessages: Set(messageId) }

const messages = [];
// { id, from, to, text, paid, price, timestamp }

const onlineUsers = new Map();
// username -> socket.id

let nextMessageId = 1;

/**
 * Helpers
 */
function sanitizeUser(user) {
  return {
    username: user.username,
    coins: user.coins
  };
}

function auth(req, res, next) {
  const username = req.headers["x-username"];
  const password = req.headers["x-password"];

  if (!username || !password) {
    return res.status(401).json({ error: "Missing auth headers" });
  }

  const user = users.get(username);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  req.user = user;
  next();
}

/**
 * Auth routes
 */
app.post("/api/signup", (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  if (users.has(username)) {
    return res.status(400).json({ error: "User already exists" });
  }

  const user = {
    username,
    password,
    coins: 10,
    unlockedMessages: new Set()
  };

  users.set(username, user);

  res.json({ user: sanitizeUser(user) });
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  const user = users.get(username);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  res.json({ user: sanitizeUser(user) });
});

/**
 * Social/user listing
 */
app.get("/api/users", auth, (req, res) => {
  const list = Array.from(users.values())
    .filter(u => u.username !== req.user.username)
    .map(u => ({
      username: u.username,
      online: onlineUsers.has(u.username)
    }));

  res.json({ users: list });
});

/**
 * Messaging
 */
app.get("/api/messages/:otherUser", auth, (req, res) => {
  const me = req.user.username;
  const other = req.params.otherUser;

  const convo = messages
    .filter(
      m =>
        (m.from === me && m.to === other) ||
        (m.from === other && m.to === me)
    )
    .map(m => {
      const isRecipient = m.to === me;
      const unlocked = !m.paid || m.from === me || req.user.unlockedMessages.has(m.id);

      return {
        id: m.id,
        from: m.from,
        to: m.to,
        paid: m.paid,
        price: m.price,
        timestamp: m.timestamp,
        text: unlocked ? m.text : "[Locked message - pay to unlock]"
      };
    });

  res.json({ messages: convo });
});

app.post("/api/messages", auth, (req, res) => {
  const from = req.user.username;
  const { to, text, paid = false, price = 0 } = req.body;

  if (!to || !text) {
    return res.status(400).json({ error: "to and text required" });
  }

  if (!users.has(to)) {
    return res.status(404).json({ error: "Recipient not found" });
  }

  const msg = {
    id: nextMessageId++,
    from,
    to,
    text,
    paid: !!paid,
    price: paid ? Math.max(1, Number(price) || 1) : 0,
    timestamp: Date.now()
  };

  messages.push(msg);

  const recipientSocketId = onlineUsers.get(to);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit("new_message", {
      from: msg.from,
      id: msg.id,
      paid: msg.paid,
      price: msg.price,
      preview: msg.paid ? "[Paid message]" : msg.text
    });

    io.to(recipientSocketId).emit("notification", {
      type: "message",
      text: `New message from ${from}`
    });
  }

  res.json({ message: msg });
});

/**
 * Monetization
 * Fake coin purchase endpoint
 */
app.post("/api/purchase-coins", auth, (req, res) => {
  const { amount } = req.body;
  const add = Math.max(1, Number(amount) || 0);

  req.user.coins += add;

  res.json({
    success: true,
    coins: req.user.coins
  });
});

app.post("/api/unlock-message/:id", auth, (req, res) => {
  const messageId = Number(req.params.id);
  const msg = messages.find(m => m.id === messageId);

  if (!msg) {
    return res.status(404).json({ error: "Message not found" });
  }

  if (msg.to !== req.user.username) {
    return res.status(403).json({ error: "Only recipient can unlock" });
  }

  if (!msg.paid) {
    return res.status(400).json({ error: "Message is not locked" });
  }

  if (req.user.unlockedMessages.has(msg.id)) {
    return res.json({
      success: true,
      text: msg.text,
      coins: req.user.coins
    });
  }

  if (req.user.coins < msg.price) {
    return res.status(400).json({ error: "Not enough coins" });
  }

  req.user.coins -= msg.price;
  req.user.unlockedMessages.add(msg.id);

  const sender = users.get(msg.from);
  if (sender) {
    sender.coins += msg.price;
  }

  res.json({
    success: true,
    text: msg.text,
    coins: req.user.coins
  });
});

/**
 * Socket.IO realtime presence
 */
io.on("connection", socket => {
  socket.on("register", username => {
    if (!username) return;
    onlineUsers.set(username, socket.id);
    io.emit("presence", {
      username,
      online: true
    });
  });

  socket.on("disconnect", () => {
    let disconnectedUser = null;
    for (const [username, sid] of onlineUsers.entries()) {
      if (sid === socket.id) {
        disconnectedUser = username;
        onlineUsers.delete(username);
        break;
      }
    }

    if (disconnectedUser) {
      io.emit("presence", {
        username: disconnectedUser,
        online: false
      });
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
