```js
const authSection = document.getElementById("authSection");
const appSection = document.getElementById("appSection");
const authStatus = document.getElementById("authStatus");

const usernameInput = document.getElementById("username");
const passwordInput = document.getElementById("password");
const signupBtn = document.getElementById("signupBtn");
const loginBtn = document.getElementById("loginBtn");

const meEl = document.getElementById("me");
const coinsEl = document.getElementById("coins");
const buyCoinsBtn = document.getElementById("buyCoinsBtn");

const userList = document.getElementById("userList");
const chatTitle = document.getElementById("chatTitle");
const messagesEl = document.getElementById("messages");
const composer = document.getElementById("composer");
const messageText = document.getElementById("messageText");
const paidMessage = document.getElementById("paidMessage");
const messagePrice = document.getElementById("messagePrice");
const sendBtn = document.getElementById("sendBtn");

const notificationsEl = document.getElementById("notifications");

let currentUser = null;
let currentPassword = null;
let selectedUser = null;
let socket = null;

function headers() {
  return {
    "Content-Type": "application/json",
    "x-username": currentUser.username,
    "x-password": currentPassword
  };
}

function addNotification(text) {
  const li = document.createElement("li");
  li.textContent = `${new Date().toLocaleTimeString()} - ${text}`;
  notificationsEl.prepend(li);
}

async function signup() {
  const username = usernameInput.value.trim();
  const password = passwordInput.value.trim();

  const res = await fetch("/api/signup", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password })
  });

  const data = await res.json();
  if (!res.ok) {
    authStatus.textContent = data.error;
    return;
  }

  authStatus.textContent = "Signup successful. You can now log in.";
}

async function login() {
  const username = usernameInput.value.trim();
  const password = passwordInput.value.trim();

  const res = await fetch("/api/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password })
  });

  const data = await res.json();
  if (!res.ok) {
    authStatus.textContent = data.error;
    return;
  }

  currentUser = data.user;
  currentPassword = password;

  authSection.classList.add("hidden");
  appSection.classList.remove("hidden");

  meEl.textContent = currentUser.username;
  coinsEl.textContent = currentUser.coins;

  connectSocket();
  loadUsers();
}

function connectSocket() {
  socket = io();

  socket.on("connect", () => {
    socket.emit("register", currentUser.username);
  });

  socket.on("new_message", payload => {
    addNotification(`Message from ${payload.from}`);
    if (selectedUser === payload.from) {
      loadMessages(selectedUser);
    }
  });

  socket.on("notification", payload => {
    addNotification(payload.text);
  });

  socket.on("presence", () => {
    loadUsers();
  });
}

async function loadUsers() {
  const res = await fetch("/api/users", {
    headers: headers()
  });
  const data = await res.json();

  userList.innerHTML = "";
  data.users.forEach(user => {
    const li = document.createElement("li");
    li.innerHTML = `
      <button class="user-btn">
        ${user.username} ${user.online ? "🟢" : "⚪"}
      </button>
    `;
    li.querySelector("button").onclick = () => {
      selectedUser = user.username;
      chatTitle.textContent = `Chat with ${user.username}`;
      composer.classList.remove("hidden");
      loadMessages(user.username);
    };
    userList.appendChild(li);
  });
}

async function loadMessages(otherUser) {
  const res = await fetch(`/api/messages/${encodeURIComponent(otherUser)}`, {
    headers: headers()
  });
  const data = await res.json();

  messagesEl.innerHTML = "";

  data.messages.forEach(msg => {
    const div = document.createElement("div");
    div.className = "message";

    const locked = msg.text === "[Locked message - pay to unlock]";

    div.innerHTML = `
      <div><strong>${msg.from}</strong>: ${msg.text}</div>
      <div class="meta">
        ${new Date(msg.timestamp).toLocaleString()}
        ${msg.paid ? ` | Paid: ${msg.price} coins` : ""}
      </div>
    `;

    if (locked) {
      const btn = document.createElement("button");
      btn.textContent = `Unlock for ${msg.price} coins`;
      btn.onclick = async () => {
        const unlockRes = await fetch(`/api/unlock-message/${msg.id}`, {
          method: "POST",
          headers: headers()
        });
        const unlockData = await unlockRes.json();

        if (!unlockRes.ok) {
          alert(unlockData.error);
          return;
        }

        currentUser.coins = unlockData.coins;
        coinsEl.textContent = currentUser.coins;
        loadMessages(otherUser);
      };
      div.appendChild(btn);
    }

    messagesEl.appendChild(div);
  });

  messagesEl.scrollTop = messagesEl.scrollHeight;
}

async function sendMessage() {
  if (!selectedUser) return;

  const text = messageText.value.trim();
  if (!text) return;

  const res = await fetch("/api/messages", {
    method: "POST",
    headers: headers(),
    body: JSON.stringify({
      to: selectedUser,
      text,
      paid: paidMessage.checked,
      price: Number(messagePrice.value || 1)
    })
  });

  const data = await res.json();
  if (!res.ok) {
    alert(data.error);
    return;
  }

  messageText.value = "";
  loadMessages(selectedUser);
}

async function buyCoins() {
  const res = await fetch("/api/purchase-coins", {
    method: "POST",
    headers: headers(),
    body: JSON.stringify({ amount: 10 })
  });

  const data = await res.json();
  currentUser.coins = data.coins;
  coinsEl.textContent = currentUser.coins;
  addNotification("Purchased 10 coins");
}

signupBtn.onclick = signup;
loginBtn.onclick = login;
sendBtn.onclick = sendMessage;
buyCoinsBtn.onclick = buyCoins;
```

