## `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory demo storage
const users = new Map(); // userId -> { id, username, coins }
const messages = []; // { id, from, to, text, createdAt }
const socketsByUser = new Map(); // userId -> socket.id

app.get("/", (_, res) => {
  res.json({ ok: true, service: "social messaging demo" });
});

// Simple signup/login
app.post("/auth", (req, res) => {
  const { username } = req.body;
  if (!username || typeof username !== "string") {
    return res.status(400).json({ error: "username required" });
  }

  let existing = [...users.values()].find(
    (u) => u.username.toLowerCase() === username.toLowerCase()
  );

  if (!existing) {
    existing = { id: uuid(), username, coins: 0 };
    users.set(existing.id, existing);
  }

  res.json(existing);
});

// List users
app.get("/users", (_, res) => {
  res.json([...users.values()]);
});

// Get conversation between two users
app.get("/messages/:userA/:userB", (req, res) => {
  const { userA, userB } = req.params;
  const convo = messages.filter(
    (m) =>
      (m.from === userA && m.to === userB) ||
      (m.from === userB && m.to === userA)
  );
  res.json(convo);
});

// Send message
app.post("/messages", (req, res) => {
  const { from, to, text } = req.body;
  if (!from || !to || !text) {
    return res.status(400).json({ error: "from, to, text required" });
  }

  const sender = users.get(from);
  const recipient = users.get(to);
  if (!sender || !recipient) {
    return res.status(404).json({ error: "user not found" });
  }

  const msg = {
    id: uuid(),
    from,
    to,
    text: String(text).slice(0, 500),
    createdAt: new Date().toISOString()
  };

  messages.push(msg);

  io.to(`user:${to}`).emit("message:new", msg);
  io.to(`user:${to}`).emit("notification", {
    id: uuid(),
    type: "message",
    text: `New message from ${sender.username}`,
    createdAt: new Date().toISOString()
  });

  io.to(`user:${from}`).emit("message:new", msg);

  res.json(msg);
});

// Mock monetization: buy coins
app.post("/purchase", (req, res) => {
  const { userId, amount } = req.body;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: "user not found" });
  }

  const parsed = Number(amount);
  if (![100, 500, 1000].includes(parsed)) {
    return res.status(400).json({ error: "invalid amount" });
  }

  // Mock successful purchase
  user.coins += parsed;

  io.to(`user:${userId}`).emit("notification", {
    id: uuid(),
    type: "purchase",
    text: `Purchase successful: ${parsed} coins added`,
    createdAt: new Date().toISOString()
  });

  res.json({ success: true, user });
});

// Mock premium message using coins
app.post("/premium-message", (req, res) => {
  const { from, to, text } = req.body;
  const sender = users.get(from);
  const recipient = users.get(to);

  if (!sender || !recipient) {
    return res.status(404).json({ error: "user not found" });
  }

  if (sender.coins < 10) {
    return res.status(400).json({ error: "not enough coins" });
  }

  sender.coins -= 10;

  const msg = {
    id: uuid(),
    from,
    to,
    text: `💎 ${String(text).slice(0, 500)}`,
    createdAt: new Date().toISOString(),
    premium: true
  };

  messages.push(msg);

  io.to(`user:${to}`).emit("message:new", msg);
  io.to(`user:${to}`).emit("notification", {
    id: uuid(),
    type: "premium_message",
    text: `Premium message from ${sender.username}`,
    createdAt: new Date().toISOString()
  });

  io.to(`user:${from}`).emit("message:new", msg);
  io.to(`user:${from}`).emit("balance:update", { coins: sender.coins });

  res.json({ success: true, msg, coins: sender.coins });
});

io.on("connection", (socket) => {
  socket.on("identify", (userId) => {
    if (!userId) return;
    socketsByUser.set(userId, socket.id);
    socket.join(`user:${userId}`);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of socketsByUser.entries()) {
      if (socketId === socket.id) {
        socketsByUser.delete(userId);
      }
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

