## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";
const socket = io(API);

export default function App() {
  const [me, setMe] = useState(null);
  const [username, setUsername] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  const selectedUser = useMemo(
    () => users.find((u) => u.id === selectedUserId),
    [users, selectedUserId]
  );

  async function refreshUsers() {
    const res = await fetch(`${API}/users`);
    const data = await res.json();
    setUsers(data);
  }

  async function login() {
    const res = await fetch(`${API}/auth`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const data = await res.json();
    setMe(data);
    socket.emit("identify", data.id);
  }

  async function loadConversation(otherId) {
    if (!me || !otherId) return;
    const res = await fetch(`${API}/messages/${me.id}/${otherId}`);
    const data = await res.json();
    setMessages(data);
  }

  async function sendMessage(premium = false) {
    if (!me || !selectedUserId || !text.trim()) return;

    const endpoint = premium ? "/premium-message" : "/messages";
    const res = await fetch(`${API}${endpoint}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        from: me.id,
        to: selectedUserId,
        text
      })
    });

    const data = await res.json();
    if (!res.ok) {
      alert(data.error || "Failed");
      return;
    }

    if (premium) {
      setMe((prev) => ({ ...prev, coins: data.coins }));
      setMessages((prev) => [...prev, data.msg]);
    } else {
      setMessages((prev) => [...prev, data]);
    }

    setText("");
  }

  async function buyCoins(amount) {
    if (!me) return;
    const res = await fetch(`${API}/purchase`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: me.id, amount })
    });
    const data = await res.json();
    if (data.user) setMe(data.user);
  }

  useEffect(() => {
    refreshUsers();
    const interval = setInterval(refreshUsers, 3000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    socket.on("message:new", (msg) => {
      if (
        me &&
        ((msg.from === me.id && msg.to === selectedUserId) ||
          (msg.from === selectedUserId && msg.to === me.id))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev].slice(0, 10));
    });

    socket.on("balance:update", ({ coins }) => {
      setMe((prev) => ({ ...prev, coins }));
    });

    return () => {
      socket.off("message:new");
      socket.off("notification");
      socket.off("balance:update");
    };
  }, [me, selectedUserId]);

  useEffect(() => {
    if (selectedUserId) loadConversation(selectedUserId);
  }, [selectedUserId, me]);

  if (!me) {
    return (
      <div className="app">
        <div className="panel" style={{ maxWidth: 400, margin: "80px auto" }}>
          <h2>Login / Signup</h2>
          <input
            placeholder="Enter username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <button onClick={login}>Continue</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <h1>Social Messaging Demo</h1>
      <div className="small">
        Logged in as <b>{me.username}</b> · Coins: <b>{me.coins}</b>
      </div>

      <div className="row" style={{ marginTop: 16 }}>
        <div className="panel users">
          <h3>Users</h3>
          {users
            .filter((u) => u.id !== me.id)
            .map((u) => (
              <button key={u.id} onClick={() => setSelectedUserId(u.id)}>
                {u.username}
              </button>
            ))}

          <h3>Buy Coins</h3>
          <button onClick={() => buyCoins(100)}>Buy 100</button>
          <button onClick={() => buyCoins(500)}>Buy 500</button>
          <button onClick={() => buyCoins(1000)}>Buy 1000</button>

          <h3>Notifications</h3>
          {notifications.map((n) => (
            <div key={n.id} className="notif">
              <div>{n.text}</div>
              <div className="small">{n.createdAt}</div>
            </div>
          ))}
        </div>

        <div className="panel chat">
          <h3>
            Chat {selectedUser ? `with ${selectedUser.username}` : ""}
          </h3>

          <div style={{ minHeight: 300, maxHeight: 400, overflowY: "auto" }}>
            {messages.map((m) => (
              <div
                key={m.id}
                className={`msg ${m.from === me.id ? "mine" : ""}`}
              >
                <div>{m.text}</div>
                <div className="small">{m.createdAt}</div>
              </div>
            ))}
          </div>

          {selectedUserId && (
            <>
              <textarea
                rows="3"
                placeholder="Write a message"
                value={text}
                onChange={(e) => setText(e.target.value)}
              />
              <button onClick={() => sendMessage(false)}>Send Message</button>
              <button onClick={() => sendMessage(true)}>
                Send Premium Message (10 coins)
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
