import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import { createServer } from "http";
import { Server } from "socket.io";
import Stripe from "stripe";
import { v4 as uuidv4 } from "uuid";

dotenv.config();

const app = express();
const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use(express.json());

const users = [];
const messages = [];
const premiumUsers = new Set();
const onlineUsers = new Map(); // userId -> socketId

app.get("/", (req, res) => {
  res.json({ ok: true, message: "Server running" });
});

// Register/login minimal demo
app.post("/auth", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  let user = users.find((u) => u.username === username);
  if (!user) {
    user = { id: uuidv4(), username };
    users.push(user);
  }

  res.json({ user, premium: premiumUsers.has(user.id) });
});

app.get("/users", (req, res) => {
  res.json(users);
});

app.get("/messages/:userA/:userB", (req, res) => {
  const { userA, userB } = req.params;
  const convo = messages.filter(
    (m) =>
      (m.from === userA && m.to === userB) ||
      (m.from === userB && m.to === userA)
  );
  res.json(convo);
});

app.post("/messages", (req, res) => {
  const { from, to, text } = req.body;
  if (!from || !to || !text) {
    return res.status(400).json({ error: "from, to, text required" });
  }

  const msg = {
    id: uuidv4(),
    from,
    to,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(msg);

  const recipientSocketId = onlineUsers.get(to);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit("new_message", msg);
    io.to(recipientSocketId).emit("notification", {
      type: "message",
      text: `New message received`
    });
  }

  const senderSocketId = onlineUsers.get(from);
  if (senderSocketId) {
    io.to(senderSocketId).emit("message_sent", msg);
  }

  res.json(msg);
});

// Stripe checkout for premium
app.post("/create-checkout-session", async (req, res) => {
  try {
    const { userId } = req.body;
    if (!userId) return res.status(400).json({ error: "userId required" });

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Messaging"
            },
            unit_amount: 499
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}?payment=success&userId=${userId}`,
      cancel_url: `${process.env.CLIENT_URL}?payment=cancel`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Demo-only endpoint to mark premium after success redirect
app.post("/activate-premium", (req, res) => {
  const { userId } = req.body;
  if (!userId) return res.status(400).json({ error: "userId required" });

  premiumUsers.add(userId);

  const socketId = onlineUsers.get(userId);
  if (socketId) {
    io.to(socketId).emit("notification", {
      type: "premium",
      text: "Premium activated!"
    });
  }

  res.json({ success: true });
});

app.get("/premium/:userId", (req, res) => {
  res.json({ premium: premiumUsers.has(req.params.userId) });
});

io.on("connection", (socket) => {
  socket.on("register_socket", (userId) => {
    onlineUsers.set(userId, socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) {
        onlineUsers.delete(userId);
        break;
      }
    }
  });
});

httpServer.listen(process.env.PORT || 4000, () => {
  console.log(`Server listening on port ${process.env.PORT || 4000}`);
});
```

