import React, { useEffect, useState } from "react";
import {
  auth,
  getUsers,
  getMessages,
  sendMessage,
  createCheckoutSession,
  activatePremium,
  getPremium
} from "./api";
import { socket } from "./socket";

export default function App() {
  const [username, setUsername] = useState("");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [premium, setPremium] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const payment = params.get("payment");
    const userId = params.get("userId");

    if (payment === "success" && userId) {
      activatePremium(userId).then(() => {
        getPremium(userId).then((res) => setPremium(res.premium));
      });
      window.history.replaceState({}, "", "/");
    }
  }, []);

  useEffect(() => {
    socket.on("new_message", (msg) => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("message_sent", (msg) => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("message_sent");
      socket.off("notification");
    };
  }, [selectedUser]);

  async function handleLogin() {
    const res = await auth(username);
    setMe(res.user);
    setPremium(res.premium);
    socket.emit("register_socket", res.user.id);
    const allUsers = await getUsers();
    setUsers(allUsers.filter((u) => u.id !== res.user.id));
  }

  async function openChat(user) {
    setSelectedUser(user);
    const convo = await getMessages(me.id, user.id);
    setMessages(convo);
  }

  async function handleSend() {
    if (!text.trim() || !selectedUser) return;
    await sendMessage(me.id, selectedUser.id, text);
    setText("");
  }

  async function handleUpgrade() {
    const res = await createCheckoutSession(me.id);
    if (res.url) {
      window.location.href = res.url;
    }
  }

  if (!me) {
    return (
      <div style={{ padding: 20, fontFamily: "Arial" }}>
        <h1>Social Messaging App</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter username"
        />
        <button onClick={handleLogin}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "Arial" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 12 }}>
        <h3>{me.username}</h3>
        <p>{premium ? "Premium User" : "Free User"}</p>
        {!premium && <button onClick={handleUpgrade}>Upgrade $4.99</button>}

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>{u.username}</button>
          </div>
        ))}

        <h4>Notifications</h4>
        {notifications.map((n, i) => (
          <div key={i} style={{ fontSize: 12, marginBottom: 8 }}>
            {n.text}
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 12 }}>
        <h2>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h2>

        <div
          style={{
            border: "1px solid #ccc",
            height: "70vh",
            overflowY: "auto",
            padding: 10,
            marginBottom: 10
          }}
        >
          {messages.map((m) => (
            <div
              key={m.id}
              style={{
                textAlign: m.from === me.id ? "right" : "left",
                margin: "8px 0"
              }}
            >
              <span
                style={{
                  display: "inline-block",
                  padding: "8px 12px",
                  background: m.from === me.id ? "#d1e7dd" : "#f8d7da",
                  borderRadius: 8
                }}
              >
                {m.text}
              </span>
            </div>
          ))}
        </div>

        {selectedUser && (
          <div>
            <input
              style={{ width: "70%", marginRight: 8 }}
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type message"
            />
            <button onClick={handleSend}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
}
