const express = require("express");
const http = require("http");
const path = require("path");
const jwt = require("jsonwebtoken");
const bcrypt = require("bcryptjs");
const Database = require("better-sqlite3");
const { Server } = require("socket.io");
const Stripe = require("stripe");
require("dotenv").config();

const app = express();
const server = http.createServer(app);
const io = new Server(server);
const db = new Database("app.db");
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || "secret";
const APP_URL = process.env.APP_URL || `http://localhost:${PORT}`;

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  premium INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sender_id INTEGER NOT NULL,
  receiver_id INTEGER NOT NULL,
  content TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
`);

const onlineUsers = new Map(); // userId -> socket.id

function createToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username, premium: user.premium },
    JWT_SECRET,
    { expiresIn: "7d" }
  );
}

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "Missing token" });
  const token = auth.split(" ")[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/api/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const existing = db.prepare("SELECT id FROM users WHERE username = ?").get(username);
  if (existing) return res.status(400).json({ error: "Username already exists" });

  const hash = bcrypt.hashSync(password, 10);
  const result = db
    .prepare("INSERT INTO users (username, password_hash) VALUES (?, ?)")
    .run(username, hash);

  const user = { id: result.lastInsertRowid, username, premium: 0 };
  const token = createToken(user);
  res.json({ token, user });
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  const user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = bcrypt.compareSync(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = createToken(user);
  res.json({
    token,
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

app.get("/api/users", authMiddleware, (req, res) => {
  const users = db
    .prepare("SELECT id, username, premium FROM users WHERE id != ?")
    .all(req.user.id);
  res.json(users);
});

app.get("/api/messages/:userId", authMiddleware, (req, res) => {
  const otherUserId = Number(req.params.userId);
  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
  `).all(req.user.id, otherUserId, otherUserId, req.user.id);

  res.json(messages);
});

app.post("/api/messages", authMiddleware, (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  const result = db.prepare(`
    INSERT INTO messages (sender_id, receiver_id, content)
    VALUES (?, ?, ?)
  `).run(req.user.id, receiverId, content);

  const message = db.prepare("SELECT * FROM messages WHERE id = ?").get(result.lastInsertRowid);

  const receiverSocketId = onlineUsers.get(Number(receiverId));
  if (receiverSocketId) {
    io.to(receiverSocketId).emit("new_message", message);
    io.to(receiverSocketId).emit("notification", {
      type: "message",
      text: `New message from user ${req.user.username}`
    });
  }

  res.json(message);
});

app.post("/api/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Upgrade"
            },
            unit_amount: 499
          },
          quantity: 1
        }
      ],
      success_url: `${APP_URL}/?success=1`,
      cancel_url: `${APP_URL}/?canceled=1`,
      metadata: {
        userId: String(req.user.id)
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/me", authMiddleware, (req, res) => {
  const user = db
    .prepare("SELECT id, username, premium FROM users WHERE id = ?")
    .get(req.user.id);
  res.json(user);
});

// Minimal fake success endpoint for local demo if you don't configure webhooks.
// In production, use Stripe webhooks instead.
app.post("/api/activate-premium-demo", authMiddleware, (req, res) => {
  db.prepare("UPDATE users SET premium = 1 WHERE id = ?").run(req.user.id);
  const updated = db
    .prepare("SELECT id, username, premium FROM users WHERE id = ?")
    .get(req.user.id);
  res.json(updated);
});

io.on("connection", (socket) => {
  socket.on("authenticate", (token) => {
    try {
      const user = jwt.verify(token, JWT_SECRET);
      onlineUsers.set(user.id, socket.id);
      socket.user = user;
      socket.emit("authenticated", { ok: true });
    } catch {
      socket.emit("authenticated", { ok: false });
    }
  });

  socket.on("disconnect", () => {
    if (socket.user) {
      onlineUsers.delete(socket.user.id);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at ${APP_URL}`);
});
