# 5) `public/app.js`

```js
let token = localStorage.getItem("token");
let currentUser = null;
let selectedUser = null;
let users = [];
let socket = null;

async function api(path, options = {}) {
  const headers = {
    "Content-Type": "application/json",
    ...(options.headers || {})
  };
  if (token) headers.Authorization = `Bearer ${token}`;

  const res = await fetch(path, { ...options, headers });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || "Request failed");
  return data;
}

async function register() {
  try {
    const username = document.getElementById("username").value;
    const password = document.getElementById("password").value;
    const data = await api("/api/register", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    token = data.token;
    localStorage.setItem("token", token);
    await initApp();
  } catch (e) {
    alert(e.message);
  }
}

async function login() {
  try {
    const username = document.getElementById("username").value;
    const password = document.getElementById("password").value;
    const data = await api("/api/login", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    token = data.token;
    localStorage.setItem("token", token);
    await initApp();
  } catch (e) {
    alert(e.message);
  }
}

function logout() {
  localStorage.removeItem("token");
  token = null;
  location.reload();
}

async function initApp() {
  try {
    currentUser = await api("/api/me");
    document.getElementById("authSection").style.display = "none";
    document.getElementById("appSection").style.display = "block";
    document.getElementById("me").textContent = currentUser.username;
    document.getElementById("premiumBadge").textContent = currentUser.premium ? "⭐ Premium" : "";

    users = await api("/api/users");
    renderUsers();

    connectSocket();
  } catch (e) {
    console.error(e);
    logout();
  }
}

function renderUsers() {
  const ul = document.getElementById("users");
  ul.innerHTML = "";
  users.forEach((user) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <button onclick="selectUser(${user.id})">
        ${user.username} ${user.premium ? "⭐" : ""}
      </button>
    `;
    ul.appendChild(li);
  });
}

async function selectUser(userId) {
  selectedUser = users.find(u => u.id === userId);
  document.getElementById("chatTitle").textContent = `Chat with ${selectedUser.username}`;
  await loadMessages();
}

async function loadMessages() {
  if (!selectedUser) return;
  const messages = await api(`/api/messages/${selectedUser.id}`);
  const box = document.getElementById("messages");
  box.innerHTML = "";
  messages.forEach(renderMessage);
}

function renderMessage(msg) {
  const box = document.getElementById("messages");
  const div = document.createElement("div");
  div.className = msg.sender_id === currentUser.id ? "msg mine" : "msg theirs";
  div.textContent = msg.content;
  box.appendChild(div);
  box.scrollTop = box.scrollHeight;
}

async function sendMessage() {
  if (!selectedUser) return alert("Select a user first");
  const input = document.getElementById("messageInput");
  const content = input.value.trim();
  if (!content) return;

  const msg = await api("/api/messages", {
    method: "POST",
    body: JSON.stringify({
      receiverId: selectedUser.id,
      content
    })
  });

  renderMessage(msg);
  input.value = "";
}

function addNotification(text) {
  const ul = document.getElementById("notifications");
  const li = document.createElement("li");
  li.textContent = text;
  ul.prepend(li);
}

function connectSocket() {
  socket = io();
  socket.on("connect", () => {
    socket.emit("authenticate", token);
  });

  socket.on("new_message", (msg) => {
    if (selectedUser && (msg.sender_id === selectedUser.id || msg.receiver_id === selectedUser.id)) {
      renderMessage(msg);
    }
  });

  socket.on("notification", (n) => {
    addNotification(n.text);
  });
}

async function buyPremium() {
  try {
    const data = await api("/api/create-checkout-session", {
      method: "POST"
    });
    window.location.href = data.url;
  } catch (e) {
    alert(e.message);
  }
}

async function activatePremiumDemo() {
  try {
    const user = await api("/api/activate-premium-demo", {
      method: "POST"
    });
    currentUser = user;
    document.getElementById("premiumBadge").textContent = currentUser.premium ? "⭐ Premium" : "";
    addNotification("Premium activated (demo)");
  } catch (e) {
    alert(e.message);
  }
}

if (token) {
  initApp();
}
