const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory demo storage
const users = [];
const messages = [];
const socketsByUserId = new Map();

// Helper
function getUserById(id) {
  return users.find((u) => u.id === id);
}

// Register / login
app.post("/auth", (req, res) => {
  const { username } = req.body;
  if (!username) {
    return res.status(400).json({ error: "username required" });
  }

  let user = users.find((u) => u.username === username);
  if (!user) {
    user = {
      id: uuidv4(),
      username,
      premium: false,
      coins: 0
    };
    users.push(user);
  }

  res.json(user);
});

// List users
app.get("/users", (req, res) => {
  res.json(users);
});

// Get messages between two users
app.get("/messages", (req, res) => {
  const { userId, peerId } = req.query;
  const convo = messages.filter(
    (m) =>
      (m.from === userId && m.to === peerId) ||
      (m.from === peerId && m.to === userId)
  );
  res.json(convo);
});

// Send message
app.post("/messages", (req, res) => {
  const { from, to, text } = req.body;

  if (!from || !to || !text) {
    return res.status(400).json({ error: "from, to, text required" });
  }

  const sender = getUserById(from);
  const recipient = getUserById(to);

  if (!sender || !recipient) {
    return res.status(404).json({ error: "user not found" });
  }

  const message = {
    id: uuidv4(),
    from,
    to,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(message);

  // Real-time notification to recipient
  const recipientSocket = socketsByUserId.get(to);
  if (recipientSocket) {
    recipientSocket.emit("new_message", {
      message,
      notification: `${sender.username} sent you a message`
    });
  }

  res.json(message);
});

// Mock monetization: buy premium
app.post("/purchase/premium", (req, res) => {
  const { userId } = req.body;
  const user = getUserById(userId);

  if (!user) {
    return res.status(404).json({ error: "user not found" });
  }

  user.premium = true;

  const userSocket = socketsByUserId.get(userId);
  if (userSocket) {
    userSocket.emit("premium_activated", {
      premium: true,
      message: "Premium activated"
    });
  }

  res.json({
    success: true,
    premium: true
  });
});

// Mock monetization: buy coins
app.post("/purchase/coins", (req, res) => {
  const { userId, amount } = req.body;
  const user = getUserById(userId);

  if (!user) {
    return res.status(404).json({ error: "user not found" });
  }

  user.coins += Number(amount || 0);

  const userSocket = socketsByUserId.get(userId);
  if (userSocket) {
    userSocket.emit("coins_updated", {
      coins: user.coins
    });
  }

  res.json({
    success: true,
    coins: user.coins
  });
});

io.on("connection", (socket) => {
  socket.on("register_socket", (userId) => {
    socketsByUserId.set(userId, socket);
  });

  socket.on("disconnect", () => {
    for (const [userId, s] of socketsByUserId.entries()) {
      if (s.id === socket.id) {
        socketsByUserId.delete(userId);
      }
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
