```js
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

export default function App() {
  const [username, setUsername] = useState("");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    return () => socket.disconnect();
  }, [socket]);

  useEffect(() => {
    socket.on("new_message", ({ message, notification }) => {
      setNotifications((prev) => [notification, ...prev]);

      if (
        selectedUser &&
        (message.from === selectedUser.id || message.to === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("premium_activated", ({ message }) => {
      setNotifications((prev) => [message, ...prev]);
      setMe((prev) => ({ ...prev, premium: true }));
    });

    socket.on("coins_updated", ({ coins }) => {
      setNotifications((prev) => [`Coins updated: ${coins}`, ...prev]);
      setMe((prev) => ({ ...prev, coins }));
    });

    return () => {
      socket.off("new_message");
      socket.off("premium_activated");
      socket.off("coins_updated");
    };
  }, [socket, selectedUser]);

  async function login() {
    const res = await fetch(`${API}/auth`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const user = await res.json();
    setMe(user);

    socket.connect();
    socket.emit("register_socket", user.id);

    loadUsers(user.id);
  }

  async function loadUsers(myId) {
    const res = await fetch(`${API}/users`);
    const data = await res.json();
    setUsers(data.filter((u) => u.id !== myId));
  }

  async function openChat(user) {
    setSelectedUser(user);
    const res = await fetch(
      `${API}/messages?userId=${me.id}&peerId=${user.id}`
    );
    const data = await res.json();
    setMessages(data);
  }

  async function sendMessage() {
    if (!text.trim() || !selectedUser) return;

    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        from: me.id,
        to: selectedUser.id,
        text
      })
    });

    const msg = await res.json();
    setMessages((prev) => [...prev, msg]);
    setText("");
  }

  async function buyPremium() {
    const res = await fetch(`${API}/purchase/premium`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: me.id })
    });
    const data = await res.json();
    if (data.premium) {
      setMe((prev) => ({ ...prev, premium: true }));
    }
  }

  async function buyCoins() {
    const res = await fetch(`${API}/purchase/coins`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: me.id, amount: 10 })
    });
    const data = await res.json();
    setMe((prev) => ({ ...prev, coins: data.coins }));
  }

  if (!me) {
    return (
      <div className="container">
        <h1>Mini Social Messaging App</h1>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={login}>Login / Register</button>
      </div>
    );
  }

  return (
    <div className="app">
      <aside className="sidebar">
        <h2>{me.username}</h2>
        <p>Premium: {me.premium ? "Yes" : "No"}</p>
        <p>Coins: {me.coins}</p>
        <button onClick={buyPremium}>Buy Premium</button>
        <button onClick={buyCoins}>Buy 10 Coins</button>

        <h3>Users</h3>
        {users.map((user) => (
          <button
            key={user.id}
            className="user-btn"
            onClick={() => openChat(user)}
          >
            {user.username}
          </button>
        ))}

        <h3>Notifications</h3>
        <ul className="notifications">
          {notifications.map((n, i) => (
            <li key={i}>{n}</li>
          ))}
        </ul>
      </aside>

      <main className="chat">
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.username}</h2>
            <div className="messages">
              {messages.map((m) => (
                <div
                  key={m.id}
                  className={m.from === me.id ? "message mine" : "message"}
                >
                  <strong>{m.from === me.id ? "You" : selectedUser.username}:</strong>{" "}
                  {m.text}
                </div>
              ))}
            </div>

            <div className="composer">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message"
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div>Select a user to start chatting</div>
        )}
      </main>
    </div>
  );
}
```

