### `lib/auth.ts`
```ts
import jwt from 'jsonwebtoken'

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret'

export function signToken(user: { id: string; email: string }) {
  return jwt.sign(user, JWT_SECRET, { expiresIn: '7d' })
}

export function verifyToken(token: string) {
  return jwt.verify(token, JWT_SECRET) as { id: string; email: string }
}
```

### Register API
```ts
import { prisma } from '@/lib/prisma'
import bcrypt from 'bcryptjs'
import { signToken } from '@/lib/auth'

export async function POST(req: Request) {
  const { email, password, name } = await req.json()
  const passwordHash = await bcrypt.hash(password, 10)

  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  })

  const token = signToken({ id: user.id, email: user.email })

  return Response.json({ token, user })
}
```

### Login API
```ts
import { prisma } from '@/lib/prisma'
import bcrypt from 'bcryptjs'
import { signToken } from '@/lib/auth'

export async function POST(req: Request) {
  const { email, password } = await req.json()

  const user = await prisma.user.findUnique({ where: { email } })
  if (!user) return new Response('Invalid credentials', { status: 401 })

  const ok = await bcrypt.compare(password, user.passwordHash)
  if (!ok) return new Response('Invalid credentials', { status: 401 })

  const token = signToken({ id: user.id, email: user.email })
  return Response.json({ token, user })
}
```

### Create message API
```ts
import { prisma } from '@/lib/prisma'
import { verifyToken } from '@/lib/auth'

export async function POST(req: Request) {
  const auth = req.headers.get('authorization')
  if (!auth) return new Response('Unauthorized', { status: 401 })

  const token = auth.replace('Bearer ', '')
  const me = verifyToken(token)

  const { receiverId, content } = await req.json()

  const user = await prisma.user.findUnique({ where: { id: me.id } })
  if (!user) return new Response('Unauthorized', { status: 401 })

  if (!user.isPremium && user.credits <= 0) {
    return new Response('Payment required: no credits', { status: 402 })
  }

  const message = await prisma.message.create({
    data: {
      senderId: me.id,
      receiverId,
      content
    }
  })

  if (!user.isPremium) {
    await prisma.user.update({
      where: { id: me.id },
      data: { credits: { decrement: 1 } }
    })
  }

  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: 'message',
      content: `New message from ${user.name}`
    }
  })

  return Response.json({ message, notification })
}
```

## Real-time with Socket.IO

### `server.js`
```ts
const { createServer } = require('http')
const next = require('next')
const { Server } = require('socket.io')

const dev = process.env.NODE_ENV !== 'production'
const app = next({ dev })
const handle = app.getRequestHandler()

app.prepare().then(() => {
  const server = createServer((req, res) => handle(req, res))
  const io = new Server(server, {
    cors: { origin: '*' }
  })

  const onlineUsers = new Map()

  io.on('connection', (socket) => {
    socket.on('join', (userId) => {
      onlineUsers.set(userId, socket.id)
      socket.join(userId)
    })

    socket.on('send_message', (payload) => {
      io.to(payload.receiverId).emit('new_message', payload)
      io.to(payload.receiverId).emit('new_notification', {
        type: 'message',
        content: `New message received`
      })
    })

    socket.on('disconnect', () => {
      for (const [userId, socketId] of onlineUsers.entries()) {
        if (socketId === socket.id) onlineUsers.delete(userId)
      }
    })
  })

  server.listen(3000, () => {
    console.log('> Ready on http://localhost:3000')
  })
})
```

## Stripe monetization

### Create checkout session
```ts
import Stripe from 'stripe'
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!)

export async function POST(req: Request) {
  const { userId, type } = await req.json()

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: 'usd',
          product_data: { name: type === 'credits' ? '10 Message Credits' : 'Premium Upgrade' },
          unit_amount: type === 'credits' ? 499 : 999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.APP_URL}/success`,
    cancel_url: `${process.env.APP_URL}/billing`,
    metadata: { userId, type }
  })

  return Response.json({ url: session.url })
}
```

### Stripe webhook
```ts
import Stripe from 'stripe'
import { prisma } from '@/lib/prisma'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!)

export async function POST(req: Request) {
  const body = await req.text()
  const sig = req.headers.get('stripe-signature')!

  let event
  try {
    event = stripe.webhooks.constructEvent(
      body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    )
  } catch {
    return new Response('Invalid signature', { status: 400 })
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object as Stripe.Checkout.Session
    const userId = session.metadata?.userId!
    const type = session.metadata?.type!

    await prisma.purchase.create({
      data: {
        userId,
        stripeSessionId: session.id,
        type,
        amount: session.amount_total || 0,
        status: 'completed'
      }
    })

    if (type === 'credits') {
      await prisma.user.update({
        where: { id: userId },
        data: { credits: { increment: 10 } }
      })
    }

    if (type === 'premium') {
      await prisma.user.update({
        where: { id: userId },
        data: { isPremium: true }
      })
    }
  }

  return new Response('ok')
}
```

