### Chat page sketch
```tsx
'use client'

import { useEffect, useState } from 'react'
import { io } from 'socket.io-client'

const socket = io('http://localhost:3000')

export default function ChatPage() {
  const [token, setToken] = useState('')
  const [userId, setUserId] = useState('')
  const [receiverId, setReceiverId] = useState('')
  const [content, setContent] = useState('')
  const [messages, setMessages] = useState<any[]>([])
  const [notifications, setNotifications] = useState<any[]>([])

  useEffect(() => {
    const savedUserId = localStorage.getItem('userId') || ''
    setUserId(savedUserId)
    socket.emit('join', savedUserId)

    socket.on('new_message', (msg) => {
      setMessages((prev) => [...prev, msg])
    })

    socket.on('new_notification', (notif) => {
      setNotifications((prev) => [...prev, notif])
    })

    return () => {
      socket.off('new_message')
      socket.off('new_notification')
    }
  }, [])

  async function sendMessage() {
    const res = await fetch('/api/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${localStorage.getItem('token')}`
      },
      body: JSON.stringify({ receiverId, content })
    })

    if (!res.ok) {
      alert(await res.text())
      return
    }

    const data = await res.json()
    setMessages((prev) => [...prev, data.message])

    socket.emit('send_message', data.message)
    setContent('')
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>Chat</h1>
      <input placeholder="Receiver ID" value={receiverId} onChange={(e) => setReceiverId(e.target.value)} />
      <input placeholder="Message" value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>

      <h2>Messages</h2>
      {messages.map((m) => (
        <div key={m.id}>{m.content}</div>
      ))}

      <h2>Notifications</h2>
      {notifications.map((n, i) => (
        <div key={i}>{n.content}</div>
      ))}
    </div>
  )
}
```

