# 1. Backend: `server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const bodyParser = require("body-parser");
const crypto = require("crypto");

const app = express();
app.use(cors());
app.use(bodyParser.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

// In-memory MVP storage
const users = {};
const sessions = {};
const messages = [];
const purchases = [];

function makeId() {
  return crypto.randomBytes(8).toString("hex");
}

function auth(req, res, next) {
  const token = req.headers.authorization;
  if (!token || !sessions[token]) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  req.userId = sessions[token];
  next();
}

// Signup
app.post("/signup", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "Missing fields" });
  }
  const exists = Object.values(users).find(u => u.username === username);
  if (exists) return res.status(400).json({ error: "User exists" });

  const id = makeId();
  users[id] = { id, username, password, coins: 0 };
  res.json({ ok: true });
});

// Login
app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = Object.values(users).find(
    u => u.username === username && u.password === password
  );
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const token = makeId();
  sessions[token] = user.id;
  res.json({ token, user: { id: user.id, username: user.username, coins: user.coins } });
});

// Current user
app.get("/me", auth, (req, res) => {
  const user = users[req.userId];
  res.json({ id: user.id, username: user.username, coins: user.coins });
});

// List users
app.get("/users", auth, (req, res) => {
  const list = Object.values(users).map(u => ({
    id: u.id,
    username: u.username
  }));
  res.json(list);
});

// Get messages between current user and another user
app.get("/messages/:otherUserId", auth, (req, res) => {
  const me = req.userId;
  const other = req.params.otherUserId;
  const convo = messages.filter(
    m =>
      (m.from === me && m.to === other) ||
      (m.from === other && m.to === me)
  );
  res.json(convo);
});

// Send message
app.post("/messages", auth, (req, res) => {
  const { to, text } = req.body;
  if (!to || !text) return res.status(400).json({ error: "Missing fields" });
  if (!users[to]) return res.status(404).json({ error: "Recipient not found" });

  const msg = {
    id: makeId(),
    from: req.userId,
    to,
    text,
    createdAt: Date.now()
  };
  messages.push(msg);

  io.to(to).emit("message:new", msg);
  io.to(to).emit("notification", {
    type: "new_message",
    from: req.userId,
    text: `New message received`
  });
  io.to(req.userId).emit("message:new", msg);

  res.json(msg);
});

// Mock purchase endpoint
app.post("/purchase", auth, (req, res) => {
  const { pack } = req.body;
  const packMap = {
    small: 100,
    medium: 250,
    large: 700
  };
  if (!packMap[pack]) return res.status(400).json({ error: "Invalid pack" });

  users[req.userId].coins += packMap[pack];
  const purchase = {
    id: makeId(),
    userId: req.userId,
    pack,
    amount: packMap[pack],
    createdAt: Date.now()
  };
  purchases.push(purchase);

  io.to(req.userId).emit("notification", {
    type: "purchase_success",
    text: `Purchased ${pack} coin pack`
  });

  res.json({
    ok: true,
    coins: users[req.userId].coins,
    purchase
  });
});

io.on("connection", socket => {
  socket.on("auth", token => {
    const userId = sessions[token];
    if (userId) {
      socket.join(userId);
      socket.emit("ready", { userId });
    }
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

