```jsx
import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  useEffect(() => {
    if (!token) return;

    fetch(`${API}/me`, {
      headers: { Authorization: token }
    })
      .then(r => r.json())
      .then(setMe);

    fetch(`${API}/users`, {
      headers: { Authorization: token }
    })
      .then(r => r.json())
      .then(data => setUsers(data));

    const socket = io(API);
    socket.emit("auth", token);

    socket.on("message:new", msg => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages(prev => [...prev, msg]);
      }
    });

    socket.on("notification", n => {
      setNotifications(prev => [n, ...prev]);
      fetch(`${API}/me`, {
        headers: { Authorization: token }
      })
        .then(r => r.json())
        .then(setMe);
    });

    return () => socket.disconnect();
  }, [token, selectedUser]);

  const authSubmit = async () => {
    const path = authMode === "signup" ? "/signup" : "/login";
    const res = await fetch(`${API}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password })
    });
    const data = await res.json();

    if (authMode === "signup") {
      alert(data.ok ? "Signup successful. Please log in." : data.error);
      if (data.ok) setAuthMode("login");
      return;
    }

    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
    } else {
      alert(data.error || "Auth failed");
    }
  };

  const loadMessages = async user => {
    setSelectedUser(user);
    const res = await fetch(`${API}/messages/${user.id}`, {
      headers: { Authorization: token }
    });
    const data = await res.json();
    setMessages(data);
  };

  const sendMessage = async () => {
    if (!selectedUser || !text.trim()) return;
    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token
      },
      body: JSON.stringify({ to: selectedUser.id, text })
    });
    const msg = await res.json();
    setMessages(prev => [...prev, msg]);
    setText("");
  };

  const buyCoins = async pack => {
    const res = await fetch(`${API}/purchase`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token
      },
      body: JSON.stringify({ pack })
    });
    const data = await res.json();
    if (data.coins !== undefined) {
      setMe(prev => ({ ...prev, coins: data.coins }));
    } else {
      alert(data.error || "Purchase failed");
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    setToken("");
    setMe(null);
    setUsers([]);
    setSelectedUser(null);
    setMessages([]);
  };

  if (!token) {
    return (
      <div style={{ padding: 20, fontFamily: "Arial" }}>
        <h2>Social Messaging MVP</h2>
        <div>
          <button onClick={() => setAuthMode("login")}>Login</button>
          <button onClick={() => setAuthMode("signup")}>Signup</button>
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            placeholder="username"
            value={username}
            onChange={e => setUsername(e.target.value)}
          />
        </div>
        <div style={{ marginTop: 8 }}>
          <input
            placeholder="password"
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
          />
        </div>
        <button style={{ marginTop: 12 }} onClick={authSubmit}>
          {authMode}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "Arial" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 12 }}>
        <h3>{me?.username}</h3>
        <p>Coins: {me?.coins ?? 0}</p>
        <button onClick={() => buyCoins("small")}>Buy Small Pack</button>
        <button onClick={() => buyCoins("medium")} style={{ marginLeft: 8 }}>
          Buy Medium
        </button>
        <div style={{ marginTop: 12 }}>
          <button onClick={logout}>Logout</button>
        </div>

        <h4 style={{ marginTop: 20 }}>Users</h4>
        {users
          .filter(u => u.id !== me?.id)
          .map(u => (
            <div key={u.id}>
              <button onClick={() => loadMessages(u)}>{u.username}</button>
            </div>
          ))}

        <h4 style={{ marginTop: 20 }}>Notifications</h4>
        <div style={{ maxHeight: 200, overflow: "auto" }}>
          {notifications.map((n, i) => (
            <div key={i} style={{ fontSize: 12, marginBottom: 8 }}>
              {n.text}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1, padding: 12 }}>
        <h3>
          Chat {selectedUser ? `with ${selectedUser.username}` : ""}
        </h3>

        <div
          style={{
            border: "1px solid #ccc",
            height: "75vh",
            overflow: "auto",
            padding: 8,
            marginBottom: 12
          }}
        >
          {messages.map(m => (
            <div
              key={m.id}
              style={{
                textAlign: m.from === me?.id ? "right" : "left",
                marginBottom: 8
              }}
            >
              <span
                style={{
                  display: "inline-block",
                  padding: 8,
                  background: m.from === me?.id ? "#d1ffd6" : "#f1f1f1",
                  borderRadius: 8
                }}
              >
                {m.text}
              </span>
            </div>
          ))}
        </div>

        {selectedUser && (
          <div>
            <input
              style={{ width: "80%" }}
              value={text}
              onChange={e => setText(e.target.value)}
              placeholder="Type a message"
            />
