```js
import { useEffect, useState } from "react";
import io from "socket.io-client";

let socket;

export default function ChatPage() {
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);
  const [notification, setNotification] = useState("");

  useEffect(() => {
    const stored = localStorage.getItem("user");
    if (!stored) {
      window.location.href = "/";
      return;
    }

    const parsed = JSON.parse(stored);
    setUser(parsed);

    socket = io();
    socket.emit("register", parsed.id);

    socket.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (n) => {
      setNotification(n.text);
      setTimeout(() => setNotification(""), 3000);
    });

    fetch("/api/auth")
      .then((res) => res.json())
      .then((data) => setUsers(data.filter((u) => u.id !== parsed.id)));

    fetch(`/api/messages?userId=${parsed.id}`)
      .then((res) => res.json())
      .then(setMessages);

    return () => {
      socket.disconnect();
    };
  }, []);

  const sendMessage = async () => {
    if (!receiverId || !content) return;

    const res = await fetch("/api/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        senderId: user.id,
        receiverId: Number(receiverId),
        content
      })
    });

    const msg = await res.json();
    setMessages((prev) => [...prev, msg]);
    socket.emit("send_message", {
      ...msg,
      senderName: user.name
    });
    setContent("");
  };

  const buyPremium = async () => {
    const res = await fetch("/api/purchase", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: user.id })
    });

    const updated = await res.json();
    setUser(updated);
    localStorage.setItem("user", JSON.stringify(updated));
    alert("Premium unlocked!");
  };

  return (
    <div className="container">
      <h1>Welcome, {user?.name}</h1>
      <p>Status: {user?.premium ? "Premium" : "Free"}</p>
      <button onClick={buyPremium}>Buy Premium</button>

      {notification && <div className="notification">{notification}</div>}

      <h2>Send Message</h2>
      <select value={receiverId} onChange={(e) => setReceiverId(e.target.value)}>
        <option value="">Select user</option>
        {users.map((u) => (
          <option key={u.id} value={u.id}>
            {u.name} ({u.email})
          </option>
        ))}
      </select>

      <input
        placeholder="Type message"
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />
      <button onClick={sendMessage}>Send</button>

      <h2>Messages</h2>
      <div className="messages">
        {messages.map((m) => (
          <div key={m.id} className="message">
            <strong>{m.senderId === user?.id ? "You" : `User ${m.senderId}`}</strong>: {m.content}
          </div>
        ))}
      </div>
    </div>
  );
}
