# 1. Backend

Create `server.js`:

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const cors = require("cors");

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

app.use(cors());
app.use(express.json());

/**
 * In-memory data
 */
const users = {}; 
// username -> { username, credits }

const messages = []; 
// { id, from, to, text, paid, unlockedBy: [] }

const onlineUsers = {}; 
// username -> socket.id

let nextMessageId = 1;

/**
 * Auth/login
 */
app.post("/login", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  if (!users[username]) {
    users[username] = { username, credits: 10 };
  }

  res.json(users[username]);
});

/**
 * List users
 */
app.get("/users", (req, res) => {
  res.json(Object.values(users));
});

/**
 * Get conversation between two users
 */
app.get("/messages", (req, res) => {
  const { user1, user2 } = req.query;
  if (!user1 || !user2) {
    return res.status(400).json({ error: "user1 and user2 required" });
  }

  const convo = messages.filter(
    (m) =>
      (m.from === user1 && m.to === user2) ||
      (m.from === user2 && m.to === user1)
  );

  res.json(convo);
});

/**
 * Send message
 * body: { from, to, text, paid }
 */
app.post("/messages", (req, res) => {
  const { from, to, text, paid } = req.body;
  if (!from || !to || !text) {
    return res.status(400).json({ error: "from, to, text required" });
  }

  const msg = {
    id: nextMessageId++,
    from,
    to,
    text,
    paid: !!paid,
    unlockedBy: paid ? [from] : [from, to]
  };

  messages.push(msg);

  if (onlineUsers[to]) {
    io.to(onlineUsers[to]).emit("new_message", msg);
    io.to(onlineUsers[to]).emit("notification", {
      type: "message",
      text: `New message from ${from}`
    });
  }

  if (onlineUsers[from]) {
    io.to(onlineUsers[from]).emit("new_message", msg);
  }

  res.json(msg);
});

/**
 * Unlock paid message
 * body: { username, messageId }
 * costs 3 credits
 */
app.post("/unlock", (req, res) => {
  const { username, messageId } = req.body;
  const user = users[username];
  const msg = messages.find((m) => m.id === Number(messageId));

  if (!user || !msg) {
    return res.status(404).json({ error: "user or message not found" });
  }

  if (!msg.paid) {
    return res.status(400).json({ error: "message is not paid" });
  }

  if (msg.unlockedBy.includes(username)) {
    return res.json({ success: true, credits: user.credits, message: msg });
  }

  if (user.credits < 3) {
    return res.status(400).json({ error: "not enough credits" });
  }

  user.credits -= 3;
  msg.unlockedBy.push(username);

  res.json({ success: true, credits: user.credits, message: msg });
});

/**
 * Fake purchase credits
 * body: { username, amount }
 */
app.post("/purchase", (req, res) => {
  const { username, amount } = req.body;
  const user = users[username];
  if (!user) return res.status(404).json({ error: "user not found" });

  const creditsToAdd = Number(amount) || 0;
  if (creditsToAdd <= 0) {
    return res.status(400).json({ error: "invalid amount" });
  }

  user.credits += creditsToAdd;

  if (onlineUsers[username]) {
    io.to(onlineUsers[username]).emit("credits_updated", {
      credits: user.credits
    });
    io.to(onlineUsers[username]).emit("notification", {
      type: "purchase",
      text: `Purchase successful: +${creditsToAdd} credits`
    });
  }

  res.json(user);
});

/**
 * Socket.IO
 */
io.on("connection", (socket) => {
  socket.on("register", (username) => {
    onlineUsers[username] = socket.id;
    socket.username = username;
    console.log(`${username} connected`);
  });

  socket.on("disconnect", () => {
    if (socket.username) {
      delete onlineUsers[socket.username];
      console.log(`${socket.username} disconnected`);
    }
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

