import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

export default function App() {
  const [username, setUsername] = useState("");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [paid, setPaid] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    if (!me) return;

    socket.connect();
    socket.emit("register", me.username);

    socket.on("new_message", (msg) => {
      if (
        selectedUser &&
        ((msg.from === me.username && msg.to === selectedUser.username) ||
          (msg.from === selectedUser.username && msg.to === me.username))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n.text, ...prev.slice(0, 4)]);
    });

    socket.on("credits_updated", ({ credits }) => {
      setMe((prev) => ({ ...prev, credits }));
    });

    return () => {
      socket.disconnect();
    };
  }, [me, selectedUser, socket]);

  async function login() {
    const res = await fetch(`${API}/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const data = await res.json();
    setMe(data);
    loadUsers();
  }

  async function loadUsers() {
    const res = await fetch(`${API}/users`);
    const data = await res.json();
    setUsers(data);
  }

  async function openChat(user) {
    setSelectedUser(user);
    const res = await fetch(
      `${API}/messages?user1=${me.username}&user2=${user.username}`
    );
    const data = await res.json();
    setMessages(data);
  }

  async function sendMessage() {
    if (!selectedUser || !text.trim()) return;

    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        from: me.username,
        to: selectedUser.username,
        text,
        paid
      })
    });

    const msg = await res.json();
    setMessages((prev) => [...prev, msg]);
    setText("");
    setPaid(false);
  }

  async function purchaseCredits() {
    const res = await fetch(`${API}/purchase`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: me.username, amount: 10 })
    });
    const data = await res.json();
    setMe(data);
  }

  async function unlockMessage(messageId) {
    const res = await fetch(`${API}/unlock`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: me.username, messageId })
    });

    const data = await res.json();
    if (data.success) {
      setMe((prev) => ({ ...prev, credits: data.credits }));
      setMessages((prev) =>
        prev.map((m) =>
          m.id === messageId ? { ...m, unlockedBy: data.message.unlockedBy } : m
        )
      );
    } else {
      alert(data.error || "Failed to unlock");
    }
  }

  if (!me) {
    return (
      <div className="login">
        <h1>Mini Social Messenger</h1>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div className="app">
      <aside className="sidebar">
        <h2>{me.username}</h2>
        <p>Credits: {me.credits}</p>
        <button onClick={purchaseCredits}>Buy 10 Credits</button>

        <h3>Users</h3>
        <button onClick={loadUsers}>Refresh Users</button>
        <ul>
          {users
            .filter((u) => u.username !== me.username)
            .map((u) => (
              <li key={u.username}>
                <button onClick={() => openChat(u)}>{u.username}</button>
              </li>
            ))}
        </ul>

        <h3>Notifications</h3>
        <ul>
          {notifications.map((n, i) => (
            <li key={i}>{n}</li>
          ))}
        </ul>
      </aside>

      <main className="chat">
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.username}</h2>
            <div className="messages">
              {messages.map((m) => {
                const canView = !m.paid || m.unlockedBy.includes(me.username);
                return (
                  <div
                    key={m.id}
                    className={
                      m.from === me.username ? "message mine" : "message"
                    }
                  >
                    <strong>{m.from}: </strong>
                    {canView ? (
                      <span>{m.text}</span>
                    ) : (
                      <>
                        <span>Locked paid message</span>
                        <button onClick={() => unlockMessage(m.id)}>
                          Unlock (3 credits)
                        </button>
                      </>
                    )}
                    {m.paid && <em> 💎</em>}
                  </div>
                );
              })}
            </div>

            <div className="composer">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message"
              />
              <label>
                <input
                  type="checkbox"
                  checked={paid}
                  onChange={(e) => setPaid(e.target.checked)}
                />
                Paid
              </label>
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div className="empty">Select a user to start chatting</div>
        )}
      </main>
    </div>
  );
}
