import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

// In-memory demo data
const users = [];
const messages = [];
const sessions = new Map(); // token -> userId

function auth(req, res, next) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  const userId = sessions.get(token);
  if (!userId) return res.status(401).json({ error: "Unauthorized" });
  req.userId = userId;
  next();
}

app.get("/", (_, res) => {
  res.json({ ok: true, service: "social-messaging-api" });
});

app.post("/signup", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }
  if (users.find(u => u.username === username)) {
    return res.status(400).json({ error: "username already exists" });
  }

  const user = {
    id: uuid(),
    username,
    password,
    premium: false
  };
  users.push(user);

  const token = uuid();
  sessions.set(token, user.id);

  res.json({
    token,
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const token = uuid();
  sessions.set(token, user.id);

  res.json({
    token,
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

app.get("/users", auth, (req, res) => {
  res.json(
    users.map(u => ({
      id: u.id,
      username: u.username,
      premium: u.premium
    }))
  );
});

app.get("/messages/:otherUserId", auth, (req, res) => {
  const { otherUserId } = req.params;
  const convo = messages.filter(
    m =>
      (m.from === req.userId && m.to === otherUserId) ||
      (m.from === otherUserId && m.to === req.userId)
  );
  res.json(convo);
});

app.post("/messages", auth, (req, res) => {
  const { to, text } = req.body;
  if (!to || !text) return res.status(400).json({ error: "to and text required" });

  const msg = {
    id: uuid(),
    from: req.userId,
    to,
    text,
    createdAt: Date.now()
  };

  messages.push(msg);

  io.to(to).emit("message:new", msg);
  io.to(req.userId).emit("message:new", msg);
  io.to(to).emit("notification", {
    type: "new_message",
    text: "You received a new message"
  });

  res.json(msg);
});

// Mock monetization endpoint
app.post("/premium/upgrade", auth, (req, res) => {
  const user = users.find(u => u.id === req.userId);
  if (!user) return res.status(404).json({ error: "User not found" });

  user.premium = true;

  io.to(user.id).emit("premium:upgraded", {
    premium: true
  });

  res.json({
    success: true,
    premium: true
  });
});

io.on("connection", socket => {
  socket.on("auth", ({ token }) => {
    const userId = sessions.get(token);
    if (!userId) return;
    socket.join(userId);
    socket.emit("ready", { userId });
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
