```jsx
import React, { useEffect, useMemo, useState } from "react";
import ReactDOM from "react-dom/client";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [authMode, setAuthMode] = useState("login");
  const [form, setForm] = useState({ username: "", password: "" });
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    if (!token) return;
    socket.connect();
    socket.emit("auth", { token });

    socket.on("message:new", msg => {
      if (
        selectedUser &&
        ((msg.from === selectedUser.id && msg.to === user.id) ||
          (msg.from === user.id && msg.to === selectedUser.id))
      ) {
        setMessages(prev => [...prev, msg]);
      }
    });

    socket.on("notification", n => {
      setNotifications(prev => [n.text, ...prev].slice(0, 5));
    });

    socket.on("premium:upgraded", () => {
      const updated = { ...user, premium: true };
      setUser(updated);
      localStorage.setItem("user", JSON.stringify(updated));
    });

    return () => {
      socket.off("message:new");
      socket.off("notification");
      socket.off("premium:upgraded");
      socket.disconnect();
    };
  }, [token, selectedUser, user, socket]);

  useEffect(() => {
    if (token) loadUsers();
  }, [token]);

  async function api(path, options = {}) {
    const res = await fetch(`${API}${path}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...(token ? { Authorization: `Bearer ${token}` } : {})
      }
    });
    return res.json();
  }

  async function submitAuth() {
    const data = await api(authMode === "login" ? "/login" : "/signup", {
      method: "POST",
      body: JSON.stringify(form)
    });

    if (data.token) {
      setToken(data.token);
      setUser(data.user);
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function loadUsers() {
    const data = await api("/users");
    setUsers(data.filter(u => u.id !== user?.id));
  }

  async function openChat(u) {
    setSelectedUser(u);
    const data = await api(`/messages/${u.id}`);
    setMessages(data);
  }

  async function sendMessage() {
    if (!selectedUser || !text.trim()) return;
    const msg = await api("/messages", {
      method: "POST",
      body: JSON.stringify({ to: selectedUser.id, text })
    });
    setMessages(prev => [...prev, msg]);
    setText("");
  }

  async function upgradePremium() {
    const data = await api("/premium/upgrade", { method: "POST" });
    if (data.success) {
      const updated = { ...user, premium: true };
      setUser(updated);
      localStorage.setItem("user", JSON.stringify(updated));
    }
  }

  function logout() {
    localStorage.clear();
    setToken("");
    setUser(null);
    setUsers([]);
    setSelectedUser(null);
    setMessages([]);
  }

  if (!token || !user) {
    return (
      <div style={{ padding: 24 }}>
        <h2>Messaging MVP</h2>
        <div className="row">
          <button onClick={() => setAuthMode("login")}>Login</button>
          <button onClick={() => setAuthMode("signup")}>Signup</button>
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            placeholder="username"
            value={form.username}
            onChange={e => setForm({ ...form, username: e.target.value })}
          />
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            placeholder="password"
            type="password"
            value={form.password}
            onChange={e => setForm({ ...form, password: e.target.value })}
          />
        </div>
        <div style={{ marginTop: 12 }}>
          <button onClick={submitAuth}>{authMode}</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <div className="sidebar">
        <h3>{user.username}</h3>
        <p>{user.premium ? "Premium" : "Free"}</p>
        {!user.premium && <button onClick={upgradePremium}>Unlock Premium</button>}
        <button onClick={logout} style={{ display: "block", marginTop: 8 }}>Logout</button>

        <h4 style={{ marginTop: 20 }}>Users</h4>
        {users.map(u => (
          <div key={u.id} style={{ marginBottom: 8 }}>
            <button onClick={() => openChat(u)}>
              {u.username} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div className="main">
        <h2>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h2>

        {notifications.map((n, i) => (
          <div className="notice" key={i}>{n}</div>
        ))}

        <div className="messages">
          {messages.map(m => (
            <div className="msg" key={m.id}>
              <strong>{m.from === user.id ? "You" : selectedUser?.username}:</strong> {m.text}
            </div>
          ))}
        </div>

        {selectedUser && (
          <div className="row">
            <input
              style={{ flex: 1 }}
              value={text}
              onChange={e => setText(e.target.value)}
              placeholder="Type a message"
            />
            <button onClick={sendMessage}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
