const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const dotenv = require("dotenv");
const Stripe = require("stripe");
const { v4: uuidv4 } = require("uuid");
const path = require("path");

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server);
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const PORT = process.env.PORT || 3000;
const BASE_URL = process.env.BASE_URL || `http://localhost:${PORT}`;

/**
 * In-memory demo storage
 */
const users = [
  { id: "u1", username: "alice", password: "1234", premium: false },
  { id: "u2", username: "bob", password: "1234", premium: false }
];

const sessions = new Map(); // token -> userId
const socketsByUserId = new Map(); // userId -> socket.id
const messages = []; // {id, from, to, text, createdAt}

/**
 * Helpers
 */
function auth(req, res, next) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  if (!token || !sessions.has(token)) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  req.userId = sessions.get(token);
  next();
}

function getUserSafe(user) {
  return {
    id: user.id,
    username: user.username,
    premium: user.premium
  };
}

/**
 * Auth routes
 */
app.post("/api/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const exists = users.find(u => u.username === username);
  if (exists) {
    return res.status(400).json({ error: "username already exists" });
  }

  const user = {
    id: uuidv4(),
    username,
    password,
    premium: false
  };

  users.push(user);
  const token = uuidv4();
  sessions.set(token, user.id);

  res.json({ token, user: getUserSafe(user) });
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = uuidv4();
  sessions.set(token, user.id);

  res.json({ token, user: getUserSafe(user) });
});

app.get("/api/me", auth, (req, res) => {
  const user = users.find(u => u.id === req.userId);
  res.json({ user: getUserSafe(user) });
});

app.get("/api/users", auth, (req, res) => {
  const currentUserId = req.userId;
  res.json({
    users: users
      .filter(u => u.id !== currentUserId)
      .map(getUserSafe)
  });
});

/**
 * Messaging routes
 */
app.get("/api/messages/:otherUserId", auth, (req, res) => {
  const currentUserId = req.userId;
  const otherUserId = req.params.otherUserId;

  const thread = messages.filter(
    m =>
      (m.from === currentUserId && m.to === otherUserId) ||
      (m.from === otherUserId && m.to === currentUserId)
  );

  res.json({ messages: thread });
});

app.post("/api/messages", auth, (req, res) => {
  const from = req.userId;
  const { to, text } = req.body;

  if (!to || !text) {
    return res.status(400).json({ error: "to and text required" });
  }

  const recipient = users.find(u => u.id === to);
  if (!recipient) {
    return res.status(404).json({ error: "Recipient not found" });
  }

  const sender = users.find(u => u.id === from);

  // Monetization rule:
  // free users can only send messages up to 5 chars to demonstrate premium gating
  if (!sender.premium && text.length > 5) {
    return res.status(402).json({
      error: "Upgrade to premium to send messages longer than 5 characters"
    });
  }

  const message = {
    id: uuidv4(),
    from,
    to,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(message);

  const recipientSocketId = socketsByUserId.get(to);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit("new_message", message);
    io.to(recipientSocketId).emit("notification", {
      type: "message",
      title: "New message",
      body: `${sender.username}: ${text}`
    });
  }

  res.json({ message });
});

/**
 * Stripe checkout
 */
app.post("/api/create-checkout-session", auth, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Messaging Upgrade"
            },
            unit_amount: 500
          },
          quantity: 1
        }
      ],
      success_url: `${BASE_URL}/?success=1`,
      cancel_url: `${BASE_URL}/?canceled=1`,
      metadata: {
        userId: req.userId
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

/**
 * Demo-only success endpoint to mark premium manually
 * In production, use Stripe webhooks instead.
 */
app.post("/api/demo-upgrade", auth, (req, res) => {
  const user = users.find(u => u.id === req.userId);
  user.premium = true;
  res.json({ user: getUserSafe(user) });
});

/**
 * Socket auth
 */
io.on("connection", socket => {
  socket.on("authenticate", token => {
    const userId = sessions.get(token);
    if (!userId) {
      socket.emit("auth_error", "Invalid token");
      return;
    }

    socketsByUserId.set(userId, socket.id);
    socket.data.userId = userId;
    socket.emit("authenticated", { userId });
  });

  socket.on("disconnect", () => {
    const userId = socket.data.userId;
    if (userId) {
      socketsByUserId.delete(userId);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at ${BASE_URL}`);
});
