# 5) `public/app.js`

```js
let token = localStorage.getItem("token") || "";
let currentUser = null;
let selectedUser = null;
let socket = null;

async function api(path, options = {}) {
  const res = await fetch(path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {})
    }
  });

  const data = await res.json();
  if (!res.ok) throw new Error(data.error || "Request failed");
  return data;
}

function addNotification(text) {
  const li = document.createElement("li");
  li.textContent = text;
  document.getElementById("notifications").prepend(li);
}

function renderMe() {
  document.getElementById("me").textContent = currentUser.username;
  document.getElementById("premiumBadge").textContent = currentUser.premium
    ? "⭐ Premium"
    : "Free";
}

async function register() {
  try {
    const username = document.getElementById("username").value;
    const password = document.getElementById("password").value;
    const data = await api("/api/register", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    token = data.token;
    localStorage.setItem("token", token);
    currentUser = data.user;
    initApp();
  } catch (e) {
    alert(e.message);
  }
}

async function login() {
  try {
    const username = document.getElementById("username").value;
    const password = document.getElementById("password").value;
    const data = await api("/api/login", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    token = data.token;
    localStorage.setItem("token", token);
    currentUser = data.user;
    initApp();
  } catch (e) {
    alert(e.message);
  }
}

async function loadMe() {
  const data = await api("/api/me");
  currentUser = data.user;
  renderMe();
}

async function loadUsers() {
  const data = await api("/api/users");
  const list = document.getElementById("usersList");
  list.innerHTML = "";

  data.users.forEach(user => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.textContent = user.username + (user.premium ? " ⭐" : "");
    btn.onclick = () => selectUser(user);
    li.appendChild(btn);
    list.appendChild(li);
  });
}

async function selectUser(user) {
  selectedUser = user;
  document.getElementById("chatWith").textContent = `Chatting with ${user.username}`;
  await loadMessages();
}

async function loadMessages() {
  if (!selectedUser) return;
  const data = await api(`/api/messages/${selectedUser.id}`);
  const box = document.getElementById("messages");
  box.innerHTML = "";

  data.messages.forEach(msg => {
    const div = document.createElement("div");
    div.className = "message " + (msg.from === currentUser.id ? "mine" : "theirs");
    div.textContent = msg.text;
    box.appendChild(div);
  });

  box.scrollTop = box.scrollHeight;
}

async function sendMessage() {
  if (!selectedUser) return alert("Select a user first");
  const input = document.getElementById("messageInput");
  const text = input.value.trim();
  if (!text) return;

  try {
    await api("/api/messages", {
      method: "POST",
      body: JSON.stringify({
        to: selectedUser.id,
        text
      })
    });
    input.value = "";
    await loadMessages();
  } catch (e) {
    alert(e.message);
  }
}

async function startCheckout() {
  try {
    const data = await api("/api/create-checkout-session", {
      method: "POST"
    });
    window.location.href = data.url;
  } catch (e) {
    alert(e.message);
  }
}

async function demoUpgrade() {
  try {
    const data = await api("/api/demo-upgrade", {
      method: "POST"
    });
    currentUser = data.user;
    renderMe();
    addNotification("Premium unlocked (demo)");
  } catch (e) {
    alert(e.message);
  }
}

function initSocket() {
  socket = io();

  socket.on("connect", () => {
    socket.emit("authenticate", token);
  });

  socket.on("authenticated", () => {
    addNotification("Realtime connected");
  });

  socket.on("new_message", async msg => {
    addNotification("New message received");
    if (
      selectedUser &&
      (msg.from === selectedUser.id || msg.to === selectedUser.id)
    ) {
      await loadMessages();
    }
  });

  socket.on("notification", notif => {
    addNotification(`${notif.title}: ${notif.body}`);
  });
}

async function initApp() {
  document.getElementById("authSection").classList.add("hidden");
  document.getElementById("appSection").classList.remove("hidden");
  await loadMe();
  await loadUsers();
  initSocket();
}

async function boot() {
  if (!token) return;
  try {
    await initApp();
  } catch {
    localStorage.removeItem("token");
    token = "";
  }
}

boot();
