# 5. `server.js`

```js
require("dotenv").config();

const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");
const cors = require("cors");
const Stripe = require("stripe");

const app = express();
const server = http.createServer(app);
const io = new Server(server);
const stripe = Stripe(process.env.STRIPE_SECRET_KEY);

app.use(cors());
app.use(express.json());
app.use(express.static("public"));

const db = new sqlite3.Database("./app.db");

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE,
      password TEXT,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER,
      receiver_id INTEGER,
      content TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: "No token" });

  const token = authHeader.split(" ")[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

function getUserByUsername(username) {
  return new Promise((resolve, reject) => {
    db.get("SELECT * FROM users WHERE username = ?", [username], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

function getUserById(id) {
  return new Promise((resolve, reject) => {
    db.get("SELECT * FROM users WHERE id = ?", [id], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

const onlineUsers = new Map();

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  const hashed = await bcrypt.hash(password, 10);

  db.run(
    "INSERT INTO users (username, password) VALUES (?, ?)",
    [username, hashed],
    function (err) {
      if (err) return res.status(400).json({ error: "Username already exists" });
      res.json({ success: true });
    }
  );
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await getUserByUsername(username);

  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const valid = await bcrypt.compare(password, user.password);
  if (!valid) return res.status(400).json({ error: "Invalid credentials" });

  const token = jwt.sign(
    { id: user.id, username: user.username, premium: user.premium },
    process.env.JWT_SECRET
  );

  res.json({
    token,
    user: {
      id: user.id,
      username: user.username,
      premium: user.premium
    }
  });
});

app.get("/api/users", authMiddleware, (req, res) => {
  db.all(
    "SELECT id, username, premium FROM users WHERE id != ?",
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.get("/api/messages/:userId", authMiddleware, (req, res) => {
  const otherUserId = parseInt(req.params.userId, 10);

  db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
    `,
    [req.user.id, otherUserId, otherUserId, req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content } = req.body;

  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  db.run(
    "INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)",
    [req.user.id, receiverId, content],
    async function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      const message = {
        id: this.lastID,
        sender_id: req.user.id,
        receiver_id: receiverId,
        content,
        created_at: new Date().toISOString()
      };

      const receiverSocketId = onlineUsers.get(String(receiverId));
      if (receiverSocketId) {
        io.to(receiverSocketId).emit("new_message", message);
        io.to(receiverSocketId).emit("notification", {
          type: "message",
          text: `New message from ${req.user.username}`
        });
      }

      res.json(message);
    }
  );
});

app.post("/api/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price: process.env.STRIPE_PRICE_ID,
          quantity: 1
        }
      ],
      success_url: `${process.env.APP_URL}/app.html?payment=success`,
      cancel_url: `${process.env.APP_URL}/app.html?payment=cancel`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/upgrade-premium", authMiddleware, (req, res) => {
  db.run(
    "UPDATE users SET premium = 1 WHERE id = ?",
    [req.user.id],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json({ success: true });
    }
  );
});

io.on("connection", (socket) => {
  socket.on("authenticate", (token) => {
    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      onlineUsers.set(String(user.id), socket.id);
      socket.user = user;
      socket.emit("authenticated", { success: true });
    } catch {
      socket.emit("authenticated", { success: false });
    }
  });

  socket.on("disconnect", () => {
    if (socket.user) {
      onlineUsers.delete(String(socket.user.id));
    }
  });
});

server.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on http://localhost:${process.env.PORT || 3000}`);
});
```

