const token = localStorage.getItem("token");
const me = JSON.parse(localStorage.getItem("user") || "null");

if (!token || !me) {
  window.location.href = "/";
}

const socket = io();
let selectedUser = null;

socket.on("connect", () => {
  socket.emit("authenticate", token);
});

socket.on("new_message", (message) => {
  if (
    selectedUser &&
    (message.sender_id === selectedUser.id || message.receiver_id === selectedUser.id)
  ) {
    appendMessage(message);
  }
});

socket.on("notification", (notification) => {
  const li = document.createElement("li");
  li.innerText = notification.text;
  document.getElementById("notifications").prepend(li);
});

socket.on("authenticated", (data) => {
  if (!data.success) {
    logout();
  }
});

document.getElementById("me").innerText =
  `Logged in as ${me.username} ${me.premium ? "(Premium)" : "(Free)"}`;

async function loadUsers() {
  const res = await fetch("/api/users", {
    headers: { Authorization: `Bearer ${token}` }
  });
  const users = await res.json();

  const ul = document.getElementById("users");
  ul.innerHTML = "";

  users.forEach((user) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <button onclick="selectUser(${user.id}, '${user.username}')">
        ${user.username} ${user.premium ? "⭐" : ""}
      </button>
    `;
    ul.appendChild(li);
  });
}

async function selectUser(id, username) {
  selectedUser = { id, username };
  document.getElementById("chatTitle").innerText = `Chat with ${username}`;

  const res = await fetch(`/api/messages/${id}`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const messages = await res.json();

  const box = document.getElementById("messages");
  box.innerHTML = "";
  messages.forEach(appendMessage);
}

function appendMessage(message) {
  const div = document.createElement("div");
  div.className = message.sender_id === me.id ? "message mine" : "message theirs";
  div.innerText = message.content;
  document.getElementById("messages").appendChild(div);
}

async function sendMessage() {
  if (!selectedUser) return alert("Select a user first");

  const input = document.getElementById("messageInput");
  const content = input.value.trim();
  if (!content) return;

  const res = await fetch("/api/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`
    },
    body: JSON.stringify({
      receiverId: selectedUser.id,
      content
    })
  });

  const message = await res.json();
  appendMessage(message);
  input.value = "";
}

async function buyPremium() {
  const res = await fetch("/api/create-checkout-session", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`
    }
  });

  const data = await res.json();
  if (data.url) {
    window.location.href = data.url;
  } else {
    alert(data.error || "Payment error");
  }
}

// Minimal mock finalization for demo purposes
async function mockUpgrade() {
  const res = await fetch("/api/upgrade-premium", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`
    }
  });

  const data = await res.json();
  if (data.success) {
    alert("Premium upgraded");
    const updated = { ...me, premium: 1 };
    localStorage.setItem("user", JSON.stringify(updated));
    location.reload();
  }
}

function logout() {
  localStorage.removeItem("token");
  localStorage.removeItem("user");
  window.location.href = "/";
}

loadUsers();
