```js
import express from "express";
import http from "http";
import cors from "cors";
import jwt from "jsonwebtoken";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "http://localhost:5173", methods: ["GET", "POST"] }
});

app.use(cors());
app.use(express.json());

const JWT_SECRET = "dev_secret_key";

// In-memory data for MVP
const users = [];
const messages = [];
const notifications = [];
const premiumUsers = new Set();
const onlineUsers = new Map(); // userId -> socketId

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "Missing token" });
  const token = auth.split(" ")[1];
  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.get("/", (req, res) => {
  res.json({ ok: true, service: "social-mvp-server" });
});

app.post("/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }
  if (users.find(u => u.username === username)) {
    return res.status(400).json({ error: "username already exists" });
  }

  const user = { id: uuidv4(), username, password };
  users.push(user);

  const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET);
  res.json({ token, user: { id: user.id, username: user.username } });
});

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) return res.status(401).json({ error: "invalid credentials" });

  const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET);
  res.json({ token, user: { id: user.id, username: user.username } });
});

app.get("/users", authMiddleware, (req, res) => {
  res.json(
    users
      .filter(u => u.id !== req.user.id)
      .map(u => ({
        id: u.id,
        username: u.username,
        premium: premiumUsers.has(u.id),
        online: onlineUsers.has(u.id)
      }))
  );
});

app.get("/messages/:otherUserId", authMiddleware, (req, res) => {
  const { otherUserId } = req.params;
  const convo = messages.filter(
    m =>
      (m.from === req.user.id && m.to === otherUserId) ||
      (m.from === otherUserId && m.to === req.user.id)
  );
  res.json(convo);
});

app.get("/notifications", authMiddleware, (req, res) => {
  const userNotifications = notifications.filter(n => n.userId === req.user.id);
  res.json(userNotifications);
});

app.post("/purchase", authMiddleware, (req, res) => {
  premiumUsers.add(req.user.id);

  notifications.push({
    id: uuidv4(),
    userId: req.user.id,
    text: "Premium unlocked successfully",
    createdAt: Date.now()
  });

  const socketId = onlineUsers.get(req.user.id);
  if (socketId) {
    io.to(socketId).emit("notification", {
      text: "Premium unlocked successfully"
    });
  }

  res.json({ success: true, premium: true });
});

io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("Missing token"));
  try {
    const user = jwt.verify(token, JWT_SECRET);
    socket.user = user;
    next();
  } catch {
    next(new Error("Invalid token"));
  }
});

io.on("connection", socket => {
  onlineUsers.set(socket.user.id, socket.id);

  io.emit("presence", Array.from(onlineUsers.keys()));

  socket.on("send_message", ({ to, text }) => {
    const msg = {
      id: uuidv4(),
      from: socket.user.id,
      to,
      text,
      createdAt: Date.now()
    };
    messages.push(msg);

    const notif = {
      id: uuidv4(),
      userId: to,
      text: `New message from ${socket.user.username}`,
      createdAt: Date.now()
    };
    notifications.push(notif);

    const recipientSocket = onlineUsers.get(to);
    if (recipientSocket) {
      io.to(recipientSocket).emit("new_message", msg);
      io.to(recipientSocket).emit("notification", notif);
    }

    socket.emit("new_message", msg);
  });

  socket.on("disconnect", () => {
    onlineUsers.delete(socket.user.id);
    io.emit("presence", Array.from(onlineUsers.keys()));
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

