```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:3001";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(
    JSON.parse(localStorage.getItem("user") || "null")
  );
  const [mode, setMode] = useState("login");
  const [authForm, setAuthForm] = useState({ username: "", password: "" });
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => {
    if (!token) return null;
    return io(API, { auth: { token } });
  }, [token]);

  useEffect(() => {
    if (!token) return;

    fetch(`${API}/users`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(setUsers);

    fetch(`${API}/notifications`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(setNotifications);
  }, [token]);

  useEffect(() => {
    if (!socket) return;

    socket.on("new_message", msg => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages(prev => [...prev, msg]);
      }
    });

    socket.on("notification", notif => {
      setNotifications(prev => [notif, ...prev]);
    });

    socket.on("presence", onlineIds => {
      setUsers(prev =>
        prev.map(u => ({ ...u, online: onlineIds.includes(u.id) }))
      );
    });

    return () => socket.disconnect();
  }, [socket, selectedUser]);

  async function auth(endpoint) {
    const res = await fetch(`${API}/${endpoint}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(authForm)
    });
    const data = await res.json();
    if (data.token) {
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
      setToken(data.token);
      setMe(data.user);
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function loadMessages(user) {
    setSelectedUser(user);
    const res = await fetch(`${API}/messages/${user.id}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    setMessages(data);
  }

  function sendMessage() {
    if (!text.trim() || !selectedUser || !socket) return;
    socket.emit("send_message", { to: selectedUser.id, text });
    setText("");
  }

  async function purchasePremium() {
    const res = await fetch(`${API}/purchase`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) {
      alert("Premium unlocked");
    }
  }

  function logout() {
    localStorage.clear();
    setToken("");
    setMe(null);
    setUsers([]);
    setSelectedUser(null);
    setMessages([]);
    setNotifications([]);
  }

  if (!token || !me) {
    return (
      <div style={{ maxWidth: 360, margin: "80px auto", background: "white", padding: 20 }}>
        <h2>Social MVP</h2>
        <input
          placeholder="Username"
          value={authForm.username}
          onChange={e => setAuthForm({ ...authForm, username: e.target.value })}
          style={{ width: "100%", marginBottom: 8 }}
        />
        <input
          placeholder="Password"
          type="password"
          value={authForm.password}
          onChange={e => setAuthForm({ ...authForm, password: e.target.value })}
          style={{ width: "100%", marginBottom: 8 }}
        />
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => auth(mode)}>{mode}</button>
          <button onClick={() => setMode(mode === "login" ? "register" : "login")}>
            switch to {mode === "login" ? "register" : "login"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <div className="sidebar">
        <h3>{me.username}</h3>
        <button onClick={purchasePremium}>Unlock Premium</button>
        <button onClick={logout} style={{ marginLeft: 8 }}>Logout</button>

        <h4>Notifications</h4>
        {notifications.slice(0, 5).map((n, i) => (
          <div key={n.id || i} className="notif">{n.text}</div>
        ))}

        <h4>Users</h4>
        {users.map(user => (
          <div
            key={user.id}
            className={`user ${selectedUser?.id === user.id ? "selected" : ""}`}
            onClick={() => loadMessages(user)}
          >
            <div>{user.username} {user.online ? "🟢" : "⚪"}</div>
            <small>{user.premium ? "Premium" : "Free"}</small>
          </div>
        ))}
      </div>

      <div className="main">
        <div className="topbar">
          <div>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</div>
        </div>

        <div className="messages">
          {messages.map(msg => (
            <div
              key={msg.id}
              className={`msg ${msg.from === me.id ? "mine" : ""}`}
            >
              {msg.text}
            </div>
          ))}
        </div>

        <div className="input">
          <input
            style={{ flex: 1 }}
            value={text}
            onChange={e => setText(e.target.value)}
            placeholder="Type a message"
            onKeyDown={e => e.key === "Enter" && sendMessage()}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}
