  cors: { origin: "*" }
});

// In-memory demo data
const users = new Map(); // username -> { username, premium }
const messages = []; // { from, to, text, ts }
const socketsByUser = new Map(); // username -> socket.id

app.post("/login", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  if (!users.has(username)) {
    users.set(username, { username, premium: false });
  }

  res.json({ user: users.get(username) });
});

app.get("/messages/:username/:peer", (req, res) => {
  const { username, peer } = req.params;
  const convo = messages.filter(
    m =>
      (m.from === username && m.to === peer) ||
      (m.from === peer && m.to === username)
  );
  res.json({ messages: convo });
});

app.post("/monetize/upgrade", (req, res) => {
  const { username } = req.body;
  const user = users.get(username);
  if (!user) return res.status(404).json({ error: "user not found" });

  user.premium = true;
  users.set(username, user);

  const socketId = socketsByUser.get(username);
  if (socketId) {
    io.to(socketId).emit("premium-upgraded", { premium: true });
  }

  res.json({ success: true, user });
});

io.on("connection", socket => {
  socket.on("register", username => {
    socketsByUser.set(username, socket.id);
    socket.data.username = username;
    io.to(socket.id).emit("notification", {
      type: "system",
      message: `Welcome, ${username}`
    });
  });

  socket.on("send-message", payload => {
    const { from, to, text } = payload;
    if (!from || !to || !text) return;

    const msg = { from, to, text, ts: Date.now() };
    messages.push(msg);

    const recipientSocket = socketsByUser.get(to);
    const senderSocket = socketsByUser.get(from);

    if (recipientSocket) {
      io.to(recipientSocket).emit("new-message", msg);
      io.to(recipientSocket).emit("notification", {
        type: "message",
        message: `New message from ${from}`
      });
    }

    if (senderSocket) {
      io.to(senderSocket).emit("new-message", msg);
    }
  });

  socket.on("disconnect", () => {
    const username = socket.data.username;
    if (username) socketsByUser.delete(username);
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
