Create a Vite React app, then replace `src/App.jsx` with:

```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

export default function App() {
  const [username, setUsername] = useState("");
  const [inputName, setInputName] = useState("");
  const [peer, setPeer] = useState("bob");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [premium, setPremium] = useState(false);

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    if (!username) return;

    socket.connect();
    socket.emit("register", username);

    socket.on("new-message", msg => {
      const relevant =
        (msg.from === username && msg.to === peer) ||
        (msg.from === peer && msg.to === username);
      if (relevant) {
        setMessages(prev => [...prev, msg]);
      }
    });

    socket.on("notification", n => {
      setNotifications(prev => [n, ...prev].slice(0, 10));
    });

    socket.on("premium-upgraded", data => {
      setPremium(data.premium);
      setNotifications(prev => [
        { type: "monetization", message: "You are now premium!" },
        ...prev
      ]);
    });

    return () => {
      socket.off("new-message");
      socket.off("notification");
      socket.off("premium-upgraded");
      socket.disconnect();
    };
  }, [username, peer, socket]);

  useEffect(() => {
    if (!username || !peer) return;
    fetch(`${API}/messages/${username}/${peer}`)
      .then(r => r.json())
      .then(data => setMessages(data.messages || []));
  }, [username, peer]);

  async function login() {
    const res = await fetch(`${API}/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: inputName })
    });
    const data = await res.json();
    setUsername(data.user.username);
    setPremium(data.user.premium);
  }

  function sendMessage() {
    if (!text.trim()) return;
    socket.emit("send-message", { from: username, to: peer, text });
    setText("");
  }

  async function upgrade() {
    const res = await fetch(`${API}/monetize/upgrade`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const data = await res.json();
    setPremium(data.user.premium);
  }

  if (!username) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h1>Mini Social Messaging App</h1>
        <input
          value={inputName}
          onChange={e => setInputName(e.target.value)}
          placeholder="Enter username"
        />
        <button onClick={login}>Login</button>
        <p>Open another browser tab and log in as another user.</p>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 20, padding: 20, fontFamily: "sans-serif" }}>
      <div>
        <h2>
          Logged in as {username} {premium ? "⭐ Premium" : ""}
        </h2>

        <div style={{ marginBottom: 12 }}>
          <label>Chat with: </label>
          <input value={peer} onChange={e => setPeer(e.target.value)} />
          {!premium && (
            <button onClick={upgrade} style={{ marginLeft: 10 }}>
              Upgrade to Premium
            </button>
          )}
        </div>

        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10, marginBottom: 10 }}>
          {messages.map((m, i) => (
            <div key={i} style={{ margin: "8px 0" }}>
              <strong>{m.from}:</strong> {m.text}
            </div>
          ))}
        </div>

        <div>
          <input
            value={text}
            onChange={e => setText(e.target.value)}
            placeholder="Type message"
            style={{ width: "70%" }}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>

      <div>
        <h3>Notifications</h3>
        <div style={{ border: "1px solid #ccc", padding: 10 }}>
          {notifications.map((n, i) => (
            <div key={i} style={{ marginBottom: 8 }}>
              <strong>{n.type}:</strong> {n.message}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
