## 3. `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const PORT = 3000;
const JWT_SECRET = "replace-this-with-a-secret";

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const db = new sqlite3.Database("./app.db");

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER NOT NULL,
      receiver_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: "Missing token" });

  const token = authHeader.split(" ")[1];
  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function getUserByUsername(username) {
  return new Promise((resolve, reject) => {
    db.get("SELECT * FROM users WHERE username = ?", [username], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

function getUserById(id) {
  return new Promise((resolve, reject) => {
    db.get("SELECT * FROM users WHERE id = ?", [id], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

const onlineUsers = new Map(); // userId -> socket.id

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  try {
    const existing = await getUserByUsername(username);
    if (existing) return res.status(400).json({ error: "User already exists" });

    const password_hash = await bcrypt.hash(password, 10);
    db.run(
      "INSERT INTO users (username, password_hash) VALUES (?, ?)",
      [username, password_hash],
      function (err) {
        if (err) return res.status(500).json({ error: "DB error" });
        res.json({ success: true, userId: this.lastID });
      }
    );
  } catch (e) {
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  try {
    const user = await getUserByUsername(username);
    if (!user) return res.status(401).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.password_hash);
    if (!ok) return res.status(401).json({ error: "Invalid credentials" });

    const token = jwt.sign(
      { id: user.id, username: user.username, premium: user.premium },
      JWT_SECRET
    );

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        premium: !!user.premium
      }
    });
  } catch {
    res.status(500).json({ error: "Server error" });
  }
});

app.get("/api/users", authMiddleware, (req, res) => {
  db.all(
    "SELECT id, username, premium FROM users WHERE id != ?",
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.get("/api/messages/:userId", authMiddleware, (req, res) => {
  const otherUserId = parseInt(req.params.userId, 10);

  db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
    `,
    [req.user.id, otherUserId, otherUserId, req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  const sender = await getUserById(req.user.id);
  if (!sender) return res.status(404).json({ error: "Sender not found" });

  // Monetization rule:
  // Free users can only send messages up to 100 chars.
  // Premium users can send unlimited length.
  if (!sender.premium && content.length > 100) {
    return res.status(402).json({
      error: "Upgrade to premium to send messages longer than 100 characters"
    });
  }

  db.run(
    "INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)",
    [req.user.id, receiverId, content],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      const message = {
        id: this.lastID,
        sender_id: req.user.id,
        receiver_id: receiverId,
        content,
        created_at: new Date().toISOString()
      };

      const receiverSocketId = onlineUsers.get(String(receiverId));
      if (receiverSocketId) {
        io.to(receiverSocketId).emit("new_message", message);
        io.to(receiverSocketId).emit("notification", {
          type: "message",
          text: `New message from ${req.user.username}`
        });
      }

      res.json({ success: true, message });
    }
  );
});

// Fake purchase endpoint for demo purposes
app.post("/api/purchase/premium", authMiddleware, (req, res) => {
  db.run(
    "UPDATE users SET premium = 1 WHERE id = ?",
    [req.user.id],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      const newToken = jwt.sign(
        { id: req.user.id, username: req.user.username, premium: 1 },
        JWT_SECRET
      );

      const socketId = onlineUsers.get(String(req.user.id));
      if (socketId) {
        io.to(socketId).emit("notification", {
          type: "premium",
          text: "Premium unlocked successfully"
        });
      }

      res.json({ success: true, premium: true, token: newToken });
    }
  );
});

io.on("connection", (socket) => {
  socket.on("authenticate", (token) => {
    try {
      const user = jwt.verify(token, JWT_SECRET);
      socket.user = user;
      onlineUsers.set(String(user.id), socket.id);
      socket.emit("notification", {
        type: "system",
        text: `Connected as ${user.username}`
      });
    } catch {
      socket.emit("notification", {
        type: "error",
        text: "Socket authentication failed"
      });
    }
  });

  socket.on("disconnect", () => {
    if (socket.user) {
      onlineUsers.delete(String(socket.user.id));
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

