        const receiverId = parseInt(document.getElementById("userList").value, 10);
        const content = document.getElementById("messageInput").value;

        const res = await fetch("/api/messages", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`
          },
          body: JSON.stringify({ receiverId, content })
        });

        const data = await res.json();
        if (data.error) return alert(data.error);

        renderMessage(data.message);
        document.getElementById("messageInput").value = "";
      }

      async function buyPremium() {
        const res = await fetch("/api/purchase/premium", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`
          }
        });

        const data = await res.json();
        if (data.error) return alert(data.error);

        token = data.token;
        currentUser.premium = true;
        localStorage.setItem("token", token);
        localStorage.setItem("user", JSON.stringify(currentUser));
        renderMe();
        logNotification("Premium activated");
        loadUsers();
      }

      function connectSocket() {
        if (socket) socket.disconnect();

        socket = io();
        socket.on("connect", () => {
          socket.emit("authenticate", token);
        });

        socket.on("notification", (payload) => {
          logNotification(payload.text);
        });

        socket.on("new_message", (message) => {
          const selectedUserId = parseInt(document.getElementById("userList").value, 10);
          if (
            selectedUserId &&
            (message.sender_id === selectedUserId || message.receiver_id === selectedUserId)
          ) {
            renderMessage(message);
          }
          logNotification("You received a new message");
        });
      }

      renderMe();
      if (token && currentUser) {
        connectSocket();
        loadUsers();
      }
    </script>
