<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, chart updates, and form-driven event handling.</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="success">Start Stream</button>
        <button id="stopBtn">Stop Stream</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>
    </div>

    <div class="stats">
      <div class="stat-card">
        <div class="stat-label">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="avgValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Events Submitted</div>
        <div class="stat-value" id="eventCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Real-Time Data Visualization</h2>
        <div class="chart-wrap">
          <canvas id="chartCanvas" width="800" height="320"></canvas>
        </div>
        <div class="legend">
          <span><i class="dot blue"></i> Live metric</span>
          <span><i class="dot orange"></i> Average line</span>
        </div>
        <div class="footer-note">
          Simulated data updates every second. Use the controls to start, stop, or reset the stream.
        </div>
      </div>

      <div class="panel">
        <h2>Submit Event</h2>
        <form id="eventForm" novalidate>
          <div class="field">
            <label for="title">Event Title</label>
            <input id="title" name="title" type="text" placeholder="e.g. Sensor alert" />
            <div class="error" id="titleError"></div>
          </div>

          <div class="field">
            <label for="category">Category</label>
            <select id="category" name="category">
              <option value="">Select a category</option>
              <option value="Info">Info</option>
              <option value="Warning">Warning</option>
              <option value="Critical">Critical</option>
            </select>
            <div class="error" id="categoryError"></div>
          </div>

          <div class="field">
            <label for="threshold">Threshold</label>
            <input id="threshold" name="threshold" type="number" min="0" max="1000" placeholder="e.g. 75" />
            <div class="error" id="thresholdError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional details..."></textarea>
            <div class="error" id="notesError"></div>
          </div>

          <button type="submit" class="primary">Submit Event</button>
          <div class="success-message" id="formSuccess"></div>
        </form>

        <h2 style="margin-top: 24px;">Activity Log</h2>
        <div class="log" id="activityLog"></div>
      </div>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById("chartCanvas");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const avgValueEl = document.getElementById("avgValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const eventForm = document.getElementById("eventForm");
    const activityLog = document.getElementById("activityLog");
    const formSuccess = document.getElementById("formSuccess");

    const titleInput = document.getElementById("title");
    const categoryInput = document.getElementById("category");
    const thresholdInput = document.getElementById("threshold");
    const notesInput = document.getElementById("notes");

    const titleError = document.getElementById("titleError");
    const categoryError = document.getElementById("categoryError");
    const thresholdError = document.getElementById("thresholdError");
    const notesError = document.getElementById("notesError");

    let data = [];
    let timer = null;
    let eventCount = 0;
    const maxPoints = 30;

    function randomMetric() {
      const base = 50;
      const variance = Math.random() * 40 - 20;
      const wave = Math.sin(Date.now() / 3000) * 15;
      return Math.max(0, Math.round(base + variance + wave));
    }

    function addDataPoint(value) {
      const point = {
        time: new Date(),
        value
      };
      data.push(point);
      if (data.length > maxPoints) data.shift();
      updateStats();
      drawChart();
    }

    function updateStats() {
      if (data.length === 0) {
        currentValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(0);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
      eventCountEl.textContent = eventCount;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      const gridRows = 5;
      const gridCols = 6;

      for (let i = 0; i <= gridRows; i++) {
        const y = (height / gridRows) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= gridCols; i++) {
        const x = (width / gridCols) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const minVal = Math.min(...values, 0);
      const maxVal = Math.max(...values, 100);
      const padding = 30;

      const xStep = (width - padding * 2) / (maxPoints - 1 || 1);
      const yScale = (height - padding * 2) / (maxVal - minVal || 1);

      function getX(index) {
        return padding + index * xStep;
      }

      function getY(value) {
        return height - padding - (value - minVal) * yScale;
      }

      // Average line
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      ctx.beginPath();
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([6, 6]);
      ctx.moveTo(padding, getY(avg));
      ctx.lineTo(width - padding, getY(avg));
      ctx.stroke();
      ctx.setLineDash([]);

      // Area fill
      ctx.beginPath();
      ctx.moveTo(getX(0), getY(values[0]));
      values.forEach((v, i) => {
        ctx.lineTo(getX(i), getY(v));
      });
      ctx.lineTo(getX(values.length - 1), height - padding);
      ctx.lineTo(getX(0), height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 3;
      values.forEach((v, i) => {
        const x = getX(i);
        const y = getY(v);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // Points
      values.forEach((v, i) => {
        const x = getX(i);
        const y = getY(v);
        ctx.beginPath();
        ctx.fillStyle = "#93c5fd";
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "rgba(229, 231, 235, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText(`Max: ${maxVal}`, 10, 16);
      ctx.fillText(`Min: ${minVal}`, 10, height - 10);
      ctx.fillText(`Avg: ${avg.toFixed(1)}`, width - 80, 16);
    }

    function startStream() {
      if (timer) return;
      addLog("Data stream started.");
      timer = setInterval(() => {
        const value = randomMetric();
        addDataPoint(value);
      }, 1000);
    }

    function stopStream() {
      if (!timer) return;
      clearInterval(timer);
      timer = null;
      addLog("Data stream stopped.");
    }

    function resetDashboard() {
      stopStream();
      data = [];
      eventCount = 0;
      updateStats();
      drawChart();
      activityLog.innerHTML = "";
      formSuccess.textContent = "";
      eventCountEl.textContent = "0";
      addLog("Dashboard reset.");
    }

    function addLog(message, category = "Info") {
      const item = document.createElement("div");
      item.className = "log-item";

      let borderColor = "#3b82f6";
      if (category === "Warning") borderColor = "#f59e0b";
      if (category === "Critical") borderColor = "#ef4444";

      item.style.borderLeftColor = borderColor;

      const time = new Date().toLocaleTimeString();
      item.innerHTML = `
        <div class="log-time">${time} • ${category}</div>
        <div>${escapeHtml(message)}</div>
      `;

      activityLog.prepend(item);
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function clearErrors() {
      titleError.textContent = "";
      categoryError.textContent = "";
      thresholdError.textContent = "";
      notesError.textContent = "";
      formSuccess.textContent = "";
    }

    function validateForm() {
      clearErrors();
      let valid = true;

      const title = titleInput.value.trim();
      const category = categoryInput.value;
      const threshold = thresholdInput.value.trim();
      const notes = notesInput.value.trim();

      if (!title) {
        titleError.textContent = "Title is required.";
        valid = false;
      } else if (title.length < 3) {
        titleError.textContent = "Title must be at least 3 characters.";
        valid = false;
      }

      if (!category) {
        categoryError.textContent = "Please select a category.";
        valid = false;
      }

      if (!threshold) {
        thresholdError.textContent = "Threshold is required.";
        valid = false;
      } else if (isNaN(Number(threshold)) || Number(threshold) < 0 || Number(threshold) > 1000) {
        thresholdError.textContent = "Threshold must be a number between 0 and 1000.";
        valid = false;
      }

      if (notes.length > 200) {
        notesError.textContent = "Notes must be 200 characters or fewer.";
        valid = false;
      }

      return valid;
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      const payload = {
        title: titleInput.value.trim(),
        category: categoryInput.value,
        threshold: Number(thresholdInput.value),
        notes: notesInput.value.trim()
      };

      eventCount++;
      eventCountEl.textContent = eventCount;

      addLog(
        `Event submitted: "${payload.title}" with threshold ${payload.threshold}. ${payload.notes ? "Notes: " + payload.notes : ""}`,
        payload.category
      );

      formSuccess.textContent = "Event submitted successfully.";
      eventForm.reset();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    // Initial render
    updateStats();
    drawChart();
    addLog("Dashboard initialized.");
    startStream();
  </script>
</body>
</html>
```

