    .delta.up {
      color: var(--accent);
    }

    .delta.down {
      color: var(--danger);
    }

    .chart-wrap {
      position: relative;
      width: 100%;
      height: 340px;
      background: linear-gradient(180deg, rgba(56,189,248,0.05), rgba(34,197,94,0.03));
      border-radius: 14px;
      overflow: hidden;
      border: 1px solid var(--border);
    }

    canvas {
      width: 100%;
      height: 100%;
      display: block;
    }

    .side-stack {
      display: grid;
      gap: 20px;
    }

    form {
      display: grid;
      gap: 12px;
    }

    .field {
      display: grid;
      gap: 6px;
    }

    label {
      font-size: 0.92rem;
      color: var(--muted);
    }

    input, select, textarea {
      width: 100%;
      padding: 11px 12px;
      border-radius: 10px;
      border: 1px solid var(--border);
      background: #0b1220;
      color: var(--text);
      outline: none;
    }

    input:focus, select:focus, textarea:focus {
      border-color: var(--accent-2);
      box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15);
    }

    .error {
      color: #fca5a5;
      font-size: 0.85rem;
      min-height: 1em;
    }

    .success {
      color: #86efac;
      font-size: 0.9rem;
      margin-top: 4px;
      min-height: 1em;
    }

    .log {
      max-height: 260px;
      overflow: auto;
      display: grid;
      gap: 10px;
    }

    .log-item {
      background: #0b1220;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 10px 12px;
      font-size: 0.92rem;
    }

    .log-item .time {
      color: var(--muted);
      font-size: 0.8rem;
      margin-bottom: 4px;
    }

    .status-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
      margin-top: 12px;
      flex-wrap: wrap;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: #0b1220;
      border: 1px solid var(--border);
      padding: 8px 10px;
      border-radius: 999px;
    }

    .dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--accent);
      box-shadow: 0 0 10px rgba(34,197,94,0.8);
    }

    .dot.paused {
      background: var(--warning);
      box-shadow: 0 0 10px rgba(245,158,11,0.8);
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, chart updates, and form-driven event handling.</p>
      </div>
      <div class="controls">
        <button id="toggleLiveBtn">Pause Live Data</button>
        <button id="addSpikeBtn" class="secondary">Add Traffic Spike</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>
    </div>

    <div class="kpis">
      <div class="kpi">
        <div class="label">Active Users</div>
        <div class="value" id="activeUsers">0</div>
        <div class="delta up" id="activeUsersDelta">+0%</div>
      </div>
      <div class="kpi">
        <div class="label">Requests / min</div>
        <div class="value" id="requestsPerMin">0</div>
        <div class="delta up" id="requestsDelta">+0%</div>
      </div>
      <div class="kpi">
        <div class="label">Error Rate</div>
        <div class="value" id="errorRate">0%</div>
        <div class="delta down" id="errorDelta">0%</div>
      </div>
      <div class="kpi">
        <div class="label">Avg Response</div>
        <div class="value" id="responseTime">0 ms</div>
        <div class="delta up" id="responseDelta">+0%</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="chart"></canvas>
        </div>
        <div class="status-row">
          <div class="badge">
            <span class="dot" id="liveDot"></span>
            <span id="liveStatus">Streaming live data</span>
          </div>
          <div>Points: <strong id="pointCount">0</strong></div>
          <div>Last update: <strong id="lastUpdate">--:--:--</strong></div>
        </div>
      </div>

      <div class="side-stack">
        <div class="panel">
          <h2>Create Event</h2>
          <form id="eventForm" novalidate>
            <div class="field">
              <label for="eventName">Event Name</label>
              <input id="eventName" name="eventName" type="text" placeholder="e.g. Deploy Release" />
              <div class="error" id="eventNameError"></div>
            </div>

            <div class="field">
              <label for="severity">Severity</label>
              <select id="severity" name="severity">
                <option value="">Select severity</option>
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="critical">Critical</option>
              </select>
              <div class="error" id="severityError"></div>
            </div>

            <div class="field">
              <label for="impact">Traffic Impact (%)</label>
              <input id="impact" name="impact" type="number" min="-100" max="300" placeholder="e.g. 25" />
              <div class="error" id="impactError"></div>
            </div>

            <div class="field">
              <label for="notes">Notes</label>
              <textarea id="notes" name="notes" rows="4" placeholder="Optional details..."></textarea>
              <div class="error" id="notesError"></div>
            </div>

            <button type="submit">Submit Event</button>
            <div class="success" id="formSuccess"></div>
          </form>
        </div>

        <div class="panel">
          <h2>Event Log</h2>
          <div class="log" id="eventLog"></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    const state = {
      live: true,
      maxPoints: 50,
      trafficData: [],
      labels: [],
      metrics: {
        activeUsers: 1200,
        requestsPerMin: 8500,
        errorRate: 1.2,
        responseTime: 240
      },
      previousMetrics: {}
    };

    const els = {
      chart: document.getElementById('chart'),
      activeUsers: document.getElementById('activeUsers'),
      requestsPerMin: document.getElementById('requestsPerMin'),
      errorRate: document.getElementById('errorRate'),
      responseTime: document.getElementById('responseTime'),
      activeUsersDelta: document.getElementById('activeUsersDelta'),
      requestsDelta: document.getElementById('requestsDelta'),
      errorDelta: document.getElementById('errorDelta'),
      responseDelta: document.getElementById('responseDelta'),
      pointCount: document.getElementById('pointCount'),
      lastUpdate: document.getElementById('lastUpdate'),
      liveDot: document.getElementById('liveDot'),
      liveStatus: document.getElementById('liveStatus'),
      toggleLiveBtn: document.getElementById('toggleLiveBtn'),
      addSpikeBtn: document.getElementById('addSpikeBtn'),
      resetBtn: document.getElementById('resetBtn'),
      eventForm: document.getElementById('eventForm'),
      eventLog: document.getElementById('eventLog'),
      formSuccess: document.getElementById('formSuccess'),
      eventName: document.getElementById('eventName'),
      severity: document.getElementById('severity'),
      impact: document.getElementById('impact'),
      notes: document.getElementById('notes')
    };

    const ctx = els.chart.getContext('2d');

    function formatNumber(num) {
      return new Intl.NumberFormat().format(Math.round(num));
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function clamp(value, min, max) {
      return Math.min(max, Math.max(min, value));
    }

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function seedData() {
      state.trafficData = [];
      state.labels = [];
      let base = 120;

      for (let i = 0; i < state.maxPoints; i++) {
        base += randomBetween(-8, 8);
        base = clamp(base, 40, 220);
        state.trafficData.push(base);
        state.labels.push(i);
      }
    }

    function updateMetricsFromTraffic(latest) {
      state.previousMetrics = { ...state.metrics };

      state.metrics.activeUsers = clamp(
        state.metrics.activeUsers + randomBetween(-40, 60) + latest * 0.2,
        300,
        10000
      );

      state.metrics.requestsPerMin = clamp(
        latest * 70 + randomBetween(-300, 300),
        1000,
        25000
      );

      state.metrics.errorRate = clamp(
        state.metrics.errorRate + randomBetween(-0.15, 0.15),
        0.1,
        8
      );

      state.metrics.responseTime = clamp(
        120 + (220 - latest) * 1.2 + randomBetween(-20, 20),
        80,
        1200
      );
    }

    function percentDelta(current, previous) {
      if (!previous || previous === 0) return 0;
      return ((current - previous) / previous) * 100;
    }

    function setDelta(el, delta, invert = false, suffix = '%') {
      const positive = invert ? delta < 0 : delta >= 0;
      el.className = 'delta ' + (positive ? 'up' : 'down');
      const sign = delta >= 0 ? '+' : '';
      el.textContent = `${sign}${delta.toFixed(1)}${suffix}`;
    }

    function renderKPIs() {
      const m = state.metrics;
      const p = state.previousMetrics;

      els.activeUsers.textContent = formatNumber(m.activeUsers);
      els.requestsPerMin.textContent = formatNumber(m.requestsPerMin);
      els.errorRate.textContent = `${m.errorRate.toFixed(2)}%`;
      els.responseTime.textContent = `${Math.round(m.responseTime)} ms`;

      setDelta(els.activeUsersDelta, percentDelta(m.activeUsers, p.activeUsers));
      setDelta(els.requestsDelta, percentDelta(m.requestsPerMin, p.requestsPerMin));
      setDelta(els.errorDelta, percentDelta(m.errorRate, p.errorRate), true);
      setDelta(els.responseDelta, percentDelta(m.responseTime, p.responseTime), true);

      els.pointCount.textContent = state.trafficData.length;
      els.lastUpdate.textContent = formatTime();
    }

    function resizeCanvas() {
      const rect = els.chart.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      els.chart.width = rect.width * dpr;
      els.chart.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function drawChart() {
      const canvas = els.chart;
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      const padding = { top: 20, right: 20, bottom: 30, left: 40 };
      const chartW = width - padding.left - padding.right;
      const chartH = height - padding.top - padding.bottom;

      const data = state.trafficData;
      const min = Math.min(...data, 0);
      const max = Math.max(...data, 1);
      const range = max - min || 1;

      // Grid
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let i = 0; i <= 4; i++) {
        const y = padding.top + (chartH / 4) * i;
        ctx.moveTo(padding.left, y);
        ctx.lineTo(width - padding.right, y);
      }
      ctx.stroke();

      // Y labels
      ctx.fillStyle = 'rgba(229,231,235,0.7)';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      for (let i = 0; i <= 4; i++) {
        const value = max - (range / 4) * i;
        const y = padding.top + (chartH / 4) * i + 4;
        ctx.fillText(Math.round(value), padding.left - 8, y);
      }

      // Line path
      const points = data.map((value, i) => {
        const x = padding.left + (i / (data.length - 1)) * chartW;
        const y = padding.top + chartH - ((value - min) / range) * chartH;
        return { x, y, value };
      });

      // Area fill
      const gradient = ctx.createLinearGradient(0, padding.top, 0, height);
      gradient.addColorStop(0, 'rgba(56,189,248,0.35)');
      gradient.addColorStop(1, 'rgba(56,189,248,0.02)');

      ctx.beginPath();
      points.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.lineTo(points[points.length - 1].x, height - padding.bottom);
      ctx.lineTo(points[0].x, height - padding.bottom);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Stroke line
      ctx.beginPath();
      points.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Latest point
      const last = points[points.length - 1];
      if (last) {
        ctx.beginPath();
        ctx.arc(last.x, last.y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
        ctx.shadowColor = 'rgba(34,197,94,0.8)';
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(last.x, last.y, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
      }

      // X labels
      ctx.fillStyle = 'rgba(229,231,235,0.6)';
      ctx.textAlign = 'center';
      const steps = 5;
      for (let i = 0; i < steps; i++) {
        const idx = Math.floor((data.length - 1) * (i / (steps - 1)));
        const x = padding.left + (idx / (data.length - 1)) * chartW;
        ctx.fillText(`${idx + 1}`, x, height - 8);
      }
    }

    function tick() {
      if (!state.live) return;

      const last = state.trafficData[state.trafficData.length - 1] || 120;
      let next = last + randomBetween(-12, 12);
      next = clamp(next, 30, 240);

      state.trafficData.push(next);
      if (state.trafficData.length > state.maxPoints) {
        state.trafficData.shift();
      }

      updateMetricsFromTraffic(next);
      renderKPIs();
      drawChart();
    }

    function addLog(message, severity = 'info') {
      const item = document.createElement('div');
      item.className = 'log-item';

      const colorMap = {
        info: '#38bdf8',
        warning: '#f59e0b',
        critical: '#ef4444'
      };

      item.innerHTML = `
        <div class="time">${formatTime()}</div>
        <div><strong style="color:${colorMap[severity] || '#38bdf8'}">${severity.toUpperCase()}</strong> — ${message}</div>
      `;

      els.eventLog.prepend(item);

      while (els.eventLog.children.length > 12) {
        els.eventLog.removeChild(els.eventLog.lastChild);
      }
    }

    function clearErrors() {
      document.querySelectorAll('.error').forEach(el => el.textContent = '');
      els.formSuccess.textContent = '';
    }

    function validateForm(data) {
      const errors = {};

      if (!data.eventName.trim()) {
        errors.eventName = 'Event name is required.';
      } else if (data.eventName.trim().length < 3) {
        errors.eventName = 'Event name must be at least 3 characters.';
      }

      if (!data.severity) {
        errors.severity = 'Please select a severity.';
      }

      if (data.impact === '') {
        errors.impact = 'Impact is required.';
      } else if (isNaN(Number(data.impact))) {
        errors.impact = 'Impact must be a number.';
      } else if (Number(data.impact) < -100 || Number(data.impact) > 300) {
        errors.impact = 'Impact must be between -100 and 300.';
      }

      if (data.notes.length > 200) {
        errors.notes = 'Notes must be 200 characters or fewer.';
      }

      return errors;
    }

    function showErrors(errors) {
      document.getElementById('eventNameError').textContent = errors.eventName || '';
      document.getElementById('severityError').textContent = errors.severity || '';
      document.getElementById('impactError').textContent = errors.impact || '';
      document.getElementById('notesError').textContent = errors.notes || '';
    }

    function applyImpact(impact, severity) {
      const factor = Number(impact);
      const latest = state.trafficData[state.trafficData.length - 1] || 100;
      const boosted = clamp(latest * (1 + factor / 100), 20, 300);
      state.trafficData[state.trafficData.length - 1] = boosted;

      state.previousMetrics = { ...state.metrics };
      state.metrics.requestsPerMin = clamp(state.metrics.requestsPerMin * (1 + factor / 100), 500, 40000);
      state.metrics.activeUsers = clamp(state.metrics.activeUsers * (1 + factor / 200), 100, 20000);

      if (severity === 'critical') {
        state.metrics.errorRate = clamp(state.metrics.errorRate + 1.5, 0.1, 15);
        state.metrics.responseTime = clamp(state.metrics.responseTime + 120, 80, 2000);
      } else if (severity === 'warning') {
        state.metrics.errorRate = clamp(state.metrics.errorRate + 0.5, 0.1, 15);
        state.metrics.responseTime = clamp(state.metrics.responseTime + 60, 80, 2000);
      } else {
        state.metrics.errorRate = clamp(state.metrics.errorRate + 0.1, 0.1, 15);
      }

      renderKPIs();
      drawChart();
    }

    els.eventForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const formData = {
        eventName: els.eventName.value,
        severity: els.severity.value,
        impact: els.impact.value,
        notes: els.notes.value.trim()
      };

      const errors = validateForm(formData);

      if (Object.keys(errors).length > 0) {
        showErrors(errors);
        return;
      }

      applyImpact(formData.impact, formData.severity);

      const notesText = formData.notes ? ` Notes: ${formData.notes}` : '';
      addLog(
        `${formData.eventName} submitted with ${formData.impact}% impact.${notesText}`,
        formData.severity
      );

      els.formSuccess.textContent = 'Event submitted successfully.';
      els.eventForm.reset();
    });

    els.toggleLiveBtn.addEventListener('click', () => {
      state.live = !state.live;
      els.toggleLiveBtn.textContent = state.live ? 'Pause Live Data' : 'Resume Live Data';
      els.liveStatus.textContent = state.live ? 'Streaming live data' : 'Live stream paused';
      els.liveDot.classList.toggle('paused', !state.live);
      addLog(state.live ? 'Live updates resumed.' : 'Live updates paused.', 'info');
    });

    els.addSpikeBtn.addEventListener('click', () => {
      const last = state.trafficData[state.trafficData.length - 1] || 100;
      const spike = clamp(last + randomBetween(40, 90), 20, 300);
      state.trafficData[state.trafficData.length - 1] = spike;
      updateMetricsFromTraffic(spike);
      renderKPIs();
      drawChart();
      addLog('Manual traffic spike injected.', 'warning');
    });

    els.resetBtn.addEventListener('click', () => {
      state.metrics = {
        activeUsers: 1200,
        requestsPerMin: 8500,
        errorRate: 1.2,
        responseTime: 240
      };
      state.previousMetrics = { ...state.metrics };
      seedData();
      renderKPIs();
      drawChart();
      els.eventLog.innerHTML = '';
      clearErrors();
      els.eventForm.reset();
      addLog('Dashboard reset to initial state.', 'info');
    });

    window.addEventListener('resize', resizeCanvas);

    // Init
    seedData();
    state.previousMetrics = { ...state.metrics };
    renderKPIs();
    resizeCanvas();
    addLog('Dashboard initialized.', 'info');

    setInterval(tick, 1000);
  </script>
</body>
</html>
```

## What this does

- Simulates live traffic data every second
- Draws a real-time line chart on a canvas
- Updates KPI cards based on the latest data
- Lets users submit events through a form
- Validates form inputs before submission
- Applies event impact to the dashboard metrics
- Maintains an event log
- Supports pause/resume and reset controls

