  <script>
    const chartCanvas = document.getElementById("chart");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");
    const logList = document.getElementById("logList");
    const statusText = document.getElementById("statusText");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");
    const injectBtn = document.getElementById("injectBtn");

    const eventForm = document.getElementById("eventForm");
    const settingsForm = document.getElementById("settingsForm");

    let data = [];
    let labels = [];
    let timer = null;
    let updateInterval = 1000;
    let maxPoints = 40;
    let eventCount = 0;
    let peakValue = 0;

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function addLog(message) {
      const li = document.createElement("li");
      li.className = "log-item";
      li.innerHTML = `
        <div class="log-time">${nowTime()}</div>
        <div>${message}</div>
      `;
      logList.prepend(li);

      while (logList.children.length > 20) {
        logList.removeChild(logList.lastChild);
      }
    }

    function generateValue() {
      const base = 50 + Math.sin(Date.now() / 3000) * 20;
      const noise = Math.random() * 15 - 7.5;
      return Math.max(0, Math.round(base + noise));
    }

    function pushDataPoint(value = generateValue()) {
      const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      data.push(value);
      labels.push(timestamp);

      if (data.length > maxPoints) {
        data.shift();
        labels.shift();
      }

      updateStats();
      drawChart();
    }

    function updateStats() {
      const current = data[data.length - 1] ?? 0;
      const avg = data.length
        ? (data.reduce((sum, v) => sum + v, 0) / data.length).toFixed(1)
        : 0;

      peakValue = data.length ? Math.max(...data, peakValue) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peakValue;
      eventCountEl.textContent = eventCount;
    }

    function drawChart() {
      const w = chartCanvas.width;
      const h = chartCanvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const maxVal = Math.max(...data, 100);
      const minVal = Math.min(...data, 0);
      const range = Math.max(1, maxVal - minVal);

      const padding = 30;
      const innerW = w - padding * 2;
      const innerH = h - padding * 2;

      // Area fill
      ctx.beginPath();
      data.forEach((value, i) => {
        const x = padding + (i / (data.length - 1)) * innerW;
        const y = h - padding - ((value - minVal) / range) * innerH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + innerW, h - padding);
      ctx.lineTo(padding, h - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((value, i) => {
        const x = padding + (i / (data.length - 1)) * innerW;
        const y = h - padding - ((value - minVal) / range) * innerH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((value, i) => {
        const x = padding + (i / (data.length - 1)) * innerW;
        const y = h - padding - ((value - minVal) / range) * innerH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = "rgba(229, 231, 235, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText(String(maxVal), 6, padding);
      ctx.fillText(String(Math.round((maxVal + minVal) / 2)), 6, h / 2);
      ctx.fillText(String(minVal), 6, h - padding);
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(() => {
        pushDataPoint();
      }, updateInterval);
      statusText.textContent = "Streaming Live";
      addLog("Data stream started.");
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
      statusText.textContent = "Paused";
      addLog("Data stream paused.");
    }

    function resetDashboard() {
      data = [];
      labels = [];
      peakValue = 0;
      updateStats();
      drawChart();
      addLog("Dashboard reset.");
    }

    function injectSpike() {
      const spike = Math.round(120 + Math.random() * 80);
      pushDataPoint(spike);
      addLog(`Manual spike injected: value ${spike}.`);
    }

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);
    injectBtn.addEventListener("click", injectSpike);

    function clearErrors() {
      document.getElementById("titleError").textContent = "";
      document.getElementById("severityError").textContent = "";
      document.getElementById("thresholdError").textContent = "";
      document.getElementById("notesError").textContent = "";
      document.getElementById("formSuccess").textContent = "";
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const title = document.getElementById("title").value.trim();
      const severity = document.getElementById("severity").value;
      const threshold = document.getElementById("threshold").value.trim();
      const notes = document.getElementById("notes").value.trim();

      let valid = true;

      if (!title || title.length < 3) {
        document.getElementById("titleError").textContent = "Title must be at least 3 characters.";
        valid = false;
      }

      if (!severity) {
        document.getElementById("severityError").textContent = "Please select a severity.";
        valid = false;
      }

      if (!threshold || Number(threshold) < 0) {
        document.getElementById("thresholdError").textContent = "Threshold must be a valid non-negative number.";
        valid = false;
      }

      if (notes.length > 200) {
        document.getElementById("notesError").textContent = "Notes must be 200 characters or fewer.";
        valid = false;
      }

      if (!valid) return;

      eventCount++;
      updateStats();

      addLog(
        `New event submitted: <strong>${title}</strong> | Severity: <strong>${severity}</strong> | Threshold: <strong>${threshold}</strong>${notes ? ` | Notes: ${notes}` : ""}`
      );

      document.getElementById("formSuccess").textContent = "Event submitted successfully.";
      eventForm.reset();
    });

    settingsForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const intervalValue = Number(document.getElementById("interval").value);
      const maxPointsValue = Number(document.getElementById("maxPoints").value);

      if (intervalValue >= 100) {
        updateInterval = intervalValue;
      }

      if (maxPointsValue >= 10 && maxPointsValue <= 500) {
        maxPoints = maxPointsValue;
      }

      if (timer) {
        clearInterval(timer);
        timer = null;
        startStream();
      }

      addLog(`Settings updated: interval ${updateInterval}ms, max points ${maxPoints}.`);
    });

    // Seed initial data
    for (let i = 0; i < 12; i++) {
      pushDataPoint(generateValue());
    }

    drawChart();
    startStream();
  </script>
</body>
</html>
```

## What this does

- Simulates real-time incoming data with `setInterval`
- Draws a live line chart using the HTML5 Canvas API
- Updates summary cards:
  - current value
  - average
  - peak
  - event count
- Handles form submission with validation
- Logs user actions and system events
- Lets users:
  - start stream
  - stop stream
  - reset dashboard
  - inject a spike
  - change update interval and max data points

