              <div class="error" id="notesError"></div>
            </div>

            <button type="submit" class="btn-success">Submit Record</button>
            <div class="success-message" id="formSuccess"></div>
          </form>
        </div>
      </div>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById("chart");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const recordCountEl = document.getElementById("recordCount");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const form = document.getElementById("recordForm");
    const recordsTableBody = document.getElementById("recordsTableBody");
    const formSuccess = document.getElementById("formSuccess");

    let liveData = [];
    let maxPoints = 40;
    let intervalId = null;
    let records = [];

    function randomValue() {
      return Math.floor(30 + Math.random() * 60);
    }

    function addLivePoint() {
      const value = randomValue();
      const timestamp = new Date().toLocaleTimeString();

      liveData.push({ value, timestamp });
      if (liveData.length > maxPoints) {
        liveData.shift();
      }

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (liveData.length === 0) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        return;
      }

      const values = liveData.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      const padding = 40;

      ctx.clearRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i < 5; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      // Axes
      ctx.strokeStyle = "rgba(148, 163, 184, 0.35)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, height - padding);
      ctx.lineTo(width - padding, height - padding);
      ctx.stroke();

      if (liveData.length < 2) return;

      const values = liveData.map(d => d.value);
      const minVal = 0;
      const maxVal = 100;

      const xStep = (width - padding * 2) / (maxPoints - 1);

      // Area fill
      ctx.beginPath();
      liveData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - minVal) / (maxVal - minVal)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + (liveData.length - 1) * xStep, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      liveData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - minVal) / (maxVal - minVal)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      liveData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - minVal) / (maxVal - minVal)) * (height - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "rgba(229, 231, 235, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText("100", 8, padding + 4);
      ctx.fillText("75", 14, padding + (height - padding * 2) * 0.25 + 4);
      ctx.fillText("50", 14, padding + (height - padding * 2) * 0.5 + 4);
      ctx.fillText("25", 14, padding + (height - padding * 2) * 0.75 + 4);
      ctx.fillText("0", 20, height - padding + 4);
    }

    function startFeed() {
      if (intervalId) return;
      intervalId = setInterval(addLivePoint, 1000);
    }

    function stopFeed() {
      clearInterval(intervalId);
      intervalId = null;
    }

    function resetData() {
      stopFeed();
      liveData = [];
      updateMetrics();
      drawChart();
    }

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ["nameError", "categoryError", "priorityError", "valueError", "notesError"].forEach(id => {
        setError(id, "");
      });
      formSuccess.textContent = "";
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.name.trim()) {
        setError("nameError", "Name is required.");
        valid = false;
      }

      if (!data.category) {
        setError("categoryError", "Category is required.");
        valid = false;
      }

      if (!data.priority) {
        setError("priorityError", "Priority is required.");
        valid = false;
      }

      const numericValue = Number(data.value);
      if (data.value === "" || Number.isNaN(numericValue)) {
        setError("valueError", "Value is required.");
        valid = false;
      } else if (numericValue < 0 || numericValue > 100) {
        setError("valueError", "Value must be between 0 and 100.");
        valid = false;
      }

      if (data.notes.length > 200) {
        setError("notesError", "Notes must be 200 characters or fewer.");
        valid = false;
      }

      return valid;
    }

    function priorityBadge(priority) {
      const cls =
        priority === "High" ? "badge-high" :
        priority === "Medium" ? "badge-medium" :
        "badge-low";
      return `<span class="badge ${cls}">${priority}</span>`;
    }

    function renderRecords() {
      recordsTableBody.innerHTML = records.map(record => `
        <tr>
          <td>${escapeHtml(record.name)}</td>
          <td>${escapeHtml(record.category)}</td>
          <td>${priorityBadge(record.priority)}</td>
          <td>${escapeHtml(String(record.value))}</td>
          <td>${escapeHtml(record.notes)}</td>
        </tr>
      `).join("");

      recordCountEl.textContent = records.length;
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = {
        name: form.name.value,
        category: form.category.value,
        priority: form.priority.value,
        value: form.value.value,
        notes: form.notes.value.trim()
      };

      if (!validateForm(formData)) return;

      records.unshift({
        ...formData,
        value: Number(formData.value)
      });

      renderRecords();
      form.reset();
      formSuccess.textContent = "Record submitted successfully.";
    });

    startBtn.addEventListener("click", startFeed);
    stopBtn.addEventListener("click", stopFeed);
    resetBtn.addEventListener("click", resetData);

    // Seed initial data
    for (let i = 0; i < 12; i++) {
      addLivePoint();
    }
    drawChart();
    renderRecords();
  </script>
</body>
</html>
```

## What this does
- Simulates real-time data every second
- Draws a live-updating line/area chart on a canvas
- Updates summary metrics:
  - current value
  - average
  - peak
  - record count
- Handles form validation
- Safely renders submitted records into a table

