  </div>

  <script>
    const chartCanvas = document.getElementById("chart");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const currentTrendEl = document.getElementById("currentTrend");
    const streamStatusEl = document.getElementById("streamStatus");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const form = document.getElementById("recordForm");
    const recordsTableBody = document.getElementById("recordsTableBody");
    const formSuccess = document.getElementById("formSuccess");

    const maxPoints = 40;
    let dataPoints = [];
    let labels = [];
    let intervalId = null;
    let peakValue = 0;
    let lastValue = null;

    function generateValue() {
      const base = 50;
      const variation = Math.random() * 40 - 20;
      const spike = Math.random() > 0.92 ? Math.random() * 35 : 0;
      return Math.max(5, Math.round(base + variation + spike));
    }

    function addDataPoint() {
      const value = generateValue();
      const time = new Date().toLocaleTimeString();

      dataPoints.push(value);
      labels.push(time);

      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
        labels.shift();
      }

      peakValue = Math.max(peakValue, value);
      updateMetrics(value);
      drawChart();
    }

    function updateMetrics(value) {
      const avg = dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length || 0;
      currentValueEl.textContent = value.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peakValue.toFixed(0);

      if (lastValue === null) {
        currentTrendEl.textContent = "Initial reading received";
      } else if (value > lastValue) {
        currentTrendEl.textContent = `Up by ${value - lastValue}`;
      } else if (value < lastValue) {
        currentTrendEl.textContent = `Down by ${lastValue - value}`;
      } else {
        currentTrendEl.textContent = "No change";
      }

      lastValue = value;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 8; i++) {
        const x = (width / 8) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      if (dataPoints.length < 2) return;

      const minVal = Math.min(...dataPoints, 0);
      const maxVal = Math.max(...dataPoints, 100);
      const padding = 30;
      const chartHeight = height - padding * 2;
      const chartWidth = width - padding * 2;

      const getX = (index) => padding + (index / (dataPoints.length - 1)) * chartWidth;
      const getY = (value) => {
        const normalized = (value - minVal) / (maxVal - minVal || 1);
        return height - padding - normalized * chartHeight;
      };

      // Area fill
      ctx.beginPath();
      ctx.moveTo(getX(0), getY(dataPoints[0]));
      dataPoints.forEach((value, index) => {
        ctx.lineTo(getX(index), getY(value));
      });
      ctx.lineTo(getX(dataPoints.length - 1), height - padding);
      ctx.lineTo(getX(0), height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(34, 197, 94, 0.05)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      ctx.moveTo(getX(0), getY(dataPoints[0]));
      dataPoints.forEach((value, index) => {
        ctx.lineTo(getX(index), getY(value));
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((value, index) => {
        ctx.beginPath();
        ctx.arc(getX(index), getY(value), 4, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.fillText(maxVal.toFixed(0), 6, padding);
      ctx.fillText(((maxVal + minVal) / 2).toFixed(0), 6, height / 2);
      ctx.fillText(minVal.toFixed(0), 6, height - padding);

      // Last X label
      ctx.fillText(labels[labels.length - 1] || "", width - 80, height - 8);
    }

    function startStream() {
      if (intervalId) return;
      streamStatusEl.textContent = "ON";
      streamStatusEl.style.color = "#86efac";
      addDataPoint();
      intervalId = setInterval(addDataPoint, 1000);
    }

    function stopStream() {
      clearInterval(intervalId);
      intervalId = null;
      streamStatusEl.textContent = "OFF";
      streamStatusEl.style.color = "#fca5a5";
    }

    function resetData() {
      dataPoints = [];
      labels = [];
      peakValue = 0;
      lastValue = null;

      currentValueEl.textContent = "0";
      averageValueEl.textContent = "0";
      peakValueEl.textContent = "0";
      currentTrendEl.textContent = "Waiting for data...";
      drawChart();
    }

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetData);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ["nameError", "categoryError", "severityError", "notesError"].forEach(id => {
        document.getElementById(id).textContent = "";
      });
      formSuccess.textContent = "";
    }

    function severityBadge(severity) {
      const cls =
        severity === "High" ? "badge-high" :
        severity === "Medium" ? "badge-medium" :
        "badge-low";
      return `<span class="badge ${cls}">${severity}</span>`;
    }

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const severity = document.getElementById("severity").value;
      const notes = document.getElementById("notes").value.trim();

      let valid = true;

      if (!name || name.length < 2) {
        setError("nameError", "Name must be at least 2 characters.");
        valid = false;
      }

      if (!category) {
        setError("categoryError", "Please select a category.");
        valid = false;
      }

      if (!severity) {
        setError("severityError", "Please select a severity.");
        valid = false;
      }

      if (!notes || notes.length < 5) {
        setError("notesError", "Notes must be at least 5 characters.");
        valid = false;
      }

      if (!valid) return;

      const timestamp = new Date().toLocaleString();

      if (recordsTableBody.children.length === 1 &&
          recordsTableBody.children[0].children.length === 1) {
        recordsTableBody.innerHTML = "";
      }

      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${timestamp}</td>
        <td>${escapeHtml(name)}</td>
        <td>${escapeHtml(category)}</td>
        <td>${severityBadge(severity)}</td>
        <td>${escapeHtml(notes)}</td>
      `;
      recordsTableBody.prepend(row);

      formSuccess.textContent = "Record submitted successfully.";
      form.reset();
    });

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    // Initial render
    drawChart();
  </script>
</body>
</html>
