  <div class="container">
    <div class="header">
      <div>
        <h1>Real-Time Operations Dashboard</h1>
        <p>Live metrics, charting, and form-driven alerts</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="primary">Start Stream</button>
        <button id="stopBtn">Stop Stream</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>
    </div>

    <div class="kpis">
      <div class="kpi">
        <div class="label">Current Value</div>
        <div class="value" id="currentValue">0</div>
      </div>
      <div class="kpi">
        <div class="label">Average</div>
        <div class="value" id="avgValue">0</div>
      </div>
      <div class="kpi">
        <div class="label">Peak</div>
        <div class="value" id="peakValue">0</div>
      </div>
      <div class="kpi">
        <div class="label">Alerts Triggered</div>
        <div class="value" id="alertCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Live Data Stream</h2>
        <div class="chart-wrap">
          <canvas id="chart"></canvas>
        </div>
        <div class="footer-note">
          Simulated real-time data updates every second.
        </div>
      </div>

      <div class="side-stack">
        <div class="panel">
          <h2>Create Alert Rule</h2>
          <form id="alertForm" novalidate>
            <div class="field">
              <label for="ruleName">Rule Name</label>
              <input id="ruleName" name="ruleName" type="text" placeholder="High Temperature" />
              <div class="error" id="ruleNameError"></div>
            </div>

            <div class="row">
              <div class="field">
                <label for="threshold">Threshold</label>
                <input id="threshold" name="threshold" type="number" min="0" max="100" placeholder="75" />
                <div class="error" id="thresholdError"></div>
              </div>

              <div class="field">
                <label for="severity">Severity</label>
                <select id="severity" name="severity">
                  <option value="">Select</option>
                  <option value="warning">Warning</option>
                  <option value="critical">Critical</option>
                </select>
                <div class="error" id="severityError"></div>
              </div>
            </div>

            <div class="field">
              <label for="message">Message</label>
              <textarea id="message" name="message" rows="3" placeholder="Notify team when threshold is exceeded"></textarea>
              <div class="error" id="messageError"></div>
            </div>

            <button type="submit" class="primary">Save Rule</button>
            <div class="success" id="formSuccess"></div>
          </form>
        </div>

        <div class="panel">
          <h2>Event Log</h2>
          <div class="log" id="eventLog"></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const avgValueEl = document.getElementById("avgValue");
    const peakValueEl = document.getElementById("peakValue");
    const alertCountEl = document.getElementById("alertCount");
    const eventLogEl = document.getElementById("eventLog");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const alertForm = document.getElementById("alertForm");
    const formSuccess = document.getElementById("formSuccess");

    const state = {
      data: [],
      maxPoints: 40,
      timer: null,
      alerts: [],
      alertCount: 0
    };

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function randomValue() {
      const last = state.data.length ? state.data[state.data.length - 1].value : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 20 - 10)));
      return Number(next.toFixed(1));
    }

    function addDataPoint() {
      const point = {
        time: new Date(),
        value: randomValue()
      };

      state.data.push(point);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }

      updateKPIs();
      evaluateAlerts(point);
      drawChart();
    }

    function updateKPIs() {
      if (!state.data.length) {
        currentValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        alertCountEl.textContent = state.alertCount;
        return;
      }

      const values = state.data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      alertCountEl.textContent = state.alertCount;
    }

    function drawChart() {
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);

      const padding = 30;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = padding + (chartH / 5) * i;
        ctx.fillText(value.toString(), 4, y + 4);
      }

      if (state.data.length < 2) return;

      const xStep = chartW / (state.maxPoints - 1);

      // Area fill
      ctx.beginPath();
      state.data.forEach((point, i) => {
        const x = padding + i * xStep;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + (state.data.length - 1) * xStep;
      ctx.lineTo(lastX, padding + chartH);
      ctx.lineTo(padding, padding + chartH);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, padding + chartH);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      state.data.forEach((point, i) => {
        const x = padding + i * xStep;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Points
      state.data.forEach((point, i) => {
        const x = padding + i * xStep;
        const y = padding + chartH - (point.value / 100) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });
    }

    function addLog(message, type = "ok") {
      const item = document.createElement("div");
      item.className = "log-item";

      const time = new Date().toLocaleTimeString();
      item.innerHTML = `
        <div class="time">${time}</div>
        <div>${message} <span class="badge ${type === "warn" ? "warn" : "ok"}">${type}</span></div>
      `;

      eventLogEl.prepend(item);

      while (eventLogEl.children.length > 12) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    function evaluateAlerts(point) {
      state.alerts.forEach(rule => {
        if (point.value > rule.threshold) {
          state.alertCount++;
          updateKPIs();
          addLog(
            `Rule "${rule.ruleName}" triggered at value ${point.value.toFixed(1)} (threshold: ${rule.threshold})`,
            rule.severity === "critical" ? "warn" : "ok"
          );
        }
      });
    }

    function startStream() {
      if (state.timer) return;
      state.timer = setInterval(addDataPoint, 1000);
      addLog("Data stream started");
    }

    function stopStream() {
      if (!state.timer) return;
      clearInterval(state.timer);
      state.timer = null;
      addLog("Data stream stopped", "warn");
    }

    function resetDashboard() {
      stopStream();
      state.data = [];
      state.alertCount = 0;
      updateKPIs();
      drawChart();
      eventLogEl.innerHTML = "";
      addLog("Dashboard reset");
    }

    function clearErrors() {
      ["ruleName", "threshold", "severity", "message"].forEach(field => {
        document.getElementById(field + "Error").textContent = "";
      });
      formSuccess.textContent = "";
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.ruleName.trim()) {
        document.getElementById("ruleNameError").textContent = "Rule name is required.";
        valid = false;
      }

      if (data.threshold === "" || isNaN(data.threshold)) {
        document.getElementById("thresholdError").textContent = "Threshold is required.";
        valid = false;
      } else if (Number(data.threshold) < 0 || Number(data.threshold) > 100) {
        document.getElementById("thresholdError").textContent = "Threshold must be between 0 and 100.";
        valid = false;
      }

      if (!data.severity) {
        document.getElementById("severityError").textContent = "Severity is required.";
        valid = false;
      }

      if (!data.message.trim()) {
        document.getElementById("messageError").textContent = "Message is required.";
        valid = false;
      }

      return valid;
    }

    alertForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = {
        ruleName: document.getElementById("ruleName").value,
        threshold: document.getElementById("threshold").value,
        severity: document.getElementById("severity").value,
        message: document.getElementById("message").value
      };

      if (!validateForm(formData)) return;

      const rule = {
        ruleName: formData.ruleName.trim(),
        threshold: Number(formData.threshold),
        severity: formData.severity,
        message: formData.message.trim()
      };

      state.alerts.push(rule);
      formSuccess.textContent = `Rule "${rule.ruleName}" saved successfully.`;
      addLog(`Alert rule created: "${rule.ruleName}" at threshold ${rule.threshold}`);
      alertForm.reset();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);
    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    updateKPIs();
    addLog("Dashboard ready");
  </script>
</body>
</html>
```

