      background: linear-gradient(180deg, rgba(56,189,248,0.04), rgba(255,255,255,0));
      border-radius: 12px;
    }

    form {
      display: grid;
      gap: 12px;
    }

    .field {
      display: grid;
      gap: 6px;
    }

    label {
      font-size: 0.92rem;
      color: var(--muted);
    }

    input, select, textarea {
      width: 100%;
      padding: 10px 12px;
      border-radius: 10px;
      border: 1px solid var(--border);
      background: #0b1220;
      color: var(--text);
      outline: none;
    }

    input:focus, select:focus, textarea:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15);
    }

    .error {
      color: #fca5a5;
      font-size: 0.85rem;
      min-height: 16px;
    }

    .success-message {
      color: #86efac;
      font-size: 0.9rem;
      min-height: 18px;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      overflow: hidden;
    }

    th, td {
