      padding: 12px;
      border-bottom: 1px solid var(--border);
      font-size: 0.95rem;
    }

    th {
      color: var(--muted);
      font-weight: 600;
    }

    .badge {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 999px;
      font-size: 0.8rem;
      font-weight: 700;
    }

    .badge.low {
      background: rgba(34,197,94,0.15);
      color: #86efac;
    }

    .badge.medium {
      background: rgba(245,158,11,0.15);
      color: #fcd34d;
    }

    .badge.high {
      background: rgba(239,68,68,0.15);
      color: #fca5a5;
    }

    @media (max-width: 900px) {
      .metric, .chart-card, .form-card, .table-card {
        grid-column: span 12;
      }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Real-Time Operations Dashboard</h1>
        <p>Live metrics, streaming chart, and interactive form handling</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="primary">Start Stream</button>
        <button id="stopBtn">Stop Stream</button>
        <button id="resetBtn" class="danger">Reset Data</button>
      </div>
    </div>

    <div class="grid">
      <div class="card metric">
        <h3>Current Value</h3>
        <div class="value" id="currentValue">0</div>
        <div class="sub">Latest incoming reading</div>
      </div>

      <div class="card metric">
        <h3>Average</h3>
        <div class="value" id="avgValue">0</div>
        <div class="sub">Rolling average</div>
      </div>

      <div class="card metric">
        <h3>Peak</h3>
        <div class="value" id="peakValue">0</div>
        <div class="sub">Highest observed value</div>
      </div>

      <div class="card metric">
        <h3>Status</h3>
        <div class="value" id="statusValue">Idle</div>
        <div class="sub">Stream state</div>
      </div>

      <div class="card chart-card">
        <h2 style="margin-top:0;">Live Data Chart</h2>
        <canvas id="chart" width="800" height="320"></canvas>
      </div>

      <div class="card form-card">
        <h2 style="margin-top:0;">Submit Incident</h2>
        <form id="incidentForm" novalidate>
          <div class="field">
            <label for="name">Name</label>
            <input id="name" name="name" type="text" placeholder="Enter your name" />
            <div class="error" id="nameError"></div>
          </div>

          <div class="field">
            <label for="department">Department</label>
            <select id="department" name="department">
              <option value="">Select department</option>
              <option>Operations</option>
              <option>Engineering</option>
              <option>Support</option>
              <option>Finance</option>
            </select>
            <div class="error" id="departmentError"></div>
          </div>

          <div class="field">
            <label for="severity">Severity</label>
            <select id="severity" name="severity">
              <option value="">Select severity</option>
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
            <div class="error" id="severityError"></div>
          </div>

          <div class="field">
            <label for="description">Description</label>
            <textarea id="description" name="description" rows="4" placeholder="Describe the issue"></textarea>
            <div class="error" id="descriptionError"></div>
          </div>

          <button type="submit" class="primary">Submit Report</button>
          <div class="success-message" id="formSuccess"></div>
        </form>
      </div>

      <div class="card table-card">
        <h2 style="margin-top:0;">Submitted Reports</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Department</th>
              <th>Severity</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody id="reportsTableBody">
            <tr>
              <td colspan="5" style="color: var(--muted);">No reports submitted yet.</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const statusValueEl = document.getElementById('statusValue');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const incidentForm = document.getElementById('incidentForm');
    const reportsTableBody = document.getElementById('reportsTableBody');
    const formSuccess = document.getElementById('formSuccess');

    let data = [];
    let maxPoints = 50;
    let intervalId = null;
    let peak = 0;

    function generateDataPoint() {
      const last = data.length ? data[data.length - 1].value : 50;
      const next = Math.max(5, Math.min(100, last + (Math.random() * 20 - 10)));
      return {
        time: new Date(),
        value: Number(next.toFixed(1))
      };
    }

    function addDataPoint() {
      const point = generateDataPoint();
      data.push(point);
      if (data.length > maxPoints) data.shift();
      peak = Math.max(peak, point.value);
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      const current = data.length ? data[data.length - 1].value : 0;
      const avg = data.length
        ? data.reduce((sum, p) => sum + p.value, 0) / data.length
        : 0;

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      statusValueEl.textContent = intervalId ? 'Streaming' : 'Stopped';
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const padding = 30;
      const minY = 0;
      const maxY = 100;
      const plotWidth = width - padding * 2;
      const plotHeight = height - padding * 2;

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * plotWidth;
        const y = padding + (1 - (point.value - minY) / (maxY - minY)) * plotHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + ((data.length - 1) / (maxPoints - 1)) * plotWidth;
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * plotWidth;
        const y = padding + (1 - (point.value - minY) / (maxY - minY)) * plotHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * plotWidth;
        const y = padding + (1 - (point.value - minY) / (maxY - minY)) * plotHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#e0f2fe';
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = 'rgba(148, 163, 184, 0.9)';
      ctx.font = '12px sans-serif';
      ctx.fillText('100', 4, padding + 4);
      ctx.fillText('50', 10, height / 2);
      ctx.fillText('0', 16, height - padding + 4);
    }

    function startStream() {
      if (intervalId) return;
      intervalId = setInterval(addDataPoint, 1000);
      statusValueEl.textContent = 'Streaming';
    }

    function stopStream() {
      clearInterval(intervalId);
      intervalId = null;
      statusValueEl.textContent = 'Stopped';
    }

    function resetData() {
      stopStream();
      data = [];
      peak = 0;
      updateMetrics();
      drawChart();
    }

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetData);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ['nameError', 'departmentError', 'severityError', 'descriptionError'].forEach(id => {
        setError(id, '');
      });
      formSuccess.textContent = '';
    }

    function validateForm(formData) {
      let valid = true;
      clearErrors();

      if (!formData.name.trim()) {
        setError('nameError', 'Name is required.');
        valid = false;
      }

      if (!formData.department) {
        setError('departmentError', 'Department is required.');
        valid = false;
      }

      if (!formData.severity) {
        setError('severityError', 'Severity is required.');
        valid = false;
      }

      if (!formData.description.trim()) {
        setError('descriptionError', 'Description is required.');
        valid = false;
      } else if (formData.description.trim().length < 10) {
        setError('descriptionError', 'Description must be at least 10 characters.');
        valid = false;
      }

      return valid;
    }

    function severityBadge(severity) {
      const cls = severity.toLowerCase();
      return `<span class="badge ${cls}">${severity}</span>`;
    }

    function addReportRow(report) {
      const emptyRow = reportsTableBody.querySelector('td[colspan="5"]');
      if (emptyRow) {
        reportsTableBody.innerHTML = '';
      }

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${report.time}</td>
        <td>${report.name}</td>
        <td>${report.department}</td>
        <td>${severityBadge(report.severity)}</td>
        <td>${report.description}</td>
      `;
      reportsTableBody.prepend(row);
    }

    incidentForm.addEventListener('submit', function (e) {
      e.preventDefault();

      const formData = {
        name: document.getElementById('name').value,
        department: document.getElementById('department').value,
        severity: document.getElementById('severity').value,
        description: document.getElementById('description').value
      };

      if (!validateForm(formData)) return;

      const report = {
        ...formData,
        time: new Date().toLocaleTimeString()
      };

      addReportRow(report);
      formSuccess.textContent = 'Report submitted successfully.';
      incidentForm.reset();
    });

    // Initial render
    updateMetrics();
    drawChart();

    // Seed with a few points
    for (let i = 0; i < 10; i++) addDataPoint();
  </script>
</body>
</html>
