    const configForm = document.getElementById("configForm");
    const successMessage = document.getElementById("successMessage");
    const logList = document.getElementById("logList");

    const formFields = {
      name: document.getElementById("name"),
      threshold: document.getElementById("threshold"),
      category: document.getElementById("category"),
      notes: document.getElementById("notes")
    };

    const formErrors = {
      name: document.getElementById("nameError"),
      threshold: document.getElementById("thresholdError"),
      category: document.getElementById("categoryError"),
      notes: document.getElementById("notesError")
    };

    let data = [];
    let maxPoints = 40;
    let intervalId = null;
    let eventCount = 0;
    let thresholdValue = 75;

    function randomMetric() {
      const base = 50 + Math.sin(Date.now() / 3000) * 20;
      const noise = Math.random() * 20 - 10;
      return Math.max(0, Math.min(100, Math.round(base + noise)));
    }

    function addDataPoint(value) {
      const timestamp = new Date().toLocaleTimeString();
      data.push({ value, timestamp });
      if (data.length > maxPoints) data.shift();

      updateStats();
      drawChart();

      if (value >= thresholdValue) {
        addLog("alert", `Threshold exceeded: ${value} >= ${thresholdValue}`);
      }
    }

    function updateStats() {
      if (data.length === 0) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
      eventCountEl.textContent = eventCount;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 8; i++) {
        const x = (width / 8) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      // Threshold line
      const thresholdY = height - (thresholdValue / 100) * height;
      ctx.strokeStyle = "rgba(245, 158, 11, 0.9)";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(0, thresholdY);
      ctx.lineTo(width, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = "rgba(245, 158, 11, 0.95)";
      ctx.font = "12px sans-serif";
      ctx.fillText(`Threshold: ${thresholdValue}`, 10, Math.max(14, thresholdY - 8));

      if (data.length < 2) return;

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (point.value / 100) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(width, height);
      ctx.lineTo(0, height);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.03)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (point.value / 100) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (point.value / 100) * height;
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = point.value >= thresholdValue ? "#f59e0b" : "#22c55e";
        ctx.fill();
      });
    }

    function addLog(type, message) {
      eventCount++;
      eventCountEl.textContent = eventCount;

      const li = document.createElement("li");
      li.className = "log-item";

      const time = new Date().toLocaleTimeString();
      const labelMap = {
        info: "INFO",
        alert: "ALERT",
        user: "USER"
      };

      li.innerHTML = `
        <div class="meta">
          <span class="pill ${type}">${labelMap[type] || "INFO"}</span>
          <span>${time}</span>
        </div>
        <div>${message}</div>
      `;

      logList.prepend(li);

      while (logList.children.length > 20) {
        logList.removeChild(logList.lastChild);
      }
    }

    function startStream() {
      if (intervalId) return;
      intervalId = setInterval(() => {
        addDataPoint(randomMetric());
      }, 1000);
      statusTextEl.textContent = "Streaming live data";
      addLog("info", "Data stream started");
    }

    function stopStream() {
      if (!intervalId) return;
      clearInterval(intervalId);
      intervalId = null;
      statusTextEl.textContent = "Stream paused";
      addLog("info", "Data stream stopped");
    }

    function resetDashboard() {
      data = [];
      drawChart();
      updateStats();
      addLog("info", "Dashboard reset");
    }

    function clearErrors() {
      Object.values(formErrors).forEach(el => el.textContent = "");
      successMessage.style.display = "none";
    }

    function validateForm() {
      clearErrors();
      let isValid = true;

      const name = formFields.name.value.trim();
      const threshold = formFields.threshold.value.trim();
      const category = formFields.category.value;
      const notes = formFields.notes.value.trim();

      if (name.length < 2) {
        formErrors.name.textContent = "Name must be at least 2 characters.";
        isValid = false;
      }

      if (threshold === "") {
        formErrors.threshold.textContent = "Threshold is required.";
        isValid = false;
      } else {
        const num = Number(threshold);
        if (Number.isNaN(num) || num < 0 || num > 100) {
          formErrors.threshold.textContent = "Threshold must be a number between 0 and 100.";
          isValid = false;
        }
      }

      if (!category) {
        formErrors.category.textContent = "Please select a category.";
        isValid = false;
      }

      if (notes.length > 200) {
        formErrors.notes.textContent = "Notes must be 200 characters or fewer.";
        isValid = false;
      }

      return isValid;
    }

    configForm.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      const payload = {
        name: formFields.name.value.trim(),
        threshold: Number(formFields.threshold.value),
        category: formFields.category.value,
        notes: formFields.notes.value.trim()
      };

      thresholdValue = payload.threshold;
      drawChart();

      successMessage.style.display = "block";
      successMessage.textContent = `Saved by ${payload.name}. Threshold set to ${payload.threshold} for ${payload.category}.`;

      addLog(
        "user",
        `Configuration updated by ${payload.name}: threshold=${payload.threshold}, category=${payload.category}`
      );
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    // Seed initial data
    for (let i = 0; i < 12; i++) {
      addDataPoint(randomMetric());
    }
    drawChart();
    addLog("info", "Dashboard initialized");
    startStream();
  </script>
</body>
</html>
```

