<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, chart updates, and form-driven event handling</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="btn-success">Start Stream</button>
        <button id="stopBtn" class="btn-danger">Stop Stream</button>
