        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Status</div>
        <div class="stat-value"><span id="streamStatus" class="badge">Running</span></div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Live Data Chart</h2>
        <div class="chart-wrap">
          <canvas id="chartCanvas"></canvas>
        </div>
        <div class="footer-note">
          Simulated real-time values update every second. Use the form to inject custom events into the activity log.
        </div>
      </div>

