              <label for="eventType">Event Type</label>
              <select id="eventType" name="eventType">
                <option value="">Select a type</option>
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="critical">Critical</option>
              </select>
              <div class="error" id="eventTypeError"></div>
            </div>

            <div class="field">
              <label for="eventMessage">Message</label>
              <textarea id="eventMessage" name="eventMessage" rows="4" placeholder="Describe the event..."></textarea>
              <div class="error" id="eventMessageError"></div>
            </div>

            <button type="submit" class="btn-primary">Submit Event</button>
            <div class="success-message" id="formSuccess"></div>
          </form>
