  <script>
    const canvas = document.getElementById("chartCanvas");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const streamStatusEl = document.getElementById("streamStatus");
    const activityLog = document.getElementById("activityLog");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const eventForm = document.getElementById("eventForm");
    const formSuccess = document.getElementById("formSuccess");

    const MAX_POINTS = 30;
    let data = [];
    let timer = null;
    let running = true;

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function generateValue() {
      const last = data.length ? data[data.length - 1] : 50;
      const next = Math.max(5, Math.min(100, last + (Math.random() * 20 - 10)));
      return Math.round(next);
    }

    function addDataPoint(value = generateValue()) {
      const timestamp = new Date();
      data.push({ value, time: timestamp });
      if (data.length > MAX_POINTS) data.shift();
      updateStats();
      drawChart();
    }

    function updateStats() {
      if (!data.length) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
    }

    function drawGrid(width, height, padding) {
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 0; i <= rows; i++) {
        const y = padding + ((height - padding * 2) / rows) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = padding + ((width - padding * 2) / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }
    }

    function drawChart() {
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;
      const padding = 30;

      ctx.clearRect(0, 0, width, height);
      drawGrid(width, height, padding);

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = 0;
      const max = 100;

      const stepX = (width - padding * 2) / (MAX_POINTS - 1);

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + (data.length - 1) * stepX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(34, 197, 94, 0.05)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "rgba(229, 231, 235, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText("100", 5, padding + 4);
      ctx.fillText("50", 12, height / 2);
      ctx.fillText("0", 18, height - padding + 4);
    }

    function startStream() {
      if (timer) return;
      running = true;
      streamStatusEl.textContent = "Running";
      timer = setInterval(() => {
        addDataPoint();
      }, 1000);
      addLog("System", "info", "Real-time stream started.");
    }

    function stopStream() {
      running = false;
      streamStatusEl.textContent = "Stopped";
      clearInterval(timer);
      timer = null;
      addLog("System", "warning", "Real-time stream stopped.");
    }

    function resetData() {
      data = [];
      updateStats();
      drawChart();
      addLog("System", "info", "Dashboard data reset.");
    }

    function addLog(title, type, message) {
      const item = document.createElement("div");
      item.className = "log-item";

      let color = "#93c5fd";
      if (type === "warning") color = "#fcd34d";
      if (type === "critical") color = "#fca5a5";
      if (type === "info") color = "#86efac";

      const time = new Date().toLocaleTimeString();

      item.innerHTML = `
        <div class="log-time">${time}</div>
        <div><strong style="color:${color}">${title}</strong></div>
        <div>${message}</div>
      `;

      activityLog.prepend(item);

      while (activityLog.children.length > 12) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    function clearErrors() {
      document.getElementById("eventNameError").textContent = "";
      document.getElementById("eventTypeError").textContent = "";
      document.getElementById("eventMessageError").textContent = "";
      formSuccess.textContent = "";
    }

    function validateForm(formData) {
      clearErrors();
      let valid = true;

      if (!formData.eventName.trim()) {
        document.getElementById("eventNameError").textContent = "Event name is required.";
        valid = false;
      }

      if (!formData.eventType.trim()) {
        document.getElementById("eventTypeError").textContent = "Please select an event type.";
        valid = false;
      }

      if (!formData.eventMessage.trim()) {
        document.getElementById("eventMessageError").textContent = "Message is required.";
        valid = false;
      } else if (formData.eventMessage.trim().length < 5) {
        document.getElementById("eventMessageError").textContent = "Message must be at least 5 characters.";
        valid = false;
      }

      return valid;
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = {
        eventName: document.getElementById("eventName").value,
        eventType: document.getElementById("eventType").value,
        eventMessage: document.getElementById("eventMessage").value
      };

      if (!validateForm(formData)) return;

      addLog(formData.eventName, formData.eventType, formData.eventMessage);
      formSuccess.textContent = "Event submitted successfully.";
      eventForm.reset();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetData);

    window.addEventListener("resize", resizeCanvas);

    // Initial seed data
    for (let i = 0; i < 12; i++) {
      addDataPoint(Math.round(40 + Math.random() * 30));
    }

    resizeCanvas();
    startStream();
  </script>
</body>
</html>
```

