<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>
          <span id="statusDot" class="status-dot live"></span>
          <span id="statusText">Live stream active</span>
        </p>
      </div>
      <div class="controls">
        <button id="startBtn" class="success">Start</button>
        <button id="stopBtn">Stop</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>
    </div>

    <div class="stats">
      <div class="stat-card">
        <div class="stat-label">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Data Points</div>
        <div class="stat-value" id="pointCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Real-Time Data Visualization</h2>
        <div class="chart-wrap">
          <canvas id="chartCanvas"></canvas>
        </div>
        <div class="footer-note">
          Simulated sensor stream updating every second.
        </div>
      </div>

      <div class="panel">
        <h2>Submit Configuration</h2>
        <form id="configForm" novalidate>
          <div class="field">
            <label for="deviceName">Device Name</label>
            <input type="text" id="deviceName" name="deviceName" placeholder="e.g. Sensor-A1" />
            <div class="error" id="deviceNameError"></div>
          </div>

          <div class="field">
            <label for="threshold">Alert Threshold</label>
            <input type="number" id="threshold" name="threshold" placeholder="e.g. 75" min="0" max="100" />
            <div class="error" id="thresholdError"></div>
          </div>

          <div class="field">
            <label for="interval">Update Interval</label>
            <select id="interval" name="interval">
              <option value="500">500 ms</option>
              <option value="1000" selected>1000 ms</option>
              <option value="2000">2000 ms</option>
            </select>
            <div class="error" id="intervalError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Optional notes..."></textarea>
            <div class="error" id="notesError"></div>
          </div>

          <button type="submit" class="primary">Save Configuration</button>
          <div class="success-message" id="formSuccess"></div>
        </form>

        <h2 style="margin-top: 24px;">Activity Log</h2>
        <div class="log" id="activityLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chartCanvas");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const pointCountEl = document.getElementById("pointCount");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const statusDot = document.getElementById("statusDot");
    const statusText = document.getElementById("statusText");

    const form = document.getElementById("configForm");
    const activityLog = document.getElementById("activityLog");
    const formSuccess = document.getElementById("formSuccess");

    let data = [];
    let maxPoints = 40;
    let timer = null;
    let updateInterval = 1000;
    let threshold = 75;

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * devicePixelRatio;
      canvas.height = rect.height * devicePixelRatio;
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      drawChart();
    }

    window.addEventListener("resize", resizeCanvas);

    function generateDataPoint() {
      const last = data.length ? data[data.length - 1].value : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 20 - 10)));
      return {
        time: new Date(),
        value: Number(next.toFixed(1))
      };
    }

    function addDataPoint() {
      const point = generateDataPoint();
      data.push(point);
      if (data.length > maxPoints) data.shift();

      updateStats();
      drawChart();

      if (point.value >= threshold) {
        addLog(`Threshold alert: value ${point.value} exceeded threshold ${threshold}`, "alert");
      }
    }

    function updateStats() {
      if (!data.length) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        pointCountEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      pointCountEl.textContent = data.length;
    }

    function drawChart() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height);
      drawAxes(width, height);

      if (data.length < 2) return;

      const padding = 30;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      ctx.beginPath();
      ctx.lineWidth = 2;
      ctx.strokeStyle = "#3b82f6";

      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = padding + (1 - point.value / 100) * chartHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Fill area under line
      ctx.lineTo(padding + chartWidth, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = "rgba(59, 130, 246, 0.15)";
      ctx.fill();

      // Draw points
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = padding + (1 - point.value / 100) * chartHeight;

        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = point.value >= threshold ? "#ef4444" : "#22c55e";
        ctx.fill();
      });

      // Threshold line
      const thresholdY = padding + (1 - threshold / 100) * chartHeight;
      ctx.beginPath();
      ctx.setLineDash([6, 6]);
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(width - padding, thresholdY);
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = "#f59e0b";
      ctx.font = "12px sans-serif";
      ctx.fillText(`Threshold: ${threshold}`, width - 120, thresholdY - 8);
    }

    function drawGrid(width, height) {
      const padding = 30;
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 5; i++) {
        const x = padding + ((width - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }
    }

    function drawAxes(width, height) {
      const padding = 30;
      ctx.strokeStyle = "rgba(229, 231, 235, 0.4)";
      ctx.lineWidth = 1.2;

      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, height - padding);
      ctx.lineTo(width - padding, height - padding);
      ctx.stroke();

      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";

      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.fillText(value.toString(), 4, y + 4);
      }
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(addDataPoint, updateInterval);
      statusDot.classList.add("live");
      statusText.textContent = "Live stream active";
      addLog(`Stream started at ${updateInterval} ms interval`);
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
      statusDot.classList.remove("live");
      statusText.textContent = "Stream paused";
      addLog("Stream stopped");
    }

    function resetDashboard() {
      data = [];
      updateStats();
      drawChart();
      addLog("Dashboard reset");
    }

    function addLog(message, type = "info") {
      const item = document.createElement("div");
      item.className = "log-item";

      const time = document.createElement("div");
      time.className = "log-time";
      time.textContent = new Date().toLocaleTimeString();

      const text = document.createElement("div");
      text.textContent = message;

      if (type === "alert") {
        text.style.color = "#fca5a5";
      }

      item.appendChild(time);
      item.appendChild(text);

      activityLog.prepend(item);

      while (activityLog.children.length > 12) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    function clearErrors() {
      document.querySelectorAll(".error").forEach(el => el.textContent = "");
      formSuccess.textContent = "";
    }

    function validateForm(values) {
      const errors = {};

      if (!values.deviceName.trim()) {
        errors.deviceName = "Device name is required.";
      } else if (values.deviceName.trim().length < 3) {
        errors.deviceName = "Device name must be at least 3 characters.";
      }

      if (values.threshold === "") {
        errors.threshold = "Threshold is required.";
      } else {
        const num = Number(values.threshold);
        if (Number.isNaN(num) || num < 0 || num > 100) {
          errors.threshold = "Threshold must be between 0 and 100.";
        }
      }

      if (!values.interval) {
        errors.interval = "Please select an update interval.";
      }

      if (values.notes.length > 200) {
        errors.notes = "Notes must be 200 characters or fewer.";
      }

      return errors;
    }

    function showErrors(errors) {
      Object.entries(errors).forEach(([key, message]) => {
        const errorEl = document.getElementById(`${key}Error`);
        if (errorEl) errorEl.textContent = message;
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        deviceName: form.deviceName.value,
        threshold: form.threshold.value,
        interval: form.interval.value,
        notes: form.notes.value
      };

      const errors = validateForm(values);

      if (Object.keys(errors).length > 0) {
        showErrors(errors);
        addLog("Form submission failed validation");
        return;
      }

      threshold = Number(values.threshold);
      updateInterval = Number(values.interval);

      const wasRunning = !!timer;
      if (wasRunning) {
        stopStream();
        startStream();
      }

      formSuccess.textContent = "Configuration saved successfully.";
      addLog(
        `Configuration updated: device=${values.deviceName}, threshold=${threshold}, interval=${updateInterval}ms`
      );

      drawChart();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    resizeCanvas();
    for (let i = 0; i < 12; i++) addDataPoint();
    startStream();
  </script>
</body>
</html>
```

