  <script>
    const MAX_POINTS = 20;
    let liveData = [];
    let timer = null;
    let submittedRecords = [];

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const recordCountEl = document.getElementById('recordCount');

    const ctx = document.getElementById('liveChart').getContext('2d');

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Sensor Value',
          data: [],
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: '#93c5fd'
        }]
      },
      options: {
        responsive: true,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' },
            beginAtZero: true
          }
        }
      }
    });

    function getRandomValue() {
      return +(Math.random() * 100).toFixed(1);
    }

    function getTimeLabel() {
      return new Date().toLocaleTimeString();
    }

    function updateKPIs() {
      if (liveData.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const current = liveData[liveData.length - 1];
      const avg = (liveData.reduce((sum, v) => sum + v, 0) / liveData.length).toFixed(1);
      const peak = Math.max(...liveData).toFixed(1);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peak;
    }

    function addLivePoint() {
      const value = getRandomValue();
      const time = getTimeLabel();

      liveData.push(value);
      chart.data.labels.push(time);
      chart.data.datasets[0].data.push(value);

      if (liveData.length > MAX_POINTS) {
        liveData.shift();
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
      updateKPIs();
    }

    function startLiveUpdates() {
      if (timer) return;
      timer = setInterval(addLivePoint, 1000);
    }

    function stopLiveUpdates() {
      clearInterval(timer);
      timer = null;
    }

    function resetDashboard() {
      stopLiveUpdates();
      liveData = [];
      chart.data.labels = [];
      chart.data.datasets[0].data = [];
      chart.update();
      updateKPIs();
    }

    document.getElementById('startBtn').addEventListener('click', startLiveUpdates);
    document.getElementById('stopBtn').addEventListener('click', stopLiveUpdates);
    document.getElementById('resetBtn').addEventListener('click', resetDashboard);

    function clearErrors() {
      document.getElementById('nameError').textContent = '';
      document.getElementById('metricError').textContent = '';
      document.getElementById('categoryError').textContent = '';
      document.getElementById('notesError').textContent = '';
      document.getElementById('successMessage').textContent = '';
    }

    function getStatus(metric) {
      if (metric >= 75) return { label: 'Alert', className: 'status-alert' };
      if (metric >= 40) return { label: 'Warning', className: 'status-warn' };
      return { label: 'OK', className: 'status-ok' };
    }

    function renderRecords() {
      const tbody = document.getElementById('recordsTableBody');
      recordCountEl.textContent = submittedRecords.length;

      if (submittedRecords.length === 0) {
        tbody.innerHTML = `
          <tr>
            <td colspan="6" style="color: var(--muted);">No records submitted yet.</td>
          </tr>
        `;
        return;
      }

      tbody.innerHTML = submittedRecords
        .slice()
        .reverse()
        .map(record => `
          <tr>
            <td>${record.time}</td>
            <td>${record.name}</td>
            <td>${record.metric}</td>
            <td>${record.category}</td>
            <td><span class="status-pill ${record.status.className}">${record.status.label}</span></td>
            <td>${record.notes || '-'}</td>
          </tr>
        `)
        .join('');
    }

    document.getElementById('recordForm').addEventListener('submit', function (e) {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById('name').value.trim();
      const metricRaw = document.getElementById('metric').value.trim();
      const category = document.getElementById('category').value;
      const notes = document.getElementById('notes').value.trim();

      let isValid = true;

      if (!name) {
        document.getElementById('nameError').textContent = 'Name is required.';
        isValid = false;
      }

      if (!metricRaw) {
        document.getElementById('metricError').textContent = 'Metric value is required.';
        isValid = false;
      }

      const metric = parseFloat(metricRaw);
      if (metricRaw && (isNaN(metric) || metric < 0 || metric > 1000)) {
        document.getElementById('metricError').textContent = 'Metric must be a number between 0 and 1000.';
        isValid = false;
      }

      if (!category) {
        document.getElementById('categoryError').textContent = 'Please select a category.';
        isValid = false;
      }

      if (notes.length > 200) {
        document.getElementById('notesError').textContent = 'Notes must be 200 characters or fewer.';
        isValid = false;
      }

      if (!isValid) return;

      const status = getStatus(metric);
      const record = {
        time: getTimeLabel(),
        name,
        metric: metric.toFixed(1),
        category,
        notes,
        status
      };

      submittedRecords.push(record);
      renderRecords();

      document.getElementById('successMessage').textContent = 'Record submitted successfully.';
      this.reset();
    });

    // Seed initial chart data
    for (let i = 0; i < 6; i++) {
      addLivePoint();
    }
    renderRecords();
    startLiveUpdates();
  </script>
</body>
</html>
