  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const avgValueEl = document.getElementById("avgValue");
    const maxValueEl = document.getElementById("maxValue");
    const statusBadge = document.getElementById("statusBadge");
    const eventLog = document.getElementById("eventLog");

    const form = document.getElementById("metricForm");
    const formSuccess = document.getElementById("formSuccess");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");
    const randomInjectBtn = document.getElementById("randomInjectBtn");

    const MAX_POINTS = 40;
    let thresholdValue = 75;
    let data = [];
    let timer = null;
    let running = true;
    let t = 0;

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function generatePoint() {
      t += 1;
      const base = 50 + Math.sin(t / 3) * 12;
      const noise = (Math.random() - 0.5) * 10;
      const spike = Math.random() > 0.94 ? Math.random() * 30 : 0;
      return Math.max(5, Math.min(100, base + noise + spike));
    }

    function addDataPoint(value, source = "simulation") {
      const point = {
        time: new Date(),
        value: Number(value.toFixed(2)),
        source
      };

      data.push(point);
      if (data.length > MAX_POINTS) data.shift();

      updateStats();
      drawChart();
    }

    function updateStats() {
      if (!data.length) {
        currentValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        maxValueEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const max = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      maxValueEl.textContent = max.toFixed(1);
    }

    function drawChart() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      const padding = 36;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 5; i++) {
        const x = padding + (chartW / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      for (let i = 0; i <= 5; i++) {
        const val = 100 - (100 / 5) * i;
        const y = padding + (chartH / 5) * i + 4;
        ctx.fillText(val.toFixed(0), padding - 8, y);
      }

      // Threshold line
      const thresholdY = padding + chartH - (thresholdValue / 100) * chartH;
      ctx.strokeStyle = "#22c55e";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(width - padding, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "#22c55e";
      ctx.textAlign = "left";
      ctx.fillText(`Threshold: ${thresholdValue}`, width - padding - 100, thresholdY - 8);

      if (!data.length) return;

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (index / Math.max(1, MAX_POINTS - 1)) * chartW;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + ((data.length - 1) / Math.max(1, MAX_POINTS - 1)) * chartW;
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(59,130,246,0.35)");
      gradient.addColorStop(1, "rgba(59,130,246,0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (index / Math.max(1, MAX_POINTS - 1)) * chartW;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + (index / Math.max(1, MAX_POINTS - 1)) * chartW;
        const y = padding + chartH - (point.value / 100) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = point.value >= thresholdValue ? "#ef4444" : "#93c5fd";
        ctx.fill();
      });
    }

    function startSimulation() {
      if (timer) return;
      running = true;
      updateStatus();
      timer = setInterval(() => {
        addDataPoint(generatePoint(), "simulation");
      }, 1000);
    }

    function stopSimulation() {
      running = false;
      updateStatus();
      clearInterval(timer);
      timer = null;
    }

    function resetDashboard() {
      data = [];
      t = 0;
      thresholdValue = 75;
      document.getElementById("threshold").value = "";
      updateStats();
      drawChart();
      addLog("Dashboard reset", "system");
    }

    function updateStatus() {
      statusBadge.textContent = running ? "Running" : "Stopped";
      statusBadge.style.background = running
        ? "rgba(34,197,94,0.15)"
        : "rgba(239,68,68,0.15)";
      statusBadge.style.color = running ? "#86efac" : "#fca5a5";
      statusBadge.style.borderColor = running
        ? "rgba(34,197,94,0.25)"
        : "rgba(239,68,68,0.25)";
    }

    function addLog(message, type = "info") {
      const item = document.createElement("div");
      item.className = "log-item";

      const left = document.createElement("div");
      left.textContent = `[${type.toUpperCase()}] ${message}`;

      const right = document.createElement("div");
      right.className = "log-time";
      right.textContent = new Date().toLocaleTimeString();

      item.appendChild(left);
      item.appendChild(right);

      eventLog.prepend(item);

      while (eventLog.children.length > 30) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function clearErrors() {
      [
        "metricNameError",
        "metricTypeError",
        "metricValueError",
        "thresholdError",
        "notesError"
      ].forEach(id => {
        document.getElementById(id).textContent = "";
      });
      formSuccess.textContent = "";
    }

    function validateForm(values) {
      let valid = true;

      if (!values.metricName.trim()) {
        document.getElementById("metricNameError").textContent = "Metric name is required.";
        valid = false;
      }

      if (!values.metricType) {
        document.getElementById("metricTypeError").textContent = "Please select a metric type.";
        valid = false;
      }

      if (values.metricValue === "" || isNaN(Number(values.metricValue))) {
        document.getElementById("metricValueError").textContent = "Enter a valid metric value.";
        valid = false;
      }

      if (values.threshold !== "" && isNaN(Number(values.threshold))) {
        document.getElementById("thresholdError").textContent = "Threshold must be numeric.";
        valid = false;
      }

      if (values.notes.length > 200) {
        document.getElementById("notesError").textContent = "Notes must be 200 characters or fewer.";
        valid = false;
      }

      return valid;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        metricName: document.getElementById("metricName").value,
        metricType: document.getElementById("metricType").value,
        metricValue: document.getElementById("metricValue").value,
        threshold: document.getElementById("threshold").value,
        notes: document.getElementById("notes").value.trim()
      };

      if (!validateForm(values)) return;

      const numericValue = Number(values.metricValue);
      addDataPoint(numericValue, "manual");

      if (values.threshold !== "") {
        thresholdValue = Number(values.threshold);
      }

      drawChart();

      const noteText = values.notes ? ` Notes: ${values.notes}` : "";
      addLog(
        `${values.metricName} (${values.metricType}) submitted with value ${numericValue}. Threshold: ${thresholdValue}.${noteText}`,
        "event"
      );

      formSuccess.textContent = "Metric event submitted successfully.";
      form.reset();
    });

    randomInjectBtn.addEventListener("click", () => {
      const spike = 80 + Math.random() * 20;
      addDataPoint(spike, "spike");
      addLog(`Random spike injected: ${spike.toFixed(1)}`, "warning");
    });

    startBtn.addEventListener("click", () => {
      startSimulation();
      addLog("Simulation started", "system");
    });

    stopBtn.addEventListener("click", () => {
      stopSimulation();
      addLog("Simulation stopped", "system");
    });

    resetBtn.addEventListener("click", () => {
      resetDashboard();
    });

    window.addEventListener("resize", resizeCanvas);

    // Initial setup
    resizeCanvas();
    for (let i = 0; i < 12; i++) {
      addDataPoint(generatePoint(), "bootstrap");
    }
    updateStatus();
    startSimulation();
    addLog("Dashboard initialized", "system");
  </script>
</body>
</html>
```

