  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const sampleCountEl = document.getElementById('sampleCount');
    const feedStatusEl = document.getElementById('feedStatus');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const eventForm = document.getElementById('eventForm');
    const eventsTableBody = document.getElementById('eventsTableBody');
    const eventCountEl = document.getElementById('eventCount');
    const formSuccessEl = document.getElementById('formSuccess');

    const maxPoints = 50;
    let dataPoints = [];
    let timer = null;
    let events = [];

    function randomValue() {
      const base = 50;
      const variance = Math.random() * 40 - 20;
      const trend = Math.sin(Date.now() / 2000) * 10;
      return Math.max(0, Math.round(base + variance + trend));
    }

    function addDataPoint() {
      const value = randomValue();
      const timestamp = new Date().toLocaleTimeString();

      dataPoints.push({ value, timestamp });
      if (dataPoints.length > maxPoints) dataPoints.shift();

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (dataPoints.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        sampleCountEl.textContent = '0';
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const average = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current;
      averageValueEl.textContent = average.toFixed(1);
      peakValueEl.textContent = peak;
      sampleCountEl.textContent = dataPoints.length;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      const padding = 40;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + ((height - 2 * padding) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 5; i++) {
        const x = padding + ((width - 2 * padding) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      if (dataPoints.length < 2) return;

      const values = dataPoints.map(p => p.value);
      const maxVal = Math.max(...values, 100);
      const minVal = Math.min(...values, 0);
      const range = maxVal - minVal || 1;

      // Axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText(maxVal.toString(), 8, padding + 4);
      ctx.fillText(minVal.toString(), 8, height - padding + 4);

      // Area fill
      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');

      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * (width - 2 * padding);
        const y = height - padding - ((point.value - minVal) / range) * (height - 2 * padding);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + ((dataPoints.length - 1) / (maxPoints - 1)) * (width - 2 * padding);
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * (width - 2 * padding);
        const y = height - padding - ((point.value - minVal) / range) * (height - 2 * padding);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * (width - 2 * padding);
        const y = height - padding - ((point.value - minVal) / range) * (height - 2 * padding);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#93c5fd';
        ctx.fill();
      });
    }

    function startFeed() {
      if (timer) return;
      feedStatusEl.textContent = 'Status: running';
      timer = setInterval(addDataPoint, 1000);
    }

    function stopFeed() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
      feedStatusEl.textContent = 'Status: stopped';
    }

    function resetData() {
      stopFeed();
      dataPoints = [];
      updateMetrics();
      drawChart();
    }

    function clearErrors() {
      ['name', 'category', 'severity', 'message'].forEach(field => {
        document.getElementById(field + 'Error').textContent = '';
      });
      formSuccessEl.textContent = '';
    }

    function validateForm(formData) {
      let valid = true;
      clearErrors();

      if (!formData.name.trim()) {
        document.getElementById('nameError').textContent = 'Name is required.';
        valid = false;
      }

      if (!formData.category) {
        document.getElementById('categoryError').textContent = 'Category is required.';
        valid = false;
      }

      if (!formData.severity) {
        document.getElementById('severityError').textContent = 'Severity is required.';
        valid = false;
      }

      if (!formData.message.trim()) {
        document.getElementById('messageError').textContent = 'Message is required.';
        valid = false;
      } else if (formData.message.trim().length < 5) {
        document.getElementById('messageError').textContent = 'Message must be at least 5 characters.';
        valid = false;
      }

      return valid;
    }

    function severityBadge(severity) {
      const cls =
        severity === 'High' ? 'badge-high' :
        severity === 'Medium' ? 'badge-medium' :
        'badge-low';

      return `<span class="badge ${cls}">${severity}</span>`;
    }

    function renderEvents() {
      eventCountEl.textContent = `${events.length} event${events.length !== 1 ? 's' : ''}`;

      if (events.length === 0) {
        eventsTableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted); text-align:center;">No events submitted yet</td>
          </tr>
        `;
        return;
      }

      eventsTableBody.innerHTML = events
        .slice()
        .reverse()
        .map(event => `
          <tr>
            <td>${event.time}</td>
            <td>${escapeHtml(event.name)}</td>
            <td>${escapeHtml(event.category)}</td>
            <td>${severityBadge(event.severity)}</td>
            <td>${escapeHtml(event.message)}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = {
        name: document.getElementById('name').value,
        category: document.getElementById('category').value,
        severity: document.getElementById('severity').value,
        message: document.getElementById('message').value
      };

      if (!validateForm(formData)) return;

      events.push({
        ...formData,
        time: new Date().toLocaleString()
      });

      renderEvents();
      eventForm.reset();
      clearErrors();
      formSuccessEl.textContent = 'Event submitted successfully.';
    });

    startBtn.addEventListener('click', startFeed);
    stopBtn.addEventListener('click', stopFeed);
    resetBtn.addEventListener('click', resetData);

    // Initial render
    updateMetrics();
    drawChart();
    renderEvents();
  </script>
</body>
</html>
