        <h2 class="panel-title">Submitted Records</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Category</th>
              <th>Priority</th>
              <th>Notes</th>
            </tr>
          </thead>
          <tbody id="recordsTableBody">
            <tr>
              <td colspan="5" style="color: var(--muted); text-align: center;">No records submitted yet</td>
            </tr>
          </tbody>
        </table>
      </div>
