  </div>

  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const submissionCountEl = document.getElementById('submissionCount');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const eventForm = document.getElementById('eventForm');
    const recordsTableBody = document.getElementById('recordsTableBody');
    const formSuccess = document.getElementById('formSuccess');

    const MAX_POINTS = 50;
    let dataPoints = [];
    let timer = null;
    let submissions = [];

    function randomValue() {
      const base = 50;
      const variance = Math.random() * 40 - 20;
      const trend = Math.sin(Date.now() / 2000) * 10;
      return Math.max(5, Math.round(base + variance + trend));
    }

    function addDataPoint() {
      const value = randomValue();
      const timestamp = new Date().toLocaleTimeString();

      dataPoints.push({ value, timestamp });
      if (dataPoints.length > MAX_POINTS) dataPoints.shift();

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (dataPoints.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
      submissionCountEl.textContent = submissions.length;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 10; i++) {
        const x = (width / 10) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      if (dataPoints.length < 2) return;

      const values = dataPoints.map(p => p.value);
      const min = Math.min(...values) - 5;
      const max = Math.max(...values) + 5;
      const range = max - min || 1;

      const xStep = width / (MAX_POINTS - 1);

      // Area fill
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = index * xStep;
        const y = height - ((point.value - min) / range) * (height - 30) - 15;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo((dataPoints.length - 1) * xStep, height - 10);
      ctx.lineTo(0, height - 10);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(34, 197, 94, 0.05)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = index * xStep;
        const y = height - ((point.value - min) / range) * (height - 30) - 15;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((point, index) => {
        const x = index * xStep;
        const y = height - ((point.value - min) / range) * (height - 30) - 15;
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = 'rgba(229, 231, 235, 0.8)';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Min: ${Math.min(...values)}`, 10, height - 12);
      ctx.fillText(`Max: ${Math.max(...values)}`, width - 70, 16);
    }

    function startFeed() {
      if (timer) return;
      addDataPoint();
      timer = setInterval(addDataPoint, 1000);
    }

    function stopFeed() {
      clearInterval(timer);
      timer = null;
    }

    function resetDashboard() {
      stopFeed();
      dataPoints = [];
      submissions = [];
      recordsTableBody.innerHTML = `
        <tr>
          <td colspan="5" style="color: var(--muted); text-align: center;">No records submitted yet</td>
        </tr>
      `;
      formSuccess.textContent = '';
      updateMetrics();
      drawChart();
    }

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ['nameError', 'categoryError', 'priorityError', 'notesError'].forEach(id => {
        setError(id, '');
      });
      formSuccess.textContent = '';
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.name.trim()) {
        setError('nameError', 'Name is required.');
        valid = false;
      } else if (data.name.trim().length < 3) {
        setError('nameError', 'Name must be at least 3 characters.');
        valid = false;
      }

      if (!data.category) {
        setError('categoryError', 'Please select a category.');
        valid = false;
      }

      if (!data.priority) {
        setError('priorityError', 'Please select a priority.');
        valid = false;
      }

      if (data.notes.length > 200) {
        setError('notesError', 'Notes must be 200 characters or fewer.');
        valid = false;
      }

      return valid;
    }

    function priorityBadge(priority) {
      const cls =
        priority === 'High' ? 'badge-high' :
        priority === 'Medium' ? 'badge-medium' : 'badge-low';

      return `<span class="badge ${cls}">${priority}</span>`;
    }

    function renderTable() {
      if (submissions.length === 0) {
        recordsTableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted); text-align: center;">No records submitted yet</td>
          </tr>
        `;
        return;
      }

      recordsTableBody.innerHTML = submissions
        .slice()
        .reverse()
        .map(item => `
          <tr>
            <td>${item.time}</td>
            <td>${escapeHtml(item.name)}</td>
            <td>${escapeHtml(item.category)}</td>
            <td>${priorityBadge(item.priority)}</td>
            <td>${escapeHtml(item.notes || '-')}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = {
        name: document.getElementById('name').value,
        category: document.getElementById('category').value,
        priority: document.getElementById('priority').value,
        notes: document.getElementById('notes').value.trim()
      };

      if (!validateForm(formData)) return;

      submissions.push({
        ...formData,
        time: new Date().toLocaleString()
      });

      renderTable();
      updateMetrics();
      formSuccess.textContent = 'Record submitted successfully.';
      eventForm.reset();
    });

    startBtn.addEventListener('click', startFeed);
    stopBtn.addEventListener('click', stopFeed);
    resetBtn.addEventListener('click', resetDashboard);

    // Initial render
    updateMetrics();
    drawChart();
    startFeed();
  </script>
</body>
</html>
```

