        <button id="stopBtn">Stop</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>
    </div>

    <div class="grid">
      <section class="metrics">
        <div class="metric">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
          <div class="sub">Latest reading</div>
        </div>
