          <div class="sub">Rolling average</div>
        </div>
        <div class="metric">
          <div class="label">Peak</div>
          <div class="value" id="peakValue">0</div>
          <div class="sub">Highest observed</div>
        </div>
        <div class="metric">
          <div class="label">Samples</div>
          <div class="value" id="sampleCount">0</div>
          <div class="sub">Total points collected</div>
        </div>
      </section>

      <section class="card chart-card">
        <h2>Live Data Chart</h2>
        <div class="chart-wrap">
          <canvas id="chart"></canvas>
        </div>
      </section>

      <section class="card form-card">
        <h2>Submit Incident</h2>
        <form id="incidentForm" novalidate>
          <div class="field">
            <label for="name">Name</label>
            <input id="name" name="name" type="text" placeholder="Jane Doe" />
            <div class="error" id="nameError"></div>
          </div>

          <div class="field">
            <label for="email">Email</label>
            <input id="email" name="email" type="email" placeholder="jane@example.com" />
            <div class="error" id="emailError"></div>
          </div>

          <div class="field">
            <label for="severity">Severity</label>
            <select id="severity" name="severity">
              <option value="">Select severity</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
            <div class="error" id="severityError"></div>
          </div>

          <div class="field">
            <label for="message">Message</label>
            <textarea id="message" name="message" rows="4" placeholder="Describe the issue..."></textarea>
            <div class="error" id="messageError"></div>
          </div>

          <button type="submit" class="primary">Submit Report</button>
          <div class="status" id="formStatus"></div>
        </form>
      </section>

      <section class="card table-card">
        <h2>Submitted Reports</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Email</th>
              <th>Severity</th>
              <th>Message</th>
            </tr>
          </thead>
          <tbody id="reportTableBody">
            <tr>
              <td colspan="5" style="color: var(--muted);">No reports submitted yet.</td>
            </tr>
          </tbody>
        </table>
      </section>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const sampleCountEl = document.getElementById('sampleCount');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const form = document.getElementById('incidentForm');
    const formStatus = document.getElementById('formStatus');
    const reportTableBody = document.getElementById('reportTableBody');

    const fields = {
      name: document.getElementById('name'),
      email: document.getElementById('email'),
      severity: document.getElementById('severity'),
      message: document.getElementById('message')
    };

    const errors = {
      name: document.getElementById('nameError'),
      email: document.getElementById('emailError'),
      severity: document.getElementById('severityError'),
      message: document.getElementById('messageError')
    };

    let data = [];
    let timer = null;
    const maxPoints = 50;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = chartCanvas.getBoundingClientRect();
      chartCanvas.width = rect.width * dpr;
      chartCanvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function generateNextValue() {
      const last = data.length ? data[data.length - 1] : 50;
      const drift = (Math.random() - 0.5) * 12;
      let next = last + drift;
      next = Math.max(10, Math.min(100, next));
      return Number(next.toFixed(1));
    }

    function addDataPoint() {
      const value = generateNextValue();
      const point = {
        time: new Date(),
        value
      };
      data.push(point);
      if (data.length > maxPoints) data.shift();
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (!data.length) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        sampleCountEl.textContent = '0';
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      sampleCountEl.textContent = String(data.length);
    }

    function drawChart() {
      const rect = chartCanvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      const padding = 36;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 5; i++) {
        const x = padding + (chartW / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = 'rgba(148, 163, 184, 0.9)';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';

      for (let i = 0; i <= 5; i++) {
        const value = 100 - (90 / 5) * i;
        const y = padding + (chartH / 5) * i;
        ctx.fillText(value.toFixed(0), padding - 8, y);
      }

      if (!data.length) {
        ctx.fillStyle = 'rgba(148, 163, 184, 0.8)';
        ctx.textAlign = 'center';
        ctx.fillText('No live data yet. Click Start.', width / 2, height / 2);
        return;
      }

      const minY = 10;
      const maxY = 100;

      const xStep = data.length > 1 ? chartW / (data.length - 1) : chartW;

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = padding + ((maxY - point.value) / (maxY - minY)) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + (data.length - 1) * xStep, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = padding + ((maxY - point.value) / (maxY - minY)) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#60a5fa';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = padding + ((maxY - point.value) / (maxY - minY)) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });
    }

    function startFeed() {
      if (timer) return;
      addDataPoint();
      timer = setInterval(addDataPoint, 1000);
    }

    function stopFeed() {
      clearInterval(timer);
      timer = null;
    }

    function resetFeed() {
      stopFeed();
      data = [];
      updateMetrics();
      drawChart();
    }

    function validateEmail(email) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function clearErrors() {
      Object.values(errors).forEach(el => el.textContent = '');
      formStatus.textContent = '';
    }

    function validateForm() {
      clearErrors();
      let valid = true;

      if (!fields.name.value.trim()) {
        errors.name.textContent = 'Name is required.';
        valid = false;
      }

      if (!fields.email.value.trim()) {
        errors.email.textContent = 'Email is required.';
        valid = false;
      } else if (!validateEmail(fields.email.value.trim())) {
        errors.email.textContent = 'Enter a valid email address.';
        valid = false;
      }

      if (!fields.severity.value) {
        errors.severity.textContent = 'Please select a severity.';
        valid = false;
      }

      if (!fields.message.value.trim()) {
        errors.message.textContent = 'Message is required.';
        valid = false;
      } else if (fields.message.value.trim().length < 10) {
        errors.message.textContent = 'Message must be at least 10 characters.';
        valid = false;
      }

      return valid;
    }

    function addReportRow(report) {
      const emptyRow = reportTableBody.querySelector('td[colspan="5"]');
      if (emptyRow) {
        reportTableBody.innerHTML = '';
      }

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>${report.time}</td>
        <td>${escapeHtml(report.name)}</td>
        <td>${escapeHtml(report.email)}</td>
        <td><span class="badge ${report.severity}">${report.severity}</span></td>
        <td>${escapeHtml(report.message)}</td>
      `;
      reportTableBody.prepend(tr);
    }

    function escapeHtml(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();

      if (!validateForm()) {
        formStatus.textContent = 'Please fix the errors above.';
        formStatus.style.color = '#fca5a5';
        return;
      }

      const report = {
        time: new Date().toLocaleTimeString(),
        name: fields.name.value.trim(),
        email: fields.email.value.trim(),
        severity: fields.severity.value,
        message: fields.message.value.trim()
      };

      formStatus.textContent = 'Submitting...';
      formStatus.style.color = '#93c5fd';

      // Simulate async request
      await new Promise(resolve => setTimeout(resolve, 700));

      addReportRow(report);
      form.reset();
      clearErrors();
      formStatus.textContent = 'Report submitted successfully.';
      formStatus.style.color = '#86efac';
    });

    startBtn.addEventListener('click', startFeed);
    stopBtn.addEventListener('click', stopFeed);
    resetBtn.addEventListener('click', resetFeed);

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    updateMetrics();
    drawChart();
  </script>
</body>
</html>
```

## What this does

- Simulates live incoming data every second
- Draws a real-time line chart on a `<canvas>`
- Updates summary metrics:
  - current value
  - average
  - peak
  - sample count
- Handles form validation for:
  - name
  - email
  - severity
  - message length
- Simulates async form submission
- Adds submitted reports to a table

