<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p><span class="status-dot"></span>Live simulation running in browser</p>
      </div>
      <div class="controls">
        <select id="speedSelect" class="btn">
          <option value="2000">Update: 2s</option>
          <option value="1000">Update: 1s</option>
          <option value="500">Update: 0.5s</option>
        </select>
        <button id="toggleBtn" class="btn primary">Pause</button>
        <button id="addRandomBtn" class="btn">Add Random Record</button>
      </div>
    </div>

    <div class="grid">
      <div class="card span-3">
        <div class="kpi">
          <div class="kpi-label">Active Users</div>
          <div class="kpi-value" id="kpiUsers">0</div>
          <div class="kpi-trend up" id="trendUsers">+0%</div>
        </div>
      </div>

      <div class="card span-3">
        <div class="kpi">
          <div class="kpi-label">Transactions/min</div>
          <div class="kpi-value" id="kpiTx">0</div>
          <div class="kpi-trend up" id="trendTx">+0%</div>
        </div>
      </div>

      <div class="card span-3">
        <div class="kpi">
          <div class="kpi-label">Error Rate</div>
          <div class="kpi-value" id="kpiErrors">0%</div>
          <div class="kpi-trend down" id="trendErrors">-0%</div>
        </div>
      </div>

      <div class="card span-3">
        <div class="kpi">
          <div class="kpi-label">Revenue</div>
          <div class="kpi-value" id="kpiRevenue">$0</div>
          <div class="kpi-trend up" id="trendRevenue">+0%</div>
        </div>
      </div>

      <div class="card span-8">
        <h2>Traffic Over Time</h2>
        <div class="chart-wrap">
          <canvas id="lineChart" width="900" height="280"></canvas>
        </div>
      </div>

      <div class="card span-4">
        <h2>Live Event Feed</h2>
        <div class="feed" id="eventFeed"></div>
      </div>

      <div class="card span-6">
        <h2>Category Distribution</h2>
        <div class="chart-wrap">
          <canvas id="barChart" width="600" height="280"></canvas>
        </div>
      </div>

      <div class="card span-6">
        <h2>Submit Incident Report</h2>
        <form id="incidentForm" novalidate>
          <div class="form-row">
            <div class="field">
              <label for="title">Title</label>
              <input id="title" name="title" type="text" placeholder="Service latency spike" />
              <div class="error" id="titleError"></div>
            </div>
            <div class="field">
              <label for="severity">Severity</label>
              <select id="severity" name="severity">
                <option value="">Select severity</option>
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </select>
              <div class="error" id="severityError"></div>
            </div>
          </div>

          <div class="field">
            <label for="owner">Owner Email</label>
            <input id="owner" name="owner" type="email" placeholder="owner@example.com" />
            <div class="error" id="ownerError"></div>
          </div>

          <div class="field">
            <label for="description">Description</label>
            <textarea id="description" name="description" placeholder="Describe the issue and impact..."></textarea>
            <div class="error" id="descriptionError"></div>
          </div>

          <div style="display:flex; gap:12px; align-items:center; flex-wrap:wrap;">
            <button type="submit" class="btn primary">Submit Report</button>
            <button type="reset" class="btn">Reset</button>
            <div id="formMessage" class="success"></div>
          </div>
        </form>
      </div>

      <div class="card span-12">
        <h2>Incident Queue</h2>
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Title</th>
              <th>Severity</th>
              <th>Owner</th>
              <th>Created</th>
            </tr>
          </thead>
          <tbody id="incidentTableBody"></tbody>
        </table>
        <div class="footer-note">New form submissions are added to the table in real time.</div>
      </div>
    </div>
  </div>

  <script>
    const state = {
      running: true,
      intervalMs: 2000,
      timer: null,
      maxPoints: 24,
      trafficSeries: [],
      categories: {
        API: 12,
        Web: 18,
        Auth: 7,
        Billing: 10,
        Search: 14
      },
      incidents: [],
      metrics: {
        users: 1240,
        tx: 320,
        errors: 1.8,
        revenue: 12450
      }
    };

    const els = {
      kpiUsers: document.getElementById('kpiUsers'),
      kpiTx: document.getElementById('kpiTx'),
      kpiErrors: document.getElementById('kpiErrors'),
      kpiRevenue: document.getElementById('kpiRevenue'),
      trendUsers: document.getElementById('trendUsers'),
      trendTx: document.getElementById('trendTx'),
      trendErrors: document.getElementById('trendErrors'),
      trendRevenue: document.getElementById('trendRevenue'),
      eventFeed: document.getElementById('eventFeed'),
      lineChart: document.getElementById('lineChart'),
      barChart: document.getElementById('barChart'),
      toggleBtn: document.getElementById('toggleBtn'),
      speedSelect: document.getElementById('speedSelect'),
      addRandomBtn: document.getElementById('addRandomBtn'),
      incidentForm: document.getElementById('incidentForm'),
      incidentTableBody: document.getElementById('incidentTableBody'),
      formMessage: document.getElementById('formMessage')
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function randInt(min, max) {
      return Math.floor(rand(min, max + 1));
    }

    function formatCurrency(value) {
      return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        maximumFractionDigits: 0
      }).format(value);
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function seedTraffic() {
      const now = Date.now();
      for (let i = state.maxPoints - 1; i >= 0; i--) {
        state.trafficSeries.push({
          time: new Date(now - i * state.intervalMs),
          value: randInt(80, 180)
        });
      }
    }

    function updateMetrics() {
      const prev = { ...state.metrics };

      state.metrics.users = clamp(Math.round(state.metrics.users + rand(-40, 55)), 800, 3000);
      state.metrics.tx = clamp(Math.round(state.metrics.tx + rand(-20, 25)), 120, 900);
      state.metrics.errors = clamp(+(state.metrics.errors + rand(-0.4, 0.35)).toFixed(1), 0.1, 8.5);
      state.metrics.revenue = clamp(Math.round(state.metrics.revenue + rand(-400, 900)), 5000, 50000);

      renderKPIs(prev);
    }

    function renderKPIs(prev) {
      els.kpiUsers.textContent = state.metrics.users.toLocaleString();
      els.kpiTx.textContent = state.metrics.tx.toLocaleString();
      els.kpiErrors.textContent = state.metrics.errors.toFixed(1) + '%';
      els.kpiRevenue.textContent = formatCurrency(state.metrics.revenue);

      setTrend(els.trendUsers, prev.users, state.metrics.users, false);
      setTrend(els.trendTx, prev.tx, state.metrics.tx, false);
      setTrend(els.trendErrors, prev.errors, state.metrics.errors, true);
      setTrend(els.trendRevenue, prev.revenue, state.metrics.revenue, false);
    }

    function setTrend(el, oldVal, newVal, invertGood) {
      const pct = oldVal === 0 ? 0 : (((newVal - oldVal) / oldVal) * 100);
      const positive = pct >= 0;
      const good = invertGood ? !positive : positive;
      el.textContent = `${positive ? '+' : ''}${pct.toFixed(1)}%`;
      el.className = 'kpi-trend ' + (good ? 'up' : 'down');
    }

    function updateTrafficSeries() {
      const last = state.trafficSeries[state.trafficSeries.length - 1]?.value ?? 120;
      const next = clamp(Math.round(last + rand(-25, 30)), 40, 220);
      state.trafficSeries.push({
        time: new Date(),
        value: next
      });
      if (state.trafficSeries.length > state.maxPoints) {
        state.trafficSeries.shift();
      }
    }

    function updateCategories() {
      Object.keys(state.categories).forEach(key => {
        state.categories[key] = clamp(state.categories[key] + randInt(-2, 3), 2, 30);
      });
    }

    function addFeedEvent(message, type = 'info') {
      const div = document.createElement('div');
      div.className = 'feed-item';
      const color =
        type === 'error' ? 'var(--danger)' :
        type === 'warn' ? 'var(--warning)' :
        'var(--accent-2)';
      div.innerHTML = `<div style="color:${color}; font-weight:600;">${message}</div><small>${formatTime()}</small>`;
      els.eventFeed.prepend(div);
      while (els.eventFeed.children.length > 12) {
        els.eventFeed.removeChild(els.eventFeed.lastChild);
      }
    }

    function randomFeedEvent() {
      const events = [
        ['API latency normalized', 'info'],
        ['New user signup burst detected', 'info'],
        ['Payment retry threshold exceeded', 'warn'],
        ['Search index refresh completed', 'info'],
        ['Authentication failures increased', 'error'],
        ['Background job queue drained', 'info'],
        ['Cache hit ratio improved', 'info'],
        ['Webhook delivery delays observed', 'warn']
      ];
      const [msg, type] = events[randInt(0, events.length - 1)];
      addFeedEvent(msg, type);
    }

    function drawLineChart() {
      const canvas = els.lineChart;
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      const pad = { top: 20, right: 20, bottom: 35, left: 40 };
      const innerW = w - pad.left - pad.right;
      const innerH = h - pad.top - pad.bottom;

      const values = state.trafficSeries.map(p => p.value);
      const min = Math.min(...values) - 10;
      const max = Math.max(...values) + 10;

      ctx.strokeStyle = 'rgba(148,163,184,0.25)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 4; i++) {
        const y = pad.top + (innerH / 4) * i;
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(w - pad.right, y);
        ctx.stroke();
      }

      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      for (let i = 0; i <= 4; i++) {
        const val = Math.round(max - ((max - min) / 4) * i);
        const y = pad.top + (innerH / 4) * i;
        ctx.fillText(String(val), 6, y + 4);
      }

      const points = state.trafficSeries.map((p, i) => {
        const x = pad.left + (i / (state.trafficSeries.length - 1 || 1)) * innerW;
        const y = pad.top + ((max - p.value) / (max - min || 1)) * innerH;
        return { x, y, value: p.value, time: p.time };
      });

      const gradient = ctx.createLinearGradient(0, pad.top, 0, h - pad.bottom);
      gradient.addColorStop(0, 'rgba(59,130,246,0.35)');
      gradient.addColorStop(1, 'rgba(59,130,246,0.02)');

      ctx.beginPath();
      ctx.moveTo(points[0].x, h - pad.bottom);
      points.forEach((pt, i) => {
        if (i === 0) ctx.lineTo(pt.x, pt.y);
        else ctx.lineTo(pt.x, pt.y);
      });
      ctx.lineTo(points[points.length - 1].x, h - pad.bottom);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      ctx.beginPath();
      points.forEach((pt, i) => {
        if (i === 0) ctx.moveTo(pt.x, pt.y);
        else ctx.lineTo(pt.x, pt.y);
      });
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      points.forEach((pt, i) => {
        if (i % 4 === 0 || i === points.length - 1) {
          ctx.fillStyle = '#94a3b8';
          ctx.fillText(
            pt.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            pt.x - 20,
            h - 12
          );
        }
      });

      points.forEach(pt => {
        ctx.beginPath();
        ctx.arc(pt.x, pt.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#93c5fd';
        ctx.fill();
      });
    }

    function drawBarChart() {
      const canvas = els.barChart;
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      const pad = { top: 20, right: 20, bottom: 40, left: 40 };
      const innerW = w - pad.left - pad.right;
      const innerH = h - pad.top - pad.bottom;

      const entries = Object.entries(state.categories);
      const max = Math.max(...entries.map(([, v]) => v), 1);
      const barWidth = innerW / entries.length * 0.6;
      const gap = innerW / entries.length * 0.4;

      ctx.strokeStyle = 'rgba(148,163,184,0.25)';
      for (let i = 0; i <= 4; i++) {
        const y = pad.top + (innerH / 4) * i;
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(w - pad.right, y);
        ctx.stroke();
      }

      entries.forEach(([label, value], i) => {
        const x = pad.left + i * (barWidth + gap) + gap / 2;
        const barH = (value / max) * innerH;
        const y = h - pad.bottom - barH;

        const grad = ctx.createLinearGradient(0, y, 0, h - pad.bottom);
        grad.addColorStop(0, '#22c55e');
        grad.addColorStop(1, '#166534');

        ctx.fillStyle = grad;
        roundRect(ctx, x, y, barWidth, barH, 10, true, false);

        ctx.fillStyle = '#e5e7eb';
        ctx.font = '12px sans-serif';
        ctx.fillText(String(value), x + barWidth / 2 - 8, y - 8);

        ctx.fillStyle = '#94a3b8';
        ctx.fillText(label, x + 4, h - 14);
      });
    }

    function roundRect(ctx, x, y, width, height, radius, fill, stroke) {
      if (typeof radius === 'number') {
        radius = { tl: radius, tr: radius, br: radius, bl: radius };
      }
      ctx.beginPath();
      ctx.moveTo(x + radius.tl, y);
      ctx.lineTo(x + width - radius.tr, y);
      ctx.quadraticCurveTo(x + width, y, x + width, y + radius.tr);
      ctx.lineTo(x + width, y + height - radius.br);
      ctx.quadraticCurveTo(x + width, y + height, x + width - radius.br, y + height);
      ctx.lineTo(x + radius.bl, y + height);
      ctx.quadraticCurveTo(x, y + height, x, y + height - radius.bl);
      ctx.lineTo(x, y + radius.tl);
      ctx.quadraticCurveTo(x, y, x + radius.tl, y);
      ctx.closePath();
      if (fill) ctx.fill();
      if (stroke) ctx.stroke();
    }

    function renderIncidentTable() {
      els.incidentTableBody.innerHTML = '';
      state.incidents.forEach(item => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${item.id}</td>
          <td>${escapeHtml(item.title)}</td>
          <td><span class="badge ${item.severity}">${item.severity}</span></td>
          <td>${escapeHtml(item.owner)}</td>
          <td>${item.created}</td>
        `;
        els.incidentTableBody.appendChild(tr);
      });
    }

    function escapeHtml(str) {
      return str.replace(/[&<>"']/g, ch => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      }[ch]));
    }

    function validateForm(data) {
      const errors = {};

      if (!data.title.trim() || data.title.trim().length < 4) {
        errors.title = 'Title must be at least 4 characters.';
      }

      if (!data.severity) {
        errors.severity = 'Please select a severity.';
      }

      const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.owner);
      if (!emailOk) {
        errors.owner = 'Enter a valid email address.';
      }

      if (!data.description.trim() || data.description.trim().length < 10) {
        errors.description = 'Description must be at least 10 characters.';
      }

      return errors;
    }

    function showFormErrors(errors) {
      document.getElementById('titleError').textContent = errors.title || '';
      document.getElementById('severityError').textContent = errors.severity || '';
      document.getElementById('ownerError').textContent = errors.owner || '';
      document.getElementById('descriptionError').textContent = errors.description || '';
    }

    function clearFormErrors() {
      showFormErrors({});
      els.formMessage.textContent = '';
    }

    function addIncident(data) {
      const incident = {
        id: 'INC-' + String(state.incidents.length + 1).padStart(4, '0'),
        title: data.title.trim(),
        severity: data.severity,
        owner: data.owner.trim(),
        description: data.description.trim(),
        created: formatTime()
      };
      state.incidents.unshift(incident);
      renderIncidentTable();
      addFeedEvent(`Incident created: ${incident.title}`, incident.severity === 'high' ? 'error' : 'warn');
    }

    function addRandomIncident() {
      const samples = [
        { title: 'API timeout spike', severity: 'high', owner: 'api-team@example.com', description: 'Elevated timeout rate observed on public API.' },
        { title: 'Search relevance drift', severity: 'medium', owner: 'search@example.com', description: 'Users report lower quality search results in top queries.' },
        { title: 'Minor UI rendering issue', severity: 'low', owner: 'frontend@example.com', description: 'Dashboard widgets overlap on smaller tablet screens.' }
      ];
      addIncident(samples[randInt(0, samples.length - 1)]);
    }

    function tick() {
      updateMetrics();
      updateTrafficSeries();
      updateCategories();
      drawLineChart();
      drawBarChart();
      randomFeedEvent();
    }

    function startTimer() {
      stopTimer();
      state.timer = setInterval(() => {
        if (state.running) tick();
      }, state.intervalMs);
    }

    function stopTimer() {
      if (state.timer) clearInterval(state.timer);
    }

    els.toggleBtn.addEventListener('click', () => {
      state.running = !state.running;
      els.toggleBtn.textContent = state.running ? 'Pause' : 'Resume';
      addFeedEvent(state.running ? 'Live updates resumed' : 'Live updates paused', 'info');
    });

    els.speedSelect.addEventListener('change', (e) => {
      state.intervalMs = Number(e.target.value);
      startTimer();
      addFeedEvent(`Update interval changed to ${state.intervalMs}ms`, 'info');
    });

    els.addRandomBtn.addEventListener('click', () => {
      addRandomIncident();
    });

    els.incidentForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearFormErrors();

      const data = {
        title: document.getElementById('title').value,
        severity: document.getElementById('severity').value,
        owner: document.getElementById('owner').value,
        description: document.getElementById('description').value
      };

      const errors = validateForm(data);
      if (Object.keys(errors).length) {
        showFormErrors(errors);
        return;
      }

      addIncident(data);
      els.formMessage.textContent = 'Incident submitted successfully.';
      els.incidentForm.reset();
    });

    els.incidentForm.addEventListener('reset', () => {
      setTimeout(clearFormErrors, 0);
    });

    function init() {
      seedTraffic();
      renderKPIs({ ...state.metrics });
      drawLineChart();
      drawBarChart();
      addFeedEvent('Dashboard initialized', 'info');

      addIncident({
        title: 'Initial monitoring baseline',
        severity: 'low',
        owner: 'ops@example.com',
        description: 'Baseline monitoring event created automatically.'
      });

      startTimer();
    }

    init();
  </script>
</body>
</html>
```

## Features included

- Real-time simulated updates with `setInterval`
- Canvas-based line chart
- Canvas-based bar chart
- Live feed panel
- KPI metric cards with trend indicators
- Form validation
- Incident submission handling
- Dynamic table rendering
- Pause/resume and speed controls

