    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: linear-gradient(180deg, #0b1220 0%, #0f172a 100%);
      color: var(--text);
    }

    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 24px;
    }

    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      margin-bottom: 24px;
      flex-wrap: wrap;
    }

    .header h1 {
      margin: 0;
      font-size: 1.8rem;
    }

    .header p {
      margin: 6px 0 0;
      color: var(--muted);
    }

    .status {
      display: flex;
      align-items: center;
      gap: 10px;
      background: var(--panel);
      border: 1px solid var(--border);
      padding: 12px 16px;
      border-radius: 999px;
      box-shadow: var(--shadow);
    }

    .status-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--accent);
      box-shadow: 0 0 10px var(--accent);
      animation: pulse 1.5s infinite;
    }

    @keyframes pulse {
      0% { transform: scale(1); opacity: 1; }
      50% { transform: scale(1.4); opacity: 0.6; }
      100% { transform: scale(1); opacity: 1; }
    }

    .grid {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 20px;
    }

    .card {
      background: rgba(17, 24, 39, 0.9);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 20px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(8px);
    }

    .kpi {
      grid-column: span 3;
    }

    .kpi h3 {
      margin: 0 0 10px;
      font-size: 0.95rem;
      color: var(--muted);
      font-weight: 600;
    }

    .kpi .value {
      font-size: 2rem;
      font-weight: 800;
      margin-bottom: 8px;
    }

    .kpi .sub {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .chart-card {
      grid-column: span 8;
    }

    .controls-card {
      grid-column: span 4;
    }

    .form-card {
      grid-column: span 5;
    }

    .table-card {
      grid-column: span 7;
    }

    .card-title {
      margin: 0 0 16px;
      font-size: 1.1rem;
      font-weight: 700;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
