        <span id="statusText">Live stream active</span>
      </div>
    </div>

    <div class="grid">
      <div class="card kpi">
        <h3>Current Value</h3>
        <div class="value" id="currentValue">0</div>
        <div class="sub">Latest incoming metric</div>
      </div>

      <div class="card kpi">
        <h3>Average</h3>
        <div class="value" id="averageValue">0</div>
        <div class="sub">Rolling average</div>
      </div>

      <div class="card kpi">
        <h3>Peak</h3>
