  <script>
    const labels = [];
    const dataPoints = [];
    const maxPoints = 20;
    let streamInterval = null;
    let reportEntries = [];

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const entryCountEl = document.getElementById("entryCount");
    const streamStateEl = document.getElementById("streamState");
    const statusTextEl = document.getElementById("statusText");
    const statusDotEl = document.getElementById("statusDot");

    const ctx = document.getElementById("liveChart").getContext("2d");
    const liveChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Metric",
          data: dataPoints,
          borderColor: "#3b82f6",
          backgroundColor: "rgba(59,130,246,0.2)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: "#93c5fd"
        }]
      },
      options: {
        responsive: true,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.15)" }
          },
          y: {
            beginAtZero: true,
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.15)" }
          }
        }
      }
    });

    function getRandomValue() {
      return Math.floor(Math.random() * 40) + 60;
    }

    function addDataPoint(value = getRandomValue()) {
      const now = new Date();
      const timeLabel = now.toLocaleTimeString();

      labels.push(timeLabel);
      dataPoints.push(value);

      if (labels.length > maxPoints) labels.shift();
      if (dataPoints.length > maxPoints) dataPoints.shift();

      liveChart.update();
      updateKPIs();
    }

    function updateKPIs() {
      const current = dataPoints[dataPoints.length - 1] || 0;
      const avg = dataPoints.length
        ? (dataPoints.reduce((sum, val) => sum + val, 0) / dataPoints.length).toFixed(1)
        : 0;
      const peak = dataPoints.length ? Math.max(...dataPoints) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peak;
      entryCountEl.textContent = reportEntries.length;
    }

    function startStream() {
      if (streamInterval) return;
      streamInterval = setInterval(() => addDataPoint(), 1000);
      streamStateEl.textContent = "Running";
      statusTextEl.textContent = "Live stream active";
      statusDotEl.style.background = "#22c55e";
      statusDotEl.style.boxShadow = "0 0 10px #22c55e";
    }

    function stopStream() {
      clearInterval(streamInterval);
      streamInterval = null;
      streamStateEl.textContent = "Stopped";
      statusTextEl.textContent = "Live stream paused";
      statusDotEl.style.background = "#f59e0b";
      statusDotEl.style.boxShadow = "0 0 10px #f59e0b";
    }

    function resetStream() {
      stopStream();
      labels.length = 0;
      dataPoints.length = 0;
      liveChart.update();
      updateKPIs();
    }

    document.getElementById("startBtn").addEventListener("click", startStream);
    document.getElementById("stopBtn").addEventListener("click", stopStream);
    document.getElementById("resetBtn").addEventListener("click", resetStream);
    document.getElementById("injectBtn").addEventListener("click", () => {
      addDataPoint(140);
    });

    function showError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ["nameError", "categoryError", "severityError", "descriptionError"].forEach(id => {
        document.getElementById(id).textContent = "";
      });
      document.getElementById("formSuccess").textContent = "";
    }

    function getSeverityBadge(severity) {
      const cls =
        severity === "High" ? "badge-high" :
        severity === "Medium" ? "badge-medium" :
        "badge-low";
      return `<span class="badge ${cls}">${severity}</span>`;
    }

    function renderTable() {
      const tbody = document.getElementById("reportTableBody");

      if (reportEntries.length === 0) {
        tbody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted); text-align: center;">
              No reports submitted yet.
            </td>
          </tr>
        `;
        return;
      }

      tbody.innerHTML = reportEntries.map(entry => `
        <tr>
          <td>${entry.time}</td>
          <td>${entry.name}</td>
          <td>${entry.category}</td>
          <td>${getSeverityBadge(entry.severity)}</td>
          <td>${entry.description}</td>
        </tr>
      `).join("");
    }

    document.getElementById("reportForm").addEventListener("submit", function (e) {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const severity = document.getElementById("severity").value;
      const description = document.getElementById("description").value.trim();

      let isValid = true;

      if (!name || name.length < 2) {
        showError("nameError", "Please enter a valid name.");
        isValid = false;
      }

      if (!category) {
        showError("categoryError", "Please select a category.");
        isValid = false;
      }

      if (!severity) {
        showError("severityError", "Please select a severity.");
        isValid = false;
      }

      if (!description || description.length < 10) {
        showError("descriptionError", "Description must be at least 10 characters.");
        isValid = false;
      }

      if (!isValid) return;

      const entry = {
        time: new Date().toLocaleTimeString(),
        name,
        category,
        severity,
        description
      };

      reportEntries.unshift(entry);
      renderTable();
      updateKPIs();

      document.getElementById("formSuccess").textContent = "Report submitted successfully.";
      this.reset();
    });

    addDataPoint();
    addDataPoint();
    addDataPoint();
    startStream();
    renderTable();
    updateKPIs();
  </script>
</body>
</html>
```

## Features included

- Real-time chart updates every second
- Manual spike injection
- Start/stop/reset stream controls
- KPI summary cards
- Form validation
- Dynamic table rendering
- Responsive layout

