        <section class="card">
          <div class="panel-header">
            <h2>Activity Log</h2>
          </div>
          <ul class="log-list" id="logList"></ul>
        </section>
      </aside>
    </div>

    <div class="footer-note">
      Built with vanilla HTML, CSS, and JavaScript.
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chartCanvas");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");
    const streamStatusEl = document.getElementById("streamStatus");
    const logListEl = document.getElementById("logList");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const alertForm = document.getElementById("alertForm");
    const formSuccess = document.getElementById("formSuccess");

    const fields = {
      alertName: document.getElementById("alertName"),
      threshold: document.getElementById("threshold"),
      severity: document.getElementById("severity"),
      notes: document.getElementById("notes")
    };

    const errors = {
      alertName: document.getElementById("alertNameError"),
      threshold: document.getElementById("thresholdError"),
      severity: document.getElementById("severityError"),
      notes: document.getElementById("notesError")
    };

    let data = [];
    let maxPoints = 40;
    let intervalId = null;
    let peakValue = 0;
    let eventCount = 0;

    function resizeCanvas() {
      const rect = canvas.parentElement.getBoundingClientRect();
      canvas.width = rect.width - 20;
      canvas.height = rect.height - 20;
      drawChart();
    }

    window.addEventListener("resize", resizeCanvas);

    function generateDataPoint() {
      const last = data.length ? data[data.length - 1].value : 50;
      const variation = (Math.random() - 0.5) * 18;
      let next = Math.max(5, Math.min(100, last + variation));
      next = Number(next.toFixed(1));

      const point = {
        time: new Date(),
        value: next
      };

      data.push(point);
      if (data.length > maxPoints) data.shift();

      if (next > peakValue) peakValue = next;

      updateStats();
      drawChart();
      checkAlerts(next);
    }

    function updateStats() {
      if (!data.length) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        return;
      }

      const current = data[data.length - 1].value;
      const avg = data.reduce((sum, p) => sum + p.value, 0) / data.length;

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peakValue.toFixed(1);
      eventCountEl.textContent = eventCount;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // Background grid
      const padding = 40;
      const chartW = w - padding * 2;
      const chartH = h - padding * 2;

      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(w - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 5; i++) {
        const x = padding + (chartW / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, h - padding);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";

      for (let i = 0; i <= 5; i++) {
        const value = 100 - (100 / 5) * i;
        const y = padding + (chartH / 5) * i + 4;
        ctx.fillText(value.toFixed(0), padding - 8, y);
      }

      if (data.length < 2) return;

      // Area fill
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (chartW / (maxPoints - 1)) * index;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + (chartW / (maxPoints - 1)) * (data.length - 1);
      ctx.lineTo(lastX, h - padding);
      ctx.lineTo(padding, h - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, h - padding);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (chartW / (maxPoints - 1)) * index;
        const y = padding + chartH - (point.value / 100) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + (chartW / (maxPoints - 1)) * index;
        const y = padding + chartH - (point.value / 100) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });
    }

    function addLog(message) {
      eventCount++;
      eventCountEl.textContent = eventCount;

      const li = document.createElement("li");
      li.className = "log-item";

      const time = document.createElement("span");
      time.className = "log-time";
      time.textContent = new Date().toLocaleTimeString();

      const text = document.createElement("div");
      text.textContent = message;

      li.appendChild(time);
      li.appendChild(text);

      logListEl.prepend(li);

      while (logListEl.children.length > 12) {
        logListEl.removeChild(logListEl.lastChild);
      }
    }

    function startStream() {
      if (intervalId) return;
      intervalId = setInterval(generateDataPoint, 1000);
      streamStatusEl.textContent = "Running";
      streamStatusEl.style.background = "rgba(34,197,94,0.15)";
      streamStatusEl.style.color = "#86efac";
      addLog("Data stream started.");
    }

    function stopStream() {
      if (!intervalId) return;
      clearInterval(intervalId);
      intervalId = null;
      streamStatusEl.textContent = "Stopped";
      streamStatusEl.style.background = "rgba(239,68,68,0.15)";
      streamStatusEl.style.color = "#fca5a5";
      addLog("Data stream stopped.");
    }

    function resetDashboard() {
      data = [];
      peakValue = 0;
      drawChart();
      updateStats();
      addLog("Dashboard data reset.");
    }

    function validateForm() {
      let valid = true;
      formSuccess.textContent = "";

      Object.values(errors).forEach(el => el.textContent = "");

      const alertName = fields.alertName.value.trim();
      const threshold = fields.threshold.value.trim();
      const severity = fields.severity.value.trim();
      const notes = fields.notes.value.trim();

      if (!alertName || alertName.length < 3) {
        errors.alertName.textContent = "Alert name must be at least 3 characters.";
        valid = false;
      }

      const thresholdNum = Number(threshold);
      if (!threshold || Number.isNaN(thresholdNum) || thresholdNum < 0 || thresholdNum > 100) {
        errors.threshold.textContent = "Threshold must be a number between 0 and 100.";
        valid = false;
      }

      if (!severity) {
        errors.severity.textContent = "Please select a severity level.";
        valid = false;
      }

      if (notes.length > 200) {
        errors.notes.textContent = "Notes must be 200 characters or fewer.";
        valid = false;
      }

      return valid;
    }

    function getSavedAlerts() {
      return JSON.parse(localStorage.getItem("dashboardAlerts") || "[]");
    }

    function saveAlert(alert) {
      const alerts = getSavedAlerts();
      alerts.push(alert);
      localStorage.setItem("dashboardAlerts", JSON.stringify(alerts));
    }

    function checkAlerts(currentValue) {
      const alerts = getSavedAlerts();
      alerts.forEach(alert => {
        if (!alert.triggered && currentValue >= alert.threshold) {
          alert.triggered = true;
          addLog(`Alert triggered: "${alert.name}" at value ${currentValue.toFixed(1)} (${alert.severity})`);
        }
      });
      localStorage.setItem("dashboardAlerts", JSON.stringify(alerts));
    }

    alertForm.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      const alert = {
        name: fields.alertName.value.trim(),
        threshold: Number(fields.threshold.value),
        severity: fields.severity.value,
        notes: fields.notes.value.trim(),
        createdAt: new Date().toISOString(),
        triggered: false
      };

      saveAlert(alert);
      formSuccess.textContent = "Alert saved successfully.";
      addLog(`New alert created: "${alert.name}" with threshold ${alert.threshold}.`);

      alertForm.reset();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    // Initial seed data
    for (let i = 0; i < 12; i++) {
      generateDataPoint();
    }

    resizeCanvas();
    startStream();
  </script>
</body>
</html>
```

## Features included

- **Real-time charting** using `<canvas>`
- **Live stats**:
  - current value
  - average
  - peak
  - event count
- **Interactive controls**:
  - start stream
  - stop stream
  - reset data
- **Form handling**:
  - validation
  - success messaging
  - localStorage persistence
- **Activity log**
- **Alert triggering** when live data crosses saved thresholds

