<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, chart updates, and form submission handling in the browser.</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="success">Start Stream</button>
        <button id="stopBtn">Stop Stream</button>
        <button id="resetBtn" class="danger">Reset Data</button>
      </div>
    </div>

    <div class="metrics">
      <div class="metric-card">
        <div class="metric-label">Current Value</div>
        <div class="metric-value" id="currentValue">0</div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Average</div>
        <div class="metric-value" id="averageValue">0</div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Peak</div>
        <div class="metric-value" id="peakValue">0</div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Events Submitted</div>
        <div class="metric-value" id="eventCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Real-Time Chart</h2>
        <div class="chart-wrap">
          <canvas id="chartCanvas" width="800" height="340"></canvas>
        </div>
        <div class="legend">
          <span class="series-a">Sensor A</span>
          <span class="series-b">Sensor B</span>
        </div>
        <div class="footer-note">
          The chart updates every second with simulated streaming data.
        </div>
      </div>

      <div class="side-stack">
        <div class="panel">
          <h2>Submit Event</h2>
          <form id="eventForm" novalidate>
            <div class="field">
              <label for="title">Event Title</label>
              <input type="text" id="title" name="title" placeholder="e.g. Temperature spike" />
              <div class="error" id="titleError"></div>
            </div>

            <div class="field">
              <label for="severity">Severity</label>
              <select id="severity" name="severity">
                <option value="">Select severity</option>
                <option value="info">Info</option>
                <option value="warn">Warning</option>
              </select>
              <div class="error" id="severityError"></div>
            </div>

            <div class="field">
              <label for="description">Description</label>
              <textarea id="description" name="description" rows="4" placeholder="Describe the event..."></textarea>
              <div class="error" id="descriptionError"></div>
            </div>

            <button type="submit" class="primary">Submit Event</button>
            <div class="success-message" id="formSuccess"></div>
          </form>
        </div>

        <div class="panel">
          <h2>Activity Log</h2>
          <div class="log" id="activityLog"></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    const MAX_POINTS = 40;
    const dataA = [];
    const dataB = [];
    let intervalId = null;
    let submittedEvents = 0;

    const canvas = document.getElementById("chartCanvas");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");
    const activityLog = document.getElementById("activityLog");

    function randomValue(base = 50, variance = 20) {
      return Math.max(0, Math.round(base + (Math.random() - 0.5) * variance * 2));
    }

    function addDataPoint() {
      const nextA = randomValue(60, 18);
      const nextB = randomValue(45, 14);

      if (dataA.length >= MAX_POINTS) dataA.shift();
      if (dataB.length >= MAX_POINTS) dataB.shift();

      dataA.push(nextA);
      dataB.push(nextB);

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      const latest = dataA[dataA.length - 1] ?? 0;
      const avg = dataA.length
        ? (dataA.reduce((sum, v) => sum + v, 0) / dataA.length).toFixed(1)
        : 0;
      const peak = dataA.length ? Math.max(...dataA) : 0;

      currentValueEl.textContent = latest;
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peak;
      eventCountEl.textContent = submittedEvents;
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height);

      const allValues = [...dataA, ...dataB];
      const maxVal = Math.max(100, ...allValues, 1);
      const padding = 30;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      drawSeries(dataA, "#3b82f6", maxVal, padding, chartWidth, chartHeight, height);
      drawSeries(dataB, "#22c55e", maxVal, padding, chartWidth, chartHeight, height);

      drawAxesLabels(maxVal, padding, chartHeight, height);
    }

    function drawGrid(width, height) {
      ctx.save();
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = 30 + i * ((height - 60) / 5);
        ctx.beginPath();
        ctx.moveTo(30, y);
        ctx.lineTo(width - 30, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 8; i++) {
        const x = 30 + i * ((width - 60) / 8);
        ctx.beginPath();
        ctx.moveTo(x, 30);
        ctx.lineTo(x, height - 30);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawSeries(data, color, maxVal, padding, chartWidth, chartHeight, canvasHeight) {
      if (!data.length) return;

      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / Math.max(data.length - 1, 1)) * chartWidth;
        const y = canvasHeight - padding - (value / maxVal) * chartHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.fillStyle = color;
      data.forEach((value, index) => {
        const x = padding + (index / Math.max(data.length - 1, 1)) * chartWidth;
        const y = canvasHeight - padding - (value / maxVal) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      ctx.restore();
    }

    function drawAxesLabels(maxVal, padding, chartHeight, canvasHeight) {
      ctx.save();
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";

      for (let i = 0; i <= 5; i++) {
        const value = Math.round(maxVal - (i / 5) * maxVal);
        const y = padding + i * (chartHeight / 5);
        ctx.fillText(String(value), 4, y + 4);
      }

      ctx.restore();
    }

    function startStream() {
      if (intervalId) return;
      intervalId = setInterval(addDataPoint, 1000);
      addLog("Data stream started", "info");
    }

    function stopStream() {
      if (!intervalId) return;
      clearInterval(intervalId);
      intervalId = null;
      addLog("Data stream stopped", "warn");
    }

    function resetData() {
      dataA.length = 0;
      dataB.length = 0;
      updateMetrics();
      drawChart();
      addLog("Dashboard data reset", "warn");
    }

    function addLog(message, severity = "info") {
      const item = document.createElement("div");
      item.className = "log-item";

      const time = new Date().toLocaleTimeString();
      item.innerHTML = `
        <div class="time">${time}</div>
        <div>
          ${escapeHtml(message)}
          <span class="badge ${severity}">${severity.toUpperCase()}</span>
        </div>
      `;

      activityLog.prepend(item);

      while (activityLog.children.length > 12) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function clearErrors() {
      document.getElementById("titleError").textContent = "";
      document.getElementById("severityError").textContent = "";
      document.getElementById("descriptionError").textContent = "";
      document.getElementById("formSuccess").textContent = "";
    }

    function validateForm(values) {
      let valid = true;
      clearErrors();

      if (!values.title.trim()) {
        document.getElementById("titleError").textContent = "Title is required.";
        valid = false;
      } else if (values.title.trim().length < 3) {
        document.getElementById("titleError").textContent = "Title must be at least 3 characters.";
        valid = false;
      }

      if (!values.severity) {
        document.getElementById("severityError").textContent = "Please select a severity.";
        valid = false;
      }

      if (!values.description.trim()) {
        document.getElementById("descriptionError").textContent = "Description is required.";
        valid = false;
      } else if (values.description.trim().length < 10) {
        document.getElementById("descriptionError").textContent = "Description must be at least 10 characters.";
        valid = false;
      }

      return valid;
    }

    document.getElementById("eventForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const values = {
        title: document.getElementById("title").value,
        severity: document.getElementById("severity").value,
        description: document.getElementById("description").value
      };

      if (!validateForm(values)) return;

      submittedEvents++;
      updateMetrics();

      addLog(`${values.title}: ${values.description}`, values.severity);
      document.getElementById("formSuccess").textContent = "Event submitted successfully.";

      e.target.reset();
    });

    document.getElementById("startBtn").addEventListener("click", startStream);
    document.getElementById("stopBtn").addEventListener("click", stopStream);
    document.getElementById("resetBtn").addEventListener("click", resetData);

    // Initial render
    drawChart();
    updateMetrics();
    startStream();
  </script>
</body>
</html>
