            <label for="severity">Severity</label>
            <select id="severity" name="severity">
              <option value="">Select severity</option>
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
            <div class="error" id="severityError"></div>
          </div>

          <div class="field">
            <label for="value">Observed Value</label>
            <input id="value" name="value" type="number" step="0.1" placeholder="e.g. 72.4" />
            <div class="error" id="valueError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional notes..."></textarea>
            <div class="error" id="notesError"></div>
          </div>

          <button type="submit" class="btn-primary">Submit Event</button>
          <div class="success-message" id="formSuccess"></div>
        </form>
      </div>

      <div class="card table-card">
        <h2>Event Log</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
