  <script>
    const MAX_POINTS = 40;
    const dataPoints = [];
    const events = [];
    let timer = null;
    let peak = 0;
    let lastValue = null;

    const currentValueEl = document.getElementById('currentValue');
    const currentDeltaEl = document.getElementById('currentDelta');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');

    const canvas = document.getElementById('chartCanvas');
    const ctx = canvas.getContext('2d');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const form = document.getElementById('eventForm');
    const tableBody = document.getElementById('eventTableBody');
    const formSuccess = document.getElementById('formSuccess');

    function randomValue() {
      const base = 50;
      const wave = Math.sin(Date.now() / 3000) * 10;
      const noise = (Math.random() - 0.5) * 12;
      return Math.max(0, +(base + wave + noise).toFixed(1));
    }

    function addDataPoint() {
      const value = randomValue();
      const timestamp = new Date().toLocaleTimeString();

      dataPoints.push({ value, timestamp });
      if (dataPoints.length > MAX_POINTS) dataPoints.shift();

      if (value > peak) peak = value;

      updateKPIs(value);
      drawChart();
    }

    function updateKPIs(current) {
      currentValueEl.textContent = current.toFixed(1);

      if (lastValue === null) {
        currentDeltaEl.textContent = 'First data point received';
      } else {
        const diff = +(current - lastValue).toFixed(1);
        const sign = diff >= 0 ? '+' : '';
        currentDeltaEl.textContent = `${sign}${diff} vs previous`;
        currentDeltaEl.style.color = diff >= 0 ? '#86efac' : '#fca5a5';
      }

      lastValue = current;

      const avg = dataPoints.reduce((sum, p) => sum + p.value, 0) / (dataPoints.length || 1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      eventCountEl.textContent = events.length;
    }

    function drawChart() {
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const width = rect.width;
      const height = rect.height;
      const padding = 32;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i < 5; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i < 6; i++) {
        const x = padding + ((width - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      if (dataPoints.length === 0) {
        ctx.fillStyle = '#94a3b8';
        ctx.font = '14px sans-serif';
        ctx.fillText('No data yet. Start the stream.', padding, height / 2);
        return;
      }

      const values = dataPoints.map(p => p.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 100);
      const range = max - min || 1;

      const xStep = (width - padding * 2) / Math.max(dataPoints.length - 1, 1);

      // Area fill
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + (dataPoints.length - 1) * xStep, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#60a5fa';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Min: ${min.toFixed(1)}`, padding, height - 8);
      ctx.fillText(`Max: ${max.toFixed(1)}`, width - padding - 60, height - 8);
    }

    function startStream() {
      if (timer) return;
      addDataPoint();
      timer = setInterval(addDataPoint, 1000);
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
    }

    function resetDashboard() {
      stopStream();
      dataPoints.length = 0;
      events.length = 0;
      peak = 0;
      lastValue = null;

      currentValueEl.textContent = '0';
      currentDeltaEl.textContent = 'Waiting for data...';
      currentDeltaEl.style.color = '#86efac';
      avgValueEl.textContent = '0';
      peakValueEl.textContent = '0';
      eventCountEl.textContent = '0';

      tableBody.innerHTML = `
        <tr>
          <td colspan="5" style="color: var(--muted);">No events logged yet.</td>
        </tr>
      `;

      form.reset();
      clearErrors();
      formSuccess.textContent = '';
      drawChart();
    }

    function clearErrors() {
      document.getElementById('titleError').textContent = '';
      document.getElementById('severityError').textContent = '';
      document.getElementById('valueError').textContent = '';
      document.getElementById('notesError').textContent = '';
    }

    function validateForm(data) {
      clearErrors();
      let valid = true;

      if (!data.title.trim()) {
        document.getElementById('titleError').textContent = 'Title is required.';
        valid = false;
      } else if (data.title.trim().length < 3) {
        document.getElementById('titleError').textContent = 'Title must be at least 3 characters.';
        valid = false;
      }

      if (!data.severity) {
        document.getElementById('severityError').textContent = 'Please select a severity.';
        valid = false;
      }

      if (data.value === '' || isNaN(Number(data.value))) {
        document.getElementById('valueError').textContent = 'Observed value must be a valid number.';
        valid = false;
      }

      if (data.notes.length > 200) {
        document.getElementById('notesError').textContent = 'Notes must be 200 characters or fewer.';
        valid = false;
      }

      return valid;
    }

    function severityBadge(severity) {
      const map = {
        Low: 'badge badge-low',
        Medium: 'badge badge-medium',
        High: 'badge badge-high'
      };
      return `<span class="${map[severity] || 'badge'}">${severity}</span>`;
    }

    function renderEvents() {
      if (events.length === 0) {
        tableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted);">No events logged yet.</td>
          </tr>
        `;
        return;
      }

      tableBody.innerHTML = events
        .slice()
        .reverse()
        .map(event => `
          <tr>
            <td>${event.time}</td>
            <td>${escapeHtml(event.title)}</td>
            <td>${severityBadge(event.severity)}</td>
            <td>${Number(event.value).toFixed(1)}</td>
            <td>${escapeHtml(event.notes || '-')}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      formSuccess.textContent = '';

      const formData = {
        title: form.title.value,
        severity: form.severity.value,
        value: form.value.value,
        notes: form.notes.value.trim()
      };

      if (!validateForm(formData)) return;

      events.push({
        ...formData,
        time: new Date().toLocaleTimeString()
      });

      renderEvents();
      eventCountEl.textContent = events.length;
      formSuccess.textContent = 'Event submitted successfully.';
      form.reset();
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetDashboard);
    window.addEventListener('resize', drawChart);

    drawChart();
  </script>
</body>
</html>
```

