      .metric,
      .chart-card,
      .form-card,
      .feed-card {
        grid-column: span 12;
      }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Operations Dashboard</h1>
        <div style="color: var(--muted); margin-top: 6px;">Real-time monitoring and input management</div>
      </div>
      <div class="status">
        <span class="status-dot"></span>
        Live stream active
      </div>
    </div>

    <div class="grid">
      <div class="card metric">
        <h3>Total Events</h3>
        <div class="value" id="totalEvents">0</div>
        <div class="delta" id="eventsDelta">+0 in last minute</div>
      </div>

      <div class="card metric">
        <h3>Average Value</h3>
        <div class="value" id="avgValue">0</div>
        <div class="delta">Rolling average</div>
      </div>

      <div class="card metric">
        <h3>Peak Value</h3>
        <div class="value" id="peakValue">0</div>
        <div class="delta">Highest observed</div>
      </div>

      <div class="card metric">
        <h3>Last Category</h3>
        <div class="value" id="lastCategory" style="font-size: 1.4rem;">—</div>
        <div class="delta">Most recent submission</div>
      </div>

      <div class="card chart-card">
        <h2>Live Data Trend</h2>
        <canvas id="chart" width="800" height="320"></canvas>
      </div>

      <div class="card form-card">
        <h2>Submit New Record</h2>
        <form id="recordForm">
          <div class="field">
            <label for="title">Title</label>
            <input id="title" name="title" type="text" placeholder="Enter record title" required />
          </div>

          <div class="row">
            <div class="field">
              <label for="category">Category</label>
              <select id="category" name="category" required>
                <option value="">Select</option>
                <option value="System">System</option>
                <option value="User">User</option>
                <option value="Alert">Alert</option>
                <option value="Transaction">Transaction</option>
              </select>
            </div>

            <div class="field">
              <label for="value">Value</label>
              <input id="value" name="value" type="number" min="0" max="1000" placeholder="e.g. 42" required />
            </div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" placeholder="Optional notes"></textarea>
          </div>

          <button type="submit">Add Record</button>
          <div id="formMessage" class="message"></div>
        </form>
      </div>

      <div class="card feed-card">
        <h2>Recent Activity</h2>
        <ul id="feedList" class="feed-list"></ul>
      </div>
    </div>
  </div>

  <script>
    const state = {
      points: [],
      records: [],
      maxPoints: 40,
      totalEvents: 0,
      peakValue: 0
    };

    const els = {
      totalEvents: document.getElementById('totalEvents'),
      eventsDelta: document.getElementById('eventsDelta'),
      avgValue: document.getElementById('avgValue'),
      peakValue: document.getElementById('peakValue'),
      lastCategory: document.getElementById('lastCategory'),
      feedList: document.getElementById('feedList'),
      form: document.getElementById('recordForm'),
      formMessage: document.getElementById('formMessage'),
      chart: document.getElementById('chart')
    };

    const ctx = els.chart.getContext('2d');

    function randomValue(min = 10, max = 100) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function addPoint(value, source = 'Live stream') {
      const point = {
        time: nowTime(),
        value,
        source
      };

      state.points.push(point);
      if (state.points.length > state.maxPoints) {
        state.points.shift();
      }

      state.totalEvents += 1;
      state.peakValue = Math.max(state.peakValue, value);

      updateMetrics();
      drawChart();
    }

    function addRecord(record) {
      state.records.unshift(record);
      if (state.records.length > 20) {
        state.records.pop();
      }
      renderFeed();
    }

    function updateMetrics() {
      const values = state.points.map(p => p.value);
      const avg = values.length
        ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
        : 0;

      els.totalEvents.textContent = state.totalEvents;
      els.avgValue.textContent = avg;
      els.peakValue.textContent = state.peakValue;
      els.lastCategory.textContent = state.records[0]?.category || '—';

      const recentCount = state.points.slice(-10).length;
      els.eventsDelta.textContent = `+${recentCount} recent updates`;
    }

    function renderFeed() {
      els.feedList.innerHTML = '';

      if (state.records.length === 0) {
        const empty = document.createElement('li');
        empty.className = 'feed-item';
        empty.innerHTML = '<span>No activity yet.</span>';
        els.feedList.appendChild(empty);
        return;
      }

      state.records.forEach(record => {
        const li = document.createElement('li');
        li.className = 'feed-item';
        li.innerHTML = `
          <div>
            <strong>${escapeHtml(record.title)}</strong>
            <div class="feed-meta">${escapeHtml(record.category)} • Value: ${record.value}</div>
            ${record.notes ? `<div class="feed-meta">${escapeHtml(record.notes)}</div>` : ''}
          </div>
          <div class="feed-meta">${record.time}</div>
        `;
        els.feedList.appendChild(li);
      });
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function drawChart() {
      const canvas = els.chart;
      const width = canvas.width;
      const height = canvas.height;
      const padding = 36;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i < 5; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      if (state.points.length === 0) return;

      const values = state.points.map(p => p.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 100);
      const range = Math.max(max - min, 1);

      // Axis labels
      ctx.fillStyle = 'rgba(148, 163, 184, 0.9)';
      ctx.font = '12px sans-serif';
      ctx.fillText(String(max), 8, padding + 4);
      ctx.fillText(String(min), 8, height - padding);

      // Line
      ctx.beginPath();
      state.points.forEach((point, index) => {
        const x = padding + (index / Math.max(state.points.length - 1, 1)) * (width - padding * 2);
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Area fill
      ctx.lineTo(width - padding, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Redraw line on top
      ctx.beginPath();
      state.points.forEach((point, index) => {
        const x = padding + (index / Math.max(state.points.length - 1, 1)) * (width - padding * 2);
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Last point marker
      const lastIndex = state.points.length - 1;
      const last = state.points[lastIndex];
      const lastX = padding + (lastIndex / Math.max(state.points.length - 1, 1)) * (width - padding * 2);
      const lastY = height - padding - ((last.value - min) / range) * (height - padding * 2);

      ctx.beginPath();
      ctx.arc(lastX, lastY, 5, 0, Math.PI * 2);
      ctx.fillStyle = '#22c55e';
      ctx.fill();

      // X labels
      ctx.fillStyle = 'rgba(148, 163, 184, 0.9)';
      const step = Math.max(1, Math.floor(state.points.length / 6));
      state.points.forEach((point, index) => {
        if (index % step === 0 || index === state.points.length - 1) {
          const x = padding + (index / Math.max(state.points.length - 1, 1)) * (width - padding * 2);
          ctx.fillText(point.time, x - 18, height - 10);
        }
      });
    }

    function handleSubmit(event) {
      event.preventDefault();

      const formData = new FormData(els.form);
      const title = formData.get('title').trim();
      const category = formData.get('category').trim();
      const value = Number(formData.get('value'));
      const notes = formData.get('notes').trim();

      if (!title || !category || Number.isNaN(value)) {
        showMessage('Please complete all required fields.', 'error');
        return;
      }

      const record = {
        title,
        category,
        value,
        notes,
        time: nowTime()
      };

      addRecord(record);
      addPoint(value, 'Manual entry');
      showMessage('Record added successfully.', 'success');
      els.form.reset();
      updateMetrics();
    }

    function showMessage(text, type) {
      els.formMessage.textContent = text;
      els.formMessage.className = `message ${type}`;
      setTimeout(() => {
        els.formMessage.textContent = '';
        els.formMessage.className = 'message';
      }, 2500);
    }

    function simulateLiveData() {
      const categories = ['System', 'User', 'Alert', 'Transaction'];
      const value = randomValue(20, 120);
      const category = categories[Math.floor(Math.random() * categories.length)];

      addPoint(value, 'Live stream');
      addRecord({
        title: `Auto event ${state.totalEvents}`,
        category,
        value,
        notes: 'Generated automatically from live stream',
        time: nowTime()
      });
    }

    function resizeCanvasForDisplay() {
      const rect = els.chart.getBoundingClientRect();
      const ratio = window.devicePixelRatio || 1;
      els.chart.width = Math.floor(rect.width * ratio);
      els.chart.height = Math.floor(320 * ratio);
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    els.form.addEventListener('submit', handleSubmit);
    window.addEventListener('resize', resizeCanvasForDisplay);

    renderFeed();
    updateMetrics();

    for (let i = 0; i < 12; i++) {
      addPoint(randomValue(20, 100));
    }

    resizeCanvasForDisplay();
    setInterval(simulateLiveData, 2000);
  </script>
</body>
</html>
```

