      font-size: 0.95rem;
    }

    th {
      color: var(--muted);
      font-weight: 600;
    }

    .badge {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 999px;
      font-size: 0.8rem;
      background: rgba(34,197,94,0.12);
      color: #86efac;
    }

    .toolbar {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 14px;
      flex-wrap: wrap;
    }

    .toolbar select {
      max-width: 220px;
    }

    @media (max-width: 1100px) {
      .metrics {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .content,
      .bottom {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 800px) {
      .app {
        grid-template-columns: 1fr;
      }

      .sidebar {
        position: relative;
        height: auto;
        border-right: none;
        border-bottom: 1px solid var(--border);
      }

      .row {
        grid-template-columns: 1fr;
      }

      .metrics {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <div class="app">
    <aside class="sidebar">
      <div class="brand">PulseBoard</div>
      <nav class="nav">
        <a href="#" class="active">Dashboard</a>
        <a href="#">Analytics</a>
        <a href="#">Events</a>
        <a href="#">Settings</a>
      </nav>
    </aside>

    <main class="main">
      <div class="topbar">
        <div>
          <h1>Realtime Operations Dashboard</h1>
          <div style="color: var(--muted); margin-top: 6px;">
            Monitor live activity and submit new records.
          </div>
        </div>
        <div class="status">
          <span class="dot"></span>
          Live stream active
        </div>
      </div>

      <section class="grid metrics">
        <div class="panel metric-card">
          <div class="metric-label">Active Users</div>
          <div class="metric-value" id="activeUsers">0</div>
          <div class="metric-trend" id="activeUsersTrend">+0.0%</div>
        </div>
        <div class="panel metric-card">
          <div class="metric-label">Transactions/min</div>
          <div class="metric-value" id="txRate">0</div>
          <div class="metric-trend" id="txRateTrend">+0.0%</div>
        </div>
        <div class="panel metric-card">
          <div class="metric-label">Error Rate</div>
          <div class="metric-value" id="errorRate">0%</div>
          <div class="metric-trend" id="errorRateTrend">Stable</div>
        </div>
        <div class="panel metric-card">
          <div class="metric-label">Avg Response</div>
          <div class="metric-value" id="responseTime">0ms</div>
          <div class="metric-trend" id="responseTimeTrend">+0ms</div>
        </div>
      </section>

      <section class="grid content">
        <div class="panel">
          <h2>Traffic Trend</h2>
          <div class="chart-wrap">
            <canvas id="trafficChart" width="900" height="320"></canvas>
          </div>
        </div>

        <div class="panel">
          <h2>Live Activity Feed</h2>
          <div class="feed" id="activityFeed"></div>
        </div>
      </section>

      <section class="grid bottom">
        <div class="panel">
          <h2>Submit New Event</h2>
          <form id="eventForm" novalidate>
            <div class="row">
              <div class="field">
                <label for="title">Title</label>
                <input id="title" name="title" type="text" placeholder="e.g. Payment processed" />
                <div class="error" id="titleError"></div>
              </div>
              <div class="field">
                <label for="category">Category</label>
                <select id="category" name="category">
                  <option value="">Select category</option>
                  <option value="System">System</option>
                  <option value="Payment">Payment</option>
                  <option value="User">User</option>
                  <option value="Alert">Alert</option>
                </select>
                <div class="error" id="categoryError"></div>
              </div>
            </div>

            <div class="field">
              <label for="value">Value</label>
              <input id="value" name="value" type="number" placeholder="e.g. 42" />
              <div class="error" id="valueError"></div>
            </div>

            <div class="field">
              <label for="description">Description</label>
              <textarea id="description" name="description" placeholder="Optional details..."></textarea>
            </div>

            <div class="actions">
              <button type="submit" class="btn-primary">Submit Event</button>
              <button type="reset" class="btn-secondary">Reset</button>
              <span class="message" id="formMessage"></span>
            </div>
          </form>
        </div>

        <div class="panel">
          <div class="toolbar">
            <h2 style="margin: 0;">Recent Records</h2>
            <select id="filterCategory">
              <option value="All">All Categories</option>
              <option value="System">System</option>
              <option value="Payment">Payment</option>
              <option value="User">User</option>
              <option value="Alert">Alert</option>
            </select>
          </div>

          <div class="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Title</th>
                  <th>Category</th>
                  <th>Value</th>
                  <th>Time</th>
                </tr>
              </thead>
              <tbody id="recordsTableBody"></tbody>
            </table>
          </div>
        </div>
      </section>
    </main>
  </div>

  <script>
    const state = {
      metrics: {
        activeUsers: 120,
        txRate: 38,
        errorRate: 1.2,
        responseTime: 240
      },
      chartData: [],
      records: [],
      maxChartPoints: 40
    };

    const els = {
      activeUsers: document.getElementById('activeUsers'),
      txRate: document.getElementById('txRate'),
      errorRate: document.getElementById('errorRate'),
      responseTime: document.getElementById('responseTime'),
      activeUsersTrend: document.getElementById('activeUsersTrend'),
      txRateTrend: document.getElementById('txRateTrend'),
      errorRateTrend: document.getElementById('errorRateTrend'),
      responseTimeTrend: document.getElementById('responseTimeTrend'),
      activityFeed: document.getElementById('activityFeed'),
      recordsTableBody: document.getElementById('recordsTableBody'),
      eventForm: document.getElementById('eventForm'),
      formMessage: document.getElementById('formMessage'),
      filterCategory: document.getElementById('filterCategory'),
      chart: document.getElementById('trafficChart'),
      titleError: document.getElementById('titleError'),
      categoryError: document.getElementById('categoryError'),
      valueError: document.getElementById('valueError')
    };

    const ctx = els.chart.getContext('2d');

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }

    function updateMetrics() {
      const prev = { ...state.metrics };

      state.metrics.activeUsers = Math.round(clamp(prev.activeUsers + randomBetween(-8, 10), 80, 220));
      state.metrics.txRate = Math.round(clamp(prev.txRate + randomBetween(-4, 5), 10, 80));
      state.metrics.errorRate = clamp(prev.errorRate + randomBetween(-0.3, 0.25), 0.1, 5.0);
      state.metrics.responseTime = Math.round(clamp(prev.responseTime + randomBetween(-25, 30), 120, 600));

      els.activeUsers.textContent = state.metrics.activeUsers;
      els.txRate.textContent = state.metrics.txRate;
      els.errorRate.textContent = state.metrics.errorRate.toFixed(1) + '%';
      els.responseTime.textContent = state.metrics.responseTime + 'ms';

      const userTrend = (((state.metrics.activeUsers - prev.activeUsers) / prev.activeUsers) * 100) || 0;
      const txTrend = (((state.metrics.txRate - prev.txRate) / prev.txRate) * 100) || 0;
      const errTrend = state.metrics.errorRate - prev.errorRate;
      const resTrend = state.metrics.responseTime - prev.responseTime;

      els.activeUsersTrend.textContent = `${userTrend >= 0 ? '+' : ''}${userTrend.toFixed(1)}%`;
      els.txRateTrend.textContent = `${txTrend >= 0 ? '+' : ''}${txTrend.toFixed(1)}%`;
      els.errorRateTrend.textContent = `${errTrend >= 0 ? '+' : ''}${errTrend.toFixed(2)}%`;
      els.responseTimeTrend.textContent = `${resTrend >= 0 ? '+' : ''}${resTrend}ms`;

      els.activeUsersTrend.style.color = userTrend >= 0 ? '#86efac' : '#fca5a5';
      els.txRateTrend.style.color = txTrend >= 0 ? '#86efac' : '#fca5a5';
      els.errorRateTrend.style.color = errTrend <= 0 ? '#86efac' : '#fca5a5';
      els.responseTimeTrend.style.color = resTrend <= 0 ? '#86efac' : '#fca5a5';
    }

    function pushChartPoint() {
      state.chartData.push({
        time: formatTime(),
        value: state.metrics.activeUsers
      });

      if (state.chartData.length > state.maxChartPoints) {
        state.chartData.shift();
      }
    }

    function drawChart() {
      const canvas = els.chart;
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;

      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const width = rect.width;
      const height = rect.height;
      const padding = 32;

      ctx.clearRect(0, 0, width, height);

      ctx.strokeStyle = 'rgba(148, 163, 184, 0.2)';
      ctx.lineWidth = 1;

      for (let i = 0; i < 5; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      if (state.chartData.length < 2) return;

      const values = state.chartData.map(p => p.value);
      const min = Math.min(...values) - 10;
      const max = Math.max(...values) + 10;
      const range = max - min || 1;

      const xStep = (width - padding * 2) / (state.chartData.length - 1);

      ctx.beginPath();
      state.chartData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / range) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');

      ctx.lineTo(width - padding, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Min: ${Math.round(min + 10)}`, padding, 18);
      ctx.fillText(`Max: ${Math.round(max - 10)}`, width - 90, 18);
    }

    function addFeedItem(record) {
      const item = document.createElement('div');
      item.className = 'feed-item';
      item.innerHTML = `
        <strong>${escapeHtml(record.title)}</strong>
        <div>${escapeHtml(record.description || 'No description provided')}</div>
        <div class="feed-meta">${record.category} • Value: ${record.value} • ${record.time}</div>
      `;
      els.activityFeed.prepend(item);

      while (els.activityFeed.children.length > 12) {
        els.activityFeed.removeChild(els.activityFeed.lastChild);
      }
    }

    function renderRecords() {
      const filter = els.filterCategory.value;
      const filtered = filter === 'All'
        ? state.records
        : state.records.filter(r => r.category === filter);

      els.recordsTableBody.innerHTML = filtered
        .slice()
        .reverse()
        .map(record => `
          <tr>
            <td>${escapeHtml(record.title)}</td>
            <td><span class="badge">${escapeHtml(record.category)}</span></td>
            <td>${record.value}</td>
            <td>${record.time}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function clearErrors() {
      els.titleError.textContent = '';
      els.categoryError.textContent = '';
      els.valueError.textContent = '';
      els.formMessage.textContent = '';
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.title.trim()) {
        els.titleError.textContent = 'Title is required.';
        valid = false;
      }

      if (!data.category) {
        els.categoryError.textContent = 'Category is required.';
        valid = false;
      }

      if (data.value === '' || isNaN(Number(data.value))) {
        els.valueError.textContent = 'A numeric value is required.';
        valid = false;
      }

      return valid;
    }

    function createRecord(data) {
      return {
        id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),
        title: data.title.trim(),
        category: data.category,
        value: Number(data.value),
        description: data.description.trim(),
        time: formatTime()
      };
    }

    function handleFormSubmit(event) {
      event.preventDefault();

      const formData = new FormData(els.eventForm);
      const data = Object.fromEntries(formData.entries());

      if (!validateForm(data)) return;

      const record = createRecord(data);
      state.records.push(record);

      addFeedItem(record);
      renderRecords();

      els.formMessage.textContent = 'Event submitted successfully.';
      els.eventForm.reset();
    }

    function generateSystemEvent() {
      const templates = [
        { title: 'User login spike', category: 'User', description: 'Concurrent sessions increased.' },
        { title: 'Payment processed', category: 'Payment', description: 'Transaction completed successfully.' },
        { title: 'Background job completed', category: 'System', description: 'Scheduled task finished.' },
        { title: 'Latency threshold warning', category: 'Alert', description: 'Response time exceeded target.' }
      ];

      const template = templates[Math.floor(Math.random() * templates.length)];
      const record = {
        id: String(Date.now() + Math.random()),
        title: template.title,
        category: template.category,
        value: Math.round(randomBetween(1, 100)),
        description: template.description,
        time: formatTime()
      };

      state.records.push(record);
      addFeedItem(record);
      renderRecords();
    }

    function tick() {
      updateMetrics();
      pushChartPoint();
      drawChart();

      if (Math.random() > 0.45) {
        generateSystemEvent();
      }
    }

    function seedInitialData() {
      for (let i = 0; i < 12; i++) {
        updateMetrics();
        pushChartPoint();
      }

      const initialRecords = [
        { title: 'Service started', category: 'System', value: 1, description: 'Dashboard initialized.', time: formatTime() },
        { title: 'First payment batch', category: 'Payment', value: 18, description: 'Batch settled.', time: formatTime() },
        { title: 'New user registrations', category: 'User', value: 7, description: 'Morning signup activity.', time: formatTime() },
        { title: 'CPU usage alert', category: 'Alert', value: 82, description: 'Usage exceeded threshold.', time: formatTime() }
      ];

      initialRecords.forEach(data => {
        const record = { id: String(Date.now() + Math.random()), ...data };
        state.records.push(record);
        addFeedItem(record);
      });

      renderRecords();
      drawChart();
    }

    els.eventForm.addEventListener('submit', handleFormSubmit);
    els.filterCategory.addEventListener('change', renderRecords);
    window.addEventListener('resize', drawChart);

    seedInitialData();
    setInterval(tick, 1500);
  </script>
</body>
</html>
```

