        <div class="card metric-card">
          <h3>Peak</h3>
          <div class="metric-value" id="peakValue">0</div>
          <div class="metric-sub">Highest observed value</div>
        </div>
        <div class="card metric-card">
          <h3>Events</h3>
          <div class="metric-value" id="eventCount">0</div>
          <div class="metric-sub">Logged dashboard actions</div>
        </div>
      </section>

      <section class="card chart-card">
        <h2 class="card-title">Live Data Stream</h2>
        <canvas id="chart" width="800" height="320"></canvas>
      </section>

      <section class="card form-card">
        <h2 class="card-title">Configuration Form</h2>
        <form id="configForm">
          <div class="field">
            <label for="streamName">Stream Name</label>
            <input id="streamName" name="streamName" type="text" placeholder="e.g. Sensor A" required />
          </div>

          <div class="field">
            <label for="updateInterval">Update Interval (ms)</label>
            <input id="updateInterval" name="updateInterval" type="number" min="100" step="100" value="1000" required />
          </div>

          <div class="field">
            <label for="dataMode">Data Mode</label>
            <select id="dataMode" name="dataMode">
              <option value="random">Random</option>
              <option value="spiky">Spiky</option>
              <option value="smooth">Smooth</option>
            </select>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional configuration notes"></textarea>
          </div>

          <div class="form-actions">
            <button type="submit" class="primary">Apply Settings</button>
            <button type="button" id="fillDemoBtn">Fill Demo</button>
          </div>
        </form>
        <div id="formStatus" class="status"></div>
      </section>

      <section class="card log-card">
        <h2 class="card-title">Event Log</h2>
        <ul id="logList" class="log-list"></ul>
      </section>
    </div>
  </div>

  <script>
    const state = {
      data: [],
      maxPoints: 40,
      intervalId: null,
      updateInterval: 1000,
      mode: 'random',
      streamName: 'Default Stream',
      eventCount: 0,
      smoothValue: 50
    };

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const logListEl = document.getElementById('logList');
    const formStatusEl = document.getElementById('formStatus');

    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    function logEvent(message) {
      state.eventCount += 1;
      eventCountEl.textContent = state.eventCount;

      const item = document.createElement('li');
      item.className = 'log-item';

      const text = document.createElement('div');
      text.textContent = message;

      const time = document.createElement('span');
      time.textContent = new Date().toLocaleTimeString();

      item.appendChild(text);
      item.appendChild(time);

      logListEl.prepend(item);

      while (logListEl.children.length > 20) {
        logListEl.removeChild(logListEl.lastChild);
      }
    }

    function generateValue() {
      if (state.mode === 'random') {
        return Math.floor(Math.random() * 100);
      }

      if (state.mode === 'spiky') {
        const base = Math.random() * 60;
        const spike = Math.random() > 0.85 ? Math.random() * 50 : 0;
        return Math.min(100, Math.floor(base + spike));
      }

      if (state.mode === 'smooth') {
        const delta = (Math.random() - 0.5) * 12;
        state.smoothValue = Math.max(0, Math.min(100, state.smoothValue + delta));
        return Math.floor(state.smoothValue);
      }

      return 0;
    }

    function addDataPoint() {
      const value = generateValue();
      state.data.push(value);

      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      const latest = state.data[state.data.length - 1] ?? 0;
      const avg = state.data.length
        ? state.data.reduce((sum, val) => sum + val, 0) / state.data.length
        : 0;
      const peak = state.data.length ? Math.max(...state.data) : 0;

      currentValueEl.textContent = latest.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      const padding = 30;

      ctx.clearRect(0, 0, width, height);

      ctx.strokeStyle = 'rgba(148, 163, 184, 0.25)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.beginPath();

      if (state.data.length > 0) {
        state.data.forEach((value, index) => {
          const x = padding + (index / Math.max(state.maxPoints - 1, 1)) * (width - padding * 2);
          const y = height - padding - (value / 100) * (height - padding * 2);

          if (index === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        });
      }

      ctx.stroke();

      if (state.data.length > 0) {
        ctx.fillStyle = '#22c55e';
        state.data.forEach((value, index) => {
          const x = padding + (index / Math.max(state.maxPoints - 1, 1)) * (width - padding * 2);
          const y = height - padding - (value / 100) * (height - padding * 2);

          ctx.beginPath();
          ctx.arc(x, y, 3, 0, Math.PI * 2);
          ctx.fill();
        });
      }

      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText('100', 5, padding + 4);
      ctx.fillText('0', 15, height - padding + 4);

      ctx.fillStyle = '#e5e7eb';
      ctx.font = 'bold 14px sans-serif';
      ctx.fillText(state.streamName, padding, 20);
    }

    function startStream() {
      if (state.intervalId) return;
      state.intervalId = setInterval(addDataPoint, state.updateInterval);
      logEvent(`Started stream "${state.streamName}" at ${state.updateInterval}ms interval.`);
    }

    function stopStream() {
      if (!state.intervalId) return;
      clearInterval(state.intervalId);
      state.intervalId = null;
      logEvent(`Stopped stream "${state.streamName}".`);
    }

    function resetDashboard() {
      stopStream();
      state.data = [];
      state.smoothValue = 50;
      updateMetrics();
      drawChart();
      logEvent('Dashboard reset.');
    }

    document.getElementById('startBtn').addEventListener('click', startStream);
    document.getElementById('stopBtn').addEventListener('click', stopStream);
    document.getElementById('resetBtn').addEventListener('click', resetDashboard);

    document.getElementById('fillDemoBtn').addEventListener('click', () => {
      document.getElementById('streamName').value = 'Demo Sensor';
      document.getElementById('updateInterval').value = 500;
      document.getElementById('dataMode').value = 'smooth';
      document.getElementById('notes').value = 'Demo configuration for smooth live updates.';
      formStatusEl.textContent = 'Demo values filled.';
      formStatusEl.className = 'status success';
    });

    document.getElementById('configForm').addEventListener('submit', (event) => {
      event.preventDefault();

      const streamName = document.getElementById('streamName').value.trim();
      const updateInterval = Number(document.getElementById('updateInterval').value);
      const dataMode = document.getElementById('dataMode').value;
      const notes = document.getElementById('notes').value.trim();

      if (!streamName) {
        formStatusEl.textContent = 'Stream name is required.';
        formStatusEl.className = 'status error';
        return;
      }

      if (!updateInterval || updateInterval < 100) {
        formStatusEl.textContent = 'Update interval must be at least 100ms.';
        formStatusEl.className = 'status error';
        return;
      }

      const wasRunning = Boolean(state.intervalId);
      if (wasRunning) {
        stopStream();
      }

      state.streamName = streamName;
      state.updateInterval = updateInterval;
      state.mode = dataMode;

      formStatusEl.textContent = `Settings applied for "${streamName}" (${dataMode}, ${updateInterval}ms).`;
      formStatusEl.className = 'status success';

      logEvent(`Applied settings: name="${streamName}", mode="${dataMode}", interval=${updateInterval}ms${notes ? ', notes added' : ''}.`);

      drawChart();

      if (wasRunning) {
        startStream();
      }
    });

    updateMetrics();
    drawChart();
    logEvent('Dashboard initialized.');
  </script>
</body>
</html>
