  <script>
    const state = {
      metrics: {
        activeUsers: 128,
        transactions: 342,
        errorRate: 1.8,
        responseTime: 245
      },
      chartData: Array.from({ length: 30 }, (_, i) => ({
        label: i + 1,
        value: 50 + Math.floor(Math.random() * 50)
      })),
      feed: []
    };

    const els = {
      activeUsers: document.getElementById('activeUsers'),
      transactions: document.getElementById('transactions'),
      errorRate: document.getElementById('errorRate'),
      responseTime: document.getElementById('responseTime'),
      activeUsersTrend: document.getElementById('activeUsersTrend'),
      transactionsTrend: document.getElementById('transactionsTrend'),
      errorRateTrend: document.getElementById('errorRateTrend'),
      responseTimeTrend: document.getElementById('responseTimeTrend'),
      activityFeed: document.getElementById('activityFeed'),
      chart: document.getElementById('realtimeChart'),
      form: document.getElementById('eventForm'),
      formMessage: document.getElementById('formMessage')
    };

    const ctx = els.chart.getContext('2d');

    function randomBetween(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }

    function addFeedItem(title, description, type = 'info') {
      const item = {
        title,
        description,
        type,
        time: formatTime()
      };

      state.feed.unshift(item);
      state.feed = state.feed.slice(0, 20);
      renderFeed();
    }

    function renderFeed() {
      els.activityFeed.innerHTML = '';

      if (state.feed.length === 0) {
        els.activityFeed.innerHTML = '<div class="feed-item"><strong>No activity yet</strong><small>Live events will appear here.</small></div>';
        return;
      }

      state.feed.forEach(entry => {
        const div = document.createElement('div');
        div.className = 'feed-item';

        let color = '#93c5fd';
        if (entry.type === 'success') color = '#86efac';
        if (entry.type === 'warning') color = '#fcd34d';
        if (entry.type === 'error') color = '#fca5a5';

        div.innerHTML = `
          <strong style="color:${color}">${entry.title}</strong>
          <div>${entry.description || 'No description provided.'}</div>
          <small>${entry.time}</small>
        `;
        els.activityFeed.appendChild(div);
      });
    }

    function renderMetrics() {
      els.activeUsers.textContent = state.metrics.activeUsers;
      els.transactions.textContent = state.metrics.transactions;
      els.errorRate.textContent = state.metrics.errorRate.toFixed(1) + '%';
      els.responseTime.textContent = state.metrics.responseTime + 'ms';
    }

    function updateTrend(el, value, suffix, inverse = false) {
      const positive = inverse ? value < 0 : value >= 0;
      el.textContent = `${value >= 0 ? '+' : ''}${value}${suffix}`;
      el.style.color = positive ? '#86efac' : '#fca5a5';
    }

    function renderChart() {
      const canvas = els.chart;
      const width = canvas.width;
      const height = canvas.height;
      const padding = 32;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;

      for (let i = 0; i < 5; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      const values = state.chartData.map(d => d.value);
      const min = Math.min(...values) - 10;
      const max = Math.max(...values) + 10;

      const xStep = (width - padding * 2) / (state.chartData.length - 1);

      // Area fill
      ctx.beginPath();
      state.chartData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(width - padding, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      state.chartData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      state.chartData.forEach((point, index) => {
        const x = padding + index * xStep;
        const y = height - padding - ((point.value - min) / (max - min)) * (height - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#e0f2fe';
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = 'rgba(229,231,235,0.7)';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Min: ${Math.round(min)}`, padding, height - 8);
      ctx.fillText(`Max: ${Math.round(max)}`, width - padding - 60, 20);
    }

    function simulateRealtimeUpdate() {
      const prevUsers = state.metrics.activeUsers;
      const prevTransactions = state.metrics.transactions;
      const prevErrorRate = state.metrics.errorRate;
      const prevResponseTime = state.metrics.responseTime;

      state.metrics.activeUsers = clamp(prevUsers + randomBetween(-5, 8), 80, 220);
      state.metrics.transactions = clamp(prevTransactions + randomBetween(0, 12), 100, 1000);
      state.metrics.errorRate = clamp(prevErrorRate + (Math.random() * 0.6 - 0.3), 0.2, 5.0);
      state.metrics.responseTime = clamp(prevResponseTime + randomBetween(-20, 25), 120, 500);

      updateTrend(els.activeUsersTrend, state.metrics.activeUsers - prevUsers, ' users');
      updateTrend(els.transactionsTrend, state.metrics.transactions - prevTransactions, ' tx');
      updateTrend(els.errorRateTrend, +(state.metrics.errorRate - prevErrorRate).toFixed(1), '%', true);
      updateTrend(els.responseTimeTrend, state.metrics.responseTime - prevResponseTime, 'ms', true);

      const nextValue = clamp(
        state.chartData[state.chartData.length - 1].value + randomBetween(-12, 12),
        20,
        120
      );

      state.chartData.push({
        label: state.chartData.length + 1,
        value: nextValue
      });

      if (state.chartData.length > 30) {
        state.chartData.shift();
      }

      renderMetrics();
      renderChart();

      const eventRoll = Math.random();
      if (eventRoll > 0.7) {
        const types = ['info', 'success', 'warning', 'error'];
        const type = types[randomBetween(0, types.length - 1)];
        addFeedItem(
          `System ${type}`,
          `Automated ${type} event detected with throughput ${nextValue}.`,
          type
        );
      }
    }

    function validateForm(data) {
      const errors = [];

      if (!data.eventName.trim()) errors.push('Event name is required.');
      if (!data.eventType.trim()) errors.push('Event type is required.');
      if (data.eventValue === '' || Number.isNaN(Number(data.eventValue))) errors.push('Value must be a number.');

      return errors;
    }

    els.form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(els.form);
      const data = {
        eventName: formData.get('eventName') || '',
        eventType: formData.get('eventType') || '',
        eventValue: formData.get('eventValue') || '',
        eventDescription: formData.get('eventDescription') || ''
      };

      const errors = validateForm(data);

      if (errors.length > 0) {
        els.formMessage.textContent = errors.join(' ');
        els.formMessage.className = 'message error';
        return;
      }

      const numericValue = Number(data.eventValue);

      addFeedItem(
        data.eventName,
        `${data.eventDescription || 'Manual event submitted.'} Value: ${numericValue}`,
        data.eventType
      );

      state.metrics.transactions += 1;
      state.metrics.activeUsers = clamp(state.metrics.activeUsers + (data.eventType === 'success' ? 2 : 0), 80, 220);
      state.chartData.push({
        label: state.chartData.length + 1,
        value: clamp(numericValue, 20, 120)
      });

      if (state.chartData.length > 30) {
        state.chartData.shift();
      }

      renderMetrics();
      renderChart();

      els.form.reset();
      els.formMessage.textContent = 'Event submitted successfully.';
      els.formMessage.className = 'message success';

      setTimeout(() => {
        els.formMessage.textContent = '';
        els.formMessage.className = 'message';
      }, 3000);
    });

    function init() {
      addFeedItem('Dashboard initialized', 'Real-time monitoring started.', 'success');
      addFeedItem('Data source connected', 'Streaming mock telemetry is active.', 'info');
      renderMetrics();
      renderChart();
      renderFeed();
      setInterval(simulateRealtimeUpdate, 2000);
    }

    init();
  </script>
</body>
</html>
```

