# 2. `server.js`

This server:

- Serves static frontend files
- Emits simulated real-time metrics every 2 seconds
- Accepts form submissions
- Broadcasts submitted entries to all connected clients

```js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const PORT = process.env.PORT || 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

let submissions = [];
let metricHistory = [];

function generateMetric() {
  const timestamp = new Date().toLocaleTimeString();
  const value = Math.floor(Math.random() * 100) + 1;

  const point = { timestamp, value };
  metricHistory.push(point);

  if (metricHistory.length > 20) {
    metricHistory.shift();
  }

  return point;
}

app.get('/api/submissions', (req, res) => {
  res.json(submissions);
});

app.get('/api/metrics', (req, res) => {
  res.json(metricHistory);
});

app.post('/api/submit', (req, res) => {
  const { name, email, category, amount } = req.body;

  if (!name || !email || !category || amount === undefined) {
    return res.status(400).json({
      success: false,
      message: 'All fields are required.'
    });
  }

  const entry = {
    id: Date.now(),
    name,
    email,
    category,
    amount: Number(amount),
    createdAt: new Date().toISOString()
  };

  submissions.unshift(entry);

  io.emit('newSubmission', entry);

  res.json({
    success: true,
    message: 'Submission received successfully.',
    data: entry
  });
});

io.on('connection', (socket) => {
  console.log('Client connected:', socket.id);

  socket.emit('initialMetrics', metricHistory);
  socket.emit('initialSubmissions', submissions);

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

setInterval(() => {
  const metric = generateMetric();
  io.emit('metricUpdate', metric);
}, 2000);

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

