# 5. `public/app.js`

This handles:

- Socket connection
- Live chart updates
- Form submission
- Table rendering
- Summary stats updates

```js
const socket = io();

const connectionStatus = document.getElementById('connectionStatus');
const totalSubmissionsEl = document.getElementById('totalSubmissions');
const latestMetricEl = document.getElementById('latestMetric');
const averageAmountEl = document.getElementById('averageAmount');
const submissionsTableBody = document.getElementById('submissionsTableBody');
const dataForm = document.getElementById('dataForm');
const formMessage = document.getElementById('formMessage');

let submissions = [];
let metrics = [];

const ctx = document.getElementById('metricsChart').getContext('2d');

const metricsChart = new Chart(ctx, {
  type: 'line',
  data: {
    labels: [],
    datasets: [
      {
        label: 'Metric Value',
        data: [],
        borderColor: '#2563eb',
        backgroundColor: 'rgba(37, 99, 235, 0.15)',
        fill: true,
        tension: 0.3
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        beginAtZero: true
      }
    }
  }
});

function updateChart() {
  metricsChart.data.labels = metrics.map(point => point.timestamp);
  metricsChart.data.datasets[0].data = metrics.map(point => point.value);
  metricsChart.update();
}

function renderSubmissions() {
  submissionsTableBody.innerHTML = '';

  submissions.slice(0, 10).forEach(entry => {
    const row = document.createElement('tr');
    row.innerHTML = `
      <td>${entry.name}</td>
      <td>${entry.email}</td>
      <td>${entry.category}</td>
      <td>${entry.amount.toFixed(2)}</td>
      <td>${new Date(entry.createdAt).toLocaleString()}</td>
    `;
    submissionsTableBody.appendChild(row);
  });
}

function updateStats() {
  totalSubmissionsEl.textContent = submissions.length;
  latestMetricEl.textContent = metrics.length ? metrics[metrics.length - 1].value : '--';

  if (submissions.length === 0) {
    averageAmountEl.textContent = '0.00';
    return;
  }

  const total = submissions.reduce((sum, item) => sum + Number(item.amount), 0);
  const average = total / submissions.length;
  averageAmountEl.textContent = average.toFixed(2);
}

socket.on('connect', () => {
  connectionStatus.textContent = 'Connected';
  connectionStatus.classList.remove('disconnected');
  connectionStatus.classList.add('connected');
});

socket.on('disconnect', () => {
  connectionStatus.textContent = 'Disconnected';
  connectionStatus.classList.remove('connected');
  connectionStatus.classList.add('disconnected');
});

socket.on('initialMetrics', (initialMetrics) => {
  metrics = initialMetrics;
  updateChart();
  updateStats();
});

socket.on('metricUpdate', (metric) => {
  metrics.push(metric);

  if (metrics.length > 20) {
    metrics.shift();
  }

  updateChart();
  updateStats();
});

socket.on('initialSubmissions', (initialSubmissions) => {
  submissions = initialSubmissions;
  renderSubmissions();
  updateStats();
});

socket.on('newSubmission', (entry) => {
  submissions.unshift(entry);
  renderSubmissions();
  updateStats();
});

dataForm.addEventListener('submit', async (event) => {
  event.preventDefault();

  const formData = new FormData(dataForm);
  const payload = {
    name: formData.get('name'),
    email: formData.get('email'),
    category: formData.get('category'),
    amount: formData.get('amount')
  };

  formMessage.textContent = 'Submitting...';
  formMessage.style.color = '#374151';

  try {
    const response = await fetch('/api/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (!response.ok) {
      throw new Error(result.message || 'Submission failed');
    }

    formMessage.textContent = result.message;
    formMessage.style.color = '#166534';
    dataForm.reset();
  } catch (error) {
    formMessage.textContent = error.message;
    formMessage.style.color = '#991b1b';
  }
});
