            <option value="info">Info</option>
            <option value="warning">Warning</option>
            <option value="error">Error</option>
          </select>
          <input type="number" id="eventValue" placeholder="Value" required />
          <button type="submit">Submit</button>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const labels = [];
    const dataPoints = [];
    let submittedEvents = 0;

    const ctx = document.getElementById('liveChart').getContext('2d');
    const liveChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: dataPoints,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateStats() {
      const current = dataPoints[dataPoints.length - 1] || 0;
      const avg = dataPoints.length
        ? (dataPoints.reduce((sum, val) => sum + val, 0) / dataPoints.length).toFixed(1)
        : 0;

      document.getElementById('currentValue').textContent = current;
      document.getElementById('averageValue').textContent = avg;
      document.getElementById('eventCount').textContent = submittedEvents;
    }

    function addLiveDataPoint() {
      const now = new Date();
      const label = now.toLocaleTimeString();
      const value = Math.floor(Math.random() * 100);

      labels.push(label);
      dataPoints.push(value);

      if (labels.length > 20) {
        labels.shift();
        dataPoints.shift();
      }

      liveChart.update();
      updateStats();
    }

    setInterval(addLiveDataPoint, 1000);
    addLiveDataPoint();

    const eventForm = document.getElementById('eventForm');
    const eventLog = document.getElementById('eventLog');

    eventForm.addEventListener('submit', function (e) {
      e.preventDefault();

      const name = document.getElementById('eventName').value.trim();
      const type = document.getElementById('eventType').value;
      const value = document.getElementById('eventValue').value;

      if (!name || !type || value === '') return;

      submittedEvents++;

      const logItem = document.createElement('div');
      logItem.className = 'log-item';
      logItem.innerHTML = `
        <strong>${name}</strong> 
        <span style="color:#6b7280;">(${type})</span> 
        - Value: ${value}
      `;

      eventLog.prepend(logItem);
      updateStats();
      eventForm.reset();
    });
  </script>
</body>
</html>
```

