## `app.js`

```javascript
const MAX_POINTS = 20;

const state = {
  records: [],
  streamActive: true,
  intervalId: null
};

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const peakValueEl = document.getElementById("peakValue");
const totalRecordsEl = document.getElementById("totalRecords");
const recordsTableBody = document.getElementById("recordsTableBody");
const dataForm = document.getElementById("dataForm");
const formMessage = document.getElementById("formMessage");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const clearDataBtn = document.getElementById("clearDataBtn");

const ctx = document.getElementById("liveChart").getContext("2d");

const chartData = {
  labels: [],
  datasets: [
    {
      label: "Value",
      data: [],
      borderColor: "#3b82f6",
      backgroundColor: "rgba(59, 130, 246, 0.2)",
      fill: true,
      tension: 0.3,
      pointRadius: 3
    }
  ]
};

const liveChart = new Chart(ctx, {
  type: "line",
  data: chartData,
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.1)" }
      },
      y: {
        beginAtZero: true,
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.1)" }
      }
    }
  }
});

function formatTime(date = new Date()) {
  return date.toLocaleTimeString();
}

function calculateMetrics() {
  const values = state.records.map(record => record.value);

  const current = values.length ? values[values.length - 1] : 0;
  const average = values.length
    ? (values.reduce((sum, value) => sum + value, 0) / values.length).toFixed(2)
    : 0;
  const peak = values.length ? Math.max(...values) : 0;
  const total = values.length;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  peakValueEl.textContent = peak;
  totalRecordsEl.textContent = total;
}

function renderTable() {
  recordsTableBody.innerHTML = "";

  const recentRecords = [...state.records].reverse().slice(0, 10);

  recentRecords.forEach(record => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${record.time}</td>
      <td>${record.label}</td>
      <td>${record.value}</td>
      <td>${record.category}</td>
      <td>${record.note || "-"}</td>
    `;
    recordsTableBody.appendChild(row);
  });
}

function updateChart() {
  const recentRecords = state.records.slice(-MAX_POINTS);
  liveChart.data.labels = recentRecords.map(record => record.time);
  liveChart.data.datasets[0].data = recentRecords.map(record => record.value);
  liveChart.update();
}

function refreshUI() {
  calculateMetrics();
  renderTable();
  updateChart();
}

function addRecord(record) {
  state.records.push(record);
  refreshUI();
}

function generateRandomRecord() {
  const categories = ["system", "sensor", "user"];
  const randomValue = Math.floor(Math.random() * 100) + 1;

  return {
    time: formatTime(),
    label: "Auto Stream",
    value: randomValue,
    category: categories[Math.floor(Math.random() * categories.length)],
    note: "Simulated real-time event"
  };
}

function startStream() {
  state.intervalId = setInterval(() => {
    if (state.streamActive) {
      addRecord(generateRandomRecord());
    }
  }, 1500);
}

function stopStream() {
  clearInterval(state.intervalId);
  state.intervalId = null;
}

dataForm.addEventListener("submit", event => {
  event.preventDefault();

  const formData = new FormData(dataForm);
  const label = formData.get("label").trim();
  const value = Number(formData.get("value"));
  const category = formData.get("category");
  const note = formData.get("note").trim();

  if (!label || Number.isNaN(value)) {
    formMessage.textContent = "Please provide valid input values.";
    formMessage.style.color = "#ef4444";
    return;
  }

  addRecord({
    time: formatTime(),
    label,
    value,
    category,
    note
  });

  formMessage.textContent = "Record submitted successfully.";
  formMessage.style.color = "#10b981";
  dataForm.reset();
});

toggleStreamBtn.addEventListener("click", () => {
  state.streamActive = !state.streamActive;
  toggleStreamBtn.textContent = state.streamActive ? "Pause Stream" : "Resume Stream";
});

clearDataBtn.addEventListener("click", () => {
  state.records = [];
  refreshUI();
  formMessage.textContent = "All data cleared.";
  formMessage.style.color = "#10b981";
});

refreshUI();
startStream();
```

