        <div class="card stat-card">
          <h3>Samples</h3>
          <div class="value" id="sampleCount">0</div>
        </div>
      </section>

      <section class="card chart-card">
        <h2>Live Metric Chart</h2>
        <canvas id="chart" width="900" height="320"></canvas>
      </section>

      <aside class="card form-card">
        <h2>Dashboard Settings</h2>
        <form id="settingsForm">
          <div class="field">
            <label for="metricName">Metric Name</label>
            <input id="metricName" name="metricName" type="text" value="CPU Load" required />
          </div>

          <div class="field">
            <label for="updateInterval">Update Interval (ms)</label>
            <input id="updateInterval" name="updateInterval" type="number" min="100" step="100" value="1000" required />
          </div>

          <div class="field">
            <label for="threshold">Alert Threshold</label>
            <input id="threshold" name="threshold" type="number" min="0" max="100" value="75" required />
          </div>

          <div class="field">
            <label for="themeMode">Display Mode</label>
            <select id="themeMode" name="themeMode">
              <option value="dark" selected>Dark</option>
              <option value="light">Light</option>
            </select>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional dashboard notes..."></textarea>
          </div>

          <div class="form-actions">
            <button type="submit" class="primary">Save Settings</button>
            <button type="button" id="simulateAlertBtn">Simulate Alert</button>
          </div>
        </form>
        <div class="status" id="formStatus"></div>
      </aside>

      <section class="card log-card">
        <h2>Event Log</h2>
        <ul class="log-list" id="eventLog"></ul>
      </section>
    </div>
  </div>

  <script>
    const state = {
      metricName: "CPU Load",
      updateInterval: 1000,
      threshold: 75,
      themeMode: "dark",
      notes: "",
      data: [],
      maxPoints: 30,
      timer: null
    };

    const elements = {
      chart: document.getElementById("chart"),
      currentValue: document.getElementById("currentValue"),
      averageValue: document.getElementById("averageValue"),
      peakValue: document.getElementById("peakValue"),
      sampleCount: document.getElementById("sampleCount"),
      eventLog: document.getElementById("eventLog"),
      form: document.getElementById("settingsForm"),
      formStatus: document.getElementById("formStatus"),
      startBtn: document.getElementById("startBtn"),
      stopBtn: document.getElementById("stopBtn"),
      resetBtn: document.getElementById("resetBtn"),
      simulateAlertBtn: document.getElementById("simulateAlertBtn")
    };

    const ctx = elements.chart.getContext("2d");

    function randomMetricValue() {
      const base = 40 + Math.random() * 30;
      const spike = Math.random() > 0.85 ? Math.random() * 35 : 0;
      return Math.min(100, Math.round(base + spike));
    }

    function addLog(message, type = "info") {
      const li = document.createElement("li");
      li.className = "log-item";

      const text = document.createElement("div");
      text.innerHTML = `<strong>${message}</strong>`;

      const meta = document.createElement("span");
      meta.textContent = new Date().toLocaleTimeString();

      if (type === "alert") {
        const badge = document.createElement("span");
        badge.className = "badge";
        badge.textContent = "ALERT";
        text.appendChild(document.createTextNode(" "));
        text.appendChild(badge);
      }

      li.appendChild(text);
      li.appendChild(meta);

      elements.eventLog.prepend(li);

      while (elements.eventLog.children.length > 20) {
        elements.eventLog.removeChild(elements.eventLog.lastChild);
      }
    }

    function updateStats() {
      const values = state.data.map(point => point.value);
      const current = values[values.length - 1] ?? 0;
      const average = values.length
        ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
        : 0;
      const peak = values.length ? Math.max(...values) : 0;

      elements.currentValue.textContent = current;
      elements.averageValue.textContent = average;
      elements.peakValue.textContent = peak;
      elements.sampleCount.textContent = values.length;
    }

    function drawChart() {
      const canvas = elements.chart;
      const width = canvas.width;
      const height = canvas.height;

      ctx.clearRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Axis labels
      ctx.fillStyle = "rgba(148, 163, 184, 0.8)";
      ctx.font = "12px sans-serif";
      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = (height / 5) * i;
        ctx.fillText(value.toString(), 8, y + 14);
      }

      if (state.data.length < 2) return;

      const paddingX = 40;
      const chartWidth = width - paddingX - 10;
      const chartHeight = height - 20;

      // Threshold line
      const thresholdY = chartHeight - (state.threshold / 100) * chartHeight;
      ctx.strokeStyle = "rgba(245, 158, 11, 0.9)";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(paddingX, thresholdY);
      ctx.lineTo(width - 10, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Line
      ctx.beginPath();
      ctx.lineWidth = 3;
      ctx.strokeStyle = "#3b82f6";

      state.data.forEach((point, index) => {
        const x = paddingX + (index / (state.maxPoints - 1)) * chartWidth;
        const y = chartHeight - (point.value / 100) * chartHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Fill
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");

      ctx.lineTo(paddingX + chartWidth, chartHeight);
      ctx.lineTo(paddingX, chartHeight);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Points
      state.data.forEach((point, index) => {
        const x = paddingX + (index / (state.maxPoints - 1)) * chartWidth;
        const y = chartHeight - (point.value / 100) * chartHeight;

        ctx.beginPath();
        ctx.fillStyle = point.value >= state.threshold ? "#f59e0b" : "#22c55e";
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function pushDataPoint() {
      const value = randomMetricValue();
      const point = {
        time: Date.now(),
        value
      };

      state.data.push(point);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }

      updateStats();
      drawChart();

      if (value >= state.threshold) {
        addLog(`${state.metricName} exceeded threshold with value ${value}`, "alert");
      }
    }

    function startStream() {
      stopStream();
      state.timer = setInterval(pushDataPoint, state.updateInterval);
      addLog(`Started ${state.metricName} stream at ${state.updateInterval}ms interval`);
    }

    function stopStream() {
      if (state.timer) {
        clearInterval(state.timer);
        state.timer = null;
        addLog(`Stopped ${state.metricName} stream`);
      }
    }

    function resetData() {
      state.data = [];
      updateStats();
      drawChart();
      addLog(`Reset dashboard data`);
    }

    function applyTheme(mode) {
      if (mode === "light") {
        document.documentElement.style.setProperty("--bg", "#f8fafc");
        document.documentElement.style.setProperty("--panel", "#ffffff");
        document.documentElement.style.setProperty("--panel-2", "#e2e8f0");
        document.documentElement.style.setProperty("--border", "#cbd5e1");
        document.documentElement.style.setProperty("--text", "#0f172a");
        document.documentElement.style.setProperty("--muted", "#475569");
        document.body.style.background = "linear-gradient(180deg, #e2e8f0 0%, #f8fafc 100%)";
      } else {
        document.documentElement.style.setProperty("--bg", "#0f172a");
        document.documentElement.style.setProperty("--panel", "#111827");
        document.documentElement.style.setProperty("--panel-2", "#1f2937");
        document.documentElement.style.setProperty("--border", "#334155");
        document.documentElement.style.setProperty("--text", "#e5e7eb");
        document.documentElement.style.setProperty("--muted", "#94a3b8");
        document.body.style.background = "linear-gradient(180deg, #0b1220 0%, #0f172a 100%)";
      }
      drawChart();
    }

    elements.form.addEventListener("submit", (event) => {
      event.preventDefault();

      const formData = new FormData(elements.form);
      const metricName = formData.get("metricName").toString().trim();
      const updateInterval = Number(formData.get("updateInterval"));
      const threshold = Number(formData.get("threshold"));
      const themeMode = formData.get("themeMode").toString();
      const notes = formData.get("notes").toString().trim();

      if (!metricName) {
        elements.formStatus.textContent = "Metric name is required.";
        elements.formStatus.style.color = "#fca5a5";
        return;
      }

      if (Number.isNaN(updateInterval) || updateInterval < 100) {
        elements.formStatus.textContent = "Update interval must be at least 100ms.";
        elements.formStatus.style.color = "#fca5a5";
        return;
      }

      if (Number.isNaN(threshold) || threshold < 0 || threshold > 100) {
        elements.formStatus.textContent = "Threshold must be between 0 and 100.";
        elements.formStatus.style.color = "#fca5a5";
        return;
      }

      state.metricName = metricName;
      state.updateInterval = updateInterval;
      state.threshold = threshold;
      state.themeMode = themeMode;
      state.notes = notes;

      applyTheme(themeMode);

      if (state.timer) {
        startStream();
      }

      elements.formStatus.textContent = "Settings saved successfully.";
      elements.formStatus.style.color = "#86efac";

      addLog(`Updated settings for ${metricName}`);
    });

    elements.startBtn.addEventListener("click", startStream);
    elements.stopBtn.addEventListener("click", stopStream);
    elements.resetBtn.addEventListener("click", resetData);

    elements.simulateAlertBtn.addEventListener("click", () => {
      const simulatedValue = Math.max(state.threshold + 5, 80);
      state.data.push({ time: Date.now(), value: simulatedValue });
      if (state.data.length > state.maxPoints) state.data.shift();
      updateStats();
      drawChart();
      addLog(`${state.metricName} simulated alert at value ${simulatedValue}`, "alert");
    });

    window.addEventListener("resize", drawChart);

    // Initial render
    updateStats();
    drawChart();
    addLog("Dashboard initialized");
  </script>
</body>
</html>
```

