## `app.js`

```javascript
const labels = [];
const values = [];
const maxPoints = 20;

let feedRunning = true;
let feedInterval = null;

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const totalPointsEl = document.getElementById("totalPoints");
const eventLogEl = document.getElementById("eventLog");
const dataForm = document.getElementById("dataForm");
const labelInput = document.getElementById("labelInput");
const valueInput = document.getElementById("valueInput");
const toggleFeedBtn = document.getElementById("toggleFeedBtn");
const clearDataBtn = document.getElementById("clearDataBtn");

const ctx = document.getElementById("liveChart").getContext("2d");

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Sensor Value",
        data: values,
        borderColor: "#22c55e",
        backgroundColor: "rgba(34, 197, 94, 0.2)",
        fill: true,
        tension: 0.3,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
    },
  },
});

function getCurrentTimeLabel() {
  return new Date().toLocaleTimeString();
}

function addDataPoint(label, value, source = "manual") {
  labels.push(label);
  values.push(value);

  if (labels.length > maxPoints) {
    labels.shift();
    values.shift();
  }

  liveChart.update();
  updateMetrics();
  addEventLog(`${source.toUpperCase()}: Added value ${value} at ${label}`);
}

function updateMetrics() {
  const total = values.length;
  const current = total ? values[total - 1] : 0;
  const average = total
    ? (values.reduce((sum, val) => sum + val, 0) / total).toFixed(2)
    : 0;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  totalPointsEl.textContent = total;
}

function addEventLog(message) {
  const item = document.createElement("li");
  item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(item);

  while (eventLogEl.children.length > 10) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function generateRandomValue() {
  return Math.floor(Math.random() * 100) + 1;
}

function startFeed() {
  feedInterval = setInterval(() => {
    if (!feedRunning) return;
    addDataPoint(getCurrentTimeLabel(), generateRandomValue(), "auto");
  }, 1000);
}

function toggleFeed() {
  feedRunning = !feedRunning;
  toggleFeedBtn.textContent = feedRunning ? "Pause Feed" : "Resume Feed";
  addEventLog(feedRunning ? "Auto feed resumed" : "Auto feed paused");
}

function clearData() {
  labels.length = 0;
  values.length = 0;
  liveChart.update();
  updateMetrics();
  addEventLog("All chart data cleared");
}

dataForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const label = labelInput.value.trim();
  const value = parseFloat(valueInput.value);

  if (!label || Number.isNaN(value)) {
    addEventLog("Invalid form submission");
    return;
  }

  addDataPoint(label, value, "manual");
  dataForm.reset();
  labelInput.focus();
});

toggleFeedBtn.addEventListener("click", toggleFeed);
clearDataBtn.addEventListener("click", clearData);

updateMetrics();
startFeed();
```

