<body>
  <div class="container">
    <section class="main">
      <h1>Real-Time Dashboard</h1>

      <div class="stats">
        <div class="card">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="card">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="card">
          <div class="label">Data Points</div>
          <div class="value" id="pointCount">0</div>
        </div>
      </div>

      <div class="chart-container">
        <h3>Live Data Stream</h3>
        <canvas id="chart" width="900" height="320"></canvas>
      </div>
    </section>

    <aside class="sidebar">
      <h2>Controls</h2>

      <form id="dataForm">
        <label>
          Metric Name
          <input type="text" id="metricName" name="metricName" placeholder="e.g. Temperature" required />
        </label>

        <label>
          Initial Value
          <input type="number" id="initialValue" name="initialValue" value="50" required />
        </label>

        <label>
          Update Interval (ms)
          <select id="interval" name="interval">
            <option value="500">500</option>
            <option value="1000" selected>1000</option>
            <option value="2000">2000</option>
          </select>
        </label>

        <button type="submit">Start Stream</button>
        <button type="button" class="secondary" id="stopBtn">Stop Stream</button>
        <button type="button" class="secondary" id="resetBtn">Reset Data</button>
      </form>

      <div class="log" id="eventLog">
        <div class="log-item">System ready.</div>
      </div>
    </aside>
  </div>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const pointCountEl = document.getElementById('pointCount');
    const eventLog = document.getElementById('eventLog');

    const form = document.getElementById('dataForm');
    const metricNameInput = document.getElementById('metricName');
    const initialValueInput = document.getElementById('initialValue');
    const intervalInput = document.getElementById('interval');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    let data = [];
    let timer = null;
    let metricName = 'Metric';

    function log(message, type = '') {
      const item = document.createElement('div');
      item.className = `log-item ${type}`;
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);
    }

    function updateStats() {
      const count = data.length;
      const current = count ? data[data.length - 1] : 0;
      const avg = count
        ? data.reduce((sum, val) => sum + val, 0) / count
        : 0;

      currentValueEl.textContent = current.toFixed(2);
      averageValueEl.textContent = avg.toFixed(2);
      pointCountEl.textContent = count;
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const max = Math.max(...data);
      const min = Math.min(...data);
      const range = max - min || 1;

      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = (index / (data.length - 1)) * width;
        const y = height - ((value - min) / range) * (height - 20) - 10;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.fillStyle = '#3b82f6';
      data.forEach((value, index) => {
        const x = (index / (data.length - 1)) * width;
        const y = height - ((value - min) / range) * (height - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px Arial';
      ctx.fillText(`${metricName} (min: ${min.toFixed(1)}, max: ${max.toFixed(1)})`, 10, 18);
    }

    function generateNextValue(lastValue) {
      const variation = (Math.random() - 0.5) * 10;
      return Math.max(0, lastValue + variation);
    }

    function pushDataPoint(value) {
      data.push(value);
      if (data.length > 30) data.shift();
      updateStats();
      drawChart();
    }

    function startStream(initialValue, interval) {
      if (timer) clearInterval(timer);

      let current = initialValue;
      pushDataPoint(current);

      timer = setInterval(() => {
        current = generateNextValue(current);
        pushDataPoint(current);
      }, interval);

      log(`Started "${metricName}" stream at ${interval}ms interval.`, 'success');
    }

    function stopStream() {
      if (timer) {
        clearInterval(timer);
        timer = null;
        log('Stream stopped.', 'error');
      }
    }

    function resetData() {
      data = [];
      updateStats();
      drawChart();
      log('Data reset.');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = metricNameInput.value.trim();
      const initialValue = parseFloat(initialValueInput.value);
      const interval = parseInt(intervalInput.value, 10);

      if (!name) {
        log('Metric name is required.', 'error');
        return;
      }

      if (Number.isNaN(initialValue)) {
        log('Initial value must be a valid number.', 'error');
        return;
      }

      metricName = name;
      resetData();
      startStream(initialValue, interval);
    });

    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetData);

    updateStats();
    drawChart();
  </script>
</body>
</html>
```

## What this includes

- A live-updating chart drawn with `<canvas>`
- Summary stat cards:
  - current value
  - average
  - number of data points
- A control form to:
  - set metric name
  - set initial value
  - choose update interval
- Buttons to:
  - start stream
  - stop stream
  - reset data
- Event log for user actions

