  <script>
    const maxPoints = 20;
    const labels = [];
    const trafficData = [];
    const responseData = [];

    function currentTimeLabel() {
      return new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
    }

    function randomBetween(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetric(id, trendId, newValue, formatter, trendValue, inverse = false) {
      document.getElementById(id).textContent = formatter(newValue);

      const trendEl = document.getElementById(trendId);
      const sign = trendValue > 0 ? "+" : "";
      trendEl.textContent = `${sign}${trendValue.toFixed(1)}%`;

      trendEl.classList.remove("positive", "negative", "neutral");

      if (trendValue === 0) {
        trendEl.classList.add("neutral");
      } else {
        const isPositive = inverse ? trendValue < 0 : trendValue > 0;
        trendEl.classList.add(isPositive ? "positive" : "negative");
      }
    }

    const lineChart = new Chart(document.getElementById("lineChart"), {
      type: "line",
      data: {
        labels,
        datasets: [
          {
            label: "Requests / Min",
            data: trafficData,
            borderColor: "#3b82f6",
            backgroundColor: "rgba(59,130,246,0.2)",
            tension: 0.35,
            fill: true
          },
          {
            label: "Response Time (ms)",
            data: responseData,
            borderColor: "#22c55e",
            backgroundColor: "rgba(34,197,94,0.15)",
            tension: 0.35,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.12)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.12)" }
          }
        }
      }
    });

    const doughnutChart = new Chart(document.getElementById("doughnutChart"), {
      type: "doughnut",
      data: {
        labels: ["API", "Web", "Mobile", "Background Jobs"],
        datasets: [{
          data: [35, 30, 20, 15],
          backgroundColor: ["#3b82f6", "#22c55e", "#f59e0b", "#ef4444"],
          borderColor: "#111827",
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const barChart = new Chart(document.getElementById("barChart"), {
      type: "bar",
      data: {
        labels: ["CPU", "Memory", "Disk", "Queue"],
        datasets: [{
          label: "Usage %",
          data: [55, 68, 42, 37],
          backgroundColor: ["#3b82f6", "#22c55e", "#f59e0b", "#ef4444"],
          borderRadius: 8
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { display: false }
          },
          y: {
            beginAtZero: true,
            max: 100,
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148,163,184,0.12)" }
          }
        }
      }
    });

    let metrics = {
      activeUsers: 1240,
      transactions: 320,
      errorRate: 1.8,
      responseTime: 240
    };

    function seedInitialData() {
      for (let i = 0; i < 10; i++) {
        labels.push(currentTimeLabel());
        trafficData.push(randomBetween(220, 420));
        responseData.push(randomBetween(180, 320));
      }
      lineChart.update();
    }

    function simulateRealtimeUpdate() {
      const prev = { ...metrics };

      metrics.activeUsers = Math.max(100, metrics.activeUsers + randomBetween(-25, 35));
      metrics.transactions = Math.max(50, metrics.transactions + randomBetween(-20, 25));
      metrics.errorRate = Math.max(0.1, +(metrics.errorRate + (Math.random() * 0.6 - 0.3)).toFixed(2));
      metrics.responseTime = Math.max(80, metrics.responseTime + randomBetween(-20, 30));

      const activeUsersTrend = ((metrics.activeUsers - prev.activeUsers) / prev.activeUsers) * 100;
      const transactionsTrend = ((metrics.transactions - prev.transactions) / prev.transactions) * 100;
      const errorRateTrend = ((metrics.errorRate - prev.errorRate) / prev.errorRate) * 100;
      const responseTimeTrend = ((metrics.responseTime - prev.responseTime) / prev.responseTime) * 100;

      updateMetric("activeUsers", "activeUsersTrend", metrics.activeUsers, v => v.toLocaleString(), activeUsersTrend);
      updateMetric("transactions", "transactionsTrend", metrics.transactions, v => v.toLocaleString(), transactionsTrend);
      updateMetric("errorRate", "errorRateTrend", metrics.errorRate, v => `${v.toFixed(2)}%`, errorRateTrend, true);
      updateMetric("responseTime", "responseTimeTrend", metrics.responseTime, v => `${v} ms`, responseTimeTrend, true);

      labels.push(currentTimeLabel());
      trafficData.push(metrics.transactions + randomBetween(-15, 15));
      responseData.push(metrics.responseTime);

      if (labels.length > maxPoints) {
        labels.shift();
        trafficData.shift();
        responseData.shift();
      }

      lineChart.update();

      doughnutChart.data.datasets[0].data = [
        randomBetween(20, 40),
        randomBetween(20, 35),
        randomBetween(10, 25),
        randomBetween(10, 20)
      ];
      doughnutChart.update();

      barChart.data.datasets[0].data = [
        randomBetween(35, 90),
        randomBetween(40, 95),
        randomBetween(20, 80),
        randomBetween(10, 70)
      ];
      barChart.update();
    }

    function addLogEntry(entry) {
      const log = document.getElementById("activityLog");
      const item = document.createElement("li");
      item.className = "log-item";
      item.innerHTML = `
        <div class="log-meta">${entry.time} • ${entry.category} • ${entry.priority} • ${entry.owner}</div>
        <strong>${entry.title}</strong>
        <div>${entry.description}</div>
      `;
      log.prepend(item);

      while (log.children.length > 12) {
        log.removeChild(log.lastChild);
      }
    }

    document.getElementById("dashboardForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const formData = new FormData(this);
      const entry = {
        title: formData.get("title").trim(),
        category: formData.get("category"),
        priority: formData.get("priority"),
        owner: formData.get("owner").trim(),
        description: formData.get("description").trim(),
        time: new Date().toLocaleString()
      };

      if (!entry.title || !entry.category || !entry.priority || !entry.owner || !entry.description) {
        document.getElementById("formMessage").textContent = "Please complete all fields.";
        document.getElementById("formMessage").style.color = "#ef4444";
        return;
      }

      addLogEntry(entry);

      document.getElementById("formMessage").textContent = "Submission added successfully.";
      document.getElementById("formMessage").style.color = "#22c55e";

      this.reset();
    });

    document.getElementById("dashboardForm").addEventListener("reset", function () {
      setTimeout(() => {
        document.getElementById("formMessage").textContent = "";
      }, 0);
    });

    seedInitialData();
    simulateRealtimeUpdate();
    setInterval(simulateRealtimeUpdate, 2000);

    [
      {
        title: "API latency spike detected",
        category: "Alert",
        priority: "High",
        owner: "System",
        description: "Response time exceeded threshold for 2 minutes.",
        time: new Date().toLocaleString()
      },
      {
        title: "Nightly maintenance completed",
        category: "Maintenance",
        priority: "Low",
        owner: "Ops Team",
        description: "Database optimization and cache refresh completed successfully.",
        time: new Date().toLocaleString()
      }
    ].forEach(addLogEntry);
  </script>
</body>
</html>
