              <button type="submit" class="btn-primary">Add Record</button>
            </div>
          </form>
        </div>

        <div class="panel">
          <h2>System Notes</h2>
          <div class="small-note">
            This starter dashboard uses simulated data in the browser. In production, replace the generator with:
            <ul>
              <li>WebSocket stream</li>
