  <script>
    const state = {
      data: [],
      events: [],
      threshold: 75,
      updateInterval: 1000,
      maxPoints: 40,
      timer: null,
      paused: false,
      alertCount: 0,
      peak: 0
    };

    const els = {
      currentValue: document.getElementById("currentValue"),
      averageValue: document.getElementById("averageValue"),
      peakValue: document.getElementById("peakValue"),
      alertCount: document.getElementById("alertCount"),
      eventsTableBody: document.getElementById("eventsTableBody"),
      settingsForm: document.getElementById("settingsForm"),
      manualEntryForm: document.getElementById("manualEntryForm"),
      updateInterval: document.getElementById("updateInterval"),
      threshold: document.getElementById("threshold"),
      maxPoints: document.getElementById("maxPoints"),
      formMessage: document.getElementById("formMessage"),
      toggleStreamBtn: document.getElementById("toggleStreamBtn"),
      resetBtn: document.getElementById("resetBtn"),
      connectionStatus: document.getElementById("connectionStatus"),
      manualValue: document.getElementById("manualValue"),
      manualSource: document.getElementById("manualSource"),
      canvas: document.getElementById("chartCanvas")
    };

    const ctx = els.canvas.getContext("2d");

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function randomValue() {
      const base = 40 + Math.random() * 30;
      const spike = Math.random() > 0.85 ? Math.random() * 35 : 0;
      return Math.min(100, Math.round(base + spike));
    }

    function addDataPoint(value, source = "sensor") {
      const timestamp = new Date();
      const status = value >= state.threshold ? "alert" : "normal";

      state.data.push({
        time: timestamp,
        value
      });

      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }

      state.events.unshift({
        time: formatTime(timestamp),
        value,
        source,
        status
      });

      if (state.events.length > 12) {
        state.events.pop();
      }

      if (value >= state.threshold) {
        state.alertCount += 1;
      }

      state.peak = Math.max(state.peak, value);

      updateMetrics();
      renderTable();
      drawChart();
    }

    function updateMetrics() {
      const latest = state.data[state.data.length - 1];
      const values = state.data.map(d => d.value);
      const avg = values.length
        ? values.reduce((sum, v) => sum + v, 0) / values.length
        : 0;

      els.currentValue.textContent = latest ? latest.value : 0;
      els.averageValue.textContent = avg.toFixed(1);
      els.peakValue.textContent = state.peak.toFixed(0);
      els.alertCount.textContent = state.alertCount;
    }

    function renderTable() {
      els.eventsTableBody.innerHTML = state.events.map(event => {
        const sourceClass = event.source === "manual" || event.source === "operator" || event.source === "external"
          ? "manual"
          : event.status;

        return `
          <tr>
            <td>${event.time}</td>
            <td>${event.value}</td>
            <td>${event.source}</td>
            <td><span class="tag ${sourceClass === "manual" ? "manual" : event.status}">${event.status}</span></td>
          </tr>
        `;
      }).join("");
    }

    function drawChart() {
      const canvas = els.canvas;
      const width = canvas.width;
      const height = canvas.height;
      const padding = 40;

      ctx.clearRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.fillText(value.toString(), 8, y + 4);
      }

      if (state.data.length === 0) return;

      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;
      const stepX = state.data.length > 1 ? chartWidth / (state.data.length - 1) : chartWidth;

      // Threshold line
      const thresholdY = padding + chartHeight - (state.threshold / 100) * chartHeight;
      ctx.strokeStyle = "rgba(239, 68, 68, 0.7)";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(width - padding, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "#fca5a5";
      ctx.fillText(`Threshold: ${state.threshold}`, width - 130, thresholdY - 8);

      // Area fill
      ctx.beginPath();
      state.data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartHeight - (point.value / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + (state.data.length - 1) * stepX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      state.data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartHeight - (point.value / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      state.data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartHeight - (point.value / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = point.value >= state.threshold ? "#ef4444" : "#22c55e";
        ctx.fill();
      });
    }

    function tick() {
      if (!state.paused) {
        addDataPoint(randomValue(), "sensor");
      }
    }

    function startStream() {
      clearInterval(state.timer);
      state.timer = setInterval(tick, state.updateInterval);
    }

    function stopStream() {
      clearInterval(state.timer);
      state.timer = null;
    }

    function setMessage(message, isError = false) {
      els.formMessage.textContent = message;
      els.formMessage.style.color = isError ? "#fca5a5" : "#93c5fd";
    }

    els.settingsForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const interval = Number(els.updateInterval.value);
      const threshold = Number(els.threshold.value);
      const maxPoints = Number(els.maxPoints.value);

      if (interval < 200 || threshold < 0 || threshold > 100 || maxPoints < 10) {
        setMessage("Please enter valid settings values.", true);
        return;
      }

      state.updateInterval = interval;
      state.threshold = threshold;
      state.maxPoints = maxPoints;

      if (state.data.length > state.maxPoints) {
        state.data = state.data.slice(-state.maxPoints);
      }

      startStream();
      drawChart();
      setMessage("Settings applied successfully.");
    });

    els.toggleStreamBtn.addEventListener("click", () => {
      state.paused = !state.paused;
      els.toggleStreamBtn.textContent = state.paused ? "Resume Stream" : "Pause Stream";
      els.connectionStatus.textContent = state.paused ? "Live Updates Paused" : "Live Updates Active";
      els.connectionStatus.style.background = state.paused
        ? "rgba(245, 158, 11, 0.15)"
        : "rgba(34, 197, 94, 0.15)";
      els.connectionStatus.style.color = state.paused ? "#fcd34d" : "#86efac";
      els.connectionStatus.style.borderColor = state.paused
        ? "rgba(245, 158, 11, 0.35)"
        : "rgba(34, 197, 94, 0.35)";
      setMessage(state.paused ? "Stream paused." : "Stream resumed.");
    });

    els.resetBtn.addEventListener("click", () => {
      state.data = [];
      state.events = [];
      state.alertCount = 0;
      state.peak = 0;
      updateMetrics();
      renderTable();
      drawChart();
      setMessage("Dashboard data has been reset.");
    });

    els.manualEntryForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const value = Number(els.manualValue.value);
      const source = els.manualSource.value;

      if (Number.isNaN(value) || value < 0 || value > 100) {
        setMessage("Manual value must be between 0 and 100.", true);
        return;
      }

      addDataPoint(value, source);
      els.manualEntryForm.reset();
      setMessage(`Manual record added from source: ${source}.`);
    });

    function seedInitialData() {
      for (let i = 0; i < 12; i++) {
        addDataPoint(randomValue(), "sensor");
      }
    }

    function init() {
      seedInitialData();
      startStream();
      drawChart();
    }

    init();

    window.addEventListener("resize", drawChart);
  </script>
</body>
</html>
```

