  <script>
    const state = {
      data: [],
      maxPoints: 40,
      timer: null,
      interval: 1000,
      baseline: 50,
      variance: 15,
      peak: 0,
      eventCount: 0,
      running: true
    };

    const els = {
      chart: document.getElementById('chart'),
      metricCurrent: document.getElementById('metricCurrent'),
      metricTrend: document.getElementById('metricTrend'),
      metricAverage: document.getElementById('metricAverage'),
      metricPeak: document.getElementById('metricPeak'),
      metricEvents: document.getElementById('metricEvents'),
      activityFeed: document.getElementById('activityFeed'),
      liveStatus: document.getElementById('liveStatus'),

      startBtn: document.getElementById('startBtn'),
      stopBtn: document.getElementById('stopBtn'),
      resetBtn: document.getElementById('resetBtn'),

      settingsForm: document.getElementById('settingsForm'),
      eventForm: document.getElementById('eventForm'),

      interval: document.getElementById('interval'),
      baseline: document.getElementById('baseline'),
      variance: document.getElementById('variance'),

      intervalError: document.getElementById('intervalError'),
      baselineError: document.getElementById('baselineError'),
      varianceError: document.getElementById('varianceError'),
      settingsSuccess: document.getElementById('settingsSuccess'),

      eventType: document.getElementById('eventType'),
      message: document.getElementById('message'),
      eventTypeError: document.getElementById('eventTypeError'),
      messageError: document.getElementById('messageError'),
      eventSuccess: document.getElementById('eventSuccess')
    };

    const ctx = els.chart.getContext('2d');

    function resizeCanvas() {
      const rect = els.chart.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      els.chart.width = rect.width * dpr;
      els.chart.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function randomValue() {
      const noise = (Math.random() - 0.5) * 2 * state.variance;
      return Math.max(0, +(state.baseline + noise).toFixed(2));
    }

    function addDataPoint(value = randomValue()) {
      const timestamp = new Date();
      state.data.push({ value, timestamp });

      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }

      state.peak = Math.max(state.peak, value);
      maybeGenerateFeedEvent(value);
      updateMetrics();
      drawChart();
    }

    function maybeGenerateFeedEvent(value) {
      if (value > state.baseline + state.variance * 0.8) {
        addFeedItem('Alert', `High value detected: ${value}`);
      } else if (value < Math.max(0, state.baseline - state.variance * 0.8)) {
        addFeedItem('Warning', `Low value detected: ${value}`);
      }
    }

    function updateMetrics() {
      const values = state.data.map(d => d.value);
      const current = values[values.length - 1] ?? 0;
      const previous = values[values.length - 2] ?? current;
      const avg = values.length
        ? values.reduce((sum, v) => sum + v, 0) / values.length
        : 0;
      const trend = previous === 0 ? 0 : ((current - previous) / previous) * 100;

      els.metricCurrent.textContent = current.toFixed(2);
      els.metricAverage.textContent = avg.toFixed(2);
      els.metricPeak.textContent = state.peak.toFixed(2);
      els.metricEvents.textContent = state.eventCount.toString();

      const trendText = `${trend >= 0 ? '+' : ''}${trend.toFixed(1)}%`;
      els.metricTrend.textContent = trendText;
      els.metricTrend.style.color = trend >= 0 ? '#86efac' : '#fca5a5';
    }

    function drawChart() {
      const width = els.chart.clientWidth;
      const height = els.chart.clientHeight;

      ctx.clearRect(0, 0, width, height);

      const padding = 24;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      ctx.strokeStyle = 'rgba(148, 163, 184, 0.2)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 4; i++) {
        const y = padding + (chartH / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      if (state.data.length < 2) return;

      const values = state.data.map(d => d.value);
      const min = Math.min(...values, state.baseline - state.variance, 0);
      const max = Math.max(...values, state.baseline + state.variance);
      const range = Math.max(1, max - min);

      ctx.beginPath();
      state.data.forEach((point, index) => {
        const x = padding + (index / (state.maxPoints - 1)) * chartW;
        const y = padding + chartH - ((point.value - min) / range) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');

      ctx.lineTo(padding + ((state.data.length - 1) / (state.maxPoints - 1)) * chartW, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      const last = state.data[state.data.length - 1];
      const lastX = padding + ((state.data.length - 1) / (state.maxPoints - 1)) * chartW;
      const lastY = padding + chartH - ((last.value - min) / range) * chartH;

      ctx.beginPath();
      ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
      ctx.fillStyle = '#22c55e';
      ctx.fill();
    }

    function addFeedItem(type, message) {
      state.eventCount += 1;

      const item = document.createElement('div');
      item.className = 'feed-item';
      item.innerHTML = `
        <strong>${escapeHtml(type)}</strong>
        <div>${escapeHtml(message)}</div>
        <time>${new Date().toLocaleTimeString()}</time>
      `;

      els.activityFeed.prepend(item);

      while (els.activityFeed.children.length > 20) {
        els.activityFeed.removeChild(els.activityFeed.lastChild);
      }

      updateMetrics();
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function startStream() {
      stopStream();
      state.running = true;
      updateStatus();
      state.timer = setInterval(() => addDataPoint(), state.interval);
    }

    function stopStream() {
      state.running = false;
      updateStatus();
      if (state.timer) {
        clearInterval(state.timer);
        state.timer = null;
      }
    }

    function updateStatus() {
      els.liveStatus.innerHTML = state.running
        ? '<span class="status-dot"></span><span>Live stream active</span>'
        : '<span class="status-dot" style="background:#f59e0b; box-shadow:0 0 12px #f59e0b;"></span><span>Stream paused</span>';
    }

    function resetDashboard() {
      state.data = [];
      state.peak = 0;
      state.eventCount = 0;
      els.activityFeed.innerHTML = '';
      updateMetrics();
      drawChart();
      addFeedItem('Info', 'Dashboard reset');
    }

    function clearSettingsErrors() {
      els.intervalError.textContent = '';
      els.baselineError.textContent = '';
      els.varianceError.textContent = '';
      els.settingsSuccess.textContent = '';
    }

    function clearEventErrors() {
      els.eventTypeError.textContent = '';
      els.messageError.textContent = '';
      els.eventSuccess.textContent = '';
    }

    els.settingsForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearSettingsErrors();

      const interval = Number(els.interval.value);
      const baseline = Number(els.baseline.value);
      const variance = Number(els.variance.value);

      let valid = true;

      if (!interval || interval < 100) {
        els.intervalError.textContent = 'Interval must be at least 100 ms.';
        valid = false;
      }

      if (baseline < 0 || Number.isNaN(baseline)) {
        els.baselineError.textContent = 'Baseline must be 0 or greater.';
        valid = false;
      }

      if (!variance || variance < 1) {
        els.varianceError.textContent = 'Variance must be at least 1.';
        valid = false;
      }

      if (!valid) return;

      state.interval = interval;
      state.baseline = baseline;
      state.variance = variance;

      els.settingsSuccess.textContent = 'Settings applied successfully.';
      addFeedItem('Info', `Simulation updated: interval=${interval}ms, baseline=${baseline}, variance=${variance}`);

      if (state.running) {
        startStream();
      }
      drawChart();
    });

    els.eventForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearEventErrors();

      const eventType = els.eventType.value.trim();
      const message = els.message.value.trim();

      let valid = true;

      if (!eventType) {
        els.eventTypeError.textContent = 'Please select an event type.';
        valid = false;
      }

      if (!message || message.length < 3) {
        els.messageError.textContent = 'Message must be at least 3 characters.';
        valid = false;
      }

      if (!valid) return;

      addFeedItem(eventType, message);
      els.eventSuccess.textContent = 'Event submitted successfully.';
      els.eventForm.reset();
    });

    els.startBtn.addEventListener('click', () => {
      startStream();
      addFeedItem('Info', 'Live stream started');
    });

    els.stopBtn.addEventListener('click', () => {
      stopStream();
      addFeedItem('Info', 'Live stream stopped');
    });

    els.resetBtn.addEventListener('click', () => {
      resetDashboard();
    });

    window.addEventListener('resize', resizeCanvas);

    function init() {
      resizeCanvas();
      for (let i = 0; i < 12; i++) {
        addDataPoint(randomValue());
      }
      addFeedItem('Info', 'Dashboard initialized');
      startStream();
    }

    init();
  </script>
</body>
</html>
