<body>
  <div class="container">
    <div class="header">
      <h1>Interactive Real-Time Dashboard</h1>
      <div class="status">
        <span class="status-dot"></span>
        <span id="connectionStatus">Live data stream active</span>
      </div>
    </div>

    <div class="grid">
      <div class="card metric-card">
        <div class="metric-title">Active Users</div>
        <div class="metric-value" id="activeUsers">128</div>
        <div class="metric-change positive" id="usersChange">+4.2% from last minute</div>
      </div>

      <div class="card metric-card">
        <div class="metric-title">Transactions</div>
        <div class="metric-value" id="transactions">54</div>
        <div class="metric-change positive" id="transactionsChange">+2.1% from last minute</div>
      </div>

      <div class="card metric-card">
        <div class="metric-title">Error Rate</div>
        <div class="metric-value" id="errorRate">1.2%</div>
        <div class="metric-change negative" id="errorRateChange">+0.3% from last minute</div>
      </div>

      <div class="card metric-card">
        <div class="metric-title">System Load</div>
        <div class="metric-value" id="systemLoad">67%</div>
        <div class="metric-change positive" id="systemLoadChange">Stable</div>
      </div>

      <div class="card chart-card">
        <h2>Live Throughput</h2>
        <canvas id="realtimeChart"></canvas>
      </div>

      <div class="card form-card">
        <h2>Submit Event</h2>
        <form id="eventForm">
          <label>
            Event Name
            <input type="text" id="eventName" name="eventName" placeholder="Enter event name" required />
          </label>

          <label>
            Category
            <select id="eventCategory" name="eventCategory" required>
              <option value="">Select category</option>
              <option value="Info">Info</option>
              <option value="Warning">Warning</option>
              <option value="Error">Error</option>
              <option value="Transaction">Transaction</option>
            </select>
          </label>

          <label>
            Value
            <input type="number" id="eventValue" name="eventValue" placeholder="Enter numeric value" required />
          </label>

          <label>
            Notes
            <textarea id="eventNotes" name="eventNotes" rows="4" placeholder="Optional notes"></textarea>
          </label>

          <button type="submit">Add Event</button>
          <div id="formMessage" class="message"></div>
        </form>
      </div>

      <div class="card log-card">
        <h2>Activity Log</h2>
        <ul id="activityLog" class="log-list"></ul>
      </div>
    </div>
  </div>

  <script>
    const maxDataPoints = 20;

    const labels = [];
    const throughputData = [];

    function getTimeLabel() {
      return new Date().toLocaleTimeString();
    }

    for (let i = 0; i < 10; i++) {
      labels.push(getTimeLabel());
      throughputData.push(Math.floor(Math.random() * 100) + 20);
    }

    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Requests / sec',
          data: throughputData,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.1)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.1)' },
            beginAtZero: true
          }
        }
      }
    });

    const activeUsersEl = document.getElementById('activeUsers');
    const transactionsEl = document.getElementById('transactions');
    const errorRateEl = document.getElementById('errorRate');
    const systemLoadEl = document.getElementById('systemLoad');
    const activityLogEl = document.getElementById('activityLog');
    const formMessageEl = document.getElementById('formMessage');

    let activeUsers = 128;
    let transactions = 54;
    let errorRate = 1.2;
    let systemLoad = 67;

    function addLog(message, category = 'Info') {
      const li = document.createElement('li');
      li.className = 'log-item';

      const text = document.createElement('div');
      text.innerHTML = `<strong>[${category}]</strong> ${message}`;

      const time = document.createElement('div');
      time.className = 'log-time';
      time.textContent = new Date().toLocaleString();

      li.appendChild(text);
      li.appendChild(time);

      activityLogEl.prepend(li);

      while (activityLogEl.children.length > 12) {
        activityLogEl.removeChild(activityLogEl.lastChild);
      }
    }

    function updateMetrics() {
      activeUsers += Math.floor(Math.random() * 11) - 5;
      transactions += Math.floor(Math.random() * 7) - 2;
      errorRate = Math.max(0, +(errorRate + (Math.random() * 0.4 - 0.2)).toFixed(1));
      systemLoad = Math.min(100, Math.max(0, systemLoad + Math.floor(Math.random() * 9) - 4));

      activeUsersEl.textContent = activeUsers;
      transactionsEl.textContent = transactions;
      errorRateEl.textContent = `${errorRate}%`;
      systemLoadEl.textContent = `${systemLoad}%`;
    }

    function updateChart() {
      const newValue = Math.floor(Math.random() * 100) + 20;
      realtimeChart.data.labels.push(getTimeLabel());
      realtimeChart.data.datasets[0].data.push(newValue);

      if (realtimeChart.data.labels.length > maxDataPoints) {
        realtimeChart.data.labels.shift();
        realtimeChart.data.datasets[0].data.shift();
      }

      realtimeChart.update();
    }

    function simulateRealtimeUpdates() {
      updateMetrics();
      updateChart();

      const events = [
        'Background sync completed',
        'New user session started',
        'Transaction batch processed',
        'Cache refreshed',
        'API latency spike detected',
        'Worker heartbeat received'
      ];

      const categories = ['Info', 'Transaction', 'Warning'];
      const randomEvent = events[Math.floor(Math.random() * events.length)];
      const randomCategory = categories[Math.floor(Math.random() * categories.length)];

      addLog(randomEvent, randomCategory);
    }

    setInterval(simulateRealtimeUpdates, 2000);

    document.getElementById('eventForm').addEventListener('submit', function (e) {
      e.preventDefault();

      const eventName = document.getElementById('eventName').value.trim();
      const eventCategory = document.getElementById('eventCategory').value;
      const eventValue = document.getElementById('eventValue').value.trim();
      const eventNotes = document.getElementById('eventNotes').value.trim();

      if (!eventName || !eventCategory || !eventValue) {
        formMessageEl.textContent = 'Please fill in all required fields.';
        formMessageEl.className = 'message error';
        return;
      }

      const numericValue = Number(eventValue);
      if (Number.isNaN(numericValue)) {
        formMessageEl.textContent = 'Value must be a valid number.';
        formMessageEl.className = 'message error';
        return;
      }

      addLog(
        `${eventName} submitted with value ${numericValue}${eventNotes ? ` — ${eventNotes}` : ''}`,
        eventCategory
      );

      if (eventCategory === 'Transaction') {
        transactions += 1;
        transactionsEl.textContent = transactions;
      }

      if (eventCategory === 'Error') {
        errorRate = +(errorRate + 0.2).toFixed(1);
        errorRateEl.textContent = `${errorRate}%`;
      }

      throughputData.push(numericValue);
      labels.push(getTimeLabel());

      if (throughputData.length > maxDataPoints) {
        throughputData.shift();
        labels.shift();
      }

      realtimeChart.update();

      formMessageEl.textContent = 'Event submitted successfully.';
      formMessageEl.className = 'message success';

      e.target.reset();
    });

    addLog('Dashboard initialized', 'Info');
  </script>
</body>
</html>
```

