## `app.js`

```javascript
const settingsForm = document.getElementById("settingsForm");
const manualEntryForm = document.getElementById("manualEntryForm");
const toggleStreamBtn = document.getElementById("toggleStream");

const metricNameInput = document.getElementById("metricName");
const updateIntervalInput = document.getElementById("updateInterval");
const maxPointsInput = document.getElementById("maxPoints");
const thresholdInput = document.getElementById("threshold");
const manualValueInput = document.getElementById("manualValue");

const chartTitle = document.getElementById("chartTitle");
const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const thresholdValueEl = document.getElementById("thresholdValue");
const streamStatusEl = document.getElementById("streamStatus");
const alertBadge = document.getElementById("alertBadge");
const eventLog = document.getElementById("eventLog");

let config = {
  metricName: "CPU Usage",
  updateInterval: 1000,
  maxPoints: 20,
  threshold: 75
};

let isStreaming = true;
let intervalId = null;
let dataPoints = [];
let labels = [];

metricNameInput.value = config.metricName;
updateIntervalInput.value = config.updateInterval;
maxPointsInput.value = config.maxPoints;
thresholdInput.value = config.threshold;
chartTitle.textContent = config.metricName;

const ctx = document.getElementById("realtimeChart").getContext("2d");

const realtimeChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: config.metricName,
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.2)",
        fill: true,
        tension: 0.3,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      y: {
        min: 0,
        max: 100
      }
    },
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    }
  }
});

function generateValue() {
  return Math.floor(Math.random() * 101);
}

function getTimestamp() {
  return new Date().toLocaleTimeString();
}

function addEvent(message) {
  const item = document.createElement("div");
  item.className = "event-item";
  item.textContent = `[${getTimestamp()}] ${message}`;
  eventLog.prepend(item);

  while (eventLog.children.length > 20) {
    eventLog.removeChild(eventLog.lastChild);
  }
}

function updateStats() {
  const current = dataPoints[dataPoints.length - 1] ?? 0;
  const average =
    dataPoints.length > 0
      ? (dataPoints.reduce((sum, val) => sum + val, 0) / dataPoints.length).toFixed(1)
      : 0;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  thresholdValueEl.textContent = config.threshold;

  if (current >= config.threshold) {
    alertBadge.textContent = "Alert";
    alertBadge.className = "badge danger";
  } else if (current >= config.threshold * 0.85) {
    alertBadge.textContent = "Warning";
    alertBadge.className = "badge warning";
  } else {
    alertBadge.textContent = "Normal";
    alertBadge.className = "badge";
  }
}

function pushDataPoint(value, source = "auto") {
  const timestamp = getTimestamp();

  labels.push(timestamp);
  dataPoints.push(value);

  if (dataPoints.length > config.maxPoints) {
    dataPoints.shift();
    labels.shift();
  }

  realtimeChart.data.labels = labels;
  realtimeChart.data.datasets[0].data = dataPoints;
  realtimeChart.data.datasets[0].label = config.metricName;
  realtimeChart.update();

  updateStats();

  if (value >= config.threshold) {
    addEvent(`${source} value ${value} exceeded threshold ${config.threshold}`);
  } else {
    addEvent(`${source} value ${value} recorded`);
  }
}

function startStream() {
  clearInterval(intervalId);
  intervalId = setInterval(() => {
    if (!isStreaming) return;
    pushDataPoint(generateValue(), "auto");
  }, config.updateInterval);
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const metricName = metricNameInput.value.trim();
  const updateInterval = Number(updateIntervalInput.value);
  const maxPoints = Number(maxPointsInput.value);
  const threshold = Number(thresholdInput.value);

  if (!metricName || updateInterval < 500 || maxPoints < 10 || threshold < 0 || threshold > 100) {
    addEvent("Invalid settings submitted");
    return;
  }

  config = {
    metricName,
    updateInterval,
    maxPoints,
    threshold
  };

  chartTitle.textContent = config.metricName;
  realtimeChart.data.datasets[0].label = config.metricName;
  realtimeChart.update();

  addEvent(`Settings updated for ${config.metricName}`);
  updateStats();
  startStream();
});

manualEntryForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const value = Number(manualValueInput.value);

  if (Number.isNaN(value) || value < 0 || value > 100) {
    addEvent("Invalid manual value");
    return;
  }

  pushDataPoint(value, "manual");
  manualValueInput.value = "";
});

toggleStreamBtn.addEventListener("click", () => {
  isStreaming = !isStreaming;
  streamStatusEl.textContent = isStreaming ? "Running" : "Paused";
  toggleStreamBtn.textContent = isStreaming ? "Pause" : "Resume";
  addEvent(`Stream ${isStreaming ? "resumed" : "paused"}`);
});

updateStats();
startStream();
```

