      padding: 10px 14px;
      border-radius: 999px;
      color: var(--muted);
    }

    .status-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--accent-2);
      box-shadow: 0 0 10px var(--accent-2);
    }

    .grid {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 20px;
    }

    .card {
      background: rgba(17, 24, 39, 0.9);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 20px;
    }

    .card h2 {
      margin-top: 0;
      font-size: 1.1rem;
      margin-bottom: 16px;
    }

    .span-8 {
      grid-column: span 8;
    }

    .span-4 {
      grid-column: span 4;
    }

    .span-12 {
      grid-column: span 12;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }

    .stat {
      background: var(--panel-light);
      border: 1px solid var(--border);
      border-radius: 12px;
