<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <div style="color: var(--muted); margin-top: 6px;">
          Monitor live metrics and submit events through the control form.
        </div>
      </div>
      <div class="status">
        <span class="status-dot"></span>
        <span id="connectionStatus">Live updates active</span>
      </div>
    </div>

    <div class="grid">
      <section class="card span-8">
        <h2>Live Metric Trend</h2>
        <canvas id="realtimeChart"></canvas>
      </section>

      <section class="card span-4">
        <h2>Current Stats</h2>
        <div class="stats">
          <div class="stat">
            <div class="stat-label">Current Value</div>
            <div class="stat-value" id="currentValue">0</div>
          </div>
          <div class="stat">
            <div class="stat-label">Average</div>
            <div class="stat-value" id="averageValue">0</div>
          </div>
          <div class="stat">
            <div class="stat-label">Events Logged</div>
            <div class="stat-value" id="eventCount">0</div>
          </div>
        </div>
      </section>

      <section class="card span-4">
        <h2>Submit Event</h2>
        <form id="eventForm">
          <div class="field">
            <label for="eventType">Event Type</label>
            <select id="eventType" name="eventType" required>
              <option value="">Select an event</option>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="alert">Alert</option>
            </select>
          </div>

          <div class="field">
            <label for="metricValue">Metric Value</label>
            <input
              type="number"
              id="metricValue"
              name="metricValue"
              placeholder="Enter a numeric value"
              required
            />
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea
              id="notes"
              name="notes"
              rows="4"
              placeholder="Optional notes..."
            ></textarea>
          </div>

          <div class="actions">
            <button type="submit">Submit</button>
            <button type="button" class="secondary" id="resetFormBtn">Reset</button>
          </div>

          <div id="formMessage" class="message"></div>
        </form>
      </section>

      <section class="card span-8">
        <h2>Event Log</h2>
        <ul id="eventLog" class="log-list"></ul>
      </section>
    </div>
  </div>

  <script>
    const chartLabels = [];
    const chartData = [];
    const maxPoints = 20;
    const submittedEvents = [];

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const eventCountEl = document.getElementById('eventCount');
    const eventLogEl = document.getElementById('eventLog');
    const formMessageEl = document.getElementById('formMessage');
    const eventForm = document.getElementById('eventForm');
    const resetFormBtn = document.getElementById('resetFormBtn');

    const ctx = document.getElementById('realtimeChart').getContext('2d');

    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: chartLabels,
        datasets: [
          {
            label: 'Metric',
            data: chartData,
            borderColor: '#38bdf8',
            backgroundColor: 'rgba(56, 189, 248, 0.2)',
            fill: true,
            tension: 0.35,
            pointRadius: 3,
            pointBackgroundColor: '#38bdf8'
          }
        ]
      },
      options: {
        responsive: true,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' },
            beginAtZero: true
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function addChartPoint(value, label = formatTime()) {
      chartLabels.push(label);
      chartData.push(value);

      if (chartLabels.length > maxPoints) {
        chartLabels.shift();
        chartData.shift();
      }

      realtimeChart.update();
      updateStats();
    }

    function updateStats() {
      const latest = chartData[chartData.length - 1] ?? 0;
      const avg =
        chartData.length > 0
          ? chartData.reduce((sum, val) => sum + val, 0) / chartData.length
          : 0;

      currentValueEl.textContent = Number(latest).toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      eventCountEl.textContent = submittedEvents.length;
    }

    function addLogEntry({ type, value, notes, time }) {
      const li = document.createElement('li');
      li.className = 'log-item';
      li.innerHTML = `
        <div class="log-time">${time}</div>
        <div><strong>${type.toUpperCase()}</strong> — Value: ${value}</div>
        <div>${notes ? notes : '<em>No notes provided</em>'}</div>
      `;
      eventLogEl.prepend(li);
    }

    function showMessage(text, type = 'success') {
      formMessageEl.textContent = text;
      formMessageEl.className = `message ${type}`;
    }

    function clearMessage() {
      formMessageEl.textContent = '';
      formMessageEl.className = 'message';
    }

    function simulateRealtimeData() {
      const nextValue = Math.random() * 100;
      addChartPoint(nextValue);
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearMessage();

      const eventType = document.getElementById('eventType').value;
      const metricValue = parseFloat(document.getElementById('metricValue').value);
      const notes = document.getElementById('notes').value.trim();

      if (!eventType || Number.isNaN(metricValue)) {
        showMessage('Please complete all required fields correctly.', 'error');
        return;
      }

      const event = {
        type: eventType,
        value: metricValue,
        notes,
        time: formatTime()
      };

      submittedEvents.push(event);
      addChartPoint(metricValue, event.time);
      addLogEntry(event);
      updateStats();

      showMessage('Event submitted successfully.', 'success');
      eventForm.reset();
    });

    resetFormBtn.addEventListener('click', () => {
      eventForm.reset();
      clearMessage();
    });

    for (let i = 0; i < 8; i++) {
      addChartPoint(Math.random() * 100, formatTime(new Date(Date.now() - (8 - i) * 1000)));
    }

    setInterval(simulateRealtimeData, 2000);
  </script>
</body>
</html>
