<body>
  <div class="container">
    <div class="header">
      <h1>Interactive Realtime Dashboard</h1>
      <div class="status" id="connectionStatus">Live updates active</div>
    </div>

    <div class="grid">
      <div class="metrics">
        <div class="metric">
          <div class="metric-label">Current Value</div>
          <div class="metric-value" id="currentValue">0</div>
        </div>
        <div class="metric">
          <div class="metric-label">Average</div>
          <div class="metric-value" id="averageValue">0</div>
        </div>
        <div class="metric">
          <div class="metric-label">Peak</div>
          <div class="metric-value" id="peakValue">0</div>
        </div>
        <div class="metric">
          <div class="metric-label">Events Submitted</div>
          <div class="metric-value" id="eventCount">0</div>
        </div>
      </div>

      <div class="card chart-card">
        <h2>Realtime Data Stream</h2>
        <canvas id="realtimeChart"></canvas>
      </div>

      <div class="card form-card">
        <h2>Submit Event</h2>
        <form id="eventForm">
          <label>
            Event Name
            <input type="text" id="eventName" name="eventName" placeholder="e.g. Sensor Alert" required />
          </label>

          <label>
            Category
            <select id="category" name="category" required>
              <option value="">Select category</option>
              <option value="Info">Info</option>
              <option value="Warning">Warning</option>
              <option value="Critical">Critical</option>
            </select>
          </label>

          <label>
            Value
            <input type="number" id="eventValue" name="eventValue" placeholder="e.g. 42" required />
          </label>

          <label>
            Notes
            <textarea id="notes" name="notes" rows="4" placeholder="Optional notes"></textarea>
          </label>

          <div class="form-actions">
            <button type="submit">Submit</button>
            <button type="reset" class="secondary-btn">Reset</button>
          </div>

          <div id="formMessage" class="message"></div>
        </form>
      </div>

      <div class="card log-card">
        <h2>Event Log</h2>
        <ul id="eventLog" class="log-list"></ul>
      </div>
    </div>
  </div>

  <script>
    const maxPoints = 20;
    const dataPoints = [];
    let submittedEvents = 0;
    let peakValue = 0;

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const formMessageEl = document.getElementById('formMessage');
    const eventLogEl = document.getElementById('eventLog');

    const ctx = document.getElementById('realtimeChart').getContext('2d');

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Live Metric',
          data: [],
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function getTimeLabel() {
      return new Date().toLocaleTimeString();
    }

    function updateMetrics() {
      const current = dataPoints[dataPoints.length - 1] || 0;
      const avg = dataPoints.length
        ? dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length
        : 0;

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peakValue.toFixed(1);
      eventCountEl.textContent = submittedEvents;
    }

    function pushDataPoint(value) {
      const time = getTimeLabel();

      dataPoints.push(value);
      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
      }

      if (value > peakValue) {
        peakValue = value;
      }

      chart.data.labels.push(time);
      chart.data.datasets[0].data.push(value);

      if (chart.data.labels.length > maxPoints) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
      updateMetrics();
    }

    function simulateRealtimeData() {
      const nextValue = Math.random() * 100;
      pushDataPoint(nextValue);
    }

    function addLogEntry(text, category = 'Info') {
      const li = document.createElement('li');
      li.className = 'log-item';
      li.innerHTML = `
        <span class="log-time">${getTimeLabel()} • ${category}</span>
        <div>${text}</div>
      `;
      eventLogEl.prepend(li);

      const maxLogs = 25;
      while (eventLogEl.children.length > maxLogs) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    document.getElementById('eventForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const eventName = document.getElementById('eventName').value.trim();
      const category = document.getElementById('category').value;
      const eventValue = parseFloat(document.getElementById('eventValue').value);
      const notes = document.getElementById('notes').value.trim();

      if (!eventName || !category || Number.isNaN(eventValue)) {
        formMessageEl.textContent = 'Please complete all required fields correctly.';
        formMessageEl.className = 'message error';
        return;
      }

      submittedEvents += 1;
      pushDataPoint(eventValue);

      addLogEntry(
        `<strong>${eventName}</strong> submitted with value <strong>${eventValue}</strong>${notes ? ` — ${notes}` : ''}`,
        category
      );

      formMessageEl.textContent = 'Event submitted successfully.';
      formMessageEl.className = 'message success';

      e.target.reset();
    });

    document.getElementById('eventForm').addEventListener('reset', () => {
      formMessageEl.textContent = '';
      formMessageEl.className = 'message';
    });

    for (let i = 0; i < 8; i++) {
      simulateRealtimeData();
    }

    setInterval(simulateRealtimeData, 2000);
  </script>
</body>
</html>
```

