## `app.js`

```javascript
const MAX_POINTS = 20;

const state = {
  chart: null,
  intervalId: null,
  dataPoints: [],
  labels: [],
  events: [],
  peak: 0,
  running: false
};

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const peakValueEl = document.getElementById("peakValue");
const totalEventsEl = document.getElementById("totalEvents");
const connectionStatusEl = document.getElementById("connectionStatus");
const eventsTableBodyEl = document.getElementById("eventsTableBody");

const startBtn = document.getElementById("startBtn");
const stopBtn = document.getElementById("stopBtn");
const resetBtn = document.getElementById("resetBtn");
const clearFormBtn = document.getElementById("clearFormBtn");
const eventForm = document.getElementById("eventForm");

function formatTime(date = new Date()) {
  return date.toLocaleTimeString();
}

function randomMetric() {
  return Math.floor(40 + Math.random() * 60);
}

function calculateAverage(values) {
  if (!values.length) return 0;
  const total = values.reduce((sum, value) => sum + value, 0);
  return (total / values.length).toFixed(1);
}

function updateKpis() {
  const latest = state.dataPoints[state.dataPoints.length - 1] || 0;
  currentValueEl.textContent = latest;
  averageValueEl.textContent = calculateAverage(state.dataPoints);
  peakValueEl.textContent = state.peak;
  totalEventsEl.textContent = state.events.length;
}

function updateChart() {
  const nextValue = randomMetric();
  const nextLabel = formatTime();

  state.dataPoints.push(nextValue);
  state.labels.push(nextLabel);

  if (state.dataPoints.length > MAX_POINTS) {
    state.dataPoints.shift();
    state.labels.shift();
  }

  if (nextValue > state.peak) {
    state.peak = nextValue;
  }

  state.chart.data.labels = state.labels;
  state.chart.data.datasets[0].data = state.dataPoints;
  state.chart.update();

  updateKpis();
}

function setRunningStatus(isRunning) {
  state.running = isRunning;
  connectionStatusEl.textContent = isRunning ? "Live" : "Paused";
  connectionStatusEl.classList.toggle("online", isRunning);
  connectionStatusEl.classList.toggle("offline", !isRunning);
}

function startStream() {
  if (state.intervalId) return;
  updateChart();
  state.intervalId = setInterval(updateChart, 1000);
  setRunningStatus(true);
}

function stopStream() {
  if (!state.intervalId) return;
  clearInterval(state.intervalId);
  state.intervalId = null;
  setRunningStatus(false);
}

function resetDashboard() {
  stopStream();
  state.dataPoints = [];
  state.labels = [];
  state.peak = 0;
  state.chart.data.labels = [];
  state.chart.data.datasets[0].data = [];
  state.chart.update();
  updateKpis();
}

function getBadgeClass(type) {
  switch (type) {
    case "Warning":
      return "warning";
    case "Error":
      return "error";
    default:
      return "info";
  }
}

function renderEvents() {
  if (!state.events.length) {
    eventsTableBodyEl.innerHTML = `
      <tr class="empty-row">
        <td colspan="4">No events yet</td>
      </tr>
    `;
    return;
  }

  eventsTableBodyEl.innerHTML = state.events
    .slice()
    .reverse()
    .map((event) => {
      return `
        <tr>
          <td>${event.time}</td>
          <td><span class="badge ${getBadgeClass(event.type).toLowerCase()}">${event.type}</span></td>
          <td>${event.source}</td>
          <td>${event.message}</td>
        </tr>
      `;
    })
    .join("");

  updateKpis();
}

function handleFormSubmit(event) {
  event.preventDefault();

  const formData = new FormData(eventForm);
  const eventType = formData.get("eventType")?.trim();
  const eventSource = formData.get("eventSource")?.trim();
  const eventMessage = formData.get("eventMessage")?.trim();

  if (!eventType || !eventSource || !eventMessage) {
    alert("Please complete all fields.");
    return;
  }

  state.events.push({
    time: formatTime(),
    type: eventType,
    source: eventSource,
    message: eventMessage
  });

  renderEvents();
  eventForm.reset();
}

function clearForm() {
  eventForm.reset();
}

function createChart() {
  const ctx = document.getElementById("liveChart").getContext("2d");

  state.chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: state.labels,
      datasets: [
        {
          label: "Metric",
          data: state.dataPoints,
          borderColor: "#3b82f6",
          backgroundColor: "rgba(59, 130, 246, 0.2)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointHoverRadius: 5
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      plugins: {
        legend: {
          labels: {
            color: "#e5e7eb"
          }
        }
      },
      scales: {
        x: {
          ticks: {
            color: "#94a3b8"
          },
          grid: {
            color: "rgba(148, 163, 184, 0.15)"
          }
        },
        y: {
          beginAtZero: true,
          ticks: {
            color: "#94a3b8"
          },
          grid: {
            color: "rgba(148, 163, 184, 0.15)"
          }
        }
      }
    }
  });
}

function init() {
  createChart();
  updateKpis();
  renderEvents();

  startBtn.addEventListener("click", startStream);
  stopBtn.addEventListener("click", stopStream);
  resetBtn.addEventListener("click", resetDashboard);
  clearFormBtn.addEventListener("click", clearForm);
  eventForm.addEventListener("submit", handleFormSubmit);

  startStream();
}

init();
```

