  <script>
    const state = {
      records: [],
      metrics: {
        activeUsers: 120,
        transactions: 42,
        errorRate: 0.8
      },
      chartPoints: 20
    };

    const els = {
      activeUsers: document.getElementById('activeUsers'),
      activeUsersDelta: document.getElementById('activeUsersDelta'),
      transactions: document.getElementById('transactions'),
      transactionsDelta: document.getElementById('transactionsDelta'),
      errorRate: document.getElementById('errorRate'),
      errorRateDelta: document.getElementById('errorRateDelta'),
      recordCount: document.getElementById('recordCount'),
      activityFeed: document.getElementById('activityFeed'),
      recordForm: document.getElementById('recordForm'),
      formMessage: document.getElementById('formMessage'),
      recordsTableBody: document.getElementById('recordsTableBody'),
      nameError: document.getElementById('nameError'),
      emailError: document.getElementById('emailError'),
      priorityError: document.getElementById('priorityError'),
      messageError: document.getElementById('messageError')
    };

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(value, min, max) {
      return Math.min(Math.max(value, min), max);
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }

    function addFeedItem(text) {
      const item = document.createElement('div');
      item.className = 'feed-item';
      item.innerHTML = `
        <div>${text}</div>
        <div class="time">${formatTime()}</div>
      `;
      els.activityFeed.prepend(item);

      while (els.activityFeed.children.length > 12) {
        els.activityFeed.removeChild(els.activityFeed.lastChild);
      }
    }

    function updateKPIs(prevMetrics, nextMetrics) {
      const activeDelta = (((nextMetrics.activeUsers - prevMetrics.activeUsers) / prevMetrics.activeUsers) * 100 || 0).toFixed(1);
      const txDelta = (((nextMetrics.transactions - prevMetrics.transactions) / prevMetrics.transactions) * 100 || 0).toFixed(1);
      const errDelta = (nextMetrics.errorRate - prevMetrics.errorRate).toFixed(2);

      els.activeUsers.textContent = Math.round(nextMetrics.activeUsers);
      els.activeUsersDelta.textContent = `${activeDelta >= 0 ? '+' : ''}${activeDelta}% vs last tick`;

      els.transactions.textContent = Math.round(nextMetrics.transactions);
      els.transactionsDelta.textContent = `${txDelta >= 0 ? '+' : ''}${txDelta}% vs last tick`;

      els.errorRate.textContent = `${nextMetrics.errorRate.toFixed(2)}%`;
      els.errorRateDelta.textContent = `${errDelta >= 0 ? '+' : ''}${errDelta}% vs last tick`;
      els.errorRateDelta.style.color = nextMetrics.errorRate > 1.5 ? '#fca5a5' : '#86efac';

      els.recordCount.textContent = state.records.length;
    }

    const chartCtx = document.getElementById('realtimeChart').getContext('2d');
    const labels = Array.from({ length: state.chartPoints }, (_, i) => `${i + 1}`);
    const initialData = Array.from({ length: state.chartPoints }, () => Math.round(randomBetween(30, 70)));

    const realtimeChart = new Chart(chartCtx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Requests/sec',
          data: initialData,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.18)',
          fill: true,
          tension: 0.35,
          pointRadius: 2,
          pointBackgroundColor: '#7dd3fc'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          }
        }
      }
    });

    function tickRealtimeData() {
      const prev = { ...state.metrics };

      state.metrics.activeUsers = clamp(state.metrics.activeUsers + randomBetween(-8, 10), 80, 220);
      state.metrics.transactions = clamp(state.metrics.transactions + randomBetween(-5, 6), 20, 90);
      state.metrics.errorRate = clamp(state.metrics.errorRate + randomBetween(-0.15, 0.18), 0.1, 3.5);

      updateKPIs(prev, state.metrics);

      const nextValue = Math.round(
        state.metrics.transactions + randomBetween(0, 20) + state.metrics.activeUsers * 0.08
      );

      realtimeChart.data.labels.push(formatTime());
      realtimeChart.data.labels.shift();
      realtimeChart.data.datasets[0].data.push(nextValue);
      realtimeChart.data.datasets[0].data.shift();
      realtimeChart.update();

      const feedMessages = [
        `Processed ${Math.round(state.metrics.transactions)} transactions in the last minute`,
        `Active users changed to ${Math.round(state.metrics.activeUsers)}`,
        `Error rate is now ${state.metrics.errorRate.toFixed(2)}%`,
        `Throughput sample recorded at ${nextValue} req/sec`
      ];

      if (Math.random() > 0.45) {
        addFeedItem(feedMessages[Math.floor(Math.random() * feedMessages.length)]);
      }
    }

    function clearErrors() {
      els.nameError.textContent = '';
      els.emailError.textContent = '';
      els.priorityError.textContent = '';
      els.messageError.textContent = '';
      els.formMessage.textContent = '';
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.name.trim()) {
        els.nameError.textContent = 'Name is required.';
        valid = false;
      }

      if (!data.email.trim()) {
        els.emailError.textContent = 'Email is required.';
        valid = false;
      } else {
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(data.email)) {
          els.emailError.textContent = 'Enter a valid email address.';
          valid = false;
        }
      }

      if (!data.priority) {
        els.priorityError.textContent = 'Priority is required.';
        valid = false;
      }

      if (!data.message.trim()) {
        els.messageError.textContent = 'Message is required.';
        valid = false;
      } else if (data.message.trim().length < 10) {
        els.messageError.textContent = 'Message must be at least 10 characters.';
        valid = false;
      }

      return valid;
    }

    function renderRecords() {
      els.recordsTableBody.innerHTML = '';

      if (state.records.length === 0) {
        const row = document.createElement('tr');
        row.innerHTML = `<td colspan="5" style="color:#94a3b8;">No records submitted yet.</td>`;
        els.recordsTableBody.appendChild(row);
        return;
      }

      state.records.forEach(record => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${escapeHtml(record.name)}</td>
          <td>${escapeHtml(record.email)}</td>
          <td><span class="badge ${record.priority}">${record.priority}</span></td>
          <td>${escapeHtml(record.message)}</td>
          <td>${record.time}</td>
        `;
        els.recordsTableBody.appendChild(row);
      });
    }

    function escapeHtml(str) {
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    els.recordForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(els.recordForm);
      const data = {
        name: formData.get('name') || '',
        email: formData.get('email') || '',
        priority: formData.get('priority') || '',
        message: formData.get('message') || ''
      };

      if (!validateForm(data)) return;

      const record = {
        ...data,
        time: formatTime()
      };

      state.records.unshift(record);
      renderRecords();
      els.recordForm.reset();
      els.formMessage.textContent = 'Record submitted successfully.';
      els.recordCount.textContent = state.records.length;

      addFeedItem(`New ${record.priority} priority record submitted by ${record.name}`);
    });

    els.recordForm.addEventListener('reset', () => {
      setTimeout(() => {
        clearErrors();
      }, 0);
    });

    updateKPIs(state.metrics, state.metrics);
    renderRecords();
    addFeedItem('Dashboard initialized');
    addFeedItem('Awaiting live updates');

    setInterval(tickRealtimeData, 2000);
  </script>
</body>
</html>
