  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <div class="label">Latest Value</div>
        <div class="value" id="latestValue">0</div>
      </div>
      <div class="stat">
        <div class="label">Average</div>
        <div class="value" id="avgValue">0</div>
      </div>
      <div class="stat">
        <div class="label">Events Logged</div>
        <div class="value" id="eventCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="liveChart" height="120"></canvas>
        <div class="status" id="streamStatus">Streaming every 1 second</div>
      </div>

      <div class="card">
        <h2>Controls & Form</h2>
        <form id="eventForm">
          <label>
            Event Name
            <input type="text" id="eventName" placeholder="e.g. Manual adjustment" required />
          </label>

          <label>
            Value
            <input type="number" id="eventValue" placeholder="e.g. 42" required />
          </label>

          <label>
            Category
            <select id="eventCategory">
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="critical">Critical</option>
            </select>
          </label>

          <div class="row">
            <button type="submit">Add Event</button>
            <button type="button" class="secondary" id="toggleStream">Pause Stream</button>
          </div>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const maxPoints = 20;
    let streamRunning = true;
    let counter = 0;
    let values = [];

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const eventCountEl = document.getElementById('eventCount');
    const eventLogEl = document.getElementById('eventLog');
    const streamStatusEl = document.getElementById('streamStatus');
    const toggleStreamBtn = document.getElementById('toggleStream');
    const eventForm = document.getElementById('eventForm');

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Sensor Value',
          data: [],
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        animation: false,
        responsive: true,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        }
      }
    });

    function updateStats(newValue) {
      latestValueEl.textContent = newValue.toFixed(1);
      const avg = values.reduce((sum, v) => sum + v, 0) / values.length;
      avgValueEl.textContent = avg.toFixed(1);
    }

    function addLog(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLogEl.prepend(item);
      eventCountEl.textContent = eventLogEl.children.length;
    }

    function pushDataPoint(value, source = 'stream') {
      counter++;
      const label = new Date().toLocaleTimeString();

      chart.data.labels.push(label);
      chart.data.datasets[0].data.push(value);

      values.push(value);

      if (chart.data.labels.length > maxPoints) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      if (values.length > maxPoints) {
        values.shift();
      }

      chart.update();
      updateStats(value);

      if (source === 'stream') {
        addLog(`Auto data received: ${value.toFixed(1)}`);
      }
    }

    function generateRandomValue() {
      return 20 + Math.random() * 80;
    }

    const interval = setInterval(() => {
      if (!streamRunning) return;
      pushDataPoint(generateRandomValue(), 'stream');
    }, 1000);

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('eventName').value.trim();
      const value = parseFloat(document.getElementById('eventValue').value);
      const category = document.getElementById('eventCategory').value;

      if (!name || Number.isNaN(value)) {
        alert('Please enter a valid name and numeric value.');
        return;
      }

      pushDataPoint(value, 'manual');
      addLog(`${category.toUpperCase()}: ${name} (${value})`);

      eventForm.reset();
    });

    toggleStreamBtn.addEventListener('click', () => {
      streamRunning = !streamRunning;
      toggleStreamBtn.textContent = streamRunning ? 'Pause Stream' : 'Resume Stream';
      streamStatusEl.textContent = streamRunning
        ? 'Streaming every 1 second'
        : 'Stream paused';
    });

    // Seed initial data
    for (let i = 0; i < 5; i++) {
      pushDataPoint(generateRandomValue(), 'manual');
    }
  </script>
</body>
</html>
```

## What this does

- Shows a live-updating line chart
- Simulates real-time incoming data every second
- Displays summary stats:
  - latest value
  - average
  - event count
- Includes a form to manually add events/data points
- Lets the user pause/resume the live stream
- Logs activity in a simple event feed

