          <button class="danger" id="stopBtn" type="button">Stop</button>
          <button class="secondary" id="clearBtn" type="button">Clear</button>
        </div>
      </div>
    </div>

    <div class="card full-width">
      <h2>Recent Data</h2>
      <table>
        <thead>
          <tr>
            <th>Time</th>
            <th>Value</th>
            <th>Source</th>
          </tr>
        </thead>
        <tbody id="dataTable"></tbody>
      </table>
    </div>
  </div>

  <script>
    const data = [];
    const maxPoints = 30;
    let timer = null;

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const countValueEl = document.getElementById('countValue');
    const dataTable = document.getElementById('dataTable');
    const form = document.getElementById('dataForm');
    const valueInput = document.getElementById('valueInput');
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    function addDataPoint(value, source = 'manual') {
      const point = {
        time: new Date(),
        value: Number(value),
        source
      };

      data.push(point);
      if (data.length > maxPoints) data.shift();

      updateStats();
      updateTable();
      drawChart();
    }

    function updateStats() {
      if (data.length === 0) {
        latestValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        countValueEl.textContent = '0';
        return;
      }

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, p) => sum + p.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(2);
      avgValueEl.textContent = avg.toFixed(2);
      countValueEl.textContent = data.length;
    }

    function updateTable() {
      dataTable.innerHTML = '';

      [...data].reverse().forEach(point => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${point.time.toLocaleTimeString()}</td>
          <td>${point.value.toFixed(2)}</td>
          <td>${point.source}</td>
        `;
        dataTable.appendChild(row);
      });
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values);
      const max = Math.max(...values);
      const range = max - min || 1;

      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = (i / (maxPoints - 1)) * w;
        const y = h - ((point.value - min) / range) * (h - 20) - 10;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Draw points
      ctx.fillStyle = '#86efac';
      data.forEach((point, i) => {
        const x = (i / (maxPoints - 1)) * w;
        const y = h - ((point.value - min) / range) * (h - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function startSimulation() {
      if (timer) return;
      timer = setInterval(() => {
        const randomValue = 20 + Math.random() * 80;
        addDataPoint(randomValue, 'auto');
      }, 1000);
    }

    function stopSimulation() {
      clearInterval(timer);
      timer = null;
    }

    function clearData() {
      data.length = 0;
      updateStats();
      updateTable();
      drawChart();
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const value = parseFloat(valueInput.value);

      if (!isNaN(value)) {
        addDataPoint(value, 'manual');
        valueInput.value = '';
      }
    });

    document.getElementById('startBtn').addEventListener('click', startSimulation);
    document.getElementById('stopBtn').addEventListener('click', stopSimulation);
    document.getElementById('clearBtn').addEventListener('click', clearData);

    // Seed with initial data
    for (let i = 0; i < 8; i++) {
      addDataPoint(20 + Math.random() * 80, 'auto');
    }
    startSimulation();
  </script>
</body>
</html>
