const ctx = document.getElementById('liveChart').getContext('2d');
const submissionList = document.getElementById('submissionList');
const form = document.getElementById('dataForm');
const formMessage = document.getElementById('formMessage');

const chartData = {
  labels: [],
  datasets: [
    {
      label: 'Metric',
      data: [],
      borderColor: '#2563eb',
      backgroundColor: 'rgba(37, 99, 235, 0.2)',
      tension: 0.3,
      fill: true
    }
  ]
};

const liveChart = new Chart(ctx, {
  type: 'line',
  data: chartData,
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        min: 0,
        max: 100
      }
    }
  }
});

function addSubmission(entry) {
  const li = document.createElement('li');
  li.textContent = `${entry.createdAt} — ${entry.name}: ${entry.amount}`;
  submissionList.prepend(li);

  while (submissionList.children.length > 10) {
    submissionList.removeChild(submissionList.lastChild);
  }
}

function setSubmissions(entries) {
  submissionList.innerHTML = '';
  entries.forEach(addSubmission);
}

function addMetricPoint(point) {
  chartData.labels.push(point.timestamp);
  chartData.datasets[0].data.push(point.value);

  if (chartData.labels.length > 20) {
    chartData.labels.shift();
    chartData.datasets[0].data.shift();
  }

  liveChart.update();
}

const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
const socket = new WebSocket(`${protocol}://${window.location.host}`);

socket.addEventListener('message', (event) => {
  const data = JSON.parse(event.data);

  if (data.type === 'init') {
    setSubmissions(data.submissions);
  }

  if (data.type === 'metric') {
    addMetricPoint(data);
  }

  if (data.type === 'submission') {
    addSubmission(data.entry);
  }
});

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  formMessage.textContent = 'Sending...';

  const payload = {
    name: form.name.value.trim(),
    amount: form.amount.value
  };

  try {
    const res = await fetch('/api/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    const result = await res.json();

    if (!res.ok) {
      throw new Error(result.error || 'Submission failed');
    }

    form.reset();
    formMessage.textContent = 'Submitted successfully';
  } catch (err) {
    formMessage.textContent = err.message;
  }
});
