  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const statusTextEl = document.getElementById('statusText');
    const toggleBtn = document.getElementById('toggleBtn');
    const resetBtn = document.getElementById('resetBtn');
    const settingsForm = document.getElementById('settingsForm');
    const eventLog = document.getElementById('eventLog');

    let config = {
      label: 'Sensor A',
      interval: 1000,
      baseValue: 50,
      variance: 10
    };

    let data = [];
    let maxPoints = 30;
    let timer = null;
    let running = true;

    function logEvent(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);

      const muted = eventLog.querySelector('.muted');
      if (muted) muted.remove();

      while (eventLog.children.length > 20) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function generateValue() {
      const noise = (Math.random() * 2 - 1) * config.variance;
      return Math.max(0, +(config.baseValue + noise).toFixed(2));
    }

    function addDataPoint() {
      const value = generateValue();
      const point = {
        time: new Date(),
        value
      };

      data.push(point);
      if (data.length > maxPoints) data.shift();

      updateStats();
      drawChart();
    }

    function updateStats() {
      if (data.length === 0) {
        latestValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        return;
      }

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, p) => sum + p.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(2);
      avgValueEl.textContent = avg.toFixed(2);
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(40, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length === 0) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values, config.baseValue - config.variance, 0);
      const max = Math.max(...values, config.baseValue + config.variance, 1);
      const padding = 10;
      const chartLeft = 40;
      const chartRight = w - 10;
      const chartTop = 10;
      const chartBottom = h - 30;
      const chartWidth = chartRight - chartLeft;
      const chartHeight = chartBottom - chartTop;

      // Axes
      ctx.strokeStyle = 'rgba(229, 231, 235, 0.4)';
      ctx.beginPath();
      ctx.moveTo(chartLeft, chartTop);
      ctx.lineTo(chartLeft, chartBottom);
      ctx.lineTo(chartRight, chartBottom);
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px Arial';
      ctx.fillText(max.toFixed(1), 5, chartTop + 5);
      ctx.fillText(min.toFixed(1), 5, chartBottom);

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = chartLeft + (i / Math.max(data.length - 1, 1)) * chartWidth;
        const y = chartBottom - ((point.value - min) / Math.max(max - min, 1)) * chartHeight;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#38bdf8';
      data.forEach((point, i) => {
        const x = chartLeft + (i / Math.max(data.length - 1, 1)) * chartWidth;
        const y = chartBottom - ((point.value - min) / Math.max(max - min, 1)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      // Title
      ctx.fillStyle = '#e5e7eb';
      ctx.font = 'bold 14px Arial';
      ctx.fillText(config.label, 50, 20);
    }

    function startTimer() {
      stopTimer();
      timer = setInterval(addDataPoint, config.interval);
    }

    function stopTimer() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    toggleBtn.addEventListener('click', () => {
      running = !running;

      if (running) {
        startTimer();
        toggleBtn.textContent = 'Pause';
        statusTextEl.textContent = 'Running';
        logEvent('Data stream resumed');
      } else {
        stopTimer();
        toggleBtn.textContent = 'Resume';
        statusTextEl.textContent = 'Paused';
        logEvent('Data stream paused');
      }
    });

    resetBtn.addEventListener('click', () => {
      data = [];
      updateStats();
      drawChart();
      logEvent('Data reset');
    });

    settingsForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = document.getElementById('dataLabel').value.trim();
      const interval = parseInt(document.getElementById('intervalInput').value, 10);
      const baseValue = parseFloat(document.getElementById('baseValueInput').value);
      const variance = parseFloat(document.getElementById('varianceInput').value);

      if (!label || interval < 100 || variance < 1) {
        logEvent('Invalid form input');
        return;
      }

      config = { label, interval, baseValue, variance };
      logEvent(`Settings updated: ${label}, ${interval}ms, base=${baseValue}, variance=${variance}`);

      if (running) startTimer();
      drawChart();
    });

    // Initial state
    for (let i = 0; i < 10; i++) addDataPoint();
    startTimer();
    logEvent('Dashboard initialized');
  </script>
</body>
</html>
