## 2) `server.js`

```js
const express = require('express');
const path = require('path');

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

let latestPoint = {
  time: new Date().toLocaleTimeString(),
  value: 50
};

let submittedItems = [];

const clients = new Set();

function broadcast(data) {
  const payload = `data: ${JSON.stringify(data)}\n\n`;
  for (const res of clients) {
    res.write(payload);
  }
}

// Simulate real-time data every 2 seconds
setInterval(() => {
  const nextValue = Math.max(0, Math.min(100, latestPoint.value + (Math.random() * 20 - 10)));
  latestPoint = {
    time: new Date().toLocaleTimeString(),
    value: Number(nextValue.toFixed(1))
  };

  broadcast({
    type: 'metric',
    point: latestPoint
  });
}, 2000);

// SSE endpoint
app.get('/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  clients.add(res);

  // Send initial state
  res.write(`data: ${JSON.stringify({
    type: 'init',
    point: latestPoint,
    items: submittedItems
  })}\n\n`);

  req.on('close', () => {
    clients.delete(res);
  });
});

// Form submission endpoint
app.post('/submit', (req, res) => {
  const { name, amount } = req.body;

  if (!name || amount === undefined || amount === '') {
    return res.status(400).json({ error: 'Name and amount are required.' });
  }

  const item = {
    id: Date.now(),
    name: String(name),
    amount: Number(amount),
    createdAt: new Date().toLocaleTimeString()
  };

  submittedItems.unshift(item);

  broadcast({
    type: 'submission',
    item
  });

  res.json({ success: true, item });
});

app.get('/items', (req, res) => {
  res.json(submittedItems);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

