## 4) `public/app.js`

```js
const ctx = document.getElementById('metricChart');

const labels = [];
const values = [];

const chart = new Chart(ctx, {
  type: 'line',
  data: {
    labels,
    datasets: [{
      label: 'Metric Value',
      data: values,
      borderColor: '#3b82f6',
      backgroundColor: 'rgba(59,130,246,0.2)',
      tension: 0.3,
      fill: true
    }]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        min: 0,
        max: 100
      }
    }
  }
});

const itemList = document.getElementById('itemList');
const form = document.getElementById('recordForm');
const formMessage = document.getElementById('formMessage');

function addPoint(point) {
  labels.push(point.time);
  values.push(point.value);

  if (labels.length > 10) {
    labels.shift();
    values.shift();
  }

  chart.update();
}

function addItem(item) {
  const li = document.createElement('li');
  li.textContent = `${item.createdAt} — ${item.name}: ${item.amount}`;
  itemList.prepend(li);
}

const eventSource = new EventSource('/events');

eventSource.onmessage = (event) => {
  const data = JSON.parse(event.data);

  if (data.type === 'init') {
    addPoint(data.point);
    itemList.innerHTML = '';
    data.items.forEach(addItem);
  }

  if (data.type === 'metric') {
    addPoint(data.point);
  }

  if (data.type === 'submission') {
    addItem(data.item);
  }
};

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  formMessage.textContent = '';

  const name = document.getElementById('name').value.trim();
  const amount = document.getElementById('amount').value;

  try {
    const res = await fetch('/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ name, amount })
    });

    const data = await res.json();

    if (!res.ok) {
      formMessage.textContent = data.error || 'Submission failed';
      formMessage.className = 'error';
      return;
    }

    form.reset();
    formMessage.textContent = 'Submitted successfully';
    formMessage.className = 'success';
  } catch (err) {
    formMessage.textContent = 'Network error';
    formMessage.className = 'error';
  }
});
