    const latestValueEl = document.getElementById('latestValue');
    const averageValueEl = document.getElementById('averageValue');
    const thresholdValueEl = document.getElementById('thresholdValue');
    const eventLog = document.getElementById('eventLog');
    const statusEl = document.getElementById('status');
    const form = document.getElementById('controlForm');
    const thresholdInput = document.getElementById('thresholdInput');
    const speedSelect = document.getElementById('speedSelect');
    const dashboardNameInput = document.getElementById('dashboardName');

    let threshold = Number(thresholdInput.value);
    let intervalMs = Number(speedSelect.value);
    let timer = null;

    const labels = [];
    const values = [];

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: values,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          tension: 0.3,
          fill: true
