      const li = document.createElement('li');
      li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(li);

      while (eventLog.children.length > 8) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function updateStats() {
      const latest = values[values.length - 1] ?? 0;
      const avg = values.length
        ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1)
        : 0;

      latestValueEl.textContent = latest;
      averageValueEl.textContent = avg;
      thresholdValueEl.textContent = threshold;
    }

    function generateDataPoint() {
      const value = Math.floor(Math.random() * 101);
      const time = new Date().toLocaleTimeString();

      labels.push(time);
      values.push(value);

      if (labels.length > 12) {
        labels.shift();
        values.shift();
      }

      chart.update();
      updateStats();

      if (value > threshold) {
        addLog(`Alert: value ${value} exceeded threshold ${threshold}`);
        statusEl.textContent = 'Alert';
        statusEl.style.color = '#ef4444';
      } else {
        statusEl.textContent = 'Running';
        statusEl.style.color = '#22c55e';
      }
    }

    function startFeed() {
      if (timer) clearInterval(timer);
      timer = setInterval(generateDataPoint, intervalMs);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      threshold = Number(thresholdInput.value);
      intervalMs = Number(speedSelect.value);
      const name = dashboardNameInput.value.trim() || 'Real-Time Dashboard';

      document.title = name;
      document.querySelector('h1').textContent = name;

      startFeed();
      updateStats();
      addLog(`Settings applied: threshold=${threshold}, speed=${intervalMs}ms`);
    });

    // Initial state
    addLog('Dashboard started');
    updateStats();
    startFeed();
  </script>
