## 3. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static("public"));

let dataPoints = [
  { time: new Date().toLocaleTimeString(), value: 10, label: "Initial" }
];

let events = [
  { time: new Date().toLocaleTimeString(), message: "Dashboard started" }
];

function broadcast(payload) {
  const message = JSON.stringify(payload);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/data", (req, res) => {
  res.json({ dataPoints, events });
});

app.post("/api/data", (req, res) => {
  const { label, value } = req.body;

  if (!label || typeof value !== "number" || Number.isNaN(value)) {
    return res.status(400).json({ error: "Invalid label or value" });
  }

  const point = {
    time: new Date().toLocaleTimeString(),
    label,
    value
  };

  dataPoints.push(point);
  if (dataPoints.length > 20) dataPoints.shift();

  const event = {
    time: new Date().toLocaleTimeString(),
    message: `Added ${label}: ${value}`
  };

  events.unshift(event);
  if (events.length > 20) events.pop();

  broadcast({ type: "update", point, event, dataPoints, events });

  res.json({ success: true, point });
});

setInterval(() => {
  const point = {
    time: new Date().toLocaleTimeString(),
    label: "Auto",
    value: Math.floor(Math.random() * 100)
  };

  dataPoints.push(point);
  if (dataPoints.length > 20) dataPoints.shift();

  const event = {
    time: new Date().toLocaleTimeString(),
    message: `Auto-generated value: ${point.value}`
  };

  events.unshift(event);
  if (events.length > 20) events.pop();

  broadcast({ type: "update", point, event, dataPoints, events });
}, 3000);

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", dataPoints, events }));
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
