## 6. `public/app.js`

```js
const ctx = document.getElementById("chart").getContext("2d");
const eventLog = document.getElementById("eventLog");
const form = document.getElementById("dataForm");
const statusEl = document.getElementById("status");

let chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Values",
        data: [],
        borderColor: "#2563eb",
        backgroundColor: "rgba(37, 99, 235, 0.2)",
        tension: 0.3,
        fill: true
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        beginAtZero: true
      }
    }
  }
});

function renderChart(dataPoints) {
  chart.data.labels = dataPoints.map((p) => `${p.time} (${p.label})`);
  chart.data.datasets[0].data = dataPoints.map((p) => p.value);
  chart.update();
}

function renderEvents(events) {
  eventLog.innerHTML = "";
  events.forEach((event) => {
    const li = document.createElement("li");
    li.textContent = `[${event.time}] ${event.message}`;
    eventLog.appendChild(li);
  });
}

async function loadInitialData() {
  const res = await fetch("/api/data");
  const payload = await res.json();
  renderChart(payload.dataPoints);
  renderEvents(payload.events);
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const label = document.getElementById("label").value.trim();
  const value = Number(document.getElementById("value").value);

  statusEl.textContent = "Submitting...";

  try {
    const res = await fetch("/api/data", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ label, value })
    });

    const result = await res.json();

    if (!res.ok) {
      throw new Error(result.error || "Submission failed");
    }

    form.reset();
    statusEl.textContent = "Submitted successfully";
  } catch (err) {
    statusEl.textContent = err.message;
  }
});

loadInitialData();

const protocol = window.location.protocol === "https:" ? "wss" : "ws";
const socket = new WebSocket(`${protocol}://${window.location.host}`);

socket.addEventListener("message", (event) => {
  const payload = JSON.parse(event.data);

  if (payload.type === "init" || payload.type === "update") {
    renderChart(payload.dataPoints);
    renderEvents(payload.events);
  }
});

socket.addEventListener("open", () => {
  console.log("WebSocket connected");
});

socket.addEventListener("close", () => {
  console.log("WebSocket disconnected");
});
