  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const countValueEl = document.getElementById("countValue");
    const logEl = document.getElementById("log");
    const form = document.getElementById("dataForm");

    const maxPoints = 30;
    const data = [];

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
      logEl.prepend(item);

      while (logEl.children.length > 20) {
        logEl.removeChild(logEl.lastChild);
      }
    }

    function addDataPoint(label, value) {
      data.push({
        label,
        value: Number(value),
        time: new Date()
      });

      if (data.length > maxPoints) {
        data.shift();
      }

      updateStats();
      drawChart();
      addLog(`${label}: ${value}`);
    }

    function updateStats() {
      if (data.length === 0) {
        latestValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        countValueEl.textContent = "0";
        return;
      }

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, d) => sum + d.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(2);
      avgValueEl.textContent = avg.toFixed(2);
      countValueEl.textContent = data.length;
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      const padding = 40;

      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, width, height);

      // Axes
      ctx.strokeStyle = "#cbd5e1";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, 10);
      ctx.lineTo(padding, height - padding);
      ctx.lineTo(width - 10, height - padding);
      ctx.stroke();

      if (data.length === 0) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values);
      const max = Math.max(...values);
      const range = max - min || 1;

      // Grid lines and labels
      ctx.fillStyle = "#64748b";
      ctx.font = "12px Arial";
      for (let i = 0; i <= 4; i++) {
        const y = 10 + ((height - padding - 10) / 4) * i;
        const value = max - (range / 4) * i;

        ctx.strokeStyle = "#e2e8f0";
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - 10, y);
        ctx.stroke();

        ctx.fillText(value.toFixed(1), 5, y + 4);
      }

      // Line
      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + (index / Math.max(data.length - 1, 1)) * (width - padding - 20);
        const y = 10 + ((max - point.value) / range) * (height - padding - 10);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#1d4ed8";
      data.forEach((point, index) => {
        const x = padding + (index / Math.max(data.length - 1, 1)) * (width - padding - 20);
        const y = 10 + ((max - point.value) / range) * (height - padding - 10);

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = document.getElementById("label").value.trim();
      const value = parseFloat(document.getElementById("value").value);

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value);
      form.reset();
    });

    // Simulated real-time data
    setInterval(() => {
      const randomValue = 20 + Math.random() * 80;
      addDataPoint("Auto", randomValue);
    }, 1000);

    // Initial render
    updateStats();
    drawChart();
  </script>
</body>
</html>
```

