          </div>
        </div>
      </div>

      <div class="card">
        <h2>Controls</h2>
        <form id="controlForm">
          <div>
            <label for="threshold">Alert Threshold</label>
            <input type="number" id="threshold" name="threshold" value="50" min="0" max="100" />
            <div class="error" id="thresholdError">Please enter a value between 0 and 100.</div>
          </div>

