  <script>
    const maxPoints = 20;
    let threshold = 50;
    let mode = "normal";
    let latest = 0;
    let values = [];

    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const thresholdValueEl = document.getElementById("thresholdValue");
    const activityLog = document.getElementById("activityLog");

    const ctx = document.getElementById("liveChart").getContext("2d");

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels: [],
        datasets: [{
          label: "Sensor Value",
          data: [],
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.15)",
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        animation: false,
        responsive: true,
        scales: {
          y: {
            min: 0,
            max: 100
          }
        }
      }
    });

    function addLog(message) {
      const li = document.createElement("li");
      li.textContent = `${new Date().toLocaleTimeString()}: ${message}`;
      activityLog.prepend(li);

      while (activityLog.children.length > 8) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    function updateStats() {
      latestValueEl.textContent = latest.toFixed(1);
      const avg = values.length
        ? values.reduce((a, b) => a + b, 0) / values.length
        : 0;
      avgValueEl.textContent = avg.toFixed(1);
      thresholdValueEl.textContent = threshold;
    }

    function generateValue() {
      const base = mode === "boost" ? 65 : 40;
      const variance = mode === "boost" ? 35 : 20;
      return Math.max(0, Math.min(100, base + (Math.random() * variance - variance / 2)));
    }

    function tick() {
      latest = generateValue();
      values.push(latest);
      if (values.length > maxPoints) values.shift();

      const timeLabel = new Date().toLocaleTimeString();

      chart.data.labels.push(timeLabel);
      chart.data.datasets[0].data.push(latest);

      if (chart.data.labels.length > maxPoints) chart.data.labels.shift();
      if (chart.data.datasets[0].data.length > maxPoints) chart.data.datasets[0].data.shift();

      chart.update();
      updateStats();

      if (latest > threshold) {
        addLog(`Alert: value ${latest.toFixed(1)} exceeded threshold ${threshold}`);
      }
    }

    document.getElementById("controlForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const thresholdInput = document.getElementById("threshold");
      const labelInput = document.getElementById("label");
      const modeInput = document.getElementById("mode");

      const thresholdError = document.getElementById("thresholdError");
      const labelError = document.getElementById("labelError");

      let valid = true;

      const newThreshold = Number(thresholdInput.value);
      if (Number.isNaN(newThreshold) || newThreshold < 0 || newThreshold > 100) {
        thresholdError.style.display = "block";
        valid = false;
      } else {
        thresholdError.style.display = "none";
      }

      const label = labelInput.value.trim();
      if (label.length < 3) {
        labelError.style.display = "block";
        valid = false;
      } else {
        labelError.style.display = "none";
      }

      if (!valid) return;

      threshold = newThreshold;
      mode = modeInput.value;

      addLog(`Settings updated: threshold=${threshold}, mode=${mode}, label="${label}"`);
      updateStats();
      this.reset();
      document.getElementById("threshold").value = threshold;
      document.getElementById("mode").value = mode;
    });

    updateStats();
    addLog("Dashboard started");
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

