## 2) `server.js`

```js
const express = require("express");
const path = require("path");

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let latestValue = 50;
let latestLabel = "Live Metric";
let history = [];
let clients = [];

function broadcast(data) {
  const payload = `data: ${JSON.stringify(data)}\n\n`;
  clients.forEach((res) => res.write(payload));
}

function pushDataPoint(value, source = "system") {
  const point = {
    time: new Date().toLocaleTimeString(),
    value,
    source
  };

  history.push(point);
  if (history.length > 20) history.shift();

  latestValue = value;

  broadcast({
    type: "update",
    latestValue,
    latestLabel,
    history
  });
}

// SSE endpoint
app.get("/events", (req, res) => {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders?.();

  clients.push(res);

  // send initial state
  res.write(
    `data: ${JSON.stringify({
      type: "init",
      latestValue,
      latestLabel,
      history
    })}\n\n`
  );

  req.on("close", () => {
    clients = clients.filter((client) => client !== res);
  });
});

// form submission endpoint
app.post("/submit", (req, res) => {
  const { label, value } = req.body;

  if (typeof label !== "string" || typeof value !== "number" || Number.isNaN(value)) {
    return res.status(400).json({ error: "Invalid payload" });
  }

  latestLabel = label.trim() || "Live Metric";
  pushDataPoint(value, "user");

  res.json({
    success: true,
    latestLabel,
    latestValue
  });
});

// simulate realtime updates
setInterval(() => {
  const next = Math.max(0, Math.min(100, latestValue + (Math.random() * 20 - 10)));
  pushDataPoint(Number(next.toFixed(1)), "system");
}, 2000);

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

