## 4) `public/app.js`

```js
const metricLabel = document.getElementById("metricLabel");
const metricValue = document.getElementById("metricValue");
const connectionStatus = document.getElementById("connectionStatus");
const form = document.getElementById("metricForm");
const labelInput = document.getElementById("labelInput");
const valueInput = document.getElementById("valueInput");
const formMessage = document.getElementById("formMessage");

const ctx = document.getElementById("chart").getContext("2d");

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Metric Value",
        data: [],
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59,130,246,0.2)",
        tension: 0.3,
        fill: true
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        min: 0,
        max: 100
      }
    }
  }
});

function render(state) {
  metricLabel.textContent = state.latestLabel;
  metricValue.textContent = state.latestValue;

  chart.data.labels = state.history.map((p) => p.time);
  chart.data.datasets[0].data = state.history.map((p) => p.value);
  chart.update();
}

const eventSource = new EventSource("/events");

eventSource.onopen = () => {
  connectionStatus.textContent = "Live";
  connectionStatus.className = "status live";
};

eventSource.onmessage = (event) => {
  const state = JSON.parse(event.data);
  render(state);
};

eventSource.onerror = () => {
  connectionStatus.textContent = "Disconnected";
  connectionStatus.className = "status offline";
};

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  formMessage.textContent = "";

  const payload = {
    label: labelInput.value,
    value: Number(valueInput.value)
  };

  try {
    const res = await fetch("/submit", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(payload)
    });

    const data = await res.json();

    if (!res.ok) {
      throw new Error(data.error || "Submission failed");
    }

    formMessage.textContent = "Submitted successfully";
    valueInput.value = "";
  } catch (err) {
    formMessage.textContent = err.message;
  }
});
