  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="chart" width="700" height="300"></canvas>

        <div class="stats">
          <div class="stat">
            <div class="label">Latest Value</div>
            <div class="value" id="latestValue">0</div>
          </div>
          <div class="stat">
            <div class="label">Average</div>
            <div class="value" id="averageValue">0</div>
          </div>
        </div>

        <div class="status" id="feedStatus">Feed running...</div>
      </div>

      <div class="card">
        <h2>Controls</h2>
        <form id="controlForm">
          <label>
            Sensor Name
            <input type="text" id="sensorName" placeholder="e.g. Temperature Sensor" required />
          </label>

          <label>
            Update Speed
            <select id="speed">
              <option value="1000">1 second</option>
              <option value="500">0.5 second</option>
              <option value="2000">2 seconds</option>
            </select>
          </label>

          <label>
            Manual Value
            <input type="number" id="manualValue" placeholder="e.g. 42" />
          </label>

          <button type="submit">Apply Settings</button>
          <button type="button" id="pushValueBtn">Push Manual Value</button>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const averageValueEl = document.getElementById('averageValue');
    const feedStatusEl = document.getElementById('feedStatus');
    const eventLogEl = document.getElementById('eventLog');

    const form = document.getElementById('controlForm');
    const sensorNameInput = document.getElementById('sensorName');
    const speedSelect = document.getElementById('speed');
    const manualValueInput = document.getElementById('manualValue');
    const pushValueBtn = document.getElementById('pushValueBtn');

    let sensorName = 'Default Sensor';
    let intervalMs = 1000;
    let timer = null;
    let data = [];

    function log(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLogEl.prepend(item);
    }

    function generateValue() {
      return Math.floor(Math.random() * 100);
    }

    function addDataPoint(value) {
      data.push(value);
      if (data.length > 30) data.shift();
      updateStats();
      drawChart();
    }

    function updateStats() {
      const latest = data[data.length - 1] ?? 0;
      const avg = data.length
        ? (data.reduce((sum, n) => sum + n, 0) / data.length).toFixed(1)
        : 0;

      latestValueEl.textContent = latest;
      averageValueEl.textContent = avg;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = (index / (data.length - 1)) * w;
        const y = h - (value / 100) * h;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#86efac';
      data.forEach((value, index) => {
        const x = (index / (data.length - 1)) * w;
        const y = h - (value / 100) * h;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function startFeed() {
      if (timer) clearInterval(timer);

      timer = setInterval(() => {
        const value = generateValue();
        addDataPoint(value);
        feedStatusEl.textContent = `${sensorName} feed running every ${intervalMs}ms`;
      }, intervalMs);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      sensorName = sensorNameInput.value.trim() || 'Default Sensor';
      intervalMs = Number(speedSelect.value);

      startFeed();
      log(`Updated settings: sensor="${sensorName}", speed=${intervalMs}ms`);
    });

    pushValueBtn.addEventListener('click', () => {
      const value = Number(manualValueInput.value);
      if (Number.isNaN(value)) {
        log('Manual value rejected: invalid number');
        return;
      }

      const clamped = Math.max(0, Math.min(100, value));
      addDataPoint(clamped);
      log(`Manual value pushed: ${clamped}`);
      manualValueInput.value = '';
    });

    // Initial state
    sensorNameInput.value = sensorName;
    startFeed();
    log('Dashboard started');
  </script>
</body>
