    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const form = document.getElementById("entryForm");
    const log = document.getElementById("log");

    const maxPoints = 30;
    const data = Array.from({ length: maxPoints }, () => randomValue());
    const labels = Array.from({ length: maxPoints }, (_, i) => i + 1);

    function randomValue() {
      return Math.floor(Math.random() * 100);
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      const padding = 30;

      ctx.clearRect(0, 0, w, h);

      // Axes
      ctx.strokeStyle = "#cbd5e1";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, h - padding);
      ctx.lineTo(w - padding, h - padding);
      ctx.stroke();

      // Line
      const maxVal = 100;
      const stepX = (w - padding * 2) / (data.length - 1);

      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = h - padding - (val / maxVal) * (h - padding * 2);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#1d4ed8";
      data.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = h - padding - (val / maxVal) * (h - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function updateStats() {
      const current = data[data.length - 1];
      const avg = data.reduce((sum, v) => sum + v, 0) / data.length;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg.toFixed(1);
    }

    function tick() {
      data.push(randomValue());
      if (data.length > maxPoints) data.shift();

      drawChart();
      updateStats();
    }

    setInterval(tick, 1000);
    drawChart();
    updateStats();

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const value = document.getElementById("value").value.trim();

      if (!name || !value) return;

      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `${new Date().toLocaleTimeString()} — ${name}: ${value}`;
      log.prepend(item);

      document.getElementById("name").value = "";
      document.getElementById("value").value = "";
    });
  </script>
