      ctx.fillStyle = "#1d4ed8";
      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * (width - padding * 2);
        const y = height - padding - ((value - minVal) / range) * (height - padding * 2);

        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      // Axis labels
      ctx.fillStyle = "#666";
      ctx.font = "12px Arial";
      ctx.fillText(maxVal.toFixed(0), 5, padding + 5);
      ctx.fillText(minVal.toFixed(0), 5, height - padding);
    }

    function pushDataPoint(value = Math.floor(Math.random() * 100)) {
      data.push(value);
      if (data.length > 30) data.shift();
      updateStats();
      drawChart();
    }

    function startRealtimeUpdates() {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        pushDataPoint();
      }, intervalMs);
    }

    controlForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = new FormData(controlForm);
      const label = formData.get("label");
      const value = Number(formData.get("value"));

      if (Number.isNaN(value)) {
        alert("Please enter a valid number.");
        return;
      }

      pushDataPoint(value);
      addLog(`${label}: added value ${value}`);

      controlForm.reset();
      speedSelect.value = String(intervalMs);
    });

    speedSelect.addEventListener("change", () => {
      intervalMs = Number(speedSelect.value);
      startRealtimeUpdates();
      addLog(`Changed update speed to ${intervalMs} ms`);
    });

    updateStats();
    drawChart();
    startRealtimeUpdates();
    addLog("Dashboard started");
  </script>
</body>
</html>
```

