            <input id="valueInput" name="value" type="number" placeholder="e.g. 72" required />
          </div>

          <div>
            <label for="speedSelect">Update Speed</label>
            <select id="speedSelect" name="speed">
              <option value="1000">1 second</option>
              <option value="500">0.5 second</option>
              <option value="2000">2 seconds</option>
            </select>
          </div>

          <button type="submit">Add Event</button>
        </form>

