  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const statusTextEl = document.getElementById('statusText');
    const form = document.getElementById('controlForm');
    const eventLog = document.getElementById('eventLog');
    const speedSelect = document.getElementById('speedSelect');

    const maxPoints = 40;
    let data = Array.from({ length: maxPoints }, () => randomValue());
    let timer = null;
    let intervalMs = Number(speedSelect.value);

    function randomValue() {
      return Math.floor(30 + Math.random() * 70);
    }

    function average(arr) {
      return arr.reduce((sum, n) => sum + n, 0) / arr.length;
    }

    function updateStats() {
      const latest = data[data.length - 1];
      latestValueEl.textContent = latest;
      avgValueEl.textContent = average(data).toFixed(1);
      statusTextEl.textContent = timer ? 'Running' : 'Stopped';
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      const pad = 30;

      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = 'rgba(148,163,184,0.2)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = pad + ((h - pad * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(pad, y);
        ctx.lineTo(w - pad, y);
        ctx.stroke();
      }

      // Axes
      ctx.strokeStyle = '#475569';
      ctx.beginPath();
      ctx.moveTo(pad, pad);
      ctx.lineTo(pad, h - pad);
      ctx.lineTo(w - pad, h - pad);
      ctx.stroke();

      const min = 0;
      const max = 100;
      const stepX = (w - pad * 2) / (data.length - 1);

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, i) => {
        const x = pad + i * stepX;
        const y = h - pad - ((value - min) / (max - min)) * (h - pad * 2);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#86efac';
      data.forEach((value, i) => {
        const x = pad + i * stepX;
        const y = h - pad - ((value - min) / (max - min)) * (h - pad * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function tick(newValue = randomValue()) {
      data.push(newValue);
      if (data.length > maxPoints) data.shift();
      updateStats();
      drawChart();
    }

    function startTimer() {
      stopTimer();
      timer = setInterval(() => tick(), intervalMs);
      updateStats();
    }

    function stopTimer() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
    }

    function addLogItem(text) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `${new Date().toLocaleTimeString()} — ${text}`;

      if (eventLog.querySelector('.muted')) {
        eventLog.innerHTML = '';
      }

      eventLog.prepend(item);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(form);
      const label = formData.get('label');
      const value = Number(formData.get('value'));

      if (!label || Number.isNaN(value)) return;

      tick(value);
      addLogItem(`${label}: ${value}`);
      form.reset();
      speedSelect.value = String(intervalMs);
    });

    speedSelect.addEventListener('change', (e) => {
      intervalMs = Number(e.target.value);
      startTimer();
      addLogItem(`Update speed changed to ${intervalMs}ms`);
    });

    // Initial render
    updateStats();
    drawChart();
    startTimer();
  </script>
</body>
</html>
