    const latestValueEl = document.getElementById('latestValue');
    const averageValueEl = document.getElementById('averageValue');
    const totalPointsEl = document.getElementById('totalPoints');
    const dataTableBody = document.getElementById('dataTableBody');
    const dataForm = document.getElementById('dataForm');
    const valueInput = document.getElementById('valueInput');

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Value',
          data: [],
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#cbd5e1' },
            grid: { color: '#334155' }
          },
          y: {
            ticks: { color: '#cbd5e1' },
            grid: { color: '#334155' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function formatTime(date) {
      return date.toLocaleTimeString();
    }

    function addDataPoint(value, source = 'auto') {
      const point = {
        time: new Date(),
        value: Number(value),
        source
      };

      dataPoints.push(point);

      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
      }

      updateUI();
    }

    function updateUI() {
      chart.data.labels = dataPoints.map(p => formatTime(p.time));
      chart.data.datasets[0].data = dataPoints.map(p => p.value);
      chart.update();

      const latest = dataPoints[dataPoints.length - 1];
      const avg = dataPoints.length
        ? dataPoints.reduce((sum, p) => sum + p.value, 0) / dataPoints.length
        : 0;

      latestValueEl.textContent = latest ? latest.value.toFixed(2) : '0';
      averageValueEl.textContent = avg.toFixed(2);
      totalPointsEl.textContent = dataPoints.length;

      dataTableBody.innerHTML = [...dataPoints]
        .reverse()
        .map(p => `
          <tr>
            <td>${formatTime(p.time)}</td>
            <td>${p.value.toFixed(2)}</td>
            <td>${p.source}</td>
          </tr>
        `)
        .join('');
    }

    function generateRandomValue() {
      return (Math.random() * 100).toFixed(2);
    }

    function startFeed() {
      if (timer) return;
      timer = setInterval(() => {
        addDataPoint(generateRandomValue(), 'auto');
      }, 1000);
    }

    function stopFeed() {
      clearInterval(timer);
      timer = null;
    }

    function resetDashboard() {
      stopFeed();
      dataPoints = [];
      updateUI();
    }

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const value = valueInput.value.trim();

      if (value === '') return;

      addDataPoint(value, 'manual');
      valueInput.value = '';
      valueInput.focus();
    });

    document.getElementById('startBtn').addEventListener('click', startFeed);
    document.getElementById('stopBtn').addEventListener('click', stopFeed);
    document.getElementById('resetBtn').addEventListener('click', resetDashboard);

    updateUI();
    startFeed();
  </script>
</body>
</html>
```

