  <script>
    const maxPoints = 20;
    const labels = [];
    const values = [];

    const ctx = document.getElementById('liveChart').getContext('2d');
    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const pointCountEl = document.getElementById('pointCount');
    const logEl = document.getElementById('log');
    const form = document.getElementById('dataForm');
    const labelInput = document.getElementById('labelInput');
    const valueInput = document.getElementById('valueInput');
    const modeSelect = document.getElementById('modeSelect');

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: values,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateStats() {
      const latest = values.length ? values[values.length - 1] : 0;
      const avg = values.length
        ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(2)
        : 0;

      latestValueEl.textContent = latest;
      avgValueEl.textContent = avg;
      pointCountEl.textContent = values.length;
    }

    function addLog(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(item);
    }

    function trimData() {
      while (labels.length > maxPoints) labels.shift();
      while (values.length > maxPoints) values.shift();
    }

    function addPoint(label, value) {
      labels.push(label);
      values.push(value);
      trimData();
      chart.update();
      updateStats();
    }

    function replaceLatestPoint(label, value) {
      if (values.length === 0) {
        addPoint(label, value);
        return;
      }
      labels[labels.length - 1] = label;
      values[values.length - 1] = value;
      chart.update();
      updateStats();
    }

    // Simulated realtime data feed
    setInterval(() => {
      const value = Math.floor(Math.random() * 100);
      const label = new Date().toLocaleTimeString();
      addPoint(label, value);
      addLog(`Auto data received: ${value}`);
    }, 2000);

    // Form handling
    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);
      const mode = modeSelect.value;

      if (!label || Number.isNaN(value)) {
        addLog('Invalid form input.');
        return;
      }

      if (mode === 'append') {
        addPoint(label, value);
        addLog(`Manual point added: ${label} = ${value}`);
      } else {
        replaceLatestPoint(label, value);
        addLog(`Latest point replaced: ${label} = ${value}`);
      }

      form.reset();
    });

    // Seed initial data
    for (let i = 0; i < 5; i++) {
      addPoint(`Init ${i + 1}`, Math.floor(Math.random() * 100));
    }
    addLog('Dashboard initialized.');
  </script>
