  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <h2 id="currentValue">0</h2>
        <p>Current Value</p>
      </div>
      <div class="stat">
        <h2 id="averageValue">0</h2>
        <p>Average</p>
      </div>
      <div class="stat">
        <h2 id="thresholdValue">50</h2>
        <p>Alert Threshold</p>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h3>Live Chart</h3>
        <canvas id="chart" width="700" height="300"></canvas>
      </div>

      <div class="card">
        <h3>Controls</h3>
        <form id="controlForm">
          <div>
            <label for="threshold">Threshold</label>
            <input type="number" id="threshold" name="threshold" value="50" min="0" max="100" />
          </div>

          <div>
            <label for="speed">Update Speed</label>
            <select id="speed" name="speed">
              <option value="1000">1 second</option>
              <option value="500">0.5 second</option>
              <option value="200">0.2 second</option>
            </select>
          </div>

          <button type="submit">Apply Settings</button>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const thresholdValueEl = document.getElementById("thresholdValue");
    const eventLog = document.getElementById("eventLog");
    const form = document.getElementById("controlForm");
    const thresholdInput = document.getElementById("threshold");
    const speedInput = document.getElementById("speed");

    let threshold = 50;
    let updateSpeed = 1000;
    let timer = null;
    let data = Array.from({ length: 30 }, () => Math.floor(Math.random() * 100));

    function logEvent(message) {
      const entry = document.createElement("div");
      entry.className = "log-entry";
      entry.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(entry);
    }

    function updateStats() {
      const current = data[data.length - 1];
      const avg = data.reduce((sum, val) => sum + val, 0) / data.length;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg.toFixed(1);
      thresholdValueEl.textContent = threshold;

      if (current > threshold) {
        logEvent(`Alert: value ${current} exceeded threshold ${threshold}`);
      }
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      const padding = 30;

      ctx.clearRect(0, 0, width, height);

      // Axes
      ctx.strokeStyle = "#999";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, height - padding);
      ctx.lineTo(width - padding, height - padding);
      ctx.stroke();

      // Threshold line
      const thresholdY = height - padding - (threshold / 100) * (height - 2 * padding);
      ctx.strokeStyle = "#ef4444";
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(width - padding, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Data line
      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * (width - 2 * padding);
        const y = height - padding - (value / 100) * (height - 2 * padding);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#2563eb";
      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * (width - 2 * padding);
        const y = height - padding - (value / 100) * (height - 2 * padding);

        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function generateDataPoint() {
      const nextValue = Math.floor(Math.random() * 100);
      data.push(nextValue);
      if (data.length > 30) data.shift();

      updateStats();
      drawChart();
    }

    function startUpdates() {
      if (timer) clearInterval(timer);
      timer = setInterval(generateDataPoint, updateSpeed);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      threshold = Number(thresholdInput.value);
      updateSpeed = Number(speedInput.value);

      updateStats();
      drawChart();
      startUpdates();

      logEvent(`Settings updated: threshold=${threshold}, speed=${updateSpeed}ms`);
    });

    // Initial render
    updateStats();
    drawChart();
    startUpdates();
    logEvent("Dashboard started");
  </script>
</body>
</html>
