      <form id="controlForm">
        <label>
          Data Label
          <input type="text" id="dataLabel" placeholder="e.g. Sensor A" required />
        </label>

        <label>
          Update Interval
          <select id="intervalSelect">
            <option value="500">0.5 sec</option>
            <option value="1000" selected>1 sec</option>
            <option value="2000">2 sec</option>
          </select>
        </label>

        <label>
          Manual Value
          <input type="number" id="manualValue" placeholder="Optional numeric value" />
        </label>

        <button type="submit">Submit Entry</button>
        <button type="button" id="toggleBtn">Pause</button>
      </form>

      <div class="log" id="log"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const statusTextEl = document.getElementById('statusText');
    const logEl = document.getElementById('log');

    const form = document.getElementById('controlForm');
    const dataLabelInput = document.getElementById('dataLabel');
    const intervalSelect = document.getElementById('intervalSelect');
    const manualValueInput = document.getElementById('manualValue');
    const toggleBtn = document.getElementById('toggleBtn');

    let data = Array.from({ length: 30 }, () => randomValue());
    let timer = null;
    let running = true;
    let currentInterval = Number(intervalSelect.value);

    function randomValue() {
      return Math.floor(20 + Math.random() * 80);
    }

    function addLog(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(item);
    }

    function updateStats() {
      const latest = data[data.length - 1] ?? 0;
      const avg = data.reduce((sum, v) => sum + v, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(0);
      avgValueEl.textContent = avg.toFixed(1);
      statusTextEl.textContent = running ? 'Running' : 'Paused';
      statusTextEl.style.color = running ? '#22c55e' : '#ef4444';
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      const padding = 30;

      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i < 5; i++) {
        const y = padding + ((h - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(w - padding, y);
        ctx.stroke();
      }

      // Axes
      ctx.strokeStyle = '#475569';
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, h - padding);
      ctx.lineTo(w - padding, h - padding);
      ctx.stroke();

      const max = 100;
      const min = 0;
      const stepX = (w - padding * 2) / (data.length - 1 || 1);

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = h - padding - ((value - min) / (max - min)) * (h - padding * 2);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#86efac';
      data.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = h - padding - ((value - min) / (max - min)) * (h - padding * 2);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function tick(value = randomValue()) {
      data.push(value);
      if (data.length > 30) data.shift();
      updateStats();
      drawChart();
    }

    function startTimer() {
      clearInterval(timer);
      timer = setInterval(() => {
        if (running) tick();
      }, currentInterval);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = dataLabelInput.value.trim();
      const manualValue = manualValueInput.value.trim();
      const value = manualValue === '' ? randomValue() : Number(manualValue);

      if (!label) {
        alert('Please enter a data label.');
        return;
      }

      if (Number.isNaN(value)) {
        alert('Manual value must be numeric.');
        return;
      }

      tick(value);
      addLog(`${label}: submitted value ${value}`);

      manualValueInput.value = '';
      dataLabelInput.value = '';
    });

    intervalSelect.addEventListener('change', () => {
      currentInterval = Number(intervalSelect.value);
      startTimer();
      addLog(`Update interval changed to ${currentInterval} ms`);
    });

    toggleBtn.addEventListener('click', () => {
      running = !running;
      toggleBtn.textContent = running ? 'Pause' : 'Resume';
      updateStats();
      addLog(running ? 'Realtime updates resumed' : 'Realtime updates paused');
    });

    updateStats();
    drawChart();
    startTimer();
    addLog('Dashboard started');
  </script>
</body>
</html>
```

## What this includes

- **Realtime visualization**: simulated data updates on a timer
- **Interactive chart**: drawn on a `<canvas>`
- **Form handling**:
  - text input
  - select dropdown
  - numeric input
  - validation
  - submit handling
- **Controls**:
  - pause/resume updates
  - change update interval
  - manually inject values
- **Activity log**: shows recent actions

