## `service-worker.js`

This optional background worker updates the badge with the number of blocked requests per tab.

```js
const blockedCounts = new Map();

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener((info) => {
  const tabId = info.request.tabId;
  if (tabId < 0) return;

  const current = blockedCounts.get(tabId) || 0;
  const next = current + 1;
  blockedCounts.set(tabId, next);

  chrome.action.setBadgeBackgroundColor({ color: "#b91c1c", tabId });
  chrome.action.setBadgeText({ text: String(next), tabId });
});

chrome.tabs.onRemoved.addListener((tabId) => {
  blockedCounts.delete(tabId);
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  if (changeInfo.status === "loading") {
    blockedCounts.set(tabId, 0);
    chrome.action.setBadgeText({ text: "", tabId });
  }
});

chrome.runtime.onInstalled.addListener(() => {
  chrome.action.setBadgeBackgroundColor({ color: "#b91c1c" });
});
```

