# 2. `background.js`

This script installs dynamic blocking rules and supports enabling/disabling them.

```javascript
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "www.google-analytics.com",
  "googletagmanager.com",
  "connect.facebook.net",
  "facebook.com/tr",
  "doubleclick.net",
  "stats.g.doubleclick.net",
  "ads.twitter.com",
  "static.ads-twitter.com",
  "snap.licdn.com",
  "bat.bing.com",
  "hotjar.com",
  "script.hotjar.com",
  "static.hotjar.com",
  "segment.com",
  "cdn.segment.com",
  "api.segment.io"
];

const RULE_ID_START = 1000;

async function buildRules() {
  return TRACKER_DOMAINS.map((domain, index) => ({
    id: RULE_ID_START + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  }));
}

async function enableBlocking() {
  const rules = await buildRules();
  const ids = rules.map(r => r.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: ids,
    addRules: rules
  });

  await chrome.storage.local.set({ blockingEnabled: true });
  console.log("Tracking protection enabled");
}

async function disableBlocking() {
  const rules = await buildRules();
  const ids = rules.map(r => r.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: ids
  });

  await chrome.storage.local.set({ blockingEnabled: false });
  console.log("Tracking protection disabled");
}

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");
  if (blockingEnabled === false) {
    await disableBlocking();
  } else {
    await enableBlocking();
  }
});

chrome.runtime.onStartup.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");
  if (blockingEnabled === false) {
    await disableBlocking();
  } else {
    await enableBlocking();
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.action === "enable") {
    enableBlocking().then(() => sendResponse({ success: true }));
    return true;
  }

  if (message.action === "disable") {
    disableBlocking().then(() => sendResponse({ success: true }));
    return true;
  }

  if (message.action === "status") {
    chrome.storage.local.get("blockingEnabled").then((result) => {
      sendResponse({ enabled: result.blockingEnabled !== false });
    });
    return true;
  }
});
```

