## 2. `rules.js`

This file defines a list of common tracker domains and converts them into blocking rules.

```js
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "www.google-analytics.com",
  "googletagmanager.com",
  "connect.facebook.net",
  "facebook.com/tr",
  "doubleclick.net",
  "stats.g.doubleclick.net",
  "analytics.twitter.com",
  "static.ads-twitter.com",
  "snap.licdn.com",
  "bat.bing.com",
  "hotjar.com",
  "script.hotjar.com",
  "cdn.segment.com",
  "api.segment.io",
  "fullstory.com",
  "edge.fullstory.com",
  "mixpanel.com",
  "api.mixpanel.com"
];

function buildRules() {
  return TRACKER_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "image",
        "ping",
        "sub_frame"
      ]
    }
  }));
}
```

