## `background.js`

This optional background script updates the badge with the number of blocked requests per tab.

```js
const blockedCounts = {};

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener((info) => {
  const tabId = info.request.tabId;
  if (tabId < 0) return;

  blockedCounts[tabId] = (blockedCounts[tabId] || 0) + 1;

  chrome.action.setBadgeBackgroundColor({
    color: "#d32f2f",
    tabId
  });

  chrome.action.setBadgeText({
    text: String(blockedCounts[tabId]),
    tabId
  });
});

chrome.tabs.onRemoved.addListener((tabId) => {
  delete blockedCounts[tabId];
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  if (changeInfo.status === "loading") {
    blockedCounts[tabId] = 0;
    chrome.action.setBadgeText({
      text: "",
      tabId
    });
  }
});
```

