## 2. `background.js`

This script installs dynamic blocking rules using `declarativeNetRequest`.

```js
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "www.google-analytics.com",
  "ssl.google-analytics.com",
  "doubleclick.net",
  "www.googletagmanager.com",
  "connect.facebook.net",
  "facebook.com/tr",
  "static.hotjar.com",
  "script.hotjar.com",
  "cdn.segment.com",
  "api.segment.io",
  "bat.bing.com",
  "snap.licdn.com",
  "px.ads.linkedin.com",
  "analytics.twitter.com",
  "static.ads-twitter.com",
  "googlesyndication.com",
  "adservice.google.com",
  "scorecardresearch.com",
  "zedo.com",
  "quantserve.com"
];

function buildRules(enabled) {
  if (!enabled) return [];

  return TRACKER_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "image",
        "sub_frame",
        "ping"
      ]
    }
  }));
}

async function updateRules(enabled) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingRuleIds = existingRules.map(rule => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingRuleIds,
    addRules: buildRules(enabled)
  });
}

async function initialize() {
  const result = await chrome.storage.sync.get({ blockingEnabled: true });
  await updateRules(result.blockingEnabled);
}

chrome.runtime.onInstalled.addListener(() => {
  initialize();
});

chrome.runtime.onStartup.addListener(() => {
  initialize();
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes.blockingEnabled) {
    updateRules(changes.blockingEnabled.newValue);
  }
});
```

