### `background.js`
Loads static rules and strips tracking parameters from navigations.

```js
const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "gclid",
  "fbclid",
  "mc_cid",
  "mc_eid"
];

chrome.runtime.onInstalled.addListener(async () => {
  try {
    const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
    const existingRuleIds = existingRules.map(r => r.id);

    if (existingRuleIds.length) {
      await chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: existingRuleIds
      });
    }

    const rulesUrl = chrome.runtime.getURL("rules.json");
    const response = await fetch(rulesUrl);
    const staticRules = await response.json();

    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: staticRules
    });

    console.log("Tracker blocking rules installed.");
  } catch (err) {
    console.error("Failed to install rules:", err);
  }
});

chrome.webNavigation.onBeforeNavigate?.addListener(async (details) => {
  if (details.frameId !== 0) return;

  try {
    const url = new URL(details.url);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        changed = true;
      }
    }

    if (changed && url.href !== details.url) {
      await chrome.tabs.update(details.tabId, { url: url.toString() });
    }
  } catch (err) {
    console.error("URL cleanup failed:", err);
  }
});
```

