### `content.js`
This lightly reduces fingerprinting surface. It is intentionally conservative to avoid breaking sites.

```js
(() => {
  const patch = (obj, prop, value) => {
    try {
      Object.defineProperty(obj, prop, {
        get: () => value,
        configurable: true
      });
    } catch (_) {}
  };

  patch(navigator, "doNotTrack", "1");

  try {
    const originalQuery = window.navigator.permissions?.query;
    if (originalQuery) {
      window.navigator.permissions.query = async function (parameters) {
        if (parameters && parameters.name === "notifications") {
          return { state: Notification.permission };
        }
        return originalQuery.apply(this, arguments);
      };
    }
  } catch (_) {}

  try {
    const originalGetContext = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (...args) {
      const ctx = originalGetContext.apply(this, args);
      return ctx;
    };
  } catch (_) {}
})();
```

