## `popup.js`

```js
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");
const RULESET_ID = "tracker_rules";

async function updateUI() {
  const enabledRulesets = await chrome.declarativeNetRequest.getEnabledRulesets();
  const enabled = enabledRulesets.includes(RULESET_ID);
  statusEl.textContent = enabled ? "Blocking is ON" : "Blocking is OFF";
  toggleBtn.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
}

toggleBtn.addEventListener("click", async () => {
  const enabledRulesets = await chrome.declarativeNetRequest.getEnabledRulesets();
  const enabled = enabledRulesets.includes(RULESET_ID);

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [RULESET_ID]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID]
    });
  }

  updateUI();
});

updateUI();
```

