## `background.js`

```js
importScripts("rules.js");

function matchesTracker(url) {
  try {
    const parsed = new URL(url);
    const host = parsed.hostname.toLowerCase();
    const full = url.toLowerCase();

    return TRACKER_DOMAINS.some(domain => {
      return host === domain || host.endsWith("." + domain) || full.includes(domain);
    });
  } catch {
    return false;
  }
}

function stripTrackingParams(url) {
  try {
    const parsed = new URL(url);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (parsed.searchParams.has(param)) {
        parsed.searchParams.delete(param);
        changed = true;
      }
    }

    return changed ? parsed.toString() : null;
  } catch {
    return null;
  }
}

// Block known tracker requests
chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (matchesTracker(details.url)) {
      console.log("[Privacy Tracker Blocker] Blocked:", details.url);
      return { cancel: true };
    }

    // Strip tracking params on main frame navigations
    if (details.type === "main_frame") {
      const cleanedUrl = stripTrackingParams(details.url);
      if (cleanedUrl && cleanedUrl !== details.url) {
        console.log("[Privacy Tracker Blocker] Redirected:", details.url, "->", cleanedUrl);
        return { redirectUrl: cleanedUrl };
      }
    }

    return {};
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Optional: badge count per tab
const blockedCounts = new Map();

function updateBadge(tabId) {
  const count = blockedCounts.get(tabId) || 0;
  chrome.action.setBadgeText({
    tabId,
    text: count > 0 ? String(count) : ""
  });
  chrome.action.setBadgeBackgroundColor({
    tabId,
    color: "#b00020"
  });
}

chrome.webRequest.onErrorOccurred.addListener(
  (details) => {
    if (details.tabId >= 0 && matchesTracker(details.url)) {
      const current = blockedCounts.get(details.tabId) || 0;
      blockedCounts.set(details.tabId, current + 1);
      updateBadge(details.tabId);
    }
  },
  { urls: ["<all_urls>"] }
);

chrome.tabs.onRemoved.addListener((tabId) => {
  blockedCounts.delete(tabId);
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  if (changeInfo.status === "loading") {
    blockedCounts.set(tabId, 0);
    updateBadge(tabId);
  }
});
```

