## `service_worker.js`

This keeps track of whether blocking is enabled and allows toggling dynamic rules.

```javascript
const DYNAMIC_RULE_IDS = [1001];
const TRACKER_TEST_RULE = {
  id: 1001,
  priority: 1,
  action: { type: "block" },
  condition: {
    urlFilter: "||example-tracker.com^",
    resourceTypes: ["script", "xmlhttprequest", "image", "ping", "sub_frame"]
  }
};

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.sync.get({ enabled: true });
  await setEnabled(data.enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const data = await chrome.storage.sync.get({ enabled: true });
  await setEnabled(data.enabled);
});

async function setEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }
  await chrome.storage.sync.set({ enabled });
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getStatus") {
    chrome.storage.sync.get({ enabled: true }).then(sendResponse);
    return true;
  }

  if (message?.type === "setStatus") {
    setEnabled(message.enabled).then(() => {
      sendResponse({ ok: true, enabled: message.enabled });
    });
    return true;
  }
});
```

