## Optional: Add dynamic user-controlled blocking

If you want users to enable/disable blocking without removing the extension, you can add a toggle.

### Replace `background.js` with:

```js
const RULESET_ID = "tracker_rules";

async function setBlockingEnabled(enabled) {
  const currentlyEnabled = enabled ? [RULESET_ID] : [];
  const currentlyDisabled = enabled ? [] : [RULESET_ID];

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: currentlyEnabled,
    disableRulesetIds: currentlyDisabled
  });

  await chrome.storage.local.set({ blockingEnabled: enabled });
}

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");
  await setBlockingEnabled(blockingEnabled !== false);
});

chrome.action.onClicked.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");
  const nextState = !(blockingEnabled !== false);
  await setBlockingEnabled(nextState);

  console.log(`Blocking ${nextState ? "enabled" : "disabled"}`);
});
```

