## 5. `popup.js`

This script toggles the static ruleset on and off and shows a simple blocked count placeholder.

```javascript
const toggleButton = document.getElementById("toggleButton");
const statusText = document.getElementById("statusText");
const blockedCount = document.getElementById("blockedCount");

async function loadState() {
  const result = await chrome.storage.local.get({
    blockingEnabled: true,
    blockedCount: 0
  });

  updateUI(result.blockingEnabled, result.blockedCount);
}

function updateUI(enabled, count) {
  statusText.textContent = enabled ? "Enabled" : "Disabled";
  toggleButton.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
  blockedCount.textContent = count;
}

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }

  await chrome.storage.local.set({ blockingEnabled: enabled });
  const result = await chrome.storage.local.get(["blockedCount"]);
  updateUI(enabled, result.blockedCount || 0);
}

toggleButton.addEventListener("click", async () => {
  const result = await chrome.storage.local.get({ blockingEnabled: true });
  await setBlockingEnabled(!result.blockingEnabled);
});

loadState();
```

