## `background.js`

This script intercepts requests and blocks those matching known tracker patterns.

```js
let blockingEnabled = true;
let blockedCount = 0;

chrome.storage.local.get(["blockingEnabled", "blockedCount"], (result) => {
  if (typeof result.blockingEnabled === "boolean") {
    blockingEnabled = result.blockingEnabled;
  }
  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }
});

function isTracker(url) {
  try {
    const parsed = new URL(url);
    const fullUrl = url.toLowerCase();
    const hostname = parsed.hostname.toLowerCase();

    return TRACKER_PATTERNS.some((pattern) => {
      const p = pattern.toLowerCase();
      return hostname === p ||
             hostname.endsWith("." + p) ||
             fullUrl.includes(p);
    });
  } catch (e) {
    return false;
  }
}

function updateBadge() {
  chrome.browserAction.setBadgeText({
    text: blockedCount > 0 ? String(blockedCount) : ""
  });
  chrome.browserAction.setBadgeBackgroundColor({ color: "#d9534f" });
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!blockingEnabled) {
      return { cancel: false };
    }

    const resourceTypesToCheck = ["script", "xmlhttprequest", "image", "sub_frame"];

    if (!resourceTypesToCheck.includes(details.type)) {
      return { cancel: false };
    }

    if (isTracker(details.url)) {
      blockedCount += 1;
      chrome.storage.local.set({ blockedCount });
      updateBadge();

      console.log("Blocked tracker:", details.url);
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({
      blockingEnabled,
      blockedCount
    });
  }

  if (message.type === "setBlockingEnabled") {
    blockingEnabled = !!message.enabled;
    chrome.storage.local.set({ blockingEnabled });
    sendResponse({ success: true, blockingEnabled });
  }

  if (message.type === "resetBlockedCount") {
    blockedCount = 0;
    chrome.storage.local.set({ blockedCount });
    updateBadge();
    sendResponse({ success: true, blockedCount });
  }

  return true;
});

updateBadge();
```

