function refreshStatus() {
  chrome.runtime.sendMessage({ type: "getStatus" }, (response) => {
    const statusEl = document.getElementById("status");
    const countEl = document.getElementById("count");
    const toggleBtn = document.getElementById("toggleBtn");

    if (!response) {
      statusEl.textContent = "Status: Error";
      return;
    }

    statusEl.textContent = `Status: ${response.blockingEnabled ? "Enabled" : "Disabled"}`;
    countEl.textContent = `Blocked: ${response.blockedCount}`;
    toggleBtn.textContent = response.blockingEnabled ? "Disable Blocking" : "Enable Blocking";
  });
}

document.getElementById("toggleBtn").addEventListener("click", () => {
  chrome.runtime.sendMessage({ type: "getStatus" }, (response) => {
    if (!response) return;

    chrome.runtime.sendMessage(
      {
        type: "setBlockingEnabled",
        enabled: !response.blockingEnabled
      },
      () => refreshStatus()
    );
  });
});

document.getElementById("resetBtn").addEventListener("click", () => {
  chrome.runtime.sendMessage({ type: "resetBlockedCount" }, () => {
    refreshStatus();
  });
});

refreshStatus();
