## `background.js`

This script blocks requests matching the tracker patterns and keeps a simple block count.

```js
let blockingEnabled = true;
let blockedCount = 0;

chrome.storage.local.get(["blockingEnabled", "blockedCount"], (result) => {
  if (typeof result.blockingEnabled === "boolean") {
    blockingEnabled = result.blockingEnabled;
  }

  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }

  updateBadge();
});

function updateBadge() {
  chrome.browserAction.setBadgeText({
    text: blockedCount > 0 ? String(blockedCount) : ""
  });

  chrome.browserAction.setBadgeBackgroundColor({
    color: blockingEnabled ? "#d32f2f" : "#757575"
  });
}

function persistState() {
  chrome.storage.local.set({
    blockingEnabled,
    blockedCount
  });
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!blockingEnabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    updateBadge();
    persistState();

    console.log("Blocked tracker:", details.url);

    return { cancel: true };
  },
  { urls: TRACKER_PATTERNS },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({
      blockingEnabled,
      blockedCount
    });
    return;
  }

  if (message.type === "toggleBlocking") {
    blockingEnabled = !blockingEnabled;
    persistState();
    updateBadge();

    sendResponse({
      blockingEnabled,
      blockedCount
    });
    return;
  }

  if (message.type === "resetCount") {
    blockedCount = 0;
    persistState();
    updateBadge();

    sendResponse({
      blockingEnabled,
      blockedCount
    });
  }
});
```

