## 3. `background.js`

This initializes extension state and tracks whether blocking is enabled.

```js
const DEFAULT_SETTINGS = {
  enabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.local.get(["enabled"]);
  if (typeof existing.enabled === "undefined") {
    await chrome.storage.local.set(DEFAULT_SETTINGS);
  }
  console.log("Privacy Tracker Blocker installed");
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    chrome.storage.local.get(["enabled"]).then((result) => {
      sendResponse({ enabled: result.enabled !== false });
    });
    return true;
  }

  if (message.type === "setStatus") {
    const enabled = !!message.enabled;

    chrome.storage.local.set({ enabled }).then(async () => {
      await chrome.declarativeNetRequest.updateEnabledRulesets({
        enableRulesetIds: enabled ? ["tracker_rules"] : [],
        disableRulesetIds: enabled ? [] : ["tracker_rules"]
      });

      sendResponse({ success: true, enabled });
    });

    return true;
  }
});
```

