## `background.js`

This script blocks matching requests and keeps a simple block count.

```javascript
let blockedCount = 0;
let extensionEnabled = true;

function updateBadge() {
  const text = extensionEnabled ? String(blockedCount) : "OFF";
  chrome.browserAction.setBadgeText({ text });
  chrome.browserAction.setBadgeBackgroundColor({
    color: extensionEnabled ? "#d9534f" : "#777777"
  });
}

chrome.storage.local.get(["blockedCount", "extensionEnabled"], (result) => {
  blockedCount = result.blockedCount || 0;
  extensionEnabled = result.extensionEnabled !== false;
  updateBadge();
});

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!extensionEnabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    chrome.storage.local.set({ blockedCount });
    updateBadge();

    console.log("Blocked tracker:", details.url);
    return { cancel: true };
  },
  { urls: TRACKER_PATTERNS, types: ["script", "xmlhttprequest", "image", "sub_frame"] },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStats") {
    sendResponse({
      blockedCount,
      extensionEnabled
    });
  }

  if (message.type === "toggleExtension") {
    extensionEnabled = !extensionEnabled;
    chrome.storage.local.set({ extensionEnabled });
    updateBadge();
    sendResponse({
      blockedCount,
      extensionEnabled
    });
  }

  if (message.type === "resetStats") {
    blockedCount = 0;
    chrome.storage.local.set({ blockedCount });
    updateBadge();
    sendResponse({
      blockedCount,
      extensionEnabled
    });
  }

  return true;
});
```

