## Replace `background.js` with this

```js
importScripts("rules.js");

let blockedCount = 0;
let enabled = true;

function isTracker(url) {
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname;
    const fullUrl = parsed.href;

    return TRACKER_DOMAINS.some((domain) => {
      return (
        hostname === domain ||
        hostname.endsWith(`.${domain}`) ||
        fullUrl.includes(domain)
      );
    });
  } catch (e) {
    return false;
  }
}

function loadState() {
  chrome.storage.local.get(["blockedCount", "enabled"], (result) => {
    blockedCount = result.blockedCount || 0;
    enabled = result.enabled !== false;
  });
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!enabled) {
      return {};
    }

    if (isTracker(details.url)) {
      blockedCount++;
      chrome.storage.local.set({ blockedCount });
      console.log("Blocked tracker:", details.url);
      return { cancel: true };
    }

    return {};
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

chrome.storage.onChanged.addListener((changes, area) => {
  if (area !== "local") return;

  if (changes.enabled) {
    enabled = changes.enabled.newValue !== false;
  }

  if (changes.blockedCount) {
    blockedCount = changes.blockedCount.newValue || 0;
  }
});

chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({ blockedCount: 0, enabled: true });
  loadState();
});

chrome.runtime.onStartup.addListener(() => {
  loadState();
});

loadState();
