## `background.js`

In Manifest V3, dynamic blocking is best done with `declarativeNetRequest`. This script converts the domain list into blocking rules and installs them on extension startup.

```js
importScripts("rules.js");

const RULE_ID_START = 1000;

function buildRules(domains) {
  return domains.map((domain, index) => ({
    id: RULE_ID_START + index,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "image",
        "sub_frame",
        "ping"
      ]
    }
  }));
}

async function installRules() {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingRuleIds = existingRules.map(rule => rule.id);

  const newRules = buildRules(TRACKER_DOMAINS);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingRuleIds,
    addRules: newRules
  });

  console.log(`Installed ${newRules.length} tracking protection rules.`);
}

chrome.runtime.onInstalled.addListener(() => {
  installRules().catch(console.error);
});

chrome.runtime.onStartup.addListener(() => {
  installRules().catch(console.error);
});
```

