## `background.js`

```js
importScripts("rules.js");

function hostnameFromUrl(url) {
  try {
    return new URL(url).hostname;
  } catch {
    return "";
  }
}

function matchesTrackerDomain(hostname) {
  return TRACKER_DOMAINS.some(domain =>
    hostname === domain || hostname.endsWith(`.${domain}`)
  );
}

function matchesTrackerPattern(url) {
  return TRACKER_PATTERNS.some(pattern => pattern.test(url));
}

async function incrementBlockedCount() {
  const data = await chrome.storage.local.get(["blockedCount"]);
  const blockedCount = (data.blockedCount || 0) + 1;
  await chrome.storage.local.set({ blockedCount });
  chrome.action.setBadgeText({ text: String(blockedCount) });
  chrome.action.setBadgeBackgroundColor({ color: "#d32f2f" });
}

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(["blockedCount"]);
  if (typeof data.blockedCount !== "number") {
    await chrome.storage.local.set({ blockedCount: 0 });
  }
  chrome.action.setBadgeBackgroundColor({ color: "#d32f2f" });
});

chrome.webRequest.onBeforeRequest.addListener(
  details => {
    const hostname = hostnameFromUrl(details.url);

    const shouldBlock =
      matchesTrackerDomain(hostname) || matchesTrackerPattern(details.url);

    if (shouldBlock) {
      incrementBlockedCount();
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
```

