## `background.js`

```javascript
let blocklist = {
  domains: [],
  urlPatterns: []
};

async function loadBlocklist() {
  try {
    const url = browser.runtime.getURL("blocklist.json");
    const response = await fetch(url);
    blocklist = await response.json();
    console.log("Blocklist loaded:", blocklist);
  } catch (error) {
    console.error("Failed to load blocklist:", error);
  }
}

function matchesBlockedDomain(requestUrl) {
  try {
    const hostname = new URL(requestUrl).hostname;
    return blocklist.domains.some(domain =>
      hostname === domain || hostname.endsWith(`.${domain}`)
    );
  } catch {
    return false;
  }
}

function matchesBlockedPattern(requestUrl) {
  return blocklist.urlPatterns.some(pattern => requestUrl.includes(pattern));
}

function shouldBlock(details) {
  if (details.type !== "script") {
    return false;
  }

  const url = details.url;

  if (matchesBlockedDomain(url)) {
    return true;
  }

  if (matchesBlockedPattern(url)) {
    return true;
  }

  return false;
}

function handleBeforeRequest(details) {
  if (shouldBlock(details)) {
    console.log("Blocked tracker:", details.url);
    return { cancel: true };
  }

  return { cancel: false };
}

loadBlocklist().then(() => {
  browser.webRequest.onBeforeRequest.addListener(
    handleBeforeRequest,
    { urls: ["<all_urls>"] },
    ["blocking"]
  );
});
```

