## 3. `background.js`

This manages the enabled/disabled state by turning the static ruleset on or off.

```javascript
const RULESET_ID = "tracker-rules";
const STORAGE_KEY = "blockingEnabled";

async function setBlockingEnabled(enabled) {
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });

  await chrome.storage.local.set({ [STORAGE_KEY]: enabled });
}

async function initialize() {
  const result = await chrome.storage.local.get(STORAGE_KEY);
  const enabled = result[STORAGE_KEY] !== false;
  await setBlockingEnabled(enabled);
}

chrome.runtime.onInstalled.addListener(() => {
  initialize();
});

chrome.runtime.onStartup.addListener(() => {
  initialize();
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getState") {
    chrome.storage.local.get(STORAGE_KEY).then((result) => {
      const enabled = result[STORAGE_KEY] !== false;
      sendResponse({ enabled });
    });
    return true;
  }

  if (message.type === "setState") {
    setBlockingEnabled(message.enabled)
      .then(() => sendResponse({ success: true, enabled: message.enabled }))
      .catch((error) => sendResponse({ success: false, error: error.message }));
    return true;
  }
});
```

