## `background.js`

This service worker blocks matching requests and keeps a simple block count.

```js
importScripts("rules.js");

let blockedCount = 0;
let enabled = true;

chrome.storage.local.get(["enabled", "blockedCount"], (result) => {
  if (typeof result.enabled === "boolean") {
    enabled = result.enabled;
  }
  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }
  updateBadge();
});

function updateBadge() {
  chrome.action.setBadgeText({
    text: blockedCount > 0 ? String(blockedCount) : ""
  });
  chrome.action.setBadgeBackgroundColor({ color: "#d9534f" });
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!enabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    chrome.storage.local.set({ blockedCount });
    updateBadge();

    return { cancel: true };
  },
  { urls: TRACKER_PATTERNS },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({ enabled, blockedCount });
  }

  if (message.type === "toggleEnabled") {
    enabled = !enabled;
    chrome.storage.local.set({ enabled });
    sendResponse({ enabled, blockedCount });
  }

  if (message.type === "resetCount") {
    blockedCount = 0;
    chrome.storage.local.set({ blockedCount });
    updateBadge();
    sendResponse({ enabled, blockedCount });
  }

  return true;
});
```

