chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!blockingEnabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    saveSettings();

    return { cancel: true };
  },
  {
    urls: DEFAULT_TRACKERS,
    types: ["script", "xmlhttprequest", "image", "sub_frame"]
  },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({
      blockingEnabled,
      blockedCount
    });
  }

  if (message.type === "toggleBlocking") {
    blockingEnabled = !blockingEnabled;
    saveSettings();
    sendResponse({
      blockingEnabled
    });
  }

  if (message.type === "resetCount") {
    blockedCount = 0;
    saveSettings();
    sendResponse({
      blockedCount
    });
  }

  return true;
});
