## `background.js`

This script blocks matching requests and keeps a simple block counter.

```javascript
let blockedCount = 0;
let enabled = true;

function updateBadge() {
  const text = enabled ? String(blockedCount) : "OFF";
  chrome.browserAction.setBadgeText({ text });
  chrome.browserAction.setBadgeBackgroundColor({
    color: enabled ? "#d9534f" : "#777777"
  });
}

chrome.storage.local.get(["enabled", "blockedCount"], (result) => {
  if (typeof result.enabled === "boolean") {
    enabled = result.enabled;
  }

  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }

  updateBadge();
});

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!enabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    chrome.storage.local.set({ blockedCount });
    updateBadge();

    console.log("Blocked tracker:", details.url);

    return { cancel: true };
  },
  { urls: TRACKER_PATTERNS },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({
      enabled,
      blockedCount
    });
  }

  if (message.type === "toggleEnabled") {
    enabled = !enabled;
    chrome.storage.local.set({ enabled });
    updateBadge();

    sendResponse({
      enabled,
      blockedCount
    });
  }
});
```

