## 2. `background.js`

This script intercepts outgoing requests and blocks ones matching a tracker list.

```javascript
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "googletagmanager.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "analytics.twitter.com",
  "ads.twitter.com",
  "hotjar.com",
  "segment.io",
  "mixpanel.com"
];

const DEFAULT_SETTINGS = {
  enabled: true,
  blockedCount: 0
};

function getSettings() {
  return new Promise((resolve) => {
    chrome.storage.local.get(DEFAULT_SETTINGS, (items) => {
      resolve(items);
    });
  });
}

function setSettings(newSettings) {
  return new Promise((resolve) => {
    chrome.storage.local.set(newSettings, () => resolve());
  });
}

function isTrackerUrl(url) {
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname;

    return TRACKER_DOMAINS.some((domain) =>
      hostname === domain || hostname.endsWith(`.${domain}`)
    );
  } catch (e) {
    return false;
  }
}

async function incrementBlockedCount() {
  const settings = await getSettings();
  await setSettings({
    ...settings,
    blockedCount: (settings.blockedCount || 0) + 1
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  const settings = await getSettings();
  await setSettings({
    enabled: settings.enabled ?? true,
    blockedCount: settings.blockedCount ?? 0
  });
});

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    return new Promise(async (resolve) => {
      const settings = await getSettings();

      if (!settings.enabled) {
        resolve({ cancel: false });
        return;
      }

      const isScriptOrRequest =
        details.type === "script" ||
        details.type === "xmlhttprequest" ||
        details.type === "image" ||
        details.type === "sub_frame" ||
        details.type === "ping";

      if (isScriptOrRequest && isTrackerUrl(details.url)) {
        incrementBlockedCount();
        resolve({ cancel: true });
        return;
      }

      resolve({ cancel: false });
    });
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
```

