const TRACKER_RULES = [
  {
    id: 1,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||google-analytics.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping"]
    }
  },
  {
    id: 2,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||googletagmanager.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping"]
    }
  },
  {
    id: 3,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||doubleclick.net^",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping"]
    }
  }
];

chrome.runtime.onInstalled.addListener(async () => {
  await chrome.storage.local.set({ enabled: true, blockedCount: 0 });
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: TRACKER_RULES.map(rule => rule.id),
    addRules: TRACKER_RULES
  });
});
