You can save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
      overflow: hidden;
    }

    .toolbar {
      display: flex;
      gap: 12px;
      align-items: center;
      padding: 12px 16px;
      background: #111827;
      border-bottom: 1px solid #1f2937;
    }

    .toolbar button,
    .toolbar select {
      background: #1f2937;
      color: #e5e7eb;
      border: 1px solid #374151;
      padding: 8px 12px;
      border-radius: 6px;
      cursor: pointer;
    }

    .toolbar button:hover,
    .toolbar select:hover {
      background: #374151;
    }

    #chart {
      width: 100vw;
      height: calc(100vh - 58px);
      position: relative;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: white;
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      box-shadow: 0 4px 20px rgba(0,0,0,0.35);
      opacity: 0;
      transition: opacity 0.15s ease;
      white-space: nowrap;
      z-index: 10;
    }

    .axis path,
    .axis line {
      stroke: #475569;
    }

    .axis text {
      fill: #cbd5e1;
      font-size: 11px;
    }

    .grid line {
      stroke: #1e293b;
      stroke-opacity: 0.8;
      shape-rendering: crispEdges;
    }

    .grid path {
      stroke-width: 0;
    }

    .cell {
      stroke: #0b1220;
      stroke-width: 1px;
    }

    .label {
      fill: #f8fafc;
      font-size: 10px;
      text-anchor: middle;
      dominant-baseline: middle;
      pointer-events: none;
      user-select: none;
    }

    .legend text {
      fill: #cbd5e1;
      font-size: 11px;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="toggleUpdates">Pause Updates</button>
    <button id="resetZoom">Reset Zoom</button>
    <label>
      Update Speed:
      <select id="speedSelect">
        <option value="2000">2s</option>
        <option value="1000" selected>1s</option>
        <option value="500">0.5s</option>
        <option value="250">0.25s</option>
      </select>
    </label>
  </div>

  <div id="chart">
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    const sectors = [
      "Technology", "Finance", "Healthcare", "Energy",
      "Consumer", "Industrial", "Utilities", "Materials"
    ];

    const stocksPerSector = 12;

    function generateInitialData() {
      const data = [];
      sectors.forEach(sector => {
        for (let i = 0; i < stocksPerSector; i++) {
          const symbol = sector.slice(0, 3).toUpperCase() + (i + 1);
          const price = +(50 + Math.random() * 250).toFixed(2);
          data.push({
            sector,
            symbol,
            price,
            prevPrice: price,
            changePct: 0
          });
        }
      });
      return data;
    }

    let data = generateInitialData();

    const container = document.getElementById("chart");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 30, right: 30, bottom: 60, left: 100 };
    let width = container.clientWidth - margin.left - margin.right;
    let height = container.clientHeight - margin.top - margin.bottom;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", container.clientWidth)
      .attr("height", container.clientHeight);

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g");
    const gridLayer = zoomLayer.append("g").attr("class", "grid");
    const cellsLayer = zoomLayer.append("g");
    const labelsLayer = zoomLayer.append("g");

    const xAxisGroup = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${height})`);

    const yAxisGroup = root.append("g")
      .attr("class", "axis");

    const xGridGroup = root.append("g")
      .attr("class", "grid")
      .attr("transform", `translate(0,${height})`);

    const legendGroup = svg.append("g").attr("class", "legend");

    const stockSymbols = data.map(d => d.symbol);
    const sectorNames = sectors;

    let xScale = d3.scaleBand()
      .domain(stockSymbols)
      .range([0, width])
      .padding(0.05);

    let yScale = d3.scaleBand()
      .domain(sectorNames)
      .range([0, height])
      .padding(0.05);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1e293b", "#16a34a"])
      .clamp(true);

    function drawLegend() {
      const legendWidth = 220;
      const legendHeight = 12;
      const x = container.clientWidth - legendWidth - 40;
      const y = 20;

      legendGroup.attr("transform", `translate(${x},${y})`);
      legendGroup.selectAll("*").remove();

      const defs = svg.select("defs").empty() ? svg.append("defs") : svg.select("defs");
      defs.select("#legend-gradient").remove();

      const gradient = defs.append("linearGradient")
        .attr("id", "legend-gradient")
        .attr("x1", "0%")
        .attr("x2", "100%");

      gradient.append("stop").attr("offset", "0%").attr("stop-color", "#b91c1c");
      gradient.append("stop").attr("offset", "50%").attr("stop-color", "#1e293b");
      gradient.append("stop").attr("offset", "100%").attr("stop-color", "#16a34a");

      legendGroup.append("text")
        .attr("x", 0)
        .attr("y", -6)
        .text("Price Change %");

      legendGroup.append("rect")
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", "url(#legend-gradient)")
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-5, 5])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .ticks(5)
        .tickFormat(d => `${d}%`);

      legendGroup.append("g")
        .attr("transform", `translate(0,${legendHeight})`)
        .call(legendAxis)
        .call(g => g.selectAll("text").attr("fill", "#cbd5e1"))
        .call(g => g.selectAll("line,path").attr("stroke", "#475569"));
    }

    function render() {
      const xAxis = d3.axisBottom(xScale).tickValues(
        xScale.domain().filter((d, i) => i % Math.ceil(stockSymbols.length / 16) === 0)
      );

      const yAxis = d3.axisLeft(yScale);

      xAxisGroup.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      yAxisGroup.call(yAxis);

      const cells = cellsLayer.selectAll(".cell")
        .data(data, d => d.symbol);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 3)
        .attr("ry", 3)
        .merge(cells)
        .attr("x", d => xScale(d.symbol))
        .attr("y", d => yScale(d.sector))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.changePct))
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .style("left", `${event.offsetX + 14}px`)
            .style("top", `${event.offsetY + 14}px`)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Sector: ${d.sector}<br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: ${d.changePct.toFixed(2)}%
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        });

      cells.exit().remove();

      const labels = labelsLayer.selectAll(".label")
        .data(data, d => d.symbol);

      labels.enter()
        .append("text")
        .attr("class", "label")
        .merge(labels)
        .attr("x", d => xScale(d.symbol) + xScale.bandwidth() / 2)
        .attr("y", d => yScale(d.sector) + yScale.bandwidth() / 2)
        .text(d => xScale.bandwidth() > 35 && yScale.bandwidth() > 18 ? d.symbol : "");

      labels.exit().remove();
    }

    function updateData() {
      data.forEach(d => {
        d.prevPrice = d.price;
        const drift = (Math.random() - 0.5) * 4;
        d.price = Math.max(5, +(d.price + drift).toFixed(2));
        d.changePct = +(((d.price - d.prevPrice) / d.prevPrice) * 100).toFixed(2);
      });

      cellsLayer.selectAll(".cell")
        .data(data, d => d.symbol)
        .transition()
        .duration(300)
        .attr("fill", d => colorScale(d.changePct));

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function zoomed(event) {
      const transform = event.transform;
      zoomLayer.attr("transform", transform);

      const zx = transform.rescaleX(
        d3.scaleLinear().domain([0, width]).range([0, width])
      );

      const visibleSymbols = stockSymbols.map(symbol => {
        const x = xScale(symbol);
        return { symbol, x: zx(x) };
      });

      xAxisGroup.call(
        d3.axisBottom(
          d3.scaleBand()
            .domain(stockSymbols)
            .range([transform.applyX(0), transform.applyX(width)])
            .padding(0.05)
        ).tickValues(
          stockSymbols.filter((d, i) => i % Math.max(1, Math.ceil(16 / transform.k)) === 0)
        )
      )
      .selectAll("text")
      .attr("transform", "rotate(-45)")
      .style("text-anchor", "end");
    }

    function resize() {
      width = container.clientWidth - margin.left - margin.right;
      height = container.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", container.clientWidth)
        .attr("height", container.clientHeight);

      xScale.range([0, width]);
      yScale.range([0, height]);

      xAxisGroup.attr("transform", `translate(0,${height})`);

      render();
      drawLegend();
    }

    let isRunning = true;
    let intervalMs = 1000;
    let timer = setInterval(updateData, intervalMs);

    document.getElementById("toggleUpdates").addEventListener("click", () => {
      isRunning = !isRunning;
      const btn = document.getElementById("toggleUpdates");
      btn.textContent = isRunning ? "Pause Updates" : "Resume Updates";

      clearInterval(timer);
      if (isRunning) {
        timer = setInterval(updateData, intervalMs);
      }
    });

    document.getElementById("speedSelect").addEventListener("change", (e) => {
      intervalMs = +e.target.value;
      clearInterval(timer);
      if (isRunning) {
        timer = setInterval(updateData, intervalMs);
      }
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    render();
    drawLegend();
  </script>
</body>
</html>
```

