      border: 1px solid #475569;
      border-radius: 6px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.4;
      display: none;
      white-space: nowrap;
      box-shadow: 0 4px 16px rgba(0,0,0,0.35);
    }

    .legend {
      margin-top: 10px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 12px;
      color: #cbd5e1;
    }

    .legend-bar {
      width: 240px;
      height: 12px;
      border-radius: 4px;
      border: 1px solid #334155;
      background: linear-gradient(to right, #7f1d1d, #ef4444, #e2e8f0, #22c55e, #14532d);
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Real-Time Stock Price Heatmap</h1>
    <div id="chart" class="chart-wrap"></div>
    <div class="legend">
      <span>Negative</span>
      <div class="legend-bar"></div>
      <span>Positive</span>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA", "META", "NFLX",
      "AMD", "INTC", "ORCL", "IBM", "CRM", "UBER", "SHOP", "BABA",
      "JPM", "BAC", "GS", "V", "MA", "PYPL", "DIS", "KO"
    ];

    const timeWindow = 120; // number of columns visible in data history
    const updateIntervalMs = 1000;

    const basePrices = new Map(
      symbols.map(s => [s, 50 + Math.random() * 250])
    );

    const data = [];
    let currentTime = new Date();

    function generateSnapshot(ts) {
      return symbols.map(symbol => {
        const prev = basePrices.get(symbol);
        const drift = (Math.random() - 0.5) * 2.5;
        const next = Math.max(5, prev + drift);
        basePrices.set(symbol, next);

        return {
          symbol,
          time: new Date(ts),
          price: +next.toFixed(2),
          change: +(((next - prev) / prev) * 100).toFixed(3)
        };
      });
    }

    for (let i = timeWindow - 1; i >= 0; i--) {
      const ts = new Date(currentTime.getTime() - i * updateIntervalMs);
      data.push(...generateSnapshot(ts));
    }

    const container = document.getElementById("chart");
    const width = container.clientWidth;
    const height = container.clientHeight;

    const margin = { top: 20, right: 20, bottom: 40, left: 80 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const canvas = d3.select(container)
      .append("canvas")
      .attr("width", width * devicePixelRatio)
      .attr("height", height * devicePixelRatio)
      .style("width", `${width}px`)
      .style("height", `${height}px`);

    const ctx = canvas.node().getContext("2d");
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const svg = d3.select(container)
      .append("svg")
      .attr("class", "overlay")
      .attr("width", width)
      .attr("height", height);

    const plot = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const xAxisG = plot.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${innerHeight})`);

    const yAxisG = plot.append("g")
      .attr("class", "axis");

    const tooltip = d3.select(container)
      .append("div")
      .attr("class", "tooltip");

    function getTimeColumns() {
      const times = Array.from(new Set(data.map(d => +d.time)))
        .sort((a, b) => a - b)
        .map(t => new Date(t));
      return times;
    }

    let timeColumns = getTimeColumns();

    let xScale = d3.scaleBand()
      .domain(timeColumns.map(d => +d))
      .range([0, innerWidth])
      .paddingInner(0.02)
      .paddingOuter(0);

    let yScale = d3.scaleBand()
      .domain(symbols)
      .range([0, innerHeight])
      .paddingInner(0.04)
      .paddingOuter(0);

    const colorScale = d3.scaleLinear()
      .domain([-2, -0.5, 0, 0.5, 2])
      .range(["#7f1d1d", "#ef4444", "#e2e8f0", "#22c55e", "#14532d"])
      .clamp(true);

    let transform = d3.zoomIdentity;

    function draw() {
      ctx.clearRect(0, 0, width, height);

      ctx.save();
      ctx.translate(margin.left, margin.top);

      const zx = transform.rescaleX(
        d3.scaleLinear()
          .domain([0, innerWidth])
          .range([0, innerWidth])
      );

      const visibleX0 = zx.invert(0);
      const visibleX1 = zx.invert(innerWidth);

      const colWidth = xScale.bandwidth();
      const rowHeight = yScale.bandwidth();

      for (const d of data) {
        const baseX = xScale(+d.time);
        const baseY = yScale(d.symbol);

        if (baseX == null || baseY == null) continue;

        const x = zx(baseX);
        const w = colWidth * transform.k;

        if (x + w < 0 || x > innerWidth) continue;
        if (baseX < visibleX0 - colWidth || baseX > visibleX1 + colWidth) continue;

        ctx.fillStyle = colorScale(d.change);
        ctx.fillRect(x, baseY, Math.max(1, w), rowHeight);
      }

      ctx.restore();

      const tickCount = Math.max(4, Math.floor(innerWidth / 100));
      const xLinear = d3.scaleLinear()
        .domain([0, innerWidth])
        .range([0, innerWidth]);

      const zxAxis = transform.rescaleX(xLinear);
      const visibleTimes = timeColumns.map(d => +d);
      const minT = d3.min(visibleTimes);
      const maxT = d3.max(visibleTimes);

      const axisScale = d3.scaleTime()
        .domain([
          new Date(minT + (zxAxis.invert(0) / innerWidth) * (maxT - minT)),
          new Date(minT + (zxAxis.invert(innerWidth) / innerWidth) * (maxT - minT))
        ])
        .range([0, innerWidth]);

      xAxisG.call(
        d3.axisBottom(axisScale)
          .ticks(tickCount)
          .tickFormat(d3.timeFormat("%H:%M:%S"))
      );

      yAxisG.call(d3.axisLeft(yScale));
    }

    function updateData() {
      currentTime = new Date(currentTime.getTime() + updateIntervalMs);
      data.push(...generateSnapshot(currentTime));

      const cutoff = currentTime.getTime() - (timeWindow - 1) * updateIntervalMs;
      for (let i = data.length - 1; i >= 0; i--) {
        if (+data[i].time < cutoff) {
          data.splice(i, 1);
        }
      }

      timeColumns = getTimeColumns();
      xScale.domain(timeColumns.map(d => +d));

      draw();
    }

    function getCellFromMouse(mx, my) {
      const px = mx - margin.left;
      const py = my - margin.top;

      if (px < 0 || px > innerWidth || py < 0 || py > innerHeight) return null;

      const zx = transform.rescaleX(
        d3.scaleLinear().domain([0, innerWidth]).range([0, innerWidth])
      );

      const colWidth = xScale.bandwidth();
      const rowHeight = yScale.bandwidth();

      const symbol = symbols.find(s => {
        const y = yScale(s);
        return py >= y && py <= y + rowHeight;
      });

      if (!symbol) return null;

      let matched = null;

      for (const t of timeColumns) {
        const baseX = xScale(+t);
        const x = zx(baseX);
        const w = colWidth * transform.k;

        if (px >= x && px <= x + w) {
          matched = +t;
          break;
        }
      }

      if (matched == null) return null;

      return data.find(d => d.symbol === symbol && +d.time === matched) || null;
    }

    svg.on("mousemove", function(event) {
      const [mx, my] = d3.pointer(event, this);
      const cell = getCellFromMouse(mx, my);

      if (!cell) {
        tooltip.style("display", "none");
        return;
      }

      tooltip
        .style("display", "block")
        .style("left", `${mx + 14}px`)
        .style("top", `${my + 14}px`)
        .html(`
          <strong>${cell.symbol}</strong><br/>
          Time: ${d3.timeFormat("%H:%M:%S")(cell.time)}<br/>
          Price: $${cell.price.toFixed(2)}<br/>
          Change: <span style="color:${cell.change >= 0 ? "#4ade80" : "#f87171"}">
            ${cell.change.toFixed(3)}%
          </span>
        `);
    });

    svg.on("mouseleave", () => {
      tooltip.style("display", "none");
    });

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        transform = event.transform;
        draw();
      });

    svg.call(zoom);

    draw();
    setInterval(updateData, updateIntervalMs);

    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
```

