      <div class="status" id="status">Running</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmapCanvas"></canvas>
      <svg class="overlay" id="overlay"></svg>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const overlay = d3.select("#overlay");
    const chartWrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");

    const symbolCountEl = document.getElementById("symbolCount");
    const timeBucketsEl = document.getElementById("timeBuckets");
    const updateIntervalEl = document.getElementById("updateInterval");
    const toggleUpdatesEl = document.getElementById("toggleUpdates");
    const resetZoomEl = document.getElementById("resetZoom");
    const regenerateEl = document.getElementById("regenerate");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 20, bottom: 30, left: 90 };

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;
    let dpr = window.devicePixelRatio || 1;

    let symbols = [];
    let timestamps = [];
    let data = []; // 2D array: rows=symbols, cols=time buckets
    let basePrices = new Map();

    let timer = null;
    let running = true;

    let transform = d3.zoomIdentity;

    const colorScale = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#7f1d1d", "#dc2626", "#f59e0b", "#16a34a", "#14532d"])
      .clamp(true);

    function generateSymbols(n) {
      const pool = [
        "AAPL","MSFT","GOOG","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
        "ORCL","CRM","UBER","SHOP","PYPL","ADBE","QCOM","AVGO","CSCO","IBM",
        "BABA","SONY","SAP","SQ","PLTR","SNOW","ZM","DOCU","COIN","ROKU",
        "DIS","PEP","KO","NKE","MCD","WMT","COST","TGT","JPM","GS",
        "BAC","V","MA","AXP","XOM","CVX","BA","GE","CAT","F"
      ];
      if (n <= pool.length) return pool.slice(0, n);
      return Array.from({ length: n }, (_, i) => `SYM${i + 1}`);
    }

    function generateInitialData(symbolCount, bucketCount) {
      symbols = generateSymbols(symbolCount);
      timestamps = Array.from({ length: bucketCount }, (_, i) => {
        const now = Date.now();
        return now - (bucketCount - 1 - i) * 60_000;
      });

      basePrices = new Map();
      data = symbols.map(symbol => {
        const base = 50 + Math.random() * 450;
        basePrices.set(symbol, base);

        let current = base;
        const row = [];
        for (let i = 0; i < bucketCount; i++) {
          current *= 1 + (Math.random() - 0.5) * 0.01;
          const pctChange = ((current - base) / base) * 100;
          row.push({
            symbol,
            timestamp: timestamps[i],
            price: current,
            pctChange
          });
        }
        return row;
      });
    }

    function pushRealtimeUpdate() {
      const nextTimestamp = (timestamps[timestamps.length - 1] || Date.now()) + 60_000;
      timestamps.push(nextTimestamp);

      for (let r = 0; r < symbols.length; r++) {
        const symbol = symbols[r];
        const row = data[r];
        const prev = row[row.length - 1];
        const base = basePrices.get(symbol);

        const drift = (Math.random() - 0.5) * 0.012;
        const nextPrice = prev.price * (1 + drift);
        const pctChange = ((nextPrice - base) / base) * 100;

        row.push({
          symbol,
          timestamp: nextTimestamp,
          price: nextPrice,
          pctChange
        });

        if (row.length > +timeBucketsEl.value) {
          row.shift();
        }
      }

      if (timestamps.length > +timeBucketsEl.value) {
        timestamps.shift();
      }

      draw();
    }

    function resize() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      overlay.attr("width", width).attr("height", height);

      draw();
    }

    function getBaseScales() {
      const x = d3.scaleLinear()
        .domain([0, timestamps.length])
        .range([margin.left, margin.left + innerWidth]);

      const y = d3.scaleLinear()
        .domain([0, symbols.length])
        .range([margin.top, margin.top + innerHeight]);

      return { x, y };
    }

    function drawAxes(xScale, yScale) {
      ctx.save();
      ctx.strokeStyle = "#334155";
      ctx.fillStyle = "#cbd5e1";
      ctx.lineWidth = 1;
      ctx.font = "12px Inter, Arial, sans-serif";

      // Border
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);

      // Y labels
      const yStep = Math.max(1, Math.ceil(symbols.length / Math.max(1, innerHeight / 24)));
      for (let i = 0; i < symbols.length; i += yStep) {
        const y0 = yScale(i);
        const y1 = yScale(i + 1);
        const y = (y0 + y1) / 2;

        ctx.fillStyle = "#cbd5e1";
        ctx.textAlign = "right";
        ctx.textBaseline = "middle";
        ctx.fillText(symbols[i], margin.left - 8, y);

        ctx.strokeStyle = "rgba(51, 65, 85, 0.25)";
        ctx.beginPath();
        ctx.moveTo(margin.left, y0);
        ctx.lineTo(margin.left + innerWidth, y0);
        ctx.stroke();
      }

      // X labels
      const visibleCols = Math.max(1, Math.floor((xScale(timestamps.length) - xScale(0)) / 80));
      const xStep = Math.max(1, Math.ceil(timestamps.length / visibleCols));

      for (let i = 0; i < timestamps.length; i += xStep) {
        const x0 = xScale(i);
        const label = new Date(timestamps[i]).toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit"
        });

        ctx.save();
        ctx.translate(x0 + 4, margin.top + innerHeight + 6);
        ctx.rotate(Math.PI / 4);
        ctx.fillStyle = "#94a3b8";
        ctx.textAlign = "left";
        ctx.textBaseline = "top";
        ctx.fillText(label, 0, 0);
        ctx.restore();

        ctx.strokeStyle = "rgba(51, 65, 85, 0.25)";
        ctx.beginPath();
        ctx.moveTo(x0, margin.top);
        ctx.lineTo(x0, margin.top + innerHeight);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawHeatmap(xScale, yScale) {
      ctx.save();

      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      for (let r = 0; r < data.length; r++) {
        const row = data[r];
        for (let c = 0; c < row.length; c++) {
          const cell = row[c];
          const x0 = xScale(c);
          const x1 = xScale(c + 1);
          const y0 = yScale(r);
          const y1 = yScale(r + 1);

          const w = x1 - x0;
          const h = y1 - y0;

          if (x1 < margin.left || x0 > margin.left + innerWidth) continue;
          if (y1 < margin.top || y0 > margin.top + innerHeight) continue;
          if (w <= 0 || h <= 0) continue;

          ctx.fillStyle = colorScale(cell.pctChange);
          ctx.fillRect(x0, y0, w, h);

          if (w > 8 && h > 8) {
            ctx.strokeStyle = "rgba(15, 23, 42, 0.25)";
            ctx.strokeRect(x0, y0, w, h);
          }
        }
      }

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      const { x: baseX, y: baseY } = getBaseScales();
      const xScale = transform.rescaleX(baseX);
      const yScale = transform.rescaleY(baseY);

      drawHeatmap(xScale, yScale);
      drawAxes(xScale, yScale);
    }

    function getCellAtPoint(px, py) {
      const { x: baseX, y: baseY } = getBaseScales();
      const xScale = transform.rescaleX(baseX);
      const yScale = transform.rescaleY(baseY);

      if (
        px < margin.left ||
        px > margin.left + innerWidth ||
        py < margin.top ||
        py > margin.top + innerHeight
      ) {
        return null;
      }

      const col = Math.floor(xScale.invert(px));
      const row = Math.floor(yScale.invert(py));

      if (row < 0 || row >= data.length) return null;
      if (col < 0 || col >= timestamps.length) return null;

      const cell = data[row][col];
      if (!cell) return null;

      return { row, col, cell };
    }

    function setupInteractions() {
      const zoom = d3.zoom()
        .scaleExtent([1, 20])
        .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .on("zoom", (event) => {
          transform = event.transform;
          draw();
        });

      overlay.call(zoom);

      resetZoomEl.onclick = () => {
        overlay.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
      };

      overlay.on("mousemove", (event) => {
        const [mx, my] = d3.pointer(event);
        const hit = getCellAtPoint(mx, my);

        if (!hit) {
          tooltip.style.opacity = 0;
          return;
        }

        const { cell } = hit;
        tooltip.style.opacity = 1;
        tooltip.style.left = `${mx + 12}px`;
        tooltip.style.top = `${my + 12}px`;
        tooltip.innerHTML = `
          <strong>${cell.symbol}</strong><br/>
          Time: ${new Date(cell.timestamp).toLocaleTimeString()}<br/>
          Price: $${cell.price.toFixed(2)}<br/>
          Change: <span style="color:${colorScale(cell.pctChange)}">${cell.pctChange.toFixed(2)}%</span>
        `;
      });

      overlay.on("mouseleave", () => {
        tooltip.style.opacity = 0;
      });
    }

    function startUpdates() {
      stopUpdates();
      const interval = Math.max(100, +updateIntervalEl.value || 500);
      timer = setInterval(() => {
        if (running) pushRealtimeUpdate();
      }, interval);
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    function rebuild() {
      generateInitialData(+symbolCountEl.value, +timeBucketsEl.value);
      transform = d3.zoomIdentity;
      draw();
      startUpdates();
    }

    toggleUpdatesEl.onclick = () => {
      running = !running;
      toggleUpdatesEl.textContent = running ? "Pause" : "Resume";
      statusEl.textContent = running ? "Running" : "Paused";
    };

    regenerateEl.onclick = rebuild;
    symbolCountEl.onchange = rebuild;
    timeBucketsEl.onchange = rebuild;
    updateIntervalEl.onchange = startUpdates;

    window.addEventListener("resize", resize);

    generateInitialData(+symbolCountEl.value, +timeBucketsEl.value);
    resize();
    setupInteractions();
    startUpdates();
  </script>
</body>
</html>
```

