    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
      "ORCL","CRM","ADBE","PYPL","UBER","SHOP","SNOW","PLTR","BABA","JPM",
      "BAC","GS","MS","V","MA","DIS","KO","PEP","WMT","COST"
    ];

    const timeSteps = 120; // number of columns
    const updateIntervalMs = 1000;

    const margin = { top: 20, right: 20, bottom: 40, left: 80 };

    const chartEl = document.getElementById("chart");
    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetZoomBtn = document.getElementById("resetZoom");
    const pauseBtn = document.getElementById("pauseBtn");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let live = true;

    // Generate initial data
    // Each row is a symbol, each column is a time bucket with price and pct change
    let data = symbols.map(symbol => {
      let base = 80 + Math.random() * 220;
      let row = [];
      let prev = base;
      for (let i = 0; i < timeSteps; i++) {
        const drift = (Math.random() - 0.5) * 2.5;
        const price = Math.max(5, prev + drift);
        const pct = ((price - base) / base) * 100;
        row.push({
          symbol,
          timeIndex: i,
          timestamp: Date.now() - (timeSteps - i) * updateIntervalMs,
          price,
          pct
        });
        prev = price;
      }
      return row;
    });

    const xBase = d3.scaleBand().domain(d3.range(timeSteps)).paddingInner(0.02);
    const yBase = d3.scaleBand().domain(symbols).paddingInner(0.04);

    let xScale = xBase.copy();
    let yScale = yBase.copy();

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#1e293b", "#22c55e", "#14532d"])
      .clamp(true);

    const xAxisG = svg.append("g").attr("class", "axis x-axis");
    const yAxisG = svg.append("g").attr("class", "axis y-axis");
    const gridG = svg.append("g").attr("class", "grid");

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [20000, 20000]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function resize() {
      width = chartEl.clientWidth;
      height = chartEl.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      canvas.width = width * devicePixelRatio;
      canvas.height = height * devicePixelRatio;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);

      svg.attr("width", width).attr("height", height);

      xBase.range([margin.left, margin.left + innerWidth]);
      yBase.range([margin.top, margin.top + innerHeight]);

      xScale.range(xBase.range());
      yScale.range(yBase.range());

      draw();
    }

    function drawAxes() {
      const visibleXTicks = xScale.domain().filter((d, i) => {
        const bw = xScale.bandwidth();
        return bw > 18 ? true : i % Math.ceil(18 / Math.max(1, bw)) === 0;
      });

      const xAxis = d3.axisBottom(xScale)
        .tickValues(visibleXTicks)
        .tickFormat(d => {
          const point = data[0][d];
          const date = new Date(point.timestamp);
          return d3.timeFormat("%H:%M:%S")(date);
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG
        .attr("transform", `translate(0, ${margin.top + innerHeight})`)
        .call(xAxis);

      yAxisG
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);
    }

    function drawGrid() {
      gridG.selectAll("*").remove();

      const xTicks = xScale.domain();
      const yTicks = yScale.domain();

      gridG.attr("opacity", 0.15);

      gridG.selectAll(".vline")
        .data(xTicks)
        .enter()
        .append("line")
        .attr("x1", d => xScale(d))
        .attr("x2", d => xScale(d))
        .attr("y1", margin.top)
        .attr("y2", margin.top + innerHeight)
        .attr("stroke", "#94a3b8");

      gridG.selectAll(".hline")
        .data(yTicks)
        .enter()
        .append("line")
        .attr("x1", margin.left)
        .attr("x2", margin.left + innerWidth)
        .attr("y1", d => yScale(d))
        .attr("y2", d => yScale(d))
        .attr("stroke", "#94a3b8");
    }

    function drawHeatmap() {
      ctx.clearRect(0, 0, width, height);

      for (let r = 0; r < symbols.length; r++) {
        const symbol = symbols[r];
        const y = yScale(symbol);
        const h = yScale.bandwidth();

        if (y == null || h <= 0) continue;
        if (y + h < margin.top || y > margin.top + innerHeight) continue;

        for (let c = 0; c < timeSteps; c++) {
          const x = xScale(c);
          const w = xScale.bandwidth();
          if (x == null || w <= 0) continue;
          if (x + w < margin.left || x > margin.left + innerWidth) continue;

          const cell = data[r][c];
          ctx.fillStyle = colorScale(cell.pct);
          ctx.fillRect(x, y, w, h);
        }
      }

      // Border around plotting area
      ctx.strokeStyle = "#475569";
      ctx.lineWidth = 1;
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);
    }

    function draw() {
      drawHeatmap();
      drawAxes();
      drawGrid();
    }

    function zoomed(event) {
      const t = event.transform;

      const zx = t.rescaleX(d3.scaleLinear()
        .domain([0, timeSteps])
        .range([margin.left, margin.left + innerWidth]));

      const zy = t.rescaleY(d3.scaleLinear()
        .domain([0, symbols.length])
        .range([margin.top, margin.top + innerHeight]));

      const xPositions = d3.range(timeSteps).map(i => zx(i));
      const xNextPositions = d3.range(timeSteps).map(i => zx(i + 1));
      const yPositions = d3.range(symbols.length).map(i => zy(i));
      const yNextPositions = d3.range(symbols.length).map(i => zy(i + 1));

      xScale = d3.scaleBand()
        .domain(d3.range(timeSteps))
        .range([xPositions[0], xNextPositions[timeSteps - 1]])
        .paddingInner(0.02);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([yPositions[0], yNextPositions[symbols.length - 1]])
        .paddingInner(0.04);

      draw();
    }

    function updateData() {
      const now = Date.now();

      data = data.map(row => {
        const last = row[row.length - 1];
        const newPrice = Math.max(5, last.price + (Math.random() - 0.5) * 4);
        const base = row[0].price;
        const pct = ((newPrice - base) / base) * 100;

        const shifted = row.slice(1);
        shifted.push({
          symbol: last.symbol,
          timeIndex: timeSteps - 1,
          timestamp: now,
          price: newPrice,
          pct
        });

        // Reindex timeIndex
        for (let i = 0; i < shifted.length; i++) {
          shifted[i].timeIndex = i;
        }

        return shifted;
      });

      draw();
    }

    function getCellAt(mx, my) {
      if (
        mx < margin.left ||
        mx > margin.left + innerWidth ||
        my < margin.top ||
        my > margin.top + innerHeight
      ) {
        return null;
      }

      let foundRow = null;
      let foundCol = null;

      for (let i = 0; i < symbols.length; i++) {
        const s = symbols[i];
        const y = yScale(s);
        const h = yScale.bandwidth();
        if (my >= y && my <= y + h) {
          foundRow = i;
          break;
        }
      }

      for (let j = 0; j < timeSteps; j++) {
        const x = xScale(j);
        const w = xScale.bandwidth();
        if (mx >= x && mx <= x + w) {
          foundCol = j;
          break;
        }
      }

      if (foundRow == null || foundCol == null) return null;
      return data[foundRow][foundCol];
    }

    svg.on("mousemove", function(event) {
      const [mx, my] = d3.pointer(event, this);
      const cell = getCellAt(mx, my);

      if (!cell) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = `${mx + 18}px`;
      tooltip.style.top = `${my + 18}px`;

      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: ${cell.pct.toFixed(2)}%</div>
        <div>Time: ${new Date(cell.timestamp).toLocaleTimeString()}</div>
      `;
    });

    svg.on("mouseleave", function() {
      tooltip.style.display = "none";
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    pauseBtn.addEventListener("click", () => {
      live = !live;
      pauseBtn.textContent = live ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = `Live updates: ${live ? "ON" : "OFF"}`;
    });

    setInterval(() => {
      if (live) updateData();
    }, updateIntervalMs);

    window.addEventListener("resize", resize);

    resize();
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each stock has a row of time-series cells:

```js
{
  symbol,
  timeIndex,
  timestamp,
  price,
  pct
}
```

The heatmap color is based on `pct`, the percentage change from the row’s initial base price.

### Rendering
- The heatmap itself is drawn on a `<canvas>` for speed.
- Axes and interaction layer are handled with `<svg>` and D3.

### Zoom/pan
D3 zoom transforms the visible coordinate system, and the heatmap is redrawn using updated scales.

### Real-time updates
Every second:
- oldest column is removed
- newest price is appended
- chart redraws

