  </style>
</head>
<body>
  <div class="app">
    <div class="header">
      <div class="title">Real-Time Stock Price Heatmap</div>
      <div class="controls">
        <button id="toggleUpdates">Pause Updates</button>
        <button id="resetZoom">Reset Zoom</button>
        <button id="randomize">Randomize</button>
        <div class="status" id="status">Live updates running</div>
      </div>
    </div>

    <div class="legend">
      <span>-5%</span>
      <div class="legend-bar"></div>
      <span>+5%</span>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <svg id="heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="footer">
      <div class="hint">Mouse wheel to zoom, drag to pan, hover cells for details.</div>
      <div class="hint">Color encodes percent change from baseline price.</div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "CRM", "ORCL", "IBM", "UBER", "SHOP",
      "BABA", "PYPL", "SQ", "ADBE", "SNOW"
    ];

    const timeSteps = 60;
    const updateIntervalMs = 1000;

    const baselinePrices = new Map();
    const currentPrices = new Map();

    symbols.forEach(symbol => {
      const base = 50 + Math.random() * 450;
      baselinePrices.set(symbol, base);
      currentPrices.set(symbol, base);
    });

    function formatTime(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function nextPrice(symbol) {
      const current = currentPrices.get(symbol);
      const drift = (Math.random() - 0.5) * current * 0.01;
      const meanReversion = (baselinePrices.get(symbol) - current) * 0.01;
      const next = Math.max(1, current + drift + meanReversion);
      currentPrices.set(symbol, next);
      return next;
    }

    let now = new Date();
    let data = [];

    function initializeData() {
      const start = new Date(now.getTime() - (timeSteps - 1) * updateIntervalMs);
      data = symbols.flatMap(symbol => {
        let price = baselinePrices.get(symbol);
        return d3.range(timeSteps).map(i => {
          const time = new Date(start.getTime() + i * updateIntervalMs);
          price = Math.max(1, price + (Math.random() - 0.5) * price * 0.01);
          currentPrices.set(symbol, price);
          const baseline = baselinePrices.get(symbol);
          const changePct = ((price - baseline) / baseline) * 100;
          return { symbol, time, price, changePct };
        });
      });
    }

    initializeData();

    const svg = d3.select("#heatmap");
    const tooltip = d3.select("#tooltip");
    const chartWrap = document.getElementById("chartWrap");

    const margin = { top: 20, right: 20, bottom: 60, left: 80 };

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    const root = svg.append("g");
    const plot = root.append("g").attr("class", "plot");
    const cellsLayer = plot.append("g").attr("class", "cells");
    const xAxisG = root.append("g").attr("class", "axis x-axis");
    const yAxisG = root.append("g").attr("class", "axis y-axis");

    const xScaleBase = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    const yScaleBase = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);

    let xScale = xScaleBase.copy();
    let yScale = yScaleBase.copy();

    const colorScale = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#7f1d1d", "#ef4444", "#f8fafc", "#22c55e", "#14532d"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;
    let updatesRunning = true;

    function getTimes() {
      return Array.from(new Set(data.map(d => +d.time)))
        .sort((a, b) => a - b)
        .map(t => new Date(t));
    }

    function resize() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      root.attr("transform", `translate(${margin.left},${margin.top})`);
      xAxisG.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisG.attr("transform", `translate(${margin.left},${margin.top})`);

      render();
    }

    function updateScales() {
      const times = getTimes().map(t => +t);
      xScaleBase.domain(times).range([0, innerWidth]);
      yScaleBase.domain(symbols).range([0, innerHeight]);

      const zx = currentTransform.rescaleX(
        d3.scaleLinear()
          .domain([0, innerWidth])
          .range([0, innerWidth])
      );

      const zy = currentTransform.rescaleY(
        d3.scaleLinear()
          .domain([0, innerHeight])
          .range([0, innerHeight])
      );

      const x0 = zx.domain()[0];
      const x1 = zx.domain()[1];
      const y0 = zy.domain()[0];
      const y1 = zy.domain()[1];

      xScale = xScaleBase.copy().range([
        x0,
        x1
      ]);

      yScale = yScaleBase.copy().range([
        y0,
        y1
      ]);
    }

    function renderAxes() {
      const times = getTimes();
      const visibleTimes = times.filter(t => {
        const x = xScale(+t);
        return x !== undefined && x + xScale.bandwidth() >= 0 && x <= innerWidth;
      });

      const xTickValues = visibleTimes.filter((_, i) => {
        const approxCount = Math.max(1, Math.floor(visibleTimes.length / 8));
        return i % approxCount === 0;
      });

      const xAxis = d3.axisBottom(
        d3.scalePoint()
          .domain(xTickValues.map(d => +d))
          .range([
            xTickValues.length ? xScale(+xTickValues[0]) + xScale.bandwidth() / 2 : 0,
            xTickValues.length ? xScale(+xTickValues[xTickValues.length - 1]) + xScale.bandwidth() / 2 : innerWidth
          ])
      )
      .tickFormat(d => formatTime(new Date(+d)));

      const yAxis = d3.axisLeft(
        d3.scalePoint()
          .domain(symbols)
          .range([
            yScale(symbols[0]) + yScale.bandwidth() / 2,
            yScale(symbols[symbols.length - 1]) + yScale.bandwidth() / 2
          ])
      );

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);

      xAxisG.selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      xAxisG.selectAll("path,line").attr("stroke", "#334155");
      yAxisG.selectAll("path,line").attr("stroke", "#334155");
    }

    function renderCells() {
      const join = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${+d.time}`);

      join.enter()
        .append("rect")
        .attr("class", "cell")
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .style("left", `${event.offsetX + 12}px`)
            .style("top", `${event.offsetY + 12}px`)
            .html(`
              <div><strong>${d.symbol}</strong></div>
              <div>Time: ${formatTime(d.time)}</div>
              <div>Price: $${d.price.toFixed(2)}</div>
              <div>Change: <span style="color:${colorScale(d.changePct)}">${d.changePct.toFixed(2)}%</span></div>
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        })
        .merge(join)
        .attr("x", d => xScale(+d.time))
        .attr("y", d => yScale(d.symbol))
        .attr("width", Math.max(0, xScale.bandwidth()))
        .attr("height", Math.max(0, yScale.bandwidth()))
        .attr("fill", d => colorScale(clamp(d.changePct, -5, 5)));

      join.exit().remove();
    }

    function render() {
      updateScales();
      renderCells();
      renderAxes();
    }

    function pushLiveUpdate() {
      now = new Date();
      const cutoff = new Date(now.getTime() - (timeSteps - 1) * updateIntervalMs);

      const newPoints = symbols.map(symbol => {
        const price = nextPrice(symbol);
        const baseline = baselinePrices.get(symbol);
        const changePct = ((price - baseline) / baseline) * 100;
        return {
          symbol,
          time: new Date(now),
          price,
          changePct
        };
      });

      data = data
        .filter(d => d.time >= cutoff)
        .concat(newPoints);

      render();
    }

    function randomizeData() {
      symbols.forEach(symbol => {
        const base = 50 + Math.random() * 450;
        baselinePrices.set(symbol, base);
        currentPrices.set(symbol, base);
      });
      now = new Date();
      initializeData();
      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("toggleUpdates").addEventListener("click", (e) => {
      updatesRunning = !updatesRunning;
      e.target.textContent = updatesRunning ? "Pause Updates" : "Resume Updates";
      document.getElementById("status").textContent = updatesRunning
        ? "Live updates running"
        : "Live updates paused";
    });

    document.getElementById("randomize").addEventListener("click", () => {
      randomizeData();
    });

    window.addEventListener("resize", resize);

    resize();

    setInterval(() => {
      if (updatesRunning) {
        pushLiveUpdate();
      }
    }, updateIntervalMs);
  </script>
</body>
</html>
```

