## Optional: WebSocket update stub

Here is a simple replacement pattern for live updates:

```js
const socket = new WebSocket("wss://your-feed.example.com/stocks");

socket.onmessage = (event) => {
  const incoming = JSON.parse(event.data);
  // Example:
  // [{ symbol: "AAPL", price: 192.31, time: "2026-01-01T12:00:00Z" }]

  const latestTime = new Date();

  const newPoints = incoming.map(item => {
    currentPrices.set(item.symbol, item.price);
    const baseline = baselinePrices.get(item.symbol) ?? item.price;
    if (!baselinePrices.has(item.symbol)) baselinePrices.set(item.symbol, item.price);

    return {
      symbol: item.symbol,
      time: new Date(item.time || latestTime),
      price: item.price,
      changePct: ((item.price - baseline) / baseline) * 100
    };
  });

  const cutoff = new Date(Date.now() - (timeSteps - 1) * updateIntervalMs);
  data = data.filter(d => d.time >= cutoff).concat(newPoints);
  render();
};
```

