  <script>
    const svg = d3.select("svg");
    const chart = document.getElementById("chart");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");
    const pauseBtn = document.getElementById("pauseBtn");
    const resetZoomBtn = document.getElementById("resetZoomBtn");
    const speedSelect = document.getElementById("speedSelect");

    let width = chart.clientWidth;
    let height = chart.clientHeight;

    const root = svg.append("g");
    const heatmapLayer = root.append("g");

    const rows = 10;
    const cols = 12;
    const total = rows * cols;

    const symbols = [
      "AAPL","MSFT","GOOG","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC","ORCL","IBM",
      "JPM","BAC","WFC","GS","MS","C","V","MA","PYPL","AXP","BLK","SCHW",
      "XOM","CVX","COP","SLB","BP","TTE","PBR","SHEL","EOG","MPC","PSX","VLO",
      "JNJ","PFE","MRK","ABBV","LLY","BMY","UNH","CVS","TMO","DHR","MDT","AMGN",
      "KO","PEP","MCD","SBUX","NKE","COST","WMT","TGT","HD","LOW","PG","CL",
      "BA","CAT","DE","GE","HON","MMM","LMT","RTX","UPS","FDX","UNP","CSX",
      "DIS","CMCSA","TMUS","VZ","T","CHTR","SPOT","SONY","EA","UBER","LYFT","ABNB",
      "CRM","ADBE","NOW","INTU","QCOM","AVGO","TXN","MU","SHOP","SQ","SNOW","PLTR",
      "F","GM","RIVN","LCID","NIO","BABA","JD","PDD","SE","MELI","SAP","ASML",
      "UBS","HSBC","SAN","DB","BNP","ING","RIO","BHP","VALE","GLEN","NEM","FCX"
    ].slice(0, total);

    let data = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      return {
        id: i,
        symbol,
        row: Math.floor(i / cols),
        col: i % cols,
        price: base,
        open: base,
        changePct: 0
      };
    });

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#1f2937", "#22c55e", "#14532d"])
      .clamp(true);

    function getCellSize() {
      return {
        cellWidth: width / cols,
        cellHeight: height / rows
      };
    }

    function render() {
      width = chart.clientWidth;
      height = chart.clientHeight;
      svg.attr("viewBox", `0 0 ${width} ${height}`);

      const { cellWidth, cellHeight } = getCellSize();

      const cells = heatmapLayer.selectAll(".stock")
        .data(data, d => d.symbol);

      const enter = cells.enter()
        .append("g")
        .attr("class", "stock");

      enter.append("rect")
        .attr("class", "cell")
        .attr("rx", 4)
        .attr("ry", 4);

      enter.append("text")
        .attr("class", "label");

      const merged = enter.merge(cells);

      merged.attr("transform", d => `translate(${d.col * cellWidth}, ${d.row * cellHeight})`);

      merged.select("rect")
        .transition()
        .duration(250)
        .attr("width", Math.max(0, cellWidth - 2))
        .attr("height", Math.max(0, cellHeight - 2))
        .attr("fill", d => colorScale(d.changePct));

      merged.select("text")
        .attr("x", cellWidth / 2)
        .attr("y", cellHeight / 2)
        .style("font-size", `${Math.max(9, Math.min(cellWidth, cellHeight) * 0.16)}px`)
        .text(d => {
          if (cellWidth < 55 || cellHeight < 28) return "";
          return `${d.symbol} ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(1)}%`;
        });

      merged
        .on("mousemove", function(event, d) {
          const [mx, my] = d3.pointer(event, chart);
          tooltip
            .style("left", `${mx}px`)
            .style("top", `${my}px`)
            .style("opacity", 1)
            .html(`
              <div><strong>${d.symbol}</strong></div>
              <div>Price: $${d.price.toFixed(2)}</div>
              <div>Open: $${d.open.toFixed(2)}</div>
              <div>Change: <span style="color:${d.changePct >= 0 ? "#4ade80" : "#f87171"}">
                ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
              </span></div>
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        });

      cells.exit().remove();
    }

    function updateData() {
      data.forEach(d => {
        const drift = (Math.random() - 0.5) * 0.02;
        d.price *= (1 + drift);
        d.changePct = ((d.price - d.open) / d.open) * 100;
      });
      render();
    }

    let intervalMs = Number(speedSelect.value);
    let timer = null;
    let paused = false;

    function startUpdates() {
      stopUpdates();
      timer = setInterval(() => {
        if (!paused) updateData();
      }, intervalMs);
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
    }

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
      statusEl.textContent = paused ? "Live updates paused" : "Live updates running";
    });

    speedSelect.addEventListener("change", () => {
      intervalMs = Number(speedSelect.value);
      startUpdates();
    });

    const zoom = d3.zoom()
      .scaleExtent([0.5, 8])
      .translateExtent([[-width, -height], [width * 2, height * 2]])
      .on("zoom", (event) => {
        root.attr("transform", event.transform);
      });

    svg.call(zoom);

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", () => {
      render();
    });

    render();
    startUpdates();
  </script>
