          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const wrapper = document.getElementById("chartWrapper");
    const tooltip = document.getElementById("tooltip");
    const toggleBtn = document.getElementById("toggleStream");
    const resetZoomBtn = document.getElementById("resetZoom");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 30, bottom: 60, left: 80 };

    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP"
    ];

    const timeSteps = 60; // columns in heatmap
    const updateIntervalMs = 1000;

    let isStreaming = true;
    let streamTimer = null;

    // Initialize synthetic data
    let data = [];
    let timestamps = [];

    function nowLabel(offset = 0) {
      const d = new Date(Date.now() + offset);
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }

    function initializeData() {
      timestamps = [];
      data = [];

      for (let t = timeSteps - 1; t >= 0; t--) {
        timestamps.push(nowLabel(-t * updateIntervalMs));
      }

      stocks.forEach(stock => {
        let base = 100 + Math.random() * 200;
        for (let t = 0; t < timeSteps; t++) {
          const drift = (Math.random() - 0.5) * 2;
          base += drift;
          const pctChange = Math.max(-5, Math.min(5, ((Math.random() - 0.5) * 10)));
          data.push({
            stock,
            timeIndex: t,
            timeLabel: timestamps[t],
            price: +base.toFixed(2),
            changePct: +pctChange.toFixed(2)
          });
        }
      });
    }

    initializeData();

    const svg = d3.select("#chartWrapper")
      .append("svg");

    const rootG = svg.append("g");
    const gridG = rootG.append("g").attr("class", "grid");
    const cellsG = rootG.append("g").attr("class", "cells");
    const xAxisG = rootG.append("g").attr("class", "axis x-axis");
    const yAxisG = rootG.append("g").attr("class", "axis y-axis");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let xScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#1f2937", "#22c55e", "#14532d"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;

    function resize() {
      width = wrapper.clientWidth;
      height = wrapper.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("width", width).attr("height", height);
      rootG.attr("transform", `translate(${margin.left},${margin.top})`);

      xScale.range([0, innerWidth]).domain(d3.range(timeSteps));
      yScale.range([0, innerHeight]).domain(stocks);

      render();
    }

    function renderAxes(transform = currentTransform) {
      const zx = transform.rescaleX(
        d3.scaleLinear()
          .domain([0, timeSteps])
          .range([0, innerWidth])
      );

      const visibleTicks = d3.range(timeSteps).filter(i => {
        const x = zx(i + 0.5);
        return x >= 0 && x <= innerWidth;
      });

      const xAxis = d3.axisBottom(zx)
        .tickValues(visibleTicks.map(i => i + 0.5))
        .tickFormat((d, i) => {
          const idx = Math.floor(d);
          return timestamps[idx] || "";
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG
        .attr("transform", `translate(0,${innerHeight})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end")
        .attr("dx", "-0.6em")
        .attr("dy", "0.2em");

      yAxisG.call(yAxis);
    }

    function renderGrid(transform = currentTransform) {
      const zx = transform.rescaleX(
        d3.scaleLinear().domain([0, timeSteps]).range([0, innerWidth])
      );

      const verticalLines = d3.range(timeSteps + 1).map(i => ({
        x: zx(i)
      }));

      const horizontalLines = stocks.map(stock => ({
        y: yScale(stock)
      }));
      horizontalLines.push({ y: innerHeight });

      const v = gridG.selectAll(".v-line")
        .data(verticalLines);

      v.join("line")
        .attr("class", "v-line")
        .attr("x1", d => d.x)
        .attr("x2", d => d.x)
        .attr("y1", 0)
        .attr("y2", innerHeight)
        .attr("stroke", "#1e293b");

      const h = gridG.selectAll(".h-line")
        .data(horizontalLines);

      h.join("line")
        .attr("class", "h-line")
        .attr("x1", 0)
        .attr("x2", innerWidth)
        .attr("y1", d => d.y)
        .attr("y2", d => d.y)
        .attr("stroke", "#1e293b");
    }

    function renderCells(transform = currentTransform) {
      const zx = transform.rescaleX(
        d3.scaleLinear().domain([0, timeSteps]).range([0, innerWidth])
      );

      const cellWidth = i => Math.max(0, zx(i + 1) - zx(i));
      const cellX = i => zx(i);

      const cells = cellsG.selectAll("rect")
        .data(data, d => `${d.stock}-${d.timeIndex}`);

      cells.join(
        enter => enter.append("rect")
          .attr("rx", 2)
          .attr("ry", 2)
          .attr("x", d => cellX(d.timeIndex))
          .attr("y", d => yScale(d.stock))
          .attr("width", d => cellWidth(d.timeIndex))
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.changePct))
          .attr("stroke", "#0f172a")
          .attr("stroke-width", 0.5)
          .on("mousemove", (event, d) => showTooltip(event, d))
          .on("mouseleave", hideTooltip),
        update => update,
        exit => exit.remove()
      )
      .transition()
      .duration(300)
      .attr("x", d => cellX(d.timeIndex))
      .attr("y", d => yScale(d.stock))
      .attr("width", d => cellWidth(d.timeIndex))
      .attr("height", yScale.bandwidth())
      .attr("fill", d => colorScale(d.changePct));
    }

    function render(transform = currentTransform) {
      renderGrid(transform);
      renderCells(transform);
      renderAxes(transform);
    }

    function showTooltip(event, d) {
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <div><strong>${d.stock}</strong></div>
        <div>Time: ${d.timeLabel}</div>
        <div>Price: $${d.price.toFixed(2)}</div>
        <div>Change: <span style="color:${d.changePct >= 0 ? '#22c55e' : '#ef4444'}">${d.changePct.toFixed(2)}%</span></div>
      `;
      const rect = wrapper.getBoundingClientRect();
      tooltip.style.left = `${event.clientX - rect.left}px`;
      tooltip.style.top = `${event.clientY - rect.top}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    function pushNewData() {
      const newTime = nowLabel();
      timestamps.shift();
      timestamps.push(newTime);

      const nextData = [];

      stocks.forEach(stock => {
        const stockRows = data
          .filter(d => d.stock === stock)
          .sort((a, b) => a.timeIndex - b.timeIndex);

        const last = stockRows[stockRows.length - 1];
        const newPrice = Math.max(10, last.price + (Math.random() - 0.5) * 4);
        const newChange = Math.max(-5, Math.min(5, last.changePct + (Math.random() - 0.5) * 1.5));

        for (let i = 1; i < stockRows.length; i++) {
          nextData.push({
            ...stockRows[i],
            timeIndex: i - 1,
            timeLabel: timestamps[i - 1]
          });
        }

        nextData.push({
          stock,
          timeIndex: timeSteps - 1,
          timeLabel: timestamps[timeSteps - 1],
          price: +newPrice.toFixed(2),
          changePct: +newChange.toFixed(2)
        });
      });

      data = nextData;
      render(currentTransform);
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render(currentTransform);
      });

    svg.call(zoom);

    function resetZoom() {
      svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    }

    function startStream() {
      if (streamTimer) clearInterval(streamTimer);
      streamTimer = setInterval(() => {
        if (isStreaming) {
          pushNewData();
        }
      }, updateIntervalMs);
    }

    toggleBtn.addEventListener("click", () => {
      isStreaming = !isStreaming;
      toggleBtn.textContent = isStreaming ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = isStreaming ? "Streaming live updates..." : "Stream paused";
    });

    resetZoomBtn.addEventListener("click", resetZoom);
    window.addEventListener("resize", resize);

    resize();
    startStream();
  </script>
</body>
</html>
