  </style>
</head>
<body>
  <div class="container">
    <div class="title">Real-Time Stock Price Heatmap</div>
    <div class="subtitle">
      Heatmap of percentage price changes by symbol over time. Scroll to zoom, drag to pan.
    </div>

    <div class="controls">
      <button id="resetZoomBtn">Reset Zoom</button>
      <button id="pauseBtn">Pause Updates</button>
    </div>

    <div id="chart" class="chart-wrapper">
      <canvas id="heatmapCanvas"></canvas>
      <svg id="overlaySvg" class="overlay"></svg>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="legend">
      <span>-5%</span>
      <div class="legend-bar"></div>
      <span>+5%</span>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "CRM", "ORCL", "IBM", "UBER", "SHOP"
    ];

    const totalColumns = 240; // time buckets retained
    const updateIntervalMs = 1000;
    const margin = { top: 20, right: 20, bottom: 40, left: 70 };

    let paused = false;

    const chartEl = document.getElementById("chart");
    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlaySvg");
    const tooltip = d3.select("#tooltip");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;
    let rowHeight = 0;

    let currentTransform = d3.zoomIdentity;

    const now = new Date();

    // Initial synthetic data
    let timeBuckets = d3.range(totalColumns).map(i => new Date(now.getTime() - (totalColumns - 1 - i) * updateIntervalMs));

    // Each row contains values for each time bucket
    let data = symbols.map(symbol => {
      let base = 100 + Math.random() * 200;
      let prev = base;
      const values = timeBuckets.map(t => {
        prev = prev * (1 + (Math.random() - 0.5) * 0.01);
        return {
          symbol,
          time: t,
          price: prev,
          changePct: 0
        };
      });

      for (let i = 1; i < values.length; i++) {
        values[i].changePct = ((values[i].price - values[i - 1].price) / values[i - 1].price) * 100;
      }

      return { symbol, values };
    });

    const yScale = d3.scaleBand()
      .domain(symbols)
      .paddingInner(0.04)
      .paddingOuter(0.02);

    const xBaseScale = d3.scaleTime();

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#f8fafc", "#22c55e", "#14532d"])
      .clamp(true);

    const xAxisG = svg.append("g").attr("class", "axis x-axis");
    const yAxisG = svg.append("g").attr("class", "axis y-axis");
    const hoverG = svg.append("g");

    const hoverRect = hoverG.append("rect")
      .attr("fill", "none")
      .attr("stroke", "#fbbf24")
      .attr("stroke-width", 1.5)
      .style("display", "none");

    function resize() {
      const rect = chartEl.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;
      rowHeight = innerHeight / symbols.length;

      canvas.width = width * devicePixelRatio;
      canvas.height = height * devicePixelRatio;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);

      svg
        .attr("width", width)
        .attr("height", height);

      yScale.range([margin.top, margin.top + innerHeight]);
      xBaseScale
        .domain(d3.extent(timeBuckets))
        .range([margin.left, margin.left + innerWidth]);

      draw();
    }

    function getXScale() {
      return currentTransform.rescaleX(xBaseScale);
    }

    function drawAxes(xScale) {
      const xAxis = d3.axisBottom(xScale)
        .ticks(Math.max(4, innerWidth / 100))
        .tickFormat(d3.timeFormat("%H:%M:%S"));

      const yAxis = d3.axisLeft(yScale);

      xAxisG
        .attr("transform", `translate(0, ${margin.top + innerHeight})`)
        .call(xAxis);

      yAxisG
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);

      yAxisG.selectAll(".tick line").remove();
      xAxisG.selectAll(".tick line")
        .attr("stroke", "#334155")
        .attr("y1", -innerHeight)
        .attr("y2", 0)
        .attr("stroke-dasharray", "2,2");
    }

    function drawHeatmap(xScale) {
      ctx.clearRect(0, 0, width, height);

      ctx.fillStyle = "#111827";
      ctx.fillRect(0, 0, width, height);

      const colWidthBase = innerWidth / totalColumns;
      const x0 = xScale.range()[0];
      const x1 = xScale.range()[1];

      for (const row of data) {
        const y = yScale(row.symbol);
        const h = yScale.bandwidth();

        for (let i = 0; i < row.values.length; i++) {
          const d = row.values[i];
          const nextTime = i < row.values.length - 1 ? row.values[i + 1].time : new Date(d.time.getTime() + updateIntervalMs);

          const cellX = xScale(d.time);
          const cellX2 = xScale(nextTime);
          const cellW = Math.max(1, cellX2 - cellX);

          if (cellX + cellW < x0 || cellX > x1) continue;

          ctx.fillStyle = colorScale(d.changePct);
          ctx.fillRect(cellX, y, cellW, h);
        }
      }

      // Border around plot area
      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);
    }

    function draw() {
      const xScale = getXScale();
      drawHeatmap(xScale);
      drawAxes(xScale);
    }

    function findCell(mx, my) {
      const xScale = getXScale();

      if (
        mx < margin.left || mx > margin.left + innerWidth ||
        my < margin.top || my > margin.top + innerHeight
      ) {
        return null;
      }

      const symbol = symbols.find(s => {
        const y = yScale(s);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (!symbol) return null;

      const time = xScale.invert(mx);
      const row = data.find(r => r.symbol === symbol);
      if (!row) return null;

      let index = d3.bisector(d => d.time).right(row.values, time) - 1;
      index = Math.max(0, Math.min(row.values.length - 1, index));

      const d = row.values[index];
      const nextTime = index < row.values.length - 1
        ? row.values[index + 1].time
        : new Date(d.time.getTime() + updateIntervalMs);

      const x = xScale(d.time);
      const x2 = xScale(nextTime);
      const y = yScale(symbol);
      const w = Math.max(1, x2 - x);
      const h = yScale.bandwidth();

      return { d, x, y, w, h };
    }

    function onPointerMove(event) {
      const [mx, my] = d3.pointer(event, chartEl);
      const cell = findCell(mx, my);

      if (!cell) {
        hoverRect.style("display", "none");
        tooltip.style("opacity", 0);
        return;
      }

      hoverRect
        .style("display", null)
        .attr("x", cell.x)
        .attr("y", cell.y)
        .attr("width", cell.w)
        .attr("height", cell.h);

      tooltip
        .style("opacity", 1)
        .style("left", `${mx}px`)
        .style("top", `${my}px`)
        .html(`
          <div><strong>${cell.d.symbol}</strong></div>
          <div>Time: ${d3.timeFormat("%H:%M:%S")(cell.d.time)}</div>
          <div>Price: $${cell.d.price.toFixed(2)}</div>
          <div>Change: <span style="color:${colorScale(cell.d.changePct)}">${cell.d.changePct.toFixed(2)}%</span></div>
        `);
    }

    function onPointerLeave() {
      hoverRect.style("display", "none");
      tooltip.style("opacity", 0);
    }

    function pushNewDataPoint() {
      const newTime = new Date();

      timeBuckets.push(newTime);
      timeBuckets.shift();

      for (const row of data) {
        const last = row.values[row.values.length - 1];
        const newPrice = last.price * (1 + (Math.random() - 0.5) * 0.02);
        const changePct = ((newPrice - last.price) / last.price) * 100;

        row.values.push({
          symbol: row.symbol,
          time: newTime,
          price: newPrice,
          changePct
        });

        row.values.shift();

        // refresh timestamps to match global buckets
        for (let i = 0; i < row.values.length; i++) {
          row.values[i].time = timeBuckets[i];
        }
      }

      xBaseScale.domain(d3.extent(timeBuckets));
      draw();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([
        [margin.left, margin.top],
        [margin.left + innerWidth, margin.top + innerHeight]
      ])
      .extent([
        [margin.left, margin.top],
        [margin.left + innerWidth, margin.top + innerHeight]
      ])
      .filter(event => {
        return !event.ctrlKey && !event.button;
      })
      .on("zoom", (event) => {
        currentTransform = event.transform;
        draw();
      });

    svg.call(zoom);

    svg.append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", innerWidth)
      .attr("height", innerHeight)
      .attr("fill", "transparent")
      .style("cursor", "crosshair")
      .on("mousemove", onPointerMove)
      .on("mouseleave", onPointerLeave);

    function updateInteractionLayer() {
      const rect = svg.selectAll("rect.interaction-layer").data([null]);
      rect.join("rect")
        .attr("class", "interaction-layer")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight)
        .attr("fill", "transparent")
        .style("cursor", "crosshair")
        .on("mousemove", onPointerMove)
        .on("mouseleave", onPointerLeave);
    }

    document.getElementById("resetZoomBtn").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      paused = !paused;
      e.target.textContent = paused ? "Resume Updates" : "Pause Updates";
    });

    window.addEventListener("resize", () => {
      resize();
      updateInteractionLayer();
    });

    resize();
    updateInteractionLayer();

    setInterval(() => {
      if (!paused) pushNewDataPoint();
    }, updateIntervalMs);
  </script>
</body>
</html>
