      stroke: rgba(255,255,255,0.08);
      stroke-width: 0.5;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: #e2e8f0;
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(-50%, -120%);
      white-space: nowrap;
    }

    .legend text {
      fill: #cbd5e1;
      font-size: 11px;
    }

    .title {
      font-size: 14px;
      font-weight: 600;
      fill: #e2e8f0;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="toolbar">
      <button id="toggle">Pause</button>
      <button id="resetZoom">Reset Zoom</button>
      <div class="status" id="status">Live updates running</div>
    </div>
    <div id="chart">
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "META", "NVDA", "TSLA", "NFLX",
      "AMD", "INTC", "ORCL", "CRM", "UBER", "SHOP", "BABA", "PYPL",
      "JPM", "GS", "BAC", "V", "MA", "DIS", "KO", "PEP"
    ];

    const timeWindow = 60; // number of columns visible in data history
    const updateIntervalMs = 1000;

    const basePrices = new Map();
    const latestPrices = new Map();
    const history = [];

    stocks.forEach(symbol => {
      const base = 50 + Math.random() * 450;
      basePrices.set(symbol, base);
      latestPrices.set(symbol, base);
    });

    function formatTime(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function generateTick() {
      const now = new Date();

      stocks.forEach(symbol => {
        const prev = latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 0.02;
        const next = Math.max(1, prev * (1 + drift));
        latestPrices.set(symbol, next);

        const base = basePrices.get(symbol);
        const pctChange = ((next - base) / base) * 100;

        history.push({
          symbol,
          time: now,
          timeKey: now.getTime(),
          price: next,
          pctChange
        });
      });

      const maxRows = stocks.length * timeWindow;
      while (history.length > maxRows) {
        history.splice(0, stocks.length);
      }
    }

    for (let i = timeWindow; i > 0; i--) {
      const t = new Date(Date.now() - i * updateIntervalMs);
      stocks.forEach(symbol => {
        const prev = latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 0.02;
        const next = Math.max(1, prev * (1 + drift));
        latestPrices.set(symbol, next);

        const base = basePrices.get(symbol);
        const pctChange = ((next - base) / base) * 100;

        history.push({
          symbol,
          time: t,
          timeKey: t.getTime(),
          price: next,
          pctChange
        });
      });
    }

    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleBtn = document.getElementById("toggle");
    const resetZoomBtn = document.getElementById("resetZoom");

    const margin = { top: 50, right: 30, bottom: 70, left: 80 };

    const svg = d3.select("#chart")
      .append("svg");

    const root = svg.append("g");
    const plot = root.append("g");
    const xAxisG = root.append("g").attr("class", "axis");
    const yAxisG = root.append("g").attr("class", "axis");
    const xGridG = root.append("g").attr("class", "grid");
    const yGridG = root.append("g").attr("class", "grid");
    const titleG = root.append("text")
      .attr("class", "title")
      .text("Realtime Stock Price Heatmap (% change from baseline)");

    const defs = svg.append("defs");
    const legendGradient = defs.append("linearGradient")
      .attr("id", "legend-gradient")
      .attr("x1", "0%")
      .attr("x2", "100%")
      .attr("y1", "0%")
      .attr("y2", "0%");

    legendGradient.append("stop").attr("offset", "0%").attr("stop-color", "#b91c1c");
    legendGradient.append("stop").attr("offset", "50%").attr("stop-color", "#f8fafc");
    legendGradient.append("stop").attr("offset", "100%").attr("stop-color", "#15803d");

    const legendG = svg.append("g").attr("class", "legend");
    legendG.append("rect")
      .attr("width", 180)
      .attr("height", 12)
      .attr("fill", "url(#legend-gradient)")
      .attr("stroke", "#475569");

    legendG.append("text").attr("class", "legend-min").attr("y", 28).attr("x", 0);
    legendG.append("text").attr("class", "legend-mid").attr("y", 28).attr("x", 90).attr("text-anchor", "middle").text("0%");
    legendG.append("text").attr("class", "legend-max").attr("y", 28).attr("x", 180).attr("text-anchor", "end");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let xScale = d3.scaleBand();
    let yScale = d3.scaleBand();
    let xBaseScale = d3.scaleBand();
    let yBaseScale = d3.scaleBand();

    let currentTransform = d3.zoomIdentity;

    function getTimeKeys() {
      return Array.from(new Set(history.map(d => d.timeKey))).sort((a, b) => a - b);
    }

    function getColorScale() {
      const extent = d3.extent(history, d => d.pctChange);
      const min = Math.min(extent[0] ?? -5, -0.01);
      const max = Math.max(extent[1] ?? 5, 0.01);
      const abs = Math.max(Math.abs(min), Math.abs(max), 1);
      return {
        scale: d3.scaleLinear()
          .domain([-abs, 0, abs])
          .range(["#b91c1c", "#f8fafc", "#15803d"])
          .clamp(true),
        abs
      };
    }

    function resize() {
      width = container.clientWidth;
      height = container.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("width", width).attr("height", height);

      root.attr("transform", `translate(${margin.left},${margin.top})`);
      titleG.attr("x", margin.left).attr("y", 24);

      xAxisG.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisG.attr("transform", `translate(${margin.left},${margin.top})`);
      xGridG.attr("transform", `translate(${margin.left},${margin.top})`);
      yGridG.attr("transform", `translate(${margin.left},${margin.top})`);
      plot.attr("transform", `translate(${margin.left},${margin.top})`);

      legendG.attr("transform", `translate(${width - 230}, 18)`);

      render();
    }

    function render() {
      const timeKeys = getTimeKeys();
      const timeLabels = new Map(timeKeys.map(k => [k, formatTime(new Date(k))]));

      xBaseScale = d3.scaleBand()
        .domain(timeKeys)
        .range([0, innerWidth])
        .paddingInner(0.02)
        .paddingOuter(0.01);

      yBaseScale = d3.scaleBand()
        .domain(stocks)
        .range([0, innerHeight])
        .paddingInner(0.02)
        .paddingOuter(0.01);

      const zx = currentTransform.rescaleX(
        d3.scaleLinear().domain([0, innerWidth]).range([0, innerWidth])
      );

      const zy = currentTransform.rescaleY(
        d3.scaleLinear().domain([0, innerHeight]).range([0, innerHeight])
      );

      const xPositions = new Map(
        timeKeys.map(k => [k, zx(xBaseScale(k))])
      );

      const yPositions = new Map(
        stocks.map(s => [s, zy(yBaseScale(s))])
      );

      const scaledBandwidthX = xBaseScale.bandwidth() * currentTransform.k;
      const scaledBandwidthY = yBaseScale.bandwidth() * currentTransform.k;

      const { scale: colorScale, abs } = getColorScale();

      legendG.select(".legend-min").text(`${(-abs).toFixed(1)}%`);
      legendG.select(".legend-max").text(`${abs.toFixed(1)}%`);

      const visibleData = history.filter(d => {
        const x = xPositions.get(d.timeKey);
        const y = yPositions.get(d.symbol);
        return x + scaledBandwidthX >= 0 &&
               x <= innerWidth &&
               y + scaledBandwidthY >= 0 &&
               y <= innerHeight;
      });

      const cells = plot.selectAll(".cell")
        .data(visibleData, d => `${d.symbol}-${d.timeKey}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .merge(cells)
        .attr("x", d => xPositions.get(d.timeKey))
        .attr("y", d => yPositions.get(d.symbol))
        .attr("width", Math.max(0, scaledBandwidthX))
        .attr("height", Math.max(0, scaledBandwidthY))
        .attr("fill", d => colorScale(d.pctChange))
        .on("mousemove", function(event, d) {
          tooltip.style.opacity = 1;
          tooltip.style.left = `${event.offsetX}px`;
          tooltip.style.top = `${event.offsetY}px`;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Time: ${formatTime(d.time)}<br/>
            Price: $${d.price.toFixed(2)}<br/>
            Change: ${d.pctChange.toFixed(2)}%
          `;
        })
        .on("mouseleave", function() {
          tooltip.style.opacity = 0;
        });

      cells.exit().remove();

      const xTicks = timeKeys.filter((_, i) => {
        const approxCount = Math.max(2, Math.floor(innerWidth / 90));
        const step = Math.max(1, Math.ceil(timeKeys.length / approxCount));
        return i % step === 0;
      });

      const yTicks = stocks.filter((_, i) => {
        const approxCount = Math.max(4, Math.floor(innerHeight / 24));
        const step = Math.max(1, Math.ceil(stocks.length / approxCount));
        return i % step === 0;
      });

      const xAxis = d3.axisBottom(
        d3.scaleOrdinal()
          .domain(xTicks)
          .range(xTicks.map(k => xPositions.get(k) + scaledBandwidthX / 2))
      )
      .tickFormat(d => timeLabels.get(d));

      const yAxis = d3.axisLeft(
        d3.scaleOrdinal()
          .domain(yTicks)
          .range(yTicks.map(s => yPositions.get(s) + scaledBandwidthY / 2))
      );

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(yAxis);

      const xGrid = xGridG.selectAll(".x-grid-line")
        .data(xTicks, d => d);

      xGrid.enter()
        .append("line")
        .attr("class", "x-grid-line")
        .merge(xGrid)
        .attr("x1", d => xPositions.get(d))
        .attr("x2", d => xPositions.get(d))
        .attr("y1", 0)
        .attr("y2", innerHeight)
        .attr("stroke", "#1e293b");

      xGrid.exit().remove();

      const yGrid = yGridG.selectAll(".y-grid-line")
        .data(yTicks, d => d);

      yGrid.enter()
        .append("line")
        .attr("class", "y-grid-line")
        .merge(yGrid)
        .attr("x1", 0)
        .attr("x2", innerWidth)
        .attr("y1", d => yPositions.get(d))
        .attr("y2", d => yPositions.get(d))
        .attr("stroke", "#1e293b");

      yGrid.exit().remove();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width || 1, height || 1]])
      .extent([[0, 0], [width || 1, height || 1]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    let running = true;
    let timer = null;

    function start() {
      if (timer) return;
      timer = setInterval(() => {
        if (!running) return;
        generateTick();
        render();
      }, updateIntervalMs);
    }

    function stop() {
      clearInterval(timer);
      timer = null;
    }

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      statusEl.textContent = running ? "Live updates running" : "Live updates paused";
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    resize();
    start();
  </script>
</body>
</html>
