  <script>
    class StockHeatmap {
      constructor({
        container,
        tooltip,
        width = 1200,
        height = 700,
        symbols = [],
        timeBuckets = 60
      }) {
        this.container = d3.select(container);
        this.tooltip = d3.select(tooltip);
        this.width = width;
        this.height = height;
        this.symbols = symbols;
        this.timeBuckets = timeBuckets;

        this.margin = { top: 20, right: 30, bottom: 90, left: 90 };
        this.legendHeight = 14;
        this.legendWidth = 240;

        this.innerWidth = this.width - this.margin.left - this.margin.right;
        this.innerHeight = this.height - this.margin.top - this.margin.bottom;

        this.data = [];
        this.timeLabels = [];
        this.zoomTransform = d3.zoomIdentity;

        this.init();
      }

      init() {
        this.svg = this.container
          .append("svg")
          .attr("viewBox", `0 0 ${this.width} ${this.height}`)
          .attr("preserveAspectRatio", "xMidYMid meet");

        this.root = this.svg.append("g")
          .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.clipId = `clip-${Math.random().toString(36).slice(2)}`;

        this.svg.append("defs")
          .append("clipPath")
          .attr("id", this.clipId)
          .append("rect")
          .attr("width", this.innerWidth)
          .attr("height", this.innerHeight);

        this.gridLayer = this.root.append("g");
        this.cellsViewport = this.root.append("g")
          .attr("clip-path", `url(#${this.clipId})`);

        this.cellsLayer = this.cellsViewport.append("g");
        this.xAxisLayer = this.root.append("g")
          .attr("class", "axis")
          .attr("transform", `translate(0,${this.innerHeight})`);

        this.yAxisLayer = this.root.append("g")
          .attr("class", "axis");

        this.legendLayer = this.svg.append("g")
          .attr("class", "legend")
          .attr("transform", `translate(${this.width - this.legendWidth - 40}, ${this.height - 40})`);

        this.xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
        this.yScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);

        this.colorScale = d3.scaleSequential()
          .interpolator(d3.interpolateRdYlGn)
          .domain([-5, 5]); // percent change

        this.xAxis = d3.axisBottom(this.xScale);
        this.yAxis = d3.axisLeft(this.yScale);

        this.zoom = d3.zoom()
          .scaleExtent([1, 12])
          .translateExtent([[0, 0], [this.innerWidth, this.innerHeight]])
          .extent([[0, 0], [this.innerWidth, this.innerHeight]])
          .on("zoom", (event) => this.onZoom(event));

        this.svg.call(this.zoom);

        this.drawLegend();
      }

      generateInitialData() {
        const now = new Date();
        this.timeLabels = d3.range(this.timeBuckets).map(i => {
          const t = new Date(now.getTime() - (this.timeBuckets - 1 - i) * 60 * 1000);
          return d3.timeFormat("%H:%M")(t);
        });

        const baselines = new Map(
          this.symbols.map(s => [s, 100 + Math.random() * 200])
        );

        this.data = [];

        this.symbols.forEach(symbol => {
          let price = baselines.get(symbol);
          this.timeLabels.forEach(time => {
            price *= 1 + (Math.random() - 0.5) * 0.01;
            const baseline = baselines.get(symbol);
            const pctChange = ((price - baseline) / baseline) * 100;
            this.data.push({
              symbol,
              time,
              price: +price.toFixed(2),
              pctChange: +pctChange.toFixed(2)
            });
          });
        });
      }

      pushRealtimeUpdate() {
        const nextTime = this.nextTimeLabel();
        this.timeLabels.push(nextTime);

        if (this.timeLabels.length > this.timeBuckets) {
          const removed = this.timeLabels.shift();
          this.data = this.data.filter(d => d.time !== removed);
        }

        this.symbols.forEach(symbol => {
          const symbolRows = this.data.filter(d => d.symbol === symbol);
          const last = symbolRows[symbolRows.length - 1];
          const baseline = symbolRows[0] ? symbolRows[0].price / (1 + symbolRows[0].pctChange / 100) : 100;
          const prevPrice = last ? last.price : 100 + Math.random() * 100;
          const newPrice = prevPrice * (1 + (Math.random() - 0.5) * 0.02);
          const pctChange = ((newPrice - baseline) / baseline) * 100;

          this.data.push({
            symbol,
            time: nextTime,
            price: +newPrice.toFixed(2),
            pctChange: +pctChange.toFixed(2)
          });
        });

        const extent = d3.extent(this.data, d => d.pctChange);
        const maxAbs = Math.max(Math.abs(extent[0] || 0), Math.abs(extent[1] || 0), 1);
        this.colorScale.domain([-maxAbs, maxAbs]);
      }

      nextTimeLabel() {
        const last = this.timeLabels[this.timeLabels.length - 1];
        if (!last) return d3.timeFormat("%H:%M")(new Date());

        const [h, m] = last.split(":").map(Number);
        const dt = new Date();
        dt.setHours(h, m, 0, 0);
        dt.setMinutes(dt.getMinutes() + 1);
        return d3.timeFormat("%H:%M")(dt);
      }

      render() {
        this.xScale.domain(this.timeLabels).range([0, this.innerWidth]);
        this.yScale.domain(this.symbols).range([0, this.innerHeight]);

        this.drawGrid();
        this.drawAxes();
        this.drawCells();
        this.drawLegend();
      }

      drawGrid() {
        const xLines = this.gridLayer.selectAll(".x-grid")
          .data(this.timeLabels, d => d);

        xLines.join(
          enter => enter.append("line")
            .attr("class", "grid-line x-grid")
            .attr("x1", d => this.xScale(d))
            .attr("x2", d => this.xScale(d))
            .attr("y1", 0)
            .attr("y2", this.innerHeight),
          update => update,
          exit => exit.remove()
        )
        .attr("x1", d => this.xScale(d))
        .attr("x2", d => this.xScale(d))
        .attr("y1", 0)
        .attr("y2", this.innerHeight);

        const yLines = this.gridLayer.selectAll(".y-grid")
          .data(this.symbols, d => d);

        yLines.join(
          enter => enter.append("line")
            .attr("class", "grid-line y-grid")
            .attr("x1", 0)
            .attr("x2", this.innerWidth)
            .attr("y1", d => this.yScale(d))
            .attr("y2", d => this.yScale(d)),
          update => update,
          exit => exit.remove()
        )
        .attr("x1", 0)
        .attr("x2", this.innerWidth)
        .attr("y1", d => this.yScale(d))
        .attr("y2", d => this.yScale(d));
      }

      drawAxes() {
        this.xAxisLayer
          .call(this.xAxis)
          .selectAll("text")
          .attr("transform", "rotate(-45)")
          .style("text-anchor", "end")
          .attr("dx", "-0.5em")
          .attr("dy", "0.2em");

        this.yAxisLayer.call(this.yAxis);
      }

      drawCells() {
        const self = this;

        const cells = this.cellsLayer.selectAll(".cell")
          .data(this.data, d => `${d.symbol}-${d.time}`);

        cells.join(
          enter => enter.append("rect")
            .attr("class", "cell")
            .attr("rx", 2)
            .attr("ry", 2)
            .attr("x", d => this.xScale(d.time))
            .attr("y", d => this.yScale(d.symbol))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.pctChange))
            .on("mousemove", function(event, d) {
              self.tooltip
                .style("opacity", 1)
                .style("left", `${event.offsetX + 16}px`)
                .style("top", `${event.offsetY + 16}px`)
                .html(`
                  <div><strong>${d.symbol}</strong></div>
                  <div>Time: ${d.time}</div>
                  <div>Price: $${d.price.toFixed(2)}</div>
                  <div>Change: ${d.pctChange.toFixed(2)}%</div>
                `);
            })
            .on("mouseleave", () => {
              self.tooltip.style("opacity", 0);
            }),
          update => update,
          exit => exit.remove()
        )
        .transition()
        .duration(250)
        .attr("x", d => this.xScale(d.time))
        .attr("y", d => this.yScale(d.symbol))
        .attr("width", this.xScale.bandwidth())
        .attr("height", this.yScale.bandwidth())
        .attr("fill", d => this.colorScale(d.pctChange));
      }

      drawLegend() {
        this.legendLayer.selectAll("*").remove();

        const legendId = `legend-gradient-${Math.random().toString(36).slice(2)}`;
        const defs = this.svg.select("defs");

        const gradient = defs.append("linearGradient")
          .attr("id", legendId)
          .attr("x1", "0%")
          .attr("x2", "100%")
          .attr("y1", "0%")
          .attr("y2", "0%");

        const [min, max] = this.colorScale.domain();
        const steps = d3.range(0, 1.01, 0.1);

        steps.forEach(t => {
          gradient.append("stop")
            .attr("offset", `${t * 100}%`)
            .attr("stop-color", this.colorScale(min + t * (max - min)));
        });

        this.legendLayer.append("rect")
          .attr("width", this.legendWidth)
          .attr("height", this.legendHeight)
          .attr("rx", 4)
          .attr("fill", `url(#${legendId})`);

        const legendScale = d3.scaleLinear()
          .domain([min, max])
          .range([0, this.legendWidth]);

        const legendAxis = d3.axisBottom(legendScale)
          .ticks(5)
          .tickFormat(d => `${d}%`);

        this.legendLayer.append("g")
          .attr("transform", `translate(0, ${this.legendHeight})`)
          .call(legendAxis);

        this.legendLayer.append("text")
          .attr("x", 0)
          .attr("y", -6)
          .text("% Change");
      }

      onZoom(event) {
        this.zoomTransform = event.transform;

        const zx = event.transform.rescaleX(
          d3.scaleLinear()
            .domain([0, this.timeLabels.length])
            .range([0, this.innerWidth])
        );

        const visibleTimes = this.timeLabels.filter((_, i) => {
          const px = zx(i);
          return px >= -this.xScale.bandwidth() && px <= this.innerWidth + this.xScale.bandwidth();
        });

        const scaledBandwidth = Math.max(this.xScale.bandwidth() * event.transform.k, 2);

        this.cellsLayer.selectAll(".cell")
          .attr("x", d => {
            const i = this.timeLabels.indexOf(d.time);
            return zx(i);
          })
          .attr("width", scaledBandwidth)
          .attr("y", d => this.yScale(d.symbol))
          .attr("height", this.yScale.bandwidth());

        this.gridLayer.selectAll(".x-grid")
          .attr("x1", d => {
            const i = this.timeLabels.indexOf(d);
            return zx(i);
          })
          .attr("x2", d => {
            const i = this.timeLabels.indexOf(d);
            return zx(i);
          });

        const xAxisScale = d3.scaleBand()
          .domain(visibleTimes)
          .range([
            visibleTimes.length ? zx(this.timeLabels.indexOf(visibleTimes[0])) : 0,
            visibleTimes.length ? zx(this.timeLabels.indexOf(visibleTimes[visibleTimes.length - 1]) + 1) : this.innerWidth
          ])
          .paddingInner(0.02)
          .paddingOuter(0.01);

        this.xAxisLayer.call(d3.axisBottom(xAxisScale))
          .selectAll("text")
          .attr("transform", "rotate(-45)")
          .style("text-anchor", "end")
          .attr("dx", "-0.5em")
          .attr("dy", "0.2em");
      }

      resetZoom() {
        this.svg.transition().duration(400).call(this.zoom.transform, d3.zoomIdentity);
      }

      rebuild(symbols, timeBuckets) {
        this.symbols = symbols;
        this.timeBuckets = timeBuckets;
        this.generateInitialData();
        this.render();
        this.resetZoom();
      }
    }

    function generateSymbols(count) {
      const base = [
        "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA", "META", "NFLX", "AMD", "INTC",
        "ORCL", "CRM", "UBER", "SHOP", "PYPL", "ADBE", "QCOM", "BABA", "SONY", "IBM",
        "CSCO", "AVGO", "PLTR", "SQ", "SNOW", "ZM", "COIN", "SAP", "ARM", "DELL",
        "ASML", "TXN", "MU", "PANW", "CRWD", "NOW", "TEAM", "DOCU", "FSLY", "NET",
        "OKTA", "DDOG", "MDB", "ZS", "TWLO", "ROKU", "SE", "BIDU", "JD", "VEEV"
      ];
      return base.slice(0, count);
    }

    const chart = new StockHeatmap({
      container: "#chart",
      tooltip: "#tooltip",
      symbols: generateSymbols(20),
      timeBuckets: 60
    });

    chart.generateInitialData();
    chart.render();

    const status = document.getElementById("status");
    const toggleStreamBtn = document.getElementById("toggleStream");
    const resetZoomBtn = document.getElementById("resetZoom");
    const intervalSelect = document.getElementById("intervalSelect");
    const symbolCountInput = document.getElementById("symbolCount");
    const timeCountInput = document.getElementById("timeCount");
    const rebuildBtn = document.getElementById("rebuild");

    let streaming = true;
    let intervalMs = +intervalSelect.value;
    let timer = null;

    function startStream() {
      stopStream();
      timer = setInterval(() => {
        chart.pushRealtimeUpdate();
        chart.render();
      }, intervalMs);
      status.textContent = "Streaming live updates...";
    }

    function stopStream() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    startStream();

    toggleStreamBtn.addEventListener("click", () => {
      streaming = !streaming;
      if (streaming) {
        startStream();
        toggleStreamBtn.textContent = "Pause Stream";
        status.textContent = "Streaming live updates...";
      } else {
        stopStream();
        toggleStreamBtn.textContent = "Resume Stream";
        status.textContent = "Stream paused";
      }
    });

    resetZoomBtn.addEventListener("click", () => {
      chart.resetZoom();
    });

    intervalSelect.addEventListener("change", () => {
      intervalMs = +intervalSelect.value;
      if (streaming) startStream();
    });

    rebuildBtn.addEventListener("click", () => {
      const symbolCount = Math.max(5, Math.min(50, +symbolCountInput.value || 20));
      const timeCount = Math.max(20, Math.min(200, +timeCountInput.value || 60));
      chart.rebuild(generateSymbols(symbolCount), timeCount);
    });
  </script>
</body>
</html>
