  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    :root {
      --bg: #0f172a;
      --panel: #111827;
      --grid: #1f2937;
      --text: #e5e7eb;
      --muted: #94a3b8;
      --border: #334155;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, sans-serif;
      background: var(--bg);
      color: var(--text);
    }

    .container {
      padding: 16px;
    }

    .header {
      display: flex;
