      flex-wrap: wrap;
    }

    .title {
      font-size: 20px;
      font-weight: 700;
    }

    .controls {
      display: flex;
      gap: 8px;
      align-items: center;
      flex-wrap: wrap;
    }

    button {
      background: #1e293b;
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 12px;
      cursor: pointer;
    }

    button:hover {
      background: #334155;
    }

    .chart-wrap {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 12px;
      overflow: hidden;
    }

    svg {
      width: 100%;
      height: 700px;
      display: block;
      background: #0b1220;
      border-radius: 8px;
    }

    .axis text {
      fill: var(--muted);
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: var(--border);
    }

    .tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.96);
      color: white;
      border: 1px solid #475569;
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 12px;
      line-height: 1.4;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(8px, 8px);
      transition: opacity 0.08s linear;
      z-index: 1000;
      min-width: 160px;
    }

    .legend-label {
      fill: var(--muted);
      font-size: 11px;
    }

    .status {
      color: var(--muted);
      font-size: 13px;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <div class="title">Real-Time Stock Price Heatmap</div>
        <div class="status" id="status">Streaming simulated price changes</div>
      </div>
      <div class="controls">
        <button id="pauseBtn">Pause</button>
        <button id="resumeBtn">Resume</button>
        <button id="resetZoomBtn">Reset Zoom</button>
      </div>
    </div>

    <div class="chart-wrap">
      <svg id="heatmap"></svg>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const svg = d3.select("#heatmap");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const width = 1400;
    const height = 700;

    svg.attr("viewBox", `0 0 ${width} ${height}`);

    const margin = { top: 40, right: 30, bottom: 80, left: 90 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const clipId = "heatmap-clip";
    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", innerWidth)
      .attr("height", innerHeight);

    const plot = svg.append("g")
      .attr("clip-path", `url(#${clipId})`)
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const xAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${innerHeight})`);

    const yAxisG = root.append("g")
      .attr("class", "axis");

    const gridLayer = plot.append("g");
    const cellLayer = plot.append("g");

    const legendG = svg.append("g")
      .attr("transform", `translate(${width - 260}, ${height - 50})`);

    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "ORCL", "CRM", "UBER", "SHOP", "BABA", "PYPL",
      "JPM", "GS", "BAC", "V", "MA", "DIS", "KO", "PEP"
    ];

    const maxColumns = 120;
    const updateIntervalMs = 1000;

    let tick = 0;
    let running = true;

    const basePrices = new Map();
    const latestPrices = new Map();
    const series = [];

    stocks.forEach(symbol => {
      const base = 50 + Math.random() * 450;
      basePrices.set(symbol, base);
      latestPrices.set(symbol, base);
    });

    function formatTime(index) {
      const now = new Date(Date.now() - (maxColumns - 1 - index) * updateIntervalMs);
      return d3.timeFormat("%H:%M:%S")(now);
    }

    function generateNextColumn() {
      const timestamp = new Date();

      stocks.forEach(symbol => {
        const prev = latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 0.02;
        const shock = (Math.random() - 0.5) * 0.8;
        const next = Math.max(5, prev * (1 + drift / 100) + shock);

        latestPrices.set(symbol, next);

        const base = basePrices.get(symbol);
        const pctChange = ((next - base) / base) * 100;

        series.push({
          symbol,
          timeIndex: tick,
          timestamp,
          price: next,
          pctChange
        });
      });

      tick += 1;

      const minTickToKeep = Math.max(0, tick - maxColumns);
      while (series.length && series[0].timeIndex < minTickToKeep) {
        series.shift();
      }
    }

    for (let i = 0; i < maxColumns; i++) {
      generateNextColumn();
    }

    const xBase = d3.scaleBand()
      .domain(d3.range(Math.max(0, tick - maxColumns), tick))
      .range([0, innerWidth])
      .paddingInner(0.02)
      .paddingOuter(0);

    const yBase = d3.scaleBand()
      .domain(stocks)
      .range([0, innerHeight])
      .paddingInner(0.03)
      .paddingOuter(0);

    let xScale = xBase.copy();
    let yScale = yBase.copy();

    const colorScale = d3.scaleSequential()
      .domain([6, -6])
      .interpolator(d3.interpolateRdYlGn);

    function drawLegend() {
      const legendWidth = 180;
      const legendHeight = 12;

      const defs = svg.select("defs");
      const gradientId = "legend-gradient";

      let gradient = defs.select(`#${gradientId}`);
      if (gradient.empty()) {
        gradient = defs.append("linearGradient")
          .attr("id", gradientId)
          .attr("x1", "0%")
          .attr("x2", "100%")
          .attr("y1", "0%")
          .attr("y2", "0%");
      }

      const stops = d3.range(0, 1.01, 0.1);
      gradient.selectAll("stop")
        .data(stops)
        .join("stop")
        .attr("offset", d => `${d * 100}%`)
        .attr("stop-color", d => colorScale(6 - d * 12));

      legendG.selectAll("*").remove();

      legendG.append("text")
        .attr("class", "legend-label")
        .attr("x", 0)
        .attr("y", -8)
        .text("Price Change %");

      legendG.append("rect")
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", `url(#${gradientId})`)
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-6, 6])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .ticks(5)
        .tickFormat(d => `${d}%`);

      legendG.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0,${legendHeight})`)
        .call(legendAxis);
    }

    function getVisibleTimeDomain() {
      return d3.range(Math.max(0, tick - maxColumns), tick);
    }

    function updateBaseDomains() {
      xBase.domain(getVisibleTimeDomain());
    }

    function renderAxes() {
      const xAxis = d3.axisBottom(xScale)
        .tickValues(xScale.domain().filter((d, i, arr) => {
          const step = Math.max(1, Math.floor(arr.length / 8));
          return i % step === 0;
        }))
        .tickFormat(d => {
          const offset = d - (tick - maxColumns);
          const idx = Math.max(0, Math.min(maxColumns - 1, offset));
          return formatTime(idx);
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(yAxis);
    }

    function renderGrid() {
      const xLines = gridLayer.selectAll(".vline")
        .data(xScale.domain(), d => d);

      xLines.join(
        enter => enter.append("line")
          .attr("class", "vline")
          .attr("stroke", "#162033")
          .attr("stroke-width", 1)
          .attr("y1", 0)
          .attr("y2", innerHeight),
        update => update,
        exit => exit.remove()
      )
      .attr("x1", d => xScale(d))
      .attr("x2", d => xScale(d));

      const yLines = gridLayer.selectAll(".hline")
        .data(yScale.domain(), d => d);

      yLines.join(
        enter => enter.append("line")
          .attr("class", "hline")
          .attr("stroke", "#162033")
          .attr("stroke-width", 1)
          .attr("x1", 0)
          .attr("x2", innerWidth),
        update => update,
        exit => exit.remove()
      )
      .attr("y1", d => yScale(d))
      .attr("y2", d => yScale(d));
    }

    function renderCells() {
      const visibleX = new Set(xScale.domain());
      const visibleY = new Set(yScale.domain());

      const filtered = series.filter(d => visibleX.has(d.timeIndex) && visibleY.has(d.symbol));

      const cells = cellLayer.selectAll("rect.cell")
        .data(filtered, d => `${d.symbol}-${d.timeIndex}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 1)
          .attr("ry", 1)
          .attr("stroke", "rgba(0,0,0,0.15)")
          .attr("stroke-width", 0.5)
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .html(`
                <div><strong>${d.symbol}</strong></div>
                <div>Time: ${d3.timeFormat("%H:%M:%S")(d.timestamp)}</div>
                <div>Price: $${d.price.toFixed(2)}</div>
                <div>Change: <span style="color:${d.pctChange >= 0 ? '#4ade80' : '#f87171'}">${d.pctChange.toFixed(2)}%</span></div>
              `)
              .style("left", `${event.clientX + 12}px`)
              .style("top", `${event.clientY + 12}px`);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update,
        exit => exit.remove()
      )
      .attr("x", d => xScale(d.timeIndex))
      .attr("y", d => yScale(d.symbol))
      .attr("width", Math.max(1, xScale.bandwidth()))
      .attr("height", Math.max(1, yScale.bandwidth()))
      .attr("fill", d => colorScale(Math.max(-6, Math.min(6, d.pctChange))));
    }

    function render() {
      renderAxes();
      renderGrid();
      renderCells();
      drawLegend();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        const t = event.transform;

        const zx = t.rescaleX(d3.scaleLinear()
          .domain([0, xBase.domain().length])
          .range([0, innerWidth]));

        const zy = t.rescaleY(d3.scaleLinear()
          .domain([0, yBase.domain().length])
          .range([0, innerHeight]));

        const xDomain = xBase.domain();
        const yDomain = yBase.domain();

        const xStart = Math.max(0, Math.floor(zx.domain()[0]));
        const xEnd = Math.min(xDomain.length, Math.ceil(zx.domain()[1]));
        const yStart = Math.max(0, Math.floor(zy.domain()[0]));
        const yEnd = Math.min(yDomain.length, Math.ceil(zy.domain()[1]));

        const visibleX = xDomain.slice(xStart, xEnd);
        const visibleY = yDomain.slice(yStart, yEnd);

        xScale = d3.scaleBand()
          .domain(visibleX)
          .range([Math.max(0, t.x), Math.min(innerWidth * t.k + t.x, innerWidth)])
          .paddingInner(0.02);

        yScale = d3.scaleBand()
          .domain(visibleY)
          .range([Math.max(0, t.y), Math.min(innerHeight * t.k + t.y, innerHeight)])
          .paddingInner(0.03);

        render();
      });

    svg.call(
      zoom.transform,
      d3.zoomIdentity.translate(0, 0).scale(1)
    );

    svg.call(zoom);

    function resetScales() {
      updateBaseDomains();
      xScale = xBase.copy();
      yScale = yBase.copy();
    }

    function tickUpdate() {
      if (!running) return;

      generateNextColumn();
      updateBaseDomains();
      xScale = xBase.copy();
      render();

      statusEl.textContent = `Streaming simulated price changes • Last update ${new Date().toLocaleTimeString()}`;
    }

    resetScales();
    render();

    const timer = setInterval(tickUpdate, updateIntervalMs);

    document.getElementById("pauseBtn").addEventListener("click", () => {
      running = false;
      statusEl.textContent = "Paused";
    });

    document.getElementById("resumeBtn").addEventListener("click", () => {
      running = true;
      statusEl.textContent = `Streaming simulated price changes • Resumed ${new Date().toLocaleTimeString()}`;
    });

    document.getElementById("resetZoomBtn").addEventListener("click", () => {
      resetScales();
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
      render();
    });

    window.addEventListener("resize", () => {
      render();
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each update creates one new time column for every stock:

```js
{
  symbol,
  timeIndex,
  timestamp,
  price,
  pctChange
}
```

### Heatmap mapping
- `xScale`: time buckets
- `yScale`: stock symbols
- `fill`: percentage change from base price

### Real-time updates
Every second:

- generate new prices
- append a new column
- remove old columns beyond `maxColumns`
- rerender

### Zoom/pan
D3 zoom transforms the visible domain and redraws the heatmap.

---

## Notes

This example uses **simulated data**. To connect to real stock data, replace `generateNextColumn()` with updates from:

- WebSocket feed
- polling a market API
- browser-side stream from your provider

For example, you could ingest messages like:

```js
{
  symbol: "AAPL",
  price: 214.32,
  timestamp: Date.now()
}
```

and aggregate them into time buckets before drawing.

