    }

    button:hover {
      background: #374151;
    }

    .chart-wrap {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background: #020617;
    }

    .axis path,
    .axis line {
      stroke: #475569;
    }

    .axis text {
      fill: #cbd5e1;
      font-size: 12px;
    }

    .grid line {
      stroke: rgba(148, 163, 184, 0.12);
    }

