    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.96);
      color: #f8fafc;
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 12px;
      line-height: 1.4;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(-50%, -110%);
      white-space: nowrap;
    }

    .legend text {
      fill: #cbd5e1;
      font-size: 11px;
    }

    .status {
      font-size: 12px;
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Real-Time Stock Price Heatmap</h1>
      <div class="controls">
        <button id="resetZoom">Reset Zoom</button>
        <button id="toggleUpdates">Pause Updates</button>
        <div class="status" id="status">Live updates: ON</div>
      </div>
    </div>
    <div class="chart-wrap" id="chartWrap">
      <div class="tooltip" id="tooltip"></div>
      <svg id="chart"></svg>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 30, bottom: 80, left: 90 };
    let width = wrap.clientWidth - margin.left - margin.right;
    let height = wrap.clientHeight - margin.top - margin.bottom;

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g").attr("class", "zoom-layer");
    const gridLayer = zoomLayer.append("g").attr("class", "grid");
    const cellsLayer = zoomLayer.append("g").attr("class", "cells");

    const xAxisG = root.append("g")
      .attr("class", "axis x-axis")
      .attr("transform", `translate(0,${height})`);

    const yAxisG = root.append("g")
      .attr("class", "axis y-axis");

    const legendG = root.append("g")
      .attr("class", "legend");

    const stocks = [
      "AAPL","MSFT","GOOGL","AMZN","META","TSLA","NVDA","NFLX",
      "AMD","INTC","ORCL","IBM","CRM","UBER","SHOP","BABA"
    ];

    const timeSteps = 60;
    const data = [];
    const basePrices = new Map();

    stocks.forEach(symbol => {
      basePrices.set(symbol, 80 + Math.random() * 220);
    });

    function timeLabel(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function generateInitialData() {
      const now = new Date();
      for (let t = timeSteps - 1; t >= 0; t--) {
        const ts = new Date(now.getTime() - t * 1000);
        stocks.forEach(symbol => {
          const prev = basePrices.get(symbol);
          const next = Math.max(10, prev + (Math.random() - 0.5) * 4);
          basePrices.set(symbol, next);
          data.push({
            symbol,
            timestamp: ts,
            timeKey: +ts,
            price: +next.toFixed(2),
            change: 0
          });
        });
      }
      computeChanges();
    }

    function computeChanges() {
      const grouped = d3.group(data, d => d.symbol);
      grouped.forEach(values => {
        values.sort((a, b) => a.timeKey - b.timeKey);
        for (let i = 0; i < values.length; i++) {
          if (i === 0) {
            values[i].change = 0;
          } else {
            const prev = values[i - 1].price;
            values[i].change = ((values[i].price - prev) / prev) * 100;
          }
        }
      });
    }

    generateInitialData();

    let uniqueTimes = [];
    let xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleSequential()
      .domain([3, -3])
      .interpolator(d3.interpolateRdYlGn);

    function updateDimensions() {
      width = wrap.clientWidth - margin.left - margin.right;
      height = wrap.clientHeight - margin.top - margin.bottom;
      svg.attr("viewBox", `0 0 ${wrap.clientWidth} ${wrap.clientHeight}`);
      xAxisG.attr("transform", `translate(0,${height})`);
    }

    function buildScales() {
      uniqueTimes = Array.from(new Set(data.map(d => d.timeKey))).sort((a, b) => a - b);
      xScale.domain(uniqueTimes).range([0, width]);
      yScale.domain(stocks).range([0, height]);
    }

    function renderAxes() {
      const xAxis = d3.axisBottom(xScale)
        .tickValues(uniqueTimes.filter((d, i) => i % Math.ceil(uniqueTimes.length / 8) === 0))
        .tickFormat(d => timeLabel(new Date(+d)));

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(yAxis);

      const xGrid = d3.axisBottom(xScale)
        .tickValues(uniqueTimes)
        .tickSize(height)
        .tickFormat("");

      const yGrid = d3.axisLeft(yScale)
        .tickSize(-width)
        .tickFormat("");

      gridLayer.selectAll(".x-grid").data([null]).join("g")
        .attr("class", "x-grid")
        .attr("transform", `translate(0,0)`)
        .call(xGrid);

      gridLayer.selectAll(".y-grid").data([null]).join("g")
        .attr("class", "y-grid")
        .call(yGrid);
    }

    function renderLegend() {
      const legendWidth = 220;
      const legendHeight = 12;
      const legendX = width - legendWidth;
      const legendY = -18;

      const defs = svg.selectAll("defs").data([null]).join("defs");
      const gradient = defs.selectAll("#legend-gradient").data([null]).join("linearGradient")
        .attr("id", "legend-gradient")
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      const stops = d3.range(0, 1.01, 0.1);
      gradient.selectAll("stop")
        .data(stops)
        .join("stop")
        .attr("offset", d => `${d * 100}%`)
        .attr("stop-color", d => colorScale(3 - d * 6));

      legendG.attr("transform", `translate(${legendX},${legendY})`);

      legendG.selectAll("rect.legend-bar").data([null]).join("rect")
        .attr("class", "legend-bar")
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", "url(#legend-gradient)")
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear().domain([-3, 3]).range([0, legendWidth]);
      const legendAxis = d3.axisBottom(legendScale)
        .tickValues([-3, -2, -1, 0, 1, 2, 3])
        .tickFormat(d => `${d}%`);

      legendG.selectAll("g.legend-axis").data([null]).join("g")
        .attr("class", "legend-axis")
        .attr("transform", `translate(0,${legendHeight})`)
        .call(legendAxis);

      legendG.selectAll("text.legend-title").data([null]).join("text")
        .attr("class", "legend-title")
        .attr("x", 0)
        .attr("y", -4)
        .text("Price Change");
    }

    function renderCells() {
      const cells = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${d.timeKey}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.timeKey))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(Math.max(-3, Math.min(3, d.change))))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 12}px`)
              .style("top", `${event.offsetY - 8}px`)
              .html(`
                <strong>${d.symbol}</strong><br/>
                Time: ${timeLabel(d.timestamp)}<br/>
                Price: $${d.price.toFixed(2)}<br/>
                Change: ${d.change.toFixed(2)}%
              `);
            d3.select(this).attr("stroke", "#f8fafc").attr("stroke-width", 1.5);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
            d3.select(this).attr("stroke", "rgba(15, 23, 42, 0.35)").attr("stroke-width", 1);
          }),
        update => update
          .transition()
          .duration(300)
          .attr("x", d => xScale(d.timeKey))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(Math.max(-3, Math.min(3, d.change)))),
        exit => exit.remove()
      );
    }

    function render() {
      updateDimensions();
      buildScales();
      renderAxes();
      renderCells();
      renderLegend();
      applyCurrentZoom();
    }

    let currentTransform = d3.zoomIdentity;

    function applyCurrentZoom() {
      zoomLayer.attr("transform", currentTransform);
      xAxisG.attr("transform", `translate(0,${height}) scale(${currentTransform.k},1) translate(${currentTransform.x / currentTransform.k},0)`);
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        zoomLayer.attr("transform", currentTransform);
      });

    svg.call(zoom);

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    });

    let liveUpdates = true;

    document.getElementById("toggleUpdates").addEventListener("click", (e) => {
      liveUpdates = !liveUpdates;
      e.target.textContent = liveUpdates ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = `Live updates: ${liveUpdates ? "ON" : "OFF"}`;
    });

    function pushLiveUpdate() {
      const ts = new Date();
      stocks.forEach(symbol => {
        const prev = basePrices.get(symbol);
        const drift = (Math.random() - 0.5) * 5;
        const next = Math.max(10, prev + drift);
        basePrices.set(symbol, next);

        data.push({
          symbol,
          timestamp: ts,
          timeKey: +ts,
          price: +next.toFixed(2),
          change: ((next - prev) / prev) * 100
        });
      });

      const cutoffTimes = Array.from(new Set(data.map(d => d.timeKey))).sort((a, b) => a - b);
      if (cutoffTimes.length > timeSteps) {
        const allowed = new Set(cutoffTimes.slice(cutoffTimes.length - timeSteps));
        for (let i = data.length - 1; i >= 0; i--) {
          if (!allowed.has(data[i].timeKey)) {
            data.splice(i, 1);
          }
        }
      }
    }

    setInterval(() => {
      if (!liveUpdates) return;
      pushLiveUpdate();
      render();
    }, 1000);

    window.addEventListener("resize", render);

    render();
  </script>
</body>
</html>
