      margin-top: 10px;
      color: var(--muted);
      font-size: 12px;
    }

    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(
        to right,
        #7f1d1d 0%,
        #ef4444 25%,
        #1f2937 50%,
        #22c55e 75%,
        #14532d 100%
      );
      border: 1px solid var(--border);
    }

    .status {
      font-size: 12px;
      color: var(--muted);
      margin-top: 8px;
    }

    .cell {
      shape-rendering: crispEdges;
    }

    .crosshair {
      stroke: rgba(255,255,255,0.15);
      stroke-width: 1;
      stroke-dasharray: 3 3;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="header">
      <div class="title">Real-Time Stock Price Heatmap</div>
      <div class="controls">
        <label>
          Update interval:
          <input id="speed" type="range" min="200" max="2000" step="100" value="1000" />
          <span id="speedLabel">1000ms</span>
        </label>
        <label>
          Volatility:
          <input id="volatility" type="range" min="0.1" max="5" step="0.1" value="1.2" />
          <span id="volLabel">1.2</span>
        </label>
        <button id="pauseBtn">Pause</button>
        <button id="resetZoomBtn">Reset Zoom</button>
      </div>
    </div>

    <div class="panel">
      <svg id="chart"></svg>
      <div class="legend">
        <span>- Loss</span>
        <div class="legend-bar"></div>
        <span>Gain +</span>
      </div>
      <div class="status" id="status"></div>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "CRM", "ORCL", "UBER", "SHOP", "PYPL", "ADBE",
      "QCOM", "AVGO", "SNOW", "PLTR"
    ];

    const timeWindow = 60; // number of columns
    const initialPrices = {};
    const latestPrices = {};
    const data = [];

    symbols.forEach(symbol => {
      const base = 50 + Math.random() * 450;
      initialPrices[symbol] = base;
      latestPrices[symbol] = base;
    });

    function formatTime(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function makeInitialData() {
      const now = Date.now();
      for (let t = timeWindow - 1; t >= 0; t--) {
        const timestamp = new Date(now - t * 1000);
        symbols.forEach(symbol => {
          const prev = latestPrices[symbol];
          const next = prev + (Math.random() - 0.5) * 2;
          latestPrices[symbol] = Math.max(1, next);
          data.push({
            symbol,
            timestamp,
            price: latestPrices[symbol],
            changePct: ((latestPrices[symbol] - initialPrices[symbol]) / initialPrices[symbol]) * 100
          });
        });
      }
    }

    makeInitialData();

    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");
    const status = d3.select("#status");

    let width = 0;
    let height = 0;

    const margin = { top: 20, right: 20, bottom: 80, left: 90 };

    const root = svg.append("g");
    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g");
    const xAxisLayer = root.append("g").attr("class", "axis");
    const yAxisLayer = root.append("g").attr("class", "axis");

    const crosshairX = root.append("line").attr("class", "crosshair").style("opacity", 0);
    const crosshairY = root.append("line").attr("class", "crosshair").style("opacity", 0);

    let xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    let yScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);

    let xAxis = d3.axisBottom(xScale);
    let yAxis = d3.axisLeft(yScale);

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#1f2937", "#22c55e", "#14532d"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;
    let paused = false;
    let timer = null;
    let updateInterval = 1000;
    let volatility = 1.2;

    function getTimeColumns() {
      const timestamps = Array.from(new Set(data.map(d => +d.timestamp)))
        .sort((a, b) => a - b)
        .map(ms => new Date(ms));
      return timestamps;
    }

    function resize() {
      const rect = svg.node().getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      xScale
        .domain(getTimeColumns().map(d => +d))
        .range([margin.left, width - margin.right]);

      yScale
        .domain(symbols)
        .range([margin.top, height - margin.bottom]);

      xAxisLayer.attr("transform", `translate(0, ${height - margin.bottom})`);
      yAxisLayer.attr("transform", `translate(${margin.left}, 0)`);

      render();
    }

    function render() {
      const times = getTimeColumns();

      xScale.domain(times.map(d => +d));
      yScale.domain(symbols);

      const cellWidth = xScale.bandwidth();
      const cellHeight = yScale.bandwidth();

      const cells = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${+d.timestamp}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(+d.timestamp))
        .attr("y", d => yScale(d.symbol))
        .attr("width", cellWidth)
        .attr("height", cellHeight)
        .attr("fill", d => colorScale(d.changePct))
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Time: ${formatTime(d.timestamp)}<br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: ${d.changePct.toFixed(2)}%
            `)
            .style("left", `${event.clientX + 12}px`)
            .style("top", `${event.clientY + 12}px`);

          const x = xScale(+d.timestamp) + cellWidth / 2;
          const y = yScale(d.symbol) + cellHeight / 2;

          crosshairX
            .attr("x1", margin.left)
            .attr("x2", width - margin.right)
            .attr("y1", y)
            .attr("y2", y)
            .style("opacity", 1);

          crosshairY
            .attr("x1", x)
            .attr("x2", x)
            .attr("y1", margin.top)
            .attr("y2", height - margin.bottom)
            .style("opacity", 1);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
          crosshairX.style("opacity", 0);
          crosshairY.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(250)
        .attr("x", d => xScale(+d.timestamp))
        .attr("y", d => yScale(d.symbol))
        .attr("width", cellWidth)
        .attr("height", cellHeight)
        .attr("fill", d => colorScale(d.changePct));

      cells.exit().remove();

      xAxis.scale(currentTransform.rescaleX(
        d3.scaleLinear()
          .domain([margin.left, width - margin.right])
          .range([margin.left, width - margin.right])
      ));

      const tickValues = times
        .map(d => +d)
        .filter((_, i) => i % Math.ceil(times.length / 8) === 0);

      const transformedX = d3.scaleBand()
        .domain(times.map(d => +d))
        .range([
          currentTransform.applyX(margin.left),
          currentTransform.applyX(width - margin.right)
        ])
        .paddingInner(0.02)
        .paddingOuter(0.01);

      cellsLayer.selectAll("rect.cell")
        .attr("x", d => transformedX(+d.timestamp))
        .attr("width", transformedX.bandwidth())
        .attr("y", d => currentTransform.applyY(yScale(d.symbol)))
        .attr("height", yScale.bandwidth() * currentTransform.k);

      const xAxisScale = d3.scalePoint()
        .domain(times.map(d => +d))
        .range([
          currentTransform.applyX(margin.left + transformedX.bandwidth() / 2),
          currentTransform.applyX(width - margin.right - transformedX.bandwidth() / 2)
        ]);

      const yAxisScale = d3.scalePoint()
        .domain(symbols)
        .range([
          currentTransform.applyY(margin.top + yScale.bandwidth() / 2),
          currentTransform.applyY(height - margin.bottom - yScale.bandwidth() / 2)
        ]);

      xAxisLayer.call(
        d3.axisBottom(xAxisScale)
          .tickValues(tickValues)
          .tickFormat(ms => formatTime(new Date(+ms)))
      )
      .selectAll("text")
      .attr("transform", "rotate(-35)")
      .style("text-anchor", "end");

      yAxisLayer.call(d3.axisLeft(yAxisScale));

      status.text(
        `Symbols: ${symbols.length} · Time buckets: ${times.length} · Cells: ${data.length} · Zoom: ${currentTransform.k.toFixed(2)}x`
      );
    }

    function pushNewColumn() {
      const now = new Date();

      symbols.forEach(symbol => {
        const prev = latestPrices[symbol];
        const drift = (Math.random() - 0.5) * volatility * 2;
        const next = Math.max(1, prev + drift);
        latestPrices[symbol] = next;

        data.push({
          symbol,
          timestamp: now,
          price: next,
          changePct: ((next - initialPrices[symbol]) / initialPrices[symbol]) * 100
        });
      });

      const times = getTimeColumns();
      if (times.length > timeWindow) {
        const cutoff = +times[times.length - timeWindow];
        for (let i = data.length - 1; i >= 0; i--) {
          if (+data[i].timestamp < cutoff) {
            data.splice(i, 1);
          }
        }
      }

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [10000, 10000]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    function startTimer() {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        if (!paused) pushNewColumn();
      }, updateInterval);
    }

    document.getElementById("speed").addEventListener("input", (e) => {
      updateInterval = +e.target.value;
      document.getElementById("speedLabel").textContent = `${updateInterval}ms`;
      startTimer();
    });

    document.getElementById("volatility").addEventListener("input", (e) => {
      volatility = +e.target.value;
      document.getElementById("volLabel").textContent = volatility.toFixed(1);
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      paused = !paused;
      e.target.textContent = paused ? "Resume" : "Pause";
    });

    document.getElementById("resetZoomBtn").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    resize();
    startTimer();
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each cell is:

```js
{
  symbol,
  timestamp,
  price,
  changePct
}
```

The heatmap uses:

- `symbol` for rows
- `timestamp` for columns
- `changePct` for color

---

### Real-time updates
Every interval:

- a new timestamp column is created
- each stock gets a new simulated price
- oldest columns are removed to keep a fixed window

This happens in:

```js
pushNewColumn()
```

---

### Zoom and pan
D3 zoom is attached to the SVG:

```js
const zoom = d3.zoom()
  .scaleExtent([1, 8])
  .on("zoom", (event) => {
    currentTransform = event.transform;
    render();
  });
```

This lets users:

- scroll to zoom
- drag to pan

---

### Color mapping
The heatmap color is based on percentage change from initial price:

- red = negative
- dark neutral = near zero
- green = positive

```js
const colorScale = d3.scaleLinear()
  .domain([-5, -1, 0, 1, 5])
  .range(["#7f1d1d", "#ef4444", "#1f2937", "#22c55e", "#14532d"]);
```

---

## If you want real stock data

Replace the simulated update logic with a real-time source such as:

- WebSocket feed
- SSE stream
- polling a market API

For example, instead of:

```js
const drift = (Math.random() - 0.5) * volatility * 2;
const next = Math.max(1, prev + drift);
```

you would ingest actual prices:

```js
function onMarketTick(symbol, price, timestamp) {
  latestPrices[symbol] = price;
  data.push({
    symbol,
    timestamp: new Date(timestamp),
    price,
    changePct: ((price - initialPrices[symbol]) / initialPrices[symbol]) * 100
  });
  render();
}
```

