Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
      overflow: hidden;
    }

    #container {
      position: relative;
      width: 100vw;
      height: 100vh;
      background: #111;
    }

    canvas {
      display: block;
      position: absolute;
      top: 0;
      left: 0;
    }

    svg.overlay {
      position: absolute;
      top: 0;
      left: 0;
      pointer-events: all;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(20, 20, 20, 0.95);
      color: #fff;
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      border: 1px solid #444;
      white-space: nowrap;
      display: none;
      z-index: 10;
    }

    .legend {
      position: absolute;
      right: 16px;
      top: 16px;
      background: rgba(0,0,0,0.6);
      padding: 10px;
      border-radius: 8px;
      border: 1px solid #333;
      font-size: 12px;
      color: #ddd;
      z-index: 5;
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      margin: 6px 0;
      background: linear-gradient(to right, #b30000, #222, #00c853);
      border-radius: 4px;
      border: 1px solid #555;
    }

    .title {
      position: absolute;
      left: 16px;
      top: 16px;
      z-index: 5;
      font-size: 18px;
      font-weight: bold;
    }

    .subtitle {
      position: absolute;
      left: 16px;
      top: 42px;
      z-index: 5;
      font-size: 12px;
      color: #aaa;
    }
  </style>
</head>
<body>
  <div id="container">
    <div class="title">Real-Time Stock Price Heatmap</div>
    <div class="subtitle">Mouse wheel to zoom, drag to pan, hover for details</div>
    <canvas id="heatmap"></canvas>
    <svg class="overlay"></svg>
    <div class="tooltip" id="tooltip"></div>
    <div class="legend">
      <div>Price Change</div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>-5%</span>
        <span>0%</span>
        <span>+5%</span>
      </div>
    </div>
  </div>

  <script>
    const container = document.getElementById("container");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("svg.overlay");
    const tooltip = document.getElementById("tooltip");

    let width = container.clientWidth;
    let height = container.clientHeight;

    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;
    canvas.style.width = width + "px";
    canvas.style.height = height + "px";
    ctx.scale(devicePixelRatio, devicePixelRatio);

    svg.attr("width", width).attr("height", height);

    const margin = { top: 80, right: 20, bottom: 40, left: 80 };
    const innerWidth = () => width - margin.left - margin.right;
    const innerHeight = () => height - margin.top - margin.bottom;

    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "IBM", "CRM", "UBER",
      "SHOP", "PYPL", "SQ", "SNOW", "ADBE"
    ];

    const timeSteps = 120; // columns
    const data = [];
    const basePrices = new Map();

    symbols.forEach(symbol => {
      basePrices.set(symbol, 100 + Math.random() * 200);
    });

    // Initialize time-series heatmap data
    for (let t = 0; t < timeSteps; t++) {
      const timestamp = Date.now() - (timeSteps - t) * 1000;
      symbols.forEach(symbol => {
        const prev = t === 0
          ? basePrices.get(symbol)
          : data[data.length - symbols.length]?.price ?? basePrices.get(symbol);

        const drift = (Math.random() - 0.5) * 2;
        const price = Math.max(5, prev + drift);
        const changePct = ((price - basePrices.get(symbol)) / basePrices.get(symbol)) * 100;

        data.push({
          symbol,
          timeIndex: t,
          timestamp,
          price,
          changePct
        });
      });
    }

    let xScale = d3.scaleLinear()
      .domain([0, timeSteps])
      .range([margin.left, width - margin.right]);

    let yScale = d3.scaleBand()
      .domain(symbols)
      .range([margin.top, height - margin.bottom])
      .paddingInner(0.05);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b30000", "#222222", "#00c853"])
      .clamp(true);

    let transform = d3.zoomIdentity;

    function getVisibleXScale() {
      return transform.rescaleX(xScale);
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      const zx = getVisibleXScale();

      // Background plot area
      ctx.fillStyle = "#181818";
      ctx.fillRect(margin.left, margin.top, innerWidth(), innerHeight());

      // Draw cells
      const bandH = yScale.bandwidth();

      for (const d of data) {
        const x0 = zx(d.timeIndex);
        const x1 = zx(d.timeIndex + 1);
        const y = yScale(d.symbol);

        if (y == null) continue;
        if (x1 < margin.left || x0 > width - margin.right) continue;

        ctx.fillStyle = colorScale(d.changePct);
        ctx.fillRect(x0, y, Math.max(1, x1 - x0), bandH);
      }

      drawAxes(zx);
    }

    function drawAxes(zx) {
      ctx.save();
      ctx.strokeStyle = "#666";
      ctx.fillStyle = "#ccc";
      ctx.lineWidth = 1;
      ctx.font = "11px Arial";

      // X axis
      ctx.beginPath();
      ctx.moveTo(margin.left, height - margin.bottom);
      ctx.lineTo(width - margin.right, height - margin.bottom);
      ctx.stroke();

      const xTicks = zx.ticks(10);
      xTicks.forEach(t => {
        const x = zx(t);
        if (x < margin.left || x > width - margin.right) return;

        ctx.strokeStyle = "#444";
        ctx.beginPath();
        ctx.moveTo(x, margin.top);
        ctx.lineTo(x, height - margin.bottom);
        ctx.stroke();

        ctx.fillStyle = "#aaa";
        ctx.fillText(`${Math.round(t)}s`, x - 10, height - margin.bottom + 16);
      });

      // Y axis
      ctx.strokeStyle = "#666";
      ctx.beginPath();
      ctx.moveTo(margin.left, margin.top);
      ctx.lineTo(margin.left, height - margin.bottom);
      ctx.stroke();

      symbols.forEach(symbol => {
        const y = yScale(symbol);
        if (y == null) return;
        const cy = y + yScale.bandwidth() / 2;

        ctx.strokeStyle = "#222";
        ctx.beginPath();
        ctx.moveTo(margin.left, y + yScale.bandwidth());
        ctx.lineTo(width - margin.right, y + yScale.bandwidth());
        ctx.stroke();

        ctx.fillStyle = "#ccc";
        ctx.fillText(symbol, 10, cy + 4);
      });

      ctx.restore();
    }

    function updateData() {
      // Shift left by removing oldest time slice
      const latestTimeIndex = d3.max(data, d => d.timeIndex);
      const newTimeIndex = latestTimeIndex + 1;
      const timestamp = Date.now();

      // Remove oldest column
      const minTimeIndex = d3.min(data, d => d.timeIndex);
      for (let i = data.length - 1; i >= 0; i--) {
        if (data[i].timeIndex === minTimeIndex) {
          data.splice(i, 1);
        }
      }

      // Reindex remaining data
      for (const d of data) {
        d.timeIndex -= 1;
      }

      // Add new column
      symbols.forEach(symbol => {
        const last = [...data].reverse().find(d => d.symbol === symbol);
        const prev = last ? last.price : basePrices.get(symbol);
        const drift = (Math.random() - 0.5) * 3;
        const price = Math.max(5, prev + drift);
        const changePct = ((price - basePrices.get(symbol)) / basePrices.get(symbol)) * 100;

        data.push({
          symbol,
          timeIndex: timeSteps - 1,
          timestamp,
          price,
          changePct
        });
      });

      draw();
    }

    function getCellAt(mx, my) {
      const zx = getVisibleXScale();

      const symbol = symbols.find(s => {
        const y = yScale(s);
        return y != null && my >= y && my <= y + yScale.bandwidth();
      });

      if (!symbol) return null;

      const timeIndex = Math.floor(zx.invert(mx));
      if (timeIndex < 0 || timeIndex >= timeSteps) return null;

      return data.find(d => d.symbol === symbol && d.timeIndex === timeIndex) || null;
    }

    svg.on("mousemove", function(event) {
      const [mx, my] = d3.pointer(event);
      const cell = getCellAt(mx, my);

      if (!cell) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = (mx + 16) + "px";
      tooltip.style.top = (my + 16) + "px";
      tooltip.innerHTML = `
        <strong>${cell.symbol}</strong><br/>
        Price: $${cell.price.toFixed(2)}<br/>
        Change: ${cell.changePct.toFixed(2)}%<br/>
        Time Index: ${cell.timeIndex}
      `;
    });

    svg.on("mouseleave", function() {
      tooltip.style.display = "none";
    });

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
      .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
      .on("zoom", (event) => {
        transform = event.transform;
        draw();
      });

    svg.call(zoom);

    function resize() {
      width = container.clientWidth;
      height = container.clientHeight;

      canvas.width = width * devicePixelRatio;
      canvas.height = height * devicePixelRatio;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(devicePixelRatio, devicePixelRatio);

      svg.attr("width", width).attr("height", height);

      xScale.range([margin.left, width - margin.right]);
      yScale.range([margin.top, height - margin.bottom]);

      draw();
    }

    window.addEventListener("resize", resize);

    draw();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
