<body>
  <div class="container">
    <h1>Real-Time Stock Price Heatmap</h1>

    <div class="controls">
      <button id="toggleUpdates">Pause Updates</button>
      <button id="resetZoom">Reset Zoom</button>
      <button id="addSymbol">Add Symbol</button>
      <button id="removeSymbol">Remove Symbol</button>
      <div class="status" id="status">Live updates running</div>
    </div>

    <div class="chart-wrapper">
      <svg id="heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="legend">
      <span>-5%</span>
      <div class="legend-bar"></div>
      <span>+5%</span>
    </div>
  </div>

  <script>
    const svg = d3.select("#heatmap");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 40, right: 20, bottom: 80, left: 100 };
    const outerWidth = () => svg.node().clientWidth;
    const outerHeight = () => svg.node().clientHeight;
    const width = () => outerWidth() - margin.left - margin.right;
    const height = () => outerHeight() - margin.top - margin.bottom;

    const symbolsBase = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "BABA"
    ];

    let symbols = [...symbolsBase];
    const timeWindow = 40; // number of columns
    const updateIntervalMs = 1000;
    let updatesRunning = true;
    let timer = null;

    // State: each symbol has current price and history
    const stockState = new Map();

    function randomBasePrice() {
      return +(50 + Math.random() * 450).toFixed(2);
    }

    function initState() {
      stockState.clear();
      symbols.forEach(sym => {
        const base = randomBasePrice();
        const history = [];
        for (let i = 0; i < timeWindow; i++) {
          const price = +(base * (1 + (Math.random() - 0.5) * 0.02)).toFixed(2);
          history.push({
            time: new Date(Date.now() - (timeWindow - i) * updateIntervalMs),
            price,
            changePct: +(((price - base) / base) * 100).toFixed(2),
            base
          });
        }
        stockState.set(sym, {
          currentPrice: history[history.length - 1].price,
          basePrice: base,
          history
        });
      });
    }

    initState();

    const root = svg.append("g")
      .attr("class", "root")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g").attr("class", "zoom-layer");
    const cellsLayer = zoomLayer.append("g").attr("class", "cells");
    const xAxisLayer = root.append("g").attr("class", "x-axis axis");
    const yAxisLayer = root.append("g").attr("class", "y-axis axis");

    const clipId = "heatmap-clip";
    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect");

    cellsLayer.attr("clip-path", `url(#${clipId})`);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#dc2626", "#1f2937", "#16a34a"])
      .clamp(true);

    let xScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    let xAxisScale = null;
    let yAxisScale = null;

    function getTimeLabels() {
      const firstSymbol = symbols[0];
      if (!firstSymbol || !stockState.has(firstSymbol)) return [];
      return stockState.get(firstSymbol).history.map(d => d.time);
    }

    function flattenData() {
      const data = [];
      symbols.forEach(sym => {
        const state = stockState.get(sym);
        if (!state) return;
        state.history.forEach((d, i) => {
          data.push({
            symbol: sym,
            timeIndex: i,
            time: d.time,
            price: d.price,
            changePct: d.changePct,
            base: d.base
          });
        });
      });
      return data;
    }

    function formatTime(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function renderAxes(currentXScale = xScale, currentYScale = yScale) {
      const times = getTimeLabels();

      const xTickValues = times.filter((_, i) => i % Math.max(1, Math.floor(times.length / 8)) === 0);

      const xAxis = d3.axisBottom(currentXScale)
        .tickValues(xTickValues.map((_, i) => {
          const idxs = times
            .map((t, idx) => ({ t, idx }))
            .filter((_, j) => j % Math.max(1, Math.floor(times.length / 8)) === 0)
            .map(d => d.idx);
          return idxs[i];
        }))
        .tickFormat(i => times[i] ? formatTime(times[i]) : "");

      const yAxis = d3.axisLeft(currentYScale);

      xAxisLayer
        .attr("transform", `translate(${margin.left},${margin.top + height()})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisLayer
        .attr("transform", `translate(${margin.left},${margin.top})`)
        .call(yAxis);
    }

    function render() {
      const times = getTimeLabels();
      const data = flattenData();

      xScale = d3.scaleBand()
        .domain(d3.range(times.length))
        .range([0, width()])
        .paddingInner(0.04)
        .paddingOuter(0.02);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([0, height()])
        .paddingInner(0.04)
        .paddingOuter(0.02);

      xAxisScale = xScale.copy();
      yAxisScale = yScale.copy();

      svg.select(`#${clipId} rect`)
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", width())
        .attr("height", height());

      const cells = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${d.timeIndex}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.timeIndex))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("rx", 2)
        .attr("ry", 2)
        .attr("fill", d => colorScale(d.changePct))
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .style("left", `${event.offsetX}px`)
            .style("top", `${event.offsetY}px`)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Time: ${formatTime(d.time)}<br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: <span style="color:${d.changePct >= 0 ? '#4ade80' : '#f87171'}">${d.changePct.toFixed(2)}%</span>
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(400)
        .attr("x", d => xScale(d.timeIndex))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.changePct));

      cells.exit().remove();

      renderAxes(xScale, yScale);
    }

    function updateData() {
      const now = new Date();

      symbols.forEach(sym => {
        const state = stockState.get(sym);
        if (!state) return;

        const drift = (Math.random() - 0.5) * 0.015;
        const nextPrice = +(state.currentPrice * (1 + drift)).toFixed(2);
        state.currentPrice = nextPrice;

        const changePct = +(((nextPrice - state.basePrice) / state.basePrice) * 100).toFixed(2);

        state.history.push({
          time: now,
          price: nextPrice,
          changePct,
          base: state.basePrice
        });

        if (state.history.length > timeWindow) {
          state.history.shift();
        }
      });

      render();
    }

    function addSymbol() {
      const pool = ["PYPL", "SQ", "ZM", "SNOW", "PLTR", "COIN", "DOCU", "ADBE", "SAP", "SONY"];
      const available = pool.filter(s => !symbols.includes(s));
      if (!available.length) return;
      const sym = available[Math.floor(Math.random() * available.length)];
      symbols.push(sym);

      const base = randomBasePrice();
      const history = [];
      for (let i = 0; i < timeWindow; i++) {
        const price = +(base * (1 + (Math.random() - 0.5) * 0.02)).toFixed(2);
        history.push({
          time: new Date(Date.now() - (timeWindow - i) * updateIntervalMs),
          price,
          changePct: +(((price - base) / base) * 100).toFixed(2),
          base
        });
      }

      stockState.set(sym, {
        currentPrice: history[history.length - 1].price,
        basePrice: base,
        history
      });

      render();
    }

    function removeSymbol() {
      if (symbols.length <= 3) return;
      const sym = symbols[symbols.length - 1];
      symbols = symbols.filter(s => s !== sym);
      stockState.delete(sym);
      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [outerWidth(), outerHeight()]])
      .extent([[0, 0], [outerWidth(), outerHeight()]])
      .on("zoom", (event) => {
        const t = event.transform;

        const zx = t.rescaleX(d3.scaleLinear()
          .domain([0, getTimeLabels().length])
          .range([0, width()]));

        const zy = t.rescaleY(d3.scaleLinear()
          .domain([0, symbols.length])
          .range([0, height()]));

        const transformedX = i => zx(i);
        const transformedY = s => {
          const idx = symbols.indexOf(s);
          return zy(idx);
        };

        const cellWidth = Math.max(1, (zx(1) - zx(0)) * 0.96);
        const cellHeight = Math.max(1, (zy(1) - zy(0)) * 0.96);

        cellsLayer.selectAll("rect.cell")
          .attr("x", d => transformedX(d.timeIndex))
          .attr("y", d => transformedY(d.symbol))
          .attr("width", cellWidth)
          .attr("height", cellHeight);

        const xBandLike = d3.scaleBand()
          .domain(d3.range(getTimeLabels().length))
          .range([zx(0), zx(getTimeLabels().length)])
          .paddingInner(0.04)
          .paddingOuter(0.02);

        const yBandLike = d3.scaleBand()
          .domain(symbols)
          .range([zy(0), zy(symbols.length)])
          .paddingInner(0.04)
          .paddingOuter(0.02);

        renderAxes(xBandLike, yBandLike);
      });

    svg.call(zoom);

    document.getElementById("toggleUpdates").addEventListener("click", (e) => {
      updatesRunning = !updatesRunning;
      e.target.textContent = updatesRunning ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = updatesRunning ? "Live updates running" : "Live updates paused";

      if (updatesRunning) {
        startUpdates();
      } else {
        stopUpdates();
      }
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("addSymbol").addEventListener("click", addSymbol);
    document.getElementById("removeSymbol").addEventListener("click", removeSymbol);

    function startUpdates() {
      stopUpdates();
      timer = setInterval(updateData, updateIntervalMs);
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    window.addEventListener("resize", () => {
      render();
    });

    render();
    startUpdates();
  </script>
</body>
</html>
```

