<body>
  <div class="container">
    <div class="header">
      <h1>Real-Time Stock Price Heatmap</h1>
      <div class="controls">
        <button id="pauseBtn">Pause</button>
        <button id="resumeBtn">Resume</button>
        <button id="resetZoomBtn">Reset Zoom</button>
        <div class="status" id="status">Live updates running</div>
      </div>
    </div>
    <div id="chart">
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP"
    ];

    const timeWindow = 60; // number of columns visible in data history
    const updateIntervalMs = 1000;

    const basePrices = new Map();
    const currentPrices = new Map();
    const history = [];

    symbols.forEach(symbol => {
      const base = 50 + Math.random() * 250;
      basePrices.set(symbol, base);
      currentPrices.set(symbol, base);
    });

    function generateTick(timestamp) {
      const row = {
        time: timestamp,
        values: symbols.map(symbol => {
          const prev = currentPrices.get(symbol);
          const drift = (Math.random() - 0.5) * 0.02;
          const next = Math.max(1, prev * (1 + drift));
          currentPrices.set(symbol, next);

          const base = basePrices.get(symbol);
          const pctChange = ((next - base) / base) * 100;

          return {
            symbol,
            price: next,
            pctChange
          };
        })
      };

      history.push(row);
      if (history.length > timeWindow) history.shift();
    }

    for (let i = timeWindow; i > 0; i--) {
      generateTick(Date.now() - i * updateIntervalMs);
    }

    const chartEl = document.getElementById("chart");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 30, bottom: 60, left: 90 };
    const legendHeight = 14;
    const legendWidth = 220;

    let width = chartEl.clientWidth;
    let height = chartEl.clientHeight;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .style("display", "block");

    const defs = svg.append("defs");

    const root = svg.append("g");

    const plot = root.append("g")
      .attr("class", "plot");

    const heatmapLayer = plot.append("g").attr("class", "heatmap-layer");
    const xAxisLayer = root.append("g").attr("class", "axis x-axis");
    const yAxisLayer = root.append("g").attr("class", "axis y-axis");
    const borderLayer = plot.append("rect").attr("class", "grid-border");

    const legendGroup = svg.append("g").attr("class", "legend");

    const clipId = "clip-heatmap";
    defs.append("clipPath")
      .attr("id", clipId)
      .append("rect");

    heatmapLayer.attr("clip-path", `url(#${clipId})`);

    let innerWidth = 0;
    let innerHeight = 0;

    const xScaleBase = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    const yScaleBase = d3.scaleBand().domain(symbols).paddingInner(0.02).paddingOuter(0.01);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1e293b", "#16a34a"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;

    function formatTime(ts) {
      return d3.timeFormat("%H:%M:%S")(new Date(ts));
    }

    function flattenData() {
      return history.flatMap((tick, colIndex) =>
        tick.values.map(v => ({
          time: tick.time,
          colIndex,
          symbol: v.symbol,
          price: v.price,
          pctChange: v.pctChange
        }))
      );
    }

    function updateDimensions() {
      width = chartEl.clientWidth;
      height = chartEl.clientHeight;

      svg.attr("width", width).attr("height", height);

      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom - 40;

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      xScaleBase
        .domain(history.map(d => d.time))
        .range([0, innerWidth]);

      yScaleBase
        .range([0, innerHeight]);

      xAxisLayer.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisLayer.attr("transform", `translate(${margin.left},${margin.top})`);

      borderLayer
        .attr("x", 0)
        .attr("y", 0)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      plot.attr("transform", `translate(0,0)`);

      defs.select(`#${clipId} rect`)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      legendGroup.attr(
        "transform",
        `translate(${width - legendWidth - 30}, ${height - 28})`
      );
    }

    function renderLegend() {
      const gradientId = "legend-gradient";
      let gradient = defs.select(`#${gradientId}`);

      if (gradient.empty()) {
        gradient = defs.append("linearGradient")
          .attr("id", gradientId)
          .attr("x1", "0%")
          .attr("x2", "100%")
          .attr("y1", "0%")
          .attr("y2", "0%");
      }

      gradient.selectAll("stop").remove();

      [
        { offset: "0%", color: "#b91c1c" },
        { offset: "50%", color: "#1e293b" },
        { offset: "100%", color: "#16a34a" }
      ].forEach(s => {
        gradient.append("stop")
          .attr("offset", s.offset)
          .attr("stop-color", s.color);
      });

      legendGroup.selectAll("*").remove();

      legendGroup.append("text")
        .attr("x", 0)
        .attr("y", -6)
        .text("Price Change %");

      legendGroup.append("rect")
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", `url(#${gradientId})`)
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-5, 5])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .ticks(5)
        .tickFormat(d => `${d}%`);

      legendGroup.append("g")
        .attr("transform", `translate(0,${legendHeight})`)
        .call(legendAxis)
        .call(g => g.selectAll("text").attr("fill", "#cbd5e1"))
        .call(g => g.selectAll("line,path").attr("stroke", "#475569"));
    }

    function render() {
      xScaleBase.domain(history.map(d => d.time));

      const transformedX = currentTransform.rescaleX(
        d3.scaleLinear()
          .domain([0, history.length])
          .range([0, innerWidth])
      );

      const visibleDomain = transformedX.domain();

      const data = flattenData();

      const cellWidthBase = innerWidth / Math.max(history.length, 1);
      const cellHeight = yScaleBase.bandwidth();

      const cells = heatmapLayer.selectAll(".cell")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 1)
          .attr("ry", 1)
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 14}px`)
              .style("top", `${event.offsetY + 14}px`)
              .html(`
                <strong>${d.symbol}</strong><br/>
                Time: ${formatTime(d.time)}<br/>
                Price: $${d.price.toFixed(2)}<br/>
                Change: ${d.pctChange.toFixed(2)}%
              `);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update,
        exit => exit.remove()
      )
      .attr("x", d => transformedX(d.colIndex))
      .attr("y", d => yScaleBase(d.symbol))
      .attr("width", Math.max(1, transformedX(d.colIndex + 1) - transformedX(d.colIndex)))
      .attr("height", cellHeight)
      .attr("fill", d => colorScale(d.pctChange));

      const xTickValues = history
        .map((d, i) => ({ time: d.time, i }))
        .filter(d => d.i >= visibleDomain[0] && d.i <= visibleDomain[1]);

      const tickStep = Math.max(1, Math.ceil(xTickValues.length / 8));
      const shownTicks = xTickValues.filter((d, idx) => idx % tickStep === 0);

      const xAxisScale = d3.scalePoint()
        .domain(shownTicks.map(d => d.time))
        .range([
          transformedX(visibleDomain[0]),
          transformedX(visibleDomain[1])
        ]);

      const xAxis = d3.axisBottom(xAxisScale)
        .tickFormat(d => formatTime(d));

      xAxisLayer.call(xAxis)
        .call(g => g.selectAll("text")
          .attr("transform", "rotate(-35)")
          .style("text-anchor", "end"));

      const yAxis = d3.axisLeft(yScaleBase);

      yAxisLayer.call(yAxis);

      borderLayer
        .attr("width", innerWidth)
        .attr("height", innerHeight);
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom)
      .on("dblclick.zoom", null);

    function resetZoom() {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    }

    function resize() {
      updateDimensions();

      svg.call(
        zoom
          .translateExtent([[0, 0], [innerWidth, innerHeight]])
          .extent([[0, 0], [innerWidth, innerHeight]])
      );

      renderLegend();
      render();
    }

    let timer = null;

    function startUpdates() {
      if (timer) return;
      timer = setInterval(() => {
        generateTick(Date.now());
        render();
      }, updateIntervalMs);
      statusEl.textContent = "Live updates running";
    }

    function stopUpdates() {
      clearInterval(timer);
      timer = null;
      statusEl.textContent = "Live updates paused";
    }

    document.getElementById("pauseBtn").addEventListener("click", stopUpdates);
    document.getElementById("resumeBtn").addEventListener("click", startUpdates);
    document.getElementById("resetZoomBtn").addEventListener("click", resetZoom);

    window.addEventListener("resize", resize);

    resize();
    startUpdates();
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each second, the app generates a new “tick” for every stock symbol:

```js
{
  time: timestamp,
  values: [
    { symbol: "AAPL", price: 182.34, pctChange: 1.24 },
    ...
  ]
}
```

The heatmap keeps a rolling history of the latest 60 time steps.

---

### Heatmap rendering
Each cell is a rectangle:

- `x` = time index
- `y` = stock symbol
- `fill` = percent change color

Red means negative, green means positive, dark neutral means near zero.

---

### Real-time updates
A `setInterval()` adds a new tick every second:

```js
timer = setInterval(() => {
  generateTick(Date.now());
  render();
}, 1000);
```

---

### Zoom and pan
D3 zoom transforms the x-direction time axis so users can inspect dense data.

```js
const zoom = d3.zoom()
  .scaleExtent([1, 12])
  .on("zoom", (event) => {
    currentTransform = event.transform;
    render();
  });
```

---

## If you want real stock data

Replace the simulated generator with a client-side market data source, for example:

- WebSocket feed from your provider
- polling a REST endpoint
- services like Polygon, Finnhub, Alpha Vantage, IEX Cloud, Twelve Data, etc.

You would replace:

```js
generateTick(Date.now());
```

with logic that ingests actual quotes and appends them into `history`.

Example shape:

```js
function ingestRealTick(timestamp, quoteMap) {
  const row = {
    time: timestamp,
    values: symbols.map(symbol => {
      const price = quoteMap[symbol];
      const base = basePrices.get(symbol) ?? price;
      if (!basePrices.has(symbol)) basePrices.set(symbol, price);

      return {
        symbol,
        price,
        pctChange: ((price - base) / base) * 100
      };
    })
  };

  history.push(row);
  if (history.length > timeWindow) history.shift();
  render();
}
```

