    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>

      <label>
        Symbols
        <input id="symbolCount" type="number" min="5" max="200" value="30" />
      </label>

      <label>
        Time Buckets
        <input id="timeBuckets" type="number" min="20" max="500" value="120" />
      </label>

      <label>
        Update Rate
        <select id="updateRate">
          <option value="250">250 ms</option>
          <option value="500" selected>500 ms</option>
          <option value="1000">1000 ms</option>
        </select>
      </label>

      <button id="resetZoom">Reset Zoom</button>
      <button id="regenerate">Regenerate</button>

      <div class="status" id="status">Running</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmapCanvas"></canvas>
      <svg class="overlay" id="overlay"></svg>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div>Price Change (%)</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const margin = { top: 20, right: 20, bottom: 40, left: 90 };

    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const chartWrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");

    const symbolCountInput = document.getElementById("symbolCount");
    const timeBucketsInput = document.getElementById("timeBuckets");
    const updateRateInput = document.getElementById("updateRate");
    const resetZoomBtn = document.getElementById("resetZoom");
    const regenerateBtn = document.getElementById("regenerate");
    const statusEl = document.getElementById("status");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let symbols = [];
    let times = [];
    let data = []; // 2D matrix: rows = symbols, cols = times
    let basePrices = new Map();

    let xScale, yScale, colorScale;
    let xAxisG, yAxisG, gridG;
    let zoomBehavior;
    let currentTransform = d3.zoomIdentity;
    let timer = null;

    function generateSymbols(n) {
      const seed = [
        "AAPL","MSFT","GOOG","AMZN","META","TSLA","NVDA","NFLX","AMD","INTC",
        "ORCL","CRM","UBER","SHOP","BABA","PYPL","SQ","SONY","SAP","IBM",
        "ADBE","QCOM","CSCO","AVGO","TXN","MU","PLTR","SNOW","ABNB","DIS",
        "JPM","BAC","GS","V","MA","WMT","COST","KO","PEP","NKE",
        "XOM","CVX","PFE","MRK","JNJ","UNH","CAT","GE","BA","F"
      ];
      const out = [];
      for (let i = 0; i < n; i++) {
        out.push(seed[i % seed.length] + (i >= seed.length ? "_" + Math.floor(i / seed.length) : ""));
      }
      return out;
    }

    function generateTimeLabels(n) {
      const now = new Date();
      const arr = [];
      for (let i = n - 1; i >= 0; i--) {
        const d = new Date(now.getTime() - i * 60 * 1000);
        arr.push(d);
      }
      return arr;
    }

    function initializeData(symbolCount, bucketCount) {
      symbols = generateSymbols(symbolCount);
      times = generateTimeLabels(bucketCount);
      basePrices = new Map();

      data = symbols.map((symbol) => {
        const startPrice = 50 + Math.random() * 450;
        basePrices.set(symbol, startPrice);

        let price = startPrice;
        const row = [];
        for (let i = 0; i < bucketCount; i++) {
          const drift = (Math.random() - 0.5) * 0.8;
          price = Math.max(1, price * (1 + drift / 100));
          const pctChange = ((price - startPrice) / startPrice) * 100;
          row.push({
            symbol,
            time: times[i],
            price,
            pctChange
          });
        }
        return row;
      });

      updateStatus();
    }

    function updateStatus() {
      statusEl.textContent = `Symbols: ${symbols.length} | Buckets: ${times.length} | Live updates: ON`;
    }

    function setupDimensions() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      svg.attr("width", width).attr("height", height);
    }

    function setupScales() {
      xScale = d3.scaleBand()
        .domain(d3.range(times.length))
        .range([margin.left, margin.left + innerWidth])
        .paddingInner(0.02)
        .paddingOuter(0);

      yScale = d3.scaleBand()
        .domain(d3.range(symbols.length))
        .range([margin.top, margin.top + innerHeight])
        .paddingInner(0.04)
        .paddingOuter(0);

      colorScale = d3.scaleLinear()
        .domain([-5, -2, 0, 2, 5])
        .range(["#7f1d1d", "#dc2626", "#f59e0b", "#84cc16", "#16a34a"])
        .clamp(true);
    }

    function setupAxes() {
      svg.selectAll("*").remove();

      gridG = svg.append("g");
      xAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0, ${margin.top + innerHeight})`);

      yAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(${margin.left}, 0)`);

      svg.append("rect")
        .attr("class", "zoom-pane")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight)
        .attr("fill", "transparent")
        .style("cursor", "grab");

      renderAxes(currentTransform);
    }

    function renderAxes(transform) {
      const zx = transform.rescaleX(d3.scaleLinear()
        .domain([0, times.length])
        .range([margin.left, margin.left + innerWidth]));

      const visibleIndices = [];
      const step = Math.max(1, Math.ceil(times.length / 10));

      for (let i = 0; i < times.length; i += step) {
        visibleIndices.push(i);
      }

      const xAxis = d3.axisBottom(zx)
        .tickValues(visibleIndices.map(i => i + 0.5))
        .tickFormat(d => {
          const idx = Math.max(0, Math.min(times.length - 1, Math.floor(d)));
          return d3.timeFormat("%H:%M")(times[idx]);
        });

      const yAxis = d3.axisLeft(yScale)
        .tickValues(d3.range(symbols.length))
        .tickFormat(i => symbols[i]);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);

      yAxisG.selectAll(".tick text")
        .attr("font-size", Math.max(9, Math.min(12, yScale.bandwidth() * 0.45)));
    }

    function drawHeatmap() {
      ctx.clearRect(0, 0, width, height);

      ctx.save();

      const linearX = d3.scaleLinear()
        .domain([0, times.length])
        .range([margin.left, margin.left + innerWidth]);

      const zx = currentTransform.rescaleX(linearX);

      const x0 = zx.invert(margin.left);
      const x1 = zx.invert(margin.left + innerWidth);

      const startCol = Math.max(0, Math.floor(x0));
      const endCol = Math.min(times.length - 1, Math.ceil(x1));

      for (let row = 0; row < symbols.length; row++) {
        const y = yScale(row);
        const h = yScale.bandwidth();

        for (let col = startCol; col <= endCol; col++) {
          const cell = data[row][col];
          const x = zx(col);
          const xNext = zx(col + 1);
          const w = Math.max(1, xNext - x);

          if (x + w < margin.left || x > margin.left + innerWidth) continue;

          ctx.fillStyle = colorScale(cell.pctChange);
          ctx.fillRect(x, y, w, h);
        }
      }

      // Grid border
      ctx.strokeStyle = "#2a2f4a";
      ctx.lineWidth = 1;
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);

      ctx.restore();
    }

    function getCellAtPointer(event) {
      const [mx, my] = d3.pointer(event, svg.node());

      if (
        mx < margin.left || mx > margin.left + innerWidth ||
        my < margin.top || my > margin.top + innerHeight
      ) {
        return null;
      }

      const row = Math.floor((my - margin.top) / yScale.step());
      if (row < 0 || row >= symbols.length) return null;

      const linearX = d3.scaleLinear()
        .domain([0, times.length])
        .range([margin.left, margin.left + innerWidth]);

      const zx = currentTransform.rescaleX(linearX);
      const colFloat = zx.invert(mx);
      const col = Math.floor(colFloat);

      if (col < 0 || col >= times.length) return null;

      return {
        row,
        col,
        cell: data[row][col],
        x: mx,
        y: my
      };
    }

    function showTooltip(info) {
      const { cell, x, y } = info;
      tooltip.style.display = "block";
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(cell.time)}</div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: <span style="color:${colorScale(cell.pctChange)}">${cell.pctChange.toFixed(2)}%</span></div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = "none";
    }

    function setupZoom() {
      zoomBehavior = d3.zoom()
        .scaleExtent([1, 20])
        .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .on("zoom", (event) => {
          currentTransform = event.transform;
          drawHeatmap();
          renderAxes(currentTransform);
        });

      svg.call(zoomBehavior);

      svg.select(".zoom-pane")
        .on("mousemove", (event) => {
          const info = getCellAtPointer(event);
          if (info) showTooltip(info);
          else hideTooltip();
        })
        .on("mouseleave", hideTooltip);
    }

    function pushRealTimeUpdate() {
      const newTime = new Date(times[times.length - 1].getTime() + 60 * 1000);
      times.push(newTime);
      times.shift();

      for (let row = 0; row < symbols.length; row++) {
        const prev = data[row][data[row].length - 1];
        const startPrice = basePrices.get(symbols[row]);
        const drift = (Math.random() - 0.5) * 1.2;
        const newPrice = Math.max(1, prev.price * (1 + drift / 100));
        const pctChange = ((newPrice - startPrice) / startPrice) * 100;

        data[row].push({
          symbol: symbols[row],
          time: newTime,
          price: newPrice,
          pctChange
        });
        data[row].shift();
      }

      drawHeatmap();
      renderAxes(currentTransform);
    }

    function startUpdates() {
      stopUpdates();
      const rate = +updateRateInput.value;
      timer = setInterval(pushRealTimeUpdate, rate);
    }

    function stopUpdates() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
    }

    function rebuild() {
      stopUpdates();
      currentTransform = d3.zoomIdentity;

      initializeData(+symbolCountInput.value, +timeBucketsInput.value);
      setupDimensions();
      setupScales();
      setupAxes();
      drawHeatmap();
      setupZoom();
      svg.call(zoomBehavior.transform, d3.zoomIdentity);
      startUpdates();
    }

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(250).call(zoomBehavior.transform, d3.zoomIdentity);
    });

    regenerateBtn.addEventListener("click", rebuild);
    updateRateInput.addEventListener("change", startUpdates);

    window.addEventListener("resize", () => {
      setupDimensions();
      setupScales();
      setupAxes();
      drawHeatmap();
      setupZoom();
      svg.call(zoomBehavior.transform, currentTransform);
    });

    rebuild();
  </script>
</body>
</html>
