        <div class="legend-bar"></div>
        <span class="meta">Positive</span>
      </div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmapCanvas"></canvas>
      <svg class="overlay" id="overlay"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    (() => {
      const symbols = [
        "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
        "META", "TSLA", "AMD", "NFLX", "INTC",
        "ORCL", "CRM", "ADBE", "UBER", "SHOP",
        "PYPL", "QCOM", "AVGO", "IBM", "CSCO"
      ];

      const state = {
        running: true,
        updateMs: 500,
        maxPoints: 120,
        data: [],
        timestamps: [],
        prices: new Map(),
        returns: new Map(),
        transform: d3.zoomIdentity,
      };

      const margin = { top: 20, right: 20, bottom: 40, left: 80 };

      const wrap = document.getElementById("chartWrap");
      const canvas = document.getElementById("heatmapCanvas");
      const ctx = canvas.getContext("2d");
      const svg = d3.select("#overlay");
      const tooltip = document.getElementById("tooltip");

      const toggleBtn = document.getElementById("toggleBtn");
      const resetZoomBtn = document.getElementById("resetZoomBtn");
      const speedSelect = document.getElementById("speedSelect");
      const windowSelect = document.getElementById("windowSelect");
      const statusText = document.getElementById("statusText");

      const gRoot = svg.append("g");
      const gXAxis = gRoot.append("g").attr("class", "axis x-axis");
      const gYAxis = gRoot.append("g").attr("class", "axis y-axis");
      const gCrosshair = gRoot.append("g");

      const vLine = gCrosshair.append("line").attr("class", "crosshair");
      const hLine = gCrosshair.append("line").attr("class", "crosshair");

      let width = 0;
      let height = 0;
      let innerWidth = 0;
      let innerHeight = 0;
      let timer = null;

      // Initialize baseline prices
      symbols.forEach(sym => {
        const base = 80 + Math.random() * 320;
        state.prices.set(sym, base);
        state.returns.set(sym, 0);
      });

      function resize() {
        const rect = wrap.getBoundingClientRect();
        const dpr = window.devicePixelRatio || 1;

        width = rect.width;
        height = rect.height;
        innerWidth = width - margin.left - margin.right;
        innerHeight = height - margin.top - margin.bottom;

        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;

        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

        svg.attr("width", width).attr("height", height);

        gXAxis.attr("transform", `translate(0, ${margin.top + innerHeight})`);
        gYAxis.attr("transform", `translate(${margin.left}, 0)`);

        draw();
      }

      function generateTick() {
        const now = new Date();
        state.timestamps.push(now);

        const column = [];

        for (const sym of symbols) {
          const prev = state.prices.get(sym);
          const drift = (Math.random() - 0.5) * 0.008;
          const shock = (Math.random() - 0.5) * 0.02;
          const next = prev * (1 + drift + shock);
          const ret = (next - prev) / prev;

          state.prices.set(sym, next);
          state.returns.set(sym, ret);

          column.push({
            symbol: sym,
            price: next,
            return: ret,
            time: now
          });
        }

        state.data.push(column);

        if (state.data.length > state.maxPoints) {
          state.data.shift();
          state.timestamps.shift();
        }
      }

      function getBaseScales() {
        const x = d3.scaleLinear()
          .domain([0, Math.max(0, state.data.length)])
          .range([margin.left, margin.left + innerWidth]);

        const y = d3.scaleBand()
          .domain(symbols)
          .range([margin.top, margin.top + innerHeight])
          .paddingInner(0.04)
          .paddingOuter(0.02);

        return { x, y };
      }

      function getZoomedXScale(baseX) {
        return state.transform.rescaleX(baseX);
      }

      function colorForValue(v) {
        // Clamp around [-3%, +3%]
        const t = Math.max(-0.03, Math.min(0.03, v));

        // Blue -> white -> red
        return d3.scaleLinear()
          .domain([-0.03, -0.015, 0, 0.015, 0.03])
          .range(["#1e3a8a", "#2563eb", "#e5e7eb", "#f97316", "#991b1b"])
          .interpolate(d3.interpolateRgb)(t);
      }

      function drawAxes(baseX, y) {
        const zx = getZoomedXScale(baseX);

        const tickCount = Math.max(2, Math.floor(innerWidth / 100));
        const xAxis = d3.axisBottom(zx)
          .ticks(tickCount)
          .tickFormat(i => {
            const idx = Math.round(i);
            const t = state.timestamps[idx];
            if (!t) return "";
            return d3.timeFormat("%H:%M:%S")(t);
          });

        const yAxis = d3.axisLeft(y);

        gXAxis.call(xAxis);
        gYAxis.call(yAxis);

        gXAxis.selectAll("text").attr("dy", "1em");
      }

      function drawHeatmap(baseX, y) {
        ctx.clearRect(0, 0, width, height);

        // Background
        ctx.fillStyle = "#0b1020";
        ctx.fillRect(0, 0, width, height);

        // Plot area background
        ctx.fillStyle = "#0f1730";
        ctx.fillRect(margin.left, margin.top, innerWidth, innerHeight);

        const zx = getZoomedXScale(baseX);
        const bandH = y.bandwidth();

        // Vertical grid lines
        ctx.strokeStyle = "rgba(255,255,255,0.06)";
        ctx.lineWidth = 1;
        const xTicks = zx.ticks(Math.max(2, Math.floor(innerWidth / 100)));
        for (const t of xTicks) {
          const px = zx(t);
          ctx.beginPath();
          ctx.moveTo(px, margin.top);
          ctx.lineTo(px, margin.top + innerHeight);
          ctx.stroke();
        }

        // Horizontal grid lines
        for (const sym of symbols) {
          const py = y(sym);
          ctx.beginPath();
          ctx.moveTo(margin.left, py);
          ctx.lineTo(margin.left + innerWidth, py);
          ctx.stroke();
        }

        // Draw cells
        for (let col = 0; col < state.data.length; col++) {
          const x0 = zx(col);
          const x1 = zx(col + 1);
          const cellW = x1 - x0;

          if (x1 < margin.left || x0 > margin.left + innerWidth) continue;
          if (cellW <= 0.25) continue;

          const column = state.data[col];
          for (let row = 0; row < column.length; row++) {
            const d = column[row];
            const y0 = y(d.symbol);
            if (y0 == null) continue;

            ctx.fillStyle = colorForValue(d.return);
            ctx.fillRect(x0, y0, Math.max(1, cellW), bandH);
          }
        }

        // Border around plot area
        ctx.strokeStyle = "#334155";
        ctx.lineWidth = 1;
        ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);
      }

      function draw() {
        if (innerWidth <= 0 || innerHeight <= 0) return;
        const { x, y } = getBaseScales();
        drawHeatmap(x, y);
        drawAxes(x, y);
      }

      function findCell(mx, my) {
        const { x, y } = getBaseScales();
        const zx = getZoomedXScale(x);

        if (
          mx < margin.left || mx > margin.left + innerWidth ||
          my < margin.top || my > margin.top + innerHeight
        ) {
          return null;
        }

        const xIndexFloat = zx.invert(mx);
        const col = Math.floor(xIndexFloat);
        if (col < 0 || col >= state.data.length) return null;

        let symbol = null;
        for (const s of symbols) {
          const y0 = y(s);
          const y1 = y0 + y.bandwidth();
          if (my >= y0 && my <= y1) {
            symbol = s;
            break;
          }
        }
        if (!symbol) return null;

        const row = state.data[col].find(d => d.symbol === symbol);
        if (!row) return null;

        return { col, row, xScale: zx, yScale: y };
      }

      function showTooltip(event) {
        const [mx, my] = d3.pointer(event, svg.node());
        const hit = findCell(mx, my);

        if (!hit) {
          tooltip.style.display = "none";
          vLine.style("display", "none");
          hLine.style("display", "none");
          return;
        }

        const { col, row, xScale, yScale } = hit;
        const x0 = xScale(col);
        const x1 = xScale(col + 1);
        const y0 = yScale(row.symbol);
        const y1 = y0 + yScale.bandwidth();

        vLine
          .style("display", null)
          .attr("x1", (x0 + x1) / 2)
          .attr("x2", (x0 + x1) / 2)
          .attr("y1", margin.top)
          .attr("y2", margin.top + innerHeight);

        hLine
          .style("display", null)
          .attr("x1", margin.left)
          .attr("x2", margin.left + innerWidth)
          .attr("y1", (y0 + y1) / 2)
          .attr("y2", (y0 + y1) / 2);

        const pct = (row.return * 100).toFixed(2);
        tooltip.style.display = "block";
        tooltip.style.left = `${event.clientX}px`;
        tooltip.style.top = `${event.clientY}px`;
        tooltip.innerHTML = `
          <div><strong>${row.symbol}</strong></div>
          <div>Time: ${d3.timeFormat("%H:%M:%S")(row.time)}</div>
          <div>Price: $${row.price.toFixed(2)}</div>
          <div>Return: <span style="color:${row.return >= 0 ? '#fb923c' : '#60a5fa'}">${pct}%</span></div>
          <div>Index: ${col}</div>
        `;
      }

      const zoom = d3.zoom()
        .scaleExtent([1, 20])
        .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .filter(event => {
          return !event.ctrlKey && !event.button;
        })
        .on("zoom", (event) => {
          state.transform = event.transform;
          draw();
        });

      svg.call(zoom);

      svg.on("mousemove", showTooltip);
      svg.on("mouseleave", () => {
        tooltip.style.display = "none";
        vLine.style("display", "none");
        hLine.style("display", "none");
      });

      function restartTimer() {
        if (timer) clearInterval(timer);
        timer = setInterval(() => {
          if (!state.running) return;
          generateTick();
          draw();
        }, state.updateMs);
      }

      toggleBtn.addEventListener("click", () => {
        state.running = !state.running;
        toggleBtn.textContent = state.running ? "Pause" : "Resume";
        statusText.textContent = state.running
          ? "Streaming live simulated prices"
          : "Stream paused";
      });

      resetZoomBtn.addEventListener("click", () => {
        svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
      });

      speedSelect.addEventListener("change", (e) => {
        state.updateMs = +e.target.value;
        restartTimer();
      });

      windowSelect.addEventListener("change", (e) => {
        state.maxPoints = +e.target.value;
        while (state.data.length > state.maxPoints) {
          state.data.shift();
          state.timestamps.shift();
        }
        draw();
      });

      window.addEventListener("resize", resize);

      // Seed initial data
      for (let i = 0; i < 60; i++) {
        generateTick();
      }

      resize();
      restartTimer();
    })();
  </script>
</body>
</html>
