      opacity: 0;
      transition: opacity 0.12s ease;
      white-space: nowrap;
      z-index: 10;
    }

    .axis text {
      fill: #bbb;
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #444;
    }

    .grid line {
      stroke: #222;
    }

    .cell {
      stroke: #1a1a1a;
      stroke-width: 1px;
      cursor: pointer;
    }

    .cell:hover {
      stroke: #fff;
      stroke-width: 1.5px;
    }

    .legend text {
      fill: #bbb;
      font-size: 11px;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetZoom">Reset Zoom</button>
    <button id="pauseBtn">Pause Updates</button>
    <div class="status" id="status">Live updates running</div>
  </div>

  <div id="chart">
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    const sectors = [
      "Technology", "Finance", "Healthcare", "Energy",
      "Consumer", "Industrial", "Utilities", "Real Estate"
    ];

    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "ORCL",
      "JPM", "BAC", "GS", "MS", "C", "WFC", "BLK", "AXP",
      "JNJ", "PFE", "MRK", "ABBV", "UNH", "LLY", "TMO", "BMY",
      "XOM", "CVX", "COP", "SLB", "EOG", "MPC", "PSX", "VLO",
      "WMT", "COST", "HD", "MCD", "NKE", "SBUX", "TGT", "LOW"
    ];

    function randomSector() {
      return sectors[Math.floor(Math.random() * sectors.length)];
    }

    function generateData() {
      return stocks.map(symbol => {
        const price = +(50 + Math.random() * 450).toFixed(2);
        const change = +((Math.random() - 0.5) * 10).toFixed(2);
        return {
          symbol,
          sector: randomSector(),
          price,
          change,
          volume: Math.floor(100000 + Math.random() * 5000000),
          time: new Date()
        };
      });
    }

    let data = generateData();
    let liveUpdates = true;

    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 30, bottom: 80, left: 120 };
    let width = container.clientWidth - margin.left - margin.right;
    let height = container.clientHeight - margin.top - margin.bottom;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", container.clientWidth)
      .attr("height", container.clientHeight)
      .style("display", "block");

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g");
    const gridLayer = zoomLayer.append("g").attr("class", "grid");
    const cellsLayer = zoomLayer.append("g");
    const xAxisLayer = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${height})`);
    const yAxisLayer = root.append("g")
      .attr("class", "axis");

    const clipId = "clip-heatmap";
    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", width)
      .attr("height", height);

    zoomLayer.attr("clip-path", `url(#${clipId})`);

    const xScale = d3.scaleBand().padding(0.05);
    const yScale = d3.scaleBand().padding(0.05);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#2a2a2a", "#16a34a"])
      .clamp(true);

    const xAxis = d3.axisBottom(xScale);
    const yAxis = d3.axisLeft(yScale);

    function updateScales() {
      width = container.clientWidth - margin.left - margin.right;
      height = container.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", container.clientWidth)
        .attr("height", container.clientHeight);

      xScale.domain(data.map(d => d.symbol)).range([0, width]);
      yScale.domain(sectors).range([0, height]);

      svg.select(`#${clipId} rect`)
        .attr("width", width)
        .attr("height", height);

      xAxisLayer.attr("transform", `translate(0,${height})`);
    }

    function render() {
      updateScales();

      xAxisLayer.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      yAxisLayer.call(yAxis);

      const gridX = gridLayer.selectAll(".vline")
        .data(data.map(d => d.symbol), d => d);

      gridX.join(
        enter => enter.append("line")
          .attr("class", "vline")
          .attr("stroke", "#222"),
        update => update,
        exit => exit.remove()
      )
      .attr("x1", d => xScale(d) + xScale.bandwidth() / 2)
      .attr("x2", d => xScale(d) + xScale.bandwidth() / 2)
      .attr("y1", 0)
      .attr("y2", height);

      const gridY = gridLayer.selectAll(".hline")
        .data(sectors, d => d);

      gridY.join(
        enter => enter.append("line")
          .attr("class", "hline")
          .attr("stroke", "#222"),
        update => update,
        exit => exit.remove()
      )
      .attr("x1", 0)
      .attr("x2", width)
      .attr("y1", d => yScale(d) + yScale.bandwidth() / 2)
      .attr("y2", d => yScale(d) + yScale.bandwidth() / 2);

      const cells = cellsLayer.selectAll(".cell")
        .data(data, d => d.symbol);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 4)
          .attr("ry", 4)
          .on("mousemove", (event, d) => {
            tooltip.style.opacity = 1;
            tooltip.innerHTML = `
              <strong>${d.symbol}</strong><br>
              Sector: ${d.sector}<br>
              Price: $${d.price.toFixed(2)}<br>
              Change: ${d.change > 0 ? "+" : ""}${d.change.toFixed(2)}%<br>
              Volume: ${d.volume.toLocaleString()}<br>
              Updated: ${d.time.toLocaleTimeString()}
            `;
            tooltip.style.left = `${event.offsetX + 14}px`;
            tooltip.style.top = `${event.offsetY + 14}px`;
          })
          .on("mouseleave", () => {
            tooltip.style.opacity = 0;
          })
          .on("click", (_, d) => {
            alert(`${d.symbol}\nPrice: $${d.price}\nChange: ${d.change}%`);
          }),
        update => update,
        exit => exit.remove()
      )
      .transition()
      .duration(400)
      .attr("x", d => xScale(d.symbol))
      .attr("y", d => yScale(d.sector))
      .attr("width", xScale.bandwidth())
      .attr("height", yScale.bandwidth())
      .attr("fill", d => colorScale(d.change));
    }

    function simulateUpdate() {
      data = data.map(d => {
        const delta = (Math.random() - 0.5) * 1.2;
        const pctChange = d.change + delta;
        const newPrice = Math.max(1, d.price * (1 + delta / 100));
        return {
          ...d,
          price: +newPrice.toFixed(2),
          change: +pctChange.toFixed(2),
          volume: d.volume + Math.floor(Math.random() * 50000),
          time: new Date()
        };
      });

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      liveUpdates = !liveUpdates;
      e.target.textContent = liveUpdates ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = liveUpdates ? "Live updates running" : "Live updates paused";
    });

    window.addEventListener("resize", () => {
      render();
    });

    render();

    setInterval(() => {
      if (liveUpdates) simulateUpdate();
    }, 1000);

    // Optional legend
    const legendWidth = 220;
    const legendHeight = 12;

    const legend = svg.append("g")
      .attr("class", "legend")
      .attr("transform", `translate(${margin.left}, 8)`);

    const defs = svg.append("defs");
    const gradient = defs.append("linearGradient")
      .attr("id", "legend-gradient");

    gradient.append("stop")
      .attr("offset", "0%")
      .attr("stop-color", "#b91c1c");

    gradient.append("stop")
      .attr("offset", "50%")
      .attr("stop-color", "#2a2a2a");

    gradient.append("stop")
      .attr("offset", "100%")
      .attr("stop-color", "#16a34a");

    legend.append("text")
      .attr("x", 0)
      .attr("y", -2)
      .text("Price Change %");

    legend.append("rect")
      .attr("x", 0)
      .attr("y", 6)
      .attr("width", legendWidth)
      .attr("height", legendHeight)
      .attr("fill", "url(#legend-gradient)")
      .attr("stroke", "#444");

    legend.append("text")
      .attr("x", 0)
      .attr("y", 34)
      .text("-5%");

    legend.append("text")
      .attr("x", legendWidth / 2 - 10)
      .attr("y", 34)
      .text("0%");

    legend.append("text")
      .attr("x", legendWidth - 20)
      .attr("y", 34)
      .text("+5%");
  </script>
</body>
</html>
```

## Features included

- **Heatmap cells** represent stocks
- **X-axis** = stock symbols
- **Y-axis** = sectors
- **Color** = percent price change
- **Real-time updates** every second
- **Zoom/pan** via mouse wheel and drag
- **Tooltip** on hover
- **Pause/resume** updates
- **Reset zoom** button
- **Responsive resize**

## Notes

If you want this to use **real stock data**, replace the `simulateUpdate()` logic with data from:

- WebSocket market feed
- polling a REST API
- services like Alpha Vantage, Finnhub, Polygon, IEX, etc.

For example, you would:
1. fetch latest prices
2. update `data`
3. call `render()`

