You could extend this with:

- sector grouping headers
- animated flashing on price changes
- filtering by sector
- search for ticker
- canvas rendering for thousands of symbols
- WebSocket integration for actual live market streams
- time-based heatmap where x-axis is time and y-axis is ticker

If you want, I can also provide:
1. a **React version**
2. a **Canvas/WebGL high-performance version**
3. a **version connected to a real-time API**
4. a **treemap-style stock market heatmap like Finviz**

Below is a complete client-side example of an interactive stock price heatmap with:

- real-time updates
- zoom and pan
- hover tooltip
- color scale legend
- no backend required
- simulated live stock prices

It uses:

- HTML/CSS/JS
- D3.js for rendering and zoom/pan

You can save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
      overflow: hidden;
    }

    .app {
      display: flex;
      flex-direction: column;
      height: 100vh;
      width: 100vw;
    }

    .toolbar {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      background: #111827;
      border-bottom: 1px solid #1f2937;
      flex-wrap: wrap;
    }

    .toolbar button,
    .toolbar select {
      background: #1f2937;
      color: #e5e7eb;
      border: 1px solid #374151;
      border-radius: 6px;
      padding: 8px 12px;
      cursor: pointer;
    }

    .toolbar button:hover,
    .toolbar select:hover {
      background: #374151;
    }

    .toolbar .status {
      margin-left: auto;
      font-size: 14px;
      color: #93c5fd;
    }

    .chart-container {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background: #020617;
      cursor: grab;
    }

    svg:active {
      cursor: grabbing;
    }

    .axis text {
      fill: #cbd5e1;
      font-size: 12px;
    }

    .axis path,
    .axis line {
      stroke: #334155;
    }

    .cell {
      stroke: rgba(255,255,255,0.08);
      stroke-width: 1px;
      shape-rendering: crispEdges;
    }

    .cell:hover {
      stroke: #fff;
      stroke-width: 2px;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.96);
      color: #f8fafc;
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 13px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      white-space: nowrap;
    }

    .legend {
      position: absolute;
      right: 16px;
      bottom: 16px;
      background: rgba(15, 23, 42, 0.92);
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 10px;
      color: #e2e8f0;
      font-size: 12px;
    }

    .legend-title {
      margin-bottom: 8px;
      font-weight: bold;
    }

    .legend-scale {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .legend-gradient {
      width: 180px;
      height: 12px;
      border-radius: 6px;
      background: linear-gradient(to right, #7f1d1d, #dc2626, #f8fafc, #16a34a, #14532d);
      border: 1px solid #475569;
    }

    .legend-labels {
      display: flex;
      justify-content: space-between;
      margin-top: 6px;
      font-size: 11px;
      color: #cbd5e1;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetZoom">Reset Zoom</button>
      <button id="pauseBtn">Pause Updates</button>

      <label for="speedSelect">Update Speed:</label>
      <select id="speedSelect">
        <option value="250">Fast</option>
        <option value="500" selected>Normal</option>
        <option value="1000">Slow</option>
      </select>

      <label for="metricSelect">Color Metric:</label>
      <select id="metricSelect">
        <option value="changePct" selected>% Change</option>
        <option value="price">Price</option>
        <option value="volume">Volume</option>
      </select>

      <div class="status" id="statusText">Live updates running</div>
    </div>

    <div class="chart-container" id="chartContainer">
      <svg id="heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-title">Heatmap Scale</div>
        <div class="legend-gradient"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
      "ORCL","IBM","CRM","ADBE","CSCO","QCOM","AVGO","TXN","SHOP","UBER",
      "PYPL","SQ","SNOW","PLTR","BABA","SONY","SAP","ASML","TSM","MU"
    ];

    const timeSteps = 60;
    const rows = symbols.length;
    const cols = timeSteps;

    let updateInterval = 500;
    let isPaused = false;
    let timer = null;
    let currentMetric = "changePct";

    const svg = d3.select("#heatmap");
    const container = document.getElementById("chartContainer");
    const tooltip = d3.select("#tooltip");
    const statusText = document.getElementById("statusText");

    let width = container.clientWidth;
    let height = container.clientHeight;

    const margin = { top: 30, right: 20, bottom: 50, left: 90 };
    const innerWidth = () => width - margin.left - margin.right;
    const innerHeight = () => height - margin.top - margin.bottom;

    const root = svg.append("g");
    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g");
    const xAxisLayer = root.append("g").attr("class", "axis");
    const yAxisLayer = root.append("g").attr("class", "axis");

    const defs = svg.append("defs");
    defs.append("clipPath")
      .attr("id", "clip")
      .append("rect");

    cellsLayer.attr("clip-path", "url(#clip)");

    const basePrices = new Map();
    const data = [];

    symbols.forEach(symbol => {
      const start = 50 + Math.random() * 450;
      basePrices.set(symbol, start);
      for (let t = 0; t < cols; t++) {
        const noise = (Math.random() - 0.5) * 2;
        const price = start * (1 + noise * 0.002 + t * 0.0002);
        const volume = Math.floor(100000 + Math.random() * 5000000);
        const changePct = ((price - start) / start) * 100;
        data.push({
          symbol,
          time: t,
          label: `T-${cols - t}`,
          price,
          volume,
          changePct
        });
      }
    });

    const xScale = d3.scaleBand();
    const yScale = d3.scaleBand();

    const colorScales = {
      changePct: d3.scaleLinear()
        .domain([-5, -2, 0, 2, 5])
        .range(["#7f1d1d", "#dc2626", "#f8fafc", "#16a34a", "#14532d"])
        .clamp(true),

      price: d3.scaleSequential(d3.interpolateTurbo),

      volume: d3.scaleSequential(d3.interpolatePlasma)
    };

    function getMetricValue(d) {
      return d[currentMetric];
    }

    function updateDynamicDomains() {
      if (currentMetric === "price") {
        const extent = d3.extent(data, d => d.price);
        colorScales.price.domain(extent);
      } else if (currentMetric === "volume") {
        const extent = d3.extent(data, d => d.volume);
        colorScales.volume.domain(extent);
      }
    }

    function getColor(d) {
      return colorScales[currentMetric](getMetricValue(d));
    }

    function formatMetric(d) {
      if (currentMetric === "changePct") return `${d.changePct.toFixed(2)}%`;
      if (currentMetric === "price") return `$${d.price.toFixed(2)}`;
      if (currentMetric === "volume") return d.volume.toLocaleString();
      return "";
    }

    function render() {
      width = container.clientWidth;
      height = container.clientHeight;

      svg.attr("width", width).attr("height", height);

      xScale
        .domain(d3.range(cols))
        .range([margin.left, width - margin.right])
        .padding(0.02);

      yScale
        .domain(symbols)
        .range([margin.top, height - margin.bottom])
        .padding(0.02);

      defs.select("#clip rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth())
        .attr("height", innerHeight());

      updateDynamicDomains();

      const cells = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => getColor(d))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 12}px`)
              .style("top", `${event.offsetY + 12}px`)
              .html(`
                <div><strong>${d.symbol}</strong></div>
                <div>Time: ${d.label}</div>
                <div>Price: $${d.price.toFixed(2)}</div>
                <div>Change: ${d.changePct.toFixed(2)}%</div>
                <div>Volume: ${d.volume.toLocaleString()}</div>
              `);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update
          .transition()
          .duration(200)
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => getColor(d))
      );

      const xTickValues = d3.range(0, cols, Math.max(1, Math.floor(cols / 10)));

      const xAxis = d3.axisBottom(xScale)
        .tickValues(xTickValues)
        .tickFormat(d => `T-${cols - d}`);

      const yAxis = d3.axisLeft(yScale);

      xAxisLayer
        .attr("transform", `translate(0,${height - margin.bottom})`)
        .call(xAxis);

      yAxisLayer
        .attr("transform", `translate(${margin.left},0)`)
        .call(yAxis);
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
      .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    function tick() {
      for (const symbol of symbols) {
        const symbolData = data.filter(d => d.symbol === symbol).sort((a, b) => a.time - b.time);

        for (let i = 0; i < symbolData.length - 1; i++) {
          symbolData[i].price = symbolData[i + 1].price;
          symbolData[i].volume = symbolData[i + 1].volume;
          symbolData[i].changePct = symbolData[i + 1].changePct;
          symbolData[i].label = symbolData[i + 1].label;
        }

        const last = symbolData[symbolData.length - 1];
        const prev = symbolData[symbolData.length - 2];
        const base = basePrices.get(symbol);

        const drift = (Math.random() - 0.5) * 0.02;
        const newPrice = Math.max(1, prev.price * (1 + drift));
        const newVolume = Math.floor(100000 + Math.random() * 5000000);
        const newChangePct = ((newPrice - base) / base) * 100;

        last.price = newPrice;
        last.volume = newVolume;
        last.changePct = newChangePct;
        last.label = "Now";
      }

      for (let t = 0; t < cols; t++) {
        data.forEach(d => {
          if (d.time === t) {
            d.label = t === cols - 1 ? "Now" : `T-${cols - 1 - t}`;
          }
        });
      }

      render();
    }

    function startUpdates() {
      stopUpdates();
      timer = setInterval(() => {
        if (!isPaused) tick();
      }, updateInterval);
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
    }

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      isPaused = !isPaused;
      e.target.textContent = isPaused ? "Resume Updates" : "Pause Updates";
      statusText.textContent = isPaused ? "Live updates paused" : "Live updates running";
    });

    document.getElementById("speedSelect").addEventListener("change", (e) => {
      updateInterval = Number(e.target.value);
      startUpdates();
    });

    document.getElementById("metricSelect").addEventListener("change", (e) => {
      currentMetric = e.target.value;
      render();
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", () => {
      render();
    });

    render();
    startUpdates();
  </script>
</body>
</html>
```

## Features included

- Heatmap rows = stock symbols
- Heatmap columns = recent time slices
- Real-time simulated updates
- Zoom and pan via mouse/touchpad
- Hover tooltip with:
  - symbol
