    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, container, tooltip, options = {}) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.container = container;
        this.tooltip = tooltip;

        this.devicePixelRatio = window.devicePixelRatio || 1;

        this.symbols = options.symbols || [];
        this.timeBuckets = options.timeBuckets || 60;
        this.data = options.data || [];

        this.baseCellWidth = 28;
        this.baseCellHeight = 24;
        this.headerHeight = 30;
        this.rowLabelWidth = 80;

        this.scale = 1;
        this.minScale = 0.5;
        this.maxScale = 4;

        this.offsetX = 0;
        this.offsetY = 0;

        this.isDragging = false;
        this.lastMouseX = 0;
        this.lastMouseY = 0;

        this.hoveredCell = null;

        this.resize();
        this.attachEvents();
        this.render();
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.canvas.width = rect.width * this.devicePixelRatio;
        this.canvas.height = rect.height * this.devicePixelRatio;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.devicePixelRatio, 0, 0, this.devicePixelRatio, 0, 0);
        this.render();
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.container.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const oldScale = this.scale;
          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          this.scale = Math.max(this.minScale, Math.min(this.maxScale, this.scale * zoomFactor));

          const scaleRatio = this.scale / oldScale;

          this.offsetX = mouseX - (mouseX - this.offsetX) * scaleRatio;
          this.offsetY = mouseY - (mouseY - this.offsetY) * scaleRatio;

          this.render();
        }, { passive: false });

        this.container.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.lastMouseX = e.clientX;
          this.lastMouseY = e.clientY;
          this.container.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.container.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          if (this.isDragging) {
            const dx = e.clientX - this.lastMouseX;
            const dy = e.clientY - this.lastMouseY;
            this.offsetX += dx;
            this.offsetY += dy;
            this.lastMouseX = e.clientX;
            this.lastMouseY = e.clientY;
            this.render();
          } else {
            this.updateHover(mouseX, mouseY, e.clientX, e.clientY);
          }
        });

        this.container.addEventListener('mouseleave', () => {
          this.hoveredCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });
      }

      updateHover(mouseX, mouseY, clientX, clientY) {
        const cell = this.getCellAt(mouseX, mouseY);
        this.hoveredCell = cell;

        if (cell) {
          const value = this.data[cell.row][cell.col];
          this.tooltip.style.display = 'block';
          this.tooltip.style.left = clientX - this.container.getBoundingClientRect().left + 'px';
          this.tooltip.style.top = clientY - this.container.getBoundingClientRect().top + 'px';
          this.tooltip.innerHTML = `
            <div><strong>${this.symbols[cell.row]}</strong></div>
            <div>Time: ${cell.col}</div>
            <div>Change: ${value.toFixed(2)}%</div>
          `;
        } else {
          this.tooltip.style.display = 'none';
        }

        this.render();
      }

      getCellAt(mouseX, mouseY) {
        const cellWidth = this.baseCellWidth * this.scale;
        const cellHeight = this.baseCellHeight * this.scale;

        const x = mouseX - this.offsetX;
        const y = mouseY - this.offsetY;

        if (x < this.rowLabelWidth || y < this.headerHeight) return null;

        const col = Math.floor((x - this.rowLabelWidth) / cellWidth);
        const row = Math.floor((y - this.headerHeight) / cellHeight);

        if (
          row >= 0 &&
          row < this.symbols.length &&
          col >= 0 &&
          col < this.timeBuckets
        ) {
          return { row, col };
        }

        return null;
      }

      getColor(value) {
        const clamped = Math.max(-5, Math.min(5, value));
        const t = (clamped + 5) / 10;

        if (t < 0.5) {
          const local = t / 0.5;
          return this.lerpColor([127, 29, 29], [248, 250, 252], local);
        } else {
          const local = (t - 0.5) / 0.5;
          return this.lerpColor([248, 250, 252], [20, 83, 45], local);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.devicePixelRatio;
        const height = this.canvas.height / this.devicePixelRatio;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        const cellWidth = this.baseCellWidth * this.scale;
        const cellHeight = this.baseCellHeight * this.scale;

        ctx.save();
        ctx.translate(this.offsetX, this.offsetY);

        ctx.font = `${Math.max(10, 12 * this.scale)}px Arial`;
        ctx.textBaseline = 'middle';

        // Header background
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, this.rowLabelWidth + this.timeBuckets * cellWidth, this.headerHeight);

        // Row label background
        ctx.fillRect(0, 0, this.rowLabelWidth, this.headerHeight + this.symbols.length * cellHeight);

        // Time labels
        ctx.fillStyle = '#cbd5e1';
        ctx.textAlign = 'center';
        for (let col = 0; col < this.timeBuckets; col++) {
          const x = this.rowLabelWidth + col * cellWidth;
          if (x + cellWidth < -this.offsetX || x > width - this.offsetX) continue;
          ctx.fillText(`${col}`, x + cellWidth / 2, this.headerHeight / 2);
        }

        // Row labels
        ctx.textAlign = 'left';
        for (let row = 0; row < this.symbols.length; row++) {
          const y = this.headerHeight + row * cellHeight;
          if (y + cellHeight < -this.offsetY || y > height - this.offsetY) continue;
          ctx.fillStyle = '#cbd5e1';
          ctx.fillText(this.symbols[row], 8, y + cellHeight / 2);
        }

        // Cells
        for (let row = 0; row < this.symbols.length; row++) {
          const y = this.headerHeight + row * cellHeight;
          if (y + cellHeight < -this.offsetY || y > height - this.offsetY) continue;

          for (let col = 0; col < this.timeBuckets; col++) {
            const x = this.rowLabelWidth + col * cellWidth;
            if (x + cellWidth < -this.offsetX || x > width - this.offsetX) continue;

            const value = this.data[row][col];
            ctx.fillStyle = this.getColor(value);
            ctx.fillRect(x, y, cellWidth - 1, cellHeight - 1);

            if (
              this.hoveredCell &&
              this.hoveredCell.row === row &&
              this.hoveredCell.col === col
            ) {
              ctx.strokeStyle = '#f8fafc';
              ctx.lineWidth = 2;
              ctx.strokeRect(x + 1, y + 1, cellWidth - 3, cellHeight - 3);
            }
          }
        }

        ctx.restore();
      }

      pushUpdate(symbolIndex, newValue) {
        const row = this.data[symbolIndex];
        row.shift();
        row.push(newValue);
        this.render();
      }

      resetView() {
        this.scale = 1;
        this.offsetX = 0;
        this.offsetY = 0;
        this.render();
      }
    }

    function generateSymbols(count) {
      const base = ['AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA', 'NVDA', 'META', 'NFLX', 'AMD', 'INTC'];
      const symbols = [];
      for (let i = 0; i < count; i++) {
        symbols.push(base[i % base.length] + (i >= base.length ? i : ''));
      }
      return symbols;
    }

    function generateInitialData(rows, cols) {
      return Array.from({ length: rows }, () =>
        Array.from({ length: cols }, () => (Math.random() * 10 - 5))
      );
    }

    function nextValue(prev) {
      const drift = (Math.random() - 0.5) * 1.2;
      return Math.max(-5, Math.min(5, prev + drift));
    }

    const symbols = generateSymbols(40);
    const timeBuckets = 80;
    const data = generateInitialData(symbols.length, timeBuckets);

    const canvas = document.getElementById('heatmapCanvas');
    const container = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');
    const statusText = document.getElementById('statusText');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');

    const heatmap = new StockHeatmap(canvas, container, tooltip, {
      symbols,
      timeBuckets,
      data
    });

    let streaming = true;
    let tick = 0;

    const interval = setInterval(() => {
      if (!streaming) return;

      for (let i = 0; i < symbols.length; i++) {
        const prev = heatmap.data[i][heatmap.data[i].length - 1];
        heatmap.pushUpdate(i, nextValue(prev));
      }

      tick++;
      statusText.textContent = `Streaming live updates... tick ${tick}`;
    }, 1000);

    resetViewBtn.addEventListener('click', () => {
      heatmap.resetView();
    });

    toggleStreamBtn.addEventListener('click', () => {
      streaming = !streaming;
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
      statusText.textContent = streaming ? `Streaming live updates... tick ${tick}` : 'Stream paused';
    });
  </script>
