  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.dpr = Math.max(1, window.devicePixelRatio || 1);

        this.symbols = [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
          'META', 'TSLA', 'AMD', 'NFLX', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'PYPL'
        ];

        this.timeSteps = 120;
        this.data = [];
        this.timestamps = [];
        this.basePrices = new Map();

        this.cellWidth = 14;
        this.cellHeight = 24;
        this.offsetX = 0;
        this.offsetY = 0;
        this.minCellWidth = 4;
        this.maxCellWidth = 60;
        this.minCellHeight = 12;
        this.maxCellHeight = 50;

        this.leftAxisWidth = 80;
        this.topAxisHeight = 30;

        this.isDragging = false;
        this.lastMouse = { x: 0, y: 0 };
        this.hoveredCell = null;

        this.running = true;
        this.updateInterval = 500;
        this.volatility = 1.5;
        this.timer = null;

        this.initData();
        this.attachEvents();
        this.resize();
        this.start();
      }

      initData() {
        const now = Date.now();

        this.symbols.forEach(symbol => {
          this.basePrices.set(symbol, 100 + Math.random() * 300);
        });

        this.timestamps = [];
        for (let i = 0; i < this.timeSteps; i++) {
          this.timestamps.push(now - (this.timeSteps - i) * 1000);
        }

        this.data = this.symbols.map(symbol => {
          let price = this.basePrices.get(symbol);
          const row = [];
          for (let i = 0; i < this.timeSteps; i++) {
            const delta = (Math.random() - 0.5) * this.volatility * 2;
            price = Math.max(1, price + delta);
            row.push({
              price,
              change: delta
            });
          }
          this.basePrices.set(symbol, price);
          return row;
        });
      }

      start() {
        this.stop();
        this.timer = setInterval(() => {
          if (this.running) {
            this.pushTick();
            this.render();
          }
        }, this.updateInterval);
      }

      stop() {
        if (this.timer) {
          clearInterval(this.timer);
          this.timer = null;
        }
      }

      setUpdateInterval(ms) {
        this.updateInterval = ms;
        this.start();
      }

      setVolatility(v) {
        this.volatility = v;
      }

      pushTick() {
        const ts = Date.now();
        this.timestamps.push(ts);
        if (this.timestamps.length > this.timeSteps) {
          this.timestamps.shift();
        }

        this.symbols.forEach((symbol, rowIndex) => {
          let lastPrice = this.basePrices.get(symbol);
          const delta = (Math.random() - 0.5) * this.volatility * 2;
          const nextPrice = Math.max(1, lastPrice + delta);
          this.basePrices.set(symbol, nextPrice);

          this.data[rowIndex].push({
            price: nextPrice,
            change: delta
          });

          if (this.data[rowIndex].length > this.timeSteps) {
            this.data[rowIndex].shift();
          }
        });
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.lastMouse = { x: e.offsetX, y: e.offsetY };
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.isDragging) {
            const dx = x - this.lastMouse.x;
            const dy = y - this.lastMouse.y;
            this.offsetX += dx;
            this.offsetY += dy;
            this.lastMouse = { x, y };
            this.render();
          } else {
            this.updateHover(x, y);
          }
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.hoveredCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          const mouseX = e.offsetX;
          const mouseY = e.offsetY;

          const prevCellWidth = this.cellWidth;
          const prevCellHeight = this.cellHeight;

          this.cellWidth = Math.min(this.maxCellWidth, Math.max(this.minCellWidth, this.cellWidth * zoomFactor));
          this.cellHeight = Math.min(this.maxCellHeight, Math.max(this.minCellHeight, this.cellHeight * zoomFactor));

          const scaleX = this.cellWidth / prevCellWidth;
          const scaleY = this.cellHeight / prevCellHeight;

          this.offsetX = mouseX - (mouseX - this.offsetX) * scaleX;
          this.offsetY = mouseY - (mouseY - this.offsetY) * scaleY;

          this.render();
        }, { passive: false });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      resetView() {
        this.cellWidth = 14;
        this.cellHeight = 24;
        this.offsetX = 0;
        this.offsetY = 0;
        this.render();
      }

      updateHover(x, y) {
        const gridX = x - this.leftAxisWidth - this.offsetX;
        const gridY = y - this.topAxisHeight - this.offsetY;

        const col = Math.floor(gridX / this.cellWidth);
        const row = Math.floor(gridY / this.cellHeight);

        if (
          row >= 0 && row < this.symbols.length &&
          col >= 0 && col < this.timeSteps
        ) {
          const cell = this.data[row][col];
          const symbol = this.symbols[row];
          const ts = this.timestamps[col];

          this.hoveredCell = { row, col };

          this.tooltip.style.display = 'block';
          this.tooltip.style.left = `${x}px`;
          this.tooltip.style.top = `${y}px`;
          this.tooltip.innerHTML = `
            <div><strong>${symbol}</strong></div>
            <div>Price: ${cell.price.toFixed(2)}</div>
            <div>Change: ${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}</div>
            <div>Time: ${new Date(ts).toLocaleTimeString()}</div>
          `;
        } else {
          this.hoveredCell = null;
          this.tooltip.style.display = 'none';
        }

        this.render();
      }

      getColor(change) {
        const maxAbs = Math.max(0.01, this.volatility * 1.5);
        const normalized = Math.max(-1, Math.min(1, change / maxAbs));

        if (normalized >= 0) {
          const t = normalized;
          const r = Math.round(80 - 50 * t);
          const g = Math.round(80 + 120 * t);
          const b = Math.round(80 - 40 * t);
          return `rgb(${r}, ${g}, ${b})`;
        } else {
          const t = Math.abs(normalized);
          const r = Math.round(80 + 120 * t);
          const g = Math.round(80 - 50 * t);
          const b = Math.round(80 - 50 * t);
          return `rgb(${r}, ${g}, ${b})`;
        }
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);

        ctx.fillStyle = '#121a30';
        ctx.fillRect(0, 0, width, height);

        const gridStartX = this.leftAxisWidth + this.offsetX;
        const gridStartY = this.topAxisHeight + this.offsetY;

        const visibleCols = Math.ceil((width - this.leftAxisWidth) / this.cellWidth) + 2;
        const visibleRows = Math.ceil((height - this.topAxisHeight) / this.cellHeight) + 2;

        const startCol = Math.max(0, Math.floor((-this.offsetX) / this.cellWidth));
        const startRow = Math.max(0, Math.floor((-this.offsetY) / this.cellHeight));
        const endCol = Math.min(this.timeSteps, startCol + visibleCols);
        const endRow = Math.min(this.symbols.length, startRow + visibleRows);

        for (let row = startRow; row < endRow; row++) {
          for (let col = startCol; col < endCol; col++) {
            const x = gridStartX + col * this.cellWidth;
            const y = gridStartY + row * this.cellHeight;
            const cell = this.data[row][col];

            ctx.fillStyle = this.getColor(cell.change);
            ctx.fillRect(x, y, this.cellWidth - 1, this.cellHeight - 1);

            if (this.hoveredCell && this.hoveredCell.row === row && this.hoveredCell.col === col) {
              ctx.strokeStyle = '#ffffff';
              ctx.lineWidth = 2;
              ctx.strokeRect(x + 1, y + 1, this.cellWidth - 3, this.cellHeight - 3);
            }
          }
        }

        ctx.fillStyle = '#0f1730';
        ctx.fillRect(0, 0, this.leftAxisWidth, height);
        ctx.fillRect(0, 0, width, this.topAxisHeight);

        ctx.strokeStyle = '#2a3658';
        ctx.beginPath();
        ctx.moveTo(this.leftAxisWidth + 0.5, 0);
        ctx.lineTo(this.leftAxisWidth + 0.5, height);
        ctx.moveTo(0, this.topAxisHeight + 0.5);
        ctx.lineTo(width, this.topAxisHeight + 0.5);
        ctx.stroke();

        ctx.fillStyle = '#dbe4ff';
        ctx.font = '12px Inter, sans-serif';
        ctx.textBaseline = 'middle';

        for (let row = startRow; row < endRow; row++) {
          const y = gridStartY + row * this.cellHeight + this.cellHeight / 2;
          if (y >= this.topAxisHeight && y <= height) {
            ctx.fillText(this.symbols[row], 10, y);
          }
        }

        ctx.textBaseline = 'top';
        for (let col = startCol; col < endCol; col++) {
          const x = gridStartX + col * this.cellWidth;
          if (x + this.cellWidth >= this.leftAxisWidth && x <= width) {
            if (col % Math.max(1, Math.floor(50 / this.cellWidth)) === 0) {
              const ts = this.timestamps[col];
              const label = new Date(ts).toLocaleTimeString([], {
                minute: '2-digit',
                second: '2-digit'
              });
              ctx.save();
              ctx.translate(x + 4, 4);
              ctx.rotate(-Math.PI / 4);
              ctx.fillText(label, 0, 0);
              ctx.restore();
            }
          }
        }

        this.statusEl.textContent =
          `Symbols: ${this.symbols.length} | Time buckets: ${this.timeSteps} | Zoom: ${this.cellWidth.toFixed(1)}x${this.cellHeight.toFixed(1)}`;
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const status = document.getElementById('status');

    const heatmap = new StockHeatmap(canvas, tooltip, status);

    const intervalInput = document.getElementById('intervalInput');
    const volatilityInput = document.getElementById('volatilityInput');
    const toggleBtn = document.getElementById('toggleBtn');
    const resetViewBtn = document.getElementById('resetViewBtn');

    intervalInput.addEventListener('change', () => {
      const value = Math.max(100, Number(intervalInput.value) || 500);
      heatmap.setUpdateInterval(value);
    });

    volatilityInput.addEventListener('change', () => {
      const value = Math.max(0.1, Number(volatilityInput.value) || 1.5);
      heatmap.setVolatility(value);
    });

    toggleBtn.addEventListener('click', () => {
      heatmap.running = !heatmap.running;
      toggleBtn.textContent = heatmap.running ? 'Pause' : 'Resume';
    });

    resetViewBtn.addEventListener('click', () => {
      heatmap.resetView();
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each cell stores:

```js
{
  price: Number,
  change: Number
}
```

- `price` = simulated current stock price
- `change` = latest delta used for coloring

### Real-time updates
Every interval:

- a new timestamp is appended
- each stock gets a new simulated price
- oldest column is removed
- newest column appears on the right

### Zoom/pan
- **Mouse wheel** scales `cellWidth` and `cellHeight`
- **Mouse drag** adjusts `offsetX` and `offsetY`

### Rendering
The heatmap is drawn on a `<canvas>` for smoother updates and better scalability than a large DOM grid.

