      color: var(--muted);
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      margin-bottom: 6px;
      background: linear-gradient(
        to right,
        rgb(180, 40, 40),
        rgb(80, 80, 80),
        rgb(40, 180, 90)
      );
      border: 1px solid rgba(255,255,255,0.08);
    }

    .legend-labels {
      display: flex;
      justify-content: space-between;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <div class="title">Realtime Stock Heatmap</div>
      <div class="stat" id="status">Streaming: ON</div>
      <div class="stat" id="zoomStat">Zoom: 1.00x</div>
      <button id="toggleStream">Pause Stream</button>
      <button id="resetView">Reset View</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-3%</span>
          <span>0%</span>
          <span>+3%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('chartWrap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const zoomStatEl = document.getElementById('zoomStat');
    const toggleStreamBtn = document.getElementById('toggleStream');
    const resetViewBtn = document.getElementById('resetView');

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'IBM', 'UBER', 'SHOP', 'CRM'
    ];

    const state = {
      rows: symbols.length,
      cols: 240,
      cellData: [],
      prices: {},
      baselinePrices: {},
      streaming: true,
      zoomX: 1,
      minZoomX: 1,
      maxZoomX: 12,
      panX: 0,
      isDragging: false,
      dragStartX: 0,
      dragStartPanX: 0,
      hover: null,
      lastTimestamp: Date.now(),
      timeLabels: []
    };

    function initData() {
      state.cellData = Array.from({ length: state.rows }, () =>
        Array.from({ length: state.cols }, () => null)
      );

      const now = Date.now();
      state.timeLabels = Array.from({ length: state.cols }, (_, i) => {
        return now - (state.cols - 1 - i) * 1000;
      });

      symbols.forEach(symbol => {
        const base = 100 + Math.random() * 400;
        state.prices[symbol] = base;
        state.baselinePrices[symbol] = base;

        for (let c = 0; c < state.cols; c++) {
          const drift = (Math.random() - 0.5) * 0.8;
          state.prices[symbol] *= (1 + drift / 100);
          const pct = ((state.prices[symbol] - state.baselinePrices[symbol]) / state.baselinePrices[symbol]) * 100;
          state.cellData[symbols.indexOf(symbol)][c] = {
            symbol,
            price: state.prices[symbol],
            pctChange: pct,
            ts: state.timeLabels[c]
          };
        }

        state.baselinePrices[symbol] = state.prices[symbol];
      });
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * DPR);
      canvas.height = Math.floor(rect.height * DPR);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function colorForPct(pct) {
      const clamped = clamp(pct, -3, 3);
      if (clamped < 0) {
        const t = (clamped + 3) / 3;
        const r = 180 * (1 - t) + 80 * t;
        const g = 40 * (1 - t) + 80 * t;
        const b = 40 * (1 - t) + 80 * t;
        return `rgb(${r|0}, ${g|0}, ${b|0})`;
      } else {
        const t = clamped / 3;
        const r = 80 * (1 - t) + 40 * t;
        const g = 80 * (1 - t) + 180 * t;
        const b = 80 * (1 - t) + 90 * t;
        return `rgb(${r|0}, ${g|0}, ${b|0})`;
      }
    }

    function getLayout() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;

      const leftPad = 70;
      const topPad = 30;
      const rightPad = 20;
      const bottomPad = 40;

      const plotWidth = width - leftPad - rightPad;
      const plotHeight = height - topPad - bottomPad;

      const rowHeight = plotHeight / state.rows;
      const visibleCols = state.cols / state.zoomX;
      const cellWidth = plotWidth / visibleCols;
      const maxPan = Math.max(0, state.cols - visibleCols);

      state.panX = clamp(state.panX, 0, maxPan);

      return {
        width,
        height,
        leftPad,
        topPad,
        rightPad,
        bottomPad,
        plotWidth,
        plotHeight,
        rowHeight,
        cellWidth,
        visibleCols,
        startCol: Math.floor(state.panX),
        endCol: Math.min(state.cols, Math.ceil(state.panX + visibleCols)),
        maxPan
      };
    }

    function drawAxes(layout) {
      const {
        leftPad, topPad, plotWidth, plotHeight, rowHeight, startCol, endCol, cellWidth
      } = layout;

      ctx.strokeStyle = '#2a3658';
      ctx.lineWidth = 1;

      ctx.strokeRect(leftPad, topPad, plotWidth, plotHeight);

      ctx.font = '12px sans-serif';
      ctx.fillStyle = '#8ea0c9';
      ctx.textBaseline = 'middle';

      for (let r = 0; r < state.rows; r++) {
        const y = topPad + r * rowHeight;
        ctx.strokeStyle = '#1f2a44';
        ctx.beginPath();
        ctx.moveTo(leftPad, y);
        ctx.lineTo(leftPad + plotWidth, y);
        ctx.stroke();

        ctx.fillText(symbols[r], 10, y + rowHeight / 2);
      }

      const timeTickCount = Math.min(8, endCol - startCol);
      for (let i = 0; i <= timeTickCount; i++) {
        const col = startCol + ((endCol - startCol) * i / timeTickCount);
        const x = leftPad + (col - state.panX) * cellWidth;

        ctx.strokeStyle = '#1f2a44';
        ctx.beginPath();
        ctx.moveTo(x, topPad);
        ctx.lineTo(x, topPad + plotHeight);
        ctx.stroke();

        const idx = clamp(Math.round(col), 0, state.cols - 1);
        const label = formatTime(state.timeLabels[idx]);
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(label, x, topPad + plotHeight + 8);
      }
    }

    function drawCells(layout) {
      const { leftPad, topPad, rowHeight, cellWidth, startCol, endCol } = layout;

      for (let r = 0; r < state.rows; r++) {
        for (let c = startCol; c < endCol; c++) {
          const cell = state.cellData[r][c];
          if (!cell) continue;

          const x = leftPad + (c - state.panX) * cellWidth;
          const y = topPad + r * rowHeight;

          ctx.fillStyle = colorForPct(cell.pctChange);
          ctx.fillRect(x, y, Math.ceil(cellWidth), Math.ceil(rowHeight));

          if (state.hover && state.hover.row === r && state.hover.col === c) {
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, Math.max(0, cellWidth - 2), Math.max(0, rowHeight - 2));
          }
        }
      }
    }

    function draw() {
      const layout = getLayout();
      ctx.clearRect(0, 0, canvas.width / DPR, canvas.height / DPR);

      drawCells(layout);
      drawAxes(layout);

      zoomStatEl.textContent = `Zoom: ${state.zoomX.toFixed(2)}x`;
    }

    function pushNewColumn() {
      const ts = Date.now();
      state.timeLabels.shift();
      state.timeLabels.push(ts);

      for (let r = 0; r < state.rows; r++) {
        const symbol = symbols[r];
        const prev = state.prices[symbol];
        const move = (Math.random() - 0.5) * 1.2;
        const next = prev * (1 + move / 100);
        state.prices[symbol] = next;

        const pctChange = ((next - prev) / prev) * 100;

        state.cellData[r].shift();
        state.cellData[r].push({
          symbol,
          price: next,
          pctChange,
          ts
        });
      }

      if (state.zoomX === 1) {
        state.panX = 0;
      }
    }

    function screenToCell(mx, my) {
      const layout = getLayout();
      const { leftPad, topPad, plotWidth, plotHeight, rowHeight, cellWidth } = layout;

      if (
        mx < leftPad || mx > leftPad + plotWidth ||
        my < topPad || my > topPad + plotHeight
      ) {
        return null;
      }

      const row = Math.floor((my - topPad) / rowHeight);
      const col = Math.floor(state.panX + (mx - leftPad) / cellWidth);

      if (row < 0 || row >= state.rows || col < 0 || col >= state.cols) return null;

      return { row, col };
    }

    function updateTooltip(mx, my) {
      const hit = screenToCell(mx, my);
      state.hover = hit;

      if (!hit) {
        tooltip.style.display = 'none';
        draw();
        return;
      }

      const cell = state.cellData[hit.row][hit.col];
      if (!cell) {
        tooltip.style.display = 'none';
        draw();
        return;
      }

      tooltip.style.display = 'block';
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: ${cell.pctChange >= 0 ? '+' : ''}${cell.pctChange.toFixed(2)}%</div>
        <div>Time: ${formatTime(cell.ts)}</div>
      `;

      draw();
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (state.isDragging) {
        const layout = getLayout();
        const dx = mx - state.dragStartX;
        const deltaCols = dx / layout.cellWidth;
        state.panX = clamp(state.dragStartPanX - deltaCols, 0, layout.maxPan);
        draw();
        return;
      }

      updateTooltip(mx, my);
    });

    canvas.addEventListener('mouseleave', () => {
      state.hover = null;
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      canvas.classList.add('dragging');
      state.dragStartX = e.offsetX;
      state.dragStartPanX = state.panX;
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const layout = getLayout();
      const mouseColBefore = state.panX + (mx - layout.leftPad) / layout.cellWidth;

      const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
      const nextZoom = clamp(state.zoomX * zoomFactor, state.minZoomX, state.maxZoomX);

      if (nextZoom === state.zoomX) return;

      state.zoomX = nextZoom;

      const nextLayout = getLayout();
      state.panX = mouseColBefore - (mx - nextLayout.leftPad) / nextLayout.cellWidth;
      state.panX = clamp(state.panX, 0, nextLayout.maxPan);

      draw();
    }, { passive: false });

    toggleStreamBtn.addEventListener('click', () => {
      state.streaming = !state.streaming;
      statusEl.textContent = `Streaming: ${state.streaming ? 'ON' : 'OFF'}`;
      toggleStreamBtn.textContent = state.streaming ? 'Pause Stream' : 'Resume Stream';
    });

    resetViewBtn.addEventListener('click', () => {
      state.zoomX = 1;
      state.panX = 0;
      draw();
    });

    initData();
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    setInterval(() => {
      if (!state.streaming) return;
      pushNewColumn();
      draw();
    }, 500);
  </script>
</body>
</html>
```

