<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>

      <button id="toggleStreamBtn">Pause Stream</button>
      <button id="resetViewBtn">Reset View</button>

      <label>
        Window:
        <select id="windowSizeSelect">
          <option value="60">60 ticks</option>
          <option value="120" selected>120 ticks</option>
          <option value="240">240 ticks</option>
          <option value="480">480 ticks</option>
        </select>
      </label>

      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>

      <div class="status" id="statusText">Streaming...</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;

        this.symbols = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'NVDA',
          'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
          'CRM', 'ORCL', 'IBM', 'UBER', 'SHOP'
        ];

        this.maxTicks = 120;
        this.data = [];
        this.streaming = true;
        this.tickIndex = 0;

        this.basePrices = {};
        this.lastPrices = {};

        this.margin = {
          top: 30,
          right: 20,
          bottom: 40,
          left: 80
        };

        this.view = {
          scaleX: 1,
          offsetX: 0
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          hoverCell: null
        };

        this.devicePixelRatio = window.devicePixelRatio || 1;

        this.initPrices();
        this.seedInitialData();
        this.bindEvents();
        this.resize();
        this.startStream();
        this.renderLoop();
      }

      initPrices() {
        for (const symbol of this.symbols) {
          const base = 50 + Math.random() * 250;
          this.basePrices[symbol] = base;
          this.lastPrices[symbol] = base;
        }
      }

      seedInitialData() {
        for (let i = 0; i < this.maxTicks; i++) {
          this.pushNextTick();
        }
      }

      pushNextTick() {
        const row = {
          time: Date.now(),
          values: {}
        };

        for (const symbol of this.symbols) {
          const prev = this.lastPrices[symbol];
          const drift = (Math.random() - 0.5) * 0.01;
          const volatility = (Math.random() - 0.5) * 0.03;
          const next = Math.max(1, prev * (1 + drift + volatility));
          this.lastPrices[symbol] = next;

          const pctChange = ((next - this.basePrices[symbol]) / this.basePrices[symbol]) * 100;

          row.values[symbol] = {
            price: next,
            pctChange
          };
        }

        this.data.push(row);
        if (this.data.length > this.maxTicks) {
          this.data.shift();
        }

        this.tickIndex++;
      }

      startStream() {
        this.streamInterval = setInterval(() => {
          if (!this.streaming) return;
          this.pushNextTick();
        }, 400);
      }

      stopStream() {
        clearInterval(this.streamInterval);
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const plotWidth = this.width - this.margin.left - this.margin.right;
          const plotX = mouseX - this.margin.left;

          if (plotX < 0 || plotX > plotWidth) return;

          const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
          const oldScale = this.view.scaleX;
          const newScale = Math.min(8, Math.max(1, oldScale * zoomFactor));

          const worldXBefore = (plotX / oldScale) + this.view.offsetX;
          this.view.scaleX = newScale;
          this.view.offsetX = worldXBefore - (plotX / newScale);

          this.clampView();
        }, { passive: false });

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            this.interaction.lastX = e.clientX;

            this.view.offsetX -= dx / this.getCellWidth();
            this.clampView();
          }

          this.updateHover(x, y);
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
        });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(this.width * this.devicePixelRatio);
        this.canvas.height = Math.floor(this.height * this.devicePixelRatio);
        this.ctx.setTransform(this.devicePixelRatio, 0, 0, this.devicePixelRatio, 0, 0);
      }

      getPlotWidth() {
        return this.width - this.margin.left - this.margin.right;
      }

      getPlotHeight() {
        return this.height - this.margin.top - this.margin.bottom;
      }

      getVisibleTickCount() {
        return this.data.length / this.view.scaleX;
      }

      getCellWidth() {
        return this.getPlotWidth() / this.getVisibleTickCount();
      }

      getCellHeight() {
        return this.getPlotHeight() / this.symbols.length;
      }

      clampView() {
        const visible = this.getVisibleTickCount();
        const maxOffset = Math.max(0, this.data.length - visible);
        this.view.offsetX = Math.max(0, Math.min(maxOffset, this.view.offsetX));
      }

      resetView() {
        this.view.scaleX = 1;
        this.view.offsetX = 0;
      }

      setWindowSize(size) {
        this.maxTicks = size;
        while (this.data.length > this.maxTicks) {
          this.data.shift();
        }
        this.resetView();
      }

      updateHover(mouseX, mouseY) {
        const plotX = mouseX - this.margin.left;
        const plotY = mouseY - this.margin.top;

        if (
          plotX < 0 ||
          plotY < 0 ||
          plotX > this.getPlotWidth() ||
          plotY > this.getPlotHeight()
        ) {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
          return;
        }

        const cellWidth = this.getCellWidth();
        const cellHeight = this.getCellHeight();

        const col = Math.floor(plotX / cellWidth);
        const row = Math.floor(plotY / cellHeight);

        const visibleStart = Math.floor(this.view.offsetX);
        const dataIndex = visibleStart + col;
        const symbol = this.symbols[row];
        const tick = this.data[dataIndex];

        if (!tick || !symbol || !tick.values[symbol]) {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
          return;
        }

        this.interaction.hoverCell = { row, col, dataIndex, symbol, tick };

        const value = tick.values[symbol];
        const time = new Date(tick.time).toLocaleTimeString();

        this.tooltip.innerHTML = `
          <div><strong>${symbol}</strong></div>
          <div>Price: $${value.price.toFixed(2)}</div>
          <div>Change: ${value.pctChange.toFixed(2)}%</div>
          <div>Time: ${time}</div>
        `;
        this.tooltip.style.left = `${mouseX}px`;
        this.tooltip.style.top = `${mouseY}px`;
        this.tooltip.style.display = 'block';
      }

      colorForPctChange(pct) {
        const clamped = Math.max(-5, Math.min(5, pct));
        const t = (clamped + 5) / 10;

        const red = { r: 180, g: 30, b: 30 };
        const mid = { r: 80, g: 80, b: 80 };
        const green = { r: 30, g: 180, b: 60 };

        let c1, c2, localT;
        if (t < 0.5) {
          c1 = red;
          c2 = mid;
          localT = t / 0.5;
        } else {
          c1 = mid;
          c2 = green;
          localT = (t - 0.5) / 0.5;
        }

        const r = Math.round(c1.r + (c2.r - c1.r) * localT);
        const g = Math.round(c1.g + (c2.g - c1.g) * localT);
        const b = Math.round(c1.b + (c2.b - c1.b) * localT);

        return `rgb(${r}, ${g}, ${b})`;
      }

      drawAxes() {
        const ctx = this.ctx;
        const plotWidth = this.getPlotWidth();
        const plotHeight = this.getPlotHeight();
        const cellHeight = this.getCellHeight();
        const cellWidth = this.getCellWidth();

        ctx.save();
        ctx.strokeStyle = '#334155';
        ctx.fillStyle = '#94a3b8';
        ctx.lineWidth = 1;
        ctx.font = '12px sans-serif';

        ctx.beginPath();
        ctx.moveTo(this.margin.left, this.margin.top);
        ctx.lineTo(this.margin.left, this.margin.top + plotHeight);
        ctx.lineTo(this.margin.left + plotWidth, this.margin.top + plotHeight);
        ctx.stroke();

        for (let i = 0; i < this.symbols.length; i++) {
          const y = this.margin.top + i * cellHeight + cellHeight / 2;
          ctx.fillText(this.symbols[i], 10, y + 4);

          ctx.strokeStyle = 'rgba(51, 65, 85, 0.35)';
          ctx.beginPath();
          ctx.moveTo(this.margin.left, this.margin.top + i * cellHeight);
          ctx.lineTo(this.margin.left + plotWidth, this.margin.top + i * cellHeight);
          ctx.stroke();
        }

        const visibleStart = Math.floor(this.view.offsetX);
        const visibleCount = Math.ceil(this.getVisibleTickCount());

        const labelStep = Math.max(1, Math.floor(visibleCount / 8));
        for (let i = 0; i < visibleCount; i += labelStep) {
          const dataIndex = visibleStart + i;
          const tick = this.data[dataIndex];
          if (!tick) continue;

          const x = this.margin.left + i * cellWidth;
          const timeLabel = new Date(tick.time).toLocaleTimeString();

          ctx.strokeStyle = 'rgba(51, 65, 85, 0.35)';
          ctx.beginPath();
          ctx.moveTo(x, this.margin.top);
          ctx.lineTo(x, this.margin.top + plotHeight);
          ctx.stroke();

          ctx.save();
          ctx.translate(x + 4, this.margin.top + plotHeight + 14);
          ctx.rotate(-0.35);
          ctx.fillStyle = '#94a3b8';
          ctx.fillText(timeLabel, 0, 0);
          ctx.restore();
        }

        ctx.restore();
      }

      drawCells() {
        const ctx = this.ctx;
        const cellWidth = this.getCellWidth();
        const cellHeight = this.getCellHeight();
        const visibleStart = Math.floor(this.view.offsetX);
        const visibleCount = Math.ceil(this.getVisibleTickCount());

        for (let col = 0; col < visibleCount; col++) {
          const dataIndex = visibleStart + col;
          const tick = this.data[dataIndex];
          if (!tick) continue;

          for (let row = 0; row < this.symbols.length; row++) {
            const symbol = this.symbols[row];
            const value = tick.values[symbol];
            if (!value) continue;

            const x = this.margin.left + col * cellWidth;
            const y = this.margin.top + row * cellHeight;

            ctx.fillStyle = this.colorForPctChange(value.pctChange);
            ctx.fillRect(x, y, Math.ceil(cellWidth), Math.ceil(cellHeight));

            ctx.strokeStyle = 'rgba(2, 6, 23, 0.35)';
            ctx.strokeRect(x, y, Math.ceil(cellWidth), Math.ceil(cellHeight));

            if (
              this.interaction.hoverCell &&
              this.interaction.hoverCell.dataIndex === dataIndex &&
              this.interaction.hoverCell.row === row
            ) {
              ctx.strokeStyle = '#ffffff';
              ctx.lineWidth = 2;
              ctx.strokeRect(x + 1, y + 1, Math.max(0, cellWidth - 2), Math.max(0, cellHeight - 2));
              ctx.lineWidth = 1;
            }
          }
        }
      }

      drawTitle() {
        const ctx = this.ctx;
        ctx.save();
        ctx.fillStyle = '#e5e7eb';
        ctx.font = 'bold 14px sans-serif';
        ctx.fillText('Price Change Heatmap (%)', this.margin.left, 18);
        ctx.restore();
      }

      render() {
        this.ctx.clearRect(0, 0, this.width, this.height);
        this.drawTitle();
        this.drawCells();
        this.drawAxes();
      }

      renderLoop() {
        const loop = () => {
          this.render();
          this.statusEl.textContent = this.streaming
            ? `Streaming... ${this.data.length} ticks`
            : `Paused ${this.data.length} ticks`;
          requestAnimationFrame(loop);
        };
        requestAnimationFrame(loop);
      }
    }

    const canvas = document.getElementById('heatmapCanvas');
    const tooltip = document.getElementById('tooltip');
    const statusText = document.getElementById('statusText');

    const heatmap = new StockHeatmap(canvas, tooltip, statusText);

    document.getElementById('toggleStreamBtn').addEventListener('click', (e) => {
      heatmap.streaming = !heatmap.streaming;
      e.target.textContent = heatmap.streaming ? 'Pause Stream' : 'Resume Stream';
    });

    document.getElementById('resetViewBtn').addEventListener('click', () => {
      heatmap.resetView();
    });

    document.getElementById('windowSizeSelect').addEventListener('change', (e) => {
      heatmap.setWindowSize(Number(e.target.value));
    });
  </script>
</body>
</html>
