      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(20, 24, 40, 0.96);
      color: var(--text);
      border: 1px solid #3a426d;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      white-space: nowrap;
      transform: translate(10px, 10px);
      display: none;
      z-index: 10;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
      font-size: 12px;
      color: var(--muted);
    }

    .legend-bar {
      width: 180px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(
        90deg,
        #8b0000 0%,
        #ff5c7a 25%,
        #2b3355 50%,
        #19c37d 75%,
        #006b3c 100%
      );
      border: 1px solid #3a426d;
    }

    .hint {
      font-size: 12px;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="stat" id="status">Streaming: ON</div>
      <button id="toggleStream">Pause Stream</button>
      <button id="resetView">Reset View</button>
      <div class="hint">Wheel = zoom, drag = pan, hover = inspect</div>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "CRM", "ORCL", "UBER", "SHOP", "BABA", "PYPL",
      "JPM", "GS", "V", "MA", "DIS", "PEP", "KO", "NKE"
    ];

    const timePoints = 120; // columns
    const rows = symbols.length;

    // Heatmap data: each row is a stock, each column is a time bucket
    const data = symbols.map(() => {
      const arr = [];
      let current = (Math.random() - 0.5) * 2;
      for (let i = 0; i < timePoints; i++) {
        current += (Math.random() - 0.5) * 0.6;
        current = clamp(current, -5, 5);
        arr.push(current);
      }
      return arr;
    });

    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("canvasWrap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleStreamBtn = document.getElementById("toggleStream");
    const resetViewBtn = document.getElementById("resetView");

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    const margin = {
      top: 30,
      right: 20,
      bottom: 30,
      left: 80
    };

    const view = {
      offsetX: 0,
      offsetY: 0,
      scaleX: 1,
      scaleY: 1
    };

    const minScaleX = 0.5;
    const maxScaleX = 8;
    const minScaleY = 0.75;
    const maxScaleY = 4;

    let isDragging = false;
    let lastMouseX = 0;
    let lastMouseY = 0;
    let streaming = true;
    let hoveredCell = null;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function colorForValue(value) {
      // Map -5..5 to 0..1
      const t = clamp((value + 5) / 10, 0, 1);

      // 3-stop gradient: red -> neutral -> green
      if (t < 0.5) {
        const local = t / 0.5;
        return mixColor([255, 92, 122], [43, 51, 85], local);
      } else {
        const local = (t - 0.5) / 0.5;
        return mixColor([43, 51, 85], [25, 195, 125], local);
      }
    }

    function mixColor(c1, c2, t) {
      const r = Math.round(lerp(c1[0], c2[0], t));
      const g = Math.round(lerp(c1[1], c2[1], t));
      const b = Math.round(lerp(c1[2], c2[2], t));
      return `rgb(${r}, ${g}, ${b})`;
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      dpr = window.devicePixelRatio || 1;

      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function getPlotArea() {
      return {
        x: margin.left,
        y: margin.top,
        w: width - margin.left - margin.right,
        h: height - margin.top - margin.bottom
      };
    }

    function getCellSize() {
      const plot = getPlotArea();
      return {
        cellW: (plot.w / timePoints) * view.scaleX,
        cellH: (plot.h / rows) * view.scaleY
      };
    }

    function getMaxOffsets() {
      const plot = getPlotArea();
      const { cellW, cellH } = getCellSize();
      const contentW = cellW * timePoints;
      const contentH = cellH * rows;

      return {
        maxOffsetX: Math.max(0, contentW - plot.w),
        maxOffsetY: Math.max(0, contentH - plot.h)
      };
    }

    function constrainView() {
      const { maxOffsetX, maxOffsetY } = getMaxOffsets();
      view.offsetX = clamp(view.offsetX, 0, maxOffsetX);
      view.offsetY = clamp(view.offsetY, 0, maxOffsetY);
      view.scaleX = clamp(view.scaleX, minScaleX, maxScaleX);
      view.scaleY = clamp(view.scaleY, minScaleY, maxScaleY);
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#0f1220";
      ctx.fillRect(0, 0, width, height);

      const plot = getPlotArea();
      const { cellW, cellH } = getCellSize();

      // Plot background
      ctx.fillStyle = "#12162a";
      ctx.fillRect(plot.x, plot.y, plot.w, plot.h);

      // Clip to plot area
      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.clip();

      const startCol = Math.max(0, Math.floor(view.offsetX / cellW));
      const endCol = Math.min(timePoints, Math.ceil((view.offsetX + plot.w) / cellW));
      const startRow = Math.max(0, Math.floor(view.offsetY / cellH));
      const endRow = Math.min(rows, Math.ceil((view.offsetY + plot.h) / cellH));

      for (let r = startRow; r < endRow; r++) {
        for (let c = startCol; c < endCol; c++) {
          const x = plot.x + c * cellW - view.offsetX;
          const y = plot.y + r * cellH - view.offsetY;
          const value = data[r][c];

          ctx.fillStyle = colorForValue(value);
          ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));

          if (cellW > 18 && cellH > 14) {
            ctx.strokeStyle = "rgba(255,255,255,0.05)";
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }
      }

      // Hover highlight
      if (hoveredCell) {
        const { row, col } = hoveredCell;
        if (row >= startRow && row < endRow && col >= startCol && col < endCol) {
          const x = plot.x + col * cellW - view.offsetX;
          const y = plot.y + row * cellH - view.offsetY;
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
        }
      }

      ctx.restore();

      drawAxes(plot, cellW, cellH);
    }

    function drawAxes(plot, cellW, cellH) {
      ctx.strokeStyle = "#3a426d";
      ctx.lineWidth = 1;

      // Border
      ctx.strokeRect(plot.x, plot.y, plot.w, plot.h);

      // Row labels
      ctx.fillStyle = "#dbe2ff";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";

      const startRow = Math.max(0, Math.floor(view.offsetY / cellH));
      const endRow = Math.min(rows, Math.ceil((view.offsetY + plot.h) / cellH));

      for (let r = startRow; r < endRow; r++) {
        const y = plot.y + r * cellH - view.offsetY + cellH / 2;
        if (y >= plot.y && y <= plot.y + plot.h) {
          ctx.fillText(symbols[r], margin.left - 8, y);
        }
      }

      // Time labels
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillStyle = "#93a0c8";

      const startCol = Math.max(0, Math.floor(view.offsetX / cellW));
      const endCol = Math.min(timePoints, Math.ceil((view.offsetX + plot.w) / cellW));

      const now = Date.now();
      for (let c = startCol; c < endCol; c++) {
        if (cellW < 24 && c % 4 !== 0) continue;
        if (cellW < 14 && c % 8 !== 0) continue;

        const x = plot.x + c * cellW - view.offsetX + cellW / 2;
        const minutesAgo = timePoints - 1 - c;
        const ts = new Date(now - minutesAgo * 60_000);
        const label = ts.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        ctx.fillText(label, x, plot.y + plot.h + 6);
      }
    }

    function screenToCell(mx, my) {
      const plot = getPlotArea();
      const { cellW, cellH } = getCellSize();

      if (
        mx < plot.x || mx > plot.x + plot.w ||
        my < plot.y || my > plot.y + plot.h
      ) {
        return null;
      }

      const localX = mx - plot.x + view.offsetX;
      const localY = my - plot.y + view.offsetY;

      const col = Math.floor(localX / cellW);
      const row = Math.floor(localY / cellH);

      if (row < 0 || row >= rows || col < 0 || col >= timePoints) {
        return null;
      }

      return { row, col };
    }

    function updateTooltip(mx, my) {
      const cell = screenToCell(mx, my);
      hoveredCell = cell;

      if (!cell) {
        tooltip.style.display = "none";
        draw();
        return;
      }

      const value = data[cell.row][cell.col];
      const now = Date.now();
      const minutesAgo = timePoints - 1 - cell.col;
      const ts = new Date(now - minutesAgo * 60_000);

      tooltip.innerHTML = `
        <div><strong>${symbols[cell.row]}</strong></div>
        <div>Time: ${ts.toLocaleTimeString()}</div>
        <div>Change: <span style="color:${value >= 0 ? '#19c37d' : '#ff5c7a'}">${value.toFixed(2)}%</span></div>
      `;
      tooltip.style.display = "block";
      tooltip.style.left = mx + "px";
      tooltip.style.top = my + "px";

      draw();
    }

    function zoomAt(mx, my, deltaX, deltaY) {
      const plot = getPlotArea();
      const before = screenToWorld(mx, my);

      const zoomFactorX = deltaX < 0 ? 1.1 : 0.9;
      const zoomFactorY = deltaY < 0 ? 1.1 : 0.9;

      view.scaleX *= zoomFactorX;
      view.scaleY *= zoomFactorY;
      constrainView();

      const afterCellSize = getCellSize();

      if (
        mx >= plot.x && mx <= plot.x + plot.w &&
        my >= plot.y && my <= plot.y + plot.h
      ) {
        view.offsetX = before.worldX - (mx - plot.x);
        view.offsetY = before.worldY - (my - plot.y);

        const { maxOffsetX, maxOffsetY } = getMaxOffsets();
        view.offsetX = clamp(view.offsetX, 0, maxOffsetX);
        view.offsetY = clamp(view.offsetY, 0, maxOffsetY);
      }

      draw();
    }

    function screenToWorld(mx, my) {
      const plot = getPlotArea();
      return {
        worldX: mx - plot.x + view.offsetX,
        worldY: my - plot.y + view.offsetY
      };
    }

    function streamTick() {
      if (!streaming) return;

      for (let r = 0; r < rows; r++) {
        const row = data[r];
        const last = row[row.length - 1];
        let next = last + (Math.random() - 0.5) * 0.8;
        next = clamp(next, -5, 5);
        row.shift();
        row.push(next);
      }

      draw();
    }

    canvas.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (isDragging) {
        const dx = mx - lastMouseX;
        const dy = my - lastMouseY;
        view.offsetX -= dx;
        view.offsetY -= dy;
        constrainView();
        lastMouseX = mx;
        lastMouseY = my;
        tooltip.style.display = "none";
        hoveredCell = null;
        draw();
      } else {
        updateTooltip(mx, my);
      }
    });

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      canvas.classList.add("dragging");
      const rect = canvas.getBoundingClientRect();
      lastMouseX = e.clientX - rect.left;
      lastMouseY = e.clientY - rect.top;
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
      hoveredCell = null;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      // Shift+wheel = vertical emphasis, otherwise horizontal emphasis
      if (e.shiftKey) {
        zoomAt(mx, my, 1, e.deltaY);
      } else {
        zoomAt(mx, my, e.deltaY, e.deltaY);
      }
    }, { passive: false });

    toggleStreamBtn.addEventListener("click", () => {
      streaming = !streaming;
      statusEl.textContent = `Streaming: ${streaming ? "ON" : "OFF"}`;
      toggleStreamBtn.textContent = streaming ? "Pause Stream" : "Resume Stream";
    });

    resetViewBtn.addEventListener("click", () => {
      view.offsetX = 0;
      view.offsetY = 0;
      view.scaleX = 1;
      view.scaleY = 1;
      constrainView();
      draw();
    });

    window.addEventListener("resize", resize);

    resize();
    draw();
    setInterval(streamTick, 1000);
  </script>
</body>
</html>
```

---

## Notes on the implementation

### Data model
- `data[row][col]` stores the percent change for a symbol at a time bucket.
- This demo uses simulated values in the range `-5%` to `+5%`.

### Rendering
- The heatmap is drawn on a `<canvas>`.
- Only visible rows/columns are rendered based on the current pan/zoom state.

### Zoom/pan
- `view.scaleX`, `view.scaleY` control zoom
- `view.offsetX`, `view.offsetY` control pan
- Mouse wheel zooms
- Dragging pans

### Real-time updates
- `setInterval(streamTick, 1000)` simulates one new time bucket per second
- Each row shifts left and appends a new value

