<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Heatmap</h1>
      <div class="meta" id="status">Connecting…</div>
      <div class="legend">
        <span>Low</span>
        <div class="gradient"></div>
        <span>High</span>
      </div>
      <div class="hint">Wheel: zoom · Drag: pan</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.dpr = window.devicePixelRatio || 1;

        this.margin = {
          top: 20,
          right: 20,
          bottom: 40,
          left: 80
        };

        this.symbols = [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
          'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA'
        ];

        this.maxPoints = 300;
        this.data = [];
        this.timestamps = [];

        this.basePrices = {};
        this.currentPrices = {};
        this.symbols.forEach(sym => {
          const base = 50 + Math.random() * 250;
          this.basePrices[sym] = base;
          this.currentPrices[sym] = base;
        });

        this.viewStart = 0;
        this.viewEnd = 100;

        this.isDragging = false;
        this.dragStartX = 0;
        this.dragStartViewStart = 0;
        this.dragStartViewEnd = 0;

        this.hoverCell = null;

        this.initData();
        this.attachEvents();
        this.resize();
        this.startStream();
        this.render();
      }

      initData() {
        const now = Date.now();
        for (let i = 0; i < 120; i++) {
          this.pushTick(now - (119 - i) * 1000, false);
        }
        this.viewEnd = this.data.length;
        this.viewStart = Math.max(0, this.viewEnd - 60);
        this.statusEl.textContent = 'Live updates active';
      }

      startStream() {
        setInterval(() => {
          this.pushTick(Date.now(), true);
          const visibleCount = this.viewEnd - this.viewStart;
          const nearRightEdge = this.viewEnd >= this.data.length - 2;

          if (nearRightEdge) {
            this.viewEnd = this.data.length;
            this.viewStart = Math.max(0, this.viewEnd - visibleCount);
          }

          this.render();
        }, 1000);
      }

      pushTick(timestamp, trim = true) {
        const row = {};
        for (const sym of this.symbols) {
          const drift = (Math.random() - 0.5) * 2.5;
          const next = Math.max(5, this.currentPrices[sym] + drift);
          this.currentPrices[sym] = next;

          const pctChange = ((next - this.basePrices[sym]) / this.basePrices[sym]) * 100;
          row[sym] = {
            price: next,
            pctChange
          };
        }

        this.timestamps.push(timestamp);
        this.data.push(row);

        if (trim && this.data.length > this.maxPoints) {
          this.data.shift();
          this.timestamps.shift();
          this.viewStart = Math.max(0, this.viewStart - 1);
          this.viewEnd = Math.max(1, this.viewEnd - 1);
        }
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const plotWidth = this.width - this.margin.left - this.margin.right;
          const relX = Math.max(0, Math.min(1, (x - this.margin.left) / plotWidth));

          const currentSpan = this.viewEnd - this.viewStart;
          const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
          let nextSpan = currentSpan * zoomFactor;

          nextSpan = Math.max(10, Math.min(this.data.length, nextSpan));

          const anchor = this.viewStart + currentSpan * relX;
          let nextStart = anchor - nextSpan * relX;
          let nextEnd = nextStart + nextSpan;

          if (nextStart < 0) {
            nextStart = 0;
            nextEnd = nextSpan;
          }
          if (nextEnd > this.data.length) {
            nextEnd = this.data.length;
            nextStart = nextEnd - nextSpan;
          }

          this.viewStart = nextStart;
          this.viewEnd = nextEnd;
          this.render();
        }, { passive: false });

        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.canvas.classList.add('dragging');
          this.dragStartX = e.clientX;
          this.dragStartViewStart = this.viewStart;
          this.dragStartViewEnd = this.viewEnd;
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          if (this.isDragging) {
            const dx = e.clientX - this.dragStartX;
            const plotWidth = this.width - this.margin.left - this.margin.right;
            const span = this.dragStartViewEnd - this.dragStartViewStart;
            const deltaPoints = (dx / plotWidth) * span;

            let nextStart = this.dragStartViewStart - deltaPoints;
            let nextEnd = this.dragStartViewEnd - deltaPoints;

            if (nextStart < 0) {
              nextStart = 0;
              nextEnd = span;
            }
            if (nextEnd > this.data.length) {
              nextEnd = this.data.length;
              nextStart = this.data.length - span;
            }

            this.viewStart = nextStart;
            this.viewEnd = nextEnd;
            this.render();
          }

          this.updateHover(e);
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(this.width * this.dpr);
        this.canvas.height = Math.floor(this.height * this.dpr);
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

        this.render();
      }

      updateHover(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        const plot = this.getPlotArea();
        if (
          x < plot.x || x > plot.x + plot.w ||
          y < plot.y || y > plot.y + plot.h
        ) {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
          return;
        }

        const visibleStart = Math.floor(this.viewStart);
        const visibleEnd = Math.ceil(this.viewEnd);
        const visibleCount = Math.max(1, visibleEnd - visibleStart);

        const colWidth = plot.w / visibleCount;
        const rowHeight = plot.h / this.symbols.length;

        const col = Math.floor((x - plot.x) / colWidth);
        const row = Math.floor((y - plot.y) / rowHeight);

        const dataIndex = visibleStart + col;
        const symbol = this.symbols[row];

        if (
          dataIndex >= 0 &&
          dataIndex < this.data.length &&
          symbol &&
          this.data[dataIndex]
        ) {
          this.hoverCell = { dataIndex, row, col, symbol, x, y };
          const point = this.data[dataIndex][symbol];
          const ts = new Date(this.timestamps[dataIndex]).toLocaleTimeString();

          this.tooltip.innerHTML = `
            <strong>${symbol}</strong><br/>
            Price: $${point.price.toFixed(2)}<br/>
            Change: ${point.pctChange.toFixed(2)}%<br/>
            Time: ${ts}
          `;
          this.tooltip.style.display = 'block';
          this.tooltip.style.left = `${x}px`;
          this.tooltip.style.top = `${y}px`;
        } else {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
        }

        this.render();
      }

      getPlotArea() {
        return {
          x: this.margin.left,
          y: this.margin.top,
          w: this.width - this.margin.left - this.margin.right,
          h: this.height - this.margin.top - this.margin.bottom
        };
      }

      colorScale(value) {
        // value expected around -10..10
        const v = Math.max(-10, Math.min(10, value));
        const t = (v + 10) / 20;

        const stops = [
          [30, 58, 138],   // blue
          [37, 99, 235],   // bright blue
          [34, 197, 94],   // green
          [245, 158, 11],  // amber
          [239, 68, 68]    // red
        ];

        const scaled = t * (stops.length - 1);
        const i = Math.floor(scaled);
        const frac = scaled - i;

        const c1 = stops[i] || stops[stops.length - 1];
        const c2 = stops[i + 1] || stops[stops.length - 1];

        const r = Math.round(c1[0] + (c2[0] - c1[0]) * frac);
        const g = Math.round(c1[1] + (c2[1] - c1[1]) * frac);
        const b = Math.round(c1[2] + (c2[2] - c1[2]) * frac);

        return `rgb(${r}, ${g}, ${b})`;
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        const plot = this.getPlotArea();

        // Background
        ctx.fillStyle = '#121a2b';
        ctx.fillRect(0, 0, this.width, this.height);

        // Plot background
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(plot.x, plot.y, plot.w, plot.h);

        const visibleStart = Math.floor(this.viewStart);
        const visibleEnd = Math.ceil(this.viewEnd);
        const visibleCount = Math.max(1, visibleEnd - visibleStart);

        const colWidth = plot.w / visibleCount;
        const rowHeight = plot.h / this.symbols.length;

        // Draw cells
        for (let c = 0; c < visibleCount; c++) {
          const dataIndex = visibleStart + c;
          if (!this.data[dataIndex]) continue;

          for (let r = 0; r < this.symbols.length; r++) {
            const sym = this.symbols[r];
            const point = this.data[dataIndex][sym];
            const x = plot.x + c * colWidth;
            const y = plot.y + r * rowHeight;

            ctx.fillStyle = this.colorScale(point.pctChange);
            ctx.fillRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));

            ctx.strokeStyle = 'rgba(31, 42, 68, 0.35)';
            ctx.strokeRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));
          }
        }

        // Highlight hover cell
        if (this.hoverCell) {
          const c = this.hoverCell.col;
          const r = this.hoverCell.row;
          const x = plot.x + c * colWidth;
          const y = plot.y + r * rowHeight;

          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, Math.ceil(colWidth) - 2, Math.ceil(rowHeight) - 2);
          ctx.lineWidth = 1;
        }

        // Axes labels - Y
        ctx.fillStyle = '#dbe4ff';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        for (let r = 0; r < this.symbols.length; r++) {
          const y = plot.y + r * rowHeight + rowHeight / 2;
          ctx.fillText(this.symbols[r], this.margin.left - 10, y);
        }

        // X ticks
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillStyle = '#8ea0c9';

        const tickCount = Math.min(8, visibleCount);
        for (let i = 0; i < tickCount; i++) {
          const t = tickCount === 1 ? 0 : i / (tickCount - 1);
          const idx = Math.min(this.data.length - 1, Math.floor(visibleStart + t * (visibleCount - 1)));
          const x = plot.x + t * plot.w;
          const ts = this.timestamps[idx];
          if (!ts) continue;

          const label = new Date(ts).toLocaleTimeString([], {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
          });

          ctx.fillText(label, x, plot.y + plot.h + 8);

          ctx.strokeStyle = 'rgba(142, 160, 201, 0.15)';
          ctx.beginPath();
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.h);
          ctx.stroke();
        }

        // Border
        ctx.strokeStyle = '#2a3758';
        ctx.strokeRect(plot.x, plot.y, plot.w, plot.h);
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    new StockHeatmap(canvas, tooltip, statusEl);
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each time tick stores a row like:

```js
{
  AAPL: { price: 182.31, pctChange: 1.24 },
  MSFT: { price: 410.12, pctChange: -0.42 },
  ...
}
```

### Rendering
- The canvas is divided into:
  - rows for symbols
  - columns for time points
- Each cell is colored by `pctChange`

### Real-time updates
- `setInterval(..., 1000)` simulates a new market tick every second
- New data is appended and old data is trimmed when exceeding `maxPoints`

### Zoom/pan
- **Wheel** changes visible time span
- **Drag** shifts the visible window left/right

