If you later want to replace the simulated stream:

```js
const ws = new WebSocket('wss://your-stock-feed');

ws.onopen = () => {
  statusEl.textContent = 'Connected to live feed';
};

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);

  // Example expected shape:
  // {
  //   timestamp: 1712345678901,
  //   prices: {
  //     AAPL: 182.31,
  //     MSFT: 410.12
  //   }
  // }

  const row = {};
  for (const sym of heatmap.symbols) {
    const next = msg.prices[sym] ?? heatmap.currentPrices[sym];
    heatmap.currentPrices[sym] = next;
    const pctChange = ((next - heatmap.basePrices[sym]) / heatmap.basePrices[sym]) * 100;
    row[sym] = { price: next, pctChange };
  }

  heatmap.timestamps.push(msg.timestamp);
  heatmap.data.push(row);
  heatmap.render();
};
