<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>

      <div class="group">
        <label for="rows">Symbols</label>
        <input id="rows" type="number" min="5" max="200" value="30" />
      </div>

      <div class="group">
        <label for="cols">Time Buckets</label>
        <input id="cols" type="number" min="10" max="500" value="120" />
      </div>

      <div class="group">
        <label for="interval">Update ms</label>
        <input id="interval" type="number" min="50" max="5000" value="500" />
      </div>

      <div class="group">
        <button id="resetView">Reset View</button>
        <button id="regenerate">Regenerate Data</button>
        <button id="toggleStream">Pause</button>
      </div>

      <div class="status" id="status">Streaming</div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;

        this.dpr = window.devicePixelRatio || 1;
        this.width = 0;
        this.height = 0;

        this.symbols = [];
        this.data = [];
        this.basePrices = [];

        this.rows = 30;
        this.cols = 120;
        this.updateInterval = 500;
        this.streaming = true;
        this.timer = null;

        this.margin = {
          top: 30,
          right: 20,
          bottom: 30,
          left: 80
        };

        this.view = {
          scaleX: 1,
          scaleY: 1,
          offsetX: 0,
          offsetY: 0
        };

        this.drag = {
          active: false,
          startX: 0,
          startY: 0,
          originOffsetX: 0,
          originOffsetY: 0
        };

        this.hover = {
          x: 0,
          y: 0,
          row: -1,
          col: -1
        };

        this.maxAbsChange = 5; // percent clamp for color scale

        this.handleResize = this.handleResize.bind(this);
        this.onWheel = this.onWheel.bind(this);
        this.onMouseDown = this.onMouseDown.bind(this);
        this.onMouseMove = this.onMouseMove.bind(this);
        this.onMouseUp = this.onMouseUp.bind(this);
        this.onMouseLeave = this.onMouseLeave.bind(this);

        this.attachEvents();
        this.resize();
        this.generateData(this.rows, this.cols);
        this.startStreaming();
        this.render();
      }

      attachEvents() {
        window.addEventListener('resize', this.handleResize);
        this.canvas.addEventListener('wheel', this.onWheel, { passive: false });
        this.canvas.addEventListener('mousedown', this.onMouseDown);
        window.addEventListener('mousemove', this.onMouseMove);
        window.addEventListener('mouseup', this.onMouseUp);
        this.canvas.addEventListener('mouseleave', this.onMouseLeave);
      }

      destroy() {
        window.removeEventListener('resize', this.handleResize);
        this.canvas.removeEventListener('wheel', this.onWheel);
        this.canvas.removeEventListener('mousedown', this.onMouseDown);
        window.removeEventListener('mousemove', this.onMouseMove);
        window.removeEventListener('mouseup', this.onMouseUp);
        this.canvas.removeEventListener('mouseleave', this.onMouseLeave);
        this.stopStreaming();
      }

      handleResize() {
        this.resize();
        this.render();
      }

      resize() {
        const rect = this.canvas.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(this.width * this.dpr);
        this.canvas.height = Math.floor(this.height * this.dpr);
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      }

      generateSymbols(count) {
        const pool = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA', 'NVDA', 'META', 'NFLX',
          'AMD', 'INTC', 'CRM', 'ORCL', 'UBER', 'LYFT', 'SHOP', 'SQ',
          'PYPL', 'BABA', 'SONY', 'SAP', 'ADBE', 'QCOM', 'AVGO', 'CSCO',
          'IBM', 'PLTR', 'SNOW', 'ZM', 'DOCU', 'ROKU', 'COIN', 'HOOD'
        ];

        const symbols = [];
        for (let i = 0; i < count; i++) {
          if (i < pool.length) {
            symbols.push(pool[i]);
          } else {
            symbols.push(`SYM${i + 1}`);
          }
        }
        return symbols;
      }

      generateData(rows, cols) {
        this.rows = rows;
        this.cols = cols;
        this.symbols = this.generateSymbols(rows);
        this.basePrices = [];
        this.data = [];

        for (let r = 0; r < rows; r++) {
          const base = 50 + Math.random() * 250;
          this.basePrices.push(base);

          const row = [];
          let price = base;
          for (let c = 0; c < cols; c++) {
            price *= 1 + (Math.random() - 0.5) * 0.01;
            const pct = ((price - base) / base) * 100;
            row.push({
              price,
              pct,
              timestamp: Date.now() - (cols - c) * this.updateInterval
            });
          }
          this.data.push(row);
        }

        this.resetView();
      }

      resetView() {
        this.view.scaleX = 1;
        this.view.scaleY = 1;
        this.view.offsetX = 0;
        this.view.offsetY = 0;
        this.render();
      }

      startStreaming() {
        this.stopStreaming();
        this.streaming = true;
        this.statusEl.textContent = 'Streaming';
        this.timer = setInterval(() => {
          this.tick();
          this.render();
        }, this.updateInterval);
      }

      stopStreaming() {
        if (this.timer) {
          clearInterval(this.timer);
          this.timer = null;
        }
      }

      toggleStreaming() {
        if (this.streaming) {
          this.streaming = false;
          this.stopStreaming();
          this.statusEl.textContent = 'Paused';
        } else {
          this.streaming = true;
          this.startStreaming();
        }
      }

      setUpdateInterval(ms) {
        this.updateInterval = ms;
        if (this.streaming) {
          this.startStreaming();
        }
      }

      tick() {
        const now = Date.now();

        for (let r = 0; r < this.rows; r++) {
          const row = this.data[r];
          const last = row[row.length - 1];
          const drift = (Math.random() - 0.5) * 0.008;
          const momentum = last ? (last.pct / 100) * 0.05 : 0;
          const nextPrice = Math.max(1, last.price * (1 + drift + momentum));
          const base = this.basePrices[r];
          const pct = ((nextPrice - base) / base) * 100;

          row.shift();
          row.push({
            price: nextPrice,
            pct,
            timestamp: now
          });
        }
      }

      getPlotArea() {
        return {
          x: this.margin.left,
          y: this.margin.top,
          width: this.width - this.margin.left - this.margin.right,
          height: this.height - this.margin.top - this.margin.bottom
        };
      }

      clampOffsets(plot, scaledWidth, scaledHeight) {
        const minX = Math.min(0, plot.width - scaledWidth);
        const minY = Math.min(0, plot.height - scaledHeight);

        this.view.offsetX = Math.max(minX, Math.min(0, this.view.offsetX));
        this.view.offsetY = Math.max(minY, Math.min(0, this.view.offsetY));
      }

      onWheel(e) {
        e.preventDefault();

        const plot = this.getPlotArea();
        const mx = e.offsetX - plot.x;
        const my = e.offsetY - plot.y;

        if (mx < 0 || my < 0 || mx > plot.width || my > plot.height) return;

        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        const prevScaleX = this.view.scaleX;
        const prevScaleY = this.view.scaleY;

        const nextScaleX = Math.max(1, Math.min(12, prevScaleX * zoomFactor));
        const nextScaleY = Math.max(1, Math.min(12, prevScaleY * zoomFactor));

        const contentX = (mx - this.view.offsetX) / prevScaleX;
        const contentY = (my - this.view.offsetY) / prevScaleY;

        this.view.scaleX = nextScaleX;
        this.view.scaleY = nextScaleY;
        this.view.offsetX = mx - contentX * nextScaleX;
        this.view.offsetY = my - contentY * nextScaleY;

        this.clampOffsets(plot, plot.width * this.view.scaleX, plot.height * this.view.scaleY);
        this.render();
      }

      onMouseDown(e) {
        this.drag.active = true;
        this.drag.startX = e.clientX;
        this.drag.startY = e.clientY;
        this.drag.originOffsetX = this.view.offsetX;
        this.drag.originOffsetY = this.view.offsetY;
        this.canvas.classList.add('dragging');
      }

      onMouseMove(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        this.hover.x = x;
        this.hover.y = y;

        if (this.drag.active) {
          const dx = e.clientX - this.drag.startX;
          const dy = e.clientY - this.drag.startY;
          const plot = this.getPlotArea();

          this.view.offsetX = this.drag.originOffsetX + dx;
          this.view.offsetY = this.drag.originOffsetY + dy;
          this.clampOffsets(plot, plot.width * this.view.scaleX, plot.height * this.view.scaleY);
          this.render();
          return;
        }

        this.updateHover(x, y);
        this.render();
      }

      onMouseUp() {
        this.drag.active = false;
        this.canvas.classList.remove('dragging');
      }

      onMouseLeave() {
        this.hover.row = -1;
        this.hover.col = -1;
        this.tooltip.style.display = 'none';
        this.render();
      }

      updateHover(x, y) {
        const plot = this.getPlotArea();

        if (
          x < plot.x || x > plot.x + plot.width ||
          y < plot.y || y > plot.y + plot.height
        ) {
          this.hover.row = -1;
          this.hover.col = -1;
          this.tooltip.style.display = 'none';
          return;
        }

        const localX = x - plot.x;
        const localY = y - plot.y;

        const scaledWidth = plot.width * this.view.scaleX;
        const scaledHeight = plot.height * this.view.scaleY;

        const contentX = (localX - this.view.offsetX) / this.view.scaleX;
        const contentY = (localY - this.view.offsetY) / this.view.scaleY;

        if (
          contentX < 0 || contentY < 0 ||
          contentX > plot.width || contentY > plot.height
        ) {
          this.hover.row = -1;
          this.hover.col = -1;
          this.tooltip.style.display = 'none';
          return;
        }

        const cellW = plot.width / this.cols;
        const cellH = plot.height / this.rows;

        const col = Math.floor(contentX / cellW);
        const row = Math.floor(contentY / cellH);

        if (row >= 0 && row < this.rows && col >= 0 && col < this.cols) {
          this.hover.row = row;
          this.hover.col = col;

          const point = this.data[row][col];
          const date = new Date(point.timestamp).toLocaleTimeString();

          this.tooltip.innerHTML = `
            <strong>${this.symbols[row]}</strong><br>
            Price: $${point.price.toFixed(2)}<br>
            Change: ${point.pct.toFixed(2)}%<br>
            Time: ${date}
          `;
          this.tooltip.style.display = 'block';
          this.tooltip.style.left = `${x}px`;
          this.tooltip.style.top = `${y}px`;
        } else {
          this.hover.row = -1;
          this.hover.col = -1;
          this.tooltip.style.display = 'none';
        }
      }

      colorForPct(pct) {
        const clamped = Math.max(-this.maxAbsChange, Math.min(this.maxAbsChange, pct));
        const t = (clamped + this.maxAbsChange) / (2 * this.maxAbsChange);

        if (t < 0.5) {
          const k = t / 0.5;
          const r = Math.round(180 + (80 - 180) * k);
          const g = Math.round(35 + (80 - 35) * k);
          const b = Math.round(24 + (80 - 24) * k);
          return `rgb(${r},${g},${b})`;
        } else {
          const k = (t - 0.5) / 0.5;
          const r = Math.round(80 + (24 - 80) * k);
          const g = Math.round(80 + (160 - 80) * k);
          const b = Math.round(80 + (88 - 80) * k);
          return `rgb(${r},${g},${b})`;
        }
      }

      renderAxes(plot) {
        const ctx = this.ctx;
        ctx.save();

        ctx.strokeStyle = '#2a3658';
        ctx.fillStyle = '#8ea0c9';
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.moveTo(plot.x, plot.y);
        ctx.lineTo(plot.x, plot.y + plot.height);
        ctx.lineTo(plot.x + plot.width, plot.y + plot.height);
        ctx.stroke();

        const rowH = plot.height / this.rows;
        ctx.font = '12px Inter, sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        for (let r = 0; r < this.rows; r++) {
          const y = plot.y + (r + 0.5) * rowH * this.view.scaleY + this.view.offsetY;
          if (y < plot.y || y > plot.y + plot.height) continue;
          ctx.fillText(this.symbols[r], plot.x - 8, y);
        }

        const visibleTicks = Math.min(10, this.cols);
        const step = Math.max(1, Math.floor(this.cols / visibleTicks));
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        for (let c = 0; c < this.cols; c += step) {
          const x = plot.x + c * (plot.width / this.cols) * this.view.scaleX + this.view.offsetX;
          if (x < plot.x || x > plot.x + plot.width) continue;

          const point = this.data[0]?.[c];
          const label = point
            ? new Date(point.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
            : `${c}`;

          ctx.fillText(label, x + ((plot.width / this.cols) * this.view.scaleX) / 2, plot.y + plot.height + 6);
        }

        ctx.restore();
      }

      renderGrid(plot) {
        const ctx = this.ctx;
        const cellW = plot.width / this.cols;
        const cellH = plot.height / this.rows;

        ctx.save();

        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        ctx.translate(plot.x + this.view.offsetX, plot.y + this.view.offsetY);
        ctx.scale(this.view.scaleX, this.view.scaleY);

        for (let r = 0; r < this.rows; r++) {
          for (let c = 0; c < this.cols; c++) {
            const point = this.data[r][c];
            ctx.fillStyle = this.colorForPct(point.pct);
            ctx.fillRect(c * cellW, r * cellH, cellW, cellH);
          }
        }

        if (cellW * this.view.scaleX > 8 && cellH * this.view.scaleY > 8) {
          ctx.strokeStyle = 'rgba(255,255,255,0.06)';
          ctx.lineWidth = 1 / Math.max(this.view.scaleX, this.view.scaleY);

          for (let r = 0; r <= this.rows; r++) {
            const y = r * cellH;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(this.cols * cellW, y);
            ctx.stroke();
          }

          for (let c = 0; c <= this.cols; c++) {
            const x = c * cellW;
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, this.rows * cellH);
            ctx.stroke();
          }
        }

        if (this.hover.row >= 0 && this.hover.col >= 0) {
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2 / Math.max(this.view.scaleX, this.view.scaleY);
          ctx.strokeRect(
            this.hover.col * cellW,
            this.hover.row * cellH,
            cellW,
            cellH
          );
        }

        ctx.restore();
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        const plot = this.getPlotArea();

        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, this.width, this.height);

        ctx.fillStyle = '#121a2b';
        ctx.fillRect(plot.x, plot.y, plot.width, plot.height);

        this.clampOffsets(plot, plot.width * this.view.scaleX, plot.height * this.view.scaleY);
        this.renderGrid(plot);
        this.renderAxes(plot);

        ctx.save();
        ctx.strokeStyle = '#2a3658';
        ctx.strokeRect(plot.x, plot.y, plot.width, plot.height);
        ctx.restore();
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    let heatmap = new StockHeatmap(canvas, tooltip, statusEl);

    const rowsInput = document.getElementById('rows');
    const colsInput = document.getElementById('cols');
    const intervalInput = document.getElementById('interval');
    const resetViewBtn = document.getElementById('resetView');
    const regenerateBtn = document.getElementById('regenerate');
    const toggleStreamBtn = document.getElementById('toggleStream');

    function regenerate() {
      const rows = Math.max(5, Math.min(200, Number(rowsInput.value) || 30));
      const cols = Math.max(10, Math.min(500, Number(colsInput.value) || 120));
      heatmap.generateData(rows, cols);
      heatmap.render();
    }

    rowsInput.addEventListener('change', regenerate);
    colsInput.addEventListener('change', regenerate);

    intervalInput.addEventListener('change', () => {
      const ms = Math.max(50, Math.min(5000, Number(intervalInput.value) || 500));
      heatmap.setUpdateInterval(ms);
      regenerate();
    });

    resetViewBtn.addEventListener('click', () => heatmap.resetView());
    regenerateBtn.addEventListener('click', regenerate);

    toggleStreamBtn.addEventListener('click', () => {
      heatmap.toggleStreaming();
      toggleStreamBtn.textContent = heatmap.streaming ? 'Pause' : 'Resume';
    });
  </script>
</body>
</html>
```

