      border: 1px solid #475569;
      padding: 8px 10px;
      font-size: 12px;
      border-radius: 6px;
      display: none;
      white-space: nowrap;
      z-index: 10;
    }

    .legend {
      margin-top: 12px;
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 12px;
      color: #cbd5e1;
    }

    .legend-bar {
      width: 240px;
      height: 12px;
      border-radius: 6px;
      background: linear-gradient(
        to right,
        #1e3a8a,
        #2563eb,
        #06b6d4,
        #22c55e,
        #f59e0b,
        #ef4444
      );
      border: 1px solid #334155;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Interactive Real-Time Stock Price Heatmap</h1>
    <div id="chart" class="chart-wrap">
      <canvas id="heatmap"></canvas>
      <svg id="overlay" class="overlay"></svg>
      <div id="tooltip" class="tooltip"></div>
    </div>
    <div class="legend">
      <span>Low intensity</span>
      <div class="legend-bar"></div>
      <span>High intensity</span>
    </div>
  </div>

  <script>
    const container = document.getElementById("chart");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");

    const width = container.clientWidth;
    const height = container.clientHeight;

    canvas.width = width;
    canvas.height = height;

    svg.attr("width", width).attr("height", height);

    const margin = { top: 20, right: 20, bottom: 40, left: 70 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Heatmap grid configuration
    const timeBuckets = 120;   // columns
    const priceBuckets = 60;   // rows
    const visibleDurationMs = 2 * 60 * 1000; // 2 minutes visible window

    let now = Date.now();
    let startTime = now - visibleDurationMs;

    let basePrice = 100;
    let minPrice = 95;
    let maxPrice = 105;

    // 2D matrix: rows = price buckets, cols = time buckets
    let data = Array.from({ length: priceBuckets }, () =>
      Array.from({ length: timeBuckets }, () => 0)
    );

    const xScale = d3.scaleTime()
      .domain([new Date(startTime), new Date(now)])
      .range([margin.left, margin.left + innerWidth]);

    const yScale = d3.scaleLinear()
      .domain([minPrice, maxPrice])
      .range([margin.top + innerHeight, margin.top]);

    const colorScale = d3.scaleSequential()
      .interpolator(d3.interpolateTurbo)
      .domain([0, 100]);

    const xAxisG = svg.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0, ${margin.top + innerHeight})`);

    const yAxisG = svg.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left}, 0)`);

    const clipRect = svg.append("defs")
      .append("clipPath")
      .attr("id", "plot-clip")
      .append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", innerWidth)
      .attr("height", innerHeight);

    const interactionLayer = svg.append("rect")
      .attr("x", margin.left)
      .attr("y", margin.top)
      .attr("width", innerWidth)
      .attr("height", innerHeight)
      .attr("fill", "transparent")
      .style("cursor", "crosshair");

    let currentTransform = d3.zoomIdentity;

    function renderAxes() {
      const zx = currentTransform.rescaleX(xScale);
      const zy = currentTransform.rescaleY(yScale);

      xAxisG.call(d3.axisBottom(zx).ticks(8));
      yAxisG.call(d3.axisLeft(zy).ticks(8));
    }

    function renderHeatmap() {
      ctx.clearRect(0, 0, width, height);

      const zx = currentTransform.rescaleX(xScale);
      const zy = currentTransform.rescaleY(yScale);

      const timeStep = visibleDurationMs / timeBuckets;
      const priceStep = (maxPrice - minPrice) / priceBuckets;

      for (let row = 0; row < priceBuckets; row++) {
        for (let col = 0; col < timeBuckets; col++) {
          const value = data[row][col];
          if (value <= 0) continue;

          const t0 = startTime + col * timeStep;
          const t1 = t0 + timeStep;

          const p0 = minPrice + row * priceStep;
          const p1 = p0 + priceStep;

          const x0 = zx(new Date(t0));
          const x1 = zx(new Date(t1));
          const y0 = zy(p0);
          const y1 = zy(p1);

          const cellX = x0;
          const cellY = y1;
          const cellW = Math.max(1, x1 - x0);
          const cellH = Math.max(1, y0 - y1);

          if (
            cellX + cellW < margin.left ||
            cellX > margin.left + innerWidth ||
            cellY + cellH < margin.top ||
            cellY > margin.top + innerHeight
          ) {
            continue;
          }

          ctx.fillStyle = colorScale(value);
          ctx.fillRect(cellX, cellY, cellW, cellH);
        }
      }

      // Border around plot area
      ctx.strokeStyle = "#334155";
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);
    }

    function render() {
      renderAxes();
      renderHeatmap();
    }

    function shiftDataWindow(newNow) {
      const elapsed = newNow - now;
      if (elapsed <= 0) return;

      const timeStep = visibleDurationMs / timeBuckets;
      const bucketsToShift = Math.floor(elapsed / timeStep);

      if (bucketsToShift > 0) {
        for (let row = 0; row < priceBuckets; row++) {
          data[row].splice(0, bucketsToShift);
          for (let i = 0; i < bucketsToShift; i++) {
            data[row].push(0);
          }
        }
        startTime += bucketsToShift * timeStep;
        now = startTime + visibleDurationMs;
        xScale.domain([new Date(startTime), new Date(now)]);
      } else {
        now = newNow;
        xScale.domain([new Date(startTime), new Date(now)]);
      }
    }

    function injectTick() {
      const newNow = Date.now();
      shiftDataWindow(newNow);

      // Simulate stock movement
      basePrice += (Math.random() - 0.5) * 0.4;
      basePrice = Math.max(minPrice + 0.5, Math.min(maxPrice - 0.5, basePrice));

      // Simulate several trades around current price
      const trades = 3 + Math.floor(Math.random() * 5);
      const timeStep = visibleDurationMs / timeBuckets;
      const latestCol = Math.min(
        timeBuckets - 1,
        Math.floor((newNow - startTime) / timeStep)
      );

      for (let i = 0; i < trades; i++) {
        const tradePrice = basePrice + (Math.random() - 0.5) * 1.2;
        const row = Math.floor(((tradePrice - minPrice) / (maxPrice - minPrice)) * priceBuckets);

        if (row >= 0 && row < priceBuckets && latestCol >= 0 && latestCol < timeBuckets) {
          data[row][latestCol] = Math.min(100, data[row][latestCol] + 15 + Math.random() * 30);
        }
      }

      // Fade older values slightly for visual motion
      for (let row = 0; row < priceBuckets; row++) {
        for (let col = 0; col < timeBuckets; col++) {
          data[row][col] *= 0.995;
        }
      }

      render();
    }

    function getCellFromMouse(mx, my) {
      const zx = currentTransform.rescaleX(xScale);
      const zy = currentTransform.rescaleY(yScale);

      if (
        mx < margin.left || mx > margin.left + innerWidth ||
        my < margin.top || my > margin.top + innerHeight
      ) {
        return null;
      }

      const timeValue = zx.invert(mx).getTime();
      const priceValue = zy.invert(my);

      const timeStep = visibleDurationMs / timeBuckets;
      const priceStep = (maxPrice - minPrice) / priceBuckets;

      const col = Math.floor((timeValue - startTime) / timeStep);
      const row = Math.floor((priceValue - minPrice) / priceStep);

      if (row < 0 || row >= priceBuckets || col < 0 || col >= timeBuckets) {
        return null;
      }

      return {
        row,
        col,
        value: data[row][col],
        time: new Date(startTime + col * timeStep),
        price: minPrice + row * priceStep
      };
    }

    interactionLayer
      .on("mousemove", function(event) {
        const [mx, my] = d3.pointer(event, this);
        const cell = getCellFromMouse(mx, my);

        if (!cell) {
          tooltip.style.display = "none";
          return;
        }

        tooltip.style.display = "block";
        tooltip.style.left = `${mx + 14}px`;
        tooltip.style.top = `${my + 14}px`;
        tooltip.innerHTML = `
          <div><strong>Time:</strong> ${cell.time.toLocaleTimeString()}</div>
          <div><strong>Price:</strong> ${cell.price.toFixed(2)}</div>
          <div><strong>Intensity:</strong> ${cell.value.toFixed(1)}</div>
        `;
      })
      .on("mouseleave", function() {
        tooltip.style.display = "none";
      });

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
      .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    render();

    // Simulated real-time stream
    setInterval(injectTick, 200);

    // Resize support
    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
