<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="meta" id="status">Streaming simulated market data...</div>
      <button id="resetZoom">Reset Zoom</button>
      <button id="pauseBtn">Pause</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <svg class="overlay" id="overlay"></svg>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div>Price Change</div>
        <div class="legend-bar"></div>
        <div class="legend-scale">
          <span>-3%</span>
          <span>0%</span>
          <span>+3%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "ORCL", "CRM", "UBER", "SHOP", "BABA", "PYPL",
      "ADBE", "QCOM", "AVGO", "SNOW"
    ];

    const timeSteps = 120; // columns visible in the rolling buffer
    const updateIntervalMs = 1000;

    const margin = { top: 40, right: 20, bottom: 40, left: 80 };

    const chartWrap = document.getElementById("chartWrap");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetZoomBtn = document.getElementById("resetZoom");
    const pauseBtn = document.getElementById("pauseBtn");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;
    let dpr = window.devicePixelRatio || 1;

    let paused = false;
    let timer = null;

    // Rolling time-series heatmap data:
    // each row is a symbol, each column is a time bucket
    let timestamps = [];
    let data = [];
    let latestPrices = new Map();
    let basePrices = new Map();

    // initialize prices
    symbols.forEach(sym => {
      const base = 100 + Math.random() * 400;
      basePrices.set(sym, base);
      latestPrices.set(sym, base);
    });

    function seedData() {
      timestamps = [];
      data = symbols.map(sym => []);

      const now = Date.now();
      for (let i = timeSteps - 1; i >= 0; i--) {
        const ts = now - i * updateIntervalMs;
        timestamps.push(ts);
      }

      symbols.forEach((sym, rowIndex) => {
        let price = basePrices.get(sym);
        for (let i = 0; i < timeSteps; i++) {
          price = nextPrice(price);
          latestPrices.set(sym, price);
          data[rowIndex].push({
            symbol: sym,
            timestamp: timestamps[i],
            price,
            changePct: ((price - basePrices.get(sym)) / basePrices.get(sym)) * 100
          });
        }
      });
    }

    function nextPrice(prev) {
      const drift = (Math.random() - 0.5) * 2.5;
      return Math.max(5, prev * (1 + drift / 100));
    }

    seedData();

    let xBaseScale, yBaseScale, xScale, yScale, colorScale;
    let xAxisG, yAxisG, zoomLayer;
    let currentTransform = d3.zoomIdentity;

    function initSvg() {
      svg.selectAll("*").remove();

      xAxisG = svg.append("g").attr("class", "axis x-axis");
      yAxisG = svg.append("g").attr("class", "axis y-axis");

      zoomLayer = svg.append("rect")
        .attr("fill", "transparent")
        .style("cursor", "grab");

      const zoom = d3.zoom()
        .scaleExtent([1, 12])
        .translateExtent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
        .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
        .on("zoom", (event) => {
          currentTransform = event.transform;
          updateScalesFromTransform();
          render();
        });

      svg.call(zoom);

      resetZoomBtn.onclick = () => {
        svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
      };
    }

    function resize() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;
      dpr = window.devicePixelRatio || 1;

      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      svg.attr("width", width).attr("height", height);

      xBaseScale = d3.scaleLinear()
        .domain([0, timestamps.length])
        .range([margin.left, width - margin.right]);

      yBaseScale = d3.scaleBand()
        .domain(symbols)
        .range([margin.top, height - margin.bottom])
        .paddingInner(0.06)
        .paddingOuter(0.02);

      colorScale = d3.scaleLinear()
        .domain([-3, 0, 3])
        .range(["#ef4444", "#1f2937", "#22c55e"])
        .clamp(true);

      initSvg();
      updateScalesFromTransform();
      render();
    }

    function updateScalesFromTransform() {
      xScale = currentTransform.rescaleX(xBaseScale);

      const yRange = [margin.top, height - margin.bottom];
      const y0 = currentTransform.applyY(yRange[0]);
      const y1 = currentTransform.applyY(yRange[1]);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([y0, y1])
        .paddingInner(0.06)
        .paddingOuter(0.02);
    }

    function renderAxes() {
      const visibleTicks = Math.max(2, Math.floor(innerWidth / 100));
      const xAxis = d3.axisBottom(xScale)
        .ticks(visibleTicks)
        .tickFormat(i => {
          const idx = Math.max(0, Math.min(timestamps.length - 1, Math.round(i)));
          return d3.timeFormat("%H:%M:%S")(new Date(timestamps[idx]));
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG
        .attr("transform", `translate(0, ${height - margin.bottom})`)
        .call(xAxis);

      yAxisG
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);

      zoomLayer
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);
    }

    function renderHeatmap() {
      ctx.clearRect(0, 0, width, height);

      // background panel
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(margin.left, margin.top, innerWidth, innerHeight);

      // clip plot area
      ctx.save();
      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      const colWidth = Math.abs(xScale(1) - xScale(0));
      const minCellWidth = 1;

      for (let row = 0; row < symbols.length; row++) {
        const sym = symbols[row];
        const y = yScale(sym);
        const h = yScale.bandwidth();

        if (y + h < margin.top || y > height - margin.bottom) continue;

        const rowData = data[row];
        for (let col = 0; col < rowData.length; col++) {
          const d = rowData[col];
          const x = xScale(col);
          const w = Math.max(minCellWidth, colWidth);

          if (x + w < margin.left || x > width - margin.right) continue;

          ctx.fillStyle = colorScale(d.changePct);
          ctx.fillRect(x, y, w, h);
        }
      }

      // grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.06)";
      ctx.lineWidth = 1;

      symbols.forEach(sym => {
        const y = yScale(sym);
        if (y >= margin.top && y <= height - margin.bottom) {
          ctx.beginPath();
          ctx.moveTo(margin.left, y);
          ctx.lineTo(width - margin.right, y);
          ctx.stroke();
        }
      });

      ctx.restore();

      // border
      ctx.strokeStyle = "#334155";
      ctx.strokeRect(margin.left, margin.top, innerWidth, innerHeight);
    }

    function render() {
      renderHeatmap();
      renderAxes();
    }

    function appendTick() {
      const ts = Date.now();
      timestamps.push(ts);
      if (timestamps.length > timeSteps) timestamps.shift();

      symbols.forEach((sym, rowIndex) => {
        const prev = latestPrices.get(sym);
        const price = nextPrice(prev);
        latestPrices.set(sym, price);

        const point = {
          symbol: sym,
          timestamp: ts,
          price,
          changePct: ((price - basePrices.get(sym)) / basePrices.get(sym)) * 100
        };

        data[rowIndex].push(point);
        if (data[rowIndex].length > timeSteps) data[rowIndex].shift();
      });

      statusEl.textContent = `Streaming simulated market data... Last update ${new Date(ts).toLocaleTimeString()}`;
      render();
    }

    function getCellAt(mx, my) {
      if (
        mx < margin.left || mx > width - margin.right ||
        my < margin.top || my > height - margin.bottom
      ) {
        return null;
      }

      const symbol = symbols.find(sym => {
        const y = yScale(sym);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (!symbol) return null;

      const xIndex = Math.floor(xScale.invert(mx));
      const clampedIndex = Math.max(0, Math.min(timeSteps - 1, xIndex));
      const rowIndex = symbols.indexOf(symbol);
      const cell = data[rowIndex][clampedIndex];

      if (!cell) return null;

      return {
        ...cell,
        rowIndex,
        colIndex: clampedIndex
      };
    }

    function showTooltip(event, cell) {
      tooltip.style.opacity = "1";
      tooltip.style.left = event.offsetX + 12 + "px";
      tooltip.style.top = event.offsetY + 12 + "px";
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Time: ${new Date(cell.timestamp).toLocaleTimeString()}</div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: <span style="color:${cell.changePct >= 0 ? '#4ade80' : '#f87171'}">${cell.changePct.toFixed(2)}%</span></div>
      `;
    }

    function hideTooltip() {
      tooltip.style.opacity = "0";
    }

    svg.on("mousemove", function(event) {
      const [mx, my] = d3.pointer(event, this);
      const cell = getCellAt(mx, my);
      if (cell) showTooltip(event, cell);
      else hideTooltip();
    });

    svg.on("mouseleave", hideTooltip);

    pauseBtn.onclick = () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
    };

    function startStream() {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        if (!paused) appendTick();
      }, updateIntervalMs);
    }

    window.addEventListener("resize", resize);

    resize();
    startStream();
  </script>
</body>
</html>
