      "AMD", "INTC", "CRM", "ORCL", "IBM", "UBER", "SHOP", "SQ",
      "BABA", "SONY", "SAP", "ADBE"
    ];

    const timeSteps = 120; // columns
    const cellData = [];
    const basePrices = new Map();

    symbols.forEach(symbol => {
      basePrices.set(symbol, 100 + Math.random() * 200);
    });

    function nowLabel(offset) {
      const d = new Date(Date.now() - (timeSteps - 1 - offset) * 1000);
      return d.toLocaleTimeString();
    }

    for (let row = 0; row < symbols.length; row++) {
      const symbol = symbols[row];
      const rowData = [];
      let price = basePrices.get(symbol);
      for (let col = 0; col < timeSteps; col++) {
        price *= 1 + (Math.random() - 0.5) * 0.01;
        rowData.push({
          symbol,
          timeIndex: col,
          timeLabel: nowLabel(col),
          price,
          changePct: ((Math.random() - 0.5) * 4)
        });
      }
      cellData.push(rowData);
    }

    const wrap = document.getElementById("chartWrap");
    const heatmapCanvas = document.getElementById("heatmap");
    const overlayCanvas = document.getElementById("overlay");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");
    const resetZoomBtn = document.getElementById("resetZoom");

    const heatCtx = heatmapCanvas.getContext("2d");
    const overlayCtx = overlayCanvas.getContext("2d");

    let width = 0;
    let height = 0;
    let dpr = window.devicePixelRatio || 1;

    const margin = { top: 20, right: 20, bottom: 40, left: 80 };

    let xBaseScale, yBaseScale;
    let currentTransform = d3.zoomIdentity;

    function resize() {
      width = wrap.clientWidth;
      height = wrap.clientHeight;

      [heatmapCanvas, overlayCanvas].forEach(canvas => {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        canvas.style.width = width + "px";
        canvas.style.height = height + "px";
