      heatCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
      overlayCtx.setTransform(dpr, 0, 0, dpr, 0, 0);

      xBaseScale = d3.scaleLinear()
        .domain([0, timeSteps])
        .range([margin.left, width - margin.right]);

