    function colorForChange(changePct) {
      const clamped = Math.max(-5, Math.min(5, changePct));
      const t = (clamped + 5) / 10;
      return d3.interpolateRdYlGn(t);
    }

    function getScaledX() {
      return currentTransform.rescaleX(xBaseScale);
