      overlayCtx.beginPath();
      overlayCtx.moveTo(margin.left, height - margin.bottom);
      overlayCtx.lineTo(width - margin.right, height - margin.bottom);
      overlayCtx.stroke();

      // Y axis
      overlayCtx.beginPath();
      overlayCtx.moveTo(margin.left, margin.top);
      overlayCtx.lineTo(margin.left, height - margin.bottom);
      overlayCtx.stroke();

      const xScale = getScaledX();

      // X ticks
      const ticks = xScale.ticks(8).filter(t => t >= 0 && t <= timeSteps - 1);
      overlayCtx.textAlign = "center";
      overlayCtx.textBaseline = "top";
      overlayCtx.font = "11px Arial";

      ticks.forEach(t => {
        const x = xScale(t);
        overlayCtx.strokeStyle = "#1e293b";
        overlayCtx.beginPath();
        overlayCtx.moveTo(x, margin.top);
        overlayCtx.lineTo(x, height - margin.bottom);
        overlayCtx.stroke();

        overlayCtx.fillStyle = "#94a3b8";
        const idx = Math.round(t);
        overlayCtx.fillText(cellData[0][idx]?.timeLabel || "", x, height - margin.bottom + 6);
      });

      // Y labels
      overlayCtx.textAlign = "right";
      overlayCtx.textBaseline = "middle";
      overlayCtx.fillStyle = "#cbd5e1";

      symbols.forEach((symbol, i) => {
        const [y0, y1] = getScaledY(i);
        const cy = (y0 + y1) / 2;
        if (cy < margin.top || cy > height - margin.bottom) return;
        overlayCtx.fillText(symbol, margin.left - 8, cy);
