        const cellHeight = y1 - y0;

        if (y1 < margin.top || y0 > height - margin.bottom) continue;

        for (let col = 0; col < timeSteps; col++) {
          const x0 = xScale(col);
          const x1 = xScale(col + 1);
          const cellWidth = x1 - x0;

          if (x1 < margin.left || x0 > width - margin.right) continue;
          if (cellWidth < 0.25 || cellHeight < 0.25) continue;

          const cell = cellData[row][col];
          heatCtx.fillStyle = colorForChange(cell.changePct);
          heatCtx.fillRect(x0, y0, cellWidth, cellHeight);
        }
      }
    }

    function draw() {
      drawHeatmap();
      drawAxes();
    }

    function findCellAt(mx, my) {
      const xScale = getScaledX();

      for (let row = 0; row < symbols.length; row++) {
        const [y0, y1] = getScaledY(row);
        if (my < y0 || my > y1) continue;

        const col = Math.floor(xScale.invert(mx));
        if (col >= 0 && col < timeSteps) {
          return cellData[row][col];
        }
      }
      return null;
    }

    overlayCanvas.addEventListener("mousemove", e => {
      const rect = overlayCanvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const cell = findCellAt(mx, my);
      if (!cell) {
        tooltip.style.display = "none";
        draw();
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = mx + "px";
      tooltip.style.top = my + "px";
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Time: ${cell.timeLabel}</div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: ${cell.changePct.toFixed(2)}%</div>
      `;

      draw();

      const row = symbols.indexOf(cell.symbol);
      const [y0, y1] = getScaledY(row);
      const x0 = getScaledX()(cell.timeIndex);
      const x1 = getScaledX()(cell.timeIndex + 1);

      overlayCtx.save();
      overlayCtx.strokeStyle = "#ffffff";
      overlayCtx.lineWidth = 2;
      overlayCtx.strokeRect(x0, y0, x1 - x0, y1 - y0);
      overlayCtx.restore();
    });

    overlayCanvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
      draw();
    });

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        draw();
      });

    d3.select(overlayCanvas).call(zoom);

    resetZoomBtn.addEventListener("click", () => {
      d3.select(overlayCanvas)
        .transition()
        .duration(300)
        .call(zoom.transform, d3.zoomIdentity);
    });

    function pushRealtimeUpdate() {
      const latestTime = new Date().toLocaleTimeString();

      for (let row = 0; row < symbols.length; row++) {
        const rowData = cellData[row];
        const prev = rowData[rowData.length - 1];
        const nextPrice = prev.price * (1 + (Math.random() - 0.5) * 0.01);
        const nextChange = ((nextPrice - prev.price) / prev.price) * 100;

        rowData.shift();
        rowData.push({
          symbol: prev.symbol,
          timeIndex: timeSteps - 1,
          timeLabel: latestTime,
          price: nextPrice,
          changePct: nextChange
        });

        for (let i = 0; i < rowData.length; i++) {
          rowData[i].timeIndex = i;
        }
      }

      status.textContent = "Streaming updates... " + new Date().toLocaleTimeString();
      draw();
    }

    window.addEventListener("resize", resize);

    resize();
    setInterval(pushRealtimeUpdate, 1000);
  </script>
</body>
</html>
```

