        #2f3654 50%,
        #19c37d 75%,
        #006b3c 100%
      );
      border: 1px solid #3a4268;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="meta" id="status">Streaming: ON</div>
      <button id="toggleStream">Pause Stream</button>
      <button id="resetView">Reset View</button>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;

        this.symbols = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA',
          'NVDA', 'META', 'NFLX', 'AMD', 'INTC',
          'CRM', 'ORCL', 'UBER', 'SHOP', 'BABA',
          'JPM', 'BAC', 'GS', 'V', 'MA'
        ];

        this.timeSteps = 240;
        this.data = this.symbols.map(() =>
          Array.from({ length: this.timeSteps }, () => 0)
        );

        this.basePrices = {};
        this.currentPrices = {};
        this.symbols.forEach(symbol => {
          const base = 50 + Math.random() * 250;
          this.basePrices[symbol] = base;
          this.currentPrices[symbol] = base;
        });

        this.view = {
          offsetX: 120,
          offsetY: 40,
          scaleX: 1,
          scaleY: 1,
          minScaleX: 0.4,
          maxScaleX: 6,
          minScaleY: 0.5,
          maxScaleY: 4
        };

        this.layout = {
          leftAxisWidth: 100,
          topAxisHeight: 30,
          cellWidth: 18,
          cellHeight: 24
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          lastY: 0,
          hoverCell: null
        };

        this.streaming = true;
        this.lastTimestamp = Date.now();

        this.resize();
        this.attachEvents();
        this.seedInitialData();
        this.start();
      }

      seedInitialData() {
        for (let t = 0; t < this.timeSteps; t++) {
          this.pushNextFrame();
        }
      }

      pushNextFrame() {
        this.symbols.forEach((symbol, row) => {
          const drift = (Math.random() - 0.5) * 0.8;
          const volatility = 0.3 + Math.random() * 1.2;
          const deltaPct = drift * volatility;
          this.currentPrices[symbol] *= (1 + deltaPct / 100);

          const pctFromBase =
            ((this.currentPrices[symbol] - this.basePrices[symbol]) / this.basePrices[symbol]) * 100;

          this.data[row].shift();
          this.data[row].push(pctFromBase);
        });

        this.lastTimestamp = Date.now();
      }

      start() {
        const tick = () => {
          if (this.streaming) {
            this.pushNextFrame();
          }
          this.draw();
          requestAnimationFrame(tick);
        };

        setInterval(() => {
          if (this.streaming) this.pushNextFrame();
        }, 700);

        tick();
      }

      resize() {
        const dpr = window.devicePixelRatio || 1;
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = rect.width * dpr;
        this.canvas.height = rect.height * dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        this.width = rect.width;
        this.height = rect.height;
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
          this.interaction.lastY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            const dy = e.clientY - this.interaction.lastY;
            this.view.offsetX += dx;
            this.view.offsetY += dy;
            this.interaction.lastX = e.clientX;
            this.interaction.lastY = e.clientY;
          }

          this.updateHover(x, y, e.clientX, e.clientY);
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

          const prevScaleX = this.view.scaleX;
          const prevScaleY = this.view.scaleY;

          if (e.shiftKey) {
            this.view.scaleY *= zoomFactor;
            this.view.scaleY = Math.max(this.view.minScaleY, Math.min(this.view.maxScaleY, this.view.scaleY));
          } else {
            this.view.scaleX *= zoomFactor;
            this.view.scaleY *= zoomFactor;
            this.view.scaleX = Math.max(this.view.minScaleX, Math.min(this.view.maxScaleX, this.view.scaleX));
            this.view.scaleY = Math.max(this.view.minScaleY, Math.min(this.view.maxScaleY, this.view.scaleY));
          }

          const scaleRatioX = this.view.scaleX / prevScaleX;
          const scaleRatioY = this.view.scaleY / prevScaleY;

          this.view.offsetX = mouseX - (mouseX - this.view.offsetX) * scaleRatioX;
          this.view.offsetY = mouseY - (mouseY - this.view.offsetY) * scaleRatioY;
        }, { passive: false });
      }

      resetView() {
        this.view.offsetX = 120;
        this.view.offsetY = 40;
        this.view.scaleX = 1;
        this.view.scaleY = 1;
      }

      updateHover(x, y, clientX, clientY) {
        const cell = this.screenToCell(x, y);
        if (!cell) {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
          return;
        }

        const { row, col } = cell;
        const symbol = this.symbols[row];
        const value = this.data[row][col];
        const age = this.timeSteps - 1 - col;

        this.interaction.hoverCell = cell;
        this.tooltip.style.display = 'block';
        this.tooltip.style.left = clientX + 'px';
        this.tooltip.style.top = clientY + 'px';
        this.tooltip.innerHTML = `
          <strong>${symbol}</strong><br/>
          Change: <span style="color:${value >= 0 ? '#19c37d' : '#ff5c5c'}">${value.toFixed(2)}%</span><br/>
          Time bucket: ${col}<br/>
          Age: ${age} ticks ago
        `;
      }

      screenToCell(x, y) {
        const cellW = this.layout.cellWidth * this.view.scaleX;
        const cellH = this.layout.cellHeight * this.view.scaleY;

        const gridX = x - this.view.offsetX - this.layout.leftAxisWidth;
        const gridY = y - this.view.offsetY - this.layout.topAxisHeight;

        if (gridX < 0 || gridY < 0) return null;

        const col = Math.floor(gridX / cellW);
        const row = Math.floor(gridY / cellH);

        if (
          row < 0 || row >= this.symbols.length ||
          col < 0 || col >= this.timeSteps
        ) {
          return null;
        }

        return { row, col };
      }

      colorForValue(value) {
        const clamped = Math.max(-5, Math.min(5, value));

        if (clamped < 0) {
          const t = (clamped + 5) / 5;
          return this.lerpColor([139, 0, 0], [47, 54, 84], t);
        } else {
          const t = clamped / 5;
          return this.lerpColor([47, 54, 84], [25, 195, 125], t);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      draw() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        this.drawBackground();
        this.drawHeatmap();
        this.drawAxes();
        this.drawHover();
      }

      drawBackground() {
        const ctx = this.ctx;
        ctx.fillStyle = '#0f1220';
        ctx.fillRect(0, 0, this.width, this.height);
      }

      drawHeatmap() {
        const ctx = this.ctx;
        const cellW = this.layout.cellWidth * this.view.scaleX;
        const cellH = this.layout.cellHeight * this.view.scaleY;
        const startX = this.view.offsetX + this.layout.leftAxisWidth;
        const startY = this.view.offsetY + this.layout.topAxisHeight;

        for (let row = 0; row < this.symbols.length; row++) {
          for (let col = 0; col < this.timeSteps; col++) {
            const x = startX + col * cellW;
            const y = startY + row * cellH;

            if (x + cellW < 0 || x > this.width || y + cellH < 0 || y > this.height) {
              continue;
            }

            ctx.fillStyle = this.colorForValue(this.data[row][col]);
            ctx.fillRect(x, y, cellW, cellH);

            ctx.strokeStyle = 'rgba(42, 47, 74, 0.35)';
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }
      }

      drawAxes() {
        const ctx = this.ctx;
        const cellW = this.layout.cellWidth * this.view.scaleX;
        const cellH = this.layout.cellHeight * this.view.scaleY;
        const startX = this.view.offsetX + this.layout.leftAxisWidth;
        const startY = this.view.offsetY + this.layout.topAxisHeight;

        ctx.save();
        ctx.font = '12px Inter, sans-serif';
        ctx.textBaseline = 'middle';

        for (let row = 0; row < this.symbols.length; row++) {
          const y = startY + row * cellH + cellH / 2;
          if (y < 0 || y > this.height) continue;

          ctx.fillStyle = '#dbe2ff';
          ctx.fillText(this.symbols[row], this.view.offsetX + 8, y);
        }

        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        const step = Math.max(1, Math.floor(12 / this.view.scaleX));
        for (let col = 0; col < this.timeSteps; col += step) {
          const x = startX + col * cellW + cellW / 2;
          if (x < 0 || x > this.width) continue;

          ctx.fillStyle = '#8e97b7';
          ctx.fillText(`-${this.timeSteps - 1 - col}`, x, this.view.offsetY + 6);
        }

        ctx.restore();
      }

      drawHover() {
        if (!this.interaction.hoverCell) return;

        const ctx = this.ctx;
        const { row, col } = this.interaction.hoverCell;
        const cellW = this.layout.cellWidth * this.view.scaleX;
        const cellH = this.layout.cellHeight * this.view.scaleY;
        const x = this.view.offsetX + this.layout.leftAxisWidth + col * cellW;
        const y = this.view.offsetY + this.layout.topAxisHeight + row * cellH;

        ctx.save();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, cellW, cellH);
        ctx.restore();
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const heatmap = new StockHeatmap(canvas, tooltip, statusEl);

    document.getElementById('toggleStream').addEventListener('click', (e) => {
      heatmap.streaming = !heatmap.streaming;
      statusEl.textContent = `Streaming: ${heatmap.streaming ? 'ON' : 'OFF'}`;
      e.target.textContent = heatmap.streaming ? 'Pause Stream' : 'Resume Stream';
    });

    document.getElementById('resetView').addEventListener('click', () => {
      heatmap.resetView();
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `symbols`: stock rows
- `timeSteps`: number of visible historical columns
- `data[row][col]`: percent change from base price

### Real-time updates
- Every ~700ms, a new value is generated for each stock
- Oldest column is removed with `shift()`
- Newest value is appended with `push()`

### Rendering
- Canvas draws:
  - heatmap cells
  - row labels
  - time labels
  - hover outline

### Interaction
- **Mouse drag** → pan
- **Mouse wheel** → zoom
- **Shift + wheel** → vertical-only zoom
- **Hover** → tooltip

