      border: 1px solid #31385f;
      border-radius: 8px;
      padding: 8px 12px;
      cursor: pointer;
    }

    .toolbar button:hover {
      background: #2a3154;
    }

    .canvas-wrap {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(18, 22, 38, 0.95);
      color: var(--text);
      border: 1px solid #39406a;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      min-width: 140px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
    }

    .legend {
      position: absolute;
      right: 16px;
      bottom: 16px;
      width: 180px;
      background: rgba(23, 26, 43, 0.92);
      border: 1px solid #31385f;
      border-radius: 10px;
      padding: 10px;
      backdrop-filter: blur(4px);
    }

    .legend-title {
      font-size: 12px;
      color: var(--muted);
      margin-bottom: 8px;
    }

    .legend-bar {
      height: 14px;
      border-radius: 999px;
      background: linear-gradient(
        90deg,
        rgb(180, 30, 30) 0%,
        rgb(80, 80, 80) 50%,
        rgb(20, 180, 80) 100%
      );
      border: 1px solid #3a4168;
    }

    .legend-labels {
      margin-top: 6px;
      display: flex;
      justify-content: space-between;
      font-size: 11px;
      color: var(--muted);
    }

    .help {
      position: absolute;
      left: 16px;
      bottom: 16px;
      background: rgba(23, 26, 43, 0.92);
      border: 1px solid #31385f;
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 12px;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="stat" id="status">Streaming: ON</div>
      <div class="stat" id="zoomStat">Zoom: 1.00x</div>
      <div class="stat" id="panStat">Pan: (0, 0)</div>
      <button id="toggleStreamBtn">Pause Stream</button>
      <button id="resetViewBtn">Reset View</button>
      <button id="randomizeBtn">Randomize</button>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-title">Price Change</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>

      <div class="help">
        Wheel: Zoom<br />
        Drag: Pan<br />
        Hover: Inspect cell
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const zoomStatEl = document.getElementById('zoomStat');
    const panStatEl = document.getElementById('panStat');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const randomizeBtn = document.getElementById('randomizeBtn');

    const SYMBOLS = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'META', 'TSLA', 'NFLX',
      'AMD', 'INTC', 'CRM', 'ORCL', 'UBER', 'SHOP', 'BABA', 'PYPL',
      'JPM', 'GS', 'BAC', 'V', 'MA', 'DIS', 'KO', 'PEP'
    ];

    const TIME_BUCKETS = 120;
    const ROWS = SYMBOLS.length;
    const COLS = TIME_BUCKETS;

    let heatmapData = [];
    let basePrices = {};
    let streaming = true;

    const view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0,
      minScale: 0.5,
      maxScale: 6
    };

    const layout = {
      leftAxisWidth: 80,
      topAxisHeight: 30,
      rightPad: 10,
      bottomPad: 10
    };

    let interaction = {
      dragging: false,
      lastX: 0,
      lastY: 0,
      hoverCell: null
    };

    function initData() {
      heatmapData = [];
      basePrices = {};

      for (const symbol of SYMBOLS) {
        basePrices[symbol] = 50 + Math.random() * 250;
      }

      for (let r = 0; r < ROWS; r++) {
        const row = [];
        let current = basePrices[SYMBOLS[r]];
        for (let c = 0; c < COLS; c++) {
          current *= 1 + (Math.random() - 0.5) * 0.01;
          const pctChange = ((current - basePrices[SYMBOLS[r]]) / basePrices[SYMBOLS[r]]) * 100;
          row.push({
            price: current,
            pctChange,
            timestamp: Date.now() - (COLS - c) * 1000
          });
        }
        heatmapData.push(row);
      }
    }

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function colorForPct(pct) {
      const clamped = clamp(pct, -5, 5);
      const t = (clamped + 5) / 10;

      let r, g, b;
      if (t < 0.5) {
        const k = t / 0.5;
        r = Math.round(180 + (80 - 180) * k);
        g = Math.round(30 + (80 - 30) * k);
        b = Math.round(30 + (80 - 30) * k);
      } else {
        const k = (t - 0.5) / 0.5;
        r = Math.round(80 + (20 - 80) * k);
        g = Math.round(80 + (180 - 80) * k);
        b = Math.round(80 + (80 - 80) * k);
      }

      return `rgb(${r}, ${g}, ${b})`;
    }

    function getPlotArea() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      return {
        x: layout.leftAxisWidth,
        y: layout.topAxisHeight,
        width: width - layout.leftAxisWidth - layout.rightPad,
        height: height - layout.topAxisHeight - layout.bottomPad
      };
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const plot = getPlotArea();

      ctx.fillStyle = '#0f1220';
      ctx.fillRect(0, 0, width, height);

      ctx.fillStyle = '#171a2b';
      ctx.fillRect(plot.x, plot.y, plot.width, plot.height);

      const cellW = (plot.width / COLS) * view.scaleX;
      const cellH = (plot.height / ROWS) * view.scaleY;

      const startCol = Math.max(0, Math.floor(-view.offsetX / cellW));
      const endCol = Math.min(COLS, Math.ceil((plot.width - view.offsetX) / cellW));
      const startRow = Math.max(0, Math.floor(-view.offsetY / cellH));
      const endRow = Math.min(ROWS, Math.ceil((plot.height - view.offsetY) / cellH));

      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.width, plot.height);
      ctx.clip();

      for (let r = startRow; r < endRow; r++) {
        for (let c = startCol; c < endCol; c++) {
          const cell = heatmapData[r][c];
          const x = plot.x + view.offsetX + c * cellW;
          const y = plot.y + view.offsetY + r * cellH;

          ctx.fillStyle = colorForPct(cell.pctChange);
          ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));

          if (cellW > 18 && cellH > 14) {
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }
      }

      if (interaction.hoverCell) {
        const { row, col } = interaction.hoverCell;
        if (row >= 0 && row < ROWS && col >= 0 && col < COLS) {
          const x = plot.x + view.offsetX + col * cellW;
          const y = plot.y + view.offsetY + row * cellH;
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, Math.max(0, cellW - 2), Math.max(0, cellH - 2));
        }
      }

      ctx.restore();

      drawAxes(plot, cellW, cellH, startCol, endCol, startRow, endRow);
      updateStats();
    }

    function drawAxes(plot, cellW, cellH, startCol, endCol, startRow, endRow) {
      ctx.fillStyle = '#cfd7ff';
      ctx.font = '12px Inter, system-ui, sans-serif';
      ctx.textBaseline = 'middle';

      for (let r = startRow; r < endRow; r++) {
        const y = plot.y + view.offsetY + r * cellH + cellH / 2;
        if (y < plot.y - 20 || y > plot.y + plot.height + 20) continue;
        ctx.fillStyle = '#98a2c8';
        ctx.fillText(SYMBOLS[r], 10, y);
      }

      ctx.textAlign = 'center';
      for (let c = startCol; c < endCol; c += Math.max(1, Math.floor(12 / view.scaleX))) {
        const x = plot.x + view.offsetX + c * cellW + cellW / 2;
        if (x < plot.x || x > plot.x + plot.width) continue;
        const ts = heatmapData[0][c]?.timestamp || Date.now();
        const d = new Date(ts);
        const label = d.toLocaleTimeString([], { minute: '2-digit', second: '2-digit' });
        ctx.fillStyle = '#98a2c8';
        ctx.fillText(label, x, 15);
      }

      ctx.strokeStyle = '#2a2f4a';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(plot.x, plot.y);
      ctx.lineTo(plot.x, plot.y + plot.height);
      ctx.lineTo(plot.x + plot.width, plot.y + plot.height);
      ctx.stroke();
      ctx.textAlign = 'left';
    }

    function updateStats() {
      zoomStatEl.textContent = `Zoom: ${view.scaleX.toFixed(2)}x`;
      panStatEl.textContent = `Pan: (${Math.round(view.offsetX)}, ${Math.round(view.offsetY)})`;
      statusEl.textContent = `Streaming: ${streaming ? 'ON' : 'OFF'}`;
    }

    function screenToCell(mx, my) {
      const plot = getPlotArea();
      if (
        mx < plot.x || mx > plot.x + plot.width ||
        my < plot.y || my > plot.y + plot.height
      ) {
        return null;
      }

      const cellW = (plot.width / COLS) * view.scaleX;
      const cellH = (plot.height / ROWS) * view.scaleY;

      const col = Math.floor((mx - plot.x - view.offsetX) / cellW);
      const row = Math.floor((my - plot.y - view.offsetY) / cellH);

      if (row < 0 || row >= ROWS || col < 0 || col >= COLS) return null;
      return { row, col };
    }

    function updateTooltip(mx, my) {
      const cellPos = screenToCell(mx, my);
      interaction.hoverCell = cellPos;

      if (!cellPos) {
        tooltip.style.display = 'none';
        draw();
        return;
      }

      const { row, col } = cellPos;
      const cell = heatmapData[row][col];
      const symbol = SYMBOLS[row];
      const time = new Date(cell.timestamp).toLocaleTimeString();

      tooltip.innerHTML = `
        <div><strong>${symbol}</strong></div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: ${cell.pctChange.toFixed(2)}%</div>
        <div>Time: ${time}</div>
      `;
      tooltip.style.display = 'block';
      tooltip.style.left = `${mx + 14}px`;
      tooltip.style.top = `${my + 14}px`;

      draw();
    }

    function zoomAt(mx, my, deltaY) {
      const plot = getPlotArea();
      const oldScaleX = view.scaleX;
      const oldScaleY = view.scaleY;

      const zoomFactor = deltaY < 0 ? 1.1 : 0.9;
      view.scaleX = clamp(view.scaleX * zoomFactor, view.minScale, view.maxScale);
      view.scaleY = clamp(view.scaleY * zoomFactor, view.minScale, view.maxScale);

      const oldCellW = (plot.width / COLS) * oldScaleX;
      const oldCellH = (plot.height / ROWS) * oldScaleY;
      const newCellW = (plot.width / COLS) * view.scaleX;
      const newCellH = (plot.height / ROWS) * view.scaleY;

      const relX = mx - plot.x;
      const relY = my - plot.y;

      const worldX = (relX - view.offsetX) / oldCellW;
      const worldY = (relY - view.offsetY) / oldCellH;

      view.offsetX = relX - worldX * newCellW;
      view.offsetY = relY - worldY * newCellH;

      draw();
    }

    function streamTick() {
      if (!streaming) return;

      for (let r = 0; r < ROWS; r++) {
        const symbol = SYMBOLS[r];
        const last = heatmapData[r][heatmapData[r].length - 1];
        let nextPrice = last.price * (1 + (Math.random() - 0.5) * 0.008);

        if (Math.random() < 0.03) {
          nextPrice *= 1 + (Math.random() - 0.5) * 0.04;
        }

        const pctChange = ((nextPrice - basePrices[symbol]) / basePrices[symbol]) * 100;

        heatmapData[r].shift();
        heatmapData[r].push({
          price: nextPrice,
          pctChange,
          timestamp: Date.now()
        });
      }

      draw();
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (interaction.dragging) {
        const dx = mx - interaction.lastX;
        const dy = my - interaction.lastY;
        view.offsetX += dx;
        view.offsetY += dy;
        interaction.lastX = mx;
        interaction.lastY = my;
        draw();
      } else {
        updateTooltip(mx, my);
      }
    });

    canvas.addEventListener('mousedown', (e) => {
      interaction.dragging = true;
      canvas.classList.add('dragging');
      const rect = canvas.getBoundingClientRect();
      interaction.lastX = e.clientX - rect.left;
      interaction.lastY = e.clientY - rect.top;
    });

    window.addEventListener('mouseup', () => {
      interaction.dragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
      interaction.hoverCell = null;
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      zoomAt(mx, my, e.deltaY);
    }, { passive: false });

    toggleStreamBtn.addEventListener('click', () => {
      streaming = !streaming;
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
      draw();
    });

    resetViewBtn.addEventListener('click', () => {
      view.scaleX = 1;
      view.scaleY = 1;
      view.offsetX = 0;
      view.offsetY = 0;
      draw();
    });

    randomizeBtn.addEventListener('click', () => {
      initData();
      draw();
    });

    window.addEventListener('resize', resizeCanvas);

    initData();
    resizeCanvas();
    setInterval(streamTick, 1000);
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each stock row contains a rolling array of time buckets:

```js
{
  price: 123.45,
  pctChange: 1.27,
  timestamp: 1710000000000
}
```

### Rendering
- The heatmap is drawn on a `<canvas>`
- Only visible rows/columns are rendered based on current zoom/pan
- Colors map from red → neutral → green based on `% change`

### Real-time updates
Every second:
- oldest value is removed
- newest simulated price is appended
- heatmap redraws

### Zoom/pan
- Mouse wheel changes `scaleX` and `scaleY`
- Dragging changes `offsetX` and `offsetY`

