<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <button id="toggleFeed">Pause Feed</button>
      <button id="resetZoom">Reset Zoom</button>
      <label>
        Window:
        <select id="windowSize">
          <option value="30">30 cols</option>
          <option value="60" selected>60 cols</option>
          <option value="120">120 cols</option>
        </select>
      </label>
      <div class="status" id="status">Running</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "AMD",
      "NFLX", "INTC", "CRM", "ORCL", "UBER", "SHOP", "PYPL", "ADBE",
      "QCOM", "AVGO", "CSCO", "IBM"
    ];

    const state = {
      rows: symbols.length,
      cols: 60,
      maxCols: 120,
      running: true,
      data: [],
      basePrices: new Map(),
      latestPrices: new Map(),
      transform: d3.zoomIdentity,
      hoveredCell: null
    };

    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleFeedBtn = document.getElementById("toggleFeed");
    const resetZoomBtn = document.getElementById("resetZoom");
    const windowSizeSelect = document.getElementById("windowSize");

    const margin = { top: 30, right: 20, bottom: 30, left: 80 };

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;
    let dpr = window.devicePixelRatio || 1;

    function initPrices() {
      symbols.forEach(symbol => {
        const base = 50 + Math.random() * 250;
        state.basePrices.set(symbol, base);
        state.latestPrices.set(symbol, base);
      });
    }

    function seedData() {
      state.data = [];
      const now = Date.now();
      for (let c = state.cols - 1; c >= 0; c--) {
        const timestamp = now - c * 1000;
        const col = [];
        symbols.forEach(symbol => {
          const prev = state.latestPrices.get(symbol);
          const next = prev * (1 + (Math.random() - 0.5) * 0.01);
          state.latestPrices.set(symbol, next);
          const base = state.basePrices.get(symbol);
          col.push({
            symbol,
            timestamp,
            price: next,
            changePct: ((next - base) / base) * 100
          });
        });
        state.data.push(col);
      }
    }

    function appendLiveColumn() {
      const timestamp = Date.now();
      const col = [];
      symbols.forEach(symbol => {
        const prev = state.latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 0.008;
        const next = prev * (1 + drift);
        state.latestPrices.set(symbol, next);
        const base = state.basePrices.get(symbol);
        col.push({
          symbol,
          timestamp,
          price: next,
          changePct: ((next - base) / base) * 100
        });
      });

      state.data.push(col);
      while (state.data.length > state.maxCols) {
        state.data.shift();
      }
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function getVisibleCols() {
      return state.data.slice(-state.cols);
    }

    function getScales() {
      const visible = getVisibleCols();
      const xDomain = d3.range(visible.length);
      const yDomain = symbols;

      const x = d3.scaleBand()
        .domain(xDomain)
        .range([0, innerWidth])
        .paddingInner(0.02)
        .paddingOuter(0);

      const y = d3.scaleBand()
        .domain(yDomain)
        .range([0, innerHeight])
        .paddingInner(0.04)
        .paddingOuter(0);

      return { x, y, visible };
    }

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#dc2626", "#f3f4f6", "#16a34a"])
      .clamp(true);

    function formatTime(ts) {
      return new Date(ts).toLocaleTimeString();
    }

    function clear() {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, width, height);
    }

    function drawAxes(x, y, visible) {
      ctx.save();
      ctx.translate(margin.left, margin.top);
      ctx.font = "12px Inter, system-ui, sans-serif";
      ctx.fillStyle = "#cbd5e1";
      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;

      symbols.forEach(symbol => {
        const yy = y(symbol) + y.bandwidth() / 2;
        ctx.fillText(symbol, -70, yy + 4);
      });

      const tickCount = Math.min(8, visible.length);
      const tickStep = Math.max(1, Math.floor(visible.length / tickCount));

      for (let i = 0; i < visible.length; i += tickStep) {
        const xx = x(i) + x.bandwidth() / 2;
        const ts = visible[i][0].timestamp;
        ctx.fillText(formatTime(ts), xx - 20, innerHeight + 18);
      }

      ctx.strokeStyle = "#1f2937";
      ctx.beginPath();
      ctx.moveTo(0, innerHeight + 0.5);
      ctx.lineTo(innerWidth, innerHeight + 0.5);
      ctx.moveTo(0.5, 0);
      ctx.lineTo(0.5, innerHeight);
      ctx.stroke();

      ctx.restore();
    }

    function drawHeatmap(x, y, visible) {
      ctx.save();
      ctx.translate(margin.left, margin.top);

      const zx = state.transform.rescaleX(
        d3.scaleLinear().domain([0, visible.length]).range([0, innerWidth])
      );

      const start = Math.max(0, Math.floor(zx.invert(0)));
      const end = Math.min(visible.length, Math.ceil(zx.invert(innerWidth)));

      for (let c = start; c < end; c++) {
        const x0 = zx(c);
        const x1 = zx(c + 1);
        const cellW = Math.max(1, x1 - x0 - 1);

        for (let r = 0; r < symbols.length; r++) {
          const cell = visible[c][r];
          const yy = y(cell.symbol);
          const hh = y.bandwidth();

          ctx.fillStyle = colorScale(cell.changePct);
          ctx.fillRect(x0, yy, cellW, hh);

          if (
            state.hoveredCell &&
            state.hoveredCell.col === c &&
            state.hoveredCell.row === r
          ) {
            ctx.strokeStyle = "#facc15";
            ctx.lineWidth = 2;
            ctx.strokeRect(x0 + 1, yy + 1, Math.max(0, cellW - 2), Math.max(0, hh - 2));
          }
        }
      }

      ctx.restore();
    }

    function draw() {
      clear();
      const { x, y, visible } = getScales();
      drawHeatmap(x, y, visible);
      drawAxes(x, y, visible);
    }

    function pointerToCell(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const px = clientX - rect.left - margin.left;
      const py = clientY - rect.top - margin.top;

      if (px < 0 || py < 0 || px > innerWidth || py > innerHeight) return null;

      const { y, visible } = getScales();

      const zx = state.transform.rescaleX(
        d3.scaleLinear().domain([0, visible.length]).range([0, innerWidth])
      );

      const col = Math.floor(zx.invert(px));
      if (col < 0 || col >= visible.length) return null;

      let row = null;
      for (let r = 0; r < symbols.length; r++) {
        const yy = y(symbols[r]);
        if (py >= yy && py <= yy + y.bandwidth()) {
          row = r;
          break;
        }
      }

      if (row == null) return null;

      return { col, row, cell: visible[col][row] };
    }

    canvas.addEventListener("mousemove", (e) => {
      const hit = pointerToCell(e.clientX, e.clientY);
      state.hoveredCell = hit ? { col: hit.col, row: hit.row } : null;

      if (hit) {
        tooltip.style.display = "block";
        tooltip.style.left = `${e.offsetX}px`;
        tooltip.style.top = `${e.offsetY}px`;
        tooltip.innerHTML = `
          <div><strong>${hit.cell.symbol}</strong></div>
          <div>Time: ${formatTime(hit.cell.timestamp)}</div>
          <div>Price: $${hit.cell.price.toFixed(2)}</div>
          <div>Change: ${hit.cell.changePct.toFixed(2)}%</div>
        `;
      } else {
        tooltip.style.display = "none";
      }

      draw();
    });

    canvas.addEventListener("mouseleave", () => {
      state.hoveredCell = null;
      tooltip.style.display = "none";
      draw();
    });

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .filter((event) => {
        return event.type === "wheel" || event.type === "mousedown" || event.type === "mousemove";
      })
      .on("zoom", (event) => {
        state.transform = event.transform;
        draw();
      });

    d3.select(canvas).call(zoom);

    toggleFeedBtn.addEventListener("click", () => {
      state.running = !state.running;
      toggleFeedBtn.textContent = state.running ? "Pause Feed" : "Resume Feed";
      statusEl.textContent = state.running ? "Running" : "Paused";
    });

    resetZoomBtn.addEventListener("click", () => {
      d3.select(canvas).transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    windowSizeSelect.addEventListener("change", (e) => {
      state.cols = Number(e.target.value);
      draw();
    });

    window.addEventListener("resize", resize);

    initPrices();
    seedData();
    resize();

    setInterval(() => {
      if (!state.running) return;
      appendLiveColumn();
      draw();
    }, 1000);
  </script>
</body>
</html>
```

---

## How it works

### Data model
The heatmap stores data as:

```js
state.data = [
  [ {symbol, timestamp, price, changePct}, ...rows ],
  [ {symbol, timestamp, price, changePct}, ...rows ],
  ...
];
```

So each outer array item is a **time column**, and each inner array contains one cell per stock symbol.

---

### Rendering
- The heatmap is drawn on a `<canvas>`.
- Y positions use a `scaleBand` over stock symbols.
- X positions are computed from a zoomable linear scale.
- Colors map percentage change:
  - red = negative
  - white = neutral
  - green = positive

---

### Zoom/pan
D3 zoom manages a transform:

```js
state.transform = event.transform;
```

That transform is applied to a linear x-scale to determine:
- which columns are visible
- where each column is drawn

---

### Real-time updates
Every second:
- each stock price gets a small random drift
- a new column is appended
- old columns are removed once `maxCols` is exceeded

---

## Good next improvements

Here are the most useful next steps for productionizing this:

### 1. Replace simulated data with real WebSocket data
For example:

```js
const socket = new WebSocket("wss://your-feed.example.com/stocks");

socket.onmessage = (event) => {
  const tick = JSON.parse(event.data);
  // aggregate ticks into current time bucket
