  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Heatmap</h1>
      <button id="resetBtn">Reset View</button>

      <label>
        Update Interval
        <select id="intervalSelect">
          <option value="250">250ms</option>
          <option value="500" selected>500ms</option>
          <option value="1000">1000ms</option>
        </select>
      </label>

      <label>
        Max History
        <input id="historyInput" type="number" min="20" max="500" value="120" />
      </label>

      <label>
        Volatility
        <input id="volatilityInput" type="range" min="0.1" max="3" step="0.1" value="0.8" />
      </label>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div>Price Change %</div>
        <div class="legend-bar"></div>
        <div class="legend-scale">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('chartWrap');
    const tooltip = document.getElementById('tooltip');

    const resetBtn = document.getElementById('resetBtn');
    const intervalSelect = document.getElementById('intervalSelect');
    const historyInput = document.getElementById('historyInput');
    const volatilityInput = document.getElementById('volatilityInput');

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA',
      'JPM', 'GS', 'BAC', 'V', 'MA'
    ];

    const state = {
      data: [],
      timestamps: [],
      maxHistory: Number(historyInput.value),
      updateInterval: Number(intervalSelect.value),
      volatility: Number(volatilityInput.value),
      timer: null,

      view: {
        scaleX: 1,
        scaleY: 1,
        offsetX: 0,
        offsetY: 0
      },

      interaction: {
        dragging: false,
        lastX: 0,
        lastY: 0,
        mouseX: 0,
        mouseY: 0
      },

      layout: {
        leftPad: 80,
        rightPad: 20,
        topPad: 20,
        bottomPad: 40
      },

      colorRange: {
        min: -5,
        max: 5
      }
    };

    function initData() {
      state.data = symbols.map(() => []);
      state.timestamps = [];

      for (let t = 0; t < state.maxHistory; t++) {
        appendTick(false);
      }
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function colorForValue(value) {
      const { min, max } = state.colorRange;
      const clamped = clamp(value, min, max);
      const t = (clamped - min) / (max - min);

      if (t < 0.5) {
        const k = t / 0.5;
        const r = Math.round(lerp(180, 230, k));
        const g = Math.round(lerp(30, 200, k));
        const b = Math.round(lerp(30, 60, k));
        return `rgb(${r},${g},${b})`;
      } else {
        const k = (t - 0.5) / 0.5;
        const r = Math.round(lerp(230, 30, k));
        const g = Math.round(lerp(200, 180, k));
        const b = Math.round(lerp(60, 90, k));
        return `rgb(${r},${g},${b})`;
      }
    }

    function appendTick(useCurrentTime = true) {
      const now = useCurrentTime ? Date.now() : Date.now() - (state.maxHistory - state.timestamps.length) * state.updateInterval;
      state.timestamps.push(now);

      for (let i = 0; i < symbols.length; i++) {
        const series = state.data[i];
        const prev = series.length ? series[series.length - 1] : (Math.random() * 2 - 1);
        const drift = (Math.random() * 2 - 1) * state.volatility;
        const meanReversion = -prev * 0.08;
        const next = clamp(prev + drift + meanReversion, -6, 6);
        series.push(next);

        if (series.length > state.maxHistory) {
          series.shift();
        }
      }

      if (state.timestamps.length > state.maxHistory) {
        state.timestamps.shift();
      }
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * DPR);
      canvas.height = Math.floor(rect.height * DPR);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function getPlotArea() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;
      const { leftPad, rightPad, topPad, bottomPad } = state.layout;
      return {
        x: leftPad,
        y: topPad,
        w: width - leftPad - rightPad,
        h: height - topPad - bottomPad
      };
    }

    function getVisibleWindow() {
      const plot = getPlotArea();
      const totalCols = state.timestamps.length;
      const totalRows = symbols.length;

      const visibleCols = clamp(totalCols / state.view.scaleX, 5, totalCols);
      const visibleRows = clamp(totalRows / state.view.scaleY, 3, totalRows);

      const maxOffsetX = Math.max(0, totalCols - visibleCols);
      const maxOffsetY = Math.max(0, totalRows - visibleRows);

      state.view.offsetX = clamp(state.view.offsetX, 0, maxOffsetX);
      state.view.offsetY = clamp(state.view.offsetY, 0, maxOffsetY);

      return {
        plot,
        totalCols,
        totalRows,
        visibleCols,
        visibleRows,
        startCol: state.view.offsetX,
        startRow: state.view.offsetY,
        cellW: plot.w / visibleCols,
        cellH: plot.h / visibleRows
      };
    }

    function drawBackground(width, height) {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = '#0a0f1d';
      ctx.fillRect(0, 0, width, height);
    }

    function drawAxes(info) {
      const { plot, visibleRows, visibleCols, startRow, startCol, cellW, cellH, totalCols } = info;

      ctx.strokeStyle = '#2a3554';
      ctx.lineWidth = 1;
      ctx.strokeRect(plot.x, plot.y, plot.w, plot.h);

      ctx.font = '12px Inter, system-ui, sans-serif';
      ctx.fillStyle = '#8ea0c9';
      ctx.textBaseline = 'middle';

      for (let r = 0; r < Math.ceil(visibleRows); r++) {
        const rowIndex = Math.floor(startRow + r);
        if (rowIndex >= symbols.length) break;
        const y = plot.y + r * cellH + cellH / 2;
        ctx.fillText(symbols[rowIndex], 10, y);
      }

      ctx.textBaseline = 'top';
      const desiredTicks = Math.max(2, Math.floor(plot.w / 120));
      const step = Math.max(1, Math.floor(visibleCols / desiredTicks));

      for (let c = 0; c < visibleCols; c += step) {
        const colIndex = Math.floor(startCol + c);
        if (colIndex >= totalCols) break;
        const x = plot.x + c * cellW;

        ctx.strokeStyle = '#1a2440';
        ctx.beginPath();
        ctx.moveTo(x, plot.y);
        ctx.lineTo(x, plot.y + plot.h);
        ctx.stroke();

        const ts = state.timestamps[colIndex];
        if (ts) {
          ctx.save();
          ctx.translate(x + 4, plot.y + plot.h + 6);
          ctx.fillStyle = '#8ea0c9';
          ctx.fillText(formatTime(ts), 0, 0);
          ctx.restore();
        }
      }

      for (let r = 0; r <= visibleRows; r++) {
        const y = plot.y + r * cellH;
        ctx.strokeStyle = '#16203a';
        ctx.beginPath();
        ctx.moveTo(plot.x, y);
        ctx.lineTo(plot.x + plot.w, y);
        ctx.stroke();
      }
    }

    function drawHeatmap(info) {
      const { plot, visibleRows, visibleCols, startRow, startCol, cellW, cellH } = info;

      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.clip();

      for (let r = 0; r < Math.ceil(visibleRows); r++) {
        const rowIndex = Math.floor(startRow + r);
        if (rowIndex >= symbols.length) break;

        const row = state.data[rowIndex];
        for (let c = 0; c < Math.ceil(visibleCols); c++) {
          const colIndex = Math.floor(startCol + c);
          if (colIndex >= state.timestamps.length) break;

          const value = row[colIndex];
          const x = plot.x + c * cellW;
          const y = plot.y + r * cellH;

          ctx.fillStyle = colorForValue(value);
          ctx.fillRect(x, y, Math.ceil(cellW) + 1, Math.ceil(cellH) + 1);
        }
      }

      ctx.restore();
    }

    function drawCrosshairAndTooltip(info) {
      const { plot, visibleRows, visibleCols, startRow, startCol, cellW, cellH } = info;
      const mx = state.interaction.mouseX;
      const my = state.interaction.mouseY;

      if (mx < plot.x || mx > plot.x + plot.w || my < plot.y || my > plot.y + plot.h) {
        tooltip.style.display = 'none';
        return;
      }

      const localX = mx - plot.x;
      const localY = my - plot.y;

      const c = Math.floor(localX / cellW);
      const r = Math.floor(localY / cellH);

      const rowIndex = Math.floor(startRow + r);
      const colIndex = Math.floor(startCol + c);

      if (
        rowIndex < 0 || rowIndex >= symbols.length ||
        colIndex < 0 || colIndex >= state.timestamps.length
      ) {
        tooltip.style.display = 'none';
        return;
      }

      const x = plot.x + c * cellW;
      const y = plot.y + r * cellH;
      const value = state.data[rowIndex][colIndex];
      const ts = state.timestamps[colIndex];

      ctx.save();
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, cellW, cellH);
      ctx.restore();

      tooltip.style.display = 'block';
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
      tooltip.innerHTML = `
        <div><strong>${symbols[rowIndex]}</strong></div>
        <div>Time: ${formatTime(ts)}</div>
        <div>Change: <strong>${value.toFixed(2)}%</strong></div>
      `;
    }

    function draw() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;
      drawBackground(width, height);
      const info = getVisibleWindow();
      drawHeatmap(info);
      drawAxes(info);
      drawCrosshairAndTooltip(info);
    }

    function zoomAt(mouseX, mouseY, deltaY) {
      const info = getVisibleWindow();
      const { plot } = info;

      const insidePlot =
        mouseX >= plot.x && mouseX <= plot.x + plot.w &&
        mouseY >= plot.y && mouseY <= plot.y + plot.h;

      if (!insidePlot) return;

      const zoomFactor = deltaY < 0 ? 1.12 : 0.89;
      const localXRatio = (mouseX - plot.x) / plot.w;
      const localYRatio = (mouseY - plot.y) / plot.h;

      const oldVisibleCols = info.visibleCols;
      const oldVisibleRows = info.visibleRows;

      state.view.scaleX = clamp(state.view.scaleX * zoomFactor, 1, 12);
      state.view.scaleY = clamp(state.view.scaleY * zoomFactor, 1, 8);

      const newInfo = getVisibleWindow();
      const newVisibleCols = newInfo.visibleCols;
      const newVisibleRows = newInfo.visibleRows;

      const anchorCol = state.view.offsetX + oldVisibleCols * localXRatio;
      const anchorRow = state.view.offsetY + oldVisibleRows * localYRatio;

      state.view.offsetX = anchorCol - newVisibleCols * localXRatio;
      state.view.offsetY = anchorRow - newVisibleRows * localYRatio;

      draw();
    }

    function resetView() {
      state.view.scaleX = 1;
      state.view.scaleY = 1;
      state.view.offsetX = 0;
      state.view.offsetY = 0;
      draw();
    }

    function restartStream() {
      if (state.timer) clearInterval(state.timer);
      state.timer = setInterval(() => {
        appendTick(true);

        const totalCols = state.timestamps.length;
        const visibleCols = clamp(totalCols / state.view.scaleX, 5, totalCols);
        const nearRightEdge = state.view.offsetX >= Math.max(0, totalCols - visibleCols - 2);

        if (nearRightEdge || state.view.scaleX === 1) {
          state.view.offsetX = Math.max(0, totalCols - visibleCols);
        }

        draw();
      }, state.updateInterval);
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      state.interaction.mouseX = e.clientX - rect.left;
      state.interaction.mouseY = e.clientY - rect.top;

      if (state.interaction.dragging) {
        const dx = state.interaction.mouseX - state.interaction.lastX;
        const dy = state.interaction.mouseY - state.interaction.lastY;

        const info = getVisibleWindow();
        state.view.offsetX -= dx / info.cellW;
        state.view.offsetY -= dy / info.cellH;

        state.interaction.lastX = state.interaction.mouseX;
        state.interaction.lastY = state.interaction.mouseY;
      }

      draw();
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('mousedown', (e) => {
      const rect = canvas.getBoundingClientRect();
      state.interaction.dragging = true;
      state.interaction.lastX = e.clientX - rect.left;
      state.interaction.lastY = e.clientY - rect.top;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.interaction.dragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      zoomAt(mx, my, e.deltaY);
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    intervalSelect.addEventListener('change', () => {
      state.updateInterval = Number(intervalSelect.value);
      restartStream();
    });

    historyInput.addEventListener('change', () => {
      state.maxHistory = clamp(Number(historyInput.value) || 120, 20, 500);
      historyInput.value = state.maxHistory;
      initData();
      resetView();
      restartStream();
    });

    volatilityInput.addEventListener('input', () => {
      state.volatility = Number(volatilityInput.value);
    });

    window.addEventListener('resize', resize);

    initData();
    resize();
    restartStream();
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `state.data` is a 2D array:
  - rows = symbols
  - columns = time ticks
- `state.timestamps` stores the time for each column

### Rendering
- The heatmap is drawn on a `<canvas>`
- Each cell is colored based on a percent change value
- Axes and labels are drawn on top

### Real-time updates
- `appendTick()` simulates a new price-change datapoint for each symbol
- old columns are removed once `maxHistory` is reached

### Zoom/pan
- `scaleX`, `scaleY` control zoom
- `offsetX`, `offsetY` control pan
- mouse wheel zooms around cursor position
- drag pans the visible window

---

## Notes / limitations of this initial version

This is a good starting point, but for production you’d likely want:

1. **Real market data**
   - replace `appendTick()` simulation with WebSocket/SSE updates

2. **Better color scaling**
   - dynamic domain based on rolling volatility
   - perceptually uniform color palette

3. **Improved axes**
   - smarter tick formatting
   - sticky row labels
   - better time scale handling

4. **Performance upgrades**
   - offscreen canvas
   - partial redraws
   - WebGL for very large grids

5. **Interaction improvements**
   - separate horizontal/vertical zoom modifiers
   - touch support
   - selection/brush zoom
   - keyboard navigation

6. **Data semantics**
   - absolute price, returns, volume, or order-book depth
   - market session boundaries
   - missing-data handling

