        to right,
        #8b0000 0%,
        #d73027 20%,
        #f46d43 35%,
        #2a2a2a 50%,
        #74add1 65%,
        #4575b4 80%,
        #1e3a8a 100%
      );
      border: 1px solid #2a3a72;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <h1>Realtime Stock Heatmap</h1>

    <button id="toggleStreamBtn">Pause Stream</button>
    <button id="resetViewBtn">Reset View</button>

    <label>
      Update Interval
      <select id="intervalSelect">
        <option value="250">250ms</option>
        <option value="500" selected>500ms</option>
        <option value="1000">1000ms</option>
      </select>
    </label>

    <label>
      Volatility
      <input id="volatilityInput" type="range" min="0.1" max="5" step="0.1" value="1.2" />
    </label>

    <div class="legend">
      <span>-</span>
      <div class="legend-bar"></div>
      <span>+</span>
    </div>

    <div class="status" id="statusText">Streaming live</div>
  </div>

  <div class="container">
    <div class="yLabels">
      <canvas id="yAxisCanvas"></canvas>
    </div>

    <div class="heatmapWrap" id="heatmapWrap">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="xAxis">
      <canvas id="xAxisCanvas"></canvas>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "CRM", "ORCL", "UBER", "SHOP", "PYPL",
      "ADBE", "QCOM", "AVGO", "SNOW", "PLTR"
    ];

    const state = {
      rows: symbols.length,
      cols: 240,
      data: [],
      timestamps: [],
      prices: {},
      returnsWindow: [],
      streamRunning: true,
      updateIntervalMs: 500,
      volatility: 1.2,

      view: {
        offsetX: 0,       // in columns
        scaleX: 8,        // pixels per column
        rowHeight: 28
      },

      interaction: {
        dragging: false,
        lastX: 0
      },

      hover: {
        row: -1,
        col: -1,
        x: 0,
        y: 0
      }
    };

    const heatmapCanvas = document.getElementById("heatmapCanvas");
    const yAxisCanvas = document.getElementById("yAxisCanvas");
    const xAxisCanvas = document.getElementById("xAxisCanvas");
    const heatmapWrap = document.getElementById("heatmapWrap");
    const tooltip = document.getElementById("tooltip");
    const toggleStreamBtn = document.getElementById("toggleStreamBtn");
    const resetViewBtn = document.getElementById("resetViewBtn");
    const intervalSelect = document.getElementById("intervalSelect");
    const volatilityInput = document.getElementById("volatilityInput");
    const statusText = document.getElementById("statusText");

    const heatCtx = heatmapCanvas.getContext("2d");
    const yCtx = yAxisCanvas.getContext("2d");
    const xCtx = xAxisCanvas.getContext("2d");

    function initData() {
      const now = Date.now();
      for (const symbol of symbols) {
        state.prices[symbol] = 100 + Math.random() * 200;
      }

      for (let c = 0; c < state.cols; c++) {
        const ts = now - (state.cols - c) * state.updateIntervalMs;
        state.timestamps.push(ts);

        const col = [];
        for (let r = 0; r < state.rows; r++) {
          const symbol = symbols[r];
          const change = randomNormal() * 0.3;
          state.prices[symbol] *= (1 + change / 100);
          col.push(change);
        }
        state.data.push(col);
      }

      state.view.offsetX = Math.max(0, state.cols - 80);
    }

    function randomNormal() {
      let u = 0, v = 0;
      while (u === 0) u = Math.random();
      while (v === 0) v = Math.random();
      return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
    }

    function appendDataColumn() {
      const ts = Date.now();
      const col = [];

      for (let r = 0; r < state.rows; r++) {
        const symbol = symbols[r];
        const drift = (Math.random() - 0.5) * 0.05;
        const shock = randomNormal() * state.volatility * 0.35;
        const pctChange = drift + shock;

        state.prices[symbol] *= (1 + pctChange / 100);
        col.push(pctChange);
      }

      state.data.push(col);
      state.timestamps.push(ts);

      const maxCols = 2000;
      if (state.data.length > maxCols) {
        state.data.shift();
        state.timestamps.shift();
        state.view.offsetX = Math.max(0, state.view.offsetX - 1);
      }

      const visibleCols = getVisibleColumnCount();
      const rightEdge = state.view.offsetX + visibleCols;
      const nearLiveEdge = rightEdge >= state.data.length - 2;

      if (nearLiveEdge) {
        state.view.offsetX = Math.max(0, state.data.length - visibleCols);
      }
    }

    function getVisibleColumnCount() {
      const width = heatmapWrap.clientWidth;
      return Math.max(1, Math.floor(width / state.view.scaleX));
    }

    function resizeCanvas(canvas, ctx) {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    function resizeAll() {
      resizeCanvas(heatmapCanvas, heatCtx);
      resizeCanvas(yAxisCanvas, yCtx);
      resizeCanvas(xAxisCanvas, xCtx);
      render();
    }

    function clampView() {
      const visibleCols = getVisibleColumnCount();
      const maxOffset = Math.max(0, state.data.length - visibleCols);
      state.view.offsetX = Math.max(0, Math.min(state.view.offsetX, maxOffset));
      state.view.scaleX = Math.max(2, Math.min(state.view.scaleX, 60));
    }

    function colorForValue(v) {
      const clamped = Math.max(-3, Math.min(3, v));
      const t = (clamped + 3) / 6;

      const stops = [
        { t: 0.0, c: [139, 0, 0] },
        { t: 0.2, c: [215, 48, 39] },
        { t: 0.35, c: [244, 109, 67] },
        { t: 0.5, c: [42, 42, 42] },
        { t: 0.65, c: [116, 173, 209] },
        { t: 0.8, c: [69, 117, 180] },
        { t: 1.0, c: [30, 58, 138] }
      ];

      for (let i = 0; i < stops.length - 1; i++) {
        const a = stops[i];
        const b = stops[i + 1];
        if (t >= a.t && t <= b.t) {
          const localT = (t - a.t) / (b.t - a.t);
          const r = Math.round(a.c[0] + (b.c[0] - a.c[0]) * localT);
          const g = Math.round(a.c[1] + (b.c[1] - a.c[1]) * localT);
          const bch = Math.round(a.c[2] + (b.c[2] - a.c[2]) * localT);
          return `rgb(${r},${g},${bch})`;
        }
      }
      return "rgb(42,42,42)";
    }

    function renderHeatmap() {
      const width = heatmapWrap.clientWidth;
      const height = heatmapWrap.clientHeight;
      heatCtx.clearRect(0, 0, width, height);

      const rowHeight = state.view.rowHeight;
      const scaleX = state.view.scaleX;
      const startCol = Math.floor(state.view.offsetX);
      const visibleCols = getVisibleColumnCount() + 1;

      heatCtx.fillStyle = "#09101f";
      heatCtx.fillRect(0, 0, width, height);

      for (let r = 0; r < state.rows; r++) {
        const y = r * rowHeight;
        if (y > height) break;

        for (let i = 0; i < visibleCols; i++) {
          const colIndex = startCol + i;
          if (colIndex < 0 || colIndex >= state.data.length) continue;

          const x = (colIndex - state.view.offsetX) * scaleX;
          const value = state.data[colIndex][r];

          heatCtx.fillStyle = colorForValue(value);
          heatCtx.fillRect(x, y, Math.ceil(scaleX), rowHeight);
        }
      }

      heatCtx.strokeStyle = "rgba(255,255,255,0.08)";
      heatCtx.lineWidth = 1;

      for (let r = 0; r <= state.rows; r++) {
        const y = r * rowHeight + 0.5;
        heatCtx.beginPath();
        heatCtx.moveTo(0, y);
        heatCtx.lineTo(width, y);
        heatCtx.stroke();
      }

      if (scaleX >= 8) {
        for (let i = 0; i < visibleCols; i++) {
          const colIndex = startCol + i;
          const x = Math.floor((colIndex - state.view.offsetX) * scaleX) + 0.5;
          heatCtx.beginPath();
          heatCtx.moveTo(x, 0);
          heatCtx.lineTo(x, height);
          heatCtx.stroke();
        }
      }

      if (state.hover.row >= 0 && state.hover.col >= 0) {
        const x = (state.hover.col - state.view.offsetX) * scaleX;
        const y = state.hover.row * rowHeight;
        heatCtx.strokeStyle = "rgba(255,255,255,0.9)";
        heatCtx.lineWidth = 2;
        heatCtx.strokeRect(x + 1, y + 1, Math.max(0, scaleX - 2), rowHeight - 2);
      }
    }

    function renderYAxis() {
      const width = yAxisCanvas.parentElement.clientWidth;
      const height = yAxisCanvas.parentElement.clientHeight;
      yCtx.clearRect(0, 0, width, height);

      yCtx.fillStyle = "#0f1731";
      yCtx.fillRect(0, 0, width, height);

      yCtx.font = "12px system-ui, sans-serif";
      yCtx.textBaseline = "middle";

      for (let r = 0; r < state.rows; r++) {
        const y = r * state.view.rowHeight;
        if (y > height) break;

        if (state.hover.row === r) {
          yCtx.fillStyle = "rgba(110,168,254,0.18)";
          yCtx.fillRect(0, y, width, state.view.rowHeight);
        }

        yCtx.strokeStyle = "rgba(255,255,255,0.08)";
        yCtx.beginPath();
        yCtx.moveTo(0, y + 0.5);
        yCtx.lineTo(width, y + 0.5);
        yCtx.stroke();

        yCtx.fillStyle = "#dbe4ff";
        yCtx.fillText(symbols[r], 12, y + state.view.rowHeight / 2);
      }
    }

    function renderXAxis() {
      const width = xAxisCanvas.parentElement.clientWidth;
      const height = xAxisCanvas.parentElement.clientHeight;
      xCtx.clearRect(0, 0, width, height);

      xCtx.fillStyle = "#0f1731";
      xCtx.fillRect(0, 0, width, height);

      const scaleX = state.view.scaleX;
      const startCol = Math.floor(state.view.offsetX);
      const visibleCols = getVisibleColumnCount() + 1;

      xCtx.font = "11px system-ui, sans-serif";
      xCtx.textBaseline = "middle";
      xCtx.fillStyle = "#8ea0d6";
      xCtx.strokeStyle = "rgba(255,255,255,0.08)";

      const labelEvery = scaleX < 6 ? 10 : scaleX < 12 ? 5 : 2;

      for (let i = 0; i < visibleCols; i++) {
        const colIndex = startCol + i;
        if (colIndex < 0 || colIndex >= state.timestamps.length) continue;
        if (colIndex % labelEvery !== 0) continue;

        const x = (colIndex - state.view.offsetX) * scaleX;
        const date = new Date(state.timestamps[colIndex]);
        const label = date.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit"
        });

        xCtx.beginPath();
        xCtx.moveTo(x + 0.5, 0);
        xCtx.lineTo(x + 0.5, height);
        xCtx.stroke();

        xCtx.fillText(label, x + 4, height / 2);
      }
    }

    function render() {
      clampView();
      renderHeatmap();
      renderYAxis();
      renderXAxis();
      renderTooltip();
    }

    function renderTooltip() {
      const { row, col, x, y } = state.hover;
      if (row < 0 || col < 0 || !state.data[col]) {
        tooltip.style.display = "none";
        return;
      }

      const symbol = symbols[row];
      const value = state.data[col][row];
      const ts = state.timestamps[col];
      const price = state.prices[symbol];

      tooltip.innerHTML = `
        <strong>${symbol}</strong><br/>
        Change: ${value.toFixed(2)}%<br/>
        Time: ${new Date(ts).toLocaleTimeString()}<br/>
        Latest Price: $${price.toFixed(2)}
      `;
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
      tooltip.style.display = "block";
    }

    function updateHover(clientX, clientY) {
      const rect = heatmapCanvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const row = Math.floor(y / state.view.rowHeight);
      const col = Math.floor(state.view.offsetX + x / state.view.scaleX);

      if (
        row >= 0 && row < state.rows &&
        col >= 0 && col < state.data.length
      ) {
        state.hover.row = row;
        state.hover.col = col;
        state.hover.x = x;
        state.hover.y = y;
      } else {
        state.hover.row = -1;
        state.hover.col = -1;
      }

      render();
    }

    heatmapWrap.addEventListener("mousemove", (e) => {
      if (state.interaction.dragging) {
        const dx = e.clientX - state.interaction.lastX;
        state.interaction.lastX = e.clientX;
        state.view.offsetX -= dx / state.view.scaleX;
        clampView();
        render();
      } else {
        updateHover(e.clientX, e.clientY);
      }
    });

    heatmapWrap.addEventListener("mouseleave", () => {
      state.hover.row = -1;
      state.hover.col = -1;
      render();
    });

    heatmapWrap.addEventListener("mousedown", (e) => {
      state.interaction.dragging = true;
      state.interaction.lastX = e.clientX;
      heatmapWrap.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      state.interaction.dragging = false;
      heatmapWrap.classList.remove("dragging");
    });

    heatmapWrap.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = heatmapCanvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const anchorCol = state.view.offsetX + mouseX / state.view.scaleX;

      const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
      state.view.scaleX *= zoomFactor;
      state.view.scaleX = Math.max(2, Math.min(60, state.view.scaleX));

      state.view.offsetX = anchorCol - mouseX / state.view.scaleX;
      clampView();
      render();
    }, { passive: false });

    toggleStreamBtn.addEventListener("click", () => {
      state.streamRunning = !state.streamRunning;
      toggleStreamBtn.textContent = state.streamRunning ? "Pause Stream" : "Resume Stream";
      statusText.textContent = state.streamRunning ? "Streaming live" : "Streaming paused";
    });

    resetViewBtn.addEventListener("click", () => {
      state.view.scaleX = 8;
      state.view.offsetX = Math.max(0, state.data.length - getVisibleColumnCount());
      render();
    });

    intervalSelect.addEventListener("change", () => {
      state.updateIntervalMs = Number(intervalSelect.value);
      restartStream();
    });

    volatilityInput.addEventListener("input", () => {
      state.volatility = Number(volatilityInput.value);
    });

    let streamTimer = null;

    function restartStream() {
      if (streamTimer) clearInterval(streamTimer);
      streamTimer = setInterval(() => {
        if (!state.streamRunning) return;
        appendDataColumn();
        render();
      }, state.updateIntervalMs);
    }

    window.addEventListener("resize", resizeAll);

    initData();
    resizeAll();
    restartStream();
  </script>
</body>
</html>
```

