      color: var(--muted);
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetBtn">Reset View</button>
      <div class="status" id="status">Streaming updates...</div>
      <div class="legend">
        <span>-5%</span>
        <div class="gradient"></div>
        <span>+5%</span>
      </div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const statusEl = document.getElementById("status");

    const DPR = window.devicePixelRatio || 1;

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "ADBE"
    ];

    const totalTimeSteps = 180; // columns
    const visibleInitialCols = 60;

    // data[row][col] = % change
    let data = symbols.map(() => {
      const row = [];
      let base = (Math.random() - 0.5) * 2;
      for (let i = 0; i < totalTimeSteps; i++) {
        base += (Math.random() - 0.5) * 0.6;
        base = clamp(base, -5, 5);
        row.push(base);
      }
      return row;
    });

    const margin = {
      top: 20,
      right: 20,
      bottom: 40,
      left: 80
    };

    const view = {
      offsetX: totalTimeSteps - visibleInitialCols,
      offsetY: 0,
      scaleX: totalTimeSteps / visibleInitialCols,
      scaleY: 1
    };

    let isDragging = false;
    let lastMouse = null;
    let hoverCell = null;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function getChartArea() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;
      return {
        x: margin.left,
        y: margin.top,
        width: width - margin.left - margin.right,
        height: height - margin.top - margin.bottom
      };
    }

    function getVisibleCols() {
      return totalTimeSteps / view.scaleX;
    }

    function getVisibleRows() {
      return symbols.length / view.scaleY;
    }

    function colorForValue(v) {
      const min = -5;
      const max = 5;
      const t = clamp((v - min) / (max - min), 0, 1);

      // red -> dark neutral -> green
      if (t < 0.5) {
        const local = t / 0.5;
        return lerpColor([139, 0, 0], [44, 44, 44], local);
      } else {
        const local = (t - 0.5) / 0.5;
        return lerpColor([44, 44, 44], [0, 109, 44], local);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    function draw() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;
      const chart = getChartArea();

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#171a2b";
      ctx.fillRect(0, 0, width, height);

      const visibleCols = getVisibleCols();
      const visibleRows = getVisibleRows();

      view.offsetX = clamp(view.offsetX, 0, Math.max(0, totalTimeSteps - visibleCols));
      view.offsetY = clamp(view.offsetY, 0, Math.max(0, symbols.length - visibleRows));

      const cellW = chart.width / visibleCols;
      const cellH = chart.height / visibleRows;

      // Heatmap cells
      const startCol = Math.floor(view.offsetX);
      const endCol = Math.min(totalTimeSteps, Math.ceil(view.offsetX + visibleCols));
      const startRow = Math.floor(view.offsetY);
      const endRow = Math.min(symbols.length, Math.ceil(view.offsetY + visibleRows));

      for (let r = startRow; r < endRow; r++) {
        for (let c = startCol; c < endCol; c++) {
          const x = chart.x + (c - view.offsetX) * cellW;
          const y = chart.y + (r - view.offsetY) * cellH;
          const val = data[r][c];

          ctx.fillStyle = colorForValue(val);
          ctx.fillRect(x, y, Math.ceil(cellW) + 1, Math.ceil(cellH) + 1);
        }
      }

      // Grid
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let c = 0; c <= visibleCols; c++) {
        const x = chart.x + c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, chart.y);
        ctx.lineTo(x, chart.y + chart.height);
        ctx.stroke();
      }

      for (let r = 0; r <= visibleRows; r++) {
        const y = chart.y + r * cellH;
        ctx.beginPath();
        ctx.moveTo(chart.x, y);
        ctx.lineTo(chart.x + chart.width, y);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "#dbe2ff";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";

      for (let r = startRow; r < endRow; r++) {
        const y = chart.y + (r - view.offsetY + 0.5) * cellH;
        if (y >= chart.y && y <= chart.y + chart.height) {
          ctx.fillText(symbols[r], chart.x - 8, y);
        }
      }

      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      const tickCount = Math.min(8, Math.floor(visibleCols));
      for (let i = 0; i <= tickCount; i++) {
        const col = view.offsetX + (visibleCols * i / tickCount);
        const x = chart.x + (col - view.offsetX) * cellW;
        const label = `T-${Math.max(0, Math.round(totalTimeSteps - col - 1))}`;
        ctx.fillStyle = "#93a0c8";
        ctx.fillText(label, x, chart.y + chart.height + 8);
      }

      // Hover highlight
      if (hoverCell) {
        const { row, col } = hoverCell;
        if (
          row >= startRow && row < endRow &&
          col >= startCol && col < endCol
        ) {
          const x = chart.x + (col - view.offsetX) * cellW;
          const y = chart.y + (row - view.offsetY) * cellH;
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
        }
      }
    }

    function screenToCell(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const chart = getChartArea();

      if (
        x < chart.x || x > chart.x + chart.width ||
        y < chart.y || y > chart.y + chart.height
      ) {
        return null;
      }

      const visibleCols = getVisibleCols();
      const visibleRows = getVisibleRows();
      const cellW = chart.width / visibleCols;
      const cellH = chart.height / visibleRows;

      const col = Math.floor(view.offsetX + (x - chart.x) / cellW);
      const row = Math.floor(view.offsetY + (y - chart.y) / cellH);

      if (
        row < 0 || row >= symbols.length ||
        col < 0 || col >= totalTimeSteps
      ) {
        return null;
      }

      return { row, col, x, y };
    }

    canvas.addEventListener("mousemove", (e) => {
      const cell = screenToCell(e.clientX, e.clientY);

      if (isDragging && lastMouse) {
        const dx = e.clientX - lastMouse.x;
        const dy = e.clientY - lastMouse.y;

        const chart = getChartArea();
        const visibleCols = getVisibleCols();
        const visibleRows = getVisibleRows();

        const cellW = chart.width / visibleCols;
        const cellH = chart.height / visibleRows;

        view.offsetX -= dx / cellW;
        view.offsetY -= dy / cellH;

        lastMouse = { x: e.clientX, y: e.clientY };
        draw();
        tooltip.style.display = "none";
        return;
      }

      hoverCell = cell ? { row: cell.row, col: cell.col } : null;

      if (cell) {
        const value = data[cell.row][cell.col];
        tooltip.style.display = "block";
        tooltip.style.left = `${cell.x}px`;
        tooltip.style.top = `${cell.y}px`;
        tooltip.innerHTML = `
          <strong>${symbols[cell.row]}</strong><br>
          Time Index: ${cell.col}<br>
          Change: ${value.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = "none";
      }

      draw();
    });

    canvas.addEventListener("mouseleave", () => {
      hoverCell = null;
      tooltip.style.display = "none";
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastMouse = { x: e.clientX, y: e.clientY };
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      lastMouse = null;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const cell = screenToCell(e.clientX, e.clientY);
      if (!cell) return;

      const prevVisibleCols = getVisibleCols();
      const prevVisibleRows = getVisibleRows();

      view.scaleX = clamp(view.scaleX * zoomFactor, 1, 12);
      view.scaleY = clamp(view.scaleY * zoomFactor, 1, 6);

      const nextVisibleCols = getVisibleCols();
      const nextVisibleRows = getVisibleRows();

      const anchorColRatio = (cell.col - view.offsetX) / prevVisibleCols;
      const anchorRowRatio = (cell.row - view.offsetY) / prevVisibleRows;

      view.offsetX = cell.col - anchorColRatio * nextVisibleCols;
      view.offsetY = cell.row - anchorRowRatio * nextVisibleRows;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      view.offsetX = totalTimeSteps - visibleInitialCols;
      view.offsetY = 0;
      view.scaleX = totalTimeSteps / visibleInitialCols;
      view.scaleY = 1;
      draw();
    });

    function pushRealtimeData() {
      for (let r = 0; r < symbols.length; r++) {
        const prev = data[r][data[r].length - 1];
        let next = prev + (Math.random() - 0.5) * 0.8;
        next = clamp(next, -5, 5);
        data[r].push(next);
        data[r].shift();
      }

      statusEl.textContent = `Streaming updates... ${new Date().toLocaleTimeString()}`;
      draw();
    }

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    draw();

    setInterval(pushRealtimeData, 1000);
  </script>
</body>
</html>
```

