    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 14, 24, 0.95);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      min-width: 160px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
    }

    .legend {
      position: absolute;
      right: 16px;
      bottom: 16px;
      width: 220px;
      background: rgba(18, 26, 43, 0.92);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      backdrop-filter: blur(4px);
    }

    .legend-title {
      font-size: 12px;
      color: var(--muted);
      margin-bottom: 8px;
    }

    .legend-bar {
      height: 14px;
      border-radius: 999px;
      background: linear-gradient(
        to right,
        rgb(180, 35, 35),
        rgb(220, 120, 50),
        rgb(80, 80, 80),
        rgb(60, 170, 90),
        rgb(20, 200, 120)
      );
      border: 1px solid var(--border);
    }

    .legend-labels {
      display: flex;
      justify-content: space-between;
      font-size: 11px;
      color: var(--muted);
      margin-top: 6px;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>

      <div class="group">
        <label for="stockCount">Stocks</label>
        <input id="stockCount" type="number" min="10" max="500" value="60" />
      </div>

      <div class="group">
        <label for="timeSteps">Time Steps</label>
        <input id="timeSteps" type="number" min="20" max="500" value="120" />
      </div>

      <div class="group">
        <label for="updateMs">Update ms</label>
        <input id="updateMs" type="number" min="100" max="5000" step="100" value="1000" />
      </div>

      <div class="group">
        <button id="resetBtn">Reset</button>
        <button id="pauseBtn">Pause</button>
      </div>

      <div class="status" id="status">Running</div>
    </div>

    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-title">Price Change %</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, container, tooltip, statusEl) {
        this.canvas = canvas;
        this.container = container;
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.ctx = canvas.getContext('2d');

        this.dpr = window.devicePixelRatio || 1;

        this.stocks = [];
        this.data = [];
        this.timeLabels = [];

        this.stockCount = 60;
        this.timeSteps = 120;
        this.updateMs = 1000;
        this.timer = null;
        this.running = true;

        this.baseCellWidth = 18;
        this.baseCellHeight = 18;
        this.scale = 1;
        this.minScale = 0.4;
        this.maxScale = 4;
        this.offsetX = 120;
        this.offsetY = 40;

        this.headerHeight = 30;
        this.labelWidth = 100;

        this.dragging = false;
        this.lastMouseX = 0;
        this.lastMouseY = 0;
        this.hoveredCell = null;

        this.priceRange = 5; // +/- 5%

        this.bindEvents();
        this.resize();
        this.initializeData();
        this.start();
        this.render();
      }

      bindEvents() {
        window.addEventListener('resize', () => {
          this.resize();
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => this.onWheel(e), { passive: false });
        this.canvas.addEventListener('mousedown', (e) => this.onMouseDown(e));
        window.addEventListener('mousemove', (e) => this.onMouseMove(e));
        window.addEventListener('mouseup', () => this.onMouseUp());
        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
          this.hoveredCell = null;
          this.render();
        });
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      }

      initializeData() {
        this.stocks = Array.from({ length: this.stockCount }, (_, i) => ({
          symbol: this.generateTicker(i),
          basePrice: 50 + Math.random() * 250,
          sector: ['Tech', 'Finance', 'Energy', 'Health', 'Retail'][i % 5]
        }));

        this.timeLabels = [];
        const now = Date.now();
        for (let t = this.timeSteps - 1; t >= 0; t--) {
          this.timeLabels.push(this.formatTime(now - t * this.updateMs));
        }

        this.data = this.stocks.map(stock => {
          let prev = 0;
          const row = [];
          for (let t = 0; t < this.timeSteps; t++) {
            prev += (Math.random() - 0.5) * 1.2;
            prev = Math.max(-this.priceRange, Math.min(this.priceRange, prev));
            row.push({
              changePct: prev,
              price: stock.basePrice * (1 + prev / 100),
              volume: Math.floor(1000 + Math.random() * 50000)
            });
          }
          return row;
        });
      }

      generateTicker(i) {
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const a = letters[i % 26];
        const b = letters[Math.floor(i / 26) % 26];
        const c = letters[Math.floor(i / 676) % 26];
        return (a + b + c).replace(/A+$/, 'A').slice(0, 4);
      }

      formatTime(ts) {
        const d = new Date(ts);
        return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      }

      start() {
        this.stop();
        this.running = true;
        this.statusEl.textContent = 'Running';
        this.timer = setInterval(() => this.tick(), this.updateMs);
      }

      stop() {
        if (this.timer) {
          clearInterval(this.timer);
          this.timer = null;
        }
      }

      tick() {
        const now = Date.now();
        this.timeLabels.shift();
        this.timeLabels.push(this.formatTime(now));

        for (let i = 0; i < this.stocks.length; i++) {
          const row = this.data[i];
          const last = row[row.length - 1];
          let nextChange = last.changePct + (Math.random() - 0.5) * 1.0;
          nextChange = Math.max(-this.priceRange, Math.min(this.priceRange, nextChange));

          row.shift();
          row.push({
            changePct: nextChange,
            price: this.stocks[i].basePrice * (1 + nextChange / 100),
            volume: Math.floor(1000 + Math.random() * 50000)
          });
        }

        this.render();
      }

      reset(stockCount, timeSteps, updateMs) {
        this.stockCount = stockCount;
        this.timeSteps = timeSteps;
        this.updateMs = updateMs;
        this.scale = 1;
        this.offsetX = 120;
        this.offsetY = 40;
        this.initializeData();
        if (this.running) this.start();
        this.render();
      }

      onWheel(e) {
        e.preventDefault();

        const rect = this.canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        const oldScale = this.scale;
        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        this.scale = Math.max(this.minScale, Math.min(this.maxScale, this.scale * zoomFactor));

        const worldX = (mouseX - this.offsetX) / oldScale;
        const worldY = (mouseY - this.offsetY) / oldScale;

        this.offsetX = mouseX - worldX * this.scale;
        this.offsetY = mouseY - worldY * this.scale;

        this.render();
      }

      onMouseDown(e) {
        this.dragging = true;
        this.lastMouseX = e.clientX;
        this.lastMouseY = e.clientY;
        this.canvas.classList.add('dragging');
      }

      onMouseMove(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (this.dragging) {
          const dx = e.clientX - this.lastMouseX;
          const dy = e.clientY - this.lastMouseY;
          this.offsetX += dx;
          this.offsetY += dy;
          this.lastMouseX = e.clientX;
          this.lastMouseY = e.clientY;
          this.render();
          return;
        }

        const cell = this.getCellAt(x, y);
        if (cell) {
          this.hoveredCell = cell;
          this.showTooltip(x, y, cell);
        } else {
          this.hoveredCell = null;
          this.tooltip.style.display = 'none';
        }
        this.render();
      }

      onMouseUp() {
        this.dragging = false;
        this.canvas.classList.remove('dragging');
      }

      getCellAt(screenX, screenY) {
        const x = (screenX - this.offsetX) / this.scale;
        const y = (screenY - this.offsetY) / this.scale;

        const gridX = x - this.labelWidth;
        const gridY = y - this.headerHeight;

        if (gridX < 0 || gridY < 0) return null;

        const col = Math.floor(gridX / this.baseCellWidth);
        const row = Math.floor(gridY / this.baseCellHeight);

        if (
          row >= 0 && row < this.stocks.length &&
          col >= 0 && col < this.timeSteps
        ) {
          return {
            row,
            col,
            stock: this.stocks[row],
            point: this.data[row][col],
            time: this.timeLabels[col]
          };
        }

        return null;
      }

      showTooltip(x, y, cell) {
        const { stock, point, time } = cell;
        this.tooltip.innerHTML = `
          <div><strong>${stock.symbol}</strong> <span style="color:#8ea0c9">(${stock.sector})</span></div>
          <div>Time: ${time}</div>
          <div>Price: $${point.price.toFixed(2)}</div>
          <div>Change: <span style="color:${this.getTextColor(point.changePct)}">${point.changePct.toFixed(2)}%</span></div>
          <div>Volume: ${point.volume.toLocaleString()}</div>
        `;
        this.tooltip.style.display = 'block';
        this.tooltip.style.left = Math.min(x + 14, this.container.clientWidth - 180) + 'px';
        this.tooltip.style.top = Math.min(y + 14, this.container.clientHeight - 100) + 'px';
      }

      getTextColor(value) {
        if (value > 0.2) return '#4fd18b';
        if (value < -0.2) return '#ff7b72';
        return '#dbe4ff';
      }

      getColor(value) {
        const clamped = Math.max(-this.priceRange, Math.min(this.priceRange, value));
        const normalized = (clamped + this.priceRange) / (2 * this.priceRange);

        if (normalized < 0.5) {
          const t = normalized / 0.5;
          return this.lerpColor(
            [180, 35, 35],
            [80, 80, 80],
            t
          );
        } else {
          const t = (normalized - 0.5) / 0.5;
          return this.lerpColor(
            [80, 80, 80],
            [20, 200, 120],
            t
          );
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        ctx.save();
        ctx.translate(this.offsetX, this.offsetY);
        ctx.scale(this.scale, this.scale);

        this.drawHeaders(ctx);
        this.drawGrid(ctx);

        ctx.restore();

        this.drawOverlay(ctx, width, height);
      }

      drawHeaders(ctx) {
        ctx.fillStyle = '#dbe4ff';
        ctx.font = '12px sans-serif';
        ctx.textBaseline = 'middle';

        for (let r = 0; r < this.stocks.length; r++) {
          const y = this.headerHeight + r * this.baseCellHeight + this.baseCellHeight / 2;
          ctx.fillStyle = '#8ea0c9';
          ctx.fillText(this.stocks[r].symbol, 8, y);
        }

        for (let c = 0; c < this.timeSteps; c++) {
          const x = this.labelWidth + c * this.baseCellWidth + this.baseCellWidth / 2;
          ctx.save();
          ctx.translate(x, this.headerHeight - 6);
          ctx.rotate(-Math.PI / 4);
          ctx.fillStyle = '#8ea0c9';
          ctx.fillText(this.timeLabels[c], 0, 0);
          ctx.restore();
        }
      }

      drawGrid(ctx) {
        for (let r = 0; r < this.stocks.length; r++) {
          for (let c = 0; c < this.timeSteps; c++) {
            const x = this.labelWidth + c * this.baseCellWidth;
            const y = this.headerHeight + r * this.baseCellHeight;
            const point = this.data[r][c];

            ctx.fillStyle = this.getColor(point.changePct);
            ctx.fillRect(x, y, this.baseCellWidth - 1, this.baseCellHeight - 1);

            if (this.hoveredCell && this.hoveredCell.row === r && this.hoveredCell.col === c) {
              ctx.strokeStyle = '#ffffff';
              ctx.lineWidth = 2 / this.scale;
              ctx.strokeRect(x + 1, y + 1, this.baseCellWidth - 3, this.baseCellHeight - 3);
            }
          }
        }

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1 / this.scale;

        const totalWidth = this.labelWidth + this.timeSteps * this.baseCellWidth;
        const totalHeight = this.headerHeight + this.stocks.length * this.baseCellHeight;

        for (let r = 0; r <= this.stocks.length; r++) {
          const y = this.headerHeight + r * this.baseCellHeight;
          ctx.beginPath();
          ctx.moveTo(this.labelWidth, y);
          ctx.lineTo(totalWidth, y);
          ctx.stroke();
        }

        for (let c = 0; c <= this.timeSteps; c++) {
          const x = this.labelWidth + c * this.baseCellWidth;
          ctx.beginPath();
          ctx.moveTo(x, this.headerHeight);
          ctx.lineTo(x, totalHeight);
          ctx.stroke();
        }
      }

      drawOverlay(ctx, width, height) {
        ctx.fillStyle = 'rgba(18, 26, 43, 0.9)';
        ctx.fillRect(10, height - 40, 220, 28);
        ctx.fillStyle = '#dbe4ff';
        ctx.font = '12px sans-serif';
        ctx.fillText(
          `Zoom: ${this.scale.toFixed(2)}x | Pan: (${Math.round(this.offsetX)}, ${Math.round(this.offsetY)})`,
          18,
          height - 22
        );
      }
    }

    const canvas = document.getElementById('heatmap');
    const container = document.getElementById('container');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const stockCountInput = document.getElementById('stockCount');
    const timeStepsInput = document.getElementById('timeSteps');
    const updateMsInput = document.getElementById('updateMs');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    const heatmap = new StockHeatmap(canvas, container, tooltip, statusEl);

    resetBtn.addEventListener('click', () => {
      const stockCount = parseInt(stockCountInput.value, 10);
      const timeSteps = parseInt(timeStepsInput.value, 10);
      const updateMs = parseInt(updateMsInput.value, 10);
      heatmap.reset(stockCount, timeSteps, updateMs);
    });

    pauseBtn.addEventListener('click', () => {
      if (heatmap.running) {
        heatmap.running = false;
        heatmap.stop();
        pauseBtn.textContent = 'Resume';
        statusEl.textContent = 'Paused';
      } else {
        heatmap.running = true;
        heatmap.start();
        pauseBtn.textContent = 'Pause';
      }
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
- Rows = stocks
- Columns = time steps
- Each cell stores:
  - `changePct`
  - `price`
  - `volume`

### Real-time updates
- A timer shifts old values left
- Appends a new simulated price point to each stock row
- Updates time labels

### Zoom/pan
- **Mouse wheel** changes scale
- **Drag** moves viewport
- Zoom centers around cursor position

### Rendering
- Uses **Canvas 2D**
- Draws:
  - stock labels
  - time labels
  - heatmap cells
  - hover highlight
  - status overlay

