  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.dpr = window.devicePixelRatio || 1;

        this.margin = {
          top: 30,
          right: 20,
          bottom: 40,
          left: 90
        };

        this.symbols = [];
        this.data = [];
        this.timestamps = [];
        this.basePrices = new Map();

        this.maxPoints = 120;
        this.streaming = true;
        this.streamTimer = null;

        this.view = {
          offsetX: 0,
          scaleX: 1
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          hoverCell: null
        };

        this.colorRange = {
          min: -0.03,
          max: 0.03
        };

        this.initSymbols(20);
        this.initData();
        this.attachEvents();
        this.resize();
        this.startStream();
        this.render();
      }

      initSymbols(count) {
        const pool = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'META', 'NVDA', 'TSLA', 'NFLX',
          'AMD', 'INTC', 'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA', 'PYPL',
          'ADBE', 'QCOM', 'AVGO', 'CSCO', 'IBM', 'SONY', 'SAP', 'SQ',
          'PLTR', 'SNOW', 'ZM', 'DOCU', 'COIN', 'ROKU', 'TWLO', 'PANW',
          'DDOG', 'NET', 'TEAM', 'OKTA', 'MDB', 'ZS', 'SE', 'MELI'
        ];

        this.symbols = pool.slice(0, count);
        this.basePrices.clear();

        for (const symbol of this.symbols) {
          this.basePrices.set(symbol, 50 + Math.random() * 450);
        }
      }

      initData() {
        this.timestamps = [];
        this.data = [];

        const now = Date.now();
        for (let i = this.maxPoints - 1; i >= 0; i--) {
          const ts = now - i * 1000;
          this.timestamps.push(ts);
        }

        for (let row = 0; row < this.symbols.length; row++) {
          const rowData = [];
          let drift = 0;
          for (let col = 0; col < this.maxPoints; col++) {
            drift += (Math.random() - 0.5) * 0.004;
            drift *= 0.9;
            rowData.push(this.clamp(drift, -0.04, 0.04));
          }
          this.data.push(rowData);
        }

        this.view.offsetX = 0;
        this.view.scaleX = 1;
      }

      startStream() {
        this.stopStream();
        this.streamTimer = setInterval(() => {
          if (!this.streaming) return;
          this.pushDataPoint();
          this.render();
        }, 400);
      }

      stopStream() {
        if (this.streamTimer) {
          clearInterval(this.streamTimer);
          this.streamTimer = null;
        }
      }

      pushDataPoint() {
        const ts = Date.now();
        this.timestamps.push(ts);
        if (this.timestamps.length > this.maxPoints) {
          this.timestamps.shift();
        }

        for (let row = 0; row < this.symbols.length; row++) {
          const prev = this.data[row][this.data[row].length - 1] || 0;
          const next = this.clamp(prev + (Math.random() - 0.5) * 0.01, -0.05, 0.05);
          this.data[row].push(next);
          if (this.data[row].length > this.maxPoints) {
            this.data[row].shift();
          }
        }
      }

      attachEvents() {
        window.addEventListener('resize', () => {
          this.resize();
          this.render();
        });

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            this.interaction.lastX = e.clientX;
            this.pan(dx);
            this.render();
          }

          this.updateHover(x, y, e.clientX, e.clientY);
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();
          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const delta = e.deltaY > 0 ? 0.9 : 1.1;
          this.zoom(mouseX, delta);
          this.render();
        }, { passive: false });
      }

      resize() {
        const rect = this.canvas.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      }

      pan(dx) {
        const plotWidth = this.width - this.margin.left - this.margin.right;
        const totalWidth = plotWidth * this.view.scaleX;
        const maxOffset = Math.max(0, totalWidth - plotWidth);
        this.view.offsetX = this.clamp(this.view.offsetX - dx, 0, maxOffset);
      }

      zoom(mouseX, factor) {
        const plotX = this.margin.left;
        const plotWidth = this.width - this.margin.left - this.margin.right;
        if (mouseX < plotX || mouseX > plotX + plotWidth) return;

        const oldScale = this.view.scaleX;
        const newScale = this.clamp(oldScale * factor, 1, 12);

        const rel = (mouseX - plotX + this.view.offsetX) / (plotWidth * oldScale);
        this.view.scaleX = newScale;

        const totalWidth = plotWidth * newScale;
        const newOffset = rel * totalWidth - (mouseX - plotX);
        const maxOffset = Math.max(0, totalWidth - plotWidth);
        this.view.offsetX = this.clamp(newOffset, 0, maxOffset);
      }

      updateHover(x, y, clientX, clientY) {
        const plot = this.getPlotRect();
        if (
          x < plot.x || x > plot.x + plot.width ||
          y < plot.y || y > plot.y + plot.height
        ) {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
          return;
        }

        const rowHeight = plot.height / this.symbols.length;
        const visibleCols = this.maxPoints / this.view.scaleX;
        const colWidth = plot.width / visibleCols;
        const startCol = this.view.offsetX / (plot.width * this.view.scaleX) * this.maxPoints;

        const row = Math.floor((y - plot.y) / rowHeight);
        const col = Math.floor(startCol + (x - plot.x) / colWidth);

        if (
          row >= 0 && row < this.symbols.length &&
          col >= 0 && col < this.maxPoints
        ) {
          const value = this.data[row][col];
          const ts = this.timestamps[col];
          this.interaction.hoverCell = { row, col };

          this.tooltip.style.display = 'block';
          this.tooltip.style.left = `${clientX}px`;
          this.tooltip.style.top = `${clientY}px`;
          this.tooltip.innerHTML = `
            <div><strong>${this.symbols[row]}</strong></div>
            <div>Change: ${(value * 100).toFixed(2)}%</div>
            <div>Time: ${new Date(ts).toLocaleTimeString()}</div>
          `;
        } else {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
        }

        this.render();
      }

      getPlotRect() {
        return {
          x: this.margin.left,
          y: this.margin.top,
          width: this.width - this.margin.left - this.margin.right,
          height: this.height - this.margin.top - this.margin.bottom
        };
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        this.drawBackground();
        this.drawHeatmap();
        this.drawAxes();
        this.drawHover();
      }

      drawBackground() {
        const ctx = this.ctx;
        const plot = this.getPlotRect();

        ctx.fillStyle = '#0a0f1f';
        ctx.fillRect(0, 0, this.width, this.height);

        ctx.fillStyle = '#10182f';
        ctx.fillRect(plot.x, plot.y, plot.width, plot.height);

        ctx.strokeStyle = '#24345f';
        ctx.strokeRect(plot.x, plot.y, plot.width, plot.height);
      }

      drawHeatmap() {
        const ctx = this.ctx;
        const plot = this.getPlotRect();
        const rows = this.symbols.length;
        const rowHeight = plot.height / rows;

        const visibleCols = this.maxPoints / this.view.scaleX;
        const startCol = this.view.offsetX / (plot.width * this.view.scaleX) * this.maxPoints;
        const endCol = Math.min(this.maxPoints, startCol + visibleCols);
        const colWidth = plot.width / visibleCols;

        ctx.save();
        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        for (let row = 0; row < rows; row++) {
          const y = plot.y + row * rowHeight;

          for (let col = Math.floor(startCol); col < Math.ceil(endCol); col++) {
            const x = plot.x + (col - startCol) * colWidth;
            const value = this.data[row][col];
            ctx.fillStyle = this.valueToColor(value);
            ctx.fillRect(x, y, Math.ceil(colWidth) + 1, Math.ceil(rowHeight) + 1);
          }
        }

        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 1;

        for (let row = 0; row <= rows; row++) {
          const y = plot.y + row * rowHeight;
          ctx.beginPath();
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.width, y);
          ctx.stroke();
        }

        const gridStep = Math.max(1, Math.floor(visibleCols / 8));
        for (let col = Math.floor(startCol); col <= endCol; col += gridStep) {
          const x = plot.x + (col - startCol) * colWidth;
          ctx.beginPath();
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.height);
          ctx.stroke();
        }

        ctx.restore();
      }

      drawAxes() {
        const ctx = this.ctx;
        const plot = this.getPlotRect();
        const rows = this.symbols.length;
        const rowHeight = plot.height / rows;

        ctx.fillStyle = '#dbe4ff';
        ctx.font = '12px sans-serif';
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'right';

        for (let row = 0; row < rows; row++) {
          const y = plot.y + row * rowHeight + rowHeight / 2;
          ctx.fillText(this.symbols[row], plot.x - 10, y);
        }

        const visibleCols = this.maxPoints / this.view.scaleX;
        const startCol = this.view.offsetX / (plot.width * this.view.scaleX) * this.maxPoints;
        const endCol = Math.min(this.maxPoints, startCol + visibleCols);
        const colWidth = plot.width / visibleCols;
        const tickStep = Math.max(1, Math.floor(visibleCols / 6));

        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillStyle = '#8ea0d0';

        for (let col = Math.floor(startCol); col < endCol; col += tickStep) {
          const x = plot.x + (col - startCol) * colWidth;
          const ts = this.timestamps[col];
          if (!ts) continue;
          const label = new Date(ts).toLocaleTimeString([], {
            minute: '2-digit',
            second: '2-digit'
          });
          ctx.fillText(label, x, plot.y + plot.height + 8);
        }

        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = '#8ea0d0';
        ctx.fillText('Stocks', 12, this.margin.top / 2 + 4);

        ctx.textAlign = 'center';
        ctx.fillText('Time', plot.x + plot.width / 2, this.height - 14);
      }

      drawHover() {
        const hover = this.interaction.hoverCell;
        if (!hover) return;

        const plot = this.getPlotRect();
        const rowHeight = plot.height / this.symbols.length;
        const visibleCols = this.maxPoints / this.view.scaleX;
        const colWidth = plot.width / visibleCols;
        const startCol = this.view.offsetX / (plot.width * this.view.scaleX) * this.maxPoints;

        const x = plot.x + (hover.col - startCol) * colWidth;
        const y = plot.y + hover.row * rowHeight;

        if (x + colWidth < plot.x || x > plot.x + plot.width) return;

        const ctx = this.ctx;
        ctx.save();
        ctx.strokeStyle = 'rgba(255,255,255,0.9)';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
        ctx.restore();
      }

      valueToColor(value) {
        const v = this.clamp(value, this.colorRange.min, this.colorRange.max);
        const t = (v - this.colorRange.min) / (this.colorRange.max - this.colorRange.min);

        let r, g, b;
        if (t < 0.5) {
          const k = t / 0.5;
          r = Math.round(180 + (80 - 180) * k);
          g = Math.round(30 + (80 - 30) * k);
          b = Math.round(30 + (80 - 30) * k);
        } else {
          const k = (t - 0.5) / 0.5;
          r = Math.round(80 + (20 - 80) * k);
          g = Math.round(80 + (180 - 80) * k);
          b = Math.round(80 + (80 - 80) * k);
        }

        return `rgb(${r}, ${g}, ${b})`;
      }

      clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      setSymbolCount(count) {
        this.initSymbols(count);
        this.initData();
        this.render();
      }

      setWindowSize(size) {
        this.maxPoints = size;
        this.initData();
        this.render();
      }

      toggleStreaming() {
        this.streaming = !this.streaming;
        this.statusEl.textContent = this.streaming
          ? 'Streaming live data...'
          : 'Stream paused';
      }

      resetView() {
        this.view.offsetX = 0;
        this.view.scaleX = 1;
        this.render();
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const heatmap = new StockHeatmap(canvas, tooltip, statusEl);

    document.getElementById('symbolCount').addEventListener('change', (e) => {
      heatmap.setSymbolCount(Number(e.target.value));
    });

    document.getElementById('windowSize').addEventListener('change', (e) => {
      heatmap.setWindowSize(Number(e.target.value));
    });

    document.getElementById('toggleStream').addEventListener('click', (e) => {
      heatmap.toggleStreaming();
      e.target.textContent = heatmap.streaming ? 'Pause Stream' : 'Resume Stream';
    });

    document.getElementById('resetView').addEventListener('click', () => {
      heatmap.resetView();
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `symbols`: stock rows
- `timestamps`: time columns
- `data[row][col]`: price-change value for a stock at a time point

### Rendering
- The heatmap is drawn on a `<canvas>`
- Each cell is colored based on percent change:
  - red = negative
  - gray = neutral
  - green = positive

### Real-time updates
- `setInterval()` simulates incoming market ticks
- New values are appended and old values are removed once the window is full

### Zoom/pan
- Horizontal zoom only for now
- Mouse wheel changes `scaleX`
- Dragging changes `offsetX`

