<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="meta" id="status">Connecting to mock stream...</div>
      <div class="help">Wheel: zoom • Drag: pan • Hover: inspect</div>
      <div class="legend">
        <span class="meta">-5%</span>
        <div class="legend-bar"></div>
        <span class="meta">+5%</span>
      </div>
    </div>

    <div class="canvas-wrap" id="wrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('wrap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AMD","NFLX","INTC",
      "CRM","ORCL","IBM","UBER","SHOP","SQ","PYPL","BABA","SONY","ADBE",
      "QCOM","AVGO","CSCO","SAP","TXN","MU","PLTR","SNOW","ARM","PANW"
    ];

    const timeBuckets = 120; // columns
    const data = symbols.map(() => Array.from({ length: timeBuckets }, () => 0));

    // View transform
    let scaleX = 1;
    let scaleY = 1;
    let offsetX = 80;
    let offsetY = 30;

    const baseCellWidth = 14;
    const baseCellHeight = 22;
    const headerHeight = 24;
    const labelWidth = 70;

    let isDragging = false;
    let lastMouseX = 0;
    let lastMouseY = 0;
    let hoverCell = null;

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      render();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function colorForChange(value) {
      // value expected roughly in [-5, 5]
      const v = clamp(value, -5, 5);

      if (v < 0) {
        const t = (v + 5) / 5; // -5 => 0, 0 => 1
        const r = Math.round(lerp(127, 55, t));
        const g = Math.round(lerp(29, 65, t));
        const b = Math.round(lerp(29, 81, t));
        return `rgb(${r},${g},${b})`;
      } else {
        const t = v / 5; // 0 => 0, 5 => 1
        const r = Math.round(lerp(55, 20, t));
        const g = Math.round(lerp(65, 83, t));
        const b = Math.round(lerp(81, 45, t));
        return `rgb(${r},${g},${b})`;
      }
    }

    function formatTimeBucket(colIndex) {
      const now = new Date();
      const minutesAgo = timeBuckets - 1 - colIndex;
      const d = new Date(now.getTime() - minutesAgo * 60 * 1000);
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }

    function screenToGrid(x, y) {
      const cellW = baseCellWidth * scaleX;
      const cellH = baseCellHeight * scaleY;

      const gridX = x - offsetX - labelWidth;
      const gridY = y - offsetY - headerHeight;

      const col = Math.floor(gridX / cellW);
      const row = Math.floor(gridY / cellH);

      if (row >= 0 && row < symbols.length && col >= 0 && col < timeBuckets) {
        return { row, col };
      }
      return null;
    }

    function drawHeaders(cellW, cellH) {
      ctx.save();
      ctx.translate(offsetX, offsetY);

      // top-left corner
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, labelWidth, headerHeight);

      // column headers
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(labelWidth, 0, timeBuckets * cellW, headerHeight);

      // row labels
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, headerHeight, labelWidth, symbols.length * cellH);

      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;

      // row labels
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "#cbd5e1";
      for (let r = 0; r < symbols.length; r++) {
        const y = headerHeight + r * cellH;
        ctx.strokeRect(0, y, labelWidth, cellH);
        ctx.fillText(symbols[r], 8, y + cellH / 2);
      }

      // column labels every N columns depending on zoom
      const step = cellW < 20 ? 10 : cellW < 40 ? 5 : 2;
      ctx.textBaseline = "middle";
      for (let c = 0; c < timeBuckets; c++) {
        const x = labelWidth + c * cellW;
        if (c % step === 0) {
          ctx.save();
          ctx.beginPath();
          ctx.rect(x, 0, cellW, headerHeight);
          ctx.clip();
          ctx.strokeRect(x, 0, cellW, headerHeight);
          ctx.fillStyle = "#cbd5e1";
          ctx.fillText(formatTimeBucket(c), x + 4, headerHeight / 2);
          ctx.restore();
        }
      }

      ctx.restore();
    }

    function drawHeatmap(cellW, cellH) {
      ctx.save();
      ctx.translate(offsetX + labelWidth, offsetY + headerHeight);

      const visibleWidth = canvas.clientWidth;
      const visibleHeight = canvas.clientHeight;

      const startCol = Math.max(0, Math.floor((-offsetX) / cellW) - 2);
      const endCol = Math.min(timeBuckets, startCol + Math.ceil(visibleWidth / cellW) + 10);

      const startRow = Math.max(0, Math.floor((-offsetY) / cellH) - 2);
      const endRow = Math.min(symbols.length, startRow + Math.ceil(visibleHeight / cellH) + 10);

      for (let r = startRow; r < endRow; r++) {
        for (let c = startCol; c < endCol; c++) {
          const x = c * cellW;
          const y = r * cellH;
          const value = data[r][c];

          ctx.fillStyle = colorForChange(value);
          ctx.fillRect(x, y, cellW, cellH);

          ctx.strokeStyle = "rgba(15, 23, 42, 0.55)";
          ctx.strokeRect(x, y, cellW, cellH);
        }
      }

      if (hoverCell) {
        const { row, col } = hoverCell;
        ctx.lineWidth = 2;
        ctx.strokeStyle = "#f8fafc";
        ctx.strokeRect(col * cellW + 1, row * cellH + 1, cellW - 2, cellH - 2);
      }

      ctx.restore();
    }

    function render() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      ctx.clearRect(0, 0, w, h);

      const cellW = baseCellWidth * scaleX;
      const cellH = baseCellHeight * scaleY;

      drawHeatmap(cellW, cellH);
      drawHeaders(cellW, cellH);
    }

    function pushNewColumn() {
      for (let r = 0; r < symbols.length; r++) {
        const prev = data[r][data[r].length - 1] || 0;
        const next = clamp(prev + (Math.random() - 0.5) * 1.2, -5, 5);
        data[r].shift();
        data[r].push(Number(next.toFixed(2)));
      }
      statusEl.textContent = "Live mock stream active • Last update: " + new Date().toLocaleTimeString();
      render();
    }

    function showTooltip(clientX, clientY, cell) {
      const value = data[cell.row][cell.col];
      tooltip.style.display = 'block';
      tooltip.style.left = clientX + 'px';
      tooltip.style.top = clientY + 'px';
      tooltip.innerHTML = `
        <div><strong>${symbols[cell.row]}</strong></div>
        <div class="muted">${formatTimeBucket(cell.col)}</div>
        <div>${value > 0 ? '+' : ''}${value.toFixed(2)}%</div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      if (isDragging) {
        offsetX += e.clientX - lastMouseX;
        offsetY += e.clientY - lastMouseY;
        lastMouseX = e.clientX;
        lastMouseY = e.clientY;
        render();
        hideTooltip();
        return;
      }

      const cell = screenToGrid(x, y);
      hoverCell = cell;
      render();

      if (cell) {
        showTooltip(e.clientX - rect.left, e.clientY - rect.top, cell);
      } else {
        hideTooltip();
      }
    });

    canvas.addEventListener('mouseleave', () => {
      hoverCell = null;
      hideTooltip();
      render();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomIntensity = 0.1;
      const delta = -Math.sign(e.deltaY) * zoomIntensity;

      const prevScaleX = scaleX;
      const prevScaleY = scaleY;

      scaleX = clamp(scaleX * (1 + delta), 0.4, 4);
      scaleY = clamp(scaleY * (1 + delta * 0.6), 0.6, 3);

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldX = (mx - offsetX - labelWidth) / (baseCellWidth * prevScaleX);
      const worldY = (my - offsetY - headerHeight) / (baseCellHeight * prevScaleY);

      offsetX = mx - labelWidth - worldX * (baseCellWidth * scaleX);
      offsetY = my - headerHeight - worldY * (baseCellHeight * scaleY);

      render();
    }, { passive: false });

    // Seed initial data
    for (let c = 1; c < timeBuckets; c++) {
      for (let r = 0; r < symbols.length; r++) {
        const prev = data[r][c - 1];
        data[r][c] = clamp(prev + (Math.random() - 0.5) * 1.0, -5, 5);
      }
    }

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    setInterval(pushNewColumn, 1000);
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `data[row][col]` stores percent change for a stock symbol at a time bucket.
- Every second:
  - oldest column is removed
  - a new value is appended for each stock

### Rendering
- The heatmap is drawn on a `<canvas>`.
- Colors map from red to neutral to green based on percent change.

### Interaction
- `wheel` adjusts zoom
- `mousedown + mousemove` pans
- `mousemove` detects hovered cell and shows tooltip

