<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Heatmap</h1>
      <div class="stat" id="status">Streaming: ON</div>
      <div class="stat" id="viewportInfo"></div>
      <button id="resetViewBtn">Reset View</button>
      <button id="toggleStreamBtn">Pause Stream</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, container, tooltip, viewportInfoEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.container = container;
        this.tooltip = tooltip;
        this.viewportInfoEl = viewportInfoEl;

        this.dpr = window.devicePixelRatio || 1;

        this.symbols = [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
          'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'SNOW'
        ];

        this.maxColumns = 600;
        this.data = []; // each column: { time, values: [{symbol, price, changePct}] }

        this.basePrices = new Map();
        this.lastPrices = new Map();

        for (const symbol of this.symbols) {
          const base = 50 + Math.random() * 450;
          this.basePrices.set(symbol, base);
          this.lastPrices.set(symbol, base);
        }

        this.layout = {
          leftPad: 80,
          topPad: 20,
          rightPad: 20,
          bottomPad: 40
        };

        this.view = {
          startCol: 0,
          visibleCols: 80,
          minVisibleCols: 10,
          maxVisibleCols: 200
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          hover: null
        };

        this.resize();
        this.attachEvents();
        this.seedInitialData(120);
        this.render();
      }

      seedInitialData(count) {
        for (let i = 0; i < count; i++) {
          this.pushNextColumn(false);
        }
        this.view.startCol = Math.max(0, this.data.length - this.view.visibleCols);
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(rect.width * this.dpr);
        this.canvas.height = Math.floor(rect.height * this.dpr);
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';

        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const oldVisible = this.view.visibleCols;
          const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
          let nextVisible = Math.round(oldVisible * zoomFactor);

          nextVisible = Math.max(this.view.minVisibleCols, Math.min(this.view.maxVisibleCols, nextVisible));

          const mouse = this.getMousePos(e);
          const plot = this.getPlotRect();
          const relX = Math.max(0, Math.min(1, (mouse.x - plot.x) / plot.w));
          const anchorCol = this.view.startCol + relX * oldVisible;

          this.view.visibleCols = nextVisible;
          this.view.startCol = Math.round(anchorCol - relX * nextVisible);
          this.clampView();

          this.render();
        }, { passive: false });

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
        });

        window.addEventListener('mousemove', (e) => {
          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            this.interaction.lastX = e.clientX;

            const plot = this.getPlotRect();
            const colWidth = plot.w / this.view.visibleCols;
            const deltaCols = dx / colWidth;

            this.view.startCol -= deltaCols;
            this.clampView();
            this.render();
          } else {
            this.updateHover(e);
          }
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
          this.interaction.hover = null;
          this.render();
        });
      }

      getPlotRect() {
        return {
          x: this.layout.leftPad,
          y: this.layout.topPad,
          w: this.width - this.layout.leftPad - this.layout.rightPad,
          h: this.height - this.layout.topPad - this.layout.bottomPad
        };
      }

      clampView() {
        const maxStart = Math.max(0, this.data.length - this.view.visibleCols);
        this.view.startCol = Math.max(0, Math.min(maxStart, this.view.startCol));
      }

      pushNextColumn(render = true) {
        const time = new Date();
        const values = [];

        for (const symbol of this.symbols) {
          const last = this.lastPrices.get(symbol);
          const drift = (Math.random() - 0.5) * 0.02;
          const volatility = 0.003 + Math.random() * 0.01;
          const next = Math.max(1, last * (1 + drift * volatility * 10));
          this.lastPrices.set(symbol, next);

          const base = this.basePrices.get(symbol);
          const changePct = ((next - base) / base) * 100;

          values.push({
            symbol,
            price: next,
            changePct
          });
        }

        this.data.push({ time, values });

        if (this.data.length > this.maxColumns) {
          this.data.shift();
          this.view.startCol = Math.max(0, this.view.startCol - 1);
        }

        const nearRightEdge = this.view.startCol + this.view.visibleCols >= this.data.length - 2;
        if (nearRightEdge) {
          this.view.startCol = Math.max(0, this.data.length - this.view.visibleCols);
        }

        if (render) this.render();
      }

      getColor(changePct) {
        const clamped = Math.max(-5, Math.min(5, changePct));

        if (clamped < 0) {
          const t = (clamped + 5) / 5;
          return this.lerpColor([139, 30, 30], [42, 53, 94], t);
        } else {
          const t = clamped / 5;
          return this.lerpColor([42, 53, 94], [24, 195, 126], t);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      formatTime(date) {
        return date.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        });
      }

      updateHover(e) {
        const mouse = this.getMousePos(e);
        const plot = this.getPlotRect();

        if (
          mouse.x < plot.x || mouse.x > plot.x + plot.w ||
          mouse.y < plot.y || mouse.y > plot.y + plot.h
        ) {
          this.tooltip.style.display = 'none';
          this.interaction.hover = null;
          this.render();
          return;
        }

        const rowHeight = plot.h / this.symbols.length;
        const colWidth = plot.w / this.view.visibleCols;

        const col = Math.floor((mouse.x - plot.x) / colWidth) + Math.floor(this.view.startCol);
        const row = Math.floor((mouse.y - plot.y) / rowHeight);

        if (!this.data[col] || !this.data[col].values[row]) {
          this.tooltip.style.display = 'none';
          this.interaction.hover = null;
          this.render();
          return;
        }

        const point = this.data[col];
        const cell = point.values[row];

        this.interaction.hover = { col, row };

        this.tooltip.style.display = 'block';
        this.tooltip.style.left = mouse.x + 'px';
        this.tooltip.style.top = mouse.y + 'px';
        this.tooltip.innerHTML = `
          <div><strong>${cell.symbol}</strong></div>
          <div>Time: ${this.formatTime(point.time)}</div>
          <div>Price: $${cell.price.toFixed(2)}</div>
          <div>Change: <span style="color:${cell.changePct >= 0 ? '#18c37e' : '#e05252'}">
            ${cell.changePct >= 0 ? '+' : ''}${cell.changePct.toFixed(2)}%
          </span></div>
        `;

        this.render();
      }

      getMousePos(e) {
        const rect = this.canvas.getBoundingClientRect();
        return {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top
        };
      }

      render() {
        if (!this.ctx) return;

        const ctx = this.ctx;
        const { width, height } = this;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#0a0f1f';
        ctx.fillRect(0, 0, width, height);

        const plot = this.getPlotRect();
        const rowHeight = plot.h / this.symbols.length;
        const colWidth = plot.w / this.view.visibleCols;

        this.drawGrid(plot, rowHeight, colWidth);
        this.drawCells(plot, rowHeight, colWidth);
        this.drawAxes(plot, rowHeight, colWidth);
        this.drawHover(plot, rowHeight, colWidth);

        this.viewportInfoEl.textContent =
          `Showing ${Math.floor(this.view.visibleCols)} columns | Start: ${Math.floor(this.view.startCol)} | Total: ${this.data.length}`;
      }

      drawGrid(plot, rowHeight, colWidth) {
        const ctx = this.ctx;
        ctx.strokeStyle = '#1f2a4d';
        ctx.lineWidth = 1;

        ctx.beginPath();

        for (let r = 0; r <= this.symbols.length; r++) {
          const y = plot.y + r * rowHeight;
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.w, y);
        }

        for (let c = 0; c <= this.view.visibleCols; c++) {
          const x = plot.x + c * colWidth;
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.h);
        }

        ctx.stroke();
      }

      drawCells(plot, rowHeight, colWidth) {
        const ctx = this.ctx;
        const start = Math.floor(this.view.startCol);
        const end = Math.min(this.data.length, Math.ceil(this.view.startCol + this.view.visibleCols));

        for (let c = start; c < end; c++) {
          const screenCol = c - this.view.startCol;
          const x = plot.x + screenCol * colWidth;

          const column = this.data[c];
          if (!column) continue;

          for (let r = 0; r < column.values.length; r++) {
            const y = plot.y + r * rowHeight;
            const cell = column.values[r];

            ctx.fillStyle = this.getColor(cell.changePct);
            ctx.fillRect(
              x + 0.5,
              y + 0.5,
              Math.max(0, colWidth - 1),
              Math.max(0, rowHeight - 1)
            );
          }
        }
      }

      drawAxes(plot, rowHeight, colWidth) {
        const ctx = this.ctx;

        ctx.fillStyle = '#8ea0d0';
        ctx.font = '12px Inter, system-ui, sans-serif';
        ctx.textBaseline = 'middle';

        for (let r = 0; r < this.symbols.length; r++) {
          const y = plot.y + r * rowHeight + rowHeight / 2;
          ctx.fillText(this.symbols[r], 10, y);
        }

        ctx.textBaseline = 'top';
        ctx.textAlign = 'center';

        const tickCount = Math.min(8, Math.floor(this.view.visibleCols));
        for (let i = 0; i <= tickCount; i++) {
          const t = i / tickCount;
          const col = Math.floor(this.view.startCol + t * (this.view.visibleCols - 1));
          const x = plot.x + t * plot.w;

          if (this.data[col]) {
            ctx.fillText(this.formatTime(this.data[col].time), x, plot.y + plot.h + 8);
          }
        }

        ctx.textAlign = 'left';
      }

      drawHover(plot, rowHeight, colWidth) {
        const hover = this.interaction.hover;
        if (!hover) return;

        const ctx = this.ctx;
        const x = plot.x + (hover.col - this.view.startCol) * colWidth;
        const y = plot.y + hover.row * rowHeight;

        ctx.save();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, Math.max(0, colWidth - 2), Math.max(0, rowHeight - 2));
        ctx.restore();
      }
    }

    const canvas = document.getElementById('heatmap');
    const chartWrap = document.getElementById('chartWrap');
    const tooltip = document.getElementById('tooltip');
    const viewportInfo = document.getElementById('viewportInfo');
    const statusEl = document.getElementById('status');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');

    const heatmap = new StockHeatmap(canvas, chartWrap, tooltip, viewportInfo);

    let streaming = true;
    let interval = setInterval(() => {
      if (streaming) heatmap.pushNextColumn(true);
    }, 1000);

    resetViewBtn.addEventListener('click', () => {
      heatmap.view.visibleCols = 80;
      heatmap.view.startCol = Math.max(0, heatmap.data.length - heatmap.view.visibleCols);
      heatmap.render();
    });

    toggleStreamBtn.addEventListener('click', () => {
      streaming = !streaming;
      statusEl.textContent = `Streaming: ${streaming ? 'ON' : 'OFF'}`;
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
    });
  </script>
</body>
</html>
```

