      background: linear-gradient(to right, #1e3a8a, #22c55e, #f59e0b, #dc2626);
      border: 1px solid #555;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <div class="legend">
      <span>Low</span>
      <div class="gradient"></div>
      <span>High</span>
    </div>
    <button id="resetBtn">Reset View</button>
  </div>

  <div id="container">
    <canvas id="heatmap"></canvas>
    <div id="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const container = document.getElementById('container');

    const stocks = ['AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA', 'NVDA', 'META', 'NFLX', 'AMD', 'INTC'];
    const timeSteps = 120;

    // Heatmap data: rows = stocks, cols = time
    let data = stocks.map(() =>
      Array.from({ length: timeSteps }, () => 80 + Math.random() * 40)
    );

    let view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0
    };

    let isDragging = false;
    let lastMouse = { x: 0, y: 0 };

    function resizeCanvas() {
      canvas.width = container.clientWidth * devicePixelRatio;
      canvas.height = container.clientHeight * devicePixelRatio;
      canvas.style.width = container.clientWidth + 'px';
      canvas.style.height = container.clientHeight + 'px';
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    function getMinMax() {
      let min = Infinity, max = -Infinity;
      for (const row of data) {
        for (const v of row) {
          if (v < min) min = v;
          if (v > max) max = v;
        }
      }
      return { min, max };
    }

    function colorForValue(value, min, max) {
      const t = (value - min) / (max - min || 1);

      // Simple blue -> green -> orange -> red gradient
      const stops = [
        [30, 58, 138],
        [34, 197, 94],
        [245, 158, 11],
        [220, 38, 38]
      ];

      const scaled = t * (stops.length - 1);
      const i = Math.floor(scaled);
      const f = scaled - i;

      const c1 = stops[Math.min(i, stops.length - 1)];
      const c2 = stops[Math.min(i + 1, stops.length - 1)];

      const r = Math.round(c1[0] + (c2[0] - c1[0]) * f);
      const g = Math.round(c1[1] + (c2[1] - c1[1]) * f);
      const b = Math.round(c1[2] + (c2[2] - c1[2]) * f);

      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const width = container.clientWidth;
      const height = container.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const rows = stocks.length;
      const cols = timeSteps;
      const baseCellW = width / cols;
      const baseCellH = height / rows;

      const cellW = baseCellW * view.scaleX;
      const cellH = baseCellH * view.scaleY;

      const { min, max } = getMinMax();

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * cellW + view.offsetX;
          const y = r * cellH + view.offsetY;

          if (x + cellW < 0 || x > width || y + cellH < 0 || y > height) continue;

          ctx.fillStyle = colorForValue(data[r][c], min, max);
          ctx.fillRect(x, y, cellW, cellH);

          if (cellW > 18 && cellH > 14) {
            ctx.fillStyle = 'rgba(255,255,255,0.8)';
            ctx.font = '10px sans-serif';
            ctx.fillText(data[r][c].toFixed(1), x + 3, y + 12);
          }
        }
      }

      // Row labels
      ctx.fillStyle = '#fff';
      ctx.font = '12px sans-serif';
      for (let r = 0; r < rows; r++) {
        const y = r * cellH + view.offsetY + cellH / 2 + 4;
        if (y >= 0 && y <= height) {
          ctx.fillText(stocks[r], 4, y);
        }
      }
    }

    function screenToCell(mx, my) {
      const width = container.clientWidth;
      const height = container.clientHeight;
      const rows = stocks.length;
      const cols = timeSteps;
      const baseCellW = width / cols;
      const baseCellH = height / rows;
      const cellW = baseCellW * view.scaleX;
      const cellH = baseCellH * view.scaleY;

      const c = Math.floor((mx - view.offsetX) / cellW);
      const r = Math.floor((my - view.offsetY) / cellH);

      if (r >= 0 && r < rows && c >= 0 && c < cols) {
        return { r, c };
      }
      return null;
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (isDragging) {
        const dx = mx - lastMouse.x;
        const dy = my - lastMouse.y;
        view.offsetX += dx;
        view.offsetY += dy;
        lastMouse = { x: mx, y: my };
        draw();
      }

      const cell = screenToCell(mx, my);
      if (cell) {
        const value = data[cell.r][cell.c];
        tooltip.style.display = 'block';
        tooltip.style.left = (mx + 12) + 'px';
        tooltip.style.top = (my + 12) + 'px';
        tooltip.textContent = `${stocks[cell.r]} | t=${cell.c} | $${value.toFixed(2)}`;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('mousedown', (e) => {
      const rect = canvas.getBoundingClientRect();
      isDragging = true;
      lastMouse = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      };
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const prevScaleX = view.scaleX;
      const prevScaleY = view.scaleY;

      view.scaleX = Math.max(0.5, Math.min(8, view.scaleX * zoomFactor));
      view.scaleY = Math.max(0.5, Math.min(8, view.scaleY * zoomFactor));

      // Zoom toward cursor
      view.offsetX = mx - ((mx - view.offsetX) * (view.scaleX / prevScaleX));
      view.offsetY = my - ((my - view.offsetY) * (view.scaleY / prevScaleY));

      draw();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      view = { scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0 };
      draw();
    });

    // Simulate real-time updates
    setInterval(() => {
      for (let r = 0; r < data.length; r++) {
        data[r].shift();
        const last = data[r][data[r].length - 1];
        const next = Math.max(50, Math.min(150, last + (Math.random() - 0.5) * 6));
        data[r].push(next);
      }
      draw();
    }, 500);

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
  </script>
</body>
</html>
