  <script>
    const symbols = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 60; // columns
    let running = true;

    // Initialize synthetic price-change heatmap data
    let z = symbols.map(() =>
      Array.from({ length: timeSteps }, () => (Math.random() - 0.5) * 2)
    );

    let xLabels = Array.from({ length: timeSteps }, (_, i) => i - timeSteps + 1);

    const data = [{
      type: "heatmap",
      z,
      x: xLabels,
      y: symbols,
      colorscale: "RdYlGn",
      zmin: -3,
      zmax: 3,
      hovertemplate: "Stock: %{y}<br>t=%{x}<br>Change: %{z:.2f}%<extra></extra>"
    }];

    const layout = {
      title: "Live Stock Price Change Heatmap",
      paper_bgcolor: "#111",
      plot_bgcolor: "#111",
      font: { color: "#eee" },
      margin: { t: 50, l: 80, r: 20, b: 50 },
      xaxis: {
        title: "Time",
        rangeslider: { visible: false },
        fixedrange: false
      },
      yaxis: {
        title: "Symbol",
        autorange: "reversed",
        fixedrange: false
      }
    };

    const config = {
      responsive: true,
      scrollZoom: true,
      displayModeBar: true
    };

    Plotly.newPlot("chart", data, layout, config);

    function nextValue(prev) {
      // random walk with slight mean reversion
      return Math.max(-3, Math.min(3, prev * 0.7 + (Math.random() - 0.5) * 1.2));
    }

    function updateHeatmap() {
      if (!running) return;

      for (let row = 0; row < z.length; row++) {
        const last = z[row][z[row].length - 1];
        z[row].push(nextValue(last));
        z[row].shift();
      }

      const lastX = xLabels[xLabels.length - 1];
      xLabels.push(lastX + 1);
      xLabels.shift();

      Plotly.react("chart", [{
        ...data[0],
        z,
        x: xLabels
      }], layout, config);
    }

    setInterval(updateHeatmap, 1000);

    document.getElementById("toggle").addEventListener("click", () => {
      running = !running;
      document.getElementById("toggle").textContent = running ? "Pause" : "Resume";
    });
  </script>
