```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
    }

    .container {
      padding: 16px;
    }

    h2 {
      margin: 0 0 12px;
      font-size: 20px;
    }

    svg {
      background: #1a1a1a;
      border: 1px solid #333;
      display: block;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(0,0,0,0.85);
      color: white;
      padding: 6px 8px;
      border-radius: 4px;
      font-size: 12px;
      border: 1px solid #555;
      opacity: 0;
    }

    .axis text {
      fill: #ccc;
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #555;
    }
  </style>
</head>
<body>
  <div class="container">
    <h2>Realtime Stock Price Heatmap</h2>
    <div id="chart"></div>
  </div>
  <div class="tooltip" id="tooltip"></div>

  <script>
    const stocks = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 30;
    const cellSize = 24;
    const margin = { top: 20, right: 20, bottom: 40, left: 70 };
    const width = 1000;
    const height = stocks.length * cellSize + margin.top + margin.bottom;

    let currentStep = 0;
    let data = [];

    // Seed initial data
    for (let t = 0; t < timeSteps; t++) {
      stocks.forEach(stock => {
        data.push({
          stock,
          time: t,
          priceChange: (Math.random() - 0.5) * 4 // -2% to +2%
        });
      });
    }

    const x = d3.scaleBand()
      .domain(d3.range(timeSteps))
      .range([margin.left, width - margin.right])
      .padding(0.05);

    const y = d3.scaleBand()
      .domain(stocks)
      .range([margin.top, height - margin.bottom])
      .padding(0.05);

    const color = d3.scaleSequential()
      .domain([2, -2]) // green positive, red negative
      .interpolator(d3.interpolateRdYlGn);

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    const heatmapGroup = svg.append("g");

    const xAxisGroup = svg.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${height - margin.bottom})`);

    const yAxisGroup = svg.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left},0)`);

    const tooltip = d3.select("#tooltip");

    function render() {
      const cells = heatmapGroup.selectAll("rect")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("x", d => x(d.time))
        .attr("y", d => y(d.stock))
        .attr("width", x.bandwidth())
        .attr("height", y.bandwidth())
        .attr("fill", d => color(d.priceChange))
        .on("mousemove", (event, d) => {
          tooltip
            .style("opacity", 1)
            .style("left", `${event.pageX + 10}px`)
            .style("top", `${event.pageY + 10}px`)
            .html(
              `<strong>${d.stock}</strong><br/>
               Time: ${d.time}<br/>
               Change: ${d.priceChange.toFixed(2)}%`
            );
        })
        .on("mouseleave", () => {
          tooltip.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", d => x(d.time))
        .attr("y", d => y(d.stock))
        .attr("width", x.bandwidth())
        .attr("height", y.bandwidth())
        .attr("fill", d => color(d.priceChange));

      cells.exit().remove();

      xAxisGroup.call(
        d3.axisBottom(x).tickFormat(d => `T${d}`)
      );

      yAxisGroup.call(d3.axisLeft(y));
    }

    function updateData() {
      currentStep++;

      // Shift old columns left
      data = data
        .filter(d => d.time > 0)
        .map(d => ({ ...d, time: d.time - 1 }));

      // Add new rightmost column
      stocks.forEach(stock => {
        data.push({
          stock,
          time: timeSteps - 1,
          priceChange: (Math.random() - 0.5) * 4
        });
      });

      render();
    }

    // Zoom/pan
    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        heatmapGroup.attr("transform", event.transform);
        xAxisGroup.attr("transform", `translate(${event.transform.x},${height - margin.bottom + event.transform.y}) scale(${event.transform.k},1)`);
        yAxisGroup.attr("transform", `translate(${margin.left + event.transform.x},${event.transform.y}) scale(1,${event.transform.k})`);
      });

    svg.call(zoom);

    render();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
```

