    );

    let scale = 1;
    let offsetX = 80;
    let offsetY = 40;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function colorForValue(v) {
      // red -> black -> green
      const clamped = Math.max(-1, Math.min(1, v));
      if (clamped < 0) {
        const t = 1 + clamped;
        return `rgb(${Math.floor(255 * (1 - t))},0,0)`;
      } else {
        const t = clamped;
        return `rgb(0,${Math.floor(255 * t)},0)`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#111";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const cellW = 20 * scale;
      const cellH = 20 * scale;

      ctx.save();
      ctx.translate(offsetX, offsetY);

      // draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(c * cellW, r * cellH, cellW - 1, cellH - 1);
        }
      }

      // row labels
      ctx.fillStyle = "#ccc";
      ctx.font = `${Math.max(10, 12 * scale)}px sans-serif`;
      for (let r = 0; r < rows; r++) {
        ctx.fillText(stocks[r], -70, r * cellH + cellH * 0.7);
      }

      // column labels
      for (let c = 0; c < cols; c += 5) {
        ctx.fillText(`${c}`, c * cellW + 2, -8);
      }

      ctx.restore();
    }

    function updateData() {
      for (let r = 0; r < rows; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        let next = prev + (Math.random() * 0.4 - 0.2);
        next = Math.max(-1, Math.min(1, next));
        data[r].push(next);
      }
      draw();
    }

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale *= zoomFactor;
      scale = Math.max(0.4, Math.min(4, scale));
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    resize();
    setInterval(updateData, 500);
  </script>
</body>
</html>
```

### What this does
- Each row is a stock.
- Each column is a recent time slice.
- Colors represent price movement:
  - red = negative
  - green = positive
  - dark = neutral
- Every 500ms, new simulated values are appended.
- Mouse wheel zooms.
- Dragging pans the heatmap.

