  <div class="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Mouse wheel to zoom, drag to pan</span>
  </div>
  <div class="chart-wrap">
    <svg id="chart"></svg>
  </div>
  <div class="tooltip" id="tooltip"></div>

  <script>
    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 30, right: 20, bottom: 60, left: 70 };
    let width = window.innerWidth - margin.left - margin.right;
    let height = window.innerHeight - 50 - margin.top - margin.bottom;

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g");

    const xAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${height})`);

    const yAxisG = root.append("g")
      .attr("class", "axis");

    const symbols = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 40;

    let times = d3.range(timeSteps).map(i => i);
    let data = [];

    // Initialize data
    for (let y = 0; y < symbols.length; y++) {
      let base = 100 + Math.random() * 100;
      for (let x = 0; x < timeSteps; x++) {
        base += (Math.random() - 0.5) * 4;
        data.push({
          symbol: symbols[y],
          time: x,
          price: +base.toFixed(2)
        });
      }
    }

    const xScale = d3.scaleBand()
      .domain(times)
      .range([0, width])
      .padding(0.02);

    const yScale = d3.scaleBand()
      .domain(symbols)
      .range([0, height])
      .padding(0.02);

    const colorScale = d3.scaleSequential(d3.interpolateRdYlGn);

    function updateColorDomain() {
      const prices = data.map(d => d.price);
      colorScale.domain([d3.min(prices), d3.max(prices)]);
    }

    function render() {
      updateColorDomain();

      const cells = cellsLayer.selectAll("rect")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.price))
          .on("mousemove", (event, d) => {
            tooltip
              .style("display", "block")
              .style("left", `${event.pageX + 10}px`)
              .style("top", `${event.pageY + 10}px`)
              .html(`
                <strong>${d.symbol}</strong><br/>
                Time: ${d.time}<br/>
                Price: $${d.price}
              `);
          })
          .on("mouseleave", () => {
            tooltip.style("display", "none");
          }),
        update => update
          .transition()
          .duration(250)
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.price)),
        exit => exit.remove()
      );

      xAxisG.call(
        d3.axisBottom(xScale)
          .tickValues(times.filter(t => t % 5 === 0))
      );

      yAxisG.call(d3.axisLeft(yScale));
    }

    render();

    // Realtime update simulation
    function tick() {
      times = times.map(t => t + 1);
      xScale.domain(times);

      const nextTime = d3.max(times);

      symbols.forEach(symbol => {
        const prev = data
          .filter(d => d.symbol === symbol)
          .sort((a, b) => a.time - b.time);

        const lastPrice = prev[prev.length - 1].price;
        const newPrice = +(lastPrice + (Math.random() - 0.5) * 5).toFixed(2);

        // remove oldest point for this symbol
        const oldestTime = d3.min(prev, d => d.time);
        data = data.filter(d => !(d.symbol === symbol && d.time === oldestTime));

        // add newest point
        data.push({
          symbol,
          time: nextTime,
          price: newPrice
        });
      });

      render();
    }

    setInterval(tick, 1000);

    // Zoom / pan
    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    // Resize handling
    window.addEventListener("resize", () => {
      width = window.innerWidth - margin.left - margin.right;
      height = window.innerHeight - 50 - margin.top - margin.bottom;

      xScale.range([0, width]);
      yScale.range([0, height]);

      xAxisG.attr("transform", `translate(0,${height})`);

      render();
    });
  </script>
</body>
</html>
