Below is a minimal working example of a **client-side stock price heatmap** with:

- **real-time updates** via simulated streaming data
- **zoom/pan** interactions
- pure **HTML/CSS/JS**
- rendered on a **canvas** for speed

You can save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      font-family: sans-serif;
      background: #111;
      color: #eee;
    }

    .toolbar {
      display: flex;
      gap: 12px;
      align-items: center;
      padding: 10px 14px;
      background: #1b1b1b;
      border-bottom: 1px solid #333;
    }

    .toolbar button {
      background: #2a2a2a;
      color: #eee;
      border: 1px solid #444;
      padding: 6px 10px;
      cursor: pointer;
    }

    .toolbar button:hover {
      background: #3a3a3a;
    }

    .container {
      padding: 12px;
    }

    canvas {
      display: block;
      background: #000;
      border: 1px solid #333;
      cursor: grab;
      max-width: 100%;
    }

    .hint {
      margin-top: 8px;
      color: #aaa;
      font-size: 13px;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetView">Reset View</button>
    <button id="toggleStream">Pause</button>
    <span id="status">Streaming...</span>
  </div>

  <div class="container">
    <canvas id="heatmap" width="1000" height="500"></canvas>
    <div class="hint">
      Mouse wheel = zoom horizontally, drag = pan, live updates every 250ms
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const resetBtn = document.getElementById("resetView");
    const toggleBtn = document.getElementById("toggleStream");
    const statusEl = document.getElementById("status");

    const rows = 20;          // stocks
    const maxCols = 300;      // time history
    const cellW = 12;
    const cellH = 20;

    const stockNames = Array.from({ length: rows }, (_, i) => `STK${String(i + 1).padStart(2, "0")}`);
    const data = Array.from({ length: rows }, () => []);

    // seed initial values
    for (let r = 0; r < rows; r++) {
      let price = 100 + Math.random() * 50;
      for (let c = 0; c < 80; c++) {
        price += (Math.random() - 0.5) * 2;
        data[r].push(price);
      }
    }

    let view = {
      scaleX: 1,
      offsetX: 0
    };

    let dragging = false;
    let lastX = 0;
    let streaming = true;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function getVisibleCols() {
      return canvas.width / (cellW * view.scaleX);
    }

    function getMaxOffsetX() {
      const totalCols = Math.max(...data.map(row => row.length));
      const visibleCols = getVisibleCols();
      return Math.max(0, totalCols - visibleCols);
    }

    function colorForChange(change) {
      // change roughly in [-3, 3]
      const normalized = clamp((change + 3) / 6, 0, 1);
      const r = Math.floor(255 * (1 - normalized));
      const g = Math.floor(255 * normalized);
      return `rgb(${r},${g},60)`;
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#000";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const totalCols = Math.max(...data.map(row => row.length));
      const visibleCols = getVisibleCols();
      const startCol = Math.floor(view.offsetX);
      const endCol = Math.min(totalCols, Math.ceil(startCol + visibleCols));
      const scaledCellW = cellW * view.scaleX;

      // labels area
      const labelWidth = 70;
      ctx.fillStyle = "#111";
      ctx.fillRect(0, 0, labelWidth, canvas.height);

      for (let r = 0; r < rows; r++) {
        const y = r * cellH;

        // stock label
        ctx.fillStyle = "#ddd";
        ctx.font = "12px sans-serif";
        ctx.fillText(stockNames[r], 8, y + 14);

        // row separator
        ctx.strokeStyle = "#222";
        ctx.beginPath();
        ctx.moveTo(0, y + cellH);
        ctx.lineTo(canvas.width, y + cellH);
        ctx.stroke();

        for (let c = startCol; c < endCol; c++) {
          const x = labelWidth + (c - view.offsetX) * scaledCellW;
          const price = data[r][c];
          if (price == null) continue;

          const prev = c > 0 ? data[r][c - 1] : price;
          const change = price - prev;

          ctx.fillStyle = colorForChange(change);
          ctx.fillRect(x, y + 1, scaledCellW - 1, cellH - 2);
        }
      }

      // vertical grid
      ctx.strokeStyle = "#1a1a1a";
      ctx.lineWidth = 1;
      for (let c = startCol; c < endCol; c++) {
        const x = labelWidth + (c - view.offsetX) * scaledCellW;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, rows * cellH);
        ctx.stroke();
      }

      // border around heatmap area
      ctx.strokeStyle = "#444";
      ctx.strokeRect(70, 0, canvas.width - 70, rows * cellH);
    }

    function tick() {
      for (let r = 0; r < rows; r++) {
        const row = data[r];
        const last = row[row.length - 1] ?? (100 + Math.random() * 50);
        const next = last + (Math.random() - 0.5) * 4;
        row.push(next);
        if (row.length > maxCols) row.shift();
      }

      // keep view pinned near right edge if already near it
      const maxOffset = getMaxOffsetX();
      if (view.offsetX > maxOffset - 3) {
        view.offsetX = maxOffset;
      } else {
        view.offsetX = clamp(view.offsetX, 0, maxOffset);
      }

      draw();
    }

    let interval = setInterval(() => {
      if (streaming) tick();
    }, 250);

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const oldScale = view.scaleX;
      const zoomFactor = e.deltaY < 0 ? 1.15 : 0.87;
      const newScale = clamp(oldScale * zoomFactor, 0.5, 6);

      const labelWidth = 70;
      const mouseX = e.offsetX;
      const heatmapX = Math.max(0, mouseX - labelWidth);
      const colUnderMouse = view.offsetX + heatmapX / (cellW * oldScale);

      view.scaleX = newScale;
      view.offsetX = colUnderMouse - heatmapX / (cellW * newScale);
      view.offsetX = clamp(view.offsetX, 0, getMaxOffsetX());

      draw();
    }, { passive: false });

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      lastX = e.clientX;
      canvas.style.cursor = "grabbing";
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      canvas.style.cursor = "grab";
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      const dx = e.clientX - lastX;
      lastX = e.clientX;

      view.offsetX -= dx / (cellW * view.scaleX);
      view.offsetX = clamp(view.offsetX, 0, getMaxOffsetX());
      draw();
    });

    resetBtn.addEventListener("click", () => {
      view.scaleX = 1;
      view.offsetX = getMaxOffsetX();
      draw();
    });

    toggleBtn.addEventListener("click", () => {
      streaming = !streaming;
      toggleBtn.textContent = streaming ? "Pause" : "Resume";
      statusEl.textContent = streaming ? "Streaming..." : "Paused";
    });

    // initial view at right edge
    view.offsetX = getMaxOffsetX();
    draw();
  </script>
</body>
</html>
