      }

      render(currentXScale, currentYScale);
      status.text(`updated: ${new Date().toLocaleTimeString()}`);
    }

    let currentXScale = xScale.copy();
    let currentYScale = yScale.copy();

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        const t = event.transform;

        // zoom/pan x continuously by rescaling point positions
        const x0 = d3.scaleLinear()
          .domain([0, timeSteps])
          .range([0, innerWidth]);

        const zx = t.rescaleX(x0);

        const xPositions = d3.range(timeSteps).map(i => zx(i));
        const nextX = d3.scaleBand()
          .domain(d3.range(timeSteps))
          .range([xPositions[0], xPositions[xPositions.length - 1] + (xPositions[1] - xPositions[0])])
          .padding(0.02);

        // vertical pan/zoom approximation for band scale
        const y0 = d3.scaleLinear()
          .domain([0, stocks.length])
          .range([0, innerHeight]);

        const zy = t.rescaleY(y0);

        const yPositions = d3.range(stocks.length).map(i => zy(i));
        const nextY = d3.scaleBand()
          .domain(stocks)
          .range([yPositions[0], yPositions[yPositions.length - 1] + (yPositions[1] - yPositions[0])])
          .padding(0.02);

        currentXScale = nextX;
        currentYScale = nextY;
        render(currentXScale, currentYScale);
      });

    svg.call(zoom);

    setInterval(updateData, 1000);
  </script>
</body>
</html>
```

