    const width = +svg.attr("width");
    const height = +svg.attr("height");
    const margin = { top: 40, right: 20, bottom: 80, left: 80 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const g = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const heatmapLayer = g.append("g");
    const xAxisG = g.append("g").attr("class", "axis").attr("transform", `translate(0,${innerHeight})`);
    const yAxisG = g.append("g").attr("class", "axis");

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","TSLA",
      "META","NVDA","NFLX","AMD","INTC"
    ];

    const timeSteps = 60; // columns
    const cellWidth = innerWidth / timeSteps;
    const cellHeight = innerHeight / stocks.length;

    // Initial baseline prices
    const baseline = {};
    stocks.forEach(s => baseline[s] = 100 + Math.random() * 200);

    // Heatmap data: one row per stock, one column per time index
    let data = [];
    for (let t = 0; t < timeSteps; t++) {
      stocks.forEach(stock => {
        data.push({
          stock,
          time: t,
          price: baseline[stock],
          change: 0
        });
      });
    }

    const xScale = d3.scaleBand()
      .domain(d3.range(timeSteps))
      .range([0, innerWidth])
      .padding(0.02);

    const yScale = d3.scaleBand()
      .domain(stocks)
      .range([0, innerHeight])
      .padding(0.02);

    const colorScale = d3.scaleSequential()
      .domain([5, -5]) // reversed so red = down, green = up with interpolator below
      .interpolator(d3.interpolateRdYlGn);

    function render(currentXScale = xScale) {
      const cells = heatmapLayer.selectAll("rect")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.join("rect")
        .attr("x", d => currentXScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", currentXScale.bandwidth ? currentXScale.bandwidth() : cellWidth)
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(Math.max(-5, Math.min(5, d.change))))
        .on("mousemove", (event, d) => {
          tooltip
            .style("display", "block")
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY + 10) + "px")
            .html(`
              <div><strong>${d.stock}</strong></div>
              <div>Time: ${d.time}</div>
              <div>Price: $${d.price.toFixed(2)}</div>
              <div>Change: ${d.change.toFixed(2)}%</div>
            `);
        })
        .on("mouseleave", () => {
          tooltip.style("display", "none");
        });

      xAxisG.call(
        d3.axisBottom(currentXScale)
          .tickValues(currentXScale.domain().filter((d, i) => i % 5 === 0))
      );

      yAxisG.call(d3.axisLeft(yScale));
    }

    render();

    // Zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        const zx = event.transform.rescaleX(
          d3.scaleLinear()
            .domain([0, timeSteps])
            .range([0, innerWidth])
        );

        const visibleDomain = d3.range(timeSteps).filter(t => {
          const px = zx(t);
          return px >= -50 && px <= innerWidth + 50;
        });

        const zoomedBand = d3.scaleBand()
          .domain(visibleDomain)
          .range(visibleDomain.length
            ? [zx(visibleDomain[0]), zx(visibleDomain[visibleDomain.length - 1] + 1 || visibleDomain[visibleDomain.length - 1] + 1)]
            : [0, innerWidth]
          )
          .padding(0.02);

        heatmapLayer.selectAll("rect")
          .attr("x", d => zx(d.time))
          .attr("width", Math.max(1, zx(1) - zx(0) - 1));

        xAxisG.call(
          d3.axisBottom(zx)
            .ticks(10)
            .tickFormat(d => Math.floor(d))
        );
      });

    svg.call(zoom);

    // Simulate realtime updates
    function tick() {
      // Shift all time values left
      data.forEach(d => d.time -= 1);
      data = data.filter(d => d.time >= 0);

      // Add a new column at the right
      const newTime = timeSteps - 1;
      stocks.forEach(stock => {
        const prev = data
          .filter(d => d.stock === stock)
          .sort((a, b) => b.time - a.time)[0];

        const prevPrice = prev ? prev.price : baseline[stock];
        const nextPrice = prevPrice * (1 + (Math.random() - 0.5) * 0.02);
        const change = ((nextPrice - baseline[stock]) / baseline[stock]) * 100;

        data.push({
          stock,
          time: newTime,
          price: nextPrice,
          change
        });
      });

      render();
    }

    setInterval(tick, 1000);
  </script>
