      width: 140px;
      height: 12px;
      background: linear-gradient(to right, #8b0000, #222, #006400);
      margin: 6px 0;
      border: 1px solid #444;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetView">Reset View</button>
    <button id="pauseBtn">Pause</button>
    <div class="status" id="status"></div>
  </div>

  <div class="container">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      <div><strong>Price Change</strong></div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>-</span><span>0</span><span>+</span>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");
    const resetBtn = document.getElementById("resetView");
    const pauseBtn = document.getElementById("pauseBtn");

    const ROWS = 30;   // stocks
    const COLS = 120;  // time slices
    const STOCKS = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, "0")}`);

    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => 0)
    );

    let prices = Array.from({ length: ROWS }, () => 100 + Math.random() * 50);

    let paused = false;

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v roughly in [-3, 3]
      const maxAbs = 3;
      const t = clamp(v / maxAbs, -1, 1);

      if (t < 0) {
        const a = Math.abs(t);
        const r = Math.round(30 + a * 109);
        const g = Math.round(34 - a * 20);
        const b = Math.round(34 - a * 20);
        return `rgb(${r},${g},${b})`;
      } else {
        const r = Math.round(34 - t * 20);
        const g = Math.round(34 + t * 105);
        const b = Math.round(34 - t * 20);
        return `rgb(${r},${g},${b})`;
      }
    }

    function simulateTick() {
      for (let r = 0; r < ROWS; r++) {
        const drift = (Math.random() - 0.5) * 0.6;
        prices[r] += drift;
        const pctChange = drift; // simplified signal for heatmap

        data[r].shift();
        data[r].push(pctChange);
      }
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      const cellW = width / COLS;
      const cellH = height / ROWS;

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(c * cellW, r * cellH, cellW + 0.5, cellH + 0.5);
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1 / scale;

      for (let r = 0; r <= ROWS; r++) {
        ctx.beginPath();
        ctx.moveTo(0, r * cellH);
        ctx.lineTo(width, r * cellH);
        ctx.stroke();
      }

      for (let c = 0; c <= COLS; c += 10) {
        ctx.beginPath();
        ctx.moveTo(c * cellW, 0);
        ctx.lineTo(c * cellW, height);
        ctx.stroke();
      }

      // Row labels
      ctx.fillStyle = "#ddd";
      ctx.font = `${12 / scale}px sans-serif`;
      for (let r = 0; r < ROWS; r++) {
        ctx.fillText(STOCKS[r], 4, r * cellH + cellH * 0.7);
      }

      ctx.restore();

      statusEl.textContent =
        `Rows: ${ROWS} | Cols: ${COLS} | Zoom: ${scale.toFixed(2)}x | Pan: (${Math.round(offsetX)}, ${Math.round(offsetY)})`;
    }

    function animate() {
      if (!paused) {
        simulateTick();
      }
      draw();
      requestAnimationFrame(animate);
    }

    // Mouse pan
    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    // Wheel zoom
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 8);

      // Zoom around mouse position
      offsetX = mx - ((mx - offsetX) * newScale) / scale;
      offsetY = my - ((my - offsetY) * newScale) / scale;
      scale = newScale;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
    });

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    animate();
  </script>
</body>
</html>
```

## What this does

- Each **row** is a stock
- Each **column** is a recent time slice
- Colors represent simulated price movement:
  - **green** = positive
  - **red** = negative
  - **dark/neutral** = near zero
- New values stream in continuously by shifting old data left and appending new values
- You can:
  - **drag** to pan
  - **mouse wheel** to zoom
  - **reset** the view
  - **pause/resume** updates

