<body>
  <div class="toolbar">
    <button id="resetView">Reset View</button>
    <span>Wheel = zoom horizontally, drag = pan, live updates every 500ms</span>
  </div>
  <div id="wrap">
    <canvas id="heatmap" width="1200" height="500"></canvas>
  </div>
  <div class="hint">
    Rows = stocks, columns = time, color = price change intensity
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const resetBtn = document.getElementById('resetView');

    const STOCKS = [
      "AAPL","MSFT","GOOG","AMZN","NVDA","META","TSLA","AMD",
      "NFLX","INTC","ORCL","CRM","UBER","SHOP","BABA","IBM"
    ];

    const ROWS = STOCKS.length;
    const MAX_COLS = 240; // total time history
    const CELL_H = canvas.height / ROWS;

    // Heatmap data: each row contains values in [-1, 1]
    const data = Array.from({ length: ROWS }, () =>
      Array.from({ length: MAX_COLS }, () => 0)
    );

    // Seed with random walk-ish values
    for (let r = 0; r < ROWS; r++) {
      let v = (Math.random() - 0.5) * 0.2;
      for (let c = 0; c < MAX_COLS; c++) {
        v += (Math.random() - 0.5) * 0.15;
        v = Math.max(-1, Math.min(1, v));
        data[r][c] = v;
      }
    }

    // View state
    let viewStart = 0;
    let viewCols = 80; // visible columns
    const minViewCols = 10;
    const maxViewCols = MAX_COLS;

    let isDragging = false;
    let dragStartX = 0;
    let dragStartViewStart = 0;

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function valueToColor(v) {
      // Negative = red, positive = green, near zero = dark
      const t = clamp((v + 1) / 2, 0, 1);

      let r, g, b;
      if (v < 0) {
        r = Math.floor(80 + 175 * Math.abs(v));
        g = Math.floor(20 + 40 * (1 - Math.abs(v)));
        b = Math.floor(20 + 40 * (1 - Math.abs(v)));
      } else {
        r = Math.floor(20 + 40 * (1 - v));
        g = Math.floor(80 + 175 * v);
        b = Math.floor(20 + 40 * (1 - v));
      }

      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const cellW = canvas.width / viewCols;

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let i = 0; i < viewCols; i++) {
          const c = Math.floor(viewStart + i);
          if (c < 0 || c >= MAX_COLS) continue;

          ctx.fillStyle = valueToColor(data[r][c]);
          ctx.fillRect(i * cellW, r * CELL_H, Math.ceil(cellW), Math.ceil(CELL_H));
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let r = 0; r <= ROWS; r++) {
        const y = r * CELL_H;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      const verticalLines = 10;
      for (let i = 0; i <= verticalLines; i++) {
        const x = (i / verticalLines) * canvas.width;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }

      // Labels
      ctx.fillStyle = "#fff";
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";

      for (let r = 0; r < ROWS; r++) {
        ctx.fillText(STOCKS[r], 6, r * CELL_H + CELL_H / 2);
      }

      // Border
      ctx.strokeStyle = "#555";
      ctx.strokeRect(0, 0, canvas.width, canvas.height);
    }

    function pushRealtimeData() {
      for (let r = 0; r < ROWS; r++) {
        const prev = data[r][data[r].length - 1];
        let next = prev + (Math.random() - 0.5) * 0.18;
        next = clamp(next, -1, 1);
        data[r].push(next);
        data[r].shift();
      }

      // Auto-follow right edge if already near the end
      const rightEdge = viewStart + viewCols;
      if (rightEdge >= MAX_COLS - 2) {
        viewStart = MAX_COLS - viewCols;
      }

      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
      const mouseRatio = e.offsetX / canvas.width;
      const anchorCol = viewStart + mouseRatio * viewCols;

      let newViewCols = clamp(Math.round(viewCols * zoomFactor), minViewCols, maxViewCols);
      let newViewStart = anchorCol - mouseRatio * newViewCols;
      newViewStart = clamp(newViewStart, 0, MAX_COLS - newViewCols);

      viewCols = newViewCols;
      viewStart = newViewStart;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      dragStartX = e.clientX;
      dragStartViewStart = viewStart;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;

      const dx = e.clientX - dragStartX;
      const colsPerPixel = viewCols / canvas.width;
      viewStart = clamp(dragStartViewStart - dx * colsPerPixel, 0, MAX_COLS - viewCols);
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    resetBtn.addEventListener('click', () => {
      viewStart = MAX_COLS - 80;
      viewCols = 80;
      draw();
    });

    // Initial view near latest data
    viewStart = MAX_COLS - viewCols;
    draw();

    // Simulated realtime updates
    setInterval(pushRealtimeData, 500);
  </script>
</body>
</html>
```

