  </div>

  <div class="container" id="container">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      <div>+ gain</div>
      <div class="legend-bar"></div>
      <div>- loss</div>
    </div>
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const container = document.getElementById("container");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetView");

    const ROWS = 20;   // stocks
    const COLS = 60;   // time slices
    const stockNames = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, "0")}`);

    // Heatmap values in range roughly [-5, 5]
    const data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => (Math.random() - 0.5) * 2)
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    const minScale = 0.5;
    const maxScale = 6;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width * devicePixelRatio;
      canvas.height = rect.height * devicePixelRatio;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    function valueToColor(v) {
      // Clamp to [-5, 5]
      const x = Math.max(-5, Math.min(5, v));
      if (x >= 0) {
        const t = x / 5;
        const r = Math.round(34 * (1 - t));
        const g = Math.round(34 + (179 - 34) * t);
        const b = Math.round(34 * (1 - t));
        return `rgb(${r},${g},${b})`;
      } else {
        const t = Math.abs(x) / 5;
        const r = Math.round(34 + (179 - 34) * t);
        const g = Math.round(34 * (1 - t));
        const b = Math.round(34 * (1 - t));
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      const cellW = 30 * scale;
      const cellH = 24 * scale;

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = offsetX + c * cellW;
          const y = offsetY + r * cellH;

          if (x + cellW < 0 || y + cellH < 0 || x > width || y > height) continue;

          ctx.fillStyle = valueToColor(data[r][c]);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);
        }
      }

      // Labels for visible rows
      ctx.fillStyle = "#ddd";
      ctx.font = `${Math.max(10, 12 * scale)}px sans-serif`;
      for (let r = 0; r < ROWS; r++) {
        const y = offsetY + r * cellH + cellH * 0.65;
        if (y < 0 || y > height) continue;
        ctx.fillText(stockNames[r], 4, y);
      }
    }

    function screenToGrid(mx, my) {
      const cellW = 30 * scale;
      const cellH = 24 * scale;
      const col = Math.floor((mx - offsetX) / cellW);
      const row = Math.floor((my - offsetY) / cellH);
      if (row >= 0 && row < ROWS && col >= 0 && col < COLS) {
        return { row, col };
      }
      return null;
    }

    // Simulated realtime updates
    function tick() {
      for (let r = 0; r < ROWS; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = prev + (Math.random() - 0.5) * 0.8;
        data[r].push(Math.max(-5, Math.min(5, next)));
      }
      draw();
    }

    // Mouse interactions
    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (isDragging) {
        offsetX += e.clientX - lastX;
        offsetY += e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        draw();
      }

      const hit = screenToGrid(mx, my);
      if (hit) {
        const value = data[hit.row][hit.col].toFixed(2);
        tooltip.style.display = "block";
        tooltip.style.left = `${mx + 14}px`;
        tooltip.style.top = `${my + 14}px`;
        tooltip.textContent = `${stockNames[hit.row]} | t=${hit.col} | ${value}%`;
      } else {
        tooltip.style.display = "none";
      }
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = scale;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale = Math.max(minScale, Math.min(maxScale, scale * zoomFactor));

      // Zoom around mouse position
      const wx = (mx - offsetX) / oldScale;
      const wy = (my - offsetY) / oldScale;
      offsetX = mx - wx * scale;
      offsetY = my - wy * scale;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    setInterval(tick, 500);
  </script>
