It simulates stock prices over time and colors cells by percent change.

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
      overflow: hidden;
    }

    #toolbar {
      padding: 10px;
      background: #1b1b1b;
      border-bottom: 1px solid #333;
      display: flex;
      gap: 10px;
      align-items: center;
    }

    button {
      background: #2a2a2a;
      color: #eee;
      border: 1px solid #444;
      padding: 6px 10px;
      cursor: pointer;
    }

    button:hover {
      background: #3a3a3a;
    }

    #chart {
      width: 100vw;
      height: calc(100vh - 50px);
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(0,0,0,0.85);
      color: white;
      padding: 6px 8px;
      border-radius: 4px;
      font-size: 12px;
      border: 1px solid #555;
    }

    .axis text {
      fill: #ccc;
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #555;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <button id="pauseBtn">Pause</button>
    <button id="resetZoomBtn">Reset Zoom</button>
    <span>Realtime Stock Heatmap</span>
  </div>
  <div id="chart"></div>
  <div class="tooltip" id="tooltip" style="display:none;"></div>

  <script>
    const stocks = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 60;
    const cellWidth = 18;
    const cellHeight = 28;
    const margin = { top: 20, right: 20, bottom: 40, left: 70 };

    let paused = false;
    let tick = 0;

    // Initial simulated data
    let data = stocks.map(symbol => {
      let base = 100 + Math.random() * 200;
      let series = [];
      for (let t = 0; t < timeSteps; t++) {
        base *= 1 + (Math.random() - 0.5) * 0.02;
        series.push({
          symbol,
          time: t,
          price: +base.toFixed(2)
        });
      }
      return series;
    });

    function flattenData() {
      return data.flat().map((d, i, arr) => {
        const stockSeries = data.find(s => s[0].symbol === d.symbol);
        const idx = stockSeries.findIndex(x => x.time === d.time);
        const prev = idx > 0 ? stockSeries[idx - 1].price : d.price;
        const change = ((d.price - prev) / prev) * 100;
        return { ...d, change };
      });
    }

    const width = margin.left + margin.right + timeSteps * cellWidth;
    const height = margin.top + margin.bottom + stocks.length * cellHeight;

    const container = d3.select("#chart");
    const svg = container.append("svg")
      .attr("width", "100%")
      .attr("height", "100%")
      .style("background", "#111");

    const root = svg.append("g");
    const plot = root.append("g");

    const x = d3.scaleBand()
      .domain(d3.range(timeSteps))
      .range([margin.left, margin.left + timeSteps * cellWidth]);

    const y = d3.scaleBand()
      .domain(stocks)
      .range([margin.top, margin.top + stocks.length * cellHeight]);

    const color = d3.scaleLinear()
      .domain([-2, 0, 2])
      .range(["#b91c1c", "#1f2937", "#16a34a"])
      .clamp(true);

    const xAxis = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0, ${margin.top + stocks.length * cellHeight})`);

    const yAxis = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left}, 0)`);

    const tooltip = d3.select("#tooltip");

    function render() {
      const flat = flattenData();

      const cells = plot.selectAll("rect")
        .data(flat, d => `${d.symbol}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("x", d => x(d.time))
        .attr("y", d => y(d.symbol))
        .attr("width", x.bandwidth())
        .attr("height", y.bandwidth())
        .attr("stroke", "#222")
        .attr("stroke-width", 1)
        .merge(cells)
        .attr("fill", d => color(d.change))
        .on("mousemove", function(event, d) {
          tooltip
            .style("display", "block")
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY + 10) + "px")
            .html(`
              <strong>${d.symbol}</strong><br>
              T: ${d.time}<br>
              Price: $${d.price}<br>
              Change: ${d.change.toFixed(2)}%
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("display", "none");
        });

      cells.exit().remove();

      xAxis.call(
        d3.axisBottom(x)
          .tickValues(x.domain().filter(d => d % 5 === 0))
          .tickFormat(d => `T${d}`)
      );

      yAxis.call(d3.axisLeft(y));
    }

    function updateData() {
      data = data.map(series => {
        const last = series[series.length - 1];
        const nextPrice = +(last.price * (1 + (Math.random() - 0.5) * 0.03)).toFixed(2);
        const shifted = series.slice(1).map((d, i) => ({
          ...d,
          time: i
        }));
        shifted.push({
          symbol: last.symbol,
          time: timeSteps - 1,
          price: nextPrice
        });
        return shifted;
      });
      tick++;
      render();
    }

    render();

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        root.attr("transform", event.transform);
      });

    svg.call(zoom);

    d3.select("#resetZoomBtn").on("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    d3.select("#pauseBtn").on("click", function() {
      paused = !paused;
      this.textContent = paused ? "Resume" : "Pause";
    });

    setInterval(() => {
      if (!paused) updateData();
    }, 1000);
  </script>
</body>
</html>
