      ctx.font = "12px sans-serif";
      for (let row = 0; row < STOCKS; row++) {
        const y = row * CELL_H + 12;
        ctx.fillText(stockNames[row], -55, y);
      }

      ctx.restore();
    }

    function updateData() {
      for (let row = 0; row < STOCKS; row++) {
        data[row].shift();

        const prev = data[row][data[row].length - 1] || 0;
        const next = Math.max(-1, Math.min(1, prev + (Math.random() - 0.5) * 0.3));
        data[row].push(next);
      }
      draw();
    }

    // Zoom around mouse position
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(minScale, Math.min(maxScale, scale * zoomFactor));

      // Keep mouse point stable during zoom
      const wx = (mx - offsetX) / scale;
      const wy = (my - offsetY) / scale;

      offsetX = mx - wx * newScale;
      offsetY = my - wy * newScale;
      scale = newScale;

      draw();
    }, { passive: false });

    // Pan
    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 60;
      offsetY = 20;
      draw();
    });

    // Initial view
    offsetX = 60;
    offsetY = 20;
    draw();

    // Simulated realtime updates
    setInterval(updateData, UPDATE_MS);
  </script>
</body>
</html>
```

