  </style>
</head>
<body>
  <div class="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Wheel = zoom</span>
    <span>Drag = pan</span>
    <span id="status"></span>
  </div>

  <div class="container">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      Price Change
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between; margin-top:4px;">
        <span>-5%</span><span>0%</span><span>+5%</span>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const statusEl = document.getElementById('status');
    const container = canvas.parentElement;

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","TSLA","NVDA","META","NFLX","AMD","INTC",
      "ORCL","IBM","CRM","UBER","SHOP","BABA","SONY","SAP","ADBE","PYPL"
    ];

    const timeSteps = 120; // columns
    const rows = stocks.length;

    // Heatmap data: rows x columns, values represent % change
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeSteps }, () => (Math.random() - 0.5) * 2)
    );

    let view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0
    };

    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width * devicePixelRatio;
      canvas.height = rect.height * devicePixelRatio;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // Clamp to [-5, 5]
      const x = clamp(v, -5, 5);

      // Simple segmented gradient:
      // blue -> green -> orange -> red
      if (x < -1.5) return interpolateColor([-30,58,138], [34,197,94], (x + 5) / 3.5);
      if (x < 1.5) return interpolateColor([34,197,94], [245,158,11], (x + 1.5) / 3);
      return interpolateColor([245,158,11], [220,38,38], (x - 1.5) / 3.5);
    }

    function interpolateColor(a, b, t) {
      t = clamp(t, 0, 1);
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r},${g},${b2})`;
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const labelWidth = 70;
      const gridX = labelWidth + view.offsetX;
      const gridY = view.offsetY;
      const cellW = (width - labelWidth) / timeSteps * view.scaleX;
      const cellH = (height / rows) * view.scaleY;

      // Background
      ctx.fillStyle = "#0b0f14";
      ctx.fillRect(0, 0, width, height);

      // Draw stock labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";

      for (let r = 0; r < rows; r++) {
        const y = gridY + r * cellH;
        if (y + cellH < 0 || y > height) continue;
        ctx.fillText(stocks[r], 8, y + cellH / 2);
      }

      // Draw heatmap cells
      for (let r = 0; r < rows; r++) {
        const y = gridY + r * cellH;
        if (y + cellH < 0 || y > height) continue;

        for (let c = 0; c < timeSteps; c++) {
          const x = gridX + c * cellW;
          if (x + cellW < labelWidth || x > width) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW + 0.5, cellH + 0.5);
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let r = 0; r <= rows; r++) {
        const y = gridY + r * cellH;
        ctx.beginPath();
        ctx.moveTo(labelWidth, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let c = 0; c <= timeSteps; c += 10) {
        const x = gridX + c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();

        if (x > labelWidth && x < width) {
          ctx.fillStyle = "#aaa";
          ctx.font = "11px sans-serif";
          ctx.fillText(String(c), x + 2, 12);
        }
      }

      statusEl.textContent =
        `zoomX=${view.scaleX.toFixed(2)} zoomY=${view.scaleY.toFixed(2)} ` +
        `pan=(${Math.round(view.offsetX)}, ${Math.round(view.offsetY)})`;
    }

    function updateData() {
      // Shift left and append new simulated values
      for (let r = 0; r < rows; r++) {
        const prev = data[r][data[r].length - 1];
        const next = clamp(prev + (Math.random() - 0.5) * 0.8, -5, 5);
        data[r].shift();
        data[r].push(next);
      }
      draw();
    }

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      view.offsetX += dx;
      view.offsetY += dy;
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

      if (e.shiftKey) {
        view.scaleY = clamp(view.scaleY * zoomFactor, 0.5, 6);
      } else {
        view.scaleX = clamp(view.scaleX * zoomFactor, 0.5, 8);
      }

      draw();
    }, { passive: false });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    draw();

    // Simulated realtime updates every 500ms
    setInterval(updateData, 500);
  </script>
</body>
</html>
