      cursor: grab;
    }
    canvas:active {
      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Realtime Stock Heatmap</strong></div>
    <div>Wheel: zoom | Drag: pan</div>
  </div>
  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');

    const ROWS = 30;   // stocks
    const COLS = 120;  // time slices
    const stocks = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);

    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => (Math.random() - 0.5) * 4)
    );

    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = window.innerWidth * dpr;
      canvas.height = window.innerHeight * dpr;
      canvas.style.width = window.innerWidth + 'px';
      canvas.style.height = window.innerHeight + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function valueToColor(v) {
      // map roughly -5..5 to red->gray->green
      const clamped = Math.max(-5, Math.min(5, v));
      if (clamped >= 0) {
        const t = clamped / 5;
        const r = Math.round(40 * (1 - t));
        const g = Math.round(80 + 175 * t);
        const b = Math.round(40 * (1 - t));
        return `rgb(${r},${g},${b})`;
      } else {
        const t = Math.abs(clamped) / 5;
        const r = Math.round(80 + 175 * t);
        const g = Math.round(40 * (1 - t));
        const b = Math.round(40 * (1 - t));
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = '#111';
      ctx.fillRect(0, 0, w, h);

      const labelWidth = 70;
      const topPad = 20;
      const cellW = 12 * scale;
      const cellH = 18 * scale;

      ctx.save();
      ctx.translate(offsetX + labelWidth, offsetY + topPad);

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = c * cellW;
          const y = r * cellH;

          if (x + cellW < -labelWidth || y + cellH < -topPad || x > w || y > h) continue;

          ctx.fillStyle = valueToColor(data[r][c]);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);
        }
      }
      ctx.restore();

      // Row labels
      ctx.save();
      ctx.translate(offsetX, offsetY + topPad);
      ctx.fillStyle = '#ddd';
      ctx.font = `${Math.max(10, 12 * scale)}px sans-serif`;
      ctx.textBaseline = 'middle';

      for (let r = 0; r < ROWS; r++) {
        const y = r * cellH + cellH / 2;
        if (y < -20 || y > h + 20) continue;
        ctx.fillText(stocks[r], 8, y);
      }
      ctx.restore();

      // Title-ish axis hint
      ctx.fillStyle = '#aaa';
      ctx.font = '12px sans-serif';
      ctx.fillText('Time →', 90, 16);
    }

    function tickData() {
      for (let r = 0; r < ROWS; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = prev + (Math.random() - 0.5) * 1.2;
        data[r].push(Math.max(-5, Math.min(5, next)));
      }
      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(0.5, Math.min(4, scale * zoomFactor));

      // zoom around mouse position
      const wx = (mouseX - offsetX);
      const wy = (mouseY - offsetY);
      offsetX = mouseX - (wx / scale) * newScale;
      offsetY = mouseY - (wy / scale) * newScale;
      scale = newScale;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    window.addEventListener('resize', resize);

    resize();
    setInterval(tickData, 500);
  </script>
</body>
</html>
```

