      Array.from({ length: cols }, () => Math.random() * 2 - 1)
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // Cell base size
    const baseCellW = 20;
    const baseCellH = 40;

    function colorForValue(v) {
      // v in [-1, 1], red = down, green = up
      const clamped = Math.max(-1, Math.min(1, v));
      if (clamped >= 0) {
        const g = Math.floor(80 + clamped * 175);
        return `rgb(30,${g},60)`;
      } else {
        const r = Math.floor(80 + (-clamped) * 175);
        return `rgb(${r},40,40)`;
      }
    }

