          const x = c * cellW;
          const y = r * cellH;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // Draw labels only when zoomed in enough
          if (scale > 1.5 && c === cols - 1) {
            ctx.fillStyle = "#fff";
            ctx.font = "12px sans-serif";
            ctx.fillText(stocks[r], x - 50, y + cellH / 2);
          }
        }
      }

      ctx.restore();

      // Overlay axis labels
      ctx.fillStyle = "#ccc";
      ctx.font = "12px sans-serif";
      ctx.fillText("Stocks vs Time", 10, canvas.height - 10);
    }

    // Simulate real-time updates by shifting left and appending new values
    function tick() {
      for (let r = 0; r < rows; r++) {
        data[r].shift();
        const last = data[r][data[r].length - 1] || 0;
        let next = last + (Math.random() * 0.4 - 0.2);
        next = Math.max(-1, Math.min(1, next));
        data[r].push(next);
      }
      draw();
    }

    setInterval(tick, 500);

    // Zoom interaction
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = 1.1;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      if (e.deltaY < 0) {
        scale *= zoomFactor;
      } else {
        scale /= zoomFactor;
      }

      scale = Math.max(0.5, Math.min(5, scale));

      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      draw();
    }, { passive: false });

    // Pan interaction
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
    });

    resize();
  </script>
</body>
</html>
