  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const resetBtn = document.getElementById('resetView');

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","META","TSLA","NVDA","NFLX","AMD","INTC",
      "ORCL","IBM","CRM","UBER","SHOP","BABA","SONY","SAP","ADBE","QCOM"
    ];

    const timeSteps = 120; // columns
    const rows = stocks.length;

    // Heatmap data: rows x columns
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeSteps }, () => (Math.random() - 0.5) * 4)
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v roughly in [-5, 5]
      const max = 5;
      const n = clamp(v / max, -1, 1);

      if (n >= 0) {
        const g = Math.floor(40 + n * 180);
        const r = Math.floor(30 - n * 20);
        const b = Math.floor(30 - n * 20);
        return `rgb(${r},${g},${b})`;
      } else {
        const x = Math.abs(n);
        const r = Math.floor(40 + x * 180);
        const g = Math.floor(30 - x * 20);
        const b = Math.floor(30 - x * 20);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      const labelWidth = 70;
      const topPad = 20;
      const gridX = labelWidth + offsetX;
      const gridY = topPad + offsetY;

      const cellW = (width - labelWidth) / timeSteps * scale;
      const cellH = (height - topPad - 10) / rows * scale;

      // Background
      ctx.fillStyle = "#0d0d0d";
      ctx.fillRect(0, 0, width, height);

      // Draw heatmap cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeSteps; c++) {
          const x = gridX + c * cellW;
          const y = gridY + r * cellH;

          if (x + cellW < labelWidth || x > width || y + cellH < topPad || y > height) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW, cellH);
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let r = 0; r <= rows; r++) {
        const y = gridY + r * cellH;
        ctx.beginPath();
        ctx.moveTo(labelWidth, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let c = 0; c <= timeSteps; c += 10) {
        const x = gridX + c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, topPad);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      // Stock labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";

      for (let r = 0; r < rows; r++) {
        const y = gridY + r * cellH + cellH / 2;
        if (y < topPad || y > height) continue;
        ctx.fillText(stocks[r], 8, y);
      }

      // Time labels
      ctx.textBaseline = "top";
      for (let c = 0; c < timeSteps; c += 10) {
        const x = gridX + c * cellW;
        if (x < labelWidth || x > width) continue;
        ctx.fillText(`${c}`, x + 2, 2);
      }
    }

    function updateData() {
      for (let r = 0; r < rows; r++) {
        const prev = data[r][data[r].length - 1];
        const next = clamp(prev + (Math.random() - 0.5) * 1.2, -5, 5);
        data[r].shift();
        data[r].push(next);
      }
      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const oldScale = scale;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale = clamp(scale * zoomFactor, 0.5, 5);

      // Zoom around cursor
      offsetX = mouseX - ((mouseX - offsetX) * (scale / oldScale));
      offsetY = mouseY - ((mouseY - offsetY) * (scale / oldScale));

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    setInterval(updateData, 500);
  </script>
