    const resetBtn = document.getElementById("resetView");

    const rows = 30;   // stocks
    const cols = 120;  // time buckets
    const stockNames = Array.from({ length: rows }, (_, i) => `STK${String(i + 1).padStart(2, "0")}`);

    // Heatmap values in range roughly [-1, 1]
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => (Math.random() - 0.5) * 0.4)
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    const minScale = 0.5;
    const maxScale = 8;

    // Layout
    const leftLabelWidth = 80;
    const topLabelHeight = 30;
    const baseCellW = 8;
    const baseCellH = 18;

    // Realtime updates: shift left, append new values
    function tickData() {
      for (let r = 0; r < rows; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        let next = prev + (Math.random() - 0.5) * 0.15;
        next = Math.max(-1, Math.min(1, next));
        data[r].push(next);
      }
    }

    function valueToColor(v) {
      // v in [-1, 1]
      if (v < 0) {
        const t = Math.min(1, Math.abs(v));
        const r = Math.floor(20 * (1 - t) + 30 * t);
        const g = Math.floor(20 * (1 - t) + 80 * t);
        const b = Math.floor(20 * (1 - t) + 220 * t);
        return `rgb(${r},${g},${b})`;
      } else {
        const t = Math.min(1, v);
        const r = Math.floor(20 * (1 - t) + 220 * t);
        const g = Math.floor(20 * (1 - t) + 50 * t);
        const b = Math.floor(20 * (1 - t) + 50 * t);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background
      ctx.fillStyle = "#000";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Header backgrounds
      ctx.fillStyle = "#111";
      ctx.fillRect(0, 0, canvas.width, topLabelHeight);
      ctx.fillRect(0, 0, leftLabelWidth, canvas.height);

      // Heatmap area clip
      ctx.save();
      ctx.beginPath();
      ctx.rect(leftLabelWidth, topLabelHeight, canvas.width - leftLabelWidth, canvas.height - topLabelHeight);
      ctx.clip();

      const cellW = baseCellW * scale;
      const cellH = baseCellH * scale;

      // Draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = leftLabelWidth + offsetX + c * cellW;
          const y = topLabelHeight + offsetY + r * cellH;

          if (x + cellW < leftLabelWidth || x > canvas.width || y + cellH < topLabelHeight || y > canvas.height) {
            continue;
          }

          ctx.fillStyle = valueToColor(data[r][c]);
          ctx.fillRect(x, y, cellW, cellH);

          // Grid lines when zoomed enough
          if (scale > 1.2) {
            ctx.strokeStyle = "rgba(255,255,255,0.08)";
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }
      }

      ctx.restore();

      // Labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";

      // Row labels
      for (let r = 0; r < rows; r++) {
        const y = topLabelHeight + offsetY + r * (baseCellH * scale) + (baseCellH * scale) / 2;
        if (y < topLabelHeight || y > canvas.height) continue;
        ctx.fillText(stockNames[r], 8, y);
      }

      // Column labels
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      const cellW2 = baseCellW * scale;
      for (let c = 0; c < cols; c += Math.max(1, Math.floor(8 / scale))) {
        const x = leftLabelWidth + offsetX + c * cellW2 + cellW2 / 2;
        if (x < leftLabelWidth || x > canvas.width) continue;
        ctx.fillText(String(c), x, topLabelHeight / 2);
      }

      // Borders
      ctx.strokeStyle = "#444";
      ctx.strokeRect(leftLabelWidth, topLabelHeight, canvas.width - leftLabelWidth, canvas.height - topLabelHeight);
      ctx.beginPath();
      ctx.moveTo(leftLabelWidth, 0);
      ctx.lineTo(leftLabelWidth, canvas.height);
      ctx.moveTo(0, topLabelHeight);
      ctx.lineTo(canvas.width, topLabelHeight);
      ctx.stroke();
    }

    // Pan
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.offsetX;
      lastY = e.offsetY;
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    canvas.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      const dx = e.offsetX - lastX;
      const dy = e.offsetY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.offsetX;
      lastY = e.offsetY;
      draw();
    });

    // Zoom centered on mouse
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      const oldScale = scale;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale = Math.max(minScale, Math.min(maxScale, scale * zoomFactor));

      const heatmapX = mouseX - leftLabelWidth;
      const heatmapY = mouseY - topLabelHeight;

      offsetX = heatmapX - ((heatmapX - offsetX) * (scale / oldScale));
      offsetY = heatmapY - ((heatmapY - offsetY) * (scale / oldScale));

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    // Animation loop for realtime updates
    setInterval(() => {
      tickData();
      draw();
    }, 500);

    draw();
  </script>
