        return transform.applyX(xBase(v));
      };
    }

    function render() {
      const zx = rescaledXBand(currentTransform);

      const cells = plot.selectAll("rect.cell")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.join("rect")
        .attr("class", "cell")
        .attr("x", d => zx(d.time))
        .attr("y", d => yBase(d.stock))
        .attr("width", Math.max(1, currentTransform.k * xBase.bandwidth()))
        .attr("height", yBase.bandwidth())
        .attr("fill", d => color(d.value))
        .on("mousemove", (event, d) => {
          tooltip
            .style("display", "block")
            .style("left", (event.clientX + 12) + "px")
            .style("top", (event.clientY + 12) + "px")
            .html(
              `<strong>${d.stock}</strong><br>` +
              `Time: ${d.time}<br>` +
              `Change: ${d.value.toFixed(2)}%`
            );
        })
        .on("mouseleave", () => {
          tooltip.style("display", "none");
        });

      const visibleTicks = d3.range(timeSteps).filter(t => {
        const x = zx(t);
        return x >= -50 && x <= innerWidth + 50;
      });

      const xAxisScale = d3.scalePoint()
        .domain(visibleTicks)
        .range([
          visibleTicks.length ? zx(visibleTicks[0]) + currentTransform.k * xBase.bandwidth() / 2 : 0,
          visibleTicks.length ? zx(visibleTicks[visibleTicks.length - 1]) + currentTransform.k * xBase.bandwidth() / 2 : innerWidth
        ]);

      const xAxis = d3.axisBottom(xAxisScale)
        .tickValues(visibleTicks.filter((_, i) => i % Math.max(1, Math.ceil(visibleTicks.length / 10)) === 0))
        .tickFormat(d => `T${d}`);

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      yAxisG.call(d3.axisLeft(yBase));
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    function tickUpdate() {
      // Shift left by removing oldest time column and adding newest
      currentTick++;

      data = data
        .filter(d => d.time > 0)
        .map(d => ({ ...d, time: d.time - 1 }));

      for (const stock of stocks) {
        data.push({
          stock,
          time: timeSteps - 1,
          value: Math.max(-5, Math.min(5, (Math.random() - 0.5) * 6))
        });
      }

      render();
    }

    render();
    setInterval(tickUpdate, 1000);
  </script>
</body>
</html>
```

## Features included
- Client-side only
- Heatmap grid of stocks vs. time
- Simulated real-time updates every second
- Mouse wheel zoom
- Drag pan
- Tooltip on hover

## Notes
- X-axis zoom/pan is the main interaction.
- Y-axis remains fixed for simplicity.
- Data is simulated, but you can replace `tickUpdate()` with websocket/API updates.

If you want, I can also provide:
1. a React version,
2. a canvas-based version for better performance,
3. or a version wired to real stock data.

Below is a complete starter implementation for a browser-based project management app with:

- Drag-and-drop Kanban boards
- Projects and tasks
- Real-time collaboration via WebSockets
- Browser-based frontend
- Node.js backend
- In-memory storage for simplicity

This is a solid foundation you can extend with:
- authentication
- database persistence
- comments
- due dates
- activity logs
- permissions
- file attachments

