# 5. Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let projects = [];
let selectedProjectId = null;
let editingTaskId = null;

const projectListEl = document.getElementById("projectList");
const boardEl = document.getElementById("board");
const boardTitleEl = document.getElementById("boardTitle");
const addTaskBtn = document.getElementById("addTaskBtn");

const projectNameInput = document.getElementById("projectNameInput");
const createProjectBtn = document.getElementById("createProjectBtn");

const taskModal = document.getElementById("taskModal");
const modalTitle = document.getElementById("modalTitle");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskColumnSelect = document.getElementById("taskColumn");
const saveTaskBtn = document.getElementById("saveTaskBtn");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");

let draggedTaskId = null;
let draggedFromColumnId = null;

function getSelectedProject() {
  return projects.find((p) => p.id === selectedProjectId);
}

function renderProjects() {
  projectListEl.innerHTML = "";

  projects.forEach((project) => {
    const li = document.createElement("li");
    li.textContent = project.name;
    li.className = project.id === selectedProjectId ? "active" : "";
    li.onclick = () => {
      selectedProjectId = project.id;
      renderProjects();
      renderBoard();
    };
    projectListEl.appendChild(li);
  });
}

function renderBoard() {
  const project = getSelectedProject();
  boardEl.innerHTML = "";

  if (!project) {
    boardTitleEl.textContent = "Select a project";
    addTaskBtn.disabled = true;
    return;
  }

  boardTitleEl.textContent = project.name;
  addTaskBtn.disabled = false;

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = project.columns
        .find((c) => c.id === destinationColumnId)
        .taskIds.length;

      await fetch(`${API_URL}/projects/${project.id}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
      });

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description || "")}</p>
        <p><strong>Assignee:</strong> ${escapeHtml(task.assignee || "Unassigned")}</p>
        <div class="task-actions">
          <button data-action="edit">Edit</button>
          <button data-action="delete">Delete</button>
        </div>
      `;

      taskEl.querySelector('[data-action="edit"]').onclick = () => {
        openEditTaskModal(task, column.id);
      };

      taskEl.querySelector('[data-action="delete"]').onclick = async () => {
        await fetch(`${API_URL}/projects/${project.id}/tasks/${task.id}`, {
          method: "DELETE"
        });
      };

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function openAddTaskModal() {
  editingTaskId = null;
  modalTitle.textContent = "Add Task";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskAssigneeInput.value = "";
  taskColumnSelect.value = "todo";
  taskModal.classList.remove("hidden");
}

function openEditTaskModal(task, columnId) {
  editingTaskId = task.id;
  modalTitle.textContent = "Edit Task";
  taskTitleInput.value = task.title || "";
  taskDescriptionInput.value = task.description || "";
  taskAssigneeInput.value = task.assignee || "";
  taskColumnSelect.value = columnId;
  taskModal.classList.remove("hidden");
}

function closeTaskModal() {
  taskModal.classList.add("hidden");
}

async function createProject() {
  const name = projectNameInput.value.trim();
  if (!name) return;

  await fetch(`${API_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  projectNameInput.value = "";
}

async function saveTask() {
  const project = getSelectedProject();
  if (!project) return;

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  if (editingTaskId) {
    await fetch(`${API_URL}/projects/${project.id}/tasks/${editingTaskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee })
    });
  } else {
    await fetch(`${API_URL}/projects/${project.id}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee, columnId })
    });
  }

  closeTaskModal();
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (char) => {
    const map = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;"
    };
    return map[char];
  });
}

function applySocketMessage(message) {
  const { type, payload } = message;

  switch (type) {
    case "INIT_STATE":
      projects = payload;
      if (!selectedProjectId && projects.length > 0) {
        selectedProjectId = projects[0].id;
      }
      break;

    case "PROJECT_CREATED":
      projects.push(payload);
      if (!selectedProjectId) {
        selectedProjectId = payload.id;
      }
      break;

    case "TASK_CREATED": {
      const project = projects.find((p) => p.id === payload.projectId);
      if (!project) break;
      project.tasks[payload.task.id] = payload.task;
      const column = project.columns.find((c) => c.id === payload.columnId);
      if (column) column.taskIds.push(payload.task.id);
      break;
    }

    case "TASK_UPDATED": {
      const project = projects.find((p) => p.id === payload.projectId);
      if (!project) break;
      project.tasks[payload.task.id] = payload.task;
      break;
    }

    case "TASK_DELETED": {
      const project = projects.find((p) => p.id === payload.projectId);
      if (!project) break;
      delete project.tasks[payload.taskId];
      project.columns.forEach((col) => {
        col.taskIds = col.taskIds.filter((id) => id !== payload.taskId);
      });
      break;
    }

    case "TASK_MOVED": {
      const project = projects.find((p) => p.id === payload.projectId);
      if (!project) break;

      const sourceColumn = project.columns.find((c) => c.id === payload.sourceColumnId);
      const destinationColumn = project.columns.find((c) => c.id === payload.destinationColumnId);

      if (!sourceColumn || !destinationColumn) break;

      sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== payload.taskId);
      destinationColumn.taskIds.splice(payload.destinationIndex, 0, payload.taskId);
      break;
    }
  }

  renderProjects();
  renderBoard();
}

function connectWebSocket() {
  const socket = new WebSocket(WS_URL);

  socket.onopen = () => {
    console.log("Connected to WebSocket server");
  };

  socket.onmessage = (event) => {
    const message = JSON.parse(event.data);
    applySocketMessage(message);
  };

  socket.onclose = () => {
    console.log("WebSocket disconnected. Reconnecting...");
    setTimeout(connectWebSocket, 1000);
  };
}

createProjectBtn.onclick = createProject;
addTaskBtn.onclick = openAddTaskModal;
saveTaskBtn.onclick = saveTask;
cancelTaskBtn.onclick = closeTaskModal;

connectWebSocket();
```

