# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
    { id: "inprogress", title: "In Progress", taskIds: ["task-3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Design landing page",
      description: "Create wireframes and final UI mockups",
      assignee: "Alice"
    },
    "task-2": {
      id: "task-2",
      title: "Set up authentication",
      description: "Implement login and registration flow",
      assignee: "Bob"
    },
    "task-3": {
      id: "task-3",
      title: "Create API docs",
      description: "Document REST endpoints for frontend team",
      assignee: "Charlie"
    }
  }
};

function broadcastBoard() {
  io.emit("board:update", boardState);
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", (task) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const newTask = {
      id,
      title: task.title || "Untitled Task",
      description: task.description || "",
      assignee: task.assignee || ""
    };

    boardState.tasks[id] = newTask;
    const targetColumn = boardState.columns.find(c => c.id === (task.columnId || "todo"));
    if (targetColumn) {
      targetColumn.taskIds.push(id);
    }

    broadcastBoard();
  });

  socket.on("task:update", (updatedTask) => {
    if (!updatedTask?.id || !boardState.tasks[updatedTask.id]) return;

    boardState.tasks[updatedTask.id] = {
      ...boardState.tasks[updatedTask.id],
      title: updatedTask.title ?? boardState.tasks[updatedTask.id].title,
      description: updatedTask.description ?? boardState.tasks[updatedTask.id].description,
      assignee: updatedTask.assignee ?? boardState.tasks[updatedTask.id].assignee
    };

    broadcastBoard();
  });

  socket.on("task:delete", (taskId) => {
    if (!boardState.tasks[taskId]) return;

    delete boardState.tasks[taskId];
    boardState.columns.forEach(column => {
      column.taskIds = column.taskIds.filter(id => id !== taskId);
    });

    broadcastBoard();
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
    const targetColumn = boardState.columns.find(c => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn || !boardState.tasks[taskId]) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

    const safeIndex = Math.max(0, Math.min(targetIndex, targetColumn.taskIds.length));
    targetColumn.taskIds.splice(safeIndex, 0, taskId);

    broadcastBoard();
  });

  socket.on("column:create", (title) => {
    const id = `column-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    boardState.columns.push({
      id,
      title: title || "New Column",
      taskIds: []
    });

    broadcastBoard();
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

