# 5. `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const modalEl = document.getElementById("task-modal");
const modalTitleEl = document.getElementById("modal-title");
const taskIdEl = document.getElementById("task-id");
const taskTitleEl = document.getElementById("task-title");
const taskDescriptionEl = document.getElementById("task-description");
const taskAssigneeEl = document.getElementById("task-assignee");
const taskColumnEl = document.getElementById("task-column");
const saveTaskBtn = document.getElementById("save-task-btn");
const deleteTaskBtn = document.getElementById("delete-task-btn");
const cancelTaskBtn = document.getElementById("cancel-task-btn");
const addTaskBtn = document.getElementById("add-task-btn");
const addColumnBtn = document.getElementById("add-column-btn");

socket.on("board:init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";
  populateColumnOptions();

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = column.title;

    headerEl.appendChild(titleEl);
    columnEl.appendChild(headerEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = column.id;
      const targetIndex = getDropIndex(taskListEl, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div>${escapeHtml(task.description || "")}</div>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
      `;

      taskEl.addEventListener("click", () => {
        openTaskModal(task, column.id);
      });

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    const addInlineBtn = document.createElement("button");
    addInlineBtn.className = "add-task-inline";
    addInlineBtn.textContent = "+ Add Task";
    addInlineBtn.addEventListener("click", () => {
      openTaskModal(null, column.id);
    });

    columnEl.appendChild(taskListEl);
    columnEl.appendChild(addInlineBtn);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(container, mouseY) {
  const cards = [...container.querySelectorAll(".task-card:not(.dragging)")];
  let closest = { offset: Number.NEGATIVE_INFINITY, index: cards.length };

  cards.forEach((card, index) => {
    const rect = card.getBoundingClientRect();
    const offset = mouseY - rect.top - rect.height / 2;
    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

function populateColumnOptions() {
  taskColumnEl.innerHTML = "";
  boardState.columns.forEach(column => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnEl.appendChild(option);
  });
}

function openTaskModal(task = null, columnId = "todo") {
  modalEl.classList.remove("hidden");

  if (task) {
    modalTitleEl.textContent = "Edit Task";
    taskIdEl.value = task.id;
    taskTitleEl.value = task.title;
    taskDescriptionEl.value = task.description || "";
    taskAssigneeEl.value = task.assignee || "";
    taskColumnEl.value = columnId;
    deleteTaskBtn.classList.remove("hidden");
  } else {
    modalTitleEl.textContent = "Create Task";
    taskIdEl.value = "";
    taskTitleEl.value = "";
    taskDescriptionEl.value = "";
    taskAssigneeEl.value = "";
    taskColumnEl.value = columnId;
    deleteTaskBtn.classList.add("hidden");
  }
}

function closeTaskModal() {
  modalEl.classList.add("hidden");
}

saveTaskBtn.addEventListener("click", () => {
  const id = taskIdEl.value.trim();
  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const assignee = taskAssigneeEl.value.trim();
  const columnId = taskColumnEl.value;

  if (!title) {
    alert("Task title is required.");
    return;
  }

  if (id) {
    const originalColumn = boardState.columns.find(col => col.taskIds.includes(id));
    if (originalColumn && originalColumn.id !== columnId) {
      socket.emit("task:move", {
        taskId: id,
        sourceColumnId: originalColumn.id,
        targetColumnId: columnId,
        targetIndex: boardState.columns.find(c => c.id === columnId)?.taskIds.length || 0
      });
    }

    socket.emit("task:update", {
      id,
      title,
      description,
      assignee
    });
  } else {
    socket.emit("task:create", {
      title,
      description,
      assignee,
      columnId
    });
  }

  closeTaskModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const id = taskIdEl.value.trim();
  if (!id) return;

  const confirmed = confirm("Delete this task?");
  if (!confirmed) return;

  socket.emit("task:delete", id);
  closeTaskModal();
});

cancelTaskBtn.addEventListener("click", closeTaskModal);

addTaskBtn.addEventListener("click", () => {
  const firstColumnId = boardState?.columns?.[0]?.id || "todo";
  openTaskModal(null, firstColumnId);
});

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Enter column name:");
  if (!title) return;
  socket.emit("column:create", title.trim());
});

modalEl.addEventListener("click", (e) => {
  if (e.target === modalEl) {
    closeTaskModal();
  }
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

