```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory board state
 * Replace with a database in production.
 */
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Design homepage",
      description: "Create wireframes and mockups",
      assignee: "Alice",
      updatedAt: Date.now()
    },
    "task-2": {
      id: "task-2",
      title: "Set up API",
      description: "Initialize backend routes",
      assignee: "Bob",
      updatedAt: Date.now()
    },
    "task-3": {
      id: "task-3",
      title: "Build login page",
      description: "Implement login form UI",
      assignee: "Charlie",
      updatedAt: Date.now()
    }
  },
  columnOrder: ["todo", "doing", "done"]
};

function broadcastBoard() {
  io.emit("board:update", board);
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "", columnId = "todo" } = req.body;

  if (!title || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = `task-${Date.now()}`;
  const task = {
    id,
    title,
    description,
    assignee,
    updatedAt: Date.now()
  };

  board.tasks[id] = task;
  board.columns[columnId].taskIds.push(id);

  broadcastBoard();
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee } = req.body;

  board.tasks[id] = {
    ...existing,
    title: title ?? existing.title,
    description: description ?? existing.description,
    assignee: assignee ?? existing.assignee,
    updatedAt: Date.now()
  };

  broadcastBoard();
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];

  for (const columnId of board.columnOrder) {
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
      taskId => taskId !== id
    );
  }

  broadcastBoard();
  res.json({ success: true });
});

app.put("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  if (
    !board.tasks[taskId] ||
    !board.columns[sourceColumnId] ||
    !board.columns[destinationColumnId]
  ) {
    return res.status(400).json({ error: "Invalid move request" });
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  const destTaskIds =
    sourceColumnId === destinationColumnId
      ? sourceTaskIds
      : [...board.columns[destinationColumnId].taskIds];

  sourceTaskIds.splice(sourceIndex, 1);

  if (sourceColumnId === destinationColumnId) {
    sourceTaskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
  } else {
    destTaskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
    board.columns[destinationColumnId].taskIds = destTaskIds;
  }

  board.tasks[taskId].updatedAt = Date.now();

  broadcastBoard();
  res.json(board);
});

io.on("connection", socket => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", payload => {
    const { title, description = "", assignee = "", columnId = "todo" } = payload;

    if (!title || !board.columns[columnId]) return;

    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    board.tasks[id] = {
      id,
      title,
      description,
      assignee,
      updatedAt: Date.now()
    };
    board.columns[columnId].taskIds.push(id);

    broadcastBoard();
  });

  socket.on("task:update", payload => {
    const { id, title, description, assignee } = payload;
    if (!board.tasks[id]) return;

    board.tasks[id] = {
      ...board.tasks[id],
      title: title ?? board.tasks[id].title,
      description: description ?? board.tasks[id].description,
      assignee: assignee ?? board.tasks[id].assignee,
      updatedAt: Date.now()
    };

    broadcastBoard();
  });

  socket.on("task:delete", ({ id }) => {
    if (!board.tasks[id]) return;

    delete board.tasks[id];
    for (const columnId of board.columnOrder) {
      board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
        taskId => taskId !== id
      );
    }

    broadcastBoard();
  });

  socket.on("task:move", payload => {
    const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    if (
      !board.tasks[taskId] ||
      !board.columns[sourceColumnId] ||
      !board.columns[destinationColumnId]
    ) {
      return;
    }

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    const destTaskIds =
      sourceColumnId === destinationColumnId
        ? sourceTaskIds
        : [...board.columns[destinationColumnId].taskIds];

    sourceTaskIds.splice(sourceIndex, 1);

    if (sourceColumnId === destinationColumnId) {
      sourceTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
    } else {
      destTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
      board.columns[destinationColumnId].taskIds = destTaskIds;
    }

    board.tasks[taskId].updatedAt = Date.now();
    broadcastBoard();
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
