# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;
let draggedFromIndex = null;

const boardEl = document.getElementById("board");
const modalEl = document.getElementById("taskModal");
const modalTitleEl = document.getElementById("modalTitle");
const taskForm = document.getElementById("taskForm");
const taskIdEl = document.getElementById("taskId");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskAssigneeEl = document.getElementById("taskAssignee");
const taskColumnEl = document.getElementById("taskColumn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");
const openCreateModalBtn = document.getElementById("openCreateModalBtn");
const closeModalBtn = document.getElementById("closeModalBtn");
const connectionStatusEl = document.getElementById("connectionStatus");

function openModal(task = null, columnId = "todo") {
  modalEl.classList.remove("hidden");

  if (task) {
    modalTitleEl.textContent = "Edit Task";
    taskIdEl.value = task.id;
    taskTitleEl.value = task.title;
    taskDescriptionEl.value = task.description || "";
    taskAssigneeEl.value = task.assignee || "";
    taskColumnEl.value = findTaskColumn(task.id);
    deleteTaskBtn.classList.remove("hidden");
  } else {
    modalTitleEl.textContent = "Create Task";
    taskIdEl.value = "";
    taskTitleEl.value = "";
    taskDescriptionEl.value = "";
    taskAssigneeEl.value = "";
    taskColumnEl.value = columnId;
    deleteTaskBtn.classList.add("hidden");
  }
}

function closeModal() {
  modalEl.classList.add("hidden");
  taskForm.reset();
  taskIdEl.value = "";
}

function findTaskColumn(taskId) {
  for (const columnId of boardState.columnOrder) {
    if (boardState.columns[columnId].taskIds.includes(taskId)) {
      return columnId;
    }
  }
  return "todo";
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columnOrder.forEach(columnId => {
    const column = boardState.columns[columnId];

    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+";
    addBtn.className = "add-task-inline";
    addBtn.addEventListener("click", () => openModal(null, column.id));

    const headerWrap = document.createElement("div");
    headerWrap.style.display = "flex";
    headerWrap.style.justifyContent = "space-between";
    headerWrap.style.alignItems = "center";
    headerWrap.appendChild(titleEl);
    headerWrap.appendChild(addBtn);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", e => {
      e.preventDefault();

      if (!draggedTaskId || draggedFromColumnId == null || draggedFromIndex == null) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId,
        sourceIndex: draggedFromIndex,
        destinationIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
      draggedFromIndex = null;
    });

    column.taskIds.forEach((taskId, index) => {
      const task = boardState.tasks[taskId];
      const cardEl = document.createElement("div");
      cardEl.className = "task-card";
      cardEl.draggable = true;
      cardEl.dataset.taskId = task.id;
      cardEl.dataset.index = index;

      cardEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-meta">
          <div><strong>Assignee:</strong> ${escapeHtml(task.assignee || "Unassigned")}</div>
          <div><strong>Updated:</strong> ${new Date(task.updatedAt).toLocaleString()}</div>
        </div>
      `;

      cardEl.addEventListener("click", () => openModal(task));

      cardEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        draggedFromIndex = index;
        cardEl.classList.add("dragging");
      });

      cardEl.addEventListener("dragend", () => {
        cardEl.classList.remove("dragging");
      });

      taskListEl.appendChild(cardEl);
    });

    columnEl.appendChild(headerWrap);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(container, mouseY) {
  const cards = [...container.querySelectorAll(".task-card:not(.dragging)")];

  for (let i = 0; i < cards.length; i++) {
    const rect = cards[i].getBoundingClientRect();
    const midpoint = rect.top + rect.height / 2;
    if (mouseY < midpoint) {
      return i;
    }
  }

  return cards.length;
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

taskForm.addEventListener("submit", e => {
  e.preventDefault();

  const id = taskIdEl.value.trim();
  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const assignee = taskAssigneeEl.value.trim();
  const selectedColumnId = taskColumnEl.value;

  if (!title) return;

  if (id) {
    const currentColumnId = findTaskColumn(id);

    socket.emit("task:update", {
      id,
      title,
      description,
      assignee
    });

    if (currentColumnId !== selectedColumnId) {
      const sourceIndex = boardState.columns[currentColumnId].taskIds.indexOf(id);
      const destinationIndex = boardState.columns[selectedColumnId].taskIds.length;

      socket.emit("task:move", {
        taskId: id,
        sourceColumnId: currentColumnId,
        destinationColumnId: selectedColumnId,
        sourceIndex,
        destinationIndex
      });
    }
  } else {
    socket.emit("task:create", {
      title,
      description,
      assignee,
      columnId: selectedColumnId
    });
  }

  closeModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const id = taskIdEl.value;
  if (!id) return;

  socket.emit("task:delete", { id });
  closeModal();
});

openCreateModalBtn.addEventListener("click", () => openModal());
closeModalBtn.addEventListener("click", closeModal);

modalEl.addEventListener("click", e => {
  if (e.target === modalEl) {
    closeModal();
  }
});

socket.on("connect", () => {
  connectionStatusEl.textContent = "Connected";
  connectionStatusEl.className = "status connected";
});

socket.on("disconnect", () => {
  connectionStatusEl.textContent = "Disconnected";
  connectionStatusEl.className = "status disconnected";
});

socket.on("board:update", updatedBoard => {
  boardState = updatedBoard;
  renderBoard();
});

fetchBoard();
```

