# 2. Backend: `server/server.js`

```js
const express = require("express");
const cors = require("cors");
const http = require("http");
const { WebSocketServer } = require("ws");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

const PORT = 4000;

/**
 * In-memory data store
 * Replace with a real DB in production.
 */
let state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "todo",
          title: "To Do",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "inprogress",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "done",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes",
          assignee: "Alice",
          updatedAt: Date.now()
        },
        "task-2": {
          id: "task-2",
          title: "Define color palette",
          description: "Choose brand colors",
          assignee: "Bob",
          updatedAt: Date.now()
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement responsive landing page",
          assignee: "Charlie",
          updatedAt: Date.now()
        }
      }
    }
  ]
};

function broadcast(message, except = null) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client !== except && client.readyState === 1) {
      client.send(data);
    }
  });
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: `project-${Date.now()}`,
    name,
    columns: [
      { id: "todo", title: "To Do", taskIds: [] },
      { id: "inprogress", title: "In Progress", taskIds: [] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {}
  };

  state.projects.push(project);
  broadcast({ type: "PROJECT_CREATED", payload: project });
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const { projectId } = req.params;
  const { title, description, assignee, columnId = "todo" } = req.body;

  const project = state.projects.find((p) => p.id === projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const taskId = `task-${Date.now()}`;
  const task = {
    id: taskId,
    title,
    description,
    assignee,
    updatedAt: Date.now()
  };

  project.tasks[taskId] = task;
  const column = project.columns.find((c) => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Column not found" });

  column.taskIds.push(taskId);

  broadcast({
    type: "TASK_CREATED",
    payload: { projectId, task, columnId }
  });

  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const { title, description, assignee } = req.body;

  const project = state.projects.find((p) => p.id === projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  project.tasks[taskId] = {
    ...project.tasks[taskId],
    title,
    description,
    assignee,
    updatedAt: Date.now()
  };

  broadcast({
    type: "TASK_UPDATED",
    payload: { projectId, task: project.tasks[taskId] }
  });

  res.json(project.tasks[taskId]);
});

app.post("/api/projects/:projectId/move-task", (req, res) => {
  const { projectId } = req.params;
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const project = state.projects.find((p) => p.id === projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  if (project.tasks[taskId]) {
    project.tasks[taskId].updatedAt = Date.now();
  }

  broadcast({
    type: "TASK_MOVED",
    payload: {
      projectId,
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    }
  });

  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "INIT_STATE", payload: state.projects }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }

      if (data.type === "PRESENCE_UPDATE") {
        broadcast(
          {
            type: "PRESENCE_UPDATE",
            payload: data.payload
          },
          ws
        );
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
