# 5. Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let projects = [];
let selectedProjectId = null;
let socket = null;
let currentUser = `User-${Math.floor(Math.random() * 1000)}`;
let presence = {};

const projectListEl = document.getElementById("projectList");
const boardEl = document.getElementById("board");
const boardTitleEl = document.getElementById("boardTitle");
const createProjectBtn = document.getElementById("createProjectBtn");
const projectNameInput = document.getElementById("projectNameInput");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleInput = document.getElementById("taskTitle");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskDescriptionInput = document.getElementById("taskDescription");
const presenceBarEl = document.getElementById("presenceBar");

async function fetchProjects() {
  const res = await fetch(`${API_URL}/projects`);
  projects = await res.json();

  if (!selectedProjectId && projects.length > 0) {
    selectedProjectId = projects[0].id;
  }

  renderProjects();
  renderBoard();
}

function connectWebSocket() {
  socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    sendPresence();
  });

  socket.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case "INIT_STATE":
        projects = message.payload;
        if (!selectedProjectId && projects.length > 0) {
          selectedProjectId = projects[0].id;
        }
        renderProjects();
        renderBoard();
        break;

      case "PROJECT_CREATED":
        projects.push(message.payload);
        renderProjects();
        renderBoard();
        break;

      case "TASK_CREATED": {
        const { projectId, task, columnId } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) return;
        project.tasks[task.id] = task;
        const column = project.columns.find((c) => c.id === columnId);
        column.taskIds.push(task.id);
        renderBoard();
        break;
      }

      case "TASK_UPDATED": {
        const { projectId, task } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) return;
        project.tasks[task.id] = task;
        renderBoard();
        break;
      }

      case "TASK_MOVED": {
        const { projectId, taskId, sourceColumnId, destinationColumnId, destinationIndex } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) return;

        const source = project.columns.find((c) => c.id === sourceColumnId);
        const dest = project.columns.find((c) => c.id === destinationColumnId);

        source.taskIds = source.taskIds.filter((id) => id !== taskId);
        dest.taskIds.splice(destinationIndex, 0, taskId);

        renderBoard();
        break;
      }

      case "PRESENCE_UPDATE":
        presence[message.payload.user] = message.payload.projectId;
        renderPresence();
        break;
    }
  });

  socket.addEventListener("close", () => {
    setTimeout(connectWebSocket, 2000);
  });
}

function sendPresence() {
  if (socket && socket.readyState === WebSocket.OPEN) {
    socket.send(
      JSON.stringify({
        type: "PRESENCE_UPDATE",
        payload: {
          user: currentUser,
          projectId: selectedProjectId
        }
      })
    );
  }
}

function getSelectedProject() {
  return projects.find((p) => p.id === selectedProjectId);
}

function renderProjects() {
  projectListEl.innerHTML = "";

  projects.forEach((project) => {
    const li = document.createElement("li");
    li.textContent = project.name;
    if (project.id === selectedProjectId) li.classList.add("active");

    li.addEventListener("click", () => {
      selectedProjectId = project.id;
      renderProjects();
      renderBoard();
      sendPresence();
    });

    projectListEl.appendChild(li);
  });
}

function renderPresence() {
  const usersInProject = Object.entries(presence)
    .filter(([, projectId]) => projectId === selectedProjectId)
    .map(([user]) => user);

  presenceBarEl.textContent = usersInProject.length
    ? `Viewing this project: ${usersInProject.join(", ")}`
    : "No collaborators currently visible";
}

function renderBoard() {
  const project = getSelectedProject();
  boardEl.innerHTML = "";

  if (!project) {
    boardTitleEl.textContent = "Select a project";
    renderPresence();
    return;
  }

  boardTitleEl.textContent = project.name;

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    column.taskIds.forEach((taskId, index) => {
      const task = project.tasks[taskId];
      const dropZoneBefore = createDropZone(column.id, index);
      taskListEl.appendChild(dropZoneBefore);

      const taskEl = createTaskCard(task, column.id);
      taskListEl.appendChild(taskEl);
    });

    const dropZoneEnd = createDropZone(column.id, column.taskIds.length);
    taskListEl.appendChild(dropZoneEnd);

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });

  renderPresence();
}

function createTaskCard(task, columnId) {
  const taskEl = document.createElement("div");
  taskEl.className = "task-card";
  taskEl.draggable = true;
  taskEl.dataset.taskId = task.id;
  taskEl.dataset.columnId = columnId;

  taskEl.innerHTML = `
    <h4>${escapeHtml(task.title)}</h4>
    <div>${escapeHtml(task.description || "")}</div>
    <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
  `;

  taskEl.addEventListener("dragstart", (e) => {
    taskEl.classList.add("dragging");
    e.dataTransfer.setData(
      "application/json",
      JSON.stringify({
        taskId: task.id,
        sourceColumnId: columnId
      })
    );
  });

  taskEl.addEventListener("dragend", () => {
    taskEl.classList.remove("dragging");
    document.querySelectorAll(".drop-zone").forEach((z) => z.classList.remove("active"));
  });

  taskEl.addEventListener("dblclick", async () => {
    const newTitle = prompt("Edit task title", task.title);
    if (newTitle === null) return;

    const newDescription = prompt("Edit description", task.description || "");
    if (newDescription === null) return;

    const newAssignee = prompt("Edit assignee", task.assignee || "");
    if (newAssignee === null) return;

    await fetch(`${API_URL}/projects/${selectedProjectId}/tasks/${task.id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTitle,
        description: newDescription,
        assignee: newAssignee
      })
    });
  });

  return taskEl;
}

function createDropZone(columnId, index) {
  const zone = document.createElement("div");
  zone.className = "drop-zone";
  zone.dataset.columnId = columnId;
  zone.dataset.index = index;

  zone.addEventListener("dragover", (e) => {
    e.preventDefault();
    zone.classList.add("active");
  });

  zone.addEventListener("dragleave", () => {
    zone.classList.remove("active");
  });

  zone.addEventListener("drop", async (e) => {
    e.preventDefault();
    zone.classList.remove("active");

    const data = JSON.parse(e.dataTransfer.getData("application/json"));
    const { taskId, sourceColumnId } = data;
    const destinationColumnId = columnId;
    const destinationIndex = Number(index);

    if (!selectedProjectId) return;

    await fetch(`${API_URL}/projects/${selectedProjectId}/move-task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex
      })
    });
  });

  return zone;
}

createProjectBtn.addEventListener("click", async () => {
  const name = projectNameInput.value.trim();
  if (!name) return;

  const res = await fetch(`${API_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  selectedProjectId = project.id;
  projectNameInput.value = "";
  renderProjects();
  renderBoard();
  sendPresence();
});

addTaskBtn.addEventListener("click", async () => {
  if (!selectedProjectId) return;

  const title = taskTitleInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const description = taskDescriptionInput.value.trim();

  if (!title) return;

  await fetch(`${API_URL}/projects/${selectedProjectId}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title,
      assignee,
      description,
      columnId: "todo"
    })
  });

  taskTitleInput.value = "";
  taskAssigneeInput.value = "";
  taskDescriptionInput.value = "";
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchProjects();
connectWebSocket();
```

