# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const { v4: uuidv4 } = require("uuid");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = boardState.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  const task = {
    id: uuidv4(),
    title,
    description,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  boardState.tasks[task.id] = task;
  column.taskIds.push(task.id);

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks[id];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description } = req.body;

  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;
  task.updatedAt = new Date().toISOString();

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete boardState.tasks[id];
  boardState.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((taskId) => taskId !== id);
  });

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json({ success: true });
});

app.put("/api/board/move", (req, res) => {
  const {
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex
  } = req.body;

  const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(
    (c) => c.id === destinationColumnId
  );

  if (!boardState.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column id" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  if (
    typeof destinationIndex !== "number" ||
    destinationIndex < 0 ||
    destinationIndex > destinationColumn.taskIds.length
  ) {
    destinationColumn.taskIds.push(taskId);
  } else {
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
  }

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json({ success: true, board: boardState });
});

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "BOARD_UPDATED",
      payload: boardState
    })
  );

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

