# 5. `public/app.js`

```js
let boardState = { columns: [], tasks: {} };
let currentEditTaskId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;
let socket = null;

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskColumnEl = document.getElementById("taskColumn");
const connectionStatusEl = document.getElementById("connectionStatus");

const editModal = document.getElementById("editModal");
const editTitleEl = document.getElementById("editTitle");
const editDescriptionEl = document.getElementById("editDescription");
const saveTaskBtn = document.getElementById("saveTaskBtn");
const cancelEditBtn = document.getElementById("cancelEditBtn");

async function fetchBoard() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  socket = new WebSocket(`${protocol}//${window.location.host}`);

  socket.addEventListener("open", () => {
    connectionStatusEl.textContent = "Connected";
  });

  socket.addEventListener("close", () => {
    connectionStatusEl.textContent = "Disconnected - retrying...";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("message", (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATED") {
      boardState = data.payload;
      renderBoard();
    }
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = column.id;
      const destinationIndex = column.taskIds.length;

      await fetch("/api/board/move", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const taskTitle = document.createElement("h3");
      taskTitle.textContent = task.title;

      const taskDescription = document.createElement("p");
      taskDescription.textContent = task.description || "";

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.className = "edit-btn";
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditModal(task.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => deleteTask(task.id));

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      taskEl.appendChild(taskTitle);
      taskEl.appendChild(taskDescription);
      taskEl.appendChild(actions);

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const columnId = taskColumnEl.value;

  if (!title) return;

  await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, columnId })
  });

  taskForm.reset();
});

async function deleteTask(taskId) {
  await fetch(`/api/tasks/${taskId}`, {
    method: "DELETE"
  });
}

function openEditModal(taskId) {
  const task = boardState.tasks[taskId];
  if (!task) return;

  currentEditTaskId = taskId;
  editTitleEl.value = task.title;
  editDescriptionEl.value = task.description || "";
  editModal.classList.remove("hidden");
}

saveTaskBtn.addEventListener("click", async () => {
  if (!currentEditTaskId) return;

  await fetch(`/api/tasks/${currentEditTaskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title: editTitleEl.value.trim(),
      description: editDescriptionEl.value.trim()
    })
  });

  closeEditModal();
});

cancelEditBtn.addEventListener("click", closeEditModal);

function closeEditModal() {
  currentEditTaskId = null;
  editModal.classList.add("hidden");
}

window.addEventListener("click", (e) => {
  if (e.target === editModal) {
    closeEditModal();
  }
});

fetchBoard();
connectWebSocket();
```

