# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory data store
 * Replace with DB in production
 */
const state = {
  boards: [
    {
      id: "board-1",
      name: "Website Redesign",
      columns: [
        {
          id: "col-1",
          title: "Backlog",
          taskIds: []
        },
        {
          id: "col-2",
          title: "In Progress",
          taskIds: []
        },
        {
          id: "col-3",
          title: "Review",
          taskIds: []
        },
        {
          id: "col-4",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {}
    }
  ]
};

// Seed sample tasks
(function seed() {
  const board = state.boards[0];
  const tasks = [
    { title: "Create wireframes", description: "Design homepage wireframes" },
    { title: "Set up landing page", description: "Build initial landing page" },
    { title: "Review typography", description: "Choose font pairings" }
  ];

  tasks.forEach((task, i) => {
    const id = uuidv4();
    board.tasks[id] = {
      id,
      title: task.title,
      description: task.description,
      assignee: "",
      createdAt: Date.now()
    };
    board.columns[i === 0 ? 0 : i === 1 ? 1 : 2].taskIds.push(id);
  });
})();

function getBoard(boardId) {
  return state.boards.find((b) => b.id === boardId);
}

app.get("/api/boards", (req, res) => {
  res.json(state.boards);
});

app.get("/api/boards/:boardId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards", (req, res) => {
  const { name } = req.body;
  const board = {
    id: uuidv4(),
    name: name || "Untitled Board",
    columns: [
      { id: uuidv4(), title: "Backlog", taskIds: [] },
      { id: uuidv4(), title: "In Progress", taskIds: [] },
      { id: uuidv4(), title: "Review", taskIds: [] },
      { id: uuidv4(), title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  state.boards.push(board);
  io.emit("board:created", board);
  res.status(201).json(board);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { title, description, assignee, columnId } = req.body;
  if (!title) return res.status(400).json({ error: "Title is required" });

  const taskId = uuidv4();
  const task = {
    id: taskId,
    title,
    description: description || "",
    assignee: assignee || "",
    createdAt: Date.now()
  };

  board.tasks[taskId] = task;

  const targetColumn =
    board.columns.find((c) => c.id === columnId) || board.columns[0];
  targetColumn.taskIds.push(taskId);

  io.to(board.id).emit("task:created", { boardId: board.id, task, columnId: targetColumn.id });
  res.status(201).json(task);
});

app.put("/api/boards/:boardId/tasks/:taskId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const task = board.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, assignee } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (assignee !== undefined) task.assignee = assignee;

  io.to(board.id).emit("task:updated", { boardId: board.id, task });
  res.json(task);
});

app.delete("/api/boards/:boardId/tasks/:taskId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const taskId = req.params.taskId;
  if (!board.tasks[taskId]) return res.status(404).json({ error: "Task not found" });

  delete board.tasks[taskId];
  board.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  io.to(board.id).emit("task:deleted", { boardId: board.id, taskId });
  res.json({ success: true });
});

app.put("/api/boards/:boardId/reorder", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceCol = board.columns.find((c) => c.id === sourceColumnId);
  const destCol = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceCol || !destCol) {
    return res.status(400).json({ error: "Invalid column IDs" });
  }

  const [movedTaskId] = sourceCol.taskIds.splice(sourceIndex, 1);
  if (!movedTaskId) {
    return res.status(400).json({ error: "Invalid source index" });
  }

  destCol.taskIds.splice(destinationIndex, 0, movedTaskId);

  io.to(board.id).emit("task:moved", {
    boardId: board.id,
    sourceColumnId,
    destinationColumnId,
    sourceIndex,
    destinationIndex,
    taskId: movedTaskId
  });

  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("board:join", (boardId) => {
    socket.join(boardId);
    console.log(`Socket ${socket.id} joined board ${boardId}`);
  });

  socket.on("presence:update", ({ boardId, user }) => {
    socket.to(boardId).emit("presence:update", user);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

