function renderBoard() {
  boardContainer.innerHTML = "";

  board.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h3");
    title.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";

    column.taskIds.forEach((taskId, index) => {
      const task = board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
      `;

      taskEl.addEventListener("click", () => openEditTaskModal(task.id, column.id));
      taskEl.addEventListener("dragstart", onDragStart);
      taskEl.addEventListener("dragend", onDragEnd);

      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);

    columnEl.addEventListener("dragover", onDragOver);
    columnEl.addEventListener("dragleave", onDragLeave);
    columnEl.addEventListener("drop", onDrop);

    boardContainer.appendChild(columnEl);
  });
}

function openCreateTaskModal() {
  modalTitle.textContent = "Create Task";
  taskIdInput.value = "";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskAssigneeInput.value = "";
  taskColumnSelect.value = board.columns[0]?.id || "";
  deleteTaskBtn.classList.add("hidden");
  taskModal.classList.remove("hidden");
}

function openEditTaskModal(taskId, columnId) {
  const task = board.tasks[taskId];
  if (!task) return;

  modalTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskAssigneeInput.value = task.assignee || "";
  taskColumnSelect.value = columnId;
  deleteTaskBtn.classList.remove("hidden");
  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
}

async function saveTask() {
  const taskId = taskIdInput.value;
  const payload = {
    title: taskTitleInput.value.trim(),
    description: taskDescriptionInput.value.trim(),
    assignee: taskAssigneeInput.value.trim(),
    columnId: taskColumnSelect.value
  };

  if (!payload.title) {
    alert("Task title is required");
    return;
  }

  if (taskId) {
    await fetch(`${API_URL}/boards/${BOARD_ID}/tasks/${taskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const currentColumn = board.columns.find((col) => col.taskIds.includes(taskId));
    if (currentColumn && currentColumn.id !== payload.columnId) {
      const sourceIndex = currentColumn.taskIds.indexOf(taskId);
      await fetch(`${API_URL}/boards/${BOARD_ID}/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sourceColumnId: currentColumn.id,
          destinationColumnId: payload.columnId,
          sourceIndex,
          destinationIndex: board.columns.find(c => c.id === payload.columnId).taskIds.length
        })
      });
    }
  } else {
    await fetch(`${API_URL}/boards/${BOARD_ID}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  }

  closeModal();
}

async function deleteTask() {
  const taskId = taskIdInput.value;
  if (!taskId) return;
  if (!confirm("Delete this task?")) return;

  await fetch(`${API_URL}/boards/${BOARD_ID}/tasks/${taskId}`, {
    method: "DELETE"
  });

  closeModal();
}

let dragData = null;

function onDragStart(e) {
  const taskEl = e.currentTarget;
  dragData = {
    taskId: taskEl.dataset.taskId,
    sourceColumnId: taskEl.dataset.columnId,
    sourceIndex: Number(taskEl.dataset.index)
  };
  taskEl.classList.add("dragging");
}

function onDragEnd(e) {
  e.currentTarget.classList.remove("dragging");
  document.querySelectorAll(".column").forEach((col) => col.classList.remove("drag-over"));
}

function onDragOver(e) {
  e.preventDefault();
  e.currentTarget.classList.add("drag-over");
}

function onDragLeave(e) {
  e.currentTarget.classList.remove("drag-over");
}

async function onDrop(e) {
  e.preventDefault();
  const columnEl = e.currentTarget;
  columnEl.classList.remove("drag-over");

  if (!dragData) return;

  const destinationColumnId = columnEl.dataset.columnId;
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);
  const destinationIndex = destinationColumn.taskIds.length;

  await fetch(`${API_URL}/boards/${BOARD_ID}/reorder`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sourceColumnId: dragData.sourceColumnId,
      destinationColumnId,
      sourceIndex: dragData.sourceIndex,
      destinationIndex
    })
  });

  dragData = null;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function updatePresenceUI() {
  presenceList.innerHTML = "";
  const users = Array.from(collaborators.values());

  if (!users.length) {
    presenceList.textContent = "No active collaborators";
    return;
  }

  users.forEach((user) => {
    const el = document.createElement("span");
    el.className = "presence-user";
    el.textContent = user.name;
    presenceList.appendChild(el);
  });
}

function announcePresence() {
  const user = {
    id: socket.id,
    name: currentUser,
    lastSeen: Date.now()
  };
  collaborators.set(user.id, user);
  updatePresenceUI();
  socket.emit("presence:update", { boardId: BOARD_ID, user });
}

socket.on("connect", () => {
  socket.emit("board:join", BOARD_ID);
  announcePresence();
});

socket.on("presence:update", (user) => {
  collaborators.set(user.id, user);
  updatePresenceUI();
});

socket.on("task:created", ({ task, columnId }) => {
  board.tasks[task.id] = task;
  const col = board.columns.find((c) => c.id === columnId);
  if (col && !col.taskIds.includes(task.id)) {
    col.taskIds.push(task.id);
  }
  renderBoard();
});

socket.on("task:updated", ({ task }) => {
  board.tasks[task.id] = task;
  renderBoard();
});

socket.on("task:deleted", ({ taskId }) => {
  delete board.tasks[taskId];
  board.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });
  renderBoard();
});

socket.on("task:moved", ({ sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId }) => {
  const sourceCol = board.columns.find((c) => c.id === sourceColumnId);
  const destCol = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceCol || !destCol) return;

  const existingSourceIndex = sourceCol.taskIds.indexOf(taskId);
  if (existingSourceIndex !== -1) {
    sourceCol.taskIds.splice(existingSourceIndex, 1);
  } else {
    sourceCol.taskIds.splice(sourceIndex, 1);
  }

  if (!destCol.taskIds.includes(taskId)) {
    destCol.taskIds.splice(destinationIndex, 0, taskId);
  }

  renderBoard();
});

newTaskBtn.addEventListener("click", openCreateTaskModal);
saveTaskBtn.addEventListener("click", saveTask);
cancelTaskBtn.addEventListener("click", closeModal);
deleteTaskBtn.addEventListener("click", deleteTask);

saveNameBtn.addEventListener("click", () => {
  currentUser = usernameInput.value.trim() || currentUser;
  localStorage.setItem("pm_user", currentUser);
  announcePresence();
});

window.addEventListener("load", fetchBoard);
```

