## `server/server.js`

```js
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import http from "http";

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 4000;

const server = http.createServer(app);

const wss = new WebSocketServer({ server });

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project",
      description: "Initialize frontend and backend structure"
    },
    "task-2": {
      id: "task-2",
      title: "Design board UI",
      description: "Create Kanban layout and styling"
    }
  }
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/task", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const id = `task-${Date.now()}`;
  boardState.tasks[id] = { id, title, description };

  const column = boardState.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(id);

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json(boardState);
});

app.put("/api/task/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  boardState.tasks[id] = {
    ...boardState.tasks[id],
    title: title ?? boardState.tasks[id].title,
    description: description ?? boardState.tasks[id].description
  };

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json(boardState);
});

app.delete("/api/task/:id", (req, res) => {
  const { id } = req.params;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete boardState.tasks[id];
  boardState.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((taskId) => taskId !== id);
  });

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json(boardState);
});

app.put("/api/board/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  broadcast({
    type: "BOARD_UPDATED",
    payload: boardState
  });

  res.json(boardState);
});

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "BOARD_UPDATED",
      payload: boardState
    })
  );

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

