## `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let boardState = null;
let socket = null;
let draggedTaskId = null;
let draggedSourceColumnId = null;
let draggedSourceIndex = null;

const boardEl = document.getElementById("board");
const statusEl = document.getElementById("status");
const newTaskBtn = document.getElementById("newTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");
const dialogTitle = document.getElementById("dialogTitle");
const cancelBtn = document.getElementById("cancelBtn");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
  populateColumnOptions();
}

function connectWebSocket() {
  socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    statusEl.textContent = "Connected";
  });

  socket.addEventListener("close", () => {
    statusEl.textContent = "Disconnected - retrying...";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("message", (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATED") {
      boardState = data.payload;
      renderBoard();
      populateColumnOptions();
    }
  });
}

function populateColumnOptions() {
  taskColumnSelect.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      const destinationColumnId = column.id;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      if (draggedTaskId == null) return;

      await fetch(`${API_URL}/board/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sourceColumnId: draggedSourceColumnId,
          destinationColumnId,
          sourceIndex: draggedSourceIndex,
          destinationIndex,
          taskId: draggedTaskId
        })
      });

      draggedTaskId = null;
      draggedSourceColumnId = null;
      draggedSourceIndex = null;
    });

    column.taskIds.forEach((taskId, index) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedSourceColumnId = column.id;
        draggedSourceIndex = index;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const title = document.createElement("h3");
      title.textContent = task.title;

      const desc = document.createElement("p");
      desc.textContent = task.description || "";

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.className = "edit-btn";
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditDialog(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", async () => {
        await fetch(`${API_URL}/task/${task.id}`, {
          method: "DELETE"
        });
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      taskEl.appendChild(title);
      taskEl.appendChild(desc);
      taskEl.appendChild(actions);

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(container, mouseY) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  let closest = { offset: Number.NEGATIVE_INFINITY, index: draggableElements.length };

  draggableElements.forEach((child, index) => {
    const box = child.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

function openNewDialog() {
  dialogTitle.textContent = "New Task";
  taskIdInput.value = "";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnSelect.value = boardState.columns[0]?.id || "todo";
  taskDialog.showModal();
}

function openEditDialog(task, columnId) {
  dialogTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskColumnSelect.value = columnId;
  taskDialog.showModal();
}

newTaskBtn.addEventListener("click", openNewDialog);

cancelBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const id = taskIdInput.value;
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  if (id) {
    const originalColumn = boardState.columns.find((col) =>
      col.taskIds.includes(id)
    );

    await fetch(`${API_URL}/task/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description })
    });

    if (originalColumn && originalColumn.id !== columnId) {
      const sourceIndex = originalColumn.taskIds.indexOf(id);
      const destinationColumn = boardState.columns.find((c) => c.id === columnId);
      const destinationIndex = destinationColumn.taskIds.length;

      await fetch(`${API_URL}/board/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sourceColumnId: originalColumn.id,
          destinationColumnId: columnId,
          sourceIndex,
          destinationIndex,
          taskId: id
        })
      });
    }
  } else {
    await fetch(`${API_URL}/task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, columnId })
    });
  }

  taskDialog.close();
});

fetchBoard();
connectWebSocket();
