# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const { v4: uuidv4 } = require("uuid");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const board = {
  id: "default-board",
  name: "Team Project Board",
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function broadcast(data, exclude = null) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN && client !== exclude) {
      client.send(message);
    }
  });
}

function getBoardState() {
  return board;
}

app.get("/api/board", (req, res) => {
  res.json(getBoardState());
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskId = uuidv4();
  const task = {
    id: taskId,
    title,
    description,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  board.tasks[taskId] = task;
  column.taskIds.push(taskId);

  const payload = {
    type: "TASK_CREATED",
    task,
    columnId
  };

  broadcast(payload);
  res.status(201).json({ success: true, task, columnId });
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  const task = board.tasks[taskId];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;
  task.updatedAt = new Date().toISOString();

  const payload = {
    type: "TASK_UPDATED",
    task
  };

  broadcast(payload);
  res.json({ success: true, task });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const task = board.tasks[taskId];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  }

  delete board.tasks[taskId];

  const payload = {
    type: "TASK_DELETED",
    taskId
  };

  broadcast(payload);
  res.json({ success: true });
});

app.post("/api/tasks/:taskId/move", (req, res) => {
  const { taskId } = req.params;
  const { sourceColumnId, targetColumnId, targetIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const targetColumn = board.columns.find((c) => c.id === targetColumnId);

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (!sourceColumn || !targetColumn) {
    return res.status(404).json({ error: "Source or target column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const safeIndex =
    typeof targetIndex === "number" && targetIndex >= 0
      ? Math.min(targetIndex, targetColumn.taskIds.length)
      : targetColumn.taskIds.length;

  targetColumn.taskIds.splice(safeIndex, 0, taskId);

  const payload = {
    type: "TASK_MOVED",
    taskId,
    sourceColumnId,
    targetColumnId,
    targetIndex: safeIndex
  };

  broadcast(payload);
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "BOARD_STATE",
      board: getBoardState()
    })
  );

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

