# 5. `public/app.js`

```js
const state = {
  board: null,
  ws: null,
  draggedTaskId: null,
  draggedFromColumnId: null
};

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const statusEl = document.getElementById("status");
const taskModal = document.getElementById("taskModal");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");
const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");
const cancelModalBtn = document.getElementById("cancelModalBtn");

function openModal(edit = false, task = null, columnId = "todo") {
  modalTitle.textContent = edit ? "Edit Task" : "Add Task";
  taskIdInput.value = task?.id || "";
  taskTitleInput.value = task?.title || "";
  taskDescriptionInput.value = task?.description || "";
  populateColumnOptions();
  taskColumnSelect.value = task ? findTaskColumn(task.id) : columnId;
  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
  taskForm.reset();
  taskIdInput.value = "";
}

function populateColumnOptions() {
  taskColumnSelect.innerHTML = "";
  state.board.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);
  });
}

function findTaskColumn(taskId) {
  return state.board.columns.find((col) => col.taskIds.includes(taskId))?.id;
}

async function fetchBoard() {
  const res = await fetch("/api/board");
  const data = await res.json();
  state.board = data;
  renderBoard();
}

function renderBoard() {
  if (!state.board) return;

  boardEl.innerHTML = "";

  state.board.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+";
    addBtn.title = `Add task to ${column.title}`;
    addBtn.addEventListener("click", () => openModal(false, null, column.id));

    const headerWrap = document.createElement("div");
    headerWrap.style.display = "flex";
    headerWrap.style.justifyContent = "space-between";
    headerWrap.style.alignItems = "center";
    headerWrap.appendChild(titleEl);
    headerWrap.appendChild(addBtn);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!state.draggedTaskId || !state.draggedFromColumnId) return;
      const targetColumnId = column.id;

      await moveTask(state.draggedTaskId, state.draggedFromColumnId, targetColumnId, column.taskIds.length);

      state.draggedTaskId = null;
      state.draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = state.board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        state.draggedTaskId = task.id;
        state.draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const title = document.createElement("h3");
      title.textContent = task.title;

      const desc = document.createElement("p");
      desc.textContent = task.description || "No description";

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openModal(true, task));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.className = "delete";
      deleteBtn.addEventListener("click", async () => {
        await deleteTask(task.id);
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      taskEl.appendChild(title);
      taskEl.appendChild(desc);
      taskEl.appendChild(actions);

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(headerWrap);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

async function createTask(title, description, columnId) {
  const res = await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, columnId })
  });

  if (!res.ok) {
    alert("Failed to create task");
  }
}

async function updateTask(taskId, title, description, newColumnId) {
  const oldColumnId = findTaskColumn(taskId);

  const updateRes = await fetch(`/api/tasks/${taskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description })
  });

  if (!updateRes.ok) {
    alert("Failed to update task");
    return;
  }

  if (oldColumnId && newColumnId && oldColumnId !== newColumnId) {
    await moveTask(taskId, oldColumnId, newColumnId, state.board.columns.find(c => c.id === newColumnId).taskIds.length);
  }
}

async function deleteTask(taskId) {
  const res = await fetch(`/api/tasks/${taskId}`, {
    method: "DELETE"
  });

  if (!res.ok) {
    alert("Failed to delete task");
  }
}

async function moveTask(taskId, sourceColumnId, targetColumnId, targetIndex) {
  const res = await fetch(`/api/tasks/${taskId}/move`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sourceColumnId,
      targetColumnId,
      targetIndex
    })
  });

  if (!res.ok) {
    alert("Failed to move task");
  }
}

function applyRealtimeEvent(event) {
  switch (event.type) {
    case "BOARD_STATE":
      state.board = event.board;
      renderBoard();
      break;

    case "TASK_CREATED": {
      state.board.tasks[event.task.id] = event.task;
      const column = state.board.columns.find((c) => c.id === event.columnId);
      if (column && !column.taskIds.includes(event.task.id)) {
        column.taskIds.push(event.task.id);
      }
      renderBoard();
      break;
    }

    case "TASK_UPDATED": {
      state.board.tasks[event.task.id] = event.task;
      renderBoard();
      break;
    }

    case "TASK_DELETED": {
      delete state.board.tasks[event.taskId];
      state.board.columns.forEach((column) => {
        column.taskIds = column.taskIds.filter((id) => id !== event.taskId);
      });
      renderBoard();
      break;
    }

    case "TASK_MOVED": {
      const { taskId, sourceColumnId, targetColumnId, targetIndex } = event;
      const sourceColumn = state.board.columns.find((c) => c.id === sourceColumnId);
      const targetColumn = state.board.columns.find((c) => c.id === targetColumnId);

      if (sourceColumn) {
        sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
      }

      if (targetColumn && !targetColumn.taskIds.includes(taskId)) {
        targetColumn.taskIds.splice(targetIndex, 0, taskId);
      }

      renderBoard();
      break;
    }
  }
}

function connectWebSocket() {
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  const ws = new WebSocket(`${protocol}//${window.location.host}`);
  state.ws = ws;

  ws.addEventListener("open", () => {
    statusEl.textContent = "Connected";
    statusEl.style.color = "#86efac";
  });

  ws.addEventListener("close", () => {
    statusEl.textContent = "Disconnected";
    statusEl.style.color = "#fca5a5";
    setTimeout(connectWebSocket, 2000);
  });

  ws.addEventListener("message", (message) => {
    const event = JSON.parse(message.data);
    applyRealtimeEvent(event);
  });
}

addTaskBtn.addEventListener("click", () => openModal(false));

cancelModalBtn.addEventListener("click", closeModal);

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  if (id) {
    await updateTask(id, title, description, columnId);
  } else {
    await createTask(title, description, columnId);
  }

  closeModal();
});

window.addEventListener("DOMContentLoaded", async () => {
  await fetchBoard();
  connectWebSocket();
});
```

