# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        {
          id: "task-1",
          title: "Set up project repo",
          description: "Initialize repository and README"
        },
        {
          id: "task-2",
          title: "Design homepage",
          description: "Create initial wireframes"
        }
      ]
    },
    {
      id: "inprogress",
      title: "In Progress",
      tasks: [
        {
          id: "task-3",
          title: "Build drag-and-drop UI",
          description: "Implement Kanban interactions"
        }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        {
          id: "task-4",
          title: "Collect requirements",
          description: "Define MVP features"
        }
      ]
    }
  ]
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", ({ columnId, task }) => {
    const column = boardState.columns.find((col) => col.id === columnId);
    if (!column) return;

    column.tasks.push(task);
    io.emit("board:update", boardState);
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    for (const column of boardState.columns) {
      const task = column.tasks.find((t) => t.id === taskId);
      if (task) {
        task.title = title;
        task.description = description;
        break;
      }
    }
    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const column of boardState.columns) {
      const index = column.tasks.findIndex((t) => t.id === taskId);
      if (index !== -1) {
        column.tasks.splice(index, 1);
        break;
      }
    }
    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = boardState.columns.find((col) => col.id === sourceColumnId);
    const targetColumn = boardState.columns.find((col) => col.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    const taskIndex = sourceColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceColumn.tasks.splice(taskIndex, 1);

    const safeIndex = Math.max(0, Math.min(targetIndex, targetColumn.tasks.length));
    targetColumn.tasks.splice(safeIndex, 0, task);

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

