# 6. `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskModal = document.getElementById("taskModal");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");
const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");
const cancelBtn = document.getElementById("cancelBtn");

function generateId() {
  return "task-" + Date.now() + "-" + Math.floor(Math.random() * 10000);
}

function openModal({ mode, task = null, columnId = null }) {
  taskColumnSelect.innerHTML = "";

  if (!boardState) return;

  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);
  });

  if (mode === "create") {
    modalTitle.textContent = "Add Task";
    taskIdInput.value = "";
    taskTitleInput.value = "";
    taskDescriptionInput.value = "";
    taskColumnSelect.value = columnId || boardState.columns[0].id;
    deleteTaskBtn.classList.add("hidden");
  } else {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    taskTitleInput.value = task.title;
    taskDescriptionInput.value = task.description || "";
    taskColumnSelect.value = columnId;
    deleteTaskBtn.classList.remove("hidden");
  }

  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      let targetIndex = column.tasks.length;

      if (afterElement) {
        targetIndex = [...taskListEl.children].indexOf(afterElement);
      }

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId: column.id,
        targetIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.tasks.forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("click", () => {
        openModal({ mode: "edit", task, columnId: column.id });
      });

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    const addInlineBtn = document.createElement("button");
    addInlineBtn.className = "add-task-inline";
    addInlineBtn.textContent = "+ Add task";
    addInlineBtn.addEventListener("click", () => {
      openModal({ mode: "create", columnId: column.id });
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    columnEl.appendChild(addInlineBtn);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

addTaskBtn.addEventListener("click", () => {
  openModal({ mode: "create" });
});

cancelBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", (e) => {
  if (e.target === taskModal) closeModal();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const id = taskIdInput.value;
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const selectedColumnId = taskColumnSelect.value;

  if (!title) return;

  if (!id) {
    socket.emit("task:create", {
      columnId: selectedColumnId,
      task: {
        id: generateId(),
        title,
        description
      }
    });
  } else {
    const originalColumn = boardState.columns.find((col) =>
      col.tasks.some((task) => task.id === id)
    );

    if (originalColumn && originalColumn.id !== selectedColumnId) {
      socket.emit("task:update", { taskId: id, title, description });

      socket.emit("task:move", {
        taskId: id,
        sourceColumnId: originalColumn.id,
        targetColumnId: selectedColumnId,
        targetIndex: boardState.columns.find(c => c.id === selectedColumnId).tasks.length
      });
    } else {
      socket.emit("task:update", { taskId: id, title, description });
    }
  }

  closeModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const id = taskIdInput.value;
  if (!id) return;

  socket.emit("task:delete", { taskId: id });
  closeModal();
});

socket.on("board:init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});
```

