# 2. Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const PORT = 4000;

/**
 * In-memory board state
 * Replace with a database in production.
 */
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project repository",
      description: "Initialize Git repo and README",
      assignee: "Alice",
      dueDate: "2026-09-20"
    },
    "task-2": {
      id: "task-2",
      title: "Design board layout",
      description: "Create initial Kanban UI",
      assignee: "Bob",
      dueDate: "2026-09-22"
    }
  }
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, dueDate, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const id = `task-${Date.now()}`;
  const task = {
    id,
    title,
    description: description || "",
    assignee: assignee || "",
    dueDate: dueDate || ""
  };

  board.tasks[id] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(id);

  broadcast({ type: "BOARD_UPDATED", payload: board });

  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id
  };

  board.tasks[id] = updated;

  broadcast({ type: "BOARD_UPDATED", payload: board });

  res.json(updated);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];

  board.columns = board.columns.map((column) => ({
    ...column,
    taskIds: column.taskIds.filter((taskId) => taskId !== id)
  }));

  broadcast({ type: "BOARD_UPDATED", payload: board });

  res.json({ success: true });
});

app.put("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  if (destinationIndex >= 0 && destinationIndex <= destinationColumn.taskIds.length) {
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
  } else {
    destinationColumn.taskIds.push(taskId);
  }

  broadcast({ type: "BOARD_UPDATED", payload: board });

  res.json({ success: true, board });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATED", payload: board }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });

  ws.on("close", () => {
    console.log("Client disconnected");
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

