# 5. Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let boardState = null;
let socket = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const connectionStatusEl = document.getElementById("connection-status");
const taskModal = document.getElementById("task-modal");
const taskForm = document.getElementById("task-form");
const modalTitle = document.getElementById("modal-title");
const openTaskModalBtn = document.getElementById("open-task-modal");
const cancelTaskModalBtn = document.getElementById("cancel-task-modal");

const taskIdInput = document.getElementById("task-id");
const taskTitleInput = document.getElementById("task-title");
const taskDescriptionInput = document.getElementById("task-description");
const taskAssigneeInput = document.getElementById("task-assignee");
const taskDueDateInput = document.getElementById("task-due-date");
const taskColumnInput = document.getElementById("task-column");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
  populateColumnOptions();
}

function connectWebSocket() {
  socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    connectionStatusEl.textContent = "Connected";
  });

  socket.addEventListener("close", () => {
    connectionStatusEl.textContent = "Disconnected - retrying...";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("message", (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATED") {
      boardState = data.payload;
      renderBoard();
      populateColumnOptions();
    }
  });
}

function populateColumnOptions() {
  taskColumnInput.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnInput.appendChild(option);
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drop-target");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-target");
    });

    taskList.addEventListener("drop", async (e) => {
      e.preventDefault();
      taskList.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskList.dataset.columnId;
      const destinationIndex = boardState.columns.find(c => c.id === destinationColumnId).taskIds.length;

      await fetch(`${API_URL}/board/move`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      const titleEl = document.createElement("h3");
      titleEl.textContent = task.title;

      const descEl = document.createElement("p");
      descEl.textContent = task.description || "";

      const metaEl = document.createElement("div");
      metaEl.className = "task-meta";
      metaEl.innerHTML = `
        <div><strong>Assignee:</strong> ${task.assignee || "Unassigned"}</div>
        <div><strong>Due:</strong> ${task.dueDate || "No due date"}</div>
      `;

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.className = "edit-btn";
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditModal(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", async () => {
        await fetch(`${API_URL}/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(titleEl);
      card.appendChild(descEl);
      card.appendChild(metaEl);
      card.appendChild(actions);

      taskList.appendChild(card);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function openCreateModal() {
  modalTitle.textContent = "Add Task";
  taskForm.reset();
  taskIdInput.value = "";
  if (boardState?.columns?.length) {
    taskColumnInput.value = boardState.columns[0].id;
  }
  taskModal.classList.remove("hidden");
}

function openEditModal(task, columnId) {
  modalTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskAssigneeInput.value = task.assignee || "";
  taskDueDateInput.value = task.dueDate || "";
  taskColumnInput.value = columnId;
  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
}

openTaskModalBtn.addEventListener("click", openCreateModal);
cancelTaskModalBtn.addEventListener("click", closeModal);

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const payload = {
    title: taskTitleInput.value.trim(),
    description: taskDescriptionInput.value.trim(),
    assignee: taskAssigneeInput.value.trim(),
    dueDate: taskDueDateInput.value,
    columnId: taskColumnInput.value
  };

  if (!payload.title) return;

  if (id) {
    const currentColumn = boardState.columns.find((col) => col.taskIds.includes(id));
    const selectedColumnId = payload.columnId;

    await fetch(`${API_URL}/tasks/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: payload.title,
        description: payload.description,
        assignee: payload.assignee,
        dueDate: payload.dueDate
      })
    });

    if (currentColumn && currentColumn.id !== selectedColumnId) {
      await fetch(`${API_URL}/board/move`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: id,
          sourceColumnId: currentColumn.id,
          destinationColumnId: selectedColumnId,
          destinationIndex: boardState.columns.find(c => c.id === selectedColumnId).taskIds.length
        })
      });
    }
  } else {
    await fetch(`${API_URL}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  }

  closeModal();
});

window.addEventListener("DOMContentLoaded", async () => {
  await fetchBoard();
  connectWebSocket();
});
```

