# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Set up project repo", description: "Initialize GitHub repository" },
        { id: "task-2", title: "Design homepage", description: "Create wireframe for dashboard" }
      ]
    },
    {
      id: "inprogress",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag-and-drop", description: "Implement task movement between columns" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Write requirements", description: "Document MVP features" }
      ]
    }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  broadcast({ type: "BOARD_UPDATE", payload: boardState });
  res.json({ success: true });
});

app.post("/api/task", (req, res) => {
  const { columnId, task } = req.body;
  const column = boardState.columns.find(c => c.id === columnId);

  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.tasks.push(task);
  broadcast({ type: "BOARD_UPDATE", payload: boardState });
  res.json({ success: true, board: boardState });
});

app.put("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;
  const updatedTask = req.body;

  for (const column of boardState.columns) {
    const taskIndex = column.tasks.findIndex(t => t.id === taskId);
    if (taskIndex !== -1) {
      column.tasks[taskIndex] = { ...column.tasks[taskIndex], ...updatedTask };
      broadcast({ type: "BOARD_UPDATE", payload: boardState });
      return res.json({ success: true, board: boardState });
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const column of boardState.columns) {
    const taskIndex = column.tasks.findIndex(t => t.id === taskId);
    if (taskIndex !== -1) {
      column.tasks.splice(taskIndex, 1);
      broadcast({ type: "BOARD_UPDATE", payload: boardState });
      return res.json({ success: true, board: boardState });
    }
  }

  res.status(404).json({ error: "Task not found" });
});

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATE", payload: boardState }));

  ws.on("message", message => {
    try {
      const data = JSON.parse(message);

      if (data.type === "MOVE_TASK") {
        const { taskId, sourceColumnId, targetColumnId, targetIndex } = data.payload;

        const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
        const targetColumn = boardState.columns.find(c => c.id === targetColumnId);

        if (!sourceColumn || !targetColumn) return;

        const taskIndex = sourceColumn.tasks.findIndex(t => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = sourceColumn.tasks.splice(taskIndex, 1);
        targetColumn.tasks.splice(targetIndex, 0, task);

        broadcast({ type: "BOARD_UPDATE", payload: boardState });
      }

      if (data.type === "CREATE_TASK") {
        const { columnId, task } = data.payload;
        const column = boardState.columns.find(c => c.id === columnId);
        if (!column) return;

        column.tasks.push(task);
        broadcast({ type: "BOARD_UPDATE", payload: boardState });
      }

      if (data.type === "UPDATE_TASK") {
        const { taskId, updates } = data.payload;
        for (const column of boardState.columns) {
          const task = column.tasks.find(t => t.id === taskId);
          if (task) {
            Object.assign(task, updates);
            broadcast({ type: "BOARD_UPDATE", payload: boardState });
            break;
          }
        }
      }

      if (data.type === "DELETE_TASK") {
        const { taskId } = data.payload;
        for (const column of boardState.columns) {
          const index = column.tasks.findIndex(t => t.id === taskId);
          if (index !== -1) {
            column.tasks.splice(index, 1);
            broadcast({ type: "BOARD_UPDATE", payload: boardState });
            break;
          }
        }
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
