  socket.addEventListener("message", event => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATE") {
      boardState = data.payload;
      renderBoard();
      populateColumnOptions();
    }
  });
}

function populateColumnOptions() {
  taskColumnInput.innerHTML = "";
  boardState.columns.forEach(column => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnInput.appendChild(option);
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = `${column.title} (${column.tasks.length})`;

    headerEl.appendChild(titleEl);
    columnEl.appendChild(headerEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", e => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = column.id;
      const targetIndex = column.tasks.length;

      socket.send(JSON.stringify({
        type: "MOVE_TASK",
        payload: {
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          targetColumnId,
          targetIndex
        }
      }));

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.tasks.forEach(task => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const title = document.createElement("h3");
      title.textContent = task.title;

      const desc = document.createElement("p");
      desc.textContent = task.description || "";

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditDialog(task, column.id));

      actions.appendChild(editBtn);

      taskEl.appendChild(title);
      taskEl.appendChild(desc);
      taskEl.appendChild(actions);

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function openAddDialog() {
  dialogTitle.textContent = "Add Task";
  taskIdInput.value = "";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnInput.value = boardState.columns[0]?.id || "";
  deleteTaskBtn.style.display = "none";
  taskDialog.showModal();
}

function openEditDialog(task, columnId) {
  dialogTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskColumnInput.value = columnId;
  deleteTaskBtn.style.display = "inline-block";
  taskDialog.showModal();
}

addTaskBtn.addEventListener("click", openAddDialog);

cancelTaskBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", e => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const selectedColumnId = taskColumnInput.value;

  if (!title) return;

  if (!id) {
    const newTask = { id: generateId(), title, description };
    socket.send(JSON.stringify({
      type: "CREATE_TASK",
      payload: {
        columnId: selectedColumnId,
        task: newTask
      }
    }));
  } else {
    let currentColumnId = null;
    for (const column of boardState.columns) {
      if (column.tasks.some(t => t.id === id)) {
        currentColumnId = column.id;
        break;
      }
    }

    socket.send(JSON.stringify({
      type: "UPDATE_TASK",
      payload: {
        taskId: id,
        updates: { title, description }
      }
    }));

    if (currentColumnId && currentColumnId !== selectedColumnId) {
      socket.send(JSON.stringify({
        type: "MOVE_TASK",
        payload: {
          taskId: id,
          sourceColumnId: currentColumnId,
          targetColumnId: selectedColumnId,
          targetIndex: boardState.columns.find(c => c.id === selectedColumnId)?.tasks.length || 0
        }
      }));
    }
  }

  taskDialog.close();
});

deleteTaskBtn.addEventListener("click", () => {
  const id = taskIdInput.value;
  if (!id) return;

  socket.send(JSON.stringify({
    type: "DELETE_TASK",
    payload: { taskId: id }
  }));

  taskDialog.close();
});

fetchBoard();
connectWebSocket();
```

