# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory data store
 * Replace with a database for production use.
 */
let board = {
  id: "board-1",
  name: "Team Project Board",
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed data
const seedTasks = [
  {
    id: uuidv4(),
    title: "Set up project repository",
    description: "Initialize Git repo and project structure",
    assignee: "Alice",
    priority: "High",
    createdAt: new Date().toISOString()
  },
  {
    id: uuidv4(),
    title: "Design homepage wireframe",
    description: "Create initial UI mockups",
    assignee: "Bob",
    priority: "Medium",
    createdAt: new Date().toISOString()
  },
  {
    id: uuidv4(),
    title: "Implement auth flow",
    description: "Login, logout, and session handling",
    assignee: "Charlie",
    priority: "High",
    createdAt: new Date().toISOString()
  }
];

board.tasks[seedTasks[0].id] = seedTasks[0];
board.tasks[seedTasks[1].id] = seedTasks[1];
board.tasks[seedTasks[2].id] = seedTasks[2];

board.columns[0].taskIds.push(seedTasks[0].id, seedTasks[1].id);
board.columns[1].taskIds.push(seedTasks[2].id);

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, priority, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = {
    id: uuidv4(),
    title,
    description: description || "",
    assignee: assignee || "",
    priority: priority || "Low",
    createdAt: new Date().toISOString()
  };

  board.tasks[task.id] = task;
  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = board.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id: taskId
  };

  board.tasks[taskId] = updated;

  io.emit("board:update", board);
  res.json(updated);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  board.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  io.emit("board:update", board);
  res.json({ success: true });
});

app.post("/api/board/move-task", (req, res) => {
  const {
    taskId,
    sourceColumnId,
    destinationColumnId,
    sourceIndex,
    destinationIndex
  } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Source or destination column not found" });
  }

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ success: true, board });
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", (payload) => {
    const { title, description, assignee, priority, columnId } = payload;

    if (!title || !columnId) return;

    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    const task = {
      id: uuidv4(),
      title,
      description: description || "",
      assignee: assignee || "",
      priority: priority || "Low",
      createdAt: new Date().toISOString()
    };

    board.tasks[task.id] = task;
    column.taskIds.push(task.id);

    io.emit("board:update", board);
  });

  socket.on("task:update", ({ taskId, updates }) => {
    if (!board.tasks[taskId]) return;

    board.tasks[taskId] = {
      ...board.tasks[taskId],
      ...updates,
      id: taskId
    };

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId }) => {
    if (!board.tasks[taskId]) return;

    delete board.tasks[taskId];
    board.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn || !board.tasks[taskId]) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
