# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;
let draggedFromIndex = null;

const boardEl = document.getElementById("board");
const taskModal = document.getElementById("taskModal");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");
const openTaskModalBtn = document.getElementById("openTaskModalBtn");
const closeTaskModalBtn = document.getElementById("closeTaskModalBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const assigneeInput = document.getElementById("assignee");
const priorityInput = document.getElementById("priority");
const columnIdInput = document.getElementById("columnId");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function populateColumnOptions() {
  columnIdInput.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    columnIdInput.appendChild(option);
  });
}

function renderBoard() {
  if (!boardState) return;

  populateColumnOptions();
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId) return;

      const destinationColumnId = column.id;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId,
        sourceIndex: draggedFromIndex,
        destinationIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
      draggedFromIndex = null;
    });

    column.taskIds.forEach((taskId, index) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = `task-card priority-${task.priority}`;
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-meta">
          <div><strong>Assignee:</strong> ${escapeHtml(task.assignee || "Unassigned")}</div>
          <div><strong>Priority:</strong> ${escapeHtml(task.priority)}</div>
        </div>
      `;

      taskEl.addEventListener("click", () => openEditModal(task, column.id));

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        draggedFromIndex = index;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(taskListEl, mouseY) {
  const taskElements = [...taskListEl.querySelectorAll(".task-card:not(.dragging)")];

  let closest = { offset: Number.NEGATIVE_INFINITY, index: taskElements.length };

  taskElements.forEach((child, index) => {
    const box = child.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

function openCreateModal() {
  modalTitle.textContent = "Create Task";
  taskForm.reset();
  taskIdInput.value = "";
  deleteTaskBtn.classList.add("hidden");
  if (boardState?.columns?.length) {
    columnIdInput.value = boardState.columns[0].id;
  }
  taskModal.classList.remove("hidden");
}

function openEditModal(task, columnId) {
  modalTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  titleInput.value = task.title;
  descriptionInput.value = task.description || "";
  assigneeInput.value = task.assignee || "";
  priorityInput.value = task.priority || "Low";
  columnIdInput.value = columnId;
  deleteTaskBtn.classList.remove("hidden");
  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
}

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const taskId = taskIdInput.value.trim();
  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();
  const assignee = assigneeInput.value.trim();
  const priority = priorityInput.value;
  const selectedColumnId = columnIdInput.value;

  if (!title) return;

  if (taskId) {
    const currentColumn = boardState.columns.find((col) =>
      col.taskIds.includes(taskId)
    );

    socket.emit("task:update", {
      taskId,
      updates: { title, description, assignee, priority }
    });

    if (currentColumn && currentColumn.id !== selectedColumnId) {
      const sourceIndex = currentColumn.taskIds.indexOf(taskId);
      const destinationColumn = boardState.columns.find((c) => c.id === selectedColumnId);
      const destinationIndex = destinationColumn.taskIds.length;

      socket.emit("task:move", {
        taskId,
        sourceColumnId: currentColumn.id,
        destinationColumnId: selectedColumnId,
        sourceIndex,
        destinationIndex
      });
    }
  } else {
    socket.emit("task:create", {
      title,
      description,
      assignee,
      priority,
      columnId: selectedColumnId
    });
  }

  closeModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const taskId = taskIdInput.value.trim();
  if (!taskId) return;

  socket.emit("task:delete", { taskId });
  closeModal();
});

openTaskModalBtn.addEventListener("click", openCreateModal);
closeTaskModalBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", (e) => {
  if (e.target === taskModal) closeModal();
});

socket.on("board:update", (updatedBoard) => {
  boardState = updatedBoard;
  renderBoard();
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchBoard();
