# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));
app.use(express.json());

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function broadcastBoard() {
  io.emit("board:update", boardState);
}

io.on("connection", (socket) => {
  console.log(`User connected: ${socket.id}`);

  socket.emit("board:update", boardState);

  socket.on("task:create", ({ columnId, title, description }) => {
    const taskId = uuidv4();
    const task = {
      id: taskId,
      title: title || "Untitled Task",
      description: description || "",
      createdAt: Date.now()
    };

    boardState.tasks[taskId] = task;

    const column = boardState.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(taskId);
      broadcastBoard();
    }
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    if (boardState.tasks[taskId]) {
      boardState.tasks[taskId].title = title;
      boardState.tasks[taskId].description = description;
      broadcastBoard();
    }
  });

  socket.on("task:delete", ({ taskId }) => {
    delete boardState.tasks[taskId];

    boardState.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    broadcastBoard();
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    if (targetIndex < 0 || targetIndex > targetColumn.taskIds.length) {
      targetColumn.taskIds.push(taskId);
    } else {
      targetColumn.taskIds.splice(targetIndex, 0, taskId);
    }

    broadcastBoard();
  });

  socket.on("column:create", ({ title }) => {
    const column = {
      id: uuidv4(),
      title: title || "New Column",
      taskIds: []
    };

    boardState.columns.push(column);
    broadcastBoard();
  });

  socket.on("column:update", ({ columnId, title }) => {
    const column = boardState.columns.find((c) => c.id === columnId);
    if (column) {
      column.title = title;
      broadcastBoard();
    }
  });

  socket.on("disconnect", () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

