# 6. `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const addColumnBtn = document.getElementById("add-column-btn");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Column name:");
  if (title) {
    socket.emit("column:create", { title });
  }
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleInput = columnNode.querySelector(".column-title");
    const addTaskBtn = columnNode.querySelector(".add-task-btn");
    const taskList = columnNode.querySelector(".task-list");

    columnNode.dataset.columnId = column.id;
    taskList.dataset.columnId = column.id;

    titleInput.value = column.title;
    titleInput.addEventListener("change", () => {
      socket.emit("column:update", {
        columnId: column.id,
        title: titleInput.value
      });
    });

    addTaskBtn.addEventListener("click", () => {
      const title = prompt("Task title:");
      if (title) {
        socket.emit("task:create", {
          columnId: column.id,
          title,
          description: ""
        });
      }
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = taskList.dataset.columnId;
      const targetIndex = getDropIndex(taskList, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      const titleInput = taskNode.querySelector(".task-title");
      const descInput = taskNode.querySelector(".task-desc");
      const deleteBtn = taskNode.querySelector(".delete-task-btn");

      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;

      titleInput.value = task.title;
      descInput.value = task.description;

      titleInput.addEventListener("change", () => {
        socket.emit("task:update", {
          taskId: task.id,
          title: titleInput.value,
          description: descInput.value
        });
      });

      descInput.addEventListener("change", () => {
        socket.emit("task:update", {
          taskId: task.id,
          title: titleInput.value,
          description: descInput.value
        });
      });

      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
      });

      taskList.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

function getDropIndex(container, mouseY) {
  const taskElements = [...container.querySelectorAll(".task:not(.dragging)")];

  let closest = {
    offset: Number.NEGATIVE_INFINITY,
    index: taskElements.length
  };

  taskElements.forEach((taskEl, index) => {
    const box = taskEl.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}
