# 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");
const crypto = require("crypto");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const board = {
  id: "default-board",
  title: "Team Project Board",
  columns: [
    {
      id: "col-todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "col-inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "col-done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function createTask({ title, description = "", assignee = "", priority = "Medium" }) {
  const id = crypto.randomUUID();
  return {
    id,
    title,
    description,
    assignee,
    priority,
    createdAt: Date.now()
  };
}

// Seed demo tasks
const task1 = createTask({
  title: "Set up landing page",
  description: "Create initial marketing page layout",
  assignee: "Alice",
  priority: "High"
});
const task2 = createTask({
  title: "Implement auth flow",
  description: "Login, logout, and session handling",
  assignee: "Bob",
  priority: "High"
});
const task3 = createTask({
  title: "Write API docs",
  description: "Document endpoints for frontend team",
  assignee: "Carol",
  priority: "Medium"
});

board.tasks[task1.id] = task1;
board.tasks[task2.id] = task2;
board.tasks[task3.id] = task3;

board.columns[0].taskIds.push(task1.id, task3.id);
board.columns[1].taskIds.push(task2.id);

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, priority, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = createTask({ title, description, assignee, priority });
  board.tasks[task.id] = task;
  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const task = board.tasks[req.params.id];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee, priority } = req.body;

  task.title = title ?? task.title;
  task.description = description ?? task.description;
  task.assignee = assignee ?? task.assignee;
  task.priority = priority ?? task.priority;

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const taskId = req.params.id;
  const task = board.tasks[taskId];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  }

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = board.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;
    if (!board.tasks[taskId]) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex =
      typeof targetIndex === "number" && targetIndex >= 0
        ? Math.min(targetIndex, targetColumn.taskIds.length)
        : targetColumn.taskIds.length;

    targetColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:reorder", ({ columnId, taskId, targetIndex }) => {
    const column = board.columns.find((c) => c.id === columnId);
    if (!column || !board.tasks[taskId]) return;

    column.taskIds = column.taskIds.filter((id) => id !== taskId);

    const safeIndex =
      typeof targetIndex === "number" && targetIndex >= 0
        ? Math.min(targetIndex, column.taskIds.length)
        : column.taskIds.length;

    column.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
