# 5) `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskModal = document.getElementById("taskModal");
const openTaskModalBtn = document.getElementById("openTaskModalBtn");
const closeTaskModalBtn = document.getElementById("closeTaskModalBtn");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");

const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskPriorityInput = document.getElementById("taskPriority");
const taskColumnInput = document.getElementById("taskColumn");

function openModal(editTask = null, columnId = null) {
  populateColumnOptions();

  if (editTask) {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = editTask.id;
    taskTitleInput.value = editTask.title;
    taskDescriptionInput.value = editTask.description || "";
    taskAssigneeInput.value = editTask.assignee || "";
    taskPriorityInput.value = editTask.priority || "Medium";
    taskColumnInput.value = columnId || "";
  } else {
    modalTitle.textContent = "Add Task";
    taskForm.reset();
    taskIdInput.value = "";
  }

  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
}

function populateColumnOptions() {
  taskColumnInput.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnInput.appendChild(option);
  });
}

function getTaskColumnId(taskId) {
  for (const column of boardState.columns) {
    if (column.taskIds.includes(taskId)) return column.id;
  }
  return null;
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+";
    addBtn.addEventListener("click", () => openModal(null, column.id));

    headerEl.appendChild(titleEl);
    headerEl.appendChild(addBtn);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drop-zone-active");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-zone-active");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drop-zone-active");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      let targetIndex = column.taskIds.length;

      if (afterElement) {
        targetIndex = [...taskListEl.children].indexOf(afterElement);
      }

      if (draggedFromColumnId === column.id) {
        socket.emit("task:reorder", {
          columnId: column.id,
          taskId: draggedTaskId,
          targetIndex
        });
      } else {
        socket.emit("task:move", {
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          targetColumnId: column.id,
          targetIndex
        });
      }
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const cardEl = document.createElement("div");
      cardEl.className = "task-card";
      cardEl.draggable = true;
      cardEl.dataset.taskId = task.id;

      cardEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        cardEl.classList.add("dragging");
      });

      cardEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        draggedFromColumnId = null;
        cardEl.classList.remove("dragging");
      });

      const title = document.createElement("h3");
      title.textContent = task.title;

      const desc = document.createElement("p");
      desc.textContent = task.description || "No description";

      const meta = document.createElement("div");
      meta.className = "task-meta";

      const assignee = document.createElement("span");
      assignee.textContent = task.assignee ? `👤 ${task.assignee}` : "Unassigned";

      const priority = document.createElement("span");
      priority.className = `priority ${task.priority.toLowerCase()}`;
      priority.textContent = task.priority;

      meta.appendChild(assignee);
      meta.appendChild(priority);

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openModal(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", async () => {
        await fetch(`/api/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      cardEl.appendChild(title);
      cardEl.appendChild(desc);
      cardEl.appendChild(meta);
      cardEl.appendChild(actions);

      taskListEl.appendChild(cardEl);
    });

    columnEl.appendChild(headerEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task-card:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

openTaskModalBtn.addEventListener("click", () => openModal());
closeTaskModalBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", (e) => {
  if (e.target === taskModal) closeModal();
});

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const payload = {
    title: taskTitleInput.value.trim(),
    description: taskDescriptionInput.value.trim(),
    assignee: taskAssigneeInput.value.trim(),
    priority: taskPriorityInput.value,
    columnId: taskColumnInput.value
  };

  const taskId = taskIdInput.value.trim();

  if (taskId) {
    const oldColumnId = getTaskColumnId(taskId);

    await fetch(`/api/tasks/${taskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    if (oldColumnId && oldColumnId !== payload.columnId) {
      socket.emit("task:move", {
        taskId,
        sourceColumnId: oldColumnId,
        targetColumnId: payload.columnId,
        targetIndex: boardState.columns.find(c => c.id === payload.columnId)?.taskIds.length ?? 0
      });
    }
  } else {
    await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  }

  closeModal();
});

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

async function init() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
}

init();
