# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static("public"));

const boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "inprogress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

function sendBoard(ws) {
  ws.send(JSON.stringify({ type: "BOARD_STATE", payload: boardState }));
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const task = {
    id: uuidv4(),
    title,
    description,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };

  boardState.tasks[task.id] = task;

  const column = boardState.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(task.id);

  broadcast({ type: "BOARD_STATE", payload: boardState });
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  const task = boardState.tasks[id];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  task.title = title ?? task.title;
  task.description = description ?? task.description;
  task.updatedAt = Date.now();

  broadcast({ type: "BOARD_STATE", payload: boardState });
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete boardState.tasks[id];
  boardState.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  broadcast({ type: "BOARD_STATE", payload: boardState });
  res.json({ success: true });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  if (destinationIndex < 0 || destinationIndex > destinationColumn.taskIds.length) {
    destinationColumn.taskIds.push(taskId);
  } else {
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
  }

  broadcast({ type: "BOARD_STATE", payload: boardState });
  res.json({ success: true });
});

wss.on("connection", ws => {
  sendBoard(ws);

  ws.on("message", raw => {
    try {
      const message = JSON.parse(raw);

      if (message.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
