    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", e => {
      e.preventDefault();
      taskList.classList.add("drop-target");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-target");
    });

    taskList.addEventListener("drop", async e => {
      e.preventDefault();
      taskList.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationIndex = getDropIndex(taskList, e.clientY);

      await fetch("/api/move-task", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId: column.id,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <small>Updated: ${new Date(task.updatedAt).toLocaleString()}</small>
      `;

      taskEl.addEventListener("click", () => openEditModal(task.id));

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(taskList, mouseY) {
  const taskElements = [...taskList.querySelectorAll(".task:not(.dragging)")];

  let closest = { offset: Number.NEGATIVE_INFINITY, index: taskElements.length };

  taskElements.forEach((taskEl, index) => {
    const box = taskEl.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();

  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const columnId = taskColumnEl.value;

  if (!title) return;

  await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, columnId })
  });

  taskForm.reset();
});

function openEditModal(taskId) {
  const task = boardState.tasks[taskId];
  if (!task) return;

  editingTaskId = taskId;
  editTitle.value = task.title;
  editDescription.value = task.description || "";
  editModal.classList.remove("hidden");
}

function closeEditModal() {
  editingTaskId = null;
  editModal.classList.add("hidden");
}

saveTaskBtn.addEventListener("click", async () => {
  if (!editingTaskId) return;

  await fetch(`/api/tasks/${editingTaskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title: editTitle.value.trim(),
      description: editDescription.value.trim()
    })
  });

  closeEditModal();
});

deleteTaskBtn.addEventListener("click", async () => {
  if (!editingTaskId) return;

  await fetch(`/api/tasks/${editingTaskId}`, {
    method: "DELETE"
  });

  closeEditModal();
});

cancelEditBtn.addEventListener("click", closeEditModal);

editModal.addEventListener("click", e => {
  if (e.target === editModal) {
    closeEditModal();
  }
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchBoard();
