# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));
app.use(express.json());

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function broadcastState() {
  io.emit("board:update", boardState);
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", ({ title, description, columnId }) => {
    const taskId = uuidv4();
    const safeTitle = (title || "").trim();
    const safeDescription = (description || "").trim();

    if (!safeTitle) return;

    const task = {
      id: taskId,
      title: safeTitle,
      description: safeDescription,
      createdAt: Date.now(),
      updatedAt: Date.now()
    };

    boardState.tasks[taskId] = task;

    const column = boardState.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(taskId);
    } else {
      boardState.columns[0].taskIds.push(taskId);
    }

    broadcastState();
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    const task = boardState.tasks[taskId];
    if (!task) return;

    task.title = (title || "").trim() || task.title;
    task.description = (description || "").trim();
    task.updatedAt = Date.now();

    broadcastState();
  });

  socket.on("task:delete", ({ taskId }) => {
    if (!boardState.tasks[taskId]) return;

    delete boardState.tasks[taskId];

    boardState.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    broadcastState();
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;
    if (!boardState.tasks[taskId]) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof targetIndex === "number" && targetIndex >= 0
        ? Math.min(targetIndex, targetColumn.taskIds.length)
        : targetColumn.taskIds.length;

    targetColumn.taskIds.splice(insertIndex, 0, taskId);

    broadcastState();
  });

  socket.on("column:create", ({ title }) => {
    const safeTitle = (title || "").trim();
    if (!safeTitle) return;

    boardState.columns.push({
      id: uuidv4(),
      title: safeTitle,
      taskIds: []
    });

    broadcastState();
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

