# 6. `public/app.js`

```js
const socket = io();

let boardState = { columns: [], tasks: {} };
let editingTaskId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskColumnEl = document.getElementById("taskColumn");
const addTaskBtn = document.getElementById("addTaskBtn");
const addColumnBtn = document.getElementById("addColumnBtn");

const taskModal = document.getElementById("taskModal");
const editTaskTitle = document.getElementById("editTaskTitle");
const editTaskDescription = document.getElementById("editTaskDescription");
const saveTaskBtn = document.getElementById("saveTaskBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");
const closeModalBtn = document.getElementById("closeModalBtn");

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
  renderColumnOptions();
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const columnId = taskColumnEl.value;

  if (!title) return;

  socket.emit("task:create", { title, description, columnId });

  taskTitleEl.value = "";
  taskDescriptionEl.value = "";
});

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Enter column name:");
  if (!title || !title.trim()) return;
  socket.emit("column:create", { title: title.trim() });
});

saveTaskBtn.addEventListener("click", () => {
  if (!editingTaskId) return;

  socket.emit("task:update", {
    taskId: editingTaskId,
    title: editTaskTitle.value,
    description: editTaskDescription.value
  });

  closeModal();
});

deleteTaskBtn.addEventListener("click", () => {
  if (!editingTaskId) return;

  socket.emit("task:delete", { taskId: editingTaskId });
  closeModal();
});

closeModalBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", (e) => {
  if (e.target === taskModal) closeModal();
});

function openModal(taskId) {
  const task = boardState.tasks[taskId];
  if (!task) return;

  editingTaskId = taskId;
  editTaskTitle.value = task.title;
  editTaskDescription.value = task.description || "";
  taskModal.classList.remove("hidden");
}

function closeModal() {
  editingTaskId = null;
  taskModal.classList.add("hidden");
}

function renderColumnOptions() {
  const currentValue = taskColumnEl.value;
  taskColumnEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnEl.appendChild(option);
  });

  if ([...taskColumnEl.options].some(opt => opt.value === currentValue)) {
    taskColumnEl.value = currentValue;
  }
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = column.title;

    headerEl.appendChild(titleEl);
    columnEl.appendChild(headerEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    const taskIds = column.taskIds || [];

    taskIds.forEach((taskId, index) => {
      const dropZoneBefore = createDropZone(column.id, index);
      taskListEl.appendChild(dropZoneBefore);

      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("click", () => openModal(task.id));

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        draggedFromColumnId = null;
        taskEl.classList.remove("dragging");
        clearDropZoneHighlights();
      });

      taskListEl.appendChild(taskEl);
    });

    const dropZoneAfter = createDropZone(column.id, taskIds.length);
    taskListEl.appendChild(dropZoneAfter);

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function createDropZone(columnId, index) {
  const dropZone = document.createElement("div");
  dropZone.className = "drop-zone";
  dropZone.dataset.columnId = columnId;
  dropZone.dataset.index = index;

  dropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropZone.classList.add("active");
  });

  dropZone.addEventListener("dragleave", () => {
    dropZone.classList.remove("active");
  });

  dropZone.addEventListener("drop", (e) => {
    e.preventDefault();
    dropZone.classList.remove("active");

    if (!draggedTaskId || !draggedFromColumnId) return;

    socket.emit("task:move", {
      taskId: draggedTaskId,
      sourceColumnId: draggedFromColumnId,
      targetColumnId: columnId,
      targetIndex: Number(index)
    });
  });

  return dropZone;
}

function clearDropZoneHighlights() {
  document.querySelectorAll(".drop-zone.active").forEach((el) => {
    el.classList.remove("active");
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
