import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state
let board = {
  columns: {
    "todo": {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    "inprogress": {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    "done": {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["todo", "inprogress", "done"],
  tasks: {}
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description,
    createdAt: Date.now()
  };

  board.tasks[id] = task;
  board.columns[columnId].taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    title: title ?? board.tasks[id].title,
    description: description ?? board.tasks[id].description
  };

  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];

  for (const column of Object.values(board.columns)) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  io.emit("board:update", board);
  res.json({ success: true });
});

app.post("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  if (
    !board.tasks[taskId] ||
    !board.columns[sourceColumnId] ||
    !board.columns[destinationColumnId]
  ) {
    return res.status(400).json({ error: "Invalid move request" });
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  sourceTaskIds.splice(sourceIndex, 1);

  if (sourceColumnId === destinationColumnId) {
    sourceTaskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
  } else {
    const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
    destinationTaskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
    board.columns[destinationColumnId].taskIds = destinationTaskIds;
  }

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);
  socket.emit("board:update", board);

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

