## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");
  const [editingTask, setEditingTask] = useState(null);

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  const createTask = async () => {
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDescription,
        columnId: selectedColumn
      })
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  const updateTask = async () => {
    if (!editingTask) return;

    await fetch(`${API_URL}/api/tasks/${editingTask.id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        title: editingTask.title,
        description: editingTask.description
      })
    });

    setEditingTask(null);
  };

  const deleteTask = async (taskId) => {
    await fetch(`${API_URL}/api/tasks/${taskId}`, {
      method: "DELETE"
    });
  };

  const findTaskLocation = (taskId) => {
    for (const columnId of board.columnOrder) {
      const column = board.columns[columnId];
      const index = column.taskIds.indexOf(taskId);
      if (index !== -1) {
        return { columnId, index };
      }
    }
    return null;
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over || !board) return;
    if (active.id === over.id) return;

    const source = findTaskLocation(active.id);
    const destination = findTaskLocation(over.id);

    if (!source || !destination) return;

    await fetch(`${API_URL}/api/board/move`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        taskId: active.id,
        sourceColumnId: source.columnId,
        destinationColumnId: destination.columnId,
        sourceIndex: source.index,
        destinationIndex: destination.index
      })
    });
  };

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
      </header>

      <section className="task-form">
        <h2>Create Task</h2>
        <input
          type="text"
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <textarea
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
        />
        <select
          value={selectedColumn}
          onChange={(e) => setSelectedColumn(e.target.value)}
        >
          {columns.map((column) => (
            <option key={column.id} value={column.id}>
              {column.title}
            </option>
          ))}
        </select>
        <button onClick={createTask}>Add Task</button>
      </section>

      {editingTask && (
        <section className="task-form">
          <h2>Edit Task</h2>
          <input
            type="text"
            value={editingTask.title}
            onChange={(e) =>
              setEditingTask({ ...editingTask, title: e.target.value })
            }
          />
          <textarea
            value={editingTask.description}
            onChange={(e) =>
              setEditingTask({ ...editingTask, description: e.target.value })
            }
          />
          <div className="edit-actions">
            <button onClick={updateTask}>Save</button>
            <button onClick={() => setEditingTask(null)}>Cancel</button>
          </div>
        </section>
      )}

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => {
            const tasks = column.taskIds.map((taskId) => board.tasks[taskId]).filter(Boolean);

            return (
              <Column
                key={column.id}
                column={column}
                tasks={tasks}
                onEdit={setEditingTask}
                onDelete={deleteTask}
              />
            );
          })}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onEdit, onDelete }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} onEdit={onEdit} onDelete={onDelete} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onEdit, onDelete }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
      <div className="task-actions">
        <button onClick={() => onEdit(task)}>Edit</button>
        <button onClick={() => onDelete(task.id)}>Delete</button>
      </div>
    </div>
  );
}

export default App;
```

