# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory demo data
 * Replace with a database in production.
 */
let state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "col-1",
          title: "Backlog",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "col-2",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "col-3",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes",
          assignee: "Alice",
          priority: "High"
        },
        "task-2": {
          id: "task-2",
          title: "Collect brand assets",
          description: "Gather logos, colors, and typography",
          assignee: "Bob",
          priority: "Medium"
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement responsive landing page",
          assignee: "Charlie",
          priority: "High"
        }
      }
    }
  ]
};

function getProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.get("/api/projects/:projectId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });
  res.json(project);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const newProject = {
    id: uuidv4(),
    name,
    columns: [
      { id: uuidv4(), title: "Backlog", taskIds: [] },
      { id: uuidv4(), title: "In Progress", taskIds: [] },
      { id: uuidv4(), title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  state.projects.push(newProject);
  io.emit("project:created", newProject);
  res.status(201).json(newProject);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { title, description = "", assignee = "", priority = "Low", columnId } = req.body;
  const taskId = uuidv4();

  const task = {
    id: taskId,
    title,
    description,
    assignee,
    priority
  };

  project.tasks[taskId] = task;

  const targetColumn =
    project.columns.find((c) => c.id === columnId) || project.columns[0];

  targetColumn.taskIds.push(taskId);

  io.emit("task:created", {
    projectId: project.id,
    task,
    columnId: targetColumn.id
  });

  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const task = project.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, assignee, priority } = req.body;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (assignee !== undefined) task.assignee = assignee;
  if (priority !== undefined) task.priority = priority;

  io.emit("task:updated", {
    projectId: project.id,
    task
  });

  res.json(task);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  io.emit("task:deleted", {
    projectId: project.id,
    taskId
  });

  res.json({ success: true });
});

app.put("/api/projects/:projectId/reorder", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column IDs" });
  }

  const [movedTaskId] = sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, movedTaskId);

  io.emit("task:moved", {
    projectId: project.id,
    sourceColumnId,
    destinationColumnId,
    sourceIndex,
    destinationIndex,
    taskId: movedTaskId
  });

  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.on("join:project", (projectId) => {
    socket.join(projectId);
  });

  socket.on("cursor:move", (payload) => {
    socket.broadcast.emit("cursor:update", {
      socketId: socket.id,
      ...payload
    });
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
    socket.broadcast.emit("user:disconnected", { socketId: socket.id });
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

