# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let projects = [];
let currentProjectId = null;
let remoteCursors = {};

const boardEl = document.getElementById("board");
const projectSelectEl = document.getElementById("projectSelect");
const projectNameInputEl = document.getElementById("projectNameInput");
const createProjectBtnEl = document.getElementById("createProjectBtn");

const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskAssigneeEl = document.getElementById("taskAssignee");
const taskPriorityEl = document.getElementById("taskPriority");
const taskColumnEl = document.getElementById("taskColumn");
const addTaskBtnEl = document.getElementById("addTaskBtn");
const presenceLayerEl = document.getElementById("presenceLayer");

async function fetchProjects() {
  const res = await fetch(`${API_URL}/projects`);
  projects = await res.json();

  renderProjectSelector();

  if (!currentProjectId && projects.length > 0) {
    currentProjectId = projects[0].id;
    socket.emit("join:project", currentProjectId);
  }

  renderCurrentProject();
}

function getCurrentProject() {
  return projects.find((p) => p.id === currentProjectId);
}

function renderProjectSelector() {
  projectSelectEl.innerHTML = "";
  projects.forEach((project) => {
    const option = document.createElement("option");
    option.value = project.id;
    option.textContent = project.name;
    if (project.id === currentProjectId) option.selected = true;
    projectSelectEl.appendChild(option);
  });
}

function renderTaskColumnOptions(project) {
  taskColumnEl.innerHTML = "";
  project.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnEl.appendChild(option);
  });
}

function renderCurrentProject() {
  const project = getCurrentProject();
  if (!project) {
    boardEl.innerHTML = "<p>No project selected.</p>";
    return;
  }

  renderTaskColumnOptions(project);
  boardEl.innerHTML = "";

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      const draggingEl = document.querySelector(".dragging");
      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      if (!draggingEl) return;

      if (afterElement == null) {
        taskListEl.appendChild(draggingEl);
      } else {
        taskListEl.insertBefore(draggingEl, afterElement);
      }
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("text/taskId");
      const sourceColumnId = e.dataTransfer.getData("text/sourceColumnId");
      const destinationColumnId = column.id;

      const destinationTaskEls = [...taskListEl.querySelectorAll(".task-card")];
      const destinationIndex = destinationTaskEls.findIndex((el) => el.dataset.taskId === taskId);

      const project = getCurrentProject();
      const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
      const sourceIndex = sourceColumn.taskIds.findIndex((id) => id === taskId);

      await fetch(`${API_URL}/projects/${project.id}/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sourceColumnId,
          destinationColumnId,
          sourceIndex,
          destinationIndex: destinationIndex === -1 ? destinationTaskEls.length - 1 : destinationIndex
        })
      });
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = `task-card priority-${task.priority}`;
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div>${escapeHtml(task.description)}</div>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
        <div class="task-meta">Priority: ${escapeHtml(task.priority)}</div>
        <div class="task-actions">
          <button data-action="edit">Edit</button>
          <button data-action="delete">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        taskEl.classList.add("dragging");
        e.dataTransfer.setData("text/taskId", task.id);
        e.dataTransfer.setData("text/sourceColumnId", column.id);
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector('[data-action="edit"]').addEventListener("click", async () => {
        const newTitle = prompt("Task title:", task.title);
        if (newTitle === null) return;

        const newDescription = prompt("Task description:", task.description);
        if (newDescription === null) return;

        const newAssignee = prompt("Assignee:", task.assignee);
        if (newAssignee === null) return;

        const newPriority = prompt("Priority (Low, Medium, High):", task.priority);
        if (newPriority === null) return;

        await fetch(`${API_URL}/projects/${project.id}/tasks/${task.id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            title: newTitle,
            description: newDescription,
            assignee: newAssignee,
            priority: newPriority
          })
        });
      });

      taskEl.querySelector('[data-action="delete"]').addEventListener("click", async () => {
        await fetch(`${API_URL}/projects/${project.id}/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task-card:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

createProjectBtnEl.addEventListener("click", async () => {
  const name = projectNameInputEl.value.trim();
  if (!name) return;

  const res = await fetch(`${API_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  currentProjectId = project.id;
  projectNameInputEl.value = "";
  await fetchProjects();
});

projectSelectEl.addEventListener("change", () => {
  currentProjectId = projectSelectEl.value;
  socket.emit("join:project", currentProjectId);
  renderCurrentProject();
});

addTaskBtnEl.addEventListener("click", async () => {
  const project = getCurrentProject();
  if (!project) return;

  const title = taskTitleEl.value.trim();
  if (!title) return;

  await fetch(`${API_URL}/projects/${project.id}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title,
      description: taskDescriptionEl.value.trim(),
      assignee: taskAssigneeEl.value.trim(),
      priority: taskPriorityEl.value,
      columnId: taskColumnEl.value
    })
  });

  taskTitleEl.value = "";
  taskDescriptionEl.value = "";
  taskAssigneeEl.value = "";
  taskPriorityEl.value = "Low";
});

socket.on("project:created", (project) => {
  projects.push(project);
  renderProjectSelector();
  renderCurrentProject();
});

socket.on("task:created", ({ projectId, task, columnId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  project.tasks[task.id] = task;
  const column = project.columns.find((c) => c.id === columnId);
  if (column) column.taskIds.push(task.id);

  if (projectId === currentProjectId) renderCurrentProject();
});

socket.on("task:updated", ({ projectId, task }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  project.tasks[task.id] = task;
  if (projectId === currentProjectId) renderCurrentProject();
});

socket.on("task:deleted", ({ projectId, taskId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  delete project.tasks[taskId];
  project.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  if (projectId === currentProjectId) renderCurrentProject();
});

socket.on("task:moved", ({ projectId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);
  if (!sourceColumn || !destinationColumn) return;

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  if (projectId === currentProjectId) renderCurrentProject();
});

document.addEventListener("mousemove", (e) => {
  socket.emit("cursor:move", {
    x: e.clientX,
    y: e.clientY
  });
});

socket.on("cursor:update", ({ socketId, x, y }) => {
  let cursorEl = remoteCursors[socketId];
  if (!cursorEl) {
    cursorEl = document.createElement("div");
    cursorEl.className = "remote-cursor";
    cursorEl.textContent = `User ${socketId.slice(0, 4)}`;
    presenceLayerEl.appendChild(cursorEl);
    remoteCursors[socketId] = cursorEl;
  }

  cursorEl.style.left = `${x}px`;
  cursorEl.style.top = `${y}px`;
});

socket.on("user:disconnected", ({ socketId }) => {
  const cursorEl = remoteCursors[socketId];
  if (cursorEl) {
    cursorEl.remove();
    delete remoteCursors[socketId];
  }
});

fetchProjects();
```

