## `server/server.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["1", "2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["todo", "doing", "done"],
  tasks: {
    "1": { id: "1", title: "Set up project repo", description: "Initialize GitHub repository" },
    "2": { id: "2", title: "Design UI mockups", description: "Create wireframes for dashboard" },
    "3": { id: "3", title: "Build auth flow", description: "Implement login and registration" }
  }
};

app.get("/board", (req, res) => {
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", ({ columnId, task }) => {
    const id = Date.now().toString();
    const newTask = {
      id,
      title: task.title || "Untitled Task",
      description: task.description || ""
    };

    board.tasks[id] = newTask;
    board.columns[columnId].taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:update", ({ taskId, updates }) => {
    if (!board.tasks[taskId]) return;
    board.tasks[taskId] = {
      ...board.tasks[taskId],
      ...updates
    };
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
    if (!board.columns[sourceColumnId] || !board.columns[destinationColumnId]) return;

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    sourceTaskIds.splice(sourceIndex, 1);

    if (sourceColumnId === destinationColumnId) {
      sourceTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
    } else {
      const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
      destinationTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
      board.columns[destinationColumnId].taskIds = destinationTaskIds;
    }

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!board.tasks[taskId] || !board.columns[columnId]) return;

    delete board.tasks[taskId];
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(id => id !== taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

