## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function App() {
  const [board, setBoard] = useState(null);
  const [selectedTask, setSelectedTask] = useState(null);
  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch("http://localhost:4000/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  const findTaskLocation = (taskId) => {
    for (const columnId of board.columnOrder) {
      const column = board.columns[columnId];
      const index = column.taskIds.indexOf(taskId);
      if (index !== -1) {
        return { columnId, index };
      }
    }
    return null;
  };

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!over || !board) return;

    const taskId = active.id;
    const overId = over.id;

    const source = findTaskLocation(taskId);
    if (!source) return;

    let destination = findTaskLocation(overId);

    if (!destination) {
      if (board.columns[overId]) {
        destination = {
          columnId: overId,
          index: board.columns[overId].taskIds.length
        };
      } else {
        return;
      }
    }

    if (
      source.columnId === destination.columnId &&
      source.index === destination.index
    ) {
      return;
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId: source.columnId,
      destinationColumnId: destination.columnId,
      sourceIndex: source.index,
      destinationIndex: destination.index
    });
  };

  const createTask = (columnId) => {
    const title = prompt("Task title:");
    if (!title) return;
    const description = prompt("Task description:") || "";

    socket.emit("task:create", {
      columnId,
      task: { title, description }
    });
  };

  const updateTask = (task) => {
    const title = prompt("Edit title:", task.title);
    if (title === null) return;
    const description = prompt("Edit description:", task.description);
    if (description === null) return;

    socket.emit("task:update", {
      taskId: task.id,
      updates: { title, description }
    });
  };

  const deleteTask = (taskId, columnId) => {
    if (!confirm("Delete this task?")) return;
    socket.emit("task:delete", { taskId, columnId });
  };

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <h1>Project Management Board</h1>
      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.taskIds.map((taskId) => board.tasks[taskId])}
              onCreateTask={() => createTask(column.id)}
              onEditTask={updateTask}
              onDeleteTask={deleteTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onCreateTask, onEditTask, onDeleteTask }) {
  return (
    <div className="column" id={column.id}>
      <div className="column-header">
        <h2>{column.title}</h2>
        <button onClick={onCreateTask}>+ Add</button>
      </div>

      <SortableContext items={tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              columnId={column.id}
              onEdit={() => onEditTask(task)}
              onDelete={() => onDeleteTask(task.id, column.id)}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onEdit, onDelete }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h3>{task.title}</h3>
      <p>{task.description}</p>
      <div className="task-actions">
        <button onClick={onEdit}>Edit</button>
        <button className="danger" onClick={onDelete}>Delete</button>
      </div>
    </div>
  );
}

export default App;
```

