# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));
app.use(express.json());

const boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "inprogress", title: "In Progress", taskIds: [] },
    { id: "review", title: "Review", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

function broadcastBoard() {
  io.emit("board:update", boardState);
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", ({ columnId, title, description }) => {
    const column = boardState.columns.find((c) => c.id === columnId);
    if (!column || !title?.trim()) return;

    const id = uuidv4();
    boardState.tasks[id] = {
      id,
      title: title.trim(),
      description: description?.trim() || "",
      createdAt: Date.now()
    };
    column.taskIds.push(id);

    broadcastBoard();
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    const task = boardState.tasks[taskId];
    if (!task) return;

    task.title = title?.trim() || task.title;
    task.description = description?.trim() || "";
    broadcastBoard();
  });

  socket.on("task:delete", ({ taskId }) => {
    if (!boardState.tasks[taskId]) return;

    delete boardState.tasks[taskId];
    boardState.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    broadcastBoard();
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn || !boardState.tasks[taskId]) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex = Math.max(0, Math.min(targetIndex, targetColumn.taskIds.length));
    targetColumn.taskIds.splice(safeIndex, 0, taskId);

    broadcastBoard();
  });

  socket.on("column:create", ({ title }) => {
    if (!title?.trim()) return;

    boardState.columns.push({
      id: uuidv4(),
      title: title.trim(),
      taskIds: []
    });

    broadcastBoard();
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

