# 5. `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const addColumnBtn = document.getElementById("add-column-btn");

const modal = document.getElementById("modal");
const modalTitle = document.getElementById("modal-title");
const taskTitleInput = document.getElementById("task-title-input");
const taskDescInput = document.getElementById("task-desc-input");
const saveTaskBtn = document.getElementById("save-task-btn");
const deleteTaskBtn = document.getElementById("delete-task-btn");
const cancelTaskBtn = document.getElementById("cancel-task-btn");

let currentBoard = null;
let editingTaskId = null;
let editingColumnId = null;

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard(board);
});

function renderBoard(board) {
  boardEl.innerHTML = "";

  board.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = column.title;

    headerEl.appendChild(titleEl);
    columnEl.appendChild(headerEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      const dragging = document.querySelector(".dragging");
      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      if (!dragging) return;

      if (afterElement == null) {
        taskListEl.appendChild(dragging);
      } else {
        taskListEl.insertBefore(dragging, afterElement);
      }
    });

    taskListEl.addEventListener("drop", () => {
      const dragging = document.querySelector(".dragging");
      if (!dragging) return;

      const taskId = dragging.dataset.taskId;
      const sourceColumnId = dragging.dataset.columnId;
      const targetColumnId = taskListEl.dataset.columnId;
      const taskElements = [...taskListEl.querySelectorAll(".task")];
      const targetIndex = taskElements.findIndex((el) => el.dataset.taskId === taskId);

      socket.emit("task:move", {
        taskId,
        sourceColumnId,
        targetColumnId,
        targetIndex: targetIndex === -1 ? taskElements.length : targetIndex
      });
    });

    column.taskIds.forEach((taskId) => {
      const task = board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description)}</p>
      `;

      taskEl.addEventListener("click", () => openEditModal(task.id, column.id));

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    const addTaskBtn = document.createElement("button");
    addTaskBtn.className = "add-task-btn";
    addTaskBtn.textContent = "+ Add Task";
    addTaskBtn.addEventListener("click", () => openCreateModal(column.id));

    columnEl.appendChild(taskListEl);
    columnEl.appendChild(addTaskBtn);
    boardEl.appendChild(columnEl);
  });
}

function openCreateModal(columnId) {
  editingTaskId = null;
  editingColumnId = columnId;
  modalTitle.textContent = "Create Task";
  taskTitleInput.value = "";
  taskDescInput.value = "";
  deleteTaskBtn.classList.add("hidden");
  modal.classList.remove("hidden");
}

function openEditModal(taskId, columnId) {
  const task = currentBoard.tasks[taskId];
  if (!task) return;

  editingTaskId = taskId;
  editingColumnId = columnId;
  modalTitle.textContent = "Edit Task";
  taskTitleInput.value = task.title;
  taskDescInput.value = task.description;
  deleteTaskBtn.classList.remove("hidden");
  modal.classList.remove("hidden");
}

function closeModal() {
  modal.classList.add("hidden");
}

saveTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();

  if (!title) {
    alert("Task title is required.");
    return;
  }

  if (editingTaskId) {
    socket.emit("task:update", {
      taskId: editingTaskId,
      title,
      description
    });
  } else {
    socket.emit("task:create", {
      columnId: editingColumnId,
      title,
      description
    });
  }

  closeModal();
});

deleteTaskBtn.addEventListener("click", () => {
  if (!editingTaskId) return;
  socket.emit("task:delete", { taskId: editingTaskId });
  closeModal();
});

cancelTaskBtn.addEventListener("click", closeModal);

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Enter column name:");
  if (!title || !title.trim()) return;
  socket.emit("column:create", { title: title.trim() });
});

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
