const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "Todo",
      taskIds: ["task-1", "task-2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
