  columnOrder: ["todo", "inprogress", "done"],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project",
      description: "Initialize frontend and backend"
    },
    "task-2": {
      id: "task-2",
      title: "Build board UI",
      description: "Create Kanban columns and cards"
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", (task) => {
    const newTask = {
      id: task.id,
      title: task.title,
      description: task.description || ""
    };

    boardState.tasks[newTask.id] = newTask;
    boardState.columns[task.columnId].taskIds.push(newTask.id);

    io.emit("board:update", boardState);
  });

  socket.on("board:update", (newState) => {
    boardState = newState;
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
