# 6. Main app

## `client/src/App.tsx`

```tsx
import { useEffect, useState } from "react";
import { socket } from "./socket";
import { BoardState } from "./types";
import Board from "./components/Board";

const emptyBoard: BoardState = {
  tasks: {},
  columns: {},
  columnOrder: []
};

function App() {
  const [board, setBoard] = useState<BoardState>(emptyBoard);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    socket.on("board:init", (state: BoardState) => {
      setBoard(state);
    });

    socket.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:init");
      socket.off("board:update");
    };
  }, []);

  const createTask = () => {
    if (!newTaskTitle.trim()) return;

    const task = {
      id: `task-${Date.now()}`,
      title: newTaskTitle,
      description: "",
      columnId: "todo"
    };

    socket.emit("task:create", task);
    setNewTaskTitle("");
  };

  const updateBoard = (newBoard: BoardState) => {
    setBoard(newBoard);
    socket.emit("board:update", newBoard);
  };

  return (
    <div style={{ padding: 20, fontFamily: "Arial, sans-serif" }}>
      <h1>Project Management Board</h1>

      <div style={{ marginBottom: 20 }}>
        <input
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="New task title"
          style={{ padding: 8, width: 240, marginRight: 8 }}
        />
        <button onClick={createTask} style={{ padding: "8px 12px" }}>
          Add Task
        </button>
      </div>

      <Board board={board} onBoardChange={updateBoard} />
    </div>
  );
}

export default App;
```

