# 7. Board with drag-and-drop

## `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { BoardState } from "../types";
import Column from "./Column";

type Props = {
  board: BoardState;
  onBoardChange: (board: BoardState) => void;
};

function Board({ board, onBoardChange }: Props) {
  const sensors = useSensors(useSensor(PointerSensor));

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (!over || active.id === over.id) return;

    const sourceColumn = Object.values(board.columns).find((column) =>
      column.taskIds.includes(String(active.id))
    );

    const destinationColumn = Object.values(board.columns).find((column) =>
      column.taskIds.includes(String(over.id))
    );

    if (!sourceColumn || !destinationColumn) return;

    const sourceTaskIndex = sourceColumn.taskIds.indexOf(String(active.id));
    const destinationTaskIndex = destinationColumn.taskIds.indexOf(String(over.id));

    const newBoard = structuredClone(board);

    if (sourceColumn.id === destinationColumn.id) {
      const taskIds = [...sourceColumn.taskIds];
      taskIds.splice(sourceTaskIndex, 1);
      taskIds.splice(destinationTaskIndex, 0, String(active.id));
      newBoard.columns[sourceColumn.id].taskIds = taskIds;
    } else {
      const sourceTaskIds = [...sourceColumn.taskIds];
      sourceTaskIds.splice(sourceTaskIndex, 1);

      const destinationTaskIds = [...destinationColumn.taskIds];
      destinationTaskIds.splice(destinationTaskIndex, 0, String(active.id));

      newBoard.columns[sourceColumn.id].taskIds = sourceTaskIds;
      newBoard.columns[destinationColumn.id].taskIds = destinationTaskIds;
    }

    onBoardChange(newBoard);
  };

  return (
    <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return <Column key={column.id} column={column} tasks={tasks} />;
        })}
      </div>
    </DndContext>
  );
}

export default Board;
```

