import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project repo",
      description: "Initialize frontend and backend structure"
    },
    "task-2": {
      id: "task-2",
      title: "Design board UI",
      description: "Create Kanban board layout"
    },
    "task-3": {
      id: "task-3",
      title: "Implement WebSocket sync",
      description: "Broadcast board changes in real time"
    }
  },
  columnOrder: ["todo", "inprogress", "done"]
};

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/tasks", (req, res) => {
  const { columnId, title, description } = req.body;

  if (!columnId || !title) {
    return res.status(400).json({ error: "columnId and title are required" });
  }

  const taskId = `task-${Date.now()}`;
  board.tasks[taskId] = {
    id: taskId,
    title,
    description: description || ""
  };
  board.columns[columnId].taskIds.push(taskId);

  io.emit("board:update", board);
  res.status(201).json(board);
});

app.post("/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  if (!taskId || !sourceColumnId || !destinationColumnId || destinationIndex == null) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  const destTaskIds =
    sourceColumnId === destinationColumnId
      ? sourceTaskIds
      : [...board.columns[destinationColumnId].taskIds];

  const sourceIndex = sourceTaskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(404).json({ error: "Task not found in source column" });
  }

  sourceTaskIds.splice(sourceIndex, 1);
  destTaskIds.splice(destinationIndex, 0, taskId);

  board.columns[sourceColumnId].taskIds =
    sourceColumnId === destinationColumnId ? destTaskIds : sourceTaskIds;

  board.columns[destinationColumnId].taskIds = destTaskIds;

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", ({ columnId, title, description }) => {
    if (!columnId || !title) return;

    const taskId = `task-${Date.now()}`;
    board.tasks[taskId] = {
      id: taskId,
      title,
      description: description || ""
    };
    board.columns[columnId].taskIds.push(taskId);

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    if (!taskId || !sourceColumnId || !destinationColumnId || destinationIndex == null) return;

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    const destTaskIds =
      sourceColumnId === destinationColumnId
        ? sourceTaskIds
        : [...board.columns[destinationColumnId].taskIds];

    const sourceIndex = sourceTaskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceTaskIds.splice(sourceIndex, 1);
    destTaskIds.splice(destinationIndex, 0, taskId);

    board.columns[sourceColumnId].taskIds =
      sourceColumnId === destinationColumnId ? destTaskIds : sourceTaskIds;

    board.columns[destinationColumnId].taskIds = destTaskIds;

    io.emit("board:update", board);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
