```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import Board from "./components/Board";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch("http://localhost:4000/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  function findTaskLocation(taskId) {
    for (const columnId of board.columnOrder) {
      const taskIds = board.columns[columnId].taskIds;
      const index = taskIds.indexOf(taskId);
      if (index !== -1) {
        return { columnId, index };
      }
    }
    return null;
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const taskId = active.id;
    const overId = over.id;

    const source = findTaskLocation(taskId);
    if (!source) return;

    let destinationColumnId = null;
    let destinationIndex = 0;

    if (board.columns[overId]) {
      destinationColumnId = overId;
      destinationIndex = board.columns[overId].taskIds.length;
    } else {
      const destination = findTaskLocation(overId);
      if (!destination) return;
      destinationColumnId = destination.columnId;
      destinationIndex = destination.index;
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId: source.columnId,
      destinationColumnId,
      destinationIndex
    });
  }

  function createTask(columnId) {
    const title = window.prompt("Task title:");
    if (!title) return;

    const description = window.prompt("Task description:") || "";

    socket.emit("task:create", {
      columnId,
      title,
      description
    });
  }

  if (!board) {
    return <div className="app-shell">Loading board...</div>;
  }

  return (
    <div className="app-shell">
      <header className="app-header">
        <h1>Project Management Board</h1>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <Board board={board} columns={columns} onCreateTask={createTask} />
      </DndContext>
    </div>
  );
}
```

