## `server/src/store.ts`

```ts
import { v4 as uuid } from "uuid";
import { AppState, Board, Task } from "./types";

const boardId = "board-1";

const initialBoard: Board = {
  id: boardId,
  title: "Team Project Board",
  columnOrder: ["todo", "inprogress", "done"],
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {}
};

const state: AppState = {
  boards: {
    [boardId]: initialBoard
  }
};

function getBoard(boardId: string) {
  const board = state.boards[boardId];
  if (!board) throw new Error("Board not found");
  return board;
}

export function getState() {
  return state;
}

export function createTask(boardId: string, columnId: string, title: string, description?: string) {
  const board = getBoard(boardId);
  const column = board.columns[columnId];
  if (!column) throw new Error("Column not found");

  const task: Task = {
    id: uuid(),
    title,
    description
  };

  board.tasks[task.id] = task;
  column.taskIds.push(task.id);

  return board;
}

export function moveTask(
  boardId: string,
  sourceColumnId: string,
  destinationColumnId: string,
  sourceIndex: number,
  destinationIndex: number
) {
  const board = getBoard(boardId);
  const source = board.columns[sourceColumnId];
  const destination = board.columns[destinationColumnId];

  if (!source || !destination) throw new Error("Invalid column");

  const [movedTaskId] = source.taskIds.splice(sourceIndex, 1);
  destination.taskIds.splice(destinationIndex, 0, movedTaskId);

  return board;
}

export function reorderTask(boardId: string, columnId: string, sourceIndex: number, destinationIndex: number) {
  const board = getBoard(boardId);
  const column = board.columns[columnId];
  if (!column) throw new Error("Column not found");

  const [movedTaskId] = column.taskIds.splice(sourceIndex, 1);
  column.taskIds.splice(destinationIndex, 0, movedTaskId);

  return board;
}
```

## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { createTask, getState, moveTask, reorderTask } from "./store";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/state", (_req, res) => {
  res.json(getState());
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("state:update", getState());

  socket.on("task:create", (payload) => {
    try {
      const { boardId, columnId, title, description } = payload;
      const board = createTask(boardId, columnId, title, description);
      io.emit("board:update", board);
    } catch (error) {
      socket.emit("error:message", { message: (error as Error).message });
    }
  });

  socket.on("task:move", (payload) => {
    try {
      const {
        boardId,
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex
      } = payload;

      const board =
        sourceColumnId === destinationColumnId
          ? reorderTask(boardId, sourceColumnId, sourceIndex, destinationIndex)
          : moveTask(boardId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex);

      io.emit("board:update", board);
    } catch (error) {
      socket.emit("error:message", { message: (error as Error).message });
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

