## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { AppState, Board } from "./types";
import { socket } from "./socket";
import BoardView from "./components/Board";

const BOARD_ID = "board-1";

export default function App() {
  const [state, setState] = useState<AppState | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");

  useEffect(() => {
    fetch("http://localhost:4000/api/state")
      .then((res) => res.json())
      .then((data) => setState(data));

    socket.on("state:update", (data: AppState) => setState(data));
    socket.on("board:update", (board: Board) => {
      setState((prev) => {
        if (!prev) return { boards: { [board.id]: board } };
        return {
          ...prev,
          boards: {
            ...prev.boards,
            [board.id]: board
          }
        };
      });
    });

    return () => {
      socket.off("state:update");
      socket.off("board:update");
    };
  }, []);

  const board = useMemo(() => state?.boards[BOARD_ID], [state]);

  const sensors = useSensors(useSensor(PointerSensor));

  function handleCreateTask() {
    if (!newTaskTitle.trim()) return;
    socket.emit("task:create", {
      boardId: BOARD_ID,
      columnId: selectedColumn,
      title: newTaskTitle
    });
    setNewTaskTitle("");
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over || !board) return;
    if (active.id === over.id) return;

    const source = findTaskLocation(board, String(active.id));
    const destination = findTaskLocation(board, String(over.id));

    if (!source || !destination) return;

    socket.emit("task:move", {
      boardId: BOARD_ID,
      sourceColumnId: source.columnId,
      destinationColumnId: destination.columnId,
      sourceIndex: source.index,
      destinationIndex: destination.index
    });
  }

  if (!board) return <div className="app">Loading...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>{board.title}</h1>
        <div className="task-form">
          <select value={selectedColumn} onChange={(e) => setSelectedColumn(e.target.value)}>
            {board.columnOrder.map((columnId) => (
              <option key={columnId} value={columnId}>
                {board.columns[columnId].title}
              </option>
            ))}
          </select>
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={handleCreateTask}>Add Task</button>
        </div>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <BoardView board={board} />
      </DndContext>
    </div>
  );
}

function findTaskLocation(board: Board, taskId: string) {
  for (const columnId of board.columnOrder) {
    const index = board.columns[columnId].taskIds.indexOf(taskId);
    if (index !== -1) {
      return { columnId, index };
    }
  }
  return null;
}
```

