## `server.js`

```js
const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

const boardState = {
  columns: {
    todo: {
      id: 'todo',
      title: 'Todo',
      taskIds: []
    },
    inprogress: {
      id: 'inprogress',
      title: 'In Progress',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {}
};

function createTask(title) {
  const id = `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  return {
    id,
    title,
    description: '',
    createdAt: new Date().toISOString()
  };
}

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

function sendState(ws) {
  ws.send(JSON.stringify({
    type: 'STATE_SYNC',
    payload: boardState
  }));
}

function removeTaskFromAllColumns(taskId) {
  Object.values(boardState.columns).forEach(column => {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  });
}

wss.on('connection', ws => {
  sendState(ws);

  ws.on('message', raw => {
    let message;
    try {
      message = JSON.parse(raw);
    } catch (err) {
      ws.send(JSON.stringify({
        type: 'ERROR',
        payload: { message: 'Invalid JSON' }
      }));
      return;
    }

    const { type, payload } = message;

    switch (type) {
      case 'CREATE_TASK': {
        const { title, columnId = 'todo' } = payload || {};
        if (!title || !boardState.columns[columnId]) return;

        const task = createTask(title);
        boardState.tasks[task.id] = task;
        boardState.columns[columnId].taskIds.push(task.id);

        broadcast({
          type: 'STATE_SYNC',
          payload: boardState
        });
        break;
      }

      case 'UPDATE_TASK': {
        const { taskId, title, description } = payload || {};
        const task = boardState.tasks[taskId];
        if (!task) return;

        if (typeof title === 'string') task.title = title;
        if (typeof description === 'string') task.description = description;

        broadcast({
          type: 'STATE_SYNC',
          payload: boardState
        });
        break;
      }

      case 'DELETE_TASK': {
        const { taskId } = payload || {};
        if (!boardState.tasks[taskId]) return;

        delete boardState.tasks[taskId];
        removeTaskFromAllColumns(taskId);

        broadcast({
          type: 'STATE_SYNC',
          payload: boardState
        });
        break;
      }

      case 'MOVE_TASK': {
        const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload || {};
        if (
          !taskId ||
          !boardState.tasks[taskId] ||
          !boardState.columns[sourceColumnId] ||
          !boardState.columns[destinationColumnId]
        ) {
          return;
        }

        const sourceColumn = boardState.columns[sourceColumnId];
        const destinationColumn = boardState.columns[destinationColumnId];

        sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

        const insertIndex =
          typeof destinationIndex === 'number'
            ? Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length))
            : destinationColumn.taskIds.length;

        destinationColumn.taskIds.splice(insertIndex, 0, taskId);

        broadcast({
          type: 'STATE_SYNC',
          payload: boardState
        });
        break;
      }

      case 'REORDER_TASK': {
        const { columnId, taskId, destinationIndex } = payload || {};
        const column = boardState.columns[columnId];
        if (!column || !boardState.tasks[taskId]) return;

        column.taskIds = column.taskIds.filter(id => id !== taskId);

        const insertIndex =
          typeof destinationIndex === 'number'
            ? Math.max(0, Math.min(destinationIndex, column.taskIds.length))
            : column.taskIds.length;

        column.taskIds.splice(insertIndex, 0, taskId);

        broadcast({
          type: 'STATE_SYNC',
          payload: boardState
        });
        break;
      }

      default:
        ws.send(JSON.stringify({
          type: 'ERROR',
          payload: { message: `Unknown message type: ${type}` }
        }));
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
