## `public/app.js`

```js
const boardEl = document.getElementById('board');
const createTaskBtn = document.getElementById('create-task-btn');
const newTaskTitleEl = document.getElementById('new-task-title');
const newTaskColumnEl = document.getElementById('new-task-column');
const connectionStatusEl = document.getElementById('connection-status');

const columnTemplate = document.getElementById('column-template');
const taskTemplate = document.getElementById('task-template');

let state = null;
let socket = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

function connectWebSocket() {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  socket = new WebSocket(`${protocol}//${window.location.host}`);

  socket.addEventListener('open', () => {
    setConnectionStatus('Connected', 'connected');
  });

  socket.addEventListener('close', () => {
    setConnectionStatus('Disconnected', 'disconnected');
    setTimeout(connectWebSocket, 1500);
  });

  socket.addEventListener('error', () => {
    setConnectionStatus('Disconnected', 'disconnected');
  });

  socket.addEventListener('message', event => {
    const message = JSON.parse(event.data);

    if (message.type === 'STATE_SYNC') {
      state = message.payload;
      renderBoard();
    }
  });
}

function setConnectionStatus(text, className) {
  connectionStatusEl.textContent = text;
  connectionStatusEl.className = `status ${className}`;
}

function sendMessage(type, payload) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  socket.send(JSON.stringify({ type, payload }));
}

function renderBoard() {
  if (!state) return;
  boardEl.innerHTML = '';

  Object.values(state.columns).forEach(column => {
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleEl = columnNode.querySelector('.column-title');
    const taskListEl = columnNode.querySelector('.task-list');

    columnNode.dataset.columnId = column.id;
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    taskListEl.addEventListener('dragover', event => {
      event.preventDefault();
      const afterElement = getDragAfterElement(taskListEl, event.clientY);
      const draggingEl = document.querySelector('.task-card.dragging');
      if (!draggingEl) return;

      if (afterElement == null) {
        taskListEl.appendChild(draggingEl);
      } else {
        taskListEl.insertBefore(draggingEl, afterElement);
      }
    });

    taskListEl.addEventListener('drop', event => {
      event.preventDefault();
      const draggingEl = document.querySelector('.task-card.dragging');
      if (!draggingEl) return;

      const taskId = draggingEl.dataset.taskId;
      const destinationColumnId = column.id;
      const taskElements = [...taskListEl.querySelectorAll('.task-card')];
      const destinationIndex = taskElements.findIndex(el => el.dataset.taskId === taskId);

      if (draggedFromColumnId === destinationColumnId) {
        sendMessage('REORDER_TASK', {
          columnId: destinationColumnId,
          taskId,
          destinationIndex
        });
      } else {
        sendMessage('MOVE_TASK', {
          taskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        });
      }
    });

    column.taskIds.forEach(taskId => {
      const task = state.tasks[taskId];
      if (!task) return;

      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      const titleInput = taskNode.querySelector('.task-title-input');
      const deleteBtn = taskNode.querySelector('.delete-task-btn');

      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;
      titleInput.value = task.title;

      taskNode.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add('dragging');
      });

      taskNode.addEventListener('dragend', () => {
        taskNode.classList.remove('dragging');
      });

      titleInput.addEventListener('change', () => {
        sendMessage('UPDATE_TASK', {
          taskId: task.id,
          title: titleInput.value
        });
      });

      deleteBtn.addEventListener('click', () => {
        sendMessage('DELETE_TASK', {
          taskId: task.id
        });
      });

      taskListEl.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.task-card:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

createTaskBtn.addEventListener('click', () => {
  const title = newTaskTitleEl.value.trim();
  const columnId = newTaskColumnEl.value;

  if (!title) return;

  sendMessage('CREATE_TASK', { title, columnId });
  newTaskTitleEl.value = '';
});

newTaskTitleEl.addEventListener('keydown', event => {
  if (event.key === 'Enter') {
    createTaskBtn.click();
  }
});

setConnectionStatus('Connecting...', 'connecting');
connectWebSocket();
