import express from 'express';
import http from 'http';
import cors from 'cors';
import { Server } from 'socket.io';

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: '*'
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    doing: {
      id: 'doing',
      title: 'In Progress',
      taskIds: ['task-3']
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  columnOrder: ['todo', 'doing', 'done'],
  tasks: {
    'task-1': {
      id: 'task-1',
      title: 'Set up project repo',
      description: 'Initialize frontend and backend structure'
    },
    'task-2': {
      id: 'task-2',
      title: 'Design board UI',
      description: 'Create Kanban layout and styling'
    },
    'task-3': {
      id: 'task-3',
      title: 'Implement socket sync',
      description: 'Broadcast board updates in real time'
    }
  }
};

app.get('/api/board', (req, res) => {
  res.json(board);
});

app.post('/api/tasks', (req, res) => {
  const { title, description = '', columnId = 'todo' } = req.body;

  if (!title?.trim()) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const id = `task-${Date.now()}`;
  board.tasks[id] = {
    id,
    title,
    description
  };
  board.columns[columnId].taskIds.push(id);

  io.emit('board:update', board);
  res.status(201).json(board);
});

app.put('/api/tasks/:taskId', (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  board.tasks[taskId] = {
    ...board.tasks[taskId],
    ...(title !== undefined ? { title } : {}),
    ...(description !== undefined ? { description } : {})
  };

  io.emit('board:update', board);
  res.json(board);
});

app.delete('/api/tasks/:taskId', (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  delete board.tasks[taskId];

  for (const column of Object.values(board.columns)) {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  }

  io.emit('board:update', board);
  res.json(board);
});

app.post('/api/board/reorder', (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const sourceColumn = board.columns[sourceColumnId];
  const destinationColumn = board.columns[destinationColumnId];

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: 'Invalid column' });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit('board:update', board);
  res.json(board);
});

io.on('connection', socket => {
  console.log('Client connected:', socket.id);
  socket.emit('board:init', board);

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
