```jsx
import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
  arrayMove
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const API_URL = 'http://localhost:4000';
const socket = io(API_URL);

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then(res => res.json())
      .then(setBoard);

    socket.on('board:init', setBoard);
    socket.on('board:update', setBoard);

    return () => {
      socket.off('board:init', setBoard);
      socket.off('board:update', setBoard);
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnTasks = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const columnId of board.columnOrder) {
      const column = board.columns[columnId];
      result[columnId] = column.taskIds.map(taskId => board.tasks[taskId]).filter(Boolean);
    }
    return result;
  }, [board]);

  async function createTask(e) {
    e.preventDefault();

    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDescription,
        columnId: 'todo'
      })
    });

    setNewTaskTitle('');
    setNewTaskDescription('');
  }

  async function deleteTask(taskId) {
    await fetch(`${API_URL}/api/tasks/${taskId}`, {
      method: 'DELETE'
    });
  }

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return board.columnOrder.find(columnId =>
      board.columns[columnId].taskIds.includes(taskId)
    );
  }

  async function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumnId = findColumnByTaskId(activeId);
    const destinationColumnId =
      board.columnOrder.find(columnId => board.columns[columnId].taskIds.includes(overId)) ||
      overId;

    if (!sourceColumnId || !destinationColumnId) return;

    const sourceTasks = [...board.columns[sourceColumnId].taskIds];
    const destTasks =
      sourceColumnId === destinationColumnId
        ? sourceTasks
        : [...board.columns[destinationColumnId].taskIds];

    const sourceIndex = sourceTasks.indexOf(activeId);
    let destinationIndex = destTasks.indexOf(overId);

    if (destinationIndex === -1) {
      destinationIndex = destTasks.length;
    }

    let updatedBoard = structuredClone(board);

    if (sourceColumnId === destinationColumnId) {
      updatedBoard.columns[sourceColumnId].taskIds = arrayMove(
        updatedBoard.columns[sourceColumnId].taskIds,
        sourceIndex,
        destinationIndex
      );
    } else {
      updatedBoard.columns[sourceColumnId].taskIds.splice(sourceIndex, 1);
      updatedBoard.columns[destinationColumnId].taskIds.splice(destinationIndex, 0, activeId);
    }

    setBoard(updatedBoard);

    await fetch(`${API_URL}/api/board/reorder`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex,
        taskId: activeId
      })
    });
  }

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Board</h1>
      </header>

      <section className="task-form-section">
        <form className="task-form" onSubmit={createTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={e => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={e => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </section>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <main className="board">
          {board.columnOrder.map(columnId => {
            const column = board.columns[columnId];
            const tasks = columnTasks[columnId];

            return (
              <Column key={column.id} column={column} tasks={tasks} onDeleteTask={deleteTask} />
            );
          })}
        </main>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onDeleteTask }) {
  return (
    <div className="column" id={column.id}>
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map(task => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} onDelete={() => onDeleteTask(task.id)} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onDelete }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h3>{task.title}</h3>
      <p>{task.description}</p>
      <button className="delete-btn" onClick={onDelete}>
        Delete
      </button>
    </div>
  );
}

export default App;
```

