import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory project state for MVP
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["todo", "inprogress", "done"],
  tasks: {}
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description,
    createdAt: new Date().toISOString()
  };

  boardState.tasks[id] = task;
  boardState.columns[columnId].taskIds.push(id);

  io.emit("board:update", boardState);

  res.status(201).json(task);
});

app.put("/api/board", (req, res) => {
  const nextState = req.body;

  if (!nextState || !nextState.columns || !nextState.tasks) {
    return res.status(400).json({ error: "Invalid board state" });
  }

  boardState = nextState;
  io.emit("board:update", boardState);

  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", ({ title, description, columnId = "todo" }) => {
    if (!title) return;

    const id = uuidv4();
    const task = {
      id,
      title,
      description: description || "",
      createdAt: new Date().toISOString()
    };

    boardState.tasks[id] = task;
    boardState.columns[columnId].taskIds.push(id);

    io.emit("board:update", boardState);
  });

  socket.on("board:move", (nextState) => {
    boardState = nextState;
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

