# 4. Main App

## `client/src/App.jsx`

```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import Board from "./components/Board";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:init", (state) => setBoard(state));
    socket.on("board:update", (state) => setBoard(state));

    return () => {
      socket.off("board:init");
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnTaskMap = useMemo(() => {
    if (!board) return {};
    const map = {};
    for (const columnId of board.columnOrder) {
      map[columnId] = board.columns[columnId].taskIds;
    }
    return map;
  }, [board]);

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return board.columnOrder.find((columnId) =>
      board.columns[columnId].taskIds.includes(taskId)
    );
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumnId = findColumnByTaskId(activeId);
    const targetColumnId =
      board.columns[overId] ? overId : findColumnByTaskId(overId);

    if (!sourceColumnId || !targetColumnId) return;

    const nextBoard = structuredClone(board);

    if (sourceColumnId === targetColumnId) {
      const taskIds = nextBoard.columns[sourceColumnId].taskIds;
      const oldIndex = taskIds.indexOf(activeId);
      const newIndex = taskIds.indexOf(overId);

      nextBoard.columns[sourceColumnId].taskIds = arrayMove(
        taskIds,
        oldIndex,
        newIndex
      );
    } else {
      const sourceTaskIds = [...nextBoard.columns[sourceColumnId].taskIds];
      const targetTaskIds = [...nextBoard.columns[targetColumnId].taskIds];

      const sourceIndex = sourceTaskIds.indexOf(activeId);
      sourceTaskIds.splice(sourceIndex, 1);

      const targetIndex = board.columns[overId]
        ? targetTaskIds.length
        : targetTaskIds.indexOf(overId);

      if (targetIndex < 0) {
        targetTaskIds.push(activeId);
      } else {
        targetTaskIds.splice(targetIndex, 0, activeId);
      }

      nextBoard.columns[sourceColumnId].taskIds = sourceTaskIds;
      nextBoard.columns[targetColumnId].taskIds = targetTaskIds;
    }

    setBoard(nextBoard);
    socket.emit("board:move", nextBoard);
  }

  function handleCreateTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: "todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  }

  if (!board) return <div className="app-shell">Loading board...</div>;

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Project Management Board</h1>
      </header>

      <section className="task-form-section">
        <form className="task-form" onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </section>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragEnd={handleDragEnd}
      >
        <Board board={board} columnTaskMap={columnTaskMap} />
      </DndContext>
    </div>
  );
}
```

