import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

const board = {
  columns: {
    backlog: {
      id: "backlog",
      title: "Backlog",
      taskIds: []
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    review: {
      id: "review",
      title: "Review",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["backlog", "inprogress", "review", "done"],
  tasks: {}
};

function createTask(title, description = "") {
  const id = uuidv4();
  return {
    id,
    title,
    description,
    createdAt: new Date().toISOString()
  };
}

// Seed sample tasks
const t1 = createTask("Set up project repo", "Initialize frontend and backend");
const t2 = createTask("Design board layout", "Create Kanban board UI");
const t3 = createTask("Implement socket sync", "Broadcast board changes");

board.tasks[t1.id] = t1;
board.tasks[t2.id] = t2;
board.tasks[t3.id] = t3;

board.columns.backlog.taskIds.push(t1.id, t2.id);
board.columns.inprogress.taskIds.push(t3.id);

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/tasks", (req, res) => {
  const { title, description, columnId = "backlog" } = req.body;

  if (!title || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task title or columnId" });
  }

  const task = createTask(title, description);
  board.tasks[task.id] = task;
  board.columns[columnId].taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:create", ({ title, description, columnId }) => {
    if (!title || !board.columns[columnId]) return;

    const task = createTask(title, description);
    board.tasks[task.id] = task;
    board.columns[columnId].taskIds.push(task.id);

    io.emit("board:update", board);
  });

  socket.on("board:moveTask", ({ taskId, sourceColumnId, destColumnId, sourceIndex, destIndex }) => {
    const sourceColumn = board.columns[sourceColumnId];
    const destColumn = board.columns[destColumnId];

    if (!sourceColumn || !destColumn) return;
    if (!board.tasks[taskId]) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);
    destColumn.taskIds.splice(destIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

