import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { socket } from "./socket";
import type { Board, Task } from "./types";

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

function Column({
  id,
  title,
  tasks
}: {
  id: string;
  title: string;
  tasks: Task[];
}) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{title}</h3>
      </div>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" data-column-id={id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    socket.on("board:init", (data: Board) => setBoard(data));
    socket.on("board:update", (data: Board) => setBoard({ ...data }));

    fetch("http://localhost:4000/board")
      .then((res) => res.json())
      .then((data) => setBoard(data));

    return () => {
      socket.off("board:init");
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((taskId) => board.tasks[taskId]).filter(Boolean);
      return { ...column, tasks };
    });
  }, [board]);

  function findColumnByTaskId(taskId: string) {
    if (!board) return null;
    return Object.values(board.columns).find((column) => column.taskIds.includes(taskId)) || null;
  }

  function handleDragEnd(event: DragEndEvent) {
    if (!board) return;
    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const sourceColumn = findColumnByTaskId(taskId);
    if (!sourceColumn) return;

    const destinationColumn =
      findColumnByTaskId(overId) ||
      Object.values(board.columns).find((col) => col.id === overId) ||
      sourceColumn;

    if (!destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    let destIndex = destinationColumn.taskIds.indexOf(overId);

    if (destIndex === -1) {
      destIndex = destinationColumn.taskIds.length;
    }

    socket.emit("board:moveTask", {
      taskId,
      sourceColumnId: sourceColumn.id,
      destColumnId: destinationColumn.id,
      sourceIndex,
      destIndex
    });
  }

  function handleCreateTask(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;

    socket.emit("task:create", {
      title,
      description,
      columnId: "backlog"
    });

    setTitle("");
    setDescription("");
  }

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="app-header">
        <h1>Project Board</h1>
      </header>

      <form className="task-form" onSubmit={handleCreateTask}>
        <input
          type="text"
          placeholder="Task title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              id={column.id}
              title={column.title}
              tasks={column.tasks}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
