import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { boardState } from "./store.js";
import type { BoardState, Task } from "./types.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/board", (_req, res) => {
  res.json(boardState);
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:create", (task: Task & { columnId: string }) => {
    const { columnId, ...newTask } = task;
    boardState.tasks[newTask.id] = newTask;
    boardState.columns[columnId].taskIds.push(newTask.id);
    io.emit("board:update", boardState);
  });

  socket.on(
    "task:move",
    (payload: {
      taskId: string;
      sourceColumnId: string;
      destinationColumnId: string;
      sourceIndex: number;
      destinationIndex: number;
    }) => {
      const {
        taskId,
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex
      } = payload;

      const sourceColumn = boardState.columns[sourceColumnId];
      const destinationColumn = boardState.columns[destinationColumnId];

      sourceColumn.taskIds.splice(sourceIndex, 1);
      destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

      io.emit("board:update", boardState);
    }
  );
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
