## `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter
} from "@dnd-kit/core";
import { arrayMove } from "@dnd-kit/sortable";
import type { BoardState } from "../types";
import Column from "./Column";

type Props = {
  board: BoardState;
  onMoveTask: (payload: {
    taskId: string;
    sourceColumnId: string;
    destinationColumnId: string;
    sourceIndex: number;
    destinationIndex: number;
  }) => void;
  onAddTask: (columnId: string) => void;
};

function findColumnId(board: BoardState, taskId: string): string | null {
  for (const columnId of board.columnOrder) {
    if (board.columns[columnId].taskIds.includes(taskId)) {
      return columnId;
    }
  }
  return null;
}

export default function Board({ board, onMoveTask, onAddTask }: Props) {
  const sensors = useSensors(useSensor(PointerSensor));

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const sourceColumnId = findColumnId(board, taskId);
    const destinationColumnId = findColumnId(board, overId);

    if (!sourceColumnId || !destinationColumnId) return;

    const sourceTaskIds = board.columns[sourceColumnId].taskIds;
    const destinationTaskIds = board.columns[destinationColumnId].taskIds;

    const sourceIndex = sourceTaskIds.indexOf(taskId);
    const overIndex = destinationTaskIds.indexOf(overId);

    if (sourceColumnId === destinationColumnId) {
      const reordered = arrayMove(sourceTaskIds, sourceIndex, overIndex);
      reordered.forEach((id, index) => {
        board.columns[sourceColumnId].taskIds[index] = id;
      });
    }

    onMoveTask({
      taskId,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex: overIndex
    });
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);
          return <Column key={column.id} column={column} tasks={tasks} onAddTask={onAddTask} />;
        })}
      </div>
    </DndContext>
  );
}
```

