import { useEffect, useState } from "react";
import { io, Socket } from "socket.io-client";
import Board from "./components/Board";
import type { BoardState, Task } from "./types";

const socket: Socket = io("http://localhost:4000");

function createTaskId() {
  return `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
}

const initialBoard: BoardState = {
  tasks: {},
  columns: {},
  columnOrder: []
};

export default function App() {
  const [board, setBoard] = useState<BoardState>(initialBoard);

  useEffect(() => {
    fetch("http://localhost:4000/board")
      .then((res) => res.json())
      .then((data) => setBoard(data));

    socket.on("board:update", (updatedBoard: BoardState) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const handleAddTask = (columnId: string) => {
    const title = window.prompt("Task title?");
    if (!title) return;

    const task: Task & { columnId: string } = {
      id: createTaskId(),
      title,
      columnId
    };

    socket.emit("task:create", task);
  };

  const handleMoveTask = (payload: {
    taskId: string;
    sourceColumnId: string;
    destinationColumnId: string;
    sourceIndex: number;
    destinationIndex: number;
  }) => {
    socket.emit("task:move", payload);
  };

  return (
    <div className="app">
      <h1>Project Management Board</h1>
      <Board board={board} onMoveTask={handleMoveTask} onAddTask={handleAddTask} />
    </div>
  );
}
