## `server/server.js`

```js
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import { v4 as uuidv4 } from "uuid";
import http from "http";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const PORT = 4000;

/**
 * In-memory data store
 * Replace with a database later.
 */
const state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "col-1",
          title: "Backlog",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "col-2",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "col-3",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes",
          assignee: "Alex",
          updatedAt: Date.now()
        },
        "task-2": {
          id: "task-2",
          title: "Define color palette",
          description: "Choose primary and secondary brand colors",
          assignee: "Sam",
          updatedAt: Date.now()
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement responsive landing page",
          assignee: "Jordan",
          updatedAt: Date.now()
        }
      }
    }
  ]
};

function getProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

function broadcast(message) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(payload);
    }
  });
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.get("/api/projects/:projectId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: uuidv4(),
    name: name || "Untitled Project",
    columns: [
      { id: uuidv4(), title: "Backlog", taskIds: [] },
      { id: uuidv4(), title: "In Progress", taskIds: [] },
      { id: uuidv4(), title: "Done", taskIds: [] }
    ],
    tasks: {}
  };

  state.projects.push(project);

  broadcast({ type: "PROJECT_CREATED", payload: project });
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { title, description, assignee, columnId } = req.body;
  const taskId = uuidv4();

  const task = {
    id: taskId,
    title: title || "Untitled Task",
    description: description || "",
    assignee: assignee || "",
    updatedAt: Date.now()
  };

  project.tasks[taskId] = task;

  const targetColumn =
    project.columns.find((col) => col.id === columnId) || project.columns[0];

  targetColumn.taskIds.push(taskId);

  broadcast({
    type: "TASK_CREATED",
    payload: {
      projectId: project.id,
      task,
      columnId: targetColumn.id
    }
  });

  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project || !project.tasks[req.params.taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  const existing = project.tasks[req.params.taskId];
  const updated = {
    ...existing,
    ...req.body,
    id: existing.id,
    updatedAt: Date.now()
  };

  project.tasks[req.params.taskId] = updated;

  broadcast({
    type: "TASK_UPDATED",
    payload: {
      projectId: project.id,
      task: updated
    }
  });

  res.json(updated);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  const { projectId, taskId } = req.params;

  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  broadcast({
    type: "TASK_DELETED",
    payload: {
      projectId,
      taskId
    }
  });

  res.status(204).send();
});

app.post("/api/projects/:projectId/move-task", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number"
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  if (project.tasks[taskId]) {
    project.tasks[taskId].updatedAt = Date.now();
  }

  broadcast({
    type: "TASK_MOVED",
    payload: {
      projectId: project.id,
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex: insertIndex
    }
  });

  res.json({ success: true });
});

const wss = new WebSocketServer({ server });

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "INITIAL_STATE",
      payload: state.projects
    })
  );

  ws.on("message", (message) => {
    try {
      const parsed = JSON.parse(message.toString());

      if (parsed.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

