## `client/app.js`

```js
const API_BASE = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let projects = [];
let selectedProjectId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const projectListEl = document.getElementById("projectList");
const boardTitleEl = document.getElementById("boardTitle");
const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const createProjectBtn = document.getElementById("createProjectBtn");
const projectNameInput = document.getElementById("projectNameInput");

const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");
const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskColumnSelect = document.getElementById("taskColumn");

function getSelectedProject() {
  return projects.find((p) => p.id === selectedProjectId);
}

async function fetchProjects() {
  const res = await fetch(`${API_BASE}/projects`);
  projects = await res.json();

  if (!selectedProjectId && projects.length > 0) {
    selectedProjectId = projects[0].id;
  }

  render();
}

function render() {
  renderProjectList();
  renderBoard();
}

function renderProjectList() {
  projectListEl.innerHTML = "";

  projects.forEach((project) => {
    const li = document.createElement("li");
    li.textContent = project.name;
    li.className = project.id === selectedProjectId ? "active" : "";
    li.addEventListener("click", () => {
      selectedProjectId = project.id;
      render();
    });
    projectListEl.appendChild(li);
  });
}

function renderBoard() {
  const project = getSelectedProject();

  if (!project) {
    boardTitleEl.textContent = "Select a project";
    boardEl.innerHTML = "";
    addTaskBtn.disabled = true;
    return;
  }

  boardTitleEl.textContent = project.name;
  addTaskBtn.disabled = false;
  boardEl.innerHTML = "";

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h3");
    title.textContent = column.title;

    const taskList = document.createElement("div");
    taskList.className = "task-list";

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", async (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      await fetch(`${API_BASE}/projects/${project.id}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId: column.id,
          destinationIndex: column.taskIds.length
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.columnId = column.id;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      const titleEl = document.createElement("h4");
      titleEl.textContent = task.title;

      const descEl = document.createElement("p");
      descEl.textContent = task.description;

      const metaEl = document.createElement("div");
      metaEl.className = "task-meta";
      metaEl.textContent = `Assignee: ${task.assignee || "Unassigned"}`;

      const actionsEl = document.createElement("div");
      actionsEl.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditTaskDialog(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", async () => {
        await fetch(`${API_BASE}/projects/${project.id}/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      actionsEl.append(editBtn, deleteBtn);
      card.append(titleEl, descEl, metaEl, actionsEl);
      taskList.appendChild(card);
    });

    columnEl.append(title, taskList);
    boardEl.appendChild(columnEl);
  });
}

function populateColumnOptions(project, selectedColumnId) {
  taskColumnSelect.innerHTML = "";
  project.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    if (column.id === selectedColumnId) {
      option.selected = true;
    }
    taskColumnSelect.appendChild(option);
  });
}

function openCreateTaskDialog() {
  const project = getSelectedProject();
  if (!project) return;

  taskForm.reset();
  taskIdInput.value = "";
  populateColumnOptions(project, project.columns[0]?.id);
  taskDialog.showModal();
}

function openEditTaskDialog(task, columnId) {
  const project = getSelectedProject();
  if (!project) return;

  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description;
  taskAssigneeInput.value = task.assignee;
  populateColumnOptions(project, columnId);
  taskDialog.showModal();
}

createProjectBtn.addEventListener("click", async () => {
  const name = projectNameInput.value.trim();
  if (!name) return;

  await fetch(`${API_BASE}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  projectNameInput.value = "";
});

addTaskBtn.addEventListener("click", openCreateTaskDialog);

cancelTaskBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  const project = getSelectedProject();
  if (!project) return;

  const taskId = taskIdInput.value;
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  if (taskId) {
    await fetch(`${API_BASE}/projects/${project.id}/tasks/${taskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee })
    });

    const currentColumn = project.columns.find((col) => col.taskIds.includes(taskId));
    if (currentColumn && currentColumn.id !== columnId) {
      await fetch(`${API_BASE}/projects/${project.id}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId,
          sourceColumnId: currentColumn.id,
          destinationColumnId: columnId,
          destinationIndex: project.columns.find((c) => c.id === columnId)?.taskIds.length || 0
        })
      });
    }
  } else {
    await fetch(`${API_BASE}/projects/${project.id}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee, columnId })
    });
  }

  taskDialog.close();
});

function connectWebSocket() {
  const ws = new WebSocket(WS_URL);

  ws.addEventListener("open", () => {
    console.log("WebSocket connected");
  });

  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case "INITIAL_STATE":
        projects = message.payload;
        if (!selectedProjectId && projects.length > 0) {
          selectedProjectId = projects[0].id;
        }
        render();
        break;

      case "PROJECT_CREATED":
        projects.push(message.payload);
        if (!selectedProjectId) {
          selectedProjectId = message.payload.id;
        }
        render();
        break;

      case "TASK_CREATED": {
        const { projectId, task, columnId } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) break;
        project.tasks[task.id] = task;
        const column = project.columns.find((c) => c.id === columnId);
        if (column) column.taskIds.push(task.id);
        render();
        break;
      }

      case "TASK_UPDATED": {
        const { projectId, task } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) break;
        project.tasks[task.id] = task;
        render();
        break;
      }

      case "TASK_DELETED": {
        const { projectId, taskId } = message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) break;
        delete project.tasks[taskId];
        project.columns.forEach((col) => {
          col.taskIds = col.taskIds.filter((id) => id !== taskId);
        });
        render();
        break;
      }

      case "TASK_MOVED": {
        const { projectId, taskId, sourceColumnId, destinationColumnId, destinationIndex } =
          message.payload;
        const project = projects.find((p) => p.id === projectId);
        if (!project) break;

        const source = project.columns.find((c) => c.id === sourceColumnId);
        const destination = project.columns.find((c) => c.id === destinationColumnId);
        if (!source || !destination) break;

        source.taskIds = source.taskIds.filter((id) => id !== taskId);
        destination.taskIds.splice(destinationIndex, 0, taskId);
        render();
        break;
      }

      default:
        break;
    }
  });

  ws.addEventListener("close", () => {
    console.log("WebSocket disconnected. Reconnecting...");
    setTimeout(connectWebSocket, 1000);
  });
}

fetchProjects();
connectWebSocket();
```

