import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";

const app = express();
const PORT = 4000;

app.use(cors());
app.use(express.json());

let state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "col-todo",
          title: "To Do",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "col-inprogress",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "col-done",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes"
        },
        "task-2": {
          id: "task-2",
          title: "Define color palette",
          description: "Choose primary and secondary brand colors"
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement hero section and CTA"
        }
      }
    }
  ]
};

function getProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

function broadcast(wss, message) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(payload);
    }
  });
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const newProject = {
    id: `project-${Date.now()}`,
    name,
    columns: [
      { id: `col-${Date.now()}-todo`, title: "To Do", taskIds: [] },
      { id: `col-${Date.now()}-inprogress`, title: "In Progress", taskIds: [] },
      { id: `col-${Date.now()}-done`, title: "Done", taskIds: [] }
    ],
    tasks: {}
  };

  state.projects.push(newProject);
  res.status(201).json(newProject);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const { projectId } = req.params;
  const { title, description, columnId } = req.body;
  const project = getProject(projectId);

  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const taskId = `task-${Date.now()}`;
  const task = { id: taskId, title, description };
  project.tasks[taskId] = task;

  const column = project.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Column not found" });
  }

  column.taskIds.push(taskId);
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const { title, description } = req.body;
  const project = getProject(projectId);

  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  project.tasks[taskId] = {
    ...project.tasks[taskId],
    title,
    description
  };

  res.json(project.tasks[taskId]);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const project = getProject(projectId);

  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  res.status(204).send();
});

const server = app.listen(PORT, () => {
  console.log(`HTTP server running on http://localhost:${PORT}`);
});

const wss = new WebSocketServer({ server });

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "INIT_STATE", payload: state }));

  ws.on("message", (raw) => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === "MOVE_TASK") {
        const { projectId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = message.payload;
        const project = getProject(projectId);

        if (!project) return;

        const sourceCol = project.columns.find((c) => c.id === sourceColumnId);
        const destCol = project.columns.find((c) => c.id === destinationColumnId);

        if (!sourceCol || !destCol) return;

        sourceCol.taskIds.splice(sourceIndex, 1);
        destCol.taskIds.splice(destinationIndex, 0, taskId);

        broadcast(wss, {
          type: "STATE_UPDATED",
          payload: state
        });
      }

      if (message.type === "CREATE_TASK") {
        const { projectId, columnId, title, description } = message.payload;
        const project = getProject(projectId);
        if (!project) return;

        const taskId = `task-${Date.now()}`;
        project.tasks[taskId] = { id: taskId, title, description };

        const column = project.columns.find((c) => c.id === columnId);
        if (!column) return;

        column.taskIds.push(taskId);

        broadcast(wss, {
          type: "STATE_UPDATED",
          payload: state
        });
      }

      if (message.type === "UPDATE_TASK") {
        const { projectId, taskId, title, description } = message.payload;
        const project = getProject(projectId);
        if (!project || !project.tasks[taskId]) return;

        project.tasks[taskId] = {
          ...project.tasks[taskId],
          title,
          description
        };

        broadcast(wss, {
          type: "STATE_UPDATED",
          payload: state
        });
      }

      if (message.type === "DELETE_TASK") {
        const { projectId, taskId } = message.payload;
        const project = getProject(projectId);
        if (!project || !project.tasks[taskId]) return;

        delete project.tasks[taskId];
        project.columns.forEach((col) => {
          col.taskIds = col.taskIds.filter((id) => id !== taskId);
        });

        broadcast(wss, {
          type: "STATE_UPDATED",
          payload: state
        });
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});
