## `client/app.js`

```js
const API_BASE = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let appState = { projects: [] };
let currentProjectId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const projectSelectEl = document.getElementById("projectSelect");
const newProjectBtn = document.getElementById("newProjectBtn");

const ws = new WebSocket(WS_URL);

ws.addEventListener("open", () => {
  console.log("Connected to WebSocket server");
});

ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);

  if (message.type === "INIT_STATE" || message.type === "STATE_UPDATED") {
    appState = message.payload;
    if (!currentProjectId && appState.projects.length > 0) {
      currentProjectId = appState.projects[0].id;
    }
    renderProjectOptions();
    renderBoard();
  }
});

async function fetchProjects() {
  const res = await fetch(`${API_BASE}/projects`);
  const projects = await res.json();
  appState.projects = projects;
  if (!currentProjectId && projects.length > 0) {
    currentProjectId = projects[0].id;
  }
  renderProjectOptions();
  renderBoard();
}

function getCurrentProject() {
  return appState.projects.find((p) => p.id === currentProjectId);
}

function renderProjectOptions() {
  projectSelectEl.innerHTML = "";
  appState.projects.forEach((project) => {
    const option = document.createElement("option");
    option.value = project.id;
    option.textContent = project.name;
    if (project.id === currentProjectId) option.selected = true;
    projectSelectEl.appendChild(option);
  });
}

function renderBoard() {
  const project = getCurrentProject();
  boardEl.innerHTML = "";

  if (!project) {
    boardEl.innerHTML = "<p>No project selected.</p>";
    return;
  }

  const columnTemplate = document.getElementById("columnTemplate");
  const taskTemplate = document.getElementById("taskTemplate");

  project.columns.forEach((column) => {
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    columnNode.dataset.columnId = column.id;
    columnNode.querySelector("h2").textContent = column.title;

    const addTaskBtn = columnNode.querySelector(".add-task-btn");
    addTaskBtn.addEventListener("click", () => createTask(column.id));

    const taskList = columnNode.querySelector(".task-list");
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const sourceProject = getCurrentProject();
      const sourceColumn = sourceProject.columns.find(c => c.id === draggedFromColumnId);
      const destinationColumn = sourceProject.columns.find(c => c.id === column.id);

      const sourceIndex = sourceColumn.taskIds.indexOf(draggedTaskId);
      const destinationIndex = destinationColumn.taskIds.length;

      ws.send(JSON.stringify({
        type: "MOVE_TASK",
        payload: {
          projectId: currentProjectId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId: column.id,
          sourceIndex,
          destinationIndex,
          taskId: draggedTaskId
        }
      }));

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      taskNode.dataset.taskId = task.id;
      taskNode.querySelector(".task-title").textContent = task.title;
      taskNode.querySelector(".task-desc").textContent = task.description;

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
      });

      taskNode.querySelector(".edit-btn").addEventListener("click", () => editTask(task));
      taskNode.querySelector(".delete-btn").addEventListener("click", () => deleteTask(task.id));

      taskList.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

function createTask(columnId) {
  const title = prompt("Task title:");
  if (!title) return;
  const description = prompt("Task description:") || "";

  ws.send(JSON.stringify({
    type: "CREATE_TASK",
    payload: {
      projectId: currentProjectId,
      columnId,
      title,
      description
    }
  }));
}

function editTask(task) {
  const title = prompt("Edit task title:", task.title);
  if (!title) return;
  const description = prompt("Edit task description:", task.description) || "";

  ws.send(JSON.stringify({
    type: "UPDATE_TASK",
    payload: {
      projectId: currentProjectId,
      taskId: task.id,
      title,
      description
    }
  }));
}

function deleteTask(taskId) {
  const confirmed = confirm("Delete this task?");
  if (!confirmed) return;

  ws.send(JSON.stringify({
    type: "DELETE_TASK",
    payload: {
      projectId: currentProjectId,
      taskId
    }
  }));
}

projectSelectEl.addEventListener("change", (e) => {
  currentProjectId = e.target.value;
  renderBoard();
});

newProjectBtn.addEventListener("click", async () => {
  const name = prompt("Project name:");
  if (!name) return;

  const res = await fetch(`${API_BASE}/projects`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  appState.projects.push(project);
  currentProjectId = project.id;
  renderProjectOptions();
  renderBoard();
});

fetchProjects();
```

