```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

const board = {
  id: "board-1",
  title: "Team Project Board",
  columns: [
    {
      id: "col-todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "col-inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "col-done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function getBoardState() {
  return board;
}

app.get("/api/board", (req, res) => {
  res.json(getBoardState());
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "col-todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const task = {
    id: uuidv4(),
    title,
    description,
    createdAt: new Date().toISOString()
  };

  board.tasks[task.id] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/board/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Source or destination column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number"
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", ({ title, description = "", columnId = "col-todo" }) => {
    const task = {
      id: uuidv4(),
      title,
      description,
      createdAt: new Date().toISOString()
    };

    board.tasks[task.id] = task;

    const column = board.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(task.id);
      io.emit("board:update", board);
    }
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof destinationIndex === "number"
        ? destinationIndex
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
