## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard({ ...updatedBoard });
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnMap = useMemo(() => {
    if (!board) return {};
    return Object.fromEntries(board.columns.map((col) => [col.id, col]));
  }, [board]);

  function findColumnByTaskId(taskId) {
    return board.columns.find((col) => col.taskIds.includes(taskId));
  }

  function handleCreateTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: "col-todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeTaskId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(activeTaskId);
    if (!sourceColumn) return;

    let destinationColumn = board.columns.find((col) => col.id === overId);
    let destinationIndex = 0;

    if (destinationColumn) {
      destinationIndex = destinationColumn.taskIds.length;
    } else {
      destinationColumn = findColumnByTaskId(overId);
      if (!destinationColumn) return;
      destinationIndex = destinationColumn.taskIds.indexOf(overId);
    }

    if (sourceColumn.id === destinationColumn.id) {
      const oldIndex = sourceColumn.taskIds.indexOf(activeTaskId);
      const newIndex = destinationIndex;

      const updatedColumns = board.columns.map((col) => {
        if (col.id !== sourceColumn.id) return col;
        return {
          ...col,
          taskIds: arrayMove(col.taskIds, oldIndex, newIndex)
        };
      });

      const updatedBoard = { ...board, columns: updatedColumns };
      setBoard(updatedBoard);

      socket.emit("task:move", {
        taskId: activeTaskId,
        sourceColumnId: sourceColumn.id,
        destinationColumnId: destinationColumn.id,
        destinationIndex: newIndex
      });

      return;
    }

    const updatedColumns = board.columns.map((col) => {
      if (col.id === sourceColumn.id) {
        return {
          ...col,
          taskIds: col.taskIds.filter((id) => id !== activeTaskId)
        };
      }

      if (col.id === destinationColumn.id) {
        const newTaskIds = [...col.taskIds];
        newTaskIds.splice(destinationIndex, 0, activeTaskId);
        return {
          ...col,
          taskIds: newTaskIds
        };
      }

      return col;
    });

    const updatedBoard = { ...board, columns: updatedColumns };
    setBoard(updatedBoard);

    socket.emit("task:move", {
      taskId: activeTaskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex
    });
  }

  if (!board) {
    return <div className="app-loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>{board.title}</h1>
      </header>

      <section className="task-form-section">
        <form className="task-form" onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </section>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columns.map((column) => (
            <Column key={column.id} column={column} tasks={column.taskIds.map((id) => board.tasks[id])} />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" id={column.id}>
          <DroppableColumn id={column.id}>
            {tasks.map((task) => (
              <TaskCard key={task.id} task={task} />
            ))}
          </DroppableColumn>
        </div>
      </SortableContext>
    </div>
  );
}

function DroppableColumn({ id, children }) {
  return (
    <div data-column-id={id} className="droppable-column">
      {children}
    </div>
  );
}

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h3>{task.title}</h3>
      <p>{task.description}</p>
    </div>
  );
}

export default App;
```

