```js
const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const state = {
  projects: [
    {
      id: "project-1",
      name: "Demo Project",
      columns: [
        { id: "col-todo", title: "To Do", taskIds: ["task-1", "task-2"] },
        { id: "col-doing", title: "In Progress", taskIds: ["task-3"] },
        { id: "col-done", title: "Done", taskIds: [] }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Set up project",
          description: "Initialize repository and app structure"
        },
        "task-2": {
          id: "task-2",
          title: "Design board UI",
          description: "Create responsive kanban layout"
        },
        "task-3": {
          id: "task-3",
          title: "Implement drag and drop",
          description: "Allow moving tasks between columns"
        }
      }
    }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

function findProject(projectId) {
  return state.projects.find(p => p.id === projectId);
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: `project-${Date.now()}`,
    name: name || "Untitled Project",
    columns: [
      { id: `col-${Date.now()}-todo`, title: "To Do", taskIds: [] },
      { id: `col-${Date.now()}-doing`, title: "In Progress", taskIds: [] },
      { id: `col-${Date.now()}-done`, title: "Done", taskIds: [] }
    ],
    tasks: {}
  };

  state.projects.push(project);
  broadcast({ type: "STATE_UPDATED", payload: state });
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { title, description, columnId } = req.body;
  const taskId = `task-${Date.now()}`;
  const task = {
    id: taskId,
    title: title || "Untitled Task",
    description: description || ""
  };

  project.tasks[taskId] = task;
  const column = project.columns.find(c => c.id === columnId) || project.columns[0];
  column.taskIds.push(taskId);

  broadcast({ type: "STATE_UPDATED", payload: state });
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const task = project.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description } = req.body;
  task.title = title ?? task.title;
  task.description = description ?? task.description;

  broadcast({ type: "STATE_UPDATED", payload: state });
  res.json(task);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const taskId = req.params.taskId;
  delete project.tasks[taskId];
  project.columns.forEach(col => {
    col.taskIds = col.taskIds.filter(id => id !== taskId);
  });

  broadcast({ type: "STATE_UPDATED", payload: state });
  res.json({ success: true });
});

app.post("/api/projects/:projectId/move-task", (req, res) => {
  const project = findProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { taskId, sourceColumnId, targetColumnId, targetIndex } = req.body;
  const source = project.columns.find(c => c.id === sourceColumnId);
  const target = project.columns.find(c => c.id === targetColumnId);

  if (!source || !target) {
    return res.status(400).json({ error: "Invalid column" });
  }

  source.taskIds = source.taskIds.filter(id => id !== taskId);

  const insertIndex =
    typeof targetIndex === "number" ? targetIndex : target.taskIds.length;

  target.taskIds.splice(insertIndex, 0, taskId);

  broadcast({ type: "STATE_UPDATED", payload: state });
  res.json({ success: true });
});

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "STATE_UPDATED", payload: state }));

  ws.on("message", raw => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
