```js
let appState = { projects: [] };
let selectedProjectId = null;
let socket = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const projectListEl = document.getElementById("projectList");
const boardTitleEl = document.getElementById("boardTitle");
const boardEl = document.getElementById("board");
const projectNameInput = document.getElementById("projectNameInput");
const createProjectBtn = document.getElementById("createProjectBtn");
const taskTitleInput = document.getElementById("taskTitleInput");
const taskDescInput = document.getElementById("taskDescInput");
const taskColumnSelect = document.getElementById("taskColumnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");

async function fetchState() {
  const res = await fetch("/api/state");
  appState = await res.json();

  if (!selectedProjectId && appState.projects.length) {
    selectedProjectId = appState.projects[0].id;
  }

  render();
}

function connectWebSocket() {
  const protocol = location.protocol === "https:" ? "wss:" : "ws:";
  socket = new WebSocket(`${protocol}//${location.host}`);

  socket.addEventListener("message", event => {
    const message = JSON.parse(event.data);
    if (message.type === "STATE_UPDATED") {
      appState = message.payload;

      const stillExists = appState.projects.some(p => p.id === selectedProjectId);
      if (!stillExists && appState.projects.length) {
        selectedProjectId = appState.projects[0].id;
      }

      render();
    }
  });

  socket.addEventListener("close", () => {
    setTimeout(connectWebSocket, 1500);
  });
}

function getSelectedProject() {
  return appState.projects.find(p => p.id === selectedProjectId) || null;
}

function renderProjects() {
  projectListEl.innerHTML = "";

  appState.projects.forEach(project => {
    const li = document.createElement("li");
    li.textContent = project.name;
    if (project.id === selectedProjectId) li.classList.add("active");
    li.addEventListener("click", () => {
      selectedProjectId = project.id;
      render();
    });
    projectListEl.appendChild(li);
  });
}

function renderTaskColumnOptions(project) {
  taskColumnSelect.innerHTML = "";
  if (!project) return;

  project.columns.forEach(col => {
    const option = document.createElement("option");
    option.value = col.id;
    option.textContent = col.title;
    taskColumnSelect.appendChild(option);
  });
}

function createTaskCard(task, columnId) {
  const card = document.createElement("div");
  card.className = "task-card";
  card.draggable = true;
  card.dataset.taskId = task.id;
  card.dataset.columnId = columnId;

  card.innerHTML = `
    <h4>${escapeHtml(task.title)}</h4>
    <p>${escapeHtml(task.description || "")}</p>
    <div class="task-actions">
      <button data-action="edit">Edit</button>
      <button data-action="delete">Delete</button>
    </div>
  `;

  card.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    draggedFromColumnId = columnId;
    card.classList.add("dragging");
  });

  card.addEventListener("dragend", () => {
    draggedTaskId = null;
    draggedFromColumnId = null;
    card.classList.remove("dragging");
    document.querySelectorAll(".drop-target").forEach(el => el.classList.remove("drop-target"));
  });

  card.querySelector('[data-action="edit"]').addEventListener("click", async () => {
    const newTitle = prompt("Task title:", task.title);
    if (newTitle === null) return;
    const newDescription = prompt("Task description:", task.description || "");
    if (newDescription === null) return;

    await fetch(`/api/projects/${selectedProjectId}/tasks/${task.id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: newTitle, description: newDescription })
    });
  });

  card.querySelector('[data-action="delete"]').addEventListener("click", async () => {
    await fetch(`/api/projects/${selectedProjectId}/tasks/${task.id}`, {
      method: "DELETE"
    });
  });

  return card;
}

function renderBoard() {
  const project = getSelectedProject();
  boardEl.innerHTML = "";

  if (!project) {
    boardTitleEl.textContent = "Select a project";
    renderTaskColumnOptions(null);
    return;
  }

  boardTitleEl.textContent = project.name;
  renderTaskColumnOptions(project);

  project.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h3");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      taskListEl.classList.add("drop-target");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-target");
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      taskListEl.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      await fetch(`/api/projects/${selectedProjectId}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          targetColumnId: column.id,
          targetIndex: project.columns.find(c => c.id === column.id).taskIds.length
        })
      });
    });

    if (column.taskIds.length === 0) {
      const empty = document.createElement("div");
      empty.className = "empty-state";
      empty.textContent = "Drop tasks here";
      taskListEl.appendChild(empty);
    } else {
      column.taskIds.forEach(taskId => {
        const task = project.tasks[taskId];
        if (task) {
          taskListEl.appendChild(createTaskCard(task, column.id));
        }
      });
    }

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function render() {
  renderProjects();
  renderBoard();
}

async function createProject() {
  const name = projectNameInput.value.trim();
  if (!name) return;

  const res = await fetch("/api/projects", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  selectedProjectId = project.id;
  projectNameInput.value = "";
}

async function addTask() {
  const project = getSelectedProject();
  if (!project) return;

  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  await fetch(`/api/projects/${project.id}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, columnId })
  });

  taskTitleInput.value = "";
  taskDescInput.value = "";
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

createProjectBtn.addEventListener("click", createProject);
addTaskBtn.addEventListener("click", addTask);

fetchState();
connectWebSocket();
```

