# 2. `server.js`

```js
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const { v4: uuidv4 } = require('uuid');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static('public'));

// In-memory data store
const store = {
  projects: [
    {
      id: 'project-1',
      name: 'Demo Project',
      columns: [
        {
          id: 'todo',
          title: 'To Do',
          taskIds: ['task-1', 'task-2']
        },
        {
          id: 'in-progress',
          title: 'In Progress',
          taskIds: ['task-3']
        },
        {
          id: 'done',
          title: 'Done',
          taskIds: []
        }
      ],
      tasks: {
        'task-1': {
          id: 'task-1',
          title: 'Set up project structure',
          description: 'Create frontend and backend skeleton',
          assignee: 'Alice',
          updatedAt: Date.now()
        },
        'task-2': {
          id: 'task-2',
          title: 'Implement drag and drop',
          description: 'Allow cards to move between columns',
          assignee: 'Bob',
          updatedAt: Date.now()
        },
        'task-3': {
          id: 'task-3',
          title: 'Add WebSocket sync',
          description: 'Broadcast changes to connected clients',
          assignee: 'Carol',
          updatedAt: Date.now()
        }
      }
    }
  ]
};

function getProject(projectId) {
  return store.projects.find(p => p.id === projectId);
}

function broadcast(message, excludeSocket = null) {
  const data = JSON.stringify(message);
  wss.clients.forEach(client => {
    if (client !== excludeSocket && client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

app.get('/api/projects', (req, res) => {
  res.json(store.projects);
});

app.post('/api/projects', (req, res) => {
  const { name } = req.body;
  const project = {
    id: uuidv4(),
    name: name || 'Untitled Project',
    columns: [
      { id: uuidv4(), title: 'To Do', taskIds: [] },
      { id: uuidv4(), title: 'In Progress', taskIds: [] },
      { id: uuidv4(), title: 'Done', taskIds: [] }
    ],
    tasks: {}
  };

  store.projects.push(project);
  broadcast({ type: 'PROJECT_CREATED', payload: project });
  res.status(201).json(project);
});

app.post('/api/projects/:projectId/tasks', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const { title, description, assignee, columnId } = req.body;
  const task = {
    id: uuidv4(),
    title: title || 'Untitled Task',
    description: description || '',
    assignee: assignee || '',
    updatedAt: Date.now()
  };

  project.tasks[task.id] = task;

  const targetColumn = project.columns.find(c => c.id === columnId) || project.columns[0];
  targetColumn.taskIds.push(task.id);

  broadcast({
    type: 'TASK_CREATED',
    payload: { projectId: project.id, task, columnId: targetColumn.id }
  });

  res.status(201).json(task);
});

app.put('/api/projects/:projectId/tasks/:taskId', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const task = project.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: 'Task not found' });

  const { title, description, assignee } = req.body;
  task.title = title ?? task.title;
  task.description = description ?? task.description;
  task.assignee = assignee ?? task.assignee;
  task.updatedAt = Date.now();

  broadcast({
    type: 'TASK_UPDATED',
    payload: { projectId: project.id, task }
  });

  res.json(task);
});

app.delete('/api/projects/:projectId/tasks/:taskId', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) return res.status(404).json({ error: 'Task not found' });

  delete project.tasks[taskId];
  project.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  });

  broadcast({
    type: 'TASK_DELETED',
    payload: { projectId: project.id, taskId }
  });

  res.status(204).send();
});

app.put('/api/projects/:projectId/move-task', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = project.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = project.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: 'Invalid column' });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const insertIndex =
    typeof destinationIndex === 'number'
      ? Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length))
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  if (project.tasks[taskId]) {
    project.tasks[taskId].updatedAt = Date.now();
  }

  const payload = {
    projectId: project.id,
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex: insertIndex
  };

  broadcast({ type: 'TASK_MOVED', payload });
  res.json(payload);
});

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'INIT', payload: store.projects }));

  ws.on('message', raw => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === 'PING') {
        ws.send(JSON.stringify({ type: 'PONG' }));
      }
    } catch (err) {
      console.error('Invalid WS message', err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
