# 5. `public/app.js`

```js
const state = {
  projects: [],
  selectedProjectId: null,
  ws: null
};

const projectListEl = document.getElementById('project-list');
const boardEl = document.getElementById('board');
const boardTitleEl = document.getElementById('board-title');
const addTaskBtn = document.getElementById('add-task-btn');
const createProjectBtn = document.getElementById('create-project-btn');
const newProjectNameEl = document.getElementById('new-project-name');

const taskDialog = document.getElementById('task-dialog');
const taskForm = document.getElementById('task-form');
const taskFormTitle = document.getElementById('task-form-title');
const taskIdEl = document.getElementById('task-id');
const taskTitleEl = document.getElementById('task-title');
const taskDescriptionEl = document.getElementById('task-description');
const taskAssigneeEl = document.getElementById('task-assignee');
const taskColumnEl = document.getElementById('task-column');
const cancelTaskBtn = document.getElementById('cancel-task-btn');

function getSelectedProject() {
  return state.projects.find(p => p.id === state.selectedProjectId);
}

async function fetchProjects() {
  const res = await fetch('/api/projects');
  const projects = await res.json();
  state.projects = projects;
  if (!state.selectedProjectId && projects.length) {
    state.selectedProjectId = projects[0].id;
  }
  render();
}

function render() {
  renderProjectList();
  renderBoard();
}

function renderProjectList() {
  projectListEl.innerHTML = '';

  state.projects.forEach(project => {
    const li = document.createElement('li');
    li.textContent = project.name;
    if (project.id === state.selectedProjectId) {
      li.classList.add('active');
    }
    li.addEventListener('click', () => {
      state.selectedProjectId = project.id;
      render();
    });
    projectListEl.appendChild(li);
  });
}

function renderBoard() {
  const project = getSelectedProject();
  boardEl.innerHTML = '';

  if (!project) {
    boardTitleEl.textContent = 'Select a project';
    addTaskBtn.disabled = true;
    return;
  }

  boardTitleEl.textContent = project.name;
  addTaskBtn.disabled = false;

  project.columns.forEach(column => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement('h3');
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement('div');
    taskListEl.className = 'task-list';
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener('dragover', e => {
      e.preventDefault();
      taskListEl.classList.add('drop-target');
    });

    taskListEl.addEventListener('dragleave', () => {
      taskListEl.classList.remove('drop-target');
    });

    taskListEl.addEventListener('drop', async e => {
      e.preventDefault();
      taskListEl.classList.remove('drop-target');

      const taskId = e.dataTransfer.getData('text/task-id');
      const sourceColumnId = e.dataTransfer.getData('text/source-column-id');
      const destinationColumnId = column.id;

      if (!taskId || !sourceColumnId || !destinationColumnId) return;
      if (sourceColumnId === destinationColumnId) return;

      await moveTask(taskId, sourceColumnId, destinationColumnId, 0);
    });

    column.taskIds.forEach(taskId => {
      const task = project.tasks[taskId];
      if (!task) return;

      const card = document.createElement('div');
      card.className = 'task-card';
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.columnId = column.id;

      card.addEventListener('dragstart', e => {
        card.classList.add('dragging');
        e.dataTransfer.setData('text/task-id', task.id);
        e.dataTransfer.setData('text/source-column-id', column.id);
      });

      card.addEventListener('dragend', () => {
        card.classList.remove('dragging');
      });

      const title = document.createElement('h4');
      title.textContent = task.title;

      const desc = document.createElement('p');
      desc.textContent = task.description || '';

      const meta = document.createElement('div');
      meta.className = 'task-meta';
      meta.textContent = `Assignee: ${task.assignee || 'Unassigned'}`;

      const actions = document.createElement('div');
      actions.className = 'task-actions';

      const editBtn = document.createElement('button');
      editBtn.textContent = 'Edit';
      editBtn.addEventListener('click', () => openTaskDialog(task, column.id));

      const deleteBtn = document.createElement('button');
      deleteBtn.textContent = 'Delete';
      deleteBtn.addEventListener('click', async () => {
        await deleteTask(task.id);
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(title);
      card.appendChild(desc);
      card.appendChild(meta);
      card.appendChild(actions);

      taskListEl.appendChild(card);
    });

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function openTaskDialog(task = null, columnId = null) {
  const project = getSelectedProject();
  if (!project) return;

  taskForm.reset();
  taskColumnEl.innerHTML = '';

  project.columns.forEach(column => {
    const option = document.createElement('option');
    option.value = column.id;
    option.textContent = column.title;
    taskColumnEl.appendChild(option);
  });

  if (task) {
    taskFormTitle.textContent = 'Edit Task';
    taskIdEl.value = task.id;
    taskTitleEl.value = task.title;
    taskDescriptionEl.value = task.description || '';
    taskAssigneeEl.value = task.assignee || '';
    taskColumnEl.value = columnId || project.columns[0].id;
  } else {
    taskFormTitle.textContent = 'Add Task';
    taskIdEl.value = '';
    taskColumnEl.value = columnId || project.columns[0].id;
  }

  taskDialog.showModal();
}

taskForm.addEventListener('submit', async e => {
  e.preventDefault();

  const project = getSelectedProject();
  if (!project) return;

  const taskId = taskIdEl.value;
  const payload = {
    title: taskTitleEl.value.trim(),
    description: taskDescriptionEl.value.trim(),
    assignee: taskAssigneeEl.value.trim(),
    columnId: taskColumnEl.value
  };

  if (!payload.title) return;

  if (taskId) {
    await fetch(`/api/projects/${project.id}/tasks/${taskId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  } else {
    await fetch(`/api/projects/${project.id}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  }

  taskDialog.close();
});

cancelTaskBtn.addEventListener('click', () => taskDialog.close());

addTaskBtn.addEventListener('click', () => {
  const project = getSelectedProject();
  if (!project) return;
  openTaskDialog(null, project.columns[0].id);
});

createProjectBtn.addEventListener('click', async () => {
  const name = newProjectNameEl.value.trim();
  if (!name) return;

  const res = await fetch('/api/projects', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  state.selectedProjectId = project.id;
  newProjectNameEl.value = '';
  render();
});

async function deleteTask(taskId) {
  const project = getSelectedProject();
  if (!project) return;

  await fetch(`/api/projects/${project.id}/tasks/${taskId}`, {
    method: 'DELETE'
  });
}

async function moveTask(taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  const project = getSelectedProject();
  if (!project) return;

  await fetch(`/api/projects/${project.id}/move-task`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    })
  });
}

function applyMessage(message) {
  const { type, payload } = message;

  switch (type) {
    case 'INIT':
      state.projects = payload;
      if (!state.selectedProjectId && payload.length) {
        state.selectedProjectId = payload[0].id;
      }
      render();
      break;

    case 'PROJECT_CREATED':
      state.projects.push(payload);
      render();
      break;

    case 'TASK_CREATED': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;

      project.tasks[payload.task.id] = payload.task;
      const column = project.columns.find(c => c.id === payload.columnId);
      if (column && !column.taskIds.includes(payload.task.id)) {
        column.taskIds.push(payload.task.id);
      }
      render();
      break;
    }

    case 'TASK_UPDATED': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;

      project.tasks[payload.task.id] = payload.task;
      render();
      break;
    }

    case 'TASK_DELETED': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;

      delete project.tasks[payload.taskId];
      project.columns.forEach(column => {
        column.taskIds = column.taskIds.filter(id => id !== payload.taskId);
      });
      render();
      break;
    }

    case 'TASK_MOVED': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;

      const sourceColumn = project.columns.find(c => c.id === payload.sourceColumnId);
      const destinationColumn = project.columns.find(c => c.id === payload.destinationColumnId);

      if (!sourceColumn || !destinationColumn) break;

      sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== payload.taskId);

      const existingIndex = destinationColumn.taskIds.indexOf(payload.taskId);
      if (existingIndex !== -1) {
        destinationColumn.taskIds.splice(existingIndex, 1);
      }

      destinationColumn.taskIds.splice(payload.destinationIndex, 0, payload.taskId);
      render();
      break;
    }
  }
}

function connectWebSocket() {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  const ws = new WebSocket(`${protocol}//${location.host}`);
  state.ws = ws;

  ws.addEventListener('open', () => {
    console.log('WebSocket connected');
  });

  ws.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    applyMessage(message);
  });

  ws.addEventListener('close', () => {
    console.log('WebSocket disconnected, retrying...');
    setTimeout(connectWebSocket, 1000);
  });
}

fetchProjects();
connectWebSocket();
