```js
const express = require('express');
const http = require('http');
const path = require('path');
const { WebSocketServer } = require('ws');
const { v4: uuidv4 } = require('uuid');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// In-memory store
const db = {
  projects: [
    {
      id: 'project-1',
      name: 'Demo Project',
      columns: [
        { id: 'col-todo', title: 'To Do', taskIds: ['task-1', 'task-2'] },
        { id: 'col-doing', title: 'In Progress', taskIds: ['task-3'] },
        { id: 'col-done', title: 'Done', taskIds: [] }
      ],
      tasks: {
        'task-1': {
          id: 'task-1',
          title: 'Set up project',
          description: 'Initialize repository and structure'
        },
        'task-2': {
          id: 'task-2',
          title: 'Design board UI',
          description: 'Create Kanban layout'
        },
        'task-3': {
          id: 'task-3',
          title: 'Implement drag and drop',
          description: 'Move tasks between columns'
        }
      }
    }
  ]
};

function getProject(projectId) {
  return db.projects.find(p => p.id === projectId);
}

function broadcast(message, except = null) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client !== except && client.readyState === 1) {
      client.send(data);
    }
  }
}

// REST API
app.get('/api/projects', (req, res) => {
  res.json(db.projects);
});

app.post('/api/projects', (req, res) => {
  const { name } = req.body;
  const project = {
    id: uuidv4(),
    name: name || 'Untitled Project',
    columns: [
      { id: uuidv4(), title: 'To Do', taskIds: [] },
      { id: uuidv4(), title: 'In Progress', taskIds: [] },
      { id: uuidv4(), title: 'Done', taskIds: [] }
    ],
    tasks: {}
  };
  db.projects.push(project);
  broadcast({ type: 'project_created', payload: project });
  res.status(201).json(project);
});

app.post('/api/projects/:projectId/tasks', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const { title, description, columnId } = req.body;
  const task = {
    id: uuidv4(),
    title: title || 'Untitled Task',
    description: description || ''
  };

  project.tasks[task.id] = task;

  const column = project.columns.find(c => c.id === columnId) || project.columns[0];
  column.taskIds.push(task.id);

  const payload = { projectId: project.id, task, columnId: column.id };
  broadcast({ type: 'task_created', payload });
  res.status(201).json(payload);
});

app.put('/api/projects/:projectId/tasks/:taskId', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const task = project.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: 'Task not found' });

  const { title, description } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  const payload = { projectId: project.id, task };
  broadcast({ type: 'task_updated', payload });
  res.json(payload);
});

app.delete('/api/projects/:projectId/tasks/:taskId', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) return res.status(404).json({ error: 'Task not found' });

  delete project.tasks[taskId];
  for (const col of project.columns) {
    col.taskIds = col.taskIds.filter(id => id !== taskId);
  }

  const payload = { projectId: project.id, taskId };
  broadcast({ type: 'task_deleted', payload });
  res.json({ success: true });
});

app.post('/api/projects/:projectId/move-task', (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: 'Project not found' });

  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceCol = project.columns.find(c => c.id === sourceColumnId);
  const destCol = project.columns.find(c => c.id === destinationColumnId);

  if (!sourceCol || !destCol) {
    return res.status(400).json({ error: 'Invalid column(s)' });
  }

  sourceCol.taskIds = sourceCol.taskIds.filter(id => id !== taskId);

  const insertAt = Math.max(0, Math.min(destinationIndex, destCol.taskIds.length));
  destCol.taskIds.splice(insertAt, 0, taskId);

  const payload = {
    projectId: project.id,
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex
  };

  broadcast({ type: 'task_moved', payload });
  res.json(payload);
});

// WebSocket
wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'connected', payload: { ok: true } }));

  ws.on('message', raw => {
    try {
      const msg = JSON.parse(raw.toString());

      // Optional client-originated realtime events
      if (msg.type === 'ping') {
        ws.send(JSON.stringify({ type: 'pong', payload: Date.now() }));
      }
    } catch (err) {
      ws.send(JSON.stringify({ type: 'error', payload: 'Invalid message' }));
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
