# `public/app.js`

```js
const state = {
  projects: [],
  currentProjectId: null,
  socket: null,
  dragTaskId: null,
  dragSourceColumnId: null
};

const boardEl = document.getElementById('board');
const projectSelectEl = document.getElementById('project-select');
const createProjectBtn = document.getElementById('create-project-btn');
const projectNameInput = document.getElementById('project-name-input');
const createTaskBtn = document.getElementById('create-task-btn');
const taskTitleInput = document.getElementById('task-title-input');
const taskDescInput = document.getElementById('task-desc-input');
const statusEl = document.getElementById('status');
const taskTemplate = document.getElementById('task-template');

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json' },
    ...options
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({ error: 'Request failed' }));
    throw new Error(err.error || 'Request failed');
  }
  return res.json();
}

function getCurrentProject() {
  return state.projects.find(p => p.id === state.currentProjectId);
}

function renderProjectSelect() {
  projectSelectEl.innerHTML = '';
  state.projects.forEach(project => {
    const option = document.createElement('option');
    option.value = project.id;
    option.textContent = project.name;
    if (project.id === state.currentProjectId) option.selected = true;
    projectSelectEl.appendChild(option);
  });
}

function renderBoard() {
  const project = getCurrentProject();
  boardEl.innerHTML = '';

  if (!project) {
    boardEl.innerHTML = '<p>No project selected.</p>';
    return;
  }

  project.columns.forEach(column => {
    const colEl = document.createElement('div');
    colEl.className = 'column';
    colEl.dataset.columnId = column.id;

    const title = document.createElement('h2');
    title.textContent = column.title;

    const list = document.createElement('div');
    list.className = 'task-list';
    list.dataset.columnId = column.id;

    list.addEventListener('dragover', e => {
      e.preventDefault();
      list.classList.add('drop-target');
    });

    list.addEventListener('dragleave', () => {
      list.classList.remove('drop-target');
    });

    list.addEventListener('drop', async e => {
      e.preventDefault();
      list.classList.remove('drop-target');

      if (!state.dragTaskId || !state.dragSourceColumnId) return;

      const destinationColumnId = list.dataset.columnId;
      const destinationIndex = list.children.length;

      try {
        await api(`/api/projects/${project.id}/move-task`, {
          method: 'POST',
          body: JSON.stringify({
            taskId: state.dragTaskId,
            sourceColumnId: state.dragSourceColumnId,
            destinationColumnId,
            destinationIndex
          })
        });
      } catch (err) {
        alert(err.message);
      } finally {
        state.dragTaskId = null;
        state.dragSourceColumnId = null;
      }
    });

    column.taskIds.forEach(taskId => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.querySelector('.task-title').textContent = task.title;
      taskEl.querySelector('.task-desc').textContent = task.description;

      taskEl.addEventListener('dragstart', () => {
        state.dragTaskId = task.id;
        state.dragSourceColumnId = column.id;
        taskEl.classList.add('dragging');
      });

      taskEl.addEventListener('dragend', () => {
        taskEl.classList.remove('dragging');
      });

      taskEl.querySelector('.edit-task-btn').addEventListener('click', async () => {
        const newTitle = prompt('Task title:', task.title);
        if (newTitle === null) return;
        const newDesc = prompt('Task description:', task.description);
        if (newDesc === null) return;

        try {
          await api(`/api/projects/${project.id}/tasks/${task.id}`, {
            method: 'PUT',
            body: JSON.stringify({ title: newTitle, description: newDesc })
          });
        } catch (err) {
          alert(err.message);
        }
      });

      taskEl.querySelector('.delete-task-btn').addEventListener('click', async () => {
        if (!confirm(`Delete "${task.title}"?`)) return;
        try {
          await api(`/api/projects/${project.id}/tasks/${task.id}`, {
            method: 'DELETE'
          });
        } catch (err) {
          alert(err.message);
        }
      });

      list.appendChild(taskEl);
    });

    colEl.appendChild(title);
    colEl.appendChild(list);
    boardEl.appendChild(colEl);
  });
}

function applyRealtimeEvent(message) {
  const { type, payload } = message;

  switch (type) {
    case 'project_created':
      state.projects.push(payload);
      if (!state.currentProjectId) state.currentProjectId = payload.id;
      break;

    case 'task_created': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;
      project.tasks[payload.task.id] = payload.task;
      const col = project.columns.find(c => c.id === payload.columnId);
      if (col && !col.taskIds.includes(payload.task.id)) {
        col.taskIds.push(payload.task.id);
      }
      break;
    }

    case 'task_updated': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;
      project.tasks[payload.task.id] = payload.task;
      break;
    }

    case 'task_deleted': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;
      delete project.tasks[payload.taskId];
      project.columns.forEach(col => {
        col.taskIds = col.taskIds.filter(id => id !== payload.taskId);
      });
      break;
    }

    case 'task_moved': {
      const project = state.projects.find(p => p.id === payload.projectId);
      if (!project) break;

      const sourceCol = project.columns.find(c => c.id === payload.sourceColumnId);
      const destCol = project.columns.find(c => c.id === payload.destinationColumnId);
      if (!sourceCol || !destCol) break;

      sourceCol.taskIds = sourceCol.taskIds.filter(id => id !== payload.taskId);
      destCol.taskIds = destCol.taskIds.filter(id => id !== payload.taskId);

      const index = Math.max(0, Math.min(payload.destinationIndex, destCol.taskIds.length));
      destCol.taskIds.splice(index, 0, payload.taskId);
      break;
    }
  }

  renderProjectSelect();
  renderBoard();
}

async function loadProjects() {
  state.projects = await api('/api/projects');
  if (state.projects.length && !state.currentProjectId) {
    state.currentProjectId = state.projects[0].id;
  }
  renderProjectSelect();
  renderBoard();
}

function connectSocket() {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  state.socket = new WebSocket(`${protocol}//${location.host}`);

  state.socket.addEventListener('open', () => {
    statusEl.textContent = 'Connected';
  });

  state.socket.addEventListener('close', () => {
    statusEl.textContent = 'Disconnected - retrying...';
    setTimeout(connectSocket, 1500);
  });

  state.socket.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    if (message.type === 'connected') return;
    applyRealtimeEvent(message);
  });
}

createProjectBtn.addEventListener('click', async () => {
  const name = projectNameInput.value.trim();
  if (!name) return alert('Enter a project name');

  try {
    const project = await api('/api/projects', {
      method: 'POST',
      body: JSON.stringify({ name })
    });
    state.currentProjectId = project.id;
    projectNameInput.value = '';
    await loadProjects();
  } catch (err) {
    alert(err.message);
  }
});

projectSelectEl.addEventListener('change', () => {
  state.currentProjectId = projectSelectEl.value;
  renderBoard();
});

createTaskBtn.addEventListener('click', async () => {
  const project = getCurrentProject();
  if (!project) return alert('Select a project first');

  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();
  if (!title) return alert('Enter a task title');

  try {
    await api(`/api/projects/${project.id}/tasks`, {
      method: 'POST',
      body: JSON.stringify({
        title,
        description,
        columnId: project.columns[0].id
      })
    });
    taskTitleInput.value = '';
    taskDescInput.value = '';
  } catch (err) {
    alert(err.message);
  }
});

loadProjects().catch(err => {
  console.error(err);
  alert('Failed to load projects');
});

connectSocket();
