```js
import express from "express";
import http from "http";
import { WebSocketServer } from "ws";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

let boardState = {
  columns: {
    "todo": {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    "in-progress": {
      id: "in-progress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    "done": {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project repo", description: "Initialize GitHub repository" },
    "task-2": { id: "task-2", title: "Design board UI", description: "Create initial kanban layout" },
    "task-3": { id: "task-3", title: "Implement WebSocket sync", description: "Broadcast updates to all clients" }
  },
  columnOrder: ["todo", "in-progress", "done"]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;
  const id = `task-${Date.now()}`;

  boardState.tasks[id] = { id, title, description };
  boardState.columns[columnId].taskIds.push(id);

  broadcast({ type: "BOARD_UPDATED", payload: boardState });
  res.status(201).json(boardState.tasks[id]);
});

app.put("/api/board", (req, res) => {
  boardState = req.body;
  broadcast({ type: "BOARD_UPDATED", payload: boardState });
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATED", payload: boardState }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "UPDATE_BOARD") {
        boardState = data.payload;
        broadcast({ type: "BOARD_UPDATED", payload: boardState });
      }

      if (data.type === "CREATE_TASK") {
        const { title, description, columnId } = data.payload;
        const id = `task-${Date.now()}`;
        boardState.tasks[id] = { id, title, description };
        boardState.columns[columnId].taskIds.push(id);
        broadcast({ type: "BOARD_UPDATED", payload: boardState });
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

