```jsx
import React, { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

function TaskCard({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="task-card">
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [ws, setWs] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch(`${API_URL}/board`)
      .then((res) => res.json())
      .then(setBoard);

    const socket = new WebSocket(WS_URL);

    socket.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === "BOARD_UPDATED") {
        setBoard(data.payload);
      }
    };

    setWs(socket);

    return () => socket.close();
  }, []);

  const orderedColumns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);
      return { ...column, tasks };
    });
  }, [board]);

  function findColumnByTaskId(taskId) {
    return Object.values(board.columns).find((column) => column.taskIds.includes(taskId));
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(activeId);
    const destinationColumn =
      findColumnByTaskId(overId) || board.columns[overId];

    if (!sourceColumn || !destinationColumn) return;

    const newBoard = structuredClone(board);

    if (sourceColumn.id === destinationColumn.id) {
      const taskIds = [...newBoard.columns[sourceColumn.id].taskIds];
      const oldIndex = taskIds.indexOf(activeId);
      const newIndex = taskIds.indexOf(overId);

      taskIds.splice(oldIndex, 1);
      taskIds.splice(newIndex, 0, activeId);

      newBoard.columns[sourceColumn.id].taskIds = taskIds;
    } else {
      const sourceTaskIds = [...newBoard.columns[sourceColumn.id].taskIds];
      const destTaskIds = [...newBoard.columns[destinationColumn.id].taskIds];

      sourceTaskIds.splice(sourceTaskIds.indexOf(activeId), 1);

      const insertIndex = destTaskIds.includes(overId)
        ? destTaskIds.indexOf(overId)
        : destTaskIds.length;

      destTaskIds.splice(insertIndex, 0, activeId);

      newBoard.columns[sourceColumn.id].taskIds = sourceTaskIds;
      newBoard.columns[destinationColumn.id].taskIds = destTaskIds;
    }

    setBoard(newBoard);

    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: "UPDATE_BOARD", payload: newBoard }));
    }
  }

  function handleCreateTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim() || !ws) return;

    const payload = {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: selectedColumn
    };

    if (ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: "CREATE_TASK", payload }));
    }

    setNewTaskTitle("");
    setNewTaskDescription("");
  }

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
      </header>

      <form className="task-form" onSubmit={handleCreateTask}>
        <input
          type="text"
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
        />
        <select value={selectedColumn} onChange={(e) => setSelectedColumn(e.target.value)}>
          {board.columnOrder.map((columnId) => (
            <option key={columnId} value={columnId}>
              {board.columns[columnId].title}
            </option>
          ))}
        </select>
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {orderedColumns.map((column) => (
            <div key={column.id}>
              <Column column={column} tasks={column.tasks} />
            </div>
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

