# `server.js`

```js
const express = require('express');
const http = require('http');
const path = require('path');
const { WebSocketServer } = require('ws');
const { v4: uuidv4 } = require('uuid');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

const db = {
  board: {
    id: 'default-board',
    name: 'Team Project Board',
    columns: [
      { id: 'todo', title: 'To Do', taskIds: [] },
      { id: 'inprogress', title: 'In Progress', taskIds: [] },
      { id: 'done', title: 'Done', taskIds: [] }
    ],
    tasks: {}
  }
};

function seedData() {
  const tasks = [
    { title: 'Set up repository', description: 'Initialize git and README', columnId: 'todo' },
    { title: 'Design homepage', description: 'Create wireframe for dashboard', columnId: 'inprogress' },
    { title: 'Deploy prototype', description: 'Push MVP to staging', columnId: 'done' }
  ];

  tasks.forEach(task => {
    const id = uuidv4();
    db.board.tasks[id] = {
      id,
      title: task.title,
      description: task.description,
      assignee: '',
      updatedAt: Date.now()
    };
    const col = db.board.columns.find(c => c.id === task.columnId);
    col.taskIds.push(id);
  });
}

seedData();

function getBoardState() {
  return db.board;
}

function broadcast(message, except = null) {
  const payload = JSON.stringify(message);
  wss.clients.forEach(client => {
    if (client !== except && client.readyState === 1) {
      client.send(payload);
    }
  });
}

app.get('/api/board', (req, res) => {
  res.json(getBoardState());
});

app.post('/api/tasks', (req, res) => {
  const { title, description = '', columnId = 'todo', assignee = '' } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: 'title and columnId are required' });
  }

  const column = db.board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: 'Column not found' });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description,
    assignee,
    updatedAt: Date.now()
  };

  db.board.tasks[id] = task;
  column.taskIds.push(id);

  const event = { type: 'TASK_CREATED', payload: { task, columnId } };
  broadcast(event);

  res.status(201).json(task);
});

app.put('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const existing = db.board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const { title, description, assignee } = req.body;

  if (title !== undefined) existing.title = title;
  if (description !== undefined) existing.description = description;
  if (assignee !== undefined) existing.assignee = assignee;
  existing.updatedAt = Date.now();

  const event = { type: 'TASK_UPDATED', payload: { task: existing } };
  broadcast(event);

  res.json(existing);
});

app.delete('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const task = db.board.tasks[id];

  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  db.board.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  delete db.board.tasks[id];

  const event = { type: 'TASK_DELETED', payload: { taskId: id } };
  broadcast(event);

  res.status(204).send();
});

app.post('/api/tasks/:id/move', (req, res) => {
  const { id } = req.params;
  const { sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  if (!db.board.tasks[id]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const sourceColumn = db.board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = db.board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: 'Source or destination column not found' });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(taskId => taskId !== id);

  const insertIndex =
    typeof destinationIndex === 'number'
      ? Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length))
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, id);

  db.board.tasks[id].updatedAt = Date.now();

  const event = {
    type: 'TASK_MOVED',
    payload: {
      taskId: id,
      sourceColumnId,
      destinationColumnId,
      destinationIndex: insertIndex
    }
  };

  broadcast(event);
  res.json({ success: true });
});

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'BOARD_STATE', payload: getBoardState() }));

  ws.on('message', raw => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === 'PING') {
        ws.send(JSON.stringify({ type: 'PONG' }));
      }
    } catch (err) {
      console.error('Invalid WS message', err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
