# `public/app.js`

```js
const state = {
  board: null,
  socket: null,
  draggedTaskId: null,
  draggedFromColumnId: null
};

async function fetchBoard() {
  const res = await fetch('/api/board');
  const board = await res.json();
  state.board = board;
  renderBoard();
}

function connectWebSocket() {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  const socket = new WebSocket(`${protocol}//${location.host}`);
  state.socket = socket;

  socket.addEventListener('open', () => {
    console.log('WebSocket connected');
  });

  socket.addEventListener('message', event => {
    const msg = JSON.parse(event.data);

    switch (msg.type) {
      case 'BOARD_STATE':
        state.board = msg.payload;
        renderBoard();
        break;
      case 'TASK_CREATED': {
        const { task, columnId } = msg.payload;
        state.board.tasks[task.id] = task;
        const col = state.board.columns.find(c => c.id === columnId);
        if (col && !col.taskIds.includes(task.id)) col.taskIds.push(task.id);
        renderBoard();
        break;
      }
      case 'TASK_UPDATED': {
        const { task } = msg.payload;
        state.board.tasks[task.id] = task;
        renderBoard();
        break;
      }
      case 'TASK_DELETED': {
        const { taskId } = msg.payload;
        delete state.board.tasks[taskId];
        state.board.columns.forEach(c => {
          c.taskIds = c.taskIds.filter(id => id !== taskId);
        });
        renderBoard();
        break;
      }
      case 'TASK_MOVED': {
        const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = msg.payload;
        const source = state.board.columns.find(c => c.id === sourceColumnId);
        const dest = state.board.columns.find(c => c.id === destinationColumnId);

        if (source) source.taskIds = source.taskIds.filter(id => id !== taskId);
        if (dest) {
          dest.taskIds = dest.taskIds.filter(id => id !== taskId);
          dest.taskIds.splice(destinationIndex, 0, taskId);
        }
        renderBoard();
        break;
      }
    }
  });

  socket.addEventListener('close', () => {
    console.log('WebSocket disconnected, retrying...');
    setTimeout(connectWebSocket, 1500);
  });
}

function renderBoard() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';

  state.board.columns.forEach(column => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.columnId = column.id;

    const title = document.createElement('h2');
    title.textContent = column.title;

    const list = document.createElement('div');
    list.className = 'task-list';
    list.dataset.columnId = column.id;

    list.addEventListener('dragover', e => {
      e.preventDefault();
      list.classList.add('drop-target');
    });

    list.addEventListener('dragleave', () => {
      list.classList.remove('drop-target');
    });

    list.addEventListener('drop', async e => {
      e.preventDefault();
      list.classList.remove('drop-target');

      const taskId = state.draggedTaskId;
      const sourceColumnId = state.draggedFromColumnId;
      const destinationColumnId = column.id;

      if (!taskId || !sourceColumnId || !destinationColumnId) return;

      const destinationIndex = column.taskIds.length;

      await fetch(`/api/tasks/${taskId}/move`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sourceColumnId,
          destinationColumnId,
          destinationIndex
        })
      });
    });

    column.taskIds.forEach(taskId => {
      const task = state.board.tasks[taskId];
      if (!task) return;

      const taskEl = createTaskElement(task, column.id);
      list.appendChild(taskEl);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(list);
    boardEl.appendChild(columnEl);
  });
}

function createTaskElement(task, columnId) {
  const template = document.getElementById('task-template');
  const taskEl = template.content.firstElementChild.cloneNode(true);

  taskEl.dataset.taskId = task.id;
  taskEl.dataset.columnId = columnId;

  taskEl.querySelector('.task-title').textContent = task.title;
  taskEl.querySelector('.task-description').textContent = task.description || '';
  taskEl.querySelector('.task-assignee').value = task.assignee || '';

  taskEl.addEventListener('dragstart', () => {
    state.draggedTaskId = task.id;
    state.draggedFromColumnId = columnId;
    taskEl.classList.add('dragging');
  });

  taskEl.addEventListener('dragend', () => {
    taskEl.classList.remove('dragging');
  });

  taskEl.querySelector('.save-btn').addEventListener('click', async () => {
    const assignee = taskEl.querySelector('.task-assignee').value;

    await fetch(`/api/tasks/${task.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        assignee
      })
    });
  });

  taskEl.querySelector('.delete-btn').addEventListener('click', async () => {
    await fetch(`/api/tasks/${task.id}`, {
      method: 'DELETE'
    });
  });

  return taskEl;
}

document.getElementById('new-task-form').addEventListener('submit', async e => {
  e.preventDefault();

  const title = document.getElementById('task-title').value.trim();
  const description = document.getElementById('task-description').value.trim();
  const columnId = document.getElementById('task-column').value;

  if (!title) return;

  await fetch('/api/tasks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, description, columnId })
  });

  e.target.reset();
});

fetchBoard();
connectWebSocket();
```

