# `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const db = {
  projects: {
    "default-project": {
      id: "default-project",
      name: "Demo Project",
      columns: [
        { id: "todo", title: "To Do", taskIds: [] },
        { id: "in-progress", title: "In Progress", taskIds: [] },
        { id: "done", title: "Done", taskIds: [] }
      ],
      tasks: {}
    }
  }
};

function seedDemoData() {
  const project = db.projects["default-project"];
  const t1 = { id: uuidv4(), title: "Set up project", description: "Initialize app structure", assignee: "Alex" };
  const t2 = { id: uuidv4(), title: "Build board UI", description: "Create kanban layout", assignee: "Sam" };
  const t3 = { id: uuidv4(), title: "Add WebSocket sync", description: "Enable real-time updates", assignee: "Jordan" };

  project.tasks[t1.id] = t1;
  project.tasks[t2.id] = t2;
  project.tasks[t3.id] = t3;

  project.columns[0].taskIds.push(t1.id, t2.id);
  project.columns[1].taskIds.push(t3.id);
}
seedDemoData();

function getProject(projectId) {
  return db.projects[projectId];
}

function broadcast(message, except = null) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN && client !== except) {
      client.send(payload);
    }
  });
}

app.get("/api/projects/:projectId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });
  res.json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { title, description = "", assignee = "", columnId = "todo" } = req.body;
  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const task = {
    id: uuidv4(),
    title: title.trim(),
    description,
    assignee
  };

  project.tasks[task.id] = task;
  const column = project.columns.find((c) => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid columnId" });
  column.taskIds.push(task.id);

  const event = { type: "TASK_CREATED", projectId: project.id, task, columnId };
  broadcast(event);
  res.status(201).json({ task, columnId });
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const task = project.tasks[req.params.taskId];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, assignee } = req.body;
  if (typeof title === "string") task.title = title.trim();
  if (typeof description === "string") task.description = description;
  if (typeof assignee === "string") task.assignee = assignee;

  const event = { type: "TASK_UPDATED", projectId: project.id, task };
  broadcast(event);
  res.json(task);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) return res.status(404).json({ error: "Task not found" });

  delete project.tasks[taskId];
  project.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  const event = { type: "TASK_DELETED", projectId: project.id, taskId };
  broadcast(event);
  res.status(204).send();
});

app.post("/api/projects/:projectId/move-task", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const source = project.columns.find((c) => c.id === sourceColumnId);
  const destination = project.columns.find((c) => c.id === destinationColumnId);

  if (!source || !destination) {
    return res.status(400).json({ error: "Invalid source or destination column" });
  }

  const sourceIndex = source.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(400).json({ error: "Task not found in source column" });
  }

  source.taskIds.splice(sourceIndex, 1);
  destination.taskIds.splice(destinationIndex, 0, taskId);

  const event = {
    type: "TASK_MOVED",
    projectId: project.id,
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex
  };

  broadcast(event);
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "CONNECTED", message: "WebSocket connected" }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      if (msg.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG", ts: Date.now() }));
      }
    } catch (err) {
      ws.send(JSON.stringify({ type: "ERROR", message: "Invalid message format" }));
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
