```js
const PROJECT_ID = "default-project";

let state = {
  project: null,
  socket: null
};

const boardEl = document.getElementById("board");
const dialogEl = document.getElementById("task-dialog");
const formEl = document.getElementById("task-form");
const openCreateBtn = document.getElementById("open-create-task");
const cancelTaskBtn = document.getElementById("cancel-task");
const deleteTaskBtn = document.getElementById("delete-task");
const connectionStatusEl = document.getElementById("connection-status");

const taskIdEl = document.getElementById("task-id");
const taskTitleEl = document.getElementById("task-title");
const taskDescriptionEl = document.getElementById("task-description");
const taskAssigneeEl = document.getElementById("task-assignee");
const taskColumnEl = document.getElementById("task-column");

async function fetchProject() {
  const res = await fetch(`/api/projects/${PROJECT_ID}`);
  state.project = await res.json();
  renderBoard();
}

function renderBoard() {
  if (!state.project) return;
  boardEl.innerHTML = "";

  state.project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const listEl = document.createElement("div");
    listEl.className = "task-list";
    listEl.dataset.columnId = column.id;

    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      const dragging = document.querySelector(".dragging");
      const afterElement = getDragAfterElement(listEl, e.clientY);
      if (!dragging) return;
      if (afterElement == null) {
        listEl.appendChild(dragging);
      } else {
        listEl.insertBefore(dragging, afterElement);
      }
    });

    listEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("text/taskId");
      const sourceColumnId = e.dataTransfer.getData("text/sourceColumnId");
      const destinationColumnId = listEl.dataset.columnId;
      const destinationIndex = [...listEl.children].findIndex(
        (child) => child.dataset.taskId === taskId
      );

      await moveTask(taskId, sourceColumnId, destinationColumnId, destinationIndex);
    });

    column.taskIds.forEach((taskId) => {
      const task = state.project.tasks[taskId];
      if (!task) return;

      const cardEl = document.createElement("div");
      cardEl.className = "task-card";
      cardEl.draggable = true;
      cardEl.dataset.taskId = task.id;
      cardEl.dataset.columnId = column.id;

      cardEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
      `;

      cardEl.addEventListener("click", () => openEditDialog(task.id, column.id));

      cardEl.addEventListener("dragstart", (e) => {
        cardEl.classList.add("dragging");
        e.dataTransfer.setData("text/taskId", task.id);
        e.dataTransfer.setData("text/sourceColumnId", column.id);
      });

      cardEl.addEventListener("dragend", () => {
        cardEl.classList.remove("dragging");
      });

      listEl.appendChild(cardEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(listEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task-card:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;
      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      }
      return closest;
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

function openCreateDialog() {
  formEl.reset();
  taskIdEl.value = "";
  taskColumnEl.value = "todo";
  deleteTaskBtn.classList.add("hidden");
  dialogEl.querySelector("h2").textContent = "Create Task";
  dialogEl.showModal();
}

function findTaskColumn(taskId) {
  return state.project.columns.find((col) => col.taskIds.includes(taskId));
}

function openEditDialog(taskId) {
  const task = state.project.tasks[taskId];
  const column = findTaskColumn(taskId);
  if (!task || !column) return;

  taskIdEl.value = task.id;
  taskTitleEl.value = task.title;
  taskDescriptionEl.value = task.description || "";
  taskAssigneeEl.value = task.assignee || "";
  taskColumnEl.value = column.id;
  deleteTaskBtn.classList.remove("hidden");
  dialogEl.querySelector("h2").textContent = "Edit Task";
  dialogEl.showModal();
}

async function createTask(payload) {
  const res = await fetch(`/api/projects/${PROJECT_ID}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (!res.ok) throw new Error("Failed to create task");
}

async function updateTask(taskId, payload) {
  const res = await fetch(`/api/projects/${PROJECT_ID}/tasks/${taskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (!res.ok) throw new Error("Failed to update task");
}

async function deleteTask(taskId) {
  const res = await fetch(`/api/projects/${PROJECT_ID}/tasks/${taskId}`, {
    method: "DELETE"
  });
  if (!res.ok) throw new Error("Failed to delete task");
}

async function moveTask(taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  const res = await fetch(`/api/projects/${PROJECT_ID}/move-task`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    })
  });
  if (!res.ok) throw new Error("Failed to move task");
}

function applyRealtimeEvent(event) {
  if (!state.project || event.projectId !== state.project.id) return;

  switch (event.type) {
    case "TASK_CREATED": {
      state.project.tasks[event.task.id] = event.task;
      const column = state.project.columns.find((c) => c.id === event.columnId);
      if (column && !column.taskIds.includes(event.task.id)) {
        column.taskIds.push(event.task.id);
      }
      break;
    }
    case "TASK_UPDATED": {
      state.project.tasks[event.task.id] = event.task;
      break;
    }
    case "TASK_DELETED": {
      delete state.project.tasks[event.taskId];
      state.project.columns.forEach((column) => {
        column.taskIds = column.taskIds.filter((id) => id !== event.taskId);
      });
      break;
    }
    case "TASK_MOVED": {
      const source = state.project.columns.find((c) => c.id === event.sourceColumnId);
      const destination = state.project.columns.find((c) => c.id === event.destinationColumnId);
      if (!source || !destination) break;

      source.taskIds = source.taskIds.filter((id) => id !== event.taskId);
      destination.taskIds = destination.taskIds.filter((id) => id !== event.taskId);
      destination.taskIds.splice(event.destinationIndex, 0, event.taskId);
      break;
    }
    default:
      return;
  }

  renderBoard();
}

function connectWebSocket() {
  const protocol = location.protocol === "https:" ? "wss:" : "ws:";
  const socket = new WebSocket(`${protocol}//${location.host}`);
  state.socket = socket;

  socket.addEventListener("open", () => {
    connectionStatusEl.textContent = "Online";
    connectionStatusEl.classList.remove("offline");
    connectionStatusEl.classList.add("online");
  });

  socket.addEventListener("close", () => {
    connectionStatusEl.textContent = "Offline";
    connectionStatusEl.classList.remove("online");
    connectionStatusEl.classList.add("offline");
    setTimeout(connectWebSocket, 1500);
  });

  socket.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data);
    applyRealtimeEvent(msg);
  });
}

formEl.addEventListener("submit", async (e) => {
  e.preventDefault();

  const taskId = taskIdEl.value.trim();
  const payload = {
    title: taskTitleEl.value.trim(),
    description: taskDescriptionEl.value.trim(),
    assignee: taskAssigneeEl.value.trim(),
    columnId: taskColumnEl.value
  };

  try {
    if (taskId) {
      const currentColumn = findTaskColumn(taskId);
      await updateTask(taskId, payload);

      if (currentColumn && currentColumn.id !== payload.columnId) {
        await moveTask(taskId, currentColumn.id, payload.columnId, state.project.columns.find(c => c.id === payload.columnId).taskIds.length);
      }
    } else {
      await createTask(payload);
    }

    dialogEl.close();
  } catch (err) {
    alert(err.message);
  }
});

openCreateBtn.addEventListener("click", openCreateDialog);

cancelTaskBtn.addEventListener("click", () => {
  dialogEl.close();
});

deleteTaskBtn.addEventListener("click", async () => {
  const taskId = taskIdEl.value.trim();
  if (!taskId) return;

  try {
    await deleteTask(taskId);
    dialogEl.close();
  } catch (err) {
    alert(err.message);
  }
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function init() {
  await fetchProject();
  connectWebSocket();
}

init();
