## `server/index.js`

```js
import express from 'express';
import cors from 'cors';
import { WebSocketServer } from 'ws';
import { v4 as uuidv4 } from 'uuid';
import http from 'http';

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const boardState = {
  id: 'board-1',
  version: 1,
  title: 'Project Board',
  columns: [
    {
      id: 'col-1',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    {
      id: 'col-2',
      title: 'In Progress',
      taskIds: []
    },
    {
      id: 'col-3',
      title: 'Done',
      taskIds: []
    }
  ],
  tasks: {
    'task-1': {
      id: 'task-1',
      title: 'Set up project repository',
      description: ''
    },
    'task-2': {
      id: 'task-2',
      title: 'Design initial board UI',
      description: ''
    }
  }
};

app.get('/api/board', (req, res) => {
  res.json(boardState);
});

app.post('/api/tasks', (req, res) => {
  const { columnId, title } = req.body;
  const column = boardState.columns.find(c => c.id === columnId);

  if (!column || !title?.trim()) {
    return res.status(400).json({ error: 'Invalid columnId or title' });
  }

  const id = uuidv4();
  boardState.tasks[id] = {
    id,
    title: title.trim(),
    description: ''
  };
  column.taskIds.push(id);
  boardState.version++;

  broadcast({
    type: 'BOARD_UPDATED',
    payload: boardState
  });

  res.status(201).json(boardState);
});

app.post('/api/columns', (req, res) => {
  const { title } = req.body;
  if (!title?.trim()) {
    return res.status(400).json({ error: 'Title is required' });
  }

  boardState.columns.push({
    id: uuidv4(),
    title: title.trim(),
    taskIds: []
  });
  boardState.version++;

  broadcast({
    type: 'BOARD_UPDATED',
    payload: boardState
  });

  res.status(201).json(boardState);
});

app.patch('/api/tasks/:taskId', (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  const task = boardState.tasks[taskId];
  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  if (typeof title === 'string') task.title = title;
  if (typeof description === 'string') task.description = description;

  boardState.version++;

  broadcast({
    type: 'BOARD_UPDATED',
    payload: boardState
  });

  res.json(boardState);
});

app.post('/api/move-task', (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn || !boardState.tasks[taskId]) {
    return res.status(400).json({ error: 'Invalid move request' });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const safeIndex = Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length));
  destinationColumn.taskIds.splice(safeIndex, 0, taskId);

  boardState.version++;

  broadcast({
    type: 'BOARD_UPDATED',
    payload: boardState
  });

  res.json(boardState);
});

const wss = new WebSocketServer({ server });

function broadcast(message) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(data);
    }
  }
}

wss.on('connection', ws => {
  ws.send(
    JSON.stringify({
      type: 'BOARD_UPDATED',
      payload: boardState
    })
  );

  ws.on('message', raw => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === 'PING') {
        ws.send(JSON.stringify({ type: 'PONG' }));
      }
    } catch (err) {
      console.error('Invalid WS message', err);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
