import React, { useEffect, useMemo, useState } from 'react';
import { DndContext, PointerSensor, useSensor, useSensors, closestCenter } from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
  arrayMove
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { fetchBoard, createTask, createColumn, updateTask, moveTask } from './api';
import { connectSocket } from './socket';

function TaskCard({ task, onEdit }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <input
        className="task-title-input"
        value={task.title}
        onChange={e => onEdit(task.id, { title: e.target.value })}
        onClick={e => e.stopPropagation()}
      />
    </div>
  );
}

function Column({ column, tasks, onAddTask, onEditTask }) {
  const [newTaskTitle, setNewTaskTitle] = useState('');

  return (
    <div className="column">
      <h3>{column.title}</h3>

      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} onEdit={onEditTask} />
          ))}
        </div>
      </SortableContext>

      <div className="add-task">
        <input
          value={newTaskTitle}
          onChange={e => setNewTaskTitle(e.target.value)}
          placeholder="New task"
        />
        <button
          onClick={() => {
            if (!newTaskTitle.trim()) return;
            onAddTask(column.id, newTaskTitle);
            setNewTaskTitle('');
          }}
        >
          Add
        </button>
      </div>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newColumnTitle, setNewColumnTitle] = useState('');

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetchBoard().then(setBoard).catch(console.error);

    const socket = connectSocket(msg => {
      if (msg.type === 'BOARD_UPDATED') {
        setBoard(msg.payload);
      }
    });

    return () => socket.close();
  }, []);

  const columnsWithTasks = useMemo(() => {
    if (!board) return [];
    return board.columns.map(column => ({
      ...column,
      tasks: column.taskIds.map(id => board.tasks[id]).filter(Boolean)
    }));
  }, [board]);

  async function handleAddTask(columnId, title) {
    try {
      await createTask(columnId, title);
    } catch (err) {
      console.error(err);
    }
  }

  async function handleEditTask(taskId, updates) {
    try {
      await updateTask(taskId, updates);
    } catch (err) {
      console.error(err);
    }
  }

  async function handleAddColumn() {
    if (!newColumnTitle.trim()) return;
    try {
      await createColumn(newColumnTitle);
      setNewColumnTitle('');
    } catch (err) {
      console.error(err);
    }
  }

  async function handleDragEnd(event) {
    const { active, over } = event;
    if (!active || !over || !board) return;

    const activeTaskId = active.id;
    const overTaskId = over.id;

    let sourceColumn = null;
    let destinationColumn = null;
    let destinationIndex = 0;

    for (const column of board.columns) {
      if (column.taskIds.includes(activeTaskId)) sourceColumn = column;
      if (column.taskIds.includes(overTaskId)) destinationColumn = column;
    }

    if (!sourceColumn || !destinationColumn) return;

    if (sourceColumn.id === destinationColumn.id) {
      const oldIndex = sourceColumn.taskIds.indexOf(activeTaskId);
      const newIndex = destinationColumn.taskIds.indexOf(overTaskId);

      const reordered = arrayMove(sourceColumn.taskIds, oldIndex, newIndex);

      setBoard(prev => ({
        ...prev,
        columns: prev.columns.map(col =>
          col.id === sourceColumn.id ? { ...col, taskIds: reordered } : col
        )
      }));

      await moveTask({
        taskId: activeTaskId,
        sourceColumnId: sourceColumn.id,
        destinationColumnId: destinationColumn.id,
        destinationIndex: newIndex
      });
    } else {
      destinationIndex = destinationColumn.taskIds.indexOf(overTaskId);

      setBoard(prev => ({
        ...prev,
        columns: prev.columns.map(col => {
          if (col.id === sourceColumn.id) {
            return { ...col, taskIds: col.taskIds.filter(id => id !== activeTaskId) };
          }
          if (col.id === destinationColumn.id) {
            const nextIds = [...col.taskIds];
            nextIds.splice(destinationIndex, 0, activeTaskId);
            return { ...col, taskIds: nextIds };
          }
          return col;
        })
      }));

      await moveTask({
        taskId: activeTaskId,
        sourceColumnId: sourceColumn.id,
        destinationColumnId: destinationColumn.id,
        destinationIndex
      });
    }
  }

  if (!board) return <div className="app">Loading...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>{board.title}</h1>
      </header>

      <div className="add-column-bar">
        <input
          value={newColumnTitle}
          onChange={e => setNewColumnTitle(e.target.value)}
          placeholder="New column"
        />
        <button onClick={handleAddColumn}>Add Column</button>
      </div>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {columnsWithTasks.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={column.tasks}
              onAddTask={handleAddTask}
              onEditTask={handleEditTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

