## `server/server.js`

```js
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import http from "http";
import crypto from "crypto";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const PORT = process.env.PORT || 3000;

// In-memory board state for MVP
const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function broadcast(wss, message, exclude = null) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client !== exclude && client.readyState === 1) {
      client.send(data);
    }
  }
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = boardState.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const id = crypto.randomUUID();
  const task = {
    id,
    title,
    description,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };

  boardState.tasks[id] = task;
  column.taskIds.push(id);

  const payload = { type: "TASK_CREATED", task, columnId };
  broadcast(wss, payload);

  res.status(201).json({ task, columnId });
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks[id];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description } = req.body;
  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;
  task.updatedAt = Date.now();

  const payload = { type: "TASK_UPDATED", task };
  broadcast(wss, payload);

  res.json(task);
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!boardState.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Source or destination column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number"
      ? Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length))
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  const payload = {
    type: "TASK_MOVED",
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex: insertIndex
  };

  broadcast(wss, payload);

  res.json({ success: true });
});

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

const wss = new WebSocketServer({ server });

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "BOARD_STATE", board: boardState }));

  ws.on("message", raw => {
    try {
      const message = JSON.parse(raw.toString());

      // Optional: support direct websocket mutations too
      if (message.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

