## `client/app.js`

```js
const API_BASE = "http://localhost:3000/api";
const WS_URL = "ws://localhost:3000";

let boardState = {
  columns: [],
  tasks: {}
};

let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("task-form");
const taskTitleInput = document.getElementById("task-title");
const taskDescriptionInput = document.getElementById("task-description");
const taskColumnInput = document.getElementById("task-column");

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/board`);
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  const ws = new WebSocket(WS_URL);

  ws.addEventListener("open", () => {
    console.log("WebSocket connected");
  });

  ws.addEventListener("message", event => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case "BOARD_STATE":
        boardState = message.board;
        renderBoard();
        break;

      case "TASK_CREATED": {
        const { task, columnId } = message;
        boardState.tasks[task.id] = task;
        const column = boardState.columns.find(c => c.id === columnId);
        if (column && !column.taskIds.includes(task.id)) {
          column.taskIds.push(task.id);
        }
        renderBoard();
        break;
      }

      case "TASK_UPDATED": {
        boardState.tasks[message.task.id] = message.task;
        renderBoard();
        break;
      }

      case "TASK_MOVED": {
        const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = message;
        const source = boardState.columns.find(c => c.id === sourceColumnId);
        const dest = boardState.columns.find(c => c.id === destinationColumnId);

        if (source) {
          source.taskIds = source.taskIds.filter(id => id !== taskId);
        }
        if (dest) {
          dest.taskIds = dest.taskIds.filter(id => id !== taskId);
          dest.taskIds.splice(destinationIndex, 0, taskId);
        }
        renderBoard();
        break;
      }
    }
  });

  ws.addEventListener("close", () => {
    console.log("WebSocket disconnected, retrying...");
    setTimeout(connectWebSocket, 1000);
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  for (const column of boardState.columns) {
    const columnEl = document.getElementById("column-template").content.firstElementChild.cloneNode(true);
    columnEl.dataset.columnId = column.id;
    columnEl.querySelector(".column-header").textContent = column.title;

    const taskListEl = columnEl.querySelector(".task-list");
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      await moveTask(draggedTaskId, draggedFromColumnId, destinationColumnId);
      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    for (const taskId of column.taskIds) {
      const task = boardState.tasks[taskId];
      if (!task) continue;

      const taskEl = document.getElementById("task-template").content.firstElementChild.cloneNode(true);
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.querySelector(".task-title").textContent = task.title;
      taskEl.querySelector(".task-description").textContent = task.description || "";

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    }

    boardEl.appendChild(columnEl);
  }
}

async function createTask(title, description, columnId) {
  const res = await fetch(`${API_BASE}/tasks`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ title, description, columnId })
  });

  if (!res.ok) {
    const err = await res.json();
    alert(err.error || "Failed to create task");
  }
}

async function moveTask(taskId, sourceColumnId, destinationColumnId, destinationIndex = 0) {
  const res = await fetch(`${API_BASE}/move-task`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    })
  });

  if (!res.ok) {
    const err = await res.json();
    alert(err.error || "Failed to move task");
  }
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnInput.value;

  if (!title) return;

  await createTask(title, description, columnId);

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnInput.value = "todo";
});

fetchBoard();
connectWebSocket();
```

