## `server/src/store.ts`

```ts
import { Board } from "./types";
import { v4 as uuid } from "uuid";

export const board: Board = {
  id: "board-1",
  title: "Team Project Board",
  columns: [
    { id: "todo", title: "Todo", taskIds: [] },
    { id: "in-progress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

export function createTask(title: string, description = "") {
  const id = uuid();
  board.tasks[id] = { id, title, description };
  board.columns[0].taskIds.push(id);
  return board.tasks[id];
}

export function moveTask(
  taskId: string,
  sourceColumnId: string,
  destinationColumnId: string,
  sourceIndex: number,
  destinationIndex: number
) {
  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) return;

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
}
```

## `server/src/index.ts`

```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { board, createTask, moveTask } from "./store";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/board", (_req, res) => {
  res.json(board);
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", ({ title, description }) => {
    createTask(title, description);
    io.emit("board:update", board);
  });

  socket.on("task:move", (payload) => {
    moveTask(
      payload.taskId,
      payload.sourceColumnId,
      payload.destinationColumnId,
      payload.sourceIndex,
      payload.destinationIndex
    );
    io.emit("board:update", board);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

