## `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { Board as BoardType } from "../types";
import Column from "./Column";

type Props = {
  board: BoardType;
};

export default function Board({ board }: Props) {
  const sensors = useSensors(useSensor(PointerSensor));

  const findColumnByTaskId = (taskId: string) => {
    return board.columns.find((column) => column.taskIds.includes(taskId));
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const sourceColumn = findColumnByTaskId(taskId);
    if (!sourceColumn) return;

    const destinationColumn =
      board.columns.find((col) => col.taskIds.includes(overId)) ||
      board.columns.find((col) => col.id === overId);

    if (!destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);

    let destinationIndex = destinationColumn.taskIds.indexOf(overId);
    if (destinationIndex === -1) {
      destinationIndex = destinationColumn.taskIds.length;
    }

    if (
      sourceColumn.id === destinationColumn.id &&
      sourceIndex === destinationIndex
    ) {
      return;
    }

    import("../socket").then(({ socket }) => {
      socket.emit("task:move", {
        taskId,
        sourceColumnId: sourceColumn.id,
        destinationColumnId: destinationColumn.id,
        sourceIndex,
        destinationIndex
      });
    });
  };

  return (
    <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        {board.columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            tasks={column.taskIds.map((id) => board.tasks[id]).filter(Boolean)}
          />
        ))}
      </div>
    </DndContext>
  );
}
```

