## `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["1", "2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "1": { id: "1", title: "Set up project" },
    "2": { id: "2", title: "Build drag-and-drop UI" }
  },
  columnOrder: ["todo", "doing", "done"]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/task", (req, res) => {
  const { title, columnId } = req.body;
  if (!title || !columnId || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = Date.now().toString();
  board.tasks[id] = { id, title };
  board.columns[columnId].taskIds.push(id);

  broadcast({ type: "BOARD_UPDATE", board });
  res.json(board);
});

app.post("/api/move", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  if (
    !board.tasks[taskId] ||
    !board.columns[fromColumnId] ||
    !board.columns[toColumnId]
  ) {
    return res.status(400).json({ error: "Invalid move data" });
  }

  const fromTasks = board.columns[fromColumnId].taskIds;
  const toTasks = board.columns[toColumnId].taskIds;

  const oldIndex = fromTasks.indexOf(taskId);
  if (oldIndex === -1) {
    return res.status(400).json({ error: "Task not found in source column" });
  }

  fromTasks.splice(oldIndex, 1);
  toTasks.splice(toIndex, 0, taskId);

  broadcast({ type: "BOARD_UPDATE", board });
  res.json(board);
});

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATE", board }));
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

