# 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project repo" },
    "task-2": { id: "task-2", title: "Design board layout" },
    "task-3": { id: "task-3", title: "Implement drag and drop" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", ({ columnId, title }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    state.tasks[id] = { id, title };
    state.columns[columnId].taskIds.push(id);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    const sourceTaskIds = state.columns[sourceColumnId].taskIds;
    const sourceIndex = sourceTaskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceTaskIds.splice(sourceIndex, 1);

    const destTaskIds = state.columns[destColumnId].taskIds;
    destTaskIds.splice(destIndex, 0, taskId);

    io.emit("state:update", state);
  });

  socket.on("task:reorder", ({ columnId, taskId, destIndex }) => {
    const taskIds = state.columns[columnId].taskIds;
    const sourceIndex = taskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    taskIds.splice(sourceIndex, 1);
    taskIds.splice(destIndex, 0, taskId);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    state.columns[columnId].taskIds = state.columns[columnId].taskIds.filter(id => id !== taskId);
    delete state.tasks[taskId];
    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

