# 5) `public/app.js`

```js
const socket = io();
const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let appState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

function render() {
  if (!appState) return;
  boardEl.innerHTML = "";

  appState.columnOrder.forEach((columnId) => {
    const column = appState.columns[columnId];
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);

    columnNode.dataset.columnId = column.id;
    columnNode.querySelector(".column-title").textContent = column.title;

    const taskList = columnNode.querySelector(".task-list");
    taskList.dataset.columnId = column.id;

    column.taskIds.forEach((taskId) => {
      const task = appState.tasks[taskId];
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);

      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;
      taskNode.querySelector(".task-title").textContent = task.title;

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
      });

      taskNode.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId: column.id });
      });

      taskList.appendChild(taskNode);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskList, e.clientY);
      let destIndex;

      if (!afterElement) {
        destIndex = taskList.children.length;
      } else {
        destIndex = Array.from(taskList.children).indexOf(afterElement);
      }

      const destColumnId = taskList.dataset.columnId;

      if (draggedFromColumnId === destColumnId) {
        socket.emit("task:reorder", {
          columnId: destColumnId,
          taskId: draggedTaskId,
          destIndex
        });
      } else {
        socket.emit("task:move", {
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destColumnId,
          destIndex
        });
      }

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    const form = columnNode.querySelector(".add-task-form");
    const input = columnNode.querySelector(".task-input");

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const title = input.value.trim();
      if (!title) return;
      socket.emit("task:add", { columnId: column.id, title });
      input.value = "";
    });

    boardEl.appendChild(columnNode);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}
```

