## `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Build drag-and-drop UI" }
  },
  columnOrder: ["todo", "doing", "done"]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/task", (req, res) => {
  const { content, columnId } = req.body;
  if (!content || !columnId || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = `task-${Date.now()}`;
  board.tasks[id] = { id, content };
  board.columns[columnId].taskIds.push(id);

  broadcast({ type: "board:update", board });
  res.json(board);
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board:init", board }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message);

      if (data.type === "task:move") {
        const { taskId, sourceColumnId, destColumnId, destIndex } = data;

        const source = board.columns[sourceColumnId];
        const dest = board.columns[destColumnId];

        if (!source || !dest || !board.tasks[taskId]) return;

        source.taskIds = source.taskIds.filter((id) => id !== taskId);
        dest.taskIds.splice(destIndex, 0, taskId);

        broadcast({ type: "board:update", board });
      }

      if (data.type === "task:create") {
        const { content, columnId } = data;
        if (!content || !board.columns[columnId]) return;

        const id = `task-${Date.now()}`;
        board.tasks[id] = { id, content };
        board.columns[columnId].taskIds.push(id);

        broadcast({ type: "board:update", board });
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

