const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let board = {
  columns: [
    { id: "todo", title: "To Do" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ],
  tasks: [
    { id: "1", title: "Set up project", columnId: "todo" },
    { id: "2", title: "Build drag and drop", columnId: "doing" },
    { id: "3", title: "Add real-time sync", columnId: "done" }
  ]
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:create", (task) => {
    const newTask = {
      id: String(Date.now() + Math.random()),
      title: task.title || "Untitled Task",
      columnId: task.columnId || "todo"
    };
    board.tasks.push(newTask);
    io.emit("task:created", newTask);
  });

  socket.on("task:move", ({ taskId, columnId }) => {
    const task = board.tasks.find((t) => t.id === taskId);
    if (!task) return;
    task.columnId = columnId;
    io.emit("task:moved", { taskId, columnId });
  });

  socket.on("task:delete", ({ taskId }) => {
    board.tasks = board.tasks.filter((t) => t.id !== taskId);
    io.emit("task:deleted", { taskId });
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

