# 5) `public/app.js`

```js
const socket = io();

let boardState = {
  columns: [],
  tasks: []
};

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("task-form");
const taskInput = document.getElementById("task-input");
const columnSelect = document.getElementById("column-select");

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("task:created", (task) => {
  boardState.tasks.push(task);
  renderBoard();
});

socket.on("task:moved", ({ taskId, columnId }) => {
  const task = boardState.tasks.find((t) => t.id === taskId);
  if (task) {
    task.columnId = columnId;
    renderBoard();
  }
});

socket.on("task:deleted", ({ taskId }) => {
  boardState.tasks = boardState.tasks.filter((t) => t.id !== taskId);
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  const columnId = columnSelect.value;
  if (!title) return;

  socket.emit("task:create", { title, columnId });
  taskInput.value = "";
  taskInput.focus();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    const tasks = boardState.tasks.filter((task) => task.columnId === column.id);

    tasks.forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <span>${escapeHtml(task.title)}</span>
        <button data-task-id="${task.id}">Delete</button>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        taskEl.classList.add("dragging");
        e.dataTransfer.setData("text/plain", task.id);
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const deleteBtn = taskEl.querySelector("button");
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    columnEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    columnEl.addEventListener("drop", (e) => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");
      const taskId = e.dataTransfer.getData("text/plain");
      socket.emit("task:move", { taskId, columnId: column.id });
    });

    boardEl.appendChild(columnEl);
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
