## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design UI" }
  ],
  doing: [
    { id: "3", title: "Build drag-and-drop" }
  ],
  done: [
    { id: "4", title: "Create initial backlog" }
  ]
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:add", ({ column, title }) => {
    if (!board[column] || !title?.trim()) return;

    const task = {
      id: Date.now().toString() + Math.random().toString(36).slice(2, 7),
      title: title.trim()
    };

    board[column].push(task);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const fromTasks = board[fromColumn];
    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);

    const insertIndex =
      typeof toIndex === "number" && toIndex >= 0 && toIndex <= board[toColumn].length
        ? toIndex
        : board[toColumn].length;

    board[toColumn].splice(insertIndex, 0, task);
    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, column }) => {
    if (!board[column]) return;
    board[column] = board[column].filter((t) => t.id !== taskId);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

