## 5) `public/app.js`

```js
const socket = io();

let boardState = {
  todo: [],
  doing: [],
  done: []
};

let draggedTaskId = null;
let draggedFromColumn = null;

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

function renderBoard() {
  ["todo", "doing", "done"].forEach((column) => {
    const list = document.querySelector(`[data-list="${column}"]`);
    list.innerHTML = "";

    boardState[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      const title = document.createElement("span");
      title.textContent = task.title;

      const delBtn = document.createElement("button");
      delBtn.textContent = "Delete";
      delBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, column });
      });

      taskEl.appendChild(title);
      taskEl.appendChild(delBtn);

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumn = column;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        draggedFromColumn = null;
        taskEl.classList.remove("dragging");
        document.querySelectorAll(".task-list").forEach((l) => l.classList.remove("drag-over"));
      });

      list.appendChild(taskEl);
    });
  });

  setupDropZones();
}

function setupDropZones() {
  document.querySelectorAll(".task-list").forEach((list) => {
    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      const toColumn = list.dataset.list;
      if (!draggedTaskId || !draggedFromColumn) return;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        fromColumn: draggedFromColumn,
        toColumn,
        toIndex: boardState[toColumn].length
      });
    });
  });
}

document.querySelectorAll("[data-add]").forEach((button) => {
  button.addEventListener("click", () => {
    const column = button.dataset.add;
    const input = document.querySelector(`[data-input="${column}"]`);
    const title = input.value.trim();

    if (!title) return;

    socket.emit("task:add", { column, title });
    input.value = "";
  });
});

document.querySelectorAll("[data-input]").forEach((input) => {
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      const column = input.dataset.input;
      const title = input.value.trim();

      if (!title) return;

      socket.emit("task:add", { column, title });
      input.value = "";
    }
  });
});
```

