const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["1", "2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "1": { id: "1", content: "Set up project" },
    "2": { id: "2", content: "Build drag-and-drop board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", ({ columnId, content }) => {
    const id = Date.now().toString();
    board.tasks[id] = { id, content };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    const sourceIds = board.columns[sourceColumnId].taskIds;
    const destIds = board.columns[destColumnId].taskIds;

    const sourceIndex = sourceIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceIds.splice(sourceIndex, 1);
    destIds.splice(destIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(id => id !== taskId);
    delete board.tasks[taskId];
    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
