## 5. `public/app.js`

```js
const socket = io();
const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let boardData = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("board:update", (data) => {
  boardData = data;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardData.columnOrder.forEach((columnId) => {
    const column = boardData.columns[columnId];
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleEl = columnNode.querySelector("h2");
    const taskListEl = columnNode.querySelector(".task-list");
    const formEl = columnNode.querySelector(".task-form");
    const inputEl = formEl.querySelector("input");

    titleEl.textContent = column.title;
    columnNode.dataset.columnId = column.id;
    taskListEl.dataset.columnId = column.id;

    column.taskIds.forEach((taskId) => {
      const task = boardData.tasks[taskId];
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      const contentEl = taskNode.querySelector(".task-content");
      const deleteBtn = taskNode.querySelector(".delete-btn");

      contentEl.textContent = task.content;
      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
      });

      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId: column.id });
      });

      taskListEl.appendChild(taskNode);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      let destIndex = column.taskIds.length;

      if (afterElement) {
        destIndex = Array.from(taskListEl.children).indexOf(afterElement);
      }

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        destColumnId: column.id,
        destIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    formEl.addEventListener("submit", (e) => {
      e.preventDefault();
      const content = inputEl.value.trim();
      if (!content) return;
      socket.emit("task:create", { columnId: column.id, content });
      inputEl.value = "";
    });

    boardEl.appendChild(columnNode);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}
```

