const boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["todo", "doing", "done"],
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Design board UI" },
    "task-3": { id: "task-3", content: "Implement drag and drop" }
  }
};

io.on("connection", (socket) => {
  socket.emit("board:init", boardState);

  socket.on("task:add", ({ columnId, content }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    boardState.tasks[id] = { id, content };
    boardState.columns[columnId].taskIds.push(id);
    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromTaskIds = boardState.columns[fromColumnId].taskIds;
    const toTaskIds = boardState.columns[toColumnId].taskIds;

    const fromIndex = fromTaskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    fromTaskIds.splice(fromIndex, 1);
    toTaskIds.splice(toIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("task:reorder", ({ columnId, taskId, toIndex }) => {
    const taskIds = boardState.columns[columnId].taskIds;
    const fromIndex = taskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    taskIds.splice(fromIndex, 1);
    taskIds.splice(toIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    const taskIds = boardState.columns[columnId].taskIds;
    boardState.columns[columnId].taskIds = taskIds.filter((id) => id !== taskId);
    delete boardState.tasks[taskId];
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
