## 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Design task board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:add", ({ columnId, content }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    board.tasks[id] = { id, content };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceIds = board.columns[sourceColumnId].taskIds;
    const targetIds = board.columns[targetColumnId].taskIds;

    const sourceIndex = sourceIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceIds.splice(sourceIndex, 1);

    if (sourceColumnId === targetColumnId) {
      targetIds.splice(targetIndex, 0, taskId);
    } else {
      targetIds.splice(targetIndex, 0, taskId);
    }

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(id => id !== taskId);
    delete board.tasks[taskId];
    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

