## `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

const state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {}
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

function sendState(ws) {
  ws.send(JSON.stringify({ type: "state", payload: state }));
}

wss.on("connection", ws => {
  sendState(ws);

  ws.on("message", message => {
    let data;
    try {
      data = JSON.parse(message);
    } catch {
      return;
    }

    if (data.type === "add_task") {
      const { columnId, text } = data.payload;
      const id = "task_" + Date.now() + "_" + Math.floor(Math.random() * 10000);

      state.tasks[id] = { id, text };
      state.columns[columnId].taskIds.push(id);

      broadcast({ type: "state", payload: state });
    }

    if (data.type === "move_task") {
      const { taskId, fromColumnId, toColumnId, toIndex } = data.payload;

      const fromTasks = state.columns[fromColumnId].taskIds;
      const toTasks = state.columns[toColumnId].taskIds;

      const oldIndex = fromTasks.indexOf(taskId);
      if (oldIndex !== -1) {
        fromTasks.splice(oldIndex, 1);
      }

      const insertIndex = Math.max(0, Math.min(toIndex, toTasks.length));
      toTasks.splice(insertIndex, 0, taskId);

      broadcast({ type: "state", payload: state });
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

