# 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Build drag-and-drop board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

let nextTaskId = 3;

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:add", ({ columnId, content }) => {
    if (!content || !board.columns[columnId]) return;

    const id = `task-${nextTaskId++}`;
    board.tasks[id] = { id, content };
    board.columns[columnId].taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const source = board.columns[sourceColumnId];
    const target = board.columns[targetColumnId];

    if (!source || !target || !board.tasks[taskId]) return;

    source.taskIds = source.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof targetIndex === "number" && targetIndex >= 0
        ? targetIndex
        : target.taskIds.length;

    target.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!board.tasks[taskId] || !board.columns[columnId]) return;

    delete board.tasks[taskId];
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

