## 6. `public/app.js`

```js
const socket = io();
const boardEl = document.getElementById("board");

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columnOrder.forEach((columnId) => {
    const column = boardState.columns[columnId];
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
      <div class="add-task">
        <input type="text" placeholder="New task..." />
        <button>Add</button>
      </div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.innerHTML = `
        <button class="delete-btn">×</button>
        <span>${escapeHtml(task.content)}</span>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId: column.id });
      });

      taskListEl.appendChild(taskEl);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = taskListEl.dataset.columnId;
      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex: boardState.columns[targetColumnId].taskIds.length
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    const input = columnEl.querySelector("input");
    const addButton = columnEl.querySelector("button");

    addButton.addEventListener("click", () => {
      const content = input.value.trim();
      if (!content) return;
      socket.emit("task:add", { columnId: column.id, content });
      input.value = "";
    });

    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") addButton.click();
    });

    boardEl.appendChild(columnEl);
  });
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}
```

