## `server.js`
```js
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));
app.use(express.json());

let state = {
  tasks: [
    { id: '1', title: 'Set up project', status: 'todo' },
    { id: '2', title: 'Build drag and drop UI', status: 'doing' },
    { id: '3', title: 'Test collaboration', status: 'done' }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get('/api/state', (req, res) => {
  res.json(state);
});

app.post('/api/tasks', (req, res) => {
  const { title } = req.body;
  if (!title || !title.trim()) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const task = {
    id: Date.now().toString(),
    title: title.trim(),
    status: 'todo'
  };

  state.tasks.push(task);
  broadcast({ type: 'state', payload: state });
  res.json(task);
});

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'state', payload: state }));

  ws.on('message', message => {
    try {
      const data = JSON.parse(message);

      if (data.type === 'move-task') {
        const { taskId, status } = data.payload;
        const task = state.tasks.find(t => t.id === taskId);
        if (task && ['todo', 'doing', 'done'].includes(status)) {
          task.status = status;
          broadcast({ type: 'state', payload: state });
        }
      }

      if (data.type === 'create-task') {
        const title = data.payload?.title?.trim();
        if (title) {
          const task = {
            id: Date.now().toString(),
            title,
            status: 'todo'
          };
          state.tasks.push(task);
          broadcast({ type: 'state', payload: state });
        }
      }
    } catch (err) {
      console.error('Invalid message:', err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

