## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

const state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project" },
    "task-2": { id: "task-2", title: "Create first board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

function broadcastState() {
  io.emit("state:update", state);
}

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:create", ({ columnId, title }) => {
    if (!columnId || !title || !state.columns[columnId]) return;

    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    state.tasks[id] = { id, title: title.trim() || "Untitled Task" };
    state.columns[columnId].taskIds.push(id);

    broadcastState();
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    if (
      !taskId ||
      !state.tasks[taskId] ||
      !state.columns[fromColumnId] ||
      !state.columns[toColumnId]
    ) {
      return;
    }

    const fromTaskIds = state.columns[fromColumnId].taskIds;
    const toTaskIds = state.columns[toColumnId].taskIds;

    const currentIndex = fromTaskIds.indexOf(taskId);
    if (currentIndex === -1) return;

    fromTaskIds.splice(currentIndex, 1);

    const safeIndex =
      typeof toIndex === "number" && toIndex >= 0 && toIndex <= toTaskIds.length
        ? toIndex
        : toTaskIds.length;

    toTaskIds.splice(safeIndex, 0, taskId);

    broadcastState();
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!taskId || !columnId || !state.columns[columnId] || !state.tasks[taskId]) {
      return;
    }

    state.columns[columnId].taskIds = state.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );
    delete state.tasks[taskId];

    broadcastState();
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

