## 5) `public/app.js`

```js
const socket = io();

let appState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const addTaskForm = document.getElementById("add-task-form");
const columnSelect = document.getElementById("column-select");
const taskTitleInput = document.getElementById("task-title");

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

addTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.emit("task:create", { columnId, title });
  taskTitleInput.value = "";
});

function render() {
  if (!appState) return;

  boardEl.innerHTML = "";

  appState.columnOrder.forEach((columnId) => {
    const column = appState.columns[columnId];
    const columnEl = document.createElement("section");
    columnEl.className = "column";

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drop-target");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-target");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const toColumnId = taskListEl.dataset.columnId;
      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      let toIndex = appState.columns[toColumnId].taskIds.length;

      if (afterElement) {
        toIndex = Array.from(taskListEl.children).indexOf(afterElement);
      }

      socket.emit("task:move", {
        taskId: draggedTaskId,
        fromColumnId: draggedFromColumnId,
        toColumnId,
        toIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = appState.tasks[taskId];
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      const textEl = document.createElement("span");
      textEl.textContent = task.title;

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", {
          taskId: task.id,
          columnId: column.id
        });
      });

      taskEl.appendChild(textEl);
      taskEl.appendChild(deleteBtn);

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [
    ...container.querySelectorAll(".task:not(.dragging)")
  ];

  let closest = { offset: Number.NEGATIVE_INFINITY, element: null };

  for (const child of draggableElements) {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, element: child };
    }
  }

  return closest.element;
}
```

