## `public/app.js`

```js
const socket = new WebSocket(`ws://${location.host}`);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumn = null;

socket.addEventListener('message', event => {
  const data = JSON.parse(event.data);

  if (data.type === 'init' || data.type === 'state_update') {
    boardState = data.state;
    renderBoard();
  }
});

function renderBoard() {
  if (!boardState) return;

  Object.entries(boardState.columns).forEach(([columnId, tasks]) => {
    const list = document.getElementById(columnId);
    list.innerHTML = '';

    list.addEventListener('dragover', e => {
      e.preventDefault();
    });

    list.addEventListener('drop', e => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumn) return;

      socket.send(JSON.stringify({
        type: 'move_task',
        taskId: draggedTaskId,
        fromColumn: draggedFromColumn,
        toColumn: columnId,
        toIndex: tasks.length
      }));

      draggedTaskId = null;
      draggedFromColumn = null;
    });

    tasks.forEach(task => {
      const el = document.createElement('div');
      el.className = 'task';
      el.draggable = true;
      el.textContent = task.title;
      el.dataset.taskId = task.id;

      el.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedFromColumn = columnId;
        el.classList.add('dragging');
      });

      el.addEventListener('dragend', () => {
        el.classList.remove('dragging');
      });

      list.appendChild(el);
    });
  });
}

document.querySelectorAll('.add-task-form').forEach(form => {
  form.addEventListener('submit', e => {
    e.preventDefault();
    const input = form.querySelector('input');
    const title = input.value.trim();
    const columnId = form.dataset.column;

    if (!title) return;

    socket.send(JSON.stringify({
      type: 'add_task',
      columnId,
      title
    }));

    input.value = '';
  });
});
```

