## 5. `public/app.js`

```js
const socket = io();
const boardEl = document.getElementById("board");

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columnOrder.forEach((columnId) => {
    const column = boardState.columns[columnId];
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = column.title;
    columnEl.appendChild(title);

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = taskList.dataset.columnId;
      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex: boardState.columns[targetColumnId].taskIds.length
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "×";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId: column.id });
      });

      const text = document.createElement("span");
      text.textContent = task.title;

      taskEl.appendChild(deleteBtn);
      taskEl.appendChild(text);
      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(taskList);

    const addTask = document.createElement("div");
    addTask.className = "add-task";

    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = "New task";

    const button = document.createElement("button");
    button.textContent = "Add";
    button.addEventListener("click", () => {
      const title = input.value.trim();
      if (!title) return;
      socket.emit("task:add", { columnId: column.id, title });
      input.value = "";
    });

    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") button.click();
    });

    addTask.appendChild(input);
    addTask.appendChild(button);
    columnEl.appendChild(addTask);

    boardEl.appendChild(columnEl);
  });
}
```

