const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

const state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project" },
    "task-2": { id: "task-2", title: "Design board UI" },
    "task-3": { id: "task-3", title: "Implement drag and drop" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", ({ columnId, title }) => {
    if (!columnId || !title || !state.columns[columnId]) return;

    const id = `task-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    state.tasks[id] = { id, title };
    state.columns[columnId].taskIds.push(id);

    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = state.columns[fromColumnId];
    const toColumn = state.columns[toColumnId];

    if (!taskId || !fromColumn || !toColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex =
      typeof toIndex === "number" && toIndex >= 0
        ? Math.min(toIndex, toColumn.taskIds.length)
        : toColumn.taskIds.length;

    toColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!taskId || !columnId || !state.columns[columnId]) return;

    state.columns[columnId].taskIds = state.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );
    delete state.tasks[taskId];

    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
