## `server.js`

```js
const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));

let state = {
  tasks: [
    { id: '1', title: 'Set up project', status: 'todo' },
    { id: '2', title: 'Build drag and drop', status: 'doing' },
    { id: '3', title: 'Test collaboration', status: 'done' }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'init', state }));

  ws.on('message', message => {
    try {
      const data = JSON.parse(message);

      if (data.type === 'add_task') {
        const task = {
          id: Date.now().toString(),
          title: data.title,
          status: 'todo'
        };
        state.tasks.push(task);
        broadcast({ type: 'state', state });
      }

      if (data.type === 'move_task') {
        const task = state.tasks.find(t => t.id === data.id);
        if (task) {
          task.status = data.status;
          broadcast({ type: 'state', state });
        }
      }
    } catch (err) {
      console.error('Invalid message:', err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

