# 8. Risk engine

This validates max order size and basic price checks.

## `src/risk.rs`

```rust
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::{
    bus::EventBus,
    messages::{OrderType, RiskCheckedOrder, RiskDecision},
};

pub async fn run_risk(bus: EventBus) {
    let mut order_rx = bus.order_tx.subscribe();
    let max_order_qty = 1000_u64;

    loop {
        match order_rx.recv().await {
            Ok(order) => {
                let decision = if order.qty > max_order_qty {
                    RiskDecision::Rejected("order qty exceeds max limit".to_string())
                } else if matches!(order.order_type, OrderType::Limit) && order.price.is_none() {
                    RiskDecision::Rejected("limit order missing price".to_string())
                } else {
                    RiskDecision::Approved
                };

                let checked = RiskCheckedOrder { order, decision };
                let _ = bus.risk_tx.send(checked.clone());
                info!("risk processed order: {:?}", checked);
            }
            Err(RecvError::Lagged(n)) => {
                warn!("risk lagged by {} messages", n);
            }
            Err(RecvError::Closed) => break,
        }
    }
}
```

