# 9. OMS

Tracks order lifecycle and forwards approved orders to execution.

## `src/oms.rs`

```rust
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};
use uuid::Uuid;

use crate::{
    bus::EventBus,
    messages::{ExecutionReport, OrderStatus, RiskDecision},
};

pub type OrderStore = Arc<DashMap<Uuid, OrderStatus>>;

pub async fn run_oms(bus: EventBus, store: OrderStore) {
    let mut risk_rx = bus.risk_tx.subscribe();

    loop {
        match risk_rx.recv().await {
            Ok(checked) => match checked.decision {
                RiskDecision::Approved => {
                    store.insert(checked.order.order_id, OrderStatus::New);
                    let _ = bus.order_tx.send(checked.order.clone());
                    info!("oms forwarded approved order: {:?}", checked.order);
                }
                RiskDecision::Rejected(reason) => {
                    store.insert(checked.order.order_id, OrderStatus::Rejected);

                    let report = ExecutionReport {
                        order_id: checked.order.order_id,
                        status: OrderStatus::Rejected,
                        filled_qty: 0,
                        remaining_qty: checked.order.qty,
                        avg_price: None,
                        reason: Some(reason),
                        ts: chrono::Utc::now(),
                    };

                    let _ = bus.exec_tx.send(report.clone());
                    info!("oms rejected order: {:?}", report);
                }
            },
            Err(RecvError::Lagged(n)) => {
                warn!("oms lagged by {} messages", n);
            }
            Err(RecvError::Closed) => break,
        }
    }
}
```

