# 10. Execution gateway

This simulates sending to an exchange and receiving fills.

## `src/execution.rs`

```rust
use chrono::Utc;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::{
    bus::EventBus,
    messages::{ExecutionReport, OrderStatus},
};

pub async fn run_execution(bus: EventBus) {
    let mut order_rx = bus.order_tx.subscribe();

    loop {
        match order_rx.recv().await {
            Ok(order) => {
                let sent = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Sent,
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    avg_price: None,
                    reason: None,
                    ts: Utc::now(),
                };
                let _ = bus.exec_tx.send(sent.clone());
                info!("execution sent order: {:?}", sent);

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    remaining_qty: 0,
                    avg_price: order.price,
                    reason: None,
                    ts: Utc::now(),
                };
                let _ = bus.exec_tx.send(fill.clone());
                info!("execution fill report: {:?}", fill);
            }
            Err(RecvError::Lagged(n)) => {
                warn!("execution lagged by {} messages", n);
            }
            Err(RecvError::Closed) => break,
        }
    }
}
```

