impl crate::strategy_trait::StrategyEngine for ThresholdStrategy {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest> {
        if tick.last > self.threshold {
            Some(OrderRequest {
                order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.qty,
                order_type: OrderType::Limit,
                price: Some(tick.ask),
                ts: Utc::now(),
            })
        } else {
            None
        }
    }
