# src/strategy.rs

A simple strategy example. In production, strategies should be isolated and configurable.

```rust
use crate::bus::Topic;
use crate::types::{MarketTick, Qty, Side, Signal, StrategyId};
use std::time::Instant;
use tracing::info;

pub async fn run_strategy(
    strategy_id: StrategyId,
    md_topic: Topic<MarketTick>,
    signal_topic: Topic<Signal>,
) {
    let mut rx = md_topic.subscribe();
    let mut last_price: Option<i64> = None;

    loop {
        match rx.recv().await {
            Ok(tick) => {
                let current = tick.last.0;

                if let Some(prev) = last_price {
                    let diff = current - prev;

                    if diff >= 3 {
                        let signal = Signal {
                            strategy_id,
                            instrument_id: tick.instrument_id,
                            side: Side::Buy,
                            price: tick.ask,
                            qty: Qty(10),
                            created_at: Instant::now(),
                        };
                        signal_topic.publish(signal);
                        info!("strategy={} generated BUY signal", strategy_id);
                    } else if diff <= -3 {
                        let signal = Signal {
                            strategy_id,
                            instrument_id: tick.instrument_id,
                            side: Side::Sell,
                            price: tick.bid,
                            qty: Qty(10),
                            created_at: Instant::now(),
                        };
                        signal_topic.publish(signal);
                        info!("strategy={} generated SELL signal", strategy_id);
                    }
                }

                last_price = Some(current);
            }
            Err(_) => {}
        }
    }
}
```

