# src/risk.rs

Risk must be fast and deterministic in the hot path.

```rust
use crate::bus::Topic;
use crate::types::{OrderRequest, Qty, Signal};
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::time::Instant;
use tracing::{info, warn};

pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_notional: i64,
}

pub struct OrderIdGenerator {
    next: AtomicU64,
}

impl OrderIdGenerator {
    pub fn new(start: u64) -> Self {
        Self {
            next: AtomicU64::new(start),
        }
    }

    pub fn next_id(&self) -> u64 {
        self.next.fetch_add(1, Ordering::Relaxed)
    }
}

pub async fn run_risk(
    signal_topic: Topic<Signal>,
    order_topic: Topic<OrderRequest>,
    limits: Arc<RiskLimits>,
    id_gen: Arc<OrderIdGenerator>,
) {
    let mut rx = signal_topic.subscribe();

    loop {
        match rx.recv().await {
            Ok(signal) => {
                if signal.qty.0 > limits.max_order_qty.0 {
                    warn!("risk reject: qty too large");
                    continue;
                }

                let notional = signal.price.0 * signal.qty.0 as i64;
                if notional > limits.max_notional {
                    warn!("risk reject: notional too large");
                    continue;
                }

                let order = OrderRequest {
                    order_id: id_gen.next_id(),
                    strategy_id: signal.strategy_id,
                    instrument_id: signal.instrument_id,
                    side: signal.side,
                    price: signal.price,
                    qty: signal.qty,
                    created_at: Instant::now(),
                };

                order_topic.publish(order);
                info!("risk approved order");
            }
            Err(_) => {}
        }
    }
}
```

