# src/oms.rs

OMS tracks order state. For now it just forwards to execution and emits events.

```rust
use crate::bus::Topic;
use crate::types::{OrderEvent, OrderRequest, OrderStatus};
use dashmap::DashMap;
use std::sync::Arc;
use std::time::Instant;
use tracing::info;

pub struct OrderStore {
    pub states: DashMap<u64, OrderStatus>,
}

impl OrderStore {
    pub fn new() -> Self {
        Self {
            states: DashMap::new(),
        }
    }
}

pub async fn run_oms(
    order_topic: Topic<OrderRequest>,
    exec_topic: Topic<OrderRequest>,
    order_event_topic: Topic<OrderEvent>,
    store: Arc<OrderStore>,
) {
    let mut rx = order_topic.subscribe();

    loop {
        match rx.recv().await {
            Ok(order) => {
                store.states.insert(order.order_id, OrderStatus::New);

                order_event_topic.publish(OrderEvent {
                    order_id: order.order_id,
                    status: OrderStatus::New,
                    ts: Instant::now(),
                });

                exec_topic.publish(order.clone());

                store.states.insert(order.order_id, OrderStatus::Sent);
                order_event_topic.publish(OrderEvent {
                    order_id: order.order_id,
                    status: OrderStatus::Sent,
                    ts: Instant::now(),
                });

                info!("oms forwarded order_id={}", order.order_id);
            }
            Err(_) => {}
        }
    }
}
```

