# src/state.rs

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use uuid::Uuid;

use crate::types::{ExecutionReport, OrderStatus, Qty, Symbol};

#[derive(Debug, Clone)]
pub struct Position {
    pub symbol: Symbol,
    pub net_qty: Qty,
}

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order_id: Uuid,
    pub symbol: Symbol,
    pub status: OrderStatus,
    pub filled_qty: Qty,
}

#[derive(Clone, Default)]
pub struct SharedState {
    pub positions: Arc<Mutex<HashMap<Symbol, Position>>>,
    pub orders: Arc<Mutex<HashMap<Uuid, OrderRecord>>>,
}

impl SharedState {
    pub fn apply_execution(&self, report: &ExecutionReport, symbol: &str, signed_fill: Qty) {
        {
            let mut orders = self.orders.lock().unwrap();
            if let Some(order) = orders.get_mut(&report.order_id) {
                order.status = report.status.clone();
                order.filled_qty = report.filled_qty;
            }
        }

        {
            let mut positions = self.positions.lock().unwrap();
            let pos = positions.entry(symbol.to_string()).or_insert(Position {
                symbol: symbol.to_string(),
                net_qty: 0,
            });
            pos.net_qty += signed_fill;
        }
    }

    pub fn insert_order(&self, order_id: Uuid, symbol: String) {
        let mut orders = self.orders.lock().unwrap();
        orders.insert(order_id, OrderRecord {
            order_id,
            symbol,
            status: OrderStatus::PendingNew,
            filled_qty: 0,
        });
    }

    pub fn get_position(&self, symbol: &str) -> Qty {
        let positions = self.positions.lock().unwrap();
        positions.get(symbol).map(|p| p.net_qty).unwrap_or(0)
    }
}
