pub fn start_strategy(md_rx: Receiver<MarketData>, signal_tx: Sender<Signal>) {
    thread::spawn(move || {
        while let Ok(md) = md_rx.recv() {
            let spread = md.ask - md.bid;

            if spread <= 2 && md.ask < 100_05 {
                let signal = Signal {
                    symbol: md.symbol.clone(),
                    side: Side::Buy,
                    qty: 10,
                    limit_price: Some(md.ask),
                    ts: now_nanos(),
                };

                if signal_tx.send(signal).is_err() {
                    break;
                }
            }
        }

        info!("strategy stopped");
    });
}
