# src/risk.rs

```rust
use std::thread;

use crossbeam::channel::{Receiver, Sender};
use tracing::{info, warn};
use uuid::Uuid;

use crate::state::SharedState;
use crate::types::{NewOrder, OrderType, Side, Signal};

pub fn start_risk(
    signal_rx: Receiver<Signal>,
    order_tx: Sender<NewOrder>,
    state: SharedState,
    max_abs_position: i64,
    max_order_qty: i64,
) {
    thread::spawn(move || {
        while let Ok(signal) = signal_rx.recv() {
            if signal.qty > max_order_qty {
                warn!("risk reject: qty too large");
                continue;
            }

            let current_pos = state.get_position(&signal.symbol);
            let projected = match signal.side {
                Side::Buy => current_pos + signal.qty,
                Side::Sell => current_pos - signal.qty,
            };

            if projected.abs() > max_abs_position {
                warn!("risk reject: position limit exceeded");
                continue;
            }

            let order = NewOrder {
                order_id: Uuid::new_v4(),
                symbol: signal.symbol.clone(),
                side: signal.side,
                qty: signal.qty,
                order_type: if signal.limit_price.is_some() {
                    OrderType::Limit
                } else {
                    OrderType::Market
                },
                limit_price: signal.limit_price,
                ts: signal.ts,
            };

            state.insert_order(order.order_id, order.symbol.clone());

            if order_tx.send(order).is_err() {
                break;
            }
        }

        info!("risk engine stopped");
    });
}
