```rust
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use crossbeam::channel::{Receiver, Sender};
use tracing::info;

use crate::state::SharedState;
use crate::types::{ExecutionReport, NewOrder, OrderStatus, Side};

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

pub fn start_execution_gateway(
    order_rx: Receiver<NewOrder>,
    exec_report_tx: Sender<ExecutionReport>,
    state: SharedState,
) {
    thread::spawn(move || {
        while let Ok(order) = order_rx.recv() {
            thread::sleep(Duration::from_micros(50));

            let report = ExecutionReport {
                order_id: order.order_id,
                status: OrderStatus::Filled,
                filled_qty: order.qty,
                remaining_qty: 0,
                avg_price: order.limit_price,
                reason: None,
                ts: now_nanos(),
            };

            let signed_fill = match order.side {
                Side::Buy => order.qty,
                Side::Sell => -order.qty,
            };

            state.apply_execution(&report, &order.symbol, signed_fill);

            if exec_report_tx.send(report).is_err() {
                break;
            }
        }

        info!("execution gateway stopped");
    });
}
