async fn run_strategy(
    mut market_rx: broadcast::Receiver<MarketTick>,
    order_tx: mpsc::Sender<OrderRequest>,
) {
    while let Ok(tick) = market_rx.recv().await {
        if tick.last < dec!(100.50) {
            let order = OrderRequest {
                strategy_id: "mean_reversion_1".to_string(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: dec!(10),
                order_type: OrderType::Limit,
                limit_price: Some(tick.bid),
                client_order_id: Uuid::new_v4(),
                ts: Utc::now(),
