use common::{OrderRequest, RiskCheckedOrder, RiskDecision};
use rust_decimal_macros::dec;
use tokio::sync::mpsc;

async fn run_risk(
    mut order_rx: mpsc::Receiver<OrderRequest>,
    checked_tx: mpsc::Sender<RiskCheckedOrder>,
) {
    while let Some(order) = order_rx.recv().await {
        let decision = if order.qty > dec!(1000) {
            RiskDecision::Rejected("order size exceeds max limit".to_string())
        } else {
            RiskDecision::Approved
        };

        let checked = RiskCheckedOrder { order, decision };

        if checked_tx.send(checked).await.is_err() {
            break;
        }
    }
}

