use common::{ExecutionReport, OrderRequest, OrderStatus, RiskCheckedOrder, RiskDecision};
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::mpsc;

#[derive(Clone)]
struct OmsState {
    orders: Arc<DashMap<common::OrderId, OrderRequest>>,
}

async fn run_oms(
    mut checked_rx: mpsc::Receiver<RiskCheckedOrder>,
    exec_tx: mpsc::Sender<OrderRequest>,
    report_tx: mpsc::Sender<ExecutionReport>,
    state: OmsState,
) {
    while let Some(checked) = checked_rx.recv().await {
        match checked.decision {
            RiskDecision::Approved => {
                state
                    .orders
                    .insert(checked.order.client_order_id, checked.order.clone());

                let report = ExecutionReport {
                    order_id: checked.order.client_order_id,
                    symbol: checked.order.symbol.clone(),
                    status: OrderStatus::New,
                    filled_qty: rust_decimal::Decimal::ZERO,
                    remaining_qty: checked.order.qty,
                    avg_fill_price: None,
                    reason: None,
                    ts: chrono::Utc::now(),
                };

                let _ = report_tx.send(report).await;
                let _ = exec_tx.send(checked.order).await;
            }
            RiskDecision::Rejected(reason) => {
                let report = ExecutionReport {
                    order_id: checked.order.client_order_id,
                    symbol: checked.order.symbol.clone(),
                    status: OrderStatus::Rejected,
                    filled_qty: rust_decimal::Decimal::ZERO,
                    remaining_qty: checked.order.qty,
                    avg_fill_price: None,
                    reason: Some(reason),
                    ts: chrono::Utc::now(),
                };

                let _ = report_tx.send(report).await;
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let (checked_tx, checked_rx) = mpsc::channel(1024);
    let (exec_tx, mut exec_rx) = mpsc::channel(1024);
    let (report_tx, mut report_rx) = mpsc::channel(1024);

    let state = OmsState {
        orders: Arc::new(DashMap::new()),
    };

    tokio::spawn(run_oms(checked_rx, exec_tx, report_tx, state));

    tokio::spawn(async move {
        while let Some(order) = exec_rx.recv().await {
            println!("OMS routed to execution: {:?}", order);
        }
    });

    tokio::spawn(async move {
        while let Some(report) = report_rx.recv().await {
            println!("OMS report: {:?}", report);
        }
    });

    let checked = common::RiskCheckedOrder {
        order: common::OrderRequest {
            strategy_id: "s1".to_string(),
            symbol: "AAPL".to_string(),
            side: common::Side::Buy,
            qty: rust_decimal_macros::dec!(10),
            order_type: common::OrderType::Limit,
            limit_price: Some(rust_decimal_macros::dec!(100.0)),
            client_order_id: uuid::Uuid::new_v4(),
            ts: chrono::Utc::now(),
        },
        decision: common::RiskDecision::Approved,
    };

    let _ = checked_tx.send(checked).await;
    tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
}
