use chrono::Utc;
use common::{ExecutionReport, OrderRequest, OrderStatus};
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};

async fn run_execution(
    mut exec_rx: mpsc::Receiver<OrderRequest>,
    report_tx: mpsc::Sender<ExecutionReport>,
) {
    while let Some(order) = exec_rx.recv().await {
        let ack = ExecutionReport {
            order_id: order.client_order_id,
            symbol: order.symbol.clone(),
            status: OrderStatus::Acked,
            filled_qty: rust_decimal::Decimal::ZERO,
            remaining_qty: order.qty,
            avg_fill_price: None,
            reason: None,
            ts: Utc::now(),
        };

        let _ = report_tx.send(ack).await;

        sleep(Duration::from_millis(5)).await;

        let fill = ExecutionReport {
            order_id: order.client_order_id,
            symbol: order.symbol.clone(),
            status: OrderStatus::Filled,
            filled_qty: order.qty,
            remaining_qty: rust_decimal::Decimal::ZERO,
            avg_fill_price: order.limit_price,
            reason: None,
            ts: Utc::now(),
        };

        let _ = report_tx.send(fill).await;
    }
}

#[tokio::main]
async fn main() {
    let (exec_tx, exec_rx) = mpsc::channel(1024);
    let (report_tx, mut report_rx) = mpsc::channel(1024);

    tokio::spawn(run_execution(exec_rx, report_tx));

    tokio::spawn(async move {
        while let Some(report) = report_rx.recv().await {
            println!("execution report: {:?}", report);
