use common::{ExecutionReport, OrderStatus};
use dashmap::DashMap;
use rust_decimal::Decimal;
use std::sync::Arc;
use tokio::sync::mpsc;

#[derive(Clone)]
struct PositionState {
    positions: Arc<DashMap<String, Decimal>>,
}

async fn run_positions(
    mut report_rx: mpsc::Receiver<ExecutionReport>,
    state: PositionState,
) {
    while let Some(report) = report_rx.recv().await {
        if let OrderStatus::Filled = report.status {
            let mut entry = state
                .positions
                .entry(report.symbol.clone())
                .or_insert(Decimal::ZERO);
            *entry += report.filled_qty;
        }
    }
}

#[tokio::main]
async fn main() {
    let (report_tx, report_rx) = mpsc::channel(1024);
    let state = PositionState {
        positions: Arc::new(DashMap::new()),
    };

    let state_clone = state.clone();
    tokio::spawn(run_positions(report_rx, state_clone));

    let report = common::ExecutionReport {
        order_id: uuid::Uuid::new_v4(),
        symbol: "AAPL".to_string(),
        status: common::OrderStatus::Filled,
        filled_qty: Decimal::new(10, 0),
        remaining_qty: Decimal::ZERO,
        avg_fill_price: Some(Decimal::new(10000, 2)),
        reason: None,
        ts: chrono::Utc::now(),
    };

    let _ = report_tx.send(report).await;
    tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;

    for item in state.positions.iter() {
        println!("position {} => {}", item.key(), item.value());
    }
}
