use crate::types::MarketTick;
use chrono::Utc;
use crossbeam::channel::Sender;
use rand::Rng;
use std::{thread, time::Duration};

pub struct MarketDataEngine {
    tx_tick: Sender<MarketTick>,
}

impl MarketDataEngine {
    pub fn new(tx_tick: Sender<MarketTick>) -> Self {
        Self { tx_tick }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut rng = rand::thread_rng();
            let instrument_id = 1_u64;
            let mut px = 1_000_000_i64;

            loop {
                let delta: i64 = rng.gen_range(-20..=20);
                px += delta;

                let tick = MarketTick {
                    instrument_id,
                    bid: px - 5,
                    ask: px + 5,
                    last: px,
                    ts: Utc::now(),
                };

                if self.tx_tick.send(tick).is_err() {
                    break;
                }

                thread::sleep(Duration::from_millis(1));
            }
        });
    }
}
