## `src/strategy.rs`

A simple example strategy: buy if price drops enough, sell if rises enough.

```rust
use crate::types::{MarketTick, OrderRequest, OrderType, Price, Side, StrategyId};
use crossbeam::channel::{Receiver, Sender};
use std::thread;

pub struct SimpleStrategy {
    strategy_id: StrategyId,
    rx_tick: Receiver<MarketTick>,
    tx_order_req: Sender<OrderRequest>,
    last_price: Option<Price>,
    threshold: Price,
    order_qty: i64,
}

impl SimpleStrategy {
    pub fn new(
        strategy_id: StrategyId,
        rx_tick: Receiver<MarketTick>,
        tx_order_req: Sender<OrderRequest>,
        threshold: Price,
        order_qty: i64,
    ) -> Self {
        Self {
            strategy_id,
            rx_tick,
            tx_order_req,
            last_price: None,
            threshold,
            order_qty,
        }
    }

    pub fn start(mut self) {
        thread::spawn(move || {
            while let Ok(tick) = self.rx_tick.recv() {
                if let Some(last) = self.last_price {
                    let diff = tick.last - last;

                    let req = if diff <= -self.threshold {
                        Some(OrderRequest {
                            strategy_id: self.strategy_id,
                            instrument_id: tick.instrument_id,
                            side: Side::Buy,
                            qty: self.order_qty,
                            order_type: OrderType::Limit,
                            limit_price: Some(tick.ask),
                        })
                    } else if diff >= self.threshold {
                        Some(OrderRequest {
                            strategy_id: self.strategy_id,
                            instrument_id: tick.instrument_id,
                            side: Side::Sell,
                            qty: self.order_qty,
                            order_type: OrderType::Limit,
                            limit_price: Some(tick.bid),
                        })
                    } else {
                        None
                    };

                    if let Some(order) = req {
                        let _ = self.tx_order_req.send(order);
                    }
                }

                self.last_price = Some(tick.last);
            }
        });
    }
}
```

