## `src/risk.rs`

Pre-trade risk checks.

```rust
use crate::types::{ApprovedOrder, OrderId, OrderRequest, Side};
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;
use std::thread;

pub struct RiskEngine {
    rx_order_req: Receiver<OrderRequest>,
    tx_approved: Sender<ApprovedOrder>,
    max_order_qty: i64,
    max_abs_position: i64,
}

impl RiskEngine {
    pub fn new(
        rx_order_req: Receiver<OrderRequest>,
        tx_approved: Sender<ApprovedOrder>,
        max_order_qty: i64,
        max_abs_position: i64,
    ) -> Self {
        Self {
            rx_order_req,
            tx_approved,
            max_order_qty,
            max_abs_position,
        }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut next_order_id: OrderId = 1;
            let mut positions: HashMap<u64, i64> = HashMap::new();

            while let Ok(req) = self.rx_order_req.recv() {
                if req.qty <= 0 || req.qty > self.max_order_qty {
                    continue;
                }

                let current_pos = *positions.get(&req.instrument_id).unwrap_or(&0);
                let projected = match req.side {
                    Side::Buy => current_pos + req.qty,
                    Side::Sell => current_pos - req.qty,
                };

                if projected.abs() > self.max_abs_position {
                    continue;
                }

                positions.insert(req.instrument_id, projected);

                let approved = ApprovedOrder {
                    order_id: next_order_id,
                    request: req,
                    ts: Utc::now(),
                };
                next_order_id += 1;

                let _ = self.tx_approved.send(approved);
            }
        });
    }
}
```

Note: in a real system, position reservation should be more nuanced:
- reserve on order acceptance
- release on reject/cancel
- update on fills
- distinguish working orders from filled positions

