## `src/oms.rs`

```rust
use crate::types::{ApprovedOrder, ExecutionReport, ExecutionReportStatus};
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;
use std::thread;

pub struct Oms {
    rx_approved: Receiver<ApprovedOrder>,
    tx_exec: Sender<ApprovedOrder>,
    rx_reports: Receiver<ExecutionReport>,
}

impl Oms {
    pub fn new(
        rx_approved: Receiver<ApprovedOrder>,
        tx_exec: Sender<ApprovedOrder>,
        rx_reports: Receiver<ExecutionReport>,
    ) -> Self {
        Self {
            rx_approved,
            tx_exec,
            rx_reports,
        }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut live_orders: HashMap<u64, ApprovedOrder> = HashMap::new();

            loop {
                crossbeam::select! {
                    recv(self.rx_approved) -> msg => {
                        match msg {
                            Ok(order) => {
                                live_orders.insert(order.order_id, order.clone());
                                let _ = self.tx_exec.send(order);
                            }
                            Err(_) => break,
                        }
                    }
                    recv(self.rx_reports) -> msg => {
                        match msg {
                            Ok(report) => {
                                match report.status {
                                    ExecutionReportStatus::Filled
                                    | ExecutionReportStatus::Rejected
                                    | ExecutionReportStatus::Cancelled => {
                                        live_orders.remove(&report.order_id);
                                    }
                                    _ => {}
                                }
                            }
                            Err(_) => break,
                        }
                    }
                }
            }
        });
    }
}
```

