use crate::types::{ApprovedOrder, ExecutionReport, ExecutionReportStatus};
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::{thread, time::Duration};

pub struct ExecutionGateway {
    rx_exec: Receiver<ApprovedOrder>,
    tx_reports: Sender<ExecutionReport>,
}

impl ExecutionGateway {
    pub fn new(
        rx_exec: Receiver<ApprovedOrder>,
        tx_reports: Sender<ExecutionReport>,
    ) -> Self {
        Self { rx_exec, tx_reports }
    }

    pub fn start(self) {
        thread::spawn(move || {
            while let Ok(order) = self.rx_exec.recv() {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    status: ExecutionReportStatus::Acked,
                    filled_qty: 0,
                    remaining_qty: order.request.qty,
                    avg_price: None,
                    reason: None,
                    ts: Utc::now(),
                };
                let _ = self.tx_reports.send(ack);

                thread::sleep(Duration::from_millis(2));

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    status: ExecutionReportStatus::Filled,
                    filled_qty: order.request.qty,
                    remaining_qty: 0,
                    avg_price: order.request.limit_price,
                    reason: None,
                    ts: Utc::now(),
                };
                let _ = self.tx_reports.send(fill);
            }
        });
    }
}
