use crate::types::{ExecutionReport, ExecutionReportStatus, Side};
use crossbeam::channel::Receiver;
use std::collections::HashMap;
use std::thread;

pub struct PositionEngine {
    rx_reports: Receiver<(ExecutionReport, Side, u64)>,
}

impl PositionEngine {
    pub fn new(rx_reports: Receiver<(ExecutionReport, Side, u64)>) -> Self {
        Self { rx_reports }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut positions: HashMap<u64, i64> = HashMap::new();

            while let Ok((report, side, instrument_id)) = self.rx_reports.recv() {
                if report.status == ExecutionReportStatus::Filled {
                    let pos = positions.entry(instrument_id).or_insert(0);
                    match side {
                        Side::Buy => *pos += report.filled_qty,
                        Side::Sell => *pos -= report.filled_qty,
                    }
                    println!("Updated position instrument={} pos={}", instrument_id, pos);
                }
            }
        });
    }
}
