use oms::Oms;
use risk::RiskEngine;
use strategy::SimpleStrategy;
use types::{ApprovedOrder, ExecutionReport};

use std::{collections::HashMap, thread, time::Duration};

fn main() {
    let (tx_tick, rx_tick) = event_bus::bounded_channel(1024);
    let (tx_order_req, rx_order_req) = event_bus::bounded_channel(1024);
    let (tx_approved, rx_approved) = event_bus::bounded_channel::<ApprovedOrder>(1024);
    let (tx_exec, rx_exec) = event_bus::bounded_channel::<ApprovedOrder>(1024);
    let (tx_reports, rx_reports) = event_bus::bounded_channel::<ExecutionReport>(1024);

    let md = MarketDataEngine::new(tx_tick);
    md.start();

    let strategy = SimpleStrategy::new(1, rx_tick, tx_order_req, 10, 100);
    strategy.start();

    let risk = RiskEngine::new(rx_order_req, tx_approved, 1000, 10_000);
    risk.start();

    let (tx_reports_for_oms, rx_reports_for_oms) = unbounded();
    let (tx_reports_for_state, rx_reports_for_state) = unbounded();

    thread::spawn(move || {
        let mut order_meta: HashMap<u64, (types::Side, u64)> = HashMap::new();

        while let Ok(report) = rx_reports.recv() {
            let _ = tx_reports_for_oms.send(report.clone());

            if let Some((side, instrument_id)) = order_meta.get(&report.order_id).cloned() {
                let _ = tx_reports_for_state.send((report.clone(), side, instrument_id));
            }

            // In a real system, this metadata belongs in OMS/shared state.
        }
    });

    let oms = Oms::new(rx_approved, tx_exec, rx_reports_for_oms);
    oms.start();

    let exec = ExecutionGateway::new(rx_exec, tx_reports);
    exec.start();

    let positions = positions::PositionEngine::new(rx_reports_for_state);
    positions.start();

    loop {
        thread::sleep(Duration::from_secs(1));
    }
