    pub symbol: Symbol,
    pub venue: Venue,
    pub status: OrderStatus,
    pub filled_qty: Decimal,
    pub remaining_qty: Decimal,
    pub avg_price: Option<Decimal>,
    pub reason: Option<String>,
    pub ts_exchange: Timestamp,
    pub ts_received: Timestamp,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Position {
    pub symbol: Symbol,
    pub net_qty: Decimal,
    pub avg_price: Decimal,
    pub realized_pnl: Decimal,
}

#[derive(Debug, Clone)]
pub enum PlatformEvent {
    MarketData(MarketTick),
    NewOrder(NewOrder),
    ExecutionReport(ExecutionReport),
    RiskReject {
        order: NewOrder,
        reason: String,
    },
}

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("max order quantity exceeded")]
    MaxOrderQtyExceeded,
    #[error("position limit exceeded")]
    PositionLimitExceeded,
    #[error("price missing for limit order")]
    MissingPrice,
}

pub struct RiskEngine {
    max_order_qty: Decimal,
    max_position_abs: Decimal,
    positions: HashMap<Symbol, Position>,
}

impl RiskEngine {
    pub fn new(max_order_qty: Decimal, max_position_abs: Decimal) -> Self {
        Self {
            max_order_qty,
            max_position_abs,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), RiskError> {
        if order.qty > self.max_order_qty {
            return Err(RiskError::MaxOrderQtyExceeded);
        }

        if matches!(order.order_type, OrderType::Limit) && order.price.is_none() {
            return Err(RiskError::MissingPrice);
        }

        let current_pos = self
            .positions
            .get(&order.symbol)
            .map(|p| p.net_qty)
            .unwrap_or(Decimal::ZERO);

        let signed_qty = match order.side {
            Side::Buy => order.qty,
            Side::Sell => -order.qty,
        };

        let projected = current_pos + signed_qty;
        if projected.abs() > self.max_position_abs {
            return Err(RiskError::PositionLimitExceeded);
        }

        Ok(())
    }

    pub fn on_fill(&mut self, report: &ExecutionReport) {
        if !matches!(report.status, OrderStatus::PartiallyFilled | OrderStatus::Filled) {
            return;
        }

        let fill_qty = report.filled_qty;
        let fill_price = report.avg_price.unwrap_or(Decimal::ZERO);

        let pos = self.positions.entry(report.symbol.clone()).or_insert(Position {
            symbol: report.symbol.clone(),
            net_qty: Decimal::ZERO,
            avg_price: Decimal::ZERO,
            realized_pnl: Decimal::ZERO,
        });

        // Simplified position update logic
        pos.net_qty += fill_qty;
        pos.avg_price = fill_price;
    }
}

pub struct Oms {
    orders: HashMap<OrderId, NewOrder>,
    statuses: HashMap<OrderId, OrderStatus>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
            statuses: HashMap::new(),
        }
    }

    pub fn register_order(&mut self, order: NewOrder) {
        self.statuses
            .insert(order.client_order_id, OrderStatus::PendingNew);
        self.orders.insert(order.client_order_id, order);
    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) {
        self.statuses.insert(report.order_id, report.status.clone());
    }
}

pub struct StrategyEngine {
    strategy_id: StrategyId,
    last_ticks: HashMap<Symbol, MarketTick>,
}

impl StrategyEngine {
    pub fn new(strategy_id: StrategyId) -> Self {
        Self {
            strategy_id,
            last_ticks: HashMap::new(),
        }
    }

    pub fn on_market_data(&mut self, tick: MarketTick) -> Option<NewOrder> {
        let symbol = tick.symbol.clone();
        self.last_ticks.insert(symbol.clone(), tick.clone());

        // Example toy strategy:
        // If spread is wide enough, place a buy order near bid.
        let spread = tick.ask - tick.bid;
        let threshold = Decimal::new(5, 2); // 0.05

        if spread > threshold {
            Some(NewOrder {
                strategy_id: self.strategy_id.clone(),
                venue: tick.venue.clone(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: Decimal::new(1, 0),
                order_type: OrderType::Limit,
                price: Some(tick.bid),
                client_order_id: Uuid::new_v4(),
                ts_created: now_nanos(),
            })
        } else {
            None
        }
    }
}

pub struct ExecutionGateway {
    tx_exec_reports: Sender<PlatformEvent>,
}

impl ExecutionGateway {
    pub fn new(tx_exec_reports: Sender<PlatformEvent>) -> Self {
        Self { tx_exec_reports }
    }

    pub fn send_order(&self, order: NewOrder) {
        let tx = self.tx_exec_reports.clone();

        // Simulated async exchange ack/fill
        thread::spawn(move || {
            thread::sleep(Duration::from_millis(1));

            let ack = ExecutionReport {
                order_id: order.client_order_id,
                venue_order_id: Some(format!("VENUE-{}", order.client_order_id)),
                symbol: order.symbol.clone(),
                venue: order.venue.clone(),
                status: OrderStatus::New,
                filled_qty: Decimal::ZERO,
                remaining_qty: order.qty,
                avg_price: order.price,
                reason: None,
                ts_exchange: now_nanos(),
                ts_received: now_nanos(),
            };

            tx.send(PlatformEvent::ExecutionReport(ack)).unwrap();

            thread::sleep(Duration::from_millis(1));

            let fill = ExecutionReport {
                order_id: order.client_order_id,
                venue_order_id: Some(format!("VENUE-{}", order.client_order_id)),
                symbol: order.symbol.clone(),
                venue: order.venue.clone(),
                status: OrderStatus::Filled,
                filled_qty: order.qty,
                remaining_qty: Decimal::ZERO,
                avg_price: order.price,
                reason: None,
                ts_exchange: now_nanos(),
                ts_received: now_nanos(),
            };

            tx.send(PlatformEvent::ExecutionReport(fill)).unwrap();
        });
    }
}

pub struct MarketDataGateway {
    tx_events: Sender<PlatformEvent>,
}

impl MarketDataGateway {
    pub fn new(tx_events: Sender<PlatformEvent>) -> Self {
        Self { tx_events }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut px = Decimal::new(10000, 2); // 100.00
            loop {
                let tick = MarketTick {
                    venue: "SIM".to_string(),
                    symbol: "FOO".to_string(),
                    bid: px,
                    ask: px + Decimal::new(10, 2),
                    bid_size: Decimal::new(10, 0),
                    ask_size: Decimal::new(12, 0),
                    ts_exchange: now_nanos(),
                    ts_received: now_nanos(),
                };

                if self.tx_events.send(PlatformEvent::MarketData(tick)).is_err() {
                    break;
                }

                px += Decimal::new(1, 2);
                thread::sleep(Duration::from_millis(10));
            }
        });
    }
}

fn event_loop(rx: Receiver<PlatformEvent>, tx: Sender<PlatformEvent>) {
    let mut strategy = StrategyEngine::new("mean_reversion_1".to_string());
    let mut risk = RiskEngine::new(Decimal::new(100, 0), Decimal::new(1000, 0));
    let mut oms = Oms::new();
    let exec = ExecutionGateway::new(tx.clone());

    while let Ok(event) = rx.recv() {
        match event {
            PlatformEvent::MarketData(tick) => {
                if let Some(order) = strategy.on_market_data(tick) {
                    match risk.check_order(&order) {
                        Ok(_) => {
                            oms.register_order(order.clone());
                            exec.send_order(order);
                        }
                        Err(e) => {
                            error!("risk rejected order: {}", e);
                        }
                    }
                }
            }
            PlatformEvent::ExecutionReport(report) => {
                oms.on_execution_report(&report);
                risk.on_fill(&report);
                info!(
                    "execution report: order_id={}, status={:?}, filled_qty={}",
                    report.order_id, report.status, report.filled_qty
                );
            }
            PlatformEvent::NewOrder(order) => {
                match risk.check_order(&order) {
                    Ok(_) => {
                        oms.register_order(order.clone());
                        exec.send_order(order);
                    }
                    Err(e) => {
                        error!("risk rejected external order: {}", e);
                    }
                }
            }
            PlatformEvent::RiskReject { order, reason } => {
                error!(
                    "risk reject: order_id={}, symbol={}, reason={}",
                    order.client_order_id, order.symbol, reason
                );
            }
        }
    }
}

fn main() {
    tracing_subscriber::fmt::init();

    let (tx, rx) = bounded::<PlatformEvent>(1024);

    let md = MarketDataGateway::new(tx.clone());
    md.start();

    event_loop(rx, tx);

    info!("platform shut down");
}
```

