# src/risk.rs

```rust
use crate::types::{OrderRequest, Side};
use rust_decimal::Decimal;
use std::collections::HashMap;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("order quantity exceeds max allowed")]
    MaxOrderQtyExceeded,
    #[error("order notional exceeds max allowed")]
    MaxOrderNotionalExceeded,
    #[error("position limit exceeded")]
    PositionLimitExceeded,
    #[error("price required for limit order")]
    MissingLimitPrice,
}

#[derive(Clone)]
pub struct RiskLimits {
    pub max_order_qty: Decimal,
    pub max_order_notional: Decimal,
    pub max_abs_position: Decimal,
}

pub struct RiskEngine {
    limits: RiskLimits,
    positions: HashMap<String, Decimal>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn update_position(&mut self, symbol: &str, delta: Decimal) {
        let entry = self.positions.entry(symbol.to_string()).or_default();
        *entry += delta;
    }

    pub fn validate(&self, order: &OrderRequest) -> Result<(), RiskError> {
        if order.qty > self.limits.max_order_qty {
            return Err(RiskError::MaxOrderQtyExceeded);
        }

        let px = match order.price {
            Some(p) => p,
            None => {
                if matches!(order.order_type, crate::types::OrderType::Limit) {
                    return Err(RiskError::MissingLimitPrice);
                }
                Decimal::ZERO
            }
        };

        let notional = px * order.qty;
        if notional > self.limits.max_order_notional {
            return Err(RiskError::MaxOrderNotionalExceeded);
        }

        let current_pos = self.positions.get(&order.symbol).cloned().unwrap_or_default();
        let projected = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected.abs() > self.limits.max_abs_position {
            return Err(RiskError::PositionLimitExceeded);
        }

        Ok(())
    }
}
