use crate::types::{ExecutionReport, OrderId, OrderRequest, OrderStatus, ValidatedOrder};
use chrono::Utc;
use dashmap::DashMap;
use uuid::Uuid;

pub struct OrderState {
    pub order_id: OrderId,
    pub request: OrderRequest,
    pub status: OrderStatus,
}

pub struct Oms {
    orders: DashMap<OrderId, OrderState>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: DashMap::new(),
        }
    }

    pub fn register(&self, req: OrderRequest) -> ValidatedOrder {
        let order_id = Uuid::new_v4();
        let state = OrderState {
            order_id,
            request: req.clone(),
            status: OrderStatus::New,
        };
        self.orders.insert(order_id, state);

        ValidatedOrder {
            order_id,
            request: req,
            ts: Utc::now(),
        }
    }

    pub fn on_execution_report(&self, report: &ExecutionReport) {
        if let Some(mut entry) = self.orders.get_mut(&report.order_id) {
            entry.status = report.status.clone();
        }
    }
}
