use crate::types::{ExecutionReport, OrderStatus, Side};
use dashmap::DashMap;
use rust_decimal::Decimal;

#[derive(Clone, Default)]
pub struct PositionService {
    positions: DashMap<String, Decimal>,
}

impl PositionService {
    pub fn new() -> Self {
        Self {
            positions: DashMap::new(),
        }
    }

    pub fn on_fill(&self, report: &ExecutionReport, side: Side) {
        if !matches!(report.status, OrderStatus::PartiallyFilled | OrderStatus::Filled) {
            return;
        }

        let delta = match side {
            Side::Buy => report.filled_qty,
            Side::Sell => -report.filled_qty,
        };

        let mut entry = self.positions.entry(report.symbol.clone()).or_insert(Decimal::ZERO);
        *entry += delta;
    }

    pub fn get(&self, symbol: &str) -> Decimal {
        self.positions.get(symbol).map(|v| *v).unwrap_or(Decimal::ZERO)
    }
}
