use crate::types::{MarketTick, OrderRequest, OrderType, Side, TimeInForce};
use chrono::Utc;
use rust_decimal::Decimal;
use uuid::Uuid;

#[derive(Clone)]
pub struct StrategyEngine {
    pub target_symbol: String,
}

impl StrategyEngine {
    pub fn new(target_symbol: impl Into<String>) -> Self {
        Self {
            target_symbol: target_symbol.into(),
        }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<OrderRequest> {
        if tick.symbol != self.target_symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread <= Decimal::new(1, 2) {
            Some(OrderRequest {
                client_order_id: Uuid::new_v4(),
                exchange: tick.exchange.clone(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                order_type: OrderType::Limit,
                tif: TimeInForce::Ioc,
                qty: Decimal::new(10, 0),
                price: Some(tick.bid),
                ts: Utc::now(),
            })
        } else {
            None
        }
    }
}
