```rust
mod bus;
mod config;
mod execution;
mod market_data;
mod metrics;
mod oms;
mod position;
mod risk;
mod strategy;
mod types;

use bus::Topic;
use config::AppConfig;
use execution::ExecutionGateway;
use market_data::run_market_data_feed;
use metrics::Metrics;
use oms::Oms;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tokio::sync::Mutex;
use tracing::{error, info};
use types::{ExecutionReport, MarketTick};

use std::sync::Arc;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = AppConfig::default();
    let metrics = Metrics::default();

    let market_topic: Topic<MarketTick> = Topic::new(1024);
    let exec_topic: Topic<ExecutionReport> = Topic::new(1024);

    let strategy = StrategyEngine::new("BTC-USD");
    let risk = Arc::new(Mutex::new(RiskEngine::new(cfg.risk_limits)));
    let oms = Arc::new(Oms::new());
    let execution = ExecutionGateway::new();

    let md_topic_clone = market_topic.clone();
    tokio::spawn(async move {
        run_market_data_feed(md_topic_clone).await;
    });

    let metrics_clone = metrics.clone();
    let strategy_clone = strategy.clone();
    let risk_clone = risk.clone();
    let oms_clone = oms.clone();
    let exec_topic_clone = exec_topic.clone();
    let execution_clone = execution.clone();

    tokio::spawn(async move {
        let mut rx = market_topic.subscribe();

        loop {
            match rx.recv().await {
                Ok(tick) => {
                    metrics_clone.inc_ticks();

                    if let Some(order_req) = strategy_clone.on_tick(&tick) {
                        let validation = {
                            let risk_guard = risk_clone.lock().await;
                            risk_guard.validate(&order_req)
                        };

                        match validation {
                            Ok(_) => {
                                let validated = oms_clone.register(order_req);
                                metrics_clone.inc_orders();

                                let report = execution_clone.send_order(validated).await;
                                exec_topic_clone.publish(report);
                            }
                            Err(e) => {
                                metrics_clone.inc_rejects();
                                error!("risk reject: {}", e);
                            }
                        }
                    }
                }
                Err(e) => {
                    error!("market data receive error: {}", e);
                }
            }
        }
    });

    let oms_clone2 = oms.clone();
    tokio::spawn(async move {
        let mut rx = exec_topic.subscribe();

        loop {
            match rx.recv().await {
                Ok(report) => {
                    oms_clone2.on_execution_report(&report);
                    info!("execution report: {:?}", report);
                }
                Err(e) => {
                    error!("execution report receive error: {}", e);
                }
            }
        }
    });

    tokio::signal::ctrl_c().await.unwrap();
    info!("shutdown");
}
```

