```rust
use crate::bus::Topic;
use crate::types::{MarketTick, OrderRequest, OrderType, Side};
use chrono::Utc;
use crossbeam::channel::Receiver;
use rust_decimal::Decimal;
use std::str::FromStr;
use std::thread;
use uuid::Uuid;

pub fn start_strategy(
    market_data_rx: Receiver<MarketTick>,
    order_topic: Topic<OrderRequest>,
) {
    thread::spawn(move || {
        let threshold = Decimal::from_str("100.20").unwrap();
        let mut sent = false;

        while let Ok(tick) = market_data_rx.recv() {
            if !sent && tick.last > threshold {
                let order = OrderRequest {
                    id: Uuid::new_v4(),
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    qty: 100,
                    order_type: OrderType::Limit,
                    price: Some(tick.ask),
                    ts: Utc::now(),
                };

                order_topic.publish(order);
                sent = true;
            }
        }
    });
}
