use crate::bus::Topic;
use crate::types::{OrderEvent, OrderRequest, OrderStatus};
use chrono::Utc;
use crossbeam::channel::Receiver;
use std::thread;

pub fn start_risk_engine(
    order_rx: Receiver<OrderRequest>,
    approved_topic: Topic<OrderEvent>,
) {
    thread::spawn(move || {
        let max_order_qty = 1000_u64;

        while let Ok(order) = order_rx.recv() {
            let status = if order.qty > max_order_qty {
                OrderStatus::Rejected("Order qty exceeds max limit".to_string())
            } else {
                OrderStatus::Approved
            };

            let event = OrderEvent {
                order,
                status,
                ts: Utc::now(),
            };

            approved_topic.publish(event);
        }
    });
}
