# src/oms.rs

```rust
use crate::bus::Topic;
use crate::types::{OrderEvent, OrderStatus};
use chrono::Utc;
use crossbeam::channel::Receiver;
use std::collections::HashMap;
use std::thread;
use uuid::Uuid;

pub fn start_oms(
    approved_rx: Receiver<OrderEvent>,
    execution_topic: Topic<OrderEvent>,
) {
    thread::spawn(move || {
        let mut orders: HashMap<Uuid, OrderEvent> = HashMap::new();

        while let Ok(event) = approved_rx.recv() {
            let id = event.order.id;
            orders.insert(id, event.clone());

            match event.status {
                OrderStatus::Approved => {
                    let sent_event = OrderEvent {
                        order: event.order,
                        status: OrderStatus::Sent,
                        ts: Utc::now(),
                    };
                    orders.insert(id, sent_event.clone());
                    execution_topic.publish(sent_event);
                }
                _ => {
                    println!("OMS rejected order {}: {:?}", id, event.status);
                }
            }
        }
    });
}
