# src/execution.rs

This simulates exchange execution.

```rust
use crate::bus::Topic;
use crate::types::{FillEvent, OrderEvent, OrderStatus};
use chrono::Utc;
use crossbeam::channel::Receiver;
use std::thread;
use std::time::Duration;

pub fn start_execution_gateway(
    execution_rx: Receiver<OrderEvent>,
    order_update_topic: Topic<OrderEvent>,
    fill_topic: Topic<FillEvent>,
) {
    thread::spawn(move || {
        while let Ok(event) = execution_rx.recv() {
            let ack = OrderEvent {
                order: event.order.clone(),
                status: OrderStatus::Acked,
                ts: Utc::now(),
            };
            order_update_topic.publish(ack);

            thread::sleep(Duration::from_millis(5));

            let fill = FillEvent {
                order_id: event.order.id,
                symbol: event.order.symbol.clone(),
                side: event.order.side.clone(),
                qty: event.order.qty,
                price: event.order.price.unwrap_or_default(),
                ts: Utc::now(),
            };
            fill_topic.publish(fill);

            let filled = OrderEvent {
                order: event.order,
                status: OrderStatus::Filled,
                ts: Utc::now(),
            };
            order_update_topic.publish(filled);
        }
    });
}
