use crate::types::{FillEvent, Side};
use crossbeam::channel::Receiver;
use std::collections::HashMap;
use std::thread;

pub fn start_position_service(fill_rx: Receiver<FillEvent>) {
    thread::spawn(move || {
        let mut positions: HashMap<String, i64> = HashMap::new();

        while let Ok(fill) = fill_rx.recv() {
            let delta = match fill.side {
                Side::Buy => fill.qty as i64,
                Side::Sell => -(fill.qty as i64),
            };

            let pos = positions.entry(fill.symbol.clone()).or_insert(0);
            *pos += delta;

            println!("Position update: {} => {}", fill.symbol, *pos);
        }
    });
}
