    pub fn run(&self) {
        let tx = self.tx.clone();
        thread::spawn(move || {
            let mut px = 100_00i64;
            loop {
                let tick = MarketTick {
                    symbol: "FOO".to_string(),
                    bid: px,
                    ask: px + 2,
                    ts: Utc::now(),
