use crate::common::types::{Event, MarketTick, Signal, Side};
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::thread;

pub struct StrategyEngine {
    market_rx: Receiver<Event>,
    signal_tx: Sender<Event>,
}

impl StrategyEngine {
    pub fn new(market_rx: Receiver<Event>, signal_tx: Sender<Event>) -> Self {
        Self { market_rx, signal_tx }
    }

    pub fn run(self) {
        thread::spawn(move || {
            while let Ok(event) = self.market_rx.recv() {
                if let Event::MarketTick(tick) = event {
                    if let Some(signal) = Self::on_tick(&tick) {
                        let _ = self.signal_tx.send(Event::Signal(signal));
                    }
                }
            }
        });
    }

    fn on_tick(tick: &MarketTick) -> Option<Signal> {
        let spread = tick.ask - tick.bid;
        if spread <= 2 && tick.bid < 100_10 {
            Some(Signal {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 10,
                price: Some(tick.ask),
                ts: Utc::now(),
            })
        } else {
            None
        }
    }
}
```

