```rust
use crate::common::config::Config;
use crate::common::types::{Event, Order, OrderStatus, OrderType, Side};
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;
use std::thread;
use uuid::Uuid;

pub struct RiskEngine {
    signal_rx: Receiver<Event>,
    order_tx: Sender<Event>,
    config: Config,
    positions: HashMap<String, i64>,
}

impl RiskEngine {
    pub fn new(signal_rx: Receiver<Event>, order_tx: Sender<Event>, config: Config) -> Self {
        Self {
            signal_rx,
            order_tx,
            config,
            positions: HashMap::new(),
        }
    }

    pub fn run(mut self) {
        thread::spawn(move || {
            while let Ok(event) = self.signal_rx.recv() {
                if let Event::Signal(signal) = event {
                    if signal.qty > self.config.max_order_qty {
                        continue;
                    }

                    let pos = *self.positions.get(&signal.symbol).unwrap_or(&0);
                    let delta = match signal.side {
                        Side::Buy => signal.qty as i64,
                        Side::Sell => -(signal.qty as i64),
                    };

                    if (pos + delta).abs() > self.config.max_position_per_symbol {
                        continue;
                    }

                    let order = Order {
                        id: Uuid::new_v4(),
                        symbol: signal.symbol.clone(),
                        side: signal.side,
                        qty: signal.qty,
                        price: signal.price,
                        order_type: OrderType::Limit,
                        status: OrderStatus::New,
                        ts: Utc::now(),
                    };

                    let _ = self.order_tx.send(Event::NewOrder(order));
                }
            }
        });
    }
}
```

