use crate::common::types::{Event, Fill};
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::{thread, time::Duration};

pub struct ExecutionGateway {
    rx: Receiver<Event>,
    oms_tx: Sender<Event>,
}

impl ExecutionGateway {
    pub fn new(rx: Receiver<Event>, oms_tx: Sender<Event>) -> Self {
        Self { rx, oms_tx }
    }

    pub fn run(self) {
        thread::spawn(move || {
            while let Ok(event) = self.rx.recv() {
                if let Event::NewOrder(order) = event {
                    let _ = self.oms_tx.send(Event::OrderAck(order.id));

                    thread::sleep(Duration::from_millis(1));

                    let fill_price = order.price.unwrap_or(0);
                    let fill = Fill {
                        order_id: order.id,
                        symbol: order.symbol,
                        side: order.side,
                        qty: order.qty,
                        price: fill_price,
                        ts: Utc::now(),
                    };

                    let _ = self.oms_tx.send(Event::Fill(fill));
                }
            }
        });
    }
}
```

