use crate::common::types::Event;
use crossbeam::channel::Receiver;
use std::fs::OpenOptions;
use std::io::Write;
use std::thread;

pub struct EventLog {
    rx: Receiver<Event>,
    path: String,
}

impl EventLog {
    pub fn new(rx: Receiver<Event>, path: impl Into<String>) -> Self {
        Self {
            rx,
            path: path.into(),
        }
    }

    pub fn run(self) {
        thread::spawn(move || {
            let mut file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(&self.path)
                .expect("failed to open event log");

            while let Ok(event) = self.rx.recv() {
                let line = format!("{:?}\n", event);
                let _ = file.write_all(line.as_bytes());
            }
        });
    }
}
```

