}

impl OmsEngine {
    pub fn new(rx: Receiver<Event>, exec_tx: Sender<Event>) -> Self {
        Self { rx, exec_tx, orders: HashMap::new() }
    }

    pub fn run(mut self) {
        thread::spawn(move || {
            while let Ok(event) = self.rx.recv() {
                match event {
                    Event::NewOrder(mut order) => {
                        order.status = OrderStatus::PendingSend;
                        self.orders.insert(order.id, order.clone());
                        let _ = self.exec_tx.send(Event::NewOrder(order));
                    }
                    Event::OrderAck(order_id) => {
                        if let Some(order) = self.orders.get_mut(&order_id) {
                            order.status = OrderStatus::Acked;
                        }
                    }
                    Event::Fill(fill) => {
                        if let Some(order) = self.orders.get_mut(&fill.order_id) {
                            order.status = OrderStatus::Filled;
                        }
                    }
                    Event::Reject { order_id, .. } => {
                        if let Some(order) = self.orders.get_mut(&order_id) {
                            order.status = OrderStatus::Rejected;
                        }
                    }
                    _ => {}
