        loop {
            let tick = MarketTick {
                symbol: "AAPL".to_string(),
                bid: px - Decimal::new(1, 2),
                ask: px + Decimal::new(1, 2),
                last: px,
                ts: Utc::now(),
            };

            if self.tx.send(Event::Market(tick)).await.is_err() {
                break;
            }

            px += Decimal::new(1, 2);
            sleep(Duration::from_millis(10)).await;
        }
    }
