use chrono::Utc;
use common::{Event, NewOrder, OrderType, Side};
use rust_decimal::Decimal;
use tokio::sync::mpsc;
use uuid::Uuid;

pub struct StrategyEngine {
    rx: mpsc::Receiver<Event>,
    tx: mpsc::Sender<Event>,
    last_price: Option<Decimal>,
}

impl StrategyEngine {
    pub fn new(rx: mpsc::Receiver<Event>, tx: mpsc::Sender<Event>) -> Self {
        Self {
            rx,
            tx,
            last_price: None,
        }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::Market(tick) = event {
                if let Some(prev) = self.last_price {
                    if tick.last > prev {
                        let order = NewOrder {
                            id: Uuid::new_v4(),
                            symbol: tick.symbol.clone(),
                            side: Side::Buy,
                            qty: Decimal::new(10, 0),
                            order_type: OrderType::Limit,
                            limit_price: Some(tick.ask),
                            ts: Utc::now(),
                        };

                        if self.tx.send(Event::NewOrder(order)).await.is_err() {
                            break;
                        }
                    }
                }
                self.last_price = Some(tick.last);
            }
        }
    }
}
```

