use common::{Event, NewOrder};
use rust_decimal::Decimal;
use tokio::sync::mpsc;

pub struct RiskEngine {
    rx: mpsc::Receiver<Event>,
    tx: mpsc::Sender<Event>,
    max_order_qty: Decimal,
}

impl RiskEngine {
    pub fn new(rx: mpsc::Receiver<Event>, tx: mpsc::Sender<Event>, max_order_qty: Decimal) -> Self {
        Self {
            rx,
            tx,
            max_order_qty,
        }
    }

    fn check(&self, order: &NewOrder) -> Result<(), String> {
        if order.qty <= Decimal::ZERO {
            return Err("quantity must be positive".into());
        }

        if order.qty > self.max_order_qty {
            return Err(format!("quantity exceeds max {}", self.max_order_qty));
        }

        Ok(())
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::NewOrder(order) = event {
                let out = match self.check(&order) {
                    Ok(_) => Event::RiskApproved(order),
                    Err(reason) => Event::RiskRejected(order, reason),
                };

                if self.tx.send(out).await.is_err() {
                    break;
                }
            }
        }
    }
}
```

