use common::{Event, OrderId, OrderStatus};
use std::collections::HashMap;
use tokio::sync::mpsc;

pub struct Oms {
    rx: mpsc::Receiver<Event>,
    tx: mpsc::Sender<Event>,
    statuses: HashMap<OrderId, OrderStatus>,
}

impl Oms {
    pub fn new(rx: mpsc::Receiver<Event>, tx: mpsc::Sender<Event>) -> Self {
        Self {
            rx,
            tx,
            statuses: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                Event::RiskApproved(order) => {
                    self.statuses.insert(order.id, OrderStatus::Approved);
                    if self.tx.send(Event::OrderSent(order)).await.is_err() {
                        break;
                    }
                }
                Event::RiskRejected(order, reason) => {
                    self.statuses
                        .insert(order.id, OrderStatus::Rejected(reason));
                }
                Event::Fill(fill) => {
                    self.statuses.insert(fill.order_id, OrderStatus::Filled);
                }
                _ => {}
            }
        }
    }
}
```

