}

impl ExecutionGateway {
    pub fn new(rx: mpsc::Receiver<Event>, tx: mpsc::Sender<Event>) -> Self {
        Self { rx, tx }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::OrderSent(order) = event {
                sleep(Duration::from_millis(2)).await;

                let price = order.limit_price.unwrap_or_default();
                let fill = Fill {
                    order_id: order.id,
                    symbol: order.symbol,
                    side: order.side,
                    qty: order.qty,
                    price,
                    ts: Utc::now(),
                };

                if self.tx.send(Event::Fill(fill)).await.is_err() {
                    break;
                }
            }
        }
    }
}
