            if let Event::Fill(fill) = event {
                let pos = self.positions.entry(fill.symbol).or_insert(Decimal::ZERO);
                match fill.side {
                    Side::Buy => *pos += fill.qty,
                    Side::Sell => *pos -= fill.qty,
                }
                println!("Updated positions: {:?}", self.positions);
            }
        }
    }
}
