# src/risk.rs

```rust
use crate::bus::EventBus;
use crate::types::{Event, NewOrder};
use rust_decimal::Decimal;
use std::collections::HashMap;
use std::str::FromStr;

pub struct RiskEngine {
    bus: EventBus<Event>,
    max_order_qty: Decimal,
    max_symbol_position: Decimal,
    positions: HashMap<String, Decimal>,
}

impl RiskEngine {
    pub fn new(bus: EventBus<Event>) -> Self {
        Self {
            bus,
            max_order_qty: Decimal::from_str("100").unwrap(),
            max_symbol_position: Decimal::from_str("1000").unwrap(),
            positions: HashMap::new(),
        }
    }

    fn approve(&self, order: &NewOrder) -> Result<(), String> {
        if order.qty > self.max_order_qty {
            return Err("order qty exceeds max_order_qty".to_string());
        }

        let current = self
            .positions
            .get(&order.symbol)
            .cloned()
            .unwrap_or(Decimal::ZERO);

        let projected = match order.side {
            crate::types::Side::Buy => current + order.qty,
            crate::types::Side::Sell => current - order.qty,
        };

        if projected.abs() > self.max_symbol_position {
            return Err("projected position exceeds max_symbol_position".to_string());
        }

        Ok(())
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::NewOrder(order)) => {
                    match self.approve(&order) {
                        Ok(_) => self.bus.publish(Event::RiskApproved(order)),
                        Err(reason) => self.bus.publish(Event::RiskRejected { order, reason }),
                    }
                }
                Ok(Event::PositionUpdate(pos)) => {
                    self.positions.insert(pos.symbol, pos.net_qty);
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
