use crate::bus::EventBus;
use crate::types::{Event, NewOrder, OrderStatus};
use std::collections::HashMap;
use uuid::Uuid;

pub struct Oms {
    bus: EventBus<Event>,
    orders: HashMap<Uuid, (NewOrder, OrderStatus)>,
}

impl Oms {
    pub fn new(bus: EventBus<Event>) -> Self {
        Self {
            bus,
            orders: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::RiskApproved(order)) => {
                    self.orders
                        .insert(order.id, (order.clone(), OrderStatus::PendingNew));
                    self.bus.publish(Event::RiskApproved(order));
                }
                Ok(Event::ExecutionReport(report)) => {
                    if let Some((_, status)) = self.orders.get_mut(&report.order_id) {
                        *status = report.status.clone();
                    }
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
