# src/position.rs

```rust
use crate::bus::EventBus;
use crate::types::{Event, OrderStatus, PositionUpdate, Side};
use chrono::Utc;
use rust_decimal::Decimal;
use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Position {
    net_qty: Decimal,
    avg_price: Decimal,
    realized_pnl: Decimal,
}

pub struct PositionService {
    bus: EventBus<Event>,
    positions: HashMap<String, Position>,
    order_sides: HashMap<uuid::Uuid, Side>,
}

impl PositionService {
    pub fn new(bus: EventBus<Event>) -> Self {
        Self {
            bus,
            positions: HashMap::new(),
            order_sides: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::RiskApproved(order)) => {
                    self.order_sides.insert(order.id, order.side);
                }
                Ok(Event::ExecutionReport(report)) => {
                    if !matches!(report.status, OrderStatus::Filled | OrderStatus::PartiallyFilled) {
                        continue;
                    }

                    let side = match self.order_sides.get(&report.order_id) {
                        Some(s) => s.clone(),
                        None => continue,
                    };

                    let fill_qty = report.filled_qty;
                    let fill_price = report.avg_price.unwrap_or(Decimal::ZERO);

                    let pos = self.positions.entry(report.symbol.clone()).or_insert(Position {
                        net_qty: Decimal::ZERO,
                        avg_price: Decimal::ZERO,
                        realized_pnl: Decimal::ZERO,
                    });

                    match side {
                        Side::Buy => {
                            let new_qty = pos.net_qty + fill_qty;
                            if new_qty != Decimal::ZERO {
                                pos.avg_price = ((pos.avg_price * pos.net_qty) + (fill_price * fill_qty)) / new_qty;
                            }
                            pos.net_qty = new_qty;
                        }
                        Side::Sell => {
                            pos.net_qty -= fill_qty;
                            // Simplified PnL logic
                            pos.realized_pnl += fill_qty * fill_price;
                        }
                    }

                    self.bus.publish(Event::PositionUpdate(PositionUpdate {
                        symbol: report.symbol,
                        net_qty: pos.net_qty,
                        avg_price: pos.avg_price,
                        realized_pnl: pos.realized_pnl,
                        ts: Utc::now(),
                    }));
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
