# Improved version with explicit channels

For lower latency and cleaner ownership, use **dedicated bounded MPSC channels** instead of a global broadcast bus.

If you want, this is actually the better code pattern to start with.

## Example: pipeline with dedicated channels

```rust
use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use std::collections::HashMap;
use tokio::sync::mpsc;
use uuid::Uuid;

#[derive(Debug, Clone)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
enum OrderType {
    Market,
    Limit,
}

#[derive(Debug, Clone)]
struct MarketData {
    symbol: String,
    bid: Decimal,
    ask: Decimal,
    last: Decimal,
    ts: DateTime<Utc>,
}

#[derive(Debug, Clone)]
struct NewOrder {
    id: Uuid,
    symbol: String,
    side: Side,
    qty: Decimal,
    order_type: OrderType,
    price: Option<Decimal>,
    ts: DateTime<Utc>,
}

#[derive(Debug, Clone)]
enum OrderStatus {
    PendingNew,
    New,
    Filled,
    Rejected,
}

#[derive(Debug, Clone)]
struct ExecutionReport {
    order_id: Uuid,
    symbol: String,
    status: OrderStatus,
    filled_qty: Decimal,
    avg_price: Option<Decimal>,
    reason: Option<String>,
    ts: DateTime<Utc>,
}

struct StrategyEngine {
    md_rx: mpsc::Receiver<MarketData>,
    order_tx: mpsc::Sender<NewOrder>,
    threshold: Decimal,
}

impl StrategyEngine {
    async fn run(mut self) {
        while let Some(md) = self.md_rx.recv().await {
            if md.last < self.threshold {
                let order = NewOrder {
                    id: Uuid::new_v4(),
                    symbol: md.symbol,
                    side: Side::Buy,
                    qty: Decimal::new(10, 0),
                    order_type: OrderType::Limit,
                    price: Some(md.bid),
                    ts: Utc::now(),
                };

                if self.order_tx.send(order).await.is_err() {
                    break;
                }
            }
        }
    }
}

struct RiskEngine {
    order_rx: mpsc::Receiver<NewOrder>,
    approved_tx: mpsc::Sender<NewOrder>,
    max_order_qty: Decimal,
    positions: HashMap<String, Decimal>,
}

impl RiskEngine {
    async fn run(mut self) {
        while let Some(order) = self.order_rx.recv().await {
            let current = self.positions.get(&order.symbol).cloned().unwrap_or(Decimal::ZERO);
            let projected = match order.side {
                Side::Buy => current + order.qty,
                Side::Sell => current - order.qty,
            };

            if order.qty <= self.max_order_qty && projected.abs() <= Decimal::new(1000, 0) {
                if self.approved_tx.send(order).await.is_err() {
                    break;
                }
            }
        }
    }
}

struct ExecutionGateway {
    approved_rx: mpsc::Receiver<NewOrder>,
    exec_tx: mpsc::Sender<ExecutionReport>,
}

impl ExecutionGateway {
    async fn run(mut self) {
        while let Some(order) = self.approved_rx.recv().await {
            let report = ExecutionReport {
                order_id: order.id,
                symbol: order.symbol,
                status: OrderStatus::Filled,
                filled_qty: order.qty,
                avg_price: order.price,
                reason: None,
                ts: Utc::now(),
            };

            if self.exec_tx.send(report).await.is_err() {
                break;
            }
        }
    }
}
```

This pattern is often better than a single shared bus for the hot path.

