## src/strategy.rs

A simple strategy: buy if spread is tight and ask is below threshold.

```rust
use crate::types::{MarketTick, Signal, Side};
use chrono::Utc;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::info;

pub async fn run_strategy(
    mut md_rx: Receiver<MarketTick>,
    signal_tx: Sender<Signal>,
) {
    const MAX_BUY_PRICE: i64 = 100_500;
    const MAX_SPREAD: i64 = 25;

    while let Some(tick) = md_rx.recv().await {
        let spread = tick.ask - tick.bid;

        if tick.ask <= MAX_BUY_PRICE && spread <= MAX_SPREAD {
            let signal = Signal {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                price: tick.ask,
                qty: 10,
                ts: Utc::now(),
            };

            if signal_tx.send(signal).await.is_err() {
                info!("signal consumer dropped");
                break;
            }
        }
    }
}
