## src/risk.rs

Risk checks should be extremely fast and deterministic.

```rust
use crate::types::{NewOrder, Signal, OrderType, TimeInForce};
use chrono::Utc;
use std::collections::HashMap;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::{info, warn};
use uuid::Uuid;

pub struct RiskLimits {
    pub max_order_qty: i64,
    pub max_position_abs: i64,
    pub enabled: bool,
}

pub async fn run_risk(
    mut signal_rx: Receiver<Signal>,
    order_tx: Sender<NewOrder>,
    limits: RiskLimits,
) {
    let mut positions: HashMap<String, i64> = HashMap::new();

    while let Some(signal) = signal_rx.recv().await {
        if !limits.enabled {
            warn!("risk disabled, dropping signal");
            continue;
        }

        if signal.qty > limits.max_order_qty {
            warn!("risk reject: qty too large");
            continue;
        }

        let pos = *positions.get(&signal.symbol).unwrap_or(&0);
        let projected = match signal.side {
            crate::types::Side::Buy => pos + signal.qty,
            crate::types::Side::Sell => pos - signal.qty,
        };

        if projected.abs() > limits.max_position_abs {
            warn!("risk reject: position limit exceeded");
            continue;
        }

        let order = NewOrder {
            order_id: Uuid::new_v4(),
            symbol: signal.symbol.clone(),
            side: signal.side,
            order_type: OrderType::Limit,
            tif: TimeInForce::IOC,
            price: Some(signal.price),
            qty: signal.qty,
            ts: Utc::now(),
        };

        positions.insert(signal.symbol.clone(), projected);

        if order_tx.send(order).await.is_err() {
            info!("order consumer dropped");
            break;
        }
    }
}
```

