## src/oms.rs

OMS tracks order state and forwards to execution.

```rust
use crate::types::{ExecutionReport, NewOrder, OrderStatus};
use std::collections::HashMap;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::info;
use uuid::Uuid;

pub struct OrderRecord {
    pub order: NewOrder,
    pub status: OrderStatus,
    pub filled_qty: i64,
}

pub async fn run_oms(
    mut new_order_rx: Receiver<NewOrder>,
    exec_tx: Sender<NewOrder>,
    mut exec_report_rx: Receiver<ExecutionReport>,
) {
    let mut orders: HashMap<Uuid, OrderRecord> = HashMap::new();

    loop {
        tokio::select! {
            maybe_order = new_order_rx.recv() => {
                match maybe_order {
                    Some(order) => {
                        let record = OrderRecord {
                            order: order.clone(),
                            status: OrderStatus::PendingNew,
                            filled_qty: 0,
                        };
                        orders.insert(order.order_id, record);

                        if exec_tx.send(order).await.is_err() {
                            info!("execution gateway dropped");
                            break;
                        }
                    }
                    None => break,
                }
            }

            maybe_report = exec_report_rx.recv() => {
                match maybe_report {
                    Some(report) => {
                        if let Some(record) = orders.get_mut(&report.order_id) {
                            record.status = report.status;
                            record.filled_qty = report.filled_qty;
                        }
                    }
                    None => break,
                }
            }
        }
    }
}
```

