    match next_event() {
        Event::MarketData(tick) => handle_tick(tick),
        Event::Signal(sig) => handle_signal(sig),
        Event::ExecutionReport(rep) => handle_exec_report(rep),
        Event::Timer(t) => handle_timer(t),
    }
}
