# src/strategy.rs

A simple strategy: if spread is small and price moves enough, emit a signal.

```rust
use crate::bus::EventBus;
use crate::types::{Event, OrderRequest, OrderType, Side, Signal};
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;
use tracing::info;

static ORDER_ID: AtomicU64 = AtomicU64::new(1);

pub fn start_strategy(bus: EventBus) {
    let rx = bus.subscribe();

    thread::spawn(move || {
        let mut last_mid: Option<f64> = None;

        while let Ok(event) = rx.recv() {
            if let Event::MarketTick(tick) = event {
                let mid = (tick.bid + tick.ask) * 0.5;
                let spread = tick.ask - tick.bid;

                if let Some(prev) = last_mid {
                    let move_size = mid - prev;

                    if spread <= 0.03 && move_size > 0.02 {
                        let signal = Signal {
                            symbol: tick.symbol.clone(),
                            side: Side::Buy,
                            price: tick.ask,
                            qty: 10,
                        };
                        bus.publish(Event::Signal(signal));
                    } else if spread <= 0.03 && move_size < -0.02 {
                        let signal = Signal {
                            symbol: tick.symbol.clone(),
                            side: Side::Sell,
                            price: tick.bid,
                            qty: 10,
                        };
                        bus.publish(Event::Signal(signal));
                    }
                }

                last_mid = Some(mid);
            }
        }
    });

    let rx2 = bus.subscribe();
    thread::spawn(move || {
        while let Ok(event) = rx2.recv() {
            if let Event::Signal(signal) = event {
                let order = OrderRequest {
                    client_order_id: ORDER_ID.fetch_add(1, Ordering::Relaxed),
                    symbol: signal.symbol,
                    side: signal.side,
                    order_type: OrderType::Limit,
                    price: Some(signal.price),
                    qty: signal.qty,
                    created_at: 0,
                };
                bus.publish(Event::OrderRequest(order));
            }
        }
    });

    info!("strategy started");
}
