# src/risk.rs

This is intentionally simple, but the interface is what matters.

```rust
use crate::bus::EventBus;
use crate::types::{Event, RiskApprovedOrder};
use std::collections::HashMap;
use std::thread;
use tracing::{info, warn};

pub fn start_risk_engine(bus: EventBus, max_order_qty: u64, max_position_abs: i64) {
    let rx = bus.subscribe();

    thread::spawn(move || {
        let mut positions: HashMap<String, i64> = HashMap::new();

        while let Ok(event) = rx.recv() {
            match event {
                Event::OrderRequest(order) => {
                    if order.qty > max_order_qty {
                        warn!("risk reject: qty too large order_id={}", order.client_order_id);
                        continue;
                    }

                    let pos = *positions.get(&order.symbol).unwrap_or(&0);
                    let delta = match order.side {
                        crate::types::Side::Buy => order.qty as i64,
                        crate::types::Side::Sell => -(order.qty as i64),
                    };

                    if (pos + delta).abs() > max_position_abs {
                        warn!(
                            "risk reject: position limit exceeded order_id={}",
                            order.client_order_id
                        );
                        continue;
                    }

                    positions.insert(order.symbol.clone(), pos + delta);
                    bus.publish(Event::RiskApproved(RiskApprovedOrder { order }));
                }
                Event::ExecutionReport(report) => {
                    if !report.accepted {
                        warn!("execution rejected order_id={}", report.client_order_id);
                    }
                }
                _ => {}
            }
        }
    });

    info!("risk engine started");
}
```

