use crate::bus::EventBus;
use crate::types::{Event, ExecutionReport};
use rand::Rng;
use std::thread;
use std::time::Duration;
use tracing::info;

pub fn start_exchange_gateway(bus: EventBus) {
    let rx = bus.subscribe();

    thread::spawn(move || {
        let mut rng = rand::thread_rng();

        while let Ok(event) = rx.recv() {
            if let Event::RiskApproved(approved) = event {
                thread::sleep(Duration::from_micros(100));

                let accepted = rng.gen_bool(0.98);
                let report = ExecutionReport {
                    client_order_id: approved.order.client_order_id,
                    symbol: approved.order.symbol.clone(),
                    filled_qty: if accepted { approved.order.qty } else { 0 },
                    avg_price: approved.order.price.unwrap_or(0.0),
                    accepted,
                    reason: if accepted {
                        None
                    } else {
                        Some("simulated venue reject".to_string())
                    },
                };

                bus.publish(Event::ExecutionReport(report));
            }
        }
    });

    info!("exchange gateway started");
}
