## src/main.rs alternative design

```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use std::thread;

mod types;
use types::*;

fn market_data_producer(tx: Sender<MarketTick>) {
    thread::spawn(move || {
        let mut px = 100.0;
        loop {
            px += 0.01;
            let tick = MarketTick {
                symbol: "FOO".to_string(),
                bid: px - 0.01,
                ask: px + 0.01,
                ts_exchange_ns: 0,
            };
            if tx.try_send(tick).is_err() {
                // drop on overload or count metric
            }
        }
    });
}

fn strategy(rx: Receiver<MarketTick>, tx: Sender<OrderRequest>) {
    thread::spawn(move || {
        let mut last_mid = None;
        let mut next_id = 1u64;

        while let Ok(tick) = rx.recv() {
            let mid = (tick.bid + tick.ask) * 0.5;
            if let Some(prev) = last_mid {
                if mid > prev + 0.02 {
                    let order = OrderRequest {
                        client_order_id: next_id,
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        order_type: OrderType::Limit,
                        price: Some(tick.ask),
                        qty: 10,
                        created_at: 0,
                    };
                    next_id += 1;
                    let _ = tx.try_send(order);
                }
            }
            last_mid = Some(mid);
        }
    });
}

fn risk(rx: Receiver<OrderRequest>, tx: Sender<RiskApprovedOrder>) {
    thread::spawn(move || {
        while let Ok(order) = rx.recv() {
            if order.qty <= 100 {
                let _ = tx.try_send(RiskApprovedOrder { order });
            }
        }
    });
}

fn exchange(rx: Receiver<RiskApprovedOrder>, tx: Sender<ExecutionReport>) {
    thread::spawn(move || {
        while let Ok(approved) = rx.recv() {
            let report = ExecutionReport {
                client_order_id: approved.order.client_order_id,
                symbol: approved.order.symbol,
                filled_qty: approved.order.qty,
                avg_price: approved.order.price.unwrap_or(0.0),
                accepted: true,
                reason: None,
            };
            let _ = tx.try_send(report);
        }
    });
}

fn main() {
    let (md_tx, md_rx) = bounded::<MarketTick>(65_536);
    let (ord_tx, ord_rx) = bounded::<OrderRequest>(65_536);
    let (risk_tx, risk_rx) = bounded::<RiskApprovedOrder>(65_536);
    let (exec_tx, exec_rx) = bounded::<ExecutionReport>(65_536);

    market_data_producer(md_tx);
    strategy(md_rx, ord_tx);
    risk(ord_rx, risk_tx);
    exchange(risk_rx, exec_tx);

    while let Ok(report) = exec_rx.recv() {
        println!("execution report: {:?}", report);
    }
}
```

This version is closer to what you want for a low-latency core:
- fewer unnecessary copies
- clearer ownership
- easier to benchmark
- easier to split into services later

