# 7. State store

## `src/state.rs`

```rust
use dashmap::DashMap;
use uuid::Uuid;

use crate::types::{ExecutionReport, OrderRequest, OrderStatus, Position, Side};

pub struct State {
    pub orders: DashMap<Uuid, OrderRequest>,
    pub executions: DashMap<Uuid, ExecutionReport>,
    pub positions: DashMap<String, Position>,
}

impl State {
    pub fn new() -> Self {
        Self {
            orders: DashMap::new(),
            executions: DashMap::new(),
            positions: DashMap::new(),
        }
    }

    pub fn record_order(&self, order: OrderRequest) {
        self.orders.insert(order.order_id, order);
    }

    pub fn record_execution(&self, exec: ExecutionReport) {
        self.executions.insert(exec.order_id, exec.clone());

        match exec.status {
            OrderStatus::Filled | OrderStatus::PartiallyFilled => {
                let signed_qty = match exec.side {
                    Side::Buy => exec.filled_qty as i64,
                    Side::Sell => -(exec.filled_qty as i64),
                };

                self.positions
                    .entry(exec.symbol.clone())
                    .and_modify(|p| {
                        p.net_qty += signed_qty;
                        if let Some(avg) = exec.avg_price {
                            p.avg_price = avg;
                        }
                    })
                    .or_insert(Position {
                        symbol: exec.symbol.clone(),
                        net_qty: signed_qty,
                        avg_price: exec.avg_price.unwrap_or(0.0),
                    });
            }
            _ => {}
        }
    }

    pub fn get_position(&self, symbol: &str) -> i64 {
        self.positions.get(symbol).map(|p| p.net_qty).unwrap_or(0)
    }
}
