# 9. Strategy engine

This example strategy buys if price drops below threshold and sells if above threshold.

## `src/strategy.rs`

```rust
use chrono::Utc;
use crossbeam::channel::Receiver;
use tracing::{info, warn};
use uuid::Uuid;

use crate::{
    bus::Bus,
    types::{Event, OrderRequest, OrderType, Side, TimeInForce},
};

pub fn start_strategy(rx: Receiver<Event>, order_bus: Bus<Event>, symbol: String) {
    std::thread::spawn(move || {
        for event in rx.iter() {
            if let Event::Market(tick) = event {
                if tick.symbol != symbol {
                    continue;
                }

                if tick.last < 99.90 {
                    let order = OrderRequest {
                        order_id: Uuid::new_v4(),
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        qty: 100,
                        order_type: OrderType::Limit,
                        price: Some(tick.bid),
                        tif: TimeInForce::IOC,
                        ts: Utc::now(),
                    };
                    info!("strategy generated BUY order {:?}", order.order_id);
                    order_bus.publish(Event::OrderNew(order));
                } else if tick.last > 100.10 {
                    let order = OrderRequest {
                        order_id: Uuid::new_v4(),
                        symbol: tick.symbol.clone(),
                        side: Side::Sell,
                        qty: 100,
                        order_type: OrderType::Limit,
                        price: Some(tick.ask),
                        tif: TimeInForce::IOC,
                        ts: Utc::now(),
                    };
                    warn!("strategy generated SELL order {:?}", order.order_id);
                    order_bus.publish(Event::OrderNew(order));
                }
            }
        }
    });
}
