# 10. Risk engine

This is where you enforce hard limits before orders leave the system.

## `src/risk.rs`

```rust
use std::sync::Arc;

use chrono::Utc;
use crossbeam::channel::Receiver;
use tracing::{error, info};

use crate::{
    bus::Bus,
    state::State,
    types::{Event, ExecutionReport, OrderStatus, Side},
};

pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_position_abs: i64,
    pub trading_enabled: bool,
}

pub fn start_risk(
    rx: Receiver<Event>,
    approved_bus: Bus<Event>,
    state: Arc<State>,
    limits: RiskLimits,
) {
    std::thread::spawn(move || {
        for event in rx.iter() {
            if let Event::OrderNew(order) = event {
                if !limits.trading_enabled {
                    let reject = ExecutionReport {
                        order_id: order.order_id,
                        venue_order_id: None,
                        symbol: order.symbol.clone(),
                        side: order.side,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_price: None,
                        status: OrderStatus::Rejected("trading disabled".into()),
                        ts: Utc::now(),
                    };
                    approved_bus.publish(Event::OrderReject(reject));
                    continue;
                }

                if order.qty > limits.max_order_qty {
                    let reject = ExecutionReport {
                        order_id: order.order_id,
                        venue_order_id: None,
                        symbol: order.symbol.clone(),
                        side: order.side,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_price: None,
                        status: OrderStatus::Rejected("max order qty exceeded".into()),
                        ts: Utc::now(),
                    };
                    approved_bus.publish(Event::OrderReject(reject));
                    continue;
                }

                let current_pos = state.get_position(&order.symbol);
                let projected = match order.side {
                    Side::Buy => current_pos + order.qty as i64,
                    Side::Sell => current_pos - order.qty as i64,
                };

                if projected.abs() > limits.max_position_abs {
                    let reject = ExecutionReport {
                        order_id: order.order_id,
                        venue_order_id: None,
                        symbol: order.symbol.clone(),
                        side: order.side,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_price: None,
                        status: OrderStatus::Rejected("position limit exceeded".into()),
                        ts: Utc::now(),
                    };
                    error!("risk rejected order {:?}", order.order_id);
                    approved_bus.publish(Event::OrderReject(reject));
                    continue;
                }

                info!("risk approved order {:?}", order.order_id);
                approved_bus.publish(Event::OrderNew(order));
            }
        }
    });
}
