# 11. OMS

The OMS records orders and execution reports.

## `src/oms.rs`

```rust
use std::sync::Arc;

use crossbeam::channel::Receiver;
use tracing::info;

use crate::{state::State, types::Event};

pub fn start_oms(rx: Receiver<Event>, state: Arc<State>) {
    std::thread::spawn(move || {
        for event in rx.iter() {
            match event {
                Event::OrderNew(order) => {
                    state.record_order(order.clone());
                    info!("OMS recorded new order {:?}", order.order_id);
                }
                Event::OrderAck(exec) | Event::OrderFill(exec) | Event::OrderReject(exec) => {
                    state.record_execution(exec.clone());
                    info!("OMS recorded execution for {:?}", exec.order_id);
                }
                Event::Market(_) => {}
            }
        }
    });
}
