# 12. Execution gateway

This simulates exchange behavior.

## `src/execution.rs`

```rust
use std::{thread, time::Duration};

use chrono::Utc;
use crossbeam::channel::Receiver;
use tracing::{info, warn};

use crate::{
    bus::Bus,
    types::{Event, ExecutionReport, OrderStatus},
};

pub fn start_execution(rx: Receiver<Event>, report_bus: Bus<Event>) {
    thread::spawn(move || {
        for event in rx.iter() {
            if let Event::OrderNew(order) = event {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    venue_order_id: Some(format!("VENUE-{}", order.order_id)),
                    symbol: order.symbol.clone(),
                    side: order.side,
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    avg_price: None,
                    status: OrderStatus::Acked,
                    ts: Utc::now(),
                };
                report_bus.publish(Event::OrderAck(ack));
                info!("execution acked order {:?}", order.order_id);

                thread::sleep(Duration::from_millis(2));

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    venue_order_id: Some(format!("VENUE-{}", order.order_id)),
                    symbol: order.symbol.clone(),
                    side: order.side,
                    filled_qty: order.qty,
                    remaining_qty: 0,
                    avg_price: order.price,
                    status: OrderStatus::Filled,
                    ts: Utc::now(),
                };
                report_bus.publish(Event::OrderFill(fill));
                warn!("execution filled order {:?}", order.order_id);
            }
        }
    });
}
```

