## src/strategy.rs

A simple example strategy: buy if spread is narrow and ask is below a threshold.

```rust
use std::time::{SystemTime, UNIX_EPOCH};

use rust_decimal::Decimal;
use tokio::sync::broadcast;
use tracing::{error, info};
use uuid::Uuid;

use crate::types::{MarketEvent, OrderCommand, OrderType, Side};

pub struct StrategyEngine {
    market_rx: broadcast::Receiver<MarketEvent>,
    order_tx: broadcast::Sender<OrderCommand>,
}

impl StrategyEngine {
    pub fn new(
        market_rx: broadcast::Receiver<MarketEvent>,
        order_tx: broadcast::Sender<OrderCommand>,
    ) -> Self {
        Self { market_rx, order_tx }
    }

    pub async fn run(mut self) {
        info!("strategy engine started");

        loop {
            match self.market_rx.recv().await {
                Ok(event) => {
                    if should_buy(&event) {
                        let order = OrderCommand {
                            order_id: Uuid::new_v4(),
                            symbol: event.symbol.clone(),
                            side: Side::Buy,
                            qty: Decimal::new(1, 0),
                            price: Some(event.ask),
                            order_type: OrderType::Limit,
                            ts_nanos: now_nanos(),
                        };

                        if let Err(e) = self.order_tx.send(order) {
                            error!("failed to publish order command: {:?}", e);
                        }
                    }
                }
                Err(e) => {
                    error!("market receive error: {:?}", e);
                }
            }
        }
    }
}

fn should_buy(event: &MarketEvent) -> bool {
    let spread = event.ask - event.bid;
    spread <= Decimal::new(20, 0) && event.ask <= Decimal::new(50010, 0)
}

fn now_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
