use rust_decimal::Decimal;
use tokio::sync::broadcast;
use tracing::{error, info};

use crate::types::OrderCommand;

pub struct RiskEngine {
    order_rx: broadcast::Receiver<OrderCommand>,
    approved_tx: broadcast::Sender<OrderCommand>,
}

impl RiskEngine {
    pub fn new(
        order_rx: broadcast::Receiver<OrderCommand>,
        approved_tx: broadcast::Sender<OrderCommand>,
    ) -> Self {
        Self {
            order_rx,
            approved_tx,
        }
    }

    pub async fn run(mut self) {
        info!("risk engine started");

        loop {
            match self.order_rx.recv().await {
                Ok(order) => {
                    if self.check_order(&order) {
                        if let Err(e) = self.approved_tx.send(order) {
                            error!("failed to publish approved order: {:?}", e);
                        }
                    } else {
                        error!("risk rejected order: {:?}", order.order_id);
                    }
                }
                Err(e) => error!("risk receive error: {:?}", e),
            }
        }
    }

    fn check_order(&self, order: &OrderCommand) -> bool {
        order.qty > Decimal::ZERO && order.qty <= Decimal::new(10, 0)
    }
}
