```rust
use std::collections::HashMap;

use tokio::sync::broadcast;
use tracing::{error, info};
use uuid::Uuid;

use crate::types::{ExecStatus, ExecutionReport, OrderCommand};

pub struct Oms {
    approved_rx: broadcast::Receiver<OrderCommand>,
    exec_tx: broadcast::Sender<ExecutionReport>,
    exec_rx: broadcast::Receiver<ExecutionReport>,
    orders: HashMap<Uuid, OrderState>,
}

#[derive(Debug, Clone)]
struct OrderState {
    order: OrderCommand,
    status: ExecStatus,
}

impl Oms {
    pub fn new(
        approved_rx: broadcast::Receiver<OrderCommand>,
        exec_tx: broadcast::Sender<ExecutionReport>,
        exec_rx: broadcast::Receiver<ExecutionReport>,
    ) -> Self {
        Self {
            approved_rx,
            exec_tx,
            exec_rx,
            orders: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        info!("oms started");

        loop {
            tokio::select! {
                result = self.approved_rx.recv() => {
                    match result {
                        Ok(order) => {
                            self.orders.insert(order.order_id, OrderState {
                                order: order.clone(),
                                status: ExecStatus::New,
                            });

                            let report = ExecutionReport {
                                order_id: order.order_id,
                                venue_order_id: None,
                                status: ExecStatus::New,
                                filled_qty: rust_decimal::Decimal::ZERO,
                                remaining_qty: order.qty,
                                avg_price: None,
                                reason: None,
                                ts_nanos: order.ts_nanos,
                            };

                            if let Err(e) = self.exec_tx.send(report) {
                                error!("failed to emit new order report: {:?}", e);
                            }
                        }
                        Err(e) => error!("oms approved_rx error: {:?}", e),
                    }
                }
                result = self.exec_rx.recv() => {
                    match result {
                        Ok(report) => {
                            if let Some(state) = self.orders.get_mut(&report.order_id) {
                                state.status = report.status.clone();
                            }
                        }
                        Err(e) => error!("oms exec_rx error: {:?}", e),
                    }
                }
            }
        }
    }
}
