# 7. Risk engine

Risk must be **in the order path**.  
Keep it fast and deterministic.

## `src/risk.rs`

```rust
use rust_decimal::Decimal;
use thiserror::Error;

use crate::types::OrderRequest;

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("order quantity exceeds max allowed")]
    MaxQtyExceeded,
    #[error("invalid quantity")]
    InvalidQty,
}

#[derive(Clone)]
pub struct RiskEngine {
    pub max_order_qty: Decimal,
}

impl RiskEngine {
    pub fn new(max_order_qty: Decimal) -> Self {
        Self { max_order_qty }
    }

    pub fn check(&self, order: &OrderRequest) -> Result<(), RiskError> {
        if order.qty <= Decimal::ZERO {
            return Err(RiskError::InvalidQty);
        }

        if order.qty > self.max_order_qty {
            return Err(RiskError::MaxQtyExceeded);
        }

        Ok(())
    }
}
```

