# 8. Order router

This is where:
- orders from strategies arrive
- risk checks happen
- broker/exchange submission occurs
- updates are published back to the bus

## `src/order_router.rs`

```rust
use std::sync::Arc;
use tracing::{error, info};

use crate::{
    broker::Broker,
    bus::EventBus,
    risk::RiskEngine,
    types::{Event, OrderStatus, OrderUpdate},
};

pub struct OrderRouter<B: Broker + 'static> {
    pub bus: EventBus,
    pub broker: Arc<B>,
    pub risk: RiskEngine,
}

impl<B: Broker + 'static> OrderRouter<B> {
    pub fn new(bus: EventBus, broker: Arc<B>, risk: RiskEngine) -> Self {
        Self { bus, broker, risk }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::OrderRequest(order)) => {
                    match self.risk.check(&order) {
                        Ok(_) => {
                            let update = self.broker.send_order(order).await;
                            self.bus.publish(Event::OrderUpdate(update));
                        }
                        Err(e) => {
                            error!("risk rejection: {}", e);
                            let reject = OrderUpdate {
                                id: order.id,
                                status: OrderStatus::Rejected(e.to_string()),
                                filled_qty: rust_decimal::Decimal::ZERO,
                                remaining_qty: order.qty,
                                ts_nanos: order.ts_nanos,
                            };
                            self.bus.publish(Event::OrderUpdate(reject));
                        }
                    }
                }
                Ok(_) => {}
                Err(err) => {
                    info!("order router receiver error: {}", err);
                }
            }
        }
    }
}
```

