# 9. Strategy interface

A strategy should only care about:
- market data
- generating orders
- maybe receiving fills

## `src/strategy.rs`

```rust
use rust_decimal::Decimal;
use std::time::{SystemTime, UNIX_EPOCH};
use tracing::info;
use uuid::Uuid;

use crate::types::{Event, MarketTick, OrderRequest, OrderType, Side};

pub trait Strategy: Send {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest>;
    fn on_order_update(&mut self, _update: &crate::types::OrderUpdate) {}
}

pub struct SimpleSpreadStrategy {
    pub symbol: String,
    pub threshold: Decimal,
    pub order_qty: Decimal,
}

impl SimpleSpreadStrategy {
    pub fn new(symbol: String, threshold: Decimal, order_qty: Decimal) -> Self {
        Self {
            symbol,
            threshold,
            order_qty,
        }
    }
}

impl Strategy for SimpleSpreadStrategy {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest> {
        if tick.symbol != self.symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread >= self.threshold {
            info!("spread opportunity detected: {}", spread);

            Some(OrderRequest {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                order_type: OrderType::Limit,
                limit_price: Some(tick.bid),
                ts_nanos: now_nanos(),
            })
        } else {
            None
        }
    }
}

pub struct StrategyRunner<S: Strategy> {
    strategy: S,
    bus: crate::bus::EventBus,
}

impl<S: Strategy> StrategyRunner<S> {
    pub fn new(strategy: S, bus: crate::bus::EventBus) -> Self {
        Self { strategy, bus }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::MarketTick(tick)) => {
                    if let Some(order) = self.strategy.on_tick(&tick) {
                        self.bus.publish(Event::OrderRequest(order));
                    }
                }
                Ok(Event::OrderUpdate(update)) => {
                    self.strategy.on_order_update(&update);
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

