pub struct MarketDataGateway {
    bus: EventBus,
    symbol: String,
}

impl MarketDataGateway {
    pub fn new(bus: EventBus, symbol: String) -> Self {
        Self { bus, symbol }
    }

    pub async fn run(self) {
        let mut px = Decimal::from_str("100.00").unwrap();

        loop {
            let tick = MarketTick {
                symbol: self.symbol.clone(),
                bid: px,
                ask: px + Decimal::from_str("0.05").unwrap(),
                ts_nanos: now_nanos(),
            };

            self.bus.publish(Event::MarketTick(tick));

            px += Decimal::from_str("0.01").unwrap();
            sleep(Duration::from_millis(10)).await;
        }
    }
}

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
