use rust_decimal::Decimal;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::types::{Event, ExecutionReport, OrderStatus};

pub async fn run_risk_engine(bus: EventBus) {
    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::OrderRequest(order)) => {
                let max_order_qty = Decimal::new(1000, 0);

                if order.qty > max_order_qty {
                    warn!("risk rejected order {:?}", order.order_id);

                    let report = ExecutionReport {
                        order_id: order.order_id,
                        status: OrderStatus::Rejected,
                        filled_qty: Decimal::ZERO,
                        avg_price: None,
                        reason: Some("Order quantity exceeds limit".to_string()),
                        ts_nanos: now_nanos(),
                    };

                    bus.publish(Event::ExecutionReport(report));
                } else {
                    info!("risk passed order {:?}", order.order_id);
                    // Forward by republishing. In a more refined design,
                    // use separate channels/topics for validated orders.
                    bus.publish(Event::OrderRequest(order));
                }
            }
            Ok(_) => {}
            Err(_) => {}
        }
    }
}

