package com.example.trading.core.model;

import java.math.BigDecimal;

public class Order {
    public enum Side { BUY, SELL }
    public enum Type { MARKET, LIMIT }
    public enum Status { NEW, ACCEPTED, PARTIALLY_FILLED, FILLED, CANCELED, REJECTED }

    private final String orderId;
    private final String clientId;
    private final String instrumentId;
    private final Side side;
    private final Type type;
    private final BigDecimal price;
    private final long quantity;
    private long remainingQuantity;
    private Status status;
    private final long timestamp;

    public Order(
            String orderId,
            String clientId,
            String instrumentId,
            Side side,
            Type type,
            BigDecimal price,
            long quantity,
            long timestamp
    ) {
        this.orderId = orderId;
        this.clientId = clientId;
        this.instrumentId = instrumentId;
        this.side = side;
        this.type = type;
        this.price = price;
        this.quantity = quantity;
        this.remainingQuantity = quantity;
        this.status = Status.NEW;
        this.timestamp = timestamp;
    }

    public String getOrderId() { return orderId; }
    public String getClientId() { return clientId; }
    public String getInstrumentId() { return instrumentId; }
    public Side getSide() { return side; }
    public Type getType() { return type; }
    public BigDecimal getPrice() { return price; }
    public long getQuantity() { return quantity; }
    public long getRemainingQuantity() { return remainingQuantity; }
    public Status getStatus() { return status; }
    public long getTimestamp() { return timestamp; }

    public void fill(long qty) {
        this.remainingQuantity -= qty;
        if (remainingQuantity == 0) {
            this.status = Status.FILLED;
        } else {
            this.status = Status.PARTIALLY_FILLED;
        }
    }

    public void accept() {
        this.status = Status.ACCEPTED;
    }

    public void reject() {
        this.status = Status.REJECTED;
    }

    public void cancel() {
        this.status = Status.CANCELED;
    }
}
