## 7.3 Risk engine

```java
package com.example.trading.core.risk;

import com.example.trading.core.model.Order;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RiskEngine {

    public static class RiskLimit {
        public final long maxOrderQty;
        public final BigDecimal maxNotional;
        public final long maxPosition;

        public RiskLimit(long maxOrderQty, BigDecimal maxNotional, long maxPosition) {
            this.maxOrderQty = maxOrderQty;
            this.maxNotional = maxNotional;
            this.maxPosition = maxPosition;
        }
    }

    private final Map<String, RiskLimit> limitsByClient = new ConcurrentHashMap<>();

    public void setLimit(String clientId, RiskLimit limit) {
        limitsByClient.put(clientId, limit);
    }

    public boolean check(Order order) {
        RiskLimit limit = limitsByClient.get(order.getClientId());
        if (limit == null) return false;
        if (order.getQuantity() > limit.maxOrderQty) return false;

        if (order.getPrice() != null) {
            BigDecimal notional = order.getPrice().multiply(BigDecimal.valueOf(order.getQuantity()));
            if (notional.compareTo(limit.maxNotional) > 0) return false;
        }

        return true;
    }
}
```

