## 7.4 Order book

For the initial version, use price-level maps.

```java
package com.example.trading.core.book;

import com.example.trading.core.model.Order;

import java.math.BigDecimal;
import java.util.*;

public class OrderBook {
    private final String instrumentId;

    private final NavigableMap<BigDecimal, Deque<Order>> bids =
            new TreeMap<>(Comparator.reverseOrder());

    private final NavigableMap<BigDecimal, Deque<Order>> asks =
            new TreeMap<>();

    public OrderBook(String instrumentId) {
        this.instrumentId = instrumentId;
    }

    public String getInstrumentId() {
        return instrumentId;
    }

    public NavigableMap<BigDecimal, Deque<Order>> getBids() {
        return bids;
    }

    public NavigableMap<BigDecimal, Deque<Order>> getAsks() {
        return asks;
    }

    public void add(Order order) {
        NavigableMap<BigDecimal, Deque<Order>> sideBook =
                order.getSide() == Order.Side.BUY ? bids : asks;

        sideBook.computeIfAbsent(order.getPrice(), p -> new ArrayDeque<>()).addLast(order);
    }
}
