## 7.5 Matching engine

```java
package com.example.trading.core.match;

import com.example.trading.core.book.OrderBook;
import com.example.trading.core.model.Order;
import com.example.trading.core.model.Trade;

import java.math.BigDecimal;
import java.util.*;

public class MatchingEngine {

    public List<Trade> match(OrderBook book, Order incoming) {
        List<Trade> trades = new ArrayList<>();

        if (incoming.getSide() == Order.Side.BUY) {
            matchBuy(book, incoming, trades);
        } else {
            matchSell(book, incoming, trades);
        }

        if (incoming.getRemainingQuantity() > 0 && incoming.getType() == Order.Type.LIMIT) {
            book.add(incoming);
        }

        return trades;
    }

    private void matchBuy(OrderBook book, Order incoming, List<Trade> trades) {
        Iterator<Map.Entry<BigDecimal, Deque<Order>>> it = book.getAsks().entrySet().iterator();

        while (it.hasNext() && incoming.getRemainingQuantity() > 0) {
            Map.Entry<BigDecimal, Deque<Order>> level = it.next();

            if (incoming.getType() == Order.Type.LIMIT &&
                    level.getKey().compareTo(incoming.getPrice()) > 0) {
                break;
            }

            Deque<Order> queue = level.getValue();
            while (!queue.isEmpty() && incoming.getRemainingQuantity() > 0) {
                Order resting = queue.peekFirst();
                long fillQty = Math.min(incoming.getRemainingQuantity(), resting.getRemainingQuantity());

                incoming.fill(fillQty);
                resting.fill(fillQty);

                trades.add(new Trade(
                        UUID.randomUUID().toString(),
                        incoming.getOrderId(),
                        resting.getOrderId(),
                        incoming.getInstrumentId(),
                        level.getKey(),
                        fillQty,
                        System.nanoTime()
                ));

                if (resting.getRemainingQuantity() == 0) {
                    queue.removeFirst();
                }
            }

            if (queue.isEmpty()) {
                it.remove();
            }
        }
    }

    private void matchSell(OrderBook book, Order incoming, List<Trade> trades) {
        Iterator<Map.Entry<BigDecimal, Deque<Order>>> it = book.getBids().entrySet().iterator();

        while (it.hasNext() && incoming.getRemainingQuantity() > 0) {
            Map.Entry<BigDecimal, Deque<Order>> level = it.next();

            if (incoming.getType() == Order.Type.LIMIT &&
                    level.getKey().compareTo(incoming.getPrice()) < 0) {
                break;
            }

            Deque<Order> queue = level.getValue();
            while (!queue.isEmpty() && incoming.getRemainingQuantity() > 0) {
                Order resting = queue.peekFirst();
                long fillQty = Math.min(incoming.getRemainingQuantity(), resting.getRemainingQuantity());

                incoming.fill(fillQty);
                resting.fill(fillQty);

                trades.add(new Trade(
                        UUID.randomUUID().toString(),
                        resting.getOrderId(),
                        incoming.getOrderId(),
                        incoming.getInstrumentId(),
                        level.getKey(),
                        fillQty,
                        System.nanoTime()
                ));

                if (resting.getRemainingQuantity() == 0) {
                    queue.removeFirst();
                }
            }

            if (queue.isEmpty()) {
                it.remove();
            }
        }
    }
}
```

