## 7.6 Trading engine orchestration

```java
package com.example.trading.core.engine;

import com.example.trading.core.book.OrderBook;
import com.example.trading.core.match.MatchingEngine;
import com.example.trading.core.model.Order;
import com.example.trading.core.model.Trade;
import com.example.trading.core.risk.RiskEngine;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class TradingEngine {

    private final RiskEngine riskEngine;
    private final MatchingEngine matchingEngine;
    private final Map<String, OrderBook> books = new ConcurrentHashMap<>();

    public TradingEngine(RiskEngine riskEngine, MatchingEngine matchingEngine) {
        this.riskEngine = riskEngine;
        this.matchingEngine = matchingEngine;
    }

    public Result process(Order order) {
        if (!riskEngine.check(order)) {
            order.reject();
            return Result.rejected(order, "Risk check failed");
        }

        order.accept();
        OrderBook book = books.computeIfAbsent(order.getInstrumentId(), OrderBook::new);
        List<Trade> trades = matchingEngine.match(book, order);

        return Result.accepted(order, trades);
    }

    public record Result(Order order, List<Trade> trades, boolean accepted, String reason) {
        public static Result accepted(Order order, List<Trade> trades) {
            return new Result(order, trades, true, null);
        }

        public static Result rejected(Order order, String reason) {
            return new Result(order, List.of(), false, reason);
        }
    }
}
```

