## `crates/core/src/risk.rs`

```rust
use common::{OrderRequest, Side};
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Debug, Clone, Default)]
pub struct Position {
    pub net_qty: i64,
}

#[derive(Clone)]
pub struct RiskManager {
    max_order_qty: u64,
    max_abs_position: i64,
    positions: Arc<DashMap<String, Position>>,
}

impl RiskManager {
    pub fn new(max_order_qty: u64, max_abs_position: i64) -> Self {
        Self {
            max_order_qty,
            max_abs_position,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn check_order(&self, req: &OrderRequest) -> Result<(), String> {
        if req.qty == 0 {
            return Err("quantity must be > 0".into());
        }

        if req.qty > self.max_order_qty {
            return Err(format!(
                "order qty {} exceeds max {}",
                req.qty, self.max_order_qty
            ));
        }

        let current = self
            .positions
            .get(&req.symbol)
            .map(|p| p.net_qty)
            .unwrap_or(0);

        let delta = match req.side {
            Side::Buy => req.qty as i64,
            Side::Sell => -(req.qty as i64),
        };

        let projected = current + delta;
        if projected.abs() > self.max_abs_position {
            return Err(format!(
                "projected position {} exceeds max abs position {}",
                projected, self.max_abs_position
            ));
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, side: &Side, fill_qty: u64) {
        let delta = match side {
            Side::Buy => fill_qty as i64,
            Side::Sell => -(fill_qty as i64),
        };

        self.positions
            .entry(symbol.to_string())
            .and_modify(|p| p.net_qty += delta)
            .or_insert(Position { net_qty: delta });
    }
}
