```rust
use async_trait::async_trait;
use chrono::Utc;
use common::{ExecutionReport, Order, OrderStatus};
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};

#[async_trait]
pub trait ExecutionVenue: Send + Sync {
    async fn send_order(&self, order: Order);
}

#[derive(Clone)]
pub struct SimulatedExecutionVenue {
    pub tx: mpsc::Sender<ExecutionReport>,
}

#[async_trait]
impl ExecutionVenue for SimulatedExecutionVenue {
    async fn send_order(&self, order: Order) {
        let accepted = ExecutionReport {
            order_id: order.order_id,
            client_order_id: order.client_order_id.clone(),
            symbol: order.symbol.clone(),
            status: OrderStatus::Accepted,
            filled_qty: 0,
            last_fill_qty: 0,
            last_fill_price: None,
            reason: None,
            ts: Utc::now(),
        };

        let _ = self.tx.send(accepted).await;

        sleep(Duration::from_millis(10)).await;

        let fill_price = order.limit_price.unwrap_or(100.0);
        let filled = ExecutionReport {
            order_id: order.order_id,
            client_order_id: order.client_order_id.clone(),
            symbol: order.symbol.clone(),
            status: OrderStatus::Filled,
            filled_qty: order.qty,
            last_fill_qty: order.qty,
            last_fill_price: Some(fill_price),
            reason: None,
            ts: Utc::now(),
        };

        let _ = self.tx.send(filled).await;
    }
}
