## `crates/core/src/engine.rs`

```rust
use crate::execution::ExecutionVenue;
use crate::market_data::MarketDataCache;
use crate::persistence::Persistence;
use crate::risk::RiskManager;
use crate::types::{EngineCommand, EngineEvent};
use chrono::Utc;
use common::{ExecutionReport, Order, OrderRequest, OrderStatus};
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::{broadcast, mpsc};
use uuid::Uuid;

pub struct TradingEngine<P, E>
where
    P: Persistence + 'static,
    E: ExecutionVenue + 'static,
{
    pub risk: RiskManager,
    pub market_data: MarketDataCache,
    pub persistence: Arc<P>,
    pub execution: Arc<E>,
    pub orders: Arc<DashMap<Uuid, Order>>,
    pub event_tx: broadcast::Sender<EngineEvent>,
}

impl<P, E> TradingEngine<P, E>
where
    P: Persistence + 'static,
    E: ExecutionVenue + 'static,
{
    pub fn new(risk: RiskManager, persistence: Arc<P>, execution: Arc<E>) -> Self {
        let (event_tx, _) = broadcast::channel(1024);
        Self {
            risk,
            market_data: MarketDataCache::default(),
            persistence,
            execution,
            orders: Arc::new(DashMap::new()),
            event_tx,
        }
    }

    pub async fn run(self: Arc<Self>, mut rx: mpsc::Receiver<EngineCommand>) {
        while let Some(cmd) = rx.recv().await {
            match cmd {
                EngineCommand::NewOrder(req) => self.handle_new_order(req).await,
                EngineCommand::CancelOrder { order_id } => self.handle_cancel_order(order_id).await,
                EngineCommand::MarketData(tick) => {
                    self.market_data.update(tick.clone());
                    let _ = self.event_tx.send(EngineEvent::MarketData(tick));
                }
                EngineCommand::ExecutionUpdate(report) => {
                    self.handle_execution_update(report).await;
                }
            }
        }
    }

    async fn handle_new_order(&self, req: OrderRequest) {
        if let Err(reason) = self.risk.check_order(&req) {
            let _ = self.event_tx.send(EngineEvent::OrderRejected {
                client_order_id: req.client_order_id,
                reason,
            });
            return;
        }

        let order = Order {
            order_id: Uuid::new_v4(),
            client_order_id: req.client_order_id.clone(),
            symbol: req.symbol.clone(),
            side: req.side.clone(),
            qty: req.qty,
            filled_qty: 0,
            order_type: req.order_type,
            limit_price: req.limit_price,
            status: OrderStatus::New,
            strategy_id: req.strategy_id,
            created_at: Utc::now(),
        };

        self.orders.insert(order.order_id, order.clone());
        self.persistence.save_order(&order).await;
        let _ = self.event_tx.send(EngineEvent::OrderAccepted(order.clone()));

        let execution = self.execution.clone();
        tokio::spawn(async move {
            execution.send_order(order).await;
        });
    }

    async fn handle_cancel_order(&self, order_id: Uuid) {
        if let Some(mut entry) = self.orders.get_mut(&order_id) {
            entry.status = OrderStatus::Cancelled;
            let report = ExecutionReport {
                order_id,
                client_order_id: entry.client_order_id.clone(),
                symbol: entry.symbol.clone(),
                status: OrderStatus::Cancelled,
                filled_qty: entry.filled_qty,
                last_fill_qty: 0,
                last_fill_price: None,
                reason: None,
                ts: Utc::now(),
            };
            self.persistence.save_execution_report(&report).await;
            let _ = self.event_tx.send(EngineEvent::ExecutionReport(report));
        }
    }

    async fn handle_execution_update(&self, report: ExecutionReport) {
        if let Some(mut entry) = self.orders.get_mut(&report.order_id) {
            entry.status = report.status.clone();
            entry.filled_qty = report.filled_qty;

            if report.last_fill_qty > 0 {
                self.risk
                    .apply_fill(&entry.symbol, &entry.side, report.last_fill_qty);
            }
        }

        self.persistence.save_execution_report(&report).await;
        let _ = self.event_tx.send(EngineEvent::ExecutionReport(report));
    }
}
