## `crates/core/src/strategy_api.rs`

This is a simple TCP JSON API for initial testing. In production, use **gRPC** or a binary protocol.

```rust
use crate::types::EngineCommand;
use common::OrderRequest;
use tokio::{
    io::{AsyncBufReadExt, BufReader},
    net::TcpListener,
    sync::mpsc,
};

pub async fn run_strategy_api(addr: &str, tx: mpsc::Sender<EngineCommand>) -> anyhow::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    tracing::info!("strategy API listening on {}", addr);

    loop {
        let (socket, peer) = listener.accept().await?;
        tracing::info!("strategy client connected: {}", peer);
        let tx = tx.clone();

        tokio::spawn(async move {
            let reader = BufReader::new(socket);
            let mut lines = reader.lines();

            while let Ok(Some(line)) = lines.next_line().await {
                match serde_json::from_str::<OrderRequest>(&line) {
                    Ok(req) => {
                        if tx.send(EngineCommand::NewOrder(req)).await.is_err() {
                            break;
                        }
                    }
                    Err(err) => {
                        tracing::warn!("invalid order request: {}", err);
                    }
                }
            }
        });
    }
}
```

