# 7. Order book

## `src/orderbook.rs`

This is a minimal price-time priority order book.

```rust
use std::cmp::Reverse;
use std::collections::{BTreeMap, VecDeque};

use crate::types::{Order, OrderId, Price, Qty, Side, Trade};
use chrono::Utc;

#[derive(Debug, Clone)]
pub struct BookOrder {
    pub order: Order,
    pub remaining: Qty,
}

#[derive(Debug, Default)]
pub struct OrderBook {
    pub symbol: String,
    bids: BTreeMap<Reverse<Price>, VecDeque<BookOrder>>,
    asks: BTreeMap<Price, VecDeque<BookOrder>>,
}

impl OrderBook {
    pub fn new(symbol: String) -> Self {
        Self {
            symbol,
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) -> (Vec<Trade>, Qty) {
        let mut incoming_remaining = order.qty;
        let mut trades = Vec::new();

        match order.side {
            Side::Buy => {
                while incoming_remaining > 0 {
                    let best_ask_price = match self.asks.keys().next().cloned() {
                        Some(p) => p,
                        None => break,
                    };

                    if let Some(limit_price) = order.price {
                        if best_ask_price > limit_price {
                            break;
                        }
                    }

                    let queue = self.asks.get_mut(&best_ask_price).unwrap();
                    while incoming_remaining > 0 && !queue.is_empty() {
                        let resting = queue.front_mut().unwrap();
                        let fill_qty = incoming_remaining.min(resting.remaining);

                        trades.push(Trade {
                            symbol: order.symbol.clone(),
                            buy_order_id: order.id,
                            sell_order_id: resting.order.id,
                            price: best_ask_price,
                            qty: fill_qty,
                            ts: Utc::now(),
                        });

                        incoming_remaining -= fill_qty;
                        resting.remaining -= fill_qty;

                        if resting.remaining == 0 {
                            queue.pop_front();
                        }
                    }

                    if queue.is_empty() {
                        self.asks.remove(&best_ask_price);
                    }
                }

                if incoming_remaining > 0 && order.price.is_some() {
                    self.bids
                        .entry(Reverse(order.price.unwrap()))
                        .or_default()
                        .push_back(BookOrder {
                            order,
                            remaining: incoming_remaining,
                        });
                }
            }
            Side::Sell => {
                while incoming_remaining > 0 {
                    let best_bid_price = match self.bids.keys().next().cloned() {
                        Some(Reverse(p)) => p,
                        None => break,
                    };

                    if let Some(limit_price) = order.price {
                        if best_bid_price < limit_price {
                            break;
                        }
                    }

                    let queue = self.bids.get_mut(&Reverse(best_bid_price)).unwrap();
                    while incoming_remaining > 0 && !queue.is_empty() {
                        let resting = queue.front_mut().unwrap();
                        let fill_qty = incoming_remaining.min(resting.remaining);

                        trades.push(Trade {
                            symbol: order.symbol.clone(),
                            buy_order_id: resting.order.id,
                            sell_order_id: order.id,
                            price: best_bid_price,
                            qty: fill_qty,
                            ts: Utc::now(),
                        });

                        incoming_remaining -= fill_qty;
                        resting.remaining -= fill_qty;

                        if resting.remaining == 0 {
                            queue.pop_front();
                        }
                    }

                    if queue.is_empty() {
                        self.bids.remove(&Reverse(best_bid_price));
                    }
                }

                if incoming_remaining > 0 && order.price.is_some() {
                    self.asks
                        .entry(order.price.unwrap())
                        .or_default()
                        .push_back(BookOrder {
                            order,
                            remaining: incoming_remaining,
                        });
                }
            }
        }

        (trades, incoming_remaining)
    }

    pub fn cancel_order(&mut self, order_id: OrderId) -> bool {
        for queue in self.bids.values_mut() {
            if let Some(pos) = queue.iter().position(|o| o.order.id == order_id) {
                queue.remove(pos);
                return true;
            }
        }

        for queue in self.asks.values_mut() {
            if let Some(pos) = queue.iter().position(|o| o.order.id == order_id) {
                queue.remove(pos);
                return true;
            }
        }

        false
    }

    pub fn best_bid(&self) -> Option<Price> {
        self.bids.keys().next().map(|r| r.0)
    }

    pub fn best_ask(&self) -> Option<Price> {
        self.asks.keys().next().cloned()
    }
}
