# 8. Matching engine

## `src/matching_engine.rs`

```rust
use std::collections::HashMap;

use chrono::Utc;
use crossbeam::channel::Receiver;

use crate::audit::AuditLogger;
use crate::types::{
    Event, ExecutionReport, ExecutionReportStatus, Order, Symbol,
};
use crate::orderbook::OrderBook;
use crate::event_bus::EventBus;

pub struct MatchingEngine {
    books: HashMap<Symbol, OrderBook>,
    bus: EventBus,
    audit: AuditLogger,
}

impl MatchingEngine {
    pub fn new(bus: EventBus, audit: AuditLogger) -> Self {
        Self {
            books: HashMap::new(),
            bus,
            audit,
        }
    }

    fn get_book(&mut self, symbol: &str) -> &mut OrderBook {
        self.books
            .entry(symbol.to_string())
            .or_insert_with(|| OrderBook::new(symbol.to_string()))
    }

    pub fn run(mut self, rx: Receiver<Event>) {
        while let Ok(event) = rx.recv() {
            self.audit.log(&event);

            match event {
                Event::NewOrder(order) => self.handle_new_order(order),
                Event::CancelOrder { order_id, symbol, .. } => {
                    self.handle_cancel(order_id, &symbol)
                }
                _ => {}
            }
        }
    }

    fn handle_new_order(&mut self, order: Order) {
        self.bus.publish(Event::ExecutionReport(ExecutionReport {
            order_id: order.id,
            status: ExecutionReportStatus::Accepted,
            filled_qty: 0,
            remaining_qty: order.qty,
            ts: Utc::now(),
        }));

        let book = self.get_book(&order.symbol);
        let (trades, remaining) = book.add_order(order.clone());

        let filled = order.qty - remaining;

        for trade in trades {
            self.bus.publish(Event::Trade(trade));
        }

        let status = if remaining == 0 {
            ExecutionReportStatus::Filled
        } else if filled > 0 {
            ExecutionReportStatus::PartiallyFilled
        } else {
            ExecutionReportStatus::Accepted
        };

        self.bus.publish(Event::ExecutionReport(ExecutionReport {
            order_id: order.id,
            status,
            filled_qty: filled,
            remaining_qty: remaining,
            ts: Utc::now(),
        }));

        let bid = book.best_bid();
        let ask = book.best_ask();
        self.bus.publish(Event::MarketData {
            symbol: order.symbol,
            bid,
            ask,
            ts: Utc::now(),
        });
    }

    fn handle_cancel(&mut self, order_id: uuid::Uuid, symbol: &str) {
        let cancelled = self.get_book(symbol).cancel_order(order_id);

        let status = if cancelled {
            ExecutionReportStatus::Cancelled
        } else {
            ExecutionReportStatus::Rejected("Order not found".to_string())
        };

        self.bus.publish(Event::ExecutionReport(ExecutionReport {
            order_id,
            status,
            filled_qty: 0,
            remaining_qty: 0,
            ts: Utc::now(),
        }));
    }
}
```

