This is intentionally basic. It should be expanded later with notional, fat-finger, position, and credit checks.

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use crate::types::{Order, Qty};

#[derive(Clone)]
pub struct RiskManager {
    max_order_qty: Qty,
    account_limits: Arc<Mutex<HashMap<String, Qty>>>,
}

impl RiskManager {
    pub fn new(max_order_qty: Qty) -> Self {
        Self {
            max_order_qty,
            account_limits: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn set_account_limit(&self, account: String, max_qty: Qty) {
        self.account_limits.lock().unwrap().insert(account, max_qty);
    }

    pub fn check_order(&self, order: &Order) -> Result<(), String> {
        if order.qty == 0 {
            return Err("Quantity cannot be zero".to_string());
        }

        if order.qty > self.max_order_qty {
            return Err(format!("Order qty exceeds global max {}", self.max_order_qty));
        }

        if let Some(limit) = self.account_limits.lock().unwrap().get(&order.account) {
            if order.qty > *limit {
                return Err(format!("Order qty exceeds account max {}", limit));
            }
        }

        if matches!(order.order_type, crate::types::OrderType::Limit) && order.price.is_none() {
            return Err("Limit order requires price".to_string());
        }

        Ok(())
    }
}
```

