# 10. Gateway

## `src/gateway.rs`

The gateway performs pre-trade risk checks before publishing to the engine.

```rust
use chrono::Utc;

use crate::event_bus::EventBus;
use crate::risk::RiskManager;
use crate::types::{Event, ExecutionReport, ExecutionReportStatus, Order};

#[derive(Clone)]
pub struct OrderGateway {
    bus: EventBus,
    risk: RiskManager,
}

impl OrderGateway {
    pub fn new(bus: EventBus, risk: RiskManager) -> Self {
        Self { bus, risk }
    }

    pub fn submit_order(&self, order: Order) {
        match self.risk.check_order(&order) {
            Ok(_) => self.bus.publish(Event::NewOrder(order)),
            Err(reason) => {
                self.bus.publish(Event::ExecutionReport(ExecutionReport {
                    order_id: order.id,
                    status: ExecutionReportStatus::Rejected(reason),
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    ts: Utc::now(),
                }));
            }
        }
    }

    pub fn cancel_order(
        &self,
        order_id: uuid::Uuid,
        account: String,
        symbol: String,
    ) {
        self.bus.publish(Event::CancelOrder {
            order_id,
            account,
            symbol,
            ts: Utc::now(),
        });
    }
}
```

