pub struct RiskLimits {
    pub max_order_qty: u64,
    pub enabled: bool,
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check(&self, req: &OrderRequest) -> RiskDecision {
        if !self.limits.enabled {
            return RiskDecision::Rejected("risk_disabled");
        }

        if req.qty > self.limits.max_order_qty {
            return RiskDecision::Rejected("max_order_qty_exceeded");
        }

        RiskDecision::Approved
    }
}
