```rust
use std::collections::HashMap;

use crate::common::events::{ExchangeEvent, NewOrder, OrderId, OrderRequest};

#[derive(Debug, Clone, Copy)]
pub enum OrderStatus {
    PendingNew,
    Acked,
    Rejected,
    PartiallyFilled,
    Filled,
}

#[derive(Debug, Clone, Copy)]
pub struct OrderState {
    pub order_id: OrderId,
    pub request: OrderRequest,
    pub filled_qty: u64,
    pub status: OrderStatus,
}

pub struct OrderManager {
    next_order_id: u64,
    orders: HashMap<u64, OrderState>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            next_order_id: 1,
            orders: HashMap::new(),
        }
    }

    pub fn create_order(&mut self, req: OrderRequest) -> NewOrder {
        let order_id = OrderId(self.next_order_id);
        self.next_order_id += 1;

        let state = OrderState {
            order_id,
            request: req,
            filled_qty: 0,
            status: OrderStatus::PendingNew,
        };

        self.orders.insert(order_id.0, state);

        NewOrder { order_id, request: req }
    }

    pub fn on_exchange_event(&mut self, event: ExchangeEvent) {
        match event {
            ExchangeEvent::Ack { order_id, .. } => {
                if let Some(order) = self.orders.get_mut(&order_id.0) {
                    order.status = OrderStatus::Acked;
                }
            }
            ExchangeEvent::Reject { order_id, .. } => {
                if let Some(order) = self.orders.get_mut(&order_id.0) {
                    order.status = OrderStatus::Rejected;
                }
            }
            ExchangeEvent::Fill {
                order_id,
                fill_qty,
                ..
            } => {
                if let Some(order) = self.orders.get_mut(&order_id.0) {
                    order.filled_qty += fill_qty;
                    if order.filled_qty >= order.request.qty {
                        order.status = OrderStatus::Filled;
                    } else {
                        order.status = OrderStatus::PartiallyFilled;
                    }
                }
            }
        }
    }
}
```

