```rust
use std::collections::HashMap;

use crate::common::events::{ExchangeEvent, InstrumentId, Side};

pub struct PositionManager {
    positions: HashMap<u64, i64>,
    order_to_instrument: HashMap<u64, (InstrumentId, Side)>,
}

impl PositionManager {
    pub fn new() -> Self {
        Self {
            positions: HashMap::new(),
            order_to_instrument: HashMap::new(),
        }
    }

    pub fn register_order(
        &mut self,
        order_id: u64,
        instrument_id: InstrumentId,
        side: Side,
    ) {
        self.order_to_instrument
            .insert(order_id, (instrument_id, side));
    }

    pub fn on_exchange_event(&mut self, event: ExchangeEvent) {
        if let ExchangeEvent::Fill {
            order_id,
            fill_qty,
            ..
        } = event
        {
            if let Some((instrument_id, side)) = self.order_to_instrument.get(&order_id.0) {
                let pos = self.positions.entry(instrument_id.0).or_insert(0);
                match side {
                    Side::Buy => *pos += fill_qty as i64,
                    Side::Sell => *pos -= fill_qty as i64,
                }
            }
        }
    }

    pub fn get_position(&self, instrument_id: InstrumentId) -> i64 {
        *self.positions.get(&instrument_id.0).unwrap_or(&0)
    }
}
