use crate::common::events::{ExchangeEvent, NewOrder};
use crate::gateway::exchange_gateway::ExchangeGateway;

pub struct MockGateway {
    pending: Vec<ExchangeEvent>,
}

impl MockGateway {
    pub fn new() -> Self {
        Self { pending: Vec::new() }
    }
}

impl ExchangeGateway for MockGateway {
    fn send_order(&mut self, order: NewOrder) {
        self.pending.push(ExchangeEvent::Ack {
            order_id: order.order_id,
            ts_nanos: order.request.ts_nanos + 1000,
        });

        self.pending.push(ExchangeEvent::Fill {
            order_id: order.order_id,
            fill_qty: order.request.qty,
            fill_price_ticks: match order.request.order_type {
                crate::common::events::OrderType::Market => 100,
                crate::common::events::OrderType::Limit { price_ticks } => price_ticks,
            },
            ts_nanos: order.request.ts_nanos + 2000,
        });
    }

    fn poll(&mut self) -> Vec<ExchangeEvent> {
        std::mem::take(&mut self.pending)
    }
}
