use common::events::*;
use gateway::exchange_gateway::ExchangeGateway;
use gateway::mock_gateway::MockGateway;
use oms::order_manager::OrderManager;
use positions::manager::PositionManager;
use risk::engine::{RiskEngine, RiskLimits};
use strategy::engine::StrategyEngine;
use strategy::traits::Strategy;

struct SimpleStrategy;

impl Strategy for SimpleStrategy {
    fn on_market_data(&mut self, md: MarketDataEvent) -> Option<OrderRequest> {
        let spread = md.ask_ticks - md.bid_ticks;
        if spread >= 2 {
            Some(OrderRequest {
                strategy_id: StrategyId(1),
                instrument_id: md.instrument_id,
                side: Side::Buy,
                qty: 10,
                order_type: OrderType::Limit {
                    price_ticks: md.bid_ticks,
                },
                ts_nanos: md.ts_nanos,
            })
        } else {
            None
        }
    }
}

fn main() {
    let mut strategy_engine = StrategyEngine::new();
    strategy_engine.register(Box::new(SimpleStrategy));

    let risk_engine = RiskEngine::new(RiskLimits {
        max_order_qty: 100,
        enabled: true,
    });

    let mut order_manager = OrderManager::new();
    let mut position_manager = PositionManager::new();
    let mut gateway = MockGateway::new();

    let market_data = vec![
        MarketDataEvent {
            instrument_id: InstrumentId(1),
            bid_ticks: 100,
            ask_ticks: 103,
            ts_nanos: 1_000_000,
        },
        MarketDataEvent {
            instrument_id: InstrumentId(1),
            bid_ticks: 101,
            ask_ticks: 102,
            ts_nanos: 2_000_000,
        },
    ];

    for md in market_data {
        let requests = strategy_engine.on_market_data(md);

        for req in requests {
            match risk_engine.check(&req) {
                RiskDecision::Approved => {
                    let new_order = order_manager.create_order(req);
                    position_manager.register_order(
                        new_order.order_id.0,
                        new_order.request.instrument_id,
                        new_order.request.side,
                    );
                    gateway.send_order(new_order);
                }
                RiskDecision::Rejected(reason) => {
                    println!("order rejected by risk: {}", reason);
                }
            }
        }

        for event in gateway.poll() {
            order_manager.on_exchange_event(event);
            position_manager.on_exchange_event(event);
            println!("exchange event: {:?}", event);
        }
    }

    println!("final position: {}", position_manager.get_position(InstrumentId(1)));
}
