use anyhow::Result;
use common::pb::{OrderIntent, OrderType, Side, MarketEvent};
use std::time::{SystemTime, UNIX_EPOCH};
use tracing::info;
use uuid::Uuid;

fn now_nanos() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as i64
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt().json().init();

    let nats = async_nats::connect("nats://127.0.0.1:4222").await?;
    let mut sub = nats.subscribe("market.SIM.FOO".into()).await?;

    while let Some(msg) = sub.next().await {
        let event: MarketEvent = serde_json::from_slice(&msg.payload)?;

        let side = if event.last < 99.5 {
            Some(Side::Buy)
        } else if event.last > 100.5 {
            Some(Side::Sell)
        } else {
            None
        };

        if let Some(side) = side {
            let intent = OrderIntent {
                strategy_id: "mean-reversion-1".into(),
                client_order_id: Uuid::new_v4().to_string(),
                instrument: event.instrument.clone(),
                side: side as i32,
                order_type: OrderType::Market as i32,
                quantity: 10.0,
                limit_price: 0.0,
                ts_nanos: now_nanos(),
            };

            nats.publish("intent.orders".into(), serde_json::to_vec(&intent)?.into()).await?;
            info!(client_order_id = intent.client_order_id, "published order intent");
        }
