use anyhow::Result;
use common::pb::{OrderIntent, RiskDecision};
use tracing::info;

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt().json().init();

    let nats = async_nats::connect("nats://127.0.0.1:4222").await?;
    let mut sub = nats.subscribe("intent.orders".into()).await?;

    let kill_switch = false;
    let max_qty = 100.0;

    while let Some(msg) = sub.next().await {
        let intent: OrderIntent = serde_json::from_slice(&msg.payload)?;

        let approved = !kill_switch
            && intent.quantity <= max_qty
            && intent.instrument.as_ref().map(|i| i.symbol.as_str()) == Some("FOO");

        let reason = if approved {
            "approved".to_string()
        } else {
            "rejected by risk".to_string()
        };

        let decision = RiskDecision {
            approved,
            reason,
            intent: Some(intent),
        };

        nats.publish("risk.decisions".into(), serde_json::to_vec(&decision)?.into()).await?;
        info!("published risk decision");
    }

    Ok(())
}
