use anyhow::Result;
use common::pb::{Order, OrderStatus, RiskDecision};
use dashmap::DashMap;
use tracing::info;
use uuid::Uuid;

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt().json().init();

    let nats = async_nats::connect("nats://127.0.0.1:4222").await?;
    let mut risk_sub = nats.subscribe("risk.decisions".into()).await?;
    let mut exec_sub = nats.subscribe("orders.execution".into()).await?;

    let orders: DashMap<String, Order> = DashMap::new();

    loop {
        tokio::select! {
            Some(msg) = risk_sub.next() => {
                let decision: RiskDecision = serde_json::from_slice(&msg.payload)?;
                if decision.approved {
                    if let Some(intent) = decision.intent {
                        let order = Order {
                            order_id: Uuid::new_v4().to_string(),
                            client_order_id: intent.client_order_id,
                            strategy_id: intent.strategy_id,
                            instrument: intent.instrument,
                            side: intent.side,
                            order_type: intent.order_type,
                            quantity: intent.quantity,
                            limit_price: intent.limit_price,
                            status: OrderStatus::New as i32,
                            created_at_nanos: intent.ts_nanos,
                        };

                        orders.insert(order.order_id.clone(), order.clone());
                        nats.publish("orders.created".into(), serde_json::to_vec(&order)?.into()).await?;
                        info!(order_id = order.order_id, "created order");
                    }
                }
            }
            Some(msg) = exec_sub.next() => {
                let report: common::pb::ExecutionReport = serde_json::from_slice(&msg.payload)?;
                if let Some(mut existing) = orders.get_mut(&report.order_id) {
                    existing.status = report.status;
                    info!(order_id = report.order_id, status = report.status, "updated order status");
                }
            }
        }
    }
}
