```rust
use anyhow::Result;
use common::pb::{ExecutionReport, Order, OrderStatus};
use rand::Rng;
use std::time::{SystemTime, UNIX_EPOCH};
use tracing::info;

fn now_nanos() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as i64
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt().json().init();

    let nats = async_nats::connect("nats://127.0.0.1:4222").await?;
    let mut sub = nats.subscribe("orders.created".into()).await?;

    while let Some(msg) = sub.next().await {
        let order: Order = serde_json::from_slice(&msg.payload)?;

        let ack = ExecutionReport {
            order_id: order.order_id.clone(),
            client_order_id: order.client_order_id.clone(),
            status: OrderStatus::Acknowledged as i32,
            filled_qty: 0.0,
            fill_price: 0.0,
            ts_nanos: now_nanos(),
            reason: "".into(),
        };

        nats.publish("orders.execution".into(), serde_json::to_vec(&ack)?.into()).await?;
        info!(order_id = order.order_id, "sent ack");

        let fill_px = 100.0 + rand::thread_rng().gen_range(-0.2..0.2);
        let fill = ExecutionReport {
            order_id: order.order_id.clone(),
            client_order_id: order.client_order_id.clone(),
            status: OrderStatus::Filled as i32,
            filled_qty: order.quantity,
            fill_price: fill_px,
            ts_nanos: now_nanos(),
            reason: "".into(),
        };

        tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        nats.publish("orders.execution".into(), serde_json::to_vec(&fill)?.into()).await?;
        info!(order_id = order.order_id, fill_price = fill_px, "sent fill");
    }

    Ok(())
}
```

