```rust
use anyhow::Result;
use common::pb::{ExecutionReport, Position, Side};
use dashmap::DashMap;
use tracing::info;

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt().json().init();

    let nats = async_nats::connect("nats://127.0.0.1:4222").await?;
    let mut exec_sub = nats.subscribe("orders.execution".into()).await?;
    let positions: DashMap<String, Position> = DashMap::new();

    while let Some(msg) = exec_sub.next().await {
        let report: ExecutionReport = serde_json::from_slice(&msg.payload)?;
        if report.status != common::pb::OrderStatus::Filled as i32 {
            continue;
        }

        let key = "SIM:FOO".to_string();
        let mut pos = positions.entry(key.clone()).or_insert(Position {
            instrument: Some(common::pb::Instrument {
                venue: "SIM".into(),
                symbol: "FOO".into(),
            }),
            net_qty: 0.0,
            avg_price: 0.0,
            realized_pnl: 0.0,
            unrealized_pnl: 0.0,
        });

        pos.net_qty += report.filled_qty;
        pos.avg_price = report.fill_price;

        nats.publish("positions.updated".into(), serde_json::to_vec(&*pos)?.into()).await?;
        info!(net_qty = pos.net_qty, avg_price = pos.avg_price, "updated position");
    }

    Ok(())
}
```

Note: this is intentionally simplified. In production, fills must carry side/instrument/order linkage sufficient for correct position accounting.

