// trading-core/src/risk.rs
use common::order::NewOrderRequest;

pub trait RiskChecker: Send + Sync {
    fn check(&self, order: &NewOrderRequest) -> Result<(), String>;
}

pub struct SimpleRiskChecker;

impl RiskChecker for SimpleRiskChecker {
    fn check(&self, order: &NewOrderRequest) -> Result<(), String> {
        if order.quantity <= 0 {
            return Err("quantity must be positive".into());
        }
        if matches!(order.order_type, common::types::OrderType::Limit) && order.price.is_none() {
            return Err("limit order requires price".into());
        }
        Ok(())
    }
}
