## Order book skeleton

```rust
// trading-core/src/order_book.rs
use std::collections::{BTreeMap, HashMap, VecDeque};
use common::order::Order;
use common::events::Event;
use common::types::*;

#[derive(Debug)]
struct RestingOrder {
    order: Order,
}

pub struct OrderBook {
    instrument_id: InstrumentId,
    bids: BTreeMap<Price, VecDeque<RestingOrder>>, // ascending; iterate reverse for best bid
    asks: BTreeMap<Price, VecDeque<RestingOrder>>, // ascending; best ask first
    order_index: HashMap<OrderId, (Side, Price)>,
    next_trade_id: u64,
}

impl OrderBook {
    pub fn new(instrument_id: InstrumentId) -> Self {
        Self {
            instrument_id,
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
            order_index: HashMap::new(),
            next_trade_id: 1,
        }
    }

    pub fn submit_order(&mut self, mut incoming: Order) -> Vec<Event> {
        let mut events = vec![Event::OrderAccepted {
            order_id: incoming.order_id,
            instrument_id: self.instrument_id,
        }];

        match incoming.side {
            Side::Buy => self.match_buy(&mut incoming, &mut events),
            Side::Sell => self.match_sell(&mut incoming, &mut events),
        }

        if incoming.remaining() > 0
            && incoming.order_type == OrderType::Limit
            && incoming.tif == TimeInForce::Gtc
        {
            let price = incoming.price.unwrap();
            self.rest_order(incoming, price);
            events.push(Event::OrderRested {
                order_id: self.last_order_id(),
                instrument_id: self.instrument_id,
                price,
                remaining: self.last_remaining(),
            });
        }

        events
    }

    fn match_buy(&mut self, incoming: &mut Order, events: &mut Vec<Event>) {
        while incoming.remaining() > 0 {
            let best_ask_price = match self.asks.keys().next().copied() {
                Some(p) => p,
                None => break,
            };

            if let Some(limit_price) = incoming.price {
                if best_ask_price > limit_price {
                    break;
                }
            }

            self.execute_against_level(Side::Sell, best_ask_price, incoming, events);
        }
    }

    fn match_sell(&mut self, incoming: &mut Order, events: &mut Vec<Event>) {
        while incoming.remaining() > 0 {
            let best_bid_price = match self.bids.keys().next_back().copied() {
                Some(p) => p,
                None => break,
            };

            if let Some(limit_price) = incoming.price {
                if best_bid_price < limit_price {
                    break;
                }
            }

            self.execute_against_level(Side::Buy, best_bid_price, incoming, events);
        }
    }

    fn execute_against_level(
        &mut self,
        resting_side: Side,
        price: Price,
        incoming: &mut Order,
        events: &mut Vec<Event>,
    ) {
        let book_side = match resting_side {
            Side::Buy => &mut self.bids,
            Side::Sell => &mut self.asks,
        };

        let mut remove_level = false;

        if let Some(queue) = book_side.get_mut(&price) {
            while incoming.remaining() > 0 && !queue.is_empty() {
                let resting = queue.front_mut().unwrap();
                let exec_qty = incoming.remaining().min(resting.order.remaining());

                incoming.filled_quantity += exec_qty;
                resting.order.filled_quantity += exec_qty;

                let (buy_order_id, sell_order_id) = match incoming.side {
                    Side::Buy => (incoming.order_id, resting.order.order_id),
                    Side::Sell => (resting.order.order_id, incoming.order_id),
                };

                events.push(Event::TradeExecuted {
                    trade_id: self.next_trade_id,
                    instrument_id: self.instrument_id,
                    buy_order_id,
                    sell_order_id,
                    price,
                    quantity: exec_qty,
                    ts_nanos: current_time_nanos(),
                });
                self.next_trade_id += 1;

                if resting.order.remaining() == 0 {
                    let completed = queue.pop_front().unwrap();
                    self.order_index.remove(&completed.order.order_id);
                }
            }

            remove_level = queue.is_empty();
        }

        if remove_level {
            book_side.remove(&price);
        }
    }

    fn rest_order(&mut self, order: Order, price: Price) {
        let side = order.side;
        let order_id = order.order_id;

        let book_side = match side {
            Side::Buy => &mut self.bids,
            Side::Sell => &mut self.asks,
        };

        book_side
            .entry(price)
            .or_insert_with(VecDeque::new)
            .push_back(RestingOrder { order });

        self.order_index.insert(order_id, (side, price));
    }

    pub fn cancel_order(&mut self, order_id: OrderId) -> Option<Event> {
        let (side, price) = self.order_index.get(&order_id).copied()?;
        let book_side = match side {
            Side::Buy => &mut self.bids,
            Side::Sell => &mut self.asks,
        };

        if let Some(queue) = book_side.get_mut(&price) {
            if let Some(pos) = queue.iter().position(|o| o.order.order_id == order_id) {
                queue.remove(pos);
                self.order_index.remove(&order_id);

                if queue.is_empty() {
                    book_side.remove(&price);
                }

                return Some(Event::OrderCanceled {
                    order_id,
                    instrument_id: self.instrument_id,
                });
            }
        }

        None
    }

    fn last_order_id(&self) -> OrderId {
        0
    }

    fn last_remaining(&self) -> Quantity {
        0
    }
}

fn current_time_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

Note: `last_order_id()` and `last_remaining()` are placeholders. In a real implementation, emit `OrderRested` directly from the incoming order before moving it.

