```rust
// trading-core/src/engine.rs
use std::collections::HashMap;
use std::sync::Arc;

use common::events::Event;
use common::order::{NewOrderRequest, Order};
use common::types::*;
use crate::order_book::OrderBook;
use crate::risk::RiskChecker;

pub struct TradingEngine<R: RiskChecker> {
    books: HashMap<InstrumentId, OrderBook>,
    risk: Arc<R>,
    next_order_id: OrderId,
}

impl<R: RiskChecker> TradingEngine<R> {
    pub fn new(risk: Arc<R>) -> Self {
        Self {
            books: HashMap::new(),
            risk,
            next_order_id: 1,
        }
    }

    pub fn submit_order(&mut self, req: NewOrderRequest) -> Vec<Event> {
        if let Err(reason) = self.risk.check(&req) {
            return vec![Event::OrderRejected {
                client_order_id: req.client_order_id,
                reason,
            }];
        }

        let order = Order {
            order_id: self.next_order_id,
            client_order_id: req.client_order_id,
            account_id: req.account_id,
            instrument_id: req.instrument_id,
            side: req.side,
            order_type: req.order_type,
            price: req.price,
            quantity: req.quantity,
            filled_quantity: 0,
            status: OrderStatus::New,
            tif: req.tif,
            created_at_nanos: current_time_nanos(),
        };
        self.next_order_id += 1;

        let book = self.books
            .entry(order.instrument_id)
            .or_insert_with(|| OrderBook::new(order.instrument_id));

        book.submit_order(order)
    }

    pub fn cancel_order(
        &mut self,
        instrument_id: InstrumentId,
        order_id: OrderId,
    ) -> Option<Event> {
        self.books.get_mut(&instrument_id)?.cancel_order(order_id)
    }
}

