# 7. Matching engine design

For an initial implementation, use:

- `TreeMap<Long, Deque<Order>>` for bids and asks
- Bids sorted descending
- Asks sorted ascending
- FIFO within each price level

This is not the absolute fastest possible structure, but it is:
- Correct
- Easy to reason about
- Easy to replace later with array-based or custom intrusive structures

## Order book structure
```java
import java.util.*;

public final class OrderBook {
    private final NavigableMap<Long, Deque<Order>> bids =
        new TreeMap<>(Comparator.reverseOrder());
    private final NavigableMap<Long, Deque<Order>> asks =
        new TreeMap<>();

    private final Map<Long, Order> ordersById = new HashMap<>();

    public synchronized List<Trade> add(Order incoming, IdGenerator tradeIds) {
        List<Trade> trades = new ArrayList<>();
        if (incoming.side == Side.BUY) {
            matchBuy(incoming, trades, tradeIds);
            if (incoming.openQuantity > 0 && incoming.type == OrderType.LIMIT && incoming.tif == TimeInForce.GTC) {
                addToBook(bids, incoming);
            }
        } else {
            matchSell(incoming, trades, tradeIds);
            if (incoming.openQuantity > 0 && incoming.type == OrderType.LIMIT && incoming.tif == TimeInForce.GTC) {
                addToBook(asks, incoming);
            }
        }

        if (incoming.openQuantity > 0 && incoming.tif != TimeInForce.GTC) {
            incoming.openQuantity = 0;
        }

        return trades;
    }

    public synchronized boolean cancel(long orderId) {
        Order order = ordersById.remove(orderId);
        if (order == null) return false;

        NavigableMap<Long, Deque<Order>> book = order.side == Side.BUY ? bids : asks;
        Deque<Order> level = book.get(order.price);
        if (level != null) {
            level.removeIf(o -> o.orderId == orderId);
            if (level.isEmpty()) {
                book.remove(order.price);
            }
        }
        order.openQuantity = 0;
        return true;
    }

    private void matchBuy(Order incoming, List<Trade> trades, IdGenerator tradeIds) {
        while (incoming.openQuantity > 0 && !asks.isEmpty()) {
            Map.Entry<Long, Deque<Order>> bestAsk = asks.firstEntry();
            long askPrice = bestAsk.getKey();

            if (incoming.type == OrderType.LIMIT && incoming.price < askPrice) {
                break;
            }

            Deque<Order> level = bestAsk.getValue();
            while (incoming.openQuantity > 0 && !level.isEmpty()) {
                Order resting = level.peekFirst();
                long qty = Math.min(incoming.openQuantity, resting.openQuantity);

                incoming.openQuantity -= qty;
                resting.openQuantity -= qty;

                trades.add(new Trade(
                    tradeIds.next(),
                    incoming.instrument,
                    incoming.orderId,
                    resting.orderId,
                    qty,
                    resting.price,
                    System.nanoTime()
                ));

                if (resting.openQuantity == 0) {
                    level.removeFirst();
                    ordersById.remove(resting.orderId);
                }
            }

            if (level.isEmpty()) {
                asks.remove(askPrice);
            }
        }
    }

    private void matchSell(Order incoming, List<Trade> trades, IdGenerator tradeIds) {
        while (incoming.openQuantity > 0 && !bids.isEmpty()) {
            Map.Entry<Long, Deque<Order>> bestBid = bids.firstEntry();
            long bidPrice = bestBid.getKey();

            if (incoming.type == OrderType.LIMIT && incoming.price > bidPrice) {
                break;
            }

            Deque<Order> level = bestBid.getValue();
            while (incoming.openQuantity > 0 && !level.isEmpty()) {
                Order resting = level.peekFirst();
                long qty = Math.min(incoming.openQuantity, resting.openQuantity);

                incoming.openQuantity -= qty;
                resting.openQuantity -= qty;

                trades.add(new Trade(
                    tradeIds.next(),
                    incoming.instrument,
                    resting.orderId,
                    incoming.orderId,
                    qty,
                    resting.price,
                    System.nanoTime()
                ));

                if (resting.openQuantity == 0) {
                    level.removeFirst();
                    ordersById.remove(resting.orderId);
                }
            }

            if (level.isEmpty()) {
                bids.remove(bidPrice);
            }
        }
    }

    private void addToBook(NavigableMap<Long, Deque<Order>> book, Order order) {
        book.computeIfAbsent(order.price, p -> new ArrayDeque<>()).addLast(order);
        ordersById.put(order.orderId, order);
    }
}
```

