# 15. Example orchestrator

```java
import java.util.*;
import java.util.concurrent.*;

public final class TradingPlatform {
    private final List<ExecutionPartition> partitions = new ArrayList<>();
    private final List<Thread> threads = new ArrayList<>();
    private final RiskChecker riskChecker;

    public TradingPlatform(int partitionCount, RiskChecker riskChecker) {
        this.riskChecker = riskChecker;

        for (int i = 0; i < partitionCount; i++) {
            ExecutionPartition partition = new ExecutionPartition(
                new AtomicIdGenerator(i * 1_000_000L),
                new AtomicIdGenerator(i * 10_000_000L)
            );
            partitions.add(partition);

            Thread t = new Thread(partition, "exec-partition-" + i);
            t.start();
            threads.add(t);
        }
    }

    public String submit(NewOrderRequest request) {
        RiskResult risk = riskChecker.check(request);
        if (!risk.allowed()) {
            return "REJECTED: " + risk.reason();
        }

        int partition = partitionFor(request.instrument());
        partitions.get(partition).submit(new NewOrderCommand(request));
        return "ACCEPTED";
    }

    public String cancel(String instrument, long orderId) {
        int partition = partitionFor(instrument);
        partitions.get(partition).submit(new CancelOrderCommand(instrument, orderId));
        return "CANCEL_SUBMITTED";
    }

    private int partitionFor(String instrument) {
        return Math.floorMod(instrument.hashCode(), partitions.size());
    }

    public void shutdown() {
        partitions.forEach(ExecutionPartition::stop);
        threads.forEach(Thread::interrupt);
    }
}
```

