# 10. Risk Engine

```java
package com.trading.risk;

import com.trading.common.OrderRequest;
import com.trading.common.bus.EventHandler;
import com.trading.common.bus.InMemoryEventBus;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RiskEngine implements EventHandler<OrderRequest> {
    private final InMemoryEventBus<OrderRequest> approvedOrdersBus;
    private final Map<String, Long> maxOrderSizeBySymbol = new ConcurrentHashMap<>();
    private final Map<String, Long> currentPositionBySymbol = new ConcurrentHashMap<>();
    private final Map<String, Long> maxPositionBySymbol = new ConcurrentHashMap<>();
    private volatile boolean killSwitch = false;

    public RiskEngine(InMemoryEventBus<OrderRequest> approvedOrdersBus) {
        this.approvedOrdersBus = approvedOrdersBus;
    }

    public void setMaxOrderSize(String symbol, long size) {
        maxOrderSizeBySymbol.put(symbol, size);
    }

    public void setMaxPosition(String symbol, long pos) {
        maxPositionBySymbol.put(symbol, pos);
    }

    public void updatePosition(String symbol, long position) {
        currentPositionBySymbol.put(symbol, position);
    }

    public void setKillSwitch(boolean enabled) {
        this.killSwitch = enabled;
    }

    @Override
    public void onEvent(OrderRequest order) {
        if (killSwitch) {
            System.err.println("Order blocked by kill switch: " + order.strategyOrderId);
            return;
        }

        long maxOrderSize = maxOrderSizeBySymbol.getOrDefault(order.symbol, 0L);
        if (order.quantity > maxOrderSize) {
            System.err.println("Order rejected: max order size exceeded " + order.strategyOrderId);
            return;
        }

        long currentPos = currentPositionBySymbol.getOrDefault(order.symbol, 0L);
        long maxPos = maxPositionBySymbol.getOrDefault(order.symbol, 0L);

        long projectedPos = order.side.name().equals("BUY")
                ? currentPos + order.quantity
                : currentPos - order.quantity;

        if (Math.abs(projectedPos) > maxPos) {
            System.err.println("Order rejected: max position exceeded " + order.strategyOrderId);
            return;
        }

        approvedOrdersBus.publish(order);
    }
}
```

