import java.util.concurrent.atomic.AtomicLong;

public class OrderManagementSystem implements EventHandler<OrderRequest> {
    private final AtomicLong internalOrderIdGenerator = new AtomicLong(1000);
    private final Map<Long, OrderRequest> liveOrders = new ConcurrentHashMap<>();
    private final InMemoryEventBus<OrderRequest> executionBus;
    private final InMemoryEventBus<ExecutionReport> executionReportBus;

    public OrderManagementSystem(
            InMemoryEventBus<OrderRequest> executionBus,
            InMemoryEventBus<ExecutionReport> executionReportBus) {
        this.executionBus = executionBus;
        this.executionReportBus = executionReportBus;
    }

    @Override
    public void onEvent(OrderRequest order) {
        long internalId = internalOrderIdGenerator.incrementAndGet();
        liveOrders.put(internalId, order);

        executionBus.publish(order);

        ExecutionReport ack = new ExecutionReport();
        ack.internalOrderId = internalId;
        ack.strategyOrderId = order.strategyOrderId;
        ack.symbol = order.symbol;
        ack.status = OrderStatus.ACCEPTED;
        ack.exchangeTsNanos = System.nanoTime();

        executionReportBus.publish(ack);
    }
}
