```java
package com.trading.positions;

import com.trading.common.ExecutionReport;
import com.trading.common.OrderStatus;
import com.trading.common.bus.EventHandler;
import com.trading.risk.RiskEngine;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PositionService implements EventHandler<ExecutionReport> {
    private final Map<String, Long> positions = new ConcurrentHashMap<>();
    private final RiskEngine riskEngine;

    public PositionService(RiskEngine riskEngine) {
        this.riskEngine = riskEngine;
    }

    @Override
    public void onEvent(ExecutionReport report) {
        if (report.status != OrderStatus.FILLED && report.status != OrderStatus.PARTIALLY_FILLED) {
            return;
        }

        positions.merge(report.symbol, report.filledQty, Long::sum);
        riskEngine.updatePosition(report.symbol, positions.get(report.symbol));

        System.out.println("Updated position " + report.symbol + " = " + positions.get(report.symbol));
    }

    public long getPosition(String symbol) {
        return positions.getOrDefault(symbol, 0L);
    }
}
```

Note: in a real system, fill side must be included so positions update correctly for buys vs sells.

