use bus::EventBus;
use chrono::Utc;
use common::{MarketDataEvent, OrderRequest, OrderType, SignalEvent, TimeInForce, Side};
use tokio::sync::broadcast::error::RecvError;
use uuid::Uuid;

pub async fn run_strategy(
    md_bus: EventBus<MarketDataEvent>,
    signal_bus: EventBus<SignalEvent>,
) {
    let mut rx = md_bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(md) => {
                if md.last.to_string().ends_with("00") {
                    let signal = SignalEvent {
                        strategy_id: "mean_reversion_1".to_string(),
                        instrument: md.instrument.clone(),
                        side: Side::Buy,
                        qty: 1.into(),
                        limit_price: Some(md.bid),
                        ts: Utc::now(),
                    };
                    signal_bus.publish(signal);
                }
            }
            Err(RecvError::Lagged(_)) => continue,
            Err(_) => break,
        }
    }
}

pub fn signal_to_order(signal: SignalEvent) -> OrderRequest {
    OrderRequest {
        order_id: Uuid::new_v4(),
        strategy_id: signal.strategy_id,
        instrument: signal.instrument,
        side: signal.side,
        qty: signal.qty,
        order_type: OrderType::Limit,
        limit_price: signal.limit_price,
        tif: TimeInForce::IOC,
        ts: signal.ts,
    }
}
```

