use bus::EventBus;
use chrono::Utc;
use common::{RiskDecision, SignalEvent};
use rust_decimal::Decimal;
use strategy::signal_to_order;
use tokio::sync::broadcast::error::RecvError;

pub async fn run_risk(
    signal_bus: EventBus<SignalEvent>,
    risk_bus: EventBus<RiskDecision>,
) {
    let mut rx = signal_bus.subscribe();
    let max_order_qty = Decimal::from(10);

    loop {
        match rx.recv().await {
            Ok(signal) => {
                if signal.qty > max_order_qty {
                    risk_bus.publish(RiskDecision::Rejected {
                        order_id: uuid::Uuid::new_v4(),
                        reason: "max order qty exceeded".to_string(),
                        ts: Utc::now(),
                    });
                } else {
                    let order = signal_to_order(signal);
                    risk_bus.publish(RiskDecision::Approved(order));
                }
            }
            Err(RecvError::Lagged(_)) => continue,
            Err(_) => break,
        }
    }
}
```

