use std::collections::HashMap;

use bus::EventBus;
use common::{OrderRequest, OrderStatus, RiskDecision};
use tokio::sync::broadcast::error::RecvError;

pub async fn run_oms(
    risk_bus: EventBus<RiskDecision>,
    order_bus: EventBus<OrderRequest>,
) {
    let mut rx = risk_bus.subscribe();
    let mut live_orders: HashMap<common::OrderId, OrderStatus> = HashMap::new();

    loop {
        match rx.recv().await {
            Ok(decision) => match decision {
                RiskDecision::Approved(order) => {
                    live_orders.insert(order.order_id, OrderStatus::New);
                    order_bus.publish(order);
                }
                RiskDecision::Rejected { .. } => {}
            },
            Err(RecvError::Lagged(_)) => continue,
            Err(_) => break,
        }
    }
}
```

