use bus::EventBus;
use chrono::Utc;
use common::{ExecutionReport, OrderRequest, OrderStatus};
use tokio::sync::broadcast::error::RecvError;
use tokio::time::{sleep, Duration};

pub async fn run_execution(
    order_bus: EventBus<OrderRequest>,
    exec_bus: EventBus<ExecutionReport>,
) {
    let mut rx = order_bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(order) => {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Acked,
                    filled_qty: 0.into(),
                    avg_price: None,
                    reason: None,
                    ts: Utc::now(),
                };
                exec_bus.publish(ack);

                sleep(Duration::from_millis(2)).await;

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    avg_price: order.limit_price,
                    reason: None,
                    ts: Utc::now(),
                };
                exec_bus.publish(fill);
            }
            Err(RecvError::Lagged(_)) => continue,
            Err(_) => break,
        }
    }
}
```

