use std::collections::HashMap;

use bus::EventBus;
use common::{ExecutionReport, OrderStatus, Position};
use rust_decimal::Decimal;
use tokio::sync::broadcast::error::RecvError;

pub async fn run_positions(exec_bus: EventBus<ExecutionReport>) {
    let mut rx = exec_bus.subscribe();
    let mut positions: HashMap<String, Position> = HashMap::new();

    loop {
        match rx.recv().await {
            Ok(report) => {
                if let OrderStatus::Filled = report.status {
                    let pos = positions.entry("BTC-USD".to_string()).or_insert(Position {
                        instrument: "BTC-USD".to_string(),
                        ..Default::default()
                    });

                    pos.net_qty += report.filled_qty;
                    if let Some(px) = report.avg_price {
                        pos.avg_price = if pos.net_qty != Decimal::ZERO { px } else { Decimal::ZERO };
                    }
                }
            }
            Err(RecvError::Lagged(_)) => continue,
            Err(_) => break,
        }
    }
}
