```rust
// crates/strategy/src/simple.rs
use common::{now_ts, MarketTick, NewOrder, OrderType, Side};
use crate::Strategy;

pub struct SimpleStrategy {
    pub strategy_id: String,
    pub instrument: String,
    pub threshold: i64,
}

impl Strategy for SimpleStrategy {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<NewOrder> {
        if tick.instrument != self.instrument {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread >= self.threshold {
            Some(NewOrder {
                strategy_id: self.strategy_id.clone(),
                client_order_id: format!("{}-{}", self.strategy_id, tick.ts),
                instrument: tick.instrument.clone(),
                side: Side::Buy,
                qty: 1,
                order_type: OrderType::Limit,
                price: Some(tick.bid),
                ts: now_ts(),
            })
        } else {
            None
        }
    }
}
```

