## 7.4 Risk engine

```rust
// crates/risk/src/lib.rs
use common::{NewOrder, Qty};
use std::collections::HashMap;

pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_position_abs: Qty,
}

pub struct RiskEngine {
    pub limits: RiskLimits,
    pub positions: HashMap<String, Qty>,
}

impl RiskEngine {
    pub fn new(max_order_qty: Qty, max_position_abs: Qty) -> Self {
        Self {
            limits: RiskLimits {
                max_order_qty,
                max_position_abs,
            },
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), String> {
        if order.qty <= 0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err("order qty exceeds max_order_qty".into());
        }

        let pos = *self.positions.get(&order.instrument).unwrap_or(&0);
        let projected = match order.side {
            common::Side::Buy => pos + order.qty,
            common::Side::Sell => pos - order.qty,
        };

        if projected.abs() > self.limits.max_position_abs {
            return Err("projected position exceeds max_position_abs".into());
        }

        Ok(())
    }

    pub fn apply_fill(&mut self, instrument: &str, side: &common::Side, qty: Qty) {
        let pos = self.positions.entry(instrument.to_string()).or_insert(0);
        match side {
            common::Side::Buy => *pos += qty,
            common::Side::Sell => *pos -= qty,
        }
    }
}
```

