## 7.5 OMS

```rust
// crates/oms/src/lib.rs
use common::{ExecutionReport, NewOrder};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum OrderState {
    PendingNew,
    Acked,
    PartiallyFilled,
    Filled,
    Cancelled,
    Rejected,
}

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order: NewOrder,
    pub state: OrderState,
}

pub struct Oms {
    pub orders: HashMap<String, OrderRecord>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn register_new(&mut self, order: NewOrder) {
        self.orders.insert(
            order.client_order_id.clone(),
            OrderRecord {
                order,
                state: OrderState::PendingNew,
            },
        );
    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) {
        if let Some(record) = self.orders.get_mut(&report.client_order_id) {
            record.state = match report.exec_type {
                common::ExecType::Ack => OrderState::Acked,
                common::ExecType::PartialFill => OrderState::PartiallyFilled,
                common::ExecType::Fill => OrderState::Filled,
                common::ExecType::Cancelled => OrderState::Cancelled,
                common::ExecType::Rejected => OrderState::Rejected,
            };
        }
    }
}
```

