## 7.7 Main app wiring

```rust
// crates/app/src/main.rs
use common::bus::EventBus;
use common::{now_ts, MarketTick};
use execution::ExecutionGateway;
use oms::Oms;
use risk::RiskEngine;
use std::sync::Arc;
use strategy::simple::SimpleStrategy;
use strategy::Strategy;
use tokio::sync::Mutex;
use tokio::time::{sleep, Duration};

#[tokio::main]
async fn main() {
    let market_bus = EventBus::<MarketTick>::new(1024);

    let strategy = Arc::new(Mutex::new(SimpleStrategy {
        strategy_id: "strat-1".into(),
        instrument: "BTC-USD".into(),
        threshold: 10,
    }));

    let risk = Arc::new(Mutex::new(RiskEngine::new(100, 1000)));
    let oms = Arc::new(Mutex::new(Oms::new()));
    let exec = Arc::new(ExecutionGateway::new());

    // Strategy task
    {
        let mut rx = market_bus.subscribe();
        let strategy = Arc::clone(&strategy);
        let risk = Arc::clone(&risk);
        let oms = Arc::clone(&oms);
        let exec = Arc::clone(&exec);

        tokio::spawn(async move {
            loop {
                match rx.recv().await {
                    Ok(tick) => {
                        let maybe_order = {
                            let mut strat = strategy.lock().await;
                            strat.on_tick(&tick)
                        };

                        if let Some(order) = maybe_order {
                            let risk_ok = {
                                let risk_engine = risk.lock().await;
                                risk_engine.check_order(&order)
                            };

                            match risk_ok {
                                Ok(_) => {
                                    {
                                        let mut oms_guard = oms.lock().await;
                                        oms_guard.register_new(order.clone());
                                    }

                                    let report = exec.send_order(&order).await;

                                    {
                                        let mut oms_guard = oms.lock().await;
                                        oms_guard.on_execution_report(&report);
                                    }

                                    println!("order sent: {:?}", order.client_order_id);
                                    println!("exec report: {:?}", report.exec_type);
                                }
                                Err(reason) => {
                                    println!("risk rejected order {}: {}", order.client_order_id, reason);
                                }
                            }
                        }
                    }
                    Err(err) => {
                        println!("market bus error: {:?}", err);
                    }
                }
            }
        });
    }

    // Simulated market data publisher
    {
        let market_bus = market_bus.clone();
        tokio::spawn(async move {
            let mut px = 1000_i64;
            loop {
                let tick = MarketTick {
                    instrument: "BTC-USD".into(),
                    bid: px,
                    ask: px + 12,
                    last: px + 6,
                    bid_qty: 10,
                    ask_qty: 10,
                    ts: now_ts(),
                };
                market_bus.publish(tick);
                px += 1;
                sleep(Duration::from_millis(10)).await;
            }
        });
    }

    loop {
        sleep(Duration::from_secs(1)).await;
    }
}
```

