## `risk/src/lib.rs`

```rust
use common::types::*;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
    pub max_position_abs: f64,
    pub kill_switch: bool,
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check(&self, order: &OrderRequest, current_position: f64) -> RiskDecision {
        if self.limits.kill_switch {
            return RiskDecision {
                approved: false,
                reason: Some("kill switch enabled".to_string()),
                ts_checked: now_micros(),
            };
        }

        if order.qty <= 0.0 {
            return RiskDecision {
                approved: false,
                reason: Some("qty must be positive".to_string()),
                ts_checked: now_micros(),
            };
        }

        if order.qty > self.limits.max_order_qty {
            return RiskDecision {
                approved: false,
                reason: Some("order qty exceeds max".to_string()),
                ts_checked: now_micros(),
            };
        }

        let px = order.limit_px.unwrap_or(0.0);
        let notional = px * order.qty;
        if px > 0.0 && notional > self.limits.max_notional {
            return RiskDecision {
                approved: false,
                reason: Some("order notional exceeds max".to_string()),
                ts_checked: now_micros(),
            };
        }

        let projected_position = match order.side {
            Side::Buy => current_position + order.qty,
            Side::Sell => current_position - order.qty,
        };

        if projected_position.abs() > self.limits.max_position_abs {
            return RiskDecision {
                approved: false,
                reason: Some("projected position exceeds limit".to_string()),
                ts_checked: now_micros(),
            };
        }

        RiskDecision {
            approved: true,
            reason: None,
            ts_checked: now_micros(),
        }
    }
}
