use std::collections::HashMap;
use common::types::*;

pub struct Oms {
    orders: HashMap<OrderId, Order>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn accept_order(&mut self, req: OrderRequest) -> Order {
        let order = Order {
            client_order_id: req.client_order_id,
            venue_order_id: None,
            request: req,
            status: OrderStatus::New,
            filled_qty: 0.0,
            avg_fill_px: 0.0,
            ts_updated: now_micros(),
        };
        self.orders.insert(order.client_order_id, order.clone());
        order
    }

    pub fn mark_sent(&mut self, client_order_id: OrderId, venue_order_id: Option<String>) {
        if let Some(order) = self.orders.get_mut(&client_order_id) {
            order.status = OrderStatus::Sent;
            order.venue_order_id = venue_order_id;
            order.ts_updated = now_micros();
        }
    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) -> Option<Order> {
        let order = self.orders.get_mut(&report.client_order_id)?;
        order.status = report.status;

        if report.fill_qty > 0.0 {
            let prev_notional = order.avg_fill_px * order.filled_qty;
            let new_notional = prev_notional + report.fill_px.unwrap_or(0.0) * report.fill_qty;
            order.filled_qty += report.fill_qty;
            if order.filled_qty > 0.0 {
                order.avg_fill_px = new_notional / order.filled_qty;
            }
        }

        order.ts_updated = now_micros();
        Some(order.clone())
    }

    pub fn get(&self, client_order_id: OrderId) -> Option<&Order> {
        self.orders.get(&client_order_id)
    }
}
