use std::collections::HashMap;
use common::types::*;

pub struct PositionBook {
    positions: HashMap<Symbol, Position>,
}

impl PositionBook {
    pub fn new() -> Self {
        Self {
            positions: HashMap::new(),
        }
    }

    pub fn apply_fill(
        &mut self,
        symbol: &str,
        side: Side,
        fill_qty: f64,
        fill_px: f64,
    ) -> Position {
        let pos = self.positions.entry(symbol.to_string()).or_insert(Position {
            symbol: symbol.to_string(),
            ..Default::default()
        });

        match side {
            Side::Buy => {
                let new_qty = pos.net_qty + fill_qty;
                if new_qty.abs() > f64::EPSILON {
                    pos.avg_px = ((pos.net_qty * pos.avg_px) + (fill_qty * fill_px)) / new_qty;
                } else {
                    pos.avg_px = 0.0;
                }
                pos.net_qty = new_qty;
            }
            Side::Sell => {
                pos.net_qty -= fill_qty;
            }
        }

        pos.clone()
    }

    pub fn get_position_qty(&self, symbol: &str) -> f64 {
        self.positions.get(symbol).map(|p| p.net_qty).unwrap_or(0.0)
    }
}
