use common::types::*;

pub struct SimpleStrategy {
    pub strategy_id: StrategyId,
    pub threshold_bps: f64,
    next_order_id: u64,
}

impl SimpleStrategy {
    pub fn new(strategy_id: StrategyId, threshold_bps: f64) -> Self {
        Self {
            strategy_id,
            threshold_bps,
            next_order_id: 1,
        }
    }

    pub fn on_quote(&mut self, quote: &Quote) -> Option<OrderRequest> {
        let mid = (quote.bid_px + quote.ask_px) / 2.0;
        let spread_bps = ((quote.ask_px - quote.bid_px) / mid) * 10_000.0;

        if spread_bps < self.threshold_bps {
            let order = OrderRequest {
                strategy_id: self.strategy_id.clone(),
                instrument: quote.instrument.clone(),
                side: Side::Buy,
                order_type: OrderType::Limit,
                tif: TimeInForce::Ioc,
                qty: 1.0,
                limit_px: Some(quote.ask_px),
                client_order_id: self.next_order_id,
                ts_created: now_micros(),
            };
            self.next_order_id += 1;
            return Some(order);
        }

        None
    }
}
