use common::types::*;
use execution::{ExecutionVenue, MockExecutionVenue};
use oms::Oms;
use positions::PositionBook;
use risk::{RiskEngine, RiskLimits};
use strategy::SimpleStrategy;

fn main() {
    let instrument = Instrument {
        symbol: "AAPL".to_string(),
        venue: "XNAS".to_string(),
    };

    let mut strategy = SimpleStrategy::new("mean_revert_1".to_string(), 5.0);
    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_notional: 1_000_000.0,
        max_position_abs: 1_000.0,
        kill_switch: false,
    });
    let mut oms = Oms::new();
    let positions = PositionBook::new();
    let venue = MockExecutionVenue;

    let quote = Quote {
        instrument: instrument.clone(),
        bid_px: 100.00,
        bid_qty: 10.0,
        ask_px: 100.02,
        ask_qty: 12.0,
        ts_exchange: now_micros(),
        ts_received: now_micros(),
    };

    if let Some(order_req) = strategy.on_quote(&quote) {
        let current_pos = positions.get_position_qty(&order_req.instrument.symbol);
        let decision = risk.check(&order_req, current_pos);

        if decision.approved {
            let order = oms.accept_order(order_req.clone());
            match venue.send_order(&order) {
                Ok(venue_order_id) => {
                    println!("order sent: {:?}", order.client_order_id);
                    let mut oms = oms;
                    oms.mark_sent(order.client_order_id, venue_order_id);
                }
                Err(err) => {
                    println!("send failed: {}", err);
                }
            }
        } else {
            println!("risk rejected order: {:?}", decision.reason);
        }
    }
}
