    pub async fn run(&mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::MarketData(md) = event {
                self.on_market_data(md).await;
            }
        }
    }

    async fn on_market_data(&self, md: MarketData) {
        let spread = md.ask - md.bid;
        if md.symbol == "AAPL" && spread <= 0.02 && md.ask < 189.15 {
            let order = NewOrderRequest {
                client_order_id: Uuid::new_v4().to_string(),
                symbol: md.symbol,
                side: Side::Buy,
                qty: 100,
                price: Some(md.ask),
                order_type: OrderType::Limit,
                tif: TimeInForce::Day,
            };

            let _ = self.tx.send(Event::NewOrder(order)).await;
        }
    }
