// crates/risk/src/engine.rs
use common::events::Event;
use common::types::NewOrderRequest;
use tokio::sync::mpsc::{Receiver, Sender};

pub struct RiskEngine {
    rx: Receiver<Event>,
    tx: Sender<Event>,
    max_order_qty: u64,
}

impl RiskEngine {
    pub fn new(rx: Receiver<Event>, tx: Sender<Event>, max_order_qty: u64) -> Self {
        Self {
            rx,
            tx,
            max_order_qty,
        }
    }

    pub async fn run(&mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::NewOrder(order) = event {
                self.check(order).await;
            }
        }
    }

    async fn check(&self, order: NewOrderRequest) {
        if order.qty > self.max_order_qty {
            eprintln!("Risk reject: qty too large {:?}", order);
            return;
        }

        let _ = self.tx.send(Event::NewOrder(order)).await;
    }
}
