# 12. OMS

```rust
// crates/oms/src/order_manager.rs
use common::events::Event;
use common::types::{ExecutionReport, NewOrderRequest};
use std::collections::HashMap;
use tokio::sync::mpsc::{Receiver, Sender};
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct ManagedOrder {
    pub order_id: String,
    pub request: NewOrderRequest,
    pub status: String,
}

pub struct OrderManager {
    rx: Receiver<Event>,
    tx: Sender<Event>,
    orders: HashMap<String, ManagedOrder>,
}

impl OrderManager {
    pub fn new(rx: Receiver<Event>, tx: Sender<Event>) -> Self {
        Self {
            rx,
            tx,
            orders: HashMap::new(),
        }
    }

    pub async fn run(&mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                Event::NewOrder(order) => self.handle_new_order(order).await,
                Event::ExecutionReport(report) => self.handle_execution_report(report).await,
                _ => {}
            }
        }
    }

    async fn handle_new_order(&mut self, req: NewOrderRequest) {
        let order_id = Uuid::new_v4().to_string();
        let managed = ManagedOrder {
            order_id: order_id.clone(),
            request: req.clone(),
            status: "PENDING_NEW".to_string(),
        };

        self.orders.insert(order_id.clone(), managed);

        let report = ExecutionReport {
            order_id,
            client_order_id: req.client_order_id,
            status: "PENDING_NEW".to_string(),
            filled_qty: 0,
            remaining_qty: req.qty,
            avg_price: None,
            reason: None,
        };

        let _ = self.tx.send(Event::ExecutionReport(report)).await;
    }

    async fn handle_execution_report(&mut self, report: ExecutionReport) {
        if let Some(order) = self.orders.get_mut(&report.order_id) {
            order.status = report.status.clone();
        }
    }
}
