// crates/execution/src/simulator.rs
use common::events::Event;
use common::types::ExecutionReport;
use tokio::sync::mpsc::{Receiver, Sender};
use tokio::time::{sleep, Duration};

pub struct SimExecutionGateway {
    rx: Receiver<Event>,
    tx: Sender<Event>,
}

impl SimExecutionGateway {
    pub fn new(rx: Receiver<Event>, tx: Sender<Event>) -> Self {
        Self { rx, tx }
    }

    pub async fn run(&mut self) {
        while let Some(event) = self.rx.recv().await {
            if let Event::ExecutionReport(pending) = event {
                sleep(Duration::from_millis(5)).await;

                let ack = ExecutionReport {
                    status: "NEW".to_string(),
                    ..pending.clone()
                };
                let _ = self.tx.send(Event::ExecutionReport(ack)).await;

                sleep(Duration::from_millis(20)).await;

                let fill = ExecutionReport {
                    status: "FILLED".to_string(),
                    filled_qty: pending.remaining_qty,
                    remaining_qty: 0,
                    avg_price: Some(189.11),
                    ..pending
                };
                let _ = self.tx.send(Event::ExecutionReport(fill)).await;
            }
        }
    }
}
