        while let Some(event) = self.rx.recv().await {
            if let Event::Fill(fill) = event {
                let pos = self.positions.entry(fill.symbol.clone()).or_insert(0);
                match fill.side {
                    Side::Buy => *pos += fill.qty as i64,
                    Side::Sell => *pos -= fill.qty as i64,
                }
            }
        }
    }
}
