# 6. Event bus

This is a simple in-process event bus using Tokio channels.  
For low latency, in-process bounded channels are a good MVP.

## `src/bus.rs`

```rust
use crate::types::{MarketTick, OrderAck, OrderRequest};
use tokio::sync::mpsc;

#[derive(Clone)]
pub struct Bus {
    pub market_tx: mpsc::Sender<MarketTick>,
    pub order_tx: mpsc::Sender<OrderRequest>,
    pub ack_tx: mpsc::Sender<OrderAck>,
}

pub struct BusReceivers {
    pub market_rx: mpsc::Receiver<MarketTick>,
    pub order_rx: mpsc::Receiver<OrderRequest>,
    pub ack_rx: mpsc::Receiver<OrderAck>,
}

pub fn create_bus(buffer: usize) -> (Bus, BusReceivers) {
    let (market_tx, market_rx) = mpsc::channel(buffer);
    let (order_tx, order_rx) = mpsc::channel(buffer);
    let (ack_tx, ack_rx) = mpsc::channel(buffer);

    (
        Bus {
            market_tx,
            order_tx,
            ack_tx,
        },
        BusReceivers {
            market_rx,
            order_rx,
            ack_rx,
        },
    )
}
```

