# 8. Strategy engine

This strategy is intentionally simple:  
if spread and price conditions match, place a small order.

## `src/strategy.rs`

```rust
use crate::types::{MarketTick, OrderRequest, Side};
use std::time::Instant;
use tokio::sync::mpsc::{Receiver, Sender};

pub async fn run_strategy(
    mut market_rx: Receiver<MarketTick>,
    order_tx: Sender<OrderRequest>,
) {
    while let Some(tick) = market_rx.recv().await {
        let mid = (tick.bid + tick.ask) / 2.0;

        if mid < 99.8 {
            let order = OrderRequest {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 10,
                price: tick.ask,
                ts: Instant::now(),
            };

            if order_tx.send(order).await.is_err() {
                break;
            }
        } else if mid > 100.2 {
            let order = OrderRequest {
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: 10,
                price: tick.bid,
                ts: Instant::now(),
            };

            if order_tx.send(order).await.is_err() {
                break;
            }
        }
    }
}
