# 9. Risk manager

A minimal risk layer is mandatory.  
This version enforces:

- max order quantity
- max absolute position

## `src/risk.rs`

```rust
use crate::types::{OrderRequest, Position, Side};
use std::collections::HashMap;

pub struct RiskManager {
    max_order_qty: u64,
    max_abs_position: i64,
    positions: HashMap<String, Position>,
}

impl RiskManager {
    pub fn new(max_order_qty: u64, max_abs_position: i64) -> Self {
        Self {
            max_order_qty,
            max_abs_position,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty > self.max_order_qty {
            return Err(format!("order qty {} exceeds max {}", order.qty, self.max_order_qty));
        }

        let current = self.positions.get(&order.symbol).map(|p| p.qty).unwrap_or(0);
        let delta = match order.side {
            Side::Buy => order.qty as i64,
            Side::Sell => -(order.qty as i64),
        };

        let projected = current + delta;
        if projected.abs() > self.max_abs_position {
            return Err(format!(
                "projected position {} exceeds max abs position {}",
                projected, self.max_abs_position
            ));
        }

        Ok(())
    }

    pub fn apply_fill(&mut self, order: &OrderRequest) {
        let pos = self.positions.entry(order.symbol.clone()).or_insert(Position {
            symbol: order.symbol.clone(),
            qty: 0,
        });

        match order.side {
            Side::Buy => pos.qty += order.qty as i64,
            Side::Sell => pos.qty -= order.qty as i64,
        }
    }
}
```

