use crate::types::{OrderAck, OrderRequest};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;
use tokio::sync::mpsc::{Receiver, Sender};

static ORDER_ID: AtomicU64 = AtomicU64::new(1);

pub async fn run_exchange_adapter(
    mut order_rx: Receiver<OrderRequest>,
    ack_tx: Sender<OrderAck>,
) {
    while let Some(order) = order_rx.recv().await {
        let order_id = ORDER_ID.fetch_add(1, Ordering::Relaxed);

        println!(
            "[EXCHANGE] order_id={} symbol={} side={:?} qty={} price={}",
            order_id, order.symbol, order.side, order.qty, order.price
        );

        let ack = OrderAck {
            order_id,
            accepted: true,
            reason: None,
            ts: Instant::now(),
        };

        if ack_tx.send(ack).await.is_err() {
            break;
        }
    }
}
