# 11. Order manager

The order manager sits between strategy and exchange.  
It applies risk checks and forwards approved orders.

## `src/order_manager.rs`

```rust
use crate::risk::RiskManager;
use crate::types::{OrderAck, OrderRequest};
use std::time::Instant;
use tokio::sync::mpsc::{Receiver, Sender};

pub async fn run_order_manager(
    mut strategy_order_rx: Receiver<OrderRequest>,
    exchange_order_tx: Sender<OrderRequest>,
    ack_tx: Sender<OrderAck>,
) {
    let mut risk = RiskManager::new(100, 1000);

    while let Some(order) = strategy_order_rx.recv().await {
        match risk.check_order(&order) {
            Ok(_) => {
                risk.apply_fill(&order);

                if exchange_order_tx.send(order).await.is_err() {
                    break;
                }
            }
            Err(reason) => {
                let ack = OrderAck {
                    order_id: 0,
                    accepted: false,
                    reason: Some(reason),
                    ts: Instant::now(),
                };

                if ack_tx.send(ack).await.is_err() {
                    break;
                }
            }
        }
    }
}
```

