    let (exchange_order_tx, exchange_order_rx) = mpsc::channel(1024);
    let (ack_tx, mut ack_rx) = mpsc::channel(1024);

    let md_task = tokio::spawn(market_data::run_market_data(
        "FOO".to_string(),
        market_tx,
    ));

    let strategy_task = tokio::spawn(strategy::run_strategy(
        market_rx,
        strategy_order_tx,
    ));

    let om_task = tokio::spawn(order_manager::run_order_manager(
        strategy_order_rx,
        exchange_order_tx,
        ack_tx.clone(),
    ));

    let ex_task = tokio::spawn(exchange::run_exchange_adapter(
        exchange_order_rx,
        ack_tx,
    ));

    let ack_task = tokio::spawn(async move {
        while let Some(ack) = ack_rx.recv().await {
            println!(
                "[ACK] order_id={} accepted={} reason={:?}",
                ack.order_id, ack.accepted, ack.reason
            );
        }
    });

    let _ = tokio::join!(md_task, strategy_task, om_task, ex_task, ack_task);
}
