# Main implementation

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const ROUTE_QUEUE_SIZE: usize = 100_000;
const NUM_PRODUCERS: usize = 4;
const NUM_ROUTER_SHARDS: usize = 8;
const NUM_TOPICS: usize = 128;
const MESSAGES_PER_PRODUCER: usize = 2_000_000;

#[derive(Clone)]
struct Message {
    id: u64,
    topic: u32,
    payload: Arc<Vec<u8>>,
    created_at: Instant,
}

struct RouteMetrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl RouteMetrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_received(&self) {
        self.received.fetch_add(1, Ordering::Relaxed);
    }

    fn record_routed(&self, latency_ns: u64) {
        self.routed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn record_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

struct Route {
    sender: Sender<Message>,
    metrics: Arc<RouteMetrics>,
}

struct Router {
    routes: Arc<DashMap<u32, Arc<Route>>>,
    ingress_tx: Sender<Message>,
    ingress_rx: Receiver<Message>,
    running: Arc<AtomicBool>,
    global_received: Arc<AtomicU64>,
    global_routed: Arc<AtomicU64>,
    global_dropped: Arc<AtomicU64>,
}

impl Router {
    fn new() -> Self {
        let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);
        Self {
            routes: Arc::new(DashMap::new()),
            ingress_tx,
            ingress_rx,
            running: Arc::new(AtomicBool::new(true)),
            global_received: Arc::new(AtomicU64::new(0)),
            global_routed: Arc::new(AtomicU64::new(0)),
            global_dropped: Arc::new(AtomicU64::new(0)),
        }
    }

    fn register_route(&self, topic: u32) -> Receiver<Message> {
        let (tx, rx) = bounded::<Message>(ROUTE_QUEUE_SIZE);
        let route = Arc::new(Route {
            sender: tx,
            metrics: Arc::new(RouteMetrics::new()),
        });
        self.routes.insert(topic, route);
        rx
    }

    fn ingress_sender(&self) -> Sender<Message> {
        self.ingress_tx.clone()
    }

    fn start_router_shards(&self, num_shards: usize) -> Vec<thread::JoinHandle<()>> {
        let mut handles = Vec::with_capacity(num_shards);

        for shard_id in 0..num_shards {
            let ingress_rx = self.ingress_rx.clone();
            let routes = self.routes.clone();
            let running = self.running.clone();
            let global_received = self.global_received.clone();
            let global_routed = self.global_routed.clone();
            let global_dropped = self.global_dropped.clone();

            let handle = thread::spawn(move || {
                while running.load(Ordering::Relaxed) {
                    match ingress_rx.recv() {
                        Ok(msg) => {
                            global_received.fetch_add(1, Ordering::Relaxed);

                            if let Some(route_ref) = routes.get(&msg.topic) {
                                let route = route_ref.value().clone();
                                route.metrics.record_received();

                                let latency_ns = msg.created_at.elapsed().as_nanos() as u64;

                                match route.sender.try_send(msg) {
                                    Ok(_) => {
                                        route.metrics.record_routed(latency_ns);
                                        global_routed.fetch_add(1, Ordering::Relaxed);
                                    }
                                    Err(_) => {
                                        route.metrics.record_dropped();
                                        global_dropped.fetch_add(1, Ordering::Relaxed);
                                    }
                                }
                            } else {
                                global_dropped.fetch_add(1, Ordering::Relaxed);
                            }
                        }
                        Err(_) => break,
                    }
                }

                println!("Router shard {} stopped", shard_id);
            });

            handles.push(handle);
        }

        handles
    }

    fn start_metrics_reporter(&self) -> thread::JoinHandle<()> {
        let routes = self.routes.clone();
        let running = self.running.clone();
        let global_received = self.global_received.clone();
        let global_routed = self.global_routed.clone();
        let global_dropped = self.global_dropped.clone();

        thread::spawn(move || {
            let mut last_received = 0;
            let mut last_routed = 0;
            let mut last_dropped = 0;

            while running.load(Ordering::Relaxed) {
                thread::sleep(Duration::from_secs(1));

                let received = global_received.load(Ordering::Relaxed);
                let routed = global_routed.load(Ordering::Relaxed);
                let dropped = global_dropped.load(Ordering::Relaxed);

                let received_delta = received - last_received;
                let routed_delta = routed - last_routed;
                let dropped_delta = dropped - last_dropped;

                last_received = received;
                last_routed = routed;
                last_dropped = dropped;

                println!(
                    "[GLOBAL] recv/s={} routed/s={} dropped/s={} total_recv={} total_routed={} total_dropped={}",
                    received_delta, routed_delta, dropped_delta, received, routed, dropped
                );

                for entry in routes.iter() {
                    let topic = *entry.key();
                    let route = entry.value();
                    let metrics = &route.metrics;

                    let rec = metrics.received.load(Ordering::Relaxed);
                    let rout = metrics.routed.load(Ordering::Relaxed);
                    let drop = metrics.dropped.load(Ordering::Relaxed);
                    let total_lat = metrics.total_latency_ns.load(Ordering::Relaxed);
                    let max_lat = metrics.max_latency_ns.load(Ordering::Relaxed);

                    let avg_lat = if rout > 0 {
                        total_lat / rout
                    } else {
                        0
                    };

                    println!(
                        "  [TOPIC {}] received={} routed={} dropped={} avg_latency_ns={} max_latency_ns={}",
                        topic, rec, rout, drop, avg_lat, max_lat
                    );
                }
            }
        })
    }

    fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn start_consumer(topic: u32, rx: Receiver<Message>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut processed: u64 = 0;
        while let Ok(_msg) = rx.recv() {
            processed += 1;

            // Simulate lightweight processing
            if processed % 1_000_000 == 0 {
                println!("Consumer topic {} processed {}", topic, processed);
            }
        }
    })
}

fn start_producer(
    producer_id: usize,
    tx: Sender<Message>,
    topic_count: usize,
    messages: usize,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut rng = rand::thread_rng();

        for i in 0..messages {
            let topic = rng.gen_range(0..topic_count) as u32;
            let msg = Message {
                id: ((producer_id as u64) << 32) | i as u64,
                topic,
                payload: Arc::new(vec![0u8; 128]),
                created_at: Instant::now(),
            };

            if tx.send(msg).is_err() {
                break;
            }
        }

        println!("Producer {} finished", producer_id);
    })
}

fn main() {
    let router = Router::new();

    let mut consumer_handles = Vec::new();
    for topic in 0..NUM_TOPICS as u32 {
        let rx = router.register_route(topic);
        consumer_handles.push(start_consumer(topic, rx));
    }

    let router_handles = router.start_router_shards(NUM_ROUTER_SHARDS);
    let metrics_handle = router.start_metrics_reporter();

    let ingress_tx = router.ingress_sender();
    let mut producer_handles = Vec::new();

    for producer_id in 0..NUM_PRODUCERS {
        producer_handles.push(start_producer(
            producer_id,
            ingress_tx.clone(),
            NUM_TOPICS,
            MESSAGES_PER_PRODUCER,
        ));
    }

    for handle in producer_handles {
        handle.join().unwrap();
    }

    drop(ingress_tx);

    thread::sleep(Duration::from_secs(5));
    router.stop();

    for handle in router_handles {
        let _ = handle.join();
    }

    let _ = metrics_handle.join();

    drop(router);

    for handle in consumer_handles {
        let _ = handle.join();
    }
}
```

