## `main.rs`

```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 8;
const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const EGRESS_QUEUE_SIZE: usize = 1_000_000;
const NUM_CONSUMERS_PER_ROUTE: usize = 2;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: u64,
    payload: [u8; 64],
    ingress_ts: Instant,
}

#[derive(Default)]
struct RouteStats {
    count: AtomicU64,
}

struct Metrics {
    total_ingress: AtomicU64,
    total_routed: AtomicU64,
    total_dropped: AtomicU64,
    route_latency_ns: Mutex<Histogram<u64>>,
    end_to_end_latency_ns: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            total_ingress: AtomicU64::new(0),
            total_routed: AtomicU64::new(0),
            total_dropped: AtomicU64::new(0),
            route_latency_ns: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
            end_to_end_latency_ns: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
        }
    }

    fn record_route_latency(&self, d: Duration) {
        let ns = d.as_nanos() as u64;
        let mut h = self.route_latency_ns.lock();
        let _ = h.record(ns);
    }

    fn record_end_to_end_latency(&self, d: Duration) {
        let ns = d.as_nanos() as u64;
        let mut h = self.end_to_end_latency_ns.lock();
        let _ = h.record(ns);
    }

    fn snapshot_and_print(&self, interval_secs: u64) {
        let ingress = self.total_ingress.swap(0, Ordering::Relaxed);
        let routed = self.total_routed.swap(0, Ordering::Relaxed);
        let dropped = self.total_dropped.swap(0, Ordering::Relaxed);

        let route_hist = {
            let mut h = self.route_latency_ns.lock();
            let copy = h.clone();
            h.reset();
            copy
        };

        let e2e_hist = {
            let mut h = self.end_to_end_latency_ns.lock();
            let copy = h.clone();
            h.reset();
            copy
        };

        println!(
            "[metrics] ingress/s={} routed/s={} dropped/s={} \
route_p50={}us route_p95={}us route_p99={}us \
e2e_p50={}us e2e_p95={}us e2e_p99={}us",
            ingress / interval_secs,
            routed / interval_secs,
            dropped / interval_secs,
            route_hist.value_at_quantile(0.50) / 1_000,
            route_hist.value_at_quantile(0.95) / 1_000,
            route_hist.value_at_quantile(0.99) / 1_000,
            e2e_hist.value_at_quantile(0.50) / 1_000,
            e2e_hist.value_at_quantile(0.95) / 1_000,
            e2e_hist.value_at_quantile(0.99) / 1_000,
        );
    }
}

struct Router {
    routes: DashMap<u64, Vec<Sender<Message>>>,
    route_stats: DashMap<u64, RouteStats>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(metrics: Arc<Metrics>) -> Self {
        Self {
            routes: DashMap::new(),
            route_stats: DashMap::new(),
            metrics,
        }
    }

    fn add_route(&self, topic: u64, consumers: Vec<Sender<Message>>) {
        self.routes.insert(topic, consumers);
        self.route_stats.insert(topic, RouteStats::default());
    }

    fn route(&self, msg: Message) {
        let route_start = Instant::now();

        if let Some(consumers) = self.routes.get(&msg.topic) {
            let consumer_list = consumers.value();

            // Simple fan-out to all consumers for the topic.
            for tx in consumer_list.iter() {
                if tx.try_send(msg.clone()).is_err() {
                    self.metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
                }
            }

            if let Some(stat) = self.route_stats.get(&msg.topic) {
                stat.count.fetch_add(1, Ordering::Relaxed);
            }

            self.metrics.total_routed.fetch_add(1, Ordering::Relaxed);
        } else {
            self.metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
        }

        self.metrics.record_route_latency(route_start.elapsed());
    }
}

fn shard_for(topic: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % NUM_SHARDS
}

fn start_router_workers(
    shard_rxs: Vec<Receiver<Message>>,
    router: Arc<Router>,
    running: Arc<AtomicBool>,
) -> Vec<thread::JoinHandle<()>> {
    shard_rxs
        .into_iter()
        .enumerate()
        .map(|(shard_id, rx)| {
            let router = router.clone();
            let running = running.clone();

            thread::Builder::new()
                .name(format!("router-shard-{}", shard_id))
                .spawn(move || {
                    while running.load(Ordering::Relaxed) {
                        match rx.recv_timeout(Duration::from_millis(100)) {
                            Ok(msg) => {
                                router.route(msg);
                            }
                            Err(_) => {}
                        }
                    }
                })
                .unwrap()
        })
        .collect()
}

fn start_consumers(
    topic: u64,
    metrics: Arc<Metrics>,
) -> Vec<(Sender<Message>, thread::JoinHandle<()>)> {
    let mut out = Vec::new();

    for i in 0..NUM_CONSUMERS_PER_ROUTE {
        let (tx, rx) = bounded::<Message>(EGRESS_QUEUE_SIZE);
        let metrics = metrics.clone();

        let handle = thread::Builder::new()
            .name(format!("consumer-topic-{}-{}", topic, i))
            .spawn(move || {
                while let Ok(msg) = rx.recv() {
                    // Simulate consumer processing
                    let e2e = msg.ingress_ts.elapsed();
                    metrics.record_end_to_end_latency(e2e);
                }
            })
            .unwrap();

        out.push((tx, handle));
    }

    out
}

fn start_metrics_reporter(
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let interval = 1;
        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(interval));
            metrics.snapshot_and_print(interval);
        }
    })
}

fn start_producer(
    shard_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut rng = rand::thread_rng();
        let mut id = 0u64;

        while running.load(Ordering::Relaxed) {
            let topic = rng.gen_range(0..16u64);
            let msg = Message {
                id,
                topic,
                payload: [42u8; 64],
                ingress_ts: Instant::now(),
            };
            id += 1;

            let shard = shard_for(topic);
            metrics.total_ingress.fetch_add(1, Ordering::Relaxed);

            if shard_txs[shard].try_send(msg).is_err() {
                metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let router = Arc::new(Router::new(metrics.clone()));
    let running = Arc::new(AtomicBool::new(true));

    // Create shard ingress queues
    let mut shard_txs = Vec::new();
    let mut shard_rxs = Vec::new();
    for _ in 0..NUM_SHARDS {
        let (tx, rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);
        shard_txs.push(tx);
        shard_rxs.push(rx);
    }

    // Register routes
    let mut consumer_handles = Vec::new();
    for topic in 0..16u64 {
        let consumers = start_consumers(topic, metrics.clone());
        let txs = consumers.iter().map(|(tx, _)| tx.clone()).collect::<Vec<_>>();
        for (_, handle) in consumers {
            consumer_handles.push(handle);
        }
        router.add_route(topic, txs);
    }

    let router_handles = start_router_workers(shard_rxs, router.clone(), running.clone());
    let metrics_handle = start_metrics_reporter(metrics.clone(), running.clone());
    let producer_handle = start_producer(shard_txs, metrics.clone(), running.clone());

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    let _ = producer_handle.join();
    let _ = metrics_handle.join();
    for h in router_handles {
        let _ = h.join();
    }

    // Consumers are blocked on recv(); in a real system you'd use shutdown channels.
    for h in consumer_handles {
        let _ = h.thread().id();
    }

    println!("shutdown complete");
}
```

