use anyhow::Result;
use bytes::Bytes;
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

use crossbeam::channel::{bounded, Receiver, Sender};

const ROUTER_WORKERS: usize = 8;
const SUBSCRIBER_QUEUE_SIZE: usize = 65536;
const ROUTER_QUEUE_SIZE: usize = 262144;
const METRICS_REPORT_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Clone)]
struct Message {
    topic: Arc<str>,
    payload: Bytes,
    created_at: Instant,
    id: u64,
}

struct Subscriber {
    name: Arc<str>,
    tx: Sender<Message>,
}

struct Metrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    received: AtomicU64,
    end_to_end_ns_total: AtomicU64,
    end_to_end_count: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            received: AtomicU64::new(0),
            end_to_end_ns_total: AtomicU64::new(0),
            end_to_end_count: AtomicU64::new(0),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3)
                    .expect("failed to create histogram"),
            ),
        }
    }

    fn record_delivery_latency(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.received.fetch_add(1, Ordering::Relaxed);
        self.end_to_end_ns_total.fetch_add(ns, Ordering::Relaxed);
        self.end_to_end_count.fetch_add(1, Ordering::Relaxed);

        let mut hist = self.latency_hist.lock();
        let _ = hist.record(ns);
    }

    fn snapshot_and_reset_histogram(&self) -> Histogram<u64> {
        let mut hist = self.latency_hist.lock();
        let snapshot = hist.clone();
        hist.reset();
        snapshot
    }
}

struct Router {
    worker_txs: Vec<Sender<Message>>,
    subscriptions: Arc<DashMap<Arc<str>, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
}

impl Router {
    fn new(worker_count: usize) -> Self {
        let subscriptions = Arc::new(DashMap::<Arc<str>, Vec<Subscriber>>::new());
        let metrics = Arc::new(Metrics::new());
        let running = Arc::new(AtomicBool::new(true));

        let mut worker_txs = Vec::with_capacity(worker_count);

        for worker_id in 0..worker_count {
            let (tx, rx) = bounded::<Message>(ROUTER_QUEUE_SIZE);
            worker_txs.push(tx);

            let subscriptions_clone = Arc::clone(&subscriptions);
            let metrics_clone = Arc::clone(&metrics);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name(format!("router-worker-{worker_id}"))
                .spawn(move || {
                    router_worker_loop(rx, subscriptions_clone, metrics_clone, running_clone);
                })
                .expect("failed to spawn router worker");
        }

        Self {
            worker_txs,
            subscriptions,
            metrics,
            running,
        }
    }

    fn subscribe(&self, topic: &str, subscriber_name: &str) -> Receiver<Message> {
        let (tx, rx) = bounded::<Message>(SUBSCRIBER_QUEUE_SIZE);
        let subscriber = Subscriber {
            name: Arc::from(subscriber_name),
            tx,
        };

        self.subscriptions
            .entry(Arc::from(topic))
            .and_modify(|subs| subs.push(Subscriber {
                name: subscriber.name.clone(),
                tx: subscriber.tx.clone(),
            }))
            .or_insert_with(|| vec![subscriber]);

        rx
    }

    fn publish(&self, msg: Message) -> Result<()> {
        let idx = shard_for_topic(&msg.topic, self.worker_txs.len());
        self.metrics.routed.fetch_add(1, Ordering::Relaxed);

        match self.worker_txs[idx].try_send(msg) {
            Ok(_) => Ok(()),
            Err(_) => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                anyhow::bail!("router queue full")
            }
        }
    }

    fn metrics(&self) -> Arc<Metrics> {
        Arc::clone(&self.metrics)
    }

    fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn shard_for_topic(topic: &str, shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % shards
}

fn router_worker_loop(
    rx: Receiver<Message>,
    subscriptions: Arc<DashMap<Arc<str>, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                if let Some(subs) = subscriptions.get(&msg.topic) {
                    for sub in subs.iter() {
                        if sub.tx.try_send(msg.clone()).is_err() {
                            metrics.dropped.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                }
            }
            Err(crossbeam::channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam::channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn start_subscriber(name: String, rx: Receiver<Message>, metrics: Arc<Metrics>) {
    thread::Builder::new()
        .name(format!("subscriber-{name}"))
        .spawn(move || {
            while let Ok(msg) = rx.recv() {
                let latency = msg.created_at.elapsed();
                metrics.record_delivery_latency(latency);

                // Simulate lightweight processing
                std::hint::black_box(msg.id);
                std::hint::black_box(msg.payload.len());
            }
        })
        .expect("failed to spawn subscriber");
}

fn start_metrics_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    thread::spawn(move || {
        let mut last_routed = 0;
        let mut last_received = 0;
        let mut last_dropped = 0;

        while running.load(Ordering::Relaxed) {
            thread::sleep(METRICS_REPORT_INTERVAL);

            let routed = metrics.routed.load(Ordering::Relaxed);
            let received = metrics.received.load(Ordering::Relaxed);
            let dropped = metrics.dropped.load(Ordering::Relaxed);

            let routed_delta = routed - last_routed;
            let received_delta = received - last_received;
            let dropped_delta = dropped - last_dropped;

            last_routed = routed;
            last_received = received;
            last_dropped = dropped;

            let count = metrics.end_to_end_count.load(Ordering::Relaxed);
            let total_ns = metrics.end_to_end_ns_total.load(Ordering::Relaxed);
            let avg_ns = if count > 0 { total_ns / count } else { 0 };

            let hist = metrics.snapshot_and_reset_histogram();

            let p50 = if hist.len() > 0 { hist.value_at_quantile(0.50) } else { 0 };
            let p95 = if hist.len() > 0 { hist.value_at_quantile(0.95) } else { 0 };
            let p99 = if hist.len() > 0 { hist.value_at_quantile(0.99) } else { 0 };
            let max = if hist.len() > 0 { hist.max() } else { 0 };

            println!(
                "throughput routed/s={} received/s={} dropped/s={} avg_latency_us={} p50_us={} p95_us={} p99_us={} max_us={}",
                routed_delta,
                received_delta,
                dropped_delta,
                avg_ns / 1_000,
                p50 / 1_000,
                p95 / 1_000,
                p99 / 1_000,
                max / 1_000
            );
        }
    });
}

fn main() -> Result<()> {
    let router = Arc::new(Router::new(ROUTER_WORKERS));

    let topics = vec!["orders", "trades", "quotes", "risk"];

    for i in 0..8 {
        let topic = topics[i % topics.len()];
        let rx = router.subscribe(topic, &format!("sub-{i}"));
        start_subscriber(format!("sub-{i}"), rx, router.metrics());
    }

    start_metrics_reporter(router.metrics(), Arc::clone(&router.running));

    let producer_threads = 8;
    let test_duration = Duration::from_secs(10);

    let mut handles = Vec::new();

    for producer_id in 0..producer_threads {
        let router_clone = Arc::clone(&router);
        let topics_clone = topics.clone();

        let handle = thread::spawn(move || {
            let start = Instant::now();
            let mut rng = rand::thread_rng();
            let mut seq: u64 = producer_id as u64 * 1_000_000_000;

            while start.elapsed() < test_duration {
                let topic = topics_clone[rng.gen_range(0..topics_clone.len())];
                let payload = Bytes::from_static(b"abcdefghijklmnopqrstuvwxyz012345");

                let msg = Message {
                    topic: Arc::from(topic),
                    payload,
                    created_at: Instant::now(),
                    id: seq,
                };

                let _ = router_clone.publish(msg);
                seq += 1;
            }
        });

        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    thread::sleep(Duration::from_secs(2));
    router.shutdown();

    Ok(())
}
```

