# `src/main.rs`

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug)]
struct Message {
    topic: u64,
    payload: Vec<u8>,
    created_ns: u64,
}

impl Message {
    fn new(topic: u64, payload: Vec<u8>) -> Self {
        Self {
            topic,
            payload,
            created_ns: now_ns(),
        }
    }
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

struct Subscriber {
    id: u64,
    tx: Sender<Message>,
}

struct Metrics {
    published: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    consumed: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            published: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            consumed: AtomicU64::new(0),
            latency_hist: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        if let Ok(mut h) = self.latency_hist.lock() {
            let _ = h.record(latency_ns);
        }
    }
}

struct Router {
    topics: DashMap<u64, Vec<Subscriber>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(metrics: Arc<Metrics>) -> Self {
        Self {
            topics: DashMap::new(),
            metrics,
        }
    }

    fn subscribe(&self, topic: u64, subscriber_id: u64, queue_size: usize) -> Receiver<Message> {
        let (tx, rx) = bounded(queue_size);
        let sub = Subscriber {
            id: subscriber_id,
            tx,
        };

        self.topics
            .entry(topic)
            .and_modify(|subs| subs.push(Subscriber {
                id: sub.id,
                tx: sub.tx.clone(),
            }))
            .or_insert_with(|| vec![sub]);

        rx
    }

    fn publish(&self, msg: Message) {
        self.metrics.published.fetch_add(1, Ordering::Relaxed);

        if let Some(subscribers) = self.topics.get(&msg.topic) {
            for sub in subscribers.iter() {
                match sub.tx.try_send(msg.clone()) {
                    Ok(_) => {
                        self.metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(_) => {
                        self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
        } else {
            self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn start_consumer(
    subscriber_id: u64,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) {
            match rx.recv_timeout(Duration::from_millis(100)) {
                Ok(msg) => {
                    let latency = now_ns().saturating_sub(msg.created_ns);
                    metrics.record_latency(latency);
                    metrics.consumed.fetch_add(1, Ordering::Relaxed);

                    // Simulate lightweight processing
                    std::hint::black_box((subscriber_id, msg.payload.len()));
                }
                Err(_) => {}
            }
        }
    })
}

fn start_monitor(metrics: Arc<Metrics>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_published = 0;
        let mut last_routed = 0;
        let mut last_consumed = 0;
        let mut last_dropped = 0;

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let published = metrics.published.load(Ordering::Relaxed);
            let routed = metrics.routed.load(Ordering::Relaxed);
            let consumed = metrics.consumed.load(Ordering::Relaxed);
            let dropped = metrics.dropped.load(Ordering::Relaxed);

            let pub_rate = published - last_published;
            let route_rate = routed - last_routed;
            let cons_rate = consumed - last_consumed;
            let drop_rate = dropped - last_dropped;

            last_published = published;
            last_routed = routed;
            last_consumed = consumed;
            last_dropped = dropped;

            let (p50, p99, p999, max) = if let Ok(h) = metrics.latency_hist.lock() {
                if h.len() > 0 {
                    (
                        h.value_at_quantile(0.50),
                        h.value_at_quantile(0.99),
                        h.value_at_quantile(0.999),
                        h.max(),
                    )
                } else {
                    (0, 0, 0, 0)
                }
            } else {
                (0, 0, 0, 0)
            };

            println!(
                "pub/s={} routed/s={} consumed/s={} dropped/s={} latency(ns): p50={} p99={} p999={} max={}",
                pub_rate, route_rate, cons_rate, drop_rate, p50, p99, p999, max
            );
        }
    })
}

fn start_producer(
    router: Arc<Router>,
    running: Arc<AtomicBool>,
    producer_id: u64,
    topic_count: u64,
    payload_size: usize,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let payload = vec![0u8; payload_size];
        let mut counter = producer_id * 1_000_000_000;

        while running.load(Ordering::Relaxed) {
            let topic = counter % topic_count;
            let msg = Message::new(topic, payload.clone());
            router.publish(msg);
            counter += 1;
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let router = Arc::new(Router::new(metrics.clone()));
    let running = Arc::new(AtomicBool::new(true));

    let topic_count = 8;
    let subscribers_per_topic = 2;
    let producer_count = 4;
    let payload_size = 128;
    let queue_size = 65_536;

    let mut consumer_handles = Vec::new();

    for topic in 0..topic_count {
        for sub_id in 0..subscribers_per_topic {
            let rx = router.subscribe(topic, topic * 1000 + sub_id, queue_size);
            let handle = start_consumer(
                topic * 1000 + sub_id,
                rx,
                metrics.clone(),
                running.clone(),
            );
            consumer_handles.push(handle);
        }
    }

    let monitor_handle = start_monitor(metrics.clone(), running.clone());

    let mut producer_handles = Vec::new();
    for producer_id in 0..producer_count {
        producer_handles.push(start_producer(
            router.clone(),
            running.clone(),
            producer_id,
            topic_count,
            payload_size,
        ));
    }

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for h in producer_handles {
        let _ = h.join();
    }

    for h in consumer_handles {
        let _ = h.join();
    }

    let _ = monitor_handle.join();

    println!("Final stats:");
    println!(
        "published={} routed={} consumed={} dropped={}",
        metrics.published.load(Ordering::Relaxed),
        metrics.routed.load(Ordering::Relaxed),
        metrics.consumed.load(Ordering::Relaxed),
        metrics.dropped.load(Ordering::Relaxed),
    );

    if let Ok(h) = metrics.latency_hist.lock() {
        if h.len() > 0 {
            println!(
                "Latency summary (ns): p50={} p95={} p99={} p999={} max={}",
                h.value_at_quantile(0.50),
                h.value_at_quantile(0.95),
                h.value_at_quantile(0.99),
                h.value_at_quantile(0.999),
                h.max()
            );
        }
    }
}
```

