```rust
use bytes::Bytes;
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_WORKERS: usize = 8;
const CHANNEL_CAPACITY: usize = 262_144;
const BATCH_SIZE: usize = 1024;
const MESSAGE_SIZE: usize = 128;
const RUN_SECONDS: u64 = 10;

#[derive(Clone)]
struct Message {
    route_key: u64,
    created_at: Instant,
    payload: Bytes,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000, 3).unwrap()
            ),
        }
    }

    fn record_latency(&self, micros: u64) {
        if let Ok(mut hist) = self.latency_hist.lock() {
            let _ = hist.record(micros);
        }
    }
}

fn route_message(msg: &Message, num_workers: usize) -> usize {
    (msg.route_key as usize) % num_workers
}

fn producer_thread(
    ingress_tx: Sender<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut rng = rand::thread_rng();
        let payload = vec![0u8; MESSAGE_SIZE];

        while running.load(Ordering::Relaxed) {
            let msg = Message {
                route_key: rng.gen::<u64>(),
                created_at: Instant::now(),
                payload: Bytes::copy_from_slice(&payload),
            };

            metrics.received.fetch_add(1, Ordering::Relaxed);

            if ingress_tx.try_send(msg).is_err() {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    })
}

fn router_thread(
    ingress_rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut batch = Vec::with_capacity(BATCH_SIZE);

        while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
            batch.clear();

            for _ in 0..BATCH_SIZE {
                match ingress_rx.try_recv() {
                    Ok(msg) => batch.push(msg),
                    Err(_) => break,
                }
            }

            if batch.is_empty() {
                thread::yield_now();
                continue;
            }

            for msg in batch.drain(..) {
                let idx = route_message(&msg, worker_txs.len());
                if worker_txs[idx].try_send(msg).is_ok() {
                    metrics.routed.fetch_add(1, Ordering::Relaxed);
                } else {
                    metrics.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
    })
}

fn worker_thread(
    worker_rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
    worker_id: usize,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut local_batch = Vec::with_capacity(BATCH_SIZE);

        while running.load(Ordering::Relaxed) || !worker_rx.is_empty() {
            local_batch.clear();

            for _ in 0..BATCH_SIZE {
                match worker_rx.try_recv() {
                    Ok(msg) => local_batch.push(msg),
                    Err(_) => break,
                }
            }

            if local_batch.is_empty() {
                thread::yield_now();
                continue;
            }

            for msg in local_batch.drain(..) {
                // Simulate processing / forwarding
                std::hint::black_box(&msg.payload);

                let latency = msg.created_at.elapsed().as_micros() as u64;
                metrics.record_latency(latency);
                metrics.processed.fetch_add(1, Ordering::Relaxed);
            }
        }

        println!("worker {} exiting", worker_id);
    })
}

fn metrics_thread(metrics: Arc<Metrics>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_received = 0;
        let mut last_processed = 0;

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let received = metrics.received.load(Ordering::Relaxed);
            let routed = metrics.routed.load(Ordering::Relaxed);
            let dropped = metrics.dropped.load(Ordering::Relaxed);
            let processed = metrics.processed.load(Ordering::Relaxed);

            let rps_in = received - last_received;
            let rps_out = processed - last_processed;

            last_received = received;
            last_processed = processed;

            let hist_snapshot = {
                let hist = metrics.latency_hist.lock().unwrap();
                hist.clone()
            };

            println!(
                "in/s={} out/s={} total_received={} routed={} processed={} dropped={} p50={}us p95={}us p99={}us max={}us",
                rps_in,
                rps_out,
                received,
                routed,
                processed,
                dropped,
                hist_snapshot.value_at_quantile(0.50),
                hist_snapshot.value_at_quantile(0.95),
                hist_snapshot.value_at_quantile(0.99),
                hist_snapshot.max()
            );
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(CHANNEL_CAPACITY);

    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_handles = Vec::with_capacity(NUM_WORKERS);

    for worker_id in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY);
        worker_txs.push(tx);

        worker_handles.push(worker_thread(
            rx,
            metrics.clone(),
            running.clone(),
            worker_id,
        ));
    }

    let producer = producer_thread(ingress_tx, metrics.clone(), running.clone());
    let router = router_thread(ingress_rx, worker_txs, metrics.clone(), running.clone());
    let metrics_handle = metrics_thread(metrics.clone(), running.clone());

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    producer.join().unwrap();
    router.join().unwrap();

    for handle in worker_handles {
        handle.join().unwrap();
    }

    metrics_handle.join().unwrap();

    let final_hist = metrics.latency_hist.lock().unwrap().clone();

    println!("--- Final Summary ---");
    println!(
        "received={} routed={} processed={} dropped={}",
        metrics.received.load(Ordering::Relaxed),
        metrics.routed.load(Ordering::Relaxed),
        metrics.processed.load(Ordering::Relaxed),
        metrics.dropped.load(Ordering::Relaxed),
    );
    println!(
        "latency: p50={}us p95={}us p99={}us p99.9={}us max={}us",
        final_hist.value_at_quantile(0.50),
        final_hist.value_at_quantile(0.95),
        final_hist.value_at_quantile(0.99),
        final_hist.value_at_quantile(0.999),
        final_hist.max()
    );
}
```

