Example implementation:

```java
package hfmsg;

import java.util.concurrent.atomic.LongAdder;

public final class InMemoryDestinationPublisher implements DestinationPublisher {
    private final LongAdder[] counters;

    public InMemoryDestinationPublisher(int destinationCount) {
        this.counters = new LongAdder[destinationCount];
        for (int i = 0; i < destinationCount; i++) {
            counters[i] = new LongAdder();
        }
    }

    @Override
    public void publish(MessageEvent event, int destinationId) {
        // In production this could write to a socket, Aeron publication, Kafka producer, etc.
        counters[destinationId].increment();
    }

    public long count(int destinationId) {
        return counters[destinationId].sum();
    }
}
```

