# 8. Router event handler

```java
package hfmsg;

import com.lmax.disruptor.EventHandler;

public final class RoutingEventHandler implements EventHandler<MessageEvent> {
    private final RoutingStrategy routingStrategy;
    private final DestinationPublisher destinationPublisher;
    private final LatencyMonitor latencyMonitor;
    private final int destinationCount;

    public RoutingEventHandler(
            RoutingStrategy routingStrategy,
            DestinationPublisher destinationPublisher,
            LatencyMonitor latencyMonitor,
            int destinationCount) {
        this.routingStrategy = routingStrategy;
        this.destinationPublisher = destinationPublisher;
        this.latencyMonitor = latencyMonitor;
        this.destinationCount = destinationCount;
    }

    @Override
    public void onEvent(MessageEvent event, long sequence, boolean endOfBatch) {
        long now = System.nanoTime();
        event.routedNanoTime = now;

        int destinationId = routingStrategy.route(event, destinationCount);
        destinationPublisher.publish(event, destinationId);

        latencyMonitor.recordIngressToRoute(now - event.ingressNanoTime);
        latencyMonitor.recordEndToEnd(now - event.createdNanoTime);
        latencyMonitor.incrementRouted();

        event.clear();
    }
}
```

