# 9. High-frequency router service

```java
package hfmsg;

import com.lmax.disruptor.*;
import com.lmax.disruptor.dsl.Disruptor;
import com.lmax.disruptor.dsl.ProducerType;

import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;

public final class HighFrequencyMessageRouter implements AutoCloseable {
    private final Disruptor<MessageEvent> disruptor;
    private final RingBuffer<MessageEvent> ringBuffer;
    private final MessageTranslator translator = new MessageTranslator();
    private final LatencyMonitor latencyMonitor;

    public HighFrequencyMessageRouter(
            int ringBufferSize,
            RoutingStrategy routingStrategy,
            DestinationPublisher destinationPublisher,
            int destinationCount,
            LatencyMonitor latencyMonitor) {

        this.latencyMonitor = latencyMonitor;

        ThreadFactory threadFactory = Executors.defaultThreadFactory();

        this.disruptor = new Disruptor<>(
                new MessageEventFactory(),
                ringBufferSize,
                threadFactory,
                ProducerType.MULTI,
                new BusySpinWaitStrategy()
        );

        this.disruptor.handleEventsWith(
                new RoutingEventHandler(
                        routingStrategy,
                        destinationPublisher,
                        latencyMonitor,
                        destinationCount
                )
        );

        this.ringBuffer = disruptor.start();
    }

    public boolean publish(IncomingMessage message) {
        try {
            ringBuffer.publishEvent(translator, message);
            return true;
        } catch (InsufficientCapacityException e) {
            latencyMonitor.incrementDropped();
            return false;
        } catch (Exception e) {
            latencyMonitor.incrementDropped();
            return false;
        }
    }

    public boolean tryPublish(IncomingMessage message) {
        boolean published = ringBuffer.tryPublishEvent(translator, message);
        if (!published) {
            latencyMonitor.incrementDropped();
        }
        return published;
    }

    public LatencyMonitor latencyMonitor() {
        return latencyMonitor;
    }

    @Override
    public void close() {
        disruptor.shutdown();
    }
}
```

