public final class LatencyMonitor {
    private final Recorder ingressToRouteRecorder = new Recorder(3);
    private final Recorder endToEndRecorder = new Recorder(3);

    private final AtomicReference<Histogram> ingressSnapshot =
            new AtomicReference<>(new Histogram(3_600_000_000L, 3));
    private final AtomicReference<Histogram> e2eSnapshot =
            new AtomicReference<>(new Histogram(3_600_000_000L, 3));

    private final LongAdder routedCount = new LongAdder();
