        return routedCount.sum();
    }

    public long droppedCount() {
        return droppedCount.sum();
    }

    public void refresh() {
        ingressSnapshot.set(ingressToRouteRecorder.getIntervalHistogram());
        e2eSnapshot.set(endToEndRecorder.getIntervalHistogram());
    }

