## main.rs

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_WORKERS: usize = 8;
const QUEUE_CAPACITY: usize = 1_000_000;
const METRICS_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: String,
    payload: Vec<u8>,
    created_at: Instant,
}

#[derive(Default)]
struct WorkerStats {
    processed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
}

struct SharedMetrics {
    histograms: Vec<Mutex<Histogram<u64>>>,
    worker_stats: Vec<WorkerStats>,
    total_ingress: AtomicU64,
    total_routed: AtomicU64,
}

impl SharedMetrics {
    fn new(num_workers: usize) -> Self {
        let mut histograms = Vec::with_capacity(num_workers);
        let mut worker_stats = Vec::with_capacity(num_workers);

        for _ in 0..num_workers {
            histograms.push(Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ));
            worker_stats.push(WorkerStats::default());
        }

        Self {
            histograms,
            worker_stats,
            total_ingress: AtomicU64::new(0),
            total_routed: AtomicU64::new(0),
        }
    }
}

struct Router {
    worker_senders: Vec<Sender<Message>>,
    route_table: HashMap<String, usize>,
    metrics: Arc<SharedMetrics>,
}

impl Router {
    fn new(worker_senders: Vec<Sender<Message>>, metrics: Arc<SharedMetrics>) -> Self {
        Self {
            worker_senders,
            route_table: HashMap::new(),
            metrics,
        }
    }

    fn register_topic(&mut self, topic: &str, worker_id: usize) {
        self.route_table.insert(topic.to_string(), worker_id);
    }

    fn route(&self, msg: Message) {
        self.metrics.total_ingress.fetch_add(1, Ordering::Relaxed);

        let worker_id = self
            .route_table
            .get(&msg.topic)
            .copied()
            .unwrap_or_else(|| self.hash_topic(&msg.topic) % self.worker_senders.len());

        match self.worker_senders[worker_id].try_send(msg) {
            Ok(_) => {
                self.metrics.total_routed.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                self.metrics.worker_stats[worker_id]
                    .dropped
                    .fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    fn hash_topic(&self, topic: &str) -> usize {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        topic.hash(&mut hasher);
        hasher.finish() as usize
    }
}

fn worker_loop(worker_id: usize, rx: Receiver<Message>, metrics: Arc<SharedMetrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let now = Instant::now();
                let latency = now.duration_since(msg.created_at).as_nanos() as u64;

                metrics.worker_stats[worker_id]
                    .processed
                    .fetch_add(1, Ordering::Relaxed);

                metrics.worker_stats[worker_id]
                    .total_latency_ns
                    .fetch_add(latency, Ordering::Relaxed);

                if let Ok(mut hist) = metrics.histograms[worker_id].lock() {
                    let _ = hist.record(latency);
                }

                // Simulate forwarding/processing
                process_message(msg);
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn process_message(_msg: Message) {
    // Replace with actual downstream send / business logic
    std::hint::spin_loop();
}

fn metrics_loop(metrics: Arc<SharedMetrics>, running: Arc<AtomicBool>) {
    let mut last_ingress = 0;
    let mut last_routed = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(METRICS_INTERVAL);

        let ingress = metrics.total_ingress.load(Ordering::Relaxed);
        let routed = metrics.total_routed.load(Ordering::Relaxed);

        let ingress_rate = ingress - last_ingress;
        let routed_rate = routed - last_routed;

        last_ingress = ingress;
        last_routed = routed;

        println!("=== Metrics ===");
        println!("Ingress/sec: {}", ingress_rate);
        println!("Routed/sec : {}", routed_rate);

        for (i, stats) in metrics.worker_stats.iter().enumerate() {
            let processed = stats.processed.load(Ordering::Relaxed);
            let dropped = stats.dropped.load(Ordering::Relaxed);
            let total_latency = stats.total_latency_ns.load(Ordering::Relaxed);

            let avg_latency_ns = if processed > 0 {
                total_latency / processed
            } else {
                0
            };

            if let Ok(hist) = metrics.histograms[i].lock() {
                let p50 = if hist.len() > 0 { hist.value_at_quantile(0.50) } else { 0 };
                let p95 = if hist.len() > 0 { hist.value_at_quantile(0.95) } else { 0 };
                let p99 = if hist.len() > 0 { hist.value_at_quantile(0.99) } else { 0 };
                let max = if hist.len() > 0 { hist.max() } else { 0 };

                println!(
                    "Worker {}: processed={}, dropped={}, avg={}ns p50={}ns p95={}ns p99={}ns max={}ns",
                    i, processed, dropped, avg_latency_ns, p50, p95, p99, max
                );
            }
        }
    }
}

fn producer_loop(router: Arc<Router>, running: Arc<AtomicBool>) {
    let mut id = 0u64;
    let topics = ["orders", "trades", "quotes", "risk", "audit"];

    while running.load(Ordering::Relaxed) {
        let topic = topics[(id as usize) % topics.len()].to_string();
        let msg = Message {
            id,
            topic,
            payload: vec![0u8; 128],
            created_at: Instant::now(),
        };

        router.route(msg);
        id += 1;

        // Remove this in real production ingress; here it's just a synthetic load generator
        if id % 100_000 == 0 {
            std::hint::spin_loop();
        }
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(SharedMetrics::new(NUM_WORKERS));

    let mut worker_senders = Vec::with_capacity(NUM_WORKERS);
    let mut worker_receivers = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        worker_senders.push(tx);
        worker_receivers.push(rx);
    }

    let mut router = Router::new(worker_senders, metrics.clone());

    router.register_topic("orders", 0);
    router.register_topic("trades", 1);
    router.register_topic("quotes", 2);
    router.register_topic("risk", 3);
    router.register_topic("audit", 4);

    let router = Arc::new(router);

    let mut handles = Vec::new();

    for (worker_id, rx) in worker_receivers.into_iter().enumerate() {
        let metrics_clone = metrics.clone();
        let running_clone = running.clone();
        handles.push(thread::spawn(move || {
            worker_loop(worker_id, rx, metrics_clone, running_clone)
        }));
    }

    {
        let metrics_clone = metrics.clone();
        let running_clone = running.clone();
        handles.push(thread::spawn(move || {
            metrics_loop(metrics_clone, running_clone)
        }));
    }

    let producer_threads = num_cpus::get().max(2) / 2;
    for _ in 0..producer_threads {
        let router_clone = router.clone();
        let running_clone = running.clone();
        handles.push(thread::spawn(move || {
            producer_loop(router_clone, running_clone)
        }));
    }

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for handle in handles {
        let _ = handle.join();
    }
}
```

