use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_WORKERS: usize = 8;
const QUEUE_CAPACITY: usize = 1_000_000;
const METRICS_INTERVAL_SECS: u64 = 1;
const RUN_DURATION_SECS: u64 = 10;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    route_key: u64,
    created_at: Instant,
    payload: [u8; 64],
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    total_latency_ns: AtomicU64,
    route_counts: Mutex<HashMap<u64, u64>>,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            route_counts: Mutex::new(HashMap::new()),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap()
            ),
        }
    }

    fn record_route(&self, route_key: u64) {
        let mut routes = self.route_counts.lock().unwrap();
        *routes.entry(route_key).or_insert(0) += 1;
    }

    fn record_latency(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.total_latency_ns.fetch_add(ns, Ordering::Relaxed);
        let mut hist = self.latency_hist.lock().unwrap();
        let _ = hist.record(ns);
    }
}

fn worker_loop(
    worker_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let latency = msg.created_at.elapsed();
                metrics.processed.fetch_add(1, Ordering::Relaxed);
                metrics.record_latency(latency);

                // Simulated processing
                std::hint::black_box(msg.payload);
                std::hint::black_box(worker_id);
            }
            Err(_) => {}
        }
    }
}

fn router_loop(
    ingress_rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    let num_workers = worker_txs.len();

    while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
        match ingress_rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let shard = (msg.route_key as usize) % num_workers;
                metrics.routed.fetch_add(1, Ordering::Relaxed);
                metrics.record_route(msg.route_key);

                if worker_txs[shard].try_send(msg).is_err() {
                    metrics.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }
}

fn producer_loop(
    producer_id: usize,
    ingress_tx: Sender<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    let mut rng = rand::thread_rng();
    let mut msg_id = producer_id as u64 * 1_000_000_000;

    while running.load(Ordering::Relaxed) {
        let msg = Message {
            id: msg_id,
            route_key: rng.gen_range(0..1024),
            created_at: Instant::now(),
            payload: [42u8; 64],
        };

        metrics.received.fetch_add(1, Ordering::Relaxed);

        if ingress_tx.try_send(msg).is_err() {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }

        msg_id += 1;
    }
}

fn metrics_loop(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let mut last_processed = 0u64;
    let mut last_received = 0u64;
    let mut last_routed = 0u64;
    let mut last_dropped = 0u64;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(METRICS_INTERVAL_SECS));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let processed = metrics.processed.load(Ordering::Relaxed);

        let delta_received = received - last_received;
        let delta_routed = routed - last_routed;
        let delta_dropped = dropped - last_dropped;
        let delta_processed = processed - last_processed;

        last_received = received;
        last_routed = routed;
        last_dropped = dropped;
        last_processed = processed;

        let hist = metrics.latency_hist.lock().unwrap();
        let p50 = if hist.len() > 0 { hist.value_at_quantile(0.50) } else { 0 };
        let p95 = if hist.len() > 0 { hist.value_at_quantile(0.95) } else { 0 };
        let p99 = if hist.len() > 0 { hist.value_at_quantile(0.99) } else { 0 };
        let max = if hist.len() > 0 { hist.max() } else { 0 };

        println!(
            "Throughput recv={} routed={} processed={} dropped={} msg/s | latency(ns) p50={} p95={} p99={} max={}",
            delta_received,
            delta_routed,
            delta_processed,
            delta_dropped,
            p50,
            p95,
            p99,
            max
        );
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(QUEUE_CAPACITY);

    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY / NUM_WORKERS);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    let router_metrics = Arc::clone(&metrics);
    let router_running = Arc::clone(&running);
    let router_worker_txs = worker_txs.clone();
    let router_handle = thread::spawn(move || {
        router_loop(ingress_rx, router_worker_txs, router_metrics, router_running)
    });

    let mut worker_handles = Vec::new();
    for (i, rx) in worker_rxs.into_iter().enumerate() {
        let worker_metrics = Arc::clone(&metrics);
        let worker_running = Arc::clone(&running);
        worker_handles.push(thread::spawn(move || {
            worker_loop(i, rx, worker_metrics, worker_running)
        }));
    }

    let producer_count = num_cpus::get().max(2);
    let mut producer_handles = Vec::new();
    for i in 0..producer_count {
        let producer_tx = ingress_tx.clone();
        let producer_metrics = Arc::clone(&metrics);
        let producer_running = Arc::clone(&running);
        producer_handles.push(thread::spawn(move || {
            producer_loop(i, producer_tx, producer_metrics, producer_running)
        }));
    }

    let metrics_handle = {
        let metrics = Arc::clone(&metrics);
        let running = Arc::clone(&running);
        thread::spawn(move || metrics_loop(metrics, running))
    };

    thread::sleep(Duration::from_secs(RUN_DURATION_SECS));
    running.store(false, Ordering::Relaxed);

    for handle in producer_handles {
        let _ = handle.join();
    }

    let _ = router_handle.join();

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = metrics_handle.join();

    println!("Final stats:");
    println!(
        "received={} routed={} processed={} dropped={}",
        metrics.received.load(Ordering::Relaxed),
        metrics.routed.load(Ordering::Relaxed),
        metrics.processed.load(Ordering::Relaxed),
        metrics.dropped.load(Ordering::Relaxed),
    );

    let hist = metrics.latency_hist.lock().unwrap();
    if hist.len() > 0 {
        println!(
            "Latency(ns): p50={} p95={} p99={} p99.9={} max={}",
            hist.value_at_quantile(0.50),
            hist.value_at_quantile(0.95),
            hist.value_at_quantile(0.99),
            hist.value_at_quantile(0.999),
            hist.max()
        );
    }
}
```

