```rust
use bytes::Bytes;
use crossbeam::channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[inline(always)]
fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

#[derive(Clone)]
pub struct Message {
    pub topic: Arc<str>,
    pub payload: Bytes,
    pub created_at_ns: u64,
    pub sequence: u64,
}

impl Message {
    pub fn new(topic: Arc<str>, payload: Bytes, sequence: u64) -> Self {
        Self {
            topic,
            payload,
            created_at_ns: now_nanos(),
            sequence,
        }
    }
}

pub trait Handler: Send + Sync + 'static {
    fn on_message(&self, msg: &Message);
}

pub struct PrintHandler;

impl Handler for PrintHandler {
    fn on_message(&self, msg: &Message) {
        let _ = msg;
        // Intentionally minimal for performance.
    }
}

struct Subscriber {
    id: usize,
    sender: Sender<Message>,
}

pub struct Metrics {
    pub received: AtomicU64,
    pub routed: AtomicU64,
    pub dropped: AtomicU64,
    pub worker_processed: AtomicU64,
    pub total_route_latency_ns: AtomicU64,
    pub total_end_to_end_latency_ns: AtomicU64,
    pub max_route_latency_ns: AtomicU64,
    pub max_end_to_end_latency_ns: AtomicU64,
    pub route_hist: Mutex<Histogram<u64>>,
    pub e2e_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    pub fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            worker_processed: AtomicU64::new(0),
            total_route_latency_ns: AtomicU64::new(0),
            total_end_to_end_latency_ns: AtomicU64::new(0),
            max_route_latency_ns: AtomicU64::new(0),
            max_end_to_end_latency_ns: AtomicU64::new(0),
            route_hist: Mutex::new(Histogram::new(3).unwrap()),
            e2e_hist: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    #[inline(always)]
    pub fn record_route_latency(&self, latency_ns: u64) {
        self.total_route_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);
        self.update_max(&self.max_route_latency_ns, latency_ns);
        let mut h = self.route_hist.lock();
        let _ = h.record(latency_ns);
    }

    #[inline(always)]
    pub fn record_e2e_latency(&self, latency_ns: u64) {
        self.total_end_to_end_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);
        self.update_max(&self.max_end_to_end_latency_ns, latency_ns);
        let mut h = self.e2e_hist.lock();
        let _ = h.record(latency_ns);
    }

    #[inline(always)]
    fn update_max(&self, target: &AtomicU64, value: u64) {
        let mut current = target.load(Ordering::Relaxed);
        while value > current {
            match target.compare_exchange_weak(
                current,
                value,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    pub fn snapshot(&self) -> MetricsSnapshot {
        let received = self.received.load(Ordering::Relaxed);
        let routed = self.routed.load(Ordering::Relaxed);
        let dropped = self.dropped.load(Ordering::Relaxed);
        let worker_processed = self.worker_processed.load(Ordering::Relaxed);
        let total_route_latency_ns = self.total_route_latency_ns.load(Ordering::Relaxed);
        let total_end_to_end_latency_ns =
            self.total_end_to_end_latency_ns.load(Ordering::Relaxed);
        let max_route_latency_ns = self.max_route_latency_ns.load(Ordering::Relaxed);
        let max_end_to_end_latency_ns =
            self.max_end_to_end_latency_ns.load(Ordering::Relaxed);

        let route_hist = self.route_hist.lock();
        let e2e_hist = self.e2e_hist.lock();

        MetricsSnapshot {
            received,
            routed,
            dropped,
            worker_processed,
            avg_route_latency_ns: if routed > 0 {
                total_route_latency_ns / routed
            } else {
                0
            },
            avg_e2e_latency_ns: if worker_processed > 0 {
                total_end_to_end_latency_ns / worker_processed
            } else {
                0
            },
            max_route_latency_ns,
            max_end_to_end_latency_ns,
            route_p50_ns: route_hist.value_at_quantile(0.50),
            route_p99_ns: route_hist.value_at_quantile(0.99),
            route_p999_ns: route_hist.value_at_quantile(0.999),
            e2e_p50_ns: e2e_hist.value_at_quantile(0.50),
            e2e_p99_ns: e2e_hist.value_at_quantile(0.99),
            e2e_p999_ns: e2e_hist.value_at_quantile(0.999),
        }
    }
}

pub struct MetricsSnapshot {
    pub received: u64,
    pub routed: u64,
    pub dropped: u64,
    pub worker_processed: u64,
    pub avg_route_latency_ns: u64,
    pub avg_e2e_latency_ns: u64,
    pub max_route_latency_ns: u64,
    pub max_end_to_end_latency_ns: u64,
    pub route_p50_ns: u64,
    pub route_p99_ns: u64,
    pub route_p999_ns: u64,
    pub e2e_p50_ns: u64,
    pub e2e_p99_ns: u64,
    pub e2e_p999_ns: u64,
}

pub struct Router {
    ingress_tx: Sender<Message>,
    subscriptions: Arc<DashMap<Arc<str>, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
    next_subscriber_id: AtomicUsize,
}

impl Router {
    pub fn new(
        ingress_capacity: usize,
        worker_count: usize,
        worker_queue_capacity: usize,
    ) -> Self {
        let (ingress_tx, ingress_rx) = bounded::<Message>(ingress_capacity);
        let subscriptions = Arc::new(DashMap::<Arc<str>, Vec<Subscriber>>::new());
        let metrics = Arc::new(Metrics::new());
        let running = Arc::new(AtomicBool::new(true));

        let mut worker_senders = Vec::with_capacity(worker_count);

        for worker_id in 0..worker_count {
            let (tx, rx) = bounded::<Message>(worker_queue_capacity);
            worker_senders.push(tx);

            let metrics_clone = Arc::clone(&metrics);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name(format!("worker-{worker_id}"))
                .spawn(move || worker_loop(worker_id, rx, metrics_clone, running_clone))
                .expect("failed to spawn worker");
        }

        {
            let subscriptions_clone = Arc::clone(&subscriptions);
            let metrics_clone = Arc::clone(&metrics);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name("router-dispatch".to_string())
                .spawn(move || {
                    dispatch_loop(
                        ingress_rx,
                        worker_senders,
                        subscriptions_clone,
                        metrics_clone,
                        running_clone,
                    )
                })
                .expect("failed to spawn dispatch thread");
        }

        Self {
            ingress_tx,
            subscriptions,
            metrics,
            running,
            next_subscriber_id: AtomicUsize::new(1),
        }
    }

    #[inline(always)]
    pub fn publish(&self, msg: Message) -> Result<(), Message> {
        self.metrics.received.fetch_add(1, Ordering::Relaxed);
        match self.ingress_tx.try_send(msg) {
            Ok(_) => Ok(()),
            Err(err) => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                Err(err.into_inner())
            }
        }
    }

    pub fn subscribe<H: Handler>(&self, topic: &str, handler: H, queue_capacity: usize) -> usize {
        let subscriber_id = self.next_subscriber_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = bounded::<Message>(queue_capacity);
        let topic_arc: Arc<str> = Arc::from(topic);

        let subscriber = Subscriber {
            id: subscriber_id,
            sender: tx,
        };

        self.subscriptions
            .entry(Arc::clone(&topic_arc))
            .and_modify(|subs| subs.push(Subscriber {
                id: subscriber.id,
                sender: subscriber.sender.clone(),
            }))
            .or_insert_with(|| vec![subscriber]);

        let metrics_clone = Arc::clone(&self.metrics);
        let running_clone = Arc::clone(&self.running);
        let handler = Arc::new(handler);

        thread::Builder::new()
            .name(format!("subscriber-{subscriber_id}"))
            .spawn(move || subscriber_loop(rx, handler, metrics_clone, running_clone))
            .expect("failed to spawn subscriber thread");

        subscriber_id
    }

    pub fn unsubscribe(&self, topic: &str, subscriber_id: usize) -> bool {
        if let Some(mut entry) = self.subscriptions.get_mut(topic) {
            let before = entry.len();
            entry.retain(|s| s.id != subscriber_id);
            return before != entry.len();
        }
        false
    }

    pub fn metrics(&self) -> Arc<Metrics> {
        Arc::clone(&self.metrics)
    }

    pub fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn dispatch_loop(
    ingress_rx: Receiver<Message>,
    worker_senders: Vec<Sender<Message>>,
    subscriptions: Arc<DashMap<Arc<str>, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match ingress_rx.recv() {
            Ok(msg) => {
                let route_start = now_nanos();

                if let Some(subs) = subscriptions.get(&msg.topic) {
                    for sub in subs.iter() {
                        let _ = sub.sender.try_send(msg.clone());
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                } else if !worker_senders.is_empty() {
                    let idx = hash_topic(&msg.topic) % worker_senders.len();
                    if worker_senders[idx].try_send(msg).is_ok() {
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    } else {
                        metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                } else {
                    metrics.dropped.fetch_add(1, Ordering::Relaxed);
                }

                let route_latency = now_nanos().saturating_sub(route_start);
                metrics.record_route_latency(route_latency);
            }
            Err(_) => break,
        }
    }
}

fn worker_loop(
    _worker_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv() {
            Ok(msg) => {
                let now = now_nanos();
                let e2e = now.saturating_sub(msg.created_at_ns);
                metrics.worker_processed.fetch_add(1, Ordering::Relaxed);
                metrics.record_e2e_latency(e2e);
            }
            Err(_) => break,
        }
    }
}

fn subscriber_loop<H: Handler>(
    rx: Receiver<Message>,
    handler: Arc<H>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv() {
            Ok(msg) => {
                handler.on_message(&msg);
                let now = now_nanos();
                let e2e = now.saturating_sub(msg.created_at_ns);
                metrics.worker_processed.fetch_add(1, Ordering::Relaxed);
                metrics.record_e2e_latency(e2e);
            }
            Err(_) => break,
        }
    }
}

#[inline(always)]
fn hash_topic(topic: &str) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    hasher.finish() as usize
}
