use ahash::AHasher;
use bytes::{Buf, BufMut, BytesMut};
use hyper::service::{make_service_fn, service_fn};
use hyper::{Body, Request, Response, Server};
use parking_lot::Mutex;
use prometheus::{
    Encoder, Histogram, HistogramOpts, IntCounter, IntGauge, Registry, TextEncoder,
};
use std::collections::HashMap;
use std::convert::Infallible;
use std::hash::{Hash, Hasher};
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use thiserror::Error;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;

const WORKER_COUNT: usize = 16;
const CHANNEL_CAPACITY: usize = 100_000;
const MAX_FRAME_SIZE: usize = 1024 * 1024;

#[derive(Debug, Clone)]
struct Message {
    id: u64,
    topic: String,
    payload: Vec<u8>,
    ingress_ts_ns: u64,
}

#[derive(Clone)]
struct Metrics {
    registry: Registry,
    messages_in: IntCounter,
    messages_routed: IntCounter,
    messages_dropped: IntCounter,
    active_connections: IntGauge,
    ingress_to_route_latency_us: Histogram,
    end_to_end_latency_us: Histogram,
}

impl Metrics {
    fn new() -> Self {
        let registry = Registry::new();

        let messages_in = IntCounter::new("messages_in_total", "Total messages received").unwrap();
        let messages_routed =
            IntCounter::new("messages_routed_total", "Total messages routed").unwrap();
        let messages_dropped =
            IntCounter::new("messages_dropped_total", "Total messages dropped").unwrap();
        let active_connections =
            IntGauge::new("active_connections", "Current active TCP connections").unwrap();

        let ingress_to_route_latency_us = Histogram::with_opts(HistogramOpts::new(
            "ingress_to_route_latency_us",
            "Latency from ingress to routing in microseconds",
        ).buckets(vec![
            1.0, 2.0, 5.0, 10.0, 20.0, 50.0, 100.0, 200.0, 500.0, 1000.0, 5000.0,
        ])).unwrap();

        let end_to_end_latency_us = Histogram::with_opts(HistogramOpts::new(
            "end_to_end_latency_us",
            "End-to-end processing latency in microseconds",
        ).buckets(vec![
            1.0, 2.0, 5.0, 10.0, 20.0, 50.0, 100.0, 200.0, 500.0, 1000.0, 5000.0, 10000.0,
        ])).unwrap();

        registry.register(Box::new(messages_in.clone())).unwrap();
        registry.register(Box::new(messages_routed.clone())).unwrap();
        registry.register(Box::new(messages_dropped.clone())).unwrap();
        registry.register(Box::new(active_connections.clone())).unwrap();
        registry
            .register(Box::new(ingress_to_route_latency_us.clone()))
            .unwrap();
        registry
            .register(Box::new(end_to_end_latency_us.clone()))
            .unwrap();

        Self {
            registry,
            messages_in,
            messages_routed,
            messages_dropped,
            active_connections,
            ingress_to_route_latency_us,
            end_to_end_latency_us,
        }
    }
}

#[derive(Debug, Error)]
enum ProtocolError {
    #[error("frame too large")]
    FrameTooLarge,
    #[error("invalid frame")]
    InvalidFrame,
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn hash_topic(topic: &str) -> usize {
    let mut hasher = AHasher::default();
    topic.hash(&mut hasher);
    hasher.finish() as usize
}

fn encode_message(msg: &Message) -> Vec<u8> {
    let topic_bytes = msg.topic.as_bytes();
    let payload_len = msg.payload.len();
    let topic_len = topic_bytes.len();

    let total_len = 8 + 8 + 4 + topic_len + 4 + payload_len;
    let mut buf = BytesMut::with_capacity(4 + total_len);

    buf.put_u32(total_len as u32);
    buf.put_u64(msg.id);
    buf.put_u64(msg.ingress_ts_ns);
    buf.put_u32(topic_len as u32);
    buf.extend_from_slice(topic_bytes);
    buf.put_u32(payload_len as u32);
    buf.extend_from_slice(&msg.payload);

    buf.to_vec()
}

fn decode_message(buf: &[u8]) -> Result<Message, ProtocolError> {
    let mut b = buf;

    if b.remaining() < 8 + 8 + 4 {
        return Err(ProtocolError::InvalidFrame);
    }

    let id = b.get_u64();
    let ingress_ts_ns = b.get_u64();
    let topic_len = b.get_u32() as usize;

    if b.remaining() < topic_len + 4 {
        return Err(ProtocolError::InvalidFrame);
    }

    let topic = String::from_utf8(b[..topic_len].to_vec())
        .map_err(|_| ProtocolError::InvalidFrame)?;
    b.advance(topic_len);

    let payload_len = b.get_u32() as usize;
    if b.remaining() < payload_len {
        return Err(ProtocolError::InvalidFrame);
    }

    let payload = b[..payload_len].to_vec();

    Ok(Message {
        id,
        topic,
        payload,
        ingress_ts_ns,
    })
}

async fn read_frame(stream: &mut TcpStream) -> Result<Option<Message>, ProtocolError> {
    let mut len_buf = [0u8; 4];
    match stream.read_exact(&mut len_buf).await {
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
        Err(e) => return Err(ProtocolError::Io(e)),
    }

    let frame_len = u32::from_be_bytes(len_buf) as usize;
    if frame_len > MAX_FRAME_SIZE {
        return Err(ProtocolError::FrameTooLarge);
    }

    let mut frame = vec![0u8; frame_len];
    stream.read_exact(&mut frame).await?;
    let msg = decode_message(&frame)?;
    Ok(Some(msg))
}

async fn write_frame(stream: &mut TcpStream, msg: &Message) -> Result<(), ProtocolError> {
    let data = encode_message(msg);
    stream.write_all(&data).await?;
    Ok(())
}

async fn metrics_server(metrics: Metrics, addr: SocketAddr) {
    let registry = metrics.registry.clone();

    let make_svc = make_service_fn(move |_| {
        let registry = registry.clone();
        async move {
            Ok::<_, Infallible>(service_fn(move |_req: Request<Body>| {
                let registry = registry.clone();
                async move {
                    let encoder = TextEncoder::new();
                    let metric_families = registry.gather();
                    let mut buffer = Vec::new();
                    encoder.encode(&metric_families, &mut buffer).unwrap();
                    Ok::<_, Infallible>(Response::new(Body::from(buffer)))
                }
            }))
        }
    });

    let server = Server::bind(&addr).serve(make_svc);
    if let Err(e) = server.await {
        eprintln!("metrics server error: {}", e);
    }
}

async fn worker_loop(
    worker_id: usize,
    mut rx: mpsc::Receiver<Message>,
    metrics: Metrics,
    subscribers: Arc<Mutex<HashMap<String, Vec<mpsc::Sender<Message>>>>>,
) {
    while let Some(msg) = rx.recv().await {
        let now = now_ns();
        let e2e_us = (now.saturating_sub(msg.ingress_ts_ns)) as f64 / 1000.0;
        metrics.end_to_end_latency_us.observe(e2e_us);

        let targets = {
            let map = subscribers.lock();
            map.get(&msg.topic).cloned()
        };

        if let Some(targets) = targets {
            for tx in targets {
                let _ = tx.try_send(msg.clone());
            }
        }

        metrics.messages_routed.inc();

        if worker_id == 0 && msg.id % 1_000_000 == 0 {
            println!("worker {} processed message {}", worker_id, msg.id);
        }
    }
}

async fn handle_connection(
    mut stream: TcpStream,
    worker_senders: Arc<Vec<mpsc::Sender<Message>>>,
    metrics: Metrics,
) {
    metrics.active_connections.inc();

    loop {
        match read_frame(&mut stream).await {
            Ok(Some(mut msg)) => {
                metrics.messages_in.inc();

                if msg.ingress_ts_ns == 0 {
                    msg.ingress_ts_ns = now_ns();
                }

                let route_start = now_ns();
                let shard = hash_topic(&msg.topic) % worker_senders.len();
                let route_latency_us =
                    (route_start.saturating_sub(msg.ingress_ts_ns)) as f64 / 1000.0;
                metrics
                    .ingress_to_route_latency_us
                    .observe(route_latency_us);

                match worker_senders[shard].try_send(msg) {
                    Ok(_) => {}
                    Err(_) => {
                        metrics.messages_dropped.inc();
                    }
                }
            }
            Ok(None) => break,
            Err(e) => {
                eprintln!("connection error: {}", e);
                break;
            }
        }
    }

    metrics.active_connections.dec();
}

async fn subscriber_task(mut rx: mpsc::Receiver<Message>, name: String) {
    while let Some(msg) = rx.recv().await {
        let _ = msg;
        if false {
            println!("subscriber {} got message", name);
        }
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let metrics = Metrics::new();

    let metrics_addr: SocketAddr = "0.0.0.0:9090".parse()?;
    tokio::spawn(metrics_server(metrics.clone(), metrics_addr));

    let mut worker_senders = Vec::with_capacity(WORKER_COUNT);
    let subscribers: Arc<Mutex<HashMap<String, Vec<mpsc::Sender<Message>>>>> =
        Arc::new(Mutex::new(HashMap::new()));

    for i in 0..WORKER_COUNT {
        let (tx, rx) = mpsc::channel::<Message>(CHANNEL_CAPACITY);
        worker_senders.push(tx);

        let metrics_clone = metrics.clone();
        let subscribers_clone = subscribers.clone();
        tokio::spawn(worker_loop(i, rx, metrics_clone, subscribers_clone));
    }

    let worker_senders = Arc::new(worker_senders);

    for topic in ["orders", "trades", "quotes"] {
        let (tx, rx) = mpsc::channel::<Message>(10_000);
        subscribers.lock().entry(topic.to_string()).or_default().push(tx);
        tokio::spawn(subscriber_task(rx, format!("sub-{}", topic)));
    }

    let listener = TcpListener::bind("0.0.0.0:7000").await?;
    println!("router listening on 0.0.0.0:7000");
    println!("metrics on http://0.0.0.0:9090");

    loop {
        let (stream, _) = listener.accept().await?;
        let senders = worker_senders.clone();
        let metrics_clone = metrics.clone();

        tokio::spawn(async move {
            handle_connection(stream, senders, metrics_clone).await;
        });
    }
}
