```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const WORKER_QUEUE_SIZE: usize = 262_144;
const NUM_TOPICS: usize = 1024;
const PAYLOAD_SIZE: usize = 128;
const RUN_SECONDS: u64 = 10;

#[derive(Clone)]
struct Message {
    route_key: u64,
    created_at: Instant,
    payload: [u8; PAYLOAD_SIZE],
}

struct Metrics {
    total_received: AtomicU64,
    total_routed: AtomicU64,
    total_processed: AtomicU64,
    total_dropped: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            total_received: AtomicU64::new(0),
            total_routed: AtomicU64::new(0),
            total_processed: AtomicU64::new(0),
            total_dropped: AtomicU64::new(0),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000, 3)
                    .expect("failed to create histogram"),
            ),
        }
    }

    fn record_latency_micros(&self, micros: u64) {
        if let Ok(mut hist) = self.latency_hist.lock() {
            let _ = hist.record(micros);
        }
    }

    fn print_snapshot(&self, elapsed: Duration) {
        let received = self.total_received.load(Ordering::Relaxed);
        let routed = self.total_routed.load(Ordering::Relaxed);
        let processed = self.total_processed.load(Ordering::Relaxed);
        let dropped = self.total_dropped.load(Ordering::Relaxed);

        let secs = elapsed.as_secs_f64();
        let throughput = if secs > 0.0 {
            processed as f64 / secs
        } else {
            0.0
        };

        let hist = self.latency_hist.lock().unwrap();
        let p50 = hist.value_at_quantile(0.50);
        let p95 = hist.value_at_quantile(0.95);
        let p99 = hist.value_at_quantile(0.99);
        let max = hist.max();

        println!("=== Metrics Snapshot ===");
        println!("Elapsed: {:.2}s", secs);
        println!("Received: {}", received);
        println!("Routed:   {}", routed);
        println!("Processed:{}", processed);
        println!("Dropped:  {}", dropped);
        println!("Throughput: {:.0} msg/sec", throughput);
        println!("Latency (micros): p50={} p95={} p99={} max={}", p50, p95, p99, max);
        println!();
    }
}

struct Router {
    worker_senders: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(worker_senders: Vec<Sender<Message>>, metrics: Arc<Metrics>) -> Self {
        Self {
            worker_senders,
            metrics,
        }
    }

    fn route(&self, msg: Message) {
        self.metrics.total_received.fetch_add(1, Ordering::Relaxed);

        let idx = shard_for(msg.route_key, self.worker_senders.len());

        match self.worker_senders[idx].try_send(msg) {
            Ok(_) => {
                self.metrics.total_routed.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                self.metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    }
}

fn shard_for(route_key: u64, shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    route_key.hash(&mut hasher);
    (hasher.finish() as usize) % shards
}

fn worker_loop(id: usize, rx: Receiver<Message>, metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let _ = id;

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let latency = msg.created_at.elapsed();
                let micros = latency.as_micros() as u64;
                metrics.record_latency_micros(micros);
                metrics.total_processed.fetch_add(1, Ordering::Relaxed);

                // Simulate lightweight processing to keep benchmark realistic.
                std::hint::black_box(msg.payload[0]);
            }
            Err(_) => {}
        }
    }
}

fn producer_loop(router: Arc<Router>, running: Arc<AtomicBool>) {
    let mut rng = rand::thread_rng();

    while running.load(Ordering::Relaxed) {
        let mut payload = [0u8; PAYLOAD_SIZE];
        rng.fill(&mut payload);

        let msg = Message {
            route_key: rng.gen_range(0..NUM_TOPICS as u64),
            created_at: Instant::now(),
            payload,
        };

        router.route(msg);
    }
}

fn metrics_loop(metrics: Arc<Metrics>, running: Arc<AtomicBool>, start: Instant) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));
        metrics.print_snapshot(start.elapsed());
    }
}

fn main() {
    let num_workers = num_cpus::get().max(2);
    let num_producers = num_cpus::get().max(2);

    println!("Starting router with {} producers and {} workers", num_producers, num_workers);

    let metrics = Arc::new(Metrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let mut worker_senders = Vec::with_capacity(num_workers);
    let mut worker_receivers = Vec::with_capacity(num_workers);

    for _ in 0..num_workers {
        let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
        worker_senders.push(tx);
        worker_receivers.push(rx);
    }

    let router = Arc::new(Router::new(worker_senders, metrics.clone()));

    let mut handles = Vec::new();

    for (id, rx) in worker_receivers.into_iter().enumerate() {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || worker_loop(id, rx, metrics, running)));
    }

    for _ in 0..num_producers {
        let router = router.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || producer_loop(router, running)));
    }

    {
        let metrics = metrics.clone();
        let running = running.clone();
        let start = Instant::now();
        handles.push(thread::spawn(move || metrics_loop(metrics, running, start)));
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    for handle in handles {
        let _ = handle.join();
    }

    println!("Final metrics:");
    metrics.print_snapshot(Duration::from_secs(RUN_SECONDS));
}
```

