use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use rand::Rng;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const EGRESS_QUEUE_SIZE: usize = 1_000_000;
const NUM_ROUTER_THREADS: usize = 4;
const NUM_EGRESS_THREADS: usize = 8;
const PAYLOAD_SIZE: usize = 128;

#[derive(Clone)]
struct Message {
    id: u64,
    route_key: u64,
    created_ns: u64,
    payload: [u8; PAYLOAD_SIZE],
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    delivered: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn record_receive(&self) {
        self.received.fetch_add(1, Ordering::Relaxed);
    }

    fn record_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    fn record_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    fn record_delivery_latency(&self, latency_ns: u64) {
        self.delivered.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }
}

struct LatencyHistogram {
    // Buckets in microseconds:
    // <1, <5, <10, <50, <100, <500, <1000, <5000, >=5000
    buckets: [AtomicU64; 9],
}

impl LatencyHistogram {
    fn new() -> Self {
        Self {
            buckets: std::array::from_fn(|_| AtomicU64::new(0)),
        }
    }

    fn record_ns(&self, ns: u64) {
        let us = ns / 1_000;
        let idx = match us {
            0 => 0,
            1..=4 => 1,
            5..=9 => 2,
            10..=49 => 3,
            50..=99 => 4,
            100..=499 => 5,
            500..=999 => 6,
            1000..=4999 => 7,
            _ => 8,
        };
        self.buckets[idx].fetch_add(1, Ordering::Relaxed);
    }

    fn snapshot(&self) -> [u64; 9] {
        std::array::from_fn(|i| self.buckets[i].load(Ordering::Relaxed))
    }
}

type RouteTable = DashMap<u64, usize>;

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn router_worker(
    ingress_rx: Receiver<Message>,
    egress_txs: Arc<Vec<Sender<Message>>>,
    routes: Arc<RouteTable>,
    metrics: Arc<Metrics>,
) {
    while let Ok(msg) = ingress_rx.recv() {
        let target = routes
            .get(&msg.route_key)
            .map(|v| *v)
            .unwrap_or((msg.route_key as usize) % egress_txs.len());

        match egress_txs[target].try_send(msg) {
            Ok(_) => metrics.record_routed(),
            Err(_) => metrics.record_dropped(),
        }
    }
}

fn egress_worker(
    egress_rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    histogram: Arc<LatencyHistogram>,
) {
    while let Ok(msg) = egress_rx.recv() {
        let latency = now_ns().saturating_sub(msg.created_ns);

        metrics.record_delivery_latency(latency);
        histogram.record_ns(latency);

        // Simulate delivery work
        std::hint::black_box(msg);
    }
}

fn producer(ingress_tx: Sender<Message>, metrics: Arc<Metrics>, producer_id: u64) {
    let mut rng = rand::thread_rng();
    let mut msg_id = producer_id * 1_000_000_000;

    loop {
        let mut payload = [0u8; PAYLOAD_SIZE];
        rng.fill(&mut payload);

        let msg = Message {
            id: msg_id,
            route_key: rng.gen_range(0..1024),
            created_ns: now_ns(),
            payload,
        };

        metrics.record_receive();

        if ingress_tx.try_send(msg).is_err() {
            metrics.record_dropped();
        }

        msg_id += 1;
    }
}

fn metrics_reporter(metrics: Arc<Metrics>, histogram: Arc<LatencyHistogram>) {
    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_delivered = 0;
    let mut last_dropped = 0;

    loop {
        thread::sleep(Duration::from_secs(1));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let delivered = metrics.delivered.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let total_latency_ns = metrics.total_latency_ns.load(Ordering::Relaxed);
        let max_latency_ns = metrics.max_latency_ns.load(Ordering::Relaxed);

        let delta_received = received - last_received;
        let delta_routed = routed - last_routed;
        let delta_delivered = delivered - last_delivered;
        let delta_dropped = dropped - last_dropped;

        last_received = received;
        last_routed = routed;
        last_delivered = delivered;
        last_dropped = dropped;

        let avg_latency_us = if delivered > 0 {
            (total_latency_ns / delivered) as f64 / 1_000.0
        } else {
            0.0
        };

        let hist = histogram.snapshot();

        println!("=== Metrics ===");
        println!("recv/s      : {}", delta_received);
        println!("routed/s    : {}", delta_routed);
        println!("delivered/s : {}", delta_delivered);
        println!("dropped/s   : {}", delta_dropped);
        println!("avg lat us  : {:.2}", avg_latency_us);
        println!("max lat us  : {:.2}", max_latency_ns as f64 / 1_000.0);
        println!(
            "lat buckets : <1={} <5={} <10={} <50={} <100={} <500={} <1000={} <5000={} >=5000={}",
            hist[0], hist[1], hist[2], hist[3], hist[4], hist[5], hist[6], hist[7], hist[8]
        );
    }
}

fn main() {
    let metrics = Arc::new(Metrics::default());
    let histogram = Arc::new(LatencyHistogram::new());
    let routes = Arc::new(RouteTable::new());

    for key in 0..1024u64 {
        routes.insert(key, (key as usize) % NUM_EGRESS_THREADS);
    }

    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);

    let mut egress_txs = Vec::with_capacity(NUM_EGRESS_THREADS);
    let mut egress_rxs = Vec::with_capacity(NUM_EGRESS_THREADS);

    for _ in 0..NUM_EGRESS_THREADS {
        let (tx, rx) = bounded::<Message>(EGRESS_QUEUE_SIZE);
        egress_txs.push(tx);
        egress_rxs.push(rx);
    }

    let egress_txs = Arc::new(egress_txs);

    for _ in 0..NUM_ROUTER_THREADS {
        let rx = ingress_rx.clone();
        let txs = Arc::clone(&egress_txs);
        let routes = Arc::clone(&routes);
        let metrics = Arc::clone(&metrics);

        thread::spawn(move || router_worker(rx, txs, routes, metrics));
    }

    for rx in egress_rxs {
        let metrics = Arc::clone(&metrics);
        let histogram = Arc::clone(&histogram);

        thread::spawn(move || egress_worker(rx, metrics, histogram));
    }

    let producer_threads = num_cpus::get().max(2);
    for i in 0..producer_threads {
        let tx = ingress_tx.clone();
        let metrics = Arc::clone(&metrics);

        thread::spawn(move || producer(tx, metrics, i as u64));
    }

    {
        let metrics = Arc::clone(&metrics);
        let histogram = Arc::clone(&histogram);
        thread::spawn(move || metrics_reporter(metrics, histogram));
    }

    loop {
        thread::park();
    }
}
```

