```rust
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use rand::Rng;
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_WORKERS: usize = 8;
const QUEUE_CAPACITY: usize = 100_000;
const PAYLOAD_SIZE: usize = 128;
const REPORT_INTERVAL_SECS: u64 = 1;

#[inline(always)]
fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

#[derive(Clone)]
struct Message {
    id: u64,
    topic: u64,
    created_at_ns: u64,
    payload: [u8; PAYLOAD_SIZE],
}

impl Message {
    #[inline(always)]
    fn new(id: u64, topic: u64) -> Self {
        let mut payload = [0u8; PAYLOAD_SIZE];
        payload[0..8].copy_from_slice(&id.to_le_bytes());
        Self {
            id,
            topic,
            created_at_ns: now_nanos(),
            payload,
        }
    }
}

struct RouteMetrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl RouteMetrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    #[inline(always)]
    fn record_routed(&self, latency_ns: u64) {
        self.routed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    #[inline(always)]
    fn record_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

struct Router {
    workers: Vec<Sender<Message>>,
    route_metrics: DashMap<u64, Arc<RouteMetrics>>,
}

impl Router {
    fn new(workers: Vec<Sender<Message>>) -> Self {
        Self {
            workers,
            route_metrics: DashMap::new(),
        }
    }

    #[inline(always)]
    fn get_metrics(&self, topic: u64) -> Arc<RouteMetrics> {
        self.route_metrics
            .entry(topic)
            .or_insert_with(|| Arc::new(RouteMetrics::new()))
            .clone()
    }

    #[inline(always)]
    fn route(&self, msg: Message) {
        let worker_idx = (msg.topic as usize) % self.workers.len();
        let metrics = self.get_metrics(msg.topic);

        match self.workers[worker_idx].try_send(msg) {
            Ok(_) => {}
            Err(TrySendError::Full(_)) | Err(TrySendError::Disconnected(_)) => {
                metrics.record_dropped();
            }
        }
    }
}

fn worker_loop(worker_id: usize, rx: Receiver<Message>, metrics: Arc<DashMap<u64, Arc<RouteMetrics>>>) {
    let _ = worker_id;
    while let Ok(msg) = rx.recv() {
        let latency_ns = now_nanos().saturating_sub(msg.created_at_ns);

        if let Some(entry) = metrics.get(&msg.topic) {
            entry.record_routed(latency_ns);
        }

        // Simulate lightweight processing
        std::hint::black_box(msg.payload[0]);
    }
}

fn metrics_reporter(metrics: Arc<DashMap<u64, Arc<RouteMetrics>>>, running: Arc<AtomicBool>) {
    let mut last_routed: HashMap<u64, u64> = HashMap::new();
    let mut last_dropped: HashMap<u64, u64> = HashMap::new();

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));

        println!("==== metrics report ====");
        for entry in metrics.iter() {
            let topic = *entry.key();
            let m = entry.value();

            let routed = m.routed.load(Ordering::Relaxed);
            let dropped = m.dropped.load(Ordering::Relaxed);
            let total_latency = m.total_latency_ns.load(Ordering::Relaxed);
            let max_latency = m.max_latency_ns.load(Ordering::Relaxed);

            let prev_routed = *last_routed.get(&topic).unwrap_or(&0);
            let prev_dropped = *last_dropped.get(&topic).unwrap_or(&0);

            let delta_routed = routed - prev_routed;
            let delta_dropped = dropped - prev_dropped;

            last_routed.insert(topic, routed);
            last_dropped.insert(topic, dropped);

            let avg_latency_ns = if routed > 0 {
                total_latency / routed
            } else {
                0
            };

            println!(
                "topic={} routed_total={} routed/s={} dropped_total={} dropped/s={} avg_latency_ns={} max_latency_ns={}",
                topic,
                routed,
                delta_routed,
                dropped,
                delta_dropped,
                avg_latency_ns,
                max_latency
            );
        }
    }
}

fn producer_loop(router: Arc<Router>, running: Arc<AtomicBool>, producer_id: usize) {
    let mut rng = rand::thread_rng();
    let mut msg_id = producer_id as u64 * 1_000_000_000;

    while running.load(Ordering::Relaxed) {
        let topic = rng.gen_range(0..1024) as u64;
        let msg = Message::new(msg_id, topic);
        router.route(msg);
        msg_id += 1;
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));

    let mut worker_senders = Vec::with_capacity(NUM_WORKERS);
    let metrics_map: Arc<DashMap<u64, Arc<RouteMetrics>>> = Arc::new(DashMap::new());

    for worker_id in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        worker_senders.push(tx);

        let metrics_clone = Arc::clone(&metrics_map);
        thread::spawn(move || worker_loop(worker_id, rx, metrics_clone));
    }

    let router = Arc::new(Router::new(worker_senders));

    // Share router metrics map with workers/reporter
    for entry in router.route_metrics.iter() {
        metrics_map.insert(*entry.key(), entry.value().clone());
    }

    // Reporter
    {
        let metrics_clone = Arc::clone(&router.route_metrics);
        let running_clone = Arc::clone(&running);
        thread::spawn(move || metrics_reporter(metrics_clone, running_clone));
    }

    // Producers
    let num_producers = 4;
    let mut producer_handles = Vec::new();
    for producer_id in 0..num_producers {
        let router_clone = Arc::clone(&router);
        let running_clone = Arc::clone(&running);
        producer_handles.push(thread::spawn(move || {
            producer_loop(router_clone, running_clone, producer_id)
        }));
    }

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for handle in producer_handles {
        let _ = handle.join();
    }

    println!("Shutting down.");
}
```

