```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_ROUTES: usize = 8;
const QUEUE_CAPACITY: usize = 262_144;
const PRODUCER_THREADS: usize = 4;
const MESSAGES_PER_PRODUCER: usize = 2_000_000;
const METRICS_INTERVAL_SECS: u64 = 1;

#[derive(Clone, Copy)]
#[repr(C)]
struct Message {
    route_key: u64,
    sequence: u64,
    created_at_nanos: u64,
    payload: [u8; 64],
}

struct RouteMetrics {
    processed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
    histogram: Mutex<Histogram<u64>>,
}

impl RouteMetrics {
    fn new() -> Self {
        Self {
            processed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
            histogram: Mutex::new(Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap()),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.processed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current_max = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current_max {
            match self.max_latency_ns.compare_exchange_weak(
                current_max,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current_max = v,
            }
        }

        if let Ok(mut hist) = self.histogram.lock() {
            let _ = hist.record(latency_ns);
        }
    }

    fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

struct Router {
    route_senders: Vec<Sender<Message>>,
    route_metrics: Vec<Arc<RouteMetrics>>,
}

impl Router {
    fn new(num_routes: usize, queue_capacity: usize) -> (Self, Vec<Receiver<Message>>) {
        let mut senders = Vec::with_capacity(num_routes);
        let mut receivers = Vec::with_capacity(num_routes);
        let mut metrics = Vec::with_capacity(num_routes);

        for _ in 0..num_routes {
            let (tx, rx) = bounded::<Message>(queue_capacity);
            senders.push(tx);
            receivers.push(rx);
            metrics.push(Arc::new(RouteMetrics::new()));
        }

        (
            Self {
                route_senders: senders,
                route_metrics: metrics,
            },
            receivers,
        )
    }

    #[inline(always)]
    fn route(&self, msg: Message) {
        let route_idx = (msg.route_key as usize) % self.route_senders.len();
        match self.route_senders[route_idx].try_send(msg) {
            Ok(_) => {}
            Err(_) => {
                self.route_metrics[route_idx].record_drop();
            }
        }
    }
}

fn now_nanos(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn start_route_workers(
    receivers: Vec<Receiver<Message>>,
    metrics: Vec<Arc<RouteMetrics>>,
    start: Instant,
    shutdown: Arc<AtomicBool>,
) -> Vec<thread::JoinHandle<()>> {
    receivers
        .into_iter()
        .enumerate()
        .map(|(route_id, rx)| {
            let route_metrics = metrics[route_id].clone();
            let shutdown_flag = shutdown.clone();

            thread::spawn(move || {
                while !shutdown_flag.load(Ordering::Relaxed) || !rx.is_empty() {
                    match rx.recv_timeout(Duration::from_millis(10)) {
                        Ok(msg) => {
                            let now = now_nanos(start);
                            let latency = now.saturating_sub(msg.created_at_nanos);

                            // Simulated processing
                            std::hint::black_box(msg.payload);

                            route_metrics.record_latency(latency);
                        }
                        Err(crossbeam::channel::RecvTimeoutError::Timeout) => continue,
                        Err(crossbeam::channel::RecvTimeoutError::Disconnected) => break,
                    }
                }
            })
        })
        .collect()
}

fn start_metrics_reporter(
    metrics: Vec<Arc<RouteMetrics>>,
    shutdown: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while !shutdown.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(METRICS_INTERVAL_SECS));

            println!("================ METRICS ================");
            for (i, m) in metrics.iter().enumerate() {
                let processed = m.processed.load(Ordering::Relaxed);
                let dropped = m.dropped.load(Ordering::Relaxed);
                let total_latency = m.total_latency_ns.load(Ordering::Relaxed);
                let max_latency = m.max_latency_ns.load(Ordering::Relaxed);

                let avg_latency = if processed > 0 {
                    total_latency / processed
                } else {
                    0
                };

                let (p50, p99, p999) = if let Ok(hist) = m.histogram.lock() {
                    (
                        hist.value_at_quantile(0.50),
                        hist.value_at_quantile(0.99),
                        hist.value_at_quantile(0.999),
                    )
                } else {
                    (0, 0, 0)
                };

                println!(
                    "route={} processed={} dropped={} avg_ns={} max_ns={} p50_ns={} p99_ns={} p999_ns={}",
                    i, processed, dropped, avg_latency, max_latency, p50, p99, p999
                );
            }
        }
    })
}

fn main() {
    let start = Instant::now();
    let shutdown = Arc::new(AtomicBool::new(false));

    let (router, receivers) = Router::new(NUM_ROUTES, QUEUE_CAPACITY);

    let worker_handles = start_route_workers(
        receivers,
        router.route_metrics.clone(),
        start,
        shutdown.clone(),
    );

    let metrics_handle = start_metrics_reporter(router.route_metrics.clone(), shutdown.clone());

    let router = Arc::new(router);

    let producer_handles: Vec<_> = (0..PRODUCER_THREADS)
        .map(|producer_id| {
            let router = router.clone();
            thread::spawn(move || {
                let mut rng = rand::thread_rng();

                for seq in 0..MESSAGES_PER_PRODUCER {
                    let route_key = rng.gen::<u64>();
                    let created_at_nanos = now_nanos(start);

                    let msg = Message {
                        route_key,
                        sequence: ((producer_id as u64) << 32) | seq as u64,
                        created_at_nanos,
                        payload: [producer_id as u8; 64],
                    };

                    router.route(msg);
                }
            })
        })
        .collect();

    for h in producer_handles {
        h.join().unwrap();
    }

    shutdown.store(true, Ordering::Relaxed);

    drop(router);

    for h in worker_handles {
        h.join().unwrap();
    }

    metrics_handle.join().unwrap();

    println!("Finished.");
}
```

