## `src/main.rs`

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const PAYLOAD_SIZE: usize = 128;
const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const DEST_QUEUE_SIZE: usize = 1_000_000;
const NUM_TOPICS: usize = 1024;
const NUM_ROUTER_WORKERS: usize = 8;
const NUM_DESTINATIONS: usize = 8;
const RUN_SECONDS: u64 = 10;

#[derive(Clone)]
struct Message {
    id: u64,
    topic: u64,
    created_at_ns: u64,
    payload: [u8; PAYLOAD_SIZE],
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn hash_topic(topic: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    hasher.finish() as usize
}

struct Metrics {
    routed_count: AtomicU64,
    dropped_count: AtomicU64,
    ingress_latency_ns_total: AtomicU64,
    end_to_end_latency_ns_total: AtomicU64,
    ingress_hist: Mutex<Histogram<u64>>,
    e2e_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed_count: AtomicU64::new(0),
            dropped_count: AtomicU64::new(0),
            ingress_latency_ns_total: AtomicU64::new(0),
            end_to_end_latency_ns_total: AtomicU64::new(0),
            ingress_hist: Mutex::new(Histogram::new(3).unwrap()),
            e2e_hist: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_ingress_latency(&self, latency_ns: u64) {
        self.ingress_latency_ns_total
            .fetch_add(latency_ns, Ordering::Relaxed);
        if let Ok(mut hist) = self.ingress_hist.lock() {
            let _ = hist.record(latency_ns);
        }
    }

    fn record_e2e_latency(&self, latency_ns: u64) {
        self.end_to_end_latency_ns_total
            .fetch_add(latency_ns, Ordering::Relaxed);
        if let Ok(mut hist) = self.e2e_hist.lock() {
            let _ = hist.record(latency_ns);
        }
    }
}

fn producer_thread(tx: Sender<Message>, running: Arc<AtomicBool>, producer_id: usize) {
    let mut rng = rand::thread_rng();
    let mut msg_id = producer_id as u64 * 1_000_000_000;

    while running.load(Ordering::Relaxed) {
        let mut payload = [0u8; PAYLOAD_SIZE];
        rng.fill(&mut payload);

        let msg = Message {
            id: msg_id,
            topic: rng.gen_range(0..NUM_TOPICS as u64),
            created_at_ns: now_ns(),
            payload,
        };

        if tx.try_send(msg).is_err() {
            // Backpressure/drop policy: drop when full
        }

        msg_id += 1;
    }
}

fn router_worker(
    ingress_rx: Receiver<Message>,
    dest_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
        match ingress_rx.recv_timeout(Duration::from_micros(50)) {
            Ok(msg) => {
                let route_start = now_ns();
                let shard = hash_topic(msg.topic) % dest_txs.len();

                let ingress_latency = route_start.saturating_sub(msg.created_at_ns);
                metrics.record_ingress_latency(ingress_latency);

                if dest_txs[shard].try_send(msg).is_ok() {
                    metrics.routed_count.fetch_add(1, Ordering::Relaxed);
                } else {
                    metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }
}

fn destination_worker(
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_micros(50)) {
            Ok(msg) => {
                // Simulate lightweight processing
                let _ = msg.payload[0];

                let done_ns = now_ns();
                let e2e_latency = done_ns.saturating_sub(msg.created_at_ns);
                metrics.record_e2e_latency(e2e_latency);
            }
            Err(_) => {}
        }
    }
}

fn metrics_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let mut last_routed = 0u64;
    let mut last_dropped = 0u64;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let routed = metrics.routed_count.load(Ordering::Relaxed);
        let dropped = metrics.dropped_count.load(Ordering::Relaxed);

        let routed_delta = routed - last_routed;
        let dropped_delta = dropped - last_dropped;

        last_routed = routed;
        last_dropped = dropped;

        let ingress_snapshot = {
            let hist = metrics.ingress_hist.lock().unwrap();
            (
                hist.value_at_quantile(0.50),
                hist.value_at_quantile(0.95),
                hist.value_at_quantile(0.99),
                hist.max(),
            )
        };

        let e2e_snapshot = {
            let hist = metrics.e2e_hist.lock().unwrap();
            (
                hist.value_at_quantile(0.50),
                hist.value_at_quantile(0.95),
                hist.value_at_quantile(0.99),
                hist.max(),
            )
        };

        println!(
            "throughput routed/s={} dropped/s={} total_routed={} total_dropped={} \
             ingress_ns p50={} p95={} p99={} max={} \
             e2e_ns p50={} p95={} p99={} max={}",
            routed_delta,
            dropped_delta,
            routed,
            dropped,
            ingress_snapshot.0,
            ingress_snapshot.1,
            ingress_snapshot.2,
            ingress_snapshot.3,
            e2e_snapshot.0,
            e2e_snapshot.1,
            e2e_snapshot.2,
            e2e_snapshot.3,
        );
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());

    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);

    let mut dest_txs = Vec::with_capacity(NUM_DESTINATIONS);
    let mut dest_rxs = Vec::with_capacity(NUM_DESTINATIONS);

    for _ in 0..NUM_DESTINATIONS {
        let (tx, rx) = bounded::<Message>(DEST_QUEUE_SIZE);
        dest_txs.push(tx);
        dest_rxs.push(rx);
    }

    let mut handles = Vec::new();

    // Producers
    let producer_count = num_cpus::get().max(4);
    for i in 0..producer_count {
        let tx = ingress_tx.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || producer_thread(tx, running, i)));
    }

    // Router workers
    for _ in 0..NUM_ROUTER_WORKERS {
        let rx = ingress_rx.clone();
        let txs = dest_txs.clone();
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || {
            router_worker(rx, txs, metrics, running)
        }));
    }

    // Destination workers
    for rx in dest_rxs {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || destination_worker(rx, metrics, running)));
    }

    // Metrics reporter
    {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || metrics_reporter(metrics, running)));
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    drop(ingress_tx);

    for handle in handles {
        let _ = handle.join();
    }

    println!("Finished.");
}
```

