# Main implementation

```rust
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

type Topic = u16;
type RouteId = u16;

#[inline(always)]
fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

#[derive(Clone, Debug)]
pub struct Message {
    pub id: u64,
    pub topic: Topic,
    pub payload: [u8; 64],
    pub ingress_ts_ns: u64,
}

impl Message {
    #[inline(always)]
    pub fn new(id: u64, topic: Topic, payload: [u8; 64]) -> Self {
        Self {
            id,
            topic,
            payload,
            ingress_ts_ns: now_nanos(),
        }
    }
}

#[derive(Default)]
pub struct RouteStats {
    pub routed: AtomicU64,
    pub dropped: AtomicU64,
    pub total_route_latency_ns: AtomicU64,
    pub total_end_to_end_latency_ns: AtomicU64,
}

pub struct RouteMetrics {
    pub route_id: RouteId,
    pub stats: Arc<RouteStats>,
    pub route_latency_hist: Mutex<Histogram<u64>>,
    pub e2e_latency_hist: Mutex<Histogram<u64>>,
}

impl RouteMetrics {
    pub fn new(route_id: RouteId) -> Self {
        Self {
            route_id,
            stats: Arc::new(RouteStats::default()),
            route_latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
            e2e_latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
        }
    }

    #[inline(always)]
    pub fn record_route_latency(&self, ns: u64) {
        self.stats.routed.fetch_add(1, Ordering::Relaxed);
        self.stats
            .total_route_latency_ns
            .fetch_add(ns, Ordering::Relaxed);
        if let Ok(mut h) = self.route_latency_hist.lock() {
            let _ = h.record(ns);
        }
    }

    #[inline(always)]
    pub fn record_drop(&self) {
        self.stats.dropped.fetch_add(1, Ordering::Relaxed);
    }

    #[inline(always)]
    pub fn record_e2e_latency(&self, ns: u64) {
        self.stats
            .total_end_to_end_latency_ns
            .fetch_add(ns, Ordering::Relaxed);
        if let Ok(mut h) = self.e2e_latency_hist.lock() {
            let _ = h.record(ns);
        }
    }
}

pub struct Router {
    ingress_tx: Sender<Message>,
    routes: Arc<HashMap<Topic, Vec<RouteId>>>,
    route_senders: Arc<HashMap<RouteId, Sender<Message>>>,
    route_metrics: Arc<HashMap<RouteId, Arc<RouteMetrics>>>,
    running: Arc<AtomicBool>,
}

impl Router {
    pub fn new(
        ingress_capacity: usize,
        route_table: HashMap<Topic, Vec<RouteId>>,
        route_capacity: usize,
    ) -> (Self, Receiver<Message>, HashMap<RouteId, Receiver<Message>>) {
        let (ingress_tx, ingress_rx) = bounded::<Message>(ingress_capacity);

        let mut route_senders = HashMap::new();
        let mut route_receivers = HashMap::new();
        let mut route_metrics = HashMap::new();

        let unique_routes: std::collections::HashSet<RouteId> = route_table
            .values()
            .flat_map(|v| v.iter().copied())
            .collect();

        for route_id in unique_routes {
            let (tx, rx) = bounded::<Message>(route_capacity);
            route_senders.insert(route_id, tx);
            route_receivers.insert(route_id, rx);
            route_metrics.insert(route_id, Arc::new(RouteMetrics::new(route_id)));
        }

        let router = Self {
            ingress_tx,
            routes: Arc::new(route_table),
            route_senders: Arc::new(route_senders),
            route_metrics: Arc::new(route_metrics),
            running: Arc::new(AtomicBool::new(true)),
        };

        (router, ingress_rx, route_receivers)
    }

    pub fn sender(&self) -> Sender<Message> {
        self.ingress_tx.clone()
    }

    pub fn metrics(&self) -> Arc<HashMap<RouteId, Arc<RouteMetrics>>> {
        self.route_metrics.clone()
    }

    pub fn start(&self, ingress_rx: Receiver<Message>) -> thread::JoinHandle<()> {
        let routes = self.routes.clone();
        let route_senders = self.route_senders.clone();
        let route_metrics = self.route_metrics.clone();
        let running = self.running.clone();

        thread::spawn(move || {
            while running.load(Ordering::Relaxed) {
                match ingress_rx.recv() {
                    Ok(msg) => {
                        let dispatch_start = now_nanos();

                        if let Some(route_ids) = routes.get(&msg.topic) {
                            for route_id in route_ids {
                                if let Some(tx) = route_senders.get(route_id) {
                                    match tx.try_send(msg.clone()) {
                                        Ok(_) => {
                                            let route_latency = now_nanos() - dispatch_start;
                                            if let Some(metrics) = route_metrics.get(route_id) {
                                                metrics.record_route_latency(route_latency);
                                            }
                                        }
                                        Err(TrySendError::Full(_)) => {
                                            if let Some(metrics) = route_metrics.get(route_id) {
                                                metrics.record_drop();
                                            }
                                        }
                                        Err(TrySendError::Disconnected(_)) => {
                                            if let Some(metrics) = route_metrics.get(route_id) {
                                                metrics.record_drop();
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
        })
    }

    pub fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

pub fn start_consumer(
    route_id: RouteId,
    rx: Receiver<Message>,
    metrics: Arc<RouteMetrics>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while let Ok(_msg) = rx.recv() {
            let done_ns = now_nanos();
            let e2e = done_ns.saturating_sub(_msg.ingress_ts_ns);
            metrics.record_e2e_latency(e2e);

            // Simulate lightweight processing
            std::hint::spin_loop();
        }

        println!("Consumer {} exiting", route_id);
    })
}

pub fn start_metrics_reporter(
    metrics_map: Arc<HashMap<RouteId, Arc<RouteMetrics>>>,
    interval: Duration,
) -> thread::JoinHandle<()> {
    thread::spawn(move || loop {
        thread::sleep(interval);

        println!("================ METRICS ================");
        for (route_id, metrics) in metrics_map.iter() {
            let routed = metrics.stats.routed.load(Ordering::Relaxed);
            let dropped = metrics.stats.dropped.load(Ordering::Relaxed);
            let total_route_ns = metrics
                .stats
                .total_route_latency_ns
                .load(Ordering::Relaxed);
            let total_e2e_ns = metrics
                .stats
                .total_end_to_end_latency_ns
                .load(Ordering::Relaxed);

            let avg_route = if routed > 0 {
                total_route_ns / routed
            } else {
                0
            };

            let avg_e2e = if routed > 0 {
                total_e2e_ns / routed
            } else {
                0
            };

            let (p50_route, p99_route) = {
                let h = metrics.route_latency_hist.lock().unwrap();
                (
                    h.value_at_quantile(0.50),
                    h.value_at_quantile(0.99),
                )
            };

            let (p50_e2e, p99_e2e) = {
                let h = metrics.e2e_latency_hist.lock().unwrap();
                (
                    h.value_at_quantile(0.50),
                    h.value_at_quantile(0.99),
                )
            };

            println!(
                "route={} routed={} dropped={} avg_route_ns={} p50_route_ns={} p99_route_ns={} avg_e2e_ns={} p50_e2e_ns={} p99_e2e_ns={}",
                route_id,
                routed,
                dropped,
                avg_route,
                p50_route,
                p99_route,
                avg_e2e,
                p50_e2e,
                p99_e2e
            );
        }
    })
}

fn main() {
    let mut route_table = HashMap::new();
    route_table.insert(1, vec![10, 11]);
    route_table.insert(2, vec![11, 12]);
    route_table.insert(3, vec![12]);

    let (router, ingress_rx, route_receivers) = Router::new(
        1_000_000, // ingress queue
        route_table,
        100_000,   // per-route queue
    );

    let router_handle = router.start(ingress_rx);

    let metrics_map = router.metrics();

    let mut consumer_handles = Vec::new();
    for (route_id, rx) in route_receivers {
        let metrics = metrics_map.get(&route_id).unwrap().clone();
        consumer_handles.push(start_consumer(route_id, rx, metrics));
    }

    let _reporter = start_metrics_reporter(metrics_map.clone(), Duration::from_secs(2));

    let producer_count = 4;
    let messages_per_producer = 2_000_000;

    let mut producers = Vec::new();
    for p in 0..producer_count {
        let tx = router.sender();
        producers.push(thread::spawn(move || {
            let mut rng = rand::thread_rng();
            for i in 0..messages_per_producer {
                let topic = match rng.gen_range(0..3) {
                    0 => 1,
                    1 => 2,
                    _ => 3,
                };

                let mut payload = [0u8; 64];
                payload[0] = (i & 0xFF) as u8;
                payload[1] = p as u8;

                let msg = Message::new((p as u64) << 32 | i as u64, topic, payload);

                let _ = tx.send(msg);
            }
        }));
    }

    for p in producers {
        p.join().unwrap();
    }

    drop(router.sender());

    thread::sleep(Duration::from_secs(5));
    router.stop();

    let _ = router_handle.join();
    for h in consumer_handles {
        let _ = h.join();
    }
}
