# Java Implementation

```java
import java.util.Arrays;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

/**
 * High-frequency in-memory messaging router with:
 * - topic-based routing
 * - async worker pool
 * - latency monitoring
 * - periodic metrics reporting
 *
 * This is a high-performance skeleton, not a full distributed broker.
 */
public class HighFrequencyMessagingSystem {

    public static void main(String[] args) throws Exception {
        RouterConfig config = new RouterConfig(
                4,                  // worker threads
                1 << 20,            // queue capacity per worker
                1000                // metrics print interval ms
        );

        MessageRouter router = new MessageRouter(config);

        router.subscribe("orders", msg -> {
            // Simulate fast processing
            blackhole(msg.payload());
        });

        router.subscribe("orders", msg -> {
            blackhole(msg.payload());
        });

        router.start();

        int producerThreads = 4;
        int messagesPerProducer = 2_000_000;

        ExecutorService producers = Executors.newFixedThreadPool(producerThreads);
        CountDownLatch latch = new CountDownLatch(producerThreads);

        long start = System.nanoTime();

        for (int i = 0; i < producerThreads; i++) {
            final int producerId = i;
            producers.submit(() -> {
                try {
                    for (int j = 0; j < messagesPerProducer; j++) {
                        byte[] payload = ("producer-" + producerId + "-msg-" + j).getBytes();
                        router.publish(new Message("orders", payload, System.nanoTime()));
                    }
                } finally {
                    latch.countDown();
                }
            });
        }

        latch.await();
        long publishEnd = System.nanoTime();

        System.out.println("Publishing complete in ms: " + ((publishEnd - start) / 1_000_000));

        Thread.sleep(5000);

        producers.shutdown();
        router.shutdown();
    }

    private static volatile int sink;
    private static void blackhole(byte[] data) {
        sink ^= Arrays.hashCode(data);
    }

    // ----------------------------
    // Message
    // ----------------------------
    public record Message(String topic, byte[] payload, long createdNanos) {
        public Message {
            Objects.requireNonNull(topic, "topic");
            Objects.requireNonNull(payload, "payload");
        }
    }

    // ----------------------------
    // Config
    // ----------------------------
    public record RouterConfig(
            int workerThreads,
            int queueCapacityPerWorker,
            long metricsIntervalMillis
    ) {
        public RouterConfig {
            if (workerThreads <= 0) throw new IllegalArgumentException("workerThreads must be > 0");
            if (queueCapacityPerWorker <= 0) throw new IllegalArgumentException("queueCapacityPerWorker must be > 0");
            if (metricsIntervalMillis <= 0) throw new IllegalArgumentException("metricsIntervalMillis must be > 0");
        }
    }

    // ----------------------------
    // Router
    // ----------------------------
    public static final class MessageRouter {
        private final RouterConfig config;
        private final ConcurrentHashMap<String, CopyOnWriteArrayList<Consumer<Message>>> subscribers = new ConcurrentHashMap<>();
        private final Worker[] workers;
        private final AtomicInteger rr = new AtomicInteger(0);
        private final ScheduledExecutorService metricsScheduler;
        private final RouterMetrics metrics = new RouterMetrics();
        private volatile boolean running = false;

        public MessageRouter(RouterConfig config) {
            this.config = config;
            this.workers = new Worker[config.workerThreads()];
            for (int i = 0; i < workers.length; i++) {
                workers[i] = new Worker(
                        "router-worker-" + i,
                        config.queueCapacityPerWorker(),
                        subscribers,
                        metrics
                );
            }
            this.metricsScheduler = Executors.newSingleThreadScheduledExecutor(r -> {
                Thread t = new Thread(r, "metrics-reporter");
                t.setDaemon(true);
                return t;
            });
        }

        public void start() {
            if (running) return;
            running = true;

            for (Worker worker : workers) {
                worker.start();
            }

            metricsScheduler.scheduleAtFixedRate(
                    this::printMetrics,
                    config.metricsIntervalMillis(),
                    config.metricsIntervalMillis(),
                    TimeUnit.MILLISECONDS
            );
        }

        public void shutdown() {
            running = false;
            for (Worker worker : workers) {
                worker.shutdown();
            }
            metricsScheduler.shutdownNow();
        }

        public void subscribe(String topic, Consumer<Message> handler) {
            subscribers.computeIfAbsent(topic, t -> new CopyOnWriteArrayList<>()).add(handler);
        }

        public boolean publish(Message message) {
            if (!running) {
                throw new IllegalStateException("Router not started");
            }

            int idx = Math.floorMod(rr.getAndIncrement(), workers.length);
            boolean offered = workers[idx].offer(message);
            if (!offered) {
                metrics.droppedMessages.increment();
            } else {
                metrics.publishedMessages.increment();
            }
            return offered;
        }

        private void printMetrics() {
            long published = metrics.publishedMessages.sum();
            long routed = metrics.routedMessages.sum();
            long dropped = metrics.droppedMessages.sum();
            long processed = metrics.processedMessages.sum();
            long errors = metrics.handlerErrors.sum();

            LatencySnapshot snapshot = metrics.latency.snapshotAndReset();

            System.out.printf(
                    "[METRICS] published=%d routed=%d processed=%d dropped=%d errors=%d " +
                    "latency(us): avg=%.2f p50=%d p95=%d p99=%d max=%d%n",
                    published,
                    routed,
                    processed,
                    dropped,
                    errors,
                    snapshot.avgMicros(),
                    snapshot.p50Micros(),
                    snapshot.p95Micros(),
                    snapshot.p99Micros(),
                    snapshot.maxMicros()
            );
        }
    }

    // ----------------------------
    // Worker
    // ----------------------------
    static final class Worker implements Runnable {
        private final String name;
        private final ArrayBlockingQueue<Message> queue;
        private final Map<String, CopyOnWriteArrayList<Consumer<Message>>> subscribers;
        private final RouterMetrics metrics;
        private final Thread thread;
        private volatile boolean running = true;

        Worker(
                String name,
                int capacity,
                Map<String, CopyOnWriteArrayList<Consumer<Message>>> subscribers,
                RouterMetrics metrics
        ) {
            this.name = name;
            this.queue = new ArrayBlockingQueue<>(capacity);
            this.subscribers = subscribers;
            this.metrics = metrics;
            this.thread = new Thread(this, name);
            this.thread.setDaemon(true);
        }

        void start() {
            thread.start();
        }

        boolean offer(Message message) {
            return queue.offer(message);
        }

        void shutdown() {
            running = false;
            thread.interrupt();
        }

        @Override
        public void run() {
            while (running) {
                try {
                    Message msg = queue.poll(1, TimeUnit.MILLISECONDS);
                    if (msg == null) {
                        continue;
                    }

                    CopyOnWriteArrayList<Consumer<Message>> handlers = subscribers.get(msg.topic());
                    if (handlers == null || handlers.isEmpty()) {
                        continue;
                    }

                    metrics.routedMessages.increment();

                    long now = System.nanoTime();
                    long latencyNanos = now - msg.createdNanos();
                    metrics.latency.record(latencyNanos);

                    for (Consumer<Message> handler : handlers) {
                        try {
                            handler.accept(msg);
                            metrics.processedMessages.increment();
                        } catch (Exception e) {
                            metrics.handlerErrors.increment();
                        }
                    }
                } catch (InterruptedException e) {
                    if (!running) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                } catch (Exception e) {
                    metrics.workerErrors.increment();
                }
            }
        }
    }

    // ----------------------------
    // Metrics
    // ----------------------------
    static final class RouterMetrics {
        final LongAdder publishedMessages = new LongAdder();
        final LongAdder routedMessages = new LongAdder();
        final LongAdder processedMessages = new LongAdder();
        final LongAdder droppedMessages = new LongAdder();
        final LongAdder handlerErrors = new LongAdder();
        final LongAdder workerErrors = new LongAdder();
        final LatencyMonitor latency = new LatencyMonitor();
    }

    // ----------------------------
    // Latency Monitor
    // ----------------------------
    static final class LatencyMonitor {
        // Buckets in microseconds for rough percentile estimation
        // 0..999 us, then overflow bucket
        private final AtomicLongArray buckets = new AtomicLongArray(1001);
        private final LongAdder totalMicros = new LongAdder();
        private final LongAdder count = new LongAdder();
        private final AtomicLong maxMicros = new AtomicLong();

        void record(long latencyNanos) {
            long micros = latencyNanos / 1_000;
            int bucket = (int) Math.min(micros, 1000);

            buckets.incrementAndGet(bucket);
            totalMicros.add(micros);
            count.increment();

            long prev;
            do {
                prev = maxMicros.get();
                if (micros <= prev) break;
            } while (!maxMicros.compareAndSet(prev, micros));
        }

        LatencySnapshot snapshotAndReset() {
            long[] snapshot = new long[1001];
            long totalCount = count.sumThenReset();
            long total = totalMicros.sumThenReset();
            long max = maxMicros.getAndSet(0);

            for (int i = 0; i < snapshot.length; i++) {
                snapshot[i] = buckets.getAndSet(i, 0);
            }

            if (totalCount == 0) {
                return new LatencySnapshot(0.0, 0, 0, 0, 0);
            }

            long p50 = percentile(snapshot, totalCount, 0.50);
            long p95 = percentile(snapshot, totalCount, 0.95);
            long p99 = percentile(snapshot, totalCount, 0.99);
            double avg = (double) total / totalCount;

            return new LatencySnapshot(avg, p50, p95, p99, max);
        }

        private long percentile(long[] buckets, long totalCount, double percentile) {
            long threshold = (long) Math.ceil(totalCount * percentile);
            long cumulative = 0;
            for (int i = 0; i < buckets.length; i++) {
                cumulative += buckets[i];
                if (cumulative >= threshold) {
                    return i;
                }
            }
            return buckets.length - 1;
        }
    }

    public record LatencySnapshot(
            double avgMicros,
            long p50Micros,
            long p95Micros,
            long p99Micros,
            long maxMicros
    ) {}
}
```

