```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const WORKER_QUEUE_SIZE: usize = 1024 * 64;
const SUBSCRIBER_QUEUE_SIZE: usize = 1024 * 64;
const NUM_WORKERS: usize = 8;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: String,
    payload: Vec<u8>,
    created_ns: u64,
}

#[derive(Clone)]
struct DeliveredMessage {
    message: Message,
    routed_ns: u64,
    delivered_ns: u64,
}

type SubscriberId = u64;
type SubscriberSender = Sender<DeliveredMessage>;

#[derive(Default)]
struct Metrics {
    ingress_count: AtomicU64,
    routed_count: AtomicU64,
    delivered_count: AtomicU64,
    dropped_count: AtomicU64,
}

struct LatencyMetrics {
    end_to_end: Mutex<Histogram<u64>>,
    routing: Mutex<Histogram<u64>>,
}

impl LatencyMetrics {
    fn new() -> Self {
        Self {
            end_to_end: Mutex::new(Histogram::new(3).unwrap()),
            routing: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_routing(&self, nanos: u64) {
        if let Ok(mut h) = self.routing.lock() {
            let _ = h.record(nanos);
        }
    }

    fn record_end_to_end(&self, nanos: u64) {
        if let Ok(mut h) = self.end_to_end.lock() {
            let _ = h.record(nanos);
        }
    }

    fn snapshot_and_reset(&self) -> (Histogram<u64>, Histogram<u64>) {
        let mut routing = self.routing.lock().unwrap();
        let mut end_to_end = self.end_to_end.lock().unwrap();

        let routing_snapshot = routing.clone();
        let end_snapshot = end_to_end.clone();

        *routing = Histogram::new(3).unwrap();
        *end_to_end = Histogram::new(3).unwrap();

        (routing_snapshot, end_snapshot)
    }
}

struct Broker {
    worker_senders: Vec<Sender<Message>>,
    subscribers: Arc<DashMap<String, Vec<(SubscriberId, SubscriberSender)>>>,
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
    running: Arc<AtomicBool>,
}

impl Broker {
    fn new(num_workers: usize) -> Self {
        let subscribers = Arc::new(DashMap::new());
        let metrics = Arc::new(Metrics::default());
        let latency = Arc::new(LatencyMetrics::new());
        let running = Arc::new(AtomicBool::new(true));

        let mut worker_senders = Vec::with_capacity(num_workers);

        for worker_id in 0..num_workers {
            let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
            worker_senders.push(tx);

            let subscribers_clone = Arc::clone(&subscribers);
            let metrics_clone = Arc::clone(&metrics);
            let latency_clone = Arc::clone(&latency);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name(format!("worker-{worker_id}"))
                .spawn(move || {
                    worker_loop(
                        worker_id,
                        rx,
                        subscribers_clone,
                        metrics_clone,
                        latency_clone,
                        running_clone,
                    );
                })
                .expect("failed to spawn worker");
        }

        Self {
            worker_senders,
            subscribers,
            metrics,
            latency,
            running,
        }
    }

    fn subscribe(&self, topic: &str, subscriber_id: SubscriberId) -> Receiver<DeliveredMessage> {
        let (tx, rx) = bounded::<DeliveredMessage>(SUBSCRIBER_QUEUE_SIZE);

        self.subscribers
            .entry(topic.to_string())
            .and_modify(|subs| subs.push((subscriber_id, tx.clone())))
            .or_insert_with(|| vec![(subscriber_id, tx)]);

        rx
    }

    fn publish(&self, message: Message) -> Result<(), &'static str> {
        self.metrics.ingress_count.fetch_add(1, Ordering::Relaxed);

        let worker_idx = shard_for(&message.topic, self.worker_senders.len());
        match self.worker_senders[worker_idx].try_send(message) {
            Ok(_) => Ok(()),
            Err(_) => {
                self.metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
                Err("worker queue full")
            }
        }
    }

    fn start_metrics_reporter(&self) {
        let metrics = Arc::clone(&self.metrics);
        let latency = Arc::clone(&self.latency);
        let running = Arc::clone(&self.running);

        thread::spawn(move || {
            let mut last_ingress = 0;
            let mut last_routed = 0;
            let mut last_delivered = 0;
            let mut last_dropped = 0;

            while running.load(Ordering::Relaxed) {
                thread::sleep(Duration::from_secs(1));

                let ingress = metrics.ingress_count.load(Ordering::Relaxed);
                let routed = metrics.routed_count.load(Ordering::Relaxed);
                let delivered = metrics.delivered_count.load(Ordering::Relaxed);
                let dropped = metrics.dropped_count.load(Ordering::Relaxed);

                let ingress_rate = ingress - last_ingress;
                let routed_rate = routed - last_routed;
                let delivered_rate = delivered - last_delivered;
                let dropped_rate = dropped - last_dropped;

                last_ingress = ingress;
                last_routed = routed;
                last_delivered = delivered;
                last_dropped = dropped;

                let (routing_hist, e2e_hist) = latency.snapshot_and_reset();

                println!("=== metrics ===");
                println!(
                    "ingress/s={} routed/s={} delivered/s={} dropped/s={}",
                    ingress_rate, routed_rate, delivered_rate, dropped_rate
                );

                if routing_hist.len() > 0 {
                    println!(
                        "routing latency ns: p50={} p95={} p99={} max={}",
                        routing_hist.value_at_quantile(0.50),
                        routing_hist.value_at_quantile(0.95),
                        routing_hist.value_at_quantile(0.99),
                        routing_hist.max()
                    );
                }

                if e2e_hist.len() > 0 {
                    println!(
                        "end-to-end latency ns: p50={} p95={} p99={} max={}",
                        e2e_hist.value_at_quantile(0.50),
                        e2e_hist.value_at_quantile(0.95),
                        e2e_hist.value_at_quantile(0.99),
                        e2e_hist.max()
                    );
                }
            }
        });
    }

    fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn worker_loop(
    _worker_id: usize,
    rx: Receiver<Message>,
    subscribers: Arc<DashMap<String, Vec<(SubscriberId, SubscriberSender)>>>,
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(msg) => {
                let routed_ns = now_ns();
                metrics.routed_count.fetch_add(1, Ordering::Relaxed);
                latency.record_routing(routed_ns.saturating_sub(msg.created_ns));

                if let Some(subs) = subscribers.get(&msg.topic) {
                    for (_, sub_tx) in subs.iter() {
                        let delivered_ns = now_ns();
                        let delivered = DeliveredMessage {
                            message: msg.clone(),
                            routed_ns,
                            delivered_ns,
                        };

                        if sub_tx.try_send(delivered).is_ok() {
                            metrics.delivered_count.fetch_add(1, Ordering::Relaxed);
                            latency.record_end_to_end(delivered_ns.saturating_sub(msg.created_ns));
                        } else {
                            metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn shard_for(topic: &str, num_workers: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % num_workers
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn main() {
    let broker = Arc::new(Broker::new(NUM_WORKERS));
    broker.start_metrics_reporter();

    let sub_rx = broker.subscribe("orders", 1);

    let subscriber_handle = {
        thread::spawn(move || {
            while let Ok(delivered) = sub_rx.recv() {
                let _ = delivered.message.id;
            }
        })
    };

    let producer_threads = num_cpus::get();
    let messages_per_thread = 500_000;

    let mut handles = Vec::new();

    for producer_id in 0..producer_threads {
        let broker_clone = Arc::clone(&broker);

        let handle = thread::spawn(move || {
            for i in 0..messages_per_thread {
                let msg = Message {
                    id: ((producer_id as u64) << 32) | i as u64,
                    topic: "orders".to_string(),
                    payload: vec![0u8; 128],
                    created_ns: now_ns(),
                };

                let _ = broker_clone.publish(msg);
            }
        });

        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    thread::sleep(Duration::from_secs(5));
    broker.shutdown();
    let _ = subscriber_handle.join();
}
```

