## `src/main.rs`

```rust
use bytes::Bytes;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

type Topic = String;
type SubscriberId = u64;

#[derive(Clone)]
struct Message {
    topic: Topic,
    payload: Bytes,
    created_at: Instant,
    sequence: u64,
}

#[derive(Clone)]
struct DeliveredMessage {
    subscriber_id: SubscriberId,
    topic: Topic,
    payload: Bytes,
    sequence: u64,
    latency_micros: u64,
}

struct Subscriber {
    id: SubscriberId,
    tx: Sender<DeliveredMessage>,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    delivery_errors: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            delivery_errors: AtomicU64::new(0),
            latency_hist: Mutex::new(Histogram::new_with_bounds(1, 60_000_000, 3).unwrap()),
        }
    }

    fn record_latency(&self, micros: u64) {
        if let Ok(mut hist) = self.latency_hist.lock() {
            let _ = hist.record(micros);
        }
    }
}

struct Router {
    shard_senders: Vec<Sender<Message>>,
    subscribers: Arc<DashMap<Topic, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
}

impl Router {
    fn new(num_shards: usize, shard_queue_size: usize) -> Self {
        let subscribers = Arc::new(DashMap::<Topic, Vec<Subscriber>>::new());
        let metrics = Arc::new(Metrics::new());
        let running = Arc::new(AtomicBool::new(true));

        let mut shard_senders = Vec::with_capacity(num_shards);

        for shard_id in 0..num_shards {
            let (tx, rx) = bounded::<Message>(shard_queue_size);
            shard_senders.push(tx);

            let subs = Arc::clone(&subscribers);
            let metrics_clone = Arc::clone(&metrics);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name(format!("router-shard-{shard_id}"))
                .spawn(move || {
                    shard_worker(rx, subs, metrics_clone, running_clone);
                })
                .expect("failed to spawn shard worker");
        }

        Self {
            shard_senders,
            subscribers,
            metrics,
            running,
        }
    }

    fn subscribe(&self, topic: impl Into<String>, subscriber: Subscriber) {
        let topic = topic.into();
        self.subscribers
            .entry(topic)
            .and_modify(|subs| subs.push(subscriber.clone()))
            .or_insert_with(|| vec![subscriber]);
    }

    fn publish(&self, msg: Message) -> Result<(), &'static str> {
        self.metrics.received.fetch_add(1, Ordering::Relaxed);

        let shard = self.pick_shard(&msg.topic);
        match self.shard_senders[shard].try_send(msg) {
            Ok(_) => Ok(()),
            Err(_) => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                Err("queue full")
            }
        }
    }

    fn pick_shard(&self, topic: &str) -> usize {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        topic.hash(&mut hasher);
        (hasher.finish() as usize) % self.shard_senders.len()
    }

    fn metrics_reporter(&self, interval: Duration) {
        let metrics = Arc::clone(&self.metrics);
        let running = Arc::clone(&self.running);

        thread::spawn(move || {
            let mut last_received = 0;
            let mut last_routed = 0;
            let mut last_dropped = 0;

            while running.load(Ordering::Relaxed) {
                thread::sleep(interval);

                let received = metrics.received.load(Ordering::Relaxed);
                let routed = metrics.routed.load(Ordering::Relaxed);
                let dropped = metrics.dropped.load(Ordering::Relaxed);
                let delivery_errors = metrics.delivery_errors.load(Ordering::Relaxed);

                let delta_received = received - last_received;
                let delta_routed = routed - last_routed;
                let delta_dropped = dropped - last_dropped;

                last_received = received;
                last_routed = routed;
                last_dropped = dropped;

                let hist_snapshot = {
                    let hist = metrics.latency_hist.lock().unwrap();
                    hist.clone()
                };

                println!(
                    "[metrics] recv/s={} routed/s={} dropped/s={} total_delivery_errors={} p50={}us p95={}us p99={}us max={}us",
                    delta_received / interval.as_secs().max(1),
                    delta_routed / interval.as_secs().max(1),
                    delta_dropped / interval.as_secs().max(1),
                    delivery_errors,
                    hist_snapshot.value_at_quantile(0.50),
                    hist_snapshot.value_at_quantile(0.95),
                    hist_snapshot.value_at_quantile(0.99),
                    hist_snapshot.max()
                );
            }
        });
    }

    fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn shard_worker(
    rx: Receiver<Message>,
    subscribers: Arc<DashMap<Topic, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(msg) => {
                if let Some(subs_ref) = subscribers.get(&msg.topic) {
                    let subs = subs_ref.clone();
                    let now = Instant::now();
                    let latency = now.duration_since(msg.created_at).as_micros() as u64;

                    for sub in subs.iter() {
                        let delivered = DeliveredMessage {
                            subscriber_id: sub.id,
                            topic: msg.topic.clone(),
                            payload: msg.payload.clone(),
                            sequence: msg.sequence,
                            latency_micros: latency,
                        };

                        if sub.tx.try_send(delivered).is_ok() {
                            metrics.routed.fetch_add(1, Ordering::Relaxed);
                        } else {
                            metrics.delivery_errors.fetch_add(1, Ordering::Relaxed);
                        }
                    }

                    metrics.record_latency(latency);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn spawn_subscriber(id: SubscriberId) -> Subscriber {
    let (tx, rx) = bounded::<DeliveredMessage>(100_000);

    thread::Builder::new()
        .name(format!("subscriber-{id}"))
        .spawn(move || {
            let mut processed = 0u64;
            let mut last = Instant::now();

            while let Ok(_msg) = rx.recv() {
                processed += 1;

                if last.elapsed() >= Duration::from_secs(1) {
                    println!("[subscriber {id}] processed/s={processed}");
                    processed = 0;
                    last = Instant::now();
                }
            }
        })
        .expect("failed to spawn subscriber");

    Subscriber { id, tx }
}

fn main() {
    let num_shards = num_cpus::get().max(4);
    let router = Arc::new(Router::new(num_shards, 1_000_000));

    router.metrics_reporter(Duration::from_secs(1));

    for i in 0..8 {
        router.subscribe("orders", spawn_subscriber(i));
    }

    let publisher_threads = 4;
    let messages_per_thread = 2_000_000u64;

    let mut handles = Vec::new();

    for t in 0..publisher_threads {
        let router_clone = Arc::clone(&router);
        let handle = thread::spawn(move || {
            let mut rng = rand::thread_rng();

            for seq in 0..messages_per_thread {
                let payload_size = 128;
                let payload: Vec<u8> = (0..payload_size).map(|_| rng.gen()).collect();

                let msg = Message {
                    topic: "orders".to_string(),
                    payload: Bytes::from(payload),
                    created_at: Instant::now(),
                    sequence: (t as u64) << 32 | seq,
                };

                let _ = router_clone.publish(msg);
            }
        });

        handles.push(handle);
    }

    let start = Instant::now();

    for h in handles {
        h.join().unwrap();
    }

    let elapsed = start.elapsed();
    println!("Publishing completed in {:?}", elapsed);

    thread::sleep(Duration::from_secs(5));
    router.shutdown();
}
```

