# 7. Example of a more optimized worker loop

Here is a batch-oriented worker sketch:

```rust
fn shard_worker_batched(
    rx: Receiver<Message>,
    subscribers: Arc<DashMap<Topic, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    let mut batch = Vec::with_capacity(1024);

    while running.load(Ordering::Relaxed) {
        batch.clear();

        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(msg) => batch.push(msg),
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }

        while let Ok(msg) = rx.try_recv() {
            batch.push(msg);
            if batch.len() >= 1024 {
                break;
            }
        }

        let now = Instant::now();

        for msg in &batch {
            if let Some(subs_ref) = subscribers.get(&msg.topic) {
                let latency = now.duration_since(msg.created_at).as_micros() as u64;

                for sub in subs_ref.iter() {
                    let delivered = DeliveredMessage {
                        subscriber_id: sub.id,
                        topic: msg.topic.clone(),
                        payload: msg.payload.clone(),
                        sequence: msg.sequence,
                        latency_micros: latency,
                    };

                    if sub.tx.try_send(delivered).is_ok() {
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    } else {
                        metrics.delivery_errors.fetch_add(1, Ordering::Relaxed);
                    }
                }

                metrics.record_latency(latency);
            }
        }
    }
}
```

