type LatencyBuckets struct {
	lt10us   atomic.Uint64
	lt50us   atomic.Uint64
	lt100us  atomic.Uint64
	lt500us  atomic.Uint64
	lt1ms    atomic.Uint64
	lt5ms    atomic.Uint64
	lt10ms   atomic.Uint64
	lt50ms   atomic.Uint64
	ge50ms   atomic.Uint64
}

func (l *LatencyBuckets) Observe(d time.Duration) {
	switch {
	case d < 10*time.Microsecond:
		l.lt10us.Add(1)
	case d < 50*time.Microsecond:
		l.lt50us.Add(1)
	case d < 100*time.Microsecond:
		l.lt100us.Add(1)
	case d < 500*time.Microsecond:
		l.lt500us.Add(1)
	case d < 1*time.Millisecond:
		l.lt1ms.Add(1)
	case d < 5*time.Millisecond:
		l.lt5ms.Add(1)
	case d < 10*time.Millisecond:
		l.lt10ms.Add(1)
	case d < 50*time.Millisecond:
		l.lt50ms.Add(1)
	default:
		l.ge50ms.Add(1)
	}
}

func (l *LatencyBuckets) Snapshot() map[string]uint64 {
	return map[string]uint64{
		"lt_10us":  l.lt10us.Load(),
		"lt_50us":  l.lt50us.Load(),
		"lt_100us": l.lt100us.Load(),
		"lt_500us": l.lt500us.Load(),
		"lt_1ms":   l.lt1ms.Load(),
		"lt_5ms":   l.lt5ms.Load(),
		"lt_10ms":  l.lt10ms.Load(),
		"lt_50ms":  l.lt50ms.Load(),
		"ge_50ms":  l.ge50ms.Load(),
	}
}

type TopicMetrics struct {
	Received atomic.Uint64
	Dropped  atomic.Uint64
}

type Metrics struct {
	ReceivedMessages atomic.Uint64
	RoutedMessages   atomic.Uint64
	DroppedMessages  atomic.Uint64

	ProcessingLatency LatencyBuckets
	EndToEndLatency   LatencyBuckets

	topMu        sync.RWMutex
	TopicCounter map[string]*TopicMetrics
}

func NewMetrics() *Metrics {
	return &Metrics{
		TopicCounter: make(map[string]*TopicMetrics),
	}
}

func (m *Metrics) topic(topic string) *TopicMetrics {
	m.topMu.RLock()
	tm, ok := m.TopicCounter[topic]
	m.topMu.RUnlock()
	if ok {
		return tm
	}

	m.topMu.Lock()
	defer m.topMu.Unlock()
	tm, ok = m.TopicCounter[topic]
	if ok {
		return tm
	}
	tm = &TopicMetrics{}
	m.TopicCounter[topic] = tm
	return tm
}

func (m *Metrics) IncReceived(topic string) {
	m.ReceivedMessages.Add(1)
	m.topic(topic).Received.Add(1)
}

func (m *Metrics) IncDropped(topic string) {
	m.DroppedMessages.Add(1)
	m.topic(topic).Dropped.Add(1)
}

func (m *Metrics) IncRouted() {
	m.RoutedMessages.Add(1)
}

func (m *Metrics) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	resp := map[string]any{
		"received_messages": m.ReceivedMessages.Load(),
		"routed_messages":   m.RoutedMessages.Load(),
		"dropped_messages":  m.DroppedMessages.Load(),
		"processing_latency": m.ProcessingLatency.Snapshot(),
		"end_to_end_latency": m.EndToEndLatency.Snapshot(),
		"topics":             map[string]any{},
	}

	topics := make(map[string]any)
	m.topMu.RLock()
	for k, v := range m.TopicCounter {
		topics[k] = map[string]uint64{
			"received": v.Received.Load(),
			"dropped":  v.Dropped.Load(),
		}
	}
	m.topMu.RUnlock()
	resp["topics"] = topics

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}
