# `router/router.go`

```go
package router

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"time"
)

var ErrRouterClosed = errors.New("router closed")
var ErrBackpressure = errors.New("router backpressure")

type Handler func(Message)

type subscriber struct {
	name string
	ch   chan Message
}

type shard struct {
	ch chan Message
}

type Router struct {
	shards      []shard
	subscribers map[string][]subscriber
	subMu       sync.RWMutex
	metrics     *Metrics
	wg          sync.WaitGroup
	closed      chan struct{}
}

func NewRouter(numShards int, shardBuffer int) *Router {
	if numShards <= 0 {
		numShards = runtime.NumCPU() * 2
	}
	if shardBuffer <= 0 {
		shardBuffer = 65536
	}

	r := &Router{
		shards:      make([]shard, numShards),
		subscribers: make(map[string][]subscriber),
		metrics:     NewMetrics(),
		closed:      make(chan struct{}),
	}

	for i := range r.shards {
		r.shards[i] = shard{
			ch: make(chan Message, shardBuffer),
		}
		r.wg.Add(1)
		go r.runShard(i)
	}

	return r
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}

func (r *Router) Subscribe(topic, name string, buffer int, handler Handler) {
	if buffer <= 0 {
		buffer = 4096
	}
	sub := subscriber{
		name: name,
		ch:   make(chan Message, buffer),
	}

	r.subMu.Lock()
	r.subscribers[topic] = append(r.subscribers[topic], sub)
	r.subMu.Unlock()

	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		for msg := range sub.ch {
			handler(msg)
		}
	}()
}

func (r *Router) Publish(msg Message) error {
	select {
	case <-r.closed:
		return ErrRouterClosed
	default:
	}

	r.metrics.IncReceived(msg.Topic)

	idx := int(hashKey(msg.Key) % uint64(len(r.shards)))
	select {
	case r.shards[idx].ch <- msg:
		return nil
	default:
		r.metrics.IncDropped(msg.Topic)
		return ErrBackpressure
	}
}

func (r *Router) runShard(idx int) {
	defer r.wg.Done()

	for {
		select {
		case <-r.closed:
			return
		case msg := <-r.shards[idx].ch:
			start := time.Now()

			r.subMu.RLock()
			subs := r.subscribers[msg.Topic]
			r.subMu.RUnlock()

			for _, sub := range subs {
				select {
				case sub.ch <- msg:
					r.metrics.IncRouted()
				default:
					r.metrics.IncDropped(msg.Topic)
				}
			}

			r.metrics.ProcessingLatency.Observe(time.Since(start))
			r.metrics.EndToEndLatency.Observe(time.Since(msg.CreatedAt))
		}
	}
}

func (r *Router) Close() {
	select {
	case <-r.closed:
		return
	default:
		close(r.closed)
	}

	for _, s := range r.shards {
		close(s.ch)
	}

	r.subMu.Lock()
	for _, subs := range r.subscribers {
		for _, sub := range subs {
			close(sub.ch)
		}
	}
	r.subMu.Unlock()

	r.wg.Wait()
}

func hashKey(k uint64) uint64 {
	h := fnv.New64a()
	var b [8]byte
	b[0] = byte(k)
	b[1] = byte(k >> 8)
	b[2] = byte(k >> 16)
	b[3] = byte(k >> 24)
	b[4] = byte(k >> 32)
	b[5] = byte(k >> 40)
	b[6] = byte(k >> 48)
	b[7] = byte(k >> 56)
	_, _ = h.Write(b[:])
	return h.Sum64()
}
