package router

import (
	"sync/atomic"
	"time"
)

type Metrics struct {
	Published uint64
	Routed    uint64
	Dropped    uint64
	Delivered uint64
	Rejected  uint64

	TotalRouteLatencyNanos uint64
	MaxRouteLatencyNanos   uint64

	TotalEndToEndLatencyNanos uint64
	MaxEndToEndLatencyNanos   uint64

	SubscriberQueueFull uint64
}

func (m *Metrics) IncPublished() {
	atomic.AddUint64(&m.Published, 1)
}

func (m *Metrics) IncRouted() {
	atomic.AddUint64(&m.Routed, 1)
}

func (m *Metrics) IncDropped() {
	atomic.AddUint64(&m.Dropped, 1)
}

func (m *Metrics) IncDelivered() {
	atomic.AddUint64(&m.Delivered, 1)
}

func (m *Metrics) IncRejected() {
	atomic.AddUint64(&m.Rejected, 1)
}

func (m *Metrics) IncSubscriberQueueFull() {
	atomic.AddUint64(&m.SubscriberQueueFull, 1)
}

func (m *Metrics) ObserveRouteLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.TotalRouteLatencyNanos, ns)
	updateMax(&m.MaxRouteLatencyNanos, ns)
}

func (m *Metrics) ObserveEndToEndLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.TotalEndToEndLatencyNanos, ns)
	updateMax(&m.MaxEndToEndLatencyNanos, ns)
}

func updateMax(addr *uint64, val uint64) {
	for {
		cur := atomic.LoadUint64(addr)
		if val <= cur {
			return
		}
		if atomic.CompareAndSwapUint64(addr, cur, val) {
			return
		}
	}
}

type Snapshot struct {
	Published uint64
	Routed    uint64
	Dropped   uint64
	Delivered uint64
	Rejected  uint64

	SubscriberQueueFull uint64

	AvgRouteLatency time.Duration
	MaxRouteLatency time.Duration

	AvgEndToEndLatency time.Duration
	MaxEndToEndLatency time.Duration
}

func (m *Metrics) Snapshot() Snapshot {
	published := atomic.LoadUint64(&m.Published)
	routed := atomic.LoadUint64(&m.Routed)
	delivered := atomic.LoadUint64(&m.Delivered)

	totalRoute := atomic.LoadUint64(&m.TotalRouteLatencyNanos)
	maxRoute := atomic.LoadUint64(&m.MaxRouteLatencyNanos)

	totalE2E := atomic.LoadUint64(&m.TotalEndToEndLatencyNanos)
	maxE2E := atomic.LoadUint64(&m.MaxEndToEndLatencyNanos)

	var avgRoute time.Duration
	if routed > 0 {
		avgRoute = time.Duration(totalRoute / routed)
	}

	var avgE2E time.Duration
	if delivered > 0 {
		avgE2E = time.Duration(totalE2E / delivered)
	}

	return Snapshot{
		Published: atomic.LoadUint64(&m.Published),
		Routed:    routed,
		Dropped:   atomic.LoadUint64(&m.Dropped),
		Delivered: delivered,
		Rejected:  atomic.LoadUint64(&m.Rejected),

		SubscriberQueueFull: atomic.LoadUint64(&m.SubscriberQueueFull),

		AvgRouteLatency: avgRoute,
		MaxRouteLatency: time.Duration(maxRoute),

		AvgEndToEndLatency: avgE2E,
		MaxEndToEndLatency: time.Duration(maxE2E),
	}
}
