# Improved Version

Here is a corrected and slightly more production-ready version of `router.go` that addresses the issues above.

## Replace `router/router.go` with:

```go
package router

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

var ErrRouterClosed = errors.New("router closed")
var ErrSubscriberExists = errors.New("subscriber already exists")

type Handler func(Envelope)

type subscriber struct {
	name string
	ch   chan Envelope
}

type worker struct {
	id int
	ch chan Message
}

type Router struct {
	workers []worker

	mu   sync.RWMutex
	subs map[string][]*subscriber

	metrics Metrics

	closeCh uint32
	wg      sync.WaitGroup

	subscriberBuffer int
}

type Config struct {
	WorkerCount      int
	WorkerBuffer     int
	SubscriberBuffer int
}

func NewRouter(cfg Config) *Router {
	if cfg.WorkerCount <= 0 {
		cfg.WorkerCount = runtime.NumCPU()
	}
	if cfg.WorkerBuffer <= 0 {
		cfg.WorkerBuffer = 65536
	}
	if cfg.SubscriberBuffer <= 0 {
		cfg.SubscriberBuffer = 4096
	}

	r := &Router{
		workers:          make([]worker, cfg.WorkerCount),
		subs:             make(map[string][]*subscriber),
		subscriberBuffer: cfg.SubscriberBuffer,
	}

	for i := 0; i < cfg.WorkerCount; i++ {
		r.workers[i] = worker{
			id: i,
			ch: make(chan Message, cfg.WorkerBuffer),
		}
		r.wg.Add(1)
		go r.runWorker(r.workers[i])
	}

	return r
}

func (r *Router) isClosed() bool {
	return atomic.LoadUint32(&r.closeCh) == 1
}

func (r *Router) Publish(msg Message) error {
	if r.isClosed() {
		r.metrics.IncRejected()
		return ErrRouterClosed
	}

	r.metrics.IncPublished()

	idx := int(hashTopic(msg.Topic) % uint32(len(r.workers)))

	select {
	case r.workers[idx].ch <- msg:
		return nil
	default:
		r.metrics.IncDropped()
		return nil
	}
}

func (r *Router) Subscribe(topic, name string, handler Handler) error {
	sub := &subscriber{
		name: name,
		ch:   make(chan Envelope, r.subscriberBuffer),
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	existing := r.subs[topic]
	for _, s := range existing {
		if s.name == name {
			return ErrSubscriberExists
		}
	}

	r.subs[topic] = append(r.subs[topic], sub)

	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		for env := range sub.ch {
			handler(env)
			if !env.Msg.CreatedAt.IsZero() {
				r.metrics.ObserveEndToEndLatency(time.Since(env.Msg.CreatedAt))
			}
		}
	}()

	return nil
}

func (r *Router) runWorker(w worker) {
	defer r.wg.Done()

	for msg := range w.ch {
		start := time.Now()

		r.mu.RLock()
		subs := r.subs[msg.Topic]
		r.mu.RUnlock()

		routedAt := time.Now()
		routeLatency := routedAt.Sub(start)

		env := Envelope{
			Msg:        msg,
			ReceivedAt: start,
			RoutedAt:   routedAt,
			WorkerID:   w.id,
			RouteNanos: routeLatency.Nanoseconds(),
		}

		for _, sub := range subs {
			select {
			case sub.ch <- env:
				r.metrics.IncDelivered()
			default:
				r.metrics.IncSubscriberQueueFull()
			}
		}

		r.metrics.IncRouted()
		r.metrics.ObserveRouteLatency(routeLatency)
	}
}

func (r *Router) Close() {
	if !atomic.CompareAndSwapUint32(&r.closeCh, 0, 1) {
		return
	}

	for _, w := range r.workers {
		close(w.ch)
	}

	r.wg.Wait()

	r.mu.Lock()
	defer r.mu.Unlock()

	for _, subs := range r.subs {
		for _, sub := range subs {
			close(sub.ch)
		}
	}
}
