# `router/metrics.go`

```go
package router

import (
	"encoding/json"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

type LatencyStats struct {
	Count uint64        `json:"count"`
	Min   time.Duration `json:"min_ns"`
	Max   time.Duration `json:"max_ns"`
	Sum   time.Duration `json:"sum_ns"`
}

func (l *LatencyStats) Observe(d time.Duration) {
	ns := d.Nanoseconds()
	for {
		old := atomic.LoadUint64(&l.Count)
		if atomic.CompareAndSwapUint64(&l.Count, old, old+1) {
			break
		}
	}

	for {
		old := atomic.LoadInt64((*int64)(&l.Min))
		if old != 0 && ns >= old {
			break
		}
		if atomic.CompareAndSwapInt64((*int64)(&l.Min), old, ns) {
			break
		}
	}

	for {
		old := atomic.LoadInt64((*int64)(&l.Max))
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapInt64((*int64)(&l.Max), old, ns) {
			break
		}
	}

	atomic.AddInt64((*int64)(&l.Sum), ns)
}

type TopicMetrics struct {
	Received uint64 `json:"received"`
	Routed   uint64 `json:"routed"`
	Dropped  uint64 `json:"dropped"`
}

type Metrics struct {
	ReceivedTotal uint64 `json:"received_total"`
	RoutedTotal   uint64 `json:"routed_total"`
	DroppedTotal  uint64 `json:"dropped_total"`

	ProcessingLatency LatencyStats `json:"processing_latency"`
	EndToEndLatency   LatencyStats `json:"end_to_end_latency"`

	mu     sync.RWMutex
	topics map[string]*TopicMetrics
}

func NewMetrics() *Metrics {
	return &Metrics{
		topics: make(map[string]*TopicMetrics),
	}
}

func (m *Metrics) topic(topic string) *TopicMetrics {
	m.mu.RLock()
	tm, ok := m.topics[topic]
	m.mu.RUnlock()
	if ok {
		return tm
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	tm, ok = m.topics[topic]
	if ok {
		return tm
	}
	tm = &TopicMetrics{}
	m.topics[topic] = tm
	return tm
}

func (m *Metrics) IncReceived(topic string) {
	atomic.AddUint64(&m.ReceivedTotal, 1)
	tm := m.topic(topic)
	atomic.AddUint64(&tm.Received, 1)
}

func (m *Metrics) IncRouted(topic string) {
	atomic.AddUint64(&m.RoutedTotal, 1)
	tm := m.topic(topic)
	atomic.AddUint64(&tm.Routed, 1)
}

func (m *Metrics) IncDropped(topic string) {
	atomic.AddUint64(&m.DroppedTotal, 1)
	tm := m.topic(topic)
	atomic.AddUint64(&tm.Dropped, 1)
}

type MetricsSnapshot struct {
	ReceivedTotal     uint64                  `json:"received_total"`
	RoutedTotal       uint64                  `json:"routed_total"`
	DroppedTotal      uint64                  `json:"dropped_total"`
	ProcessingLatency LatencySnapshot         `json:"processing_latency"`
	EndToEndLatency   LatencySnapshot         `json:"end_to_end_latency"`
	Topics            map[string]TopicMetrics `json:"topics"`
}

type LatencySnapshot struct {
	Count uint64  `json:"count"`
	MinNs int64   `json:"min_ns"`
	MaxNs int64   `json:"max_ns"`
	SumNs int64   `json:"sum_ns"`
	AvgNs float64 `json:"avg_ns"`
}

func (m *Metrics) Snapshot() MetricsSnapshot {
	m.mu.RLock()
	defer m.mu.RUnlock()

	topics := make(map[string]TopicMetrics, len(m.topics))
	for k, v := range m.topics {
		topics[k] = TopicMetrics{
			Received: atomic.LoadUint64(&v.Received),
			Routed:   atomic.LoadUint64(&v.Routed),
			Dropped:  atomic.LoadUint64(&v.Dropped),
		}
	}

	procCount := atomic.LoadUint64(&m.ProcessingLatency.Count)
	procSum := atomic.LoadInt64((*int64)(&m.ProcessingLatency.Sum))
	e2eCount := atomic.LoadUint64(&m.EndToEndLatency.Count)
	e2eSum := atomic.LoadInt64((*int64)(&m.EndToEndLatency.Sum))

	var procAvg float64
	if procCount > 0 {
		procAvg = float64(procSum) / float64(procCount)
	}

	var e2eAvg float64
	if e2eCount > 0 {
		e2eAvg = float64(e2eSum) / float64(e2eCount)
	}

	return MetricsSnapshot{
		ReceivedTotal: atomic.LoadUint64(&m.ReceivedTotal),
		RoutedTotal:   atomic.LoadUint64(&m.RoutedTotal),
		DroppedTotal:  atomic.LoadUint64(&m.DroppedTotal),
		ProcessingLatency: LatencySnapshot{
			Count: procCount,
			MinNs: atomic.LoadInt64((*int64)(&m.ProcessingLatency.Min)),
			MaxNs: atomic.LoadInt64((*int64)(&m.ProcessingLatency.Max)),
			SumNs: procSum,
			AvgNs: procAvg,
		},
		EndToEndLatency: LatencySnapshot{
			Count: e2eCount,
			MinNs: atomic.LoadInt64((*int64)(&m.EndToEndLatency.Min)),
			MaxNs: atomic.LoadInt64((*int64)(&m.EndToEndLatency.Max)),
			SumNs: e2eSum,
			AvgNs: e2eAvg,
		},
		Topics: topics,
	}
}

func (m *Metrics) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(m.Snapshot())
}
