# `router/router.go`

```go
package router

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"time"
)

type Handler func(Message)

type shard struct {
	queue chan Message
}

type Router struct {
	shards        []shard
	handlers      sync.Map // map[string]Handler
	metrics       *Metrics
	workerCount   int
	queueSize     int
	shutdownCh    chan struct{}
	wg            sync.WaitGroup
	dropIfFull    bool
}

type Config struct {
	ShardCount  int
	WorkersPerShard int
	QueueSize   int
	DropIfFull  bool
}

func NewRouter(cfg Config) *Router {
	if cfg.ShardCount <= 0 {
		cfg.ShardCount = runtime.NumCPU()
	}
	if cfg.WorkersPerShard <= 0 {
		cfg.WorkersPerShard = 2
	}
	if cfg.QueueSize <= 0 {
		cfg.QueueSize = 65536
	}

	r := &Router{
		shards:      make([]shard, cfg.ShardCount),
		metrics:     NewMetrics(),
		workerCount: cfg.WorkersPerShard,
		queueSize:   cfg.QueueSize,
		shutdownCh:  make(chan struct{}),
		dropIfFull:  cfg.DropIfFull,
	}

	for i := range r.shards {
		r.shards[i] = shard{
			queue: make(chan Message, cfg.QueueSize),
		}
		for w := 0; w < r.workerCount; w++ {
			r.wg.Add(1)
			go r.worker(i)
		}
	}

	return r
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}

func (r *Router) Register(topic string, h Handler) {
	r.handlers.Store(topic, h)
}

func (r *Router) Submit(msg Message) error {
	r.metrics.IncReceived(msg.Topic)

	idx := r.shardFor(msg.Topic)
	msg.ReceivedAt = time.Now()

	if r.dropIfFull {
		select {
		case r.shards[idx].queue <- msg:
			r.metrics.IncRouted(msg.Topic)
			return nil
		default:
			r.metrics.IncDropped(msg.Topic)
			return errors.New("queue full, message dropped")
		}
	}

	select {
	case r.shards[idx].queue <- msg:
		r.metrics.IncRouted(msg.Topic)
		return nil
	case <-r.shutdownCh:
		r.metrics.IncDropped(msg.Topic)
		return errors.New("router shutting down")
	}
}

func (r *Router) shardFor(topic string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) worker(shardIdx int) {
	defer r.wg.Done()

	q := r.shards[shardIdx].queue
	for {
		select {
		case msg := <-q:
			r.process(msg)
		case <-r.shutdownCh:
			return
		}
	}
}

func (r *Router) process(msg Message) {
	start := time.Now()

	hv, ok := r.handlers.Load(msg.Topic)
	if !ok {
		r.metrics.IncDropped(msg.Topic)
		return
	}

	handler := hv.(Handler)
	handler(msg)

	end := time.Now()
	processingLatency := end.Sub(start)
	endToEndLatency := end.Sub(msg.CreatedAt)

	r.metrics.ProcessingLatency.Observe(processingLatency)
	r.metrics.EndToEndLatency.Observe(endToEndLatency)
}

func (r *Router) Close() {
	close(r.shutdownCh)
	r.wg.Wait()
}
