```go
package router

import (
	"encoding/json"
	"net/http"
	"sync/atomic"
	"time"
)

type Metrics struct {
	received uint64
	routed   uint64
	failed   uint64
	dropped  uint64

	latencyCount uint64
	latencyTotal int64
	latencyMax   int64
}

func (m *Metrics) IncReceived() {
	atomic.AddUint64(&m.received, 1)
}

func (m *Metrics) IncRouted() {
	atomic.AddUint64(&m.routed, 1)
}

func (m *Metrics) IncFailed() {
	atomic.AddUint64(&m.failed, 1)
}

func (m *Metrics) IncDropped() {
	atomic.AddUint64(&m.dropped, 1)
}

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := d.Nanoseconds()
	atomic.AddUint64(&m.latencyCount, 1)
	atomic.AddInt64(&m.latencyTotal, ns)

	for {
		current := atomic.LoadInt64(&m.latencyMax)
		if ns <= current {
			break
		}
		if atomic.CompareAndSwapInt64(&m.latencyMax, current, ns) {
			break
		}
	}
}

type MetricsSnapshot struct {
	Received     uint64  `json:"received"`
	Routed       uint64  `json:"routed"`
	Failed       uint64  `json:"failed"`
	Dropped      uint64  `json:"dropped"`
	LatencyCount uint64  `json:"latency_count"`
	LatencyAvgMs float64 `json:"latency_avg_ms"`
	LatencyMaxMs float64 `json:"latency_max_ms"`
}

func (m *Metrics) Snapshot() MetricsSnapshot {
	count := atomic.LoadUint64(&m.latencyCount)
	total := atomic.LoadInt64(&m.latencyTotal)
	max := atomic.LoadInt64(&m.latencyMax)

	avgMs := 0.0
	if count > 0 {
		avgMs = float64(total) / float64(count) / 1e6
	}

	return MetricsSnapshot{
		Received:     atomic.LoadUint64(&m.received),
		Routed:       atomic.LoadUint64(&m.routed),
		Failed:       atomic.LoadUint64(&m.failed),
		Dropped:      atomic.LoadUint64(&m.dropped),
		LatencyCount: count,
		LatencyAvgMs: avgMs,
		LatencyMaxMs: float64(max) / 1e6,
	}
}

func (m *Metrics) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(m.Snapshot())
}
