## `router/router.go`

```go
package router

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"time"
)

var ErrRouterClosed = errors.New("router closed")
var ErrBackpressure = errors.New("router backpressure: queue full")

type shard struct {
	ch chan Message
}

type Router struct {
	ingress chan Message
	shards  []shard
	handler Handler
	metrics *Metrics

	wg      sync.WaitGroup
	closeCh chan struct{}
}

type Config struct {
	IngressBuffer int
	ShardCount    int
	ShardBuffer   int
}

func DefaultConfig() Config {
	cpus := runtime.NumCPU()
	return Config{
		IngressBuffer: 1024 * 64,
		ShardCount:    cpus * 2,
		ShardBuffer:   1024 * 64,
	}
}

func NewRouter(cfg Config, handler Handler, metrics *Metrics) *Router {
	if cfg.IngressBuffer <= 0 {
		cfg.IngressBuffer = 1024 * 64
	}
	if cfg.ShardCount <= 0 {
		cfg.ShardCount = runtime.NumCPU() * 2
	}
	if cfg.ShardBuffer <= 0 {
		cfg.ShardBuffer = 1024 * 64
	}
	if metrics == nil {
		metrics = &Metrics{}
	}

	r := &Router{
		ingress: make(chan Message, cfg.IngressBuffer),
		shards:  make([]shard, cfg.ShardCount),
		handler: handler,
		metrics: metrics,
		closeCh: make(chan struct{}),
	}

	for i := range r.shards {
		r.shards[i] = shard{ch: make(chan Message, cfg.ShardBuffer)}
	}

	r.wg.Add(1)
	go r.runIngress()

	for i := range r.shards {
		r.wg.Add(1)
		go r.runShard(i)
	}

	return r
}

func (r *Router) Publish(msg Message) error {
	select {
	case <-r.closeCh:
		return ErrRouterClosed
	default:
	}

	r.metrics.IncReceived()

	select {
	case r.ingress <- msg:
		return nil
	default:
		r.metrics.IncDropped()
		return ErrBackpressure
	}
}

func (r *Router) runIngress() {
	defer r.wg.Done()

	for {
		select {
		case <-r.closeCh:
			return
		case msg := <-r.ingress:
			idx := r.shardFor(msg)
			select {
			case r.shards[idx].ch <- msg:
				r.metrics.IncRouted()
			default:
				r.metrics.IncDropped()
			}
		}
	}
}

func (r *Router) runShard(i int) {
	defer r.wg.Done()

	for {
		select {
		case <-r.closeCh:
			return
		case msg := <-r.shards[i].ch:
			start := time.Now()
			if err := r.handler.Handle(msg); err != nil {
				r.metrics.IncFailed()
			}
			r.metrics.ObserveLatency(time.Since(start))
		}
	}
}

func (r *Router) shardFor(msg Message) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(msg.Key))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) Close() {
	select {
	case <-r.closeCh:
		return
	default:
		close(r.closeCh)
	}
	r.wg.Wait()
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}
```

