```go
package main

import (
	"fmt"
	"hash/fnv"
	"runtime"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Worker struct {
	ch chan Message
}

type Router struct {
	workers []Worker
}

var (
	totalProcessed uint64
	totalLatencyNs uint64
	maxLatencyNs   uint64
)

func NewRouter(workerCount int, queueSize int) *Router {
	r := &Router{
		workers: make([]Worker, workerCount),
	}
	for i := range r.workers {
		r.workers[i] = Worker{
			ch: make(chan Message, queueSize),
		}
		go startWorker(r.workers[i].ch)
	}
	return r
}

func startWorker(ch <-chan Message) {
	for msg := range ch {
		// Simulated processing
		latency := uint64(time.Now().UnixNano() - msg.CreatedAt)

		atomic.AddUint64(&totalProcessed, 1)
		atomic.AddUint64(&totalLatencyNs, latency)

		for {
			currentMax := atomic.LoadUint64(&maxLatencyNs)
			if latency <= currentMax {
				break
			}
			if atomic.CompareAndSwapUint64(&maxLatencyNs, currentMax, latency) {
				break
			}
		}
	}
}

func (r *Router) Route(msg Message) {
	idx := hashTopic(msg.Topic) % uint32(len(r.workers))
	r.workers[idx].ch <- msg
}

func hashTopic(topic string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return h.Sum32()
}

func producer(r *Router, topics []string) {
	var id uint64
	payload := make([]byte, 128)

	for {
		for _, topic := range topics {
			id++
			msg := Message{
				ID:        id,
				Topic:     topic,
				Payload:   payload,
				CreatedAt: time.Now().UnixNano(),
			}
			r.Route(msg)
		}
	}
}

func metricsPrinter() {
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	var lastProcessed uint64

	for range ticker.C {
		currentProcessed := atomic.LoadUint64(&totalProcessed)
		currentLatency := atomic.LoadUint64(&totalLatencyNs)
		currentMax := atomic.LoadUint64(&maxLatencyNs)

		delta := currentProcessed - lastProcessed
		lastProcessed = currentProcessed

		avgLatency := uint64(0)
		if currentProcessed > 0 {
			avgLatency = currentLatency / currentProcessed
		}

		fmt.Printf(
			"throughput=%d msg/s total=%d avg_latency=%dus max_latency=%dus goroutines=%d\n",
			delta,
			currentProcessed,
			avgLatency/1000,
			currentMax/1000,
			runtime.NumGoroutine(),
		)
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	topics := []string{
		"orders",
		"trades",
		"quotes",
		"risk",
		"positions",
		"alerts",
	}

	router := NewRouter(64, 65536)

	go metricsPrinter()
	go producer(router, topics)

	select {}
}
