```go
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Router struct {
	topics map[string][]chan Message
	mu     sync.RWMutex
}

func NewRouter() *Router {
	return &Router{
		topics: make(map[string][]chan Message),
	}
}

func (r *Router) Subscribe(topic string, ch chan Message) {
	r.mu.Lock()
	r.topics[topic] = append(r.topics[topic], ch)
	r.mu.Unlock()
}

func (r *Router) Publish(msg Message) {
	r.mu.RLock()
	subs := r.topics[msg.Topic]
	r.mu.RUnlock()

	for _, ch := range subs {
		select {
		case ch <- msg:
		default:
			// drop if subscriber is slow
		}
	}
}

type Metrics struct {
	totalMessages uint64
	totalLatency  uint64 // nanoseconds
	mu            sync.Mutex
	samples       []int64
}

func (m *Metrics) Record(latency time.Duration) {
	atomic.AddUint64(&m.totalMessages, 1)
	atomic.AddUint64(&m.totalLatency, uint64(latency.Nanoseconds()))

	m.mu.Lock()
	if len(m.samples) < 100000 {
		m.samples = append(m.samples, latency.Nanoseconds())
	}
	m.mu.Unlock()
}

func (m *Metrics) Report(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastCount uint64

	for range ticker.C {
		total := atomic.LoadUint64(&m.totalMessages)
		delta := total - lastCount
		lastCount = total

		avg := time.Duration(0)
		totalLat := atomic.LoadUint64(&m.totalLatency)
		if total > 0 {
			avg = time.Duration(totalLat / total)
		}

		m.mu.Lock()
		samples := append([]int64(nil), m.samples...)
		m.samples = m.samples[:0]
		m.mu.Unlock()

		var p95, p99 time.Duration
		if len(samples) > 0 {
			sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })
			p95 = time.Duration(samples[(len(samples)*95)/100])
			p99 = time.Duration(samples[(len(samples)*99)/100])
		}

		fmt.Printf(
			"throughput=%d msg/s total=%d avg=%s p95=%s p99=%s\n",
			delta/int64(interval/time.Second),
			total,
			avg,
			p95,
			p99,
		)
	}
}

func producer(id int, router *Router, topics []string, counter *uint64) {
	payload := make([]byte, 128)
	for {
		msgID := atomic.AddUint64(counter, 1)
		msg := Message{
			ID:        msgID,
			Topic:     topics[rand.Intn(len(topics))],
			Payload:   payload,
			CreatedAt: time.Now().UnixNano(),
		}
		router.Publish(msg)
	}
}

func consumer(id int, ch chan Message, metrics *Metrics) {
	for msg := range ch {
		latency := time.Since(time.Unix(0, msg.CreatedAt))
		metrics.Record(latency)
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	router := NewRouter()
	metrics := &Metrics{
		samples: make([]int64, 0, 100000),
	}

	topics := []string{"orders", "trades", "quotes", "risk"}

	// Create subscribers
	for i := 0; i < 8; i++ {
		ch := make(chan Message, 65536)
		topic := topics[i%len(topics)]
		router.Subscribe(topic, ch)
		go consumer(i, ch, metrics)
	}

	// Start metrics reporter
	go metrics.Report(1 * time.Second)

	var msgCounter uint64

	// Start producers
	for i := 0; i < 16; i++ {
		go producer(i, router, topics, &msgCounter)
	}

	select {}
}
