Below is a **minimal working version** of a **high-frequency messaging system** in **Go** that:

- routes messages by topic
- uses worker sharding for throughput
- tracks per-message latency
- exposes basic metrics
- is simple enough to run locally

It is **not production-grade**, but it demonstrates the core architecture for a very fast in-memory router.

---

## Features

- **Producer** generates messages at high rate
- **Router** dispatches messages to shard workers
- **Consumers** process messages
- **Latency monitoring** records end-to-end time
- **Metrics reporter** prints throughput and latency stats every second

---

## Code

Save as `main.go`:

```go
package main

import (
	"fmt"
	"hash/fnv"
	"math/rand"
	"sort"
	"sync/atomic"
	"time"
)

const (
	NumShards        = 8
	MessagesPerBatch = 1000
	ChannelSize      = 65536
	RunDuration      = 10 * time.Second
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Worker struct {
	id      int
	inbox   chan Message
	handled uint64
}

type Metrics struct {
	produced uint64
	routed   uint64
	handled  uint64
	dropped  uint64

	latencyCount uint64
	latencySumNs uint64
	latencyMaxNs uint64

	// simple ring buffer substitute for percentile sampling
	samples chan int64
}

func NewWorker(id int) *Worker {
	return &Worker{
		id:    id,
		inbox: make(chan Message, ChannelSize),
	}
}

func (w *Worker) Start(metrics *Metrics) {
	go func() {
		for msg := range w.inbox {
			// Simulate lightweight processing
			_ = msg.Payload

			latency := time.Now().UnixNano() - msg.CreatedAt
			atomic.AddUint64(&w.handled, 1)
			atomic.AddUint64(&metrics.handled, 1)
			atomic.AddUint64(&metrics.latencyCount, 1)
			atomic.AddUint64(&metrics.latencySumNs, uint64(latency))

			for {
				old := atomic.LoadUint64(&metrics.latencyMaxNs)
				if uint64(latency) <= old || atomic.CompareAndSwapUint64(&metrics.latencyMaxNs, old, uint64(latency)) {
					break
				}
			}

			select {
			case metrics.samples <- latency:
			default:
				// drop sample if full
			}
		}
	}()
}

type Router struct {
	workers []*Worker
	metrics *Metrics
}

func NewRouter(numShards int, metrics *Metrics) *Router {
	workers := make([]*Worker, numShards)
	for i := 0; i < numShards; i++ {
		workers[i] = NewWorker(i)
		workers[i].Start(metrics)
	}
	return &Router{
		workers: workers,
		metrics: metrics,
	}
}

func (r *Router) Route(msg Message) {
	idx := shardForTopic(msg.Topic, len(r.workers))
	select {
	case r.workers[idx].inbox <- msg:
		atomic.AddUint64(&r.metrics.routed, 1)
	default:
		atomic.AddUint64(&r.metrics.dropped, 1)
	}
}

func shardForTopic(topic string, shards int) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return int(h.Sum32()) % shards
}

func producer(router *Router, stop <-chan struct{}) {
	var id uint64
	topics := []string{
		"orders", "trades", "prices", "risk",
		"accounts", "fills", "positions", "alerts",
	}

	payload := make([]byte, 128)

	for {
		select {
		case <-stop:
			return
		default:
		}

		for i := 0; i < MessagesPerBatch; i++ {
			msg := Message{
				ID:        id,
				Topic:     topics[rand.Intn(len(topics))],
				Payload:   payload,
				CreatedAt: time.Now().UnixNano(),
			}
			id++
			atomic.AddUint64(&router.metrics.produced, 1)
			router.Route(msg)
		}
	}
}

func report(metrics *Metrics, stop <-chan struct{}) {
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	var lastProduced, lastRouted, lastHandled, lastDropped uint64

	for {
		select {
		case <-ticker.C:
			produced := atomic.LoadUint64(&metrics.produced)
			routed := atomic.LoadUint64(&metrics.routed)
			handled := atomic.LoadUint64(&metrics.handled)
			dropped := atomic.LoadUint64(&metrics.dropped)
			latCount := atomic.LoadUint64(&metrics.latencyCount)
			latSum := atomic.LoadUint64(&metrics.latencySumNs)
			latMax := atomic.LoadUint64(&metrics.latencyMaxNs)

			pRate := produced - lastProduced
			rRate := routed - lastRouted
			hRate := handled - lastHandled
			dRate := dropped - lastDropped

			lastProduced = produced
			lastRouted = routed
			lastHandled = handled
			lastDropped = dropped

			var avgLatencyUs float64
			if latCount > 0 {
				avgLatencyUs = float64(latSum) / float64(latCount) / 1000.0
			}

			p50, p95, p99 := samplePercentiles(metrics)

			fmt.Printf(
				"prod=%d/s routed=%d/s handled=%d/s dropped=%d/s totalHandled=%d avg=%.2fus p50=%.2fus p95=%.2fus p99=%.2fus max=%.2fus\n",
				pRate, rRate, hRate, dRate, handled,
				avgLatencyUs, p50, p95, p99, float64(latMax)/1000.0,
			)

		case <-stop:
			return
		}
	}
}

func samplePercentiles(metrics *Metrics) (p50, p95, p99 float64) {
	sz := len(metrics.samples)
	if sz == 0 {
		return 0, 0, 0
	}

	values := make([]int64, 0, sz)
	for {
		select {
		case v := <-metrics.samples:
			values = append(values, v)
		default:
			goto DONE
		}
	}

DONE:
	if len(values) == 0 {
		return 0, 0, 0
	}

	sort.Slice(values, func(i, j int) bool { return values[i] < values[j] })

	get := func(p float64) float64 {
		idx := int(float64(len(values)-1) * p)
		return float64(values[idx]) / 1000.0
	}

	return get(0.50), get(0.95), get(0.99)
}

func main() {
	rand.Seed(time.Now().UnixNano())

	metrics := &Metrics{
		samples: make(chan int64, 100000),
	}

	router := NewRouter(NumShards, metrics)

	stop := make(chan struct{})

	go producer(router, stop)
	go report(metrics, stop)

	time.Sleep(RunDuration)
	close(stop)

	// allow workers to drain briefly
	time.Sleep(1 * time.Second)

	fmt.Println("done")
}
