```rust
use anyhow::{bail, Context, Result};
use core_affinity::CoreId;
use nix::sched::{sched_setaffinity, CpuSet};
use nix::unistd::Pid;
use std::env;
use std::mem::{size_of, zeroed};
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::ptr;
use std::sync::atomic::{compiler_fence, Ordering};

const ETH_P_IP: u16 = 0x0800;
const ETH_HDR_LEN: usize = 14;
const IPV4_MIN_HDR_LEN: usize = 20;
const UDP_PROTO: u8 = 17;
const TCP_PROTO: u8 = 6;

const SOL_XDP: i32 = 283;
const XDP_UMEM_REG: i32 = 1;
const XDP_RX_RING: i32 = 2;
const XDP_TX_RING: i32 = 3;
const XDP_UMEM_FILL_RING: i32 = 4;
const XDP_UMEM_COMPLETION_RING: i32 = 5;
const XDP_MMAP_OFFSETS: i32 = 6;
const XDP_STATISTICS: i32 = 7;
const XDP_OPTIONS: i32 = 8;

const XDP_SHARED_UMEM: u16 = 1 << 0;
const XDP_COPY: u16 = 1 << 1;
const XDP_ZEROCOPY: u16 = 1 << 2;
const XDP_USE_NEED_WAKEUP: u16 = 1 << 3;

const AF_XDP: i32 = 44;

const XDP_PGOFF_RX_RING: libc::off_t = 0;
const XDP_PGOFF_TX_RING: libc::off_t = 0x80000000;
const XDP_UMEM_PGOFF_FILL_RING: libc::off_t = 0x100000000;
const XDP_UMEM_PGOFF_COMPLETION_RING: libc::off_t = 0x180000000;

const FRAME_SIZE: usize = 2048;
const NUM_FRAMES: usize = 4096;
const UMEM_SIZE: usize = FRAME_SIZE * NUM_FRAMES;
const RING_SIZE: u32 = 1024;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpRingOffset {
    producer: u64,
    consumer: u64,
    desc: u64,
    flags: u64,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpMmapOffsets {
    rx: XdpRingOffset,
    tx: XdpRingOffset,
    fr: XdpRingOffset,
    cr: XdpRingOffset,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpUmemReg {
    addr: u64,
    len: u64,
    chunk_size: u32,
    headroom: u32,
    flags: u32,
    tx_metadata_len: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct SockAddrXdp {
    sxdp_family: u16,
    sxdp_flags: u16,
    sxdp_ifindex: u32,
    sxdp_queue_id: u32,
    sxdp_shared_umem_fd: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpDesc {
    addr: u64,
    len: u32,
    options: u32,
}

#[derive(Debug)]
struct MmapRing {
    map: *mut u8,
    len: usize,
    producer: *mut u32,
    consumer: *mut u32,
    desc: *mut u8,
}

impl Drop for MmapRing {
    fn drop(&mut self) {
        unsafe {
            if !self.map.is_null() && self.len > 0 {
                libc::munmap(self.map as *mut _, self.len);
            }
        }
    }
}

struct Umem {
    ptr: *mut u8,
    len: usize,
}

impl Drop for Umem {
    fn drop(&mut self) {
        unsafe {
            if !self.ptr.is_null() && self.len > 0 {
                libc::munmap(self.ptr as *mut _, self.len);
            }
        }
    }
}

struct Xsk {
    fd: RawFd,
    rx: MmapRing,
    tx: MmapRing,
    fr: MmapRing,
    cr: MmapRing,
    umem: Umem,
}

impl Drop for Xsk {
    fn drop(&mut self) {
        unsafe {
            libc::close(self.fd);
        }
    }
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn if_nametoindex(name: &str) -> Result<u32> {
    let c = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        bail!("if_nametoindex failed for {}", name);
    }
    Ok(idx)
}

fn mmap_ring(fd: RawFd, opt: &XdpRingOffset, entries: u32, pgoff: libc::off_t, desc_size: usize) -> Result<MmapRing> {
    let ring_sz = (opt.desc as usize) + (entries as usize * desc_size);
    let map = unsafe {
        libc::mmap(
            ptr::null_mut(),
            ring_sz,
            libc::PROT_READ | libc::PROT_WRITE,
            libc::MAP_SHARED | libc::MAP_POPULATE,
            fd,
            pgoff,
        )
    };
    if map == libc::MAP_FAILED {
        bail!("mmap ring failed");
    }

    let base = map as *mut u8;
    Ok(MmapRing {
        map: base,
        len: ring_sz,
        producer: unsafe { base.add(opt.producer as usize) as *mut u32 },
        consumer: unsafe { base.add(opt.consumer as usize) as *mut u32 },
        desc: unsafe { base.add(opt.desc as usize) },
    })
}

fn create_xsk(ifname: &str, queue_id: u32) -> Result<Xsk> {
    let fd = unsafe { libc::socket(AF_XDP, libc::SOCK_RAW, 0) };
    if fd < 0 {
        bail!("socket(AF_XDP) failed");
    }

    let umem_ptr = unsafe {
        libc::mmap(
            ptr::null_mut(),
            UMEM_SIZE,
            libc::PROT_READ | libc::PROT_WRITE,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_POPULATE,
            -1,
            0,
        )
    };
    if umem_ptr == libc::MAP_FAILED {
        unsafe { libc::close(fd) };
        bail!("mmap UMEM failed");
    }

    let umem = Umem {
        ptr: umem_ptr as *mut u8,
        len: UMEM_SIZE,
    };

    let reg = XdpUmemReg {
        addr: umem.ptr as u64,
        len: umem.len as u64,
        chunk_size: FRAME_SIZE as u32,
        headroom: 0,
        flags: 0,
        tx_metadata_len: 0,
    };

    let rc = unsafe {
        libc::setsockopt(
            fd,
            SOL_XDP,
            XDP_UMEM_REG,
            &reg as *const _ as *const _,
            size_of::<XdpUmemReg>() as libc::socklen_t,
        )
    };
    if rc != 0 {
        unsafe { libc::close(fd) };
        bail!("setsockopt XDP_UMEM_REG failed");
    }

    for (optname, val) in [
        (XDP_RX_RING, RING_SIZE),
        (XDP_TX_RING, RING_SIZE),
        (XDP_UMEM_FILL_RING, RING_SIZE),
        (XDP_UMEM_COMPLETION_RING, RING_SIZE),
    ] {
        let rc = unsafe {
            libc::setsockopt(
                fd,
                SOL_XDP,
                optname,
                &val as *const _ as *const _,
                size_of::<u32>() as libc::socklen_t,
            )
        };
        if rc != 0 {
            unsafe { libc::close(fd) };
            bail!("setsockopt ring {} failed", optname);
        }
    }

    let mut offs: XdpMmapOffsets = unsafe { zeroed() };
    let mut optlen = size_of::<XdpMmapOffsets>() as libc::socklen_t;
    let rc = unsafe {
        libc::getsockopt(
            fd,
            SOL_XDP,
            XDP_MMAP_OFFSETS,
            &mut offs as *mut _ as *mut _,
            &mut optlen,
        )
    };
    if rc != 0 {
        unsafe { libc::close(fd) };
        bail!("getsockopt XDP_MMAP_OFFSETS failed");
    }

    let rx = mmap_ring(fd, &offs.rx, RING_SIZE, XDP_PGOFF_RX_RING, size_of::<XdpDesc>())?;
    let tx = mmap_ring(fd, &offs.tx, RING_SIZE, XDP_PGOFF_TX_RING, size_of::<XdpDesc>())?;
    let fr = mmap_ring(fd, &offs.fr, RING_SIZE, XDP_UMEM_PGOFF_FILL_RING, size_of::<u64>())?;
    let cr = mmap_ring(fd, &offs.cr, RING_SIZE, XDP_UMEM_PGOFF_COMPLETION_RING, size_of::<u64>())?;

    let ifindex = if_nametoindex(ifname)?;
    let bind_addr = SockAddrXdp {
        sxdp_family: AF_XDP as u16,
        sxdp_flags: XDP_USE_NEED_WAKEUP | XDP_ZEROCOPY,
        sxdp_ifindex: ifindex,
        sxdp_queue_id: queue_id,
        sxdp_shared_umem_fd: 0,
    };

    let rc = unsafe {
        libc::bind(
            fd,
            &bind_addr as *const _ as *const libc::sockaddr,
            size_of::<SockAddrXdp>() as libc::socklen_t,
        )
    };
    if rc != 0 {
        unsafe { libc::close(fd) };
        bail!("bind(AF_XDP) failed");
    }

    let xsk = Xsk { fd, rx, tx, fr, cr, umem };

    // Pre-fill fill ring with all frames.
    unsafe {
        let prod = *xsk.fr.producer;
        for i in 0..RING_SIZE as usize {
            let slot = xsk.fr.desc.add(i * size_of::<u64>()) as *mut u64;
            *slot = (i * FRAME_SIZE) as u64;
        }
        compiler_fence(Ordering::Release);
        *xsk.fr.producer = prod.wrapping_add(RING_SIZE);
    }

    Ok(xsk)
}

fn pin_to_cpu(cpu: usize) -> Result<()> {
    if let Some(cores) = core_affinity::get_core_ids() {
        if let Some(core) = cores.into_iter().find(|c: &CoreId| c.id == cpu) {
            core_affinity::set_for_current(core);
            return Ok(());
        }
    }

    let mut cpuset = CpuSet::new();
    cpuset.set(cpu)?;
    sched_setaffinity(Pid::from_raw(0), &cpuset)?;
    Ok(())
}

#[inline(always)]
fn parse_ipv4_filter(pkt: &[u8], allow_dst: Ipv4Addr, allow_dport: u16) -> bool {
    if pkt.len() < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
        return false;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != ETH_P_IP {
        return false;
    }

    let ip = &pkt[ETH_HDR_LEN..];
    let ihl = ((ip[0] & 0x0f) as usize) * 4;
    if ihl < IPV4_MIN_HDR_LEN || ip.len() < ihl {
        return false;
    }

    let proto = ip[9];
    let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);
    if dst != allow_dst {
        return false;
    }

    match proto {
        UDP_PROTO | TCP_PROTO => {
            if ip.len() < ihl + 4 {
                return false;
            }
            let dport = u16::from_be_bytes([ip[ihl + 2], ip[ihl + 3]]);
            dport == allow_dport
        }
        _ => false,
    }
}

#[inline(always)]
unsafe fn rx_desc_at(r: &MmapRing, idx: u32) -> *mut XdpDesc {
    r.desc.add((idx as usize % RING_SIZE as usize) * size_of::<XdpDesc>()) as *mut XdpDesc
}

#[inline(always)]
unsafe fn tx_desc_at(r: &MmapRing, idx: u32) -> *mut XdpDesc {
    r.desc.add((idx as usize % RING_SIZE as usize) * size_of::<XdpDesc>()) as *mut XdpDesc
}

#[inline(always)]
unsafe fn u64_slot_at(r: &MmapRing, idx: u32) -> *mut u64 {
    r.desc.add((idx as usize % RING_SIZE as usize) * size_of::<u64>()) as *mut u64
}

fn kick_tx(fd: RawFd) {
    let dummy: [u8; 0] = [];
    unsafe {
        libc::send(fd, dummy.as_ptr() as *const _, 0, libc::MSG_DONTWAIT);
    }
}

fn recycle_completions(xsk: &Xsk) {
    unsafe {
        let mut cr_cons = *xsk.cr.consumer;
        let cr_prod = *xsk.cr.producer;
        let mut fr_prod = *xsk.fr.producer;

        while cr_cons != cr_prod {
            let addr = *u64_slot_at(&xsk.cr, cr_cons);
            *u64_slot_at(&xsk.fr, fr_prod) = addr;
            cr_cons = cr_cons.wrapping_add(1);
            fr_prod = fr_prod.wrapping_add(1);
        }

        compiler_fence(Ordering::Release);
        *xsk.cr.consumer = cr_cons;
        *xsk.fr.producer = fr_prod;
    }
}

fn run(xsk: &Xsk, allow_dst: Ipv4Addr, allow_dport: u16) -> Result<()> {
    loop {
        recycle_completions(xsk);

        let rx_cons;
        let rx_prod;
        unsafe {
            rx_cons = *xsk.rx.consumer;
            rx_prod = *xsk.rx.producer;
        }

        if rx_cons == rx_prod {
            std::hint::spin_loop();
            continue;
        }

        let mut new_rx_cons = rx_cons;
        let mut tx_prod;
        unsafe {
            tx_prod = *xsk.tx.producer;
        }

        while new_rx_cons != rx_prod {
            let desc = unsafe { *rx_desc_at(&xsk.rx, new_rx_cons) };
            let pkt_ptr = unsafe { xsk.umem.ptr.add(desc.addr as usize) };
            let pkt = unsafe { std::slice::from_raw_parts(pkt_ptr, desc.len as usize) };

            let pass = parse_ipv4_filter(pkt, allow_dst, allow_dport);

            if pass {
                unsafe {
                    let txd = tx_desc_at(&xsk.tx, tx_prod);
                    (*txd).addr = desc.addr;
                    (*txd).len = desc.len;
                    (*txd).options = 0;
                }
                tx_prod = tx_prod.wrapping_add(1);
            } else {
                unsafe {
                    let fr_prod = *xsk.fr.producer;
                    *u64_slot_at(&xsk.fr, fr_prod) = desc.addr;
                    compiler_fence(Ordering::Release);
                    *xsk.fr.producer = fr_prod.wrapping_add(1);
                }
            }

            new_rx_cons = new_rx_cons.wrapping_add(1);
        }

        unsafe {
            compiler_fence(Ordering::Release);
            *xsk.rx.consumer = new_rx_cons;
            *xsk.tx.producer = tx_prod;
        }

        kick_tx(xsk.fd);
    }
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 6 {
        bail!("usage: {} <ifname> <queue_id> <cpu> <allow_dst_ipv4> <allow_dport>", args[0]);
    }

    let ifname = &args[1];
    let queue_id: u32 = args[2].parse().context("invalid queue_id")?;
    let cpu: usize = args[3].parse().context("invalid cpu")?;
    let allow_dst: Ipv4Addr = args[4].parse().context("invalid IPv4")?;
    let allow_dport: u16 = args[5].parse().context("invalid port")?;

    pin_to_cpu(cpu)?;
    let xsk = create_xsk(ifname, queue_id)?;
    run(&xsk, allow_dst, allow_dport)
}
