## 1) eBPF/XDP program: `xdp_filter.c`

```c
// xdp_filter.c
// Build with clang -O2 -g -target bpf -c xdp_filter.c -o xdp_filter.o

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/in.h>

char LICENSE[] SEC("license") = "GPL";

// Single-entry config map holding one blocked IPv4 address in network byte order.
struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u32);
} blocked_ip SEC(".maps");

// Per-action counters
struct counters {
    __u64 passed;
    __u64 dropped;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct counters);
} stats SEC(".maps");

static __always_inline void count_pass(void) {
    __u32 k = 0;
    struct counters *c = bpf_map_lookup_elem(&stats, &k);
    if (c) c->passed++;
}

static __always_inline void count_drop(void) {
    __u32 k = 0;
    struct counters *c = bpf_map_lookup_elem(&stats, &k);
    if (c) c->dropped++;
}

SEC("xdp")
int xdp_pkt_filter(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        count_pass();
        return XDP_PASS;
    }

    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        count_pass();
        return XDP_PASS;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        count_pass();
        return XDP_PASS;
    }

    __u32 key = 0;
    __u32 *blocked = bpf_map_lookup_elem(&blocked_ip, &key);
    if (blocked && iph->saddr == *blocked) {
        count_drop();
        return XDP_DROP;
    }

    count_pass();
    return XDP_PASS;
}
```

