## 2) Userspace loader: `loader.c`

This uses **libbpf** to:
- load the XDP object
- attach it to an interface
- set the blocked IP
- print counters periodically

```c
// loader.c
// Example build:
// cc -O2 -g loader.c -o loader -lbpf -lelf -lz

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>

#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static volatile sig_atomic_t stop = 0;

static void on_sigint(int signo) {
    (void)signo;
    stop = 1;
}

struct counters {
    unsigned long long passed;
    unsigned long long dropped;
};

static int set_blocked_ip(int map_fd, const char *ip_str) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip_str, &addr) != 1) {
        fprintf(stderr, "invalid IPv4 address: %s\n", ip_str);
        return -1;
    }

    __u32 key = 0;
    __u32 value = addr.s_addr; // network byte order
    if (bpf_map_update_elem(map_fd, &key, &value, BPF_ANY) != 0) {
        perror("bpf_map_update_elem(blocked_ip)");
        return -1;
    }
    return 0;
}

static int read_stats(int map_fd, struct counters *total) {
    memset(total, 0, sizeof(*total));

    int ncpu = libbpf_num_possible_cpus();
    if (ncpu < 1) {
        fprintf(stderr, "libbpf_num_possible_cpus failed\n");
        return -1;
    }

    struct counters *percpu = calloc(ncpu, sizeof(*percpu));
    if (!percpu) {
        perror("calloc");
        return -1;
    }

    __u32 key = 0;
    if (bpf_map_lookup_elem(map_fd, &key, percpu) != 0) {
        perror("bpf_map_lookup_elem(stats)");
        free(percpu);
        return -1;
    }

    for (int i = 0; i < ncpu; i++) {
        total->passed += percpu[i].passed;
        total->dropped += percpu[i].dropped;
    }

    free(percpu);
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "usage: %s <ifname> <xdp_filter.o> <blocked_ipv4>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *obj_path = argv[2];
    const char *blocked_ipv4 = argv[3];

    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    struct bpf_object *obj = NULL;
    int prog_fd = -1, map_block_fd = -1, map_stats_fd = -1;
    int err;

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    struct bpf_object_open_opts opts = {};
    obj = bpf_object__open_file(obj_path, &opts);
    if (libbpf_get_error(obj)) {
        err = (int)libbpf_get_error(obj);
        fprintf(stderr, "bpf_object__open_file failed: %d\n", err);
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "bpf_object__load failed: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_pkt_filter");
    if (!prog) {
        fprintf(stderr, "program xdp_pkt_filter not found\n");
        bpf_object__close(obj);
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "invalid program fd\n");
        bpf_object__close(obj);
        return 1;
    }

    map_block_fd = bpf_object__find_map_fd_by_name(obj, "blocked_ip");
    map_stats_fd = bpf_object__find_map_fd_by_name(obj, "stats");
    if (map_block_fd < 0 || map_stats_fd < 0) {
        fprintf(stderr, "failed to find map fds\n");
        bpf_object__close(obj);
        return 1;
    }

    if (set_blocked_ip(map_block_fd, blocked_ipv4) != 0) {
        bpf_object__close(obj);
        return 1;
    }

    err = bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    if (err) {
        fprintf(stderr, "bpf_xdp_attach failed: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    printf("XDP filter attached to %s, blocking source IP %s\n", ifname, blocked_ipv4);

    while (!stop) {
        struct counters c;
        if (read_stats(map_stats_fd, &c) == 0) {
            printf("passed=%llu dropped=%llu\n", c.passed, c.dropped);
        }
        sleep(1);
    }

    bpf_xdp_detach(ifindex, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    bpf_object__close(obj);
    printf("detached\n");
    return 0;
}
```

