```c
// afxdp_forwarder.c
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <linux/if_link.h>
#include <linux/if_xdp.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <poll.h>
#include <pthread.h>
#include <sched.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>
#include <bpf/bpf.h>
#include <bpf/libbpf.h>
#include <xdp/xsk.h>

#define NUM_FRAMES          4096
#define FRAME_SIZE          XSK_UMEM__DEFAULT_FRAME_SIZE
#define UMEM_SIZE           (NUM_FRAMES * FRAME_SIZE)

#define RX_RING_SIZE        1024
#define TX_RING_SIZE        1024
#define FQ_RING_SIZE        2048
#define CQ_RING_SIZE        2048
#define BATCH_SIZE          64

static volatile sig_atomic_t running = 1;

struct config {
    char ifname[IFNAMSIZ];
    int ifindex;
    int queue_id;
    int xdp_flags;
    uint16_t allow_udp_port; // 0 = allow any
    uint16_t allow_tcp_port; // 0 = allow any
};

struct xsk_umem_info {
    struct xsk_umem *umem;
    void *buffer;
    struct xsk_ring_prod fq;
    struct xsk_ring_cons cq;
};

struct xsk_socket_info {
    struct xsk_socket *xsk;
    struct xsk_ring_cons rx;
    struct xsk_ring_prod tx;
    struct xsk_umem_info *umem;
    uint64_t umem_frame_addr[NUM_FRAMES];
    uint32_t free_head;
    uint32_t free_cnt;
    uint64_t rx_npkts;
    uint64_t tx_npkts;
    uint64_t dropped;
};

static void on_signal(int signo) {
    (void)signo;
    running = 0;
}

static int bump_memlock_rlimit(void) {
    struct rlimit r = {RLIM_INFINITY, RLIM_INFINITY};
    return setrlimit(RLIMIT_MEMLOCK, &r);
}

static inline uint64_t alloc_frame(struct xsk_socket_info *xsk) {
    if (!xsk->free_cnt)
        return UINT64_MAX;
    xsk->free_cnt--;
    return xsk->umem_frame_addr[xsk->free_head++];
}

static inline void free_frame(struct xsk_socket_info *xsk, uint64_t addr) {
    xsk->umem_frame_addr[--xsk->free_head] = addr;
    xsk->free_cnt++;
}

static int xsk_configure_umem(struct xsk_umem_info *umem) {
    int ret;
    void *bufs;

    ret = posix_memalign(&bufs, getpagesize(), UMEM_SIZE);
    if (ret)
        return ret;

    memset(bufs, 0, UMEM_SIZE);

    struct xsk_umem_config cfg = {
        .fill_size = FQ_RING_SIZE,
        .comp_size = CQ_RING_SIZE,
        .frame_size = FRAME_SIZE,
        .frame_headroom = 0,
        .flags = 0,
    };

    ret = xsk_umem__create(&umem->umem, bufs, UMEM_SIZE,
                           &umem->fq, &umem->cq, &cfg);
    if (ret)
        return ret;

    umem->buffer = bufs;
    return 0;
}

static int xsk_populate_fill_ring(struct xsk_socket_info *xsk) {
    uint32_t idx;
    int ret = xsk_ring_prod__reserve(&xsk->umem->fq, NUM_FRAMES, &idx);
    if (ret != NUM_FRAMES)
        return -1;

    for (int i = 0; i < NUM_FRAMES; i++) {
        *xsk_ring_prod__fill_addr(&xsk->umem->fq, idx++) = i * FRAME_SIZE;
        xsk->umem_frame_addr[i] = i * FRAME_SIZE;
    }

    xsk_ring_prod__submit(&xsk->umem->fq, NUM_FRAMES);
    xsk->free_head = 0;
    xsk->free_cnt = NUM_FRAMES;
    return 0;
}

static int xsk_configure_socket(struct xsk_socket_info *xsk, struct config *cfg) {
    struct xsk_socket_config xcfg = {
        .rx_size = RX_RING_SIZE,
        .tx_size = TX_RING_SIZE,
        .libbpf_flags = 0,
        .xdp_flags = cfg->xdp_flags,
        .bind_flags = XDP_USE_NEED_WAKEUP,
    };

    return xsk_socket__create(&xsk->xsk, cfg->ifname, cfg->queue_id,
                              xsk->umem->umem, &xsk->rx, &xsk->tx, &xcfg);
}

static bool packet_allowed(void *data, uint32_t len, struct config *cfg) {
    if (len < sizeof(struct ethhdr))
        return false;

    struct ethhdr *eth = data;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return false;

    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return false;

    struct iphdr *ip = (struct iphdr *)((uint8_t *)data + sizeof(struct ethhdr));
    if (ip->ihl < 5)
        return false;

    uint32_t ip_hdr_len = ip->ihl * 4;
    if (len < sizeof(struct ethhdr) + ip_hdr_len)
        return false;

    uint8_t *l4 = (uint8_t *)ip + ip_hdr_len;
    uint32_t l4_len = len - sizeof(struct ethhdr) - ip_hdr_len;

    if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr))
            return false;
        struct udphdr *udp = (struct udphdr *)l4;
        if (cfg->allow_udp_port == 0)
            return true;
        return ntohs(udp->dest) == cfg->allow_udp_port;
    }

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr))
            return false;
        struct tcphdr *tcp = (struct tcphdr *)l4;
        if (cfg->allow_tcp_port == 0)
            return true;
        return ntohs(tcp->dest) == cfg->allow_tcp_port;
    }

    return false;
}

static inline void swap_macs(struct ethhdr *eth) {
    unsigned char tmp[ETH_ALEN];
    memcpy(tmp, eth->h_source, ETH_ALEN);
    memcpy(eth->h_source, eth->h_dest, ETH_ALEN);
    memcpy(eth->h_dest, tmp, ETH_ALEN);
}

static void complete_tx(struct xsk_socket_info *xsk) {
    uint32_t idx_cq = 0;
    unsigned int completed = xsk_ring_cons__peek(&xsk->umem->cq, BATCH_SIZE, &idx_cq);
    if (!completed)
        return;

    for (unsigned int i = 0; i < completed; i++) {
        uint64_t addr = *xsk_ring_cons__comp_addr(&xsk->umem->cq, idx_cq + i);
        free_frame(xsk, addr);
    }
    xsk_ring_cons__release(&xsk->umem->cq, completed);
}

static int kick_tx(struct xsk_socket_info *xsk) {
    int fd = xsk_socket__fd(xsk->xsk);
    return sendto(fd, NULL, 0, MSG_DONTWAIT, NULL, 0);
}

static void process_packets(struct xsk_socket_info *xsk, struct config *cfg) {
    uint32_t idx_rx = 0;
    unsigned int rcvd = xsk_ring_cons__peek(&xsk->rx, BATCH_SIZE, &idx_rx);
    if (!rcvd)
        return;

    uint32_t idx_tx = 0;
    unsigned int reserved = xsk_ring_prod__reserve(&xsk->tx, rcvd, &idx_tx);
    if (reserved < rcvd) {
        xsk->dropped += (rcvd - reserved);
    }

    unsigned int tx_count = 0;

    for (unsigned int i = 0; i < rcvd; i++) {
        struct xdp_desc *rx_desc = xsk_ring_cons__rx_desc(&xsk->rx, idx_rx + i);
        uint64_t addr = rx_desc->addr;
        uint32_t len = rx_desc->len;
        void *pkt = xsk_umem__get_data(xsk->umem->buffer, addr);

        xsk->rx_npkts++;

        if (!packet_allowed(pkt, len, cfg)) {
            xsk->dropped++;
            uint32_t idx_fq;
            while (xsk_ring_prod__reserve(&xsk->umem->fq, 1, &idx_fq) != 1) {}
            *xsk_ring_prod__fill_addr(&xsk->umem->fq, idx_fq) = addr;
            xsk_ring_prod__submit(&xsk->umem->fq, 1);
            continue;
        }

        struct ethhdr *eth = pkt;
        swap_macs(eth);

        if (tx_count < reserved) {
            struct xdp_desc *tx_desc = xsk_ring_prod__tx_desc(&xsk->tx, idx_tx + tx_count);
            tx_desc->addr = addr;
            tx_desc->len = len;
            tx_count++;
            xsk->tx_npkts++;
        } else {
            xsk->dropped++;
            uint32_t idx_fq;
            while (xsk_ring_prod__reserve(&xsk->umem->fq, 1, &idx_fq) != 1) {}
            *xsk_ring_prod__fill_addr(&xsk->umem->fq, idx_fq) = addr;
            xsk_ring_prod__submit(&xsk->umem->fq, 1);
        }
    }

    xsk_ring_cons__release(&xsk->rx, rcvd);

    if (tx_count) {
        xsk_ring_prod__submit(&xsk->tx, tx_count);
        kick_tx(xsk);
    }

    complete_tx(xsk);
}

static int load_bpf_and_xskmap(const char *obj_path, int ifindex, int queue_id, int xsk_fd) {
    struct bpf_object *obj = NULL;
    int prog_fd = -1, map_fd = -1, err;
    struct bpf_program *prog;

    obj = bpf_object__open_file(obj_path, NULL);
    if (libbpf_get_error(obj))
        return -1;

    err = bpf_object__load(obj);
    if (err)
        return -1;

    prog = bpf_object__find_program_by_name(obj, "xdp_sock_prog");
    if (!prog)
        return -1;

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0)
        return -1;

    map_fd = bpf_object__find_map_fd_by_name(obj, "xsks_map");
    if (map_fd < 0)
        return -1;

    __u32 key = queue_id;
    __u32 value = xsk_fd;
    if (bpf_map_update_elem(map_fd, &key, &value, 0) != 0)
        return -1;

    err = bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    if (err)
        return -1;

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -i <ifname> [-q queue] [--udp-port N] [--tcp-port N]\n",
        prog);
}

int main(int argc, char **argv) {
    struct config cfg = {
        .queue_id = 0,
        .xdp_flags = XDP_FLAGS_DRV_MODE,
        .allow_udp_port = 0,
        .allow_tcp_port = 0,
    };

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-i") && i + 1 < argc) {
            strncpy(cfg.ifname, argv[++i], sizeof(cfg.ifname) - 1);
        } else if (!strcmp(argv[i], "-q") && i + 1 < argc) {
            cfg.queue_id = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "--udp-port") && i + 1 < argc) {
            cfg.allow_udp_port = (uint16_t)atoi(argv[++i]);
        } else if (!strcmp(argv[i], "--tcp-port") && i + 1 < argc) {
            cfg.allow_tcp_port = (uint16_t)atoi(argv[++i]);
        } else {
            usage(argv[0]);
            return 1;
        }
    }

    if (!cfg.ifname[0]) {
        usage(argv[0]);
        return 1;
    }

    cfg.ifindex = if_nametoindex(cfg.ifname);
    if (!cfg.ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (bump_memlock_rlimit()) {
        perror("setrlimit");
        return 1;
    }

    struct xsk_umem_info umem = {0};
    struct xsk_socket_info xsk = {0};
    xsk.umem = &umem;

    if (xsk_configure_umem(&umem)) {
        fprintf(stderr, "xsk_configure_umem failed\n");
        return 1;
    }

    if (xsk_populate_fill_ring(&xsk)) {
        fprintf(stderr, "xsk_populate_fill_ring failed\n");
        return 1;
    }

    if (xsk_configure_socket(&xsk, &cfg)) {
        fprintf(stderr, "xsk_configure_socket failed\n");
        return 1;
    }

    if (load_bpf_and_xskmap("xdp_pass_kern.o", cfg.ifindex, cfg.queue_id,
                            xsk_socket__fd(xsk.xsk))) {
        fprintf(stderr, "load_bpf_and_xskmap failed\n");
        return 1;
    }

    struct pollfd fds[] = {
        { .fd = xsk_socket__fd(xsk.xsk), .events = POLLIN }
    };

    while (running) {
        int ret = poll(fds, 1, 1000);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("poll");
            break;
        }

        process_packets(&xsk, &cfg);

        static uint64_t last_rx = 0, last_tx = 0, last_drop = 0;
        if ((xsk.rx_npkts - last_rx) >= 100000 ||
            (xsk.tx_npkts - last_tx) >= 100000 ||
            (xsk.dropped - last_drop) >= 100000) {
            printf("rx=%llu tx=%llu drop=%llu\n",
                   (unsigned long long)xsk.rx_npkts,
                   (unsigned long long)xsk.tx_npkts,
                   (unsigned long long)xsk.dropped);
            last_rx = xsk.rx_npkts;
            last_tx = xsk.tx_npkts;
            last_drop = xsk.dropped;
        }
    }

    printf("final: rx=%llu tx=%llu drop=%llu\n",
           (unsigned long long)xsk.rx_npkts,
           (unsigned long long)xsk.tx_npkts,
           (unsigned long long)xsk.dropped);

    xsk_socket__delete(xsk.xsk);
    xsk_umem__delete(umem.umem);
    free(umem.buffer);
    return 0;
}
