use anyhow::{Context, Result};
use core_affinity::CoreId;
use std::collections::VecDeque;
use std::mem::size_of;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::ptr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

const ETH_P_IP: u16 = 0x0800;
const IPPROTO_UDP: u8 = 17;
const IPPROTO_TCP: u8 = 6;

const FRAME_SIZE: usize = 2048;
const NUM_FRAMES: usize = 4096;
const BATCH_SIZE: usize = 64;

// Simple allowlist example
const ALLOWED_DST_PORT: u16 = 9000;
const FORWARD_IFINDEX: i32 = 3; // set to your egress ifindex

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    version_ihl: u8,
    dscp_ecn: u8,
    total_length: u16,
    identification: u16,
    flags_fragment: u16,
    ttl: u8,
    protocol: u8,
    hdr_checksum: u16,
    src: u32,
    dst: u32,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct UdpHdr {
    src_port: u16,
    dst_port: u16,
    len: u16,
    checksum: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    data_offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

fn be16(x: u16) -> u16 {
    u16::from_be(x)
}

fn be32(x: u32) -> u32 {
    u32::from_be(x)
}

fn parse_ipv4_udp_dst_port(buf: &[u8]) -> Option<u16> {
    if buf.len() < size_of::<EthHdr>() + size_of::<Ipv4Hdr>() {
        return None;
    }

    let eth = unsafe { &*(buf.as_ptr() as *const EthHdr) };
    if be16(eth.ethertype) != ETH_P_IP {
        return None;
    }

    let ip_off = size_of::<EthHdr>();
    let ip = unsafe { &*(buf[ip_off..].as_ptr() as *const Ipv4Hdr) };
    let ihl = ((ip.version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || buf.len() < ip_off + ihl {
        return None;
    }

    if ip.protocol != IPPROTO_UDP {
        return None;
    }

    let udp_off = ip_off + ihl;
    if buf.len() < udp_off + size_of::<UdpHdr>() {
        return None;
    }

    let udp = unsafe { &*(buf[udp_off..].as_ptr() as *const UdpHdr) };
    Some(be16(udp.dst_port))
}

fn parse_ipv4_tuple(buf: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u8, u16, u16)> {
    if buf.len() < size_of::<EthHdr>() + size_of::<Ipv4Hdr>() {
        return None;
    }

    let eth = unsafe { &*(buf.as_ptr() as *const EthHdr) };
    if be16(eth.ethertype) != ETH_P_IP {
        return None;
    }

    let ip_off = size_of::<EthHdr>();
    let ip = unsafe { &*(buf[ip_off..].as_ptr() as *const Ipv4Hdr) };
    let ihl = ((ip.version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || buf.len() < ip_off + ihl {
        return None;
    }

    let src = Ipv4Addr::from(be32(ip.src));
    let dst = Ipv4Addr::from(be32(ip.dst));
    let proto = ip.protocol;

    let l4_off = ip_off + ihl;
    match proto {
        IPPROTO_UDP => {
            if buf.len() < l4_off + size_of::<UdpHdr>() {
                return None;
            }
            let udp = unsafe { &*(buf[l4_off..].as_ptr() as *const UdpHdr) };
            Some((src, dst, proto, be16(udp.src_port), be16(udp.dst_port)))
        }
        IPPROTO_TCP => {
            if buf.len() < l4_off + size_of::<TcpHdr>() {
                return None;
            }
            let tcp = unsafe { &*(buf[l4_off..].as_ptr() as *const TcpHdr) };
            Some((src, dst, proto, be16(tcp.src_port), be16(tcp.dst_port)))
        }
        _ => Some((src, dst, proto, 0, 0)),
    }
}

// Placeholder abstraction. In production, use a mature AF_XDP crate or FFI bindings.
struct Packet {
    data: Vec<u8>,
}

struct XskSocket {
    rxq: VecDeque<Packet>,
    txq: VecDeque<Packet>,
}

impl XskSocket {
    fn open(_ifindex: i32, _queue_id: u32) -> Result<Self> {
        Ok(Self {
            rxq: VecDeque::with_capacity(NUM_FRAMES),
            txq: VecDeque::with_capacity(NUM_FRAMES),
        })
    }

    fn recv_batch(&mut self, out: &mut Vec<Packet>) -> usize {
        let mut n = 0;
        while n < BATCH_SIZE {
            if let Some(pkt) = self.rxq.pop_front() {
                out.push(pkt);
                n += 1;
            } else {
                break;
            }
        }
        n
    }

    fn send_batch(&mut self, pkts: &mut Vec<Packet>) -> usize {
        let mut sent = 0;
        for pkt in pkts.drain(..) {
            if self.txq.len() < NUM_FRAMES {
                self.txq.push_back(pkt);
                sent += 1;
            } else {
                break;
            }
        }
        sent
    }

    fn complete_tx(&mut self) {
        while self.txq.pop_front().is_some() {}
    }
}

fn should_forward(pkt: &[u8]) -> bool {
    match parse_ipv4_udp_dst_port(pkt) {
        Some(port) if port == ALLOWED_DST_PORT => true,
        _ => false,
    }
}

fn pin_to_core(core_id: usize) -> Result<()> {
    let cores = core_affinity::get_core_ids().context("failed to get core ids")?;
    let core = cores
        .into_iter()
        .find(|c| c.id == core_id)
        .with_context(|| format!("core {} not found", core_id))?;
    core_affinity::set_for_current(core);
    Ok(())
}

fn run_service(ingress_ifindex: i32, queue_id: u32, core_id: usize, stop: Arc<AtomicBool>) -> Result<()> {
    pin_to_core(core_id)?;

    let mut xsk = XskSocket::open(ingress_ifindex, queue_id)
        .context("failed to open AF_XDP socket")?;

    let mut rx_batch = Vec::with_capacity(BATCH_SIZE);
    let mut tx_batch = Vec::with_capacity(BATCH_SIZE);

    let mut last_stats = Instant::now();
    let mut rx_pkts: u64 = 0;
    let mut fwd_pkts: u64 = 0;
    let mut drop_pkts: u64 = 0;

    while !stop.load(Ordering::Relaxed) {
        rx_batch.clear();
        let n = xsk.recv_batch(&mut rx_batch);
        if n == 0 {
            std::hint::spin_loop();
            continue;
        }

        rx_pkts += n as u64;

        for pkt in rx_batch.drain(..) {
            if should_forward(&pkt.data) {
                // Example: packet metadata/logging hook
                if let Some((src, dst, proto, sport, dport)) = parse_ipv4_tuple(&pkt.data) {
                    let _ = (src, dst, proto, sport, dport);
                }

                tx_batch.push(pkt);
                fwd_pkts += 1;
            } else {
                drop_pkts += 1;
            }

            if tx_batch.len() >= BATCH_SIZE {
                let _ = xsk.send_batch(&mut tx_batch);
                xsk.complete_tx();
            }
        }

        if !tx_batch.is_empty() {
            let _ = xsk.send_batch(&mut tx_batch);
            xsk.complete_tx();
        }

        if last_stats.elapsed() >= Duration::from_secs(1) {
            eprintln!(
                "rx={} fwd={} drop={}",
                rx_pkts, fwd_pkts, drop_pkts
            );
            last_stats = Instant::now();
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    let stop = Arc::new(AtomicBool::new(false));

    // In production, install signal handlers for SIGINT/SIGTERM.
    let ingress_ifindex = 2; // set to your ingress ifindex
    let queue_id = 0;
    let core_id = 0;

    run_service(ingress_ifindex, queue_id, core_id, stop)
}
