struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent: u16,
}

#[derive(Debug)]
struct Ring {
    map: *mut u8,
    map_len: usize,
    producer: *mut u32,
    consumer: *mut u32,
    desc: *mut XdpDesc,
    size: u32,
    mask: u32,
}

unsafe impl Send for Ring {}
unsafe impl Sync for Ring {}

impl Ring {
    unsafe fn from_mmap(fd: RawFd, offset: &XdpRingOffset, pgoff: i64, size: u32) -> Result<Self> {
        let desc_bytes = (size as usize) * size_of::<XdpDesc>();
        let map_len = offset.desc as usize + desc_bytes;
        let map = mmap(
            null_mut(),
            map_len,
            PROT_READ | PROT_WRITE,
            MAP_SHARED | MAP_POPULATE,
            fd,
            pgoff,
        );
        if map == MAP_FAILED {
            return Err(anyhow!("mmap failed"));
        }

        Ok(Self {
            map: map as *mut u8,
            map_len,
            producer: (map as *mut u8).add(offset.producer as usize) as *mut u32,
            consumer: (map as *mut u8).add(offset.consumer as usize) as *mut u32,
            desc: (map as *mut u8).add(offset.desc as usize) as *mut XdpDesc,
            size,
            mask: size - 1,
        })
    }

    #[inline(always)]
    unsafe fn prod(&self) -> u32 {
        ptr::read_volatile(self.producer)
    }

    #[inline(always)]
    unsafe fn cons(&self) -> u32 {
        ptr::read_volatile(self.consumer)
    }

    #[inline(always)]
    unsafe fn set_prod(&self, v: u32) {
        ptr::write_volatile(self.producer, v);
    }

    #[inline(always)]
    unsafe fn set_cons(&self, v: u32) {
        ptr::write_volatile(self.consumer, v);
    }

    #[inline(always)]
    unsafe fn desc_at(&self, idx: u32) -> *mut XdpDesc {
        self.desc.add((idx & self.mask) as usize)
    }
}

impl Drop for Ring {
    fn drop(&mut self) {
        unsafe {
            let _ = munmap(self.map as *mut c_void, self.map_len);
        }
    }
}

#[derive(Debug)]
struct Umem {
    area: *mut u8,
    len: usize,
}

unsafe impl Send for Umem {}
unsafe impl Sync for Umem {}

impl Umem {
    fn new() -> Result<Self> {
        unsafe {
            let area = mmap(
                null_mut(),
                UMEM_SIZE,
                PROT_READ | PROT_WRITE,
                MAP_PRIVATE | MAP_POPULATE | libc::MAP_ANONYMOUS,
                -1,
                0,
            );
            if area == MAP_FAILED {
                return Err(anyhow!("UMEM mmap failed"));
            }
            Ok(Self {
                area: area as *mut u8,
                len: UMEM_SIZE,
            })
        }
    }

    #[inline(always)]
    unsafe fn frame_ptr(&self, addr: u64) -> *mut u8 {
        self.area.add(addr as usize)
    }
}

impl Drop for Umem {
    fn drop(&mut self) {
        unsafe {
            let _ = munmap(self.area as *mut c_void, self.len);
        }
    }
}

struct Xsk {
    fd: RawFd,
    rx: Ring,
    tx: Ring,
    fr: Ring,
    cr: Ring,
    umem: Umem,
}

impl Drop for Xsk {
    fn drop(&mut self) {
        unsafe {
            let _ = close(self.fd);
        }
    }
}

fn ifindex(name: &str) -> Result<u32> {
    let c = CString::new(name)?;
    let idx = unsafe { if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(anyhow!("if_nametoindex failed for {}", name))
    } else {
        Ok(idx)
    }
}

fn create_xsk(ifname: &str, queue_id: u32) -> Result<Xsk> {
    unsafe {
        let fd = socket(AF_XDP, SOCK_RAW, 0);
        if fd < 0 {
            return Err(anyhow!("socket(AF_XDP) failed"));
        }

        let umem = Umem::new()?;

        let reg = XdpUmemReg {
            addr: umem.area as u64,
            len: UMEM_SIZE as u64,
            chunk_size: FRAME_SIZE as u32,
            headroom: 0,
            flags: 0,
        };

        let rc = setsockopt(
            fd,
            SOL_XDP,
            XDP_UMEM_REG,
            &reg as *const _ as *const c_void,
            size_of::<XdpUmemReg>() as u32,
        );
        if rc != 0 {
            return Err(anyhow!("setsockopt XDP_UMEM_REG failed"));
        }

        let ring_size = RING_SIZE as i32;
        for opt in [
            XDP_RX_RING,
            XDP_TX_RING,
            XDP_UMEM_FILL_RING,
            XDP_UMEM_COMPLETION_RING,
        ] {
            let rc = setsockopt(
                fd,
                SOL_XDP,
                opt,
                &ring_size as *const _ as *const c_void,
                size_of::<i32>() as u32,
            );
            if rc != 0 {
                return Err(anyhow!("setsockopt ring size failed for opt {}", opt));
            }
        }

        let mut offsets: XdpMmapOffsets = zeroed();
        let mut offsets_len = size_of::<XdpMmapOffsets>() as libc::socklen_t;
        let rc = libc::getsockopt(
            fd,
            SOL_XDP,
            XDP_MMAP_OFFSETS,
            &mut offsets as *mut _ as *mut c_void,
            &mut offsets_len,
        );
        if rc != 0 {
            return Err(anyhow!("getsockopt XDP_MMAP_OFFSETS failed"));
        }

        let rx = Ring::from_mmap(fd, &offsets.rx, XDP_PGOFF_RX_RING, RING_SIZE)?;
        let tx = Ring::from_mmap(fd, &offsets.tx, XDP_PGOFF_TX_RING, RING_SIZE)?;
        let fr = Ring::from_mmap(fd, &offsets.fr, XDP_PGOFF_FILL_RING, RING_SIZE)?;
        let cr = Ring::from_mmap(fd, &offsets.cr, XDP_PGOFF_UMEM_COMPLETION_RING, RING_SIZE)?;

        let idx = ifindex(ifname)?;
        let mut sxdp: sockaddr_xdp = zeroed();
        sxdp.sxdp_family = AF_XDP as u16;
        sxdp.sxdp_ifindex = idx;
        sxdp.sxdp_queue_id = queue_id;
        sxdp.sxdp_flags = 0;

        let rc = bind(
            fd,
            &sxdp as *const _ as *const sockaddr,
            size_of::<sockaddr_xdp>() as u32,
        );
        if rc != 0 {
            return Err(anyhow!("bind(AF_XDP) failed"));
        }

        // Seed fill ring with all frames.
        let mut prod = fr.prod();
        for i in 0..RING_SIZE {
            let d = fr.desc_at(prod + i);
            (*d).addr = (i as usize * FRAME_SIZE) as u64;
            (*d).len = 0;
            (*d).options = 0;
        }
        compiler_fence(Ordering::Release);
        fr.set_prod(prod + RING_SIZE);

        Ok(Xsk { fd, rx, tx, fr, cr, umem })
    }
}

#[inline(always)]
fn be16(x: u16) -> u16 {
    u16::from_be(x)
}

#[inline(always)]
unsafe fn parse_and_filter(pkt: *const u8, len: usize, allow_udp_dst: Option<u16>) -> bool {
    if len < size_of::<EthHdr>() {
        return false;
    }

    let eth = &*(pkt as *const EthHdr);
    let ethertype = be16(eth.ethertype);
    if ethertype != 0x0800 {
        return false; // only IPv4
    }

    let ip_ptr = pkt.add(size_of::<EthHdr>());
    if len < size_of::<EthHdr>() + size_of::<Ipv4Hdr>() {
        return false;
    }

    let ip = &*(ip_ptr as *const Ipv4Hdr);
    let ihl = ((ip.version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 {
        return false;
    }
    if len < size_of::<EthHdr>() + ihl {
        return false;
    }

    match ip.protocol {
        17 => {
            let udp_ptr = ip_ptr.add(ihl);
            if len < size_of::<EthHdr>() + ihl + size_of::<UdpHdr>() {
                return false;
            }
            let udp = &*(udp_ptr as *const UdpHdr);
            if let Some(port) = allow_udp_dst {
                be16(udp.dst_port) == port
            } else {
                true
            }
        }
        6 => true, // allow TCP
        _ => false,
    }
}

unsafe fn recycle_completions(xsk: &Xsk) {
    let cons = xsk.cr.cons();
    let prod = xsk.cr.prod();
    let n = prod.wrapping_sub(cons);
    if n == 0 {
        return;
    }

    let fr_prod = xsk.fr.prod();
    for i in 0..n {
        let cdesc = xsk.cr.desc_at(cons + i);
        let fdesc = xsk.fr.desc_at(fr_prod + i);
        (*fdesc).addr = (*cdesc).addr;
        (*fdesc).len = 0;
        (*fdesc).options = 0;
    }

    compiler_fence(Ordering::Release);
    xsk.cr.set_cons(cons + n);
    xsk.fr.set_prod(fr_prod + n);
}

unsafe fn kick_tx(fd: RawFd) {
    let _ = libc::sendto(fd, ptr::null(), 0, libc::MSG_DONTWAIT, ptr::null(), 0);
}

unsafe fn forward_loop(rx_xsk: &Xsk, tx_xsk: &Xsk, allow_udp_dst: Option<u16>) -> Result<()> {
    loop {
        recycle_completions(tx_xsk);

        let rx_cons = rx_xsk.rx.cons();
        let rx_prod = rx_xsk.rx.prod();
        let available = rx_prod.wrapping_sub(rx_cons);
        if available == 0 {
            let mut pfd = pollfd {
                fd: rx_xsk.fd,
                events: POLLIN,
                revents: 0,
            };
            let rc = poll(&mut pfd, 1, 1);
            if rc < 0 {
                return Err(anyhow!("poll failed"));
            }
            continue;
        }

        let batch = available.min(BATCH_SIZE as u32);
        let tx_prod = tx_xsk.tx.prod();
        let mut forwarded = 0u32;
        let mut dropped = 0u32;

        for i in 0..batch {
            let rxd = *rx_xsk.rx.desc_at(rx_cons + i);
            let pkt = rx_xsk.umem.frame_ptr(rxd.addr);
            let len = rxd.len as usize;

            if parse_and_filter(pkt, len, allow_udp_dst) {
                let txd = tx_xsk.tx.desc_at(tx_prod + forwarded);
                (*txd).addr = rxd.addr;
                (*txd).len = rxd.len;
                (*txd).options = 0;
                forwarded += 1;
            } else {
                let fr_prod = rx_xsk.fr.prod();
                let fdesc = rx_xsk.fr.desc_at(fr_prod);
                (*fdesc).addr = rxd.addr;
                (*fdesc).len = 0;
                (*fdesc).options = 0;
                compiler_fence(Ordering::Release);
                rx_xsk.fr.set_prod(fr_prod + 1);
                dropped += 1;
            }
        }

        compiler_fence(Ordering::Release);
        rx_xsk.rx.set_cons(rx_cons + batch);

        if forwarded > 0 {
            compiler_fence(Ordering::Release);
            tx_xsk.tx.set_prod(tx_prod + forwarded);
            kick_tx(tx_xsk.fd);
        }

        let _ = dropped;
    }
}

fn pin_to_core(core: usize) -> Result<()> {
    let cores = core_affinity::get_core_ids().ok_or_else(|| anyhow!("no core ids"))?;
    let core_id = cores
        .into_iter()
        .find(|c: &CoreId| c.id == core)
        .ok_or_else(|| anyhow!("core {} not found", core))?;
    core_affinity::set_for_current(core_id);
    Ok(())
}

fn main() -> Result<()> {
    let rx_if = std::env::args().nth(1).context("missing rx interface")?;
    let tx_if = std::env::args().nth(2).context("missing tx interface")?;
    let queue_id: u32 = std::env::args()
        .nth(3)
        .unwrap_or_else(|| "0".to_string())
        .parse()
        .context("invalid queue id")?;
    let allow_udp_dst = std::env::args()
        .nth(4)
        .map(|s| s.parse::<u16>())
        .transpose()
        .context("invalid UDP port")?;

    pin_to_core(0)?;

    let rx_xsk = create_xsk(&rx_if, queue_id).context("create rx xsk failed")?;
    let tx_xsk = create_xsk(&tx_if, queue_id).context("create tx xsk failed")?;

    unsafe { forward_loop(&rx_xsk, &tx_xsk, allow_udp_dst) }
}
```

