## File: `main.c`

```c
#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <arpa/inet.h>

#include <rte_common.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_ether.h>
#include <rte_cycles.h>
#include <rte_branch_prediction.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024

#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

static volatile bool force_quit = false;

static struct rte_mempool *mbuf_pool = NULL;

struct app_config {
    uint16_t port_in;
    uint16_t port_out;
    uint32_t blocked_src_ip; // network byte order, 0 = disabled
};

static struct app_config g_cfg = {
    .port_in = 0,
    .port_out = 1,
    .blocked_src_ip = 0
};

static void
signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        force_quit = true;
    }
}

static int
port_init(uint16_t port, struct rte_mempool *mp)
{
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1, tx_rings = 1;
    int retval;
    uint16_t q;

    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    retval = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (retval < 0)
        return retval;

    for (q = 0; q < rx_rings; q++) {
        retval = rte_eth_rx_queue_setup(
            port, q, RX_RING_SIZE,
            rte_eth_dev_socket_id(port), NULL, mp);
        if (retval < 0)
            return retval;
    }

    for (q = 0; q < tx_rings; q++) {
        retval = rte_eth_tx_queue_setup(
            port, q, TX_RING_SIZE,
            rte_eth_dev_socket_id(port), NULL);
        if (retval < 0)
            return retval;
    }

    retval = rte_eth_dev_start(port);
    if (retval < 0)
        return retval;

    struct rte_ether_addr addr;
    rte_eth_macaddr_get(port, &addr);
    printf("Port %u MAC: %02X:%02X:%02X:%02X:%02X:%02X\n",
           port,
           addr.addr_bytes[0], addr.addr_bytes[1], addr.addr_bytes[2],
           addr.addr_bytes[3], addr.addr_bytes[4], addr.addr_bytes[5]);

    retval = rte_eth_promiscuous_enable(port);
    if (retval != 0) {
        fprintf(stderr, "Warning: failed to enable promiscuous mode on port %u\n", port);
    }

    return 0;
}

static inline bool
packet_allowed(struct rte_mbuf *m, const struct app_config *cfg)
{
    struct rte_ether_hdr *eth;
    struct rte_ipv4_hdr *ip;
    uint16_t ether_type;

    if (unlikely(rte_pktmbuf_data_len(m) < sizeof(struct rte_ether_hdr)))
        return false;

    eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    ether_type = rte_be_to_cpu_16(eth->ether_type);

    if (ether_type != RTE_ETHER_TYPE_IPV4)
        return false;

    if (unlikely(rte_pktmbuf_data_len(m) < sizeof(struct rte_ether_hdr) + sizeof(struct rte_ipv4_hdr)))
        return false;

    ip = (struct rte_ipv4_hdr *)(eth + 1);

    if (cfg->blocked_src_ip != 0 && ip->src_addr == cfg->blocked_src_ip)
        return false;

    return true;
}

static inline void
process_burst(uint16_t port_in, uint16_t port_out, const struct app_config *cfg)
{
    struct rte_mbuf *bufs[BURST_SIZE];
    struct rte_mbuf *tx_bufs[BURST_SIZE];
    uint16_t nb_rx, nb_tx;
    uint16_t tx_count = 0;

    nb_rx = rte_eth_rx_burst(port_in, 0, bufs, BURST_SIZE);
    if (unlikely(nb_rx == 0))
        return;

    for (uint16_t i = 0; i < nb_rx; i++) {
        struct rte_mbuf *m = bufs[i];

        if (packet_allowed(m, cfg)) {
            tx_bufs[tx_count++] = m;
        } else {
            rte_pktmbuf_free(m);
        }
    }

    if (likely(tx_count > 0)) {
        nb_tx = rte_eth_tx_burst(port_out, 0, tx_bufs, tx_count);

        if (unlikely(nb_tx < tx_count)) {
            for (uint16_t i = nb_tx; i < tx_count; i++) {
                rte_pktmbuf_free(tx_bufs[i]);
            }
        }
    }
}

static int
parse_ipv4(const char *s, uint32_t *out_be)
{
    struct in_addr addr;
    if (inet_pton(AF_INET, s, &addr) != 1)
        return -1;
    *out_be = addr.s_addr;
    return 0;
}

int
main(int argc, char *argv[])
{
    int ret;
    uint16_t nb_ports;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    if (argc >= 1) {
        g_cfg.port_in = (uint16_t)atoi(argv[0]);
    }
    if (argc >= 2) {
        g_cfg.port_out = (uint16_t)atoi(argv[1]);
    }
    if (argc >= 3) {
        if (parse_ipv4(argv[2], &g_cfg.blocked_src_ip) != 0) {
            rte_exit(EXIT_FAILURE, "Invalid blocked source IP: %s\n", argv[2]);
        }
    }

    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 2) {
        rte_exit(EXIT_FAILURE, "Need at least 2 DPDK ports\n");
    }

    if (g_cfg.port_in >= nb_ports || g_cfg.port_out >= nb_ports) {
        rte_exit(EXIT_FAILURE, "Invalid port ids: in=%u out=%u available=%u\n",
                 g_cfg.port_in, g_cfg.port_out, nb_ports);
    }

    mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL",
        NUM_MBUFS * nb_ports,
        MBUF_CACHE_SIZE,
        0,
        RTE_MBUF_DEFAULT_BUF_SIZE,
        rte_socket_id());

    if (mbuf_pool == NULL) {
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");
    }

    if (port_init(g_cfg.port_in, mbuf_pool) != 0) {
        rte_exit(EXIT_FAILURE, "Cannot init input port %" PRIu16 "\n", g_cfg.port_in);
    }

    if (port_init(g_cfg.port_out, mbuf_pool) != 0) {
        rte_exit(EXIT_FAILURE, "Cannot init output port %" PRIu16 "\n", g_cfg.port_out);
    }

    printf("Forwarding from port %u -> port %u\n", g_cfg.port_in, g_cfg.port_out);
    if (g_cfg.blocked_src_ip != 0) {
        struct in_addr a = { .s_addr = g_cfg.blocked_src_ip };
        printf("Blocking source IPv4: %s\n", inet_ntoa(a));
    }

    while (!force_quit) {
        process_burst(g_cfg.port_in, g_cfg.port_out, &g_cfg);
    }

    printf("Shutting down...\n");
    rte_eth_dev_stop(g_cfg.port_in);
    rte_eth_dev_stop(g_cfg.port_out);
    rte_eth_dev_close(g_cfg.port_in);
    rte_eth_dev_close(g_cfg.port_out);

    return 0;
}
