## Example: `ultra_low_latency_filter_forward.c`

```c
// ultra_low_latency_filter_forward.c
//
// Safe, high-performance packet filter/forwarder using DPDK.
// Example behavior:
//   - Forward only IPv4 UDP packets destined to port 9000
//   - Drop everything else
//
// Build example:
//   cc -O3 -march=native ultra_low_latency_filter_forward.c -o ulfwd \
//      $(pkg-config --cflags --libs libdpdk)
//
// Run example:
//   sudo ./ulfwd -l 0-1 -n 4 -- -p 0x3
//
// Notes:
//   - Assumes two ports: port 0 <-> port 1
//   - Single RX/TX queue per port
//   - Single worker loop for simplicity

#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <arpa/inet.h>

#include <rte_common.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_udp.h>
#include <rte_tcp.h>
#include <rte_ether.h>
#include <rte_cycles.h>
#include <rte_branch_prediction.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8192
#define MBUF_CACHE_SIZE 256
#define BURST_SIZE 32

static volatile bool force_quit = false;

struct filter_config {
    uint16_t forward_udp_dst_port;   // e.g. 9000
    uint32_t allow_dst_ip_be;        // 0 means any
    uint32_t allow_src_ip_be;        // 0 means any
};

static struct filter_config g_filter = {
    .forward_udp_dst_port = 9000,
    .allow_dst_ip_be = 0,
    .allow_src_ip_be = 0,
};

static void handle_signal(int sig) {
    (void)sig;
    force_quit = true;
}

static inline int
port_init(uint16_t port, struct rte_mempool *mbuf_pool) {
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1, tx_rings = 1;
    int retval;
    uint16_t q;

    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    retval = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (retval < 0)
        return retval;

    for (q = 0; q < rx_rings; q++) {
        retval = rte_eth_rx_queue_setup(
            port, q, RX_RING_SIZE,
            rte_eth_dev_socket_id(port),
            NULL,
            mbuf_pool
        );
        if (retval < 0)
            return retval;
    }

    for (q = 0; q < tx_rings; q++) {
        retval = rte_eth_tx_queue_setup(
            port, q, TX_RING_SIZE,
            rte_eth_dev_socket_id(port),
            NULL
        );
        if (retval < 0)
            return retval;
    }

    retval = rte_eth_dev_start(port);
    if (retval < 0)
        return retval;

    rte_eth_promiscuous_enable(port);

    struct rte_ether_addr addr;
    rte_eth_macaddr_get(port, &addr);
    printf("Port %u MAC: %02X:%02X:%02X:%02X:%02X:%02X\n",
           port,
           addr.addr_bytes[0], addr.addr_bytes[1], addr.addr_bytes[2],
           addr.addr_bytes[3], addr.addr_bytes[4], addr.addr_bytes[5]);

    return 0;
}

static inline bool
packet_allowed(struct rte_mbuf *m, const struct filter_config *cfg) {
    struct rte_ether_hdr *eth;
    struct rte_ipv4_hdr *ip;
    uint16_t ether_type;

    if (unlikely(rte_pktmbuf_data_len(m) < sizeof(struct rte_ether_hdr)))
        return false;

    eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    ether_type = rte_be_to_cpu_16(eth->ether_type);

    if (ether_type != RTE_ETHER_TYPE_IPV4)
        return false;

    if (unlikely(rte_pktmbuf_data_len(m) < sizeof(struct rte_ether_hdr) + sizeof(struct rte_ipv4_hdr)))
        return false;

    ip = (struct rte_ipv4_hdr *)(eth + 1);

    if (cfg->allow_src_ip_be && ip->src_addr != cfg->allow_src_ip_be)
        return false;

    if (cfg->allow_dst_ip_be && ip->dst_addr != cfg->allow_dst_ip_be)
        return false;

    if (ip->next_proto_id != IPPROTO_UDP)
        return false;

    uint8_t ihl = (uint8_t)((ip->version_ihl & 0x0F) * 4);
    if (unlikely(ihl < sizeof(struct rte_ipv4_hdr)))
        return false;

    if (unlikely(rte_pktmbuf_data_len(m) <
                 sizeof(struct rte_ether_hdr) + ihl + sizeof(struct rte_udp_hdr)))
        return false;

    struct rte_udp_hdr *udp =
        (struct rte_udp_hdr *)((uint8_t *)ip + ihl);

    if (rte_be_to_cpu_16(udp->dst_port) != cfg->forward_udp_dst_port)
        return false;

    return true;
}

static inline uint16_t
flush_tx(uint16_t tx_port, struct rte_mbuf **tx_bufs, uint16_t tx_count) {
    if (tx_count == 0)
        return 0;

    uint16_t sent = rte_eth_tx_burst(tx_port, 0, tx_bufs, tx_count);

    if (unlikely(sent < tx_count)) {
        for (uint16_t i = sent; i < tx_count; i++) {
            rte_pktmbuf_free(tx_bufs[i]);
        }
    }

    return 0;
}

static void
main_loop(uint16_t port0, uint16_t port1) {
    struct rte_mbuf *rx_bufs[BURST_SIZE];
    struct rte_mbuf *tx_bufs_p0[BURST_SIZE];
    struct rte_mbuf *tx_bufs_p1[BURST_SIZE];
    uint16_t tx_count_p0 = 0;
    uint16_t tx_count_p1 = 0;

    const uint64_t drain_tsc = rte_get_tsc_hz() / 1000000; // ~1us
    uint64_t prev_tsc = rte_rdtsc();

    while (!force_quit) {
        uint64_t now = rte_rdtsc();
        if (unlikely(now - prev_tsc > drain_tsc)) {
            flush_tx(port0, tx_bufs_p0, tx_count_p0);
            flush_tx(port1, tx_bufs_p1, tx_count_p1);
            tx_count_p0 = 0;
            tx_count_p1 = 0;
            prev_tsc = now;
        }

        // RX from port0 -> maybe forward to port1
        uint16_t nb_rx = rte_eth_rx_burst(port0, 0, rx_bufs, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = rx_bufs[i];
            if (likely(packet_allowed(m, &g_filter))) {
                tx_bufs_p1[tx_count_p1++] = m;
                if (unlikely(tx_count_p1 == BURST_SIZE)) {
                    flush_tx(port1, tx_bufs_p1, tx_count_p1);
                    tx_count_p1 = 0;
                }
            } else {
                rte_pktmbuf_free(m);
            }
        }

        // RX from port1 -> maybe forward to port0
        nb_rx = rte_eth_rx_burst(port1, 0, rx_bufs, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = rx_bufs[i];
            if (likely(packet_allowed(m, &g_filter))) {
                tx_bufs_p0[tx_count_p0++] = m;
                if (unlikely(tx_count_p0 == BURST_SIZE)) {
                    flush_tx(port0, tx_bufs_p0, tx_count_p0);
                    tx_count_p0 = 0;
                }
            } else {
                rte_pktmbuf_free(m);
            }
        }
    }

    flush_tx(port0, tx_bufs_p0, tx_count_p0);
    flush_tx(port1, tx_bufs_p1, tx_count_p1);
}

static uint32_t
parse_portmask(const char *portmask) {
    char *end = NULL;
    unsigned long pm = strtoul(portmask, &end, 16);
    if (end == NULL || *end != '\0')
        return 0;
    return (uint32_t)pm;
}

int main(int argc, char **argv) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Failed to initialize EAL\n");

    argc -= ret;
    argv += ret;

    uint32_t portmask = 0x3; // default ports 0 and 1 enabled

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-p") && i + 1 < argc) {
            portmask = parse_portmask(argv[++i]);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint16_t nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 2)
        rte_exit(EXIT_FAILURE, "Need at least 2 DPDK ports\n");

    uint16_t ports[2];
    uint16_t found = 0;
    RTE_ETH_FOREACH_DEV(ret) {
        if (portmask & (1u << ret)) {
            ports[found++] = (uint16_t)ret;
            if (found == 2)
                break;
        }
    }

    if (found < 2)
        rte_exit(EXIT_FAILURE, "Portmask must enable at least 2 ports\n");

    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL",
        NUM_MBUFS * nb_ports,
        MBUF_CACHE_SIZE,
        0,
        RTE_MBUF_DEFAULT_BUF_SIZE,
        rte_socket_id()
    );

    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    if (port_init(ports[0], mbuf_pool) != 0)
        rte_exit(EXIT_FAILURE, "Cannot init port %" PRIu16 "\n", ports[0]);

    if (port_init(ports[1], mbuf_pool) != 0)
        rte_exit(EXIT_FAILURE, "Cannot init port %" PRIu16 "\n", ports[1]);

    printf("Forwarding allowed IPv4/UDP dport=%u between port %u <-> port %u\n",
           g_filter.forward_udp_dst_port, ports[0], ports[1]);

    main_loop(ports[0], ports[1]);

    rte_eth_dev_stop(ports[0]);
    rte_eth_dev_stop(ports[1]);
    rte_eth_dev_close(ports[0]);
    rte_eth_dev_close(ports[1]);

    return 0;
}
```

