```rust
use anyhow::{anyhow, Context, Result};
use parking_lot::RwLock;
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;
use tokio::signal;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct FilterConfig {
    allowed_ethertypes: HashSet<u16>,
    allowed_src_ips: HashSet<Ipv4Addr>,
    allowed_dst_ips: HashSet<Ipv4Addr>,
    allowed_tcp_ports: HashSet<u16>,
    allowed_udp_ports: HashSet<u16>,
}

impl Default for FilterConfig {
    fn default() -> Self {
        let mut allowed_ethertypes = HashSet::new();
        allowed_ethertypes.insert(EtherTypes::Ipv4.0);

        Self {
            allowed_ethertypes,
            allowed_src_ips: HashSet::new(),
            allowed_dst_ips: HashSet::new(),
            allowed_tcp_ports: HashSet::new(),
            allowed_udp_ports: HashSet::new(),
        }
    }
}

#[derive(Default)]
struct Stats {
    rx_packets: AtomicU64,
    rx_bytes: AtomicU64,
    forwarded_packets: AtomicU64,
    forwarded_bytes: AtomicU64,
    dropped_packets: AtomicU64,
    parse_errors: AtomicU64,
}

impl Stats {
    fn snapshot(&self) -> StatsSnapshot {
        StatsSnapshot {
            rx_packets: self.rx_packets.load(Ordering::Relaxed),
            rx_bytes: self.rx_bytes.load(Ordering::Relaxed),
            forwarded_packets: self.forwarded_packets.load(Ordering::Relaxed),
            forwarded_bytes: self.forwarded_bytes.load(Ordering::Relaxed),
            dropped_packets: self.dropped_packets.load(Ordering::Relaxed),
            parse_errors: self.parse_errors.load(Ordering::Relaxed),
        }
    }
}

#[derive(Debug, Serialize)]
struct StatsSnapshot {
    rx_packets: u64,
    rx_bytes: u64,
    forwarded_packets: u64,
    forwarded_bytes: u64,
    dropped_packets: u64,
    parse_errors: u64,
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .ok_or_else(|| anyhow!("interface not found: {}", name))
}

fn packet_allowed(frame: &[u8], cfg: &FilterConfig) -> Result<bool> {
    let eth = EthernetPacket::new(frame).ok_or_else(|| anyhow!("invalid ethernet frame"))?;
    let ethertype = eth.get_ethertype().0;

    if !cfg.allowed_ethertypes.is_empty() && !cfg.allowed_ethertypes.contains(&ethertype) {
        return Ok(false);
    }

    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return Ok(true);
    }

    let ip = Ipv4Packet::new(eth.payload()).ok_or_else(|| anyhow!("invalid ipv4 packet"))?;

    if !cfg.allowed_src_ips.is_empty() && !cfg.allowed_src_ips.contains(&ip.get_source()) {
        return Ok(false);
    }

    if !cfg.allowed_dst_ips.is_empty() && !cfg.allowed_dst_ips.contains(&ip.get_destination()) {
        return Ok(false);
    }

    match ip.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ip.payload()).ok_or_else(|| anyhow!("invalid tcp packet"))?;
            if !cfg.allowed_tcp_ports.is_empty()
                && !cfg.allowed_tcp_ports.contains(&tcp.get_destination())
                && !cfg.allowed_tcp_ports.contains(&tcp.get_source())
            {
                return Ok(false);
            }
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ip.payload()).ok_or_else(|| anyhow!("invalid udp packet"))?;
            if !cfg.allowed_udp_ports.is_empty()
                && !cfg.allowed_udp_ports.contains(&udp.get_destination())
                && !cfg.allowed_udp_ports.contains(&udp.get_source())
            {
                return Ok(false);
            }
        }
        _ => {}
    }

    Ok(true)
}

fn open_channel(
    iface: &NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;
    config.promiscuous = true;

    match datalink::channel(iface, config).context("failed to open datalink channel")? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => Err(anyhow!("unsupported channel type")),
    }
}

fn forwarding_loop(
    in_iface: NetworkInterface,
    out_iface: NetworkInterface,
    filter_cfg: Arc<RwLock<FilterConfig>>,
    stats: Arc<Stats>,
) -> Result<()> {
    let (_in_tx, mut rx) = open_channel(&in_iface)?;
    let (mut tx, _out_rx) = open_channel(&out_iface)?;

    loop {
        match rx.next() {
            Ok(frame) => {
                stats.rx_packets.fetch_add(1, Ordering::Relaxed);
                stats.rx_bytes
                    .fetch_add(frame.len() as u64, Ordering::Relaxed);

                let allowed = match packet_allowed(frame, &filter_cfg.read()) {
                    Ok(v) => v,
                    Err(_) => {
                        stats.parse_errors.fetch_add(1, Ordering::Relaxed);
                        false
                    }
                };

                if !allowed {
                    stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    continue;
                }

                match tx.send_to(frame, None) {
                    Some(Ok(())) => {
                        stats.forwarded_packets.fetch_add(1, Ordering::Relaxed);
                        stats
                            .forwarded_bytes
                            .fetch_add(frame.len() as u64, Ordering::Relaxed);
                    }
                    Some(Err(_)) | None => {
                        stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(_) => {
                std::hint::spin_loop();
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let in_iface_name = std::env::args()
        .nth(1)
        .ok_or_else(|| anyhow!("usage: packet_forwarder <in_iface> <out_iface>"))?;
    let out_iface_name = std::env::args()
        .nth(2)
        .ok_or_else(|| anyhow!("usage: packet_forwarder <in_iface> <out_iface>"))?;

    let in_iface = find_interface(&in_iface_name)?;
    let out_iface = find_interface(&out_iface_name)?;

    let filter_cfg = Arc::new(RwLock::new(FilterConfig::default()));
    let stats = Arc::new(Stats::default());

    {
        let mut cfg = filter_cfg.write();
        cfg.allowed_ethertypes.insert(EtherTypes::Ipv4.0);
        cfg.allowed_tcp_ports.insert(80);
        cfg.allowed_tcp_ports.insert(443);
        cfg.allowed_udp_ports.insert(53);
    }

    let stats_clone = Arc::clone(&stats);
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(Duration::from_secs(1)).await;
            let snap = stats_clone.snapshot();
            println!("{}", serde_json::to_string(&snap).unwrap());
        }
    });

    let filter_cfg_clone = Arc::clone(&filter_cfg);
    let stats_clone = Arc::clone(&stats);
    let in_iface_clone = in_iface.clone();
    let out_iface_clone = out_iface.clone();

    let worker = thread::spawn(move || {
        if let Err(e) = forwarding_loop(in_iface_clone, out_iface_clone, filter_cfg_clone, stats_clone) {
            eprintln!("forwarding loop error: {e:#}");
        }
    });

    signal::ctrl_c().await?;
    eprintln!("shutdown requested");

    let _ = worker.join();
    Ok(())
}
