use std::ptr::{null, null_mut};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};

const ETH_P_IP: u16 = 0x0800;
const ETH_P_IPV6: u16 = 0x86DD;
const ETH_HDR_LEN: usize = 14;
const IPV4_MIN_HDR_LEN: usize = 20;
const UDP_PROTO: u8 = 17;
const TCP_PROTO: u8 = 6;

const SOL_XDP: c_int = 283;
const XDP_UMEM_REG: c_int = 1;
const XDP_UMEM_FILL_RING: c_int = 2;
const XDP_UMEM_COMPLETION_RING: c_int = 3;
const XDP_RX_RING: c_int = 4;
const XDP_TX_RING: c_int = 5;
const XDP_MMAP_OFFSETS: c_int = 6;
const XDP_STATISTICS: c_int = 7;
const XDP_OPTIONS: c_int = 8;

const XDP_SHARED_UMEM: u16 = 1 << 0;
const XDP_COPY: u16 = 1 << 1;
const XDP_ZEROCOPY: u16 = 1 << 2;
const XDP_USE_NEED_WAKEUP: u16 = 1 << 3;

const XDP_PGOFF_RX_RING: i64 = 0;
const XDP_PGOFF_TX_RING: i64 = 0x80000000;
const XDP_UMEM_PGOFF_FILL_RING: i64 = 0x100000000;
const XDP_UMEM_PGOFF_COMPLETION_RING: i64 = 0x180000000;

const FRAME_SIZE: usize = 2048;
const NUM_FRAMES: usize = 4096;
const BATCH_SIZE: usize = 64;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpRingOffset {
    producer: u64,
    consumer: u64,
    desc: u64,
    flags: u64,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpMmapOffsets {
    rx: XdpRingOffset,
    tx: XdpRingOffset,
    fr: XdpRingOffset,
    cr: XdpRingOffset,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpUmemReg {
    addr: u64,
    len: u64,
    chunk_size: u32,
    headroom: u32,
    flags: u32,
    tx_metadata_len: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct SockAddrXdp {
    sxdp_family: u16,
    sxdp_flags: u16,
    sxdp_ifindex: u32,
    sxdp_queue_id: u32,
    sxdp_shared_umem_fd: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct XdpDesc {
    addr: u64,
    len: u32,
    options: u32,
}

#[repr(C)]
struct Ring {
    producer: *mut u32,
    consumer: *mut u32,
    flags: *mut u32,
    desc: *mut XdpDesc,
    mask: u32,
    size: u32,
    map: *mut c_void,
    map_len: usize,
}

impl Default for Ring {
    fn default() -> Self {
        Self {
            producer: null_mut(),
            consumer: null_mut(),
            flags: null_mut(),
            desc: null_mut(),
            mask: 0,
            size: 0,
            map: null_mut(),
            map_len: 0,
        }
    }
}

#[repr(C)]
struct U64Ring {
    producer: *mut u32,
    consumer: *mut u32,
    flags: *mut u32,
    desc: *mut u64,
    mask: u32,
    size: u32,
    map: *mut c_void,
    map_len: usize,
}

impl Default for U64Ring {
    fn default() -> Self {
        Self {
            producer: null_mut(),
            consumer: null_mut(),
            flags: null_mut(),
            desc: null_mut(),
            mask: 0,
            size: 0,
            map: null_mut(),
            map_len: 0,
        }
    }
}

struct Umem {
    ptr: *mut u8,
    len: usize,
}

impl Drop for Umem {
    fn drop(&mut self) {
        unsafe {
            libc::munmap(self.ptr as *mut c_void, self.len);
        }
    }
}

struct XskSocket {
    fd: RawFd,
    rx: Ring,
    tx: Ring,
    fill: U64Ring,
    comp: U64Ring,
    umem: Umem,
}

impl Drop for XskSocket {
    fn drop(&mut self) {
        unsafe {
            libc::close(self.fd);
            if !self.rx.map.is_null() {
                libc::munmap(self.rx.map, self.rx.map_len);
            }
            if !self.tx.map.is_null() {
                libc::munmap(self.tx.map, self.tx.map_len);
            }
            if !self.fill.map.is_null() {
                libc::munmap(self.fill.map, self.fill.map_len);
            }
            if !self.comp.map.is_null() {
                libc::munmap(self.comp.map, self.comp.map_len);
            }
        }
    }
}

#[derive(Parser, Debug)]
struct Args {
    #[arg(long)]
    ifindex_in: u32,
    #[arg(long)]
    ifindex_out: u32,
    #[arg(long, default_value_t = 0)]
    queue_in: u32,
    #[arg(long, default_value_t = 0)]
    queue_out: u32,
    #[arg(long, default_value_t = 2048)]
    ring_size: u32,
    #[arg(long)]
    cpu: Option<usize>,
    #[arg(long)]
    allow_udp_dst: Option<u16>,
    #[arg(long)]
    allow_tcp_dst: Option<u16>,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if let Some(cpu) = args.cpu {
        pin_cpu(cpu)?;
    }

    let running = Arc::new(AtomicBool::new(true));
    {
        let r = running.clone();
        ctrlc::set_handler(move || {
            r.store(false, Ordering::Relaxed);
        })?;
    }

    let mut xsk_in = create_xsk(args.ifindex_in, args.queue_in, args.ring_size)
        .context("failed to create input AF_XDP socket")?;
    let mut xsk_out = create_xsk(args.ifindex_out, args.queue_out, args.ring_size)
        .context("failed to create output AF_XDP socket")?;

    prime_fill_ring(&mut xsk_in)?;
    prime_fill_ring(&mut xsk_out)?;

    fast_path_loop(
        &mut xsk_in,
        &mut xsk_out,
        running,
        args.allow_udp_dst,
        args.allow_tcp_dst,
    )
}

fn pin_cpu(cpu: usize) -> Result<()> {
    let cores = core_affinity::get_core_ids().ok_or_else(|| anyhow!("no core ids"))?;
    let core = cores
        .into_iter()
        .find(|c| c.id == cpu)
        .ok_or_else(|| anyhow!("cpu {} not found", cpu))?;
    if !core_affinity::set_for_current(core) {
        return Err(anyhow!("failed to pin to cpu {}", cpu));
    }
    Ok(())
}

fn create_xsk(ifindex: u32, queue_id: u32, ring_size: u32) -> Result<XskSocket> {
    unsafe {
        let fd = libc::socket(libc::AF_XDP, libc::SOCK_RAW, 0);
        if fd < 0 {
            return Err(anyhow!("socket(AF_XDP) failed"));
        }

        let umem_len = FRAME_SIZE * NUM_FRAMES;
        let umem_ptr = libc::mmap(
            null_mut(),
            umem_len,
            libc::PROT_READ | libc::PROT_WRITE,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_POPULATE,
            -1,
            0,
        ) as *mut u8;

        if umem_ptr.is_null() || umem_ptr as isize == -1 {
            libc::close(fd);
            return Err(anyhow!("mmap UMEM failed"));
        }

        let umem = Umem {
            ptr: umem_ptr,
            len: umem_len,
        };

        let reg = XdpUmemReg {
            addr: umem.ptr as u64,
            len: umem.len as u64,
            chunk_size: FRAME_SIZE as u32,
            headroom: 0,
            flags: 0,
            tx_metadata_len: 0,
        };

        setsockopt_struct(fd, SOL_XDP, XDP_UMEM_REG, &reg)?;
        setsockopt_u32(fd, SOL_XDP, XDP_UMEM_FILL_RING, ring_size)?;
        setsockopt_u32(fd, SOL_XDP, XDP_UMEM_COMPLETION_RING, ring_size)?;
        setsockopt_u32(fd, SOL_XDP, XDP_RX_RING, ring_size)?;
        setsockopt_u32(fd, SOL_XDP, XDP_TX_RING, ring_size)?;

        let mut offsets: XdpMmapOffsets = zeroed();
        let mut optlen = size_of::<XdpMmapOffsets>() as libc::socklen_t;
        let rc = libc::getsockopt(
            fd,
            SOL_XDP,
            XDP_MMAP_OFFSETS,
            &mut offsets as *mut _ as *mut c_void,
            &mut optlen,
        );
        if rc != 0 {
            libc::close(fd);
            return Err(anyhow!("getsockopt(XDP_MMAP_OFFSETS) failed"));
        }

        let rx = map_desc_ring(fd, ring_size, &offsets.rx, XDP_PGOFF_RX_RING)?;
        let tx = map_desc_ring(fd, ring_size, &offsets.tx, XDP_PGOFF_TX_RING)?;
        let fill = map_u64_ring(fd, ring_size, &offsets.fr, XDP_UMEM_PGOFF_FILL_RING)?;
        let comp = map_u64_ring(fd, ring_size, &offsets.cr, XDP_UMEM_PGOFF_COMPLETION_RING)?;

        let saddr = SockAddrXdp {
            sxdp_family: libc::AF_XDP as u16,
            sxdp_flags: XDP_ZEROCOPY | XDP_USE_NEED_WAKEUP,
            sxdp_ifindex: ifindex,
            sxdp_queue_id: queue_id,
            sxdp_shared_umem_fd: 0,
        };

        let rc = libc::bind(
            fd,
            &saddr as *const _ as *const libc::sockaddr,
            size_of::<SockAddrXdp>() as u32,
        );
        if rc != 0 {
            libc::close(fd);
            return Err(anyhow!("bind(AF_XDP) failed"));
        }

        Ok(XskSocket {
            fd,
            rx,
            tx,
            fill,
            comp,
            umem,
        })
    }
}

unsafe fn map_desc_ring(fd: RawFd, ring_size: u32, off: &XdpRingOffset, pgoff: i64) -> Result<Ring> {
    let map_len = off.desc as usize + (ring_size as usize) * size_of::<XdpDesc>();
    let map = libc::mmap(
        null_mut(),
        map_len,
        libc::PROT_READ | libc::PROT_WRITE,
        libc::MAP_SHARED | libc::MAP_POPULATE,
        fd,
        pgoff,
    );
    if map.is_null() || map as isize == -1 {
        return Err(anyhow!("mmap desc ring failed"));
    }

    Ok(Ring {
        producer: (map as *mut u8).add(off.producer as usize) as *mut u32,
        consumer: (map as *mut u8).add(off.consumer as usize) as *mut u32,
        flags: (map as *mut u8).add(off.flags as usize) as *mut u32,
        desc: (map as *mut u8).add(off.desc as usize) as *mut XdpDesc,
        mask: ring_size - 1,
        size: ring_size,
        map,
        map_len,
    })
}

unsafe fn map_u64_ring(fd: RawFd, ring_size: u32, off: &XdpRingOffset, pgoff: i64) -> Result<U64Ring> {
    let map_len = off.desc as usize + (ring_size as usize) * size_of::<u64>();
    let map = libc::mmap(
        null_mut(),
        map_len,
        libc::PROT_READ | libc::PROT_WRITE,
        libc::MAP_SHARED | libc::MAP_POPULATE,
        fd,
        pgoff,
    );
    if map.is_null() || map as isize == -1 {
        return Err(anyhow!("mmap u64 ring failed"));
    }

    Ok(U64Ring {
        producer: (map as *mut u8).add(off.producer as usize) as *mut u32,
        consumer: (map as *mut u8).add(off.consumer as usize) as *mut u32,
        flags: (map as *mut u8).add(off.flags as usize) as *mut u32,
        desc: (map as *mut u8).add(off.desc as usize) as *mut u64,
        mask: ring_size - 1,
        size: ring_size,
        map,
        map_len,
    })
}

fn setsockopt_struct<T>(fd: RawFd, level: c_int, opt: c_int, val: &T) -> Result<()> {
    let rc = unsafe {
        libc::setsockopt(
            fd,
            level,
            opt,
            val as *const _ as *const c_void,
            size_of::<T>() as libc::socklen_t,
        )
    };
    if rc != 0 {
        return Err(anyhow!("setsockopt({}, {}) failed", level, opt));
    }
    Ok(())
}

fn setsockopt_u32(fd: RawFd, level: c_int, opt: c_int, val: u32) -> Result<()> {
    let rc = unsafe {
        libc::setsockopt(
            fd,
            level,
            opt,
            &val as *const _ as *const c_void,
            size_of::<u32>() as libc::socklen_t,
        )
    };
    if rc != 0 {
        return Err(anyhow!("setsockopt({}, {}) failed", level, opt));
    }
    Ok(())
}

fn prime_fill_ring(xsk: &mut XskSocket) -> Result<()> {
    unsafe {
        let prod = *xsk.fill.producer;
        let cons = *xsk.fill.consumer;
        let free = xsk.fill.size - (prod - cons);
        let n = free.min(NUM_FRAMES as u32);

        for i in 0..n {
            let idx = (prod + i) & xsk.fill.mask;
            *xsk.fill.desc.add(idx as usize) = (i as usize * FRAME_SIZE) as u64;
        }
        std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
        *xsk.fill.producer = prod + n;
    }
    Ok(())
}

fn fast_path_loop(
    xsk_in: &mut XskSocket,
    xsk_out: &mut XskSocket,
    running: Arc<AtomicBool>,
    allow_udp_dst: Option<u16>,
    allow_tcp_dst: Option<u16>,
) -> Result<()> {
    while running.load(Ordering::Relaxed) {
        unsafe {
            let rx_prod = *xsk_in.rx.producer;
            let rx_cons = *xsk_in.rx.consumer;
            let available = rx_prod.wrapping_sub(rx_cons);
            if available == 0 {
                poll_wakeup(xsk_in.fd)?;
                continue;
            }

            let burst = available.min(BATCH_SIZE as u32);
            let tx_prod = *xsk_out.tx.producer;
            let tx_cons = *xsk_out.tx.consumer;
            let tx_free = xsk_out.tx.size - tx_prod.wrapping_sub(tx_cons);
            let n = burst.min(tx_free);

            if n == 0 {
                complete_tx(xsk_out)?;
                continue;
            }

            let mut forwarded = 0u32;

            for i in 0..n {
                let rx_idx = (rx_cons + i) & xsk_in.rx.mask;
                let rxd = *xsk_in.rx.desc.add(rx_idx as usize);

                let pkt = xsk_in.umem.ptr.add(rxd.addr as usize);
                let len = rxd.len as usize;

                if packet_allowed(pkt, len, allow_udp_dst, allow_tcp_dst) {
                    let tx_idx = (tx_prod + forwarded) & xsk_out.tx.mask;
                    *xsk_out.tx.desc.add(tx_idx as usize) = XdpDesc {
                        addr: rxd.addr,
                        len: rxd.len,
                        options: 0,
                    };
                    forwarded += 1;
                } else {
                    recycle_frame(&mut xsk_in.fill, rxd.addr)?;
                }
            }

            std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
            *xsk_in.rx.consumer = rx_cons + n;

            if forwarded > 0 {
                std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
                *xsk_out.tx.producer = tx_prod + forwarded;
                kick_tx(xsk_out.fd)?;
            }

            replenish_fill_from_completion(xsk_out)?;
            replenish_fill_from_completion(xsk_in)?;
        }
    }
    Ok(())
}

unsafe fn recycle_frame(fill: &mut U64Ring, addr: u64) -> Result<()> {
    let prod = *fill.producer;
    let cons = *fill.consumer;
    let free = fill.size - prod.wrapping_sub(cons);
    if free == 0 {
        return Ok(());
    }
    let idx = prod & fill.mask;
    *fill.desc.add(idx as usize) = addr;
    std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
    *fill.producer = prod + 1;
    Ok(())
}

unsafe fn replenish_fill_from_completion(xsk: &mut XskSocket) -> Result<()> {
    let comp_prod = *xsk.comp.producer;
    let comp_cons = *xsk.comp.consumer;
    let avail = comp_prod.wrapping_sub(comp_cons);
    if avail == 0 {
        return Ok(());
    }

    let fill_prod = *xsk.fill.producer;
    let fill_cons = *xsk.fill.consumer;
    let fill_free = xsk.fill.size - fill_prod.wrapping_sub(fill_cons);
    let n = avail.min(fill_free);

    for i in 0..n {
        let cidx = (comp_cons + i) & xsk.comp.mask;
        let fidx = (fill_prod + i) & xsk.fill.mask;
        let addr = *xsk.comp.desc.add(cidx as usize);
        *xsk.fill.desc.add(fidx as usize) = addr;
    }

    std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
    *xsk.comp.consumer = comp_cons + n;
    *xsk.fill.producer = fill_prod + n;
    Ok(())
}

fn poll_wakeup(fd: RawFd) -> Result<()> {
    let mut pfd = libc::pollfd {
        fd,
        events: libc::POLLIN,
        revents: 0,
    };
    let rc = unsafe { libc::poll(&mut pfd, 1, 1) };
    if rc < 0 {
        return Err(anyhow!("poll failed"));
    }
    Ok(())
}

fn kick_tx(fd: RawFd) -> Result<()> {
    let rc = unsafe { libc::sendto(fd, null(), 0, libc::MSG_DONTWAIT, null(), 0) };
    if rc < 0 {
        let err = std::io::Error::last_os_error();
        let raw = err.raw_os_error().unwrap_or(0);
        if raw != libc::EAGAIN && raw != libc::EBUSY {
            return Err(anyhow!("sendto kick failed: {}", err));
        }
    }
    Ok(())
}

fn complete_tx(xsk: &mut XskSocket) -> Result<()> {
    replenish_fill_from_completion(xsk)
}

fn packet_allowed(
    pkt: *const u8,
    len: usize,
    allow_udp_dst: Option<u16>,
    allow_tcp_dst: Option<u16>,
) -> bool {
    if len < ETH_HDR_LEN {
        return false;
    }

    unsafe {
        let ethertype = u16::from_be_bytes([*pkt.add(12), *pkt.add(13)]);
        if ethertype != ETH_P_IP {
            return false;
        }

        if len < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
            return false;
        }

        let ip = pkt.add(ETH_HDR_LEN);
        let version_ihl = *ip;
        let version = version_ihl >> 4;
        let ihl = (version_ihl & 0x0f) as usize * 4;

        if version != 4 || ihl < IPV4_MIN_HDR_LEN || len < ETH_HDR_LEN + ihl {
            return false;
        }

        let proto = *ip.add(9);
        let l4 = ip.add(ihl);
        let l4_len = len - ETH_HDR_LEN - ihl;

        match proto {
            UDP_PROTO => {
                if l4_len < 8 {
                    return false;
                }
                let dst = u16::from_be_bytes([*l4.add(2), *l4.add(3)]);
                match allow_udp_dst {
                    Some(port) => dst == port,
                    None => true,
                }
            }
            TCP_PROTO => {
                if l4_len < 20 {
                    return false;
                }
                let dst = u16::from_be_bytes([*l4.add(2), *l4.add(3)]);
                match allow_tcp_dst {
                    Some(port) => dst == port,
                    None => true,
                }
            }
            _ => false,
        }
    }
}
