## src/main.rs

```rust
use anyhow::{bail, Context, Result};
use clap::Parser;
use core_affinity;
use etherparse::{Ethernet2HeaderSlice, Ipv4HeaderSlice};
use log::{error, info, warn};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::Duration;
use xsk_rs::{
    config::{BindFlags, LibbpfFlags, SocketConfig, UmemConfig, XdpFlags},
    socket::{CompQueue, FillQueue, RxQueue, Socket, TxQueue, Umem},
    umem::frame::FrameDesc,
};

const FRAME_SIZE: usize = 2048;
const NUM_FRAMES: usize = 8192;
const RX_BATCH: usize = 64;
const FQ_SIZE: usize = 4096;
const CQ_SIZE: usize = 4096;
const RXQ_SIZE: usize = 2048;
const TXQ_SIZE: usize = 2048;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Input interface
    #[arg(long)]
    in_if: String,

    /// Output interface
    #[arg(long)]
    out_if: String,

    /// Queue id on input interface
    #[arg(long, default_value_t = 0)]
    in_queue: u32,

    /// Queue id on output interface
    #[arg(long, default_value_t = 0)]
    out_queue: u32,

    /// Optional CPU core to pin the worker to
    #[arg(long)]
    cpu: Option<usize>,

    /// Drop packets not matching dst IPv4
    #[arg(long)]
    allow_dst_ip: Option<Ipv4Addr>,

    /// Drop packets not matching dst UDP port
    #[arg(long)]
    allow_dst_port: Option<u16>,
}

struct XskPort {
    umem: Umem,
    fq: FillQueue,
    cq: CompQueue,
    rx: RxQueue,
    tx: TxQueue,
    socket: Socket,
    free_frames: Vec<u64>,
}

fn build_port(ifname: &str, queue_id: u32) -> Result<XskPort> {
    let umem_cfg = UmemConfig::builder()
        .frame_count(NUM_FRAMES as u32)
        .frame_size(FRAME_SIZE as u32)
        .fill_queue_size(FQ_SIZE as u32)
        .comp_queue_size(CQ_SIZE as u32)
        .build();

    let (umem, mut fq, cq) = Umem::new(umem_cfg).context("creating UMEM")?;

    let sock_cfg = SocketConfig::builder()
        .rx_queue_size(RXQ_SIZE as u32)
        .tx_queue_size(TXQ_SIZE as u32)
        .libbpf_flags(LibbpfFlags::XSK_LIBBPF_FLAGS__INHIBIT_PROG_LOAD)
        .xdp_flags(XdpFlags::default())
        .bind_flags(BindFlags::XDP_USE_NEED_WAKEUP)
        .build();

    let (socket, rx, tx) = Socket::new(&umem, ifname, queue_id, sock_cfg)
        .with_context(|| format!("binding AF_XDP socket to {} queue {}", ifname, queue_id))?;

    let mut free_frames = Vec::with_capacity(NUM_FRAMES);
    for i in 0..NUM_FRAMES {
        free_frames.push((i * FRAME_SIZE) as u64);
    }

    // Prime fill queue with as many frames as possible.
    let initial = FQ_SIZE.min(free_frames.len());
    let mut descs = Vec::with_capacity(initial);
    for _ in 0..initial {
        descs.push(FrameDesc::new(free_frames.pop().unwrap(), FRAME_SIZE as u32));
    }

    let n = fq.produce(&descs).context("priming fill queue")?;
    if n != descs.len() {
        bail!("short produce to fill queue: {} != {}", n, descs.len());
    }

    Ok(XskPort {
        umem,
        fq,
        cq,
        rx,
        tx,
        socket,
        free_frames,
    })
}

fn recycle_completions(port: &mut XskPort) -> Result<()> {
    let completed = port.cq.consume(RX_BATCH as u32).context("cq consume")?;
    for d in completed {
        port.free_frames.push(d.addr());
    }
    Ok(())
}

fn refill_fillq(port: &mut XskPort) -> Result<()> {
    if port.free_frames.is_empty() {
        return Ok(());
    }

    let budget = FQ_SIZE.min(port.free_frames.len()).min(RX_BATCH);
    let mut descs = Vec::with_capacity(budget);
    for _ in 0..budget {
        let addr = port.free_frames.pop().unwrap();
        descs.push(FrameDesc::new(addr, FRAME_SIZE as u32));
    }

    let produced = port.fq.produce(&descs).context("fq produce")?;
    if produced < descs.len() {
        for d in descs.into_iter().skip(produced) {
            port.free_frames.push(d.addr());
        }
    }
    Ok(())
}

fn packet_allowed(buf: &[u8], allow_ip: Option<Ipv4Addr>, allow_port: Option<u16>) -> bool {
    let eth = match Ethernet2HeaderSlice::from_slice(buf) {
        Ok(v) => v,
        Err(_) => return false,
    };

    // IPv4 only in this example
    if eth.ether_type() != 0x0800 {
        return false;
    }

    let ip_start = Ethernet2HeaderSlice::LEN;
    let ipv4 = match Ipv4HeaderSlice::from_slice(&buf[ip_start..]) {
        Ok(v) => v,
        Err(_) => return false,
    };

    if let Some(ip) = allow_ip {
        let dst = Ipv4Addr::from(ipv4.destination());
        if dst != ip {
            return false;
        }
    }

    // UDP only if port filter requested
    if let Some(port) = allow_port {
        if ipv4.protocol() != 17 {
            return false;
        }
        let ip_hlen = ipv4.slice().len();
        let udp_start = ip_start + ip_hlen;
        if buf.len() < udp_start + 4 {
            return false;
        }
        let dst_port = u16::from_be_bytes([buf[udp_start + 2], buf[udp_start + 3]]);
        if dst_port != port {
            return false;
        }
    }

    true
}

fn forward_loop(
    mut in_port: XskPort,
    mut out_port: XskPort,
    allow_ip: Option<Ipv4Addr>,
    allow_port: Option<u16>,
    running: Arc<AtomicBool>,
) -> Result<()> {
    let mut rx_buf = Vec::with_capacity(RX_BATCH);

    while running.load(Ordering::Relaxed) {
        recycle_completions(&mut out_port)?;
        refill_fillq(&mut in_port)?;

        rx_buf.clear();
        let received = in_port.rx.consume(RX_BATCH as u32, &mut rx_buf).context("rx consume")?;
        if received == 0 {
            if in_port.socket.needs_wakeup() {
                let _ = in_port.socket.poll(Duration::from_millis(0));
            }
            if out_port.socket.needs_wakeup() {
                let _ = out_port.socket.poll(Duration::from_millis(0));
            }
            std::hint::spin_loop();
            continue;
        }

        let mut tx_descs = Vec::with_capacity(received as usize);

        for desc in &rx_buf {
            let addr = desc.addr();
            let len = desc.len() as usize;

            let pkt = unsafe {
                // SAFETY:
                // AF_XDP UMEM frame address/length comes from kernel RX ring.
                // We only create a temporary shared slice for parsing.
                std::slice::from_raw_parts(in_port.umem.data().add(addr as usize), len)
            };

            if packet_allowed(pkt, allow_ip, allow_port) {
                // Copy into an output frame.
                // For same-UMEM / advanced setups you can do true zero-copy ownership transfer patterns,
                // but this simple version uses separate UMEMs for clarity.
                let out_addr = match out_port.free_frames.pop() {
                    Some(a) => a,
                    None => {
                        // No TX buffers available; drop.
                        in_port.free_frames.push(addr);
                        continue;
                    }
                };

                let out_pkt = unsafe {
                    std::slice::from_raw_parts_mut(
                        out_port.umem.data().add(out_addr as usize),
                        FRAME_SIZE,
                    )
                };

                if len > FRAME_SIZE {
                    in_port.free_frames.push(addr);
                    out_port.free_frames.push(out_addr);
                    continue;
                }

                out_pkt[..len].copy_from_slice(pkt);
                tx_descs.push(FrameDesc::new(out_addr, len as u32));
            }

            // Return input frame to free list; later re-added to fill queue.
            in_port.free_frames.push(addr);
        }

        if !tx_descs.is_empty() {
            let sent = out_port.tx.produce(&tx_descs).context("tx produce")?;
            if sent < tx_descs.len() {
                for d in tx_descs.into_iter().skip(sent) {
                    out_port.free_frames.push(d.addr());
                }
            }

            if out_port.socket.needs_wakeup() {
                let _ = out_port.socket.poll(Duration::from_millis(0));
            }
        }
    }

    Ok(())
}

fn pin_cpu(cpu: usize) {
    if let Some(cores) = core_affinity::get_core_ids() {
        if let Some(core) = cores.into_iter().find(|c| c.id == cpu) {
            if core_affinity::set_for_current(core) {
                info!("Pinned worker to CPU {}", cpu);
            } else {
                warn!("Failed to pin worker to CPU {}", cpu);
            }
        } else {
            warn!("CPU {} not found", cpu);
        }
    } else {
        warn!("Could not query CPU core ids");
    }
}

fn main() -> Result<()> {
    env_logger::init();
    let args = Args::parse();

    if let Some(cpu) = args.cpu {
        pin_cpu(cpu);
    }

    let running = Arc::new(AtomicBool::new(true));
    {
        let r = running.clone();
        ctrlc::set_handler(move || {
            r.store(false, Ordering::Relaxed);
        })
        .context("installing Ctrl-C handler")?;
    }

    info!(
        "starting forwarder in_if={} out_if={} in_q={} out_q={}",
        args.in_if, args.out_if, args.in_queue, args.out_queue
    );

    let in_port = build_port(&args.in_if, args.in_queue)
        .with_context(|| format!("building input port {}", args.in_if))?;
    let out_port = build_port(&args.out_if, args.out_queue)
        .with_context(|| format!("building output port {}", args.out_if))?;

    if let Err(e) = forward_loop(
        in_port,
        out_port,
        args.allow_dst_ip,
        args.allow_dst_port,
        running,
    ) {
        error!("forward loop failed: {e:#}");
        return Err(e);
    }

    Ok(())
}
