```rust
use anyhow::{anyhow, Result};
use clap::Parser;
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::time::Duration;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Interface to receive packets on
    #[arg(long)]
    ingress: String,

    /// Interface to forward packets out
    #[arg(long)]
    egress: String,

    /// Optional allowed destination TCP/UDP port
    #[arg(long)]
    allow_port: Option<u16>,
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .ok_or_else(|| anyhow!("interface not found: {}", name))
}

fn make_channel(
    iface: &NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;
    config.promiscuous = true;

    match datalink::channel(iface, config)? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => Err(anyhow!("unsupported channel type")),
    }
}

fn allowed_frame(frame: &[u8], allow_port: Option<u16>) -> bool {
    let eth = match EthernetPacket::new(frame) {
        Some(p) => p,
        None => return false,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = match Ipv4Packet::new(eth.payload()) {
                Some(p) => p,
                None => return false,
            };

            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = match TcpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    match allow_port {
                        Some(port) => tcp.get_destination() == port,
                        None => true,
                    }
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = match UdpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    match allow_port {
                        Some(port) => udp.get_destination() == port,
                        None => true,
                    }
                }
                _ => false,
            }
        }
        _ => false,
    }
}

fn forward_frame(tx: &mut Box<dyn DataLinkSender>, frame: &[u8]) -> Result<()> {
    match tx.send_to(frame, None) {
        Some(Ok(())) => Ok(()),
        Some(Err(e)) => Err(anyhow!("send error: {}", e)),
        None => Err(anyhow!("send failed: no tx buffer available")),
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    let ingress = find_interface(&args.ingress)?;
    let egress = find_interface(&args.egress)?;

    let (_ingress_tx, mut ingress_rx) = make_channel(&ingress)?;
    let (mut egress_tx, _egress_rx) = make_channel(&egress)?;

    loop {
        match ingress_rx.next() {
            Ok(frame) => {
                if allowed_frame(frame, args.allow_port) {
                    if let Err(e) = forward_frame(&mut egress_tx, frame) {
                        eprintln!("forward error: {e}");
                    }
                }
            }
            Err(_) => {
                // timeout or transient read error; continue tight loop
            }
        }
    }
}
```

