```rust
use anyhow::{Context, Result};
use clap::Parser;
use serde::Deserialize;
use std::{
    collections::HashSet,
    net::{IpAddr, SocketAddr},
    path::PathBuf,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Duration,
};
use tokio::{
    net::UdpSocket,
    sync::mpsc,
    time::interval,
};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Path to TOML config
    #[arg(short, long)]
    config: PathBuf,
}

#[derive(Debug, Deserialize, Clone)]
struct Config {
    listen_addr: SocketAddr,
    forward_addr: SocketAddr,
    workers: usize,
    max_packet_size: usize,
    allowed_sources: Option<Vec<IpAddr>>,
    denied_sources: Option<Vec<IpAddr>>,
    required_prefix_hex: Option<String>,
    channel_capacity: usize,
}

#[derive(Clone)]
struct Filter {
    allowed_sources: Option<HashSet<IpAddr>>,
    denied_sources: HashSet<IpAddr>,
    required_prefix: Option<Vec<u8>>,
    max_packet_size: usize,
}

impl Filter {
    fn from_config(cfg: &Config) -> Result<Self> {
        let required_prefix = match &cfg.required_prefix_hex {
            Some(s) => Some(hex_to_bytes(s)?),
            None => None,
        };

        Ok(Self {
            allowed_sources: cfg
                .allowed_sources
                .as_ref()
                .map(|v| v.iter().copied().collect()),
            denied_sources: cfg
                .denied_sources
                .clone()
                .unwrap_or_default()
                .into_iter()
                .collect(),
            required_prefix,
            max_packet_size: cfg.max_packet_size,
        })
    }

    #[inline]
    fn accept(&self, src: SocketAddr, payload: &[u8]) -> bool {
        if payload.len() > self.max_packet_size {
            return false;
        }

        let ip = src.ip();

        if self.denied_sources.contains(&ip) {
            return false;
        }

        if let Some(allowed) = &self.allowed_sources {
            if !allowed.contains(&ip) {
                return false;
            }
        }

        if let Some(prefix) = &self.required_prefix {
            if payload.len() < prefix.len() || &payload[..prefix.len()] != prefix.as_slice() {
                return false;
            }
        }

        true
    }
}

fn hex_to_bytes(s: &str) -> Result<Vec<u8>> {
    let s = s.trim();
    if s.len() % 2 != 0 {
        anyhow::bail!("required_prefix_hex must have even length");
    }

    let mut out = Vec::with_capacity(s.len() / 2);
    let bytes = s.as_bytes();

    for i in (0..bytes.len()).step_by(2) {
        let hi = from_hex(bytes[i])?;
        let lo = from_hex(bytes[i + 1])?;
        out.push((hi << 4) | lo);
    }

    Ok(out)
}

fn from_hex(b: u8) -> Result<u8> {
    match b {
        b'0'..=b'9' => Ok(b - b'0'),
        b'a'..=b'f' => Ok(10 + b - b'a'),
        b'A'..=b'F' => Ok(10 + b - b'A'),
        _ => anyhow::bail!("invalid hex character"),
    }
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    accepted: AtomicU64,
    forwarded: AtomicU64,
    dropped: AtomicU64,
    forward_errors: AtomicU64,
}

#[derive(Debug)]
struct Packet {
    src: SocketAddr,
    len: usize,
    buf: Vec<u8>,
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    let args = Args::parse();
    let config_text = std::fs::read_to_string(&args.config)
        .with_context(|| format!("failed to read config {:?}", args.config))?;
    let cfg: Config = toml::from_str(&config_text).context("failed to parse TOML config")?;

    let workers = cfg.workers.max(1);
    let filter = Arc::new(Filter::from_config(&cfg)?);
    let metrics = Arc::new(Metrics::default());

    let socket = Arc::new(
        UdpSocket::bind(cfg.listen_addr)
            .await
            .with_context(|| format!("failed to bind {}", cfg.listen_addr))?,
    );

    let mut txs = Vec::with_capacity(workers);

    for _ in 0..workers {
        let (tx, mut rx) = mpsc::channel::<Packet>(cfg.channel_capacity);
        txs.push(tx);

        let forward_addr = cfg.forward_addr;
        let metrics = Arc::clone(&metrics);

        tokio::spawn(async move {
            let out = match UdpSocket::bind("0.0.0.0:0").await {
                Ok(s) => s,
                Err(e) => {
                    eprintln!("worker failed to bind outbound socket: {e}");
                    return;
                }
            };

            while let Some(pkt) = rx.recv().await {
                match out.send_to(&pkt.buf[..pkt.len], forward_addr).await {
                    Ok(_) => {
                        metrics.forwarded.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(e) => {
                        metrics.forward_errors.fetch_add(1, Ordering::Relaxed);
                        eprintln!("forward error from {}: {}", pkt.src, e);
                    }
                }
            }
        });
    }

    {
        let metrics = Arc::clone(&metrics);
        tokio::spawn(async move {
            let mut tick = interval(Duration::from_secs(1));
            loop {
                tick.tick().await;
                let received = metrics.received.load(Ordering::Relaxed);
                let accepted = metrics.accepted.load(Ordering::Relaxed);
                let forwarded = metrics.forwarded.load(Ordering::Relaxed);
                let dropped = metrics.dropped.load(Ordering::Relaxed);
                let forward_errors = metrics.forward_errors.load(Ordering::Relaxed);

                eprintln!(
                    "metrics received={} accepted={} forwarded={} dropped={} forward_errors={}",
                    received, accepted, forwarded, dropped, forward_errors
                );
            }
        });
    }

    let mut rr = 0usize;
    let mut buf = vec![0u8; cfg.max_packet_size];

    loop {
        let (len, src) = socket.recv_from(&mut buf).await?;
        metrics.received.fetch_add(1, Ordering::Relaxed);

        let payload = &buf[..len];
        if !filter.accept(src, payload) {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
            continue;
        }

        metrics.accepted.fetch_add(1, Ordering::Relaxed);

        let mut pkt_buf = Vec::with_capacity(len);
        pkt_buf.extend_from_slice(payload);

        let pkt = Packet {
            src,
            len,
            buf: pkt_buf,
        };

        let tx = &txs[rr % txs.len()];
        rr = rr.wrapping_add(1);

        if tx.send(pkt).await.is_err() {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}
