## Rust example: low-latency UDP filter/forwarder

```rust
use std::io;
use std::net::{SocketAddr, UdpSocket};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

const MAX_PACKET_SIZE: usize = 2048;
const BATCH_SIZE: usize = 64;

#[derive(Clone)]
struct Config {
    listen_addr: SocketAddr,
    forward_addr: SocketAddr,
    allowed_source_port: Option<u16>,
    drop_if_payload_starts_with: Option<Vec<u8>>,
}

#[derive(Default, Debug)]
struct Stats {
    received: u64,
    forwarded: u64,
    dropped: u64,
}

fn packet_allowed(cfg: &Config, src: SocketAddr, payload: &[u8]) -> bool {
    if let Some(port) = cfg.allowed_source_port {
        if src.port() != port {
            return false;
        }
    }

    if let Some(prefix) = &cfg.drop_if_payload_starts_with {
        if payload.starts_with(prefix) {
            return false;
        }
    }

    true
}

fn worker(cfg: Arc<Config>) -> io::Result<()> {
    let rx = UdpSocket::bind(cfg.listen_addr)?;
    rx.set_nonblocking(false)?;
    rx.set_read_timeout(Some(Duration::from_millis(100)))?;

    let tx = UdpSocket::bind("0.0.0.0:0")?;
    tx.connect(cfg.forward_addr)?;

    let mut stats = Stats::default();

    let mut buffers: Vec<[u8; MAX_PACKET_SIZE]> = vec![[0u8; MAX_PACKET_SIZE]; BATCH_SIZE];

    loop {
        for buf in &mut buffers {
            match rx.recv_from(buf) {
                Ok((len, src)) => {
                    stats.received += 1;
                    let payload = &buf[..len];

                    if packet_allowed(&cfg, src, payload) {
                        match tx.send(payload) {
                            Ok(_) => {
                                stats.forwarded += 1;
                            }
                            Err(e) => {
                                eprintln!("forward error: {e}");
                            }
                        }
                    } else {
                        stats.dropped += 1;
                    }
                }
                Err(ref e)
                    if e.kind() == io::ErrorKind::WouldBlock
                        || e.kind() == io::ErrorKind::TimedOut =>
                {
                    break;
                }
                Err(e) => {
                    eprintln!("recv error: {e}");
                    break;
                }
            }
        }

        if (stats.received % 10_000) == 0 && stats.received != 0 {
            println!(
                "stats: received={} forwarded={} dropped={}",
                stats.received, stats.forwarded, stats.dropped
            );
        }
    }
}

fn main() -> io::Result<()> {
    let cfg = Arc::new(Config {
        listen_addr: "0.0.0.0:9000".parse().unwrap(),
        forward_addr: "127.0.0.1:9001".parse().unwrap(),
        allowed_source_port: None,
        drop_if_payload_starts_with: Some(b"DROP".to_vec()),
    });

    let worker_cfg = cfg.clone();
    let handle = thread::spawn(move || worker(worker_cfg));

    match handle.join() {
        Ok(res) => res,
        Err(_) => Err(io::Error::new(
            io::ErrorKind::Other,
            "worker thread panicked",
        )),
    }
}
