## Example: higher-performance direction in C with recvmmsg/sendmmsg

Here is a **minimal safe skeleton** showing the syscall pattern often used for lower latency on Linux:

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define BATCH 32
#define BUF_SZ 2048

static int allowed(const unsigned char *buf, size_t len) {
    if (len >= 4 && memcmp(buf, "DROP", 4) == 0) return 0;
    return 1;
}

int main() {
    int rx = socket(AF_INET, SOCK_DGRAM, 0);
    int tx = socket(AF_INET, SOCK_DGRAM, 0);
    if (rx < 0 || tx < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in bind_addr = {0};
    bind_addr.sin_family = AF_INET;
    bind_addr.sin_port = htons(9000);
    bind_addr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(rx, (struct sockaddr *)&bind_addr, sizeof(bind_addr)) < 0) {
        perror("bind");
        return 1;
    }

    struct sockaddr_in dst = {0};
    dst.sin_family = AF_INET;
    dst.sin_port = htons(9001);
    inet_pton(AF_INET, "127.0.0.1", &dst.sin_addr);

    unsigned char bufs[BATCH][BUF_SZ];
    struct mmsghdr msgs[BATCH];
    struct iovec iovecs[BATCH];
    struct sockaddr_in src_addrs[BATCH];

    memset(msgs, 0, sizeof(msgs));
    memset(iovecs, 0, sizeof(iovecs));
    memset(src_addrs, 0, sizeof(src_addrs));

    for (int i = 0; i < BATCH; i++) {
        iovecs[i].iov_base = bufs[i];
        iovecs[i].iov_len = BUF_SZ;
        msgs[i].msg_hdr.msg_iov = &iovecs[i];
        msgs[i].msg_hdr.msg_iovlen = 1;
        msgs[i].msg_hdr.msg_name = &src_addrs[i];
        msgs[i].msg_hdr.msg_namelen = sizeof(src_addrs[i]);
    }

    for (;;) {
        int n = recvmmsg(rx, msgs, BATCH, 0, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvmmsg");
            break;
        }

        for (int i = 0; i < n; i++) {
            size_t len = msgs[i].msg_len;
            if (!allowed(bufs[i], len)) continue;

            ssize_t sent = sendto(tx, bufs[i], len, 0,
                                  (struct sockaddr *)&dst, sizeof(dst));
            if (sent < 0) perror("sendto");
        }
    }

    close(rx);
    close(tx);
    return 0;
}
