use anyhow::{anyhow, Context, Result};
use clap::Parser;
use core_affinity;
use etherparse::{Ipv4HeaderSlice, SlicedPacket, TransportSlice};
use std::net::Ipv4Addr;
use std::sync::Arc;
use xsk_rs::{
    config::{SocketConfig, UmemConfig, XdpFlags},
    socket::Socket,
    umem::Umem,
};

const FRAME_SIZE: usize = 2048;
const NUM_FRAMES: usize = 4096;
const BATCH_SIZE: usize = 64;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// RX interface name, e.g. eth0
    #[arg(long)]
    rx_if: String,

    /// RX queue id
    #[arg(long, default_value_t = 0)]
    rx_queue: u32,

    /// TX interface name, e.g. eth1
    #[arg(long)]
    tx_if: String,

    /// TX queue id
    #[arg(long, default_value_t = 0)]
    tx_queue: u32,

    /// Optional destination UDP port to allow; others dropped
    #[arg(long)]
    allow_udp_dst: Option<u16>,

    /// Optional destination IPv4 to allow; others dropped
    #[arg(long)]
    allow_dst_ip: Option<Ipv4Addr>,

    /// Optional CPU core pinning
    #[arg(long)]
    cpu: Option<usize>,
}

#[derive(Clone, Debug)]
struct Filter {
    allow_udp_dst: Option<u16>,
    allow_dst_ip: Option<Ipv4Addr>,
}

impl Filter {
    #[inline(always)]
    fn allow(&self, pkt: &[u8]) -> bool {
        let sliced = match SlicedPacket::from_ethernet(pkt) {
            Ok(s) => s,
            Err(_) => return false,
        };

        let ip_ok = match (&self.allow_dst_ip, &sliced.ip) {
            (None, _) => true,
            (Some(allowed), Some(etherparse::InternetSlice::Ipv4(h, _))) => {
                let dst = Ipv4Addr::from(h.destination());
                &dst == allowed
            }
            _ => false,
        };

        if !ip_ok {
            return false;
        }

        match self.allow_udp_dst {
            None => true,
            Some(port) => match sliced.transport {
                Some(TransportSlice::Udp(udp)) => udp.destination_port() == port,
                _ => false,
            },
        }
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    if let Some(cpu_id) = args.cpu {
        let cores = core_affinity::get_core_ids().ok_or_else(|| anyhow!("failed to get core ids"))?;
        let core = cores
            .into_iter()
            .find(|c| c.id == cpu_id)
            .ok_or_else(|| anyhow!("cpu core {} not found", cpu_id))?;
        core_affinity::set_for_current(core);
    }

    let filter = Filter {
        allow_udp_dst: args.allow_udp_dst,
        allow_dst_ip: args.allow_dst_ip,
    };

    let umem_cfg = UmemConfig {
        frame_count: NUM_FRAMES as u32,
        frame_size: FRAME_SIZE as u32,
        fill_queue_size: NUM_FRAMES as u32 / 2,
        comp_queue_size: NUM_FRAMES as u32 / 2,
        ..Default::default()
    };

    let umem = Arc::new(Umem::new(umem_cfg).context("create UMEM")?);

    let sock_cfg = SocketConfig {
        rx_queue_size: 2048,
        tx_queue_size: 2048,
        libbpf_flags: 0,
        xdp_flags: XdpFlags::default(),
        bind_flags: Default::default(),
    };

    let mut rx_sock = Socket::new(
        umem.clone(),
        &args.rx_if,
        args.rx_queue,
        sock_cfg.clone(),
    )
    .with_context(|| format!("create RX socket on {}:{}", args.rx_if, args.rx_queue))?;

    let mut tx_sock = Socket::new(
        umem.clone(),
        &args.tx_if,
        args.tx_queue,
        sock_cfg,
    )
    .with_context(|| format!("create TX socket on {}:{}", args.tx_if, args.tx_queue))?;

    // Pre-fill RX fill ring with UMEM frames
    {
        let mut fq = rx_sock.fill_queue();
        for frame_idx in 0..(NUM_FRAMES / 2) {
            let addr = (frame_idx * FRAME_SIZE) as u64;
            fq.produce(&[addr]).context("fill queue produce")?;
        }
    }

    let mut rx_batch = Vec::with_capacity(BATCH_SIZE);
    let mut tx_addrs = Vec::with_capacity(BATCH_SIZE);
    let mut refill_addrs = Vec::with_capacity(BATCH_SIZE);

    loop {
        rx_batch.clear();
        tx_addrs.clear();
        refill_addrs.clear();

        {
            let mut rxq = rx_sock.rx_queue();
            let received = rxq.consume(BATCH_SIZE, &mut rx_batch).context("rx consume")?;
            if received == 0 {
                std::hint::spin_loop();
                continue;
            }
        }

        for desc in &rx_batch {
            let addr = desc.addr;
            let len = desc.len as usize;

            let data = unsafe {
                umem.frame(addr)
                    .ok_or_else(|| anyhow!("invalid frame addr {}", addr))?
            };

            let pkt = &data[..len.min(FRAME_SIZE)];

            if filter.allow(pkt) {
                tx_addrs.push((addr, len));
            } else {
                refill_addrs.push(addr);
            }
        }

        if !tx_addrs.is_empty() {
            let mut txq = tx_sock.tx_queue();
            let mut produced = 0usize;

            while produced < tx_addrs.len() {
                let chunk: Vec<_> = tx_addrs[produced..]
                    .iter()
                    .map(|(addr, len)| xsk_rs::desc::Desc {
                        addr: *addr,
                        len: *len as u32,
                        options: 0,
                    })
                    .collect();

                let n = txq.produce(&chunk).context("tx produce")?;
                if n == 0 {
                    std::hint::spin_loop();
                    continue;
                }
                produced += n;
            }

            tx_sock.wakeup().ok();

            let mut cq = tx_sock.comp_queue();
            let mut completed = Vec::with_capacity(BATCH_SIZE);
            let _ = cq.consume(BATCH_SIZE, &mut completed);

            for addr in completed {
                refill_addrs.push(addr);
            }
        }

        if !refill_addrs.is_empty() {
            let mut fq = rx_sock.fill_queue();
            let mut offset = 0usize;
            while offset < refill_addrs.len() {
                let n = fq.produce(&refill_addrs[offset..]).context("refill produce")?;
                if n == 0 {
                    std::hint::spin_loop();
                    continue;
                }
                offset += n;
            }
        }
    }
}
