# `udp_filter_forwarder.cpp`

```cpp
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>

#include <atomic>
#include <cstring>
#include <functional>
#include <iostream>
#include <string>
#include <thread>
#include <unordered_set>
#include <vector>

namespace cfg {
constexpr int kListenPort = 9000;
constexpr int kMaxEvents = 256;
constexpr int kBufferSize = 2048;
constexpr int kWorkerThreads = 4;

// Forward destination
constexpr const char* kForwardIp = "127.0.0.1";
constexpr int kForwardPort = 10000;
}

// Simple packet filter policy
class PacketFilter {
public:
    PacketFilter() {
        blocked_ips_.insert(ipToInt("10.0.0.13"));
    }

    bool allow(const sockaddr_in& src, const char* data, ssize_t len) const {
        uint32_t ip = src.sin_addr.s_addr;
        if (blocked_ips_.find(ip) != blocked_ips_.end()) {
            return false;
        }

        // Example payload filter:
        // Drop packets beginning with "DROP"
        if (len >= 4 && std::memcmp(data, "DROP", 4) == 0) {
            return false;
        }

        return true;
    }

private:
    std::unordered_set<uint32_t> blocked_ips_;

    static uint32_t ipToInt(const std::string& ip) {
        in_addr addr{};
        inet_pton(AF_INET, ip.c_str(), &addr);
        return addr.s_addr;
    }
};

static int setNonBlocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static int createUdpSocket(int port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int reuse = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt SO_REUSEADDR");
        close(fd);
        return -1;
    }

#ifdef SO_REUSEPORT
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt SO_REUSEPORT");
        close(fd);
        return -1;
    }
#endif

    int rcvbuf = 4 * 1024 * 1024;
    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) {
        perror("setsockopt SO_RCVBUF");
    }

    if (setNonBlocking(fd) < 0) {
        perror("fcntl O_NONBLOCK");
        close(fd);
        return -1;
    }

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(port);

    if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    return fd;
}

class Worker {
public:
    Worker(int listen_port, const std::string& forward_ip, int forward_port)
        : listen_port_(listen_port), forward_ip_(forward_ip), forward_port_(forward_port) {}

    bool init() {
        sockfd_ = createUdpSocket(listen_port_);
        if (sockfd_ < 0) return false;

        epfd_ = epoll_create1(0);
        if (epfd_ < 0) {
            perror("epoll_create1");
            return false;
        }

        epoll_event ev{};
        ev.events = EPOLLIN | EPOLLET;
        ev.data.fd = sockfd_;
        if (epoll_ctl(epfd_, EPOLL_CTL_ADD, sockfd_, &ev) < 0) {
            perror("epoll_ctl");
            return false;
        }

        std::memset(&forward_addr_, 0, sizeof(forward_addr_));
        forward_addr_.sin_family = AF_INET;
        forward_addr_.sin_port = htons(forward_port_);
        if (inet_pton(AF_INET, forward_ip_.c_str(), &forward_addr_.sin_addr) != 1) {
            std::cerr << "Invalid forward IP\n";
            return false;
        }

        return true;
    }

    void run(std::atomic<bool>& running) {
        std::vector<epoll_event> events(cfg::kMaxEvents);
        alignas(64) char buffer[cfg::kBufferSize];

        while (running.load(std::memory_order_relaxed)) {
            int n = epoll_wait(epfd_, events.data(), cfg::kMaxEvents, 100);
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("epoll_wait");
                break;
            }

            for (int i = 0; i < n; ++i) {
                if (events[i].data.fd != sockfd_) continue;

                while (true) {
                    sockaddr_in src{};
                    socklen_t slen = sizeof(src);

                    ssize_t r = recvfrom(sockfd_, buffer, sizeof(buffer), 0,
                                         reinterpret_cast<sockaddr*>(&src), &slen);

                    if (r < 0) {
                        if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                        perror("recvfrom");
                        break;
                    }

                    if (!filter_.allow(src, buffer, r)) {
                        continue;
                    }

                    ssize_t s = sendto(sockfd_, buffer, r, 0,
                                       reinterpret_cast<sockaddr*>(&forward_addr_),
                                       sizeof(forward_addr_));
                    if (s < 0) {
                        perror("sendto");
                    }
                }
            }
        }
    }

    ~Worker() {
        if (sockfd_ >= 0) close(sockfd_);
        if (epfd_ >= 0) close(epfd_);
    }

private:
    int listen_port_;
    std::string forward_ip_;
    int forward_port_;

    int sockfd_ = -1;
    int epfd_ = -1;
    sockaddr_in forward_addr_{};
    PacketFilter filter_;
};

int main() {
    std::atomic<bool> running{true};
    std::vector<std::thread> threads;
    std::vector<std::unique_ptr<Worker>> workers;

    for (int i = 0; i < cfg::kWorkerThreads; ++i) {
        auto worker = std::make_unique<Worker>(
            cfg::kListenPort, cfg::kForwardIp, cfg::kForwardPort);

        if (!worker->init()) {
            std::cerr << "Worker init failed\n";
            return 1;
        }

        threads.emplace_back([&running, w = worker.get()]() {
            w->run(running);
        });

        workers.push_back(std::move(worker));
    }

    std::cout << "UDP filter/forwarder running on port " << cfg::kListenPort
              << ", forwarding to " << cfg::kForwardIp << ":" << cfg::kForwardPort
              << "\nPress Ctrl+C to stop.\n";

    for (auto& t : threads) {
        t.join();
    }

    return 0;
}
```

