```rust
use anyhow::{anyhow, Context, Result};
use clap::Parser;
use crossbeam_channel::{bounded, Receiver, Sender};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Input interface name
    #[arg(long)]
    in_if: String,

    /// Output interface name
    #[arg(long)]
    out_if: String,

    /// Optional destination UDP port to allow
    #[arg(long)]
    udp_dst_port: Option<u16>,

    /// Optional destination TCP port to allow
    #[arg(long)]
    tcp_dst_port: Option<u16>,

    /// Queue depth between RX and TX
    #[arg(long, default_value_t = 4096)]
    queue_depth: usize,
}

#[derive(Clone, Debug)]
struct Filter {
    udp_dst_port: Option<u16>,
    tcp_dst_port: Option<u16>,
}

impl Filter {
    #[inline]
    fn allows(&self, frame: &[u8]) -> bool {
        let eth = match EthernetPacket::new(frame) {
            Some(p) => p,
            None => return false,
        };

        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                let ip = match Ipv4Packet::new(eth.payload()) {
                    Some(p) => p,
                    None => return false,
                };

                match ip.get_next_level_protocol() {
                    IpNextHeaderProtocols::Udp => {
                        if let Some(port) = self.udp_dst_port {
                            let udp = match UdpPacket::new(ip.payload()) {
                                Some(p) => p,
                                None => return false,
                            };
                            udp.get_destination() == port
                        } else {
                            false
                        }
                    }
                    IpNextHeaderProtocols::Tcp => {
                        if let Some(port) = self.tcp_dst_port {
                            let tcp = match TcpPacket::new(ip.payload()) {
                                Some(p) => p,
                                None => return false,
                            };
                            tcp.get_destination() == port
                        } else {
                            false
                        }
                    }
                    _ => false,
                }
            }
            _ => false,
        }
    }
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .ok_or_else(|| anyhow!("interface not found: {}", name))
}

fn make_channel(
    iface: &NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;
    config.promiscuous = true;

    match datalink::channel(iface, config).context("failed to create datalink channel")? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => Err(anyhow!("unsupported channel type")),
    }
}

fn rx_loop(mut rx: Box<dyn DataLinkReceiver>, txq: Sender<Vec<u8>>, filter: Arc<Filter>) {
    loop {
        match rx.next() {
            Ok(packet) => {
                if filter.allows(packet) {
                    // Copy once into owned buffer for cross-thread handoff.
                    let mut buf = Vec::with_capacity(packet.len());
                    buf.extend_from_slice(packet);
                    let _ = txq.try_send(buf);
                }
            }
            Err(_) => {
                // Timeout or transient error; continue.
                continue;
            }
        }
    }
}

fn tx_loop(mut tx: Box<dyn DataLinkSender>, rxq: Receiver<Vec<u8>>) {
    while let Ok(frame) = rxq.recv() {
        let _ = tx.send_to(&frame, None);
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    let in_if = find_interface(&args.in_if)?;
    let out_if = find_interface(&args.out_if)?;

    let (_in_tx_unused, in_rx) = make_channel(&in_if)?;
    let (out_tx, _out_rx_unused) = make_channel(&out_if)?;

    let filter = Arc::new(Filter {
        udp_dst_port: args.udp_dst_port,
        tcp_dst_port: args.tcp_dst_port,
    });

    let (txq, rxq) = bounded::<Vec<u8>>(args.queue_depth);

    let filter_rx = filter.clone();
    let rx_thread = thread::spawn(move || rx_loop(in_rx, txq, filter_rx));
    let tx_thread = thread::spawn(move || tx_loop(out_tx, rxq));

    rx_thread.join().unwrap();
    tx_thread.join().unwrap();

    Ok(())
}
```

