use anyhow::{Context, Result};
use clap::Parser;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use log::{debug, info, warn};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Ingress interface
    #[arg(long)]
    ingress: String,

    /// Egress interface
    #[arg(long)]
    egress: String,

    /// Allow only this destination UDP port (repeatable)
    #[arg(long)]
    allow_udp_port: Vec<u16>,

    /// Allow only this destination TCP port (repeatable)
    #[arg(long)]
    allow_tcp_port: Vec<u16>,

    /// Optional allowed destination IPv4
    #[arg(long)]
    allow_dst_ip: Vec<Ipv4Addr>,
}

#[derive(Default)]
struct Stats {
    rx: u64,
    tx: u64,
    drop: u64,
    parse_err: u64,
}

#[derive(Clone, Debug)]
struct Policy {
    allow_udp_ports: Vec<u16>,
    allow_tcp_ports: Vec<u16>,
    allow_dst_ips: Vec<Ipv4Addr>,
}

impl Policy {
    fn allows(&self, packet: &[u8]) -> bool {
        let sliced = match SlicedPacket::from_ethernet(packet) {
            Ok(p) => p,
            Err(_) => return false,
        };

        let ip_ok = match &sliced.net {
            Some(InternetSlice::Ipv4(ip, _)) => {
                if self.allow_dst_ips.is_empty() {
                    true
                } else {
                    let dst = Ipv4Addr::from(ip.header().destination());
                    self.allow_dst_ips.contains(&dst)
                }
            }
            _ => false,
        };

        if !ip_ok {
            return false;
        }

        match &sliced.transport {
            Some(TransportSlice::Udp(udp)) => {
                if self.allow_udp_ports.is_empty() {
                    true
                } else {
                    self.allow_udp_ports.contains(&udp.destination_port())
                }
            }
            Some(TransportSlice::Tcp(tcp)) => {
                if self.allow_tcp_ports.is_empty() {
                    true
                } else {
                    self.allow_tcp_ports.contains(&tcp.destination_port())
                }
            }
            _ => false,
        }
    }
}

/// Placeholder frame buffer from RX
struct Frame {
    data: Vec<u8>,
}

/// Abstract low-latency I/O backend.
/// Replace with real AF_XDP socket/UMEM implementation.
trait IoBackend {
    fn recv_batch(&mut self, max_batch: usize) -> Result<Vec<Frame>>;
    fn send_batch(&mut self, frames: Vec<Frame>) -> Result<usize>;
}

/// Dummy backend for initial integration/testing.
struct DummyBackend {
    counter: u64,
}

impl DummyBackend {
    fn new() -> Self {
        Self { counter: 0 }
    }
}

impl IoBackend for DummyBackend {
    fn recv_batch(&mut self, _max_batch: usize) -> Result<Vec<Frame>> {
        std::thread::sleep(Duration::from_millis(10));
        self.counter += 1;
        Ok(Vec::new())
    }

    fn send_batch(&mut self, frames: Vec<Frame>) -> Result<usize> {
        Ok(frames.len())
    }
}

fn process_batch(
    ingress: &mut dyn IoBackend,
    egress: &mut dyn IoBackend,
    policy: &Policy,
    stats: &mut Stats,
) -> Result<()> {
    let frames = ingress.recv_batch(64)?;
    if frames.is_empty() {
        return Ok(());
    }

    stats.rx += frames.len() as u64;

    let mut forward = Vec::with_capacity(frames.len());

    for frame in frames {
        if policy.allows(&frame.data) {
            forward.push(frame);
        } else {
            stats.drop += 1;
        }
    }

    let sent = egress.send_batch(forward)?;
    stats.tx += sent as u64;

    Ok(())
}

fn main() -> Result<()> {
    env_logger::init();
    let args = Args::parse();

    let policy = Policy {
        allow_udp_ports: args.allow_udp_port,
        allow_tcp_ports: args.allow_tcp_port,
        allow_dst_ips: args.allow_dst_ip,
    };

    info!(
        "starting ultra-net ingress={} egress={}",
        args.ingress, args.egress
    );
    debug!("policy: {:?}", policy);

    // Replace with real AF_XDP backends.
    let mut ingress_backend = DummyBackend::new();
    let mut egress_backend = DummyBackend::new();

    let mut stats = Stats::default();
    let mut last = Instant::now();

    loop {
        if let Err(e) = process_batch(
            &mut ingress_backend,
            &mut egress_backend,
            &policy,
            &mut stats,
        ) {
            warn!("processing error: {e:#}");
        }

        if last.elapsed() >= Duration::from_secs(1) {
            info!(
                "stats rx={} tx={} drop={} parse_err={}",
                stats.rx, stats.tx, stats.drop, stats.parse_err
            );
            last = Instant::now();
        }
    }
}
