# 1) Kernel XDP program: `xdp_prog_kern.c`

```c
// xdp_prog_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

struct ethhdr {
    unsigned char h_dest[6];
    unsigned char h_source[6];
    __be16 h_proto;
};

struct iphdr {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    __u8 ihl:4,
         version:4;
#else
    __u8 version:4,
         ihl:4;
#endif
    __u8 tos;
    __be16 tot_len;
    __be16 id;
    __be16 frag_off;
    __u8 ttl;
    __u8 protocol;
    __be16 check;
    __be32 saddr;
    __be32 daddr;
};

#ifndef ETH_P_IP
#define ETH_P_IP 0x0800
#endif

static __always_inline int parse_eth(void **data, void *data_end, struct ethhdr **ethh) {
    struct ethhdr *eth = *data;
    if ((void *)(eth + 1) > data_end)
        return -1;
    *ethh = eth;
    *data = eth + 1;
    return bpf_ntohs(eth->h_proto);
}

static __always_inline int parse_ipv4(void **data, void *data_end, struct iphdr **iph) {
    struct iphdr *ip = *data;
    if ((void *)(ip + 1) > data_end)
        return -1;
    if (ip->ihl < 5)
        return -1;
    if ((void *)ip + ip->ihl * 4 > data_end)
        return -1;
    *iph = ip;
    *data = (void *)ip + ip->ihl * 4;
    return 0;
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth;
    int eth_proto = parse_eth(&data, data_end, &eth);
    if (eth_proto < 0)
        return XDP_DROP;

    if (eth_proto != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *ip;
    if (parse_ipv4(&data, data_end, &ip) < 0)
        return XDP_DROP;

    // Example policy:
    // - Drop ICMP
    // - Redirect UDP to interface in devmap key 0
    // - Pass TCP upward to kernel stack
    switch (ip->protocol) {
        case 1:  // ICMP
            return XDP_DROP;
        case 17: // UDP
            return bpf_redirect_map(&tx_port, 0, 0);
        case 6:  // TCP
            return XDP_PASS;
        default:
            return XDP_PASS;
    }
}

char _license[] SEC("license") = "GPL";
```

