# 2) Userspace loader: `xdp_loader.c`

This attaches the XDP program to an interface and populates the devmap with an egress interface.

```c
// xdp_loader.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <net/if.h>
#include <unistd.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <ingress_ifname> <egress_ifname>\n", prog);
}

int main(int argc, char **argv) {
    struct bpf_object *obj = NULL;
    struct bpf_program *prog = NULL;
    int prog_fd, map_fd;
    int ifindex_in, ifindex_out;
    int err;
    __u32 key = 0;
    __u32 val;

    if (argc != 3) {
        usage(argv[0]);
        return 1;
    }

    ifindex_in = if_nametoindex(argv[1]);
    ifindex_out = if_nametoindex(argv[2]);

    if (!ifindex_in || !ifindex_out) {
        fprintf(stderr, "Invalid interface name(s)\n");
        return 1;
    }

    obj = bpf_object__open_file("xdp_prog_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    prog = bpf_object__find_program_by_name(obj, "xdp_filter_forward");
    if (!prog) {
        fprintf(stderr, "Failed to find XDP program\n");
        bpf_object__close(obj);
        return 1;
    }

    prog_fd = bpf_program__fd(prog);

    map_fd = bpf_object__find_map_fd_by_name(obj, "tx_port");
    if (map_fd < 0) {
        fprintf(stderr, "Failed to find devmap\n");
        bpf_object__close(obj);
        return 1;
    }

    val = ifindex_out;
    err = bpf_map_update_elem(map_fd, &key, &val, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to update devmap: %s\n", strerror(errno));
        bpf_object__close(obj);
        return 1;
    }

    err = bpf_set_link_xdp_fd(ifindex_in, prog_fd, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to attach XDP program: %s\n", strerror(-err));
        bpf_object__close(obj);
        return 1;
    }

    printf("Attached XDP program to %s (ifindex=%d), redirecting UDP to %s (ifindex=%d)\n",
           argv[1], ifindex_in, argv[2], ifindex_out);

    printf("Press Ctrl+C to exit...\n");
    while (1) pause();

    bpf_set_link_xdp_fd(ifindex_in, -1, 0);
    bpf_object__close(obj);
    return 0;
}
```

