# src/packet.rs

```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EtherType {
    Ipv4,
    Other(u16),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpProto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub ethertype: EtherType,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub proto: IpProto,
    pub ihl_bytes: usize,
}

#[derive(Debug, Clone, Copy)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct ParsedPacket {
    pub eth: EthernetHeader,
    pub ipv4: Option<Ipv4Header>,
    pub tcp: Option<TcpHeader>,
    pub udp: Option<UdpHeader>,
}

impl ParsedPacket {
    pub fn src_port(&self) -> Option<u16> {
        self.tcp.map(|h| h.src_port).or_else(|| self.udp.map(|h| h.src_port))
    }

    pub fn dst_port(&self) -> Option<u16> {
        self.tcp.map(|h| h.dst_port).or_else(|| self.udp.map(|h| h.dst_port))
    }
}

pub fn parse_packet(buf: &[u8]) -> Option<ParsedPacket> {
    if buf.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    let eth = EthernetHeader {
        ethertype: match ethertype {
            0x0800 => EtherType::Ipv4,
            other => EtherType::Other(other),
        },
    };

    let mut parsed = ParsedPacket {
        eth,
        ipv4: None,
        tcp: None,
        udp: None,
    };

    if eth.ethertype != EtherType::Ipv4 {
        return Some(parsed);
    }

    if buf.len() < 14 + 20 {
        return None;
    }

    let ip = &buf[14..];
    let version = ip[0] >> 4;
    let ihl = (ip[0] & 0x0f) as usize;
    if version != 4 || ihl < 5 {
        return None;
    }
    let ihl_bytes = ihl * 4;
    if ip.len() < ihl_bytes {
        return None;
    }

    let proto = match ip[9] {
        6 => IpProto::Tcp,
        17 => IpProto::Udp,
        other => IpProto::Other(other),
    };

    let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
    let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

    let ipv4 = Ipv4Header {
        src,
        dst,
        proto,
        ihl_bytes,
    };
    parsed.ipv4 = Some(ipv4);

    let l4 = &ip[ihl_bytes..];
    match proto {
        IpProto::Tcp => {
            if l4.len() < 4 {
                return Some(parsed);
            }
            parsed.tcp = Some(TcpHeader {
                src_port: u16::from_be_bytes([l4[0], l4[1]]),
                dst_port: u16::from_be_bytes([l4[2], l4[3]]),
            });
        }
        IpProto::Udp => {
            if l4.len() < 4 {
                return Some(parsed);
            }
            parsed.udp = Some(UdpHeader {
                src_port: u16::from_be_bytes([l4[0], l4[1]]),
                dst_port: u16::from_be_bytes([l4[2], l4[3]]),
            });
        }
        IpProto::Other(_) => {}
    }

    Some(parsed)
}
