# src/filter.rs

```rust
use crate::config::{FilterRule, L4Proto, RuleAction};
use crate::packet::{IpProto, ParsedPacket};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    Drop,
    Pass,
    Forward,
}

pub struct FilterEngine {
    rules: Vec<FilterRule>,
}

impl FilterEngine {
    pub fn new(rules: Vec<FilterRule>) -> Self {
        Self { rules }
    }

    pub fn classify(&self, pkt: &ParsedPacket) -> Decision {
        for rule in &self.rules {
            if rule_matches(rule, pkt) {
                return match rule.action {
                    RuleAction::Drop => Decision::Drop,
                    RuleAction::Pass => Decision::Pass,
                    RuleAction::Forward => Decision::Forward,
                };
            }
        }

        Decision::Pass
    }
}

fn rule_matches(rule: &FilterRule, pkt: &ParsedPacket) -> bool {
    let Some(ip) = pkt.ipv4 else {
        return false;
    };

    if let Some(src_ip) = rule.src_ip {
        if ip.src != src_ip {
            return false;
        }
    }

    if let Some(dst_ip) = rule.dst_ip {
        if ip.dst != dst_ip {
            return false;
        }
    }

    if let Some(proto) = rule.protocol {
        let matches = matches!(
            (proto, ip.proto),
            (L4Proto::Tcp, IpProto::Tcp) | (L4Proto::Udp, IpProto::Udp)
        );
        if !matches {
            return false;
        }
    }

    if let Some(src_port) = rule.src_port {
        if pkt.src_port() != Some(src_port) {
            return false;
        }
    }

    if let Some(dst_port) = rule.dst_port {
        if pkt.dst_port() != Some(dst_port) {
            return false;
        }
    }

    true
}
