```rust
use anyhow::Result;

pub trait PacketBackend {
    fn recv_batch(&mut self, out: &mut Vec<Vec<u8>>) -> Result<usize>;
    fn send_egress(&mut self, pkt: Vec<u8>) -> Result<()>;
    fn recycle(&mut self, _pkt: Vec<u8>) -> Result<()> {
        Ok(())
    }
}

pub struct MockBackend {
    packets: Vec<Vec<u8>>,
    idx: usize,
    sent: usize,
}

impl MockBackend {
    pub fn new(packets: Vec<Vec<u8>>) -> Self {
        Self {
            packets,
            idx: 0,
            sent: 0,
        }
    }
}

impl PacketBackend for MockBackend {
    fn recv_batch(&mut self, out: &mut Vec<Vec<u8>>) -> Result<usize> {
        out.clear();
        let mut count = 0;
        while self.idx < self.packets.len() && count < 64 {
            out.push(self.packets[self.idx].clone());
            self.idx += 1;
            count += 1;
        }
        Ok(count)
    }

    fn send_egress(&mut self, _pkt: Vec<u8>) -> Result<()> {
        self.sent += 1;
        Ok(())
    }
}
