# src/service.rs

```rust
use anyhow::Result;

use crate::backend::PacketBackend;
use crate::filter::{Decision, FilterEngine};
use crate::forward::{ForwardAction, Forwarder};
use crate::packet::parse_packet;
use crate::stats::Stats;

pub struct NetworkService<B: PacketBackend> {
    backend: B,
    filter: FilterEngine,
    forwarder: Forwarder,
    stats: Stats,
    batch: Vec<Vec<u8>>,
}

impl<B: PacketBackend> NetworkService<B> {
    pub fn new(backend: B, filter: FilterEngine) -> Self {
        Self {
            backend,
            filter,
            forwarder: Forwarder::new(),
            stats: Stats::default(),
            batch: Vec::with_capacity(64),
        }
    }

    pub fn run_once(&mut self) -> Result<usize> {
        let n = self.backend.recv_batch(&mut self.batch)?;
        if n == 0 {
            return Ok(0);
        }

        for pkt in self.batch.drain(..) {
            self.stats.inc_rx();

            let Some(parsed) = parse_packet(&pkt) else {
                self.stats.inc_parse_error();
                self.backend.recycle(pkt)?;
                continue;
            };

            let decision = self.filter.classify(&parsed);
            let action = self.forwarder.action_for(decision);

            match action {
                ForwardAction::Drop => {
                    self.stats.inc_drop();
                    self.backend.recycle(pkt)?;
                }
                ForwardAction::TxEgress => {
                    self.backend.send_egress(pkt)?;
                    self.stats.inc_tx();
                }
                ForwardAction::TxIngress => {
                    self.backend.recycle(pkt)?;
                }
                ForwardAction::Consume => {
                    self.stats.inc_pass();
                    self.backend.recycle(pkt)?;
                }
            }
        }

        Ok(n)
    }

    pub fn stats(&self) -> &Stats {
        &self.stats
    }
}
