# 7. Packet parser

This is a minimal parser for Ethernet + IPv4 + TCP/UDP.

```rust
pub fn parse_packet(buf: &[u8]) -> Option<PacketMeta> {
    if buf.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    if ethertype != 0x0800 {
        return Some(PacketMeta {
            ethertype,
            src_ip: None,
            dst_ip: None,
            protocol: None,
            src_port: None,
            dst_port: None,
        });
    }

    if buf.len() < 34 {
        return None;
    }

    let ip_start = 14;
    let version_ihl = buf[ip_start];
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if ihl < 20 || buf.len() < ip_start + ihl {
        return None;
    }

    let protocol = buf[ip_start + 9];
    let src_ip = [
        buf[ip_start + 12],
        buf[ip_start + 13],
        buf[ip_start + 14],
        buf[ip_start + 15],
    ];
    let dst_ip = [
        buf[ip_start + 16],
        buf[ip_start + 17],
        buf[ip_start + 18],
        buf[ip_start + 19],
    ];

    let l4_start = ip_start + ihl;
    let (src_port, dst_port) = match protocol {
        6 | 17 => {
            if buf.len() < l4_start + 4 {
                (None, None)
            } else {
                let sp = u16::from_be_bytes([buf[l4_start], buf[l4_start + 1]]);
                let dp = u16::from_be_bytes([buf[l4_start + 2], buf[l4_start + 3]]);
                (Some(sp), Some(dp))
            }
        }
        _ => (None, None),
    };

    Some(PacketMeta {
        ethertype,
        src_ip: Some(src_ip),
        dst_ip: Some(dst_ip),
        protocol: Some(protocol),
        src_port,
        dst_port,
    })
}
```

