use std::net::{IpAddr, Ipv4Addr};

pub fn matches_rule(meta: &PacketMeta, rule: &Rule) -> bool {
    let src_ip = match meta.src_ip {
        Some(ip) => IpAddr::V4(Ipv4Addr::new(ip[0], ip[1], ip[2], ip[3])),
        None => return false,
    };

    if !rule.src_cidr.contains(&src_ip) {
        return false;
    }

    if let Some(dst_cidr) = &rule.dst_cidr {
        let dst_ip = match meta.dst_ip {
            Some(ip) => IpAddr::V4(Ipv4Addr::new(ip[0], ip[1], ip[2], ip[3])),
            None => return false,
        };
        if !dst_cidr.contains(&dst_ip) {
            return false;
        }
    }

    match rule.protocol {
        Protocol::Any => {}
        Protocol::Tcp => {
            if meta.protocol != Some(6) {
                return false;
            }
        }
        Protocol::Udp => {
            if meta.protocol != Some(17) {
                return false;
            }
        }
    }

    if let Some(port) = rule.dst_port {
        if meta.dst_port != Some(port) {
            return false;
        }
    }

    true
}

pub fn decide(meta: &PacketMeta, rules: &[Rule]) -> Action {
    for rule in rules {
        if matches_rule(meta, rule) {
            return rule.action.clone();
        }
    }
    Action::Deny
}
