# 9. Forwarding loop skeleton

Below is a **safe conceptual skeleton**. It does not include raw AF_XDP bindings, but shows the structure.

```rust
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

pub struct Forwarder {
    rules: Arc<Vec<Rule>>,
    running: Arc<AtomicBool>,
}

impl Forwarder {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules: Arc::new(rules),
            running: Arc::new(AtomicBool::new(true)),
        }
    }

    pub fn run(&self) -> anyhow::Result<()> {
        while self.running.load(Ordering::Relaxed) {
            // 1. receive burst from ingress ring
            let packets: Vec<Vec<u8>> = self.recv_burst()?;

            // 2. classify and batch actions
            let mut to_forward = Vec::with_capacity(packets.len());

            for pkt in packets {
                if let Some(meta) = parse_packet(&pkt) {
                    match decide(&meta, &self.rules) {
                        Action::Allow => to_forward.push(pkt),
                        Action::Deny => {
                            // increment drop counter
                        }
                    }
                } else {
                    // malformed packet
                }
            }

            // 3. transmit allowed burst to egress ring
            self.send_burst(to_forward)?;
        }

        Ok(())
    }

    fn recv_burst(&self) -> anyhow::Result<Vec<Vec<u8>>> {
        Ok(Vec::new())
    }

    fn send_burst(&self, _packets: Vec<Vec<u8>>) -> anyhow::Result<()> {
        Ok(())
    }
}
