# 1. eBPF/XDP program

Save as `xdp_filter_forward.bpf.c`:

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>

char LICENSE[] SEC("license") = "GPL";

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 source address in network byte order
    __type(value, __u8);  // 1 = blocked
} blocklist SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);   // logical port
    __type(value, __u32); // ifindex
} tx_ports SEC(".maps");

struct stats_rec {
    __u64 passed;
    __u64 dropped;
    __u64 redirected;
    __u64 non_ipv4;
    __u64 malformed;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct stats_rec);
} stats SEC(".maps");

static __always_inline void count_passed(void) {
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s) s->passed++;
}

static __always_inline void count_dropped(void) {
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s) s->dropped++;
}

static __always_inline void count_redirected(void) {
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s) s->redirected++;
}

static __always_inline void count_non_ipv4(void) {
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s) s->non_ipv4++;
}

static __always_inline void count_malformed(void) {
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s) s->malformed++;
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        count_malformed();
        return XDP_DROP;
    }

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP) {
        count_non_ipv4();
        return XDP_PASS;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        count_malformed();
        return XDP_DROP;
    }

    if (iph->ihl < 5) {
        count_malformed();
        return XDP_DROP;
    }

    void *l4 = (void *)iph + iph->ihl * 4;
    if (l4 > data_end) {
        count_malformed();
        return XDP_DROP;
    }

    // Example: only inspect UDP specially; other IPv4 traffic is redirected too.
    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udph = l4;
        if ((void *)(udph + 1) > data_end) {
            count_malformed();
            return XDP_DROP;
        }
    }

    __u32 src = iph->saddr;
    __u8 *blocked = bpf_map_lookup_elem(&blocklist, &src);
    if (blocked && *blocked) {
        count_dropped();
        return XDP_DROP;
    }

    // Redirect to tx_ports[0] if configured; otherwise pass.
    __u32 out_port = 0;
    __u32 *ifindex = bpf_map_lookup_elem(&tx_ports, &out_port);
    if (ifindex) {
        count_redirected();
        return bpf_redirect_map(&tx_ports, out_port, 0);
    }

    count_passed();
    return XDP_PASS;
}
```

