# 2. Userspace loader

Save as `loader.c`:

```c
// SPDX-License-Identifier: GPL-2.0
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

struct stats_rec {
    __u64 passed;
    __u64 dropped;
    __u64 redirected;
    __u64 non_ipv4;
    __u64 malformed;
};

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <ingress_ifname> <egress_ifname> [blocked_ipv4 ...]\n",
        prog);
}

int main(int argc, char **argv)
{
    struct bpf_object *obj = NULL;
    int prog_fd, ifindex_in, ifindex_out;
    int map_blocklist, map_tx_ports, map_stats;
    int err;

    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    ifindex_in = if_nametoindex(argv[1]);
    ifindex_out = if_nametoindex(argv[2]);

    if (!ifindex_in || !ifindex_out) {
        fprintf(stderr, "Invalid interface name(s)\n");
        return 1;
    }

    obj = bpf_object__open_file("xdp_filter_forward.bpf.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        goto cleanup;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_filter_forward");
    if (!prog) {
        fprintf(stderr, "Program not found\n");
        err = 1;
        goto cleanup;
    }

    prog_fd = bpf_program__fd(prog);

    err = bpf_xdp_attach(ifindex_in, prog_fd, XDP_FLAGS_DRV_MODE, NULL);
    if (err) {
        fprintf(stderr, "Failed to attach XDP program: %s\n", strerror(-err));
        goto cleanup;
    }

    map_blocklist = bpf_object__find_map_fd_by_name(obj, "blocklist");
    map_tx_ports  = bpf_object__find_map_fd_by_name(obj, "tx_ports");
    map_stats     = bpf_object__find_map_fd_by_name(obj, "stats");

    if (map_blocklist < 0 || map_tx_ports < 0 || map_stats < 0) {
        fprintf(stderr, "Failed to find one or more maps\n");
        err = 1;
        goto detach;
    }

    __u32 key = 0;
    __u32 val = ifindex_out;
    err = bpf_map_update_elem(map_tx_ports, &key, &val, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to configure tx_ports\n");
        goto detach;
    }

    for (int i = 3; i < argc; i++) {
        struct in_addr addr;
        if (inet_pton(AF_INET, argv[i], &addr) != 1) {
            fprintf(stderr, "Invalid IPv4 address: %s\n", argv[i]);
            continue;
        }
        __u32 ip = addr.s_addr; // network byte order
        __u8 blocked = 1;
        if (bpf_map_update_elem(map_blocklist, &ip, &blocked, BPF_ANY)) {
            fprintf(stderr, "Failed to add blocklist entry for %s\n", argv[i]);
        }
    }

    printf("XDP program attached to %s (ifindex=%d), redirecting to %s (ifindex=%d)\n",
           argv[1], ifindex_in, argv[2], ifindex_out);
    printf("Press Ctrl+C to exit\n");

    while (1) {
        sleep(2);

        __u32 stats_key = 0;
        int ncpus = libbpf_num_possible_cpus();
        struct stats_rec *percpu = calloc(ncpus, sizeof(*percpu));
        if (!percpu)
            continue;

        if (bpf_map_lookup_elem(map_stats, &stats_key, percpu) == 0) {
            struct stats_rec total = {0};
            for (int i = 0; i < ncpus; i++) {
                total.passed     += percpu[i].passed;
                total.dropped    += percpu[i].dropped;
                total.redirected += percpu[i].redirected;
                total.non_ipv4   += percpu[i].non_ipv4;
                total.malformed  += percpu[i].malformed;
            }

            printf("stats: pass=%llu drop=%llu redirect=%llu non_ipv4=%llu malformed=%llu\n",
                   (unsigned long long)total.passed,
                   (unsigned long long)total.dropped,
                   (unsigned long long)total.redirected,
                   (unsigned long long)total.non_ipv4,
                   (unsigned long long)total.malformed);
        }

        free(percpu);
    }

detach:
    bpf_xdp_detach(ifindex_in, XDP_FLAGS_DRV_MODE, NULL);

cleanup:
    bpf_object__close(obj);
    return err != 0;
}
```

