## Initial XDP Program in C

This example:

- drops packets from blocked IPv4 sources
- optionally redirects packets to another interface
- counts packets by action

### `xdp_filter_kern.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/in.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, __u32);   // IPv4 source address
    __type(value, __u8);  // 1 = blocked
} blocklist SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 3);
    __type(key, __u32);
    __type(value, __u64);
} counters SEC(".maps");
// counters[0] = pass, counters[1] = drop, counters[2] = redirect

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

static __always_inline void count_action(__u32 idx) {
    __u64 *val = bpf_map_lookup_elem(&counters, &idx);
    if (val)
        __sync_fetch_and_add(val, 1);
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP) {
        count_action(0);
        return XDP_PASS;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_ABORTED;

    __u32 src_ip = iph->saddr;
    __u8 *blocked = bpf_map_lookup_elem(&blocklist, &src_ip);
    if (blocked && *blocked == 1) {
        count_action(1);
        return XDP_DROP;
    }

    // Example: redirect UDP traffic to interface in tx_port[0]
    if (iph->protocol == IPPROTO_UDP) {
        __u32 key = 0;
        __u32 *ifindex = bpf_map_lookup_elem(&tx_port, &key);
        if (ifindex) {
            count_action(2);
            return bpf_redirect_map(&tx_port, key, 0);
        }
    }

    count_action(0);
    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

