### `src/main.rs`

```rust
use anyhow::{Context, Result};
use clap::Parser;
use libbpf_rs::{MapCore, ObjectBuilder, XdpFlags};
use std::net::Ipv4Addr;
use std::str::FromStr;
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug)]
struct Args {
    #[arg(long)]
    iface: String,

    #[arg(long)]
    redirect_ifindex: Option<u32>,

    #[arg(long)]
    block_ip: Vec<String>,

    #[arg(long, default_value = "xdp_filter_kern.bpf.o")]
    bpf_obj: String,
}

fn ipv4_to_u32(ip: &str) -> Result<u32> {
    let addr = Ipv4Addr::from_str(ip)?;
    Ok(u32::from_be_bytes(addr.octets()))
}

fn main() -> Result<()> {
    let args = Args::parse();

    let builder = ObjectBuilder::default();
    let open_obj = builder.open_file(&args.bpf_obj)
        .with_context(|| format!("opening BPF object {}", args.bpf_obj))?;
    let mut obj = open_obj.load()?;

    let prog = obj.prog_mut("xdp_filter_forward")
        .context("finding xdp_filter_forward program")?;

    prog.attach_xdp(&args.iface, XdpFlags::default())
        .with_context(|| format!("attaching XDP to {}", args.iface))?;

    if let Some(ifindex) = args.redirect_ifindex {
        let map = obj.map_mut("tx_port").context("finding tx_port map")?;
        let key: u32 = 0;
        map.update(&key.to_ne_bytes(), &ifindex.to_ne_bytes(), libbpf_rs::MapFlags::ANY)?;
    }

    if !args.block_ip.is_empty() {
        let map = obj.map_mut("blocklist").context("finding blocklist map")?;
        for ip in &args.block_ip {
            let ip_u32 = ipv4_to_u32(ip)?;
            let val: u8 = 1;
            map.update(&ip_u32.to_ne_bytes(), &[val], libbpf_rs::MapFlags::ANY)
                .with_context(|| format!("adding {} to blocklist", ip))?;
        }
    }

    let counters = obj.map("counters").context("finding counters map")?;

    ctrlc::set_handler(|| {
        std::process::exit(0);
    })?;

    loop {
        for i in 0u32..3 {
            if let Some(v) = counters.lookup(&i.to_ne_bytes(), libbpf_rs::MapFlags::ANY)? {
                if v.len() == 8 {
                    let mut arr = [0u8; 8];
                    arr.copy_from_slice(&v);
                    let count = u64::from_ne_bytes(arr);
                    let label = match i {
                        0 => "pass",
                        1 => "drop",
                        2 => "redirect",
                        _ => "unknown",
                    };
                    println!("{label}: {count}");
                }
            }
        }
        println!("---");
        thread::sleep(Duration::from_secs(2));
    }
}
```

