## src/main.rs
```rust
use libc::{
    bind, close, if_nametoindex, recv, sendto, setsockopt, sockaddr, sockaddr_ll, socket, AF_PACKET,
    ETH_P_ALL, PACKET_ADD_MEMBERSHIP, PACKET_MR_PROMISC, SOCK_RAW, SOL_PACKET,
};
use std::ffi::CString;
use std::io;
use std::mem::{size_of, zeroed};
use std::os::fd::RawFd;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use thiserror::Error;

const BUF_SIZE: usize = 2048;

#[derive(Debug, Error)]
enum AppError {
    #[error("io error: {0}")]
    Io(#[from] io::Error),
    #[error("interface not found: {0}")]
    InterfaceNotFound(String),
    #[error("syscall failed: {0}")]
    Syscall(String),
}

#[derive(Default)]
struct Counters {
    rx_packets: AtomicU64,
    tx_packets: AtomicU64,
    dropped_packets: AtomicU64,
    rx_bytes: AtomicU64,
    tx_bytes: AtomicU64,
}

#[derive(Clone)]
struct FilterRule {
    ethertype_allowlist: Vec<u16>,
}

impl FilterRule {
    fn allows(&self, frame: &[u8]) -> bool {
        if frame.len() < 14 {
            return false;
        }
        let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
        self.ethertype_allowlist.contains(&ethertype)
    }
}

struct PacketSocket {
    fd: RawFd,
    if_index: i32,
}

impl Drop for PacketSocket {
    fn drop(&mut self) {
        unsafe {
            close(self.fd);
        }
    }
}

impl PacketSocket {
    fn open(interface: &str) -> Result<Self, AppError> {
        let if_name = CString::new(interface).unwrap();
        let if_index = unsafe { if_nametoindex(if_name.as_ptr()) } as i32;
        if if_index == 0 {
            return Err(AppError::InterfaceNotFound(interface.to_string()));
        }

        let fd = unsafe { socket(AF_PACKET, SOCK_RAW, (ETH_P_ALL as u16).to_be() as i32) };
        if fd < 0 {
            return Err(io::Error::last_os_error().into());
        }

        let mut addr: sockaddr_ll = unsafe { zeroed() };
        addr.sll_family = AF_PACKET as u16;
        addr.sll_protocol = (ETH_P_ALL as u16).to_be();
        addr.sll_ifindex = if_index;

        let rc = unsafe {
            bind(
                fd,
                &addr as *const sockaddr_ll as *const sockaddr,
                size_of::<sockaddr_ll>() as u32,
            )
        };
        if rc < 0 {
            unsafe { close(fd) };
            return Err(io::Error::last_os_error().into());
        }

        Ok(Self { fd, if_index })
    }

    fn recv_frame(&self, buf: &mut [u8]) -> Result<usize, AppError> {
        let n = unsafe { recv(self.fd, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
        if n < 0 {
            return Err(io::Error::last_os_error().into());
        }
        Ok(n as usize)
    }

    fn send_frame(&self, frame: &[u8]) -> Result<usize, AppError> {
        let mut addr: sockaddr_ll = unsafe { zeroed() };
        addr.sll_family = AF_PACKET as u16;
        addr.sll_protocol = (ETH_P_ALL as u16).to_be();
        addr.sll_ifindex = self.if_index;

        let n = unsafe {
            sendto(
                self.fd,
                frame.as_ptr() as *const _,
                frame.len(),
                0,
                &addr as *const sockaddr_ll as *const sockaddr,
                size_of::<sockaddr_ll>() as u32,
            )
        };
        if n < 0 {
            return Err(io::Error::last_os_error().into());
        }
        Ok(n as usize)
    }
}

fn forwarding_loop(
    rx_if: &str,
    tx_if: &str,
    filter: FilterRule,
    counters: Arc<Counters>,
) -> Result<(), AppError> {
    let rx_sock = PacketSocket::open(rx_if)?;
    let tx_sock = PacketSocket::open(tx_if)?;

    let mut buf = vec![0u8; BUF_SIZE];

    loop {
        let n = rx_sock.recv_frame(&mut buf)?;
        counters.rx_packets.fetch_add(1, Ordering::Relaxed);
        counters.rx_bytes.fetch_add(n as u64, Ordering::Relaxed);

        let frame = &buf[..n];

        if !filter.allows(frame) {
            counters.dropped_packets.fetch_add(1, Ordering::Relaxed);
            continue;
        }

        let sent = tx_sock.send_frame(frame)?;
        counters.tx_packets.fetch_add(1, Ordering::Relaxed);
        counters.tx_bytes.fetch_add(sent as u64, Ordering::Relaxed);
    }
}

fn main() -> Result<(), AppError> {
    let counters = Arc::new(Counters::default());

    let stats = counters.clone();
    thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(1));
        println!(
            "rx_pkts={} tx_pkts={} drop_pkts={} rx_bytes={} tx_bytes={}",
            stats.rx_packets.load(Ordering::Relaxed),
            stats.tx_packets.load(Ordering::Relaxed),
            stats.dropped_packets.load(Ordering::Relaxed),
            stats.rx_bytes.load(Ordering::Relaxed),
            stats.tx_bytes.load(Ordering::Relaxed),
        );
    });

    let filter = FilterRule {
        // Example: IPv4 (0x0800), ARP (0x0806), IPv6 (0x86DD)
        ethertype_allowlist: vec![0x0800, 0x0806, 0x86DD],
    };

    forwarding_loop("eth0", "eth1", filter, counters)
}
```

