# 1. XDP/eBPF program

This example:
- parses Ethernet + IPv4
- checks protocol and destination port
- redirects matching packets to an AF_XDP socket
- otherwise passes or drops

## `ebpf/xdp_filter.bpf.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct rule_key {
    __u8 proto;
    __u16 dport;
};

struct rule_val {
    __u32 action;   // 0=PASS, 1=DROP, 2=REDIRECT
    __u32 xsks_map_key;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, struct rule_key);
    __type(value, struct rule_val);
} rules SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_XSKMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} xsks_map SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct iphdr **iph) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    *iph = (void *)(eth + 1);
    if ((void *)((*iph) + 1) > data_end)
        return -1;

    return 0;
}

SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct iphdr *iph;

    if (parse_ipv4(data, data_end, &iph) < 0)
        return XDP_PASS;

    struct rule_key key = {};
    key.proto = iph->protocol;

    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (void *)iph + iph->ihl * 4;
        if ((void *)(udp + 1) > data_end)
            return XDP_PASS;
        key.dport = bpf_ntohs(udp->dest);
    } else if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (void *)iph + iph->ihl * 4;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        key.dport = bpf_ntohs(tcp->dest);
    } else {
        return XDP_PASS;
    }

    struct rule_val *rv = bpf_map_lookup_elem(&rules, &key);
    if (!rv)
        return XDP_PASS;

    if (rv->action == 1)
        return XDP_DROP;

    if (rv->action == 2)
        return bpf_redirect_map(&xsks_map, rv->xsks_map_key, XDP_PASS);

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

