use anyhow::{Context, Result};
use aya::maps::HashMap as BpfHashMap;
use aya::programs::{Xdp, XdpFlags};
use aya::{include_bytes_aligned, Bpf};
use clap::Parser;
use std::net::SocketAddr;
use tokio::signal;

#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct RuleKey {
    proto: u8,
    dport: u16,
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct RuleVal {
    action: u32,
    xsks_map_key: u32,
}

#[derive(Parser, Debug)]
struct Opt {
    #[arg(long, default_value = "eth0")]
    iface: String,

    #[arg(long, default_value = "127.0.0.1:8080")]
    api: SocketAddr,
}

#[tokio::main]
async fn main() -> Result<()> {
    let opt = Opt::parse();

    let mut bpf = Bpf::load(include_bytes_aligned!(
        "../target/bpfel-unknown-none/debug/xdp_filter"
    ))?;

    let program: &mut Xdp = bpf.program_mut("xdp_filter_prog")
        .context("program not found")?
        .try_into()?;

    program.load()?;
    program.attach(&opt.iface, XdpFlags::default())
        .context("failed to attach XDP program")?;

    let mut rules: BpfHashMap<_, RuleKey, RuleVal> =
        BpfHashMap::try_from(bpf.map_mut("rules")?)?;

    // Example defensive rules:
    // Drop TCP/23
    rules.insert(
        RuleKey { proto: 6, dport: 23 },
        RuleVal { action: 1, xsks_map_key: 0 },
        0,
    )?;

    // Redirect UDP/9000 to userspace queue 0
    rules.insert(
        RuleKey { proto: 17, dport: 9000 },
        RuleVal { action: 2, xsks_map_key: 0 },
        0,
    )?;

    println!("service running on iface={} api={}", opt.iface, opt.api);
    println!("press Ctrl-C to stop");

    signal::ctrl_c().await?;
    println!("shutting down");
    Ok(())
}
