# 1) XDP program: `xdp_filter_forward.c`

```c
// xdp_filter_forward.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

char LICENSE[] SEC("license") = "GPL";

struct stats {
    __u64 packets;
    __u64 bytes;
};

enum action_id {
    ACT_PASS = 0,
    ACT_DROP = 1,
    ACT_REDIRECT = 2,
    ACT_MAX = 3,
};

// Blocklist of IPv4 source addresses.
// key: __u32 IPv4 address in network byte order
// val: __u8 dummy
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, __u32);
    __type(value, __u8);
} blocked_ips SEC(".maps");

// Redirect target interface index by ingress ifindex.
// key: ingress ifindex
// val: egress ifindex
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 256);
    __type(key, __u32);
    __type(value, __u32);
} redirect_ifindex SEC(".maps");

// Devmap used by bpf_redirect_map for fast redirect.
struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 256);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

// Per-CPU stats by action.
struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, ACT_MAX);
    __type(key, __u32);
    __type(value, struct stats);
} counters SEC(".maps");

static __always_inline void count_action(__u32 action, __u64 bytes)
{
    struct stats *s = bpf_map_lookup_elem(&counters, &action);
    if (!s)
        return;
    s->packets += 1;
    s->bytes += bytes;
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        count_action(ACT_DROP, 0);
        return XDP_DROP;
    }

    __u16 h_proto = bpf_ntohs(eth->h_proto);
    __u64 pkt_len = (__u64)((char *)data_end - (char *)data);

    // Only inspect IPv4 here; pass others.
    if (h_proto != ETH_P_IP) {
        count_action(ACT_PASS, pkt_len);
        return XDP_PASS;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        count_action(ACT_DROP, pkt_len);
        return XDP_DROP;
    }

    // Basic IPv4 header length validation.
    if (iph->ihl < 5) {
        count_action(ACT_DROP, pkt_len);
        return XDP_DROP;
    }

    if ((void *)iph + iph->ihl * 4 > data_end) {
        count_action(ACT_DROP, pkt_len);
        return XDP_DROP;
    }

    // Drop if source IP is blocked.
    __u32 src = iph->saddr; // network byte order
    __u8 *blocked = bpf_map_lookup_elem(&blocked_ips, &src);
    if (blocked) {
        count_action(ACT_DROP, pkt_len);
        return XDP_DROP;
    }

    // Optional redirect based on ingress ifindex.
    __u32 in_if = ctx->ingress_ifindex;
    __u32 *out_if = bpf_map_lookup_elem(&redirect_ifindex, &in_if);
    if (out_if) {
        __u32 port_key = *out_if;
        count_action(ACT_REDIRECT, pkt_len);
        return bpf_redirect_map(&tx_port, port_key, 0);
    }

    count_action(ACT_PASS, pkt_len);
    return XDP_PASS;
}
```

