# 3) Userspace loader in Go: `main.go`

This example:

- loads the XDP object
- attaches to an interface
- inserts blocked IPs
- configures redirect
- prints counters periodically

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
)

type Stats struct {
	Packets uint64
	Bytes   uint64
}

func ipv4ToBE(ipStr string) uint32 {
	ip := net.ParseIP(ipStr).To4()
	if ip == nil {
		log.Fatalf("invalid IPv4: %s", ipStr)
	}
	return binary.BigEndian.Uint32(ip)
}

func mustInterfaceIndex(name string) int {
	iface, err := net.InterfaceByName(name)
	if err != nil {
		log.Fatalf("lookup interface %s: %v", name, err)
	}
	return iface.Index
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <ingress-iface>\n", os.Args[0])
		os.Exit(1)
	}
	ifName := os.Args[1]

	spec, err := ebpf.LoadCollectionSpec("xdp_filter_forward.o")
	if err != nil {
		log.Fatalf("load spec: %v", err)
	}

	coll, err := ebpf.NewCollection(spec)
	if err != nil {
		log.Fatalf("new collection: %v", err)
	}
	defer coll.Close()

	prog := coll.Programs["xdp_filter_forward"]
	if prog == nil {
		log.Fatal("program xdp_filter_forward not found")
	}

	iface, err := net.InterfaceByName(ifName)
	if err != nil {
		log.Fatalf("interface lookup: %v", err)
	}

	l, err := link.AttachXDP(link.XDPOptions{
		Program:   prog,
		Interface: iface.Index,
		Flags:     link.XDPGenericMode, // switch to native/driver mode if supported
	})
	if err != nil {
		log.Fatalf("attach xdp: %v", err)
	}
	defer l.Close()

	blocked := coll.Maps["blocked_ips"]
	redirectMap := coll.Maps["redirect_ifindex"]
	txPort := coll.Maps["tx_port"]
	counters := coll.Maps["counters"]

	if blocked == nil || redirectMap == nil || txPort == nil || counters == nil {
		log.Fatal("required maps not found")
	}

	// Example blocklist entries.
	for _, ip := range []string{
		"10.0.0.10",
		"192.168.1.100",
	} {
		key := ipv4ToBE(ip)
		val := uint8(1)
		if err := blocked.Put(key, val); err != nil {
			log.Fatalf("insert blocked ip %s: %v", ip, err)
		}
	}

	// Example redirect: packets arriving on ingress iface are redirected to egress iface.
	// Set EGRESS_IFACE env var to enable.
	egressName := os.Getenv("EGRESS_IFACE")
	if egressName != "" {
		egressIdx := mustInterfaceIndex(egressName)
		ingressIdx := uint32(iface.Index)
		egressIdx32 := uint32(egressIdx)

		if err := redirectMap.Put(ingressIdx, egressIdx32); err != nil {
			log.Fatalf("redirect_ifindex put: %v", err)
		}
		// devmap key is the egress ifindex in this design
		if err := txPort.Put(egressIdx32, egressIdx32); err != nil {
			log.Fatalf("tx_port put: %v", err)
		}

		log.Printf("redirect enabled: ingress=%s(%d) -> egress=%s(%d)",
			ifName, iface.Index, egressName, egressIdx)
	}

	log.Printf("XDP attached to %s (ifindex=%d)", ifName, iface.Index)

	// Handle Ctrl-C.
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			printCounters(counters)
		case sig := <-sigCh:
			log.Printf("received signal %v, exiting", sig)
			return
		}
	}
}

func printCounters(counters *ebpf.Map) {
	actionNames := map[uint32]string{
		0: "PASS",
		1: "DROP",
		2: "REDIRECT",
	}

	for action := uint32(0); action < 3; action++ {
		var perCPU []Stats
		if err := counters.Lookup(action, &perCPU); err != nil {
			log.Printf("lookup counter %d: %v", action, err)
			continue
		}

		var total Stats
		for _, s := range perCPU {
			total.Packets += s.Packets
			total.Bytes += s.Bytes
		}

		log.Printf("action=%s packets=%d bytes=%d",
			actionNames[action], total.Packets, total.Bytes)
	}
}
```

