## `src/main.rs`
```rust
use anyhow::{Context, Result};
use clap::Parser;
use core_affinity;
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use serde::Deserialize;
use std::collections::HashMap;
use std::fs;
use std::sync::Arc;
use std::time::Duration;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    #[arg(long)]
    in_iface: String,

    #[arg(long)]
    policy: String,

    #[arg(long, default_value_t = false)]
    pin_core0: bool,
}

#[derive(Debug, Deserialize)]
struct Policy {
    rules: Vec<Rule>,
}

#[derive(Debug, Deserialize)]
struct Rule {
    name: String,
    ethertype: Option<u16>,
    ipv4_proto: Option<u8>,
    src_ip: Option<String>,
    dst_ip: Option<String>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    action: Action,
}

#[derive(Debug, Deserialize, Clone)]
#[serde(tag = "type")]
enum Action {
    Drop,
    Pass,
    Forward { out_iface: String },
}

#[derive(Debug, Clone)]
struct ParsedPacket<'a> {
    ethertype: u16,
    ipv4_proto: Option<u8>,
    src_ip: Option<std::net::Ipv4Addr>,
    dst_ip: Option<std::net::Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    raw: &'a [u8],
}

fn load_policy(path: &str) -> Result<Policy> {
    let data = fs::read_to_string(path)
        .with_context(|| format!("failed to read policy file: {}", path))?;
    let policy: Policy = serde_json::from_str(&data)
        .with_context(|| format!("failed to parse policy JSON: {}", path))?;
    Ok(policy)
}

fn parse_packet(frame: &[u8]) -> Option<ParsedPacket<'_>> {
    let eth = EthernetPacket::new(frame)?;
    let ethertype = eth.get_ethertype().0;

    let mut parsed = ParsedPacket {
        ethertype,
        ipv4_proto: None,
        src_ip: None,
        dst_ip: None,
        src_port: None,
        dst_port: None,
        raw: frame,
    };

    if eth.get_ethertype() == EtherTypes::Ipv4 {
        let ip = Ipv4Packet::new(eth.payload())?;
        parsed.ipv4_proto = Some(ip.get_next_level_protocol().0);
        parsed.src_ip = Some(ip.get_source());
        parsed.dst_ip = Some(ip.get_destination());

        match ip.get_next_level_protocol() {
            IpNextHeaderProtocols::Tcp => {
                let tcp = TcpPacket::new(ip.payload())?;
                parsed.src_port = Some(tcp.get_source());
                parsed.dst_port = Some(tcp.get_destination());
            }
            IpNextHeaderProtocols::Udp => {
                let udp = UdpPacket::new(ip.payload())?;
                parsed.src_port = Some(udp.get_source());
                parsed.dst_port = Some(udp.get_destination());
            }
            _ => {}
        }
    }

    Some(parsed)
}

fn rule_matches(rule: &Rule, pkt: &ParsedPacket<'_>) -> bool {
    if let Some(et) = rule.ethertype {
        if pkt.ethertype != et {
            return false;
        }
    }

    if let Some(proto) = rule.ipv4_proto {
        if pkt.ipv4_proto != Some(proto) {
            return false;
        }
    }

    if let Some(ref src_ip) = rule.src_ip {
        let parsed_ip = match src_ip.parse::<std::net::Ipv4Addr>() {
            Ok(ip) => ip,
            Err(_) => return false,
        };
        if pkt.src_ip != Some(parsed_ip) {
            return false;
        }
    }

    if let Some(ref dst_ip) = rule.dst_ip {
        let parsed_ip = match dst_ip.parse::<std::net::Ipv4Addr>() {
            Ok(ip) => ip,
            Err(_) => return false,
        };
        if pkt.dst_ip != Some(parsed_ip) {
            return false;
        }
    }

    if let Some(sp) = rule.src_port {
        if pkt.src_port != Some(sp) {
            return false;
        }
    }

    if let Some(dp) = rule.dst_port {
        if pkt.dst_port != Some(dp) {
            return false;
        }
    }

    true
}

fn decide_action(policy: &Policy, pkt: &ParsedPacket<'_>) -> Action {
    for rule in &policy.rules {
        if rule_matches(rule, pkt) {
            return rule.action.clone();
        }
    }
    Action::Drop
}

fn get_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface not found: {}", name))
}

fn build_tx_channels(policy: &Policy) -> Result<HashMap<String, Box<dyn DataLinkSender>>> {
    let mut tx_map = HashMap::new();

    for rule in &policy.rules {
        if let Action::Forward { out_iface } = &rule.action {
            if tx_map.contains_key(out_iface) {
                continue;
            }

            let iface = get_interface(out_iface)?;
            let cfg = Config {
                write_buffer_size: 1 << 20,
                read_buffer_size: 1 << 20,
                read_timeout: Some(Duration::from_millis(1)),
                write_timeout: Some(Duration::from_millis(1)),
                promiscuous: false,
                ..Default::default()
            };

            match datalink::channel(&iface, cfg)? {
                Channel::Ethernet(tx, _) => {
                    tx_map.insert(out_iface.clone(), tx);
                }
                _ => anyhow::bail!("unsupported channel type for {}", out_iface),
            }
        }
    }

    Ok(tx_map)
}

fn forward_packet(tx: &mut Box<dyn DataLinkSender>, frame: &[u8]) -> Result<()> {
    match tx.send_to(frame, None) {
        Some(Ok(())) => Ok(()),
        Some(Err(e)) => Err(e.into()),
        None => anyhow::bail!("send_to returned None"),
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.pin_core0 {
        if let Some(core_ids) = core_affinity::get_core_ids() {
            if let Some(core0) = core_ids.first() {
                core_affinity::set_for_current(*core0);
            }
        }
    }

    let policy = Arc::new(load_policy(&args.policy)?);
    let in_iface = get_interface(&args.in_iface)?;

    let cfg = Config {
        read_buffer_size: 1 << 20,
        write_buffer_size: 1 << 20,
        read_timeout: Some(Duration::from_millis(1)),
        write_timeout: Some(Duration::from_millis(1)),
        promiscuous: true,
        ..Default::default()
    };

    let mut tx_map = build_tx_channels(&policy)?;

    let mut rx: Box<dyn DataLinkReceiver> = match datalink::channel(&in_iface, cfg)? {
        Channel::Ethernet(_, rx) => rx,
        _ => anyhow::bail!("unsupported channel type for input interface"),
    };

    loop {
        match rx.next() {
            Ok(frame) => {
                if let Some(pkt) = parse_packet(frame) {
                    match decide_action(&policy, &pkt) {
                        Action::Drop => {}
                        Action::Pass => {}
                        Action::Forward { out_iface } => {
                            if let Some(tx) = tx_map.get_mut(&out_iface) {
                                let _ = forward_packet(tx, pkt.raw);
                            }
                        }
                    }
                }
            }
            Err(_) => {
                continue;
            }
        }
    }
}
```

