use crate::config::RuleConfig;
use std::collections::HashSet;
use std::net::{IpAddr, SocketAddr};

#[derive(Clone)]
pub struct PacketFilter {
    allow_source_ips: HashSet<IpAddr>,
    block_source_ips: HashSet<IpAddr>,
    allow_destination_ports: HashSet<u16>,
    max_packet_size: usize,
    allow_all_sources: bool,
    allow_all_ports: bool,
}

#[derive(Debug, Clone, Copy)]
pub enum FilterDecision {
    Allow,
    Drop,
}

impl PacketFilter {
    pub fn from_config(cfg: &RuleConfig) -> Self {
        let allow_source_ips: HashSet<IpAddr> = cfg
            .allow_source_ips
            .iter()
            .filter_map(|s| s.parse().ok())
            .collect();

        let block_source_ips: HashSet<IpAddr> = cfg
            .block_source_ips
            .iter()
            .filter_map(|s| s.parse().ok())
            .collect();

        let allow_destination_ports: HashSet<u16> =
            cfg.allow_destination_ports.iter().copied().collect();

        let allow_all_sources = allow_source_ips.is_empty();
        let allow_all_ports = allow_destination_ports.is_empty();

        Self {
            allow_source_ips,
            block_source_ips,
            allow_destination_ports,
            max_packet_size: cfg.max_packet_size,
            allow_all_sources,
            allow_all_ports,
        }
    }

    pub fn evaluate(
        &self,
        src: SocketAddr,
        local_dst: SocketAddr,
        packet_len: usize,
    ) -> FilterDecision {
        if packet_len > self.max_packet_size {
            return FilterDecision::Drop;
        }

        if self.block_source_ips.contains(&src.ip()) {
            return FilterDecision::Drop;
        }

        if !self.allow_all_sources && !self.allow_source_ips.contains(&src.ip()) {
            return FilterDecision::Drop;
        }

        if !self.allow_all_ports && !self.allow_destination_ports.contains(&local_dst.port()) {
            return FilterDecision::Drop;
        }

        FilterDecision::Allow
    }
}
