## src/forwarder.rs

```rust
use crate::config::{ForwardingConfig, ListenerConfig};
use crate::filter::{FilterDecision, PacketFilter};
use crate::metrics::Metrics;
use anyhow::{anyhow, Result};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use tokio::net::UdpSocket;
use tracing::{debug, error, info};

#[derive(Clone)]
pub struct TargetPool {
    targets: Arc<Vec<std::net::SocketAddr>>,
    next: Arc<AtomicUsize>,
}

impl TargetPool {
    pub fn new(cfg: &ForwardingConfig) -> Result<Self> {
        if cfg.targets.is_empty() {
            return Err(anyhow!("at least one forwarding target is required"));
        }

        Ok(Self {
            targets: Arc::new(cfg.targets.clone()),
            next: Arc::new(AtomicUsize::new(0)),
        })
    }

    pub fn pick(&self) -> std::net::SocketAddr {
        let idx = self.next.fetch_add(1, Ordering::Relaxed);
        self.targets[idx % self.targets.len()]
    }
}

pub async fn run_listener(
    listener: ListenerConfig,
    filter: PacketFilter,
    targets: TargetPool,
    metrics: Metrics,
) -> Result<()> {
    let socket = UdpSocket::bind(listener.bind).await?;
    info!("listening on {}", listener.bind);

    let send_socket = UdpSocket::bind("0.0.0.0:0").await?;

    let mut buf = vec![0u8; listener.recv_buffer_size];

    loop {
        let (len, src_addr) = match socket.recv_from(&mut buf).await {
            Ok(v) => v,
            Err(e) => {
                metrics.inc_errors();
                error!("recv error on {}: {}", listener.bind, e);
                continue;
            }
        };

        metrics.inc_received();

        let decision = filter.evaluate(src_addr, listener.bind, len);
        match decision {
            FilterDecision::Drop => {
                metrics.inc_dropped();
                debug!("dropped packet from {}", src_addr);
            }
            FilterDecision::Allow => {
                let target = targets.pick();
                match send_socket.send_to(&buf[..len], target).await {
                    Ok(_) => {
                        metrics.inc_forwarded();
                    }
                    Err(e) => {
                        metrics.inc_errors();
                        error!("forward error to {}: {}", target, e);
                    }
                }
            }
        }
    }
}
