```rust
mod config;
mod filter;
mod forwarder;
mod metrics;

use crate::config::Config;
use crate::filter::PacketFilter;
use crate::forwarder::{run_listener, TargetPool};
use crate::metrics::Metrics;
use anyhow::Result;
use std::env;
use tokio::signal;
use tracing::{error, info};

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,ultra_forwarder=debug".to_string()),
        )
        .init();

    let config_path = env::args()
        .nth(1)
        .unwrap_or_else(|| "config.yaml".to_string());

    let raw = std::fs::read_to_string(&config_path)?;
    let cfg: Config = serde_yaml::from_str(&raw)?;

    let filter = PacketFilter::from_config(&cfg.rules);
    let targets = TargetPool::new(&cfg.forwarding)?;
    let metrics = Metrics::default();

    let mut handles = Vec::new();

    for listener in cfg.listeners.clone() {
        let filter = filter.clone();
        let targets = targets.clone();
        let metrics = metrics.clone();

        handles.push(tokio::spawn(async move {
            if let Err(e) = run_listener(listener, filter, targets, metrics).await {
                error!("listener task failed: {}", e);
            }
        }));
    }

    let metrics_task = {
        let metrics = metrics.clone();
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                let snap = metrics.snapshot();
                info!(
                    received = snap.received,
                    forwarded = snap.forwarded,
                    dropped = snap.dropped,
                    errors = snap.errors,
                    "metrics"
                );
            }
        })
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    for h in handles {
        h.abort();
    }
    metrics_task.abort();

    Ok(())
}
