```rust
use cidr::Ipv4Inet;
use std::net::Ipv4Addr;

use crate::config::{Config, RuleConfig};
use crate::packet::PacketMeta;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Drop,
    Forward,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub ethertype: Option<u16>,
    pub src_cidr: Option<Ipv4Inet>,
    pub dst_cidr: Option<Ipv4Inet>,
    pub ip_proto: Option<u8>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

#[derive(Debug, Clone)]
pub struct RuleEngine {
    pub default_action: Action,
    pub rules: Vec<Rule>,
}

impl RuleEngine {
    pub fn from_config(cfg: &Config) -> anyhow::Result<Self> {
        let default_action = parse_action(&cfg.global.default_action)?;
        let mut rules = Vec::with_capacity(cfg.rule.len());
        for r in &cfg.rule {
            rules.push(parse_rule(r)?);
        }
        Ok(Self { default_action, rules })
    }

    pub fn decide(&self, meta: &PacketMeta) -> Action {
        for r in &self.rules {
            if let Some(v) = r.ethertype {
                if meta.ethertype != Some(v) {
                    continue;
                }
            }
            if let Some(v) = r.ip_proto {
                if meta.ip_proto != Some(v) {
                    continue;
                }
            }
            if let Some(v) = r.src_port {
                if meta.src_port != Some(v) {
                    continue;
                }
            }
            if let Some(v) = r.dst_port {
                if meta.dst_port != Some(v) {
                    continue;
                }
            }
            if let Some(c) = &r.src_cidr {
                match meta.src_ip {
                    Some(ip) if c.contains(&ip) => {}
                    _ => continue,
                }
            }
            if let Some(c) = &r.dst_cidr {
                match meta.dst_ip {
                    Some(ip) if c.contains(&ip) => {}
                    _ => continue,
                }
            }
            return r.action;
        }
        self.default_action
    }
}

fn parse_action(s: &str) -> anyhow::Result<Action> {
    match s.to_ascii_lowercase().as_str() {
        "drop" => Ok(Action::Drop),
        "forward" => Ok(Action::Forward),
        _ => anyhow::bail!("invalid action: {s}"),
    }
}

fn parse_rule(r: &RuleConfig) -> anyhow::Result<Rule> {
    Ok(Rule {
        action: parse_action(&r.action)?,
        ethertype: r.ethertype,
        src_cidr: match &r.src_cidr {
            Some(s) => Some(s.parse()?),
            None => None,
        },
        dst_cidr: match &r.dst_cidr {
            Some(s) => Some(s.parse()?),
            None => None,
        },
        ip_proto: r.ip_proto,
        src_port: r.src_port,
        dst_port: r.dst_port,
    })
}
