# src/packet.rs

```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, Default)]
pub struct PacketMeta {
    pub ethertype: Option<u16>,
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub ip_proto: Option<u8>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub l2_len: usize,
    pub l3_len: usize,
    pub l4_off: usize,
}

pub fn parse_packet(buf: &[u8]) -> PacketMeta {
    let mut m = PacketMeta::default();
    if buf.len() < 14 {
        return m;
    }

    let mut ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    let mut off = 14;

    if ethertype == 0x8100 && buf.len() >= 18 {
        ethertype = u16::from_be_bytes([buf[16], buf[17]]);
        off = 18;
    }

    m.ethertype = Some(ethertype);
    m.l2_len = off;

    if ethertype != 0x0800 {
        return m;
    }

    if buf.len() < off + 20 {
        return m;
    }

    let vihl = buf[off];
    let version = vihl >> 4;
    let ihl = ((vihl & 0x0f) as usize) * 4;
    if version != 4 || ihl < 20 || buf.len() < off + ihl {
        return m;
    }

    let proto = buf[off + 9];
    let src = Ipv4Addr::new(buf[off + 12], buf[off + 13], buf[off + 14], buf[off + 15]);
    let dst = Ipv4Addr::new(buf[off + 16], buf[off + 17], buf[off + 18], buf[off + 19]);

    m.src_ip = Some(src);
    m.dst_ip = Some(dst);
    m.ip_proto = Some(proto);
    m.l3_len = ihl;
    m.l4_off = off + ihl;

    match proto {
        6 | 17 => {
            if buf.len() >= m.l4_off + 4 {
                m.src_port = Some(u16::from_be_bytes([buf[m.l4_off], buf[m.l4_off + 1]]));
                m.dst_port = Some(u16::from_be_bytes([buf[m.l4_off + 2], buf[m.l4_off + 3]]));
            }
        }
        _ => {}
    }

    m
}

pub fn rewrite_macs(buf: &mut [u8], src_mac: [u8; 6], dst_mac: [u8; 6]) {
    if buf.len() >= 12 {
        buf[0..6].copy_from_slice(&dst_mac);
        buf[6..12].copy_from_slice(&src_mac);
    }
}

pub fn parse_mac(s: &str) -> anyhow::Result<[u8; 6]> {
    let parts: Vec<_> = s.split(':').collect();
    if parts.len() != 6 {
        anyhow::bail!("invalid MAC: {s}");
    }
    let mut out = [0u8; 6];
    for (i, p) in parts.iter().enumerate() {
        out[i] = u8::from_str_radix(p, 16)?;
    }
    Ok(out)
}
