# src/worker.rs

```rust
use std::sync::Arc;
use std::sync::atomic::Ordering;

use anyhow::Result;

use crate::config::LinkConfig;
use crate::packet::{parse_mac, parse_packet, rewrite_macs};
use crate::rules::{Action, RuleEngine};
use crate::stats::SharedStats;
use crate::xdp::XdpSocket;

pub fn run_worker(link: LinkConfig, rules: Arc<RuleEngine>, stats: SharedStats) -> Result<()> {
    if let Some(cores) = core_affinity::get_core_ids() {
        if let Some(core) = cores.into_iter().find(|c| c.id == link.cpu) {
            core_affinity::set_for_current(core);
        }
    }

    let src_mac = parse_mac(&link.src_mac)?;
    let dst_mac = parse_mac(&link.dst_mac)?;

    let mut rx = XdpSocket::open(&link.rx_if, link.queue)?;
    let mut tx = XdpSocket::open(&link.tx_if, link.queue)?;

    loop {
        let mut batch = rx.recv_batch(64)?;
        if batch.is_empty() {
            std::hint::spin_loop();
            continue;
        }

        for frame in batch.iter_mut() {
            let pkt = &mut frame.data[..frame.len];
            stats.rx_pkts.fetch_add(1, Ordering::Relaxed);
            stats.rx_bytes.fetch_add(frame.len as u64, Ordering::Relaxed);

            let meta = parse_packet(pkt);
            let action = rules.decide(&meta);

            match action {
                Action::Drop => {
                    stats.drop_pkts.fetch_add(1, Ordering::Relaxed);
                }
                Action::Forward => {
                    rewrite_macs(pkt, src_mac, dst_mac);
                    tx.tx_one(pkt)?;
                    stats.tx_pkts.fetch_add(1, Ordering::Relaxed);
                    stats.tx_bytes.fetch_add(frame.len as u64, Ordering::Relaxed);
                }
            }
        }

        tx.complete()?;
        rx.refill()?;
    }
}
