#[derive(Parser, Debug)]
struct Cli {
    #[arg(short, long, default_value = "config.toml")]
    config: String,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let text = fs::read_to_string(&cli.config)?;
    let cfg: Config = toml::from_str(&text)?;

    let rules = Arc::new(RuleEngine::from_config(&cfg)?);
    let stats: SharedStats = Arc::new(Stats::default());

    let metrics_stats = stats.clone();
    let metrics_addr = cfg.global.metrics_addr.clone();

    let metrics_task = tokio::spawn(async move {
        let app = Router::new().route("/metrics", get(move || {
            let s = metrics_stats.clone();
            async move { s.render_prometheus() }
        }));

        let listener = tokio::net::TcpListener::bind(&metrics_addr).await.unwrap();
        axum::serve(listener, app).await.unwrap();
    });

    let mut joins = Vec::new();
    for link in cfg.link.clone() {
        let rules = rules.clone();
        let stats = stats.clone();
        joins.push(thread::spawn(move || {
            if let Err(e) = worker::run_worker(link, rules, stats) {
                eprintln!("worker failed: {e:#}");
            }
        }));
    }

    metrics_task.await?;
    for j in joins {
        let _ = j.join();
    }

    Ok(())
