use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::Instant;

mod packet;
mod rules;
mod stats;

use packet::{EtherType, IpProtocol, PacketView};
use rules::{Action, RuleEngine};
use stats::Stats;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    rules: Vec<rules::Rule>,
}

fn process_frame(frame: &[u8], engine: &RuleEngine, stats: &Stats) -> Option<Vec<u8>> {
    stats.rx_packets.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    stats.rx_bytes.fetch_add(frame.len() as u64, std::sync::atomic::Ordering::Relaxed);

    let pkt = match PacketView::parse(frame) {
        Ok(p) => p,
        Err(_) => {
            stats.parse_errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };

    let action = engine.evaluate(&pkt);

    match action {
        Action::Drop => {
            stats.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            None
        }
        Action::Pass => {
            stats.passed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            Some(frame.to_vec())
        }
        Action::Forward { out_port } => {
            let _ = out_port;
            stats.forwarded.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            Some(frame.to_vec())
        }
    }
}

fn main() {
    let config_json = r#"
    {
        "rules": [
            {
                "src_ip": "10.0.0.10",
                "dst_ip": "10.0.0.20",
                "src_port": 12345,
                "dst_port": 8080,
                "protocol": "TCP",
                "action": { "Forward": { "out_port": 1 } }
            },
            {
                "src_ip": null,
                "dst_ip": null,
                "src_port": null,
                "dst_port": 22,
                "protocol": "TCP",
                "action": "Drop"
            }
        ]
    }
    "#;

    let config: Config = serde_json::from_str(config_json).expect("invalid config");
    let engine = Arc::new(RuleEngine::new(config.rules));
    let stats = Arc::new(Stats::default());

    let sample_packet = build_sample_ipv4_tcp_packet(
        Ipv4Addr::new(10, 0, 0, 10),
        Ipv4Addr::new(10, 0, 0, 20),
        12345,
        8080,
    );

    let start = Instant::now();
    let result = process_frame(&sample_packet, &engine, &stats);
    let elapsed = start.elapsed();

    println!("decision: {}", if result.is_some() { "forward/pass" } else { "drop" });
    println!("latency: {:?}", elapsed);
    println!("stats: {:?}", stats.snapshot());
}

fn build_sample_ipv4_tcp_packet(
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
) -> Vec<u8> {
    let mut buf = vec![0u8; 14 + 20 + 20];

    buf[12] = 0x08;
    buf[13] = 0x00;

    let ip_start = 14;
    buf[ip_start] = 0x45;
    buf[ip_start + 1] = 0;
    let total_len = 20 + 20;
    buf[ip_start + 2] = ((total_len >> 8) & 0xff) as u8;
    buf[ip_start + 3] = (total_len & 0xff) as u8;
    buf[ip_start + 8] = 64;
    buf[ip_start + 9] = 6;

    buf[ip_start + 12..ip_start + 16].copy_from_slice(&src_ip.octets());
    buf[ip_start + 16..ip_start + 20].copy_from_slice(&dst_ip.octets());

    let tcp_start = 14 + 20;
    buf[tcp_start] = (src_port >> 8) as u8;
    buf[tcp_start + 1] = (src_port & 0xff) as u8;
    buf[tcp_start + 2] = (dst_port >> 8) as u8;
    buf[tcp_start + 3] = (dst_port & 0xff) as u8;
    buf[tcp_start + 12] = 0x50;

    buf
}
