use std::net::Ipv4Addr;
use thiserror::Error;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EtherType {
    Ipv4,
    Other(u16),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpProtocol {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone)]
pub struct PacketView {
    pub ethertype: EtherType,
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub protocol: Option<IpProtocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

#[derive(Debug, Error)]
pub enum ParseError {
    #[error("frame too short")]
    TooShort,
    #[error("unsupported packet")]
    Unsupported,
}

impl PacketView {
    pub fn parse(frame: &[u8]) -> Result<Self, ParseError> {
        if frame.len() < 14 {
            return Err(ParseError::TooShort);
        }

        let ethertype_raw = u16::from_be_bytes([frame[12], frame[13]]);
        let ethertype = match ethertype_raw {
            0x0800 => EtherType::Ipv4,
            other => EtherType::Other(other),
        };

        match ethertype {
            EtherType::Ipv4 => Self::parse_ipv4(frame),
            _ => Err(ParseError::Unsupported),
        }
    }

    fn parse_ipv4(frame: &[u8]) -> Result<Self, ParseError> {
        if frame.len() < 14 + 20 {
            return Err(ParseError::TooShort);
        }

        let ip_start = 14;
        let ihl = (frame[ip_start] & 0x0f) as usize * 4;
        if ihl < 20 || frame.len() < 14 + ihl {
            return Err(ParseError::TooShort);
        }

        let proto = frame[ip_start + 9];
        let src_ip = Ipv4Addr::new(
            frame[ip_start + 12],
            frame[ip_start + 13],
            frame[ip_start + 14],
            frame[ip_start + 15],
        );
        let dst_ip = Ipv4Addr::new(
            frame[ip_start + 16],
            frame[ip_start + 17],
            frame[ip_start + 18],
            frame[ip_start + 19],
        );

        let l4_start = 14 + ihl;
        let protocol = match proto {
            6 => Some(IpProtocol::Tcp),
            17 => Some(IpProtocol::Udp),
            other => Some(IpProtocol::Other(other)),
        };

        let (src_port, dst_port) = if matches!(protocol, Some(IpProtocol::Tcp) | Some(IpProtocol::Udp)) {
            if frame.len() < l4_start + 4 {
                return Err(ParseError::TooShort);
            }
            let sp = u16::from_be_bytes([frame[l4_start], frame[l4_start + 1]]);
            let dp = u16::from_be_bytes([frame[l4_start + 2], frame[l4_start + 3]]);
            (Some(sp), Some(dp))
        } else {
            (None, None)
        };

        Ok(PacketView {
            ethertype: EtherType::Ipv4,
            src_ip: Some(src_ip),
            dst_ip: Some(dst_ip),
            protocol,
            src_port,
            dst_port,
        })
    }
}
