use crate::packet::{IpProtocol, PacketView};
use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ProtocolMatch {
    TCP,
    UDP,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Action {
    Drop,
    Pass,
    Forward { out_port: u16 },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<ProtocolMatch>,
    pub action: Action,
}

#[derive(Debug)]
pub struct RuleEngine {
    rules: Vec<Rule>,
}

impl RuleEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, pkt: &PacketView) -> Action {
        for rule in &self.rules {
            if rule_matches(rule, pkt) {
                return rule.action.clone();
            }
        }
        Action::Drop
    }
}

fn rule_matches(rule: &Rule, pkt: &PacketView) -> bool {
    if let Some(ip) = rule.src_ip {
        if pkt.src_ip != Some(ip) {
            return false;
        }
    }

    if let Some(ip) = rule.dst_ip {
        if pkt.dst_ip != Some(ip) {
            return false;
        }
    }

    if let Some(port) = rule.src_port {
        if pkt.src_port != Some(port) {
            return false;
        }
    }

    if let Some(port) = rule.dst_port {
        if pkt.dst_port != Some(port) {
            return false;
        }
    }

    if let Some(proto) = &rule.protocol {
        let matches = match proto {
            ProtocolMatch::TCP => pkt.protocol == Some(IpProtocol::Tcp),
            ProtocolMatch::UDP => pkt.protocol == Some(IpProtocol::Udp),
        };
        if !matches {
            return false;
        }
    }

    true
}
