use anyhow::{Context, Result};
use clap::Parser;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use serde::Deserialize;
use socket2::{Domain, Protocol, Socket, Type};
use std::fs;
use std::io;
use std::mem::MaybeUninit;
use std::os::fd::{AsRawFd, FromRawFd};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
struct Args {
    #[arg(short, long, default_value = "config.toml")]
    config: String,
}

#[derive(Debug, Deserialize, Clone)]
struct Config {
    ingress_interface: String,
    egress_interface: String,
    max_packet_size: usize,
    workers: usize,
    filter: FilterConfig,
    metrics: MetricsConfig,
}

#[derive(Debug, Deserialize, Clone)]
struct MetricsConfig {
    log_interval_secs: u64,
}

#[derive(Debug, Deserialize, Clone)]
struct FilterConfig {
    allow_ipv4: bool,
    allow_ipv6: bool,
    drop_non_ip: bool,
    udp: UdpFilterConfig,
    tcp: TcpFilterConfig,
}

#[derive(Debug, Deserialize, Clone)]
struct UdpFilterConfig {
    enabled: bool,
    allowed_dst_ports: Vec<u16>,
}

#[derive(Debug, Deserialize, Clone)]
struct TcpFilterConfig {
    enabled: bool,
    allowed_dst_ports: Vec<u16>,
}

#[derive(Default)]
struct Metrics {
    rx_packets: AtomicU64,
    rx_bytes: AtomicU64,
    dropped_packets: AtomicU64,
    forwarded_packets: AtomicU64,
    parse_errors: AtomicU64,
}

fn load_config(path: &str) -> Result<Config> {
    let data = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {path}"))?;
    let cfg: Config = toml::from_str(&data)
        .with_context(|| format!("failed to parse config file: {path}"))?;
    Ok(cfg)
}

fn if_index(name: &str) -> Result<i32> {
    let cstr = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(cstr.as_ptr()) };
    if idx == 0 {
        anyhow::bail!("interface not found: {name}");
    }
    Ok(idx as i32)
}

fn bind_raw_socket(interface: &str) -> Result<std::net::UdpSocket> {
    let proto = (libc::ETH_P_ALL as u16).to_be() as i32;
    let sock = Socket::new(
        Domain::PACKET,
        Type::RAW,
        Some(Protocol::from(proto)),
    )?;

    let ifidx = if_index(interface)?;

    let sll = libc::sockaddr_ll {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: (libc::ETH_P_ALL as u16).to_be(),
        sll_ifindex: ifidx,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            sock.as_raw_fd(),
            &sll as *const _ as *const libc::sockaddr,
            std::mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
        )
    };
    if ret != 0 {
        return Err(io::Error::last_os_error()).context("bind AF_PACKET failed");
    }

    let fd = sock.as_raw_fd();
    let dup_fd = unsafe { libc::dup(fd) };
    if dup_fd < 0 {
        return Err(io::Error::last_os_error()).context("dup failed");
    }

    let udp = unsafe { std::net::UdpSocket::from_raw_fd(dup_fd) };
    Ok(udp)
}

fn make_tx_socket(interface: &str) -> Result<Socket> {
    let proto = (libc::ETH_P_ALL as u16).to_be() as i32;
    let sock = Socket::new(
        Domain::PACKET,
        Type::RAW,
        Some(Protocol::from(proto)),
    )?;

    let ifidx = if_index(interface)?;
    let sll = libc::sockaddr_ll {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: (libc::ETH_P_ALL as u16).to_be(),
        sll_ifindex: ifidx,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            sock.as_raw_fd(),
            &sll as *const _ as *const libc::sockaddr,
            std::mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
        )
    };
    if ret != 0 {
        return Err(io::Error::last_os_error()).context("bind tx AF_PACKET failed");
    }

    Ok(sock)
}

fn packet_allowed(cfg: &FilterConfig, packet: &[u8]) -> Result<bool> {
    let sliced = match SlicedPacket::from_ethernet(packet) {
        Ok(v) => v,
        Err(_) => return Ok(!cfg.drop_non_ip),
    };

    match sliced.net {
        Some(InternetSlice::Ipv4(_hdr, _ext)) => {
            if !cfg.allow_ipv4 {
                return Ok(false);
            }
        }
        Some(InternetSlice::Ipv6(_hdr, _ext)) => {
            if !cfg.allow_ipv6 {
                return Ok(false);
            }
        }
        None => {
            return Ok(!cfg.drop_non_ip);
        }
        _ => {}
    }

    match sliced.transport {
        Some(TransportSlice::Udp(udp)) => {
            if !cfg.udp.enabled {
                return Ok(false);
            }
            Ok(cfg.udp.allowed_dst_ports.contains(&udp.destination_port()))
        }
        Some(TransportSlice::Tcp(tcp)) => {
            if !cfg.tcp.enabled {
                return Ok(false);
            }
            Ok(cfg.tcp.allowed_dst_ports.contains(&tcp.destination_port()))
        }
        Some(_) => Ok(false),
        None => Ok(false),
    }
}

fn forward_packet(tx: &Socket, packet: &[u8]) -> Result<()> {
    tx.send(packet)?;
    Ok(())
}

fn worker_loop(
    cfg: Config,
    running: Arc<AtomicBool>,
    metrics: Arc<Metrics>,
) -> Result<()> {
    let rx = bind_raw_socket(&cfg.ingress_interface)?;
    let tx = make_tx_socket(&cfg.egress_interface)?;

    let mut buf = vec![0u8; cfg.max_packet_size];

    while running.load(Ordering::Relaxed) {
        match rx.recv(&mut buf) {
            Ok(n) => {
                let pkt = &buf[..n];
                metrics.rx_packets.fetch_add(1, Ordering::Relaxed);
                metrics.rx_bytes.fetch_add(n as u64, Ordering::Relaxed);

                match packet_allowed(&cfg.filter, pkt) {
                    Ok(true) => {
                        if forward_packet(&tx, pkt).is_ok() {
                            metrics.forwarded_packets.fetch_add(1, Ordering::Relaxed);
                        } else {
                            metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                    Ok(false) => {
                        metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(_) => {
                        metrics.parse_errors.fetch_add(1, Ordering::Relaxed);
                        metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(_) => {
                metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    Ok(())
}

fn metrics_loop(
    running: Arc<AtomicBool>,
    metrics: Arc<Metrics>,
    interval: Duration,
) {
    let mut last = Instant::now();
    let mut prev_rx = 0;
    let mut prev_fwd = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(interval);

        let rx = metrics.rx_packets.load(Ordering::Relaxed);
        let bytes = metrics.rx_bytes.load(Ordering::Relaxed);
        let dropped = metrics.dropped_packets.load(Ordering::Relaxed);
        let fwd = metrics.forwarded_packets.load(Ordering::Relaxed);
        let parse = metrics.parse_errors.load(Ordering::Relaxed);

        let elapsed = last.elapsed().as_secs_f64().max(0.001);
        let rx_pps = (rx - prev_rx) as f64 / elapsed;
        let fwd_pps = (fwd - prev_fwd) as f64 / elapsed;

        println!(
            "rx={} fwd={} drop={} parse_err={} bytes={} rx_pps={:.0} fwd_pps={:.0}",
            rx, fwd, dropped, parse, bytes, rx_pps, fwd_pps
        );

        prev_rx = rx;
        prev_fwd = fwd;
        last = Instant::now();
    }
}

fn main() -> Result<()> {
    let args = Args::parse();
    let cfg = load_config(&args.config)?;

    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::default());

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let metrics_thread = {
        let running = running.clone();
        let metrics = metrics.clone();
        let interval = Duration::from_secs(cfg.metrics.log_interval_secs);
        thread::spawn(move || metrics_loop(running, metrics, interval))
    };

    let mut workers = Vec::new();
    for _ in 0..cfg.workers.max(1) {
        let running = running.clone();
        let metrics = metrics.clone();
        let worker_cfg = cfg.clone();
        workers.push(thread::spawn(move || worker_loop(worker_cfg, running, metrics)));
    }

    for w in workers {
        match w.join() {
            Ok(res) => {
                if let Err(e) = res {
                    eprintln!("worker error: {e:#}");
                }
            }
            Err(_) => eprintln!("worker panicked"),
        }
    }

    let _ = metrics_thread.join();
    Ok(())
}
