# Initial implementation in C with DPDK

## File: `ultra_forwarder.c`

```c
#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <arpa/inet.h>

#include <rte_common.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_tcp.h>
#include <rte_udp.h>
#include <rte_ether.h>
#include <rte_lcore.h>
#include <rte_cycles.h>
#include <rte_branch_prediction.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8192
#define MBUF_CACHE_SIZE 256
#define BURST_SIZE 32
#define MAX_PORTS 4

static volatile bool force_quit = false;

struct app_stats {
    uint64_t rx_pkts;
    uint64_t tx_pkts;
    uint64_t dropped_pkts;
    uint64_t ipv4_pkts;
    uint64_t non_ipv4_pkts;
    uint64_t tcp_pkts;
    uint64_t udp_pkts;
};

static struct app_stats stats[RTE_MAX_LCORE];

enum action_type {
    ACTION_DROP = 0,
    ACTION_PASS = 1,
    ACTION_FWD  = 2,
};

struct rule {
    uint32_t src_ip;
    uint32_t src_mask;
    uint32_t dst_ip;
    uint32_t dst_mask;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;      // 0 = any, IPPROTO_TCP, IPPROTO_UDP
    enum action_type action;
    uint16_t out_port;   // valid if ACTION_FWD
};

#define MAX_RULES 64
static struct rule rules[MAX_RULES];
static uint16_t nb_rules = 0;

static struct rte_mempool *mbuf_pool;
static uint16_t enabled_ports[MAX_PORTS];
static uint16_t nb_enabled_ports = 0;

static inline uint32_t
mask_ip(uint32_t ip, uint32_t mask) {
    return ip & mask;
}

static inline bool
rule_match_ipv4(const struct rule *r,
                uint32_t src_ip,
                uint32_t dst_ip,
                uint16_t src_port,
                uint16_t dst_port,
                uint8_t proto) {
    if (r->proto != 0 && r->proto != proto)
        return false;

    if (r->src_mask && mask_ip(src_ip, r->src_mask) != mask_ip(r->src_ip, r->src_mask))
        return false;

    if (r->dst_mask && mask_ip(dst_ip, r->dst_mask) != mask_ip(r->dst_ip, r->dst_mask))
        return false;

    if (r->src_port && r->src_port != src_port)
        return false;

    if (r->dst_port && r->dst_port != dst_port)
        return false;

    return true;
}

static inline enum action_type
apply_rules(uint32_t src_ip,
            uint32_t dst_ip,
            uint16_t src_port,
            uint16_t dst_port,
            uint8_t proto,
            uint16_t *out_port) {
    for (uint16_t i = 0; i < nb_rules; i++) {
        if (rule_match_ipv4(&rules[i], src_ip, dst_ip, src_port, dst_port, proto)) {
            *out_port = rules[i].out_port;
            return rules[i].action;
        }
    }

    return ACTION_PASS;
}

static void
signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM)
        force_quit = true;
}

static int
port_init(uint16_t port, struct rte_mempool *pool) {
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1, tx_rings = 1;
    int retval;
    uint16_t q;

    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    retval = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (retval < 0)
        return retval;

    for (q = 0; q < rx_rings; q++) {
        retval = rte_eth_rx_queue_setup(port, q, RX_RING_SIZE,
                                        rte_eth_dev_socket_id(port), NULL, pool);
        if (retval < 0)
            return retval;
    }

    for (q = 0; q < tx_rings; q++) {
        retval = rte_eth_tx_queue_setup(port, q, TX_RING_SIZE,
                                        rte_eth_dev_socket_id(port), NULL);
        if (retval < 0)
            return retval;
    }

    retval = rte_eth_dev_start(port);
    if (retval < 0)
        return retval;

    rte_eth_promiscuous_enable(port);

    struct rte_ether_addr addr;
    rte_eth_macaddr_get(port, &addr);
    printf("Port %u MAC: %02X:%02X:%02X:%02X:%02X:%02X\n",
           port,
           addr.addr_bytes[0], addr.addr_bytes[1], addr.addr_bytes[2],
           addr.addr_bytes[3], addr.addr_bytes[4], addr.addr_bytes[5]);

    return 0;
}

static void
add_sample_rules(void) {
    // Example: forward UDP dst port 9000 to port 1
    rules[nb_rules++] = (struct rule){
        .src_ip = 0,
        .src_mask = 0,
        .dst_ip = 0,
        .dst_mask = 0,
        .src_port = 0,
        .dst_port = 9000,
        .proto = IPPROTO_UDP,
        .action = ACTION_FWD,
        .out_port = 1
    };

    // Example: drop TCP dst port 23
    rules[nb_rules++] = (struct rule){
        .src_ip = 0,
        .src_mask = 0,
        .dst_ip = 0,
        .dst_mask = 0,
        .src_port = 0,
        .dst_port = 23,
        .proto = IPPROTO_TCP,
        .action = ACTION_DROP,
        .out_port = 0
    };
}

static inline void
free_unsent(struct rte_mbuf **bufs, uint16_t sent, uint16_t total) {
    for (uint16_t i = sent; i < total; i++)
        rte_pktmbuf_free(bufs[i]);
}

static int
lcore_main(void *arg) {
    (void)arg;

    const uint16_t in_port = enabled_ports[0];
    const unsigned lcore_id = rte_lcore_id();
    struct rte_mbuf *bufs[BURST_SIZE];
    struct rte_mbuf *tx_bufs[MAX_PORTS][BURST_SIZE];
    uint16_t tx_counts[MAX_PORTS];
    memset(tx_counts, 0, sizeof(tx_counts));

    printf("Entering main loop on lcore %u, reading from port %u\n", lcore_id, in_port);

    while (!force_quit) {
        const uint16_t nb_rx = rte_eth_rx_burst(in_port, 0, bufs, BURST_SIZE);
        if (unlikely(nb_rx == 0))
            continue;

        stats[lcore_id].rx_pkts += nb_rx;

        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = bufs[i];
            struct rte_ether_hdr *eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);

            if (unlikely(rte_be_to_cpu_16(eth->ether_type) != RTE_ETHER_TYPE_IPV4)) {
                stats[lcore_id].non_ipv4_pkts++;
                rte_pktmbuf_free(m);
                stats[lcore_id].dropped_pkts++;
                continue;
            }

            stats[lcore_id].ipv4_pkts++;

            struct rte_ipv4_hdr *ip = (struct rte_ipv4_hdr *)(eth + 1);
            uint8_t proto = ip->next_proto_id;
            uint32_t src_ip = rte_be_to_cpu_32(ip->src_addr);
            uint32_t dst_ip = rte_be_to_cpu_32(ip->dst_addr);
            uint16_t src_port = 0, dst_port = 0;

            if (proto == IPPROTO_TCP) {
                stats[lcore_id].tcp_pkts++;
                struct rte_tcp_hdr *tcp = (struct rte_tcp_hdr *)((uint8_t *)ip + sizeof(struct rte_ipv4_hdr));
                src_port = rte_be_to_cpu_16(tcp->src_port);
                dst_port = rte_be_to_cpu_16(tcp->dst_port);
            } else if (proto == IPPROTO_UDP) {
                stats[lcore_id].udp_pkts++;
                struct rte_udp_hdr *udp = (struct rte_udp_hdr *)((uint8_t *)ip + sizeof(struct rte_ipv4_hdr));
                src_port = rte_be_to_cpu_16(udp->src_port);
                dst_port = rte_be_to_cpu_16(udp->dst_port);
            }

            uint16_t out_port = in_port;
            enum action_type action = apply_rules(src_ip, dst_ip, src_port, dst_port, proto, &out_port);

            if (action == ACTION_DROP) {
                rte_pktmbuf_free(m);
                stats[lcore_id].dropped_pkts++;
                continue;
            }

            if (action == ACTION_PASS) {
                out_port = in_port;
            }

            if (unlikely(out_port >= RTE_MAX_ETHPORTS || !rte_eth_dev_is_valid_port(out_port))) {
                rte_pktmbuf_free(m);
                stats[lcore_id].dropped_pkts++;
                continue;
            }

            uint16_t idx = tx_counts[out_port]++;
            tx_bufs[out_port][idx] = m;

            if (tx_counts[out_port] == BURST_SIZE) {
                uint16_t sent = rte_eth_tx_burst(out_port, 0, tx_bufs[out_port], tx_counts[out_port]);
                stats[lcore_id].tx_pkts += sent;
                if (unlikely(sent < tx_counts[out_port])) {
                    free_unsent(tx_bufs[out_port], sent, tx_counts[out_port]);
                    stats[lcore_id].dropped_pkts += (tx_counts[out_port] - sent);
                }
                tx_counts[out_port] = 0;
            }
        }

        for (uint16_t p = 0; p < nb_enabled_ports; p++) {
            uint16_t port = enabled_ports[p];
            if (tx_counts[port] > 0) {
                uint16_t sent = rte_eth_tx_burst(port, 0, tx_bufs[port], tx_counts[port]);
                stats[lcore_id].tx_pkts += sent;
                if (unlikely(sent < tx_counts[port])) {
                    free_unsent(tx_bufs[port], sent, tx_counts[port]);
                    stats[lcore_id].dropped_pkts += (tx_counts[port] - sent);
                }
                tx_counts[port] = 0;
            }
        }
    }

    return 0;
}

static void
print_stats(void) {
    uint64_t rx = 0, tx = 0, drop = 0, ipv4 = 0, non_ipv4 = 0, tcp = 0, udp = 0;

    RTE_LCORE_FOREACH_WORKER(unsigned lcore_id) {
        rx += stats[lcore_id].rx_pkts;
        tx += stats[lcore_id].tx_pkts;
        drop += stats[lcore_id].dropped_pkts;
        ipv4 += stats[lcore_id].ipv4_pkts;
        non_ipv4 += stats[lcore_id].non_ipv4_pkts;
        tcp += stats[lcore_id].tcp_pkts;
        udp += stats[lcore_id].udp_pkts;
    }

    unsigned main_lcore = rte_get_main_lcore();
    rx += stats[main_lcore].rx_pkts;
    tx += stats[main_lcore].tx_pkts;
    drop += stats[main_lcore].dropped_pkts;
    ipv4 += stats[main_lcore].ipv4_pkts;
    non_ipv4 += stats[main_lcore].non_ipv4_pkts;
    tcp += stats[main_lcore].tcp_pkts;
    udp += stats[main_lcore].udp_pkts;

    printf("\n=== stats ===\n");
    printf("rx=%" PRIu64 " tx=%" PRIu64 " drop=%" PRIu64 "\n", rx, tx, drop);
    printf("ipv4=%" PRIu64 " non_ipv4=%" PRIu64 " tcp=%" PRIu64 " udp=%" PRIu64 "\n",
           ipv4, non_ipv4, tcp, udp);
}

int
main(int argc, char *argv[]) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 1)
        rte_exit(EXIT_FAILURE, "No available Ethernet ports\n");

    nb_enabled_ports = 0;
    RTE_ETH_FOREACH_DEV(ret) {
        if (nb_enabled_ports < MAX_PORTS)
            enabled_ports[nb_enabled_ports++] = (uint16_t)ret;
    }

    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL",
                                        NUM_MBUFS * nb_enabled_ports,
                                        MBUF_CACHE_SIZE,
                                        0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());

    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    for (uint16_t i = 0; i < nb_enabled_ports; i++) {
        if (port_init(enabled_ports[i], mbuf_pool) != 0)
            rte_exit(EXIT_FAILURE, "Cannot init port %" PRIu16 "\n", enabled_ports[i]);
    }

    add_sample_rules();

    printf("Initialized with %u ports and %u rules\n", nb_enabled_ports, nb_rules);

    rte_eal_mp_remote_launch(lcore_main, NULL, CALL_MAIN);
    RTE_LCORE_FOREACH_WORKER(ret) {
        if (rte_eal_wait_lcore(ret) < 0)
            return -1;
    }

    print_stats();

    for (uint16_t i = 0; i < nb_enabled_ports; i++) {
        rte_eth_dev_stop(enabled_ports[i]);
        rte_eth_dev_close(enabled_ports[i]);
    }

    return 0;
}
