# Option A: Initial XDP/eBPF implementation

This is the safest and most realistic starting point for low-latency filtering.

## 1) XDP program in C

This example:
- parses Ethernet + IPv4,
- drops packets from blocked source IPs,
- passes everything else.

```c
// xdp_filter.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 source address
    __type(value, __u8);  // 1 = blocked
} blocked_ips SEC(".maps");

SEC("xdp")
int xdp_packet_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (eth->h_proto != __builtin_bswap16(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_ABORTED;

    __u32 src = ip->saddr;
    __u8 *blocked = bpf_map_lookup_elem(&blocked_ips, &src);
    if (blocked && *blocked == 1)
        return XDP_DROP;

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

