## 3) Rule updater

This inserts blocked IPs into the BPF map.

```c
// block_ip.c
#include <stdio.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <bpf/bpf.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <map_path> <ipv4>\n", argv[0]);
        return 1;
    }

    const char *map_path = argv[1];
    const char *ip_str = argv[2];

    int map_fd = bpf_obj_get(map_path);
    if (map_fd < 0) {
        perror("bpf_obj_get");
        return 1;
    }

    __u32 ip;
    if (inet_pton(AF_INET, ip_str, &ip) != 1) {
        fprintf(stderr, "Invalid IP\n");
        return 1;
    }

    __u8 value = 1;
    if (bpf_map_update_elem(map_fd, &ip, &value, BPF_ANY) < 0) {
        perror("bpf_map_update_elem");
        return 1;
    }

    printf("Blocked %s\n", ip_str);
    return 0;
}
```

