[dependencies]
libc = "0.2"
anyhow = "1"
```

## main.rs

```rust
use anyhow::{Context, Result};
use std::collections::HashSet;
use std::mem;
use std::os::fd::RawFd;

const ETH_P_ALL: u16 = 0x0003;

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_raw_socket() -> Result<RawFd> {
    let fd = unsafe {
        libc::socket(
            libc::AF_PACKET,
            libc::SOCK_RAW,
            htons(ETH_P_ALL) as i32,
        )
    };
    if fd < 0 {
        anyhow::bail!("socket() failed");
    }
    Ok(fd)
}

fn parse_ipv4_src(packet: &[u8]) -> Option<[u8; 4]> {
    if packet.len() < 14 + 20 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ihl = (packet[14] & 0x0f) as usize * 4;
    if packet.len() < 14 + ihl || ihl < 20 {
        return None;
    }

    Some([packet[26], packet[27], packet[28], packet[29]])
}

fn main() -> Result<()> {
    let fd = open_raw_socket().context("opening raw socket")?;

    let mut blocked = HashSet::new();
    blocked.insert([10, 0, 0, 1]);
    blocked.insert([192, 168, 1, 10]);

    let mut buf = vec![0u8; 2048];

    loop {
        let n = unsafe {
            libc::recv(
                fd,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            continue;
        }

        let packet = &buf[..n as usize];

        if let Some(src) = parse_ipv4_src(packet) {
            if blocked.contains(&src) {
                println!(
                    "drop src={}.{}.{}.{} len={}",
                    src[0], src[1], src[2], src[3], packet.len()
                );
                continue;
            } else {
                println!(
                    "pass src={}.{}.{}.{} len={}",
                    src[0], src[1], src[2], src[3], packet.len()
                );
            }
        }
    }
}
```

This version only **observes and classifies**. For real forwarding, use XDP/AF_XDP or DPDK with explicit authorized egress policy.

