# src/packet.rs

```rust
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Proto {
    Tcp,
    Udp,
    Icmp,
    Other,
}

#[derive(Debug, Clone)]
pub struct PacketMeta {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub proto: L4Proto,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

pub fn parse_packet(frame: &[u8]) -> Option<PacketMeta> {
    let eth = EthernetPacket::new(frame)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ipv4 = Ipv4Packet::new(eth.payload())?;
    let src_ip = ipv4.get_source();
    let dst_ip = ipv4.get_destination();

    match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ipv4.payload())?;
            Some(PacketMeta {
                src_ip: Some(src_ip),
                dst_ip: Some(dst_ip),
                proto: L4Proto::Tcp,
                src_port: Some(tcp.get_source()),
                dst_port: Some(tcp.get_destination()),
            })
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ipv4.payload())?;
            Some(PacketMeta {
                src_ip: Some(src_ip),
                dst_ip: Some(dst_ip),
                proto: L4Proto::Udp,
                src_port: Some(udp.get_source()),
                dst_port: Some(udp.get_destination()),
            })
        }
        IpNextHeaderProtocols::Icmp => Some(PacketMeta {
            src_ip: Some(src_ip),
            dst_ip: Some(dst_ip),
            proto: L4Proto::Icmp,
            src_port: None,
            dst_port: None,
        }),
        _ => Some(PacketMeta {
            src_ip: Some(src_ip),
            dst_ip: Some(dst_ip),
            proto: L4Proto::Other,
            src_port: None,
            dst_port: None,
        }),
    }
}

pub fn rewrite_dst_mac(frame: &mut [u8], new_dst: [u8; 6]) -> bool {
    if let Some(mut eth) = MutableEthernetPacket::new(frame) {
        eth.set_destination(new_dst.into());
        true
    } else {
        false
    }
}
