# src/filter.rs

```rust
use crate::config::{Action, RuleConfig};
use crate::packet::{L4Proto, PacketMeta};
use std::net::Ipv4Addr;
use std::str::FromStr;

#[derive(Debug, Clone)]
pub struct Rule {
    pub name: String,
    pub action: Action,
    pub proto: Option<L4Proto>,
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl Rule {
    pub fn from_config(cfg: &RuleConfig) -> anyhow::Result<Self> {
        let proto = match cfg.proto.as_deref() {
            Some("tcp") => Some(L4Proto::Tcp),
            Some("udp") => Some(L4Proto::Udp),
            Some("icmp") => Some(L4Proto::Icmp),
            Some(_) => Some(L4Proto::Other),
            None => None,
        };

        Ok(Self {
            name: cfg.name.clone(),
            action: cfg.action.clone(),
            proto,
            src_ip: cfg.src_ip.as_deref().map(Ipv4Addr::from_str).transpose()?,
            dst_ip: cfg.dst_ip.as_deref().map(Ipv4Addr::from_str).transpose()?,
            src_port: cfg.src_port,
            dst_port: cfg.dst_port,
        })
    }

    pub fn matches(&self, p: &PacketMeta) -> bool {
        if let Some(proto) = self.proto {
            if proto != p.proto {
                return false;
            }
        }
        if let Some(src_ip) = self.src_ip {
            if p.src_ip != Some(src_ip) {
                return false;
            }
        }
        if let Some(dst_ip) = self.dst_ip {
            if p.dst_ip != Some(dst_ip) {
                return false;
            }
        }
        if let Some(src_port) = self.src_port {
            if p.src_port != Some(src_port) {
                return false;
            }
        }
        if let Some(dst_port) = self.dst_port {
            if p.dst_port != Some(dst_port) {
                return false;
            }
        }
        true
    }
}

#[derive(Debug)]
pub struct FilterEngine {
    pub default_action: Action,
    pub rules: Vec<Rule>,
}

impl FilterEngine {
    pub fn decide<'a>(&'a self, p: &PacketMeta) -> (&'a Action, Option<&'a str>) {
        for rule in &self.rules {
            if rule.matches(p) {
                return (&rule.action, Some(&rule.name));
            }
        }
        (&self.default_action, None)
    }
}
