# src/forward.rs

```rust
use anyhow::{anyhow, Result};
use pnet::datalink::{self, Channel, DataLinkSender, NetworkInterface};
use std::str::FromStr;

pub struct Forwarder {
    tx: Box<dyn DataLinkSender>,
    next_hop_mac: [u8; 6],
}

impl Forwarder {
    pub fn new(egress_iface: &str, next_hop_mac: &str) -> Result<Self> {
        let interfaces = datalink::interfaces();
        let iface = interfaces
            .into_iter()
            .find(|i| i.name == egress_iface)
            .ok_or_else(|| anyhow!("egress interface not found"))?;

        let tx = match datalink::channel(&iface, Default::default())? {
            Channel::Ethernet(tx, _) => tx,
            _ => return Err(anyhow!("unsupported channel type")),
        };

        Ok(Self {
            tx,
            next_hop_mac: parse_mac(next_hop_mac)?,
        })
    }

    pub fn next_hop_mac(&self) -> [u8; 6] {
        self.next_hop_mac
    }

    pub fn send(&mut self, frame: &[u8]) -> Result<()> {
        match self.tx.send_to(frame, None) {
            Some(Ok(())) => Ok(()),
            Some(Err(e)) => Err(e.into()),
            None => Err(anyhow!("send failed")),
        }
    }
}

fn parse_mac(s: &str) -> Result<[u8; 6]> {
    let parts: Vec<_> = s.split(':').collect();
    if parts.len() != 6 {
        return Err(anyhow!("invalid MAC"));
    }
    let mut mac = [0u8; 6];
    for (i, p) in parts.iter().enumerate() {
        mac[i] = u8::from_str_radix(p, 16)?;
    }
    Ok(mac)
}
