# src/main.rs

```rust
mod config;
mod filter;
mod forward;
mod packet;
mod stats;

use anyhow::{anyhow, Result};
use config::{Action, Config};
use filter::{FilterEngine, Rule};
use forward::Forwarder;
use packet::{parse_packet, rewrite_dst_mac};
use pnet::datalink::{self, Channel};
use stats::new_shared;
use std::thread;
use std::time::Duration;

fn main() -> Result<()> {
    let cfg_path = std::env::args().nth(1).unwrap_or_else(|| "config.json".to_string());
    let cfg = Config::load(&cfg_path)?;

    let rules = cfg
        .rules
        .iter()
        .map(Rule::from_config)
        .collect::<Result<Vec<_>, _>>()?;

    let engine = FilterEngine {
        default_action: cfg.default_action.clone(),
        rules,
    };

    let shared_stats = new_shared();

    {
        let stats = shared_stats.clone();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(5));
            let s = stats.lock();
            println!(
                "rx={} parsed={} fwd={} drop={} parse_fail={}",
                s.rx_packets,
                s.parsed_packets,
                s.forwarded_packets,
                s.dropped_packets,
                s.parse_failures
            );
            for (rule, hits) in &s.rule_hits {
                println!("rule_hit {}={}", rule, hits);
            }
            for (reason, hits) in &s.drop_reasons {
                println!("drop_reason {}={}", reason, hits);
            }
        });
    }

    let interfaces = datalink::interfaces();
    let ingress = interfaces
        .into_iter()
        .find(|i| i.name == cfg.ingress_iface)
        .ok_or_else(|| anyhow!("ingress interface not found"))?;

    let (_, mut rx) = match datalink::channel(&ingress, Default::default())? {
        Channel::Ethernet(tx, rx) => (tx, rx),
        _ => return Err(anyhow!("unsupported ingress channel type")),
    };

    let mut forwarder = Forwarder::new(&cfg.egress_iface, &cfg.next_hop_mac)?;
    let next_hop_mac = forwarder.next_hop_mac();

    loop {
        match rx.next() {
            Ok(frame) => {
                {
                    let mut s = shared_stats.lock();
                    s.rx_packets += 1;
                }

                let meta = match parse_packet(frame) {
                    Some(m) => {
                        let mut s = shared_stats.lock();
                        s.parsed_packets += 1;
                        m
                    }
                    None => {
                        let mut s = shared_stats.lock();
                        s.parse_failures += 1;
                        s.dropped_packets += 1;
                        *s.drop_reasons.entry("parse_failed".into()).or_default() += 1;
                        continue;
                    }
                };

                let (action, rule_name) = engine.decide(&meta);

                if let Some(rule_name) = rule_name {
                    let mut s = shared_stats.lock();
                    *s.rule_hits.entry(rule_name.to_string()).or_default() += 1;
                }

                match action {
                    Action::Drop => {
                        let mut s = shared_stats.lock();
                        s.dropped_packets += 1;
                        *s.drop_reasons.entry("policy_drop".into()).or_default() += 1;
                    }
                    Action::Allow => {
                        let mut owned = frame.to_vec();
                        if !rewrite_dst_mac(&mut owned, next_hop_mac) {
                            let mut s = shared_stats.lock();
                            s.dropped_packets += 1;
                            *s.drop_reasons.entry("rewrite_failed".into()).or_default() += 1;
                            continue;
                        }

                        if let Err(_) = forwarder.send(&owned) {
                            let mut s = shared_stats.lock();
                            s.dropped_packets += 1;
                            *s.drop_reasons.entry("send_failed".into()).or_default() += 1;
                            continue;
                        }

                        let mut s = shared_stats.lock();
                        s.forwarded_packets += 1;
                    }
                }
            }
            Err(_) => {
                let mut s = shared_stats.lock();
                s.dropped_packets += 1;
                *s.drop_reasons.entry("rx_error".into()).or_default() += 1;
            }
        }
    }
}
