# Initial implementation

## 1. eBPF/XDP program: `xdp_filter_kern.c`

```c
// xdp_filter_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

char LICENSE[] SEC("license") = "GPL";

struct rule_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct rule_val {
    __u32 action; // 0=pass, 1=drop
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 4096);
    __type(key, struct rule_key);
    __type(value, struct rule_val);
} rules_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 2); // 0=pass, 1=drop
    __type(key, __u32);
    __type(value, struct stats_val);
} stats_map SEC(".maps");

static __always_inline void update_stats(__u32 idx, __u64 bytes)
{
    struct stats_val *s = bpf_map_lookup_elem(&stats_map, &idx);
    if (!s)
        return;
    s->packets++;
    s->bytes += bytes;
}

SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_PASS;

    if (iph->ihl < 5)
        return XDP_PASS;

    void *l4 = (void *)iph + (iph->ihl * 4);
    if (l4 > data_end)
        return XDP_PASS;

    struct rule_key key = {};
    key.src_ip = iph->saddr;
    key.dst_ip = iph->daddr;
    key.proto = iph->protocol;

    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return XDP_PASS;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    struct rule_val *rule = bpf_map_lookup_elem(&rules_map, &key);
    __u64 pkt_len = (__u64)((char *)data_end - (char *)data);

    if (rule && rule->action == 1) {
        update_stats(1, pkt_len);
        return XDP_DROP;
    }

    update_stats(0, pkt_len);
    return XDP_PASS;
}
```

