## 2. User-space loader: `loader.c`

This uses libbpf to load and attach the XDP program.

```c
// loader.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

struct rule_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct rule_val {
    __u32 action; // 0=pass, 1=drop
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

static int add_drop_rule(int map_fd,
                         const char *src_ip,
                         const char *dst_ip,
                         int src_port,
                         int dst_port,
                         int proto)
{
    struct rule_key key = {};
    struct rule_val val = { .action = 1 };

    if (inet_pton(AF_INET, src_ip, &key.src_ip) != 1) return -1;
    if (inet_pton(AF_INET, dst_ip, &key.dst_ip) != 1) return -1;

    key.src_port = htons(src_port);
    key.dst_port = htons(dst_port);
    key.proto = proto;

    return bpf_map_update_elem(map_fd, &key, &val, BPF_ANY);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <ifname> <xdp_kern.o>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *objfile = argv[2];
    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    struct bpf_object *obj = bpf_object__open_file(objfile, NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    if (bpf_object__load(obj)) {
        fprintf(stderr, "Failed to load BPF object\n");
        bpf_object__close(obj);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_filter_prog");
    if (!prog) {
        fprintf(stderr, "Program not found\n");
        bpf_object__close(obj);
        return 1;
    }

    int prog_fd = bpf_program__fd(prog);
    if (bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL) < 0) {
        fprintf(stderr, "Failed to attach XDP program\n");
        bpf_object__close(obj);
        return 1;
    }

    int rules_fd = bpf_object__find_map_fd_by_name(obj, "rules_map");
    int stats_fd = bpf_object__find_map_fd_by_name(obj, "stats_map");
    if (rules_fd < 0 || stats_fd < 0) {
        fprintf(stderr, "Failed to find maps\n");
        bpf_xdp_detach(ifindex, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
        bpf_object__close(obj);
        return 1;
    }

    // Example defensive rule: drop UDP from 10.0.0.1:12345 to 10.0.0.2:9999
    if (add_drop_rule(rules_fd, "10.0.0.1", "10.0.0.2", 12345, 9999, IPPROTO_UDP) == 0) {
        printf("Installed sample drop rule\n");
    }

    printf("XDP program attached to %s. Press Ctrl+C to exit.\n", ifname);

    while (1) {
        struct stats_val total[2] = {};
        for (int cpu = 0; cpu < 128; cpu++) {
            // placeholder: proper per-cpu aggregation would use bpf_map_lookup_elem
            // into an array sized by nr_cpus; keeping initial implementation simple
        }

        __u32 key = 0;
        struct stats_val pass_stats = {};
        if (bpf_map_lookup_elem(stats_fd, &key, &pass_stats) == 0) {
            printf("PASS packets=%llu bytes=%llu\n",
                   (unsigned long long)pass_stats.packets,
                   (unsigned long long)pass_stats.bytes);
        }

        key = 1;
        struct stats_val drop_stats = {};
        if (bpf_map_lookup_elem(stats_fd, &key, &drop_stats) == 0) {
            printf("DROP packets=%llu bytes=%llu\n",
                   (unsigned long long)drop_stats.packets,
                   (unsigned long long)drop_stats.bytes);
        }

        sleep(2);
    }

    bpf_xdp_detach(ifindex, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    bpf_object__close(obj);
    return 0;
}
