## Initial implementation

### 1. eBPF/XDP program in C

`xdp_filter_kern.c`
```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>

struct flow_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct counter {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, __u8); // 1 = allow, 2 = drop
} policy_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, struct counter);
} stats_map SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct flow_key *key, __u64 *pkt_len) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return -1;

    if (iph->ihl < 5)
        return -1;

    if ((void *)iph + iph->ihl * 4 > data_end)
        return -1;

    key->src_ip = iph->saddr;
    key->dst_ip = iph->daddr;
    key->proto = iph->protocol;
    key->src_port = 0;
    key->dst_port = 0;

    void *l4 = (void *)iph + iph->ihl * 4;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return -1;
        key->src_port = tcp->source;
        key->dst_port = tcp->dest;
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return -1;
        key->src_port = udp->source;
        key->dst_port = udp->dest;
    }

    *pkt_len = (__u64)((char *)data_end - (char *)data);
    return 0;
}

static __always_inline void update_stats(struct flow_key *key, __u64 pkt_len) {
    struct counter *c = bpf_map_lookup_elem(&stats_map, key);
    if (c) {
        __sync_fetch_and_add(&c->packets, 1);
        __sync_fetch_and_add(&c->bytes, pkt_len);
    } else {
        struct counter init = {
            .packets = 1,
            .bytes = pkt_len,
        };
        bpf_map_update_elem(&stats_map, key, &init, BPF_ANY);
    }
}

SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct flow_key key = {};
    __u64 pkt_len = 0;

    if (parse_ipv4(data, data_end, &key, &pkt_len) < 0)
        return XDP_PASS;

    update_stats(&key, pkt_len);

    __u8 *action = bpf_map_lookup_elem(&policy_map, &key);
    if (!action)
        return XDP_PASS;

    if (*action == 2)
        return XDP_DROP;

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

### 2. User-space loader/controller in C

`xdp_filter_user.c`
```c
// SPDX-License-Identifier: GPL-2.0
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

struct flow_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct counter {
    __u64 packets;
    __u64 bytes;
};

static int parse_ip(const char *s, __u32 *out) {
    struct in_addr addr;
    if (inet_pton(AF_INET, s, &addr) != 1)
        return -1;
    *out = addr.s_addr;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage:\n"
        "  %s <ifname> allow|drop <src_ip> <dst_ip> <proto> <src_port> <dst_port>\n"
        "  %s <ifname> stats\n",
        prog, prog);
}

int main(int argc, char **argv) {
    struct bpf_object *obj = NULL;
    int ifindex, prog_fd, policy_fd, stats_fd;
    int err;

    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    ifindex = if_nametoindex(argv[1]);
    if (!ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    obj = bpf_object__open_file("xdp_filter_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "open failed\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "load failed: %d\n", err);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_filter_prog");
    if (!prog) {
        fprintf(stderr, "program not found\n");
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    policy_fd = bpf_object__find_map_fd_by_name(obj, "policy_map");
    stats_fd = bpf_object__find_map_fd_by_name(obj, "stats_map");

    err = bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_DRV_MODE, NULL);
    if (err) {
        fprintf(stderr, "attach failed: %d\n", err);
        return 1;
    }

    if (!strcmp(argv[2], "stats")) {
        struct flow_key key = {}, next_key;
        struct counter values[128];
        printf("stats:\n");
        while (bpf_map_get_next_key(stats_fd, &key, &next_key) == 0) {
            memset(values, 0, sizeof(values));
            if (bpf_map_lookup_elem(stats_fd, &next_key, values) == 0) {
                __u64 packets = 0, bytes = 0;
                for (int i = 0; i < 128; i++) {
                    packets += values[i].packets;
                    bytes += values[i].bytes;
                }
                struct in_addr s = { .s_addr = next_key.src_ip };
                struct in_addr d = { .s_addr = next_key.dst_ip };
                printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
                    inet_ntoa(s), ntohs(next_key.src_port),
                    inet_ntoa(d), ntohs(next_key.dst_port),
                    next_key.proto,
                    (unsigned long long)packets,
                    (unsigned long long)bytes);
            }
            key = next_key;
        }
        return 0;
    }

    if (argc != 9) {
        usage(argv[0]);
        return 1;
    }

    struct flow_key fk = {};
    __u8 action = 0;

    if (parse_ip(argv[3], &fk.src_ip) < 0 || parse_ip(argv[4], &fk.dst_ip) < 0) {
        fprintf(stderr, "invalid IP\n");
        return 1;
    }

    fk.proto = (__u8)atoi(argv[5]);
    fk.src_port = htons((__u16)atoi(argv[6]));
    fk.dst_port = htons((__u16)atoi(argv[7]));

    if (!strcmp(argv[2], "allow"))
        action = 1;
    else if (!strcmp(argv[2], "drop"))
        action = 2;
    else {
        usage(argv[0]);
        return 1;
    }

    err = bpf_map_update_elem(policy_fd, &fk, &action, BPF_ANY);
    if (err) {
        fprintf(stderr, "policy update failed: %s\n", strerror(errno));
        return 1;
    }

    printf("policy installed\n");
    return 0;
}
