import (
	"log"
	"net"
	"os"
	"strings"
	"time"
)

const (
	listenAddr   = ":9000"
	upstreamAddr = "127.0.0.1:9001"
	maxPacket    = 2048
)

func allowed(pkt []byte) bool {
	// Minimal example filter:
	// drop empty packets and packets containing a blocked marker.
	if len(pkt) == 0 {
		return false
	}
	if strings.Contains(string(pkt), "BLOCK") {
		return false
	}
	return true
}

func main() {
	laddr, err := net.ResolveUDPAddr("udp", listenAddr)
	if err != nil {
		log.Fatal(err)
	}

	upaddr, err := net.ResolveUDPAddr("udp", upstreamAddr)
	if err != nil {
		log.Fatal(err)
	}

	inConn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		log.Fatal(err)
	}
	defer inConn.Close()

	outConn, err := net.DialUDP("udp", nil, upaddr)
	if err != nil {
		log.Fatal(err)
	}
	defer outConn.Close()

	log.Printf("relay listening on %s forwarding to %s", listenAddr, upstreamAddr)

	buf := make([]byte, maxPacket)

	for {
		n, clientAddr, err := inConn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("read error: %v", err)
			continue
		}

		pkt := make([]byte, n)
		copy(pkt, buf[:n])

		if !allowed(pkt) {
			log.Printf("dropped packet from %s", clientAddr)
			continue
		}

		_, err = outConn.Write(pkt)
		if err != nil {
			log.Printf("forward error: %v", err)
			continue
		}

		// Optional: wait briefly for one upstream response and relay it back.
		_ = outConn.SetReadDeadline(time.Now().Add(200 * time.Millisecond))
		rbuf := make([]byte, maxPacket)
		rn, _, err := outConn.ReadFromUDP(rbuf)
		if err == nil && rn > 0 {
			_, werr := inConn.WriteToUDP(rbuf[:rn], clientAddr)
			if werr != nil {
				log.Printf("response relay error: %v", werr)
			}
		}
	}
}
