```rust
use anyhow::{Context, Result};
use clap::Parser;
use ipnet::IpNet;
use mio::net::UdpSocket;
use mio::{Events, Interest, Poll, Token};
use std::net::{SocketAddr, ToSocketAddrs};

const INGRESS: Token = Token(0);

#[derive(Parser, Debug)]
#[command(about = "Minimal UDP filter/forwarder for lab use")]
struct Args {
    /// Local bind address, e.g. 0.0.0.0:9000
    #[arg(long)]
    bind: SocketAddr,

    /// Forward destination, e.g. 127.0.0.1:9001
    #[arg(long)]
    forward: String,

    /// Allowlisted source CIDR, repeatable, e.g. --allow 192.168.1.0/24
    #[arg(long)]
    allow: Vec<IpNet>,

    /// Maximum accepted packet size
    #[arg(long, default_value_t = 1500)]
    max_len: usize,
}

fn main() -> Result<()> {
    let args = Args::parse();

    let forward_addr = args
        .forward
        .to_socket_addrs()
        .context("failed to resolve forward address")?
        .next()
        .context("forward address resolved to nothing")?;

    let mut poll = Poll::new()?;
    let mut events = Events::with_capacity(1024);

    let mut ingress = UdpSocket::bind(args.bind)?;
    poll.registry()
        .register(&mut ingress, INGRESS, Interest::READABLE)?;

    let mut buf = vec![0u8; 65535];

    eprintln!(
        "listening on {}, forwarding to {}, allowlist={:?}, max_len={}",
        args.bind, forward_addr, args.allow, args.max_len
    );

    loop {
        poll.poll(&mut events, None)?;

        for event in events.iter() {
            if event.token() == INGRESS && event.is_readable() {
                loop {
                    match ingress.recv_from(&mut buf) {
                        Ok((n, src)) => {
                            if n > args.max_len {
                                continue;
                            }

                            if !args.allow.is_empty()
                                && !args.allow.iter().any(|net| net.contains(&src.ip()))
                            {
                                continue;
                            }

                            let payload = &buf[..n];
                            let _ = ingress.send_to(payload, forward_addr);
                        }
                        Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                            break;
                        }
                        Err(e) => {
                            eprintln!("recv error: {e}");
                            break;
                        }
                    }
                }
            }
        }
    }
}
```

