## Minimal working example: Rust UDP filter/forwarder

```rust
use std::collections::HashSet;
use std::io;
use std::net::{SocketAddr, UdpSocket};
use std::time::{Duration, Instant};

fn main() -> io::Result<()> {
    // Listen for inbound UDP packets here
    let listen: SocketAddr = "0.0.0.0:9000".parse().unwrap();

    // Forward allowed packets here
    let upstream: SocketAddr = "127.0.0.1:9001".parse().unwrap();

    // Simple source-IP allowlist for demo purposes
    let mut allow = HashSet::new();
    allow.insert("127.0.0.1".parse().unwrap());

    let sock = UdpSocket::bind(listen)?;
    sock.set_nonblocking(true)?;

    let out = UdpSocket::bind("0.0.0.0:0")?;
    out.set_nonblocking(true)?;

    let mut buf = [0u8; 2048];
    let mut passed: u64 = 0;
    let mut dropped: u64 = 0;
    let mut last_stats = Instant::now();

    loop {
        match sock.recv_from(&mut buf) {
            Ok((n, src)) => {
                if allow.contains(&src.ip()) {
                    let _ = out.send_to(&buf[..n], upstream)?;
                    passed += 1;
                } else {
                    dropped += 1;
                }
            }
            Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {
                if last_stats.elapsed() >= Duration::from_secs(5) {
                    eprintln!("passed={}, dropped={}", passed, dropped);
                    last_stats = Instant::now();
                }
                std::thread::sleep(Duration::from_micros(50));
            }
            Err(e) => return Err(e),
        }
    }
}
