## Minimal working example: filtered UDP relay in Go

```go
package main

import (
	"log"
	"net"
	"sync/atomic"
	"time"
)

var (
	packetsIn      uint64
	packetsDropped uint64
	packetsFwd     uint64
)

// allowPacket is a minimal packet-level filter.
// Replace with your own safe policy for lab use.
func allowPacket(src *net.UDPAddr, data []byte) bool {
	if len(data) == 0 || len(data) > 1400 {
		return false
	}
	// Example: only allow packets from localhost/private lab source port range
	if src.IP.IsLoopback() {
		return true
	}
	return false
}

func main() {
	listenAddr := ":9000"
	upstreamAddr := "127.0.0.1:9001"

	localAddr, err := net.ResolveUDPAddr("udp", listenAddr)
	if err != nil {
		log.Fatal(err)
	}
	upstreamUDPAddr, err := net.ResolveUDPAddr("udp", upstreamAddr)
	if err != nil {
		log.Fatal(err)
	}

	conn, err := net.ListenUDP("udp", localAddr)
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close()

	upstreamConn, err := net.DialUDP("udp", nil, upstreamUDPAddr)
	if err != nil {
		log.Fatal(err)
	}
	defer upstreamConn.Close()

	// Track most recent client for simple response relay.
	// Minimal demo only; production code should map flows properly.
	var lastClient atomic.Value
	lastClient.Store((*net.UDPAddr)(nil))

	// Upstream -> client relay
	go func() {
		buf := make([]byte, 2048)
		for {
			_ = upstreamConn.SetReadDeadline(time.Now().Add(1 * time.Second))
			n, _, err := upstreamConn.ReadFromUDP(buf)
			if err != nil {
				if ne, ok := err.(net.Error); ok && ne.Timeout() {
					continue
				}
				log.Printf("upstream read error: %v", err)
				continue
			}
			v := lastClient.Load()
			client, _ := v.(*net.UDPAddr)
			if client == nil {
				continue
			}
			_, err = conn.WriteToUDP(buf[:n], client)
			if err != nil {
				log.Printf("client write error: %v", err)
			}
		}
	}()

	// Metrics logger
	go func() {
		t := time.NewTicker(5 * time.Second)
		defer t.Stop()
		for range t.C {
			log.Printf("in=%d dropped=%d forwarded=%d",
				atomic.LoadUint64(&packetsIn),
				atomic.LoadUint64(&packetsDropped),
				atomic.LoadUint64(&packetsFwd),
			)
		}
	}()

	buf := make([]byte, 2048)
	log.Printf("listening on %s, forwarding to %s", listenAddr, upstreamAddr)

	for {
		n, src, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("read error: %v", err)
			continue
		}
		atomic.AddUint64(&packetsIn, 1)

		pkt := make([]byte, n)
		copy(pkt, buf[:n])

		if !allowPacket(src, pkt) {
			atomic.AddUint64(&packetsDropped, 1)
			continue
		}

		lastClient.Store(src)

		_, err = upstreamConn.Write(pkt)
		if err != nil {
			log.Printf("forward error: %v", err)
			continue
		}
		atomic.AddUint64(&packetsFwd, 1)
	}
}
