## `udp_forwarder.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <sched.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef BATCH_SIZE
#define BATCH_SIZE 32
#endif

#ifndef MAX_PKT
#define MAX_PKT 2048
#endif

typedef struct {
    int listen_port;
    const char *forward_ip;
    int forward_port;
    int cpu_core;          // -1 disables pinning
    int max_len_filter;    // drop packets > this size
    int first_byte_filter; // -1 disables, otherwise require buf[0] == value
} config_t;

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static int pin_to_cpu(int cpu) {
    if (cpu < 0) return 0;
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    return sched_setaffinity(0, sizeof(set), &set);
}

static int make_udp_listener(int port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

    int rcvbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(port);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking");
        close(fd);
        return -1;
    }

    return fd;
}

static int make_udp_sender(void) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket sender");
        return -1;
    }

    int sndbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf));

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking sender");
        close(fd);
        return -1;
    }

    return fd;
}

static bool packet_allowed(const uint8_t *buf, size_t len, const config_t *cfg) {
    if (len == 0) return false;
    if ((int)len > cfg->max_len_filter) return false;
    if (cfg->first_byte_filter >= 0 && buf[0] != (uint8_t)cfg->first_byte_filter) return false;
    return true;
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr,
                "Usage: %s <listen_port> <forward_ip> <forward_port> [cpu_core|-1] [max_len] [first_byte|-1]\n",
                argv[0]);
        return 1;
    }

    config_t cfg;
    cfg.listen_port = atoi(argv[1]);
    cfg.forward_ip = argv[2];
    cfg.forward_port = atoi(argv[3]);
    cfg.cpu_core = (argc > 4) ? atoi(argv[4]) : -1;
    cfg.max_len_filter = (argc > 5) ? atoi(argv[5]) : 1500;
    cfg.first_byte_filter = (argc > 6) ? atoi(argv[6]) : -1;

    if (pin_to_cpu(cfg.cpu_core) < 0) {
        perror("sched_setaffinity");
    }

    int rxfd = make_udp_listener(cfg.listen_port);
    if (rxfd < 0) return 1;

    int txfd = make_udp_sender();
    if (txfd < 0) {
        close(rxfd);
        return 1;
    }

    struct sockaddr_in fwd_addr;
    memset(&fwd_addr, 0, sizeof(fwd_addr));
    fwd_addr.sin_family = AF_INET;
    fwd_addr.sin_port = htons(cfg.forward_port);
    if (inet_pton(AF_INET, cfg.forward_ip, &fwd_addr.sin_addr) != 1) {
        fprintf(stderr, "invalid forward IP\n");
        close(rxfd);
        close(txfd);
        return 1;
    }

    int ep = epoll_create1(0);
    if (ep < 0) {
        perror("epoll_create1");
        close(rxfd);
        close(txfd);
        return 1;
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN;
    ev.data.fd = rxfd;

    if (epoll_ctl(ep, EPOLL_CTL_ADD, rxfd, &ev) < 0) {
        perror("epoll_ctl");
        close(ep);
        close(rxfd);
        close(txfd);
        return 1;
    }

    struct epoll_event events[8];

    // Preallocate batch receive/send structures
    struct mmsghdr msgs[BATCH_SIZE];
    struct iovec iovecs[BATCH_SIZE];
    struct sockaddr_in src_addrs[BATCH_SIZE];
    uint8_t bufs[BATCH_SIZE][MAX_PKT];

    struct mmsghdr out_msgs[BATCH_SIZE];
    struct iovec out_iovecs[BATCH_SIZE];

    uint64_t rx_packets = 0, tx_packets = 0, drop_packets = 0;

    fprintf(stderr, "Listening on UDP %d, forwarding to %s:%d\n",
            cfg.listen_port, cfg.forward_ip, cfg.forward_port);

    while (1) {
        int n = epoll_wait(ep, events, 8, -1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < n; i++) {
            if (events[i].data.fd != rxfd) continue;

            while (1) {
                memset(msgs, 0, sizeof(msgs));

                for (int j = 0; j < BATCH_SIZE; j++) {
                    iovecs[j].iov_base = bufs[j];
                    iovecs[j].iov_len = MAX_PKT;

                    msgs[j].msg_hdr.msg_iov = &iovecs[j];
                    msgs[j].msg_hdr.msg_iovlen = 1;
                    msgs[j].msg_hdr.msg_name = &src_addrs[j];
                    msgs[j].msg_hdr.msg_namelen = sizeof(src_addrs[j]);
                }

                int r = recvmmsg(rxfd, msgs, BATCH_SIZE, 0, NULL);
                if (r < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                    perror("recvmmsg");
                    break;
                }

                rx_packets += r;

                int out_count = 0;
                memset(out_msgs, 0, sizeof(out_msgs));

                for (int j = 0; j < r; j++) {
                    size_t len = msgs[j].msg_len;
                    uint8_t *buf = bufs[j];

                    if (!packet_allowed(buf, len, &cfg)) {
                        drop_packets++;
                        continue;
                    }

                    out_iovecs[out_count].iov_base = buf;
                    out_iovecs[out_count].iov_len = len;

                    out_msgs[out_count].msg_hdr.msg_iov = &out_iovecs[out_count];
                    out_msgs[out_count].msg_hdr.msg_iovlen = 1;
                    out_msgs[out_count].msg_hdr.msg_name = &fwd_addr;
                    out_msgs[out_count].msg_hdr.msg_namelen = sizeof(fwd_addr);
                    out_count++;
                }

                if (out_count > 0) {
                    int s = sendmmsg(txfd, out_msgs, out_count, 0);
                    if (s < 0) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            perror("sendmmsg");
                        }
                    } else {
                        tx_packets += s;
                        if (s < out_count) {
                            drop_packets += (out_count - s);
                        }
                    }
                }

                // Lightweight periodic stats
                static uint64_t loops = 0;
                loops++;
                if ((loops & 0x3FFF) == 0) {
                    fprintf(stderr, "rx=%llu tx=%llu drop=%llu\n",
                            (unsigned long long)rx_packets,
                            (unsigned long long)tx_packets,
                            (unsigned long long)drop_packets);
                }
            }
        }
    }

    close(ep);
    close(rxfd);
    close(txfd);
    return 0;
}
```

