## `ultra_forwarder.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <sched.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>

#define MAX_EVENTS 64
#define BATCH_RECV  32
#define PKT_BUF_SZ  2048

static volatile sig_atomic_t g_running = 1;

typedef struct {
    int in_fd;
    int out_fd;
    struct sockaddr_in out_addr;
    uint32_t allow_src_ip;   // network byte order, 0 = allow any
    size_t min_len;
    size_t max_len;
} config_t;

static void on_sigint(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static int pin_to_cpu(int cpu) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    return sched_setaffinity(0, sizeof(set), &set);
}

static int make_udp_listener(const char *bind_ip, uint16_t port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
#ifdef SO_REUSEPORT
    setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one));
#endif

    int rcvbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, bind_ip, &addr.sin_addr) != 1) {
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

static int make_udp_sender(void) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    int sndbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf));

    if (set_nonblocking(fd) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int packet_allowed(const config_t *cfg,
                          const struct sockaddr_in *src,
                          ssize_t len) {
    if (len < 0) return 0;
    if ((size_t)len < cfg->min_len || (size_t)len > cfg->max_len) return 0;
    if (cfg->allow_src_ip != 0 && src->sin_addr.s_addr != cfg->allow_src_ip) return 0;
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 5) {
        fprintf(stderr,
                "Usage: %s <bind_ip> <bind_port> <dst_ip> <dst_port> "
                "[allow_src_ip|any] [cpu]\n",
                argv[0]);
        return 1;
    }

    const char *bind_ip = argv[1];
    uint16_t bind_port = (uint16_t)atoi(argv[2]);
    const char *dst_ip = argv[3];
    uint16_t dst_port = (uint16_t)atoi(argv[4]);

    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.min_len = 1;
    cfg.max_len = PKT_BUF_SZ;

    if (argc >= 6 && strcmp(argv[5], "any") != 0) {
        if (inet_pton(AF_INET, argv[5], &cfg.allow_src_ip) != 1) {
            fprintf(stderr, "Invalid allow_src_ip\n");
            return 1;
        }
    }

    if (argc >= 7) {
        int cpu = atoi(argv[6]);
        if (pin_to_cpu(cpu) != 0) {
            perror("sched_setaffinity");
        }
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    cfg.in_fd = make_udp_listener(bind_ip, bind_port);
    if (cfg.in_fd < 0) {
        perror("make_udp_listener");
        return 1;
    }

    cfg.out_fd = make_udp_sender();
    if (cfg.out_fd < 0) {
        perror("make_udp_sender");
        close(cfg.in_fd);
        return 1;
    }

    memset(&cfg.out_addr, 0, sizeof(cfg.out_addr));
    cfg.out_addr.sin_family = AF_INET;
    cfg.out_addr.sin_port = htons(dst_port);
    if (inet_pton(AF_INET, dst_ip, &cfg.out_addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid dst_ip\n");
        close(cfg.in_fd);
        close(cfg.out_fd);
        return 1;
    }

    int ep = epoll_create1(0);
    if (ep < 0) {
        perror("epoll_create1");
        close(cfg.in_fd);
        close(cfg.out_fd);
        return 1;
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN;
    ev.data.fd = cfg.in_fd;

    if (epoll_ctl(ep, EPOLL_CTL_ADD, cfg.in_fd, &ev) < 0) {
        perror("epoll_ctl");
        close(ep);
        close(cfg.in_fd);
        close(cfg.out_fd);
        return 1;
    }

    struct epoll_event events[MAX_EVENTS];
    unsigned char bufs[BATCH_RECV][PKT_BUF_SZ];

    while (g_running) {
        int n = epoll_wait(ep, events, MAX_EVENTS, 1000);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < n; i++) {
            if (events[i].data.fd != cfg.in_fd) continue;

            for (int j = 0; j < BATCH_RECV; j++) {
                struct sockaddr_in src;
                socklen_t slen = sizeof(src);
                ssize_t r = recvfrom(cfg.in_fd, bufs[j], PKT_BUF_SZ, 0,
                                     (struct sockaddr *)&src, &slen);
                if (r < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                    if (errno == EINTR) continue;
                    break;
                }

                if (!packet_allowed(&cfg, &src, r)) {
                    continue;
                }

                ssize_t s = sendto(cfg.out_fd, bufs[j], (size_t)r, 0,
                                   (struct sockaddr *)&cfg.out_addr,
                                   sizeof(cfg.out_addr));
                (void)s; // In a production service, track drops/backpressure.
            }
        }
    }

    close(ep);
    close(cfg.in_fd);
    close(cfg.out_fd);
    return 0;
}
