## Example: minimal safe UDP filter/forwarder in Go

```go
package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"sync/atomic"
	"syscall"
	"time"
)

type Config struct {
	ListenAddr   string
	UpstreamAddr string
	AllowedIPs   map[string]struct{}
}

func main() {
	cfg := Config{
		ListenAddr:   ":9000",
		UpstreamAddr: "127.0.0.1:9001",
		AllowedIPs: map[string]struct{}{
			"127.0.0.1": {},
		},
	}

	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()

	if err := run(ctx, cfg); err != nil {
		log.Fatal(err)
	}
}

func run(ctx context.Context, cfg Config) error {
	laddr, err := net.ResolveUDPAddr("udp", cfg.ListenAddr)
	if err != nil {
		return fmt.Errorf("resolve listen addr: %w", err)
	}
	upstream, err := net.ResolveUDPAddr("udp", cfg.UpstreamAddr)
	if err != nil {
		return fmt.Errorf("resolve upstream addr: %w", err)
	}

	conn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		return fmt.Errorf("listen: %w", err)
	}
	defer conn.Close()

	upConn, err := net.DialUDP("udp", nil, upstream)
	if err != nil {
		return fmt.Errorf("dial upstream: %w", err)
	}
	defer upConn.Close()

	var accepted uint64
	var dropped uint64
	var forwarded uint64

	go func() {
		t := time.NewTicker(5 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				log.Printf("stats accepted=%d dropped=%d forwarded=%d",
					atomic.LoadUint64(&accepted),
					atomic.LoadUint64(&dropped),
					atomic.LoadUint64(&forwarded),
				)
			}
		}
	}()

	buf := make([]byte, 2048)

	for {
		_ = conn.SetReadDeadline(time.Now().Add(1 * time.Second))
		n, src, err := conn.ReadFromUDP(buf)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				select {
				case <-ctx.Done():
					return nil
				default:
					continue
				}
			}
			return fmt.Errorf("read: %w", err)
		}

		srcIP := src.IP.String()
		if _, ok := cfg.AllowedIPs[srcIP]; !ok {
			atomic.AddUint64(&dropped, 1)
			continue
		}
		atomic.AddUint64(&accepted, 1)

		if _, err := upConn.Write(buf[:n]); err != nil {
			log.Printf("forward error from %s: %v", src, err)
			continue
		}
		atomic.AddUint64(&forwarded, 1)
	}
}
```

