## Minimal example in C

```c
// toy_l2_filter.c
// Build: gcc -O2 -Wall -o toy_l2_filter toy_l2_filter.c
// Run:   sudo ./toy_l2_filter eth0
//
// WARNING:
// - Lab/demo use only.
// - Re-injecting frames on the same interface can create loops.
// - This is intentionally minimal and not optimized.

#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

static volatile sig_atomic_t stop_flag = 0;

static void on_sigint(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int ifindex_from_name(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);
    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static void print_mac(const uint8_t *m) {
    printf("%02x:%02x:%02x:%02x:%02x:%02x",
           m[0], m[1], m[2], m[3], m[4], m[5]);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <iface>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    signal(SIGINT, on_sigint);

    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket(AF_PACKET)");
        return 1;
    }

    int ifindex = ifindex_from_name(fd, ifname);
    if (ifindex < 0) {
        perror("SIOCGIFINDEX");
        close(fd);
        return 1;
    }

    struct sockaddr_ll bind_addr;
    memset(&bind_addr, 0, sizeof(bind_addr));
    bind_addr.sll_family   = AF_PACKET;
    bind_addr.sll_protocol = htons(ETH_P_ALL);
    bind_addr.sll_ifindex  = ifindex;

    if (bind(fd, (struct sockaddr *)&bind_addr, sizeof(bind_addr)) < 0) {
        perror("bind(AF_PACKET)");
        close(fd);
        return 1;
    }

    uint8_t buf[2048];
    printf("listening on %s (ifindex=%d), Ctrl-C to stop\n", ifname, ifindex);

    while (!stop_flag) {
        struct sockaddr_ll src_addr;
        socklen_t src_len = sizeof(src_addr);
        ssize_t n = recvfrom(fd, buf, sizeof(buf), 0,
                             (struct sockaddr *)&src_addr, &src_len);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        if ((size_t)n < sizeof(struct ethhdr)) continue;

        struct ethhdr *eth = (struct ethhdr *)buf;
        uint16_t ethertype = ntohs(eth->h_proto);

        // Tiny demo policy:
        // - allow only ARP and IPv4
        // - drop everything else
        bool allow = (ethertype == ETH_P_ARP || ethertype == ETH_P_IP);

        printf("[%s] ", allow ? "ALLOW" : "DROP ");
        print_mac(eth->h_source);
        printf(" -> ");
        print_mac(eth->h_dest);
        printf(" type=0x%04x len=%zd\n", ethertype, n);

        if (!allow) continue;

        // Optional re-injection demo:
        // Only forward packets marked as PACKET_OUTGOING? No:
        // To reduce obvious loops, skip frames we ourselves transmitted.
        if (src_addr.sll_pkttype == PACKET_OUTGOING) continue;

        struct sockaddr_ll tx_addr;
        memset(&tx_addr, 0, sizeof(tx_addr));
        tx_addr.sll_family   = AF_PACKET;
        tx_addr.sll_ifindex  = ifindex;
        tx_addr.sll_halen    = ETH_ALEN;
        memcpy(tx_addr.sll_addr, eth->h_dest, ETH_ALEN);

        if (sendto(fd, buf, n, 0, (struct sockaddr *)&tx_addr, sizeof(tx_addr)) < 0) {
            perror("sendto");
        }
    }

    close(fd);
    return 0;
}
```

