use std::{
    collections::HashSet,
    net::{IpAddr, SocketAddr},
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Duration,
};

use tokio::{net::UdpSocket, time};

struct Metrics {
    received: AtomicU64,
    accepted: AtomicU64,
    dropped: AtomicU64,
    forwarded: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            accepted: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            forwarded: AtomicU64::new(0),
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse()?;
    let upstream_addr: SocketAddr = "127.0.0.1:9001".parse()?;

    // Replace with your lab/test sender IPs.
    let allowed_sources: HashSet<IpAddr> = [
        "127.0.0.1".parse()?,
    ]
    .into_iter()
    .collect();

    // Optional payload prefix filter.
    let required_prefix: Option<&'static [u8]> = Some(b"OK:");

    let inbound = Arc::new(UdpSocket::bind(listen_addr).await?);
    let outbound = Arc::new(UdpSocket::bind("0.0.0.0:0").await?);
    let metrics = Arc::new(Metrics::new());

    println!("listening on {}", listen_addr);
    println!("forwarding to {}", upstream_addr);

    {
        let metrics = Arc::clone(&metrics);
        tokio::spawn(async move {
            let mut ticker = time::interval(Duration::from_secs(5));
            loop {
                ticker.tick().await;
                println!(
                    "rx={} accepted={} dropped={} fwd={}",
                    metrics.received.load(Ordering::Relaxed),
                    metrics.accepted.load(Ordering::Relaxed),
                    metrics.dropped.load(Ordering::Relaxed),
                    metrics.forwarded.load(Ordering::Relaxed),
                );
            }
        });
    }

    let mut buf = vec![0u8; 2048];

    loop {
        let (n, src) = inbound.recv_from(&mut buf).await?;
        metrics.received.fetch_add(1, Ordering::Relaxed);

        if !allowed_sources.contains(&src.ip()) {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
            continue;
        }

        let packet = &buf[..n];

        if let Some(prefix) = required_prefix {
            if !packet.starts_with(prefix) {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
                continue;
            }
        }

        metrics.accepted.fetch_add(1, Ordering::Relaxed);

        let sent = outbound.send_to(packet, upstream_addr).await?;
        if sent == packet.len() {
            metrics.forwarded.fetch_add(1, Ordering::Relaxed);
        }
    }
}
```

