## Minimal working example: UDP filter + forwarder in Go

What it does:
- Listens on one UDP port
- Applies a simple packet-level filter
- Forwards allowed packets to an upstream UDP server
- Returns upstream responses to the original client
- Uses pooled buffers to reduce allocations

### `main.go`
```go
package main

import (
	"bytes"
	"context"
	"flag"
	"log"
	"net"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"
)

type Config struct {
	ListenAddr   string
	UpstreamAddr string
	MaxPacket    int
	DropPrefix   []byte
	ReadTimeout  time.Duration
	WriteTimeout time.Duration
}

type packet struct {
	n    int
	addr *net.UDPAddr
	buf  []byte
}

func main() {
	var cfg Config
	var drop string

	flag.StringVar(&cfg.ListenAddr, "listen", ":9000", "UDP listen address")
	flag.StringVar(&cfg.UpstreamAddr, "upstream", "127.0.0.1:9001", "UDP upstream address")
	flag.IntVar(&cfg.MaxPacket, "max-packet", 2048, "max UDP packet size")
	flag.StringVar(&drop, "drop-prefix", "DROP", "drop packets starting with this prefix")
	flag.DurationVar(&cfg.ReadTimeout, "read-timeout", 2*time.Second, "socket read timeout")
	flag.DurationVar(&cfg.WriteTimeout, "write-timeout", 2*time.Second, "socket write timeout")
	flag.Parse()

	cfg.DropPrefix = []byte(drop)

	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()

	if err := run(ctx, cfg); err != nil {
		log.Fatal(err)
	}
}

func run(ctx context.Context, cfg Config) error {
	laddr, err := net.ResolveUDPAddr("udp", cfg.ListenAddr)
	if err != nil {
		return err
	}
	uaddr, err := net.ResolveUDPAddr("udp", cfg.UpstreamAddr)
	if err != nil {
		return err
	}

	inConn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		return err
	}
	defer inConn.Close()

	upConn, err := net.DialUDP("udp", nil, uaddr)
	if err != nil {
		return err
	}
	defer upConn.Close()

	log.Printf("listening on %s, forwarding to %s", cfg.ListenAddr, cfg.UpstreamAddr)

	var bufPool = sync.Pool{
		New: func() any {
			b := make([]byte, cfg.MaxPacket)
			return &b
		},
	}

	type clientKey string
	clientMap := sync.Map{} // maps a short request token to client addr for demo request/response pairing

	// Response path: read from upstream and send back to remembered client.
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			default:
			}

			_ = upConn.SetReadDeadline(time.Now().Add(cfg.ReadTimeout))
			bp := bufPool.Get().(*[]byte)
			buf := *bp

			n, err := upConn.Read(buf)
			if err != nil {
				if ne, ok := err.(net.Error); ok && ne.Timeout() {
					bufPool.Put(bp)
					continue
				}
				log.Printf("upstream read error: %v", err)
				bufPool.Put(bp)
				continue
			}

			// Demo correlation: first 8 bytes are treated as request token.
			if n < 8 {
				bufPool.Put(bp)
				continue
			}
			key := clientKey(string(buf[:8]))
			v, ok := clientMap.Load(key)
			if !ok {
				bufPool.Put(bp)
				continue
			}
			clientAddr := v.(*net.UDPAddr)

			_ = inConn.SetWriteDeadline(time.Now().Add(cfg.WriteTimeout))
			if _, err := inConn.WriteToUDP(buf[:n], clientAddr); err != nil {
				log.Printf("client write error: %v", err)
			}

			bufPool.Put(bp)
		}
	}()

	for {
		select {
		case <-ctx.Done():
			return nil
		default:
		}

		_ = inConn.SetReadDeadline(time.Now().Add(500 * time.Millisecond))
		bp := bufPool.Get().(*[]byte)
		buf := *bp

		n, clientAddr, err := inConn.ReadFromUDP(buf)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				bufPool.Put(bp)
				continue
			}
			bufPool.Put(bp)
			return err
		}

		// Packet-level filter: drop packets with a forbidden prefix.
		if bytes.HasPrefix(buf[:n], cfg.DropPrefix) {
			bufPool.Put(bp)
			continue
		}

		// Demo request/response correlation:
		// require first 8 bytes to be a client-provided token.
		if n >= 8 {
			key := clientKey(string(buf[:8]))
			clientMap.Store(key, clientAddr)
		}

		_ = upConn.SetWriteDeadline(time.Now().Add(cfg.WriteTimeout))
		if _, err := upConn.Write(buf[:n]); err != nil {
			log.Printf("upstream write error: %v", err)
		}

		bufPool.Put(bp)
	}
}
```

