	defer conn.Close()

	buf := make([]byte, 2048)
	log.Println("echo upstream listening on :9001")
	for {
		n, client, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Println(err)
			continue
		}
		_, err = conn.WriteToUDP(buf[:n], client)
		if err != nil {
			log.Println(err)
		}
	}
}
