## Minimal working example: Rust UDP filter/forwarder

### `Cargo.toml`
```toml
[package]
name = "udp_filter_forwarder"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1", features = ["full"] }
clap = { version = "4", features = ["derive"] }
anyhow = "1"
```

### `src/main.rs`
```rust
use anyhow::{Context, Result};
use clap::Parser;
use std::collections::HashSet;
use std::net::{IpAddr, SocketAddr};
use tokio::net::UdpSocket;

#[derive(Parser, Debug)]
#[command(about = "Minimal UDP filter/forwarder for authorized testing")]
struct Args {
    /// Local bind address, e.g. 0.0.0.0:9000
    #[arg(long)]
    bind: SocketAddr,

    /// Upstream destination, e.g. 127.0.0.1:9001
    #[arg(long)]
    forward: SocketAddr,

    /// Comma-separated allowlist of source IPs, e.g. 127.0.0.1,10.0.0.2
    #[arg(long, default_value = "127.0.0.1")]
    allow: String,

    /// Max packet size
    #[arg(long, default_value_t = 2048)]
    mtu: usize,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    let allowed: HashSet<IpAddr> = args
        .allow
        .split(',')
        .filter(|s| !s.trim().is_empty())
        .map(|s| s.trim().parse())
        .collect::<std::result::Result<_, _>>()
        .context("failed to parse allowlist IPs")?;

    let sock = UdpSocket::bind(args.bind)
        .await
        .with_context(|| format!("failed to bind {}", args.bind))?;

    let upstream = UdpSocket::bind("0.0.0.0:0")
        .await
        .context("failed to bind ephemeral upstream socket")?;
    upstream
        .connect(args.forward)
        .await
        .with_context(|| format!("failed to connect upstream {}", args.forward))?;

    eprintln!(
        "listening on {}, forwarding to {}, allowed sources: {:?}",
        args.bind, args.forward, allowed
    );

    let mut buf = vec![0u8; args.mtu];
    let mut passed: u64 = 0;
    let mut dropped: u64 = 0;

    loop {
        let (n, src) = sock.recv_from(&mut buf).await?;
        if !allowed.contains(&src.ip()) {
            dropped += 1;
            if dropped % 100 == 1 {
                eprintln!("dropped={} last_src={}", dropped, src);
            }
            continue;
        }

        upstream.send(&buf[..n]).await?;
        passed += 1;

        if passed % 100 == 1 {
            eprintln!("passed={} dropped={} last_src={} bytes={}", passed, dropped, src, n);
        }
    }
}
```

