## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A parsed record view into a reusable buffer.
/// Fields are represented as byte ranges into `line_buf` to avoid allocations.
#[derive(Debug)]
pub struct Record {
    pub fields: Vec<(usize, usize)>,
}

impl Record {
    #[inline]
    pub fn field<'a>(&self, line: &'a [u8], idx: usize) -> Option<&'a [u8]> {
        self.fields.get(idx).map(|&(start, end)| &line[start..end])
    }

    #[inline]
    pub fn len(&self) -> usize {
        self.fields.len()
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.fields.is_empty()
    }
}

/// High-throughput streaming parser for delimiter-separated records.
/// Designed to reuse buffers and avoid per-line allocations where possible.
pub struct StreamingParser<R: BufRead> {
    reader: R,
    delimiter: u8,
    line_buf: Vec<u8>,
    record: Record,
}

impl<R: BufRead> StreamingParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            reader,
            delimiter,
            line_buf: Vec::with_capacity(64 * 1024),
            record: Record {
                fields: Vec::with_capacity(32),
            },
        }
    }

    /// Parses the next record into internal reusable buffers.
    /// Returns:
    /// - Ok(Some((&line_buf, &record))) for a parsed line
    /// - Ok(None) on EOF
    /// - Err(...) on I/O error
    pub fn next_record(&mut self) -> io::Result<Option<(&[u8], &Record)>> {
        self.line_buf.clear();
        self.record.fields.clear();

        let bytes_read = self.reader.read_until(b'\n', &mut self.line_buf)?;
        if bytes_read == 0 {
            return Ok(None);
        }

        // Trim trailing newline / CRLF without allocation
        if self.line_buf.last() == Some(&b'\n') {
            self.line_buf.pop();
            if self.line_buf.last() == Some(&b'\r') {
                self.line_buf.pop();
            }
        }

        self.parse_fields();
        Ok(Some((&self.line_buf, &self.record)))
    }

    #[inline]
    fn parse_fields(&mut self) {
        let mut start = 0;
        let len = self.line_buf.len();

        for i in 0..len {
            if self.line_buf[i] == self.delimiter {
                self.record.fields.push((start, i));
                start = i + 1;
            }
        }

        // Final field
        self.record.fields.push((start, len));
    }

    /// Process all records with a callback.
    /// The callback must not retain references after it returns.
    pub fn process_all<F>(&mut self, mut handler: F) -> io::Result<()>
    where
        F: FnMut(&[u8], &Record) -> io::Result<()>,
    {
        while let Some((line, record)) = self.next_record()? {
            handler(line, record)?;
        }
        Ok(())
    }
}

/// Example high-throughput aggregation:
/// Count records and sum a numeric field at `numeric_field_idx`.
pub fn process_file<P: AsRef<Path>>(path: P, delimiter: u8, numeric_field_idx: usize) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file); // 1 MiB buffer
    let mut parser = StreamingParser::new(reader, delimiter);

    let mut row_count: u64 = 0;
    let mut sum: u64 = 0;

    parser.process_all(|line, record| {
        row_count += 1;

        if let Some(field_bytes) = record.field(line, numeric_field_idx) {
            if !field_bytes.is_empty() {
                if let Ok(s) = std::str::from_utf8(field_bytes) {
                    if let Ok(v) = s.parse::<u64>() {
                        sum += v;
                    }
                }
            }
        }

        Ok(())
    })?;

    println!("rows={row_count}, sum={sum}");
    Ok(())
}

fn main() -> io::Result<()> {
    // Example usage:
    // Parses a TSV file and sums the 3rd field (index 2)
    process_file("large_input.tsv", b'\t', 2)
}
```

