## Faster numeric parsing

If numeric parsing is hot, replace:

```rust
if let Ok(s) = std::str::from_utf8(field_bytes) {
    if let Ok(v) = s.parse::<u64>() {
        sum += v;
    }
}
```

with a manual byte parser:

```rust
#[inline]
fn parse_u64_bytes(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut value: u64 = 0;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        value = value.checked_mul(10)?
                     .checked_add((b - b'0') as u64)?;
    }
    Some(value)
}
```

Then use:

```rust
if let Some(field_bytes) = record.field(line, numeric_field_idx) {
    if let Some(v) = parse_u64_bytes(field_bytes) {
        sum += v;
    }
}
```

