## More robust chunk-based parser for very large records

If records may exceed typical line sizes, `read_until()` can still grow `line_buf` significantly. For stricter memory control, use a **chunk-scanning parser** that processes input in fixed-size blocks.

Here is a lower-level version that scans arbitrary chunks and emits records without requiring the whole file in memory:

```rust
use std::fs::File;
use std::io::{self, Read};
use std::path::Path;

pub struct ChunkedLineParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
    filled: usize,
}

impl<R: Read> ChunkedLineParser<R> {
    pub fn new(reader: R, chunk_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; chunk_size],
            carry: Vec::with_capacity(chunk_size),
            filled: 0,
        }
    }

    pub fn process_lines<F>(&mut self, mut handler: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                if !self.carry.is_empty() {
                    handler(&self.carry)?;
                    self.carry.clear();
                }
                return Ok(());
            }

            let chunk = &self.buf[..n];
            let mut start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    if self.carry.is_empty() {
                        let mut line = &chunk[start..i];
                        if line.last() == Some(&b'\r') {
                            line = &line[..line.len() - 1];
                        }
                        handler(line)?;
                    } else {
                        self.carry.extend_from_slice(&chunk[start..i]);
                        if self.carry.last() == Some(&b'\r') {
                            self.carry.pop();
                        }
                        handler(&self.carry)?;
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }
    }
}

pub fn process_large_file_chunked<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let mut parser = ChunkedLineParser::new(file, 1024 * 1024);

    let mut count = 0u64;
    parser.process_lines(|line| {
        count += 1;
        // Process line here
        let _ = line;
        Ok(())
    })?;

    println!("lines={count}");
    Ok(())
}
```

