## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid loading the whole file into memory
/// - Handle records spanning multiple chunks
/// - Process records immediately via callback
///
/// This parser emits each line as raw bytes (`&[u8]`) to avoid UTF-8 overhead.
/// If your input is guaranteed UTF-8, you can convert in the callback.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    carry: Vec<u8>,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a specified buffer size.
    ///
    /// Recommended sizes:
    /// - 64 KiB to 1 MiB for many workloads
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            carry: Vec::new(),
        }
    }

    /// Parse newline-delimited records and invoke `on_record` for each one.
    ///
    /// `on_record` receives the raw bytes of a record without the trailing '\n'.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            // Refill buffer if fully consumed
            if self.start == self.end {
                let n = self.reader.read(&mut self.buf)?;
                if n == 0 {
                    // EOF: emit any remaining partial record
                    if !self.carry.is_empty() {
                        on_record(&self.carry);
                        self.carry.clear();
                    }
                    return Ok(());
                }
                self.start = 0;
                self.end = n;
            }

            let chunk = &self.buf[self.start..self.end];
            let mut line_start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    let line = &chunk[line_start..i];

                    if self.carry.is_empty() {
                        // Fast path: line fully contained in current chunk
                        on_record(line);
                    } else {
                        // Slow path: line spans multiple chunks
                        self.carry.extend_from_slice(line);
                        on_record(&self.carry);
                        self.carry.clear();
                    }

                    line_start = i + 1;
                }
            }

            // Save any trailing partial record
            if line_start < chunk.len() {
                self.carry.extend_from_slice(&chunk[line_start..]);
            }

            self.start = self.end;
        }
    }
}

/// Example record parser:
/// Parse lines of the form:
///   timestamp,user_id,event_type,payload
///
/// This function avoids allocations except where conversion is needed.
/// For maximum throughput, keep data as bytes as long as possible.
fn process_record(record: &[u8]) {
    // Trim trailing '\r' for Windows line endings
    let record = if record.last() == Some(&b'\r') {
        &record[..record.len() - 1]
    } else {
        record
    };

    let mut fields = record.split(|&b| b == b',');

    let timestamp = fields.next().unwrap_or(b"");
    let user_id = fields.next().unwrap_or(b"");
    let event_type = fields.next().unwrap_or(b"");
    let payload = fields.next().unwrap_or(b"");

    // Example: lightweight processing
    // In real systems, avoid expensive UTF-8 conversion unless necessary.
    println!(
        "ts={:?}, user={:?}, event={:?}, payload_len={}",
        String::from_utf8_lossy(timestamp),
        String::from_utf8_lossy(user_id),
        String::from_utf8_lossy(event_type),
        payload.len()
    );
}

fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::with_capacity(reader, 1024 * 1024);

    parser.parse(|record| {
        process_record(record);
    })?;

    Ok(())
}
```

