use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// High-throughput streaming line parser.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid loading the whole file into memory
/// - Handle records split across chunk boundaries
/// - Process records immediately via callback
///
/// Record format:
/// - newline-delimited (`\n`)
/// - optional `\r\n` support
///
/// For each parsed line, `on_record` is called with the line bytes
/// excluding the trailing newline.
pub struct StreamingLineParser<const BUF_SIZE: usize = 1024 * 1024> {
    buf: Box<[u8; BUF_SIZE]>,
    carry: Vec<u8>,
}

impl<const BUF_SIZE: usize> StreamingLineParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0u8; BUF_SIZE]),
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse from any reader.
    ///
    /// `on_record` is called for each full line.
    pub fn parse<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            let n = reader.read(&mut *self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            self.process_chunk(chunk, &mut on_record);
        }

        // Flush any trailing partial record as a final record.
        if !self.carry.is_empty() {
            let line = trim_cr(&self.carry);
            on_record(line);
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F)
    where
        F: FnMut(&[u8]),
    {
        let mut start = 0;

        for i in memchr_iter(b'\n', chunk) {
            let line_part = &chunk[start..i];

            if self.carry.is_empty() {
                let line = trim_cr(line_part);
                on_record(line);
            } else {
                self.carry.extend_from_slice(line_part);
                let line = trim_cr(&self.carry);
                on_record(line);
                self.carry.clear();
            }

            start = i + 1;
        }

        // Save trailing partial line, if any.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }
    }
}

/// Trim trailing '\r' for CRLF support.
fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(b'\r') = line.last().copied() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Simple memchr-style iterator for byte search.
/// For maximum performance in production, prefer the `memchr` crate.
fn memchr_iter(byte: u8, haystack: &[u8]) -> impl Iterator<Item = usize> + '_ {
    haystack
        .iter()
        .enumerate()
        .filter_map(move |(i, &b)| if b == byte { Some(i) } else { None })
}

/// Example record processor:
/// Parse lines of the form:
///   key,value,timestamp
///
/// This function avoids allocation unless UTF-8 conversion is needed externally.
fn process_csv_like_record(record: &[u8]) {
    let mut fields = record.split(|&b| b == b',');

    let key = fields.next().unwrap_or(&[]);
    let value = fields.next().unwrap_or(&[]);
    let ts = fields.next().unwrap_or(&[]);

    // Example: lightweight processing without allocating strings.
    // In real systems, parse integers/floats directly from bytes if possible.
    println!(
        "key={:?}, value={:?}, ts={:?}",
        String::from_utf8_lossy(key),
        String::from_utf8_lossy(value),
        String::from_utf8_lossy(ts)
    );
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingLineParser::<{ 1024 * 1024 }>::new();
    parser.parse(reader, |record| {
        process_csv_like_record(record);
    })?;

    Ok(())
}
```

