## More generic framed parser

If your data is not line-delimited but instead uses a custom framing format, here is a reusable pattern.

This version parses records with:

- 4-byte little-endian length prefix
- followed by payload bytes

It handles partial frames across chunk boundaries.

```rust
use std::io::{self, Read};

pub struct LengthPrefixedParser<const BUF_SIZE: usize = 1024 * 1024> {
    buf: Box<[u8; BUF_SIZE]>,
    pending: Vec<u8>,
}

impl<const BUF_SIZE: usize> LengthPrefixedParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0u8; BUF_SIZE]),
            pending: Vec::with_capacity(4096),
        }
    }

    pub fn parse<R, F>(&mut self, mut reader: R, mut on_frame: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            let n = reader.read(&mut *self.buf)?;
            if n == 0 {
                break;
            }

            self.pending.extend_from_slice(&self.buf[..n]);
            self.process_pending(&mut on_frame)?;
        }

        if !self.pending.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "trailing incomplete frame",
            ));
        }

        Ok(())
    }

    fn process_pending<F>(&mut self, on_frame: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        let mut offset = 0;

        while self.pending.len().saturating_sub(offset) >= 4 {
            let len_bytes = &self.pending[offset..offset + 4];
            let frame_len = u32::from_le_bytes([
                len_bytes[0],
                len_bytes[1],
                len_bytes[2],
                len_bytes[3],
            ]) as usize;

            let total = 4 + frame_len;
            if self.pending.len() - offset < total {
                break;
            }

            let frame = &self.pending[offset + 4..offset + total];
            on_frame(frame);
            offset += total;
        }

        if offset > 0 {
            self.pending.drain(..offset);
        }

        Ok(())
    }
}
```

