use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A parsed record view into the current line buffer.
/// Fields borrow from the parser's internal buffer, so they must be
/// consumed before the next record is read.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a str>,
}

/// High-throughput streaming parser for delimited text input.
///
/// Design goals:
/// - Minimal allocations
/// - Reuse buffers across records
/// - Avoid loading entire input into memory
/// - Process arbitrarily large files
pub struct StreamingParser<R: BufRead> {
    reader: R,
    line_buf: Vec<u8>,
    field_buf: Vec<&'static str>, // internal trick; see parse_line()
    delimiter: u8,
}

impl<R: BufRead> StreamingParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            reader,
            line_buf: Vec::with_capacity(64 * 1024),
            field_buf: Vec::with_capacity(32),
            delimiter,
        }
    }

    /// Process each record with a callback.
    ///
    /// The callback receives a Record whose field slices are valid only
    /// until the next iteration.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record) -> io::Result<()>,
    {
        loop {
            self.line_buf.clear();

            let bytes_read = self.reader.read_until(b'\n', &mut self.line_buf)?;
            if bytes_read == 0 {
                break;
            }

            // Trim trailing newline / CRLF
            while matches!(self.line_buf.last(), Some(b'\n' | b'\r')) {
                self.line_buf.pop();
            }

            let record = self.parse_line()?;
            on_record(record)?;
        }

        Ok(())
    }

    fn parse_line<'a>(&'a mut self) -> io::Result<Record<'a>> {
        self.field_buf.clear();

        let bytes = &self.line_buf;
        let mut start = 0;

        for i in 0..=bytes.len() {
            if i == bytes.len() || bytes[i] == self.delimiter {
                let slice = &bytes[start..i];
                let s = std::str::from_utf8(slice).map_err(|e| {
                    io::Error::new(io::ErrorKind::InvalidData, format!("UTF-8 error: {e}"))
                })?;

                // SAFETY:
                // We store references into self.line_buf and return them immediately
                // in Record<'a>. field_buf is cleared before next parse_line call.
                let s_static: &'static str = unsafe { std::mem::transmute::<&str, &'static str>(s) };
                self.field_buf.push(s_static);

                start = i + 1;
            }
        }

        let fields: Vec<&'a str> = self
            .field_buf
            .iter()
            .map(|s| unsafe { std::mem::transmute::<&str, &'a str>(*s) })
            .collect();

        Ok(Record { fields })
    }
}

/// Example record processor that avoids storing all records in memory.
fn process_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file); // 1MB buffer
    let mut parser = StreamingParser::new(reader, b',');

    let mut row_count: u64 = 0;
    let mut total_fields: u64 = 0;

    parser.parse(|record| {
        row_count += 1;
        total_fields += record.fields.len() as u64;

        // Example processing:
        // if let Some(first) = record.fields.get(0) {
        //     do_something(first);
        // }

        if row_count % 1_000_000 == 0 {
            eprintln!("Processed {} rows...", row_count);
        }

        Ok(())
    })?;

    println!("Done. Rows: {}, Total fields: {}", row_count, total_fields);
    Ok(())
}

fn main() -> io::Result<()> {
    process_file("large_input.csv")
}
```

