pub struct StreamingParser<R: BufRead> {
    reader: R,
    line_buf: Vec<u8>,
    delimiter: u8,
}

impl<R: BufRead> StreamingParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            reader,
            line_buf: Vec::with_capacity(64 * 1024),
            delimiter,
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record) -> io::Result<()>,
    {
        loop {
            self.line_buf.clear();

            let bytes_read = self.reader.read_until(b'\n', &mut self.line_buf)?;
            if bytes_read == 0 {
                break;
            }

            while matches!(self.line_buf.last(), Some(b'\n' | b'\r')) {
                self.line_buf.pop();
            }

            let record = self.parse_line()?;
            on_record(record)?;
        }

        Ok(())
    }

    fn parse_line<'a>(&'a self) -> io::Result<Record<'a>> {
        let bytes = &self.line_buf;
        let mut fields = Vec::with_capacity(16);
        let mut start = 0;

        for i in 0..=bytes.len() {
            if i == bytes.len() || bytes[i] == self.delimiter {
                let slice = &bytes[start..i];
                let s = std::str::from_utf8(slice).map_err(|e| {
                    io::Error::new(io::ErrorKind::InvalidData, format!("UTF-8 error: {e}"))
                })?;
                fields.push(s);
                start = i + 1;
            }
        }

        Ok(Record { fields })
    }
}

fn process_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);
    let mut parser = StreamingParser::new(reader, b',');

    let mut row_count = 0u64;

    parser.parse(|record| {
        row_count += 1;

        if row_count % 1_000_000 == 0 {
            eprintln!("Processed {} rows", row_count);
        }

        // Process fields here

        Ok(())
    })?;

    println!("Finished: {} rows", row_count);
    Ok(())
}

fn main() -> io::Result<()> {
    process_file("large_input.csv")
}
