## Ultra-fast chunk-scanning version

This version avoids `read_until` and scans the buffered reader directly using `fill_buf()` and `consume()`.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};

pub struct ChunkParser<R: BufRead> {
    reader: R,
    carry: Vec<u8>,
    delimiter: u8,
}

impl<R: BufRead> ChunkParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            reader,
            carry: Vec::with_capacity(64 * 1024),
            delimiter,
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[&[u8]]) -> io::Result<()>,
    {
        let mut fields: Vec<&[u8]> = Vec::with_capacity(32);

        loop {
            let buf = self.reader.fill_buf()?;
            if buf.is_empty() {
                if !self.carry.is_empty() {
                    Self::process_line(&self.carry, self.delimiter, &mut fields, &mut on_record)?;
                    self.carry.clear();
                }
                break;
            }

            let mut start = 0;
            for i in 0..buf.len() {
                if buf[i] == b'\n' {
                    if self.carry.is_empty() {
                        let line = &buf[start..i];
                        Self::process_line(line, self.delimiter, &mut fields, &mut on_record)?;
                    } else {
                        self.carry.extend_from_slice(&buf[start..i]);
                        Self::process_line(&self.carry, self.delimiter, &mut fields, &mut on_record)?;
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < buf.len() {
                self.carry.extend_from_slice(&buf[start..]);
            }

            let consumed = buf.len();
            self.reader.consume(consumed);
        }

        Ok(())
    }

    fn process_line<F>(
        line: &[u8],
        delimiter: u8,
        fields: &mut Vec<&[u8]>,
        on_record: &mut F,
    ) -> io::Result<()>
    where
        F: FnMut(&[&[u8]]) -> io::Result<()>,
    {
        fields.clear();

        let line = if line.ends_with(b"\r") {
            &line[..line.len() - 1]
        } else {
            line
        };

        let mut start = 0;
        for i in 0..=line.len() {
            if i == line.len() || line[i] == delimiter {
                fields.push(&line[start..i]);
                start = i + 1;
            }
        }

        on_record(fields)
    }
}

fn main() -> io::Result<()> {
    let file = File::open("large_input.csv")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);
    let mut parser = ChunkParser::new(reader, b',');

    let mut rows = 0u64;
    parser.parse(|fields| {
        rows += 1;
        if rows % 1_000_000 == 0 {
            eprintln!("Processed {}", rows);
        }

        // Example: access first field as bytes
        // if let Some(first) = fields.get(0) { ... }

        Ok(())
    })?;

    println!("Rows processed: {}", rows);
    Ok(())
}
