## 1. High-throughput streaming parser in Rust

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Represents a parsed record from a line like:
/// timestamp|user_id|event_type|value
#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a str,
    user_id: u64,
    event_type: &'a str,
    value: f64,
}

/// Parse a single line without unnecessary allocations.
/// Returns None if the line is malformed.
fn parse_line(line: &str) -> Option<Record<'_>> {
    let mut parts = line.trim_end_matches('\n').split('|');

    let timestamp = parts.next()?;
    let user_id = parts.next()?.parse().ok()?;
    let event_type = parts.next()?;
    let value = parts.next()?.parse().ok()?;

    // Reject extra fields if strict parsing is desired
    if parts.next().is_some() {
        return None;
    }

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

/// Process records in a streaming fashion.
/// `on_record` is called for each successfully parsed record.
fn process_file<P, F>(path: P, mut on_record: F) -> io::Result<()>
where
    P: AsRef<Path>,
    F: FnMut(Record<'_>),
{
    let file = File::open(path)?;
    // Large buffer reduces syscall overhead for huge files.
    let reader = BufReader::with_capacity(1024 * 1024, file);

    process_reader(reader, &mut on_record)
}

/// Generic streaming processor over any BufRead source.
fn process_reader<R, F>(mut reader: R, on_record: &mut F) -> io::Result<()>
where
    R: BufRead,
    F: FnMut(Record<'_>),
{
    let mut line = String::with_capacity(1024);

    loop {
        line.clear();

        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 {
            break;
        }

        if let Some(record) = parse_line(&line) {
            on_record(record);
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";

    let mut count = 0u64;
    let mut sum = 0.0f64;

    process_file(path, |record| {
        count += 1;
        sum += record.value;

        // Example lightweight processing
        if count % 1_000_000 == 0 {
            eprintln!(
                "Processed {} records; latest user_id={}, event_type={}",
                count, record.user_id, record.event_type
            );
        }
    })?;

    println!("Total records: {}", count);
    println!("Sum of values: {}", sum);

    Ok(())
}
```

