## 3. Faster version using `fill_buf()` for lower overhead

If you want even tighter control and potentially better throughput, use `BufRead::fill_buf()` and scan bytes directly. This avoids some overhead from `read_line()` and UTF-8/string handling until needed.

This version processes newline-delimited records from raw bytes.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

fn process_file_bytes<P, F>(path: P, mut on_line: F) -> io::Result<()>
where
    P: AsRef<Path>,
    F: FnMut(&[u8]),
{
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file);

    let mut carry = Vec::<u8>::with_capacity(4096);

    loop {
        let buffer = reader.fill_buf()?;
        if buffer.is_empty() {
            if !carry.is_empty() {
                on_line(&carry);
                carry.clear();
            }
            break;
        }

        let mut start = 0;
        for i in 0..buffer.len() {
            if buffer[i] == b'\n' {
                if carry.is_empty() {
                    on_line(&buffer[start..i]);
                } else {
                    carry.extend_from_slice(&buffer[start..i]);
                    on_line(&carry);
                    carry.clear();
                }
                start = i + 1;
            }
        }

        if start < buffer.len() {
            carry.extend_from_slice(&buffer[start..]);
        }

        let consumed = buffer.len();
        reader.consume(consumed);
    }

    Ok(())
}

fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    let mut n = 0u64;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn parse_f64_ascii(bytes: &[u8]) -> Option<f64> {
    std::str::from_utf8(bytes).ok()?.parse::<f64>().ok()
}

fn split4<'a>(line: &'a [u8], delim: u8) -> Option<(&'a [u8], &'a [u8], &'a [u8], &'a [u8])> {
    let mut fields = [0usize; 3];
    let mut found = 0usize;

    for (i, &b) in line.iter().enumerate() {
        if b == delim {
            if found < 3 {
                fields[found] = i;
            }
            found += 1;
        }
    }

    if found != 3 {
        return None;
    }

    let a = &line[..fields[0]];
    let b = &line[fields[0] + 1..fields[1]];
    let c = &line[fields[1] + 1..fields[2]];
    let d = &line[fields[2] + 1..];
    Some((a, b, c, d))
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";

    let mut count = 0u64;
    let mut sum = 0.0f64;

    process_file_bytes(path, |line| {
        let line = if line.ends_with(b"\r") {
            &line[..line.len() - 1]
        } else {
            line
        };

        if let Some((timestamp, user_id, event_type, value)) = split4(line, b'|') {
            let _timestamp = timestamp; // borrowed bytes
            let parsed_user_id = parse_u64_ascii(user_id);
            let parsed_value = parse_f64_ascii(value);

            if parsed_user_id.is_some() && parsed_value.is_some() {
                count += 1;
                sum += parsed_value.unwrap();

                if count % 1_000_000 == 0 {
                    eprintln!(
                        "Processed {} records; user_id={}, event_type={}",
                        count,
                        parsed_user_id.unwrap(),
                        String::from_utf8_lossy(event_type)
                    );
                }
            }
        }
    })?;

    println!("Total records: {}", count);
    println!("Sum of values: {}", sum);

    Ok(())
}
```

