## 5. If your input is not line-based

For binary protocols or arbitrary chunked formats, use a **state machine parser** over chunks.

Example skeleton:

```rust
use std::io::{self, Read, BufReader};
use std::fs::File;

struct Parser {
    buffer: Vec<u8>,
}

impl Parser {
    fn new() -> Self {
        Self {
            buffer: Vec::with_capacity(64 * 1024),
        }
    }

    /// Feed new bytes into the parser.
    /// Parse as many complete messages as possible.
    fn feed<F>(&mut self, data: &[u8], mut on_message: F)
    where
        F: FnMut(&[u8]),
    {
        self.buffer.extend_from_slice(data);

        let mut offset = 0usize;

        loop {
            // Example protocol:
            // [4-byte little-endian length][payload]
            if self.buffer.len() - offset < 4 {
                break;
            }

            let len_bytes = &self.buffer[offset..offset + 4];
            let msg_len = u32::from_le_bytes([
                len_bytes[0],
                len_bytes[1],
                len_bytes[2],
                len_bytes[3],
            ]) as usize;

            if self.buffer.len() - offset < 4 + msg_len {
                break;
            }

            let payload_start = offset + 4;
            let payload_end = payload_start + msg_len;
            on_message(&self.buffer[payload_start..payload_end]);

            offset = payload_end;
        }

        if offset > 0 {
            self.buffer.drain(..offset);
        }
    }
}

fn main() -> io::Result<()> {
    let file = File::open("input.bin")?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file);
    let mut parser = Parser::new();

    let mut chunk = vec![0u8; 64 * 1024];

    loop {
        let n = reader.read(&mut chunk)?;
        if n == 0 {
            break;
        }

        parser.feed(&chunk[..n], |message| {
            // Process each complete message
            println!("Message of {} bytes", message.len());
        });
    }

    Ok(())
}
```

