## 8. Production-ready version with `memchr`

```rust
use memchr::memchr_iter;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn process_fast<F>(path: &str, mut on_line: F) -> io::Result<()>
where
    F: FnMut(&[u8]),
{
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file);
    let mut carry = Vec::<u8>::with_capacity(4096);

    loop {
        let buf = reader.fill_buf()?;
        if buf.is_empty() {
            if !carry.is_empty() {
                on_line(&carry);
            }
            break;
        }

        let mut start = 0;
        for end in memchr_iter(b'\n', buf) {
            if carry.is_empty() {
                on_line(&buf[start..end]);
            } else {
                carry.extend_from_slice(&buf[start..end]);
                on_line(&carry);
                carry.clear();
            }
            start = end + 1;
        }

        if start < buf.len() {
            carry.extend_from_slice(&buf[start..]);
        }

        let len = buf.len();
        reader.consume(len);
    }

    Ok(())
}
