## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

/// High-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid loading the whole file into memory
/// - Handle records spanning multiple buffer fills
/// - Process records immediately via callback
///
/// This parser yields each line as raw bytes (`&[u8]`) when possible.
/// If a line spans multiple chunks, it is assembled into `spill`.
pub struct StreamingLineParser<R: Read> {
    reader: R,
    buf: Box<[u8]>,
    start: usize,
    end: usize,
    spill: Vec<u8>,
}

impl<R: Read> StreamingLineParser<R> {
    /// Create a parser with a configurable internal buffer size.
    ///
    /// For high-throughput workloads, 64 KiB to 1 MiB is often a good range.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 0);
        Self {
            reader,
            buf: vec![0u8; capacity].into_boxed_slice(),
            start: 0,
            end: 0,
            spill: Vec::new(),
        }
    }

    /// Parse the stream, invoking `on_record` for each complete line.
    ///
    /// The callback receives the raw bytes of the line without the trailing '\n'.
    /// If the line ends with "\r\n", the '\r' is stripped too.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            if self.start == self.end {
                let n = self.reader.read(&mut self.buf)?;
                if n == 0 {
                    // EOF: emit any remaining partial record
                    if !self.spill.is_empty() {
                        let line = trim_cr(&self.spill);
                        on_record(line);
                        self.spill.clear();
                    }
                    return Ok(());
                }
                self.start = 0;
                self.end = n;
            }

            let chunk = &self.buf[self.start..self.end];
            let mut line_start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    let line_part = &chunk[line_start..i];

                    if self.spill.is_empty() {
                        let line = trim_cr(line_part);
                        on_record(line);
                    } else {
                        self.spill.extend_from_slice(line_part);
                        let line = trim_cr(&self.spill);
                        on_record(line);
                        self.spill.clear();
                    }

                    line_start = i + 1;
                }
            }

            // Save any trailing partial line
            if line_start < chunk.len() {
                self.spill.extend_from_slice(&chunk[line_start..]);
            }

            self.start = self.end;
        }
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(&b'\r') = line.last() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Example record processor:
/// counts lines and bytes without storing them.
fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingLineParser::with_capacity(reader, 1024 * 1024);

    let mut line_count: u64 = 0;
    let mut byte_count: u64 = 0;

    parser.parse(|record| {
        line_count += 1;
        byte_count += record.len() as u64;

        // Example: lightweight processing
        // Avoid converting to UTF-8 unless necessary for performance.
        // if let Ok(s) = std::str::from_utf8(record) {
        //     println!("{}", s);
        // }
    })?;

    println!("lines: {}", line_count);
    println!("bytes: {}", byte_count);

    Ok(())
}
```

