    spill: Vec<u8>,
}

impl<R: Read> FastStreamingLineParser<R> {
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            buf: vec![0u8; capacity].into_boxed_slice(),
            start: 0,
            end: 0,
            spill: Vec::new(),
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            if self.start == self.end {
                let n = self.reader.read(&mut self.buf)?;
                if n == 0 {
                    if !self.spill.is_empty() {
                        on_record(trim_cr(&self.spill));
                        self.spill.clear();
                    }
                    return Ok(());
                }
                self.start = 0;
                self.end = n;
            }

            let chunk = &self.buf[self.start..self.end];
            let mut last = 0;

            for nl in memchr_iter(b'\n', chunk) {
                let part = &chunk[last..nl];

                if self.spill.is_empty() {
                    on_record(trim_cr(part));
                } else {
                    self.spill.extend_from_slice(part);
                    on_record(trim_cr(&self.spill));
                    self.spill.clear();
                }

                last = nl + 1;
            }

            if last < chunk.len() {
                self.spill.extend_from_slice(&chunk[last..]);
            }

            self.start = self.end;
        }
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if line.last() == Some(&b'\r') {
        &line[..line.len() - 1]
    } else {
        line
    }
}
