## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record that borrows from the input line buffer.
/// No field allocation unless you explicitly copy data out.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a [u8]>,
}

/// Streaming parser configuration.
#[derive(Clone, Debug)]
pub struct ParserConfig {
    pub field_delimiter: u8,
    pub record_delimiter: u8,
    pub buffer_size: usize,
    pub max_record_size: usize,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            field_delimiter: b',',
            record_delimiter: b'\n',
            buffer_size: 1024 * 1024, // 1 MiB
            max_record_size: 16 * 1024 * 1024, // 16 MiB safety cap
        }
    }
}

/// High-throughput streaming parser.
/// Reads chunks from a reader, extracts records, and invokes a callback per record.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    config: ParserConfig,
    chunk: Vec<u8>,
    carry: Vec<u8>,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        let buffer_size = config.buffer_size;
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            config,
            chunk: vec![0; buffer_size],
            carry: Vec::with_capacity(4096),
        }
    }

    /// Parse the stream and invoke `on_record` for each parsed record.
    ///
    /// The callback receives a Record borrowing from an internal temporary buffer,
    /// so it must not store references beyond the callback scope.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.chunk)?;
            if n == 0 {
                break;
            }

            self.process_chunk(&self.chunk[..n], &mut on_record)?;
        }

        // Flush final partial record if present.
        if !self.carry.is_empty() {
            let record_buf = std::mem::take(&mut self.carry);
            self.handle_record(&record_buf, &mut on_record)?;
            self.carry = Vec::with_capacity(4096);
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, data: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..data.len() {
            if data[i] == self.config.record_delimiter {
                if self.carry.is_empty() {
                    // Fast path: record is fully inside this chunk.
                    let record = &data[start..i];
                    self.handle_record(record, on_record)?;
                } else {
                    // Record spans chunks.
                    self.carry.extend_from_slice(&data[start..i]);
                    let record_buf = std::mem::take(&mut self.carry);
                    self.handle_record(&record_buf, on_record)?;
                    self.carry = Vec::with_capacity(4096);
                }
                start = i + 1;
            }
        }

        // Save trailing partial record.
        if start < data.len() {
            let remaining = &data[start..];
            if self.carry.len() + remaining.len() > self.config.max_record_size {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "record exceeds max_record_size",
                ));
            }
            self.carry.extend_from_slice(remaining);
        }

        Ok(())
    }

    fn handle_record<F>(&self, record: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        let fields = split_fields(record, self.config.field_delimiter);
        on_record(Record { fields })
    }
}

/// Split a record into borrowed field slices.
/// This allocates only the Vec of field references, not field contents.
fn split_fields(mut record: &[u8], delim: u8) -> Vec<&[u8]> {
    // Trim trailing '\r' for Windows line endings.
    if let Some(b'\r') = record.last().copied() {
        record = &record[..record.len() - 1];
    }

    let mut fields = Vec::with_capacity(8);
    let mut start = 0;

    for i in 0..record.len() {
        if record[i] == delim {
            fields.push(&record[start..i]);
            start = i + 1;
        }
    }

    fields.push(&record[start..]);
    fields
}

/// Example usage: parse a file and count records / sum a numeric field.
fn main() -> io::Result<()> {
    let path = Path::new("large_input.csv");
    let file = File::open(path)?;

    let config = ParserConfig {
        field_delimiter: b',',
        record_delimiter: b'\n',
        buffer_size: 4 * 1024 * 1024, // 4 MiB
        max_record_size: 64 * 1024 * 1024,
    };

    let mut parser = StreamingParser::new(file, config);

    let mut record_count: u64 = 0;
    let mut numeric_sum: u64 = 0;

    parser.parse(|record| {
        record_count += 1;

        // Example: sum field[2] if present and numeric.
        if let Some(field) = record.fields.get(2) {
            if let Ok(s) = std::str::from_utf8(field) {
                if let Ok(v) = s.trim().parse::<u64>() {
                    numeric_sum += v;
                }
            }
        }

        Ok(())
    })?;

    println!("records: {}", record_count);
    println!("sum(field[2]): {}", numeric_sum);

    Ok(())
}
