## Rust implementation

```rust
use std::borrow::Cow;
use std::fs::File;
use std::io::{self, BufReader, Read};

const DEFAULT_BUF_SIZE: usize = 1024 * 1024; // 1 MiB

#[derive(Debug)]
pub struct Record<'a> {
    pub timestamp: u64,
    pub device_id: Cow<'a, str>,
    pub value: f64,
}

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    Utf8(std::str::Utf8Error),
    InvalidFormat,
    InvalidTimestamp,
    InvalidValue,
}

impl From<io::Error> for ParseError {
    fn from(e: io::Error) -> Self {
        ParseError::Io(e)
    }
}

impl From<std::str::Utf8Error> for ParseError {
    fn from(e: std::str::Utf8Error) -> Self {
        ParseError::Utf8(e)
    }
}

/// High-throughput streaming parser for newline-delimited records.
/// Designed to minimize allocations and handle records split across buffer boundaries.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            buf: vec![0; capacity],
            carry: Vec::with_capacity(1024),
            start: 0,
            end: 0,
            eof: false,
        }
    }

    pub fn new(reader: R) -> Self {
        Self::with_capacity(reader, DEFAULT_BUF_SIZE)
    }

    fn refill(&mut self) -> Result<(), ParseError> {
        if self.eof {
            return Ok(());
        }

        self.start = 0;
        let n = self.reader.read(&mut self.buf)?;
        self.end = n;

        if n == 0 {
            self.eof = true;
        }

        Ok(())
    }

    /// Returns the next raw line as bytes.
    /// Uses zero-copy slices when the line is fully inside the current buffer.
    /// Uses `carry` only when a line spans multiple chunks.
    fn next_line_bytes<'a>(&'a mut self) -> Result<Option<Cow<'a, [u8]>>, ParseError> {
        loop {
            if self.start >= self.end {
                self.refill()?;
                if self.start >= self.end {
                    if self.carry.is_empty() {
                        return Ok(None);
                    } else {
                        let line = std::mem::take(&mut self.carry);
                        return Ok(Some(Cow::Owned(line)));
                    }
                }
            }

            let slice = &self.buf[self.start..self.end];
            if let Some(pos) = memchr::memchr(b'\n', slice) {
                let line_end = self.start + pos;
                let mut line = &self.buf[self.start..line_end];
                self.start = line_end + 1;

                if !self.carry.is_empty() {
                    self.carry.extend_from_slice(line);
                    let owned = std::mem::take(&mut self.carry);
                    return Ok(Some(Cow::Owned(trim_cr_owned(owned))));
                } else {
                    line = trim_cr(line);
                    return Ok(Some(Cow::Borrowed(line)));
                }
            } else {
                self.carry.extend_from_slice(slice);
                self.start = self.end;
            }
        }
    }

    pub fn next_record<'a>(&'a mut self) -> Result<Option<Record<'a>>, ParseError> {
        let line = match self.next_line_bytes()? {
            Some(line) => line,
            None => return Ok(None),
        };

        parse_record(line)
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if line.last() == Some(&b'\r') {
        &line[..line.len() - 1]
    } else {
        line
    }
}

fn trim_cr_owned(mut line: Vec<u8>) -> Vec<u8> {
    if line.last() == Some(&b'\r') {
        line.pop();
    }
    line
}

fn parse_record<'a>(line: Cow<'a, [u8]>) -> Result<Option<Record<'a>>, ParseError> {
    if line.is_empty() {
        return Ok(None);
    }

    let bytes = line.as_ref();

    let first_comma = memchr::memchr(b',', bytes).ok_or(ParseError::InvalidFormat)?;
    let second_comma = memchr::memchr(b',', &bytes[first_comma + 1..])
        .map(|p| p + first_comma + 1)
        .ok_or(ParseError::InvalidFormat)?;

    let ts_bytes = &bytes[..first_comma];
    let dev_bytes = &bytes[first_comma + 1..second_comma];
    let val_bytes = &bytes[second_comma + 1..];

    let timestamp = parse_u64(ts_bytes).ok_or(ParseError::InvalidTimestamp)?;
    let value = parse_f64(val_bytes).ok_or(ParseError::InvalidValue)?;

    let device_id = match line {
        Cow::Borrowed(_) => Cow::Borrowed(std::str::from_utf8(dev_bytes)?),
        Cow::Owned(ref owned) => {
            let start = first_comma + 1;
            let end = second_comma;
            let s = std::str::from_utf8(&owned[start..end])?.to_owned();
            Cow::Owned(s)
        }
    };

    Ok(Some(Record {
        timestamp,
        device_id,
        value,
    }))
}

fn parse_u64(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut n = 0u64;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn parse_f64(bytes: &[u8]) -> Option<f64> {
    let s = std::str::from_utf8(bytes).ok()?;
    s.parse::<f64>().ok()
}

fn main() -> Result<(), ParseError> {
    let file = File::open("data.csv")?;
    let reader = BufReader::with_capacity(DEFAULT_BUF_SIZE, file);
    let mut parser = StreamingParser::new(reader);

    let mut count = 0usize;
    let mut sum = 0.0f64;

    while let Some(record) = parser.next_record()? {
        count += 1;
        sum += record.value;

        // Process record here without storing all records in memory.
        // Example:
        // println!("{:?}", record);
    }

    println!("Processed {} records, sum={}", count, sum);
    Ok(())
}
```

