use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A parsed record borrowing from the input buffer where possible.
/// This avoids unnecessary allocations for string fields.
#[derive(Debug)]
struct Record<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a str,
    value: i64,
}

/// Parse a single CSV-like line:
/// timestamp,user_id,event_type,value
///
/// Returns None if the line is malformed.
fn parse_line(line: &str) -> Option<Record<'_>> {
    let mut parts = line.trim_end_matches(&['\n', '\r'][..]).split(',');

    let timestamp = parts.next()?.parse().ok()?;
    let user_id = parts.next()?.parse().ok()?;
    let event_type = parts.next()?;
    let value = parts.next()?.parse().ok()?;

    // Reject extra columns
    if parts.next().is_some() {
        return None;
    }

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

/// Process a parsed record.
/// Replace this with your actual business logic.
fn handle_record(record: &Record) {
    // Example: lightweight processing
    // Avoid println! in real high-throughput paths unless necessary.
    let _ = (
        record.timestamp,
        record.user_id,
        record.event_type,
        record.value,
    );
}

/// High-throughput streaming parser:
/// - Uses a large buffered reader
/// - Reuses a single String buffer for each line
/// - Never loads the entire file into memory
fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;

    // Tune buffer size depending on storage and workload.
    // 1-8 MiB is often a good starting point for large sequential reads.
    let reader = BufReader::with_capacity(4 * 1024 * 1024, file);

    let mut line_buf = String::with_capacity(1024);

    let mut total_lines: u64 = 0;
    let mut parsed_lines: u64 = 0;
    let mut bad_lines: u64 = 0;

    let mut reader = reader;
    loop {
        line_buf.clear();

        let bytes_read = reader.read_line(&mut line_buf)?;
        if bytes_read == 0 {
            break;
        }

        total_lines += 1;

        if let Some(record) = parse_line(&line_buf) {
            handle_record(&record);
            parsed_lines += 1;
        } else {
            bad_lines += 1;
        }
    }

    eprintln!(
        "done: total_lines={}, parsed_lines={}, bad_lines={}",
        total_lines, parsed_lines, bad_lines
    );

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    parse_file(path)
}
