# Higher-throughput version using `fill_buf`

If you want even lower overhead than `read_line`, you can parse directly from the internal byte buffer and avoid UTF-8/string handling until needed.

This version scans bytes and processes newline-delimited records from the buffered stream.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

#[derive(Debug)]
struct RecordBytes<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a [u8],
    value: i64,
}

fn parse_u64_bytes(s: &[u8]) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let mut n = 0u64;
    for &b in s {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn parse_i64_bytes(s: &[u8]) -> Option<i64> {
    if s.is_empty() {
        return None;
    }

    let (neg, digits) = if s[0] == b'-' {
        (true, &s[1..])
    } else {
        (false, s)
    };

    let v = parse_u64_bytes(digits)? as i64;
    Some(if neg { -v } else { v })
}

fn parse_record_bytes(line: &[u8]) -> Option<RecordBytes<'_>> {
    let line = if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    };
    let line = if line.ends_with(b"\r") {
        &line[..line.len() - 1]
    } else {
        line
    };

    let mut fields = [0usize; 3];
    let mut count = 0usize;

    for (i, &b) in line.iter().enumerate() {
        if b == b',' {
            if count < 3 {
                fields[count] = i;
            }
            count += 1;
        }
    }

    if count != 3 {
        return None;
    }

    let c1 = fields[0];
    let c2 = fields[1];
    let c3 = fields[2];

    let f1 = &line[..c1];
    let f2 = &line[c1 + 1..c2];
    let f3 = &line[c2 + 1..c3];
    let f4 = &line[c3 + 1..];

    Some(RecordBytes {
        timestamp: parse_u64_bytes(f1)?,
        user_id: parse_u64_bytes(f2)?,
        event_type: f3,
        value: parse_i64_bytes(f4)?,
    })
}

fn handle_record_bytes(record: &RecordBytes) {
    let _ = (
        record.timestamp,
        record.user_id,
        record.event_type,
        record.value,
    );
}

fn parse_file_fast<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(4 * 1024 * 1024, file);

    let mut carry = Vec::<u8>::with_capacity(8192);

    let mut total_lines = 0u64;
    let mut parsed_lines = 0u64;
    let mut bad_lines = 0u64;

    loop {
        let buf = reader.fill_buf()?;
        if buf.is_empty() {
            if !carry.is_empty() {
                total_lines += 1;
                if let Some(rec) = parse_record_bytes(&carry) {
                    handle_record_bytes(&rec);
                    parsed_lines += 1;
                } else {
                    bad_lines += 1;
                }
                carry.clear();
            }
            break;
        }

        let mut start = 0usize;
        for i in 0..buf.len() {
            if buf[i] == b'\n' {
                total_lines += 1;

                if carry.is_empty() {
                    let line = &buf[start..=i];
                    if let Some(rec) = parse_record_bytes(line) {
                        handle_record_bytes(&rec);
                        parsed_lines += 1;
                    } else {
                        bad_lines += 1;
                    }
                } else {
                    carry.extend_from_slice(&buf[start..=i]);
                    if let Some(rec) = parse_record_bytes(&carry) {
                        handle_record_bytes(&rec);
                        parsed_lines += 1;
                    } else {
                        bad_lines += 1;
                    }
                    carry.clear();
                }

                start = i + 1;
            }
        }

        if start < buf.len() {
            carry.extend_from_slice(&buf[start..]);
        }

        let consumed = buf.len();
        reader.consume(consumed);
    }

    eprintln!(
        "done: total_lines={}, parsed_lines={}, bad_lines={}",
        total_lines, parsed_lines, bad_lines
    );

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    parse_file_fast(path)
}
```

