```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

/// High-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid loading the whole file into memory
/// - Handle records spanning multiple buffer fills
/// - Process records immediately via callback
///
/// This parser emits each line without the trailing '\n'.
/// It also trims a trailing '\r' for CRLF compatibility.
pub struct StreamingLineParser<const BUF_SIZE: usize> {
    buf: Box<[u8; BUF_SIZE]>,
    /// Number of valid bytes currently in `buf`
    filled: usize,
    /// Current scan position within valid bytes
    scan: usize,
    /// Accumulates a line only when it spans multiple chunks
    spill: Vec<u8>,
}

impl<const BUF_SIZE: usize> StreamingLineParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0u8; BUF_SIZE]),
            filled: 0,
            scan: 0,
            spill: Vec::with_capacity(1024),
        }
    }

    /// Parse all newline-delimited records from `reader`.
    ///
    /// `on_record` is called for each parsed line as raw bytes.
    /// This avoids allocating strings unless the caller wants them.
    pub fn parse<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            // If buffer has been fully scanned, refill from start.
            if self.scan == self.filled {
                self.filled = reader.read(&mut self.buf[..])?;
                self.scan = 0;

                if self.filled == 0 {
                    // EOF: emit any remaining partial record
                    if !self.spill.is_empty() {
                        let record = trim_cr(&self.spill);
                        on_record(record);
                        self.spill.clear();
                    }
                    return Ok(());
                }
            }

            // Process as many complete lines as possible in current buffer.
            let chunk = &self.buf[self.scan..self.filled];

            if let Some(rel_pos) = memchr_nl(chunk) {
                let nl_pos = self.scan + rel_pos;
                let line = &self.buf[self.scan..nl_pos];

                if self.spill.is_empty() {
                    let record = trim_cr(line);
                    on_record(record);
                } else {
                    self.spill.extend_from_slice(line);
                    let record = trim_cr(&self.spill);
                    on_record(record);
                    self.spill.clear();
                }

                self.scan = nl_pos + 1;
            } else {
                // No newline found: append remainder to spill and force refill.
                self.spill.extend_from_slice(chunk);
                self.scan = self.filled;
            }
        }
    }
}

/// Trim trailing '\r' if present (for CRLF files)
fn trim_cr(bytes: &[u8]) -> &[u8] {
    if let Some(b'\r') = bytes.last().copied() {
        &bytes[..bytes.len() - 1]
    } else {
        bytes
    }
}

/// Fast newline search.
/// Replace with `memchr::memchr(b'\n', chunk)` for even better performance.
#[inline]
fn memchr_nl(chunk: &[u8]) -> Option<usize> {
    chunk.iter().position(|&b| b == b'\n')
}

/// Example record processor:
/// Parse each line as "key,value,timestamp" without allocating intermediate strings.
fn process_csv_like_record(record: &[u8]) {
    let mut fields = record.split(|&b| b == b',');

    let key = fields.next().unwrap_or(b"");
    let value = fields.next().unwrap_or(b"");
    let ts = fields.next().unwrap_or(b"");

    // Example: convert only when needed
    // Avoid UTF-8 conversion unless required by downstream logic
    println!(
        "key={:?}, value={:?}, ts={:?}",
        String::from_utf8_lossy(key),
        String::from_utf8_lossy(value),
        String::from_utf8_lossy(ts)
    );
}

fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingLineParser::<64 * 1024>::new();

    parser.parse(reader, |record| {
        process_csv_like_record(record);
    })?;

    Ok(())
}
```

