## More optimized version using `memchr`

```rust
use memchr::memchr;
use std::io::{self, Read};

pub struct FastLineParser<const BUF_SIZE: usize> {
    buf: Box<[u8; BUF_SIZE]>,
    filled: usize,
    scan: usize,
    spill: Vec<u8>,
}

impl<const BUF_SIZE: usize> FastLineParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0; BUF_SIZE]),
            filled: 0,
            scan: 0,
            spill: Vec::with_capacity(1024),
        }
    }

    pub fn parse<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            if self.scan == self.filled {
                self.filled = reader.read(&mut self.buf[..])?;
                self.scan = 0;

                if self.filled == 0 {
                    if !self.spill.is_empty() {
                        on_record(trim_cr(&self.spill));
                        self.spill.clear();
                    }
                    return Ok(());
                }
            }

            let chunk = &self.buf[self.scan..self.filled];
            match memchr(b'\n', chunk) {
                Some(pos) => {
                    let end = self.scan + pos;
                    let line = &self.buf[self.scan..end];

                    if self.spill.is_empty() {
                        on_record(trim_cr(line));
                    } else {
                        self.spill.extend_from_slice(line);
                        on_record(trim_cr(&self.spill));
                        self.spill.clear();
                    }

                    self.scan = end + 1;
                }
                None => {
                    self.spill.extend_from_slice(chunk);
                    self.scan = self.filled;
                }
            }
        }
    }
}

fn trim_cr(bytes: &[u8]) -> &[u8] {
    if bytes.last() == Some(&b'\r') {
        &bytes[..bytes.len() - 1]
    } else {
        bytes
    }
}
