## If you need binary framed parsing

For binary protocols with a length prefix, use this pattern:

- read into fixed buffer
- check whether enough bytes exist for header
- decode frame length
- if full frame available, process it
- otherwise compact remaining bytes and refill

Example:

```rust
use std::io::{self, Read};

pub struct LengthPrefixedParser<const BUF_SIZE: usize> {
    buf: Box<[u8; BUF_SIZE]>,
    start: usize,
    end: usize,
}

impl<const BUF_SIZE: usize> LengthPrefixedParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0; BUF_SIZE]),
            start: 0,
            end: 0,
        }
    }

    pub fn parse<R, F>(&mut self, mut reader: R, mut on_frame: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            // Try to parse as many frames as possible
            while self.end - self.start >= 4 {
                let len_bytes = &self.buf[self.start..self.start + 4];
                let frame_len = u32::from_le_bytes([
                    len_bytes[0],
                    len_bytes[1],
                    len_bytes[2],
                    len_bytes[3],
                ]) as usize;

                if frame_len > BUF_SIZE - 4 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "frame too large for buffer",
                    ));
                }

                if self.end - self.start < 4 + frame_len {
                    break;
                }

                let frame_start = self.start + 4;
                let frame_end = frame_start + frame_len;
                on_frame(&self.buf[frame_start..frame_end]);
                self.start = frame_end;
            }

            // Compact unread bytes to front if needed
            if self.start > 0 {
                let remaining = self.end - self.start;
                self.buf.copy_within(self.start..self.end, 0);
                self.start = 0;
                self.end = remaining;
            }

            // Refill
            let n = reader.read(&mut self.buf[self.end..])?;
            if n == 0 {
                if self.start != self.end {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "truncated frame at EOF",
                    ));
                }
                return Ok(());
            }
            self.end += n;
        }
    }
}
```

