```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

/// A callback-based streaming parser for newline-delimited records.
/// Each line is parsed into comma-separated fields.
///
/// Designed for:
/// - very large files
/// - minimal memory overhead
/// - handling records split across chunk boundaries
///
/// Notes:
/// - This example avoids building large intermediate structures.
/// - It reuses buffers aggressively.
/// - It only allocates when a line spans multiple chunks.
const DEFAULT_BUF_SIZE: usize = 1024 * 1024; // 1 MiB

pub struct StreamingParser<R, F>
where
    R: Read,
    F: FnMut(&[&[u8]]) -> io::Result<()>,
{
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    on_record: F,
}

impl<R, F> StreamingParser<R, F>
where
    R: Read,
    F: FnMut(&[&[u8]]) -> io::Result<()>,
{
    pub fn new(reader: R, buf_size: usize, on_record: F) -> Self {
        Self {
            reader: BufReader::with_capacity(buf_size, reader),
            buf: vec![0; buf_size],
            carry: Vec::new(),
            on_record,
        }
    }

    pub fn parse(&mut self) -> io::Result<()> {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }
            self.process_chunk(&self.buf[..n])?;
        }

        // Flush any remaining partial record at EOF
        if !self.carry.is_empty() {
            self.process_line_owned()?;
        }

        Ok(())
    }

    fn process_chunk(&mut self, chunk: &[u8]) -> io::Result<()> {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: line is fully contained in this chunk
                    let line = &chunk[start..i];
                    self.process_line(line)?;
                } else {
                    // Slow path: line spans chunk boundary
                    self.carry.extend_from_slice(&chunk[start..i]);
                    self.process_line_owned()?;
                }
                start = i + 1;
            }
        }

        // Save trailing partial line
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    fn process_line_owned(&mut self) -> io::Result<()> {
        // Trim optional CR for Windows line endings
        if self.carry.last() == Some(&b'\r') {
            self.carry.pop();
        }

        let fields = split_fields(&self.carry);
        (self.on_record)(&fields)?;
        self.carry.clear();
        Ok(())
    }

    fn process_line(&mut self, line: &[u8]) -> io::Result<()> {
        let line = if line.last() == Some(&b'\r') {
            &line[..line.len() - 1]
        } else {
            line
        };

        let fields = split_fields(line);
        (self.on_record)(&fields)
    }
}

/// Split a line on commas without allocating field contents.
/// Returns slices into the original line buffer.
///
/// This is a simple parser:
/// - no quoted fields
/// - no escaping
/// - suitable for high-throughput simple delimited formats
fn split_fields(line: &[u8]) -> Vec<&[u8]> {
    let mut fields = Vec::with_capacity(16);
    let mut start = 0;

    for i in 0..line.len() {
        if line[i] == b',' {
            fields.push(&line[start..i]);
            start = i + 1;
        }
    }

    fields.push(&line[start..]);
    fields
}

/// Example consumer that counts records and sums a numeric field.
fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;

    let mut record_count: u64 = 0;
    let mut sum_field_2: u64 = 0;

    let mut parser = StreamingParser::new(file, DEFAULT_BUF_SIZE, |fields| {
        record_count += 1;

        // Example: sum the 2nd field if present and numeric
        if fields.len() > 1 {
            if let Ok(s) = std::str::from_utf8(fields[1]) {
                if let Ok(v) = s.trim().parse::<u64>() {
                    sum_field_2 += v;
                }
            }
        }

        Ok(())
    });

    parser.parse()?;

    println!("records={}", record_count);
    println!("sum_field_2={}", sum_field_2);

    Ok(())
}
```

