# Lower-allocation version using a field iterator

This version avoids allocating a `Vec` for fields.

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

const DEFAULT_BUF_SIZE: usize = 1024 * 1024;

pub struct StreamingParser<R, F>
where
    R: Read,
    F: FnMut(FieldIter<'_>) -> io::Result<()>,
{
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    on_record: F,
}

impl<R, F> StreamingParser<R, F>
where
    R: Read,
    F: FnMut(FieldIter<'_>) -> io::Result<()>,
{
    pub fn new(reader: R, buf_size: usize, on_record: F) -> Self {
        Self {
            reader: BufReader::with_capacity(buf_size, reader),
            buf: vec![0; buf_size],
            carry: Vec::new(),
            on_record,
        }
    }

    pub fn parse(&mut self) -> io::Result<()> {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }
            self.process_chunk(&self.buf[..n])?;
        }

        if !self.carry.is_empty() {
            self.process_line_owned()?;
        }

        Ok(())
    }

    fn process_chunk(&mut self, chunk: &[u8]) -> io::Result<()> {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    let line = &chunk[start..i];
                    self.process_line(line)?;
                } else {
                    self.carry.extend_from_slice(&chunk[start..i]);
                    self.process_line_owned()?;
                }
                start = i + 1;
            }
        }

        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    fn process_line_owned(&mut self) -> io::Result<()> {
        if self.carry.last() == Some(&b'\r') {
            self.carry.pop();
        }

        let iter = FieldIter::new(&self.carry);
        (self.on_record)(iter)?;
        self.carry.clear();
        Ok(())
    }

    fn process_line(&mut self, line: &[u8]) -> io::Result<()> {
        let line = if line.last() == Some(&b'\r') {
            &line[..line.len() - 1]
        } else {
            line
        };

        let iter = FieldIter::new(line);
        (self.on_record)(iter)
    }
}

pub struct FieldIter<'a> {
    line: &'a [u8],
    pos: usize,
    done: bool,
}

impl<'a> FieldIter<'a> {
    pub fn new(line: &'a [u8]) -> Self {
        Self {
            line,
            pos: 0,
            done: false,
        }
    }
}

impl<'a> Iterator for FieldIter<'a> {
    type Item = &'a [u8];

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }

        let start = self.pos;

        while self.pos < self.line.len() && self.line[self.pos] != b',' {
            self.pos += 1;
        }

        let field = &self.line[start..self.pos];

        if self.pos < self.line.len() {
            self.pos += 1; // skip comma
        } else {
            self.done = true;
        }

        if self.pos >= self.line.len() && start == self.line.len() {
            self.done = true;
        }

        Some(field)
    }
}

fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;

    let mut records = 0u64;
    let mut sum = 0u64;

    let mut parser = StreamingParser::new(file, DEFAULT_BUF_SIZE, |fields| {
        records += 1;

        for (idx, field) in fields.enumerate() {
            if idx == 1 {
                if let Ok(s) = std::str::from_utf8(field) {
                    if let Ok(v) = s.trim().parse::<u64>() {
                        sum += v;
                    }
                }
                break;
            }
        }

        Ok(())
    });

    parser.parse()?;

    println!("records={records}");
    println!("sum={sum}");
    Ok(())
}
