Here is a faster delimiter scan version:

```rust
use memchr::memchr_iter;
use std::fs::File;
use std::io::{self, BufReader, Read};

const DEFAULT_BUF_SIZE: usize = 1024 * 1024;

pub struct StreamingParser<R, F>
where
    R: Read,
    F: FnMut(&[u8]) -> io::Result<()>,
{
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    on_line: F,
}

impl<R, F> StreamingParser<R, F>
where
    R: Read,
    F: FnMut(&[u8]) -> io::Result<()>,
{
    pub fn new(reader: R, buf_size: usize, on_line: F) -> Self {
        Self {
            reader: BufReader::with_capacity(buf_size, reader),
            buf: vec![0; buf_size],
            carry: Vec::new(),
            on_line,
        }
    }

    pub fn parse(&mut self) -> io::Result<()> {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }
            self.process_chunk(&self.buf[..n])?;
        }

        if !self.carry.is_empty() {
            self.emit_owned_line()?;
        }

        Ok(())
    }

    fn process_chunk(&mut self, chunk: &[u8]) -> io::Result<()> {
        let mut start = 0;

        for nl in memchr_iter(b'\n', chunk) {
            if self.carry.is_empty() {
                self.emit_line(&chunk[start..nl])?;
            } else {
                self.carry.extend_from_slice(&chunk[start..nl]);
                self.emit_owned_line()?;
            }
            start = nl + 1;
        }

        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    fn emit_owned_line(&mut self) -> io::Result<()> {
        if self.carry.last() == Some(&b'\r') {
            self.carry.pop();
        }
        (self.on_line)(&self.carry)?;
        self.carry.clear();
        Ok(())
    }

    fn emit_line(&mut self, line: &[u8]) -> io::Result<()> {
        let line = if line.last() == Some(&b'\r') {
            &line[..line.len() - 1]
        } else {
            line
        };
        (self.on_line)(line)
    }
}

