## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// High-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Minimal allocations
/// - Reusable fixed-size buffer
/// - Handles records spanning multiple buffer reads
/// - Callback-based processing to avoid accumulating parsed output in memory
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Box<[u8]>,
    carry: Vec<u8>,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a configurable buffer size.
    ///
    /// For high-throughput workloads, 64 KiB to 1 MiB are common good starting points.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0, "buffer_size must be > 0");
        Self {
            reader,
            buf: vec![0u8; buffer_size].into_boxed_slice(),
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse newline-delimited records and invoke `on_record` for each complete line.
    ///
    /// `on_record` receives the raw bytes of the line excluding the trailing '\n'.
    /// If the input uses CRLF, trailing '\r' is stripped.
    ///
    /// This function avoids copying for records fully contained in the current read buffer.
    /// Only records split across chunk boundaries are accumulated into `carry`.
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    if self.carry.is_empty() {
                        let line = trim_cr(&chunk[start..i]);
                        on_record(line)?;
                    } else {
                        self.carry.extend_from_slice(&chunk[start..i]);
                        let line = trim_cr(&self.carry);
                        on_record(line)?;
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        // Emit final unterminated line if present
        if !self.carry.is_empty() {
            let line = trim_cr(&self.carry);
            on_record(line)?;
            self.carry.clear();
        }

        Ok(())
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(b'\r') = line.last().copied() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Example record parser:
/// Parse lines of the form:
///   key,value,timestamp
///
/// This avoids allocating Strings unless you choose to.
/// It parses directly from bytes.
#[derive(Debug)]
struct Record<'a> {
    key: &'a [u8],
    value: &'a [u8],
    timestamp: u64,
}

fn parse_csv_like_record(line: &[u8]) -> Option<Record<'_>> {
    let mut parts = line.splitn(3, |&b| b == b',');
    let key = parts.next()?;
    let value = parts.next()?;
    let ts_bytes = parts.next()?;

    let timestamp = parse_u64_ascii(ts_bytes)?;
    Some(Record {
        key,
        value,
        timestamp,
    })
}

fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut n: u64 = 0;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::new(reader, 1024 * 1024);

    let mut count: u64 = 0;
    let mut bad: u64 = 0;

    parser.parse_lines(|line| {
        if let Some(record) = parse_csv_like_record(line) {
            // Process immediately; do not store all records.
            // Example: aggregate, filter, write to another stream, etc.
            let _ = record.key;
            let _ = record.value;
            let _ = record.timestamp;
            count += 1;
        } else {
            bad += 1;
        }
        Ok(())
    })?;

    eprintln!("parsed records: {}", count);
    eprintln!("bad records: {}", bad);

    Ok(())
}
