## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming line parser.
///
/// Features:
/// - Reuses a fixed-size read buffer
/// - Avoids loading the whole file into memory
/// - Handles lines split across chunk boundaries
/// - Processes records incrementally via callback
///
/// Suitable for:
/// - log processing
/// - NDJSON
/// - line-oriented protocols
/// - large text datasets
pub struct StreamingLineParser<const BUF_SIZE: usize = 1024 * 1024> {
    buf: Box<[u8; BUF_SIZE]>,
    carry: Vec<u8>,
}

impl<const BUF_SIZE: usize> StreamingLineParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0u8; BUF_SIZE]),
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse from any reader.
    ///
    /// `on_record` is called for each complete line without the trailing '\n'.
    /// If the input ends without a trailing newline, the final partial line is emitted too.
    pub fn parse<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            let n = reader.read(&mut *self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            self.process_chunk(chunk, &mut on_record);
        }

        if !self.carry.is_empty() {
            on_record(&self.carry);
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F)
    where
        F: FnMut(&[u8]),
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: line fully inside current chunk
                    let mut line = &chunk[start..i];
                    if let Some(stripped) = strip_trailing_cr(line) {
                        line = stripped;
                    }
                    on_record(line);
                } else {
                    // Slow path: line spans previous chunk(s)
                    self.carry.extend_from_slice(&chunk[start..i]);
                    let mut line = self.carry.as_slice();
                    if let Some(stripped) = strip_trailing_cr(line) {
                        line = stripped;
                    }
                    on_record(line);
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        // Save trailing partial line
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }
    }
}

fn strip_trailing_cr(line: &[u8]) -> Option<&[u8]> {
    if line.last() == Some(&b'\r') {
        Some(&line[..line.len() - 1])
    } else {
        None
    }
}

/// Example record parser:
/// parse "timestamp,level,message"
#[derive(Debug)]
struct LogRecord<'a> {
    timestamp: &'a [u8],
    level: &'a [u8],
    message: &'a [u8],
}

fn parse_csv3_line(line: &[u8]) -> Option<LogRecord<'_>> {
    let mut parts = line.splitn(3, |&b| b == b',');
    let timestamp = parts.next()?;
    let level = parts.next()?;
    let message = parts.next()?;
    Some(LogRecord {
        timestamp,
        level,
        message,
    })
}

pub fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingLineParser::<{ 1024 * 1024 }>::new();

    let mut count: u64 = 0;
    let mut errors: u64 = 0;

    parser.parse(reader, |line| {
        if let Some(record) = parse_csv3_line(line) {
            // Process immediately; do not store all records.
            // Example lightweight work:
            let _ = record.timestamp;
            let _ = record.level;
            let _ = record.message;
            count += 1;
        } else {
            errors += 1;
        }
    })?;

    eprintln!("parsed={}, errors={}", count, errors);
    Ok(())
}

fn main() -> io::Result<()> {
    parse_file("large_input.log")
}
```

