## Example: length-prefixed binary frame parser

This parses records of the form:

- 4-byte little-endian length
- followed by payload bytes

```rust
use std::io::{self, Read};

pub struct LengthPrefixedParser<const BUF_SIZE: usize = 1024 * 1024> {
    buf: Box<[u8; BUF_SIZE]>,
    carry: Vec<u8>,
}

impl<const BUF_SIZE: usize> LengthPrefixedParser<BUF_SIZE> {
    pub fn new() -> Self {
        Self {
            buf: Box::new([0u8; BUF_SIZE]),
            carry: Vec::with_capacity(4096),
        }
    }

    pub fn parse<R, F>(&mut self, mut reader: R, mut on_frame: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]),
    {
        loop {
            let n = reader.read(&mut *self.buf)?;
            if n == 0 {
                break;
            }

            self.carry.extend_from_slice(&self.buf[..n]);
            self.process_carry(&mut on_frame)?;
        }

        if !self.carry.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "incomplete trailing frame",
            ));
        }

        Ok(())
    }

    fn process_carry<F>(&mut self, on_frame: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        let mut offset = 0;

        while self.carry.len().saturating_sub(offset) >= 4 {
            let len_bytes = &self.carry[offset..offset + 4];
            let frame_len = u32::from_le_bytes([
                len_bytes[0],
                len_bytes[1],
                len_bytes[2],
                len_bytes[3],
            ]) as usize;

            let total = 4 + frame_len;
            if self.carry.len().saturating_sub(offset) < total {
                break;
            }

            let payload = &self.carry[offset + 4..offset + total];
            on_frame(payload);
            offset += total;
        }

        if offset > 0 {
            self.carry.drain(..offset);
        }

        Ok(())
    }
}
```

