use std::fs::File;
use std::io::{self, BufReader, Read};

/// A parsed record view.
/// Borrowed from an internal buffer, so it is only valid during the callback.
#[derive(Debug)]
pub struct Record<'a> {
    pub line: &'a [u8],
}

/// High-throughput streaming parser for newline-delimited data.
///
/// Design goals:
/// - Read in large chunks
/// - Avoid per-line allocations
/// - Preserve partial records across chunk boundaries
/// - Process records immediately via callback
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a fixed-capacity buffer.
    ///
    /// `capacity` should be reasonably large for throughput, e.g. 64 KiB to several MiB.
    pub fn new(reader: R, capacity: usize) -> Self {
        let mut buf = Vec::with_capacity(capacity);
        buf.resize(capacity, 0);
        Self {
            reader,
            buf,
            start: 0,
            end: 0,
        }
    }

    /// Parse all records and invoke `on_record` for each one.
    ///
    /// The callback receives a borrowed slice valid only during the callback.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            // First, process any complete lines already in the buffer.
            while let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let line_end = self.start + pos;
                let mut line = &self.buf[self.start..line_end];

                // Trim trailing '\r' for CRLF support.
                if let Some(b'\r') = line.last().copied() {
                    line = &line[..line.len() - 1];
                }

                on_record(Record { line })?;
                self.start = line_end + 1;
            }

            // If buffer fully consumed, reset indices.
            if self.start == self.end {
                self.start = 0;
                self.end = 0;
            }

            // If buffer has unprocessed partial data at the end, compact it to the front.
            if self.end == self.buf.len() {
                if self.start > 0 {
                    let remaining = self.end - self.start;
                    self.buf.copy_within(self.start..self.end, 0);
                    self.start = 0;
                    self.end = remaining;
                } else {
                    // Buffer is full and no newline found: record exceeds buffer capacity.
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "record exceeds parser buffer capacity",
                    ));
                }
            }

            // Read more data into available space.
            let n = self.reader.read(&mut self.buf[self.end..])?;
            if n == 0 {
                // EOF: emit trailing partial line if present.
                if self.start < self.end {
                    let mut line = &self.buf[self.start..self.end];
                    if let Some(b'\r') = line.last().copied() {
                        line = &line[..line.len() - 1];
                    }
                    on_record(Record { line })?;
                }
                return Ok(());
            }
            self.end += n;
        }
    }
}

fn main() -> io::Result<()> {
    let file = File::open("large_input.txt")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::new(reader, 1024 * 1024);

    let mut count: u64 = 0;
