## If you need arbitrarily large records

The above version rejects a record larger than the buffer. If you need to support huge individual records, use a spillover buffer only when necessary.

Here is a variant that supports oversized records while still keeping normal-case memory low:

```rust
use std::io::{self, Read};

pub struct LargeRecordParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    overflow: Vec<u8>,
}

impl<R: Read> LargeRecordParser<R> {
    pub fn new(reader: R, capacity: usize) -> Self {
        let mut buf = Vec::with_capacity(capacity);
        buf.resize(capacity, 0);
        Self {
            reader,
            buf,
            start: 0,
            end: 0,
            overflow: Vec::new(),
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            while let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let line_end = self.start + pos;
                let line = &self.buf[self.start..line_end];

                if self.overflow.is_empty() {
                    let line = trim_cr(line);
                    on_record(line)?;
                } else {
                    self.overflow.extend_from_slice(line);
                    let line = trim_cr(&self.overflow);
                    on_record(line)?;
                    self.overflow.clear();
                }

                self.start = line_end + 1;
            }

            if self.start == self.end {
                self.start = 0;
                self.end = 0;
            }

            if self.end == self.buf.len() {
                if self.start > 0 {
                    let remaining = self.end - self.start;
                    if !self.overflow.is_empty() {
                        self.overflow.extend_from_slice(&self.buf[self.start..self.end]);
                    }
                    self.buf.copy_within(self.start..self.end, 0);
                    self.start = 0;
                    self.end = remaining;
                } else {
                    // Entire buffer is one partial record segment
                    self.overflow.extend_from_slice(&self.buf[..self.end]);
                    self.start = 0;
                    self.end = 0;
                }
            }

            let n = self.reader.read(&mut self.buf[self.end..])?;
            if n == 0 {
                if self.start < self.end {
                    if self.overflow.is_empty() {
                        on_record(trim_cr(&self.buf[self.start..self.end]))?;
                    } else {
                        self.overflow.extend_from_slice(&self.buf[self.start..self.end]);
                        on_record(trim_cr(&self.overflow))?;
                        self.overflow.clear();
                    }
                } else if !self.overflow.is_empty() {
                    on_record(trim_cr(&self.overflow))?;
                    self.overflow.clear();
                }
                return Ok(());
            }
            self.end += n;
        }
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(b'\r') = line.last().copied() {
        &line[..line.len() - 1]
    } else {
        line
    }
}
```

