```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A lightweight view into a parsed record.
/// Fields borrow from the internal line buffer, so they are only valid
/// during the callback invocation.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a str>,
}

/// Streaming parser configuration.
#[derive(Debug, Clone)]
pub struct ParserConfig {
    /// Field delimiter, e.g. b',' for CSV-like data or b'\t' for TSV.
    pub delimiter: u8,

    /// Whether to skip empty lines.
    pub skip_empty_lines: bool,

    /// Whether the first line is a header and should be skipped.
    pub skip_header: bool,

    /// Maximum allowed line length to protect memory usage.
    pub max_line_len: usize,

    /// Reader buffer capacity.
    pub reader_capacity: usize,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            delimiter: b',',
            skip_empty_lines: true,
            skip_header: false,
            max_line_len: 16 * 1024 * 1024, // 16 MB safety cap per line
            reader_capacity: 1024 * 1024,   // 1 MB buffered I/O
        }
    }
}

/// Errors that can occur during parsing.
#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    LineTooLong(usize),
    InvalidUtf8(std::str::Utf8Error),
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

impl From<std::str::Utf8Error> for ParseError {
    fn from(err: std::str::Utf8Error) -> Self {
        ParseError::InvalidUtf8(err)
    }
}

/// High-throughput streaming parser.
pub struct StreamingParser<R: BufRead> {
    reader: R,
    config: ParserConfig,
    line_buf: Vec<u8>,
    field_positions: Vec<(usize, usize)>,
    line_number: usize,
}

impl<R: BufRead> StreamingParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        Self {
            reader,
            config,
            line_buf: Vec::with_capacity(8 * 1024),
            field_positions: Vec::with_capacity(32),
            line_number: 0,
        }
    }

    /// Parse the stream and invoke `on_record` for each parsed record.
    ///
    /// The callback receives a Record whose field slices are valid only
    /// for the duration of the callback.
    pub fn parse<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(usize, Record<'_>) -> Result<(), ParseError>,
    {
        loop {
            self.line_buf.clear();

            let bytes_read = self.reader.read_until(b'\n', &mut self.line_buf)?;
            if bytes_read == 0 {
                break;
            }

            self.line_number += 1;

            if self.line_buf.len() > self.config.max_line_len {
                return Err(ParseError::LineTooLong(self.line_buf.len()));
            }

            // Trim trailing newline / CRLF in-place logically.
            while matches!(self.line_buf.last(), Some(b'\n' | b'\r')) {
                self.line_buf.pop();
            }

            if self.config.skip_empty_lines && self.line_buf.is_empty() {
                continue;
            }

            if self.config.skip_header && self.line_number == 1 {
                continue;
            }

            self.field_positions.clear();
            self.split_fields();

            let line_str = std::str::from_utf8(&self.line_buf)?;
            let mut fields = Vec::with_capacity(self.field_positions.len());

            for &(start, end) in &self.field_positions {
                fields.push(&line_str[start..end]);
            }

            let record = Record { fields };
            on_record(self.line_number, record)?;
        }

        Ok(())
    }

    /// Split the current line buffer into fields by delimiter.
    /// This is a simple delimiter split, not full RFC 4180 CSV quoting support.
    #[inline]
    fn split_fields(&mut self) {
        let mut start = 0;
        let delim = self.config.delimiter;

        for (i, &b) in self.line_buf.iter().enumerate() {
            if b == delim {
                self.field_positions.push((start, i));
                start = i + 1;
            }
        }

        self.field_positions.push((start, self.line_buf.len()));
    }
}

/// Convenience function to parse a file path.
pub fn parse_file<P, F>(path: P, config: ParserConfig, on_record: F) -> Result<(), ParseError>
where
    P: AsRef<Path>,
    F: FnMut(usize, Record<'_>) -> Result<(), ParseError>,
{
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(config.reader_capacity, file);
    let mut parser = StreamingParser::new(reader, config);
    parser.parse(on_record)
}

fn main() -> Result<(), ParseError> {
