## More optimized variant: byte-level chunk parser

If you want to handle arbitrary streaming data, not just line-oriented input, here is a lower-level chunk parser pattern that processes raw bytes in fixed-size chunks.

```rust
use std::io::{self, Read};

pub struct ChunkParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
}

impl<R: Read> ChunkParser<R> {
    pub fn new(reader: R, chunk_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; chunk_size],
            carry: Vec::with_capacity(1024),
        }
    }

    /// Processes newline-delimited records from arbitrary chunks.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                if !self.carry.is_empty() {
                    on_record(&self.carry)?;
                    self.carry.clear();
                }
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0;

            for (i, &b) in chunk.iter().enumerate() {
                if b == b'\n' {
                    if self.carry.is_empty() {
                        let mut line = &chunk[start..i];
                        if line.ends_with(b"\r") {
                            line = &line[..line.len() - 1];
                        }
                        on_record(line)?;
                    } else {
                        self.carry.extend_from_slice(&chunk[start..i]);
                        if self.carry.ends_with(b"\r") {
                            self.carry.pop();
                        }
                        on_record(&self.carry)?;
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        Ok(())
    }
}
```

