use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A parsed record represented as byte ranges into a reusable line buffer.
/// This avoids allocating Strings for every field.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a [u8]>,
}

/// High-throughput streaming parser for delimiter-separated records.
///
/// Features:
/// - Reads incrementally from a buffered reader
/// - Reuses internal buffers
/// - Avoids per-field allocation by returning slices into the current line
/// - Suitable for very large files
pub struct StreamingParser<R: BufRead> {
    reader: R,
    line_buf: Vec<u8>,
    field_buf: Vec<&'static [u8]>, // placeholder, rebuilt per record
    delimiter: u8,
}

impl<R: BufRead> StreamingParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            reader,
            line_buf: Vec::with_capacity(64 * 1024),
            field_buf: Vec::with_capacity(64),
            delimiter,
        }
    }

    /// Parse the stream line-by-line and invoke `on_record` for each record.
    ///
    /// This is memory-efficient because:
    /// - only one line is kept in memory at a time
    /// - field slices borrow from that line buffer
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            self.line_buf.clear();

            let bytes_read = self.reader.read_until(b'\n', &mut self.line_buf)?;
            if bytes_read == 0 {
                break;
            }

            // Trim trailing newline / carriage return without allocation
            while matches!(self.line_buf.last(), Some(b'\n' | b'\r')) {
                self.line_buf.pop();
            }

            let fields = split_fields(&self.line_buf, self.delimiter);
            on_record(Record { fields })?;
        }

        Ok(())
    }
}

/// Split a line into fields without allocating field contents.
/// Returns slices into the original line buffer.
fn split_fields(line: &[u8], delimiter: u8) -> Vec<&[u8]> {
    let mut fields = Vec::with_capacity(16);
    let mut start = 0;

    for (i, &b) in line.iter().enumerate() {
        if b == delimiter {
            fields.push(&line[start..i]);
            start = i + 1;
        }
    }

    // Final field
    fields.push(&line[start..]);
    fields
}

/// Example record processor:
/// - parses the first field as u64
/// - counts records
/// - sums first-column values
#[derive(Default, Debug)]
struct Stats {
    records: u64,
    sum_first_col: u64,
}

fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    let mut n = 0u64;
    if bytes.is_empty() {
        return None;
    }

    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }

    Some(n)
}

pub fn process_file<P: AsRef<Path>>(path: P, delimiter: u8) -> io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file); // 1MB buffer
    let mut parser = StreamingParser::new(reader, delimiter);

    let mut stats = Stats::default();

    parser.parse(|record| {
        stats.records += 1;

        if let Some(first) = record.fields.get(0) {
            if let Some(v) = parse_u64_ascii(first) {
                stats.sum_first_col += v;
            }
        }

        // Do your actual processing here.
        // Important: don't retain `record.fields` after this callback returns,
        // because they borrow from the parser's reusable line buffer.
        Ok(())
    })?;

    Ok(stats)
}

fn main() -> io::Result<()> {
    let stats = process_file("large_input.csv", b',')?;
    println!("records={}, sum_first_col={}", stats.records, stats.sum_first_col);
    Ok(())
}
