```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Handle gigabyte-scale input
/// - Keep memory usage bounded
/// - Avoid storing all records in memory
/// - Minimize allocations by reusing buffers
///
/// This parser reads chunks from an input stream and emits records separated by '\n'.
/// It supports records spanning multiple chunks by keeping only the incomplete tail.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable buffer size.
    ///
    /// For high throughput, buffer sizes like 64 KiB, 256 KiB, or 1 MiB are common.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(buffer_size / 4),
            eof: false,
        }
    }

    /// Process all records in the stream.
    ///
    /// `on_record` is called for each parsed record as a byte slice.
    /// The slice is only valid during the callback.
    ///
    /// This avoids allocating a new String/Vec for every record.
    pub fn process<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;
                break;
            }

            self.process_chunk(&self.buf[..n], &mut on_record)?;
        }

        // Emit any remaining partial record at EOF.
        if !self.carry.is_empty() {
            on_record(&self.carry)?;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record fully contained in current chunk.
                    let record = &chunk[start..i];
                    on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s).
                    self.carry.extend_from_slice(&chunk[start..i]);
                    on_record(&self.carry)?;
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        // Save incomplete trailing record.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }
}

/// Example record processor:
/// Count records and total bytes without storing them.
#[derive(Default, Debug)]
pub struct Stats {
    pub records: u64,
    pub bytes: u64,
}

impl Stats {
    pub fn on_record(&mut self, record: &[u8]) -> io::Result<()> {
        self.records += 1;
        self.bytes += record.len() as u64;
        Ok(())
    }
}

/// Convenience function to parse a file.
pub fn parse_file<P: AsRef<Path>>(path: P, buffer_size: usize) -> io::Result<Stats> {
    let file = File::open(path)?;
    let mut parser = StreamingParser::new(file, buffer_size);
    let mut stats = Stats::default();

    parser.process(|record| stats.on_record(record))?;

    Ok(stats)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let stats = parse_file(path, 1024 * 1024)?; // 1 MiB buffer

    println!("Records: {}", stats.records);
    println!("Bytes: {}", stats.bytes);

    Ok(())
}
```

