```rust
use memchr::memchr_iter;
use std::io::{self, BufReader, Read};

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge(usize),
}

impl From<io::Error> for ParseError {
    fn from(e: io::Error) -> Self {
        ParseError::Io(e)
    }
}

pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
    max_record_size: usize,
    strip_cr: bool,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, buffer_size: usize, max_record_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(buffer_size / 4),
            eof: false,
            max_record_size,
            strip_cr: true,
        }
    }

    pub fn process<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(&[u8]) -> Result<(), ParseError>,
    {
        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;
                break;
            }
            let chunk = self.buf[..n].to_vec(); // can be optimized away in a more advanced design
            self.process_chunk(&chunk, &mut on_record)?;
        }

        if !self.carry.is_empty() {
            let record = if self.strip_cr && self.carry.last() == Some(&b'\r') {
                &self.carry[..self.carry.len() - 1]
            } else {
                &self.carry
            };
            on_record(record)?;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> Result<(), ParseError>
    where
        F: FnMut(&[u8]) -> Result<(), ParseError>,
    {
        let mut start = 0;

        for i in memchr_iter(b'\n', chunk) {
            if self.carry.is_empty() {
                let mut record = &chunk[start..i];
                if self.strip_cr && record.last() == Some(&b'\r') {
                    record = &record[..record.len() - 1];
                }
                on_record(record)?;
            } else {
                self.carry.extend_from_slice(&chunk[start..i]);
                if self.carry.len() > self.max_record_size {
                    return Err(ParseError::RecordTooLarge(self.carry.len()));
                }

                let record = if self.strip_cr && self.carry.last() == Some(&b'\r') {
                    &self.carry[..self.carry.len() - 1]
                } else {
                    &self.carry
                };
                on_record(record)?;
                self.carry.clear();
            }
            start = i + 1;
        }

        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
            if self.carry.len() > self.max_record_size {
                return Err(ParseError::RecordTooLarge(self.carry.len()));
            }
        }

        Ok(())
    }
}
