## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a single buffer
/// - Avoid storing all records in memory
/// - Minimize copying
/// - Handle arbitrarily large inputs
///
/// This parser reads chunks from the input stream and emits records
/// separated by '\n'. It supports records spanning multiple chunks.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a configurable internal buffer size.
    ///
    /// For high throughput, sizes like 64 KiB to several MiB are common.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            eof: false,
        }
    }

    /// Refill the internal buffer while preserving any unconsumed bytes.
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        // If all data has been consumed, reset pointers.
        if self.start == self.end {
            self.start = 0;
            self.end = 0;
        } else if self.start > 0 {
            // Move remaining unconsumed bytes to the front.
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        }

        // Read more data into the free tail of the buffer.
        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    /// Find the next newline-delimited record in the current buffer.
    ///
    /// Returns a slice into the internal buffer.
    fn next_record_in_buffer(&mut self) -> Option<&[u8]> {
        let data = &self.buf[self.start..self.end];
        if let Some(pos) = memchr::memchr(b'\n', data) {
            let record_start = self.start;
            let record_end = self.start + pos;

            self.start = record_end + 1;

            let mut record = &self.buf[record_start..record_end];
            if record.ends_with(b"\r") {
                record = &record[..record.len() - 1];
            }
            Some(record)
        } else {
            None
        }
    }

    /// Process all records using a callback.
    ///
    /// The callback receives each record as a borrowed byte slice.
    /// The slice is only valid until the next parser operation.
    pub fn process_records<F>(&mut self, mut f: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut spill = Vec::<u8>::new();

        loop {
            // Emit all complete records currently in the buffer.
            while let Some(record) = self.next_record_in_buffer() {
                if spill.is_empty() {
                    f(record)?;
                } else {
                    spill.extend_from_slice(record);
                    f(&spill)?;
                    spill.clear();
                }
            }

            if self.eof {
                // Handle trailing partial record at EOF.
                if self.start < self.end {
                    if spill.is_empty() {
                        f(&self.buf[self.start..self.end])?;
                    } else {
                        spill.extend_from_slice(&self.buf[self.start..self.end]);
                        f(&spill)?;
                    }
                } else if !spill.is_empty() {
                    f(&spill)?;
                }
                break;
            }

            // If no newline found and buffer is full, spill partial record.
            if self.start == 0 && self.end == self.buf.len() {
                spill.extend_from_slice(&self.buf[..self.end]);
                self.start = 0;
                self.end = 0;
            }

            self.refill()?;
        }

        Ok(())
    }
}

/// Example usage: parse a file and count records + bytes.
pub fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let mut parser = StreamingParser::with_capacity(file, 1024 * 1024);

    let mut record_count: u64 = 0;
    let mut total_bytes: u64 = 0;

    parser.process_records(|record| {
        record_count += 1;
        total_bytes += record.len() as u64;

        // Example processing:
        // - decode UTF-8 if needed
        // - parse fields
        // - aggregate stats
        // Avoid allocating unless necessary.
        Ok(())
    })?;

    println!("records: {}", record_count);
    println!("payload bytes: {}", total_bytes);

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: streaming_parser <input-file>");
    parse_file(path)
}
