```rust
use std::io;

pub trait RecordHandler {
    fn on_record(&mut self, record: &[u8]) -> io::Result<()>;
}

pub trait Delimiter {
    fn find(&self, buf: &[u8]) -> Option<usize>;
    fn strip<'a>(&self, record: &'a [u8]) -> &'a [u8] {
        record
    }
}

pub struct NewlineDelimiter;

impl Delimiter for NewlineDelimiter {
    fn find(&self, buf: &[u8]) -> Option<usize> {
        memchr::memchr(b'\n', buf)
    }

    fn strip<'a>(&self, record: &'a [u8]) -> &'a [u8] {
        if record.ends_with(b"\r") {
            &record[..record.len() - 1]
        } else {
            record
        }
    }
}
