```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited data.
///
/// Design goals:
/// - Reuse a single buffer
/// - Avoid loading the full file into memory
/// - Avoid per-record allocation where possible
/// - Process records incrementally via callback
///
/// This parser assumes records are delimited by '\n'.
/// It yields each record as a byte slice into an internal buffer.
/// The callback must not retain the slice after returning.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a specified buffer capacity.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 1, "buffer capacity must be > 1");
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            eof: false,
        }
    }

    /// Refill the buffer while preserving unconsumed bytes.
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        // Move unconsumed bytes to the front if needed.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        // If buffer is full and no delimiter found, caller may need a larger buffer
        // or a spillover strategy.
        if self.end == self.buf.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "record exceeds buffer capacity",
            ));
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    /// Process each record using the provided callback.
    ///
    /// The callback receives a slice excluding the trailing '\n'.
    /// If the input ends without a trailing newline, the final partial record is emitted.
    pub fn process_records<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            // Search for newline in current buffer.
            if let Some(pos) = self.buf[self.start..self.end]
                .iter()
                .position(|&b| b == b'\n')
            {
                let newline_idx = self.start + pos;
                let mut record = &self.buf[self.start..newline_idx];

                // Trim optional '\r' for CRLF support.
                if let Some(&b'\r') = record.last() {
                    record = &record[..record.len() - 1];
                }

                on_record(record)?;
                self.start = newline_idx + 1;
                continue;
            }

            // No newline found.
            if self.eof {
                // Emit trailing partial record if present.
                if self.start < self.end {
                    let mut record = &self.buf[self.start..self.end];
                    if let Some(&b'\r') = record.last() {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record)?;
                    self.start = self.end;
                }
                break;
            }

            self.refill()?;
        }

        Ok(())
    }
}

/// Example domain parser: parse lines of the form:
/// key,value,timestamp
///
/// This avoids allocating Strings unless needed.
#[derive(Debug)]
pub struct ParsedRecord<'a> {
    pub key: &'a [u8],
    pub value: &'a [u8],
    pub timestamp: &'a [u8],
}

pub fn parse_csv3_line(line: &[u8]) -> Option<ParsedRecord<'_>> {
    let mut parts = line.splitn(3, |&b| b == b',');

    let key = parts.next()?;
    let value = parts.next()?;
    let timestamp = parts.next()?;

    Some(ParsedRecord {
        key,
        value,
        timestamp,
    })
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::with_capacity(reader, 1024 * 1024);

    let mut count: u64 = 0;

    parser.process_records(|line| {
        if let Some(record) = parse_csv3_line(line) {
            // Example processing:
            // Avoid converting to UTF-8 unless necessary.
            // Do lightweight work here.
            let _ = record;
            count += 1;
        } else {
            eprintln!("Malformed line: {:?}", String::from_utf8_lossy(line));
        }
        Ok(())
    })?;

    println!("Processed {} records", count);
    Ok(())
}
