# Improved Version With Oversized Record Support

If records may exceed buffer size, here is a more robust version that uses a small spill buffer only when necessary.

```rust
use std::io::{self, Read};

pub struct StreamingParserLarge<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
    spill: Vec<u8>,
}

impl<R: Read> StreamingParserLarge<R> {
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            eof: false,
            spill: Vec::new(),
        }
    }

    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    pub fn process_records<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            if let Some(pos) = self.buf[self.start..self.end]
                .iter()
                .position(|&b| b == b'\n')
            {
                let newline_idx = self.start + pos;

                if self.spill.is_empty() {
                    let mut record = &self.buf[self.start..newline_idx];
                    if let Some(&b'\r') = record.last() {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record)?;
                } else {
                    self.spill.extend_from_slice(&self.buf[self.start..newline_idx]);
                    if self.spill.last() == Some(&b'\r') {
                        self.spill.pop();
                    }
                    on_record(&self.spill)?;
                    self.spill.clear();
                }

                self.start = newline_idx + 1;
                continue;
            }

            if self.eof {
                if self.start < self.end || !self.spill.is_empty() {
                    if self.start < self.end {
                        self.spill.extend_from_slice(&self.buf[self.start..self.end]);
                    }
                    let mut record = self.spill.as_slice();
                    if let Some(&b'\r') = record.last() {
                        record = &record[..record.len() - 1];
                    }
                    if !record.is_empty() || !self.spill.is_empty() {
                        on_record(record)?;
                    }
                    self.spill.clear();
                    self.start = self.end;
                }
                break;
            }

            // Buffer full and still no newline: spill partial data.
            if self.start == 0 && self.end == self.buf.len() {
                self.spill.extend_from_slice(&self.buf[..self.end]);
                self.start = 0;
                self.end = 0;
            }

            self.refill()?;
        }

        Ok(())
    }
}
```

