## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Handle very large inputs without loading them fully into memory
/// - Minimize allocations by reusing buffers
/// - Support partial records spanning chunk boundaries
/// - Process records incrementally via callback
///
/// Notes:
/// - This parser emits records as byte slices to avoid UTF-8 validation overhead.
/// - If you need UTF-8 strings, convert in the callback.
/// - The parser copies only when a record spans multiple chunks.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable buffer size.
    ///
    /// For high-throughput workloads, 64 KiB to 1 MiB is often reasonable.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Process all records separated by '\n'.
    ///
    /// The callback receives each record without the trailing newline.
    /// Returns the number of records processed.
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<u64>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut total_records = 0u64;

        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;

                if !self.carry.is_empty() {
                    on_record(&self.carry)?;
                    total_records += 1;
                    self.carry.clear();
                }
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0usize;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    if self.carry.is_empty() {
                        // Fast path: record fully contained in current chunk
                        on_record(&chunk[start..i])?;
                    } else {
                        // Slow path: record spans chunk boundary
                        self.carry.extend_from_slice(&chunk[start..i]);
                        on_record(&self.carry)?;
                        self.carry.clear();
                    }
                    total_records += 1;
                    start = i + 1;
                }
            }

            // Save trailing partial record
            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        Ok(total_records)
    }
}

/// Example record processor that counts bytes and records.
#[derive(Default, Debug)]
pub struct Stats {
    pub records: u64,
    pub bytes: u64,
}

impl Stats {
    pub fn process(&mut self, record: &[u8]) {
        self.records += 1;
        self.bytes += record.len() as u64;
    }
}

/// Example usage with a file path.
pub fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<Stats> {
    let file = File::open(path)?;
    let mut parser = StreamingParser::new(file, 256 * 1024);

    let mut stats = Stats::default();

    parser.parse_lines(|record| {
        stats.process(record);

        // Example: lightweight filtering / parsing
        // if record.starts_with(b"ERROR") { ... }

        Ok(())
    })?;

    Ok(stats)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let stats = parse_file(path)?;
    println!("Processed {} records, {} bytes", stats.records, stats.bytes);
    Ok(())
}
