Code:

```rust
use memchr::memchr_iter;
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
    max_record_size: usize,
    strip_cr: bool,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(1024),
            eof: false,
            max_record_size: 16 * 1024 * 1024,
            strip_cr: true,
        }
    }

    pub fn with_max_record_size(mut self, size: usize) -> Self {
        self.max_record_size = size;
        self
    }

    pub fn with_strip_cr(mut self, strip: bool) -> Self {
        self.strip_cr = strip;
        self
    }

    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<u64>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut total_records = 0u64;

        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;

                if !self.carry.is_empty() {
                    let rec = if self.strip_cr && self.carry.last() == Some(&b'\r') {
                        &self.carry[..self.carry.len() - 1]
                    } else {
                        &self.carry
                    };
                    on_record(rec)?;
                    total_records += 1;
                    self.carry.clear();
                }
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0usize;

            for end in memchr_iter(b'\n', chunk) {
                if self.carry.is_empty() {
                    let mut rec = &chunk[start..end];
                    if self.strip_cr && rec.last() == Some(&b'\r') {
                        rec = &rec[..rec.len() - 1];
                    }
                    on_record(rec)?;
                } else {
                    self.carry.extend_from_slice(&chunk[start..end]);
                    if self.carry.len() > self.max_record_size {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "record exceeds maximum allowed size",
                        ));
                    }

                    let rec_len = self.carry.len();
                    let rec = if self.strip_cr && self.carry.last() == Some(&b'\r') {
                        &self.carry[..rec_len - 1]
                    } else {
                        &self.carry[..]
                    };
                    on_record(rec)?;
                    self.carry.clear();
                }

                total_records += 1;
                start = end + 1;
            }

            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
                if self.carry.len() > self.max_record_size {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "record exceeds maximum allowed size",
                    ));
                }
            }
        }

        Ok(total_records)
    }
}

