## Rust implementation

```rust
use std::io::{self, Read};

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Minimal memory overhead
/// - Incremental parsing from any `Read`
/// - Reuses a fixed-size internal buffer
/// - Handles records split across read boundaries
///
/// Notes:
/// - Returned record slices are only valid until the next call to `next_record`.
/// - Very large records that exceed buffer capacity are accumulated into `spill`.
pub struct StreamingParser<R: Read> {
    reader: R,

    // Main reusable buffer
    buf: Box<[u8]>,
    start: usize,
    end: usize,

    // Spill buffer for records larger than the main buffer
    spill: Vec<u8>,

    // EOF reached
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a specified buffer size.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 1, "capacity must be > 1");
        Self {
            reader,
            buf: vec![0u8; capacity].into_boxed_slice(),
            start: 0,
            end: 0,
            spill: Vec::new(),
            eof: false,
        }
    }

    /// Create a parser with a default 64 KiB buffer.
    pub fn new(reader: R) -> Self {
        Self::with_capacity(reader, 64 * 1024)
    }

    /// Returns the next newline-delimited record.
    ///
    /// The returned slice is valid until the next call to `next_record`.
    ///
    /// Behavior:
    /// - Strips trailing '\n'
    /// - Also strips trailing '\r' for CRLF input
    /// - Returns the final unterminated line at EOF
    pub fn next_record<'a>(&'a mut self) -> io::Result<Option<&'a [u8]>> {
        loop {
            // Search for newline in current buffer window.
            if let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let nl = self.start + pos;

                if self.spill.is_empty() {
                    let mut record = &self.buf[self.start..nl];
                    if let Some(b'\r') = record.last().copied() {
                        record = &record[..record.len() - 1];
                    }
                    self.start = nl + 1;
                    return Ok(Some(record));
                } else {
                    self.spill.extend_from_slice(&self.buf[self.start..nl]);
                    if self.spill.last() == Some(&b'\r') {
                        self.spill.pop();
                    }
                    self.start = nl + 1;
                    return Ok(Some(&self.spill));
                }
            }

            // No newline found in current buffer.
            if self.eof {
                if self.start < self.end || !self.spill.is_empty() {
                    self.spill.extend_from_slice(&self.buf[self.start..self.end]);
                    self.start = self.end;

                    if self.spill.last() == Some(&b'\r') {
                        self.spill.pop();
                    }

                    if self.spill.is_empty() {
                        return Ok(None);
                    }

                    return Ok(Some(&self.spill));
                } else {
                    return Ok(None);
                }
            }

            // Buffer exhausted: compact or spill before reading more.
            self.prepare_for_read()?;
            self.fill_buf()?;
        }
    }

    fn prepare_for_read(&mut self) -> io::Result<()> {
        // If there is unconsumed data and no room at the end, compact it.
        if self.end == self.buf.len() {
            if self.start > 0 {
                let len = self.end - self.start;
                self.buf.copy_within(self.start..self.end, 0);
                self.start = 0;
                self.end = len;
            } else {
                // Buffer full and no newline found: spill current contents.
                self.spill.extend_from_slice(&self.buf[..self.end]);
                self.start = 0;
                self.end = 0;
            }
        }
        Ok(())
    }

    fn fill_buf(&mut self) -> io::Result<()> {
        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(())
    }
}

