## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Minimal memory overhead
/// - Reusable fixed-size buffer
/// - Incremental parsing across chunk boundaries
/// - Zero-copy delivery when possible
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    scratch: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a fixed buffer size.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0, "buffer_size must be > 0");
        Self {
            reader,
            buf: vec![0; buffer_size],
            start: 0,
            end: 0,
            scratch: Vec::new(),
            eof: false,
        }
    }

    /// Parse the stream and invoke `on_record` for each newline-delimited record.
    ///
    /// Records are delivered without the trailing '\n'.
    /// If the input ends without a trailing newline, the final partial record is emitted.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            if self.start == self.end && self.eof {
                if !self.scratch.is_empty() {
                    on_record(&self.scratch)?;
                    self.scratch.clear();
                }
                return Ok(());
            }

            if self.start == self.end && !self.eof {
                self.fill_buf()?;
            }

            while self.start < self.end {
                let slice = &self.buf[self.start..self.end];

                if let Some(pos) = memchr::memchr(b'\n', slice) {
                    let line = &slice[..pos];
                    self.start += pos + 1;

                    if self.scratch.is_empty() {
                        on_record(line)?;
                    } else {
                        self.scratch.extend_from_slice(line);
                        on_record(&self.scratch)?;
                        self.scratch.clear();
                    }
                } else {
                    self.scratch.extend_from_slice(slice);
                    self.start = self.end;
                    break;
                }
            }

            if self.start == self.end && !self.eof {
                self.fill_buf()?;
            }
        }
    }

    fn fill_buf(&mut self) -> io::Result<()> {
        self.start = 0;
        self.end = 0;

        let n = self.reader.read(&mut self.buf)?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end = n;
        }
        Ok(())
    }
}

/// Example typed parser for records like:
/// timestamp,level,message
#[derive(Debug)]
pub struct LogRecord<'a> {
    pub timestamp: &'a [u8],
    pub level: &'a [u8],
    pub message: &'a [u8],
}

/// Parse a CSV-like log line into fields without allocation.
///
/// Returns None if the line is malformed.
pub fn parse_log_record(line: &[u8]) -> Option<LogRecord<'_>> {
    let first = memchr::memchr(b',', line)?;
    let second = memchr::memchr(b',', &line[first + 1..])? + first + 1;

    Some(LogRecord {
        timestamp: &line[..first],
        level: &line[first + 1..second],
        message: &line[second + 1..],
    })
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.log");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::new(reader, 1024 * 1024);

    let mut count: u64 = 0;

    parser.parse(|line| {
        if let Some(record) = parse_log_record(line) {
            // Process record immediately; avoid storing all records.
            // Example: count only ERROR lines.
            if record.level == b"ERROR" {
                count += 1;
            }
        }
        Ok(())
    })?;

    println!("ERROR count: {}", count);
    Ok(())
}
