## Rust implementation

```rust
use std::io::{self, BufRead, BufReader, Read};

/// A parsed record borrowed from internal buffers when possible.
/// If a record spans multiple chunks, it is assembled into `scratch` and
/// passed as an owned slice reference valid for the callback duration.
#[derive(Debug, Clone, Copy)]
pub struct Record<'a> {
    pub bytes: &'a [u8],
}

impl<'a> Record<'a> {
    pub fn as_str(&self) -> Result<&'a str, std::str::Utf8Error> {
        std::str::from_utf8(self.bytes)
    }
}

/// High-throughput streaming parser for delimiter-separated records.
/// Default use case: newline-delimited data.
pub struct StreamingParser<R> {
    reader: BufReader<R>,
    delimiter: u8,
    scratch: Vec<u8>,
    records_parsed: u64,
    bytes_read: u64,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a configurable reader buffer capacity.
    pub fn with_capacity(inner: R, capacity: usize, delimiter: u8) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, inner),
            delimiter,
            scratch: Vec::with_capacity(1024),
            records_parsed: 0,
            bytes_read: 0,
        }
    }

    /// Create a parser with a sensible default buffer size.
    pub fn new(inner: R) -> Self {
        Self::with_capacity(inner, 1024 * 1024, b'\n')
    }

    pub fn records_parsed(&self) -> u64 {
        self.records_parsed
    }

    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    /// Parse the stream and invoke `on_record` for each record.
    ///
    /// The callback should process the record immediately and not retain references.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            let buf = self.reader.fill_buf()?;
            if buf.is_empty() {
                // EOF: flush any partial record remaining in scratch.
                if !self.scratch.is_empty() {
                    self.records_parsed += 1;
                    on_record(Record {
                        bytes: &self.scratch,
                    })?;
                    self.scratch.clear();
                }
                return Ok(());
            }

            self.bytes_read += buf.len() as u64;

            let mut start = 0;
            for i in 0..buf.len() {
                if buf[i] == self.delimiter {
                    if self.scratch.is_empty() {
                        // Fast path: record fully contained in current buffer.
                        let record = &buf[start..i];
                        self.records_parsed += 1;
                        on_record(Record { bytes: record })?;
                    } else {
                        // Slow path: record spans multiple buffers.
                        self.scratch.extend_from_slice(&buf[start..i]);
                        self.records_parsed += 1;
                        on_record(Record {
                            bytes: &self.scratch,
                        })?;
                        self.scratch.clear();
                    }
                    start = i + 1;
                }
            }

            // Save trailing partial record bytes if no delimiter at end.
            if start < buf.len() {
                self.scratch.extend_from_slice(&buf[start..]);
            }

            let consumed = buf.len();
            self.reader.consume(consumed);
        }
    }
}
```

