## Example with max record size protection

```rust
use memchr::memchr_iter;
use std::io::{self, BufRead, BufReader, Read};

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge { size: usize, max: usize },
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Record<'a> {
    pub bytes: &'a [u8],
}

pub struct StreamingParser<R> {
    reader: BufReader<R>,
    delimiter: u8,
    scratch: Vec<u8>,
    max_record_size: usize,
}

impl<R: Read> StreamingParser<R> {
    pub fn with_capacity_and_limit(
        inner: R,
        capacity: usize,
        delimiter: u8,
        max_record_size: usize,
    ) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, inner),
            delimiter,
            scratch: Vec::with_capacity(1024),
            max_record_size,
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(Record<'_>) -> Result<(), ParseError>,
    {
        loop {
            let buf = self.reader.fill_buf()?;
            if buf.is_empty() {
                if !self.scratch.is_empty() {
                    if self.scratch.len() > self.max_record_size {
                        return Err(ParseError::RecordTooLarge {
                            size: self.scratch.len(),
                            max: self.max_record_size,
                        });
                    }
                    on_record(Record {
                        bytes: &self.scratch,
                    })?;
                    self.scratch.clear();
                }
                return Ok(());
            }

            let mut start = 0;
            for i in memchr_iter(self.delimiter, buf) {
                let segment_len = i - start;
                let total_len = self.scratch.len() + segment_len;
                if total_len > self.max_record_size {
                    return Err(ParseError::RecordTooLarge {
                        size: total_len,
                        max: self.max_record_size,
                    });
                }

                if self.scratch.is_empty() {
                    on_record(Record {
                        bytes: &buf[start..i],
                    })?;
                } else {
                    self.scratch.extend_from_slice(&buf[start..i]);
                    on_record(Record {
                        bytes: &self.scratch,
                    })?;
                    self.scratch.clear();
                }

                start = i + 1;
            }

            if start < buf.len() {
                let trailing = &buf[start..];
                let total_len = self.scratch.len() + trailing.len();
                if total_len > self.max_record_size {
                    return Err(ParseError::RecordTooLarge {
                        size: total_len,
                        max: self.max_record_size,
                    });
                }
                self.scratch.extend_from_slice(trailing);
            }

            let consumed = buf.len();
            self.reader.consume(consumed);
        }
    }
}
```

