This initial version implements a **newline-delimited record parser** with support for:

- arbitrarily large input streams
- records split across buffer boundaries
- callback-based processing to avoid storing parsed output
- optional owned fallback only when a record spans multiple chunks

---

## Rust Implementation

```rust
use std::borrow::Cow;
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record that is either borrowed from the current buffer
/// or owned when it had to be stitched across chunk boundaries.
#[derive(Debug)]
pub struct Record<'a> {
    pub bytes: Cow<'a, [u8]>,
}

impl<'a> Record<'a> {
    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    pub fn as_str(&self) -> Option<&str> {
        std::str::from_utf8(&self.bytes).ok()
    }
}

/// High-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid allocations for records fully contained in a chunk
/// - Allocate only when a record spans multiple chunks
/// - Process records via callback to avoid retaining parsed data
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Box<[u8]>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a configurable buffer size.
    ///
    /// For throughput, 64 KiB to several MiB can work well depending on workload.
    pub fn with_buffer_size(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0, "buffer_size must be > 0");
        Self {
            reader,
            buf: vec![0u8; buffer_size].into_boxed_slice(),
            carry: Vec::new(),
            eof: false,
        }
    }

    /// Parse all records from the stream.
    ///
    /// The callback is invoked once per record.
    /// Records do not include the trailing '\n'.
    ///
    /// If the input ends without a trailing newline, the final partial record
    /// is still emitted.
    pub fn parse_all<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: for<'a> FnMut(Record<'a>) -> io::Result<()>,
    {
        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;
                break;
            }

            let chunk = &self.buf[..n];
            self.process_chunk(chunk, &mut on_record)?;
        }

        // Emit any remaining partial record at EOF.
        if !self.carry.is_empty() {
            let record = Record {
                bytes: Cow::Owned(std::mem::take(&mut self.carry)),
            };
            on_record(record)?;
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: for<'a> FnMut(Record<'a>) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record is fully inside current chunk.
                    let mut end = i;
                    if end > start && chunk[end - 1] == b'\r' {
                        end -= 1; // Handle CRLF
                    }

                    let record = Record {
                        bytes: Cow::Borrowed(&chunk[start..end]),
                    };
                    on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s) + current chunk.
                    let mut end = i;
                    if end > start && chunk[end - 1] == b'\r' {
                        end -= 1; // Handle CRLF
                    }

                    self.carry.extend_from_slice(&chunk[start..end]);
                    let record = Record {
                        bytes: Cow::Owned(std::mem::take(&mut self.carry)),
                    };
                    on_record(record)?;
                }

                start = i + 1;
            }
        }

        // Save trailing partial record bytes.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }
}

/// Convenience function for parsing a file.
pub fn parse_file<P, F>(path: P, buffer_size: usize, on_record: F) -> io::Result<()>
where
    P: AsRef<Path>,
    F: for<'a> FnMut(Record<'a>) -> io::Result<()>,
{
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(buffer_size, file);
    let mut parser = StreamingParser::with_buffer_size(reader, buffer_size);
    parser.parse_all(on_record)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";

    let mut count: u64 = 0;
    let mut total_bytes: u64 = 0;

    parse_file(path, 1024 * 1024, |record| {
        count += 1;
        total_bytes += record.as_bytes().len() as u64;

        // Example processing:
        // if let Some(s) = record.as_str() {
        //     println!("{}", s);
        // }

        Ok(())
    })?;

    println!("records: {}", count);
    println!("payload bytes: {}", total_bytes);

    Ok(())
}
