Below is an initial implementation in Rust of a high-throughput streaming parser designed for gigabyte-scale input with minimal memory overhead.

It is built around these principles:

- streaming from any `Read`
- fixed-size reusable buffer
- zero-copy parsing where possible via borrowed slices
- incremental record extraction across chunk boundaries
- minimal allocations
- callback-based consumption so parsed records do not need to be retained

This example parses newline-delimited records, but the structure is general and can be adapted to CSV, log formats, binary framed protocols, etc.

---

## Features

- Handles arbitrarily large inputs
- Uses a single reusable buffer
- Correctly handles records split across buffer boundaries
- Avoids per-line allocation when the line is fully contained in the current buffer window
- Falls back to a scratch buffer only for boundary-spanning records
- Exposes a visitor/callback API for throughput

---

## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record, borrowing from the parser buffer when possible.
#[derive(Debug)]
pub enum Record<'a> {
    Borrowed(&'a [u8]),
    Owned(Vec<u8>),
}

impl<'a> Record<'a> {
    pub fn as_bytes(&self) -> &[u8] {
        match self {
            Record::Borrowed(b) => b,
            Record::Owned(v) => v.as_slice(),
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        std::str::from_utf8(self.as_bytes()).ok()
    }
}

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design:
/// - Reads chunks into a reusable buffer
/// - Scans for '\n'
/// - Emits borrowed slices when record is fully in-buffer
/// - Uses scratch only when a record spans multiple reads
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    scratch: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a fixed-capacity buffer.
    ///
    /// Recommended sizes:
    /// - 64 KiB to 1 MiB for general workloads
    /// - larger if records are often large
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 0);
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            scratch: Vec::new(),
            eof: false,
        }
    }

    /// Fill the buffer, compacting unconsumed bytes to the front first.
    fn refill(&mut self) -> io::Result<usize> {
        if self.eof {
            return Ok(0);
        }

        // Compact remaining bytes to the front.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(n)
    }

    /// Parse the next record.
    ///
    /// Returns:
    /// - Ok(Some(record)) when a record is available
    /// - Ok(None) on end of stream
    pub fn next_record<'a>(&'a mut self) -> io::Result<Option<Record<'a>>> {
        loop {
            // Search for newline in current buffer window.
            if let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let abs_pos = self.start + pos;
                let line = &self.buf[self.start..abs_pos];
                self.start = abs_pos + 1;

                if self.scratch.is_empty() {
                    return Ok(Some(Record::Borrowed(line)));
                } else {
                    self.scratch.extend_from_slice(line);
                    let owned = std::mem::take(&mut self.scratch);
                    return Ok(Some(Record::Owned(owned)));
                }
            }

            // No newline in current buffer.
            if self.eof {
                if self.start < self.end || !self.scratch.is_empty() {
                    self.scratch.extend_from_slice(&self.buf[self.start..self.end]);
                    self.start = self.end;
                    let owned = std::mem::take(&mut self.scratch);
                    return Ok(Some(Record::Owned(owned)));
                }
                return Ok(None);
            }

            // If buffer is full and no delimiter found, spill current fragment to scratch.
            if self.start == 0 && self.end == self.buf.len() {
                self.scratch.extend_from_slice(&self.buf[..self.end]);
                self.start = 0;
                self.end = 0;
            } else if self.start < self.end {
                self.scratch.extend_from_slice(&self.buf[self.start..self.end]);
                self.start = 0;
                self.end = 0;
            }

            self.refill()?;
        }
    }

    /// Drive parsing with a callback to avoid storing records.
    pub fn for_each_record<F>(&mut self, mut f: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        while let Some(record) = self.next_record()? {
            f(record.as_bytes())?;
        }
        Ok(())
    }
}

/// Example record processor.
/// Replace with your actual parsing logic.
fn process_record(record: &[u8]) -> io::Result<()> {
    // Example: count bytes, parse fields, validate, etc.
    let _len = record.len();
    Ok(())
}

fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(256 * 1024, file);
    let mut parser = StreamingParser::with_capacity(reader, 256 * 1024);

    parser.for_each_record(|record| process_record(record))?;
    Ok(())
}

fn main() -> io::Result<()> {
    parse_file("large_input.txt")
}
```

