Below is an initial implementation in Rust of a high-throughput streaming parser designed for gigabyte-scale input with minimal memory overhead.

It is built around these goals:

- Stream from any `Read` source
- Reuse a fixed-size buffer
- Avoid loading the full input into memory
- Parse records incrementally
- Handle records split across buffer boundaries
- Expose a callback-based API to avoid accumulating parsed output

This example implements a newline-delimited record parser, which is a common foundation for logs, CSV-like line processing, NDJSON, etc.

---

## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Fixed-size reusable buffer
/// - Minimal allocations
/// - Handles records spanning multiple chunks
/// - Callback-based consumption to avoid storing output
///
/// This parser emits each line without the trailing '\n'.
/// If the input ends without a trailing newline, the final partial line is emitted too.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
    bytes_read: u64,
    records_parsed: u64,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable internal buffer size.
    ///
    /// Recommended sizes for throughput are often 64 KiB to 1 MiB depending on workload.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0, "buffer_size must be > 0");
        Self {
            reader,
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(1024),
            bytes_read: 0,
            records_parsed: 0,
        }
    }

    /// Parse the stream and invoke `on_record` for each complete record.
    ///
    /// The callback receives a byte slice for each record. The slice is only valid
    /// during the callback invocation, so copy it if you need to retain it.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            self.bytes_read += n as u64;
            self.process_chunk(&self.buf[..n], &mut on_record)?;
        }

        // Emit final unterminated record if present.
        if !self.carry.is_empty() {
            on_record(&self.carry)?;
            self.records_parsed += 1;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record fully contained in current chunk.
                    let mut record = &chunk[start..i];

                    // Trim optional '\r' for CRLF support.
                    if let Some(b'\r') = record.last().copied() {
                        record = &record[..record.len() - 1];
                    }

                    on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s) + current chunk.
                    self.carry.extend_from_slice(&chunk[start..i]);

                    if self.carry.last() == Some(&b'\r') {
                        self.carry.pop();
                    }

                    on_record(&self.carry)?;
                    self.carry.clear();
                }

                self.records_parsed += 1;
                start = i + 1;
            }
        }

        // Save trailing partial record.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    pub fn records_parsed(&self) -> u64 {
        self.records_parsed
    }
}

/// Example consumer that counts records and bytes without storing them.
pub fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::new(reader, 256 * 1024);

    let mut record_count = 0u64;
    let mut payload_bytes = 0u64;

    parser.parse(|record| {
        record_count += 1;
        payload_bytes += record.len() as u64;

        // Example processing:
        // - decode UTF-8 if needed
        // - parse fields
        // - write to downstream sink
        //
        // Avoid allocating unless necessary.

        Ok(())
    })?;

    println!("bytes_read={}", parser.bytes_read());
    println!("records_parsed={}", parser.records_parsed());
    println!("record_count={}", record_count);
    println!("payload_bytes={}", payload_bytes);

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: streaming_parser <input-file>");

    parse_file(path)
}
