## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Handle very large inputs without loading them fully into memory
/// - Reuse a single buffer
/// - Avoid per-record allocations where possible
/// - Support records spanning chunk boundaries
///
/// This parser yields each line as a borrowed slice when possible.
/// If a line spans multiple chunks, it is assembled into a scratch buffer.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    scratch: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a configurable internal buffer size.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            scratch: Vec::new(),
            eof: false,
        }
    }

    /// Refills the internal buffer, preserving unread bytes if necessary.
    fn refill(&mut self) -> io::Result<usize> {
        if self.eof {
            return Ok(0);
        }

        // Move unread bytes to the front if needed.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(n)
    }

    /// Process all records using a callback.
    ///
    /// The callback receives each record as a byte slice without the trailing newline.
    /// It should process the slice immediately, since borrowed slices may reference
    /// internal parser buffers.
    pub fn process_all<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            match self.next_record()? {
                Some(record) => on_record(record)?,
                None => break,
            }
        }
        Ok(())
    }

    /// Returns the next record, if any.
    ///
    /// Records are delimited by '\n'. A trailing '\r' before '\n' is stripped.
    pub fn next_record(&mut self) -> io::Result<Option<&[u8]>> {
        loop {
            if let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let newline_idx = self.start + pos;
                let record = if self.scratch.is_empty() {
                    let mut slice = &self.buf[self.start..newline_idx];
                    if slice.last() == Some(&b'\r') {
                        slice = &slice[..slice.len() - 1];
                    }
                    self.start = newline_idx + 1;
                    return Ok(Some(slice));
                } else {
                    self.scratch
                        .extend_from_slice(&self.buf[self.start..newline_idx]);
                    if self.scratch.last() == Some(&b'\r') {
                        self.scratch.pop();
                    }
                    self.start = newline_idx + 1;
                    let out = &self.scratch[..];
                    return Ok(Some(out));
                };
            }

            // No newline found in current buffer.
            if self.eof {
                if self.start < self.end {
                    if self.scratch.is_empty() {
                        let mut slice = &self.buf[self.start..self.end];
                        if slice.last() == Some(&b'\r') {
                            slice = &slice[..slice.len() - 1];
                        }
                        self.start = self.end;
                        return Ok(Some(slice));
                    } else {
                        self.scratch
                            .extend_from_slice(&self.buf[self.start..self.end]);
                        if self.scratch.last() == Some(&b'\r') {
                            self.scratch.pop();
                        }
                        self.start = self.end;
                        let out = &self.scratch[..];
                        return Ok(Some(out));
                    }
                } else if !self.scratch.is_empty() {
                    if self.scratch.last() == Some(&b'\r') {
                        self.scratch.pop();
                    }
                    let out = &self.scratch[..];
                    self.scratch = Vec::new();
                    return Ok(Some(out));
                } else {
                    return Ok(None);
                }
            }

            // Append current unread bytes to scratch if record spans chunks.
            if self.start < self.end {
                self.scratch
                    .extend_from_slice(&self.buf[self.start..self.end]);
                self.start = self.end;
            }

            self.refill()?;
        }
    }
}

impl StreamingParser<BufReader<File>> {
    pub fn from_file<P: AsRef<Path>>(path: P, capacity: usize) -> io::Result<Self> {
        let file = File::open(path)?;
        Ok(Self::with_capacity(BufReader::with_capacity(capacity, file), capacity))
    }
}

