/// Fast ASCII u64 parser without intermediate allocation.
pub fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut n: u64 = 0;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let mut parser = StreamingParser::from_file(path, 1024 * 1024)?; // 1 MiB buffer

    parser.process_all(|record| {
        process_csv_like_record(record)?;
        Ok(())
    })?;

    Ok(())
}
