## Production-ready initial version

Here is a cleaner version that avoids the problematic `next_record()` API and uses only callback-based processing:

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    scratch: Vec<u8>,
    eof: bool,
    max_record_size: usize,
}

impl<R: Read> StreamingParser<R> {
    pub fn with_capacity(reader: R, capacity: usize, max_record_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            scratch: Vec::new(),
            eof: false,
            max_record_size,
        }
    }

    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(())
    }

    fn append_to_scratch(&mut self, data: &[u8]) -> io::Result<()> {
        let new_len = self.scratch.len() + data.len();
        if new_len > self.max_record_size {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "record exceeds max_record_size",
            ));
        }
        self.scratch.extend_from_slice(data);
        Ok(())
    }

    pub fn process_all<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            if let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let newline_idx = self.start + pos;

                if self.scratch.is_empty() {
                    let mut slice = &self.buf[self.start..newline_idx];
                    if slice.last() == Some(&b'\r') {
                        slice = &slice[..slice.len() - 1];
                    }
                    self.start = newline_idx + 1;
                    on_record(slice)?;
                } else {
                    let chunk = self.buf[self.start..newline_idx].to_vec();
                    self.start = newline_idx + 1;
                    self.append_to_scratch(&chunk)?;
                    if self.scratch.last() == Some(&b'\r') {
                        self.scratch.pop();
                    }
                    on_record(&self.scratch)?;
                    self.scratch.clear();
                }
                continue;
            }

            if self.eof {
                if self.start < self.end {
                    if self.scratch.is_empty() {
                        let mut slice = &self.buf[self.start..self.end];
                        if slice.last() == Some(&b'\r') {
                            slice = &slice[..slice.len() - 1];
                        }
                        self.start = self.end;
                        on_record(slice)?;
                    } else {
                        let chunk = self.buf[self.start..self.end].to_vec();
                        self.start = self.end;
                        self.append_to_scratch(&chunk)?;
                        if self.scratch.last() == Some(&b'\r') {
                            self.scratch.pop();
                        }
                        on_record(&self.scratch)?;
                        self.scratch.clear();
                    }
                } else if !self.scratch.is_empty() {
                    if self.scratch.last() == Some(&b'\r') {
                        self.scratch.pop();
                    }
                    on_record(&self.scratch)?;
                    self.scratch.clear();
                }
                break;
            }

            if self.start < self.end {
                let chunk = self.buf[self.start..self.end].to_vec();
                self.start = self.end;
                self.append_to_scratch(&chunk)?;
            }

            self.refill()?;
        }

        Ok(())
    }
}

impl StreamingParser<BufReader<File>> {
    pub fn from_file<P: AsRef<Path>>(
        path: P,
        capacity: usize,
        max_record_size: usize,
    ) -> io::Result<Self> {
        let file = File::open(path)?;
        Ok(Self::with_capacity(
            BufReader::with_capacity(capacity, file),
            capacity,
            max_record_size,
        ))
    }
}

pub fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut n = 0u64;
    for &b in bytes {
        if b < b'0' || b > b'9' {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

pub fn process_csv_like_record(record: &[u8]) -> io::Result<()> {
    let mut fields = record.split(|&b| b == b',');

    let key = fields.next().unwrap_or(&[]);
    let value = fields.next().unwrap_or(&[]);
    let timestamp = fields.next().unwrap_or(&[]);

    let ts = parse_u64_ascii(timestamp).unwrap_or(0);

    let _ = (key, value, ts);
    Ok(())
}

fn main() -> io::Result<()> {
    let mut parser = StreamingParser::from_file(
        "large_input.txt",
        1024 * 1024,
        16 * 1024 * 1024,
    )?;

    parser.process_all(|record| process_csv_like_record(record))?;
    Ok(())
}
