Below is an initial implementation in Rust of a high-throughput streaming parser designed for gigabyte-scale input with minimal memory overhead.

It is built around these principles:

- streaming from any `Read`
- fixed-size reusable buffer
- zero-copy parsing where possible
- incremental record extraction across chunk boundaries
- no full-file buffering
- simple callback-based consumption

This example parses newline-delimited records, but the structure is adaptable to CSV, log formats, framed protocols, etc.

---

## Features

- Handles arbitrarily large input streams
- Reuses a single buffer
- Correctly handles records split across read boundaries
- Avoids per-byte allocations
- Exposes records as borrowed slices when fully contained in the current buffer
- Falls back to a small carryover buffer only when a record spans chunks

---

## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - minimal allocations
/// - chunked reading
/// - support for records crossing chunk boundaries
/// - callback-based processing to avoid storing parsed output
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Box<[u8]>,
    start: usize,
    end: usize,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a reusable fixed-size buffer.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self {
            reader,
            buf: vec![0u8; capacity].into_boxed_slice(),
            start: 0,
            end: 0,
            carry: Vec::new(),
            eof: false,
        }
    }

    /// Fill internal buffer, compacting unconsumed bytes first.
    fn refill(&mut self) -> io::Result<usize> {
        if self.eof {
            return Ok(0);
        }

        // Compact remaining bytes to the front.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        }
        self.end += n;
        Ok(n)
    }

    /// Process all records separated by '\n'.
    ///
    /// The callback receives each record without the trailing newline.
    /// Records may be borrowed from the internal buffer or assembled in `carry`
    /// if they span multiple chunks.
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            // Search for complete lines in current buffer.
            while self.start < self.end {
                let slice = &self.buf[self.start..self.end];

                if let Some(pos) = memchr::memchr(b'\n', slice) {
                    let line = &slice[..pos];
                    self.start += pos + 1;

                    if self.carry.is_empty() {
                        on_record(line)?;
                    } else {
                        self.carry.extend_from_slice(line);
                        on_record(&self.carry)?;
                        self.carry.clear();
                    }
                } else {
                    // No newline in current slice; append to carry and refill.
                    self.carry.extend_from_slice(slice);
                    self.start = self.end;
                    break;
                }
            }

            if self.eof {
                if !self.carry.is_empty() {
                    on_record(&self.carry)?;
                    self.carry.clear();
                }
                return Ok(());
            }

            self.refill()?;
        }
    }
}

/// Example consumer that counts lines and bytes.
pub struct Stats {
    pub records: u64,
    pub bytes: u64,
}

impl Stats {
    pub fn new() -> Self {
        Self { records: 0, bytes: 0 }
    }

    pub fn consume(&mut self, record: &[u8]) {
        self.records += 1;
        self.bytes += record.len() as u64;
    }
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingParser::with_capacity(reader, 1024 * 1024);
    let mut stats = Stats::new();

    parser.parse_lines(|record| {
        // Replace this with real parsing logic.
        stats.consume(record);
        Ok(())
    })?;

    println!("records: {}", stats.records);
    println!("bytes: {}", stats.bytes);

    Ok(())
}
