    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal_hup;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *a, int n) {
    int rc = snprintf(dst, dstsz, fmt, a, n);
    if (rc < 0 || (size_t)rc >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int safe_snprintf2(char *dst, size_t dstsz, const char *fmt, const char *a) {
    int rc = snprintf(dst, dstsz, fmt, a);
    if (rc < 0 || (size_t)rc >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int touch_new_log(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, mode);
    if (fd < 0) return -1;
    if (close(fd) < 0) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations < 1) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
        return touch_new_log(cfg->log_path, cfg->create_mode);
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, i) < 0) {
            return -1;
        }
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return touch_new_log(cfg->log_path, cfg->create_mode);
}

static int maybe_rotate(const struct config *cfg) {
    uint64_t sz;
    if (file_size(cfg->log_path, &sz) < 0) {
        if (errno == ENOENT) {
            return touch_new_log(cfg->log_path, cfg->create_mode);
        }
        return -1;
    }

    if (sz >= cfg->max_size || g_force_rotate) {
        g_force_rotate = 0;
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-p poll_sec] [-m mode_octal] [-d]\n"
        "  -f <logfile>   Path to log file\n"
        "  -s <bytes>     Rotate when file reaches this size (default: %llu)\n"
        "  -n <count>     Number of rotated files to keep (default: %d)\n"
        "  -p <sec>       Poll interval in seconds (default: %d)\n"
        "  -m <octal>     Mode for newly created log file (default: 0644)\n"
        "  -d             Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_POLL_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < -2147483647L - 1L || v > 2147483647L) return -1;
    *out = (int)v;
    return 0;
}

static int parse_mode(const char *s, mode_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 8);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (mode_t)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg.daemonize = 0;
    cfg.create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg.log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return 1;
                }
                memcpy(cfg.log_path, optarg, strlen(optarg) + 1);
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) < 0 || cfg.max_size == 0) {
                    fprintf(stderr, "invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) < 0 || cfg.max_rotations < 0 || cfg.max_rotations > 9999) {
                    fprintf(stderr, "invalid rotation count\n");
                    return 1;
                }
                break;
            case 'p':
                if (parse_int(optarg, &cfg.poll_interval_sec) < 0 || cfg.poll_interval_sec < 1 || cfg.poll_interval_sec > 3600) {
                    fprintf(stderr, "invalid poll interval\n");
                    return 1;
                }
                break;
            case 'm':
                if (parse_mode(optarg, &cfg.create_mode) < 0) {
                    fprintf(stderr, "invalid mode\n");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_terminate) {
        if (maybe_rotate(&cfg) < 0) {
            /* In constrained systems, avoid verbose logging loops.
               Sleep and retry. */
        }

        struct timespec ts;
        ts.tv_sec = cfg.poll_interval_sec;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            if (g_terminate) break;
        }
    }

    return 0;
}
