3. a **production-ready version with pidfile, syslog, and lockfile support**.

Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It avoids dynamic allocation in the hot path, uses fixed-size buffers, and rotates based on file size.

## Features
- Monitors one log file
- Rotates when size exceeds threshold
- Keeps `N` rotated files
- Uses fixed-size buffers
- Minimal heap usage
- Simple polling loop
- Optional daemonization

## Code

```c
/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate <logfile> <max_bytes> <keep_count> <poll_seconds> [--daemon]
 *
 * Example:
 *   ./memlogrotate /var/log/myapp.log 1048576 5 2 --daemon
 *
 * Notes:
 * - Rotates:
 *     logfile -> logfile.1
 *     logfile.1 -> logfile.2
 *     ...
 *     logfile.(keep_count-1) -> logfile.keep_count
 * - Oldest file is removed.
 * - This implementation uses polling, not inotify, to keep memory use simple/predictable.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_KEEP_COUNT 1000
#define LOGMSG_BUF 256

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_log(const char *fmt, ...) {
    char buf[LOGMSG_BUF];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len > 0) {
        (void)write(STDERR_FILENO, buf, len);
    }
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size_off(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(const char *base, unsigned index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *logfile, unsigned keep_count) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep_count == 0) {
        int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd >= 0) close(fd);
        return 0;
    }

    if (build_rotated_path(logfile, keep_count, oldp, sizeof(oldp)) != 0) {
        return -1;
    }
    (void)unlink(oldp);

    for (unsigned i = keep_count; i > 1; --i) {
        if (build_rotated_path(logfile, i - 1, oldp, sizeof(oldp)) != 0) {
            return -1;
        }
        if (build_rotated_path(logfile, i, newp, sizeof(newp)) != 0) {
            return -1;
        }

        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (build_rotated_path(logfile, 1, newp, sizeof(newp)) != 0) {
        return -1;
    }

    if (rename(logfile, newp) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    uint64_t v;
    if (parse_u64(s, &v) != 0 || v > UINT_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

static void install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    (void)sigaction(SIGINT, &sa, NULL);
    (void)sigaction(SIGTERM, &sa, NULL);
    (void)sigaction(SIGHUP, &sa, NULL);
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        dprintf(STDERR_FILENO,
                "Usage: %s <logfile> <max_bytes> <keep_count> <poll_seconds> [--daemon]\n",
                argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    uint64_t max_bytes = 0;
    unsigned keep_count = 0;
    unsigned poll_seconds = 0;
    bool do_daemon = false;

    if (parse_u64(argv[2], &max_bytes) != 0 || max_bytes == 0) {
        safe_log("Invalid max_bytes\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep_count) != 0 || keep_count > MAX_KEEP_COUNT) {
        safe_log("Invalid keep_count (max %d)\n", MAX_KEEP_COUNT);
        return 1;
    }

    if (parse_u32(argv[4], &poll_seconds) != 0 || poll_seconds == 0) {
        safe_log("Invalid poll_seconds\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            safe_log("Unknown option: %s\n", argv[5]);
            return 1;
        }
        do_daemon = true;
    }

    install_signals();

    if (do_daemon) {
        if (daemonize_process() != 0) {
            safe_log("Failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    while (!g_stop) {
        off_t sz = 0;
        if (file_size_off(logfile, &sz) == 0) {
            if ((uint64_t)sz >= max_bytes) {
                if (rotate_logs(logfile, keep_count) != 0) {
                    safe_log("Rotation failed for %s: %s\n", logfile, strerror(errno));
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            } else {
                safe_log("stat(%s) failed: %s\n", logfile, strerror(errno));
            }
        }

        for (unsigned i = 0; i < poll_seconds && !g_stop; ++i) {
            sleep(1);
        }
    }

    return 0;
}
