## Code: `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <limits.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 1
#define DEFAULT_MAX_FILES 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_files;
    unsigned int check_interval_sec;
    mode_t create_mode;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    }

    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int ensure_logfile_exists(const char *path, mode_t mode) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_files < 1) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
        return ensure_logfile_exists(cfg->log_path, cfg->create_mode);
    }

    if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_files) < 0) {
        return -1;
    }
    if (unlink(old_path) < 0 && errno != ENOENT) {
        return -1;
    }

    for (int i = cfg->max_files - 1; i >= 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return ensure_logfile_exists(cfg->log_path, cfg->create_mode);
}

static int should_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    return ((uint64_t)st.st_size >= cfg->max_size) ? 1 : 0;
}

static void sleep_interval(unsigned int sec) {
    struct timespec req, rem;
    req.tv_sec = sec;
    req.tv_nsec = 0;

    while (g_running && nanosleep(&req, &rem) < 0) {
        if (errno == EINTR) {
            req = rem;
            continue;
        }
        break;
    }
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> [max_size_bytes] [max_files] [check_interval_sec]\n"
        "Defaults:\n"
        "  max_size_bytes     = %llu\n"
        "  max_files          = %d\n"
        "  check_interval_sec = %d\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_FILES,
        DEFAULT_CHECK_INTERVAL_SEC);
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    unsigned long long v;

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v < 0 || v > 1000000) {
        errno = ERANGE;
        return -1;
    }
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_files = DEFAULT_MAX_FILES;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.create_mode = 0644;

    if (argc < 2 || argc > 5) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log_path too long\n");
        return 1;
    }
    memcpy(cfg.log_path, argv[1], strlen(argv[1]) + 1);

    if (argc >= 3) {
        if (parse_u64(argv[2], &cfg.max_size) < 0 || cfg.max_size == 0) {
            fprintf(stderr, "invalid max_size_bytes\n");
            return 1;
        }
    }

    if (argc >= 4) {
        if (parse_int(argv[3], &cfg.max_files) < 0) {
            fprintf(stderr, "invalid max_files\n");
            return 1;
        }
    }

    if (argc >= 5) {
        int tmp;
        if (parse_int(argv[4], &tmp) < 0 || tmp <= 0) {
            fprintf(stderr, "invalid check_interval_sec\n");
            return 1;
        }
        cfg.check_interval_sec = (unsigned int)tmp;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_logfile_exists(cfg.log_path, cfg.create_mode) < 0) {
        perror("ensure_logfile_exists");
        return 1;
    }

    while (g_running) {
        int r = should_rotate(&cfg);
        if (r < 0) {
            perror("should_rotate");
        } else if (r > 0) {
            if (rotate_logs(&cfg) < 0) {
                perror("rotate_logs");
            }
        }

        sleep_interval(cfg.check_interval_sec);
    }

    return 0;
}
