```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_INTERVAL_SEC 1
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    unsigned poll_interval_sec;
    int daemonize;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *a, int n) {
    int rc = snprintf(dst, dstsz, fmt, a, n);
    if (rc < 0 || (size_t)rc >= dstsz) {
        return -1;
    }
    return 0;
}

static int path_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations < 1) {
        return 0;
    }

    /* Remove the oldest file if it exists */
    if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, cfg->max_rotations) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    unlink(oldp);

    /* Shift N-1 down to 1 */
    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, i) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->log_path, i + 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (path_exists(oldp)) {
            if (rename(oldp, newp) != 0) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    if (safe_snprintf(newp, sizeof(newp), "%s.1", cfg->log_path, 0) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (path_exists(cfg->log_path)) {
        if (rename(cfg->log_path, newp) != 0) {
            return -1;
        }
    }

    /* Recreate empty active log */
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-p poll_sec] [-d]\n"
        "  -f <logfile>    Path to log file\n"
        "  -s <max_bytes>  Rotate when size >= max_bytes (default: %llu)\n"
        "  -n <rotations>  Number of rotated files to keep (default: %d)\n"
        "  -p <poll_sec>   Poll interval in seconds (default: %d)\n"
        "  -d              Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_POLL_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static int parse_uint(const char *s, unsigned *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v > 1000000UL) return -1;
    *out = (unsigned)v;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg.daemonize = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "Log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) != 0) {
                    fprintf(stderr, "Invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) != 0 || cfg.max_rotations < 1) {
                    fprintf(stderr, "Invalid rotations\n");
                    return 1;
                }
                break;
            case 'p':
                if (parse_uint(optarg, &cfg.poll_interval_sec) != 0 || cfg.poll_interval_sec < 1) {
                    fprintf(stderr, "Invalid poll interval\n");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    install_signal_handlers();

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            fprintf(stderr, "Failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        uint64_t size = 0;
        if (get_file_size(cfg.log_path, &size) == 0) {
            if (size >= cfg.max_size) {
                if (rotate_logs(&cfg) != 0) {
                    /* In a minimal daemon, avoid extra memory/logging complexity */
                    sleep(cfg.poll_interval_sec);
                    continue;
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(cfg.log_path, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            }
        }

        sleep(cfg.poll_interval_sec);
    }

    return 0;
}
