## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_FILES 5
#define DEFAULT_POLL_MS 1000
#define DEFAULT_MODE 0640

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int max_files;
    int poll_ms;
    mode_t create_mode;
    int daemonize;
    rlim_t mem_limit_bytes;
};

static void on_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static void install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);
}

static void msleep_int(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
    }
}

static int set_memory_limit(rlim_t bytes) {
    if (bytes == 0) return 0;
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int make_daemon(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > 2) close(fd);

    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_size(const char *s, off_t *out) {
    if (!s || !*s) return -1;

    char *end = NULL;
    unsigned long long base = strtoull(s, &end, 10);
    if (end == s) return -1;

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') return -1;
        switch (*end) {
            case 'k': case 'K': mult = 1024ULL; break;
            case 'm': case 'M': mult = 1024ULL * 1024ULL; break;
            case 'g': case 'G': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    unsigned long long total = base * mult;
    if (total > (unsigned long long)LLONG_MAX) return -1;
    *out = (off_t)total;
    return 0;
}

static int path_with_suffix(char *dst, size_t dstsz, const char *base, int suffix) {
    int n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_files < 1) {
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC | O_CREAT, cfg->create_mode);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->max_files) == 0) {
        unlink(oldp);
    }

    for (int i = cfg->max_files - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) != 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) != 0) return -1;
        rename(oldp, newp);
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) != 0) return -1;
    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_log_exists(cfg);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> -s <size> [-n max_files] [-p poll_ms] [-m mem_bytes] [-d]\n"
        "  -f <logfile>   Path to log file\n"
        "  -s <size>      Rotate threshold, e.g. 1048576, 10M, 256K\n"
        "  -n <files>     Number of rotated files to keep (default: %d)\n"
        "  -p <poll_ms>   Poll interval in milliseconds (default: %d)\n"
        "  -m <bytes>     Set RLIMIT_AS memory cap in bytes\n"
        "  -d             Daemonize\n",
        prog, DEFAULT_MAX_FILES, DEFAULT_POLL_MS);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_files = DEFAULT_MAX_FILES;
    cfg->poll_ms = DEFAULT_POLL_MS;
    cfg->create_mode = DEFAULT_MODE;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path))
                    return -1;
                break;
            case 's':
                if (parse_size(optarg, &cfg->max_size) != 0) return -1;
                break;
            case 'n':
                if (parse_int(optarg, &cfg->max_files) != 0) return -1;
                if (cfg->max_files < 0 || cfg->max_files > 1000) return -1;
                break;
            case 'p':
                if (parse_int(optarg, &cfg->poll_ms) != 0) return -1;
                if (cfg->poll_ms < 10 || cfg->poll_ms > 3600000) return -1;
                break;
            case 'm': {
                int tmp;
                if (parse_int(optarg, &tmp) != 0 || tmp <= 0) return -1;
                cfg->mem_limit_bytes = (rlim_t)tmp;
                break;
            }
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->max_size <= 0) return -1;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    install_signals();

    if (cfg.mem_limit_bytes > 0) {
        if (set_memory_limit(cfg.mem_limit_bytes) != 0) {
            dprintf(STDERR_FILENO, "failed to set memory limit: %s\n", strerror(errno));
            return 1;
        }
    }

    if (cfg.daemonize) {
        if (make_daemon() != 0) {
            dprintf(STDERR_FILENO, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    if (ensure_log_exists(&cfg) != 0) {
        dprintf(STDERR_FILENO, "failed to create log file: %s\n", strerror(errno));
        return 1;
    }

    while (g_running) {
        if (check_and_rotate(&cfg) != 0) {
            /* Sleep and retry; avoid noisy logging in constrained environments */
        }
        msleep_int(cfg.poll_ms);
    }

    return 0;
}
