## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>

#ifndef PATH_MAX_LEN
#define PATH_MAX_LEN 256
#endif

#ifndef SLEEP_SECS
#define SLEEP_SECS 5
#endif

#ifndef MAX_ROTATIONS
#define MAX_ROTATIONS 10
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    char log_path[PATH_MAX_LEN];
    off_t max_size;
    int rotations;
    unsigned sleep_secs;
    int daemonize;
} config_t;

static void safe_log_stderr(const char *msg) {
    if (msg) {
        write(STDERR_FILENO, msg, strlen(msg));
    }
}

static int parse_off_t(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    if (!s || !out) return -1;
    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (!s || !out) return -1;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (int)v;
    return 0;
}

static int path_with_suffix(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (!dst || !base || dst_sz == 0) return -1;
    n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX_LEN];
    char newp[PATH_MAX_LEN];
    int i;

    if (!cfg) return -1;
    if (cfg->rotations < 1 || cfg->rotations > MAX_ROTATIONS) return -1;

    /* Remove oldest */
    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->rotations) == 0) {
        unlink(oldp);
    }

    /* Shift N-1 down to 1 */
    for (i = cfg->rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) != 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) != 0) {
            return -1;
        }
        rename(oldp, newp);
    }

    /* Current log -> .1 */
    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) != 0) {
        if (errno == ENOENT) {
            return 0; /* nothing to rotate */
        }
        return -1;
    }

    /* Recreate empty log file */
    {
        int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static int needs_rotation(const config_t *cfg) {
    struct stat st;
    if (!cfg) return 0;
    if (stat(cfg->log_path, &st) != 0) {
        return 0;
    }
    return st.st_size >= cfg->max_size;
}

static int daemonize_process(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <max_size_bytes> [-n rotations] [-t sleep_secs] [-d]\n"
        "  -f logfile         Path to log file\n"
        "  -s max_size_bytes  Rotate when file reaches this size\n"
        "  -n rotations       Number of rotated files to keep (1-%d, default 5)\n"
        "  -t sleep_secs      Poll interval in seconds (default %d)\n"
        "  -d                 Daemonize\n",
        prog, MAX_ROTATIONS, SLEEP_SECS);
}

int main(int argc, char **argv) {
    config_t cfg;
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.rotations = 5;
    cfg.sleep_secs = SLEEP_SECS;
    cfg.daemonize = 0;

    while ((opt = getopt(argc, argv, "f:s:n:t:d")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg.log_path)) {
                    safe_log_stderr("log path too long\n");
                    return 1;
                }
                strncpy(cfg.log_path, optarg, sizeof(cfg.log_path) - 1);
                cfg.log_path[sizeof(cfg.log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_off_t(optarg, &cfg.max_size) != 0 || cfg.max_size <= 0) {
                    safe_log_stderr("invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.rotations) != 0 ||
                    cfg.rotations < 1 || cfg.rotations > MAX_ROTATIONS) {
                    safe_log_stderr("invalid rotations\n");
                    return 1;
                }
                break;
            case 't':
                {
                    int tmp;
                    if (parse_int(optarg, &tmp) != 0 || tmp <= 0) {
                        safe_log_stderr("invalid sleep secs\n");
                        return 1;
                    }
                    cfg.sleep_secs = (unsigned)tmp;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0' || cfg.max_size <= 0) {
        usage(argv[0]);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            safe_log_stderr("failed to daemonize\n");
            return 1;
        }
    }

    while (g_running) {
        if (needs_rotation(&cfg)) {
            if (rotate_logs(&cfg) != 0) {
                /* In daemon mode stderr goes to /dev/null */
                safe_log_stderr("rotation failed\n");
            }
        }
        sleep(cfg.sleep_secs);
    }

    return 0;
}
