Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It avoids dynamic allocation in the hot path, uses fixed-size buffers, and rotates logs by size with a configurable number of backups.

## Features
- Monitors one log file
- Rotates when file exceeds a size threshold
- Keeps `N` rotated backups
- Uses fixed-size buffers
- No heap allocation required in steady state
- Optional daemonization
- Low memory footprint

## Code

```c
/*
 * tinylogrot.c
 *
 * Memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic tinylogrot.c -o tinylogrot
 *
 * Usage:
 *   ./tinylogrot /path/to/logfile max_bytes backups interval_seconds [--daemon]
 *
 * Example:
 *   ./tinylogrot /var/log/myapp.log 1048576 5 2 --daemon
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 32
#define SLEEP_GRANULARITY_MS 200

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_snprintf(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (suffix < 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    }
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_size_off(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int fsync_parent_dir(const char *path) {
    char dirbuf[PATH_MAX];
    size_t len = strnlen(path, PATH_MAX);
    if (len == 0 || len >= sizeof(dirbuf)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    memcpy(dirbuf, path, len + 1);

    char *slash = strrchr(dirbuf, '/');
    if (slash == NULL) {
        strcpy(dirbuf, ".");
    } else if (slash == dirbuf) {
        slash[1] = '\0';
    } else {
        *slash = '\0';
    }

    int dfd = open(dirbuf, O_RDONLY | O_DIRECTORY);
    if (dfd < 0) return -1;
    int rc = fsync(dfd);
    close(dfd);
    return rc;
}

static int rotate_logs(const char *path, int backups) {
    if (backups < 1 || backups > MAX_BACKUPS) {
        errno = EINVAL;
        return -1;
    }

    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    /* Remove oldest backup if present */
    if (safe_snprintf(oldp, sizeof(oldp), path, backups) < 0) return -1;
    (void)unlink(oldp);

    /* Shift backups: path.(n-1) -> path.n */
    for (int i = backups - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (safe_snprintf(newp, sizeof(newp), path, i + 1) < 0) return -1;
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* Move current log to .1 if it exists */
    if (safe_snprintf(newp, sizeof(newp), path, 1) < 0) return -1;
    if (rename(path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    if (fsync(fd) < 0) {
        close(fd);
        return -1;
    }
    close(fd);

    (void)fsync_parent_dir(path);
    return 0;
}

static void sleep_interval(unsigned interval_seconds) {
    struct timespec req;
    req.tv_sec = 0;
    req.tv_nsec = SLEEP_GRANULARITY_MS * 1000000L;

    unsigned total_ms = interval_seconds * 1000U;
    unsigned elapsed = 0;

    while (g_running && elapsed < total_ms) {
        nanosleep(&req, NULL);
        elapsed += SLEEP_GRANULARITY_MS;
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < INT_MIN || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s /path/to/logfile max_bytes backups interval_seconds [--daemon]\n",
        prog);
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    uint64_t max_bytes = 0;
    int backups = 0;
    int interval = 0;
    bool do_daemon = false;

    if (parse_u64(argv[2], &max_bytes) < 0 || max_bytes == 0) {
        fprintf(stderr, "Invalid max_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &backups) < 0 || backups < 1 || backups > MAX_BACKUPS) {
        fprintf(stderr, "Invalid backups (1-%d)\n", MAX_BACKUPS);
        return 1;
    }

    if (parse_int(argv[4], &interval) < 0 || interval < 1) {
        fprintf(stderr, "Invalid interval_seconds\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            usage(argv[0]);
            return 1;
        }
        do_daemon = true;
    }

    if (strlen(log_path) >= PATH_MAX) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (do_daemon) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size_off(log_path, &sz) == 0) {
            if ((uint64_t)sz >= max_bytes) {
                if (rotate_logs(log_path, backups) < 0) {
                    /* In daemon mode stderr may be /dev/null; keep behavior simple */
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(log_path, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            }
        }

        sleep_interval((unsigned)interval);
    }

    return 0;
}
```

