/*
 * memlogrotate.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Example:
 *   ./memlogrotate /var/log/myapp.log 10485760 5 5
 *
 * Args:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *   argv[5] = optional mode: "rename" (default) or "copytruncate"
 *
 * Notes:
 * - rename mode is preferred if the writer reopens logs on SIGHUP or similar.
 * - copytruncate is useful if the writer keeps the file open and cannot reopen.
 * - This daemon uses fixed-size arrays and no malloc.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define COPY_BUF_SIZE 4096
#define LOG_MSG_SIZE  256

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_write_stderr(const char *msg) {
    if (!msg) return;
    size_t len = 0;
    while (msg[len] != '\0') len++;
    while (len > 0) {
        ssize_t n = write(STDERR_FILENO, msg, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            break;
        }
        msg += n;
        len -= (size_t)n;
    }
}

static void log_err(const char *fmt, ...) {
    char buf[LOG_MSG_SIZE];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n < 0) return;
    if ((size_t)n >= sizeof(buf)) {
        buf[sizeof(buf) - 2] = '\n';
        buf[sizeof(buf) - 1] = '\0';
    }
    safe_write_stderr(buf);
}

static int set_memory_limits(void) {
    struct rlimit rl;

    /* Address space limit: 16 MiB */
    rl.rlim_cur = 16 * 1024 * 1024;
    rl.rlim_max = 16 * 1024 * 1024;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }

    /* Data segment limit: 4 MiB */
    rl.rlim_cur = 4 * 1024 * 1024;
    rl.rlim_max = 4 * 1024 * 1024;
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        return -1;
    }

    /* Stack limit: 1 MiB */
    rl.rlim_cur = 1024 * 1024;
    rl.rlim_max = 1024 * 1024;
    if (setrlimit(RLIMIT_STACK, &rl) != 0) {
        return -1;
    }

    /* Limit open files */
    rl.rlim_cur = 16;
    rl.rlim_max = 16;
    if (setrlimit(RLIMIT_NOFILE, &rl) != 0) {
        return -1;
    }

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, unsigned idx) {
    if (!out || !base || out_sz == 0) return -1;
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int copy_file_contents(int src_fd, int dst_fd) {
    char buf[COPY_BUF_SIZE];
    for (;;) {
        ssize_t r = read(src_fd, buf, sizeof(buf));
        if (r == 0) break;
        if (r < 0) {
            if (errno == EINTR) continue;
            return -1;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dst_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                return -1;
            }
            off += w;
        }
    }
    return 0;
}

static int rotate_rename(const char *path, unsigned keep_count) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep_count == 0) {
        int fd = open(path, O_WRONLY | O_TRUNC);
        if (fd >= 0) close(fd);
        return 0;
    }

    if (build_rotated_path(oldp, sizeof(oldp), path, keep_count) != 0) return -1;
    unlink(oldp);

    for (unsigned i = keep_count; i > 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i - 1) != 0) return -1;
        if (build_rotated_path(newp, sizeof(newp), path, i) != 0) return -1;
        (void)rename(oldp, newp);
    }

    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) return -1;
    if (rename(path, newp) != 0) {
        return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_copytruncate(const char *path, unsigned keep_count) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int src_fd = -1, dst_fd = -1;
    int rc = -1;

    if (keep_count == 0) {
        src_fd = open(path, O_WRONLY);
        if (src_fd < 0) return -1;
        rc = ftruncate(src_fd, 0);
        close(src_fd);
        return rc;
    }

    if (build_rotated_path(oldp, sizeof(oldp), path, keep_count) != 0) return -1;
    unlink(oldp);

    for (unsigned i = keep_count; i > 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i - 1) != 0) return -1;
        if (build_rotated_path(newp, sizeof(newp), path, i) != 0) return -1;
        (void)rename(oldp, newp);
    }

    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) return -1;

    src_fd = open(path, O_RDONLY);
    if (src_fd < 0) goto out;

    dst_fd = open(newp, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dst_fd < 0) goto out;

    if (copy_file_contents(src_fd, dst_fd) != 0) goto out;

    close(dst_fd);
    dst_fd = -1;
    close(src_fd);
    src_fd = -1;

    src_fd = open(path, O_WRONLY);
    if (src_fd < 0) goto out;

    if (ftruncate(src_fd, 0) != 0) goto out;

    rc = 0;

out:
    if (src_fd >= 0) close(src_fd);
    if (dst_fd >= 0) close(dst_fd);
    return rc;
}

static int ensure_file_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    if (!s || !out) return -1;
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    uint64_t v;
    if (parse_u64(s, &v) != 0) return -1;
    if (v > 0xffffffffULL) return -1;
    *out = (unsigned)v;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        safe_write_stderr(
            "usage: memlogrotate <log_path> <max_bytes> <keep_count> <poll_sec> [rename|copytruncate]\n"
        );
        return 1;
    }

    const char *log_path = argv[1];
    uint64_t max_bytes = 0;
    unsigned keep_count = 0;
    unsigned poll_sec = 0;
    bool copytruncate = false;

    if (strlen(log_path) >= PATH_MAX) {
        safe_write_stderr("error: log path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_bytes) != 0 || max_bytes == 0) {
        safe_write_stderr("error: invalid max_bytes\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep_count) != 0) {
        safe_write_stderr("error: invalid keep_count\n");
        return 1;
    }

    if (parse_u32(argv[4], &poll_sec) != 0 || poll_sec == 0) {
        safe_write_stderr("error: invalid poll_sec\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "copytruncate") == 0) {
            copytruncate = true;
        } else if (strcmp(argv[5], "rename") == 0) {
            copytruncate = false;
        } else {
            safe_write_stderr("error: mode must be rename or copytruncate\n");
            return 1;
        }
    }

    if (ensure_file_exists(log_path) != 0) {
        log_err("error: cannot create/open log file: %s\n", strerror(errno));
        return 1;
    }

    if (set_memory_limits() != 0) {
        log_err("error: setrlimit failed: %s\n", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGTERM, &sa, NULL) != 0 ||
        sigaction(SIGINT,  &sa, NULL) != 0 ||
        sigaction(SIGHUP,  &sa, NULL) != 0) {
        log_err("error: sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (daemonize_self() != 0) {
        log_err("error: daemonize failed: %s\n", strerror(errno));
        return 1;
    }

    while (!g_stop) {
        struct stat st;
        if (stat(log_path, &st) == 0) {
            if ((uint64_t)st.st_size >= max_bytes) {
                int rc = copytruncate
                    ? rotate_copytruncate(log_path, keep_count)
                    : rotate_rename(log_path, keep_count);

                if (rc != 0) {
                    /* Best effort: sleep and retry later */
                }
            }
        } else {
            /* Recreate missing log file */
            (void)ensure_file_exists(log_path);
        }

        struct timespec ts;
        ts.tv_sec = (time_t)poll_sec;
        ts.tv_nsec = 0;

        while (nanosleep(&ts, &ts) != 0) {
            if (errno == EINTR) {
                if (g_stop) break;
                continue;
            }
            break;
        }
    }

    return 0;
}
