## Build

```bash
cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
```

---

## Run

Rotate `/var/log/myapp.log` when it reaches 10 MiB, keep 5 old files, check every 5 seconds:

```bash
./memlogrotate /var/log/myapp.log 10485760 5 5
```

Using copy-truncate mode:

```bash
./memlogrotate /var/log/myapp.log 10485760 5 5 copytruncate
```

---

## Memory-constrained design notes

Why this is memory-friendly:

- No `malloc()`/`free()`
- Small fixed buffers:
  - `4096` bytes for copying
  - `256` bytes for error messages
  - `PATH_MAX` path buffers on stack only during rotation
- Polling loop keeps no in-memory state besides a few scalars
- Low FD limit via `RLIMIT_NOFILE`
- Stack capped with `RLIMIT_STACK`

Approximate working memory is very small aside from libc/runtime overhead.

---

## Important caveats

### 1. `copytruncate` can lose data
If the application writes while the daemon is copying and truncating, some log lines may be duplicated or lost.

### 2. `rename` mode is safer
But it requires the log writer to reopen the file after rotation, otherwise it may continue writing to the renamed file.

### 3. `RLIMIT_AS` portability
`RLIMIT_AS` works on Linux but may behave differently on other Unix systems.

### 4. No compression
Compression usually increases memory usage. If you need strict memory limits, avoid gzip in-process.

---

## Possible improvements

If you want, I can also provide:

1. a **more production-safe version** with PID file and syslog support  
2. an **ultra-minimal version** under ~200 lines  
3. a **Rust implementation** with fixed-capacity buffers  
4. a version using **inotify** instead of polling  
5. a **multi-file rotation daemon** with static configuration limits

Below is a compact, memory-conscious log rotation daemon in C for Linux. It:

- Watches a single log file by polling `stat()`
- Rotates when size exceeds a threshold
- Keeps a fixed number of rotated files
- Uses no dynamic allocation
- Avoids buffering large data in memory
- Can optionally copy-truncate if the writer keeps the file open
- Runs as a daemon
- Tries to stay within strict memory constraints

## Features

- Fixed-size stack buffers only
- No heap allocations in normal operation
- Simple rename-based rotation:
  - `app.log` → `app.log.1`
  - `app.log.1` → `app.log.2`
  - etc.
- Optional `copytruncate` mode:
  - Copies current file to `.1`
  - Truncates original file in place
  - Useful when the logging process does not reopen logs after rename

---

## Code

```c
/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate /path/to/app.log max_bytes rotations interval_sec [copytruncate]
 *
 * Example:
 *   ./memlogrotate /var/log/app.log 10485760 5 2 0
 *
 * Arguments:
 *   log_path      - file to monitor
 *   max_bytes     - rotate when file size >= max_bytes
 *   rotations     - number of rotated files to keep
 *   interval_sec  - polling interval
 *   copytruncate  - 0 = rename rotation, 1 = copytruncate
 *
 * Notes:
 *   - rename rotation is more efficient, but requires the writer to reopen logs.
 *   - copytruncate works with writers that keep the file open, but may lose lines
 *     written during copy/truncate race windows.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/file.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define COPY_BUF_SIZE 4096
#define LOCKFILE_SUFFIX ".lock"

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int make_lockfile_path(const char *log_path, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s%s", log_path, LOCKFILE_SUFFIX);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int acquire_lock(const char *log_path) {
    char lockpath[PATH_MAX];
    if (make_lockfile_path(log_path, lockpath, sizeof(lockpath)) < 0) {
        return -1;
    }

    int fd = open(lockpath, O_CREAT | O_RDWR, 0644);
    if (fd < 0) return -1;

    if (flock(fd, LOCK_EX | LOCK_NB) < 0) {
        close(fd);
        return -1;
    }

    return fd; /* keep open for lifetime */
}

static int make_rotated_path(const char *base, unsigned idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int copy_file_contents(int src_fd, int dst_fd) {
    char buf[COPY_BUF_SIZE];

    for (;;) {
        ssize_t r = read(src_fd, buf, sizeof(buf));
        if (r == 0) break;
        if (r < 0) {
            if (errno == EINTR) continue;
            return -1;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dst_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                return -1;
            }
            off += w;
        }
    }

    return 0;
}

static int rotate_by_rename(const char *log_path, unsigned rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations == 0) {
        if (unlink(log_path) < 0 && errno != ENOENT) return -1;
        int fd = open(log_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    if (make_rotated_path(log_path, rotations, oldp, sizeof(oldp)) < 0) return -1;
    if (unlink(oldp) < 0 && errno != ENOENT) return -1;

    for (unsigned i = rotations; i > 1; --i) {
        if (make_rotated_path(log_path, i - 1, oldp, sizeof(oldp)) < 0) return -1;
        if (make_rotated_path(log_path, i, newp, sizeof(newp)) < 0) return -1;

        if (rename(oldp, newp) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (make_rotated_path(log_path, 1, newp, sizeof(newp)) < 0) return -1;

    if (rename(log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(log_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int rotate_by_copytruncate(const char *log_path, unsigned rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations == 0) {
        int fd = open(log_path, O_WRONLY);
        if (fd < 0) return -1;
        int rc = ftruncate(fd, 0);
        close(fd);
        return rc;
    }

    if (make_rotated_path(log_path, rotations, oldp, sizeof(oldp)) < 0) return -1;
    if (unlink(oldp) < 0 && errno != ENOENT) return -1;

    for (unsigned i = rotations; i > 1; --i) {
        if (make_rotated_path(log_path, i - 1, oldp, sizeof(oldp)) < 0) return -1;
        if (make_rotated_path(log_path, i, newp, sizeof(newp)) < 0) return -1;
        if (rename(oldp, newp) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (make_rotated_path(log_path, 1, newp, sizeof(newp)) < 0) return -1;

    int src_fd = open(log_path, O_RDONLY);
    if (src_fd < 0) return -1;

    struct stat st;
    if (fstat(src_fd, &st) < 0) {
        close(src_fd);
        return -1;
    }

    int dst_fd = open(newp, O_CREAT | O_WRONLY | O_TRUNC, st.st_mode & 0777);
    if (dst_fd < 0) {
        close(src_fd);
        return -1;
    }

    int rc = copy_file_contents(src_fd, dst_fd);
    if (rc == 0) {
        if (fsync(dst_fd) < 0) rc = -1;
    }

    close(dst_fd);
    close(src_fd);

    if (rc < 0) return -1;

    int wr_fd = open(log_path, O_WRONLY);
    if (wr_fd < 0) return -1;

    rc = ftruncate(wr_fd, 0);
    close(wr_fd);
    return rc;
}

static int should_rotate(const char *log_path, off_t max_bytes, bool *result) {
    struct stat st;
    if (stat(log_path, &st) < 0) {
        if (errno == ENOENT) {
            *result = false;
            return 0;
        }
        return -1;
    }

    *result = (st.st_size >= max_bytes);
    return 0;
}

static int ensure_log_exists(const char *log_path) {
    int fd = open(log_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s log_path max_bytes rotations interval_sec copytruncate\n"
        "  log_path      path to log file\n"
        "  max_bytes     rotate when size >= this value\n"
        "  rotations     number of rotated files to keep\n"
        "  interval_sec  polling interval in seconds\n"
        "  copytruncate  0 or 1\n",
        prog);
}

int main(int argc, char **argv) {
    if (argc != 6) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];

    errno = 0;
    char *end = NULL;
    unsigned long long max_bytes_ull = strtoull(argv[2], &end, 10);
    if (errno || !end || *end != '\0' || max_bytes_ull == 0 ||
        max_bytes_ull > (unsigned long long)LLONG_MAX) {
        usage(argv[0]);
        return 1;
    }

    errno = 0;
    end = NULL;
    unsigned long rotations_ul = strtoul(argv[3], &end, 10);
    if (errno || !end || *end != '\0' || rotations_ul > 1000UL) {
        usage(argv[0]);
        return 1;
    }

    errno = 0;
    end = NULL;
    unsigned long interval_ul = strtoul(argv[4], &end, 10);
    if (errno || !end || *end != '\0' || interval_ul == 0 || interval_ul > 86400UL) {
        usage(argv[0]);
        return 1;
    }

    errno = 0;
    end = NULL;
    unsigned long copytruncate_ul = strtoul(argv[5], &end, 10);
    if (errno || !end || *end != '\0' || copytruncate_ul > 1UL) {
        usage(argv[0]);
        return 1;
    }

    off_t max_bytes = (off_t)max_bytes_ull;
    unsigned rotations = (unsigned)rotations_ul;
    unsigned interval_sec = (unsigned)interval_ul;
    bool copytruncate = (copytruncate_ul != 0);

    if (install_signals() < 0) {
        log_stderr("failed to install signal handlers");
        return 1;
    }

    if (ensure_log_exists(log_path) < 0) {
        log_stderr("failed to create/open log file: %s", strerror(errno));
        return 1;
    }

    int lock_fd = acquire_lock(log_path);
    if (lock_fd < 0) {
        log_stderr("another instance may be running, or lock failed");
        return 1;
    }

    if (daemonize_process() < 0) {
        log_stderr("failed to daemonize");
        close(lock_fd);
        return 1;
    }

    while (!g_stop) {
        bool rotate = false;

        if (should_rotate(log_path, max_bytes, &rotate) == 0 && rotate) {
            if (copytruncate) {
                (void)rotate_by_copytruncate(log_path, rotations);
            } else {
                (void)rotate_by_rename(log_path, rotations);
            }
        } else {
            (void)ensure_log_exists(log_path);
        }

        for (unsigned i = 0; i < interval_sec && !g_stop; ++i) {
            sleep(1);
        }
    }

    close(lock_fd);
    return 0;
}
