## C Code

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd /var/log/app.log 10485760 5 2
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Notes:
 * - Uses polling to avoid inotify complexity and memory overhead.
 * - Assumes single log file target.
 * - Best used when the writer keeps appending to the same pathname.
 * - If the writer keeps the old file descriptor open after rename,
 *   it may continue writing to the rotated file. In that case, the
 *   writer should reopen logs on SIGHUP or use copytruncate logic
 *   instead (not implemented here to keep memory and code small).
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define PIDFILE_MODE 0644

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

static void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int keep_count;
    unsigned int poll_interval;
};

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_uint(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v > UINT_MAX) return -1;
    *out = (unsigned int)v;
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (suffix >= 0) {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    } else {
        n = snprintf(dst, dst_sz, "%s", base);
    }
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->keep_count <= 0) {
        /* No backups requested: just truncate current file */
        int fd = open(cfg->log_path, O_WRONLY);
        if (fd < 0) return -1;
        int rc = ftruncate(fd, 0);
        close(fd);
        return rc;
    }

    /* Remove the oldest if it exists */
    if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, cfg->keep_count) < 0) {
        return -1;
    }
    (void)unlink(oldp);

    /* Shift N-1 down to 1 upward */
    for (int i = cfg->keep_count - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, i) < 0) return -1;
        if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, i + 1) < 0) return -1;
        (void)rename(oldp, newp);
    }

    /* Rename current log to .1 */
    if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, 1) < 0) return -1;
    if (rename(cfg->log_path, newp) < 0) {
        return -1;
    }

    /* Recreate empty log file with conservative permissions */
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            /* Create missing log file */
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
            "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_interval_sec>\n",
            prog);
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));

    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        dprintf(STDERR_FILENO, "log path too long\n");
        return 1;
    }
    memcpy(cfg.log_path, argv[1], strlen(argv[1]) + 1);

    uint64_t max_size_u64 = 0;
    if (parse_u64(argv[2], &max_size_u64) < 0 || max_size_u64 == 0) {
        dprintf(STDERR_FILENO, "invalid max_size_bytes\n");
        return 1;
    }
    if (max_size_u64 > (uint64_t)LLONG_MAX) {
        dprintf(STDERR_FILENO, "max_size_bytes too large\n");
        return 1;
    }
    cfg.max_size = (off_t)max_size_u64;

    if (parse_int(argv[3], &cfg.keep_count) < 0) {
        dprintf(STDERR_FILENO, "invalid keep_count\n");
        return 1;
    }

    if (parse_uint(argv[4], &cfg.poll_interval) < 0 || cfg.poll_interval == 0) {
        dprintf(STDERR_FILENO, "invalid poll_interval_sec\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        dprintf(STDERR_FILENO, "failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (daemonize_self() < 0) {
        return 1;
    }

    while (!g_terminate) {
        (void)check_and_rotate(&cfg);

        if (g_reload) {
            /* Placeholder for config reload if desired */
            g_reload = 0;
        }

        unsigned int remaining = cfg.poll_interval;
        while (remaining > 0 && !g_terminate) {
            remaining = sleep(remaining);
        }
    }

    return 0;
}
```

