## Code: `logrotated.c`

```c
/*
 * logrotated.c
 *
 * Memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c99 -Wall -Wextra -o logrotated logrotated.c
 *
 * Example:
 *   ./logrotated -i 5 -s 1048576 -k 4 /var/log/app.log /var/log/other.log
 *
 * Options:
 *   -i <seconds>   Poll interval
 *   -s <bytes>     Rotate when file size exceeds this threshold
 *   -k <count>     Number of rotated files to keep
 *   -n             Do not daemonize
 *
 * Constraints:
 *   - No heap allocation
 *   - Fixed maximum number of files and path lengths
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 256
#endif

#define MAX_LOGS        16
#define MAX_ROTATIONS   32
#define DEFAULT_INTERVAL 5
#define DEFAULT_KEEP     4
#define DEFAULT_SIZE     (1024 * 1024)

static volatile sig_atomic_t g_running = 1;

struct log_target {
    char path[PATH_MAX];
};

struct config {
    unsigned interval_sec;
    off_t rotate_size;
    unsigned keep_count;
    bool nodaemon;
    unsigned log_count;
    struct log_target logs[MAX_LOGS];
};

static void on_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static void safe_perror(const char *msg, const char *path) {
    if (path) {
        fprintf(stderr, "%s: %s: %s\n", msg, path, strerror(errno));
    } else {
        fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    }
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") < 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (fd != STDIN_FILENO) dup2(fd, STDIN_FILENO);
    if (fd != STDOUT_FILENO) dup2(fd, STDOUT_FILENO);
    if (fd != STDERR_FILENO) dup2(fd, STDERR_FILENO);

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    char *end = NULL;
    unsigned long v;

    if (!s || !*s) return -1;
    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno || *end != '\0' || v > UINT_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    unsigned long long v;

    if (!s || !*s) return -1;
    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno || *end != '\0') return -1;
    *out = (off_t)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-n] [-i seconds] [-s bytes] [-k keep] <log1> [log2 ...]\n",
        prog);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;
    unsigned u;
    off_t sz;

    cfg->interval_sec = DEFAULT_INTERVAL;
    cfg->rotate_size = DEFAULT_SIZE;
    cfg->keep_count = DEFAULT_KEEP;
    cfg->nodaemon = false;
    cfg->log_count = 0;

    while ((opt = getopt(argc, argv, "ni:s:k:")) != -1) {
        switch (opt) {
            case 'n':
                cfg->nodaemon = true;
                break;
            case 'i':
                if (parse_u32(optarg, &u) != 0 || u == 0) return -1;
                cfg->interval_sec = u;
                break;
            case 's':
                if (parse_offt(optarg, &sz) != 0 || sz <= 0) return -1;
                cfg->rotate_size = sz;
                break;
            case 'k':
                if (parse_u32(optarg, &u) != 0 || u == 0 || u > MAX_ROTATIONS) return -1;
                cfg->keep_count = u;
                break;
            default:
                return -1;
        }
    }

    for (int i = optind; i < argc; i++) {
        if (cfg->log_count >= MAX_LOGS) {
            fprintf(stderr, "Too many log files; max=%d\n", MAX_LOGS);
            return -1;
        }
        if (snprintf(cfg->logs[cfg->log_count].path,
                     sizeof(cfg->logs[cfg->log_count].path),
                     "%s", argv[i]) >= (int)sizeof(cfg->logs[cfg->log_count].path)) {
            fprintf(stderr, "Path too long: %s\n", argv[i]);
            return -1;
        }
        cfg->log_count++;
    }

    if (cfg->log_count == 0) {
        return -1;
    }

    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, unsigned suffix) {
    int n = snprintf(out, out_sz, "%s.%u", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_one(const char *path, unsigned keep_count) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep_count == 0 || keep_count > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    /* Remove oldest */
    if (path_with_suffix(oldp, sizeof(oldp), path, keep_count) != 0) {
        return -1;
    }
    (void)unlink(oldp);

    /* Shift N-1 -> N down to 1 -> 2 */
    for (unsigned i = keep_count; i > 1; i--) {
        if (path_with_suffix(oldp, sizeof(oldp), path, i - 1) != 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), path, i) != 0) {
            return -1;
        }
        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Move active log to .1 */
    if (path_with_suffix(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }
    if (rename(path, newp) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty active log */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int check_and_rotate(const struct log_target *t, off_t rotate_size, unsigned keep_count) {
    struct stat st;

    if (stat(t->path, &st) != 0) {
        if (errno == ENOENT) {
            /* Create missing file */
            int fd = open(t->path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= rotate_size) {
        return rotate_one(t->path, keep_count);
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    struct sigaction sa;
    unsigned i;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        safe_perror("sigaction", NULL);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        safe_perror("sigaction", NULL);
        return 1;
    }

    if (!cfg.nodaemon) {
        if (daemonize_self() != 0) {
            safe_perror("daemonize", NULL);
            return 1;
        }
    }

    while (g_running) {
        for (i = 0; i < cfg.log_count; i++) {
            if (check_and_rotate(&cfg.logs[i], cfg.rotate_size, cfg.keep_count) != 0) {
                /* In daemon mode stderr goes to /dev/null; in -n mode user sees it */
                safe_perror("rotate/check failed", cfg.logs[i].path);
            }
        }

        for (unsigned slept = 0; g_running && slept < cfg.interval_sec; slept++) {
            sleep(1);
        }
    }

    return 0;
}
