    off_t max_size;
    unsigned scan_interval;
    unsigned max_rotations;
    int daemonize;
    int verbose;
} config_t;

typedef struct {
    char name[MAX_NAME];
} file_entry_t;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static void log_msg(const config_t *cfg, const char *msg) {
    if (cfg->verbose) {
        write(STDERR_FILENO, msg, strlen(msg));
        write(STDERR_FILENO, "\n", 1);
    }
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    int n;
    va_start(ap, fmt);
    n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int is_regular_file(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return 0;
    }
    if (!S_ISREG(st.st_mode)) {
        return 0;
    }
    if (size_out) {
        *size_out = st.st_size;
    }
    return 1;
}

static int rotate_one(const config_t *cfg, const char *dir, const char *name) {
    char src[PATH_MAX];
    char dst[PATH_MAX];
    char msg[PATH_MAX + 64];
    unsigned i;

    if (cfg->max_rotations == 0) {
        if (safe_snprintf(src, sizeof(src), "%s/%s", dir, name) != 0) {
            return -1;
        }
        int fd = open(src, O_WRONLY | O_TRUNC);
        if (fd >= 0) {
            close(fd);
            if (cfg->verbose) {
                safe_snprintf(msg, sizeof(msg), "truncated %s", src);
                log_msg(cfg, msg);
            }
            return 0;
        }
        return -1;
    }

    if (safe_snprintf(src, sizeof(src), "%s/%s.%u", dir, name, cfg->max_rotations) != 0) {
        return -1;
    }
    unlink(src);

    for (i = cfg->max_rotations; i > 1; --i) {
        if (safe_snprintf(src, sizeof(src), "%s/%s.%u", dir, name, i - 1) != 0) {
            return -1;
        }
        if (safe_snprintf(dst, sizeof(dst), "%s/%s.%u", dir, name, i) != 0) {
            return -1;
        }
        rename(src, dst);
    }

    if (safe_snprintf(src, sizeof(src), "%s/%s", dir, name) != 0) {
        return -1;
    }
    if (safe_snprintf(dst, sizeof(dst), "%s/%s.1", dir, name) != 0) {
        return -1;
    }

    if (rename(src, dst) != 0) {
        return -1;
    }

    int fd = open(src, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    if (cfg->verbose) {
        safe_snprintf(msg, sizeof(msg), "rotated %s", src);
        log_msg(cfg, msg);
    }

    return 0;
}

static int should_skip_name(const char *name) {
    size_t len = strlen(name);
    if (len == 0) return 1;
    if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) return 1;

    /* Skip already rotated files like *.1, *.2, etc. */
    const char *dot = strrchr(name, '.');
    if (dot && dot[1] != '\0') {
        int all_digits = 1;
        const char *p = dot + 1;
        while (*p) {
            if (*p < '0' || *p > '9') {
                all_digits = 0;
                break;
            }
            ++p;
        }
        if (all_digits) return 1;
    }

    return 0;
}

static size_t scan_dir(const config_t *cfg, file_entry_t *files, size_t max_files) {
    DIR *d;
    struct dirent *de;
    size_t count = 0;

    d = opendir(cfg->dir);
    if (!d) {
        return 0;
    }

    while ((de = readdir(d)) != NULL) {
        if (count >= max_files) {
            break;
        }

        if (should_skip_name(de->d_name)) {
            continue;
        }

        size_t len = strnlen(de->d_name, MAX_NAME);
        if (len == 0 || len >= MAX_NAME) {
            continue;
        }

        memcpy(files[count].name, de->d_name, len);
        files[count].name[len] = '\0';
        count++;
    }

    closedir(d);
    return count;
}

static void process_files(const config_t *cfg, file_entry_t *files, size_t count) {
    char path[PATH_MAX];
    off_t size;
    size_t i;

    for (i = 0; i < count; ++i) {
        if (safe_snprintf(path, sizeof(path), "%s/%s", cfg->dir, files[i].name) != 0) {
            continue;
        }

        if (!is_regular_file(path, &size)) {
            continue;
        }

        if (size >= cfg->max_size) {
            rotate_one(cfg, cfg->dir, files[i].name);
        }
    }
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -d <dir> [-s max_size_bytes] [-i scan_seconds] [-r rotations] [-D] [-v]\n"
        "  -d directory to monitor\n"
        "  -s max file size before rotation (default %d)\n"
        "  -i scan interval seconds (default %d)\n"
        "  -r number of rotated files to keep (default %d)\n"
        "  -D daemonize\n"
        "  -v verbose\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_SCAN_INTERVAL, DEFAULT_MAX_ROTATIONS);
}

static int parse_u32(const char *s, unsigned *out) {
    char *end = NULL;
    unsigned long v;
    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno || !end || *end != '\0' || v > UINT32_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;
    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno || !end || *end != '\0' || v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    file_entry_t files[MAX_FILES];
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.scan_interval = DEFAULT_SCAN_INTERVAL;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;

    while ((opt = getopt(argc, argv, "d:s:i:r:Dv")) != -1) {
        switch (opt) {
            case 'd':
                if (strlen(optarg) >= sizeof(cfg.dir)) {
                    fprintf(stderr, "directory path too long\n");
                    return 1;
                }
                strcpy(cfg.dir, optarg);
                break;
            case 's':
                if (parse_offt(optarg, &cfg.max_size) != 0) {
                    fprintf(stderr, "invalid max size\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_u32(optarg, &cfg.scan_interval) != 0 || cfg.scan_interval == 0) {
                    fprintf(stderr, "invalid scan interval\n");
                    return 1;
                }
                break;
            case 'r':
                if (parse_u32(optarg, &cfg.max_rotations) != 0) {
                    fprintf(stderr, "invalid rotation count\n");
                    return 1;
                }
                break;
            case 'D':
                cfg.daemonize = 1;
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.dir[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    install_signals();

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            fprintf(stderr, "failed to daemonize\n");
            return 1;
        }
    }

    while (g_running) {
        size_t count = scan_dir(&cfg, files, MAX_FILES);
        process_files(&cfg, files, count);

        for (unsigned slept = 0; g_running && slept < cfg.scan_interval; ++slept) {
            sleep(1);
        }
    }

    return 0;
}
```

