## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOG_PATH 1024
#define MAX_ROTATIONS 16
#define DEFAULT_SLEEP_SEC 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[MAX_LOG_PATH];
    size_t max_size;
    int max_rotations;
    unsigned sleep_sec;
    int daemonize;
} config_t;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_write_stderr(const char *msg) {
    if (!msg) return;
    size_t len = 0;
    while (msg[len] != '\0') len++;
    while (len > 0) {
        ssize_t n = write(STDERR_FILENO, msg, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            break;
        }
        msg += n;
        len -= (size_t)n;
    }
}

static void log_err(const char *fmt, ...) {
    char buf[256];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n < 0) return;
    if ((size_t)n >= sizeof(buf)) {
        buf[sizeof(buf) - 2] = '\n';
        buf[sizeof(buf) - 1] = '\0';
    }
    safe_write_stderr(buf);
}

static int parse_size(const char *s, size_t *out) {
    if (!s || !out) return -1;

    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) return -1;

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') return -1;
        switch (*end) {
            case 'k': case 'K': mult = 1024ULL; break;
            case 'm': case 'M': mult = 1024ULL * 1024ULL; break;
            case 'g': case 'G': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    unsigned long long total = v * mult;
    if (total > (unsigned long long)SIZE_MAX) return -1;
    *out = (size_t)total;
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int idx) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) return -1;
    *sz = st.st_size;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[MAX_LOG_PATH + 32];
    char newp[MAX_LOG_PATH + 32];

    if (cfg->max_rotations < 1 || cfg->max_rotations > MAX_ROTATIONS) {
        return -1;
    }

    if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, cfg->max_rotations) != 0) {
        log_err("path too long\n");
        return -1;
    }
    unlink(oldp);

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, i) != 0) {
            log_err("path too long\n");
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), cfg->log_path, i + 1) != 0) {
            log_err("path too long\n");
            return -1;
        }
        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                log_err("rename %s -> %s failed: %s\n", oldp, newp, strerror(errno));
            }
        }
    }

    if (build_rotated_path(newp, sizeof(newp), cfg->log_path, 1) != 0) {
        log_err("path too long\n");
        return -1;
    }

    if (rename(cfg->log_path, newp) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_err("rename %s -> %s failed: %s\n", cfg->log_path, newp, strerror(errno));
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        log_err("recreate %s failed: %s\n", cfg->log_path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int maybe_rotate(const config_t *cfg) {
    off_t sz = 0;
    if (file_size(cfg->log_path, &sz) != 0) {
        if (errno != ENOENT) {
            log_err("stat %s failed: %s\n", cfg->log_path, strerror(errno));
        }
        return 0;
    }

    if ((uintmax_t)sz >= (uintmax_t)cfg->max_size) {
        return rotate_logs(cfg);
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > 2) close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s maxsize] [-n rotations] [-t sleepsec] [-d]\n"
        "  -f logfile     Path to log file\n"
        "  -s maxsize     Rotate at size, e.g. 1048576, 10M, 512K\n"
        "  -n rotations   Number of rotated files to keep (1-%d)\n"
        "  -t sleepsec    Poll interval in seconds\n"
        "  -d             Daemonize\n",
        prog, MAX_ROTATIONS);
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = 5;
    cfg->sleep_sec = DEFAULT_SLEEP_SEC;
    cfg->daemonize = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:t:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    log_err("log path too long\n");
                    return -1;
                }
                memcpy(cfg->log_path, optarg, strlen(optarg) + 1);
                break;
            case 's':
                if (parse_size(optarg, &cfg->max_size) != 0 || cfg->max_size == 0) {
                    log_err("invalid size: %s\n", optarg);
                    return -1;
                }
                break;
            case 'n':
                cfg->max_rotations = atoi(optarg);
                if (cfg->max_rotations < 1 || cfg->max_rotations > MAX_ROTATIONS) {
                    log_err("rotations must be 1-%d\n", MAX_ROTATIONS);
                    return -1;
                }
                break;
            case 't':
                cfg->sleep_sec = (unsigned)atoi(optarg);
                if (cfg->sleep_sec == 0) {
                    log_err("sleepsec must be > 0\n");
                    return -1;
                }
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        usage(argv[0]);
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    if (parse_args(argc, argv, &cfg) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            log_err("daemonize failed: %s\n", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        (void)maybe_rotate(&cfg);

        struct timespec ts;
        ts.tv_sec = cfg.sleep_sec;
        ts.tv_nsec = 0;

        while (nanosleep(&ts, &ts) != 0) {
            if (errno == EINTR) {
                if (!g_running) break;
                continue;
            }
            break;
        }
    }

    return 0;
}
