If you want, I can also provide a stricter memory-bounded `copytruncate` implementation that:
- copies current log to `.1`
- truncates original in place
- helps with writers that do not reopen file descriptors

That version is a bit more I/O heavy but often more practical.

Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits.

Features:
- No dynamic allocation in steady state
- Fixed-size buffers
- Rotates when file exceeds a size threshold
- Keeps N rotated files
- Optional periodic fsync
- Simple polling loop, no heavy dependencies
- Can run as a daemon
- Reopens log if file is replaced externally

Assumptions:
- You want to rotate a single log file
- Rotation naming: `log`, `log.1`, `log.2`, ..., `log.N`
- This daemon does not compress logs
- It does not parse the log stream; it only monitors file size

## C code

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 1000 -d
 *
 * Options:
 *   -f <path>     Log file path
 *   -s <bytes>    Rotate when size >= bytes
 *   -n <count>    Number of rotated files to keep
 *   -i <ms>       Poll interval in milliseconds
 *   -d            Daemonize
 *   -y            fsync after rotation
 *
 * Notes:
 *   - Uses fixed-size buffers only.
 *   - Avoids malloc/calloc/realloc.
 *   - Intended for low-memory environments.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_MS 1000
#define DEFAULT_ROTATIONS   5
#define MAX_ROTATIONS       100
#define MIN_INTERVAL_MS     100

static volatile sig_atomic_t g_stop = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    int interval_ms;
    int daemonize;
    int do_fsync;
};

struct file_state {
    dev_t dev;
    ino_t ino;
    off_t size;
    int valid;
};

static void on_signal_stop(int signo) {
    (void)signo;
    g_stop = 1;
}

static void on_signal_reload(int signo) {
    (void)signo;
    g_reload = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));

    sa.sa_handler = on_signal_stop;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;

    sa.sa_handler = on_signal_reload;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno || end == s || *end != '\0') return -1;
    if (v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <path> -s <bytes> [-n <count>] [-i <ms>] [-d] [-y]\n",
        prog);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->interval_ms = DEFAULT_INTERVAL_MS;

    while ((opt = getopt(argc, argv, "f:s:n:i:dy")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) return -1;
                strcpy(cfg->log_path, optarg);
                break;
            case 's':
                if (parse_offt(optarg, &cfg->max_size) < 0) return -1;
                break;
            case 'n':
                if (parse_int(optarg, &cfg->rotations) < 0) return -1;
                break;
            case 'i':
                if (parse_int(optarg, &cfg->interval_ms) < 0) return -1;
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'y':
                cfg->do_fsync = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    if (cfg->max_size <= 0) return -1;
    if (cfg->rotations < 1 || cfg->rotations > MAX_ROTATIONS) return -1;
    if (cfg->interval_ms < MIN_INTERVAL_MS) return -1;

    return 0;
}

static int stat_file(const char *path, struct file_state *st) {
    struct stat sb;
    if (stat(path, &sb) < 0) return -1;
    st->dev = sb.st_dev;
    st->ino = sb.st_ino;
    st->size = sb.st_size;
    st->valid = 1;
    return 0;
}

static int same_file(const struct file_state *a, const struct file_state *b) {
    return a->valid && b->valid && a->dev == b->dev && a->ino == b->ino;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int sync_parent_dir(const char *path) {
    char dirbuf[PATH_MAX];
    char *slash;
    int dfd;

    if (strlen(path) >= sizeof(dirbuf)) return -1;
    strcpy(dirbuf, path);

    slash = strrchr(dirbuf, '/');
    if (slash == NULL) {
        strcpy(dirbuf, ".");
    } else if (slash == dirbuf) {
        slash[1] = '\0';
    } else {
        *slash = '\0';
    }

    dfd = open(dirbuf, O_RDONLY | O_DIRECTORY);
    if (dfd < 0) return -1;
    if (fsync(dfd) < 0) {
        close(dfd);
        return -1;
    }
    close(dfd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    if (cfg->rotations >= 1) {
        if (build_rotated_path(cfg->log_path, cfg->rotations, oldp, sizeof(oldp)) < 0)
            return -1;
        (void)unlink(oldp);
    }

    for (i = cfg->rotations - 1; i >= 1; --i) {
        if (build_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) < 0)
            return -1;
        if (build_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) < 0)
            return -1;
        (void)rename(oldp, newp);
    }

    if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) < 0)
        return -1;

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    {
        int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        if (cfg->do_fsync) {
            (void)fsync(fd);
        }
        close(fd);
    }

    if (cfg->do_fsync) {
        (void)sync_parent_dir(cfg->log_path);
    }

    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
        if (g_stop) break;
    }
}

static int run_loop(const struct config *cfg) {
    struct file_state prev;
    struct file_state cur;

    memset(&prev, 0, sizeof(prev));
    memset(&cur, 0, sizeof(cur));

    for (;;) {
        if (g_stop) break;

        if (stat_file(cfg->log_path, &cur) == 0) {
            if (!same_file(&prev, &cur)) {
                prev = cur;
            } else {
                prev.size = cur.size;
            }

            if (cur.size >= cfg->max_size) {
                if (rotate_logs(cfg) == 0) {
                    memset(&prev, 0, sizeof(prev));
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
                if (fd >= 0) close(fd);
            }
        }

        if (g_reload) {
            g_reload = 0;
            memset(&prev, 0, sizeof(prev));
        }

        sleep_ms(cfg->interval_ms);
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (run_loop(&cfg) < 0) {
        return 1;
    }

    return 0;
}
```

