## `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#ifndef PATH_MAX_LEN
#define PATH_MAX_LEN 256
#endif

#ifndef DEFAULT_CHECK_INTERVAL_SEC
#define DEFAULT_CHECK_INTERVAL_SEC 5
#endif

#ifndef DEFAULT_MAX_ROTATIONS
#define DEFAULT_MAX_ROTATIONS 5
#endif

#ifndef DEFAULT_MAX_FILE_SIZE
#define DEFAULT_MAX_FILE_SIZE (10 * 1024 * 1024)
#endif

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX_LEN];
    size_t max_file_size;
    int max_rotations;
    unsigned check_interval_sec;
    mode_t create_mode;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int safe_snprintf(char *dst, size_t dst_sz, const char *fmt, const char *a, int b) {
    int n = snprintf(dst, dst_sz, fmt, a, b);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int path_with_suffix(char *dst, size_t dst_sz, const char *base, int suffix) {
    return safe_snprintf(dst, dst_sz, "%s.%d", base, suffix);
}

static off_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return -1;
    }
    return st.st_size;
}

static int fsync_path(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    int rc = fsync(fd);
    close(fd);
    return rc;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX_LEN];
    char new_path[PATH_MAX_LEN];

    if (cfg->max_rotations <= 0) {
        if (truncate(cfg->log_path, 0) < 0) {
            return -1;
        }
        return 0;
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) == 0) {
        unlink(old_path);
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }
        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    if (fsync(fd) < 0) {
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size_bytes] [-n rotations] [-i interval_sec] [-m octal_mode] [-d]\n"
        "  -f logfile          Path to log file\n"
        "  -s max_size_bytes   Rotate when file exceeds this size (default: %d)\n"
        "  -n rotations        Number of rotated files to keep (default: %d)\n"
        "  -i interval_sec     Poll interval in seconds (default: %d)\n"
        "  -m octal_mode       File mode for new log file (default: 0644)\n"
        "  -d                  Do not daemonize\n",
        prog,
        DEFAULT_MAX_FILE_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_args(int argc, char **argv, config_t *cfg, int *no_daemon) {
    int opt;
    *no_daemon = 0;

    memset(cfg, 0, sizeof(*cfg));
    cfg->max_file_size = DEFAULT_MAX_FILE_SIZE;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->create_mode = 0644;

    while ((opt = getopt(argc, argv, "f:s:n:i:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return -1;
                }
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's': {
                unsigned long long v = strtoull(optarg, NULL, 10);
                if (v == 0) {
                    fprintf(stderr, "invalid max size\n");
                    return -1;
                }
                cfg->max_file_size = (size_t)v;
                break;
            }
            case 'n': {
                long v = strtol(optarg, NULL, 10);
                if (v < 0 || v > 1000) {
                    fprintf(stderr, "invalid rotations\n");
                    return -1;
                }
                cfg->max_rotations = (int)v;
                break;
            }
            case 'i': {
                unsigned long v = strtoul(optarg, NULL, 10);
                if (v == 0 || v > 86400) {
                    fprintf(stderr, "invalid interval\n");
                    return -1;
                }
                cfg->check_interval_sec = (unsigned)v;
                break;
            }
            case 'm': {
                unsigned long v = strtoul(optarg, NULL, 8);
                if (v > 0777) {
                    fprintf(stderr, "invalid mode\n");
                    return -1;
                }
                cfg->create_mode = (mode_t)v;
                break;
            }
            case 'd':
                *no_daemon = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        fprintf(stderr, "log file path required\n");
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    int no_daemon;

    if (parse_args(argc, argv, &cfg, &no_daemon) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (!no_daemon) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        off_t sz = get_file_size(cfg.log_path);
        if (sz >= 0 && (size_t)sz >= cfg.max_file_size) {
            if (rotate_logs(&cfg) < 0) {
                /* In a constrained daemon, avoid unbounded logging.
                   Sleep and retry later. */
            } else {
                fsync_path(cfg.log_path);
            }
        }

        struct timespec ts;
        ts.tv_sec = cfg.check_interval_sec;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            if (!g_running) break;
        }
    }

    return 0;
}
