## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#ifndef MAX_LOGS
#define MAX_LOGS 32
#endif

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 256
#endif

#ifndef CONFIG_LINE_LEN
#define CONFIG_LINE_LEN 320
#endif

#ifndef DEFAULT_INTERVAL_SEC
#define DEFAULT_INTERVAL_SEC 5
#endif

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int keep;
    int copytruncate; /* 0 = rename rotation, 1 = copy+truncate */
} log_config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (end == s) return -1;

    unsigned long long mult = 1;
    if (*end) {
        if (strcmp(end, "K") == 0 || strcmp(end, "k") == 0) mult = 1024ULL;
        else if (strcmp(end, "M") == 0 || strcmp(end, "m") == 0) mult = 1024ULL * 1024ULL;
        else if (strcmp(end, "G") == 0 || strcmp(end, "g") == 0) mult = 1024ULL * 1024ULL * 1024ULL;
        else return -1;
    }

    *out = (off_t)(v * mult);
    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *a, int n) {
    int rc = snprintf(dst, dstsz, fmt, a, n);
    if (rc < 0 || (size_t)rc >= dstsz) return -1;
    return 0;
}

static int rotate_rename(const log_config_t *cfg) {
    char oldp[MAX_PATH_LEN + 16];
    char newp[MAX_PATH_LEN + 16];

    for (int i = cfg->keep - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) < 0) return -1;
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->path, i + 1) < 0) return -1;
        (void)unlink(newp);
        if (rename(oldp, newp) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (cfg->keep > 0) {
        if (safe_snprintf(newp, sizeof(newp), "%s.1", cfg->path, 1) < 0) return -1;
        (void)unlink(newp);
        if (rename(cfg->path, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    } else {
        (void)unlink(cfg->path);
    }

    int fd = open(cfg->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_copytruncate(const log_config_t *cfg) {
    char rotp[MAX_PATH_LEN + 16];
    if (safe_snprintf(rotp, sizeof(rotp), "%s.1", cfg->path, 1) < 0) return -1;

    for (int i = cfg->keep - 1; i >= 1; --i) {
        char oldp[MAX_PATH_LEN + 16];
        char newp[MAX_PATH_LEN + 16];
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) < 0) return -1;
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->path, i + 1) < 0) return -1;
        (void)unlink(newp);
        if (rename(oldp, newp) < 0 && errno != ENOENT) return -1;
    }

    int src = open(cfg->path, O_RDONLY);
    if (src < 0) return -1;

    int dst = open(rotp, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dst < 0) {
        close(src);
        return -1;
    }

    char buf[1024];
    for (;;) {
        ssize_t r = read(src, buf, sizeof(buf));
        if (r == 0) break;
        if (r < 0) {
            close(src);
            close(dst);
            return -1;
        }
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dst, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(src);
                close(dst);
                return -1;
            }
            off += w;
        }
    }

    close(src);
    close(dst);

    int fd = open(cfg->path, O_WRONLY);
    if (fd < 0) return -1;
    if (ftruncate(fd, 0) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_log(const log_config_t *cfg) {
    if (cfg->copytruncate) return rotate_copytruncate(cfg);
    return rotate_rename(cfg);
}

static int check_and_rotate(const log_config_t *cfg) {
    struct stat st;
    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    if (!S_ISREG(st.st_mode)) return -1;
    if (st.st_size < cfg->max_size) return 0;

    return rotate_log(cfg);
}

static int parse_config(const char *file, log_config_t *logs, int *count, unsigned *interval_sec) {
    FILE *fp = fopen(file, "r");
    if (!fp) return -1;

    char line[CONFIG_LINE_LEN];
    int n = 0;
    unsigned interval = DEFAULT_INTERVAL_SEC;

    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '#' || *p == '\n' || *p == '\0') continue;

        if (strncmp(p, "interval=", 9) == 0) {
            unsigned long v = strtoul(p + 9, NULL, 10);
            if (v > 0) interval = (unsigned)v;
            continue;
        }

        if (n >= MAX_LOGS) {
            fclose(fp);
            return -1;
        }

        char path[MAX_PATH_LEN];
        char sizebuf[32];
        int keep = 0;
        int copytruncate = 0;

        int rc = sscanf(p, "%255s %31s %d %d", path, sizebuf, &keep, &copytruncate);
        if (rc < 3) {
            fclose(fp);
            return -1;
        }

        off_t max_size;
        if (parse_size(sizebuf, &max_size) < 0) {
            fclose(fp);
            return -1;
        }

        memset(&logs[n], 0, sizeof(logs[n]));
        strncpy(logs[n].path, path, sizeof(logs[n].path) - 1);
        logs[n].max_size = max_size;
        logs[n].keep = keep;
        logs[n].copytruncate = copytruncate;
        n++;
    }

    fclose(fp);
    *count = n;
    *interval_sec = interval;
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > 2) close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s [-n] <config>\n", prog);
    fprintf(stderr, "  -n   no daemonize\n");
}

int main(int argc, char **argv) {
    int nodaemon = 0;
    const char *config_path = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-n") == 0) {
            nodaemon = 1;
        } else {
            config_path = argv[i];
        }
    }

    if (!config_path) {
        usage(argv[0]);
        return 1;
    }

    log_config_t logs[MAX_LOGS];
    int log_count = 0;
    unsigned interval_sec = DEFAULT_INTERVAL_SEC;

    memset(logs, 0, sizeof(logs));

    if (parse_config(config_path, logs, &log_count, &interval_sec) < 0) {
        fprintf(stderr, "Failed to parse config: %s\n", config_path);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!nodaemon) {
        if (daemonize() < 0) {
            fprintf(stderr, "Failed to daemonize\n");
            return 1;
        }
    }

    while (g_running) {
        for (int i = 0; i < log_count; ++i) {
            (void)check_and_rotate(&logs[i]);
        }

        struct timespec ts;
        ts.tv_sec = interval_sec;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && g_running) {
        }
    }

    return 0;
}
```

