## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 1
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_stop = 0;
static volatile sig_atomic_t g_hup = 0;

struct config {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    int check_interval_sec;
    int daemonize;
};

static void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_stop = 1;
    } else if (sig == SIGHUP) {
        g_hup = 1;
    }
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (suffix < 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    }
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        /* Truncate in place if no rotations requested */
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    /* Remove the oldest */
    if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, cfg->max_rotations) < 0)
        return -1;
    (void)unlink(oldp);

    /* Shift N-1 -> N, ..., 1 -> 2 */
    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, i) < 0)
            return -1;
        if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, i + 1) < 0)
            return -1;

        if (file_exists(oldp)) {
            if (rename(oldp, newp) < 0) {
                return -1;
            }
        }
    }

    /* Current log -> .1 */
    if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, 1) < 0)
        return -1;

    if (file_exists(cfg->log_path)) {
        if (rename(cfg->log_path, newp) < 0) {
            return -1;
        }
    }

    /* Recreate current log */
    if (ensure_log_exists(cfg->log_path) < 0) {
        return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size_bytes] [-n rotations] [-i interval_sec] [-d]\n"
        "  -f logfile           Path to log file\n"
        "  -s max_size_bytes    Rotate when size exceeds this value (default: %llu)\n"
        "  -n rotations         Number of rotated files to keep (default: %d)\n"
        "  -i interval_sec      Poll interval in seconds (default: %d)\n"
        "  -d                   Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.daemonize = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) < 0) {
                    fprintf(stderr, "invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) < 0) {
                    fprintf(stderr, "invalid rotations\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.check_interval_sec) < 0 || cfg.check_interval_sec <= 0) {
                    fprintf(stderr, "invalid interval\n");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_stop) {
        uint64_t size = 0;

        if (g_hup) {
            g_hup = 0;
            if (rotate_logs(&cfg) < 0) {
                /* In constrained daemon, avoid excessive logging */
            }
        } else if (get_file_size(cfg.log_path, &size) == 0) {
            if (size >= cfg.max_size) {
                if (rotate_logs(&cfg) < 0) {
                    /* Silent failure or minimal handling */
                }
            }
        }

        struct timespec ts;
        ts.tv_sec = cfg.check_interval_sec;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            if (g_stop) break;
            if (g_hup) break;
        }
    }

    return 0;
}
