#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_log_stderr(const char *fmt, ...) {
    char buf[256];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n > 0) {
        if ((size_t)n > sizeof(buf)) n = sizeof(buf);
        (void)write(STDERR_FILENO, buf, (size_t)n);
    }
}

typedef struct {
    char log_path[PATH_MAX];
    uint64_t max_size;
    unsigned int max_rotations;
    unsigned int check_interval_sec;
    bool daemonize;
} config_t;

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec] [-d]\n"
        "  -f <logfile>      Path to log file\n"
        "  -s <max_bytes>    Rotate when file size exceeds this value (default: %llu)\n"
        "  -n <rotations>    Number of rotated files to keep (default: %u)\n"
        "  -i <interval>     Poll interval in seconds (default: %u)\n"
        "  -d                Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    if (!s || !*s) return -1;
    errno = 0;
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    uint64_t v;
    if (parse_u64(s, &v) != 0 || v > 0xFFFFFFFFu) return -1;
    *out = (unsigned int)v;
    return 0;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->daemonize = false;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:d")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    safe_log_stderr("Path too long\n");
                    return -1;
                }
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_u64(optarg, &cfg->max_size) != 0 || cfg->max_size == 0) {
                    safe_log_stderr("Invalid max size\n");
                    return -1;
                }
                break;
            case 'n':
                if (parse_u32(optarg, &cfg->max_rotations) != 0 || cfg->max_rotations == 0) {
                    safe_log_stderr("Invalid rotations count\n");
                    return -1;
                }
                break;
            case 'i':
                if (parse_u32(optarg, &cfg->check_interval_sec) != 0 || cfg->check_interval_sec == 0) {
                    safe_log_stderr("Invalid interval\n");
                    return -1;
                }
                break;
            case 'd':
                cfg->daemonize = true;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        safe_log_stderr("Missing logfile path\n");
        return -1;
    }

    return 0;
}

static int make_rotated_path(const char *base, unsigned int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations > 1) {
        for (unsigned int i = cfg->max_rotations - 1; i >= 1; --i) {
            if (make_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) != 0) return -1;
            if (make_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) != 0) return -1;

            if (rename(oldp, newp) != 0) {
                if (errno != ENOENT) {
                    safe_log_stderr("rename(%s -> %s) failed: %s\n", oldp, newp, strerror(errno));
                    return -1;
                }
            }

            if (i == 1) break;
        }
    }

    if (cfg->max_rotations >= 1) {
        if (make_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) != 0) return -1;
        if (rename(cfg->log_path, newp) != 0) {
            if (errno != ENOENT) {
                safe_log_stderr("rename(%s -> %s) failed: %s\n", cfg->log_path, newp, strerror(errno));
                return -1;
            }
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        safe_log_stderr("open(%s) failed: %s\n", cfg->log_path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        safe_log_stderr("stat(%s) failed: %s\n", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        safe_log_stderr("%s is not a regular file\n", cfg->log_path);
        return -1;
    }

    if ((uint64_t)st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    if (dup2(nullfd, STDIN_FILENO) < 0) return -1;
    if (dup2(nullfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(nullfd, STDERR_FILENO) < 0) return -1;

    if (nullfd > STDERR_FILENO) close(nullfd);

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        safe_log_stderr("sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            safe_log_stderr("daemonize failed: %s\n", strerror(errno));
            return 1;
        }
    }

    while (!g_stop) {
        (void)check_and_rotate(&cfg);

        unsigned int slept = 0;
        while (!g_stop && slept < cfg.check_interval_sec) {
            sleep(1);
            ++slept;
        }
    }

    return 0;
}
