#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define MAX_PATH_LEN 256
#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[MAX_PATH_LEN];
    off_t max_size;
    int max_rotations;
    int check_interval;
    int daemonize;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (!s || !out) return -1;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0') return -1;
    if (v < 0 || v > 2147483647L) return -1;
    *out = (int)v;
    return 0;
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    unsigned long long v;
    unsigned long long mult = 1;

    if (!s || !out) return -1;

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno || end == s) return -1;

    if (*end != '\0') {
        if (end[1] != '\0') return -1;
        switch (*end) {
            case 'K': case 'k': mult = 1024ULL; break;
            case 'M': case 'm': mult = 1024ULL * 1024ULL; break;
            case 'G': case 'g': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    if (v > (unsigned long long)((~(off_t)0) / mult)) return -1;
    *out = (off_t)(v * mult);
    return 0;
}

static void print_usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size] [-n rotations] [-i interval] [-d]\n"
        "  -f logfile     Path to log file\n"
        "  -s max_size    Rotate when file exceeds size (e.g. 1048576, 10M, 512K)\n"
        "  -n rotations   Number of rotated files to keep\n"
        "  -i interval    Check interval in seconds\n"
        "  -d             Run as daemon\n",
        prog);
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];
    int i;

    if (!cfg) return -1;

    if (cfg->max_rotations > 0) {
        snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, cfg->max_rotations);
        unlink(old_path);

        for (i = cfg->max_rotations - 1; i >= 1; --i) {
            snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i);
            snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i + 1);

            if (file_exists(old_path)) {
                if (rename(old_path, new_path) < 0) {
                    return -1;
                }
            }
        }

        snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path);
        if (rename(cfg->log_path, new_path) < 0) {
            if (errno != ENOENT) return -1;
        }
    } else {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int should_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }
    return st.st_size >= cfg->max_size ? 1 : 0;
}

static int run_daemon(const config_t *cfg) {
    while (g_running) {
        int rc = should_rotate(cfg);
        if (rc < 0) {
            sleep(cfg->check_interval);
            continue;
        }

        if (rc == 1) {
            if (rotate_logs(cfg) == 0) {
                ensure_log_exists(cfg->log_path);
            }
        }

        sleep(cfg->check_interval);
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval = DEFAULT_CHECK_INTERVAL;
    cfg.daemonize = 0;

    while ((opt = getopt(argc, argv, "f:s:n:i:d")) != -1) {
        switch (opt) {
            case 'f':
                strncpy(cfg.log_path, optarg, sizeof(cfg.log_path) - 1);
                cfg.log_path[sizeof(cfg.log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_size(optarg, &cfg.max_size) < 0) {
                    fprintf(stderr, "Invalid size: %s\n", optarg);
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) < 0) {
                    fprintf(stderr, "Invalid rotation count: %s\n", optarg);
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.check_interval) < 0 || cfg.check_interval <= 0) {
                    fprintf(stderr, "Invalid interval: %s\n", optarg);
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        print_usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    return run_daemon(&cfg);
}
