```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd /var/log/myapp.log 1048576 5 5
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Notes:
 * - Uses polling, not inotify, to keep implementation simple and memory-stable.
 * - Rotation scheme:
 *     logfile.(N-1) -> logfile.N
 *     ...
 *     logfile.1 -> logfile.2
 *     logfile -> logfile.1
 * - Then recreates/truncates the original logfile.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (fd != STDIN_FILENO) dup2(fd, STDIN_FILENO);
    if (fd != STDOUT_FILENO) dup2(fd, STDOUT_FILENO);
    if (fd != STDERR_FILENO) dup2(fd, STDERR_FILENO);

    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int safe_snprintf_path(char *dst, size_t dstsz, const char *base, unsigned int idx) {
    int n = snprintf(dst, dstsz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *log_path, unsigned int keep_count) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    struct stat st;

    if (keep_count == 0) {
        int fd = open(log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    if (safe_snprintf_path(old_path, sizeof(old_path), log_path, keep_count) < 0)
        return -1;
    unlink(old_path);

    for (unsigned int i = keep_count; i > 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), log_path, i - 1) < 0)
            return -1;
        if (safe_snprintf_path(new_path, sizeof(new_path), log_path, i) < 0)
            return -1;

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (safe_snprintf_path(new_path, sizeof(new_path), log_path, 1) < 0)
        return -1;

    if (stat(log_path, &st) == 0) {
        if (rename(log_path, new_path) < 0) {
            return -1;
        }

        int fd = open(log_path, O_WRONLY | O_CREAT | O_TRUNC, st.st_mode & 0777);
        if (fd < 0) {
            return -1;
        }

        if (fchown(fd, st.st_uid, st.st_gid) < 0) {
            /* Ignore ownership errors if not privileged */
        }

        close(fd);
    } else {
        if (errno != ENOENT) return -1;

        int fd = open(log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static int check_rotate(const char *log_path, off_t max_size, unsigned int keep_count) {
    struct stat st;

    if (stat(log_path, &st) < 0) {
        if (errno == ENOENT) {
            int fd = open(log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= max_size) {
        return rotate_logs(log_path, keep_count);
    }

    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    uint64_t v;
    if (parse_u64(s, &v) < 0) return -1;
    if (v > 0xFFFFFFFFu) return -1;
    *out = (unsigned int)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_seconds> [--daemon]\n",
            prog);
}

int main(int argc, char **argv) {
    const char *log_path;
    uint64_t max_size_u64;
    unsigned int keep_count;
    unsigned int poll_seconds;
    int do_daemon = 0;

    if (argc < 5 || argc > 6) {
        usage(argv[0]);
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            usage(argv[0]);
            return 1;
        }
        do_daemon = 1;
    }

    log_path = argv[1];

    if (strlen(log_path) >= PATH_MAX) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_size_u64) < 0 || max_size_u64 == 0) {
        fprintf(stderr, "invalid max_size_bytes\n");
        return 1;
    }

    if (max_size_u64 > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "max_size_bytes too large\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep_count) < 0) {
        fprintf(stderr, "invalid keep_count\n");
        return 1;
    }

    if (parse_u32(argv[4], &poll_seconds) < 0 || poll_seconds == 0) {
        fprintf(stderr, "invalid poll_seconds\n");
        return 1;
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (do_daemon) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        if (check_rotate(log_path, (off_t)max_size_u64, keep_count) < 0) {
            /*
             * In a constrained daemon, avoid excessive logging or allocations.
             * Sleep and retry on error.
             */
        }

        struct timespec ts;
        ts.tv_sec = (time_t)poll_seconds;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}
```

---

## How it works

1. `stat()` checks the current log size.
2. If the file size is at or above the threshold:
   - `log.N-1` becomes `log.N`
   - `log.1` becomes `log.2`
   - `log` becomes `log.1`
3. A fresh `log` file is created.
4. The daemon sleeps for the configured polling interval.

---

## Memory characteristics

This implementation is memory-constrained because:

- No `malloc`, `calloc`, `realloc`, or free-store usage
- Only fixed-size path buffers:
  - `old_path[PATH_MAX]`
  - `new_path[PATH_MAX]`
- No file contents are copied in memory
- Rotation uses filesystem `rename()` rather than buffered copying

This makes memory usage predictable and bounded.

---

## Example usage

Rotate `/var/log/app.log` at 10 MB, keep 4 archives, check every 2 seconds:

```sh
./memlogd /var/log/app.log 10485760 4 2 --daemon
```

Run in foreground:

```sh
./memlogd /var/log/app.log 10485760 4 2
```

---

## Important limitations

This is intentionally minimal. In production, you may also want:

- PID file locking
- Config file support
- Compression of rotated logs
- Copytruncate mode for applications that keep the file descriptor open
- Syslog/error reporting
- inotify support
- Hard resource limits via `setrlimit()`
- Privilege dropping
- Handling of cross-filesystem rotation
- Safer synchronization with writers

