# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#ifndef MAX_LOGS
#define MAX_LOGS 16
#endif

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 256
#endif

#ifndef MAX_ROTATIONS
#define MAX_ROTATIONS 16
#endif

#ifndef DEFAULT_POLL_INTERVAL_SEC
#define DEFAULT_POLL_INTERVAL_SEC 5
#endif

#ifndef DEFAULT_MAX_SIZE
#define DEFAULT_MAX_SIZE (1024 * 1024)
#endif

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int rotate_count;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    int log_count;
    unsigned poll_interval_sec;
    int foreground;
} daemon_config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int rotate_one_log(const log_config_t *cfg) {
    if (!cfg || cfg->rotate_count < 1 || cfg->rotate_count > MAX_ROTATIONS) {
        return -1;
    }

    char old_path[MAX_PATH_LEN + 16];
    char new_path[MAX_PATH_LEN + 16];

    /* Remove oldest */
    if (snprintf(old_path, sizeof(old_path), "%s.%d", cfg->path, cfg->rotate_count) >= (int)sizeof(old_path)) {
        return -1;
    }
    unlink(old_path);

    /* Shift N-1 down to 1 */
    for (int i = cfg->rotate_count - 1; i >= 1; --i) {
        if (snprintf(old_path, sizeof(old_path), "%s.%d", cfg->path, i) >= (int)sizeof(old_path)) {
            return -1;
        }
        if (snprintf(new_path, sizeof(new_path), "%s.%d", cfg->path, i + 1) >= (int)sizeof(new_path)) {
            return -1;
        }

        if (file_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                return -1;
            }
        }
    }

    /* Move current log to .1 */
    if (file_exists(cfg->path)) {
        if (snprintf(new_path, sizeof(new_path), "%s.1", cfg->path) >= (int)sizeof(new_path)) {
            return -1;
        }
        if (rename(cfg->path, new_path) != 0) {
            return -1;
        }
    }

    /* Recreate empty active log */
    FILE *fp = fopen(cfg->path, "a");
    if (!fp) {
        return -1;
    }
    fclose(fp);

    return 0;
}

static void check_and_rotate(const daemon_config_t *cfg) {
    for (int i = 0; i < cfg->log_count; ++i) {
        off_t size = 0;
        if (get_file_size(cfg->logs[i].path, &size) != 0) {
            continue;
        }

        if (size >= cfg->logs[i].max_size) {
            if (rotate_one_log(&cfg->logs[i]) != 0) {
                fprintf(stderr, "rotation failed for %s: %s\n",
                        cfg->logs[i].path, strerror(errno));
            }
        }
    }
}

static int add_log_config(daemon_config_t *cfg, const char *path, off_t max_size, int rotate_count) {
    if (!cfg || !path) {
        return -1;
    }
    if (cfg->log_count >= MAX_LOGS) {
        return -1;
    }
    if (rotate_count < 1 || rotate_count > MAX_ROTATIONS) {
        return -1;
    }

    log_config_t *dst = &cfg->logs[cfg->log_count];
    size_t len = strnlen(path, MAX_PATH_LEN);
    if (len == 0 || len >= MAX_PATH_LEN) {
        return -1;
    }

    memcpy(dst->path, path, len);
    dst->path[len] = '\0';
    dst->max_size = max_size;
    dst->rotate_count = rotate_count;
    cfg->log_count++;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-i poll_interval_sec] [-s max_size_bytes] [-r rotate_count] log1 [log2 ...]\n"
        "Example: %s -i 2 -s 1048576 -r 4 /var/log/app.log\n",
        prog, prog);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg.foreground = 1;

    off_t default_max_size = DEFAULT_MAX_SIZE;
    int default_rotate_count = 4;

    int opt;
    while ((opt = getopt(argc, argv, "i:s:r:")) != -1) {
        switch (opt) {
            case 'i':
                cfg.poll_interval_sec = (unsigned)strtoul(optarg, NULL, 10);
                if (cfg.poll_interval_sec == 0) {
                    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
                }
                break;
            case 's':
                default_max_size = (off_t)strtoll(optarg, NULL, 10);
                if (default_max_size <= 0) {
                    default_max_size = DEFAULT_MAX_SIZE;
                }
                break;
            case 'r':
                default_rotate_count = (int)strtol(optarg, NULL, 10);
                if (default_rotate_count < 1 || default_rotate_count > MAX_ROTATIONS) {
                    default_rotate_count = 4;
                }
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return 1;
    }

    for (int i = optind; i < argc; ++i) {
        if (add_log_config(&cfg, argv[i], default_max_size, default_rotate_count) != 0) {
            fprintf(stderr, "failed to add log: %s\n", argv[i]);
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        check_and_rotate(&cfg);

        struct timespec ts;
        ts.tv_sec = cfg.poll_interval_sec;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}
```

