# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 16
#define LOG_MSG_MAX   256
#define SLEEP_GRANULARITY_MS 200

typedef struct {
    char log_path[PATH_MAX];
    size_t rotate_size;
    unsigned int rotate_count;
    unsigned int poll_interval_ms;
    bool daemonize;
    bool create_if_missing;
    mode_t create_mode;
} config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_log(const char *fmt, ...) {
    char buf[LOG_MSG_MAX];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n < 0) {
        return;
    }

    size_t len = (size_t)n;
    if (len >= sizeof(buf)) {
        len = sizeof(buf) - 1;
    }

    buf[len] = '\n';
    len++;
    if (len > sizeof(buf)) {
        len = sizeof(buf);
    }

    (void)write(STDERR_FILENO, buf, len);
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v > 0xFFFFFFFFu) {
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static int parse_size(const char *s, size_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) {
        return -1;
    }

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') {
            return -1;
        }
        switch (*end) {
            case 'k':
            case 'K':
                mult = 1024ULL;
                break;
            case 'm':
            case 'M':
                mult = 1024ULL * 1024ULL;
                break;
            case 'g':
            case 'G':
                mult = 1024ULL * 1024ULL * 1024ULL;
                break;
            default:
                return -1;
        }
    }

    if (v > (unsigned long long)SIZE_MAX / mult) {
        return -1;
    }

    *out = (size_t)(v * mult);
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s --log PATH --size N[k|m|g] --count N [options]\n"
        "Options:\n"
        "  --interval MS       Poll interval in milliseconds (default: 1000)\n"
        "  --daemon            Run as daemon\n"
        "  --create            Create log file if missing\n"
        "  --mode OCTAL        Mode for created file (default: 0644)\n",
        prog);
}

static int parse_octal_mode(const char *s, mode_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 8);
    if (errno != 0 || end == s || *end != '\0' || v > 07777) {
        return -1;
    }
    *out = (mode_t)v;
    return 0;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_ms = 1000;
    cfg->create_mode = 0644;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--log") == 0) {
            if (++i >= argc) return -1;
            if (strlen(argv[i]) >= sizeof(cfg->log_path)) return -1;
            strcpy(cfg->log_path, argv[i]);
        } else if (strcmp(argv[i], "--size") == 0) {
            if (++i >= argc) return -1;
            if (parse_size(argv[i], &cfg->rotate_size) != 0) return -1;
        } else if (strcmp(argv[i], "--count") == 0) {
            if (++i >= argc) return -1;
            if (parse_u32(argv[i], &cfg->rotate_count) != 0) return -1;
        } else if (strcmp(argv[i], "--interval") == 0) {
            if (++i >= argc) return -1;
            if (parse_u32(argv[i], &cfg->poll_interval_ms) != 0) return -1;
        } else if (strcmp(argv[i], "--daemon") == 0) {
            cfg->daemonize = true;
        } else if (strcmp(argv[i], "--create") == 0) {
            cfg->create_if_missing = true;
        } else if (strcmp(argv[i], "--mode") == 0) {
            if (++i >= argc) return -1;
            if (parse_octal_mode(argv[i], &cfg->create_mode) != 0) return -1;
        } else {
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->rotate_size == 0 || cfg->rotate_count == 0) {
        return -1;
    }

    if (cfg->rotate_count > MAX_ROTATIONS) {
        return -1;
    }

    if (cfg->poll_interval_ms == 0) {
        return -1;
    }

    return 0;
}

static int make_rotated_path(const char *base, unsigned int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int ensure_file_exists(const config_t *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->rotate_count > 0) {
        if (make_rotated_path(cfg->log_path, cfg->rotate_count, old_path, sizeof(old_path)) != 0) {
            return -1;
        }
        (void)unlink(old_path);
    }

    for (unsigned int i = cfg->rotate_count; i > 1; i--) {
        if (make_rotated_path(cfg->log_path, i - 1, old_path, sizeof(old_path)) != 0) {
            return -1;
        }
        if (make_rotated_path(cfg->log_path, i, new_path, sizeof(new_path)) != 0) {
            return -1;
        }
        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                safe_log("rename(%s -> %s) failed: %s", old_path, new_path, strerror(errno));
                return -1;
            }
        }
    }

    if (make_rotated_path(cfg->log_path, 1, new_path, sizeof(new_path)) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            safe_log("rename(%s -> %s) failed: %s", cfg->log_path, new_path, strerror(errno));
            return -1;
        }
    }

    if (cfg->create_if_missing) {
        if (ensure_file_exists(cfg) != 0) {
            safe_log("failed to create new log file %s: %s", cfg->log_path, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    (void)sigaction(SIGINT, &sa, NULL);
    (void)sigaction(SIGTERM, &sa, NULL);
}

static void sleep_ms(unsigned int ms) {
    struct timespec req, rem;
    req.tv_sec = ms / 1000;
    req.tv_nsec = (long)(ms % 1000) * 1000000L;

    while (nanosleep(&req, &rem) != 0) {
        if (errno == EINTR) {
            if (!g_running) {
                return;
            }
            req = rem;
        } else {
            return;
        }
    }
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT && cfg->create_if_missing) {
            if (ensure_file_exists(cfg) != 0) {
                safe_log("failed to create missing log file %s: %s", cfg->log_path, strerror(errno));
                return -1;
            }
            return 0;
        }
        safe_log("stat(%s) failed: %s", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        safe_log("%s is not a regular file", cfg->log_path);
        return -1;
    }

    if ((uintmax_t)st.st_size >= (uintmax_t)cfg->rotate_size) {
        safe_log("rotating %s (size=%jd)", cfg->log_path, (intmax_t)st.st_size);
        if (rotate_logs(cfg) != 0) {
            return -1;
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    install_signals();

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            safe_log("daemonize failed: %s", strerror(errno));
            return 1;
        }
    }

    safe_log("memlogd started: log=%s size=%zu count=%u interval_ms=%u",
             cfg.log_path, cfg.rotate_size, cfg.rotate_count, cfg.poll_interval_ms);

    while (g_running) {
        (void)check_and_rotate(&cfg);

        unsigned int remaining = cfg.poll_interval_ms;
        while (remaining > 0 && g_running) {
            unsigned int chunk = remaining > SLEEP_GRANULARITY_MS ? SLEEP_GRANULARITY_MS : remaining;
            sleep_ms(chunk);
            remaining -= chunk;
        }
    }

    safe_log("memlogd exiting");
    return 0;
}
