#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE_BYTES (10 * 1024 * 1024ULL)
#define MIN_CHECK_INTERVAL_SEC 1
#define MAX_ROTATIONS 32

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    unsigned long long max_size_bytes;
    int max_rotations;
    int check_interval_sec;
    int copytruncate;
    int verbose;
} config_t;

static void handle_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static void print_usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [options]\n"
        "Options:\n"
        "  -f <path>   Log file to monitor\n"
        "  -s <bytes>  Rotate when size exceeds bytes (default: %llu)\n"
        "  -n <count>  Number of rotated files to keep, 1-%d (default: %d)\n"
        "  -i <sec>    Check interval in seconds (default: %d)\n"
        "  -t          Copytruncate mode: create rotated name, then truncate active file\n"
        "  -v          Verbose logging\n"
        "  -h          Show this help\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE_BYTES,
        MAX_ROTATIONS,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_ull(const char *s, unsigned long long *out) {
    char *end = NULL;
    unsigned long long v;

    if (s == NULL || *s == '\0') {
        return -1;
    }

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }

    *out = v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (s == NULL || *s == '\0') {
        return -1;
    }

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v < INT32_MIN || v > INT32_MAX) {
        return -1;
    }

    *out = (int)v;
    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *base, int idx) {
    int n = snprintf(dst, dstsz, fmt, base, idx);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, unsigned long long *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (unsigned long long)st.st_size;
    return 0;
}

static int copy_file_contents(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    char buf[4096];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) {
        return -1;
    }

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (close(in_fd) != 0) {
        close(out_fd);
        return -1;
    }
    if (close(out_fd) != 0) {
        return -1;
    }

    return 0;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        return -1;
    }
    if (ftruncate(fd, 0) != 0) {
        close(fd);
        return -1;
    }
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    int i;

    if (cfg->max_rotations < 1 || cfg->max_rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    if (cfg->copytruncate) {
        if (safe_snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path, 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (file_exists(new_path)) {
            if (unlink(new_path) != 0) {
                return -1;
            }
        }

        if (copy_file_contents(cfg->log_path, new_path) != 0) {
            return -1;
        }

        if (truncate_file(cfg->log_path) != 0) {
            return -1;
        }

        for (i = cfg->max_rotations; i >= 2; --i) {
            if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i - 1) != 0 ||
                safe_snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i) != 0) {
                errno = ENAMETOOLONG;
                return -1;
            }

            if (file_exists(old_path)) {
                if (rename(old_path, new_path) != 0) {
                    return -1;
                }
            }
        }

        return 0;
    }

    if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, cfg->max_rotations) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    if (file_exists(old_path)) {
        if (unlink(old_path) != 0) {
            return -1;
        }
    }

    for (i = cfg->max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i) != 0 ||
            safe_snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i + 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (file_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                return -1;
            }
        }
    }

    if (safe_snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path, 1) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        return -1;
    }

    {
        int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) {
            return -1;
        }
        if (close(fd) != 0) {
            return -1;
        }
    }

    return 0;
}

static void log_message(const config_t *cfg, const char *msg) {
    if (cfg->verbose) {
        time_t now = time(NULL);
        struct tm tm_now;
        char ts[32];

        if (localtime_r(&now, &tm_now) != NULL &&
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_now) > 0) {
            fprintf(stderr, "[%s] %s\n", ts, msg);
        } else {
            fprintf(stderr, "%s\n", msg);
        }
    }
}

static int run_daemon_loop(const config_t *cfg) {
    while (g_running) {
        unsigned long long size = 0;

        if (get_file_size(cfg->log_path, &size) == 0) {
            if (size >= cfg->max_size_bytes) {
                log_message(cfg, "rotation threshold reached");
                if (rotate_logs(cfg) != 0) {
                    perror("rotate_logs");
                } else {
                    log_message(cfg, "rotation completed");
                }
            }
        } else {
            if (errno != ENOENT) {
                perror("stat");
            }
        }

        for (int slept = 0; g_running && slept < cfg->check_interval_sec; ++slept) {
            sleep(1);
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size_bytes = DEFAULT_MAX_SIZE_BYTES;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.copytruncate = 0;
    cfg.verbose = 0;

    while ((opt = getopt(argc, argv, "f:s:n:i:tvh")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_ull(optarg, &cfg.max_size_bytes) != 0 || cfg.max_size_bytes == 0) {
                    fprintf(stderr, "invalid size: %s\n", optarg);
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) != 0 ||
                    cfg.max_rotations < 1 || cfg.max_rotations > MAX_ROTATIONS) {
                    fprintf(stderr, "invalid rotation count: %s\n", optarg);
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.check_interval_sec) != 0 ||
                    cfg.check_interval_sec < MIN_CHECK_INTERVAL_SEC) {
                    fprintf(stderr, "invalid interval: %s\n", optarg);
                    return 1;
                }
                break;
            case 't':
                cfg.copytruncate = 1;
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            case 'h':
            default:
                print_usage(argv[0]);
                return (opt == 'h') ? 0 : 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        fprintf(stderr, "missing required -f <logfile>\n");
        print_usage(argv[0]);
        return 1;
    }

    install_signal_handlers();

    log_message(&cfg, "starting log rotation daemon");
    return run_daemon_loop(&cfg);
}
