# `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE_BYTES (10 * 1024 * 1024)
#define DEFAULT_ROTATIONS      5
#define DEFAULT_INTERVAL_SEC   5
#define DEFAULT_LOCKFILE       "/tmp/logrotated.lock"
#define DEFAULT_PIDFILE        "/tmp/logrotated.pid"

#define LOGMSG_BUF_SZ 256

static volatile sig_atomic_t g_terminate = 0;

struct config {
    char log_path[PATH_MAX];
    char lock_path[PATH_MAX];
    char pid_path[PATH_MAX];
    off_t max_size_bytes;
    int max_rotations;
    unsigned interval_sec;
    int daemonize;
};

static void on_signal(int signo) {
    (void)signo;
    g_terminate = 1;
}

static void safe_log_stderr(const char *fmt, ...) {
    char buf[LOGMSG_BUF_SZ];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    dprintf(STDERR_FILENO, "%s\n", buf);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int write_pidfile(const char *pid_path) {
    int fd = open(pid_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;

    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || write(fd, buf, (size_t)len) != len) {
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int acquire_lockfile(const char *lock_path) {
    int fd = open(lock_path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;

    struct flock fl;
    memset(&fl, 0, sizeof(fl));
    fl.l_type = F_WRLCK;
    fl.l_whence = SEEK_SET;

    if (fcntl(fd, F_SETLK, &fl) < 0) {
        close(fd);
        return -1;
    }

    return fd; /* keep open for lock lifetime */
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
        return 0;
    }

    if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) < 0) {
        return -1;
    }

    if (unlink(old_path) < 0 && errno != ENOENT) {
        return -1;
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int maybe_rotate(const struct config *cfg) {
    off_t sz = 0;
    if (file_size(cfg->log_path, &sz) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    if (sz < cfg->max_size_bytes) return 0;

    return rotate_logs(cfg);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [options]\n"
        "Options:\n"
        "  -f <path>   Log file to monitor\n"
        "  -s <bytes>  Max size before rotation (default: %d)\n"
        "  -n <count>  Number of rotated files to keep (default: %d)\n"
        "  -i <sec>    Poll interval seconds (default: %d)\n"
        "  -l <path>   Lock file path (default: %s)\n"
        "  -p <path>   PID file path (default: %s)\n"
        "  -d          Daemonize\n"
        "  -h          Show help\n",
        prog,
        DEFAULT_MAX_SIZE_BYTES,
        DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC,
        DEFAULT_LOCKFILE,
        DEFAULT_PIDFILE
    );
}

static int parse_long(const char *s, long *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size_bytes = DEFAULT_MAX_SIZE_BYTES;
    cfg->max_rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->daemonize = 0;

    snprintf(cfg->lock_path, sizeof(cfg->lock_path), "%s", DEFAULT_LOCKFILE);
    snprintf(cfg->pid_path, sizeof(cfg->pid_path), "%s", DEFAULT_PIDFILE);

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:l:p:dh")) != -1) {
        long v;
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path))
                    return -1;
                break;
            case 's':
                if (parse_long(optarg, &v) < 0 || v <= 0) return -1;
                cfg->max_size_bytes = (off_t)v;
                break;
            case 'n':
                if (parse_long(optarg, &v) < 0 || v < 0 || v > 9999) return -1;
                cfg->max_rotations = (int)v;
                break;
            case 'i':
                if (parse_long(optarg, &v) < 0 || v <= 0) return -1;
                cfg->interval_sec = (unsigned)v;
                break;
            case 'l':
                if (snprintf(cfg->lock_path, sizeof(cfg->lock_path), "%s", optarg) >= (int)sizeof(cfg->lock_path))
                    return -1;
                break;
            case 'p':
                if (snprintf(cfg->pid_path, sizeof(cfg->pid_path), "%s", optarg) >= (int)sizeof(cfg->pid_path))
                    return -1;
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'h':
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        safe_log_stderr("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    int lock_fd = acquire_lockfile(cfg.lock_path);
    if (lock_fd < 0) {
        safe_log_stderr("failed to acquire lockfile '%s': %s", cfg.lock_path, strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            safe_log_stderr("failed to daemonize: %s", strerror(errno));
            close(lock_fd);
            return 1;
        }
    }

    if (write_pidfile(cfg.pid_path) < 0) {
        safe_log_stderr("failed to write pidfile '%s': %s", cfg.pid_path, strerror(errno));
        close(lock_fd);
        return 1;
    }

    while (!g_terminate) {
        if (maybe_rotate(&cfg) < 0) {
            safe_log_stderr("rotation check failed for '%s': %s", cfg.log_path, strerror(errno));
        }

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (!g_terminate && nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            /* retry remaining sleep */
        }
    }

    unlink(cfg.pid_path);
    close(lock_fd);
    return 0;
}
