# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_ROTATE_SIZE (10 * 1024 * 1024ULL)
#define MAX_ROTATIONS_LIMIT 64
#define LOGMSG_MAX 256

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    uint64_t rotate_size;
    unsigned int max_rotations;
    unsigned int check_interval_sec;
    int daemonize;
    int truncate_on_failure;
};

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void safe_log(FILE *stream, const char *fmt, ...) {
    char buf[LOGMSG_MAX];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    fprintf(stream, "%s\n", buf);
    fflush(stream);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, unsigned int suffix) {
    int n = snprintf(out, out_sz, "%s.%u", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_log(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_rotations == 0) {
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) < 0) {
        return -1;
    }

    (void)unlink(old_path);

    for (unsigned int i = cfg->max_rotations; i > 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i - 1) < 0) {
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        if (cfg->truncate_on_failure) {
            fd = open(new_path, O_WRONLY | O_TRUNC);
            if (fd >= 0) {
                close(fd);
                return 0;
            }
        }
        return -1;
    }

    close(fd);
    return 0;
}

static int should_rotate(const struct config *cfg, off_t *size_out) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (size_out) *size_out = st.st_size;
    return (uint64_t)st.st_size >= cfg->rotate_size ? 1 : 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s rotate_size_bytes] [-n rotations] [-i interval_sec] [-d] [-t]\n"
        "  -f <logfile>   Path to log file to monitor\n"
        "  -s <bytes>     Rotate when file reaches this size (default: %llu)\n"
        "  -n <count>     Number of rotated files to keep (default: %u, max: %u)\n"
        "  -i <sec>       Poll interval in seconds (default: %u)\n"
        "  -d             Daemonize\n"
        "  -t             If recreate fails after rename, truncate rotated file as fallback\n",
        prog,
        (unsigned long long)DEFAULT_ROTATE_SIZE,
        DEFAULT_MAX_ROTATIONS,
        MAX_ROTATIONS_LIMIT,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v > UINT_MAX) return -1;
    *out = (unsigned int)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.rotate_size = DEFAULT_ROTATE_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.daemonize = 0;
    cfg.truncate_on_failure = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:dt")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    safe_log(stderr, "log path too long");
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.rotate_size) < 0 || cfg.rotate_size == 0) {
                    safe_log(stderr, "invalid rotate size");
                    return 1;
                }
                break;
            case 'n':
                if (parse_u32(optarg, &cfg.max_rotations) < 0 || cfg.max_rotations > MAX_ROTATIONS_LIMIT) {
                    safe_log(stderr, "invalid rotation count");
                    return 1;
                }
                break;
            case 'i':
                if (parse_u32(optarg, &cfg.check_interval_sec) < 0 || cfg.check_interval_sec == 0) {
                    safe_log(stderr, "invalid interval");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 't':
                cfg.truncate_on_failure = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_terminate) {
        off_t size = 0;
        int rc = should_rotate(&cfg, &size);
        if (rc > 0) {
            if (rotate_log(&cfg) < 0) {
                safe_log(stderr, "rotation failed for %s: %s", cfg.log_path, strerror(errno));
            }
        } else if (rc < 0) {
            if (errno != ENOENT) {
                safe_log(stderr, "stat failed for %s: %s", cfg.log_path, strerror(errno));
            }
        }

        if (g_reload) {
            g_reload = 0;
            safe_log(stderr, "SIGHUP received; reload not implemented in initial version");
        }

        for (unsigned int slept = 0; slept < cfg.check_interval_sec && !g_terminate; ++slept) {
            sleep(1);
        }
    }

    return 0;
}
