# Optional hardened extension: strict memory rlimit snippet

You asked for strict memory limits, so here is a small helper you can integrate:

```c
#include <sys/resource.h>

static int apply_memory_limits(rlim_t address_space_bytes, rlim_t data_bytes, rlim_t stack_bytes) {
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = address_space_bytes;
    if (setrlimit(RLIMIT_AS, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = data_bytes;
    if (setrlimit(RLIMIT_DATA, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = stack_bytes;
    if (setrlimit(RLIMIT_STACK, &rl) < 0) return -1;

    return 0;
}
```

Example use near startup:

```c
if (apply_memory_limits(32 * 1024 * 1024, 8 * 1024 * 1024, 1 * 1024 * 1024) < 0) {
    perror("setrlimit");
    return 1;
}
