- and syslog logging,

while still keeping the daemon memory-bounded.

Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to run under **strict memory limits**.

It is intentionally:
- **single-process**
- **low-allocation**
- **streaming-oriented**
- **fixed-buffer**
- **simple and auditable**

It supports:
- monitoring a configured log file
- rotating when file size exceeds a threshold
- keeping a fixed number of rotated files
- optional periodic polling
- no dynamic allocation in the hot path
- bounded memory usage

---

# Design goals

This implementation is optimized for constrained environments:

- **No heap allocations required during steady-state operation**
- **Fixed-size buffers**
- **No recursive logic**
- **No large in-memory file copies**
- **Rotation via rename**
- **Simple polling loop instead of inotify** for portability and lower complexity

Memory usage is roughly bounded by:
- one daemon state struct
- a few fixed path buffers
- a small I/O/logging buffer

---

# Features

- Rotate `logfile` when `size >= max_size`
- Keep `N` archives:
  - `logfile.1`
  - `logfile.2`
  - ...
  - `logfile.N`
- Oldest archive removed before shifting
- Recreate the active log file after rotation
- Polling interval configurable
- Optional foreground mode
- Optional PID file
- Signal handling:
  - `SIGTERM`, `SIGINT` => clean shutdown
  - `SIGHUP` => force rotation check

---

# Initial implementation

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 5 -F
 *
 * Notes:
 * - Uses polling instead of inotify for simplicity and bounded memory.
 * - Avoids heap allocation in steady state.
 * - Rotates by rename() and recreates the active file.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10 * 1024 * 1024ULL)
#define LOG_BUF_SIZE         256

typedef struct {
    char log_path[PATH_MAX];
    char pid_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    int interval_sec;
    int foreground;
    int use_pidfile;
    mode_t create_mode;
} config_t;

typedef struct {
    config_t cfg;
    volatile sig_atomic_t terminate;
    volatile sig_atomic_t reload;
    int pid_fd;
} daemon_state_t;

static daemon_state_t g_state;

static void log_msg(const char *fmt, ...)
{
    char buf[LOG_BUF_SIZE];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len > 0) {
        if (len == sizeof(buf)) {
            len = sizeof(buf) - 1;
        }
        buf[len] = '\n';
        if (len + 1 < sizeof(buf)) {
            (void)write(STDERR_FILENO, buf, len + 1);
        } else {
            (void)write(STDERR_FILENO, buf, len);
        }
    }
}

static void handle_signal(int sig)
{
    if (sig == SIGTERM || sig == SIGINT) {
        g_state.terminate = 1;
    } else if (sig == SIGHUP) {
        g_state.reload = 1;
    }
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int write_pidfile(const char *path)
{
    char buf[32];
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || len >= (int)sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)len) != len) {
        close(fd);
        return -1;
    }

    return fd;
}

static void remove_pidfile(daemon_state_t *st)
{
    if (st->use_pidfile && st->pid_fd >= 0) {
        close(st->pid_fd);
        st->pid_fd = -1;
        unlink(st->cfg.pid_path);
    }
}

static int daemonize_if_needed(int foreground)
{
    if (foreground) {
        return 0;
    }

    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > 2) close(fd);
    }

    if (chdir("/") < 0) {
        return -1;
    }

    return 0;
}

static int path_with_suffix(char *dst, size_t dst_sz, const char *base, int suffix)
{
    int n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dst_sz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode)
{
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg)
{
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        if (truncate(cfg->log_path, 0) < 0) {
            return -1;
        }
        return 0;
    }

    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->max_rotations) < 0) {
        return -1;
    }
    (void)unlink(oldp);

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) < 0) {
            return -1;
        }
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    if (ensure_log_exists(cfg->log_path, cfg->create_mode) < 0) {
        return -1;
    }

    return 0;
}

static int check_and_rotate(const config_t *cfg)
{
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_log_exists(cfg->log_path, cfg->create_mode);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if ((uint64_t)st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s -f <logfile> [options]\n"
        "Options:\n"
        "  -f <path>   Log file path (required)\n"
        "  -s <bytes>  Max size before rotation (default: %llu)\n"
        "  -n <count>  Number of rotated files to keep (default: %d)\n"
        "  -i <sec>    Poll interval seconds (default: %d)\n"
        "  -p <path>   PID file path\n"
        "  -m <octal>  Create mode for new log file (default: 0644)\n"
        "  -F          Foreground mode\n"
        "  -h          Show this help\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC
    );
}

static int parse_octal_mode(const char *s, mode_t *out)
{
    char *end = NULL;
    unsigned long v = strtoul(s, &end, 8);
    if (!s[0] || (end && *end != '\0') || v > 0777) {
        return -1;
    }
    *out = (mode_t)v;
    return 0;
}

static int parse_u64(const char *s, uint64_t *out)
{
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (!s[0] || (end && *end != '\0')) {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out)
{
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s[0] || (end && *end != '\0') || v < 0 || v > 1000000) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv)
{
    memset(&g_state, 0, sizeof(g_state));
    g_state.pid_fd = -1;

    config_t *cfg = &g_state.cfg;
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->foreground = 0;
    cfg->use_pidfile = 0;
    cfg->create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:p:m:Fh")) != -1) {
        switch (opt) {
        case 'f':
            if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                fprintf(stderr, "log path too long\n");
                return 1;
            }
            break;
        case 's':
            if (parse_u64(optarg, &cfg->max_size) < 0 || cfg->max_size == 0) {
                fprintf(stderr, "invalid size\n");
                return 1;
            }
            break;
        case 'n':
            if (parse_int(optarg, &cfg->max_rotations) < 0) {
                fprintf(stderr, "invalid rotation count\n");
                return 1;
            }
            break;
        case 'i':
            if (parse_int(optarg, &cfg->interval_sec) < 0 || cfg->interval_sec <= 0) {
                fprintf(stderr, "invalid interval\n");
                return 1;
            }
            break;
        case 'p':
            if (snprintf(cfg->pid_path, sizeof(cfg->pid_path), "%s", optarg) >= (int)sizeof(cfg->pid_path)) {
                fprintf(stderr, "pid path too long\n");
                return 1;
            }
            cfg->use_pidfile = 1;
            break;
        case 'm':
            if (parse_octal_mode(optarg, &cfg->create_mode) < 0) {
                fprintf(stderr, "invalid mode\n");
                return 1;
            }
            break;
        case 'F':
            cfg->foreground = 1;
            break;
        case 'h':
        default:
            usage(argv[0]);
            return 1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (daemonize_if_needed(cfg->foreground) < 0) {
        perror("daemonize");
        return 1;
    }

    if (cfg->use_pidfile) {
        g_state.pid_fd = write_pidfile(cfg->pid_path);
        if (g_state.pid_fd < 0) {
            perror("pidfile");
            return 1;
        }
    }

    if (ensure_log_exists(cfg->log_path, cfg->create_mode) < 0) {
        perror("ensure_log_exists");
        remove_pidfile(&g_state);
        return 1;
    }

    while (!g_state.terminate) {
        if (check_and_rotate(cfg) < 0) {
            log_msg("rotation check failed for %s: %s", cfg->log_path, strerror(errno));
        }

        g_state.reload = 0;

        for (int slept = 0; slept < cfg->interval_sec && !g_state.terminate && !g_state.reload; ++slept) {
            sleep(1);
        }
    }

    remove_pidfile(&g_state);
    return 0;
}
