# Source code

```c
/*
 * memlogd.c
 *
 * Initial memory-constrained log rotation daemon.
 *
 * Features:
 *  - Fixed maximum number of watched logs
 *  - Fixed path lengths
 *  - No heap allocation in steady state
 *  - Polling-based size checks
 *  - Rotate by rename: logfile -> logfile.1, ..., logfile.N
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -i 5 -d \
 *     /var/log/app.log:1048576:5 \
 *     /var/log/other.log:2097152:3
 *
 * Spec format per log:
 *   path:max_bytes:keep_count
 *
 * Notes:
 *  - Rotation uses rename() chain.
 *  - Writers must reopen the file after rotation if they keep it open.
 *  - This implementation recreates the original log file after rotation.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS 32
#define MAX_KEEP 32
#define DEFAULT_INTERVAL_SEC 5
#define MAX_SPEC_LEN 8192

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct log_target {
    char path[PATH_MAX];
    off_t max_bytes;
    int keep_count;
    mode_t create_mode;
    uid_t uid;
    gid_t gid;
    int have_owner;
};

struct config {
    struct log_target logs[MAX_LOGS];
    size_t log_count;
    unsigned interval_sec;
    int daemonize;
    int verbose;
};

static void on_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        g_terminate = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(int verbose, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    if (verbose) {
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
    }
    va_end(ap);
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < INT_MIN || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int split_spec(char *spec, char **path, char **maxb, char **keep) {
    char *p1 = strchr(spec, ':');
    if (!p1) return -1;
    *p1 = '\0';

    char *p2 = strchr(p1 + 1, ':');
    if (!p2) return -1;
    *p2 = '\0';

    *path = spec;
    *maxb = p1 + 1;
    *keep = p2 + 1;
    return 0;
}

static int parse_log_spec(const char *arg, struct log_target *t) {
    char buf[MAX_SPEC_LEN];
    char *path = NULL, *maxb = NULL, *keep = NULL;
    uint64_t max_bytes = 0;
    int keep_count = 0;
    struct stat st;

    if (strlen(arg) >= sizeof(buf)) return -1;
    memcpy(buf, arg, strlen(arg) + 1);

    if (split_spec(buf, &path, &maxb, &keep) < 0) return -1;
    if (strlen(path) == 0 || strlen(path) >= sizeof(t->path)) return -1;
    if (parse_u64(maxb, &max_bytes) < 0) return -1;
    if (parse_int(keep, &keep_count) < 0) return -1;
    if (keep_count < 1 || keep_count > MAX_KEEP) return -1;
    if (max_bytes == 0 || max_bytes > (uint64_t)INT64_MAX) return -1;

    memset(t, 0, sizeof(*t));
    memcpy(t->path, path, strlen(path) + 1);
    t->max_bytes = (off_t)max_bytes;
    t->keep_count = keep_count;
    t->create_mode = 0644;
    t->have_owner = 0;

    if (stat(t->path, &st) == 0) {
        t->create_mode = st.st_mode & 0777;
        t->uid = st.st_uid;
        t->gid = st.st_gid;
        t->have_owner = 1;
    }

    return 0;
}

static int ensure_parentless_create(const struct log_target *t, int verbose) {
    int fd = open(t->path, O_WRONLY | O_CREAT | O_APPEND, t->create_mode);
    if (fd < 0) {
        log_msg(verbose, "open create failed for %s: %s", t->path, strerror(errno));
        return -1;
    }

    if (t->have_owner) {
        if (fchown(fd, t->uid, t->gid) < 0) {
            if (errno != EPERM) {
                log_msg(verbose, "fchown failed for %s: %s", t->path, strerror(errno));
                close(fd);
                return -1;
            }
        }
    }

    if (close(fd) < 0) {
        log_msg(verbose, "close failed for %s: %s", t->path, strerror(errno));
        return -1;
    }

    return 0;
}

static int make_rotated_path(const char *base, int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_one(const struct log_target *t, int verbose) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (t->keep_count > 0) {
        if (make_rotated_path(t->path, t->keep_count, oldp, sizeof(oldp)) < 0) {
            log_msg(verbose, "path too long during rotation: %s", t->path);
            return -1;
        }
        if (unlink(oldp) < 0 && errno != ENOENT) {
            log_msg(verbose, "unlink failed for %s: %s", oldp, strerror(errno));
            return -1;
        }
    }

    for (int i = t->keep_count - 1; i >= 1; --i) {
        if (make_rotated_path(t->path, i, oldp, sizeof(oldp)) < 0) return -1;
        if (make_rotated_path(t->path, i + 1, newp, sizeof(newp)) < 0) return -1;

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                log_msg(verbose, "rename failed %s -> %s: %s", oldp, newp, strerror(errno));
                return -1;
            }
        }
    }

    if (make_rotated_path(t->path, 1, newp, sizeof(newp)) < 0) return -1;
    if (rename(t->path, newp) < 0) {
        if (errno != ENOENT) {
            log_msg(verbose, "rename failed %s -> %s: %s", t->path, newp, strerror(errno));
            return -1;
        }
    }

    if (ensure_parentless_create(t, verbose) < 0) {
        log_msg(verbose, "failed to recreate log file %s", t->path);
        return -1;
    }

    log_msg(verbose, "rotated %s", t->path);
    return 0;
}

static int check_and_rotate(const struct log_target *t, int verbose) {
    struct stat st;
    if (stat(t->path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_parentless_create(t, verbose);
        }
        log_msg(verbose, "stat failed for %s: %s", t->path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(verbose, "not a regular file: %s", t->path);
        return -1;
    }

    if (st.st_size >= t->max_bytes) {
        return rotate_one(t, verbose);
    }

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] [-v] [-i seconds] path:max_bytes:keep [...]\n"
        "  -d           daemonize\n"
        "  -v           verbose logging to stderr\n"
        "  -i seconds   polling interval (default %d)\n",
        prog, DEFAULT_INTERVAL_SEC);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;

    while ((opt = getopt(argc, argv, "dvi:")) != -1) {
        switch (opt) {
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'v':
                cfg->verbose = 1;
                break;
            case 'i': {
                int iv = 0;
                if (parse_int(optarg, &iv) < 0 || iv <= 0) return -1;
                cfg->interval_sec = (unsigned)iv;
                break;
            }
            default:
                return -1;
        }
    }

    for (int i = optind; i < argc; ++i) {
        if (cfg->log_count >= MAX_LOGS) return -1;
        if (parse_log_spec(argv[i], &cfg->logs[cfg->log_count]) < 0) return -1;
        cfg->log_count++;
    }

    if (cfg->log_count == 0) return -1;
    return 0;
}

static void main_loop(const struct config *cfg) {
    while (!g_terminate) {
        for (size_t i = 0; i < cfg->log_count; ++i) {
            (void)check_and_rotate(&cfg->logs[i], cfg->verbose);
        }

        if (g_reload) {
            /* Placeholder: config reload intentionally omitted in initial version. */
            g_reload = 0;
            log_msg(cfg->verbose, "SIGHUP received: reload not implemented");
        }

        for (unsigned slept = 0; slept < cfg->interval_sec && !g_terminate; ++slept) {
            sleep(1);
        }
    }
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_self() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    main_loop(&cfg);
    return 0;
}
