# Source code

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Features:
 *   - Polls a single log file
 *   - Rotates when file size >= max_size
 *   - Keeps a fixed number of rotated logs
 *   - Uses fixed-size buffers only
 *   - Daemonizes optionally
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 5 -d
 *
 * Options:
 *   -f <path>   Log file path
 *   -s <bytes>  Rotate when size >= bytes
 *   -n <count>  Number of rotated files to keep
 *   -i <sec>    Poll interval in seconds
 *   -d          Daemonize
 *   -p <file>   PID file
 *
 * Notes:
 *   - This implementation uses rename-based rotation.
 *   - Writers that keep the old fd open will continue writing to the old inode.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define LOGMSG_BUF_SZ        256

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    char pid_path[PATH_MAX];
    off_t max_size;
    int rotate_count;
    int interval_sec;
    int daemonize;
};

static void on_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        g_terminate = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static void log_stderr(const char *fmt, ...) {
    char buf[LOGMSG_BUF_SZ];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    dprintf(STDERR_FILENO, "%s\n", buf);
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int write_pidfile(const char *path) {
    if (path[0] == '\0') return 0;

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;

    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || len >= (int)sizeof(buf)) {
        close(fd);
        errno = EOVERFLOW;
        return -1;
    }

    ssize_t wr = write(fd, buf, (size_t)len);
    int saved = errno;
    close(fd);
    errno = saved;

    if (wr != len) return -1;
    return 0;
}

static void remove_pidfile(const char *path) {
    if (path[0] != '\0') {
        unlink(path);
    }
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    if (dup2(nullfd, STDIN_FILENO) < 0) return -1;
    if (dup2(nullfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(nullfd, STDERR_FILENO) < 0) return -1;

    if (nullfd > STDERR_FILENO) close(nullfd);
    return 0;
}

static int path_with_suffix(char *dst, size_t dstsz, const char *base, int suffix) {
    int n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    return close(fd);
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotate_count < 1) {
        errno = EINVAL;
        return -1;
    }

    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->rotate_count) < 0) {
        return -1;
    }
    unlink(oldp);

    for (int i = cfg->rotate_count - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    return close(fd);
}

static int should_rotate(const struct config *cfg, bool *out_rotate) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            *out_rotate = false;
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    *out_rotate = (st.st_size >= cfg->max_size);
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > INT32_MAX) {
        errno = ERANGE;
        return -1;
    }

    *out = (int)v;
    return 0;
}

static int parse_off_t(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0) {
        errno = ERANGE;
        return -1;
    }

    *out = (off_t)v;
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> -s <bytes> [-n rotations] [-i interval] [-d] [-p pidfile]\n",
        prog);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->rotate_count = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->max_size = 0;
    cfg->daemonize = 0;

    while ((opt = getopt(argc, argv, "f:s:n:i:dp:")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    errno = ENAMETOOLONG;
                    return -1;
                }
                break;
            case 's':
                if (parse_off_t(optarg, &cfg->max_size) < 0) return -1;
                break;
            case 'n':
                if (parse_int(optarg, &cfg->rotate_count) < 0) return -1;
                break;
            case 'i':
                if (parse_int(optarg, &cfg->interval_sec) < 0) return -1;
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'p':
                if (snprintf(cfg->pid_path, sizeof(cfg->pid_path), "%s", optarg) >= (int)sizeof(cfg->pid_path)) {
                    errno = ENAMETOOLONG;
                    return -1;
                }
                break;
            default:
                errno = EINVAL;
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->max_size <= 0) {
        errno = EINVAL;
        return -1;
    }
    if (cfg->rotate_count < 1 || cfg->interval_sec < 1) {
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    bool rotate = false;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        log_stderr("argument error: %s", strerror(errno));
        return 1;
    }

    if (install_signals() < 0) {
        log_stderr("failed to install signals: %s", strerror(errno));
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        log_stderr("failed to ensure log exists: %s", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_self() < 0) {
            log_stderr("failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    if (write_pidfile(cfg.pid_path) < 0) {
        log_stderr("failed to write pidfile: %s", strerror(errno));
        return 1;
    }

    while (!g_terminate) {
        if (g_reload) {
            g_reload = 0;
            /* Placeholder for future config reload support */
        }

        if (should_rotate(&cfg, &rotate) < 0) {
            log_stderr("stat failed for %s: %s", cfg.log_path, strerror(errno));
        } else if (rotate) {
            if (rotate_logs(&cfg) < 0) {
                log_stderr("rotation failed for %s: %s", cfg.log_path, strerror(errno));
            }
        }

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (nanosleep(&ts, &ts) < 0) {
            if (errno == EINTR) {
                if (g_terminate) break;
                continue;
            }
            break;
        }
    }

    remove_pidfile(cfg.pid_path);
    return 0;
}
