#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            32
#define MAX_ROTATIONS       16
#define MAX_LINE_LEN        1024
#define DEFAULT_INTERVAL_S  5
#define DEFAULT_ROTATIONS   5
#define DEFAULT_MAX_SIZE    (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

typedef struct {
    char path[PATH_MAX];
    uint64_t max_size;
    int rotations;
    int enabled;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    size_t count;
    unsigned interval_s;
    int daemonize;
    char config_path[PATH_MAX];
} daemon_config_t;

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void trim_whitespace(char *s) {
    char *start = s;
    while (*start == ' ' || *start == '\t' || *start == '\n' || *start == '\r') {
        start++;
    }

    if (start != s) {
        memmove(s, start, strlen(start) + 1);
    }

    size_t len = strlen(s);
    while (len > 0) {
        char c = s[len - 1];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            s[len - 1] = '\0';
            len--;
        } else {
            break;
        }
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_size_with_suffix(const char *s, uint64_t *out) {
    size_t len = strlen(s);
    if (len == 0) return -1;

    char numbuf[64];
    if (len >= sizeof(numbuf)) return -1;

    strcpy(numbuf, s);
    char suffix = numbuf[len - 1];
    uint64_t mult = 1;

    if (suffix == 'K' || suffix == 'k') {
        mult = 1024ULL;
        numbuf[len - 1] = '\0';
    } else if (suffix == 'M' || suffix == 'm') {
        mult = 1024ULL * 1024ULL;
        numbuf[len - 1] = '\0';
    } else if (suffix == 'G' || suffix == 'g') {
        mult = 1024ULL * 1024ULL * 1024ULL;
        numbuf[len - 1] = '\0';
    }

    uint64_t base = 0;
    if (parse_u64(numbuf, &base) < 0) return -1;

    if (base > UINT64_MAX / mult) return -1;
    *out = base * mult;
    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_s = DEFAULT_INTERVAL_S;
    cfg->daemonize = 0;
    cfg->count = 0;
}

static int add_log_config(daemon_config_t *cfg, const char *path, uint64_t max_size, int rotations) {
    if (cfg->count >= MAX_LOGS) return -1;
    if (rotations < 1 || rotations > MAX_ROTATIONS) return -1;
    if (strlen(path) >= sizeof(cfg->logs[0].path)) return -1;

    log_config_t *lc = &cfg->logs[cfg->count++];
    memset(lc, 0, sizeof(*lc));
    strcpy(lc->path, path);
    lc->max_size = max_size;
    lc->rotations = rotations;
    lc->enabled = 1;
    return 0;
}

/*
Config format:

interval=5
daemonize=0

log=/var/log/app.log,10M,5
log=/tmp/test.log,1M,3
*/
static int load_config_file(const char *path, daemon_config_t *cfg) {
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;

    daemon_config_t tmp;
    init_default_config(&tmp);
    strncpy(tmp.config_path, path, sizeof(tmp.config_path) - 1);
    tmp.config_path[sizeof(tmp.config_path) - 1] = '\0';

    char line[MAX_LINE_LEN];
    unsigned lineno = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        lineno++;
        trim_whitespace(line);

        if (line[0] == '\0' || line[0] == '#') continue;

        if (strncasecmp(line, "interval=", 9) == 0) {
            int v = 0;
            if (parse_int(line + 9, &v) < 0 || v <= 0) {
                log_stderr("config:%u invalid interval", lineno);
                fclose(fp);
                return -1;
            }
            tmp.interval_s = (unsigned)v;
            continue;
        }

        if (strncasecmp(line, "daemonize=", 10) == 0) {
            int v = 0;
            if (parse_int(line + 10, &v) < 0 || (v != 0 && v != 1)) {
                log_stderr("config:%u invalid daemonize", lineno);
                fclose(fp);
                return -1;
            }
            tmp.daemonize = v;
            continue;
        }

        if (strncasecmp(line, "log=", 4) == 0) {
            char *spec = line + 4;
            char *p1 = strchr(spec, ',');
            if (!p1) {
                log_stderr("config:%u invalid log entry", lineno);
                fclose(fp);
                return -1;
            }
            *p1 = '\0';

            char *p2 = strchr(p1 + 1, ',');
            if (!p2) {
                log_stderr("config:%u invalid log entry", lineno);
                fclose(fp);
                return -1;
            }
            *p2 = '\0';

            char *path_part = spec;
            char *size_part = p1 + 1;
            char *rot_part  = p2 + 1;

            trim_whitespace(path_part);
            trim_whitespace(size_part);
            trim_whitespace(rot_part);

            uint64_t max_size = 0;
            int rotations = 0;

            if (parse_size_with_suffix(size_part, &max_size) < 0 || max_size == 0) {
                log_stderr("config:%u invalid size", lineno);
                fclose(fp);
                return -1;
            }

            if (parse_int(rot_part, &rotations) < 0) {
                log_stderr("config:%u invalid rotations", lineno);
                fclose(fp);
                return -1;
            }

            if (add_log_config(&tmp, path_part, max_size, rotations) < 0) {
                log_stderr("config:%u failed to add log", lineno);
                fclose(fp);
                return -1;
            }
            continue;
        }

        log_stderr("config:%u unknown directive", lineno);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (tmp.count == 0) {
        log_stderr("config contains no log entries");
        return -1;
    }

    *cfg = tmp;
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_one(const log_config_t *lc) {
    struct stat st;
    if (stat(lc->path, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        return -1;
    }

    if ((uint64_t)st.st_size < lc->max_size) {
        return 0;
    }

    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (lc->rotations > 0) {
        if (path_with_suffix(oldp, sizeof(oldp), lc->path, lc->rotations) < 0) {
            return -1;
        }
        unlink(oldp);

        for (int i = lc->rotations - 1; i >= 1; --i) {
            if (path_with_suffix(oldp, sizeof(oldp), lc->path, i) < 0) {
                return -1;
            }
            if (path_with_suffix(newp, sizeof(newp), lc->path, i + 1) < 0) {
                return -1;
            }
            if (rename(oldp, newp) < 0) {
                if (errno != ENOENT) {
                    return -1;
                }
            }
        }

        if (path_with_suffix(newp, sizeof(newp), lc->path, 1) < 0) {
            return -1;
        }

        if (rename(lc->path, newp) < 0) {
            return -1;
        }

        int fd = open(lc->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) {
            return -1;
        }
        close(fd);
    }

    return 0;
}

static void run_loop(daemon_config_t *cfg) {
    while (!g_terminate) {
        if (g_reload) {
            daemon_config_t new_cfg;
            if (load_config_file(cfg->config_path, &new_cfg) == 0) {
                *cfg = new_cfg;
            }
            g_reload = 0;
        }

        for (size_t i = 0; i < cfg->count; ++i) {
            if (!cfg->logs[i].enabled) continue;
            if (rotate_one(&cfg->logs[i]) < 0) {
                /* best-effort initial implementation */
            }
        }

        unsigned slept = 0;
        while (slept < cfg->interval_s && !g_terminate && !g_reload) {
            sleep(1);
            slept++;
        }
    }
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s -c <config>\n", prog);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    init_default_config(&cfg);

    int opt;
    const char *config_path = NULL;

    while ((opt = getopt(argc, argv, "c:")) != -1) {
        switch (opt) {
            case 'c':
                config_path = optarg;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!config_path) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(config_path) >= sizeof(cfg.config_path)) {
        log_stderr("config path too long");
        return 1;
    }

    strcpy(cfg.config_path, config_path);

    if (load_config_file(config_path, &cfg) < 0) {
        log_stderr("failed to load config");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        log_stderr("failed to install signal handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            log_stderr("failed to daemonize");
            return 1;
        }
    }

    run_loop(&cfg);
    return 0;
}
