#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <time.h>
#include <limits.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS 32
#define MAX_ROTATIONS 16
#define MAX_PATH_LEN PATH_MAX
#define DEFAULT_POLL_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_FILE_SIZE (10 * 1024 * 1024ULL)
#define DEFAULT_MEMORY_LIMIT_MB 16

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char path[MAX_PATH_LEN];
    uint64_t max_size;
    int rotations;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    size_t log_count;
    unsigned poll_interval_sec;
    int daemonize;
    int verbose;
    rlim_t memory_limit_bytes;
} daemon_config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    signal(SIGHUP, SIG_IGN);
    signal(SIGPIPE, SIG_IGN);
}

static int set_memory_limits(rlim_t bytes) {
    struct rlimit rl;

    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return -1;
    }

#ifdef RLIMIT_DATA
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        perror("setrlimit(RLIMIT_DATA)");
    }
#endif

#ifdef RLIMIT_RSS
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_RSS, &rl) != 0) {
        /* RLIMIT_RSS may be ignored on Linux */
    }
#endif

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        perror("setsid");
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        perror("chdir");
        return -1;
    }

    umask(027);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) {
            close(fd);
        }
    }

    return 0;
}

static void safe_log(int verbose, const char *msg) {
    if (verbose) {
        write(STDERR_FILENO, msg, strlen(msg));
    }
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int recreate_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) {
        return -1;
    }
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_one_log(const log_config_t *cfg, int verbose) {
    char oldpath[MAX_PATH_LEN];
    char newpath[MAX_PATH_LEN];
    struct stat st;

    if (stat(cfg->path, &st) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    for (int i = cfg->rotations; i >= 1; --i) {
        if (i == cfg->rotations) {
            snprintf(oldpath, sizeof(oldpath), "%s.%d", cfg->path, i);
            if (unlink(oldpath) != 0 && errno != ENOENT) {
                return -1;
            }
        } else {
            snprintf(oldpath, sizeof(oldpath), "%s.%d", cfg->path, i);
            snprintf(newpath, sizeof(newpath), "%s.%d", cfg->path, i + 1);
            if (rename(oldpath, newpath) != 0 && errno != ENOENT) {
                return -1;
            }
        }
    }

    snprintf(newpath, sizeof(newpath), "%s.1", cfg->path);
    if (rename(cfg->path, newpath) != 0) {
        return -1;
    }

    if (recreate_empty_file(cfg->path, st.st_mode & 0777) != 0) {
        return -1;
    }

    if (verbose) {
        char buf[512];
        int n = snprintf(buf, sizeof(buf), "rotated: %s\n", cfg->path);
        if (n > 0) {
            write(STDERR_FILENO, buf, (size_t)n);
        }
    }

    return 0;
}

static int check_and_rotate(const log_config_t *cfg, int verbose) {
    uint64_t size = 0;
    if (get_file_size(cfg->path, &size) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (size >= cfg->max_size) {
        return rotate_one_log(cfg, verbose);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [options] --log <path[:max_size[:rotations]]> ...\n"
        "Options:\n"
        "  -d                 Run as daemon\n"
        "  -v                 Verbose logging\n"
        "  -p <seconds>       Poll interval (default: %u)\n"
        "  -m <MB>            Memory limit in MB (default: %u)\n"
        "  --log spec         Log spec: /path/file.log[:max_size[:rotations]]\n"
        "                     max_size supports suffixes K,M,G\n"
        "Example:\n"
        "  %s -d -p 2 -m 8 --log /var/log/app.log:10M:5\n",
        prog,
        DEFAULT_POLL_INTERVAL_SEC,
        DEFAULT_MEMORY_LIMIT_MB,
        prog
    );
}

static int parse_size(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) {
        return -1;
    }

    uint64_t mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') {
            return -1;
        }
        switch (*end) {
            case 'k':
            case 'K': mult = 1024ULL; break;
            case 'm':
            case 'M': mult = 1024ULL * 1024ULL; break;
            case 'g':
            case 'G': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    *out = (uint64_t)v * mult;
    return 0;
}

static int parse_log_spec(const char *spec, log_config_t *cfg) {
    char buf[MAX_PATH_LEN + 64];
    char *p1, *p2;
    size_t len = strlen(spec);

    if (len == 0 || len >= sizeof(buf)) {
        return -1;
    }

    memcpy(buf, spec, len + 1);

    p1 = strchr(buf, ':');
    p2 = NULL;
    if (p1) {
        *p1++ = '\0';
        p2 = strchr(p1, ':');
        if (p2) {
            *p2++ = '\0';
        }
    }

    if (strlen(buf) == 0 || strlen(buf) >= sizeof(cfg->path)) {
        return -1;
    }

    memset(cfg, 0, sizeof(*cfg));
    memcpy(cfg->path, buf, strlen(buf) + 1);
    cfg->max_size = DEFAULT_MAX_FILE_SIZE;
    cfg->rotations = DEFAULT_MAX_ROTATIONS;

    if (p1 && *p1) {
        if (parse_size(p1, &cfg->max_size) != 0) {
            return -1;
        }
    }

    if (p2 && *p2) {
        char *end = NULL;
        long r = strtol(p2, &end, 10);
        if (end == p2 || *end != '\0' || r < 1 || r > MAX_ROTATIONS) {
            return -1;
        }
        cfg->rotations = (int)r;
    }

    return 0;
}

static int parse_args(int argc, char **argv, daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->memory_limit_bytes = (rlim_t)DEFAULT_MEMORY_LIMIT_MB * 1024 * 1024;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-d") == 0) {
            cfg->daemonize = 1;
        } else if (strcmp(argv[i], "-v") == 0) {
            cfg->verbose = 1;
        } else if (strcmp(argv[i], "-p") == 0) {
            if (i + 1 >= argc) return -1;
            char *end = NULL;
            long v = strtol(argv[++i], &end, 10);
            if (end == argv[i] || *end != '\0' || v <= 0 || v > 86400) return -1;
            cfg->poll_interval_sec = (unsigned)v;
        } else if (strcmp(argv[i], "-m") == 0) {
            if (i + 1 >= argc) return -1;
            char *end = NULL;
            long v = strtol(argv[++i], &end, 10);
            if (end == argv[i] || *end != '\0' || v < 4 || v > 1024) return -1;
            cfg->memory_limit_bytes = (rlim_t)v * 1024 * 1024;
        } else if (strcmp(argv[i], "--log") == 0) {
            if (i + 1 >= argc) return -1;
            if (cfg->log_count >= MAX_LOGS) return -1;
            if (parse_log_spec(argv[++i], &cfg->logs[cfg->log_count]) != 0) return -1;
            cfg->log_count++;
        } else {
            return -1;
        }
    }

    if (cfg->log_count == 0) {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    daemon_config_t cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    install_signal_handlers();

    if (set_memory_limits(cfg.memory_limit_bytes) != 0) {
        fprintf(stderr, "failed to set memory limits\n");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            return 1;
        }
    }

    safe_log(cfg.verbose, "log rotation daemon started\n");

    while (g_running) {
        for (size_t i = 0; i < cfg.log_count; ++i) {
            if (check_and_rotate(&cfg.logs[i], cfg.verbose) != 0) {
                if (cfg.verbose) {
                    char buf[512];
                    int n = snprintf(buf, sizeof(buf),
                                     "error processing %s: %s\n",
                                     cfg.logs[i].path, strerror(errno));
                    if (n > 0) {
                        write(STDERR_FILENO, buf, (size_t)n);
                    }
                }
            }
        }

        for (unsigned slept = 0; g_running && slept < cfg.poll_interval_sec; ++slept) {
            sleep(1);
        }
    }

    safe_log(cfg.verbose, "log rotation daemon stopped\n");
    return 0;
}
