## Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 16
#define DEFAULT_POLL_INTERVAL_SEC 2
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#define DEFAULT_RETENTION 5
#define LOGMSG_MAX 256

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    size_t max_size;
    int retention;
    int poll_interval_sec;
    int daemonize;
    rlim_t memory_limit_bytes;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_log_stderr(const char *fmt, ...) {
    char buf[LOGMSG_MAX];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    write(STDERR_FILENO, buf, strnlen(buf, sizeof(buf)));
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->retention < 1 || cfg->retention > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    if (build_rotated_path(cfg->log_path, cfg->retention, old_path, sizeof(old_path)) != 0) {
        return -1;
    }

    unlink(old_path);

    for (int i = cfg->retention - 1; i >= 1; --i) {
        if (build_rotated_path(cfg->log_path, i, old_path, sizeof(old_path)) != 0) {
            return -1;
        }
        if (build_rotated_path(cfg->log_path, i + 1, new_path, sizeof(new_path)) != 0) {
            return -1;
        }
        rename(old_path, new_path);
    }

    if (build_rotated_path(cfg->log_path, 1, new_path, sizeof(new_path)) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    if (ensure_log_exists(cfg->log_path) != 0) {
        return -1;
    }

    return 0;
}

static int parse_size(const char *s, size_t *out) {
    char *end = NULL;
    unsigned long long val = strtoull(s, &end, 10);
    if (end == s) return -1;

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (strcmp(end, "K") == 0 || strcmp(end, "k") == 0) mult = 1024ULL;
        else if (strcmp(end, "M") == 0 || strcmp(end, "m") == 0) mult = 1024ULL * 1024ULL;
        else if (strcmp(end, "G") == 0 || strcmp(end, "g") == 0) mult = 1024ULL * 1024ULL * 1024ULL;
        else return -1;
    }

    unsigned long long result = val * mult;
    if (result > SIZE_MAX) return -1;
    *out = (size_t)result;
    return 0;
}

static void usage(const char *prog) {
    safe_log_stderr(
        "Usage: %s -f <logfile> [-s maxsize] [-r retention] [-p pollsec] [-m membytes] [-d]\n"
        "  -f <logfile>   Path to log file\n"
        "  -s <size>      Rotate at size, e.g. 1048576, 10M, 512K (default 10M)\n"
        "  -r <count>     Number of rotated files to keep, 1-%d (default %d)\n"
        "  -p <sec>       Poll interval seconds (default %d)\n"
        "  -m <bytes>     RLIMIT_AS memory limit in bytes\n"
        "  -d             Daemonize\n",
        prog, MAX_ROTATIONS, DEFAULT_RETENTION, DEFAULT_POLL_INTERVAL_SEC
    );
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->retention = DEFAULT_RETENTION;
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->memory_limit_bytes = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:r:p:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    return -1;
                }
                break;
            case 's':
                if (parse_size(optarg, &cfg->max_size) != 0) {
                    return -1;
                }
                break;
            case 'r':
                cfg->retention = atoi(optarg);
                if (cfg->retention < 1 || cfg->retention > MAX_ROTATIONS) {
                    return -1;
                }
                break;
            case 'p':
                cfg->poll_interval_sec = atoi(optarg);
                if (cfg->poll_interval_sec < 1 || cfg->poll_interval_sec > 3600) {
                    return -1;
                }
                break;
            case 'm':
                cfg->memory_limit_bytes = (rlim_t)strtoull(optarg, NULL, 10);
                if (cfg->memory_limit_bytes == 0) {
                    return -1;
                }
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        return -1;
    }

    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;

    return 0;
}

static int run_daemon(const config_t *cfg) {
    if (ensure_log_exists(cfg->log_path) != 0) {
        safe_log_stderr("failed to create log file: %s\n", strerror(errno));
        return 1;
    }

    while (g_running) {
        off_t size = 0;
        if (get_file_size(cfg->log_path, &size) == 0) {
            if ((size_t)size >= cfg->max_size) {
                if (rotate_logs(cfg) != 0) {
                    safe_log_stderr("rotation failed for %s: %s\n", cfg->log_path, strerror(errno));
                }
            }
        } else {
            if (errno == ENOENT) {
                if (ensure_log_exists(cfg->log_path) != 0) {
                    safe_log_stderr("failed to recreate missing log file: %s\n", strerror(errno));
                }
            } else {
                safe_log_stderr("stat failed on %s: %s\n", cfg->log_path, strerror(errno));
            }
        }

        for (int i = 0; i < cfg->poll_interval_sec && g_running; ++i) {
            sleep(1);
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signal_handlers() != 0) {
        safe_log_stderr("failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            safe_log_stderr("failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    if (cfg.memory_limit_bytes > 0) {
        if (set_memory_limit(cfg.memory_limit_bytes) != 0) {
            safe_log_stderr("failed to set memory limit: %s\n", strerror(errno));
            return 1;
        }
    }

    return run_daemon(&cfg);
}
