static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static void log_stderr(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len < sizeof(buf) - 1) {
        buf[len++] = '\n';
        buf[len] = '\0';
    }
    (void)write(STDERR_FILENO, buf, len);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, unsigned int suffix) {
    int n = snprintf(out, out_sz, "%s.%u", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->rotations == 0) {
        int fd = open(cfg->log_path, O_WRONLY);
        if (fd >= 0) {
            int rc = ftruncate(fd, 0);
            close(fd);
            return rc;
        }
        return -1;
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->rotations) != 0) {
        return -1;
    }
    (void)unlink(old_path);

    for (unsigned int i = cfg->rotations; i > 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i - 1) != 0) {
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i) != 0) {
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (cfg->truncate_on_rotate_failure) {
            int fd = open(cfg->log_path, O_WRONLY);
            if (fd >= 0) {
                int rc = ftruncate(fd, 0);
                close(fd);
                return rc;
            }
        }
        return -1;
    }

    int fd = open(cfg->log_path, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int should_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    return ((size_t)st.st_size >= cfg->max_size) ? 1 : 0;
}

static void usage(const char *prog) {
    log_stderr(
        "Usage: %s --log PATH [options]\n"
        "Options:\n"
        "  --size BYTES          Rotate when log reaches BYTES (default: %u)\n"
        "  --rotations N         Number of rotated files to keep (default: %u)\n"
        "  --interval SEC        Poll interval in seconds (default: %u)\n"
        "  --memory-limit MB     RLIMIT_AS in MB (default: %u)\n"
        "  --daemon              Run as daemon\n"
        "  --truncate-fallback   Truncate if rename rotation fails\n",
        prog,
        DEFAULT_MAX_SIZE,
        DEFAULT_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC,
        DEFAULT_MEMORY_LIMIT_MB
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->truncate_on_rotate_failure = 0;
    cfg->memory_limit_bytes = (rlim_t)DEFAULT_MEMORY_LIMIT_MB * 1024 * 1024;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--log") == 0) {
            if (++i >= argc) return -1;
            if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", argv[i]) >= (int)sizeof(cfg->log_path)) {
                return -1;
            }
        } else if (strcmp(argv[i], "--size") == 0) {
            uint64_t v;
            if (++i >= argc || parse_u64(argv[i], &v) != 0) return -1;
            cfg->max_size = (size_t)v;
        } else if (strcmp(argv[i], "--rotations") == 0) {
            uint64_t v;
            if (++i >= argc || parse_u64(argv[i], &v) != 0) return -1;
            if (v > 1000) return -1;
            cfg->rotations = (unsigned int)v;
        } else if (strcmp(argv[i], "--interval") == 0) {
            uint64_t v;
            if (++i >= argc || parse_u64(argv[i], &v) != 0) return -1;
            if (v == 0 || v > 86400) return -1;
            cfg->interval_sec = (unsigned int)v;
        } else if (strcmp(argv[i], "--memory-limit") == 0) {
            uint64_t v;
            if (++i >= argc || parse_u64(argv[i], &v) != 0) return -1;
            if (v == 0 || v > 1024) return -1;
            cfg->memory_limit_bytes = (rlim_t)v * 1024 * 1024;
        } else if (strcmp(argv[i], "--daemon") == 0) {
            cfg->daemonize = 1;
        } else if (strcmp(argv[i], "--truncate-fallback") == 0) {
            cfg->truncate_on_rotate_failure = 1;
        } else {
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    if (cfg->max_size == 0) return -1;

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    install_signal_handlers();

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            log_stderr("daemonize failed: %s", strerror(errno));
            return 1;
        }
    }

    if (set_memory_limit(cfg.memory_limit_bytes) != 0) {
        log_stderr("failed to set memory limit: %s", strerror(errno));
        return 1;
    }

    while (g_running) {
        int rc = should_rotate(&cfg);
        if (rc < 0) {
            log_stderr("stat failed for %s: %s", cfg.log_path, strerror(errno));
        } else if (rc > 0) {
            if (rotate_logs(&cfg) != 0) {
                log_stderr("rotation failed for %s: %s", cfg.log_path, strerror(errno));
            }
        }

        for (unsigned int slept = 0; g_running && slept < cfg.interval_sec; ++slept) {
            sleep(1);
        }
    }

    return 0;
}
