# Source code

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -i 5 -s 1048576 -k 5 /var/log/app.log /var/log/worker.log
 *
 * Notes:
 * - Rotates when file size >= max_size
 * - Keeps rotated files as .1, .2, ..., .N
 * - Uses polling, not inotify
 * - Avoids dynamic allocation in steady-state
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOG_FILES 64
#define MAX_ROTATIONS 32
#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)
#define DEFAULT_KEEP 5

static volatile sig_atomic_t g_terminate = 0;

typedef struct {
    char path[PATH_MAX];
    off_t last_size;
    ino_t last_ino;
    dev_t last_dev;
    int initialized;
} log_target_t;

typedef struct {
    unsigned int interval_sec;
    uint64_t max_size;
    unsigned int keep;
    int daemonize;
    int copytruncate;
    int verbose;
    size_t num_targets;
    log_target_t targets[MAX_LOG_FILES];
} config_t;

static void on_signal(int signo) {
    (void)signo;
    g_terminate = 1;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) {
        return;
    }

    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    dprintf(STDERR_FILENO, "%s\n", buf);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);

    if (n < 0) return -1;
    if ((size_t)n >= dstsz) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int copy_file_contents(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    char buf[4096];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}

static int truncate_file(const char *path) {
    return truncate(path, 0);
}

static int rotate_by_rename(const char *path, unsigned int keep, int verbose) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep == 0 || keep > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    for (unsigned int i = keep; i > 0; --i) {
        if (i == keep) {
            if (safe_snprintf(oldp, sizeof(oldp), "%s.%u", path, i) < 0) {
                errno = ENAMETOOLONG;
                return -1;
            }
            unlink(oldp);
        }

        if (i == 1) {
            if (safe_snprintf(newp, sizeof(newp), "%s.1", path) < 0) {
                errno = ENAMETOOLONG;
                return -1;
            }
            if (rename(path, newp) < 0) {
                return -1;
            }
            log_msg(verbose, "rotated %s -> %s", path, newp);
        } else {
            if (safe_snprintf(oldp, sizeof(oldp), "%s.%u", path, i - 1) < 0) {
                errno = ENAMETOOLONG;
                return -1;
            }
            if (safe_snprintf(newp, sizeof(newp), "%s.%u", path, i) < 0) {
                errno = ENAMETOOLONG;
                return -1;
            }
            rename(oldp, newp);
        }
    }

    return 0;
}

static int rotate_by_copytruncate(const char *path, unsigned int keep, int verbose) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep == 0 || keep > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    for (unsigned int i = keep; i > 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%u", path, i - 1) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf(newp, sizeof(newp), "%s.%u", path, i) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (i == keep) {
            unlink(newp);
        }
        rename(oldp, newp);
    }

    if (safe_snprintf(newp, sizeof(newp), "%s.1", path) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (copy_file_contents(path, newp) < 0) {
        return -1;
    }

    if (truncate_file(path) < 0) {
        return -1;
    }

    log_msg(verbose, "copytruncate rotated %s -> %s", path, newp);
    return 0;
}

static int stat_target(log_target_t *t, struct stat *st) {
    if (stat(t->path, st) < 0) {
        return -1;
    }
    return 0;
}

static int maybe_rotate_target(config_t *cfg, log_target_t *t) {
    struct stat st;

    if (stat_target(t, &st) < 0) {
        if (errno != ENOENT) {
            log_msg(cfg->verbose, "stat failed for %s: %s", t->path, strerror(errno));
        }
        t->initialized = 0;
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(cfg->verbose, "skipping non-regular file: %s", t->path);
        return 0;
    }

    if (!t->initialized) {
        t->last_size = st.st_size;
        t->last_ino = st.st_ino;
        t->last_dev = st.st_dev;
        t->initialized = 1;
    }

    if ((uint64_t)st.st_size >= cfg->max_size) {
        int rc;
        if (cfg->copytruncate) {
            rc = rotate_by_copytruncate(t->path, cfg->keep, cfg->verbose);
        } else {
            rc = rotate_by_rename(t->path, cfg->keep, cfg->verbose);
        }

        if (rc < 0) {
            log_msg(cfg->verbose, "rotation failed for %s: %s", t->path, strerror(errno));
            return -1;
        }

        t->initialized = 0;
        return 1;
    }

    if (st.st_ino != t->last_ino || st.st_dev != t->last_dev) {
        log_msg(cfg->verbose, "file replaced/reopened: %s", t->path);
    } else if (st.st_size < t->last_size) {
        log_msg(cfg->verbose, "file truncated externally: %s", t->path);
    }

    t->last_size = st.st_size;
    t->last_ino = st.st_ino;
    t->last_dev = st.st_dev;
    t->initialized = 1;
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s [options] <logfile> [logfile...]\n"
        "Options:\n"
        "  -i <sec>    Poll interval in seconds (default: %u)\n"
        "  -s <bytes>  Rotate when size >= bytes (default: %llu)\n"
        "  -k <count>  Number of rotated files to keep (default: %u, max: %u)\n"
        "  -d          Daemonize\n"
        "  -c          Use copytruncate instead of rename\n"
        "  -v          Verbose logging\n",
        prog,
        DEFAULT_INTERVAL_SEC,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_KEEP,
        MAX_ROTATIONS
    );
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v > UINT_MAX) return -1;
    *out = (unsigned int)v;
    return 0;
}

static int add_target(config_t *cfg, const char *path) {
    if (cfg->num_targets >= MAX_LOG_FILES) {
        errno = ENOSPC;
        return -1;
    }

    size_t len = strnlen(path, PATH_MAX);
    if (len == 0 || len >= PATH_MAX) {
        errno = ENAMETOOLONG;
        return -1;
    }

    log_target_t *t = &cfg->targets[cfg->num_targets];
    memset(t, 0, sizeof(*t));
    memcpy(t->path, path, len);
    t->path[len] = '\0';

    cfg->num_targets++;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.interval_sec = DEFAULT_INTERVAL_SEC;
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.keep = DEFAULT_KEEP;

    int opt;
    while ((opt = getopt(argc, argv, "i:s:k:dcv")) != -1) {
        switch (opt) {
            case 'i':
                if (parse_u32(optarg, &cfg.interval_sec) < 0 || cfg.interval_sec == 0) {
                    dprintf(STDERR_FILENO, "invalid interval: %s\n", optarg);
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) < 0 || cfg.max_size == 0) {
                    dprintf(STDERR_FILENO, "invalid size: %s\n", optarg);
                    return 1;
                }
                break;
            case 'k':
                if (parse_u32(optarg, &cfg.keep) < 0 || cfg.keep == 0 || cfg.keep > MAX_ROTATIONS) {
                    dprintf(STDERR_FILENO, "invalid keep count: %s\n", optarg);
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'c':
                cfg.copytruncate = 1;
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return 1;
    }

    for (int i = optind; i < argc; ++i) {
        if (add_target(&cfg, argv[i]) < 0) {
            dprintf(STDERR_FILENO, "failed to add target %s: %s\n", argv[i], strerror(errno));
            return 1;
        }
    }

    if (install_signal_handlers() < 0) {
        dprintf(STDERR_FILENO, "failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            dprintf(STDERR_FILENO, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    log_msg(cfg.verbose, "memlogd started: targets=%zu interval=%u size=%llu keep=%u mode=%s",
            cfg.num_targets,
            cfg.interval_sec,
            (unsigned long long)cfg.max_size,
            cfg.keep,
            cfg.copytruncate ? "copytruncate" : "rename");

    while (!g_terminate) {
        for (size_t i = 0; i < cfg.num_targets; ++i) {
            maybe_rotate_target(&cfg, &cfg.targets[i]);
        }

        for (unsigned int slept = 0; slept < cfg.interval_sec && !g_terminate; ++slept) {
            sleep(1);
        }
    }

    log_msg(cfg.verbose, "memlogd exiting");
    return 0;
}
```

