#include <sys/resource.h>

static int apply_limits(rlim_t as_limit, rlim_t data_limit, rlim_t stack_limit, rlim_t nofile_limit) {
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = as_limit;
    if (setrlimit(RLIMIT_AS, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = data_limit;
    if (setrlimit(RLIMIT_DATA, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = stack_limit;
    if (setrlimit(RLIMIT_STACK, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = nofile_limit;
    if (setrlimit(RLIMIT_NOFILE, &rl) < 0) return -1;

    return 0;
}
