```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE      (10 * 1024 * 1024ULL)
#define DEFAULT_MAX_FILES     5
#define DEFAULT_POLL_INTERVAL 5
#define DEFAULT_MEMORY_LIMIT  (8 * 1024 * 1024ULL)

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    unsigned long long max_size;
    int max_files;
    int poll_interval;
    int daemonize;
    rlim_t memory_limit;
};

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int apply_resource_limits(rlim_t mem_limit) {
    struct rlimit rl;

    rl.rlim_cur = 0;
    rl.rlim_max = 0;
    if (setrlimit(RLIMIT_CORE, &rl) < 0) {
        return -1;
    }

#ifdef RLIMIT_AS
    rl.rlim_cur = mem_limit;
    rl.rlim_max = mem_limit;
    if (setrlimit(RLIMIT_AS, &rl) < 0) {
        return -1;
    }
#endif

#ifdef RLIMIT_DATA
    rl.rlim_cur = mem_limit;
    rl.rlim_max = mem_limit;
    if (setrlimit(RLIMIT_DATA, &rl) < 0) {
        return -1;
    }
#endif

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    if (close(fd) < 0) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    for (int i = cfg->max_files - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    if (fsync(fd) < 0) {
        close(fd);
        return -1;
    }
    if (close(fd) < 0) return -1;

    return 0;
}

static int should_rotate(const struct config *cfg, int *result) {
    struct stat st;
    if (lstat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            *result = 0;
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    *result = ((unsigned long long)st.st_size >= cfg->max_size) ? 1 : 0;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [options]\n"
        "Options:\n"
        "  -f <path>   Log file path\n"
        "  -s <bytes>  Max size before rotation (default: %llu)\n"
        "  -n <count>  Number of rotated files to keep (default: %d)\n"
        "  -p <sec>    Poll interval seconds (default: %d)\n"
        "  -m <bytes>  Memory limit bytes (default: %llu)\n"
        "  -d          Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_FILES,
        DEFAULT_POLL_INTERVAL,
        (unsigned long long)DEFAULT_MEMORY_LIMIT
    );
}

static int parse_ull(const char *s, unsigned long long *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 1 || v > 1000) return -1;
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_files = DEFAULT_MAX_FILES;
    cfg.poll_interval = DEFAULT_POLL_INTERVAL;
    cfg.daemonize = 0;
    cfg.memory_limit = DEFAULT_MEMORY_LIMIT;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    log_stderr("log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_ull(optarg, &cfg.max_size) < 0 || cfg.max_size == 0) {
                    log_stderr("invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_files) < 0) {
                    log_stderr("invalid max files\n");
                    return 1;
                }
                break;
            case 'p':
                if (parse_int(optarg, &cfg.poll_interval) < 0) {
                    log_stderr("invalid poll interval\n");
                    return 1;
                }
                break;
            case 'm': {
                unsigned long long v;
                if (parse_ull(optarg, &v) < 0 || v < (1024 * 1024ULL)) {
                    log_stderr("invalid memory limit\n");
                    return 1;
                }
                cfg.memory_limit = (rlim_t)v;
                break;
            }
            case 'd':
                cfg.daemonize = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (apply_resource_limits(cfg.memory_limit) < 0) {
        perror("setrlimit");
        return 1;
    }

    while (!g_terminate) {
        int rotate = 0;

        if (g_reload) {
            g_reload = 0;
        }

        if (should_rotate(&cfg, &rotate) < 0) {
            /* In daemon mode stderr goes to /dev/null; keep behavior simple */
        } else if (rotate) {
            if (rotate_logs(&cfg) < 0) {
                /* Best-effort: continue loop */
            }
        }

        for (int i = 0; i < cfg.poll_interval; ++i) {
            if (g_terminate || g_reload) break;
            sleep(1);
        }
    }

    return 0;
}
