Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to run under **strict memory limits**.

It aims to be:

- **single-process**
- **low-allocation**
- **fixed-size buffers**
- **no dynamic memory in steady state**
- **simple and auditable**

It supports:

- monitoring a single log file
- rotating when size exceeds a threshold
- keeping a fixed number of rotated files
- optional periodic polling
- reopening the active log file after rotation

---

# Design goals

This implementation is intentionally conservative:

- avoids heap allocation during normal operation
- uses fixed-size path buffers
- uses `stat`, `rename`, and `truncate`-style rotation logic
- polls instead of using heavier event frameworks
- keeps state in a small struct
- can daemonize or run in foreground

This is a good **initial implementation**, not a production-complete one. It does **not** yet include:

- config file parsing
- signal-driven reload
- compression
- multi-log support
- inode-following for external rotations
- privilege dropping
- journald/syslog integration
- lock files

---

# Source code

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Features:
 * - Monitors one log file
 * - Rotates when file size exceeds max_size
 * - Keeps N rotated files: logfile.1 ... logfile.N
 * - Uses fixed-size buffers, minimal heap usage
 * - Polling-based loop
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -std=c11 -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 5
 *
 * Notes:
 * - This implementation assumes the writer keeps writing to the same pathname.
 * - After rotation, a new empty file is created at the original path.
 * - If the writer holds the old file descriptor open, it may continue writing
 *   to the rotated file. Handling that robustly requires cooperation from the
 *   writer (e.g. SIGHUP/reopen) or more advanced strategies.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10 * 1024 * 1024ULL)
#define MAX_ROTATIONS        99

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    uint64_t max_size;
    unsigned int rotations;
    unsigned int interval_sec;
    int foreground;
    int verbose;
};

struct daemon_state {
    struct config cfg;
    ino_t last_inode;
    dev_t last_dev;
    off_t last_size;
};

static void on_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        g_terminate = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(const struct config *cfg, const char *level, const char *fmt, ...) {
    va_list ap;
    char buf[512];
    int n;
    time_t now;
    struct tm tmv;

    now = time(NULL);
    localtime_r(&now, &tmv);

    n = snprintf(buf, sizeof(buf),
                 "%04d-%02d-%02d %02d:%02d:%02d [%s] ",
                 tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
                 tmv.tm_hour, tmv.tm_min, tmv.tm_sec, level);
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        return;
    }

    va_start(ap, fmt);
    vsnprintf(buf + (size_t)n, sizeof(buf) - (size_t)n, fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len + 1 < sizeof(buf)) {
        buf[len++] = '\n';
        buf[len] = '\0';
    }

    if (cfg->foreground || cfg->verbose) {
        (void)write(STDERR_FILENO, buf, len);
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    unsigned long long v;

    if (s == NULL || *s == '\0') {
        return -1;
    }

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }

    *out = (uint64_t)v;
    return 0;
}

static int parse_uint(const char *s, unsigned int *out) {
    uint64_t v;
    if (parse_u64(s, &v) != 0 || v > UINT_MAX) {
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> [-s max_size] [-n rotations] [-i interval] [-F] [-v]\n"
        "  -f <logfile>   Path to log file to monitor\n"
        "  -s <bytes>     Rotate when size >= bytes (default: %u)\n"
        "  -n <count>     Number of rotated files to keep (default: %u, max: %u)\n"
        "  -i <sec>       Poll interval in seconds (default: %u)\n"
        "  -F             Run in foreground\n"
        "  -v             Verbose logging\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, MAX_ROTATIONS, DEFAULT_INTERVAL_SEC);
}

static int daemonize_self(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (fd != STDIN_FILENO) dup2(fd, STDIN_FILENO);
    if (fd != STDOUT_FILENO) dup2(fd, STDOUT_FILENO);
    if (fd != STDERR_FILENO) dup2(fd, STDERR_FILENO);

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) != 0) return -1;

    return 0;
}

static int build_rotated_path(const char *base, unsigned int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const struct config *cfg, mode_t *mode_out, uid_t *uid_out, gid_t *gid_out) {
    struct stat st;
    int fd;

    if (stat(cfg->log_path, &st) == 0) {
        if (!S_ISREG(st.st_mode)) {
            log_msg(cfg, "ERROR", "path exists but is not a regular file: %s", cfg->log_path);
            return -1;
        }
        *mode_out = st.st_mode & 0777;
        *uid_out = st.st_uid;
        *gid_out = st.st_gid;
        return 0;
    }

    if (errno != ENOENT) {
        log_msg(cfg, "ERROR", "stat failed for %s: %s", cfg->log_path, strerror(errno));
        return -1;
    }

    fd = open(cfg->log_path, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        log_msg(cfg, "ERROR", "failed to create log file %s: %s", cfg->log_path, strerror(errno));
        return -1;
    }
    close(fd);

    if (stat(cfg->log_path, &st) != 0) {
        log_msg(cfg, "ERROR", "stat after create failed for %s: %s", cfg->log_path, strerror(errno));
        return -1;
    }

    *mode_out = st.st_mode & 0777;
    *uid_out = st.st_uid;
    *gid_out = st.st_gid;
    return 0;
}

static int create_fresh_log(const struct config *cfg, mode_t mode, uid_t uid, gid_t gid) {
    int fd = open(cfg->log_path, O_CREAT | O_WRONLY | O_TRUNC, mode);
    if (fd < 0) {
        log_msg(cfg, "ERROR", "failed to create fresh log %s: %s", cfg->log_path, strerror(errno));
        return -1;
    }
    close(fd);

    if (chown(cfg->log_path, uid, gid) != 0) {
        if (errno != EPERM) {
            log_msg(cfg, "WARN", "chown failed on %s: %s", cfg->log_path, strerror(errno));
        }
    }

    if (chmod(cfg->log_path, mode) != 0) {
        log_msg(cfg, "WARN", "chmod failed on %s: %s", cfg->log_path, strerror(errno));
    }

    return 0;
}

static int rotate_logs(struct daemon_state *st) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    mode_t mode;
    uid_t uid;
    gid_t gid;

    if (ensure_log_exists(&st->cfg, &mode, &uid, &gid) != 0) {
        return -1;
    }

    for (unsigned int i = st->cfg.rotations; i > 0; --i) {
        if (build_rotated_path(st->cfg.log_path, i, oldp, sizeof(oldp)) != 0) {
            log_msg(&st->cfg, "ERROR", "rotated path too long");
            return -1;
        }

        if (i == st->cfg.rotations) {
            (void)unlink(oldp);
            continue;
        }

        if (build_rotated_path(st->cfg.log_path, i + 1, newp, sizeof(newp)) != 0) {
            log_msg(&st->cfg, "ERROR", "rotated path too long");
            return -1;
        }

        if (rename(oldp, newp) != 0 && errno != ENOENT) {
            log_msg(&st->cfg, "ERROR", "rename %s -> %s failed: %s", oldp, newp, strerror(errno));
            return -1;
        }
    }

    if (build_rotated_path(st->cfg.log_path, 1, newp, sizeof(newp)) != 0) {
        log_msg(&st->cfg, "ERROR", "rotated path too long");
        return -1;
    }

    if (rename(st->cfg.log_path, newp) != 0) {
        if (errno != ENOENT) {
            log_msg(&st->cfg, "ERROR", "rename %s -> %s failed: %s",
                    st->cfg.log_path, newp, strerror(errno));
            return -1;
        }
    }

    if (create_fresh_log(&st->cfg, mode, uid, gid) != 0) {
        return -1;
    }

    log_msg(&st->cfg, "INFO", "rotated log: %s -> %s", st->cfg.log_path, newp);
    return 0;
}

static int check_and_rotate(struct daemon_state *st) {
    struct stat stbuf;

    if (stat(st->cfg.log_path, &stbuf) != 0) {
        if (errno == ENOENT) {
            mode_t mode = 0644;
            uid_t uid = getuid();
            gid_t gid = getgid();
            if (create_fresh_log(&st->cfg, mode, uid, gid) != 0) {
                return -1;
            }
            log_msg(&st->cfg, "INFO", "created missing log file: %s", st->cfg.log_path);
            return 0;
        }
        log_msg(&st->cfg, "ERROR", "stat failed for %s: %s", st->cfg.log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(stbuf.st_mode)) {
        log_msg(&st->cfg, "ERROR", "not a regular file: %s", st->cfg.log_path);
        return -1;
    }

    st->last_inode = stbuf.st_ino;
    st->last_dev = stbuf.st_dev;
    st->last_size = stbuf.st_size;

    if ((uint64_t)stbuf.st_size >= st->cfg.max_size) {
        return rotate_logs(st);
    }

    return 0;
}

static int sleep_interruptible(unsigned int sec) {
    struct timespec req, rem;
    req.tv_sec = (time_t)sec;
    req.tv_nsec = 0;

    while (nanosleep(&req, &rem) != 0) {
        if (errno == EINTR) {
            if (g_terminate || g_reload) {
                return 0;
            }
            req = rem;
            continue;
        }
        return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    struct daemon_state st;
    int opt;

    memset(&st, 0, sizeof(st));
    st.cfg.max_size = DEFAULT_MAX_SIZE;
    st.cfg.rotations = DEFAULT_ROTATIONS;
    st.cfg.interval_sec = DEFAULT_INTERVAL_SEC;
    st.cfg.foreground = 0;
    st.cfg.verbose = 0;

    while ((opt = getopt(argc, argv, "f:s:n:i:Fv")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(st.cfg.log_path)) {
                    dprintf(STDERR_FILENO, "log path too long\n");
                    return 1;
                }
                strcpy(st.cfg.log_path, optarg);
                break;
            case 's':
                if (parse_u64(optarg, &st.cfg.max_size) != 0 || st.cfg.max_size == 0) {
                    dprintf(STDERR_FILENO, "invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_uint(optarg, &st.cfg.rotations) != 0 ||
                    st.cfg.rotations == 0 || st.cfg.rotations > MAX_ROTATIONS) {
                    dprintf(STDERR_FILENO, "invalid rotation count\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_uint(optarg, &st.cfg.interval_sec) != 0 || st.cfg.interval_sec == 0) {
                    dprintf(STDERR_FILENO, "invalid interval\n");
                    return 1;
                }
                break;
            case 'F':
                st.cfg.foreground = 1;
                break;
            case 'v':
                st.cfg.verbose = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (st.cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signals() != 0) {
        dprintf(STDERR_FILENO, "failed to install signal handlers\n");
        return 1;
    }

    if (!st.cfg.foreground) {
        if (daemonize_self() != 0) {
            dprintf(STDERR_FILENO, "failed to daemonize\n");
            return 1;
        }
    }

    log_msg(&st.cfg, "INFO", "starting memlogd for %s", st.cfg.log_path);

    while (!g_terminate) {
        if (check_and_rotate(&st) != 0) {
            log_msg(&st.cfg, "WARN", "check failed; retrying");
        }

        if (g_reload) {
            g_reload = 0;
            log_msg(&st.cfg, "INFO", "received SIGHUP");
        }

        if (sleep_interruptible(st.cfg.interval_sec) != 0) {
            log_msg(&st.cfg, "WARN", "sleep failed: %s", strerror(errno));
        }
    }

    log_msg(&st.cfg, "INFO", "terminating");
    return 0;
}
```

