# Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_LOGS 16
#define MAX_PATH_LEN 256
#define DEFAULT_POLL_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int rotations;
    int enabled;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    int log_count;
    unsigned int poll_interval_sec;
    int truncate_after_rotate;
    int foreground;
} daemon_config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_log(const char *msg) {
    if (msg) {
        write(STDERR_FILENO, msg, strlen(msg));
    }
}

static void safe_log2(const char *a, const char *b) {
    if (a) write(STDERR_FILENO, a, strlen(a));
    if (b) write(STDERR_FILENO, b, strlen(b));
}

static int file_exists(const char *path) {
    struct stat st;
    return (stat(path, &st) == 0);
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (!path || !size_out) return -1;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n;
    if (!base || !out || out_sz == 0) return -1;
    n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_one(const log_config_t *logcfg, int truncate_after_rotate) {
    int i;
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];
    int fd;

    if (!logcfg || !logcfg->enabled) return -1;
    if (logcfg->rotations < 1) return 0;

    /* Remove the oldest generation if it exists */
    if (build_rotated_path(logcfg->path, logcfg->rotations, old_path, sizeof(old_path)) != 0) {
        safe_log("rotate_one: oldest path too long\n");
        return -1;
    }
    unlink(old_path);

    /* Shift .N-1 -> .N down to .1 -> .2 */
    for (i = logcfg->rotations - 1; i >= 1; --i) {
        if (build_rotated_path(logcfg->path, i, old_path, sizeof(old_path)) != 0) {
            safe_log("rotate_one: old path too long\n");
            return -1;
        }
        if (build_rotated_path(logcfg->path, i + 1, new_path, sizeof(new_path)) != 0) {
            safe_log("rotate_one: new path too long\n");
            return -1;
        }
        if (file_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                safe_log2("rotate_one: rename failed: ", old_path);
                safe_log("\n");
                return -1;
            }
        }
    }

    /* Rotate active log to .1 */
    if (build_rotated_path(logcfg->path, 1, new_path, sizeof(new_path)) != 0) {
        safe_log("rotate_one: active rotated path too long\n");
        return -1;
    }

    if (file_exists(logcfg->path)) {
        if (rename(logcfg->path, new_path) != 0) {
            safe_log2("rotate_one: active rename failed: ", logcfg->path);
            safe_log("\n");
            return -1;
        }
    }

    if (truncate_after_rotate) {
        fd = open(logcfg->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) {
            safe_log2("rotate_one: recreate failed: ", logcfg->path);
            safe_log("\n");
            return -1;
        }
        close(fd);
    }

    return 0;
}

static int check_and_rotate(const log_config_t *logcfg, int truncate_after_rotate) {
    off_t size = 0;

    if (!logcfg || !logcfg->enabled) return -1;

    if (get_file_size(logcfg->path, &size) != 0) {
        /* Missing file is not fatal */
        return 0;
    }

    if (size >= logcfg->max_size) {
        return rotate_one(logcfg, truncate_after_rotate);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    int i;
    if (!cfg) return;
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->truncate_after_rotate = 1;
    cfg->foreground = 1;
    for (i = 0; i < MAX_LOGS; ++i) {
        cfg->logs[i].max_size = DEFAULT_MAX_SIZE;
        cfg->logs[i].rotations = DEFAULT_ROTATIONS;
        cfg->logs[i].enabled = 0;
    }
}

static int add_log(daemon_config_t *cfg, const char *path, off_t max_size, int rotations) {
    log_config_t *slot;
    size_t len;

    if (!cfg || !path) return -1;
    if (cfg->log_count >= MAX_LOGS) return -1;
    if (max_size <= 0 || rotations < 1) return -1;

    len = strnlen(path, MAX_PATH_LEN);
    if (len == 0 || len >= MAX_PATH_LEN) return -1;

    slot = &cfg->logs[cfg->log_count];
    memset(slot, 0, sizeof(*slot));
    memcpy(slot->path, path, len);
    slot->path[len] = '\0';
    slot->max_size = max_size;
    slot->rotations = rotations;
    slot->enabled = 1;
    cfg->log_count++;

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] [-t] [-i poll_sec] -l path:max_size:rotations [...]\n"
        "  -f    run in foreground (default)\n"
        "  -d    run as daemon\n"
        "  -t    do not recreate/truncate active log after rotation\n"
        "  -i N  polling interval in seconds\n"
        "  -l spec  add log spec, format: /path/to/log:size:rotations\n"
        "\n"
        "Example:\n"
        "  %s -f -i 2 -l /var/log/app.log:1048576:5\n",
        prog, prog);
}

static int parse_log_spec(daemon_config_t *cfg, const char *spec) {
    char buf[MAX_PATH_LEN + 64];
    char *p1, *p2;
    char *path;
    long long size_ll;
    long rotations_l;

    if (!cfg || !spec) return -1;
    if (strlen(spec) >= sizeof(buf)) return -1;

    memset(buf, 0, sizeof(buf));
    strcpy(buf, spec);

    p1 = strrchr(buf, ':');
    if (!p1) return -1;
    *p1++ = '\0';

    p2 = strrchr(buf, ':');
    if (!p2) return -1;
    *p2++ = '\0';

    path = buf;

    errno = 0;
    size_ll = atoll(p1 ? p2 : "");
    (void)size_ll;

    errno = 0;
    size_ll = atoll(p1);
    if (errno != 0 || size_ll <= 0) return -1;

    errno = 0;
    rotations_l = atol(p2);
    if (errno != 0 || rotations_l <= 0 || rotations_l > 1000) return -1;

    return add_log(cfg, path, (off_t)size_ll, (int)rotations_l);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    int opt;
    int i;
    struct sigaction sa;

    init_default_config(&cfg);

    while ((opt = getopt(argc, argv, "fdti:l:")) != -1) {
        switch (opt) {
            case 'f':
                cfg.foreground = 1;
                break;
            case 'd':
                cfg.foreground = 0;
                break;
            case 't':
                cfg.truncate_after_rotate = 0;
                break;
            case 'i':
                cfg.poll_interval_sec = (unsigned int)atoi(optarg);
                if (cfg.poll_interval_sec == 0) cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
                break;
            case 'l':
                if (parse_log_spec(&cfg, optarg) != 0) {
                    fprintf(stderr, "Invalid log spec: %s\n", optarg);
                    return 1;
                }
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_count == 0) {
        usage(argv[0]);
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!cfg.foreground) {
        if (daemonize_process() != 0) {
            fprintf(stderr, "Failed to daemonize\n");
            return 1;
        }
    }

    while (g_running) {
        for (i = 0; i < cfg.log_count; ++i) {
            (void)check_and_rotate(&cfg.logs[i], cfg.truncate_after_rotate);
        }
        sleep(cfg.poll_interval_sec);
    }

    return 0;
}
```

