# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            64
#define MAX_LINE_LEN        1024
#define MAX_PATH_LEN        PATH_MAX
#define DEFAULT_INTERVAL    5
#define DEFAULT_ROTATIONS   5
#define DEFAULT_MAX_SIZE    (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char path[MAX_PATH_LEN];
    uint64_t max_size;
    int rotate_count;
    mode_t create_mode;
    uid_t create_uid;
    gid_t create_gid;
    int have_create_owner;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    size_t count;
    unsigned interval_sec;
    int foreground;
    char config_path[MAX_PATH_LEN];
} daemon_config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *level, const char *fmt, ...) {
    char buf[512];
    va_list ap;
    int n;
    time_t now;
    struct tm tm_now;

    now = time(NULL);
    localtime_r(&now, &tm_now);

    n = strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_now);
    if (n <= 0 || (size_t)n >= sizeof(buf)) {
        return;
    }

    int off = n;
    n = snprintf(buf + off, sizeof(buf) - (size_t)off, " [%s] ", level);
    if (n < 0 || (size_t)n >= sizeof(buf) - (size_t)off) {
        return;
    }
    off += n;

    va_start(ap, fmt);
    n = vsnprintf(buf + off, sizeof(buf) - (size_t)off, fmt, ap);
    va_end(ap);

    if (n < 0) {
        return;
    }

    size_t len = strnlen(buf, sizeof(buf));
    if (len + 1 < sizeof(buf)) {
        buf[len++] = '\n';
    }

    (void)write(STDERR_FILENO, buf, len);
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < INT32_MIN || v > INT32_MAX) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static char *trim(char *s) {
    char *end;

    while (*s == ' ' || *s == '\t' || *s == '\r' || *s == '\n') {
        s++;
    }
    if (*s == '\0') {
        return s;
    }

    end = s + strlen(s) - 1;
    while (end > s && (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')) {
        *end-- = '\0';
    }
    return s;
}

static int parse_owner(const char *s, uid_t *uid, gid_t *gid) {
    /* Format: UID:GID */
    const char *colon = strchr(s, ':');
    if (!colon) {
        return -1;
    }

    char ubuf[32];
    char gbuf[32];
    size_t ulen = (size_t)(colon - s);
    size_t glen = strlen(colon + 1);

    if (ulen == 0 || glen == 0 || ulen >= sizeof(ubuf) || glen >= sizeof(gbuf)) {
        return -1;
    }

    memcpy(ubuf, s, ulen);
    ubuf[ulen] = '\0';
    memcpy(gbuf, colon + 1, glen + 1);

    int u, g;
    if (parse_int(ubuf, &u) != 0 || parse_int(gbuf, &g) != 0 || u < 0 || g < 0) {
        return -1;
    }

    *uid = (uid_t)u;
    *gid = (gid_t)g;
    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_sec = DEFAULT_INTERVAL;
    cfg->foreground = 1;
}

static int add_log_config(daemon_config_t *cfg, const log_config_t *log) {
    if (cfg->count >= MAX_LOGS) {
        return -1;
    }
    cfg->logs[cfg->count++] = *log;
    return 0;
}

static int parse_config(const char *path, daemon_config_t *cfg) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        log_msg("ERROR", "failed to open config '%s': %s", path, strerror(errno));
        return -1;
    }

    char line[MAX_LINE_LEN];
    size_t lineno = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        lineno++;
        char *s = trim(line);

        if (*s == '\0' || *s == '#') {
            continue;
        }

        if (strncmp(s, "interval=", 9) == 0) {
            int v;
            if (parse_int(s + 9, &v) != 0 || v <= 0) {
                log_msg("ERROR", "config:%zu invalid interval", lineno);
                fclose(fp);
                return -1;
            }
            cfg->interval_sec = (unsigned)v;
            continue;
        }

        if (strncmp(s, "log ", 4) == 0) {
            log_config_t lc;
            memset(&lc, 0, sizeof(lc));
            lc.max_size = DEFAULT_MAX_SIZE;
            lc.rotate_count = DEFAULT_ROTATIONS;
            lc.create_mode = 0640;

            /* Format:
             * log <path> size=<bytes> rotate=<count> mode=<octal> owner=<uid:gid>
             */
            char *saveptr = NULL;
            char *tok = strtok_r(s, " \t", &saveptr); /* log */
            (void)tok;
            tok = strtok_r(NULL, " \t", &saveptr);    /* path */
            if (!tok) {
                log_msg("ERROR", "config:%zu missing log path", lineno);
                fclose(fp);
                return -1;
            }

            if (strnlen(tok, sizeof(lc.path)) >= sizeof(lc.path)) {
                log_msg("ERROR", "config:%zu path too long", lineno);
                fclose(fp);
                return -1;
            }
            strcpy(lc.path, tok);

            while ((tok = strtok_r(NULL, " \t", &saveptr)) != NULL) {
                if (strncmp(tok, "size=", 5) == 0) {
                    if (parse_u64(tok + 5, &lc.max_size) != 0 || lc.max_size == 0) {
                        log_msg("ERROR", "config:%zu invalid size", lineno);
                        fclose(fp);
                        return -1;
                    }
                } else if (strncmp(tok, "rotate=", 7) == 0) {
                    if (parse_int(tok + 7, &lc.rotate_count) != 0 || lc.rotate_count < 1 || lc.rotate_count > 9999) {
                        log_msg("ERROR", "config:%zu invalid rotate count", lineno);
                        fclose(fp);
                        return -1;
                    }
                } else if (strncmp(tok, "mode=", 5) == 0) {
                    char *end = NULL;
                    errno = 0;
                    unsigned long m = strtoul(tok + 5, &end, 8);
                    if (errno != 0 || end == tok + 5 || *end != '\0' || m > 07777UL) {
                        log_msg("ERROR", "config:%zu invalid mode", lineno);
                        fclose(fp);
                        return -1;
                    }
                    lc.create_mode = (mode_t)m;
                } else if (strncmp(tok, "owner=", 6) == 0) {
                    if (parse_owner(tok + 6, &lc.create_uid, &lc.create_gid) != 0) {
                        log_msg("ERROR", "config:%zu invalid owner", lineno);
                        fclose(fp);
                        return -1;
                    }
                    lc.have_create_owner = 1;
                } else {
                    log_msg("ERROR", "config:%zu unknown token '%s'", lineno, tok);
                    fclose(fp);
                    return -1;
                }
            }

            if (add_log_config(cfg, &lc) != 0) {
                log_msg("ERROR", "too many log entries (max=%d)", MAX_LOGS);
                fclose(fp);
                return -1;
            }
            continue;
        }

        log_msg("ERROR", "config:%zu unknown directive", lineno);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int path_with_suffix(char *out, size_t outsz, const char *base, int suffix) {
    int n = snprintf(out, outsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= outsz) {
        return -1;
    }
    return 0;
}

static int recreate_log_file(const log_config_t *lc) {
    int fd = open(lc->path, O_WRONLY | O_CREAT | O_TRUNC, lc->create_mode);
    if (fd < 0) {
        log_msg("ERROR", "open('%s') failed: %s", lc->path, strerror(errno));
        return -1;
    }

    if (fchmod(fd, lc->create_mode) != 0) {
        log_msg("ERROR", "fchmod('%s') failed: %s", lc->path, strerror(errno));
    }

    if (lc->have_create_owner) {
        if (fchown(fd, lc->create_uid, lc->create_gid) != 0) {
            log_msg("ERROR", "fchown('%s') failed: %s", lc->path, strerror(errno));
        }
    }

    if (close(fd) != 0) {
        log_msg("ERROR", "close('%s') failed: %s", lc->path, strerror(errno));
        return -1;
    }

    return 0;
}

static int rotate_log(const log_config_t *lc) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    for (int i = lc->rotate_count; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), lc->path, i) != 0) {
            log_msg("ERROR", "path too long during rotation");
            return -1;
        }

        if (i == lc->rotate_count) {
            if (unlink(oldp) != 0 && errno != ENOENT) {
                log_msg("ERROR", "unlink('%s') failed: %s", oldp, strerror(errno));
                return -1;
            }
        } else {
            if (path_with_suffix(newp, sizeof(newp), lc->path, i + 1) != 0) {
                log_msg("ERROR", "path too long during rotation");
                return -1;
            }
            if (rename(oldp, newp) != 0 && errno != ENOENT) {
                log_msg("ERROR", "rename('%s','%s') failed: %s", oldp, newp, strerror(errno));
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), lc->path, 1) != 0) {
        log_msg("ERROR", "path too long during rotation");
        return -1;
    }

    if (rename(lc->path, newp) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_msg("ERROR", "rename('%s','%s') failed: %s", lc->path, newp, strerror(errno));
        return -1;
    }

    if (recreate_log_file(lc) != 0) {
        return -1;
    }

    log_msg("INFO", "rotated '%s' -> '%s'", lc->path, newp);
    return 0;
}

static int check_and_rotate(const log_config_t *lc) {
    struct stat st;
    if (stat(lc->path, &st) != 0) {
        if (errno != ENOENT) {
            log_msg("ERROR", "stat('%s') failed: %s", lc->path, strerror(errno));
            return -1;
        }
        return 0;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg("ERROR", "'%s' is not a regular file", lc->path);
        return -1;
    }

    if ((uint64_t)st.st_size >= lc->max_size) {
        return rotate_log(lc);
    }

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -c <config> [-f]\n"
        "  -c <config>   Path to config file\n"
        "  -f            Run in foreground\n",
        prog);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    init_default_config(&cfg);

    int opt;
    while ((opt = getopt(argc, argv, "c:f")) != -1) {
        switch (opt) {
            case 'c':
                if (strnlen(optarg, sizeof(cfg.config_path)) >= sizeof(cfg.config_path)) {
                    log_msg("ERROR", "config path too long");
                    return 1;
                }
                strcpy(cfg.config_path, optarg);
                break;
            case 'f':
                cfg.foreground = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.config_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (parse_config(cfg.config_path, &cfg) != 0) {
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize_self() != 0) {
            log_msg("ERROR", "daemonize failed: %s", strerror(errno));
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_msg("INFO", "started: logs=%zu interval=%u sec", cfg.count, cfg.interval_sec);

    while (g_running) {
        for (size_t i = 0; i < cfg.count; ++i) {
            (void)check_and_rotate(&cfg.logs[i]);
        }

        for (unsigned slept = 0; g_running && slept < cfg.interval_sec; ++slept) {
            sleep(1);
        }
    }

    log_msg("INFO", "stopped");
    return 0;
}
