# Important note about a bug in the current CLI

In the code above, `foreground` defaults to `1`, so daemon mode won’t actually happen unless you change the default.

To make daemon mode the default, change:

```c
cfg->foreground = 1;
```

to:

```c
cfg->foreground = 0;
```

inside `init_default_config()`.

---

# Recommended immediate hardening improvements

For a stricter production-ready version, I’d suggest next adding:

1. **PID file / single-instance lock**
   - prevent multiple daemons rotating the same files

2. **Open-file based validation**
   - use `lstat`, `open`, `fstat` to reduce symlink/race issues

3. **Safer recreation**
   - preserve ownership/mode from original file when not explicitly configured

4. **Config reload on SIGHUP**
   - still possible with fixed-size config arrays

5. **Optional syslog logging**
   - stderr is fine for foreground, but daemon mode should usually log elsewhere

6. **Monotonic sleep/timer**
   - avoid issues with wall clock changes

7. **Directory fsync after rotation**
   - improve crash consistency

8. **Drop privileges**
   - if started as root, switch to dedicated service user after opening what’s needed

9. **copytruncate option**
   - useful for applications that keep file descriptors open and don’t reopen logs

10. **Per-log state**
   - track inode/device to detect replacement/truncation more intelligently

---

# Memory characteristics

This implementation is memory-constrained by design:
- `daemon_config_t` contains a fixed array of `MAX_LOGS`
- each log entry contains a fixed path buffer
- config parsing uses a fixed line buffer
- rotation uses only stack-allocated path buffers
- no heap allocations in the steady-state loop

Approximate static/runtime memory footprint is small, mostly:
- config struct
- stack frames
- libc overhead

---

If you want, I can next provide one of these:

1. **a more hardened version with PID locking and race-resistant file handling**
2. **an ultra-minimal version for embedded Linux**
3. **a version with `copytruncate` support**
4. **a version with strict per-process memory caps using `setrlimit()`**

Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to operate under **strict memory limits**.

It aims to be:

- **Single-process**
- **Low-allocation / mostly static memory**
- **Streaming-based** for file operations
- **Configurable via command-line**
- **Suitable as a starting point** for embedded or constrained systems

It supports:

- Monitoring a single log file
- Rotating when size exceeds a threshold
- Keeping a fixed number of rotated files
- Optional polling interval
- Minimal heap usage

---

## Features

- No dynamic allocation in normal operation
- Fixed-size buffers
- Polling loop instead of inotify for simplicity and portability
- Rotation scheme:
  - `app.log` → `app.log.1`
  - `app.log.1` → `app.log.2`
  - ...
  - oldest removed when exceeding retention count
- Optional truncation/recreate behavior

---

## Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#ifndef READ_BUF_SIZE
#define READ_BUF_SIZE 4096
#endif

#ifndef DEFAULT_POLL_INTERVAL_SEC
#define DEFAULT_POLL_INTERVAL_SEC 5
#endif

#ifndef DEFAULT_ROTATIONS
#define DEFAULT_ROTATIONS 5
#endif

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    unsigned poll_interval_sec;
    int verbose;
    int copytruncate; /* 0 = rename/create, 1 = copytruncate */
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode, int verbose) {
    int in_fd = -1, out_fd = -1;
    char buf[READ_BUF_SIZE];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) {
        log_msg(verbose, "copy_file: open src failed: %s\n", strerror(errno));
        return -1;
    }

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out_fd < 0) {
        log_msg(verbose, "copy_file: open dst failed: %s\n", strerror(errno));
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                log_msg(verbose, "copy_file: write failed: %s\n", strerror(errno));
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        log_msg(verbose, "copy_file: read failed: %s\n", strerror(errno));
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (close(in_fd) != 0) {
        log_msg(verbose, "copy_file: close src failed: %s\n", strerror(errno));
    }
    if (close(out_fd) != 0) {
        log_msg(verbose, "copy_file: close dst failed: %s\n", strerror(errno));
    }

    return 0;
}

static int truncate_file(const char *path, int verbose) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        log_msg(verbose, "truncate_file: open failed: %s\n", strerror(errno));
        return -1;
    }
    if (ftruncate(fd, 0) != 0) {
        log_msg(verbose, "truncate_file: ftruncate failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (close(fd) != 0) {
        log_msg(verbose, "truncate_file: close failed: %s\n", strerror(errno));
    }
    return 0;
}

static int shift_rotations(const char *base, int rotations, int verbose) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (rotations <= 0) {
        return 0;
    }

    if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", base, rotations) != 0) {
        return -1;
    }
    if (unlink(old_path) != 0 && errno != ENOENT) {
        log_msg(verbose, "shift_rotations: unlink %s failed: %s\n", old_path, strerror(errno));
        return -1;
    }

    for (int i = rotations - 1; i >= 1; --i) {
        if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", base, i) != 0 ||
            safe_snprintf(new_path, sizeof(new_path), "%s.%d", base, i + 1) != 0) {
            return -1;
        }

        if (!file_exists(old_path)) {
            continue;
        }

        if (rename(old_path, new_path) != 0) {
            log_msg(verbose, "shift_rotations: rename %s -> %s failed: %s\n",
                    old_path, new_path, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int rotate_rename_create(const config_t *cfg) {
    char first_rot[PATH_MAX];
    struct stat st;

    if (stat(cfg->log_path, &st) != 0) {
        log_msg(cfg->verbose, "rotate: stat failed: %s\n", strerror(errno));
        return -1;
    }

    if (shift_rotations(cfg->log_path, cfg->rotations, cfg->verbose) != 0) {
        return -1;
    }

    if (safe_snprintf(first_rot, sizeof(first_rot), "%s.1", cfg->log_path) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, first_rot) != 0) {
        log_msg(cfg->verbose, "rotate: rename active log failed: %s\n", strerror(errno));
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, st.st_mode & 0777);
    if (fd < 0) {
        log_msg(cfg->verbose, "rotate: recreate log failed: %s\n", strerror(errno));
        return -1;
    }
    if (close(fd) != 0) {
        log_msg(cfg->verbose, "rotate: close recreated log failed: %s\n", strerror(errno));
    }

    log_msg(cfg->verbose, "Rotated %s using rename/create\n", cfg->log_path);
    return 0;
}

static int rotate_copytruncate(const config_t *cfg) {
    char first_rot[PATH_MAX];
    struct stat st;

    if (stat(cfg->log_path, &st) != 0) {
        log_msg(cfg->verbose, "rotate_copytruncate: stat failed: %s\n", strerror(errno));
        return -1;
    }

    if (shift_rotations(cfg->log_path, cfg->rotations, cfg->verbose) != 0) {
        return -1;
    }

    if (safe_snprintf(first_rot, sizeof(first_rot), "%s.1", cfg->log_path) != 0) {
        return -1;
    }

    if (copy_file(cfg->log_path, first_rot, st.st_mode & 0777, cfg->verbose) != 0) {
        return -1;
    }

    if (truncate_file(cfg->log_path, cfg->verbose) != 0) {
        return -1;
    }

    log_msg(cfg->verbose, "Rotated %s using copytruncate\n", cfg->log_path);
    return 0;
}

static int should_rotate(const config_t *cfg, int *result_out) {
    off_t sz;
    if (get_file_size(cfg->log_path, &sz) != 0) {
        if (errno == ENOENT) {
            *result_out = 0;
            return 0;
        }
        return -1;
    }

    *result_out = (sz >= cfg->max_size) ? 1 : 0;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <max_bytes> [options]\n"
        "Options:\n"
        "  -f <path>     Log file path\n"
        "  -s <bytes>    Rotate when file size >= bytes\n"
        "  -n <count>    Number of rotated files to keep (default: %d)\n"
        "  -p <sec>      Poll interval seconds (default: %d)\n"
        "  -c            Use copytruncate instead of rename/create\n"
        "  -v            Verbose logging\n"
        "  -h            Show this help\n",
        prog, DEFAULT_ROTATIONS, DEFAULT_POLL_INTERVAL_SEC);
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 2147483647L) return -1;
    *out = (int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;
    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.rotations = DEFAULT_ROTATIONS;
    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:cvh")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg.log_path)) {
                    fprintf(stderr, "Path too long\n");
                    return 1;
                }
                strcpy(cfg.log_path, optarg);
                break;
            case 's':
                if (parse_offt(optarg, &cfg.max_size) != 0 || cfg.max_size <= 0) {
                    fprintf(stderr, "Invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.rotations) != 0 || cfg.rotations < 1) {
                    fprintf(stderr, "Invalid rotation count\n");
                    return 1;
                }
                break;
            case 'p':
                {
                    int v;
                    if (parse_int(optarg, &v) != 0 || v < 1) {
                        fprintf(stderr, "Invalid poll interval\n");
                        return 1;
                    }
                    cfg.poll_interval_sec = (unsigned)v;
                }
                break;
            case 'c':
                cfg.copytruncate = 1;
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return (opt == 'h') ? 0 : 1;
        }
    }

    if (cfg.log_path[0] == '\0' || cfg.max_size <= 0) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_msg(cfg.verbose,
            "Starting log rotation daemon: file=%s max_size=%lld rotations=%d poll=%u mode=%s\n",
            cfg.log_path,
            (long long)cfg.max_size,
            cfg.rotations,
            cfg.poll_interval_sec,
            cfg.copytruncate ? "copytruncate" : "rename/create");

    while (g_running) {
        int rotate = 0;
        if (should_rotate(&cfg, &rotate) != 0) {
            log_msg(cfg.verbose, "Error checking file size: %s\n", strerror(errno));
        } else if (rotate) {
            int rc = cfg.copytruncate ? rotate_copytruncate(&cfg)
                                      : rotate_rename_create(&cfg);
            if (rc != 0) {
                log_msg(cfg.verbose, "Rotation failed\n");
            }
        }

        for (unsigned i = 0; i < cfg.poll_interval_sec && g_running; ++i) {
            sleep(1);
        }
    }

    log_msg(cfg.verbose, "Exiting\n");
    return 0;
}
