#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define COPY_BUF_SIZE 4096

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_force_rotate = 0;

static void on_term(int sig) {
    (void)sig;
    g_running = 0;
}

static void on_hup(int sig) {
    (void)sig;
    g_force_rotate = 1;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *a, int n) {
    int rc = snprintf(dst, dstsz, fmt, a, n);
    if (rc < 0 || (size_t)rc >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in_fd = -1, out_fd = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (fsync(out_fd) < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}

static int rotate_log(const char *path, int keep) {
    struct stat st;
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep < 1) {
        errno = EINVAL;
        return -1;
    }

    if (stat(path, &st) < 0) {
        return -1;
    }

    /* Shift: logfile.(keep-1) -> logfile.keep, ... logfile.1 -> logfile.2 */
    for (int i = keep - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", path, i) < 0) return -1;
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", path, i + 1) < 0) return -1;
        (void)rename(oldp, newp);
    }

    /* Current logfile -> logfile.1 */
    if (safe_snprintf(newp, sizeof(newp), "%s.1", path, 1) < 0) return -1;

    /*
     * Prefer rename for O(1) memory and speed.
     * If rename fails across filesystems, fall back to copy+truncate.
     */
    if (rename(path, newp) < 0) {
        if (errno != EXDEV) {
            return -1;
        }
        if (copy_file(path, newp, st.st_mode & 0777) < 0) {
            return -1;
        }
        if (truncate(path, 0) < 0) {
            return -1;
        }
        return 0;
    }

    /* Recreate active log file with same permissions */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, st.st_mode & 0777);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int should_rotate(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return 0;
    }
    return st.st_size >= max_size;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> <max-bytes> <keep-count> <interval-seconds>\n"
        "Example: %s /var/log/myapp.log 1048576 5 2\n",
        prog, prog);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_bytes;
    int keep;
    int interval;
    struct sigaction sa;

    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];
    max_bytes = (off_t)atoll(argv[2]);
    keep = atoi(argv[3]);
    interval = atoi(argv[4]);

    if (max_bytes <= 0 || keep <= 0 || interval <= 0) {
        usage(argv[0]);
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_term;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_hup;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGHUP, &sa, NULL);

    while (g_running) {
        if (g_force_rotate || should_rotate(logfile, max_bytes)) {
            g_force_rotate = 0;
            if (rotate_log(logfile, keep) < 0) {
                /* Minimal error reporting, no extra memory use */
                fprintf(stderr, "rotate failed for %s: %s\n", logfile, strerror(errno));
            }
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
