```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (1024 * 1024) /* 1 MiB */
#define DEFAULT_ROTATIONS 5
#define DEFAULT_INTERVAL_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations < 1) return 0;

    /* Remove oldest */
    if (build_rotated_path(oldp, sizeof(oldp), path, rotations) < 0) {
        perror("build_rotated_path");
        return -1;
    }
    unlink(oldp);

    /* Shift: .(n-1) -> .n */
    for (int i = rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i) < 0) {
            perror("build_rotated_path");
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), path, i + 1) < 0) {
            perror("build_rotated_path");
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                perror("rename");
                return -1;
            }
        }
    }

    /* Current -> .1 */
    if (build_rotated_path(newp, sizeof(newp), path, 1) < 0) {
        perror("build_rotated_path");
        return -1;
    }

    if (rename(path, newp) < 0) {
        if (errno != ENOENT) {
            perror("rename current");
            return -1;
        }
    }

    /* Recreate empty current log */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open new log");
        return -1;
    }
    close(fd);

    return 0;
}

static int ensure_log_exists(const char *path, dev_t *dev_out, ino_t *ino_out) {
    struct stat st;

    if (stat(path, &st) == 0) {
        if (!S_ISREG(st.st_mode)) {
            fprintf(stderr, "Not a regular file: %s\n", path);
            return -1;
        }
        *dev_out = st.st_dev;
        *ino_out = st.st_ino;
        return 0;
    }

    if (errno != ENOENT) {
        perror("stat");
        return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("create log");
        return -1;
    }
    close(fd);

    if (stat(path, &st) < 0) {
        perror("stat after create");
        return -1;
    }

    *dev_out = st.st_dev;
    *ino_out = st.st_ino;
    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, int rotations,
                            dev_t *last_dev, ino_t *last_ino) {
    struct stat st;

    if (stat(path, &st) < 0) {
        if (errno == ENOENT) {
            if (ensure_log_exists(path, last_dev, last_ino) < 0) return -1;
            return 0;
        }
        perror("stat");
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Not a regular file: %s\n", path);
        return -1;
    }

    /* Detect replacement/truncation by external tool */
    if (st.st_dev != *last_dev || st.st_ino != *last_ino) {
        *last_dev = st.st_dev;
        *last_ino = st.st_ino;
    }

    if (st.st_size >= max_size) {
        if (rotate_logs(path, rotations) < 0) return -1;
        if (ensure_log_exists(path, last_dev, last_ino) < 0) return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> [max_size_bytes] [rotations] [interval_sec]\n"
        "Defaults: max_size=%d rotations=%d interval=%d\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_INTERVAL_SEC);
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval_sec = DEFAULT_INTERVAL_SEC;
    dev_t last_dev = 0;
    ino_t last_ino = 0;

    if (argc < 2 || argc > 5) {
        usage(argv[0]);
        return 1;
    }

    log_path = argv[1];

    if (argc >= 3) {
        max_size = (off_t)atoll(argv[2]);
        if (max_size <= 0) {
            fprintf(stderr, "Invalid max_size\n");
            return 1;
        }
    }

    if (argc >= 4) {
        rotations = atoi(argv[3]);
        if (rotations < 1 || rotations > 9999) {
            fprintf(stderr, "Invalid rotations\n");
            return 1;
        }
    }

    if (argc >= 5) {
        interval_sec = atoi(argv[4]);
        if (interval_sec < 1) {
            fprintf(stderr, "Invalid interval_sec\n");
            return 1;
        }
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (ensure_log_exists(log_path, &last_dev, &last_ino) < 0) {
        return 1;
    }

    while (!g_stop) {
        if (check_and_rotate(log_path, max_size, rotations, &last_dev, &last_ino) < 0) {
            /* In a tiny daemon, just log and continue after sleep */
        }
        sleep((unsigned int)interval_sec);
    }

    return 0;
}
