#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <signal.h>
#include <limits.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (1024 * 1024) /* 1 MiB */
#define DEFAULT_ROTATIONS 5
#define DEFAULT_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size_exceeds(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return 0;
    }
    return st.st_size >= max_size;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    if (rotations < 1) return 0;

    if (build_rotated_path(oldp, sizeof(oldp), path, rotations) != 0) {
        return -1;
    }
    unlink(oldp);

    for (i = rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i) != 0) {
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), path, i + 1) != 0) {
            return -1;
        }
        rename(oldp, newp);
    }

    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }

    if (rename(path, newp) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec]\n"
        "  -d             Run as daemon\n"
        "  -f <logfile>   Log file to rotate\n"
        "  -s <bytes>     Max size before rotation (default: %d)\n"
        "  -n <count>     Number of rotated files to keep (default: %d)\n"
        "  -i <seconds>   Poll interval (default: %d)\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_INTERVAL);
}

int main(int argc, char **argv) {
    const char *logfile = NULL;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_INTERVAL;
    int do_daemon = 0;
    int opt;

    while ((opt = getopt(argc, argv, "df:s:n:i:")) != -1) {
        switch (opt) {
            case 'd':
                do_daemon = 1;
                break;
            case 'f':
                logfile = optarg;
                break;
            case 's':
                max_size = (off_t)atoll(optarg);
                break;
            case 'n':
                rotations = atoi(optarg);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!logfile || max_size <= 0 || rotations < 1 || interval < 1) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (do_daemon) {
        if (daemonize() != 0) {
            return 1;
        }
    }

    while (g_running) {
        if (file_size_exceeds(logfile, max_size)) {
            rotate_logs(logfile, rotations);
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
