```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MAX_PATH 256
#define MAX_ROTATIONS 9

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > 2) close(fd);
    }

    return 0;
}

static int build_rotated_path(char *dst, size_t dstsz, const char *base, int index) {
    int n = snprintf(dst, dstsz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    if (rotations < 1 || rotations > MAX_ROTATIONS) return -1;

    char oldp[MAX_PATH];
    char newp[MAX_PATH];

    for (int i = rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (build_rotated_path(newp, sizeof(newp), path, i + 1) < 0) return -1;

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (build_rotated_path(newp, sizeof(newp), path, 1) < 0) return -1;

    if (rename(path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, int rotations) {
    struct stat st;
    if (stat(path, &st) < 0) {
        if (errno == ENOENT) {
            int fd = open(path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (st.st_size >= max_size) {
        return rotate_logs(path, rotations);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s [-n] <log_path> <max_size_bytes> <rotations> <interval_sec>\n", prog);
    fprintf(stderr, "  -n : do not daemonize\n");
}

int main(int argc, char **argv) {
    int nodaemon = 0;
    int argi = 1;

    if (argc > 1 && strcmp(argv[1], "-n") == 0) {
        nodaemon = 1;
        argi++;
    }

    if (argc - argi != 4) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[argi++];
    long long max_size = atoll(argv[argi++]);
    int rotations = atoi(argv[argi++]);
    int interval = atoi(argv[argi++]);

    if (strlen(log_path) >= MAX_PATH) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    if (max_size <= 0 || rotations < 1 || rotations > MAX_ROTATIONS || interval <= 0) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!nodaemon) {
        if (daemonize() < 0) {
            return 1;
        }
    }

    while (g_running) {
        (void)check_and_rotate(log_path, (off_t)max_size, rotations);
        sleep((unsigned int)interval);
    }

    return 0;
}
