## File: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define MAX_LOGS        16
#define MAX_PATH_LEN    256
#define MAX_LINE_LEN    384
#define COPY_BUF_SIZE   4096
#define DEFAULT_SLEEP   5

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int keep;
    int copytruncate; /* 0=rename/create, 1=copy/truncate */
} log_cfg_t;

static log_cfg_t g_logs[MAX_LOGS];
static int g_log_count = 0;
static unsigned g_sleep_secs = DEFAULT_SLEEP;

static void trim_newline(char *s) {
    size_t n = strlen(s);
    while (n > 0 && (s[n - 1] == '\n' || s[n - 1] == '\r')) {
        s[n - 1] = '\0';
        n--;
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    uint64_t v = 0;
    if (!s || !*s) return -1;
    for (; *s; s++) {
        if (*s < '0' || *s > '9') return -1;
        v = v * 10 + (uint64_t)(*s - '0');
    }
    *out = v;
    return 0;
}

static int parse_config(const char *cfg_path) {
    FILE *f = fopen(cfg_path, "r");
    char line[MAX_LINE_LEN];

    if (!f) {
        perror("fopen config");
        return -1;
    }

    while (fgets(line, sizeof(line), f)) {
        char path[MAX_PATH_LEN];
        char mode[32];
        uint64_t size_u64;
        uint64_t keep_u64;
        int n;

        trim_newline(line);
        if (line[0] == '\0' || line[0] == '#')
            continue;

        if (strncmp(line, "sleep ", 6) == 0) {
            if (parse_u64(line + 6, &size_u64) == 0 && size_u64 > 0 && size_u64 < 86400) {
                g_sleep_secs = (unsigned)size_u64;
            }
            continue;
        }

        if (g_log_count >= MAX_LOGS) {
            fprintf(stderr, "too many log entries, max=%d\n", MAX_LOGS);
            break;
        }

        path[0] = '\0';
        mode[0] = '\0';
        size_u64 = 0;
        keep_u64 = 0;

        n = sscanf(line, "%255s %llu %llu %31s",
                   path,
                   (unsigned long long *)&size_u64,
                   (unsigned long long *)&keep_u64,
                   mode);
        if (n < 3) {
            fprintf(stderr, "invalid config line: %s\n", line);
            continue;
        }

        strncpy(g_logs[g_log_count].path, path, MAX_PATH_LEN - 1);
        g_logs[g_log_count].path[MAX_PATH_LEN - 1] = '\0';
        g_logs[g_log_count].max_size = (off_t)size_u64;
        g_logs[g_log_count].keep = (int)keep_u64;
        g_logs[g_log_count].copytruncate = (n >= 4 && strcmp(mode, "copytruncate") == 0) ? 1 : 0;
        g_log_count++;
    }

    fclose(f);
    return 0;
}

static int make_backup_name(char *out, size_t out_sz, const char *base, int idx) {
    int rc = snprintf(out, out_sz, "%s.%d", base, idx);
    if (rc < 0 || (size_t)rc >= out_sz) return -1;
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in_fd = -1, out_fd = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (close(in_fd) < 0) {
        close(out_fd);
        return -1;
    }
    if (close(out_fd) < 0) {
        return -1;
    }
    return 0;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (ftruncate(fd, 0) < 0) {
        close(fd);
        return -1;
    }
    return close(fd);
}

static int create_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) return -1;
    return close(fd);
}

static int rotate_one(const log_cfg_t *cfg) {
    struct stat st;
    char oldn[MAX_PATH_LEN + 16];
    char newn[MAX_PATH_LEN + 16];
    int i;

    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) return 0;
        perror("stat");
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "not a regular file: %s\n", cfg->path);
        return -1;
    }

    if (st.st_size < cfg->max_size) {
        return 0;
    }

    if (cfg->keep < 1) {
        if (truncate_file(cfg->path) < 0) {
            perror("truncate");
            return -1;
        }
        return 1;
    }

    if (make_backup_name(oldn, sizeof(oldn), cfg->path, cfg->keep) == 0) {
        unlink(oldn);
    }

    for (i = cfg->keep - 1; i >= 1; i--) {
        if (make_backup_name(oldn, sizeof(oldn), cfg->path, i) < 0 ||
            make_backup_name(newn, sizeof(newn), cfg->path, i + 1) < 0) {
            fprintf(stderr, "path too long during rotation: %s\n", cfg->path);
            return -1;
        }
        rename(oldn, newn);
    }

    if (make_backup_name(newn, sizeof(newn), cfg->path, 1) < 0) {
        fprintf(stderr, "path too long during rotation: %s\n", cfg->path);
        return -1;
    }

    if (cfg->copytruncate) {
        if (copy_file(cfg->path, newn, st.st_mode & 0777) < 0) {
            perror("copy_file");
            return -1;
        }
        if (truncate_file(cfg->path) < 0) {
            perror("truncate_file");
            return -1;
        }
    } else {
        if (rename(cfg->path, newn) < 0) {
            perror("rename current");
            return -1;
        }
        if (create_empty_file(cfg->path, st.st_mode & 0777) < 0) {
            perror("create new log");
            return -1;
        }
    }

    return 1;
}

static void daemon_loop(void) {
    for (;;) {
        int i;
        for (i = 0; i < g_log_count; i++) {
            rotate_one(&g_logs[i]);
        }
        sleep(g_sleep_secs);
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <config>\n", argv[0]);
        return 1;
    }

    if (parse_config(argv[1]) < 0) {
        return 1;
    }

    if (g_log_count == 0) {
        fprintf(stderr, "no logs configured\n");
        return 1;
    }

    daemon_loop();
    return 0;
}
