## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>

#define MAX_PATH 256
#define MAX_ROTATIONS 9

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldname[MAX_PATH];
    char newname[MAX_PATH];
    int i;

    if (rotations < 1 || rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    for (i = rotations - 1; i >= 1; --i) {
        int n1 = snprintf(oldname, sizeof(oldname), "%s.%d", path, i);
        int n2 = snprintf(newname, sizeof(newname), "%s.%d", path, i + 1);

        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(oldname) || n2 >= (int)sizeof(newname)) {
            errno = ENAMETOOLONG;
            return -1;
        }

        (void)unlink(newname);
        if (rename(oldname, newname) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    int n = snprintf(newname, sizeof(newname), "%s.1", path);
    if (n < 0 || n >= (int)sizeof(newname)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    (void)unlink(newname);
    if (rename(path, newname) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int ensure_file_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, int rotations) {
    struct stat st;

    if (stat(path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_file_exists(path);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= max_size) {
        return rotate_logs(path, rotations);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] <logfile> <max_size_bytes> <rotations> <interval_sec>\n"
        "  -f   run in foreground\n"
        "Example:\n"
        "  %s -f /tmp/app.log 1048576 5 2\n",
        prog, prog);
}

int main(int argc, char **argv) {
    int foreground = 0;
    const char *logfile;
    off_t max_size;
    int rotations;
    int interval;
    char *end;

    if (argc >= 2 && strcmp(argv[1], "-f") == 0) {
        foreground = 1;
        argv++;
        argc--;
    }

    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];

    errno = 0;
    max_size = strtoll(argv[2], &end, 10);
    if (errno || *end != '\0' || max_size <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    errno = 0;
    rotations = (int)strtol(argv[3], &end, 10);
    if (errno || *end != '\0' || rotations < 1 || rotations > MAX_ROTATIONS) {
        fprintf(stderr, "Invalid rotations (1-%d)\n", MAX_ROTATIONS);
        return 1;
    }

    errno = 0;
    interval = (int)strtol(argv[4], &end, 10);
    if (errno || *end != '\0' || interval <= 0) {
        fprintf(stderr, "Invalid interval_sec\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!foreground) {
        if (daemonize() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (ensure_file_exists(logfile) < 0) {
        perror("ensure_file_exists");
        return 1;
    }

    while (g_running) {
        if (check_and_rotate(logfile, max_size, rotations) < 0) {
            /* Minimal daemon: ignore transient errors and continue */
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
