## File: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>

#define MAX_LOGS 16
#define MAX_PATH 256
#define MAX_LINE 512

typedef struct {
    char path[MAX_PATH];
    off_t max_size;
    int keep;
    int copytruncate;
} log_cfg_t;

static log_cfg_t g_logs[MAX_LOGS];
static int g_log_count = 0;
static volatile sig_atomic_t g_running = 1;
static unsigned g_interval = 5;
static int g_foreground = 0;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void trim_newline(char *s) {
    size_t n = strlen(s);
    while (n > 0 && (s[n - 1] == '\n' || s[n - 1] == '\r')) {
        s[n - 1] = '\0';
        n--;
    }
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (end == s) return -1;

    unsigned long long mult = 1;
    if (*end == 'K' || *end == 'k') mult = 1024ULL;
    else if (*end == 'M' || *end == 'm') mult = 1024ULL * 1024ULL;
    else if (*end == 'G' || *end == 'g') mult = 1024ULL * 1024ULL * 1024ULL;
    else if (*end != '\0') return -1;

    *out = (off_t)(v * mult);
    return 0;
}

static int parse_config(const char *cfg_path) {
    FILE *f = fopen(cfg_path, "r");
    if (!f) {
        perror("fopen config");
        return -1;
    }

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), f)) {
        trim_newline(line);

        if (line[0] == '\0' || line[0] == '#')
            continue;

        if (strncmp(line, "interval=", 9) == 0) {
            unsigned long v = strtoul(line + 9, NULL, 10);
            if (v > 0) g_interval = (unsigned)v;
            continue;
        }

        if (strncmp(line, "log ", 4) == 0) {
            if (g_log_count >= MAX_LOGS) {
                fprintf(stderr, "too many log entries\n");
                fclose(f);
                return -1;
            }

            char path[MAX_PATH];
            char size_s[32];
            int keep = 0;
            int copytruncate = 0;

            int n = sscanf(line + 4, "%255s %31s %d %d",
                           path, size_s, &keep, &copytruncate);
            if (n != 4) {
                fprintf(stderr, "bad config line: %s\n", line);
                fclose(f);
                return -1;
            }

            off_t max_size;
            if (parse_size(size_s, &max_size) != 0) {
                fprintf(stderr, "bad size in line: %s\n", line);
                fclose(f);
                return -1;
            }

            strncpy(g_logs[g_log_count].path, path, MAX_PATH - 1);
            g_logs[g_log_count].path[MAX_PATH - 1] = '\0';
            g_logs[g_log_count].max_size = max_size;
            g_logs[g_log_count].keep = keep;
            g_logs[g_log_count].copytruncate = copytruncate ? 1 : 0;
            g_log_count++;
        }
    }

    fclose(f);
    return 0;
}

static int copy_file_then_truncate(const char *src, const char *dst) {
    int in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    struct stat st;
    if (fstat(in_fd, &st) != 0) {
        close(in_fd);
        return -1;
    }

    int out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, st.st_mode & 0777);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    char buf[1024];
    ssize_t r;
    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (fsync(out_fd) != 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(out_fd);

    int wr_fd = open(src, O_WRONLY);
    if (wr_fd < 0) {
        close(in_fd);
        return -1;
    }

    if (ftruncate(wr_fd, 0) != 0) {
        close(wr_fd);
        close(in_fd);
        return -1;
    }

    close(wr_fd);
    close(in_fd);
    return 0;
}

static int rotate_one(const log_cfg_t *cfg) {
    char oldp[MAX_PATH];
    char newp[MAX_PATH];

    if (cfg->keep < 1) return 0;

    for (int i = cfg->keep; i >= 1; --i) {
        if (snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) >= (int)sizeof(oldp))
            return -1;

        if (i == cfg->keep) {
            unlink(oldp);
        } else {
            if (snprintf(newp, sizeof(newp), "%s.%d", cfg->path, i + 1) >= (int)sizeof(newp))
                return -1;
            rename(oldp, newp);
        }
    }

    if (snprintf(newp, sizeof(newp), "%s.1", cfg->path) >= (int)sizeof(newp))
        return -1;

    if (cfg->copytruncate) {
        if (copy_file_then_truncate(cfg->path, newp) != 0) {
            perror("copytruncate");
            return -1;
        }
    } else {
        if (rename(cfg->path, newp) != 0) {
            perror("rename");
            return -1;
        }

        int fd = open(cfg->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) {
            perror("create new log");
            return -1;
        }
        close(fd);
    }

    return 0;
}

static void check_logs(void) {
    for (int i = 0; i < g_log_count; ++i) {
        struct stat st;
        if (stat(g_logs[i].path, &st) != 0) {
            continue;
        }

        if (!S_ISREG(st.st_mode)) {
            continue;
        }

        if (st.st_size >= g_logs[i].max_size) {
            rotate_one(&g_logs[i]);
        }
    }
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "usage: %s [-f] <config>\n", prog);
    fprintf(stderr, "  -f   foreground\n");
}

int main(int argc, char **argv) {
    const char *cfg_path = NULL;

    int opt;
    while ((opt = getopt(argc, argv, "f")) != -1) {
        switch (opt) {
            case 'f':
                g_foreground = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return 1;
    }

    cfg_path = argv[optind];

    if (parse_config(cfg_path) != 0) {
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (!g_foreground) {
        if (daemonize_self() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        check_logs();
        sleep(g_interval);
    }

    return 0;
}
```

