## `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MAX_PATH_LEN 256
#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (1024 * 1024) /* 1 MiB */

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size_exceeds(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return 0;
    }
    return st.st_size >= max_size;
}

static int rotate_logs(const char *path, int max_rotations) {
    char oldname[MAX_PATH_LEN];
    char newname[MAX_PATH_LEN];
    int i;

    if (max_rotations < 1) return -1;

    /* Remove oldest */
    snprintf(oldname, sizeof(oldname), "%s.%d", path, max_rotations);
    unlink(oldname);

    /* Shift N-1 down to N */
    for (i = max_rotations - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", path, i);
        snprintf(newname, sizeof(newname), "%s.%d", path, i + 1);
        rename(oldname, newname);
    }

    /* Rotate current log to .1 */
    snprintf(newname, sizeof(newname), "%s.1", path);
    if (rename(path, newname) < 0) {
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] -f <logfile> [-s max_size_bytes] [-n rotations] [-i interval_sec]\n"
        "  -d                 Run as daemon\n"
        "  -f <logfile>       Log file to monitor\n"
        "  -s <bytes>         Rotate when size >= bytes (default: %d)\n"
        "  -n <count>         Number of rotated files to keep (default: %d)\n"
        "  -i <seconds>       Poll interval (default: %d)\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_MAX_ROTATIONS, DEFAULT_CHECK_INTERVAL);
}

int main(int argc, char *argv[]) {
    char logfile[MAX_PATH_LEN] = {0};
    off_t max_size = DEFAULT_MAX_SIZE;
    int max_rotations = DEFAULT_MAX_ROTATIONS;
    int interval = DEFAULT_CHECK_INTERVAL;
    int run_as_daemon = 0;
    int opt;

    while ((opt = getopt(argc, argv, "df:s:n:i:")) != -1) {
        switch (opt) {
            case 'd':
                run_as_daemon = 1;
                break;
            case 'f':
                strncpy(logfile, optarg, sizeof(logfile) - 1);
                logfile[sizeof(logfile) - 1] = '\0';
                break;
            case 's':
                max_size = (off_t)atoll(optarg);
                break;
            case 'n':
                max_rotations = atoi(optarg);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (logfile[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (max_size <= 0 || max_rotations <= 0 || interval <= 0) {
        fprintf(stderr, "Invalid numeric argument\n");
        return 1;
    }

    if (install_signals() < 0) {
        perror("sigaction");
        return 1;
    }

    if (run_as_daemon) {
        if (daemonize() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        if (file_size_exceeds(logfile, max_size)) {
            rotate_logs(logfile, max_rotations);
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
