```c
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdlib.h>

#define LOG_PATH        "/tmp/myapp.log"
#define MAX_SIZE        (1024 * 1024)   /* 1 MiB */
#define MAX_ROTATIONS   3
#define POLL_INTERVAL   5               /* seconds */
#define PATH_BUF        256

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    return st.st_size;
}

static int touch_empty_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const char *base) {
    char oldp[PATH_BUF];
    char newp[PATH_BUF];
    int i;

    /* Remove oldest if it exists */
    snprintf(oldp, sizeof(oldp), "%s.%d", base, MAX_ROTATIONS);
    unlink(oldp);

    /* Shift: log.2 -> log.3, log.1 -> log.2, ... */
    for (i = MAX_ROTATIONS - 1; i >= 1; --i) {
        snprintf(oldp, sizeof(oldp), "%s.%d", base, i);
        snprintf(newp, sizeof(newp), "%s.%d", base, i + 1);
        if (file_exists(oldp)) {
            if (rename(oldp, newp) != 0) {
                return -1;
            }
        }
    }

    /* Rotate current log -> log.1 */
    snprintf(newp, sizeof(newp), "%s.1", base);
    if (file_exists(base)) {
        if (rename(base, newp) != 0) {
            return -1;
        }
    }

    /* Recreate empty current log */
    if (touch_empty_file(base) != 0) {
        return -1;
    }

    return 0;
}

static void daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        _exit(1);
    }

    pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Ensure log file exists */
    if (!file_exists(LOG_PATH)) {
        if (touch_empty_file(LOG_PATH) != 0) {
            return 1;
        }
    }

    daemonize();

    while (g_running) {
        off_t sz = file_size(LOG_PATH);
        if (sz >= 0 && sz >= MAX_SIZE) {
            rotate_logs(LOG_PATH);
        }
        sleep(POLL_INTERVAL);
    }

    return 0;
}
```

