#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <time.h>

#define MAX_PATH 256
#define ERRBUF   256

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[MAX_PATH];
    size_t max_size;
    int max_files;
    unsigned poll_interval_sec;
    rlim_t mem_limit_bytes;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
#ifdef RLIMIT_DATA
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    setrlimit(RLIMIT_DATA, &rl);
#endif
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > 2) close(fd);

    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, const char *a, int n) {
    int rc = snprintf(dst, dstsz, fmt, a, n);
    if (rc < 0 || (size_t)rc >= dstsz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[MAX_PATH];
    char newp[MAX_PATH];
    int i;

    if (cfg->max_files < 1) return 0;

    /* Remove oldest */
    if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, cfg->max_files) != 0)
        return -1;
    unlink(oldp);

    /* Shift N-1 down to 1 */
    for (i = cfg->max_files - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, i) != 0)
            return -1;
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->log_path, i + 1) != 0)
            return -1;

        if (file_exists(oldp)) {
            if (rename(oldp, newp) != 0) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    if (safe_snprintf(newp, sizeof(newp), "%s.1", cfg->log_path, 1) != 0)
        return -1;

    if (file_exists(cfg->log_path)) {
        if (rename(cfg->log_path, newp) != 0) {
            return -1;
        }
    }

    /* Recreate empty log file */
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void sleep_interval(unsigned sec) {
    struct timespec req, rem;
    req.tv_sec = sec;
    req.tv_nsec = 0;
    while (nanosleep(&req, &rem) != 0 && errno == EINTR && g_running) {
        req = rem;
    }
}

static int run_daemon(const struct config *cfg) {
    while (g_running) {
        off_t sz = file_size(cfg->log_path);
        if (sz >= 0 && (size_t)sz >= cfg->max_size) {
            if (rotate_logs(cfg) != 0) {
                /* Silent failure in minimal daemon */
            }
        }
        sleep_interval(cfg->poll_interval_sec);
    }
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    struct sigaction sa;

    if (argc != 6) {
        fprintf(stderr,
            "usage: %s <log_path> <max_size_bytes> <max_files> <poll_sec> <mem_limit_bytes>\n",
            argv[0]);
        return 1;
    }

    memset(&cfg, 0, sizeof(cfg));
    strncpy(cfg.log_path, argv[1], sizeof(cfg.log_path) - 1);
    cfg.max_size = (size_t)strtoull(argv[2], NULL, 10);
    cfg.max_files = atoi(argv[3]);
    cfg.poll_interval_sec = (unsigned)strtoul(argv[4], NULL, 10);
    cfg.mem_limit_bytes = (rlim_t)strtoull(argv[5], NULL, 10);

    if (cfg.log_path[0] == '\0' || cfg.max_size == 0 || cfg.max_files < 1 || cfg.poll_interval_sec == 0) {
        fprintf(stderr, "invalid arguments\n");
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    if (set_memory_limit(cfg.mem_limit_bytes) != 0) {
        fprintf(stderr, "failed to set memory limit: %s\n", strerror(errno));
        return 1;
    }

    if (daemonize() != 0) {
        fprintf(stderr, "failed to daemonize: %s\n", strerror(errno));
        return 1;
    }

    return run_daemon(&cfg);
}
