## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (10 * 1024 * 1024) /* 10 MB */
#define DEFAULT_ROTATIONS 5
#define DEFAULT_INTERVAL 5                  /* seconds */

/* Strict memory limits */
#define MEM_LIMIT_AS   (8 * 1024 * 1024)    /* 8 MB virtual memory */
#define MEM_LIMIT_DATA (2 * 1024 * 1024)    /* 2 MB data segment */
#define MEM_LIMIT_STACK (512 * 1024)        /* 512 KB stack */

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_memory_limits(void) {
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = MEM_LIMIT_AS;
    if (setrlimit(RLIMIT_AS, &rl) != 0) return -1;

    rl.rlim_cur = rl.rlim_max = MEM_LIMIT_DATA;
    if (setrlimit(RLIMIT_DATA, &rl) != 0) return -1;

    rl.rlim_cur = rl.rlim_max = MEM_LIMIT_STACK;
    if (setrlimit(RLIMIT_STACK, &rl) != 0) return -1;

    return 0;
}

static int write_stderr(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n < 0) return -1;
    if ((size_t)n > sizeof(buf)) n = (int)sizeof(buf);
    return (int)write(STDERR_FILENO, buf, (size_t)n);
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_name(char *out, size_t out_sz, const char *base, int idx) {
    int n = snprintf(out, out_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations < 1) return 0;

    if (build_rotated_name(oldp, sizeof(oldp), path, rotations) != 0)
        return -1;
    unlink(oldp);

    for (int i = rotations - 1; i >= 1; --i) {
        if (build_rotated_name(oldp, sizeof(oldp), path, i) != 0)
            return -1;
        if (build_rotated_name(newp, sizeof(newp), path, i + 1) != 0)
            return -1;

        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT)
                return -1;
        }
    }

    if (build_rotated_name(newp, sizeof(newp), path, 1) != 0)
        return -1;

    if (rename(path, newp) != 0) {
        if (errno != ENOENT)
            return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s <logfile> [max_size_bytes] [rotations] [interval_sec] [--no-daemon]\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_INTERVAL;
    bool no_daemon = false;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];

    if (argc >= 3) max_size = (off_t)atoll(argv[2]);
    if (argc >= 4) rotations = atoi(argv[3]);
    if (argc >= 5) interval = atoi(argv[4]);
    if (argc >= 6 && strcmp(argv[5], "--no-daemon") == 0) no_daemon = true;

    if (max_size <= 0 || rotations < 1 || interval < 1) {
        usage(argv[0]);
        return 1;
    }

    if (set_memory_limits() != 0) {
        write_stderr("failed to set memory limits: %s\n", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!no_daemon) {
        if (daemonize() != 0) {
            write_stderr("failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0) {
            if (sz >= max_size) {
                if (rotate_logs(logfile, rotations) != 0) {
                    /* best effort: continue running */
                }
            }
        } else {
            /* If file doesn't exist, create it */
            if (errno == ENOENT) {
                int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
                if (fd >= 0) close(fd);
            }
        }

        sleep((unsigned int)interval);
    }

    return 0;
}
