#include <sys/stat.h>
#include <sys/types.h>

#define PATH_MAX_LEN 256
#define READ_BUF_SZ  256

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX_LEN];
    size_t rotate_size;
    int keep_count;
    unsigned sleep_secs;
    int daemonize;
};

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int do_daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > 2) close(fd);

    return 0;
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *sz = st.st_size;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int idx) {
    int n = snprintf(out, out_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX_LEN];
    char newp[PATH_MAX_LEN];

    if (cfg->keep_count <= 0) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) return -1;
        return 0;
    }

    if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, cfg->keep_count) < 0)
        return -1;
    unlink(oldp);

    for (int i = cfg->keep_count - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, i) < 0)
            return -1;
        if (build_rotated_path(newp, sizeof(newp), cfg->log_path, i + 1) < 0)
            return -1;
        if (rename(oldp, newp) < 0 && errno != ENOENT)
            return -1;
    }

    if (build_rotated_path(newp, sizeof(newp), cfg->log_path, 1) < 0)
        return -1;

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    if (!cfg) return -1;

    memset(cfg, 0, sizeof(*cfg));
    cfg->rotate_size = 1024 * 1024;
    cfg->keep_count = 3;
    cfg->sleep_secs = 5;
    cfg->daemonize = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:k:t:d")) != -1) {
        switch (opt) {
            case 'f':
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's':
                cfg->rotate_size = (size_t)strtoull(optarg, NULL, 10);
                break;
            case 'k':
                cfg->keep_count = atoi(optarg);
                break;
            case 't':
                cfg->sleep_secs = (unsigned)strtoul(optarg, NULL, 10);
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    if (cfg->rotate_size == 0) return -1;
    if (cfg->keep_count < 0) return -1;
    if (cfg->sleep_secs == 0) cfg->sleep_secs = 1;

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s rotate_bytes] [-k keep_count] [-t sleep_secs] [-d]\n",
        prog);
}

int main(int argc, char **argv) {
    struct config cfg;
    off_t sz;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (cfg.daemonize) {
        if (do_daemonize() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    while (g_running) {
        if (file_size(cfg.log_path, &sz) == 0) {
            if ((size_t)sz >= cfg.rotate_size) {
                if (rotate_logs(&cfg) < 0) {
                    /* In a real daemon, write to syslog or a status file */
                }
            }
        } else {
            if (errno == ENOENT) {
                ensure_log_exists(cfg.log_path);
            }
        }

        sleep(cfg.sleep_secs);
    }

    return 0;
}
