## `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <stdlib.h>
#include <signal.h>

#define MAX_PATH_LEN 256

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size_exceeds(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }
    return st.st_size >= max_size;
}

static int make_rotated_name(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int max_files) {
    char oldname[MAX_PATH_LEN];
    char newname[MAX_PATH_LEN];
    int i;

    if (max_files < 1) {
        return -1;
    }

    /* Remove oldest */
    if (make_rotated_name(oldname, sizeof(oldname), path, max_files) != 0) {
        return -1;
    }
    unlink(oldname);

    /* Shift N-1 down to 1 upward */
    for (i = max_files - 1; i >= 1; --i) {
        if (make_rotated_name(oldname, sizeof(oldname), path, i) != 0) {
            return -1;
        }
        if (make_rotated_name(newname, sizeof(newname), path, i + 1) != 0) {
            return -1;
        }
        rename(oldname, newname);
    }

    /* Rotate current log to .1 */
    if (make_rotated_name(newname, sizeof(newname), path, 1) != 0) {
        return -1;
    }
    if (rename(path, newname) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] <logfile> <max_size_bytes> <max_rotated_files> <interval_sec>\n"
        "  -d   daemonize\n",
        prog);
}

int main(int argc, char **argv) {
    int argi = 1;
    int do_daemon = 0;
    const char *logfile;
    off_t max_size;
    int max_files;
    unsigned int interval_sec;

    if (argc > 1 && strcmp(argv[1], "-d") == 0) {
        do_daemon = 1;
        argi++;
    }

    if (argc - argi != 4) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[argi++];
    max_size = (off_t)atoll(argv[argi++]);
    max_files = atoi(argv[argi++]);
    interval_sec = (unsigned int)atoi(argv[argi++]);

    if (strlen(logfile) >= MAX_PATH_LEN - 16) {
        fprintf(stderr, "logfile path too long\n");
        return 1;
    }
    if (max_size <= 0 || max_files <= 0 || interval_sec == 0) {
        fprintf(stderr, "invalid arguments\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (do_daemon) {
        if (daemonize() != 0) {
            return 1;
        }
    }

    while (g_running) {
        int rc = file_size_exceeds(logfile, max_size);
        if (rc < 0) {
            /* On stat error, just continue next cycle */
        } else if (rc > 0) {
            rotate_logs(logfile, max_files);
        }
        sleep(interval_sec);
    }

    return 0;
}
