## `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>

#define MAX_PATH_LEN 256
#define CHECK_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[MAX_PATH_LEN];
    off_t max_size;
    int max_rotations;
    int foreground;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    if (cfg->max_rotations < 1) return 0;

    if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) < 0)
        return -1;
    unlink(old_path);

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, i) < 0)
            return -1;
        if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0)
            return -1;
        rename(old_path, new_path);
    }

    if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0)
        return -1;

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (!s || *s == '\0' || !end) return -1;
    if (v <= 0) return -1;

    long long mult = 1;
    if (*end != '\0') {
        if (strcmp(end, "K") == 0 || strcmp(end, "k") == 0) mult = 1024LL;
        else if (strcmp(end, "M") == 0 || strcmp(end, "m") == 0) mult = 1024LL * 1024LL;
        else if (strcmp(end, "G") == 0 || strcmp(end, "g") == 0) mult = 1024LL * 1024LL * 1024LL;
        else return -1;
    }

    *out = (off_t)(v * mult);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] <log_path> <max_size> <max_rotations>\n"
        "  -f              Run in foreground\n"
        "  max_size        e.g. 1024, 10K, 5M\n"
        "  max_rotations   e.g. 3\n",
        prog);
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.foreground = 0;

    int argi = 1;
    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        cfg.foreground = 1;
        argi++;
    }

    if (argc - argi != 3) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(argv[argi]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    memcpy(cfg.log_path, argv[argi], strlen(argv[argi]) + 1);

    if (parse_size(argv[argi + 1], &cfg.max_size) < 0) {
        fprintf(stderr, "invalid max_size\n");
        return 1;
    }

    if (parse_int(argv[argi + 2], &cfg.max_rotations) < 0 || cfg.max_rotations < 1) {
        fprintf(stderr, "invalid max_rotations\n");
        return 1;
    }

    if (install_signals() < 0) {
        perror("sigaction");
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(cfg.log_path, &sz) == 0) {
            if (sz >= cfg.max_size) {
                if (rotate_logs(&cfg) < 0) {
                    /* Silent in daemon mode; keep running */
                }
            }
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    return 0;
}
