#endif

#ifndef MAX_ROTATIONS
#define MAX_ROTATIONS 9
#endif

struct config {
    const char *log_path;
    off_t max_size;
    int rotations;
};

static int write_all(int fd, const char *buf, size_t len) {
    while (len > 0) {
        ssize_t n = write(fd, buf, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        buf += n;
        len -= (size_t)n;
    }
    return 0;
}

static int open_log(const char *path) {
    return open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int index) {
    int n;
    if (index == 0) {
        n = snprintf(out, out_sz, "%s", base);
    } else {
        n = snprintf(out, out_sz, "%s.%d", base, index);
    }
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    if (cfg->rotations < 1 || cfg->rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    /* Remove oldest */
    if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, cfg->rotations) < 0) {
        return -1;
    }
    unlink(oldp);

    /* Shift: .(n-1) -> .n, ..., .1 -> .2 */
    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, i) < 0) {
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), cfg->log_path, i + 1) < 0) {
            return -1;
        }
        rename(oldp, newp);
    }

    /* Current log -> .1 */
    if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, 0) < 0) {
        return -1;
    }
    if (build_rotated_path(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }
    rename(oldp, newp);

    return 0;
}

static int maybe_rotate(int *fd, const struct config *cfg) {
    struct stat st;
    if (fstat(*fd, &st) < 0) {
        return -1;
    }

    if (st.st_size < cfg->max_size) {
        return 0;
    }

    if (close(*fd) < 0) {
        return -1;
    }

    if (rotate_logs(cfg) < 0) {
        return -1;
    }

    *fd = open_log(cfg->log_path);
    if (*fd < 0) {
        return -1;
    }

    return 0;
}

static int process_stream(int fd, const struct config *cfg) {
    char rbuf[READ_BUF_SIZE];
    char lbuf[LINE_BUF_SIZE];
    size_t llen = 0;

    for (;;) {
        ssize_t nr = read(STDIN_FILENO, rbuf, sizeof(rbuf));
        if (nr < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (nr == 0) {
            break;
        }

        for (ssize_t i = 0; i < nr; ++i) {
            char c = rbuf[i];

            if (llen < sizeof(lbuf)) {
                lbuf[llen++] = c;
            } else {
                /* Line too long: flush what we have and continue */
                if (write_all(fd, lbuf, llen) < 0) return -1;
                if (maybe_rotate(&fd, cfg) < 0) return -1;
                llen = 0;
                lbuf[llen++] = c;
            }

            if (c == '\n') {
                if (write_all(fd, lbuf, llen) < 0) return -1;
                if (maybe_rotate(&fd, cfg) < 0) return -1;
                llen = 0;
            }
        }
    }

    if (llen > 0) {
        if (write_all(fd, lbuf, llen) < 0) return -1;
        if (maybe_rotate(&fd, cfg) < 0) return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    const char *msg =
        "Usage: %s <log_path> <max_size_bytes> <rotations>\n"
        "Example: %s /tmp/app.log 1048576 3\n";
    fprintf(stderr, msg, prog, prog);
}

int main(int argc, char **argv) {
    struct config cfg;
    int fd;
    char *end = NULL;

    if (argc != 4) {
        usage(argv[0]);
        return 2;
    }

    cfg.log_path = argv[1];

    errno = 0;
    cfg.max_size = strtoll(argv[2], &end, 10);
    if (errno != 0 || end == argv[2] || *end != '\0' || cfg.max_size <= 0) {
        fprintf(stderr, "invalid max_size_bytes\n");
        return 2;
    }

    errno = 0;
    cfg.rotations = (int)strtol(argv[3], &end, 10);
    if (errno != 0 || end == argv[3] || *end != '\0' ||
        cfg.rotations < 1 || cfg.rotations > MAX_ROTATIONS) {
        fprintf(stderr, "invalid rotations (1-%d)\n", MAX_ROTATIONS);
        return 2;
    }

    fd = open_log(cfg.log_path);
    if (fd < 0) {
        perror("open_log");
        return 1;
    }

    if (process_stream(fd, &cfg) < 0) {
        perror("process_stream");
        close(fd);
        return 1;
    }

    if (close(fd) < 0) {
        perror("close");
        return 1;
    }

    return 0;
}
