#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int set_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > 2) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int keep) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep < 1) return 0;

    if (path_with_suffix(oldp, sizeof(oldp), path, keep) == 0) {
        unlink(oldp);
    }

    for (int i = keep - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), path, i) != 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), path, i + 1) != 0) return -1;
        if (rename(oldp, newp) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (path_with_suffix(newp, sizeof(newp), path, 1) != 0) return -1;
    if (rename(path, newp) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int file_size_off(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *sz = st.st_size;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] -p <logfile> -s <max_bytes> [-k keep] [-i interval_sec] [-m mem_bytes]\n"
        "  -f              foreground mode\n"
        "  -p <logfile>    path to log file\n"
        "  -s <max_bytes>  rotate when file exceeds this size\n"
        "  -k <keep>       number of rotated files to keep (default: 3)\n"
        "  -i <sec>        polling interval in seconds (default: 5)\n"
        "  -m <bytes>      address-space memory limit via setrlimit (default: 16777216)\n",
        prog);
}

int main(int argc, char **argv) {
    const char *log_path = NULL;
    off_t max_size = 0;
    int keep = 3;
    int interval_sec = 5;
    rlim_t mem_limit = 16 * 1024 * 1024;
    bool foreground = false;

    int opt;
    while ((opt = getopt(argc, argv, "fp:s:k:i:m:")) != -1) {
        switch (opt) {
            case 'f':
                foreground = true;
                break;
            case 'p':
                log_path = optarg;
                break;
            case 's':
                max_size = (off_t)strtoll(optarg, NULL, 10);
                break;
            case 'k':
                keep = atoi(optarg);
                break;
            case 'i':
                interval_sec = atoi(optarg);
                break;
            case 'm':
                mem_limit = (rlim_t)strtoull(optarg, NULL, 10);
                break;
            default:
                usage(argv[0]);
                return 2;
        }
    }

    if (!log_path || max_size <= 0 || keep < 1 || interval_sec < 1) {
        usage(argv[0]);
        return 2;
    }

    if (set_memory_limit_bytes(mem_limit) < 0) {
        log_stderr("failed to set memory limit: %s\n", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!foreground) {
        if (daemonize() < 0) {
            log_stderr("daemonize failed: %s\n", strerror(errno));
            return 1;
        }
    }

    while (!g_stop) {
        off_t sz;
        if (file_size_off(log_path, &sz) == 0) {
            if (sz >= max_size) {
                if (rotate_logs(log_path, keep) < 0) {
                    /* In daemon mode stderr is /dev/null; in foreground this is visible. */
                    log_stderr("rotation failed for %s: %s\n", log_path, strerror(errno));
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(log_path, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            } else {
                log_stderr("stat failed for %s: %s\n", log_path, strerror(errno));
            }
        }

        sleep((unsigned)interval_sec);
    }

    return 0;
}
