```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (1024 * 1024)   /* 1 MiB */
#define DEFAULT_ROTATIONS 3
#define DEFAULT_INTERVAL 1               /* seconds */

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *base, int suffix) {
    int n;
    if (suffix < 0)
        n = snprintf(dst, dstsz, "%s", base);
    else
        n = snprintf(dst, dstsz, "%s.%d", base, suffix);

    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int create_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) return -1;
    if (close(fd) < 0) return -1;
    return 0;
}

static int rotate_logs(const char *path, int rotations, mode_t mode) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    if (rotations < 1) {
        if (create_empty_file(path, mode) < 0) return -1;
        return 0;
    }

    /* Remove the oldest if it exists */
    if (safe_snprintf(oldp, sizeof(oldp), path, rotations) < 0) return -1;
    (void)unlink(oldp);

    /* Shift N-1 ... 1 upward */
    for (i = rotations - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (safe_snprintf(newp, sizeof(newp), path, i + 1) < 0) return -1;
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* Move current log to .1 */
    if (safe_snprintf(newp, sizeof(newp), path, 1) < 0) return -1;
    if (rename(path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    /* Create fresh log file */
    if (create_empty_file(path, mode) < 0) return -1;

    return 0;
}

static int stat_file(const char *path, off_t *size_out, mode_t *mode_out, ino_t *ino_out, dev_t *dev_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    if (size_out) *size_out = st.st_size;
    if (mode_out) *mode_out = st.st_mode & 0777;
    if (ino_out) *ino_out = st.st_ino;
    if (dev_out) *dev_out = st.st_dev;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> [max_size_bytes] [rotations] [interval_sec]\n"
        "Defaults: max_size=%d rotations=%d interval=%d\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_INTERVAL);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_INTERVAL;

    ino_t last_ino = 0;
    dev_t last_dev = 0;
    int have_identity = 0;

    if (argc < 2 || argc > 5) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];

    if (argc >= 3) {
        max_size = (off_t)atoll(argv[2]);
        if (max_size < 1) {
            fprintf(stderr, "invalid max_size\n");
            return 1;
        }
    }

    if (argc >= 4) {
        rotations = atoi(argv[3]);
        if (rotations < 0 || rotations > 9999) {
            fprintf(stderr, "invalid rotations\n");
            return 1;
        }
    }

    if (argc >= 5) {
        interval = atoi(argv[4]);
        if (interval < 1 || interval > 3600) {
            fprintf(stderr, "invalid interval\n");
            return 1;
        }
    }

    if (install_signals() < 0) {
        perror("sigaction");
        return 1;
    }

    while (!g_stop) {
        off_t size;
        mode_t mode;
        ino_t ino;
        dev_t dev;

        if (stat_file(logfile, &size, &mode, &ino, &dev) == 0) {
            if (!have_identity) {
                last_ino = ino;
                last_dev = dev;
                have_identity = 1;
            } else {
                /* If file was replaced externally, update identity */
                if (ino != last_ino || dev != last_dev) {
                    last_ino = ino;
                    last_dev = dev;
                }
            }

            if (size >= max_size) {
                if (rotate_logs(logfile, rotations, mode) < 0) {
                    perror("rotate");
                } else {
                    /* Refresh identity after rotation */
                    if (stat_file(logfile, NULL, NULL, &ino, &dev) == 0) {
                        last_ino = ino;
                        last_dev = dev;
                        have_identity = 1;
                    } else {
                        have_identity = 0;
                    }
                }
            }
        } else {
            if (errno == ENOENT) {
                /* If missing, create it with a conservative mode */
                if (create_empty_file(logfile, 0644) < 0) {
                    perror("create");
                } else if (stat_file(logfile, NULL, NULL, &ino, &dev) == 0) {
                    last_ino = ino;
                    last_dev = dev;
                    have_identity = 1;
                }
            } else {
                perror("stat");
            }
        }

        sleep((unsigned int)interval);
    }

    return 0;
}
