## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int keep) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep < 1) {
        return 0;
    }

    /* Remove oldest */
    if (build_rotated_path(oldp, sizeof(oldp), path, keep) != 0) {
        return -1;
    }
    unlink(oldp);

    /* Shift keep-1 ... 1 upward */
    for (int i = keep - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i) != 0) {
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), path, i + 1) != 0) {
            return -1;
        }
        rename(oldp, newp);
    }

    /* Rotate current log to .1 */
    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }
    if (rename(path, newp) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int sync_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        return -1;
    }
    int rc = fsync(fd);
    int saved = errno;
    close(fd);
    errno = saved;
    return rc;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_bytes> <keep_count> <poll_seconds>\n"
        "Example: %s /var/log/app.log 1048576 3 2\n",
        prog, prog);
}

int main(int argc, char **argv) {
    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    off_t max_bytes = (off_t)atoll(argv[2]);
    int keep_count = atoi(argv[3]);
    int poll_seconds = atoi(argv[4]);

    if (max_bytes <= 0 || keep_count < 1 || poll_seconds < 1) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(log_path, &sz) == 0) {
            if (sz >= max_bytes) {
                /* Best effort sync before rotate */
                sync_file(log_path);
                if (rotate_logs(log_path, keep_count) != 0) {
                    fprintf(stderr, "rotate failed for %s: %s\n",
                            log_path, strerror(errno));
                }
            }
        } else {
            if (errno != ENOENT) {
                fprintf(stderr, "stat failed for %s: %s\n",
                        log_path, strerror(errno));
            }
        }

        sleep((unsigned int)poll_seconds);
    }

    return 0;
}
