## Minimal implementation

```c
/*
 * minilogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c99 -Wall -Wextra -o minilogd minilogd.c
 *
 * Run:
 *   ./minilogd /var/log/app.log 1048576 5 2
 *
 * Args:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Example:
 *   ./minilogd ./app.log 1000000 3 1
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>

#define MAX_PATH_LEN 256

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int make_rotated_name(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int keep_count) {
    char old_name[MAX_PATH_LEN];
    char new_name[MAX_PATH_LEN];
    int i;

    if (keep_count < 1) {
        /* No backups requested: just truncate current file */
        FILE *f = fopen(path, "w");
        if (!f) {
            return -1;
        }
        fclose(f);
        return 0;
    }

    /* Remove the oldest file: path.keep_count */
    if (make_rotated_name(old_name, sizeof(old_name), path, keep_count) != 0) {
        return -1;
    }
    unlink(old_name);

    /* Shift: path.(n-1) -> path.n */
    for (i = keep_count - 1; i >= 1; --i) {
        if (make_rotated_name(old_name, sizeof(old_name), path, i) != 0) {
            return -1;
        }
        if (make_rotated_name(new_name, sizeof(new_name), path, i + 1) != 0) {
            return -1;
        }
        rename(old_name, new_name);
    }

    /* Current log -> path.1 */
    if (make_rotated_name(new_name, sizeof(new_name), path, 1) != 0) {
        return -1;
    }
    if (rename(path, new_name) != 0) {
        return -1;
    }

    /* Recreate empty log file */
    FILE *f = fopen(path, "w");
    if (!f) {
        return -1;
    }
    fclose(f);

    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') {
        return -1;
    }
    if (v < 0 || v > 2147483647L) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') {
        return -1;
    }
    if (v < 0) {
        return -1;
    }
    *out = (off_t)v;
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_size;
    int keep_count;
    int poll_interval;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_seconds>\n", argv[0]);
        return 1;
    }

    log_path = argv[1];

    if (strlen(log_path) >= MAX_PATH_LEN - 16) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    if (parse_size(argv[2], &max_size) != 0 || max_size <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &keep_count) != 0) {
        fprintf(stderr, "Invalid keep_count\n");
        return 1;
    }

    if (parse_int(argv[4], &poll_interval) != 0 || poll_interval <= 0) {
        fprintf(stderr, "Invalid poll_seconds\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (g_running) {
        off_t sz = 0;

        if (file_size(log_path, &sz) == 0) {
            if (sz >= max_size) {
                if (rotate_logs(log_path, keep_count) != 0) {
                    fprintf(stderr, "Rotation failed for %s: %s\n", log_path, strerror(errno));
                }
            }
        } else {
            /* If file doesn't exist, create it */
            if (errno == ENOENT) {
                FILE *f = fopen(log_path, "w");
                if (f) {
                    fclose(f);
                } else {
                    fprintf(stderr, "Failed to create %s: %s\n", log_path, strerror(errno));
                }
            } else {
                fprintf(stderr, "stat(%s) failed: %s\n", log_path, strerror(errno));
            }
        }

        sleep((unsigned int)poll_interval);
    }

    return 0;
}
