Below is a **minimal working log rotation daemon** in **C for Linux** designed to be **memory-constrained** and to enforce **strict memory limits** on itself.

It:
- Monitors a single log file
- Rotates when size exceeds a threshold
- Keeps a fixed number of rotated files
- Uses a small static buffer
- Sets strict process memory limits with `setrlimit()`
- Avoids dynamic allocation

---

## `logrotated.c`

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>

#define PATH_MAX_LEN 256
#define COPY_BUF_SIZE 4096

static int set_memory_limits(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;

    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return -1;
    }

    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        perror("setrlimit(RLIMIT_DATA)");
        return -1;
    }

    return 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    return st.st_size;
}

static int copy_file(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    ssize_t r;
    char buf[COPY_BUF_SIZE];

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) {
        perror("open src");
        return -1;
    }

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        perror("open dst");
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                perror("write");
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        perror("read");
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY | O_TRUNC);
    if (fd < 0) {
        perror("truncate open");
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const char *log_path, int max_files) {
    char old_path[PATH_MAX_LEN];
    char new_path[PATH_MAX_LEN];
    int i;

    if (max_files < 1) {
        return -1;
    }

    /* Delete oldest */
    snprintf(old_path, sizeof(old_path), "%s.%d", log_path, max_files);
    unlink(old_path);

    /* Shift existing rotations upward */
    for (i = max_files - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", log_path, i + 1);
        rename(old_path, new_path);
    }

    /* Copy current log to .1 and truncate original */
    snprintf(new_path, sizeof(new_path), "%s.1", log_path);
    if (copy_file(log_path, new_path) != 0) {
        return -1;
    }

    if (truncate_file(log_path) != 0) {
        return -1;
    }

    return 0;
}

static void daemon_loop(const char *log_path, off_t max_size, int max_files, unsigned interval_sec) {
    for (;;) {
        off_t sz = file_size(log_path);
        if (sz >= 0 && sz >= max_size) {
            if (rotate_logs(log_path, max_files) != 0) {
                fprintf(stderr, "rotation failed for %s\n", log_path);
            }
        }
        sleep(interval_sec);
    }
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <max_files> <interval_sec> <mem_limit_bytes>\n", prog);
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_size;
    int max_files;
    unsigned interval_sec;
    rlim_t mem_limit;

    if (argc != 6) {
        usage(argv[0]);
        return 1;
    }

    log_path = argv[1];
    max_size = (off_t)atoll(argv[2]);
    max_files = atoi(argv[3]);
    interval_sec = (unsigned)atoi(argv[4]);
    mem_limit = (rlim_t)atoll(argv[5]);

    if (max_size <= 0 || max_files <= 0 || interval_sec == 0 || mem_limit < (64 * 1024)) {
        fprintf(stderr, "invalid arguments\n");
        return 1;
    }

    if (set_memory_limits(mem_limit) != 0) {
        return 1;
    }

    /* Optional: detach into background */
    if (daemon(0, 0) != 0) {
        perror("daemon");
        return 1;
    }

    daemon_loop(log_path, max_size, max_files, interval_sec);
    return 0;
}
```

