# `src/main.rs`

```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};

const SOCKET_PATH: &str = "/tmp/resourced.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const MAX_TOP_PROCS: usize = 10;
const MEMORY_PRESSURE_THRESHOLD_PERCENT: f32 = 90.0;
const CPU_PRESSURE_THRESHOLD_PERCENT: f32 = 95.0;

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
    alerts: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<SystemSnapshot>,
    process_index: HashMap<i32, ProcessSnapshot>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Status,
    Top,
    Kill { pid: i32 },
    Renice { pid: i32, nice: i32 },
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let state = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let server_state = Arc::clone(&state);

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = command_server(server_state).await {
            error!("command server failed: {e:#}");
        }
    });

    tokio::select! {
        _ = monitor_task => {}
        _ = server_task => {}
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info,resourced=debug".into()),
        )
        .init();
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    loop {
        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let total_memory = sys.total_memory();
        let used_memory = sys.used_memory();
        let total_swap = sys.total_swap();
        let used_swap = sys.used_swap();
        let load = sysinfo::System::load_average();

        let mut disks = Vec::new();
        for disk in sys.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            disks.push(DiskSnapshot {
                name: disk.name().to_string_lossy().to_string(),
                mount_point: disk.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            });
        }

        let mut processes = Vec::new();
        let mut process_index = HashMap::new();

        for (pid, proc_) in sys.processes() {
            let snap = ProcessSnapshot {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_percent: proc_.cpu_usage(),
                memory_bytes: proc_.memory(),
                virtual_memory_bytes: proc_.virtual_memory(),
                status: format!("{:?}", proc_.status()),
            };
            process_index.insert(snap.pid, snap.clone());
            processes.push(snap);
        }

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(MAX_TOP_PROCS);

        let mut alerts = Vec::new();
        let mem_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        if mem_percent >= MEMORY_PRESSURE_THRESHOLD_PERCENT {
            alerts.push(format!("high memory pressure: {:.2}%", mem_percent));
        }
        if cpu_usage >= CPU_PRESSURE_THRESHOLD_PERCENT {
            alerts.push(format!("high cpu pressure: {:.2}%", cpu_usage));
        }
        for d in &disks {
            if d.used_percent >= 95.0 {
                alerts.push(format!(
                    "disk nearly full: {} mounted on {} at {:.2}%",
                    d.name, d.mount_point, d.used_percent
                ));
            }
        }

        let snapshot = SystemSnapshot {
            timestamp: now_unix(),
            cpu_usage_percent: cpu_usage,
            total_memory,
            used_memory,
            total_swap,
            used_swap,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disks,
            top_processes: processes,
            alerts,
        };

        {
            let mut guard = state.write().await;
            guard.latest = Some(snapshot);
            guard.process_index = process_index;
        }

        time::sleep(SAMPLE_INTERVAL).await;
    }
}

async fn command_server(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    info!("command socket listening at {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: Command = serde_json::from_str(line.trim()).context("parsing command json")?;
    let response = execute_command(cmd, state).await;

    let encoded = serde_json::to_vec(&response)?;
    writer.write_all(&encoded).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;

    Ok(())
}

async fn execute_command(cmd: Command, state: Arc<RwLock<SharedState>>) -> Response {
    match cmd {
        Command::Status => {
            let guard = state.read().await;
            match &guard.latest {
                Some(snapshot) => Response::Ok {
                    data: serde_json::to_value(snapshot).unwrap_or_else(|_| {
                        serde_json::json!({ "error": "serialization failure" })
                    }),
                },
                None => Response::Error {
                    message: "no snapshot available yet".to_string(),
                },
            }
        }
        Command::Top => {
            let guard = state.read().await;
            match &guard.latest {
                Some(snapshot) => Response::Ok {
                    data: serde_json::json!(snapshot.top_processes),
                },
                None => Response::Error {
                    message: "no snapshot available yet".to_string(),
                },
            }
        }
        Command::Kill { pid } => match kill(Pid::from_raw(pid), Signal::SIGTERM) {
            Ok(_) => Response::Ok {
                data: serde_json::json!({
                    "message": format!("sent SIGTERM to pid {}", pid)
                }),
            },
            Err(e) => Response::Error {
                message: format!("kill failed: {}", e),
            },
        },
        Command::Renice { pid, nice } => {
            let result = renice_process(pid, nice);
            match result {
                Ok(_) => Response::Ok {
                    data: serde_json::json!({
                        "message": format!("set nice={} for pid {}", nice, pid)
                    }),
                },
                Err(e) => Response::Error {
                    message: format!("renice failed: {}", e),
                },
            }
        }
    }
}

fn renice_process(pid: i32, nice: i32) -> Result<()> {
    let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, pid as u32, nice) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    Ok(())
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
