## `src/main.rs`

```rust
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use anyhow::Result;
use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use sysinfo::System;
use tokio::{signal, time};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MetricsSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    process_count: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PolicyConfig {
    max_cpu_percent: f32,
    max_memory_percent: f32,
    sample_interval_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonState {
    latest: Option<MetricsSnapshot>,
    policy: PolicyConfig,
    last_action: Option<String>,
}

type SharedState = Arc<RwLock<DaemonState>>;

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn collect_metrics(sys: &mut System) -> MetricsSnapshot {
    sys.refresh_all();

    let cpu = sys.global_cpu_info().cpu_usage();
    let total_mem = sys.total_memory() * 1024;
    let used_mem = sys.used_memory() * 1024;
    let total_swap = sys.total_swap() * 1024;
    let used_swap = sys.used_swap() * 1024;
    let load = System::load_average();
    let process_count = sys.processes().len();

    MetricsSnapshot {
        timestamp_ms: now_ms(),
        cpu_usage_percent: cpu,
        total_memory_bytes: total_mem,
        used_memory_bytes: used_mem,
        total_swap_bytes: total_swap,
        used_swap_bytes: used_swap,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        process_count,
    }
}

fn memory_percent(snapshot: &MetricsSnapshot) -> f32 {
    if snapshot.total_memory_bytes == 0 {
        0.0
    } else {
        (snapshot.used_memory_bytes as f32 / snapshot.total_memory_bytes as f32) * 100.0
    }
}

fn enforce_policy(snapshot: &MetricsSnapshot, state: &mut DaemonState) {
    let mem_pct = memory_percent(snapshot);

    if snapshot.cpu_usage_percent > state.policy.max_cpu_percent {
        let msg = format!(
            "CPU threshold exceeded: {:.2}% > {:.2}%",
            snapshot.cpu_usage_percent, state.policy.max_cpu_percent
        );
        warn!("{msg}");
        state.last_action = Some(format!("WARN: {msg}"));
    }

    if mem_pct > state.policy.max_memory_percent {
        let msg = format!(
            "Memory threshold exceeded: {:.2}% > {:.2}%",
            mem_pct, state.policy.max_memory_percent
        );
        warn!("{msg}");
        state.last_action = Some(format!("WARN: {msg}"));
    }
}

async fn metrics_handler(State(state): State<SharedState>) -> impl IntoResponse {
    let guard = state.read();
    Json(guard.latest.clone())
}

async fn health_handler() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "ok"
    }))
}

async fn state_handler(State(state): State<SharedState>) -> impl IntoResponse {
    let guard = state.read();
    Json(guard.clone())
}

async fn monitor_loop(state: SharedState) {
    let sample_interval = {
        let guard = state.read();
        guard.policy.sample_interval_ms
    };

    let mut ticker = time::interval(Duration::from_millis(sample_interval));
    let mut sys = System::new_all();

    loop {
        ticker.tick().await;

        let snapshot = collect_metrics(&mut sys);

        {
            let mut guard = state.write();
            enforce_policy(&snapshot, &mut guard);
            guard.latest = Some(snapshot.clone());
        }

        info!(
            cpu = snapshot.cpu_usage_percent,
            mem_used = snapshot.used_memory_bytes,
            mem_total = snapshot.total_memory_bytes,
            load1 = snapshot.load_avg_one,
            procs = snapshot.process_count,
            "metrics updated"
        );
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state: SharedState = Arc::new(RwLock::new(DaemonState {
        latest: None,
        policy: PolicyConfig {
            max_cpu_percent: 90.0,
            max_memory_percent: 90.0,
            sample_interval_ms: 1000,
        },
        last_action: None,
    }));

    let monitor_state = Arc::clone(&state);
    tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let app = Router::new()
        .route("/health", get(health_handler))
        .route("/metrics", get(metrics_handler))
        .route("/state", get(state_handler))
        .with_state(Arc::clone(&state));

    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    info!("starting daemon on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;

    axum::serve(listener, app)
        .with_graceful_shutdown(async {
            match signal::ctrl_c().await {
                Ok(()) => info!("shutdown signal received"),
                Err(e) => error!("failed to listen for shutdown signal: {}", e),
            }
        })
        .await?;

    Ok(())
}
```

