use tokio::time;

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const DISK_PATH: &str = "/";
const WATCHED_PROCESSES: &[&str] = &["sshd", "systemd", "cron"];

#[derive(Debug, Error)]
enum DaemonError {
    #[error("io error: {0}")]
    Io(#[from] io::Error),
    #[error("parse error: {0}")]
    Parse(String),
    #[error("nix error: {0}")]
    Nix(#[from] nix::Error),
}

#[derive(Debug, Clone, Serialize, Default)]
struct CpuMetrics {
    usage_percent: f64,
    load1: f64,
    load5: f64,
    load15: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct MemoryMetrics {
    total_kb: u64,
    available_kb: u64,
    used_kb: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct DiskMetrics {
    path: String,
    total_bytes: u64,
    free_bytes: u64,
    available_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct ProcessInfo {
    name: String,
    pids: Vec<i32>,
    running: bool,
}

#[derive(Debug, Clone, Serialize, Default)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    uptime_secs: u64,
    cpu: CpuMetrics,
    memory: MemoryMetrics,
    disk: DiskMetrics,
    processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct CpuSample {
    total: u64,
    idle: u64,
}

#[derive(Debug, Default)]
struct SharedState {
    snapshot: MetricsSnapshot,
    last_updated: u64,
}

#[tokio::main]
async fn main() -> Result<(), DaemonError> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let state = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            eprintln!("monitor loop error: {e}");
        }
    });

    let server_state = Arc::clone(&state);
    let server_task = tokio::spawn(async move {
        if let Err(e) = command_server(server_state).await {
            eprintln!("command server error: {e}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            eprintln!("shutdown signal received");
        }
        _ = monitor_task => {
            eprintln!("monitor task exited");
        }
        _ = server_task => {
            eprintln!("server task exited");
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) -> Result<(), DaemonError> {
    let mut ticker = time::interval(SAMPLE_INTERVAL);
    let mut prev_cpu = read_cpu_sample()?;

    loop {
        ticker.tick().await;

        let now = unix_time();
        let uptime = read_uptime_secs().unwrap_or(0);
        let cpu = {
            let current = read_cpu_sample()?;
            let usage = compute_cpu_usage(&prev_cpu, &current);
            prev_cpu = current;
            let (l1, l5, l15) = read_loadavg().unwrap_or((0.0, 0.0, 0.0));
            CpuMetrics {
                usage_percent: usage,
                load1: l1,
                load5: l5,
                load15: l15,
            }
        };

        let memory = read_memory_metrics().unwrap_or_default();
        let disk = read_disk_metrics(DISK_PATH).unwrap_or_default();
        let processes = WATCHED_PROCESSES
            .iter()
            .map(|name| read_process_info(name).unwrap_or_else(|_| ProcessInfo {
                name: (*name).to_string(),
                pids: Vec::new(),
                running: false,
            }))
            .collect::<Vec<_>>();

        let snapshot = MetricsSnapshot {
            timestamp_unix: now,
            uptime_secs: uptime,
            cpu,
            memory,
            disk,
            processes,
        };

        let mut guard = state.write().await;
        guard.last_updated = now;
        guard.snapshot = snapshot;
    }
}

async fn command_server(state: Arc<RwLock<SharedState>>) -> Result<(), DaemonError> {
    let listener = UnixListener::bind(SOCKET_PATH)?;
    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer.write_all(b"sysmond ready\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        let response = handle_command(cmd, &state).await;
        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn handle_command(cmd: &str, state: &Arc<RwLock<SharedState>>) -> String {
    let parts: Vec<&str> = cmd.split_whitespace().collect();
    if parts.is_empty() {
        return json_error("empty command");
    }

    match parts[0] {
        "status" => {
            let guard = state.read().await;
            serde_json::to_string(&guard.snapshot).unwrap_or_else(|e| json_error(&format!("serialize error: {e}")))
        }
        "metrics" => {
            let guard = state.read().await;
            serde_json::to_string_pretty(&guard.snapshot)
                .unwrap_or_else(|e| json_error(&format!("serialize error: {e}")))
        }
        "restart-process" => {
            if parts.len() != 2 {
                return json_error("usage: restart-process <name>");
            }
            match restart_process_by_name(parts[1]).await {
                Ok(msg) => json_ok(&msg),
                Err(e) => json_error(&e.to_string()),
            }
        }
        "kill-process" => {
            if parts.len() != 2 {
                return json_error("usage: kill-process <name>");
            }
            match kill_process_by_name(parts[1]).await {
                Ok(msg) => json_ok(&msg),
                Err(e) => json_error(&e.to_string()),
            }
        }
        _ => json_error("unknown command"),
    }
}

async fn restart_process_by_name(name: &str) -> Result<String, DaemonError> {
    let pids = find_pids_by_name(name)?;
    if pids.is_empty() {
        return Err(DaemonError::Parse(format!("process not found: {name}")));
    }

    for pid in &pids {
        kill(Pid::from_raw(*pid), Signal::SIGTERM)?;
    }

    time::sleep(Duration::from_secs(1)).await;

    for pid in &pids {
        let _ = kill(Pid::from_raw(*pid), Signal::SIGKILL);
    }

    Ok(format!("terminated process(es) named {name}: {:?}", pids))
}

async fn kill_process_by_name(name: &str) -> Result<String, DaemonError> {
    let pids = find_pids_by_name(name)?;
    if pids.is_empty() {
        return Err(DaemonError::Parse(format!("process not found: {name}")));
    }

    for pid in &pids {
        kill(Pid::from_raw(*pid), Signal::SIGKILL)?;
    }

    Ok(format!("killed process(es) named {name}: {:?}", pids))
}

fn read_cpu_sample() -> Result<CpuSample, DaemonError> {
    let content = fs::read_to_string("/proc/stat")?;
    let line = content
        .lines()
        .find(|l| l.starts_with("cpu "))
        .ok_or_else(|| DaemonError::Parse("missing cpu line".into()))?;

    let nums: Vec<u64> = line
        .split_whitespace()
        .skip(1)
        .map(|s| s.parse::<u64>().map_err(|e| DaemonError::Parse(e.to_string())))
        .collect::<Result<Vec<_>, _>>()?;

    if nums.len() < 4 {
        return Err(DaemonError::Parse("invalid /proc/stat cpu format".into()));
    }

    let idle = nums[3] + nums.get(4).copied().unwrap_or(0);
    let total = nums.iter().sum();

    Ok(CpuSample { total, idle })
}

fn compute_cpu_usage(prev: &CpuSample, curr: &CpuSample) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let used = total_delta.saturating_sub(idle_delta);
    (used as f64 / total_delta as f64) * 100.0
}

fn read_loadavg() -> Result<(f64, f64, f64), DaemonError> {
    let content = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = content.split_whitespace().collect();
    if parts.len() < 3 {
        return Err(DaemonError::Parse("invalid /proc/loadavg".into()));
    }

    Ok((
        parts[0].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
        parts[1].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
        parts[2].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
    ))
}

fn read_uptime_secs() -> Result<u64, DaemonError> {
    let content = fs::read_to_string("/proc/uptime")?;
    let first = content
        .split_whitespace()
        .next()
        .ok_or_else(|| DaemonError::Parse("invalid /proc/uptime".into()))?;
    let uptime = first
        .split('.')
        .next()
        .unwrap_or("0")
        .parse::<u64>()
        .map_err(|e| DaemonError::Parse(e.to_string()))?;
    Ok(uptime)
}

fn read_memory_metrics() -> Result<MemoryMetrics, DaemonError> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut map = HashMap::new();

    for line in content.lines() {
        if let Some((key, rest)) = line.split_once(':') {
            let value = rest
                .trim()
                .split_whitespace()
                .next()
                .unwrap_or("0")
                .parse::<u64>()
                .unwrap_or(0);
            map.insert(key.to_string(), value);
        }
    }

    let total = *map.get("MemTotal").unwrap_or(&0);
    let available = *map.get("MemAvailable").unwrap_or(&0);
    let used = total.saturating_sub(available);
    let used_percent = if total == 0 {
        0.0
    } else {
        (used as f64 / total as f64) * 100.0
    };

    Ok(MemoryMetrics {
        total_kb: total,
        available_kb: available,
        used_kb: used,
        used_percent,
    })
}

fn read_disk_metrics(path: &str) -> Result<DiskMetrics, DaemonError> {
    let c_path = std::ffi::CString::new(path).map_err(|e| DaemonError::Parse(e.to_string()))?;
    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };

    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(DaemonError::Io(io::Error::last_os_error()));
    }

    let total = stat.f_blocks.saturating_mul(stat.f_frsize.into());
    let free = stat.f_bfree.saturating_mul(stat.f_frsize.into());
    let avail = stat.f_bavail.saturating_mul(stat.f_frsize.into());
    let used = total.saturating_sub(free);

    let used_percent = if total == 0 {
        0.0
    } else {
        (used as f64 / total as f64) * 100.0
    };

    Ok(DiskMetrics {
        path: path.to_string(),
        total_bytes: total,
        free_bytes: free,
        available_bytes: avail,
        used_percent,
    })
}

fn read_process_info(name: &str) -> Result<ProcessInfo, DaemonError> {
    let pids = find_pids_by_name(name)?;
    Ok(ProcessInfo {
        name: name.to_string(),
        running: !pids.is_empty(),
        pids,
    })
}

fn find_pids_by_name(name: &str) -> Result<Vec<i32>, DaemonError> {
    let mut pids = Vec::new();

    for entry in fs::read_dir("/proc")? {
        let entry = entry?;
        let file_name = entry.file_name();
        let pid_str = file_name.to_string_lossy();

        if !pid_str.chars().all(|c| c.is_ascii_digit()) {
            continue;
        }

        let pid: i32 = match pid_str.parse() {
            Ok(v) => v,
            Err(_) => continue,
        };

        let comm_path = format!("/proc/{pid}/comm");
        let cmd_name = match fs::read_to_string(&comm_path) {
            Ok(s) => s.trim().to_string(),
            Err(_) => continue,
        };

        if cmd_name == name {
            pids.push(pid);
        }
    }

    Ok(pids)
}

fn unix_time() -> u64 {
    use std::time::SystemTime;
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs()
}

fn json_ok(msg: &str) -> String {
    format!(r#"{{"ok":true,"message":"{}"}}"#, escape_json(msg))
}

fn json_error(msg: &str) -> String {
    format!(r#"{{"ok":false,"error":"{}"}}"#, escape_json(msg))
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}
