use std::{
    net::SocketAddr,
    process::Stdio,
    sync::Arc,
    time::{Duration, Instant},
};

use anyhow::{Context, Result};
use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use clap::Parser;
use nix::sys::signal::{killpg, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use sysinfo::System;
use tokio::{
    process::{Child, Command},
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

#[derive(Parser, Debug, Clone)]
#[command(name = "resourced")]
struct Config {
    #[arg(long, default_value = "127.0.0.1:8080")]
    listen: SocketAddr,

    #[arg(long, default_value_t = 1000)]
    poll_ms: u64,

    #[arg(long, default_value_t = 90.0)]
    cpu_alert_pct: f32,

    #[arg(long, default_value_t = 90.0)]
    mem_alert_pct: f32,

    /// Optional command to supervise and manage safely.
    /// Example: --child "/usr/local/bin/myworker --serve"
    #[arg(long)]
    child: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp_unix_ms: u128,
    uptime_secs: u64,
    cpu_usage_pct: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    memory_usage_pct: f32,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    process_count: usize,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    alerts: Vec<String>,
    supervised_child: Option<ChildStatus>,
}

#[derive(Debug, Clone, Serialize)]
struct ChildStatus {
    pid: u32,
    running: bool,
    started_at_unix_ms: u128,
}

#[derive(Debug)]
struct ManagedChild {
    child: Child,
    started_at: Instant,
    started_at_unix_ms: u128,
}

#[derive(Debug)]
struct AppState {
    metrics: RwLock<Metrics>,
    child: RwLock<Option<ManagedChild>>,
    config: Config,
}

#[derive(Debug, Deserialize)]
struct ActionRequest {
    action: String,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,axum=info,resourced=debug".to_string()),
        )
        .init();

    let config = Config::parse();

    let initial_metrics = Metrics {
        timestamp_unix_ms: now_unix_ms(),
        uptime_secs: 0,
        cpu_usage_pct: 0.0,
        total_memory_bytes: 0,
        used_memory_bytes: 0,
        memory_usage_pct: 0.0,
        total_swap_bytes: 0,
        used_swap_bytes: 0,
        process_count: 0,
        loadavg_one: 0.0,
        loadavg_five: 0.0,
        loadavg_fifteen: 0.0,
        alerts: vec![],
        supervised_child: None,
    };

    let state = Arc::new(AppState {
        metrics: RwLock::new(initial_metrics),
        child: RwLock::new(None),
        config: config.clone(),
    });

    if let Some(cmdline) = &config.child {
        let child = spawn_supervised_child(cmdline).await?;
        let pid = child.child.id().unwrap_or_default();
        info!(pid, "spawned supervised child");
        *state.child.write().await = Some(child);
    }

    let collector_state = Arc::clone(&state);
    tokio::spawn(async move {
        if let Err(e) = collector_loop(collector_state).await {
            error!(error = %e, "collector loop exited");
        }
    });

    let app = Router::new()
        .route("/healthz", get(healthz))
        .route("/metrics", get(get_metrics))
        .route("/action", post(post_action))
        .with_state(Arc::clone(&state));

    info!("listening on {}", config.listen);
    let listener = tokio::net::TcpListener::bind(config.listen).await?;
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal(Arc::clone(&state)))
        .await
        .context("server failed")?;

    Ok(())
}

async fn collector_loop(state: Arc<AppState>) -> Result<()> {
    let mut sys = System::new_all();
    let mut ticker = time::interval(Duration::from_millis(state.config.poll_ms));
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        ticker.tick().await;

        sys.refresh_cpu_usage();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_system();

        let total_mem = sys.total_memory();
        let used_mem = sys.used_memory();
        let total_swap = sys.total_swap();
        let used_swap = sys.used_swap();
        let cpu = sys.global_cpu_usage();
        let process_count = sys.processes().len();
        let load = System::load_average();

        let mem_pct = if total_mem > 0 {
            (used_mem as f32 / total_mem as f32) * 100.0
        } else {
            0.0
        };

        let mut alerts = Vec::new();
        if cpu >= state.config.cpu_alert_pct {
            alerts.push(format!("high_cpu:{cpu:.2}%"));
        }
        if mem_pct >= state.config.mem_alert_pct {
            alerts.push(format!("high_mem:{mem_pct:.2}%"));
        }

        let child_status = {
            let mut guard = state.child.write().await;
            if let Some(managed) = guard.as_mut() {
                let running = match managed.child.try_wait()? {
                    Some(status) => {
                        warn!(?status, "supervised child exited");
                        false
                    }
                    None => true,
                };

                let pid = managed.child.id().unwrap_or_default();
                Some(ChildStatus {
                    pid,
                    running,
                    started_at_unix_ms: managed.started_at_unix_ms,
                })
            } else {
                None
            }
        };

        let metrics = Metrics {
            timestamp_unix_ms: now_unix_ms(),
            uptime_secs: System::uptime(),
            cpu_usage_pct: cpu,
            total_memory_bytes: total_mem * 1024,
            used_memory_bytes: used_mem * 1024,
            memory_usage_pct: mem_pct,
            total_swap_bytes: total_swap * 1024,
            used_swap_bytes: used_swap * 1024,
            process_count,
            loadavg_one: load.one,
            loadavg_five: load.five,
            loadavg_fifteen: load.fifteen,
            alerts,
            supervised_child: child_status,
        };

        *state.metrics.write().await = metrics;
    }
}

async fn healthz() -> impl IntoResponse {
    (StatusCode::OK, "ok")
}

async fn get_metrics(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let metrics = state.metrics.read().await.clone();
    Json(metrics)
}

async fn post_action(
    State(state): State<Arc<AppState>>,
    Json(req): Json<ActionRequest>,
) -> impl IntoResponse {
    match req.action.as_str() {
        "terminate_child" => {
            let mut guard = state.child.write().await;
            if let Some(managed) = guard.as_mut() {
                if let Some(pid_u32) = managed.child.id() {
                    let pgid = Pid::from_raw(pid_u32 as i32);
                    match killpg(pgid, Signal::SIGTERM) {
                        Ok(_) => {
                            info!(pid = pid_u32, "sent SIGTERM to child process group");
                            return (StatusCode::OK, "terminated child").into_response();
                        }
                        Err(e) => {
                            error!(error = %e, pid = pid_u32, "failed to terminate child");
                            return (
                                StatusCode::INTERNAL_SERVER_ERROR,
                                format!("terminate failed: {e}"),
                            )
                                .into_response();
                        }
                    }
                }
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "child pid unavailable".to_string(),
                )
                    .into_response()
            } else {
                (StatusCode::BAD_REQUEST, "no supervised child".to_string()).into_response()
            }
        }
        _ => (StatusCode::BAD_REQUEST, "unknown action".to_string()).into_response(),
    }
}

async fn spawn_supervised_child(cmdline: &str) -> Result<ManagedChild> {
    let mut parts = shell_words(cmdline)?;
    if parts.is_empty() {
        anyhow::bail!("empty child command");
    }

    let program = parts.remove(0);
    let mut cmd = Command::new(program);
    cmd.args(parts)
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    #[cfg(target_os = "linux")]
    {
        use std::os::unix::process::CommandExt;
        unsafe {
            cmd.pre_exec(|| {
                nix::unistd::setsid()
                    .map(|_| ())
                    .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))
            });
        }
    }

    let child = cmd.spawn().context("failed to spawn child")?;
    Ok(ManagedChild {
        child,
        started_at: Instant::now(),
        started_at_unix_ms: now_unix_ms(),
    })
}

fn shell_words(input: &str) -> Result<Vec<String>> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut chars = input.chars().peekable();
    let mut quote: Option<char> = None;

    while let Some(c) = chars.next() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else if c == '\\' && q == '"' {
                    if let Some(n) = chars.next() {
                        cur.push(n);
                    }
                } else {
                    cur.push(c);
                }
            }
            None => match c {
                '\'' | '"' => quote = Some(c),
                ' ' | '\t' | '\n' if !cur.is_empty() => {
                    out.push(std::mem::take(&mut cur));
                }
                ' ' | '\t' | '\n' => {}
                '\\' => {
                    if let Some(n) = chars.next() {
                        cur.push(n);
                    }
                }
                _ => cur.push(c),
            },
        }
    }

    if quote.is_some() {
        anyhow::bail!("unterminated quote");
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    Ok(out)
}

async fn shutdown_signal(state: Arc<AppState>) {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        let mut sigterm =
            signal::unix::signal(signal::unix::SignalKind::terminate()).expect("sigterm handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");

    let mut guard = state.child.write().await;
    if let Some(managed) = guard.as_mut() {
        if let Some(pid_u32) = managed.child.id() {
            let pgid = Pid::from_raw(pid_u32 as i32);
            let _ = killpg(pgid, Signal::SIGTERM);
            let _ = time::timeout(Duration::from_secs(5), managed.child.wait()).await;
        }
    }
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
