```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::{
    cmp::Reverse,
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CpuMetrics {
    usage_percent: f32,
    logical_cores: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MemoryMetrics {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskMetrics {
    total_read_bytes: u64,
    total_written_bytes: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    cpu: CpuMetrics,
    memory: MemoryMetrics,
    disk: DiskMetrics,
    process_count: usize,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetMetrics,
    ListTopProcesses { limit: Option<usize> },
    KillProcess { pid: i32, signal: Option<String> },
    Ping,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Response {
    ok: bool,
    data: Option<serde_json::Value>,
    error: Option<String>,
}

impl Response {
    fn ok<T: Serialize>(value: T) -> Self {
        Self {
            ok: true,
            data: Some(serde_json::to_value(value).unwrap_or(serde_json::Value::Null)),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

#[derive(Clone)]
struct SharedState {
    snapshot: Arc<RwLock<MetricsSnapshot>>,
}

impl SharedState {
    async fn get_snapshot(&self) -> MetricsSnapshot {
        self.snapshot.read().await.clone()
    }

    async fn set_snapshot(&self, snap: MetricsSnapshot) {
        *self.snapshot.write().await = snap;
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn parse_signal(name: Option<String>) -> Result<Signal> {
    let sig = match name
        .unwrap_or_else(|| "term".to_string())
        .to_ascii_lowercase()
        .as_str()
    {
        "term" | "sigterm" => Signal::SIGTERM,
        "kill" | "sigkill" => Signal::SIGKILL,
        "int" | "sigint" => Signal::SIGINT,
        "hup" | "sighup" => Signal::SIGHUP,
        other => anyhow::bail!("unsupported signal: {}", other),
    };
    Ok(sig)
}

fn collect_snapshot(sys: &mut System) -> MetricsSnapshot {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything()),
    );

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let logical_cores = sys.cpus().len();

    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let free_mem = sys.free_memory();
    let avail_mem = sys.available_memory();

    let used_percent = if total_mem == 0 {
        0.0
    } else {
        (used_mem as f32 / total_mem as f32) * 100.0
    };

    let mut processes: Vec<ProcessInfo> = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_percent: p.cpu_usage(),
            memory_bytes: p.memory(),
            status: format!("{:?}", p.status()),
        })
        .collect();

    processes.sort_by_key(|p| Reverse((p.cpu_percent * 100.0) as u64));
    let top_processes = processes.iter().take(10).cloned().collect::<Vec<_>>();

    let disks = sys.disks();
    let mut total_read = 0u64;
    let mut total_written = 0u64;
    for d in disks {
        let usage = d.usage();
        total_read = total_read.saturating_add(usage.total_read_bytes);
        total_written = total_written.saturating_add(usage.total_written_bytes);
    }

    MetricsSnapshot {
        timestamp_unix: now_unix(),
        cpu: CpuMetrics {
            usage_percent: cpu_usage,
            logical_cores,
        },
        memory: MemoryMetrics {
            total_bytes: total_mem,
            used_bytes: used_mem,
            free_bytes: free_mem,
            available_bytes: avail_mem,
            used_percent,
        },
        disk: DiskMetrics {
            total_read_bytes: total_read,
            total_written_bytes: total_written,
        },
        process_count: processes.len(),
        top_processes,
    }
}

async fn monitor_loop(state: SharedState) {
    let mut sys = System::new_all();
    let mut ticker = time::interval(SAMPLE_INTERVAL);

    loop {
        ticker.tick().await;
        let snap = collect_snapshot(&mut sys);
        state.set_snapshot(snap).await;
    }
}

async fn handle_request(req: Request, state: SharedState) -> Response {
    match req {
        Request::GetMetrics => {
            let snap = state.get_snapshot().await;
            Response::ok(snap)
        }
        Request::ListTopProcesses { limit } => {
            let snap = state.get_snapshot().await;
            let n = limit.unwrap_or(10).min(100);
            Response::ok(snap.top_processes.into_iter().take(n).collect::<Vec<_>>())
        }
        Request::KillProcess { pid, signal } => match parse_signal(signal) {
            Ok(sig) => match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::ok(serde_json::json!({
                    "pid": pid,
                    "signal": format!("{:?}", sig),
                    "status": "sent"
                })),
                Err(e) => Response::err(format!("failed to signal pid {}: {}", pid, e)),
            },
            Err(e) => Response::err(e.to_string()),
        },
        Request::Ping => Response::ok(serde_json::json!({ "pong": true })),
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let req: Request = match serde_json::from_str(line) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::err(format!("invalid request: {}", e));
                let msg = serde_json::to_string(&resp)? + "\n";
                writer.write_all(msg.as_bytes()).await?;
                continue;
            }
        };

        let resp = handle_request(req, state.clone()).await;
        let msg = serde_json::to_string(&resp)? + "\n";
        writer.write_all(msg.as_bytes()).await?;
    }

    Ok(())
}

async fn socket_server(state: SharedState) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("removing stale socket {}", SOCKET_PATH))?;
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("binding unix socket {}", SOCKET_PATH))?;

    info!("socket server listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handler error: {}", e);
            }
        });
    }
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        let mut sigterm =
            signal::unix::signal(signal::unix::SignalKind::terminate()).expect("sigterm handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let initial = MetricsSnapshot {
        timestamp_unix: now_unix(),
        cpu: CpuMetrics {
            usage_percent: 0.0,
            logical_cores: 0,
        },
        memory: MemoryMetrics {
            total_bytes: 0,
            used_bytes: 0,
            free_bytes: 0,
            available_bytes: 0,
            used_percent: 0.0,
        },
        disk: DiskMetrics {
            total_read_bytes: 0,
            total_written_bytes: 0,
        },
        process_count: 0,
        top_processes: Vec::new(),
    };

    let state = SharedState {
        snapshot: Arc::new(RwLock::new(initial)),
    };

    let monitor_state = state.clone();
    let server_state = state.clone();

    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = socket_server(server_state).await {
            error!("socket server failed: {}", e);
        }
    });

    info!("osd started");

    shutdown_signal().await;
    info!("shutdown requested");

    monitor_task.abort();
    server_task.abort();

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = std::fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket {}: {}", SOCKET_PATH, e);
        }
    }

    info!("osd stopped");
    Ok(())
}
