    disk_alert_threshold: f32,
    runaway_process_cpu_threshold: f32,
    runaway_process_memory_kb: u64,
    managed_services: Vec<ManagedService>,
    watched_processes: Vec<WatchedProcess>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ManagedService {
    name: String,
    restart_cmd: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct WatchedProcess {
    name: String,
    pid_file: Option<String>,
    restart_service: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_used_percent: f32,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    disks: Vec<DiskSnapshot>,
    watched: Vec<WatchedProcessStatus>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct WatchedProcessStatus {
    name: String,
    pid: Option<i32>,
    alive: bool,
    cpu_usage_percent: Option<f32>,
    memory_kb: Option<u64>,
    last_checked_unix_ms: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonState {
    last_snapshot: Option<ResourceSnapshot>,
    last_actions: Vec<ActionRecord>,
    started_at_unix_ms: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ActionRecord {
    timestamp_unix_ms: u128,
    action: String,
    target: String,
    result: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    Status,
    RestartService { name: String },
    KillPid { pid: i32, signal: Option<i32> },
    Snapshot,
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
struct ControlResponse {
    ok: bool,
    message: String,
    state: Option<DaemonState>,
    snapshot: Option<ResourceSnapshot>,
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn default_config() -> Config {
    Config {
        socket_path: "/tmp/osd.sock".to_string(),
        poll_interval_ms: 2000,
        cpu_alert_threshold: 90.0,
        memory_alert_threshold: 90.0,
        disk_alert_threshold: 95.0,
        runaway_process_cpu_threshold: 95.0,
        runaway_process_memory_kb: 1024 * 1024,
        managed_services: vec![
            ManagedService {
                name: "example-service".to_string(),
                restart_cmd: vec![
                    "/bin/systemctl".to_string(),
                    "restart".to_string(),
                    "example-service".to_string(),
                ],
            }
        ],
        watched_processes: vec![WatchedProcess {
            name: "example-service".to_string(),
            pid_file: Some("/run/example-service.pid".to_string()),
            restart_service: Some("example-service".to_string()),
        }],
    }
}

async fn load_config(path: Option<&str>) -> Result<Config> {
    if let Some(path) = path {
        let content = tokio::fs::read_to_string(path)
            .await
            .with_context(|| format!("reading config {}", path))?;
        let cfg = serde_json::from_str::<Config>(&content)
            .with_context(|| format!("parsing config {}", path))?;
        Ok(cfg)
    } else {
        Ok(default_config())
    }
}

async fn restart_service(cfg: &Config, state: &Arc<RwLock<DaemonState>>, name: &str) -> Result<()> {
    let svc = cfg
        .managed_services
        .iter()
        .find(|s| s.name == name)
        .with_context(|| format!("service '{}' not found", name))?;

    if svc.restart_cmd.is_empty() {
        anyhow::bail!("restart command for '{}' is empty", name);
    }

    let mut cmd = Command::new(&svc.restart_cmd[0]);
    if svc.restart_cmd.len() > 1 {
        cmd.args(&svc.restart_cmd[1..]);
    }
    cmd.stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());

    let status = cmd
        .status()
        .await
        .with_context(|| format!("executing restart command for '{}'", name))?;

    let result = if status.success() {
        "success".to_string()
    } else {
        format!("exit_status={status}")
    };

    {
        let mut st = state.write().await;
        st.last_actions.push(ActionRecord {
            timestamp_unix_ms: now_unix_ms(),
            action: "restart_service".to_string(),
            target: name.to_string(),
            result: result.clone(),
        });
        if st.last_actions.len() > 1000 {
            let drain = st.last_actions.len() - 1000;
            st.last_actions.drain(0..drain);
        }
    }

    if status.success() {
        info!("restarted service {}", name);
        Ok(())
    } else {
        anyhow::bail!("restart command failed for '{}': {}", name, status)
    }
}

async fn kill_process(
    state: &Arc<RwLock<DaemonState>>,
    pid: i32,
    sig: Signal,
) -> Result<()> {
    kill(Pid::from_raw(pid), sig).with_context(|| format!("killing pid {}", pid))?;

    {
        let mut st = state.write().await;
        st.last_actions.push(ActionRecord {
            timestamp_unix_ms: now_unix_ms(),
            action: "kill_pid".to_string(),
            target: pid.to_string(),
            result: format!("signal={sig:?}"),
        });
        if st.last_actions.len() > 1000 {
            let drain = st.last_actions.len() - 1000;
            st.last_actions.drain(0..drain);
        }
    }

    Ok(())
}

fn read_pid_file(path: &str) -> Option<i32> {
    let content = fs::read_to_string(path).ok()?;
    content.trim().parse::<i32>().ok()
}

fn process_alive(sys: &System, pid: i32) -> bool {
    sys.process(SysPid::from_u32(pid as u32)).is_some()
}

fn process_status(sys: &System, wp: &WatchedProcess) -> WatchedProcessStatus {
    let pid = wp.pid_file.as_deref().and_then(read_pid_file);
    let proc = pid.and_then(|p| sys.process(SysPid::from_u32(p as u32)));

    WatchedProcessStatus {
        name: wp.name.clone(),
        pid,
        alive: pid.map(|p| process_alive(sys, p)).unwrap_or(false),
        cpu_usage_percent: proc.map(|p| p.cpu_usage()),
        memory_kb: proc.map(|p| p.memory()),
        last_checked_unix_ms: now_unix_ms(),
    }
}

fn collect_snapshot(sys: &System, disks: &Disks, cfg: &Config) -> ResourceSnapshot {
    let total_memory_kb = sys.total_memory();
    let used_memory_kb = sys.used_memory();
    let total_swap_kb = sys.total_swap();
    let used_swap_kb = sys.used_swap();
    let memory_used_percent = if total_memory_kb == 0 {
        0.0
    } else {
        (used_memory_kb as f32 / total_memory_kb as f32) * 100.0
    };

    let disks_vec = disks
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used_percent = if total == 0 {
                0.0
            } else {
                ((total - avail) as f32 / total as f32) * 100.0
            };
            DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            }
        })
        .collect::<Vec<_>>();

    let load: LoadAvg = System::load_average();

    ResourceSnapshot {
        timestamp_unix_ms: now_unix_ms(),
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        memory_used_percent,
        total_memory_kb,
        used_memory_kb,
        total_swap_kb,
        used_swap_kb,
        loadavg_one: load.one,
        loadavg_five: load.five,
        loadavg_fifteen: load.fifteen,
        disks: disks_vec,
        watched: cfg
            .watched_processes
            .iter()
            .map(|wp| process_status(sys, wp))
            .collect(),
    }
}

async fn monitor_loop(cfg: Config, state: Arc<RwLock<DaemonState>>) {
    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();
    let mut ticker = time::interval(Duration::from_millis(cfg.poll_interval_ms));

    loop {
        ticker.tick().await;

        let start = Instant::now();

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes(ProcessesToUpdate::All, true);
        disks.refresh();

        let snapshot = collect_snapshot(&sys, &disks, &cfg);

        if snapshot.cpu_usage_percent >= cfg.cpu_alert_threshold {
            warn!("high cpu usage: {:.2}%", snapshot.cpu_usage_percent);
        }

        if snapshot.memory_used_percent >= cfg.memory_alert_threshold {
            warn!("high memory usage: {:.2}%", snapshot.memory_used_percent);
        }

        for d in &snapshot.disks {
            if d.used_percent >= cfg.disk_alert_threshold {
                warn!(
                    "disk usage high on {} ({}): {:.2}%",
                    d.name, d.mount_point, d.used_percent
                );
            }
        }

        for watched in &snapshot.watched {
            if !watched.alive {
                warn!("watched process '{}' is not alive", watched.name);
                if let Some(wp) = cfg
                    .watched_processes
                    .iter()
                    .find(|p| p.name == watched.name)
                {
                    if let Some(svc) = &wp.restart_service {
                        if let Err(e) = restart_service(&cfg, &state, svc).await {
                            error!("failed to restart service '{}': {e:#}", svc);
                        }
                    }
                }
            } else if let (Some(pid), Some(cpu), Some(mem)) =
                (watched.pid, watched.cpu_usage_percent, watched.memory_kb)
            {
                if cpu >= cfg.runaway_process_cpu_threshold
                    || mem >= cfg.runaway_process_memory_kb
                {
                    warn!(
                        "runaway process '{}' pid={} cpu={:.2}% mem={}KB",
                        watched.name, pid, cpu, mem
                    );
                    if let Err(e) = kill_process(&state, pid, Signal::SIGTERM).await {
                        error!("failed to SIGTERM pid {}: {e:#}", pid);
                    }
                }
            }
        }

        {
            let mut st = state.write().await;
            st.last_snapshot = Some(snapshot);
        }

        let elapsed = start.elapsed();
        info!("monitor cycle completed in {:?}", elapsed);
    }
}

async fn handle_client(
    stream: UnixStream,
    cfg: Config,
    state: Arc<RwLock<DaemonState>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: ControlCommand = serde_json::from_str(line.trim())
        .with_context(|| "invalid control command json")?;

    let response = match cmd {
        ControlCommand::Ping => ControlResponse {
            ok: true,
            message: "pong".to_string(),
            state: None,
            snapshot: None,
        },
        ControlCommand::Status => {
            let st = state.read().await.clone();
            ControlResponse {
                ok: true,
                message: "ok".to_string(),
                state: Some(st),
                snapshot: None,
            }
        }
        ControlCommand::Snapshot => {
            let snap = state.read().await.last_snapshot.clone();
            ControlResponse {
                ok: snap.is_some(),
                message: if snap.is_some() {
                    "ok".to_string()
                } else {
                    "no snapshot yet".to_string()
                },
                state: None,
                snapshot: snap,
            }
        }
        ControlCommand::RestartService { name } => match restart_service(&cfg, &state, &name).await {
            Ok(_) => ControlResponse {
                ok: true,
                message: format!("service '{}' restarted", name),
                state: None,
                snapshot: None,
            },
            Err(e) => ControlResponse {
                ok: false,
                message: format!("{e:#}"),
                state: None,
                snapshot: None,
            },
        },
        ControlCommand::KillPid { pid, signal } => {
            let sig = signal
                .and_then(|s| Signal::try_from(s).ok())
                .unwrap_or(Signal::SIGTERM);
            match kill_process(&state, pid, sig).await {
                Ok(_) => ControlResponse {
                    ok: true,
                    message: format!("pid {} signaled with {:?}", pid, sig),
                    state: None,
                    snapshot: None,
                },
                Err(e) => ControlResponse {
                    ok: false,
                    message: format!("{e:#}"),
                    state: None,
                    snapshot: None,
                },
            }
        }
    };

    let payload = serde_json::to_vec(&response)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

async fn control_server(cfg: Config, state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let socket_path = Path::new(&cfg.socket_path);
    if socket_path.exists() {
        fs::remove_file(socket_path)
            .with_context(|| format!("removing stale socket {}", cfg.socket_path))?;
    }

    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("binding unix socket {}", cfg.socket_path))?;

    info!("control socket listening on {}", cfg.socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let cfg_clone = cfg.clone();
        let state_clone = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, cfg_clone, state_clone).await {
                error!("client handling error: {e:#}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_path = std::env::args().nth(1);
    let cfg = load_config(config_path.as_deref()).await?;

    let state = Arc::new(RwLock::new(DaemonState {
        last_snapshot: None,
        last_actions: Vec::new(),
        started_at_unix_ms: now_unix_ms(),
    }));

    let monitor_cfg = cfg.clone();
    let monitor_state = state.clone();
    tokio::spawn(async move {
        monitor_loop(monitor_cfg, monitor_state).await;
    });

    let control_cfg = cfg.clone();
    let control_state = state.clone();
    let control_task = tokio::spawn(async move { control_server(control_cfg, control_state).await });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = control_task => {
            match res {
                Ok(Ok(())) => info!("control server exited"),
                Ok(Err(e)) => error!("control server error: {e:#}"),
                Err(e) => error!("control task join error: {e:#}"),
            }
        }
    }

    if Path::new(&cfg.socket_path).exists() {
        let _ = fs::remove_file(&cfg.socket_path);
    }

    info!("daemon exiting");
    Ok(())
}
