use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{broadcast, RwLock},
    task,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const TOP_N_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    file_system: String,
    is_removable: bool,
}

#[derive(Debug, Clone, Serialize)]
struct Snapshot {
    timestamp_unix: u64,
    cpu_usage_percent: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct DaemonState {
    latest: Option<Snapshot>,
    process_index: HashMap<u32, ProcessInfo>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Status,
    Top,
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Status { snapshot: Option<Snapshot> },
    Top { processes: Vec<ProcessInfo> },
    Ack { message: String },
    Error { message: String },
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket {}", SOCKET_PATH))?;
    }

    let state = Arc::new(RwLock::new(DaemonState::default()));
    let (shutdown_tx, _) = broadcast::channel::<()>(16);

    let monitor_handle = {
        let state = Arc::clone(&state);
        let shutdown_rx = shutdown_tx.subscribe();
        task::spawn(async move {
            if let Err(e) = monitor_loop(state, shutdown_rx).await {
                error!("monitor loop failed: {e:#}");
            }
        })
    };

    let server_handle = {
        let state = Arc::clone(&state);
        let shutdown_rx = shutdown_tx.subscribe();
        let shutdown_tx = shutdown_tx.clone();
        task::spawn(async move {
            if let Err(e) = server_loop(state, shutdown_rx, shutdown_tx).await {
                error!("server loop failed: {e:#}");
            }
        })
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c, shutting down");
        }
        _ = monitor_handle => {
            warn!("monitor task exited");
        }
        _ = server_handle => {
            warn!("server task exited");
        }
    }

    let _ = shutdown_tx.send(());

    time::sleep(Duration::from_millis(300)).await;

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = std::fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket on shutdown: {e}");
        }
    }

    info!("daemon exited");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn monitor_loop(
    state: Arc<RwLock<DaemonState>>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    let mut ticker = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = ticker.tick() => {
                let snapshot = collect_snapshot(&mut system)?;
                let process_index = snapshot
                    .top_processes
                    .iter()
                    .cloned()
                    .map(|p| (p.pid, p))
                    .collect::<HashMap<_, _>>();

                {
                    let mut guard = state.write().await;
                    guard.latest = Some(snapshot);
                    guard.process_index = process_index;
                }
            }
        }
    }

    Ok(())
}

fn collect_snapshot(system: &mut System) -> Result<Snapshot> {
    system.refresh_memory();
    system.refresh_cpu();
    system.refresh_processes();
    system.refresh_disks_list();
    system.refresh_disks();

    let cpu_usage_percent = system.global_cpu_info().cpu_usage();
    let load = System::load_average();

    let total_memory_bytes = system.total_memory() * 1024;
    let used_memory_bytes = system.used_memory() * 1024;
    let total_swap_bytes = system.total_swap() * 1024;
    let used_swap_bytes = system.used_swap() * 1024;

    let mut disks = Vec::new();
    for d in system.disks() {
        disks.push(DiskInfo {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            is_removable: d.is_removable(),
        });
    }

    let mut processes = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
            virtual_memory_bytes: proc_.virtual_memory() * 1024,
            status: format!("{:?}", proc_.status()),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.memory_bytes
            .cmp(&a.memory_bytes)
            .then_with(|| b.cpu_percent.partial_cmp(&a.cpu_percent).unwrap_or(std::cmp::Ordering::Equal))
    });
    processes.truncate(TOP_N_PROCESSES);

    let timestamp_unix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    Ok(Snapshot {
        timestamp_unix,
        cpu_usage_percent,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        total_memory_bytes,
        used_memory_bytes,
        total_swap_bytes,
        used_swap_bytes,
        disks,
        top_processes: processes,
    })
}

async fn server_loop(
    state: Arc<RwLock<DaemonState>>,
    mut shutdown_rx: broadcast::Receiver<()>,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    info!("control socket listening at {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("server loop shutting down");
                break;
            }
            accept_result = listener.accept() => {
                let (stream, _) = accept_result?;
                let state = Arc::clone(&state);
                let shutdown_tx = shutdown_tx.clone();
                task::spawn(async move {
                    if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                        warn!("client handler error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<DaemonState>>,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: Command = match serde_json::from_str(line.trim()) {
        Ok(c) => c,
        Err(e) => {
            let resp = Response::Error {
                message: format!("invalid command: {e}"),
            };
            write_response(&mut writer, &resp).await?;
            return Ok(());
        }
    };

    match cmd {
        Command::Status => {
            let snapshot = {
                let guard = state.read().await;
                guard.latest.clone()
            };
            write_response(&mut writer, &Response::Status { snapshot }).await?;
        }
        Command::Top => {
            let processes = {
                let guard = state.read().await;
                guard.latest
                    .as_ref()
                    .map(|s| s.top_processes.clone())
                    .unwrap_or_default()
            };
            write_response(&mut writer, &Response::Top { processes }).await?;
        }
        Command::Shutdown => {
            let _ = shutdown_tx.send(());
            write_response(
                &mut writer,
                &Response::Ack {
                    message: "shutdown initiated".to_string(),
                },
            )
            .await?;
        }
    }

    Ok(())
}

async fn write_response<W>(writer: &mut W, resp: &Response) -> Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let payload = serde_json::to_vec(resp)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}
