use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::sys::resource::{setpriority, Which};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, Instant};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};
use thiserror::Error;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time;
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const PROCESS_TOP_N: usize = 20;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_secs: u64,
    process_top_n: usize,
    memory_alert_percent: f32,
    cpu_alert_percent: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_secs: SAMPLE_INTERVAL_SECS,
            process_top_n: PROCESS_TOP_N,
            memory_alert_percent: 90.0,
            cpu_alert_percent: 95.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SystemSnapshot {
    timestamp_unix_ms: u128,
    uptime_secs: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    used_memory_percent: f32,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    global_cpu_percent: f32,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<SystemSnapshot>,
    last_updated: Option<Instant>,
    alerts: Vec<String>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetSnapshot,
    GetAlerts,
    KillProcess { pid: i32, signal: Option<i32> },
    ReniceProcess { pid: i32, priority: i32 },
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok {
        message: String,
        snapshot: Option<SystemSnapshot>,
        alerts: Option<Vec<String>>,
    },
    Error {
        message: String,
    },
    Pong,
}

#[derive(Debug, Error)]
enum DaemonError {
    #[error("invalid signal: {0}")]
    InvalidSignal(i32),
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,osd=debug".to_string()),
        )
        .init();

    let config = Config::default();
    let state: State = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let monitor_config = config.clone();
    tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_config).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove existing socket at {SOCKET_PATH}"))?;
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket at {SOCKET_PATH}"))?;

    info!("daemon listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handling error: {e:#}");
            }
        });
    }
}

async fn monitor_loop(state: State, config: Config) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    let mut interval = time::interval(Duration::from_secs(config.sample_interval_secs));

    loop {
        interval.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let load = System::load_average();
        let total_memory = sys.total_memory();
        let used_memory = sys.used_memory();
        let total_swap = sys.total_swap();
        let used_swap = sys.used_swap();
        let global_cpu = sys.global_cpu_info().cpu_usage();

        let used_memory_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let mut disks = Vec::new();
        for d in sys.disks() {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            disks.push(DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            });
        }

        let mut processes: Vec<ProcessInfo> = sys
            .processes()
            .iter()
            .map(|(pid, p)| ProcessInfo {
                pid: pid.as_u32() as i32,
                name: p.name().to_string(),
                cpu_percent: p.cpu_usage(),
                memory_bytes: p.memory(),
                virtual_memory_bytes: p.virtual_memory(),
                status: format!("{:?}", p.status()),
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
        });
        processes.truncate(config.process_top_n);

        let snapshot = SystemSnapshot {
            timestamp_unix_ms: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_millis(),
            uptime_secs: System::uptime(),
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            total_memory_bytes: total_memory,
            used_memory_bytes: used_memory,
            used_memory_percent,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            global_cpu_percent: global_cpu,
            disks,
            top_processes: processes,
        };

        let mut alerts = Vec::new();
        if snapshot.used_memory_percent >= config.memory_alert_percent {
            alerts.push(format!(
                "high memory usage: {:.2}%",
                snapshot.used_memory_percent
            ));
        }
        if snapshot.global_cpu_percent >= config.cpu_alert_percent {
            alerts.push(format!(
                "high cpu usage: {:.2}%",
                snapshot.global_cpu_percent
            ));
        }
        for d in &snapshot.disks {
            if d.used_percent >= 95.0 {
                alerts.push(format!(
                    "disk nearly full: {} mounted on {} at {:.2}%",
                    d.name, d.mount_point, d.used_percent
                ));
            }
        }

        {
            let mut guard = state.write().await;
            guard.latest = Some(snapshot);
            guard.last_updated = Some(Instant::now());
            guard.alerts = alerts;
        }
    }
}

async fn handle_client(stream: UnixStream, state: State) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let req: Request = match serde_json::from_str(line.trim()) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid request: {e}"),
                };
                let payload = serde_json::to_vec(&resp)?;
                writer.write_all(&payload).await?;
                writer.write_all(b"\n").await?;
                continue;
            }
        };

        let resp = process_request(req, &state).await;
        let payload = serde_json::to_vec(&resp)?;
        writer.write_all(&payload).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_request(req: Request, state: &State) -> Response {
    match req {
        Request::GetSnapshot => {
            let guard = state.read().await;
            Response::Ok {
                message: "snapshot retrieved".to_string(),
                snapshot: guard.latest.clone(),
                alerts: None,
            }
        }
        Request::GetAlerts => {
            let guard = state.read().await;
            Response::Ok {
                message: "alerts retrieved".to_string(),
                snapshot: None,
                alerts: Some(guard.alerts.clone()),
            }
        }
        Request::KillProcess { pid, signal } => {
            let sig_num = signal.unwrap_or(15);
            match signal_from_i32(sig_num)
                .and_then(|sig| kill(Pid::from_raw(pid), sig).map_err(anyhow::Error::from))
            {
                Ok(_) => Response::Ok {
                    message: format!("signal {} sent to pid {}", sig_num, pid),
                    snapshot: None,
                    alerts: None,
                },
                Err(e) => Response::Error {
                    message: format!("failed to kill process: {e}"),
                },
            }
        }
        Request::ReniceProcess { pid, priority } => {
            match setpriority(Which::PRIO_PROCESS, pid as u32, priority) {
                Ok(_) => Response::Ok {
                    message: format!("set priority {} for pid {}", priority, pid),
                    snapshot: None,
                    alerts: None,
                },
                Err(e) => Response::Error {
                    message: format!("failed to renice process: {e}"),
                },
            }
        }
        Request::Ping => Response::Pong,
    }
}

fn signal_from_i32(sig: i32) -> Result<Signal> {
    Signal::try_from(sig).map_err(|_| DaemonError::InvalidSignal(sig).into())
}
