use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{Disks, Pid as SysPid, ProcessesToUpdate, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::{broadcast, RwLock};
use tokio::time;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    polling: PollingConfig,
    thresholds: ThresholdConfig,
    actions: ActionConfig,
    control: ControlConfig,
}

#[derive(Debug, Clone, Deserialize)]
struct PollingConfig {
    interval_ms: u64,
}

#[derive(Debug, Clone, Deserialize)]
struct ThresholdConfig {
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
    process_cpu_percent: f32,
    process_memory_mb: u64,
}

#[derive(Debug, Clone, Deserialize)]
struct ActionConfig {
    enable_kill_runaway_process: bool,
    enable_restart_service: bool,
    service_name: String,
}

#[derive(Debug, Clone, Deserialize)]
struct ControlConfig {
    socket_path: String,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_mb: u64,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    cpu_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    memory_percent: f32,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<MetricsSnapshot>,
    config: Option<Config>,
    alerts: Vec<String>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config.toml".to_string());

    let config = load_config(&config_path)?;
    let state = Arc::new(RwLock::new(SharedState {
        latest: None,
        config: Some(config.clone()),
        alerts: Vec::new(),
    }));

    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let monitor_state = Arc::clone(&state);
    let monitor_shutdown = shutdown_tx.subscribe();
    let monitor_config_path = config_path.clone();
    let monitor_handle = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_shutdown, monitor_config_path).await {
            error!(error = %e, "monitor loop failed");
        }
    });

    let control_state = Arc::clone(&state);
    let control_shutdown = shutdown_tx.subscribe();
    let control_handle = tokio::spawn(async move {
        if let Err(e) = control_server(control_state, control_shutdown).await {
            error!(error = %e, "control server failed");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl_c, shutting down");
        }
        _ = wait_for_sigterm() => {
            info!("received SIGTERM, shutting down");
        }
    }

    let _ = shutdown_tx.send(());
    let _ = monitor_handle.await;
    let _ = control_handle.await;

    info!("shutdown complete");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

fn load_config(path: &str) -> Result<Config> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path))?;
    let cfg = toml::from_str::<Config>(&content)
        .with_context(|| format!("failed to parse config file: {}", path))?;
    Ok(cfg)
}

async fn wait_for_sigterm() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        if let Ok(mut sigterm) = signal(SignalKind::terminate()) {
            let _ = sigterm.recv().await;
        }
    }
    #[cfg(not(unix))]
    {
        futures::future::pending::<()>().await;
    }
}

async fn monitor_loop(
    state: Arc<RwLock<SharedState>>,
    mut shutdown: broadcast::Receiver<()>,
    config_path: String,
) -> Result<()> {
    let mut system = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    let interval_ms = {
        let s = state.read().await;
        s.config
            .as_ref()
            .map(|c| c.polling.interval_ms)
            .unwrap_or(2000)
    };

    let mut ticker = time::interval(Duration::from_millis(interval_ms));

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("monitor loop stopping");
                break;
            }
            _ = ticker.tick() => {
                let cfg = {
                    let s = state.read().await;
                    s.config.clone().context("missing config in shared state")?
                };

                system.refresh_cpu_usage();
                system.refresh_memory();
                system.refresh_processes(ProcessesToUpdate::All, true);
                disks.refresh();

                let snapshot = collect_metrics(&system, &disks);
                let alerts = evaluate_policy(&snapshot, &cfg);

                if !alerts.is_empty() {
                    for alert in &alerts {
                        warn!(alert = %alert, "policy alert");
                    }
                }

                apply_actions(&snapshot, &cfg).await;

                {
                    let mut s = state.write().await;
                    s.latest = Some(snapshot);
                    s.alerts = alerts;
                }

                if let Ok(new_cfg) = load_config(&config_path) {
                    let mut s = state.write().await;
                    s.config = Some(new_cfg);
                }
            }
        }
    }

    Ok(())
}

fn collect_metrics(system: &System, disks: &Disks) -> MetricsSnapshot {
    let cpu_percent = system.global_cpu_info().cpu_usage();

    let memory_total_bytes = system.total_memory() * 1024;
    let memory_used_bytes = system.used_memory() * 1024;
    let memory_percent = if memory_total_bytes > 0 {
        (memory_used_bytes as f64 / memory_total_bytes as f64 * 100.0) as f32
    } else {
        0.0
    };

    let mut disk_snaps = Vec::new();
    for d in disks.list() {
        let total = d.total_space();
        let avail = d.available_space();
        let used_percent = if total > 0 {
            ((total - avail) as f64 / total as f64 * 100.0) as f32
        } else {
            0.0
        };

        disk_snaps.push(DiskSnapshot {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_bytes: total,
            available_bytes: avail,
            used_percent,
        });
    }

    let mut procs: Vec<ProcessSnapshot> = system
        .processes()
        .iter()
        .map(|(pid, p)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_percent: p.cpu_usage(),
            memory_mb: (p.memory() * 1024) / (1024 * 1024),
        })
        .collect();

    procs.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.memory_mb.cmp(&a.memory_mb))
    });
    procs.truncate(10);

    MetricsSnapshot {
        timestamp_unix: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs(),
        cpu_percent,
        memory_used_bytes,
        memory_total_bytes,
        memory_percent,
        disks: disk_snaps,
        top_processes: procs,
    }
}

fn evaluate_policy(snapshot: &MetricsSnapshot, cfg: &Config) -> Vec<String> {
    let mut alerts = Vec::new();

    if snapshot.cpu_percent >= cfg.thresholds.cpu_percent {
        alerts.push(format!(
            "high CPU usage: {:.2}% >= {:.2}%",
            snapshot.cpu_percent, cfg.thresholds.cpu_percent
        ));
    }

    if snapshot.memory_percent >= cfg.thresholds.memory_percent {
        alerts.push(format!(
            "high memory usage: {:.2}% >= {:.2}%",
            snapshot.memory_percent, cfg.thresholds.memory_percent
        ));
    }

    for d in &snapshot.disks {
        if d.used_percent >= cfg.thresholds.disk_percent {
            alerts.push(format!(
                "disk nearly full on {}: {:.2}% >= {:.2}%",
                d.mount_point, d.used_percent, cfg.thresholds.disk_percent
            ));
        }
    }

    for p in &snapshot.top_processes {
        if p.cpu_percent >= cfg.thresholds.process_cpu_percent {
            alerts.push(format!(
                "runaway process CPU pid={} name={} cpu={:.2}%",
                p.pid, p.name, p.cpu_percent
            ));
        }
        if p.memory_mb >= cfg.thresholds.process_memory_mb {
            alerts.push(format!(
                "runaway process memory pid={} name={} mem={}MB",
                p.pid, p.name, p.memory_mb
            ));
        }
    }

    alerts
}

async fn apply_actions(snapshot: &MetricsSnapshot, cfg: &Config) {
    if cfg.actions.enable_kill_runaway_process {
        for p in &snapshot.top_processes {
            if p.cpu_percent >= cfg.thresholds.process_cpu_percent
                || p.memory_mb >= cfg.thresholds.process_memory_mb
            {
                warn!(pid = p.pid, name = %p.name, "killing runaway process");
                if let Err(e) = kill_process(p.pid) {
                    error!(pid = p.pid, error = %e, "failed to kill process");
                }
                break;
            }
        }
    }

    if cfg.actions.enable_restart_service
        && (snapshot.cpu_percent >= cfg.thresholds.cpu_percent
            || snapshot.memory_percent >= cfg.thresholds.memory_percent)
    {
        warn!(service = %cfg.actions.service_name, "restarting service due to threshold breach");
        if let Err(e) = restart_service(&cfg.actions.service_name).await {
            error!(service = %cfg.actions.service_name, error = %e, "failed to restart service");
        }
    }
}

fn kill_process(pid: i32) -> Result<()> {
    kill(Pid::from_raw(pid), Signal::SIGKILL)
        .with_context(|| format!("failed to SIGKILL pid {}", pid))?;
    Ok(())
}

async fn restart_service(service: &str) -> Result<()> {
    let status = tokio::process::Command::new("systemctl")
        .arg("restart")
        .arg(service)
        .status()
        .await
        .with_context(|| format!("failed to execute systemctl restart {}", service))?;

    if !status.success() {
        anyhow::bail!("systemctl restart {} exited with {}", service, status);
    }

    Ok(())
}

async fn control_server(
    state: Arc<RwLock<SharedState>>,
    mut shutdown: broadcast::Receiver<()>,
) -> Result<()> {
    let socket_path = {
        let s = state.read().await;
        s.config
            .as_ref()
            .map(|c| c.control.socket_path.clone())
            .unwrap_or_else(|| "/tmp/sysguardian.sock".to_string())
    };

    if Path::new(&socket_path).exists() {
        fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove stale socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket {}", socket_path))?;

    info!(socket = %socket_path, "control socket listening");

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("control server stopping");
                let _ = fs::remove_file(&socket_path);
                break;
            }
            accept_result = listener.accept() => {
                match accept_result {
                    Ok((stream, _addr)) => {
                        let st = Arc::clone(&state);
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, st).await {
                                error!(error = %e, "client handler failed");
                            }
                        });
                    }
                    Err(e) => {
                        error!(error = %e, "accept failed");
                    }
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer.write_all(b"sysguardian ready\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "status" => {
                let s = state.read().await;
                let payload = serde_json::to_string_pretty(&serde_json::json!({
                    "latest": s.latest,
                    "alerts": s.alerts,
                }))?;
                writer.write_all(payload.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "top" => {
                let s = state.read().await;
                let payload = if let Some(latest) = &s.latest {
                    serde_json::to_string_pretty(&latest.top_processes)?
                } else {
                    "[]".to_string()
                };
                writer.write_all(payload.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "reload" => {
                writer.write_all(b"{\"status\":\"reload is automatic on each poll\"}\n").await?;
            }
            "shutdown" => {
                writer.write_all(b"{\"status\":\"shutdown command acknowledged; terminate externally or extend handler\"}\n").await?;
            }
            "help" => {
                writer
                    .write_all(b"commands: status, top, reload, shutdown, help\n")
                    .await?;
            }
            _ => {
                writer.write_all(b"{\"error\":\"unknown command\"}\n").await?;
            }
        }
    }

    Ok(())
}
