use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};

use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use nix::sys::resource::{setpriority, Which, PriorityWhich};
use serde::{Deserialize, Serialize};
use sysinfo::{Pid, ProcessRefreshKind, RefreshKind, System};
use tokio::sync::RwLock;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_alert_percent: f32,
    mem_alert_percent: f32,
    top_n_processes: usize,
    allow_renice: bool,
    renice_threshold_cpu: f32,
    renice_nice_value: i32,
    bind_addr: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_alert_percent: 90.0,
            mem_alert_percent: 90.0,
            top_n_processes: 10,
            allow_renice: false,
            renice_threshold_cpu: 95.0,
            renice_nice_value: 10,
            bind_addr: "127.0.0.1:8080".to_string(),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
    nice: i32,
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    memory_percent: f32,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    swap_percent: f32,
    cpu_percent: f32,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    uptime_seconds: u64,
    top_processes: Vec<ProcessInfo>,
    timestamp_unix_ms: u128,
}

#[derive(Clone)]
struct AppState {
    snapshot: Arc<RwLock<SystemSnapshot>>,
    config: Arc<Config>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG").unwrap_or_else(|_| "info,resourced=debug".to_string()),
        )
        .init();

    let config = Arc::new(Config::default());

    let initial = SystemSnapshot {
        total_memory_bytes: 0,
        used_memory_bytes: 0,
        memory_percent: 0.0,
        total_swap_bytes: 0,
        used_swap_bytes: 0,
        swap_percent: 0.0,
        cpu_percent: 0.0,
        loadavg_one: 0.0,
        loadavg_five: 0.0,
        loadavg_fifteen: 0.0,
        uptime_seconds: 0,
        top_processes: vec![],
        timestamp_unix_ms: now_ms(),
    };

    let state = AppState {
        snapshot: Arc::new(RwLock::new(initial)),
        config: config.clone(),
    };

    let monitor_state = state.clone();
    tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop exited: {e:?}");
        }
    });

    let app = Router::new()
        .route("/healthz", get(healthz))
        .route("/metrics", get(get_metrics))
        .with_state(state.clone());

    let addr: SocketAddr = config.bind_addr.parse()?;
    info!("starting API on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

async fn healthz() -> impl IntoResponse {
    "ok"
}

async fn get_metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.snapshot.read().await.clone();
    Json(snapshot)
}

async fn monitor_loop(state: AppState) -> anyhow::Result<()> {
    let refresh = RefreshKind::new()
        .with_memory()
        .with_cpu()
        .with_processes(ProcessRefreshKind::new().with_cpu().with_memory());

    let mut sys = System::new_with_specifics(refresh);

    loop {
        sys.refresh_memory();
        sys.refresh_cpu();
        sys.refresh_processes_specifics(ProcessRefreshKind::new().with_cpu().with_memory());

        let total_memory = sys.total_memory() * 1024;
        let used_memory = sys.used_memory() * 1024;
        let total_swap = sys.total_swap() * 1024;
        let used_swap = sys.used_swap() * 1024;

        let memory_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let swap_percent = if total_swap > 0 {
            (used_swap as f32 / total_swap as f32) * 100.0
        } else {
            0.0
        };

        let cpu_percent = sys.global_cpu_info().cpu_usage();
        let load = System::load_average();
        let uptime = System::uptime();

        let mut processes: Vec<ProcessInfo> = sys
            .processes()
            .iter()
            .map(|(pid, p)| ProcessInfo {
                pid: pid.as_u32(),
                name: p.name().to_string(),
                cpu_percent: p.cpu_usage(),
                memory_bytes: p.memory() * 1024,
                status: format!("{:?}", p.status()),
                nice: 0,
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        let top_processes = processes
            .into_iter()
            .take(state.config.top_n_processes)
            .collect::<Vec<_>>();

        let snapshot = SystemSnapshot {
            total_memory_bytes: total_memory,
            used_memory_bytes: used_memory,
            memory_percent,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            swap_percent,
            cpu_percent,
            loadavg_one: load.one,
            loadavg_five: load.five,
            loadavg_fifteen: load.fifteen,
            uptime_seconds: uptime,
            top_processes: top_processes.clone(),
            timestamp_unix_ms: now_ms(),
        };

        {
            let mut guard = state.snapshot.write().await;
            *guard = snapshot.clone();
        }

        evaluate_policies(&state, &snapshot).await;

        tokio::time::sleep(Duration::from_millis(state.config.sample_interval_ms)).await;
    }
}

async fn evaluate_policies(state: &AppState, snapshot: &SystemSnapshot) {
    if snapshot.cpu_percent >= state.config.cpu_alert_percent {
        warn!("high CPU usage: {:.2}%", snapshot.cpu_percent);
    }

    if snapshot.memory_percent >= state.config.mem_alert_percent {
        warn!("high memory usage: {:.2}%", snapshot.memory_percent);
    }

    if state.config.allow_renice {
        for proc in &snapshot.top_processes {
            if proc.cpu_percent >= state.config.renice_threshold_cpu {
                match renice_process(proc.pid, state.config.renice_nice_value) {
                    Ok(_) => warn!(
                        "reniced pid={} name={} cpu={:.2}% to nice={}",
                        proc.pid, proc.name, proc.cpu_percent, state.config.renice_nice_value
                    ),
                    Err(e) => error!(
                        "failed to renice pid={} name={}: {:?}",
                        proc.pid, proc.name, e
                    ),
                }
            }
        }
    }
}

fn renice_process(pid: u32, nice: i32) -> anyhow::Result<()> {
    setpriority(
        PriorityWhich::PRIO_PROCESS,
        pid as u32,
        nice,
    )?;
    Ok(())
}

fn now_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
