```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::Deserialize;
use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::time::{Duration, Instant};
use tokio::signal;
use tokio::time;
use tracing::{debug, error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    interval_ms: u64,
    cpu_alert_percent: f64,
    memory_alert_percent: f64,
    disk_alert_percent: f64,
    process_memory_limit_mb: u64,
    process_cpu_limit_percent: f64,
    kill_violators: bool,
    monitored_mounts: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            interval_ms: 2000,
            cpu_alert_percent: 90.0,
            memory_alert_percent: 90.0,
            disk_alert_percent: 90.0,
            process_memory_limit_mb: 1024,
            process_cpu_limit_percent: 80.0,
            kill_violators: false,
            monitored_mounts: vec!["/".to_string()],
        }
    }
}

#[derive(Debug, Clone)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_all(&self) -> u64 {
        self.idle + self.iowait
    }
}

#[derive(Debug)]
struct SystemSnapshot {
    cpu_usage_percent: f64,
    mem_usage_percent: f64,
    loadavg_1: f64,
    loadavg_5: f64,
    loadavg_15: f64,
    disks: Vec<DiskUsage>,
    processes: Vec<ProcessInfo>,
}

#[derive(Debug)]
struct DiskUsage {
    mount: String,
    total_bytes: u64,
    available_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone)]
struct ProcessInfo {
    pid: i32,
    name: String,
    rss_bytes: u64,
    cpu_percent: f64,
}

#[derive(Debug, Clone)]
struct ProcSample {
    total_time_ticks: u64,
    rss_pages: u64,
    comm: String,
}

struct DaemonState {
    prev_cpu: Option<CpuTimes>,
    prev_proc: HashMap<i32, ProcSample>,
    clk_tck: u64,
    page_size: u64,
    num_cpus: usize,
}

impl DaemonState {
    fn new() -> Result<Self> {
        let clk_tck = get_clk_tck()?;
        let page_size = get_page_size()?;
        let num_cpus = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1);

        Ok(Self {
            prev_cpu: None,
            prev_proc: HashMap::new(),
            clk_tck,
            page_size,
            num_cpus,
        })
    }
}

fn load_config(path: &str) -> Result<Config> {
    if !Path::new(path).exists() {
        warn!("config file not found at {}, using defaults", path);
        return Ok(Config::default());
    }

    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file {}", path))?;
    let cfg: Config = toml::from_str(&content)
        .with_context(|| format!("failed to parse config file {}", path))?;
    Ok(cfg)
}

fn read_cpu_times() -> Result<CpuTimes> {
    let stat = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let first = stat.lines().next().context("missing cpu line in /proc/stat")?;
    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 8 || parts[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat cpu format");
    }

    Ok(CpuTimes {
        user: parts[1].parse()?,
        nice: parts[2].parse()?,
        system: parts[3].parse()?,
        idle: parts[4].parse()?,
        iowait: parts[5].parse().unwrap_or(0),
        irq: parts[6].parse().unwrap_or(0),
        softirq: parts[7].parse().unwrap_or(0),
        steal: parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0),
    })
}

fn cpu_usage_percent(prev: &CpuTimes, curr: &CpuTimes) -> f64 {
    let prev_total = prev.total();
    let curr_total = curr.total();
    let totald = curr_total.saturating_sub(prev_total) as f64;

    let prev_idle = prev.idle_all();
    let curr_idle = curr.idle_all();
    let idled = curr_idle.saturating_sub(prev_idle) as f64;

    if totald <= 0.0 {
        0.0
    } else {
        ((totald - idled) / totald) * 100.0
    }
}

fn read_mem_usage_percent() -> Result<f64> {
    let meminfo = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut total_kb = 0u64;
    let mut available_kb = 0u64;

    for line in meminfo.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line
                .split_whitespace()
                .nth(1)
                .context("MemTotal parse")?
                .parse()?;
        } else if line.starts_with("MemAvailable:") {
            available_kb = line
                .split_whitespace()
                .nth(1)
                .context("MemAvailable parse")?
                .parse()?;
        }
    }

    if total_kb == 0 {
        anyhow::bail!("MemTotal is zero");
    }

    let used = total_kb.saturating_sub(available_kb);
    Ok((used as f64 / total_kb as f64) * 100.0)
}

fn read_loadavg() -> Result<(f64, f64, f64)> {
    let s = fs::read_to_string("/proc/loadavg").context("reading /proc/loadavg")?;
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }
    Ok((parts[0].parse()?, parts[1].parse()?, parts[2].parse()?))
}

fn read_disk_usage(mount: &str) -> Result<DiskUsage> {
    use std::process::Command;

    let output = Command::new("stat")
        .args(["-f", "-c", "%S %b %a", mount])
        .output()
        .with_context(|| format!("running stat for mount {}", mount))?;

    if !output.status.success() {
        anyhow::bail!("stat failed for mount {}", mount);
    }

    let stdout = String::from_utf8(output.stdout)?;
    let parts: Vec<&str> = stdout.split_whitespace().collect();
    if parts.len() != 3 {
        anyhow::bail!("unexpected stat output for mount {}", mount);
    }

    let block_size: u64 = parts[0].parse()?;
    let total_blocks: u64 = parts[1].parse()?;
    let avail_blocks: u64 = parts[2].parse()?;

    let total_bytes = block_size.saturating_mul(total_blocks);
    let available_bytes = block_size.saturating_mul(avail_blocks);
    let used_bytes = total_bytes.saturating_sub(available_bytes);
    let used_percent = if total_bytes == 0 {
        0.0
    } else {
        (used_bytes as f64 / total_bytes as f64) * 100.0
    };

    Ok(DiskUsage {
        mount: mount.to_string(),
        total_bytes,
        available_bytes,
        used_percent,
    })
}

fn get_clk_tck() -> Result<u64> {
    use std::process::Command;
    let output = Command::new("getconf")
        .arg("CLK_TCK")
        .output()
        .context("running getconf CLK_TCK")?;
    if !output.status.success() {
        anyhow::bail!("getconf CLK_TCK failed");
    }
    Ok(String::from_utf8(output.stdout)?.trim().parse()?)
}

fn get_page_size() -> Result<u64> {
    use std::process::Command;
    let output = Command::new("getconf")
        .arg("PAGESIZE")
        .output()
        .context("running getconf PAGESIZE")?;
    if !output.status.success() {
        anyhow::bail!("getconf PAGESIZE failed");
    }
    Ok(String::from_utf8(output.stdout)?.trim().parse()?)
}

fn read_process_sample(pid: i32) -> Result<ProcSample> {
    let stat_path = format!("/proc/{}/stat", pid);
    let content = fs::read_to_string(&stat_path)
        .with_context(|| format!("reading {}", stat_path))?;

    let open = content.find('(').context("proc stat missing '('")?;
    let close = content.rfind(')').context("proc stat missing ')'")?;
    let comm = content[open + 1..close].to_string();

    let rest = content[close + 2..].split_whitespace().collect::<Vec<_>>();
    if rest.len() < 22 {
        anyhow::bail!("unexpected /proc/{}/stat format", pid);
    }

    let utime: u64 = rest[11].parse()?;
    let stime: u64 = rest[12].parse()?;
    let rss_pages_i64: i64 = rest[21].parse()?;
    let rss_pages = rss_pages_i64.max(0) as u64;

    Ok(ProcSample {
        total_time_ticks: utime + stime,
        rss_pages,
        comm,
    })
}

fn list_pids() -> Result<Vec<i32>> {
    let mut pids = Vec::new();
    for entry in fs::read_dir("/proc").context("reading /proc")? {
        let entry = entry?;
        let name = entry.file_name();
        let s = name.to_string_lossy();
        if let Ok(pid) = s.parse::<i32>() {
            pids.push(pid);
        }
    }
    Ok(pids)
}

fn collect_processes(state: &mut DaemonState, interval: Duration) -> Result<Vec<ProcessInfo>> {
    let pids = list_pids()?;
    let mut current = HashMap::new();
    let mut processes = Vec::with_capacity(pids.len());

    let interval_secs = interval.as_secs_f64();

    for pid in pids {
        let sample = match read_process_sample(pid) {
            Ok(s) => s,
            Err(_) => continue,
        };

        let cpu_percent = if let Some(prev) = state.prev_proc.get(&pid) {
            let delta_ticks = sample
                .total_time_ticks
                .saturating_sub(prev.total_time_ticks) as f64;
            let cpu_seconds = delta_ticks / state.clk_tck as f64;
            (cpu_seconds / interval_secs) * 100.0 / state.num_cpus as f64 * state.num_cpus as f64
        } else {
            0.0
        };

        let rss_bytes = sample.rss_pages.saturating_mul(state.page_size);

        processes.push(ProcessInfo {
            pid,
            name: sample.comm.clone(),
            rss_bytes,
            cpu_percent,
        });

        current.insert(pid, sample);
    }

    state.prev_proc = current;
    Ok(processes)
}

fn collect_snapshot(state: &mut DaemonState, cfg: &Config, interval: Duration) -> Result<SystemSnapshot> {
    let curr_cpu = read_cpu_times()?;
    let cpu_usage = if let Some(prev) = &state.prev_cpu {
        cpu_usage_percent(prev, &curr_cpu)
    } else {
        0.0
    };
    state.prev_cpu = Some(curr_cpu);

    let mem_usage = read_mem_usage_percent()?;
    let (l1, l5, l15) = read_loadavg()?;

    let mut disks = Vec::new();
    for mount in &cfg.monitored_mounts {
        match read_disk_usage(mount) {
            Ok(d) => disks.push(d),
            Err(e) => warn!("disk usage read failed for {}: {}", mount, e),
        }
    }

    let processes = collect_processes(state, interval)?;

    Ok(SystemSnapshot {
        cpu_usage_percent: cpu_usage,
        mem_usage_percent: mem_usage,
        loadavg_1: l1,
        loadavg_5: l5,
        loadavg_15: l15,
        disks,
        processes,
    })
}

fn apply_policies(snapshot: &SystemSnapshot, cfg: &Config) {
    if snapshot.cpu_usage_percent >= cfg.cpu_alert_percent {
        warn!(
            "high cpu usage detected: {:.2}% (threshold {:.2}%)",
            snapshot.cpu_usage_percent, cfg.cpu_alert_percent
        );
    }

    if snapshot.mem_usage_percent >= cfg.memory_alert_percent {
        warn!(
            "high memory usage detected: {:.2}% (threshold {:.2}%)",
            snapshot.mem_usage_percent, cfg.memory_alert_percent
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= cfg.disk_alert_percent {
            warn!(
                "high disk usage on {}: {:.2}% (threshold {:.2}%)",
                disk.mount, disk.used_percent, cfg.disk_alert_percent
            );
        }
    }

    let mem_limit_bytes = cfg.process_memory_limit_mb.saturating_mul(1024 * 1024);

    for proc in &snapshot.processes {
        let mem_violation = proc.rss_bytes >= mem_limit_bytes;
        let cpu_violation = proc.cpu_percent >= cfg.process_cpu_limit_percent;

        if mem_violation || cpu_violation {
            warn!(
                "process violation pid={} name={} rss_mb={:.2} cpu={:.2}%",
                proc.pid,
                proc.name,
                proc.rss_bytes as f64 / (1024.0 * 1024.0),
                proc.cpu_percent
            );

            if cfg.kill_violators {
                match kill(Pid::from_raw(proc.pid), Signal::SIGTERM) {
                    Ok(_) => warn!("sent SIGTERM to pid={} name={}", proc.pid, proc.name),
                    Err(e) => error!("failed to SIGTERM pid={} name={}: {}", proc.pid, proc.name, e),
                }
            }
        }
    }
}

fn log_snapshot(snapshot: &SystemSnapshot) {
    info!(
        cpu_percent = format!("{:.2}", snapshot.cpu_usage_percent),
        mem_percent = format!("{:.2}", snapshot.mem_usage_percent),
        load1 = format!("{:.2}", snapshot.loadavg_1),
        load5 = format!("{:.2}", snapshot.loadavg_5),
        load15 = format!("{:.2}", snapshot.loadavg_15),
        proc_count = snapshot.processes.len(),
        "system snapshot"
    );

    for disk in &snapshot.disks {
        debug!(
            mount = %disk.mount,
            used_percent = format!("{:.2}", disk.used_percent),
            total_bytes = disk.total_bytes,
            available_bytes = disk.available_bytes,
            "disk snapshot"
        );
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,sysguardian=debug".to_string()),
        )
        .init();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "/etc/sysguardian.toml".to_string());

    let cfg = load_config(&config_path)?;
    info!("loaded config from {}", config_path);
    info!("config: {:?}", cfg);

    let mut state = DaemonState::new()?;
    let interval = Duration::from_millis(cfg.interval_ms);
    let mut ticker = time::interval(interval);

    info!("sysguardian started");

    let shutdown = async {
        signal::ctrl_c().await.expect("failed to install ctrl-c handler");
    };

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let started = Instant::now();
                match collect_snapshot(&mut state, &cfg, interval) {
                    Ok(snapshot) => {
                        log_snapshot(&snapshot);
                        apply_policies(&snapshot, &cfg);
                    }
                    Err(e) => error!("snapshot collection failed: {:?}", e),
                }
                debug!("iteration completed in {:?}", started.elapsed());
            }
            _ = &mut shutdown => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("sysguardian stopped");
    Ok(())
}
