use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::{broadcast, RwLock};
use tokio::time;
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const TOP_PROCESS_COUNT: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    free_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    cpu_usage_percent: f32,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
    file_system: String,
}

#[derive(Debug, Default)]
struct DaemonState {
    latest: Option<MetricsSnapshot>,
    process_index: HashMap<u32, ProcessInfo>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Status,
    Metrics,
    Processes,
    Kill { pid: u32 },
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Ok { message: String },
    Status { running: bool, socket_path: String },
    Metrics { snapshot: Option<MetricsSnapshot> },
    Processes { processes: Vec<ProcessInfo> },
    Error { message: String },
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket at {}", SOCKET_PATH))?;
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    info!("sysmond listening on {}", SOCKET_PATH);

    let state = Arc::new(RwLock::new(DaemonState::default()));
    let (shutdown_tx, _) = broadcast::channel::<()>(16);

    let monitor_handle = {
        let state = Arc::clone(&state);
        let shutdown_rx = shutdown_tx.subscribe();
        tokio::spawn(async move {
            if let Err(e) = monitor_loop(state, shutdown_rx).await {
                error!("monitor loop failed: {e:#}");
            }
        })
    };

    let server_handle = {
        let state = Arc::clone(&state);
        let shutdown_tx = shutdown_tx.clone();
        let shutdown_rx = shutdown_tx.subscribe();
        tokio::spawn(async move {
            if let Err(e) = server_loop(listener, state, shutdown_tx, shutdown_rx).await {
                error!("server loop failed: {e:#}");
            }
        })
    };

    tokio::select! {
        res = signal::ctrl_c() => {
            match res {
                Ok(()) => info!("received ctrl-c"),
                Err(e) => error!("failed waiting for ctrl-c: {e}"),
            }
        }
        _ = wait_for_sigterm() => {
            info!("received SIGTERM");
        }
    }

    let _ = shutdown_tx.send(());
    let _ = monitor_handle.await;
    let _ = server_handle.await;

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = std::fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket {}: {}", SOCKET_PATH, e);
        }
    }

    info!("sysmond shut down cleanly");
    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn wait_for_sigterm() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        if let Ok(mut sigterm) = signal(SignalKind::terminate()) {
            let _ = sigterm.recv().await;
        }
    }

    #[cfg(not(unix))]
    {
        futures::future::pending::<()>().await;
    }
}

async fn monitor_loop(
    state: Arc<RwLock<DaemonState>>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    system.refresh_all();

    let mut ticker = time::interval(SAMPLE_INTERVAL);
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = ticker.tick() => {
                system.refresh_cpu();
                system.refresh_memory();
                system.refresh_processes();
                system.refresh_disks();

                let snapshot = build_snapshot(&system);
                let process_index = snapshot
                    .top_processes
                    .iter()
                    .cloned()
                    .map(|p| (p.pid, p))
                    .collect::<HashMap<_, _>>();

                {
                    let mut guard = state.write().await;
                    guard.latest = Some(snapshot);
                    guard.process_index = process_index;
                }
            }
        }
    }

    Ok(())
}

fn build_snapshot(system: &System) -> MetricsSnapshot {
    let timestamp_unix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let disks = system
        .disks()
        .iter()
        .map(|d| DiskInfo {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space_bytes: d.total_space(),
            available_space_bytes: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).to_string(),
        })
        .collect::<Vec<_>>();

    let mut processes = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory(),
            status: format!("{:?}", proc_.status()),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    processes.truncate(TOP_PROCESS_COUNT);

    MetricsSnapshot {
        timestamp_unix,
        total_memory_bytes: system.total_memory(),
        used_memory_bytes: system.used_memory(),
        free_memory_bytes: system.free_memory(),
        total_swap_bytes: system.total_swap(),
        used_swap_bytes: system.used_swap(),
        cpu_usage_percent: system.global_cpu_info().cpu_usage(),
        disks,
        top_processes: processes,
    }
}

async fn server_loop(
    listener: UnixListener,
    state: Arc<RwLock<DaemonState>>,
    shutdown_tx: broadcast::Sender<()>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("server loop shutting down");
                break;
            }
            accept_res = listener.accept() => {
                let (stream, _) = accept_res.context("failed to accept client")?;
                let state = Arc::clone(&state);
                let shutdown_tx = shutdown_tx.clone();

                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                        warn!("client handler error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<DaemonState>>,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let response = match parse_request(line) {
            Ok(req) => process_request(req, &state, &shutdown_tx).await,
            Err(e) => Response::Error {
                message: format!("invalid request: {e}"),
            },
        };

        let payload = serde_json::to_vec(&response)?;
        writer.write_all(&payload).await?;
        writer.write_all(b"\n").await?;
        writer.flush().await?;
    }

    Ok(())
}

fn parse_request(line: &str) -> Result<Request> {
    if line.starts_with('{') {
        let req = serde_json::from_str::<Request>(line)?;
        return Ok(req);
    }

    let mut parts = line.split_whitespace();
    match parts.next() {
        Some("status") => Ok(Request::Status),
        Some("metrics") => Ok(Request::Metrics),
        Some("processes") => Ok(Request::Processes),
        Some("shutdown") => Ok(Request::Shutdown),
        Some("kill") => {
            let pid = parts
                .next()
                .context("missing pid")?
                .parse::<u32>()
                .context("invalid pid")?;
            Ok(Request::Kill { pid })
        }
        Some(other) => anyhow::bail!("unknown command: {}", other),
        None => anyhow::bail!("empty command"),
    }
}

async fn process_request(
    req: Request,
    state: &Arc<RwLock<DaemonState>>,
    shutdown_tx: &broadcast::Sender<()>,
) -> Response {
    match req {
        Request::Status => Response::Status {
            running: true,
            socket_path: SOCKET_PATH.to_string(),
        },
        Request::Metrics => {
            let guard = state.read().await;
            Response::Metrics {
                snapshot: guard.latest.clone(),
            }
        }
        Request::Processes => {
            let guard = state.read().await;
            let mut processes = guard.process_index.values().cloned().collect::<Vec<_>>();
            processes.sort_by(|a, b| {
                b.cpu_percent
                    .partial_cmp(&a.cpu_percent)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
            Response::Processes { processes }
        }
        Request::Kill { pid } => {
            match kill(Pid::from_raw(pid as i32), Signal::SIGTERM) {
                Ok(_) => Response::Ok {
                    message: format!("sent SIGTERM to pid {}", pid),
                },
                Err(e) => Response::Error {
                    message: format!("failed to kill pid {}: {}", pid, e),
                },
            }
        }
        Request::Shutdown => {
            let _ = shutdown_tx.send(());
            Response::Ok {
                message: "shutdown initiated".to_string(),
            }
        }
    }
}
