use crate::types::*;
use std::time::{SystemTime, UNIX_EPOCH};
use sysinfo::{Disks, LoadAvg, System};

pub struct MetricsCollector {
    system: System,
    disks: Disks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self { system, disks }
    }

    pub fn collect(&mut self, top_n: usize) -> SystemSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let core_count = self.system.cpus().len();

        let LoadAvg {
            one,
            five,
            fifteen,
        } = System::load_average();

        let total_mem = self.system.total_memory();
        let used_mem = self.system.used_memory();
        let free_mem = total_mem.saturating_sub(used_mem);

        let swap_total = self.system.total_swap();
        let swap_used = self.system.used_swap();

        let used_percent = if total_mem == 0 {
            0.0
        } else {
            (used_mem as f32 / total_mem as f32) * 100.0
        };

        let mut total_read = 0u64;
        let mut total_written = 0u64;
        for disk in self.disks.list() {
            let usage = disk.usage();
            total_read = total_read.saturating_add(usage.total_read_bytes);
            total_written = total_written.saturating_add(usage.total_written_bytes);
        }

        let mut processes: Vec<ProcessInfo> = self
            .system
            .processes()
            .values()
            .map(|p| ProcessInfo {
                pid: p.pid().as_u32() as i32,
                name: p.name().to_string(),
                cpu_percent: p.cpu_usage(),
                memory_bytes: p.memory(),
                status: format!("{:?}", p.status()),
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(top_n);

        let timestamp_unix_secs = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        SystemSnapshot {
            timestamp_unix_secs,
            cpu: CpuMetrics {
                usage_percent: cpu_usage,
                core_count,
                load_avg_one: one,
                load_avg_five: five,
                load_avg_fifteen: fifteen,
            },
            memory: MemoryMetrics {
                total_bytes: total_mem,
                used_bytes: used_mem,
                free_bytes: free_mem,
                used_percent,
                swap_total_bytes: swap_total,
                swap_used_bytes: swap_used,
            },
            disk: DiskMetrics {
                total_read_bytes: total_read,
                total_written_bytes: total_written,
            },
            process_count: self.system.processes().len(),
            top_processes: processes,
        }
    }
}
