use crate::types::{Alert, SystemSnapshot};

pub struct Thresholds {
    pub cpu_percent: f32,
    pub memory_percent: f32,
    pub process_count: usize,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_percent: 90.0,
            memory_percent: 90.0,
            process_count: 5000,
        }
    }
}

pub fn evaluate(snapshot: &SystemSnapshot, thresholds: &Thresholds) -> Vec<Alert> {
    let mut alerts = Vec::with_capacity(3);

    if snapshot.cpu.usage_percent >= thresholds.cpu_percent {
        alerts.push(Alert {
            severity: "warning".into(),
            message: format!(
                "CPU usage high: {:.2}% >= {:.2}%",
                snapshot.cpu.usage_percent, thresholds.cpu_percent
            ),
            timestamp_unix_secs: snapshot.timestamp_unix_secs,
        });
    }

    if snapshot.memory.used_percent >= thresholds.memory_percent {
        alerts.push(Alert {
            severity: "warning".into(),
            message: format!(
                "Memory usage high: {:.2}% >= {:.2}%",
                snapshot.memory.used_percent, thresholds.memory_percent
            ),
            timestamp_unix_secs: snapshot.timestamp_unix_secs,
        });
    }

    if snapshot.process_count >= thresholds.process_count {
        alerts.push(Alert {
            severity: "warning".into(),
            message: format!(
                "Process count high: {} >= {}",
                snapshot.process_count, thresholds.process_count
            ),
            timestamp_unix_secs: snapshot.timestamp_unix_secs,
        });
    }

    alerts
}
