```rust
use crate::commands::{Command, CommandResponse};
use crate::daemon::SharedState;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde_json::json;
use std::io;
use std::path::Path;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tracing::{error, info};

pub async fn run_control_socket<P: AsRef<Path>>(
    path: P,
    state: SharedState,
) -> io::Result<()> {
    let path = path.as_ref();

    if path.exists() {
        std::fs::remove_file(path)?;
    }

    let listener = UnixListener::bind(path)?;
    info!("control socket listening at {}", path.display());

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("control client error: {}", e);
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> io::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::with_capacity(1024);

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let response = match serde_json::from_str::<Command>(&line) {
        Ok(cmd) => execute_command(cmd, &state),
        Err(e) => CommandResponse::err(format!("invalid command: {}", e)),
    };

    let payload = serde_json::to_vec(&response)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

fn execute_command(cmd: Command, state: &SharedState) -> CommandResponse {
    match cmd {
        Command::Status => {
            let guard = state.lock();
            CommandResponse::ok("status", Some(json!(&guard.status)))
        }
        Command::Metrics => {
            let guard = state.lock();
            CommandResponse::ok("metrics", Some(json!(&guard.status.last_snapshot)))
        }
        Command::Top { count } => {
            let guard = state.lock();
            let count = count.unwrap_or(5);
            let top = guard
                .status
                .last_snapshot
                .as_ref()
                .map(|s| {
                    let mut v = s.top_processes.clone();
                    v.truncate(count);
                    v
                })
                .unwrap_or_default();
            CommandResponse::ok("top", Some(json!(top)))
        }
        Command::Kill { pid } => match kill(Pid::from_raw(pid), Signal::SIGTERM) {
            Ok(_) => CommandResponse::ok(format!("sent SIGTERM to {}", pid), None),
            Err(e) => CommandResponse::err(format!("kill failed: {}", e)),
        },
        Command::Renice { pid, nice } => {
            let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, pid as u32, nice) };
            if rc == 0 {
                CommandResponse::ok(format!("reniced {} to {}", pid, nice), None)
            } else {
                CommandResponse::err(format!(
                    "renice failed: {}",
                    std::io::Error::last_os_error()
                ))
            }
        }
    }
}
