```rust
use crate::metrics::MetricsCollector;
use crate::monitor::{evaluate, Thresholds};
use crate::types::{Alert, DaemonStatus, SystemSnapshot};
use parking_lot::Mutex;
use std::collections::VecDeque;
use std::sync::Arc;
use std::time::Duration;
use tracing::{info, warn};

pub type SharedState = Arc<Mutex<DaemonState>>;

pub struct DaemonState {
    pub status: DaemonStatus,
    pub alert_history: VecDeque<Alert>,
}

impl DaemonState {
    pub fn new(interval_ms: u64) -> Self {
        Self {
            status: DaemonStatus {
                running: true,
                interval_ms,
                last_snapshot: None,
                alerts: Vec::new(),
            },
            alert_history: VecDeque::with_capacity(256),
        }
    }

    pub fn update_snapshot(&mut self, snapshot: SystemSnapshot, alerts: Vec<Alert>) {
        self.status.last_snapshot = Some(snapshot);
        self.status.alerts = alerts.clone();

        for alert in alerts {
            if self.alert_history.len() == 256 {
                self.alert_history.pop_front();
            }
            self.alert_history.push_back(alert);
        }
    }
}

pub async fn run_monitor_loop(
    state: SharedState,
    interval: Duration,
    thresholds: Thresholds,
) {
    let mut collector = MetricsCollector::new();
    let mut ticker = tokio::time::interval(interval);

    info!("monitor loop started");

    loop {
        ticker.tick().await;

        let snapshot = collector.collect(16);
        let alerts = evaluate(&snapshot, &thresholds);

        if !alerts.is_empty() {
            for alert in &alerts {
                warn!("alert: {}", alert.message);
            }
        }

        {
            let mut guard = state.lock();
            if !guard.status.running {
                break;
            }
            guard.update_snapshot(snapshot, alerts);
        }
    }

    info!("monitor loop stopped");
}
