use crate::control::run_control_socket;
use crate::daemon::{run_monitor_loop, DaemonState, SharedState};
use crate::monitor::Thresholds;
use parking_lot::Mutex;
use std::sync::Arc;
use std::time::Duration;
use tokio::signal;
use tracing::{error, info};

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let interval_ms = 1000;
    let socket_path = "/tmp/osd.sock";

    let state: SharedState = Arc::new(Mutex::new(DaemonState::new(interval_ms)));

    let monitor_task = {
        let state = state.clone();
        tokio::spawn(async move {
            run_monitor_loop(
                state,
                Duration::from_millis(interval_ms),
                Thresholds::default(),
            )
            .await;
        })
    };

    let control_task = {
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = run_control_socket(socket_path, state).await {
                error!("control socket failed: {}", e);
            }
        })
    };

    info!("osd started");

    match signal::ctrl_c().await {
        Ok(_) => info!("shutdown signal received"),
        Err(e) => error!("signal error: {}", e),
    }

    {
        let mut guard = state.lock();
        guard.status.running = false;
    }

    monitor_task.abort();
    control_task.abort();

    let _ = std::fs::remove_file(socket_path);

    info!("osd stopped");
}
