use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{DiskExt, PidExt, ProcessExt, System, SystemExt};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time;
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const TOP_N_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp: u64,
    uptime_secs: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    cpu_usage_percent: f32,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_space: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_kb: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonStatus {
    started_at: u64,
    last_sample_at: u64,
    sample_interval_secs: u64,
    socket_path: String,
    process_count: usize,
}

#[derive(Debug, Default)]
struct SharedState {
    started_at: u64,
    last_sample_at: u64,
    latest_snapshot: Option<SystemSnapshot>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum ApiResponse {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ApiCommand {
    Status,
    Metrics,
    Processes,
    Kill { pid: i32 },
    Renice { pid: i32, nice: i32 },
    Shutdown,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove existing socket {}", SOCKET_PATH))?;
    }

    let started_at = now_epoch_secs();
    let state = Arc::new(RwLock::new(SharedState {
        started_at,
        last_sample_at: 0,
        latest_snapshot: None,
    }));

    let shutdown = Arc::new(tokio::sync::Notify::new());

    let monitor_state = state.clone();
    let monitor_shutdown = shutdown.clone();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_shutdown).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_state = state.clone();
    let server_shutdown = shutdown.clone();
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state, server_shutdown).await {
            error!("server loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = monitor_task => {
            warn!("monitor task exited");
        }
        _ = server_task => {
            warn!("server task exited");
        }
        _ = tokio::signal::ctrl_c() => {
            info!("received ctrl-c, shutting down");
        }
    }

    shutdown.notify_waiters();

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn monitor_loop(state: State, shutdown: Arc<tokio::sync::Notify>) -> Result<()> {
    let mut sys = System::new_all();
    let mut interval = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        tokio::select! {
            _ = shutdown.notified() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = interval.tick() => {
                sys.refresh_cpu();
                sys.refresh_memory();
                sys.refresh_disks_list();
                sys.refresh_disks();
                sys.refresh_processes();
                sys.refresh_system();

                let load = sys.load_average();
                let disks = sys.disks().iter().map(|d| {
                    let total = d.total_space();
                    let avail = d.available_space();
                    let used = total.saturating_sub(avail);
                    let used_percent = if total == 0 {
                        0.0
                    } else {
                        (used as f64 / total as f64) * 100.0
                    };

                    DiskSnapshot {
                        name: d.name().to_string_lossy().to_string(),
                        mount_point: d.mount_point().to_string_lossy().to_string(),
                        total_space: total,
                        available_space: avail,
                        used_space: used,
                        used_percent,
                    }
                }).collect::<Vec<_>>();

                let mut processes = sys.processes()
                    .iter()
                    .map(|(pid, p)| ProcessSnapshot {
                        pid: pid.as_u32() as i32,
                        name: p.name().to_string(),
                        cpu_percent: p.cpu_usage(),
                        memory_kb: p.memory(),
                        status: format!("{:?}", p.status()),
                    })
                    .collect::<Vec<_>>();

                processes.sort_by(|a, b| {
                    b.cpu_percent
                        .partial_cmp(&a.cpu_percent)
                        .unwrap_or(Ordering::Equal)
                        .then_with(|| b.memory_kb.cmp(&a.memory_kb))
                });
                processes.truncate(TOP_N_PROCESSES);

                let snapshot = SystemSnapshot {
                    timestamp: now_epoch_secs(),
                    uptime_secs: sys.uptime(),
                    load_avg_one: load.one,
                    load_avg_five: load.five,
                    load_avg_fifteen: load.fifteen,
                    total_memory_kb: sys.total_memory(),
                    used_memory_kb: sys.used_memory(),
                    total_swap_kb: sys.total_swap(),
                    used_swap_kb: sys.used_swap(),
                    cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
                    disks,
                    top_processes: processes,
                };

                let mut guard = state.write().await;
                guard.last_sample_at = snapshot.timestamp;
                guard.latest_snapshot = Some(snapshot);
            }
        }
    }

    Ok(())
}

async fn server_loop(state: State, shutdown: Arc<tokio::sync::Notify>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    info!("listening on {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown.notified() => {
                info!("server loop shutting down");
                break;
            }
            accept_result = listener.accept() => {
                let (stream, _) = accept_result?;
                let client_state = state.clone();
                let client_shutdown = shutdown.clone();

                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, client_state, client_shutdown).await {
                        warn!("client error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: State,
    shutdown: Arc<tokio::sync::Notify>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let bytes = reader.read_line(&mut line).await?;
    if bytes == 0 {
        return Ok(());
    }

    let response = match parse_command(&line) {
        Ok(cmd) => execute_command(cmd, state, shutdown).await,
        Err(e) => ApiResponse::Error {
            message: format!("invalid command: {e}"),
        },
    };

    let payload = serde_json::to_vec(&response)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;

    Ok(())
}

fn parse_command(line: &str) -> Result<ApiCommand> {
    let trimmed = line.trim();

    if trimmed.starts_with('{') {
        let cmd = serde_json::from_str::<ApiCommand>(trimmed)?;
        return Ok(cmd);
    }

    let parts = trimmed.split_whitespace().collect::<Vec<_>>();
    if parts.is_empty() {
        anyhow::bail!("empty command");
    }

    match parts[0] {
        "status" => Ok(ApiCommand::Status),
        "metrics" => Ok(ApiCommand::Metrics),
        "processes" => Ok(ApiCommand::Processes),
        "kill" if parts.len() == 2 => Ok(ApiCommand::Kill {
            pid: parts[1].parse()?,
        }),
        "renice" if parts.len() == 3 => Ok(ApiCommand::Renice {
            pid: parts[1].parse()?,
            nice: parts[2].parse()?,
        }),
        "shutdown" => Ok(ApiCommand::Shutdown),
        _ => anyhow::bail!("unknown command"),
    }
}

async fn execute_command(
    cmd: ApiCommand,
    state: State,
    shutdown: Arc<tokio::sync::Notify>,
) -> ApiResponse {
    match cmd {
        ApiCommand::Status => {
            let guard = state.read().await;
            let process_count = guard
                .latest_snapshot
                .as_ref()
                .map(|s| s.top_processes.len())
                .unwrap_or(0);

            let status = DaemonStatus {
                started_at: guard.started_at,
                last_sample_at: guard.last_sample_at,
                sample_interval_secs: SAMPLE_INTERVAL_SECS,
                socket_path: SOCKET_PATH.to_string(),
                process_count,
            };

            json_ok(status)
        }
        ApiCommand::Metrics => {
            let guard = state.read().await;
            match &guard.latest_snapshot {
                Some(snapshot) => json_ok(snapshot),
                None => ApiResponse::Error {
                    message: "no metrics available yet".to_string(),
                },
            }
        }
        ApiCommand::Processes => {
            let guard = state.read().await;
            match &guard.latest_snapshot {
                Some(snapshot) => json_ok(&snapshot.top_processes),
                None => ApiResponse::Error {
                    message: "no process data available yet".to_string(),
                },
            }
        }
        ApiCommand::Kill { pid } => match kill(Pid::from_raw(pid), Signal::SIGTERM) {
            Ok(_) => json_ok(serde_json::json!({
                "pid": pid,
                "signal": "SIGTERM"
            })),
            Err(e) => ApiResponse::Error {
                message: format!("failed to kill pid {}: {}", pid, e),
            },
        },
        ApiCommand::Renice { pid, nice } => match renice_process(pid, nice) {
            Ok(_) => json_ok(serde_json::json!({
                "pid": pid,
                "nice": nice
            })),
            Err(e) => ApiResponse::Error {
                message: format!("failed to renice pid {}: {}", pid, e),
            },
        },
        ApiCommand::Shutdown => {
            shutdown.notify_waiters();
            json_ok(serde_json::json!({
                "message": "shutdown initiated"
            }))
        }
    }
}

fn renice_process(pid: i32, nice: i32) -> Result<()> {
    let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, pid as u32, nice) };
    if rc != 0 {
        let err = std::io::Error::last_os_error();
        anyhow::bail!(err);
    }
    Ok(())
}

fn json_ok<T: Serialize>(value: T) -> ApiResponse {
    match serde_json::to_value(value) {
        Ok(data) => ApiResponse::Ok { data },
        Err(e) => ApiResponse::Error {
            message: format!("serialization error: {}", e),
        },
    }
}

fn now_epoch_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
