# src/monitor.rs

```rust
use crate::config::Config;
use crate::models::{CpuStats, DiskStats, MemoryStats, ProcessStats, SystemSnapshot};
use parking_lot::RwLock;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};
use sysinfo::{Disks, LoadAvg, System};
use tokio::time::{interval, MissedTickBehavior};
use tracing::{debug, error};

pub type SharedSnapshot = Arc<RwLock<SystemSnapshot>>;

pub fn initial_snapshot() -> SystemSnapshot {
    SystemSnapshot {
        timestamp_unix_ms: 0,
        cpu: CpuStats {
            usage_percent: 0.0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
        },
        memory: MemoryStats {
            total_bytes: 0,
            used_bytes: 0,
            free_bytes: 0,
            available_bytes: 0,
            used_percent: 0.0,
        },
        disks: Vec::new(),
        top_processes: Vec::new(),
    }
}

pub async fn run_monitor(config: Config, shared: SharedSnapshot) {
    let mut sys = System::new_all();
    let mut ticker = interval(config.sample_interval);
    ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);

    loop {
        ticker.tick().await;

        if let Err(e) = sample_once(&mut sys, &config, &shared) {
            error!("sampling failed: {e:#}");
        }
    }
}

fn sample_once(sys: &mut System, config: &Config, shared: &SharedSnapshot) -> anyhow::Result<()> {
    sys.refresh_memory();
    sys.refresh_cpu();
    sys.refresh_processes();
    let disks = Disks::new_with_refreshed_list();

    let load = System::load_average();
    let cpu_usage = sys.global_cpu_info().cpu_usage();

    let total_mem = sys.total_memory();
    let available_mem = sys.available_memory();
    let used_mem = total_mem.saturating_sub(available_mem);
    let free_mem = sys.free_memory();

    let memory_percent = if total_mem > 0 {
        (used_mem as f32 / total_mem as f32) * 100.0
    } else {
        0.0
    };

    let disk_stats = disks
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            DiskStats {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                used_percent,
            }
        })
        .collect::<Vec<_>>();

    let mut processes = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessStats {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_percent: p.cpu_usage(),
            memory_bytes: p.memory(),
            status: format!("{:?}", p.status()),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
    });
    processes.truncate(config.top_n_processes);

    let snapshot = SystemSnapshot {
        timestamp_unix_ms: SystemTime::now()
            .duration_since(UNIX_EPOCH)?
            .as_millis(),
        cpu: CpuStats {
            usage_percent: cpu_usage,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
        },
        memory: MemoryStats {
            total_bytes: total_mem,
            used_bytes: used_mem,
            free_bytes: free_mem,
            available_bytes: available_mem,
            used_percent: memory_percent,
        },
        disks: disk_stats,
        top_processes: processes,
    };

    {
        let mut guard = shared.write();
        *guard = snapshot;
    }

    debug!("snapshot updated");
    Ok(())
}
