# src/control.rs

```rust
use crate::actions::kill_process;
use crate::models::{ControlRequest, ControlResponse};
use crate::monitor::SharedSnapshot;
use anyhow::Result;
use tokio::fs;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tracing::{error, info};

pub async fn run_control_server(socket_path: std::path::PathBuf, shared: SharedSnapshot) -> Result<()> {
    if fs::try_exists(&socket_path).await.unwrap_or(false) {
        let _ = fs::remove_file(&socket_path).await;
    }

    let listener = UnixListener::bind(&socket_path)?;
    info!("control socket listening on {}", socket_path.display());

    loop {
        let (stream, _) = listener.accept().await?;
        let shared = shared.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, shared).await {
                error!("client error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, shared: SharedSnapshot) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let req = match serde_json::from_str::<ControlRequest>(line.trim()) {
            Ok(r) => r,
            Err(e) => {
                let resp = ControlResponse::Error {
                    message: format!("invalid request: {e}"),
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
                continue;
            }
        };

        let resp = match req {
            ControlRequest::GetSnapshot => {
                let snapshot = shared.read().clone();
                ControlResponse::OkSnapshot { snapshot }
            }
            ControlRequest::ListProcesses => {
                let processes = shared.read().top_processes.clone();
                ControlResponse::OkProcesses { processes }
            }
            ControlRequest::KillProcess { pid, signal } => match kill_process(pid, signal) {
                Ok(_) => ControlResponse::OkMessage {
                    message: format!("signal sent to pid {}", pid),
                },
                Err(e) => ControlResponse::Error {
                    message: format!("failed to signal pid {}: {}", pid, e),
                },
            },
            ControlRequest::Ping => ControlResponse::OkMessage {
                message: "pong".to_string(),
            },
        };

        writer
            .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
            .await?;
    }

    Ok(())
}
