# src/daemon.rs

```rust
use crate::config::Config;
use crate::control::run_control_server;
use crate::monitor::{initial_snapshot, run_monitor, SharedSnapshot};
use anyhow::Result;
use parking_lot::RwLock;
use std::sync::Arc;
use tracing::info;

pub struct Daemon {
    config: Config,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub async fn run(self) -> Result<()> {
        let shared: SharedSnapshot = Arc::new(RwLock::new(initial_snapshot()));

        let monitor_config = self.config.clone();
        let control_socket = self.config.socket_path.clone();

        let monitor_shared = shared.clone();
        let control_shared = shared.clone();

        let monitor_task = tokio::spawn(async move {
            run_monitor(monitor_config, monitor_shared).await;
        });

        let control_task = tokio::spawn(async move {
            run_control_server(control_socket, control_shared).await
        });

        tokio::select! {
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
            }
            res = control_task => {
                match res {
                    Ok(inner) => inner?,
                    Err(e) => return Err(e.into()),
                }
            }
        }

        monitor_task.abort();
        Ok(())
    }
}
```

