use crate::metrics::{ProcessInfo, SystemSnapshot};
use parking_lot::RwLock;
use std::sync::Arc;

#[derive(Clone)]
pub struct SharedState {
    inner: Arc<RwLock<State>>,
}

#[derive(Debug, Default)]
pub struct State {
    pub latest: Option<SystemSnapshot>,
    pub alerts: Vec<String>,
    pub top_processes: Vec<ProcessInfo>,
}

impl SharedState {
    pub fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(State::default())),
        }
    }

    pub fn update_snapshot(&self, snapshot: SystemSnapshot, top_processes: Vec<ProcessInfo>) {
        let mut state = self.inner.write();
        state.latest = Some(snapshot);
        state.top_processes = top_processes;
    }

    pub fn add_alert(&self, alert: String) {
        let mut state = self.inner.write();
        state.alerts.push(alert);
        if state.alerts.len() > 1000 {
            state.alerts.drain(0..500);
        }
    }

    pub fn snapshot_json(&self) -> serde_json::Value {
        let state = self.inner.read();
        serde_json::json!({
            "latest": state.latest,
            "top_processes": state.top_processes,
            "alerts": state.alerts,
        })
    }
}
