## `src/metrics.rs`

```rust
use serde::Serialize;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, RefreshKind, System};

#[derive(Debug, Clone, Serialize)]
pub struct SystemSnapshot {
    pub cpu_percent: f32,
    pub memory_percent: f32,
    pub disk_percent: f32,
    pub total_memory: u64,
    pub used_memory: u64,
    pub total_disk: u64,
    pub used_disk: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct ProcessInfo {
    pub pid: i32,
    pub name: String,
    pub cpu_percent: f32,
    pub memory_bytes: u64,
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything());

        let mut system = System::new_with_specifics(refresh);
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> (SystemSnapshot, Vec<ProcessInfo>) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks();

        let cpu_percent = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let memory_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0u64;
        let mut available_disk = 0u64;
        for disk in self.system.disks().iter() {
            total_disk += disk.total_space();
            available_disk += disk.available_space();
        }
        let used_disk = total_disk.saturating_sub(available_disk);
        let disk_percent = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        let snapshot = SystemSnapshot {
            cpu_percent,
            memory_percent,
            disk_percent,
            total_memory,
            used_memory,
            total_disk,
            used_disk,
        };

        let mut processes: Vec<ProcessInfo> = self
            .system
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessInfo {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_percent: proc_.cpu_usage(),
                memory_bytes: proc_.memory(),
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(10);

        (snapshot, processes)
    }

    pub fn all_processes(&self) -> Vec<(Pid, f32)> {
        self.system
            .processes()
            .iter()
            .map(|(pid, proc_)| (*pid, proc_.cpu_usage()))
            .collect()
    }
}
```

