## `src/policy.rs`

```rust
use crate::{
    config::Config,
    metrics::{MetricsCollector, SystemSnapshot},
    state::SharedState,
};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid as UnixPid;
use sysinfo::Pid;
use tracing::{info, warn};

pub fn evaluate(
    config: &Config,
    state: &SharedState,
    snapshot: &SystemSnapshot,
    collector: &MetricsCollector,
) {
    if snapshot.cpu_percent >= config.thresholds.cpu_percent {
        emit_alert(config, state, format!("High CPU usage: {:.2}%", snapshot.cpu_percent));
    }

    if snapshot.memory_percent >= config.thresholds.memory_percent {
        emit_alert(
            config,
            state,
            format!("High memory usage: {:.2}%", snapshot.memory_percent),
        );
    }

    if snapshot.disk_percent >= config.thresholds.disk_percent {
        emit_alert(
            config,
            state,
            format!("High disk usage: {:.2}%", snapshot.disk_percent),
        );
    }

    if config.actions.kill_high_cpu_processes {
        for (pid, cpu) in collector.all_processes() {
            if cpu >= config.thresholds.process_cpu_percent {
                if let Err(e) = terminate_process(pid) {
                    warn!("failed to kill pid {:?}: {}", pid, e);
                } else {
                    emit_alert(
                        config,
                        state,
                        format!("Killed process {:?} for CPU {:.2}%", pid, cpu),
                    );
                }
            }
        }
    }
}

fn emit_alert(config: &Config, state: &SharedState, msg: String) {
    if config.actions.log_alerts {
        warn!("{}", msg);
    } else {
        info!("{}", msg);
    }
    state.add_alert(msg);
}

fn terminate_process(pid: Pid) -> anyhow::Result<()> {
    let raw = pid.as_u32() as i32;
    kill(UnixPid::from_raw(raw), Signal::SIGKILL)?;
    Ok(())
}
