## `src/server.rs`

```rust
use crate::state::SharedState;
use anyhow::Context;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{error, info};

pub async fn run_server(socket_path: &str, state: SharedState) -> anyhow::Result<()> {
    let _ = std::fs::remove_file(socket_path);
    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("failed to bind socket at {}", socket_path))?;

    info!("control socket listening at {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client error: {}", e);
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> anyhow::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"{\"status\":\"connected\"}\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "status" => {
                let json = state.snapshot_json();
                writer.write_all(json.to_string().as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "ping" => {
                writer.write_all(b"{\"pong\":true}\n").await?;
            }
            _ => {
                writer
                    .write_all(b"{\"error\":\"unknown command\"}\n")
                    .await?;
            }
        }
    }

    Ok(())
}
