mod config;
mod metrics;
mod policy;
mod server;
mod state;

use crate::{config::Config, metrics::MetricsCollector, state::SharedState};
use tokio::time::{sleep, Duration};
use tracing::{error, info};

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "os_resource_daemon=info,tokio=warn".to_string()),
        )
        .init();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config/daemon.toml".to_string());

    let config = Config::load(&config_path)?;
    let state = SharedState::new();

    info!("starting daemon with config {}", config_path);

    let server_state = state.clone();
    let socket_path = config.socket_path.clone();
    tokio::spawn(async move {
        if let Err(e) = server::run_server(&socket_path, server_state).await {
            error!("server failed: {}", e);
        }
    });

    let mut collector = MetricsCollector::new();

    loop {
        let (snapshot, top_processes) = collector.collect();
        state.update_snapshot(snapshot.clone(), top_processes);
        policy::evaluate(&config, &state, &snapshot, &collector);

        sleep(Duration::from_millis(config.poll_interval_ms)).await;
    }
}
