use anyhow::{Context, Result};
use clap::Parser;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{Disks, Networks, System};
use thiserror::Error;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    process::Command,
    signal,
    sync::{broadcast, RwLock},
    time,
};
use tracing::{debug, error, info, warn};

#[derive(Parser, Debug)]
#[command(name = "sysmond")]
#[command(about = "High-performance system resource monitoring daemon")]
struct Cli {
    #[arg(long, default_value = "/tmp/sysmond.sock")]
    socket: PathBuf,

    #[arg(long, default_value_t = 1000)]
    interval_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ThresholdConfig {
    cpu_percent: Option<f32>,
    memory_percent: Option<f32>,
    disk_percent: Option<f32>,
    net_rx_bytes_per_sec: Option<u64>,
    net_tx_bytes_per_sec: Option<u64>,
    action: ActionConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum ActionConfig {
    Log,
    Command { program: String, args: Vec<String> },
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct DaemonConfig {
    thresholds: Vec<ThresholdConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_percent: f32,
    memory_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_disk: u64,
    used_disk: u64,
    disk_percent: f32,
    total_network_rx: u64,
    total_network_tx: u64,
    rx_bytes_per_sec: u64,
    tx_bytes_per_sec: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    GetStatus,
    GetConfig,
    SetConfig { config: DaemonConfig },
    Ping,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum ControlResponse {
    Ok,
    Pong,
    Status { snapshot: ResourceSnapshot },
    Config { config: DaemonConfig },
    Error { message: String },
}

#[derive(Debug, Error)]
enum DaemonError {
    #[error("invalid command")]
    InvalidCommand,
}

#[derive(Debug)]
struct SharedState {
    latest: Option<ResourceSnapshot>,
    config: DaemonConfig,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: None,
            config: DaemonConfig::default(),
        }
    }
}

#[derive(Debug)]
struct NetSample {
    rx: u64,
    tx: u64,
    at: Instant,
}

fn now_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn aggregate_disk(disks: &Disks) -> (u64, u64) {
    let mut total = 0u64;
    let mut available = 0u64;
    for d in disks.list() {
        total = total.saturating_add(d.total_space());
        available = available.saturating_add(d.available_space());
    }
    let used = total.saturating_sub(available);
    (total, used)
}

fn aggregate_network(networks: &Networks) -> (u64, u64) {
    let mut rx = 0u64;
    let mut tx = 0u64;
    for (_name, data) in networks.iter() {
        rx = rx.saturating_add(data.total_received());
        tx = tx.saturating_add(data.total_transmitted());
    }
    (rx, tx)
}

async fn execute_action(action: &ActionConfig, snapshot: &ResourceSnapshot) {
    match action {
        ActionConfig::Log => {
            warn!(?snapshot, "threshold exceeded");
        }
        ActionConfig::Command { program, args } => {
            let mut cmd = Command::new(program);
            cmd.args(args);
            cmd.env("SYSMOND_CPU_PERCENT", snapshot.cpu_percent.to_string());
            cmd.env("SYSMOND_MEMORY_PERCENT", snapshot.memory_percent.to_string());
            cmd.env("SYSMOND_DISK_PERCENT", snapshot.disk_percent.to_string());
            cmd.env("SYSMOND_RX_BPS", snapshot.rx_bytes_per_sec.to_string());
            cmd.env("SYSMOND_TX_BPS", snapshot.tx_bytes_per_sec.to_string());

            match cmd.spawn() {
                Ok(mut child) => {
                    tokio::spawn(async move {
                        match child.wait().await {
                            Ok(status) => debug!(?status, "action command completed"),
                            Err(e) => error!(error = %e, "action command wait failed"),
                        }
                    });
                }
                Err(e) => error!(error = %e, "failed to spawn action command"),
            }
        }
    }
}

fn threshold_exceeded(th: &ThresholdConfig, s: &ResourceSnapshot) -> bool {
    if let Some(v) = th.cpu_percent {
        if s.cpu_percent < v {
            return false;
        }
    }
    if let Some(v) = th.memory_percent {
        if s.memory_percent < v {
            return false;
        }
    }
    if let Some(v) = th.disk_percent {
        if s.disk_percent < v {
            return false;
        }
    }
    if let Some(v) = th.net_rx_bytes_per_sec {
        if s.rx_bytes_per_sec < v {
            return false;
        }
    }
    if let Some(v) = th.net_tx_bytes_per_sec {
        if s.tx_bytes_per_sec < v {
            return false;
        }
    }
    true
}

async fn monitor_loop(
    state: Arc<RwLock<SharedState>>,
    interval: Duration,
    mut shutdown_rx: broadcast::Receiver<()>,
) {
    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();
    let mut networks = Networks::new_with_refreshed_list();
    let mut ticker = time::interval(interval);
    let mut prev_net: Option<NetSample> = None;

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                sys.refresh_cpu_usage();
                sys.refresh_memory();
                disks.refresh();
                networks.refresh();

                let cpu_percent = sys.global_cpu_usage();
                let total_memory = sys.total_memory();
                let used_memory = sys.used_memory();
                let memory_percent = if total_memory == 0 {
                    0.0
                } else {
                    (used_memory as f32 / total_memory as f32) * 100.0
                };

                let (total_disk, used_disk) = aggregate_disk(&disks);
                let disk_percent = if total_disk == 0 {
                    0.0
                } else {
                    (used_disk as f32 / total_disk as f32) * 100.0
                };

                let (total_rx, total_tx) = aggregate_network(&networks);
                let now = Instant::now();

                let (rx_bps, tx_bps) = if let Some(prev) = &prev_net {
                    let elapsed = now.duration_since(prev.at).as_secs_f64();
                    if elapsed > 0.0 {
                        (
                            ((total_rx.saturating_sub(prev.rx)) as f64 / elapsed) as u64,
                            ((total_tx.saturating_sub(prev.tx)) as f64 / elapsed) as u64,
                        )
                    } else {
                        (0, 0)
                    }
                } else {
                    (0, 0)
                };

                prev_net = Some(NetSample {
                    rx: total_rx,
                    tx: total_tx,
                    at: now,
                });

                let snapshot = ResourceSnapshot {
                    timestamp_ms: now_ms(),
                    cpu_percent,
                    memory_percent,
                    total_memory,
                    used_memory,
                    total_disk,
                    used_disk,
                    disk_percent,
                    total_network_rx: total_rx,
                    total_network_tx: total_tx,
                    rx_bytes_per_sec: rx_bps,
                    tx_bytes_per_sec: tx_bps,
                };

                let config = {
                    let mut guard = state.write().await;
                    guard.latest = Some(snapshot.clone());
                    guard.config.clone()
                };

                for th in &config.thresholds {
                    if threshold_exceeded(th, &snapshot) {
                        execute_action(&th.action, &snapshot).await;
                    }
                }

                debug!(?snapshot, "resource snapshot updated");
            }
            _ = shutdown_rx.recv() => {
                info!("monitor loop shutting down");
                break;
            }
        }
    }
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<SharedState>>,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: ControlCommand = match serde_json::from_str(&line) {
            Ok(c) => c,
            Err(e) => {
                let resp = ControlResponse::Error {
                    message: format!("invalid json: {e}"),
                };
                writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
                writer.write_all(b"\n").await?;
                continue;
            }
        };

        let resp = match cmd {
            ControlCommand::Ping => ControlResponse::Pong,
            ControlCommand::GetStatus => {
                let guard = state.read().await;
                match &guard.latest {
                    Some(snapshot) => ControlResponse::Status {
                        snapshot: snapshot.clone(),
                    },
                    None => ControlResponse::Error {
                        message: "no snapshot available yet".into(),
                    },
                }
            }
            ControlCommand::GetConfig => {
                let guard = state.read().await;
                ControlResponse::Config {
                    config: guard.config.clone(),
                }
            }
            ControlCommand::SetConfig { config } => {
                let mut guard = state.write().await;
                guard.config = config;
                ControlResponse::Ok
            }
            ControlCommand::Shutdown => {
                let _ = shutdown_tx.send(());
                ControlResponse::Ok
            }
        };

        writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn control_server(
    socket_path: PathBuf,
    state: Arc<RwLock<SharedState>>,
    shutdown_tx: broadcast::Sender<()>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    if socket_path.exists() {
        std::fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove existing socket {:?}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind socket {:?}", socket_path))?;

    info!(path = %socket_path.display(), "control socket listening");

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                let (stream, _) = accept_res?;
                let state = state.clone();
                let shutdown_tx = shutdown_tx.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                        error!(error = %e, "client handler failed");
                    }
                });
            }
            _ = shutdown_rx.recv() => {
                info!("control server shutting down");
                break;
            }
        }
    }

    if socket_path.exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "sysmond=info".to_string()),
        )
        .init();

    let cli = Cli::parse();
    let state = Arc::new(RwLock::new(SharedState::new()));
    let (shutdown_tx, _) = broadcast::channel::<()>(16);

    let monitor_state = state.clone();
    let monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        monitor_loop(
            monitor_state,
            Duration::from_millis(cli.interval_ms),
            monitor_shutdown,
        )
        .await;
    });

    let server_state = state.clone();
    let server_shutdown = shutdown_tx.subscribe();
    let server_socket = cli.socket.clone();
    let server_tx = shutdown_tx.clone();
    let server_task = tokio::spawn(async move {
        if let Err(e) = control_server(server_socket, server_state, server_tx, server_shutdown).await {
            error!(error = %e, "control server failed");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c, shutting down");
            let _ = shutdown_tx.send(());
        }
        _ = monitor_task => {
            warn!("monitor task exited");
            let _ = shutdown_tx.send(());
        }
        _ = server_task => {
            warn!("server task exited");
            let _ = shutdown_tx.send(());
        }
    }

    time::sleep(Duration::from_millis(200)).await;
    info!("shutdown complete");
    Ok(())
}
