    sample_interval_ms: u64,
    cpu_alert_percent: f32,
    memory_alert_percent: f32,
    disk_alert_percent: f32,
    socket_path: String,
    top_process_count: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_alert_percent: 90.0,
            memory_alert_percent: 90.0,
            disk_alert_percent: 95.0,
            socket_path: "/tmp/sysmond.sock".to_string(),
            top_process_count: 10,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MetricsSnapshot {
    timestamp: u64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    memory_percent: f32,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    cpu_percent: f32,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Alert {
    timestamp: u64,
    severity: String,
    message: String,
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct DaemonState {
    latest: Option<MetricsSnapshot>,
    alerts: Vec<Alert>,
    counters: HashMap<String, u64>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    GetMetrics,
    GetAlerts,
    ClearAlerts,
    Ping,
    GetCounters,
}

#[derive(Debug, Serialize)]
struct CommandResponse<T: Serialize> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn push_alert(state: &mut DaemonState, severity: &str, message: String) {
    state.alerts.push(Alert {
        timestamp: now_ts(),
        severity: severity.to_string(),
        message,
    });

    if state.alerts.len() > 1024 {
        let excess = state.alerts.len() - 1024;
        state.alerts.drain(0..excess);
    }
}

async fn monitor_loop(state: Arc<RwLock<DaemonState>>, config: Config) {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    let mut interval = time::interval(Duration::from_millis(config.sample_interval_ms));

    loop {
        interval.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes();
        system.refresh_disks_list();
        system.refresh_disks();

        let total_memory = system.total_memory();
        let used_memory = system.used_memory();
        let total_swap = system.total_swap();
        let used_swap = system.used_swap();

        let memory_percent = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let cpu_percent = system.global_cpu_info().cpu_usage();

        let mut disks = Vec::new();
        for d in system.disks() {
            let total = d.total_space();
            let avail = d.available_space();
            let used_percent = if total > 0 {
                ((total - avail) as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            disks.push(DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_percent,
            });
        }

        let mut processes: Vec<ProcessInfo> = system
            .processes()
            .iter()
            .map(|(pid, p)| ProcessInfo {
                pid: pid.as_u32(),
                name: p.name().to_string(),
                cpu_percent: p.cpu_usage(),
                memory_bytes: p.memory(),
                status: format!("{:?}", p.status()),
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(config.top_process_count);

        let snapshot = MetricsSnapshot {
            timestamp: now_ts(),
            total_memory_bytes: total_memory,
            used_memory_bytes: used_memory,
            memory_percent,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            cpu_percent,
            disks: disks.clone(),
            top_processes: processes,
        };

        let mut st = state.write().await;
        st.latest = Some(snapshot);

        *st.counters.entry("samples_taken".into()).or_insert(0) += 1;

        if cpu_percent >= config.cpu_alert_percent {
            push_alert(
                &mut st,
                "warning",
                format!("CPU usage high: {:.2}%", cpu_percent),
            );
            *st.counters.entry("cpu_alerts".into()).or_insert(0) += 1;
        }

        if memory_percent >= config.memory_alert_percent {
            push_alert(
                &mut st,
                "warning",
                format!("Memory usage high: {:.2}%", memory_percent),
            );
            *st.counters.entry("memory_alerts".into()).or_insert(0) += 1;
        }

        for d in disks {
            if d.used_percent >= config.disk_alert_percent {
                push_alert(
                    &mut st,
                    "warning",
                    format!(
                        "Disk usage high on {} ({}): {:.2}%",
                        d.name, d.mount_point, d.used_percent
                    ),
                );
                *st.counters.entry("disk_alerts".into()).or_insert(0) += 1;
            }
        }
    }
}

async fn write_json_line<T: Serialize>(
    stream: &mut tokio::net::unix::OwnedWriteHalf,
    value: &T,
) -> Result<(), DaemonError> {
    let mut buf = serde_json::to_vec(value)?;
    buf.push(b'\n');
    stream.write_all(&buf).await?;
    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<DaemonState>>) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Result<Command, _> = serde_json::from_str(&line);

        match cmd {
            Ok(Command::Ping) => {
                write_json_line(
                    &mut writer,
                    &CommandResponse {
                        ok: true,
                        data: Some("pong"),
                        error: None::<String>,
                    },
                )
                .await?;
            }
            Ok(Command::GetMetrics) => {
                let st = state.read().await;
                write_json_line(
                    &mut writer,
                    &CommandResponse {
                        ok: true,
                        data: st.latest.clone(),
                        error: None::<String>,
                    },
                )
                .await?;
            }
            Ok(Command::GetAlerts) => {
                let st = state.read().await;
                write_json_line(
                    &mut writer,
                    &CommandResponse {
                        ok: true,
                        data: Some(st.alerts.clone()),
                        error: None::<String>,
                    },
                )
                .await?;
            }
            Ok(Command::ClearAlerts) => {
                let mut st = state.write().await;
                st.alerts.clear();
                write_json_line(
                    &mut writer,
                    &CommandResponse {
                        ok: true,
                        data: Some("cleared"),
                        error: None::<String>,
                    },
                )
                .await?;
            }
            Ok(Command::GetCounters) => {
                let st = state.read().await;
                write_json_line(
                    &mut writer,
                    &CommandResponse {
                        ok: true,
                        data: Some(st.counters.clone()),
                        error: None::<String>,
                    },
                )
                .await?;
            }
            Err(e) => {
                write_json_line(
                    &mut writer,
                    &CommandResponse::<()> {
                        ok: false,
                        data: None,
                        error: Some(format!("invalid command: {}", e)),
                    },
                )
                .await?;
            }
        }
    }

    Ok(())
}

async fn socket_server(state: Arc<RwLock<DaemonState>>, socket_path: &str) -> Result<(), DaemonError> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path)?;
    }

    let listener = UnixListener::bind(socket_path)?;
    info!("control socket listening at {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        task::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handler error: {}", e);
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<(), DaemonError> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();
    let state = Arc::new(RwLock::new(DaemonState::default()));

    let monitor_state = Arc::clone(&state);
    let monitor_config = config.clone();
    tokio::spawn(async move {
        monitor_loop(monitor_state, monitor_config).await;
    });

    let server_state = Arc::clone(&state);
    let socket_path = config.socket_path.clone();
    let server_task = tokio::spawn(async move { socket_server(server_state, &socket_path).await });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = server_task => {
            match res {
                Ok(Ok(())) => info!("socket server exited"),
                Ok(Err(e)) => error!("socket server error: {}", e),
                Err(e) => error!("socket server join error: {}", e),
            }
        }
    }

    if Path::new(&config.socket_path).exists() {
        if let Err(e) = std::fs::remove_file(&config.socket_path) {
            warn!("failed to remove socket file {}: {}", config.socket_path, e);
        }
    }

    info!("daemon stopped");
    Ok(())
}
