use anyhow::{Context, Result};
use nix::sys::signal::{kill as nix_kill, Signal};
use nix::unistd::Pid;
use serde::Serialize;
use std::{
    collections::HashMap,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const TOP_N: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct CpuSnapshot {
    usage_percent: f32,
    logical_cores: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemorySnapshot {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    cpu: CpuSnapshot,
    memory: MemorySnapshot,
    disks: Vec<DiskSnapshot>,
    top_cpu: Vec<ProcessSnapshot>,
    top_mem: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonStatus {
    running: bool,
    sample_interval_ms: u64,
    socket_path: String,
    last_sample_unix: u64,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Ok { message: String },
    Status { status: DaemonStatus },
    Metrics { metrics: MetricsSnapshot },
    Top {
        by_cpu: Vec<ProcessSnapshot>,
        by_mem: Vec<ProcessSnapshot>,
    },
    Error { error: String },
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<MetricsSnapshot>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    info!("daemon listening on {}", SOCKET_PATH);

    let running = Arc::new(AtomicBool::new(true));
    let state = Arc::new(RwLock::new(SharedState::default()));

    let monitor_handle = {
        let running = Arc::clone(&running);
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = monitor_loop(running, state).await {
                error!("monitor loop failed: {e:#}");
            }
        })
    };

    let server_handle = {
        let running = Arc::clone(&running);
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = server_loop(listener, running, state).await {
                error!("server loop failed: {e:#}");
            }
        })
    };

    tokio::select! {
        _ = tokio::signal::ctrl_c() => {
            warn!("received ctrl-c, shutting down");
        }
        _ = monitor_handle => {
            warn!("monitor task exited");
        }
        _ = server_handle => {
            warn!("server task exited");
        }
    }

    running.store(false, Ordering::SeqCst);

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn monitor_loop(running: Arc<AtomicBool>, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    // Prime CPU/process deltas.
    system.refresh_all();
    time::sleep(Duration::from_millis(500)).await;

    let mut ticker = time::interval(SAMPLE_INTERVAL);

    while running.load(Ordering::Relaxed) {
        ticker.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks();
        system.refresh_processes();

        let snapshot = build_snapshot(&system);

        {
            let mut guard = state.write().await;
            guard.latest = Some(snapshot);
        }
    }

    Ok(())
}

fn build_snapshot(system: &System) -> MetricsSnapshot {
    let timestamp_unix = now_unix();

    let cpu = CpuSnapshot {
        usage_percent: system.global_cpu_info().cpu_usage(),
        logical_cores: system.cpus().len(),
    };

    let total_mem = system.total_memory();
    let used_mem = system.used_memory();
    let free_mem = system.free_memory();
    let avail_mem = system.available_memory();

    let memory = MemorySnapshot {
        total_bytes: total_mem * 1024,
        used_bytes: used_mem * 1024,
        free_bytes: free_mem * 1024,
        available_bytes: avail_mem * 1024,
        used_percent: if total_mem > 0 {
            (used_mem as f32 / total_mem as f32) * 100.0
        } else {
            0.0
        },
    };

    let disks = system
        .disks()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                used_percent: if total > 0 {
                    (used as f32 / total as f32) * 100.0
                } else {
                    0.0
                },
            }
        })
        .collect::<Vec<_>>();

    let mut processes = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
            status: format!("{:?}", proc_.status()),
        })
        .collect::<Vec<_>>();

    let mut by_cpu = processes.clone();
    by_cpu.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    by_cpu.truncate(TOP_N);

    processes.sort_by(|a, b| b.memory_bytes.cmp(&a.memory_bytes));
    processes.truncate(TOP_N);

    MetricsSnapshot {
        timestamp_unix,
        cpu,
        memory,
        disks,
        top_cpu: by_cpu,
        top_mem: processes,
    }
}

async fn server_loop(
    listener: UnixListener,
    running: Arc<AtomicBool>,
    state: Arc<RwLock<SharedState>>,
) -> Result<()> {
    while running.load(Ordering::Relaxed) {
        let (stream, _) = listener.accept().await.context("accepting client")?;
        let running = Arc::clone(&running);
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, running, state).await {
                warn!("client handler error: {e:#}");
            }
        });
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    running: Arc<AtomicBool>,
    state: Arc<RwLock<SharedState>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    writer
        .write_all(b"{\"type\":\"ok\",\"message\":\"connected\"}\n")
        .await?;

    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let response = process_command(line, &running, &state).await;
        let json = serde_json::to_vec(&response)?;
        writer.write_all(&json).await?;
        writer.write_all(b"\n").await?;

        if matches!(response, Response::Ok { ref message } if message == "shutting down") {
            break;
        }
    }

    Ok(())
}

async fn process_command(
    line: &str,
    running: &Arc<AtomicBool>,
    state: &Arc<RwLock<SharedState>>,
) -> Response {
    let parts = line.split_whitespace().collect::<Vec<_>>();
    if parts.is_empty() {
        return Response::Error {
            error: "empty command".into(),
        };
    }

    match parts[0] {
        "status" => {
            let guard = state.read().await;
            let last_sample_unix = guard
                .latest
                .as_ref()
                .map(|m| m.timestamp_unix)
                .unwrap_or_default();

            Response::Status {
                status: DaemonStatus {
                    running: running.load(Ordering::Relaxed),
                    sample_interval_ms: SAMPLE_INTERVAL.as_millis() as u64,
                    socket_path: SOCKET_PATH.to_string(),
                    last_sample_unix,
                },
            }
        }
        "metrics" => {
            let guard = state.read().await;
            match &guard.latest {
                Some(metrics) => Response::Metrics {
                    metrics: metrics.clone(),
                },
                None => Response::Error {
                    error: "metrics not yet available".into(),
                },
            }
        }
        "top" => {
            let guard = state.read().await;
            match &guard.latest {
                Some(metrics) => Response::Top {
                    by_cpu: metrics.top_cpu.clone(),
                    by_mem: metrics.top_mem.clone(),
                },
                None => Response::Error {
                    error: "metrics not yet available".into(),
                },
            }
        }
        "kill" => {
            if parts.len() != 2 {
                return Response::Error {
                    error: "usage: kill <pid>".into(),
                };
            }

            match parts[1].parse::<i32>() {
                Ok(pid) => match nix_kill(Pid::from_raw(pid), Signal::SIGTERM) {
                    Ok(_) => Response::Ok {
                        message: format!("sent SIGTERM to pid {}", pid),
                    },
                    Err(e) => Response::Error {
                        error: format!("failed to kill {}: {}", pid, e),
                    },
                },
                Err(_) => Response::Error {
                    error: "invalid pid".into(),
                },
            }
        }
        "renice" => {
            if parts.len() != 3 {
                return Response::Error {
                    error: "usage: renice <pid> <nice>".into(),
                };
            }

            let pid = match parts[1].parse::<i32>() {
                Ok(v) => v,
                Err(_) => {
                    return Response::Error {
                        error: "invalid pid".into(),
                    }
                }
            };

            let nice = match parts[2].parse::<i32>() {
                Ok(v) => v,
                Err(_) => {
                    return Response::Error {
                        error: "invalid nice value".into(),
                    }
                }
            };

            match set_priority(pid, nice) {
                Ok(_) => Response::Ok {
                    message: format!("set pid {} nice to {}", pid, nice),
                },
                Err(e) => Response::Error {
                    error: format!("failed to renice {}: {}", pid, e),
                },
            }
        }
        "shutdown" => {
            running.store(false, Ordering::SeqCst);
            Response::Ok {
                message: "shutting down".into(),
            }
        }
        _ => Response::Error {
            error: format!("unknown command: {}", parts[0]),
        },
    }
}

fn set_priority(pid: i32, nice: i32) -> Result<()> {
    use nix::sys::resource::{setpriority, Which};

    setpriority(Which::PRIO_PROCESS, pid as u32, nice)
        .with_context(|| format!("setpriority({}, {})", pid, nice))?;
    Ok(())
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
