```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";
const METRICS_INTERVAL_SECS: u64 = 2;
const TOP_PROCESS_LIMIT: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct SystemMetrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    disks: Vec<DiskMetrics>,
    top_processes: Vec<ProcessMetrics>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskMetrics {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessMetrics {
    pid: i32,
    name: String,
    cpu_usage_percent: f32,
    memory: u64,
    virtual_memory: u64,
    status: String,
}

#[derive(Debug, Default)]
struct DaemonState {
    latest_metrics: Option<SystemMetrics>,
    process_index: HashMap<i32, ProcessMetrics>,
}

type SharedState = Arc<RwLock<DaemonState>>;

#[derive(Debug, Deserialize)]
#[serde(tag = "command", rename_all = "snake_case")]
enum Request {
    Status,
    Metrics,
    ListProcesses {
        limit: Option<usize>,
    },
    KillProcess {
        pid: i32,
        signal: Option<i32>,
    },
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok {
        data: serde_json::Value,
    },
    Error {
        message: String,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove existing socket {}", SOCKET_PATH))?;
    }

    let state: SharedState = Arc::new(RwLock::new(DaemonState::default()));

    let monitor_state = state.clone();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_state = state.clone();
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state).await {
            error!("server loop failed: {e:#}");
        }
    });

    info!("sysdaemon started");

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        _ = monitor_task => {
            warn!("monitor task exited");
        }
        _ = server_task => {
            warn!("server task exited");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = std::fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket on shutdown: {e}");
        }
    }

    info!("sysdaemon stopped");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "sysdaemon=info".to_string()),
        )
        .init();
}

async fn monitor_loop(state: SharedState) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    // Initial refresh to seed CPU usage calculations.
    system.refresh_all();
    time::sleep(Duration::from_millis(500)).await;

    let mut interval = time::interval(Duration::from_secs(METRICS_INTERVAL_SECS));

    loop {
        interval.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes();
        system.refresh_disks();

        let cpu_usage = system.global_cpu_info().cpu_usage();

        let disks = system
            .disks()
            .iter()
            .map(|d| DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: d.total_space(),
                available_space: d.available_space(),
            })
            .collect::<Vec<_>>();

        let mut processes = system
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessMetrics {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_usage_percent: proc_.cpu_usage(),
                memory: proc_.memory(),
                virtual_memory: proc_.virtual_memory(),
                status: format!("{:?}", proc_.status()),
            })
            .collect::<Vec<_>>();

        processes.sort_by(|a, b| {
            b.cpu_usage_percent
                .partial_cmp(&a.cpu_usage_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        let top_processes = processes
            .iter()
            .take(TOP_PROCESS_LIMIT)
            .cloned()
            .collect::<Vec<_>>();

        let process_index = processes
            .into_iter()
            .map(|p| (p.pid, p))
            .collect::<HashMap<_, _>>();

        let metrics = SystemMetrics {
            timestamp: now_unix(),
            cpu_usage_percent: cpu_usage,
            total_memory: system.total_memory(),
            used_memory: system.used_memory(),
            total_swap: system.total_swap(),
            used_swap: system.used_swap(),
            disks,
            top_processes,
        };

        let mut guard = state.write().await;
        guard.latest_metrics = Some(metrics);
        guard.process_index = process_index;
    }
}

async fn server_loop(state: SharedState) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handling error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let request: Request = match serde_json::from_str(&line) {
            Ok(req) => req,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid request: {e}"),
                };
                write_response(&mut writer, &resp).await?;
                continue;
            }
        };

        let response = process_request(request, &state).await;
        write_response(&mut writer, &response).await?;
    }

    Ok(())
}

async fn process_request(request: Request, state: &SharedState) -> Response {
    match request {
        Request::Status => {
            let guard = state.read().await;
            let ready = guard.latest_metrics.is_some();
            Response::Ok {
                data: serde_json::json!({
                    "service": "sysdaemon",
                    "ready": ready,
                    "socket_path": SOCKET_PATH,
                    "timestamp": now_unix(),
                }),
            }
        }
        Request::Metrics => {
            let guard = state.read().await;
            match &guard.latest_metrics {
                Some(metrics) => Response::Ok {
                    data: serde_json::to_value(metrics).unwrap_or_else(|_| serde_json::json!({})),
                },
                None => Response::Error {
                    message: "metrics not yet available".to_string(),
                },
            }
        }
        Request::ListProcesses { limit } => {
            let guard = state.read().await;
            let mut processes = guard.process_index.values().cloned().collect::<Vec<_>>();
            processes.sort_by(|a, b| {
                b.cpu_usage_percent
                    .partial_cmp(&a.cpu_usage_percent)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });

            let limit = limit.unwrap_or(TOP_PROCESS_LIMIT).min(processes.len());
            processes.truncate(limit);

            Response::Ok {
                data: serde_json::json!({
                    "processes": processes
                }),
            }
        }
        Request::KillProcess { pid, signal } => {
            let sig = match signal.unwrap_or(15) {
                9 => Signal::SIGKILL,
                15 => Signal::SIGTERM,
                2 => Signal::SIGINT,
                other => {
                    return Response::Error {
                        message: format!("unsupported signal: {other}"),
                    }
                }
            };

            match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::Ok {
                    data: serde_json::json!({
                        "pid": pid,
                        "signal": format!("{sig:?}"),
                        "result": "sent"
                    }),
                },
                Err(e) => Response::Error {
                    message: format!("failed to signal process {pid}: {e}"),
                },
            }
        }
    }
}

async fn write_response<W>(writer: &mut W, response: &Response) -> Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let payload = serde_json::to_string(response)?;
    writer.write_all(payload.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
