use anyhow::{Context, Result};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    collections::{HashMap, HashSet, VecDeque},
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{Disks, Pid, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::Notify,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const ALERT_HISTORY_LIMIT: usize = 256;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    cpu_alert_percent: f32,
    memory_alert_percent: f32,
    disk_alert_percent: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            cpu_alert_percent: 90.0,
            memory_alert_percent: 90.0,
            disk_alert_percent: 95.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MetricsSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    used_memory: u64,
    total_memory: u64,
    used_memory_percent: f32,
    disks: Vec<DiskMetrics>,
    watched_processes: Vec<ProcessStatus>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskMetrics {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessStatus {
    pid: u32,
    alive: bool,
    name: Option<String>,
    cpu_usage_percent: Option<f32>,
    memory_bytes: Option<u64>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Alert {
    timestamp: u64,
    severity: String,
    message: String,
}

#[derive(Debug)]
struct SharedState {
    latest: RwLock<Option<MetricsSnapshot>>,
    alerts: RwLock<VecDeque<Alert>>,
    watched_pids: RwLock<HashSet<u32>>,
    config: RwLock<Config>,
    shutting_down: AtomicBool,
    shutdown_notify: Notify,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: RwLock::new(None),
            alerts: RwLock::new(VecDeque::with_capacity(ALERT_HISTORY_LIMIT)),
            watched_pids: RwLock::new(HashSet::new()),
            config: RwLock::new(Config::default()),
            shutting_down: AtomicBool::new(false),
            shutdown_notify: Notify::new(),
        }
    }

    fn push_alert(&self, severity: impl Into<String>, message: impl Into<String>) {
        let mut alerts = self.alerts.write();
        if alerts.len() >= ALERT_HISTORY_LIMIT {
            alerts.pop_front();
        }
        alerts.push_back(Alert {
            timestamp: now_ts(),
            severity: severity.into(),
            message: message.into(),
        });
    }

    fn request_shutdown(&self) {
        self.shutting_down.store(true, Ordering::SeqCst);
        self.shutdown_notify.notify_waiters();
    }

    fn is_shutting_down(&self) -> bool {
        self.shutting_down.load(Ordering::SeqCst)
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Ok { message: String },
    Status { shutting_down: bool },
    Metrics { snapshot: Option<MetricsSnapshot> },
    Alerts { alerts: Vec<Alert> },
    Watched { pids: Vec<u32> },
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove existing socket {}", SOCKET_PATH))?;
    }

    let state = Arc::new(SharedState::new());

    let monitor_task = tokio::spawn(run_monitor(state.clone()));
    let socket_task = tokio::spawn(run_socket_server(state.clone()));
    let signal_task = tokio::spawn(wait_for_signal(state.clone()));

    tokio::select! {
        res = monitor_task => {
            error!("monitor task exited: {:?}", res);
        }
        res = socket_task => {
            error!("socket task exited: {:?}", res);
        }
        res = signal_task => {
            error!("signal task exited: {:?}", res);
        }
        _ = state.shutdown_notify.notified() => {
            info!("shutdown requested");
        }
    }

    state.request_shutdown();

    let _ = tokio::join!(monitor_task, socket_task, signal_task);

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    info!("daemon exited cleanly");
    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn wait_for_signal(state: Arc<SharedState>) {
    match signal::ctrl_c().await {
        Ok(()) => {
            info!("received ctrl-c");
            state.request_shutdown();
        }
        Err(e) => {
            error!("failed waiting for signal: {}", e);
            state.request_shutdown();
        }
    }
}

async fn run_monitor(state: Arc<SharedState>) -> Result<()> {
    let mut system = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();
    let mut ticker = time::interval(SAMPLE_INTERVAL);

    loop {
        tokio::select! {
            _ = state.shutdown_notify.notified() => {
                info!("monitor shutting down");
                break;
            }
            _ = ticker.tick() => {
                system.refresh_cpu_usage();
                system.refresh_memory();
                system.refresh_processes();
                disks.refresh();

                let snapshot = collect_metrics(&system, &disks, &state);
                evaluate_alerts(&snapshot, &state);

                {
                    let mut latest = state.latest.write();
                    *latest = Some(snapshot);
                }
            }
        }
    }

    Ok(())
}

fn collect_metrics(system: &System, disks: &Disks, state: &Arc<SharedState>) -> MetricsSnapshot {
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let used_memory_percent = if total_memory == 0 {
        0.0
    } else {
        (used_memory as f32 / total_memory as f32) * 100.0
    };

    let disk_metrics = disks
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used_percent = if total == 0 {
                0.0
            } else {
                ((total - avail) as f32 / total as f32) * 100.0
            };

            DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            }
        })
        .collect::<Vec<_>>();

    let watched = state.watched_pids.read().clone();
    let mut watched_processes = Vec::with_capacity(watched.len());

    for pid_u32 in watched {
        let pid = Pid::from_u32(pid_u32);
        if let Some(proc_) = system.process(pid) {
            watched_processes.push(ProcessStatus {
                pid: pid_u32,
                alive: true,
                name: Some(proc_.name().to_string_lossy().to_string()),
                cpu_usage_percent: Some(proc_.cpu_usage()),
                memory_bytes: Some(proc_.memory()),
            });
        } else {
            watched_processes.push(ProcessStatus {
                pid: pid_u32,
                alive: false,
                name: None,
                cpu_usage_percent: None,
                memory_bytes: None,
            });
        }
    }

    MetricsSnapshot {
        timestamp: now_ts(),
        cpu_usage_percent: system.global_cpu_usage(),
        used_memory,
        total_memory,
        used_memory_percent,
        disks: disk_metrics,
        watched_processes,
    }
}

fn evaluate_alerts(snapshot: &MetricsSnapshot, state: &Arc<SharedState>) {
    let cfg = state.config.read().clone();

    if snapshot.cpu_usage_percent >= cfg.cpu_alert_percent {
        state.push_alert(
            "warning",
            format!("high cpu usage: {:.2}%", snapshot.cpu_usage_percent),
        );
    }

    if snapshot.used_memory_percent >= cfg.memory_alert_percent {
        state.push_alert(
            "warning",
            format!("high memory usage: {:.2}%", snapshot.used_memory_percent),
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= cfg.disk_alert_percent {
            state.push_alert(
                "warning",
                format!(
                    "disk usage high on {} ({}): {:.2}%",
                    disk.name, disk.mount_point, disk.used_percent
                ),
            );
        }
    }

    for proc_ in &snapshot.watched_processes {
        if !proc_.alive {
            state.push_alert("critical", format!("watched process {} is not running", proc_.pid));
        }
    }
}

async fn run_socket_server(state: Arc<SharedState>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind socket {}", SOCKET_PATH))?;

    info!("listening on {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = state.shutdown_notify.notified() => {
                info!("socket server shutting down");
                break;
            }
            accept_res = listener.accept() => {
                match accept_res {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state).await {
                                warn!("client handler error: {}", e);
                            }
                        });
                    }
                    Err(e) => {
                        warn!("accept error: {}", e);
                    }
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<SharedState>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        let response = handle_command(cmd, &state).await;
        let json = serde_json::to_string(&response)?;
        writer.write_all(json.as_bytes()).await?;
        writer.write_all(b"\n").await?;

        if state.is_shutting_down() {
            break;
        }
    }

    Ok(())
}

async fn handle_command(cmd: &str, state: &Arc<SharedState>) -> Response {
    let mut parts = cmd.split_whitespace();
    match parts.next() {
        Some("status") => Response::Status {
            shutting_down: state.is_shutting_down(),
        },
        Some("metrics") => Response::Metrics {
            snapshot: state.latest.read().clone(),
        },
        Some("alerts") => Response::Alerts {
            alerts: state.alerts.read().iter().cloned().collect(),
        },
        Some("watched") => {
            let mut pids = state.watched_pids.read().iter().copied().collect::<Vec<_>>();
            pids.sort_unstable();
            Response::Watched { pids }
        }
        Some("watch") => match parts.next().and_then(|s| s.parse::<u32>().ok()) {
            Some(pid) => {
                state.watched_pids.write().insert(pid);
                Response::Ok {
                    message: format!("watching pid {}", pid),
                }
            }
            None => Response::Error {
                message: "usage: watch <pid>".into(),
            },
        },
        Some("unwatch") => match parts.next().and_then(|s| s.parse::<u32>().ok()) {
            Some(pid) => {
                state.watched_pids.write().remove(&pid);
                Response::Ok {
                    message: format!("unwatched pid {}", pid),
                }
            }
            None => Response::Error {
                message: "usage: unwatch <pid>".into(),
            },
        },
        Some("shutdown") => {
            state.request_shutdown();
            Response::Ok {
                message: "shutdown initiated".into(),
            }
        }
        Some(other) => Response::Error {
            message: format!("unknown command: {}", other),
        },
        None => Response::Error {
            message: "empty command".into(),
        },
    }
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
