use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    io,
    path::Path,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{Pid, ProcessRefreshKind, RefreshKind, System};
use thiserror::Error;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    task,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const POLICY_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Debug, Error)]
enum DaemonError {
    #[error("io error: {0}")]
    Io(#[from] io::Error),
    #[error("serde error: {0}")]
    Serde(#[from] serde_json::Error),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    cpu_usage_avg: f32,
    process_count: usize,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskSnapshot {
    name: String,
    available_space: u64,
    total_space: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessSnapshot {
    pid: u32,
    name: String,
    cpu_usage: f32,
    memory: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PolicyConfig {
    max_memory_percent: f32,
    max_cpu_percent: f32,
    max_processes: usize,
    kill_on_violation: bool,
}

impl Default for PolicyConfig {
    fn default() -> Self {
        Self {
            max_memory_percent: 90.0,
            max_cpu_percent: 95.0,
            max_processes: 4096,
            kill_on_violation: false,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SharedState {
    latest: Option<ResourceSnapshot>,
    policy: PolicyConfig,
    violations: Vec<String>,
    started_at_ms: u128,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: None,
            policy: PolicyConfig::default(),
            violations: Vec::new(),
            started_at_ms: now_ms(),
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    GetStatus,
    GetPolicy,
    SetPolicy {
        max_memory_percent: Option<f32>,
        max_cpu_percent: Option<f32>,
        max_processes: Option<usize>,
        kill_on_violation: Option<bool>,
    },
    ListProcesses,
    KillProcess {
        pid: u32,
    },
    Ping,
}

#[derive(Debug, Serialize)]
struct Response<T> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

impl<T> Response<T> {
    fn ok(data: T) -> Self {
        Self {
            ok: true,
            data: Some(data),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

fn now_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) {
    let mut ticker = time::interval(SAMPLE_INTERVAL);
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_memory()
            .with_processes(ProcessRefreshKind::everything()),
    );

    loop {
        ticker.tick().await;

        let started = Instant::now();
        sys.refresh_memory();
        sys.refresh_processes_specifics(ProcessRefreshKind::everything());
        sys.refresh_cpu();

        let cpu_usage_avg = sys.global_cpu_info().cpu_usage();

        let disks = sys
            .disks()
            .iter()
            .map(|d| DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                available_space: d.available_space(),
                total_space: d.total_space(),
            })
            .collect::<Vec<_>>();

        let mut top_processes = sys
            .processes()
            .iter()
            .map(|(pid, p)| ProcessSnapshot {
                pid: pid.as_u32(),
                name: p.name().to_string(),
                cpu_usage: p.cpu_usage(),
                memory: p.memory(),
                status: format!("{:?}", p.status()),
            })
            .collect::<Vec<_>>();

        top_processes.sort_by(|a, b| {
            b.cpu_usage
                .partial_cmp(&a.cpu_usage)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        top_processes.truncate(20);

        let snapshot = ResourceSnapshot {
            timestamp_ms: now_ms(),
            total_memory: sys.total_memory(),
            used_memory: sys.used_memory(),
            total_swap: sys.total_swap(),
            used_swap: sys.used_swap(),
            cpu_usage_avg,
            process_count: sys.processes().len(),
            disks,
            top_processes,
        };

        {
            let mut guard = state.write();
            guard.latest = Some(snapshot);
        }

        let elapsed = started.elapsed();
        if elapsed > SAMPLE_INTERVAL {
            warn!("monitor loop overran sample interval: {:?}", elapsed);
        }
    }
}

async fn policy_loop(state: Arc<RwLock<SharedState>>) {
    let mut ticker = time::interval(POLICY_INTERVAL);

    loop {
        ticker.tick().await;

        let (snapshot, policy) = {
            let guard = state.read();
            (guard.latest.clone(), guard.policy.clone())
        };

        let Some(snapshot) = snapshot else {
            continue;
        };

        let mut violations = Vec::new();

        let mem_pct = if snapshot.total_memory > 0 {
            (snapshot.used_memory as f32 / snapshot.total_memory as f32) * 100.0
        } else {
            0.0
        };

        if mem_pct > policy.max_memory_percent {
            violations.push(format!(
                "memory usage violation: {:.2}% > {:.2}%",
                mem_pct, policy.max_memory_percent
            ));
        }

        if snapshot.cpu_usage_avg > policy.max_cpu_percent {
            violations.push(format!(
                "cpu usage violation: {:.2}% > {:.2}%",
                snapshot.cpu_usage_avg, policy.max_cpu_percent
            ));
        }

        if snapshot.process_count > policy.max_processes {
            violations.push(format!(
                "process count violation: {} > {}",
                snapshot.process_count, policy.max_processes
            ));
        }

        if !violations.is_empty() {
            warn!("policy violations: {:?}", violations);

            if policy.kill_on_violation {
                if let Some(proc_) = snapshot.top_processes.first() {
                    match kill_process(proc_.pid) {
                        Ok(_) => warn!("killed process {} ({})", proc_.pid, proc_.name),
                        Err(e) => error!("failed to kill process {}: {}", proc_.pid, e),
                    }
                }
            }
        }

        {
            let mut guard = state.write();
            guard.violations = violations;
        }
    }
}

fn kill_process(pid: u32) -> Result<(), String> {
    use nix::sys::signal::{kill, Signal};
    use nix::unistd::Pid as NixPid;

    kill(NixPid::from_raw(pid as i32), Signal::SIGKILL).map_err(|e| e.to_string())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let response = match serde_json::from_str::<Command>(&line) {
            Ok(cmd) => handle_command(cmd, &state).await,
            Err(e) => serde_json::to_string(&Response::<()>::err(format!("invalid command: {}", e)))?,
        };

        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn handle_command(cmd: Command, state: &Arc<RwLock<SharedState>>) -> String {
    match cmd {
        Command::GetStatus => {
            let guard = state.read();
            serde_json::to_string(&Response::ok(guard.clone()))
                .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap())
        }
        Command::GetPolicy => {
            let guard = state.read();
            serde_json::to_string(&Response::ok(guard.policy.clone()))
                .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap())
        }
        Command::SetPolicy {
            max_memory_percent,
            max_cpu_percent,
            max_processes,
            kill_on_violation,
        } => {
            let mut guard = state.write();
            if let Some(v) = max_memory_percent {
                guard.policy.max_memory_percent = v;
            }
            if let Some(v) = max_cpu_percent {
                guard.policy.max_cpu_percent = v;
            }
            if let Some(v) = max_processes {
                guard.policy.max_processes = v;
            }
            if let Some(v) = kill_on_violation {
                guard.policy.kill_on_violation = v;
            }

            serde_json::to_string(&Response::ok(guard.policy.clone()))
                .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap())
        }
        Command::ListProcesses => {
            let mut sys = System::new();
            sys.refresh_processes_specifics(ProcessRefreshKind::everything());

            let mut procs: Vec<ProcessSnapshot> = sys
                .processes()
                .iter()
                .map(|(pid, p)| ProcessSnapshot {
                    pid: pid.as_u32(),
                    name: p.name().to_string(),
                    cpu_usage: p.cpu_usage(),
                    memory: p.memory(),
                    status: format!("{:?}", p.status()),
                })
                .collect();

            procs.sort_by(|a, b| {
                b.cpu_usage
                    .partial_cmp(&a.cpu_usage)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });

            serde_json::to_string(&Response::ok(procs))
                .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap())
        }
        Command::KillProcess { pid } => {
            let result = kill_process(pid);
            match result {
                Ok(_) => serde_json::to_string(&Response::ok(format!("killed {}", pid)))
                    .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap()),
                Err(e) => serde_json::to_string(&Response::<()>::err(e))
                    .unwrap_or_else(|se| serde_json::to_string(&Response::<()>::err(se.to_string())).unwrap()),
            }
        }
        Command::Ping => serde_json::to_string(&Response::ok("pong"))
            .unwrap_or_else(|e| serde_json::to_string(&Response::<()>::err(e.to_string())).unwrap()),
    }
}

async fn socket_server(state: Arc<RwLock<SharedState>>) -> Result<(), DaemonError> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH)?;
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    info!("control socket listening at {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        task::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client handler error: {}", e);
            }
        });
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<(), DaemonError> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = Arc::new(RwLock::new(SharedState::new()));

    let monitor_state = Arc::clone(&state);
    let policy_state = Arc::clone(&state);
    let socket_state = Arc::clone(&state);

    let monitor = task::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let policy = task::spawn(async move {
        policy_loop(policy_state).await;
    });

    let server = task::spawn(async move {
        if let Err(e) = socket_server(socket_state).await {
            error!("socket server error: {}", e);
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        _ = monitor => {}
        _ = policy => {}
        _ = server => {}
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}
