```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time::interval;

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const TOP_N_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct CpuSnapshot {
    usage_percent: f32,
    core_count: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemorySnapshot {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonStatus {
    timestamp_unix: u64,
    cpu: CpuSnapshot,
    memory: MemorySnapshot,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<DaemonStatus>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Ping,
    Status,
    Processes,
    Kill { pid: i32 },
    Term { pid: i32 },
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Pong,
    Ok,
    Status { status: DaemonStatus },
    Processes { processes: Vec<ProcessSnapshot> },
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket at {}", SOCKET_PATH))?;
    }

    let state: State = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            eprintln!("monitor loop error: {e:#}");
        }
    });

    let server_state = Arc::clone(&state);
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state).await {
            eprintln!("server loop error: {e:#}");
        }
    });

    tokio::select! {
        _ = tokio::signal::ctrl_c() => {
            eprintln!("received shutdown signal");
        }
        _ = monitor_task => {
            eprintln!("monitor task exited");
        }
        _ = server_task => {
            eprintln!("server task exited");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

async fn monitor_loop(state: State) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    // Prime CPU counters for meaningful usage values.
    sys.refresh_all();
    tokio::time::sleep(Duration::from_millis(500)).await;

    let mut ticker = interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        ticker.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks();

        let cpu = CpuSnapshot {
            usage_percent: sys.global_cpu_info().cpu_usage(),
            core_count: sys.cpus().len(),
        };

        let total_mem = sys.total_memory();
        let used_mem = sys.used_memory();
        let free_mem = total_mem.saturating_sub(used_mem);

        let memory = MemorySnapshot {
            total_bytes: total_mem * 1024,
            used_bytes: used_mem * 1024,
            free_bytes: free_mem * 1024,
            used_percent: if total_mem == 0 {
                0.0
            } else {
                (used_mem as f32 / total_mem as f32) * 100.0
            },
        };

        let disks = sys
            .disks()
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                DiskSnapshot {
                    name: d.name().to_string_lossy().to_string(),
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    total_bytes: total,
                    available_bytes: avail,
                    used_bytes: used,
                    used_percent: if total == 0 {
                        0.0
                    } else {
                        (used as f32 / total as f32) * 100.0
                    },
                }
            })
            .collect::<Vec<_>>();

        let mut processes = sys
            .processes()
            .iter()
            .map(|(pid, p)| ProcessSnapshot {
                pid: pid.as_u32() as i32,
                name: p.name().to_string(),
                cpu_percent: p.cpu_usage(),
                memory_bytes: p.memory() * 1024,
                status: format!("{:?}", p.status()),
            })
            .collect::<Vec<_>>();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(Ordering::Equal)
                .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
        });

        let top_processes = processes.into_iter().take(TOP_N_PROCESSES).collect();

        let status = DaemonStatus {
            timestamp_unix: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            cpu,
            memory,
            disks,
            top_processes,
        };

        let mut guard = state.write().await;
        guard.latest = Some(status);
    }
}

async fn server_loop(state: State) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: State) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let bytes = reader.read_line(&mut line).await?;
    if bytes == 0 {
        return Ok(());
    }

    let req: Request = match serde_json::from_str(line.trim()) {
        Ok(r) => r,
        Err(e) => {
            let resp = Response::Error {
                message: format!("invalid request: {e}"),
            };
            write_response(&mut writer, &resp).await?;
            return Ok(());
        }
    };

    let resp = dispatch(req, state).await;
    write_response(&mut writer, &resp).await?;
    Ok(())
}

async fn dispatch(req: Request, state: State) -> Response {
    match req {
        Request::Ping => Response::Pong,
        Request::Status => {
            let guard = state.read().await;
            match &guard.latest {
                Some(status) => Response::Status {
                    status: status.clone(),
                },
                None => Response::Error {
                    message: "status not yet available".to_string(),
                },
            }
        }
        Request::Processes => {
            let mut sys = System::new();
            sys.refresh_processes();

            let mut processes = sys
                .processes()
                .iter()
                .map(|(pid, p)| ProcessSnapshot {
                    pid: pid.as_u32() as i32,
                    name: p.name().to_string(),
                    cpu_percent: p.cpu_usage(),
                    memory_bytes: p.memory() * 1024,
                    status: format!("{:?}", p.status()),
                })
                .collect::<Vec<_>>();

            processes.sort_by(|a, b| {
                b.cpu_percent
                    .partial_cmp(&a.cpu_percent)
                    .unwrap_or(Ordering::Equal)
                    .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
            });

            Response::Processes { processes }
        }
        Request::Kill { pid } => match kill(Pid::from_raw(pid), Signal::SIGKILL) {
            Ok(_) => Response::Ok,
            Err(e) => Response::Error {
                message: format!("failed to kill pid {pid}: {e}"),
            },
        },
        Request::Term { pid } => match kill(Pid::from_raw(pid), Signal::SIGTERM) {
            Ok(_) => Response::Ok,
            Err(e) => Response::Error {
                message: format!("failed to terminate pid {pid}: {e}"),
            },
        },
    }
}

async fn write_response<W>(writer: &mut W, resp: &Response) -> Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let json = serde_json::to_string(resp)?;
    writer.write_all(json.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}
