use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use thiserror::Error;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::RwLock;
use tokio::time;

const SOCKET_PATH: &str = "/tmp/osmond.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Error)]
enum DaemonError {
    #[error("io error: {0}")]
    Io(#[from] io::Error),

    #[error("parse error: {0}")]
    Parse(String),

    #[error("signal error: {0}")]
    Signal(String),
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn busy(&self) -> u64 {
        self.total() - self.idle - self.iowait
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct CpuSnapshot {
    usage_percent: f64,
    raw: CpuTimes,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct MemorySnapshot {
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
    swap_total_kb: u64,
    swap_free_kb: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct LoadSnapshot {
    one: f64,
    five: f64,
    fifteen: f64,
    running_tasks: String,
    last_pid: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct DiskStat {
    device: String,
    reads_completed: u64,
    reads_merged: u64,
    sectors_read: u64,
    time_reading_ms: u64,
    writes_completed: u64,
    writes_merged: u64,
    sectors_written: u64,
    time_writing_ms: u64,
    io_in_progress: u64,
    time_doing_io_ms: u64,
    weighted_time_doing_io_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct ProcessInfo {
    pid: i32,
    ppid: i32,
    name: String,
    state: String,
    vm_rss_kb: u64,
    threads: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct SystemSnapshot {
    timestamp_unix: u64,
    cpu: CpuSnapshot,
    memory: MemorySnapshot,
    load: LoadSnapshot,
    disks: Vec<DiskStat>,
    process_count: usize,
    processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct SharedState {
    snapshot: SystemSnapshot,
    prev_cpu: Option<CpuTimes>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Ping,
    GetSnapshot,
    ListProcesses,
    KillProcess { pid: i32, signal: Option<i32> },
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let state: State = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            eprintln!("monitor loop error: {e}");
        }
    });

    let server_state = Arc::clone(&state);
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state).await {
            eprintln!("server loop error: {e}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            eprintln!("shutdown signal received");
        }
        _ = monitor_task => {
            eprintln!("monitor task exited");
        }
        _ = server_task => {
            eprintln!("server task exited");
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}

async fn monitor_loop(state: State) -> Result<(), DaemonError> {
    let mut interval = time::interval(SAMPLE_INTERVAL);

    loop {
        interval.tick().await;

        let cpu_raw = read_cpu_times()?;
        let memory = read_meminfo()?;
        let load = read_loadavg()?;
        let disks = read_diskstats()?;
        let processes = read_processes()?;

        let mut guard = state.write().await;
        let usage_percent = if let Some(prev) = &guard.prev_cpu {
            compute_cpu_usage(prev, &cpu_raw)
        } else {
            0.0
        };

        guard.snapshot = SystemSnapshot {
            timestamp_unix: now_unix(),
            cpu: CpuSnapshot {
                usage_percent,
                raw: cpu_raw.clone(),
            },
            memory,
            load,
            process_count: processes.len(),
            processes,
            disks,
        };

        guard.prev_cpu = Some(cpu_raw);
    }
}

async fn server_loop(state: State) -> Result<(), DaemonError> {
    let listener = UnixListener::bind(SOCKET_PATH)?;

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: State) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: Result<Request, _> = serde_json::from_str(&line);
        let resp = match req {
            Ok(r) => process_request(r, &state).await,
            Err(e) => Response::Error {
                message: format!("invalid request: {e}"),
            },
        };

        let encoded = serde_json::to_string(&resp)
            .map_err(|e| DaemonError::Parse(format!("serialize response: {e}")))?;
        writer.write_all(encoded.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_request(req: Request, state: &State) -> Response {
    match req {
        Request::Ping => Response::Ok {
            data: serde_json::json!({ "message": "pong" }),
        },
        Request::GetSnapshot => {
            let guard = state.read().await;
            match serde_json::to_value(&guard.snapshot) {
                Ok(v) => Response::Ok { data: v },
                Err(e) => Response::Error {
                    message: format!("serialization error: {e}"),
                },
            }
        }
        Request::ListProcesses => {
            let guard = state.read().await;
            match serde_json::to_value(&guard.snapshot.processes) {
                Ok(v) => Response::Ok { data: v },
                Err(e) => Response::Error {
                    message: format!("serialization error: {e}"),
                },
            }
        }
        Request::KillProcess { pid, signal } => {
            let sig = signal
                .and_then(|s| Signal::try_from(s).ok())
                .unwrap_or(Signal::SIGTERM);

            match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::Ok {
                    data: serde_json::json!({
                        "pid": pid,
                        "signal": sig as i32,
                        "result": "sent"
                    }),
                },
                Err(e) => Response::Error {
                    message: format!("failed to signal pid {pid}: {e}"),
                },
            }
        }
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn compute_cpu_usage(prev: &CpuTimes, curr: &CpuTimes) -> f64 {
    let total_delta = curr.total().saturating_sub(prev.total());
    let busy_delta = curr.busy().saturating_sub(prev.busy());

    if total_delta == 0 {
        0.0
    } else {
        (busy_delta as f64 / total_delta as f64) * 100.0
    }
}

fn read_cpu_times() -> Result<CpuTimes, DaemonError> {
    let content = fs::read_to_string("/proc/stat")?;
    let line = content
        .lines()
        .find(|l| l.starts_with("cpu "))
        .ok_or_else(|| DaemonError::Parse("missing cpu line in /proc/stat".into()))?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 8 {
        return Err(DaemonError::Parse("invalid cpu stat format".into()));
    }

    Ok(CpuTimes {
        user: parse_u64(parts[1])?,
        nice: parse_u64(parts[2])?,
        system: parse_u64(parts[3])?,
        idle: parse_u64(parts[4])?,
        iowait: parse_u64(parts[5]).unwrap_or(0),
        irq: parse_u64(parts[6]).unwrap_or(0),
        softirq: parse_u64(parts[7]).unwrap_or(0),
        steal: parts.get(8).map(|v| parse_u64(v).unwrap_or(0)).unwrap_or(0),
    })
}

fn read_meminfo() -> Result<MemorySnapshot, DaemonError> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut map = HashMap::new();

    for line in content.lines() {
        let mut parts = line.split(':');
        if let (Some(key), Some(rest)) = (parts.next(), parts.next()) {
            let value = rest
                .split_whitespace()
                .next()
                .and_then(|v| v.parse::<u64>().ok())
                .unwrap_or(0);
            map.insert(key.to_string(), value);
        }
    }

    let mem_total = *map.get("MemTotal").unwrap_or(&0);
    let mem_available = *map.get("MemAvailable").unwrap_or(&0);
    let swap_total = *map.get("SwapTotal").unwrap_or(&0);
    let swap_free = *map.get("SwapFree").unwrap_or(&0);

    Ok(MemorySnapshot {
        mem_total_kb: mem_total,
        mem_available_kb: mem_available,
        mem_used_kb: mem_total.saturating_sub(mem_available),
        swap_total_kb: swap_total,
        swap_free_kb: swap_free,
    })
}

fn read_loadavg() -> Result<LoadSnapshot, DaemonError> {
    let content = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = content.split_whitespace().collect();
    if parts.len() < 5 {
        return Err(DaemonError::Parse("invalid /proc/loadavg format".into()));
    }

    Ok(LoadSnapshot {
        one: parts[0].parse().unwrap_or(0.0),
        five: parts[1].parse().unwrap_or(0.0),
        fifteen: parts[2].parse().unwrap_or(0.0),
        running_tasks: parts[3].to_string(),
        last_pid: parts[4].parse().unwrap_or(0),
    })
}

fn read_diskstats() -> Result<Vec<DiskStat>, DaemonError> {
    let content = fs::read_to_string("/proc/diskstats")?;
    let mut out = Vec::new();

    for line in content.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 14 {
            continue;
        }

        let device = parts[2].to_string();

        if device.starts_with("loop") || device.starts_with("ram") {
            continue;
        }

        out.push(DiskStat {
            device,
            reads_completed: parse_u64(parts[3]).unwrap_or(0),
            reads_merged: parse_u64(parts[4]).unwrap_or(0),
            sectors_read: parse_u64(parts[5]).unwrap_or(0),
            time_reading_ms: parse_u64(parts[6]).unwrap_or(0),
            writes_completed: parse_u64(parts[7]).unwrap_or(0),
            writes_merged: parse_u64(parts[8]).unwrap_or(0),
            sectors_written: parse_u64(parts[9]).unwrap_or(0),
            time_writing_ms: parse_u64(parts[10]).unwrap_or(0),
            io_in_progress: parse_u64(parts[11]).unwrap_or(0),
            time_doing_io_ms: parse_u64(parts[12]).unwrap_or(0),
            weighted_time_doing_io_ms: parse_u64(parts[13]).unwrap_or(0),
        });
    }

    Ok(out)
}

fn read_processes() -> Result<Vec<ProcessInfo>, DaemonError> {
    let mut processes = Vec::new();

    for entry in fs::read_dir("/proc")? {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let name = entry.file_name();
        let pid_str = name.to_string_lossy();

        if !pid_str.chars().all(|c| c.is_ascii_digit()) {
            continue;
        }

        let pid: i32 = match pid_str.parse() {
            Ok(v) => v,
            Err(_) => continue,
        };

        if let Ok(proc_info) = read_process(pid) {
            processes.push(proc_info);
        }
    }

    processes.sort_by_key(|p| p.pid);
    Ok(processes)
}

fn read_process(pid: i32) -> Result<ProcessInfo, DaemonError> {
    let stat_path = format!("/proc/{pid}/stat");
    let status_path = format!("/proc/{pid}/status");

    let stat_content = fs::read_to_string(stat_path)?;
    let status_content = fs::read_to_string(status_path)?;

    let (name, rest) = parse_proc_stat_comm(&stat_content)?;
    let stat_parts: Vec<&str> = rest.split_whitespace().collect();

    if stat_parts.len() < 3 {
        return Err(DaemonError::Parse(format!(
            "invalid stat format for pid {pid}"
        )));
    }

    let state = stat_parts[0].to_string();
    let ppid = parse_i32(stat_parts[1])?;

    let mut vm_rss_kb = 0u64;
    let mut threads = 0u32;

    for line in status_content.lines() {
        if let Some(v) = line.strip_prefix("VmRSS:") {
            vm_rss_kb = v
                .split_whitespace()
                .next()
                .and_then(|x| x.parse::<u64>().ok())
                .unwrap_or(0);
        } else if let Some(v) = line.strip_prefix("Threads:") {
            threads = v.trim().parse::<u32>().unwrap_or(0);
        }
    }

    Ok(ProcessInfo {
        pid,
        ppid,
        name,
        state,
        vm_rss_kb,
        threads,
    })
}

fn parse_proc_stat_comm(stat: &str) -> Result<(String, String), DaemonError> {
    let start = stat
        .find('(')
        .ok_or_else(|| DaemonError::Parse("missing '(' in /proc/<pid>/stat".into()))?;
    let end = stat
        .rfind(')')
        .ok_or_else(|| DaemonError::Parse("missing ')' in /proc/<pid>/stat".into()))?;

    let name = stat[start + 1..end].to_string();
    let rest = stat[end + 1..].trim().to_string();
    Ok((name, rest))
}

fn parse_u64(s: &str) -> Result<u64, DaemonError> {
    s.parse::<u64>()
        .map_err(|e| DaemonError::Parse(format!("u64 parse '{s}': {e}")))
}

fn parse_i32(s: &str) -> Result<i32, DaemonError> {
    s.parse::<i32>()
        .map_err(|e| DaemonError::Parse(format!("i32 parse '{s}': {e}")))
}
