```rust
use anyhow::{Context, Result};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, RefreshKind, System};
use thiserror::Error;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    task,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/os-resource-daemon.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ThresholdPolicy {
    cpu_percent: f32,
    memory_percent: f32,
    max_processes: usize,
}

impl Default for ThresholdPolicy {
    fn default() -> Self {
        Self {
            cpu_percent: 90.0,
            memory_percent: 90.0,
            max_processes: 5000,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SystemSnapshot {
    timestamp_ms: u128,
    uptime_secs: u64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    cpu_usage_percent: f32,
    process_count: usize,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonState {
    latest: Option<SystemSnapshot>,
    policy: ThresholdPolicy,
    violations: Vec<String>,
    started_at_ms: u128,
}

impl DaemonState {
    fn new() -> Self {
        Self {
            latest: None,
            policy: ThresholdPolicy::default(),
            violations: Vec::new(),
            started_at_ms: now_ms(),
        }
    }
}

#[derive(Debug, Error)]
enum CommandError {
    #[error("invalid command")]
    InvalidCommand,
    #[error("serialization error")]
    Serialization,
}

fn now_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn collect_snapshot(sys: &mut System) -> SystemSnapshot {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    let total_memory_bytes = sys.total_memory() * 1024;
    let used_memory_bytes = sys.used_memory() * 1024;
    let total_swap_bytes = sys.total_swap() * 1024;
    let used_swap_bytes = sys.used_swap() * 1024;

    let mut processes: Vec<ProcessInfo> = sys
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
            status: format!("{:?}", proc_.status()),
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    let top_processes = processes.into_iter().take(10).collect::<Vec<_>>();

    let disks = sys
        .disks()
        .iter()
        .map(|d| DiskInfo {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
        })
        .collect::<Vec<_>>();

    SystemSnapshot {
        timestamp_ms: now_ms(),
        uptime_secs: System::uptime(),
        total_memory_bytes,
        used_memory_bytes,
        total_swap_bytes,
        used_swap_bytes,
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        process_count: sys.processes().len(),
        disks,
        top_processes,
    }
}

fn evaluate_policy(snapshot: &SystemSnapshot, policy: &ThresholdPolicy) -> Vec<String> {
    let mut violations = Vec::new();

    let mem_pct = if snapshot.total_memory_bytes == 0 {
        0.0
    } else {
        (snapshot.used_memory_bytes as f32 / snapshot.total_memory_bytes as f32) * 100.0
    };

    if snapshot.cpu_usage_percent > policy.cpu_percent {
        violations.push(format!(
            "CPU usage high: {:.2}% > {:.2}%",
            snapshot.cpu_usage_percent, policy.cpu_percent
        ));
    }

    if mem_pct > policy.memory_percent {
        violations.push(format!(
            "Memory usage high: {:.2}% > {:.2}%",
            mem_pct, policy.memory_percent
        ));
    }

    if snapshot.process_count > policy.max_processes {
        violations.push(format!(
            "Process count high: {} > {}",
            snapshot.process_count, policy.max_processes
        ));
    }

    violations
}

async fn monitor_loop(state: Arc<RwLock<DaemonState>>, shutdown: Arc<AtomicBool>) {
    let mut sys = System::new_all();
    sys.refresh_all();

    let mut ticker = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        ticker.tick().await;

        if shutdown.load(Ordering::Relaxed) {
            info!("monitor loop shutting down");
            break;
        }

        let started = Instant::now();
        let snapshot = collect_snapshot(&mut sys);

        {
            let mut guard = state.write();
            let violations = evaluate_policy(&snapshot, &guard.policy);
            guard.latest = Some(snapshot);
            guard.violations = violations.clone();

            if !violations.is_empty() {
                warn!(?violations, "policy violations detected");
            }
        }

        let elapsed = started.elapsed();
        info!("sample collected in {:?}", elapsed);
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetState,
    GetSnapshot,
    GetPolicy,
    SetPolicy {
        cpu_percent: Option<f32>,
        memory_percent: Option<f32>,
        max_processes: Option<usize>,
    },
    Ping,
    Shutdown,
}

#[derive(Debug, Serialize, Deserialize)]
struct Response {
    ok: bool,
    message: String,
    data: Option<serde_json::Value>,
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<DaemonState>>,
    shutdown: Arc<AtomicBool>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: Request = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response {
                    ok: false,
                    message: format!("bad request: {}", e),
                    data: None,
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
                continue;
            }
        };

        let resp = match req {
            Request::Ping => Response {
                ok: true,
                message: "pong".into(),
                data: None,
            },
            Request::GetState => {
                let guard = state.read();
                Response {
                    ok: true,
                    message: "state".into(),
                    data: Some(serde_json::to_value(&*guard)?),
                }
            }
            Request::GetSnapshot => {
                let guard = state.read();
                Response {
                    ok: true,
                    message: "snapshot".into(),
                    data: Some(serde_json::to_value(&guard.latest)?),
                }
            }
            Request::GetPolicy => {
                let guard = state.read();
                Response {
                    ok: true,
                    message: "policy".into(),
                    data: Some(serde_json::to_value(&guard.policy)?),
                }
            }
            Request::SetPolicy {
                cpu_percent,
                memory_percent,
                max_processes,
            } => {
                let mut guard = state.write();
                if let Some(v) = cpu_percent {
                    guard.policy.cpu_percent = v;
                }
                if let Some(v) = memory_percent {
                    guard.policy.memory_percent = v;
                }
                if let Some(v) = max_processes {
                    guard.policy.max_processes = v;
                }
                Response {
                    ok: true,
                    message: "policy updated".into(),
                    data: Some(serde_json::to_value(&guard.policy)?),
                }
            }
            Request::Shutdown => {
                shutdown.store(true, Ordering::Relaxed);
                Response {
                    ok: true,
                    message: "shutdown initiated".into(),
                    data: None,
                }
            }
        };

        writer
            .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
            .await?;
    }

    Ok(())
}

async fn server_loop(
    state: Arc<RwLock<DaemonState>>,
    shutdown: Arc<AtomicBool>,
) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    info!("control socket listening at {}", SOCKET_PATH);

    loop {
        if shutdown.load(Ordering::Relaxed) {
            info!("server loop shutting down");
            break;
        }

        let accept_result = tokio::select! {
            res = listener.accept() => res,
            _ = time::sleep(Duration::from_millis(200)) => {
                continue;
            }
        };

        match accept_result {
            Ok((stream, _addr)) => {
                let state = Arc::clone(&state);
                let shutdown = Arc::clone(&shutdown);
                task::spawn(async move {
                    if let Err(e) = handle_client(stream, state, shutdown).await {
                        error!("client handler error: {:?}", e);
                    }
                });
            }
            Err(e) => {
                error!("accept error: {:?}", e);
            }
        }
    }

    let _ = std::fs::remove_file(SOCKET_PATH);
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = Arc::new(RwLock::new(DaemonState::new()));
    let shutdown = Arc::new(AtomicBool::new(false));

    let monitor_state = Arc::clone(&state);
    let monitor_shutdown = Arc::clone(&shutdown);
    let monitor_task = task::spawn(async move {
        monitor_loop(monitor_state, monitor_shutdown).await;
    });

    let server_state = Arc::clone(&state);
    let server_shutdown = Arc::clone(&shutdown);
    let server_task = task::spawn(async move { server_loop(server_state, server_shutdown).await });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
            shutdown.store(true, Ordering::Relaxed);
        }
        res = server_task => {
            match res {
                Ok(Ok(())) => info!("server exited"),
                Ok(Err(e)) => error!("server error: {:?}", e),
                Err(e) => error!("server join error: {:?}", e),
            }
            shutdown.store(true, Ordering::Relaxed);
        }
    }

    let _ = monitor_task.await;
    info!("daemon stopped");
    Ok(())
}
