```rust
use serde::Serialize;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, MemoryRefreshKind, RefreshKind, System};

#[derive(Debug, Clone, Serialize)]
pub struct SystemSnapshot {
    pub cpu_usage_percent: f32,
    pub memory_used_bytes: u64,
    pub memory_total_bytes: u64,
    pub memory_usage_percent: f32,
    pub disks: Vec<DiskSnapshot>,
    pub processes: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct DiskSnapshot {
    pub name: String,
    pub mount_point: String,
    pub total_space: u64,
    pub available_space: u64,
    pub used_percent: f32,
}

pub struct MetricsCollector {
    system: System,
    disks: Disks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything());

        let mut system = System::new_with_specifics(refresh);
        system.refresh_cpu();
        system.refresh_memory();

        let disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

        Self { system, disks }
    }

    pub fn sample(&mut self) -> SystemSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh();

        let cpu = self.system.global_cpu_info().cpu_usage();
        let mem_total = self.system.total_memory();
        let mem_used = self.system.used_memory();
        let mem_pct = if mem_total == 0 {
            0.0
        } else {
            (mem_used as f32 / mem_total as f32) * 100.0
        };

        let disks = self
            .disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                let used_percent = if total == 0 {
                    0.0
                } else {
                    (used as f32 / total as f32) * 100.0
                };

                DiskSnapshot {
                    name: d.name().to_string_lossy().to_string(),
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    total_space: total,
                    available_space: avail,
                    used_percent,
                }
            })
            .collect::<Vec<_>>();

        SystemSnapshot {
            cpu_usage_percent: cpu,
            memory_used_bytes: mem_used,
            memory_total_bytes: mem_total,
            memory_usage_percent: mem_pct,
            disks,
            processes: self.system.processes().len(),
        }
    }
}
