use crate::{config::Config, metrics::SystemSnapshot};
use tracing::{info, warn};

pub fn evaluate_and_act(cfg: &Config, snapshot: &SystemSnapshot) {
    if snapshot.cpu_usage_percent >= cfg.cpu_alert_threshold && cfg.actions.log_alerts {
        warn!(
            cpu_usage_percent = snapshot.cpu_usage_percent,
            threshold = cfg.cpu_alert_threshold,
            "cpu threshold exceeded"
        );
    }

    if snapshot.memory_usage_percent >= cfg.memory_alert_threshold && cfg.actions.log_alerts {
        warn!(
            memory_usage_percent = snapshot.memory_usage_percent,
            threshold = cfg.memory_alert_threshold,
            "memory threshold exceeded"
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= cfg.disk_alert_threshold && cfg.actions.log_alerts {
            warn!(
                disk = %disk.mount_point,
                used_percent = disk.used_percent,
                threshold = cfg.disk_alert_threshold,
                "disk threshold exceeded"
            );
        }
    }

    info!(
        cpu = snapshot.cpu_usage_percent,
        mem = snapshot.memory_usage_percent,
        procs = snapshot.processes,
        "sample collected"
    );
}
