# src/control.rs

```rust
use crate::daemon::SharedState;
use anyhow::Result;
use serde_json::json;
use std::path::Path;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{error, info};

pub async fn run_control_socket<P: AsRef<Path>>(path: P, state: SharedState) -> Result<()> {
    let path = path.as_ref();

    if path.exists() {
        let _ = std::fs::remove_file(path);
    }

    let listener = UnixListener::bind(path)?;
    info!(socket = %path.display(), "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!(error = %e, "control client error");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"{\"message\":\"sysmond control ready\"}\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        let response = match cmd {
            "ping" => json!({ "ok": true, "reply": "pong" }),
            "snapshot" => {
                let snapshot = state.latest_snapshot.lock().clone();
                json!({ "ok": true, "snapshot": snapshot })
            }
            "status" => {
                let uptime = state.started_at.elapsed().as_secs();
                json!({
                    "ok": true,
                    "uptime_secs": uptime,
                    "samples_collected": *state.samples_collected.lock()
                })
            }
            _ => json!({ "ok": false, "error": "unknown command" }),
        };

        writer.write_all(response.to_string().as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}
