# src/daemon.rs

```rust
use crate::{
    actions::evaluate_and_act,
    config::Config,
    metrics::{MetricsCollector, SystemSnapshot},
};
use anyhow::Result;
use parking_lot::Mutex;
use std::{sync::Arc, time::{Duration, Instant}};
use tokio::{signal, time};
use tracing::info;

#[derive(Clone)]
pub struct SharedState {
    pub latest_snapshot: Arc<Mutex<Option<SystemSnapshot>>>,
    pub samples_collected: Arc<Mutex<u64>>,
    pub started_at: Instant,
}

impl SharedState {
    pub fn new() -> Self {
        Self {
            latest_snapshot: Arc::new(Mutex::new(None)),
            samples_collected: Arc::new(Mutex::new(0)),
            started_at: Instant::now(),
        }
    }
}

pub async fn run_daemon(cfg: Config) -> Result<()> {
    let state = SharedState::new();

    let control_state = state.clone();
    let socket_path = cfg.socket_path.clone();
    tokio::spawn(async move {
        if let Err(e) = crate::control::run_control_socket(socket_path, control_state).await {
            tracing::error!(error = %e, "control socket failed");
        }
    });

    let mut collector = MetricsCollector::new();
    let mut ticker = time::interval(Duration::from_millis(cfg.sample_interval_ms));

    info!("daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = collector.sample();
                evaluate_and_act(&cfg, &snapshot);

                *state.latest_snapshot.lock() = Some(snapshot);
                *state.samples_collected.lock() += 1;
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    Ok(())
}
```

