use anyhow::Result;
use collector::Collector;
use control::ControlServer;
use policy::PolicyEngine;
use state::{DaemonConfig, SharedState};
use std::sync::Arc;
use tokio::signal;
use tracing::{error, info};

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = DaemonConfig::default();
    let state = Arc::new(SharedState::new(config.clone()));

    let collector = Collector::new(state.clone(), config.clone());
    let policy = PolicyEngine::new(state.clone(), config.clone());
    let control = ControlServer::new(state.clone(), "/tmp/os-resource-daemon.sock");

    let collector_task = tokio::spawn(async move {
        if let Err(e) = collector.run().await {
            error!("collector failed: {e:?}");
        }
    });

    let policy_task = tokio::spawn(async move {
        if let Err(e) = policy.run().await {
            error!("policy engine failed: {e:?}");
        }
    });

    let control_task = tokio::spawn(async move {
        if let Err(e) = control.run().await {
            error!("control server failed: {e:?}");
        }
    });

    info!("daemon started");

    signal::ctrl_c().await?;
    info!("shutdown signal received");

    collector_task.abort();
    policy_task.abort();
    control_task.abort();

    Ok(())
}
