use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, SystemTime};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct DaemonConfig {
    pub sample_interval_ms: u64,
    pub policy_interval_ms: u64,
    pub cpu_high_watermark: f32,
    pub memory_high_watermark: f32,
    pub max_processes: usize,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            policy_interval_ms: 2000,
            cpu_high_watermark: 90.0,
            memory_high_watermark: 90.0,
            max_processes: 4096,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ProcessInfo {
    pub pid: i32,
    pub name: String,
    pub cpu_percent: f32,
    pub memory_bytes: u64,
    pub status: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SystemSnapshot {
    pub timestamp_ms: u128,
    pub total_memory: u64,
    pub used_memory: u64,
    pub total_swap: u64,
    pub used_swap: u64,
    pub cpu_usage_percent: f32,
    pub load_avg_one: f64,
    pub process_count: usize,
    pub top_processes: Vec<ProcessInfo>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Alert {
    pub timestamp_ms: u128,
    pub severity: String,
    pub message: String,
}

pub struct SharedState {
    pub config: DaemonConfig,
    snapshot: RwLock<Option<SystemSnapshot>>,
    alerts: RwLock<Vec<Alert>>,
    metadata: RwLock<HashMap<String, String>>,
}

impl SharedState {
    pub fn new(config: DaemonConfig) -> Self {
        Self {
            config,
            snapshot: RwLock::new(None),
            alerts: RwLock::new(Vec::new()),
            metadata: RwLock::new(HashMap::new()),
        }
    }

    pub fn update_snapshot(&self, snapshot: SystemSnapshot) {
        *self.snapshot.write() = Some(snapshot);
    }

    pub fn get_snapshot(&self) -> Option<SystemSnapshot> {
        self.snapshot.read().clone()
    }

    pub fn add_alert(&self, alert: Alert) {
        self.alerts.write().push(alert);
    }

    pub fn get_alerts(&self) -> Vec<Alert> {
        self.alerts.read().clone()
    }

    pub fn set_metadata(&self, key: String, value: String) {
        self.metadata.write().insert(key, value);
    }

    pub fn get_metadata(&self) -> HashMap<String, String> {
        self.metadata.read().clone()
    }
}

pub fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_millis()
}
