## src/collector.rs

```rust
use crate::state::{now_ms, DaemonConfig, ProcessInfo, SharedState, SystemSnapshot};
use anyhow::Result;
use std::cmp::Ordering;
use std::sync::Arc;
use std::time::Duration;
use sysinfo::{LoadAvg, ProcessStatus, System};
use tokio::time::interval;
use tracing::debug;

pub struct Collector {
    state: Arc<SharedState>,
    config: DaemonConfig,
}

impl Collector {
    pub fn new(state: Arc<SharedState>, config: DaemonConfig) -> Self {
        Self { state, config }
    }

    pub async fn run(self) -> Result<()> {
        let mut sys = System::new_all();
        let mut ticker = interval(Duration::from_millis(self.config.sample_interval_ms));

        loop {
            ticker.tick().await;

            sys.refresh_memory();
            sys.refresh_cpu();
            sys.refresh_processes();

            let load = System::load_average();

            let mut processes: Vec<ProcessInfo> = sys
                .processes()
                .values()
                .map(|p| ProcessInfo {
                    pid: p.pid().as_u32() as i32,
                    name: p.name().to_string(),
                    cpu_percent: p.cpu_usage(),
                    memory_bytes: p.memory(),
                    status: format!("{:?}", p.status()),
                })
                .collect();

            processes.sort_by(|a, b| {
                b.cpu_percent
                    .partial_cmp(&a.cpu_percent)
                    .unwrap_or(Ordering::Equal)
            });

            processes.truncate(20);

            let snapshot = SystemSnapshot {
                timestamp_ms: now_ms(),
                total_memory: sys.total_memory(),
                used_memory: sys.used_memory(),
                total_swap: sys.total_swap(),
                used_swap: sys.used_swap(),
                cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
                load_avg_one: load.one,
                process_count: sys.processes().len(),
                top_processes: processes,
            };

            self.state.update_snapshot(snapshot);
            debug!("snapshot updated");
        }
    }
}
