## src/policy.rs

```rust
use crate::actions::ActionExecutor;
use crate::state::{now_ms, Alert, DaemonConfig, SharedState};
use anyhow::Result;
use std::sync::Arc;
use std::time::Duration;
use tokio::time::interval;
use tracing::{info, warn};

pub struct PolicyEngine {
    state: Arc<SharedState>,
    config: DaemonConfig,
    actions: ActionExecutor,
}

impl PolicyEngine {
    pub fn new(state: Arc<SharedState>, config: DaemonConfig) -> Self {
        Self {
            state,
            config,
            actions: ActionExecutor::new(),
        }
    }

    pub async fn run(self) -> Result<()> {
        let mut ticker = interval(Duration::from_millis(self.config.policy_interval_ms));

        loop {
            ticker.tick().await;

            let Some(snapshot) = self.state.get_snapshot() else {
                continue;
            };

            let mem_pct = if snapshot.total_memory > 0 {
                (snapshot.used_memory as f32 / snapshot.total_memory as f32) * 100.0
            } else {
                0.0
            };

            if snapshot.cpu_usage_percent >= self.config.cpu_high_watermark {
                let msg = format!(
                    "high cpu usage detected: {:.2}%",
                    snapshot.cpu_usage_percent
                );
                warn!("{msg}");
                self.state.add_alert(Alert {
                    timestamp_ms: now_ms(),
                    severity: "warning".into(),
                    message: msg.clone(),
                });
            }

            if mem_pct >= self.config.memory_high_watermark {
                let msg = format!("high memory usage detected: {:.2}%", mem_pct);
                warn!("{msg}");
                self.state.add_alert(Alert {
                    timestamp_ms: now_ms(),
                    severity: "warning".into(),
                    message: msg.clone(),
                });
            }

            if snapshot.process_count > self.config.max_processes {
                let msg = format!(
                    "process count exceeded limit: {} > {}",
                    snapshot.process_count, self.config.max_processes
                );
                warn!("{msg}");
                self.state.add_alert(Alert {
                    timestamp_ms: now_ms(),
                    severity: "critical".into(),
                    message: msg.clone(),
                });

                self.actions.record_event("process_limit_exceeded", &msg).await?;
            }

            info!("policy evaluation complete");
        }
    }
}
