## src/control.rs

```rust
use crate::state::SharedState;
use anyhow::{anyhow, Result};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::fs;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tracing::{error, info};

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum ControlCommand {
    GetSnapshot,
    GetAlerts,
    GetMetadata,
    SetMetadata { key: String, value: String },
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ControlResponse {
    pub ok: bool,
    pub data: serde_json::Value,
    pub error: Option<String>,
}

pub struct ControlServer {
    state: Arc<SharedState>,
    socket_path: String,
}

impl ControlServer {
    pub fn new(state: Arc<SharedState>, socket_path: impl Into<String>) -> Self {
        Self {
            state,
            socket_path: socket_path.into(),
        }
    }

    pub async fn run(self) -> Result<()> {
        let _ = fs::remove_file(&self.socket_path).await;
        let listener = UnixListener::bind(&self.socket_path)?;

        info!("control socket listening at {}", self.socket_path);

        loop {
            let (stream, _) = listener.accept().await?;
            let state = self.state.clone();
            tokio::spawn(async move {
                if let Err(e) = handle_client(state, stream).await {
                    error!("client error: {e:?}");
                }
            });
        }
    }
}

async fn handle_client(state: Arc<SharedState>, stream: UnixStream) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd: ControlCommand = serde_json::from_str(line.trim())
            .map_err(|e| anyhow!("invalid command: {e}"))?;

        let response = match cmd {
            ControlCommand::GetSnapshot => ControlResponse {
                ok: true,
                data: serde_json::to_value(state.get_snapshot())?,
                error: None,
            },
            ControlCommand::GetAlerts => ControlResponse {
                ok: true,
                data: serde_json::to_value(state.get_alerts())?,
                error: None,
            },
            ControlCommand::GetMetadata => ControlResponse {
                ok: true,
                data: serde_json::to_value(state.get_metadata())?,
                error: None,
            },
            ControlCommand::SetMetadata { key, value } => {
                state.set_metadata(key, value);
                ControlResponse {
                    ok: true,
                    data: serde_json::json!({"status": "updated"}),
                    error: None,
                }
            }
            ControlCommand::Ping => ControlResponse {
                ok: true,
                data: serde_json::json!({"pong": true}),
                error: None,
            },
        };

        let encoded = serde_json::to_string(&response)?;
        writer.write_all(encoded.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}
