```rust
use std::time::{SystemTime, UNIX_EPOCH};

use sysinfo::{Disks, LoadAvg, System};

use crate::types::ResourceSnapshot;

pub struct MetricsCollector {
    system: System,
    disks: Disks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self { system, disks }
    }

    pub fn collect(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh();

        let cpu_percent = self.system.global_cpu_info().cpu_usage();

        let total_memory_bytes = self.system.total_memory() * 1024;
        let used_memory_bytes = self.system.used_memory() * 1024;
        let memory_percent = if total_memory_bytes == 0 {
            0.0
        } else {
            (used_memory_bytes as f32 / total_memory_bytes as f32) * 100.0
        };

        let mut total_disk_bytes = 0u64;
        let mut used_disk_bytes = 0u64;
        for disk in self.disks.list() {
            let total = disk.total_space();
            let avail = disk.available_space();
            total_disk_bytes += total;
            used_disk_bytes += total.saturating_sub(avail);
        }

        let disk_percent = if total_disk_bytes == 0 {
            0.0
        } else {
            (used_disk_bytes as f32 / total_disk_bytes as f32) * 100.0
        };

        let process_count = self.system.processes().len();
        let LoadAvg { one, five, fifteen } = System::load_average();

        let timestamp_unix_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();

        ResourceSnapshot {
            timestamp_unix_ms,
            cpu_percent,
            memory_percent,
            used_memory_bytes,
            total_memory_bytes,
            disk_percent,
            used_disk_bytes,
            total_disk_bytes,
            process_count,
            load_avg_1: one,
            load_avg_5: five,
            load_avg_15: fifteen,
        }
    }
}
