use tracing::{info, warn};

use crate::types::{ResourceSnapshot, Thresholds};

pub struct PolicyEngine;

impl PolicyEngine {
    pub fn evaluate(snapshot: &ResourceSnapshot, thresholds: &Thresholds) {
        if snapshot.cpu_percent >= thresholds.cpu_percent {
            warn!(
                cpu = snapshot.cpu_percent,
                threshold = thresholds.cpu_percent,
                "CPU threshold exceeded"
            );
        }

        if snapshot.memory_percent >= thresholds.memory_percent {
            warn!(
                memory = snapshot.memory_percent,
                threshold = thresholds.memory_percent,
                "Memory threshold exceeded"
            );
        }

        if snapshot.disk_percent >= thresholds.disk_percent {
            warn!(
                disk = snapshot.disk_percent,
                threshold = thresholds.disk_percent,
                "Disk threshold exceeded"
            );
        }

        if snapshot.load_avg_1 >= thresholds.load_avg_1 {
            warn!(
                load_avg_1 = snapshot.load_avg_1,
                threshold = thresholds.load_avg_1,
                "Load average threshold exceeded"
            );
        }

        if snapshot.process_count >= thresholds.process_count {
            warn!(
                process_count = snapshot.process_count,
                threshold = thresholds.process_count,
                "Process count threshold exceeded"
            );
        }

        info!("Policy evaluation complete");
    }
}
