```rust
use std::{path::Path, sync::Arc};

use anyhow::Context;
use parking_lot::RwLock;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::broadcast,
};
use tracing::{error, info};

use crate::{
    config::DaemonConfig,
    types::{ControlRequest, ControlResponse, ResourceSnapshot, Thresholds},
};

#[derive(Clone)]
pub struct SharedState {
    pub latest_snapshot: Arc<RwLock<Option<ResourceSnapshot>>>,
    pub config: Arc<RwLock<DaemonConfig>>,
}

pub async fn run_control_server(
    state: SharedState,
    shutdown_tx: broadcast::Sender<()>,
) -> anyhow::Result<()> {
    let socket_path = state.config.read().socket_path.clone();

    if Path::new(&socket_path).exists() {
        std::fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove existing socket: {}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket: {}", socket_path))?;

    info!(socket = %socket_path, "control server listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        let shutdown_tx = shutdown_tx.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                error!(error = %e, "client handling failed");
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    state: SharedState,
    shutdown_tx: broadcast::Sender<()>,
) -> anyhow::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let bytes = reader.read_line(&mut line).await?;
    if bytes == 0 {
        return Ok(());
    }

    let req: ControlRequest = serde_json::from_str(line.trim())?;

    let resp = match req {
        ControlRequest::GetStatus => {
            let snapshot = state.latest_snapshot.read().clone();
            match snapshot {
                Some(s) => ControlResponse::Status(s),
                None => ControlResponse::Error("no snapshot available yet".into()),
            }
        }
        ControlRequest::GetConfig => {
            let cfg = state.config.read().clone();
            ControlResponse::Config(cfg)
        }
        ControlRequest::SetThresholds(thresholds) => {
            update_thresholds(&state, thresholds);
            ControlResponse::Ack("thresholds updated".into())
        }
        ControlRequest::Shutdown => {
            let _ = shutdown_tx.send(());
            ControlResponse::Ack("shutdown initiated".into())
        }
    };

    let payload = serde_json::to_vec(&resp)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;

    Ok(())
}

fn update_thresholds(state: &SharedState, thresholds: Thresholds) {
    let mut cfg = state.config.write();
    cfg.thresholds = thresholds;
}
