# `src/daemon.rs`

```rust
use std::sync::Arc;
use std::time::Duration;

use parking_lot::RwLock;
use tokio::sync::broadcast;
use tracing::{error, info};

use crate::{
    config::DaemonConfig,
    control::{run_control_server, SharedState},
    metrics::MetricsCollector,
    policy::PolicyEngine,
    types::ResourceSnapshot,
};

pub struct Daemon {
    config: Arc<RwLock<DaemonConfig>>,
    latest_snapshot: Arc<RwLock<Option<ResourceSnapshot>>>,
}

impl Daemon {
    pub fn new(config: DaemonConfig) -> Self {
        Self {
            config: Arc::new(RwLock::new(config)),
            latest_snapshot: Arc::new(RwLock::new(None)),
        }
    }

    pub async fn run(self) -> anyhow::Result<()> {
        let (shutdown_tx, mut shutdown_rx) = broadcast::channel::<()>(8);

        let shared = SharedState {
            latest_snapshot: self.latest_snapshot.clone(),
            config: self.config.clone(),
        };

        let control_task = {
            let shared = shared.clone();
            let shutdown_tx = shutdown_tx.clone();
            tokio::spawn(async move { run_control_server(shared, shutdown_tx).await })
        };

        let monitor_task = {
            let config = self.config.clone();
            let latest_snapshot = self.latest_snapshot.clone();
            let mut shutdown_rx = shutdown_tx.subscribe();

            tokio::spawn(async move {
                let mut collector = MetricsCollector::new();

                loop {
                    if shutdown_rx.try_recv().is_ok() {
                        info!("monitor task received shutdown");
                        break;
                    }

                    let snapshot = collector.collect();

                    {
                        let mut guard = latest_snapshot.write();
                        *guard = Some(snapshot.clone());
                    }

                    let thresholds = {
                        let cfg = config.read();
                        cfg.thresholds.clone()
                    };

                    PolicyEngine::evaluate(&snapshot, &thresholds);

                    let interval = {
                        let cfg = config.read();
                        cfg.poll_interval_ms
                    };

                    tokio::time::sleep(Duration::from_millis(interval)).await;
                }

                Ok::<(), anyhow::Error>(())
            })
        };

        tokio::select! {
            res = control_task => {
                match res {
                    Ok(Ok(())) => info!("control task exited"),
                    Ok(Err(e)) => error!(error = %e, "control task failed"),
                    Err(e) => error!(error = %e, "control task join failed"),
                }
            }
            res = monitor_task => {
                match res {
                    Ok(Ok(())) => info!("monitor task exited"),
                    Ok(Err(e)) => error!(error = %e, "monitor task failed"),
                    Err(e) => error!(error = %e, "monitor task join failed"),
                }
            }
            _ = shutdown_rx.recv() => {
                info!("daemon received shutdown signal");
            }
        }

        Ok(())
    }
}
