use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::broadcast;
use tokio::time;

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const TOP_N_DEFAULT: usize = 10;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: i32,
    parent: Option<i32>,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
    run_time_secs: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SystemSnapshot {
    timestamp_unix: u64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    cpu_usage_percent: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    process_count: usize,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<SystemSnapshot>,
    process_index: HashMap<i32, ProcessInfo>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetSnapshot,
    ListProcesses { limit: Option<usize>, sort_by: Option<String> },
    SignalProcess { pid: i32, signal: String },
    Ping,
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    OkSnapshot { snapshot: SystemSnapshot },
    OkProcesses { processes: Vec<ProcessInfo> },
    OkMessage { message: String },
    Error { message: String },
    Pong,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    let state: State = Arc::new(RwLock::new(SharedState::default()));
    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let monitor_state = Arc::clone(&state);
    let mut monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, &mut monitor_shutdown).await {
            eprintln!("monitor loop error: {e:#}");
        }
    });

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    let server_state = Arc::clone(&state);
    let mut server_shutdown = shutdown_tx.subscribe();

    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(listener, server_state, &mut server_shutdown).await {
            eprintln!("server loop error: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            eprintln!("shutdown signal received");
        }
    }

    let _ = shutdown_tx.send(());
    let _ = monitor_task.await;
    let _ = server_task.await;

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

async fn monitor_loop(state: State, shutdown: &mut broadcast::Receiver<()>) -> Result<()> {
    let refresh = RefreshKind::new()
        .with_cpu(CpuRefreshKind::everything())
        .with_processes(ProcessRefreshKind::everything());

    let mut sys = System::new_with_specifics(refresh);
    let mut ticker = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                break;
            }
            _ = ticker.tick() => {
                sys.refresh_memory();
                sys.refresh_cpu();
                sys.refresh_processes();

                let total_memory_bytes = sys.total_memory() * 1024;
                let used_memory_bytes = sys.used_memory() * 1024;
                let total_swap_bytes = sys.total_swap() * 1024;
                let used_swap_bytes = sys.used_swap() * 1024;

                let cpu_usage_percent = if sys.cpus().is_empty() {
                    0.0
                } else {
                    let sum: f32 = sys.cpus().iter().map(|c| c.cpu_usage()).sum();
                    sum / sys.cpus().len() as f32
                };

                let load = System::load_average();

                let mut processes: Vec<ProcessInfo> = sys.processes()
                    .iter()
                    .map(|(pid, p)| ProcessInfo {
                        pid: pid.as_u32() as i32,
                        parent: p.parent().map(|pp| pp.as_u32() as i32),
                        name: p.name().to_string(),
                        cpu_percent: p.cpu_usage(),
                        memory_bytes: p.memory() * 1024,
                        virtual_memory_bytes: p.virtual_memory() * 1024,
                        status: format!("{:?}", p.status()),
                        run_time_secs: p.run_time(),
                    })
                    .collect();

                processes.sort_by(|a, b| {
                    b.cpu_percent
                        .partial_cmp(&a.cpu_percent)
                        .unwrap_or(std::cmp::Ordering::Equal)
                });

                let top_processes = processes.iter().take(TOP_N_DEFAULT).cloned().collect::<Vec<_>>();
                let process_index = processes
                    .into_iter()
                    .map(|p| (p.pid, p))
                    .collect::<HashMap<_, _>>();

                let snapshot = SystemSnapshot {
                    timestamp_unix: now_unix(),
                    total_memory_bytes,
                    used_memory_bytes,
                    total_swap_bytes,
                    used_swap_bytes,
                    cpu_usage_percent,
                    load_avg_one: load.one,
                    load_avg_five: load.five,
                    load_avg_fifteen: load.fifteen,
                    process_count: process_index.len(),
                    top_processes,
                };

                let mut guard = state.write();
                guard.latest = Some(snapshot);
                guard.process_index = process_index;
            }
        }
    }

    Ok(())
}

async fn server_loop(
    listener: UnixListener,
    state: State,
    shutdown: &mut broadcast::Receiver<()>,
) -> Result<()> {
    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                break;
            }
            accept_result = listener.accept() => {
                let (stream, _) = accept_result.context("accepting client")?;
                let client_state = Arc::clone(&state);
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, client_state).await {
                        eprintln!("client error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: State) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await.context("reading client line")? {
        let req: Request = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid request: {e}"),
                };
                write_response(&mut writer, &resp).await?;
                continue;
            }
        };

        let resp = process_request(req, &state).await;
        write_response(&mut writer, &resp).await?;
    }

    Ok(())
}

async fn process_request(req: Request, state: &State) -> Response {
    match req {
        Request::GetSnapshot => {
            let guard = state.read();
            match &guard.latest {
                Some(snapshot) => Response::OkSnapshot {
                    snapshot: snapshot.clone(),
                },
                None => Response::Error {
                    message: "no snapshot available yet".to_string(),
                },
            }
        }
        Request::ListProcesses { limit, sort_by } => {
            let guard = state.read();
            let mut processes = guard.process_index.values().cloned().collect::<Vec<_>>();

            match sort_by.as_deref() {
                Some("memory") => {
                    processes.sort_by(|a, b| b.memory_bytes.cmp(&a.memory_bytes));
                }
                Some("pid") => {
                    processes.sort_by(|a, b| a.pid.cmp(&b.pid));
                }
                _ => {
                    processes.sort_by(|a, b| {
                        b.cpu_percent
                            .partial_cmp(&a.cpu_percent)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    });
                }
            }

            let limit = limit.unwrap_or(TOP_N_DEFAULT).min(processes.len());
            processes.truncate(limit);

            Response::OkProcesses { processes }
        }
        Request::SignalProcess { pid, signal } => {
            match parse_signal(&signal) {
                Ok(sig) => match kill(Pid::from_raw(pid), sig) {
                    Ok(_) => Response::OkMessage {
                        message: format!("signal {signal} sent to pid {pid}"),
                    },
                    Err(e) => Response::Error {
                        message: format!("failed to signal pid {pid}: {e}"),
                    },
                },
                Err(msg) => Response::Error { message: msg },
            }
        }
        Request::Ping => Response::Pong,
    }
}

fn parse_signal(s: &str) -> std::result::Result<Signal, String> {
    match s.to_ascii_uppercase().as_str() {
        "TERM" | "SIGTERM" => Ok(Signal::SIGTERM),
        "KILL" | "SIGKILL" => Ok(Signal::SIGKILL),
        "INT" | "SIGINT" => Ok(Signal::SIGINT),
        "HUP" | "SIGHUP" => Ok(Signal::SIGHUP),
        "STOP" | "SIGSTOP" => Ok(Signal::SIGSTOP),
        other => Err(format!("unsupported signal: {other}")),
    }
}

async fn write_response<W>(writer: &mut W, resp: &Response) -> Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let s = serde_json::to_string(resp).context("serializing response")?;
    writer.write_all(s.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
```

