# src/main.rs

```rust
use anyhow::{Context, Result};
use arc_swap::ArcSwap;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::fs;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, PidExt, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::broadcast;
use tokio::time;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    socket_path: String,
    top_process_count: usize,
    cpu: Thresholds,
    memory: Thresholds,
    disk: Thresholds,
    actions: ActionsConfig,
}

#[derive(Debug, Clone, Deserialize)]
struct Thresholds {
    warn: f32,
    critical: f32,
}

#[derive(Debug, Clone, Deserialize)]
struct ActionsConfig {
    kill_on_critical_memory: bool,
    renice_on_critical_cpu: bool,
    renice_value: i32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    memory_usage_percent: f32,
    swap_used_bytes: u64,
    swap_total_bytes: u64,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    disks: Vec<DiskInfo>,
    top_cpu_processes: Vec<ProcessInfo>,
    top_mem_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Clone)]
struct AppState {
    config_path: String,
    config: Arc<RwLock<Config>>,
    metrics: Arc<ArcSwap<MetricsSnapshot>>,
    shutdown_tx: broadcast::Sender<()>,
}

fn load_config(path: &str) -> Result<Config> {
    let raw = fs::read_to_string(path).with_context(|| format!("reading config {}", path))?;
    let cfg = toml::from_str::<Config>(&raw).context("parsing config")?;
    Ok(cfg)
}

fn now_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn process_to_info(p: &sysinfo::Process) -> ProcessInfo {
    ProcessInfo {
        pid: p.pid().as_u32() as i32,
        name: p.name().to_string(),
        cpu: p.cpu_usage(),
        memory_bytes: p.memory(),
        virtual_memory_bytes: p.virtual_memory(),
        status: format!("{:?}", p.status()),
    }
}

fn collect_metrics(sys: &System, top_n: usize) -> MetricsSnapshot {
    let cpu_usage = sys.global_cpu_info().cpu_usage();

    let memory_total = sys.total_memory();
    let memory_used = sys.used_memory();
    let memory_usage_percent = if memory_total == 0 {
        0.0
    } else {
        (memory_used as f32 / memory_total as f32) * 100.0
    };

    let swap_total = sys.total_swap();
    let swap_used = sys.used_swap();

    let load = sys.load_average();

    let mut processes: Vec<_> = sys.processes().values().collect();

    let mut by_cpu = processes.clone();
    by_cpu.sort_by(|a, b| {
        b.cpu_usage()
            .partial_cmp(&a.cpu_usage())
            .unwrap_or(Ordering::Equal)
    });

    let mut by_mem = processes;
    by_mem.sort_by(|a, b| b.memory().cmp(&a.memory()));

    let top_cpu_processes = by_cpu
        .into_iter()
        .take(top_n)
        .map(process_to_info)
        .collect();

    let top_mem_processes = by_mem
        .into_iter()
        .take(top_n)
        .map(process_to_info)
        .collect();

    let disks = sys
        .disks()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total == 0 {
                0.0
            } else {
                (used as f32 / total as f32) * 100.0
            };

            DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            }
        })
        .collect();

    MetricsSnapshot {
        timestamp_unix_ms: now_unix_ms(),
        cpu_usage_percent: cpu_usage,
        memory_used_bytes: memory_used,
        memory_total_bytes: memory_total,
        memory_usage_percent,
        swap_used_bytes: swap_used,
        swap_total_bytes: swap_total,
        loadavg_one: load.one,
        loadavg_five: load.five,
        loadavg_fifteen: load.fifteen,
        disks,
        top_cpu_processes,
        top_mem_processes,
    }
}

fn evaluate_policies(state: &AppState, snapshot: &MetricsSnapshot) {
    let cfg = state.config.read().clone();

    if snapshot.memory_usage_percent >= cfg.memory.critical {
        warn!(
            memory_usage_percent = snapshot.memory_usage_percent,
            threshold = cfg.memory.critical,
            "critical memory threshold exceeded"
        );

        if cfg.actions.kill_on_critical_memory {
            if let Some(proc_) = snapshot
                .top_mem_processes
                .iter()
                .find(|p| p.pid > 1)
            {
                match kill(Pid::from_raw(proc_.pid), Signal::SIGTERM) {
                    Ok(_) => warn!(pid = proc_.pid, name = %proc_.name, "terminated process due to critical memory"),
                    Err(e) => error!(pid = proc_.pid, err = %e, "failed to terminate process"),
                }
            }
        }
    } else if snapshot.memory_usage_percent >= cfg.memory.warn {
        warn!(
            memory_usage_percent = snapshot.memory_usage_percent,
            threshold = cfg.memory.warn,
            "memory warning threshold exceeded"
        );
    }

    if snapshot.cpu_usage_percent >= cfg.cpu.critical {
        warn!(
            cpu_usage_percent = snapshot.cpu_usage_percent,
            threshold = cfg.cpu.critical,
            "critical cpu threshold exceeded"
        );

        if cfg.actions.renice_on_critical_cpu {
            if let Some(proc_) = snapshot
                .top_cpu_processes
                .iter()
                .find(|p| p.pid > 1)
            {
                let who = proc_.pid as u32;
                let prio = cfg.actions.renice_value;
                match nix::sys::resource::setpriority(
                    nix::sys::resource::Which::PRIO_PROCESS,
                    who,
                    prio,
                ) {
                    Ok(_) => warn!(pid = proc_.pid, name = %proc_.name, nice = prio, "reniced process due to critical cpu"),
                    Err(e) => error!(pid = proc_.pid, err = %e, "failed to renice process"),
                }
            }
        }
    } else if snapshot.cpu_usage_percent >= cfg.cpu.warn {
        warn!(
            cpu_usage_percent = snapshot.cpu_usage_percent,
            threshold = cfg.cpu.warn,
            "cpu warning threshold exceeded"
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= cfg.disk.critical {
            warn!(
                mount = %disk.mount_point,
                used_percent = disk.used_percent,
                threshold = cfg.disk.critical,
                "critical disk threshold exceeded"
            );
        } else if disk.used_percent >= cfg.disk.warn {
            warn!(
                mount = %disk.mount_point,
                used_percent = disk.used_percent,
                threshold = cfg.disk.warn,
                "disk warning threshold exceeded"
            );
        }
    }
}

async fn monitor_loop(state: AppState) {
    let cfg = state.config.read().clone();
    let mut interval = time::interval(Duration::from_millis(cfg.sample_interval_ms));

    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    loop {
        interval.tick().await;

        let cfg = state.config.read().clone();

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks();

        let snapshot = collect_metrics(&sys, cfg.top_process_count);
        evaluate_policies(&state, &snapshot);
        state.metrics.store(Arc::new(snapshot));
    }
}

async fn handle_client(stream: UnixStream, state: AppState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"osd ready\n")
        .await
        .context("writing greeting")?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        let parts: Vec<&str> = cmd.split_whitespace().collect();

        match parts.as_slice() {
            ["status"] => {
                writer.write_all(b"ok\n").await?;
            }
            ["metrics"] => {
                let snapshot = state.metrics.load();
                let body = serde_json::to_string_pretty(&*snapshot)?;
                writer.write_all(body.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            ["top"] => {
                let snapshot = state.metrics.load();
                let body = serde_json::to_string_pretty(&serde_json::json!({
                    "top_cpu_processes": snapshot.top_cpu_processes,
                    "top_mem_processes": snapshot.top_mem_processes
                }))?;
                writer.write_all(body.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            ["kill", pid] => {
                let pid: i32 = pid.parse().context("invalid pid")?;
                kill(Pid::from_raw(pid), Signal::SIGTERM)?;
                writer.write_all(b"ok\n").await?;
            }
            ["renice", pid, nice] => {
                let pid: u32 = pid.parse().context("invalid pid")?;
                let nice: i32 = nice.parse().context("invalid nice")?;
                nix::sys::resource::setpriority(
                    nix::sys::resource::Which::PRIO_PROCESS,
                    pid,
                    nice,
                )?;
                writer.write_all(b"ok\n").await?;
            }
            ["reload"] => {
                let cfg = load_config(&state.config_path)?;
                *state.config.write() = cfg;
                writer.write_all(b"ok\n").await?;
            }
            ["shutdown"] => {
                let _ = state.shutdown_tx.send(());
                writer.write_all(b"shutting down\n").await?;
                break;
            }
            _ => {
                writer
                    .write_all(b"unknown command\n")
                    .await?;
            }
        }
    }

    Ok(())
}

async fn socket_server(state: AppState) -> Result<()> {
    let socket_path = state.config.read().socket_path.clone();

    if Path::new(&socket_path).exists() {
        fs::remove_file(&socket_path)
            .with_context(|| format!("removing stale socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("binding unix socket {}", socket_path))?;

    info!(socket = %socket_path, "control socket listening");

    let mut shutdown_rx = state.shutdown_tx.subscribe();

    loop {
        tokio::select! {
            res = listener.accept() => {
                let (stream, _) = res?;
                let state_clone = state.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state_clone).await {
                        error!(err = %e, "client handler error");
                    }
                });
            }
            _ = shutdown_rx.recv() => {
                info!("socket server shutting down");
                break;
            }
        }
    }

    if Path::new(&socket_path).exists() {
        let _ = fs::remove_file(&socket_path);
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_path = "config.toml".to_string();
    let config = load_config(&config_path)?;

    let initial_metrics = MetricsSnapshot {
        timestamp_unix_ms: now_unix_ms(),
        cpu_usage_percent: 0.0,
        memory_used_bytes: 0,
        memory_total_bytes: 0,
        memory_usage_percent: 0.0,
        swap_used_bytes: 0,
        swap_total_bytes: 0,
        loadavg_one: 0.0,
        loadavg_five: 0.0,
        loadavg_fifteen: 0.0,
        disks: Vec::new(),
        top_cpu_processes: Vec::new(),
        top_mem_processes: Vec::new(),
    };

    let (shutdown_tx, _) = broadcast::channel(8);

    let state = AppState {
        config_path,
        config: Arc::new(RwLock::new(config)),
        metrics: Arc::new(ArcSwap::from_pointee(initial_metrics)),
        shutdown_tx,
    };

    let monitor_state = state.clone();
    let server_state = state.clone();
    let mut shutdown_rx = state.shutdown_tx.subscribe();

    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = socket_server(server_state).await {
            error!(err = %e, "socket server failed");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
        }
        _ = shutdown_rx.recv() => {
            info!("received shutdown signal");
        }
    }

    let _ = state.shutdown_tx.send(());

    monitor_task.abort();
    let _ = server_task.await;

    info!("daemon exited");
    Ok(())
}
```

