```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    cmp::Ordering,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const TOP_N_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_usage_percent: f32,
    memory: u64,
    virtual_memory: u64,
    status: String,
}

#[derive(Debug, Default)]
struct DaemonState {
    latest: Option<MetricsSnapshot>,
    running: bool,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Status,
    Metrics,
    Top {
        limit: Option<usize>,
    },
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Status {
        running: bool,
        has_metrics: bool,
    },
    Metrics {
        snapshot: Option<MetricsSnapshot>,
    },
    Top {
        processes: Vec<ProcessInfo>,
    },
    Ok {
        message: String,
    },
    Error {
        message: String,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket at {}", SOCKET_PATH))?;
    }

    let state = Arc::new(RwLock::new(DaemonState {
        latest: None,
        running: true,
    }));

    let monitor_state = Arc::clone(&state);
    let server_state = Arc::clone(&state);

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state).await {
            error!("server loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
            let mut s = state.write().await;
            s.running = false;
        }
        _ = monitor_task => {
            warn!("monitor task exited");
            let mut s = state.write().await;
            s.running = false;
        }
        _ = server_task => {
            warn!("server task exited");
            let mut s = state.write().await;
            s.running = false;
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    info!("daemon shutdown complete");
    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn monitor_loop(state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let refresh = RefreshKind::new()
        .with_cpu(CpuRefreshKind::everything())
        .with_memory()
        .with_disks(DiskRefreshKind::everything())
        .with_processes(ProcessRefreshKind::everything());

    let mut sys = System::new_with_specifics(refresh);

    // Prime CPU/process counters for meaningful percentages.
    sys.refresh_all();
    time::sleep(Duration::from_millis(500)).await;

    let mut ticker = time::interval(SAMPLE_INTERVAL);

    loop {
        ticker.tick().await;

        {
            let s = state.read().await;
            if !s.running {
                break;
            }
        }

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks();
        sys.refresh_processes();

        let snapshot = build_snapshot(&sys);

        {
            let mut s = state.write().await;
            s.latest = Some(snapshot);
        }
    }

    Ok(())
}

fn build_snapshot(sys: &System) -> MetricsSnapshot {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let cpu_usage_percent = sys.global_cpu_info().cpu_usage();

    let disks = sys
        .disks()
        .iter()
        .map(|d| DiskInfo {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
        })
        .collect::<Vec<_>>();

    let mut processes = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32(),
            name: p.name().to_string(),
            cpu_usage_percent: p.cpu_usage(),
            memory: p.memory(),
            virtual_memory: p.virtual_memory(),
            status: format!("{:?}", p.status()),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_usage_percent
            .partial_cmp(&a.cpu_usage_percent)
            .unwrap_or(Ordering::Equal)
            .then_with(|| b.memory.cmp(&a.memory))
    });
    processes.truncate(TOP_N_PROCESSES);

    MetricsSnapshot {
        timestamp,
        cpu_usage_percent,
        total_memory: sys.total_memory(),
        used_memory: sys.used_memory(),
        total_swap: sys.total_swap(),
        used_swap: sys.used_swap(),
        disks,
        top_processes: processes,
    }
}

async fn server_loop(state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    info!("control socket listening on {}", SOCKET_PATH);

    loop {
        {
            let s = state.read().await;
            if !s.running {
                break;
            }
        }

        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handler error: {e:#}");
            }
        });
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Command = match serde_json::from_str(&line) {
            Ok(c) => c,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid command: {e}"),
                };
                write_response(&mut writer, &resp).await?;
                continue;
            }
        };

        let resp = process_command(cmd, &state).await;
        let should_shutdown = matches!(resp, Response::Ok { ref message } if message == "shutting down");

        write_response(&mut writer, &resp).await?;

        if should_shutdown {
            break;
        }
    }

    Ok(())
}

async fn process_command(cmd: Command, state: &Arc<RwLock<DaemonState>>) -> Response {
    match cmd {
        Command::Status => {
            let s = state.read().await;
            Response::Status {
                running: s.running,
                has_metrics: s.latest.is_some(),
            }
        }
        Command::Metrics => {
            let s = state.read().await;
            Response::Metrics {
                snapshot: s.latest.clone(),
            }
        }
        Command::Top { limit } => {
            let s = state.read().await;
            let mut procs = s
                .latest
                .as_ref()
                .map(|m| m.top_processes.clone())
                .unwrap_or_default();

            if let Some(limit) = limit {
                procs.truncate(limit);
            }

            Response::Top { processes: procs }
        }
        Command::Shutdown => {
            let mut s = state.write().await;
            s.running = false;
            Response::Ok {
                message: "shutting down".to_string(),
            }
        }
    }
}

async fn write_response<W>(writer: &mut W, resp: &Response) -> Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let json = serde_json::to_string(resp)?;
    writer.write_all(json.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}
```

