use std::time::Duration;
use sysinfo::System;
use tokio::signal;
use tokio::time;

fn cpu_usage_sample(sys: &mut System) -> f32 {
    sys.refresh_cpu();
    std::thread::sleep(Duration::from_millis(200));
    sys.refresh_cpu();
    sys.global_cpu_info().cpu_usage()
}

#[tokio::main]
async fn main() {
    let mut sys = System::new_all();
    let mut interval = time::interval(Duration::from_secs(5));

    println!("sysmon-daemon starting");

    loop {
        tokio::select! {
            _ = interval.tick() => {
                sys.refresh_memory();
                let cpu = cpu_usage_sample(&mut sys);
                let total_mem = sys.total_memory();
                let used_mem = sys.used_memory();

                println!(
                    "cpu={:.2}% mem_used={}KB mem_total={}KB",
                    cpu, used_mem, total_mem
                );
            }
            _ = signal::ctrl_c() => {
                println!("sysmon-daemon shutting down");
                break;
            }
        }
    }
}
