```rust
use anyhow::Result;
use serde::Serialize;
use std::{
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::System;
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    time,
};

const SOCKET_PATH: &str = "/tmp/sysmon-daemon.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    total_disk_bytes: u64,
    used_disk_bytes: u64,
}

type SharedMetrics = Arc<RwLock<Metrics>>;

#[tokio::main]
async fn main() -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    let metrics = Arc::new(RwLock::new(Metrics::default()));

    let sampler_handle = {
        let metrics = Arc::clone(&metrics);
        tokio::spawn(async move {
            if let Err(e) = sampler_task(metrics).await {
                eprintln!("sampler error: {e}");
            }
        })
    };

    let server_handle = {
        let metrics = Arc::clone(&metrics);
        tokio::spawn(async move {
            if let Err(e) = server_task(metrics).await {
                eprintln!("server error: {e}");
            }
        })
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            eprintln!("received shutdown signal");
        }
    }

    sampler_handle.abort();
    server_handle.abort();

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

async fn sampler_task(metrics: SharedMetrics) -> Result<()> {
    let mut sys = System::new_all();

    loop {
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu = sys.global_cpu_info().cpu_usage();

        let total_memory_bytes = sys.total_memory() * 1024;
        let used_memory_bytes = sys.used_memory() * 1024;
        let total_swap_bytes = sys.total_swap() * 1024;
        let used_swap_bytes = sys.used_swap() * 1024;

        let mut total_disk_bytes = 0u64;
        let mut available_disk_bytes = 0u64;

        for disk in sys.disks() {
            total_disk_bytes += disk.total_space();
            available_disk_bytes += disk.available_space();
        }

        let used_disk_bytes = total_disk_bytes.saturating_sub(available_disk_bytes);

        let snapshot = Metrics {
            timestamp: now_unix(),
            cpu_usage_percent: cpu,
            total_memory_bytes,
            used_memory_bytes,
            total_swap_bytes,
            used_swap_bytes,
            total_disk_bytes,
            used_disk_bytes,
        };

        {
            let mut guard = metrics.write().await;
            *guard = snapshot.clone();
        }

        println!("{}", serde_json::to_string(&snapshot)?);

        time::sleep(Duration::from_secs(SAMPLE_INTERVAL_SECS)).await;
    }
}

async fn server_task(metrics: SharedMetrics) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)?;
    eprintln!("listening on {SOCKET_PATH}");

    loop {
        let (stream, _) = listener.accept().await?;
        let metrics = Arc::clone(&metrics);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, metrics).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(mut stream: UnixStream, metrics: SharedMetrics) -> Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;

    let request = std::str::from_utf8(&buf[..n]).unwrap_or("").trim();

    match request {
        "status" | "" => {
            let snapshot = {
                let guard = metrics.read().await;
                guard.clone()
            };
            let body = serde_json::to_vec(&snapshot)?;
            stream.write_all(&body).await?;
            stream.write_all(b"\n").await?;
        }
        "ping" => {
            stream.write_all(b"pong\n").await?;
        }
        _ => {
            stream.write_all(b"{\"error\":\"unknown command\"}\n").await?;
        }
    }

    Ok(())
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}
```

