# `src/main.rs`

```rust
use axum::{extract::State, response::Json, routing::get, Router};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::System;
use tokio::sync::RwLock;
use tracing::{error, info};

#[derive(Debug, Clone, Serialize, Default)]
struct ResourceSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    total_disk_bytes: u64,
    available_disk_bytes: u64,
}

#[derive(Clone)]
struct AppState {
    snapshot: Arc<RwLock<ResourceSnapshot>>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState {
        snapshot: Arc::new(RwLock::new(ResourceSnapshot::default())),
    };

    let monitor_state = state.clone();
    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(metrics))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    info!("starting resource daemon on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind listener");

    let server = axum::serve(listener, app);

    let shutdown = async {
        wait_for_shutdown_signal().await;
        info!("shutdown signal received");
    };

    if let Err(e) = server.with_graceful_shutdown(shutdown).await {
        error!("server error: {}", e);
    }

    monitor_task.abort();
    info!("daemon stopped");
}

async fn health() -> &'static str {
    "ok"
}

async fn metrics(State(state): State<AppState>) -> Json<ResourceSnapshot> {
    let snapshot = state.snapshot.read().await.clone();
    Json(snapshot)
}

async fn monitor_loop(state: AppState) {
    let mut sys = System::new_all();

    loop {
        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu_usage = sys.global_cpu_info().cpu_usage();

        // sysinfo reports memory in KiB on many platforms; convert conservatively.
        let total_memory_bytes = sys.total_memory() * 1024;
        let used_memory_bytes = sys.used_memory() * 1024;
        let total_swap_bytes = sys.total_swap() * 1024;
        let used_swap_bytes = sys.used_swap() * 1024;

        let mut total_disk_bytes = 0u64;
        let mut available_disk_bytes = 0u64;

        for disk in sys.disks() {
            total_disk_bytes = total_disk_bytes.saturating_add(disk.total_space());
            available_disk_bytes =
                available_disk_bytes.saturating_add(disk.available_space());
        }

        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        let snapshot = ResourceSnapshot {
            timestamp,
            cpu_usage_percent: cpu_usage,
            total_memory_bytes,
            used_memory_bytes,
            total_swap_bytes,
            used_swap_bytes,
            total_disk_bytes,
            available_disk_bytes,
        };

        {
            let mut guard = state.snapshot.write().await;
            *guard = snapshot.clone();
        }

        info!(
            cpu = format!("{:.2}", snapshot.cpu_usage_percent),
            used_mem = snapshot.used_memory_bytes,
            total_mem = snapshot.total_memory_bytes,
            "resource snapshot updated"
        );

        tokio::time::sleep(Duration::from_secs(2)).await;
    }
}

async fn wait_for_shutdown_signal() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        let mut sigint = signal(SignalKind::interrupt()).expect("failed to install SIGINT handler");

        tokio::select! {
            _ = sigterm.recv() => {}
            _ = sigint.recv() => {}
        }
    }

    #[cfg(not(unix))]
    {
        tokio::signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    }
}
```

