## `src/main.rs`

```rust
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use sysinfo::System;
use tokio::{signal, sync::RwLock, time};
use tracing::{error, info};

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp_unix: u64,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    available_memory_bytes: u64,
}

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<Metrics>>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let initial = Metrics {
        timestamp_unix: now_unix(),
        cpu_usage_percent: 0.0,
        total_memory_bytes: 0,
        used_memory_bytes: 0,
        available_memory_bytes: 0,
    };

    let state = AppState {
        metrics: Arc::new(RwLock::new(initial)),
    };

    let sampler_state = state.clone();
    tokio::spawn(async move {
        sampler_loop(sampler_state, Duration::from_secs(2)).await;
    });

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(metrics))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    info!("starting sysmon daemon on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind listener");

    let server = axum::serve(listener, app);

    tokio::select! {
        result = server => {
            if let Err(e) = result {
                error!("server error: {}", e);
            }
        }
        _ = shutdown_signal() => {
            info!("shutdown signal received");
        }
    }

    info!("daemon exiting");
}

async fn sampler_loop(state: AppState, interval: Duration) {
    let mut sys = System::new_all();

    loop {
        sys.refresh_cpu();
        sys.refresh_memory();

        let total_mem = sys.total_memory() * 1024;
        let used_mem = sys.used_memory() * 1024;
        let avail_mem = sys.available_memory() * 1024;

        let snapshot = Metrics {
            timestamp_unix: now_unix(),
            cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
            total_memory_bytes: total_mem,
            used_memory_bytes: used_mem,
            available_memory_bytes: avail_mem,
        };

        {
            let mut guard = state.metrics.write().await;
            *guard = snapshot;
        }

        time::sleep(interval).await;
    }
}

async fn health() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "ok"
    }))
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.metrics.read().await.clone();
    Json(snapshot)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {}
        _ = terminate => {}
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}
```

