```rust
use axum::{routing::get, Json, Router};
use chrono::{DateTime, Utc};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{Arc, Mutex},
    time::Duration,
};
use sysinfo::System;
use tokio::{signal, task, time};

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp: DateTime<Utc>,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    total_disk_bytes: u64,
    available_disk_bytes: u64,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            timestamp: Utc::now(),
            cpu_usage_percent: 0.0,
            total_memory_bytes: 0,
            used_memory_bytes: 0,
            total_swap_bytes: 0,
            used_swap_bytes: 0,
            total_disk_bytes: 0,
            available_disk_bytes: 0,
        }
    }
}

type SharedMetrics = Arc<Mutex<Metrics>>;

async fn health_handler() -> Json<Metrics> {
    Json(Metrics::default())
}

async fn metrics_handler(state: axum::extract::State<SharedMetrics>) -> Json<Metrics> {
    let data = state.0.lock().unwrap().clone();
    Json(data)
}

async fn sampler(shared: SharedMetrics) {
    let mut sys = System::new_all();

    loop {
        sys.refresh_all();

        let disks = sysinfo::Disks::new_with_refreshed_list();
        let mut total_disk = 0u64;
        let mut available_disk = 0u64;

        for d in disks.list() {
            total_disk += d.total_space();
            available_disk += d.available_space();
        }

        let snapshot = Metrics {
            timestamp: Utc::now(),
            cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
            total_memory_bytes: sys.total_memory() * 1024,
            used_memory_bytes: sys.used_memory() * 1024,
            total_swap_bytes: sys.total_swap() * 1024,
            used_swap_bytes: sys.used_swap() * 1024,
            total_disk_bytes: total_disk,
            available_disk_bytes: available_disk,
        };

        {
            let mut guard = shared.lock().unwrap();
            *guard = snapshot.clone();
        }

        println!("{}", serde_json::to_string(&snapshot).unwrap());

        time::sleep(Duration::from_secs(5)).await;
    }
}

#[tokio::main]
async fn main() {
    let shared: SharedMetrics = Arc::new(Mutex::new(Metrics::default()));

    let sampler_state = shared.clone();
    task::spawn(async move {
        sampler(sampler_state).await;
    });

    let app = Router::new()
        .route("/health", get(health_handler))
        .route("/metrics", get(metrics_handler))
        .with_state(shared);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();

    println!("listening on http://{}", addr);

    tokio::select! {
        res = axum::serve(listener, app) => {
            if let Err(err) = res {
                eprintln!("server error: {err}");
            }
        }
        _ = signal::ctrl_c() => {
            eprintln!("shutdown signal received");
        }
    }
}
```

