```rust
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const SOCKET_PATH: &str = "/tmp/sysmon_daemon.sock";

#[derive(Debug, Clone, Default)]
struct Stats {
    cpu_usage_percent: f32,
    mem_total_kb: u64,
    mem_available_kb: u64,
    last_updated_ms: u128,
}

fn read_cpu_times() -> Option<(u64, u64)> {
    let content = fs::read_to_string("/proc/stat").ok()?;
    let first = content.lines().next()?;
    let mut parts = first.split_whitespace();
    let label = parts.next()?;
    if label != "cpu" {
        return None;
    }

    let values: Vec<u64> = parts.filter_map(|p| p.parse::<u64>().ok()).collect();
    if values.len() < 4 {
        return None;
    }

    let idle = values[3] + values.get(4).copied().unwrap_or(0);
    let total: u64 = values.iter().sum();
    Some((idle, total))
}

fn read_mem_info() -> Option<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").ok()?;
    let mut total = None;
    let mut available = None;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total = line.split_whitespace().nth(1)?.parse::<u64>().ok();
        } else if line.starts_with("MemAvailable:") {
            available = line.split_whitespace().nth(1)?.parse::<u64>().ok();
        }
        if total.is_some() && available.is_some() {
            break;
        }
    }

    Some((total?, available?))
}

fn sampler(stats: Arc<Mutex<Stats>>, running: Arc<AtomicBool>, start: Instant) {
    let mut prev = read_cpu_times();

    while running.load(Ordering::Relaxed) {
        let cpu_usage = if let (Some((prev_idle, prev_total)), Some((idle, total))) =
            (prev, read_cpu_times())
        {
            let idle_delta = idle.saturating_sub(prev_idle);
            let total_delta = total.saturating_sub(prev_total);
            prev = Some((idle, total));

            if total_delta == 0 {
                0.0
            } else {
                100.0 * (1.0 - (idle_delta as f32 / total_delta as f32))
            }
        } else {
            0.0
        };

        let (mem_total, mem_available) = read_mem_info().unwrap_or((0, 0));

        {
            let mut s = stats.lock().unwrap();
            s.cpu_usage_percent = cpu_usage;
            s.mem_total_kb = mem_total;
            s.mem_available_kb = mem_available;
            s.last_updated_ms = start.elapsed().as_millis();
        }

        thread::sleep(Duration::from_secs(1));
    }
}

fn handle_client(
    mut stream: UnixStream,
    stats: Arc<Mutex<Stats>>,
    running: Arc<AtomicBool>,
) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();
    reader.read_line(&mut line)?;

    let cmd = line.trim();
    match cmd {
        "ping" => {
            writeln!(stream, "pong")?;
        }
        "stats" => {
            let s = stats.lock().unwrap().clone();
            writeln!(
                stream,
                "{{\"cpu_usage_percent\":{:.2},\"mem_total_kb\":{},\"mem_available_kb\":{},\"last_updated_ms\":{}}}",
                s.cpu_usage_percent, s.mem_total_kb, s.mem_available_kb, s.last_updated_ms
            )?;
        }
        "quit" => {
            running.store(false, Ordering::Relaxed);
            writeln!(stream, "shutting down")?;
        }
        _ => {
            writeln!(stream, "unknown command")?;
        }
    }

    Ok(())
}

fn main() -> std::io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    let stats = Arc::new(Mutex::new(Stats::default()));
    let running = Arc::new(AtomicBool::new(true));
    let start = Instant::now();

    {
        let stats = Arc::clone(&stats);
        let running = Arc::clone(&running);
        thread::spawn(move || sampler(stats, running, start));
    }

    while running.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let stats = Arc::clone(&stats);
                let running = Arc::clone(&running);
                thread::spawn(move || {
                    let _ = handle_client(stream, stats, running);
                });
            }
            Err(e) => {
                eprintln!("accept error: {e}");
                thread::sleep(Duration::from_millis(100));
            }
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}
