use anyhow::{Context, Result};
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::Duration;
use sysinfo::System;

const SOCKET_PATH: &str = "/tmp/resourced.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Default)]
struct ResourceSnapshot {
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
}

fn collect_snapshot(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_cpu();
    sys.refresh_memory();

    let cpu_usage = sys.global_cpu_info().cpu_usage();

    ResourceSnapshot {
        cpu_usage_percent: cpu_usage,
        total_memory_kib: sys.total_memory(),
        used_memory_kib: sys.used_memory(),
        total_swap_kib: sys.total_swap(),
        used_swap_kib: sys.used_swap(),
    }
}

fn handle_client(
    mut stream: UnixStream,
    state: Arc<Mutex<ResourceSnapshot>>,
    running: Arc<AtomicBool>,
) -> Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();
    reader.read_line(&mut line)?;

    let cmd = line.trim();

    match cmd {
        "status" => {
            let snapshot = state.lock().unwrap().clone();
            let body = serde_json::to_string_pretty(&snapshot)?;
            writeln!(stream, "{body}")?;
        }
        "quit" => {
            running.store(false, Ordering::SeqCst);
            writeln!(stream, "shutting down")?;
        }
        _ => {
            writeln!(stream, "unknown command")?;
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    env_logger::init();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let running = Arc::new(AtomicBool::new(true));
    let state = Arc::new(Mutex::new(ResourceSnapshot::default()));

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::SeqCst);
        })?;
    }

    let sampler_running = running.clone();
    let sampler_state = state.clone();

    let sampler = thread::spawn(move || {
        let mut sys = System::new();
        // Prime CPU measurement
        sys.refresh_cpu();
        thread::sleep(Duration::from_millis(200));

        while sampler_running.load(Ordering::SeqCst) {
            let snapshot = collect_snapshot(&mut sys);
            {
                let mut guard = sampler_state.lock().unwrap();
                *guard = snapshot.clone();
            }

            log::info!(
                "cpu={:.2}% mem={}/{} KiB swap={}/{} KiB",
                snapshot.cpu_usage_percent,
                snapshot.used_memory_kib,
                snapshot.total_memory_kib,
                snapshot.used_swap_kib,
                snapshot.total_swap_kib
            );

            thread::sleep(Duration::from_secs(SAMPLE_INTERVAL_SECS));
        }
    });

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    listener
        .set_nonblocking(true)
        .context("setting nonblocking")?;

    log::info!("resourced listening on {}", SOCKET_PATH);

    while running.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let state = state.clone();
                let running = running.clone();
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, state, running) {
                        log::error!("client error: {e:#}");
                    }
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                log::error!("listener error: {e}");
                break;
            }
        }
    }

    log::info!("shutting down");
    let _ = fs::remove_file(SOCKET_PATH);
    let _ = sampler.join();

    Ok(())
}
