use serde::Serialize;
use std::fs;
use std::io;
use std::path::Path;
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time::{sleep, Duration};

const SOCKET_PATH: &str = "/tmp/resourced.sock";
const POLL_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    load1: f32,
    load5: f32,
    load15: f32,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
}

#[tokio::main]
async fn main() -> io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let state = Arc::new(RwLock::new(Metrics::default()));

    {
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            loop {
                match collect_metrics() {
                    Ok(m) => {
                        let mut guard = state.write().await;
                        *guard = m;
                    }
                    Err(e) => {
                        eprintln!("collector error: {e}");
                    }
                }
                sleep(Duration::from_secs(POLL_INTERVAL_SECS)).await;
            }
        });
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    println!("resourced listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<Metrics>>) -> io::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    match line.trim() {
        "status" => {
            let snapshot = state.read().await.clone();
            let body = serde_json::to_string(&snapshot)
                .map_err(|e| io::Error::new(io::ErrorKind::Other, e.to_string()))?;
            writer.write_all(body.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        "quit" => {
            writer.write_all(b"bye\n").await?;
        }
        _ => {
            writer.write_all(b"unknown command\n").await?;
        }
    }

    writer.shutdown().await?;
    Ok(())
}

fn collect_metrics() -> io::Result<Metrics> {
    let (load1, load5, load15) = read_loadavg()?;
    let (mem_total_kb, mem_available_kb) = read_meminfo()?;
    let mem_used_kb = mem_total_kb.saturating_sub(mem_available_kb);

    Ok(Metrics {
        load1,
        load5,
        load15,
        mem_total_kb,
        mem_available_kb,
        mem_used_kb,
    })
}

fn read_loadavg() -> io::Result<(f32, f32, f32)> {
    let s = fs::read_to_string("/proc/loadavg")?;
    let mut parts = s.split_whitespace();

    let load1 = parts
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing load1"))?
        .parse::<f32>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;

    let load5 = parts
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing load5"))?
        .parse::<f32>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;

    let load15 = parts
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing load15"))?
        .parse::<f32>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;

    Ok((load1, load5, load15))
}

fn read_meminfo() -> io::Result<(u64, u64)> {
    let s = fs::read_to_string("/proc/meminfo")?;
    let mut total = None;
    let mut available = None;

    for line in s.lines() {
        if line.starts_with("MemTotal:") {
            total = extract_kb(line);
        } else if line.starts_with("MemAvailable:") {
            available = extract_kb(line);
        }

        if total.is_some() && available.is_some() {
            break;
        }
    }

    match (total, available) {
        (Some(t), Some(a)) => Ok((t, a)),
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "missing MemTotal or MemAvailable",
        )),
    }
}

fn extract_kb(line: &str) -> Option<u64> {
    line.split_whitespace().nth(1)?.parse().ok()
}
