```rust
use anyhow::{Context, Result};
use std::fs;
use std::time::Duration;
use tokio::signal;
use tokio::time;

#[derive(Debug, Clone, Copy)]
struct CpuStat {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuStat {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_total(&self) -> u64 {
        self.idle + self.iowait
    }
}

fn read_cpu_stat() -> Result<CpuStat> {
    let content = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let first = content
        .lines()
        .next()
        .context("missing cpu line in /proc/stat")?;

    let mut parts = first.split_whitespace();
    let label = parts.next().context("missing cpu label")?;
    if label != "cpu" {
        anyhow::bail!("unexpected first label in /proc/stat: {label}");
    }

    let nums: Vec<u64> = parts
        .take(8)
        .map(|s| s.parse::<u64>())
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("parsing cpu counters")?;

    if nums.len() < 8 {
        anyhow::bail!("not enough cpu fields");
    }

    Ok(CpuStat {
        user: nums[0],
        nice: nums[1],
        system: nums[2],
        idle: nums[3],
        iowait: nums[4],
        irq: nums[5],
        softirq: nums[6],
        steal: nums[7],
    })
}

fn read_meminfo() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut total_kb = None;
    let mut avail_kb = None;

    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total_kb = rest.split_whitespace().next().and_then(|v| v.parse().ok());
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            avail_kb = rest.split_whitespace().next().and_then(|v| v.parse().ok());
        }
    }

    let total = total_kb.context("MemTotal missing")?;
    let avail = avail_kb.context("MemAvailable missing")?;
    Ok((total, avail))
}

fn cpu_usage_percent(prev: CpuStat, curr: CpuStat) -> f64 {
    let total_delta = curr.total().saturating_sub(prev.total());
    let idle_delta = curr.idle_total().saturating_sub(prev.idle_total());

    if total_delta == 0 {
        return 0.0;
    }

    100.0 * (total_delta - idle_delta) as f64 / total_delta as f64
}

#[tokio::main]
async fn main() -> Result<()> {
    let interval = Duration::from_secs(2);
    let mut ticker = time::interval(interval);

    let mut prev_cpu = read_cpu_stat().context("initial cpu read")?;

    eprintln!("resourced starting");

    loop {
        tokio::select! {
            _ = signal::ctrl_c() => {
                eprintln!("resourced shutting down");
                break;
            }
            _ = ticker.tick() => {
                let curr_cpu = match read_cpu_stat() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("cpu read error: {e:#}");
                        continue;
                    }
                };

                let (mem_total_kb, mem_avail_kb) = match read_meminfo() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("mem read error: {e:#}");
                        continue;
                    }
                };

                let cpu = cpu_usage_percent(prev_cpu, curr_cpu);
                prev_cpu = curr_cpu;

                let mem_used_kb = mem_total_kb.saturating_sub(mem_avail_kb);
                let mem_pct = if mem_total_kb == 0 {
                    0.0
                } else {
                    100.0 * mem_used_kb as f64 / mem_total_kb as f64
                };

                println!(
                    "cpu={:.2}% mem_used={}KB mem_total={}KB mem={:.2}%",
                    cpu, mem_used_kb, mem_total_kb, mem_pct
                );
            }
        }
    }

    Ok(())
}
