```rust
use anyhow::{Context, Result};
use serde::Serialize;
use std::{
    fs,
    path::Path,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    time,
};

const SOCKET_PATH: &str = "/tmp/resmon.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Default)]
struct Stats {
    timestamp_unix_ms: u128,
    cpu_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
    disk_root_total_bytes: u64,
    disk_root_available_bytes: u64,
}

#[derive(Debug, Default, Clone, Copy)]
struct CpuSample {
    total: u64,
    idle: u64,
}

fn read_cpu_sample() -> Result<CpuSample> {
    let content = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let first = content
        .lines()
        .next()
        .context("missing first line in /proc/stat")?;

    let mut parts = first.split_whitespace();
    let label = parts.next().unwrap_or("");
    if label != "cpu" {
        anyhow::bail!("unexpected /proc/stat format");
    }

    let nums: Vec<u64> = parts.filter_map(|p| p.parse::<u64>().ok()).collect();
    if nums.len() < 4 {
        anyhow::bail!("not enough cpu fields");
    }

    let user = nums[0];
    let nice = nums[1];
    let system = nums[2];
    let idle = nums[3];
    let iowait = *nums.get(4).unwrap_or(&0);
    let irq = *nums.get(5).unwrap_or(&0);
    let softirq = *nums.get(6).unwrap_or(&0);
    let steal = *nums.get(7).unwrap_or(&0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    Ok(CpuSample {
        total,
        idle: idle_all,
    })
}

fn compute_cpu_percent(prev: CpuSample, curr: CpuSample) -> f64 {
    let totald = curr.total.saturating_sub(prev.total) as f64;
    let idled = curr.idle.saturating_sub(prev.idle) as f64;
    if totald <= 0.0 {
        0.0
    } else {
        ((totald - idled) / totald) * 100.0
    }
}

fn read_meminfo() -> Result<(u64, u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut total = 0_u64;
    let mut available = 0_u64;

    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total = rest
                .split_whitespace()
                .next()
                .unwrap_or("0")
                .parse()
                .unwrap_or(0);
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            available = rest
                .split_whitespace()
                .next()
                .unwrap_or("0")
                .parse()
                .unwrap_or(0);
        }
    }

    let used = total.saturating_sub(available);
    Ok((total, available, used))
}

fn read_root_disk_bytes() -> Result<(u64, u64)> {
    use std::process::Command;

    let output = Command::new("df")
        .args(["-B1", "/"])
        .output()
        .context("running df")?;

    if !output.status.success() {
        anyhow::bail!("df failed");
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let line = stdout.lines().nth(1).context("unexpected df output")?;
    let cols: Vec<&str> = line.split_whitespace().collect();
    if cols.len() < 5 {
        anyhow::bail!("unexpected df columns");
    }

    let total = cols[1].parse::<u64>().unwrap_or(0);
    let available = cols[3].parse::<u64>().unwrap_or(0);
    Ok((total, available))
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

async fn handle_client(stream: UnixStream, shared: Arc<Mutex<Stats>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd = line.trim();
    match cmd {
        "status" => {
            let stats = shared.lock().unwrap().clone();
            let body = serde_json::to_string(&stats)?;
            writer.write_all(body.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        "ping" => {
            writer.write_all(b"pong\n").await?;
        }
        _ => {
            writer.write_all(b"unknown command\n").await?;
        }
    }

    Ok(())
}

async fn sampler(shared: Arc<Mutex<Stats>>) -> Result<()> {
    let mut prev = read_cpu_sample()?;
    let mut ticker = time::interval(SAMPLE_INTERVAL);

    loop {
        ticker.tick().await;

        let curr = read_cpu_sample()?;
        let cpu_percent = compute_cpu_percent(prev, curr);
        prev = curr;

        let (mem_total_kb, mem_available_kb, mem_used_kb) = read_meminfo()?;
        let (disk_root_total_bytes, disk_root_available_bytes) = read_root_disk_bytes()?;

        let new_stats = Stats {
            timestamp_unix_ms: now_unix_ms(),
            cpu_percent,
            mem_total_kb,
            mem_available_kb,
            mem_used_kb,
            disk_root_total_bytes,
            disk_root_available_bytes,
        };

        let mut guard = shared.lock().unwrap();
        *guard = new_stats;
    }
}

async fn serve(shared: Arc<Mutex<Stats>>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;

    loop {
        let (stream, _) = listener.accept().await?;
        let shared = shared.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, shared).await {
                eprintln!("client error: {e:#}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let shared = Arc::new(Mutex::new(Stats::default()));

    let sampler_task = {
        let shared = shared.clone();
        tokio::spawn(async move { sampler(shared).await })
    };

    let server_task = {
        let shared = shared.clone();
        tokio::spawn(async move { serve(shared).await })
    };

    tokio::select! {
        r = sampler_task => {
            r??;
        }
        r = server_task => {
            r??;
        }
        _ = signal::ctrl_c() => {
            eprintln!("shutdown requested");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}
```

