use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{Disks, System};
use tokio::{
    signal,
    sync::RwLock,
    time,
};

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    disks: Vec<DiskMetrics>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskMetrics {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            timestamp: 0,
            cpu_usage_percent: 0.0,
            total_memory_bytes: 0,
            used_memory_bytes: 0,
            total_swap_bytes: 0,
            used_swap_bytes: 0,
            disks: Vec::new(),
        }
    }
}

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<Metrics>>,
}

#[tokio::main]
async fn main() {
    let state = AppState {
        metrics: Arc::new(RwLock::new(Metrics::default())),
    };

    let monitor_state = state.clone();
    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let app = Router::new()
        .route("/status", get(status_handler))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    println!("listening on http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();

    let server = axum::serve(listener, app).with_graceful_shutdown(shutdown_signal());

    if let Err(err) = server.await {
        eprintln!("server error: {}", err);
    }

    monitor_task.abort();
}

async fn monitor_loop(state: AppState) {
    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    let mut interval = time::interval(Duration::from_secs(2));

    loop {
        interval.tick().await;

        sys.refresh_cpu_usage();
        sys.refresh_memory();
        disks.refresh();

        let disk_metrics = disks
            .list()
            .iter()
            .map(|d| DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space_bytes: d.total_space(),
                available_space_bytes: d.available_space(),
            })
            .collect::<Vec<_>>();

        let metrics = Metrics {
            timestamp: now_unix(),
            cpu_usage_percent: sys.global_cpu_usage(),
            total_memory_bytes: sys.total_memory(),
            used_memory_bytes: sys.used_memory(),
            total_swap_bytes: sys.total_swap(),
            used_swap_bytes: sys.used_swap(),
            disks: disk_metrics,
        };

        let mut guard = state.metrics.write().await;
        *guard = metrics;
    }
}

async fn status_handler(State(state): State<AppState>) -> impl IntoResponse {
    let metrics = state.metrics.read().await.clone();
    (StatusCode::OK, Json(metrics))
}

async fn shutdown_signal() {
    let _ = signal::ctrl_c().await;
    println!("shutdown signal received");
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}
```

