use anyhow::Result;
use futures::StreamExt;
use signal_hook::consts::{SIGINT, SIGTERM};
use signal_hook_tokio::Signals;
use std::time::Duration;
use sysinfo::System;
use tokio::time;

#[derive(Debug, Clone)]
struct Config {
    interval_secs: u64,
    cpu_alert_percent: f32,
    mem_alert_percent: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            interval_secs: 2,
            cpu_alert_percent: 90.0,
            mem_alert_percent: 90.0,
        }
    }
}

#[derive(Debug)]
struct Sample {
    cpu_percent: f32,
    used_memory_bytes: u64,
    total_memory_bytes: u64,
    mem_percent: f32,
}

fn collect_sample(sys: &mut System) -> Sample {
    sys.refresh_cpu();
    sys.refresh_memory();

    let cpu_percent = sys.global_cpu_info().cpu_usage();

    let used_memory_bytes = sys.used_memory() * 1024;
    let total_memory_bytes = sys.total_memory() * 1024;
    let mem_percent = if total_memory_bytes == 0 {
        0.0
    } else {
        (used_memory_bytes as f32 / total_memory_bytes as f32) * 100.0
    };

    Sample {
        cpu_percent,
        used_memory_bytes,
        total_memory_bytes,
        mem_percent,
    }
}

fn evaluate(sample: &Sample, cfg: &Config) {
    if sample.cpu_percent >= cfg.cpu_alert_percent {
        eprintln!(
            "[alert] high cpu usage: {:.1}%",
            sample.cpu_percent
        );
    }

    if sample.mem_percent >= cfg.mem_alert_percent {
        eprintln!(
            "[alert] high memory usage: {:.1}% ({}/{} bytes)",
            sample.mem_percent,
            sample.used_memory_bytes,
            sample.total_memory_bytes
        );
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let cfg = Config::default();

    let mut sys = System::new();
    sys.refresh_cpu();
    sys.refresh_memory();

    let mut ticker = time::interval(Duration::from_secs(cfg.interval_secs));
    let mut signals = Signals::new([SIGINT, SIGTERM])?;

    println!(
        "resourced starting: interval={}s cpu_alert={} mem_alert={}",
        cfg.interval_secs, cfg.cpu_alert_percent, cfg.mem_alert_percent
    );

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let sample = collect_sample(&mut sys);
                println!(
                    "[sample] cpu={:.1}% mem={:.1}% used={} total={}",
                    sample.cpu_percent,
                    sample.mem_percent,
                    sample.used_memory_bytes,
                    sample.total_memory_bytes
                );
                evaluate(&sample, &cfg);
            }

            maybe_signal = signals.next() => {
                if let Some(sig) = maybe_signal {
                    println!("received signal {}, shutting down", sig);
                    break;
                }
            }
        }
    }

    println!("resourced stopped");
    Ok(())
}
```

