```rust
use anyhow::{Context, Result};
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::Duration;

const SOCKET_PATH: &str = "/tmp/resourced.sock";

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    loadavg_1m: f32,
    loadavg_5m: f32,
    loadavg_15m: f32,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
}

impl Default for ResourceSnapshot {
    fn default() -> Self {
        Self {
            loadavg_1m: 0.0,
            loadavg_5m: 0.0,
            loadavg_15m: 0.0,
            mem_total_kb: 0,
            mem_available_kb: 0,
            mem_used_kb: 0,
        }
    }
}

fn read_loadavg() -> Result<(f32, f32, f32)> {
    let content = fs::read_to_string("/proc/loadavg")
        .context("failed to read /proc/loadavg")?;
    let mut parts = content.split_whitespace();
    let l1: f32 = parts.next().context("missing loadavg 1m")?.parse()?;
    let l5: f32 = parts.next().context("missing loadavg 5m")?.parse()?;
    let l15: f32 = parts.next().context("missing loadavg 15m")?.parse()?;
    Ok((l1, l5, l15))
}

fn read_meminfo() -> Result<(u64, u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo")
        .context("failed to read /proc/meminfo")?;

    let mut total = 0u64;
    let mut available = 0u64;

    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total = rest.split_whitespace().next().unwrap_or("0").parse()?;
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            available = rest.split_whitespace().next().unwrap_or("0").parse()?;
        }
    }

    let used = total.saturating_sub(available);
    Ok((total, available, used))
}

fn sample_resources() -> Result<ResourceSnapshot> {
    let (l1, l5, l15) = read_loadavg()?;
    let (total, available, used) = read_meminfo()?;
    Ok(ResourceSnapshot {
        loadavg_1m: l1,
        loadavg_5m: l5,
        loadavg_15m: l15,
        mem_total_kb: total,
        mem_available_kb: available,
        mem_used_kb: used,
    })
}

fn handle_client(
    mut stream: UnixStream,
    snapshot: Arc<Mutex<ResourceSnapshot>>,
    interval_secs: Arc<AtomicU64>,
    running: Arc<AtomicBool>,
) -> Result<()> {
    let reader = stream.try_clone()?;
    let mut reader = BufReader::new(reader);

    let mut line = String::new();
    reader.read_line(&mut line)?;
    let cmd = line.trim();

    if cmd == "status" {
        let snap = snapshot.lock().unwrap().clone();
        let body = serde_json::to_string(&snap)?;
        writeln!(stream, "{body}")?;
    } else if let Some(rest) = cmd.strip_prefix("set interval ") {
        let secs: u64 = rest.parse().context("invalid interval")?;
        if secs == 0 {
            writeln!(stream, "ERR interval must be > 0")?;
        } else {
            interval_secs.store(secs, Ordering::Relaxed);
            writeln!(stream, "OK")?;
        }
    } else if cmd == "quit" {
        running.store(false, Ordering::Relaxed);
        writeln!(stream, "OK shutting down")?;
    } else {
        writeln!(stream, "ERR unknown command")?;
    }

    Ok(())
}

fn main() -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("failed to remove stale socket")?;
    }

    let running = Arc::new(AtomicBool::new(true));
    let interval_secs = Arc::new(AtomicU64::new(2));
    let snapshot = Arc::new(Mutex::new(ResourceSnapshot::default()));

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    {
        let running = running.clone();
        let interval_secs = interval_secs.clone();
        let snapshot = snapshot.clone();

        thread::spawn(move || {
            while running.load(Ordering::Relaxed) {
                match sample_resources() {
                    Ok(snap) => {
                        let mut guard = snapshot.lock().unwrap();
                        *guard = snap;
                    }
                    Err(e) => {
                        eprintln!("sampling error: {e:#}");
                    }
                }

                let sleep_for = interval_secs.load(Ordering::Relaxed);
                thread::sleep(Duration::from_secs(sleep_for));
            }
        });
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .context("failed to bind unix socket")?;

    println!("resourced listening on {}", SOCKET_PATH);

    listener.set_nonblocking(true)?;

    while running.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let snapshot = snapshot.clone();
                let interval_secs = interval_secs.clone();
                let running = running.clone();

                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, snapshot, interval_secs, running) {
                        eprintln!("client error: {e:#}");
                    }
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                eprintln!("accept error: {e}");
                thread::sleep(Duration::from_millis(200));
            }
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    println!("resourced stopped");
    Ok(())
}
