use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};

use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use tokio::{
    signal,
    sync::RwLock,
    time,
};
use sysinfo::System;

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    total_disk_read_bytes: u64,
    total_disk_written_bytes: u64,
    process_count: usize,
}

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<Metrics>>,
}

#[tokio::main]
async fn main() {
    let state = AppState {
        metrics: Arc::new(RwLock::new(Metrics::default())),
    };

    let collector_state = state.clone();
    tokio::spawn(async move {
        collector_loop(collector_state).await;
    });

    let app = Router::new()
        .route("/healthz", get(healthz))
        .route("/metrics", get(metrics))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    println!("listening on http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .unwrap();
}

async fn healthz() -> impl IntoResponse {
    "ok"
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.metrics.read().await.clone();
    Json(snapshot)
}

async fn collector_loop(state: AppState) {
    let mut sys = System::new_all();

    loop {
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu = sys.global_cpu_info().cpu_usage();
        let total_memory = sys.total_memory() * 1024;
        let used_memory = sys.used_memory() * 1024;
        let total_swap = sys.total_swap() * 1024;
        let used_swap = sys.used_swap() * 1024;
        let process_count = sys.processes().len();

        let mut total_read = 0u64;
        let mut total_written = 0u64;
        for disk in sys.disks() {
            let usage = disk.usage();
            total_read += usage.total_read_bytes;
            total_written += usage.total_written_bytes;
        }

        let new_metrics = Metrics {
            cpu_usage_percent: cpu,
            total_memory_bytes: total_memory,
            used_memory_bytes: used_memory,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            total_disk_read_bytes: total_read,
            total_disk_written_bytes: total_written,
            process_count,
        };

        {
            let mut guard = state.metrics.write().await;
            *guard = new_metrics;
        }

        time::sleep(Duration::from_secs(2)).await;
    }
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    println!("shutdown signal received");
}
```

