```rust
use axum::{extract::State, response::Json, routing::get, Router};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::System;
use tokio::sync::RwLock;
use tracing::{error, info};

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
}

#[derive(Clone, Default)]
struct AppState {
    metrics: Arc<RwLock<Metrics>>,
}

async fn status(State(state): State<AppState>) -> Json<Metrics> {
    let metrics = state.metrics.read().await.clone();
    Json(metrics)
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

async fn sampler(state: AppState, interval: Duration) {
    let mut sys = System::new_all();

    loop {
        sys.refresh_cpu_usage();
        sys.refresh_memory();

        let metrics = Metrics {
            timestamp: now_unix(),
            cpu_usage_percent: sys.global_cpu_usage(),
            total_memory_bytes: sys.total_memory() * 1024,
            used_memory_bytes: sys.used_memory() * 1024,
        };

        {
            let mut guard = state.metrics.write().await;
            *guard = metrics.clone();
        }

        info!(
            cpu_usage_percent = metrics.cpu_usage_percent,
            total_memory_bytes = metrics.total_memory_bytes,
            used_memory_bytes = metrics.used_memory_bytes,
            "sampled system metrics"
        );

        tokio::time::sleep(interval).await;
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=info".to_string()),
        )
        .init();

    let state = AppState::default();

    let sampler_state = state.clone();
    tokio::spawn(async move {
        sampler(sampler_state, Duration::from_secs(2)).await;
    });

    let app = Router::new()
        .route("/status", get(status))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    info!("starting HTTP status server on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind listener");

    let server = axum::serve(listener, app);

    tokio::select! {
        result = server => {
            if let Err(e) = result {
                error!("server error: {}", e);
            }
        }
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    info!("daemon exiting");
}
