        .with_graceful_shutdown(shutdown_signal())
        .await
        .unwrap();
}

async fn healthz() -> impl IntoResponse {
    "ok"
}

async fn get_metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.metrics.read().await.clone();
    Json(snapshot)
}

async fn collector_loop(state: AppState) {
    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    loop {
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        disks.refresh();

        let load: LoadAvg = System::load_average();

        let disk_metrics = disks
            .list()
            .iter()
            .map(|d| DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space_bytes: d.total_space(),
                available_space_bytes: d.available_space(),
            })
            .collect::<Vec<_>>();

        let cpu_usage = {
            let cpus = sys.cpus();
            if cpus.is_empty() {
                0.0
            } else {
                let sum: f32 = cpus.iter().map(|c| c.cpu_usage()).sum();
                sum / cpus.len() as f32
            }
        };

        let updated = Metrics {
            timestamp: now_ts(),
            cpu_usage_percent: cpu_usage,
            total_memory_bytes: sys.total_memory(),
            used_memory_bytes: sys.used_memory(),
            total_swap_bytes: sys.total_swap(),
            used_swap_bytes: sys.used_swap(),
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disks: disk_metrics,
        };

        {
            let mut guard = state.metrics.write().await;
            *guard = updated;
        }

        tokio::time::sleep(Duration::from_secs(2)).await;
    }
}

async fn shutdown_signal() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm = signal(SignalKind::terminate()).unwrap();
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {},
            _ = sigterm.recv() => {},
        }
    }

    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
    }

    println!("shutdown signal received");
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}
