```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

const FLOW_TIMEOUT_SECS: u64 = 30;
const MAX_FLOWS: usize = 1_000_000;

#[derive(Clone, Copy, Eq, PartialEq, Hash, Debug)]
enum IpAddrKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Eq, PartialEq, Debug)]
struct FlowKey {
    src_ip: IpAddrKey,
    dst_ip: IpAddrKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct FlowTable {
    table: HashMap<FlowKey, FlowStats>,
    timeout: Duration,
    max_flows: usize,
}

impl FlowTable {
    fn new(timeout: Duration, max_flows: usize) -> Self {
        Self {
            table: HashMap::with_capacity(max_flows / 2),
            timeout,
            max_flows,
        }
    }

    fn process_packet(&mut self, key: FlowKey, bytes: usize, tcp_flags: Option<u8>) {
        let now = Instant::now();

        if let Some(stats) = self.table.get_mut(&key) {
            stats.update(now, bytes);
            if let Some(flags) = tcp_flags {
                if flags & 0x02 != 0 { stats.tcp_syn += 1; }
                if flags & 0x01 != 0 { stats.tcp_fin += 1; }
                if flags & 0x04 != 0 { stats.tcp_rst += 1; }
            }
            return;
        }

        if self.table.len() >= self.max_flows {
            self.evict_stale(now);
            if self.table.len() >= self.max_flows {
                self.evict_one();
            }
        }

        let mut stats = FlowStats::new(now, bytes);
        if let Some(flags) = tcp_flags {
            if flags & 0x02 != 0 { stats.tcp_syn += 1; }
            if flags & 0x01 != 0 { stats.tcp_fin += 1; }
            if flags & 0x04 != 0 { stats.tcp_rst += 1; }
        }
        self.table.insert(key, stats);
    }

    fn evict_stale(&mut self, now: Instant) {
        let timeout = self.timeout;
        self.table.retain(|_, v| now.duration_since(v.last_seen) < timeout);
    }

    fn evict_one(&mut self) {
        if let Some(key) = self.table.iter()
            .min_by_key(|(_, v)| v.last_seen)
            .map(|(k, _)| *k)
        {
            self.table.remove(&key);
        }
    }

    fn export_expired(&mut self) -> Vec<(FlowKey, FlowStats)> {
        let now = Instant::now();
        let timeout = self.timeout;
        let mut expired = Vec::new();

        self.table.retain(|k, v| {
            if now.duration_since(v.last_seen) >= timeout {
                expired.push((*k, v.clone()));
                false
            } else {
                true
            }
        });

        expired
    }
}

fn main() {
    let mut flows = FlowTable::new(Duration::from_secs(FLOW_TIMEOUT_SECS), MAX_FLOWS);

    // Example synthetic packets
    let packets = vec![
        (
            FlowKey {
                src_ip: IpAddrKey::V4([10, 0, 0, 1]),
                dst_ip: IpAddrKey::V4([10, 0, 0, 2]),
                src_port: 12345,
                dst_port: 80,
                proto: 6,
            },
            1500usize,
            Some(0x02u8),
        ),
        (
            FlowKey {
                src_ip: IpAddrKey::V4([10, 0, 0, 1]),
                dst_ip: IpAddrKey::V4([10, 0, 0, 2]),
                src_port: 12345,
                dst_port: 80,
                proto: 6,
            },
            900usize,
            Some(0x10u8),
        ),
    ];

    for (key, bytes, flags) in packets {
        flows.process_packet(key, bytes, flags);
    }

    for (k, v) in flows.export_expired() {
        println!("{:?} => packets={}, bytes={}", k, v.packets, v.bytes);
    }
}
```

