# src/main.rs

```rust
use ahash::AHasher;
use crossbeam::channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use parking_lot::Mutex;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const CHANNEL_CAPACITY: usize = 8192;
const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const CLEANUP_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Debug, Clone, Copy, Hash, Eq, PartialEq)]
enum TransportProtocol {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Hash, Eq, PartialEq)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: TransportProtocol,
}

#[derive(Debug, Clone)]
struct FlowStats {
    first_seen: Instant,
    last_seen: Instant,
    packets: u64,
    bytes: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            first_seen: now,
            last_seen: now,
            packets: 1,
            bytes: bytes as u64,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.last_seen = now;
        self.packets += 1;
        self.bytes += bytes as u64;
    }
}

#[derive(Debug, Clone)]
struct PacketMeta {
    timestamp: Instant,
    len: usize,
    flow_key: FlowKey,
    tcp_flags: Option<u8>,
}

struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowStats, ahash::RandomState>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::with_hasher(ahash::RandomState::new())),
        }
    }
}

struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    fn update_flow(&self, pkt: PacketMeta) {
        let idx = self.shard_index(&pkt.flow_key);
        let shard = &self.shards[idx];
        let mut map = shard.map.lock();

        let entry = map
            .entry(pkt.flow_key)
            .or_insert_with(|| FlowStats::new(pkt.timestamp, pkt.len));

        if entry.packets > 1 || entry.bytes > pkt.len as u64 {
            entry.update(pkt.timestamp, pkt.len);
        }

        if let Some(flags) = pkt.tcp_flags {
            if flags & 0x02 != 0 {
                entry.tcp_syn += 1;
            }
            if flags & 0x01 != 0 {
                entry.tcp_fin += 1;
            }
            if flags & 0x04 != 0 {
                entry.tcp_rst += 1;
            }
        }
    }

    fn expire_inactive(&self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.lock();
            let mut to_remove = Vec::new();

            for (k, v) in map.iter() {
                if now.duration_since(v.last_seen) >= FLOW_TIMEOUT {
                    to_remove.push(k.clone());
                }
            }

            for k in to_remove {
                if let Some(v) = map.remove(&k) {
                    expired.push((k, v));
                }
            }
        }

        expired
    }

    fn total_flows(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.map.lock().len())
            .sum()
    }
}

fn parse_packet(data: &[u8], timestamp: Instant) -> Option<PacketMeta> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    let (src_ip, dst_ip) = match sliced.ip? {
        InternetSlice::Ipv4(header, _) => (
            IpAddr::V4(Ipv4Addr::from(header.source())),
            IpAddr::V4(Ipv4Addr::from(header.destination())),
        ),
        InternetSlice::Ipv6(header, _) => (
            IpAddr::V6(Ipv6Addr::from(header.source())),
            IpAddr::V6(Ipv6Addr::from(header.destination())),
        ),
    };

    match sliced.transport? {
        TransportSlice::Tcp(tcp) => Some(PacketMeta {
            timestamp,
            len: data.len(),
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: tcp.source_port(),
                dst_port: tcp.destination_port(),
                proto: TransportProtocol::Tcp,
            },
            tcp_flags: Some(tcp.flags()),
        }),
        TransportSlice::Udp(udp) => Some(PacketMeta {
            timestamp,
            len: data.len(),
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: udp.source_port(),
                dst_port: udp.destination_port(),
                proto: TransportProtocol::Udp,
            },
            tcp_flags: None,
        }),
        _ => None,
    }
}

fn worker_loop(rx: Receiver<Vec<u8>>, table: Arc<FlowTable>) {
    while let Ok(packet) = rx.recv() {
        let now = Instant::now();
        if let Some(meta) = parse_packet(&packet, now) {
            table.update_flow(meta);
        }
    }
}

fn cleanup_loop(table: Arc<FlowTable>) {
    loop {
        thread::sleep(CLEANUP_INTERVAL);
        let now = Instant::now();
        let expired = table.expire_inactive(now);

        for (key, stats) in expired {
            println!(
                "EXPIRED flow={:?} packets={} bytes={} duration_ms={}",
                key,
                stats.packets,
                stats.bytes,
                stats.last_seen.duration_since(stats.first_seen).as_millis()
            );
        }

        println!("active_flows={}", table.total_flows());
    }
}

fn capture_loop(tx_workers: Vec<Sender<Vec<u8>>>) {
    // Placeholder synthetic packet generator.
    // Replace with AF_PACKET, libpcap, DPDK, or XDP source.
    let mut i = 0usize;

    loop {
        let fake_packet = build_fake_ipv4_tcp_packet(i as u16);
        let worker_idx = i % tx_workers.len();
        if tx_workers[worker_idx].send(fake_packet).is_err() {
            break;
        }
        i = i.wrapping_add(1);
    }
}

fn build_fake_ipv4_tcp_packet(src_port: u16) -> Vec<u8> {
    let mut pkt = vec![0u8; 14 + 20 + 20];

    // Ethernet header
    pkt[12] = 0x08;
    pkt[13] = 0x00;

    // IPv4 header
    pkt[14] = 0x45;
    pkt[16] = 0x00;
    pkt[17] = 40;
    pkt[23] = 6;
    pkt[26] = 192;
    pkt[27] = 168;
    pkt[28] = 1;
    pkt[29] = 10;
    pkt[30] = 192;
    pkt[31] = 168;
    pkt[32] = 1;
    pkt[33] = 20;

    // TCP header
    pkt[34] = (src_port >> 8) as u8;
    pkt[35] = (src_port & 0xff) as u8;
    pkt[36] = 0x00;
    pkt[37] = 0x50;
    pkt[46] = 0x50;
    pkt[47] = 0x02;

    pkt
}

fn main() {
    let workers = num_cpus::get().max(2);
    let table = Arc::new(FlowTable::new(NUM_SHARDS));

    let mut txs = Vec::new();
    let mut rxs = Vec::new();

    for _ in 0..workers {
        let (tx, rx) = bounded::<Vec<u8>>(CHANNEL_CAPACITY);
        txs.push(tx);
        rxs.push(rx);
    }

    for rx in rxs {
        let table = Arc::clone(&table);
        thread::spawn(move || worker_loop(rx, table));
    }

    {
        let table = Arc::clone(&table);
        thread::spawn(move || cleanup_loop(table));
    }

    capture_loop(txs);
}
