# Important fix to apply immediately

There is a subtle bug in `update_flow()` above: the first packet of a new flow initializes stats, but the conditional update logic is awkward and can skip proper updates depending on initialization state.

Replace `update_flow()` with this cleaner version:

```rust
fn update_flow(&self, pkt: PacketMeta) {
    let idx = self.shard_index(&pkt.flow_key);
    let shard = &self.shards[idx];
    let mut map = shard.map.lock();

    match map.entry(pkt.flow_key) {
        std::collections::hash_map::Entry::Occupied(mut occ) => {
            let entry = occ.get_mut();
            entry.update(pkt.timestamp, pkt.len);

            if let Some(flags) = pkt.tcp_flags {
                if flags & 0x02 != 0 {
                    entry.tcp_syn += 1;
                }
                if flags & 0x01 != 0 {
                    entry.tcp_fin += 1;
                }
                if flags & 0x04 != 0 {
                    entry.tcp_rst += 1;
                }
            }
        }
        std::collections::hash_map::Entry::Vacant(vac) => {
            let mut stats = FlowStats::new(pkt.timestamp, pkt.len);

            if let Some(flags) = pkt.tcp_flags {
                if flags & 0x02 != 0 {
                    stats.tcp_syn += 1;
                }
                if flags & 0x01 != 0 {
                    stats.tcp_fin += 1;
                }
                if flags & 0x04 != 0 {
                    stats.tcp_rst += 1;
                }
            }

            vac.insert(stats);
        }
    }
}
```

