```rust
use ahash::RandomState;
use crossbeam_channel::{bounded, Receiver};
use hashbrown::HashMap;
use std::fmt::{self, Display};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const CHANNEL_CAPACITY: usize = 8192;

/// L4 protocol identifiers
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
enum Protocol {
    Tcp = 6,
    Udp = 17,
    Other = 255,
}

impl Display for Protocol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Protocol::Tcp => write!(f, "TCP"),
            Protocol::Udp => write!(f, "UDP"),
            Protocol::Other => write!(f, "OTHER"),
        }
    }
}

/// Compact IPv4-only 5-tuple flow key
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: Protocol,
}

impl Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let src = Ipv4Addr::from(self.src_ip);
        let dst = Ipv4Addr::from(self.dst_ip);
        write!(
            f,
            "{}:{} -> {}:{} {}",
            src, self.src_port, dst, self.dst_port, self.proto
        )
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

type FlowTable = HashMap<FlowKey, FlowStats, RandomState>;

#[derive(Debug)]
struct ParsedPacket {
    key: FlowKey,
    wire_len: usize,
}

/// Parse Ethernet + IPv4 + TCP/UDP.
/// Returns None for unsupported/non-IPv4/non-TCP/UDP packets.
fn parse_packet(frame: &[u8]) -> Option<ParsedPacket> {
    // Ethernet II header = 14 bytes
    if frame.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only in this initial version
    }

    let ip = &frame[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_length = u16::from_be_bytes([ip[2], ip[3]]) as usize;
    if total_length < ihl || ip.len() < total_length {
        return None;
    }

    let proto = match ip[9] {
        6 => Protocol::Tcp,
        17 => Protocol::Udp,
        _ => return None,
    };

    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..total_length];
    if l4.len() < 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

    Some(ParsedPacket {
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        wire_len: frame.len(),
    })
}

/// Update flow table with a parsed packet
fn process_packet(table: &mut FlowTable, pkt: ParsedPacket, now: Instant) {
    match table.get_mut(&pkt.key) {
        Some(stats) => stats.update(now, pkt.wire_len),
        None => {
            table.insert(pkt.key, FlowStats::new(now, pkt.wire_len));
        }
    }
}

/// Print top N flows by bytes
fn report_flows(table: &FlowTable, top_n: usize) {
    let mut flows: Vec<_> = table.iter().collect();
    flows.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("=== Flow Report: {} active flows ===", table.len());
    for (idx, (key, stats)) in flows.into_iter().take(top_n).enumerate() {
        let duration = stats.last_seen.duration_since(stats.first_seen);
        println!(
            "#{:<2} {:<40} packets={:<10} bytes={:<12} duration={:?}",
            idx + 1,
            key,
            stats.packets,
            stats.bytes,
            duration
        );
    }
    println!();
}

/// Simple synthetic packet generator for testing without live capture.
/// Produces Ethernet+IPv4+UDP packets.
fn packet_generator(rx_stop: Arc<AtomicBool>, tx: crossbeam_channel::Sender<Vec<u8>>) {
    let mut counter: u16 = 0;

    while !rx_stop.load(Ordering::Relaxed) {
        let src_ip = [10, 0, 0, ((counter % 250) + 1) as u8];
        let dst_ip = [192, 168, 1, ((counter % 32) + 1) as u8];
        let src_port = 10000 + (counter % 1024);
        let dst_port = 20000 + (counter % 128);

        let payload_len = 64usize;
        let udp_len = 8 + payload_len;
        let ip_len = 20 + udp_len;
        let frame_len = 14 + ip_len;

        let mut frame = vec![0u8; frame_len];

        // Ethernet
        frame[12] = 0x08;
        frame[13] = 0x00;

        // IPv4
        frame[14] = 0x45;
        frame[15] = 0x00;
        frame[16..18].copy_from_slice(&(ip_len as u16).to_be_bytes());
        frame[18..20].copy_from_slice(&0u16.to_be_bytes());
        frame[20..22].copy_from_slice(&0u16.to_be_bytes());
        frame[22] = 64;
        frame[23] = 17; // UDP
        frame[24..26].copy_from_slice(&0u16.to_be_bytes()); // checksum omitted
        frame[26..30].copy_from_slice(&src_ip);
        frame[30..34].copy_from_slice(&dst_ip);

        // UDP
        let udp_start = 34;
        frame[udp_start..udp_start + 2].copy_from_slice(&src_port.to_be_bytes());
        frame[udp_start + 2..udp_start + 4].copy_from_slice(&dst_port.to_be_bytes());
        frame[udp_start + 4..udp_start + 6].copy_from_slice(&(udp_len as u16).to_be_bytes());
        frame[udp_start + 6..udp_start + 8].copy_from_slice(&0u16.to_be_bytes());

        // Payload
        for b in &mut frame[udp_start + 8..] {
            *b = 0xaa;
        }

        if tx.send(frame).is_err() {
            break;
        }

        counter = counter.wrapping_add(1);
    }
}

fn analyzer_thread(
    rx_stop: Arc<AtomicBool>,
    rx: Receiver<Vec<u8>>,
    table: Arc<Mutex<FlowTable>>,
) {
    let mut last_report = Instant::now();

    while !rx_stop.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(frame) => {
                if let Some(pkt) = parse_packet(&frame) {
                    let now = Instant::now();
                    let mut guard = table.lock().unwrap();
                    process_packet(&mut guard, pkt, now);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }

        if last_report.elapsed() >= REPORT_INTERVAL {
            let guard = table.lock().unwrap();
            report_flows(&guard, 10);
            last_report = Instant::now();
        }
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let flow_table: Arc<Mutex<FlowTable>> =
        Arc::new(Mutex::new(HashMap::with_hasher(RandomState::new())));

    let (tx, rx) = bounded::<Vec<u8>>(CHANNEL_CAPACITY);

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .expect("failed to install Ctrl-C handler");
    }

    let gen_running = running.clone();
    let gen_tx = tx.clone();
    let generator = thread::spawn(move || {
        packet_generator(gen_running, gen_tx);
    });

    let analyzer_running = running.clone();
    let analyzer_table = flow_table.clone();
    let analyzer = thread::spawn(move || {
        analyzer_thread(analyzer_running, rx, analyzer_table);
    });

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_millis(250));
    }

    drop(tx);

    generator.join().ok();
    analyzer.join().ok();

    println!("Final report:");
    let guard = flow_table.lock().unwrap();
    report_flows(&guard, 20);
}
```

