# Optional improved version: sharded flow table

If you want a more performance-oriented initial version, here is a drop-in sharded table implementation.

## Add this type

```rust
use std::hash::{BuildHasher, Hash, Hasher};

const SHARDS: usize = 64;

struct ShardedFlowTable {
    shards: Vec<Mutex<FlowTable>>,
    hasher: RandomState,
}

impl ShardedFlowTable {
    fn new() -> Self {
        let hasher = RandomState::new();
        let mut shards = Vec::with_capacity(SHARDS);
        for _ in 0..SHARDS {
            shards.push(Mutex::new(HashMap::with_hasher(RandomState::new())));
        }
        Self { shards, hasher }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut h = self.hasher.build_hasher();
        key.hash(&mut h);
        (h.finish() as usize) % SHARDS
    }

    #[inline]
    fn update(&self, pkt: ParsedPacket, now: Instant) {
        let idx = self.shard_index(&pkt.key);
        let mut guard = self.shards[idx].lock().unwrap();
        process_packet(&mut guard, pkt, now);
    }

    fn snapshot_top(&self, top_n: usize) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let guard = shard.lock().unwrap();
            all.extend(guard.iter().map(|(k, v)| (*k, v.clone())));
        }
        all.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));
        all.truncate(top_n);
        all
    }

    fn total_flows(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.lock().unwrap().len())
            .sum()
    }
}
```

Then replace the single `Arc<Mutex<FlowTable>>` with `Arc<ShardedFlowTable>` and update the analyzer/reporter accordingly.

