# Rust implementation

```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone, Copy, Debug, Eq)]
pub struct FlowKey {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub tcp_flags_or: u8,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_flags_or: tcp_flags,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
        self.tcp_flags_or |= tcp_flags;
    }
}

#[derive(Clone, Debug)]
pub struct ParsedPacket {
    pub timestamp: Instant,
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub tcp_flags: u8,
    pub length: usize,
}

impl ParsedPacket {
    fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            proto: self.proto,
        }
    }
}

type FlowMap = HashMap<FlowKey, FlowStats>;

pub struct FlowShard {
    inner: Mutex<FlowMap>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            inner: Mutex::new(HashMap::with_capacity(65_536)),
        }
    }
}

pub struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    pub fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(key: &FlowKey) -> usize {
        let mut h = std::collections::hash_map::DefaultHasher::new();
        key.hash(&mut h);
        (h.finish() as usize) % NUM_SHARDS
    }

    pub fn update_flow(&self, pkt: &ParsedPacket) {
        let key = pkt.flow_key();
        let idx = Self::shard_index(&key);
        let shard = &self.shards[idx];
        let mut map = shard.inner.lock().unwrap();

        match map.get_mut(&key) {
            Some(stats) => stats.update(pkt.timestamp, pkt.length, pkt.tcp_flags),
            None => {
                map.insert(key, FlowStats::new(pkt.timestamp, pkt.length, pkt.tcp_flags));
            }
        }
    }

    pub fn expire_inactive(&self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.inner.lock().unwrap();
            let mut to_remove = Vec::new();

            for (k, v) in map.iter() {
                if now.duration_since(v.last_seen) >= FLOW_TIMEOUT {
                    to_remove.push(*k);
                }
            }

            for key in to_remove {
                if let Some(stats) = map.remove(&key) {
                    expired.push((key, stats));
                }
            }
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut out = Vec::new();
        for shard in &self.shards {
            let map = shard.inner.lock().unwrap();
            out.extend(map.iter().map(|(k, v)| (*k, v.clone())));
        }
        out
    }
}

pub fn parse_ipv4_packet(frame: &[u8], timestamp: Instant) -> Option<ParsedPacket> {
    if frame.len() < 14 + 20 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_start = 14;
    let version_ihl = frame[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || frame.len() < ip_start + ihl {
        return None;
    }

    let proto = frame[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        frame[ip_start + 12],
        frame[ip_start + 13],
        frame[ip_start + 14],
        frame[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        frame[ip_start + 16],
        frame[ip_start + 17],
        frame[ip_start + 18],
        frame[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    match proto {
        6 => {
            if frame.len() < l4_start + 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([frame[l4_start], frame[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([frame[l4_start + 2], frame[l4_start + 3]]);
            let tcp_flags = frame[l4_start + 13];
            Some(ParsedPacket {
                timestamp,
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
                tcp_flags,
                length: frame.len(),
            })
        }
        17 => {
            if frame.len() < l4_start + 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([frame[l4_start], frame[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([frame[l4_start + 2], frame[l4_start + 3]]);
            Some(ParsedPacket {
                timestamp,
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
                tcp_flags: 0,
                length: frame.len(),
            })
        }
        _ => None,
    }
}

pub struct Analyzer {
    flow_table: Arc<FlowTable>,
    running: Arc<AtomicBool>,
}

impl Analyzer {
    pub fn new() -> Self {
        Self {
            flow_table: Arc::new(FlowTable::new()),
            running: Arc::new(AtomicBool::new(true)),
        }
    }

    pub fn process_frame(&self, frame: &[u8]) {
        let now = Instant::now();
        if let Some(pkt) = parse_ipv4_packet(frame, now) {
            self.flow_table.update_flow(&pkt);
        }
    }

    pub fn start_maintenance(&self) -> thread::JoinHandle<()> {
        let table = Arc::clone(&self.flow_table);
        let running = Arc::clone(&self.running);

        thread::spawn(move || {
            while running.load(Ordering::Relaxed) {
                thread::sleep(EXPORT_INTERVAL);

                let now = Instant::now();
                let expired = table.expire_inactive(now);

                if !expired.is_empty() {
                    for (key, stats) in expired {
                        println!(
                            "EXPIRED {:?} packets={} bytes={} duration_ms={}",
                            key,
                            stats.packets,
                            stats.bytes,
                            stats.last_seen.duration_since(stats.first_seen).as_millis()
                        );
                    }
                }
            }
        })
    }

    pub fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        self.flow_table.snapshot()
    }
}

fn main() {
    let analyzer = Analyzer::new();
    let maintenance = analyzer.start_maintenance();

    // Example synthetic packet processing loop.
    // In production, replace with AF_PACKET, DPDK, XDP, libpcap, or netmap ingestion.
    let sample_tcp_frame = build_sample_ipv4_tcp_frame(
        Ipv4Addr::new(10, 0, 0, 1),
        Ipv4Addr::new(10, 0, 0, 2),
        12345,
        80,
        0x18,
        128,
    );

    for _ in 0..1_000_000 {
        analyzer.process_frame(&sample_tcp_frame);
    }

    thread::sleep(Duration::from_secs(1));

    for (key, stats) in analyzer.snapshot() {
        println!(
            "ACTIVE {:?} packets={} bytes={}",
            key, stats.packets, stats.bytes
        );
    }

    analyzer.stop();
    maintenance.join().unwrap();
}

fn build_sample_ipv4_tcp_frame(
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    tcp_flags: u8,
    payload_len: usize,
) -> Vec<u8> {
    let eth_len = 14;
    let ip_len = 20;
    let tcp_len = 20;
    let total_len = eth_len + ip_len + tcp_len + payload_len;

    let mut frame = vec![0u8; total_len];

    frame[12] = 0x08;
    frame[13] = 0x00;

    let ip_start = 14;
    frame[ip_start] = 0x45;
    let ip_total_len = (ip_len + tcp_len + payload_len) as u16;
    frame[ip_start + 2..ip_start + 4].copy_from_slice(&ip_total_len.to_be_bytes());
    frame[ip_start + 9] = 6;
    frame[ip_start + 12..ip_start + 16].copy_from_slice(&src_ip.octets());
    frame[ip_start + 16..ip_start + 20].copy_from_slice(&dst_ip.octets());

    let tcp_start = ip_start + ip_len;
    frame[tcp_start..tcp_start + 2].copy_from_slice(&src_port.to_be_bytes());
    frame[tcp_start + 2..tcp_start + 4].copy_from_slice(&dst_port.to_be_bytes());
    frame[tcp_start + 12] = 0x50;
    frame[tcp_start + 13] = tcp_flags;

    frame
}
```

