use ahash::RandomState;
use anyhow::{Context, Result};
use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const SNAPLEN: i32 = 2048;

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let src = Ipv4Addr::from(self.src_ip);
        let dst = Ipv4Addr::from(self.dst_ip);
        write!(
            f,
            "{}:{} -> {}:{} proto={}",
            src, self.src_port, dst, self.dst_port, self.proto
        )
    }
}

#[derive(Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct Analyzer {
    flows: HashMap<FlowKey, FlowStats, RandomState>,
    last_report: Instant,
    last_expire: Instant,
    total_packets: u64,
    total_bytes: u64,
    dropped_packets: u64,
}

impl Analyzer {
    fn new() -> Self {
        Self {
            flows: HashMap::with_hasher(RandomState::new()),
            last_report: Instant::now(),
            last_expire: Instant::now(),
            total_packets: 0,
            total_bytes: 0,
            dropped_packets: 0,
        }
    }

    fn process_packet(&mut self, packet: &[u8], now: Instant) {
        self.total_packets += 1;
        self.total_bytes += packet.len() as u64;

        match parse_ethernet_ipv4_l4(packet) {
            Some(key) => {
                if let Some(stats) = self.flows.get_mut(&key) {
                    stats.update(now, packet.len());
                } else {
                    self.flows.insert(key, FlowStats::new(now, packet.len()));
                }
            }
            None => {
                self.dropped_packets += 1;
            }
        }

        if now.duration_since(self.last_expire) >= Duration::from_secs(1) {
            self.expire_flows(now);
            self.last_expire = now;
        }

        if now.duration_since(self.last_report) >= REPORT_INTERVAL {
            self.report(now);
            self.last_report = now;
        }
    }

    fn expire_flows(&mut self, now: Instant) {
        self.flows
            .retain(|_, stats| now.duration_since(stats.last_seen) < FLOW_TIMEOUT);
    }

    fn report(&self, now: Instant) {
        println!("=== flow report @ {:?} ===", now);
        println!("active_flows={}", self.flows.len());
        println!("total_packets={}", self.total_packets);
        println!("total_bytes={}", self.total_bytes);
        println!("unparsed_packets={}", self.dropped_packets);

        let mut top: Vec<(&FlowKey, &FlowStats)> = self.flows.iter().collect();
        top.sort_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

        for (key, stats) in top.into_iter().take(10) {
            let age = now.duration_since(stats.first_seen).as_secs_f64();
            println!(
                "{} packets={} bytes={} age={:.1}s",
                key, stats.packets, stats.bytes, age
            );
        }
    }
}

fn parse_ethernet_ipv4_l4(packet: &[u8]) -> Option<FlowKey> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    if proto != 6 && proto != 17 {
        return None;
    }

    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..];
    if l4.len() < 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

fn main() -> Result<()> {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })
    .context("failed to install Ctrl-C handler")?;

    let device = Device::lookup()
        .context("failed to lookup default capture device")?
        .context("no default capture device found")?;

    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(SNAPLEN)
        .open()
        .context("failed to open capture device")?;

    cap.filter("ip and (tcp or udp)", true)
        .context("failed to install BPF filter")?;

    let mut analyzer = Analyzer::new();

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                analyzer.process_packet(packet.data, now);
            }
            Err(pcap::Error::TimeoutExpired) => {}
            Err(e) => {
                eprintln!("capture error: {e}");
                break;
            }
        }
    }

    println!("Shutting down...");
    analyzer.report(Instant::now());
    Ok(())
}
