use ahash::AHashMap;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum TransportProtocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Clone, Copy, Eq, PartialEq)]
pub enum IpAddrExt {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl fmt::Debug for IpAddrExt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IpAddrExt::V4(a) => write!(f, "{}.{}.{}.{}", a[0], a[1], a[2], a[3]),
            IpAddrExt::V6(a) => write!(f, "{}", Ipv6Addr::from(*a)),
        }
    }
}

impl Hash for IpAddrExt {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            IpAddrExt::V4(a) => {
                4u8.hash(state);
                a.hash(state);
            }
            IpAddrExt::V6(a) => {
                6u8.hash(state);
                a.hash(state);
            }
        }
    }
}

impl From<IpAddr> for IpAddrExt {
    fn from(value: IpAddr) -> Self {
        match value {
            IpAddr::V4(v4) => IpAddrExt::V4(v4.octets()),
            IpAddr::V6(v6) => IpAddrExt::V6(v6.octets()),
        }
    }
}

impl From<Ipv4Addr> for IpAddrExt {
    fn from(value: Ipv4Addr) -> Self {
        IpAddrExt::V4(value.octets())
    }
}

impl From<Ipv6Addr> for IpAddrExt {
    fn from(value: Ipv6Addr) -> Self {
        IpAddrExt::V6(value.octets())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddrExt,
    pub dst_ip: IpAddrExt,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct TcpFlags {
    pub fin: bool,
    pub syn: bool,
    pub rst: bool,
    pub psh: bool,
    pub ack: bool,
    pub urg: bool,
    pub ece: bool,
    pub cwr: bool,
}

impl TcpFlags {
    #[inline]
    pub fn merge(&mut self, other: TcpFlags) {
        self.fin |= other.fin;
        self.syn |= other.syn;
        self.rst |= other.rst;
        self.psh |= other.psh;
        self.ack |= other.ack;
        self.urg |= other.urg;
        self.ece |= other.ece;
        self.cwr |= other.cwr;
    }
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub timestamp: Instant,
    pub src_ip: IpAddrExt,
    pub dst_ip: IpAddrExt,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
    pub payload_len: usize,
    pub tcp_flags: Option<TcpFlags>,
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub tcp_flags: TcpFlags,
}

impl FlowStats {
    #[inline]
    pub fn new(pkt: &PacketMeta) -> Self {
        Self {
            packets: 1,
            bytes: pkt.payload_len as u64,
            first_seen: pkt.timestamp,
            last_seen: pkt.timestamp,
            tcp_flags: pkt.tcp_flags.unwrap_or_default(),
        }
    }

    #[inline]
    pub fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.payload_len as u64;
        self.last_seen = pkt.timestamp;
        if let Some(flags) = pkt.tcp_flags {
            self.tcp_flags.merge(flags);
        }
    }
}

#[derive(Clone, Debug)]
pub struct ExportedFlow {
    pub key: FlowKey,
    pub stats: FlowStats,
}

pub struct FlowTable {
    flows: AHashMap<FlowKey, FlowStats>,
    active_timeout: Duration,
    idle_timeout: Duration,
    last_cleanup: Instant,
    cleanup_interval: Duration,
}

impl FlowTable {
    pub fn new(
        capacity: usize,
        active_timeout: Duration,
        idle_timeout: Duration,
        cleanup_interval: Duration,
    ) -> Self {
        Self {
            flows: AHashMap::with_capacity(capacity),
            active_timeout,
            idle_timeout,
            last_cleanup: Instant::now(),
            cleanup_interval,
        }
    }

    #[inline]
    pub fn process_packet(&mut self, pkt: PacketMeta) -> Vec<ExportedFlow> {
        let key = FlowKey {
            src_ip: pkt.src_ip,
            dst_ip: pkt.dst_ip,
            src_port: pkt.src_port,
            dst_port: pkt.dst_port,
            proto: pkt.proto,
        };

        match self.flows.get_mut(&key) {
            Some(stats) => {
                let active_age = pkt.timestamp.duration_since(stats.first_seen);
                let idle_age = pkt.timestamp.duration_since(stats.last_seen);

                if active_age >= self.active_timeout || idle_age >= self.idle_timeout {
                    let old = self.flows.remove(&key).unwrap();
                    let exported = ExportedFlow { key, stats: old };
                    self.flows.insert(key, FlowStats::new(&pkt));

                    let mut out = Vec::with_capacity(1);
                    out.push(exported);

                    if pkt.timestamp.duration_since(self.last_cleanup) >= self.cleanup_interval {
                        self.last_cleanup = pkt.timestamp;
                        out.extend(self.cleanup_expired(pkt.timestamp));
                    }

                    out
                } else {
                    stats.update(&pkt);

                    if pkt.timestamp.duration_since(self.last_cleanup) >= self.cleanup_interval {
                        self.last_cleanup = pkt.timestamp;
                        self.cleanup_expired(pkt.timestamp)
                    } else {
                        Vec::new()
                    }
                }
            }
            None => {
                self.flows.insert(key, FlowStats::new(&pkt));

                if pkt.timestamp.duration_since(self.last_cleanup) >= self.cleanup_interval {
                    self.last_cleanup = pkt.timestamp;
                    self.cleanup_expired(pkt.timestamp)
                } else {
                    Vec::new()
                }
            }
        }
    }

    pub fn cleanup_expired(&mut self, now: Instant) -> Vec<ExportedFlow> {
        let mut expired = Vec::new();

        self.flows.retain(|key, stats| {
            let active_age = now.duration_since(stats.first_seen);
            let idle_age = now.duration_since(stats.last_seen);

            let keep = active_age < self.active_timeout && idle_age < self.idle_timeout;
            if !keep {
                expired.push(ExportedFlow {
                    key: *key,
                    stats: stats.clone(),
                });
            }
            keep
        });

        expired
    }

    pub fn export_all(&mut self) -> Vec<ExportedFlow> {
        let mut out = Vec::with_capacity(self.flows.len());
        for (key, stats) in self.flows.drain() {
            out.push(ExportedFlow { key, stats });
        }
        out
    }

    pub fn len(&self) -> usize {
        self.flows.len()
    }

    pub fn is_empty(&self) -> bool {
        self.flows.is_empty()
    }
}

fn export_flows(flows: &[ExportedFlow]) {
    for flow in flows {
        println!(
            "{:?}:{:?} -> {:?}:{:?} proto={:?} packets={} bytes={} duration_ms={}",
            flow.key.src_ip,
            flow.key.src_port,
            flow.key.dst_ip,
            flow.key.dst_port,
            flow.key.proto,
            flow.stats.packets,
            flow.stats.bytes,
            flow.stats
                .last_seen
                .duration_since(flow.stats.first_seen)
                .as_millis()
        );
    }
}

fn main() {
    let now = Instant::now();

    let mut table = FlowTable::new(
        1 << 16,
        Duration::from_secs(300),
        Duration::from_secs(30),
        Duration::from_secs(5),
    );

    let packets = vec![
        PacketMeta {
            timestamp: now,
            src_ip: Ipv4Addr::new(10, 0, 0, 1).into(),
            dst_ip: Ipv4Addr::new(10, 0, 0, 2).into(),
            src_port: 12345,
            dst_port: 80,
            proto: TransportProtocol::Tcp,
            payload_len: 500,
            tcp_flags: Some(TcpFlags {
                syn: true,
                ..Default::default()
            }),
        },
        PacketMeta {
            timestamp: now + Duration::from_millis(10),
            src_ip: Ipv4Addr::new(10, 0, 0, 1).into(),
            dst_ip: Ipv4Addr::new(10, 0, 0, 2).into(),
            src_port: 12345,
            dst_port: 80,
            proto: TransportProtocol::Tcp,
            payload_len: 1200,
            tcp_flags: Some(TcpFlags {
                ack: true,
                psh: true,
                ..Default::default()
            }),
        },
        PacketMeta {
            timestamp: now + Duration::from_secs(31),
            src_ip: Ipv4Addr::new(10, 0, 0, 1).into(),
            dst_ip: Ipv4Addr::new(10, 0, 0, 2).into(),
            src_port: 12345,
            dst_port: 80,
            proto: TransportProtocol::Tcp,
            payload_len: 300,
            tcp_flags: Some(TcpFlags {
                fin: true,
                ack: true,
                ..Default::default()
            }),
        },
    ];

    for pkt in packets {
        let exported = table.process_packet(pkt);
        if !exported.is_empty() {
            export_flows(&exported);
        }
    }

    let remaining = table.export_all();
    if !remaining.is_empty() {
        export_flows(&remaining);
    }
}
