# Improved hot-path version

Here is a slightly more performance-aware variant of the processing API that avoids returning a new vector each call.

Replace `process_packet` with:

```rust
impl FlowTable {
    #[inline]
    pub fn process_packet_into(&mut self, pkt: PacketMeta, out: &mut Vec<ExportedFlow>) {
        let key = FlowKey {
            src_ip: pkt.src_ip,
            dst_ip: pkt.dst_ip,
            src_port: pkt.src_port,
            dst_port: pkt.dst_port,
            proto: pkt.proto,
        };

        if let Some(stats) = self.flows.get_mut(&key) {
            let active_age = pkt.timestamp.duration_since(stats.first_seen);
            let idle_age = pkt.timestamp.duration_since(stats.last_seen);

            if active_age >= self.active_timeout || idle_age >= self.idle_timeout {
                let old = self.flows.remove(&key).unwrap();
                out.push(ExportedFlow { key, stats: old });
                self.flows.insert(key, FlowStats::new(&pkt));
            } else {
                stats.update(&pkt);
            }
        } else {
            self.flows.insert(key, FlowStats::new(&pkt));
        }

        if pkt.timestamp.duration_since(self.last_cleanup) >= self.cleanup_interval {
            self.last_cleanup = pkt.timestamp;
            self.cleanup_expired_into(pkt.timestamp, out);
        }
    }

    pub fn cleanup_expired_into(&mut self, now: Instant, out: &mut Vec<ExportedFlow>) {
        self.flows.retain(|key, stats| {
            let active_age = now.duration_since(stats.first_seen);
            let idle_age = now.duration_since(stats.last_seen);

            let keep = active_age < self.active_timeout && idle_age < self.idle_timeout;
            if !keep {
                out.push(ExportedFlow {
                    key: *key,
                    stats: stats.clone(),
                });
            }
            keep
        });
    }
}
```

And use it like:

```rust
let mut out = Vec::with_capacity(1024);
for pkt in packets {
    table.process_packet_into(pkt, &mut out);
    if !out.is_empty() {
        export_flows(&out);
        out.clear();
    }
}
```

