## `src/main.rs`

```rust
use ahash::AHasher;
use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Capture, Device};
use serde::Serialize;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const DEFAULT_SNAPLEN: i32 = 128;
const CHANNEL_CAPACITY: usize = 65536;
const FLOW_TIMEOUT_SECS: u64 = 30;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Debug, Clone, Copy, Hash, Eq, PartialEq)]
struct FlowKey {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Clone, Serialize)]
struct FlowStats {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    packets: u64,
    bytes: u64,
    first_seen_unix_secs: u64,
    last_seen_unix_secs: u64,
}

#[derive(Debug, Clone)]
struct FlowEntry {
    packets: u64,
    bytes: u64,
    first_seen_unix_secs: u64,
    last_seen_unix_secs: u64,
}

#[derive(Debug, Clone, Copy)]
struct PacketMeta {
    key: FlowKey,
    bytes: u32,
    ts_unix_secs: u64,
}

fn unix_now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0))
        .as_secs()
}

fn hash_flow_to_shard(key: &FlowKey, shards: usize) -> usize {
    let mut hasher = AHasher::default();
    key.hash(&mut hasher);
    (hasher.finish() as usize) % shards
}

fn parse_packet(data: &[u8], ts_unix_secs: u64) -> Option<PacketMeta> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    let (src, dst, proto) = match sliced.net {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = IpAddr::V4(Ipv4Addr::from(header.source()));
            let dst = IpAddr::V4(Ipv4Addr::from(header.destination()));
            (src, dst, header.protocol().0)
        }
        Some(InternetSlice::Ipv6(header, _)) => {
            let src = IpAddr::V6(Ipv6Addr::from(header.source()));
            let dst = IpAddr::V6(Ipv6Addr::from(header.destination()));
            (src, dst, header.next_header().0)
        }
        _ => return None,
    };

    let (src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
        Some(TransportSlice::Icmpv4(_)) => (0, 0),
        Some(TransportSlice::Icmpv6(_)) => (0, 0),
        _ => return None,
    };

    Some(PacketMeta {
        key: FlowKey {
            src,
            dst,
            src_port,
            dst_port,
            proto,
        },
        bytes: data.len() as u32,
        ts_unix_secs,
    })
}

fn worker_loop(
    shard_id: usize,
    rx: Receiver<PacketMeta>,
    running: Arc<AtomicBool>,
    export_interval: Duration,
    flow_timeout: Duration,
) {
    let mut flows: HashMap<FlowKey, FlowEntry, ahash::RandomState> =
        HashMap::with_hasher(ahash::RandomState::new());

    let mut last_export = unix_now_secs();

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(pkt) => {
                let entry = flows.entry(pkt.key).or_insert(FlowEntry {
                    packets: 0,
                    bytes: 0,
                    first_seen_unix_secs: pkt.ts_unix_secs,
                    last_seen_unix_secs: pkt.ts_unix_secs,
                });

                entry.packets += 1;
                entry.bytes += pkt.bytes as u64;
                if pkt.ts_unix_secs < entry.first_seen_unix_secs {
                    entry.first_seen_unix_secs = pkt.ts_unix_secs;
                }
                if pkt.ts_unix_secs > entry.last_seen_unix_secs {
                    entry.last_seen_unix_secs = pkt.ts_unix_secs;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }

        let now = unix_now_secs();
        if now.saturating_sub(last_export) >= export_interval.as_secs() {
            export_and_expire_flows(shard_id, &mut flows, now, flow_timeout.as_secs());
            last_export = now;
        }
    }

    let now = unix_now_secs();
    export_all_flows(shard_id, &mut flows, now);
}

fn export_and_expire_flows(
    shard_id: usize,
    flows: &mut HashMap<FlowKey, FlowEntry, ahash::RandomState>,
    now: u64,
    timeout_secs: u64,
) {
    let mut expired = Vec::new();

    for (k, v) in flows.iter() {
        if now.saturating_sub(v.last_seen_unix_secs) >= timeout_secs {
            expired.push(*k);
        }
    }

    for key in expired {
        if let Some(entry) = flows.remove(&key) {
            let stats = FlowStats {
                src: key.src,
                dst: key.dst,
                src_port: key.src_port,
                dst_port: key.dst_port,
                proto: key.proto,
                packets: entry.packets,
                bytes: entry.bytes,
                first_seen_unix_secs: entry.first_seen_unix_secs,
                last_seen_unix_secs: entry.last_seen_unix_secs,
            };

            println!("{}", serde_json::to_string(&stats).unwrap());
        }
    }

    eprintln!("shard={} active_flows={}", shard_id, flows.len());
}

fn export_all_flows(
    shard_id: usize,
    flows: &mut HashMap<FlowKey, FlowEntry, ahash::RandomState>,
    _now: u64,
) {
    for (key, entry) in flows.drain() {
        let stats = FlowStats {
            src: key.src,
            dst: key.dst,
            src_port: key.src_port,
            dst_port: key.dst_port,
            proto: key.proto,
            packets: entry.packets,
            bytes: entry.bytes,
            first_seen_unix_secs: entry.first_seen_unix_secs,
            last_seen_unix_secs: entry.last_seen_unix_secs,
        };

        println!("{}", serde_json::to_string(&stats).unwrap());
    }

    eprintln!("shard={} flushed", shard_id);
}

fn open_capture(device_name: &str) -> Capture<pcap::Active> {
    let device = Device::list()
        .expect("failed to list devices")
        .into_iter()
        .find(|d| d.name == device_name)
        .unwrap_or_else(|| panic!("device not found: {}", device_name));

    Capture::from_device(device)
        .expect("failed to create capture from device")
        .promisc(true)
        .snaplen(DEFAULT_SNAPLEN)
        .immediate_mode(true)
        .open()
        .expect("failed to open capture")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let device_name = args.get(1).map(String::as_str).unwrap_or("eth0");

    let worker_count = num_cpus::get().max(2);
    let running = Arc::new(AtomicBool::new(true));

    let mut txs: Vec<Sender<PacketMeta>> = Vec::with_capacity(worker_count);
    let mut handles = Vec::with_capacity(worker_count);

    for shard_id in 0..worker_count {
        let (tx, rx) = bounded::<PacketMeta>(CHANNEL_CAPACITY);
        txs.push(tx);

        let running_clone = Arc::clone(&running);
        let handle = thread::spawn(move || {
            worker_loop(
                shard_id,
                rx,
                running_clone,
                Duration::from_secs(EXPORT_INTERVAL_SECS),
                Duration::from_secs(FLOW_TIMEOUT_SECS),
            );
        });

        handles.push(handle);
    }

    {
        let running = Arc::clone(&running);
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .expect("failed to set Ctrl-C handler");
    }

    let mut cap = open_capture(device_name);

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let ts_unix_secs = packet.header.ts.tv_sec.max(0) as u64;
                if let Some(meta) = parse_packet(packet.data, ts_unix_secs) {
                    let shard = hash_flow_to_shard(&meta.key, worker_count);
                    if txs[shard].try_send(meta).is_err() {
                        // Backpressure policy:
                        // drop packet metadata if worker queue is full
                        // In production, count and export this metric.
                    }
                }
            }
            Err(err) => {
                eprintln!("capture error: {}", err);
                thread::sleep(Duration::from_millis(10));
            }
        }
    }

    drop(txs);

    for handle in handles {
        let _ = handle.join();
    }
}
```

