```rust
use ahash::AHasher;
use parking_lot::Mutex;
use serde::Serialize;
use std::collections::HashMap;
use std::hash::Hasher;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const IDLE_TIMEOUT_SECS: u64 = 30;
const ACTIVE_TIMEOUT_SECS: u64 = 300;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
pub enum TransportProtocol {
    Tcp,
    Udp,
    Icmp,
    Icmpv6,
    Other(u8),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
}

#[derive(Debug, Clone, Serialize)]
pub struct FlowRecord {
    pub key: FlowKey,
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: u64,
    pub last_seen: u64,
    pub tcp_syn: u32,
    pub tcp_fin: u32,
    pub tcp_rst: u32,
}

impl FlowRecord {
    fn new(key: FlowKey, ts: u64, bytes: usize) -> Self {
        Self {
            key,
            packets: 1,
            bytes: bytes as u64,
            first_seen: ts,
            last_seen: ts,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, ts: u64, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = ts;
    }
}

#[derive(Debug)]
pub struct ParsedPacket {
    pub timestamp_secs: u64,
    pub flow_key: FlowKey,
    pub payload_len: usize,
    pub tcp_flags: u8,
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn hash_flow_key(key: &FlowKey) -> u64 {
    let mut hasher = AHasher::default();
    match key.src_ip {
        IpAddr::V4(ip) => hasher.write(&ip.octets()),
        IpAddr::V6(ip) => hasher.write(&ip.octets()),
    }
    match key.dst_ip {
        IpAddr::V4(ip) => hasher.write(&ip.octets()),
        IpAddr::V6(ip) => hasher.write(&ip.octets()),
    }
    hasher.write_u16(key.src_port);
    hasher.write_u16(key.dst_port);
    match key.proto {
        TransportProtocol::Tcp => hasher.write_u8(6),
        TransportProtocol::Udp => hasher.write_u8(17),
        TransportProtocol::Icmp => hasher.write_u8(1),
        TransportProtocol::Icmpv6 => hasher.write_u8(58),
        TransportProtocol::Other(v) => hasher.write_u8(v),
    }
    hasher.finish()
}

pub struct FlowShard {
    inner: Mutex<HashMap<FlowKey, FlowRecord>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            inner: Mutex::new(HashMap::with_capacity(65_536)),
        }
    }
}

pub struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    pub fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    fn shard_for(&self, key: &FlowKey) -> usize {
        (hash_flow_key(key) as usize) % self.shards.len()
    }

    pub fn process_packet(&self, pkt: ParsedPacket) {
        let shard_idx = self.shard_for(&pkt.flow_key);
        let shard = &self.shards[shard_idx];
        let mut map = shard.inner.lock();

        let rec = map
            .entry(pkt.flow_key)
            .or_insert_with(|| FlowRecord::new(pkt.flow_key, pkt.timestamp_secs, pkt.payload_len));

        if rec.packets > 1 || rec.bytes > pkt.payload_len as u64 {
            rec.update(pkt.timestamp_secs, pkt.payload_len);
        }

        if rec.packets == 1 && rec.bytes == pkt.payload_len as u64 && rec.first_seen == pkt.timestamp_secs {
            // first packet already accounted for in new()
        } else {
            // update already done above
        }

        if matches!(rec.key.proto, TransportProtocol::Tcp) {
            if pkt.tcp_flags & 0x02 != 0 {
                rec.tcp_syn += 1;
            }
            if pkt.tcp_flags & 0x01 != 0 {
                rec.tcp_fin += 1;
            }
            if pkt.tcp_flags & 0x04 != 0 {
                rec.tcp_rst += 1;
            }
        }
    }

    pub fn process_batch(&self, packets: &[ParsedPacket]) {
        for pkt in packets {
            self.process_packet(pkt.clone());
        }
    }

    pub fn expire_and_export(&self, now: u64) -> Vec<FlowRecord> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.inner.lock();
            let mut to_remove = Vec::new();

            for (k, v) in map.iter() {
                let idle_expired = now.saturating_sub(v.last_seen) >= IDLE_TIMEOUT_SECS;
                let active_expired = now.saturating_sub(v.first_seen) >= ACTIVE_TIMEOUT_SECS;

                if idle_expired || active_expired {
                    expired.push(v.clone());
                    to_remove.push(*k);
                }
            }

            for k in to_remove {
                map.remove(&k);
            }
        }

        expired
    }
}

impl Clone for ParsedPacket {
    fn clone(&self) -> Self {
        Self {
            timestamp_secs: self.timestamp_secs,
            flow_key: self.flow_key,
            payload_len: self.payload_len,
            tcp_flags: self.tcp_flags,
        }
    }
}

pub fn parse_ethernet_frame(frame: &[u8], timestamp_secs: u64) -> Option<ParsedPacket> {
    if frame.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    match ethertype {
        0x0800 => parse_ipv4(&frame[14..], timestamp_secs),
        0x86DD => parse_ipv6(&frame[14..], timestamp_secs),
        _ => None,
    }
}

fn parse_ipv4(pkt: &[u8], timestamp_secs: u64) -> Option<ParsedPacket> {
    if pkt.len() < 20 {
        return None;
    }

    let version_ihl = pkt[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0F) as usize * 4;
    if version != 4 || pkt.len() < ihl || ihl < 20 {
        return None;
    }

    let total_len = u16::from_be_bytes([pkt[2], pkt[3]]) as usize;
    if total_len < ihl || pkt.len() < total_len {
        return None;
    }

    let proto = pkt[9];
    let src = Ipv4Addr::new(pkt[12], pkt[13], pkt[14], pkt[15]);
    let dst = Ipv4Addr::new(pkt[16], pkt[17], pkt[18], pkt[19]);

    let l4 = &pkt[ihl..total_len];
    parse_l4(
        IpAddr::V4(src),
        IpAddr::V4(dst),
        proto,
        l4,
        total_len,
        timestamp_secs,
    )
}

fn parse_ipv6(pkt: &[u8], timestamp_secs: u64) -> Option<ParsedPacket> {
    if pkt.len() < 40 {
        return None;
    }

    let version = pkt[0] >> 4;
    if version != 6 {
        return None;
    }

    let payload_len = u16::from_be_bytes([pkt[4], pkt[5]]) as usize;
    let next_header = pkt[6];
    if pkt.len() < 40 + payload_len {
        return None;
    }

    let src = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[8..24]).ok()?);
    let dst = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[24..40]).ok()?);

    let l4 = &pkt[40..40 + payload_len];
    parse_l4(
        IpAddr::V6(src),
        IpAddr::V6(dst),
        next_header,
        l4,
        40 + payload_len,
        timestamp_secs,
    )
}

fn parse_l4(
    src_ip: IpAddr,
    dst_ip: IpAddr,
    proto: u8,
    l4: &[u8],
    packet_len: usize,
    timestamp_secs: u64,
) -> Option<ParsedPacket> {
    match proto {
        6 => {
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let offset = ((l4[12] >> 4) as usize) * 4;
            if l4.len() < offset || offset < 20 {
                return None;
            }
            let flags = l4[13];

            Some(ParsedPacket {
                timestamp_secs,
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto: TransportProtocol::Tcp,
                },
                payload_len: packet_len,
                tcp_flags: flags,
            })
        }
        17 => {
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            Some(ParsedPacket {
                timestamp_secs,
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto: TransportProtocol::Udp,
                },
                payload_len: packet_len,
                tcp_flags: 0,
            })
        }
        1 => Some(ParsedPacket {
            timestamp_secs,
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto: TransportProtocol::Icmp,
            },
            payload_len: packet_len,
            tcp_flags: 0,
        }),
        58 => Some(ParsedPacket {
            timestamp_secs,
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto: TransportProtocol::Icmpv6,
            },
            payload_len: packet_len,
            tcp_flags: 0,
        }),
        other => Some(ParsedPacket {
            timestamp_secs,
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto: TransportProtocol::Other(other),
            },
            payload_len: packet_len,
            tcp_flags: 0,
        }),
    }
}

fn exporter_thread(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(5));
        let now = now_secs();
        let expired = table.expire_and_export(now);

        for flow in expired {
            println!("{}", serde_json::to_string(&flow).unwrap());
        }
    }
}

fn main() {
    let table = Arc::new(FlowTable::new());

    {
        let exporter_table = Arc::clone(&table);
        thread::spawn(move || exporter_thread(exporter_table));
    }

    // Example synthetic packets
    let ts = now_secs();

    let packets = vec![
        ParsedPacket {
            timestamp_secs: ts,
            flow_key: FlowKey {
                src_ip: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
                dst_ip: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
                src_port: 12345,
                dst_port: 80,
                proto: TransportProtocol::Tcp,
            },
            payload_len: 1500,
            tcp_flags: 0x02,
        },
        ParsedPacket {
            timestamp_secs: ts + 1,
            flow_key: FlowKey {
                src_ip: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
                dst_ip: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
                src_port: 12345,
                dst_port: 80,
                proto: TransportProtocol::Tcp,
            },
            payload_len: 1500,
            tcp_flags: 0x10,
        },
    ];

    table.process_batch(&packets);

    thread::sleep(Duration::from_secs(35));
}
