# A better hot-path version

Below is a cleaner version of the core update path using references and a more efficient entry pattern.

## Replace `process_packet` and `process_batch` with:

```rust
pub fn process_packet_ref(&self, pkt: &ParsedPacket) {
    let shard_idx = self.shard_for(&pkt.flow_key);
    let shard = &self.shards[shard_idx];
    let mut map = shard.inner.lock();

    use std::collections::hash_map::Entry;

    match map.entry(pkt.flow_key) {
        Entry::Occupied(mut e) => {
            let rec = e.get_mut();
            rec.update(pkt.timestamp_secs, pkt.payload_len);

            if matches!(rec.key.proto, TransportProtocol::Tcp) {
                if pkt.tcp_flags & 0x02 != 0 {
                    rec.tcp_syn += 1;
                }
                if pkt.tcp_flags & 0x01 != 0 {
                    rec.tcp_fin += 1;
                }
                if pkt.tcp_flags & 0x04 != 0 {
                    rec.tcp_rst += 1;
                }
            }
        }
        Entry::Vacant(e) => {
            let mut rec = FlowRecord::new(pkt.flow_key, pkt.timestamp_secs, pkt.payload_len);

            if matches!(rec.key.proto, TransportProtocol::Tcp) {
                if pkt.tcp_flags & 0x02 != 0 {
                    rec.tcp_syn += 1;
                }
                if pkt.tcp_flags & 0x01 != 0 {
                    rec.tcp_fin += 1;
                }
                if pkt.tcp_flags & 0x04 != 0 {
                    rec.tcp_rst += 1;
                }
            }

            e.insert(rec);
        }
    }
}

pub fn process_batch(&self, packets: &[ParsedPacket]) {
    for pkt in packets {
        self.process_packet_ref(pkt);
    }
}
```

