```rust
use clap::Parser;
use dashmap::DashMap;
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Interface to listen on
    #[arg(short, long)]
    iface: String,

    /// Flow idle timeout in seconds
    #[arg(long, default_value_t = 30)]
    idle_timeout: u64,

    /// Reporting interval in seconds
    #[arg(long, default_value_t = 5)]
    report_interval: u64,
}

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

struct Analyzer {
    flows: DashMap<FlowKey, FlowStats>,
    total_packets: AtomicU64,
    total_bytes: AtomicU64,
    running: AtomicBool,
    idle_timeout: Duration,
}

impl Analyzer {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: DashMap::new(),
            total_packets: AtomicU64::new(0),
            total_bytes: AtomicU64::new(0),
            running: AtomicBool::new(true),
            idle_timeout,
        }
    }

    fn process_packet(&self, packet: &[u8]) {
        self.total_packets.fetch_add(1, Ordering::Relaxed);
        self.total_bytes
            .fetch_add(packet.len() as u64, Ordering::Relaxed);

        let eth = match EthernetPacket::new(packet) {
            Some(p) => p,
            None => return,
        };

        if eth.get_ethertype() != EtherTypes::Ipv4 {
            return;
        }

        let ipv4 = match Ipv4Packet::new(eth.payload()) {
            Some(p) => p,
            None => return,
        };

        let src_ip = ipv4.get_source();
        let dst_ip = ipv4.get_destination();
        let proto = ipv4.get_next_level_protocol();

        let (src_port, dst_port, proto_num) = match proto {
            IpNextHeaderProtocols::Tcp => {
                let tcp = match TcpPacket::new(ipv4.payload()) {
                    Some(p) => p,
                    None => return,
                };
                (tcp.get_source(), tcp.get_destination(), 6u8)
            }
            IpNextHeaderProtocols::Udp => {
                let udp = match UdpPacket::new(ipv4.payload()) {
                    Some(p) => p,
                    None => return,
                };
                (udp.get_source(), udp.get_destination(), 17u8)
            }
            _ => return,
        };

        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto: proto_num,
        };

        let now = Instant::now();

        self.flows
            .entry(key)
            .and_modify(|stats| {
                stats.packets += 1;
                stats.bytes += packet.len() as u64;
                stats.last_seen = now;
            })
            .or_insert(FlowStats {
                packets: 1,
                bytes: packet.len() as u64,
                first_seen: now,
                last_seen: now,
            });
    }

    fn expire_flows(&self) -> usize {
        let now = Instant::now();
        let mut expired = Vec::new();

        for entry in self.flows.iter() {
            if now.duration_since(entry.value().last_seen) > self.idle_timeout {
                expired.push(*entry.key());
            }
        }

        let count = expired.len();
        for key in expired {
            self.flows.remove(&key);
        }

        count
    }

    fn report(&self) {
        let total_packets = self.total_packets.load(Ordering::Relaxed);
        let total_bytes = self.total_bytes.load(Ordering::Relaxed);
        let active_flows = self.flows.len();

        println!(
            "packets={} bytes={} active_flows={}",
            total_packets, total_bytes, active_flows
        );
    }
}

fn get_interface(name: &str) -> Option<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
}

fn main() {
    let args = Args::parse();

    let interface = get_interface(&args.iface).expect("interface not found");

    let config = Config {
        read_timeout: None,
        write_buffer_size: 0,
        read_buffer_size: 1 << 20,
        promiscuous: true,
        ..Default::default()
    };

    let analyzer = Arc::new(Analyzer::new(Duration::from_secs(args.idle_timeout)));
    let running = analyzer.running.clone();

    {
        let analyzer = Arc::clone(&analyzer);
        ctrlc::set_handler(move || {
            analyzer.running.store(false, Ordering::Relaxed);
        })
        .expect("failed to set Ctrl-C handler");
    }

    let reporter = {
        let analyzer = Arc::clone(&analyzer);
        let interval = Duration::from_secs(args.report_interval);
        thread::spawn(move || {
            while analyzer.running.load(Ordering::Relaxed) {
                thread::sleep(interval);
                let expired = analyzer.expire_flows();
                analyzer.report();
                if expired > 0 {
                    println!("expired_flows={}", expired);
                }
            }
        })
    };

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("unsupported channel type"),
        Err(e) => panic!("failed to create datalink channel: {}", e),
    };

    while analyzer.running.load(Ordering::Relaxed) {
        match rx.next() {
            Ok(packet) => analyzer.process_packet(packet),
            Err(_) => continue,
        }
    }

    reporter.join().ok();
    analyzer.report();
}
