# `src/main.rs`

```rust
use anyhow::{Context, Result};
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use serde::Serialize;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_WORKERS: usize = 4;
const CHANNEL_SIZE: usize = 65536;
const FLOW_TIMEOUT_SECS: u64 = 30;
const REPORT_INTERVAL_SECS: u64 = 5;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash, Serialize)]
enum Protocol {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
struct FlowKey {
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    proto: Protocol,
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug, Serialize)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_unix: u64,
    last_seen_unix: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
    tcp_ack: u32,
}

impl FlowStats {
    fn new(ts: u64, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen_unix: ts,
            last_seen_unix: ts,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
            tcp_ack: 0,
        }
    }

    fn update(&mut self, ts: u64, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen_unix = ts;
    }
}

#[derive(Clone, Debug)]
struct PacketRecord {
    timestamp_unix: u64,
    data: Vec<u8>,
}

#[derive(Serialize)]
struct ExportFlow {
    key: FlowKey,
    stats: FlowStats,
}

type FlowTable = DashMap<FlowKey, FlowStats>;

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn packet_worker(rx: Receiver<PacketRecord>, flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(pkt) => process_packet(&pkt, &flows),
            Err(_) => {}
        }
    }
}

fn process_packet(pkt: &PacketRecord, flows: &FlowTable) {
    let sliced = match SlicedPacket::from_ethernet(&pkt.data) {
        Ok(s) => s,
        Err(_) => return,
    };

    let (src_ip, dst_ip) = match sliced.net {
        Some(InternetSlice::Ipv4(header, _)) => {
            (header.source(), header.destination())
        }
        _ => return,
    };

    let (src_port, dst_port, proto, tcp_flags) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => {
            let mut flags = (0u32, 0u32, 0u32, 0u32);
            if tcp.syn() {
                flags.0 += 1;
            }
            if tcp.fin() {
                flags.1 += 1;
            }
            if tcp.rst() {
                flags.2 += 1;
            }
            if tcp.ack() {
                flags.3 += 1;
            }
            (
                tcp.source_port(),
                tcp.destination_port(),
                Protocol::Tcp,
                Some(flags),
            )
        }
        Some(TransportSlice::Udp(udp)) => (
            udp.source_port(),
            udp.destination_port(),
            Protocol::Udp,
            None,
        ),
        Some(other) => {
            let proto_num = match other {
                TransportSlice::Icmpv4(_) => 1,
                TransportSlice::Icmpv6(_) => 58,
                _ => 255,
            };
            (0, 0, Protocol::Other(proto_num), None)
        }
        None => return,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    let pkt_len = pkt.data.len();

    flows
        .entry(key)
        .and_modify(|stats| {
            stats.update(pkt.timestamp_unix, pkt_len);
            if let Some((syn, fin, rst, ack)) = tcp_flags {
                stats.tcp_syn += syn;
                stats.tcp_fin += fin;
                stats.tcp_rst += rst;
                stats.tcp_ack += ack;
            }
        })
        .or_insert_with(|| {
            let mut stats = FlowStats::new(pkt.timestamp_unix, pkt_len);
            if let Some((syn, fin, rst, ack)) = tcp_flags {
                stats.tcp_syn = syn;
                stats.tcp_fin = fin;
                stats.tcp_rst = rst;
                stats.tcp_ack = ack;
            }
            stats
        });
}

fn flow_expirer(flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));
        let now = now_unix();
        let mut expired = Vec::new();

        for item in flows.iter() {
            if now.saturating_sub(item.value().last_seen_unix) > FLOW_TIMEOUT_SECS {
                expired.push(*item.key());
            }
        }

        for key in expired {
            flows.remove(&key);
        }
    }
}

fn reporter(flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));

        let snapshot: Vec<ExportFlow> = flows
            .iter()
            .map(|entry| ExportFlow {
                key: *entry.key(),
                stats: entry.value().clone(),
            })
            .collect();

        let total_flows = snapshot.len();
        let total_packets: u64 = snapshot.iter().map(|f| f.stats.packets).sum();
        let total_bytes: u64 = snapshot.iter().map(|f| f.stats.bytes).sum();

        eprintln!(
            "active_flows={} total_packets={} total_bytes={}",
            total_flows, total_packets, total_bytes
        );

        if let Ok(json) = serde_json::to_string(&snapshot) {
            println!("{}", json);
        }
    }
}

fn capture_offline(path: &str, txs: &[Sender<PacketRecord>], running: Arc<AtomicBool>) -> Result<()> {
    let mut cap = pcap::Capture::from_file(path)
        .with_context(|| format!("failed to open pcap file: {}", path))?;

    let mut rr = 0usize;

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let ts = packet.header.ts.tv_sec as u64;
                let record = PacketRecord {
                    timestamp_unix: ts,
                    data: packet.data.to_vec(),
                };

                let tx = &txs[rr % txs.len()];
                if tx.send(record).is_err() {
                    break;
                }
                rr += 1;
            }
            Err(pcap::Error::NoMorePackets) => break,
            Err(e) => return Err(e).context("error reading packet from pcap"),
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        eprintln!("usage: {} <pcap-file>", args[0]);
        std::process::exit(1);
    }

    let running = Arc::new(AtomicBool::new(true));
    let flows = Arc::new(DashMap::with_capacity(1 << 20));

    let mut txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_handles = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<PacketRecord>(CHANNEL_SIZE);
        txs.push(tx);

        let flows_cloned = Arc::clone(&flows);
        let running_cloned = Arc::clone(&running);
        worker_handles.push(thread::spawn(move || {
            packet_worker(rx, flows_cloned, running_cloned);
        }));
    }

    let expirer_handle = {
        let flows = Arc::clone(&flows);
        let running = Arc::clone(&running);
        thread::spawn(move || flow_expirer(flows, running))
    };

    let reporter_handle = {
        let flows = Arc::clone(&flows);
        let running = Arc::clone(&running);
        thread::spawn(move || reporter(flows, running))
    };

    {
        let running = Arc::clone(&running);
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    capture_offline(&args[1], &txs, Arc::clone(&running))?;

    running.store(false, Ordering::Relaxed);

    drop(txs);

    for h in worker_handles {
        let _ = h.join();
    }
    let _ = expirer_handle.join();
    let _ = reporter_handle.join();

    Ok(())
}
```

