use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use rand::Rng;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_WORKERS: usize = 4;
const CHANNEL_CAPACITY: usize = 65536;
const REPORT_INTERVAL_SECS: u64 = 5;

/// Ethernet II header length
const ETH_HDR_LEN: usize = 14;
/// Minimum IPv4 header length
const IPV4_MIN_HDR_LEN: usize = 20;

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let src = Ipv4Addr::from(self.src_ip);
        let dst = Ipv4Addr::from(self.dst_ip);
        write!(
            f,
            "{}:{} -> {}:{} proto={}",
            src, self.src_port, dst, self.dst_port, self.proto
        )
    }
}

#[derive(Clone, Copy)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ms: u64,
    last_seen_ms: u64,
}

impl FlowStats {
    fn new(ts_ms: u64, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen_ms: ts_ms,
            last_seen_ms: ts_ms,
        }
    }

    fn update(&mut self, ts_ms: u64, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen_ms = ts_ms;
    }
}

struct Packet {
    timestamp_ms: u64,
    data: Vec<u8>,
}

/// Shared counters for observability.
struct Metrics {
    packets_received: AtomicU64,
    packets_parsed: AtomicU64,
    packets_dropped: AtomicU64,
    packets_unsupported: AtomicU64,
    flows_created: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            packets_received: AtomicU64::new(0),
            packets_parsed: AtomicU64::new(0),
            packets_dropped: AtomicU64::new(0),
            packets_unsupported: AtomicU64::new(0),
            flows_created: AtomicU64::new(0),
        }
    }
}

type FlowTable = DashMap<FlowKey, FlowStats>;

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

/// Parse Ethernet + IPv4 + TCP/UDP packet into a flow key.
/// Returns (flow_key, packet_len).
fn parse_flow_key(packet: &[u8]) -> Option<(FlowKey, usize)> {
    if packet.len() < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
        return None;
    }

    // Ethernet EtherType at bytes 12..14
    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only
    }

    let ip_offset = ETH_HDR_LEN;
    let version_ihl = packet[ip_offset];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < IPV4_MIN_HDR_LEN {
        return None;
    }

    if packet.len() < ETH_HDR_LEN + ihl {
        return None;
    }

    let proto = packet[ip_offset + 9];
    let src_ip = u32::from_be_bytes([
        packet[ip_offset + 12],
        packet[ip_offset + 13],
        packet[ip_offset + 14],
        packet[ip_offset + 15],
    ]);
    let dst_ip = u32::from_be_bytes([
        packet[ip_offset + 16],
        packet[ip_offset + 17],
        packet[ip_offset + 18],
        packet[ip_offset + 19],
    ]);

    let l4_offset = ETH_HDR_LEN + ihl;
    if packet.len() < l4_offset + 4 {
        return None;
    }

    match proto {
        6 | 17 => {
            let src_port = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
            let dst_port = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);
            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                packet.len(),
            ))
        }
        _ => None,
    }
}

fn worker_loop(
    worker_id: usize,
    rx: Receiver<Packet>,
    flow_table: Arc<FlowTable>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(pkt) => {
                metrics.packets_received.fetch_add(1, Ordering::Relaxed);

                if let Some((key, packet_len)) = parse_flow_key(&pkt.data) {
                    metrics.packets_parsed.fetch_add(1, Ordering::Relaxed);

                    let mut created = false;
                    flow_table
                        .entry(key)
                        .and_modify(|stats| stats.update(pkt.timestamp_ms, packet_len))
                        .or_insert_with(|| {
                            created = true;
                            FlowStats::new(pkt.timestamp_ms, packet_len)
                        });

                    if created {
                        metrics.flows_created.fetch_add(1, Ordering::Relaxed);
                    }
                } else {
                    metrics
                        .packets_unsupported
                        .fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }

    eprintln!("worker {} exiting", worker_id);
}

/// Simple dispatcher hash to assign packets to workers by flow-ish bytes.
/// In production, use RSS-compatible hashing or NIC queue affinity.
fn dispatch_index(packet: &[u8], workers: usize) -> usize {
    if packet.len() >= ETH_HDR_LEN + 20 {
        let mut h: u64 = 1469598103934665603;
        let sample = [
            packet[23], // protocol
            packet[26], packet[27], packet[28], packet[29], // src ip
            packet[30], packet[31], packet[32], packet[33], // dst ip
        ];
        for b in sample {
            h ^= b as u64;
            h = h.wrapping_mul(1099511628211);
        }
        (h as usize) % workers
    } else {
        0
    }
}

/// Mock packet source generating synthetic IPv4 TCP/UDP traffic.
/// Replace this with a real capture backend.
fn packet_source_loop(
    txs: Vec<Sender<Packet>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    let mut rng = rand::thread_rng();

    while running.load(Ordering::Relaxed) {
        let proto = if rng.gen_bool(0.7) { 6u8 } else { 17u8 };
        let src_ip = rng.gen::<u32>();
        let dst_ip = rng.gen::<u32>();
        let src_port = rng.gen_range(1024..65535) as u16;
        let dst_port = rng.gen_range(1..65535) as u16;

        let mut pkt = vec![0u8; ETH_HDR_LEN + 20 + 20];
        // Ethernet
        pkt[12] = 0x08;
        pkt[13] = 0x00;

        // IPv4
        pkt[14] = 0x45;
        pkt[23] = proto;
        pkt[26..30].copy_from_slice(&src_ip.to_be_bytes());
        pkt[30..34].copy_from_slice(&dst_ip.to_be_bytes());

        // L4 ports
        pkt[34..36].copy_from_slice(&src_port.to_be_bytes());
        pkt[36..38].copy_from_slice(&dst_port.to_be_bytes());

        let idx = dispatch_index(&pkt, txs.len());
        let packet = Packet {
            timestamp_ms: now_ms(),
            data: pkt,
        };

        if txs[idx].try_send(packet).is_err() {
            metrics.packets_dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn reporter_loop(
    flow_table: Arc<FlowTable>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));

        let packets_received = metrics.packets_received.load(Ordering::Relaxed);
        let packets_parsed = metrics.packets_parsed.load(Ordering::Relaxed);
        let packets_dropped = metrics.packets_dropped.load(Ordering::Relaxed);
        let packets_unsupported = metrics.packets_unsupported.load(Ordering::Relaxed);
        let flows_created = metrics.flows_created.load(Ordering::Relaxed);
        let active_flows = flow_table.len();

        println!("=== flow analyzer report ===");
        println!("packets_received   : {}", packets_received);
        println!("packets_parsed     : {}", packets_parsed);
        println!("packets_dropped    : {}", packets_dropped);
        println!("packets_unsupported: {}", packets_unsupported);
        println!("flows_created      : {}", flows_created);
        println!("active_flows       : {}", active_flows);

        // Print a few sample flows
        let mut shown = 0usize;
        for entry in flow_table.iter() {
            println!(
                "{} packets={} bytes={} first={} last={}",
                entry.key(),
                entry.value().packets,
                entry.value().bytes,
                entry.value().first_seen_ms,
                entry.value().last_seen_ms
            );
            shown += 1;
            if shown >= 5 {
                break;
            }
        }
        println!();
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());
    let flow_table = Arc::new(DashMap::with_capacity(1_000_000));

    let mut txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_handles = Vec::with_capacity(NUM_WORKERS);

    for worker_id in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Packet>(CHANNEL_CAPACITY);
        txs.push(tx);

        let flow_table_cloned = Arc::clone(&flow_table);
        let metrics_cloned = Arc::clone(&metrics);
        let running_cloned = Arc::clone(&running);

        let handle = thread::spawn(move || {
            worker_loop(
                worker_id,
                rx,
                flow_table_cloned,
                metrics_cloned,
                running_cloned,
            )
        });
        worker_handles.push(handle);
    }

    {
        let running_cloned = Arc::clone(&running);
        ctrlc::set_handler(move || {
            eprintln!("received Ctrl-C, shutting down...");
            running_cloned.store(false, Ordering::Relaxed);
        })
        .expect("failed to set Ctrl-C handler");
    }

    let reporter_handle = {
        let flow_table_cloned = Arc::clone(&flow_table);
        let metrics_cloned = Arc::clone(&metrics);
        let running_cloned = Arc::clone(&running);
        thread::spawn(move || reporter_loop(flow_table_cloned, metrics_cloned, running_cloned))
    };

    let source_handle = {
        let metrics_cloned = Arc::clone(&metrics);
        let running_cloned = Arc::clone(&running);
        thread::spawn(move || packet_source_loop(txs, metrics_cloned, running_cloned))
    };

    source_handle.join().unwrap();

    for handle in worker_handles {
        handle.join().unwrap();
    }

    reporter_handle.join().unwrap();

    println!("shutdown complete");
}
