use ahash::AHasher;
use crossbeam::channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const FLOW_TIMEOUT_SECS: u64 = 30;
const EXPIRE_INTERVAL_SECS: u64 = 5;
const CHANNEL_CAPACITY: usize = 1 << 16;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(u8)]
enum Protocol {
    Tcp = 6,
    Udp = 17,
    Other = 255,
}

#[derive(Clone, Copy, Debug)]
struct PacketMeta {
    timestamp_secs: u64,
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    protocol: Protocol,
    tcp_flags: u8,
    payload_bytes: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    protocol: Protocol,
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_flags_or: u8,
}

impl FlowStats {
    fn new(pkt: &PacketMeta) -> Self {
        Self {
            packets: 1,
            bytes: pkt.payload_bytes as u64,
            first_seen: pkt.timestamp_secs,
            last_seen: pkt.timestamp_secs,
            tcp_flags_or: pkt.tcp_flags,
        }
    }

    fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.payload_bytes as u64;
        if pkt.timestamp_secs < self.first_seen {
            self.first_seen = pkt.timestamp_secs;
        }
        if pkt.timestamp_secs > self.last_seen {
            self.last_seen = pkt.timestamp_secs;
        }
        self.tcp_flags_or |= pkt.tcp_flags;
    }
}

#[derive(Debug)]
struct FlowRecord {
    key: FlowKey,
    stats: FlowStats,
}

struct Shard {
    flows: Mutex<Vec<(FlowKey, FlowStats)>>,
}

impl Shard {
    fn new() -> Self {
        Self {
            flows: Mutex::new(Vec::with_capacity(4096)),
        }
    }
}

struct FlowTable {
    shards: Vec<Shard>,
}

impl FlowTable {
    fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(Shard::new());
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & (NUM_SHARDS - 1)
    }

    fn update_flow(&self, pkt: PacketMeta) {
        let key = FlowKey {
            src_ip: pkt.src_ip,
            dst_ip: pkt.dst_ip,
            src_port: pkt.src_port,
            dst_port: pkt.dst_port,
            protocol: pkt.protocol,
        };

        let idx = Self::shard_index(&key);
        let shard = &self.shards[idx];
        let mut flows = shard.flows.lock();

        for (existing_key, stats) in flows.iter_mut() {
            if *existing_key == key {
                stats.update(&pkt);
                return;
            }
        }

        flows.push((key, FlowStats::new(&pkt)));
    }

    fn expire_inactive(&self, now_secs: u64) -> Vec<FlowRecord> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut flows = shard.flows.lock();
            let mut i = 0;
            while i < flows.len() {
                let inactive = now_secs.saturating_sub(flows[i].1.last_seen) >= FLOW_TIMEOUT_SECS;
                if inactive {
                    let (key, stats) = flows.swap_remove(i);
                    expired.push(FlowRecord { key, stats });
                } else {
                    i += 1;
                }
            }
        }

        expired
    }

    fn active_flow_count(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.flows.lock().len())
            .sum()
    }
}

fn unix_now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn format_ipv4(ip: u32) -> String {
    Ipv4Addr::from(ip).to_string()
}

fn worker_loop(rx: Receiver<PacketMeta>, table: Arc<FlowTable>) {
    while let Ok(pkt) = rx.recv() {
        table.update_flow(pkt);
    }
}

fn expiration_loop(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(EXPIRE_INTERVAL_SECS));
        let now = unix_now_secs();
        let expired = table.expire_inactive(now);

        for flow in expired {
            println!(
                "EXPIRED {}:{} -> {}:{} proto={:?} packets={} bytes={} first={} last={} tcp_flags=0x{:02x}",
                format_ipv4(flow.key.src_ip),
                flow.key.src_port,
                format_ipv4(flow.key.dst_ip),
                flow.key.dst_port,
                flow.key.protocol,
                flow.stats.packets,
                flow.stats.bytes,
                flow.stats.first_seen,
                flow.stats.last_seen,
                flow.stats.tcp_flags_or
            );
        }

        println!("active_flows={}", table.active_flow_count());
    }
}

fn packet_producer(tx: Sender<PacketMeta>) {
    use rand::Rng;
    let mut rng = rand::thread_rng();

    loop {
        let pkt = PacketMeta {
            timestamp_secs: unix_now_secs(),
            src_ip: rng.gen::<u32>(),
            dst_ip: rng.gen::<u32>(),
            src_port: rng.gen_range(1024..65535),
            dst_port: if rng.gen_bool(0.5) { 80 } else { 443 },
            protocol: if rng.gen_bool(0.8) {
                Protocol::Tcp
            } else {
                Protocol::Udp
            },
            tcp_flags: if rng.gen_bool(0.8) { 0x18 } else { 0x02 },
            payload_bytes: rng.gen_range(64..1500),
        };

        if tx.send(pkt).is_err() {
            break;
        }
    }
}

fn main() {
    let table = Arc::new(FlowTable::new());
    let (tx, rx) = bounded::<PacketMeta>(CHANNEL_CAPACITY);

    let workers = thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);

    for _ in 0..workers {
        let rx_clone = rx.clone();
        let table_clone = Arc::clone(&table);
        thread::spawn(move || worker_loop(rx_clone, table_clone));
    }

    {
        let table_clone = Arc::clone(&table);
        thread::spawn(move || expiration_loop(table_clone));
    }

    packet_producer(tx);
}
```

