# `src/main.rs`

```rust
use anyhow::{Context, Result};
use dashmap::DashMap;
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::icmp::IcmpPacket;
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::time::sleep;

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const EXPIRY_SCAN_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum TransportProto {
    Tcp,
    Udp,
    Icmp,
    Icmpv6,
    Other(u8),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FlowAddr {
    V4(Ipv4Addr),
    V6(Ipv6Addr),
}

impl Hash for FlowAddr {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            FlowAddr::V4(a) => {
                4u8.hash(state);
                a.octets().hash(state);
            }
            FlowAddr::V6(a) => {
                6u8.hash(state);
                a.octets().hash(state);
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: FlowAddr,
    dst: FlowAddr,
    src_port: u16,
    dst_port: u16,
    proto: TransportProto,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

type FlowTable = DashMap<FlowKey, FlowStats>;

fn parse_transport_v4(ip: &Ipv4Packet) -> Option<(FlowKey, usize, u8)> {
    let src = FlowAddr::V4(ip.get_source());
    let dst = FlowAddr::V4(ip.get_destination());
    let payload = ip.payload();

    match ip.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(payload)?;
            let key = FlowKey {
                src,
                dst,
                src_port: tcp.get_source(),
                dst_port: tcp.get_destination(),
                proto: TransportProto::Tcp,
            };
            Some((key, ip.packet().len(), tcp.get_flags()))
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(payload)?;
            let key = FlowKey {
                src,
                dst,
                src_port: udp.get_source(),
                dst_port: udp.get_destination(),
                proto: TransportProto::Udp,
            };
            Some((key, ip.packet().len(), 0))
        }
        IpNextHeaderProtocols::Icmp => {
            let _icmp = IcmpPacket::new(payload)?;
            let key = FlowKey {
                src,
                dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Icmp,
            };
            Some((key, ip.packet().len(), 0))
        }
        other => {
            let key = FlowKey {
                src,
                dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Other(other.0),
            };
            Some((key, ip.packet().len(), 0))
        }
    }
}

fn parse_transport_v6(ip: &Ipv6Packet) -> Option<(FlowKey, usize, u8)> {
    let src = FlowAddr::V6(ip.get_source());
    let dst = FlowAddr::V6(ip.get_destination());
    let payload = ip.payload();

    match ip.get_next_header() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(payload)?;
            let key = FlowKey {
                src,
                dst,
                src_port: tcp.get_source(),
                dst_port: tcp.get_destination(),
                proto: TransportProto::Tcp,
            };
            Some((key, ip.packet().len(), tcp.get_flags()))
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(payload)?;
            let key = FlowKey {
                src,
                dst,
                src_port: udp.get_source(),
                dst_port: udp.get_destination(),
                proto: TransportProto::Udp,
            };
            Some((key, ip.packet().len(), 0))
        }
        IpNextHeaderProtocols::Icmpv6 => {
            let key = FlowKey {
                src,
                dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Icmpv6,
            };
            Some((key, ip.packet().len(), 0))
        }
        other => {
            let key = FlowKey {
                src,
                dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Other(other.0),
            };
            Some((key, ip.packet().len(), 0))
        }
    }
}

fn process_packet(frame: &[u8], flows: &FlowTable) {
    let now = Instant::now();

    let eth = match EthernetPacket::new(frame) {
        Some(p) => p,
        None => return,
    };

    let parsed = match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = match Ipv4Packet::new(eth.payload()) {
                Some(p) => p,
                None => return,
            };
            parse_transport_v4(&ip)
        }
        EtherTypes::Ipv6 => {
            let ip = match Ipv6Packet::new(eth.payload()) {
                Some(p) => p,
                None => return,
            };
            parse_transport_v6(&ip)
        }
        _ => None,
    };

    let (key, bytes, tcp_flags) = match parsed {
        Some(v) => v,
        None => return,
    };

    flows
        .entry(key)
        .and_modify(|stats| {
            stats.update(now, bytes);
            if key.proto == TransportProto::Tcp {
                if tcp_flags & 0x02 != 0 {
                    stats.tcp_syn += 1;
                }
                if tcp_flags & 0x01 != 0 {
                    stats.tcp_fin += 1;
                }
                if tcp_flags & 0x04 != 0 {
                    stats.tcp_rst += 1;
                }
            }
        })
        .or_insert_with(|| {
            let mut stats = FlowStats::new(now, bytes);
            if key.proto == TransportProto::Tcp {
                if tcp_flags & 0x02 != 0 {
                    stats.tcp_syn = 1;
                }
                if tcp_flags & 0x01 != 0 {
                    stats.tcp_fin = 1;
                }
                if tcp_flags & 0x04 != 0 {
                    stats.tcp_rst = 1;
                }
            }
            stats
        });
}

async fn expiry_task(flows: Arc<FlowTable>) {
    loop {
        sleep(EXPIRY_SCAN_INTERVAL).await;
        let now = Instant::now();
        let mut expired = Vec::new();

        for entry in flows.iter() {
            if now.duration_since(entry.value().last_seen) > FLOW_IDLE_TIMEOUT {
                expired.push(*entry.key());
            }
        }

        for key in expired {
            if let Some((key, stats)) = flows.remove(&key) {
                println!(
                    "EXPIRED flow={:?} packets={} bytes={} duration_ms={}",
                    key,
                    stats.packets,
                    stats.bytes,
                    stats.last_seen.duration_since(stats.first_seen).as_millis()
                );
            }
        }
    }
}

fn get_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface not found: {}", name))
}

fn run_capture(interface_name: &str, flows: Arc<FlowTable>) -> Result<()> {
    let interface = get_interface(interface_name)?;

    let mut config = Config::default();
    config.read_timeout = None;
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;
    config.promiscuous = true;

    let (_, mut rx) = match datalink::channel(&interface, config)
        .context("failed to create datalink channel")?
    {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    loop {
        match rx.next() {
            Ok(packet) => process_packet(packet, &flows),
            Err(_) => continue,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let interface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let flows = Arc::new(DashMap::with_capacity(1 << 20));

    let expiry_flows = flows.clone();
    tokio::spawn(async move {
        expiry_task(expiry_flows).await;
    });

    let capture_flows = flows.clone();
    let interface_clone = interface.clone();

    let handle = tokio::task::spawn_blocking(move || run_capture(&interface_clone, capture_flows));

    handle.await??;
    Ok(())
}
