use ahash::AHasher;
use crossbeam_channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use serde::Serialize;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 8;
const CHANNEL_BOUND: usize = 65536;
const FLOW_IDLE_TIMEOUT_SECS: u64 = 30;
const FLOW_ACTIVE_TIMEOUT_SECS: u64 = 300;

/// Compact transport protocol enum.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
#[repr(u8)]
pub enum TransportProtocol {
    Tcp = 6,
    Udp = 17,
    Icmp = 1,
    Icmpv6 = 58,
    Other(u8),
}

impl From<u8> for TransportProtocol {
    fn from(v: u8) -> Self {
        match v {
            6 => Self::Tcp,
            17 => Self::Udp,
            1 => Self::Icmp,
            58 => Self::Icmpv6,
            x => Self::Other(x),
        }
    }
}

/// Flow key: 5-tuple.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
}

/// Packet metadata extracted from a packet parser / capture engine.
#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub timestamp_secs: u64,
    pub length_bytes: u32,
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
    pub tcp_flags: u8,
}

impl PacketMeta {
    #[inline]
    pub fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            proto: self.proto,
        }
    }
}

/// Flow statistics.
#[derive(Debug, Clone, Serialize)]
pub struct FlowRecord {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,

    pub packets: u64,
    pub bytes: u64,

    pub first_seen: u64,
    pub last_seen: u64,

    pub tcp_syn_count: u32,
    pub tcp_fin_count: u32,
    pub tcp_rst_count: u32,
}

impl FlowRecord {
    #[inline]
    pub fn new(pkt: &PacketMeta) -> Self {
        let mut rec = Self {
            src_ip: pkt.src_ip,
            dst_ip: pkt.dst_ip,
            src_port: pkt.src_port,
            dst_port: pkt.dst_port,
            proto: pkt.proto,
            packets: 0,
            bytes: 0,
            first_seen: pkt.timestamp_secs,
            last_seen: pkt.timestamp_secs,
            tcp_syn_count: 0,
            tcp_fin_count: 0,
            tcp_rst_count: 0,
        };
        rec.update(pkt);
        rec
    }

    #[inline]
    pub fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.length_bytes as u64;
        self.last_seen = pkt.timestamp_secs;

        if matches!(pkt.proto, TransportProtocol::Tcp) {
            // TCP flags: FIN=0x01, SYN=0x02, RST=0x04
            if pkt.tcp_flags & 0x02 != 0 {
                self.tcp_syn_count += 1;
            }
            if pkt.tcp_flags & 0x01 != 0 {
                self.tcp_fin_count += 1;
            }
            if pkt.tcp_flags & 0x04 != 0 {
                self.tcp_rst_count += 1;
            }
        }
    }

    #[inline]
    pub fn is_expired(&self, now_secs: u64) -> bool {
        (now_secs - self.last_seen) >= FLOW_IDLE_TIMEOUT_SECS
            || (now_secs - self.first_seen) >= FLOW_ACTIVE_TIMEOUT_SECS
    }
}

/// Exported flow event.
#[derive(Debug, Clone, Serialize)]
pub struct ExportedFlow {
    pub flow: FlowRecord,
    pub reason: &'static str,
}

/// One shard of the flow table.
pub struct FlowShard {
    table: HashMap<FlowKey, FlowRecord, ahash::RandomState>,
}

impl FlowShard {
    pub fn new(capacity: usize) -> Self {
        Self {
            table: HashMap::with_capacity_and_hasher(capacity, ahash::RandomState::new()),
        }
    }

    #[inline]
    pub fn process_packet(&mut self, pkt: PacketMeta) {
        let key = pkt.flow_key();
        match self.table.get_mut(&key) {
            Some(flow) => flow.update(&pkt),
            None => {
                self.table.insert(key, FlowRecord::new(&pkt));
            }
        }
    }

    pub fn expire_flows(&mut self, now_secs: u64) -> Vec<ExportedFlow> {
        let mut expired = Vec::new();
        self.table.retain(|_, flow| {
            if flow.is_expired(now_secs) {
                let reason = if (now_secs - flow.last_seen) >= FLOW_IDLE_TIMEOUT_SECS {
                    "idle_timeout"
                } else {
                    "active_timeout"
                };
                expired.push(ExportedFlow {
                    flow: flow.clone(),
                    reason,
                });
                false
            } else {
                true
            }
        });
        expired
    }

    pub fn len(&self) -> usize {
        self.table.len()
    }
}

/// Worker message.
#[derive(Debug)]
pub enum WorkerMsg {
    Packet(PacketMeta),
    Expire(u64),
    Shutdown,
}

/// Worker stats.
#[derive(Debug, Default, Clone, Serialize)]
pub struct WorkerStats {
    pub packets_processed: u64,
    pub flows_active: usize,
    pub flows_exported: u64,
}

/// Worker thread.
pub fn worker_loop(
    shard_id: usize,
    rx: Receiver<WorkerMsg>,
    export_tx: Sender<ExportedFlow>,
    stats: Arc<Mutex<WorkerStats>>,
) {
    let mut shard = FlowShard::new(1 << 16);

    while let Ok(msg) = rx.recv() {
        match msg {
            WorkerMsg::Packet(pkt) => {
                shard.process_packet(pkt);
                let mut s = stats.lock();
                s.packets_processed += 1;
                s.flows_active = shard.len();
            }
            WorkerMsg::Expire(now_secs) => {
                let expired = shard.expire_flows(now_secs);
                if !expired.is_empty() {
                    let mut s = stats.lock();
                    s.flows_exported += expired.len() as u64;
                    s.flows_active = shard.len();
                    drop(s);

                    for flow in expired {
                        let _ = export_tx.send(flow);
                    }
                }
            }
            WorkerMsg::Shutdown => {
                let now_secs = now_secs();
                let expired = shard.expire_flows(now_secs);
                for flow in expired {
                    let _ = export_tx.send(flow);
                }
                break;
            }
        }
    }

    eprintln!("worker {} stopped", shard_id);
}

/// Main analyzer with sharded workers.
pub struct FlowAnalyzer {
    workers: Vec<Sender<WorkerMsg>>,
    export_rx: Receiver<ExportedFlow>,
    stats: Vec<Arc<Mutex<WorkerStats>>>,
}

impl FlowAnalyzer {
    pub fn new(num_shards: usize) -> Self {
        let (export_tx, export_rx) = bounded::<ExportedFlow>(CHANNEL_BOUND);
        let mut workers = Vec::with_capacity(num_shards);
        let mut stats = Vec::with_capacity(num_shards);

        for shard_id in 0..num_shards {
            let (tx, rx) = bounded::<WorkerMsg>(CHANNEL_BOUND);
            let shard_export_tx = export_tx.clone();
            let shard_stats = Arc::new(Mutex::new(WorkerStats::default()));
            let shard_stats_clone = shard_stats.clone();

            thread::Builder::new()
                .name(format!("flow-worker-{shard_id}"))
                .spawn(move || worker_loop(shard_id, rx, shard_export_tx, shard_stats_clone))
                .expect("failed to spawn worker");

            workers.push(tx);
            stats.push(shard_stats);
        }

        Self {
            workers,
            export_rx,
            stats,
        }
    }

    #[inline]
    fn shard_for_key(key: &FlowKey, num_shards: usize) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % num_shards
    }

    #[inline]
    pub fn process_packet(&self, pkt: PacketMeta) {
        let key = pkt.flow_key();
        let shard = Self::shard_for_key(&key, self.workers.len());
        let _ = self.workers[shard].send(WorkerMsg::Packet(pkt));
    }

    pub fn expire_all(&self, now_secs: u64) {
        for tx in &self.workers {
            let _ = tx.send(WorkerMsg::Expire(now_secs));
        }
    }

    pub fn try_drain_exports(&self) -> Vec<ExportedFlow> {
        let mut out = Vec::new();
        while let Ok(flow) = self.export_rx.try_recv() {
            out.push(flow);
        }
        out
    }

    pub fn snapshot_stats(&self) -> Vec<WorkerStats> {
        self.stats
            .iter()
            .map(|s| s.lock().clone())
            .collect()
    }

    pub fn shutdown(&self) {
        for tx in &self.workers {
            let _ = tx.send(WorkerMsg::Shutdown);
        }
    }
}

/// Return current UNIX time in seconds.
#[inline]
fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

/// Very lightweight synthetic packet generator for testing.
fn synthetic_packets(count: usize) -> Vec<PacketMeta> {
    let base_ts = now_secs();
    let mut packets = Vec::with_capacity(count);

    for i in 0..count {
        let src = IpAddr::V4(Ipv4Addr::new(10, 0, ((i / 256) % 256) as u8, (i % 256) as u8));
        let dst = IpAddr::V4(Ipv4Addr::new(192, 168, 1, ((i * 7) % 250 + 1) as u8));
        let proto = if i % 2 == 0 {
            TransportProtocol::Tcp
        } else {
            TransportProtocol::Udp
        };

        packets.push(PacketMeta {
            timestamp_secs: base_ts,
            length_bytes: 64 + (i % 1400) as u32,
            src_ip: src,
            dst_ip: dst,
            src_port: 10000 + (i % 1000) as u16,
            dst_port: 80,
            proto,
            tcp_flags: if matches!(proto, TransportProtocol::Tcp) && i % 10 == 0 {
                0x02
            } else {
                0
            },
        });
    }

    packets
}

fn main() {
    let analyzer = FlowAnalyzer::new(NUM_SHARDS);

    // Simulated ingestion thread
    let packets = synthetic_packets(500_000);
    for pkt in packets {
        analyzer.process_packet(pkt);
    }

    analyzer.expire_all(now_secs() + FLOW_IDLE_TIMEOUT_SECS + 1);

    thread::sleep(Duration::from_millis(500));

    let exports = analyzer.try_drain_exports();
    println!("exported flows: {}", exports.len());

    for flow in exports.iter().take(5) {
        println!("{}", serde_json::to_string(flow).unwrap());
    }

    let stats = analyzer.snapshot_stats();
    println!("worker stats:");
    for (i, s) in stats.iter().enumerate() {
        println!("shard {} => {}", i, serde_json::to_string(s).unwrap());
    }

    analyzer.shutdown();
}
