# `src/main.rs`

```rust
use anyhow::{Context, Result};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Active, Capture, Device};
use rustc_hash::FxHashMap;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant, SystemTime};

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const SNAPLEN: i32 = 256;
const PROMISC: bool = true;
const READ_TIMEOUT_MS: i32 = 10;

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: IpAddrKey,
    dst_ip: IpAddrKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}:{} -> {}:{} proto={}",
            self.src_ip, self.src_port, self.dst_ip, self.dst_port, self.proto
        )
    }
}

#[derive(Clone, Copy, Eq, PartialEq, Hash)]
enum IpAddrKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl fmt::Display for IpAddrKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IpAddrKey::V4(a) => write!(f, "{}", Ipv4Addr::from(*a)),
            IpAddrKey::V6(a) => write!(f, "{}", Ipv6Addr::from(*a)),
        }
    }
}

impl From<IpAddr> for IpAddrKey {
    fn from(ip: IpAddr) -> Self {
        match ip {
            IpAddr::V4(v4) => IpAddrKey::V4(v4.octets()),
            IpAddr::V6(v6) => IpAddrKey::V6(v6.octets()),
        }
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: SystemTime,
    last_seen: SystemTime,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: SystemTime, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: SystemTime, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct FlowTable {
    flows: FxHashMap<FlowKey, FlowStats>,
}

impl FlowTable {
    fn new() -> Self {
        Self {
            flows: FxHashMap::default(),
        }
    }

    fn process_packet(&mut self, packet: &[u8], ts: SystemTime) {
        let sliced = match SlicedPacket::from_ethernet(packet) {
            Ok(s) => s,
            Err(_) => return,
        };

        let (src_ip, dst_ip, proto) = match sliced.ip {
            Some(InternetSlice::Ipv4(header, _)) => {
                let src = IpAddrKey::V4(header.source());
                let dst = IpAddrKey::V4(header.destination());
                (src, dst, header.protocol())
            }
            Some(InternetSlice::Ipv6(header, _)) => {
                let src = IpAddrKey::V6(header.source());
                let dst = IpAddrKey::V6(header.destination());
                (src, dst, header.next_header())
            }
            _ => return,
        };

        let (src_port, dst_port, syn, fin, rst) = match sliced.transport {
            Some(TransportSlice::Tcp(tcp)) => (
                tcp.source_port(),
                tcp.destination_port(),
                tcp.syn(),
                tcp.fin(),
                tcp.rst(),
            ),
            Some(TransportSlice::Udp(udp)) => (
                udp.source_port(),
                udp.destination_port(),
                false,
                false,
                false,
            ),
            _ => return,
        };

        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        };

        let entry = self
            .flows
            .entry(key)
            .or_insert_with(|| FlowStats::new(ts, packet.len()));

        if entry.packets > 1 || entry.bytes > packet.len() as u64 {
            entry.update(ts, packet.len());
        }

        if syn {
            entry.tcp_syn += 1;
        }
        if fin {
            entry.tcp_fin += 1;
        }
        if rst {
            entry.tcp_rst += 1;
        }
    }

    fn expire_idle(&mut self, now: SystemTime) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();
        self.flows.retain(|k, v| {
            let idle = now
                .duration_since(v.last_seen)
                .unwrap_or_else(|_| Duration::from_secs(0));
            if idle >= FLOW_IDLE_TIMEOUT {
                expired.push((*k, v.clone()));
                false
            } else {
                true
            }
        });
        expired
    }

    fn top_n_by_bytes(&self, n: usize) -> Vec<(&FlowKey, &FlowStats)> {
        let mut items: Vec<_> = self.flows.iter().collect();
        items.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));
        items.truncate(n);
        items
    }

    fn len(&self) -> usize {
        self.flows.len()
    }
}

fn open_capture(interface: &str) -> Result<Capture<Active>> {
    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == interface)
        .with_context(|| format!("interface '{}' not found", interface))?;

    let cap = Capture::from_device(device)?
        .promisc(PROMISC)
        .snaplen(SNAPLEN)
        .timeout(READ_TIMEOUT_MS)
        .open()?;

    Ok(cap)
}

fn main() -> Result<()> {
    let interface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let mut cap = open_capture(&interface)?;
    cap.filter("ip or ip6", true)?;

    let mut table = FlowTable::new();
    let mut last_report = Instant::now();
    let mut packets_seen: u64 = 0;
    let mut bytes_seen: u64 = 0;

    eprintln!("starting capture on {}", interface);

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                packets_seen += 1;
                bytes_seen += packet.header.len as u64;

                let ts = SystemTime::now();
                table.process_packet(packet.data, ts);

                if last_report.elapsed() >= REPORT_INTERVAL {
                    report(&table, packets_seen, bytes_seen);
                    let expired = table.expire_idle(SystemTime::now());
                    if !expired.is_empty() {
                        eprintln!("expired {} idle flows", expired.len());
                    }
                    last_report = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                if last_report.elapsed() >= REPORT_INTERVAL {
                    report(&table, packets_seen, bytes_seen);
                    let expired = table.expire_idle(SystemTime::now());
                    if !expired.is_empty() {
                        eprintln!("expired {} idle flows", expired.len());
                    }
                    last_report = Instant::now();
                }
            }
            Err(e) => {
                eprintln!("capture error: {}", e);
            }
        }
    }

    eprintln!("shutting down");
    report(&table, packets_seen, bytes_seen);

    Ok(())
}

fn report(table: &FlowTable, packets_seen: u64, bytes_seen: u64) {
    println!("=== flow report ===");
    println!("active_flows={}", table.len());
    println!("packets_seen={}", packets_seen);
    println!("bytes_seen={}", bytes_seen);

    for (key, stats) in table.top_n_by_bytes(10) {
        println!(
            "{} packets={} bytes={} syn={} fin={} rst={}",
            key, stats.packets, stats.bytes, stats.tcp_syn, stats.tcp_fin, stats.tcp_rst
        );
    }
}
```

---

# Important fix

There is one hot-path correctness issue in the above code:

```rust
let entry = self
    .flows
    .entry(key)
    .or_insert_with(|| FlowStats::new(ts, packet.len()));

if entry.packets > 1 || entry.bytes > packet.len() as u64 {
    entry.update(ts, packet.len());
}
```

This is awkward and incorrect for the second packet of a flow. It should be replaced with a proper occupied/vacant match.

Use this corrected `process_packet` instead:

```rust
fn process_packet(&mut self, packet: &[u8], ts: SystemTime) {
    let sliced = match SlicedPacket::from_ethernet(packet) {
        Ok(s) => s,
        Err(_) => return,
    };

    let (src_ip, dst_ip, proto) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = IpAddrKey::V4(header.source());
            let dst = IpAddrKey::V4(header.destination());
            (src, dst, header.protocol())
        }
        Some(InternetSlice::Ipv6(header, _)) => {
            let src = IpAddrKey::V6(header.source());
            let dst = IpAddrKey::V6(header.destination());
            (src, dst, header.next_header())
        }
        _ => return,
    };

    let (src_port, dst_port, syn, fin, rst) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (
            tcp.source_port(),
            tcp.destination_port(),
            tcp.syn(),
            tcp.fin(),
            tcp.rst(),
        ),
        Some(TransportSlice::Udp(udp)) => (
            udp.source_port(),
            udp.destination_port(),
            false,
            false,
            false,
        ),
        _ => return,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    use std::collections::hash_map::Entry;
    match self.flows.entry(key) {
        Entry::Occupied(mut occ) => {
            let entry = occ.get_mut();
            entry.update(ts, packet.len());
            if syn {
                entry.tcp_syn += 1;
            }
            if fin {
                entry.tcp_fin += 1;
            }
            if rst {
                entry.tcp_rst += 1;
            }
        }
        Entry::Vacant(vac) => {
            let mut stats = FlowStats::new(ts, packet.len());
            if syn {
                stats.tcp_syn += 1;
            }
            if fin {
                stats.tcp_fin += 1;
            }
            if rst {
                stats.tcp_rst += 1;
            }
            vac.insert(stats);
        }
    }
}
```

Because `FxHashMap` aliases a hashbrown-backed map in many setups, if the `Entry` type import causes friction, you can also write:

```rust
if let Some(entry) = self.flows.get_mut(&key) {
    entry.update(ts, packet.len());
    if syn {
        entry.tcp_syn += 1;
    }
    if fin {
        entry.tcp_fin += 1;
    }
    if rst {
        entry.tcp_rst += 1;
    }
} else {
    let mut stats = FlowStats::new(ts, packet.len());
    if syn {
        stats.tcp_syn += 1;
    }
    if fin {
        stats.tcp_fin += 1;
    }
    if rst {
        stats.tcp_rst += 1;
    }
    self.flows.insert(key, stats);
}
```

