```rust
use ahash::AHashMap;
use pcap::{Active, Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_flags_or: u8,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_flags_or: tcp_flags,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
        self.tcp_flags_or |= tcp_flags;
    }
}

#[derive(Default)]
struct GlobalStats {
    total_packets: u64,
    total_bytes: u64,
    ipv4_packets: u64,
    tcp_packets: u64,
    udp_packets: u64,
    other_l4_packets: u64,
    parse_errors: u64,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let iface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == iface)
        .ok_or_else(|| format!("interface not found: {}", iface))?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(128)
        .timeout(1000)
        .open()?;

    cap.filter("ip", true)?;

    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(1 << 20);
    let mut global = GlobalStats::default();

    let mut last_export = Instant::now();
    let mut last_cleanup = Instant::now();

    eprintln!("Starting flow analyzer on interface {}", iface);

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                global.total_packets += 1;
                global.total_bytes += packet.header.len as u64;

                if let Some((key, tcp_flags)) = parse_packet(packet.data) {
                    global.ipv4_packets += 1;

                    match key.proto {
                        6 => global.tcp_packets += 1,
                        17 => global.udp_packets += 1,
                        _ => global.other_l4_packets += 1,
                    }

                    match flows.get_mut(&key) {
                        Some(stats) => stats.update(now, packet.header.len as usize, tcp_flags),
                        None => {
                            flows.insert(
                                key,
                                FlowStats::new(now, packet.header.len as usize, tcp_flags),
                            );
                        }
                    }
                } else {
                    global.parse_errors += 1;
                }

                if last_export.elapsed() >= EXPORT_INTERVAL {
                    export_stats(&flows, &global);
                    last_export = Instant::now();
                }

                if last_cleanup.elapsed() >= Duration::from_secs(1) {
                    expire_flows(&mut flows, now);
                    last_cleanup = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                let now = Instant::now();

                if last_export.elapsed() >= EXPORT_INTERVAL {
                    export_stats(&flows, &global);
                    last_export = now;
                }

                if last_cleanup.elapsed() >= Duration::from_secs(1) {
                    expire_flows(&mut flows, now);
                    last_cleanup = now;
                }
            }
            Err(e) => {
                eprintln!("capture error: {}", e);
                break;
            }
        }
    }

    eprintln!("Shutting down...");
    export_stats(&flows, &global);
    Ok(())
}

fn expire_flows(flows: &mut AHashMap<FlowKey, FlowStats>, now: Instant) {
    flows.retain(|_, stats| now.duration_since(stats.last_seen) < FLOW_TIMEOUT);
}

fn export_stats(flows: &AHashMap<FlowKey, FlowStats>, global: &GlobalStats) {
    println!("=== global ===");
    println!("total_packets={}", global.total_packets);
    println!("total_bytes={}", global.total_bytes);
    println!("ipv4_packets={}", global.ipv4_packets);
    println!("tcp_packets={}", global.tcp_packets);
    println!("udp_packets={}", global.udp_packets);
    println!("other_l4_packets={}", global.other_l4_packets);
    println!("parse_errors={}", global.parse_errors);
    println!("active_flows={}", flows.len());

    println!("=== top flows by bytes ===");
    let mut top: Vec<_> = flows.iter().collect();
    top.sort_unstable_by_key(|(_, stats)| std::cmp::Reverse(stats.bytes));

    for (key, stats) in top.into_iter().take(10) {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} age_s={} idle_s={} tcp_flags_or=0x{:02x}",
            Ipv4Addr::from(key.src_ip),
            key.src_port,
            Ipv4Addr::from(key.dst_ip),
            key.dst_port,
            key.proto,
            stats.packets,
            stats.bytes,
            stats.first_seen.elapsed().as_secs(),
            stats.last_seen.elapsed().as_secs(),
            stats.tcp_flags_or
        );
    }

    println!();
}

fn parse_packet(data: &[u8]) -> Option<(FlowKey, u8)> {
    // Ethernet II header: 14 bytes
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &data[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..];
    match proto {
        6 => parse_tcp(src_ip, dst_ip, proto, l4),
        17 => parse_udp(src_ip, dst_ip, proto, l4),
        _ => None,
    }
}

fn parse_tcp(src_ip: u32, dst_ip: u32, proto: u8, l4: &[u8]) -> Option<(FlowKey, u8)> {
    if l4.len() < 20 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
    let tcp_flags = l4[13];

    Some((
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        tcp_flags,
    ))
}

fn parse_udp(src_ip: u32, dst_ip: u32, proto: u8, l4: &[u8]) -> Option<(FlowKey, u8)> {
    if l4.len() < 8 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

    Some((
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        0,
    ))
}
