```rust
use ahash::AHasher;
use anyhow::{Context, Result};
use dashmap::DashMap;
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::icmp::IcmpPacket;
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use serde::Serialize;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::time::interval;

const FLOW_TIMEOUT_SECS: u64 = 30;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
enum TransportProto {
    Tcp,
    Udp,
    Icmp,
    Icmpv6,
    Other(u8),
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: TransportProto,
}

#[derive(Debug, Clone, Serialize)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_unix: u64,
    last_seen_unix: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: u64, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen_unix: now,
            last_seen_unix: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: u64, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen_unix = now;
    }
}

type FlowTable = DashMap<u64, Vec<(FlowKey, FlowStats)>>;

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn hash_flow_key(key: &FlowKey) -> u64 {
    let mut hasher = AHasher::default();
    key.hash(&mut hasher);
    hasher.finish()
}

fn update_flow(table: &FlowTable, key: FlowKey, pkt_len: usize, tcp_flags: Option<u8>) {
    let now = unix_now();
    let hash = hash_flow_key(&key);

    let mut bucket = table.entry(hash).or_insert_with(Vec::new);

    for (existing_key, stats) in bucket.iter_mut() {
        if *existing_key == key {
            stats.update(now, pkt_len);
            if let Some(flags) = tcp_flags {
                if flags & 0x02 != 0 {
                    stats.tcp_syn += 1;
                }
                if flags & 0x01 != 0 {
                    stats.tcp_fin += 1;
                }
                if flags & 0x04 != 0 {
                    stats.tcp_rst += 1;
                }
            }
            return;
        }
    }

    let mut stats = FlowStats::new(now, pkt_len);
    if let Some(flags) = tcp_flags {
        if flags & 0x02 != 0 {
            stats.tcp_syn += 1;
        }
        if flags & 0x01 != 0 {
            stats.tcp_fin += 1;
        }
        if flags & 0x04 != 0 {
            stats.tcp_rst += 1;
        }
    }
    bucket.push((key, stats));
}

fn parse_ipv4(table: &FlowTable, pkt: &Ipv4Packet) {
    let src = IpAddr::V4(pkt.get_source());
    let dst = IpAddr::V4(pkt.get_destination());
    let payload = pkt.payload();
    let total_len = pkt.get_total_length() as usize;

    match pkt.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(payload) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: TransportProto::Tcp,
                };
                update_flow(table, key, total_len, Some(tcp.get_flags()));
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(payload) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: TransportProto::Udp,
                };
                update_flow(table, key, total_len, None);
            }
        }
        IpNextHeaderProtocols::Icmp => {
            if IcmpPacket::new(payload).is_some() {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: 0,
                    dst_port: 0,
                    proto: TransportProto::Icmp,
                };
                update_flow(table, key, total_len, None);
            }
        }
        other => {
            let key = FlowKey {
                src_ip: src,
                dst_ip: dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Other(other.0),
            };
            update_flow(table, key, total_len, None);
        }
    }
}

fn parse_ipv6(table: &FlowTable, pkt: &Ipv6Packet) {
    let src = IpAddr::V6(pkt.get_source());
    let dst = IpAddr::V6(pkt.get_destination());
    let payload = pkt.payload();
    let total_len = pkt.get_payload_length() as usize + 40;

    match pkt.get_next_header() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(payload) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: TransportProto::Tcp,
                };
                update_flow(table, key, total_len, Some(tcp.get_flags()));
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(payload) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: TransportProto::Udp,
                };
                update_flow(table, key, total_len, None);
            }
        }
        IpNextHeaderProtocols::Icmpv6 => {
            let key = FlowKey {
                src_ip: src,
                dst_ip: dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Icmpv6,
            };
            update_flow(table, key, total_len, None);
        }
        other => {
            let key = FlowKey {
                src_ip: src,
                dst_ip: dst,
                src_port: 0,
                dst_port: 0,
                proto: TransportProto::Other(other.0),
            };
            update_flow(table, key, total_len, None);
        }
    }
}

fn handle_ethernet_frame(table: &FlowTable, frame: &[u8]) {
    if let Some(eth) = EthernetPacket::new(frame) {
        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                    parse_ipv4(table, &ipv4);
                }
            }
            EtherTypes::Ipv6 => {
                if let Some(ipv6) = Ipv6Packet::new(eth.payload()) {
                    parse_ipv6(table, &ipv6);
                }
            }
            _ => {}
        }
    }
}

async fn export_and_expire_task(table: Arc<FlowTable>) {
    let mut ticker = interval(Duration::from_secs(EXPORT_INTERVAL_SECS));

    loop {
        ticker.tick().await;
        let now = unix_now();
        let mut exported = Vec::new();
        let mut remove_hashes = Vec::new();

        for entry in table.iter_mut() {
            let hash = *entry.key();
            let bucket = entry.value();

            let mut retained = Vec::with_capacity(bucket.len());
            for (key, stats) in bucket.iter() {
                if now.saturating_sub(stats.last_seen_unix) >= FLOW_TIMEOUT_SECS {
                    exported.push((key.clone(), stats.clone()));
                } else {
                    retained.push((key.clone(), stats.clone()));
                }
            }

            if retained.is_empty() {
                remove_hashes.push(hash);
            } else if retained.len() != bucket.len() {
                drop(entry);
                if let Some(mut e) = table.get_mut(&hash) {
                    *e = retained;
                }
            }
        }

        for hash in remove_hashes {
            table.remove(&hash);
        }

        for (key, stats) in exported {
            match serde_json::to_string(&(key, stats)) {
                Ok(line) => println!("{line}"),
                Err(err) => eprintln!("export serialization error: {err}"),
            }
        }
    }
}

fn get_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface not found: {name}"))
}

fn capture_loop(interface_name: &str, table: Arc<FlowTable>) -> Result<()> {
    let interface = get_interface(interface_name)?;

    let mut config = Config::default();
    config.read_timeout = None;
    config.promiscuous = true;
    config.write_buffer_size = 0;
    config.read_buffer_size = 1 << 20;

    let channel = datalink::channel(&interface, config)
        .with_context(|| format!("failed to open datalink channel on {}", interface.name))?;

    match channel {
        Ethernet(_, mut rx) => loop {
            match rx.next() {
                Ok(packet) => handle_ethernet_frame(&table, packet),
                Err(err) => eprintln!("capture error: {err}"),
            }
        },
        _ => anyhow::bail!("unsupported channel type"),
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let interface_name = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let table = Arc::new(DashMap::with_capacity(1 << 16));
    let export_table = Arc::clone(&table);

    tokio::spawn(async move {
        export_and_expire_task(export_table).await;
    });

    let capture_table = Arc::clone(&table);
    let interface_for_thread = interface_name.clone();

    let capture_handle = std::thread::spawn(move || {
        if let Err(err) = capture_loop(&interface_for_thread, capture_table) {
            eprintln!("capture loop failed: {err:#}");
        }
    });

    capture_handle.join().unwrap();
    Ok(())
}
