## `src/main.rs`

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use serde::Serialize;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const CHANNEL_CAPACITY: usize = 65536;
const EXPORT_INTERVAL_SECS: u64 = 5;
const FLOW_TIMEOUT_SECS: u64 = 30;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum IpAddrKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: IpAddrKey,
    dst_ip: IpAddrKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Debug, Serialize)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ms: u128,
    last_seen_ms: u128,
}

struct PacketBatch {
    timestamp_ms: u128,
    data: Vec<u8>,
}

type FlowTable = DashMap<FlowKey, FlowStats>;

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

fn ipv4_to_key(ip: Ipv4Addr) -> IpAddrKey {
    IpAddrKey::V4(ip.octets())
}

fn ipv6_to_key(ip: Ipv6Addr) -> IpAddrKey {
    IpAddrKey::V6(ip.octets())
}

fn process_packet(packet: &[u8], timestamp_ms: u128, flows: &FlowTable) {
    let sliced = match SlicedPacket::from_ethernet(packet) {
        Ok(s) => s,
        Err(_) => return,
    };

    let (src_ip, dst_ip, proto) = match sliced.net {
        Some(InternetSlice::Ipv4(header, _)) => (
            ipv4_to_key(Ipv4Addr::from(header.source())),
            ipv4_to_key(Ipv4Addr::from(header.destination())),
            header.protocol().0,
        ),
        Some(InternetSlice::Ipv6(header, _)) => (
            ipv6_to_key(Ipv6Addr::from(header.source())),
            ipv6_to_key(Ipv6Addr::from(header.destination())),
            header.next_header().0,
        ),
        _ => return,
    };

    let (src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
        _ => return,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    let packet_len = packet.len() as u64;

    flows
        .entry(key)
        .and_modify(|stats| {
            stats.packets += 1;
            stats.bytes += packet_len;
            stats.last_seen_ms = timestamp_ms;
        })
        .or_insert(FlowStats {
            packets: 1,
            bytes: packet_len,
            first_seen_ms: timestamp_ms,
            last_seen_ms: timestamp_ms,
        });
}

fn worker_loop(rx: Receiver<PacketBatch>, flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(batch) => {
                process_packet(&batch.data, batch.timestamp_ms, &flows);
            }
            Err(_) => {}
        }
    }
}

fn exporter_loop(flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(EXPORT_INTERVAL_SECS));
        expire_and_export(&flows);
    }

    expire_and_export(&flows);
}

fn expire_and_export(flows: &FlowTable) {
    let cutoff = now_ms().saturating_sub(FLOW_TIMEOUT_SECS as u128 * 1000);
    let mut expired = Vec::new();

    for entry in flows.iter() {
        if entry.value().last_seen_ms < cutoff {
            expired.push((*entry.key(), entry.value().clone()));
        }
    }

    for (key, stats) in expired {
        flows.remove(&key);
        println!("{}", serde_json::to_string(&(key_to_json(&key), stats)).unwrap());
    }
}

#[derive(Serialize)]
struct FlowKeyJson {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

fn key_to_json(key: &FlowKey) -> FlowKeyJson {
    FlowKeyJson {
        src_ip: match key.src_ip {
            IpAddrKey::V4(o) => IpAddr::V4(Ipv4Addr::from(o)).to_string(),
            IpAddrKey::V6(o) => IpAddr::V6(Ipv6Addr::from(o)).to_string(),
        },
        dst_ip: match key.dst_ip {
            IpAddrKey::V4(o) => IpAddr::V4(Ipv4Addr::from(o)).to_string(),
            IpAddrKey::V6(o) => IpAddr::V6(Ipv6Addr::from(o)).to_string(),
        },
        src_port: key.src_port,
        dst_port: key.dst_port,
        proto: key.proto,
    }
}

fn capture_loop(
    iface: &str,
    txs: Vec<Sender<PacketBatch>>,
    running: Arc<AtomicBool>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut cap = pcap::Capture::from_device(iface)?
        .promisc(true)
        .immediate_mode(true)
        .open()?;

    let mut rr = 0usize;

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let batch = PacketBatch {
                    timestamp_ms: now_ms(),
                    data: packet.data.to_vec(),
                };

                let tx = &txs[rr % txs.len()];
                if tx.try_send(batch).is_err() {
                    // Drop packet under backpressure to preserve throughput.
                }
                rr = rr.wrapping_add(1);
            }
            Err(_) => {
                thread::sleep(Duration::from_millis(1));
            }
        }
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let iface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let running = Arc::new(AtomicBool::new(true));
    let flows = Arc::new(FlowTable::new());

    let worker_count = num_cpus::get().max(2) - 1;
    let mut worker_handles = Vec::new();
    let mut txs = Vec::new();

    for _ in 0..worker_count {
        let (tx, rx) = bounded::<PacketBatch>(CHANNEL_CAPACITY);
        txs.push(tx);

        let flows_clone = Arc::clone(&flows);
        let running_clone = Arc::clone(&running);

        worker_handles.push(thread::spawn(move || {
            worker_loop(rx, flows_clone, running_clone);
        }));
    }

    let exporter_flows = Arc::clone(&flows);
    let exporter_running = Arc::clone(&running);
    let exporter_handle = thread::spawn(move || {
        exporter_loop(exporter_flows, exporter_running);
    });

    let signal_running = Arc::clone(&running);
    ctrlc::set_handler(move || {
        signal_running.store(false, Ordering::Relaxed);
    })?;

    let capture_running = Arc::clone(&running);
    let capture_handle = thread::spawn(move || {
        if let Err(e) = capture_loop(&iface, txs, capture_running) {
            eprintln!("capture error: {e}");
        }
    });

    capture_handle.join().unwrap();

    for handle in worker_handles {
        handle.join().unwrap();
    }

    exporter_handle.join().unwrap();

    Ok(())
}
