```rust
use ahash::AHashMap;
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

const ETH_HDR_LEN: usize = 14;
const IPV4_MIN_HDR_LEN: usize = 20;
const TCP_MIN_HDR_LEN: usize = 20;
const UDP_HDR_LEN: usize = 8;

const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const MAX_FLOWS_HINT: usize = 1_000_000;

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Default)]
struct GlobalStats {
    total_packets: u64,
    total_bytes: u64,
    ipv4_packets: u64,
    tcp_packets: u64,
    udp_packets: u64,
    other_l4_packets: u64,
    parse_errors: u64,
    expired_flows: u64,
}

#[derive(Debug)]
struct ParsedPacket {
    flow_key: FlowKey,
    ip_total_len: usize,
    tcp_flags: Option<u8>,
}

fn parse_packet(data: &[u8]) -> Option<ParsedPacket> {
    if data.len() < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_offset = ETH_HDR_LEN;
    let version_ihl = data[ip_offset];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < IPV4_MIN_HDR_LEN {
        return None;
    }

    if data.len() < ip_offset + ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([data[ip_offset + 2], data[ip_offset + 3]]) as usize;
    let proto = data[ip_offset + 9];

    let src_ip = u32::from_be_bytes([
        data[ip_offset + 12],
        data[ip_offset + 13],
        data[ip_offset + 14],
        data[ip_offset + 15],
    ]);
    let dst_ip = u32::from_be_bytes([
        data[ip_offset + 16],
        data[ip_offset + 17],
        data[ip_offset + 18],
        data[ip_offset + 19],
    ]);

    let l4_offset = ip_offset + ihl;

    match proto {
        6 => {
            if data.len() < l4_offset + TCP_MIN_HDR_LEN {
                return None;
            }
            let src_port = u16::from_be_bytes([data[l4_offset], data[l4_offset + 1]]);
            let dst_port = u16::from_be_bytes([data[l4_offset + 2], data[l4_offset + 3]]);
            let flags = data[l4_offset + 13];

            Some(ParsedPacket {
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                ip_total_len: total_len,
                tcp_flags: Some(flags),
            })
        }
        17 => {
            if data.len() < l4_offset + UDP_HDR_LEN {
                return None;
            }
            let src_port = u16::from_be_bytes([data[l4_offset], data[l4_offset + 1]]);
            let dst_port = u16::from_be_bytes([data[l4_offset + 2], data[l4_offset + 3]]);

            Some(ParsedPacket {
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                ip_total_len: total_len,
                tcp_flags: None,
            })
        }
        _ => Some(ParsedPacket {
            flow_key: FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto,
            },
            ip_total_len: total_len,
            tcp_flags: None,
        }),
    }
}

fn expire_flows(flows: &mut AHashMap<FlowKey, FlowStats>, now: Instant, stats: &mut GlobalStats) {
    let before = flows.len();
    flows.retain(|_, flow| now.duration_since(flow.last_seen) < FLOW_TIMEOUT);
    let after = flows.len();
    stats.expired_flows += (before - after) as u64;
}

fn print_report(flows: &AHashMap<FlowKey, FlowStats>, stats: &GlobalStats, start: Instant) {
    let elapsed = start.elapsed().as_secs_f64();
    let pps = stats.total_packets as f64 / elapsed.max(1e-9);
    let bps = stats.total_bytes as f64 * 8.0 / elapsed.max(1e-9);

    println!("=== Flow Analyzer Report ===");
    println!("Uptime: {:.1}s", elapsed);
    println!("Packets: {}", stats.total_packets);
    println!("Bytes: {}", stats.total_bytes);
    println!("IPv4 packets: {}", stats.ipv4_packets);
    println!("TCP packets: {}", stats.tcp_packets);
    println!("UDP packets: {}", stats.udp_packets);
    println!("Other L4 packets: {}", stats.other_l4_packets);
    println!("Parse errors: {}", stats.parse_errors);
    println!("Active flows: {}", flows.len());
    println!("Expired flows: {}", stats.expired_flows);
    println!("Rate: {:.0} pps, {:.2} Mbps", pps, bps / 1_000_000.0);

    let mut top_flows: Vec<_> = flows.iter().collect();
    top_flows.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));
    top_flows.truncate(10);

    println!("Top flows by bytes:");
    for (key, flow) in top_flows {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} age={:.1}s idle={:.1}s syn={} fin={} rst={}",
            Ipv4Addr::from(key.src_ip),
            key.src_port,
            Ipv4Addr::from(key.dst_ip),
            key.dst_port,
            key.proto,
            flow.packets,
            flow.bytes,
            flow.first_seen.elapsed().as_secs_f64(),
            flow.last_seen.elapsed().as_secs_f64(),
            flow.tcp_syn,
            flow.tcp_fin,
            flow.tcp_rst,
        );
    }

    println!();
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })?;

    let device = Device::lookup()?
        .ok_or_else(|| "No capture device found".to_string())?;

    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(1000)
        .open()?;

    cap.filter("ip", true)?;

    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(MAX_FLOWS_HINT);
    let mut stats = GlobalStats::default();

    let start = Instant::now();
    let mut last_report = Instant::now();
    let mut last_expire = Instant::now();

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                stats.total_packets += 1;
                stats.total_bytes += packet.header.len as u64;

                match parse_packet(packet.data) {
                    Some(parsed) => {
                        stats.ipv4_packets += 1;

                        match parsed.flow_key.proto {
                            6 => stats.tcp_packets += 1,
                            17 => stats.udp_packets += 1,
                            _ => stats.other_l4_packets += 1,
                        }

                        let entry = flows
                            .entry(parsed.flow_key)
                            .or_insert_with(|| FlowStats::new(now, parsed.ip_total_len));

                        if entry.packets > 1 || entry.bytes > parsed.ip_total_len as u64 {
                            entry.update(now, parsed.ip_total_len);
                        }

                        if let Some(flags) = parsed.tcp_flags {
                            if flags & 0x02 != 0 {
                                entry.tcp_syn += 1;
                            }
                            if flags & 0x01 != 0 {
                                entry.tcp_fin += 1;
                            }
                            if flags & 0x04 != 0 {
                                entry.tcp_rst += 1;
                            }
                        }
                    }
                    None => {
                        stats.parse_errors += 1;
                    }
                }

                if last_report.elapsed() >= REPORT_INTERVAL {
                    print_report(&flows, &stats, start);
                    last_report = Instant::now();
                }

                if last_expire.elapsed() >= FLOW_TIMEOUT {
                    expire_flows(&mut flows, now, &mut stats);
                    last_expire = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                if last_report.elapsed() >= REPORT_INTERVAL {
                    print_report(&flows, &stats, start);
                    last_report = Instant::now();
                }

                if last_expire.elapsed() >= FLOW_TIMEOUT {
                    expire_flows(&mut flows, Instant::now(), &mut stats);
                    last_expire = Instant::now();
                }
            }
            Err(e) => {
                eprintln!("Capture error: {}", e);
                break;
            }
        }
    }

    println!("Shutting down...");
    print_report(&flows, &stats, start);

    Ok(())
}
