# `src/main.rs`

```rust
use ahash::AHashMap;
use crossbeam_channel::{bounded, Receiver, Sender};
use pcap::{Active, Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const BATCH_SIZE: usize = 4096;
const CHANNEL_CAPACITY: usize = 1024;
const FLOW_IDLE_TIMEOUT_SECS: u64 = 30;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u32(self.src_ip);
        state.write_u32(self.dst_ip);
        state.write_u16(self.src_port);
        state.write_u16(self.dst_port);
        state.write_u8(self.proto);
    }
}

#[derive(Clone, Copy, Debug)]
#[repr(C)]
struct PacketMeta {
    ts_sec: u64,
    ts_usec: u32,
    len: u32,
    key: FlowKey,
    tcp_flags: u8,
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_sec: u64,
    last_seen_sec: u64,
    tcp_flags_or: u8,
}

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn parse_ipv4_packet(data: &[u8], ts_sec: u64, ts_usec: u32) -> Option<PacketMeta> {
    // Ethernet II minimum header
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &data[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([ip[2], ip[3]]) as usize;
    if total_len < ihl || ip.len() < total_len {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..total_len];

    let (src_port, dst_port, tcp_flags) = match proto {
        6 => {
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let flags = l4[13];
            (src_port, dst_port, flags)
        }
        17 => {
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            (src_port, dst_port, 0)
        }
        1 => {
            // ICMP: encode type/code into ports for simple flow grouping
            if l4.len() < 2 {
                return None;
            }
            let src_port = l4[0] as u16;
            let dst_port = l4[1] as u16;
            (src_port, dst_port, 0)
        }
        _ => {
            (0, 0, 0)
        }
    };

    Some(PacketMeta {
        ts_sec,
        ts_usec,
        len: total_len as u32,
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
            _pad: 0,
        },
        tcp_flags,
    })
}

fn capture_thread(
    iface: String,
    tx: Sender<Vec<PacketMeta>>,
    running: Arc<AtomicBool>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let mut cap = Capture::from_device(iface.as_str())?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(1)
        .open()?;

    cap.filter("ip", true)?;

    let mut batch = Vec::with_capacity(BATCH_SIZE);

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let ts_sec = packet.header.ts.tv_sec as u64;
                let ts_usec = packet.header.ts.tv_usec as u32;

                if let Some(meta) = parse_ipv4_packet(packet.data, ts_sec, ts_usec) {
                    batch.push(meta);

                    if batch.len() >= BATCH_SIZE {
                        let mut out = Vec::with_capacity(BATCH_SIZE);
                        std::mem::swap(&mut out, &mut batch);
                        if tx.send(out).is_err() {
                            break;
                        }
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                if !batch.is_empty() {
                    let mut out = Vec::with_capacity(BATCH_SIZE);
                    std::mem::swap(&mut out, &mut batch);
                    if tx.send(out).is_err() {
                        break;
                    }
                }
            }
            Err(e) => {
                eprintln!("capture error: {e}");
                break;
            }
        }
    }

    if !batch.is_empty() {
        let _ = tx.send(batch);
    }

    Ok(())
}

fn export_flow(key: &FlowKey, stats: &FlowStats) {
    let src = Ipv4Addr::from(key.src_ip);
    let dst = Ipv4Addr::from(key.dst_ip);
    println!(
        "{}:{} -> {}:{} proto={} packets={} bytes={} first={} last={} tcp_flags=0x{:02x}",
        src,
        key.src_port,
        dst,
        key.dst_port,
        key.proto,
        stats.packets,
        stats.bytes,
        stats.first_seen_sec,
        stats.last_seen_sec,
        stats.tcp_flags_or
    );
}

fn expire_and_export(flows: &mut AHashMap<FlowKey, FlowStats>, now_sec: u64) {
    let mut expired = Vec::new();

    for (k, v) in flows.iter() {
        if now_sec.saturating_sub(v.last_seen_sec) >= FLOW_IDLE_TIMEOUT_SECS {
            expired.push(*k);
        }
    }

    for key in expired {
        if let Some(stats) = flows.remove(&key) {
            export_flow(&key, &stats);
        }
    }
}

fn aggregator_thread(rx: Receiver<Vec<PacketMeta>>, running: Arc<AtomicBool>) {
    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(1 << 20);
    let mut last_export = now_unix_secs();

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(200)) {
            Ok(batch) => {
                for pkt in batch {
                    let entry = flows.entry(pkt.key).or_insert(FlowStats {
                        packets: 0,
                        bytes: 0,
                        first_seen_sec: pkt.ts_sec,
                        last_seen_sec: pkt.ts_sec,
                        tcp_flags_or: 0,
                    });

                    entry.packets += 1;
                    entry.bytes += pkt.len as u64;
                    if pkt.ts_sec < entry.first_seen_sec {
                        entry.first_seen_sec = pkt.ts_sec;
                    }
                    if pkt.ts_sec > entry.last_seen_sec {
                        entry.last_seen_sec = pkt.ts_sec;
                    }
                    entry.tcp_flags_or |= pkt.tcp_flags;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }

        let now = now_unix_secs();
        if now.saturating_sub(last_export) >= EXPORT_INTERVAL_SECS {
            expire_and_export(&mut flows, now);
            last_export = now;
        }
    }

    for (k, v) in flows.drain() {
        export_flow(&k, &v);
    }
}

fn pick_default_device() -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
    let dev = Device::lookup()?
        .ok_or_else(|| "no default capture device found".to_string())?;
    Ok(dev.name)
}

fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let iface = std::env::args().nth(1).unwrap_or(pick_default_device()?);

    let running = Arc::new(AtomicBool::new(true));
    let (tx, rx) = bounded::<Vec<PacketMeta>>(CHANNEL_CAPACITY);

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let cap_running = running.clone();
    let agg_running = running.clone();

    let cap_handle = thread::spawn(move || capture_thread(iface, tx, cap_running));
    let agg_handle = thread::spawn(move || aggregator_thread(rx, agg_running));

    match cap_handle.join() {
        Ok(Ok(())) => {}
        Ok(Err(e)) => eprintln!("capture thread failed: {e}"),
        Err(_) => eprintln!("capture thread panicked"),
    }

    running.store(false, Ordering::Relaxed);

    match agg_handle.join() {
        Ok(()) => {}
        Err(_) => eprintln!("aggregator thread panicked"),
    }

    Ok(())
}
```

