## `src/main.rs`

```rust
use ahash::AHasher;
use crossbeam_channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use pcap::{Capture, Device};
use serde::Serialize;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const CHANNEL_SIZE: usize = 65536;
const FLOW_TIMEOUT_SECS: u64 = 30;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Clone, Serialize)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ExportFlow {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
}

#[derive(Debug)]
struct PacketMeta {
    ts_sec: u64,
    len: usize,
    key: FlowKey,
}

struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowStats>>,
}

struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(FlowShard {
                map: Mutex::new(HashMap::with_hasher(Default::default())),
            });
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    #[inline]
    fn update(&self, pkt: PacketMeta) {
        let idx = self.shard_index(&pkt.key);
        let mut map = self.shards[idx].map.lock();
        match map.get_mut(&pkt.key) {
            Some(stats) => {
                stats.packets += 1;
                stats.bytes += pkt.len as u64;
                stats.last_seen = pkt.ts_sec;
            }
            None => {
                map.insert(
                    pkt.key,
                    FlowStats {
                        packets: 1,
                        bytes: pkt.len as u64,
                        first_seen: pkt.ts_sec,
                        last_seen: pkt.ts_sec,
                    },
                );
            }
        }
    }

    fn expire_and_export(&self, now: u64) -> Vec<ExportFlow> {
        let mut exported = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.lock();
            let mut expired_keys = Vec::new();

            for (key, stats) in map.iter() {
                if now.saturating_sub(stats.last_seen) >= FLOW_TIMEOUT_SECS {
                    exported.push(ExportFlow {
                        src_ip: Ipv4Addr::from(key.src_ip).to_string(),
                        dst_ip: Ipv4Addr::from(key.dst_ip).to_string(),
                        src_port: key.src_port,
                        dst_port: key.dst_port,
                        proto: key.proto,
                        packets: stats.packets,
                        bytes: stats.bytes,
                        first_seen: stats.first_seen,
                        last_seen: stats.last_seen,
                    });
                    expired_keys.push(*key);
                }
            }

            for key in expired_keys {
                map.remove(&key);
            }
        }

        exported
    }
}

fn parse_ipv4_flow(packet: &[u8], ts_sec: u64) -> Option<PacketMeta> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ip.len() < ihl || ihl < 20 {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    match proto {
        6 | 17 => {
            if ip.len() < ihl + 4 {
                return None;
            }
            let l4 = &ip[ihl..];
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

            Some(PacketMeta {
                ts_sec,
                len: packet.len(),
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
            })
        }
        _ => None,
    }
}

fn capture_thread(tx: Sender<Vec<u8>>, running: Arc<AtomicBool>, iface: String) {
    let mut cap = Capture::from_device(iface.as_str())
        .unwrap()
        .promisc(true)
        .immediate_mode(true)
        .open()
        .unwrap();

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let data = packet.data.to_vec();
                if tx.send(data).is_err() {
                    break;
                }
            }
            Err(_) => {
                continue;
            }
        }
    }
}

fn worker_thread(rx: Receiver<Vec<u8>>, table: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(packet) => {
                let ts_sec = SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_secs();
                if let Some(meta) = parse_ipv4_flow(&packet, ts_sec) {
                    table.update(meta);
                }
            }
            Err(_) => {}
        }
    }
}

fn exporter_thread(table: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(EXPORT_INTERVAL_SECS));
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let flows = table.expire_and_export(now);
        for flow in flows {
            println!("{}", serde_json::to_string(&flow).unwrap());
        }
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let flows = table.expire_and_export(now + FLOW_TIMEOUT_SECS + 1);
    for flow in flows {
        println!("{}", serde_json::to_string(&flow).unwrap());
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let table = Arc::new(FlowTable::new(NUM_SHARDS));

    let devices = Device::list().unwrap();
    let iface = devices
        .into_iter()
        .find(|d| !d.flags.is_loopback())
        .expect("No suitable interface found")
        .name;

    let (tx, rx) = bounded::<Vec<u8>>(CHANNEL_SIZE);

    let capture_running = running.clone();
    let capture_iface = iface.clone();
    let capture_handle = thread::spawn(move || {
        capture_thread(tx, capture_running, capture_iface);
    });

    let mut worker_handles = Vec::new();
    let workers = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);

    for _ in 0..workers {
        let rx_clone = rx.clone();
        let table_clone = table.clone();
        let running_clone = running.clone();
        worker_handles.push(thread::spawn(move || {
            worker_thread(rx_clone, table_clone, running_clone);
        }));
    }

    let exporter_running = running.clone();
    let exporter_table = table.clone();
    let exporter_handle = thread::spawn(move || {
        exporter_thread(exporter_table, exporter_running);
    });

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .unwrap();
    }

    capture_handle.join().unwrap();
    for h in worker_handles {
        h.join().unwrap();
    }
    exporter_handle.join().unwrap();
}
```

