fn capture_thread(tx: Sender<PacketMeta>, running: Arc<AtomicBool>, iface: String) {
    let mut cap = Capture::from_device(iface.as_str())
        .unwrap()
        .promisc(true)
        .immediate_mode(true)
        .open()
