## Minimal working prototype in C

Below is a **small single-file C prototype** using `libpcap`. It is **not production-grade**, but it is a working baseline flow analyzer.

### Features
- Captures IPv4 TCP/UDP packets
- Tracks flows by 5-tuple
- Counts packets and bytes
- Expires idle flows
- Prints expired flows

---

```c
// flowmon.c
// Minimal IPv4 TCP/UDP flow analyzer using libpcap
// Build: gcc -O3 -o flowmon flowmon.c -lpcap

#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE 65536
#define IDLE_TIMEOUT 30
#define SWEEP_INTERVAL 5

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];
static volatile int running = 1;
static time_t last_sweep = 0;

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h % HASH_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
    struct in_addr s = { .s_addr = f->key.src_ip };
    struct in_addr d = { .s_addr = f->key.dst_ip };

    inet_ntop(AF_INET, &s, src, sizeof(src));
    inet_ntop(AF_INET, &d, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu duration=%lds\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           (unsigned long long)f->packets,
           (unsigned long long)f->bytes,
           (long)(f->last_seen - f->first_seen));
}

static void expire_flows(time_t now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *f = *pp;
            if ((now - f->last_seen) > IDLE_TIMEOUT) {
                print_flow(f);
                *pp = f->next;
                free(f);
            } else {
                pp = &f->next;
            }
        }
    }
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, time_t now) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *f = flow_table[idx];

    while (f) {
        if (flow_equal(&f->key, key)) {
            f->packets++;
            f->bytes += pkt_len;
            f->last_seen = now;
            return;
        }
        f = f->next;
    }

    f = calloc(1, sizeof(*f));
    if (!f) return;

    f->key = *key;
    f->packets = 1;
    f->bytes = pkt_len;
    f->first_seen = now;
    f->last_seen = now;
    f->next = flow_table[idx];
    flow_table[idx] = f;
}

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

#pragma pack(push, 1)
struct eth_hdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct ipv4_hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t proto;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct tcp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct udp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static void packet_handler(u_char *user,
                           const struct pcap_pkthdr *h,
                           const u_char *bytes) {
    (void)user;
    time_t now = time(NULL);

    if (h->caplen < sizeof(struct eth_hdr)) return;
    const struct eth_hdr *eth = (const struct eth_hdr *)bytes;
    if (ntohs(eth->ethertype) != 0x0800) return; // IPv4 only

    const u_char *ip_ptr = bytes + sizeof(struct eth_hdr);
    if (h->caplen < sizeof(struct eth_hdr) + sizeof(struct ipv4_hdr)) return;

    const struct ipv4_hdr *ip = (const struct ipv4_hdr *)ip_ptr;
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return;
    if (h->caplen < sizeof(struct eth_hdr) + ihl) return;

    flow_key_t key = {0};
    key.src_ip = ip->src_ip;
    key.dst_ip = ip->dst_ip;
    key.proto = ip->proto;

    const u_char *l4_ptr = ip_ptr + ihl;

    if (ip->proto == 6) { // TCP
        if (h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct tcp_hdr)) return;
        const struct tcp_hdr *tcp = (const struct tcp_hdr *)l4_ptr;
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
    } else if (ip->proto == 17) { // UDP
        if (h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct udp_hdr)) return;
        const struct udp_hdr *udp = (const struct udp_hdr *)l4_ptr;
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
    } else {
        return;
    }

    update_flow(&key, h->len, now);

    if ((now - last_sweep) >= SWEEP_INTERVAL) {
        expire_flows(now);
        last_sweep = now;
    }
}

static void flush_all(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *f = flow_table[i];
        while (f) {
            flow_entry_t *next = f->next;
            print_flow(f);
            free(f);
            f = next;
        }
        flow_table[i] = NULL;
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pcap = pcap_open_live(argv[1], 65535, 1, 1000, errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(pcap, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(pcap, &fp);
        pcap_freecode(&fp);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    last_sweep = time(NULL);

    while (running) {
        int rc = pcap_dispatch(pcap, 256, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(pcap));
            break;
        }
    }

    flush_all();
    pcap_close(pcap);
    return 0;
}
