# File: `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#define HASH_SIZE (1 << 20)   // 1M buckets
#define REPORT_INTERVAL 5
#define SNAPLEN 128

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ms;
    uint64_t last_seen_ms;
    int used;
} flow_entry_t;

static flow_entry_t *flow_table;
static volatile int running = 1;

static uint64_t now_ms(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (uint64_t)tv.tv_sec * 1000ULL + tv.tv_usec / 1000ULL;
}

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h & (HASH_SIZE - 1);
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, uint64_t ts_ms) {
    uint32_t idx = hash_flow(key);

    for (uint32_t i = 0; i < 16; i++) {
        flow_entry_t *e = &flow_table[(idx + i) & (HASH_SIZE - 1)];
        if (!e->used) {
            e->used = 1;
            e->key = *key;
            e->packets = 0;
            e->bytes = 0;
            e->first_seen_ms = ts_ms;
            e->last_seen_ms = ts_ms;
            return e;
        }
        if (flow_equal(&e->key, key)) {
            return e;
        }
    }

    // Simple overwrite policy under collision pressure
    flow_entry_t *e = &flow_table[idx];
    e->used = 1;
    e->key = *key;
    e->packets = 0;
    e->bytes = 0;
    e->first_seen_ms = ts_ms;
    e->last_seen_ms = ts_ms;
    return e;
}

static void print_ip(uint32_t ip, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void report_flows(void) {
    printf("=== Flow Report ===\n");
    int shown = 0;

    for (size_t i = 0; i < HASH_SIZE && shown < 20; i++) {
        flow_entry_t *e = &flow_table[i];
        if (!e->used) continue;

        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        print_ip(e->key.src_ip, src, sizeof(src));
        print_ip(e->key.dst_ip, dst, sizeof(dst));

        printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu age=%llums idle=%llums\n",
               src, ntohs(e->key.src_port),
               dst, ntohs(e->key.dst_port),
               e->key.proto,
               (unsigned long long)e->packets,
               (unsigned long long)e->bytes,
               (unsigned long long)(now_ms() - e->first_seen_ms),
               (unsigned long long)(now_ms() - e->last_seen_ms));
        shown++;
    }
    printf("\n");
}

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void process_packet(u_char *user,
                           const struct pcap_pkthdr *h,
                           const u_char *bytes) {
    (void)user;

    if (h->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = bytes + sizeof(struct ether_header);
    size_t ip_len_avail = h->caplen - sizeof(struct ether_header);
    if (ip_len_avail < sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ip_ptr;
    if (iph->ip_v != 4) return;

    size_t ip_header_len = iph->ip_hl * 4;
    if (ip_header_len < sizeof(struct ip) || ip_len_avail < ip_header_len) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const u_char *l4 = ip_ptr + ip_header_len;
    size_t l4_avail = ip_len_avail - ip_header_len;

    if (iph->ip_p == IPPROTO_TCP) {
        if (l4_avail < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (l4_avail < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    uint64_t ts_ms = (uint64_t)h->ts.tv_sec * 1000ULL + h->ts.tv_usec / 1000ULL;
    flow_entry_t *e = flow_lookup_or_create(&key, ts_ms);
    e->packets++;
    e->bytes += h->len;
    e->last_seen_ms = ts_ms;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [bpf-filter]\n", argv[0]);
        return 1;
    }

    const char *dev = argv[1];
    const char *filter_exp = (argc >= 3) ? argv[2] : "ip";

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    flow_table = calloc(HASH_SIZE, sizeof(flow_entry_t));
    if (!flow_table) {
        perror("calloc");
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pc = pcap_create(dev, errbuf);
    if (!pc) {
        fprintf(stderr, "pcap_create: %s\n", errbuf);
        free(flow_table);
        return 1;
    }

    pcap_set_snaplen(pc, SNAPLEN);
    pcap_set_promisc(pc, 1);
    pcap_set_timeout(pc, 1000);
#ifdef PCAP_ERROR_ACTIVATED
    pcap_set_immediate_mode(pc, 1);
#endif
    pcap_set_buffer_size(pc, 64 * 1024 * 1024);

    int rc = pcap_activate(pc);
    if (rc < 0) {
        fprintf(stderr, "pcap_activate: %s\n", pcap_geterr(pc));
        pcap_close(pc);
        free(flow_table);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(pc, &fp, filter_exp, 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(pc));
        pcap_close(pc);
        free(flow_table);
        return 1;
    }

    if (pcap_setfilter(pc, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(pc));
        pcap_freecode(&fp);
        pcap_close(pc);
        free(flow_table);
        return 1;
    }
    pcap_freecode(&fp);

    uint64_t last_report = now_ms();

    while (running) {
        int ret = pcap_dispatch(pc, 4096, process_packet, NULL);
        if (ret < 0) {
            fprintf(stderr, "pcap_dispatch: %s\n", pcap_geterr(pc));
            break;
        }

        uint64_t t = now_ms();
        if (t - last_report >= REPORT_INTERVAL * 1000ULL) {
            report_flows();
            last_report = t;
        }
    }

    report_flows();
    pcap_close(pc);
    free(flow_table);
    return 0;
}
