#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/time.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE (1u << 20)   // 1M buckets
#define FLOW_TIMEOUT 30        // seconds
#define REPORT_INTERVAL 5      // seconds
#define MAX_TOP_FLOWS 10

static volatile int running = 1;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint64_t x = 0;
    x ^= k->src_ip * 0x9e3779b185ebca87ULL;
    x ^= k->dst_ip * 0xc2b2ae3d27d4eb4fULL;
    x ^= ((uint64_t)k->src_port << 16) | k->dst_port;
    x ^= ((uint64_t)k->proto << 56);
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    return (uint32_t)x & (HASH_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, time_t now) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen = now;
            return;
        }
        e = e->next;
    }

    e = (flow_entry_t *)malloc(sizeof(flow_entry_t));
    if (!e) return;

    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->first_seen = now;
    e->last_seen = now;
    e->next = flow_table[idx];
    flow_table[idx] = e;
}

static void expire_flows(time_t now) {
    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((now - e->last_seen) > FLOW_TIMEOUT) {
                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

typedef struct {
    flow_entry_t *entries[MAX_TOP_FLOWS];
} top_flows_t;

static void top_insert(top_flows_t *top, flow_entry_t *e) {
    for (int i = 0; i < MAX_TOP_FLOWS; i++) {
        if (!top->entries[i] || e->bytes > top->entries[i]->bytes) {
            for (int j = MAX_TOP_FLOWS - 1; j > i; j--) {
                top->entries[j] = top->entries[j - 1];
            }
            top->entries[i] = e;
            return;
        }
    }
}

static void print_ip(uint32_t ip, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void report_flows(void) {
    top_flows_t top = {0};
    uint64_t total_flows = 0;
    uint64_t total_packets = 0;
    uint64_t total_bytes = 0;

    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        for (flow_entry_t *e = flow_table[i]; e; e = e->next) {
            total_flows++;
            total_packets += e->packets;
            total_bytes += e->bytes;
            top_insert(&top, e);
        }
    }

    printf("\n=== Flow Report ===\n");
    printf("Active flows: %lu  Packets: %lu  Bytes: %lu\n",
           total_flows, total_packets, total_bytes);
    printf("Top %d flows by bytes:\n", MAX_TOP_FLOWS);

    for (int i = 0; i < MAX_TOP_FLOWS; i++) {
        flow_entry_t *e = top.entries[i];
        if (!e) break;

        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        print_ip(e->key.src_ip, src, sizeof(src));
        print_ip(e->key.dst_ip, dst, sizeof(dst));

        printf("%2d) %s:%u -> %s:%u proto=%u pkts=%lu bytes=%lu age=%lds idle=%lds\n",
               i + 1,
               src, ntohs(e->key.src_port),
               dst, ntohs(e->key.dst_port),
               e->key.proto,
               e->packets, e->bytes,
               (long)(e->last_seen - e->first_seen),
               (long)(time(NULL) - e->last_seen));
    }
    fflush(stdout);
}

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

#pragma pack(push, 1)
struct eth_hdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct ipv4_hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t proto;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct tcp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct udp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static void process_packet(const struct pcap_pkthdr *h, const uint8_t *packet) {
    if (h->caplen < sizeof(struct eth_hdr)) return;

    const struct eth_hdr *eth = (const struct eth_hdr *)packet;
    if (ntohs(eth->ethertype) != 0x0800) return; // IPv4 only

    const uint8_t *ip_ptr = packet + sizeof(struct eth_hdr);
    uint32_t rem = h->caplen - sizeof(struct eth_hdr);
    if (rem < sizeof(struct ipv4_hdr)) return;

    const struct ipv4_hdr *ip = (const struct ipv4_hdr *)ip_ptr;
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20 || rem < ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->src_ip;
    key.dst_ip = ip->dst_ip;
    key.proto = ip->proto;

    const uint8_t *l4 = ip_ptr + ihl;
    rem -= ihl;

    if (ip->proto == IPPROTO_TCP) {
        if (rem < sizeof(struct tcp_hdr)) return;
        const struct tcp_hdr *tcp = (const struct tcp_hdr *)l4;
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
    } else if (ip->proto == IPPROTO_UDP) {
        if (rem < sizeof(struct udp_hdr)) return;
        const struct udp_hdr *udp = (const struct udp_hdr *)l4;
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
    } else {
        return;
    }

    update_flow(&key, h->len, time(NULL));
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [bpf-filter]\n", argv[0]);
        return 1;
    }

    const char *dev = argv[1];
    const char *filter_exp = (argc >= 3) ? argv[2] : "ip";

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_create(dev, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_create failed: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(handle, 128);
    pcap_set_promisc(handle, 1);
    pcap_set_timeout(handle, 100);
#ifdef PCAP_ERROR_ACTIVATED
    pcap_set_immediate_mode(handle, 1);
#endif

    int rc = pcap_activate(handle);
    if (rc < 0) {
        fprintf(stderr, "pcap_activate failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(handle, &fp, filter_exp, 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }
    pcap_freecode(&fp);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    time_t last_report = time(NULL);

    while (running) {
        struct pcap_pkthdr *header;
        const u_char *data;
        int ret = pcap_next_ex(handle, &header, &data);

        if (ret == 1) {
            process_packet(header, data);
        } else if (ret == 0) {
            // timeout
        } else if (ret == PCAP_ERROR_BREAK) {
            break;
        } else {
            fprintf(stderr, "pcap_next_ex error: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if ((now - last_report) >= REPORT_INTERVAL) {
            expire_flows(now);
            report_flows();
            last_report = now;
        }
    }

    report_flows();
    pcap_close(handle);

    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            flow_entry_t *n = e->next;
            free(e);
            e = n;
        }
    }

    return 0;
}
```

---

# Why this is “minimal working”
It does the core job:
- packet capture
- parsing
- flow aggregation
- timeout cleanup
- reporting

That makes it a valid prototype for a flow analyzer.

---

# Limitations
This is **not enough** for serious sustained gigabit monitoring in production. Main issues:

- `malloc` on new flows is expensive
- single-threaded
- `time(NULL)` per packet is slow
- linked-list hash buckets are cache-unfriendly
- libpcap may drop packets under load
- no VLAN parsing
- IPv4 only
- no TCP state tracking
- no flow export (NetFlow/IPFIX)
- no lock-free batching
- no RSS/multiqueue scaling

---

# Fast improvements
If you want to push this closer to “performance-critical”, do these first:

1. **Use `pcap_dispatch()` batching**
   - process many packets per syscall

2. **Replace `malloc` with a slab/pool allocator**
   - avoids allocator overhead

3. **Use monotonic coarse timestamps**
   - update current time once per batch, not per packet

4. **Use open addressing instead of linked lists**
   - better cache locality

5. **Shard by RSS queue / CPU**
   - one flow table per thread

6. **Pin threads to cores**
   - reduce scheduler movement

7. **Use PACKET_MMAP / AF_PACKET v3 or AF_XDP**
   - lower capture overhead

8. **Add BPF filters**
   - reduce packet volume early

