## Code: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE 262144
#define REPORT_INTERVAL 5
#define FLOW_TIMEOUT 30

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];
static volatile int running = 1;
static time_t last_report = 0;

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(flow_key_t); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h % HASH_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, time_t now) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen = now;
            return;
        }
        e = e->next;
    }

    e = malloc(sizeof(flow_entry_t));
    if (!e) return;

    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->last_seen = now;
    e->next = flow_table[idx];
    flow_table[idx] = e;
}

static void print_ip(uint32_t ip, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void report_flows(void) {
    printf("=== Flow Report ===\n");
    int shown = 0;

    for (size_t i = 0; i < HASH_SIZE && shown < 20; i++) {
        for (flow_entry_t *e = flow_table[i]; e && shown < 20; e = e->next) {
            char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
            print_ip(e->key.src_ip, src, sizeof(src));
            print_ip(e->key.dst_ip, dst, sizeof(dst));
            printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
                   src, ntohs(e->key.src_port),
                   dst, ntohs(e->key.dst_port),
                   e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes);
            shown++;
        }
    }
    printf("\n");
}

static void expire_flows(time_t now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((now - e->last_seen) > FLOW_TIMEOUT) {
                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void handle_packet(u_char *user,
                          const struct pcap_pkthdr *h,
                          const u_char *bytes) {
    (void)user;
    time_t now = time(NULL);

    if (h->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = bytes + sizeof(struct ether_header);
    if (h->caplen < sizeof(struct ether_header) + sizeof(struct ip)) return;

    const struct ip *ip_hdr = (const struct ip *)ip_ptr;
    if (ip_hdr->ip_v != 4) return;

    uint16_t ip_hdr_len = ip_hdr->ip_hl * 4;
    if (ip_hdr_len < sizeof(struct ip)) return;
    if (h->caplen < sizeof(struct ether_header) + ip_hdr_len) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip_hdr->ip_src.s_addr;
    key.dst_ip = ip_hdr->ip_dst.s_addr;
    key.proto = ip_hdr->ip_p;

    const u_char *l4_ptr = ip_ptr + ip_hdr_len;

    if (ip_hdr->ip_p == IPPROTO_TCP) {
        if (h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4_ptr;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (ip_hdr->ip_p == IPPROTO_UDP) {
        if (h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4_ptr;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    update_flow(&key, h->len, now);

    if (last_report == 0) last_report = now;
    if ((now - last_report) >= REPORT_INTERVAL) {
        expire_flows(now);
        report_flows();
        last_report = now;
    }
}

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(argv[1], 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Only Ethernet is supported\n");
        pcap_close(handle);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    printf("Capturing on %s...\n", argv[1]);

    while (running) {
        int rc = pcap_dispatch(handle, 1024, handle_packet, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch failed: %s\n", pcap_geterr(handle));
            break;
        }
    }

    report_flows();
    pcap_close(handle);
    return 0;
}
