```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <sys/time.h>

#define HASH_SIZE 65536
#define SNAPLEN 128
#define PROMISC 1
#define READ_TIMEOUT_MS 1000
#define FLOW_TIMEOUT_SEC 30

static volatile int running = 1;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h % HASH_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    struct in_addr s = { .s_addr = f->key.src_ip };
    struct in_addr d = { .s_addr = f->key.dst_ip };

    inet_ntop(AF_INET, &s, src, sizeof(src));
    inet_ntop(AF_INET, &d, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu first=%ld last=%ld\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           (unsigned long long)f->packets,
           (unsigned long long)f->bytes,
           (long)f->first_seen,
           (long)f->last_seen);
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, time_t ts) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *cur = flow_table[idx];

    while (cur) {
        if (flow_equal(&cur->key, key)) {
            cur->packets++;
            cur->bytes += pkt_len;
            cur->last_seen = ts;
            return;
        }
        cur = cur->next;
    }

    flow_entry_t *n = calloc(1, sizeof(*n));
    if (!n) {
        perror("calloc");
        return;
    }

    n->key = *key;
    n->packets = 1;
    n->bytes = pkt_len;
    n->first_seen = ts;
    n->last_seen = ts;
    n->next = flow_table[idx];
    flow_table[idx] = n;
}

static void expire_flows(time_t now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *f = *pp;
            if ((now - f->last_seen) >= FLOW_TIMEOUT_SEC) {
                print_flow(f);
                *pp = f->next;
                free(f);
            } else {
                pp = &f->next;
            }
        }
    }
}

static void flush_all_flows(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *cur = flow_table[i];
        while (cur) {
            flow_entry_t *next = cur->next;
            print_flow(cur);
            free(cur);
            cur = next;
        }
        flow_table[i] = NULL;
    }
}

static void packet_handler(u_char *user,
                           const struct pcap_pkthdr *h,
                           const u_char *bytes) {
    (void)user;

    if (h->caplen < 14) return; // Ethernet header

    const uint8_t *eth = bytes;
    uint16_t ethertype = ((uint16_t)eth[12] << 8) | eth[13];
    if (ethertype != 0x0800) return; // IPv4 only

    const struct ip *ip = (const struct ip *)(bytes + 14);
    if ((const u_char *)ip + sizeof(struct ip) > bytes + h->caplen) return;

    uint32_t ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < 20) return;
    if ((const u_char *)ip + ip_hdr_len > bytes + h->caplen) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto = ip->ip_p;

    const u_char *l4 = (const u_char *)ip + ip_hdr_len;

    if (ip->ip_p == IPPROTO_TCP) {
        if (l4 + sizeof(struct tcphdr) > bytes + h->caplen) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (ip->ip_p == IPPROTO_UDP) {
        if (l4 + sizeof(struct udphdr) > bytes + h->caplen) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    update_flow(&key, h->len, h->ts.tv_sec);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pcap = pcap_open_live(argv[1], SNAPLEN, PROMISC, READ_TIMEOUT_MS, errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_datalink(pcap) != DLT_EN10MB) {
        fprintf(stderr, "Only Ethernet is supported in this minimal version.\n");
        pcap_close(pcap);
        return 1;
    }

    struct bpf_program fp;
    const char *filter = "ip and (tcp or udp)";
    if (pcap_compile(pcap, &fp, filter, 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(pcap, &fp);
        pcap_freecode(&fp);
    }

    time_t last_expire = time(NULL);

    while (running) {
        int rc = pcap_dispatch(pcap, 1024, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch failed: %s\n", pcap_geterr(pcap));
            break;
        }

        time_t now = time(NULL);
        if (now != last_expire) {
            expire_flows(now);
            last_expire = now;
        }
    }

    flush_all_flows();
    pcap_close(pcap);
    return 0;
}
