## Minimal offline flow analyser in C++

```cpp
// safe_flow_analyzer.cpp
// Build: g++ -O2 -std=c++17 safe_flow_analyzer.cpp -lpcap -o safe_flow_analyzer
// Usage: ./safe_flow_analyzer sample.pcap

#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <cstring>

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    std::size_t operator()(const FlowKey& k) const {
        std::size_t h = 0;
        h ^= std::hash<uint32_t>{}(k.src_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint32_t>{}(k.dst_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.src_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.dst_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint8_t>{}(k.proto) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
};

static std::string ip_to_string(uint32_t ip) {
    struct in_addr addr;
    addr.s_addr = ip;
    char buf[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &addr, buf, sizeof(buf));
    return std::string(buf);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " file.pcap\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* pcap = pcap_open_offline(argv[1], errbuf);
    if (!pcap) {
        std::cerr << "pcap_open_offline failed: " << errbuf << "\n";
        return 1;
    }

    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows;

    struct pcap_pkthdr* header;
    const u_char* packet;
    int rc;

    while ((rc = pcap_next_ex(pcap, &header, &packet)) >= 0) {
        if (rc == 0) continue; // timeout, not expected offline

        if (header->caplen < 14) continue; // Ethernet header
        const uint16_t ethertype = (packet[12] << 8) | packet[13];
        if (ethertype != 0x0800) continue; // IPv4 only

        const u_char* ip_pkt = packet + 14;
        if (header->caplen < 14 + sizeof(struct ip)) continue;

        const struct ip* iph = reinterpret_cast<const struct ip*>(ip_pkt);
        const uint8_t ip_header_len = iph->ip_hl * 4;
        if (ip_header_len < 20) continue;
        if (header->caplen < 14 + ip_header_len) continue;

        FlowKey key{};
        key.src_ip = iph->ip_src.s_addr;
        key.dst_ip = iph->ip_dst.s_addr;
        key.proto = iph->ip_p;

        const u_char* l4 = ip_pkt + ip_header_len;

        if (key.proto == IPPROTO_TCP) {
            if (header->caplen < 14 + ip_header_len + sizeof(struct tcphdr)) continue;
            const struct tcphdr* tcp = reinterpret_cast<const struct tcphdr*>(l4);
            key.src_port = ntohs(tcp->th_sport);
            key.dst_port = ntohs(tcp->th_dport);
        } else if (key.proto == IPPROTO_UDP) {
            if (header->caplen < 14 + ip_header_len + sizeof(struct udphdr)) continue;
            const struct udphdr* udp = reinterpret_cast<const struct udphdr*>(l4);
            key.src_port = ntohs(udp->uh_sport);
            key.dst_port = ntohs(udp->uh_dport);
        } else {
            key.src_port = 0;
            key.dst_port = 0;
        }

        auto& st = flows[key];
        st.packets += 1;
        st.bytes += header->len;
    }

    pcap_close(pcap);

    std::vector<std::pair<FlowKey, FlowStats>> sorted(flows.begin(), flows.end());
    std::sort(sorted.begin(), sorted.end(),
              [](const auto& a, const auto& b) {
                  return a.second.bytes > b.second.bytes;
              });

    std::cout << "Top flows by bytes:\n";
    size_t limit = std::min<size_t>(20, sorted.size());
    for (size_t i = 0; i < limit; ++i) {
        const auto& [k, s] = sorted[i];
        std::cout << ip_to_string(k.src_ip) << ":" << k.src_port
                  << " -> " << ip_to_string(k.dst_ip) << ":" << k.dst_port
                  << " proto=" << static_cast<int>(k.proto)
                  << " packets=" << s.packets
                  << " bytes=" << s.bytes << "\n";
    }

    return 0;
}
```

