## Code: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define HASH_SIZE 262144
#define REPORT_INTERVAL 5
#define MAX_TOP_FLOWS 20

static volatile int running = 1;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h = (h ^ k->src_ip) * 16777619;
    h = (h ^ k->dst_ip) * 16777619;
    h = (h ^ k->src_port) * 16777619;
    h = (h ^ k->dst_port) * 16777619;
    h = (h ^ k->proto) * 16777619;
    return h & (HASH_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen = time(NULL);
            return;
        }
        e = e->next;
    }

    e = (flow_entry_t *)malloc(sizeof(flow_entry_t));
    if (!e) return;

    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->last_seen = time(NULL);
    e->next = flow_table[idx];
    flow_table[idx] = e;
}

static void ip_to_str(uint32_t ip, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void print_top_flows(void) {
    flow_entry_t *top[MAX_TOP_FLOWS] = {0};

    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            for (int j = 0; j < MAX_TOP_FLOWS; j++) {
                if (!top[j] || e->bytes > top[j]->bytes) {
                    for (int k = MAX_TOP_FLOWS - 1; k > j; k--) {
                        top[k] = top[k - 1];
                    }
                    top[j] = e;
                    break;
                }
            }
            e = e->next;
        }
    }

    printf("\n=== Top %d flows by bytes ===\n", MAX_TOP_FLOWS);
    for (int i = 0; i < MAX_TOP_FLOWS; i++) {
        if (!top[i]) break;
        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        ip_to_str(top[i]->key.src_ip, src, sizeof(src));
        ip_to_str(top[i]->key.dst_ip, dst, sizeof(dst));
        printf("%2d. %s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
               i + 1,
               src, ntohs(top[i]->key.src_port),
               dst, ntohs(top[i]->key.dst_port),
               top[i]->key.proto,
               (unsigned long long)top[i]->packets,
               (unsigned long long)top[i]->bytes);
    }
    fflush(stdout);
}

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

#pragma pack(push, 1)
struct eth_hdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct ipv4_hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t proto;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct tcp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
};

struct udp_hdr {
    uint16_t src_port;
    uint16_t dst_port;
};
#pragma pack(pop)

static void packet_handler(u_char *user,
                           const struct pcap_pkthdr *h,
                           const u_char *bytes) {
    (void)user;

    if (h->caplen < sizeof(struct eth_hdr)) return;

    const struct eth_hdr *eth = (const struct eth_hdr *)bytes;
    if (ntohs(eth->ethertype) != 0x0800) return; // IPv4 only

    const u_char *ip_ptr = bytes + sizeof(struct eth_hdr);
    if (h->caplen < sizeof(struct eth_hdr) + sizeof(struct ipv4_hdr)) return;

    const struct ipv4_hdr *ip = (const struct ipv4_hdr *)ip_ptr;
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return;
    if (h->caplen < sizeof(struct eth_hdr) + ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->src_ip;
    key.dst_ip = ip->dst_ip;
    key.proto = ip->proto;

    const u_char *l4_ptr = ip_ptr + ihl;
    size_t l4_len = h->caplen - (l4_ptr - bytes);

    if (ip->proto == 6) { // TCP
        if (l4_len < sizeof(struct tcp_hdr)) return;
        const struct tcp_hdr *tcp = (const struct tcp_hdr *)l4_ptr;
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
    } else if (ip->proto == 17) { // UDP
        if (l4_len < sizeof(struct udp_hdr)) return;
        const struct udp_hdr *udp = (const struct udp_hdr *)l4_ptr;
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    update_flow(&key, h->len);
}

int main(int argc, char *argv[]) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    char *dev;
    time_t last_report = time(NULL);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    dev = argv[1];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Only Ethernet is supported in this minimal version.\n");
        pcap_close(handle);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    printf("Capturing on %s...\n", dev);

    while (running) {
        int ret = pcap_dispatch(handle, 1024, packet_handler, NULL);
        if (ret < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if (now - last_report >= REPORT_INTERVAL) {
            print_top_flows();
            last_report = now;
        }
    }

    print_top_flows();
    pcap_close(handle);
    return 0;
}
