```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#define HASH_SIZE (1u << 20)   // 1M buckets
#define IDLE_TIMEOUT 30        // seconds
#define REPORT_INTERVAL 5      // seconds
#define MAX_PRINT 50

static volatile int running = 1;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ts_sec;
    uint64_t last_ts_sec;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *table[HASH_SIZE];
static uint64_t total_packets = 0;
static uint64_t total_bytes = 0;
static uint64_t last_report = 0;

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint64_t x = 0;
    x ^= k->src_ip * 0x9e3779b185ebca87ULL;
    x ^= k->dst_ip * 0xc2b2ae3d27d4eb4fULL;
    x ^= ((uint64_t)k->src_port << 16) | k->dst_port;
    x ^= k->proto * 0x165667b19e3779f9ULL;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    return (uint32_t)x & (HASH_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
    struct in_addr s = { .s_addr = f->key.src_ip };
    struct in_addr d = { .s_addr = f->key.dst_ip };
    inet_ntop(AF_INET, &s, src, sizeof(src));
    inet_ntop(AF_INET, &d, dst, sizeof(dst));
    printf("%s:%u -> %s:%u proto=%u pkts=%lu bytes=%lu age=%lus idle=%lus\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           f->packets, f->bytes,
           (unsigned long)(f->last_ts_sec - f->first_ts_sec),
           (unsigned long)(time(NULL) - f->last_ts_sec));
}

static void expire_flows(uint64_t now) {
    size_t printed = 0;
    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &table[i];
        while (*pp) {
            flow_entry_t *f = *pp;
            if (now - f->last_ts_sec > IDLE_TIMEOUT) {
                if (printed < MAX_PRINT) {
                    print_flow(f);
                    printed++;
                }
                *pp = f->next;
                free(f);
            } else {
                pp = &f->next;
            }
        }
    }
}

static void report_stats(uint64_t now) {
    static uint64_t prev_packets = 0, prev_bytes = 0, prev_ts = 0;
    if (prev_ts == 0) prev_ts = now;

    double dt = (double)(now - prev_ts);
    if (dt <= 0.0) dt = 1.0;

    uint64_t dpkts = total_packets - prev_packets;
    uint64_t dbytes = total_bytes - prev_bytes;

    double pps = dpkts / dt;
    double bps = (dbytes * 8.0) / dt / 1e6;

    size_t active = 0;
    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        for (flow_entry_t *f = table[i]; f; f = f->next) active++;
    }

    printf("[stats] active_flows=%zu total_pkts=%lu total_bytes=%lu rate=%.0f pps %.2f Mbps\n",
           active, total_packets, total_bytes, pps, bps);

    prev_packets = total_packets;
    prev_bytes = total_bytes;
    prev_ts = now;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, uint64_t ts_sec) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *f = table[idx];

    while (f) {
        if (flow_equal(&f->key, key)) {
            f->packets++;
            f->bytes += pkt_len;
            f->last_ts_sec = ts_sec;
            return;
        }
        f = f->next;
    }

    f = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!f) return;

    f->key = *key;
    f->packets = 1;
    f->bytes = pkt_len;
    f->first_ts_sec = ts_sec;
    f->last_ts_sec = ts_sec;
    f->next = table[idx];
    table[idx] = f;
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;
    total_packets++;
    total_bytes += h->len;

    if (h->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = bytes + sizeof(struct ether_header);
    size_t ip_avail = h->caplen - sizeof(struct ether_header);
    if (ip_avail < sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ip_ptr;
    if (iph->ip_v != 4) return;

    uint32_t ip_hlen = iph->ip_hl * 4;
    if (ip_hlen < sizeof(struct ip) || ip_avail < ip_hlen) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const u_char *l4 = ip_ptr + ip_hlen;
    size_t l4_avail = ip_avail - ip_hlen;

    if (iph->ip_p == IPPROTO_TCP) {
        if (l4_avail < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (l4_avail < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    update_flow(&key, h->len, h->ts.tv_sec);

    uint64_t now = h->ts.tv_sec;
    if (last_report == 0) last_report = now;
    if (now - last_report >= REPORT_INTERVAL) {
        report_stats(now);
        expire_flows(now);
        last_report = now;
    }
}

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <interface> [bpf_filter]\n", argv[0]);
        return 1;
    }

    const char *dev = argv[1];
    const char *filter_exp = (argc >= 3) ? argv[2] : "ip";

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pc = pcap_create(dev, errbuf);
    if (!pc) {
        fprintf(stderr, "pcap_create: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(pc, 128);
    pcap_set_promisc(pc, 1);
    pcap_set_timeout(pc, 100);
    pcap_set_buffer_size(pc, 64 * 1024 * 1024);
#ifdef PCAP_ERROR_ACTIVATED
#endif

    int rc = pcap_activate(pc);
    if (rc < 0) {
        fprintf(stderr, "pcap_activate: %s\n", pcap_geterr(pc));
        pcap_close(pc);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(pc, &fp, filter_exp, 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile: %s\n", pcap_geterr(pc));
        pcap_close(pc);
        return 1;
    }
    if (pcap_setfilter(pc, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter: %s\n", pcap_geterr(pc));
        pcap_freecode(&fp);
        pcap_close(pc);
        return 1;
    }
    pcap_freecode(&fp);

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    printf("listening on %s filter=\"%s\"\n", dev, filter_exp);

    while (running) {
        rc = pcap_dispatch(pc, 1024, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch: %s\n", pcap_geterr(pc));
            break;
        }
    }

    uint64_t now = time(NULL);
    report_stats(now);
    expire_flows(now + IDLE_TIMEOUT + 1);

    pcap_close(pc);
    return 0;
}
```

