#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f      // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f

#define SAMPLE_PERIOD_MS        10

#define TEMP_SENSOR_CHANNEL     0
#define LIGHT_SENSOR_CHANNEL    1

#define FILTER_SIZE             8

#define TEMP_HIGH_THRESHOLD_C   50.0f
#define TEMP_LOW_THRESHOLD_C    0.0f
#define LIGHT_LOW_THRESHOLD_PCT 10.0f

/* Example sensor scaling:
 * Temperature sensor assumed linear:
 *   0.5V = 0°C
 *   10mV/°C
 * So:
 *   Temp(°C) = (V - 0.5) / 0.01
 */

/*=========================================================
 * Data Types
 *=========================================================*/
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    float temperature_c;
    float min_temperature_c;
    float max_temperature_c;
    bool alarm_high;
    bool alarm_low;
} TemperatureSensorData;

typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    float light_percent;
    float min_light_percent;
    float max_light_percent;
    bool alarm_low;
} LightSensorData;

typedef struct
{
    float buffer[FILTER_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter;

/*=========================================================
 * Global Variables
 *=========================================================*/
static volatile bool g_sample_flag = false;

static TemperatureSensorData g_temp_data = {0};
static LightSensorData g_light_data = {0};

static MovingAverageFilter g_temp_filter = {0};
static MovingAverageFilter g_light_filter = {0};

/*=========================================================
 * Hardware Abstraction Prototypes
 * Replace these with MCU-specific implementations
 *=========================================================*/
void System_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void Timer_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void UART_Init(void);
void UART_SendString(const char *str);

/*=========================================================
 * Utility Functions
 *=========================================================*/
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static void filter_init(MovingAverageFilter *filter)
{
    uint8_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < FILTER_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float filter_update(MovingAverageFilter *filter, float new_sample)
{
    if (filter->count < FILTER_SIZE)
    {
        filter->buffer[filter->index] = new_sample;
        filter->sum += new_sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = new_sample;
        filter->sum += new_sample;
    }

    filter->index++;
    if (filter->index >= FILTER_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

static float voltage_to_temperature_c(float voltage)
{
    return (voltage - 0.5f) / 0.01f;
}

static float voltage_to_light_percent(float voltage)
{
    float pct = (voltage / ADC_REF_VOLTAGE) * 100.0f;

    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;

    return pct;
}

static void update_temperature_data(void)
{
    g_temp_data.raw = ADC_ReadChannel(TEMP_SENSOR_CHANNEL);
    g_temp_data.voltage = adc_to_voltage(g_temp_data.raw);
    g_temp_data.filtered_voltage = filter_update(&g_temp_filter, g_temp_data.voltage);
    g_temp_data.temperature_c = voltage_to_temperature_c(g_temp_data.filtered_voltage);

    static bool initialized = false;
    if (!initialized)
    {
        g_temp_data.min_temperature_c = g_temp_data.temperature_c;
        g_temp_data.max_temperature_c = g_temp_data.temperature_c;
        initialized = true;
    }

    if (g_temp_data.temperature_c < g_temp_data.min_temperature_c)
    {
        g_temp_data.min_temperature_c = g_temp_data.temperature_c;
    }

    if (g_temp_data.temperature_c > g_temp_data.max_temperature_c)
    {
        g_temp_data.max_temperature_c = g_temp_data.temperature_c;
    }

    g_temp_data.alarm_high = (g_temp_data.temperature_c > TEMP_HIGH_THRESHOLD_C);
    g_temp_data.alarm_low  = (g_temp_data.temperature_c < TEMP_LOW_THRESHOLD_C);
}

static void update_light_data(void)
{
    g_light_data.raw = ADC_ReadChannel(LIGHT_SENSOR_CHANNEL);
    g_light_data.voltage = adc_to_voltage(g_light_data.raw);
    g_light_data.filtered_voltage = filter_update(&g_light_filter, g_light_data.voltage);
    g_light_data.light_percent = voltage_to_light_percent(g_light_data.filtered_voltage);

    static bool initialized = false;
    if (!initialized)
    {
        g_light_data.min_light_percent = g_light_data.light_percent;
        g_light_data.max_light_percent = g_light_data.light_percent;
        initialized = true;
    }

    if (g_light_data.light_percent < g_light_data.min_light_percent)
    {
        g_light_data.min_light_percent = g_light_data.light_percent;
    }

    if (g_light_data.light_percent > g_light_data.max_light_percent)
    {
        g_light_data.max_light_percent = g_light_data.light_percent;
    }

    g_light_data.alarm_low = (g_light_data.light_percent < LIGHT_LOW_THRESHOLD_PCT);
}

/*=========================================================
 * Optional reporting
 *=========================================================*/
static void report_sensor_data(void)
{
    /* In real firmware, use snprintf carefully depending on libc size.
       This is shown for clarity. */
    char msg[256];

    /* Minimal embedded-safe formatting may be preferred in production. */
    extern int snprintf(char *str, unsigned long size, const char *format, ...);

    snprintf(msg, sizeof(msg),
             "TEMP: raw=%u V=%.3f Vf=%.3f T=%.2fC min=%.2f max=%.2f AH=%d AL=%d\r\n"
             "LIGHT: raw=%u V=%.3f Vf=%.3f L=%.2f%% min=%.2f max=%.2f AL=%d\r\n",
             g_temp_data.raw,
