## Example: Sensor Firmware in C

```c
#include <stdint.h>
#include <stdbool.h>

/*
 * Generic firmware example:
 * - Reads analog sensor via ADC
 * - Applies moving average filter
 * - Converts ADC counts to voltage
 * - Detects over-threshold condition
 *
 * Replace hardware-specific stubs with your MCU SDK/HAL functions.
 */

#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_BUFFER_SIZE      16
#define SENSOR_THRESHOLD_VOLTS  2.0f

typedef struct {
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    bool threshold_exceeded;
} SensorData;

static SensorData g_sensor_data;

/* Moving average filter state */
static float sample_buffer[SENSOR_BUFFER_SIZE];
static uint8_t sample_index = 0;
static bool buffer_full = false;

/* --- Hardware abstraction stubs --- */
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void Delay_ms(uint32_t ms);
void UART_SendString(const char *str);

/* --- Utility functions --- */
static float adc_to_voltage(uint16_t adc_value) {
    return ((float)adc_value / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float moving_average_filter(float new_sample) {
    sample_buffer[sample_index] = new_sample;
    sample_index++;

    if (sample_index >= SENSOR_BUFFER_SIZE) {
        sample_index = 0;
        buffer_full = true;
    }

    uint8_t count = buffer_full ? SENSOR_BUFFER_SIZE : sample_index;
    float sum = 0.0f;

    for (uint8_t i = 0; i < count; i++) {
        sum += sample_buffer[i];
    }

    return (count > 0) ? (sum / count) : new_sample;
}

static void process_sensor_data(uint16_t raw_adc) {
    g_sensor_data.raw = raw_adc;
    g_sensor_data.voltage = adc_to_voltage(raw_adc);
    g_sensor_data.filtered_voltage = moving_average_filter(g_sensor_data.voltage);
    g_sensor_data.threshold_exceeded =
        (g_sensor_data.filtered_voltage > SENSOR_THRESHOLD_VOLTS);
}

/* Optional: simple integer-to-string helpers if stdio is unavailable */
static void float_to_string(float value, char *buffer, int precision) {
    int int_part = (int)value;
    float frac = value - int_part;
    if (frac < 0) frac = -frac;

    char temp[16];
    int i = 0;

    if (int_part == 0) {
        temp[i++] = '0';
    } else {
        int n = int_part;
        if (n < 0) {
            *buffer++ = '-';
            n = -n;
        }

        char rev[16];
        int j = 0;
        while (n > 0) {
            rev[j++] = '0' + (n % 10);
            n /= 10;
        }
        while (j > 0) {
            temp[i++] = rev[--j];
        }
    }

    for (int k = 0; k < i; k++) {
        *buffer++ = temp[k];
    }

    *buffer++ = '.';

    for (int p = 0; p < precision; p++) {
        frac *= 10.0f;
        int digit = (int)frac;
        *buffer++ = '0' + digit;
        frac -= digit;
    }

    *buffer = '\0';
}

static void report_sensor_data(void) {
    char msg[128];
    char raw_str[16];
    char volt_str[16];
    char filt_str[16];

    /* crude integer conversion for raw */
    int raw = g_sensor_data.raw;
    int idx = 0;
    char rev[16];
    if (raw == 0) {
        raw_str[idx++] = '0';
    } else {
        int j = 0;
        while (raw > 0) {
            rev[j++] = '0' + (raw % 10);
            raw /= 10;
        }
        while (j > 0) {
            raw_str[idx++] = rev[--j];
        }
    }
    raw_str[idx] = '\0';

    float_to_string(g_sensor_data.voltage, volt_str, 3);
    float_to_string(g_sensor_data.filtered_voltage, filt_str, 3);

    /* Build message manually */
    char *p = msg;
    const char *prefix1 = "RAW=";
    const char *prefix2 = " V=";
    const char *prefix3 = " FV=";
    const char *prefix4 = " TH=";
    const char *th = g_sensor_data.threshold_exceeded ? "1" : "0";
    const char *newline = "\r\n";

    while (*prefix1) *p++ = *prefix1++;
    const char *s = raw_str;
    while (*s) *p++ = *s++;

    while (*prefix2) *p++ = *prefix2++;
    s = volt_str;
    while (*s) *p++ = *s++;

    while (*prefix3) *p++ = *prefix3++;
    s = filt_str;
    while (*s) *p++ = *s++;

    while (*prefix4) *p++ = *prefix4++;
    s = th;
    while (*s) *p++ = *s++;

    while (*newline) *p++ = *newline++;
    *p = '\0';

    UART_SendString(msg);
}

int main(void) {
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
