    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float sensor_value;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

/* =========================
   Global state
   ========================= */
static SensorData_t g_sensorData;
static MovingAverageFilter_t g_filter;

/* =========================
   Filter functions
   ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    memset(filter, 0, sizeof(MovingAverageFilter_t));
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;

    return filter->sum / (float)filter->count;
}

/* =========================
   Conversion and processing
   ========================= */
static float ADC_ToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Voltage_ToSensorUnits(float voltage)
{
    return (voltage * SENSOR_SCALE) + SENSOR_OFFSET;
}

static void ProcessSensorData(void)
{
    g_sensorData.raw_adc = ADC_ReadRaw();

    g_sensorData.voltage = ADC_ToVoltage(g_sensorData.raw_adc);

    g_sensorData.filtered_voltage = Filter_Update(&g_filter, g_sensorData.voltage);

    g_sensorData.sensor_value = Voltage_ToSensorUnits(g_sensorData.filtered_voltage);

    g_sensorData.alarm_high = (g_sensorData.sensor_value > HIGH_THRESHOLD);
    g_sensorData.alarm_low  = (g_sensorData.sensor_value < LOW_THRESHOLD);

    if (g_sensorData.alarm_high || g_sensorData.alarm_low)
    {
