#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* =========================
   Configuration
   ========================= */
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLES          16
#define TEMP_ALERT_THRESHOLD_C  50.0f

/* Example sensor:
   LM35-like behavior: 10 mV / °C
   Temperature (°C) = voltage * 100
*/
#define SENSOR_VOLTS_TO_TEMP(v) ((v) * 100.0f)

/* =========================
   Mock hardware layer
   Replace these with MCU HAL/driver calls
   ========================= */
static void SystemClock_Config(void);
static void GPIO_Init(void);
static void ADC_Init(void);
static void UART_Init(void);
static uint16_t ADC_ReadRaw(void);
static void DelayMs(uint32_t ms);
static void UART_SendString(const char *s);
static void LED_Set(bool on);

/* =========================
   Sensor processing types
   ========================= */
typedef struct
{
    uint16_t buffer[SENSOR_SAMPLES];
    uint32_t sum;
    uint8_t index;
    bool filled;
} MovingAverageFilter_t;

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float temperature_c;
    float filtered_temperature_c;
    bool alert;
} SensorData_t;

/* =========================
   Global objects
   ========================= */
static MovingAverageFilter_t tempFilter;
static SensorData_t sensorData;

/* =========================
   Utility functions
   ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    memset(filter, 0, sizeof(MovingAverageFilter_t));
}

static uint16_t Filter_Update(MovingAverageFilter_t *filter, uint16_t newSample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = newSample;
    filter->sum += newSample;

    filter->index++;
    if (filter->index >= SENSOR_SAMPLES)
    {
        filter->index = 0;
        filter->filled = true;
    }

    uint8_t divisor = filter->filled ? SENSOR_SAMPLES : filter->index;
    if (divisor == 0)
    {
        return newSample;
    }

    return (uint16_t)(filter->sum / divisor);
}

static float ADC_ToVoltage(uint16_t adcCounts)
{
    return ((float)adcCounts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Voltage_ToTemperature(float voltage)
{
    return SENSOR_VOLTS_TO_TEMP(voltage);
}

static void ProcessSensorData(SensorData_t *data)
{
    data->voltage = ADC_ToVoltage(data->raw_adc);
    data->temperature_c = Voltage_ToTemperature(data->voltage);

    uint16_t filteredAdc = Filter_Update(&tempFilter, data->raw_adc);
    float filteredVoltage = ADC_ToVoltage(filteredAdc);
    data->filtered_temperature_c = Voltage_ToTemperature(filteredVoltage);

    data->alert = (data->filtered_temperature_c >= TEMP_ALERT_THRESHOLD_C);
}

static void FormatSensorMessage(const SensorData_t *data, char *out, uint32_t maxLen)
{
    /* Minimal snprintf alternative for portability if stdio is unavailable */
    /* If your toolchain supports snprintf, use that instead. */
    int tempInt = (int)data->filtered_temperature_c;
    int tempFrac = (int)((data->filtered_temperature_c - tempInt) * 100.0f);
    if (tempFrac < 0) tempFrac = -tempFrac;

    const char *alertText = data->alert ? "ALERT" : "OK";

    /* Very simple formatting */
    /* Replace with snprintf if available */
    char msg[128];
    int n = 0;

    n += strcpy(&msg[n], "Raw ADC: ");
    {
        char num[16];
        int len = 0;
        uint16_t val = data->raw_adc;
        if (val == 0)
        {
            num[len++] = '0';
        }
        else
        {
            char rev[16];
            int r = 0;
            while (val > 0)
            {
                rev[r++] = '0' + (val % 10);
                val /= 10;
            }
            while (r > 0)
            {
                num[len++] = rev[--r];
            }
        }
        num[len] = '\0';
        n += strcpy(&msg[n], num);
    }

    n += strcpy(&msg[n], ", Temp: ");
    {
        char num[16];
        int len = 0;
        int val = tempInt;
        if (val < 0)
        {
            num[len++] = '-';
            val = -val;
        }

        if (val == 0)
        {
            num[len++] = '0';
        }
        else
        {
            char rev[16];
            int r = 0;
            while (val > 0)
            {
                rev[r++] = '0' + (val % 10);
                val /= 10;
            }
            while (r > 0)
            {
                num[len++] = rev[--r];
            }
        }

        num[len++] = '.';
        num[len++] = '0' + ((tempFrac / 10) % 10);
        num[len++] = '0' + (tempFrac % 10);
        num[len++] = 'C';
        num[len] = '\0';

        n += strcpy(&msg[n], num);
    }

    n += strcpy(&msg[n], ", Status: ");
    n += strcpy(&msg[n], alertText);
    n += strcpy(&msg[n], "\r\n");

    strncpy(out, msg, maxLen - 1);
    out[maxLen - 1] = '\0';
}

/* =========================
