# Better architecture for real firmware

For production firmware, I’d recommend splitting it into modules:

## sensor.h
```c
#ifndef SENSOR_H
#define SENSOR_H

#include <stdint.h>
#include <stdbool.h>

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float value;
    float filtered_value;
    bool alert;
} SensorData_t;

void Sensor_Init(void);
void Sensor_Update(SensorData_t *data);

#endif
```

## sensor.c
```c
#include "sensor.h"

#define ADC_MAX_COUNTS  4095.0f
#define ADC_REF_VOLTAGE 3.3f
#define FILTER_SIZE     16
#define ALERT_THRESHOLD 50.0f

static uint16_t buffer[FILTER_SIZE];
static uint32_t sum = 0;
static uint8_t index = 0;
static bool filled = false;

static uint16_t ADC_ReadRaw(void);

static uint16_t Filter_Update(uint16_t sample)
{
    sum -= buffer[index];
    buffer[index] = sample;
    sum += sample;

    index++;
    if (index >= FILTER_SIZE)
    {
        index = 0;
        filled = true;
    }

    uint8_t divisor = filled ? FILTER_SIZE : index;
    if (divisor == 0) return sample;

    return (uint16_t)(sum / divisor);
}

void Sensor_Init(void)
{
    for (int i = 0; i < FILTER_SIZE; i++)
    {
        buffer[i] = 0;
    }
    sum = 0;
    index = 0;
    filled = false;
}

void Sensor_Update(SensorData_t *data)
{
    data->raw_adc = ADC_ReadRaw();
    data->voltage = ((float)data->raw_adc / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
    data->value = data->voltage * 100.0f;

    uint16_t filtered = Filter_Update(data->raw_adc);
    data->filtered_value = (((float)filtered / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE) * 100.0f;

    data->alert = (data->filtered_value > ALERT_THRESHOLD);
}
```

