}

/*
 * Example pressure conversion:
 * 0.5V = 0 kPa
 * 2.5V = 300 kPa
 */
static float VoltageToPressureKPa(float voltage)
{
    if (voltage <= 0.5f)
    {
        return 0.0f;
    }

    return ((voltage - 0.5f) * 300.0f) / (2.0f);
}

static bool CheckTemperatureFault(float tempC)
{
    return (tempC < TEMP_MIN_C || tempC > TEMP_MAX_C);
}

static bool CheckPressureFault(float pressureKPa)
{
    return (pressureKPa < PRESS_MIN_KPA || pressureKPa > PRESS_MAX_KPA);
}

