static void ProcessTemperatureSensor(void)
{
    g_temperature.raw = ADC_ReadChannel(TEMP_SENSOR_CHANNEL);
    g_temperature.voltage = ADC_CountsToVoltage(g_temperature.raw);
    g_temperature.filtered_voltage = Filter_Update(&g_tempFilter, g_temperature.voltage);
    g_temperature.value = VoltageToTemperatureC(g_temperature.filtered_voltage);
