    return g_msTicks;
}

int main(void)
{
    uint32_t lastSampleTime = 0;
    uint32_t lastReportTime = 0;

    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    Timer_Init();
    UART_Init();

    Filter_Init(&g_tempFilter);
    Filter_Init(&g_pressFilter);

    while (1)
    {
        uint32_t now = GetTickMs();

        if ((now - lastSampleTime) >= 100)
        {
            lastSampleTime = now;
            ProcessAllSensors();
        }

        if ((now - lastReportTime) >= 500)
        {
            lastReportTime = now;
            ReportSensorData();
        }

        /* Optional low-power wait or background tasks here */
    }
}
