#include <stdint.h>
#include <stdbool.h>

/* =========================
   Configuration
   ========================= */
#define ADC_MAX_VALUE           4095.0f      // 12-bit ADC
#define VREF                    3.3f
#define SENSOR_SAMPLE_COUNT     16
#define SENSOR_THRESHOLD_VOLTS  2.0f
#define MOVING_AVG_SIZE         8

/* =========================
   Mock hardware registers / prototypes
   Replace with MCU-specific HAL/driver code
   ========================= */
