/* =========================
   Sensor data structure
   ========================= */
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered;
    bool thresholdExceeded;
} SensorData_t;

/* =========================
   Moving average filter
   ========================= */
typedef struct
{
    float buffer[MOVING_AVG_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

static void Filter_Init(MovingAverageFilter_t *filter)
{
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (uint8_t i = 0; i < MOVING_AVG_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float newValue)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = newValue;
    filter->sum += newValue;

    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;

    if (filter->count < MOVING_AVG_SIZE)
    {
        filter->count++;
    }

    return filter->sum / filter->count;
}

/* =========================
   Sensor functions
   ========================= */
static uint16_t Sensor_ReadRaw(uint8_t adcChannel)
{
    return ADC_ReadChannel(adcChannel);
}

static float Sensor_ConvertToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_VALUE) * VREF;
}

static SensorData_t Sensor_Process(uint8_t adcChannel, MovingAverageFilter_t *filter)
{
    SensorData_t data;

    data.raw = Sensor_ReadRaw(adcChannel);
    data.voltage = Sensor_ConvertToVoltage(data.raw);
    data.filtered = Filter_Update(filter, data.voltage);
    data.thresholdExceeded = (data.filtered > SENSOR_THRESHOLD_VOLTS);

    return data;
}

/* =========================
   Utility: simple float-to-string formatter
   Avoids printf for smaller embedded targets
   ========================= */
static void FloatToString(float value, char *buffer, uint8_t decimals)
{
    int32_t intPart = (int32_t)value;
    int32_t fracPart = (int32_t)((value - intPart) * 1000);

    if (fracPart < 0)
        fracPart = -fracPart;

    if (decimals == 2)
    {
        fracPart /= 10;
    }

    char temp[20];
    int i = 0, j = 0;

    if (intPart == 0)
    {
        temp[i++] = '0';
    }
    else
    {
        int32_t n = intPart;
        char rev[10];
        int k = 0;

        if (n < 0)
        {
            buffer[j++] = '-';
            n = -n;
        }

        while (n > 0)
        {
            rev[k++] = (n % 10) + '0';
            n /= 10;
        }

        while (k > 0)
        {
            temp[i++] = rev[--k];
        }
    }

    for (int k = 0; k < i; k++)
    {
        buffer[j++] = temp[k];
    }

    buffer[j++] = '.';

    if (decimals == 2)
    {
        buffer[j++] = (fracPart / 10) + '0';
        buffer[j++] = (fracPart % 10) + '0';
    }
    else if (decimals == 3)
    {
        buffer[j++] = (fracPart / 100) + '0';
        buffer[j++] = ((fracPart / 10) % 10) + '0';
        buffer[j++] = (fracPart % 10) + '0';
    }

    buffer[j] = '\0';
}

/* =========================
   Main application
   ========================= */
