        SensorData_t sensor = Sensor_Process(0, &sensorFilter);

        FloatToString(sensor.voltage, voltageStr, 2);
        FloatToString(sensor.filtered, filteredStr, 2);

        // Build UART message manually
        int idx = 0;
        const char *prefix1 = "Raw: ";
        const char *prefix2 = ", V: ";
        const char *prefix3 = ", Filt: ";
        const char *prefix4 = ", Alert: ";
        const char *alert = sensor.thresholdExceeded ? "YES\r\n" : "NO\r\n";

        for (int i = 0; prefix1[i] != '\0'; i++) msg[idx++] = prefix1[i];

        // raw integer conversion
        {
            char rawStr[10];
            int rawIdx = 0;
            uint16_t raw = sensor.raw;
            char rev[10];
            int revIdx = 0;

            if (raw == 0)
            {
                rawStr[rawIdx++] = '0';
            }
            else
            {
                while (raw > 0)
                {
                    rev[revIdx++] = (raw % 10) + '0';
                    raw /= 10;
                }
                while (revIdx > 0)
                {
                    rawStr[rawIdx++] = rev[--revIdx];
                }
            }
            rawStr[rawIdx] = '\0';

            for (int i = 0; rawStr[i] != '\0'; i++) msg[idx++] = rawStr[i];
        }

        for (int i = 0; prefix2[i] != '\0'; i++) msg[idx++] = prefix2[i];
        for (int i = 0; voltageStr[i] != '\0'; i++) msg[idx++] = voltageStr[i];
        for (int i = 0; prefix3[i] != '\0'; i++) msg[idx++] = prefix3[i];
        for (int i = 0; filteredStr[i] != '\0'; i++) msg[idx++] = filteredStr[i];
        for (int i = 0; prefix4[i] != '\0'; i++) msg[idx++] = prefix4[i];
        for (int i = 0; alert[i] != '\0'; i++) msg[idx++] = alert[i];

