static moving_avg_filter_t g_temp_filter;

/*=========================================================
 * Filter functions
 *=========================================================*/
static void moving_avg_init(moving_avg_filter_t *filter)
{
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (uint8_t i = 0; i < MOVING_AVG_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float moving_avg_update(moving_avg_filter_t *filter, float new_value)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = new_value;
    filter->sum += new_value;

    filter->index++;
    if (filter->index >= MOVING_AVG_SIZE)
    {
        filter->index = 0;
    }

    if (filter->count < MOVING_AVG_SIZE)
    {
        filter->count++;
    }

    return filter->sum / filter->count;
}

