# Example: Sensor Firmware in C

```c
#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS      4095.0f     // 12-bit ADC
#define VREF                3.3f
#define SENSOR_OFFSET_V     0.5f        // Example sensor offset
#define SENSOR_SCALE_V_PER_UNIT 0.01f   // Example: 10mV per unit

#define FILTER_WINDOW_SIZE  8
#define HIGH_THRESHOLD      80.0f
#define LOW_THRESHOLD       10.0f

/*=========================================================
 * Mock hardware interface prototypes
 * Replace these with MCU-specific implementations
 *=========================================================*/
void System_Init(void);
void ADC_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void UART_Init(void);
void UART_SendString(const char *str);
void GPIO_Init(void);
void LED_Set(bool on);
void Delay_ms(uint32_t ms);

/*=========================================================
 * Sensor data structure
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float physical_value;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

/*=========================================================
 * Global variables
 *=========================================================*/
static SensorData_t sensor;
static float filter_buffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t filter_index = 0;
static bool filter_full = false;

/*=========================================================
 * Utility: moving average filter
 *=========================================================*/
static float MovingAverageFilter(float new_sample)
{
    filter_buffer[filter_index] = new_sample;
    filter_index++;

    if (filter_index >= FILTER_WINDOW_SIZE)
    {
        filter_index = 0;
        filter_full = true;
    }

    uint8_t count = filter_full ? FILTER_WINDOW_SIZE : filter_index;
    float sum = 0.0f;

    for (uint8_t i = 0; i < count; i++)
    {
        sum += filter_buffer[i];
    }

    if (count == 0)
        return new_sample;

    return sum / count;
}

/*=========================================================
 * Convert ADC counts to voltage
 *=========================================================*/
static float ADC_ToVoltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_COUNTS) * VREF;
}

/*=========================================================
 * Convert voltage to physical sensor units
 * Example formula:
 *   physical_value = (voltage - offset) / scale
 *=========================================================*/
static float Voltage_ToPhysical(float voltage)
{
    return (voltage - SENSOR_OFFSET_V) / SENSOR_SCALE_V_PER_UNIT;
}

/*=========================================================
 * Process sensor sample
 *=========================================================*/
static void Sensor_Process(uint8_t adc_channel)
{
    sensor.raw_adc = ADC_ReadChannel(adc_channel);
    sensor.voltage = ADC_ToVoltage(sensor.raw_adc);
    sensor.filtered_voltage = MovingAverageFilter(sensor.voltage);
    sensor.physical_value = Voltage_ToPhysical(sensor.filtered_voltage);

    sensor.alarm_high = (sensor.physical_value > HIGH_THRESHOLD);
