   Sensor processing
   ========================= */
static void Sensor_Process(SensorData_t *data)
{
    data->raw_adc = ADC_ReadRaw();
    data->voltage = ADC_ToVoltage(data->raw_adc);
    data->filtered_voltage = Filter_Update(&g_filter, data->voltage);
    data->value = Sensor_ConvertVoltageToUnits(data->filtered_voltage);
}

static void Check_Alarms(SensorData_t *data)
{
    data->alarm_high = (data->value > SENSOR_HIGH_THRESHOLD);
    data->alarm_low  = (data->value < SENSOR_LOW_THRESHOLD);
}

static float ADC_ToVoltage(uint16_t adc_raw)
{
    return ((float)adc_raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Sensor_ConvertVoltageToUnits(float voltage)
{
    if (voltage <= SENSOR_VOLTAGE_MIN)
        return SENSOR_OUTPUT_MIN;

    if (voltage >= SENSOR_VOLTAGE_MAX)
        return SENSOR_OUTPUT_MAX;

    float normalized = (voltage - SENSOR_VOLTAGE_MIN) /
                       (SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN);

    return SENSOR_OUTPUT_MIN +
           normalized * (SENSOR_OUTPUT_MAX - SENSOR_OUTPUT_MIN);
}

/* =========================
   Moving average filter
   ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    memset(filter->buffer, 0, sizeof(filter->buffer));
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = sample;
    filter->sum += sample;

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;

    if (filter->count < FILTER_WINDOW_SIZE)
        filter->count++;

    return filter->sum / (float)filter->count;
}

