}

static void Sensor_ReadAndProcess(void)
{
    uint16_t raw = HAL_ADC_Read(0);

    g_sensorData.raw = raw;
    g_sensorData.voltage = ADC_ToVoltage(raw);
    g_sensorData.temperature_c = Voltage_ToTemperatureC(g_sensorData.voltage);
    g_sensorData.filtered_temperature_c =
        Filter_Update(&g_tempFilter, g_sensorData.temperature_c);

    g_sensorData.alert = (g_sensorData.filtered_temperature_c >= TEMP_ALERT_C);

    HAL_LED_Set(g_sensorData.alert);
}

static void Sensor_Report(void)
{
    char msg[128];

    snprintf(msg, sizeof(msg),
             "RAW=%u, V=%.3f V, T=%.2f C, TF=%.2f C, ALERT=%s\r\n",
             g_sensorData.raw,
             g_sensorData.voltage,
             g_sensorData.temperature_c,
             g_sensorData.filtered_temperature_c,
             g_sensorData.alert ? "ON" : "OFF");

    HAL_UART_SendString(msg);
}

/*========================
  Application
========================*/
static void App_Init(void)
{
    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_UART_Init(115200);

    Filter_Init(&g_tempFilter);

    HAL_UART_SendString("Sensor firmware started\r\n");
}

static void App_Run(void)
{
    uint32_t lastSampleTime = 0;

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - lastSampleTime) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            lastSampleTime = now;

            Sensor_ReadAndProcess();
            Sensor_Report();
        }

        /* Optional low-power wait or background tasks */
        HAL_DelayMs(1);
    }
}

int main(void)
{
    App_Init();
    App_Run();

    return 0;
}
