#include <stdbool.h>

/* =========================
   Configuration
   ========================= */
#define ADC_MAX_VALUE           4095U
#define ADC_REF_MV              3300U
#define SENSOR_SAMPLE_COUNT     16U
#define SENSOR_THRESHOLD_MV     2000U

/* =========================
   Global sensor state
   ========================= */
static uint16_t sample_buffer[SENSOR_SAMPLE_COUNT];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static bool buffer_filled = false;

static uint16_t raw_adc_value = 0;
static uint16_t sensor_mv = 0;
static uint16_t filtered_mv = 0;
static bool sensor_alert = false;

/* =========================
   Hardware abstraction stubs
   Replace these with MCU-specific implementations
   ========================= */
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
void Timer_Init(void);

uint16_t ADC_ReadChannel(uint8_t channel);
void UART_SendString(const char *str);
void Delay_ms(uint32_t ms);

/* =========================
   Utility functions
   ========================= */
static uint16_t adc_to_millivolts(uint16_t adc_value)
{
    return (uint16_t)(((uint32_t)adc_value * ADC_REF_MV) / ADC_MAX_VALUE);
}

static uint16_t moving_average_filter(uint16_t new_sample)
{
    if (buffer_filled)
    {
        sample_sum -= sample_buffer[sample_index];
    }

    sample_buffer[sample_index] = new_sample;
    sample_sum += new_sample;

    sample_index++;
    if (sample_index >= SENSOR_SAMPLE_COUNT)
    {
        sample_index = 0;
        buffer_filled = true;
    }

    if (buffer_filled)
    {
        return (uint16_t)(sample_sum / SENSOR_SAMPLE_COUNT);
    }
    else
    {
        return (uint16_t)(sample_sum / sample_index);
    }
}

static void process_sensor_data(void)
{
    raw_adc_value = ADC_ReadChannel(0);
    sensor_mv = adc_to_millivolts(raw_adc_value);
    filtered_mv = moving_average_filter(sensor_mv);

    sensor_alert = (filtered_mv > SENSOR_THRESHOLD_MV);
}

static void report_sensor_data(void)
{
    char msg[64];

    /* Minimal integer-to-string formatting without stdio if needed.
       Replace with snprintf if available in your environment. */
    int len = 0;

    len += simple_strcpy(&msg[len], "RAW=");
    len += u16_to_str(raw_adc_value, &msg[len]);

    len += simple_strcpy(&msg[len], " ADC, MV=");
    len += u16_to_str(sensor_mv, &msg[len]);

    len += simple_strcpy(&msg[len], ", FILT=");
    len += u16_to_str(filtered_mv, &msg[len]);

    len += simple_strcpy(&msg[len], ", ALERT=");
    len += simple_strcpy(&msg[len], sensor_alert ? "1\r\n" : "0\r\n");

    msg[len] = '\0';
    UART_SendString(msg);
}

/* =========================
   Lightweight string helpers
   ========================= */
int simple_strcpy(char *dst, const char *src)
{
    int count = 0;
    while (*src)
    {
        *dst++ = *src++;
        count++;
    }
    return count;
}

int u16_to_str(uint16_t value, char *buf)
{
    char temp[6];
    int i = 0;
    int j = 0;

    if (value == 0)
    {
        buf[0] = '0';
        return 1;
    }

    while (value > 0)
    {
        temp[i++] = (char)('0' + (value % 10));
        value /= 10;
    }

    while (i > 0)
    {
        buf[j++] = temp[--i];
    }

    return j;
}

/* =========================
   Main
   ========================= */
int main(void)
{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init();
    Timer_Init();

    for (uint8_t i = 0; i < SENSOR_SAMPLE_COUNT; i++)
    {
        sample_buffer[i] = 0;
    }

    while (1)
    {
        process_sensor_data();
        report_sensor_data();

        if (sensor_alert)
        {
            /* Example: set alarm GPIO or LED here */
        }
        else
        {
            /* Example: clear alarm GPIO or LED here */
        }

        Delay_ms(100);
    }

    return 0;
}
