```c
/*
 * initial_firmware.c
 *
 * Generic microcontroller firmware for reading and processing sensor data.
 *
 * Features:
 * - Periodic sensor sampling
 * - Simple moving average filter
 * - Threshold-based status flags
 * - Basic fault handling
 *
 * Replace hardware-specific functions with MCU/HAL-specific implementations.
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define SENSOR_SAMPLE_PERIOD_MS     100U
#define SENSOR_BUFFER_SIZE          8U
#define SENSOR_RAW_MIN              0U
#define SENSOR_RAW_MAX              4095U   /* Example: 12-bit ADC */
#define SENSOR_HIGH_THRESHOLD       3000U
#define SENSOR_LOW_THRESHOLD        500U

/*=========================================================
 * Type Definitions
 *=========================================================*/
typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_LOW,
    SENSOR_STATUS_HIGH,
    SENSOR_STATUS_FAULT
} sensor_status_t;

typedef struct
{
    uint16_t raw;
    uint16_t filtered;
    sensor_status_t status;
    bool new_data;
} sensor_data_t;

/*=========================================================
 * Static Module Data
 *=========================================================*/
static sensor_data_t g_sensor_data;

static uint16_t g_sample_buffer[SENSOR_BUFFER_SIZE];
static uint32_t g_sample_sum = 0;
static uint8_t g_sample_index = 0;
static bool g_buffer_initialized = false;

static volatile uint32_t g_system_tick_ms = 0;

/*=========================================================
 * Hardware Abstraction Layer Prototypes
 * Replace these with actual MCU-specific implementations.
 *=========================================================*/
static void HAL_SystemInit(void);
static void HAL_GPIO_Init(void);
static void HAL_ADC_Init(void);
static void HAL_Timer_Init(void);
static uint16_t HAL_ADC_ReadChannel(uint8_t channel);
static void HAL_LED_Set(bool on);
static void HAL_ErrorHandler(void);

/*=========================================================
 * Application Prototypes
 *=========================================================*/
static void Sensor_Init(void);
static void Sensor_Update(void);
static uint16_t Sensor_FilterSample(uint16_t sample);
static sensor_status_t Sensor_EvaluateStatus(uint16_t value);
static bool Sensor_IsValidRaw(uint16_t sample);
static void App_Init(void);
static void App_Task(void);
static uint32_t GetSystemTickMs(void);

/*=========================================================
 * Interrupt / Tick Hook
 * Call this from a hardware timer ISR every 1 ms.
 *=========================================================*/
void SysTick_Handler(void)
{
    g_system_tick_ms++;
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    App_Init();

    while (1)
    {
        App_Task();
    }

    return 0;
}

/*=========================================================
 * Application Initialization
 *=========================================================*/
static void App_Init(void)
{
    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_Timer_Init();

    Sensor_Init();
}

/*=========================================================
 * Main Application Task
 *=========================================================*/
static void App_Task(void)
{
    static uint32_t last_sample_time = 0;
    uint32_t now = GetSystemTickMs();

    if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
    {
        last_sample_time = now;
        Sensor_Update();

        /* Example actuator/indicator behavior */
        if (g_sensor_data.status == SENSOR_STATUS_HIGH)
        {
            HAL_LED_Set(true);
        }
        else
        {
            HAL_LED_Set(false);
        }
    }

    /* Other background tasks can be added here */
}

/*=========================================================
 * Sensor Module
 *=========================================================*/
static void Sensor_Init(void)
{
    memset(&g_sensor_data, 0, sizeof(g_sensor_data));
    memset(g_sample_buffer, 0, sizeof(g_sample_buffer));
    g_sample_sum = 0;
    g_sample_index = 0;
    g_buffer_initialized = false;
}

static void Sensor_Update(void)
{
    uint16_t raw_sample;
    uint16_t filtered_sample;

    /* Example: read ADC channel 0 */
    raw_sample = HAL_ADC_ReadChannel(0);

    if (!Sensor_IsValidRaw(raw_sample))
    {
        g_sensor_data.status = SENSOR_STATUS_FAULT;
        g_sensor_data.new_data = false;
        return;
    }

    filtered_sample = Sensor_FilterSample(raw_sample);

    g_sensor_data.raw = raw_sample;
    g_sensor_data.filtered = filtered_sample;
    g_sensor_data.status = Sensor_EvaluateStatus(filtered_sample);
    g_sensor_data.new_data = true;
}

static bool Sensor_IsValidRaw(uint16_t sample)
{
    if ((sample < SENSOR_RAW_MIN) || (sample > SENSOR_RAW_MAX))
    {
        return false;
    }

    return true;
}

static uint16_t Sensor_FilterSample(uint16_t sample)
{
    uint32_t average;
    uint8_t i;

    if (!g_buffer_initialized)
    {
        for (i = 0; i < SENSOR_BUFFER_SIZE; i++)
        {
            g_sample_buffer[i] = sample;
        }

        g_sample_sum = (uint32_t)sample * SENSOR_BUFFER_SIZE;
        g_sample_index = 0;
        g_buffer_initialized = true;
    }
    else
    {
        g_sample_sum -= g_sample_buffer[g_sample_index];
        g_sample_buffer[g_sample_index] = sample;
        g_sample_sum += sample;

        g_sample_index++;
        if (g_sample_index >= SENSOR_BUFFER_SIZE)
        {
            g_sample_index = 0;
        }
    }

    average = g_sample_sum / SENSOR_BUFFER_SIZE;
    return (uint16_t)average;
}

static sensor_status_t Sensor_EvaluateStatus(uint16_t value)
{
    if (value > SENSOR_HIGH_THRESHOLD)
    {
        return SENSOR_STATUS_HIGH;
    }
    else if (value < SENSOR_LOW_THRESHOLD)
    {
        return SENSOR_STATUS_LOW;
    }
    else
    {
        return SENSOR_STATUS_OK;
    }
}

/*=========================================================
 * Utility
 *=========================================================*/
static uint32_t GetSystemTickMs(void)
{
    return g_system_tick_ms;
}

/*=========================================================
 * HAL Stubs
 * Replace with real hardware code
 *=========================================================*/
static void HAL_SystemInit(void)
{
    /* Configure clocks, flash latency, etc. */
}

static void HAL_GPIO_Init(void)
{
    /* Configure LED pin, sensor power pin, etc. */
}

static void HAL_ADC_Init(void)
{
    /* Configure ADC peripheral and sensor input channel */
}

static void HAL_Timer_Init(void)
{
    /* Configure a timer or SysTick to call SysTick_Handler every 1 ms */
}

