```c
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f

#define SENSOR_SAMPLE_PERIOD_MS 10U
#define SENSOR_FILTER_SIZE      8U

/* Example sensor conversion:
 * Suppose sensor outputs:
 * 0.5V = 0 units
 * 2.5V = 100 units
 */
#define SENSOR_VOLTAGE_MIN      0.5f
#define SENSOR_VOLTAGE_MAX      2.5f
#define SENSOR_UNITS_MIN        0.0f
#define SENSOR_UNITS_MAX        100.0f

/* Fault thresholds */
#define SENSOR_OPEN_THRESHOLD_V   0.05f
#define SENSOR_SHORT_THRESHOLD_V  3.20f

/*=========================================================
 * Mock HAL / Platform Interface
 * Replace these with MCU-specific implementations
 *=========================================================*/
void HAL_SystemClock_Init(void);
void HAL_GPIO_Init(void);
void HAL_ADC_Init(void);
void HAL_Timer_Init(void);
uint16_t HAL_ADC_ReadChannel(uint8_t channel);
uint32_t HAL_GetTickMs(void);
void HAL_DelayMs(uint32_t ms);

/*=========================================================
 * Sensor Data Types
 *=========================================================*/
typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_OPEN_CIRCUIT,
    SENSOR_STATUS_SHORT_CIRCUIT,
    SENSOR_STATUS_OUT_OF_RANGE
} sensor_status_t;

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float engineering_value;
    sensor_status_t status;
    bool new_data;
} sensor_data_t;

/*=========================================================
 * Module State
 *=========================================================*/
static sensor_data_t g_sensor_data;

static float g_filter_buffer[SENSOR_FILTER_SIZE];
static uint8_t g_filter_index = 0;
static bool g_filter_filled = false;

/*=========================================================
 * Utility Functions
 *=========================================================*/
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float clampf(float value, float min_val, float max_val)
{
    if (value < min_val) return min_val;
    if (value > max_val) return max_val;
    return value;
}

static float voltage_to_engineering_units(float voltage)
{
    float normalized;

    if (voltage <= SENSOR_VOLTAGE_MIN)
    {
        return SENSOR_UNITS_MIN;
    }
    if (voltage >= SENSOR_VOLTAGE_MAX)
    {
        return SENSOR_UNITS_MAX;
    }

    normalized = (voltage - SENSOR_VOLTAGE_MIN) /
                 (SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN);

    return SENSOR_UNITS_MIN +
           normalized * (SENSOR_UNITS_MAX - SENSOR_UNITS_MIN);
}

static float moving_average_filter(float sample)
{
    float sum = 0.0f;
    uint8_t count = g_filter_filled ? SENSOR_FILTER_SIZE : g_filter_index + 1U;

    g_filter_buffer[g_filter_index] = sample;
    g_filter_index++;

    if (g_filter_index >= SENSOR_FILTER_SIZE)
    {
        g_filter_index = 0;
        g_filter_filled = true;
    }

    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filter_buffer[i];
    }

    return sum / (float)count;
}

static sensor_status_t evaluate_sensor_status(float voltage)
{
    if (voltage <= SENSOR_OPEN_THRESHOLD_V)
    {
        return SENSOR_STATUS_OPEN_CIRCUIT;
    }

    if (voltage >= SENSOR_SHORT_THRESHOLD_V)
    {
        return SENSOR_STATUS_SHORT_CIRCUIT;
    }

    if ((voltage < SENSOR_VOLTAGE_MIN) || (voltage > SENSOR_VOLTAGE_MAX))
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

/*=========================================================
 * Sensor Module
 *=========================================================*/
void Sensor_Init(void)
{
    memset(&g_sensor_data, 0, sizeof(g_sensor_data));
    memset(g_filter_buffer, 0, sizeof(g_filter_buffer));
    g_filter_index = 0;
    g_filter_filled = false;
}

void Sensor_Update(void)
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    float eng_value;
    sensor_status_t status;

    raw = HAL_ADC_ReadChannel(0);
    voltage = adc_to_voltage(raw);
    filtered_voltage = moving_average_filter(voltage);
    status = evaluate_sensor_status(filtered_voltage);

    eng_value = voltage_to_engineering_units(filtered_voltage);
    eng_value = clampf(eng_value, SENSOR_UNITS_MIN, SENSOR_UNITS_MAX);

    g_sensor_data.raw_adc = raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.filtered_voltage = filtered_voltage;
    g_sensor_data.engineering_value = eng_value;
    g_sensor_data.status = status;
    g_sensor_data.new_data = true;
}

const sensor_data_t* Sensor_GetData(void)
{
    return &g_sensor_data;
}

void Sensor_ClearNewDataFlag(void)
{
    g_sensor_data.new_data = false;
}

/*=========================================================
 * Application
 *=========================================================*/
static void System_Init(void)
{
    HAL_SystemClock_Init();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_Timer_Init();
    Sensor_Init();
}

int main(void)
{
    uint32_t last_sample_time = 0;

    System_Init();

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;
            Sensor_Update();
        }

        /* Example application behavior */
        if (Sensor_GetData()->new_data)
        {
            const sensor_data_t *data = Sensor_GetData();

            /* Insert application logic here:
             * - control loop
             * - communications
             * - logging
             * - alarms
             */

            switch (data->status)
            {
                case SENSOR_STATUS_OK:
                    /* Normal operation */
                    break;

                case SENSOR_STATUS_OPEN_CIRCUIT:
                case SENSOR_STATUS_SHORT_CIRCUIT:
                case SENSOR_STATUS_OUT_OF_RANGE:
                    /* Fault handling */
                    break;

                default:
                    break;
            }

            Sensor_ClearNewDataFlag();
        }

        /* Optional low-power wait or background tasks */
        HAL_DelayMs(1);
    }

    return 0;
}

