## Example firmware

```c
#include <stdint.h>
#include <stdbool.h>

/* Configuration */
#define SENSOR_BUFFER_SIZE   16
#define SENSOR_MAX_VALUE     4095    // Example: 12-bit ADC
#define SAMPLE_PERIOD_MS     100

/* Global sensor state */
static uint16_t sensor_buffer[SENSOR_BUFFER_SIZE];
static uint8_t sensor_index = 0;
static uint32_t sensor_sum = 0;
static uint16_t filtered_value = 0;

/* Mock hardware abstraction prototypes */
void System_Init(void);
void ADC_Init(void);
uint16_t ADC_Read(void);
void UART_Init(void);
void UART_SendString(const char *str);
void Timer_DelayMs(uint32_t ms);

/* Processing */
static void SensorBuffer_Init(void)
{
    for (uint8_t i = 0; i < SENSOR_BUFFER_SIZE; i++) {
        sensor_buffer[i] = 0;
    }
    sensor_sum = 0;
    sensor_index = 0;
    filtered_value = 0;
}

static uint16_t Process_SensorData(uint16_t new_sample)
{
    /* Remove oldest sample from sum */
    sensor_sum -= sensor_buffer[sensor_index];

    /* Store new sample */
    sensor_buffer[sensor_index] = new_sample;

    /* Add new sample to sum */
    sensor_sum += new_sample;

    /* Advance circular index */
    sensor_index = (sensor_index + 1) % SENSOR_BUFFER_SIZE;

    /* Compute moving average */
    filtered_value = (uint16_t)(sensor_sum / SENSOR_BUFFER_SIZE);

    return filtered_value;
}

/* Optional threshold/event logic */
static bool Sensor_IsAlert(uint16_t value)
{
    const uint16_t threshold = 3000;
    return (value > threshold);
}

/* Main application */
int main(void)
{
    System_Init();
    ADC_Init();
    UART_Init();
    SensorBuffer_Init();

    while (1) {
        uint16_t raw_value = ADC_Read();

        if (raw_value > SENSOR_MAX_VALUE) {
            raw_value = SENSOR_MAX_VALUE;
        }

        uint16_t avg_value = Process_SensorData(raw_value);

        if (Sensor_IsAlert(avg_value)) {
            UART_SendString("ALERT: Sensor threshold exceeded\r\n");
        } else {
            UART_SendString("Sensor OK\r\n");
        }

        Timer_DelayMs(SAMPLE_PERIOD_MS);
    }

    return 0;
}
```

