# 3. Example C Firmware

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f

#define SAMPLE_PERIOD_MS        100
#define REPORT_PERIOD_MS        1000

#define MOVING_AVG_SIZE         8

#define SENSOR_HIGH_THRESHOLD_V 2.80f
#define SENSOR_LOW_THRESHOLD_V  0.50f

/*=========================================================
 * Mock hardware abstraction layer
 * Replace these with MCU-specific implementations
 *=========================================================*/
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
void SysTick_Init(void);

uint32_t HAL_GetTick(void);
uint16_t ADC_ReadRaw(void);
void UART_SendString(const char *str);
void LED_Set(bool on);

/*=========================================================
 * Sensor processing data structures
 *=========================================================*/
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

typedef struct
{
    float buffer[MOVING_AVG_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

/*=========================================================
 * Global state
 *=========================================================*/
static SensorData_t g_sensorData;
static MovingAverageFilter_t g_filter;

/*=========================================================
 * Filter functions
 *=========================================================*/
static void MovingAverage_Init(MovingAverageFilter_t *filter)
{
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (uint8_t i = 0; i < MOVING_AVG_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float MovingAverage_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < MOVING_AVG_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;

    return filter->sum / (float)filter->count;
}

/*=========================================================
 * Sensor functions
 *=========================================================*/
static float ADC_CountsToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static void Sensor_ReadAndProcess(SensorData_t *data, MovingAverageFilter_t *filter)
{
    data->raw = ADC_ReadRaw();
    data->voltage = ADC_CountsToVoltage(data->raw);
    data->filtered_voltage = MovingAverage_Update(filter, data->voltage);

    data->alarm_high = (data->filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
    data->alarm_low  = (data->filtered_voltage < SENSOR_LOW_THRESHOLD_V);

    if (data->alarm_high || data->alarm_low)
    {
        LED_Set(true);
    }
    else
    {
        LED_Set(false);
    }
}

static void Sensor_Report(const SensorData_t *data)
{
    char msg[128];
    snprintf(msg, sizeof(msg),
             "RAW=%u, V=%.3f, FV=%.3f, AH=%d, AL=%d\r\n",
             data->raw,
             data->voltage,
             data->filtered_voltage,
             data->alarm_high ? 1 : 0,
             data->alarm_low ? 1 : 0);
    UART_SendString(msg);
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init();
    SysTick_Init();

    MovingAverage_Init(&g_filter);

    uint32_t lastSampleTime = 0;
    uint32_t lastReportTime = 0;

    UART_SendString("Sensor firmware starting...\r\n");

    while (1)
    {
        uint32_t now = HAL_GetTick();

        if ((now - lastSampleTime) >= SAMPLE_PERIOD_MS)
        {
            lastSampleTime = now;
            Sensor_ReadAndProcess(&g_sensorData, &g_filter);
        }

        if ((now - lastReportTime) >= REPORT_PERIOD_MS)
        {
            lastReportTime = now;
            Sensor_Report(&g_sensorData);
        }

        /* Optional:
         * enter low-power mode until next interrupt
         */
    }

    return 0;
}
