## Example firmware structure

```c
#include <stdint.h>
#include <stdbool.h>

/*========================
  Configuration
========================*/
#define SENSOR_SAMPLE_PERIOD_MS   100
#define FILTER_WINDOW_SIZE        8
#define SENSOR_RAW_MIN            0
#define SENSOR_RAW_MAX            4095

/*========================
  Global state
========================*/
static volatile uint32_t g_system_tick_ms = 0;

static uint16_t g_sensor_buffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t g_buffer_index = 0;
static bool g_buffer_full = false;

static uint16_t g_latest_raw = 0;
static uint16_t g_filtered_value = 0;
static float g_processed_value = 0.0f;

/*========================
  Hardware abstraction stubs
  Replace these with MCU-specific code
========================*/
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
void Timer_Init(void);

uint16_t ADC_ReadSensor(void);
void UART_SendString(const char *msg);
void DelayMs(uint32_t ms);

/*========================
  Utility functions
========================*/
static void SensorBuffer_Add(uint16_t sample)
{
    g_sensor_buffer[g_buffer_index] = sample;
    g_buffer_index++;

    if (g_buffer_index >= FILTER_WINDOW_SIZE) {
        g_buffer_index = 0;
        g_buffer_full = true;
    }
}

static uint16_t SensorBuffer_Average(void)
{
    uint32_t sum = 0;
    uint8_t count = g_buffer_full ? FILTER_WINDOW_SIZE : g_buffer_index;

    if (count == 0) {
        return 0;
    }

    for (uint8_t i = 0; i < count; i++) {
        sum += g_sensor_buffer[i];
    }

    return (uint16_t)(sum / count);
}

static float ConvertRawToEngineeringUnits(uint16_t raw)
{
    /* Example conversion:
       Convert 12-bit ADC reading to voltage assuming 3.3V reference
    */
    return ((float)raw * 3.3f) / 4095.0f;
}

static bool IsSensorValueValid(uint16_t raw)
{
    return (raw >= SENSOR_RAW_MIN && raw <= SENSOR_RAW_MAX);
}

/*========================
  Sensor processing
========================*/
static void ReadAndProcessSensor(void)
{
    uint16_t raw = ADC_ReadSensor();

    if (!IsSensorValueValid(raw)) {
        return;
    }

    g_latest_raw = raw;

    SensorBuffer_Add(raw);
    g_filtered_value = SensorBuffer_Average();
    g_processed_value = ConvertRawToEngineeringUnits(g_filtered_value);
}

/*========================
  Reporting
========================*/
static void ReportSensorData(void)
{
    char msg[64];

    /* Minimal integer-only formatting alternative may be needed
       on small MCUs if sprintf/float is too heavy.
    */
    int whole = (int)g_processed_value;
    int frac = (int)((g_processed_value - whole) * 1000.0f);
    if (frac < 0) frac = -frac;

    /* Simple manual formatting could replace snprintf if unavailable */
    extern int snprintf(char *str, unsigned long size, const char *format, ...);
    snprintf(msg, sizeof(msg),
             "RAW=%u AVG=%u VAL=%d.%03d\r\n",
             g_latest_raw,
             g_filtered_value,
             whole,
             frac);

    UART_SendString(msg);
}

/*========================
  Initialization
========================*/
static void Hardware_Init(void)
{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init();
    Timer_Init();
}

/*========================
  Main application
========================*/
int main(void)
{
    Hardware_Init();

    uint32_t last_sample_time = 0;

    while (1) {
        if ((g_system_tick_ms - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS) {
            last_sample_time = g_system_tick_ms;

            ReadAndProcessSensor();
            ReportSensorData();
        }

        /* Optional low-power wait or background tasks here */
    }

    return 0;
}

/*========================
  Example timer tick ISR hook
  Call this from a 1 ms timer interrupt
========================*/
void SysTick_Handler(void)
{
    g_system_tick_ms++;
}
