# 2. Example Firmware Implementation

## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/* =========================================================
 * Configuration
 * ========================================================= */
#define SENSOR_COUNT            2
#define ADC_MAX_VALUE           4095.0f
#define ADC_REF_VOLTAGE         3.3f

#define SAMPLE_PERIOD_MS        100
#define UART_TX_PERIOD_MS       500

#define TEMP_SENSOR_CHANNEL     0
#define LIGHT_SENSOR_CHANNEL    1

#define TEMP_ALERT_THRESHOLD_C  50.0f
#define LIGHT_ALERT_THRESHOLD_V 2.80f

#define FILTER_ALPHA            0.2f   /* 0..1, higher = less smoothing */

/* =========================================================
 * Hardware Abstraction Layer Prototypes
 * Replace these with MCU-specific implementations
 * ========================================================= */
void hal_init(void);
uint32_t hal_millis(void);
uint16_t hal_adc_read(uint8_t channel);
void hal_uart_write(const char *msg);
void hal_delay_ms(uint32_t ms);

/* =========================================================
 * Data Structures
 * ========================================================= */
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered;
    bool alert;
} SensorData;

typedef struct
{
    SensorData temperature;
    SensorData light;
} SystemData;

/* =========================================================
 * Global State
 * ========================================================= */
static SystemData g_system_data;

/* =========================================================
 * Utility Functions
 * ========================================================= */
static float adc_to_voltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
}

/*
 * Example conversion:
 * Assume temperature sensor outputs:
 *   0.5V = 0C
 *   10mV per degree C
 * Formula:
 *   Temp(C) = (V - 0.5) / 0.01
 */
static float voltage_to_temperature_c(float voltage)
{
    return (voltage - 0.5f) / 0.01f;
}

static float low_pass_filter(float previous, float current, float alpha)
{
    return (alpha * current) + ((1.0f - alpha) * previous);
}

/* =========================================================
 * Sensor Processing
 * ========================================================= */
static void process_temperature_sensor(void)
{
    uint16_t raw = hal_adc_read(TEMP_SENSOR_CHANNEL);
    float voltage = adc_to_voltage(raw);
    float temp_c = voltage_to_temperature_c(voltage);

    g_system_data.temperature.raw = raw;
    g_system_data.temperature.voltage = temp_c;

    static bool initialized = false;
    if (!initialized)
    {
        g_system_data.temperature.filtered = temp_c;
        initialized = true;
    }
    else
    {
        g_system_data.temperature.filtered =
            low_pass_filter(g_system_data.temperature.filtered, temp_c, FILTER_ALPHA);
    }

    g_system_data.temperature.alert =
        (g_system_data.temperature.filtered >= TEMP_ALERT_THRESHOLD_C);
}

static void process_light_sensor(void)
{
    uint16_t raw = hal_adc_read(LIGHT_SENSOR_CHANNEL);
    float voltage = adc_to_voltage(raw);

    g_system_data.light.raw = raw;
    g_system_data.light.voltage = voltage;

    static bool initialized = false;
    if (!initialized)
    {
        g_system_data.light.filtered = voltage;
        initialized = true;
    }
    else
    {
        g_system_data.light.filtered =
            low_pass_filter(g_system_data.light.filtered, voltage, FILTER_ALPHA);
    }

    g_system_data.light.alert =
        (g_system_data.light.filtered >= LIGHT_ALERT_THRESHOLD_V);
}

/* =========================================================
 * Telemetry / Debug Output
 * ========================================================= */
static void transmit_status(void)
{
    char buffer[256];

    snprintf(buffer, sizeof(buffer),
             "TEMP raw=%u temp=%.2fC filt=%.2fC alert=%d | "
             "LIGHT raw=%u volt=%.2fV filt=%.2fV alert=%d\r\n",
             g_system_data.temperature.raw,
             g_system_data.temperature.voltage,
             g_system_data.temperature.filtered,
             g_system_data.temperature.alert ? 1 : 0,
             g_system_data.light.raw,
             g_system_data.light.voltage,
             g_system_data.light.filtered,
             g_system_data.light.alert ? 1 : 0);

    hal_uart_write(buffer);
}

/* =========================================================
 * Main Application
 * ========================================================= */
int main(void)
{
    hal_init();

    memset(&g_system_data, 0, sizeof(g_system_data));

    uint32_t last_sample_time = 0;
    uint32_t last_uart_time = 0;

    while (1)
    {
        uint32_t now = hal_millis();

        if ((now - last_sample_time) >= SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;

            process_temperature_sensor();
            process_light_sensor();
        }

        if ((now - last_uart_time) >= UART_TX_PERIOD_MS)
        {
            last_uart_time = now;
            transmit_status();
        }

        /* Optional low-power wait or short delay */
        hal_delay_ms(1);
    }

    return 0;
}
```

