typedef struct
{
    uint16_t buffer[SENSOR_AVG_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter_t;

/*=========================================================
 * Global State
 *=========================================================*/
static SensorData_t g_sensorData;
static MovingAverageFilter_t g_filter;

/*=========================================================
 * Utility Functions
 *=========================================================*/
static void Filter_Init(MovingAverageFilter_t *filter)
{
    uint8_t i;
    filter->sum = 0;
    filter->index = 0;
    filter->count = 0;

    for (i = 0; i < SENSOR_AVG_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0;
    }
}

static uint16_t Filter_Update(MovingAverageFilter_t *filter, uint16_t sample)
{
    if (filter->count < SENSOR_AVG_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= SENSOR_AVG_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return (uint16_t)(filter->sum / filter->count);
}

static uint32_t ADC_ToMilliVolts(uint16_t adc)
{
    return ((uint32_t)adc * ADC_REF_MV) / ADC_MAX_VALUE;
}

static bool Sensor_IsValid(uint16_t adc)
{
    return (adc >= SENSOR_MIN_VALID_ADC) && (adc <= SENSOR_MAX_VALID_ADC);
}

