    g_sensorData.filtered_adc = 0;
    g_sensorData.sensor_mv = 0;
    g_sensorData.valid = false;
    g_sensorData.fault = false;

    Filter_Init(&g_filter);
}

static void Sensor_ReadAndProcess(void)
{
    uint16_t raw = HAL_ADC_Read(0);
    uint16_t filtered = Filter_Update(&g_filter, raw);
    bool valid = Sensor_IsValid(raw);

    g_sensorData.raw_adc = raw;
    g_sensorData.filtered_adc = filtered;
    g_sensorData.sensor_mv = ADC_ToMilliVolts(filtered);
    g_sensorData.valid = valid;
    g_sensorData.fault = !valid;
}

