## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Initial firmware example for sensor acquisition and processing.
 *
 * Features:
 * - Periodic sampling using a millisecond tick
 * - Simulated ADC/sensor read
 * - Calibration (offset + scale)
 * - Moving average filter
 * - Threshold detection
 * - Basic fault detection
 *
 * Replace the hardware abstraction stubs with MCU-specific drivers.
 */

/* ============================================================
 * Configuration
 * ============================================================ */

#define SYS_TICK_MS                1U
#define SENSOR_SAMPLE_PERIOD_MS   100U
#define SENSOR_MOVING_AVG_SIZE      8U

#define SENSOR_RAW_MIN              0U
#define SENSOR_RAW_MAX           4095U   /* Example: 12-bit ADC */

#define SENSOR_PROCESSED_MIN      -40.0f
#define SENSOR_PROCESSED_MAX      125.0f

#define SENSOR_ALERT_HIGH          80.0f
#define SENSOR_ALERT_LOW          -10.0f

#define SENSOR_STALE_TIMEOUT_MS   500U

/* ============================================================
 * Types
 * ============================================================ */

typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_OUT_OF_RANGE,
    SENSOR_STATUS_STALE,
    SENSOR_STATUS_HW_ERROR
} sensor_status_t;

typedef struct
{
    uint16_t raw;
    float calibrated;
    float filtered;
    sensor_status_t status;
    bool alert_high;
    bool alert_low;
    uint32_t last_update_ms;
} sensor_data_t;

typedef struct
{
    float offset;
    float scale;
} sensor_calibration_t;

typedef struct
{
    float buffer[SENSOR_MOVING_AVG_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_average_filter_t;

/* ============================================================
 * Global state
 * ============================================================ */

static volatile uint32_t g_system_time_ms = 0;

static sensor_data_t g_sensor_data = {0};

static sensor_calibration_t g_sensor_cal = {
    .offset = 0.0f,
    .scale  = 0.1f   /* Example conversion factor */
};

static moving_average_filter_t g_filter = {0};

/* ============================================================
 * Hardware abstraction stubs
 * Replace these with real MCU/HAL implementations
 * ============================================================ */

void HAL_SystemInit(void)
{
    /* Initialize clocks, GPIO, ADC, UART, timers, etc. */
}

void HAL_SysTick_Handler(void)
{
    g_system_time_ms += SYS_TICK_MS;
}

uint32_t HAL_GetTick(void)
{
    return g_system_time_ms;
}

bool HAL_SensorReadRaw(uint16_t *out_raw)
{
    /*
     * Replace with actual ADC/I2C/SPI sensor read.
     * This stub generates pseudo sensor data.
     */
    static uint16_t simulated = 2000;
    static int8_t direction = 1;

    if (out_raw == NULL)
    {
        return false;
    }

    simulated += (uint16_t)(direction * 15);

    if (simulated > 3000)
    {
        direction = -1;
    }
    else if (simulated < 1000)
    {
        direction = 1;
    }

    *out_raw = simulated;
    return true;
}

void HAL_Log(const char *msg)
{
    /* Replace with UART/ITM/RTT logging if desired */
    printf("%s\n", msg);
}

/* ============================================================
 * Filter functions
 * ============================================================ */

static void Filter_Init(moving_average_filter_t *filter)
{
    if (filter == NULL)
    {
        return;
    }

    for (uint8_t i = 0; i < SENSOR_MOVING_AVG_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }

    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;
}

static float Filter_Update(moving_average_filter_t *filter, float sample)
{
    if (filter == NULL)
    {
        return sample;
    }

    if (filter->count < SENSOR_MOVING_AVG_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= SENSOR_MOVING_AVG_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

/* ============================================================
 * Sensor processing
 * ============================================================ */

static float Sensor_ApplyCalibration(uint16_t raw, const sensor_calibration_t *cal)
{
    if (cal == NULL)
    {
        return (float)raw;
    }

    return ((float)raw * cal->scale) + cal->offset;
}

static sensor_status_t Sensor_ValidateRaw(uint16_t raw)
{
    if (raw < SENSOR_RAW_MIN || raw > SENSOR_RAW_MAX)
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

static sensor_status_t Sensor_ValidateProcessed(float value)
{
    if (value < SENSOR_PROCESSED_MIN || value > SENSOR_PROCESSED_MAX)
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

static void Sensor_UpdateAlerts(sensor_data_t *data)
{
    if (data == NULL)
    {
        return;
    }

    data->alert_high = (data->filtered > SENSOR_ALERT_HIGH);
    data->alert_low  = (data->filtered < SENSOR_ALERT_LOW);
}

static void Sensor_Process(void)
{
    uint16_t raw = 0;
    bool read_ok = HAL_SensorReadRaw(&raw);

    if (!read_ok)
    {
        g_sensor_data.status = SENSOR_STATUS_HW_ERROR;
        HAL_Log("Sensor read failed");
        return;
    }

    g_sensor_data.raw = raw;
    g_sensor_data.last_update_ms = HAL_GetTick();

    sensor_status_t raw_status = Sensor_ValidateRaw(raw);
    if (raw_status != SENSOR_STATUS_OK)
    {
        g_sensor_data.status = raw_status;
        HAL_Log("Sensor raw value out of range");
        return;
    }

    g_sensor_data.calibrated = Sensor_ApplyCalibration(raw, &g_sensor_cal);

    sensor_status_t proc_status = Sensor_ValidateProcessed(g_sensor_data.calibrated);
    if (proc_status != SENSOR_STATUS_OK)
    {
        g_sensor_data.status = proc_status;
        HAL_Log("Sensor processed value out of range");
        return;
    }

    g_sensor_data.filtered = Filter_Update(&g_filter, g_sensor_data.calibrated);
    g_sensor_data.status = SENSOR_STATUS_OK;

    Sensor_UpdateAlerts(&g_sensor_data);
}

static void Sensor_CheckStale(void)
{
    uint32_t now = HAL_GetTick();

    if ((now - g_sensor_data.last_update_ms) > SENSOR_STALE_TIMEOUT_MS)
    {
        g_sensor_data.status = SENSOR_STATUS_STALE;
    }
}

/* ============================================================
 * Application tasks
 * ============================================================ */

static void App_Init(void)
{
    HAL_SystemInit();
    Filter_Init(&g_filter);

    g_sensor_data.raw = 0;
    g_sensor_data.calibrated = 0.0f;
    g_sensor_data.filtered = 0.0f;
    g_sensor_data.status = SENSOR_STATUS_STALE;
    g_sensor_data.alert_high = false;
    g_sensor_data.alert_low = false;
    g_sensor_data.last_update_ms = 0;

    HAL_Log("Application initialized");
}

static void App_Run(void)
{
    static uint32_t last_sample_time = 0;
    uint32_t now = HAL_GetTick();

    if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
    {
        last_sample_time = now;
        Sensor_Process();
    }

    Sensor_CheckStale();

    /* Optional: publish/log data periodically */
    static uint32_t last_log_time = 0;
    if ((now - last_log_time) >= 1000U)
    {
        last_log_time = now;

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "raw=%u cal=%.2f filt=%.2f status=%d high=%d low=%d",
                 g_sensor_data.raw,
                 g_sensor_data.calibrated,
                 g_sensor_data.filtered,
                 g_sensor_data.status,
                 g_sensor_data.alert_high,
                 g_sensor_data.alert_low);
        HAL_Log(msg);
    }
}

/* ============================================================
 * Main
 * ============================================================ */

int main(void)
{
    App_Init();

    while (1)
    {
        App_Run();

        /*
         * In a real MCU:
         * - sleep until interrupt
         * - handle background tasks
         * - feed watchdog
         */
    }

    return 0;
}
```

