    g_sensor_data.voltage = 0.0f;
    g_sensor_data.temperature_c = 0.0f;
    g_sensor_data.filtered_temperature_c = 0.0f;
    g_sensor_data.valid = false;
}

static void Sensor_Read(sensor_data_t *data)
{
    uint32_t sum = 0;

    for (uint8_t i = 0; i < SENSOR_SAMPLE_COUNT; i++)
    {
        sum += ADC_ReadChannel(0); /* Sensor connected to ADC channel 0 */
    }

    data->raw_adc = (uint16_t)(sum / SENSOR_SAMPLE_COUNT);
    data->voltage = Sensor_ConvertToVoltage(data->raw_adc);
    data->valid = Sensor_Validate(data->voltage);

    if (data->valid)
    {
        data->temperature_c = Sensor_ConvertToTemperature(data->voltage);
        data->filtered_temperature_c = Sensor_Filter(data->temperature_c);
    }
    else
    {
        data->temperature_c = 0.0f;
    }
}

static float Sensor_ConvertToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
