static void SensorBuffer_AddSample(uint16_t sample)
{
    g_sensorSamples[g_sampleIndex] = sample;
    g_sampleIndex++;

    if (g_sampleIndex >= SENSOR_SAMPLE_COUNT)
    {
        g_sampleIndex = 0;
        g_bufferFilled = true;
    }
}

static uint16_t SensorBuffer_GetAverage(void)
{
    uint32_t sum = 0;
    uint8_t count = g_bufferFilled ? SENSOR_SAMPLE_COUNT : g_sampleIndex;

    if (count == 0)
    {
        return 0;
    }

    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_sensorSamples[i];
    }

    return (uint16_t)(sum / count);
}

static float ADC_CountsToVoltage(uint16_t adcCounts)
{
    return ((float)adcCounts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static void ProcessSensorData(void)
{
    uint16_t rawSample = ADC_ReadChannel(0);
    SensorBuffer_AddSample(rawSample);

    uint16_t avgSample = SensorBuffer_GetAverage();
    g_filteredVoltage = ADC_CountsToVoltage(avgSample);

    if (g_filteredVoltage > SENSOR_THRESHOLD_VOLTS)
    {
        g_thresholdExceeded = true;
        LED_Set(true);
