#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_PERIOD_MS 100U
#define FILTER_ALPHA            0.2f        // Low-pass filter coefficient

#define SENSOR_HIGH_THRESHOLD_V 2.8f
#define SENSOR_LOW_THRESHOLD_V  0.3f

/*=========================================================
 * Mock hardware interface prototypes
 * Replace these with MCU-specific implementations
 *=========================================================*/
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void Timer_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void UART_Init(void);
void UART_SendString(const char *str);

/*=========================================================
 * Global system tick
 *=========================================================*/
volatile uint32_t g_ms_ticks = 0;

/*=========================================================
 * Sensor data structure
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    bool fault_low;
    bool fault_high;
} SensorData_t;

static SensorData_t g_sensor_data;

/*=========================================================
 * Utility functions
 *=========================================================*/
static uint32_t millis(void)
{
    return g_ms_ticks;
}

static float adc_to_voltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float low_pass_filter(float input, float prev_output, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * prev_output);
}

/*=========================================================
 * Sensor processing
 *=========================================================*/
static void Sensor_Init(void)
{
    g_sensor_data.raw_adc = 0;
    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.fault_low = false;
    g_sensor_data.fault_high = false;
}

static void Sensor_ReadAndProcess(void)
{
    uint16_t adc_raw = ADC_ReadChannel(0);

    g_sensor_data.raw_adc = adc_raw;
    g_sensor_data.voltage = adc_to_voltage(adc_raw);
    g_sensor_data.filtered_voltage = low_pass_filter(
        g_sensor_data.voltage,
        g_sensor_data.filtered_voltage,
        FILTER_ALPHA
    );

    g_sensor_data.fault_low = (g_sensor_data.filtered_voltage < SENSOR_LOW_THRESHOLD_V);
    g_sensor_data.fault_high = (g_sensor_data.filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
}

/*=========================================================
 * Optional reporting
 *=========================================================*/
static void Sensor_Report(void)
{
    char msg[128];

    /* Minimal embedded-friendly formatting alternative preferred in production.
       sprintf is used here for clarity. */
    extern int sprintf(char *str, const char *format, ...);

    sprintf(msg,
            "ADC=%u, V=%.3f, Filt=%.3f, Low=%d, High=%d\r\n",
            g_sensor_data.raw_adc,
            g_sensor_data.voltage,
            g_sensor_data.filtered_voltage,
            g_sensor_data.fault_low,
            g_sensor_data.fault_high);

    UART_SendString(msg);
}

/*=========================================================
 * Main application
 *=========================================================*/
int main(void)
{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    Timer_Init();
    UART_Init();

    Sensor_Init();

    uint32_t last_sample_time = 0;
    uint32_t last_report_time = 0;

    while (1)
    {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;
            Sensor_ReadAndProcess();
        }

        if ((now - last_report_time) >= 1000U)
        {
            last_report_time = now;
            Sensor_Report();
        }

        /* Optional: enter low-power mode here until next interrupt */
    }

    return 0;
}
```

