# `sensor.c`

```c
#include "sensor.h"
#include "platform.h"

#define SENSOR_ADC_CHANNEL         0
#define SENSOR_SAMPLE_PERIOD_MS    10
#define SENSOR_FILTER_SIZE         8

#define ADC_MAX_COUNTS             4095.0f
#define ADC_REF_VOLTAGE            3.3f

/* Example conversion:
 * physical_value = voltage * scale
 * Replace with your real sensor transfer function.
 */
#define SENSOR_SCALE_FACTOR        100.0f

/* Fault thresholds */
#define SENSOR_MIN_VALID_VOLTAGE   0.1f
#define SENSOR_MAX_VALID_VOLTAGE   3.2f

static sensor_data_t g_sensor_data;
static volatile bool g_sample_ready = false;

static uint16_t filter_buffer[SENSOR_FILTER_SIZE];
static uint32_t filter_sum = 0;
static uint8_t filter_index = 0;
static bool filter_initialized = false;

static uint16_t moving_average_filter(uint16_t new_sample)
{
    if (!filter_initialized)
    {
        for (uint8_t i = 0; i < SENSOR_FILTER_SIZE; i++)
        {
            filter_buffer[i] = new_sample;
            filter_sum += new_sample;
        }
        filter_initialized = true;
        return new_sample;
    }

    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = new_sample;
    filter_sum += new_sample;

    filter_index++;
    if (filter_index >= SENSOR_FILTER_SIZE)
    {
        filter_index = 0;
    }

    return (uint16_t)(filter_sum / SENSOR_FILTER_SIZE);
}

static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float voltage_to_physical(float voltage)
{
    return voltage * SENSOR_SCALE_FACTOR;
}

void sensor_init(void)
{
    g_sensor_data.raw_adc = 0;
    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.physical_value = 0.0f;
    g_sensor_data.fault = false;

    g_sample_ready = false;
    filter_sum = 0;
    filter_index = 0;
    filter_initialized = false;
}

void sensor_task_1ms(void)
{
    static uint16_t sample_timer = 0;

    sample_timer++;
    if (sample_timer < SENSOR_SAMPLE_PERIOD_MS)
    {
        return;
    }
    sample_timer = 0;

    uint16_t raw = platform_adc_read(SENSOR_ADC_CHANNEL);
    uint16_t filtered_raw = moving_average_filter(raw);

    float voltage = adc_to_voltage(raw);
    float filtered_voltage = adc_to_voltage(filtered_raw);
    float physical = voltage_to_physical(filtered_voltage);

    bool fault = false;
    if ((filtered_voltage < SENSOR_MIN_VALID_VOLTAGE) ||
        (filtered_voltage > SENSOR_MAX_VALID_VOLTAGE))
    {
        fault = true;
    }

    g_sensor_data.raw_adc = raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.filtered_voltage = filtered_voltage;
    g_sensor_data.physical_value = physical;
    g_sensor_data.fault = fault;

    g_sample_ready = true;
}

bool sensor_sample_ready(void)
{
    return g_sample_ready;
}

void sensor_get_data(sensor_data_t *out)
{
    if (out == 0)
    {
        return;
    }

    *out = g_sensor_data;
    g_sample_ready = false;
}
