{
    HAL_SystemClock_Init();
    HAL_GPIO_Init();
    HAL_UART_Init();
    HAL_ADC_Init();
    HAL_Timer_Init(SENSOR_SAMPLE_PERIOD_MS);
}

static void Sensor_Init(void)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        g_filter_buffer[i] = 0.0f;
    }

    g_filter_index = 0;
    g_filter_full = false;

    g_sensor_data.raw = 0;
    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.fault_low = false;
    g_sensor_data.fault_high = false;
}

/*==========================================================
 * Sensor processing
 *==========================================================*/
static void Sensor_SampleAndProcess(void)
{
    uint16_t raw = HAL_ADC_ReadChannel(0);

    g_sensor_data.raw = raw;
    g_sensor_data.voltage = Sensor_ConvertRawToVoltage(raw);
    g_sensor_data.filtered_voltage = Filter_MovingAverage(g_sensor_data.voltage);

    Sensor_CheckThresholds(&g_sensor_data);
}

static float Sensor_ConvertRawToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Filter_MovingAverage(float sample)
{
    float sum = 0.0f;
    uint8_t count = 0;

    g_filter_buffer[g_filter_index] = sample;
    g_filter_index++;

    if (g_filter_index >= FILTER_WINDOW_SIZE)
    {
        g_filter_index = 0;
        g_filter_full = true;
    }

    count = g_filter_full ? FILTER_WINDOW_SIZE : g_filter_index;

    if (count == 0)
    {
        return sample;
    }

    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filter_buffer[i];
    }

    return sum / (float)count;
}

static void Sensor_CheckThresholds(SensorData_t *data)
{
    data->fault_low = (data->filtered_voltage < SENSOR_LOW_THRESHOLD_V);
    data->fault_high = (data->filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
}

static void Sensor_Report(const SensorData_t *data)
{
    char msg[128];

    snprintf(msg, sizeof(msg),
             "RAW=%u, V=%.3f, FV=%.3f, LOW=%u, HIGH=%u\r\n",
             data->raw,
             data->voltage,
             data->filtered_voltage,
             data->fault_low ? 1 : 0,
             data->fault_high ? 1 : 0);

