# Initial Firmware Implementation

```c
/*
 * initial_sensor_firmware.c
 *
 * Generic microcontroller firmware example for reading and processing sensor data.
 *
 * Features:
 * - ADC-based sensor reading
 * - Moving average filter
 * - Conversion from raw ADC counts to voltage
 * - Example threshold/alarm logic
 * - Periodic sampling in main loop
 *
 * Replace HAL_* functions with your MCU-specific drivers.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*=============================
 * Configuration
 *=============================*/
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_ADC_CHANNEL      0

#define SAMPLE_PERIOD_MS        100
#define FILTER_WINDOW_SIZE      8

#define SENSOR_HIGH_THRESHOLD_V 2.5f
#define SENSOR_LOW_THRESHOLD_V  0.5f

/*=============================
 * Data Structures
 *=============================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

/*=============================
 * Global State
 *=============================*/
static SensorData_t g_sensor_data;
static MovingAverageFilter_t g_filter;

/*=============================
 * HAL / Platform Stubs
 * Replace these with real MCU code
 *=============================*/
static void HAL_SystemInit(void)
{
    // Configure clocks, watchdog, flash latency, etc.
}

static void HAL_GPIO_Init(void)
{
    // Configure status LED, debug pins, sensor enable pins, etc.
}

static void HAL_ADC_Init(void)
{
    // Configure ADC peripheral, resolution, sample time, channel setup, etc.
}

static void HAL_UART_Init(void)
{
    // Optional: configure UART for debug logging
}

static uint32_t HAL_GetTickMs(void)
{
    // Return system uptime in milliseconds
    // Replace with SysTick or timer-based implementation
    static uint32_t fake_tick = 0;
    fake_tick += SAMPLE_PERIOD_MS;
    return fake_tick;
}

static void HAL_DelayMs(uint32_t ms)
{
    // Replace with actual blocking or timer-based delay
    (void)ms;
}

static uint16_t HAL_ADC_ReadChannel(uint8_t channel)
{
    // Replace with actual ADC conversion code
    // Example dummy waveform-like test data
    static uint16_t dummy = 1000;
    (void)channel;

    dummy += 137;
    if (dummy > 4000)
    {
        dummy = 500;
    }

    return dummy;
}

static void HAL_LED_Set(bool on)
{
    // Replace with actual GPIO write
    (void)on;
}

static void HAL_UART_Log(const char *msg)
{
    // Replace with UART transmit
    // For simulation/debug builds, this could map to printf
    printf("%s", msg);
}

/*=============================
 * Filter Functions
 *=============================*/
static void Filter_Init(MovingAverageFilter_t *filter)
{
    uint8_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / filter->count;
}

/*=============================
 * Sensor Processing
 *=============================*/
static float ADC_CountsToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static void Sensor_ReadRaw(SensorData_t *data)
{
    data->raw_adc = HAL_ADC_ReadChannel(SENSOR_ADC_CHANNEL);
}

static void Sensor_Process(SensorData_t *data, MovingAverageFilter_t *filter)
{
    data->voltage = ADC_CountsToVoltage(data->raw_adc);
    data->filtered_voltage = Filter_Update(filter, data->voltage);

    data->alarm_high = (data->filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
    data->alarm_low  = (data->filtered_voltage < SENSOR_LOW_THRESHOLD_V);
}

static void Sensor_HandleOutputs(const SensorData_t *data)
{
    // Example output behavior:
    // Turn LED on if sensor is outside normal range
    bool alarm_active = data->alarm_high || data->alarm_low;
    HAL_LED_Set(alarm_active);
}

static void Sensor_LogData(const SensorData_t *data)
{
    char msg[128];
    snprintf(msg, sizeof(msg),
             "ADC=%u, V=%.3f, Filtered=%.3f, High=%d, Low=%d\r\n",
             data->raw_adc,
             data->voltage,
             data->filtered_voltage,
             data->alarm_high ? 1 : 0,
             data->alarm_low ? 1 : 0);
    HAL_UART_Log(msg);
}

/*=============================
 * Application Initialization
 *=============================*/
static void App_Init(void)
{
    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_UART_Init();

    Filter_Init(&g_filter);

    g_sensor_data.raw_adc = 0;
    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.alarm_high = false;
    g_sensor_data.alarm_low = false;
}

/*=============================
 * Main Application Task
 *=============================*/
static void App_Task(void)
{
    Sensor_ReadRaw(&g_sensor_data);
    Sensor_Process(&g_sensor_data, &g_filter);
    Sensor_HandleOutputs(&g_sensor_data);
    Sensor_LogData(&g_sensor_data);
}

/*=============================
 * Main
 *=============================*/
int main(void)
{
    uint32_t last_sample_time = 0;

    App_Init();

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - last_sample_time) >= SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;
            App_Task();
        }

        // Idle / low-power / background tasks
        HAL_DelayMs(1);
    }

    return 0;
}
