    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.value_units = 0.0f;
    g_sensor_data.status = SENSOR_STATUS_OK;
    g_sensor_data.new_data = false;
}

static void sensor_sample_and_process(void)
{
    const uint8_t sensor_adc_channel = 0;

    uint16_t raw = hal_adc_read_channel(sensor_adc_channel);
    float voltage = sensor_adc_to_voltage(raw);
    float filtered_voltage = sensor_apply_moving_average(voltage);
    sensor_status_t status = sensor_check_status(filtered_voltage);
    float units = sensor_voltage_to_units(filtered_voltage);

    g_sensor_data.raw_adc = raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.filtered_voltage = filtered_voltage;
    g_sensor_data.value_units = units;
    g_sensor_data.status = status;
    g_sensor_data.new_data = true;
}

static float sensor_adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float sensor_voltage_to_units(float voltage)
{
    if (voltage <= SENSOR_VOLTAGE_MIN)
    {
        return SENSOR_UNITS_MIN;
    }

    if (voltage >= SENSOR_VOLTAGE_MAX)
    {
        return SENSOR_UNITS_MAX;
    }

    float ratio = (voltage - SENSOR_VOLTAGE_MIN) /
                  (SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN);

    return SENSOR_UNITS_MIN + ratio * (SENSOR_UNITS_MAX - SENSOR_UNITS_MIN);
}

static float sensor_apply_moving_average(float sample)
{
    float sum = 0.0f;

    if (!g_filter_initialized)
    {
        for (uint8_t i = 0; i < SENSOR_FILTER_SIZE; i++)
        {
            g_filter_buffer[i] = sample;
        }
        g_filter_initialized = true;
    }

    g_filter_buffer[g_filter_index] = sample;
    g_filter_index = (g_filter_index + 1U) % SENSOR_FILTER_SIZE;

    for (uint8_t i = 0; i < SENSOR_FILTER_SIZE; i++)
    {
        sum += g_filter_buffer[i];
    }

    return sum / SENSOR_FILTER_SIZE;
}

static sensor_status_t sensor_check_status(float voltage)
{
    if (voltage < SENSOR_VALID_MIN_V)
    {
        return SENSOR_STATUS_DISCONNECTED;
    }

    if (voltage > SENSOR_VALID_MAX_V)
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

