#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_PERIOD_MS 100
#define FILTER_WINDOW_SIZE      8

#define SENSOR_LOW_THRESHOLD_V  0.5f
#define SENSOR_HIGH_THRESHOLD_V 2.8f

/*=========================================================
 * Mock hardware abstraction layer (replace with MCU HAL)
 *=========================================================*/
