{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_LOW,
    SENSOR_STATUS_HIGH,
    SENSOR_STATUS_FAULT
} SensorStatus_t;

typedef struct
{
    uint16_t raw;
    float voltage;
    float filteredVoltage;
    SensorStatus_t status;
} SensorData_t;

/*=========================================================
 * Globals
 *=========================================================*/
