static float g_filterBuffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t g_filterIndex = 0;
static bool g_filterFilled = false;

/*=========================================================
 * Utility functions
 *=========================================================*/
static float ADC_CountsToVoltage(uint16_t counts)
{
    return ((float)counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float MovingAverageFilter(float newSample)
{
    g_filterBuffer[g_filterIndex] = newSample;
    g_filterIndex++;

    if (g_filterIndex >= FILTER_WINDOW_SIZE)
    {
        g_filterIndex = 0;
        g_filterFilled = true;
    }

    uint8_t count = g_filterFilled ? FILTER_WINDOW_SIZE : g_filterIndex;
    if (count == 0)
    {
        return newSample;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filterBuffer[i];
    }

    return sum / count;
}

static SensorStatus_t EvaluateSensorStatus(float voltage)
{
    if (voltage < 0.0f || voltage > ADC_REF_VOLTAGE)
    {
        return SENSOR_STATUS_FAULT;
    }
    else if (voltage < SENSOR_LOW_THRESHOLD_V)
    {
        return SENSOR_STATUS_LOW;
    }
    else if (voltage > SENSOR_HIGH_THRESHOLD_V)
    {
        return SENSOR_STATUS_HIGH;
    }
    else
    {
        return SENSOR_STATUS_OK;
    }
}

