 * Sensor task
 *=========================================================*/
static void Sensor_ReadAndProcess(void)
{
    uint16_t raw = ADC_ReadChannel(0);
    float voltage = ADC_CountsToVoltage(raw);
    float filtered = MovingAverageFilter(voltage);
    SensorStatus_t status = EvaluateSensorStatus(filtered);

    g_sensorData.raw = raw;
    g_sensorData.voltage = voltage;
    g_sensorData.filteredVoltage = filtered;
    g_sensorData.status = status;
}

