#include "sensor.h"

#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f
#define FILTER_WINDOW_SIZE      8
#define SENSOR_LOW_THRESHOLD_V  0.5f
#define SENSOR_HIGH_THRESHOLD_V 2.8f

extern uint16_t ADC_ReadChannel(uint8_t channel);

static SensorData_t sensorData;
static float filterBuffer[FILTER_WINDOW_SIZE];
static uint8_t filterIndex = 0;
static uint8_t filterCount = 0;

static float counts_to_voltage(uint16_t counts)
{
    return ((float)counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float moving_average(float sample)
{
    filterBuffer[filterIndex] = sample;
    filterIndex = (filterIndex + 1) % FILTER_WINDOW_SIZE;

    if (filterCount < FILTER_WINDOW_SIZE)
    {
        filterCount++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < filterCount; i++)
    {
        sum += filterBuffer[i];
    }

    return sum / filterCount;
}

static SensorStatus_t evaluate_status(float voltage)
{
    if (voltage < SENSOR_LOW_THRESHOLD_V)
        return SENSOR_STATUS_LOW;
    if (voltage > SENSOR_HIGH_THRESHOLD_V)
        return SENSOR_STATUS_HIGH;
    return SENSOR_STATUS_OK;
}

void Sensor_Init(void)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filterBuffer[i] = 0.0f;
    }

    sensorData.raw = 0;
    sensorData.voltage = 0.0f;
    sensorData.filteredVoltage = 0.0f;
    sensorData.status = SENSOR_STATUS_FAULT;
}

void Sensor_Update(void)
{
    sensorData.raw = ADC_ReadChannel(0);
    sensorData.voltage = counts_to_voltage(sensorData.raw);
    sensorData.filteredVoltage = moving_average(sensorData.voltage);
    sensorData.status = evaluate_status(sensorData.filteredVoltage);
}

SensorData_t Sensor_GetData(void)
{
    return sensorData;
}
