// Simple complementary fusion:
// - wheel encoders for linear velocity
// - gyro for angular velocity
// -----------------------------
class SensorFusion {
public:
    SensorFusion(double wheel_radius, double wheel_base, int ticks_per_rev)
        : wheel_radius_(wheel_radius),
          wheel_base_(wheel_base),
          ticks_per_rev_(ticks_per_rev) {}

    RobotState update(const IMUData& imu, const EncoderData& enc, double dt) {
        if (!initialized_) {
            prev_left_ticks_ = enc.left_ticks;
            prev_right_ticks_ = enc.right_ticks;
            initialized_ = true;
            return state_;
        }

        int64_t dleft_ticks = enc.left_ticks - prev_left_ticks_;
        int64_t dright_ticks = enc.right_ticks - prev_right_ticks_;

        prev_left_ticks_ = enc.left_ticks;
        prev_right_ticks_ = enc.right_ticks;

        double left_dist = ticksToMeters(dleft_ticks);
        double right_dist = ticksToMeters(dright_ticks);

        double left_vel = (dt > 1e-6) ? left_dist / dt : 0.0;
        double right_vel = (dt > 1e-6) ? right_dist / dt : 0.0;

        double linear_vel_enc = 0.5 * (left_vel + right_vel);
        double angular_vel_enc = (right_vel - left_vel) / wheel_base_;

        double angular_vel = imu.valid
            ? alpha_ * imu.gyro_z_rad_s + (1.0 - alpha_) * angular_vel_enc
            : angular_vel_enc;

        state_.linear_vel = linear_vel_enc;
        state_.angular_vel = angular_vel;
        state_.left_wheel_vel = left_vel;
        state_.right_wheel_vel = right_vel;

        state_.theta += angular_vel * dt;
        state_.x += state_.linear_vel * std::cos(state_.theta) * dt;
        state_.y += state_.linear_vel * std::sin(state_.theta) * dt;

        return state_;
    }

private:
    double wheel_radius_;
    double wheel_base_;
    int ticks_per_rev_;
    double alpha_ = 0.98;

    bool initialized_ = false;
    int64_t prev_left_ticks_ = 0;
    int64_t prev_right_ticks_ = 0;
    RobotState state_;

    double ticksToMeters(int64_t ticks) const {
        double revs = static_cast<double>(ticks) / static_cast<double>(ticks_per_rev_);
        return revs * 2.0 * M_PI * wheel_radius_;
    }
};

// -----------------------------
// Robot controller
// -----------------------------
class RobotController {
public:
    RobotController()
        : fusion_(0.05, 0.30, 2048),
          left_pid_(2.0, 0.5, 0.01, -1.0, 1.0),
          right_pid_(2.0, 0.5, 0.01, -1.0, 1.0) {}

    void setCommand(double linear_mps, double angular_rps) {
        std::lock_guard<std::mutex> lock(cmd_mutex_);
        cmd_.linear_mps = linear_mps;
        cmd_.angular_rps = angular_rps;
        cmd_.timestamp = Clock::now();
    }

    void run() {
        constexpr double control_hz = 100.0;
        constexpr double dt_target = 1.0 / control_hz;
        constexpr auto cmd_timeout = std::chrono::milliseconds(500);

        auto last = Clock::now();

        while (running_) {
            auto now = Clock::now();
            std::chrono::duration<double> elapsed = now - last;
            double dt = elapsed.count();

            if (dt < dt_target) {
                std::this_thread::sleep_for(std::chrono::duration<double>(dt_target - dt));
                continue;
            }

            last = now;

            IMUData imu = imu_.read();
            EncoderData enc = encoders_.read();

            RobotState state = fusion_.update(imu, enc, dt);

            VelocityCommand cmd;
            {
                std::lock_guard<std::mutex> lock(cmd_mutex_);
                cmd = cmd_;
            }

            bool stale = (now - cmd.timestamp) > cmd_timeout;
            if (stale) {
                cmd.linear_mps = 0.0;
                cmd.angular_rps = 0.0;
            }

            double left_target =
                cmd.linear_mps - 0.5 * cmd.angular_rps * wheel_base_;
            double right_target =
                cmd.linear_mps + 0.5 * cmd.angular_rps * wheel_base_;

            double left_pwm = left_pid_.update(left_target, state.left_wheel_vel, dt);
            double right_pwm = right_pid_.update(right_target, state.right_wheel_vel, dt);

            if (!imu.valid || !enc.valid) {
                motor_.stop();
                left_pid_.reset();
                right_pid_.reset();
                continue;
            }

            motor_.setPWM(left_pwm, right_pwm);

            std::cout
                << "Pose: (" << state.x << ", " << state.y << ", " << state.theta << ") "
                << "Vel: " << state.linear_vel << " m/s, " << state.angular_vel << " rad/s\n";
        }

        motor_.stop();
    }

    void stop() {
        running_ = false;
    }

private:
    IMU imu_;
    Encoders encoders_;
    MotorDriver motor_;
    SensorFusion fusion_;

    PID left_pid_;
    PID right_pid_;

    std::atomic<bool> running_{true};
    std::mutex cmd_mutex_;
    VelocityCommand cmd_;

    const double wheel_base_ = 0.30;
};

// -----------------------------
// Main
// -----------------------------
int main() {
    RobotController robot;

    std::thread control_thread([&robot]() {
        robot.run();
    });

    robot.setCommand(0.5, 0.0);
    std::this_thread::sleep_for(std::chrono::seconds(2));

    robot.setCommand(0.3, 0.8);
    std::this_thread::sleep_for(std::chrono::seconds(2));

    robot.setCommand(0.0, 0.0);
    std::this_thread::sleep_for(std::chrono::seconds(1));

    robot.stop();
    control_thread.join();

    return 0;
}
```

Notes:
- This is a structural example, not hard real-time certified code.
- For actual real-time systems:
  - use a monotonic clock
  - avoid dynamic allocation in the loop
  - avoid console I/O in the loop
  - use RT-safe queues/shared memory
  - pin thread priority/CPU if needed
  - add watchdogs, saturation handling, anti-windup, and fault states
- For better fusion, use:
  - EKF/UKF
  - Madgwick/Mahony filter for IMU orientation
  - robot_localization in ROS 2

