## Example: Real-time robotics control loop in C++

```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <atomic>
#include <mutex>

using Clock = std::chrono::steady_clock;

// -----------------------------
// Utility types
// -----------------------------
struct IMUData {
    double accel_x = 0.0;
    double accel_y = 0.0;
    double accel_z = 1.0;

    double gyro_x = 0.0; // rad/s
    double gyro_y = 0.0;
    double gyro_z = 0.0;
};

struct EncoderData {
    double left_velocity = 0.0;   // rad/s
    double right_velocity = 0.0;  // rad/s
};

struct RobotState {
    double pitch = 0.0;           // radians
    double pitch_rate = 0.0;      // rad/s
    double left_velocity = 0.0;   // rad/s
    double right_velocity = 0.0;  // rad/s
};

struct MotorCommand {
    double left_torque = 0.0;
    double right_torque = 0.0;
};

// -----------------------------
// Mock hardware interfaces
// Replace these with real drivers
// -----------------------------
class IMUSensor {
public:
    IMUData read() {
        IMUData data;
        // Simulated stationary robot with slight noise
        data.accel_x = 0.02;
        data.accel_y = 0.0;
        data.accel_z = 0.999;
        data.gyro_y = 0.01;
        return data;
    }
};

class EncoderSensor {
public:
    EncoderData read() {
        EncoderData data;
        data.left_velocity = 1.2;
        data.right_velocity = 1.18;
        return data;
    }
};

class MotorDriver {
public:
    void write(const MotorCommand& cmd) {
        // Replace with PWM/CAN/UART/etc.
        std::cout << "Motor cmd | Left: " << cmd.left_torque
                  << " Right: " << cmd.right_torque << "\n";
    }
};

// -----------------------------
// Complementary filter for pitch
// -----------------------------
class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha = 0.98)
        : alpha_(alpha), pitch_estimate_(0.0) {}

    double update(const IMUData& imu, double dt) {
        // Pitch from accelerometer
        double accel_pitch = std::atan2(-imu.accel_x,
                                        std::sqrt(imu.accel_y * imu.accel_y +
                                                  imu.accel_z * imu.accel_z));

        // Integrate gyro Y for pitch estimate
        double gyro_pitch = pitch_estimate_ + imu.gyro_y * dt;

        // Blend gyro and accel
        pitch_estimate_ = alpha_ * gyro_pitch + (1.0 - alpha_) * accel_pitch;
        return pitch_estimate_;
    }

private:
    double alpha_;
    double pitch_estimate_;
};

// -----------------------------
// PID controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double min_out, double max_out)
        : kp_(kp), ki_(ki), kd_(kd),
          min_out_(min_out), max_out_(max_out) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        integral_ += error * dt;
        double derivative = (dt > 0.0) ? (error - prev_error_) / dt : 0.0;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;

        // Clamp output
        if (output > max_out_) output = max_out_;
        if (output < min_out_) output = min_out_;

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_;
    double ki_;
    double kd_;
    double min_out_;
    double max_out_;

    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

// -----------------------------
// Robot controller
// Example: balance pitch + regulate wheel speed
// -----------------------------
class RobotController {
public:
    RobotController()
        : balance_pid_(25.0, 0.5, 1.5, -10.0, 10.0),
          velocity_pid_(2.0, 0.1, 0.2, -2.0, 2.0) {}

    MotorCommand compute(const RobotState& state, double target_velocity, double dt) {
        MotorCommand cmd;

        double avg_velocity = 0.5 * (state.left_velocity + state.right_velocity);

        // Outer loop: velocity controller generates desired pitch
        double desired_pitch = velocity_pid_.update(target_velocity, avg_velocity, dt);

        // Inner loop: balance controller generates torque
        double torque = balance_pid_.update(desired_pitch, state.pitch, dt);

        cmd.left_torque = torque;
        cmd.right_torque = torque;
        return cmd;
    }

private:
    PID balance_pid_;
    PID velocity_pid_;
};

// -----------------------------
// Main control loop
// -----------------------------
int main() {
    IMUSensor imu_sensor;
    EncoderSensor encoder_sensor;
    MotorDriver motor_driver;

    ComplementaryFilter filter(0.98);
    RobotController controller;

    constexpr double control_frequency_hz = 200.0;
    constexpr double dt = 1.0 / control_frequency_hz;
    const auto period = std::chrono::duration<double>(dt);

    double target_velocity = 1.0; // rad/s

    auto next_time = Clock::now();

    std::cout << "Starting control loop at " << control_frequency_hz << " Hz\n";

    while (true) {
        next_time += std::chrono::duration_cast<Clock::duration>(period);

        // 1. Read sensors
        IMUData imu = imu_sensor.read();
        EncoderData enc = encoder_sensor.read();

        // 2. Sensor fusion / state estimation
        RobotState state;
        state.pitch = filter.update(imu, dt);
        state.pitch_rate = imu.gyro_y;
        state.left_velocity = enc.left_velocity;
        state.right_velocity = enc.right_velocity;

        // 3. Compute control
        MotorCommand cmd = controller.compute(state, target_velocity, dt);

        // 4. Send actuator commands
        motor_driver.write(cmd);

        // 5. Sleep until next cycle
        std::this_thread::sleep_until(next_time);
    }

    return 0;
}
```

