## Safer PID with anti-windup

Here is a better PID implementation:

```cpp
class PID {
public:
    PID(double kp, double ki, double kd, double min_out, double max_out)
        : kp_(kp), ki_(ki), kd_(kd),
          min_out_(min_out), max_out_(max_out) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        double derivative = (dt > 0.0) ? (error - prev_error_) / dt : 0.0;

        double new_integral = integral_ + error * dt;
        double output = kp_ * error + ki_ * new_integral + kd_ * derivative;

        if (output <= max_out_ && output >= min_out_) {
            integral_ = new_integral;
        }

        output = kp_ * error + ki_ * integral_ + kd_ * derivative;

        if (output > max_out_) output = max_out_;
        if (output < min_out_) output = min_out_;

        prev_error_ = error;
        return output;
    }

private:
    double kp_, ki_, kd_;
    double min_out_, max_out_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};
```

