```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>
#include <cmath>
#include <algorithm>

using Clock = std::chrono::steady_clock;

// -----------------------------
// Utility
// -----------------------------
template <typename T>
T clamp(T v, T lo, T hi) {
    return std::max(lo, std::min(v, hi));
}

// -----------------------------
// Sensor Data Structures
// -----------------------------
struct IMUData {
    double gyro_z = 0.0;   // rad/s
    double accel_x = 0.0;  // m/s^2
    double accel_y = 0.0;  // m/s^2
    double accel_z = 9.81; // m/s^2
    Clock::time_point timestamp = Clock::now();
};

struct EncoderData {
    double left_velocity = 0.0;   // m/s
    double right_velocity = 0.0;  // m/s
    double left_position = 0.0;   // m
    double right_position = 0.0;  // m
    Clock::time_point timestamp = Clock::now();
};

struct RobotState {
    double x = 0.0;
    double y = 0.0;
    double theta = 0.0;       // heading, rad
    double linear_vel = 0.0;  // m/s
    double angular_vel = 0.0; // rad/s
};

// -----------------------------
// Thread-safe Sensor Interface
// -----------------------------
class SensorManager {
public:
    void updateIMU(const IMUData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        imu_ = data;
    }

    void updateEncoder(const EncoderData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        encoder_ = data;
    }

    IMUData getIMU() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return imu_;
    }

    EncoderData getEncoder() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return encoder_;
    }

private:
    mutable std::mutex mutex_;
    IMUData imu_;
    EncoderData encoder_;
};

// -----------------------------
// PID Controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double min_out, double max_out)
        : kp_(kp), ki_(ki), kd_(kd), min_out_(min_out), max_out_(max_out) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (dt > 1e-6) ? (error - prev_error_) / dt : 0.0;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, min_out_, max_out_);

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double min_out_, max_out_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

// -----------------------------
// Sensor Fusion
// -----------------------------
class SensorFusion {
public:
    SensorFusion(double wheel_base, double alpha = 0.98)
        : wheel_base_(wheel_base), alpha_(alpha) {}

    RobotState update(const IMUData& imu, const EncoderData& enc, double dt) {
        // Encoder-based velocities
        double linear_vel = 0.5 * (enc.left_velocity + enc.right_velocity);
        double angular_vel_enc = (enc.right_velocity - enc.left_velocity) / wheel_base_;

        // Gyro integration
        double theta_gyro = state_.theta + imu.gyro_z * dt;

        // Complementary fusion of angular velocity estimate
        double angular_vel = alpha_ * imu.gyro_z + (1.0 - alpha_) * angular_vel_enc;

        // Blend heading estimate
        state_.theta = alpha_ * theta_gyro + (1.0 - alpha_) * (state_.theta + angular_vel_enc * dt);

        // Normalize angle
        while (state_.theta > M_PI) state_.theta -= 2.0 * M_PI;
        while (state_.theta < -M_PI) state_.theta += 2.0 * M_PI;

        state_.linear_vel = linear_vel;
        state_.angular_vel = angular_vel;

        // Dead reckoning position update
        state_.x += linear_vel * std::cos(state_.theta) * dt;
        state_.y += linear_vel * std::sin(state_.theta) * dt;

        return state_;
    }

private:
    double wheel_base_;
    double alpha_;
    RobotState state_;
};

// -----------------------------
// Motor Driver Interface
// -----------------------------
class MotorDriver {
public:
    void setMotorCommands(double left_cmd, double right_cmd) {
        left_cmd = clamp(left_cmd, -1.0, 1.0);
        right_cmd = clamp(right_cmd, -1.0, 1.0);

        // Replace with actual hardware API
        std::cout << "Motor commands -> Left: " << left_cmd
                  << ", Right: " << right_cmd << "\n";
    }
};

// -----------------------------
// Robot Controller
// -----------------------------
class RobotController {
public:
    RobotController(SensorManager& sensors, MotorDriver& motors, double wheel_base)
        : sensors_(sensors),
          motors_(motors),
          fusion_(wheel_base),
          left_pid_(2.0, 0.5, 0.1, -1.0, 1.0),
          right_pid_(2.0, 0.5, 0.1, -1.0, 1.0),
          wheel_base_(wheel_base) {}

    void setTarget(double linear, double angular) {
        target_linear_ = linear;
        target_angular_ = angular;
    }

    void run(std::atomic<bool>& running) {
        constexpr double loop_hz = 100.0;
        constexpr double dt_target = 1.0 / loop_hz;

        auto last = Clock::now();

        while (running.load()) {
            auto now = Clock::now();
            std::chrono::duration<double> elapsed = now - last;
            double dt = elapsed.count();

            if (dt < dt_target) {
                std::this_thread::sleep_for(std::chrono::duration<double>(dt_target - dt));
                continue;
            }

            last = now;

            IMUData imu = sensors_.getIMU();
            EncoderData enc = sensors_.getEncoder();

            RobotState state = fusion_.update(imu, enc, dt);

            // Convert target linear/angular velocity to wheel velocities
            double target_left_vel = target_linear_ - 0.5 * wheel_base_ * target_angular_;
            double target_right_vel = target_linear_ + 0.5 * wheel_base_ * target_angular_;

            // PID wheel control
            double left_cmd = left_pid_.update(target_left_vel, enc.left_velocity, dt);
            double right_cmd = right_pid_.update(target_right_vel, enc.right_velocity, dt);

            motors_.setMotorCommands(left_cmd, right_cmd);

            // Debug output
            std::cout << "State -> x: " << state.x
                      << ", y: " << state.y
                      << ", theta: " << state.theta
                      << ", v: " << state.linear_vel
                      << ", w: " << state.angular_vel << "\n";
        }

        motors_.setMotorCommands(0.0, 0.0);
    }

private:
    SensorManager& sensors_;
    MotorDriver& motors_;
    SensorFusion fusion_;
    PID left_pid_;
    PID right_pid_;
    double wheel_base_;

    double target_linear_ = 0.5;  // m/s
    double target_angular_ = 0.0; // rad/s
};

// -----------------------------
// Simulated Sensor Threads
// -----------------------------
void imuThread(SensorManager& sensors, std::atomic<bool>& running) {
    double t = 0.0;
    while (running.load()) {
        IMUData imu;
        imu.gyro_z = 0.1 * std::sin(t);
        imu.accel_x = 0.0;
        imu.accel_y = 0.0;
        imu.accel_z = 9.81;
        imu.timestamp = Clock::now();

        sensors.updateIMU(imu);

        std::this_thread::sleep_for(std::chrono::milliseconds(5)); // 200 Hz
        t += 0.005;
    }
}

void encoderThread(SensorManager& sensors, std::atomic<bool>& running) {
    double left_pos = 0.0, right_pos = 0.0;
    while (running.load()) {
        EncoderData enc;
        enc.left_velocity = 0.48;
        enc.right_velocity = 0.52;
        left_pos += enc.left_velocity * 0.01;
        right_pos += enc.right_velocity * 0.01;
        enc.left_position = left_pos;
        enc.right_position = right_pos;
        enc.timestamp = Clock::now();

        sensors.updateEncoder(enc);

        std::this_thread::sleep_for(std::chrono::milliseconds(10)); // 100 Hz
    }
}

// -----------------------------
// Main
// -----------------------------
int main() {
    SensorManager sensors;
    MotorDriver motors;
    RobotController controller(sensors, motors, 0.4);

    std::atomic<bool> running(true);

    std::thread imu_worker(imuThread, std::ref(sensors), std::ref(running));
    std::thread encoder_worker(encoderThread, std::ref(sensors), std::ref(running));
    std::thread control_worker(&RobotController::run, &controller, std::ref(running));

    std::this_thread::sleep_for(std::chrono::seconds(5));
    running.store(false);

    imu_worker.join();
    encoder_worker.join();
    control_worker.join();

    return 0;
}
```

