Below is a compact but realistic example of a robotics control loop in **C++** that demonstrates:

- a fixed-rate real-time style loop
- IMU + wheel encoder sensor fusion
- a simple complementary filter for orientation
- PID motor speed control
- clean separation between sensing, estimation, and actuation

This is a template, not hardware-specific production code.

```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

using Clock = std::chrono::steady_clock;

// -----------------------------
// Utility
// -----------------------------
template <typename T>
T clamp(T v, T lo, T hi) {
    return std::max(lo, std::min(v, hi));
}

// -----------------------------
// Sensor data structures
// -----------------------------
struct IMUData {
    double accel_x;   // m/s^2
    double accel_y;   // m/s^2
    double gyro_z;    // rad/s
};

struct EncoderData {
    double left_velocity;   // m/s
    double right_velocity;  // m/s
};

struct RobotState {
    double x = 0.0;         // m
    double y = 0.0;         // m
    double theta = 0.0;     // rad
    double linear_vel = 0.0;
    double angular_vel = 0.0;
};

// -----------------------------
// Mock hardware interfaces
// Replace with real drivers
// -----------------------------
class IMU {
public:
    IMUData read() {
        // Simulated IMU data
        return {0.0, 0.0, 0.01};
    }
};

class Encoders {
public:
    EncoderData read() {
        // Simulated encoder velocities
        return {0.5, 0.52};
    }
};

class MotorDriver {
public:
    void setMotorCommands(double left_cmd, double right_cmd) {
        // Replace with PWM / CAN / serial motor output
        std::cout << "Motor L: " << left_cmd << " R: " << right_cmd << "\n";
    }
};

// -----------------------------
// PID Controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double out_min, double out_max)
        : kp_(kp), ki_(ki), kd_(kd), out_min_(out_min), out_max_(out_max) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (dt > 0.0) ? (error - prev_error_) / dt : 0.0;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, out_min_, out_max_);

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double out_min_, out_max_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

// -----------------------------
// Sensor Fusion / State Estimator
// Differential drive + complementary heading fusion
// -----------------------------
class StateEstimator {
public:
    StateEstimator(double wheel_base, double alpha)
        : wheel_base_(wheel_base), alpha_(alpha) {}

    void update(const IMUData& imu, const EncoderData& enc, double dt) {
        // Wheel odometry
        double v = 0.5 * (enc.left_velocity + enc.right_velocity);
        double omega_enc = (enc.right_velocity - enc.left_velocity) / wheel_base_;

        // Fuse angular velocity from gyro and encoders
        double omega_fused = alpha_ * imu.gyro_z + (1.0 - alpha_) * omega_enc;

        state_.angular_vel = omega_fused;
        state_.linear_vel = v;

        // Integrate heading
        state_.theta += omega_fused * dt;

        // Normalize theta to [-pi, pi]
        while (state_.theta > M_PI) state_.theta -= 2.0 * M_PI;
        while (state_.theta < -M_PI) state_.theta += 2.0 * M_PI;

        // Integrate position
        state_.x += v * std::cos(state_.theta) * dt;
        state_.y += v * std::sin(state_.theta) * dt;
    }

    const RobotState& getState() const {
        return state_;
    }

private:
    double wheel_base_;
    double alpha_; // gyro trust factor
    RobotState state_;
};

// -----------------------------
// Main control loop
// -----------------------------
int main() {
    IMU imu;
    Encoders encoders;
    MotorDriver motors;

    StateEstimator estimator(0.30, 0.98); // wheel base 30 cm, high gyro trust

    PID left_pid(2.0, 0.5, 0.1, -1.0, 1.0);
    PID right_pid(2.0, 0.5, 0.1, -1.0, 1.0);

    // Desired robot command
    double target_linear = 0.6;   // m/s
    double target_angular = 0.1;  // rad/s

    const double wheel_base = 0.30;
    const double loop_hz = 100.0;
    const auto loop_period = std::chrono::microseconds(
        static_cast<int>(1e6 / loop_hz));

    auto next_time = Clock::now();

    while (true) {
        auto start = Clock::now();

        // 1. Read sensors
        IMUData imu_data = imu.read();
        EncoderData enc_data = encoders.read();

        // 2. Compute dt
        static auto last_time = start;
        std::chrono::duration<double> elapsed = start - last_time;
        double dt = elapsed.count();
        last_time = start;

        if (dt <= 0.0) dt = 1.0 / loop_hz;

        // 3. Sensor fusion / state estimation
        estimator.update(imu_data, enc_data, dt);
        const RobotState& state = estimator.getState();

        // 4. Convert desired robot velocity to wheel targets
        double left_target = target_linear - 0.5 * target_angular * wheel_base;
        double right_target = target_linear + 0.5 * target_angular * wheel_base;

        // 5. Motor control using wheel velocity feedback
        double left_cmd = left_pid.update(left_target, enc_data.left_velocity, dt);
        double right_cmd = right_pid.update(right_target, enc_data.right_velocity, dt);

        // 6. Send commands to motors
        motors.setMotorCommands(left_cmd, right_cmd);

        // 7. Debug / telemetry
        std::cout
            << "State x=" << state.x
            << " y=" << state.y
            << " theta=" << state.theta
            << " v=" << state.linear_vel
            << " w=" << state.angular_vel
            << "\n";

        // 8. Maintain loop timing
        next_time += loop_period;
        std::this_thread::sleep_until(next_time);
    }

    return 0;
}
