Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Moving average energy estimate
- Adaptive thresholding
- Anomaly debounce / persistence logic

This is designed to be lightweight, streaming, and allocation-free.

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>

#ifndef ABS
#define ABS(x) ((x) < 0 ? -(x) : (x))
#endif

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

/*
 * Fixed-point embedded anomaly detector for accelerometer data.
 *
 * Pipeline:
 *   1. Compute approximate magnitude from x,y,z
 *   2. Low-pass filter to estimate baseline
 *   3. High-pass residual = |mag - baseline|
 *   4. Smooth residual into short-term energy
 *   5. Track long-term noise floor
 *   6. Trigger anomaly if energy exceeds adaptive threshold
 *
 * Notes:
 * - All arithmetic is integer/fixed-point.
 * - Shift-based filters are used for efficiency.
 * - Tunable parameters are exposed in the struct.
 */

typedef struct {
    // Filter states
    int32_t baseline;       // low-pass estimate of magnitude
    int32_t energy;         // short-term smoothed residual
    int32_t noise_floor;    // long-term smoothed energy

    // Detection state
    uint16_t over_count;    // consecutive samples over threshold
    uint16_t cooldown;      // suppress repeated triggers
    bool anomaly;

    // Tunable parameters
    uint8_t baseline_shift; // larger => slower baseline update
    uint8_t energy_shift;   // larger => slower energy smoothing
    uint8_t noise_shift;    // larger => slower noise floor tracking

    int32_t threshold_offset;   // minimum threshold above noise floor
    int32_t threshold_scale;    // multiplier on noise floor
    uint16_t trigger_count;     // samples required to trigger
    uint16_t cooldown_samples;  // refractory period after trigger
} AnomalyDetector;

static inline void anomaly_detector_init(AnomalyDetector *d)
{
    d->baseline = 0;
    d->energy = 0;
    d->noise_floor = 0;

    d->over_count = 0;
    d->cooldown = 0;
    d->anomaly = false;

    // Reasonable defaults for ~100-200 Hz sample rate
    d->baseline_shift = 5;      // LPF alpha ~= 1/32
    d->energy_shift = 3;        // LPF alpha ~= 1/8
    d->noise_shift = 6;         // LPF alpha ~= 1/64

    d->threshold_offset = 50;   // depends on accelerometer scaling
    d->threshold_scale = 3;     // threshold = offset + scale * noise_floor
    d->trigger_count = 3;       // require persistence
    d->cooldown_samples = 20;   // suppress repeated alerts
}

/*
 * Fast approximate vector magnitude.
 *
 * Instead of sqrt(x^2 + y^2 + z^2), use:
 *   max + 1/2 mid + 1/4 min
 *
 * This is much cheaper and often good enough for anomaly detection.
 */
static inline int32_t approx_magnitude(int16_t x, int16_t y, int16_t z)
{
    int32_t ax = ABS((int32_t)x);
    int32_t ay = ABS((int32_t)y);
    int32_t az = ABS((int32_t)z);

    int32_t max = ax, mid = ay, min = az;

    // Sort descending: max >= mid >= min
    if (max < mid) { int32_t t = max; max = mid; mid = t; }
    if (mid < min) { int32_t t = mid; mid = min; min = t; }
    if (max < mid) { int32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

/*
 * Process one sample.
 *
 * Returns true only on the sample where a new anomaly is declared.
 * Continuous anomaly state is also available in d->anomaly.
 */
static inline bool anomaly_detector_process(AnomalyDetector *d, AccelSample s)
{
    // 1. Magnitude approximation
    int32_t mag = approx_magnitude(s.x, s.y, s.z);

    // Initialize baseline on first sample to avoid startup spike
    if (d->baseline == 0) {
        d->baseline = mag;
        d->noise_floor = 0;
        d->energy = 0;
    }

    // 2. Low-pass baseline tracking
    d->baseline += (mag - d->baseline) >> d->baseline_shift;

    // 3. High-pass residual
    int32_t residual = ABS(mag - d->baseline);

    // 4. Short-term energy smoothing
    d->energy += (residual - d->energy) >> d->energy_shift;

    // 5. Long-term noise floor tracking
    d->noise_floor += (d->energy - d->noise_floor) >> d->noise_shift;

    // Adaptive threshold
    int32_t threshold = d->threshold_offset + d->threshold_scale * d->noise_floor;

    bool triggered = false;
    d->anomaly = false;

    if (d->cooldown > 0) {
        d->cooldown--;
        d->over_count = 0;
        return false;
    }

    // 6. Persistence logic
    if (d->energy > threshold) {
        if (d->over_count < 0xFFFF) {
            d->over_count++;
        }

        if (d->over_count >= d->trigger_count) {
            d->anomaly = true;
            triggered = true;
            d->cooldown = d->cooldown_samples;
            d->over_count = 0;
        }
    } else {
        d->over_count = 0;
    }

    return triggered;
}
