Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling noise estimate
- Threshold-based anomaly detection
- Debounce / persistence logic
- Fixed-point integer math only

You can adapt it to Arduino, STM32, ESP32, or bare-metal systems.

---

## Design

Pipeline per sample:

1. Read accelerometer `(x, y, z)`
2. Compute motion magnitude
3. Estimate slow baseline with IIR low-pass
4. Compute deviation from baseline
5. Track normal noise level
6. Trigger anomaly if deviation exceeds adaptive threshold for several samples

This is lightweight and robust for vibration spikes, impacts, or unusual motion.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Baseline magnitude estimate
    int32_t baseline;

    // Noise estimate of residual
    int32_t noise;

    // Last residual
    int32_t residual;

    // Detection state
    uint16_t anomaly_count;
    bool anomaly_active;

    // Configuration
    uint8_t baseline_shift;     // low-pass strength: larger = slower
    uint8_t noise_shift;        // noise adaptation speed
    uint16_t threshold_mult;    // threshold = noise * threshold_mult / 256
    int32_t min_threshold;      // absolute minimum threshold
    uint16_t trigger_count;     // consecutive samples to trigger
    uint16_t release_count;     // consecutive normal samples to clear

    uint16_t normal_count;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t baseline;
    int32_t residual;
    int32_t threshold;
    int32_t noise;
} DetectionResult;

/*
 * Fast approximate magnitude:
 * |x| + |y| + |z|
 * Cheaper than sqrt(x^2 + y^2 + z^2), often good enough for anomaly detection.
 */
static inline int32_t accel_magnitude_l1(const AccelSample *s) {
    return abs(s->x) + abs(s->y) + abs(s->z);
}

/*
 * Initialize detector with reasonable defaults.
 */
void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->noise = 0;
    det->residual = 0;
    det->anomaly_count = 0;
    det->normal_count = 0;
    det->anomaly_active = false;

    // Tunable parameters
    det->baseline_shift = 5;      // ~1/32 update rate
    det->noise_shift = 6;         // ~1/64 update rate
    det->threshold_mult = 768;    // 3.0x noise (768/256)
    det->min_threshold = 200;     // minimum residual threshold
    det->trigger_count = 3;       // require 3 consecutive anomalous samples
    det->release_count = 5;       // require 5 normal samples to clear
}

/*
 * Optional warm start using first sample.
 */
void anomaly_detector_seed(AnomalyDetector *det, const AccelSample *s) {
    int32_t mag = accel_magnitude_l1(s);
    det->baseline = mag;
    det->noise = 0;
    det->residual = 0;
}

/*
 * Process one accelerometer sample.
 */
DetectionResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *s) {
    DetectionResult out = {0};

    int32_t mag = accel_magnitude_l1(s);

    // Update baseline with IIR low-pass:
    // baseline += (mag - baseline) / 2^baseline_shift
    det->baseline += (mag - det->baseline) >> det->baseline_shift;

    // High-pass residual
    int32_t residual = mag - det->baseline;
    int32_t abs_residual = abs(residual);

    // Update noise estimate from absolute residual
    det->noise += (abs_residual - det->noise) >> det->noise_shift;

    // Adaptive threshold
    int32_t threshold = (det->noise * det->threshold_mult) >> 8;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    // Detection logic with persistence
    if (abs_residual > threshold) {
        if (det->anomaly_count < 65535) {
            det->anomaly_count++;
        }
        det->normal_count = 0;

        if (det->anomaly_count >= det->trigger_count) {
            det->anomaly_active = true;
        }
    } else {
        det->anomaly_count = 0;

        if (det->normal_count < 65535) {
            det->normal_count++;
        }

        if (det->normal_count >= det->release_count) {
            det->anomaly_active = false;
        }
    }

    det->residual = residual;

    out.anomaly = det->anomaly_active;
    out.magnitude = mag;
    out.baseline = det->baseline;
    out.residual = residual;
    out.threshold = threshold;
    out.noise = det->noise;

    return out;
}
```

