## More Advanced Version: Rolling Mean and Variance

If you want a z-score style detector, here is a simple window-based approach using a ring buffer.

```c
#include <string.h>

#define WINDOW_SIZE 32

typedef struct {
    int32_t buf[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int64_t sum;
    int64_t sumsq;
} RollingStats;

void rolling_stats_init(RollingStats *rs) {
    memset(rs, 0, sizeof(*rs));
}

void rolling_stats_update(RollingStats *rs, int32_t x) {
    if (rs->count < WINDOW_SIZE) {
        rs->buf[rs->index] = x;
        rs->sum += x;
        rs->sumsq += (int64_t)x * x;
        rs->count++;
    } else {
        int32_t old = rs->buf[rs->index];
        rs->buf[rs->index] = x;
        rs->sum += x - old;
        rs->sumsq += (int64_t)x * x - (int64_t)old * old;
    }

    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

bool rolling_stats_anomaly(const RollingStats *rs, int32_t x, int32_t z_thresh_q8) {
    if (rs->count < 8) {
        return false;
    }

    int64_t mean = rs->sum / rs->count;
    int64_t var = (rs->sumsq / rs->count) - (mean * mean);
    if (var < 1) {
        var = 1;
    }

    int64_t diff = x - mean;
    int64_t diff2 = diff * diff;

    // Compare diff^2 / var > z^2 without sqrt
    // z_thresh_q8 is z threshold in Q8 fixed-point
    int64_t z2_scaled = ((int64_t)z_thresh_q8 * z_thresh_q8) >> 8;
    return (diff2 << 8) > (z2_scaled * var);
}
```

This is more statistical, but the first IIR-based detector is usually better for tiny embedded systems.

