Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling mean absolute deviation estimate
- Threshold-based anomaly detection with cooldown
- Fixed-point / integer-friendly style

You can adapt it to Arduino, STM32, ESP32, or bare-metal firmware.

---

## Design

Pipeline per sample:

1. Read accelerometer `(x, y, z)`
2. Compute signal magnitude
3. Smooth magnitude to estimate normal baseline
4. Compute deviation from baseline
5. Track average deviation
6. Trigger anomaly if deviation exceeds adaptive threshold

This is lightweight and avoids floating point if needed.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

// Detector configuration
typedef struct {
    uint8_t baseline_shift;     // low-pass smoothing: larger = slower baseline
    uint8_t noise_shift;        // smoothing for noise estimate
    uint16_t threshold_mult;    // threshold multiplier in Q8 format
    uint16_t min_threshold;     // minimum absolute threshold
    uint16_t cooldown_samples;  // refractory period after anomaly
} AnomalyConfig;

// Detector state
typedef struct {
    uint32_t baseline_mag;
    uint32_t noise_est;
    uint16_t cooldown;
    bool initialized;
} AnomalyState;

// Integer magnitude approximation: avoids sqrt
// Approx ~= max + 1/2 mid + 1/4 min
static uint32_t approx_magnitude(int16_t x, int16_t y, int16_t z) {
    uint32_t ax = (uint32_t)abs(x);
    uint32_t ay = (uint32_t)abs(y);
    uint32_t az = (uint32_t)abs(z);

    uint32_t maxv = ax, midv = ay, minv = az;

    // sort 3 values descending
    if (maxv < midv) { uint32_t t = maxv; maxv = midv; midv = t; }
    if (midv < minv) { uint32_t t = midv; midv = minv; minv = t; }
    if (maxv < midv) { uint32_t t = maxv; maxv = midv; midv = t; }

    return maxv + (midv >> 1) + (minv >> 2);
}

// Initialize detector state
void anomaly_init(AnomalyState *state) {
    state->baseline_mag = 0;
    state->noise_est = 0;
    state->cooldown = 0;
    state->initialized = false;
}

// Process one sample
// Returns true if anomaly detected
bool anomaly_process_sample(const AccelSample *sample,
                            const AnomalyConfig *cfg,
                            AnomalyState *state,
                            uint32_t *out_mag,
                            uint32_t *out_dev,
                            uint32_t *out_threshold) {
    uint32_t mag = approx_magnitude(sample->x, sample->y, sample->z);

    if (!state->initialized) {
        state->baseline_mag = mag;
        state->noise_est = 0;
        state->cooldown = 0;
        state->initialized = true;

        if (out_mag) *out_mag = mag;
        if (out_dev) *out_dev = 0;
        if (out_threshold) *out_threshold = cfg->min_threshold;
        return false;
    }

    // Low-pass baseline update:
    // baseline += (mag - baseline) / 2^baseline_shift
    int32_t baseline_err = (int32_t)mag - (int32_t)state->baseline_mag;
    state->baseline_mag += (baseline_err >> cfg->baseline_shift);

    // Absolute deviation from baseline
    uint32_t dev = (mag > state->baseline_mag)
        ? (mag - state->baseline_mag)
        : (state->baseline_mag - mag);

    // Smooth noise estimate using mean absolute deviation style
    int32_t noise_err = (int32_t)dev - (int32_t)state->noise_est;
    state->noise_est += (noise_err >> cfg->noise_shift);

    // Adaptive threshold:
    // threshold = max(min_threshold, noise_est * threshold_mult / 256)
    uint32_t adaptive = (state->noise_est * cfg->threshold_mult) >> 8;
    uint32_t threshold = (adaptive > cfg->min_threshold) ? adaptive : cfg->min_threshold;

    bool anomaly = false;

    if (state->cooldown > 0) {
        state->cooldown--;
    } else if (dev > threshold) {
        anomaly = true;
        state->cooldown = cfg->cooldown_samples;
    }

    if (out_mag) *out_mag = mag;
    if (out_dev) *out_dev = dev;
    if (out_threshold) *out_threshold = threshold;

    return anomaly;
}
```

