## Features

Pipeline stages:

1. **Read accelerometer sample** `(x, y, z)`
2. **Remove gravity / slow drift** using low-pass estimate subtraction
3. **Compute signal magnitude**
4. **Smooth magnitude** with exponential moving average
5. **Track baseline and noise level**
6. **Flag anomaly** when deviation exceeds adaptive threshold

This is lightweight and avoids floating-point-heavy operations if needed.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Assumptions:
 * - Input accelerometer units are in g or m/s^2, consistent across samples
 * - Sampling rate is fixed
 * - Call accel_pipeline_process() once per sample
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Low-pass estimate of gravity / DC component
    float lp_x;
    float lp_y;
    float lp_z;

    // Smoothed signal magnitude
    float mag_ema;

    // Adaptive baseline of magnitude
    float baseline_ema;

    // Adaptive variance estimate
    float var_ema;

    // Detection state
    bool anomaly_active;
    uint32_t anomaly_countdown;

    // Configuration
    float alpha_gravity;     // low-pass coefficient for gravity estimate
    float alpha_mag;         // smoothing coefficient for magnitude
    float alpha_baseline;    // baseline adaptation rate
    float alpha_var;         // variance adaptation rate
    float threshold_k;       // threshold multiplier
    float min_threshold;     // absolute minimum threshold
    uint32_t holdoff_samples;// cooldown after anomaly trigger
    float hysteresis_ratio;  // e.g. 0.7 for release threshold
} AccelPipeline;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;
    float magnitude;
    float baseline;
    float deviation;
    float threshold;
    bool anomaly;
} AccelPipelineOutput;

static void accel_pipeline_init(AccelPipeline *p)
{
    p->lp_x = 0.0f;
    p->lp_y = 0.0f;
    p->lp_z = 0.0f;

    p->mag_ema = 0.0f;
    p->baseline_ema = 0.0f;
    p->var_ema = 0.0f;

    p->anomaly_active = false;
    p->anomaly_countdown = 0;

    // Tunable parameters
    p->alpha_gravity = 0.01f;     // slower => stronger gravity tracking
    p->alpha_mag = 0.2f;          // smoothing of dynamic magnitude
    p->alpha_baseline = 0.01f;    // slow baseline adaptation
    p->alpha_var = 0.01f;         // slow variance adaptation
    p->threshold_k = 4.0f;        // sensitivity
    p->min_threshold = 0.15f;     // floor threshold
    p->holdoff_samples = 20;      // debounce/cooldown
    p->hysteresis_ratio = 0.7f;   // release threshold fraction
}

static float fast_sqrtf(float x)
{
    // Replace with hardware sqrt or approximation if needed
    return sqrtf(x);
}

static AccelPipelineOutput accel_pipeline_process(AccelPipeline *p, AccelSample s)
{
    AccelPipelineOutput out;

    // 1. Estimate gravity / DC using low-pass filter
    p->lp_x += p->alpha_gravity * (s.x - p->lp_x);
    p->lp_y += p->alpha_gravity * (s.y - p->lp_y);
    p->lp_z += p->alpha_gravity * (s.z - p->lp_z);

    // 2. High-pass filtered dynamic acceleration
    float fx = s.x - p->lp_x;
    float fy = s.y - p->lp_y;
    float fz = s.z - p->lp_z;

    // 3. Magnitude of dynamic acceleration
    float mag = fast_sqrtf(fx * fx + fy * fy + fz * fz);

    // 4. Smooth magnitude
    p->mag_ema += p->alpha_mag * (mag - p->mag_ema);

    // 5. Track baseline
    p->baseline_ema += p->alpha_baseline * (p->mag_ema - p->baseline_ema);

    // 6. Deviation from baseline
    float deviation = p->mag_ema - p->baseline_ema;
    float abs_dev = fabsf(deviation);

    // 7. Track variance / noise level using squared deviation
    float sq = deviation * deviation;
    p->var_ema += p->alpha_var * (sq - p->var_ema);

    float sigma = fast_sqrtf(p->var_ema);
    float threshold = p->threshold_k * sigma;
    if (threshold < p->min_threshold) {
        threshold = p->min_threshold;
    }

    // 8. Detection with hysteresis and holdoff
    bool anomaly = p->anomaly_active;

    if (!p->anomaly_active) {
        if (p->anomaly_countdown > 0) {
            p->anomaly_countdown--;
        } else if (abs_dev > threshold) {
            p->anomaly_active = true;
            anomaly = true;
            p->anomaly_countdown = p->holdoff_samples;
        }
    } else {
        float release_threshold = threshold * p->hysteresis_ratio;
        if (abs_dev < release_threshold) {
            p->anomaly_active = false;
            anomaly = false;
        } else {
            anomaly = true;
        }
    }

    out.filtered_x = fx;
    out.filtered_y = fy;
    out.filtered_z = fz;
    out.magnitude = p->mag_ema;
    out.baseline = p->baseline_ema;
    out.deviation = deviation;
    out.threshold = threshold;
    out.anomaly = anomaly;

    return out;
}
```

