Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline.

It includes:
- DC offset removal
- Magnitude estimation
- Low-pass baseline tracking
- High-pass residual extraction
- Noise-floor estimation
- Adaptive threshold anomaly detection
- Debounce / persistence logic

This is suitable for microcontrollers and streaming sensor data sample-by-sample.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Input:
 *   ax, ay, az  -> raw accelerometer samples
 *
 * Output:
 *   anomaly flag per sample
 *
 * Pipeline:
 *   1. Remove DC bias from each axis
 *   2. Compute acceleration magnitude
 *   3. Track slow baseline with low-pass filter
 *   4. Compute residual = |mag - baseline|
 *   5. Estimate noise floor
 *   6. Trigger anomaly if residual exceeds adaptive threshold
 *   7. Use persistence counters to reduce false positives
 */

#ifndef ABSF
#define ABSF(x) ((x) < 0.0f ? -(x) : (x))
#endif

typedef struct {
    // Per-axis DC offset estimates
    float bias_x;
    float bias_y;
    float bias_z;

    // Slow baseline of magnitude
    float baseline_mag;

    // Noise estimate of residual
    float noise_est;

    // Filter coefficients
    float bias_alpha;      // small, e.g. 0.001
    float baseline_alpha;  // small, e.g. 0.01
    float noise_alpha;     // small, e.g. 0.01

    // Detection parameters
    float threshold_k;     // multiplier on noise estimate
    float min_threshold;   // absolute minimum threshold

    // Debounce / persistence
    uint16_t trigger_count;
    uint16_t release_count;
    uint16_t trigger_required;
    uint16_t release_required;

    bool anomaly_active;
    bool initialized;
} AnomalyDetector;

typedef struct {
    float ax_hp;
    float ay_hp;
    float az_hp;
    float magnitude;
    float baseline;
    float residual;
    float threshold;
    float noise_est;
    bool anomaly;
} DetectorOutput;

static void anomaly_detector_init(AnomalyDetector *det)
{
    det->bias_x = 0.0f;
    det->bias_y = 0.0f;
    det->bias_z = 0.0f;

    det->baseline_mag = 0.0f;
    det->noise_est = 0.0f;

    // Tunable parameters
    det->bias_alpha = 0.001f;
    det->baseline_alpha = 0.01f;
    det->noise_alpha = 0.01f;

    det->threshold_k = 6.0f;
    det->min_threshold = 0.05f;

    det->trigger_count = 0;
    det->release_count = 0;
    det->trigger_required = 3;
    det->release_required = 10;

    det->anomaly_active = false;
    det->initialized = false;
}

static DetectorOutput anomaly_detector_process(
    AnomalyDetector *det,
    float ax,
    float ay,
    float az)
{
    DetectorOutput out = {0};

    // First sample initialization
    if (!det->initialized) {
        det->bias_x = ax;
        det->bias_y = ay;
        det->bias_z = az;

        float mag0 = sqrtf(ax * ax + ay * ay + az * az);
        det->baseline_mag = mag0;
        det->noise_est = 0.01f;

        det->initialized = true;
    }

    // 1. Update DC bias estimate
    det->bias_x += det->bias_alpha * (ax - det->bias_x);
    det->bias_y += det->bias_alpha * (ay - det->bias_y);
    det->bias_z += det->bias_alpha * (az - det->bias_z);

    // 2. High-pass axis values
    float ax_hp = ax - det->bias_x;
    float ay_hp = ay - det->bias_y;
    float az_hp = az - det->bias_z;

    // 3. Magnitude of high-pass acceleration
    float mag = sqrtf(ax_hp * ax_hp + ay_hp * ay_hp + az_hp * az_hp);

    // 4. Track baseline magnitude
    det->baseline_mag += det->baseline_alpha * (mag - det->baseline_mag);

    // 5. Residual from baseline
    float residual = ABSF(mag - det->baseline_mag);

    // 6. Update noise estimate
    det->noise_est += det->noise_alpha * (residual - det->noise_est);

    // 7. Adaptive threshold
    float threshold = det->threshold_k * det->noise_est;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    bool over = (residual > threshold);

    // 8. Persistence logic
    if (!det->anomaly_active) {
        if (over) {
            if (det->trigger_count < det->trigger_required) {
                det->trigger_count++;
            }
            if (det->trigger_count >= det->trigger_required) {
                det->anomaly_active = true;
                det->release_count = 0;
            }
        } else {
            det->trigger_count = 0;
        }
    } else {
        if (!over) {
            if (det->release_count < det->release_required) {
                det->release_count++;
            }
            if (det->release_count >= det->release_required) {
                det->anomaly_active = false;
                det->trigger_count = 0;
            }
        } else {
            det->release_count = 0;
        }
    }

    out.ax_hp = ax_hp;
    out.ay_hp = ay_hp;
    out.az_hp = az_hp;
    out.magnitude = mag;
    out.baseline = det->baseline_mag;
    out.residual = residual;
    out.threshold = threshold;
    out.noise_est = det->noise_est;
    out.anomaly = det->anomaly_active;

    return out;
}
```

