 * Pipeline overview:
 * 1. Compute approximate magnitude from x,y,z
 * 2. Track slow baseline with low-pass filter
 * 3. Compute residual = |mag - baseline|
 * 4. Smooth residual into short-term energy
 * 5. Track noise floor
 * 6. Trigger anomaly if energy exceeds adaptive threshold
 * 7. Require persistence and cooldown to reduce false positives
 */

typedef struct {
    // Baseline tracking
    int32_t baseline;          // low-pass estimate of magnitude

    // Smoothed residual energy
    int32_t energy;

    // Noise floor estimate
    int32_t noise_floor;

    // Detection state
    uint16_t over_threshold_count;
    uint16_t cooldown_count;
    bool anomaly;

    // Configuration
    uint8_t baseline_shift;    // larger => slower baseline
    uint8_t energy_shift;      // larger => smoother energy
    uint8_t noise_shift;       // larger => slower noise adaptation

    int32_t threshold_offset;  // minimum extra margin
    int32_t threshold_scale;   // multiplier on noise floor
    uint16_t persistence;      // consecutive samples required
    uint16_t cooldown;         // refractory period after trigger
} AnomalyDetector;

static inline int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

/*
 * Fast approximate magnitude:
 * Instead of sqrt(x^2+y^2+z^2), use Manhattan norm.
 * For many anomaly tasks this is sufficient and much cheaper.
 */
static inline int32_t accel_magnitude_approx(const AccelSample *s) {
    return iabs32(s->x) + iabs32(s->y) + iabs32(s->z);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->energy = 0;
    det->noise_floor = 0;
    det->over_threshold_count = 0;
    det->cooldown_count = 0;
    det->anomaly = false;

    // Tunable parameters
    det->baseline_shift = 6;     // ~1/64 update rate
    det->energy_shift = 3;       // ~1/8 smoothing
    det->noise_shift = 7;        // ~1/128 update rate

    det->threshold_offset = 50;  // depends on sensor scaling
    det->threshold_scale = 3;    // threshold = noise*3 + offset
    det->persistence = 3;        // require 3 consecutive hits
    det->cooldown = 20;          // suppress retrigger for 20 samples
}

/*
 * Returns true only on the sample where a new anomaly is declared.
 * Call once per accelerometer sample.
 */
bool anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample) {
    int32_t mag = accel_magnitude_approx(sample);

    // Initialize baseline on first sample
    if (det->baseline == 0) {
        det->baseline = mag;
        det->energy = 0;
        det->noise_floor = 0;
        return false;
    }

    // 1) Low-pass baseline tracking
    det->baseline += (mag - det->baseline) >> det->baseline_shift;

    // 2) High-pass residual
    int32_t residual = iabs32(mag - det->baseline);

    // 3) Smooth residual into energy estimate
    det->energy += (residual - det->energy) >> det->energy_shift;

    // 4) Track noise floor slowly
    // Optional: only adapt strongly when below current threshold region
    det->noise_floor += (det->energy - det->noise_floor) >> det->noise_shift;

    // 5) Adaptive threshold
    int32_t threshold = det->noise_floor * det->threshold_scale + det->threshold_offset;

    // 6) Cooldown handling
    if (det->cooldown_count > 0) {
        det->cooldown_count--;
    }

    // 7) Detection with persistence
    bool triggered = false;
    if (det->cooldown_count == 0 && det->energy > threshold) {
        if (det->over_threshold_count < 0xFFFF) {
            det->over_threshold_count++;
        }

        if (det->over_threshold_count >= det->persistence) {
            triggered = true;
            det->anomaly = true;
            det->cooldown_count = det->cooldown;
            det->over_threshold_count = 0;
        }
    } else {
        det->over_threshold_count = 0;
        det->anomaly = false;
    }

    return triggered;
}
