If you want a slightly more robust detector using a fixed window RMS instead of exponential smoothing, here is another version.

```c
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample2;

typedef struct {
    int32_t baseline;
    int32_t residual_buf[WINDOW_SIZE];
    uint32_t sum_residual;
    uint8_t index;
    uint8_t filled;

    int32_t noise_floor;
    uint16_t cooldown_count;
    uint16_t persistence_count;

    uint8_t baseline_shift;
    uint8_t noise_shift;
    int32_t threshold_offset;
    int32_t threshold_scale;
    uint16_t persistence;
    uint16_t cooldown;
} WindowDetector;

static inline int32_t abs32(int32_t x) {
    return x < 0 ? -x : x;
}

static inline int32_t mag_approx(const AccelSample2 *s) {
    return abs32(s->x) + abs32(s->y) + abs32(s->z);
}

void window_detector_init(WindowDetector *d) {
    d->baseline = 0;
    d->sum_residual = 0;
    d->index = 0;
    d->filled = 0;
    d->noise_floor = 0;
    d->cooldown_count = 0;
    d->persistence_count = 0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->residual_buf[i] = 0;
    }

    d->baseline_shift = 6;
    d->noise_shift = 7;
    d->threshold_offset = 50;
    d->threshold_scale = 3;
    d->persistence = 2;
    d->cooldown = 20;
}

bool window_detector_process(WindowDetector *d, const AccelSample2 *s) {
    int32_t mag = mag_approx(s);

    if (d->baseline == 0) {
        d->baseline = mag;
        return false;
    }

    d->baseline += (mag - d->baseline) >> d->baseline_shift;
    int32_t residual = abs32(mag - d->baseline);

    d->sum_residual -= d->residual_buf[d->index];
    d->residual_buf[d->index] = residual;
    d->sum_residual += residual;

    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->filled < WINDOW_SIZE) {
        d->filled++;
    }

    int32_t avg_residual = d->sum_residual / (d->filled ? d->filled : 1);

    d->noise_floor += (avg_residual - d->noise_floor) >> d->noise_shift;
    int32_t threshold = d->noise_floor * d->threshold_scale + d->threshold_offset;

    if (d->cooldown_count > 0) {
        d->cooldown_count--;
    }

    if (d->cooldown_count == 0 && avg_residual > threshold) {
        d->persistence_count++;
        if (d->persistence_count >= d->persistence) {
            d->persistence_count = 0;
            d->cooldown_count = d->cooldown;
            return true;
        }
    } else {
        d->persistence_count = 0;
    }

    return false;
}
