Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:
- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling mean absolute deviation estimate
- Threshold-based anomaly detection with debounce
- Fixed-point integer math only

You can adapt it to Arduino, STM32, ESP32, or bare-metal systems.

---

## Design

Pipeline per sample:

1. Read accelerometer `(x, y, z)` in integer units
2. Compute approximate magnitude:
   `|x| + |y| + |z|`
3. Low-pass filter the magnitude to estimate normal baseline
4. Compute residual:
   `residual = magnitude - baseline`
5. Track average absolute residual as noise level
6. Trigger anomaly if residual exceeds:
   `threshold = noise_floor * multiplier + offset`
7. Debounce so a single spike doesn’t repeatedly fire

This is lightweight and works well for vibration, impact, or motion anomaly detection.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Low-pass filtered magnitude baseline (Q8 fixed point)
    int32_t baseline_q8;

    // Mean absolute residual / noise estimate (Q8 fixed point)
    int32_t noise_q8;

    // Last residual for optional debugging
    int16_t last_residual;

    // Debounce / holdoff
    uint16_t cooldown;
    uint16_t cooldown_period;

    // Detection parameters
    uint8_t baseline_shift;   // LPF strength: larger = slower baseline
    uint8_t noise_shift;      // LPF strength for noise estimate
    uint8_t threshold_mult;   // threshold = noise * mult + offset
    int16_t threshold_offset; // minimum threshold

    // State
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    int16_t magnitude;
    int16_t baseline;
    int16_t residual;
    int16_t threshold;
    int16_t noise;
} DetectionResult;

static inline int16_t i16_abs(int16_t v) {
    return (v < 0) ? (int16_t)(-v) : v;
}

static inline int32_t i32_abs(int32_t v) {
    return (v < 0) ? -v : v;
}

// Fast approximate magnitude for embedded use
static inline int16_t accel_magnitude_l1(const AccelSample *s) {
    int32_t mag = (int32_t)i16_abs(s->x) +
                  (int32_t)i16_abs(s->y) +
                  (int32_t)i16_abs(s->z);

    if (mag > 32767) mag = 32767;
    return (int16_t)mag;
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline_q8 = 0;
    det->noise_q8 = 0;
    det->last_residual = 0;
    det->cooldown = 0;
    det->cooldown_period = 20;   // samples to suppress repeated triggers

    det->baseline_shift = 5;     // ~1/32 smoothing
    det->noise_shift = 4;        // ~1/16 smoothing
    det->threshold_mult = 4;     // threshold = 4 * noise + offset
    det->threshold_offset = 200; // tune for sensor scale

    det->initialized = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample) {
    DetectionResult result = {0};

    int16_t mag = accel_magnitude_l1(sample);

    if (!det->initialized) {
        det->baseline_q8 = ((int32_t)mag) << 8;
        det->noise_q8 = 0;
        det->last_residual = 0;
        det->initialized = true;
    }

    // Low-pass baseline update:
    // baseline += (input - baseline) / 2^baseline_shift
    int32_t mag_q8 = ((int32_t)mag) << 8;
    det->baseline_q8 += (mag_q8 - det->baseline_q8) >> det->baseline_shift;

    int16_t baseline = (int16_t)(det->baseline_q8 >> 8);
    int16_t residual = mag - baseline;
    det->last_residual = residual;

    // Update noise estimate from absolute residual
    int32_t abs_res_q8 = ((int32_t)i16_abs(residual)) << 8;
    det->noise_q8 += (abs_res_q8 - det->noise_q8) >> det->noise_shift;

    int16_t noise = (int16_t)(det->noise_q8 >> 8);

    int32_t threshold32 = (int32_t)noise * det->threshold_mult + det->threshold_offset;
    if (threshold32 > 32767) threshold32 = 32767;
    int16_t threshold = (int16_t)threshold32;

    bool anomaly = false;

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    // Positive residual anomaly detection
    if ((residual > threshold) && (det->cooldown == 0)) {
        anomaly = true;
        det->cooldown = det->cooldown_period;
    }

    result.anomaly = anomaly;
    result.magnitude = mag;
    result.baseline = baseline;
    result.residual = residual;
    result.threshold = threshold;
    result.noise = noise;

    return result;
}
```

