Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

It includes:
- DC offset removal
- Magnitude estimation
- Low-pass baseline tracking
- High-pass residual extraction
- Running noise estimate
- Z-score style anomaly detection
- Debounce / persistence logic

You can adapt it for raw `x,y,z` accelerometer samples.

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Input:
 *   raw accelerometer samples (x, y, z), e.g. in g or mg
 *
 * Pipeline:
 *   1) Remove per-axis DC bias with slow IIR
 *   2) Compute signal magnitude
 *   3) Track slow baseline magnitude
 *   4) Compute residual = |mag - baseline|
 *   5) Track residual noise floor
 *   6) Trigger anomaly if residual exceeds threshold * noise floor
 *   7) Require persistence for robustness
 *
 * Notes:
 *   - Designed for low memory / low CPU embedded use
 *   - Uses float for clarity; can be converted to fixed-point
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Bias tracking for each axis
    float bias_x;
    float bias_y;
    float bias_z;

    // Baseline magnitude tracker
    float baseline_mag;

    // Noise estimate of residual
    float noise_est;

    // Last computed values
    float last_mag;
    float last_residual;
    float last_score;

    // Detection state
    uint16_t anomaly_count;
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    // IIR smoothing factors [0..1]
    float bias_alpha;       // slow bias adaptation, e.g. 0.001
    float baseline_alpha;   // slow baseline adaptation, e.g. 0.01
    float noise_alpha;      // noise adaptation, e.g. 0.01

    // Detection tuning
    float threshold_sigma;  // e.g. 6.0
    float min_noise;        // floor to avoid divide-by-zero, e.g. 0.01
    uint16_t trigger_count; // consecutive samples required, e.g. 3
    uint16_t release_count; // consecutive normal samples to clear, e.g. 10

    // Optional clipping
    float max_abs_input;    // sanity clamp, e.g. 16.0 g
} AnomalyConfig;

typedef struct {
    bool anomaly;
    float magnitude;
    float residual;
    float noise;
    float score;
} AnomalyResult;

static float clampf(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float absf_local(float x) {
    return (x < 0.0f) ? -x : x;
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->bias_x = 0.0f;
    det->bias_y = 0.0f;
    det->bias_z = 0.0f;
    det->baseline_mag = 0.0f;
    det->noise_est = 0.01f;
    det->last_mag = 0.0f;
    det->last_residual = 0.0f;
    det->last_score = 0.0f;
    det->anomaly_count = 0;
    det->anomaly_active = false;
}

void anomaly_config_default(AnomalyConfig *cfg) {
    cfg->bias_alpha = 0.001f;
    cfg->baseline_alpha = 0.01f;
    cfg->noise_alpha = 0.01f;
    cfg->threshold_sigma = 6.0f;
    cfg->min_noise = 0.01f;
    cfg->trigger_count = 3;
    cfg->release_count = 10;
    cfg->max_abs_input = 16.0f;
}

AnomalyResult anomaly_detector_process(
    AnomalyDetector *det,
    const AnomalyConfig *cfg,
    AccelSample raw
) {
    AnomalyResult out = {0};

    // 1) Clamp raw input for safety
    raw.x = clampf(raw.x, -cfg->max_abs_input, cfg->max_abs_input);
    raw.y = clampf(raw.y, -cfg->max_abs_input, cfg->max_abs_input);
    raw.z = clampf(raw.z, -cfg->max_abs_input, cfg->max_abs_input);

    // 2) Track slow per-axis bias
    det->bias_x += cfg->bias_alpha * (raw.x - det->bias_x);
    det->bias_y += cfg->bias_alpha * (raw.y - det->bias_y);
    det->bias_z += cfg->bias_alpha * (raw.z - det->bias_z);

    float x_hp = raw.x - det->bias_x;
    float y_hp = raw.y - det->bias_y;
    float z_hp = raw.z - det->bias_z;

    // 3) Magnitude of de-biased acceleration
    float mag = sqrtf(x_hp * x_hp + y_hp * y_hp + z_hp * z_hp);
    det->last_mag = mag;

    // 4) Track slow baseline magnitude
    det->baseline_mag += cfg->baseline_alpha * (mag - det->baseline_mag);

    // 5) Residual from baseline
    float residual = absf_local(mag - det->baseline_mag);
    det->last_residual = residual;

    // 6) Track noise floor of residual
    det->noise_est += cfg->noise_alpha * (residual - det->noise_est);
    if (det->noise_est < cfg->min_noise) {
        det->noise_est = cfg->min_noise;
    }

    // 7) Score
    float score = residual / det->noise_est;
    det->last_score = score;

    // 8) Persistence logic
    if (score > cfg->threshold_sigma) {
        if (det->anomaly_count < 65535) {
            det->anomaly_count++;
        }
    } else {
        if (det->anomaly_active) {
            // decay more slowly while active
            if (det->anomaly_count > 0) {
                det->anomaly_count--;
            }
        } else {
            det->anomaly_count = 0;
        }
    }

    if (!det->anomaly_active && det->anomaly_count >= cfg->trigger_count) {
        det->anomaly_active = true;
    }

    if (det->anomaly_active && score <= cfg->threshold_sigma) {
        static uint16_t normal_count = 0;
        normal_count++;
        if (normal_count >= cfg->release_count) {
            det->anomaly_active = false;
            det->anomaly_count = 0;
            normal_count = 0;
        }
    } else {
        // reset release counter when anomaly persists
        static uint16_t normal_count = 0;
        normal_count = 0;
    }

    out.anomaly = det->anomaly_active;
    out.magnitude = mag;
    out.residual = residual;
    out.noise = det->noise_est;
    out.score = score;

    return out;
}
