## More MCU-friendly fixed-point style version

If you want to avoid floating point, here is a simplified integer approach using milli-g units.

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int32_t bias_x;
    int32_t bias_y;
    int32_t bias_z;
    uint32_t baseline_mag;
    uint32_t noise_est;
    uint16_t anomaly_count;
    uint16_t normal_count;
    bool anomaly_active;
} AccelAnomInt;

typedef struct {
    uint8_t bias_shift;       // e.g. 10 => alpha ~ 1/1024
    uint8_t baseline_shift;   // e.g. 6  => alpha ~ 1/64
    uint8_t noise_shift;      // e.g. 6
    uint16_t threshold_q8;    // e.g. 5.0 => 1280
    uint16_t min_noise;       // e.g. 10 mg
    uint16_t trigger_count;
    uint16_t release_count;
} AccelAnomIntCfg;

static uint32_t iabs32(int32_t x) {
    return (x < 0) ? (uint32_t)(-x) : (uint32_t)x;
}

// Cheap magnitude approximation: max + 1/2 mid + 1/4 min
static uint32_t approx_mag3(int32_t x, int32_t y, int32_t z) {
    uint32_t ax = iabs32(x), ay = iabs32(y), az = iabs32(z);
    uint32_t max = ax, mid = ay, min = az;

    if (max < mid) { uint32_t t = max; max = mid; mid = t; }
    if (mid < min) { uint32_t t = mid; mid = min; min = t; }
    if (max < mid) { uint32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

void accel_anom_int_init(AccelAnomInt *d) {
    d->bias_x = d->bias_y = d->bias_z = 0;
    d->baseline_mag = 0;
    d->noise_est = 10;
    d->anomaly_count = 0;
    d->normal_count = 0;
    d->anomaly_active = false;
}

bool accel_anom_int_process(
    AccelAnomInt *d,
    const AccelAnomIntCfg *cfg,
    int32_t x_mg,
    int32_t y_mg,
    int32_t z_mg
) {
    d->bias_x += (x_mg - d->bias_x) >> cfg->bias_shift;
    d->bias_y += (y_mg - d->bias_y) >> cfg->bias_shift;
    d->bias_z += (z_mg - d->bias_z) >> cfg->bias_shift;

    int32_t x_hp = x_mg - d->bias_x;
    int32_t y_hp = y_mg - d->bias_y;
    int32_t z_hp = z_mg - d->bias_z;

    uint32_t mag = approx_mag3(x_hp, y_hp, z_hp);

    d->baseline_mag += (mag - d->baseline_mag) >> cfg->baseline_shift;

    uint32_t residual = (mag > d->baseline_mag) ?
                        (mag - d->baseline_mag) :
                        (d->baseline_mag - mag);

    d->noise_est += (residual - d->noise_est) >> cfg->noise_shift;
    if (d->noise_est < cfg->min_noise) {
        d->noise_est = cfg->min_noise;
    }

    // score_q8 = residual / noise_est in Q8
    uint32_t score_q8 = (residual << 8) / d->noise_est;

    if (score_q8 > cfg->threshold_q8) {
        if (d->anomaly_count < 65535) d->anomaly_count++;
        d->normal_count = 0;
    } else {
        d->normal_count++;
        if (!d->anomaly_active) {
            d->anomaly_count = 0;
        } else if (d->anomaly_count > 0) {
            d->anomaly_count--;
        }
    }

    if (!d->anomaly_active && d->anomaly_count >= cfg->trigger_count) {
        d->anomaly_active = true;
    }

    if (d->anomaly_active && d->normal_count >= cfg->release_count) {
        d->anomaly_active = false;
        d->anomaly_count = 0;
        d->normal_count = 0;
    }

    return d->anomaly_active;
}
```

