## Design

Pipeline:

1. Read accelerometer sample `(x, y, z)`
2. Compute signal magnitude
3. Track slow baseline with IIR low-pass
4. Compute deviation from baseline
5. Estimate normal noise level
6. Trigger anomaly if deviation exceeds adaptive threshold for several samples

This works well for:
- impacts
- vibration spikes
- sudden motion changes
- sensor disturbances

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Baseline magnitude estimate
    int32_t baseline;

    // Noise estimate of residual
    int32_t noise_est;

    // Last residual
    int32_t residual;

    // Detection state
    uint8_t anomaly_count;
    bool anomaly_active;

    // Configuration
    uint8_t baseline_shift;     // larger => slower baseline update
    uint8_t noise_shift;        // larger => slower noise update
    uint16_t threshold_offset;  // minimum threshold
    uint8_t threshold_mult;     // threshold = offset + noise_est * mult
    uint8_t trigger_count;      // consecutive samples to trigger
    uint8_t release_count;      // consecutive normal samples to clear

    uint8_t normal_count;
} AnomalyDetector;

static inline int32_t abs32(int32_t v) {
    return (v < 0) ? -v : v;
}

/*
 * Fast approximate vector magnitude:
 * max + 1/4 mid + 1/8 min
 * cheaper than sqrt(x^2+y^2+z^2)
 */
static int32_t approx_magnitude(int16_t x, int16_t y, int16_t z) {
    int32_t ax = abs32(x);
    int32_t ay = abs32(y);
    int32_t az = abs32(z);

    int32_t max = ax, mid = ay, min = az;

    if (max < mid) { int32_t t = max; max = mid; mid = t; }
    if (mid < min) { int32_t t = mid; mid = min; min = t; }
    if (max < mid) { int32_t t = max; max = mid; mid = t; }

    return max + (mid >> 2) + (min >> 3);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->noise_est = 0;
    det->residual = 0;
    det->anomaly_count = 0;
    det->normal_count = 0;
    det->anomaly_active = false;

    // Tunable parameters
    det->baseline_shift = 5;      // ~1/32 update rate
    det->noise_shift = 4;         // ~1/16 update rate
    det->threshold_offset = 50;   // depends on sensor scale
    det->threshold_mult = 4;      // adaptive threshold multiplier
    det->trigger_count = 3;       // require 3 consecutive exceedances
    det->release_count = 5;       // require 5 normal samples to clear
}

/*
 * Returns true when anomaly state is active.
 */
bool anomaly_detector_update(AnomalyDetector *det, AccelSample s) {
    int32_t mag = approx_magnitude(s.x, s.y, s.z);

    // Initialize baseline on first sample
    if (det->baseline == 0) {
        det->baseline = mag;
    }

    // Low-pass baseline tracking
    det->baseline += (mag - det->baseline) >> det->baseline_shift;

    // High-pass residual
    int32_t residual = mag - det->baseline;
    int32_t abs_residual = abs32(residual);
    det->residual = residual;

    // Update noise estimate
    det->noise_est += (abs_residual - det->noise_est) >> det->noise_shift;

    // Adaptive threshold
    int32_t threshold = det->threshold_offset + (det->noise_est * det->threshold_mult);

    bool exceeds = (abs_residual > threshold);

    if (exceeds) {
        if (det->anomaly_count < 255) det->anomaly_count++;
        det->normal_count = 0;
    } else {
        det->anomaly_count = 0;
        if (det->normal_count < 255) det->normal_count++;
    }

    if (!det->anomaly_active) {
        if (det->anomaly_count >= det->trigger_count) {
            det->anomaly_active = true;
        }
    } else {
        if (det->normal_count >= det->release_count) {
            det->anomaly_active = false;
        }
    }

    return det->anomaly_active;
}
```

