It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling noise estimate
- Threshold-based anomaly detection
- Debounce / persistence logic
- Fixed-point integer math only

You can adapt it to Arduino, STM32, ESP32, or bare-metal systems.

---

## Design

Pipeline:

1. Read accelerometer `(x, y, z)`
2. Compute motion magnitude
3. Track slow baseline with IIR low-pass
4. Compute residual = `|magnitude - baseline|`
5. Track normal residual level
6. Trigger anomaly if residual exceeds adaptive threshold for several samples

This is lightweight and practical for embedded use.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Low-pass estimate of signal magnitude
    int32_t baseline;

    // Low-pass estimate of residual/noise
    int32_t noise_est;

    // Detection state
    uint8_t anomaly_count;
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    // Smoothing factors as power-of-two shifts
    // smaller shift => faster adaptation
    uint8_t baseline_shift;   // e.g. 4 => alpha = 1/16
    uint8_t noise_shift;      // e.g. 5 => alpha = 1/32

    // Threshold multiplier in fixed-point
    // threshold = min_threshold + noise_est * threshold_mult / 256
    uint16_t threshold_mult;

    // Minimum absolute threshold
    int32_t min_threshold;

    // Number of consecutive samples required
    uint8_t trigger_count;

    // Number of consecutive normal samples to clear anomaly
    uint8_t clear_count;
} AnomalyConfig;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t baseline;
    int32_t residual;
    int32_t threshold;
} AnomalyResult;

/*
 * Fast approximate magnitude:
 * Instead of sqrt(x^2 + y^2 + z^2), use |x| + |y| + |z|
 * This is cheap and often sufficient for anomaly detection.
 */
static inline int32_t accel_magnitude_l1(const AccelSample *s)
{
    return abs(s->x) + abs(s->y) + abs(s->z);
}

/*
 * Initialize detector state.
 */
void anomaly_detector_init(AnomalyDetector *det)
{
    det->baseline = 0;
    det->noise_est = 0;
    det->anomaly_count = 0;
    det->anomaly_active = false;
}

/*
 * Process one accelerometer sample.
 */
AnomalyResult anomaly_detector_process(
    AnomalyDetector *det,
    const AnomalyConfig *cfg,
    const AccelSample *sample)
{
    AnomalyResult result = {0};

    int32_t mag = accel_magnitude_l1(sample);

    // Initialize baseline on first sample if needed
    if (det->baseline == 0) {
        det->baseline = mag;
    }

    // Low-pass baseline update:
    // baseline += (mag - baseline) / 2^baseline_shift
    det->baseline += (mag - det->baseline) >> cfg->baseline_shift;

    int32_t residual = mag - det->baseline;
    if (residual < 0) residual = -residual;

    // Update noise estimate from residual
    det->noise_est += (residual - det->noise_est) >> cfg->noise_shift;

    // Adaptive threshold
    int32_t threshold = cfg->min_threshold +
                        ((det->noise_est * cfg->threshold_mult) >> 8);

    bool above = residual > threshold;

    if (det->anomaly_active) {
        if (!above) {
            if (det->anomaly_count > 0) {
                det->anomaly_count--;
            } else {
                det->anomaly_active = false;
            }
        } else {
            det->anomaly_count = cfg->clear_count;
        }
    } else {
        if (above) {
            if (det->anomaly_count < 255) {
                det->anomaly_count++;
            }
            if (det->anomaly_count >= cfg->trigger_count) {
                det->anomaly_active = true;
                det->anomaly_count = cfg->clear_count;
            }
        } else {
            det->anomaly_count = 0;
        }
    }

    result.anomaly = det->anomaly_active;
    result.magnitude = mag;
    result.baseline = det->baseline;
    result.residual = residual;
    result.threshold = threshold;

    return result;
}
```

