## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Assumptions:
 * - Input accelerometer samples are in g or m/s^2, consistently scaled.
 * - Sampling rate is fixed.
 * - Floating point is available. If not, this can be converted to fixed-point.
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define ACCEL_WINDOW_SIZE       64
#define ACCEL_ANOMALY_COOLDOWN  20
#define ACCEL_MIN_STDDEV        0.02f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;     // low-pass filter coefficient
    float x;
    float y;
    float z;
    bool initialized;
} LowPassFilter3D;

typedef struct {
    float buffer[ACCEL_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
} RollingStats;

typedef struct {
    LowPassFilter3D lpf;
    RollingStats stats;
    float anomaly_threshold;   // e.g. 3.5 standard deviations
    uint16_t cooldown_counter;
    bool anomaly_active;
} AccelAnomalyDetector;

/* =========================
 * Low-pass filter functions
 * ========================= */

static void lpf3d_init(LowPassFilter3D *filt, float alpha)
{
    filt->alpha = alpha;
    filt->x = 0.0f;
    filt->y = 0.0f;
    filt->z = 0.0f;
    filt->initialized = false;
}

static AccelSample lpf3d_apply(LowPassFilter3D *filt, AccelSample in)
{
    if (!filt->initialized) {
        filt->x = in.x;
        filt->y = in.y;
        filt->z = in.z;
        filt->initialized = true;
    } else {
        filt->x = filt->alpha * in.x + (1.0f - filt->alpha) * filt->x;
        filt->y = filt->alpha * in.y + (1.0f - filt->alpha) * filt->y;
        filt->z = filt->alpha * in.z + (1.0f - filt->alpha) * filt->z;
    }

    AccelSample out = { filt->x, filt->y, filt->z };
    return out;
}

/* =========================
 * Rolling statistics
 * ========================= */

static void rolling_stats_init(RollingStats *rs)
{
    memset(rs->buffer, 0, sizeof(rs->buffer));
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sum_sq = 0.0f;
}

static void rolling_stats_add(RollingStats *rs, float value)
{
    if (rs->count < ACCEL_WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->count++;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sum_sq -= old * old;

        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
    }

    rs->index = (rs->index + 1) % ACCEL_WINDOW_SIZE;
}

static float rolling_stats_mean(const RollingStats *rs)
{
    if (rs->count == 0) return 0.0f;
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const RollingStats *rs)
{
    if (rs->count < 2) return 0.0f;

    float mean = rolling_stats_mean(rs);
    float var = (rs->sum_sq / (float)rs->count) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

static float rolling_stats_stddev(const RollingStats *rs)
{
    return sqrtf(rolling_stats_variance(rs));
}

/* =========================
 * Utility
 * ========================= */

static float accel_magnitude(AccelSample s)
{
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* =========================
 * Detector API
 * ========================= */

void accel_detector_init(AccelAnomalyDetector *det, float lpf_alpha, float threshold_stddev)
{
    lpf3d_init(&det->lpf, lpf_alpha);
    rolling_stats_init(&det->stats);
    det->anomaly_threshold = threshold_stddev;
    det->cooldown_counter = 0;
    det->anomaly_active = false;
}

/*
 * Process one accelerometer sample.
 *
 * Returns true if an anomaly is detected on this sample.
 */
bool accel_detector_process(AccelAnomalyDetector *det, AccelSample raw_sample)
{
    // 1. Filter raw signal
    AccelSample filtered = lpf3d_apply(&det->lpf, raw_sample);

    // 2. Compute magnitude
    float mag = accel_magnitude(filtered);

    // 3. Compute baseline stats BEFORE adding current sample
    float mean = rolling_stats_mean(&det->stats);
    float stddev = rolling_stats_stddev(&det->stats);
    if (stddev < ACCEL_MIN_STDDEV) {
        stddev = ACCEL_MIN_STDDEV;
    }

    bool anomaly = false;

    // Require enough history before detecting
    if (det->stats.count >= ACCEL_WINDOW_SIZE / 2) {
        float z = fabsf(mag - mean) / stddev;

        if (det->cooldown_counter == 0 && z > det->anomaly_threshold) {
            anomaly = true;
            det->anomaly_active = true;
            det->cooldown_counter = ACCEL_ANOMALY_COOLDOWN;
        }
    }

    // 4. Update baseline after detection decision
    rolling_stats_add(&det->stats, mag);

    // 5. Cooldown handling
    if (det->cooldown_counter > 0) {
        det->cooldown_counter--;
    } else {
        det->anomaly_active = false;
    }

    return anomaly;
}
