Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline.

It includes:

- 3-axis accelerometer sample handling
- DC removal / low-pass baseline tracking
- Magnitude estimation
- Moving average smoothing
- Adaptive thresholding using running mean + deviation
- Cooldown to avoid repeated triggers
- Simple API for integration into firmware

## Design

Pipeline per sample:

1. Read `ax, ay, az`
2. Estimate signal magnitude
3. Remove slow baseline drift
4. Smooth signal
5. Track normal behavior statistics
6. Flag anomaly if signal exceeds adaptive threshold

This is suitable for:
- vibration spike detection
- impact detection
- abnormal motion detection

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    // Baseline tracking
    float baseline;
    float baseline_alpha;   // small => slower baseline adaptation

    // Smoothing
    float smooth;
    float smooth_alpha;     // larger => faster smoothing

    // Running normal statistics
    float mean;
    float dev;              // mean absolute deviation approximation
    float stats_alpha;      // adaptation rate for normal behavior

    // Detection
    float threshold_k;      // threshold = mean + k * dev
    float min_threshold;    // absolute minimum threshold
    uint32_t cooldown_samples;
    uint32_t cooldown;

    // Initialization
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float raw_magnitude;
    float detrended;
    float smoothed;
    float threshold;
} DetectionResult;

// Fast absolute value
static inline float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

// Optional: fast approximate magnitude to avoid sqrt on MCUs
static float approx_magnitude(float x, float y, float z) {
    x = fast_absf(x);
    y = fast_absf(y);
    z = fast_absf(z);

    // Sort so x >= y >= z
    if (x < y) { float t = x; x = y; y = t; }
    if (y < z) { float t = y; y = z; z = t; }
    if (x < y) { float t = x; x = y; y = t; }

    // Approximation of Euclidean norm
    return x + 0.25f * y + 0.125f * z;
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0.0f;
    det->baseline_alpha = 0.001f;

    det->smooth = 0.0f;
    det->smooth_alpha = 0.15f;

    det->mean = 0.0f;
    det->dev = 0.0f;
    det->stats_alpha = 0.01f;

    det->threshold_k = 6.0f;
    det->min_threshold = 0.05f;

    det->cooldown_samples = 20;
    det->cooldown = 0;

    det->initialized = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    DetectionResult result = {0};

    // 1. Compute magnitude
    float mag = approx_magnitude(s.ax, s.ay, s.az);
    result.raw_magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->smooth = 0.0f;
        det->mean = 0.0f;
        det->dev = 0.0f;
        det->initialized = true;
    }

    // 2. Track slow baseline (e.g. gravity / orientation drift)
    det->baseline += det->baseline_alpha * (mag - det->baseline);

    // 3. Detrend
    float detrended = mag - det->baseline;
    if (detrended < 0.0f) detrended = -detrended;
    result.detrended = detrended;

    // 4. Smooth
    det->smooth += det->smooth_alpha * (detrended - det->smooth);
    result.smoothed = det->smooth;

    // 5. Update running statistics
    // Optionally freeze stats during cooldown/anomaly periods in real systems
    det->mean += det->stats_alpha * (det->smooth - det->mean);
    float abs_err = fast_absf(det->smooth - det->mean);
    det->dev += det->stats_alpha * (abs_err - det->dev);

    float threshold = det->mean + det->threshold_k * det->dev;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }
    result.threshold = threshold;

    // 6. Cooldown handling
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    // 7. Detect anomaly
    if (det->cooldown == 0 && det->smooth > threshold) {
        result.anomaly = true;
        det->cooldown = det->cooldown_samples;
    } else {
        result.anomaly = false;
    }

    return result;
}
