## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Low-pass baseline estimate for each axis
    int32_t lp_x;
    int32_t lp_y;
    int32_t lp_z;

    // Smoothed energy estimate
    uint32_t energy_avg;
    uint32_t noise_floor;

    // Detection state
    uint16_t cooldown;
    bool anomaly;

    // Config
    uint8_t lp_shift;          // low-pass strength: larger = slower baseline
    uint8_t energy_shift;      // smoothing for energy
    uint8_t noise_shift;       // smoothing for noise floor
    uint16_t threshold_offset; // minimum extra threshold
    uint16_t threshold_scale;  // multiplier on noise floor
    uint16_t cooldown_samples; // refractory period
} AnomalyDetector;

static inline int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

// Fast magnitude approximation: |x| + |y| + |z|
static inline uint32_t accel_mag_l1(const AccelSample *s) {
    return (uint32_t)(iabs32(s->x) + iabs32(s->y) + iabs32(s->z));
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->lp_x = 0;
    det->lp_y = 0;
    det->lp_z = 0;
    det->energy_avg = 0;
    det->noise_floor = 0;
    det->cooldown = 0;
    det->anomaly = false;

    // Tunable parameters
    det->lp_shift = 5;           // ~1/32 baseline update
    det->energy_shift = 3;       // ~1/8 energy smoothing
    det->noise_shift = 5;        // ~1/32 noise floor adaptation
    det->threshold_offset = 500; // fixed margin
    det->threshold_scale = 3;    // threshold = noise_floor * 3 + offset
    det->cooldown_samples = 20;  // suppress repeated triggers
}

// Returns true when a new anomaly is detected on this sample
bool anomaly_detector_process(AnomalyDetector *det, const AccelSample *s) {
    det->anomaly = false;

    // 1. Update low-pass baseline per axis
    det->lp_x += (((int32_t)s->x << 8) - det->lp_x) >> det->lp_shift;
    det->lp_y += (((int32_t)s->y << 8) - det->lp_y) >> det->lp_shift;
    det->lp_z += (((int32_t)s->z << 8) - det->lp_z) >> det->lp_shift;

    // 2. High-pass residual per axis
    int32_t hx = ((int32_t)s->x << 8) - det->lp_x;
    int32_t hy = ((int32_t)s->y << 8) - det->lp_y;
    int32_t hz = ((int32_t)s->z << 8) - det->lp_z;

    // 3. Residual magnitude / energy
    uint32_t residual_mag = (uint32_t)(
        iabs32(hx) + iabs32(hy) + iabs32(hz)
    ) >> 8;

    // Optional: square-like energy proxy without overflow-heavy math
    uint32_t energy = residual_mag * residual_mag;

    // 4. Smooth energy
    det->energy_avg += (energy - det->energy_avg) >> det->energy_shift;

    // 5. Update noise floor only when not in obvious event region
    uint32_t conservative_threshold =
        det->noise_floor * det->threshold_scale + det->threshold_offset;

    if (det->energy_avg < conservative_threshold || det->noise_floor == 0) {
        det->noise_floor += (det->energy_avg - det->noise_floor) >> det->noise_shift;
    }

    // 6. Final adaptive threshold
    uint32_t threshold =
        det->noise_floor * det->threshold_scale + det->threshold_offset;

    // 7. Cooldown handling
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    // 8. Detect anomaly
    if (det->cooldown == 0 && det->energy_avg > threshold) {
        det->anomaly = true;
        det->cooldown = det->cooldown_samples;
    }

    return det->anomaly;
}
