Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Moving average energy estimate
- Adaptive thresholding
- Cooldown / debounce logic
- Fixed-point integer math only

This is designed for low-resource systems without floating point.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>

#define ABS(x) ((x) < 0 ? -(x) : (x))

/*
 * Embedded accelerometer anomaly detector
 *
 * Input:
 *   raw x, y, z accelerometer samples (e.g. in milli-g or ADC counts)
 *
 * Pipeline:
 *   1. Approximate signal magnitude
 *   2. Low-pass filter to estimate baseline
 *   3. High-pass residual = magnitude - baseline
 *   4. Rectify residual
 *   5. Smooth residual energy
 *   6. Adaptive noise floor estimate
 *   7. Trigger anomaly when energy exceeds threshold
 */

typedef struct {
    int32_t baseline;        // low-pass estimate of magnitude
    int32_t energy;          // smoothed rectified residual
    int32_t noise_floor;     // adaptive background level
    uint16_t cooldown;       // debounce counter
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t residual;
    int32_t energy;
    int32_t threshold;
} DetectorOutput;

/* Tunable parameters */
enum {
    BASELINE_SHIFT    = 5,   // baseline LPF alpha = 1/32
    ENERGY_SHIFT      = 3,   // energy LPF alpha = 1/8
    NOISE_SHIFT       = 6,   // noise floor LPF alpha = 1/64
    THRESHOLD_OFFSET  = 50,  // minimum extra margin
    THRESHOLD_SCALE   = 3,   // threshold = noise_floor * scale + offset
    COOLDOWN_SAMPLES  = 20   // suppress repeated triggers
};

/*
 * Fast magnitude approximation:
 * approx |v| ~= max(|x|,|y|,|z|) + 1/2*mid + 1/4*min
 * cheaper than sqrt(x^2+y^2+z^2)
 */
static int32_t approx_magnitude(int16_t x, int16_t y, int16_t z)
{
    int32_t ax = ABS(x);
    int32_t ay = ABS(y);
    int32_t az = ABS(z);

    int32_t max = ax, mid = ay, min = az;

    if (max < mid) { int32_t t = max; max = mid; mid = t; }
    if (mid < min) { int32_t t = mid; mid = min; min = t; }
    if (max < mid) { int32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

void anomaly_detector_init(AnomalyDetector *det)
{
    det->baseline = 0;
    det->energy = 0;
    det->noise_floor = 0;
    det->cooldown = 0;
    det->initialized = false;
}

DetectorOutput anomaly_detector_update(AnomalyDetector *det, int16_t x, int16_t y, int16_t z)
{
    DetectorOutput out = {0};

    int32_t mag = approx_magnitude(x, y, z);

    if (!det->initialized) {
        det->baseline = mag;
        det->energy = 0;
        det->noise_floor = 0;
        det->cooldown = 0;
        det->initialized = true;
    }

    /* 1. Baseline tracking (low-pass) */
    det->baseline += (mag - det->baseline) >> BASELINE_SHIFT;

    /* 2. High-pass residual */
    int32_t residual = mag - det->baseline;
    int32_t rectified = ABS(residual);

    /* 3. Smoothed energy */
    det->energy += (rectified - det->energy) >> ENERGY_SHIFT;

    /*
     * 4. Adaptive noise floor
     * Update more slowly, and optionally only when not in a strong event.
     */
    if (det->energy < (det->noise_floor * 2 + THRESHOLD_OFFSET)) {
        det->noise_floor += (det->energy - det->noise_floor) >> NOISE_SHIFT;
    }

    int32_t threshold = det->noise_floor * THRESHOLD_SCALE + THRESHOLD_OFFSET;

    /* 5. Cooldown handling */
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    /* 6. Anomaly decision */
    bool anomaly = false;
    if (det->cooldown == 0 && det->energy > threshold) {
        anomaly = true;
        det->cooldown = COOLDOWN_SAMPLES;
    }

    out.anomaly = anomaly;
    out.magnitude = mag;
    out.residual = residual;
    out.energy = det->energy;
    out.threshold = threshold;

    return out;
}
