Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:
- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling mean absolute deviation estimate
- Threshold-based anomaly detection with debounce
- Fixed-point integer math only

You can adapt it to Cortex-M, AVR, ESP32, etc.

---

## Design

Pipeline per sample:

1. Read accelerometer `(x, y, z)`
2. Compute signal magnitude approximation
3. Low-pass filter to estimate gravity / slow trend
4. Subtract baseline to get dynamic motion
5. Track noise level with moving estimate
6. Trigger anomaly if residual exceeds adaptive threshold for N samples

This is efficient and robust for vibration/spike detection.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Low-pass baseline of magnitude
    int32_t baseline;

    // Smoothed absolute residual (noise floor estimate)
    int32_t noise_est;

    // Last residual
    int32_t residual;

    // Debounce counters
    uint8_t anomaly_count;
    uint8_t clear_count;

    // Output state
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    // LPF shift: baseline += (mag - baseline) >> lpf_shift
    uint8_t lpf_shift;

    // Noise estimator shift: noise += (abs(residual) - noise) >> noise_shift
    uint8_t noise_shift;

    // Threshold = min_threshold + noise_est * threshold_mult / threshold_div
    uint16_t min_threshold;
    uint16_t threshold_mult;
    uint16_t threshold_div;

    // Number of consecutive samples to assert/clear anomaly
    uint8_t trigger_count;
    uint8_t clear_count;
} AnomalyConfig;

static inline int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

/*
 * Fast magnitude approximation:
 * mag ~= max(|x|,|y|,|z|) + 1/2*mid + 1/4*min
 * Avoids sqrt.
 */
static int32_t accel_magnitude_approx(const AccelSample *s) {
    int32_t ax = iabs32(s->x);
    int32_t ay = iabs32(s->y);
    int32_t az = iabs32(s->z);

    int32_t max = ax, mid = ay, min = az;

    // Sort descending: max >= mid >= min
    if (max < mid) { int32_t t = max; max = mid; mid = t; }
    if (mid < min) { int32_t t = mid; mid = min; min = t; }
    if (max < mid) { int32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

void anomaly_detector_init(AnomalyDetector *det, const AnomalyConfig *cfg, int32_t initial_mag) {
    (void)cfg;
    det->baseline = initial_mag;
    det->noise_est = 0;
    det->residual = 0;
    det->anomaly_count = 0;
    det->clear_count = 0;
    det->anomaly_active = false;
}

/*
 * Returns true if anomaly state is active after processing this sample.
 */
bool anomaly_detector_update(AnomalyDetector *det, const AnomalyConfig *cfg, const AccelSample *sample) {
    int32_t mag = accel_magnitude_approx(sample);

    // Low-pass baseline tracking
    det->baseline += (mag - det->baseline) >> cfg->lpf_shift;

    // High-pass residual
    det->residual = mag - det->baseline;
    int32_t abs_res = iabs32(det->residual);

    // Noise floor estimate
    det->noise_est += (abs_res - det->noise_est) >> cfg->noise_shift;

    // Adaptive threshold
    int32_t threshold = cfg->min_threshold +
                        (det->noise_est * cfg->threshold_mult) / cfg->threshold_div;

    if (abs_res > threshold) {
        if (det->anomaly_count < 255) {
            det->anomaly_count++;
        }
        det->clear_count = 0;

        if (!det->anomaly_active && det->anomaly_count >= cfg->trigger_count) {
            det->anomaly_active = true;
        }
    } else {
        det->anomaly_count = 0;

        if (det->anomaly_active) {
            if (det->clear_count < 255) {
                det->clear_count++;
            }
            if (det->clear_count >= cfg->clear_count) {
                det->anomaly_active = false;
                det->clear_count = 0;
            }
        }
    }

    return det->anomaly_active;
}
```

