## Optional: Ring Buffer + Z-score Detector

If you want a more statistical detector using a rolling window, here is a second version.

```c
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32

typedef struct {
    int16_t buf[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    int32_t sum;
    int32_t sumsq;
} RollingStats;

typedef struct {
    RollingStats stats;
    uint16_t z_threshold_q8; // threshold in Q8, e.g. 3.0 = 768
    bool anomaly;
} ZScoreDetector;

static inline int16_t abs16(int16_t x) {
    return x < 0 ? -x : x;
}

static int16_t accel_feature(const AccelSample *s) {
    // Example feature: sum of abs axes
    return (int16_t)(abs16(s->x) + abs16(s->y) + abs16(s->z));
}

void rolling_stats_init(RollingStats *rs) {
    rs->idx = 0;
    rs->count = 0;
    rs->sum = 0;
    rs->sumsq = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rs->buf[i] = 0;
    }
}

void zscore_detector_init(ZScoreDetector *det, uint16_t z_threshold_q8) {
    rolling_stats_init(&det->stats);
    det->z_threshold_q8 = z_threshold_q8;
    det->anomaly = false;
}

/*
 * Integer sqrt for variance estimate
 */
static uint32_t isqrt32(uint32_t x) {
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1uL << 30;

    while (one > op) one >>= 2;

    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res += 2 * one;
        }
        res >>= 1;
        one >>= 2;
    }
    return res;
}

bool zscore_detector_update(ZScoreDetector *det, const AccelSample *sample) {
    RollingStats *rs = &det->stats;
    int16_t x = accel_feature(sample);

    if (rs->count == WINDOW_SIZE) {
        int16_t old = rs->buf[rs->idx];
        rs->sum -= old;
        rs->sumsq -= (int32_t)old * old;
    } else {
        rs->count++;
    }

    rs->buf[rs->idx] = x;
    rs->sum += x;
    rs->sumsq += (int32_t)x * x;
    rs->idx = (rs->idx + 1) % WINDOW_SIZE;

    if (rs->count < 8) {
        det->anomaly = false;
        return false;
    }

    int32_t mean = rs->sum / rs->count;
    int32_t mean_sq = mean * mean;
    int32_t ex2 = rs->sumsq / rs->count;
    int32_t var = ex2 - mean_sq;
    if (var < 1) var = 1;

    int32_t diff = x - mean;
    uint32_t stddev = isqrt32((uint32_t)var);

    // z-score in Q8
    uint32_t z_q8 = ((uint32_t)(diff < 0 ? -diff : diff) << 8) / stddev;

    det->anomaly = (z_q8 > det->z_threshold_q8);
    return det->anomaly;
}
```

