Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:
- Streaming sample ingestion
- Simple low-pass gravity estimate
- High-pass motion extraction
- Magnitude computation
- Rolling mean/variance
- Z-score based anomaly detection
- Optional cooldown to avoid repeated triggers

You can adapt it for bare-metal, RTOS, or Arduino-style environments.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *   raw accel -> low-pass gravity estimate -> high-pass motion
 *             -> motion magnitude -> rolling stats -> anomaly score
 *
 * Notes:
 * - Assumes accelerometer samples arrive at a fixed rate.
 * - Uses lightweight online statistics over a sliding window.
 * - Designed for embedded systems with limited resources.
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846f
#endif

#define WINDOW_SIZE         64      // rolling statistics window
#define ANOMALY_Z_THRESH    3.5f    // z-score threshold
#define LPF_ALPHA           0.90f   // gravity low-pass filter coefficient
#define COOLDOWN_SAMPLES    20      // suppress repeated alerts
#define EPSILON             1e-6f

typedef struct {
    float x;
    float y;
    float z;
} Vec3;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
} RollingStats;

typedef struct {
    Vec3 gravity_est;
    RollingStats stats;
    uint16_t cooldown;
    bool initialized;
} AnomalyDetector;

typedef struct {
    float raw_magnitude;
    float motion_magnitude;
    float mean;
    float stddev;
    float zscore;
    bool anomaly;
} DetectionResult;

/* ---------- Vector helpers ---------- */

static inline Vec3 vec3_sub(Vec3 a, Vec3 b) {
    Vec3 r = {a.x - b.x, a.y - b.y, a.z - b.z};
    return r;
}

static inline float vec3_mag(Vec3 v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

/* ---------- Rolling statistics ---------- */

static void rolling_stats_init(RollingStats *rs) {
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sum_sq = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        rs->buffer[i] = 0.0f;
    }
}

static void rolling_stats_update(RollingStats *rs, float x) {
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = x;
        rs->sum += x;
        rs->sum_sq += x * x;
        rs->count++;
    } else {
        float old = rs->buffer[rs->index];
        rs->buffer[rs->index] = x;
        rs->sum += x - old;
        rs->sum_sq += x * x - old * old;
    }

    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

static float rolling_stats_mean(const RollingStats *rs) {
    if (rs->count == 0) return 0.0f;
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const RollingStats *rs) {
    if (rs->count < 2) return 0.0f;

    float mean = rolling_stats_mean(rs);
    float var = (rs->sum_sq / (float)rs->count) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

static float rolling_stats_stddev(const RollingStats *rs) {
    return sqrtf(rolling_stats_variance(rs));
}

/* ---------- Detector ---------- */

void anomaly_detector_init(AnomalyDetector *det) {
    det->gravity_est.x = 0.0f;
    det->gravity_est.y = 0.0f;
    det->gravity_est.z = 0.0f;
    det->cooldown = 0;
    det->initialized = false;
    rolling_stats_init(&det->stats);
}

/*
 * Process one accelerometer sample in g or m/s^2.
 * Units must remain consistent.
 */
DetectionResult anomaly_detector_process(AnomalyDetector *det, Vec3 accel_sample) {
    DetectionResult result = {0};

    result.raw_magnitude = vec3_mag(accel_sample);

    // Initialize gravity estimate with first sample
    if (!det->initialized) {
        det->gravity_est = accel_sample;
        det->initialized = true;
    }

    // Low-pass filter to estimate gravity / static component
    det->gravity_est.x = LPF_ALPHA * det->gravity_est.x + (1.0f - LPF_ALPHA) * accel_sample.x;
    det->gravity_est.y = LPF_ALPHA * det->gravity_est.y + (1.0f - LPF_ALPHA) * accel_sample.y;
    det->gravity_est.z = LPF_ALPHA * det->gravity_est.z + (1.0f - LPF_ALPHA) * accel_sample.z;

    // High-pass motion component
    Vec3 motion = vec3_sub(accel_sample, det->gravity_est);
    result.motion_magnitude = vec3_mag(motion);

    // Update rolling statistics on motion magnitude
    rolling_stats_update(&det->stats, result.motion_magnitude);

    result.mean = rolling_stats_mean(&det->stats);
    result.stddev = rolling_stats_stddev(&det->stats);

    if (result.stddev > EPSILON) {
        result.zscore = (result.motion_magnitude - result.mean) / result.stddev;
    } else {
        result.zscore = 0.0f;
    }

    result.anomaly = false;

    // Require enough samples before detection
    if (det->stats.count >= WINDOW_SIZE / 2) {
        if (det->cooldown > 0) {
            det->cooldown--;
        } else if (result.zscore > ANOMALY_Z_THRESH) {
            result.anomaly = true;
            det->cooldown = COOLDOWN_SAMPLES;
        }
    }

    return result;
}
```

