#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Magnitude-based processing
 * - Exponential moving average baseline
 * - Rolling mean/stddev over residuals
 * - Z-score anomaly detection
 * - Consecutive-hit debounce
 *
 * Notes:
 * - Replace sqrtf() if too expensive; squared magnitude can be used instead.
 * - Tune constants for your sensor/sample rate/application.
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE             32
#define BASELINE_ALPHA          0.01f   /* low-pass baseline update */
#define ANOMALY_Z_THRESHOLD     4.0f
#define MIN_STDDEV              0.02f   /* prevents divide-by-near-zero */
#define CONSECUTIVE_TRIGGER     3
#define COOLDOWN_SAMPLES        20

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sumsq;
} RollingStats;

typedef struct {
    float baseline;
    bool baseline_initialized;

    RollingStats residual_stats;

    uint16_t consecutive_hits;
    uint16_t cooldown;

    bool anomaly_active;
    float last_magnitude;
    float last_residual;
    float last_zscore;
} AnomalyDetector;

/* =========================
 * Rolling statistics
 * ========================= */
static void rolling_stats_init(RollingStats *rs)
{
    memset(rs, 0, sizeof(*rs));
}

static void rolling_stats_push(RollingStats *rs, float value)
{
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sumsq += value * value;
        rs->count++;
        rs->index = (rs->index + 1) % WINDOW_SIZE;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sumsq -= old * old;

        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sumsq += value * value;

        rs->index = (rs->index + 1) % WINDOW_SIZE;
    }
}

static float rolling_stats_mean(const RollingStats *rs)
{
    if (rs->count == 0) return 0.0f;
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const RollingStats *rs)
{
    if (rs->count < 2) return 0.0f;

    float mean = rolling_stats_mean(rs);
    float var = (rs->sumsq / (float)rs->count) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

static float rolling_stats_stddev(const RollingStats *rs)
{
    return sqrtf(rolling_stats_variance(rs));
}

/* =========================
 * Detector core
 * ========================= */
static void anomaly_detector_init(AnomalyDetector *det)
{
    memset(det, 0, sizeof(*det));
    rolling_stats_init(&det->residual_stats);
}

static float accel_magnitude(const AccelSample *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static bool anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample)
{
    float mag = accel_magnitude(sample);
    det->last_magnitude = mag;

    /* Initialize baseline on first sample */
    if (!det->baseline_initialized) {
        det->baseline = mag;
        det->baseline_initialized = true;
    }

    /* Low-pass baseline estimate */
    det->baseline = (1.0f - BASELINE_ALPHA) * det->baseline + BASELINE_ALPHA * mag;

    /* High-pass residual */
    float residual = mag - det->baseline;
    det->last_residual = residual;

    /* Compute z-score against rolling residual stats */
    float mean = rolling_stats_mean(&det->residual_stats);
    float stddev = rolling_stats_stddev(&det->residual_stats);
    if (stddev < MIN_STDDEV) {
        stddev = MIN_STDDEV;
    }

    float z = (residual - mean) / stddev;
    det->last_zscore = z;

    /* Update stats after scoring to avoid diluting current anomaly */
    rolling_stats_push(&det->residual_stats, residual);

    bool threshold_hit = fabsf(z) >= ANOMALY_Z_THRESHOLD;

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    if (threshold_hit && det->cooldown == 0) {
        if (det->consecutive_hits < 0xFFFF) {
            det->consecutive_hits++;
        }
    } else {
        det->consecutive_hits = 0;
        det->anomaly_active = false;
    }

    if (det->consecutive_hits >= CONSECUTIVE_TRIGGER) {
        det->anomaly_active = true;
        det->cooldown = COOLDOWN_SAMPLES;
        det->consecutive_hits = 0;
        return true;
    }

    return false;
}
