## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 *
 * Assumptions:
 * - Input samples are in g units or m/s^2, consistently scaled
 * - Called at a fixed sample rate, e.g. 100 Hz
 * - Uses lightweight exponential moving averages
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Baseline tracking
    float baseline_mag;      // slow-moving average of magnitude
    float noise_est;         // average residual/noise level

    // Configuration
    float baseline_alpha;    // e.g. 0.01f
    float noise_alpha;       // e.g. 0.05f
    float threshold_sigma;   // e.g. 4.0f
    float min_noise_floor;   // prevents divide-by-near-zero, e.g. 0.02f
    uint8_t consecutive_hits_required; // e.g. 3
    uint16_t cooldown_samples;         // e.g. 50

    // State
    uint8_t consecutive_hits;
    uint16_t cooldown_counter;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float baseline;
    float residual;
    float score;
} AnomalyResult;

/* Fast magnitude approximation options:
 * 1) exact sqrtf(x*x + y*y + z*z)
 * 2) cheaper approximation if needed
 */
static float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void anomaly_detector_init(AnomalyDetector *det)
{
    det->baseline_mag = 0.0f;
    det->noise_est = 0.0f;

    det->baseline_alpha = 0.01f;
    det->noise_alpha = 0.05f;
    det->threshold_sigma = 4.0f;
    det->min_noise_floor = 0.02f;
    det->consecutive_hits_required = 3;
    det->cooldown_samples = 50;

    det->consecutive_hits = 0;
    det->cooldown_counter = 0;
    det->initialized = false;
}

AnomalyResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample)
{
    AnomalyResult result = {0};

    float mag = accel_magnitude(sample);
    result.magnitude = mag;

    // Initialize baseline on first sample
    if (!det->initialized) {
        det->baseline_mag = mag;
        det->noise_est = det->min_noise_floor;
        det->initialized = true;

        result.baseline = det->baseline_mag;
        result.residual = 0.0f;
        result.score = 0.0f;
        result.anomaly = false;
        return result;
    }

    // Update cooldown
    if (det->cooldown_counter > 0) {
        det->cooldown_counter--;
    }

    // Slow baseline tracks gravity + normal motion envelope
    det->baseline_mag =
        (1.0f - det->baseline_alpha) * det->baseline_mag +
        det->baseline_alpha * mag;

    float residual = fabsf(mag - det->baseline_mag);

    // Track normal residual/noise
    det->noise_est =
        (1.0f - det->noise_alpha) * det->noise_est +
        det->noise_alpha * residual;

    float noise = det->noise_est;
    if (noise < det->min_noise_floor) {
        noise = det->min_noise_floor;
    }

    float score = residual / noise;

    bool hit = (score >= det->threshold_sigma);

    if (hit) {
        if (det->consecutive_hits < 255) {
            det->consecutive_hits++;
        }
    } else {
        det->consecutive_hits = 0;
    }

    bool anomaly = false;
    if (det->cooldown_counter == 0 &&
        det->consecutive_hits >= det->consecutive_hits_required) {
        anomaly = true;
        det->cooldown_counter = det->cooldown_samples;
        det->consecutive_hits = 0;
    }

    result.baseline = det->baseline_mag;
    result.residual = residual;
    result.score = score;
    result.anomaly = anomaly;

    return result;
}
```

