## More Embedded-Friendly Fixed-Point Version

If your MCU lacks an FPU, use integer math. Below is a simplified fixed-point approach.

### Notes
- Represent acceleration in milli-g (`mg`)
- Avoid sqrt by using squared magnitude or Manhattan approximation
- Use integer EMA

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int16_t x_mg;
    int16_t y_mg;
    int16_t z_mg;
} AccelSampleInt;

typedef struct {
    int32_t baseline_mag;
    int32_t noise_est;

    // EMA coefficients as shift factors:
    // new = old + ((input - old) >> shift)
    uint8_t baseline_shift;   // e.g. 6 => alpha ~ 1/64
    uint8_t noise_shift;      // e.g. 4 => alpha ~ 1/16

    uint16_t threshold_ratio; // e.g. 400 => residual > 4.00 * noise
    int32_t min_noise_floor;  // e.g. 20 mg

    uint8_t consecutive_hits_required;
    uint8_t consecutive_hits;
    uint16_t cooldown_samples;
    uint16_t cooldown_counter;

    bool initialized;
} AnomalyDetectorInt;

// Cheap magnitude approximation: |x| + |y| + |z|
static int32_t abs32(int32_t v) {
    return (v < 0) ? -v : v;
}

static int32_t accel_mag_approx_mg(const AccelSampleInt *s) {
    return abs32(s->x_mg) + abs32(s->y_mg) + abs32(s->z_mg);
}

void anomaly_detector_int_init(AnomalyDetectorInt *det)
{
    det->baseline_mag = 0;
    det->noise_est = 0;
    det->baseline_shift = 6;
    det->noise_shift = 4;
    det->threshold_ratio = 400; // 4.00x
    det->min_noise_floor = 20;
    det->consecutive_hits_required = 3;
    det->consecutive_hits = 0;
    det->cooldown_samples = 50;
    det->cooldown_counter = 0;
    det->initialized = false;
}

bool anomaly_detector_int_process(AnomalyDetectorInt *det, const AccelSampleInt *sample)
{
    int32_t mag = accel_mag_approx_mg(sample);

    if (!det->initialized) {
        det->baseline_mag = mag;
        det->noise_est = det->min_noise_floor;
        det->initialized = true;
        return false;
    }

    if (det->cooldown_counter > 0) {
        det->cooldown_counter--;
    }

    det->baseline_mag += ((mag - det->baseline_mag) >> det->baseline_shift);

    int32_t residual = mag - det->baseline_mag;
    if (residual < 0) residual = -residual;

    det->noise_est += ((residual - det->noise_est) >> det->noise_shift);

    int32_t noise = det->noise_est;
    if (noise < det->min_noise_floor) {
        noise = det->min_noise_floor;
    }

    // Compare residual / noise >= threshold without division:
    // residual >= (threshold_ratio / 100) * noise
    bool hit = ((residual * 100) >= ((int32_t)det->threshold_ratio * noise));

    if (hit) {
        if (det->consecutive_hits < 255) {
            det->consecutive_hits++;
        }
    } else {
        det->consecutive_hits = 0;
    }

    if (det->cooldown_counter == 0 &&
        det->consecutive_hits >= det->consecutive_hits_required) {
        det->consecutive_hits = 0;
        det->cooldown_counter = det->cooldown_samples;
        return true;
    }

    return false;
}
```

