## Example: Windowed RMS Detector

If you want a more robust detector for vibration changes, use a window.

```c
#define WINDOW_SIZE 32

typedef struct {
    float baseline;
    float noise;
    float buf[WINDOW_SIZE];
    uint8_t idx;
    bool full;
} RmsDetector;

static float squaref(float x) { return x * x; }

bool rms_detector_process(RmsDetector *d, const AccelSample *s, float *out_rms)
{
    float mag = accel_magnitude(s);

    d->buf[d->idx++] = mag;
    if (d->idx >= WINDOW_SIZE) {
        d->idx = 0;
        d->full = true;
    }

    if (!d->full) {
        *out_rms = 0.0f;
        return false;
    }

    float sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sumsq += squaref(d->buf[i]);
    }

    float rms = sqrtf(sumsq / WINDOW_SIZE);
    *out_rms = rms;

    // Add threshold logic here
    return false;
}
```

