## Design

Pipeline per sample:

1. Read accelerometer `(x, y, z)`
2. Compute signal magnitude
3. Smooth magnitude into a baseline
4. Compute residual = `|magnitude - baseline|`
5. Track normal residual level
6. Trigger anomaly if residual exceeds adaptive threshold

This is lightweight and avoids floating-point-heavy DSP if needed.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

// Configuration parameters
#define LP_SHIFT                4   // baseline low-pass strength: 1/16
#define DEV_SHIFT               5   // deviation low-pass strength: 1/32
#define THRESHOLD_MULTIPLIER    6   // anomaly threshold = dev * multiplier
#define MIN_THRESHOLD           50  // minimum absolute threshold
#define COOLDOWN_SAMPLES        20  // suppress repeated triggers

typedef struct {
    int32_t baseline;          // low-pass filtered magnitude
    int32_t deviation;         // low-pass filtered abs residual
    uint16_t cooldown;         // debounce counter
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t residual;
    int32_t threshold;
} DetectionResult;

/*
 * Fast approximate magnitude:
 * Instead of sqrt(x^2 + y^2 + z^2), use |x| + |y| + |z|
 * Good enough for many embedded anomaly detectors.
 */
static inline int32_t accel_magnitude_l1(const AccelSample *s) {
    return abs(s->x) + abs(s->y) + abs(s->z);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->deviation = 0;
    det->cooldown = 0;
    det->initialized = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample) {
    DetectionResult result = {0};

    int32_t mag = accel_magnitude_l1(sample);
    result.magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->deviation = 0;
        det->cooldown = 0;
        det->initialized = true;
    }

    // Update baseline with exponential moving average
    det->baseline += (mag - det->baseline) >> LP_SHIFT;

    // Residual from baseline
    int32_t residual = mag - det->baseline;
    if (residual < 0) residual = -residual;
    result.residual = residual;

    // Track typical residual level
    det->deviation += (residual - det->deviation) >> DEV_SHIFT;

    int32_t threshold = det->deviation * THRESHOLD_MULTIPLIER;
    if (threshold < MIN_THRESHOLD) {
        threshold = MIN_THRESHOLD;
    }
    result.threshold = threshold;

    // Cooldown handling
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    // Anomaly decision
    if (residual > threshold && det->cooldown == 0) {
        result.anomaly = true;
        det->cooldown = COOLDOWN_SAMPLES;
    } else {
        result.anomaly = false;
    }

    return result;
}
```

