## More Robust Version with Rolling Window

If you want a slightly more advanced detector using a fixed-size ring buffer and z-score-like logic:

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

#define WINDOW_SIZE 32
#define ZSCORE_NUM  4      // trigger when |x - mean| > 4 * avg_abs_dev
#define MIN_DEV     20

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample2;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int64_t sum;
    bool cooldown;
    uint8_t cooldown_count;
} WindowDetector;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t mean;
    int32_t deviation;
    int32_t score;
} WindowResult;

static inline int32_t mag_l1(const AccelSample2 *s) {
    return abs(s->x) + abs(s->y) + abs(s->z);
}

void window_detector_init(WindowDetector *wd) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        wd->buffer[i] = 0;
    }
    wd->index = 0;
    wd->count = 0;
    wd->sum = 0;
    wd->cooldown = false;
    wd->cooldown_count = 0;
}

WindowResult window_detector_process(WindowDetector *wd, const AccelSample2 *s) {
    WindowResult r = {0};
    int32_t mag = mag_l1(s);
    r.magnitude = mag;

    if (wd->count == WINDOW_SIZE) {
        wd->sum -= wd->buffer[wd->index];
    } else {
        wd->count++;
    }

    wd->buffer[wd->index] = mag;
    wd->sum += mag;
    wd->index = (wd->index + 1) % WINDOW_SIZE;

    int32_t mean = (int32_t)(wd->sum / wd->count);
    r.mean = mean;

    int64_t dev_sum = 0;
    for (int i = 0; i < wd->count; i++) {
        int32_t d = wd->buffer[i] - mean;
        if (d < 0) d = -d;
        dev_sum += d;
    }

    int32_t avg_dev = (int32_t)(dev_sum / wd->count);
    if (avg_dev < MIN_DEV) avg_dev = MIN_DEV;
    r.deviation = avg_dev;

    int32_t score = mag - mean;
    if (score < 0) score = -score;
    r.score = score;

    if (wd->cooldown) {
        if (wd->cooldown_count > 0) {
            wd->cooldown_count--;
        } else {
            wd->cooldown = false;
        }
    }

    if (wd->count == WINDOW_SIZE && score > ZSCORE_NUM * avg_dev && !wd->cooldown) {
        r.anomaly = true;
        wd->cooldown = true;
        wd->cooldown_count = 10;
    } else {
        r.anomaly = false;
    }

    return r;
}
