Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample handling
- Magnitude estimation
- Low-pass baseline tracking
- High-pass residual extraction
- Rolling noise estimate
- Threshold-based anomaly detection with cooldown
- Fixed-size buffers, no dynamic allocation

You can adapt it to raw ADC units or calibrated g-units.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *   1. Read x,y,z sample
 *   2. Compute magnitude
 *   3. Low-pass filter magnitude to estimate baseline
 *   4. Compute residual = |magnitude - baseline|
 *   5. Track rolling noise floor
 *   6. Trigger anomaly if residual exceeds adaptive threshold
 *
 * Notes:
 *   - Uses float for clarity; can be converted to fixed-point for MCUs without FPU
 *   - No dynamic memory
 *   - Designed for periodic sampling
 */

#ifndef ABS
#define ABS(x) ((x) < 0 ? -(x) : (x))
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Filter state
    float baseline_mag;      // low-pass estimate of normal magnitude
    float noise_est;         // low-pass estimate of residual/noise
    float last_mag;

    // Parameters
    float alpha_baseline;    // e.g. 0.01f slow baseline tracking
    float alpha_noise;       // e.g. 0.05f noise tracking
    float threshold_k;       // threshold multiplier on noise
    float min_threshold;     // absolute minimum threshold
    uint32_t cooldown_ticks; // suppress repeated triggers
    uint32_t warmup_ticks;   // allow filters to settle

    // Runtime
    uint32_t tick_count;
    uint32_t cooldown_remaining;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float baseline;
    float residual;
    float threshold;
    float noise_est;
} DetectionResult;

/* Fast magnitude approximation option:
 * Replace sqrtf(x*x+y*y+z*z) with a cheaper approximation if needed.
 */
static float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void anomaly_detector_init(
    AnomalyDetector *det,
    float alpha_baseline,
    float alpha_noise,
    float threshold_k,
    float min_threshold,
    uint32_t cooldown_ticks,
    uint32_t warmup_ticks)
{
    det->baseline_mag = 0.0f;
    det->noise_est = 0.0f;
    det->last_mag = 0.0f;

    det->alpha_baseline = alpha_baseline;
    det->alpha_noise = alpha_noise;
    det->threshold_k = threshold_k;
    det->min_threshold = min_threshold;
    det->cooldown_ticks = cooldown_ticks;
    det->warmup_ticks = warmup_ticks;

    det->tick_count = 0;
    det->cooldown_remaining = 0;
    det->initialized = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample) {
    DetectionResult result = {0};

    float mag = accel_magnitude(sample);

    if (!det->initialized) {
        det->baseline_mag = mag;
        det->noise_est = 0.0f;
        det->last_mag = mag;
        det->initialized = true;
    }

    det->tick_count++;

    // Update baseline magnitude slowly
    det->baseline_mag =
        (1.0f - det->alpha_baseline) * det->baseline_mag +
        det->alpha_baseline * mag;

    // Residual from baseline
    float residual = fabsf(mag - det->baseline_mag);

    // Update noise estimate from residual
    det->noise_est =
        (1.0f - det->alpha_noise) * det->noise_est +
        det->alpha_noise * residual;

    // Adaptive threshold
    float threshold = det->threshold_k * det->noise_est;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    bool anomaly = false;

    if (det->cooldown_remaining > 0) {
        det->cooldown_remaining--;
    }

    if (det->tick_count > det->warmup_ticks &&
        det->cooldown_remaining == 0 &&
        residual > threshold) {
        anomaly = true;
        det->cooldown_remaining = det->cooldown_ticks;
    }

    result.anomaly = anomaly;
    result.magnitude = mag;
    result.baseline = det->baseline_mag;
    result.residual = residual;
    result.threshold = threshold;
    result.noise_est = det->noise_est;

    det->last_mag = mag;
    return result;
}
```

