## Example: Windowed Z-score Version

If you want a more statistical detector, here is a ring-buffer approach:

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE 32

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sumsq;
    uint32_t cooldown_remaining;
    uint32_t cooldown_ticks;
    float z_threshold;
} ZScoreDetector;

typedef struct {
    bool anomaly;
    float value;
    float mean;
    float stddev;
    float zscore;
} ZScoreResult;

static void zscore_detector_init(ZScoreDetector *d, float z_threshold, uint32_t cooldown_ticks) {
    memset(d, 0, sizeof(*d));
    d->z_threshold = z_threshold;
    d->cooldown_ticks = cooldown_ticks;
}

static float sample_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static ZScoreResult zscore_detector_process(ZScoreDetector *d, const AccelSample *s) {
    ZScoreResult r = {0};
    float v = sample_magnitude(s);

    if (d->count == WINDOW_SIZE) {
        float old = d->buffer[d->index];
        d->sum -= old;
        d->sumsq -= old * old;
    } else {
        d->count++;
    }

    d->buffer[d->index] = v;
    d->sum += v;
    d->sumsq += v * v;
    d->index = (d->index + 1) % WINDOW_SIZE;

    float mean = d->sum / d->count;
    float variance = (d->sumsq / d->count) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;
    float stddev = sqrtf(variance);

    float z = 0.0f;
    if (stddev > 1e-6f) {
        z = fabsf((v - mean) / stddev);
    }

    if (d->cooldown_remaining > 0) {
        d->cooldown_remaining--;
    }

    bool anomaly = false;
    if (d->count == WINDOW_SIZE && d->cooldown_remaining == 0 && z > d->z_threshold) {
        anomaly = true;
        d->cooldown_remaining = d->cooldown_ticks;
    }

    r.anomaly = anomaly;
    r.value = v;
    r.mean = mean;
    r.stddev = stddev;
    r.zscore = z;
    return r;
}
