Below is an initial embedded-friendly implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple 3-axis accelerometer sample type
- Magnitude computation
- Low-pass filtering
- Rolling statistics
- Z-score based anomaly detection
- A small stateful pipeline API suitable for microcontrollers
- A demo `main()` showing usage

I’ll provide it in C, since that’s common for embedded systems.

---

## Design

Pipeline stages:

1. **Input**: raw accelerometer sample `(x, y, z, timestamp)`
2. **Preprocessing**:
   - compute acceleration magnitude
   - low-pass filter to reduce noise
3. **Feature extraction**:
   - rolling mean
   - rolling standard deviation
4. **Detection**:
   - anomaly if filtered magnitude deviates from rolling mean by more than `threshold * stddev`
   - also supports a minimum stddev floor to avoid instability

This is intentionally simple and lightweight for an initial implementation.

---

## Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

#ifndef PIPELINE_WINDOW_SIZE
#define PIPELINE_WINDOW_SIZE 32
#endif

#ifndef EPSILON_STDDEV
#define EPSILON_STDDEV 0.05f
#endif

typedef struct {
    uint32_t timestamp_ms;
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;                 // low-pass filter coefficient [0..1]
    float anomaly_threshold;     // z-score threshold, e.g. 3.0
    float stddev_floor;          // minimum stddev to avoid divide-by-zero
    uint16_t warmup_samples;     // number of samples before detection is enabled
} PipelineConfig;

typedef struct {
    float buffer[PIPELINE_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
} RollingStats;

typedef struct {
    bool initialized;
    float filtered_value;
} LowPassFilter;

typedef struct {
    bool anomaly;
    float raw_magnitude;
    float filtered_magnitude;
    float mean;
    float stddev;
    float zscore;
} DetectionResult;

typedef struct {
    PipelineConfig config;
    RollingStats stats;
    LowPassFilter lpf;
    uint32_t processed_samples;
} SensorPipeline;

static void rolling_stats_init(RollingStats *rs) {
    memset(rs, 0, sizeof(*rs));
}

static void low_pass_init(LowPassFilter *lpf) {
    lpf->initialized = false;
    lpf->filtered_value = 0.0f;
}

static void sensor_pipeline_init(SensorPipeline *pipeline, const PipelineConfig *config) {
    pipeline->config = *config;
    rolling_stats_init(&pipeline->stats);
    low_pass_init(&pipeline->lpf);
    pipeline->processed_samples = 0;
}

static float accel_magnitude(const AccelSample *sample) {
    return sqrtf(sample->x * sample->x +
                 sample->y * sample->y +
                 sample->z * sample->z);
}

static float low_pass_apply(LowPassFilter *lpf, float input, float alpha) {
    if (!lpf->initialized) {
        lpf->filtered_value = input;
        lpf->initialized = true;
        return input;
    }

    lpf->filtered_value = alpha * input + (1.0f - alpha) * lpf->filtered_value;
    return lpf->filtered_value;
}

static void rolling_stats_update(RollingStats *rs, float value) {
    if (rs->count < PIPELINE_WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->index = (rs->index + 1) % PIPELINE_WINDOW_SIZE;
        rs->count++;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sum_sq -= old * old;

        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->index = (rs->index + 1) % PIPELINE_WINDOW_SIZE;
    }
}

static float rolling_stats_mean(const RollingStats *rs) {
    if (rs->count == 0) {
        return 0.0f;
    }
    return rs->sum / (float)rs->count;
}

static float rolling_stats_stddev(const RollingStats *rs) {
    if (rs->count < 2) {
        return 0.0f;
    }

    float mean = rolling_stats_mean(rs);
    float variance = (rs->sum_sq / (float)rs->count) - (mean * mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }
    return sqrtf(variance);
}

static DetectionResult sensor_pipeline_process(SensorPipeline *pipeline, const AccelSample *sample) {
    DetectionResult result;
    memset(&result, 0, sizeof(result));

    result.raw_magnitude = accel_magnitude(sample);
    result.filtered_magnitude = low_pass_apply(&pipeline->lpf,
                                               result.raw_magnitude,
                                               pipeline->config.alpha);

    rolling_stats_update(&pipeline->stats, result.filtered_magnitude);

    result.mean = rolling_stats_mean(&pipeline->stats);
    result.stddev = rolling_stats_stddev(&pipeline->stats);

    float effective_stddev = result.stddev;
    if (effective_stddev < pipeline->config.stddev_floor) {
        effective_stddev = pipeline->config.stddev_floor;
    }

    result.zscore = fabsf(result.filtered_magnitude - result.mean) / effective_stddev;

    pipeline->processed_samples++;

    bool warmed_up = pipeline->processed_samples >= pipeline->config.warmup_samples;
    bool enough_stats = pipeline->stats.count >= 2;

    result.anomaly = warmed_up &&
                     enough_stats &&
                     (result.zscore > pipeline->config.anomaly_threshold);

    return result;
}

/* Demo */
int main(void) {
    PipelineConfig config = {
        .alpha = 0.2f,
        .anomaly_threshold = 3.0f,
        .stddev_floor = EPSILON_STDDEV,
        .warmup_samples = 10
    };

    SensorPipeline pipeline;
    sensor_pipeline_init(&pipeline, &config);

    AccelSample samples[] = {
        { 0,   0.01f, 0.02f, 1.00f },
        { 10,  0.00f, 0.01f, 0.98f },
        { 20, -0.02f, 0.03f, 1.01f },
        { 30,  0.01f, 0.00f, 0.99f },
        { 40,  0.02f, 0.01f, 1.00f },
        { 50,  0.00f, 0.02f, 1.02f },
        { 60, -0.01f, 0.01f, 0.97f },
        { 70,  0.01f, 0.01f, 1.00f },
        { 80,  0.00f, 0.00f, 0.99f },
        { 90,  0.01f, 0.02f, 1.01f },
        { 100, 1.50f, 1.20f, 2.00f }, // anomaly
        { 110, 0.00f, 0.01f, 1.00f },
    };

    size_t n = sizeof(samples) / sizeof(samples[0]);
    for (size_t i = 0; i < n; i++) {
        DetectionResult r = sensor_pipeline_process(&pipeline, &samples[i]);

        printf("t=%lu ms raw=%.3f filt=%.3f mean=%.3f std=%.3f z=%.3f anomaly=%s\n",
               (unsigned long)samples[i].timestamp_ms,
               r.raw_magnitude,
               r.filtered_magnitude,
               r.mean,
               r.stddev,
               r.zscore,
               r.anomaly ? "YES" : "NO");
    }

    return 0;
}
```

