Below is a compact initial implementation of an embedded-friendly sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple 3-axis accelerometer sample type
- Magnitude computation
- Low-pass baseline estimation
- Residual/error extraction
- Sliding window statistics
- Threshold-based anomaly detection with hysteresis
- A small C implementation suitable for microcontrollers

---

## Design goals

This initial version is meant to be:

- Simple
- Deterministic
- Low memory
- No dynamic allocation
- Easy to tune

It is not ML-based. It uses statistical deviation from a slowly changing baseline.

---

## Detection approach

For each accelerometer sample:

1. Read `ax, ay, az`
2. Compute signal magnitude:
   `mag = sqrt(ax² + ay² + az²)`
3. Estimate a slow baseline with an IIR low-pass filter
4. Compute residual:
   `residual = |mag - baseline|`
5. Track residual statistics over a fixed window
6. Trigger anomaly if:
   - residual is above a threshold derived from mean/stddev, or
   - residual exceeds an absolute threshold
7. Use hysteresis / consecutive counts to reduce false positives

This works reasonably well for:

- sudden shocks
- vibration changes
- motion spikes
- sensor mounting disturbances

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef ANOMALY_WINDOW_SIZE
#define ANOMALY_WINDOW_SIZE 32
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float baseline_alpha;        // e.g. 0.01f
    float abs_threshold;         // e.g. 2.0f (depends on units)
    float stddev_multiplier;     // e.g. 3.0f
    uint8_t trigger_count;       // consecutive hits to trigger
    uint8_t clear_count;         // consecutive normal samples to clear
} AnomalyConfig;

typedef struct {
    float residual_buffer[ANOMALY_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    float baseline;
    bool baseline_initialized;

    uint8_t anomaly_hits;
    uint8_t normal_hits;
    bool anomaly_active;

    float last_magnitude;
    float last_residual;
    float mean_residual;
    float stddev_residual;
} AnomalyState;

typedef struct {
    bool anomaly;
    float magnitude;
    float baseline;
    float residual;
    float mean_residual;
    float stddev_residual;
    float dynamic_threshold;
} AnomalyResult;

static void anomaly_init(AnomalyState *state)
{
    memset(state, 0, sizeof(*state));
}

static float compute_magnitude(const AccelSample *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static void update_baseline(AnomalyState *state, float magnitude, float alpha)
{
    if (!state->baseline_initialized) {
        state->baseline = magnitude;
        state->baseline_initialized = true;
        return;
    }

    state->baseline = alpha * magnitude + (1.0f - alpha) * state->baseline;
}

static void push_residual(AnomalyState *state, float residual)
{
    state->residual_buffer[state->index] = residual;
    state->index = (state->index + 1) % ANOMALY_WINDOW_SIZE;

    if (state->count < ANOMALY_WINDOW_SIZE) {
        state->count++;
    }
}

static void compute_window_stats(const AnomalyState *state, float *mean, float *stddev)
{
    if (state->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float sum = 0.0f;
    for (uint16_t i = 0; i < state->count; i++) {
        sum += state->residual_buffer[i];
    }
    *mean = sum / (float)state->count;

    float var = 0.0f;
    for (uint16_t i = 0; i < state->count; i++) {
        float d = state->residual_buffer[i] - *mean;
        var += d * d;
    }
    var /= (float)state->count;
    *stddev = sqrtf(var);
}

static AnomalyResult anomaly_process_sample(
    AnomalyState *state,
    const AnomalyConfig *cfg,
    const AccelSample *sample)
{
    AnomalyResult result = {0};

    float mag = compute_magnitude(sample);
    update_baseline(state, mag, cfg->baseline_alpha);

    float residual = fabsf(mag - state->baseline);
    push_residual(state, residual);

    float mean = 0.0f;
    float stddev = 0.0f;
    compute_window_stats(state, &mean, &stddev);

    float dynamic_threshold = mean + cfg->stddev_multiplier * stddev;

    bool hit = false;
    if (residual > cfg->abs_threshold) {
        hit = true;
    }
    if (residual > dynamic_threshold && state->count >= ANOMALY_WINDOW_SIZE / 2) {
        hit = true;
    }

    if (hit) {
        if (state->anomaly_hits < 255) {
            state->anomaly_hits++;
        }
        state->normal_hits = 0;
    } else {
        if (state->normal_hits < 255) {
            state->normal_hits++;
        }
        state->anomaly_hits = 0;
    }

    if (!state->anomaly_active && state->anomaly_hits >= cfg->trigger_count) {
        state->anomaly_active = true;
    } else if (state->anomaly_active && state->normal_hits >= cfg->clear_count) {
        state->anomaly_active = false;
    }

    state->last_magnitude = mag;
    state->last_residual = residual;
    state->mean_residual = mean;
    state->stddev_residual = stddev;

    result.anomaly = state->anomaly_active;
    result.magnitude = mag;
    result.baseline = state->baseline;
    result.residual = residual;
    result.mean_residual = mean;
    result.stddev_residual = stddev;
    result.dynamic_threshold = dynamic_threshold;

    return result;
}
```

