# C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Notes:
 * - Uses fixed-size buffers only
 * - Assumes samples arrive at a fixed rate
 * - Uses simple low-pass filtering and threshold detection
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define WINDOW_SIZE             32
#define LPF_ALPHA               0.2f

/* Thresholds should be tuned on real data */
#define PEAK_THRESHOLD_G        2.5f
#define VAR_THRESHOLD_G2        0.15f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float peak;
    bool anomaly;
} FeatureResult;

typedef struct {
    /* Low-pass filter state */
    float filt_x;
    float filt_y;
    float filt_z;
    bool filter_initialized;

    /* Sliding window of magnitudes */
    float mag_window[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    /* Optional running state */
    FeatureResult last_result;
} SensorPipeline;

/* Initialize pipeline */
void sensor_pipeline_init(SensorPipeline *p)
{
    memset(p, 0, sizeof(SensorPipeline));
}

/* First-order low-pass filter */
static float lpf_update(float input, float prev, float alpha)
{
    return alpha * input + (1.0f - alpha) * prev;
}

/* Filter accelerometer sample */
static AccelSample filter_sample(SensorPipeline *p, AccelSample in)
{
    AccelSample out;

    if (!p->filter_initialized) {
        p->filt_x = in.x;
        p->filt_y = in.y;
        p->filt_z = in.z;
        p->filter_initialized = true;
    } else {
        p->filt_x = lpf_update(in.x, p->filt_x, LPF_ALPHA);
        p->filt_y = lpf_update(in.y, p->filt_y, LPF_ALPHA);
        p->filt_z = lpf_update(in.z, p->filt_z, LPF_ALPHA);
    }

    out.x = p->filt_x;
    out.y = p->filt_y;
    out.z = p->filt_z;
    return out;
}

/* Compute vector magnitude in g */
static float compute_magnitude(AccelSample s)
{
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* Update sliding window */
static void update_window(SensorPipeline *p, float mag)
{
    p->mag_window[p->index] = mag;
    p->index = (p->index + 1) % WINDOW_SIZE;

    if (p->count < WINDOW_SIZE) {
        p->count++;
    }
}

/* Compute features over current window */
static FeatureResult compute_features(const SensorPipeline *p)
{
    FeatureResult r = {0};
    if (p->count == 0) {
        return r;
    }

    float sum = 0.0f;
    float peak = p->mag_window[0];

    for (uint16_t i = 0; i < p->count; i++) {
        float v = p->mag_window[i];
        sum += v;
        if (v > peak) {
            peak = v;
        }
    }

    float mean = sum / (float)p->count;

    float var_sum = 0.0f;
    for (uint16_t i = 0; i < p->count; i++) {
        float d = p->mag_window[i] - mean;
        var_sum += d * d;
    }

    float variance = var_sum / (float)p->count;

    r.mean = mean;
    r.variance = variance;
    r.peak = peak;
    r.anomaly = (peak > PEAK_THRESHOLD_G) || (variance > VAR_THRESHOLD_G2);

    return r;
}

/*
 * Process one accelerometer sample.
 *
 * Returns true if a full window is available and result is updated.
 * The latest result is written to *out_result if non-NULL.
 */
bool sensor_pipeline_process(SensorPipeline *p, AccelSample raw, FeatureResult *out_result)
{
    AccelSample filtered = filter_sample(p, raw);
    float mag = compute_magnitude(filtered);

    update_window(p, mag);

    if (p->count < WINDOW_SIZE) {
        return false;
    }

    p->last_result = compute_features(p);

    if (out_result) {
        *out_result = p->last_result;
    }

    return true;
}
```

