typedef struct {
    float alpha;              // low-pass filter coefficient
    float z_threshold;        // anomaly z-score threshold
    float min_stddev;         // avoid divide-by-zero / oversensitivity
    uint16_t warmup_samples;  // samples before detection starts
    uint16_t consecutive_limit;
