    uint32_t sample_count;
    float mean;
    float m2;

    // State
    uint16_t consecutive_anomaly_count;
    uint16_t cooldown_remaining;
    bool initialized;
} DetectorState;

typedef struct {
    bool valid;
    bool anomaly;
    float magnitude;
    float mean;
    float stddev;
    float z_score;
} DetectorOutput;

