## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <string.h>

static float absf_local(float x) {
    return (x < 0.0f) ? -x : x;
}

static float maxf_local(float a, float b) {
    return (a > b) ? a : b;
}

void detector_init(DetectorState *state, const DetectorConfig *config) {
    (void)config;
    memset(state, 0, sizeof(*state));
}

static void low_pass_filter(
    DetectorState *state,
    const DetectorConfig *config,
    const AccelSample *sample
) {
    if (!state->initialized) {
        state->fax = sample->ax;
        state->fay = sample->ay;
        state->faz = sample->az;
        state->initialized = true;
        return;
    }

    float a = config->alpha;
    state->fax = a * sample->ax + (1.0f - a) * state->fax;
    state->fay = a * sample->ay + (1.0f - a) * state->fay;
    state->faz = a * sample->az + (1.0f - a) * state->faz;
}

static float compute_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void update_stats(DetectorState *state, float x) {
    state->sample_count++;

    float delta = x - state->mean;
    state->mean += delta / (float)state->sample_count;
    float delta2 = x - state->mean;
    state->m2 += delta * delta2;
}

static float compute_stddev(const DetectorState *state) {
    if (state->sample_count < 2) {
        return 0.0f;
    }
    float variance = state->m2 / (float)(state->sample_count - 1);
    return (variance > 0.0f) ? sqrtf(variance) : 0.0f;
}

DetectorOutput detector_process_sample(
    DetectorState *state,
    const DetectorConfig *config,
    const AccelSample *sample
) {
    DetectorOutput out;
    out.valid = false;
    out.anomaly = false;
    out.magnitude = 0.0f;
    out.mean = 0.0f;
    out.stddev = 0.0f;
    out.z_score = 0.0f;

    low_pass_filter(state, config, sample);

    float mag = compute_magnitude(state->fax, state->fay, state->faz);
    update_stats(state, mag);

    float stddev = compute_stddev(state);
    float effective_stddev = maxf_local(stddev, config->min_stddev);

    float z = absf_local(mag - state->mean) / effective_stddev;

    out.valid = (state->sample_count >= config->warmup_samples);
    out.magnitude = mag;
    out.mean = state->mean;
    out.stddev = stddev;
    out.z_score = z;

    if (!out.valid) {
        return out;
    }

    if (state->cooldown_remaining > 0) {
        state->cooldown_remaining--;
        return out;
    }

    if (z > config->z_threshold) {
        if (state->consecutive_anomaly_count < 0xFFFF) {
            state->consecutive_anomaly_count++;
        }
    } else {
        state->consecutive_anomaly_count = 0;
    }

    if (state->consecutive_anomaly_count >= config->consecutive_limit) {
        out.anomaly = true;
        state->consecutive_anomaly_count = 0;
        state->cooldown_remaining = config->cooldown_samples;
    }

    return out;
}
