## Source: `anomaly_detector_ema.c`

```c
#include "anomaly_detector_ema.h"
#include <math.h>
#include <string.h>

static float absf_local(float x) {
    return (x < 0.0f) ? -x : x;
}

static float maxf_local(float a, float b) {
    return (a > b) ? a : b;
}

void detector_ema_init(DetectorEmaState *state) {
    memset(state, 0, sizeof(*state));
}

static float magnitude3(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

DetectorEmaOutput detector_ema_process_sample(
    DetectorEmaState *state,
    const DetectorEmaConfig *config,
    const AccelSampleEma *sample
) {
    DetectorEmaOutput out = {0};

    if (!state->initialized) {
        state->fax = sample->ax;
        state->fay = sample->ay;
        state->faz = sample->az;

        float mag0 = magnitude3(state->fax, state->fay, state->faz);
        state->mean = mag0;
        state->var = 0.0f;
        state->sample_count = 1;
        state->initialized = true;

        out.magnitude = mag0;
        out.mean = state->mean;
        out.stddev = 0.0f;
        out.z_score = 0.0f;
        out.valid = false;
        out.anomaly = false;
        return out;
    }

    float aa = config->axis_alpha;
    state->fax = aa * sample->ax + (1.0f - aa) * state->fax;
    state->fay = aa * sample->ay + (1.0f - aa) * state->fay;
    state->faz = aa * sample->az + (1.0f - aa) * state->faz;

    float mag = magnitude3(state->fax, state->fay, state->faz);

    float diff = mag - state->mean;
    float ba = config->baseline_alpha;
    state->mean = ba * mag + (1.0f - ba) * state->mean;
    state->var = ba * (diff * diff) + (1.0f - ba) * state->var;

    state->sample_count++;

    float stddev = sqrtf(maxf_local(state->var, 0.0f));
    float effective_stddev = maxf_local(stddev, config->min_stddev);
    float z = absf_local(mag - state->mean) / effective_stddev;

    out.valid = (state->sample_count >= config->warmup_samples);
    out.anomaly = false;
    out.magnitude = mag;
    out.mean = state->mean;
    out.stddev = stddev;
    out.z_score = z;

    if (!out.valid) {
        return out;
    }

    if (state->cooldown_remaining > 0) {
        state->cooldown_remaining--;
        return out;
    }

    if (z > config->z_threshold) {
        if (state->consecutive_anomaly_count < 0xFFFF) {
            state->consecutive_anomaly_count++;
        }
    } else {
        state->consecutive_anomaly_count = 0;
    }

    if (state->consecutive_anomaly_count >= config->consecutive_limit) {
        out.anomaly = true;
        state->consecutive_anomaly_count = 0;
        state->cooldown_remaining = config->cooldown_samples;
    }

    return out;
}
```

