## C implementation

### `sensor_pipeline.h`

```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

#define SP_WINDOW_SIZE 64

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float peak_to_peak;
} FeatureVector;

typedef struct {
    float baseline_x;
    float baseline_y;
    float baseline_z;

    float mag_window[SP_WINDOW_SIZE];
    uint16_t window_index;
    uint16_t sample_count;
    bool window_full;

    FeatureVector last_features;

    float expected_mean;
    float expected_variance;
    float expected_peak_to_peak;

    float threshold;
    float alpha_baseline;   // low-pass coefficient for baseline tracking
} SensorPipeline;

void sp_init(SensorPipeline *sp,
             float expected_mean,
             float expected_variance,
             float expected_peak_to_peak,
             float threshold,
             float alpha_baseline);

bool sp_process_sample(SensorPipeline *sp, AccelSample sample, float *out_score);

FeatureVector sp_extract_features(const float *window, uint16_t len);

#ifdef __cplusplus
}
#endif

#endif
```

