### `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"

static float sp_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float sp_sqrtf_approx(float x) {
    if (x <= 0.0f) return 0.0f;

    float guess = x;
    for (int i = 0; i < 6; i++) {
        guess = 0.5f * (guess + x / guess);
    }
    return guess;
}

void sp_init(SensorPipeline *sp,
             float expected_mean,
             float expected_variance,
             float expected_peak_to_peak,
             float threshold,
             float alpha_baseline)
{
    if (!sp) return;

    sp->baseline_x = 0.0f;
    sp->baseline_y = 0.0f;
    sp->baseline_z = 0.0f;

    for (uint16_t i = 0; i < SP_WINDOW_SIZE; i++) {
        sp->mag_window[i] = 0.0f;
    }

    sp->window_index = 0;
    sp->sample_count = 0;
    sp->window_full = false;

    sp->last_features.mean = 0.0f;
    sp->last_features.variance = 0.0f;
    sp->last_features.peak_to_peak = 0.0f;

    sp->expected_mean = expected_mean;
    sp->expected_variance = expected_variance;
    sp->expected_peak_to_peak = expected_peak_to_peak;

    sp->threshold = threshold;
    sp->alpha_baseline = alpha_baseline;
}

static void sp_update_baseline(SensorPipeline *sp, AccelSample *sample) {
    sp->baseline_x = (1.0f - sp->alpha_baseline) * sp->baseline_x + sp->alpha_baseline * sample->x;
    sp->baseline_y = (1.0f - sp->alpha_baseline) * sp->baseline_y + sp->alpha_baseline * sample->y;
    sp->baseline_z = (1.0f - sp->alpha_baseline) * sp->baseline_z + sp->alpha_baseline * sample->z;

    sample->x -= sp->baseline_x;
    sample->y -= sp->baseline_y;
    sample->z -= sp->baseline_z;
}

static float sp_compute_magnitude(AccelSample sample) {
    float mag2 = sample.x * sample.x + sample.y * sample.y + sample.z * sample.z;
    return sp_sqrtf_approx(mag2);
}

FeatureVector sp_extract_features(const float *window, uint16_t len) {
    FeatureVector fv = {0};

    if (!window || len == 0) {
        return fv;
    }

    float sum = 0.0f;
    float min_v = window[0];
    float max_v = window[0];

    for (uint16_t i = 0; i < len; i++) {
        float v = window[i];
        sum += v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }

    fv.mean = sum / (float)len;
    fv.peak_to_peak = max_v - min_v;

    float var_sum = 0.0f;
    for (uint16_t i = 0; i < len; i++) {
        float d = window[i] - fv.mean;
        var_sum += d * d;
    }
    fv.variance = var_sum / (float)len;

    return fv;
}

static float sp_compute_anomaly_score(const SensorPipeline *sp, const FeatureVector *fv) {
    float d_mean = sp_absf(fv->mean - sp->expected_mean);
    float d_var  = sp_absf(fv->variance - sp->expected_variance);
    float d_p2p  = sp_absf(fv->peak_to_peak - sp->expected_peak_to_peak);

    return d_mean + d_var + d_p2p;
}

bool sp_process_sample(SensorPipeline *sp, AccelSample sample, float *out_score) {
    if (!sp) return false;

    sp_update_baseline(sp, &sample);
    float mag = sp_compute_magnitude(sample);

    sp->mag_window[sp->window_index] = mag;
    sp->window_index = (sp->window_index + 1) % SP_WINDOW_SIZE;

    if (sp->sample_count < SP_WINDOW_SIZE) {
        sp->sample_count++;
    } else {
        sp->window_full = true;
    }

    if (!sp->window_full && sp->sample_count < SP_WINDOW_SIZE) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    FeatureVector fv = sp_extract_features(sp->mag_window, SP_WINDOW_SIZE);
    sp->last_features = fv;

    float score = sp_compute_anomaly_score(sp, &fv);
    if (out_score) *out_score = score;

    return (score > sp->threshold);
}
```

