# 3. C implementation

## Header: `anomaly_pipeline.h`

```c
#ifndef ANOMALY_PIPELINE_H
#define ANOMALY_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // Bias calibration
    float bias_x;
    float bias_y;
    float bias_z;

    // Low-pass filter state
    float lp_x;
    float lp_y;
    float lp_z;
    float alpha;   // 0..1, higher = less smoothing

    // Rolling baseline stats for magnitude
    float mean;
    float var;
    float stats_alpha; // EMA factor for baseline update

    // Detection parameters
    float z_threshold;         // anomaly if z-score exceeds this
    uint16_t persistence_limit; // consecutive samples required
    uint16_t persistence_count;

    // Runtime outputs
    float last_mag;
    float last_score;
    bool anomaly;

    // Initialization state
    bool initialized;
} anomaly_pipeline_t;

void anomaly_pipeline_init(anomaly_pipeline_t *p,
                           float alpha,
                           float stats_alpha,
                           float z_threshold,
                           uint16_t persistence_limit,
                           float bias_x,
                           float bias_y,
                           float bias_z);

bool anomaly_pipeline_process(anomaly_pipeline_t *p,
                              const accel_sample_t *sample,
                              float *out_score,
                              float *out_mag);

#ifdef __cplusplus
}
#endif

#endif // ANOMALY_PIPELINE_H
```

---

## Source: `anomaly_pipeline.c`

```c
#include "anomaly_pipeline.h"
#include <math.h>
#include <stddef.h>

#define MIN_STDDEV 0.01f

static float clamp_positive(float x) {
    return (x > 0.0f) ? x : 0.0f;
}

void anomaly_pipeline_init(anomaly_pipeline_t *p,
                           float alpha,
                           float stats_alpha,
                           float z_threshold,
                           uint16_t persistence_limit,
                           float bias_x,
                           float bias_y,
                           float bias_z)
{
    if (p == NULL) {
        return;
    }

    p->bias_x = bias_x;
    p->bias_y = bias_y;
    p->bias_z = bias_z;

    p->lp_x = 0.0f;
    p->lp_y = 0.0f;
    p->lp_z = 0.0f;
    p->alpha = alpha;

    p->mean = 0.0f;
    p->var = 1.0f;
    p->stats_alpha = stats_alpha;

    p->z_threshold = z_threshold;
    p->persistence_limit = persistence_limit;
    p->persistence_count = 0;

    p->last_mag = 0.0f;
    p->last_score = 0.0f;
    p->anomaly = false;
    p->initialized = false;
}

bool anomaly_pipeline_process(anomaly_pipeline_t *p,
                              const accel_sample_t *sample,
                              float *out_score,
                              float *out_mag)
{
    if ((p == NULL) || (sample == NULL)) {
        return false;
    }

    // 1. Bias correction
    float x = sample->x - p->bias_x;
    float y = sample->y - p->bias_y;
    float z = sample->z - p->bias_z;

    // 2. Initialize LP state on first sample
    if (!p->initialized) {
        p->lp_x = x;
        p->lp_y = y;
        p->lp_z = z;

        float mag0 = sqrtf(x*x + y*y + z*z);
        p->mean = mag0;
        p->var = 1.0f;
        p->last_mag = mag0;
        p->last_score = 0.0f;
        p->anomaly = false;
        p->initialized = true;

        if (out_score) *out_score = 0.0f;
        if (out_mag) *out_mag = mag0;
        return false;
    }

    // 3. Low-pass filter
    p->lp_x = p->alpha * x + (1.0f - p->alpha) * p->lp_x;
    p->lp_y = p->alpha * y + (1.0f - p->alpha) * p->lp_y;
    p->lp_z = p->alpha * z + (1.0f - p->alpha) * p->lp_z;

    // 4. Magnitude
    float mag = sqrtf(p->lp_x * p->lp_x +
                      p->lp_y * p->lp_y +
                      p->lp_z * p->lp_z);

    // 5. Rolling mean/variance using exponential moving estimates
    float delta = mag - p->mean;
    p->mean += p->stats_alpha * delta;

    float delta2 = mag - p->mean;
    p->var = (1.0f - p->stats_alpha) * p->var + p->stats_alpha * (delta * delta2);
    p->var = clamp_positive(p->var);

    float stddev = sqrtf(p->var);
    if (stddev < MIN_STDDEV) {
        stddev = MIN_STDDEV;
    }

    // 6. Anomaly score = z-score
    float score = fabsf(mag - p->mean) / stddev;

    // 7. Persistence logic
    if (score > p->z_threshold) {
        if (p->persistence_count < p->persistence_limit) {
            p->persistence_count++;
        }
    } else {
        p->persistence_count = 0;
    }

    p->anomaly = (p->persistence_count >= p->persistence_limit);
    p->last_mag = mag;
    p->last_score = score;

    if (out_score) *out_score = score;
    if (out_mag) *out_mag = mag;

    return p->anomaly;
}
```

