#define AD_WINDOW_SIZE 32

typedef struct {
    float ax;
    float ay;
    float az;
    uint32_t timestamp_ms;
} AccelSample;

typedef struct {
    float mean_mag;
    float var_mag;
    float mean_jerk;
    float max_mag;
} AccelFeatures;

typedef struct {
    // Configuration
    float alpha;                  // smoothing factor for LPF
    float mean_mag_threshold;     // threshold for sustained acceleration
    float var_mag_threshold;      // threshold for vibration
    float jerk_threshold;         // threshold for abrupt changes
    uint8_t consecutive_limit;    // windows required before anomaly asserted

    // State
    float smoothed_mag;
    float prev_mag;
    float mag_window[AD_WINDOW_SIZE];
    float jerk_window[AD_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    bool window_full;

    uint8_t anomaly_streak;
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    bool valid_features;
    AccelFeatures features;
    float anomaly_score;
    bool anomaly_detected;
} DetectorOutput;

void anomaly_detector_init(AnomalyDetector *det);
void anomaly_detector_reset(AnomalyDetector *det);
DetectorOutput anomaly_detector_process_sample(AnomalyDetector *det, const AccelSample *sample);

