## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"

static float absf_local(float x) {
    return (x < 0.0f) ? -x : x;
}

// Lightweight magnitude approximation to avoid sqrtf:
// |a| ≈ max(|x|,|y|,|z|) + 0.5 * mid + 0.25 * min
static float approx_magnitude(float x, float y, float z) {
    float ax = absf_local(x);
    float ay = absf_local(y);
    float az = absf_local(z);

    float maxv = ax;
    float midv = ay;
    float minv = az;

    // sort 3 values descending: maxv >= midv >= minv
    if (maxv < midv) { float t = maxv; maxv = midv; midv = t; }
    if (midv < minv) { float t = midv; midv = minv; minv = t; }
    if (maxv < midv) { float t = maxv; maxv = midv; midv = t; }

    return maxv + 0.5f * midv + 0.25f * minv;
}

static float low_pass(float prev, float input, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

static AccelFeatures compute_features(const AnomalyDetector *det) {
    AccelFeatures f = {0};
    if (det->count == 0) {
        return f;
    }

    float sum_mag = 0.0f;
    float sum_jerk = 0.0f;
    float max_mag = det->mag_window[0];

    for (uint8_t i = 0; i < det->count; i++) {
        sum_mag += det->mag_window[i];
        sum_jerk += det->jerk_window[i];
        if (det->mag_window[i] > max_mag) {
            max_mag = det->mag_window[i];
        }
    }

    float mean_mag = sum_mag / det->count;
    float mean_jerk = sum_jerk / det->count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < det->count; i++) {
        float d = det->mag_window[i] - mean_mag;
        var_sum += d * d;
    }

    f.mean_mag = mean_mag;
    f.var_mag = var_sum / det->count;
    f.mean_jerk = mean_jerk;
    f.max_mag = max_mag;

    return f;
}

static float compute_anomaly_score(const AnomalyDetector *det, const AccelFeatures *f) {
    float score = 0.0f;

    if (f->mean_mag > det->mean_mag_threshold) {
        score += (f->mean_mag / det->mean_mag_threshold);
    }
    if (f->var_mag > det->var_mag_threshold) {
        score += (f->var_mag / det->var_mag_threshold);
    }
    if (f->mean_jerk > det->jerk_threshold) {
        score += (f->mean_jerk / det->jerk_threshold);
    }

    return score;
}

void anomaly_detector_init(AnomalyDetector *det) {
    if (!det) return;

    det->alpha = 0.2f;
    det->mean_mag_threshold = 1.3f;   // tune per sensor units
    det->var_mag_threshold = 0.05f;
    det->jerk_threshold = 0.15f;
    det->consecutive_limit = 3;

    anomaly_detector_reset(det);
}

void anomaly_detector_reset(AnomalyDetector *det) {
    if (!det) return;

    det->smoothed_mag = 0.0f;
    det->prev_mag = 0.0f;
    det->index = 0;
    det->count = 0;
    det->window_full = false;
    det->anomaly_streak = 0;
    det->anomaly_active = false;

    for (uint8_t i = 0; i < AD_WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
        det->jerk_window[i] = 0.0f;
    }
}

DetectorOutput anomaly_detector_process_sample(AnomalyDetector *det, const AccelSample *sample) {
    DetectorOutput out = {0};

    if (!det || !sample) {
        return out;
    }

    // 1. Compute approximate magnitude
    float mag = approx_magnitude(sample->ax, sample->ay, sample->az);

    // 2. Smooth it
    if (det->count == 0 && !det->window_full) {
        det->smoothed_mag = mag;
    } else {
        det->smoothed_mag = low_pass(det->smoothed_mag, mag, det->alpha);
    }

    // 3. Compute jerk from smoothed magnitude
    float jerk = absf_local(det->smoothed_mag - det->prev_mag);
    det->prev_mag = det->smoothed_mag;

    // 4. Store in circular buffers
    det->mag_window[det->index] = det->smoothed_mag;
    det->jerk_window[det->index] = jerk;

    det->index++;
    if (det->index >= AD_WINDOW_SIZE) {
        det->index = 0;
        det->window_full = true;
    }

    if (!det->window_full && det->count < AD_WINDOW_SIZE) {
        det->count++;
    } else if (det->window_full) {
        det->count = AD_WINDOW_SIZE;
    }

    // 5. Only emit valid features once enough samples collected
    if (det->count < AD_WINDOW_SIZE) {
        out.valid_features = false;
        return out;
    }

    out.valid_features = true;
    out.features = compute_features(det);

    // 6. Score anomaly
    out.anomaly_score = compute_anomaly_score(det, &out.features);

    bool window_anomaly =
        (out.features.mean_mag > det->mean_mag_threshold) ||
        (out.features.var_mag > det->var_mag_threshold) ||
        (out.features.mean_jerk > det->jerk_threshold);

    // 7. Persistence / debounce
    if (window_anomaly) {
        if (det->anomaly_streak < 255) {
            det->anomaly_streak++;
        }
    } else {
        det->anomaly_streak = 0;
        det->anomaly_active = false;
    }

    if (det->anomaly_streak >= det->consecutive_limit) {
        det->anomaly_active = true;
    }

    out.anomaly_detected = det->anomaly_active;
    return out;
}
```

