## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <string.h>

static float compute_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static float safe_div(float a, float b) {
    return (b > 1e-6f) ? (a / b) : 0.0f;
}

void anomaly_detector_init(AnomalyDetector *det) {
    memset(det, 0, sizeof(*det));

    det->baseline_alpha = 0.01f;   // slow baseline tracking
    det->baseline = 1.0f;          // assume ~1g initial magnitude if stationary

    // Nominal feature values; tune from real data
    det->var_nominal = 0.02f;
    det->peak_nominal = 0.20f;
    det->zc_nominal = 8.0f;

    // Feature weights
    det->w_var = 0.5f;
    det->w_peak = 0.3f;
    det->w_zc = 0.2f;

    det->anomaly_threshold = 2.5f;

    // Require multiple anomalous windows
    det->consecutive_required = 2;
    det->consecutive_anomaly_windows = 0;

    det->prev_residual = 0.0f;
}

static void compute_features(
    AnomalyDetector *det,
    AnomalyFeatures *f
) {
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float peak = 0.0f;
    uint16_t zc = 0;

    float prev = det->window[0];

    for (uint16_t i = 0; i < AD_WINDOW_SIZE; i++) {
        float v = det->window[i];
        sum += v;
        sum_sq += v * v;

        float av = fabsf(v);
        if (av > peak) {
            peak = av;
        }

        if ((prev >= 0.0f && v < 0.0f) || (prev < 0.0f && v >= 0.0f)) {
            zc++;
        }
        prev = v;
    }

    float mean = sum / AD_WINDOW_SIZE;
    float variance = (sum_sq / AD_WINDOW_SIZE) - (mean * mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    float nvar = safe_div(variance, det->var_nominal);
    float npeak = safe_div(peak, det->peak_nominal);
    float nzc = safe_div((float)zc, det->zc_nominal);

    float score =
        det->w_var * nvar +
        det->w_peak * npeak +
        det->w_zc * nzc;

    bool window_anomaly = (score > det->anomaly_threshold);

    if (window_anomaly) {
        if (det->consecutive_anomaly_windows < 255) {
            det->consecutive_anomaly_windows++;
        }
    } else {
        det->consecutive_anomaly_windows = 0;
    }

    f->mean = mean;
    f->variance = variance;
    f->peak = peak;
    f->zero_crossings = zc;
    f->score = score;
    f->is_anomaly =
        (det->consecutive_anomaly_windows >= det->consecutive_required);
}

bool anomaly_detector_process_sample(
    AnomalyDetector *det,
    const AccelSample *sample,
    AnomalyFeatures *out_features
) {
    float mag = compute_magnitude(sample);

    // Exponential moving average baseline
    det->baseline =
        (1.0f - det->baseline_alpha) * det->baseline +
        det->baseline_alpha * mag;

    // Residual removes slow orientation/gravity drift
    float residual = mag - det->baseline;

    det->window[det->index] = residual;
    det->index++;

    if (det->index >= AD_WINDOW_SIZE) {
        det->index = 0;
        det->full = true;
    }

    det->prev_residual = residual;

    if (!det->full) {
        return false;
    }

    compute_features(det, &det->last_features);

    if (out_features) {
        *out_features = det->last_features;
    }

    return true;
}
```

