Below is an initial, embedded-friendly implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple pipeline architecture
- Accelerometer preprocessing
- Magnitude and high-pass style motion extraction
- Rolling statistics
- Threshold-based anomaly detection
- C code suitable as a starting point for MCU firmware
- Notes on tuning and extension

---

## 1. Design goals

For an embedded initial implementation, we want:

- Low memory usage
- Predictable runtime
- No dynamic allocation
- Easy tuning
- Robustness to gravity and sensor bias
- Simple anomaly detection that works before ML is introduced

A practical first version is:

1. Read raw accelerometer samples `(ax, ay, az)`
2. Low-pass filter each axis to estimate gravity/bias
3. Subtract low-pass estimate to get dynamic acceleration
4. Compute motion magnitude
5. Smooth magnitude
6. Maintain rolling mean and variance
7. Flag anomaly when signal exceeds adaptive threshold for enough consecutive samples

---

## 2. Pipeline overview

```text
Raw accel (x,y,z)
   ↓
Axis low-pass filter (gravity/bias estimate)
   ↓
Dynamic accel = raw - low-pass
   ↓
Magnitude or energy feature
   ↓
Feature smoothing
   ↓
Rolling baseline stats
   ↓
Threshold / z-score anomaly detector
   ↓
Debounce / persistence logic
   ↓
Anomaly event
```

---

## 3. Embedded C implementation

This is a self-contained initial implementation.

### Header + implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* =========================
 * Configuration
 * ========================= */
#define ANOM_RING_SIZE              64
#define ANOM_MIN_CONSECUTIVE        3
#define ANOM_COOLDOWN_SAMPLES       20

typedef struct {
    float sample_rate_hz;          // e.g. 100 Hz

    // Low-pass filter coefficient for gravity estimate
    // y[n] = alpha * y[n-1] + (1-alpha) * x[n]
    // alpha near 1.0 => slower gravity tracking
    float gravity_alpha;           // e.g. 0.95

    // Feature smoothing coefficient
    float feature_alpha;           // e.g. 0.8

    // Adaptive threshold parameters
    float z_threshold;             // e.g. 4.0
    float min_abs_threshold;       // e.g. 0.15 g-equivalent or SI-scaled
    float epsilon;                 // e.g. 1e-6

    // Optional clipping to suppress impossible spikes
    float max_input_abs;           // e.g. 16.0f for +/-16g normalized units
} AnomalyConfig;

typedef struct {
    float x;
    float y;
    float z;
} Vec3f;

typedef struct {
    // Gravity / bias estimate
    Vec3f gravity_est;

    // Smoothed feature
    float feature_smooth;

    // Ring buffer for rolling stats
    float ring[ANOM_RING_SIZE];
    uint16_t ring_index;
    uint16_t ring_count;

    // Running sums for mean/std
    float sum;
    float sum_sq;

    // Detection state
    uint16_t consecutive_count;
    uint16_t cooldown;

    // Initialization flag
    bool initialized;
} AnomalyState;

typedef struct {
    bool anomaly;
    float raw_magnitude;
    float feature_value;
    float baseline_mean;
    float baseline_std;
    float z_score;
} AnomalyOutput;

/* =========================
 * Utility functions
 * ========================= */

static float clampf(float x, float lo, float hi) {
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

static float vec3_mag(Vec3f v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

static Vec3f vec3_sub(Vec3f a, Vec3f b) {
    Vec3f r = {a.x - b.x, a.y - b.y, a.z - b.z};
    return r;
}

static Vec3f vec3_lpf(Vec3f prev, Vec3f input, float alpha) {
    Vec3f out;
    out.x = alpha * prev.x + (1.0f - alpha) * input.x;
    out.y = alpha * prev.y + (1.0f - alpha) * input.y;
    out.z = alpha * prev.z + (1.0f - alpha) * input.z;
    return out;
}

/* =========================
 * Rolling stats
 * ========================= */

static void rolling_reset(AnomalyState *s) {
    memset(s->ring, 0, sizeof(s->ring));
    s->ring_index = 0;
    s->ring_count = 0;
    s->sum = 0.0f;
    s->sum_sq = 0.0f;
}

static void rolling_push(AnomalyState *s, float value) {
    if (s->ring_count < ANOM_RING_SIZE) {
        s->ring[s->ring_index] = value;
        s->sum += value;
        s->sum_sq += value * value;
        s->ring_index = (s->ring_index + 1) % ANOM_RING_SIZE;
        s->ring_count++;
    } else {
        float old = s->ring[s->ring_index];
        s->sum -= old;
        s->sum_sq -= old * old;

        s->ring[s->ring_index] = value;
        s->sum += value;
        s->sum_sq += value * value;

        s->ring_index = (s->ring_index + 1) % ANOM_RING_SIZE;
    }
}

static float rolling_mean(const AnomalyState *s) {
    if (s->ring_count == 0) return 0.0f;
    return s->sum / (float)s->ring_count;
}

static float rolling_std(const AnomalyState *s, float epsilon) {
    if (s->ring_count < 2) return 0.0f;
    float n = (float)s->ring_count;
    float mean = s->sum / n;
    float var = (s->sum_sq / n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    if (var < epsilon) var = epsilon;
    return sqrtf(var);
}

/* =========================
 * Public API
 * ========================= */

void anomaly_init(AnomalyState *state) {
    memset(state, 0, sizeof(*state));
    rolling_reset(state);
}

void anomaly_default_config(AnomalyConfig *cfg) {
    cfg->sample_rate_hz = 100.0f;
    cfg->gravity_alpha = 0.95f;
    cfg->feature_alpha = 0.80f;
    cfg->z_threshold = 4.0f;
    cfg->min_abs_threshold = 0.15f;
    cfg->epsilon = 1e-6f;
    cfg->max_input_abs = 16.0f;
}

AnomalyOutput anomaly_process_sample(
    AnomalyState *state,
    const AnomalyConfig *cfg,
    float ax,
    float ay,
    float az
) {
    AnomalyOutput out = {0};

    // Clamp raw input to avoid pathological values
    ax = clampf(ax, -cfg->max_input_abs, cfg->max_input_abs);
    ay = clampf(ay, -cfg->max_input_abs, cfg->max_input_abs);
    az = clampf(az, -cfg->max_input_abs, cfg->max_input_abs);

    Vec3f raw = {ax, ay, az};

    // Initialize gravity estimate from first sample
    if (!state->initialized) {
        state->gravity_est = raw;
        state->feature_smooth = 0.0f;
        state->initialized = true;
    }

    // Estimate gravity / slow bias
    state->gravity_est = vec3_lpf(state->gravity_est, raw, cfg->gravity_alpha);

    // Dynamic acceleration
    Vec3f dyn = vec3_sub(raw, state->gravity_est);

    // Feature: magnitude of dynamic acceleration
    float mag = vec3_mag(dyn);

    // Smooth feature
    state->feature_smooth =
        cfg->feature_alpha * state->feature_smooth +
        (1.0f - cfg->feature_alpha) * mag;

    float feature = state->feature_smooth;

    // Compute baseline before inserting current sample
    float mean = rolling_mean(state);
    float std = rolling_std(state, cfg->epsilon);

    float z = 0.0f;
    if (state->ring_count >= 8) {
        z = (feature - mean) / std;
    }

    // Detection logic
    bool above_abs = feature > cfg->min_abs_threshold;
    bool above_z = (state->ring_count >= 8) && (z > cfg->z_threshold);
    bool candidate = above_abs && above_z;

    if (state->cooldown > 0) {
        state->cooldown--;
    }

    if (candidate && state->cooldown == 0) {
        state->consecutive_count++;
    } else {
        state->consecutive_count = 0;
    }

    bool anomaly = false;
    if (state->consecutive_count >= ANOM_MIN_CONSECUTIVE) {
        anomaly = true;
        state->consecutive_count = 0;
        state->cooldown = ANOM_COOLDOWN_SAMPLES;
    }

    // Update rolling baseline after detection decision
    rolling_push(state, feature);

    out.anomaly = anomaly;
    out.raw_magnitude = mag;
    out.feature_value = feature;
    out.baseline_mean = mean;
    out.baseline_std = std;
    out.z_score = z;

    return out;
}
```

