#include <stdio.h>

int main(void) {
    AnomalyConfig cfg;
    AnomalyState state;

    anomaly_default_config(&cfg);
    anomaly_init(&state);

    // Example stream of accelerometer samples
    float samples[][3] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.03f, 0.02f, 1.00f},
        {1.50f, 1.20f, 2.00f}, // possible anomaly
        {1.40f, 1.10f, 1.80f},
        {1.30f, 1.00f, 1.70f},
        {0.01f, 0.01f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);
    for (int i = 0; i < n; i++) {
        AnomalyOutput out = anomaly_process_sample(
            &state, &cfg,
            samples[i][0], samples[i][1], samples[i][2]
        );

        printf("i=%d feat=%.4f mean=%.4f std=%.4f z=%.2f anomaly=%d\n",
               i,
               out.feature_value,
               out.baseline_mean,
               out.baseline_std,
               out.z_score,
               out.anomaly ? 1 : 0);
    }

    return 0;
}
