# 2. Embedded-oriented C implementation

This is a lightweight implementation intended as a starting point for MCU firmware.

## Header

```c
#ifndef ANOMALY_PIPELINE_H
#define ANOMALY_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 64
#define FEATURE_EPS 1e-6f

typedef struct {
    float mean;
    float var;
    float rms;
    float peak;
} Features;

typedef struct {
    float alpha_hp;       // high-pass / baseline EMA factor
    float baseline;       // EMA baseline of magnitude

    float window[WINDOW_SIZE];
    uint16_t index;
    bool full;

    // Running normal feature statistics
    float mean_rms;
    float mean_var;
    float mean_peak;

    float std_rms;
    float std_var;
    float std_peak;

    float adapt_alpha;    // adaptation rate for baseline feature stats
    float threshold;      // anomaly threshold
    uint8_t persistence;  // windows required to trigger
    uint8_t anomaly_count;
} AnomalyPipeline;

void anomaly_pipeline_init(AnomalyPipeline *p);
bool anomaly_pipeline_process_sample(
    AnomalyPipeline *p,
    float ax, float ay, float az,
    float *out_score,
    Features *out_features
);

#endif
