## Source

```c
#include "anomaly_pipeline.h"
#include <math.h>
#include <string.h>

static float fast_abs(float x) {
    return x < 0 ? -x : x;
}

static float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

static void extract_features(const float *x, uint16_t n, Features *f) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float peak = 0.0f;

    for (uint16_t i = 0; i < n; i++) {
        float v = x[i];
        sum += v;
        sumsq += v * v;
        float av = fast_abs(v);
        if (av > peak) peak = av;
    }

    f->mean = sum / n;
    f->rms = sqrtf(sumsq / n);
    f->var = (sumsq / n) - (f->mean * f->mean);
    if (f->var < 0.0f) f->var = 0.0f;
    f->peak = peak;
}

static float zscore(float x, float mean, float std) {
    float s = std;
    if (s < FEATURE_EPS) s = FEATURE_EPS;
    return (x - mean) / s;
}

static float anomaly_score(const AnomalyPipeline *p, const Features *f) {
    float zrms  = zscore(f->rms,  p->mean_rms,  p->std_rms);
    float zvar  = zscore(f->var,  p->mean_var,  p->std_var);
    float zpeak = zscore(f->peak, p->mean_peak, p->std_peak);

    // Use absolute z-scores so both unusually low/high behavior can trigger
    float score = fast_abs(zrms) + fast_abs(zvar) + fast_abs(zpeak);
    return score / 3.0f;
}

static void update_running_stats(float *mean, float *std, float x, float alpha) {
    // Simple EMA mean and EMA absolute deviation as std proxy
    float prev_mean = *mean;
    *mean = (1.0f - alpha) * (*mean) + alpha * x;

    float dev = fast_abs(x - prev_mean);
    *std = (1.0f - alpha) * (*std) + alpha * dev;

    if (*std < FEATURE_EPS) *std = FEATURE_EPS;
}

void anomaly_pipeline_init(AnomalyPipeline *p) {
    memset(p, 0, sizeof(*p));

    p->alpha_hp = 0.01f;
    p->adapt_alpha = 0.01f;
    p->threshold = 3.0f;
    p->persistence = 3;

    // Initial nominal values to avoid divide-by-zero and startup instability
    p->mean_rms = 0.1f;
    p->mean_var = 0.01f;
    p->mean_peak = 0.2f;

    p->std_rms = 0.05f;
    p->std_var = 0.01f;
    p->std_peak = 0.05f;
}

bool anomaly_pipeline_process_sample(
    AnomalyPipeline *p,
    float ax, float ay, float az,
    float *out_score,
    Features *out_features
) {
    float mag = compute_magnitude(ax, ay, az);

    // Remove slow baseline (gravity + drift approximation)
    p->baseline = (1.0f - p->alpha_hp) * p->baseline + p->alpha_hp * mag;
    float hp = mag - p->baseline;

    p->window[p->index++] = hp;
    if (p->index >= WINDOW_SIZE) {
        p->index = 0;
        p->full = true;
    }

    if (!p->full) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    Features f;
    extract_features(p->window, WINDOW_SIZE, &f);

    float score = anomaly_score(p, &f);

    if (out_score) *out_score = score;
    if (out_features) *out_features = f;

    bool is_anomaly = score > p->threshold;

    if (is_anomaly) {
        if (p->anomaly_count < 255) p->anomaly_count++;
    } else {
        p->anomaly_count = 0;

        // Only adapt baseline stats on normal windows
        update_running_stats(&p->mean_rms,  &p->std_rms,  f.rms,  p->adapt_alpha);
        update_running_stats(&p->mean_var,  &p->std_var,  f.var,  p->adapt_alpha);
        update_running_stats(&p->mean_peak, &p->std_peak, f.peak, p->adapt_alpha);
    }

    return p->anomaly_count >= p->persistence;
}
```

