# 4. Python reference implementation

This version is useful for simulation and tuning before porting to firmware.

```python
import math
from collections import deque


class Features:
    def __init__(self, mean=0.0, var=0.0, rms=0.0, peak=0.0):
        self.mean = mean
        self.var = var
        self.rms = rms
        self.peak = peak

    def __repr__(self):
        return f"Features(mean={self.mean:.4f}, var={self.var:.4f}, rms={self.rms:.4f}, peak={self.peak:.4f})"


class AnomalyPipeline:
    def __init__(self, window_size=64, alpha_hp=0.01, adapt_alpha=0.01,
                 threshold=3.0, persistence=3):
        self.window_size = window_size
        self.alpha_hp = alpha_hp
        self.adapt_alpha = adapt_alpha
        self.threshold = threshold
        self.persistence = persistence

        self.baseline = 0.0
        self.window = deque(maxlen=window_size)

        self.mean_rms = 0.1
        self.mean_var = 0.01
        self.mean_peak = 0.2

        self.std_rms = 0.05
        self.std_var = 0.01
        self.std_peak = 0.05

        self.anomaly_count = 0

    def magnitude(self, ax, ay, az):
        return math.sqrt(ax * ax + ay * ay + az * az)

    def extract_features(self, x):
        n = len(x)
        mean = sum(x) / n
        sumsq = sum(v * v for v in x)
        rms = math.sqrt(sumsq / n)
        var = max((sumsq / n) - mean * mean, 0.0)
        peak = max(abs(v) for v in x)
        return Features(mean, var, rms, peak)

    def zscore(self, x, mean, std, eps=1e-6):
        return (x - mean) / max(std, eps)

    def anomaly_score(self, f):
        zrms = abs(self.zscore(f.rms, self.mean_rms, self.std_rms))
        zvar = abs(self.zscore(f.var, self.mean_var, self.std_var))
        zpeak = abs(self.zscore(f.peak, self.mean_peak, self.std_peak))
        return (zrms + zvar + zpeak) / 3.0

    def update_running_stats(self, attr_mean, attr_std, x):
        mean = getattr(self, attr_mean)
        std = getattr(self, attr_std)

        prev_mean = mean
        mean = (1 - self.adapt_alpha) * mean + self.adapt_alpha * x
        dev = abs(x - prev_mean)
        std = (1 - self.adapt_alpha) * std + self.adapt_alpha * dev
        std = max(std, 1e-6)

        setattr(self, attr_mean, mean)
        setattr(self, attr_std, std)

    def process_sample(self, ax, ay, az):
        mag = self.magnitude(ax, ay, az)
        self.baseline = (1 - self.alpha_hp) * self.baseline + self.alpha_hp * mag
        hp = mag - self.baseline

        self.window.append(hp)
        if len(self.window) < self.window_size:
            return False, 0.0, None

        f = self.extract_features(self.window)
        score = self.anomaly_score(f)
        is_anomaly = score > self.threshold

        if is_anomaly:
            self.anomaly_count += 1
        else:
            self.anomaly_count = 0
            self.update_running_stats("mean_rms", "std_rms", f.rms)
            self.update_running_stats("mean_var", "std_var", f.var)
            self.update_running_stats("mean_peak", "std_peak", f.peak)

        triggered = self.anomaly_count >= self.persistence
        return triggered, score, f
```

