# 5. Example simulation

```python
import random

def generate_data(n=1000, anomaly_start=600, anomaly_len=80):
    data = []
    for i in range(n):
        # Normal motion around gravity on z-axis
        ax = random.gauss(0.0, 0.03)
        ay = random.gauss(0.0, 0.03)
        az = 1.0 + random.gauss(0.0, 0.03)

        # Inject anomaly: vibration/spike burst
        if anomaly_start <= i < anomaly_start + anomaly_len:
            ax += random.gauss(0.0, 0.4)
            ay += random.gauss(0.0, 0.4)
            az += random.gauss(0.0, 0.4)

        data.append((ax, ay, az))
    return data


pipeline = AnomalyPipeline()
samples = generate_data()

for i, (ax, ay, az) in enumerate(samples):
    triggered, score, features = pipeline.process_sample(ax, ay, az)
    if features is not None and i % 20 == 0:
        print(i, f"score={score:.2f}", features)
    if triggered:
        print(f"Anomaly triggered at sample {i}, score={score:.2f}")
        break
```

