```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float low_pass(float input, float prev, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

static float accel_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

void sensor_pipeline_init(SensorPipeline *sp, const PipelineConfig *cfg) {
    memset(sp, 0, sizeof(*sp));
    sp->cfg = *cfg;
}

bool sensor_pipeline_process_sample(
    SensorPipeline *sp,
    const AccelSample *sample,
    PipelineResult *result
) {
    float x, y, z;
    float mag;
    float sum = 0.0f;
    float mean;
    float var_sum = 0.0f;
    float peak_dev = 0.0f;

    result->anomaly = false;
    result->mean_mag = 0.0f;
    result->var_mag = 0.0f;
    result->peak_dev = 0.0f;

    // 1. Filter
    if (!sp->filter_initialized) {
        sp->filt_x = sample->x;
        sp->filt_y = sample->y;
        sp->filt_z = sample->z;
        sp->filter_initialized = true;
    } else {
        sp->filt_x = low_pass(sample->x, sp->filt_x, sp->cfg.alpha);
        sp->filt_y = low_pass(sample->y, sp->filt_y, sp->cfg.alpha);
        sp->filt_z = low_pass(sample->z, sp->filt_z, sp->cfg.alpha);
    }

    x = sp->filt_x;
    y = sp->filt_y;
    z = sp->filt_z;

    // 2. Magnitude
    mag = accel_magnitude(x, y, z);

    // 3. Store in rolling window
    sp->mag_window[sp->index] = mag;
    sp->index++;

    if (sp->index >= SP_WINDOW_SIZE) {
        sp->index = 0;
        sp->full = true;
    }

    // Not enough data yet
    if (!sp->full) {
        return false;
    }

    // 4. Compute mean
    for (uint16_t i = 0; i < SP_WINDOW_SIZE; i++) {
        sum += sp->mag_window[i];
    }
    mean = sum / SP_WINDOW_SIZE;

    // 5. Compute variance and peak deviation
    for (uint16_t i = 0; i < SP_WINDOW_SIZE; i++) {
        float d = sp->mag_window[i] - mean;
        var_sum += d * d;
        float abs_d = fabsf(d);
        if (abs_d > peak_dev) {
            peak_dev = abs_d;
        }
    }

    result->mean_mag = mean;
    result->var_mag = var_sum / SP_WINDOW_SIZE;
    result->peak_dev = peak_dev;

    // 6. Threshold-based anomaly detection
    if (fabsf(mean - sp->cfg.baseline_mean) > sp->cfg.mean_threshold ||
        result->var_mag > sp->cfg.var_threshold ||
        result->peak_dev > sp->cfg.peak_threshold) {
        result->anomaly = true;
    }

    return true;
}
```

