## Initial C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* =========================
 * Configuration
 * ========================= */

#define ACCEL_EPSILON            1e-6f
#define DEFAULT_ALPHA           0.2f     // LPF smoothing factor
#define DEFAULT_STATS_ALPHA     0.01f    // EMA stats update rate
#define DEFAULT_Z_THRESHOLD     4.0f     // anomaly threshold
#define DEFAULT_COOLDOWN_SAMPLES 20      // suppress repeated triggers

/* =========================
 * Data structures
 * ========================= */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;
    float x;
    float y;
    float z;
    bool initialized;
} LowPassFilter3D;

typedef struct {
    float mean;
    float var;
    float alpha;
    bool initialized;
} RunningStats;

typedef struct {
    float z_threshold;
    uint32_t cooldown_samples;
} AnomalyConfig;

typedef struct {
    bool anomaly;
    float score;          // z-score-like anomaly score
    float magnitude;
    float mean;
    float stddev;
} AnomalyResult;

typedef struct {
    LowPassFilter3D lpf;
    RunningStats stats;
    AnomalyConfig cfg;
    uint32_t cooldown_counter;
} SensorPipeline;

/* =========================
 * Utility functions
 * ========================= */

static float fast_sqrtf_safe(float x) {
    if (x <= 0.0f) {
        return 0.0f;
    }
    return sqrtf(x);
}

static float accel_magnitude(const AccelSample *s) {
    return fast_sqrtf_safe(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* =========================
 * Low-pass filter
 * y[n] = alpha*x[n] + (1-alpha)*y[n-1]
 * ========================= */

static void lpf3d_init(LowPassFilter3D *f, float alpha) {
    f->alpha = alpha;
    f->x = 0.0f;
    f->y = 0.0f;
    f->z = 0.0f;
    f->initialized = false;
}

static AccelSample lpf3d_update(LowPassFilter3D *f, AccelSample in) {
    if (!f->initialized) {
        f->x = in.x;
        f->y = in.y;
        f->z = in.z;
        f->initialized = true;
    } else {
        f->x = f->alpha * in.x + (1.0f - f->alpha) * f->x;
        f->y = f->alpha * in.y + (1.0f - f->alpha) * f->y;
        f->z = f->alpha * in.z + (1.0f - f->alpha) * f->z;
    }

    AccelSample out = { f->x, f->y, f->z };
    return out;
}

/* =========================
 * Running stats using EMA
 * mean_t = (1-a)*mean_{t-1} + a*x_t
 * var_t  = (1-a)*var_{t-1} + a*(x_t-mean_t)^2
 * ========================= */

static void running_stats_init(RunningStats *s, float alpha) {
    s->mean = 0.0f;
    s->var = 0.0f;
    s->alpha = alpha;
    s->initialized = false;
}

static void running_stats_update(RunningStats *s, float x) {
    if (!s->initialized) {
        s->mean = x;
        s->var = 0.0f;
        s->initialized = true;
        return;
    }

    float delta = x - s->mean;
    s->mean = (1.0f - s->alpha) * s->mean + s->alpha * x;

    float delta2 = x - s->mean;
    float inst_var = delta * delta2;
    s->var = (1.0f - s->alpha) * s->var + s->alpha * inst_var;

    if (s->var < 0.0f) {
        s->var = 0.0f;
    }
}

static float running_stats_stddev(const RunningStats *s) {
    return fast_sqrtf_safe(s->var);
}

/* =========================
 * Pipeline API
 * ========================= */

void sensor_pipeline_init(SensorPipeline *p,
                          float lpf_alpha,
                          float stats_alpha,
                          float z_threshold,
                          uint32_t cooldown_samples) {
    lpf3d_init(&p->lpf, lpf_alpha);
    running_stats_init(&p->stats, stats_alpha);

    p->cfg.z_threshold = z_threshold;
    p->cfg.cooldown_samples = cooldown_samples;
    p->cooldown_counter = 0;
}

void sensor_pipeline_init_default(SensorPipeline *p) {
    sensor_pipeline_init(p,
                         DEFAULT_ALPHA,
                         DEFAULT_STATS_ALPHA,
                         DEFAULT_Z_THRESHOLD,
                         DEFAULT_COOLDOWN_SAMPLES);
}

AnomalyResult sensor_pipeline_process(SensorPipeline *p, AccelSample raw) {
    AnomalyResult result = {0};

    /* 1. Filter raw sample */
    AccelSample filtered = lpf3d_update(&p->lpf, raw);

    /* 2. Compute magnitude */
    float mag = accel_magnitude(&filtered);

    /* 3. Compute anomaly score against current baseline */
    float mean = p->stats.mean;
    float stddev = running_stats_stddev(&p->stats);

    float score = 0.0f;
    if (p->stats.initialized && stddev > ACCEL_EPSILON) {
        score = fabsf(mag - mean) / stddev;
    }

    /* 4. Detect anomaly with cooldown */
    bool anomaly = false;
    if (p->stats.initialized &&
        stddev > ACCEL_EPSILON &&
        score > p->cfg.z_threshold &&
        p->cooldown_counter == 0) {
        anomaly = true;
        p->cooldown_counter = p->cfg.cooldown_samples;
    }

    if (p->cooldown_counter > 0) {
        p->cooldown_counter--;
    }

    /* 5. Update baseline after detection step */
    running_stats_update(&p->stats, mag);

    result.anomaly = anomaly;
    result.score = score;
    result.magnitude = mag;
    result.mean = mean;
    result.stddev = stddev;

    return result;
}
```

