# Source: `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"

static float absf_local(float v)
{
    return (v < 0.0f) ? -v : v;
}

/*
 * Fast magnitude approximation to avoid sqrt:
 * approx |a| ~= max + 0.5*(mid + min)
 * Good enough for anomaly detection in many embedded cases.
 */
static float accel_magnitude_approx(float x, float y, float z)
{
    float ax = absf_local(x);
    float ay = absf_local(y);
    float az = absf_local(z);

    float max = ax;
    float mid = ay;
    float min = az;

    if (max < mid) { float t = max; max = mid; mid = t; }
    if (mid < min) { float t = mid; mid = min; min = t; }
    if (max < mid) { float t = max; max = mid; mid = t; }

    return max + 0.5f * (mid + min);
}

void pipeline_init(pipeline_state_t *state, const pipeline_config_t *config)
{
    (void)config;

    state->baseline_mag = 0.0f;
    state->residual = 0.0f;
    state->energy = 0.0f;
    state->last_anomaly_ts = 0;
    state->initialized = false;
}

pipeline_output_t pipeline_process_sample(
    pipeline_state_t *state,
    const pipeline_config_t *config,
    const accel_sample_t *sample)
{
    pipeline_output_t out;
    out.anomaly = false;
    out.magnitude = 0.0f;
    out.residual = 0.0f;
    out.energy = 0.0f;

    float mag = accel_magnitude_approx(sample->x, sample->y, sample->z);

    if (!state->initialized)
    {
        state->baseline_mag = mag;
        state->residual = 0.0f;
        state->energy = 0.0f;
        state->last_anomaly_ts = 0;
        state->initialized = true;
    }

    // Low-pass baseline
    state->baseline_mag =
        (1.0f - config->baseline_alpha) * state->baseline_mag +
        config->baseline_alpha * mag;

    // High-pass residual
    state->residual = mag - state->baseline_mag;

    // Energy estimate from squared residual
    float inst_energy = state->residual * state->residual;
    state->energy =
        (1.0f - config->energy_alpha) * state->energy +
        config->energy_alpha * inst_energy;

    // Threshold + cooldown
    if (state->energy > config->anomaly_threshold)
    {
        uint32_t dt = sample->timestamp_ms - state->last_anomaly_ts;
        if ((state->last_anomaly_ts == 0U) || (dt >= config->cooldown_ms))
        {
            out.anomaly = true;
            state->last_anomaly_ts = sample->timestamp_ms;
        }
    }

    out.magnitude = mag;
    out.residual = state->residual;
    out.energy = state->energy;

    return out;
}
