## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <string.h>

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

/* Cheaper than sqrt(x*x+y*y+z*z) for some MCUs.
   For initial anomaly detection, L1 norm often works well enough. */
static float accel_mag_approx(float x, float y, float z) {
    return fast_absf(x) + fast_absf(y) + fast_absf(z);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    memset(det, 0, sizeof(*det));

    det->alpha_base = 0.01f;              /* slow baseline tracking */
    det->window_size = 32;                /* ~320 ms at 100 Hz */
    det->shock_threshold = 2.5f;          /* tune per sensor units */
    det->var_threshold = 0.5f;
    det->mean_threshold = 1.0f;
    det->sustained_windows_required = 3;

    det->last_result.type = ANOMALY_NONE;
}

void anomaly_detector_set_offsets(anomaly_detector_t *det,
                                  float ox, float oy, float oz) {
    det->offset_x = ox;
    det->offset_y = oy;
    det->offset_z = oz;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              anomaly_result_t *result) {
    /* 1. Offset correction */
    float x = sample->x - det->offset_x;
    float y = sample->y - det->offset_y;
    float z = sample->z - det->offset_z;

    /* 2. Baseline/gravity estimate via low-pass filter */
    det->base_x += det->alpha_base * (x - det->base_x);
    det->base_y += det->alpha_base * (y - det->base_y);
    det->base_z += det->alpha_base * (z - det->base_z);

    /* 3. Dynamic acceleration */
    float dx = x - det->base_x;
    float dy = y - det->base_y;
    float dz = z - det->base_z;

    /* 4. Magnitude approximation */
    float mag = accel_mag_approx(dx, dy, dz);

    /* 5. Update window stats */
    det->sum_mag += mag;
    det->sum_sq_mag += mag * mag;
    if (mag > det->peak_mag) {
        det->peak_mag = mag;
    }
    det->sample_count++;

    /* No result until window completes */
    if (det->sample_count < det->window_size) {
        return false;
    }

    /* 6. Compute features */
    float n = (float)det->window_size;
    float mean_mag = det->sum_mag / n;
    float mean_sq = det->sum_sq_mag / n;
    float var_mag = mean_sq - (mean_mag * mean_mag);
    if (var_mag < 0.0f) {
        var_mag = 0.0f;
    }

    anomaly_result_t local_result;
    local_result.type = ANOMALY_NONE;
    local_result.score = 0.0f;
    local_result.peak_mag = det->peak_mag;
    local_result.mean_mag = mean_mag;
    local_result.var_mag = var_mag;

    /* 7. Rule-based anomaly detection */
    if (det->peak_mag > det->shock_threshold) {
        local_result.type = ANOMALY_SHOCK;
        local_result.score = det->peak_mag / det->shock_threshold;
        det->sustained_windows_count = 0;
    } else if (var_mag > det->var_threshold) {
        local_result.type = ANOMALY_VIBRATION;
        local_result.score = var_mag / det->var_threshold;
        det->sustained_windows_count = 0;
    } else if (mean_mag > det->mean_threshold) {
        det->sustained_windows_count++;
        if (det->sustained_windows_count >= det->sustained_windows_required) {
            local_result.type = ANOMALY_SUSTAINED_MOTION;
            local_result.score = mean_mag / det->mean_threshold;
        }
    } else {
        det->sustained_windows_count = 0;
    }

    det->last_result = local_result;

    if (result != NULL) {
        *result = local_result;
    }

    /* 8. Reset window stats */
    det->sample_count = 0;
    det->sum_mag = 0.0f;
    det->sum_sq_mag = 0.0f;
    det->peak_mag = 0.0f;

    return true;
}
```

