Below is a compact, practical **initial implementation** of an **embedded sensor-processing pipeline** for **accelerometer anomaly detection**.

It includes:

- A simple pipeline architecture
- Streaming accelerometer preprocessing
- Feature extraction over a sliding window
- A lightweight anomaly detector
- C code suitable as a starting point for embedded systems
- Notes for tuning and deployment

---

# 1. Design goals

For an embedded target, we usually want:

- **Low memory**
- **Deterministic runtime**
- **No dynamic allocation**
- **Simple math**
- **Streaming operation**

This implementation assumes:

- 3-axis accelerometer samples: `ax, ay, az`
- Fixed sample rate
- Window-based detection
- A lightweight statistical anomaly score

---

# 2. Pipeline overview

The processing stages are:

1. **Acquire sample**
2. **Optional DC/gravity smoothing**
3. **Compute magnitude / high-pass-like signal**
4. **Store in ring buffer**
5. **When window is full, extract features**
6. **Compare features to baseline**
7. **Raise anomaly flag if score exceeds threshold**

A simple feature set:

- Mean magnitude
- Variance
- Peak-to-peak
- Mean absolute deviation

These are cheap to compute and often useful for vibration or motion anomaly detection.

---

# 3. Initial C implementation

## Header: `sensor_pipeline.h`

```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

#define SP_WINDOW_SIZE 64

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float peak_to_peak;
    float mad;   // mean absolute deviation
} FeatureVector;

typedef struct {
    // Ring buffer of scalar signal derived from accel
    float window[SP_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    // Low-pass estimate of gravity / DC component
    float lp_ax;
    float lp_ay;
    float lp_az;
    bool lp_initialized;

    // Baseline model
    FeatureVector baseline_mean;
    FeatureVector baseline_std;
    bool baseline_ready;

    // Detection threshold
    float anomaly_threshold;

    // Optional warmup/training accumulation
    uint32_t training_windows_seen;
} SensorPipeline;

void sp_init(SensorPipeline *sp, float anomaly_threshold);
bool sp_process_sample(SensorPipeline *sp, AccelSample s, float *out_score, bool *out_anomaly);
void sp_extract_features(const float *window, uint16_t len, FeatureVector *fv);
void sp_set_baseline(SensorPipeline *sp, const FeatureVector *mean, const FeatureVector *stddev);

#ifdef __cplusplus
}
#endif

#endif
```

---

## Source: `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"
#include <string.h>
#include <math.h>

#ifndef SP_EPSILON
#define SP_EPSILON 1e-6f
#endif

#ifndef SP_LP_ALPHA
// Low-pass coefficient for gravity/DC estimate
// Smaller = slower adaptation
#define SP_LP_ALPHA 0.01f
#endif

static float absf_local(float x) {
    return (x < 0.0f) ? -x : x;
}

static float sqrtf_safe(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

void sp_init(SensorPipeline *sp, float anomaly_threshold) {
    memset(sp, 0, sizeof(*sp));
    sp->anomaly_threshold = anomaly_threshold;
}

void sp_set_baseline(SensorPipeline *sp, const FeatureVector *mean, const FeatureVector *stddev) {
    sp->baseline_mean = *mean;
    sp->baseline_std = *stddev;
    sp->baseline_ready = true;
}

void sp_extract_features(const float *window, uint16_t len, FeatureVector *fv) {
    float sum = 0.0f;
    float minv = window[0];
    float maxv = window[0];

    for (uint16_t i = 0; i < len; i++) {
        float x = window[i];
        sum += x;
        if (x < minv) minv = x;
        if (x > maxv) maxv = x;
    }

    float mean = sum / (float)len;

    float var_sum = 0.0f;
    float mad_sum = 0.0f;
    for (uint16_t i = 0; i < len; i++) {
        float d = window[i] - mean;
        var_sum += d * d;
        mad_sum += absf_local(d);
    }

    fv->mean = mean;
    fv->variance = var_sum / (float)len;
    fv->peak_to_peak = maxv - minv;
    fv->mad = mad_sum / (float)len;
}

static float sp_feature_zscore(float x, float mu, float sigma) {
    float denom = (sigma > SP_EPSILON) ? sigma : SP_EPSILON;
    return absf_local((x - mu) / denom);
}

static float sp_compute_anomaly_score(const FeatureVector *fv, const FeatureVector *mu, const FeatureVector *sigma) {
    float z_mean = sp_feature_zscore(fv->mean, mu->mean, sigma->mean);
    float z_var  = sp_feature_zscore(fv->variance, mu->variance, sigma->variance);
    float z_p2p  = sp_feature_zscore(fv->peak_to_peak, mu->peak_to_peak, sigma->peak_to_peak);
    float z_mad  = sp_feature_zscore(fv->mad, mu->mad, sigma->mad);

    // Simple average z-score
    return 0.25f * (z_mean + z_var + z_p2p + z_mad);
}

bool sp_process_sample(SensorPipeline *sp, AccelSample s, float *out_score, bool *out_anomaly) {
    if (out_score) *out_score = 0.0f;
    if (out_anomaly) *out_anomaly = false;

    // Initialize LP state
    if (!sp->lp_initialized) {
        sp->lp_ax = s.ax;
        sp->lp_ay = s.ay;
        sp->lp_az = s.az;
        sp->lp_initialized = true;
    }

    // Low-pass estimate of gravity / DC component
    sp->lp_ax += SP_LP_ALPHA * (s.ax - sp->lp_ax);
    sp->lp_ay += SP_LP_ALPHA * (s.ay - sp->lp_ay);
    sp->lp_az += SP_LP_ALPHA * (s.az - sp->lp_az);

    // Remove gravity/DC
    float hx = s.ax - sp->lp_ax;
    float hy = s.ay - sp->lp_ay;
    float hz = s.az - sp->lp_az;

    // Scalar vibration/activity magnitude
    float mag = sqrtf_safe(hx * hx + hy * hy + hz * hz);

    // Push into ring buffer
    sp->window[sp->index] = mag;
    sp->index = (sp->index + 1U) % SP_WINDOW_SIZE;
    if (sp->count < SP_WINDOW_SIZE) {
        sp->count++;
    }

    // Need full window before detection
    if (sp->count < SP_WINDOW_SIZE) {
        return false;
    }

    // Reconstruct ordered window into temp array
    float ordered[SP_WINDOW_SIZE];
    uint16_t idx = sp->index;
    for (uint16_t i = 0; i < SP_WINDOW_SIZE; i++) {
        ordered[i] = sp->window[idx];
        idx = (idx + 1U) % SP_WINDOW_SIZE;
    }

    FeatureVector fv;
    sp_extract_features(ordered, SP_WINDOW_SIZE, &fv);

    if (!sp->baseline_ready) {
        // No baseline yet; cannot score anomaly
        return true;
    }

    float score = sp_compute_anomaly_score(&fv, &sp->baseline_mean, &sp->baseline_std);
    bool anomaly = (score > sp->anomaly_threshold);

    if (out_score) *out_score = score;
    if (out_anomaly) *out_anomaly = anomaly;

    return true;
}
```

