Below is a compact initial implementation of an embedded-friendly sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple processing pipeline
- Low-pass gravity estimation
- High-pass motion extraction
- Magnitude computation
- Rolling statistics
- Threshold-based anomaly detection
- C code suitable as a starting point for MCU firmware

---

## Design goals

This initial version is:

- Lightweight
- Streaming/incremental
- No dynamic allocation
- Easy to port to bare metal or RTOS
- Suitable for fixed-rate accelerometer samples

Assumptions:

- 3-axis accelerometer input: `ax, ay, az`
- Samples arrive at a roughly fixed rate
- We want to detect sudden shocks, abnormal vibration, or unusual motion

---

## Pipeline overview

For each sample:

1. Read raw accelerometer sample
2. Estimate gravity with low-pass filter
3. Subtract gravity to get dynamic acceleration
4. Compute motion magnitude
5. Smooth magnitude
6. Update rolling baseline statistics
7. Compare against threshold
8. Emit anomaly event if threshold exceeded

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    float x;
    float y;
    float z;
} vec3_t;

typedef struct {
    // Gravity estimate (low-pass state)
    vec3_t gravity;

    // Smoothed motion magnitude
    float mag_lp;

    // Rolling baseline stats using exponential moving averages
    float mean;
    float var;

    // Configuration
    float gravity_alpha;     // e.g. 0.01 to 0.1
    float mag_alpha;         // e.g. 0.1
    float stats_alpha;       // e.g. 0.01
    float threshold_sigma;   // e.g. 4.0
    float min_magnitude;     // absolute floor threshold
    uint32_t cooldown_samples;

    // Runtime state
    uint32_t cooldown;
    bool initialized;
} anomaly_detector_t;

typedef struct {
    bool anomaly;
    float raw_magnitude;
    float filtered_magnitude;
    float score;
} anomaly_result_t;

static inline float clamp_min(float x, float min_val) {
    return (x < min_val) ? min_val : x;
}

static inline float vec3_mag(vec3_t v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    det->gravity.x = 0.0f;
    det->gravity.y = 0.0f;
    det->gravity.z = 0.0f;

    det->mag_lp = 0.0f;
    det->mean = 0.0f;
    det->var = 1e-4f;

    det->gravity_alpha = 0.02f;
    det->mag_alpha = 0.15f;
    det->stats_alpha = 0.01f;
    det->threshold_sigma = 4.0f;
    det->min_magnitude = 0.2f;
    det->cooldown_samples = 20;

    det->cooldown = 0;
    det->initialized = false;
}

anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, vec3_t accel)
{
    anomaly_result_t result = {0};

    // Initialize gravity estimate from first sample
    if (!det->initialized) {
        det->gravity = accel;
        det->initialized = true;
    }

    // 1. Low-pass filter to estimate gravity
    det->gravity.x += det->gravity_alpha * (accel.x - det->gravity.x);
    det->gravity.y += det->gravity_alpha * (accel.y - det->gravity.y);
    det->gravity.z += det->gravity_alpha * (accel.z - det->gravity.z);

    // 2. High-pass: remove gravity
    vec3_t motion;
    motion.x = accel.x - det->gravity.x;
    motion.y = accel.y - det->gravity.y;
    motion.z = accel.z - det->gravity.z;

    // 3. Magnitude of dynamic acceleration
    float mag = vec3_mag(motion);
    result.raw_magnitude = mag;

    // 4. Smooth magnitude
    det->mag_lp += det->mag_alpha * (mag - det->mag_lp);
    float x = det->mag_lp;
    result.filtered_magnitude = x;

    // 5. Update rolling baseline statistics
    // EMA mean and variance
    float delta = x - det->mean;
    det->mean += det->stats_alpha * delta;

    float delta2 = x - det->mean;
    det->var = (1.0f - det->stats_alpha) * det->var + det->stats_alpha * delta * delta2;
    det->var = clamp_min(det->var, 1e-6f);

    float stddev = sqrtf(det->var);

    // 6. Compute anomaly score
    float z = (x - det->mean) / stddev;
    result.score = z;

    // 7. Threshold with cooldown and floor
    bool over_threshold = (x > det->min_magnitude) && (z > det->threshold_sigma);

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    if (over_threshold && det->cooldown == 0) {
        result.anomaly = true;
        det->cooldown = det->cooldown_samples;
    } else {
        result.anomaly = false;
    }

    return result;
}
```

