Below is an initial embedded-friendly implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple 3-axis accelerometer sample type
- Magnitude computation
- Low-pass filtering
- Rolling mean/variance estimation
- Z-score-based anomaly detection
- A small stateful pipeline API suitable for microcontrollers
- A demo `main()` loop

I’ll provide it in C, since that’s common for embedded systems.

---

## Features of this initial version

Pipeline stages:

1. **Input sample**: `ax, ay, az`
2. **Magnitude extraction**: `sqrt(ax² + ay² + az²)`
3. **Low-pass filter**: smooths noise
4. **Rolling statistics**: mean and standard deviation over a fixed window
5. **Anomaly decision**: flag if filtered magnitude deviates too much from baseline

This is intentionally simple and lightweight. It should be easy to adapt to:
- fixed-point math
- interrupt-driven sampling
- DMA-fed sensor buffers
- RTOS tasks
- threshold tuning per device

---

# C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* =========================
 * Configuration
 * ========================= */

#define ACCEL_WINDOW_SIZE      32
#define ACCEL_ZSCORE_THRESHOLD 3.0f
#define ACCEL_LPF_ALPHA        0.2f
#define ACCEL_MIN_STDDEV       0.05f

/* =========================
 * Data Types
 * ========================= */

typedef struct {
    float ax;
    float ay;
    float az;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float buffer[ACCEL_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
} rolling_stats_t;

typedef struct {
    bool initialized;
    float alpha;
    float filtered_value;
} lowpass_filter_t;

typedef struct {
    float raw_magnitude;
    float filtered_magnitude;
    float mean;
    float stddev;
    float zscore;
    bool anomaly;
} anomaly_result_t;

typedef struct {
    lowpass_filter_t lpf;
    rolling_stats_t stats;
    float zscore_threshold;
    float min_stddev;
} accel_pipeline_t;

/* =========================
 * Rolling Statistics
 * ========================= */

static void rolling_stats_init(rolling_stats_t *rs)
{
    memset(rs, 0, sizeof(*rs));
}

static void rolling_stats_update(rolling_stats_t *rs, float x)
{
    if (rs->count < ACCEL_WINDOW_SIZE) {
        rs->buffer[rs->index] = x;
        rs->sum += x;
        rs->sum_sq += x * x;
        rs->count++;
        rs->index = (rs->index + 1) % ACCEL_WINDOW_SIZE;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sum_sq -= old * old;

        rs->buffer[rs->index] = x;
        rs->sum += x;
        rs->sum_sq += x * x;

        rs->index = (rs->index + 1) % ACCEL_WINDOW_SIZE;
    }
}

static float rolling_stats_mean(const rolling_stats_t *rs)
{
    if (rs->count == 0) {
        return 0.0f;
    }
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const rolling_stats_t *rs)
{
    if (rs->count < 2) {
        return 0.0f;
    }

    float mean = rolling_stats_mean(rs);
    float var = (rs->sum_sq / (float)rs->count) - (mean * mean);

    if (var < 0.0f) {
        var = 0.0f;
    }

    return var;
}

static float rolling_stats_stddev(const rolling_stats_t *rs)
{
    return sqrtf(rolling_stats_variance(rs));
}

/* =========================
 * Low-pass Filter
 * ========================= */

static void lowpass_filter_init(lowpass_filter_t *f, float alpha)
{
    f->initialized = false;
    f->alpha = alpha;
    f->filtered_value = 0.0f;
}

static float lowpass_filter_update(lowpass_filter_t *f, float x)
{
    if (!f->initialized) {
        f->filtered_value = x;
        f->initialized = true;
    } else {
        f->filtered_value = f->alpha * x + (1.0f - f->alpha) * f->filtered_value;
    }

    return f->filtered_value;
}

/* =========================
 * Utility
 * ========================= */

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

/* =========================
 * Pipeline
 * ========================= */

void accel_pipeline_init(accel_pipeline_t *p,
                         float lpf_alpha,
                         float zscore_threshold,
                         float min_stddev)
{
    lowpass_filter_init(&p->lpf, lpf_alpha);
    rolling_stats_init(&p->stats);
    p->zscore_threshold = zscore_threshold;
    p->min_stddev = min_stddev;
}

anomaly_result_t accel_pipeline_process(accel_pipeline_t *p, const accel_sample_t *sample)
{
    anomaly_result_t result;
    memset(&result, 0, sizeof(result));

    result.raw_magnitude = accel_magnitude(sample);
    result.filtered_magnitude = lowpass_filter_update(&p->lpf, result.raw_magnitude);

    /* Compute baseline before inserting current sample to avoid diluting anomaly */
    result.mean = rolling_stats_mean(&p->stats);
    result.stddev = rolling_stats_stddev(&p->stats);

    float effective_stddev = result.stddev;
    if (effective_stddev < p->min_stddev) {
        effective_stddev = p->min_stddev;
    }

    if (p->stats.count >= ACCEL_WINDOW_SIZE / 2) {
        result.zscore = (result.filtered_magnitude - result.mean) / effective_stddev;
        if (result.zscore < 0.0f) {
            result.zscore = -result.zscore;
        }
        result.anomaly = (result.zscore >= p->zscore_threshold);
    } else {
        result.zscore = 0.0f;
        result.anomaly = false;
    }

    rolling_stats_update(&p->stats, result.filtered_magnitude);

    return result;
}

/* =========================
 * Example / Test Harness
 * ========================= */

int main(void)
{
    accel_pipeline_t pipeline;
    accel_pipeline_init(&pipeline,
                        ACCEL_LPF_ALPHA,
                        ACCEL_ZSCORE_THRESHOLD,
                        ACCEL_MIN_STDDEV);

    accel_sample_t samples[] = {
        {0.01f, 0.02f, 0.98f, 0},
        {0.00f, 0.01f, 1.01f, 10},
        {0.02f, 0.01f, 0.99f, 20},
        {0.01f, 0.00f, 1.00f, 30},
        {0.03f, 0.02f, 1.02f, 40},
        {0.02f, 0.01f, 0.97f, 50},
        {0.01f, 0.02f, 1.00f, 60},
        {0.00f, 0.01f, 0.99f, 70},
        {0.50f, 0.60f, 1.80f, 80}, /* anomaly */
        {0.01f, 0.01f, 1.00f, 90},
        {0.02f, 0.02f, 0.98f, 100},
    };

    size_t n = sizeof(samples) / sizeof(samples[0]);

    for (size_t i = 0; i < n; i++) {
        anomaly_result_t r = accel_pipeline_process(&pipeline, &samples[i]);

        printf("t=%lu ms raw=%.3f filt=%.3f mean=%.3f std=%.3f z=%.3f anomaly=%s\n",
               (unsigned long)samples[i].timestamp_ms,
               r.raw_magnitude,
               r.filtered_magnitude,
               r.mean,
               r.stddev,
               r.zscore,
               r.anomaly ? "YES" : "NO");
    }

    return 0;
}
```

