Below is an initial embedded-oriented implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple pipeline structure
- Basic preprocessing
- Magnitude estimation
- Rolling statistics
- Threshold-based anomaly detection
- C code suitable as a starting point for MCU firmware

---

## Design goals

This initial version is:

- Lightweight
- Deterministic
- No dynamic allocation
- Easy to port to embedded systems
- Easy to extend later with filtering, calibration, or ML inference

Assumptions:

- Accelerometer provides `x, y, z` samples at a fixed rate
- We want to detect sudden abnormal motion/vibration
- Floating point is acceptable for the first implementation

---

## Pipeline overview

The processing stages are:

1. **Acquire sample**
   - Read raw accelerometer axes

2. **Preprocess**
   - Optional offset correction
   - Optional scaling to `g`

3. **Feature extraction**
   - Compute acceleration magnitude
   - Remove nominal gravity baseline using a slow moving average

4. **Statistics**
   - Maintain rolling mean and variance of the motion signal

5. **Anomaly detection**
   - Trigger if:
     - signal exceeds absolute threshold, or
     - z-score exceeds threshold

6. **Output**
   - Return anomaly flag and useful debug values

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define ACC_WINDOW_SIZE         32
#define ACC_EPSILON             1e-6f

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} AccelSample;

typedef struct {
    float magnitude;
    float baseline;
    float motion;
    float mean;
    float stddev;
    float zscore;
    bool anomaly;
} AnomalyResult;

typedef struct {
    float offset_x;
    float offset_y;
    float offset_z;

    float scale_x;
    float scale_y;
    float scale_z;

    float alpha_baseline;      // slow baseline tracking, e.g. 0.01
    float abs_threshold;       // absolute motion threshold
    float zscore_threshold;    // statistical threshold
} PipelineConfig;

typedef struct {
    float motion_buffer[ACC_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    float sum;
    float sum_sq;

    float baseline;
    bool baseline_initialized;
} PipelineState;

static void pipeline_init(PipelineState *state)
{
    memset(state, 0, sizeof(PipelineState));
}

static void pipeline_default_config(PipelineConfig *cfg)
{
    cfg->offset_x = 0.0f;
    cfg->offset_y = 0.0f;
    cfg->offset_z = 0.0f;

    cfg->scale_x = 1.0f;
    cfg->scale_y = 1.0f;
    cfg->scale_z = 1.0f;

    cfg->alpha_baseline = 0.01f;
    cfg->abs_threshold = 0.30f;      // in g, if scaled to g
    cfg->zscore_threshold = 3.0f;
}

static float compute_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void rolling_stats_update(PipelineState *state, float value, float *mean, float *stddev)
{
    if (state->count < ACC_WINDOW_SIZE) {
        state->motion_buffer[state->index] = value;
        state->sum += value;
        state->sum_sq += value * value;
        state->count++;
    } else {
        float old = state->motion_buffer[state->index];
        state->sum -= old;
        state->sum_sq -= old * old;

        state->motion_buffer[state->index] = value;
        state->sum += value;
        state->sum_sq += value * value;
    }

    state->index = (state->index + 1) % ACC_WINDOW_SIZE;

    float n = (float)state->count;
    *mean = state->sum / n;

    float variance = (state->sum_sq / n) - (*mean * *mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    *stddev = sqrtf(variance);
}

static AnomalyResult pipeline_process_sample(
    PipelineState *state,
    const PipelineConfig *cfg,
    const AccelSample *sample)
{
    AnomalyResult result;
    memset(&result, 0, sizeof(result));

    // 1. Offset + scale correction
    float x = (sample->x - cfg->offset_x) * cfg->scale_x;
    float y = (sample->y - cfg->offset_y) * cfg->scale_y;
    float z = (sample->z - cfg->offset_z) * cfg->scale_z;

    // 2. Magnitude
    float mag = compute_magnitude(x, y, z);
    result.magnitude = mag;

    // 3. Baseline tracking (captures gravity + slow drift)
    if (!state->baseline_initialized) {
        state->baseline = mag;
        state->baseline_initialized = true;
    } else {
        state->baseline =
            (1.0f - cfg->alpha_baseline) * state->baseline +
            cfg->alpha_baseline * mag;
    }
    result.baseline = state->baseline;

    // 4. Motion signal
    float motion = fabsf(mag - state->baseline);
    result.motion = motion;

    // 5. Rolling statistics
    rolling_stats_update(state, motion, &result.mean, &result.stddev);

    // 6. Z-score
    if (result.stddev > ACC_EPSILON) {
        result.zscore = (motion - result.mean) / result.stddev;
    } else {
        result.zscore = 0.0f;
    }

    // 7. Anomaly decision
    bool abs_trigger = (motion > cfg->abs_threshold);
    bool z_trigger = (result.zscore > cfg->zscore_threshold);

    result.anomaly = abs_trigger || z_trigger;

    return result;
}
```

