Below is an initial embedded-oriented implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple processing pipeline
- Basic filtering
- Magnitude computation
- Rolling baseline estimation
- Threshold-based anomaly detection
- C-friendly, embedded-style code in C
- Notes for adapting to MCU firmware

---

## Design goals

This initial version is intended to be:

- Lightweight
- Deterministic
- Easy to run on microcontrollers
- Easy to tune later

Pipeline stages:

1. Read raw accelerometer sample `(ax, ay, az)`
2. Remove offset / smooth noise with a low-pass filter
3. Compute acceleration magnitude
4. Estimate normal baseline and variability
5. Detect anomaly when deviation exceeds threshold
6. Emit anomaly event

---

## Assumptions

- Accelerometer samples arrive at a fixed rate
- Input units are in `g` or raw counts converted to `g`
- We want a simple online detector, not ML-based
- Floating point is available; if not, this can be converted to fixed-point later

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;          // low-pass filter coefficient
    float mean_alpha;     // baseline mean update rate
    float var_alpha;      // baseline variance update rate
    float threshold_k;    // anomaly threshold multiplier
    float min_stddev;     // floor to avoid divide-by-zero / over-sensitivity
    uint32_t cooldown_samples; // suppress repeated alerts
} AnomalyConfig;

typedef struct {
    // Filtered accelerometer
    float fx;
    float fy;
    float fz;

    // Running baseline on magnitude
    float mean;
    float var;

    // State
    bool initialized;
    uint32_t cooldown_remaining;
    uint32_t sample_count;
} AnomalyState;

typedef struct {
    bool anomaly;
    float score;          // normalized deviation
    float magnitude;
    float mean;
    float stddev;
} AnomalyResult;

static void anomaly_init(AnomalyState *state, const AnomalyConfig *cfg) {
    (void)cfg;
    state->fx = 0.0f;
    state->fy = 0.0f;
    state->fz = 0.0f;
    state->mean = 0.0f;
    state->var = 0.0f;
    state->initialized = false;
    state->cooldown_remaining = 0;
    state->sample_count = 0;
}

static float low_pass(float prev, float input, float alpha) {
    return prev + alpha * (input - prev);
}

static AnomalyResult anomaly_process_sample(
    AnomalyState *state,
    const AnomalyConfig *cfg,
    AccelSample sample
) {
    AnomalyResult result = {0};

    // Initialize filter state on first sample
    if (!state->initialized) {
        state->fx = sample.x;
        state->fy = sample.y;
        state->fz = sample.z;

        float mag0 = sqrtf(sample.x * sample.x +
                           sample.y * sample.y +
                           sample.z * sample.z);

        state->mean = mag0;
        state->var = 0.0f;
        state->initialized = true;
        state->sample_count = 1;

        result.anomaly = false;
        result.score = 0.0f;
        result.magnitude = mag0;
        result.mean = state->mean;
        result.stddev = cfg->min_stddev;
        return result;
    }

    // 1. Low-pass filter each axis
    state->fx = low_pass(state->fx, sample.x, cfg->alpha);
    state->fy = low_pass(state->fy, sample.y, cfg->alpha);
    state->fz = low_pass(state->fz, sample.z, cfg->alpha);

    // 2. Compute magnitude
    float mag = sqrtf(state->fx * state->fx +
                      state->fy * state->fy +
                      state->fz * state->fz);

    // 3. Compute deviation from baseline
    float stddev = sqrtf(state->var);
    if (stddev < cfg->min_stddev) {
        stddev = cfg->min_stddev;
    }

    float deviation = fabsf(mag - state->mean);
    float score = deviation / stddev;

    // 4. Detect anomaly
    bool anomaly = false;
    if (state->sample_count > 10 && state->cooldown_remaining == 0) {
        if (score > cfg->threshold_k) {
            anomaly = true;
            state->cooldown_remaining = cfg->cooldown_samples;
        }
    }

    // 5. Update baseline
    // For a simple robust behavior, avoid learning too fast from anomalies.
    float mean_alpha = cfg->mean_alpha;
    float var_alpha = cfg->var_alpha;
    if (anomaly) {
        mean_alpha *= 0.1f;
        var_alpha *= 0.1f;
    }

    float delta = mag - state->mean;
    state->mean += mean_alpha * delta;

    float delta2 = mag - state->mean;
    float inst_var = delta * delta2;
    state->var = (1.0f - var_alpha) * state->var + var_alpha * inst_var;

    // 6. Update timers/counters
    if (state->cooldown_remaining > 0) {
        state->cooldown_remaining--;
    }
    state->sample_count++;

    result.anomaly = anomaly;
    result.score = score;
    result.magnitude = mag;
    result.mean = state->mean;
    result.stddev = stddev;

    return result;
}
```

