Below is a **minimal working embedded sensor-processing pipeline** in **C** that:

- simulates **accelerometer samples**
- computes a simple **magnitude-based feature**
- applies a tiny **moving average**
- detects **anomalies** using a threshold
- prints results

It is written to be easy to port to a microcontroller.

---

## Features

Pipeline stages:

1. **Read accelerometer sample** `(x, y, z)`
2. **Compute magnitude approximation**
3. **Smooth with moving average**
4. **Compare against baseline threshold**
5. **Raise anomaly flag**

This is intentionally simple and minimal.

---

## Minimal C Example

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#define WINDOW_SIZE 8
#define ANOMALY_THRESHOLD 1800

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

// Simple abs for embedded-style portability
static int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

// Cheap magnitude approximation: |x| + |y| + |z|
static int32_t accel_magnitude(const AccelSample *s) {
    return iabs32(s->x) + iabs32(s->y) + iabs32(s->z);
}

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static int32_t filter_update(MovingAverageFilter *f, int32_t sample) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = sample;
    f->sum += sample;

    f->index = (f->index + 1) % WINDOW_SIZE;
    if (f->count < WINDOW_SIZE) {
        f->count++;
    }

    return f->sum / f->count;
}

static uint8_t detect_anomaly(int32_t filtered_magnitude) {
    return (filtered_magnitude > ANOMALY_THRESHOLD) ? 1 : 0;
}

// Simulated sensor input
static AccelSample get_sample(int t) {
    AccelSample s;

    // Normal motion around ~1g on Z plus small variation
    s.x = (t % 5) * 10 - 20;
    s.y = (t % 7) * 8 - 24;
    s.z = 1000 + ((t % 3) * 15 - 15);

    // Inject anomaly
    if (t == 20 || t == 21) {
        s.x = 900;
        s.y = 850;
        s.z = 1200;
    }

    return s;
}

int main(void) {
    MovingAverageFilter filter;
    filter_init(&filter);

    for (int t = 0; t < 40; t++) {
        AccelSample s = get_sample(t);
        int32_t mag = accel_magnitude(&s);
        int32_t filtered = filter_update(&filter, mag);
        uint8_t anomaly = detect_anomaly(filtered);

        printf("t=%2d  x=%5d y=%5d z=%5d  mag=%5ld  avg=%5ld  anomaly=%d\n",
               t, s.x, s.y, s.z, (long)mag, (long)filtered, anomaly);
    }

    return 0;
}
```

---

## How it works

### 1. Magnitude feature
Instead of using:

```c
