## Minimal C Example

```c
#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define WINDOW_SIZE 16
#define THRESHOLD   2.5f
#define NUM_SAMPLES 100

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / ma->count;
}

float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

int detect_anomaly(float current, float baseline) {
    float deviation = fabsf(current - baseline);
    return deviation > THRESHOLD;
}

/* Simulated accelerometer input */
AccelSample read_accelerometer(int t) {
    AccelSample s;

    /* Normal operating vibration around gravity */
    s.ax = 0.02f * sinf(0.1f * t);
    s.ay = 0.03f * cosf(0.1f * t);
    s.az = 1.0f + 0.02f * sinf(0.05f * t);

    /* Inject anomaly */
    if (t == 60) {
        s.ax += 3.0f;
        s.ay += 2.5f;
        s.az += 1.5f;
    }

    return s;
}

int main(void) {
    MovingAverage baseline_filter;
    ma_init(&baseline_filter);

    for (int t = 0; t < NUM_SAMPLES; t++) {
        AccelSample sample = read_accelerometer(t);
        float mag = accel_magnitude(sample);
        float baseline = ma_update(&baseline_filter, mag);

        int anomaly = 0;

        /* Wait until enough samples collected */
        if (baseline_filter.count >= WINDOW_SIZE) {
            anomaly = detect_anomaly(mag, baseline);
        }

        printf("t=%3d ax=%6.3f ay=%6.3f az=%6.3f mag=%6.3f baseline=%6.3f anomaly=%d\n",
               t, sample.ax, sample.ay, sample.az, mag, baseline, anomaly);
    }

    return 0;
}
```

