## Minimal C Example

```c
#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 3.0f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean_mag;
    float max_mag;
} Features;

// Compute magnitude of acceleration vector
float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Extract simple features from a window
Features extract_features(AccelSample *window, int size) {
    Features f = {0};
    float sum = 0.0f;
    float max = 0.0f;

    for (int i = 0; i < size; i++) {
        float mag = magnitude(window[i]);
        sum += mag;
        if (mag > max) {
            max = mag;
        }
    }

    f.mean_mag = sum / size;
    f.max_mag = max;
    return f;
}

// Simple anomaly detector
bool detect_anomaly(Features f, float baseline_mean) {
    return (f.max_mag - baseline_mean) > ANOMALY_THRESHOLD;
}

// Simulated sensor read
AccelSample read_accel_sample(int t) {
    AccelSample s;

    // Normal motion around 1g on Z axis
    s.x = 0.05f * sinf(0.1f * t);
    s.y = 0.05f * cosf(0.1f * t);
    s.z = 1.0f + 0.02f * sinf(0.2f * t);

    // Inject anomaly
    if (t == 50) {
        s.x = 4.0f;
        s.y = 3.5f;
        s.z = 5.0f;
    }

    return s;
}

int main(void) {
    AccelSample window[WINDOW_SIZE];
    int count = 0;
    float baseline_mean = 1.0f; // expected normal magnitude

    for (int t = 0; t < 100; t++) {
        AccelSample sample = read_accel_sample(t);

        // Fill sliding window
        window[count % WINDOW_SIZE] = sample;
        count++;

        if (count >= WINDOW_SIZE) {
            Features f = extract_features(window, WINDOW_SIZE);
            bool anomaly = detect_anomaly(f, baseline_mean);

            printf("t=%d mean=%.2f max=%.2f anomaly=%s\n",
                   t, f.mean_mag, f.max_mag, anomaly ? "YES" : "NO");
        }
    }

    return 0;
}
