## 2. Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 8
#define ANOMALY_THRESHOLD 2.5f

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} SensorPipeline;

void pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->mag_window[i] = 0.0f;
    }
    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
}

float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

float update_moving_average(SensorPipeline *p, float mag) {
    if (p->count < WINDOW_SIZE) {
        p->mag_window[p->index] = mag;
        p->sum += mag;
        p->count++;
    } else {
        p->sum -= p->mag_window[p->index];
        p->mag_window[p->index] = mag;
        p->sum += mag;
    }

    p->index = (p->index + 1) % WINDOW_SIZE;
    return p->sum / p->count;
}

int detect_anomaly(float mag, float avg) {
    float deviation = fabsf(mag - avg);
    return (deviation > ANOMALY_THRESHOLD) ? 1 : 0;
}

void process_sample(SensorPipeline *p, float ax, float ay, float az) {
    float mag = compute_magnitude(ax, ay, az);
    float avg = update_moving_average(p, mag);
    int anomaly = detect_anomaly(mag, avg);

    printf("ax=%.2f ay=%.2f az=%.2f mag=%.2f avg=%.2f anomaly=%d\n",
           ax, ay, az, mag, avg, anomaly);
}

int main() {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    // Simulated accelerometer samples
    float samples[][3] = {
        {0.1f, 0.0f, 1.0f},
        {0.0f, 0.1f, 0.9f},
        {0.2f, 0.1f, 1.1f},
        {0.1f, 0.0f, 1.0f},
        {0.0f, 0.2f, 1.0f},
        {0.1f, 0.1f, 0.95f},
        {0.0f, 0.0f, 1.05f},
        {0.1f, 0.0f, 1.0f},
        // Anomalous spike
        {3.0f, 2.5f, 0.5f},
        {0.1f, 0.0f, 1.0f},
        {0.0f, 0.1f, 1.0f}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        process_sample(&pipeline, samples[i][0], samples[i][1], samples[i][2]);
    }

    return 0;
}
```

