## 2) Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define THRESHOLD 2.5f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mag_window[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverageDetector;

void detector_init(MovingAverageDetector *det) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
    det->index = 0;
    det->count = 0;
    det->sum = 0.0f;
}

float compute_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

float update_moving_average(MovingAverageDetector *det, float value) {
    if (det->count < WINDOW_SIZE) {
        det->mag_window[det->index] = value;
        det->sum += value;
        det->count++;
    } else {
        det->sum -= det->mag_window[det->index];
        det->mag_window[det->index] = value;
        det->sum += value;
    }

    det->index = (det->index + 1) % WINDOW_SIZE;
    return det->sum / det->count;
}

int detect_anomaly(MovingAverageDetector *det, AccelSample sample) {
    float mag = compute_magnitude(sample);
    float avg = update_moving_average(det, mag);
    float deviation = fabsf(mag - avg);

    if (deviation > THRESHOLD) {
        return 1;
    }
    return 0;
}

int main() {
