## Minimal embedded anomaly detector in C

```c
#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ACC_NORM_G 1.0f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean_mag;
    float var_mag;
} Features;

typedef struct {
    AccelSample buffer[WINDOW_SIZE];
    int index;
    bool full;
} SampleWindow;

/* ---------- Sensor input (mock) ---------- */
AccelSample read_accelerometer(void) {
    static int t = 0;
    t++;

    AccelSample s;

    /* Normal motion around 1g on Z axis */
    s.x = 0.02f * sinf(0.1f * t);
    s.y = 0.02f * cosf(0.1f * t);
    s.z = 1.0f + 0.01f * sinf(0.05f * t);

    /* Inject anomaly */
    if (t == 60 || t == 61 || t == 62) {
        s.x = 2.0f;
        s.y = 1.5f;
        s.z = 0.2f;
    }

    return s;
}

/* ---------- Window management ---------- */
void window_init(SampleWindow *w) {
    w->index = 0;
    w->full = false;
}

void window_add(SampleWindow *w, AccelSample s) {
    w->buffer[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->index == 0) {
        w->full = true;
    }
}

/* ---------- Preprocessing ---------- */
float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* ---------- Feature extraction ---------- */
Features extract_features(const SampleWindow *w) {
    Features f = {0};
    float mags[WINDOW_SIZE];
    float sum = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        mags[i] = accel_magnitude(w->buffer[i]);
        sum += mags[i];
    }

    f.mean_mag = sum / WINDOW_SIZE;

    float var_sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float d = mags[i] - f.mean_mag;
        var_sum += d * d;
    }

    f.var_mag = var_sum / WINDOW_SIZE;
    return f;
}

/* ---------- Anomaly detection ---------- */
bool detect_anomaly(Features f) {
    /* Very simple thresholds for demo */
    if (fabsf(f.mean_mag - ACC_NORM_G) > 0.2f) {
        return true;
    }
    if (f.var_mag > 0.05f) {
        return true;
    }
    return false;
}

/* ---------- Main pipeline ---------- */
int main(void) {
    SampleWindow window;
    window_init(&window);

    for (int i = 0; i < 100; i++) {
        AccelSample sample = read_accelerometer();
        window_add(&window, sample);

        if (window.full) {
            Features feat = extract_features(&window);
            bool anomaly = detect_anomaly(feat);

            printf("t=%d mean=%.3f var=%.3f anomaly=%s\n",
                   i,
                   feat.mean_mag,
                   feat.var_mag,
