## Minimal C Example

```c
#include <stdio.h>
#include <stdint.h>

#define WINDOW_SIZE 8
#define ANOMALY_THRESHOLD 1500000L
#define COOLDOWN_SAMPLES 5

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
} AccelSample;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    int64_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverage;

static void ma_init(MovingAverage *ma) {
    ma->sum = 0;
    ma->index = 0;
    ma->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0;
    }
}

static int32_t ma_update(MovingAverage *ma, int32_t value) {
    ma->sum -= ma->buffer[ma->index];
    ma->buffer[ma->index] = value;
    ma->sum += value;

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    }

    return (int32_t)(ma->sum / ma->count);
}

static int32_t compute_magnitude_sq(AccelSample s) {
    return (int32_t)s.ax * s.ax +
           (int32_t)s.ay * s.ay +
           (int32_t)s.az * s.az;
}

static int detect_anomaly(int32_t filtered_mag_sq, int *cooldown) {
    if (*cooldown > 0) {
        (*cooldown)--;
        return 0;
    }

    if (filtered_mag_sq > ANOMALY_THRESHOLD) {
        *cooldown = COOLDOWN_SAMPLES;
        return 1;
    }

    return 0;
}

int main(void) {
    MovingAverage ma;
    ma_init(&ma);

    int cooldown = 0;

    /* Simulated accelerometer stream */
    AccelSample samples[] = {
        {  10,   20, 1000},
        {  12,   18,  995},
        {   8,   22, 1003},
        {  15,   19,  998},
        {  11,   21, 1001},
        { 500,  600, 1600}, /* anomaly */
        {  10,   20, 1002},
        {   9,   19,  999},
        {  13,   17, 1004},
        { 700, -800, 1700}, /* anomaly */
        {  10,   20, 1000},
        {  11,   18, 1001}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        int32_t mag_sq = compute_magnitude_sq(samples[i]);
        int32_t filtered = ma_update(&ma, mag_sq);

        if (detect_anomaly(filtered, &cooldown)) {
            printf("Anomaly detected at sample %d: filtered_mag_sq=%ld\n",
                   i, (long)filtered);
        } else {
            printf("Sample %d: filtered_mag_sq=%ld\n", i, (long)filtered);
        }
    }

    return 0;
}
```

