#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mag_buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} SensorPipeline;

void pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->mag_buffer[i] = 0.0f;
    }
    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
}

float compute_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

int pipeline_process(SensorPipeline *p, AccelSample s, float *score_out) {
    float mag = compute_magnitude(s);

    // Update moving average window
    if (p->count < WINDOW_SIZE) {
        p->mag_buffer[p->index] = mag;
        p->sum += mag;
        p->count++;
    } else {
        p->sum -= p->mag_buffer[p->index];
        p->mag_buffer[p->index] = mag;
        p->sum += mag;
    }

    p->index = (p->index + 1) % WINDOW_SIZE;

    float mean = p->sum / p->count;

    // Simple anomaly score: absolute deviation from moving average
    float score = fabsf(mag - mean);
    *score_out = score;

    return (score > ANOMALY_THRESHOLD) ? 1 : 0;
}

int main() {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    // Simulated accelerometer stream
    AccelSample samples[] = {
