        {0.0f, 0.0f, 1.0f},
        {0.02f, 0.01f, 0.99f}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        float score;
        int anomaly = pipeline_process(&pipeline, samples[i], &score);

        printf("Sample %d: score=%.3f %s\n",
               i,
               score,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
