    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        int anomaly = detect_anomaly(&baseline, samples[i]);
        float mag = compute_magnitude(samples[i]);

        printf("Sample %d: mag=%.3f -> %s\n",
