Below is a minimal working example of an embedded-style sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- simulated accelerometer input
- simple preprocessing
- feature extraction
- anomaly detection using a rolling baseline
- alert output

I’ll provide it in C, keeping it small and microcontroller-friendly.

---

## Overview

Pipeline:

1. **Read accelerometer sample** `(ax, ay, az)`
2. **Compute magnitude**
3. **Low-pass filter**
4. **Compare against rolling mean**
5. **Flag anomaly if deviation exceeds threshold**

This is not production-grade, but it is a good minimal starting point for embedded systems.

---

## Minimal C Example

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define THRESHOLD 0.35f
#define ALPHA 0.2f   // low-pass filter coefficient

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} RollingStats;

static float lowpass_filter(float input) {
    static float prev = 0.0f;
    prev = ALPHA * input + (1.0f - ALPHA) * prev;
    return prev;
}

static float magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void rolling_init(RollingStats *rs) {
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rs->buffer[i] = 0.0f;
    }
}

static float rolling_mean(RollingStats *rs) {
    if (rs->count == 0) return 0.0f;
    return rs->sum / rs->count;
}

static void rolling_update(RollingStats *rs, float value) {
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->count++;
    } else {
        rs->sum -= rs->buffer[rs->index];
        rs->buffer[rs->index] = value;
        rs->sum += value;
    }
    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

static int detect_anomaly(RollingStats *rs, float value) {
    float mean = rolling_mean(rs);
    float diff = fabsf(value - mean);
    return (rs->count >= WINDOW_SIZE && diff > THRESHOLD);
}

// Simulated sensor stream
static AccelSample get_sample(int t) {
    AccelSample s;

    // Normal motion around 1g magnitude
    s.ax = 0.02f * sinf(0.1f * t);
    s.ay = 0.03f * cosf(0.1f * t);
    s.az = 1.00f + 0.01f * sinf(0.05f * t);

    // Inject anomaly
    if (t == 80 || t == 81 || t == 82) {
        s.ax += 1.2f;
        s.ay += 0.8f;
    }

    return s;
}

int main(void) {
    RollingStats stats;
    rolling_init(&stats);

    for (int t = 0; t < 150; t++) {
        AccelSample s = get_sample(t);

        // Step 1: feature extraction
        float mag = magnitude(s);

        // Step 2: filtering
        float filtered = lowpass_filter(mag);

        // Step 3: anomaly detection
        int anomaly = detect_anomaly(&stats, filtered);

        // Step 4: update baseline after detection check
        rolling_update(&stats, filtered);

        // Output
        printf("t=%3d mag=%.3f filt=%.3f mean=%.3f %s\n",
               t,
               mag,
               filtered,
               rolling_mean(&stats),
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

---

## How it works

### 1. Magnitude
Instead of using raw `x/y/z` separately, we compute:

```c
sqrt(ax^2 + ay^2 + az^2)
```

This gives a single motion-strength value.

### 2. Low-pass filter
We smooth noise with:

```c
prev = alpha * input + (1 - alpha) * prev;
```

### 3. Rolling mean baseline
We maintain a moving average over the last `WINDOW_SIZE` samples.

### 4. Anomaly rule
If the current filtered magnitude differs from the rolling mean by more than `THRESHOLD`, we flag it.

