Below is a minimal working example of an embedded-style sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- simulated accelerometer input
- simple preprocessing
- feature extraction over a sliding window
- anomaly detection using thresholds
- C code suitable as a starting point for microcontrollers

---

## Overview

Pipeline:

1. **Read accelerometer sample** `(ax, ay, az)`
2. **Compute magnitude**
3. **Store in sliding window**
4. **Extract simple features**
   - mean
   - variance
   - peak-to-peak
5. **Detect anomaly**
   - if variance or peak-to-peak exceeds threshold

This is intentionally minimal and avoids dynamic allocation, floating-point-heavy DSP, or ML dependencies.

---

## Minimal C Implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 32

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    bool full;
} SlidingWindow;

typedef struct {
    float mean;
    float variance;
    float peak_to_peak;
} Features;

static void window_init(SlidingWindow *w) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buffer[i] = 0.0f;
    }
    w->index = 0;
    w->full = false;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void window_add(SlidingWindow *w, float value) {
    w->buffer[w->index] = value;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->index == 0) {
        w->full = true;
    }
}

static bool window_ready(const SlidingWindow *w) {
    return w->full;
}

static Features extract_features(const SlidingWindow *w) {
    Features f = {0};
    float sum = 0.0f;
    float minv = w->buffer[0];
    float maxv = w->buffer[0];

    for (int i = 0; i < WINDOW_SIZE; i++) {
        float x = w->buffer[i];
        sum += x;
        if (x < minv) minv = x;
        if (x > maxv) maxv = x;
    }

    f.mean = sum / WINDOW_SIZE;

    float var_sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float d = w->buffer[i] - f.mean;
        var_sum += d * d;
    }

    f.variance = var_sum / WINDOW_SIZE;
    f.peak_to_peak = maxv - minv;

    return f;
}

static bool detect_anomaly(Features f) {
    const float VAR_THRESHOLD = 0.50f;
    const float P2P_THRESHOLD = 2.00f;

    if (f.variance > VAR_THRESHOLD) return true;
    if (f.peak_to_peak > P2P_THRESHOLD) return true;

    return false;
}

/* Simulated sensor stream */
static AccelSample get_next_sample(int t) {
    AccelSample s;

    /* Normal motion around 1g on Z */
    s.ax = 0.02f * sinf(0.1f * t);
    s.ay = 0.03f * cosf(0.1f * t);
    s.az = 1.0f + 0.02f * sinf(0.05f * t);

    /* Inject anomaly */
    if (t >= 80 && t < 85) {
        s.ax += 2.5f;
        s.ay += 1.5f;
    }

    return s;
}

int main(void) {
    SlidingWindow window;
    window_init(&window);

    for (int t = 0; t < 150; t++) {
        AccelSample sample = get_next_sample(t);

        /* Step 1: preprocess -> magnitude */
        float mag = accel_magnitude(sample);

        /* Step 2: update window */
        window_add(&window, mag);

        /* Step 3: when enough samples are collected, extract features */
        if (window_ready(&window)) {
            Features f = extract_features(&window);
            bool anomaly = detect_anomaly(f);

            printf("t=%3d mag=%.3f mean=%.3f var=%.3f p2p=%.3f anomaly=%s\n",
                   t, mag, f.mean, f.variance, f.peak_to_peak,
                   anomaly ? "YES" : "NO");
        } else {
            printf("t=%3d mag=%.3f warming_up\n", t, mag);
        }
    }

    return 0;
}
```

---

## How it works

### 1. Magnitude conversion
Instead of processing `ax`, `ay`, `az` separately, we reduce them to:

```c
sqrt(ax^2 + ay^2 + az^2)
```

This makes the detector orientation-tolerant.

### 2. Sliding window
A fixed-size circular buffer stores recent magnitudes.

### 3. Feature extraction
For each full window:

- **mean**: baseline activity
- **variance**: motion intensity / instability
- **peak-to-peak**: sudden spikes

### 4. Threshold detector
