- a tiny Python generator for test data

---

# 1. Design

Pipeline:

1. **Read accelerometer sample** `(ax, ay, az)`
2. **Compute magnitude**
   \[
   m = \sqrt{ax^2 + ay^2 + az^2}
   \]
3. **High-pass / detrend** using deviation from 1g baseline
4. **Windowed energy estimate**
5. **Threshold-based anomaly detection**
6. **Raise alert if energy exceeds threshold**

This is intentionally simple and practical for embedded systems.

---

# 2. Minimal embedded C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define BASELINE_G 1.0f
#define ANOMALY_THRESHOLD 0.15f

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} EnergyWindow;

static void window_init(EnergyWindow *w) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buffer[i] = 0.0f;
    }
    w->index = 0;
    w->count = 0;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static float preprocess(AccelSample s) {
    float mag = accel_magnitude(s);
    return fabsf(mag - BASELINE_G);
}

static void window_add(EnergyWindow *w, float value) {
    w->buffer[w->index] = value * value;  // energy contribution
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static float window_mean_energy(EnergyWindow *w) {
    if (w->count == 0) return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        sum += w->buffer[i];
    }
    return sum / w->count;
}

static int detect_anomaly(float mean_energy) {
    return mean_energy > ANOMALY_THRESHOLD;
}

int main(void) {
    EnergyWindow window;
    window_init(&window);

    // Simulated accelerometer stream
    AccelSample samples[] = {
        {0.01f, 0.02f, 0.99f},
        {0.00f, 0.01f, 1.02f},
        {0.02f, 0.01f, 0.98f},
        {0.01f, 0.00f, 1.01f},
        {0.03f, 0.02f, 0.97f},
        {0.50f, 0.40f, 1.30f}, // anomaly starts
        {0.60f, 0.55f, 1.40f},
        {0.45f, 0.35f, 1.25f},
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.01f, 0.99f}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        float signal = preprocess(samples[i]);
        window_add(&window, signal);
        float energy = window_mean_energy(&window);
        int anomaly = detect_anomaly(energy);

        printf("sample=%2d signal=%0.4f energy=%0.4f anomaly=%d\n",
               i, signal, energy, anomaly);
    }

    return 0;
}
```

