Below is a **minimal working example** of an embedded-style sensor-processing pipeline for **accelerometer anomaly detection**.

It includes:

- simulated accelerometer input
- simple preprocessing
- feature extraction
- anomaly detection using a lightweight threshold method
- C code suitable for microcontroller-style environments

---

## 1. Design

Pipeline:

1. **Read accelerometer sample**: `ax, ay, az`
2. **Compute magnitude**: `sqrt(ax² + ay² + az²)`
3. **Smooth signal** with exponential moving average
4. **Estimate baseline** slowly
5. **Detect anomaly** if deviation exceeds threshold

This is intentionally minimal and practical for embedded systems.

---

## 2. Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float ema;         // fast-smoothed signal
    float baseline;    // slow baseline
    float alpha_fast;  // smoothing factor for signal
    float alpha_slow;  // smoothing factor for baseline
    float threshold;   // anomaly threshold
    uint8_t initialized;
} AnomalyDetector;

void detector_init(AnomalyDetector *det, float alpha_fast, float alpha_slow, float threshold) {
    det->ema = 0.0f;
    det->baseline = 0.0f;
    det->alpha_fast = alpha_fast;
    det->alpha_slow = alpha_slow;
    det->threshold = threshold;
    det->initialized = 0;
}

float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

int detector_update(AnomalyDetector *det, float ax, float ay, float az, float *score_out) {
    float mag = accel_magnitude(ax, ay, az);

    if (!det->initialized) {
        det->ema = mag;
        det->baseline = mag;
        det->initialized = 1;
    }

    // Fast smoothing
    det->ema = det->alpha_fast * mag + (1.0f - det->alpha_fast) * det->ema;

    // Slow baseline tracking
    det->baseline = det->alpha_slow * det->ema + (1.0f - det->alpha_slow) * det->baseline;

    // Anomaly score = absolute deviation from baseline
    float score = fabsf(det->ema - det->baseline);
    *score_out = score;

    return (score > det->threshold) ? 1 : 0;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector, 0.2f, 0.01f, 0.5f);

    // Simulated accelerometer data: mostly around 1g, with one anomaly spike
    float samples[][3] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.02f},
        {0.03f, 0.02f, 0.99f},
        {0.02f, 0.01f, 1.01f},
        {1.20f, 0.80f, 2.50f}, // anomaly
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 0.97f},
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        float score;
        int anomaly = detector_update(
            &detector,
            samples[i][0],
            samples[i][1],
            samples[i][2],
            &score
        );

        printf("Sample %d: ax=%.2f ay=%.2f az=%.2f score=%.3f %s\n",
               i,
               samples[i][0],
               samples[i][1],
               samples[i][2],
               score,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

