# 2. Embedded C implementation

```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define WINDOW_SIZE 8
#define THRESHOLD 50000  // tune for your sensor scale

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int64_t sum;
    int32_t baseline;
} AnomalyDetector;

void detector_init(AnomalyDetector *det, int32_t baseline) {
    det->index = 0;
    det->count = 0;
    det->sum = 0;
    det->baseline = baseline;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->buffer[i] = 0;
    }
}

int detector_update(AnomalyDetector *det, int16_t ax, int16_t ay, int16_t az) {
    int32_t m2 = (int32_t)ax * ax + (int32_t)ay * ay + (int32_t)az * az;

    if (det->count < WINDOW_SIZE) {
        det->buffer[det->index] = m2;
        det->sum += m2;
        det->count++;
    } else {
        det->sum -= det->buffer[det->index];
        det->buffer[det->index] = m2;
        det->sum += m2;
    }

    det->index = (det->index + 1) % WINDOW_SIZE;

    int32_t avg = (int32_t)(det->sum / det->count);
    int32_t diff = avg - det->baseline;
    if (diff < 0) diff = -diff;

    return (diff > THRESHOLD) ? 1 : 0;
}

/* Simulated sensor stream */
typedef struct {
    int16_t ax, ay, az;
} Sample;

Sample test_data[] = {
    {0, 0, 1000},
