    {-4, 2, 1003},
    {3, 1, 998},
    {0, 0, 1001},
    {2, -2, 999},
    {300, 400, 1300},   // anomaly
    {350, 450, 1250},   // anomaly
    {1, 0, 1002},
    {-2, 3, 997}
};

int main(void) {
    AnomalyDetector det;

    // baseline for ~1g if sensor outputs about 1000 on Z:
    // 0^2 + 0^2 + 1000^2 = 1,000,000
    detector_init(&det, 1000000);

    int n = sizeof(test_data) / sizeof(test_data[0]);

    for (int i = 0; i < n; i++) {
        int anomaly = detector_update(&det,
                                      test_data[i].ax,
                                      test_data[i].ay,
                                      test_data[i].az);

        printf("sample %d: ax=%d ay=%d az=%d -> %s\n",
               i,
               test_data[i].ax,
               test_data[i].ay,
               test_data[i].az,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

