    int16_t temp_high_off;
    int16_t pressure_high_on;
    int16_t pressure_high_off;
    int16_t hum_low_on;
    int16_t hum_low_off;
} ThresholdConfig;

static MovingAverageFilter filters[NUM_SENSORS];
static ActuatorState actuators;
static const ThresholdConfig config = {
    .temp_high_on = 300,      // e.g. 30.0 C if scaled by 10
    .temp_high_off = 280,
    .pressure_high_on = 1200, // arbitrary units
    .pressure_high_off = 1100,
    .hum_low_on = 350,        // e.g. 35.0%
    .hum_low_off = 400
};

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->filled = false;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = sample;
    f->sum += sample;

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
        f->filled = true;
    }

    uint8_t count = f->filled ? FILTER_WINDOW : f->index;
    if (count == 0) {
        return sample;
    }

    return (int16_t)(f->sum / count);
}

/* Replace these with hardware-specific drivers */
