            demo_values[TEMP_SENSOR] += 1;
            return demo_values[TEMP_SENSOR];
        case PRESS_SENSOR:
            demo_values[PRESS_SENSOR] += 3;
            return demo_values[PRESS_SENSOR];
        case HUM_SENSOR:
