    if (!actuators.cooling_fan && temp >= config.temp_high_on) {
        set_cooling_fan(true);
    } else if (actuators.cooling_fan && temp <= config.temp_high_off) {
        set_cooling_fan(false);
    }

    if (!actuators.pressure_valve && pressure >= config.pressure_high_on) {
        set_pressure_valve(true);
    } else if (actuators.pressure_valve && pressure <= config.pressure_high_off) {
        set_pressure_valve(false);
    }

    if (!actuators.humidifier && humidity <= config.hum_low_on) {
        set_humidifier(true);
    } else if (actuators.humidifier && humidity >= config.hum_low_off) {
        set_humidifier(false);
    }
}

static void system_init(void) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        filter_init(&filters[i]);
    }

    actuators.cooling_fan = false;
    actuators.pressure_valve = false;
    actuators.humidifier = false;
}

static void process_cycle(void) {
    int16_t raw_temp = read_sensor(TEMP_SENSOR);
    int16_t raw_pressure = read_sensor(PRESS_SENSOR);
    int16_t raw_humidity = read_sensor(HUM_SENSOR);

    int16_t filt_temp = filter_update(&filters[TEMP_SENSOR], raw_temp);
    int16_t filt_pressure = filter_update(&filters[PRESS_SENSOR], raw_pressure);
    int16_t filt_humidity = filter_update(&filters[HUM_SENSOR], raw_humidity);

    printf("Raw: T=%d P=%d H=%d | Filtered: T=%d P=%d H=%d\n",
           raw_temp, raw_pressure, raw_humidity,
           filt_temp, filt_pressure, filt_humidity);

    control_logic(filt_temp, filt_pressure, filt_humidity);
}

int main(void) {
    system_init();

    for (int i = 0; i < 20; i++) {
        process_cycle();
    }

    return 0;
}
