    /* Replace with ADC/I2C/SPI/etc. read */
    static uint16_t demo_values[NUM_SENSORS] = {100, 500, 900};
    demo_values[sensor_id] = (demo_values[sensor_id] + 17 * (sensor_id + 1)) % 1024;
    return demo_values[sensor_id];
}

static void write_actuator_hw(uint8_t actuator_id, uint8_t state) {
    /* Replace with GPIO/PWM/etc. write */
    printf("Actuator %u -> %s\n", actuator_id, state ? "ON" : "OFF");
