    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->filtered = 0;
    f->valid = false;
    for (i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static bool sensor_value_valid(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

static void sensor_filter_update(SensorFilter *f, uint16_t raw_value) {
    if (!sensor_value_valid(raw_value)) {
        f->valid = false;
        return;
    }

    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = raw_value;
        f->sum += raw_value;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = raw_value;
        f->sum += raw_value;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    f->filtered = (uint16_t)(f->sum / f->count);
    f->valid = true;
