    if (!sys->sensor.enabled) {
        hw_report_status("Sensor disabled", 0, 0);
        return;
    }

    raw = hw_read_sensor();

    if (!sensor_read_valid(raw)) {
        sys->sensor.invalid_read_count++;
        hw_report_status("Invalid sensor reading", raw, 0);

        if (sys->sensor.invalid_read_count >= SENSOR_FAULT_LIMIT) {
            sys->sensor.enabled = false;
            sys->actuator.is_on = false;
            hw_actuator_set(false);
            hw_report_status("Sensor fault: system safe state", raw, 0);
        }
        return;
    }

    sys->sensor.invalid_read_count = 0;
    filtered = filter_update(&sys->filter, raw);

    actuator_update(&sys->actuator, filtered);
    hw_report_status("Normal", raw, filtered);
}

/* =========================
 * Main
 * ========================= */
int main(void) {
    EdgeSystem system;
    uint8_t i;

    edge_system_init(&system);

    for (i = 0; i < 20; i++) {
        edge_system_step(&system);
    }

    return 0;
}
