#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define SENSOR_COUNT 2
#define FILTER_WINDOW 8

#define TEMP_SENSOR 0
#define PRESSURE_SENSOR 1

typedef struct {
    int16_t samples[FILTER_WINDOW];
    uint8_t index;
    int32_t sum;
    bool filled;
} MovingAverageFilter;

typedef struct {
    MovingAverageFilter filters[SENSOR_COUNT];
    int16_t filtered_values[SENSOR_COUNT];
    bool actuator_state[SENSOR_COUNT];
} EdgeSystem;

/* ---------- Filter Functions ---------- */

void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->sum = 0;
    f->filled = false;
    for (int i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

void edge_system_init(EdgeSystem *sys) {
    for (int i = 0; i < SENSOR_COUNT; i++) {
        filter_init(&sys->filters[i]);
        sys->filtered_values[i] = 0;
        sys->actuator_state[i] = false;
    }
}

int16_t filter_update(MovingAverageFilter *f, int16_t new_sample) {
    f->sum -= f->samples[f->index];
    f->samples[f->index] = new_sample;
    f->sum += new_sample;

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
        f->filled = true;
    }

    uint8_t divisor = f->filled ? FILTER_WINDOW : f->index;
    if (divisor == 0) {
        return new_sample;
    }

    return (int16_t)(f->sum / divisor);
}

/* ---------- Sensor Validation ---------- */

bool sensor_valid(uint8_t sensor_id, int16_t value) {
    switch (sensor_id) {
        case TEMP_SENSOR:
            return (value >= -40 && value <= 125);
        case PRESSURE_SENSOR:
            return (value >= 0 && value <= 300);
        default:
            return false;
    }
}

/* ---------- Actuator Control ---------- */

void update_actuator(EdgeSystem *sys, uint8_t sensor_id, int16_t filtered_value) {
    switch (sensor_id) {
        case TEMP_SENSOR: {
            const int16_t ON_THRESHOLD = 70;
            const int16_t OFF_THRESHOLD = 65;

            if (!sys->actuator_state[sensor_id] && filtered_value >= ON_THRESHOLD) {
                sys->actuator_state[sensor_id] = true;
                printf("TEMP actuator ON\n");
            } else if (sys->actuator_state[sensor_id] && filtered_value <= OFF_THRESHOLD) {
                sys->actuator_state[sensor_id] = false;
                printf("TEMP actuator OFF\n");
            }
            break;
        }

        case PRESSURE_SENSOR: {
            const int16_t ON_THRESHOLD = 220;
            const int16_t OFF_THRESHOLD = 200;

            if (!sys->actuator_state[sensor_id] && filtered_value >= ON_THRESHOLD) {
                sys->actuator_state[sensor_id] = true;
                printf("PRESSURE actuator ON\n");
            } else if (sys->actuator_state[sensor_id] && filtered_value <= OFF_THRESHOLD) {
                sys->actuator_state[sensor_id] = false;
                printf("PRESSURE actuator OFF\n");
            }
            break;
        }

        default:
            break;
    }
}

/* ---------- Main Processing ---------- */

void process_sensor(EdgeSystem *sys, uint8_t sensor_id, int16_t raw_value) {
    if (!sensor_valid(sensor_id, raw_value)) {
        printf("Sensor %u invalid reading: %d\n", sensor_id, raw_value);
        return;
    }

    int16_t filtered = filter_update(&sys->filters[sensor_id], raw_value);
    sys->filtered_values[sensor_id] = filtered;

    printf("Sensor %u raw=%d filtered=%d\n", sensor_id, raw_value, filtered);

    update_actuator(sys, sensor_id, filtered);
}

/* ---------- Example Input Simulation ---------- */

