    f->sum = 0;
    f->initialized = true;
}

int16_t filter_update(MovingAverageFilter *f, int16_t new_sample) {
    if (!f->initialized) {
        filter_init(f);
    }

    f->sum -= f->samples[f->index];
    f->samples[f->index] = new_sample;
    f->sum += new_sample;

    f->index = (f->index + 1) % FILTER_WINDOW;

