#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define FILTER_WINDOW_SIZE 8
#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   1023

#define ACTUATOR_ON_THRESHOLD   700
#define ACTUATOR_OFF_THRESHOLD  650

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    bool sensor_fault;
    uint16_t raw_value;
    uint16_t filtered_value;
} EdgeSystemState;

/* Initialize moving average filter */
static void filter_init(MovingAverageFilter *filter) {
    filter->sum = 0;
    filter->index = 0;
    filter->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        filter->buffer[i] = 0;
    }
}

/* Add a sample and return filtered result */
static uint16_t filter_update(MovingAverageFilter *filter, uint16_t sample) {
    if (filter->count < FILTER_WINDOW_SIZE) {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    } else {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;

    return (uint16_t)(filter->sum / filter->count);
}

/* Validate sensor reading */
static bool sensor_is_valid(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* Simulated actuator control */
static void actuator_set(bool on) {
    if (on) {
        printf("Actuator: ON\n");
    } else {
        printf("Actuator: OFF\n");
    }
}

/* Update actuator state with hysteresis */
static void actuator_update(EdgeSystemState *state) {
    if (state->sensor_fault) {
        if (state->actuator_on) {
            state->actuator_on = false;
            actuator_set(false);
        }
        return;
    }

    if (!state->actuator_on && state->filtered_value >= ACTUATOR_ON_THRESHOLD) {
        state->actuator_on = true;
        actuator_set(true);
    } else if (state->actuator_on && state->filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        state->actuator_on = false;
        actuator_set(false);
    }
}

/* Process one sensor sample */
static void edge_system_process(EdgeSystemState *state,
                                MovingAverageFilter *filter,
                                uint16_t sensor_sample) {
    state->raw_value = sensor_sample;

    if (!sensor_is_valid(sensor_sample)) {
        state->sensor_fault = true;
        printf("Sensor fault: invalid reading %u\n", sensor_sample);
        actuator_update(state);
        return;
    }

    state->sensor_fault = false;
    state->filtered_value = filter_update(filter, sensor_sample);

    printf("Raw: %u, Filtered: %u\n", state->raw_value, state->filtered_value);

    actuator_update(state);
}

int main(void) {
    MovingAverageFilter filter;
    EdgeSystemState state = {0};

    filter_init(&filter);

    /* Simulated sensor stream */
    uint16_t samples[] = {
        500, 520, 540, 560, 710, 730, 720, 710,
        690, 670, 640, 620, 1100, 600, 580, 750
    };

    size_t sample_count = sizeof(samples) / sizeof(samples[0]);

    for (size_t i = 0; i < sample_count; i++) {
        edge_system_process(&state, &filter, samples[i]);
    }

    return 0;
}
