#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define SENSOR_COUNT 3
#define FILTER_WINDOW 4

#define SENSOR_MIN 0
#define SENSOR_MAX 1023

#define TEMP_ON_THRESHOLD   700
#define TEMP_OFF_THRESHOLD  650

#define PRESSURE_ON_THRESHOLD  800
#define PRESSURE_OFF_THRESHOLD 750

typedef struct {
    uint16_t samples[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool valid;
} SensorData;

typedef struct {
    bool cooling_fan;
    bool pressure_valve;
    bool alarm;
} ActuatorState;

static MovingAverageFilter filters[SENSOR_COUNT];
static SensorData sensors[SENSOR_COUNT];
static ActuatorState actuators;

enum {
    SENSOR_TEMP = 0,
    SENSOR_PRESSURE = 1,
    SENSOR_HUMIDITY = 2
};

static uint16_t clamp_sensor_value(int32_t value) {
    if (value < SENSOR_MIN) return SENSOR_MIN;
    if (value > SENSOR_MAX) return SENSOR_MAX;
    return (uint16_t)value;
}

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t new_sample) {
    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

static bool validate_sensor_reading(int32_t raw) {
    return (raw >= SENSOR_MIN && raw <= SENSOR_MAX);
}

/* Replace these with hardware-specific sensor reads */
static int32_t read_sensor_hw(uint8_t sensor_id) {
    static uint16_t demo_values[SENSOR_COUNT] = {680, 770, 500};

    switch (sensor_id) {
        case SENSOR_TEMP:
            demo_values[0] += 8;
            return demo_values[0];
        case SENSOR_PRESSURE:
            demo_values[1] += 5;
            return demo_values[1];
        case SENSOR_HUMIDITY:
            return demo_values[2];
        default:
            return -1;
    }
}

/* Replace these with GPIO/PWM/driver calls */
static void apply_actuators(const ActuatorState *state) {
    printf("Fan=%d Valve=%d Alarm=%d\n",
           state->cooling_fan,
           state->pressure_valve,
           state->alarm);
}

static void process_sensors(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        int32_t raw = read_sensor_hw(i);
        sensors[i].valid = validate_sensor_reading(raw);

        if (!sensors[i].valid) {
            sensors[i].raw = 0;
            sensors[i].filtered = 0;
            continue;
        }

        sensors[i].raw = clamp_sensor_value(raw);
        sensors[i].filtered = filter_update(&filters[i], sensors[i].raw);
    }
}

static void update_actuators(void) {
    uint16_t temp = sensors[SENSOR_TEMP].filtered;
    uint16_t pressure = sensors[SENSOR_PRESSURE].filtered;

    if (sensors[SENSOR_TEMP].valid) {
        if (!actuators.cooling_fan && temp >= TEMP_ON_THRESHOLD) {
            actuators.cooling_fan = true;
        } else if (actuators.cooling_fan && temp <= TEMP_OFF_THRESHOLD) {
            actuators.cooling_fan = false;
        }
    } else {
        actuators.cooling_fan = false;
        actuators.alarm = true;
    }

    if (sensors[SENSOR_PRESSURE].valid) {
        if (!actuators.pressure_valve && pressure >= PRESSURE_ON_THRESHOLD) {
            actuators.pressure_valve = true;
        } else if (actuators.pressure_valve && pressure <= PRESSURE_OFF_THRESHOLD) {
            actuators.pressure_valve = false;
        }
    } else {
        actuators.pressure_valve = false;
        actuators.alarm = true;
    }

    if (sensors[SENSOR_TEMP].valid && sensors[SENSOR_PRESSURE].valid) {
        actuators.alarm = false;
    }
}

static void system_init(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        filter_init(&filters[i]);
        sensors[i].raw = 0;
        sensors[i].filtered = 0;
        sensors[i].valid = false;
    }

    actuators.cooling_fan = false;
    actuators.pressure_valve = false;
    actuators.alarm = false;
}

static void system_step(void) {
