    update_actuators();
    apply_actuators(&actuators);

    printf("Temp raw=%u filt=%u valid=%d | Pressure raw=%u filt=%u valid=%d | Humidity raw=%u filt=%u valid=%d\n",
           sensors[SENSOR_TEMP].raw, sensors[SENSOR_TEMP].filtered, sensors[SENSOR_TEMP].valid,
           sensors[SENSOR_PRESSURE].raw, sensors[SENSOR_PRESSURE].filtered, sensors[SENSOR_PRESSURE].valid,
           sensors[SENSOR_HUMIDITY].raw, sensors[SENSOR_HUMIDITY].filtered, sensors[SENSOR_HUMIDITY].valid);
}

int main(void) {
    system_init();

    for (int i = 0; i < 10; i++) {
        system_step();
    }

    return 0;
}
