## C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define FILTER_WINDOW_SIZE 8
#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   1023

#define ACTUATOR_ON_THRESHOLD   700
#define ACTUATOR_OFF_THRESHOLD  650

#define SENSOR_FAULT_LIMIT 5

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    uint8_t sensor_fault_count;
    bool sensor_fault;
} SystemState;

/* ---------------- Filter ---------------- */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    return (uint16_t)(f->sum / f->count);
}

/* ---------------- Sensor ---------------- */

static bool sensor_read(uint16_t *value) {
    /* Stub: replace with ADC/I2C/SPI sensor read */
    static uint16_t simulated = 600;
    simulated += 15;
    if (simulated > 800) {
        simulated = 620;
    }

    *value = simulated;
    return true;
}

static bool sensor_validate(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* ---------------- Actuator ---------------- */

static void actuator_set(bool on) {
    /* Stub: replace with GPIO/PWM write */
    if (on) {
        printf("Actuator ON\n");
    } else {
        printf("Actuator OFF\n");
    }
}

/* ---------------- Control Logic ---------------- */

static void system_init(SystemState *state, MovingAverageFilter *filter) {
    state->actuator_on = false;
    state->sensor_fault_count = 0;
    state->sensor_fault = false;
    filter_init(filter);
    actuator_set(false);
}

static void process_sensor_and_control(SystemState *state, MovingAverageFilter *filter) {
    uint16_t raw_value;
    bool read_ok = sensor_read(&raw_value);

    if (!read_ok || !sensor_validate(raw_value)) {
        if (state->sensor_fault_count < 255) {
            state->sensor_fault_count++;
        }

        if (state->sensor_fault_count >= SENSOR_FAULT_LIMIT) {
            state->sensor_fault = true;
            state->actuator_on = false;
            actuator_set(false);
        }

        return;
    }

    state->sensor_fault_count = 0;
    state->sensor_fault = false;

    uint16_t filtered_value = filter_update(filter, raw_value);

    if (!state->actuator_on && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        state->actuator_on = true;
        actuator_set(true);
    } else if (state->actuator_on && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        state->actuator_on = false;
        actuator_set(false);
    }

    printf("Raw: %u, Filtered: %u, Fault: %s\n",
           raw_value,
           filtered_value,
           state->sensor_fault ? "YES" : "NO");
}

/* ---------------- Main Loop ---------------- */

int main(void) {
    SystemState state;
    MovingAverageFilter filter;

    system_init(&state, &filter);

    for (int i = 0; i < 50; i++) {
        process_sensor_and_control(&state, &filter);

        /* Replace with RTOS delay or timer-based scheduling */
        /* e.g., sleep_ms(100); */
    }

    return 0;
}
