## Single-file C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - sensor filtering
 * - actuator management
 * - fixed-size ring buffer
 * - no dynamic allocation
 */

/* =========================
 * Configuration
 * ========================= */
#define SAMPLE_BUFFER_SIZE 32

/* Thresholds in arbitrary sensor units */
#define SENSOR_LOW_THRESHOLD   300
#define SENSOR_HIGH_THRESHOLD  700

/* EMA filter coefficient:
 * filtered = filtered + ((raw - filtered) >> EMA_SHIFT)
 * Larger shift => smoother, slower response
 */
#define EMA_SHIFT 3   /* alpha = 1/8 */

/* Actuator cooldown / debounce in ticks */
#define ACTUATOR_MIN_HOLD_TICKS 5

/* =========================
 * Types
 * ========================= */

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} actuator_state_t;

typedef enum {
    EVENT_NONE = 0,
    EVENT_LOW,
    EVENT_NORMAL,
    EVENT_HIGH
} system_event_t;

typedef struct {
    uint16_t data[SAMPLE_BUFFER_SIZE];
    uint8_t head;
    uint8_t count;
} sample_buffer_t;

typedef struct {
    uint16_t raw_value;
    uint16_t filtered_value;
    bool initialized;
} sensor_filter_t;

typedef struct {
    actuator_state_t fan;
    actuator_state_t heater;
    uint16_t hold_ticks;
} actuator_controller_t;

typedef struct {
    sensor_filter_t sensor;
    sample_buffer_t history;
    actuator_controller_t actuators;
    system_event_t last_event;
    uint32_t tick;
} edge_system_t;

/* =========================
 * Ring buffer
 * ========================= */

static void sample_buffer_init(sample_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
    for (uint8_t i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
        buf->data[i] = 0;
    }
}

static void sample_buffer_push(sample_buffer_t *buf, uint16_t value) {
    buf->data[buf->head] = value;
    buf->head = (uint8_t)((buf->head + 1) % SAMPLE_BUFFER_SIZE);
    if (buf->count < SAMPLE_BUFFER_SIZE) {
        buf->count++;
    }
}

/* Optional helper: get latest sample */
static uint16_t sample_buffer_latest(const sample_buffer_t *buf) {
    if (buf->count == 0) {
        return 0;
    }
    uint8_t idx = (buf->head == 0) ? (SAMPLE_BUFFER_SIZE - 1) : (buf->head - 1);
    return buf->data[idx];
}

/* =========================
 * Sensor filter
 * ========================= */

static void sensor_filter_init(sensor_filter_t *filter) {
    filter->raw_value = 0;
    filter->filtered_value = 0;
    filter->initialized = false;
}

static uint16_t sensor_filter_update(sensor_filter_t *filter, uint16_t raw) {
    filter->raw_value = raw;

    if (!filter->initialized) {
        filter->filtered_value = raw;
        filter->initialized = true;
        return filter->filtered_value;
    }

    /* Integer EMA:
     * filtered += (raw - filtered) / 2^EMA_SHIFT
     */
    int32_t delta = (int32_t)raw - (int32_t)filter->filtered_value;
    filter->filtered_value = (uint16_t)((int32_t)filter->filtered_value + (delta >> EMA_SHIFT));

    return filter->filtered_value;
}

/* =========================
 * Actuator control
 * ========================= */

static void actuator_controller_init(actuator_controller_t *ctrl) {
    ctrl->fan = ACTUATOR_OFF;
    ctrl->heater = ACTUATOR_OFF;
    ctrl->hold_ticks = 0;
}

/* Hardware abstraction stubs */
static void hw_set_fan(actuator_state_t state) {
    /* Replace with GPIO/PWM/HAL call */
    printf("[HW] FAN    -> %s\n", state == ACTUATOR_ON ? "ON" : "OFF");
}

static void hw_set_heater(actuator_state_t state) {
    /* Replace with GPIO/PWM/HAL call */
    printf("[HW] HEATER -> %s\n", state == ACTUATOR_ON ? "ON" : "OFF");
}

static void actuator_apply(actuator_controller_t *ctrl,
                           actuator_state_t fan,
                           actuator_state_t heater) {
    if (ctrl->fan != fan) {
        ctrl->fan = fan;
        hw_set_fan(fan);
    }
    if (ctrl->heater != heater) {
        ctrl->heater = heater;
        hw_set_heater(heater);
    }
}

static void actuator_controller_update(actuator_controller_t *ctrl, system_event_t event) {
    if (ctrl->hold_ticks > 0) {
        ctrl->hold_ticks--;
        return;
    }

    switch (event) {
        case EVENT_HIGH:
            actuator_apply(ctrl, ACTUATOR_ON, ACTUATOR_OFF);
            ctrl->hold_ticks = ACTUATOR_MIN_HOLD_TICKS;
            break;

        case EVENT_LOW:
            actuator_apply(ctrl, ACTUATOR_OFF, ACTUATOR_ON);
            ctrl->hold_ticks = ACTUATOR_MIN_HOLD_TICKS;
            break;

        case EVENT_NORMAL:
            actuator_apply(ctrl, ACTUATOR_OFF, ACTUATOR_OFF);
            ctrl->hold_ticks = ACTUATOR_MIN_HOLD_TICKS;
            break;

        case EVENT_NONE:
        default:
            break;
    }
}

/* =========================
 * Event detection
 * ========================= */

static system_event_t detect_event(uint16_t filtered_value) {
    if (filtered_value > SENSOR_HIGH_THRESHOLD) {
        return EVENT_HIGH;
    }
    if (filtered_value < SENSOR_LOW_THRESHOLD) {
        return EVENT_LOW;
    }
    return EVENT_NORMAL;
}

/* =========================
 * System
 * ========================= */

static void edge_system_init(edge_system_t *sys) {
    sensor_filter_init(&sys->sensor);
    sample_buffer_init(&sys->history);
    actuator_controller_init(&sys->actuators);
    sys->last_event = EVENT_NONE;
    sys->tick = 0;
}

/* Replace with actual ADC/I2C/SPI sensor read */
static uint16_t hw_read_sensor_mock(void) {
    static uint16_t mock_values[] = {
        250, 280, 310, 350, 500, 720, 760, 710,
        680, 640, 400, 290, 260, 320, 450, 800
    };
    static uint8_t idx = 0;

    uint16_t value = mock_values[idx];
    idx = (uint8_t)((idx + 1) % (sizeof(mock_values) / sizeof(mock_values[0])));
    return value;
}

static const char* event_to_string(system_event_t event) {
    switch (event) {
        case EVENT_LOW: return "LOW";
        case EVENT_NORMAL: return "NORMAL";
        case EVENT_HIGH: return "HIGH";
        case EVENT_NONE:
        default: return "NONE";
    }
}

static void edge_system_process_sample(edge_system_t *sys, uint16_t raw_sample) {
    uint16_t filtered = sensor_filter_update(&sys->sensor, raw_sample);
    sample_buffer_push(&sys->history, filtered);

    system_event_t event = detect_event(filtered);

    /* Only react/log on event change to reduce chatter */
    if (event != sys->last_event) {
        printf("[SYS] tick=%lu raw=%u filtered=%u event=%s\n",
               (unsigned long)sys->tick,
               raw_sample,
               filtered,
               event_to_string(event));

        actuator_controller_update(&sys->actuators, event);
        sys->last_event = event;
    }
}

static void edge_system_tick(edge_system_t *sys) {
    sys->tick++;

    uint16_t raw = hw_read_sensor_mock();
    edge_system_process_sample(sys, raw);
}

/* =========================
 * Demo main
 * ========================= */

int main(void) {
    edge_system_t system;
    edge_system_init(&system);

    for (int i = 0; i < 40; i++) {
        edge_system_tick(&system);
    }

    printf("[SYS] latest filtered sample = %u\n", sample_buffer_latest(&system.history));
    return 0;
}
```

