#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define SENSOR_COUNT        2
#define FILTER_WINDOW       4
#define SENSOR_MIN          0
#define SENSOR_MAX          1023

#define TEMP_SENSOR_ID      0
#define HUM_SENSOR_ID       1

#define TEMP_ON_THRESHOLD   700
#define TEMP_OFF_THRESHOLD  650

#define HUM_ON_THRESHOLD    300
#define HUM_OFF_THRESHOLD   350

typedef struct {
    uint16_t samples[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool cooling_fan_on;
    bool humidifier_on;
} ActuatorState;

static MovingAverageFilter filters[SENSOR_COUNT];
static ActuatorState actuators;

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t new_sample) {
    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

static uint16_t clamp_sensor_value(int32_t value) {
    if (value < SENSOR_MIN) return SENSOR_MIN;
    if (value > SENSOR_MAX) return SENSOR_MAX;
    return (uint16_t)value;
}

/* Replace with hardware-specific sensor read */
static uint16_t read_sensor(uint8_t sensor_id) {
    static uint16_t mock_temp = 680;
    static uint16_t mock_hum = 320;

    if (sensor_id == TEMP_SENSOR_ID) {
        mock_temp += 8;
        if (mock_temp > 730) mock_temp = 640;
        return mock_temp;
    } else {
        mock_hum -= 6;
        if (mock_hum < 280) mock_hum = 360;
        return mock_hum;
    }
}

/* Replace with hardware-specific actuator writes */
static void set_cooling_fan(bool on) {
    actuators.cooling_fan_on = on;
    printf("Cooling fan: %s\n", on ? "ON" : "OFF");
}

static void set_humidifier(bool on) {
    actuators.humidifier_on = on;
    printf("Humidifier: %s\n", on ? "ON" : "OFF");
}

static void process_temperature(uint16_t filtered_value) {
    if (!actuators.cooling_fan_on && filtered_value >= TEMP_ON_THRESHOLD) {
        set_cooling_fan(true);
    } else if (actuators.cooling_fan_on && filtered_value <= TEMP_OFF_THRESHOLD) {
        set_cooling_fan(false);
    }
}

static void process_humidity(uint16_t filtered_value) {
    if (!actuators.humidifier_on && filtered_value <= HUM_ON_THRESHOLD) {
        set_humidifier(true);
    } else if (actuators.humidifier_on && filtered_value >= HUM_OFF_THRESHOLD) {
        set_humidifier(false);
    }
}

static void system_init(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        filter_init(&filters[i]);
    }

    actuators.cooling_fan_on = false;
    actuators.humidifier_on = false;
}

static void system_step(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        uint16_t raw = read_sensor(i);
        uint16_t clamped = clamp_sensor_value(raw);
        uint16_t filtered = filter_update(&filters[i], clamped);

        printf("Sensor %u raw=%u filtered=%u\n", i, raw, filtered);

        switch (i) {
            case TEMP_SENSOR_ID:
                process_temperature(filtered);
                break;
            case HUM_SENSOR_ID:
                process_humidity(filtered);
                break;
            default:
                break;
        }
    }
}

int main(void) {
    system_init();

    for (int tick = 0; tick < 20; tick++) {
        printf("---- Tick %d ----\n", tick);
        system_step();
    }

    return 0;
}
```

