static void filter_init(SensorFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->filtered = 0;
    f->valid = false;

    for (i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static bool sensor_value_valid(uint16_t raw) {
    return (raw >= SENSOR_MIN_VALID && raw <= SENSOR_MAX_VALID);
}

static void filter_update(SensorFilter *f, uint16_t raw) {
    if (!sensor_value_valid(raw)) {
        f->valid = false;
        return;
    }

    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = raw;
        f->sum += raw;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = raw;
        f->sum += raw;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    f->filtered = (uint16_t)(f->sum / f->count);
    f->valid = true;
}

