    /* Alarm control based on vibration with hysteresis */
    if (g_sensors[SENSOR_VIBRATION].valid) {
        uint16_t vib = g_sensors[SENSOR_VIBRATION].filtered;

        if (vib >= VIB_HIGH_THRESHOLD) {
