```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define FILTER_WINDOW_SIZE 8
#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   1023

#define ACTUATOR_ON_THRESHOLD   700
#define ACTUATOR_OFF_THRESHOLD  650

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    bool sensor_fault;
    uint16_t last_raw;
    uint16_t last_filtered;
} EdgeSystemState;

/* ---------------- Filter ---------------- */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;
    return (uint16_t)(f->sum / f->count);
}

/* ---------------- Sensor ---------------- */

static bool sensor_read(uint16_t *value) {
    static uint16_t simulated_data[] = {
        620, 640, 710, 730, 720, 690, 660, 640, 800, 810
    };
    static uint8_t pos = 0;

    if (pos >= sizeof(simulated_data) / sizeof(simulated_data[0])) {
        pos = 0;
    }

    *value = simulated_data[pos++];
    return true;
}

static bool sensor_validate(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* ---------------- Actuator ---------------- */

static void actuator_set(bool on) {
    if (on) {
        printf("Actuator: ON\n");
    } else {
        printf("Actuator: OFF\n");
    }
}

/* ---------------- Control Logic ---------------- */

static void edge_system_init(EdgeSystemState *state, MovingAverageFilter *filter) {
    state->actuator_on = false;
    state->sensor_fault = false;
    state->last_raw = 0;
    state->last_filtered = 0;
    filter_init(filter);
}

static void edge_system_step(EdgeSystemState *state, MovingAverageFilter *filter) {
    uint16_t raw_value;

    if (!sensor_read(&raw_value)) {
        state->sensor_fault = true;
        actuator_set(false);
        state->actuator_on = false;
        return;
    }

    state->last_raw = raw_value;

    if (!sensor_validate(raw_value)) {
        state->sensor_fault = true;
        actuator_set(false);
        state->actuator_on = false;
        return;
    }

    state->sensor_fault = false;
    state->last_filtered = filter_update(filter, raw_value);

    if (!state->actuator_on && state->last_filtered >= ACTUATOR_ON_THRESHOLD) {
        state->actuator_on = true;
        actuator_set(true);
    } else if (state->actuator_on && state->last_filtered <= ACTUATOR_OFF_THRESHOLD) {
        state->actuator_on = false;
        actuator_set(false);
    }

    printf("Raw: %u, Filtered: %u, Fault: %s\n",
           state->last_raw,
           state->last_filtered,
           state->sensor_fault ? "YES" : "NO");
}

/* ---------------- Main ---------------- */

int main(void) {
    EdgeSystemState state;
    MovingAverageFilter filter;

    edge_system_init(&state, &filter);

    for (int i = 0; i < 20; i++) {
        edge_system_step(&state, &filter);
    }

    return 0;
}
