#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define NUM_SENSORS        4
#define NUM_ACTUATORS      4
#define FILTER_WINDOW      4

typedef struct {
    int16_t samples[FILTER_WINDOW];
    uint8_t index;
    int32_t sum;
    bool initialized;
} MovingAverageFilter;

typedef struct {
    int16_t raw_value;
    int16_t filtered_value;
    bool valid;
    MovingAverageFilter filter;
} Sensor;

typedef struct {
    bool state;
    int16_t on_threshold;
    int16_t off_threshold;
} Actuator;

typedef struct {
    Sensor sensors[NUM_SENSORS];
    Actuator actuators[NUM_ACTUATORS];
} EdgeSystem;

static void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->sum = 0;
    f->initialized = false;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    if (!f->initialized) {
        for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
            f->samples[i] = sample;
        }
        f->sum = sample * FILTER_WINDOW;
        f->initialized = true;
        return sample;
    }

    f->sum -= f->samples[f->index];
    f->samples[f->index] = sample;
    f->sum += sample;
    f->index = (f->index + 1) % FILTER_WINDOW;

    return (int16_t)(f->sum / FILTER_WINDOW);
}

static void sensor_init(Sensor *s) {
    s->raw_value = 0;
    s->filtered_value = 0;
    s->valid = false;
    filter_init(&s->filter);
}

static void actuator_init(Actuator *a, int16_t on_th, int16_t off_th) {
    a->state = false;
    a->on_threshold = on_th;
    a->off_threshold = off_th;
}

static void edge_system_init(EdgeSystem *sys) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        sensor_init(&sys->sensors[i]);
    }

    for (uint8_t i = 0; i < NUM_ACTUATORS; i++) {
        actuator_init(&sys->actuators[i], 70, 60);
    }
}

/* Replace with hardware-specific sensor read */
static bool read_sensor_hw(uint8_t sensor_id, int16_t *value) {
    static int16_t demo_values[NUM_SENSORS] = {65, 72, 58, 80};

    if (sensor_id >= NUM_SENSORS || value == NULL) {
        return false;
    }

    *value = demo_values[sensor_id];
    demo_values[sensor_id] += (sensor_id % 2 == 0) ? 1 : -1;
    return true;
}

/* Replace with hardware-specific actuator write */
static void write_actuator_hw(uint8_t actuator_id, bool state) {
    printf("Actuator %u -> %s\n", actuator_id, state ? "ON" : "OFF");
}

static void update_sensor(Sensor *s, uint8_t sensor_id) {
    int16_t raw;
    if (read_sensor_hw(sensor_id, &raw)) {
        s->raw_value = raw;
        s->filtered_value = filter_update(&s->filter, raw);
        s->valid = true;
    } else {
        s->valid = false;
    }
}

static void update_actuator(Actuator *a, int16_t sensor_value, bool sensor_valid, uint8_t actuator_id) {
    if (!sensor_valid) {
        a->state = false;
        write_actuator_hw(actuator_id, a->state);
        return;
    }

    if (!a->state && sensor_value >= a->on_threshold) {
        a->state = true;
        write_actuator_hw(actuator_id, a->state);
    } else if (a->state && sensor_value <= a->off_threshold) {
        a->state = false;
        write_actuator_hw(actuator_id, a->state);
    }
}

static void edge_system_step(EdgeSystem *sys) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        update_sensor(&sys->sensors[i], i);
    }

    for (uint8_t i = 0; i < NUM_ACTUATORS; i++) {
        update_actuator(
            &sys->actuators[i],
            sys->sensors[i].filtered_value,
            sys->sensors[i].valid,
            i
        );
    }
}

int main(void) {
    EdgeSystem sys;
    edge_system_init(&sys);

    for (int cycle = 0; cycle < 10; cycle++) {
