## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */
#define NUM_SENSORS         2
#define FILTER_WINDOW       8
#define SENSOR_MIN_VALID    0
#define SENSOR_MAX_VALID    1023

#define ACTUATOR_OFF        0
#define ACTUATOR_ON         1

/* Thresholds with hysteresis */
#define TEMP_ON_THRESHOLD   700
#define TEMP_OFF_THRESHOLD  650

#define HUM_ON_THRESHOLD    300
#define HUM_OFF_THRESHOLD   350

/* =========================
 * Types
 * ========================= */
typedef struct {
    uint16_t buffer[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool valid;
    MovingAverageFilter filter;
} SensorChannel;

typedef struct {
    uint8_t state;
} Actuator;

/* =========================
 * Global system state
 * ========================= */
static SensorChannel sensors[NUM_SENSORS];
static Actuator cooling_fan;
static Actuator humidifier;

/* =========================
 * Hardware abstraction layer
 * Replace these with platform-specific code
 * ========================= */
static uint16_t hal_read_sensor(uint8_t sensor_id) {
    /* Stub sensor values for demonstration */
    static uint16_t demo_values[NUM_SENSORS] = {680, 320};

    /* Simulate small variation */
    demo_values[sensor_id] += (sensor_id == 0) ? 3 : -2;
    return demo_values[sensor_id];
}

static void hal_set_actuator(uint8_t actuator_id, uint8_t state) {
    /* Replace with GPIO/PWM/etc. */
    printf("Actuator %u -> %s\n", actuator_id, state ? "ON" : "OFF");
}

static void hal_log(const char *msg) {
    printf("%s\n", msg);
}

/* =========================
 * Filter functions
 * ========================= */
static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

/* =========================
 * Sensor handling
 * ========================= */
static bool sensor_is_valid(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

static void sensor_init(SensorChannel *ch) {
    ch->raw = 0;
    ch->filtered = 0;
    ch->valid = false;
    filter_init(&ch->filter);
}

static void sensor_update(SensorChannel *ch, uint8_t sensor_id) {
    uint16_t sample = hal_read_sensor(sensor_id);
    ch->raw = sample;

    if (!sensor_is_valid(sample)) {
        ch->valid = false;
        return;
    }

    ch->valid = true;
    ch->filtered = filter_update(&ch->filter, sample);
}

/* =========================
 * Actuator control
 * ========================= */
static void actuator_init(Actuator *a) {
    a->state = ACTUATOR_OFF;
}

static void actuator_set(Actuator *a, uint8_t actuator_id, uint8_t new_state) {
    if (a->state != new_state) {
        a->state = new_state;
        hal_set_actuator(actuator_id, new_state);
    }
}

static void control_cooling_fan(const SensorChannel *temp_sensor) {
    if (!temp_sensor->valid) {
        actuator_set(&cooling_fan, 0, ACTUATOR_OFF);
        hal_log("Temperature sensor invalid, fan forced OFF");
        return;
    }

    if (cooling_fan.state == ACTUATOR_OFF &&
        temp_sensor->filtered >= TEMP_ON_THRESHOLD) {
        actuator_set(&cooling_fan, 0, ACTUATOR_ON);
    } else if (cooling_fan.state == ACTUATOR_ON &&
               temp_sensor->filtered <= TEMP_OFF_THRESHOLD) {
        actuator_set(&cooling_fan, 0, ACTUATOR_OFF);
    }
}

static void control_humidifier(const SensorChannel *hum_sensor) {
    if (!hum_sensor->valid) {
        actuator_set(&humidifier, 1, ACTUATOR_OFF);
        hal_log("Humidity sensor invalid, humidifier forced OFF");
        return;
    }

    if (humidifier.state == ACTUATOR_OFF &&
        hum_sensor->filtered <= HUM_ON_THRESHOLD) {
        actuator_set(&humidifier, 1, ACTUATOR_ON);
    } else if (humidifier.state == ACTUATOR_ON &&
               hum_sensor->filtered >= HUM_OFF_THRESHOLD) {
        actuator_set(&humidifier, 1, ACTUATOR_OFF);
    }
}

/* =========================
 * System lifecycle
 * ========================= */
static void system_init(void) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        sensor_init(&sensors[i]);
    }

    actuator_init(&cooling_fan);
    actuator_init(&humidifier);

    hal_log("System initialized");
}

static void system_step(void) {
    /* Sensor 0 = temperature, Sensor 1 = humidity */
    sensor_update(&sensors[0], 0);
    sensor_update(&sensors[1], 1);

    control_cooling_fan(&sensors[0]);
    control_humidifier(&sensors[1]);

    printf("Temp raw=%u filtered=%u valid=%d | Hum raw=%u filtered=%u valid=%d\n",
           sensors[0].raw, sensors[0].filtered, sensors[0].valid,
           sensors[1].raw, sensors[1].filtered, sensors[1].valid);
}

int main(void) {
    system_init();

    /* In real firmware, this would run on a timer or scheduler */
    for (int i = 0; i < 20; i++) {
        system_step();
    }

    return 0;
}
