#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - Reads sensor samples
 * - Filters with moving average
 * - Controls actuators with hysteresis
 * - No dynamic memory
 * - Integer math only
 */

#define NUM_SENSORS        3
#define FILTER_WINDOW      8
#define NUM_ACTUATORS      2

/* Example thresholds for actuator control */
#define TEMP_ON_THRESHOLD      700
#define TEMP_OFF_THRESHOLD     650

#define PRESS_ON_THRESHOLD     500
#define PRESS_OFF_THRESHOLD    450

typedef struct {
    int16_t buffer[FILTER_WINDOW];
    int32_t sum;
    uint8_t index;
    bool filled;
} MovingAverageFilter;

typedef struct {
    int16_t raw;
    int16_t filtered;
    MovingAverageFilter filter;
} SensorChannel;

typedef struct {
    bool state;
} Actuator;

/* Global system state */
static SensorChannel sensors[NUM_SENSORS];
static Actuator actuators[NUM_ACTUATORS];

/* ---------- Filter functions ---------- */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->filled = false;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = sample;
    f->sum += sample;

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
        f->filled = true;
    }

    uint8_t divisor = f->filled ? FILTER_WINDOW : f->index;
    if (divisor == 0) {
        return sample;
    }

    return (int16_t)(f->sum / divisor);
}

/* ---------- Sensor interface ---------- */
/* Replace these with actual ADC/I2C/SPI reads */

static int16_t read_sensor_hw(uint8_t sensor_id) {
    /* Demo data source */
    static int16_t demo_values[NUM_SENSORS] = {600, 430, 200};

    /* Simulate changing values */
    demo_values[0] += 5;   /* temperature-like */
    demo_values[1] += 3;   /* pressure-like */
    demo_values[2] += 1;   /* unused/extra */

    return demo_values[sensor_id];
}

/* ---------- Actuator interface ---------- */
/* Replace with GPIO/PWM/relay control */

static void actuator_write_hw(uint8_t actuator_id, bool on) {
    printf("Actuator %u -> %s\n", actuator_id, on ? "ON" : "OFF");
}

static void actuator_set(uint8_t actuator_id, bool on) {
    if (actuators[actuator_id].state != on) {
        actuators[actuator_id].state = on;
        actuator_write_hw(actuator_id, on);
    }
}

/* ---------- Control logic ---------- */

static void process_control_logic(void) {
    /* Example:
     * sensor 0 controls actuator 0 using temp thresholds
     * sensor 1 controls actuator 1 using pressure thresholds
     */

    int16_t temp = sensors[0].filtered;
    int16_t pressure = sensors[1].filtered;

    /* Hysteresis control for actuator 0 */
    if (!actuators[0].state && temp >= TEMP_ON_THRESHOLD) {
        actuator_set(0, true);
    } else if (actuators[0].state && temp <= TEMP_OFF_THRESHOLD) {
        actuator_set(0, false);
    }

    /* Hysteresis control for actuator 1 */
    if (!actuators[1].state && pressure >= PRESS_ON_THRESHOLD) {
        actuator_set(1, true);
    } else if (actuators[1].state && pressure <= PRESS_OFF_THRESHOLD) {
        actuator_set(1, false);
    }
}

/* ---------- System lifecycle ---------- */

static void system_init(void) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        sensors[i].raw = 0;
        sensors[i].filtered = 0;
        filter_init(&sensors[i].filter);
    }

    for (uint8_t i = 0; i < NUM_ACTUATORS; i++) {
        actuators[i].state = false;
    }
}

static void system_step(void) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        sensors[i].raw = read_sensor_hw(i);
        sensors[i].filtered = filter_update(&sensors[i].filter, sensors[i].raw);
    }

    process_control_logic();
}

/* ---------- Demo main loop ---------- */

int main(void) {
    system_init();

    for (int i = 0; i < 40; i++) {
        system_step();

        printf("Sensors: ");
        for (uint8_t s = 0; s < NUM_SENSORS; s++) {
            printf("[raw=%d filt=%d] ", sensors[s].raw, sensors[s].filtered);
        }
        printf("\n");
    }

    return 0;
}
