## Example C Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - Reads sensor samples
 * - Filters with moving average
 * - Controls actuators with hysteresis
 * - No dynamic memory
 */

#define SENSOR_COUNT        2
#define ACTUATOR_COUNT      2
#define FILTER_WINDOW       8

#define SENSOR_MIN_VALID    0
#define SENSOR_MAX_VALID    1000

typedef struct {
    int16_t buffer[FILTER_WINDOW];
    int32_t sum;
    uint8_t index;
    uint8_t count;
    bool initialized;
} MovingAverageFilter;

typedef struct {
    int16_t raw_value;
    int16_t filtered_value;
    bool valid;
    MovingAverageFilter filter;
} Sensor;

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} ActuatorState;

typedef struct {
    ActuatorState state;
    int16_t on_threshold;
    int16_t off_threshold;
} Actuator;

typedef struct {
    Sensor sensors[SENSOR_COUNT];
    Actuator actuators[ACTUATOR_COUNT];
} EdgeSystem;

/* ---------------- Filter ---------------- */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->initialized = true;

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    if (!f->initialized) {
        filter_init(f);
    }

    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;

    return (int16_t)(f->sum / f->count);
}

/* ---------------- Sensor ---------------- */

static void sensor_init(Sensor *s) {
    s->raw_value = 0;
    s->filtered_value = 0;
    s->valid = false;
    filter_init(&s->filter);
}

static bool sensor_validate(int16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

static void sensor_update(Sensor *s, int16_t new_value) {
    s->raw_value = new_value;
    s->valid = sensor_validate(new_value);

    if (s->valid) {
        s->filtered_value = filter_update(&s->filter, new_value);
    }
}

/* ---------------- Actuator ---------------- */

static void actuator_init(Actuator *a, int16_t on_threshold, int16_t off_threshold) {
    a->state = ACTUATOR_OFF;
    a->on_threshold = on_threshold;
    a->off_threshold = off_threshold;
}

/*
 * Hysteresis:
 * - Turn ON when value >= on_threshold
 * - Turn OFF when value <= off_threshold
 * Requires on_threshold > off_threshold
 */
static void actuator_update(Actuator *a, int16_t filtered_value, bool sensor_valid) {
    if (!sensor_valid) {
        /* Fail-safe behavior: turn actuator off on invalid sensor */
        a->state = ACTUATOR_OFF;
        return;
    }

    switch (a->state) {
        case ACTUATOR_OFF:
            if (filtered_value >= a->on_threshold) {
                a->state = ACTUATOR_ON;
            }
            break;

        case ACTUATOR_ON:
            if (filtered_value <= a->off_threshold) {
                a->state = ACTUATOR_OFF;
            }
            break;

        default:
            a->state = ACTUATOR_OFF;
            break;
    }
}

/* ---------------- System ---------------- */

static void edge_system_init(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensor_init(&sys->sensors[i]);
    }

    /* Example thresholds */
    actuator_init(&sys->actuators[0], 700, 600);
    actuator_init(&sys->actuators[1], 400, 300);
}

static void edge_system_process(EdgeSystem *sys, const int16_t sensor_inputs[SENSOR_COUNT]) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensor_update(&sys->sensors[i], sensor_inputs[i]);
    }

    /*
     * Example mapping:
     * actuator 0 controlled by sensor 0
     * actuator 1 controlled by sensor 1
     */
    actuator_update(&sys->actuators[0],
                    sys->sensors[0].filtered_value,
                    sys->sensors[0].valid);

    actuator_update(&sys->actuators[1],
                    sys->sensors[1].filtered_value,
                    sys->sensors[1].valid);
}

/* ---------------- Hardware abstraction stubs ---------------- */

static int16_t read_sensor_hw(uint8_t sensor_id) {
    /* Replace with ADC/I2C/SPI/GPIO read */
    static int16_t demo_values[SENSOR_COUNT] = {650, 250};

    /* Simple demo variation */
    demo_values[sensor_id] += (sensor_id == 0) ? 15 : 25;
    if (demo_values[sensor_id] > 900) {
        demo_values[sensor_id] = (sensor_id == 0) ? 500 : 200;
    }

    return demo_values[sensor_id];
}

static void write_actuator_hw(uint8_t actuator_id, ActuatorState state) {
    /* Replace with GPIO/PWM/relay control */
    printf("Actuator %u -> %s\n", actuator_id, state == ACTUATOR_ON ? "ON" : "OFF");
}

static void publish_status(const EdgeSystem *sys) {
    /* Replace with UART/MQTT/CAN/logging as needed */
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        printf("Sensor %u: raw=%d filtered=%d valid=%d\n",
               i,
               sys->sensors[i].raw_value,
               sys->sensors[i].filtered_value,
               sys->sensors[i].valid);
    }

    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        printf("Actuator %u state=%s\n",
               i,
               sys->actuators[i].state == ACTUATOR_ON ? "ON" : "OFF");
    }
}

/* ---------------- Main loop ---------------- */

int main(void) {
    EdgeSystem sys;
    edge_system_init(&sys);

    for (int cycle = 0; cycle < 20; cycle++) {
        int16_t inputs[SENSOR_COUNT];

        for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
            inputs[i] = read_sensor_hw(i);
        }

        edge_system_process(&sys, inputs);

        for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
            write_actuator_hw(i, sys.actuators[i].state);
        }

        publish_status(&sys);
        printf("----\n");
    }

    return 0;
}
