#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define FILTER_WINDOW_SIZE 8
#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   1023

#define ACTUATOR_ON_THRESHOLD   700
#define ACTUATOR_OFF_THRESHOLD  650

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    uint16_t last_raw;
    uint16_t last_filtered;
    bool sensor_fault;
} EdgeSystemState;

/* Initialize filter */
void filter_init(MovingAverageFilter *filter) {
    filter->sum = 0;
    filter->index = 0;
    filter->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        filter->buffer[i] = 0;
    }
}

/* Add sample and return filtered value */
uint16_t filter_update(MovingAverageFilter *filter, uint16_t sample) {
    if (filter->count < FILTER_WINDOW_SIZE) {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    } else {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;
    return (uint16_t)(filter->sum / filter->count);
}

/* Validate sensor reading */
bool sensor_is_valid(uint16_t sample) {
    return (sample >= SENSOR_MIN_VALID && sample <= SENSOR_MAX_VALID);
}

/* Update actuator using hysteresis */
void actuator_update(EdgeSystemState *state, uint16_t filtered_value) {
    if (!state->actuator_on && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        state->actuator_on = true;
    } else if (state->actuator_on && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        state->actuator_on = false;
    }
}

/* Main edge processing step */
void edge_process_sample(EdgeSystemState *state,
                         MovingAverageFilter *filter,
                         uint16_t raw_sample) {
    state->last_raw = raw_sample;

    if (!sensor_is_valid(raw_sample)) {
        state->sensor_fault = true;
        return;
    }

    state->sensor_fault = false;
    state->last_filtered = filter_update(filter, raw_sample);
    actuator_update(state, state->last_filtered);
}

/* Simulated actuator output */
void actuator_apply(bool on) {
    if (on) {
        printf("Actuator: ON\n");
    } else {
        printf("Actuator: OFF\n");
    }
}

/* Simulated sensor input stream */
uint16_t simulated_sensor_read(size_t step) {
    static const uint16_t samples[] = {
        620, 640, 660, 710, 720, 690, 680, 640, 630, 750, 760, 640
    };
    return samples[step % (sizeof(samples) / sizeof(samples[0]))];
}

int main(void) {
    MovingAverageFilter filter;
    EdgeSystemState state = {0};

    filter_init(&filter);

    for (size_t i = 0; i < 12; i++) {
        uint16_t sample = simulated_sensor_read(i);
        edge_process_sample(&state, &filter, sample);

        if (state.sensor_fault) {
            printf("Sensor fault detected. Raw=%u\n", state.last_raw);
            continue;
        }

        printf("Raw=%u Filtered=%u\n", state.last_raw, state.last_filtered);
        actuator_apply(state.actuator_on);
    }

    return 0;
}
