#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */
#define SENSOR_COUNT            2
#define FILTER_WINDOW           4
#define ACTUATOR_COUNT          2

#define SENSOR_MIN_VALID        0
#define SENSOR_MAX_VALID        1023

#define TEMP_THRESHOLD_HIGH     700
#define TEMP_THRESHOLD_LOW      650

#define PRESSURE_THRESHOLD_HIGH 800
#define PRESSURE_THRESHOLD_LOW  750

/* =========================
 * Types
 * ========================= */
typedef struct {
    uint16_t samples[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
    uint16_t filtered;
    bool initialized;
} MovingAverageFilter;

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool valid;
} SensorData;

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} ActuatorState;

typedef struct {
    ActuatorState state;
    bool fault;
} Actuator;

typedef struct {
    SensorData sensors[SENSOR_COUNT];
    MovingAverageFilter filters[SENSOR_COUNT];
    Actuator actuators[ACTUATOR_COUNT];
} EdgeSystem;

/* =========================
 * Mock hardware interface
 * Replace with platform-specific code
 * ========================= */
static uint16_t sensor_read_raw(uint8_t sensor_id) {
    static uint16_t mock_values[SENSOR_COUNT] = {680, 770};

    /* Simulate changing values */
    if (sensor_id == 0) {
        mock_values[0] += 5;
        if (mock_values[0] > 720) mock_values[0] = 640;
    } else if (sensor_id == 1) {
        mock_values[1] += 3;
        if (mock_values[1] > 830) mock_values[1] = 740;
    }

    return mock_values[sensor_id];
}

static void actuator_write(uint8_t actuator_id, ActuatorState state) {
    /* Replace with GPIO/PWM/etc. */
    printf("Actuator %u -> %s\n", actuator_id, state == ACTUATOR_ON ? "ON" : "OFF");
}

/* =========================
 * Filter
 * ========================= */
static void filter_init(MovingAverageFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->filtered = 0;
    f->initialized = true;
    for (i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (!f->initialized) {
        filter_init(f);
    }

    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
    }

    f->filtered = (uint16_t)(f->sum / f->count);
    return f->filtered;
}

/* =========================
 * Validation
 * ========================= */
static bool sensor_is_valid(uint16_t raw) {
    return (raw >= SENSOR_MIN_VALID && raw <= SENSOR_MAX_VALID);
}

/* =========================
 * Control logic
 * actuator 0 responds to sensor 0
 * actuator 1 responds to sensor 1
 * Hysteresis prevents chatter
 * ========================= */
static ActuatorState controller_decide(
    uint8_t sensor_id,
    uint16_t filtered,
    ActuatorState current_state
) {
    if (sensor_id == 0) {
        if (current_state == ACTUATOR_OFF && filtered >= TEMP_THRESHOLD_HIGH) {
            return ACTUATOR_ON;
        }
        if (current_state == ACTUATOR_ON && filtered <= TEMP_THRESHOLD_LOW) {
            return ACTUATOR_OFF;
        }
    } else if (sensor_id == 1) {
        if (current_state == ACTUATOR_OFF && filtered >= PRESSURE_THRESHOLD_HIGH) {
            return ACTUATOR_ON;
        }
        if (current_state == ACTUATOR_ON && filtered <= PRESSURE_THRESHOLD_LOW) {
            return ACTUATOR_OFF;
        }
    }

    return current_state;
}

/* =========================
 * System functions
 * ========================= */
static void edge_system_init(EdgeSystem *sys) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sys->sensors[i].raw = 0;
        sys->sensors[i].filtered = 0;
        sys->sensors[i].valid = false;
        filter_init(&sys->filters[i]);
    }

    for (i = 0; i < ACTUATOR_COUNT; i++) {
        sys->actuators[i].state = ACTUATOR_OFF;
        sys->actuators[i].fault = false;
        actuator_write(i, ACTUATOR_OFF);
    }
}

static void edge_system_sample(EdgeSystem *sys) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        uint16_t raw = sensor_read_raw(i);
        sys->sensors[i].raw = raw;
        sys->sensors[i].valid = sensor_is_valid(raw);

        if (sys->sensors[i].valid) {
            sys->sensors[i].filtered = filter_update(&sys->filters[i], raw);
        }
    }
}

static void edge_system_control(EdgeSystem *sys) {
    uint8_t i;

    for (i = 0; i < ACTUATOR_COUNT && i < SENSOR_COUNT; i++) {
        if (!sys->sensors[i].valid) {
            sys->actuators[i].fault = true;
            sys->actuators[i].state = ACTUATOR_OFF;
            actuator_write(i, ACTUATOR_OFF);
            continue;
        }

        sys->actuators[i].fault = false;

        ActuatorState next = controller_decide(
            i,
            sys->sensors[i].filtered,
            sys->actuators[i].state
        );

        if (next != sys->actuators[i].state) {
            sys->actuators[i].state = next;
            actuator_write(i, next);
        }
    }
}

static void edge_system_log(const EdgeSystem *sys) {
    uint8_t i;
    for (i = 0; i < SENSOR_COUNT; i++) {
        printf("Sensor %u raw=%u filtered=%u valid=%u\n",
               i,
               sys->sensors[i].raw,
               sys->sensors[i].filtered,
               sys->sensors[i].valid ? 1 : 0);
    }

    for (i = 0; i < ACTUATOR_COUNT; i++) {
        printf("Actuator %u state=%u fault=%u\n",
               i,
               sys->actuators[i].state,
               sys->actuators[i].fault ? 1 : 0);
    }
    printf("----\n");
}

static void edge_system_step(EdgeSystem *sys) {
    edge_system_sample(sys);
    edge_system_control(sys);
    edge_system_log(sys);
}

/* =========================
 * Main
 * ========================= */
int main(void) {
    EdgeSystem sys;
    uint8_t tick;

    edge_system_init(&sys);

    for (tick = 0; tick < 20; tick++) {
        edge_system_step(&sys);

        /* Replace with RTOS delay or timer-driven scheduling */
        /* sleep_ms(100); */
    }

    return 0;
}
