#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - fixed-size moving average filter
 * - threshold-based actuator control with hysteresis
 * - no dynamic memory
 * - simple fault detection
 */

#define FILTER_WINDOW_SIZE 8
#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   1023

#define ACTUATOR_ON_THRESHOLD   700
#define ACTUATOR_OFF_THRESHOLD  650

#define SENSOR_FAULT_LIMIT 5

typedef struct {
    int32_t buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} MovingAverageFilter;

typedef struct {
    bool state;
} Actuator;

typedef struct {
    uint16_t raw_value;
    uint16_t filtered_value;
    bool valid;
} SensorData;

typedef struct {
    MovingAverageFilter filter;
    Actuator actuator;
    uint8_t consecutive_faults;
} EdgeSystem;

/* ---------------- Filter ---------------- */

static void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    return (uint16_t)(f->sum / f->count);
}

/* ---------------- Sensor ---------------- */

/*
 * Replace this with actual ADC/I2C/SPI sensor read logic.
 * Returns true if a sample was read successfully.
 */
static bool sensor_read(uint16_t *out_value) {
    static uint16_t simulated_data[] = {
        620, 640, 660, 690, 710, 730, 720, 705,
        680, 660, 640, 630, 800, 810, 820, 500,
        490, 480, 900, 910
    };
    static uint8_t idx = 0;

    if (idx >= sizeof(simulated_data) / sizeof(simulated_data[0])) {
        idx = 0;
    }

    *out_value = simulated_data[idx++];
    return true;
}

static bool sensor_validate(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* ---------------- Actuator ---------------- */

static void actuator_init(Actuator *a) {
    a->state = false;
}

static void actuator_set(Actuator *a, bool on) {
    if (a->state != on) {
        a->state = on;

        /* Replace with GPIO write */
        if (on) {
            printf("Actuator: ON\n");
        } else {
            printf("Actuator: OFF\n");
        }
    }
}

/* ---------------- Control Logic ---------------- */

static void control_update(EdgeSystem *sys, uint16_t filtered_value) {
    if (!sys->actuator.state && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        actuator_set(&sys->actuator, true);
    } else if (sys->actuator.state && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        actuator_set(&sys->actuator, false);
    }
}

/* ---------------- System ---------------- */

static void edge_system_init(EdgeSystem *sys) {
    filter_init(&sys->filter);
    actuator_init(&sys->actuator);
    sys->consecutive_faults = 0;
}

static void edge_system_process(EdgeSystem *sys) {
    SensorData data = {0};

    if (!sensor_read(&data.raw_value)) {
        sys->consecutive_faults++;
        if (sys->consecutive_faults >= SENSOR_FAULT_LIMIT) {
            actuator_set(&sys->actuator, false);
            printf("Fault: sensor read failure\n");
        }
        return;
    }

    if (!sensor_validate(data.raw_value)) {
        sys->consecutive_faults++;
        if (sys->consecutive_faults >= SENSOR_FAULT_LIMIT) {
            actuator_set(&sys->actuator, false);
            printf("Fault: invalid sensor value %u\n", data.raw_value);
        }
        return;
    }

    sys->consecutive_faults = 0;
    data.valid = true;
    data.filtered_value = filter_update(&sys->filter, data.raw_value);

    printf("Raw=%u Filtered=%u\n", data.raw_value, data.filtered_value);

    control_update(sys, data.filtered_value);
}

/* ---------------- Main Loop ---------------- */

int main(void) {
    EdgeSystem system;
    edge_system_init(&system);

    /*
     * In a real embedded target:
     * - call this from a timer tick
     * - or run inside a cooperative scheduler
     */
    for (int i = 0; i < 40; i++) {
        edge_system_process(&system);

        /* Replace with low-power sleep or RTOS delay */
        /* e.g., sleep_ms(100); */
    }

    return 0;
}
