import time
import random
from collections import deque


class MovingAverageFilter:
    def __init__(self, window_size=5):
        self.window = deque(maxlen=window_size)

    def update(self, value):
        self.window.append(value)
        return sum(self.window) / len(self.window)


class SensorManager:
    def read_temperature(self):
        # Simulated noisy temperature sensor
        return 25.0 + random.uniform(-2.0, 2.0)

    def read_humidity(self):
        # Simulated noisy humidity sensor
        return 50.0 + random.uniform(-5.0, 5.0)

    def read_all(self):
        temp = self.read_temperature()
        hum = self.read_humidity()

        # Minimal validation
        if not (-40 <= temp <= 125):
            temp = None
        if not (0 <= hum <= 100):
            hum = None

        return {
            "temperature": temp,
            "humidity": hum,
        }


class ActuatorManager:
    def __init__(self):
        self.fan_on = False
        self.pump_on = False

    def set_fan(self, state):
        if self.fan_on != state:
            self.fan_on = state
            print(f"[ACTUATOR] Fan {'ON' if state else 'OFF'}")

    def set_pump(self, state):
        if self.pump_on != state:
            self.pump_on = state
            print(f"[ACTUATOR] Pump {'ON' if state else 'OFF'}")


class EdgeController:
    def __init__(self):
        self.sensors = SensorManager()
        self.actuators = ActuatorManager()

        self.temp_filter = MovingAverageFilter(window_size=5)
        self.hum_filter = MovingAverageFilter(window_size=5)

        # Thresholds
        self.temp_high = 26.0
        self.temp_low = 25.0   # hysteresis
        self.hum_low = 45.0
        self.hum_high = 50.0   # hysteresis

    def process(self):
        raw = self.sensors.read_all()

        temp = raw["temperature"]
        hum = raw["humidity"]

        filtered_temp = None
        filtered_hum = None

        if temp is not None:
            filtered_temp = self.temp_filter.update(temp)

        if hum is not None:
            filtered_hum = self.hum_filter.update(hum)

        print(
            f"[DATA] raw_temp={temp:.2f if temp is not None else 'None'} "
            f"raw_hum={hum:.2f if hum is not None else 'None'}"
        )
        print(
            f"[FILTERED] temp={filtered_temp:.2f if filtered_temp is not None else 'None'} "
            f"hum={filtered_hum:.2f if filtered_hum is not None else 'None'}"
        )

        self.control(filtered_temp, filtered_hum)

    def control(self, temp, hum):
        # Fan control with hysteresis
        if temp is not None:
            if temp > self.temp_high:
                self.actuators.set_fan(True)
            elif temp < self.temp_low:
