## Important Fix

The two `print()` lines above use invalid inline formatting inside f-strings. Here is the **corrected working version**:

```python
import time
import random
from collections import deque


class MovingAverageFilter:
    def __init__(self, window_size=5):
        self.window = deque(maxlen=window_size)

    def update(self, value):
        self.window.append(value)
        return sum(self.window) / len(self.window)


class SensorManager:
    def read_temperature(self):
        return 25.0 + random.uniform(-2.0, 2.0)

    def read_humidity(self):
        return 50.0 + random.uniform(-5.0, 5.0)

    def read_all(self):
        temp = self.read_temperature()
        hum = self.read_humidity()

        if not (-40 <= temp <= 125):
            temp = None
        if not (0 <= hum <= 100):
            hum = None

        return {"temperature": temp, "humidity": hum}


class ActuatorManager:
    def __init__(self):
        self.fan_on = False
        self.pump_on = False

    def set_fan(self, state):
        if self.fan_on != state:
            self.fan_on = state
            print(f"[ACTUATOR] Fan {'ON' if state else 'OFF'}")

    def set_pump(self, state):
        if self.pump_on != state:
            self.pump_on = state
            print(f"[ACTUATOR] Pump {'ON' if state else 'OFF'}")


class EdgeController:
    def __init__(self):
        self.sensors = SensorManager()
        self.actuators = ActuatorManager()

        self.temp_filter = MovingAverageFilter(window_size=5)
        self.hum_filter = MovingAverageFilter(window_size=5)

        self.temp_high = 26.0
        self.temp_low = 25.0
        self.hum_low = 45.0
        self.hum_high = 50.0

    def fmt(self, value):
        return "None" if value is None else f"{value:.2f}"

    def process(self):
        raw = self.sensors.read_all()

        temp = raw["temperature"]
        hum = raw["humidity"]

        filtered_temp = self.temp_filter.update(temp) if temp is not None else None
        filtered_hum = self.hum_filter.update(hum) if hum is not None else None

        print(f"[DATA] raw_temp={self.fmt(temp)} raw_hum={self.fmt(hum)}")
        print(f"[FILTERED] temp={self.fmt(filtered_temp)} hum={self.fmt(filtered_hum)}")

        self.control(filtered_temp, filtered_hum)

    def control(self, temp, hum):
        if temp is not None:
            if temp > self.temp_high:
                self.actuators.set_fan(True)
            elif temp < self.temp_low:
                self.actuators.set_fan(False)

        if hum is not None:
            if hum < self.hum_low:
                self.actuators.set_pump(True)
            elif hum > self.hum_high:
                self.actuators.set_pump(False)

    def run(self, interval_sec=1.0, iterations=30):
        for _ in range(iterations):
            self.process()
            time.sleep(interval_sec)


if __name__ == "__main__":
    controller = EdgeController()
    controller.run()
```

