## Minimal C Implementation

```c
#include <stdint.h>
#include <stdio.h>

/* ===== Configuration ===== */
#define FILTER_WINDOW 4
#define SENSOR_THRESHOLD_ON  700
#define SENSOR_THRESHOLD_OFF 650

/* ===== Types ===== */
typedef struct {
    uint16_t buffer[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    uint8_t actuator_on;
} SystemState;

/* ===== Mock hardware layer =====
   Replace these with MCU-specific ADC/GPIO code.
*/
static uint16_t mock_sensor_read(void) {
    static uint16_t samples[] = {
        600, 720, 710, 690, 730, 740, 680, 640, 620, 710
    };
    static uint8_t i = 0;
    uint16_t value = samples[i];
    i = (i + 1) % (sizeof(samples) / sizeof(samples[0]));
    return value;
}

static void actuator_set(uint8_t on) {
    printf("ACTUATOR: %s\n", on ? "ON" : "OFF");
}

/* ===== Filter ===== */
static void filter_init(MovingAverageFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

/* ===== Control logic ===== */
static void system_init(SystemState *s) {
    s->actuator_on = 0;
}

static void system_update(SystemState *s, uint16_t filtered_value) {
    if (!s->actuator_on && filtered_value >= SENSOR_THRESHOLD_ON) {
        s->actuator_on = 1;
        actuator_set(1);
    } else if (s->actuator_on && filtered_value <= SENSOR_THRESHOLD_OFF) {
        s->actuator_on = 0;
        actuator_set(0);
    }
}

/* ===== Main loop ===== */
int main(void) {
    MovingAverageFilter filter;
    SystemState system;
    uint8_t tick;

    filter_init(&filter);
    system_init(&system);

    for (tick = 0; tick < 20; tick++) {
        uint16_t raw = mock_sensor_read();
        uint16_t filtered = filter_update(&filter, raw);

        printf("RAW=%u FILTERED=%u STATE=%s\n",
               raw,
               filtered,
               system.actuator_on ? "ON" : "OFF");

        system_update(&system, filtered);
    }

    return 0;
}
```

