      entity.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.height;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.height;
            entity.vy = 0;
          }
        }
      }
