      // Enemies
      for (const enemy of enemies) {
        enemy.x += enemy.vx * dt;
        if (enemy.x <= enemy.minX) {
          enemy.x = enemy.minX;
          enemy.vx *= -1;
        }
        if (enemy.x + enemy.width >= enemy.maxX) {
          enemy.x = enemy.maxX - enemy.width;
          enemy.vx *= -1;
        }

        if (rectsIntersect(player, enemy)) {
          // Stomp enemy if falling onto it
          const playerBottom = player.y + player.height;
          const enemyTop = enemy.y;
          const falling = player.vy > 0;

          if (falling && playerBottom - player.vy * dt <= enemyTop + 8) {
            enemy.x = enemy.minX;
            enemy.vx *= -1;
            player.vy = -400;
          } else {
            resetPlayer();
          }
        }
      }

