        winMessageTimer = 2.0;
        resetGame();
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      // Animation timing
      player.animTime += dt;
      if (player.state === "idle") {
        player.animFrame = 0;
      } else if (player.state === "run") {
        const runFPS = 10;
        player.animFrame = 1 + Math.floor(player.animTime * runFPS) % 6;
      } else if (player.state === "jump") {
        player.animFrame = 7;
      }

      // Camera follow
      camera.x = player.x + player.width / 2 - camera.width / 2;
      camera.y = player.y + player.height / 2 - camera.height / 2;

      camera.x = clamp(camera.x, 0, world.width - camera.width);
      camera.y = clamp(camera.y, 0, world.height - camera.height);

      if (winMessageTimer > 0) {
        winMessageTimer -= dt;
      }
    }

