    function drawEnemies() {
      for (const e of enemies) {
        const x = e.x - camera.x;
        const y = e.y - camera.y;

        ctx.fillStyle = "#b22222";
        ctx.fillRect(x, y, e.width, e.height);

        ctx.fillStyle = "#fff";
        ctx.fillRect(x + 5, y + 7, 5, 5);
        ctx.fillRect(x + 18, y + 7, 5, 5);

        ctx.fillStyle = "#000";
        ctx.fillRect(x + 7, y + 9, 2, 2);
        ctx.fillRect(x + 20, y + 9, 2, 2);

        ctx.fillStyle = "#333";
        ctx.fillRect(x + 4, y + e.height - 4, e.width - 8, 4);
      }
    }

    function drawGoal() {
      const x = goal.x - camera.x;
      const y = goal.y - camera.y;

      ctx.fillStyle = "#8b5cf6";
      ctx.fillRect(x, y, 6, goal.height);

      ctx.fillStyle = "#c4b5fd";
      ctx.beginPath();
      ctx.moveTo(x + 6, y);
      ctx.lineTo(x + 30, y + 10);
      ctx.lineTo(x + 6, y + 20);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const frame = player.animFrame;
      const sx = frame * playerSheet.frameWidth;
      const sy = 0;
      const dx = Math.floor(player.x - camera.x);
      const dy = Math.floor(player.y - camera.y);

      ctx.save();

      if (player.facing === -1) {
        ctx.translate(dx + player.width, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(
          playerSheet.image,
          sx, sy, playerSheet.frameWidth, playerSheet.frameHeight,
          0, 0, player.width, player.height
        );
      } else {
        ctx.drawImage(
          playerSheet.image,
          sx, sy, playerSheet.frameWidth, playerSheet.frameHeight,
          dx, dy, player.width, player.height
        );
      }

      ctx.restore();
    }

    function drawHUD() {
      if (winMessageTimer > 0) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(canvas.width / 2 - 160, 40, 320, 50);

        ctx.fillStyle = "#fff";
        ctx.font = "24px Arial";
        ctx.textAlign = "center";
        ctx.fillText("You reached the goal!", canvas.width / 2, 73);
      }
    }

    function draw(time) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawPlatforms();
      drawCoins(time);
      drawEnemies();
      drawGoal();
      drawPlayer();
      drawHUD();
    }

    // -----------------------------
    // Game loop
    // -----------------------------
    function gameLoop(timestamp) {
      const dt = Math.min((timestamp - lastTime) / 1000, 1 / 30);
      lastTime = timestamp;

      update(dt);
      draw(timestamp);

      requestAnimationFrame(gameLoop);
    }

    resetGame();
    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
