Below is a minimal working 2D platformer in a single HTML file. It includes:

- Physics simulation:
  - gravity
  - horizontal movement
  - jumping
  - collision with platforms
- Simple sprite animation:
  - idle
  - run
  - jump
- Camera follow
- Basic level geometry

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
  </style>
</head>
<body>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.code] = true);
    window.addEventListener("keyup", e => keys[e.code] = false);

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_FORCE = -14;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 550, w: 500, h: 50 },
        { x: 600, y: 480, w: 180, h: 30 },
        { x: 850, y: 420, w: 180, h: 30 },
        { x: 1100, y: 360, w: 180, h: 30 },
        { x: 1400, y: 500, w: 300, h: 30 },
        { x: 1800, y: 430, w: 220, h: 30 },
        { x: 2100, y: 350, w: 200, h: 30 },
        { x: 0, y: 700, w: 2400, h: 100 } // floor
      ]
    };

    const player = {
      x: 100,
      y: 300,
      w: 40,
      h: 60,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    const camera = {
      x: 0,
      y: 0
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      // Input
      if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (keys["ArrowRight"] || keys["KeyD"]) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if ((keys["ArrowUp"] || keys["Space"] || keys["KeyW"]) && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
      }

      // Physics
      player.vy += GRAVITY;
      player.x += player.vx;
      player.y += player.vy;

      player.vx *= FRICTION;

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }

      // Platform collisions
      player.onGround = false;

      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          const prevX = player.x - player.vx;
          const prevY = player.y - player.vy;

          const wasAbove = prevY + player.h <= p.y;
          const wasBelow = prevY >= p.y + p.h;
          const wasLeft = prevX + player.w <= p.x;
          const wasRight = prevX >= p.x + p.w;

          if (wasAbove) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (wasBelow) {
            player.y = p.y + p.h;
            player.vy = 0;
          } else if (wasLeft) {
            player.x = p.x - player.w;
            player.vx = 0;
          } else if (wasRight) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

      // Fall reset
      if (player.y > world.height + 300) {
        player.x = 100;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += 0.16;
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b8c5a";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#3f6f3e";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawPlayer() {
      const px = player.x - camera.x;
      const py = player.y - camera.y;

      ctx.save();
      ctx.translate(px + player.w / 2, py + player.h / 2);
      ctx.scale(player.facing, 1);

      // Body
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(-player.w / 2, -player.h / 2, player.w, player.h);

      // Headband
      ctx.fillStyle = "#e74c3c";
      ctx.fillRect(-player.w / 2, -player.h / 2 + 8, player.w, 8);

      // Eye
      ctx.fillStyle = "#222";
      ctx.fillRect(6, -10, 5, 5);

      // Animated legs/arms
      const t = player.animTime;
      let swing = 0;

      if (player.state === "run") {
        swing = Math.sin(t * 10) * 8;
      } else if (player.state === "jump") {
        swing = 4;
      }

      ctx.strokeStyle = "#222";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      // Arms
      ctx.beginPath();
      ctx.moveTo(-10, -5);
      ctx.lineTo(-18, 10 + swing * 0.3);
      ctx.moveTo(10, -5);
      ctx.lineTo(18, 10 - swing * 0.3);
      ctx.stroke();

      // Legs
      ctx.beginPath();
      ctx.moveTo(-8, player.h / 2 - 4);
      ctx.lineTo(-10, player.h / 2 + 14 + swing);
      ctx.moveTo(8, player.h / 2 - 4);
      ctx.lineTo(10, player.h / 2 + 14 - swing);
      ctx.stroke();

      ctx.restore();
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#b8e6b8";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 80, 180, Math.PI, 0);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      for (const p of world.platforms) {
        drawPlatform(p);
      }

      drawPlayer();

      // UI
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, 10, 240, 70);
      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText("Move: A/D or ←/→", 20, 35);
      ctx.fillText("Jump: W / Space / ↑", 20, 58);
    }

    function loop() {
      updatePlayer();
      updateCamera();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
