        ctx.moveTo(8, player.h / 2 - 4);
        ctx.lineTo(8 - swing, player.h / 2 + 10);
      } else if (player.state === "jump") {
        ctx.moveTo(-8, player.h / 2 - 4);
        ctx.lineTo(-14, player.h / 2 + 6);
        ctx.moveTo(8, player.h / 2 - 4);
        ctx.lineTo(14, player.h / 2 + 6);
