        ctx.moveTo(-player.w / 2, -8);
        ctx.lineTo(-player.w / 2 - 4, 8);
        ctx.moveTo(player.w / 2, -8);
        ctx.lineTo(player.w / 2 + 4, 8);
      }
      ctx.stroke();

      ctx.restore();
    }

    function draw() {
      drawBackground();
      drawPlatforms();
      drawPlayer();
    }

    function loop() {
      updatePlayer();
      updateCamera();
      draw();
      requestAnimationFrame(loop);
    }

