    // World
    // ----------------------------
    const GRAVITY = 1800;
    const FRICTION = 0.82;
    const MOVE_ACCEL = 1800;
    const MAX_SPEED_X = 320;
    const JUMP_SPEED = 620;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 2400, h: 80 },   // ground
        { x: 220, y: 420, w: 140, h: 20 },
        { x: 430, y: 360, w: 140, h: 20 },
        { x: 650, y: 300, w: 140, h: 20 },
        { x: 900, y: 380, w: 180, h: 20 },
        { x: 1180, y: 320, w: 160, h: 20 },
        { x: 1450, y: 260, w: 160, h: 20 },
        { x: 1720, y: 340, w: 180, h: 20 },
        { x: 2000, y: 280, w: 140, h: 20 },
      ]
    };

    // ----------------------------
    // Generate a tiny sprite sheet in code
    // 4 frames: idle1, idle2, run1, run2
    // ----------------------------
    function createPlayerSpriteSheet() {
      const frameW = 32;
      const frameH = 32;
      const frames = 4;
      const sheet = document.createElement("canvas");
      sheet.width = frameW * frames;
      sheet.height = frameH;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, armOffset, eyeShift) {
        sctx.clearRect(offsetX, 0, frameW, frameH);

        // body
        sctx.fillStyle = "#ffcc66";
        sctx.fillRect(offsetX + 10, 8, 12, 12);

        // head
        sctx.fillStyle = "#f2b28c";
        sctx.fillRect(offsetX + 9, 2, 14, 10);

        // eyes
        sctx.fillStyle = "#222";
        sctx.fillRect(offsetX + 12 + eyeShift, 5, 2, 2);
        sctx.fillRect(offsetX + 18 + eyeShift, 5, 2, 2);

        // arms
        sctx.fillStyle = "#66aaff";
        sctx.fillRect(offsetX + 6, 10 + armOffset, 4, 10);
        sctx.fillRect(offsetX + 22, 10 - armOffset, 4, 10);

        // torso
        sctx.fillStyle = "#4d96ff";
        sctx.fillRect(offsetX + 10, 12, 12, 10);

        // legs
        sctx.fillStyle = "#2d5baf";
        sctx.fillRect(offsetX + 10, 22, 4, 8 + legOffset);
        sctx.fillRect(offsetX + 18, 22, 4, 8 - legOffset);
      }

      drawFrame(0, 0, 0, 0);   // idle 1
      drawFrame(32, 1, 0, 0);  // idle 2
      drawFrame(64, 2, 2, 0);  // run 1
      drawFrame(96, -2, -2, 1);// run 2

      return { image: sheet, frameW, frameH, frames };
    }

    const playerSprite = createPlayerSpriteSheet();

    // ----------------------------
    // Player
    // ----------------------------
    const player = {
      x: 80,
      y: 200,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    // ----------------------------
    // Camera
    // ----------------------------
    const camera = {
      x: 0,
      y: 0
    };

    // ----------------------------
    // Helpers
    // ----------------------------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    // ----------------------------
    // Physics + collision
    // ----------------------------
    function updatePlayer(dt) {
      // Horizontal input
      const left = isDown("arrowleft", "a");
      const right = isDown("arrowright", "d");
      const jump = isDown("arrowup", "w", " ");

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      // Jump
      if (jump && player.onGround && !player._jumpHeld) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }
      player._jumpHeld = jump;

      // Gravity
      player.vy += GRAVITY * dt;

      // Move X
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Move Y
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height) {
        // respawn if falling off
        player.x = 80;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      player.animTime += dt;
      const moving = Math.abs(player.vx) > 20;
      if (!player.onGround) {
        player.frame = 2; // use run frame as jump/fall
      } else if (moving) {
        player.frame = Math.floor(player.animTime * 10) % 2 ? 2 : 3;
      } else {
        player.frame = Math.floor(player.animTime * 3) % 2; // idle 0/1
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    // ----------------------------
    // Rendering
    // ----------------------------
    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#b7e3a1";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, 500, 180, Math.PI, 2 * Math.PI);
        ctx.fill();
      }

      ctx.fillStyle = "#8fd17f";
      for (let i = 0; i < 10; i++) {
        const x = i * 260 - (camera.x * 0.5 % 260);
        ctx.beginPath();
        ctx.arc(x, 530, 120, Math.PI, 2 * Math.PI);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(sx, sy, p.w, 8);

        // simple tile lines
        ctx.strokeStyle = "rgba(0,0,0,0.15)";
        for (let x = 0; x < p.w; x += 32) {
          ctx.beginPath();
          ctx.moveTo(sx + x, sy + 8);
          ctx.lineTo(sx + x, sy + p.h);
          ctx.stroke();
        }
      }
    }

    function drawPlayer() {
      const sx = player.frame * playerSprite.frameW;
      const dx = Math.round(player.x - camera.x);
      const dy = Math.round(player.y - camera.y);

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(
          playerSprite.image,
          sx, 0, playerSprite.frameW, playerSprite.frameH,
          0, 0, player.w, player.h
        );
      } else {
        ctx.drawImage(
          playerSprite.image,
          sx, 0, playerSprite.frameW, playerSprite.frameH,
          dx, dy, player.w, player.h
        );
      }
      ctx.restore();
    }

    function drawDebug() {
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 70, 220, 60);
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 45);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 25);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawDebug();
    }

    // ----------------------------
    // Game loop
    // ----------------------------
    let last = performance.now();

    function loop(now) {
      let dt = (now - last) / 1000;
      last = now;

      // avoid giant physics jumps on tab switch
      dt = Math.min(dt, 0.033);

      updatePlayer(dt);
      updateCamera();
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

