Below is a minimal working 2D platformer in a single HTML file using plain JavaScript and the Canvas API.

Features:
- Gravity and jumping
- Horizontal movement
- Simple platform collision
- Basic sprite animation using a generated spritesheet
- Camera follow
- Goal flag and respawn on falling

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #87ceeb;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #111;
      background: rgba(255,255,255,0.7);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud">Move: ← → or A D | Jump: Space / W / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });
    addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- Utility ---
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    // --- Generate a tiny sprite sheet dynamically ---
    function createPlayerSpriteSheet() {
      const sheet = document.createElement("canvas");
      sheet.width = 96;  // 3 frames * 32
      sheet.height = 32;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, armOffset, eyeX) {
        // transparent bg
        // body
        sctx.fillStyle = "#ffcc66";
        sctx.fillRect(offsetX + 10, 8, 12, 14);

        // head
        sctx.fillStyle = "#f2b37a";
        sctx.fillRect(offsetX + 9, 2, 14, 10);

        // eyes
        sctx.fillStyle = "#111";
        sctx.fillRect(offsetX + eyeX, 5, 2, 2);

        // arms
        sctx.fillStyle = "#cc8844";
        sctx.fillRect(offsetX + 7, 10 + armOffset, 3, 10);
        sctx.fillRect(offsetX + 22, 10 - armOffset, 3, 10);

        // legs
        sctx.fillStyle = "#4444aa";
        sctx.fillRect(offsetX + 11, 22, 4, 8 + legOffset);
        sctx.fillRect(offsetX + 17, 22, 4, 8 - legOffset);
      }

      drawFrame(0, 2, 1, 13);   // walk 1
      drawFrame(32, 0, 0, 14);  // idle
      drawFrame(64, -2, -1, 15);// walk 2

      return sheet;
    }

    const playerSheet = createPlayerSpriteSheet();

    // --- World ---
    const world = {
      width: 2400,
      height: 1200,
      gravity: 1800,
      platforms: [
        { x: 0, y: 500, w: 500, h: 40 },
        { x: 560, y: 450, w: 180, h: 30 },
        { x: 820, y: 390, w: 180, h: 30 },
        { x: 1080, y: 330, w: 180, h: 30 },
        { x: 1380, y: 420, w: 240, h: 30 },
        { x: 1700, y: 360, w: 220, h: 30 },
        { x: 1980, y: 300, w: 260, h: 30 },
        { x: 300, y: 380, w: 120, h: 20 },
        { x: 80, y: 300, w: 100, h: 20 },
      ],
      goal: { x: 2180, y: 220, w: 24, h: 80 }
    };

    // --- Player ---
    const spawn = { x: 80, y: 200 };

    const player = {
      x: spawn.x,
      y: spawn.y,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 320,
      jump: 700,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 1
    };

    let won = false;

    function resetPlayer() {
      player.x = spawn.x;
      player.y = spawn.y;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      won = false;
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Physics / Update ---
    let lastTime = performance.now();

    function update(dt) {
      if (won) return;

      // Input
      let move = 0;
      if (keys["arrowleft"] || keys["a"]) move -= 1;
      if (keys["arrowright"] || keys["d"]) move += 1;

      player.vx = move * player.speed;

      if (move !== 0) player.facing = move;

      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jump;
        player.onGround = false;
      }

      // Gravity
      player.vy += world.gravity * dt;
      player.vy = Math.min(player.vy, 1200);

      // Horizontal move
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Vertical move
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Fall reset
      if (player.y > world.height) {
        resetPlayer();
      }

      // Goal
      if (rectsOverlap(player, world.goal)) {
        won = true;
      }

      // Animation
      if (!player.onGround) {
        player.frame = 0;
      } else if (Math.abs(player.vx) > 1) {
        player.animTime += dt * 10;
        const walkFrames = [0, 1, 2, 1];
        player.frame = walkFrames[Math.floor(player.animTime) % walkFrames.length];
      } else {
        player.frame = 1;
        player.animTime = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    // --- Drawing ---
    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 320 - (camera.x * 0.2 % 320);
        ctx.beginPath();
        ctx.arc(x, 540, 180, Math.PI, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#7fcf6a";
      for (let i = 0; i < 10; i++) {
        const x = i * 260 - (camera.x * 0.4 % 260);
        ctx.beginPath();
        ctx.arc(x, 560, 140, Math.PI, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(x, y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(x, y, p.w, 8);

        // simple tile lines
        ctx.strokeStyle = "rgba(0,0,0,0.15)";
        for (let i = 0; i < p.w; i += 32) {
          ctx.beginPath();
          ctx.moveTo(x + i, y + 8);
          ctx.lineTo(x + i, y + p.h);
          ctx.stroke();
        }
      }
    }

    function drawGoal() {
      const g = world.goal;
      const x = g.x - camera.x;
      const y = g.y - camera.y;

      ctx.fillStyle = "#666";
      ctx.fillRect(x, y, 6, g.h);

      ctx.fillStyle = "#ff3b3b";
      ctx.beginPath();
      ctx.moveTo(x + 6, y);
      ctx.lineTo(x + 30, y + 10);
      ctx.lineTo(x + 6, y + 20);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const x = Math.round(player.x - camera.x);
      const y = Math.round(player.y - camera.y);

      ctx.save();
      ctx.translate(x + player.w / 2, y);

      if (player.facing < 0) {
        ctx.scale(-1, 1);
      }

      const sx = player.frame * 32;
      ctx.drawImage(
        playerSheet,
        sx, 0, 32, 32,
        -player.w / 2, 0, player.w, player.h
      );

      ctx.restore();
    }

    function drawUI() {
      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = "#fff";
        ctx.textAlign = "center";
        ctx.font = "bold 42px sans-serif";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2 - 10);

        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 30);
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawPlatforms();
      drawGoal();
      drawPlayer();
      drawUI();
    }

    function loop(now) {
      const dt = Math.min((now - lastTime) / 1000, 1 / 30);
      lastTime = now;

      update(dt);
      draw();

      requestAnimationFrame(loop);
    }

    resetPlayer();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
