      height: 1200,
      platforms: [
        { x: -200, y: 520, w: 900, h: 80 },
        { x: 760, y: 450, w: 180, h: 24 },
        { x: 980, y: 380, w: 180, h: 24 },
        { x: 1220, y: 320, w: 180, h: 24 },
        { x: 1480, y: 420, w: 220, h: 24 },
        { x: 1760, y: 500, w: 260, h: 24 },
        { x: 2100, y: 430, w: 220, h: 24 },
      ]
    };

    const player = {
      x: 120,
      y: 200,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 900,
      jump: 620,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function update(dt) {
      const left = keys['arrowleft'] || keys['a'];
      const right = keys['arrowright'] || keys['d'];
      const jumpPressed = keys[' '] || keys['w'] || keys['arrowup'];

      // Horizontal input
      if (left) {
        player.vx -= player.speed * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed * dt;
        player.facing = 1;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-260, Math.min(260, player.vx));

      // Jump
      if (jumpPressed && player.onGround) {
        player.vy = -player.jump;
        player.onGround = false;
      }

      // Gravity
      player.vy += world.gravity * dt;

      // Friction
      if (player.onGround) {
        player.vx *= world.friction;
      } else {
        player.vx *= world.airFriction;
      }

      // Move X
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Move Y
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if fallen
      if (player.y > world.height) {
        player.x = 120;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      player.animTime += dt;
      const moving = Math.abs(player.vx) > 20;

      if (!player.onGround) {
        player.frame = 0; // jump frame in row 1
      } else if (moving) {
        player.frame = Math.floor(player.animTime * 10) % 2 + 1; // frames 1,2
      } else {
        player.frame = 0; // idle
      }

      // Camera follow
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = '#9bd18b';
      for (let i = 0; i < 8; i++) {
        const x = i * 400 - (camera.x * 0.2 % 400);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 40, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = '#7fb069';
      for (let i = 0; i < 10; i++) {
        const x = i * 300 - (camera.x * 0.35 % 300);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 10, 120, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      // Ground/platforms
      for (const p of world.platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = '#6b4f3a';
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = '#7ec850';
        ctx.fillRect(sx, sy, p.w, 10);

        // simple pattern
        ctx.fillStyle = 'rgba(0,0,0,0.08)';
        for (let x = 0; x < p.w; x += 24) {
          ctx.fillRect(sx + x, sy + 10, 2, p.h - 10);
        }
      }
    }

    function drawPlayer() {
      const sx = player.x - camera.x;
      const sy = player.y - camera.y;

      const row = player.onGround ? 0 : 1;
      const frameX = player.frame * 32;
      const frameY = row * 32;

      ctx.save();
      ctx.translate(sx + player.w / 2, sy + player.h / 2);
      ctx.scale(player.facing, 1);

      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(
        spriteSheet,
        frameX, frameY, 32, 32,
        -player.w / 2, -player.h / 2, player.w, player.h
      );
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      update(dt);
      draw();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
