        ctx.scale(-1, 1);
        ctx.drawImage(
          playerSheet,
          player.frame * 32, 0, 32, 32,
          0, 0, player.w, player.h
        );
      } else {
        ctx.drawImage(
          playerSheet,
          player.frame * 32, 0, 32, 32,
          px, py, player.w, player.h
        );
      }
      ctx.restore();
    }

    function drawWinOverlay() {
      if (!won) return;
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

