      ctx.fillText(`Coins collected: ${player.coins}`, canvas.width / 2, canvas.height / 2 + 20);
      ctx.fillText("Press R to restart", canvas.width / 2, canvas.height / 2 + 60);
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawGoal();
      drawPlayer();
      drawWinOverlay();
    }

    function resetGame() {
      player.x = 80;
      player.y = 200;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      player.coins = 0;
      player.frame = 0;
      player.animTime = 0;
      won = false;
      for (const coin of world.coins) coin.collected = false;
      hud.textContent = "Coins: 0";
    }

    function loop() {
      update();
      requestAnimationFrame(loop);
    }

    resetGame();
    loop();
  </script>
