        }
      }

      // Vertical movement
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if fallen
      if (player.y > world.height) {
        player.x = 80;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (!player.onGround) {
        player.animFrame = 1;
      } else if (Math.abs(player.vx) > 1) {
        player.animTime += dt;
        if (player.animTime > 0.12) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 3;
        }
      } else {
        player.animFrame = 0;
        player.animTime = 0;
      }

      // Camera follows player
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // parallax hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.2 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 40, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#7fcf6a";
      for (let i = 0; i < 10; i++) {
        const x = i * 260 - (camera.x * 0.35 % 260);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 10, 120, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      // grid
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;
      for (let x = 0; x < world.width; x += 64) {
        ctx.beginPath();
        ctx.moveTo(x - camera.x, -camera.y);
        ctx.lineTo(x - camera.x, world.height - camera.y);
        ctx.stroke();
      }

      // platforms
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#5dbb63";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawPlayer() {
      const sx = player.animFrame * 32;
      const dx = Math.round(player.x - camera.x);
      const dy = Math.round(player.y - camera.y);

      ctx.save();

      if (player.facing < 0) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(playerSheet, sx, 0, 32, 32, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(playerSheet, sx, 0, 32, 32, dx, dy, player.w, player.h);
      }

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
