Save as `index.html` and open in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #87ceeb;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #111;
      background: rgba(255,255,255,0.7);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <canvas id="game"></canvas>
  <div class="hud" id="hud">Coins: 0</div>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const hud = document.getElementById("hud");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    // --- Generate a tiny sprite sheet in memory ---
    function createPlayerSpriteSheet() {
      const sheet = document.createElement("canvas");
      sheet.width = 96;   // 3 frames * 32
      sheet.height = 32;
      const sctx = sheet.getContext("2d");

      for (let i = 0; i < 3; i++) {
        const x = i * 32;

        // transparent bg
        sctx.clearRect(x, 0, 32, 32);

        // head
        sctx.fillStyle = "#ffd166";
        sctx.fillRect(x + 10, 4, 12, 10);

        // body
        sctx.fillStyle = "#ef476f";
        sctx.fillRect(x + 9, 14, 14, 10);

        // legs animate
        sctx.fillStyle = "#26547c";
        if (i === 0) {
          sctx.fillRect(x + 10, 24, 4, 8);
          sctx.fillRect(x + 18, 24, 4, 8);
        } else if (i === 1) {
          sctx.fillRect(x + 8, 24, 4, 8);
          sctx.fillRect(x + 20, 24, 4, 8);
        } else {
          sctx.fillRect(x + 12, 24, 4, 8);
          sctx.fillRect(x + 16, 24, 4, 8);
        }

        // arms animate
        sctx.fillStyle = "#06d6a0";
        if (i === 1) {
          sctx.fillRect(x + 4, 15, 5, 3);
          sctx.fillRect(x + 23, 18, 5, 3);
        } else if (i === 2) {
          sctx.fillRect(x + 4, 18, 5, 3);
          sctx.fillRect(x + 23, 15, 5, 3);
        } else {
          sctx.fillRect(x + 4, 16, 5, 3);
          sctx.fillRect(x + 23, 16, 5, 3);
        }
      }

      return sheet;
    }

    const playerSheet = createPlayerSpriteSheet();

    // --- World ---
    const gravity = 0.6;
    const friction = 0.8;
    const moveAccel = 0.8;
    const maxSpeed = 6;
    const jumpPower = -12;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 550, w: 500, h: 50 },
        { x: 580, y: 500, w: 180, h: 30 },
        { x: 820, y: 440, w: 180, h: 30 },
        { x: 1060, y: 380, w: 180, h: 30 },
        { x: 1320, y: 460, w: 220, h: 30 },
        { x: 1620, y: 520, w: 300, h: 30 },
        { x: 1980, y: 450, w: 220, h: 30 },
        { x: 2200, y: 380, w: 180, h: 30 },
        { x: 300, y: 300, w: 120, h: 20 },
        { x: 480, y: 240, w: 120, h: 20 }
      ],
      coins: [
        { x: 640, y: 460, r: 10, collected: false },
        { x: 880, y: 400, r: 10, collected: false },
        { x: 1120, y: 340, r: 10, collected: false },
        { x: 1400, y: 420, r: 10, collected: false },
        { x: 1700, y: 480, r: 10, collected: false },
        { x: 2060, y: 410, r: 10, collected: false },
        { x: 350, y: 260, r: 10, collected: false }
      ]
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0,
      coins: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= moveAccel;
        player.facing = -1;
      }
      if (right) {
        player.vx += moveAccel;
        player.facing = 1;
      }

      if (!left && !right) {
        player.vx *= friction;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      player.vx = Math.max(-maxSpeed, Math.min(maxSpeed, player.vx));

      if (jump && player.onGround) {
        player.vy = jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += gravity;
      if (player.vy > 20) player.vy = 20;

      // Horizontal move
      player.x += player.vx;

      // Keep in world horizontally
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;

      // Platform collision: landing only + head bump
      for (const p of world.platforms) {
        if (rectIntersect(player, p)) {
          const prevY = player.y - player.vy;

          // Falling onto platform
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting underside
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Fall reset
      if (player.y > world.height) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const cx = coin.x;
        const cy = coin.y;
        const nearestX = Math.max(player.x, Math.min(cx, player.x + player.w));
        const nearestY = Math.max(player.y, Math.min(cy, player.y + player.h));
        const dx = cx - nearestX;
        const dy = cy - nearestY;
        if (dx * dx + dy * dy < coin.r * coin.r) {
          coin.collected = true;
          player.coins++;
          hud.textContent = `Coins: ${player.coins}`;
        }
      }

      // Animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 0.2) {
        player.frameTimer++;
        if (player.frameTimer > 8) {
          player.frame = (player.frame + 1) % 3;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
        player.frameTimer = 0;
      }

      // Camera follow
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 40, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#7cc36d";
      for (let i = 0; i < 10; i++) {
        const x = i * 280 - (camera.x * 0.5 % 280);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 10, 140, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // platforms
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7fbf5b";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        ctx.fillStyle = "gold";
        ctx.beginPath();
        ctx.arc(coin.x, coin.y, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c99700";
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      // player
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        drawPlayerSprite(0, 0);
      } else {
        ctx.translate(player.x, player.y);
        drawPlayerSprite(0, 0);
      }
      ctx.restore();

      ctx.restore();
    }

    function drawPlayerSprite(x, y) {
      const frameWidth = 32;
      const frameHeight = 32;
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(
        playerSheet,
        player.frame * frameWidth, 0, frameWidth, frameHeight,
        x, y, player.w, player.h
      );
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
