      const frameH = 48;
      const sheet = document.createElement("canvas");
      sheet.width = frameW * 4;
      sheet.height = frameH;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, armOffset, bodyColor) {
        sctx.clearRect(offsetX, 0, frameW, frameH);

        // head
        sctx.fillStyle = "#ffd6a5";
        sctx.fillRect(offsetX + 10, 4, 12, 12);

        // body
        sctx.fillStyle = bodyColor;
        sctx.fillRect(offsetX + 9, 16, 14, 16);

