        sctx.fillStyle = "#2d3142";
        sctx.fillRect(offsetX + 10, 32, 4, 12 + legOffset);
        sctx.fillRect(offsetX + 18, 32, 4, 12 - legOffset);

        // eyes
        sctx.fillStyle = "#222";
        sctx.fillRect(offsetX + 13, 8, 2, 2);
        sctx.fillRect(offsetX + 17, 8, 2, 2);
      }

      drawFrame(0, 0, 0, "#e63946");
      drawFrame(32, 3, 2, "#f77f00");
      drawFrame(64, 0, 0, "#e63946");
      drawFrame(96, -3, -2, "#f77f00");

      return sheet;
    }

    const playerSheet = createPlayerSpriteSheet();

    function update() {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (!left && !right) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      player.vy += GRAVITY;

