      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

