      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      player.x = clamp(player.x, 0, WORLD_WIDTH - player.w);

      if (player.y > 1200) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      for (const coin of coins) {
        if (!coin.collected && circleRectOverlap(coin, player)) {
          coin.collected = true;
          player.score++;
        }
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.2;
      if (!player.onGround) {
        player.frame = 1;
      } else if (moving) {
        player.animTime += 0.2;
        player.frame = Math.floor(player.animTime) % 4;
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.x = clamp(camera.x, 0, WORLD_WIDTH - canvas.width);
      camera.y = 0;
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
