        ctx.arc(x, canvas.height - 80, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#6ab04c";
      for (let i = 0; i < 10; i++) {
        const x = i * 280 - (camera.x * 0.5 % 280);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 30, 140, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = "#6d4c41";
        ctx.fillRect(sx, sy, p.w, p.h);

