        if (coin.collected) continue;
        const x = coin.x - camera.x;
        const y = coin.y - camera.y;
        const pulse = 1 + Math.sin(performance.now() * 0.01 + coin.x) * 0.1;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(pulse, pulse);

        ctx.fillStyle = "gold";
        ctx.beginPath();
        ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#cc9a00";
        ctx.lineWidth = 3;
        ctx.stroke();

        ctx.restore();
      }
    }

    function drawPlayer() {
      const sx = player.x - camera.x;
      const sy = player.y - camera.y;
      const frameW = 32;
      const frameH = 48;
      const frameX = player.frame * frameW;

      ctx.save();
      ctx.translate(sx + player.w / 2, sy);
      ctx.scale(player.facing, 1);
      ctx.drawImage(
        playerSheet,
        frameX, 0, frameW, frameH,
        -player.w / 2, 0, player.w, player.h
      );
      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.4)";
      ctx.fillRect(10, 10, 140, 40);
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText("Coins: " + player.score, 20, 37);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawPlayer();
      drawHUD();
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
