Below is a minimal working 2D platformer in a single HTML file using plain JavaScript and the Canvas API.

Features:
- Gravity and jumping
- Horizontal movement
- Simple platform collisions
- Basic sprite animation using a generated sprite sheet
- Camera follow
- Minimal but playable

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud">Move: ← → / A D &nbsp; Jump: Space / W / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 1800;
    const FRICTION = 0.82;
    const MOVE_ACCEL = 1800;
    const MAX_SPEED_X = 280;
    const JUMP_VELOCITY = -620;
    const FIXED_DT = 1 / 60;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 600, h: 40 },
        { x: 700, y: 430, w: 180, h: 30 },
        { x: 950, y: 360, w: 180, h: 30 },
        { x: 1200, y: 300, w: 180, h: 30 },
        { x: 1500, y: 380, w: 220, h: 30 },
        { x: 1800, y: 460, w: 300, h: 40 },
        { x: 300, y: 380, w: 120, h: 24 },
        { x: 60, y: 300, w: 120, h: 24 },
        { x: 2100, y: 340, w: 180, h: 24 },
        { x: 0, y: 560, w: 2400, h: 80 }
      ]
    };

    function makeSpriteSheet() {
      const sheet = document.createElement("canvas");
      sheet.width = 96;
      sheet.height = 32;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, eyeX) {
        sctx.save();
        sctx.translate(offsetX, 0);

        // body
        sctx.fillStyle = "#ffcc4d";
        sctx.fillRect(10, 6, 12, 14);

        // head
        sctx.fillStyle = "#f5b041";
        sctx.fillRect(8, 0, 16, 10);

        // eye
        sctx.fillStyle = "#222";
        sctx.fillRect(eyeX, 3, 2, 2);

        // legs
        sctx.fillStyle = "#8e44ad";
        sctx.fillRect(11, 20, 4, 8 + legOffset);
        sctx.fillRect(17, 20, 4, 8 - legOffset);

        // arms
        sctx.fillStyle = "#e67e22";
        sctx.fillRect(7, 10, 3, 8);
        sctx.fillRect(22, 10, 3, 8);

        sctx.restore();
      }

      drawFrame(0, 2, 12);   // walk 1
      drawFrame(32, -2, 14); // walk 2
      drawFrame(64, 0, 13);  // idle

      return sheet;
    }

    const spriteSheet = makeSpriteSheet();

    const player = {
      x: 80,
      y: 200,
      w: 28,
      h: 28,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 2
    };

    const camera = { x: 0, y: 0 };

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function update(dt) {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      player.vy += GRAVITY * dt;

      // Horizontal move
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if fallen
      if (player.y > world.height) {
        player.x = 80;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 20) {
        player.animTime += dt * 10;
        player.frame = Math.floor(player.animTime) % 2;
      } else {
        player.frame = 2;
      }

      // Camera follow
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#b8e6b8";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.2 % 350);
        ctx.beginPath();
        ctx.arc(x, 500, 180, Math.PI, 2 * Math.PI);
        ctx.fill();
      }

      ctx.fillStyle = "#8fd19e";
      for (let i = 0; i < 10; i++) {
        const x = i * 260 - (camera.x * 0.35 % 260);
        ctx.beginPath();
        ctx.arc(x, 540, 140, Math.PI, 2 * Math.PI);
        ctx.fill();
      }
    }

    function drawWorld() {
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawPlayer() {
      const dx = Math.round(player.x - camera.x);
      const dy = Math.round(player.y - camera.y);

      ctx.save();
      ctx.translate(dx + player.w / 2, dy);
      ctx.scale(player.facing, 1);

      const sx = player.frame * 32;
      ctx.drawImage(
        spriteSheet,
        sx, 0, 32, 32,
        -player.w / 2 - 2, -2, 32, 32
      );

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();
    }

    let accumulator = 0;
    let lastTime = performance.now();

    function loop(now) {
      let delta = (now - lastTime) / 1000;
      lastTime = now;

      if (delta > 0.1) delta = 0.1;
      accumulator += delta;

      while (accumulator >= FIXED_DT) {
        update(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
