        if (pose === "idle1") {
          g.fillRect(x + 11, 22, 4, 8);
          g.fillRect(x + 17, 22, 4, 8);
        } else if (pose === "idle2") {
          g.fillRect(x + 11, 22, 4, 8);
          g.fillRect(x + 17, 21, 4, 9);
        } else if (pose === "run1") {
