        ctx.strokeStyle = "#fff3";
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      // goal flag
      const g = world.goal;
      const gx = g.x - camera.x;
      const gy = g.y - camera.y;

      ctx.fillStyle = "#6d4c41";
      ctx.fillRect(gx, gy, 6, g.h);
      ctx.fillStyle = player.won ? "#2ecc71" : "#e74c3c";
      ctx.beginPath();
      ctx.moveTo(gx + 6, gy);
      ctx.lineTo(gx + 34, gy + 12);
      ctx.lineTo(gx + 6, gy + 24);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const frames = playerSheet.animations[player.anim.state];
      const frame = frames[player.anim.frameIndex];
      const sx = frame * playerSheet.frameW;
      const sy = 0;
      const dx = Math.round(player.x - camera.x);
      const dy = Math.round(player.y - camera.y);

      ctx.save();

      if (player.facing === -1) {
        ctx.translate(dx + player.w / 2, 0);
        ctx.scale(-1, 1);
        ctx.translate(-(dx + player.w / 2), 0);
      }

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(dx + player.w / 2, dy + player.h + 4, 14, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.drawImage(
        playerSheet.image,
        sx, sy, playerSheet.frameW, playerSheet.frameH,
        dx, dy, player.w, player.h
      );

      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(12, 12, 180, 64);
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Coins: ${player.score}/${world.coins.length}`, 24, 38);
      ctx.font = "16px sans-serif";
      ctx.fillText(`Reach the flag`, 24, 62);

      if (player.won) {
        ctx.fillStyle = "rgba(0,0,0,0.55)";
        ctx.fillRect(WIDTH / 2 - 180, HEIGHT / 2 - 50, 360, 100);
        ctx.fillStyle = "#2ecc71";
        ctx.font = "32px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", WIDTH / 2, HEIGHT / 2 - 4);
        ctx.fillStyle = "white";
        ctx.font = "18px sans-serif";
        ctx.fillText("Refresh to play again", WIDTH / 2, HEIGHT / 2 + 28);
        ctx.textAlign = "left";
      }
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      if (!player.won) {
        updatePlayer(dt);
        updateAnimation(dt);
        updateCamera();
      }

      ctx.clearRect(0, 0, WIDTH, HEIGHT);
      drawBackground();
      drawWorld();
      drawPlayer();
      drawHUD();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
