```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .info {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="info">Move: ← → or A D | Jump: Space / W / ↑</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });
    window.addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_SPEED = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_FORCE = -14;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 1100, w: 2400, h: 100 },
        { x: 200, y: 980, w: 220, h: 20 },
        { x: 520, y: 900, w: 180, h: 20 },
        { x: 820, y: 820, w: 180, h: 20 },
        { x: 1120, y: 740, w: 180, h: 20 },
        { x: 1450, y: 880, w: 260, h: 20 },
        { x: 1800, y: 780, w: 220, h: 20 },
      ]
    };

    const player = {
      x: 100,
      y: 900,
      w: 40,
      h: 60,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    const camera = {
      x: 0,
      y: 0
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= MOVE_SPEED;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_SPEED;
        player.facing = 1;
      }

      player.vx *= FRICTION;
      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (jump && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
      }

      player.vy += GRAVITY;

      // Horizontal move
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height + 300) {
        player.x = 100;
        player.y = 900;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += 0.16;
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 80, 180, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#7ec850";
        ctx.fillRect(sx, sy, p.w, 6);
      }
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // simple sprite animation using body part offsets/colors
      let legOffset = 0;
      let armOffset = 0;
      let bodyColor = "#ffcc66";

      if (player.state === "run") {
        legOffset = Math.sin(player.animTime * 10) * 8;
        armOffset = Math.sin(player.animTime * 10 + Math.PI) * 6;
        bodyColor = "#ffd166";
      } else if (player.state === "jump") {
        legOffset = 4;
        armOffset = -8;
        bodyColor = "#f4a261";
      }

      // head
      ctx.fillStyle = "#f2d3b1";
      ctx.fillRect(-10, -26, 20, 18);

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-12, -8, 24, 24);

      // arms
      ctx.fillStyle = "#e76f51";
      ctx.fillRect(-18, -6 + armOffset * 0.2, 6, 20);
      ctx.fillRect(12, -6 - armOffset * 0.2, 6, 20);

      // legs
      ctx.fillStyle = "#264653";
      ctx.fillRect(-10, 16, 7, 18 + Math.max(0, legOffset));
      ctx.fillRect(3, 16, 7, 18 + Math.max(0, -legOffset));

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(2, -20, 2, 2);
      ctx.fillRect(6, -20, 2, 2);

      ctx.restore();
    }

    function drawWorld() {
      drawBackground();
      drawPlatforms();
      drawPlayer();
    }

    function loop() {
      updatePlayer();
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawWorld();

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
