- Simple platform collisions
- Basic sprite animation using a generated sprite sheet
- Camera follow
- Minimal but working

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud">Move: ← → or A D | Jump: Space / W / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    // --- World ---
    const GRAVITY = 1800;
    const FRICTION = 0.82;
    const MOVE_ACCEL = 1800;
    const MAX_SPEED_X = 320;
    const JUMP_VELOCITY = -620;
    const TILE = 48;

    const world = {
      width: 3200,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 700, h: 80 },
        { x: 780, y: 430, w: 220, h: 30 },
        { x: 1080, y: 360, w: 220, h: 30 },
        { x: 1380, y: 300, w: 220, h: 30 },
        { x: 1700, y: 420, w: 260, h: 30 },
        { x: 2050, y: 520, w: 500, h: 80 },
        { x: 2650, y: 450, w: 180, h: 30 },
        { x: 2900, y: 380, w: 180, h: 30 },
        { x: 0, y: 1100, w: 3200, h: 100 } // floor safety
      ]
    };

    // --- Generate a tiny sprite sheet dynamically ---
    function createSpriteSheet() {
      const sheet = document.createElement("canvas");
      sheet.width = 96;   // 3 frames * 32
      sheet.height = 32;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, armOffset, bodyColor) {
        sctx.clearRect(offsetX, 0, 32, 32);

        // transparent background by default

        // shadow-ish feet area
        sctx.fillStyle = "#2b2b2b";

        // head
        sctx.fillStyle = "#ffd166";
        sctx.fillRect(offsetX + 10, 3, 12, 10);

        // body
        sctx.fillStyle = bodyColor;
        sctx.fillRect(offsetX + 9, 13, 14, 10);

        // arms
        sctx.fillStyle = "#ef476f";
        sctx.fillRect(offsetX + 5, 14 + armOffset, 4, 8);
        sctx.fillRect(offsetX + 23, 14 - armOffset, 4, 8);

        // legs
        sctx.fillStyle = "#118ab2";
        sctx.fillRect(offsetX + 10, 23, 4, 8 + legOffset);
        sctx.fillRect(offsetX + 18, 23, 4, 8 - legOffset);

        // eyes
        sctx.fillStyle = "#222";
        sctx.fillRect(offsetX + 13, 7, 2, 2);
        sctx.fillRect(offsetX + 17, 7, 2, 2);
      }

      drawFrame(0, 2, 1, "#06d6a0");
      drawFrame(32, 0, 0, "#06d6a0");
      drawFrame(64, -2, -1, "#06d6a0");

      return sheet;
    }

    const spriteSheet = createSpriteSheet();

    // --- Player ---
    const player = {
      x: 120,
      y: 200,
      w: 36,
      h: 52,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 1
    };

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update(dt) {
      // Input
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Horizontal move
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if falling
      if (player.y > world.height + 400) {
        player.x = 120;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 20) {
        player.animTime += dt * 10;
        player.frame = Math.floor(player.animTime) % 3;
      } else {
        player.frame = 1;
        player.animTime = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawBackground() {
      // parallax hills
      ctx.fillStyle = "#9ad1a3";
      for (let i = 0; i < 8; i++) {
        const x = i * 500 - (camera.x * 0.2 % 500);
        ctx.beginPath();
        ctx.arc(x, 500, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#7fb069";
      for (let i = 0; i < 10; i++) {
        const x = i * 380 - (camera.x * 0.35 % 380);
        ctx.beginPath();
        ctx.arc(x, 540, 140, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      // grid
      ctx.strokeStyle = "rgba(255,255,255,0.06)";
      ctx.lineWidth = 1;
      for (let x = 0; x < world.width; x += TILE) {
        ctx.beginPath();
        ctx.moveTo(x - camera.x, -camera.y);
        ctx.lineTo(x - camera.x, world.height - camera.y);
        ctx.stroke();
      }

      // platforms
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#7bc96f";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 10);

        // simple texture
        ctx.fillStyle = "rgba(0,0,0,0.08)";
        for (let i = 0; i < p.w; i += 24) {
          ctx.fillRect(p.x - camera.x + i, p.y - camera.y + 18, 12, p.h - 18);
        }
      }
    }

    function drawPlayer() {
      const px = Math.round(player.x - camera.x);
      const py = Math.round(player.y - camera.y);

      ctx.save();
      ctx.translate(px + player.w / 2, py + player.h / 2);
      ctx.scale(player.facing, 1);

      const frameX = player.frame * 32;
      ctx.drawImage(
        spriteSheet,
        frameX, 0, 32, 32,
        -player.w / 2, -player.h / 2, player.w, player.h
      );

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();

      // debug text
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 34, 220, 24);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(
        `x:${player.x.toFixed(0)} y:${player.y.toFixed(0)} vy:${player.vy.toFixed(0)}`,
        18, canvas.height - 17
      );
    }

    let last = performance.now();
    function loop(now) {
      let dt = (now - last) / 1000;
      last = now;

      // Prevent giant physics steps on tab switch
      dt = Math.min(dt, 0.033);

      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
