        { x: 0, y: 500, w: 500, h: 40 },
        { x: 560, y: 440, w: 180, h: 30 },
        { x: 820, y: 380, w: 180, h: 30 },
        { x: 1080, y: 320, w: 180, h: 30 },
        { x: 1360, y: 420, w: 220, h: 30 },
        { x: 1660, y: 500, w: 300, h: 40 },
        { x: 2050, y: 430, w: 220, h: 30 },
        { x: 300, y: 300, w: 120, h: 24 },
        { x: 80, y: 220, w: 120, h: 24 },
        { x: 0, y: 560, w: 2400, h: 80 }
      ]
    };

    function createPlayerSpriteSheet() {
      const frameW = 32;
      const frameH = 32;
      const frames = 4;
      const off = document.createElement('canvas');
      off.width = frameW * frames;
      off.height = frameH;
      const c = off.getContext('2d');

      for (let i = 0; i < frames; i++) {
        const x = i * frameW;

        c.clearRect(x, 0, frameW, frameH);

        // body
        c.fillStyle = '#ffcc66';
        c.fillRect(x + 10, 6, 12, 10); // head

        c.fillStyle = '#3366ff';
        c.fillRect(x + 9, 16, 14, 10); // torso

        // legs animate
        c.fillStyle = '#222';
        if (i % 2 === 0) {
          c.fillRect(x + 10, 26, 4, 6);
          c.fillRect(x + 18, 24, 4, 8);
        } else {
          c.fillRect(x + 10, 24, 4, 8);
          c.fillRect(x + 18, 26, 4, 6);
        }

        // arms animate
        c.fillStyle = '#ffcc66';
        if (i % 2 === 0) {
          c.fillRect(x + 5, 17, 4, 8);
          c.fillRect(x + 23, 19, 4, 6);
        } else {
          c.fillRect(x + 5, 19, 4, 6);
          c.fillRect(x + 23, 17, 4, 8);
        }

        // eyes
        c.fillStyle = '#000';
        c.fillRect(x + 13, 10, 2, 2);
        c.fillRect(x + 17, 10, 2, 2);
      }

      return off;
    }

    const spriteSheet = createPlayerSpriteSheet();

    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // input
      const left = keys['arrowleft'] || keys['a'];
      const right = keys['arrowright'] || keys['d'];
      const jump = keys[' '] || keys['arrowup'] || keys['w'];

      if (left) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      if (!left && !right) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      player.vy += GRAVITY;

      // horizontal move
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // world bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }
      if (player.y > world.height) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 0.2) {
        player.animTime += 0.2;
        player.frame = Math.floor(player.animTime) % 4;
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      // camera follow
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = '#9bd18b';
      for (let i = 0; i < 8; i++) {
        const hillX = i * 350 - (camera.x * 0.2 % 350);
        ctx.beginPath();
        ctx.arc(hillX, 520, 180, Math.PI, 0);
        ctx.fill();
      }

      // ground strip
      ctx.fillStyle = '#6fbf5f';
      ctx.fillRect(0, 500, canvas.width, 40);
    }

    function drawWorld() {
      for (const p of world.platforms) {
        ctx.fillStyle = '#6b4f2a';
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = '#4caf50';
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawPlayer() {
      const sx = player.frame * 32;
      const dx = player.x - camera.x;
      const dy = player.y - camera.y;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteSheet, sx, 0, 32, 32, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(spriteSheet, sx, 0, 32, 32, dx, dy, player.w, player.h);
      }
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();

      // optional debug text
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillText(`x:${player.x.toFixed(1)} y:${player.y.toFixed(1)} vx:${player.vx.toFixed(1)} vy:${player.vy.toFixed(1)}`, 10, canvas.height - 12);
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
