        ctx.font = "24px sans-serif";
        ctx.fillText("Refresh to play again", WIDTH / 2 - 110, HEIGHT / 2 + 30);
      }
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
