        if (rectIntersect(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      player.x = clamp(player.x, 0, world.width - player.w);

      if (player.y > world.height + 200) {
        player.x = 100;
        player.y = 900;
        player.vx = 0;
        player.vy = 0;
      }

      // Coin collection
      for (const coin of world.coins) {
        if (!coin.collected && circleRectIntersect(coin, player)) {
          coin.collected = true;
          player.coins++;
          coinsEl.textContent = player.coins;
        }
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime++;
      if (player.state === "run") {
        player.frame = Math.floor(player.animTime / 8) % 4;
      } else if (player.state === "idle") {
        player.frame = Math.floor(player.animTime / 20) % 2;
      } else {
        player.frame = 0;
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawBackground() {
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Distant hills
      ctx.fillStyle = "#9ed47a";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 80, 180, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(sx, sy, p.w, 6);
      }
    }

    function drawCoins() {
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const x = coin.x - camera.x;
        const y = coin.y - camera.y;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(performance.now() * 0.003);
        ctx.fillStyle = "gold";
        ctx.beginPath();
        ctx.ellipse(0, 0, coin.r, coin.r + 3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c99700";
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
      }
    }

    // Minimal "sprite animation" drawn procedurally as frames
    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // body
      ctx.fillStyle = "#ff7043";
      ctx.fillRect(-14, -18, 28, 30);

      // head
      ctx.fillStyle = "#f2c29b";
      ctx.fillRect(-10, -28, 20, 14);

      // eye
      ctx.fillStyle = "#111";
      ctx.fillRect(2, -23, 3, 3);

      // legs/arms animated by frame
      ctx.strokeStyle = "#222";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      if (player.state === "run") {
        const f = player.frame;
        const legOffset = [-6, 0, 6, 0][f];
        const armOffset = [6, 0, -6, 0][f];

        // legs
        ctx.beginPath();
        ctx.moveTo(-6, 12);
        ctx.lineTo(-8, 24 + legOffset);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(6, 12);
        ctx.lineTo(8, 24 - legOffset);
        ctx.stroke();

        // arms
        ctx.beginPath();
        ctx.moveTo(-12, -8);
        ctx.lineTo(-20, 2 + armOffset);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(12, -8);
        ctx.lineTo(20, 2 - armOffset);
        ctx.stroke();
      } else if (player.state === "jump") {
        ctx.beginPath();
        ctx.moveTo(-6, 12);
        ctx.lineTo(-12, 22);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(6, 12);
        ctx.lineTo(12, 22);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(-12, -8);
        ctx.lineTo(-20, -14);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(12, -8);
        ctx.lineTo(20, -14);
        ctx.stroke();
      } else {
        const bob = player.frame === 0 ? 0 : 1;

        ctx.beginPath();
        ctx.moveTo(-6, 12);
        ctx.lineTo(-6, 24 + bob);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(6, 12);
        ctx.lineTo(6, 24);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(-12, -8);
        ctx.lineTo(-18, 0);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(12, -8);
        ctx.lineTo(18, 0);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.1)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function loop() {
      updatePlayer();
      updateCamera();

      drawBackground();
      drawWorldBounds();
      drawPlatforms();
      drawCoins();
      drawPlayer();

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

