Below is a **minimal working 2D platformer** in a single HTML file using **plain JavaScript + Canvas**.

It includes:
- **Physics simulation**: gravity, horizontal movement, jumping, collisions
- **Platforms**
- **Sprite animation**: simple animated player using a sprite sheet generated in code
- **Camera follow**
- **Minimal but runnable**

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
  </style>
</head>
<body>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.code] = true);
    addEventListener("keyup", e => keys[e.code] = false);

    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_VELOCITY = -12;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 500, h: 40 },
        { x: 550, y: 440, w: 180, h: 30 },
        { x: 800, y: 380, w: 180, h: 30 },
        { x: 1050, y: 320, w: 180, h: 30 },
        { x: 1300, y: 420, w: 220, h: 30 },
        { x: 1600, y: 500, w: 400, h: 40 },
        { x: 2100, y: 430, w: 220, h: 30 },
        { x: 0, y: 580, w: 2400, h: 80 }
      ]
    };

    function createPlayerSpriteSheet() {
      const frameW = 32;
      const frameH = 48;
      const frames = 4;
      const off = document.createElement("canvas");
      off.width = frameW * frames;
      off.height = frameH;
      const c = off.getContext("2d");

      for (let i = 0; i < frames; i++) {
        const x = i * frameW;

        // body
        c.fillStyle = "#ffcc66";
        c.fillRect(x + 10, 8, 12, 14); // head

        c.fillStyle = "#4f8cff";
        c.fillRect(x + 8, 22, 16, 14); // torso

        c.strokeStyle = "#222";
        c.lineWidth = 3;
        c.beginPath();

        // arms
        c.moveTo(x + 8, 24);
        c.lineTo(x + 3 + (i % 2 ? 2 : 0), 30);
        c.moveTo(x + 24, 24);
        c.lineTo(x + 29 - (i % 2 ? 2 : 0), 30);

        // legs animation
        if (i % 2 === 0) {
          c.moveTo(x + 12, 36);
          c.lineTo(x + 8, 46);
          c.moveTo(x + 20, 36);
          c.lineTo(x + 24, 46);
        } else {
          c.moveTo(x + 12, 36);
          c.lineTo(x + 14, 46);
          c.moveTo(x + 20, 36);
          c.lineTo(x + 18, 46);
        }
        c.stroke();
      }

      return off;
    }

    const playerSheet = createPlayerSpriteSheet();

    const player = {
      x: 100,
      y: 200,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      // Input
      if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (keys["ArrowRight"] || keys["KeyD"]) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      if ((keys["ArrowUp"] || keys["Space"] || keys["KeyW"]) && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

      // Gravity
      player.vy += GRAVITY;

      // Horizontal movement
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Friction
      if (player.onGround) player.vx *= FRICTION;
      else player.vx *= 0.98;

      if (Math.abs(player.vx) < 0.05) player.vx = 0;

      // World bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (!player.onGround) {
        player.animFrame = 1;
      } else if (Math.abs(player.vx) > 0.2) {
        player.animTime += 1;
        if (player.animTime > 8) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
      }
    }

    function updateCamera() {
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#b7e3a1";
      for (let i = 0; i < 8; i++) {
        const x = i * 350 - (camera.x * 0.3 % 350);
        ctx.beginPath();
        ctx.arc(x, 500, 180, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawPlayer() {
      const frameW = 32;
      const frameH = 48;
      const sx = player.animFrame * frameW;
      const dx = player.x - camera.x;
      const dy = player.y - camera.y;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(playerSheet, sx, 0, frameW, frameH, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(playerSheet, sx, 0, frameW, frameH, dx, dy, player.w, player.h);
      }
      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, 10, 220, 60);
      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText("Move: A/D or ←/→", 20, 35);
      ctx.fillText("Jump: W / ↑ / Space", 20, 58);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawHUD();
    }

    function loop() {
      updatePlayer();
      updateCamera();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
