## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: Arial, sans-serif;
    }

    #app {
      width: 100%;
      height: 100%;
      display: block;
    }

    .overlay {
      position: absolute;
      top: 12px;
      left: 12px;
      color: white;
      background: rgba(0, 0, 0, 0.45);
      padding: 10px 14px;
      border-radius: 8px;
      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="overlay">
    <strong>3D Scene Viewer</strong><br />
    Drag to orbit, scroll to zoom
  </div>
  <canvas id="app"></canvas>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const canvas = document.getElementById('app');

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 15, 60);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      200
    );
    camera.position.set(8, 6, 12);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 2, 0);

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.8);
    dirLight.position.set(8, 12, 6);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -20;
    dirLight.shadow.camera.right = 20;
    dirLight.shadow.camera.top = 20;
    dirLight.shadow.camera.bottom = -20;
    scene.add(dirLight);

    // Moving point light
    const pointLight = new THREE.PointLight(0x44aaff, 60, 100, 2);
    pointLight.position.set(0, 5, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2b,
        roughness: 0.9,
        metalness: 0.1
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper
    const grid = new THREE.GridHelper(50, 50, 0x335577, 0x223344);
    grid.position.y = 0.01;
    scene.add(grid);

    // Custom shader material
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;
          vec3 pos = position;

          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;

          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          float mixVal = vUv.x * 0.5 + pulse * 0.5 + vWave;
          vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixVal));
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Center object with shader effect
    const shaderSphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.5, 128, 128),
      shaderMaterial
    );
    shaderSphere.position.set(0, 2.5, 0);
    shaderSphere.castShadow = true;
    shaderSphere.receiveShadow = true;
    scene.add(shaderSphere);

    // Reflective torus
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.3, 128, 24),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.25,
        metalness: 0.85,
        emissive: 0x220800
      })
    );
    torus.position.set(-4, 2, -2);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);

    // Box
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(2, 2, 2),
      new THREE.MeshStandardMaterial({
        color: 0x66ff99,
        roughness: 0.45,
        metalness: 0.3
      })
    );
    box.position.set(4, 1.5, 1);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    // Pillars
    const pillarGeometry = new THREE.CylinderGeometry(0.4, 0.4, 4, 32);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x8899aa,
      roughness: 0.7,
      metalness: 0.2
    });

    const pillarPositions = [
      [-6, 2, -6],
      [ 6, 2, -6],
      [-6, 2,  6],
      [ 6, 2,  6]
    ];

    pillarPositions.forEach(([x, y, z]) => {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      pillar.position.set(x, y, z);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    });

    // Clock
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Animate objects
      shaderSphere.rotation.y += 0.005;
      torus.rotation.x += 0.01;
      torus.rotation.y += 0.013;
      box.rotation.y -= 0.008;
      box.position.y = 1.5 + Math.sin(elapsed * 2.0) * 0.3;

      // Dynamic moving light
      pointLight.position.x = Math.cos(elapsed) * 6.0;
      pointLight.position.z = Math.sin(elapsed) * 6.0;
      pointLight.position.y = 4.0 + Math.sin(elapsed * 2.0) * 1.5;
      lightSphere.position.copy(pointLight.position);

      // Slight directional light motion
      dirLight.position.x = 8 + Math.sin(elapsed * 0.5) * 2.0;
      dirLight.position.z = 6 + Math.cos(elapsed * 0.5) * 2.0;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
```

