      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="overlay">
    <strong>3D Scene Viewer</strong><br />
    Drag to orbit, scroll to zoom
  </div>
  <canvas id="app"></canvas>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const canvas = document.getElementById('app');

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0b1020);
    scene.fog = new THREE.Fog(0x0b1020, 15, 50);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(6, 5, 10);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1.5, 0);

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambientLight);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Point light with dynamic movement
    const pointLight = new THREE.PointLight(0x44aaff, 40, 100, 2);
    pointLight.position.set(0, 4, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2f,
        roughness: 0.85,
        metalness: 0.15
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper
    const grid = new THREE.GridHelper(50, 50, 0x446688, 0x223344);
    grid.position.y = 0.01;
    scene.add(grid);

    // Central object with shader material
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;

        void main() {
          vUv = uv;
          vec3 pos = position;

          float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
          wave += cos(pos.x * 3.0 + uTime * 1.5) * 0.1;
          pos += normal * wave;

          vWave = wave;
          vNormalW = normalize(normalMatrix * normal);

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        uniform float uTime;

        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;

        void main() {
          float mixValue = 0.5 + 0.5 * sin(uTime + vUv.y * 8.0 + vWave * 10.0);
          vec3 color = mix(uColorA, uColorB, mixValue);

          vec3 lightDir = normalize(vec3(0.4, 1.0, 0.6));
          float diffuse = max(dot(normalize(vNormalW), lightDir), 0.0);

          float glow = 0.35 + 0.65 * abs(vWave) * 3.0;
          color *= diffuse + glow;

          gl_FragColor = vec4(color, 1.0);
        }
      `,
      wireframe: false
    });

    const centralMesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.5, 0.45, 256, 32),
      shaderMaterial
    );
    centralMesh.position.y = 2.2;
    centralMesh.castShadow = true;
    centralMesh.receiveShadow = true;
    scene.add(centralMesh);

    // Additional animated objects
    const objects = [];
    const sphereGeometry = new THREE.SphereGeometry(0.45, 32, 32);

    for (let i = 0; i < 12; i++) {
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 12, 0.8, 0.55),
        roughness: 0.35,
        metalness: 0.7,
        emissive: new THREE.Color().setHSL(i / 12, 0.8, 0.15)
      });

      const mesh = new THREE.Mesh(sphereGeometry, material);
      const angle = (i / 12) * Math.PI * 2;
      const radius = 5;

      mesh.position.set(
        Math.cos(angle) * radius,
        1 + Math.sin(i) * 0.3,
        Math.sin(angle) * radius
      );

      mesh.castShadow = true;
      mesh.receiveShadow = true;

      scene.add(mesh);
      objects.push({ mesh, angle, radius, speed: 0.3 + i * 0.03 });
    }

    // Decorative columns
    const columnGeometry = new THREE.BoxGeometry(0.8, 3, 0.8);
    for (let i = 0; i < 6; i++) {
      const mat = new THREE.MeshStandardMaterial({
        color: 0x8899aa,
        roughness: 0.6,
        metalness: 0.3
      });

      const col = new THREE.Mesh(columnGeometry, mat);
      const angle = (i / 6) * Math.PI * 2;
      col.position.set(Math.cos(angle) * 8, 1.5, Math.sin(angle) * 8);
      col.castShadow = true;
      col.receiveShadow = true;
      scene.add(col);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Rotate central object
      centralMesh.rotation.x = elapsed * 0.35;
      centralMesh.rotation.y = elapsed * 0.6;

      // Animate orbiting spheres
      objects.forEach((obj, index) => {
        const a = obj.angle + elapsed * obj.speed;
        obj.mesh.position.x = Math.cos(a) * obj.radius;
        obj.mesh.position.z = Math.sin(a) * obj.radius;
        obj.mesh.position.y = 1.2 + Math.sin(elapsed * 2 + index) * 0.5;
        obj.mesh.rotation.y += 0.02;
      });

      // Dynamic point light motion
      pointLight.position.x = Math.cos(elapsed * 1.2) * 6;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 6;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 1.5;
      pointLight.color.setHSL((elapsed * 0.1) % 1, 0.8, 0.6);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
