        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          float mixValue = 0.5 + 0.5 * sin(uTime + vUv.y * 10.0 + vWave * 5.0);
          vec3 color = mix(uColorA, uColorB, mixValue);

          float glow = 0.7 + 0.3 * sin(uTime * 3.0 + vUv.x * 20.0);
          color *= glow;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Shader Sphere
    const shaderSphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.5, 128, 128),
      shaderMaterial
    );
    shaderSphere.position.set(0, 2.5, 0);
    shaderSphere.castShadow = true;
    scene.add(shaderSphere);

    // Metallic Torus
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 128, 32),
      new THREE.MeshStandardMaterial({
        color: 0xffcc66,
        metalness: 0.9,
        roughness: 0.2
      })
    );
    torus.position.set(-4, 2, -2);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);

    // Glass-like Icosahedron
    const glassObject = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.4, 1),
      new THREE.MeshPhysicalMaterial({
        color: 0x88ffee,
        metalness: 0.1,
        roughness: 0.05,
        transmission: 0.9,
        transparent: true,
        opacity: 1.0,
        clearcoat: 1.0,
        clearcoatRoughness: 0.1
      })
    );
    glassObject.position.set(4, 2.2, 1);
    glassObject.castShadow = true;
    glassObject.receiveShadow = true;
    scene.add(glassObject);

    // Decorative pillars
    const pillarGeometry = new THREE.BoxGeometry(1, 4, 1);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x7a7f8f,
      roughness: 0.7,
      metalness: 0.2
    });

    for (let i = -2; i <= 2; i++) {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      pillar.position.set(i * 3, 2, -8);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Animate objects
      shaderSphere.rotation.y += 0.005;
      torus.rotation.x = elapsed * 0.7;
      torus.rotation.y = elapsed * 1.1;

      glassObject.rotation.x = elapsed * 0.4;
      glassObject.rotation.y = elapsed * 0.8;
      glassObject.position.y = 2.2 + Math.sin(elapsed * 2.0) * 0.3;

      // Move point light in a circle
      pointLight.position.x = Math.cos(elapsed) * 6;
      pointLight.position.z = Math.sin(elapsed) * 6;
      pointLight.position.y = 4 + Math.sin(elapsed * 2.0) * 1.5;

      pointLightHelper.position.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
