<body>
  <div class="overlay">
    <strong>3D Scene Viewer</strong><br />
    Drag to orbit, scroll to zoom
  </div>
  <div id="app"></div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const container = document.getElementById('app');

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 15, 60);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 4, 12);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    container.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 4;
    controls.maxDistance = 40;

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Point light with animation
    const pointLight = new THREE.PointLight(0x44aaff, 40, 100, 2);
    pointLight.position.set(0, 5, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(80, 80),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2b,
        metalness: 0.2,
        roughness: 0.8
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper
    const grid = new THREE.GridHelper(80, 80, 0x334466, 0x223344);
    grid.position.y = -1.99;
    scene.add(grid);

    // Custom shader material
    const shaderUniforms = {
      uTime: { value: 0.0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const vertexShader = `
      uniform float uTime;
      varying vec2 vUv;
      varying float vWave;

      void main() {
        vUv = uv;

        vec3 pos = position;
        float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                   + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;
        pos += normal * wave;
        vWave = wave;

        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
      }
    `;

    const fragmentShader = `
      uniform float uTime;
      uniform vec3 uColorA;
      uniform vec3 uColorB;

      varying vec2 vUv;
      varying float vWave;

      void main() {
        float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0);
        vec3 color = mix(uColorA, uColorB, vUv.y + vWave * 2.0 + pulse * 0.2);
        gl_FragColor = vec4(color, 1.0);
      }
    `;

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader,
      fragmentShader
    });

    // Central shader object
    const shaderObject = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.5, 0.45, 180, 32),
      shaderMaterial
    );
    shaderObject.position.set(0, 1.2, 0);
    shaderObject.castShadow = true;
    shaderObject.receiveShadow = true;
    scene.add(shaderObject);

    // Additional scene objects
    const objects = [];

    const boxGeometry = new THREE.BoxGeometry(1.2, 1.2, 1.2);
    const sphereGeometry = new THREE.SphereGeometry(0.7, 32, 32);

    for (let i = 0; i < 6; i++) {
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 6, 0.7, 0.5),
        metalness: 0.6,
        roughness: 0.3
      });

      const mesh = new THREE.Mesh(
        i % 2 === 0 ? boxGeometry : sphereGeometry,
        material
      );

      const angle = (i / 6) * Math.PI * 2;
      mesh.position.set(Math.cos(angle) * 5, -0.8, Math.sin(angle) * 5);
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      scene.add(mesh);
      objects.push(mesh);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Animate central object
      shaderObject.rotation.x = elapsed * 0.4;
      shaderObject.rotation.y = elapsed * 0.8;

      // Animate orbiting point light
      pointLight.position.x = Math.cos(elapsed * 1.2) * 6;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 6;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 1.5;
      lightSphere.position.copy(pointLight.position);

      // Animate surrounding objects
      objects.forEach((obj, i) => {
        obj.rotation.x += 0.01 + i * 0.001;
        obj.rotation.y += 0.015 + i * 0.001;

        const angle = (i / objects.length) * Math.PI * 2 + elapsed * 0.3;
        obj.position.x = Math.cos(angle) * 5;
        obj.position.z = Math.sin(angle) * 5;
        obj.position.y = -0.5 + Math.sin(elapsed * 2 + i) * 0.4;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
