    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2f,
        metalness: 0.2,
        roughness: 0.8
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard objects
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(2, 2, 2),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        metalness: 0.5,
        roughness: 0.3
      })
    );
    box.position.set(-3, 1, 0);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0x66ffcc,
        metalness: 0.1,
        roughness: 0.2
      })
    );
    sphere.position.set(3, 1.2, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Custom shader object
    const shaderUniforms = {
      uTime: { value: 0.0 },
      uColorA: { value: new THREE.Color(0x7f5af0) },
      uColorB: { value: new THREE.Color(0x2cb67d) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;

          vec3 pos = position;
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;
          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          vec3 color = mix(uColorA, uColorB, vUv.x + vWave * 1.5 + pulse * 0.2);
          gl_FragColor = vec4(color, 1.0);
        }
      `,
      side: THREE.DoubleSide
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.2, 0.35, 180, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 2.5, -3);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Decorative pillars
    const pillarGeometry = new THREE.CylinderGeometry(0.4, 0.4, 3, 32);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x8899aa,
      metalness: 0.3,
      roughness: 0.6
    });

    for (let i = 0; i < 6; i++) {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      const angle = (i / 6) * Math.PI * 2;
      pillar.position.set(Math.cos(angle) * 8, 1.5, Math.sin(angle) * 8);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate objects
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      sphere.position.y = 1.2 + Math.sin(elapsed * 2.0) * 0.4;
      sphere.rotation.y += 0.01;

      shaderMesh.rotation.x = elapsed * 0.3;
      shaderMesh.rotation.y = elapsed * 0.6;
      shaderUniforms.uTime.value = elapsed;

      // Move point light in a circle
      pointLight.position.x = Math.cos(elapsed) * 5.0;
      pointLight.position.z = Math.sin(elapsed) * 5.0;
      pointLight.position.y = 3.0 + Math.sin(elapsed * 2.0) * 1.5;

      lightSphere.position.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
