## Full Code

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      overflow: hidden;
      width: 100%;
      height: 100%;
      background: #000;
      font-family: Arial, sans-serif;
    }

    #info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      z-index: 10;
      background: rgba(0,0,0,0.4);
      padding: 10px 14px;
      border-radius: 8px;
      font-size: 14px;
    }

    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    Real-Time 3D Scene Viewer<br />
    Mouse: Rotate / Zoom / Pan
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    let scene, camera, renderer, controls;
    let clock;
    let sphere, torus, plane;
    let pointLight, directionalLight;
    let shaderMaterial;

    init();
    animate();

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050816);
      scene.fog = new THREE.Fog(0x050816, 20, 80);

      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        1000
      );
      camera.position.set(0, 4, 12);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap;
      document.body.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;

      clock = new THREE.Clock();

      // Ambient light
      const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
      scene.add(ambientLight);

      // Directional light
      directionalLight = new THREE.DirectionalLight(0xffffff, 1.5);
      directionalLight.position.set(5, 10, 5);
      directionalLight.castShadow = true;
      directionalLight.shadow.mapSize.width = 2048;
      directionalLight.shadow.mapSize.height = 2048;
      directionalLight.shadow.camera.near = 0.5;
      directionalLight.shadow.camera.far = 50;
      scene.add(directionalLight);

      // Point light with animation
      pointLight = new THREE.PointLight(0x44aaff, 2, 50);
      pointLight.position.set(0, 5, 0);
      pointLight.castShadow = true;
      scene.add(pointLight);

      const pointLightHelper = new THREE.Mesh(
        new THREE.SphereGeometry(0.15, 16, 16),
        new THREE.MeshBasicMaterial({ color: 0x44aaff })
      );
      pointLight.add(pointLightHelper);

      // Ground plane
      const planeGeometry = new THREE.PlaneGeometry(50, 50);
      const planeMaterial = new THREE.MeshStandardMaterial({
        color: 0x1a1a1a,
        roughness: 0.85,
        metalness: 0.2
      });
      plane = new THREE.Mesh(planeGeometry, planeMaterial);
      plane.rotation.x = -Math.PI / 2;
      plane.receiveShadow = true;
      scene.add(plane);

      // Shader material
      shaderMaterial = new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0.0 },
          uColorA: { value: new THREE.Color(0x00ffff) },
          uColorB: { value: new THREE.Color(0xff00ff) }
        },
        vertexShader: `
          uniform float uTime;
          varying vec2 vUv;
          varying float vWave;

          void main() {
            vUv = uv;
            vec3 pos = position;

            float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                       + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;

            pos += normal * wave;
            vWave = wave;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;

          varying vec2 vUv;
          varying float vWave;

          void main() {
            float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0);
            vec3 color = mix(uColorA, uColorB, vUv.y + vWave * 2.0 + pulse * 0.2);
            gl_FragColor = vec4(color, 1.0);
          }
        `
      });

      // Center sphere with shader
      sphere = new THREE.Mesh(
        new THREE.SphereGeometry(1.5, 128, 128),
        shaderMaterial
      );
      sphere.position.set(0, 2, 0);
      sphere.castShadow = true;
      sphere.receiveShadow = true;
      scene.add(sphere);

      // Torus knot
      torus = new THREE.Mesh(
        new THREE.TorusKnotGeometry(1, 0.35, 128, 32),
        new THREE.MeshStandardMaterial({
          color: 0xff8844,
          roughness: 0.35,
          metalness: 0.8,
          emissive: 0x331100
        })
      );
      torus.position.set(-4, 2, -2);
      torus.castShadow = true;
      torus.receiveShadow = true;
      scene.add(torus);

      // Additional objects
      const boxGroup = new THREE.Group();
      for (let i = 0; i < 20; i++) {
        const box = new THREE.Mesh(
          new THREE.BoxGeometry(0.6, 0.6, 0.6),
          new THREE.MeshStandardMaterial({
            color: new THREE.Color().setHSL(i / 20, 0.8, 0.5),
            roughness: 0.5,
            metalness: 0.4
          })
        );

        const angle = (i / 20) * Math.PI * 2;
        const radius = 8 + Math.random() * 2;
        box.position.set(
          Math.cos(angle) * radius,
          0.5 + Math.random() * 2,
          Math.sin(angle) * radius
        );
        box.rotation.set(
          Math.random() * Math.PI,
          Math.random() * Math.PI,
          Math.random() * Math.PI
        );
        box.castShadow = true;
        box.receiveShadow = true;
        boxGroup.add(box);
      }
      scene.add(boxGroup);

      // Subtle stars/background particles
      const starGeometry = new THREE.BufferGeometry();
      const starCount = 1000;
      const starPositions = new Float32Array(starCount * 3);

      for (let i = 0; i < starCount; i++) {
        starPositions[i * 3 + 0] = (Math.random() - 0.5) * 200;
        starPositions[i * 3 + 1] = Math.random() * 100;
        starPositions[i * 3 + 2] = (Math.random() - 0.5) * 200;
      }

      starGeometry.setAttribute(
        'position',
        new THREE.BufferAttribute(starPositions, 3)
      );

      const starMaterial = new THREE.PointsMaterial({
        color: 0xffffff,
        size: 0.2,
        transparent: true,
        opacity: 0.8
      });

      const stars = new THREE.Points(starGeometry, starMaterial);
      scene.add(stars);

      window.addEventListener('resize', onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderMaterial.uniforms.uTime.value = elapsed;

      // Animate objects
      sphere.rotation.y += 0.005;
      sphere.rotation.x = Math.sin(elapsed * 0.5) * 0.2;

      torus.rotation.x += 0.01;
      torus.rotation.y += 0.015;

      // Animate point light in a circular path
      pointLight.position.x = Math.cos(elapsed) * 6;
      pointLight.position.z = Math.sin(elapsed) * 6;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 2.0;

      // Animate directional light slightly
      directionalLight.position.x = Math.sin(elapsed * 0.3) * 10;
      directionalLight.position.z = Math.cos(elapsed * 0.3) * 10;

      controls.update();
      renderer.render(scene, camera);
    }
  </script>
</body>
</html>
