          vec3 lightDir = normalize(vec3(sin(uTime), 1.0, cos(uTime)));
          float diffuse = max(dot(normal, lightDir), 0.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          vec3 baseColor = mix(uColorA, uColorB, vUv.y + pulse * 0.25 + vWave);

          float fresnel = pow(1.0 - abs(dot(normal, vec3(0.0, 0.0, 1.0))), 2.0);
          vec3 color = baseColor * (0.35 + diffuse * 0.9) + fresnel * 0.35;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const centralMesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.5, 0.45, 256, 32),
      shaderMaterial
    );
    centralMesh.position.set(0, 2.2, 0);
    centralMesh.castShadow = true;
    centralMesh.receiveShadow = true;
    scene.add(centralMesh);

    // Additional reflective objects
    const sphereMaterial = new THREE.MeshStandardMaterial({
      color: 0xffaa33,
      roughness: 0.25,
      metalness: 0.8
    });

    const sphere1 = new THREE.Mesh(
      new THREE.SphereGeometry(0.8, 64, 64),
      sphereMaterial
    );
    sphere1.position.set(-3, 1, 2);
    sphere1.castShadow = true;
    sphere1.receiveShadow = true;
    scene.add(sphere1);

    const sphere2 = new THREE.Mesh(
      new THREE.SphereGeometry(0.8, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0x66ffcc,
        roughness: 0.35,
        metalness: 0.6
      })
    );
    sphere2.position.set(3, 1, -1);
    sphere2.castShadow = true;
    sphere2.receiveShadow = true;
    scene.add(sphere2);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.MeshStandardMaterial({
        color: 0x8899ff,
        roughness: 0.4,
        metalness: 0.5
      })
    );
    box.position.set(0, 0.8, -4);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Animate central object
      centralMesh.rotation.x = elapsed * 0.35;
      centralMesh.rotation.y = elapsed * 0.6;

      // Animate other objects
      sphere1.position.y = 1 + Math.sin(elapsed * 1.8) * 0.35;
      sphere1.rotation.y += 0.01;

      sphere2.position.y = 1 + Math.cos(elapsed * 1.4) * 0.3;
      sphere2.rotation.x += 0.008;

      box.rotation.x = elapsed * 0.7;
      box.rotation.y = elapsed * 0.9;

      // Move dynamic point light in a circular path
      pointLight.position.x = Math.cos(elapsed) * 4;
      pointLight.position.z = Math.sin(elapsed) * 4;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 1.2;

      lightSphere.position.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
