</head>
<body>
  <div id="info">
    Real-Time 3D Scene Viewer<br />
    Mouse: Rotate / Zoom / Pan
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0f1f);
    scene.fog = new THREE.Fog(0x0a0f1f, 20, 80);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(8, 6, 12);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 2, 0);

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambientLight);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight.position.set(10, 15, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -20;
    dirLight.shadow.camera.right = 20;
    dirLight.shadow.camera.top = 20;
    dirLight.shadow.camera.bottom = -20;
    scene.add(dirLight);

    // Point light with dynamic movement
    const pointLight = new THREE.PointLight(0x44aaff, 2.5, 100);
    pointLight.position.set(0, 5, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(100, 100);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x1a1a1a,
      roughness: 0.9,
      metalness: 0.1
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper
    const grid = new THREE.GridHelper(100, 100, 0x444444, 0x222222);
    scene.add(grid);

    // Standard objects
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.5, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.3,
        metalness: 0.6
      })
    );
    sphere.position.set(-4, 1.5, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(2.5, 2.5, 2.5),
      new THREE.MeshStandardMaterial({
        color: 0x44ff88,
        roughness: 0.5,
        metalness: 0.2
      })
    );
    box.position.set(4, 1.25, 0);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    // Torus knot with custom shader material
    const shaderUniforms = {
      uTime: { value: 0.0 },
      uColorA: { value: new THREE.Color(0x00ffff) },
      uColorB: { value: new THREE.Color(0xff00ff) }
    };

    const vertexShader = `
      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vPosition;
      uniform float uTime;

      void main() {
        vUv = uv;
        vNormal = normalize(normalMatrix * normal);

        vec3 pos = position;
        pos += normal * sin(uTime * 2.0 + position.y * 4.0) * 0.15;

        vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
        vPosition = worldPosition.xyz;

        gl_Position = projectionMatrix * viewMatrix * worldPosition;
      }
    `;

    const fragmentShader = `
      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vPosition;

      uniform float uTime;
      uniform vec3 uColorA;
      uniform vec3 uColorB;

      void main() {
        float wave = sin(vUv.y * 20.0 - uTime * 3.0) * 0.5 + 0.5;
        float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);

        vec3 color = mix(uColorA, uColorB, wave);
        color += fresnel * 0.5;

        gl_FragColor = vec4(color, 1.0);
      }
    `;

    const shaderMat = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader,
      fragmentShader
    });

    const torusKnot = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.5, 0.5, 200, 32),
      shaderMat
    );
    torusKnot.position.set(0, 3, -4);
    torusKnot.castShadow = true;
    torusKnot.receiveShadow = true;
    scene.add(torusKnot);

    // Decorative glowing orbs
    const orbGeometry = new THREE.SphereGeometry(0.2, 16, 16);
    const orbMaterial = new THREE.MeshBasicMaterial({ color: 0x88ccff });
    const orbs = [];

    for (let i = 0; i < 20; i++) {
      const orb = new THREE.Mesh(orbGeometry, orbMaterial.clone());
      orb.position.set(
        (Math.random() - 0.5) * 20,
        Math.random() * 6 + 1,
        (Math.random() - 0.5) * 20
      );
      orb.material.color.setHSL(Math.random(), 0.8, 0.6);
      scene.add(orb);
      orbs.push(orb);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate standard objects
      sphere.rotation.y += 0.01;
      sphere.position.y = 1.5 + Math.sin(elapsed * 2.0) * 0.3;

      box.rotation.x += 0.01;
      box.rotation.y += 0.015;
      box.position.y = 1.25 + Math.cos(elapsed * 1.5) * 0.25;

      // Animate shader object
      torusKnot.rotation.x = elapsed * 0.4;
      torusKnot.rotation.y = elapsed * 0.7;
      shaderUniforms.uTime.value = elapsed;

      // Dynamic point light movement
      pointLight.position.x = Math.sin(elapsed) * 8;
      pointLight.position.z = Math.cos(elapsed) * 8;
      pointLight.position.y = 4 + Math.sin(elapsed * 2.0) * 2.0;

      // Animate orbs
      orbs.forEach((orb, i) => {
        orb.position.y += Math.sin(elapsed * 2 + i) * 0.002;
        orb.position.x += Math.sin(elapsed + i * 0.3) * 0.001;
        orb.position.z += Math.cos(elapsed + i * 0.5) * 0.001;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
