  <div id="info">
    Real-Time 3D Scene Viewer<br />
    Mouse: Rotate / Zoom / Pan
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    let scene, camera, renderer, controls;
    let clock;
    let sphere, torus, floor;
    let pointLight, directionalLight;
    let shaderMaterial;

    init();
    animate();

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050816);
      scene.fog = new THREE.Fog(0x050816, 20, 60);

      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        1000
      );
      camera.position.set(0, 4, 12);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap;
      document.body.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;

      clock = new THREE.Clock();

      // Ambient light
      const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
      scene.add(ambientLight);

      // Directional light
      directionalLight = new THREE.DirectionalLight(0xffffff, 1.5);
      directionalLight.position.set(5, 10, 7);
      directionalLight.castShadow = true;
      directionalLight.shadow.mapSize.width = 2048;
      directionalLight.shadow.mapSize.height = 2048;
      directionalLight.shadow.camera.near = 0.5;
      directionalLight.shadow.camera.far = 50;
      directionalLight.shadow.camera.left = -15;
      directionalLight.shadow.camera.right = 15;
      directionalLight.shadow.camera.top = 15;
      directionalLight.shadow.camera.bottom = -15;
      scene.add(directionalLight);

      // Moving point light
      pointLight = new THREE.PointLight(0x44aaff, 2.5, 100);
      pointLight.position.set(0, 5, 0);
      pointLight.castShadow = true;
      scene.add(pointLight);

      const pointLightHelper = new THREE.Mesh(
        new THREE.SphereGeometry(0.15, 16, 16),
        new THREE.MeshBasicMaterial({ color: 0x44aaff })
      );
      pointLight.add(pointLightHelper);

      // Floor
      const floorGeometry = new THREE.PlaneGeometry(50, 50);
      const floorMaterial = new THREE.MeshStandardMaterial({
        color: 0x1a1a1a,
        roughness: 0.85,
        metalness: 0.15
      });
      floor = new THREE.Mesh(floorGeometry, floorMaterial);
      floor.rotation.x = -Math.PI / 2;
      floor.receiveShadow = true;
      scene.add(floor);

      // Shader material
      shaderMaterial = new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0.0 },
          uColorA: { value: new THREE.Color(0x00ffff) },
          uColorB: { value: new THREE.Color(0xff00ff) }
        },
        vertexShader: `
          uniform float uTime;
          varying vec2 vUv;
          varying float vWave;

          void main() {
            vUv = uv;
            vec3 pos = position;

            float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15;
            wave += cos(pos.y * 5.0 + uTime * 1.5) * 0.15;
            pos += normal * wave;

            vWave = wave;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;

          varying vec2 vUv;
          varying float vWave;

          void main() {
            float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
            vec3 color = mix(uColorA, uColorB, vUv.x + vWave * 2.0 + pulse * 0.2);
            gl_FragColor = vec4(color, 1.0);
          }
        `
      });

      // Central sphere with shader
      sphere = new THREE.Mesh(
        new THREE.SphereGeometry(1.8, 128, 128),
        shaderMaterial
      );
      sphere.position.set(0, 2.2, 0);
      sphere.castShadow = true;
      sphere.receiveShadow = true;
      scene.add(sphere);

      // Torus knot
      const torusMaterial = new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.35,
        metalness: 0.8,
        emissive: 0x331100
      });

      torus = new THREE.Mesh(
        new THREE.TorusKnotGeometry(1.1, 0.35, 180, 32),
        torusMaterial
      );
      torus.position.set(-4, 2, -2);
      torus.castShadow = true;
      torus.receiveShadow = true;
      scene.add(torus);

      // Extra objects for scene depth
      const boxGeometry = new THREE.BoxGeometry(1.4, 1.4, 1.4);
      const boxMaterial = new THREE.MeshStandardMaterial({
        color: 0x66ff99,
        roughness: 0.4,
        metalness: 0.5
      });

      for (let i = 0; i < 12; i++) {
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        const angle = (i / 12) * Math.PI * 2;
        const radius = 8 + Math.random() * 2;
        box.position.set(
          Math.cos(angle) * radius,
          0.7,
          Math.sin(angle) * radius
        );
        box.rotation.set(
          Math.random() * Math.PI,
          Math.random() * Math.PI,
          Math.random() * Math.PI
        );
        box.castShadow = true;
        box.receiveShadow = true;
        scene.add(box);
      }

      // Grid helper
      const grid = new THREE.GridHelper(50, 50, 0x444444, 0x222222);
      grid.position.y = 0.01;
      scene.add(grid);

      window.addEventListener('resize', onWindowResize);
    }

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      controls.update();

      // Update shader time
      shaderMaterial.uniforms.uTime.value = elapsed;

      // Animate sphere
      sphere.rotation.y += 0.005;
      sphere.rotation.x = Math.sin(elapsed * 0.5) * 0.2;

      // Animate torus knot
      torus.rotation.x += 0.01;
      torus.rotation.y += 0.008;
      torus.position.y = 2 + Math.sin(elapsed * 2.0) * 0.3;

      // Move point light in a circular path
      pointLight.position.x = Math.cos(elapsed) * 6.0;
      pointLight.position.z = Math.sin(elapsed) * 6.0;
      pointLight.position.y = 4.0 + Math.sin(elapsed * 2.0) * 1.5;

      // Slight directional light motion
      directionalLight.position.x = Math.sin(elapsed * 0.5) * 8.0;
      directionalLight.position.z = Math.cos(elapsed * 0.5) * 8.0;

      renderer.render(scene, camera);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }
  </script>
