        varying float vWave;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          vUv = uv;

          vec3 pos = position;
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 5.0 + uTime * 1.5) * 0.15;
          pos += normal * wave;

          vWave = wave;
          vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
          vPositionW = worldPosition.xyz;
          vNormalW = normalize(mat3(modelMatrix) * normal);

          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          float mixVal = 0.5 + 0.5 * sin(vUv.x * 8.0 + uTime + vWave * 8.0);
          vec3 baseColor = mix(uColorA, uColorB, mixVal);

          vec3 lightDir = normalize(vec3(1.0, 1.5, 0.8));
          float diff = max(dot(normalize(vNormalW), lightDir), 0.0);

          vec3 viewDir = normalize(cameraPosition - vPositionW);
          vec3 reflectDir = reflect(-lightDir, normalize(vNormalW));
          float spec = pow(max(dot(viewDir, reflectDir), 0.0), 24.0);

          vec3 color = baseColor * (0.35 + diff * 0.9);
          color += spec * vec3(1.0);
          color += pulse * 0.15;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.5, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 2.5, 3.5);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Decorative grid of small pillars
    const pillarGroup = new THREE.Group();
    const pillarGeo = new THREE.BoxGeometry(0.5, 0.5, 0.5);

    for (let x = -4; x <= 4; x += 2) {
      for (let z = -4; z <= 4; z += 2) {
        const h = Math.random() * 2 + 0.5;
        const pillar = new THREE.Mesh(
          pillarGeo,
          new THREE.MeshStandardMaterial({
            color: new THREE.Color().setHSL(Math.random(), 0.6, 0.5),
            roughness: 0.5,
            metalness: 0.3
          })
        );
        pillar.scale.y = h * 2;
        pillar.position.set(x, pillar.scale.y * 0.25, z + 8);
        pillar.castShadow = true;
        pillar.receiveShadow = true;
        pillarGroup.add(pillar);
      }
    }
    scene.add(pillarGroup);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate objects
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      sphere.position.y = 1.2 + Math.sin(elapsed * 2.0) * 0.35;
      sphere.rotation.y += 0.01;

      torus.rotation.x = elapsed * 0.7;
      torus.rotation.y = elapsed * 1.1;

      shaderMesh.rotation.y = elapsed * 0.8;
      shaderMesh.rotation.x = Math.sin(elapsed * 0.5) * 0.3;
      shaderUniforms.uTime.value = elapsed;

      // Dynamic point light motion
      pointLight.position.x = Math.cos(elapsed) * 6.0;
      pointLight.position.z = Math.sin(elapsed) * 6.0;
      pointLight.position.y = 4.0 + Math.sin(elapsed * 2.0) * 1.5;
      pointLightSphere.position.copy(pointLight.position);

      // Animate pillars
      pillarGroup.children.forEach((pillar, i) => {
        pillar.scale.y = 1.0 + Math.sin(elapsed * 2.0 + i * 0.35) * 0.8 + 1.2;
        pillar.position.y = pillar.scale.y * 0.25;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
