    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2b,
        roughness: 0.9,
        metalness: 0.1
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard objects
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.5, 1.5, 1.5),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.35,
        metalness: 0.4
      })
    );
    box.position.set(-2.5, 1, 0);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0x66ffcc,
        roughness: 0.2,
        metalness: 0.7
      })
    );
    sphere.position.set(2.5, 1.2, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Torus knot with custom shader
    const shaderUniforms = {
      uTime: { value: 0 },
      uLightPos: { value: new THREE.Vector3() },
      uColorA: { value: new THREE.Color(0x7c3aed) },
      uColorB: { value: new THREE.Color(0x06b6d4) }
    };

    const vertexShader = `
      uniform float uTime;
      varying vec3 vNormal;
      varying vec3 vWorldPosition;
      varying vec2 vUv;

      void main() {
        vUv = uv;
        vNormal = normalize(normalMatrix * normal);

        vec3 transformed = position + normal * sin(uTime * 2.0 + position.y * 4.0) * 0.08;

        vec4 worldPos = modelMatrix * vec4(transformed, 1.0);
        vWorldPosition = worldPos.xyz;

        gl_Position = projectionMatrix * viewMatrix * worldPos;
      }
    `;

    const fragmentShader = `
      uniform float uTime;
      uniform vec3 uLightPos;
      uniform vec3 uColorA;
      uniform vec3 uColorB;

      varying vec3 vNormal;
      varying vec3 vWorldPosition;
      varying vec2 vUv;

      void main() {
        vec3 normal = normalize(vNormal);
        vec3 lightDir = normalize(uLightPos - vWorldPosition);

        float diffuse = max(dot(normal, lightDir), 0.0);

        float fresnel = pow(1.0 - max(dot(normal, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

        float wave = 0.5 + 0.5 * sin(uTime * 3.0 + vUv.y * 10.0);
        vec3 baseColor = mix(uColorA, uColorB, wave);

        vec3 color = baseColor * (0.25 + diffuse * 1.2);
        color += fresnel * 0.35;

        gl_FragColor = vec4(color, 1.0);
      }
    `;

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader,
      fragmentShader
    });

    const torusKnot = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 180, 32),
      shaderMaterial
    );
    torusKnot.position.set(0, 2.2, -3);
    torusKnot.castShadow = true;
    torusKnot.receiveShadow = true;
    scene.add(torusKnot);

    // Decorative pillars
    const pillarGeometry = new THREE.CylinderGeometry(0.3, 0.3, 3, 32);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x8892b0,
      roughness: 0.7,
      metalness: 0.2
    });

    const pillarPositions = [
      [-5, 1.5, -5],
      [5, 1.5, -5],
      [-5, 1.5, 5],
      [5, 1.5, 5]
    ];

    pillarPositions.forEach(([x, y, z]) => {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      pillar.position.set(x, y, z);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    });

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate standard objects
      box.rotation.x = elapsed * 0.7;
      box.rotation.y = elapsed * 1.1;

      sphere.position.y = 1.2 + Math.sin(elapsed * 2.0) * 0.3;
      sphere.rotation.y = elapsed * 0.8;

      torusKnot.rotation.x = elapsed * 0.3;
      torusKnot.rotation.y = elapsed * 0.6;

      // Move point light in a circular path
      pointLight.position.x = Math.cos(elapsed) * 4.0;
      pointLight.position.z = Math.sin(elapsed) * 4.0;
      pointLight.position.y = 3.0 + Math.sin(elapsed * 2.0) * 1.0;

      lightSphere.position.copy(pointLight.position);

      // Update shader uniforms
      shaderUniforms.uTime.value = elapsed;
      shaderUniforms.uLightPos.value.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
