```javascript
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const canvas = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 45);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 10);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Clock
const clock = new THREE.Clock();

// Ambient light
const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(5, 10, 7);
scene.add(dirLight);

// Point light with animated motion
const pointLight = new THREE.PointLight(0x44aaff, 40, 100, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Visual helper for point light
const pointLightMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
pointLight.add(pointLightMesh);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(30, 30),
  new THREE.MeshStandardMaterial({
    color: 0x1e2438,
    roughness: 0.9,
    metalness: 0.1
  })
);
ground.rotation.x = -Math.PI * 0.5;
ground.position.y = -1.5;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x7c3aed) },
    uColorB: { value: new THREE.Color(0x06b6d4) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.15
                 + cos(pos.y * 4.0 + uTime * 1.5) * 0.1;
      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform float uTime;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      float mixValue = smoothstep(-0.2, 0.2, vWave) * 0.7 + pulse * 0.3;
      vec3 color = mix(uColorA, uColorB, mixValue);

      float glow = 0.15 / (abs(vWave) + 0.08);
      color += glow * 0.15;

      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Center object with shader effect
const shaderSphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.5, 128, 128),
  shaderMaterial
);
shaderSphere.position.set(0, 1, 0);
scene.add(shaderSphere);

// Standard material objects
const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xf59e0b,
    roughness: 0.4,
    metalness: 0.6
  })
);
box.position.set(-3.5, 0, 0);
scene.add(box);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.3, 128, 24),
  new THREE.MeshStandardMaterial({
    color: 0x10b981,
    roughness: 0.3,
    metalness: 0.8
  })
);
torus.position.set(3.5, 1, -1);
scene.add(torus);

// Optional grid helper
const grid = new THREE.GridHelper(30, 30, 0x334155, 0x1f2937);
grid.position.y = -1.49;
scene.add(grid);

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate objects
  shaderSphere.rotation.y += 0.003;
  box.rotation.x += 0.01;
  box.rotation.y += 0.015;
  torus.rotation.x += 0.008;
  torus.rotation.y += 0.01;

  // Animate dynamic point light
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;

  controls.update();
  renderer.render(scene, camera);
}

animate();
```

