            vUv = uv;
            vec3 pos = position;

            float wave = sin(pos.y * 8.0 + uTime * 2.0) * 0.15;
            pos += normal * wave;
            vWave = wave;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
