        fragmentShader: `
          uniform vec3 uColorA;
          uniform vec3 uColorB;
          varying vec2 vUv;
          varying float vWave;

          void main() {
            float mixValue = vUv.y + vWave * 2.0;
            vec3 color = mix(uColorA, uColorB, mixValue);
            gl_FragColor = vec4(color, 1.0);
          }
        `
      });

      // Main object
      sphere = new THREE.Mesh(
        new THREE.SphereGeometry(1.2, 128, 128),
        shaderMaterial
      );
      sphere.position.set(0, 1.5, 0);
      sphere.castShadow = true;
      sphere.receiveShadow = true;
      scene.add(sphere);

      // Additional objects
      const boxMat = new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.4,
        metalness: 0.6
      });

      for (let i = 0; i < 6; i++) {
        const box = new THREE.Mesh(
          new THREE.BoxGeometry(1, 1, 1),
          boxMat
        );
        box.position.set(
          Math.cos((i / 6) * Math.PI * 2) * 4,
          0.5,
          Math.sin((i / 6) * Math.PI * 2) * 4
        );
        box.castShadow = true;
        box.receiveShadow = true;
        scene.add(box);
      }

      // Grid helper
      const grid = new THREE.GridHelper(30, 30, 0x444444, 0x222222);
      scene.add(grid);

      window.addEventListener('resize', onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = elapsed;

      sphere.rotation.y += 0.005;

      // Animate point light in a circular path
      pointLight.position.x = Math.cos(elapsed) * 3;
      pointLight.position.z = Math.sin(elapsed) * 3;
      pointLight.position.y = 2 + Math.sin(elapsed * 2.0) * 0.75;

      controls.update();
      renderer.render(scene, camera);
    }
  </script>
