## `main.js`

```javascript
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 50);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 3, 8);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Clock
const clock = new THREE.Clock();

// Ambient Light
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

// Directional Light
const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
scene.add(dirLight);

// Point Light with dynamic movement
const pointLight = new THREE.PointLight(0x44aaff, 2, 30);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Light helper spheres
const pointLightMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.1, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(pointLightMesh);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(50, 50),
  new THREE.MeshStandardMaterial({
    color: 0x1a1f2b,
    roughness: 0.9,
    metalness: 0.1
  })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Standard material object
const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 128, 32),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    roughness: 0.35,
    metalness: 0.7
  })
);
torusKnot.position.set(-2.2, 1.5, 0);
torusKnot.castShadow = true;
torusKnot.receiveShadow = true;
scene.add(torusKnot);

// Shader material object
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00d4ff) },
  uColorB: { value: new THREE.Color(0xff00aa) }
};

const vertexShader = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vWave;

  void main() {
    vUv = uv;

    vec3 pos = position;
    float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
    wave += cos(pos.x * 3.0 + uTime * 1.5) * 0.1;
    pos += normal * wave;

    vWave = wave;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;

  varying vec2 vUv;
  varying float vWave;

  void main() {
    float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
    vec3 color = mix(uColorA, uColorB, vUv.x + vWave * 2.0 + pulse * 0.2);
    gl_FragColor = vec4(color, 1.0);
  }
`;

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader,
  fragmentShader
});

const shaderSphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 128, 128),
  shaderMaterial
);
shaderSphere.position.set(2.2, 1.5, 0);
shaderSphere.castShadow = true;
shaderSphere.receiveShadow = true;
scene.add(shaderSphere);

// Extra geometry for scene richness
const boxGroup = new THREE.Group();
scene.add(boxGroup);

for (let i = 0; i < 20; i++) {
  const box = new THREE.Mesh(
    new THREE.BoxGeometry(0.6, 0.6, 0.6),
    new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(i / 20, 0.7, 0.5),
      roughness: 0.5,
      metalness: 0.3
    })
  );

  const angle = (i / 20) * Math.PI * 2;
  const radius = 6 + Math.random() * 2;
  box.position.set(Math.cos(angle) * radius, 0.3, Math.sin(angle) * radius);
  box.rotation.set(Math.random(), Math.random(), Math.random());
  box.castShadow = true;
  box.receiveShadow = true;
  boxGroup.add(box);
}

// Optional grid helper
const grid = new THREE.GridHelper(50, 50, 0x444444, 0x222222);
scene.add(grid);

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsed;

  // Animate objects
  torusKnot.rotation.x += 0.01;
  torusKnot.rotation.y += 0.015;

  shaderSphere.rotation.y += 0.01;

  boxGroup.children.forEach((box, i) => {
    box.rotation.x += 0.005 + i * 0.0002;
    box.rotation.y += 0.007 + i * 0.0002;
  });

  // Dynamic point light movement
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4;
  pointLightMesh.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

