  sphere.position.y = 1.2 + Math.sin(elapsed * 2.0) * 0.3;

  torusKnot.rotation.x = elapsed * 0.4;
  torusKnot.rotation.y = elapsed * 0.7;
  shaderUniforms.uTime.value = elapsed;

  // Dynamic lighting animation
  pointLight.position.x = Math.sin(elapsed) * 4.0;
  pointLight.position.z = Math.cos(elapsed) * 4.0;
  pointLight.intensity = 20 + Math.sin(elapsed * 3.0) * 10.0;

  directionalLight.position.x = Math.sin(elapsed * 0.5) * 8.0;
  directionalLight.position.z = Math.cos(elapsed * 0.5) * 8.0;

  composer.render();
}

animate();

// Resize
