scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 20, 80);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  200
);
camera.position.set(8, 6, 12);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 2, 0);

// Ambient light
const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(8, 12, 6);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -20;
dirLight.shadow.camera.right = 20;
dirLight.shadow.camera.top = 20;
dirLight.shadow.camera.bottom = -20;
scene.add(dirLight);

// Dynamic point light
const pointLight = new THREE.PointLight(0x44aaff, 30, 50, 2);
pointLight.position.set(0, 4, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(100, 100);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x1a1f2b,
  roughness: 0.9,
  metalness: 0.1
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Standard objects
const box = new THREE.Mesh(
  new THREE.BoxGeometry(2, 2, 2),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    roughness: 0.35,
    metalness: 0.4
  })
);
box.position.set(-3, 1, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0x66ccff,
    roughness: 0.2,
    metalness: 0.8
  })
);
sphere.position.set(3, 1.2, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);

// Shader-driven object
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x7c3aed) },
  uColorB: { value: new THREE.Color(0x06b6d4) }
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;
      vec3 pos = position;

      float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.15
                 + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;

      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      vec3 color = mix(uColorA, uColorB, vUv.x + pulse * 0.25 + vWave);
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1.2, 0.35, 256, 32),
  shaderMaterial
);
torusKnot.position.set(0, 2.5, -4);
torusKnot.castShadow = true;
torusKnot.receiveShadow = true;
scene.add(torusKnot);

// Small emissive marker for point light
const lightMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.15, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(lightMarker);

// Optional grid helper
const grid = new THREE.GridHelper(40, 40, 0x334155, 0x1e293b);
scene.add(grid);

// Clock
const clock = new THREE.Clock();

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsed;

  // Animate objects
  box.rotation.x += 0.01;
  box.rotation.y += 0.015;

  sphere.position.y = 1.2 + Math.sin(elapsed * 2.0) * 0.3;
  sphere.rotation.y += 0.01;

  torusKnot.rotation.x = elapsed * 0.4;
  torusKnot.rotation.y = elapsed * 0.7;

  // Dynamic light motion
