      vec3 color = mix(uColorA, uColorB, vUv.y + vWave * 2.0 + pulse * 0.2);

      float glow = 0.7 + abs(vWave) * 2.0;
      gl_FragColor = vec4(color * glow, 1.0);
    }
  `,
});

const torusKnotGeo = new THREE.TorusKnotGeometry(1, 0.35, 256, 32);
const shaderMesh = new THREE.Mesh(torusKnotGeo, shaderMat);
shaderMesh.position.set(0, 2.2, 0);
shaderMesh.castShadow = true;
shaderMesh.receiveShadow = true;
scene.add(shaderMesh);

// Accent light helpers
const pointLightVisual = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(pointLightVisual);

// Optional grid
const grid = new THREE.GridHelper(50, 50, 0x334155, 0x1e293b);
grid.position.y = 0.001;
scene.add(grid);

// Clock
const clock = new THREE.Clock();

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate objects
  box.rotation.x = elapsed * 0.6;
  box.rotation.y = elapsed * 0.9;

  sphere.position.y = 1 + Math.sin(elapsed * 2.0) * 0.3;
  sphere.rotation.y = elapsed * 0.5;

  shaderUniforms.uTime.value = elapsed;
  shaderMesh.rotation.x = elapsed * 0.25;
  shaderMesh.rotation.y = elapsed * 0.5;

  // Animate point light in orbit
  pointLight.position.x = Math.cos(elapsed) * 4.0;
  pointLight.position.z = Math.sin(elapsed) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;

  pointLightVisual.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
