import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const canvas = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.outputColorSpace = THREE.SRGBColorSpace;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 10);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
directionalLight.position.set(5, 10, 5);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 2048;
directionalLight.shadow.mapSize.height = 2048;
directionalLight.shadow.camera.near = 0.5;
directionalLight.shadow.camera.far = 50;
directionalLight.shadow.camera.left = -15;
directionalLight.shadow.camera.right = 15;
directionalLight.shadow.camera.top = 15;
directionalLight.shadow.camera.bottom = -15;
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x44aaff, 2, 20);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Ground
const groundGeometry = new THREE.PlaneGeometry(50, 50);
const groundMaterial = new THREE.MeshStandardMaterial({
  color: 0x1a1f2b,
  roughness: 0.9,
  metalness: 0.1
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Shader material
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00d4ff) },
  uColorB: { value: new THREE.Color(0xff00aa) }
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;
    uniform float uTime;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;
      pos += normal * sin(uTime * 2.0 + position.y * 4.0) * 0.15;

      vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPosition.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPosition;
    }
  `,
  fragmentShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    void main() {
      float wave = sin(vUv.y * 10.0 - uTime * 3.0) * 0.5 + 0.5;
      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
      vec3 color = mix(uColorA, uColorB, wave);
      color += fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Main object
const sphereGeometry = new THREE.SphereGeometry(1.5, 128, 128);
const sphere = new THREE.Mesh(sphereGeometry, shaderMaterial);
sphere.position.set(0, 2, 0);
sphere.castShadow = true;
scene.add(sphere);

// Secondary object
const boxGeometry = new THREE.BoxGeometry(1.5, 1.5, 1.5);
const boxMaterial = new THREE.MeshStandardMaterial({
  color: 0xffaa00,
  roughness: 0.35,
  metalness: 0.6
});
const box = new THREE.Mesh(boxGeometry, boxMaterial);
box.position.set(-3, 1, 2);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

// Tertiary object
const torusGeometry = new THREE.TorusKnotGeometry(1, 0.3, 128, 16);
const torusMaterial = new THREE.MeshStandardMaterial({
  color: 0x66ff99,
  roughness: 0.4,
  metalness: 0.7
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(3, 2, -1);
torus.castShadow = true;
torus.receiveShadow = true;
scene.add(torus);

// Optional helpers
const gridHelper = new THREE.GridHelper(50, 50, 0x334466, 0x223344);
scene.add(gridHelper);

// Clock
const clock = new THREE.Clock();

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsedTime = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsedTime;

  sphere.rotation.y += 0.005;
  box.rotation.x += 0.01;
  box.rotation.y += 0.015;
  torus.rotation.x += 0.01;
  torus.rotation.z += 0.01;

  pointLight.position.x = Math.sin(elapsedTime) * 4.0;
  pointLight.position.z = Math.cos(elapsedTime) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsedTime * 2.0) * 0.5;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
