Below is a minimal working example of a real-time 3D scene viewer using **Three.js** with:

- a **3D scene**
- **orbit camera controls**
- **dynamic lighting**
- a **custom shader effect**
- a simple **animation loop**

You can save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x101018);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2, 6);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Dynamic lights
    const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x66ccff, 2, 20);
    pointLight.position.set(3, 3, 3);
    scene.add(pointLight);

    const pointLightHelper = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x66ccff })
    );
    scene.add(pointLightHelper);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Shader-driven object
    const uniforms = {
      uTime: { value: 0.0 },
      uLightPos: { value: new THREE.Vector3() }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        uniform float uTime;

        void main() {
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position;
          pos += normal * 0.15 * sin(uTime * 2.0 + position.y * 6.0);

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        uniform vec3 uLightPos;
        uniform float uTime;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diffuse = max(dot(normal, lightDir), 0.0);

          vec3 baseA = vec3(0.2, 0.4, 1.0);
          vec3 baseB = vec3(1.0, 0.2, 0.7);
          float pulse = 0.5 + 0.5 * sin(uTime + vWorldPosition.y * 4.0);

          vec3 baseColor = mix(baseA, baseB, pulse);
          vec3 color = baseColor * (0.2 + diffuse * 1.2);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 128, 128),
      shaderMaterial
    );
    scene.add(sphere);

    // Extra object for scene depth
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0xffaa33, metalness: 0.2, roughness: 0.4 })
    );
    box.position.set(-2.5, -0.5, 0);
    scene.add(box);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      uniforms.uTime.value = t;

      // Animate light in a circle
      pointLight.position.set(
        Math.cos(t) * 3.5,
        2.0 + Math.sin(t * 1.5),
        Math.sin(t) * 3.5
      );
      pointLightHelper.position.copy(pointLight.position);
      uniforms.uLightPos.value.copy(pointLight.position);

      sphere.rotation.y += 0.005;
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```

