    const pointLight = new THREE.PointLight(0x66ccff, 2, 20);
    pointLight.position.set(3, 3, 3);
    scene.add(pointLight);

    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.15);
    scene.add(pointLightHelper);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({
        color: 0x222222,
        metalness: 0.2,
        roughness: 0.8
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Shader material
    const uniforms = {
      uTime: { value: 0.0 },
      uLightPos: { value: pointLight.position.clone() }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        uniform float uTime;

        void main() {
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position;
          pos += normal * sin(uTime * 2.0 + position.y * 6.0) * 0.12;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        uniform vec3 uLightPos;
        uniform float uTime;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diffuse = max(dot(normal, lightDir), 0.0);

          vec3 baseColor = vec3(
            0.4 + 0.4 * sin(uTime + vWorldPosition.x * 2.0),
            0.5 + 0.4 * sin(uTime * 1.3 + vWorldPosition.y * 2.0),
            0.8 + 0.2 * sin(uTime + vWorldPosition.z * 2.0)
          );

          vec3 color = baseColor * (0.2 + diffuse * 1.2);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 128, 128),
      shaderMaterial
    );
    scene.add(sphere);

    // Extra object for scene depth
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        metalness: 0.5,
        roughness: 0.3
      })
    );
    box.position.set(-2.5, -0.5, 0);
    scene.add(box);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      uniforms.uTime.value = t;

      // Animate light
      pointLight.position.x = Math.cos(t) * 3.0;
      pointLight.position.z = Math.sin(t) * 3.0;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 1.0;
      uniforms.uLightPos.value.copy(pointLight.position);

      // Animate objects
      sphere.rotation.y += 0.003;
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
