            vec3(0.2, 0.3, 0.8),
            vec3(0.9, 0.2, 0.8),
            pulse
          );

          vec3 color = baseColor * (0.2 + diff * 1.2);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const object = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 128, 32),
      shaderMaterial
    );
    scene.add(object);

    // Optional extra object for lighting contrast
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 32, 32),
      new THREE.MeshStandardMaterial({
        color: 0xffaa33,
        roughness: 0.4,
        metalness: 0.3
      })
    );
    sphere.position.set(-2, 0, 0);
    scene.add(sphere);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate light
      pointLight.position.x = Math.cos(t) * 3.0;
      pointLight.position.z = Math.sin(t) * 3.0;
      pointLight.position.y = 1.5 + Math.sin(t * 2.0);

      pointLightHelper.position.copy(pointLight.position);

      // Animate objects
      object.rotation.y += 0.01;
      sphere.position.y = Math.sin(t * 2.0) * 0.5;

      // Update shader uniforms
      shaderMaterial.uniforms.uTime.value = t;
      shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
