      mesh.rotation.y += 0.01;
      mesh.rotation.x = Math.sin(t * 0.7) * 0.2;

      sphere.position.y = -0.4 + Math.sin(t * 2.0) * 0.25;

      controls.update();
      renderer.render(scene, camera);
    }

