  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x101018);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2, 6);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Ambient + moving point light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x66ccff, 2.5, 50);
    pointLight.position.set(3, 3, 3);
    scene.add(pointLight);

    const lightHelper = new THREE.PointLightHelper(pointLight, 0.15);
    scene.add(lightHelper);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({
        color: 0x222222,
        metalness: 0.2,
        roughness: 0.8
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Shader-driven sphere
    const uniforms = {
      uTime: { value: 0 },
      uLightPos: { value: new THREE.Vector3() }
    };

    const sphereMaterial = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        uniform float uTime;

        void main() {
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position + normal * 0.12 * sin(uTime * 2.0 + position.y * 8.0);
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        uniform vec3 uLightPos;
        uniform float uTime;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diffuse = max(dot(normal, lightDir), 0.0);

          vec3 baseColor = vec3(
            0.4 + 0.4 * sin(uTime + vWorldPosition.x * 2.0),
            0.5 + 0.4 * sin(uTime * 1.2 + vWorldPosition.y * 3.0),
            0.8
          );

          vec3 color = baseColor * (0.2 + diffuse * 1.2);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 128, 128),
      sphereMaterial
    );
    scene.add(sphere);

