    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        metalness: 0.5,
        roughness: 0.3
      })
    );
    box.position.set(-2.5, -0.5, 0);
    scene.add(box);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Move light in a circle
      pointLight.position.x = Math.cos(t) * 3.5;
      pointLight.position.z = Math.sin(t) * 3.5;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 1.0;

      uniforms.uTime.value = t;
      uniforms.uLightPos.value.copy(pointLight.position);

      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

