      uniforms,
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        varying vec2 vUv;
        uniform float uTime;

        void main() {
          vUv = uv;
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position + normal * 0.08 * sin(uTime * 2.0 + position.y * 8.0);
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
