          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diff = max(dot(normal, lightDir), 0.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vUv.y * 10.0);
          vec3 baseColor = mix(vec3(0.2, 0.3, 0.8), vec3(0.8, 0.2, 0.9), pulse);

