    );
    scene.add(mesh);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      uniforms.uTime.value = t;

      // Animate object
      mesh.rotation.y = t * 0.6;
