#include <vector>
#include <memory>
#include <cmath>

struct Vec3 {
    float x{}, y{}, z{};

    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }

    Vec3& operator+=(const Vec3& o) {
        x += o.x; y += o.y; z += o.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass{1.0f};
    bool isStatic{false};

    void ApplyForce(const Vec3& force) {
        if (!isStatic) forceAccum += force;
    }

    void Integrate(float dt) {
        if (isStatic || mass <= 0.0f) return;

        Vec3 acceleration = forceAccum * (1.0f / mass);
        velocity += acceleration * dt;
        position += velocity * dt;
        forceAccum = {0, 0, 0};
    }
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void StepSimulation(float dt) = 0;
    virtual RigidBody* CreateRigidBody(const Vec3& pos, float mass, bool isStatic) = 0;
};

class CustomPhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {
        gravity = {0.0f, -9.81f, 0.0f};
    }

    void Shutdown() override {
        bodies.clear();
    }

    void StepSimulation(float dt) override {
        for (auto& body : bodies) {
            if (!body->isStatic) {
                body->ApplyForce(gravity * body->mass);
            }
        }

        for (auto& body : bodies) {
            body->Integrate(dt);
            ResolveGroundCollision(*body);
        }
    }

    RigidBody* CreateRigidBody(const Vec3& pos, float mass, bool isStatic) override {
        auto body = std::make_unique<RigidBody>();
        body->position = pos;
        body->mass = mass;
        body->isStatic = isStatic;
        bodies.push_back(std::move(body));
        return bodies.back().get();
    }

private:
    std::vector<std::unique_ptr<RigidBody>> bodies;
    Vec3 gravity;

    void ResolveGroundCollision(RigidBody& body) {
        const float groundY = 0.0f;
        const float restitution = 0.5f;

        if (body.position.y < groundY) {
            body.position.y = groundY;
            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * restitution;
            }
        }
    }
};
