}

void SimplePhysicsPlugin::ApplyForce(BodyHandle handle, const Vec3& force) {
    auto it = bodies_.find(handle);
    if (it == bodies_.end()) return;
    it->second.accumulatedForce = Add(it->second.accumulatedForce, force);
}

void SimplePhysicsPlugin::StepSimulation(float dt) {
    for (auto& [handle, body] : bodies_) {
        if (body.desc.isStatic || body.desc.mass <= 0.0f) continue;

        Vec3 totalForce = Add(body.accumulatedForce, Scale(gravity_, body.desc.mass));
        Vec3 accel = Scale(totalForce, 1.0f / body.desc.mass);

        body.desc.velocity = Add(body.desc.velocity, Scale(accel, dt));
        body.desc.position = Add(body.desc.position, Scale(body.desc.velocity, dt));

        body.accumulatedForce = {};
    }
}

Vec3 SimplePhysicsPlugin::GetBodyPosition(BodyHandle handle) const {
    auto it = bodies_.find(handle);
    if (it == bodies_.end()) return {};
    return it->second.desc.position;
