## `src/PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
        , m_groundHeight(0.0f)
        , m_nextBodyId(1)
    {
    }

    void PhysicsWorld::SetGravity(const Vec3& gravity)
    {
        m_gravity = gravity;
    }

    const Vec3& PhysicsWorld::GetGravity() const
    {
        return m_gravity;
    }

    BodyId PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
    {
        BodyId id = m_nextBodyId++;
        m_bodies[id] = std::make_unique<RigidBody>(id, desc);
        return id;
    }

    bool PhysicsWorld::RemoveBody(BodyId id)
    {
        return m_bodies.erase(id) > 0;
    }

    RigidBody* PhysicsWorld::GetBody(BodyId id)
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    const RigidBody* PhysicsWorld::GetBody(BodyId id) const
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    void PhysicsWorld::StepSimulation(float dt)
    {
        for (auto& pair : m_bodies)
        {
            RigidBody& body = *pair.second;
            body.Integrate(dt, m_gravity);
            SolveGroundCollisions(body);
        }
    }

    void PhysicsWorld::SolveGroundCollisions(RigidBody& body)
    {
        if (body.GetType() != BodyType::Dynamic)
        {
            return;
        }

        Vec3 pos = body.GetPosition();
        Vec3 vel = body.GetVelocity();
        float radius = body.GetRadius();

        float minY = m_groundHeight + radius;
        if (pos.y < minY)
        {
            pos.y = minY;

            if (vel.y < 0.0f)
            {
                vel.y = -vel.y * body.GetRestitution();
            }

            body.SetPosition(pos);
            body.SetVelocity(vel);
        }
    }
}
