#include <iostream>
#include "IPhysicsPlugin.h"

int main()
{
    auto plugin = CustomPhysics::CreatePhysicsPlugin();
    if (!plugin->Initialize())
    {
        std::cerr << "Failed to initialize physics plugin\n";
        return 1;
    }

    CustomPhysics::PhysicsWorld* world = plugin->GetWorld();

    CustomPhysics::RigidBodyDesc bodyDesc;
    bodyDesc.type = CustomPhysics::BodyType::Dynamic;
    bodyDesc.position = CustomPhysics::Vec3(0.0f, 10.0f, 0.0f);
    bodyDesc.mass = 1.0f;
    bodyDesc.restitution = 0.5f;
    bodyDesc.radius = 0.5f;

    CustomPhysics::BodyId bodyId = world->CreateBody(bodyDesc);

    constexpr float dt = 1.0f / 60.0f;
    for (int i = 0; i < 180; ++i)
    {
        plugin->Tick(dt);

        const CustomPhysics::RigidBody* body = world->GetBody(bodyId);
        if (body)
        {
            const auto& p = body->GetPosition();
            std::cout << "Frame " << i << ": Position = ("
                      << p.x << ", " << p.y << ", " << p.z << ")\n";
        }
    }

    plugin->Shutdown();
    return 0;
}
