#include "PhysicsBody.h"

namespace CustomPhysics
{
    PhysicsBody::PhysicsBody(BodyHandle handle, const RigidBodyDesc& desc)
        : m_handle(handle)
        , m_type(desc.type)
        , m_transform(desc.initialTransform)
        , m_shape(desc.shape)
        , m_mass(desc.mass > 0.0f ? desc.mass : 1.0f)
        , m_enableGravity(desc.enableGravity)
    {
    }

    void PhysicsBody::ApplyForce(const Vec3& force)
    {
        if (m_type != BodyType::Dynamic)
            return;

        m_accumulatedForce += force;
    }

    void PhysicsBody::Integrate(float deltaTime, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic)
            return;

        Vec3 totalAcceleration = m_accumulatedForce * (1.0f / m_mass);

        if (m_enableGravity)
        {
            totalAcceleration += gravity;
        }

        m_linearVelocity += totalAcceleration * deltaTime;
        m_transform.position += m_linearVelocity * deltaTime;

        m_accumulatedForce = Vec3(0, 0, 0);
    }
}
