        {
            m_worlds.clear();
            m_initialized = false;
        }

        std::shared_ptr<PhysicsWorld> CreateWorld(const PhysicsWorldDesc& desc) override
        {
            auto world = std::make_shared<PhysicsWorld>(desc);
            m_worlds.push_back(world);
            return world;
