        gWorld = gPhysicsPlugin->CreateWorld(worldDesc);
    }
}

void ShutdownPhysics()
{
    if (gPhysicsPlugin)
    {
        gPhysicsPlugin->DestroyWorld(gWorld);
        gWorld.reset();

        gPhysicsPlugin->Shutdown();
        DestroyPhysicsPlugin(gPhysicsPlugin);
        gPhysicsPlugin = nullptr;
    }
}

void TickPhysics(float deltaTime)
{
    if (gWorld)
    {
        gWorld->StepSimulation(deltaTime);
    }
}
```

