# 12. Optional improvement: add substepping now

A very simple improvement inside `Simulate`:

```cpp
void UCustomPhysicsComponent::Simulate(float DeltaTime)
{
    if (Mass <= KINDA_SMALL_NUMBER || DeltaTime <= 0.0f)
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    const float MaxStep = 1.0f / 60.0f;
    int32 NumSteps = FMath::Clamp(FMath::CeilToInt(DeltaTime / MaxStep), 1, 8);
    float StepTime = DeltaTime / NumSteps;

    for (int32 i = 0; i < NumSteps; ++i)
    {
        FVector Position = GetComponentLocation();

        FVector Acceleration = (AccumulatedForce / Mass) + Gravity;
        Velocity += Acceleration * StepTime;
        Velocity *= FMath::Clamp(1.0f - LinearDamping * StepTime, 0.0f, 1.0f);

        Position += Velocity * StepTime;

        if (bEnableGroundCollision)
        {
            ResolveGroundCollision(Position);
        }

        SetWorldLocation(Position);
    }

    AccumulatedForce = FVector::ZeroVector;
}
```

A better version would cache position once and write back once at the end.

