```cpp
#include "CustomPhysicsWorldSubsystem.h"
#include "CustomPhysicsBodyComponent.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

UCustomPhysicsWorldSubsystem::UCustomPhysicsWorldSubsystem()
{
}

void UCustomPhysicsWorldSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
    Super::Initialize(Collection);
    UE_LOG(LogTemp, Log, TEXT("CustomPhysicsWorldSubsystem initialized"));
}

void UCustomPhysicsWorldSubsystem::Deinitialize()
{
    Bodies.Empty();
    UE_LOG(LogTemp, Log, TEXT("CustomPhysicsWorldSubsystem deinitialized"));
    Super::Deinitialize();
}

void UCustomPhysicsWorldSubsystem::RegisterBody(UCustomPhysicsBodyComponent* Body)
{
    if (Body)
    {
        Bodies.AddUnique(Body);
    }
}

void UCustomPhysicsWorldSubsystem::UnregisterBody(UCustomPhysicsBodyComponent* Body)
{
    Bodies.Remove(Body);
}

bool UCustomPhysicsWorldSubsystem::IsTickable() const
{
    return true;
}

TStatId UCustomPhysicsWorldSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsWorldSubsystem, STATGROUP_Tickables);
}

void UCustomPhysicsWorldSubsystem::Tick(float DeltaTime)
{
    for (int32 i = Bodies.Num() - 1; i >= 0; --i)
    {
        UCustomPhysicsBodyComponent* Body = Bodies[i];
        if (!IsValid(Body) || !IsValid(Body->GetOwner()))
        {
            Bodies.RemoveAt(i);
            continue;
        }

        if (!Body->bSimulate)
        {
            continue;
        }

        SimulateBody(Body, DeltaTime);
    }
}

void UCustomPhysicsWorldSubsystem::SimulateBody(UCustomPhysicsBodyComponent* Body, float DeltaTime)
{
    AActor* Owner = Body->GetOwner();
    if (!Owner)
    {
        return;
    }

    const float SafeMass = FMath::Max(Body->Mass, 0.001f);

    FVector TotalForce = Body->AccumulatedForce;
    TotalForce += Gravity * SafeMass;

    FVector Acceleration = TotalForce / SafeMass;
    Body->Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - Body->LinearDamping * DeltaTime, 0.0f, 1.0f);
    Body->Velocity *= DampingFactor;

    FVector NewLocation = Owner->GetActorLocation() + Body->Velocity * DeltaTime;

    // Simple collision with ground plane at Z = 0
    if (NewLocation.Z < 0.0f)
    {
        NewLocation.Z = 0.0f;

        if (Body->Velocity.Z < 0.0f)
        {
            Body->Velocity.Z = -Body->Velocity.Z * Body->Restitution;
        }
    }

    Owner->SetActorLocation(NewLocation);
    Body->ClearForces();
}
```

