## `PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"
#include <atomic>

namespace CustomPhysics
{
    namespace
    {
        std::atomic<uint32_t> GBodyIdCounter { 1 };
    }

    uint32_t PhysicsBody::NextId()
    {
        return GBodyIdCounter.fetch_add(1);
    }

    PhysicsBody::PhysicsBody(const PhysicsBodyDesc& desc)
        : id(NextId())
        , type(desc.type)
        , transform(desc.transform)
        , linearVelocity(desc.linearVelocity)
        , mass(desc.mass <= 0.0f ? 1.0f : desc.mass)
        , enableGravity(desc.enableGravity)
        , shape(desc.shape)
    {
    }

    void PhysicsBody::AddForce(const Vec3& force)
    {
        if (type != BodyType::Dynamic)
        {
            return;
        }

        accumulatedForce += force;
    }

    void PhysicsBody::ClearForces()
    {
        accumulatedForce = Vec3(0.0f, 0.0f, 0.0f);
    }

    void PhysicsBody::Integrate(float deltaTime, const Vec3& gravity)
    {
        if (type != BodyType::Dynamic)
        {
            return;
        }

        Vec3 acceleration = accumulatedForce * (1.0f / mass);

        if (enableGravity)
        {
            acceleration += gravity;
        }

        linearVelocity += acceleration * deltaTime;
        transform.position += linearVelocity * deltaTime;

        ClearForces();
    }
}
```

