## `PhysicsScene.cpp`

```cpp
#include "PhysicsScene.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsScene::PhysicsScene()
    {
    }

    std::shared_ptr<PhysicsBody> PhysicsScene::CreateBody(const PhysicsBodyDesc& desc)
    {
        auto body = std::make_shared<PhysicsBody>(desc);
        bodies.push_back(body);
        return body;
    }

    void PhysicsScene::RemoveBody(uint32_t bodyId)
    {
        bodies.erase(
            std::remove_if(
                bodies.begin(),
                bodies.end(),
                [bodyId](const std::shared_ptr<PhysicsBody>& body)
                {
                    return body->GetId() == bodyId;
                }),
            bodies.end());
    }

    void PhysicsScene::Simulate(float deltaTime)
    {
        for (auto& body : bodies)
        {
            body->Integrate(deltaTime, gravity);
        }

        ResolveSimpleCollisions();
    }

    void PhysicsScene::ResolveSimpleCollisions()
    {
        for (auto& body : bodies)
        {
            if (body->GetType() != BodyType::Dynamic)
            {
                continue;
            }

            Transform transform = body->GetTransform();
            Vec3 velocity = body->GetLinearVelocity();

            float floorHeight = 0.0f;

            if (auto shape = body->GetShape())
            {
                if (shape->GetType() == ShapeType::Sphere)
                {
                    auto sphere = std::static_pointer_cast<SphereShape>(shape);
                    float minZ = transform.position.z - sphere->radius;

                    if (minZ < floorHeight)
                    {
                        transform.position.z = floorHeight + sphere->radius;

                        if (velocity.z < 0.0f)
                        {
                            velocity.z = 0.0f;
                        }

                        body->SetTransform(transform);
                        body->SetLinearVelocity(velocity);
                    }
                }
                else if (shape->GetType() == ShapeType::Box)
                {
                    auto box = std::static_pointer_cast<BoxShape>(shape);
                    float minZ = transform.position.z - box->halfExtents.z;

                    if (minZ < floorHeight)
                    {
                        transform.position.z = floorHeight + box->halfExtents.z;

                        if (velocity.z < 0.0f)
                        {
                            velocity.z = 0.0f;
                        }

                        body->SetTransform(transform);
                        body->SetLinearVelocity(velocity);
                    }
                }
            }
        }
    }
}
