## `PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"

namespace CustomPhysics
{
    PhysicsBody::PhysicsBody(BodyId id, const BodyDesc& desc)
        : m_id(id)
        , m_type(desc.type)
        , m_transform(desc.transform)
        , m_mass(desc.mass)
        , m_restitution(desc.restitution)
        , m_friction(desc.friction)
        , m_enableGravity(desc.enableGravity)
    {
        if (m_type != BodyType::Dynamic || m_mass <= 0.0f)
        {
            m_mass = 0.0f;
            m_invMass = 0.0f;
        }
        else
        {
            m_invMass = 1.0f / m_mass;
        }
    }

    void PhysicsBody::AddForce(const Vec3& force)
    {
        if (m_type == BodyType::Dynamic)
        {
            m_accumulatedForce += force;
        }
    }

    void PhysicsBody::ClearForces()
    {
        m_accumulatedForce = Vec3(0, 0, 0);
    }

    void PhysicsBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic || m_invMass <= 0.0f)
            return;

        Vec3 totalAcceleration = m_accumulatedForce * m_invMass;
        if (m_enableGravity)
        {
            totalAcceleration += gravity;
        }

        m_linearVelocity += totalAcceleration * dt;
        m_transform.position += m_linearVelocity * dt;

        ClearForces();
    }
}
