## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld(const WorldDesc& desc)
        : m_gravity(desc.gravity)
        , m_fixedTimeStep(desc.fixedTimeStep)
        , m_maxSubSteps(desc.maxSubSteps)
    {
    }

    BodyId PhysicsWorld::CreateBody(const BodyDesc& desc)
    {
        BodyId id = m_nextBodyId++;
        m_bodies[id] = std::make_unique<PhysicsBody>(id, desc);
        return id;
    }

    void PhysicsWorld::DestroyBody(BodyId id)
    {
        m_bodies.erase(id);
    }

    PhysicsBody* PhysicsWorld::GetBody(BodyId id)
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    const PhysicsBody* PhysicsWorld::GetBody(BodyId id) const
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    void PhysicsWorld::StepSimulation(float deltaTime)
    {
        m_accumulator += deltaTime;

        int subSteps = 0;
        while (m_accumulator >= m_fixedTimeStep && subSteps < m_maxSubSteps)
        {
            SimulateStep(m_fixedTimeStep);
            m_accumulator -= m_fixedTimeStep;
            ++subSteps;
        }

        if (subSteps == m_maxSubSteps && m_accumulator >= m_fixedTimeStep)
        {
            m_accumulator = 0.0f;
        }
    }

    void PhysicsWorld::SimulateStep(float dt)
    {
        for (auto& [id, bodyPtr] : m_bodies)
        {
            PhysicsBody& body = *bodyPtr;
            body.Integrate(dt, m_gravity);
            SolveGroundPlaneCollision(body);
        }
    }

    void PhysicsWorld::SolveGroundPlaneCollision(PhysicsBody& body)
    {
        if (body.GetType() != BodyType::Dynamic)
            return;

        Transform transform = body.GetTransform();
        Vec3 velocity = body.GetLinearVelocity();

        const float groundY = 0.0f;

        if (transform.position.y < groundY)
        {
            transform.position.y = groundY;

            if (velocity.y < 0.0f)
            {
                velocity.y = -velocity.y * body.GetRestitution();

                velocity.x *= (1.0f - body.GetFriction() * 0.1f);
                velocity.z *= (1.0f - body.GetFriction() * 0.1f);

                if (std::abs(velocity.y) < 0.05f)
                {
                    velocity.y = 0.0f;
                }
            }

            body.SetTransform(transform);
            body.SetLinearVelocity(velocity);
        }
    }
}
