## `PhysicsPlugin.cpp`

```cpp
#include "IPhysicsPlugin.h"
#include <vector>
#include <algorithm>

namespace CustomPhysics
{
    class PhysicsPlugin final : public IPhysicsPlugin
    {
    public:
        bool Initialize() override
        {
            m_initialized = true;
            return true;
        }

        void Shutdown() override
        {
            m_worlds.clear();
            m_initialized = false;
        }

        PhysicsWorld* CreateWorld(const WorldDesc& desc) override
        {
            if (!m_initialized)
                return nullptr;

            auto world = std::make_unique<PhysicsWorld>(desc);
            PhysicsWorld* rawPtr = world.get();
            m_worlds.push_back(std::move(world));
            return rawPtr;
        }

        void DestroyWorld(PhysicsWorld* world) override
        {
            auto it = std::remove_if(
                m_worlds.begin(),
                m_worlds.end(),
                [world](const std::unique_ptr<PhysicsWorld>& ptr)
                {
                    return ptr.get() == world;
                });

            m_worlds.erase(it, m_worlds.end());
        }

    private:
        bool m_initialized = false;
        std::vector<std::unique_ptr<PhysicsWorld>> m_worlds;
    };

    std::unique_ptr<IPhysicsPlugin> CreatePhysicsPlugin()
    {
        return std::make_unique<PhysicsPlugin>();
    }
}
