    WorldDesc worldDesc;
    PhysicsWorld* world = plugin->CreateWorld(worldDesc);

    BodyDesc bodyDesc;
    bodyDesc.type = BodyType::Dynamic;
    bodyDesc.transform.position = Vec3(0.0f, 10.0f, 0.0f);
    bodyDesc.mass = 1.0f;
    bodyDesc.restitution = 0.5f;

    BodyId bodyId = world->CreateBody(bodyDesc);

    for (int i = 0; i < 180; ++i)
    {
        world->StepSimulation(1.0f / 60.0f);

        const PhysicsBody* body = world->GetBody(bodyId);
        if (body)
        {
            const auto& pos = body->GetTransform().position;
            std::cout << "Frame " << i << ": (" << pos.x << ", " << pos.y << ", " << pos.z << ")\n";
        }
    }

    plugin->DestroyWorld(world);
    plugin->Shutdown();

    return 0;
}
