## Replace `TickComponent`

```cpp
void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bSimulate || FixedTimeStep <= 0.0f)
    {
        return;
    }

    TimeAccumulator += DeltaTime;

    int32 Steps = 0;
    while (TimeAccumulator >= FixedTimeStep && Steps < MaxSubsteps)
    {
        Integrate(FixedTimeStep);
        TimeAccumulator -= FixedTimeStep;
        ++Steps;
    }

    if (Steps == MaxSubsteps && TimeAccumulator >= FixedTimeStep)
    {
        TimeAccumulator = 0.0f;
    }
}
```

This is much more stable than integrating directly with variable frame time.

