void UCustomPhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

FVector UCustomPhysicsComponent::GetVelocity() const
{
    return Velocity;
}

void UCustomPhysicsComponent::Simulate(float DeltaTime)
{
    AActor* Owner = GetOwner();
    if (!Owner || Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    // F = ma => a = F / m
    FVector Acceleration = (AccumulatedForce / Mass) + Gravity;

    // Semi-implicit Euler integration
    Velocity += Acceleration * DeltaTime;

    // Damping
    Velocity *= FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);

    FVector CurrentLocation = Owner->GetActorLocation();
    FVector NewLocation = CurrentLocation + Velocity * DeltaTime;

    // Very simple ground collision
    if (bEnableGroundCollision && NewLocation.Z < GroundHeight)
    {
        NewLocation.Z = GroundHeight;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = 0.0f;
        }
    }

    Owner->SetActorLocation(NewLocation);

    // Clear forces after integration step
    AccumulatedForce = FVector::ZeroVector;
}
```

