## `Source/CustomPhysics/Private/SimplePhysicsComponent.cpp`

```cpp
#include "SimplePhysicsComponent.h"
#include "CustomPhysicsSubsystem.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

USimplePhysicsComponent::USimplePhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void USimplePhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsSubsystem>())
        {
            Subsystem->RegisterComponent(this);
        }
    }
}

void USimplePhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsSubsystem>())
        {
            Subsystem->UnregisterComponent(this);
        }
    }

    Super::EndPlay(EndPlayReason);
}

void USimplePhysicsComponent::AddImpulse(FVector Impulse)
{
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Velocity += Impulse / Mass;
    }
}

void USimplePhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

void USimplePhysicsComponent::SimulatePhysicsStep(float DeltaTime)
{
    if (!bSimulate || DeltaTime <= 0.0f)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!IsValid(Owner))
    {
        return;
    }

    // Apply gravity
    Velocity += Gravity * DeltaTime;

    // Apply simple damping
    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;

    // Simple ground-plane collision
    if (bEnableGroundCollision && NewLocation.Z < GroundHeight)
    {
        NewLocation.Z = GroundHeight;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Restitution;
        }
    }

    Owner->SetActorLocation(NewLocation);
}
```

