    virtual void Tick(float DeltaTime) override;
    virtual bool IsTickable() const override;

    void RegisterComponent(USimplePhysicsComponent* Component);
    void UnregisterComponent(USimplePhysicsComponent* Component);

protected:
    UPROPERTY(EditAnywhere, Category="Custom Physics")
    float FixedTimeStep = 1.0f / 60.0f;

    UPROPERTY(EditAnywhere, Category="Custom Physics")
    int32 MaxSubsteps = 4;

private:
    void SimulateStep(float StepTime);

    UPROPERTY()
    TArray<TObjectPtr<USimplePhysicsComponent>> Components;

    float Accumulator = 0.0f;
};
```

## Replace `CustomPhysicsSubsystem.cpp` with:

```cpp
#include "CustomPhysicsSubsystem.h"
#include "SimplePhysicsComponent.h"

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

bool UCustomPhysicsSubsystem::IsTickable() const
{
    return true;
}

void UCustomPhysicsSubsystem::RegisterComponent(USimplePhysicsComponent* Component)
{
    if (IsValid(Component))
    {
        Components.AddUnique(Component);
    }
}

void UCustomPhysicsSubsystem::UnregisterComponent(USimplePhysicsComponent* Component)
{
    Components.Remove(Component);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    Accumulator += DeltaTime;

    int32 Steps = 0;
    while (Accumulator >= FixedTimeStep && Steps < MaxSubsteps)
    {
        SimulateStep(FixedTimeStep);
        Accumulator -= FixedTimeStep;
        ++Steps;
    }

    if (Steps == MaxSubsteps && Accumulator >= FixedTimeStep)
    {
        Accumulator = 0.0f;
    }
}

void UCustomPhysicsSubsystem::SimulateStep(float StepTime)
{
    for (int32 Index = Components.Num() - 1; Index >= 0; --Index)
    {
        USimplePhysicsComponent* Component = Components[Index];

        if (!IsValid(Component))
        {
            Components.RemoveAtSwap(Index);
            continue;
        }

        Component->SimulatePhysicsStep(StepTime);
    }
}
```

This version is much better for stable simulation.

