## RigidBody.cpp

```cpp
#include "RigidBody.h"

FRigidBody::FRigidBody(float InMass)
    : Position(0.0f, 0.0f, 0.0f)
    , Velocity(0.0f, 0.0f, 0.0f)
    , AccumulatedForce(0.0f, 0.0f, 0.0f)
    , Mass(InMass)
    , bStatic(InMass <= 0.0f)
{
}

void FRigidBody::SetPosition(const FVector3& InPosition)
{
    Position = InPosition;
}

void FRigidBody::SetVelocity(const FVector3& InVelocity)
{
    Velocity = InVelocity;
}

void FRigidBody::AddForce(const FVector3& Force)
{
    if (!bStatic)
    {
        AccumulatedForce += Force;
    }
}

const FVector3& FRigidBody::GetPosition() const
{
    return Position;
}

const FVector3& FRigidBody::GetVelocity() const
{
    return Velocity;
}

float FRigidBody::GetMass() const
{
    return Mass;
}

bool FRigidBody::IsStatic() const
{
    return bStatic;
}

void FRigidBody::Integrate(float DeltaTime, const FVector3& Gravity)
{
    if (bStatic)
    {
        return;
    }

    const FVector3 GravityForce = Gravity * Mass;
    const FVector3 TotalForce = AccumulatedForce + GravityForce;
    const FVector3 Acceleration = TotalForce * (1.0f / Mass);

    Velocity += Acceleration * DeltaTime;
    Position += Velocity * DeltaTime;
}

void FRigidBody::ClearForces()
{
    AccumulatedForce = FVector3(0.0f, 0.0f, 0.0f);
}
```

