## PhysicsWorld.cpp

```cpp
#include "PhysicsWorld.h"

FPhysicsWorld::FPhysicsWorld()
    : Gravity(0.0f, 0.0f, -980.0f)
    , GroundHeight(0.0f)
    , Restitution(0.25f)
{
}

std::shared_ptr<FRigidBody> FPhysicsWorld::CreateRigidBody(float Mass)
{
    std::shared_ptr<FRigidBody> Body = std::make_shared<FRigidBody>(Mass);
    Bodies.push_back(Body);
    return Body;
}

void FPhysicsWorld::StepSimulation(float DeltaTime)
{
    for (auto& Body : Bodies)
    {
        Body->Integrate(DeltaTime, Gravity);
    }

    SolveCollisions();

    for (auto& Body : Bodies)
    {
        Body->ClearForces();
    }
}

void FPhysicsWorld::SetGravity(const FVector3& InGravity)
{
    Gravity = InGravity;
}

const FVector3& FPhysicsWorld::GetGravity() const
{
    return Gravity;
}

void FPhysicsWorld::SolveCollisions()
{
    for (auto& Body : Bodies)
    {
        if (Body->IsStatic())
        {
            continue;
        }

        FVector3 Position = Body->GetPosition();
        FVector3 Velocity = Body->GetVelocity();

        if (Position.Z < GroundHeight)
        {
            Position.Z = GroundHeight;

            if (Velocity.Z < 0.0f)
            {
                Velocity.Z = -Velocity.Z * Restitution;
            }

            Body->SetPosition(Position);
            Body->SetVelocity(Velocity);
        }
    }
}
