# 5. Source files

## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(uint32_t id, const RigidBodyDesc& desc)
        : m_id(id)
        , m_position(desc.position)
        , m_velocity(desc.velocity)
        , m_mass(desc.isStatic ? 0.0f : desc.mass)
        , m_invMass((desc.isStatic || desc.mass <= 1e-6f) ? 0.0f : 1.0f / desc.mass)
        , m_isStatic(desc.isStatic)
        , m_shapeType(desc.shapeType)
        , m_sphere(desc.sphere)
        , m_restitution(desc.restitution)
    {
    }

    void RigidBody::AddForce(const Vector3& force)
    {
        if (m_isStatic)
        {
            return;
        }
        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vector3(0, 0, 0);
    }

    void RigidBody::Integrate(float dt, const Vector3& gravity)
    {
        if (m_isStatic)
        {
            return;
        }

        Vector3 acceleration = gravity + (m_accumulatedForce * m_invMass);
        m_velocity += acceleration * dt;
        m_position += m_velocity * dt;

        ClearForces();
    }
}
```

