## `Collision.cpp`

```cpp
#include "Collision.h"
#include <algorithm>

namespace CustomPhysics
{
    bool SphereVsPlane(RigidBody& body, const Plane& plane, Contact& outContact)
    {
        if (body.GetShapeType() != ShapeType::Sphere || body.IsStatic())
        {
            return false;
        }

        const Vector3& center = body.GetPosition();
        float radius = body.GetSphere().radius;

        float signedDistance = center.Dot(plane.normal) - plane.distance;

        if (signedDistance >= radius)
        {
            return false;
        }

        outContact.body = &body;
        outContact.normal = plane.normal;
        outContact.penetration = radius - signedDistance;
        return true;
    }

    void ResolveContact(Contact& contact)
    {
        RigidBody* body = contact.body;
        if (!body || body->IsStatic())
        {
            return;
        }

        Vector3 position = body->GetPosition();
        Vector3 velocity = body->GetVelocity();

        position += contact.normal * contact.penetration;

        float separatingVelocity = velocity.Dot(contact.normal);
        if (separatingVelocity < 0.0f)
        {
            float newSepVelocity = -separatingVelocity * body->GetRestitution();
            float deltaVelocity = newSepVelocity - separatingVelocity;
            velocity += contact.normal * deltaVelocity;
        }

        body->SetPosition(position);
        body->SetVelocity(velocity);
    }
}
```

