## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -980.0f, 0.0f)
    {
    }

    uint32_t PhysicsWorld::CreateRigidBody(const RigidBodyDesc& desc)
    {
        uint32_t id = m_nextBodyId++;
        m_bodies.push_back(std::make_unique<RigidBody>(id, desc));
        return id;
    }

    RigidBody* PhysicsWorld::GetRigidBody(uint32_t id)
    {
        for (auto& body : m_bodies)
        {
            if (body->GetId() == id)
            {
                return body.get();
            }
        }
        return nullptr;
    }

    void PhysicsWorld::RemoveRigidBody(uint32_t id)
    {
        m_bodies.erase(
            std::remove_if(
                m_bodies.begin(),
                m_bodies.end(),
                [id](const std::unique_ptr<RigidBody>& body)
                {
                    return body->GetId() == id;
                }),
            m_bodies.end());
    }

    void PhysicsWorld::SetGravity(const Vector3& gravity)
    {
        m_gravity = gravity;
    }

    const Vector3& PhysicsWorld::GetGravity() const
    {
        return m_gravity;
    }

    void PhysicsWorld::AddStaticPlane(const Plane& plane)
    {
        m_planes.push_back(plane);
    }

    void PhysicsWorld::StepSimulation(float deltaTime)
    {
        m_accumulator += deltaTime;

        while (m_accumulator >= m_fixedTimeStep)
        {
            IntegrateBodies(m_fixedTimeStep);
            DetectAndResolveCollisions();
            m_accumulator -= m_fixedTimeStep;
        }
    }

    void PhysicsWorld::IntegrateBodies(float dt)
    {
        for (auto& body : m_bodies)
        {
            body->Integrate(dt, m_gravity);
        }
    }

    void PhysicsWorld::DetectAndResolveCollisions()
    {
        for (auto& body : m_bodies)
        {
            for (const Plane& plane : m_planes)
            {
                Contact contact;
                if (SphereVsPlane(*body, plane, contact))
                {
                    ResolveContact(contact);
                }
            }
        }
    }
}
