## `CustomPhysicsPlugin.cpp`

```cpp
#include "CustomPhysicsPlugin.h"
#include <unordered_set>

namespace CustomPhysics
{
    namespace
    {
        std::unordered_set<PhysicsWorld*> g_worlds;
    }

    bool CustomPhysicsPlugin::Initialize()
    {
        if (m_initialized)
        {
            return true;
        }

        m_initialized = true;
        return true;
    }

    void CustomPhysicsPlugin::Shutdown()
    {
        for (PhysicsWorld* world : g_worlds)
        {
            delete world;
        }
        g_worlds.clear();
        m_initialized = false;
    }

    PhysicsWorld* CustomPhysicsPlugin::CreateWorld()
    {
        if (!m_initialized)
        {
            return nullptr;
        }

        PhysicsWorld* world = new PhysicsWorld();
        g_worlds.insert(world);
        return world;
    }

    void CustomPhysicsPlugin::DestroyWorld(PhysicsWorld* world)
    {
        if (!world)
        {
            return;
        }

        auto it = g_worlds.find(world);
        if (it != g_worlds.end())
        {
            delete world;
            g_worlds.erase(it);
        }
    }
}
