#include "CustomPhysicsPlugin.h"
#include <iostream>

int main()
{
    CustomPhysics::CustomPhysicsPlugin plugin;
    if (!plugin.Initialize())
    {
        return -1;
    }

    CustomPhysics::PhysicsWorld* world = plugin.CreateWorld();
    if (!world)
    {
        return -1;
    }

    CustomPhysics::Plane ground;
    ground.normal = CustomPhysics::Vector3(0, 1, 0);
    ground.distance = 0.0f;
    world->AddStaticPlane(ground);

    CustomPhysics::RigidBodyDesc ballDesc;
    ballDesc.position = CustomPhysics::Vector3(0, 300, 0);
    ballDesc.sphere.radius = 25.0f;
    ballDesc.mass = 1.0f;
    ballDesc.restitution = 0.7f;

    uint32_t ballId = world->CreateRigidBody(ballDesc);

    for (int i = 0; i < 180; ++i)
    {
        world->StepSimulation(1.0f / 60.0f);

        auto* ball = world->GetRigidBody(ballId);
        if (ball)
        {
            const auto& p = ball->GetPosition();
            std::cout << "Frame " << i << ": (" << p.x << ", " << p.y << ", " << p.z << ")\n";
        }
    }

    plugin.DestroyWorld(world);
    plugin.Shutdown();
    return 0;
}
