# 6. World subsystem for simulation

Using a `UWorldSubsystem` is a clean way to manage simulation per world.

## `Public/CustomPhysicsSubsystem.h`

```cpp
#pragma once

#include "CoreMinimal.h"
#include "Subsystems/WorldSubsystem.h"
#include "CustomPhysicsTypes.h"
#include "CustomPhysicsSubsystem.generated.h"

UCLASS()
class CUSTOMPHYSICS_API UCustomPhysicsSubsystem : public UWorldSubsystem
{
    GENERATED_BODY()

public:
    virtual void Tick(float DeltaTime);
    virtual bool ShouldCreateSubsystem(UObject* Outer) const override;
    virtual TStatId GetStatId() const;

    int32 RegisterBody(const FCustomPhysicsBody& Body);
    void UnregisterBody(int32 BodyId);
    void AddForce(int32 BodyId, const FVector& Force);

    bool IsTickable() const { return true; }

private:
    void Simulate(float DeltaTime);

private:
    UPROPERTY()
    TMap<int32, FCustomPhysicsBody> Bodies;

    int32 NextBodyId = 1;

    FVector Gravity = FVector(0.0f, 0.0f, -980.0f);
};
```

## `Private/CustomPhysicsSubsystem.cpp`

```cpp
#include "CustomPhysicsSubsystem.h"
#include "Components/SceneComponent.h"
#include "Engine/World.h"

bool UCustomPhysicsSubsystem::ShouldCreateSubsystem(UObject* Outer) const
{
    return true;
}

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    Simulate(DeltaTime);
}

int32 UCustomPhysicsSubsystem::RegisterBody(const FCustomPhysicsBody& Body)
{
    const int32 BodyId = NextBodyId++;
    Bodies.Add(BodyId, Body);
    return BodyId;
}

void UCustomPhysicsSubsystem::UnregisterBody(int32 BodyId)
{
    Bodies.Remove(BodyId);
}

void UCustomPhysicsSubsystem::AddForce(int32 BodyId, const FVector& Force)
{
    if (FCustomPhysicsBody* Body = Bodies.Find(BodyId))
    {
        Body->AccumulatedForce += Force;
    }
}

void UCustomPhysicsSubsystem::Simulate(float DeltaTime)
{
    if (DeltaTime <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    for (TPair<int32, FCustomPhysicsBody>& Pair : Bodies)
    {
        FCustomPhysicsBody& Body = Pair.Value;

        if (!Body.bSimulate || !Body.TargetComponent.IsValid())
        {
            continue;
        }

        FVector TotalForce = Body.AccumulatedForce;

        if (Body.bUseGravity)
        {
            TotalForce += Gravity * Body.Mass;
        }

        const FVector Acceleration = Body.Mass > KINDA_SMALL_NUMBER
            ? TotalForce / Body.Mass
            : FVector::ZeroVector;

        Body.Velocity += Acceleration * DeltaTime;

        USceneComponent* Component = Body.TargetComponent.Get();
        FVector NewLocation = Component->GetComponentLocation() + Body.Velocity * DeltaTime;
        Component->SetWorldLocation(NewLocation);

        Body.AccumulatedForce = FVector::ZeroVector;
    }
}
```

