## `Private/CustomPhysicsSubsystem.cpp`

```cpp
#include "CustomPhysicsSubsystem.h"
#include "CustomPhysicsComponent.h"
#include "Engine/World.h"
#include "GameFramework/Actor.h"

UCustomPhysicsSubsystem::UCustomPhysicsSubsystem()
    : Gravity(0.0f, 0.0f, -980.0f)
{
}

void UCustomPhysicsSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
    Super::Initialize(Collection);
}

void UCustomPhysicsSubsystem::Deinitialize()
{
    Bodies.Empty();
    Super::Deinitialize();
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    if (DeltaTime <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    for (int32 i = Bodies.Num() - 1; i >= 0; --i)
    {
        FCustomPhysicsBodyEntry& Body = Bodies[i];

        if (!IsValid(Body.Component))
        {
            Bodies.RemoveAtSwap(i);
            continue;
        }

        SimulateBody(Body, DeltaTime);
    }
}

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

bool UCustomPhysicsSubsystem::IsTickable() const
{
    return GetWorld() != nullptr;
}

void UCustomPhysicsSubsystem::RegisterBody(UCustomPhysicsComponent* Component, const FCustomPhysicsBodyState& InitialState)
{
    if (!IsValid(Component))
    {
        return;
    }

    if (FindBodyIndex(Component) != INDEX_NONE)
    {
        return;
    }

    FCustomPhysicsBodyEntry Entry;
    Entry.Component = Component;
    Entry.State = InitialState;

    if (AActor* Owner = Component->GetOwner())
    {
        Entry.State.Position = Owner->GetActorLocation();
    }

    Bodies.Add(Entry);
}

void UCustomPhysicsSubsystem::UnregisterBody(UCustomPhysicsComponent* Component)
{
    const int32 Index = FindBodyIndex(Component);
    if (Index != INDEX_NONE)
    {
        Bodies.RemoveAtSwap(Index);
    }
}

bool UCustomPhysicsSubsystem::AddForce(UCustomPhysicsComponent* Component, const FVector& Force)
{
    const int32 Index = FindBodyIndex(Component);
    if (Index == INDEX_NONE)
    {
        return false;
    }

    Bodies[Index].State.AccumulatedForce += Force;
    return true;
}

bool UCustomPhysicsSubsystem::SetVelocity(UCustomPhysicsComponent* Component, const FVector& NewVelocity)
{
    const int32 Index = FindBodyIndex(Component);
    if (Index == INDEX_NONE)
    {
        return false;
    }

    Bodies[Index].State.Velocity = NewVelocity;
    return true;
}

bool UCustomPhysicsSubsystem::GetBodyState(UCustomPhysicsComponent* Component, FCustomPhysicsBodyState& OutState) const
{
    const int32 Index = FindBodyIndex(Component);
    if (Index == INDEX_NONE)
    {
        return false;
    }

    OutState = Bodies[Index].State;
    return true;
}

int32 UCustomPhysicsSubsystem::FindBodyIndex(const UCustomPhysicsComponent* Component) const
{
    for (int32 i = 0; i < Bodies.Num(); ++i)
    {
        if (Bodies[i].Component == Component)
        {
            return i;
        }
    }

    return INDEX_NONE;
}

void UCustomPhysicsSubsystem::SimulateBody(FCustomPhysicsBodyEntry& Body, float DeltaTime)
{
    FCustomPhysicsBodyState& State = Body.State;

    if (!State.bSimulate || !IsValid(Body.Component))
    {
        return;
    }

    if (State.Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    FVector TotalForce = State.AccumulatedForce;

    if (State.bUseGravity)
    {
        TotalForce += Gravity * State.Mass;
    }

    const FVector Acceleration = TotalForce / State.Mass;

    State.Velocity += Acceleration * DeltaTime;
    State.Position += State.Velocity * DeltaTime;

    State.AccumulatedForce = FVector::ZeroVector;

    if (AActor* Owner = Body.Component->GetOwner())
    {
        Owner->SetActorLocation(State.Position);
    }
}
```

