## `CustomPhysicsSubsystem.cpp`

```cpp
#include "CustomPhysicsSubsystem.h"
#include "Components/SceneComponent.h"

void UCustomPhysicsSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
    Super::Initialize(Collection);
    UE_LOG(LogTemp, Log, TEXT("CustomPhysicsSubsystem initialized"));
}

void UCustomPhysicsSubsystem::Deinitialize()
{
    Bodies.Empty();
    Super::Deinitialize();
    UE_LOG(LogTemp, Log, TEXT("CustomPhysicsSubsystem deinitialized"));
}

bool UCustomPhysicsSubsystem::IsTickable() const
{
    return true;
}

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    for (TPair<int32, FSimplePhysicsBody>& Pair : Bodies)
    {
        SimulateBody(Pair.Value, DeltaTime);
    }
}

int32 UCustomPhysicsSubsystem::RegisterBody(USceneComponent* SceneComponent, float Mass, bool bSimulate)
{
    if (!SceneComponent)
    {
        return INDEX_NONE;
    }

    const int32 BodyId = NextBodyId++;

    FSimplePhysicsBody Body;
    Body.SceneComponent = SceneComponent;
    Body.Mass = FMath::Max(Mass, 0.001f);
    Body.bSimulate = bSimulate;

    Bodies.Add(BodyId, Body);
    return BodyId;
}

void UCustomPhysicsSubsystem::UnregisterBody(int32 BodyId)
{
    Bodies.Remove(BodyId);
}

void UCustomPhysicsSubsystem::AddForce(int32 BodyId, const FVector& Force)
{
    if (FSimplePhysicsBody* Body = Bodies.Find(BodyId))
    {
        Body->AddForce(Force);
    }
}

void UCustomPhysicsSubsystem::SetVelocity(int32 BodyId, const FVector& NewVelocity)
{
    if (FSimplePhysicsBody* Body = Bodies.Find(BodyId))
    {
        Body->Velocity = NewVelocity;
    }
}

void UCustomPhysicsSubsystem::SimulateBody(FSimplePhysicsBody& Body, float DeltaTime)
{
    if (!Body.bSimulate || !Body.SceneComponent.IsValid())
    {
        return;
    }

    USceneComponent* SceneComponent = Body.SceneComponent.Get();
    if (!SceneComponent)
    {
        return;
    }

    const FVector GravityForce = Gravity * Body.Mass;
    const FVector TotalForce = Body.AccumulatedForce + GravityForce;
    const FVector Acceleration = TotalForce / Body.Mass;

    Body.Velocity += Acceleration * DeltaTime;

    FVector NewLocation = SceneComponent->GetComponentLocation();
    NewLocation += Body.Velocity * DeltaTime;

    SceneComponent->SetWorldLocation(NewLocation);

    Body.ClearForces();
}
```

