#include "SimplePhysicsComponent.h"
#include "CustomPhysicsSubsystem.h"
#include "GameFramework/Actor.h"
#include "Components/SceneComponent.h"

USimplePhysicsComponent::USimplePhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void USimplePhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    UWorld* World = GetWorld();
    if (!World)
    {
        return;
    }

    UCustomPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UCustomPhysicsSubsystem>();
    if (!PhysicsSubsystem)
    {
        return;
    }

    USceneComponent* RootComponent = Owner->GetRootComponent();
    if (!RootComponent)
    {
        return;
    }

    BodyId = PhysicsSubsystem->RegisterBody(RootComponent, Mass, bSimulate);
}

void USimplePhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    UWorld* World = GetWorld();
    if (World)
    {
        if (UCustomPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UCustomPhysicsSubsystem>())
        {
            if (BodyId != INDEX_NONE)
            {
                PhysicsSubsystem->UnregisterBody(BodyId);
            }
        }
    }

    Super::EndPlay(EndPlayReason);
}

void USimplePhysicsComponent::AddForce(FVector Force)
{
    UWorld* World = GetWorld();
    if (!World)
    {
        return;
    }

    if (UCustomPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UCustomPhysicsSubsystem>())
    {
        if (BodyId != INDEX_NONE)
        {
            PhysicsSubsystem->AddForce(BodyId, Force);
        }
    }
}

void USimplePhysicsComponent::SetVelocity(FVector NewVelocity)
{
    UWorld* World = GetWorld();
    if (!World)
    {
        return;
    }

    if (UCustomPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UCustomPhysicsSubsystem>())
    {
        if (BodyId != INDEX_NONE)
        {
            PhysicsSubsystem->SetVelocity(BodyId, NewVelocity);
        }
    }
}
```

