# 10. Example: add simple ground collision

Here is a quick improvement to `SimulateBody` so bodies stop at Z = 0.

Replace `SimulateBody` with:

```cpp
void UCustomPhysicsSubsystem::SimulateBody(FSimplePhysicsBody& Body, float DeltaTime)
{
    if (!Body.bSimulate || !Body.SceneComponent.IsValid())
    {
        return;
    }

    USceneComponent* SceneComponent = Body.SceneComponent.Get();
    if (!SceneComponent)
    {
        return;
    }

    const FVector GravityForce = Gravity * Body.Mass;
    const FVector TotalForce = Body.AccumulatedForce + GravityForce;
    const FVector Acceleration = TotalForce / Body.Mass;

    Body.Velocity += Acceleration * DeltaTime;

    FVector NewLocation = SceneComponent->GetComponentLocation();
    NewLocation += Body.Velocity * DeltaTime;

    if (NewLocation.Z < 0.0f)
    {
        NewLocation.Z = 0.0f;
        if (Body.Velocity.Z < 0.0f)
        {
            Body.Velocity.Z = 0.0f;
        }
    }

    SceneComponent->SetWorldLocation(NewLocation);
    Body.ClearForces();
}
```

