# 7. Physics component source: `CustomPhysicsComponent.cpp`

```cpp
#include "CustomPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "DrawDebugHelpers.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (Mass <= KINDA_SMALL_NUMBER)
    {
        UE_LOG(LogTemp, Warning, TEXT("CustomPhysicsComponent on %s has invalid mass. Resetting to 1.0"),
            *GetOwner()->GetName());
        Mass = 1.0f;
    }
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!GetOwner())
    {
        return;
    }

    Simulate(DeltaTime);
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::AddImpulse(FVector Impulse)
{
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Velocity += Impulse / Mass;
    }
}

void UCustomPhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

void UCustomPhysicsComponent::Simulate(float DeltaTime)
{
    if (DeltaTime <= 0.0f || Mass <= KINDA_SMALL_NUMBER)
    {
        ClearForces();
        return;
    }

    FVector TotalForce = AccumulatedForce;

    if (bUseGravity)
    {
        TotalForce += Gravity * Mass;
    }

    FVector Acceleration = TotalForce / Mass;

    Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    FVector CurrentLocation = GetOwner()->GetActorLocation();
    FVector NewLocation = CurrentLocation + Velocity * DeltaTime;

    GetOwner()->SetActorLocation(NewLocation, true);

    if (bDebugDraw)
    {
        DrawDebugLine(
            GetWorld(),
            CurrentLocation,
            NewLocation,
            FColor::Green,
            false,
            0.1f,
            0,
            2.0f);

        DrawDebugDirectionalArrow(
            GetWorld(),
            NewLocation,
            NewLocation + Velocity.GetClampedToMaxSize(100.0f),
            25.0f,
            FColor::Blue,
            false,
            0.1f,
            0,
            2.0f);
    }

    ClearForces();
}

void UCustomPhysicsComponent::ClearForces()
{
    AccumulatedForce = FVector::ZeroVector;
}
```

