#include "CustomPhysicsComponent.h"
#include "CustomPhysicsSubsystem.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (bInitializeFromActorLocation)
    {
        if (AActor* Owner = GetOwner())
        {
            Body.Position = Owner->GetActorLocation();
        }
    }

    if (UCustomPhysicsSubsystem* Subsystem = GetPhysicsSubsystem())
    {
        Subsystem->RegisterComponent(this);
    }
}

void UCustomPhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (UCustomPhysicsSubsystem* Subsystem = GetPhysicsSubsystem())
    {
        Subsystem->UnregisterComponent(this);
    }

    Super::EndPlay(EndPlayReason);
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    Body.AddForce(Force);
}

void UCustomPhysicsComponent::Simulate(float DeltaTime, const FVector& Gravity)
{
    if (!Body.bSimulate || Body.Mass <= KINDA_SMALL_NUMBER)
    {
        Body.ClearForces();
        return;
    }

    FVector TotalForce = Body.AccumulatedForce;

    if (Body.bUseGravity)
    {
        TotalForce += Gravity * Body.Mass;
    }

    const FVector Acceleration = TotalForce / Body.Mass;

    Body.Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - Body.LinearDamping * DeltaTime, 0.0f, 1.0f);
    Body.Velocity *= DampingFactor;

    Body.Position += Body.Velocity * DeltaTime;

    Body.ClearForces();

    if (bSyncActorLocation)
    {
        if (AActor* Owner = GetOwner())
        {
            Owner->SetActorLocation(Body.Position);
        }
    }
}

UCustomPhysicsSubsystem* UCustomPhysicsComponent::GetPhysicsSubsystem() const
{
    if (UWorld* World = GetWorld())
    {
        return World->GetSubsystem<UCustomPhysicsSubsystem>();
    }

    return nullptr;
}
```

