bool UCustomPhysicsSubsystem::ShouldCreateSubsystem(UObject* Outer) const
{
    return true;
}

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

void UCustomPhysicsSubsystem::RegisterComponent(UCustomPhysicsComponent* Component)
{
    if (Component)
    {
        RegisteredComponents.AddUnique(Component);
    }
}

void UCustomPhysicsSubsystem::UnregisterComponent(UCustomPhysicsComponent* Component)
{
    RegisteredComponents.Remove(Component);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    TimeAccumulator += DeltaTime;
    TimeAccumulator = FMath::Min(TimeAccumulator, MaxAccumulatedTime);

    while (TimeAccumulator >= FixedTimeStep)
    {
        SimulateStep(FixedTimeStep);
        TimeAccumulator -= FixedTimeStep;
    }
}

void UCustomPhysicsSubsystem::SimulateStep(float StepTime)
{
    for (int32 Index = RegisteredComponents.Num() - 1; Index >= 0; --Index)
    {
        UCustomPhysicsComponent* Component = RegisteredComponents[Index];
        if (!IsValid(Component))
        {
            RegisteredComponents.RemoveAt(Index);
            continue;
        }

        Component->Simulate(StepTime, Gravity);
    }
}
