# 12. Optional: add simple ground collision

A very basic ground plane at `Z = 0` can be added in `Simulate()`:

## Replace `Simulate()` with:

```cpp
void UCustomPhysicsComponent::Simulate(float DeltaTime, const FVector& Gravity)
{
    if (!Body.bSimulate || Body.Mass <= KINDA_SMALL_NUMBER)
    {
        Body.ClearForces();
        return;
    }

    FVector TotalForce = Body.AccumulatedForce;

    if (Body.bUseGravity)
    {
        TotalForce += Gravity * Body.Mass;
    }

    const FVector Acceleration = TotalForce / Body.Mass;
    Body.Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - Body.LinearDamping * DeltaTime, 0.0f, 1.0f);
    Body.Velocity *= DampingFactor;

    Body.Position += Body.Velocity * DeltaTime;

    // Very simple ground collision at Z = 0
    if (Body.Position.Z < 0.0f)
    {
        Body.Position.Z = 0.0f;

        if (Body.Velocity.Z < 0.0f)
        {
            Body.Velocity.Z *= -0.3f; // restitution
        }
    }

    Body.ClearForces();

    if (bSyncActorLocation)
    {
        if (AActor* Owner = GetOwner())
        {
            Owner->SetActorLocation(Body.Position);
        }
    }
}
