## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(BodyHandle handle, BodyType type, const Transform& transform, float mass)
        : m_handle(handle)
        , m_type(type)
        , m_transform(transform)
        , m_mass(type == BodyType::Dynamic ? mass : 0.0f)
        , m_invMass((type == BodyType::Dynamic && mass > 0.0f) ? 1.0f / mass : 0.0f)
    {
    }

    void RigidBody::AddForce(const Vec3& force)
    {
        if (m_type != BodyType::Dynamic)
            return;

        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = {};
    }

    void RigidBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic)
            return;

        Vec3 acceleration = gravity + (m_accumulatedForce * m_invMass);
        m_linearVelocity += acceleration * dt;
        m_transform.position += m_linearVelocity * dt;

        ClearForces();
    }
}
```

