## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld(const WorldDesc& desc)
        : m_desc(desc)
    {
    }

    BodyHandle PhysicsWorld::CreateRigidBody(BodyType type, const Transform& transform, float mass)
    {
        const BodyHandle handle = m_nextHandle++;
        m_bodies[handle] = std::make_unique<RigidBody>(handle, type, transform, mass);
        return handle;
    }

    void PhysicsWorld::DestroyRigidBody(BodyHandle handle)
    {
        m_bodies.erase(handle);
    }

    RigidBody* PhysicsWorld::GetRigidBody(BodyHandle handle)
    {
        auto it = m_bodies.find(handle);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    const RigidBody* PhysicsWorld::GetRigidBody(BodyHandle handle) const
    {
        auto it = m_bodies.find(handle);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    void PhysicsWorld::StepSimulation(float dt)
    {
        m_accumulator += dt;

        while (m_accumulator >= m_desc.fixedTimeStep)
        {
            IntegrateBodies(m_desc.fixedTimeStep);
            SolveCollisions();
            m_accumulator -= m_desc.fixedTimeStep;
        }
    }

    void PhysicsWorld::IntegrateBodies(float dt)
    {
        for (auto& [handle, body] : m_bodies)
        {
            body->Integrate(dt, m_desc.gravity);
        }
    }

    void PhysicsWorld::SolveCollisions()
    {
        // Initial placeholder:
        // Add broadphase, narrowphase, and impulse resolution here.
        // For now, a simple ground-plane collision at y = 0.

        for (auto& [handle, body] : m_bodies)
        {
            if (body->GetType() != BodyType::Dynamic)
                continue;

            Transform t = body->GetTransform();
            Vec3 v = body->GetLinearVelocity();

            if (t.position.y < 0.0f)
            {
                t.position.y = 0.0f;
                if (v.y < 0.0f)
                {
                    v.y *= -0.3f; // simple restitution
                }

                body->SetTransform(t);
                body->SetLinearVelocity(v);
            }
        }
    }
}
