int main()
{
    CustomPhysics::IPhysicsPlugin* plugin = CustomPhysics::CreatePhysicsPlugin();

    if (!plugin->Initialize())
    {
        std::cerr << "Failed to initialize physics plugin\n";
        return 1;
    }

    auto* world = plugin->GetWorld();

    CustomPhysics::Transform t;
    t.position = {0.0f, 10.0f, 0.0f};

    auto body = world->CreateRigidBody(CustomPhysics::BodyType::Dynamic, t, 1.0f);

    for (int i = 0; i < 120; ++i)
    {
        plugin->Tick(1.0f / 60.0f);

        const auto* rb = world->GetRigidBody(body);
        if (rb)
        {
            const auto& pos = rb->GetTransform().position;
            std::cout << "Body position: " << pos.x << ", " << pos.y << ", " << pos.z << "\n";
        }
    }

    plugin->Shutdown();
    CustomPhysics::DestroyPhysicsPlugin(plugin);
    return 0;
