## `Source/CustomPhysicsPlugin/Private/CustomPhysicsComponent.cpp`

```cpp
#include "CustomPhysicsComponent.h"

#include "Components/PrimitiveComponent.h"
#include "GameFramework/Actor.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PrimaryComponentTick.bStartWithTickEnabled = true;

    TargetPrimitiveComponent = nullptr;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
    ResolveTargetComponent();
}

void UCustomPhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    Super::EndPlay(EndPlayReason);
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bEnabled)
    {
        return;
    }

    if (!TargetPrimitiveComponent)
    {
        ResolveTargetComponent();
    }

    ApplyCustomPhysics(DeltaTime);
}

void UCustomPhysicsComponent::ResolveTargetComponent()
{
    TargetPrimitiveComponent = nullptr;

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    if (TargetComponentName != NAME_None)
    {
        TArray<UActorComponent*> Components;
        Owner->GetComponents(Components);

        for (UActorComponent* Component : Components)
        {
            if (Component && Component->GetFName() == TargetComponentName)
            {
                TargetPrimitiveComponent = Cast<UPrimitiveComponent>(Component);
                if (TargetPrimitiveComponent)
                {
                    return;
                }
            }
        }
    }

    TargetPrimitiveComponent = Cast<UPrimitiveComponent>(Owner->GetRootComponent());
}

void UCustomPhysicsComponent::ApplyCustomPhysics(float DeltaTime)
{
    if (!TargetPrimitiveComponent)
    {
        return;
    }

    if (!TargetPrimitiveComponent->IsSimulatingPhysics())
    {
        return;
    }

    FVector ForceToApply = ConstantForce;

    if (!bApplyInWorldSpace)
    {
        const AActor* Owner = GetOwner();
        if (Owner)
        {
            ForceToApply = Owner->GetActorTransform().TransformVectorNoScale(ConstantForce);
        }
    }

    TargetPrimitiveComponent->AddForce(ForceToApply, NAME_None, true);
}
