```cpp
#include "RigidBody.h"

RigidBody::RigidBody(float mass, const Vec3& position, std::shared_ptr<CollisionShape> shape)
    : m_mass(mass)
    , m_position(position)
    , m_velocity(0.0f, 0.0f, 0.0f)
    , m_accumulatedForce(0.0f, 0.0f, 0.0f)
    , m_shape(std::move(shape))
{
}

void RigidBody::ApplyForce(const Vec3& force)
{
    if (IsStatic())
        return;

    m_accumulatedForce += force;
}

void RigidBody::Integrate(float deltaTime, const Vec3& gravity)
{
    if (IsStatic())
        return;

    Vec3 acceleration = gravity + (m_accumulatedForce * (1.0f / m_mass));
    m_velocity += acceleration * deltaTime;
    m_position += m_velocity * deltaTime;

    m_accumulatedForce = Vec3(0.0f, 0.0f, 0.0f);
}

void RigidBody::SetPosition(const Vec3& position)
{
    m_position = position;
}

const Vec3& RigidBody::GetPosition() const
{
    return m_position;
}

void RigidBody::SetVelocity(const Vec3& velocity)
{
    m_velocity = velocity;
}

const Vec3& RigidBody::GetVelocity() const
{
    return m_velocity;
}

float RigidBody::GetMass() const
{
    return m_mass;
}

bool RigidBody::IsStatic() const
{
    return m_mass <= 0.0f;
}

std::shared_ptr<CollisionShape> RigidBody::GetShape() const
{
    return m_shape;
}
