## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld()
    : m_gravity(0.0f, -9.81f, 0.0f)
{
}

std::shared_ptr<RigidBody> PhysicsWorld::CreateRigidBody(
    float mass,
    const Vec3& position,
    std::shared_ptr<CollisionShape> shape)
{
    auto body = std::make_shared<RigidBody>(mass, position, std::move(shape));
    m_bodies.push_back(body);
    return body;
}

void PhysicsWorld::StepSimulation(float deltaTime)
{
    for (auto& body : m_bodies)
    {
        body->Integrate(deltaTime, m_gravity);
    }

    ResolveCollisions();
}

void PhysicsWorld::SetGravity(const Vec3& gravity)
{
    m_gravity = gravity;
}

const std::vector<std::shared_ptr<RigidBody>>& PhysicsWorld::GetBodies() const
{
    return m_bodies;
}

void PhysicsWorld::ResolveCollisions()
{
    for (auto& body : m_bodies)
    {
        if (body->IsStatic())
            continue;

        auto shape = body->GetShape();
        if (!shape)
            continue;

        if (shape->GetType() == CollisionShapeType::Sphere)
        {
            auto sphere = std::static_pointer_cast<SphereShape>(shape);
            Vec3 pos = body->GetPosition();

            // Simple collision against ground plane at y = 0
            if (pos.y - sphere->GetRadius() < 0.0f)
            {
                pos.y = sphere->GetRadius();
                body->SetPosition(pos);

                Vec3 vel = body->GetVelocity();
                if (vel.y < 0.0f)
                {
                    vel.y *= -0.5f; // simple restitution
                    body->SetVelocity(vel);
                }
            }
        }
    }
}
```

