```cpp
#include "PhysicsPluginAPI.h"

extern "C"
{
    void* CreatePhysicsWorld()
    {
        return new PhysicsWorld();
    }

    void DestroyPhysicsWorld(void* world)
    {
        delete static_cast<PhysicsWorld*>(world);
    }

    void StepPhysicsWorld(void* world, float deltaTime)
    {
        if (!world)
            return;

        static_cast<PhysicsWorld*>(world)->StepSimulation(deltaTime);
    }

    void SetPhysicsWorldGravity(void* world, float x, float y, float z)
    {
        if (!world)
            return;

        static_cast<PhysicsWorld*>(world)->SetGravity(Vec3(x, y, z));
    }

    void* CreateSphereBody(
        void* world,
        float mass,
        float posX, float posY, float posZ,
        float radius)
    {
        if (!world)
            return nullptr;

        auto* physicsWorld = static_cast<PhysicsWorld*>(world);
        auto shape = std::make_shared<SphereShape>(radius);
        auto body = physicsWorld->CreateRigidBody(mass, Vec3(posX, posY, posZ), shape);
        return body.get();
    }

    void ApplyForceToBody(void* body, float fx, float fy, float fz)
    {
        if (!body)
            return;

        static_cast<RigidBody*>(body)->ApplyForce(Vec3(fx, fy, fz));
    }

    void GetBodyPosition(void* body, float* x, float* y, float* z)
    {
        if (!body || !x || !y || !z)
            return;

        const Vec3& pos = static_cast<RigidBody*>(body)->GetPosition();
        *x = pos.x;
        *y = pos.y;
        *z = pos.z;
    }
}
