## `EnginePhysicsSubsystem.h`

```cpp
#pragma once

#include "PhysicsWorld.h"
#include <memory>

class EnginePhysicsSubsystem
{
public:
    bool Initialize();
    void Shutdown();
    void Tick(float deltaTime);

    std::shared_ptr<RigidBody> CreateTestBody();

private:
    std::unique_ptr<PhysicsWorld> m_world;
};
```

## `EnginePhysicsSubsystem.cpp`

```cpp
#include "EnginePhysicsSubsystem.h"

bool EnginePhysicsSubsystem::Initialize()
{
    m_world = std::make_unique<PhysicsWorld>();
    m_world->SetGravity(Vec3(0.0f, -9.81f, 0.0f));
    return true;
}

void EnginePhysicsSubsystem::Shutdown()
{
    m_world.reset();
}

void EnginePhysicsSubsystem::Tick(float deltaTime)
{
    if (m_world)
    {
        const float fixedTimeStep = 1.0f / 60.0f;
        static float accumulator = 0.0f;

        accumulator += deltaTime;
        while (accumulator >= fixedTimeStep)
        {
            m_world->StepSimulation(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }
    }
}

std::shared_ptr<RigidBody> EnginePhysicsSubsystem::CreateTestBody()
{
    if (!m_world)
        return nullptr;

    auto shape = std::make_shared<SphereShape>(0.5f);
    return m_world->CreateRigidBody(1.0f, Vec3(0.0f, 10.0f, 0.0f), shape);
}
