# 5. Rigid body definition

## `Include/RigidBody.h`

```cpp
#pragma once

#include "PhysicsTypes.h"
#include <memory>

struct CollisionShape
{
    ShapeType type;

    union
    {
        SphereShape sphere;
        PlaneShape plane;
    };

    CollisionShape()
        : type(ShapeType::Sphere), sphere{}
    {
    }

    static CollisionShape MakeSphere(float radius)
    {
        CollisionShape shape;
        shape.type = ShapeType::Sphere;
        shape.sphere.radius = radius;
        return shape;
    }

    static CollisionShape MakePlane(const Vec3& normal, float distance)
    {
        CollisionShape shape;
        shape.type = ShapeType::Plane;
        shape.plane.normal = normal.Normalized();
        shape.plane.distance = distance;
        return shape;
    }
};

class RigidBody
{
public:
    RigidBody(int id, float mass, const Vec3& position, const CollisionShape& shape, bool isStatic = false);

    int GetId() const { return m_id; }

    const Vec3& GetPosition() const { return m_position; }
    void SetPosition(const Vec3& position) { m_position = position; }

    const Vec3& GetVelocity() const { return m_velocity; }
    void SetVelocity(const Vec3& velocity) { m_velocity = velocity; }

    float GetMass() const { return m_mass; }
    float GetInvMass() const { return m_invMass; }

    bool IsStatic() const { return m_isStatic; }

    const CollisionShape& GetShape() const { return m_shape; }

    void AddForce(const Vec3& force);
    void ClearForces();

    void Integrate(float dt, const Vec3& gravity);

private:
    int m_id = -1;
    float m_mass = 1.0f;
    float m_invMass = 1.0f;
    bool m_isStatic = false;

    Vec3 m_position;
    Vec3 m_velocity;
    Vec3 m_accumulatedForce;

    CollisionShape m_shape;
};
```

## `Source/RigidBody.cpp`

```cpp
#include "RigidBody.h"

RigidBody::RigidBody(int id, float mass, const Vec3& position, const CollisionShape& shape, bool isStatic)
    : m_id(id)
    , m_mass(isStatic ? 0.0f : mass)
    , m_invMass((isStatic || mass <= 1e-6f) ? 0.0f : 1.0f / mass)
    , m_isStatic(isStatic)
    , m_position(position)
    , m_velocity(0.0f, 0.0f, 0.0f)
    , m_accumulatedForce(0.0f, 0.0f, 0.0f)
    , m_shape(shape)
{
}

void RigidBody::AddForce(const Vec3& force)
{
    if (m_isStatic)
        return;

    m_accumulatedForce += force;
}

void RigidBody::ClearForces()
{
    m_accumulatedForce = Vec3(0.0f, 0.0f, 0.0f);
}

void RigidBody::Integrate(float dt, const Vec3& gravity)
{
    if (m_isStatic)
        return;

    Vec3 acceleration = gravity + (m_accumulatedForce * m_invMass);
    m_velocity += acceleration * dt;
    m_position += m_velocity * dt;

    ClearForces();
}
