## `Source/PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld()
    : m_gravity(0.0f, -980.0f, 0.0f) // cm/s^2 style gravity
    , m_nextBodyId(1)
{
}

void PhysicsWorld::SetGravity(const Vec3& gravity)
{
    m_gravity = gravity;
}

const Vec3& PhysicsWorld::GetGravity() const
{
    return m_gravity;
}

int PhysicsWorld::CreateRigidBody(float mass, const Vec3& position, const CollisionShape& shape, bool isStatic)
{
    int id = m_nextBodyId++;
    m_bodies[id] = std::make_unique<RigidBody>(id, mass, position, shape, isStatic);
    return id;
}

void PhysicsWorld::RemoveRigidBody(int bodyId)
{
    m_bodies.erase(bodyId);
}

RigidBody* PhysicsWorld::GetRigidBody(int bodyId)
{
    auto it = m_bodies.find(bodyId);
    if (it == m_bodies.end())
        return nullptr;
    return it->second.get();
}

const RigidBody* PhysicsWorld::GetRigidBody(int bodyId) const
{
    auto it = m_bodies.find(bodyId);
    if (it == m_bodies.end())
        return nullptr;
    return it->second.get();
}

void PhysicsWorld::AddForce(int bodyId, const Vec3& force)
{
    RigidBody* body = GetRigidBody(bodyId);
    if (body)
    {
        body->AddForce(force);
    }
}

void PhysicsWorld::StepSimulation(float dt)
{
    for (auto& [id, body] : m_bodies)
    {
        body->Integrate(dt, m_gravity);
    }

    DetectAndResolveCollisions();
}

void PhysicsWorld::DetectAndResolveCollisions()
{
    std::vector<RigidBody*> bodies;
    bodies.reserve(m_bodies.size());

    for (auto& [id, body] : m_bodies)
    {
        bodies.push_back(body.get());
    }

    for (size_t i = 0; i < bodies.size(); ++i)
    {
        for (size_t j = i + 1; j < bodies.size(); ++j)
        {
            RigidBody* a = bodies[i];
            RigidBody* b = bodies[j];

            if (a->GetShape().type == ShapeType::Sphere && b->GetShape().type == ShapeType::Plane)
            {
                ResolveSpherePlane(*a, *b);
            }
            else if (a->GetShape().type == ShapeType::Plane && b->GetShape().type == ShapeType::Sphere)
            {
                ResolveSpherePlane(*b, *a);
            }
        }
    }
}

void PhysicsWorld::ResolveSpherePlane(RigidBody& sphereBody, RigidBody& planeBody)
{
    if (sphereBody.IsStatic())
        return;

    const CollisionShape& sphereShape = sphereBody.GetShape();
    const CollisionShape& planeShape = planeBody.GetShape();

    const Vec3& center = sphereBody.GetPosition();
    const Vec3& normal = planeShape.plane.normal;
    float planeDistance = planeShape.plane.distance;
    float radius = sphereShape.sphere.radius;

    float signedDistance = center.Dot(normal) - planeDistance;

    if (signedDistance < radius)
    {
        float penetration = radius - signedDistance;

        Vec3 correctedPosition = center + normal * penetration;
        sphereBody.SetPosition(correctedPosition);

        Vec3 velocity = sphereBody.GetVelocity();
        float normalVelocity = velocity.Dot(normal);

        if (normalVelocity < 0.0f)
        {
            float restitution = 0.5f;
            Vec3 reflected = velocity - normal * ((1.0f + restitution) * normalVelocity);
            sphereBody.SetVelocity(reflected);
        }
    }
}
