## `Source/CustomPhysicsPlugin.cpp`

```cpp
#include "CustomPhysicsPlugin.h"
#include <iostream>

CustomPhysicsPlugin::CustomPhysicsPlugin() = default;
CustomPhysicsPlugin::~CustomPhysicsPlugin()
{
    Shutdown();
}

bool CustomPhysicsPlugin::Initialize()
{
    if (m_initialized)
        return true;

    m_world = std::make_unique<PhysicsWorld>();
    m_initialized = true;

    std::cout << "[CustomPhysicsPlugin] Initialized\n";
    return true;
}

void CustomPhysicsPlugin::Shutdown()
{
    if (!m_initialized)
        return;

    m_world.reset();
    m_initialized = false;

    std::cout << "[CustomPhysicsPlugin] Shutdown\n";
}

void CustomPhysicsPlugin::Tick(float deltaTime)
{
    if (!m_initialized || !m_world)
        return;

    m_world->StepSimulation(deltaTime);
}
