## Minimal plugin structure

```cpp
// PhysicsPlugin.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x+o.x, y+o.y, z+o.z}; }
    Vec3 operator*(float s) const { return {x*s, y*s, z*s}; }
};

struct Body {
    Vec3 position;
    Vec3 velocity;
    float mass;
    bool dynamic;
};

class PhysicsWorld {
public:
    void AddBody(const Body& body) { bodies.push_back(body); }
    std::vector<Body>& GetBodies() { return bodies; }

    void Step(float dt) {
        for (auto& b : bodies) {
            if (!b.dynamic) continue;
            b.velocity = b.velocity + gravity * dt;
            b.position = b.position + b.velocity * dt;
        }
    }

    void SetGravity(Vec3 g) { gravity = g; }

private:
    std::vector<Body> bodies;
    Vec3 gravity{0.0f, -9.81f, 0.0f};
};
```

