static PhysicsWorld gWorld;

extern "C" {

void Plugin_Initialize() {
    gWorld.SetGravity({0.0f, -9.81f, 0.0f});
}

int Plugin_CreateBody(float px, float py, float pz,
                      float vx, float vy, float vz,
                      float mass, int dynamic) {
    Body b;
    b.position = {px, py, pz};
    b.velocity = {vx, vy, vz};
    b.mass = mass;
    b.dynamic = dynamic != 0;
    gWorld.AddBody(b);
    return (int)gWorld.GetBodies().size() - 1;
}

void Plugin_Step(float dt) {
    gWorld.Step(dt);
}

void Plugin_GetBodyPosition(int id, float* x, float* y, float* z) {
    auto& bodies = gWorld.GetBodies();
    if (id < 0 || id >= (int)bodies.size()) return;
    *x = bodies[id].position.x;
    *y = bodies[id].position.y;
    *z = bodies[id].position.z;
}

}
