// MinimalPhysicsPlugin.cpp
#include "MinimalPhysicsPlugin.h"

void MinimalPhysicsWorld::AddBody(const RigidBody& body) {
    bodies.push_back(body);
}

void MinimalPhysicsWorld::Step(float dt) {
    for (auto& body : bodies) {
        if (body.isStatic || body.mass <= 0.0f) continue;

        Vec3 acceleration = gravity + (body.force * (1.0f / body.mass));
        body.velocity = body.velocity + acceleration * dt;
        body.position = body.position + body.velocity * dt;

        body.force = {0,0,0};

        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) body.velocity.y *= -0.5f;
        }
    }
}

const std::vector<RigidBody>& MinimalPhysicsWorld::GetBodies() const {
    return bodies;
}
