int SimplePhysicsPlugin::CreateBody(const RigidBody& body)
{
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void SimplePhysicsPlugin::ApplyForce(int bodyId, const Vec3& force)
{
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
        return;

    if (!bodies[bodyId].isStatic)
        bodies[bodyId].force += force;
}

void SimplePhysicsPlugin::StepSimulation(float deltaTime)
{
    for (auto& body : bodies)
    {
        if (body.isStatic)
            continue;

        Vec3 totalForce = body.force + gravity * body.mass;
        Vec3 acceleration = totalForce * (1.0f / body.mass);

        body.velocity += acceleration * deltaTime;
        body.position += body.velocity * deltaTime;

        // Simple collision with ground plane at y = 0
        if (body.position.y < 0.0f)
        {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f)
                body.velocity.y *= -0.5f; // crude bounce
        }

        body.force = Vec3(0.0f, 0.0f, 0.0f);
    }
}

