    bool isStatic = false;
};

using BodyHandle = uint32_t;

class MinimalPhysicsWorld {
public:
    bool Initialize();
    void Shutdown();

    BodyHandle CreateBody(const RigidBodyDesc& desc);
    void DestroyBody(BodyHandle handle);

    void ApplyForce(BodyHandle handle, Vec3 force);
    void StepSimulation(float deltaTime);

    Transform GetTransform(BodyHandle handle) const;
    void SetTransform(BodyHandle handle, const Transform& t);

private:
    struct Body {
        bool active = false;
        bool isStatic = false;
        float mass = 1.0f;
        Vec3 position{0,0,0};
        Vec3 velocity{0,0,0};
        Vec3 accumulatedForce{0,0,0};
    };

