```

```cpp
// MinimalPhysicsPlugin.cpp
#include "MinimalPhysicsPlugin.h"
#include <stdexcept>

static Vec3 Add(Vec3 a, Vec3 b) { return {a.x+b.x, a.y+b.y, a.z+b.z}; }
static Vec3 Sub(Vec3 a, Vec3 b) { return {a.x-b.x, a.y-b.y, a.z-b.z}; }
static Vec3 Mul(Vec3 v, float s) { return {v.x*s, v.y*s, v.z*s}; }

bool MinimalPhysicsWorld::Initialize() {
    bodies_.clear();
    return true;
}

void MinimalPhysicsWorld::Shutdown() {
    bodies_.clear();
}

BodyHandle MinimalPhysicsWorld::CreateBody(const RigidBodyDesc& desc) {
    Body body;
    body.active = true;
    body.isStatic = desc.isStatic;
    body.mass = desc.isStatic ? 0.0f : desc.mass;
    body.position = desc.initialPosition;
    body.velocity = desc.initialVelocity;
    body.accumulatedForce = {0,0,0};

    bodies_.push_back(body);
    return static_cast<BodyHandle>(bodies_.size() - 1);
}

void MinimalPhysicsWorld::DestroyBody(BodyHandle handle) {
    if (handle < bodies_.size()) {
        bodies_[handle].active = false;
    }
}

void MinimalPhysicsWorld::ApplyForce(BodyHandle handle, Vec3 force) {
    if (handle >= bodies_.size()) return;
    Body& b = bodies_[handle];
    if (!b.active || b.isStatic) return;
    b.accumulatedForce = Add(b.accumulatedForce, force);
}

void MinimalPhysicsWorld::StepSimulation(float dt) {
    for (auto& b : bodies_) {
        if (!b.active || b.isStatic) continue;

        Vec3 totalForce = Add(b.accumulatedForce, Mul(gravity_, b.mass));
        Vec3 acceleration = Mul(totalForce, 1.0f / b.mass);

        b.velocity = Add(b.velocity, Mul(acceleration, dt));
        b.position = Add(b.position, Mul(b.velocity, dt));

        if (b.position.y < 0.0f) {
            b.position.y = 0.0f;
            if (b.velocity.y < 0.0f) b.velocity.y *= -0.5f;
        }

        b.accumulatedForce = {0,0,0};
    }
}

Transform MinimalPhysicsWorld::GetTransform(BodyHandle handle) const {
    if (handle >= bodies_.size() || !bodies_[handle].active) {
        return {};
    }
    Transform t;
    t.position = bodies_[handle].position;
    t.rotationEuler = {0,0,0};
    return t;
}

void MinimalPhysicsWorld::SetTransform(BodyHandle handle, const Transform& t) {
    if (handle >= bodies_.size()) return;
    Body& b = bodies_[handle];
    if (!b.active) return;
    b.position = t.position;
}
