// MinimalPhysicsPlugin.cpp
#include "MinimalPhysicsPlugin.h"

bool MinimalPhysicsPlugin::Initialize() {
    bodies.clear();
    return true;
}

void MinimalPhysicsPlugin::Shutdown() {
    bodies.clear();
}

int MinimalPhysicsPlugin::CreateBody(const Vec3& position, float mass, bool isStatic) {
    RigidBody body;
    body.position = position;
    body.mass = (mass <= 0.0f) ? 1.0f : mass;
    body.isStatic = isStatic;
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void MinimalPhysicsPlugin::AddForce(int bodyId, const Vec3& force) {
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size())) return;
    if (bodies[bodyId].isStatic) return;
    bodies[bodyId].accumulatedForce += force;
}

const RigidBody* MinimalPhysicsPlugin::GetBody(int bodyId) const {
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size())) return nullptr;
    return &bodies[bodyId];
}

void MinimalPhysicsPlugin::StepSimulation(float dt) {
    if (dt <= 0.0f) return;

    for (auto& body : bodies) {
        if (body.isStatic) continue;

        Vec3 totalForce = body.accumulatedForce + gravity * body.mass;
        Vec3 acceleration = totalForce * (1.0f / body.mass);

        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;

        // Simple ground plane collision at y = 0
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) {
                body.velocity.y *= -0.5f; // restitution
            }
        }

        body.accumulatedForce = {0.0f, 0.0f, 0.0f};
    }
}
