            Vec3 gravityForce = gravity * body->mass;
            Vec3 totalForce = body->accumulatedForce + gravityForce;
            Vec3 acceleration = totalForce * (1.0f / body->mass);

            body->velocity = body->velocity + acceleration * dt;
            body->position = body->position + body->velocity * dt;

            body->accumulatedForce = {0,0,0};

            // Simple ground collision at y = 0
            if (body->position.y < 0.0f) {
                body->position.y = 0.0f;
                if (body->velocity.y < 0.0f) {
                    body->velocity.y *= -0.3f; // crude bounce
                }
            }
        }
