// MinimalPhysicsPlugin.h
#pragma once

#include <vector>
#include <cstdint>

#if defined(_WIN32)
  #define PLUGIN_EXPORT extern "C" __declspec(dllexport)
#else
  #define PLUGIN_EXPORT extern "C"
#endif

struct Vec3 {
    float x, y, z;

