    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }

    Vec3& operator+=(const Vec3& o) {
        x += o.x; y += o.y; z += o.z;
        return *this;
    }
};

struct Transform {
    Vec3 position;
};

using BodyHandle = uint32_t;

struct BodyDesc {
    float mass;
    Vec3 position;
    Vec3 velocity;
    float radius;
    bool isStatic;
};

class PhysicsWorld {
public:
    BodyHandle CreateBody(const BodyDesc& desc);
    void DestroyBody(BodyHandle handle);
    void Step(float dt);
    bool GetTransform(BodyHandle handle, Transform& out) const;
    bool SetVelocity(BodyHandle handle, const Vec3& v);

private:
    struct Body {
        bool alive = false;
        bool isStatic = false;
        float mass = 1.0f;
        float invMass = 1.0f;
        float radius = 0.5f;
        Vec3 position{0,0,0};
        Vec3 velocity{0,0,0};
    };

    std::vector<Body> bodies;
    Vec3 gravity{0.0f, -9.81f, 0.0f};
