```cpp
// MinimalPhysicsPlugin.cpp
#include "MinimalPhysicsPlugin.h"
#include <limits>

BodyHandle PhysicsWorld::CreateBody(const BodyDesc& desc) {
    Body body;
    body.alive = true;
    body.isStatic = desc.isStatic;
    body.mass = desc.isStatic ? std::numeric_limits<float>::infinity() : desc.mass;
    body.invMass = (desc.isStatic || desc.mass <= 0.0f) ? 0.0f : (1.0f / desc.mass);
    body.radius = desc.radius;
    body.position = desc.position;
    body.velocity = desc.velocity;

    for (uint32_t i = 0; i < bodies.size(); ++i) {
        if (!bodies[i].alive) {
            bodies[i] = body;
            return i;
        }
    }

    bodies.push_back(body);
    return static_cast<BodyHandle>(bodies.size() - 1);
}

void PhysicsWorld::DestroyBody(BodyHandle handle) {
    if (handle < bodies.size()) {
        bodies[handle].alive = false;
    }
}

bool PhysicsWorld::GetTransform(BodyHandle handle, Transform& out) const {
    if (handle >= bodies.size() || !bodies[handle].alive) return false;
    out.position = bodies[handle].position;
    return true;
}

bool PhysicsWorld::SetVelocity(BodyHandle handle, const Vec3& v) {
    if (handle >= bodies.size() || !bodies[handle].alive) return false;
    if (bodies[handle].isStatic) return false;
    bodies[handle].velocity = v;
    return true;
}

void PhysicsWorld::Step(float dt) {
    for (auto& b : bodies) {
        if (!b.alive || b.isStatic) continue;

        // Integrate velocity
        b.velocity += gravity * dt;

        // Integrate position
        b.position += b.velocity * dt;

        // Simple collision against ground plane y = 0
        if (b.position.y - b.radius < 0.0f) {
            b.position.y = b.radius;

            if (b.velocity.y < 0.0f) {
                b.velocity.y *= -0.5f; // restitution
            }

            // crude friction
            b.velocity.x *= 0.9f;
            b.velocity.z *= 0.9f;
        }
    }
}
