#include <SDL2/SDL.h>
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

static constexpr float PI = 3.14159265359f;

// -----------------------------
// Math
// -----------------------------
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& rhs) const { return {x + rhs.x, y + rhs.y}; }
    Vec2 operator-(const Vec2& rhs) const { return {x - rhs.x, y - rhs.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& rhs) { x += rhs.x; y += rhs.y; return *this; }
    Vec2& operator-=(const Vec2& rhs) { x -= rhs.x; y -= rhs.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float Length(const Vec2& v) {
    return std::sqrt(Dot(v, v));
}

static inline Vec2 Normalize(const Vec2& v) {
    float len = Length(v);
    if (len < 1e-6f) return {0.0f, 0.0f};
    return v / len;
}

static inline float Cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

// scalar x vector => vector
static inline Vec2 Cross(float s, const Vec2& v) {
    return {-s * v.y, s * v.x};
}

// vector x scalar => vector
static inline Vec2 Cross(const Vec2& v, float s) {
    return {s * v.y, -s * v.x};
}

static inline float Clamp(float x, float lo, float hi) {
    return std::max(lo, std::min(x, hi));
}

// -----------------------------
// Rigid body
// -----------------------------
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float width = 50.0f;
    float height = 30.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float restitution = 0.3f;
    float friction = 0.8f;

    bool isStatic = false;

    void SetBox(float w, float h, float m, bool makeStatic = false) {
        width = w;
        height = h;
        isStatic = makeStatic;

        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            mass = m;
            invMass = 1.0f / mass;
            inertia = (mass * (w * w + h * h)) / 12.0f;
            invInertia = 1.0f / inertia;
        }
    }

    void ApplyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void ApplyForceAtPoint(const Vec2& f, const Vec2& worldPoint) {
        if (isStatic) return;
        force += f;
        Vec2 r = worldPoint - position;
        torque += Cross(r, f);
    }

    void ApplyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += Cross(contactVector, impulse) * invInertia;
    }

    void IntegrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void IntegrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void ClearAccumulators() {
        force = {0.0f, 0.0f};
        torque = 0.0f;
    }

    std::vector<Vec2> GetWorldVertices() const {
        float c = std::cos(angle);
        float s = std::sin(angle);

        float hx = width * 0.5f;
        float hy = height * 0.5f;

        std::vector<Vec2> local = {
            {-hx, -hy},
            { hx, -hy},
            { hx,  hy},
            {-hx,  hy}
        };

        std::vector<Vec2> world;
        world.reserve(4);

        for (const auto& v : local) {
            Vec2 rotated{
                v.x * c - v.y * s,
                v.x * s + v.y * c
            };
            world.push_back(position + rotated);
        }

        return world;
    }
};

// -----------------------------
// Ground collision
// Simple collision against horizontal ground y = groundY
// -----------------------------
void ResolveGroundCollision(RigidBody& body, float groundY) {
    if (body.isStatic) return;

    auto verts = body.GetWorldVertices();

    float minPenetration = 0.0f;
    bool collided = false;
    Vec2 contactPoint{0.0f, 0.0f};

    for (const auto& v : verts) {
        float penetration = v.y - groundY;
        if (penetration > 0.0f) {
            collided = true;
            if (penetration > minPenetration) {
                minPenetration = penetration;
                contactPoint = v;
            }
        }
    }

    if (!collided) return;

    // Positional correction
    body.position.y -= minPenetration;

    Vec2 normal{0.0f, -1.0f}; // ground pushes upward in screen coordinates
    Vec2 r = contactPoint - body.position;

    Vec2 contactVel = body.velocity + Cross(body.angularVelocity, r);
    float velAlongNormal = Dot(contactVel, normal);

    if (velAlongNormal > 0.0f) {
        return;
    }

    float e = body.restitution;

    float rnCrossN = Cross(r, normal);
    float denom = body.invMass + (rnCrossN * rnCrossN) * body.invInertia;

    float j = -(1.0f + e) * velAlongNormal;
    if (denom > 1e-6f) {
        j /= denom;
    } else {
        j = 0.0f;
    }

    Vec2 impulse = normal * j;
    body.ApplyImpulse(impulse, r);

    // Friction impulse
    contactVel = body.velocity + Cross(body.angularVelocity, r);
    Vec2 tangent = contactVel - normal * Dot(contactVel, normal);

    float tangentLen = Length(tangent);
    if (tangentLen > 1e-6f) {
        tangent = tangent / tangentLen;

        float rtCrossT = Cross(r, tangent);
        float frictionDenom = body.invMass + (rtCrossT * rtCrossT) * body.invInertia;

        float jt = -Dot(contactVel, tangent);
        if (frictionDenom > 1e-6f) {
            jt /= frictionDenom;
        } else {
            jt = 0.0f;
        }

        float mu = body.friction;
        jt = Clamp(jt, -j * mu, j * mu);

        Vec2 frictionImpulse = tangent * jt;
        body.ApplyImpulse(frictionImpulse, r);
    }

    // Damp tiny jitter
    if (std::fabs(body.velocity.y) < 0.05f) body.velocity.y = 0.0f;
    if (std::fabs(body.angularVelocity) < 0.05f) body.angularVelocity = 0.0f;
}

// -----------------------------
// Physics world
// -----------------------------
struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec2 gravity{0.0f, 980.0f}; // pixels/s^2 downward
    float groundY = 550.0f;

    void Step(float dt) {
        // Integrate forces
        for (auto& b : bodies) {
            b.IntegrateForces(dt, gravity);
        }

        // Integrate velocities
        for (auto& b : bodies) {
            b.IntegrateVelocity(dt);
        }

        // Collisions
        for (auto& b : bodies) {
            ResolveGroundCollision(b, groundY);
        }

        // Clear forces
        for (auto& b : bodies) {
            b.ClearAccumulators();
        }
    }
};

// -----------------------------
// Rendering helpers
// -----------------------------
void DrawLine(SDL_Renderer* renderer, const Vec2& a, const Vec2& b) {
    SDL_RenderDrawLine(renderer,
                       static_cast<int>(a.x), static_cast<int>(a.y),
                       static_cast<int>(b.x), static_cast<int>(b.y));
}

void DrawBody(SDL_Renderer* renderer, const RigidBody& body) {
    auto verts = body.GetWorldVertices();
    for (int i = 0; i < 4; ++i) {
        DrawLine(renderer, verts[i], verts[(i + 1) % 4]);
    }

    // Draw center
    SDL_Rect centerRect{
        static_cast<int>(body.position.x - 2),
        static_cast<int>(body.position.y - 2),
        4, 4
    };
    SDL_RenderFillRect(renderer, &centerRect);
}

// -----------------------------
// Main
// -----------------------------
int main(int argc, char** argv) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics - Fixed Timestep",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        900, 600,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(
        window, -1, SDL_RENDERER_ACCELERATED
    );

    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    PhysicsWorld world;

    // Create a few boxes
    {
        RigidBody b;
        b.position = {200.0f, 100.0f};
        b.angle = 0.2f;
        b.velocity = {80.0f, 0.0f};
        b.angularVelocity = 1.5f;
        b.restitution = 0.25f;
        b.friction = 0.7f;
        b.SetBox(80.0f, 40.0f, 4.0f);
        world.bodies.push_back(b);
    }

    {
        RigidBody b;
        b.position = {400.0f, 50.0f};
        b.angle = -0.4f;
        b.velocity = {-20.0f, 0.0f};
        b.angularVelocity = -0.8f;
        b.restitution = 0.15f;
        b.friction = 0.9f;
        b.SetBox(60.0f, 60.0f, 6.0f);
        world.bodies.push_back(b);
    }

    bool running = true;

    // Fixed timestep physics
    const float fixedDt = 1.0f / 120.0f;
    float accumulator = 0.0f;

    Uint64 prevCounter = SDL_GetPerformanceCounter();
    const double perfFreq = static_cast<double>(SDL_GetPerformanceFrequency());

    // Frame cap target (~60 FPS)
    const double targetFrameTime = 1.0 / 60.0;

    while (running) {
        Uint64 frameStart = SDL_GetPerformanceCounter();

        Uint64 currentCounter = SDL_GetPerformanceCounter();
        double frameTime = (currentCounter - prevCounter) / perfFreq;
        prevCounter = currentCounter;

        // Avoid spiral of death on long stalls
        frameTime = std::min(frameTime, 0.25);
        accumulator += static_cast<float>(frameTime);

        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }

            if (event.type == SDL_KEYDOWN) {
                if (event.key.keysym.sym == SDLK_ESCAPE) {
                    running = false;
                }

                // Spawn a new body
                if (event.key.keysym.sym == SDLK_SPACE) {
                    RigidBody b;
                    b.position = {100.0f + static_cast<float>(rand() % 700), 50.0f};
                    b.angle = static_cast<float>((rand() % 100) / 100.0f * PI);
                    b.velocity = {
                        -100.0f + static_cast<float>(rand() % 200),
                        0.0f
                    };
                    b.angularVelocity = -3.0f + static_cast<float>(rand() % 600) / 100.0f;
                    b.restitution = 0.2f;
                    b.friction = 0.8f;
                    b.SetBox(
                        30.0f + static_cast<float>(rand() % 50),
                        30.0f + static_cast<float>(rand() % 50),
                        2.0f + static_cast<float>(rand() % 5)
                    );
                    world.bodies.push_back(b);
                }
            }
        }

        // Fixed-step simulation
        while (accumulator >= fixedDt) {
            world.Step(fixedDt);
            accumulator -= fixedDt;
        }

        // Optional interpolation alpha for smoother rendering
        float alpha = accumulator / fixedDt;
        (void)alpha; // not used in this simple example

        // Render
        SDL_SetRenderDrawColor(renderer, 18, 18, 22, 255);
        SDL_RenderClear(renderer);

        // Ground
        SDL_SetRenderDrawColor(renderer, 100, 220, 100, 255);
        SDL_RenderDrawLine(renderer, 0, static_cast<int>(world.groundY),
                           900, static_cast<int>(world.groundY));

        // Bodies
        SDL_SetRenderDrawColor(renderer, 230, 230, 240, 255);
        for (const auto& b : world.bodies) {
            DrawBody(renderer, b);
        }

        SDL_RenderPresent(renderer);

        // Frame-rate constraint / cap
        Uint64 frameEnd = SDL_GetPerformanceCounter();
        double elapsed = (frameEnd - frameStart) / perfFreq;

        if (elapsed < targetFrameTime) {
            Uint32 delayMs = static_cast<Uint32>((targetFrameTime - elapsed) * 1000.0);
            if (delayMs > 0) {
                SDL_Delay(delayMs);
            }
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
