# Code

```cpp
#include <SDL2/SDL.h>
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

constexpr int WINDOW_WIDTH = 1000;
constexpr int WINDOW_HEIGHT = 700;

constexpr double FIXED_DT = 1.0 / 120.0;   // physics timestep
constexpr int MAX_SUBSTEPS = 8;
constexpr int TARGET_FPS = 60;
constexpr double FRAME_TIME = 1.0 / TARGET_FPS;

constexpr double GRAVITY_Y = 500.0;
constexpr double RESTITUTION = 0.7;
constexpr double LINEAR_DAMPING = 0.999;
constexpr double ANGULAR_DAMPING = 0.999;

struct Vec2 {
    double x = 0.0;
    double y = 0.0;

    Vec2() = default;
    Vec2(double x_, double y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(double s) const { return {x * s, y * s}; }
    Vec2 operator/(double s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(double s) { x *= s; y *= s; return *this; }
};

static inline double Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline double Length(const Vec2& v) {
    return std::sqrt(Dot(v, v));
}

static inline Vec2 Normalize(const Vec2& v) {
    double len = Length(v);
    if (len < 1e-8) return {0.0, 0.0};
    return v / len;
}

// 2D cross products
static inline double Cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

static inline Vec2 Cross(const Vec2& v, double a) {
    return { a * v.y, -a * v.x };
}

static inline Vec2 Cross(double a, const Vec2& v) {
    return { -a * v.y, a * v.x };
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    double angle = 0.0;
    double angularVelocity = 0.0;
    double torque = 0.0;

    double radius = 20.0;

    double mass = 1.0;
    double invMass = 1.0;

    double inertia = 1.0;
    double invInertia = 1.0;

    bool isStatic = false;

    void ComputeMass(double density = 1.0) {
        if (isStatic) {
            mass = 0.0;
            invMass = 0.0;
            inertia = 0.0;
            invInertia = 0.0;
            return;
        }

        // Circle mass/inertia in 2D
        double area = M_PI * radius * radius;
        mass = area * density;
        invMass = (mass > 0.0) ? 1.0 / mass : 0.0;

        inertia = 0.5 * mass * radius * radius;
        invInertia = (inertia > 0.0) ? 1.0 / inertia : 0.0;
    }

    void ApplyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void ApplyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * Cross(contactVector, impulse);
    }

    void IntegrateForces(double dt) {
        if (isStatic) return;
        velocity += (force * invMass + Vec2{0.0, GRAVITY_Y}) * dt;
        angularVelocity += torque * invInertia * dt;

        velocity *= LINEAR_DAMPING;
        angularVelocity *= ANGULAR_DAMPING;
    }

    void IntegrateVelocity(double dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void ClearAccumulators() {
        force = {0.0, 0.0};
        torque = 0.0;
    }
};

struct Contact {
    RigidBody* a = nullptr;
    RigidBody* b = nullptr;
    Vec2 normal;
    Vec2 point;
    double penetration = 0.0;
};

bool CircleVsCircle(RigidBody& a, RigidBody& b, Contact& contact) {
    Vec2 delta = b.position - a.position;
    double distSq = Dot(delta, delta);
    double radiusSum = a.radius + b.radius;

    if (distSq >= radiusSum * radiusSum) return false;

    double dist = std::sqrt(distSq);

    contact.a = &a;
    contact.b = &b;

    if (dist > 1e-8) {
        contact.normal = delta / dist;
        contact.penetration = radiusSum - dist;
        contact.point = a.position + contact.normal * (a.radius - contact.penetration * 0.5);
    } else {
        // Perfect overlap fallback
        contact.normal = {1.0, 0.0};
        contact.penetration = a.radius;
        contact.point = a.position;
    }

    return true;
}

void ResolveCollision(Contact& c) {
    RigidBody& a = *c.a;
    RigidBody& b = *c.b;

    if (a.invMass + b.invMass == 0.0) return;

    Vec2 ra = c.point - a.position;
    Vec2 rb = c.point - b.position;

    Vec2 va = a.velocity + Cross(a.angularVelocity, ra);
    Vec2 vb = b.velocity + Cross(b.angularVelocity, rb);
    Vec2 rv = vb - va;

    double contactVel = Dot(rv, c.normal);

    // Bodies separating
    if (contactVel > 0.0) return;

    double raCrossN = Cross(ra, c.normal);
    double rbCrossN = Cross(rb, c.normal);

    double invMassSum =
        a.invMass + b.invMass +
        (raCrossN * raCrossN) * a.invInertia +
        (rbCrossN * rbCrossN) * b.invInertia;

    double e = RESTITUTION;
    double j = -(1.0 + e) * contactVel;
    j /= invMassSum;

    Vec2 impulse = c.normal * j;

    a.ApplyImpulse(impulse * -1.0, ra);
    b.ApplyImpulse(impulse, rb);

    // Optional friction
    va = a.velocity + Cross(a.angularVelocity, ra);
    vb = b.velocity + Cross(b.angularVelocity, rb);
    rv = vb - va;

    Vec2 tangent = rv - c.normal * Dot(rv, c.normal);
    double tangentLen = Length(tangent);
    if (tangentLen > 1e-8) tangent = tangent / tangentLen;
    else tangent = {0.0, 0.0};

    double jt = -Dot(rv, tangent);
    jt /= invMassSum;

    double mu = 0.3;
    Vec2 frictionImpulse;
    if (std::abs(jt) < j * mu)
        frictionImpulse = tangent * jt;
    else
        frictionImpulse = tangent * (-j * mu);

    a.ApplyImpulse(frictionImpulse * -1.0, ra);
    b.ApplyImpulse(frictionImpulse, rb);
}

void PositionalCorrection(Contact& c) {
    const double percent = 0.8;   // correction strength
    const double slop = 0.01;     // penetration allowance

    RigidBody& a = *c.a;
    RigidBody& b = *c.b;

    double invMassSum = a.invMass + b.invMass;
    if (invMassSum == 0.0) return;

    Vec2 correction = c.normal * (std::max(c.penetration - slop, 0.0) / invMassSum * percent);

    if (!a.isStatic) a.position -= correction * a.invMass;
    if (!b.isStatic) b.position += correction * b.invMass;
}

void SolveWorldBounds(RigidBody& body) {
    if (body.isStatic) return;

    // Left
    if (body.position.x - body.radius < 0.0) {
        body.position.x = body.radius;
        body.velocity.x *= -RESTITUTION;
    }
    // Right
    if (body.position.x + body.radius > WINDOW_WIDTH) {
        body.position.x = WINDOW_WIDTH - body.radius;
        body.velocity.x *= -RESTITUTION;
    }
    // Top
    if (body.position.y - body.radius < 0.0) {
        body.position.y = body.radius;
        body.velocity.y *= -RESTITUTION;
    }
    // Bottom
    if (body.position.y + body.radius > WINDOW_HEIGHT) {
        body.position.y = WINDOW_HEIGHT - body.radius;
        body.velocity.y *= -RESTITUTION;
    }
}

void DrawCircle(SDL_Renderer* renderer, int cx, int cy, int r) {
    for (int w = -r; w <= r; ++w) {
        for (int h = -r; h <= r; ++h) {
            if (w * w + h * h <= r * r) {
                SDL_RenderDrawPoint(renderer, cx + w, cy + h);
            }
        }
    }
}

void DrawBody(SDL_Renderer* renderer, const RigidBody& body) {
    DrawCircle(renderer, (int)body.position.x, (int)body.position.y, (int)body.radius);

    // Orientation line
    int x2 = (int)(body.position.x + std::cos(body.angle) * body.radius);
    int y2 = (int)(body.position.y + std::sin(body.angle) * body.radius);
    SDL_RenderDrawLine(renderer, (int)body.position.x, (int)body.position.y, x2, y2);
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics Simulation",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH,
        WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    std::vector<RigidBody> bodies;

    // Create some dynamic bodies
    for (int i = 0; i < 8; ++i) {
        RigidBody b;
        b.position = {150.0 + i * 70.0, 100.0 + i * 20.0};
        b.velocity = {50.0 - i * 5.0, 0.0};
        b.radius = 20.0 + (i % 3) * 5.0;
        b.ComputeMass(0.02);
        bodies.push_back(b);
    }

    bool running = true;
    Uint64 prevCounter = SDL_GetPerformanceCounter();
    double accumulator = 0.0;

    while (running) {
        Uint64 frameStart = SDL_GetPerformanceCounter();
        double elapsed = (double)(frameStart - prevCounter) / SDL_GetPerformanceFrequency();
        prevCounter = frameStart;

        // Prevent spiral of death on long stalls
        elapsed = std::min(elapsed, 0.25);
        accumulator += elapsed;

        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }

            if (event.type == SDL_MOUSEBUTTONDOWN) {
                if (event.button.button == SDL_BUTTON_LEFT) {
                    RigidBody b;
                    b.position = {(double)event.button.x, (double)event.button.y};
                    b.velocity = {((rand() % 200) - 100.0), -150.0};
                    b.angularVelocity = ((rand() % 200) - 100.0) * 0.02;
                    b.radius = 15.0 + rand() % 20;
                    b.ComputeMass(0.02);
                    bodies.push_back(b);
                }
            }
        }

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            // Integrate forces
            for (auto& body : bodies) {
                body.IntegrateForces(FIXED_DT);
            }

            // Detect collisions
            std::vector<Contact> contacts;
            for (size_t i = 0; i < bodies.size(); ++i) {
                for (size_t j = i + 1; j < bodies.size(); ++j) {
                    Contact c;
                    if (CircleVsCircle(bodies[i], bodies[j], c)) {
                        contacts.push_back(c);
                    }
                }
            }

            // Resolve collisions iteratively
            for (int iter = 0; iter < 8; ++iter) {
                for (auto& c : contacts) {
                    ResolveCollision(c);
                }
            }

            // Integrate velocities
            for (auto& body : bodies) {
                body.IntegrateVelocity(FIXED_DT);
                SolveWorldBounds(body);
            }

            // Positional correction
            for (auto& c : contacts) {
                PositionalCorrection(c);
            }

            // Clear forces
            for (auto& body : bodies) {
                body.ClearAccumulators();
            }

            accumulator -= FIXED_DT;
            ++substeps;
        }

        // Render
        SDL_SetRenderDrawColor(renderer, 18, 18, 22, 255);
        SDL_RenderClear(renderer);

        SDL_SetRenderDrawColor(renderer, 100, 220, 255, 255);
        for (const auto& body : bodies) {
            DrawBody(renderer, body);
        }

        SDL_RenderPresent(renderer);

        // Frame-rate cap
        Uint64 frameEnd = SDL_GetPerformanceCounter();
        double frameDuration = (double)(frameEnd - frameStart) / SDL_GetPerformanceFrequency();

        if (frameDuration < FRAME_TIME) {
            Uint32 delayMs = (Uint32)((FRAME_TIME - frameDuration) * 1000.0);
            if (delayMs > 0) SDL_Delay(delayMs);
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
