## C++ example

This example simulates simple 3D rigid bodies with gravity and ground collision.

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float FIXED_DT = 1.0f / 120.0f;   // 120 Hz physics
constexpr float MAX_FRAME_TIME = 0.25f;     // clamp huge frame spikes
constexpr int MAX_SUBSTEPS = 8;
constexpr float GRAVITY = -9.81f;
constexpr float GROUND_Y = 0.0f;

// -----------------------------
// Basic math
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return Vec3(x + b.x, y + b.y, z + b.z); }
    Vec3 operator-(const Vec3& b) const { return Vec3(x - b.x, y - b.y, z - b.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& b) const { return x*b.x + y*b.y + z*b.z; }

    Vec3 cross(const Vec3& b) const {
        return Vec3(
            y * b.z - z * b.y,
            z * b.x - x * b.z,
            x * b.y - y * b.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-8f) return Vec3(0, 0, 0);
        return *this / len;
    }
};

struct Mat3 {
    float m[3][3];

    static Mat3 identity() {
        Mat3 r{};
        r.m[0][0] = 1; r.m[0][1] = 0; r.m[0][2] = 0;
        r.m[1][0] = 0; r.m[1][1] = 1; r.m[1][2] = 0;
        r.m[2][0] = 0; r.m[2][1] = 0; r.m[2][2] = 1;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }

    Mat3 operator*(const Mat3& b) const {
        Mat3 r{};
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                r.m[i][j] = 0.0f;
                for (int k = 0; k < 3; ++k) {
                    r.m[i][j] += m[i][k] * b.m[k][j];
                }
            }
        }
        return r;
    }

    Mat3 transpose() const {
        Mat3 r{};
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                r.m[i][j] = m[j][i];
        return r;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& b) const {
        return Quat(w + b.w, x + b.x, y + b.y, z + b.z);
    }

    Quat operator*(float s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator*(const Quat& b) const {
        return Quat(
            w*b.w - x*b.x - y*b.y - z*b.z,
            w*b.x + x*b.w + y*b.z - z*b.y,
            w*b.y - x*b.z + y*b.w + z*b.x,
            w*b.z + x*b.y - y*b.x + z*b.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r{};
        float xx = x * x, yy = y * y, zz = z * z;
        float xy = x * y, xz = x * z, yz = y * z;
        float wx = w * x, wy = w * y, wz = w * z;

        r.m[0][0] = 1.0f - 2.0f * (yy + zz);
        r.m[0][1] = 2.0f * (xy - wz);
        r.m[0][2] = 2.0f * (xz + wy);

        r.m[1][0] = 2.0f * (xy + wz);
        r.m[1][1] = 1.0f - 2.0f * (xx + zz);
        r.m[1][2] = 2.0f * (yz - wx);

        r.m[2][0] = 2.0f * (xz - wy);
        r.m[2][1] = 2.0f * (yz + wx);
        r.m[2][2] = 1.0f - 2.0f * (xx + yy);

        return r;
    }
};

// -----------------------------
// Rigid body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;

    float radius; // simple sphere collision shape

    bool isStatic = false;

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos), orientation(), linearVelocity(), angularVelocity(),
          forceAccum(), torqueAccum(), mass(m), radius(r) {
        if (m <= 0.0f) {
            isStatic = true;
            mass = 0.0f;
            invMass = 0.0f;
            inertiaBody = Mat3::identity();
            invInertiaBody = Mat3::identity();
        } else {
            invMass = 1.0f / mass;

            // Sphere inertia tensor: I = 2/5 m r^2
            float I = 0.4f * mass * radius * radius;
            float invI = 1.0f / I;

            inertiaBody = {};
            invInertiaBody = {};
            inertiaBody.m[0][0] = I; inertiaBody.m[1][1] = I; inertiaBody.m[2][2] = I;
            invInertiaBody.m[0][0] = invI; invInertiaBody.m[1][1] = invI; invInertiaBody.m[2][2] = invI;
        }
    }

    Mat3 getInvInertiaWorld() const {
        Mat3 R = orientation.toMat3();
        return R * invInertiaBody * R.transpose();
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += r.cross(force);
    }

    void applyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;

        linearVelocity += impulse * invMass;

        Mat3 invInertiaWorld = getInvInertiaWorld();
        angularVelocity += invInertiaWorld * contactVector.cross(impulse);
    }

    void clearAccumulators() {
        forceAccum = Vec3(0, 0, 0);
        torqueAccum = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        linearVelocity += acceleration * dt;
        position += linearVelocity * dt;

        // Angular
        Mat3 invInertiaWorld = getInvInertiaWorld();
        Vec3 angularAcceleration = invInertiaWorld * torqueAccum;
        angularVelocity += angularAcceleration * dt;

        // Quaternion derivative: q_dot = 0.5 * omega_quat * q
        Quat omega(0.0f, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat qDot = omega * orientation;
        orientation = orientation + qDot * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

// -----------------------------
// Collision with ground plane
// -----------------------------
void solveGroundCollision(RigidBody& body, float restitution = 0.5f, float friction = 0.8f) {
    if (body.isStatic) return;

    float penetration = (GROUND_Y + body.radius) - body.position.y;
    if (penetration <= 0.0f) return;

    // Positional correction
    body.position.y += penetration;

    Vec3 normal(0, 1, 0);
    Vec3 contactPoint(body.position.x, GROUND_Y, body.position.z);
    Vec3 r = contactPoint - body.position;

    Vec3 contactVel = body.linearVelocity + body.angularVelocity.cross(r);
    float velAlongNormal = contactVel.dot(normal);

    if (velAlongNormal < 0.0f) {
        Mat3 invInertiaWorld = body.getInvInertiaWorld();
        Vec3 rn = r.cross(normal);
        Vec3 angularTerm = invInertiaWorld * rn;
        float denom = body.invMass + normal.dot(angularTerm.cross(r));

        float j = -(1.0f + restitution) * velAlongNormal;
        if (denom > 1e-6f) j /= denom;
        else j = 0.0f;

        Vec3 impulse = normal * j;
        body.applyImpulse(impulse, r);

        // Friction
        contactVel = body.linearVelocity + body.angularVelocity.cross(r);
        Vec3 tangent = contactVel - normal * contactVel.dot(normal);
        float tangentLen = tangent.length();

        if (tangentLen > 1e-6f) {
            tangent = tangent / tangentLen;

            Vec3 rt = r.cross(tangent);
            Vec3 angularTermT = invInertiaWorld * rt;
            float denomT = body.invMass + tangent.dot(angularTermT.cross(r));

            float jt = -contactVel.dot(tangent);
            if (denomT > 1e-6f) jt /= denomT;
            else jt = 0.0f;

            float maxFriction = friction * j;
            jt = std::clamp(jt, -maxFriction, maxFriction);

            Vec3 frictionImpulse = tangent * jt;
            body.applyImpulse(frictionImpulse, r);
        }
    }
}

// -----------------------------
// Physics world
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;

    void step(float dt) {
        // Apply global forces
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(Vec3(0.0f, body.mass * GRAVITY, 0.0f));
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Collisions
        for (auto& body : bodies) {
            solveGroundCollision(body);
        }
    }
};

// -----------------------------
// Main loop with frame-rate constraints
// -----------------------------
int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(2.0f, 0.5f, Vec3(0, 10, 0));
    world.bodies.emplace_back(1.0f, 0.4f, Vec3(1, 15, 0));

    world.bodies[0].linearVelocity = Vec3(1.0f, 0.0f, 0.0f);
    world.bodies[1].linearVelocity = Vec3(-0.5f, 0.0f, 0.0f);
    world.bodies[1].angularVelocity = Vec3(0.0f, 0.0f, 4.0f);

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();

    float accumulator = 0.0f;
    bool running = true;
    int frameCount = 0;

    while (running) {
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = elapsed.count();
        frameTime = std::min(frameTime, MAX_FRAME_TIME);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
            ++substeps;
        }

        // If too slow, drop excess accumulated time to avoid spiral-of-death
        if (substeps == MAX_SUBSTEPS && accumulator >= FIXED_DT) {
            accumulator = 0.0f;
        }

        // Render / debug output
        float alpha = accumulator / FIXED_DT;

        std::cout << "Frame " << frameCount++
                  << " | alpha=" << alpha
                  << " | body0 pos=("
                  << world.bodies[0].position.x << ", "
                  << world.bodies[0].position.y << ", "
                  << world.bodies[0].position.z << ")"
                  << " | body1 pos=("
                  << world.bodies[1].position.x << ", "
                  << world.bodies[1].position.y << ", "
                  << world.bodies[1].position.z << ")"
                  << "\n";

        // Simulate render frame pacing (~60 FPS)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));

        if (frameCount > 600) {
            running = false;
        }
    }

    return 0;
}
```

