# Example C++ Code

```cpp
#include <cmath>
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float FIXED_DT = 1.0f / 60.0f;
constexpr float MAX_FRAME_TIME = 0.25f; // clamp to avoid spiral of death
constexpr int   MAX_SUBSTEPS = 8;

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return Vec2(0, 0);
    return v / len;
}

// 2D cross products:
// scalar x vector -> vector
static inline Vec2 cross(float s, const Vec2& v) {
    return Vec2(-s * v.y, s * v.x);
}

// vector x vector -> scalar
static inline float cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float radius = 0.5f;      // simple circle body
    float restitution = 0.5f; // bounciness
    float linearDamping = 0.999f;
    float angularDamping = 0.999f;

    bool isStatic = false;

    void setMass(float m) {
        mass = m;
        if (m <= 0.0f || isStatic) {
            invMass = 0.0f;
        } else {
            invMass = 1.0f / m;
        }
    }

    void setCircleInertia(float r) {
        radius = r;
        if (isStatic || mass <= 0.0f) {
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            // Solid disk inertia in 2D
            inertia = 0.5f * mass * r * r;
            invInertia = 1.0f / inertia;
        }
    }

    void applyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void applyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * cross(contactVector, impulse);
    }

    void integrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void integrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;

        velocity *= linearDamping;
        angularVelocity *= angularDamping;
    }

    void clearAccumulators() {
        force = Vec2(0, 0);
        torque = 0.0f;
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0.0f, -9.81f);
    float groundY = 0.0f;

    void step(float dt) {
        // 1. Integrate forces
        for (auto& body : bodies) {
            body.integrateForces(dt, gravity);
        }

        // 2. Integrate velocities
        for (auto& body : bodies) {
            body.integrateVelocity(dt);
        }

        // 3. Solve collisions
        solveGroundCollisions();
        solveBodyCollisions();

        // 4. Clear forces
        for (auto& body : bodies) {
            body.clearAccumulators();
        }
    }

    void solveGroundCollisions() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float penetration = groundY - (body.position.y - body.radius);
            if (penetration > 0.0f) {
                // Positional correction
                body.position.y += penetration;

                Vec2 normal(0.0f, 1.0f);

                // Contact point at bottom of circle
                Vec2 contactPoint(body.position.x, body.position.y - body.radius);
                Vec2 r = contactPoint - body.position;

                Vec2 contactVelocity = body.velocity + cross(body.angularVelocity, r);
                float velAlongNormal = dot(contactVelocity, normal);

                if (velAlongNormal < 0.0f) {
                    float e = body.restitution;

                    float rnCrossN = cross(r, normal);
                    float denom = body.invMass + (rnCrossN * rnCrossN) * body.invInertia;

                    float j = -(1.0f + e) * velAlongNormal;
                    if (denom > 1e-6f) j /= denom;

                    Vec2 impulse = normal * j;
                    body.applyImpulse(impulse, r);
                }

                // Simple friction
                contactVelocity = body.velocity + cross(body.angularVelocity, r);
                Vec2 tangent = contactVelocity - normal * dot(contactVelocity, normal);
                float tangentLen = length(tangent);

                if (tangentLen > 1e-6f) {
                    tangent = tangent / tangentLen;

                    float rtCrossT = cross(r, tangent);
                    float denom = body.invMass + (rtCrossT * rtCrossT) * body.invInertia;

                    float jt = -dot(contactVelocity, tangent);
                    if (denom > 1e-6f) jt /= denom;

                    float mu = 0.5f;
                    jt = std::clamp(jt, -mu, mu);

                    Vec2 frictionImpulse = tangent * jt;
                    body.applyImpulse(frictionImpulse, r);
                }
            }
        }
    }

    void solveBodyCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                if (a.isStatic && b.isStatic) continue;

                Vec2 delta = b.position - a.position;
                float dist = length(delta);
                float minDist = a.radius + b.radius;

                if (dist < minDist && dist > 1e-6f) {
                    Vec2 normal = delta / dist;
                    float penetration = minDist - dist;

                    // Positional correction
                    float totalInvMass = a.invMass + b.invMass;
                    if (totalInvMass > 1e-6f) {
                        Vec2 correction = normal * (penetration / totalInvMass * 0.8f);
                        if (!a.isStatic) a.position -= correction * a.invMass;
                        if (!b.isStatic) b.position += correction * b.invMass;
                    }

                    Vec2 contactPoint = a.position + normal * a.radius;
                    Vec2 ra = contactPoint - a.position;
                    Vec2 rb = contactPoint - b.position;

                    Vec2 va = a.velocity + cross(a.angularVelocity, ra);
                    Vec2 vb = b.velocity + cross(b.angularVelocity, rb);
                    Vec2 rv = vb - va;

                    float velAlongNormal = dot(rv, normal);
                    if (velAlongNormal > 0.0f) continue;

                    float e = std::min(a.restitution, b.restitution);

                    float raCrossN = cross(ra, normal);
                    float rbCrossN = cross(rb, normal);

                    float denom = a.invMass + b.invMass
                        + (raCrossN * raCrossN) * a.invInertia
                        + (rbCrossN * rbCrossN) * b.invInertia;

                    if (denom < 1e-6f) continue;

                    float jImpulse = -(1.0f + e) * velAlongNormal / denom;
                    Vec2 impulse = normal * jImpulse;

                    a.applyImpulse(impulse * -1.0f, ra);
                    b.applyImpulse(impulse, rb);

                    // Friction
                    va = a.velocity + cross(a.angularVelocity, ra);
                    vb = b.velocity + cross(b.angularVelocity, rb);
                    rv = vb - va;

                    Vec2 tangent = rv - normal * dot(rv, normal);
                    float tLen = length(tangent);
                    if (tLen > 1e-6f) {
                        tangent = tangent / tLen;

                        float raCrossT = cross(ra, tangent);
                        float rbCrossT = cross(rb, tangent);

                        float frictionDenom = a.invMass + b.invMass
                            + (raCrossT * raCrossT) * a.invInertia
                            + (rbCrossT * rbCrossT) * b.invInertia;

                        if (frictionDenom > 1e-6f) {
                            float jt = -dot(rv, tangent) / frictionDenom;
                            float mu = 0.4f;
                            jt = std::clamp(jt, -mu * jImpulse, mu * jImpulse);

                            Vec2 frictionImpulse = tangent * jt;
                            a.applyImpulse(frictionImpulse * -1.0f, ra);
                            b.applyImpulse(frictionImpulse, rb);
                        }
                    }
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // Static ground is implicit via groundY

    // Create some dynamic rigid bodies
    {
        RigidBody body;
        body.position = Vec2(-1.0f, 8.0f);
        body.velocity = Vec2(2.0f, 0.0f);
        body.setMass(2.0f);
        body.setCircleInertia(0.5f);
        body.restitution = 0.7f;
        world.bodies.push_back(body);
    }

    {
        RigidBody body;
        body.position = Vec2(1.0f, 10.0f);
        body.velocity = Vec2(-1.5f, 0.0f);
        body.setMass(1.0f);
        body.setCircleInertia(0.6f);
        body.restitution = 0.5f;
        world.bodies.push_back(body);
    }

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    float accumulator = 0.0f;

    // Simulate for ~10 seconds
    float simulationTime = 0.0f;
    while (simulationTime < 10.0f) {
        auto currentTime = clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = elapsed.count();
        frameTime = std::min(frameTime, MAX_FRAME_TIME);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
            simulationTime += FIXED_DT;
            ++substeps;
        }

        // If frame is too slow, discard excess accumulated time
        if (substeps == MAX_SUBSTEPS && accumulator >= FIXED_DT) {
            accumulator = 0.0f;
        }

        // Render / debug output
        std::cout << "t=" << simulationTime << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout
                << " Body " << i
                << " Pos(" << b.position.x << ", " << b.position.y << ")"
                << " Vel(" << b.velocity.x << ", " << b.velocity.y << ")"
                << " Angle(" << b.angle << ")"
                << " AngVel(" << b.angularVelocity << ")\n";
        }
        std::cout << "----------------------\n";

        // Simulate rendering workload
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

---

# Why this satisfies frame-rate constraints

## 1. Fixed timestep
Physics always advances by:

```cpp
FIXED_DT = 1.0f / 60.0f;
```

So simulation behavior is much more stable and deterministic than using variable `dt`.

## 2. Frame time clamping
This line:

```cpp
frameTime = std::min(frameTime, MAX_FRAME_TIME);
```

prevents huge pauses from causing giant unstable physics steps.

## 3. Max substeps
This loop:

```cpp
while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS)
```

limits how much physics work can happen in one rendered frame.

## 4. Spiral-of-death protection
If rendering is too slow and physics can’t catch up, we drop excess accumulated time:

```cpp
if (substeps == MAX_SUBSTEPS && accumulator >= FIXED_DT) {
    accumulator = 0.0f;
}
```

That sacrifices perfect time accuracy to preserve real-time responsiveness.

---

# Important notes

This is a **basic engine skeleton**, not a production-grade physics engine. Real engines usually add:

- Broad-phase collision detection
- Better contact manifolds
- Iterative constraint solvers
- Sleeping/deactivation
- Continuous collision detection
- Better friction/stability handling
- Interpolation for rendering

---

# Optional: render interpolation

If you want smoother rendering between physics steps:

```cpp
float alpha = accumulator / FIXED_DT;
renderPos = currentPos * alpha + previousPos * (1.0f - alpha);
```

To support that, store previous transform before each physics step.

