# Code

```cpp
#include <SDL2/SDL.h>
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

constexpr int SCREEN_WIDTH = 1000;
constexpr int SCREEN_HEIGHT = 700;

constexpr float PIXELS_PER_METER = 50.0f;
constexpr float FIXED_DT = 1.0f / 120.0f;
constexpr float MAX_FRAME_TIME = 0.25f;
constexpr int MAX_SUBSTEPS = 8;

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& rhs) const { return Vec2(x + rhs.x, y + rhs.y); }
    Vec2 operator-(const Vec2& rhs) const { return Vec2(x - rhs.x, y - rhs.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& rhs) { x += rhs.x; y += rhs.y; return *this; }
    Vec2& operator-=(const Vec2& rhs) { x -= rhs.x; y -= rhs.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float Length(const Vec2& v) {
    return std::sqrt(Dot(v, v));
}

static inline Vec2 Normalize(const Vec2& v) {
    float len = Length(v);
    if (len < 1e-6f) return Vec2(0, 0);
    return v / len;
}

static inline float Cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

static inline Vec2 Cross(const Vec2& v, float a) {
    return Vec2(a * v.y, -a * v.x);
}

static inline Vec2 Cross(float a, const Vec2& v) {
    return Vec2(-a * v.y, a * v.x);
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float angle = 0.0f;
    float angularVelocity = 0.0f;

    Vec2 force;
    float torque = 0.0f;

    float width = 1.0f;
    float height = 1.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float restitution = 0.3f;
    float friction = 0.8f;

    bool isStatic = false;

    void SetBox(float w, float h, float m, bool makeStatic = false) {
        width = w;
        height = h;
        isStatic = makeStatic;

        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            mass = m;
            invMass = 1.0f / mass;
            inertia = (mass * (w * w + h * h)) / 12.0f;
            invInertia = 1.0f / inertia;
        }
    }

    void ApplyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void ApplyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * Cross(contactVector, impulse);
    }

    void IntegrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void IntegrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void ClearAccumulators() {
        force = Vec2(0, 0);
        torque = 0.0f;
    }

    std::vector<Vec2> GetWorldVertices() const {
        float c = std::cos(angle);
        float s = std::sin(angle);

        float hx = width * 0.5f;
        float hy = height * 0.5f;

        std::vector<Vec2> local = {
            {-hx, -hy},
            { hx, -hy},
            { hx,  hy},
            {-hx,  hy}
        };

        std::vector<Vec2> world;
        world.reserve(4);

        for (const auto& p : local) {
            Vec2 rotated(
                p.x * c - p.y * s,
                p.x * s + p.y * c
            );
            world.push_back(position + rotated);
        }

        return world;
    }
};

struct Contact {
    RigidBody* body = nullptr;
    Vec2 point;
    Vec2 normal;
    float penetration = 0.0f;
};

class PhysicsWorld {
public:
    Vec2 gravity = Vec2(0.0f, 9.81f);
    float groundY = 12.0f;

    std::vector<RigidBody> bodies;

    void Step(float dt) {
        for (auto& body : bodies) {
            body.IntegrateForces(dt, gravity);
        }

        std::vector<Contact> contacts;
        DetectGroundContacts(contacts);

        for (int i = 0; i < 8; ++i) {
            for (auto& c : contacts) {
                ResolveContact(c);
            }
        }

        for (auto& body : bodies) {
            body.IntegrateVelocity(dt);
        }

        for (auto& body : bodies) {
            body.ClearAccumulators();
        }

        PositionalCorrection(contacts);
    }

private:
    void DetectGroundContacts(std::vector<Contact>& contacts) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            auto verts = body.GetWorldVertices();
            for (const auto& v : verts) {
                if (v.y > groundY) {
                    Contact c;
                    c.body = &body;
                    c.point = v;
                    c.normal = Vec2(0.0f, -1.0f);
                    c.penetration = v.y - groundY;
                    contacts.push_back(c);
                }
            }
        }
    }

    void ResolveContact(Contact& c) {
        RigidBody& body = *c.body;

        Vec2 r = c.point - body.position;
        Vec2 rv = body.velocity + Cross(body.angularVelocity, r);

        float velAlongNormal = Dot(rv, c.normal);
        if (velAlongNormal > 0.0f) return;

        float e = body.restitution;

        float rnCross = Cross(r, c.normal);
        float invMassSum = body.invMass + (rnCross * rnCross) * body.invInertia;

        if (invMassSum <= 1e-6f) return;

        float j = -(1.0f + e) * velAlongNormal;
        j /= invMassSum;

        Vec2 impulse = c.normal * j;
        body.ApplyImpulse(impulse, r);

        rv = body.velocity + Cross(body.angularVelocity, r);

        Vec2 tangent = rv - c.normal * Dot(rv, c.normal);
        float tangentLen = Length(tangent);
        if (tangentLen > 1e-6f) {
            tangent = tangent / tangentLen;

            float rtCross = Cross(r, tangent);
            float denom = body.invMass + (rtCross * rtCross) * body.invInertia;
            if (denom > 1e-6f) {
                float jt = -Dot(rv, tangent);
                jt /= denom;

                float mu = body.friction;
                if (std::fabs(jt) > j * mu) {
                    jt = (jt < 0.0f ? -1.0f : 1.0f) * j * mu;
                }

                Vec2 frictionImpulse = tangent * jt;
                body.ApplyImpulse(frictionImpulse, r);
            }
        }
    }

    void PositionalCorrection(const std::vector<Contact>& contacts) {
        const float percent = 0.8f;
        const float slop = 0.01f;

        for (const auto& c : contacts) {
            RigidBody& body = *c.body;
            if (body.invMass <= 0.0f) continue;

            float correctionMag = std::max(c.penetration - slop, 0.0f) * percent;
            Vec2 correction = c.normal * correctionMag;
            body.position -= correction * body.invMass;
        }
    }
};

static SDL_Point ToScreen(const Vec2& p) {
    return SDL_Point{
        static_cast<int>(p.x * PIXELS_PER_METER),
        static_cast<int>(p.y * PIXELS_PER_METER)
    };
}

void DrawBody(SDL_Renderer* renderer, const RigidBody& body) {
    auto verts = body.GetWorldVertices();
    SDL_Point pts[5];
    for (int i = 0; i < 4; ++i) {
        pts[i] = ToScreen(verts[i]);
    }
    pts[4] = pts[0];

    SDL_RenderDrawLines(renderer, pts, 5);

    SDL_Point center = ToScreen(body.position);
    Vec2 dir(std::cos(body.angle), std::sin(body.angle));
    Vec2 tip = body.position + dir * (body.width * 0.5f);
    SDL_Point tipPt = ToScreen(tip);
    SDL_RenderDrawLine(renderer, center.x, center.y, tipPt.x, tipPt.y);
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics - Fixed Timestep",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        SCREEN_WIDTH,
        SCREEN_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    PhysicsWorld world;

    RigidBody box1;
    box1.position = Vec2(6.0f, 2.0f);
    box1.velocity = Vec2(2.0f, 0.0f);
    box1.angularVelocity = 1.5f;
    box1.SetBox(1.5f, 1.0f, 2.0f);
    box1.restitution = 0.2f;
    box1.friction = 0.7f;
    world.bodies.push_back(box1);

    RigidBody box2;
    box2.position = Vec2(10.0f, 4.0f);
    box2.velocity = Vec2(-1.0f, 0.0f);
    box2.angularVelocity = -0.8f;
    box2.SetBox(1.0f, 2.0f, 1.5f);
    box2.restitution = 0.4f;
    box2.friction = 0.5f;
    world.bodies.push_back(box2);

    bool running = true;
    Uint64 prevCounter = SDL_GetPerformanceCounter();
    double accumulator = 0.0;

    while (running) {
        Uint64 currentCounter = SDL_GetPerformanceCounter();
        double elapsed = static_cast<double>(currentCounter - prevCounter) /
                         static_cast<double>(SDL_GetPerformanceFrequency());
        prevCounter = currentCounter;

        elapsed = std::min(elapsed, static_cast<double>(MAX_FRAME_TIME));
        accumulator += elapsed;

        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
            if (event.type == SDL_KEYDOWN) {
                if (event.key.keysym.sym == SDLK_ESCAPE) {
                    running = false;
                }
                if (event.key.keysym.sym == SDLK_SPACE) {
                    RigidBody b;
                    b.position = Vec2(4.0f + static_cast<float>(world.bodies.size()), 1.0f);
                    b.velocity = Vec2(3.0f, -2.0f);
                    b.angularVelocity = 2.0f;
                    b.SetBox(1.0f, 1.0f, 1.0f);
                    b.restitution = 0.3f;
                    b.friction = 0.6f;
                    world.bodies.push_back(b);
                }
            }
        }

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            world.Step(FIXED_DT);
            accumulator -= FIXED_DT;
            ++substeps;
        }

        if (substeps == MAX_SUBSTEPS && accumulator >= FIXED_DT) {
            accumulator = 0.0;
        }

        SDL_SetRenderDrawColor(renderer, 20, 20, 30, 255);
        SDL_RenderClear(renderer);

        int groundScreenY = static_cast<int>(world.groundY * PIXELS_PER_METER);
        SDL_SetRenderDrawColor(renderer, 180, 180, 180, 255);
        SDL_RenderDrawLine(renderer, 0, groundScreenY, SCREEN_WIDTH, groundScreenY);

        SDL_SetRenderDrawColor(renderer, 80, 220, 120, 255);
        for (const auto& body : world.bodies) {
            DrawBody(renderer, body);
        }

        SDL_RenderPresent(renderer);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
