      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      dot(v) {
        return this.x * v.x + this.y * v.y;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      normalize() {
        const len = this.length();
        if (len > 0) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }

      static dot(a, b) {
        return a.x * b.x + a.y * b.y;
      }
    }

    function cross2DVecScalar(v, s) {
      return new Vec2(s * v.y, -s * v.x);
    }

    function cross2DScalarVec(s, v) {
      return new Vec2(-s * v.y, s * v.x);
    }

    function cross2D(a, b) {
      return a.x * b.y - a.y * b.x;
    }

    // -----------------------------
    // Rigid body
    // -----------------------------
    class RigidBody {
      constructor(x, y, width, height, mass = 1) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2(0, 0);
        this.force = new Vec2(0, 0);

        this.angle = 0;
        this.angularVelocity = 0;
        this.torque = 0;

        this.width = width;
        this.height = height;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Rectangle moment of inertia about center:
        // I = (1/12) * m * (w^2 + h^2)
        this.inertia = mass > 0 ? (mass * (width * width + height * height)) / 12 : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = 0.4;
        this.linearDamping = 0.999;
        this.angularDamping = 0.999;
        this.color = `hsl(${Math.random() * 360}, 70%, 60%)`;
      }

      applyForce(force, point = null) {
        this.force.add(force);
        if (point) {
          const r = Vec2.sub(point, this.position);
          this.torque += cross2D(r, force);
        }
      }

      applyImpulse(impulse, contactVector) {
        this.velocity.add(Vec2.scale(impulse, this.invMass));
        this.angularVelocity += cross2D(contactVector, impulse) * this.invInertia;
      }

      integrateForces(dt, gravity) {
        if (this.invMass === 0) return;

        this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
        this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
        this.angularVelocity += this.torque * this.invInertia * dt;
      }

      integrateVelocity(dt) {
        if (this.invMass === 0) return;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;

        this.velocity.scale(this.linearDamping);
        this.angularVelocity *= this.angularDamping;
      }

      clearForces() {
        this.force.x = 0;
        this.force.y = 0;
        this.torque = 0;
      }

      getVertices() {
        const hw = this.width / 2;
        const hh = this.height / 2;
        const c = Math.cos(this.angle);
        const s = Math.sin(this.angle);

        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh),
        ];

        return local.map(v => {
          const x = v.x * c - v.y * s + this.position.x;
          const y = v.x * s + v.y * c + this.position.y;
          return new Vec2(x, y);
        });
      }

      draw(ctx) {
        const verts = this.getVertices();
        ctx.beginPath();
        ctx.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < verts.length; i++) {
          ctx.lineTo(verts[i].x, verts[i].y);
        }
        ctx.closePath();
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = "#fff";
        ctx.stroke();

        // center marker
        ctx.beginPath();
        ctx.arc(this.position.x, this.position.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#fff";
        ctx.fill();
      }
    }

    // -----------------------------
    // Physics world
    // -----------------------------
    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 800); // pixels/s^2
        this.floorY = () => canvas.height - 50;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
        }

        // Collisions
        for (const body of this.bodies) {
          this.solveFloorCollision(body);
          body.clearForces();
        }
      }

      solveFloorCollision(body) {
        const verts = body.getVertices();
        let deepestVertex = null;
        let maxPenetration = 0;

        for (const v of verts) {
          const penetration = v.y - this.floorY();
          if (penetration > maxPenetration) {
            maxPenetration = penetration;
            deepestVertex = v;
          }
        }

        if (!deepestVertex) return;

        const normal = new Vec2(0, -1);
        const contactPoint = deepestVertex;
        const r = Vec2.sub(contactPoint, body.position);

        // Velocity at contact point
        const tangentVel = cross2DScalarVec(body.angularVelocity, r);
        const contactVel = Vec2.add(body.velocity, tangentVel);

        const velAlongNormal = Vec2.dot(contactVel, normal);

        // Only resolve if moving into floor
        if (velAlongNormal < 0) {
          const e = body.restitution;

          const rn = cross2D(r, normal);
          const invMassSum = body.invMass + (rn * rn) * body.invInertia;

          const j = -(1 + e) * velAlongNormal / invMassSum;
          const impulse = Vec2.scale(normal, j);

          body.applyImpulse(impulse, r);
        }

        // Positional correction to prevent sinking
        const percent = 0.8;
        const slop = 0.5;
        const correctionMag = Math.max(maxPenetration - slop, 0) * percent;
        body.position.y -= correctionMag;
      }

      draw(ctx) {
        // floor
        ctx.beginPath();
        ctx.moveTo(0, this.floorY());
        ctx.lineTo(canvas.width, this.floorY());
        ctx.strokeStyle = "#00d0ff";
        ctx.lineWidth = 2;
        ctx.stroke();

        for (const body of this.bodies) {
          body.draw(ctx);
        }
      }
    }

    // -----------------------------
    // Setup
    // -----------------------------
    const world = new PhysicsWorld();

    function spawnBox(x, y) {
      const w = 30 + Math.random() * 50;
      const h = 30 + Math.random() * 50;
      const mass = (w * h) / 1000;
      const body = new RigidBody(x, y, w, h, mass);

      body.velocity.x = (Math.random() - 0.5) * 200;
      body.velocity.y = Math.random() * -100;
      body.angularVelocity = (Math.random() - 0.5) * 4;

      world.addBody(body);
    }

    for (let i = 0; i < 8; i++) {
      spawnBox(200 + i * 70, 100 + i * 10);
    }

    canvas.addEventListener("click", (e) => {
      spawnBox(e.clientX, e.clientY);
    });

    // -----------------------------
    // Fixed timestep game loop
    // -----------------------------
    const FIXED_DT = 1 / 60;       // 60 Hz physics
    const MAX_FRAME_TIME = 0.25;  // clamp huge frame gaps
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Prevent spiral of death after tab switching / lag spikes
      if (frameTime > MAX_FRAME_TIME) {
        frameTime = MAX_FRAME_TIME;
      }

      accumulator += frameTime;

      while (accumulator >= FIXED_DT) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      render();
      requestAnimationFrame(loop);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      world.draw(ctx);

      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(`Bodies: ${world.bodies.length}`, 10, canvas.height - 20);
    }

    loop();
  </script>
</body>
</html>
```

