## C++ Example

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& rhs) {
        x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& rhs) {
        x -= rhs.x; y -= rhs.y; z -= rhs.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float length() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }

    static float dot(const Vec3& a, const Vec3& b) {
        return a.x*b.x + a.y*b.y + a.z*b.z;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float invMass;
    float restitution;
    float linearDamping;
    float radius; // simple sphere collider

    bool isStatic;

    RigidBody(const Vec3& pos, float m, float r, bool staticBody = false)
        : position(pos),
          velocity(0, 0, 0),
          forceAccum(0, 0, 0),
          mass(m),
          invMass((staticBody || m <= 0.0f) ? 0.0f : 1.0f / m),
          restitution(0.5f),
          linearDamping(0.999f),
          radius(r),
          isStatic(staticBody)
    {}

    void applyForce(const Vec3& force) {
        if (!isStatic) {
            forceAccum += force;
        }
    }

    void clearForces() {
        forceAccum = Vec3(0, 0, 0);
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void step(float dt) {
        // Apply global forces and integrate
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // Gravity
            body.applyForce(gravity * body.mass);

            // Acceleration
            Vec3 acceleration = body.forceAccum * body.invMass;

            // Semi-implicit Euler integration
            body.velocity += acceleration * dt;
            body.velocity *= body.linearDamping;
            body.position += body.velocity * dt;

            // Ground plane collision at y = 0
            resolveGroundCollision(body);

            body.clearForces();
        }

        // Optional: body-body collisions could go here
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        float groundY = 0.0f;
        float minY = groundY + body.radius;

        if (body.position.y < minY) {
            body.position.y = minY;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;

                // simple friction approximation
                body.velocity.x *= 0.8f;
                body.velocity.z *= 0.8f;

                // stop tiny bounces
                if (std::fabs(body.velocity.y) < 0.05f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // Add a dynamic sphere
    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f, false);

    // Fixed timestep settings
    const float fixedDt = 1.0f / 120.0f; // physics at 120 Hz
    const float maxFrameTime = 0.25f;    // avoid spiral of death
    const int targetFPS = 60;
    const auto targetFrameDuration = std::chrono::duration<double>(1.0 / targetFPS);

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    double accumulator = 0.0;

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto frameStart = clock::now();
        std::chrono::duration<double> elapsed = frameStart - previousTime;
        previousTime = frameStart;

        double frameTime = elapsed.count();
        frameTime = std::min(frameTime, static_cast<double>(maxFrameTime));
        accumulator += frameTime;

        // Example external force: push body in +X for first 2 seconds
        static double simTime = 0.0;

        while (accumulator >= fixedDt) {
            simTime += fixedDt;

            if (simTime < 2.0) {
                world.bodies[0].applyForce(Vec3(15.0f, 0.0f, 0.0f));
            }

            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render / output state
        const RigidBody& b = world.bodies[0];
        std::cout
            << "Frame " << frameCount++
            << " | Pos: (" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
            << " Vel: (" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";

        // Stop after some frames for demo
        if (frameCount > 600) {
            running = false;
        }

        // Frame-rate cap
        auto frameEnd = clock::now();
        std::chrono::duration<double> frameDuration = frameEnd - frameStart;

        if (frameDuration < targetFrameDuration) {
            auto sleepTime = targetFrameDuration - frameDuration;
            std::this_thread::sleep_for(
                std::chrono::duration_cast<std::chrono::milliseconds>(sleepTime)
            );
        }
    }

    return 0;
}
```

