        this.angularVelocity += Vec2.cross(contactVector, impulse) * this.invInertia;
      }

      integrateForces(dt, gravity) {
        if (this.invMass === 0) return;

        this.velocity = this.velocity.add(
          gravity.scale(dt).add(this.force.scale(this.invMass * dt))
        );
        this.angularVelocity += this.torque * this.invInertia * dt;
      }

      integrateVelocity(dt) {
        if (this.invMass === 0) return;

        this.position = this.position.add(this.velocity.scale(dt));
        this.angle += this.angularVelocity * dt;

        // Clear accumulated force/torque
        this.force = new Vec2(0, 0);
        this.torque = 0;
      }

      getVertices() {
        const hw = this.width / 2;
        const hh = this.height / 2;

        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh),
        ];

        return local.map(v => Vec2.rotate(v, this.angle).add(this.position));
      }

      draw(ctx, alpha = 1) {
        const verts = this.getVertices();

        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < verts.length; i++) {
          ctx.lineTo(verts[i].x, verts[i].y);
        }
        ctx.closePath();
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 2;
        ctx.stroke();

        // Draw center marker
        ctx.beginPath();
        ctx.arc(this.position.x, this.position.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#fff";
        ctx.fill();

        ctx.restore();
      }
    }

    // -----------------------------
    // Physics world
    // -----------------------------
    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 1000); // pixels/s^2
        this.groundY = 0;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Detect and resolve collisions with ground
        for (const body of this.bodies) {
          this.solveGroundCollision(body);
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
        }

        // Positional correction after movement
        for (const body of this.bodies) {
          this.correctGroundPenetration(body);
        }
      }

      solveGroundCollision(body) {
        const verts = body.getVertices();
        let deepestVertex = null;
        let maxPenetration = 0;

        for (const v of verts) {
          const penetration = v.y - this.groundY;
          if (penetration > maxPenetration) {
            maxPenetration = penetration;
            deepestVertex = v;
          }
        }

        if (!deepestVertex || maxPenetration <= 0) return;

        const normal = new Vec2(0, -1); // ground normal upward
        const r = deepestVertex.sub(body.position);

        // Velocity at contact point: v + w x r
        const contactVel = body.velocity.add(Vec2.crossScalarVec(body.angularVelocity, r));
        const velAlongNormal = contactVel.dot(normal);

        // Only resolve if moving into ground
        if (velAlongNormal >= 0) return;

        const e = body.restitution;

        const rn = Vec2.cross(r, normal);
        const invMassSum =
          body.invMass + (rn * rn) * body.invInertia;

        const j = -(1 + e) * velAlongNormal / invMassSum;
        const impulse = normal.scale(j);

        body.applyImpulse(impulse, r);

        // Friction impulse
        const tangent = contactVel.sub(normal.scale(contactVel.dot(normal))).normalize();
        if (tangent.length() > 0) {
          const rt = Vec2.cross(r, tangent);
          const denom = body.invMass + (rt * rt) * body.invInertia;
          let jt = -contactVel.dot(tangent) / denom;

          const mu = body.friction;
          jt = Math.max(-j * mu, Math.min(j * mu, jt));

          const frictionImpulse = tangent.scale(jt);
          body.applyImpulse(frictionImpulse, r);
        }
      }

      correctGroundPenetration(body) {
        const verts = body.getVertices();
        let maxPenetration = 0;

        for (const v of verts) {
          const penetration = v.y - this.groundY;
          if (penetration > maxPenetration) {
            maxPenetration = penetration;
          }
        }

        if (maxPenetration > 0) {
          // Move body upward to eliminate penetration
          body.position.y -= maxPenetration + 0.01;

          // Damp tiny residual motion to reduce jitter
          if (Math.abs(body.velocity.y) < 5) body.velocity.y = 0;
          if (Math.abs(body.angularVelocity) < 0.05) body.angularVelocity = 0;
        }
      }
    }

    // -----------------------------
    // Setup world
    // -----------------------------
    const world = new PhysicsWorld();
    world.groundY = canvas.height - 80;

    function resetScene() {
      world.bodies = [];
      world.groundY = canvas.height - 80;

      for (let i = 0; i < 8; i++) {
        const w = 40 + Math.random() * 50;
        const h = 30 + Math.random() * 50;
        const mass = (w * h) / 2000 + 0.5;

        const body = new RigidBody(
          200 + i * 70,
          80 + i * 20,
          w,
          h,
          mass
        );

        body.angle = (Math.random() - 0.5) * 0.6;
        body.velocity = new Vec2((Math.random() - 0.5) * 50, 0);
        body.angularVelocity = (Math.random() - 0.5) * 2;

        world.addBody(body);
      }
    }

    resetScene();

    window.addEventListener("keydown", (e) => {
      if (e.key === "r") resetScene();
    });

    window.addEventListener("resize", () => {
      world.groundY = canvas.height - 80;
    });

    // -----------------------------
    // Fixed timestep loop
    // -----------------------------
    const FIXED_DT = 1 / 120; // 120 Hz physics
    const MAX_FRAME_TIME = 0.25; // avoid spiral of death
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Ground
      ctx.beginPath();
      ctx.moveTo(0, world.groundY);
      ctx.lineTo(canvas.width, world.groundY);
      ctx.lineWidth = 4;
      ctx.strokeStyle = "#66ff99";
      ctx.stroke();

      // Bodies
      for (const body of world.bodies) {
        body.draw(ctx);
      }

      // Debug text
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText("Press R to reset", 10, canvas.height - 20);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Clamp frame time to prevent instability after tab switching / lag spikes
      frameTime = Math.min(frameTime, MAX_FRAME_TIME);

      accumulator += frameTime;

      while (accumulator >= FIXED_DT) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

