# C++ Example: Real-Time 2D Rigid Body Physics

```cpp
#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float PI = 3.14159265359f;

// -----------------------------
// Basic Math
// -----------------------------
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& rhs) const { return Vec2(x + rhs.x, y + rhs.y); }
    Vec2 operator-(const Vec2& rhs) const { return Vec2(x - rhs.x, y - rhs.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& rhs) { x += rhs.x; y += rhs.y; return *this; }
    Vec2& operator-=(const Vec2& rhs) { x -= rhs.x; y -= rhs.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

inline float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

inline float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

inline Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return Vec2(0, 0);
    return v / len;
}

// 2D cross products
inline float cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

inline Vec2 cross(const Vec2& v, float s) {
    return Vec2(s * v.y, -s * v.x);
}

inline Vec2 cross(float s, const Vec2& v) {
    return Vec2(-s * v.y, s * v.x);
}

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float radius = 0.5f;       // circle shape for simplicity
    float restitution = 0.5f;  // bounciness
    float linearDamping = 0.999f;
    float angularDamping = 0.999f;

    bool isStatic = false;

    RigidBody(Vec2 pos, float r, float m, bool staticBody = false)
        : position(pos), radius(r), mass(m), isStatic(staticBody)
    {
        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            invMass = 1.0f / mass;
            // Moment of inertia for solid disk: I = 1/2 m r^2
            inertia = 0.5f * mass * radius * radius;
            invInertia = 1.0f / inertia;
        }
    }

    void applyForce(const Vec2& f) {
        if (!isStatic) force += f;
    }

    void applyForceAtPoint(const Vec2& f, const Vec2& pointWorld) {
        if (isStatic) return;
        force += f;
        Vec2 r = pointWorld - position;
        torque += cross(r, f);
    }

    void applyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += cross(contactVector, impulse) * invInertia;
    }

    void integrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;

        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;

        velocity *= std::pow(linearDamping, dt * 60.0f);
        angularVelocity *= std::pow(angularDamping, dt * 60.0f);
    }

    void integrateVelocity(float dt) {
        if (isStatic) return;

        position += velocity * dt;
        angle += angularVelocity * dt;

        force = Vec2(0, 0);
        torque = 0.0f;
    }
};

// -----------------------------
// Collision Manifold
// -----------------------------
struct Contact {
    RigidBody* a = nullptr;
    RigidBody* b = nullptr;
    Vec2 normal;
    float penetration = 0.0f;
    Vec2 contactPoint;
};

// Circle-circle collision
bool detectCircleCircle(RigidBody& a, RigidBody& b, Contact& contact) {
    Vec2 delta = b.position - a.position;
    float distSq = dot(delta, delta);
    float radiusSum = a.radius + b.radius;

    if (distSq >= radiusSum * radiusSum) return false;

    float dist = std::sqrt(distSq);
    if (dist < 1e-6f) {
        contact.normal = Vec2(1.0f, 0.0f);
        contact.penetration = radiusSum;
        contact.contactPoint = a.position;
    } else {
        contact.normal = delta / dist;
        contact.penetration = radiusSum - dist;
        contact.contactPoint = a.position + contact.normal * a.radius;
    }

    contact.a = &a;
    contact.b = &b;
    return true;
}

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    Vec2 gravity = Vec2(0.0f, -9.81f);
    std::vector<RigidBody> bodies;

    float groundY = -5.0f;
    int solverIterations = 8;

    void step(float dt) {
        // Integrate forces
        for (auto& body : bodies) {
            body.integrateForces(dt, gravity);
        }

        // Detect collisions
        std::vector<Contact> contacts;

        // Body-body collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                Contact c;
                if (detectCircleCircle(bodies[i], bodies[j], c)) {
                    contacts.push_back(c);
                }
            }
        }

        // Ground collisions
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float bottom = body.position.y - body.radius;
            if (bottom < groundY) {
                Contact c;
                c.a = &body;
                c.b = nullptr;
                c.normal = Vec2(0.0f, 1.0f);
                c.penetration = groundY - bottom;
                c.contactPoint = Vec2(body.position.x, groundY);
                contacts.push_back(c);
            }
        }

        // Resolve collisions iteratively
        for (int iter = 0; iter < solverIterations; ++iter) {
            for (auto& c : contacts) {
                resolveContact(c);
            }
        }

        // Positional correction
        for (auto& c : contacts) {
            positionalCorrection(c);
        }

        // Integrate velocities
        for (auto& body : bodies) {
            body.integrateVelocity(dt);
        }
    }

private:
    void resolveContact(Contact& c) {
        RigidBody* a = c.a;
        RigidBody* b = c.b;

        Vec2 ra = c.contactPoint - a->position;
        Vec2 rb = b ? (c.contactPoint - b->position) : Vec2(0, 0);

        Vec2 va = a->velocity + cross(a->angularVelocity, ra);
        Vec2 vb = b ? (b->velocity + cross(b->angularVelocity, rb)) : Vec2(0, 0);
        Vec2 rv = vb - va;

        float velAlongNormal = dot(rv, c.normal);

        // Do not resolve if separating
        if (velAlongNormal > 0.0f) return;

        float e = b ? std::min(a->restitution, b->restitution) : a->restitution;

        float raCn = cross(ra, c.normal);
        float rbCn = b ? cross(rb, c.normal) : 0.0f;

        float invMassSum =
            a->invMass +
            (b ? b->invMass : 0.0f) +
            (raCn * raCn) * a->invInertia +
            (rbCn * rbCn) * (b ? b->invInertia : 0.0f);

        if (invMassSum < 1e-6f) return;

        float j = -(1.0f + e) * velAlongNormal;
        j /= invMassSum;

        Vec2 impulse = c.normal * j;

        a->applyImpulse(-impulse, ra);
        if (b) b->applyImpulse(impulse, rb);

        // Friction
        va = a->velocity + cross(a->angularVelocity, ra);
        vb = b ? (b->velocity + cross(b->angularVelocity, rb)) : Vec2(0, 0);
        rv = vb - va;

        Vec2 tangent = rv - c.normal * dot(rv, c.normal);
        float tangentLen = length(tangent);
        if (tangentLen > 1e-6f) tangent = tangent / tangentLen;
        else tangent = Vec2(0, 0);

        float jt = -dot(rv, tangent);
        jt /= invMassSum;

        float mu = 0.4f; // simple friction coefficient

        Vec2 frictionImpulse;
        if (std::abs(jt) < j * mu)
            frictionImpulse = tangent * jt;
        else
            frictionImpulse = tangent * (-j * mu);

        a->applyImpulse(-frictionImpulse, ra);
        if (b) b->applyImpulse(frictionImpulse, rb);
    }

    void positionalCorrection(Contact& c) {
        RigidBody* a = c.a;
        RigidBody* b = c.b;

        const float percent = 0.8f;   // correction strength
        const float slop = 0.01f;     // penetration allowance

        float invMassSum = a->invMass + (b ? b->invMass : 0.0f);
        if (invMassSum < 1e-6f) return;

        Vec2 correction = c.normal * (percent * std::max(c.penetration - slop, 0.0f) / invMassSum);

        if (!a->isStatic) a->position -= correction * a->invMass;
        if (b && !b->isStatic) b->position += correction * b->invMass;
    }
};

// -----------------------------
// Fixed Timestep Main Loop
// -----------------------------
int main() {
    PhysicsWorld world;

    // Add some bodies
    world.bodies.emplace_back(Vec2(-1.0f, 2.0f), 0.5f, 1.0f);
    world.bodies.emplace_back(Vec2(1.0f, 4.0f), 0.5f, 1.0f);
    world.bodies.emplace_back(Vec2(0.0f, 7.0f), 0.7f, 2.0f);

    world.bodies[0].velocity = Vec2(2.0f, 0.0f);
    world.bodies[1].velocity = Vec2(-1.0f, 0.0f);
    world.bodies[2].angularVelocity = 2.0f;

    const float fixedDt = 1.0f / 60.0f;
    const float maxFrameTime = 0.25f; // avoid spiral of death
    float accumulator = 0.0f;

    auto previousTime = std::chrono::high_resolution_clock::now();

    for (int frame = 0; frame < 600; ++frame) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Interpolation alpha for rendering
        float alpha = accumulator / fixedDt;

        // Example "render"
        std::cout << "Frame " << frame << " alpha=" << alpha << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ")"
                      << " Angle(" << b.angle << ")\n";
        }
        std::cout << "--------------------------\n";

        // Simulate rendering workload ~16ms/frame
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
