    Vec2() : x(0), y(0) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float Length(const Vec2& v) {
    return std::sqrt(Dot(v, v));
}

static inline Vec2 Normalize(const Vec2& v) {
    float len = Length(v);
    if (len < 1e-6f) return Vec2(0, 0);
    return v / len;
}

static inline float Cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

static inline Vec2 Cross(const Vec2& v, float s) {
    return Vec2(s * v.y, -s * v.x);
}

static inline Vec2 Cross(float s, const Vec2& v) {
    return Vec2(-s * v.y, s * v.x);
}

// -----------------------------
// Rigid body
// -----------------------------
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float angle;
    float angularVelocity;

    Vec2 force;
    float torque;

    float width, height;

    float mass;
    float invMass;
    float inertia;
    float invInertia;

    float restitution;
    float friction;

    bool isStatic;

    RigidBody(Vec2 pos, float w, float h, float m, bool staticBody = false)
        : position(pos), velocity(0, 0), angle(0), angularVelocity(0),
          force(0, 0), torque(0),
          width(w), height(h),
          mass(m), restitution(0.4f), friction(0.8f), isStatic(staticBody)
    {
        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            invMass = 1.0f / mass;
            inertia = (mass * (w * w + h * h)) / 12.0f;
            invInertia = 1.0f / inertia;
        }
    }

    void ApplyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void ApplyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * Cross(contactVector, impulse);
    }

    void IntegrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void IntegrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void ClearForces() {
        force = Vec2(0, 0);
        torque = 0.0f;
    }

    std::vector<Vec2> GetVertices() const {
        float c = std::cos(angle);
        float s = std::sin(angle);

        Vec2 half(width * 0.5f, height * 0.5f);
        std::vector<Vec2> local = {
            Vec2(-half.x, -half.y),
            Vec2( half.x, -half.y),
            Vec2( half.x,  half.y),
            Vec2(-half.x,  half.y)
        };

        std::vector<Vec2> world;
        for (auto& p : local) {
            Vec2 rotated(
                p.x * c - p.y * s,
                p.x * s + p.y * c
            );
            world.push_back(position + rotated);
        }
        return world;
    }
};

// -----------------------------
// Ground collision
// -----------------------------
void ResolveGroundCollision(RigidBody& body, float groundY) {
    if (body.isStatic) return;

    auto verts = body.GetVertices();

    float minPenetration = 0.0f;
    Vec2 contactPoint;
    bool collided = false;

    for (const auto& v : verts) {
        if (v.y > groundY) {
            float penetration = v.y - groundY;
            if (!collided || penetration > minPenetration) {
                minPenetration = penetration;
                contactPoint = v;
                collided = true;
            }
        }
    }

    if (!collided) return;

    Vec2 normal(0.0f, -1.0f);

    // Positional correction
    body.position.y -= minPenetration;

    Vec2 r = contactPoint - body.position;
    Vec2 contactVelocity = body.velocity + Cross(body.angularVelocity, r);

    float velAlongNormal = Dot(contactVelocity, normal);

    if (velAlongNormal > 0.0f) return;

    float e = body.restitution;

    float rCrossN = Cross(r, normal);
    float invMassSum = body.invMass + (rCrossN * rCrossN) * body.invInertia;

    float j = -(1.0f + e) * velAlongNormal;
    j /= invMassSum;

    Vec2 impulse = normal * j;
    body.ApplyImpulse(impulse, r);

    // Friction
    contactVelocity = body.velocity + Cross(body.angularVelocity, r);
    Vec2 tangent = contactVelocity - normal * Dot(contactVelocity, normal);

    if (Length(tangent) > 1e-6f) {
        tangent = Normalize(tangent);

        float rCrossT = Cross(r, tangent);
        float denom = body.invMass + (rCrossT * rCrossT) * body.invInertia;

        float jt = -Dot(contactVelocity, tangent);
        jt /= denom;

        float mu = body.friction;
        jt = std::clamp(jt, -j * mu, j * mu);

        Vec2 frictionImpulse = tangent * jt;
        body.ApplyImpulse(frictionImpulse, r);
    }
}

// -----------------------------
// Rendering
// -----------------------------
void DrawBody(SDL_Renderer* renderer, const RigidBody& body) {
    auto verts = body.GetVertices();

    SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
    for (size_t i = 0; i < verts.size(); ++i) {
        const Vec2& a = verts[i];
        const Vec2& b = verts[(i + 1) % verts.size()];
        SDL_RenderDrawLine(renderer, (int)a.x, (int)a.y, (int)b.x, (int)b.y);
    }
}

// -----------------------------
// Main
// -----------------------------
int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    const int screenWidth = 800;
    const int screenHeight = 600;
    const float groundY = 550.0f;

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        screenWidth,
        screenHeight,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    std::vector<RigidBody> bodies;
    bodies.emplace_back(Vec2(400, 100), 80, 40, 5.0f, false);
    bodies.back().angularVelocity = 1.5f;
    bodies.back().velocity = Vec2(40.0f, 0.0f);

    Vec2 gravity(0.0f, 980.0f); // pixels/s^2

    const float fixedDt = 1.0f / 120.0f;
    const float maxFrameTime = 0.25f;
    float accumulator = 0.0f;

    const int targetFPS = 60;
    const float targetFrameTime = 1.0f / targetFPS;

    Uint64 prevCounter = SDL_GetPerformanceCounter();
    double perfFreq = (double)SDL_GetPerformanceFrequency();

    bool running = true;
    while (running) {
        Uint64 frameStart = SDL_GetPerformanceCounter();

        // Measure elapsed time
        Uint64 currentCounter = SDL_GetPerformanceCounter();
        float frameTime = (float)((currentCounter - prevCounter) / perfFreq);
        prevCounter = currentCounter;

        if (frameTime > maxFrameTime)
            frameTime = maxFrameTime;

        accumulator += frameTime;

        // Events
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        // Fixed-step physics
        while (accumulator >= fixedDt) {
            for (auto& body : bodies) {
                body.IntegrateForces(fixedDt, gravity);
                body.IntegrateVelocity(fixedDt);
                ResolveGroundCollision(body, groundY);
                body.ClearForces();
            }

            accumulator -= fixedDt;
        }

        // Render
        SDL_SetRenderDrawColor(renderer, 20, 20, 30, 255);
        SDL_RenderClear(renderer);

        // Ground
        SDL_SetRenderDrawColor(renderer, 0, 255, 0, 255);
        SDL_RenderDrawLine(renderer, 0, (int)groundY, screenWidth, (int)groundY);

        for (const auto& body : bodies) {
            DrawBody(renderer, body);
        }

        SDL_RenderPresent(renderer);

        // Frame-rate cap
        Uint64 frameEnd = SDL_GetPerformanceCounter();
        float elapsed = (float)((frameEnd - frameStart) / perfFreq);

        if (elapsed < targetFrameTime) {
            Uint32 delayMs = (Uint32)((targetFrameTime - elapsed) * 1000.0f);
            if (delayMs > 0) SDL_Delay(delayMs);
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
