#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

constexpr float PI = 3.14159265358979323846f;

// -----------------------------
// Math Types
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return Vec3(x + b.x, y + b.y, z + b.z); }
    Vec3 operator-(const Vec3& b) const { return Vec3(x - b.x, y - b.y, z - b.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float length() const { return std::sqrt(x*x + y*y + z*z); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-8f) return Vec3();
        return *this / len;
    }

    static float dot(const Vec3& a, const Vec3& b) {
        return a.x*b.x + a.y*b.y + a.z*b.z;
    }

    static Vec3 cross(const Vec3& a, const Vec3& b) {
        return Vec3(
            a.y*b.z - a.z*b.y,
            a.z*b.x - a.x*b.z,
            a.x*b.y - a.y*b.x
        );
    }
};

inline Vec3 operator*(float s, const Vec3& v) {
    return v * s;
}

struct Mat3 {
    float m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = 0.0f;
    }

    static Mat3 identity() {
        Mat3 r;
        r.m[0][0] = r.m[1][1] = r.m[2][2] = 1.0f;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }

    Mat3 operator*(const Mat3& b) const {
        Mat3 r;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    r.m[i][j] += m[i][k] * b.m[k][j];
                }
            }
        }
        return r;
    }

    Mat3 transpose() const {
        Mat3 r;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                r.m[i][j] = m[j][i];
        return r;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& b) const {
        return Quat(w + b.w, x + b.x, y + b.y, z + b.z);
    }

    Quat operator*(float s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator*(const Quat& b) const {
        return Quat(
            w*b.w - x*b.x - y*b.y - z*b.z,
            w*b.x + x*b.w + y*b.z - z*b.y,
            w*b.y - x*b.z + y*b.w + z*b.x,
            w*b.z + x*b.y - y*b.x + z*b.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r;
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;

        r.m[0][0] = 1.0f - 2.0f*(yy + zz);
        r.m[0][1] = 2.0f*(xy - wz);
        r.m[0][2] = 2.0f*(xz + wy);

        r.m[1][0] = 2.0f*(xy + wz);
        r.m[1][1] = 1.0f - 2.0f*(xx + zz);
        r.m[1][2] = 2.0f*(yz - wx);

        r.m[2][0] = 2.0f*(xz - wy);
        r.m[2][1] = 2.0f*(yz + wx);
        r.m[2][2] = 1.0f - 2.0f*(xx + yy);

        return r;
    }
};

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;
    Mat3 invInertiaWorld;

    float radius; // simple sphere-like collision proxy

    bool isStatic;

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos), orientation(), linearVelocity(), angularVelocity(),
          forceAccum(), torqueAccum(), mass(m), radius(r), isStatic(false)
    {
        if (m <= 0.0f) {
            isStatic = true;
            mass = 0.0f;
            invMass = 0.0f;
            inertiaBody = Mat3::identity();
            invInertiaBody = Mat3();
        } else {
            invMass = 1.0f / mass;

            // Solid sphere inertia tensor: I = 2/5 m r^2
            float I = 0.4f * mass * radius * radius;
            inertiaBody = Mat3::identity();
            inertiaBody.m[0][0] = I;
            inertiaBody.m[1][1] = I;
            inertiaBody.m[2][2] = I;

            invInertiaBody = Mat3::identity();
            invInertiaBody.m[0][0] = 1.0f / I;
            invInertiaBody.m[1][1] = 1.0f / I;
            invInertiaBody.m[2][2] = 1.0f / I;
        }

        updateInvInertiaWorld();
    }

    void updateInvInertiaWorld() {
        Mat3 R = orientation.toMat3();
        invInertiaWorld = R * invInertiaBody * R.transpose();
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += Vec3::cross(r, force);
    }

    void applyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;
        linearVelocity += impulse * invMass;
        angularVelocity += invInertiaWorld * Vec3::cross(contactVector, impulse);
    }

    void clearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        linearVelocity += acceleration * dt;
        position += linearVelocity * dt;

        // Angular
        Vec3 angularAcceleration = invInertiaWorld * torqueAccum;
        angularVelocity += angularAcceleration * dt;

        Quat omega(0.0f, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        updateInvInertiaWorld();
        clearAccumulators();
    }
};

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float restitution = 0.5f;
    float linearDamping = 0.999f;
    float angularDamping = 0.998f;

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
            body.linearVelocity *= linearDamping;
            body.angularVelocity *= angularDamping;
        }

        // Resolve collisions with ground plane y = 0
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        float penetration = body.radius - body.position.y;
        if (penetration <= 0.0f) return;

        // Positional correction
        body.position.y += penetration;

        Vec3 contactNormal(0.0f, 1.0f, 0.0f);
        Vec3 contactPoint = Vec3(body.position.x, 0.0f, body.position.z);
        Vec3 r = contactPoint - body.position;

        Vec3 contactVelocity = body.linearVelocity + Vec3::cross(body.angularVelocity, r);
        float velAlongNormal = Vec3::dot(contactVelocity, contactNormal);

        if (velAlongNormal > 0.0f) return;

        Vec3 rn = Vec3::cross(r, contactNormal);
        Vec3 angularTerm = body.invInertiaWorld * rn;
        float denom = body.invMass + Vec3::dot(contactNormal, Vec3::cross(angularTerm, r));

        float j = -(1.0f + restitution) * velAlongNormal;
        if (std::abs(denom) > 1e-8f) {
            j /= denom;
        } else {
            j = 0.0f;
        }

        Vec3 impulse = contactNormal * j;
        body.applyImpulse(impulse, r);

        // Simple friction
        contactVelocity = body.linearVelocity + Vec3::cross(body.angularVelocity, r);
        Vec3 tangent = contactVelocity - contactNormal * Vec3::dot(contactVelocity, contactNormal);

        float tangentLen = tangent.length();
        if (tangentLen > 1e-6f) {
            tangent = tangent / tangentLen;

            Vec3 rt = Vec3::cross(r, tangent);
            Vec3 angularTermT = body.invInertiaWorld * rt;
            float denomT = body.invMass + Vec3::dot(tangent, Vec3::cross(angularTermT, r));

            float jt = -Vec3::dot(contactVelocity, tangent);
            if (std::abs(denomT) > 1e-8f) {
                jt /= denomT;
            } else {
                jt = 0.0f;
            }

            float mu = 0.5f;
            jt = std::clamp(jt, -mu * j, mu * j);

            Vec3 frictionImpulse = tangent * jt;
            body.applyImpulse(frictionImpulse, r);
        }
    }
};

// -----------------------------
// Main Loop with Frame-Rate Constraint
// -----------------------------
int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(2.0f, 0.5f, Vec3(0.0f, 5.0f, 0.0f));
    world.bodies[0].linearVelocity = Vec3(1.0f, 0.0f, 0.0f);
    world.bodies[0].angularVelocity = Vec3(0.0f, 2.0f, 0.5f);

    constexpr double physicsDt = 1.0 / 120.0; // fixed physics timestep
    constexpr double targetFrameTime = 1.0 / 60.0; // 60 FPS render/update cap

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    double accumulator = 0.0;

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto frameStart = clock::now();
        std::chrono::duration<double> elapsed = frameStart - previousTime;
        previousTime = frameStart;

        double frameTime = elapsed.count();

        // Prevent spiral of death on long stalls
        frameTime = std::min(frameTime, 0.25);
        accumulator += frameTime;

        // Fixed-step physics
        while (accumulator >= physicsDt) {
            world.step(static_cast<float>(physicsDt));
            accumulator -= physicsDt;
        }

        // "Render" / debug output
        const auto& body = world.bodies[0];
        std::cout
            << "Frame: " << frameCount
            << " Pos(" << body.position.x << ", " << body.position.y << ", " << body.position.z << ")"
            << " Vel(" << body.linearVelocity.x << ", " << body.linearVelocity.y << ", " << body.linearVelocity.z << ")"
            << " AngVel(" << body.angularVelocity.x << ", " << body.angularVelocity.y << ", " << body.angularVelocity.z << ")"
            << "\n";

        frameCount++;
        if (frameCount > 600) {
            running = false;
        }

        // Frame-rate cap
        auto frameEnd = clock::now();
        std::chrono::duration<double> workTime = frameEnd - frameStart;
        double sleepTime = targetFrameTime - workTime.count();

        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }
    }

    return 0;
}
