```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& r) {
        x += r.x; y += r.y; z += r.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& r) {
        x -= r.x; y -= r.y; z -= r.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float length() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vec3 normalized() const {
        float len = length();
        if (len <= 1e-6f) return Vec3();
        return *this / len;
    }

    static float dot(const Vec3& a, const Vec3& b) {
        return a.x*b.x + a.y*b.y + a.z*b.z;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float invMass;
    float restitution;
    float linearDamping;
    float radius;

    bool isStatic;

    RigidBody(
        const Vec3& pos,
        float m,
        float r,
        bool staticBody = false
    )
        : position(pos),
          velocity(0, 0, 0),
          forceAccum(0, 0, 0),
          mass(m),
          restitution(0.5f),
          linearDamping(0.999f),
          radius(r),
          isStatic(staticBody)
    {
        if (isStatic || mass <= 0.0f) {
            invMass = 0.0f;
            mass = 0.0f;
            isStatic = true;
        } else {
            invMass = 1.0f / mass;
        }
    }

    void applyForce(const Vec3& f) {
        if (!isStatic) {
            forceAccum += f;
        }
    }

    void clearForces() {
        forceAccum = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (isStatic) return;

        // a = F / m
        Vec3 acceleration = forceAccum * invMass;

        // Semi-implicit Euler integration
        velocity += acceleration * dt;
        velocity *= std::pow(linearDamping, dt * 60.0f);
        position += velocity * dt;

        clearForces();
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        solveGroundCollisions();
        solveBodyCollisions();
    }

private:
    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    void solveGroundCollisions() {
        const float groundY = 0.0f;

        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                body.position.y = groundY + body.radius;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // Simple friction approximation
                body.velocity.x *= 0.98f;
                body.velocity.z *= 0.98f;

                // Stop tiny bouncing
                if (std::fabs(body.velocity.y) < 0.05f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }

    void solveBodyCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveSphereSphere(bodies[i], bodies[j]);
            }
        }
    }

    void resolveSphereSphere(RigidBody& a, RigidBody& b) {
        if (a.isStatic && b.isStatic) return;

        Vec3 delta = b.position - a.position;
        float dist = delta.length();
        float minDist = a.radius + b.radius;

        if (dist <= 1e-6f || dist >= minDist) return;

        Vec3 normal = delta / dist;
        float penetration = minDist - dist;

        // Positional correction
        float totalInvMass = a.invMass + b.invMass;
        if (totalInvMass <= 0.0f) return;

        Vec3 correction = normal * (penetration / totalInvMass);

        if (!a.isStatic) {
            a.position -= correction * a.invMass;
        }
        if (!b.isStatic) {
            b.position += correction * b.invMass;
        }

        // Relative velocity
        Vec3 rv = b.velocity - a.velocity;
        float velAlongNormal = Vec3::dot(rv, normal);

        // Already separating
        if (velAlongNormal > 0.0f) return;

        float restitution = std::min(a.restitution, b.restitution);

        float impulseScalar = -(1.0f + restitution) * velAlongNormal;
        impulseScalar /= totalInvMass;

        Vec3 impulse = normal * impulseScalar;

        if (!a.isStatic) {
            a.velocity -= impulse * a.invMass;
        }
        if (!b.isStatic) {
            b.velocity += impulse * b.invMass;
        }
    }
};

int main() {
    PhysicsWorld world;

    world.addBody(RigidBody(Vec3(0, 10, 0), 1.0f, 0.5f));
    world.addBody(RigidBody(Vec3(0.8f, 13, 0), 1.0f, 0.5f));
    world.addBody(RigidBody(Vec3(2.0f, 20, 0), 2.0f, 0.7f));

    const float fixedDt = 1.0f / 60.0f;   // 60 Hz physics
    const float maxFrameTime = 0.25f;     // prevent spiral of death
    float accumulator = 0.0f;

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto currentTime = clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = elapsed.count();
        frameTime = std::min(frameTime, maxFrameTime);

        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Optional interpolation alpha for rendering
        float alpha = accumulator / fixedDt;
        (void)alpha;

        // Render / debug output
        std::cout << "Frame " << frameCount++ << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout
                << "Body " << i
                << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ") "
                << "Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }
        std::cout << "-------------------------\n";

        // Simulate rendering frame rate ~60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16));

        if (frameCount > 300) {
            running = false;
        }
    }

    return 0;
}
```

