#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

constexpr float PI = 3.14159265358979323846f;

// -----------------------------
// Basic Math Types
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return Vec3(x + b.x, y + b.y, z + b.z); }
    Vec3 operator-(const Vec3& b) const { return Vec3(x - b.x, y - b.y, z - b.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& b) const { return x*b.x + y*b.y + z*b.z; }

    Vec3 cross(const Vec3& b) const {
        return Vec3(
            y*b.z - z*b.y,
            z*b.x - x*b.z,
            x*b.y - y*b.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-8f) return Vec3();
        return *this / len;
    }
};

struct Mat3 {
    float m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = (i == j) ? 1.0f : 0.0f;
    }

    static Mat3 diagonal(float x, float y, float z) {
        Mat3 r;
        r.m[0][0] = x; r.m[0][1] = 0; r.m[0][2] = 0;
        r.m[1][0] = 0; r.m[1][1] = y; r.m[1][2] = 0;
        r.m[2][0] = 0; r.m[2][1] = 0; r.m[2][2] = z;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }

    Mat3 operator*(const Mat3& b) const {
        Mat3 r;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                r.m[i][j] = 0.0f;
                for (int k = 0; k < 3; ++k)
                    r.m[i][j] += m[i][k] * b.m[k][j];
            }
        }
        return r;
    }

    Mat3 transpose() const {
        Mat3 r;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                r.m[i][j] = m[j][i];
        return r;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& b) const {
        return Quat(
            w*b.w - x*b.x - y*b.y - z*b.z,
            w*b.x + x*b.w + y*b.z - z*b.y,
            w*b.y - x*b.z + y*b.w + z*b.x,
            w*b.z + x*b.y - y*b.x + z*b.w
        );
    }

    Quat operator*(float s) const {
        return Quat(w*s, x*s, y*s, z*s);
    }

    Quat operator+(const Quat& b) const {
        return Quat(w+b.w, x+b.x, y+b.y, z+b.z);
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r;
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;

        r.m[0][0] = 1.0f - 2.0f*(yy + zz);
        r.m[0][1] = 2.0f*(xy - wz);
        r.m[0][2] = 2.0f*(xz + wy);

        r.m[1][0] = 2.0f*(xy + wz);
        r.m[1][1] = 1.0f - 2.0f*(xx + zz);
        r.m[1][2] = 2.0f*(yz - wx);

        r.m[2][0] = 2.0f*(xz - wy);
        r.m[2][1] = 2.0f*(yz + wx);
        r.m[2][2] = 1.0f - 2.0f*(xx + yy);

        return r;
    }
};

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;

    float radius; // simple sphere-like collision proxy

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos), orientation(), linearVelocity(), angularVelocity(),
          forceAccum(), torqueAccum(), mass(m), radius(r)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;

        // Approximate inertia tensor for a solid sphere: I = 2/5 m r^2
        float I = 0.4f * mass * r * r;
        float invI = (I > 0.0f) ? 1.0f / I : 0.0f;

        inertiaBody = Mat3::diagonal(I, I, I);
        invInertiaBody = Mat3::diagonal(invI, invI, invI);
    }

    void applyForce(const Vec3& force) {
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += r.cross(force);
    }

    Mat3 getInvInertiaWorld() const {
        Mat3 R = orientation.toMat3();
        return R * invInertiaBody * R.transpose();
    }

    void integrate(float dt) {
        if (invMass == 0.0f) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        linearVelocity += acceleration * dt;
        position += linearVelocity * dt;

        // Angular
        Mat3 invInertiaWorld = getInvInertiaWorld();
        Vec3 angularAcceleration = invInertiaWorld * torqueAccum;
        angularVelocity += angularAcceleration * dt;

        // Quaternion derivative: q' = 0.5 * omegaQuat * q
        Quat omega(0.0f, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat qDot = omega * orientation * 0.5f;
        orientation = orientation + qDot * dt;
        orientation.normalize();

        // Clear accumulators
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }
};

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float restitution = 0.5f;
    float linearDamping = 0.999f;
    float angularDamping = 0.998f;

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
            body.linearVelocity *= linearDamping;
            body.angularVelocity *= angularDamping;
        }

        // Collisions
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        // Ground plane at y = 0
        float penetration = body.radius - body.position.y;
        if (penetration > 0.0f) {
            // Positional correction
            body.position.y = body.radius;

            Vec3 normal(0.0f, 1.0f, 0.0f);

            // Contact point at bottom of sphere proxy
            Vec3 contactPoint = body.position - normal * body.radius;
            Vec3 r = contactPoint - body.position;

            // Velocity at contact
            Vec3 contactVel = body.linearVelocity + body.angularVelocity.cross(r);
            float velAlongNormal = contactVel.dot(normal);

            if (velAlongNormal < 0.0f) {
                Mat3 invInertiaWorld = body.getInvInertiaWorld();

                Vec3 rn = r.cross(normal);
                Vec3 angularTerm = (invInertiaWorld * rn).cross(r);

                float denom = body.invMass + normal.dot(angularTerm);
                float j = -(1.0f + restitution) * velAlongNormal;
                if (denom > 1e-6f) {
                    j /= denom;
                } else {
                    j = 0.0f;
                }

                Vec3 impulse = normal * j;
                body.linearVelocity += impulse * body.invMass;
                body.angularVelocity += invInertiaWorld * r.cross(impulse);
            }

            // Simple friction
            Vec3 tangentVel = contactVel - normal * contactVel.dot(normal);
            float tangentSpeed = tangentVel.length();
            if (tangentSpeed > 1e-5f) {
                Vec3 tangent = tangentVel.normalized() * -1.0f;
                float frictionCoeff = 0.4f;
                float jt = frictionCoeff * body.mass * 9.81f * 0.016f; // approximate friction impulse

                Vec3 frictionImpulse = tangent * jt;
                body.linearVelocity += frictionImpulse * body.invMass;
            }
        }
    }
};

// -----------------------------
// Main Real-Time Loop
// -----------------------------
int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(2.0f, 0.5f, Vec3(0.0f, 5.0f, 0.0f));

    // Give it some initial motion
    world.bodies[0].linearVelocity = Vec3(2.0f, 0.0f, 0.0f);
    world.bodies[0].angularVelocity = Vec3(0.0f, 0.0f, 4.0f);

    const double fixedDt = 1.0 / 120.0;     // physics at 120 Hz
    const double targetFrameTime = 1.0 / 60.0; // render/update cap at 60 FPS

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    double accumulator = 0.0;

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto frameStart = clock::now();
        std::chrono::duration<double> elapsed = frameStart - previousTime;
        previousTime = frameStart;

        double frameTime = elapsed.count();

        // Prevent spiral of death on large stalls
        frameTime = std::min(frameTime, 0.25);

        accumulator += frameTime;

        // Fixed-step simulation
        while (accumulator >= fixedDt) {
            world.step(static_cast<float>(fixedDt));
            accumulator -= fixedDt;
        }

        // Render / Output
        const auto& body = world.bodies[0];
        std::cout
            << "Frame " << frameCount++
            << " | Pos: (" << body.position.x << ", " << body.position.y << ", " << body.position.z << ")"
            << " | LinVel: (" << body.linearVelocity.x << ", " << body.linearVelocity.y << ", " << body.linearVelocity.z << ")"
            << " | AngVel: (" << body.angularVelocity.x << ", " << body.angularVelocity.y << ", " << body.angularVelocity.z << ")"
            << "\n";

        // Stop after some frames for demo
        if (frameCount > 600) {
            running = false;
        }

        // Frame-rate cap
        auto frameEnd = clock::now();
        std::chrono::duration<double> workTime = frameEnd - frameStart;
        double sleepTime = targetFrameTime - workTime.count();

        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }
    }

    return 0;
}
```

---

## How it works

### 1. Fixed timestep
The simulation runs at a constant physics rate:

```cpp
const double fixedDt = 1.0 / 120.0;
```

This is important because rigid body solvers are much more stable with a fixed timestep than with variable frame times.

---

### 2. Frame-rate constraint
The loop caps rendering/update frequency to 60 FPS:

```cpp
const double targetFrameTime = 1.0 / 60.0;
```

At the end of each frame:

```cpp
std::this_thread::sleep_for(...)
```

This avoids maxing out the CPU unnecessarily.

---

### 3. Accumulator pattern
The accumulator allows rendering and simulation to run smoothly even if frame times vary:

```cpp
accumulator += frameTime;
while (accumulator >= fixedDt) {
    world.step(fixedDt);
    accumulator -= fixedDt;
}
```

This is the standard real-time game physics approach.

---

### 4. Rigid body integration
The body updates:

- linear velocity from force
- position from linear velocity
- angular velocity from torque
- orientation from angular velocity

This uses **semi-implicit Euler**, which is simple and more stable than explicit Euler.

---

### 5. Collision response
A simple impulse-based collision is applied against the ground plane:

- detect penetration
- correct position
- compute contact velocity
- apply normal impulse
- approximate friction

---

## Notes / Limitations

This is a **minimal engine skeleton**, not a full production solver. It does **not** include:

- body-body collision detection
- broadphase / narrowphase
- constraint solvers
- stacking stability
- continuous collision detection
- sleeping
- joints
- proper Coulomb friction solver

For a real engine, you’d typically add:

- **SAT / GJK / EPA** for collision detection
- **Sequential impulse solver**
- **Baumgarte stabilization**
- **warm starting**
- **island solving**
- **CCD**
- **multithreading**

