```js
class Vec2 {
  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
  }

  clone() {
    return new Vec2(this.x, this.y);
  }

  set(x, y) {
    this.x = x;
    this.y = y;
    return this;
  }

  add(v) {
    this.x += v.x;
    this.y += v.y;
    return this;
  }

  sub(v) {
    this.x -= v.x;
    this.y -= v.y;
    return this;
  }

  scale(s) {
    this.x *= s;
    this.y *= s;
    return this;
  }

  static add(a, b) {
    return new Vec2(a.x + b.x, a.y + b.y);
  }

  static sub(a, b) {
    return new Vec2(a.x - b.x, a.y - b.y);
  }

  static dot(a, b) {
    return a.x * b.x + a.y * b.y;
  }

  static cross(a, b) {
    return a.x * b.y - a.y * b.x;
  }

  static crossScalarVec(s, v) {
    return new Vec2(-s * v.y, s * v.x);
  }

  length() {
    return Math.sqrt(this.x * this.x + this.y * this.y);
  }

  normalize() {
    const len = this.length();
    if (len > 1e-8) {
      this.x /= len;
      this.y /= len;
    }
    return this;
  }
}

class RigidBody {
  constructor({
    position = new Vec2(),
    velocity = new Vec2(),
    angle = 0,
    angularVelocity = 0,
    mass = 1,
    width = 1,
    height = 1,
    restitution = 0.2,
    linearDamping = 0.01,
    angularDamping = 0.01,
    isStatic = false
  } = {}) {
    this.position = position;
    this.velocity = velocity;
    this.angle = angle;
    this.angularVelocity = angularVelocity;

    this.force = new Vec2();
    this.torque = 0;

    this.width = width;
    this.height = height;
    this.restitution = restitution;
    this.linearDamping = linearDamping;
    this.angularDamping = angularDamping;
    this.isStatic = isStatic;

    if (isStatic || mass <= 0) {
      this.mass = 0;
      this.invMass = 0;
      this.inertia = 0;
      this.invInertia = 0;
    } else {
      this.mass = mass;
      this.invMass = 1 / mass;
      this.inertia = (mass * (width * width + height * height)) / 12;
      this.invInertia = 1 / this.inertia;
    }
  }

  applyForce(force, point = null) {
    if (this.isStatic) return;
    this.force.add(force);

    if (point) {
      const r = Vec2.sub(point, this.position);
      this.torque += Vec2.cross(r, force);
    }
  }

  applyImpulse(impulse, contactVector = null) {
    if (this.isStatic) return;

    this.velocity.add(impulse.clone().scale(this.invMass));

    if (contactVector) {
      this.angularVelocity += Vec2.cross(contactVector, impulse) * this.invInertia;
    }
  }

  integrateForces(dt, gravity) {
    if (this.isStatic) return;

    this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
    this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
    this.angularVelocity += this.torque * this.invInertia * dt;

    this.velocity.scale(1 / (1 + this.linearDamping * dt));
    this.angularVelocity *= 1 / (1 + this.angularDamping * dt);
  }

  integrateVelocity(dt) {
    if (this.isStatic) return;

    this.position.x += this.velocity.x * dt;
    this.position.y += this.velocity.y * dt;
    this.angle += this.angularVelocity * dt;
  }

  clearAccumulators() {
    this.force.set(0, 0);
    this.torque = 0;
  }

  getHalfExtents() {
    return new Vec2(this.width * 0.5, this.height * 0.5);
  }
}

class PhysicsWorld {
  constructor({
    gravity = new Vec2(0, 9.81),
    fixedDt = 1 / 60,
    maxSubSteps = 5,
    maxFrameTime = 0.25,
    groundY = 500
  } = {}) {
    this.gravity = gravity;
    this.fixedDt = fixedDt;
    this.maxSubSteps = maxSubSteps;
    this.maxFrameTime = maxFrameTime;
    this.groundY = groundY;

    this.bodies = [];
    this.accumulator = 0;
    this.lastTime = 0;
  }

  addBody(body) {
    this.bodies.push(body);
    return body;
  }

  step(dt) {
    dt = Math.min(dt, this.maxFrameTime);
    this.accumulator += dt;

    let subSteps = 0;
    while (this.accumulator >= this.fixedDt && subSteps < this.maxSubSteps) {
      this.singleStep(this.fixedDt);
      this.accumulator -= this.fixedDt;
      subSteps++;
    }

    if (subSteps === this.maxSubSteps) {
      this.accumulator = 0;
    }
  }

  singleStep(dt) {
    for (const body of this.bodies) {
      body.integrateForces(dt, this.gravity);
    }

    for (const body of this.bodies) {
      body.integrateVelocity(dt);
    }

    for (const body of this.bodies) {
      this.solveGroundCollision(body);
    }

    for (const body of this.bodies) {
      body.clearAccumulators();
    }
  }

  solveGroundCollision(body) {
    if (body.isStatic) return;

    const half = body.getHalfExtents();
    const bottom = body.position.y + half.y;

    if (bottom > this.groundY) {
      const penetration = bottom - this.groundY;

      body.position.y -= penetration;

      if (body.velocity.y > 0) {
        body.velocity.y = -body.velocity.y * body.restitution;
      }

      const friction = 0.8;
      body.velocity.x *= friction;

      if (Math.abs(body.velocity.y) < 0.05) {
        body.velocity.y = 0;
      }
    }
  }
}

// Example usage with requestAnimationFrame
const world = new PhysicsWorld({
  gravity: new Vec2(0, 980), // pixels/s^2
  fixedDt: 1 / 120,
