#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

constexpr float EPSILON = 1e-6f;

// --------------------------------------------------
// Math types
// --------------------------------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
    Vec3& operator-=(const Vec3& r) { x -= r.x; y -= r.y; z -= r.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float length() const { return std::sqrt(x*x + y*y + z*z); }
    float lengthSq() const { return x*x + y*y + z*z; }

    Vec3 normalized() const {
        float len = length();
        if (len < EPSILON) return Vec3(0, 0, 0);
        return *this / len;
    }

    static float dot(const Vec3& a, const Vec3& b) {
        return a.x*b.x + a.y*b.y + a.z*b.z;
    }

    static Vec3 cross(const Vec3& a, const Vec3& b) {
        return Vec3(
            a.y*b.z - a.z*b.y,
            a.z*b.x - a.x*b.z,
            a.x*b.y - a.y*b.x
        );
    }
};

inline Vec3 operator*(float s, const Vec3& v) {
    return v * s;
}

struct Mat3 {
    float m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = 0.0f;
    }

    static Mat3 identity() {
        Mat3 r;
        r.m[0][0] = r.m[1][1] = r.m[2][2] = 1.0f;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }

    Mat3 operator*(const Mat3& r) const {
        Mat3 out;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                out.m[i][j] = 0.0f;
                for (int k = 0; k < 3; ++k) {
                    out.m[i][j] += m[i][k] * r.m[k][j];
                }
            }
        }
        return out;
    }

    Mat3 transpose() const {
        Mat3 t;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                t.m[i][j] = m[j][i];
        return t;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& r) const {
        return Quat(w + r.w, x + r.x, y + r.y, z + r.z);
    }

    Quat operator*(float s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator*(const Quat& r) const {
        return Quat(
            w*r.w - x*r.x - y*r.y - z*r.z,
            w*r.x + x*r.w + y*r.z - z*r.y,
            w*r.y - x*r.z + y*r.w + z*r.x,
            w*r.z + x*r.y - y*r.x + z*r.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < EPSILON) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r;
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;

        r.m[0][0] = 1.0f - 2.0f*(yy + zz);
        r.m[0][1] = 2.0f*(xy - wz);
        r.m[0][2] = 2.0f*(xz + wy);

        r.m[1][0] = 2.0f*(xy + wz);
        r.m[1][1] = 1.0f - 2.0f*(xx + zz);
        r.m[1][2] = 2.0f*(yz - wx);

        r.m[2][0] = 2.0f*(xz - wy);
        r.m[2][1] = 2.0f*(yz + wx);
        r.m[2][2] = 1.0f - 2.0f*(xx + yy);

        return r;
    }
};

// --------------------------------------------------
// Rigid body
// --------------------------------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaLocal;
    Mat3 invInertiaLocal;

    float radius;       // simple collision shape: sphere
    float restitution;  // bounciness
    float linearDamping;
    float angularDamping;

    bool isStatic;

    RigidBody()
        : position(), orientation(),
          linearVelocity(), angularVelocity(),
          forceAccum(), torqueAccum(),
          mass(1.0f), invMass(1.0f),
          inertiaLocal(Mat3::identity()),
          invInertiaLocal(Mat3::identity()),
          radius(0.5f),
          restitution(0.5f),
          linearDamping(0.999f),
          angularDamping(0.999f),
          isStatic(false) {}

    static RigidBody createSphere(float mass, float radius, const Vec3& pos, bool isStatic = false) {
        RigidBody body;
        body.position = pos;
        body.radius = radius;
        body.isStatic = isStatic;

        if (isStatic || mass <= EPSILON) {
            body.mass = 0.0f;
            body.invMass = 0.0f;
            body.inertiaLocal = Mat3();
            body.invInertiaLocal = Mat3();
        } else {
            body.mass = mass;
            body.invMass = 1.0f / mass;

            // Solid sphere inertia: I = 2/5 m r^2
            float i = 0.4f * mass * radius * radius;
            body.inertiaLocal = Mat3();
            body.inertiaLocal.m[0][0] = i;
            body.inertiaLocal.m[1][1] = i;
            body.inertiaLocal.m[2][2] = i;

            body.invInertiaLocal = Mat3();
            body.invInertiaLocal.m[0][0] = 1.0f / i;
            body.invInertiaLocal.m[1][1] = 1.0f / i;
            body.invInertiaLocal.m[2][2] = 1.0f / i;
        }

        return body;
    }

    Mat3 getInvInertiaWorld() const {
        if (isStatic) return Mat3();
        Mat3 R = orientation.toMat3();
        return R * invInertiaLocal * R.transpose();
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += Vec3::cross(r, force);
    }

    void applyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;
        linearVelocity += impulse * invMass;
        angularVelocity += getInvInertiaWorld() * Vec3::cross(contactVector, impulse);
    }

    void clearAccumulators() {
        forceAccum = Vec3(0, 0, 0);
        torqueAccum = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        linearVelocity += acceleration * dt;
        linearVelocity *= std::pow(linearDamping, dt * 60.0f);
        position += linearVelocity * dt;

        // Angular
        Vec3 angularAcc = getInvInertiaWorld() * torqueAccum;
        angularVelocity += angularAcc * dt;
        angularVelocity *= std::pow(angularDamping, dt * 60.0f);

        // Quaternion derivative: q' = 0.5 * omegaQuat * q
        Quat omega(0.0f, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

// --------------------------------------------------
// Collision
// --------------------------------------------------
struct Contact {
    int a;
    int b;
    Vec3 normal;
    Vec3 point;
    float penetration;
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float groundY = 0.0f;

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Detect collisions
        std::vector<Contact> contacts;
        detectGroundContacts(contacts);
        detectSphereSphereContacts(contacts);

        // Resolve collisions
        for (int iter = 0; iter < 8; ++iter) {
            for (const auto& c : contacts) {
                resolveContact(c);
            }
        }

        // Positional correction
        for (const auto& c : contacts) {
            positionalCorrection(c);
        }
    }

private:
    void detectGroundContacts(std::vector<Contact>& contacts) {
        for (int i = 0; i < (int)bodies.size(); ++i) {
            RigidBody& body = bodies[i];
            if (body.isStatic) continue;

            float bottom = body.position.y - body.radius;
            if (bottom < groundY) {
                Contact c;
                c.a = i;
                c.b = -1;
                c.normal = Vec3(0, 1, 0);
                c.penetration = groundY - bottom;
                c.point = Vec3(body.position.x, groundY, body.position.z);
                contacts.push_back(c);
            }
        }
    }

    void detectSphereSphereContacts(std::vector<Contact>& contacts) {
        for (int i = 0; i < (int)bodies.size(); ++i) {
            for (int j = i + 1; j < (int)bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];
                if (a.isStatic && b.isStatic) continue;

                Vec3 delta = b.position - a.position;
                float distSq = delta.lengthSq();
                float r = a.radius + b.radius;

                if (distSq < r * r) {
                    float dist = std::sqrt(std::max(distSq, EPSILON));
                    Vec3 normal = (dist > EPSILON) ? (delta / dist) : Vec3(1, 0, 0);

                    Contact c;
                    c.a = i;
                    c.b = j;
                    c.normal = normal;
                    c.penetration = r - dist;
                    c.point = a.position + normal * (a.radius - 0.5f * c.penetration);
                    contacts.push_back(c);
                }
            }
        }
    }

    void resolveContact(const Contact& c) {
        RigidBody& A = bodies[c.a];
        RigidBody* B = (c.b >= 0) ? &bodies[c.b] : nullptr;

        Vec3 ra = c.point - A.position;
        Vec3 rb = B ? (c.point - B->position) : Vec3(0, 0, 0);

        Vec3 va = A.linearVelocity + Vec3::cross(A.angularVelocity, ra);
        Vec3 vb = B ? (B->linearVelocity + Vec3::cross(B->angularVelocity, rb)) : Vec3(0, 0, 0);
        Vec3 rv = vb - va;

        float velAlongNormal = Vec3::dot(rv, c.normal);

        if (velAlongNormal > 0.0f)
            return;

        float e = B ? std::min(A.restitution, B->restitution) : A.restitution;

        float invMassSum = A.invMass + (B ? B->invMass : 0.0f);

        Vec3 raCrossN = Vec3::cross(ra, c.normal);
        Vec3 rbCrossN = Vec3::cross(rb, c.normal);

        Vec3 angA = A.getInvInertiaWorld() * raCrossN;
        float angFactorA = Vec3::dot(Vec3::cross(angA, ra), c.normal);

        float angFactorB = 0.0f;
        if (B) {
            Vec3 angB = B->getInvInertiaWorld() * rbCrossN;
            angFactorB = Vec3::dot(Vec3::cross(angB, rb), c.normal);
        }

        float denom = invMassSum + angFactorA + angFactorB;
        if (denom < EPSILON) return;

        float j = -(1.0f + e) * velAlongNormal;
        j /= denom;

        Vec3 impulse = c.normal * j;

        A.applyImpulse(-impulse, ra);
        if (B) B->applyImpulse(impulse, rb);
    }

    void positionalCorrection(const Contact& c) {
        RigidBody& A = bodies[c.a];
        RigidBody* B = (c.b >= 0) ? &bodies[c.b] : nullptr;

        const float percent = 0.8f;
        const float slop = 0.01f;

        float invMassSum = A.invMass + (B ? B->invMass : 0.0f);
        if (invMassSum < EPSILON) return;

        float correctionMag = std::max(c.penetration - slop, 0.0f) / invMassSum * percent;
        Vec3 correction = c.normal * correctionMag;

        if (!A.isStatic)
            A.position -= correction * A.invMass;

        if (B && !B->isStatic)
            B->position += correction * B->invMass;
    }
};

// --------------------------------------------------
// Real-time loop with fixed timestep
// --------------------------------------------------
int main() {
    PhysicsWorld world;

    // Static ground can be implicit via ground plane
    world.bodies.push_back(RigidBody::createSphere(1.0f, 0.5f, Vec3(0, 5, 0)));
    world.bodies.push_back(RigidBody::createSphere(2.0f, 0.7f, Vec3(0.2f, 8, 0)));
    world.bodies.push_back(RigidBody::createSphere(1.5f, 0.6f, Vec3(1.5f, 10, 0)));

    const float fixedDt = 1.0f / 60.0f;
    const float maxFrameTime = 0.25f;

    float accumulator = 0.0f;

    // Simulated frame times for demo
    std::vector<float> frameTimes = {
        0.016f, 0.017f, 0.015f, 0.020f, 0.016f,
        0.050f, 0.016f, 0.016f, 0.100f, 0.016f
    };

    for (size_t frame = 0; frame < frameTimes.size(); ++frame) {
        float frameTime = std::min(frameTimes[frame], maxFrameTime);
        accumulator += frameTime;

        int substeps = 0;
        const int maxSubsteps = 8;

        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            ++substeps;
        }

        // If we hit max substeps, drop excess time to preserve responsiveness
        if (substeps == maxSubsteps && accumulator >= fixedDt) {
            accumulator = 0.0f;
        }

        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.linearVelocity.x << ", " << b.linearVelocity.y << ", " << b.linearVelocity.z << ")"
                      << "\n";
        }
    }

    return 0;
}
