#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const {
        return Vec3(x + rhs.x, y + rhs.y, z + rhs.z);
    }

    Vec3 operator-(const Vec3& rhs) const {
        return Vec3(x - rhs.x, y - rhs.y, z - rhs.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3 operator/(float s) const {
        return Vec3(x / s, y / s, z / s);
    }

    Vec3& operator+=(const Vec3& rhs) {
        x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& rhs) {
        x -= rhs.x; y -= rhs.y; z -= rhs.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float dot(const Vec3& rhs) const {
        return x * rhs.x + y * rhs.y + z * rhs.z;
    }

    float length() const {
        return std::sqrt(dot(*this));
    }

    Vec3 normalized() const {
        float len = length();
        if (len <= 1e-6f) return Vec3();
        return *this / len;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float invMass;
    float restitution;
    float linearDamping;

    // For simple collision shape: sphere
    float radius;

    bool isStatic;

    RigidBody(
        const Vec3& pos,
        float m,
        float r,
        float rest = 0.5f,
        float damping = 0.999f,
        bool staticBody = false)
        : position(pos),
          velocity(),
          forceAccum(),
          mass(m),
          restitution(rest),
          linearDamping(damping),
          radius(r),
          isStatic(staticBody)
    {
        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            isStatic = true;
        } else {
            invMass = 1.0f / mass;
        }
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Semi-implicit Euler integration
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        velocity *= std::pow(linearDamping, dt * 60.0f);
        position += velocity * dt;

        clearForces();
    }

    void clearForces() {
        forceAccum = Vec3();
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    float fixedTimeStep = 1.0f / 60.0f;
    float accumulator = 0.0f;
    float maxFrameTime = 0.25f; // clamp to avoid spiral of death

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void update(float frameDeltaTime) {
        frameDeltaTime = std::min(frameDeltaTime, maxFrameTime);
        accumulator += frameDeltaTime;

        while (accumulator >= fixedTimeStep) {
            step(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }
    }

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        solveCollisions();
    }

private:
    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    void solveCollisions() {
        solveGroundCollisions();
        solveSphereSphereCollisions();
    }

    void solveGroundCollisions() {
        const Vec3 groundNormal(0.0f, 1.0f, 0.0f);
        const float groundY = 0.0f;
        const float friction = 0.8f;

        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                // Positional correction
                body.position.y = groundY + body.radius;

                float vn = body.velocity.dot(groundNormal);
                if (vn < 0.0f) {
                    // Reflect normal component with restitution
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // Crude tangential friction
                    body.velocity.x *= friction;
                    body.velocity.z *= friction;

                    // Sleep-ish threshold
                    if (std::fabs(body.velocity.y) < 0.05f) {
                        body.velocity.y = 0.0f;
                    }
                }
            }
        }
    }

    void solveSphereSphereCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                if (a.isStatic && b.isStatic) continue;

                Vec3 delta = b.position - a.position;
                float dist = delta.length();
                float minDist = a.radius + b.radius;

                if (dist <= 0.0f || dist >= minDist) continue;

                Vec3 normal = delta / dist;
                float penetration = minDist - dist;

                // Positional correction
                float totalInvMass = a.invMass + b.invMass;
                if (totalInvMass <= 0.0f) continue;

                Vec3 correction = normal * (penetration / totalInvMass);

                if (!a.isStatic) {
                    a.position -= correction * a.invMass;
                }
                if (!b.isStatic) {
                    b.position += correction * b.invMass;
                }

                // Relative velocity
                Vec3 relativeVelocity = b.velocity - a.velocity;
                float velAlongNormal = relativeVelocity.dot(normal);

                // Only resolve if moving toward each other
                if (velAlongNormal > 0.0f) continue;

                float restitution = std::min(a.restitution, b.restitution);

                float impulseMagnitude =
                    -(1.0f + restitution) * velAlongNormal / totalInvMass;

                Vec3 impulse = normal * impulseMagnitude;

                if (!a.isStatic) {
                    a.velocity -= impulse * a.invMass;
                }
                if (!b.isStatic) {
                    b.velocity += impulse * b.invMass;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    world.addBody(RigidBody(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f, 0.7f));
    world.addBody(RigidBody(Vec3(0.5f, 14.0f, 0.0f), 2.0f, 0.5f, 0.5f));
    world.addBody(RigidBody(Vec3(2.0f, 20.0f, 0.0f), 1.5f, 0.75f, 0.6f));

    // Simulated render loop
    const float simulatedFrameTime = 1.0f / 144.0f; // render at 144 FPS
    const float totalSimulationTime = 5.0f;

    float elapsed = 0.0f;
    while (elapsed < totalSimulationTime) {
        world.update(simulatedFrameTime);

        // Debug output
        std::cout << "Time: " << elapsed << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", "
                      << b.position.y << ", "
                      << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", "
                      << b.velocity.y << ", "
                      << b.velocity.z << ")\n";
        }

        elapsed += simulatedFrameTime;
    }

    return 0;
}
