```cpp
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    // Simplified scalar inertia for initial implementation
    float inertia;
    float invInertia;

    float linearDamping = 0.99f;
    float angularDamping = 0.98f;
    float restitution = 0.4f;

    bool isStatic = false;

    void SetMass(float m) {
        mass = m;
        if (m <= 0.0f || isStatic) {
            invMass = 0.0f;
        } else {
            invMass = 1.0f / m;
        }
    }

    void SetInertia(float i) {
        inertia = i;
        if (i <= 0.0f || isStatic) {
            invInertia = 0.0f;
        } else {
            invInertia = 1.0f / i;
        }
    }

    void ApplyForce(const Vec3& f) {
        if (isStatic) return;
        forceAccum += f;
    }

    void ApplyForceAtPoint(const Vec3& f, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += f;
        Vec3 r = worldPoint - position;
        torqueAccum += Cross(r, f);
    }

    void ApplyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;
        linearVelocity += impulse * invMass;
        angularVelocity += Cross(contactVector, impulse) * invInertia;
    }

    void ClearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }
};
