struct PhysicsWorld {
    std::vector<RigidBody*> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    void AddBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void Step(float dt) {
        ApplyGlobalForces();
        IntegrateBodies(dt);
        DetectAndResolveCollisions(dt);
        ClearForces();
    }

    void ApplyGlobalForces() {
        for (RigidBody* body : bodies) {
            if (body->isStatic || body->invMass == 0.0f) continue;
            body->ApplyForce(gravity * body->mass);
        }
    }

    void IntegrateBodies(float dt) {
        for (RigidBody* body : bodies) {
            if (body->isStatic || body->invMass == 0.0f) continue;

            // Linear
            Vec3 acceleration = body->forceAccum * body->invMass;
            body->linearVelocity += acceleration * dt;
            body->linearVelocity *= body->linearDamping;
            body->position += body->linearVelocity * dt;

            // Angular
            Vec3 angularAcc = body->torqueAccum * body->invInertia;
            body->angularVelocity += angularAcc * dt;
            body->angularVelocity *= body->angularDamping;

            // Quaternion integration
            Quat omega(0.0f,
                       body->angularVelocity.x,
                       body->angularVelocity.y,
                       body->angularVelocity.z);

            Quat dq = omega * body->orientation;
            dq = dq * 0.5f;

            body->orientation = body->orientation + dq * dt;
            body->orientation.NormalizeSelf();
        }
    }

    void DetectAndResolveCollisions(float dt) {
        // Initial scaffold:
        // 1. Ground-plane collision
        // 2. Pairwise sphere-sphere collision placeholder
        for (RigidBody* body : bodies) {
            ResolveGroundCollision(*body);
        }
    }

    void ResolveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        // Assume body is a sphere of radius 0.5 for initial implementation
        float radius = 0.5f;
        float groundY = 0.0f;

        if (body.position.y - radius < groundY) {
            body.position.y = groundY + radius;

            if (body.linearVelocity.y < 0.0f) {
                body.linearVelocity.y = -body.linearVelocity.y * body.restitution;

                // crude friction
                body.linearVelocity.x *= 0.8f;
                body.linearVelocity.z *= 0.8f;
            }
        }
    }

    void ClearForces() {
        for (RigidBody* body : bodies) {
            body->ClearAccumulators();
        }
    }
};
```

