# 5. Real-time simulation loop with frame-rate constraints

This is the important part for stable real-time behavior.

```cpp
class Engine {
public:
    PhysicsWorld physics;

    const float fixedDt = 1.0f / 60.0f;   // 60 Hz physics
    const float maxFrameTime = 0.25f;     // clamp huge stalls
    const int maxSubsteps = 5;            // frame-rate constraint

    float accumulator = 0.0f;

    void RunFrame(float frameTimeSeconds) {
        // Prevent giant catch-up after pause/hitch
        frameTimeSeconds = std::min(frameTimeSeconds, maxFrameTime);

        accumulator += frameTimeSeconds;

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            physics.Step(fixedDt);
            accumulator -= fixedDt;
            substeps++;
        }

        // If too slow, discard excess to preserve responsiveness
        if (substeps == maxSubsteps && accumulator >= fixedDt) {
            accumulator = std::fmod(accumulator, fixedDt);
        }

        float alpha = accumulator / fixedDt;
        Render(alpha);
    }

    void Render(float alpha) {
        // Interpolate between previous and current transforms if stored.
        // For initial implementation, render current state directly.
    }
};
```

