# 11. Optional improved collision scaffold

Here is a tiny impulse-based collision helper you can add later:

```cpp
void ResolveCollision(RigidBody& a, RigidBody& b, const Vec3& normal, float penetration) {
    if (a.invMass + b.invMass == 0.0f) return;

    Vec3 rv = b.linearVelocity - a.linearVelocity;
    float velAlongNormal = Dot(rv, normal);

    if (velAlongNormal > 0.0f) return;

    float e = std::min(a.restitution, b.restitution);

    float j = -(1.0f + e) * velAlongNormal;
    j /= (a.invMass + b.invMass);

    Vec3 impulse = normal * j;

    if (!a.isStatic) a.linearVelocity -= impulse * a.invMass;
    if (!b.isStatic) b.linearVelocity += impulse * b.invMass;

    // Positional correction
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent;
    Vec3 correction = normal * correctionMag;

    if (!a.isStatic) a.position -= correction * a.invMass;
    if (!b.isStatic) b.position += correction * b.invMass;
}
```

