Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Rigid Body Physics</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1b1b1b;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }
      add(v) { return new Vec2(this.x + v.x, this.y + v.y); }
      sub(v) { return new Vec2(this.x - v.x, this.y - v.y); }
      scale(s) { return new Vec2(this.x * s, this.y * s); }
      dot(v) { return this.x * v.x + this.y * v.y; }
      length() { return Math.hypot(this.x, this.y); }
      normalize() {
        const len = this.length();
        return len > 0 ? this.scale(1 / len) : new Vec2();
      }
    }

    class Body {
      constructor(x, y, radius, mass, color = "orange") {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2();
        this.force = new Vec2();
        this.radius = radius;
        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;
        this.restitution = 0.8;
        this.color = color;
      }

      applyForce(force) {
        this.force = this.force.add(force);
      }

      integrate(dt) {
        if (this.invMass === 0) return;

        const acceleration = this.force.scale(this.invMass);
        this.velocity = this.velocity.add(acceleration.scale(dt));
        this.position = this.position.add(this.velocity.scale(dt));
        this.force = new Vec2();
      }
    }

    const gravity = new Vec2(0, 500);

    const bodies = [
      new Body(200, 100, 25, 2, "#ff6b6b"),
      new Body(260, 80, 25, 2, "#4ecdc4"),
      new Body(320, 60, 25, 2, "#ffe66d"),
      new Body(500, 200, 40, 0, "#888") // static body
    ];

    bodies[0].velocity = new Vec2(80, 0);
    bodies[1].velocity = new Vec2(-40, 0);

    function resolveCircleCollision(a, b) {
      const normal = b.position.sub(a.position);
      const dist = normal.length();
      const minDist = a.radius + b.radius;

      if (dist === 0 || dist >= minDist) return;

      const n = normal.scale(1 / dist);
      const relativeVelocity = b.velocity.sub(a.velocity);
      const velAlongNormal = relativeVelocity.dot(n);

      // Don't resolve if separating
      if (velAlongNormal > 0) return;

      const e = Math.min(a.restitution, b.restitution);
      const j = -(1 + e) * velAlongNormal / (a.invMass + b.invMass);

      const impulse = n.scale(j);

      if (a.invMass > 0) {
        a.velocity = a.velocity.sub(impulse.scale(a.invMass));
      }
      if (b.invMass > 0) {
        b.velocity = b.velocity.add(impulse.scale(b.invMass));
      }

      // Positional correction
      const percent = 0.8;
      const slop = 0.01;
      const penetration = minDist - dist;
      const correctionMag = Math.max(penetration - slop, 0) / (a.invMass + b.invMass) * percent;
      const correction = n.scale(correctionMag);

      if (a.invMass > 0) {
        a.position = a.position.sub(correction.scale(a.invMass));
      }
      if (b.invMass > 0) {
        b.position = b.position.add(correction.scale(b.invMass));
      }
    }

    function resolveWallCollision(body) {
      if (body.invMass === 0) return;

      const r = body.radius;

      if (body.position.x - r < 0) {
        body.position.x = r;
        body.velocity.x *= -body.restitution;
      }
      if (body.position.x + r > canvas.width) {
        body.position.x = canvas.width - r;
        body.velocity.x *= -body.restitution;
      }
      if (body.position.y - r < 0) {
        body.position.y = r;
        body.velocity.y *= -body.restitution;
      }
      if (body.position.y + r > canvas.height) {
        body.position.y = canvas.height - r;
        body.velocity.y *= -body.restitution;
      }
    }

    function step(dt) {
      // Apply gravity
      for (const body of bodies) {
        if (body.invMass > 0) {
          body.applyForce(gravity.scale(body.mass));
        }
      }

      // Integrate
      for (const body of bodies) {
        body.integrate(dt);
      }

      // Collisions with walls
      for (const body of bodies) {
        resolveWallCollision(body);
      }

      // Body-body collisions
      for (let i = 0; i < bodies.length; i++) {
        for (let j = i + 1; j < bodies.length; j++) {
          resolveCircleCollision(bodies[i], bodies[j]);
        }
      }
    }

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (const body of bodies) {
        ctx.beginPath();
        ctx.arc(body.position.x, body.position.y, body.radius, 0, Math.PI * 2);
        ctx.fillStyle = body.color;
        ctx.fill();
      }

      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText("Minimal Real-Time Rigid Body Physics", 20, 30);
    }

    // Fixed timestep loop
    let lastTime = performance.now();
    let accumulator = 0;
    const fixedDt = 1 / 120;
    const maxFrameTime = 0.25;

    function loop(now) {
      let frameTime = (now - lastTime) / 1000;
      lastTime = now;

      // Clamp to avoid spiral of death
      if (frameTime > maxFrameTime) frameTime = maxFrameTime;

      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        step(fixedDt);
        accumulator -= fixedDt;
      }

      const alpha = accumulator / fixedDt;
      render(alpha);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);

    // Click to spawn new bodies
    canvas.addEventListener("click", (e) => {
      const radius = 15 + Math.random() * 20;
      const mass = radius * 0.1;
      const body = new Body(e.clientX, e.clientY, radius, mass,
        `hsl(${Math.random() * 360}, 80%, 60%)`);
      body.velocity = new Vec2(
        (Math.random() - 0.5) * 300,
        (Math.random() - 0.5) * 300
      );
      bodies.push(body);
    });
  </script>
</body>
</html>
```

