package com.example.payments.service;

import com.example.payments.domain.LedgerEntry;
import com.example.payments.domain.Payment;
import com.example.payments.repo.LedgerRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
public class LedgerService {

    private final LedgerRepository ledgerRepository;

    public void postEntries(Payment payment) {
        BigDecimal amount = payment.getAmount();

        LedgerEntry debit = LedgerEntry.builder()
                .paymentId(payment.getId())
                .accountId(payment.getDebtorAccountId())
                .debit(amount)
                .credit(BigDecimal.ZERO)
                .currency(payment.getCurrency())
                .build();

        LedgerEntry credit = LedgerEntry.builder()
                .paymentId(payment.getId())
                .accountId(payment.getCreditorAccountId())
                .debit(BigDecimal.ZERO)
                .credit(amount)
                .currency(payment.getCurrency())
                .build();

        ledgerRepository.save(debit);
        ledgerRepository.save(credit);
    }
}
