## PaymentService.java
```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.repo.PaymentRepository;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final BankConnector bankConnector;
    private final AuditService auditService;
    private final OutboxService outboxService;

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request,
                                         String idempotencyKey,
                                         Authentication authentication) {

        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .map(this::toResponse)
                .orElseGet(() -> createNewPayment(request, idempotencyKey, authentication));
    }

    private PaymentResponse createNewPayment(CreatePaymentRequest request,
                                             String idempotencyKey,
                                             Authentication authentication) {

        String actor = authentication.getName();

        riskService.screen(
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency()
        );

        Payment payment = Payment.builder()
                .idempotencyKey(idempotencyKey)
                .debtorAccountId(request.getDebtorAccountId())
                .creditorAccountId(request.getCreditorAccountId())
                .amount(request.getAmount())
                .currency(request.getCurrency())
                .status(PaymentStatus.PENDING)
                .build();

        payment = paymentRepository.save(payment);

        auditService.record("PAYMENT_CREATED", actor, "paymentId=" + payment.getId());

        ledgerService.postEntries(payment);

        boolean submitted = bankConnector.submit(payment);
        payment.setStatus(submitted ? PaymentStatus.SETTLED : PaymentStatus.FAILED);
        payment = paymentRepository.save(payment);

        auditService.record("PAYMENT_STATUS_UPDATED", actor,
                "paymentId=" + payment.getId() + ", status=" + payment.getStatus());

        outboxService.publishPaymentCreated(payment.getId().toString());
        if (payment.getStatus() == PaymentStatus.SETTLED) {
            outboxService.publishPaymentSettled(payment.getId().toString());
        }

        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        return PaymentResponse.builder()
                .paymentId(payment.getId())
                .debtorAccountId(payment.getDebtorAccountId())
                .creditorAccountId(payment.getCreditorAccountId())
                .amount(payment.getAmount())
                .currency(payment.getCurrency())
                .status(payment.getStatus())
                .build();
    }
}
