# 9. Payment service

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.NotFoundException;
import com.example.payments.repo.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final ComplianceService complianceService;
    private final AuditService auditService;
    private final EventPublisher eventPublisher;

    public PaymentService(
            PaymentRepository paymentRepository,
            ComplianceService complianceService,
            AuditService auditService,
            EventPublisher eventPublisher) {
        this.paymentRepository = paymentRepository;
        this.complianceService = complianceService;
        this.auditService = auditService;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String clientId, String idempotencyKey, String actor) {
        return paymentRepository.findByClientIdAndIdempotencyKey(clientId, idempotencyKey)
            .orElseGet(() -> createNewPayment(request, clientId, idempotencyKey, actor));
    }

    private Payment createNewPayment(CreatePaymentRequest request, String clientId, String idempotencyKey, String actor) {
        Payment payment = new Payment();
        payment.setClientId(clientId);
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            complianceService.screen(payment);

            if (complianceService.requiresManualReview(payment)) {
                payment.setStatus(PaymentStatus.PENDING_COMPLIANCE_REVIEW);
            } else {
                payment.setStatus(PaymentStatus.APPROVED);
            }

            Payment saved = paymentRepository.save(payment);
            auditService.record("PAYMENT_CREATED", saved, actor);
            eventPublisher.publishPaymentCreated(saved);
            return saved;

        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByClientIdAndIdempotencyKey(clientId, idempotencyKey)
                .orElseThrow(() -> ex);
        }
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
            .orElseThrow(() -> new NotFoundException("Payment not found"));
    }
}
```

