import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class PaymentServiceTest {

    @Test
    void shouldReturnExistingPaymentForSameIdempotencyKey() {
        PaymentRepository repo = mock(PaymentRepository.class);
        ComplianceService compliance = mock(ComplianceService.class);
        AuditService audit = mock(AuditService.class);
        EventPublisher publisher = mock(EventPublisher.class);

        Payment existing = new Payment();
        existing.setClientId("client-1");
        existing.setIdempotencyKey("idem-123");
        existing.setStatus(PaymentStatus.APPROVED);

        when(repo.findByClientIdAndIdempotencyKey("client-1", "idem-123"))
            .thenReturn(Optional.of(existing));

        PaymentService service = new PaymentService(repo, compliance, audit, publisher);

        CreatePaymentRequest req = new CreatePaymentRequest();
        req.setDebtorAccount("DEBTOR123");
        req.setCreditorAccount("CREDITOR123");
        req.setAmount(new BigDecimal("100.00"));
        req.setCurrency("USD");

        Payment result = service.createPayment(req, "client-1", "idem-123", "tester");

        assertSame(existing, result);
        verify(repo, times(1)).findByClientIdAndIdempotencyKey("client-1", "idem-123");
        verifyNoMoreInteractions(audit, publisher);
    }
}
