## PaymentService.java

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.PaymentValidationException;
import com.example.payments.persistence.PaymentEntity;
import com.example.payments.persistence.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final ComplianceService complianceService;
    private final LedgerService ledgerService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyService idempotencyService,
                          ComplianceService complianceService,
                          LedgerService ledgerService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.complianceService = complianceService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentEntity createPayment(CreatePaymentRequest request) {
        validateBusinessRules(request);

        var existingPaymentId = idempotencyService.findPaymentId(request.getIdempotencyKey());
        if (existingPaymentId.isPresent()) {
            return paymentRepository.findById(existingPaymentId.get())
                    .orElseThrow(() -> new IllegalStateException("Idempotency key exists but payment not found"));
        }

        PaymentEntity payment = new PaymentEntity();
        payment.setId(UUID.randomUUID());
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.PENDING);
        payment.setCreatedAt(Instant.now());

        paymentRepository.save(payment);

        try {
            idempotencyService.register(request.getIdempotencyKey(), payment.getId());
        } catch (DataIntegrityViolationException ex) {
            return idempotencyService.findPaymentId(request.getIdempotencyKey())
                    .flatMap(paymentRepository::findById)
                    .orElseThrow(() -> new IllegalStateException("Duplicate idempotency key but no payment found"));
        }

        var decision = complianceService.screen(
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference()
        );

        switch (decision) {
            case REJECT -> {
                payment.setStatus(PaymentStatus.REJECTED);
                paymentRepository.save(payment);
                auditService.record("PAYMENT_CREATE", payment.getId().toString(), "REJECTED", "Compliance rejected");
                return payment;
            }
            case REVIEW -> {
                payment.setStatus(PaymentStatus.COMPLIANCE_REVIEW);
                paymentRepository.save(payment);
                auditService.record("PAYMENT_CREATE", payment.getId().toString(), "REVIEW", "Queued for manual review");
                return payment;
            }
            case APPROVE -> {
                ledgerService.postDoubleEntry(
                        payment.getId(),
                        payment.getDebtorAccountId(),
                        payment.getCreditorAccountId(),
                        payment.getAmount(),
                        payment.getCurrency()
                );
                payment.setStatus(PaymentStatus.SETTLED);
                paymentRepository.save(payment);
                auditService.record("PAYMENT_CREATE", payment.getId().toString(), "SETTLED", "Payment settled");
                return payment;
            }
            default -> throw new IllegalStateException("Unexpected compliance decision");
        }
    }

    public PaymentEntity getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentValidationException("Payment not found"));
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new PaymentValidationException("Debtor and creditor accounts must differ");
        }

        if (request.getReference().length() > 140) {
            throw new PaymentValidationException("Reference too long");
        }
    }
}
```

