```java
package com.example.payments.service;

import com.example.payments.api.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.Locale;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final AuditService auditService;
    private final PaymentEventPublisher eventPublisher;

    public PaymentService(
            PaymentRepository paymentRepository,
            AuditService auditService,
            PaymentEventPublisher eventPublisher) {
        this.paymentRepository = paymentRepository;
        this.auditService = auditService;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setIdempotencyKey(idempotencyKey);
                    payment.setCustomerId(request.getCustomerId());
                    payment.setAmount(request.getAmount());
                    payment.setCurrency(request.getCurrency().toUpperCase(Locale.ROOT));
                    payment.setStatus(PaymentStatus.RECEIVED);

                    Payment saved = paymentRepository.save(payment);

                    auditService.record("PAYMENT_CREATED", saved.getId().toString(), saved.getCustomerId());
                    eventPublisher.publishPaymentCreated(saved.getId());

                    return saved;
                });
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
    }

    @Transactional
    public void markProcessing(UUID paymentId) {
        Payment payment = getPayment(paymentId);
        payment.setStatus(PaymentStatus.PROCESSING);
        auditService.record("PAYMENT_PROCESSING", payment.getId().toString(), payment.getCustomerId());
    }

    @Transactional
    public void markSettled(UUID paymentId) {
        Payment payment = getPayment(paymentId);
        payment.setStatus(PaymentStatus.SETTLED);
        auditService.record("PAYMENT_SETTLED", payment.getId().toString(), payment.getCustomerId());
    }

    @Transactional
    public void markFailed(UUID paymentId) {
        Payment payment = getPayment(paymentId);
        payment.setStatus(PaymentStatus.FAILED);
        auditService.record("PAYMENT_FAILED", payment.getId().toString(), payment.getCustomerId());
    }
}
