@Service
public class ComplianceService {

    public ComplianceResult evaluate(Payment payment) {
        if (payment.getAmount().compareTo(new BigDecimal("50000")) > 0) {
            return new ComplianceResult(false, true, "Manual review required");
        }

        if (payment.getDebtorAccount().equals(payment.getCreditorAccount())) {
            return new ComplianceResult(false, false, "Debtor and creditor accounts cannot be the same");
        }

        return new ComplianceResult(true, false, "Approved");
    }

    public static class ComplianceResult {
        private final boolean approved;
        private final boolean manualReview;
        private final String reason;

