# 14) Payment service

```java
package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.ApiException;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentGateway paymentGateway;
    private final AuditService auditService;
    private final ComplianceService complianceService;

    public PaymentService(
            PaymentRepository paymentRepository,
            PaymentGateway paymentGateway,
            AuditService auditService,
            ComplianceService complianceService
    ) {
        this.paymentRepository = paymentRepository;
        this.paymentGateway = paymentGateway;
        this.auditService = auditService;
        this.complianceService = complianceService;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new ApiException(HttpStatus.BAD_REQUEST, "Missing Idempotency-Key header");
        }

        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> processNewPayment(request, idempotencyKey));
    }

    public Payment getPayment(UUID id) {
        return paymentRepository.findById(id)
                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "Payment not found"));
    }

    private Payment processNewPayment(CreatePaymentRequest request, String idempotencyKey) {
        Instant now = Instant.now();

        Payment payment = new Payment();
        payment.setId(UUID.randomUUID());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);
        payment.setCreatedAt(now);
        payment.setUpdatedAt(now);

        paymentRepository.save(payment);
        auditService.record("PAYMENT_RECEIVED", payment, "Payment request received");

        payment.setStatus(PaymentStatus.VALIDATED);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment, "Basic validation passed");

        ComplianceService.ComplianceResult complianceResult = complianceService.evaluate(payment);

        if (complianceResult.isManualReview()) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            payment.setFailureReason(complianceResult.getReason());
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record("PAYMENT_PENDING_REVIEW", payment, complianceResult.getReason());
            return payment;
        }

        if (!complianceResult.isApproved()) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureReason(complianceResult.getReason());
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record("PAYMENT_REJECTED", payment, complianceResult.getReason());
            return payment;
        }

        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record("PAYMENT_PROCESSING", payment, "Sending to gateway");

        PaymentGateway.GatewayResult gatewayResult = paymentGateway.process(payment);

        if (gatewayResult.isSuccess()) {
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setFailureReason(null);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record("PAYMENT_COMPLETED", payment, gatewayResult.getMessage());
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(gatewayResult.getMessage());
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record("PAYMENT_FAILED", payment, gatewayResult.getMessage());
        }

        return payment;
    }
}
```

