## `IdempotencyService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.IdempotencyRecord;
import com.example.payments.exception.ConflictException;
import com.example.payments.repo.IdempotencyRepository;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Optional;
import java.util.UUID;

@Service
public class IdempotencyService {

    private final IdempotencyRepository idempotencyRepository;

    public IdempotencyService(IdempotencyRepository idempotencyRepository) {
        this.idempotencyRepository = idempotencyRepository;
    }

    public String hashRequest(String canonicalRequest) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonicalRequest.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (Exception e) {
            throw new IllegalStateException("Unable to hash request", e);
        }
    }

    public Optional<IdempotencyRecord> find(String key) {
        return idempotencyRepository.findByIdempotencyKey(key);
    }

    public IdempotencyRecord create(String key, String requestHash) {
        IdempotencyRecord record = new IdempotencyRecord();
        record.setId(UUID.randomUUID());
        record.setIdempotencyKey(key);
        record.setRequestHash(requestHash);
        return idempotencyRepository.save(record);
    }

    public void validateExisting(IdempotencyRecord record, String requestHash) {
        if (!record.getRequestHash().equals(requestHash)) {
            throw new ConflictException("Idempotency key reused with different request");
        }
    }

    public void attachPayment(IdempotencyRecord record, UUID paymentId) {
        record.setPaymentId(paymentId);
        idempotencyRepository.save(record);
    }
}
```

## `PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.domain.IdempotencyRecord;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.ValidationException;
import com.example.payments.repo.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.Map;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerService ledgerService;
    private final ComplianceService complianceService;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentService(
            PaymentRepository paymentRepository,
            LedgerService ledgerService,
            ComplianceService complianceService,
            AuditService auditService,
            IdempotencyService idempotencyService
    ) {
        this.paymentRepository = paymentRepository;
        this.ledgerService = ledgerService;
        this.complianceService = complianceService;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new ValidationException("Missing Idempotency-Key header");
        }

        String canonicalRequest = String.join("|",
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount().toPlainString(),
                request.getCurrency(),
                request.getReference()
        );

        String requestHash = idempotencyService.hashRequest(canonicalRequest);

        IdempotencyRecord record = idempotencyService.find(idempotencyKey)
                .map(existing -> {
                    idempotencyService.validateExisting(existing, requestHash);
                    return existing;
                })
                .orElseGet(() -> idempotencyService.create(idempotencyKey, requestHash));

        if (record.getPaymentId() != null) {
            Payment existing = paymentRepository.findById(record.getPaymentId())
                    .orElseThrow(() -> new IllegalStateException("Payment not found for idempotency record"));
            return toResponse(existing);
        }

        complianceService.screen(request);

        Payment payment = new Payment();
        payment.setId(UUID.randomUUID());
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.PENDING);

        payment = paymentRepository.save(payment);

        ledgerService.postEntries(payment);

        payment.setStatus(PaymentStatus.COMPLETED);
        payment = paymentRepository.save(payment);

        idempotencyService.attachPayment(record, payment.getId());

        auditService.log("PAYMENT_CREATED", Map.of(
                "paymentId", payment.getId(),
                "debtorAccountId", payment.getDebtorAccountId(),
                "creditorAccountId", payment.getCreditorAccountId(),
                "amount", payment.getAmount(),
                "currency", payment.getCurrency(),
                "status", payment.getStatus()
        ));

        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getId());
        response.setStatus(payment.getStatus());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setDebtorAccountId(payment.getDebtorAccountId());
        response.setCreditorAccountId(payment.getCreditorAccountId());
        response.setReference(payment.getReference());
        response.setCreatedAt(payment.getCreatedAt());
        return response;
    }
}
```

