## PaymentService.java

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerService ledgerService;
    private final RiskService riskService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          LedgerService ledgerService,
                          RiskService riskService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.ledgerService = ledgerService;
        this.riskService = riskService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request,
                                 String idempotencyKey,
                                 String correlationId,
                                 String actor) {

        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> processNewPayment(request, idempotencyKey, correlationId, actor));
    }

    private Payment processNewPayment(CreatePaymentRequest request,
                                      String idempotencyKey,
                                      String correlationId,
                                      String actor) {

        validateBusinessRules(request);

        Payment payment = new Payment(
                idempotencyKey,
                correlationId,
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency()
        );

        payment.transitionTo(PaymentStatus.VALIDATED);
        payment = paymentRepository.save(payment);

        auditService.record(
                "PAYMENT_CREATED",
                "PAYMENT",
                payment.getId().toString(),
                "Payment created and validated",
                actor,
                correlationId
        );

        RiskService.RiskDecision decision = riskService.evaluate(payment);

        if (decision.manualReviewRequired()) {
            payment.transitionTo(PaymentStatus.PENDING_REVIEW);
            payment = paymentRepository.save(payment);

            auditService.record(
                    "PAYMENT_REVIEW_REQUIRED",
                    "PAYMENT",
                    payment.getId().toString(),
                    decision.reason(),
                    actor,
                    correlationId
            );

            return payment;
        }

        if (!decision.approved()) {
            payment.transitionTo(PaymentStatus.REJECTED);
            payment = paymentRepository.save(payment);

            auditService.record(
                    "PAYMENT_REJECTED",
                    "PAYMENT",
                    payment.getId().toString(),
                    decision.reason(),
                    actor,
                    correlationId
            );

            return payment;
        }

        payment.transitionTo(PaymentStatus.APPROVED);
        payment = paymentRepository.save(payment);

        ledgerService.postPayment(payment);

        payment.transitionTo(PaymentStatus.POSTED);
        payment = paymentRepository.save(payment);

        auditService.record(
                "PAYMENT_POSTED",
                "PAYMENT",
                payment.getId().toString(),
                "Payment approved and posted to ledger",
                actor,
                correlationId
        );

        return payment;
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }
    }
}
```

