# 6. Payment service

## `PaymentService.java`

```java
package com.example.payments.application;

import com.example.payments.compliance.ComplianceService;
import com.example.payments.domain.*;
import com.example.payments.infrastructure.LedgerRepository;
import com.example.payments.infrastructure.PaymentRepository;
import com.example.payments.security.AuthorizationService;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerRepository ledgerRepository;
    private final AuthorizationService authorizationService;
    private final ComplianceService complianceService;

    public PaymentService(PaymentRepository paymentRepository,
                          LedgerRepository ledgerRepository,
                          AuthorizationService authorizationService,
                          ComplianceService complianceService) {
        this.paymentRepository = paymentRepository;
        this.ledgerRepository = ledgerRepository;
        this.authorizationService = authorizationService;
        this.complianceService = complianceService;
    }

    @Transactional
    public Payment process(String principal, PaymentRequest request) {
        authorizationService.assertCanInitiatePayment(principal, request.getDebtorAccount());

        return paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
            .orElseGet(() -> createAndProcess(request));
    }

    private Payment createAndProcess(PaymentRequest request) {
        validateBusinessRules(request);
        complianceService.screen(request);

        Payment payment = new Payment(
            UUID.randomUUID(),
            request.getIdempotencyKey(),
            request.getDebtorAccount(),
            request.getCreditorAccount(),
            request.getAmount(),
            request.getCurrency(),
            PaymentStatus.RECEIVED,
            Instant.now(),
            Instant.now()
        );

        payment.setStatus(PaymentStatus.VALIDATED);
        paymentRepository.save(payment);

        postLedgerEntries(payment);

        payment.setStatus(PaymentStatus.POSTED);
        return paymentRepository.save(payment);
    }

    private void validateBusinessRules(PaymentRequest request) {
        if (request.getAmount().scale() > 4) {
            throw new IllegalArgumentException("Amount scale exceeds supported precision");
        }
        if (request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
    }

    private void postLedgerEntries(Payment payment) {
        LedgerEntry debit = LedgerEntry.debit(
            payment.getId(),
            payment.getDebtorAccount(),
            payment.getAmount(),
            payment.getCurrency()
        );

        LedgerEntry credit = LedgerEntry.credit(
            payment.getId(),
            payment.getCreditorAccount(),
            payment.getAmount(),
            payment.getCurrency()
        );

        if (debit == null || credit == null) {
            throw new IllegalStateException("Ledger entry creation failed");
        }

        ledgerRepository.save(debit);
        ledgerRepository.save(credit);
    }
}
```

