})
public class PaymentEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID debtorAccountId;

    @Column(nullable = false)
    private UUID creditorAccountId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(nullable = false, length = 64)
    private String paymentReference;

    @Column(nullable = false, unique = true, length = 128)
    private String idempotencyKey;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(nullable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    public PaymentEntity() {}

    public PaymentEntity(
            UUID id,
            UUID debtorAccountId,
            UUID creditorAccountId,
            BigDecimal amount,
            String currency,
            String paymentReference,
            String idempotencyKey,
            PaymentStatus status,
            Instant createdAt,
            Instant updatedAt
    ) {
        this.id = id;
        this.debtorAccountId = debtorAccountId;
        this.creditorAccountId = creditorAccountId;
        this.amount = amount;
        this.currency = currency;
        this.paymentReference = paymentReference;
        this.idempotencyKey = idempotencyKey;
        this.status = status;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    public UUID getId() { return id; }
    public UUID getDebtorAccountId() { return debtorAccountId; }
    public UUID getCreditorAccountId() { return creditorAccountId; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public String getPaymentReference() { return paymentReference; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public PaymentStatus getStatus() { return status; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }

    public void setStatus(PaymentStatus status) {
        this.status = status;
        this.updatedAt = Instant.now();
    }
}
