# 9. Core payment service

```java
package com.bank.payments.service;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.api.PaymentResponse;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.persistence.entity.LedgerEntryEntity;
import com.bank.payments.persistence.entity.PaymentEntity;
import com.bank.payments.persistence.repository.LedgerEntryRepository;
import com.bank.payments.persistence.repository.PaymentRepository;
import com.bank.payments.security.SecurityUtils;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Locale;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerEntryRepository ledgerEntryRepository;
    private final AccountPolicyService accountPolicyService;
    private final ComplianceService complianceService;
    private final EventPublisher eventPublisher;
    private final AuditService auditService;

    public PaymentService(
            PaymentRepository paymentRepository,
            LedgerEntryRepository ledgerEntryRepository,
            AccountPolicyService accountPolicyService,
            ComplianceService complianceService,
            EventPublisher eventPublisher,
            AuditService auditService
    ) {
        this.paymentRepository = paymentRepository;
        this.ledgerEntryRepository = ledgerEntryRepository;
        this.accountPolicyService = accountPolicyService;
        this.complianceService = complianceService;
        this.eventPublisher = eventPublisher;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        String actor = SecurityUtils.currentActor();

        var existing = paymentRepository.findByIdempotencyKey(request.idempotencyKey());
        if (existing.isPresent()) {
            PaymentEntity payment = existing.get();
            auditService.log(actor, "PAYMENT_IDEMPOTENT_REPLAY", "PAYMENT",
                    payment.getId().toString(), "Returned existing payment for idempotency key");
            return new PaymentResponse(payment.getId(), payment.getStatus());
        }

        validateBusinessRules(request);

        Instant now = Instant.now();
        PaymentEntity payment = new PaymentEntity(
                UUID.randomUUID(),
                request.debtorAccountId(),
                request.creditorAccountId(),
                request.amount(),
                request.currency().toUpperCase(Locale.ROOT),
                request.paymentReference(),
                request.idempotencyKey(),
                PaymentStatus.RECEIVED,
                now,
                now
        );

        paymentRepository.save(payment);
        auditService.log(actor, "PAYMENT_CREATED", "PAYMENT", payment.getId().toString(), "Payment received");

        accountPolicyService.verifyAccountCanDebit(payment.getDebtorAccountId(), payment.getAmount(), payment.getCurrency());
        accountPolicyService.verifyAccountCanCredit(payment.getCreditorAccountId(), payment.getCurrency());
        payment.setStatus(PaymentStatus.VALIDATED);
        paymentRepository.save(payment);

        complianceService.screenPayment(payment);
        payment.setStatus(PaymentStatus.AUTHORIZED);
        paymentRepository.save(payment);

        postLedgerEntries(payment);
        payment.setStatus(PaymentStatus.POSTED);
        paymentRepository.save(payment);

        auditService.log(actor, "PAYMENT_POSTED", "PAYMENT", payment.getId().toString(), "Ledger entries posted");
        eventPublisher.publishPaymentPosted(payment);

        return new PaymentResponse(payment.getId(), payment.getStatus());
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.debtorAccountId().equals(request.creditorAccountId())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }
        if (!request.currency().matches("^[A-Za-z]{3}$")) {
            throw new IllegalArgumentException("Currency must be ISO-4217 alpha-3");
        }
    }

    private void postLedgerEntries(PaymentEntity payment) {
        Instant now = Instant.now();

        LedgerEntryEntity debit = new LedgerEntryEntity(
                UUID.randomUUID(),
                payment.getId(),
                payment.getDebtorAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                "DEBIT",
                now
        );

        LedgerEntryEntity credit = new LedgerEntryEntity(
                UUID.randomUUID(),
                payment.getId(),
                payment.getCreditorAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                "CREDIT",
                now
        );

        ledgerEntryRepository.save(debit);
        ledgerEntryRepository.save(credit);
    }
}
```

