# 12. Kafka event publisher

```java
package com.bank.payments.messaging;

import com.bank.payments.persistence.entity.PaymentEntity;
import com.bank.payments.service.EventPublisher;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

import java.util.Map;

@Component
public class KafkaEventPublisher implements EventPublisher {

    private final KafkaTemplate<String, Object> kafkaTemplate;

    public KafkaEventPublisher(KafkaTemplate<String, Object> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    @Override
    public void publishPaymentPosted(PaymentEntity payment) {
        Map<String, Object> event = Map.of(
                "eventType", "PAYMENT_POSTED",
                "paymentId", payment.getId().toString(),
                "debtorAccountId", payment.getDebtorAccountId().toString(),
                "creditorAccountId", payment.getCreditorAccountId().toString(),
                "amount", payment.getAmount(),
                "currency", payment.getCurrency()
        );
        kafkaTemplate.send("payments.events", payment.getId().toString(), event);
    }
}
