# 10. Core application service

## PaymentApplicationService.java

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Account;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.BusinessException;
import com.example.payments.repository.AccountRepository;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final AccountRepository accountRepository;
    private final LedgerService ledgerService;
    private final RiskScreeningService riskScreeningService;
    private final AuditService auditService;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     AccountRepository accountRepository,
                                     LedgerService ledgerService,
                                     RiskScreeningService riskScreeningService,
                                     AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.accountRepository = accountRepository;
        this.ledgerService = ledgerService;
        this.riskScreeningService = riskScreeningService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> processNewPayment(request, idempotencyKey));
    }

    private Payment processNewPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new BusinessException("Debtor and creditor accounts must differ");
        }

        Account debtor = accountRepository.findById(request.getDebtorAccountId())
                .orElseThrow(() -> new BusinessException("Debtor account not found"));

        Account creditor = accountRepository.findById(request.getCreditorAccountId())
                .orElseThrow(() -> new BusinessException("Creditor account not found"));

        if (!debtor.isActive() || !creditor.isActive()) {
            throw new BusinessException("One or more accounts are inactive");
        }

        if (!debtor.getCurrency().equals(request.getCurrency()) ||
            !creditor.getCurrency().equals(request.getCurrency())) {
            throw new BusinessException("Currency mismatch");
        }

        if (debtor.getAvailableBalance().compareTo(request.getAmount()) < 0) {
            throw new BusinessException("Insufficient funds");
        }

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference(),
                PaymentStatus.RECEIVED,
                idempotencyKey,
                Instant.now(),
                Instant.now()
        );

        paymentRepository.save(payment);
        auditService.record("PAYMENT_RECEIVED", "paymentId=" + payment.getId());

        payment.setStatus(PaymentStatus.SCREENING);
        riskScreeningService.screen(
                payment.getDebtorAccountId(),
                payment.getCreditorAccountId(),
                payment.getAmount(),
                payment.getCurrency()
        );

        payment.setStatus(PaymentStatus.APPROVED);

        debtor.debit(payment.getAmount());
        creditor.credit(payment.getAmount());

        accountRepository.save(debtor);
        accountRepository.save(creditor);

        ledgerService.postEntries(payment);

        payment.setStatus(PaymentStatus.POSTED);
        paymentRepository.save(payment);

        auditService.record("PAYMENT_POSTED", "paymentId=" + payment.getId());

        return payment;
    }
}
```

