## `Payment.java`

```java
package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(
    name = "payments",
    uniqueConstraints = {
        @UniqueConstraint(name = "uk_payment_idempotency_key", columnNames = "idempotency_key")
    }
)
public class Payment {

    @Id
    @Column(name = "payment_id", nullable = false, updatable = false)
    private String paymentId;

    @Column(name = "idempotency_key", nullable = false, updatable = false, length = 128)
    private String idempotencyKey;

    @Column(name = "debtor_account_id", nullable = false, length = 64)
    private String debtorAccountId;

    @Column(name = "creditor_account_id", nullable = false, length = 64)
    private String creditorAccountId;

    @Column(name = "amount", nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(name = "currency", nullable = false, length = 3)
    private String currency;

    @Column(name = "reference", length = 255)
    private String reference;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 32)
    private PaymentStatus status;

    @Column(name = "failure_code", length = 64)
    private String failureCode;

    @Column(name = "failure_reason", length = 512)
    private String failureReason;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    @Column(name = "version", nullable = false)
    private Long version;

    public Payment() {
    }

    public static Payment create(
            String idempotencyKey,
            String debtorAccountId,
            String creditorAccountId,
            BigDecimal amount,
            String currency,
            String reference
    ) {
        Payment payment = new Payment();
        payment.paymentId = UUID.randomUUID().toString();
        payment.idempotencyKey = idempotencyKey;
        payment.debtorAccountId = debtorAccountId;
        payment.creditorAccountId = creditorAccountId;
        payment.amount = amount;
        payment.currency = currency;
        payment.reference = reference;
        payment.status = PaymentStatus.RECEIVED;
        payment.createdAt = Instant.now();
        payment.updatedAt = payment.createdAt;
        return payment;
    }

    public void markValidated() {
        this.status = PaymentStatus.VALIDATED;
        this.updatedAt = Instant.now();
    }

    public void markProcessing() {
        this.status = PaymentStatus.PROCESSING;
        this.updatedAt = Instant.now();
    }

    public void markCompleted() {
        this.status = PaymentStatus.COMPLETED;
        this.updatedAt = Instant.now();
    }

    public void markFailed(String failureCode, String failureReason) {
        this.status = PaymentStatus.FAILED;
        this.failureCode = failureCode;
        this.failureReason = failureReason;
        this.updatedAt = Instant.now();
    }

    public void cancel() {
        this.status = PaymentStatus.CANCELLED;
        this.updatedAt = Instant.now();
    }

