```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.InvalidPaymentStateException;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidator paymentValidator;
    private final PaymentEventPublisher eventPublisher;

    public PaymentService(
            PaymentRepository paymentRepository,
            PaymentValidator paymentValidator,
            PaymentEventPublisher eventPublisher
    ) {
        this.paymentRepository = paymentRepository;
        this.paymentValidator = paymentValidator;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment createPayment(String idempotencyKey, CreatePaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> createNewPayment(idempotencyKey, request));
    }

    private Payment createNewPayment(String idempotencyKey, CreatePaymentRequest request) {
        paymentValidator.validateBusinessRules(request);

        Payment payment = Payment.create(
                idempotencyKey,
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference()
        );

        payment.markValidated();

        try {
            Payment saved = paymentRepository.save(payment);
            eventPublisher.publishPaymentCreated(saved);
            return saved;
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(idempotencyKey)
                    .orElseThrow(() -> ex);
        }
    }

    public Payment getPayment(String paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));
    }

    @Transactional
    public Payment cancelPayment(String paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));

        if (!payment.isCancellable()) {
            throw new InvalidPaymentStateException(
                    "Payment cannot be cancelled in state: " + payment.getStatus()
            );
        }

        payment.cancel();
        Payment saved = paymentRepository.save(payment);
        eventPublisher.publishPaymentCancelled(saved);
        return saved;
    }
}
```

