            String reference,
            String idempotencyKey,
            PaymentStatus status,
            Instant createdAt,
            Instant updatedAt,
            String failureReason
    ) {
        this.id = Objects.requireNonNull(id);
        this.debtorAccount = Objects.requireNonNull(debtorAccount);
        this.creditorAccount = Objects.requireNonNull(creditorAccount);
        this.money = Objects.requireNonNull(money);
        this.paymentMethod = Objects.requireNonNull(paymentMethod);
        this.reference = reference;
        this.idempotencyKey = Objects.requireNonNull(idempotencyKey);
        this.status = Objects.requireNonNull(status);
        this.createdAt = Objects.requireNonNull(createdAt);
        this.updatedAt = Objects.requireNonNull(updatedAt);
        this.failureReason = failureReason;
    }

    public void markValidated() {
        ensureState(PaymentStatus.RECEIVED);
        this.status = PaymentStatus.VALIDATED;
        this.updatedAt = Instant.now();
    }

    public void markProcessing() {
        if (status != PaymentStatus.VALIDATED) {
            throw new IllegalStateException("Payment must be VALIDATED before PROCESSING");
        }
        this.status = PaymentStatus.PROCESSING;
        this.updatedAt = Instant.now();
    }

    public void markCompleted() {
        if (status != PaymentStatus.PROCESSING) {
            throw new IllegalStateException("Payment must be PROCESSING before COMPLETED");
        }
        this.status = PaymentStatus.COMPLETED;
        this.updatedAt = Instant.now();
    }

    public void markFailed(String reason) {
        if (status != PaymentStatus.PROCESSING && status != PaymentStatus.VALIDATED) {
            throw new IllegalStateException("Payment must be VALIDATED or PROCESSING before FAILED");
        }
        this.status = PaymentStatus.FAILED;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    public void markRejected(String reason) {
        if (status != PaymentStatus.RECEIVED && status != PaymentStatus.VALIDATED) {
            throw new IllegalStateException("Payment must be RECEIVED or VALIDATED before REJECTED");
        }
        this.status = PaymentStatus.REJECTED;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    private void ensureState(PaymentStatus expected) {
        if (this.status != expected) {
            throw new IllegalStateException("Expected state " + expected + " but was " + this.status);
        }
    }

    public UUID getId() { return id; }
    public String getDebtorAccount() { return debtorAccount; }
    public String getCreditorAccount() { return creditorAccount; }
    public Money getMoney() { return money; }
    public PaymentMethod getPaymentMethod() { return paymentMethod; }
    public String getReference() { return reference; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public PaymentStatus getStatus() { return status; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public String getFailureReason() { return failureReason; }
}
