## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Money;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.InvalidPaymentException;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.persistence.PaymentEntity;
import com.example.payments.persistence.PaymentRepository;
import com.example.payments.persistence.mapper.PaymentMapper;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Currency;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessor paymentProcessor;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentProcessor paymentProcessor,
            AuditService auditService,
            IdempotencyService idempotencyService
    ) {
        this.paymentRepository = paymentRepository;
        this.paymentProcessor = paymentProcessor;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new InvalidPaymentException("Missing required idempotency key");
        }

        var existing = idempotencyService.findExisting(idempotencyKey);
        if (existing.isPresent()) {
            return PaymentMapper.toDomain(existing.get());
        }

        validateBusinessRules(request);

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                new Money(request.getAmount(), Currency.getInstance(request.getCurrency())),
                request.getPaymentMethod(),
                request.getReference(),
                idempotencyKey,
                PaymentStatus.RECEIVED,
                Instant.now(),
                Instant.now(),
                null
        );

        try {
            PaymentEntity saved = paymentRepository.save(PaymentMapper.toEntity(payment));
            auditService.record(saved.getId(), "PAYMENT_RECEIVED", "Payment created");

            Payment domainPayment = PaymentMapper.toDomain(saved);
            paymentProcessor.process(domainPayment);

            PaymentEntity updated = paymentRepository.save(PaymentMapper.toEntity(domainPayment));
            auditService.record(updated.getId(), "PAYMENT_STATUS_UPDATED", updated.getStatus());

            return PaymentMapper.toDomain(updated);
        } catch (IllegalArgumentException e) {
            throw new InvalidPaymentException("Invalid currency or amount: " + e.getMessage());
        } catch (DataIntegrityViolationException e) {
            return paymentRepository.findByIdempotencyKey(idempotencyKey)
                    .map(PaymentMapper::toDomain)
                    .orElseThrow(() -> e);
        }
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .map(PaymentMapper::toDomain)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccount().equals(request.getCreditorAccount())) {
            throw new InvalidPaymentException("Debtor and creditor accounts must differ");
        }

        if (request.getReference() != null && request.getReference().length() > 255) {
            throw new InvalidPaymentException("Reference exceeds maximum length");
        }
    }
}
