package com.bank.payments.persistence.entity;

import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.domain.PaymentType;
import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payments_client_request_id", columnList = "clientRequestId", unique = true),
        @Index(name = "idx_payments_status", columnList = "status")
})
public class PaymentEntity {

    @Id
    private UUID id;

    @Column(nullable = false, unique = true)
    private String clientRequestId;

    @Column(nullable = false)
    private String sourceAccountId;

    @Column(nullable = false)
    private String destinationAccountId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentType paymentType;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentStatus status;

    private String reference;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    @PrePersist
    public void prePersist() {
        Instant now = Instant.now();
        createdAt = now;
        updatedAt = now;
    }

    @PreUpdate
    public void preUpdate() {
        updatedAt = Instant.now();
    }

    public static PaymentEntity create(
            String clientRequestId,
            String sourceAccountId,
            String destinationAccountId,
            BigDecimal amount,
            String currency,
            PaymentType paymentType,
            String reference
    ) {
        PaymentEntity entity = new PaymentEntity();
        entity.id = UUID.randomUUID();
        entity.clientRequestId = clientRequestId;
        entity.sourceAccountId = sourceAccountId;
        entity.destinationAccountId = destinationAccountId;
        entity.amount = amount;
        entity.currency = currency;
        entity.paymentType = paymentType;
        entity.reference = reference;
        entity.status = PaymentStatus.RECEIVED;
        return entity;
    }

    public UUID getId() { return id; }
    public String getClientRequestId() { return clientRequestId; }
    public String getSourceAccountId() { return sourceAccountId; }
    public String getDestinationAccountId() { return destinationAccountId; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public PaymentType getPaymentType() { return paymentType; }
    public PaymentStatus getStatus() { return status; }
    public String getReference() { return reference; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }

    public void setStatus(PaymentStatus status) { this.status = status; }
}
