package com.bank.payments.service;

import com.bank.payments.persistence.entity.AccountEntity;
import com.bank.payments.persistence.repository.AccountRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;

@Service
public class AccountService {

    private final AccountRepository accountRepository;

    public AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    public AccountEntity getActiveAccount(String accountId) {
        AccountEntity account = accountRepository.findById(accountId)
                .orElseThrow(() -> new PaymentValidationException("Account not found: " + accountId));

        if (!account.isActive()) {
            throw new PaymentValidationException("Account inactive: " + accountId);
        }
        return account;
    }

    public void validateCurrency(AccountEntity source, AccountEntity destination, String currency) {
        if (!source.getCurrency().equals(currency) || !destination.getCurrency().equals(currency)) {
            throw new PaymentValidationException("Currency mismatch");
        }
    }

    public void ensureSufficientFunds(AccountEntity source, BigDecimal amount) {
        if (source.getAvailableBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException("Insufficient funds");
        }
    }
}
