```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.persistence.entity.AccountEntity;
import com.bank.payments.persistence.entity.PaymentEntity;
import com.bank.payments.persistence.repository.AccountRepository;
import com.bank.payments.persistence.repository.PaymentRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final AccountRepository accountRepository;
    private final AccountService accountService;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final OutboxService outboxService;
    private final ObjectMapper objectMapper;

    public PaymentService(
            PaymentRepository paymentRepository,
            AccountRepository accountRepository,
            AccountService accountService,
            RiskService riskService,
            LedgerService ledgerService,
            OutboxService outboxService,
            ObjectMapper objectMapper
    ) {
        this.paymentRepository = paymentRepository;
        this.accountRepository = accountRepository;
        this.accountService = accountService;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.outboxService = outboxService;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        return paymentRepository.findByClientRequestId(request.clientRequestId())
                .map(this::toResponse)
                .orElseGet(() -> processNewPayment(request));
    }

    private PaymentResponse processNewPayment(CreatePaymentRequest request) {
        AccountEntity source = accountService.getActiveAccount(request.sourceAccountId());
        AccountEntity destination = accountService.getActiveAccount(request.destinationAccountId());

        if (source.getId().equals(destination.getId())) {
            throw new PaymentValidationException("Source and destination accounts must differ");
        }

        accountService.validateCurrency(source, destination, request.currency());
        accountService.ensureSufficientFunds(source, request.amount());

        PaymentEntity payment = PaymentEntity.create(
                request.clientRequestId(),
                request.sourceAccountId(),
                request.destinationAccountId(),
                request.amount(),
                request.currency(),
                request.paymentType(),
                request.reference()
        );

        payment.setStatus(PaymentStatus.VALIDATED);
        paymentRepository.save(payment);

        if (riskService.requiresManualReview(
                request.sourceAccountId(),
                request.destinationAccountId(),
                request.amount())) {
            payment.setStatus(PaymentStatus.PENDING_RISK_REVIEW);
            paymentRepository.save(payment);
            publishEvent(payment, "PAYMENT_PENDING_REVIEW");
            return toResponse(payment);
        }

        source.debit(request.amount());
        destination.credit(request.amount());
        accountRepository.save(source);
        accountRepository.save(destination);

        ledgerService.postEntries(payment.getId(), source.getId(), destination.getId(), request.amount());

        payment.setStatus(PaymentStatus.POSTED);
        paymentRepository.save(payment);

        publishEvent(payment, "PAYMENT_POSTED");
        return toResponse(payment);
    }

    private void publishEvent(PaymentEntity payment, String eventType) {
        try {
            outboxService.enqueue(
                    "PAYMENT",
                    payment.getId().toString(),
                    eventType,
                    objectMapper.writeValueAsString(toResponse(payment))
            );
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize event payload", e);
        }
    }

    public PaymentResponse getPayment(java.util.UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentValidationException("Payment not found"));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(PaymentEntity payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getClientRequestId(),
                payment.getSourceAccountId(),
                payment.getDestinationAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getPaymentType(),
                payment.getStatus(),
                payment.getReference(),
                payment.getCreatedAt()
        );
    }
}
```

