package com.bank.payments.api;

import com.bank.payments.service.InsufficientFundsException;
import com.bank.payments.service.PaymentValidationException;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.*;

import java.time.Instant;
import java.util.Map;

@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler(PaymentValidationException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public Map<String, Object> handleValidation(PaymentValidationException ex) {
        return Map.of(
                "timestamp", Instant.now(),
                "error", "VALIDATION_ERROR",
                "message", ex.getMessage()
        );
    }

    @ExceptionHandler(InsufficientFundsException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, Object> handleFunds(InsufficientFundsException ex) {
        return Map.of(
                "timestamp", Instant.now(),
                "error", "INSUFFICIENT_FUNDS",
                "message", ex.getMessage()
        );
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public Map<String, Object> handleBeanValidation(MethodArgumentNotValidException ex) {
        return Map.of(
                "timestamp", Instant.now(),
                "error", "INVALID_REQUEST",
                "message", ex.getBindingResult().toString()
        );
    }
}
