# 11. Application service

## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentProcessor;
import com.example.payments.domain.PaymentRepository;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.exception.ValidationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessor paymentProcessor;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     PaymentProcessor paymentProcessor,
                                     IdempotencyService idempotencyService,
                                     AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.paymentProcessor = paymentProcessor;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new ValidationException("Missing required Idempotency-Key header");
        }

        return idempotencyService.findExisting(idempotencyKey)
                .orElseGet(() -> createAndProcessPayment(request, idempotencyKey));
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    private Payment createAndProcessPayment(CreatePaymentRequest request, String idempotencyKey) {
        Payment payment = Payment.createNew(
                idempotencyKey,
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference()
        );

        auditService.record("PAYMENT_RECEIVED", payment);

        validateBusinessRules(payment);
        payment.markValidated();
        paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment);

        payment.markProcessing();
        paymentRepository.save(payment);
        auditService.record("PAYMENT_PROCESSING", payment);

        paymentProcessor.process(payment);
        paymentRepository.save(payment);

        auditService.record("PAYMENT_" + payment.getStatus().name(), payment);

        return payment;
    }

    private void validateBusinessRules(Payment payment) {
        if (payment.getDebtorAccount().equals(payment.getCreditorAccount())) {
            payment.markRejected("Debtor and creditor accounts must differ");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_REJECTED", payment);
            throw new ValidationException("Debtor and creditor accounts must differ");
        }

        if (!payment.getCurrency().matches("^[A-Z]{3}$")) {
            payment.markRejected("Invalid currency");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_REJECTED", payment);
            throw new ValidationException("Invalid currency");
        }
    }
}
```

