## Domain: `Payment`

```java
package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments",
       uniqueConstraints = {
           @UniqueConstraint(name = "uk_payment_idempotency_key", columnNames = "idempotency_key")
       })
public class Payment {

    @Id
    @Column(name = "payment_id", nullable = false, updatable = false)
    private UUID paymentId;

    @Column(name = "client_reference", nullable = false, length = 100)
    private String clientReference;

    @Column(name = "debtor_account", nullable = false, length = 34)
    private String debtorAccount;

    @Column(name = "creditor_account", nullable = false, length = 34)
    private String creditorAccount;

    @Column(name = "currency", nullable = false, length = 3)
    private String currency;

    @Column(name = "amount", nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(name = "description", length = 255)
    private String description;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 30)
    private PaymentStatus status;

    @Column(name = "idempotency_key", nullable = false, length = 100)
    private String idempotencyKey;

    @Column(name = "correlation_id", nullable = false, length = 100)
    private String correlationId;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    @Column(name = "version", nullable = false)
    private Long version;

    protected Payment() {
    }

    public Payment(
            UUID paymentId,
            String clientReference,
            String debtorAccount,
            String creditorAccount,
            String currency,
            BigDecimal amount,
            String description,
            String idempotencyKey,
            String correlationId
    ) {
        this.paymentId = paymentId;
        this.clientReference = clientReference;
        this.debtorAccount = debtorAccount;
        this.creditorAccount = creditorAccount;
        this.currency = currency;
        this.amount = amount;
        this.description = description;
        this.idempotencyKey = idempotencyKey;
        this.correlationId = correlationId;
        this.status = PaymentStatus.RECEIVED;
        this.createdAt = Instant.now();
        this.updatedAt = this.createdAt;
    }

    public void markValidated() {
        transitionTo(PaymentStatus.VALIDATED);
    }

    public void markPendingApproval() {
        transitionTo(PaymentStatus.PENDING_APPROVAL);
    }

    public void approve() {
        if (status != PaymentStatus.PENDING_APPROVAL && status != PaymentStatus.VALIDATED) {
            throw new IllegalStateException("Payment cannot be approved from status: " + status);
        }
        transitionTo(PaymentStatus.APPROVED);
    }

    public void reject() {
        if (status == PaymentStatus.COMPLETED || status == PaymentStatus.CANCELLED) {
            throw new IllegalStateException("Payment cannot be rejected from status: " + status);
        }
        transitionTo(PaymentStatus.REJECTED);
    }

    public void markProcessing() {
        if (status != PaymentStatus.APPROVED) {
            throw new IllegalStateException("Payment cannot move to PROCESSING from status: " + status);
        }
        transitionTo(PaymentStatus.PROCESSING);
    }

    public void complete() {
        if (status != PaymentStatus.PROCESSING) {
            throw new IllegalStateException("Payment cannot be completed from status: " + status);
        }
        transitionTo(PaymentStatus.COMPLETED);
    }

    public void fail() {
        if (status == PaymentStatus.COMPLETED) {
            throw new IllegalStateException("Completed payment cannot fail");
        }
        transitionTo(PaymentStatus.FAILED);
    }

    public void cancel() {
        if (status == PaymentStatus.COMPLETED) {
            throw new IllegalStateException("Completed payment cannot be cancelled");
        }
        transitionTo(PaymentStatus.CANCELLED);
    }

    private void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    public UUID getPaymentId() { return paymentId; }
    public String getClientReference() { return clientReference; }
    public String getDebtorAccount() { return debtorAccount; }
    public String getCreditorAccount() { return creditorAccount; }
    public String getCurrency() { return currency; }
    public BigDecimal getAmount() { return amount; }
    public String getDescription() { return description; }
    public PaymentStatus getStatus() { return status; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getCorrelationId() { return correlationId; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public Long getVersion() { return version; }
}
```

