## Event publisher

```java
package com.example.payments.infrastructure.events;

import com.example.payments.domain.Payment;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;

import java.util.Map;

@Component
public class PaymentEventPublisher {

    private final OutboxEventRepository outboxEventRepository;
    private final ObjectMapper objectMapper;

    public PaymentEventPublisher(OutboxEventRepository outboxEventRepository, ObjectMapper objectMapper) {
        this.outboxEventRepository = outboxEventRepository;
        this.objectMapper = objectMapper;
    }

    public void publishPaymentCreated(Payment payment) {
        saveEvent(payment, "PaymentCreated");
    }

    public void publishPaymentStatusChanged(Payment payment) {
        saveEvent(payment, "PaymentStatusChanged");
    }

    private void saveEvent(Payment payment, String eventType) {
        try {
            String payload = objectMapper.writeValueAsString(Map.of(
                    "paymentId", payment.getPaymentId(),
                    "clientReference", payment.getClientReference(),
                    "status", payment.getStatus(),
                    "amount", payment.getAmount(),
                    "currency", payment.getCurrency(),
                    "correlationId", payment.getCorrelationId()
            ));

            outboxEventRepository.save(
                    new OutboxEvent(
                            "Payment",
                            payment.getPaymentId().toString(),
                            eventType,
                            payload
                    )
            );
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("Failed to serialize payment event", e);
        }
    }
}
```

