## Application service

```java
package com.example.payments.application;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentAudit;
import com.example.payments.domain.PaymentAuditRepository;
import com.example.payments.domain.PaymentRepository;
import com.example.payments.infrastructure.events.PaymentEventPublisher;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentAuditRepository paymentAuditRepository;
    private final PaymentEventPublisher paymentEventPublisher;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentAuditRepository paymentAuditRepository,
            PaymentEventPublisher paymentEventPublisher
    ) {
        this.paymentRepository = paymentRepository;
        this.paymentAuditRepository = paymentAuditRepository;
        this.paymentEventPublisher = paymentEventPublisher;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey, String correlationId) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    Payment payment = new Payment(
                            UUID.randomUUID(),
                            request.getClientReference(),
                            request.getDebtorAccount(),
                            request.getCreditorAccount(),
                            request.getCurrency(),
                            request.getAmount(),
                            request.getDescription(),
                            idempotencyKey,
                            correlationId
                    );

                    payment.markValidated();
                    payment.markPendingApproval();

                    Payment saved = paymentRepository.save(payment);
                    paymentAuditRepository.save(new PaymentAudit(saved.getPaymentId(), "PAYMENT_CREATED", "Payment created"));
                    paymentEventPublisher.publishPaymentCreated(saved);
                    return saved;
                });
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new EntityNotFoundException("Payment not found: " + paymentId));
    }

    @Transactional
    public Payment approvePayment(UUID paymentId, String reason) {
        Payment payment = getPayment(paymentId);
        payment.approve();
        Payment saved = paymentRepository.save(payment);
        paymentAuditRepository.save(new PaymentAudit(paymentId, "PAYMENT_APPROVED", reason));
        paymentEventPublisher.publishPaymentStatusChanged(saved);
        return saved;
    }

    @Transactional
    public Payment rejectPayment(UUID paymentId, String reason) {
        Payment payment = getPayment(paymentId);
        payment.reject();
        Payment saved = paymentRepository.save(payment);
        paymentAuditRepository.save(new PaymentAudit(paymentId, "PAYMENT_REJECTED", reason));
        paymentEventPublisher.publishPaymentStatusChanged(saved);
        return saved;
    }
}
```

