## REST controller

```java
package com.example.payments.api;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.DecisionRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.application.PaymentApplicationService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentApplicationService paymentApplicationService;

    public PaymentController(PaymentApplicationService paymentApplicationService) {
        this.paymentApplicationService = paymentApplicationService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse createPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId,
            @Valid @RequestBody CreatePaymentRequest request
    ) {
        String effectiveCorrelationId = correlationId != null ? correlationId : UUID.randomUUID().toString();
        return PaymentResponse.from(
                paymentApplicationService.createPayment(request, idempotencyKey, effectiveCorrelationId)
        );
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        return PaymentResponse.from(paymentApplicationService.getPayment(paymentId));
    }

    @PostMapping("/{paymentId}/approve")
    public PaymentResponse approvePayment(
            @PathVariable UUID paymentId,
            @Valid @RequestBody(required = false) DecisionRequest request
    ) {
        String reason = request != null ? request.getReason() : null;
        return PaymentResponse.from(paymentApplicationService.approvePayment(paymentId, reason));
    }

    @PostMapping("/{paymentId}/reject")
    public PaymentResponse rejectPayment(
            @PathVariable UUID paymentId,
            @Valid @RequestBody(required = false) DecisionRequest request
    ) {
        String reason = request != null ? request.getReason() : null;
        return PaymentResponse.from(paymentApplicationService.rejectPayment(paymentId, reason));
    }
}
