    details varchar(1000),
    created_at timestamp with time zone not null
);

create table outbox_events (
    id bigserial primary key,
    event_id uuid not null unique,
    aggregate_type varchar(100) not null,
    aggregate_id varchar(100) not null,
    event_type varchar(100) not null,
    payload text not null,
    created_at timestamp with time zone not null,
    published boolean not null
);

create index idx_payment_status on payments(status);
create index idx_payment_created_at on payments(created_at);
create index idx_payment_audit_payment_id on payment_audit(payment_id);
create index idx_outbox_published_created_at on outbox_events(published, created_at);
