# 10. Application Service

## `PaymentApplicationService.java`

```java
package com.example.payment.application;

import com.example.payment.domain.Payment;
import com.example.payment.domain.PaymentStatus;
import com.example.payment.dto.CreatePaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.repository.PaymentRepository;
import com.example.payment.support.AuditService;
import com.example.payment.support.IdempotencyService;
import com.example.payment.support.PaymentValidator;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidator paymentValidator;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     PaymentValidator paymentValidator,
                                     IdempotencyService idempotencyService,
                                     AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.paymentValidator = paymentValidator;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        var existing = idempotencyService.findExisting(request.getIdempotencyKey());
        if (existing.isPresent()) {
            return toResponse(existing.get());
        }

        paymentValidator.validateBusinessRules(request);

        Payment payment = new Payment();
        payment.setClientPaymentId(request.getClientPaymentId());
        payment.setIdempotencyKey(request.getIdempotencyKey());
        payment.setPaymentType(request.getPaymentType());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_CREATED", payment);

            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_VALIDATED", payment);

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_PROCESSING", payment);

            // Placeholder for actual payment execution / core banking integration
            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_COMPLETED", payment);

            return toResponse(payment);
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                    .map(this::toResponse)
                    .orElseThrow(() -> ex);
        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(ex.getMessage());
            paymentRepository.save(payment);
            auditService.record("PAYMENT_FAILED", payment);
            throw ex;
        }
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new EntityNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getId());
        response.setClientPaymentId(payment.getClientPaymentId());
        response.setPaymentType(payment.getPaymentType());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setDebtorAccount(payment.getDebtorAccount());
        response.setCreditorAccount(payment.getCreditorAccount());
        response.setReference(payment.getReference());
        response.setStatus(payment.getStatus());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
```

