# 11. Core processing service

## `PaymentProcessingService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.dto.PaymentStatusResponse;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.integration.SettlementGateway;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final AuditService auditService;
    private final SettlementGateway settlementGateway;

    public PaymentProcessingService(PaymentRepository paymentRepository,
                                    PaymentValidationService validationService,
                                    AuditService auditService,
                                    SettlementGateway settlementGateway) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.auditService = auditService;
        this.settlementGateway = settlementGateway;
    }

    @Transactional
    public PaymentResponse createPayment(String idempotencyKey, CreatePaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .map(this::toPaymentResponse)
                .orElseGet(() -> createNewPayment(idempotencyKey, request));
    }

    private PaymentResponse createNewPayment(String idempotencyKey, CreatePaymentRequest request) {
        validationService.validateBusinessRules(request);

        Payment payment = new Payment();
        payment.setIdempotencyKey(idempotencyKey);
        payment.setClientReference(request.getClientReference());
        payment.setPaymentType(request.getPaymentType());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            payment = paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_RECEIVED", "Payment request accepted");

            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_VALIDATED", "Business validation passed");

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_PROCESSING", "Payment sent for settlement");

            boolean settled = settlementGateway.settle(payment);

            if (settled) {
                payment.setStatus(PaymentStatus.SETTLED);
                payment.setFailureReason(null);
                auditService.record(payment, "PAYMENT_SETTLED", "Settlement completed successfully");
            } else {
                payment.setStatus(PaymentStatus.FAILED);
                payment.setFailureReason("Settlement gateway rejected payment");
                auditService.record(payment, "PAYMENT_FAILED", "Settlement failed");
            }

            payment = paymentRepository.save(payment);
            return toPaymentResponse(payment);

        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(idempotencyKey)
                    .map(this::toPaymentResponse)
                    .orElseThrow(() -> ex);
        } catch (IllegalArgumentException ex) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureReason(ex.getMessage());
            paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_REJECTED", ex.getMessage());
            return toPaymentResponse(payment);
        }
    }

    public PaymentStatusResponse getPaymentStatus(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));

        return new PaymentStatusResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getFailureReason(),
                payment.getUpdatedAt()
        );
    }

    private PaymentResponse toPaymentResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getClientReference(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getCreatedAt()
        );
    }
}
