package com.example.payments.domain;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

public class Payment {
    private UUID paymentId;
    private String clientReference;
    private PaymentType paymentType;
    private String sourceAccountId;
    private String destinationAccountId;
    private BigDecimal amount;
    private String currency;
    private String beneficiaryName;
    private String beneficiaryBankCode;
    private String purpose;
    private PaymentStatus status;
    private String statusReason;
    private Instant createdAt;
    private Instant updatedAt;

    public Payment() {
    }

    public boolean canCancel() {
        return status == PaymentStatus.RECEIVED
                || status == PaymentStatus.VALIDATED
                || status == PaymentStatus.PENDING_COMPLIANCE
                || status == PaymentStatus.APPROVED;
    }

    public void transitionTo(PaymentStatus newStatus) {
        if (!isValidTransition(this.status, newStatus)) {
            throw new IllegalStateException(
                    "Invalid transition from " + this.status + " to " + newStatus);
        }
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    private boolean isValidTransition(PaymentStatus from, PaymentStatus to) {
        if (from == null && to == PaymentStatus.RECEIVED) return true;

        return switch (from) {
            case RECEIVED -> to == PaymentStatus.VALIDATED || to == PaymentStatus.CANCELLED || to == PaymentStatus.REJECTED;
            case VALIDATED -> to == PaymentStatus.PENDING_COMPLIANCE || to == PaymentStatus.CANCELLED || to == PaymentStatus.REJECTED;
            case PENDING_COMPLIANCE -> to == PaymentStatus.APPROVED || to == PaymentStatus.REJECTED || to == PaymentStatus.CANCELLED;
            case APPROVED -> to == PaymentStatus.PROCESSING || to == PaymentStatus.CANCELLED;
            case PROCESSING -> to == PaymentStatus.SETTLED || to == PaymentStatus.FAILED;
            case SETTLED, FAILED, REJECTED, CANCELLED -> false;
        };
    }

    public UUID getPaymentId() { return paymentId; }
    public void setPaymentId(UUID paymentId) { this.paymentId = paymentId; }
    public String getClientReference() { return clientReference; }
    public void setClientReference(String clientReference) { this.clientReference = clientReference; }
    public PaymentType getPaymentType() { return paymentType; }
    public void setPaymentType(PaymentType paymentType) { this.paymentType = paymentType; }
    public String getSourceAccountId() { return sourceAccountId; }
    public void setSourceAccountId(String sourceAccountId) { this.sourceAccountId = sourceAccountId; }
    public String getDestinationAccountId() { return destinationAccountId; }
    public void setDestinationAccountId(String destinationAccountId) { this.destinationAccountId = destinationAccountId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getCurrency() { return currency; }
    public void setCurrency(String currency) { this.currency = currency; }
    public String getBeneficiaryName() { return beneficiaryName; }
    public void setBeneficiaryName(String beneficiaryName) { this.beneficiaryName = beneficiaryName; }
    public String getBeneficiaryBankCode() { return beneficiaryBankCode; }
    public void setBeneficiaryBankCode(String beneficiaryBankCode) { this.beneficiaryBankCode = beneficiaryBankCode; }
    public String getPurpose() { return purpose; }
