## `service/PaymentProcessor.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.persistence.PaymentEntity;
import com.example.payments.persistence.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Component;

import java.util.UUID;

@Component
public class PaymentProcessor {

    private final PaymentRepository paymentRepository;
    private final LedgerService ledgerService;
    private final EventPublisher eventPublisher;
    private final PaymentApplicationService paymentApplicationService;

    public PaymentProcessor(PaymentRepository paymentRepository,
                            LedgerService ledgerService,
                            EventPublisher eventPublisher,
                            PaymentApplicationService paymentApplicationService) {
        this.paymentRepository = paymentRepository;
        this.ledgerService = ledgerService;
        this.eventPublisher = eventPublisher;
        this.paymentApplicationService = paymentApplicationService;
    }

    @Async
    @Transactional
    public void process(UUID paymentId) {
        PaymentEntity entity = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));

        Payment payment = paymentApplicationService.toDomain(entity);

        if (payment.getStatus() != PaymentStatus.APPROVED) {
            return;
        }

        payment.transitionTo(PaymentStatus.PROCESSING);
        paymentRepository.save(paymentApplicationService.toEntity(payment));

        try {
            ledgerService.reserveFunds(payment);
            ledgerService.settleFunds(payment);
            payment.transitionTo(PaymentStatus.SETTLED);
            payment.setStatusReason("Payment settled successfully");
        } catch (Exception ex) {
            ledgerService.releaseFunds(payment);
            payment.transitionTo(PaymentStatus.FAILED);
            payment.setStatusReason("Processing failed: " + ex.getMessage());
        }

        paymentRepository.save(paymentApplicationService.toEntity(payment));
        eventPublisher.publishPaymentUpdated(payment);
    }
}
```

