## `service/PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.persistence.IdempotencyRecord;
import com.example.payments.persistence.IdempotencyRepository;
import com.example.payments.persistence.PaymentEntity;
import com.example.payments.persistence.PaymentRepository;
import com.example.payments.exception.NotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final ComplianceService complianceService;
    private final EventPublisher eventPublisher;
    private final PaymentProcessor paymentProcessor;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     IdempotencyRepository idempotencyRepository,
                                     ComplianceService complianceService,
                                     EventPublisher eventPublisher,
                                     PaymentProcessor paymentProcessor) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRepository = idempotencyRepository;
        this.complianceService = complianceService;
        this.eventPublisher = eventPublisher;
        this.paymentProcessor = paymentProcessor;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = idempotencyRepository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                UUID paymentId = UUID.fromString(existing.get().getResourceId());
                return getPayment(paymentId);
            }
        }

        Payment payment = new Payment();
        payment.setPaymentId(UUID.randomUUID());
        payment.setClientReference(request.getClientReference());
        payment.setPaymentType(request.getPaymentType());
        payment.setSourceAccountId(request.getSourceAccountId());
        payment.setDestinationAccountId(request.getDestinationAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency().toUpperCase());
        payment.setBeneficiaryName(request.getBeneficiaryName());
        payment.setBeneficiaryBankCode(request.getBeneficiaryBankCode());
        payment.setPurpose(request.getPurpose());
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());
        payment.transitionTo(PaymentStatus.RECEIVED);

        payment.transitionTo(PaymentStatus.VALIDATED);
        payment.transitionTo(PaymentStatus.PENDING_COMPLIANCE);

        if (complianceService.passesCompliance(payment)) {
            payment.transitionTo(PaymentStatus.APPROVED);
            payment.setStatusReason("Approved by compliance");
        } else {
            payment.transitionTo(PaymentStatus.REJECTED);
            payment.setStatusReason("Rejected by compliance");
        }

        paymentRepository.save(toEntity(payment));

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            IdempotencyRecord record = new IdempotencyRecord();
            record.setIdempotencyKey(idempotencyKey);
            record.setResourceType("PAYMENT");
            record.setResourceId(payment.getPaymentId().toString());
            record.setCreatedAt(Instant.now());
            idempotencyRepository.save(record);
        }

        eventPublisher.publishPaymentCreated(payment);
        eventPublisher.publishPaymentUpdated(payment);

        if (payment.getStatus() == PaymentStatus.APPROVED) {
            paymentProcessor.process(payment.getPaymentId());
        }

        return toResponse(payment);
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity entity = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NotFoundException("Payment not found: " + paymentId));
        return toResponse(toDomain(entity));
    }

    @Transactional
    public PaymentResponse cancelPayment(UUID paymentId) {
        PaymentEntity entity = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NotFoundException("Payment not found: " + paymentId));

        Payment payment = toDomain(entity);

        if (!payment.canCancel()) {
            throw new IllegalStateException("Payment cannot be cancelled in status " + payment.getStatus());
        }

        payment.transitionTo(PaymentStatus.CANCELLED);
        payment.setStatusReason("Cancelled by user request");

        paymentRepository.save(toEntity(payment));
        eventPublisher.publishPaymentUpdated(payment);

        return toResponse(payment);
    }

    public Payment toDomain(PaymentEntity entity) {
        Payment payment = new Payment();
        payment.setPaymentId(entity.getPaymentId());
        payment.setClientReference(entity.getClientReference());
        payment.setPaymentType(entity.getPaymentType());
        payment.setSourceAccountId(entity.getSourceAccountId());
        payment.setDestinationAccountId(entity.getDestinationAccountId());
        payment.setAmount(entity.getAmount());
        payment.setCurrency(entity.getCurrency());
        payment.setBeneficiaryName(entity.getBeneficiaryName());
        payment.setBeneficiaryBankCode(entity.getBeneficiaryBankCode());
        payment.setPurpose(entity.getPurpose());
        payment.setStatus(entity.getStatus());
        payment.setStatusReason(entity.getStatusReason());
        payment.setCreatedAt(entity.getCreatedAt());
        payment.setUpdatedAt(entity.getUpdatedAt());
        return payment;
    }

    public PaymentEntity toEntity(Payment payment) {
        PaymentEntity entity = new PaymentEntity();
        entity.setPaymentId(payment.getPaymentId());
        entity.setClientReference(payment.getClientReference());
        entity.setPaymentType(payment.getPaymentType());
        entity.setSourceAccountId(payment.getSourceAccountId());
        entity.setDestinationAccountId(payment.getDestinationAccountId());
        entity.setAmount(payment.getAmount());
        entity.setCurrency(payment.getCurrency());
        entity.setBeneficiaryName(payment.getBeneficiaryName());
        entity.setBeneficiaryBankCode(payment.getBeneficiaryBankCode());
        entity.setPurpose(payment.getPurpose());
        entity.setStatus(payment.getStatus());
        entity.setStatusReason(payment.getStatusReason());
        entity.setCreatedAt(payment.getCreatedAt());
        entity.setUpdatedAt(payment.getUpdatedAt());
        return entity;
    }

    public PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setClientReference(payment.getClientReference());
        response.setPaymentType(payment.getPaymentType());
        response.setSourceAccountId(payment.getSourceAccountId());
        response.setDestinationAccountId(payment.getDestinationAccountId());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setBeneficiaryName(payment.getBeneficiaryName());
        response.setBeneficiaryBankCode(payment.getBeneficiaryBankCode());
        response.setPurpose(payment.getPurpose());
        response.setStatus(payment.getStatus());
        response.setStatusReason(payment.getStatusReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
