## `PaymentProcessingService.java`

```java
package com.example.payment.service;

import com.example.payment.domain.Payment;
import com.example.payment.domain.PaymentStatus;
import com.example.payment.dto.CreatePaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.exception.PaymentNotFoundException;
import com.example.payment.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final AuditService auditService;

    public PaymentProcessingService(PaymentRepository paymentRepository,
                                    PaymentValidationService validationService,
                                    AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        return paymentRepository.findByClientRequestId(request.getClientRequestId())
                .map(this::toResponse)
                .orElseGet(() -> createNewPayment(request));
    }

    private PaymentResponse createNewPayment(CreatePaymentRequest request) {
        Payment payment = new Payment();
        payment.setClientRequestId(request.getClientRequestId());
        payment.setSourceAccount(request.getSourceAccount());
        payment.setDestinationAccount(request.getDestinationAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_RECEIVED", "Payment request accepted");

            validationService.validateBusinessRules(request);
            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_VALIDATED", "Business validation passed");

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_PROCESSING", "Payment entered processing");

            // Initial synchronous placeholder for execution.
            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_COMPLETED", "Payment completed successfully");

            return toResponse(payment);
        } catch (IllegalArgumentException ex) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureReason(ex.getMessage());
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_REJECTED", ex.getMessage());
            return toResponse(payment);
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByClientRequestId(request.getClientRequestId())
                    .map(this::toResponse)
                    .orElseThrow(() -> ex);
        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason("Internal processing error");
            payment = paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_FAILED", ex.getMessage());
            return toResponse(payment);
        }
    }

    public PaymentResponse getPayment(String paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setClientRequestId(payment.getClientRequestId());
        response.setSourceAccount(payment.getSourceAccount());
        response.setDestinationAccount(payment.getDestinationAccount());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setStatus(payment.getStatus());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
```

