# 11. Core payment processing service

## `PaymentProcessingService.java`

```java
package com.example.payment.service;

import com.example.payment.api.dto.CreatePaymentRequest;
import com.example.payment.domain.Payment;
import com.example.payment.domain.PaymentAudit;
import com.example.payment.domain.PaymentStatus;
import com.example.payment.exception.PaymentNotFoundException;
import com.example.payment.repository.PaymentAuditRepository;
import com.example.payment.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final PaymentAuditRepository paymentAuditRepository;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final IdempotencyService idempotencyService;

    @Transactional
    public Payment createPayment(CreatePaymentRequest request) {
        return idempotencyService.findExisting(request.idempotencyKey())
                .orElseGet(() -> processNewPayment(request));
    }

    @Transactional
    protected Payment processNewPayment(CreatePaymentRequest request) {
        try {
            Payment payment = Payment.builder()
                    .idempotencyKey(request.idempotencyKey())
                    .sourceAccount(request.sourceAccount())
                    .destinationAccount(request.destinationAccount())
                    .amount(request.amount())
                    .currency(request.currency().toUpperCase())
                    .status(PaymentStatus.RECEIVED)
                    .build();

            payment = paymentRepository.save(payment);
            audit(payment, PaymentStatus.RECEIVED, "Payment received");

            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);
            audit(payment, PaymentStatus.VALIDATED, "Payment validated");

            boolean allowed = riskService.isAllowed(
                    payment.getSourceAccount(),
                    payment.getDestinationAccount(),
                    payment.getAmount(),
                    payment.getCurrency()
            );

            if (!allowed) {
                payment.setStatus(PaymentStatus.REJECTED);
                payment.setFailureReason("Rejected by risk screening");
                payment = paymentRepository.save(payment);
                audit(payment, PaymentStatus.REJECTED, "Rejected by risk screening");
                return payment;
            }

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            audit(payment, PaymentStatus.PROCESSING, "Payment sent for ledger processing");

            ledgerService.transfer(
                    payment.getSourceAccount(),
                    payment.getDestinationAccount(),
                    payment.getAmount(),
                    payment.getCurrency()
            );

            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);
            audit(payment, PaymentStatus.COMPLETED, "Payment completed successfully");

            return payment;

        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(request.idempotencyKey())
                    .orElseThrow(() -> ex);
        } catch (Exception ex) {
            Payment failedPayment = paymentRepository.findByIdempotencyKey(request.idempotencyKey())
                    .orElseThrow(() -> ex);

            failedPayment.setStatus(PaymentStatus.FAILED);
            failedPayment.setFailureReason(ex.getMessage());
            failedPayment = paymentRepository.save(failedPayment);
            audit(failedPayment, PaymentStatus.FAILED, "Payment failed: " + ex.getMessage());

            return failedPayment;
        }
    }

    public Payment getPayment(String paymentId) {
        return paymentRepository.findById(java.util.UUID.fromString(paymentId))
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    private void audit(Payment payment, PaymentStatus status, String message) {
        paymentAuditRepository.save(
                PaymentAudit.builder()
                        .paymentId(payment.getId())
                        .status(status)
                        .message(message)
                        .build()
        );
    }
}
```

