## `DefaultPaymentProcessor.java`

```java
package com.example.payments.service.impl;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.integration.PaymentRailClient;
import com.example.payments.repository.PaymentRepository;
import com.example.payments.service.AuditService;
import com.example.payments.service.PaymentProcessor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class DefaultPaymentProcessor implements PaymentProcessor {

    private final PaymentRailClient paymentRailClient;
    private final PaymentRepository paymentRepository;
    private final AuditService auditService;

    public DefaultPaymentProcessor(PaymentRailClient paymentRailClient,
                                   PaymentRepository paymentRepository,
                                   AuditService auditService) {
        this.paymentRailClient = paymentRailClient;
        this.paymentRepository = paymentRepository;
        this.auditService = auditService;
    }

    @Override
    @Transactional
    public Payment process(Payment payment) {
        payment.setStatus(PaymentStatus.PROCESSING);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_PROCESSING", payment.getClientPaymentId());

        PaymentRailClient.RailResult result = paymentRailClient.submit(payment);

        if (result.success()) {
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setFailureReason(null);
            auditService.record("PAYMENT_COMPLETED", payment.getClientPaymentId());
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(result.message());
            auditService.record("PAYMENT_FAILED", payment.getClientPaymentId());
        }

        return paymentRepository.save(payment);
    }
}
```

