## `PaymentApplicationServiceImpl.java`

```java
package com.example.payments.service.impl;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import com.example.payments.service.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class PaymentApplicationServiceImpl implements PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final IdempotencyService idempotencyService;
    private final PaymentProcessor paymentProcessor;
    private final AuditService auditService;

    public PaymentApplicationServiceImpl(PaymentRepository paymentRepository,
                                         PaymentValidationService validationService,
                                         IdempotencyService idempotencyService,
                                         PaymentProcessor paymentProcessor,
                                         AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.idempotencyService = idempotencyService;
        this.paymentProcessor = paymentProcessor;
        this.auditService = auditService;
    }

    @Override
    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        return idempotencyService.findExisting(request.getClientPaymentId())
                .map(this::toResponse)
                .orElseGet(() -> createAndProcess(request));
    }

    private PaymentResponse createAndProcess(CreatePaymentRequest request) {
        validationService.validate(request);

        Payment payment = new Payment();
        payment.setClientPaymentId(request.getClientPaymentId());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentType(request.getPaymentType());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            payment = paymentRepository.save(payment);
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByClientPaymentId(request.getClientPaymentId())
                    .map(this::toResponse)
                    .orElseThrow(() -> ex);
        }

        auditService.record("PAYMENT_RECEIVED", payment.getClientPaymentId());

        payment.setStatus(PaymentStatus.VALIDATED);
        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment.getClientPaymentId());

        payment = paymentProcessor.process(payment);

        return toResponse(payment);
    }

    @Override
    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID id) {
        Payment payment = paymentRepository.findById(id)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + id));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setId(payment.getId());
        response.setClientPaymentId(payment.getClientPaymentId());
        response.setDebtorAccount(payment.getDebtorAccount());
        response.setCreditorAccount(payment.getCreditorAccount());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setPaymentType(payment.getPaymentType());
        response.setStatus(payment.getStatus());
        response.setReference(payment.getReference());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
```

