## PaymentProcessingService.java

```java
package com.example.payment.service;

import com.example.payment.api.dto.CreatePaymentRequest;
import com.example.payment.api.dto.PaymentResponse;
import com.example.payment.domain.Payment;
import com.example.payment.domain.PaymentStatus;
import com.example.payment.exception.PaymentNotFoundException;
import com.example.payment.exception.ValidationException;
import com.example.payment.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final AuditService auditService;
    private final RiskScreeningService riskScreeningService;
    private final IdempotencyService idempotencyService;

    public PaymentProcessingService(PaymentRepository paymentRepository,
                                    AuditService auditService,
                                    RiskScreeningService riskScreeningService,
                                    IdempotencyService idempotencyService) {
        this.paymentRepository = paymentRepository;
        this.auditService = auditService;
        this.riskScreeningService = riskScreeningService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existingPaymentId = idempotencyService.getPaymentId(idempotencyKey);
            if (existingPaymentId.isPresent()) {
                Payment existing = paymentRepository.findById(existingPaymentId.get())
                        .orElseThrow(() -> new PaymentNotFoundException("Payment not found for idempotency key"));
                return toResponse(existing);
            }
        }

        if (request.getDebtorAccount().equals(request.getCreditorAccount())) {
            throw new ValidationException("Debtor and creditor accounts must differ");
        }

        Payment payment = new Payment();
        payment.setClientReference(request.getClientReference());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setRemittanceInformation(request.getRemittanceInformation());
        payment.setStatus(PaymentStatus.RECEIVED);

        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_RECEIVED", "Payment request accepted");

        if (!riskScreeningService.passes(request)) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureReason("Risk screening failed");
            payment = paymentRepository.save(payment);
            auditService.record(payment.getId(), "PAYMENT_REJECTED", "Risk screening failed");
            return toResponse(payment);
        }

        payment.setStatus(PaymentStatus.VALIDATED);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_VALIDATED", "Payment validated successfully");

        payment.setStatus(PaymentStatus.PROCESSING);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_PROCESSING", "Payment sent for processing");

        // Placeholder for integration with payment rail/core banking.
        payment.setStatus(PaymentStatus.COMPLETED);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_COMPLETED", "Payment completed successfully");

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            idempotencyService.save(idempotencyKey, payment.getId());
        }

        return toResponse(payment);
    }

    public PaymentResponse getPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getId());
        response.setClientReference(payment.getClientReference());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setDebtorAccount(payment.getDebtorAccount());
        response.setCreditorAccount(payment.getCreditorAccount());
        response.setRemittanceInformation(payment.getRemittanceInformation());
        response.setStatus(payment.getStatus());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
