package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments",
       uniqueConstraints = {
           @UniqueConstraint(name = "uk_payment_client_idempotency", columnNames = {"clientId", "idempotencyKey"})
       })
public class Payment {

    @Id
    private String id;

    @Column(nullable = false)
    private String clientId;

    @Column(nullable = false)
    private String clientReference;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(nullable = false)
    private String sourceAccountId;

    @Column(nullable = false)
    private String destinationAccountId;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private DestinationType destinationType;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentStatus status;

    @Column(nullable = false)
    private String idempotencyKey;

    @Column(length = 1024)
    private String description;

    @Column(nullable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private Long version;

    protected Payment() {
    }

    public Payment(
            String clientId,
            String clientReference,
            BigDecimal amount,
            String currency,
            String sourceAccountId,
            String destinationAccountId,
            DestinationType destinationType,
            String idempotencyKey,
            String description
    ) {
        this.id = "pay_" + UUID.randomUUID();
        this.clientId = clientId;
        this.clientReference = clientReference;
        this.amount = amount;
        this.currency = currency;
        this.sourceAccountId = sourceAccountId;
        this.destinationAccountId = destinationAccountId;
        this.destinationType = destinationType;
        this.idempotencyKey = idempotencyKey;
        this.description = description;
        this.status = PaymentStatus.RECEIVED;
        this.createdAt = Instant.now();
        this.updatedAt = this.createdAt;
    }

    public void markValidated() {
        transitionTo(PaymentStatus.VALIDATED);
    }

    public void markPendingRiskReview() {
        transitionTo(PaymentStatus.PENDING_RISK_REVIEW);
    }

    public void markApproved() {
        transitionTo(PaymentStatus.APPROVED);
    }

    public void markRejected() {
        transitionTo(PaymentStatus.REJECTED);
    }

    public void markProcessing() {
        transitionTo(PaymentStatus.PROCESSING);
    }

    public void markSettled() {
        transitionTo(PaymentStatus.SETTLED);
    }

    public void markFailed() {
        transitionTo(PaymentStatus.FAILED);
    }

    public void markCancelled() {
        transitionTo(PaymentStatus.CANCELLED);
    }

    private void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    public String getId() { return id; }
    public String getClientId() { return clientId; }
    public String getClientReference() { return clientReference; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public String getSourceAccountId() { return sourceAccountId; }
    public String getDestinationAccountId() { return destinationAccountId; }
    public DestinationType getDestinationType() { return destinationType; }
    public PaymentStatus getStatus() { return status; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getDescription() { return description; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
