    public AuditService(PaymentEventRepository paymentEventRepository, ObjectMapper objectMapper) {
        this.paymentEventRepository = paymentEventRepository;
        this.objectMapper = objectMapper;
    }

    public void record(Payment payment, String eventType) {
        record(payment, eventType, Map.of(
                "paymentId", payment.getId(),
                "status", payment.getStatus().name()
        ));
    }

    public void record(Payment payment, String eventType, Map<String, Object> payload) {
        try {
            String json = objectMapper.writeValueAsString(payload);
            paymentEventRepository.save(new PaymentEvent(payment.getId(), eventType, json));
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize audit payload", e);
        }
    }
}
