# 7. Improved version of `PaymentApplicationService`

Here is a cleaner initial version:

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentEvent;
import com.example.payments.repository.PaymentEventRepository;
import com.example.payments.repository.PaymentRepository;
import com.example.payments.exception.NotFoundException;
import jakarta.transaction.Transactional;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentEventRepository paymentEventRepository;
    private final PaymentValidationService validationService;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final PaymentRailService paymentRailService;
    private final AuditService auditService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentEventRepository paymentEventRepository,
            PaymentValidationService validationService,
            RiskService riskService,
            LedgerService ledgerService,
            PaymentRailService paymentRailService,
            AuditService auditService
    ) {
        this.paymentRepository = paymentRepository;
        this.paymentEventRepository = paymentEventRepository;
        this.validationService = validationService;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.paymentRailService = paymentRailService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(String clientId, String idempotencyKey, CreatePaymentRequest request) {
        return paymentRepository.findByClientIdAndIdempotencyKey(clientId, idempotencyKey)
                .orElseGet(() -> createNewPayment(clientId, idempotencyKey, request));
    }

    private Payment createNewPayment(String clientId, String idempotencyKey, CreatePaymentRequest request) {
        validationService.validate(request);

        Payment payment = new Payment(
                clientId,
                request.getClientReference(),
                request.getAmount(),
                request.getCurrency(),
                request.getSourceAccountId(),
                request.getDestinationAccountId(),
                request.getDestinationType(),
                idempotencyKey,
                request.getDescription()
        );

        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_RECEIVED");

        payment.markValidated();
        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_VALIDATED");

        payment.markPendingRiskReview();
        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_RISK_REVIEW_STARTED");

        boolean approved = riskService.approve(payment);
        if (!approved) {
            payment.markRejected();
            paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_REJECTED");
            return payment;
        }

        payment.markApproved();
        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_APPROVED");

        payment.markProcessing();
        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_PROCESSING");

        try {
            ledgerService.reserveFunds(payment);
            paymentRailService.execute(payment);

            payment.markSettled();
            paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_SETTLED");
        } catch (Exception ex) {
            payment.markFailed();
            paymentRepository.save(payment);
            auditService.record(payment, "PAYMENT_FAILED");
            throw ex;
        }

        return payment;
    }

    public Payment getPayment(String paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NotFoundException("Payment not found: " + paymentId));
    }

    public List<PaymentEvent> getPaymentEvents(String paymentId) {
        getPayment(paymentId);
        return paymentEventRepository.findByPaymentIdOrderByCreatedAtAsc(paymentId);
    }
}
