## `internal/app/service.go`

```go
package app

import (
	"context"
	"fmt"
	"time"

	"payment-service/internal/domain"
	"payment-service/internal/ports"
)

type PaymentService struct {
	payments    ports.PaymentRepository
	idempotency ports.IdempotencyRepository
	ledger      ports.LedgerService
	fraud       ports.FraudService
	compliance  ports.ComplianceService
	events      ports.EventPublisher
	audit       ports.AuditLogger
	idGenerator func() string
	now         func() time.Time
}

func NewPaymentService(
	payments ports.PaymentRepository,
	idempotency ports.IdempotencyRepository,
	ledger ports.LedgerService,
	fraud ports.FraudService,
	compliance ports.ComplianceService,
	events ports.EventPublisher,
	audit ports.AuditLogger,
) *PaymentService {
	return &PaymentService{
		payments:    payments,
		idempotency: idempotency,
		ledger:      ledger,
		fraud:       fraud,
		compliance:  compliance,
		events:      events,
		audit:       audit,
		idGenerator: func() string { return fmt.Sprintf("pay_%d", time.Now().UnixNano()) },
		now:         time.Now,
	}
}

func (s *PaymentService) CreatePayment(ctx context.Context, req domain.CreatePaymentRequest) (domain.Payment, error) {
	if err := req.Validate(); err != nil {
		return domain.Payment{}, err
	}

	if paymentID, err := s.idempotency.GetPaymentID(ctx, req.IdempotencyKey); err == nil && paymentID != "" {
		existing, getErr := s.payments.GetByID(ctx, paymentID)
		if getErr == nil {
			return existing, nil
		}
	}

	now := s.now()
	payment := domain.Payment{
		ID:             s.idGenerator(),
		IdempotencyKey: req.IdempotencyKey,
		SourceAccount:  req.SourceAccount,
		Destination:    req.Destination,
		Amount:         req.Amount,
		Reference:      req.Reference,
		Status:         domain.PaymentStatusPending,
		CreatedAt:      now,
		UpdatedAt:      now,
	}

	if err := s.payments.Save(ctx, payment); err != nil {
		return domain.Payment{}, err
	}

	if err := s.idempotency.Save(ctx, req.IdempotencyKey, payment.ID); err != nil {
		return domain.Payment{}, err
	}

	_ = s.audit.Log(ctx, "PAYMENT_CREATED", payment, map[string]string{})
	_ = s.events.PublishPaymentCreated(ctx, payment)

	if err := s.compliance.Check(ctx, payment); err != nil {
		payment.Status = domain.PaymentStatusFailed
		payment.FailureReason = "compliance check failed"
		payment.UpdatedAt = s.now()
		_ = s.payments.Update(ctx, payment)
		_ = s.audit.Log(ctx, "PAYMENT_FAILED", payment, map[string]string{"reason": payment.FailureReason})
		_ = s.events.PublishPaymentFailed(ctx, payment)
		return payment, domain.ErrProcessingFailed(payment.FailureReason)
	}

	if err := s.fraud.Check(ctx, payment); err != nil {
		payment.Status = domain.PaymentStatusFailed
		payment.FailureReason = "fraud check failed"
		payment.UpdatedAt = s.now()
		_ = s.payments.Update(ctx, payment)
		_ = s.audit.Log(ctx, "PAYMENT_FAILED", payment, map[string]string{"reason": payment.FailureReason})
		_ = s.events.PublishPaymentFailed(ctx, payment)
		return payment, domain.ErrProcessingFailed(payment.FailureReason)
	}

	if err := s.ledger.Debit(ctx, payment.SourceAccount, payment.Amount, payment.Reference); err != nil {
		payment.Status = domain.PaymentStatusFailed
		payment.FailureReason = "ledger debit failed"
		payment.UpdatedAt = s.now()
		_ = s.payments.Update(ctx, payment)
		_ = s.audit.Log(ctx, "PAYMENT_FAILED", payment, map[string]string{"reason": payment.FailureReason})
		_ = s.events.PublishPaymentFailed(ctx, payment)
		return payment, domain.ErrProcessingFailed(payment.FailureReason)
	}

	payment.Status = domain.PaymentStatusCompleted
	payment.UpdatedAt = s.now()

	if err := s.payments.Update(ctx, payment); err != nil {
		return domain.Payment{}, err
	}

	_ = s.audit.Log(ctx, "PAYMENT_COMPLETED", payment, map[string]string{})
	_ = s.events.PublishPaymentCompleted(ctx, payment)

	return payment, nil
}

func (s *PaymentService) GetPayment(ctx context.Context, id string) (domain.Payment, error) {
	if id == "" {
		return domain.Payment{}, domain.ErrInvalidRequest("id is required")
	}
	return s.payments.GetByID(ctx, id)
}
