func (r *IdempotencyRepository) GetPaymentID(ctx context.Context, key string) (string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.data[key]
	if !ok {
		return "", domain.ErrNotFound("idempotency key not found")
	}
	return id, nil
}

func (r *IdempotencyRepository) Save(ctx context.Context, key string, paymentID string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.data[key]; exists {
		return domain.ErrDuplicateRequest("idempotency key already exists")
	}
	r.data[key] = paymentID
	return nil
}
