```go
package api

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"payment-service/internal/app"
	"payment-service/internal/domain"
)

type Handler struct {
	service *app.PaymentService
}

func NewHandler(service *app.PaymentService) *Handler {
	return &Handler{service: service}
}

func (h *Handler) Register(mux *http.ServeMux) {
	mux.HandleFunc("POST /payments", h.createPayment)
	mux.HandleFunc("GET /payments/", h.getPayment)
}

func (h *Handler) createPayment(w http.ResponseWriter, r *http.Request) {
	var req domain.CreatePaymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, domain.ErrInvalidRequest("invalid json"))
		return
	}

	payment, err := h.service.CreatePayment(r.Context(), req)
	if err != nil {
		writeError(w, err)
		return
	}

	writeJSON(w, http.StatusCreated, payment)
}

func (h *Handler) getPayment(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/payments/")
	payment, err := h.service.GetPayment(r.Context(), id)
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, payment)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, err error) {
	var appErr domain.AppError
	if errors.As(err, &appErr) {
		switch appErr.Code {
		case "INVALID_REQUEST":
			writeJSON(w, http.StatusBadRequest, appErr)
			return
		case "NOT_FOUND":
			writeJSON(w, http.StatusNotFound, appErr)
			return
		case "DUPLICATE_REQUEST":
			writeJSON(w, http.StatusConflict, appErr)
			return
		case "PROCESSING_FAILED":
			writeJSON(w, http.StatusUnprocessableEntity, appErr)
			return
		}
	}
	writeJSON(w, http.StatusInternalServerError, map[string]string{
		"code":    "INTERNAL_ERROR",
		"message": "internal server error",
	})
}
