package com.example.payments.domain;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

public class Payment {
    private final String paymentId;
    private final String clientId;
    private final String sourceAccount;
    private final String destinationAccount;
    private final BigDecimal amount;
    private final String currency;
    private final PaymentType paymentType;
    private PaymentStatus status;
    private final Instant createdAt;
    private Instant updatedAt;
    private String failureReason;
    private final String idempotencyKey;

    public Payment(
            String paymentId,
            String clientId,
            String sourceAccount,
            String destinationAccount,
            BigDecimal amount,
            String currency,
            PaymentType paymentType,
            PaymentStatus status,
            Instant createdAt,
            Instant updatedAt,
            String failureReason,
            String idempotencyKey) {
        this.paymentId = paymentId == null ? UUID.randomUUID().toString() : paymentId;
        this.clientId = Objects.requireNonNull(clientId);
        this.sourceAccount = Objects.requireNonNull(sourceAccount);
        this.destinationAccount = Objects.requireNonNull(destinationAccount);
        this.amount = Objects.requireNonNull(amount);
        this.currency = Objects.requireNonNull(currency);
        this.paymentType = Objects.requireNonNull(paymentType);
        this.status = Objects.requireNonNull(status);
        this.createdAt = createdAt == null ? Instant.now() : createdAt;
        this.updatedAt = updatedAt == null ? Instant.now() : updatedAt;
        this.failureReason = failureReason;
        this.idempotencyKey = Objects.requireNonNull(idempotencyKey);
    }

    public void markValidated() {
        transitionTo(PaymentStatus.VALIDATED);
    }

    public void markPendingApproval() {
        transitionTo(PaymentStatus.PENDING_APPROVAL);
    }

    public void markApproved() {
        transitionTo(PaymentStatus.APPROVED);
    }

    public void markProcessing() {
        transitionTo(PaymentStatus.PROCESSING);
    }

    public void markSettled() {
        transitionTo(PaymentStatus.SETTLED);
    }

    public void markRejected(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.REJECTED);
    }

    public void markFailed(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.FAILED);
    }

    public void markValidationFailed(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.VALIDATION_FAILED);
    }

    private void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    public String getPaymentId() {
        return paymentId;
    }

    public String getClientId() {
        return clientId;
    }

    public String getSourceAccount() {
        return sourceAccount;
    }

    public String getDestinationAccount() {
        return destinationAccount;
    }

    public BigDecimal getAmount() {
