package com.example.payments.infrastructure;

import com.example.payments.domain.Payment;
import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {

    private final Map<String, Payment> paymentsById = new ConcurrentHashMap<>();
    private final Map<String, String> paymentIdByIdempotencyKey = new ConcurrentHashMap<>();

    @Override
    public Payment save(Payment payment) {
        paymentsById.put(payment.getPaymentId(), payment);
        paymentIdByIdempotencyKey.put(payment.getIdempotencyKey(), payment.getPaymentId());
        return payment;
    }

    @Override
    public Optional<Payment> findById(String paymentId) {
        return Optional.ofNullable(paymentsById.get(paymentId));
    }

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        String paymentId = paymentIdByIdempotencyKey.get(idempotencyKey);
        if (paymentId == null) {
            return Optional.empty();
        }
        return findById(paymentId);
    }
}
```

