# 6. Application service

## `PaymentApplicationService.java`

```java
package com.example.payments.application;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.infrastructure.AuditService;
import com.example.payments.infrastructure.IdempotencyService;
import com.example.payments.infrastructure.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            AuditService auditService,
            IdempotencyService idempotencyService) {
        this.paymentRepository = paymentRepository;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        idempotencyService.validateKey(idempotencyKey);

        Optional<Payment> existing = paymentRepository.findByIdempotencyKey(idempotencyKey);
        if (existing.isPresent()) {
            return existing.get();
        }

        Payment payment = new Payment(
                UUID.randomUUID().toString(),
                request.getClientId(),
                request.getSourceAccount(),
                request.getDestinationAccount(),
                request.getAmount(),
                request.getCurrency(),
                request.getPaymentType(),
                PaymentStatus.RECEIVED,
                Instant.now(),
                Instant.now(),
                null,
                idempotencyKey
        );

        auditService.record("PAYMENT_RECEIVED", payment);

        if (!isValid(payment)) {
            payment.markValidationFailed("Payment validation failed");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_VALIDATION_FAILED", payment);
            return payment;
        }

        payment.markValidated();
        auditService.record("PAYMENT_VALIDATED", payment);

        if (requiresApproval(payment)) {
            payment.markPendingApproval();
            auditService.record("PAYMENT_PENDING_APPROVAL", payment);
        } else {
            payment.markApproved();
            auditService.record("PAYMENT_APPROVED", payment);

            payment.markProcessing();
            auditService.record("PAYMENT_PROCESSING", payment);

            payment.markSettled();
            auditService.record("PAYMENT_SETTLED", payment);
        }

        paymentRepository.save(payment);
        return payment;
    }

    public Optional<Payment> getPayment(String paymentId) {
        return paymentRepository.findById(paymentId);
    }

    private boolean isValid(Payment payment) {
        if (payment.getAmount().signum() <= 0) {
            return false;
        }
        if (payment.getSourceAccount().equals(payment.getDestinationAccount())) {
            return false;
        }
        return payment.getCurrency().matches("^[A-Z]{3}$");
    }

    private boolean requiresApproval(Payment payment) {
        return payment.getAmount().doubleValue() >= 10000.00;
    }
}
```

