## `service/PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.InvalidPaymentException;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyService idempotencyService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request) {
        return idempotencyService.findExisting(request.getIdempotencyKey())
                .orElseGet(() -> createNewPayment(request));
    }

    private Payment createNewPayment(CreatePaymentRequest request) {
        validateBusinessRules(request);

        Payment payment = new Payment();
        payment.setIdempotencyKey(request.getIdempotencyKey());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);

        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_CREATED", payment);

        try {
            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_VALIDATED", payment);

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_PROCESSING", payment);

            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_COMPLETED", payment);

        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(ex.getMessage());
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_FAILED", payment);
        }

        return payment;
    }

    public Payment getPayment(UUID id) {
        return paymentRepository.findById(id)
                .orElseThrow(() -> new PaymentNotFoundException(id));
    }

    @Transactional
    public Payment cancelPayment(UUID id) {
        Payment payment = getPayment(id);

        if (payment.getStatus() == PaymentStatus.COMPLETED) {
            throw new InvalidPaymentException("Completed payments cannot be cancelled");
        }

        if (payment.getStatus() == PaymentStatus.CANCELLED) {
            return payment;
        }

        payment.setStatus(PaymentStatus.CANCELLED);
        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_CANCELLED", payment);
        return payment;
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccount().equals(request.getCreditorAccount())) {
            throw new InvalidPaymentException("Debtor and creditor accounts must differ");
        }

        if (request.getAmount().signum() <= 0) {
            throw new InvalidPaymentException("Amount must be greater than zero");
        }
    }
}
```

