package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.PaymentValidationException;
import org.springframework.stereotype.Service;

import java.util.Set;

@Service
public class PaymentValidationService {

    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP");

    public void validate(CreatePaymentRequest request) {
        if (request.getSourceAccount().equals(request.getDestinationAccount())) {
            throw new PaymentValidationException("Source and destination accounts must differ");
        }

        if (!SUPPORTED_CURRENCIES.contains(request.getCurrency())) {
            throw new PaymentValidationException("Unsupported currency: " + request.getCurrency());
        }

        if (request.getAmount().scale() > 2) {
            throw new PaymentValidationException("Amount cannot have more than 2 decimal places");
        }
    }
}
