## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.CreatePaymentResponse;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.entity.PaymentEntity;
import com.example.payments.exception.ResourceNotFoundException;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentValidationService validationService,
            IdempotencyService idempotencyService,
            AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    @Transactional
    public CreatePaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existingPaymentId = idempotencyService.findPaymentId(idempotencyKey);
            if (existingPaymentId.isPresent()) {
                PaymentEntity existing = paymentRepository.findById(existingPaymentId.get())
                        .orElseThrow(() -> new ResourceNotFoundException("Payment not found for idempotency key"));
                return new CreatePaymentResponse(existing.getId(), existing.getStatus());
            }
        }

        validationService.validate(request);

        Instant now = Instant.now();
        PaymentEntity entity = new PaymentEntity();
        entity.setId(UUID.randomUUID());
        entity.setClientPaymentId(request.getClientPaymentId());
        entity.setSourceAccount(request.getSourceAccount());
        entity.setDestinationAccount(request.getDestinationAccount());
        entity.setAmount(request.getAmount());
        entity.setCurrency(request.getCurrency());
        entity.setPaymentType(request.getPaymentType());
        entity.setReference(request.getReference());
        entity.setStatus(PaymentStatus.RECEIVED);
        entity.setCreatedAt(now);
        entity.setUpdatedAt(now);

        paymentRepository.save(entity);

        auditService.record("PAYMENT_CREATED", "paymentId=" + entity.getId());

        entity.setStatus(PaymentStatus.VALIDATED);
        entity.setUpdatedAt(Instant.now());
        paymentRepository.save(entity);

        auditService.record("PAYMENT_VALIDATED", "paymentId=" + entity.getId());

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            idempotencyService.save(idempotencyKey, entity.getId());
        }

        return new CreatePaymentResponse(entity.getId(), entity.getStatus());
    }

    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity entity = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new ResourceNotFoundException("Payment not found: " + paymentId));

        return new PaymentResponse(
                entity.getId(),
                entity.getClientPaymentId(),
                entity.getSourceAccount(),
                entity.getDestinationAccount(),
                entity.getAmount(),
                entity.getCurrency(),
                entity.getPaymentType(),
                entity.getReference(),
                entity.getStatus(),
                entity.getCreatedAt(),
                entity.getUpdatedAt()
        );
    }
}
```

