## IdempotencyServiceImpl.java

```java
package com.bank.payments.service.impl;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.domain.IdempotencyRecord;
import com.bank.payments.domain.Payment;
import com.bank.payments.exception.DuplicateRequestException;
import com.bank.payments.repository.IdempotencyRecordRepository;
import com.bank.payments.repository.PaymentRepository;
import com.bank.payments.service.IdempotencyService;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class IdempotencyServiceImpl implements IdempotencyService {

    private final IdempotencyRecordRepository idempotencyRecordRepository;
    private final PaymentRepository paymentRepository;

    @Override
    @Transactional
    public Payment checkOrCreate(String idempotencyKey, CreatePaymentRequest request) {
        String requestHash = hash(request);

        return idempotencyRecordRepository.findByIdempotencyKey(idempotencyKey)
                .map(record -> {
                    if (!record.getRequestHash().equals(requestHash)) {
                        throw new DuplicateRequestException("Idempotency key reused with different payload");
                    }
                    if (record.getPaymentId() == null) {
                        return null;
                    }
                    return paymentRepository.findById(record.getPaymentId()).orElse(null);
                })
                .orElseGet(() -> {
                    IdempotencyRecord record = IdempotencyRecord.builder()
                            .idempotencyKey(idempotencyKey)
                            .requestHash(requestHash)
                            .build();
                    idempotencyRecordRepository.save(record);
                    return null;
                });
    }

    @Override
    @Transactional
    public void bindPayment(String idempotencyKey, String paymentId) {
        IdempotencyRecord record = idempotencyRecordRepository.findByIdempotencyKey(idempotencyKey)
                .orElseThrow(() -> new DuplicateRequestException("Missing idempotency record"));
        record.setPaymentId(paymentId);
        idempotencyRecordRepository.save(record);
    }

    private String hash(CreatePaymentRequest request) {
        try {
            String payload = request.getClientReference() + "|" +
                    request.getSourceAccountId() + "|" +
                    request.getDestinationAccountId() + "|" +
                    request.getAmount() + "|" +
                    request.getCurrency() + "|" +
                    request.getPaymentType();

            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(payload.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new IllegalStateException("Unable to hash request", e);
        }
    }
}
```

## LedgerServiceImpl.java

```java
package com.bank.payments.service.impl;

import com.bank.payments.domain.*;
import com.bank.payments.exception.InsufficientFundsException;
import com.bank.payments.repository.AccountRepository;
import com.bank.payments.repository.LedgerEntryRepository;
import com.bank.payments.service.LedgerService;
import java.math.BigDecimal;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class LedgerServiceImpl implements LedgerService {

    private final AccountRepository accountRepository;
    private final LedgerEntryRepository ledgerEntryRepository;

    @Override
    @Transactional
    public void postEntries(Payment payment) {
        Account source = accountRepository.findById(payment.getSourceAccountId())
                .orElseThrow(() -> new IllegalArgumentException("Source account not found"));

        Account destination = accountRepository.findById(payment.getDestinationAccountId())
                .orElseThrow(() -> new IllegalArgumentException("Destination account not found"));

        BigDecimal amount = payment.getAmount();

        if (source.getAvailableBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException("Insufficient funds");
        }

        source.debit(amount);
        destination.credit(amount);

        accountRepository.save(source);
        accountRepository.save(destination);

        ledgerEntryRepository.save(LedgerEntry.builder()
                .paymentId(payment.getPaymentId())
                .accountId(source.getAccountId())
                .entryType(LedgerEntryType.DEBIT)
                .amount(amount)
                .currency(payment.getCurrency())
                .build());

        ledgerEntryRepository.save(LedgerEntry.builder()
                .paymentId(payment.getPaymentId())
                .accountId(destination.getAccountId())
                .entryType(LedgerEntryType.CREDIT)
                .amount(amount)
                .currency(payment.getCurrency())
                .build());
    }
}
```

## PaymentApplicationService.java

```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repository.PaymentRepository;
import java.time.Instant;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;
    private final PaymentRailService paymentRailService;

    @Transactional
    public PaymentResponse createPayment(String idempotencyKey, CreatePaymentRequest request) {
        Payment existing = idempotencyService.checkOrCreate(idempotencyKey, request);
        if (existing != null) {
            return toResponse(existing);
        }

        Payment payment = Payment.builder()
                .clientReference(request.getClientReference())
                .sourceAccountId(request.getSourceAccountId())
                .destinationAccountId(request.getDestinationAccountId())
                .amount(request.getAmount())
                .currency(request.getCurrency())
                .paymentType(request.getPaymentType())
                .status(PaymentStatus.RECEIVED)
                .build();

        paymentRepository.save(payment);
        idempotencyService.bindPayment(idempotencyKey, payment.getPaymentId());
        auditService.record("PAYMENT_RECEIVED", payment.getPaymentId(), "Payment created");

        validate(payment);
        riskService.assess(payment);

        payment.setStatus(PaymentStatus.AUTHORIZED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_AUTHORIZED", payment.getPaymentId(), "Payment authorized");

        ledgerService.postEntries(payment);
        payment.setStatus(PaymentStatus.POSTED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_POSTED", payment.getPaymentId(), "Ledger posted");

        payment.setStatus(PaymentStatus.PROCESSING);
        paymentRepository.save(payment);

        paymentRailService.execute(payment);

        payment.setStatus(PaymentStatus.COMPLETED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_COMPLETED", payment.getPaymentId(), "Payment completed");

        return toResponse(payment);
    }

    private void validate(Payment payment) {
        if (payment.getSourceAccountId().equals(payment.getDestinationAccountId())) {
            payment.setStatus(PaymentStatus.REJECTED);
            throw new IllegalArgumentException("Source and destination accounts must differ");
        }
    }

    private PaymentResponse toResponse(Payment payment) {
        return PaymentResponse.builder()
                .paymentId(payment.getPaymentId())
                .clientReference(payment.getClientReference())
                .status(payment.getStatus())
                .amount(payment.getAmount())
                .currency(payment.getCurrency())
                .failureReason(payment.getFailureReason())
                .build();
    }
}
