import express from "express";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 3000;

// In-memory stores for demo only
const payments = new Map();
const idempotencyStore = new Map();
const auditLog = [];

// Simple config
const SUPPORTED_CURRENCIES = new Set(["USD", "EUR", "GBP"]);
const VALID_STATUSES = new Set(["PENDING", "SETTLED", "FAILED"]);

function logAudit(eventType, details) {
  const entry = {
    id: uuidv4(),
    timestamp: new Date().toISOString(),
    eventType,
    details
  };
  auditLog.push(entry);
  console.log(JSON.stringify(entry));
}

function validatePaymentRequest(body) {
  const { amount, currency, debtorAccount, creditorAccount, reference } = body;

  if (typeof amount !== "number" || !Number.isFinite(amount) || amount <= 0) {
    return "amount must be a positive number";
  }

  if (!SUPPORTED_CURRENCIES.has(currency)) {
    return "unsupported currency";
  }

  if (!debtorAccount || typeof debtorAccount !== "string") {
    return "debtorAccount is required";
  }

  if (!creditorAccount || typeof creditorAccount !== "string") {
    return "creditorAccount is required";
  }

  if (debtorAccount === creditorAccount) {
    return "debtorAccount and creditorAccount must differ";
  }

  if (reference && typeof reference !== "string") {
    return "reference must be a string";
  }

  return null;
}

// Health check
app.get("/health", (req, res) => {
  res.json({ status: "ok" });
});

// Create payment
app.post("/payments", (req, res) => {
  const idempotencyKey = req.header("Idempotency-Key");

  if (!idempotencyKey) {
    return res.status(400).json({
      error: "Idempotency-Key header is required"
    });
  }

  if (idempotencyStore.has(idempotencyKey)) {
    const existingPaymentId = idempotencyStore.get(idempotencyKey);
    const existingPayment = payments.get(existingPaymentId);
    return res.status(200).json(existingPayment);
  }

  const validationError = validatePaymentRequest(req.body);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const payment = {
    id: uuidv4(),
    amount: req.body.amount,
    currency: req.body.currency,
    debtorAccount: req.body.debtorAccount,
    creditorAccount: req.body.creditorAccount,
    reference: req.body.reference || "",
    status: "PENDING",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  payments.set(payment.id, payment);
  idempotencyStore.set(idempotencyKey, payment.id);

  logAudit("PAYMENT_CREATED", {
    paymentId: payment.id,
    amount: payment.amount,
    currency: payment.currency
  });

  res.status(201).json(payment);
});

// Get payment
app.get("/payments/:id", (req, res) => {
  const payment = payments.get(req.params.id);

  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  res.json(payment);
});

// Simulate settlement
app.post("/payments/:id/settle", (req, res) => {
  const payment = payments.get(req.params.id);

  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "PENDING") {
    return res.status(409).json({
      error: `cannot settle payment in status ${payment.status}`
    });
  }

  payment.status = "SETTLED";
  payment.updatedAt = new Date().toISOString();
  payments.set(payment.id, payment);

  logAudit("PAYMENT_SETTLED", {
    paymentId: payment.id
  });

  res.json(payment);
});

// Simulate failure
app.post("/payments/:id/fail", (req, res) => {
  const payment = payments.get(req.params.id);

  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "PENDING") {
    return res.status(409).json({
      error: `cannot fail payment in status ${payment.status}`
    });
  }

  payment.status = "FAILED";
  payment.updatedAt = new Date().toISOString();
  payments.set(payment.id, payment);

  logAudit("PAYMENT_FAILED", {
    paymentId: payment.id
  });

  res.json(payment);
});

// View audit log
app.get("/audit", (req, res) => {
  res.json(auditLog);
});

// Fallback
app.use((req, res) => {
  res.status(404).json({ error: "route not found" });
});

app.listen(PORT, () => {
  console.log(`Mock payment service running on port ${PORT}`);
});
