```js
import express from "express";
import { randomUUID } from "crypto";

const app = express();
app.use(express.json());

const payments = new Map();
const idempotencyStore = new Map();

function now() {
  return new Date().toISOString();
}

function validateCreatePayment(body) {
  const { amount, currency, source, merchantId } = body;

  if (!Number.isInteger(amount) || amount <= 0) {
    return "amount must be a positive integer in minor units";
  }

  if (typeof currency !== "string" || currency.length !== 3) {
    return "currency must be a 3-letter ISO code";
  }

  if (!source || typeof source !== "object") {
    return "source is required";
  }

  if (typeof merchantId !== "string" || merchantId.trim() === "") {
    return "merchantId is required";
  }

  return null;
}

app.get("/health", (req, res) => {
  res.json({ status: "ok", timestamp: now() });
});

app.post("/payments", (req, res) => {
  const idemKey = req.header("Idempotency-Key");
  if (idemKey && idempotencyStore.has(idemKey)) {
    return res.status(200).json(idempotencyStore.get(idemKey));
  }

  const error = validateCreatePayment(req.body);
  if (error) {
    return res.status(400).json({ error });
  }

  const { amount, currency, source, merchantId, autoCapture = false } = req.body;

  const payment = {
    id: randomUUID(),
    merchantId,
    amount,
    currency: currency.toUpperCase(),
    source: {
      type: source.type || "card",
      last4: source.last4 || "4242"
    },
    status: autoCapture ? "captured" : "authorized",
    createdAt: now(),
    updatedAt: now(),
    capturedAt: autoCapture ? now() : null,
    refundedAmount: 0
  };

  payments.set(payment.id, payment);

  if (idemKey) {
    idempotencyStore.set(idemKey, payment);
  }

  res.status(201).json(payment);
});

app.get("/payments/:id", (req, res) => {
  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }
  res.json(payment);
});

app.post("/payments/:id/capture", (req, res) => {
  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "authorized") {
    return res.status(409).json({ error: "only authorized payments can be captured" });
  }

  payment.status = "captured";
  payment.capturedAt = now();
  payment.updatedAt = now();

  res.json(payment);
});

app.post("/payments/:id/refund", (req, res) => {
  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "captured" && payment.status !== "partially_refunded") {
    return res.status(409).json({ error: "only captured payments can be refunded" });
  }

  const requestedAmount = req.body.amount ?? payment.amount - payment.refundedAmount;

  if (!Number.isInteger(requestedAmount) || requestedAmount <= 0) {
    return res.status(400).json({ error: "refund amount must be a positive integer" });
  }

  const remaining = payment.amount - payment.refundedAmount;
  if (requestedAmount > remaining) {
    return res.status(409).json({ error: "refund amount exceeds remaining captured amount" });
  }

  payment.refundedAmount += requestedAmount;
  payment.updatedAt = now();

  if (payment.refundedAmount === payment.amount) {
    payment.status = "refunded";
  } else {
    payment.status = "partially_refunded";
  }

  res.json(payment);
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Mock payment service listening on port ${port}`);
});
```

