```js
const express = require("express");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 3000;

// In-memory stores
const payments = new Map();
const idempotencyStore = new Map();

// Utility
function now() {
  return new Date().toISOString();
}

function badRequest(res, message) {
  return res.status(400).json({ error: message });
}

function getIdempotencyKey(req) {
  return req.header("Idempotency-Key");
}

// Health check
app.get("/health", (req, res) => {
  res.json({ status: "ok", timestamp: now() });
});

// Create payment
app.post("/payments", (req, res) => {
  const idemKey = getIdempotencyKey(req);
  if (idemKey && idempotencyStore.has(`create:${idemKey}`)) {
    return res.status(200).json(idempotencyStore.get(`create:${idemKey}`));
  }

  const { amount, currency, source, capture = false } = req.body;

  if (typeof amount !== "number" || amount <= 0) {
    return badRequest(res, "amount must be a positive number");
  }

  if (!currency || typeof currency !== "string") {
    return badRequest(res, "currency is required");
  }

  if (!source || typeof source !== "object") {
    return badRequest(res, "source is required");
  }

  const payment = {
    id: uuidv4(),
    amount,
    currency: currency.toUpperCase(),
    source: {
      type: source.type || "card",
      last4: source.last4 || "4242"
    },
    status: capture ? "captured" : "authorized",
    createdAt: now(),
    capturedAt: capture ? now() : null,
    refundedAmount: 0
  };

  payments.set(payment.id, payment);

  if (idemKey) {
    idempotencyStore.set(`create:${idemKey}`, payment);
  }

  res.status(201).json(payment);
});

// Get payment
app.get("/payments/:id", (req, res) => {
  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }
  res.json(payment);
});

// Capture payment
app.post("/payments/:id/capture", (req, res) => {
  const idemKey = getIdempotencyKey(req);
  if (idemKey && idempotencyStore.has(`capture:${req.params.id}:${idemKey}`)) {
    return res.status(200).json(idempotencyStore.get(`capture:${req.params.id}:${idemKey}`));
  }

  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "authorized") {
    return res.status(409).json({ error: `cannot capture payment in status ${payment.status}` });
  }

  payment.status = "captured";
  payment.capturedAt = now();

  if (idemKey) {
    idempotencyStore.set(`capture:${req.params.id}:${idemKey}`, payment);
  }

  res.json(payment);
});

// Refund payment
app.post("/payments/:id/refund", (req, res) => {
  const idemKey = getIdempotencyKey(req);
  if (idemKey && idempotencyStore.has(`refund:${req.params.id}:${idemKey}`)) {
    return res.status(200).json(idempotencyStore.get(`refund:${req.params.id}:${idemKey}`));
  }

  const payment = payments.get(req.params.id);
  if (!payment) {
    return res.status(404).json({ error: "payment not found" });
  }

  if (payment.status !== "captured" && payment.status !== "partially_refunded") {
    return res.status(409).json({ error: `cannot refund payment in status ${payment.status}` });
  }

  const { amount } = req.body;

  if (typeof amount !== "number" || amount <= 0) {
    return badRequest(res, "refund amount must be a positive number");
  }

  const remaining = payment.amount - payment.refundedAmount;
  if (amount > remaining) {
    return res.status(409).json({ error: "refund amount exceeds remaining captured amount" });
  }

  payment.refundedAmount += amount;
  payment.status = payment.refundedAmount === payment.amount ? "refunded" : "partially_refunded";
  payment.refundedAt = now();

  const response = {
    paymentId: payment.id,
    refundedAmount: amount,
    totalRefundedAmount: payment.refundedAmount,
    status: payment.status,
    timestamp: now()
  };

  if (idemKey) {
    idempotencyStore.set(`refund:${req.params.id}:${idemKey}`, response);
  }

  res.json(response);
});

// Start server
app.listen(PORT, () => {
  console.log(`Mock payment service listening on port ${PORT}`);
});
```

