export class HttpCorporateCrmClient implements CorporateCrmClient {
  async createCustomer(input: CreateCrmCustomerRequest): Promise<CreateCrmCustomerResponse> {
    const response = await fetch(`${env.CRM_BASE_URL}/customers`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-API-Key": env.CRM_API_KEY
      },
      body: JSON.stringify(input)
    });

    if (!response.ok) {
      throw new Error(`CRM request failed with status ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data !== "object" ||
      data === null ||
      !("crmId" in data) ||
      typeof data.crmId !== "string"
    ) {
      throw new Error("Invalid CRM response payload");
    }

    return { crmId: data.crmId };
  }
}
