```ts
import type { Customer } from "../../domain/customer.js";
import type { CorporateCrmClient } from "../../infrastructure/corporate-crm-client.js";
import type { CustomerRepository } from "./customer.repository.js";

export class CustomerAlreadyExistsError extends Error {
  constructor(email: string) {
    super(`Customer with email ${email} already exists`);
    this.name = "CustomerAlreadyExistsError";
  }
}

export class CustomerNotFoundError extends Error {
  constructor(id: string) {
    super(`Customer with id ${id} not found`);
    this.name = "CustomerNotFoundError";
  }
}

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async createCustomer(input: {
    email: string;
    firstName: string;
    lastName: string;
  }): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new CustomerAlreadyExistsError(input.email);
    }

    const crmCustomer = await this.crmClient.createCustomer({
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName
    });

    return this.repository.create({
      ...input,
      externalCrmId: crmCustomer.crmId
    });
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new CustomerNotFoundError(id);
    }
    return customer;
  }
}
```

