import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { HttpCorporateCrmClient } from "../../infrastructure/corporate-crm-client.js";
import { authMiddleware } from "../../middleware/auth.js";
import { PrismaCustomerRepository } from "./customer.repository.js";
import {
  createCustomerBodySchema,
  customerParamsSchema
} from "./customer.schemas.js";
import { CustomerService } from "./customer.service.js";

function toResponse(customer: {
  id: string;
  externalCrmId: string | null;
  email: string;
  firstName: string;
  lastName: string;
  status: string;
  createdAt: Date;
  updatedAt: Date;
}) {
  return {
    ...customer,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString()
  };
}

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const repository = new PrismaCustomerRepository();
  const crmClient = new HttpCorporateCrmClient();
  const service = new CustomerService(repository, crmClient);

  app.post(
    "/customers",
    { preHandler: authMiddleware },
    async (
      request: FastifyRequest<{ Body: unknown }>,
      reply: FastifyReply
    ): Promise<void> => {
      const body = createCustomerBodySchema.parse(request.body);

      const customer = await service.createCustomer(body);

      reply.status(201).send(toResponse(customer));
    }
  );

  app.get(
    "/customers/:id",
    { preHandler: authMiddleware },
    async (
      request: FastifyRequest<{ Params: unknown }>,
      reply: FastifyReply
    ): Promise<void> => {
      const params = customerParamsSchema.parse(request.params);

      const customer = await service.getCustomerById(params.id);

      reply.send(toResponse(customer));
    }
  );
}
