  public async getEmployeeByEmail(email: string): Promise<HrEmployeeRecord | null> {
    const response = await fetch(`${env.HR_SYSTEM_BASE_URL}/employees?email=${encodeURIComponent(email)}`, {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${env.HR_SYSTEM_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`HR system request failed with status ${response.status}`);
    }

    const json: unknown = await response.json();
    return hrEmployeeRecordSchema.parse(json);
  }
}
