# 9. Service layer

## `src/domain/customer/customer.service.ts`

```ts
import type { Customer } from "@prisma/client";
import type { CreateCustomerInput, CustomerResponse, UpdateCustomerStatusInput } from "./customer.schemas.js";
import { CustomerRepository } from "./customer.repository.js";
import { HrSystemClient } from "../../integrations/hr-system/hr.client.js";

export class CustomerService {
  public constructor(
    private readonly repository: CustomerRepository,
    private readonly hrClient: HrSystemClient
  ) {}

  public async createCustomer(input: CreateCustomerInput): Promise<CustomerResponse> {
    const employee = await this.hrClient.getEmployeeByEmail(input.email);

    if (employee !== null && !employee.active) {
      throw new Error("Employee exists in HR system but is inactive");
    }

    const created = await this.repository.create(input);
    return this.toResponse(created);
  }

  public async getCustomerById(id: string): Promise<CustomerResponse | null> {
    const customer = await this.repository.findById(id);
    return customer ? this.toResponse(customer) : null;
  }

  public async updateCustomerStatus(id: string, input: UpdateCustomerStatusInput): Promise<CustomerResponse> {
    const updated = await this.repository.updateStatus(id, input.status);
    return this.toResponse(updated);
  }

  private toResponse(customer: Customer): CustomerResponse {
    return {
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      status: customer.status,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
