export async function authMiddleware(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const authHeader = request.headers.authorization;

  if (!authHeader?.startsWith("Bearer ")) {
    throw request.server.httpErrors.unauthorized("Missing or invalid Authorization header");
  }

  const token = authHeader.slice("Bearer ".length).trim();

  if (token.length === 0) {
    throw request.server.httpErrors.unauthorized("Empty bearer token");
