```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { createCustomerSchema, updateCustomerStatusSchema } from "../domain/customer/customer.schemas.js";
import { authMiddleware } from "../middleware/auth.js";
import { prisma } from "../lib/db.js";
import { CustomerRepository } from "../domain/customer/customer.repository.js";
import { CustomerService } from "../domain/customer/customer.service.js";
import { HrSystemClient } from "../integrations/hr-system/hr.client.js";

const paramsWithIdSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(fastify: FastifyInstance): Promise<void> {
  const repository = new CustomerRepository(prisma);
  const hrClient = new HrSystemClient();
  const service = new CustomerService(repository, hrClient);

  fastify.addHook("preHandler", authMiddleware);

  fastify.post(
    "/customers",
    async (
      request: FastifyRequest<{ Body: z.infer<typeof createCustomerSchema> }>,
      reply: FastifyReply
    ) => {
      const body = createCustomerSchema.parse(request.body);
      const result = await service.createCustomer(body);
      return reply.code(201).send(result);
    }
  );

  fastify.get(
    "/customers/:id",
    async (
      request: FastifyRequest<{ Params: z.infer<typeof paramsWithIdSchema> }>,
      reply: FastifyReply
    ) => {
      const params = paramsWithIdSchema.parse(request.params);
      const result = await service.getCustomerById(params.id);

      if (result === null) {
        throw fastify.httpErrors.notFound("Customer not found");
      }

      return reply.send(result);
    }
  );

  fastify.patch(
    "/customers/:id/status",
    async (
      request: FastifyRequest<{
        Params: z.infer<typeof paramsWithIdSchema>;
        Body: z.infer<typeof updateCustomerStatusSchema>;
      }>,
      reply: FastifyReply
    ) => {
      const params = paramsWithIdSchema.parse(request.params);
      const body = updateCustomerStatusSchema.parse(request.body);
      const result = await service.updateCustomerStatus(params.id, body);
      return reply.send(result);
    }
  );
}
```

