# 11. Auth middleware

This is a stub that can be wired to your corporate OIDC/JWT validation library.

## `src/auth/auth-middleware.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { UnauthorizedError } from "../core/errors.js";

type JwtClaims = {
  sub: string;
  roles?: string[];
  iss: string;
  aud: string | string[];
};

function parseBearerToken(authHeader: string | undefined): string | null {
  if (!authHeader) return null;
  const [scheme, token] = authHeader.split(" ");
  if (scheme !== "Bearer" || !token) return null;
  return token;
}

// Replace with real JWT verification against corporate identity provider
async function verifyCorporateJwt(token: string): Promise<JwtClaims> {
  if (token === "valid-token") {
    return {
      sub: "user-123",
      roles: ["admin"],
      iss: "https://issuer.example.com",
      aud: "enterprise-microservice"
    };
  }
  throw new UnauthorizedError("Invalid token");
}

export async function authenticate(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const token = parseBearerToken(request.headers.authorization);
  if (!token) {
    throw new UnauthorizedError("Missing bearer token");
  }

  const claims = await verifyCorporateJwt(token);

  request.principal = {
    subject: claims.sub,
    roles: claims.roles ?? []
  };
}
```

