# 12. Corporate integration client

This demonstrates a typed adapter for an existing corporate system.

## `src/integrations/corporate-directory-client.ts`

```ts
import { z } from "zod";
import { IntegrationError } from "../core/errors.js";

const DirectoryUserSchema = z.object({
  id: z.string(),
  email: z.string().email(),
  firstName: z.string(),
  lastName: z.string()
});

export type DirectoryUser = z.infer<typeof DirectoryUserSchema>;

export interface CorporateDirectoryClient {
  getUserByExternalId(externalId: string): Promise<DirectoryUser | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  public constructor(private readonly baseUrl: string) {}

  public async getUserByExternalId(externalId: string): Promise<DirectoryUser | null> {
    const response = await fetch(`${this.baseUrl}/directory/users/${encodeURIComponent(externalId)}`);

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new IntegrationError("Corporate directory request failed", {
        status: response.status
      });
    }

    const json: unknown = await response.json();
    const parsed = DirectoryUserSchema.safeParse(json);

    if (!parsed.success) {
      throw new IntegrationError("Corporate directory returned invalid payload", parsed.error.flatten());
    }

    return parsed.data;
  }
}
```

