export type UserCreatedEvent = z.infer<typeof UserCreatedEventSchema>;

export interface EventBus {
  publishUserCreated(event: UserCreatedEvent): Promise<void>;
}

export class HttpEventBus implements EventBus {
  public constructor(private readonly baseUrl: string) {}

  public async publishUserCreated(event: UserCreatedEvent): Promise<void> {
    const validated = UserCreatedEventSchema.parse(event);

    const response = await fetch(`${this.baseUrl}/events`, {
      method: "POST",
      headers: {
        "content-type": "application/json"
      },
      body: JSON.stringify(validated)
    });

    if (!response.ok) {
      throw new IntegrationError("Failed to publish event", {
        status: response.status
      });
    }
  }
}
