# 17. Service layer

## `src/modules/users/user.service.ts`

```ts
import { AppError, NotFoundError, ValidationError } from "../../core/errors.js";
import type { CorporateDirectoryClient } from "../../integrations/corporate-directory-client.js";
import type { EventBus } from "../../integrations/event-bus.js";
import type { CreateUserRequest } from "./user.schemas.js";
import type { UserRepository } from "./user.repository.js";
import type { User } from "@prisma/client";

export interface UserService {
  createUser(input: CreateUserRequest): Promise<User>;
  getUserById(id: string): Promise<User>;
}

export class DefaultUserService implements UserService {
  public constructor(
    private readonly userRepository: UserRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient,
    private readonly eventBus: EventBus
  ) {}

  public async createUser(input: CreateUserRequest): Promise<User> {
    const existing = await this.userRepository.findByEmail(input.email);
    if (existing) {
      throw new ValidationError("User with this email already exists");
    }

    if (input.externalId) {
      const directoryUser = await this.corporateDirectoryClient.getUserByExternalId(input.externalId);
      if (!directoryUser) {
        throw new ValidationError("External user not found in corporate directory");
      }

      if (directoryUser.email !== input.email) {
        throw new ValidationError("Email does not match corporate directory record");
      }
    }

    try {
      const created = await this.userRepository.create(input);

      await this.eventBus.publishUserCreated({
        type: "user.created",
        payload: {
          userId: created.id,
          email: created.email
        }
      });

      return created;
    } catch (error: unknown) {
      if (error instanceof AppError) {
        throw error;
      }
      throw new AppError("USER_CREATE_FAILED", "Failed to create user", 500, error);
    }
  }

  public async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundError("User not found");
    }
    return user;
  }
}
```

