# 18. Routes

## `src/modules/users/user.routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { authenticate } from "../../auth/auth-middleware.js";
import { HttpCorporateDirectoryClient } from "../../integrations/corporate-directory-client.js";
import { HttpEventBus } from "../../integrations/event-bus.js";
import { env } from "../../config/env.js";
import { CreateUserRequestSchema, UserResponseSchema } from "./user.schemas.js";
import { PrismaUserRepository } from "./user.repository.js";
import { DefaultUserService } from "./user.service.js";
import { toUserResponse } from "./user.types.js";
import { ValidationError } from "../../core/errors.js";

const ParamsSchema = z.object({
  id: z.string().uuid()
});

export async function userRoutes(fastify: FastifyInstance): Promise<void> {
  const userRepository = new PrismaUserRepository(fastify.prisma);
  const directoryClient = new HttpCorporateDirectoryClient(env.CORPORATE_DIRECTORY_URL);
  const eventBus = new HttpEventBus(env.EVENT_BUS_URL);
  const userService = new DefaultUserService(userRepository, directoryClient, eventBus);

  fastify.post("/users", { preHandler: authenticate }, async (request, reply) => {
    const parsedBody = CreateUserRequestSchema.safeParse(request.body);
    if (!parsedBody.success) {
      throw new ValidationError("Invalid request body", parsedBody.error.flatten());
    }

    const user = await userService.createUser(parsedBody.data);
    const response = UserResponseSchema.parse(toUserResponse(user));

    return reply.code(201).send(response);
  });

  fastify.get("/users/:id", { preHandler: authenticate }, async (request, reply) => {
    const parsedParams = ParamsSchema.safeParse(request.params);
    if (!parsedParams.success) {
      throw new ValidationError("Invalid path parameters", parsedParams.error.flatten());
    }

    const user = await userService.getUserById(parsedParams.data.id);
    const response = UserResponseSchema.parse(toUserResponse(user));

    return reply.code(200).send(response);
  });
}
```

