Service:

```java
package com.acme.orders.service;

import com.acme.orders.api.dto.CreateOrderRequest;
import com.acme.orders.api.dto.OrderResponse;
import com.acme.orders.domain.OrderStatus;
import com.acme.orders.integration.ErpClient;
import com.acme.orders.persistence.OrderEntity;
import com.acme.orders.persistence.OrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderApplicationService {

    private final OrderRepository orderRepository;
    private final ErpClient erpClient;

    public OrderApplicationService(OrderRepository orderRepository, ErpClient erpClient) {
        this.orderRepository = orderRepository;
        this.erpClient = erpClient;
    }

    @Transactional
    public OrderResponse createOrder(CreateOrderRequest request) {
        OrderEntity entity = new OrderEntity();
        entity.setCustomerId(request.customerId());
        entity.setProductCode(request.productCode());
        entity.setQuantity(request.quantity());
        entity.setStatus(OrderStatus.CREATED);

        entity = orderRepository.save(entity);

        boolean submitted = erpClient.submitOrder(
            entity.getCustomerId(),
            entity.getProductCode(),
            entity.getQuantity()
        );

        entity.setStatus(submitted ? OrderStatus.SUBMITTED_TO_ERP : OrderStatus.FAILED);
        entity = orderRepository.save(entity);

        return new OrderResponse(
            entity.getId(),
            entity.getCustomerId(),
            entity.getProductCode(),
            entity.getQuantity(),
            entity.getStatus().name()
        );
    }
}
