```ts
import type { PrismaClient, Customer as PrismaCustomer } from "@prisma/client";
import type { CreateCustomerInput, Customer, CustomerStatus } from "../domain/customer.js";

function mapPrismaCustomer(record: PrismaCustomer): Customer {
  return {
    id: record.id,
    externalCrmId: record.externalCrmId,
    email: record.email,
    firstName: record.firstName,
    lastName: record.lastName,
    status: record.status as CustomerStatus,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt
  };
}

export class CustomerRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async create(input: CreateCustomerInput): Promise<Customer> {
    const record = await this.prisma.customer.create({
      data: {
        externalCrmId: input.externalCrmId,
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName,
        status: "ACTIVE"
      }
    });

    return mapPrismaCustomer(record);
  }

  async findById(id: string): Promise<Customer | null> {
    const record = await this.prisma.customer.findUnique({
      where: { id }
    });

    return record ? mapPrismaCustomer(record) : null;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const record = await this.prisma.customer.findUnique({
      where: { email }
    });

    return record ? mapPrismaCustomer(record) : null;
  }

  async updateStatus(id: string, status: CustomerStatus): Promise<Customer> {
    const record = await this.prisma.customer.update({
      where: { id },
      data: { status }
    });

    return mapPrismaCustomer(record);
  }
}
```

