});

export type CrmCustomerStatus = z.infer<typeof crmCustomerStatusSchema>;
```

`src/integrations/corporateCrmClient.ts`

```ts
import { IntegrationError } from "../domain/errors.js";
import { crmCustomerStatusSchema, type CrmCustomerStatus } from "./types.js";

export interface CorporateCrmClient {
  getCustomerStatus(externalCrmId: string): Promise<CrmCustomerStatus>;
}

interface CorporateCrmClientDeps {
  baseUrl: string;
  apiKey: string;
  fetchFn?: typeof fetch;
}

export class HttpCorporateCrmClient implements CorporateCrmClient {
  private readonly fetchFn: typeof fetch;

  constructor(private readonly deps: CorporateCrmClientDeps) {
    this.fetchFn = deps.fetchFn ?? fetch;
  }

  async getCustomerStatus(externalCrmId: string): Promise<CrmCustomerStatus> {
    const response = await this.fetchFn(
      `${this.deps.baseUrl}/customers/${encodeURIComponent(externalCrmId)}/status`,
      {
        method: "GET",
        headers: {
          "content-type": "application/json",
          "x-api-key": this.deps.apiKey
        }
      }
    );

    if (!response.ok) {
      throw new IntegrationError(`CRM request failed with status ${response.status}`);
    }

    const json: unknown = await response.json();
    return crmCustomerStatusSchema.parse(json);
  }
}
```

This abstraction makes it easy to replace HTTP with:
- SOAP client
- MQ client
- internal SDK
- enterprise ESB connector

