# 13. Service layer

`src/services/customerService.ts`

```ts
import type { Customer } from "../domain/customer.js";
import { ConflictError, NotFoundError } from "../domain/errors.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { CorporateCrmClient } from "../integrations/corporateCrmClient.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async createCustomer(input: {
    externalCrmId: string;
    email: string;
    firstName: string;
    lastName: string;
  }): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new ConflictError(`Customer with email ${input.email} already exists`);
    }

    return this.customerRepository.create(input);
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }

    return customer;
  }

  async syncCustomerStatus(id: string): Promise<Customer> {
    const customer = await this.getCustomerById(id);

    const crmStatus = await this.crmClient.getCustomerStatus(customer.externalCrmId);

    return this.customerRepository.updateStatus(customer.id, crmStatus.status);
  }
}
```

