# 14. Routes

`src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import { CustomerRepository } from "../repositories/customerRepository.js";
import { CustomerService } from "../services/customerService.js";
import { HttpCorporateCrmClient } from "../integrations/corporateCrmClient.js";
import { env } from "../config/env.js";
import {
  createCustomerBodySchema,
  customerParamsSchema,
  updateCustomerStatusBodySchema
} from "../schemas/customerSchemas.js";
import { ConflictError, IntegrationError, NotFoundError } from "../domain/errors.js";

function serializeCustomer(customer: {
  id: string;
  externalCrmId: string;
  email: string;
  firstName: string;
  lastName: string;
  status: string;
  createdAt: Date;
  updatedAt: Date;
}) {
  return {
    ...customer,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString()
  };
}

export async function customerRoutes(fastify: FastifyInstance): Promise<void> {
  const repository = new CustomerRepository(fastify.prisma);
  const crmClient = new HttpCorporateCrmClient({
    baseUrl: env.CRM_BASE_URL,
    apiKey: env.CRM_API_KEY
  });
  const service = new CustomerService(repository, crmClient);

  fastify.post("/customers", async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const body = createCustomerBodySchema.parse(request.body);
      const customer = await service.createCustomer(body);
      return reply.code(201).send(serializeCustomer(customer));
    } catch (error: unknown) {
      return handleRouteError(error, reply);
    }
  });

  fastify.get("/customers/:id", async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const params = customerParamsSchema.parse(request.params);
      const customer = await service.getCustomerById(params.id);
      return reply.send(serializeCustomer(customer));
    } catch (error: unknown) {
      return handleRouteError(error, reply);
    }
  });

  fastify.post("/customers/:id/sync-status", async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const params = customerParamsSchema.parse(request.params);
      const customer = await service.syncCustomerStatus(params.id);
      return reply.send(serializeCustomer(customer));
    } catch (error: unknown) {
      return handleRouteError(error, reply);
    }
  });

  fastify.patch("/customers/:id/status", async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const params = customerParamsSchema.parse(request.params);
      const body = updateCustomerStatusBodySchema.parse(request.body);

      const existing = await repository.findById(params.id);
      if (!existing) {
        throw new NotFoundError(`Customer ${params.id} not found`);
      }

      const updated = await repository.updateStatus(params.id, body.status);
      return reply.send(serializeCustomer(updated));
    } catch (error: unknown) {
      return handleRouteError(error, reply);
    }
  });
}

function handleRouteError(error: unknown, reply: FastifyReply) {
  if (error instanceof ZodError) {
    return reply.code(400).send({
      message: "Validation failed",
      issues: error.issues
    });
  }

  if (error instanceof NotFoundError) {
    return reply.code(404).send({ message: error.message, code: error.code });
  }

  if (error instanceof ConflictError) {
    return reply.code(409).send({ message: error.message, code: error.code });
  }

  if (error instanceof IntegrationError) {
    return reply.code(502).send({ message: error.message, code: error.code });
  }

  return reply.code(500).send({
    message: "Internal server error"
  });
}
```

