# `src/integrations/hr-system.client.ts`

This simulates integration with an existing corporate HR system.

```ts
import { IntegrationError } from "../core/errors.js";
import { env } from "../config/env.js";

export interface HrEmployeeRecord {
  readonly employeeNumber: string;
  readonly legalName: string;
  readonly emailAddress: string;
  readonly departmentCode: string;
  readonly active: boolean;
}

export class HrSystemClient {
  async fetchEmployeeById(employeeId: string): Promise<HrEmployeeRecord | null> {
    const url = `${env.HR_SYSTEM_BASE_URL}/api/employees/${encodeURIComponent(employeeId)}`;

    const response = await fetch(url, {
      method: "GET",
      headers: {
        "content-type": "application/json",
        "x-api-key": env.HR_SYSTEM_API_KEY
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new IntegrationError("Failed to fetch employee from HR system", {
        status: response.status
      });
    }

    const data: unknown = await response.json();

    if (!isHrEmployeeRecord(data)) {
      throw new IntegrationError("Invalid HR system response shape", data);
    }

    return data;
  }
}

function isHrEmployeeRecord(value: unknown): value is HrEmployeeRecord {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const v = value as Record<string, unknown>;

  return (
    typeof v.employeeNumber === "string" &&
    typeof v.legalName === "string" &&
    typeof v.emailAddress === "string" &&
    typeof v.departmentCode === "string" &&
    typeof v.active === "boolean"
  );
}
