```ts
import { Employee } from "./employee.types.js";
import { EmployeeId, asEmployeeId } from "../../core/types.js";

export interface EmployeeRepository {
  findById(id: EmployeeId): Promise<Employee | null>;
  create(input: Omit<Employee, "id">): Promise<Employee>;
}

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly store = new Map<EmployeeId, Employee>();

  async findById(id: EmployeeId): Promise<Employee | null> {
    return this.store.get(id) ?? null;
  }

  async create(input: Omit<Employee, "id">): Promise<Employee> {
    const id = asEmployeeId(crypto.randomUUID());
    const employee: Employee = { id, ...input };
    this.store.set(id, employee);
    return employee;
  }
}
