# `src/modules/employees/employee.service.ts`

```ts
import { NotFoundError } from "../../core/errors.js";
import { asEmployeeId } from "../../core/types.js";
import { HrSystemClient } from "../../integrations/hr-system.client.js";
import { EmployeeRepository } from "./employee.repository.js";
import { CreateEmployeeInput, Employee } from "./employee.types.js";

export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly hrClient: HrSystemClient
  ) {}

  async getEmployeeById(id: string): Promise<Employee> {
    const employeeId = asEmployeeId(id);

    const existing = await this.repository.findById(employeeId);
    if (existing) {
      return existing;
    }

    const hrRecord = await this.hrClient.fetchEmployeeById(id);
    if (!hrRecord) {
      throw new NotFoundError(`Employee not found: ${id}`);
    }

    return {
      id: employeeId,
      name: hrRecord.legalName,
      email: hrRecord.emailAddress,
      department: hrRecord.departmentCode,
      isActive: hrRecord.active
    };
  }

  async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    return this.repository.create({
      name: input.name,
      email: input.email,
      department: input.department,
      isActive: true
    });
  }
}
