# `src/modules/employees/employee.routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { ZodError } from "zod";
import { ValidationError } from "../../core/errors.js";
import {
  createEmployeeBodySchema,
  employeeIdParamsSchema
} from "./employee.schemas.js";
import { EmployeeService } from "./employee.service.js";

export async function employeeRoutes(
  fastify: FastifyInstance,
  deps: { employeeService: EmployeeService }
): Promise<void> {
  fastify.get("/employees/:id", async (request, reply) => {
    const parsed = employeeIdParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      throw new ValidationError("Invalid employee id params", parsed.error.flatten());
    }

    const employee = await deps.employeeService.getEmployeeById(parsed.data.id);
    return reply.code(200).send(employee);
  });

  fastify.post("/employees", async (request, reply) => {
    const parsed = createEmployeeBodySchema.safeParse(request.body);
    if (!parsed.success) {
      throw new ValidationError("Invalid create employee payload", parsed.error.flatten());
    }

    const employee = await deps.employeeService.createEmployee(parsed.data);
    return reply.code(201).send(employee);
  });

  fastify.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Request failed");

    if (error instanceof ValidationError) {
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message,
        details: error.details
      });
    }

    if (error instanceof ZodError) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        message: "Validation failed",
        details: error.flatten()
      });
    }

    if (
      typeof error === "object" &&
      error !== null &&
      "statusCode" in error &&
      "code" in error &&
      "message" in error
    ) {
      const appError = error as {
        statusCode: number;
        code: string;
        message: string;
      };

      return reply.status(appError.statusCode).send({
        error: appError.code,
        message: appError.message
      });
    }

    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });
}
```

