import Fastify from "fastify";
import helmet from "@fastify/helmet";
import sensible from "@fastify/sensible";
import { env } from "./config/env.js";
import { logger } from "./core/logger.js";
import { requestContextMiddleware } from "./middleware/request-context.js";
import { corporateAuthMiddleware } from "./middleware/auth.js";
import { healthRoutes } from "./routes/health.routes.js";
import { employeeRoutes } from "./modules/employees/employee.routes.js";
import { InMemoryEmployeeRepository } from "./modules/employees/employee.repository.js";
import { EmployeeService } from "./modules/employees/employee.service.js";
import { HrSystemClient } from "./integrations/hr-system.client.js";

export async function buildApp() {
  const app = Fastify({
    logger
  });

  await app.register(helmet);
  await app.register(sensible);

  app.addHook("onRequest", requestContextMiddleware);
  app.addHook("preHandler", corporateAuthMiddleware);

  await app.register(healthRoutes, { prefix: "/api" });

  const employeeRepository = new InMemoryEmployeeRepository();
  const hrClient = new HrSystemClient();
  const employeeService = new EmployeeService(employeeRepository, hrClient);

  await app.register(
    async (instance) => {
      await employeeRoutes(instance, { employeeService });
    },
    { prefix: "/api" }
  );

  return app;
}
