# 11. Service layer

## `src/domain/customer/customer.service.ts`

```ts
import { CrmClient } from "../../integrations/crm/crm.client.js";
import { NotFoundError, ValidationError } from "../../shared/errors.js";
import { CustomerRepository } from "./customer.repository.js";
import { CreateCustomerRequest } from "./customer.schemas.js";
import { Customer } from "./customer.types.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly crmClient: CrmClient
  ) {}

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new ValidationError("Customer with this email already exists", {
        email: input.email
      });
    }

    const crmContact = await this.crmClient.createContact({
      email: input.email,
      givenName: input.firstName,
      familyName: input.lastName
    });

    return this.customerRepository.create({
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      externalCrmId: crmContact.contactId
    });
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new NotFoundError("Customer not found", { id });
    }
    return customer;
  }
}
