# 12. Auth middleware

## `src/infrastructure/security/auth.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { IdentityClient } from "../../integrations/identity/identity.client.js";
import { UnauthorizedError } from "../../shared/errors.js";

declare module "fastify" {
  interface FastifyRequest {
    user?: {
      subjectId: string;
      email: string;
      roles: string[];
    };
  }
}

const identityClient = new IdentityClient();

export async function authenticate(
  request: FastifyRequest,
  _reply: FastifyReply
): Promise<void> {
  const authHeader = request.headers.authorization;

  if (!authHeader?.startsWith("Bearer ")) {
    throw new UnauthorizedError("Missing or invalid Authorization header");
  }

  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) {
    throw new UnauthorizedError("Bearer token is empty");
  }

  const user = await identityClient.introspectBearerToken(token);
  request.user = user;
}
```

