    lastName: customer.lastName,
    externalCrmId: customer.externalCrmId,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString()
  });
}

export async function registerCustomerRoutes(app: FastifyInstance): Promise<void> {
  const repository = new CustomerRepository();
  const crmClient = new CrmClient();
  const service = new CustomerService(repository, crmClient);

  app.post("/customers", { preHandler: [authenticate] }, async (request, reply) => {
    const body = createCustomerRequestSchema.parse(request.body);
    const customer = await service.createCustomer(body);
    return reply.status(201).send(toCustomerResponse(customer));
  });

  app.get(
    "/customers/:id",
    { preHandler: [authenticate] },
    async (request, reply) => {
      const params = customerIdSchema.parse((request.params as { id?: unknown }).id);
      const customer = await service.getCustomerById(params);
      return reply.status(200).send(toCustomerResponse(customer));
    }
  );
}
