# Application service

## `src/application/customer-service.ts`

```ts
import type { Customer, CustomerId, CreateCustomerInput } from "../domain/customer.js";
import {
  CustomerAlreadyExistsError,
  CustomerNotFoundError,
  ExternalIntegrationError
} from "../domain/errors.js";
import type {
  CorporateCrmPort,
  CorporateIdentityPort,
  CustomerRepository
} from "../domain/ports.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly crmPort: CorporateCrmPort,
    private readonly identityPort: CorporateIdentityPort
  ) {}

  public async getCustomerById(
    requesterSubject: string,
    customerId: CustomerId
  ): Promise<Customer> {
    const authorized = await this.identityPort.validateSubjectAccess(
      requesterSubject,
      customerId
    );

    if (!authorized) {
      throw new ExternalIntegrationError("identity", "Access denied by corporate identity");
    }

    const customer = await this.customerRepository.findById(customerId);

    if (customer === null) {
      throw new CustomerNotFoundError(customerId);
    }

    return customer;
  }

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);

    if (existing !== null) {
      throw new CustomerAlreadyExistsError(input.email);
    }

    const created = await this.customerRepository.create(input);
    await this.crmPort.registerCustomer(created);

    return created;
  }
}
```

