import { PrismaClient } from "@prisma/client";
import type { CustomerRepository } from "../../domain/ports.js";
import type { Customer, CustomerId, CreateCustomerInput, Email } from "../../domain/customer.js";
import { CustomerSchema } from "../../domain/customer.js";

export class PrismaCustomerRepository implements CustomerRepository {
  public constructor(private readonly prisma: PrismaClient) {}

  public async findById(id: CustomerId): Promise<Customer | null> {
    const row = await this.prisma.customer.findUnique({
      where: { id }
    });

    if (row === null) {
      return null;
    }

    return CustomerSchema.parse(row);
  }

  public async findByEmail(email: Email): Promise<Customer | null> {
    const row = await this.prisma.customer.findUnique({
      where: { email }
    });

    if (row === null) {
      return null;
    }

    return CustomerSchema.parse(row);
  }

  public async create(input: CreateCustomerInput): Promise<Customer> {
    const row = await this.prisma.customer.create({
      data: {
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName,
        status: "ACTIVE"
      }
    });

    return CustomerSchema.parse(row);
  }
}
