# Corporate integrations

In real enterprise systems, these often use mTLS, OAuth2 client credentials, proxies, retries, circuit breakers, and audit headers. Here’s a typed adapter pattern.

## `src/infrastructure/integrations/corporate-crm-client.ts`

```ts
import { z } from "zod";
import type { CorporateCrmPort } from "../../domain/ports.js";
import type { Customer } from "../../domain/customer.js";
import { ExternalIntegrationError } from "../../domain/errors.js";

const CrmRegisterPayloadSchema = z.object({
  customerId: z.string().uuid(),
  email: z.string().email(),
  firstName: z.string(),
  lastName: z.string(),
  status: z.string()
});

type CrmRegisterPayload = z.infer<typeof CrmRegisterPayloadSchema>;

export class CorporateCrmClient implements CorporateCrmPort {
  public constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  public async registerCustomer(customer: Customer): Promise<void> {
    const payload: CrmRegisterPayload = CrmRegisterPayloadSchema.parse({
      customerId: customer.id,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      status: customer.status
    });

    const response = await fetch(`${this.baseUrl}/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.apiKey
      },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new ExternalIntegrationError(
        "crm",
        `Unexpected status ${response.status}`
      );
    }
  }
}
```

## `src/infrastructure/integrations/corporate-identity-client.ts`

```ts
import { z } from "zod";
import type { CorporateIdentityPort } from "../../domain/ports.js";
import type { CustomerId } from "../../domain/customer.js";
import { ExternalIntegrationError } from "../../domain/errors.js";

const IdentityResponseSchema = z.object({
  authorized: z.boolean()
});

export class CorporateIdentityClient implements CorporateIdentityPort {
  public constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  public async validateSubjectAccess(
    subject: string,
    customerId: CustomerId
  ): Promise<boolean> {
    const response = await fetch(
      `${this.baseUrl}/access/validate?subject=${encodeURIComponent(subject)}&resource=${encodeURIComponent(customerId)}`,
      {
        method: "GET",
        headers: {
          "x-api-key": this.apiKey
        }
      }
    );

    if (!response.ok) {
      throw new ExternalIntegrationError(
        "identity",
        `Unexpected status ${response.status}`
      );
    }

    const json: unknown = await response.json();
    const parsed = IdentityResponseSchema.parse(json);
    return parsed.authorized;
  }
}
```

