# Auth plugin

## `src/interfaces/http/plugins/auth.ts`

```ts
import fp from "fastify-plugin";
import jwt from "@fastify/jwt";
import { env } from "../../../config/env.js";

declare module "fastify" {
  interface FastifyRequest {
    auth: {
      subject: string;
    };
  }
}

export const authPlugin = fp(async (fastify) => {
  await fastify.register(jwt, {
    secret: env.JWT_PUBLIC_KEY,
    verify: {
      algorithms: ["RS256"]
    }
  });

  fastify.decorateRequest("auth", null);

  fastify.addHook("preHandler", async (request) => {
    await request.jwtVerify();

    const sub = typeof request.user === "object" && request.user !== null && "sub" in request.user
      ? request.user.sub
      : undefined;

    if (typeof sub !== "string" || sub.length === 0) {
      throw fastify.httpErrors.unauthorized("Missing subject");
    }

    request.auth = { subject: sub };
  });
});
```

