# Better branded ID helpers

## Replace `src/domain/customer.ts` with this improved version

```ts
import { z } from "zod";
import type { Brand } from "../shared/types.js";

export type CustomerId = Brand<string, "CustomerId">;
export type Email = Brand<string, "Email">;

export const toCustomerId = (value: string): CustomerId => value as CustomerId;
export const toEmail = (value: string): Email => value as Email;

export const CustomerStatusSchema = z.enum(["ACTIVE", "INACTIVE", "SUSPENDED"]);
export type CustomerStatus = z.infer<typeof CustomerStatusSchema>;

export const CustomerSchema = z.object({
  id: z.string().uuid().transform(toCustomerId),
  email: z.string().email().transform(toEmail),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100),
  status: CustomerStatusSchema,
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date()
});

export type Customer = z.infer<typeof CustomerSchema>;

export const CreateCustomerInputSchema = z.object({
  email: z.string().email().transform(toEmail),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100)
});

export type CreateCustomerInput = z.infer<typeof CreateCustomerInputSchema>;
```

