```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { PrismaClient } from "@prisma/client";
import { logger } from "./config/logger.js";
import { env } from "./config/env.js";
import { authPlugin } from "./interfaces/http/plugins/auth.js";
import { errorHandlerPlugin } from "./interfaces/http/plugins/error-handler.js";
import { healthRoutes } from "./interfaces/http/routes/health-routes.js";
import { customerRoutes } from "./interfaces/http/routes/customer-routes.js";
import { PrismaCustomerRepository } from "./infrastructure/db/prisma-customer-repository.js";
import { CorporateCrmClient } from "./infrastructure/integrations/corporate-crm-client.js";
import { CorporateIdentityClient } from "./infrastructure/integrations/corporate-identity-client.js";
import { CustomerService } from "./application/customer-service.js";

export async function buildApp() {
  const fastify = Fastify({
    logger
  });

  const prisma = new PrismaClient();

  const customerRepository = new PrismaCustomerRepository(prisma);
  const crmClient = new CorporateCrmClient(env.CRM_BASE_URL, env.CRM_API_KEY);
  const identityClient = new CorporateIdentityClient(
    env.IDENTITY_BASE_URL,
    env.IDENTITY_API_KEY
  );

  const customerService = new CustomerService(
    customerRepository,
    crmClient,
    identityClient
  );

  await fastify.register(sensible);
  await fastify.register(errorHandlerPlugin);
  await fastify.register(authPlugin);

  await fastify.register(healthRoutes, { prefix: "/api" });
  await fastify.register(customerRoutes, {
    prefix: "/api",
    customerService
  });

  fastify.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return fastify;
}
```

