# `src/services/corporate-crm-client.ts`

Typed integration client for an existing corporate CRM.

```ts
import axios, { AxiosInstance } from "axios";
import { z } from "zod";
import { env } from "../config/env.js";
import { BadGatewayError } from "../domain/errors.js";
import { CustomerSchema, CreateCustomerRequest, Customer } from "../domain/customer.js";

const CrmCustomerResponseSchema = CustomerSchema;

export class CorporateCrmClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: env.CRM_BASE_URL,
      timeout: env.CRM_TIMEOUT_MS,
      headers: {
        "Content-Type": "application/json"
      }
    });
  }

  async getCustomerById(customerId: string): Promise<Customer> {
    try {
      const response = await this.http.get(`/customers/${customerId}`);
      const parsed = CrmCustomerResponseSchema.safeParse(response.data);

      if (!parsed.success) {
        throw new BadGatewayError("Invalid CRM response", parsed.error.format());
      }

      return parsed.data;
    } catch (error) {
      if (error instanceof BadGatewayError) {
        throw error;
      }

      throw new BadGatewayError("Failed to fetch customer from CRM", {
        cause: error instanceof Error ? error.message : "unknown"
      });
    }
  }

  async createCustomer(payload: CreateCustomerRequest): Promise<Customer> {
    try {
      const response = await this.http.post("/customers", payload);
      const parsed = CrmCustomerResponseSchema.safeParse(response.data);

      if (!parsed.success) {
        throw new BadGatewayError("Invalid CRM response", parsed.error.format());
      }

      return parsed.data;
    } catch (error) {
      if (error instanceof BadGatewayError) {
        throw error;
      }

      throw new BadGatewayError("Failed to create customer in CRM", {
        cause: error instanceof Error ? error.message : "unknown"
      });
    }
  }
}
```

