} from "../domain/customer.js";
import { CustomerService } from "../services/customer-service.js";
import { ValidationError } from "../domain/errors.js";

const GetCustomerParamsSchema = z.object({
  id: CustomerIdSchema
});

export async function customerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get("/customers/:id", async (request, reply) => {
    const paramsResult = GetCustomerParamsSchema.safeParse(request.params);

    if (!paramsResult.success) {
      throw new ValidationError("Invalid customer id", paramsResult.error.format());
    }

    const customer = await customerService.getCustomer(paramsResult.data.id);
    return reply.status(200).send(customer);
  });

  app.post("/customers", async (request, reply) => {
    const bodyResult = CreateCustomerRequestSchema.safeParse(request.body);

    if (!bodyResult.success) {
      throw new ValidationError("Invalid request body", bodyResult.error.format());
    }

    const customer = await customerService.createCustomer(bodyResult.data);
    return reply.status(201).send(customer);
  });
}
