```ts
import { Injectable } from '@nestjs/common';
import { AppError } from '../../common/errors/app.error';
import { CustomersRepository } from './customers.repository';
import { type CreateCustomerDto } from './dto/create-customer.dto';
import { type CustomerResponse } from './dto/customer.response';

@Injectable()
export class CustomersService {
  constructor(private readonly repository: CustomersRepository) {}

  async createCustomer(dto: CreateCustomerDto): Promise<CustomerResponse> {
    const existing = await this.repository.findByExternalId(dto.externalId);

    if (existing) {
      throw new AppError(
        'CUSTOMER_ALREADY_EXISTS',
        `Customer with externalId ${dto.externalId} already exists`,
        409,
        { externalId: dto.externalId }
      );
    }

    const customer = await this.repository.create(dto);

    return {
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }

  async getCustomerById(id: string): Promise<CustomerResponse> {
    const customer = await this.repository.findById(id);

    if (!customer) {
      throw new AppError('CUSTOMER_NOT_FOUND', `Customer ${id} not found`, 404, { id });
    }

    return {
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
```

