```ts
import { Injectable } from '@nestjs/common';
import axios, { type AxiosInstance, type AxiosRequestConfig } from 'axios';
import { AppConfigService } from '../config/config.service';
import { AppError } from '../errors/app.error';

@Injectable()
export class HttpClientService {
  private readonly client: AxiosInstance;

  constructor(config: AppConfigService) {
    this.client = axios.create({
      baseURL: config.get('CORPORATE_API_BASE_URL'),
      timeout: config.get('CORPORATE_API_TIMEOUT_MS'),
      headers: {
        'Content-Type': 'application/json'
      }
    });
  }

  async get<TResponse>(url: string, config?: AxiosRequestConfig): Promise<TResponse> {
    try {
      const response = await this.client.get<TResponse>(url, config);
      return response.data;
    } catch (error) {
      throw new AppError(
        'CORPORATE_HTTP_GET_FAILED',
        `GET ${url} failed`,
        502,
        { url, cause: error instanceof Error ? error.message : 'unknown' }
      );
    }
  }

  async post<TRequest, TResponse>(
    url: string,
    data: TRequest,
    config?: AxiosRequestConfig
  ): Promise<TResponse> {
    try {
      const response = await this.client.post<TResponse>(url, data, config);
      return response.data;
    } catch (error) {
      throw new AppError(
        'CORPORATE_HTTP_POST_FAILED',
        `POST ${url} failed`,
        502,
        { url, cause: error instanceof Error ? error.message : 'unknown' }
      );
    }
  }
}
```

