## `src/domain/customer/customerService.ts`

```ts
import type { Customer } from "./customer.js";
import type { CustomerRepository } from "./customerRepository.js";
import { NotFoundError, IntegrationError } from "../shared/errors.js";
import { err, ok, type Result } from "../shared/result.js";

export interface CorporateCustomerRecord {
  readonly externalId: string;
  readonly fullName: string;
  readonly primaryEmail: string;
  readonly active: boolean;
}

export interface CorporateCustomerGateway {
  fetchCustomer(externalId: string): Promise<CorporateCustomerRecord | null>;
}

export class CustomerService {
  public constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateGateway: CorporateCustomerGateway
  ) {}

  public async getCustomer(id: string): Promise<Result<Customer, NotFoundError>> {
    const customer = await this.repository.findById(id);
    if (customer === null) {
      return err(new NotFoundError(`Customer ${id} not found`));
    }
    return ok(customer);
  }

  public async syncCustomerFromCorporate(
    id: string,
    externalId: string
  ): Promise<Result<Customer, NotFoundError | IntegrationError>> {
    const corporateRecord = await this.corporateGateway.fetchCustomer(externalId);

    if (corporateRecord === null) {
      return err(new NotFoundError(`Corporate customer ${externalId} not found`));
    }

    const customer: Customer = {
      id,
      externalId: corporateRecord.externalId,
      name: corporateRecord.fullName,
      email: corporateRecord.primaryEmail,
      status: corporateRecord.active ? "ACTIVE" : "INACTIVE",
      createdAt: new Date()
    };

    await this.repository.save(customer);
    return ok(customer);
  }
}
```

