# 9. Infrastructure: corporate REST client

## `src/infrastructure/http/corporateApiClient.ts`

```ts
import { IntegrationError } from "../../domain/shared/errors.js";
import type { CorporateCustomerGateway, CorporateCustomerRecord } from "../../domain/customer/customerService.js";
import type { TokenProvider } from "../auth/tokenProvider.js";

export interface CorporateApiClientConfig {
  readonly baseUrl: string;
  readonly timeoutMs: number;
}

interface CorporateCustomerApiResponse {
  readonly id: string;
  readonly name: string;
  readonly email: string;
  readonly enabled: boolean;
}

export class CorporateApiClient implements CorporateCustomerGateway {
  public constructor(
    private readonly config: CorporateApiClientConfig,
    private readonly tokenProvider: TokenProvider
  ) {}

  public async fetchCustomer(externalId: string): Promise<CorporateCustomerRecord | null> {
    const token = await this.tokenProvider.getToken();
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), this.config.timeoutMs);

    try {
      const response = await fetch(
        `${this.config.baseUrl}/customers/${encodeURIComponent(externalId)}`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json"
          },
          signal: controller.signal
        }
      );

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new IntegrationError(`Corporate API returned status ${response.status}`);
      }

      const payload = (await response.json()) as CorporateCustomerApiResponse;

      return {
        externalId: payload.id,
        fullName: payload.name,
        primaryEmail: payload.email,
        active: payload.enabled
      };
    } catch (error: unknown) {
      if (error instanceof IntegrationError) {
        throw error;
      }
      throw new IntegrationError("Failed to fetch customer from corporate API");
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

