# 12. HTTP controller

## `src/interfaces/http/customerController.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import type { CustomerService } from "../../domain/customer/customerService.js";
import { IntegrationError, NotFoundError } from "../../domain/shared/errors.js";
import { customerIdParamsSchema, syncCustomerBodySchema } from "./schemas.js";
import type { CustomerResponseDto } from "./dto.js";

interface CustomerIdParams {
  readonly id: string;
}

interface SyncCustomerBody {
  readonly externalId: string;
}

function toDto(customer: {
  readonly id: string;
  readonly externalId: string;
  readonly name: string;
  readonly email: string;
  readonly status: "ACTIVE" | "INACTIVE";
  readonly createdAt: Date;
}): CustomerResponseDto {
  return {
    id: customer.id,
    externalId: customer.externalId,
    name: customer.name,
    email: customer.email,
    status: customer.status,
    createdAt: customer.createdAt.toISOString()
  };
}

export class CustomerController {
  public constructor(private readonly customerService: CustomerService) {}

  public getCustomer = async (
    request: FastifyRequest<{ Params: CustomerIdParams }>,
    reply: FastifyReply
  ): Promise<void> => {
    const params = customerIdParamsSchema.parse(request.params);
    const result = await this.customerService.getCustomer(params.id);

    if (!result.ok) {
      if (result.error instanceof NotFoundError) {
        void reply.code(404).send({ message: result.error.message });
        return;
      }
    }

    void reply.code(200).send(toDto(result.value));
  };

  public syncCustomer = async (
    request: FastifyRequest<{ Params: CustomerIdParams; Body: SyncCustomerBody }>,
    reply: FastifyReply
  ): Promise<void> => {
    const params = customerIdParamsSchema.parse(request.params);
    const body = syncCustomerBodySchema.parse(request.body);

    try {
      const result = await this.customerService.syncCustomerFromCorporate(params.id, body.externalId);

      if (!result.ok) {
        if (result.error instanceof NotFoundError) {
          void reply.code(404).send({ message: result.error.message });
          return;
        }
      }

      void reply.code(200).send(toDto(result.value));
    } catch (error: unknown) {
      if (error instanceof IntegrationError) {
        void reply.code(502).send({ message: error.message });
        return;
      }
      throw error;
    }
  };
}
```

