```ts
import { loadConfig } from "./config/env.js";
import { InMemoryCustomerRepository } from "./infrastructure/persistence/inMemoryCustomerRepository.js";
import { StaticTokenProvider } from "./infrastructure/auth/tokenProvider.js";
import { CorporateApiClient } from "./infrastructure/http/corporateApiClient.js";
import { CustomerService } from "./domain/customer/customerService.js";
import { CustomerController } from "./interfaces/http/customerController.js";
import { buildServer } from "./app/server.js";

async function main(): Promise<void> {
  const config = loadConfig(process.env);

  const repository = new InMemoryCustomerRepository();
  const tokenProvider = new StaticTokenProvider(config.corporateApiToken);

  const corporateApiClient = new CorporateApiClient(
    {
      baseUrl: config.corporateApiBaseUrl,
      timeoutMs: config.corporateApiTimeoutMs
    },
    tokenProvider
  );

  const customerService = new CustomerService(repository, corporateApiClient);
  const customerController = new CustomerController(customerService);

  const app = await buildServer(config, { customerController });

  await app.listen({
    port: config.port,
    host: "0.0.0.0"
  });
}

main().catch((error: unknown) => {
  console.error("Fatal startup error", error);
  process.exit(1);
});
