# 8. Application service layer

## `src/application/customer/customer-service.ts`

```ts
import type { CustomerRepository } from "../../domain/customer/customer-repository.js";
import type { Customer, CustomerId } from "../../domain/customer/customer.js";
import { NotFoundError, ValidationError } from "../../shared/errors.js";

export class CustomerService {
  public constructor(private readonly repository: CustomerRepository) {}

  public async getCustomerById(id: CustomerId): Promise<Customer> {
    if (id.trim().length === 0) {
      throw new ValidationError("Customer id must not be empty");
    }

    const customer = await this.repository.findById(id);

    if (customer === null) {
      throw new NotFoundError(`Customer not found: ${id}`, { customerId: id });
    }

    return customer;
  }

  public async listCustomers(): Promise<readonly Customer[]> {
    return this.repository.findAll();
  }

  public async createCustomer(input: {
    readonly id: string;
    readonly email: string;
    readonly firstName: string;
    readonly lastName: string;
  }): Promise<Customer> {
    if (input.id.trim().length === 0) {
      throw new ValidationError("Customer id must not be empty");
    }

    if (!input.email.includes("@")) {
      throw new ValidationError("Invalid email address", { email: input.email });
    }

    const customer: Customer = {
      id: input.id,
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      active: true,
      createdAt: new Date()
    };

    return this.repository.save(customer);
  }
}
```

