# 10. Corporate system integration client

This is a typed outbound client for an existing corporate directory or identity system.

## `src/infrastructure/http/corporate-directory-client.ts`

```ts
import { z } from "zod";
import { AppError } from "../../shared/errors.js";

const corporateUserSchema = z.object({
  employeeId: z.string(),
  email: z.string().email(),
  displayName: z.string(),
  department: z.string()
});

export type CorporateUser = z.infer<typeof corporateUserSchema>;

export interface CorporateDirectoryClient {
  getUserByEmail(email: string): Promise<CorporateUser | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  public constructor(
    private readonly baseUrl: string,
    private readonly fetchImpl: typeof fetch = fetch
  ) {}

  public async getUserByEmail(email: string): Promise<CorporateUser | null> {
    const url = new URL("/api/users/by-email", this.baseUrl);
    url.searchParams.set("email", email);

    const response = await this.fetchImpl(url, {
      method: "GET",
      headers: {
        "content-type": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new AppError("Corporate directory request failed", {
        code: "CORPORATE_DIRECTORY_ERROR",
        statusCode: 502,
        details: {
          upstreamStatus: response.status
        }
      });
    }

    const json: unknown = await response.json();
    return corporateUserSchema.parse(json);
  }
}
```

