## `src/interfaces/http/routes/customer-routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import type { CustomerService } from "../../../application/customer/customer-service.js";
import {
  createCustomerBodySchema,
  customerParamsSchema
} from "../schemas/customer-schemas.js";
import { authMiddleware } from "../../../infrastructure/auth/auth-middleware.js";

function toCustomerResponse(customer: {
  readonly id: string;
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
  readonly active: boolean;
  readonly createdAt: Date;
}) {
  return {
    id: customer.id,
    email: customer.email,
    firstName: customer.firstName,
    lastName: customer.lastName,
    active: customer.active,
    createdAt: customer.createdAt.toISOString()
  };
}

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.addHook("preHandler", authMiddleware);

  app.get("/customers", async (_request, reply) => {
    const customers = await customerService.listCustomers();
    return reply.send(customers.map(toCustomerResponse));
  });

  app.get("/customers/:id", async (request, reply) => {
    const params = customerParamsSchema.parse(request.params);
    const customer = await customerService.getCustomerById(params.id);
    return reply.send(toCustomerResponse(customer));
  });

  app.post("/customers", async (request, reply) => {
    const body = createCustomerBodySchema.parse(request.body);
    const customer = await customerService.createCustomer(body);
    return reply.code(201).send(toCustomerResponse(customer));
  });
}
```

