```ts
import Fastify from "fastify";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import type { AppConfig } from "./config/types.js";
import { createLogger } from "./infrastructure/logging/logger.js";
import { InMemoryCustomerRepository } from "./infrastructure/db/in-memory-customer-repository.js";
import { CustomerService } from "./application/customer/customer-service.js";
import { registerHealthRoutes } from "./interfaces/http/routes/health-routes.js";
import { registerCustomerRoutes } from "./interfaces/http/routes/customer-routes.js";
import { registerErrorHandler } from "./interfaces/http/error-handler.js";

export async function buildApp(config: AppConfig) {
  const logger = createLogger(config.logLevel);

  const app = Fastify({
    logger
  });

  await app.register(swagger, {
    openapi: {
      info: {
        title: config.serviceName,
        version: "1.0.0"
      }
    }
  });

  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  const repository = new InMemoryCustomerRepository([
    {
      id: "cust-001",
      email: "alice@example.com",
      firstName: "Alice",
      lastName: "Smith",
      active: true,
      createdAt: new Date()
    }
  ]);

  const customerService = new CustomerService(repository);

  registerErrorHandler(app);
  await registerHealthRoutes(app);
  await registerCustomerRoutes(app, customerService);

  return app;
}
