## `src/integrations/corporate-crm/crm.client.ts`

```ts
import axios, { AxiosError, type AxiosInstance } from "axios";
import { env } from "../../config/env.js";
import { IntegrationError } from "../../core/errors.js";
import { logger } from "../../plugins/logger.js";
import { crmCustomerSchema, crmErrorSchema } from "./crm.schemas.js";
import type { CrmCustomer } from "./crm.types.js";

export class CrmClient {
  private readonly http: AxiosInstance;

  public constructor() {
    this.http = axios.create({
      baseURL: env.CRM_BASE_URL,
      timeout: env.REQUEST_TIMEOUT_MS,
      headers: {
        "x-api-key": env.CRM_API_KEY,
        "content-type": "application/json"
      }
    });
  }

  public async getCustomerById(customerId: string, correlationId: string): Promise<CrmCustomer> {
    try {
      const response = await this.http.get(`/customers/${encodeURIComponent(customerId)}`, {
        headers: {
          "x-correlation-id": correlationId
        }
      });

      return crmCustomerSchema.parse(response.data);
    } catch (error: unknown) {
      if (error instanceof AxiosError) {
        const parsedError = crmErrorSchema.safeParse(error.response?.data);

        logger.error(
          {
            err: error,
            responseData: parsedError.success ? parsedError.data : error.response?.data,
            customerId,
            correlationId
          },
          "CRM request failed"
        );

        throw new IntegrationError("Failed to retrieve customer from CRM", {
          customerId,
          correlationId,
          upstreamStatus: error.response?.status
        });
      }

      logger.error({ err: error, customerId, correlationId }, "Unexpected CRM client error");
      throw new IntegrationError("Unexpected CRM integration failure", { customerId, correlationId });
    }
  }
}
```

