# 10. Fastify app bootstrap

## `src/app.ts`

```ts
import Fastify, { type FastifyInstance } from "fastify";
import { logger } from "./plugins/logger.js";
import { attachRequestContext } from "./plugins/request-context.js";
import { healthRoutes } from "./routes/health.routes.js";
import { customerRoutes } from "./routes/customer.routes.js";
import { AppError, InternalServerError } from "./core/errors.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    loggerInstance: logger,
    disableRequestLogging: false
  });

  app.addHook("onRequest", attachRequestContext);

  app.addHook("onSend", async (request, reply, payload) => {
    reply.header("x-correlation-id", request.correlationId);
    return payload;
  });

  app.setErrorHandler((error, request, reply) => {
    const appError = error instanceof AppError ? error : new InternalServerError("Unexpected error");

    request.log.error(
      {
        err: error,
        correlationId: request.correlationId
      },
      "Request failed"
    );

    reply.status(appError.statusCode).send({
      code: appError.code,
      message: appError.message,
      correlationId: request.correlationId
    });
  });

  app.register(healthRoutes, { prefix: "/api/v1" });
  app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
```

