// src/domain/access-request/access-request.entity.ts
import { InvalidJustificationError } from '../../common/errors/domain.errors';
import { AccessRequestProps, AccessRequestStatus } from './access-request.types';

export class AccessRequest {
  private constructor(private readonly props: AccessRequestProps) {}

  static create(props: Omit<AccessRequestProps, 'status' | 'createdAt'>): AccessRequest {
    if (props.justification.trim().length < 10) {
      throw new InvalidJustificationError();
    }

    return new AccessRequest({
      ...props,
      status: AccessRequestStatus.PENDING,
      createdAt: new Date(),
    });
  }

  toPrimitives(): AccessRequestProps {
    return { ...this.props };
  }
}
