// src/infrastructure/hr/corporate-hr.adapter.ts
import { Injectable, Logger } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { HrClient, EmployeeRecord } from './hr.client';

@Injectable()
export class CorporateHrAdapter implements HrClient {
  private readonly logger = new Logger(CorporateHrAdapter.name);
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: process.env.HR_API_BASE_URL,
      timeout: 5000,
      headers: {
        'X-Corporate-System': 'enterprise-access-service',
      },
    });
  }

  async getEmployee(employeeId: string): Promise<EmployeeRecord | null> {
    try {
      const response = await this.http.get(`/employees/${employeeId}`);
      const data = response.data;

      return {
        employeeId: data.employeeId,
        isActive: data.status === 'ACTIVE',
        department: data.department,
      };
    } catch (error: any) {
      if (error.response?.status === 404) {
        return null;
      }
      this.logger.error(`Failed to fetch employee ${employeeId}`, error.stack);
      throw error;
    }
  }
}
```

