## 4.9 Use case

```ts
// src/application/access-request/create-access-request.use-case.ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { AccessRequest } from '../../domain/access-request/access-request.entity';
import {
  ACCESS_REQUEST_REPOSITORY,
  AccessRequestRepository,
} from '../../domain/access-request/access-request.repository';
import { CreateAccessRequestDto } from './dto/create-access-request.dto';
import { HR_CLIENT, HrClient } from '../../infrastructure/hr/hr.client';
import {
  EVENT_PUBLISHER,
  EventPublisher,
} from '../../infrastructure/messaging/event.publisher';
import { AccessRequestResponse } from './dto/access-request.response';

@Injectable()
export class CreateAccessRequestUseCase {
  constructor(
    @Inject(ACCESS_REQUEST_REPOSITORY)
    private readonly repository: AccessRequestRepository,
    @Inject(HR_CLIENT)
    private readonly hrClient: HrClient,
    @Inject(EVENT_PUBLISHER)
    private readonly eventPublisher: EventPublisher,
  ) {}

  async execute(dto: CreateAccessRequestDto): Promise<AccessRequestResponse> {
    const employee = await this.hrClient.getEmployee(dto.employeeId);

    if (!employee || !employee.isActive) {
      throw new Error('Employee not found or inactive');
    }

    const accessRequest = AccessRequest.create({
      id: randomUUID(),
      employeeId: dto.employeeId,
      resourceCode: dto.resourceCode,
      justification: dto.justification,
    });

    await this.repository.save(accessRequest);

    const primitives = accessRequest.toPrimitives();

    await this.eventPublisher.publish({
      eventType: 'access-request.created',
      occurredAt: new Date().toISOString(),
      payload: {
        id: primitives.id,
        employeeId: primitives.employeeId,
        resourceCode: primitives.resourceCode,
        status: primitives.status,
      },
    });

    return {
      id: primitives.id,
      employeeId: primitives.employeeId,
      resourceCode: primitives.resourceCode,
      justification: primitives.justification,
      status: primitives.status,
      createdAt: primitives.createdAt.toISOString(),
    };
  }
}
