## 3.5 Authentication guard for corporate identity provider

This is a simple JWT verification placeholder. In a real enterprise environment, this should validate:
- issuer
- audience
- signature using JWKS or public key rotation
- scopes/roles
- tenant claims if applicable

### `src/common/auth/auth.guard.ts`

```ts
import {
  CanActivate,
  ExecutionContext,
  Injectable
} from '@nestjs/common';
import * as jwt from 'jsonwebtoken';
import { Request } from 'express';
import { AppConfigService } from '../config/config.service';
import { AppError } from '../errors/app-error';

export interface AuthenticatedUser {
  sub: string;
  email?: string;
  roles: string[];
}

export interface AuthenticatedRequest extends Request {
  user?: AuthenticatedUser;
}

@Injectable()
export class AuthGuard implements CanActivate {
  constructor(private readonly config: AppConfigService) {}

  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const authHeader = request.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      throw new AppError('UNAUTHORIZED', 'Missing bearer token');
    }

    const token = authHeader.slice('Bearer '.length);

    try {
      const payload = jwt.verify(token, this.config.get('JWT_PUBLIC_KEY'), {
        algorithms: ['RS256'],
        issuer: this.config.get('JWT_ISSUER'),
        audience: this.config.get('JWT_AUDIENCE')
      }) as jwt.JwtPayload;

      request.user = {
        sub: String(payload.sub),
        email: payload.email ? String(payload.email) : undefined,
        roles: Array.isArray(payload.roles) ? payload.roles.map(String) : []
      };

      return true;
    } catch {
      throw new AppError('UNAUTHORIZED', 'Invalid token');
    }
  }
}
```

