## 3.8 Application service

### `src/modules/customers/application/customers.service.ts`

```ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { AppError } from '../../../common/errors/app-error';
import { Customer } from '../domain/customer';
import {
  CUSTOMER_REPOSITORY,
  CustomerRepository
} from '../domain/customer.repository';
import { CrmClient } from '../infrastructure/crm.client';
import { CustomerEventPublisher } from '../infrastructure/event.publisher';

@Injectable()
export class CustomersService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepository,
    private readonly crmClient: CrmClient,
    private readonly eventPublisher: CustomerEventPublisher
  ) {}

  async createCustomer(input: {
    name: string;
    email: string;
  }): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new AppError('CONFLICT', 'Customer with this email already exists');
    }

    const crmRecord = await this.crmClient.createCustomer({
      name: input.name,
      email: input.email
    });

    const customer = new Customer({
      id: randomUUID(),
      externalCrmId: crmRecord.id,
      name: input.name,
      email: input.email,
      createdAt: new Date()
    });

    const saved = await this.customerRepository.create(customer);

    await this.eventPublisher.publishCustomerCreated({
      customerId: saved.id,
      email: saved.email
    });

    return saved;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new AppError('NOT_FOUND', 'Customer not found', { id });
    }
    return customer;
  }
}
```

