    if (!customer) {
      throw new NotFoundError(`Customer not found: ${id}`);
    }

    const directoryRecord = await this.corporateDirectoryClient.lookupByEmail(customer.email);

    return {
      id: customer.id,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      active: customer.active && directoryRecord !== null
    };
  }
}
```

## `src/modules/customer/customer.controller.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import { ValidationError } from "../../core/errors.js";
import { getCustomerParamsSchema } from "./customer.schemas.js";
import type { CustomerService } from "./customer.service.js";

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get(
    "/customers/:id",
    {
      schema: {
        tags: ["customers"],
        params: {
          type: "object",
          required: ["id"],
          properties: {
            id: { type: "string", minLength: 1 }
          }
        },
        response: {
          200: {
            type: "object",
            required: ["id", "email", "firstName", "lastName", "active"],
            properties: {
              id: { type: "string" },
              email: { type: "string", format: "email" },
              firstName: { type: "string" },
              lastName: { type: "string" },
              active: { type: "boolean" }
            }
          }
        }
      }
    },
    async (request: GetCustomerRequest, reply: FastifyReply) => {
      try {
        const params = getCustomerParamsSchema.parse(request.params);
        const customer = await customerService.getCustomerById(params.id);
        return reply.status(200).send(customer);
      } catch (error: unknown) {
        if (error instanceof ZodError) {
          throw new ValidationError("Invalid request parameters", error.flatten());
        }
        throw error;
      }
    }
  );
}
```

