# 7. Request context and error handling plugins

## `src/plugins/request-context.ts`

```ts
import fp from "fastify-plugin";
import { randomUUID } from "node:crypto";
import type { FastifyRequest } from "fastify";
import { asCorrelationId, type CorrelationId } from "../core/types.js";

declare module "fastify" {
  interface FastifyRequest {
    correlationId: CorrelationId;
  }
}

export default fp(async function requestContextPlugin(app) {
  app.addHook("onRequest", async (request: FastifyRequest) => {
    const headerValue = request.headers["x-correlation-id"];
    const correlationId =
      typeof headerValue === "string" && headerValue.length > 0
        ? headerValue
        : randomUUID();

    request.correlationId = asCorrelationId(correlationId);
  });
});
```

## `src/plugins/error-handler.ts`

```ts
import fp from "fastify-plugin";
import type { FastifyError, FastifyReply, FastifyRequest } from "fastify";
import { AppError, InternalServerError } from "../core/errors.js";

export default fp(async function errorHandlerPlugin(app) {
  app.setErrorHandler(
    (error: FastifyError | Error, request: FastifyRequest, reply: FastifyReply) => {
      const appError =
        error instanceof AppError
          ? error
          : new InternalServerError("An unexpected error occurred");

      request.log.error(
        {
          err: error,
          correlationId: request.correlationId,
          code: appError.code
        },
        appError.message
      );

      void reply.status(appError.statusCode).send({
        error: {
          code: appError.code,
          message: appError.message,
          correlationId: request.correlationId
        }
      });
    }
  );
});
```

