import { randomUUID } from "node:crypto";
import type { Employee, CreateEmployeeRequest } from "../domain/employee.js";
import { NotFoundError } from "../domain/errors.js";
import type { EmployeeRepository } from "../infrastructure/persistence/employee-repository.js";
import type { CorporateHrClient } from "../infrastructure/corporate/hr-client.js";

export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly hrClient: CorporateHrClient
  ) {}

  async getEmployeeById(id: string): Promise<Employee> {
    const employee = await this.repository.findById(id);
    if (!employee) {
      throw new NotFoundError("Employee", id);
    }
    return employee;
  }

  async createEmployee(input: CreateEmployeeRequest): Promise<Employee> {
    const employee: Employee = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      department: input.department,
      active: true
    };

    const created = await this.repository.create(employee);
    await this.hrClient.notifyEmployeeCreated({
      id: created.id,
      email: created.email,
      department: created.department
    });

    return created;
  }
}
