## `src/app/server.ts`

```ts
import Fastify, { type FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import { loadConfig } from "./plugins/config.js";
import { EmployeeService } from "../application/employee-service.js";
import { InMemoryEmployeeRepository } from "../infrastructure/persistence/employee-repository.js";
import { MockCorporateHrClient } from "../infrastructure/corporate/hr-client.js";
import { registerHealthRoutes } from "./routes/health.js";
import { registerEmployeeRoutes } from "./routes/employees.js";
import { DomainError } from "../domain/errors.js";

export function buildServer(): FastifyInstance {
  const config = loadConfig(process.env);

  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL
    }
  });

  void app.register(sensible);

  const employeeRepository = new InMemoryEmployeeRepository();
  const hrClient = new MockCorporateHrClient();
  const employeeService = new EmployeeService(employeeRepository, hrClient);

  app.decorate("config", config);
  app.decorate("services", {
    employeeService
  });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "request failed");

    if (error instanceof DomainError) {
      const statusCode = error.code === "NOT_FOUND" ? 404 : 400;
      return reply.status(statusCode).send({
        error: error.name,
        code: error.code,
        message: error.message
      });
    }

    return reply.status(500).send({
      error: "InternalServerError",
      code: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  void app.register(registerHealthRoutes, { prefix: "/health" });
  void app.register(registerEmployeeRoutes, { prefix: "/employees" });

  return app;
}
```

