## `src/domain/customer/customer.service.ts`

```ts
import { ConflictError, NotFoundError } from "../shared/errors.js";
import type { AuditPublisher } from "../../infrastructure/messaging/audit.publisher.js";
import type { CustomerRepository } from "./customer.repository.js";
import type { CreateCustomerInput, UpdateCustomerInput } from "./customer.schemas.js";
import { Customer } from "./customer.entity.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly auditPublisher: AuditPublisher
  ) {}

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer not found: ${id}`);
    }
    return customer;
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new ConflictError(`Customer already exists for email: ${input.email}`);
    }

    const customer = await this.customerRepository.create(input);

    await this.auditPublisher.publish({
      eventType: "CUSTOMER_CREATED",
      entityId: customer.id,
      payload: {
        email: customer.email
      }
    });

    return customer;
  }

  async updateCustomer(id: string, input: UpdateCustomerInput): Promise<Customer> {
    await this.getCustomer(id);
    const updated = await this.customerRepository.update(id, input);

    await this.auditPublisher.publish({
      eventType: "CUSTOMER_UPDATED",
      entityId: updated.id,
      payload: input
    });

    return updated;
  }
}
```

