import type { CustomerRepository } from "../../domain/customer/customer.repository.js";
import { Customer } from "../../domain/customer/customer.entity.js";
import type { CreateCustomerInput, UpdateCustomerInput } from "../../domain/customer/customer.schemas.js";
import { prisma } from "./prisma.js";

export class PrismaCustomerRepository implements CustomerRepository {
  async findById(id: string): Promise<Customer | null> {
    const record = await prisma.customer.findUnique({ where: { id } });
    return record ? this.toDomain(record) : null;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const record = await prisma.customer.findUnique({ where: { email } });
    return record ? this.toDomain(record) : null;
  }

  async create(input: CreateCustomerInput): Promise<Customer> {
    const record = await prisma.customer.create({
      data: {
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName
      }
    });

    return this.toDomain(record);
  }

  async update(id: string, input: UpdateCustomerInput): Promise<Customer> {
    const record = await prisma.customer.update({
      where: { id },
      data: input
    });

    return this.toDomain(record);
  }

  private toDomain(record: {
    id: string;
    email: string;
    firstName: string;
    lastName: string;
    isActive: boolean;
    createdAt: Date;
  }): Customer {
    return new Customer({
      id: record.id,
      email: record.email,
      firstName: record.firstName,
      lastName: record.lastName,
      isActive: record.isActive,
      createdAt: record.createdAt.toISOString()
    });
  }
}
