import { config } from "../../config/index.js";

export interface CorporateDirectoryRecord {
  employeeId: string;
  email: string;
  department: string;
  status: "ACTIVE" | "INACTIVE";
}

export interface CorporateDirectoryClient {
  getByEmail(email: string): Promise<CorporateDirectoryRecord | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  async getByEmail(email: string): Promise<CorporateDirectoryRecord | null> {
    const response = await fetch(
      `${config.CORPORATE_DIRECTORY_BASE_URL}/directory/by-email/${encodeURIComponent(email)}`,
      {
        method: "GET",
        headers: {
          "x-api-key": config.CORPORATE_DIRECTORY_API_KEY,
          "content-type": "application/json"
        }
      }
    );

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory request failed with status ${response.status}`);
    }

    const data = (await response.json()) as CorporateDirectoryRecord;
    return data;
  }
}
