import type { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { CustomerService } from "../domain/customer/customer.service.js";
import {
  createCustomerInputSchema,
  customerSchema,
  updateCustomerInputSchema
} from "../domain/customer/customer.schemas.js";
import { PrismaCustomerRepository } from "../infrastructure/db/customer.prisma.repository.js";
import { ConsoleAuditPublisher } from "../infrastructure/messaging/audit.publisher.js";

const paramsSchema = z.object({
  id: z.string().uuid()
});

const customerRoutes: FastifyPluginAsync = async (app) => {
  const service = new CustomerService(
    new PrismaCustomerRepository(),
    new ConsoleAuditPublisher()
  );

  app.get("/customers/:id", async (request, reply) => {
    const params = paramsSchema.parse(request.params);
    const customer = await service.getCustomer(params.id);
    const response = customerSchema.parse(customer);
    return reply.status(200).send(response);
  });

  app.post("/customers", async (request, reply) => {
    const body = createCustomerInputSchema.parse(request.body);
    const customer = await service.createCustomer(body);
    const response = customerSchema.parse(customer);
    return reply.status(201).send(response);
  });

  app.patch("/customers/:id", async (request, reply) => {
    const params = paramsSchema.parse(request.params);
    const body = updateCustomerInputSchema.parse(request.body);
    const customer = await service.updateCustomer(params.id, body);
    const response = customerSchema.parse(customer);
    return reply.status(200).send(response);
  });
};

export default customerRoutes;
```

