## `src/domain/customer/customer.service.ts`

```ts
import { AppError, ErrorCode } from "../../core/errors.js";
import { err, ok, type Result } from "../../core/result.js";
import type { CustomerId } from "../../core/types.js";
import type { CorporateEventPublisher } from "../../infrastructure/events/corporate-event-publisher.js";
import type { CustomerRepository } from "./customer.repository.js";
import type { Customer, CreateCustomerInput } from "./customer.types.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly eventPublisher: CorporateEventPublisher
  ) {}

  async getCustomerById(customerId: CustomerId): Promise<Result<Customer, AppError>> {
    const customer = await this.repository.findById(customerId);

    if (!customer) {
      return err(
        new AppError({
          message: `Customer not found: ${customerId}`,
          code: ErrorCode.NOT_FOUND,
          statusCode: 404
        })
      );
    }

    return ok(customer);
  }

  async createCustomer(input: CreateCustomerInput): Promise<Result<Customer, AppError>> {
    const existing = await this.repository.findByExternalRef(input.externalRef);

    if (existing) {
      return err(
        new AppError({
          message: `Customer with externalRef already exists: ${input.externalRef}`,
          code: ErrorCode.CONFLICT,
          statusCode: 409
        })
      );
    }

    const created = await this.repository.create(input);

    await this.eventPublisher.publishCustomerCreated({
      customerId: created.id,
      externalRef: created.externalRef,
      occurredAt: created.createdAt
    });

    return ok(created);
  }
}
```

