# 9. Repository implementation

For initial implementation, I’ll use in-memory storage. In enterprise production, this would be replaced with PostgreSQL, Oracle, SQL Server, etc.

## `src/infrastructure/db/in-memory-customer.repository.ts`

```ts
import type { CustomerId } from "../../core/types.js";
import type { CustomerRepository } from "../../domain/customer/customer.repository.js";
import type { Customer, CreateCustomerInput } from "../../domain/customer/customer.types.js";

function toCustomerId(value: string): CustomerId {
  return value as CustomerId;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly byId = new Map<CustomerId, Customer>();
  private readonly byExternalRef = new Map<string, Customer>();

  async findById(customerId: CustomerId): Promise<Customer | null> {
    return this.byId.get(customerId) ?? null;
  }

  async findByExternalRef(externalRef: string): Promise<Customer | null> {
    return this.byExternalRef.get(externalRef) ?? null;
  }

  async create(input: CreateCustomerInput): Promise<Customer> {
    const customer: Customer = {
      id: toCustomerId(`cust_${crypto.randomUUID()}`),
      externalRef: input.externalRef,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date().toISOString()
    };

    this.byId.set(customer.id, customer);
    this.byExternalRef.set(customer.externalRef, customer);

    return customer;
  }
}
```

