# 10. Request context / correlation ID

## `src/infrastructure/http/middleware/request-context.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import type { CorrelationId } from "../../../core/types.js";

function toCorrelationId(value: string): CorrelationId {
  return value as CorrelationId;
}

declare module "fastify" {
  interface FastifyRequest {
    correlationId: CorrelationId;
    principal?: {
      readonly subject: string;
      readonly roles: readonly string[];
      readonly token: string;
    };
  }
}

export async function requestContextHook(request: FastifyRequest, _reply: FastifyReply) {
  const headerValue = request.headers["x-correlation-id"];
  const correlationId =
    typeof headerValue === "string" && headerValue.length > 0
      ? headerValue
      : crypto.randomUUID();

  request.correlationId = toCorrelationId(correlationId);
}
```

