```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { AppError, ErrorCode } from "../../../core/errors.js";
import type { CustomerId } from "../../../core/types.js";
import { createCustomerSchema } from "../../../domain/customer/customer.types.js";
import type { CustomerService } from "../../../domain/customer/customer.service.js";
import type { CorporateAuthClient } from "../../auth/corporate-auth-client.js";

const paramsSchema = z.object({
  customerId: z.string().min(1)
});

function toCustomerId(value: string): CustomerId {
  return value as CustomerId;
}

function requireRole(request: FastifyRequest, role: string): void {
  const roles = request.principal?.roles ?? [];
  if (!roles.includes(role)) {
    throw new AppError({
      message: `Missing required role: ${role}`,
      code: ErrorCode.FORBIDDEN,
      statusCode: 403
    });
  }
}

export async function registerCustomerRoutes(
  app: FastifyInstance,
  deps: {
    customerService: CustomerService;
    authClient: CorporateAuthClient;
  }
): Promise<void> {
  app.addHook("preHandler", async (request) => {
    request.principal = await deps.authClient.authenticate(request.headers.authorization);
  });

  app.get(
    "/v1/customers/:customerId",
    async (request: FastifyRequest, reply: FastifyReply) => {
      requireRole(request, "customer.read");

      const parsedParams = paramsSchema.safeParse(request.params);
      if (!parsedParams.success) {
        throw new AppError({
          message: "Invalid request params",
          code: ErrorCode.VALIDATION_ERROR,
          statusCode: 400,
          details: parsedParams.error.flatten()
        });
      }

      const result = await deps.customerService.getCustomerById(
        toCustomerId(parsedParams.data.customerId)
      );

      if (!result.ok) {
        throw result.error;
      }

      return reply.code(200).send(result.value);
    }
  );

  app.post(
    "/v1/customers",
    async (request: FastifyRequest, reply: FastifyReply) => {
      requireRole(request, "customer.write");

      const parsedBody = createCustomerSchema.safeParse(request.body);
      if (!parsedBody.success) {
        throw new AppError({
          message: "Invalid request body",
          code: ErrorCode.VALIDATION_ERROR,
          statusCode: 400,
          details: parsedBody.error.flatten()
        });
      }

      const result = await deps.customerService.createCustomer(parsedBody.data);

      if (!result.ok) {
        throw result.error;
      }

      return reply.code(201).send(result.value);
    }
  );
}
```

