# 12. App composition

## `src/app.ts`

```ts
import Fastify from "fastify";
import { loadConfig } from "./config/env.js";
import { AppError, ErrorCode } from "./core/errors.js";
import { createLogger } from "./core/logger.js";
import { CustomerService } from "./domain/customer/customer.service.js";
import { CorporateAuthClient } from "./infrastructure/auth/corporate-auth-client.js";
import { InMemoryCustomerRepository } from "./infrastructure/db/in-memory-customer.repository.js";
import { CorporateEventPublisher } from "./infrastructure/events/corporate-event-publisher.js";
import { requestContextHook } from "./infrastructure/http/middleware/request-context.js";
import { registerCustomerRoutes } from "./infrastructure/http/routes/customer.routes.js";
import { registerHealthRoutes } from "./infrastructure/http/routes/health.routes.js";

export function buildApp() {
  const config = loadConfig(process.env);
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  const customerRepository = new InMemoryCustomerRepository();
  const eventPublisher = new CorporateEventPublisher();
  const authClient = new CorporateAuthClient();
  const customerService = new CustomerService(customerRepository, eventPublisher);

  app.addHook("onRequest", requestContextHook);

  app.addHook("onRequest", async (request) => {
    request.log = request.log.child({
      correlationId: request.correlationId
    });
  });

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      request.log.warn(
        {
          code: error.code,
          details: error.details
        },
        error.message
      );

      return reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message,
          correlationId: request.correlationId
        }
      });
    }

    request.log.error({ err: error }, "Unhandled error");

    return reply.status(500).send({
      error: {
        code: ErrorCode.INTERNAL_ERROR,
        message: "Internal server error",
        correlationId: request.correlationId
      }
    });
  });

  void registerHealthRoutes(app);
  void registerCustomerRoutes(app, {
    customerService,
    authClient
  });

  return { app, config };
}
```

