# 10. Application service

## `src/application/customer/customer.service.ts`

```ts
import {
  CustomerAlreadyExistsError,
  CustomerNotFoundError
} from "../../domain/customer/customer.errors.js";
import type { Customer, CreateCustomerRequest } from "../../domain/customer/customer.types.js";
import type {
  CorporateDirectoryPort,
  CustomerRepositoryPort,
  ErpPort
} from "./customer.ports.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepositoryPort,
    private readonly corporateDirectory: CorporateDirectoryPort,
    private readonly erp: ErpPort
  ) {}

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const identityExists = await this.corporateDirectory.validateExternalIdentity(input.externalId);
    if (!identityExists) {
      throw new Error(`External identity not found: ${input.externalId}`);
    }

    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new CustomerAlreadyExistsError(input.email);
    }

    const created = await this.customerRepository.create(input);

    await this.erp.registerCustomer(created);

    return created;
  }

  async getCustomerById(customerId: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(customerId);
    if (!customer) {
      throw new CustomerNotFoundError(customerId);
    }
    return customer;
  }
}
```

