import type { CustomerRepositoryPort } from "../../application/customer/customer.ports.js";
import type { CreateCustomerRequest, Customer } from "../../domain/customer/customer.types.js";
import { prisma } from "./prisma.js";

const toDomainCustomer = (record: {
  id: string;
  externalId: string;
  email: string;
  firstName: string;
  lastName: string;
  isActive: boolean;
  createdAt: Date;
}): Customer => ({
  id: record.id,
  externalId: record.externalId,
  email: record.email,
  firstName: record.firstName,
  lastName: record.lastName,
  isActive: record.isActive,
  createdAt: record.createdAt.toISOString()
});

export class PrismaCustomerRepository implements CustomerRepositoryPort {
  async findByEmail(email: string): Promise<Customer | null> {
    const record = await prisma.customer.findUnique({ where: { email } });
    return record ? toDomainCustomer(record) : null;
  }

  async findById(id: string): Promise<Customer | null> {
    const record = await prisma.customer.findUnique({ where: { id } });
    return record ? toDomainCustomer(record) : null;
  }

  async create(input: CreateCustomerRequest): Promise<Customer> {
    const record = await prisma.customer.create({
      data: {
        externalId: input.externalId,
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName
      }
    });

    return toDomainCustomer(record);
  }
}
