# 13. Request context and auth hooks

## `src/infrastructure/http/request-context.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";

export interface RequestContext {
  correlationId: string;
  userId?: string;
}

declare module "fastify" {
  interface FastifyRequest {
    context: RequestContext;
  }
}

export const attachRequestContext = async (
  request: FastifyRequest,
  _reply: FastifyReply
): Promise<void> => {
  const correlationIdHeader = request.headers["x-correlation-id"];
  const correlationId =
    typeof correlationIdHeader === "string" && correlationIdHeader.length > 0
      ? correlationIdHeader
      : crypto.randomUUID();

  request.context = {
    correlationId,
    userId: typeof request.headers["x-user-id"] === "string"
      ? request.headers["x-user-id"]
      : undefined
  };
};
```

## `src/infrastructure/http/auth.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";

export const requireAuth = async (
  request: FastifyRequest,
  reply: FastifyReply
): Promise<void> => {
  const authHeader = request.headers.authorization;
  if (!authHeader) {
    reply.code(401).send({
      error: "Unauthorized",
      message: "Missing Authorization header"
    });
  }
};
```

