```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../../application/customer/customer.service.js";
import {
  createCustomerRequestSchema,
  customerResponseSchema
} from "../../domain/customer/customer.schemas.js";
import { requireAuth } from "../../infrastructure/http/auth.js";

export async function customerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.post(
    "/customers",
    {
      preHandler: [requireAuth]
    },
    async (request, reply) => {
      const body = createCustomerRequestSchema.parse(request.body);
      const customer = await deps.customerService.createCustomer(body);

      const response = customerResponseSchema.parse(customer);
      reply.status(201).send(response);
    }
  );

  app.get(
    "/customers/:id",
    {
      preHandler: [requireAuth]
    },
    async (request, reply) => {
      const paramsSchema = z.object({ id: z.string().uuid() });
      const params = paramsSchema.parse(request.params);

      const customer = await deps.customerService.getCustomerById(params.id);
      const response = customerResponseSchema.parse(customer);

      reply.status(200).send(response);
    }
  );
}
```

