import Fastify from "fastify";
import sensible from "@fastify/sensible";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { logger } from "../config/logger.js";
import { env } from "../config/env.js";
import { CustomerService } from "../application/customer/customer.service.js";
import { PrismaCustomerRepository } from "../infrastructure/db/customer.repository.js";
import { CorporateDirectoryClient } from "../infrastructure/integrations/corporate-directory.client.js";
import { ErpClient } from "../infrastructure/integrations/erp.client.js";
import { attachRequestContext } from "../infrastructure/http/request-context.js";
import { registerErrorHandler } from "../infrastructure/http/error-handler.js";
import { healthRoutes } from "./routes/health.routes.js";
import { customerRoutes } from "./routes/customer.routes.js";

export const buildApp = () => {
  const app = Fastify({
    loggerInstance: logger
  });

  const customerRepository = new PrismaCustomerRepository();
  const corporateDirectory = new CorporateDirectoryClient(env.CORPORATE_DIRECTORY_BASE_URL);
  const erp = new ErpClient(env.ERP_BASE_URL, env.ERP_API_KEY);

  const customerService = new CustomerService(
    customerRepository,
    corporateDirectory,
    erp
  );

  app.addHook("onRequest", attachRequestContext);

  app.register(sensible);
  app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Microservice API",
        version: "0.1.0"
      }
    }
  });
  app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  registerErrorHandler(app);

  app.register(healthRoutes);
  app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  }, { prefix: "/api/v1" });

  return app;
};
```

