export class DomainError extends Error {
  public readonly code: string;

  public constructor(message: string, code: string) {
    super(message);
    this.name = "DomainError";
    this.code = code;
  }
}

export class EmployeeNotFoundError extends DomainError {
  public constructor(employeeId: string) {
    super(`Employee not found: ${employeeId}`, "EMPLOYEE_NOT_FOUND");
    this.name = "EmployeeNotFoundError";
  }
}

export class DuplicateEmployeeError extends DomainError {
  public constructor(email: string) {
    super(`Employee already exists for email: ${email}`, "DUPLICATE_EMPLOYEE");
    this.name = "DuplicateEmployeeError";
  }
}

export class ExternalSystemError extends DomainError {
  public constructor(system: string, message: string) {
    super(`External system error [${system}]: ${message}`, "EXTERNAL_SYSTEM_ERROR");
    this.name = "ExternalSystemError";
  }
}
