# 8. Application service

## `src/app/services/employee-service.ts`

```ts
import {
  CreateEmployeeInput,
  Employee,
  toEmployeeId
} from "../../domain/employee.js";
import {
  DuplicateEmployeeError,
  EmployeeNotFoundError,
  ExternalSystemError
} from "../../domain/errors.js";
import { EmployeeRepository } from "../ports/employee-repository.js";
import { CorporateIdentityClient } from "../ports/corporate-identity-client.js";
import { HrSystemClient } from "../ports/hr-system-client.js";

export class EmployeeService {
  public constructor(
    private readonly employeeRepository: EmployeeRepository,
    private readonly corporateIdentityClient: CorporateIdentityClient,
    private readonly hrSystemClient: HrSystemClient
  ) {}

  public async getEmployeeById(id: string): Promise<Employee> {
    const employee = await this.employeeRepository.findById(toEmployeeId(id));
    if (!employee) {
      throw new EmployeeNotFoundError(id);
    }
    return employee;
  }

  public async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const existing = await this.employeeRepository.findByEmail(input.email);
    if (existing) {
      throw new DuplicateEmployeeError(input.email);
    }

    const identityRecord = await this.corporateIdentityClient.lookupByEmail(input.email);
    if (!identityRecord || !identityRecord.exists || !identityRecord.accountEnabled) {
      throw new ExternalSystemError(
        "CorporateIdentity",
        `No active corporate identity found for ${input.email}`
      );
    }

    const department = await this.hrSystemClient.validateDepartment(
      input.departmentCode
    );
    if (!department || !department.valid) {
      throw new ExternalSystemError(
        "HRSystem",
        `Invalid department code ${input.departmentCode}`
      );
    }

    const employee: Employee = {
      id: toEmployeeId(crypto.randomUUID()),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      departmentCode: input.departmentCode,
      active: true
    };

    await this.employeeRepository.save(employee);
    return employee;
  }
}
```

Note: in Node.js, `crypto.randomUUID()` is available, but to be explicit in some setups you may import from `node:crypto`.

