## `src/infra/http/clients/corporate-identity-http-client.ts`

```ts
import { CorporateIdentityClient, CorporateIdentityRecord } from "../../../app/ports/corporate-identity-client.js";
import { Email } from "../../../domain/employee.js";

export class CorporateIdentityHttpClient implements CorporateIdentityClient {
  public constructor(private readonly baseUrl: string) {}

  public async lookupByEmail(email: Email): Promise<CorporateIdentityRecord | null> {
    const response = await fetch(
      `${this.baseUrl}/identities?email=${encodeURIComponent(email)}`
    );

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate identity lookup failed with status ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data === "object" &&
      data !== null &&
      "email" in data &&
      "exists" in data &&
      "accountEnabled" in data
    ) {
      const record = data as {
        email: string;
        exists: boolean;
        accountEnabled: boolean;
      };

      return {
        email: record.email as Email,
        exists: record.exists,
        accountEnabled: record.accountEnabled
      };
    }

    throw new Error("Invalid response from Corporate Identity service");
  }
}
```

