import { HrDepartmentRecord, HrSystemClient } from "../../../app/ports/hr-system-client.js";
import { DepartmentCode } from "../../../domain/employee.js";

export class HrSystemHttpClient implements HrSystemClient {
  public constructor(private readonly baseUrl: string) {}

  public async validateDepartment(
    code: DepartmentCode
  ): Promise<HrDepartmentRecord | null> {
    const response = await fetch(
      `${this.baseUrl}/departments/${encodeURIComponent(code)}`
    );

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`HR system lookup failed with status ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data === "object" &&
      data !== null &&
      "departmentCode" in data &&
      "valid" in data
    ) {
      const record = data as {
        departmentCode: string;
        valid: boolean;
      };

      return {
        departmentCode: record.departmentCode as DepartmentCode,
        valid: record.valid
      };
    }

    throw new Error("Invalid response from HR system");
