# 14. HTTP routes

## `src/infra/http/routes/employee-routes.ts`

```ts
import { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { EmployeeService } from "../../../app/services/employee-service.js";
import { DomainError } from "../../../domain/errors.js";
import { createEmployeeBodySchema } from "../schemas/employee-schemas.js";

const employeeParamsSchema = z.object({
  id: z.string().uuid()
});

export const registerEmployeeRoutes = (
  app: FastifyInstance,
  employeeService: EmployeeService
): void => {
  app.get(
    "/employees/:id",
    async (
      request: FastifyRequest<{ Params: { id: string } }>,
      reply: FastifyReply
    ) => {
      try {
        const params = employeeParamsSchema.parse(request.params);
        const employee = await employeeService.getEmployeeById(params.id);
        return reply.status(200).send(employee);
      } catch (error: unknown) {
        return handleRouteError(reply, error);
      }
    }
  );

  app.post(
    "/employees",
    async (
      request: FastifyRequest<{ Body: unknown }>,
      reply: FastifyReply
    ) => {
      try {
        const body = createEmployeeBodySchema.parse(request.body);
        const employee = await employeeService.createEmployee(body);
        return reply.status(201).send(employee);
      } catch (error: unknown) {
        return handleRouteError(reply, error);
      }
    }
  );
};

const handleRouteError = (reply: FastifyReply, error: unknown) => {
  if (error instanceof z.ZodError) {
    return reply.status(400).send({
      error: "VALIDATION_ERROR",
      details: error.flatten()
    });
  }

  if (error instanceof DomainError) {
    const statusCode =
      error.code === "EMPLOYEE_NOT_FOUND"
        ? 404
        : error.code === "DUPLICATE_EMPLOYEE"
          ? 409
          : 422;

    return reply.status(statusCode).send({
      error: error.code,
      message: error.message
    });
  }

  return reply.status(500).send({
    error: "INTERNAL_SERVER_ERROR"
  });
};
```

