# 15. Server wiring

## `src/infra/http/server.ts`

```ts
import Fastify, { FastifyInstance } from "fastify";
import { EmployeeService } from "../../app/services/employee-service.js";
import { InMemoryEmployeeRepository } from "../db/in-memory-employee-repository.js";
import { registerEmployeeRoutes } from "./routes/employee-routes.js";
import { registerHealthRoutes } from "./routes/health-routes.js";
import { CorporateIdentityHttpClient } from "./clients/corporate-identity-http-client.js";
import { HrSystemHttpClient } from "./clients/hr-system-http-client.js";
import { Env } from "../config/env.js";

export const buildServer = (env: Env): FastifyInstance => {
  const app = Fastify({
    logger: true
  });

  const employeeRepository = new InMemoryEmployeeRepository();
  const corporateIdentityClient = new CorporateIdentityHttpClient(
    env.CORPORATE_IDENTITY_BASE_URL
  );
  const hrSystemClient = new HrSystemHttpClient(env.HR_SYSTEM_BASE_URL);

  const employeeService = new EmployeeService(
    employeeRepository,
    corporateIdentityClient,
    hrSystemClient
  );

  registerHealthRoutes(app);
  registerEmployeeRoutes(app, employeeService);

  return app;
};
```

