# 10. Application use case

## `src/application/customer/create-customer.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Customer } from "../../domain/customer/customer.js";
import type { CustomerError } from "../../domain/customer/customer-errors.js";
import type { CustomerRepository } from "../../domain/customer/customer-repository.js";
import { err, ok, type Result } from "../../domain/shared/result.js";
import type { HrClient } from "../../infrastructure/corporate/hr-client.js";
import type { IdentityClient } from "../../infrastructure/corporate/identity-client.js";

export interface CreateCustomerCommand {
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
}

export class CreateCustomerUseCase {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly identityClient: IdentityClient,
    private readonly hrClient: HrClient
  ) {}

  public async execute(
    command: CreateCustomerCommand
  ): Promise<Result<Customer, CustomerError>> {
    const existing = await this.customerRepository.findByEmail(command.email);
    if (existing !== null) {
      return err({
        type: "CustomerAlreadyExists",
        email: command.email
      });
    }

    let identityUser;
    try {
      identityUser = await this.identityClient.findUserByEmail(command.email);
    } catch (cause) {
      return err({
        type: "CorporateIdentityLookupFailed",
        reason: cause instanceof Error ? cause.message : "Unknown identity error"
      });
    }

    if (identityUser === null || !identityUser.active) {
      return err({
        type: "CorporateIdentityLookupFailed",
        reason: "User not found or inactive in corporate identity system"
      });
    }

    let hrRecord;
    try {
      hrRecord = await this.hrClient.validateEmployee(identityUser.employeeId);
    } catch (cause) {
      return err({
        type: "CorporateHrValidationFailed",
        reason: cause instanceof Error ? cause.message : "Unknown HR error"
      });
    }

    if (hrRecord === null || !hrRecord.validForCustomerProvisioning) {
      return err({
        type: "CorporateHrValidationFailed",
        reason: "Employee is not eligible for provisioning"
      });
    }

    const customer: Customer = {
      id: randomUUID(),
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName,
      externalHrId: hrRecord.employeeId,
      createdAt: new Date()
    };

    const created = await this.customerRepository.create(customer);
    return ok(created);
  }
}
```

