## `src/infrastructure/db/customer-prisma-repository.ts`

```ts
import type { CustomerRepository } from "../../domain/customer/customer-repository.js";
import type { Customer } from "../../domain/customer/customer.js";
import { prisma } from "./prisma.js";

export class PrismaCustomerRepository implements CustomerRepository {
  public async findById(id: string): Promise<Customer | null> {
    const row = await prisma.customer.findUnique({ where: { id } });
    return row ? this.toDomain(row) : null;
  }

  public async findByEmail(email: string): Promise<Customer | null> {
    const row = await prisma.customer.findUnique({ where: { email } });
    return row ? this.toDomain(row) : null;
  }

  public async create(customer: Customer): Promise<Customer> {
    const row = await prisma.customer.create({
      data: {
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        externalHrId: customer.externalHrId,
        createdAt: customer.createdAt
      }
    });

    return this.toDomain(row);
  }

  private toDomain(row: {
    id: string;
    email: string;
    firstName: string;
    lastName: string;
    externalHrId: string | null;
    createdAt: Date;
  }): Customer {
    return {
      id: row.id,
      email: row.email,
      firstName: row.firstName,
      lastName: row.lastName,
      externalHrId: row.externalHrId ?? undefined,
      createdAt: row.createdAt
    };
  }
}
```

