## `src/interfaces/http/routes/customers.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { CreateCustomerUseCase } from "../../../application/customer/create-customer.js";
import { GetCustomerUseCase } from "../../../application/customer/get-customer.js";
import { PrismaCustomerRepository } from "../../../infrastructure/db/customer-prisma-repository.js";
import { StubHrClient } from "../../../infrastructure/corporate/hr-client-impl.js";
import { StubIdentityClient } from "../../../infrastructure/corporate/identity-client-impl.js";
import { createCustomerBodySchema } from "../schemas/customer-schemas.js";

type CreateCustomerRequest = FastifyRequest<{
  Body: {
    email: string;
    firstName: string;
    lastName: string;
  };
}>;

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

function mapCustomerErrorToHttp(error: { type: string }, reply: FastifyReply): FastifyReply {
  switch (error.type) {
    case "CustomerAlreadyExists":
      return reply.code(409).send(error);
    case "CustomerNotFound":
      return reply.code(404).send(error);
    case "CorporateIdentityLookupFailed":
    case "CorporateHrValidationFailed":
      return reply.code(502).send(error);
    default:
      return reply.code(500).send({ type: "UnknownError" });
  }
}

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const repository = new PrismaCustomerRepository();
  const identityClient = new StubIdentityClient();
  const hrClient = new StubHrClient();

  const createCustomerUseCase = new CreateCustomerUseCase(
    repository,
    identityClient,
    hrClient
  );
  const getCustomerUseCase = new GetCustomerUseCase(repository);

  app.post("/customers", async (request: CreateCustomerRequest, reply) => {
    const body = createCustomerBodySchema.parse(request.body);

    const result = await createCustomerUseCase.execute(body);

    if (!result.ok) {
      return mapCustomerErrorToHttp(result.error, reply);
    }

    return reply.code(201).send({
      id: result.value.id,
      email: result.value.email,
      firstName: result.value.firstName,
      lastName: result.value.lastName,
      externalHrId: result.value.externalHrId,
      createdAt: result.value.createdAt.toISOString()
    });
  });

  app.get("/customers/:id", async (request: GetCustomerRequest, reply) => {
    const result = await getCustomerUseCase.execute(request.params.id);

    if (!result.ok) {
      return mapCustomerErrorToHttp(result.error, reply);
    }

    return reply.code(200).send({
      id: result.value.id,
      email: result.value.email,
      firstName: result.value.firstName,
      lastName: result.value.lastName,
      externalHrId: result.value.externalHrId,
      createdAt: result.value.createdAt.toISOString()
    });
  });
}
```

