# 17. Fastify server setup

## `src/app/server.ts`

```ts
import Fastify, { type FastifyInstance } from "fastify";
import cors from "@fastify/cors";
import helmet from "@fastify/helmet";
import sensible from "@fastify/sensible";
import { healthRoutes } from "../interfaces/http/routes/health.js";
import { customerRoutes } from "../interfaces/http/routes/customers.js";
import type { Env } from "../infrastructure/config/env.js";

export function buildServer(env: Env): FastifyInstance {
  const app = Fastify({
    logger: {
      level: env.LOG_LEVEL
    },
    disableRequestLogging: false
  });

  app.register(sensible);
  app.register(helmet);
  app.register(cors, {
    origin: false
  });

  app.register(healthRoutes);
  app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
```

