## `src/domain/customer/customer.ts`

```ts
import { z } from "zod";
import { CustomerId, toCustomerId } from "../shared/brand.js";
import { ValidationError } from "../shared/errors.js";

export const CustomerStatusSchema = z.enum(["ACTIVE", "INACTIVE"]);
export type CustomerStatus = z.infer<typeof CustomerStatusSchema>;

export interface Customer {
  readonly id: CustomerId;
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
  readonly status: CustomerStatus;
  readonly createdAt: Date;
}

export interface CreateCustomerInput {
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
}

const createCustomerInputSchema = z.object({
  email: z.string().email(),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100)
});

export function validateCreateCustomerInput(input: CreateCustomerInput): CreateCustomerInput {
  const result = createCustomerInputSchema.safeParse(input);
  if (!result.success) {
    throw new ValidationError(result.error.message);
  }
  return result.data;
}

export function rehydrateCustomer(data: {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  status: CustomerStatus;
  createdAt: Date;
}): Customer {
  return {
    id: toCustomerId(data.id),
    email: data.email,
    firstName: data.firstName,
    lastName: data.lastName,
    status: data.status,
    createdAt: data.createdAt
  };
}
```

