import { PrismaClient } from "@prisma/client";
import { CustomerRepository } from "../../domain/customer/customer.repository.js";
import { Customer, CreateCustomerInput, rehydrateCustomer } from "../../domain/customer/customer.js";
import { CustomerId } from "../../domain/shared/brand.js";

export class PrismaCustomerRepository implements CustomerRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async findById(id: CustomerId): Promise<Customer | null> {
    const record = await this.prisma.customer.findUnique({
      where: { id }
    });

    if (!record) {
      return null;
    }

    return rehydrateCustomer({
      id: record.id,
      email: record.email,
      firstName: record.firstName,
      lastName: record.lastName,
      status: record.status === "ACTIVE" ? "ACTIVE" : "INACTIVE",
      createdAt: record.createdAt
    });
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const record = await this.prisma.customer.findUnique({
      where: { email }
    });

    if (!record) {
      return null;
    }

    return rehydrateCustomer({
      id: record.id,
      email: record.email,
      firstName: record.firstName,
      lastName: record.lastName,
      status: record.status === "ACTIVE" ? "ACTIVE" : "INACTIVE",
      createdAt: record.createdAt
    });
  }

  async create(input: CreateCustomerInput): Promise<Customer> {
    const record = await this.prisma.customer.create({
      data: {
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName,
        status: "ACTIVE"
      }
    });

    return rehydrateCustomer({
      id: record.id,
      email: record.email,
      firstName: record.firstName,
      lastName: record.lastName,
      status: record.status === "ACTIVE" ? "ACTIVE" : "INACTIVE",
      createdAt: record.createdAt
    });
  }
}
