## `src/application/customer/create-customer.ts`

Use case with repository + integrations.

```ts
import { CustomerRepository } from "../../domain/customer/customer.repository.js";
import { Customer, CreateCustomerInput, validateCreateCustomerInput } from "../../domain/customer/customer.js";
import { ValidationError } from "../../domain/shared/errors.js";
import { CorporateCrmClient } from "../../infrastructure/integrations/corporate-crm.client.js";
import { CorporateIdentityClient } from "../../infrastructure/integrations/corporate-identity.client.js";

export class CreateCustomerUseCase {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateCrmClient: CorporateCrmClient,
    private readonly corporateIdentityClient: CorporateIdentityClient
  ) {}

  async execute(input: CreateCustomerInput): Promise<Customer> {
    const validated = validateCreateCustomerInput(input);

    const existing = await this.customerRepository.findByEmail(validated.email);
    if (existing) {
      throw new ValidationError(`Customer already exists for email: ${validated.email}`);
    }

    await this.corporateIdentityClient.ensureIdentity({
      email: validated.email,
      firstName: validated.firstName,
      lastName: validated.lastName
    });

    const customer = await this.customerRepository.create(validated);

    await this.corporateCrmClient.registerCustomer({
      customerId: customer.id,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName
    });

    return customer;
  }
}
```

