## `src/interfaces/http/routes/customer.routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CreateCustomerUseCase } from "../../../application/customer/create-customer.js";
import { GetCustomerUseCase } from "../../../application/customer/get-customer.js";
import { toCustomerId } from "../../../domain/shared/brand.js";
import { DomainError, NotFoundError, ValidationError } from "../../../domain/shared/errors.js";
import { createCustomerBodySchema } from "../schemas/customer.schemas.js";

interface CustomerRoutesDeps {
  createCustomerUseCase: CreateCustomerUseCase;
  getCustomerUseCase: GetCustomerUseCase;
}

export async function customerRoutes(
  fastify: FastifyInstance,
  deps: CustomerRoutesDeps
): Promise<void> {
  fastify.post("/customers", async (request, reply) => {
    try {
      const body = createCustomerBodySchema.parse(request.body);
      const customer = await deps.createCustomerUseCase.execute(body);

      return reply.code(201).send({
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        status: customer.status,
        createdAt: customer.createdAt.toISOString()
      });
    } catch (error: unknown) {
      return handleHttpError(error, reply);
    }
  });

  fastify.get("/customers/:id", async (request, reply) => {
    try {
      const params = z.object({ id: z.string().min(1) }).parse(request.params);
      const customer = await deps.getCustomerUseCase.execute(toCustomerId(params.id));

      return reply.send({
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        status: customer.status,
        createdAt: customer.createdAt.toISOString()
      });
    } catch (error: unknown) {
      return handleHttpError(error, reply);
    }
  });
}

function handleHttpError(error: unknown, reply: FastifyInstance["reply"] extends never ? never : any) {
  if (error instanceof NotFoundError) {
    return reply.code(404).send({
      error: error.name,
      code: error.code,
      message: error.message
    });
  }

  if (error instanceof ValidationError || error instanceof z.ZodError) {
    return reply.code(400).send({
      error: "BadRequest",
      code: "VALIDATION_ERROR",
      message: error.message
    });
  }

  if (error instanceof DomainError) {
    return reply.code(422).send({
      error: error.name,
      code: error.code,
      message: error.message
    });
  }

  return reply.code(500).send({
    error: "InternalServerError",
    code: "INTERNAL_ERROR",
    message: "An unexpected error occurred"
  });
}
```

