```ts
import Fastify, { FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import { Env } from "../config/env.js";
import { createLogger } from "../infrastructure/logging/logger.js";
import { createPrismaClient } from "../infrastructure/db/prisma.js";
import { PrismaCustomerRepository } from "../infrastructure/db/customer-prisma.repository.js";
import { StubCorporateCrmClient } from "../infrastructure/integrations/corporate-crm.client.js";
import { StubCorporateIdentityClient } from "../infrastructure/integrations/corporate-identity.client.js";
import { CreateCustomerUseCase } from "../application/customer/create-customer.js";
import { GetCustomerUseCase } from "../application/customer/get-customer.js";
import { healthRoutes } from "../interfaces/http/routes/health.routes.js";
import { customerRoutes } from "../interfaces/http/routes/customer.routes.js";

export async function buildApp(env: Env): Promise<FastifyInstance> {
  const logger = createLogger(env);
  const prisma = createPrismaClient();

  const customerRepository = new PrismaCustomerRepository(prisma);
  const crmClient = new StubCorporateCrmClient();
  const identityClient = new StubCorporateIdentityClient();

  const createCustomerUseCase = new CreateCustomerUseCase(
    customerRepository,
    crmClient,
    identityClient
  );
  const getCustomerUseCase = new GetCustomerUseCase(customerRepository);

  const app = Fastify({
    logger
  });

  await app.register(sensible);

  await healthRoutes(app);
  await customerRoutes(app, {
    createCustomerUseCase,
    getCustomerUseCase
  });

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

