```ts
import { z } from "zod";
import { CorporateCrmClient } from "./corporate-crm.client.js";
import { HttpClient } from "./http-client.js";

const crmRegisterResponseSchema = z.object({
  success: z.boolean()
});

export class HttpCorporateCrmClient implements CorporateCrmClient {
  constructor(
    private readonly httpClient: HttpClient,
    private readonly baseUrl: string
  ) {}

  async registerCustomer(input: {
    readonly customerId: string;
    readonly email: string;
    readonly firstName: string;
    readonly lastName: string;
  }): Promise<void> {
    await this.httpClient.post(
      `${this.baseUrl}/customers/register`,
      input,
      crmRegisterResponseSchema
    );
  }
}
```

This pattern ensures external responses are validated, not trusted.

