class InMemoryCustomerRepository implements CustomerRepository {
  private readonly items = new Map<string, ReturnType<typeof rehydrateCustomer>>();

  async findById(id: string) {
    return this.items.get(id) ?? null;
  }

  async findByEmail(email: string) {
    for (const customer of this.items.values()) {
      if (customer.email === email) {
        return customer;
      }
    }
    return null;
  }

  async create(input: { email: string; firstName: string; lastName: string }) {
    const customer = rehydrateCustomer({
      id: "cust_1",
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      status: "ACTIVE",
      createdAt: new Date()
    });
    this.items.set(customer.id, customer);
    return customer;
  }
}

