# 8. Application layer

## `src/application/customer/create-customer.usecase.ts`

```ts
import { randomUUID } from 'node:crypto';
import type { CustomerRepository } from '../../domain/customer/customer.repository.js';
import {
  CreateCustomerInputSchema,
  type Customer,
  type CreateCustomerInput
} from '../../domain/customer/customer.js';
import { CustomerAlreadyExistsError } from '../../domain/customer/customer.errors.js';

export class CreateCustomerUseCase {
  constructor(private readonly customerRepository: CustomerRepository) {}

  async execute(input: CreateCustomerInput): Promise<Customer> {
    const validated = CreateCustomerInputSchema.parse(input);

    const existing = await this.customerRepository.findByEmail(validated.email);
    if (existing) {
      throw new CustomerAlreadyExistsError(validated.email);
    }

    const customer: Customer = {
      id: randomUUID() as Customer['id'],
      email: validated.email,
      firstName: validated.firstName,
      lastName: validated.lastName,
      createdAt: new Date().toISOString()
    };

    return this.customerRepository.create(customer);
  }
}
```

## `src/application/customer/get-customer.usecase.ts`

```ts
import type { CustomerRepository } from '../../domain/customer/customer.repository.js';
import { CustomerIdSchema, type Customer } from '../../domain/customer/customer.js';
import { CustomerNotFoundError } from '../../domain/customer/customer.errors.js';

export class GetCustomerUseCase {
  constructor(private readonly customerRepository: CustomerRepository) {}

  async execute(rawId: string): Promise<Customer> {
    const id = CustomerIdSchema.parse(rawId);
    const customer = await this.customerRepository.findById(id);

    if (!customer) {
      throw new CustomerNotFoundError(rawId);
    }

    return customer;
  }
}
