# 10. Corporate system integration client

This shows how to integrate with an existing corporate service through a typed abstraction.

## `src/infrastructure/http/corporate-directory.client.ts`

```ts
import { z } from 'zod';

const CorporateDirectoryUserSchema = z.object({
  employeeId: z.string(),
  email: z.string().email(),
  displayName: z.string(),
  active: z.boolean()
});

export type CorporateDirectoryUser = z.infer<typeof CorporateDirectoryUserSchema>;

export interface CorporateDirectoryClient {
  findUserByEmail(email: string): Promise<CorporateDirectoryUser | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  constructor(
    private readonly baseUrl: string,
    private readonly apiKeyHeader: string,
    private readonly apiKeyValue: string
  ) {}

  async findUserByEmail(email: string): Promise<CorporateDirectoryUser | null> {
    const url = new URL('/users', this.baseUrl);
    url.searchParams.set('email', email);

    const response = await fetch(url.toString(), {
      method: 'GET',
      headers: {
        [this.apiKeyHeader]: this.apiKeyValue,
        'content-type': 'application/json'
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory request failed with status ${response.status}`);
    }

    const json: unknown = await response.json();
    return CorporateDirectoryUserSchema.parse(json);
  }
}
```

