import { randomUUID } from 'node:crypto';

export function getOrCreateCorrelationId(input: string | string[] | undefined): string {
  if (typeof input === 'string' && input.trim().length > 0) {
    return input;
  }
  if (Array.isArray(input) && input.length > 0 && input[0]?.trim()) {
    return input[0];
  }
  return randomUUID();
}
