import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { CreateCustomerUseCase } from '../../application/customer/create-customer.usecase.js';
import { GetCustomerUseCase } from '../../application/customer/get-customer.usecase.js';
import { InMemoryCustomerRepository } from '../../infrastructure/db/in-memory-customer.repository.js';
import { authMiddleware } from '../../infrastructure/security/auth-middleware.js';

const CreateCustomerRequestSchema = z.object({
  email: z.string().email(),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100)
});

const GetCustomerParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const repository = new InMemoryCustomerRepository();
  const createCustomerUseCase = new CreateCustomerUseCase(repository);
  const getCustomerUseCase = new GetCustomerUseCase(repository);

  app.addHook('preHandler', authMiddleware);

  app.post('/customers', async (request, reply) => {
    const body = CreateCustomerRequestSchema.parse(request.body);
    const customer = await createCustomerUseCase.execute(body);
    reply.status(201).send(customer);
  });

  app.get('/customers/:id', async (request, reply) => {
    const params = GetCustomerParamsSchema.parse(request.params);
    const customer = await getCustomerUseCase.execute(params.id);
    reply.status(200).send(customer);
  });
}
```

