# 15. Fastify server setup

## `src/app/server.ts`

```ts
import Fastify from 'fastify';
import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { ZodError } from 'zod';
import { healthRoutes } from './routes/health.routes.js';
import { customerRoutes } from './routes/customer.routes.js';
import { logger } from '../infrastructure/logging/logger.js';
import { AppError } from '../shared/errors/app-error.js';
import { getOrCreateCorrelationId } from '../shared/utils/correlation-id.js';

export function buildServer(): FastifyInstance {
  const app = Fastify({
    logger
  });

  app.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    const correlationId = getOrCreateCorrelationId(request.headers['x-correlation-id']);
    reply.header('x-correlation-id', correlationId);
    request.log = request.log.child({ correlationId });
  });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, 'request failed');

    if (error instanceof ZodError) {
      reply.status(400).send({
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Request validation failed',
          details: error.flatten()
        }
      });
      return;
    }

    if (error instanceof AppError) {
      reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message,
          details: error.details
        }
      });
      return;
    }

    reply.status(500).send({
      error: {
        code: 'INTERNAL_SERVER_ERROR',
        message: 'An unexpected error occurred'
      }
    });
  });

  app.register(healthRoutes);
  app.register(customerRoutes, { prefix: '/api/v1' });

  return app;
}
```

