# 6. Application service

## `src/application/services/customerService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { CustomerRepository } from "../ports/customerRepository.js";
import type { CorporateDirectoryClient } from "../ports/corporateDirectoryClient.js";
import type { CreateCustomerRequest, Customer } from "../../domain/customer.js";
import { toCustomerId, toEmail } from "../../domain/common.js";
import type { DomainError } from "../../domain/errors.js";
import { err, ok, type Result } from "../../shared/result.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  public async createCustomer(
    request: CreateCustomerRequest
  ): Promise<Result<Customer, DomainError>> {
    const existing = await this.customerRepository.findByEmail(toEmail(request.email));
    if (existing !== null) {
      return err({
        type: "Conflict",
        message: `Customer with email ${request.email} already exists`
      });
    }

    const corporateRecord = await this.corporateDirectoryClient.lookupByEmail(request.email);
    if (corporateRecord === null || corporateRecord.status !== "ACTIVE") {
      return err({
        type: "ExternalDependencyError",
        system: "CorporateDirectory",
        message: "User not found or inactive in corporate directory"
      });
    }

    const customer: Customer = {
      id: toCustomerId(randomUUID()),
      email: toEmail(request.email),
      fullName: request.fullName,
      active: true
    };

    const created = await this.customerRepository.create(customer);
    return ok(created);
  }

  public async getCustomerById(id: string): Promise<Result<Customer, DomainError>> {
    const customer = await this.customerRepository.findById(toCustomerId(id));
    if (customer === null) {
      return err({
        type: "NotFound",
        entity: "Customer",
        id
      });
    }

    return ok(customer);
  }
}
```

