# 9. Infrastructure: PostgreSQL repository

## `src/infrastructure/db/customerRepositoryPg.ts`

```ts
import type { Pool } from "pg";
import type { CustomerRepository } from "../../application/ports/customerRepository.js";
import type { Customer } from "../../domain/customer.js";
import { toCustomerId, toEmail } from "../../domain/common.js";
import type { CustomerId, Email } from "../../domain/common.js";

type CustomerRow = {
  id: string;
  email: string;
  full_name: string;
  active: boolean;
};

export class CustomerRepositoryPg implements CustomerRepository {
  public constructor(private readonly pool: Pool) {}

  public async findById(id: CustomerId): Promise<Customer | null> {
    const result = await this.pool.query<CustomerRow>(
      `SELECT id, email, full_name, active FROM customers WHERE id = $1`,
      [id]
    );

    const row = result.rows[0];
    return row ? this.mapRow(row) : null;
  }

  public async findByEmail(email: Email): Promise<Customer | null> {
    const result = await this.pool.query<CustomerRow>(
      `SELECT id, email, full_name, active FROM customers WHERE email = $1`,
      [email]
    );

    const row = result.rows[0];
    return row ? this.mapRow(row) : null;
  }

  public async create(customer: Customer): Promise<Customer> {
    await this.pool.query(
      `INSERT INTO customers (id, email, full_name, active)
       VALUES ($1, $2, $3, $4)`,
      [customer.id, customer.email, customer.fullName, customer.active]
    );

    return customer;
  }

  private mapRow(row: CustomerRow): Customer {
    return {
      id: toCustomerId(row.id),
      email: toEmail(row.email),
      fullName: row.full_name,
      active: row.active
    };
  }
}
```

