# 10. Infrastructure: corporate integration client

## `src/infrastructure/integrations/corporateDirectoryHttpClient.ts`

```ts
import { request } from "undici";
import type {
  CorporateDirectoryClient,
  CorporateDirectoryRecord
} from "../../application/ports/corporateDirectoryClient.js";

type DirectoryApiResponse = {
  email: string;
  employeeId: string;
  status: "ACTIVE" | "INACTIVE";
};

export class CorporateDirectoryHttpClient implements CorporateDirectoryClient {
  public constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  public async lookupByEmail(email: string): Promise<CorporateDirectoryRecord | null> {
    const response = await request(`${this.baseUrl}/directory/users?email=${encodeURIComponent(email)}`, {
      method: "GET",
      headers: {
        "x-api-key": this.apiKey,
        accept: "application/json"
      }
    });

    if (response.statusCode === 404) {
      return null;
    }

    if (response.statusCode !== 200) {
      throw new Error(`Corporate directory returned status ${response.statusCode}`);
    }

    const body = (await response.body.json()) as DirectoryApiResponse;
    return {
      email: body.email,
      employeeId: body.employeeId,
      status: body.status
    };
  }
}
```

