## `src/app/routes/customerRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CreateCustomerRequestSchema } from "../../domain/customer.js";
import type { CustomerService } from "../../application/services/customerService.js";

const ParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(
  fastify: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  fastify.post("/customers", async (request, reply) => {
    if (!request.user?.roles.includes("customer:create")) {
      return reply.status(403).send({
        error: "Forbidden",
        message: "Missing required role"
      });
    }

    const parsed = CreateCustomerRequestSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        message: parsed.error.flatten()
      });
    }

    const result = await deps.customerService.createCustomer(parsed.data);

    if (!result.ok) {
      switch (result.error.type) {
        case "Conflict":
          return reply.status(409).send(result.error);
        case "ExternalDependencyError":
          return reply.status(424).send(result.error);
        default:
          return reply.status(400).send(result.error);
      }
    }

    return reply.status(201).send(result.value);
  });

  fastify.get("/customers/:id", async (request, reply) => {
    if (!request.user?.roles.includes("customer:read")) {
      return reply.status(403).send({
        error: "Forbidden",
        message: "Missing required role"
      });
    }

    const parsed = ParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        message: parsed.error.flatten()
      });
    }

    const result = await deps.customerService.getCustomerById(parsed.data.id);

    if (!result.ok) {
      switch (result.error.type) {
        case "NotFound":
          return reply.status(404).send(result.error);
        default:
          return reply.status(400).send(result.error);
      }
    }

    return reply.status(200).send(result.value);
  });
}
```

