## `src/infrastructure/http/fastify.ts`

```ts
import Fastify from "fastify";
import helmet from "@fastify/helmet";
import sensible from "@fastify/sensible";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import requestContextPlugin from "../../app/plugins/requestContext.js";
import authPlugin from "../../app/plugins/auth.js";
import errorHandlerPlugin from "../../app/plugins/errorHandler.js";
import { customerRoutes } from "../../app/routes/customerRoutes.js";
import type { CustomerService } from "../../application/services/customerService.js";
import type { Logger } from "pino";

export async function buildHttpServer(
  logger: Logger,
  deps: { customerService: CustomerService }
) {
  const app = Fastify({
    logger
  });

  await app.register(helmet);
  await app.register(sensible);
  await app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Microservice API",
        version: "1.0.0"
      }
    }
  });
  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  await app.register(requestContextPlugin);
  await app.register(authPlugin);
  await app.register(errorHandlerPlugin);

  app.get("/health", async () => ({ status: "ok" }));
  app.get("/ready", async () => ({ status: "ready" }));

  await customerRoutes(app, deps);

  return app;
}
```

