# 12. Application bootstrap

## `src/app/server.ts`

```ts
import { Pool } from "pg";
import { loadEnv } from "../infrastructure/config/env.js";
import { createLogger } from "../infrastructure/observability/logger.js";
import { CustomerRepositoryPg } from "../infrastructure/db/customerRepositoryPg.js";
import { CorporateDirectoryHttpClient } from "../infrastructure/integrations/corporateDirectoryHttpClient.js";
import { CustomerService } from "../application/services/customerService.js";
import { buildHttpServer } from "../infrastructure/http/fastify.js";

export async function createServer() {
  const env = loadEnv();
  const logger = createLogger(env);

  const pool = new Pool({
    connectionString: env.DATABASE_URL
  });

  const customerRepository = new CustomerRepositoryPg(pool);
  const corporateDirectoryClient = new CorporateDirectoryHttpClient(
    env.CORPORATE_DIRECTORY_BASE_URL,
    env.CORPORATE_DIRECTORY_API_KEY
  );

  const customerService = new CustomerService(
    customerRepository,
    corporateDirectoryClient
  );

  const app = await buildHttpServer(logger, { customerService });

  return { app, pool, logger, env };
}
```

