# 8. Application service

## `src/application/employee-service.ts`

```ts
import type { CreateEmployeeInput, Employee } from "../domain/employee.js";
import type { DomainError } from "../domain/errors.js";
import type {
  CorporateHrClient,
  EmployeeRepository,
  EventPublisher
} from "../domain/ports.js";
import { err, ok, type Result } from "../shared/result.js";

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

export class EmployeeService {
  public constructor(
    private readonly repository: EmployeeRepository,
    private readonly corporateHrClient: CorporateHrClient,
    private readonly eventPublisher: EventPublisher
  ) {}

  public async createEmployee(
    input: CreateEmployeeInput
  ): Promise<Result<Employee, DomainError>> {
    if (!isValidEmail(input.email)) {
      return err({
        type: "ValidationError",
        message: "Invalid email format"
      });
    }

    const existing = await this.repository.findByEmail(input.email);
    if (existing !== null) {
      return err({
        type: "Conflict",
        entity: "Employee",
        field: "email"
      });
    }

    if (input.managerId !== undefined) {
      try {
        const exists = await this.corporateHrClient.managerExists(input.managerId);
        if (!exists) {
          return err({
            type: "ValidationError",
            message: "Manager does not exist in Corporate HR"
          });
        }
      } catch {
        return err({
          type: "IntegrationError",
          system: "CorporateHR",
          message: "Failed to validate manager in Corporate HR"
        });
      }
    }

    const employee = await this.repository.create(input);

    try {
      await this.eventPublisher.publishEmployeeCreated(employee);
    } catch {
      return err({
        type: "IntegrationError",
        system: "EventBus",
        message: "Employee created but event publication failed"
      });
    }

    return ok(employee);
  }

  public async getEmployeeById(id: string): Promise<Result<Employee, DomainError>> {
    const employee = await this.repository.findById(id);

    if (employee === null) {
      return err({
        type: "NotFound",
        entity: "Employee",
        id
      });
    }

    return ok(employee);
  }
}
```

