# 9. Infrastructure: repository

For initial implementation, I’ll use an in-memory repository. In enterprise deployment, this would be replaced with PostgreSQL, Oracle, SQL Server, etc.

## `src/infrastructure/db/employee-repository.ts`

```ts
import type {
  Employee,
  EmployeeId,
  CreateEmployeeInput
} from "../../domain/employee.js";
import type { EmployeeRepository } from "../../domain/ports.js";
import { randomUUID } from "node:crypto";

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly employeesById = new Map<EmployeeId, Employee>();

  public async findById(id: EmployeeId): Promise<Employee | null> {
    return this.employeesById.get(id) ?? null;
  }

  public async findByEmail(email: string): Promise<Employee | null> {
    for (const employee of this.employeesById.values()) {
      if (employee.email.toLowerCase() === email.toLowerCase()) {
        return employee;
      }
    }
    return null;
  }

  public async create(input: CreateEmployeeInput): Promise<Employee> {
    const employee: Employee = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      department: input.department,
      managerId: input.managerId,
      createdAt: new Date()
    };

    this.employeesById.set(employee.id, employee);
    return employee;
  }
}
```

