# 13. Error mapping

## `src/infrastructure/web/error-handler.ts`

```ts
import type { FastifyReply } from "fastify";
import type { DomainError } from "../../domain/errors.js";

export function sendDomainError(reply: FastifyReply, error: DomainError): void {
  switch (error.type) {
    case "ValidationError":
      void reply.status(400).send({
        error: error.type,
        message: error.message
      });
      return;

    case "NotFound":
      void reply.status(404).send({
        error: error.type,
        entity: error.entity,
        id: error.id
      });
      return;

    case "Conflict":
      void reply.status(409).send({
        error: error.type,
        entity: error.entity,
        field: error.field
      });
      return;

    case "IntegrationError":
      void reply.status(502).send({
        error: error.type,
        system: error.system,
        message: error.message
      });
      return;
  }
}
```

