## `src/infrastructure/web/routes/employee-routes.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import type { EmployeeService } from "../../../application/employee-service.js";
import { sendDomainError } from "../error-handler.js";
import {
  createEmployeeBodySchema,
  employeeParamsSchema,
  type CreateEmployeeBody,
  type EmployeeParams
} from "../schemas/employee-schemas.js";

type Dependencies = {
  readonly employeeService: EmployeeService;
};

export async function employeeRoutes(
  app: FastifyInstance,
  dependencies: Dependencies
): Promise<void> {
  app.post(
    "/employees",
    async (
      request: FastifyRequest<{ Body: CreateEmployeeBody }>,
      reply: FastifyReply
    ) => {
      try {
        const body = createEmployeeBodySchema.parse(request.body);
        const result = await dependencies.employeeService.createEmployee(body);

        if (!result.ok) {
          sendDomainError(reply, result.error);
          return;
        }

        void reply.status(201).send(result.value);
      } catch (error) {
        if (error instanceof ZodError) {
          void reply.status(400).send({
            error: "ValidationError",
            message: "Invalid request body",
            details: error.flatten()
          });
          return;
        }

        throw error;
      }
    }
  );

  app.get(
    "/employees/:id",
    async (
      request: FastifyRequest<{ Params: EmployeeParams }>,
      reply: FastifyReply
    ) => {
      try {
        const params = employeeParamsSchema.parse(request.params);
        const result = await dependencies.employeeService.getEmployeeById(params.id);

        if (!result.ok) {
          sendDomainError(reply, result.error);
          return;
        }

        void reply.status(200).send(result.value);
      } catch (error) {
        if (error instanceof ZodError) {
          void reply.status(400).send({
            error: "ValidationError",
            message: "Invalid route parameters",
            details: error.flatten()
          });
          return;
        }

        throw error;
      }
    }
  );
}
```

