# 15. App composition

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import type { AppConfig } from "./config/types.js";
import { EmployeeService } from "./application/employee-service.js";
import { InMemoryEmployeeRepository } from "./infrastructure/db/employee-repository.js";
import { MockCorporateHrClient } from "./infrastructure/integrations/corporate-hr-client.js";
import { LoggingEventPublisher } from "./infrastructure/integrations/event-publisher.js";
import { healthRoutes } from "./infrastructure/web/routes/health-routes.js";
import { employeeRoutes } from "./infrastructure/web/routes/employee-routes.js";
import { createLogger } from "./infrastructure/logging/logger.js";

export async function buildApp(config: AppConfig) {
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  await app.register(sensible);

  const repository = new InMemoryEmployeeRepository();
  const corporateHrClient = new MockCorporateHrClient();
  const eventPublisher = new LoggingEventPublisher(logger);

  const employeeService = new EmployeeService(
    repository,
    corporateHrClient,
    eventPublisher
  );

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await employeeRoutes(instance, { employeeService });
  });

  return app;
}
```

