```ts
import { Inject, Injectable, ConflictException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { toCustomerId } from '../../../common/types/branded.types';
import { Customer } from '../domain/customer.entity';
import {
  CUSTOMER_REPOSITORY,
  CustomerRepository
} from '../domain/customer.repository';
import { CrmClient } from '../infrastructure/crm/crm.client';
import { CreateCustomerCommand } from './commands/create-customer.command';

@Injectable()
export class CustomerService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepository,
    private readonly crmClient: CrmClient
  ) {}

  async createCustomer(command: CreateCustomerCommand): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(command.email);
    if (existing) {
      throw new ConflictException('Customer with this email already exists');
    }

    const crmRecord = await this.crmClient.createCustomer({
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName
    });

    const customer = new Customer({
      id: toCustomerId(randomUUID()),
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName,
      externalCrmId: crmRecord.id,
      createdAt: new Date()
    });

    return this.customerRepository.save(customer);
  }
}
```

