import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';
import { Customer } from '../domain/customer.entity';
import { CustomerRepository } from '../domain/customer.repository';
import { toCustomerId } from '../../../common/types/branded.types';

@Injectable()
export class CustomerPrismaRepository implements CustomerRepository {
  constructor(private readonly prisma: PrismaService) {}

  async save(customer: Customer): Promise<Customer> {
    await this.prisma.customer.upsert({
      where: { id: customer.id },
      update: {
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        externalCrmId: customer.externalCrmId,
        createdAt: customer.createdAt
      },
      create: {
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        externalCrmId: customer.externalCrmId,
        createdAt: customer.createdAt
      }
    });

    return customer;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const record = await this.prisma.customer.findUnique({
      where: { email }
    });

    if (!record) {
      return null;
    }

    return new Customer({
      id: toCustomerId(record.id),
      email: record.email,
      firstName: record.firstName,
      lastName: record.lastName,
      externalCrmId: record.externalCrmId ?? undefined,
      createdAt: record.createdAt
    });
  }
}
