# 5. Domain layer

## `src/domain/customer/customer.types.ts`

```ts
export type CustomerId = string & { readonly brand: unique symbol };
export type Email = string & { readonly brand: unique symbol };

export function toCustomerId(value: string): CustomerId {
  if (!value || value.trim().length === 0) {
    throw new Error('Invalid CustomerId');
  }
  return value as CustomerId;
}

export function toEmail(value: string): Email {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(value)) {
    throw new Error('Invalid Email');
  }
  return value as Email;
}
```

## `src/domain/customer/customer.entity.ts`

