import { CustomerId, Email, toCustomerId, toEmail } from './customer.types';

export interface CustomerProps {
  id: CustomerId;
  firstName: string;
  lastName: string;
  email: Email;
  createdAt: Date;
}

export class Customer {
  private constructor(private readonly props: CustomerProps) {}

  static create(input: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    createdAt?: Date;
  }): Customer {
    if (input.firstName.trim().length === 0) {
      throw new Error('firstName must not be empty');
    }
    if (input.lastName.trim().length === 0) {
      throw new Error('lastName must not be empty');
    }

    return new Customer({
      id: toCustomerId(input.id),
      firstName: input.firstName.trim(),
      lastName: input.lastName.trim(),
      email: toEmail(input.email),
      createdAt: input.createdAt ?? new Date()
    });
  }

  get id(): CustomerId {
    return this.props.id;
  }

  get firstName(): string {
    return this.props.firstName;
  }

  get lastName(): string {
    return this.props.lastName;
  }

  get email(): Email {
    return this.props.email;
  }

  get createdAt(): Date {
    return this.props.createdAt;
  }

  toPrimitives(): CustomerProps {
    return { ...this.props };
  }
}
