# 15. Example of improved create service with typed errors

```ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import {
  CUSTOMER_REPOSITORY,
  CustomerRepository
} from '../../../domain/customer/customer.repository';
import { Customer } from '../../../domain/customer/customer.entity';
import { toEmail } from '../../../domain/customer/customer.types';
import { ConflictApplicationError } from '../../../common/errors/application.error';
import {
  CUSTOMER_MASTER_DATA_PORT,
  CustomerMasterDataPort
} from '../ports/customer-master-data.port';
import {
  EVENT_PUBLISHER_PORT,
  EventPublisherPort
} from '../ports/event-publisher.port';
import { CreateCustomerCommand } from '../dto/create-customer.command';
import { CustomerResponse } from '../dto/customer.response';

@Injectable()
export class CreateCustomerService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepository,
    @Inject(CUSTOMER_MASTER_DATA_PORT)
    private readonly masterDataPort: CustomerMasterDataPort,
    @Inject(EVENT_PUBLISHER_PORT)
    private readonly eventPublisher: EventPublisherPort
  ) {}

  async execute(command: CreateCustomerCommand): Promise<CustomerResponse> {
    const existing = await this.customerRepository.findByEmail(toEmail(command.email));
    if (existing) {
      throw new ConflictApplicationError('Customer with this email already exists');
    }

    const customer = Customer.create({
      id: randomUUID(),
      firstName: command.firstName,
      lastName: command.lastName,
      email: command.email
    });

    await this.customerRepository.save(customer);
    await this.masterDataPort.syncCustomer(customer);
    await this.eventPublisher.publish('customer.created', {
      customerId: customer.id,
      email: customer.email,
      occurredAt: customer.createdAt.toISOString()
    });

    return {
      id: customer.id,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString()
    };
  }
}
```

