import { toCustomerId } from '../../../common/types/branded-types';
import { DomainError } from '../../../common/errors/domain.error';
import { CreateCustomerProps, CustomerProps } from './customer.types';
import { randomUUID } from 'crypto';

export class Customer {
  private constructor(private readonly props: CustomerProps) {}

  static create(input: CreateCustomerProps): Customer {
    if (!input.email.includes('@')) {
      throw new DomainError('INVALID_EMAIL', 'Email format is invalid');
    }

    return new Customer({
      id: toCustomerId(randomUUID()),
      email: input.email.toLowerCase(),
      firstName: input.firstName.trim(),
      lastName: input.lastName.trim(),
      createdAt: new Date(),
    });
  }

  static rehydrate(props: CustomerProps): Customer {
    return new Customer(props);
  }

  get id() {
    return this.props.id;
  }

  get email() {
    return this.props.email;
  }

  get firstName() {
    return this.props.firstName;
  }

  get lastName() {
    return this.props.lastName;
  }

  get externalCrmId() {
    return this.props.externalCrmId;
  }

  get createdAt() {
    return this.props.createdAt;
  }

  attachCrmId(crmId: string): Customer {
    return Customer.rehydrate({
      ...this.props,
      externalCrmId: crmId,
    });
  }

  toPrimitives(): CustomerProps {
    return { ...this.props };
  }
}
