## `src/modules/customer/application/services/create-customer.service.ts`

```ts
import { Inject, Injectable, ConflictException } from '@nestjs/common';
import {
  CUSTOMER_REPOSITORY,
  CustomerRepository,
} from '../ports/customer.repository';
import { CRM_GATEWAY, CrmGateway } from '../ports/crm.gateway';
import { Customer } from '../../domain/customer.entity';
import { CreateCustomerCommand } from '../commands/create-customer.command';

@Injectable()
export class CreateCustomerService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepository,
    @Inject(CRM_GATEWAY)
    private readonly crmGateway: CrmGateway,
  ) {}

  async execute(command: CreateCustomerCommand): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(
      command.email.toLowerCase(),
    );

    if (existing) {
      throw new ConflictException('Customer already exists');
    }

    const customer = Customer.create(command);
    const crmResult = await this.crmGateway.createCustomer(customer);
    const enrichedCustomer = customer.attachCrmId(crmResult.crmId);

    await this.customerRepository.save(enrichedCustomer);

    return enrichedCustomer;
  }
}
```

