# 15. Repository implementation

## `src/modules/customer/infrastructure/prisma-customer.repository.ts`

```ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../../infrastructure/prisma/prisma.service';
import { CustomerRepository } from '../application/ports/customer.repository';
import { Customer } from '../domain/customer.entity';
import { toCustomerId } from '../../../common/types/branded-types';

@Injectable()
export class PrismaCustomerRepository implements CustomerRepository {
  constructor(private readonly prisma: PrismaService) {}

  async save(customer: Customer): Promise<void> {
    const data = customer.toPrimitives();

    await this.prisma.customer.upsert({
      where: { id: data.id },
      update: {
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        externalCrmId: data.externalCrmId,
      },
      create: {
        id: data.id,
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        externalCrmId: data.externalCrmId,
        createdAt: data.createdAt,
      },
    });
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const row = await this.prisma.customer.findUnique({
      where: { email },
    });

    if (!row) {
      return null;
    }

    return Customer.rehydrate({
      id: toCustomerId(row.id),
      email: row.email,
      firstName: row.firstName,
      lastName: row.lastName,
      externalCrmId: row.externalCrmId ?? undefined,
      createdAt: row.createdAt,
    });
  }
}
```

