  id: z.string().min(1),
});

@Injectable()
export class CorporateCrmGateway implements CrmGateway {
  constructor(private readonly httpClient: CorporateHttpClient) {}

  async createCustomer(customer: Customer): Promise<{ crmId: string }> {
    const response = await this.httpClient.post<
      {
        email: string;
        givenName: string;
        familyName: string;
      },
      unknown
    >('/customers', {
      email: customer.email,
      givenName: customer.firstName,
      familyName: customer.lastName,
    });

    const parsed = crmCreateResponseSchema.parse(response);

    return { crmId: parsed.id };
  }
}
