import type { CustomerProfile } from "../domain/customer.js";
import { NotFoundError } from "../domain/errors.js";
import type { CorporateIdentityClient } from "../infrastructure/corporate-identity-client.js";
import type { CorporateCrmClient } from "../infrastructure/corporate-crm-client.js";
import type { Logger } from "../infrastructure/logger.js";

export interface CustomerService {
  getCustomerProfile(customerId: string): Promise<CustomerProfile>;
}

export class DefaultCustomerService implements CustomerService {
  constructor(
    private readonly identityClient: CorporateIdentityClient,
    private readonly crmClient: CorporateCrmClient,
    private readonly logger: Logger
  ) {}

  async getCustomerProfile(customerId: string): Promise<CustomerProfile> {
    this.logger.info("Fetching customer profile", { customerId });

    const identity = await this.identityClient.getIdentityByCustomerId(customerId);

    if (identity === null) {
      throw new NotFoundError(`Customer not found: ${customerId}`);
    }

    const crm = await this.crmClient.getCustomerMetadata(customerId);

    return {
      id: identity.employeeId,
      email: identity.email,
      fullName: identity.fullName,
      status: identity.active ? "ACTIVE" : "INACTIVE",
      department: crm?.department
    };
  }
}
