# 12. Routes

## src/api/routes.ts

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import { NotFoundError, UpstreamServiceError } from "../domain/errors.js";
import { customerParamsSchema, customerResponseSchema } from "./schemas.js";
import type { CustomerService } from "../application/customer-service.js";

export interface RouteDependencies {
  customerService: CustomerService;
}

export async function registerRoutes(
  app: FastifyInstance,
  deps: RouteDependencies
): Promise<void> {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get(
    "/api/v1/customers/:id",
    async (
      request: FastifyRequest<{ Params: { id: string } }>,
      reply: FastifyReply
    ) => {
      try {
        const params = customerParamsSchema.parse(request.params);
        const customer = await deps.customerService.getCustomerProfile(params.id);
        const response = customerResponseSchema.parse(customer);
        return reply.status(200).send(response);
      } catch (error: unknown) {
        if (error instanceof ZodError) {
          return reply.status(400).send({
            error: "BAD_REQUEST",
            message: error.message
          });
        }

        if (error instanceof NotFoundError) {
          return reply.status(404).send({
            error: error.code,
            message: error.message
          });
        }

        if (error instanceof UpstreamServiceError) {
          return reply.status(502).send({
            error: error.code,
            message: error.message
          });
        }

        return reply.status(500).send({
          error: "INTERNAL_SERVER_ERROR",
          message: "An unexpected error occurred"
        });
      }
    }
  );
}
```

