# 10. Routes

## src/routes/customerRoutes.ts

```ts
import { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { customerIdParamsSchema, customerResponseSchema } from "../schemas/customer.js";
import { CustomerService } from "../services/customerService.js";

const notFoundResponseSchema = z.object({
  message: z.string()
});

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const customerService = new CustomerService(app.corporateClient);

  app.get(
    "/customers/:id",
    async (request: GetCustomerRequest, reply: FastifyReply): Promise<void> => {
      const params = customerIdParamsSchema.parse(request.params);
      const customer = await customerService.getCustomerById(params.id);

      if (customer === null) {
        reply.code(404).send({ message: "Customer not found" });
        return;
      }

      const response = customerResponseSchema.parse(customer);
      reply.code(200).send(response);
    }
  );

  app.get("/health", async (): Promise<{ status: string }> => {
    return { status: "ok" };
  });

  app.get("/ready", async (): Promise<{ status: string }> => {
    return { status: "ready" };
  });

  void notFoundResponseSchema;
}
```

