      }
    }
  });

  app.addHook("onRequest", async (request) => {
    request.log.info(
      {
        requestId: request.id,
        method: request.method,
        url: request.url
      },
      "incoming request"
    );
  });

  app.register(corporateClientPlugin);
  app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
