# 9. src/plugins/auth-context.ts

This simulates integration with a corporate identity system via headers injected by an API gateway or SSO proxy.

```ts
import fp from "fastify-plugin";
import { z } from "zod";
import type { FastifyRequest } from "fastify";

const AuthContextSchema = z.object({
  userId: z.string().min(1),
  userEmail: z.string().email(),
  roles: z.array(z.string())
});

export type AuthContext = z.infer<typeof AuthContextSchema>;

declare module "fastify" {
  interface FastifyRequest {
    authContext: AuthContext | null;
  }
}

function parseRoles(value: string | undefined): string[] {
  if (!value) return [];
  return value
    .split(",")
    .map((role) => role.trim())
    .filter((role) => role.length > 0);
}

function extractAuthContext(request: FastifyRequest): AuthContext | null {
  const candidate = {
    userId: request.headers["x-corp-user-id"],
    userEmail: request.headers["x-corp-user-email"],
    roles: parseRoles(
      typeof request.headers["x-corp-roles"] === "string"
        ? request.headers["x-corp-roles"]
        : undefined
    )
  };

  const parsed = AuthContextSchema.safeParse(candidate);
  return parsed.success ? parsed.data : null;
}

export default fp(async (fastify) => {
  fastify.decorateRequest("authContext", null);

  fastify.addHook("preHandler", async (request) => {
    request.authContext = extractAuthContext(request);
  });
});
```

