export class HttpCorporateCrmClient implements CorporateCrmClient {
  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const simulatedResponse = {
      id: crypto.randomUUID(),
      name: input.name,
      email: input.email,
      status: "active"
    };

    return CustomerSchema.parse(simulatedResponse);
  }

  async getCustomerById(id: string): Promise<Customer | null> {
    if (id === "not-found") {
      return null;
    }

    const simulatedResponse = {
      id,
      name: "Jane Doe",
      email: "jane.doe@example.com",
      status: "active"
    };

    return CustomerSchema.parse(simulatedResponse);
  }
}

export function buildCorporateCrmClient(): CorporateCrmClient {
  void config.CRM_BASE_URL;
  void config.CRM_API_KEY;
  return new HttpCorporateCrmClient();
}
