# 13. src/routes/customers.ts

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CustomerSchema,
  CustomerIdSchema
} from "../types.js";
import type { CustomerService } from "../services/customer-service.js";

const GetCustomerParamsSchema = z.object({
  id: CustomerIdSchema
});

type GetCustomerParams = z.infer<typeof GetCustomerParamsSchema>;

export async function customerRoutes(
  fastify: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  fastify.post(
    "/customers",
    async (
      request: FastifyRequest<{ Body: unknown }>,
      reply: FastifyReply
    ) => {
      if (!request.authContext) {
        return reply.code(401).send({ message: "Unauthorized" });
      }

      const body = CreateCustomerRequestSchema.parse(request.body);
      const customer = await deps.customerService.createCustomer(body);
      return reply.code(201).send(CustomerSchema.parse(customer));
    }
  );

  fastify.get(
    "/customers/:id",
    async (
      request: FastifyRequest<{ Params: GetCustomerParams }>,
      reply: FastifyReply
    ) => {
      if (!request.authContext) {
        return reply.code(401).send({ message: "Unauthorized" });
      }

      const params = GetCustomerParamsSchema.parse(request.params);
      const customer = await deps.customerService.getCustomerById(params.id);

      if (!customer) {
        return reply.code(404).send({ message: "Customer not found" });
      }

      return reply.send(CustomerSchema.parse(customer));
    }
  );
}
```

