# 14. src/app.ts

Application composition.

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { logger } from "./logger.js";
import authContextPlugin from "./plugins/auth-context.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { buildCorporateCrmClient } from "./clients/corporate-crm-client.js";
import { DefaultCustomerService } from "./services/customer-service.js";

export async function buildApp() {
  const app = Fastify({
    logger: false
  });

  await app.register(sensible);
  await app.register(authContextPlugin);

  app.setErrorHandler((error, request, reply) => {
    logger.error("request_failed", {
      method: request.method,
      url: request.url,
      error: error.message
    });

    return reply.code(400).send({
      message: error.message
    });
  });

  const crmClient = buildCorporateCrmClient();
  const customerService = new DefaultCustomerService(crmClient);

  await app.register(healthRoutes);
  await customerRoutes(app, { customerService });

  return app;
}
```

