```ts
import { randomUUID } from "node:crypto";
import type { CreateCustomerRequest, Customer } from "../domain/customer.js";

export interface CorporateCrmClient {
  createCustomer(input: CreateCustomerRequest): Promise<Customer>;
  getCustomerById(id: string): Promise<Customer | null>;
}

export class MockCorporateCrmClient implements CorporateCrmClient {
  private readonly store = new Map<string, Customer>();

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString()
    };

    this.store.set(customer.id, customer);
    return customer;
  }

  async getCustomerById(id: string): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }
}
```

