import type { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CustomerIdSchema
} from "../domain/customer.js";
import type { CustomerService } from "../services/customerService.js";

const CustomerParamsSchema = z.object({
  id: CustomerIdSchema
});

export async function customerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const body = CreateCustomerRequestSchema.parse(request.body);
    const customer = await deps.customerService.createCustomer(body);
    reply.status(201).send(customer);
  });

  app.get("/customers/:id", async (request, reply) => {
    const params = CustomerParamsSchema.parse(request.params);
    const customer = await deps.customerService.getCustomerById(params.id);

    if (customer === null) {
      reply.status(404).send({
        code: "CUSTOMER_NOT_FOUND",
        message: `Customer ${params.id} not found`
      });
      return;
    }

    reply.send(customer);
  });
}
