import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { z } from 'zod';
import type { CustomerService } from '../services/customerService.js';
import { AppError } from '../utils/errors.js';

const createCustomerSchema = z.object({
  email: z.string().email(),
  firstName: z.string().min(1),
  lastName: z.string().min(1)
});

type CreateCustomerBody = z.infer<typeof createCustomerSchema>;

export async function customerRoutes(
  fastify: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  fastify.post(
    '/customers',
    async (
      request: FastifyRequest<{ Body: CreateCustomerBody }>,
      reply: FastifyReply
    ) => {
      const parsed = createCustomerSchema.safeParse(request.body);

      if (!parsed.success) {
        throw new AppError('Invalid request body', 400, 'VALIDATION_ERROR');
      }

      const customer = await deps.customerService.createCustomer(parsed.data);

      return reply.code(201).send({ customer });
    }
  );
}
```

