import Fastify from 'fastify';
import { config } from './config.js';
import { customerRoutes } from './routes/customer.js';
import { MockCorporateCrmClient } from './integrations/corporateCrmClient.js';
import { CustomerService } from './services/customerService.js';
import { AppError } from './utils/errors.js';

export function buildApp() {
  const app = Fastify({
    logger: true
  });

  const crmClient = new MockCorporateCrmClient();
  const customerService = new CustomerService(crmClient);

  app.get('/health', async () => {
    return {
      status: 'ok',
      service: config.SERVICE_NAME
    };
  });

  app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message
        }
      });
    }

    app.log.error(error);

    return reply.status(500).send({
      error: {
        code: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred'
      }
    });
  });

  return app;
}
