# 7. `src/plugins/corporateClient.ts`

Typed integration client for existing corporate systems.

```ts
import { request } from "undici";
import { z } from "zod";
import { AppError } from "../utils/errors.js";

const CorporateCustomerSchema = z.object({
  customerId: z.string(),
  fullName: z.string(),
  primaryEmail: z.string().email(),
  enabled: z.boolean()
});

type CorporateCustomer = z.infer<typeof CorporateCustomerSchema>;

export interface CorporateClient {
  createCustomer(input: {
    name: string;
    email: string;
  }): Promise<CorporateCustomer>;
}

export function buildCorporateClient(config: {
  baseUrl: string;
  token: string;
}): CorporateClient {
  return {
    async createCustomer(input) {
      const response = await request(`${config.baseUrl}/api/customers`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${config.token}`
        },
        body: JSON.stringify(input)
      });

      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw new AppError(
          `Corporate API returned status ${response.statusCode}`,
          "CORPORATE_API_ERROR",
          502
        );
      }

      const body = await response.body.json();
      const parsed = CorporateCustomerSchema.safeParse(body);

      if (!parsed.success) {
        throw new AppError(
          "Corporate API returned invalid payload",
          "CORPORATE_API_INVALID_RESPONSE",
          502
        );
      }

      return parsed.data;
    }
  };
}
```

