# 10. `src/routes/customers.ts`

Typed route with validation.

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CreateCustomerResponseSchema,
  ErrorResponseSchema
} from "../types.js";
import { AppError } from "../utils/errors.js";

const BodySchema = CreateCustomerRequestSchema;

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const parsedBody = BodySchema.safeParse(request.body);

    if (!parsedBody.success) {
      return reply.status(400).send({
        error: {
          code: "VALIDATION_ERROR",
          message: z.prettifyError ? "Invalid request body" : "Invalid request body"
        }
      });
    }

    const customer = await app.customerService.createCustomer(parsedBody.data);
    const response = { customer };

    const parsedResponse = CreateCustomerResponseSchema.safeParse(response);
    if (!parsedResponse.success) {
      throw new AppError("Invalid response payload", "RESPONSE_VALIDATION_ERROR", 500);
    }

    return reply.status(201).send(parsedResponse.data);
  });

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message
        }
      });
    }

    app.log.error({ err: error }, "Unhandled error");

    return reply.status(500).send({
      error: {
        code: "INTERNAL_ERROR",
        message: "Internal server error"
      }
    });
  });
}
```

