```ts
import Fastify from "fastify";
import { loadConfig } from "./config.js";
import { buildCorporateClient } from "./plugins/corporateClient.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { CustomerService } from "./services/customerService.js";

declare module "fastify" {
  interface FastifyInstance {
    customerService: CustomerService;
  }
}

export function buildApp() {
  const config = loadConfig(process.env);

  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL
    }
  });

  const corporateClient = buildCorporateClient({
    baseUrl: config.CORPORATE_API_BASE_URL,
    token: config.CORPORATE_API_TOKEN
  });

  const customerService = new CustomerService(corporateClient);

  app.decorate("customerService", customerService);

  app.register(healthRoutes);
  app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
```

