# 7) `src/plugins/auth.ts`

A minimal corporate auth middleware stub.

In a real enterprise, this would validate JWTs, mTLS identity, SSO headers, or API gateway claims.

```ts
import fp from "fastify-plugin";
import type { FastifyPluginAsync, FastifyRequest } from "fastify";
import { UnauthorizedError } from "../utils/errors.js";
import type { AuthenticatedUser } from "../types.js";

declare module "fastify" {
  interface FastifyRequest {
    user?: AuthenticatedUser;
  }
}

function parseCorporateIdentity(request: FastifyRequest): AuthenticatedUser {
  const employeeId = request.headers["x-employee-id"];
  const email = request.headers["x-employee-email"];
  const roles = request.headers["x-employee-roles"];

  if (
    typeof employeeId !== "string" ||
    typeof email !== "string" ||
    typeof roles !== "string"
  ) {
    throw new UnauthorizedError("Missing corporate identity headers");
  }

  return {
    employeeId,
    email,
    roles: roles.split(",").map((r) => r.trim())
  };
}

const authPlugin: FastifyPluginAsync = async (fastify) => {
  fastify.decorateRequest("user", null);

  fastify.addHook("preHandler", async (request) => {
    if (request.url.startsWith("/health")) {
      return;
    }

    request.user = parseCorporateIdentity(request);
  });
};

export default fp(authPlugin);
```

