# 9. Corporate integration plugin

This simulates integration with an internal enterprise system.

## src/plugins/corporate-client.ts

```ts
import fp from "fastify-plugin";
import { request } from "undici";
import { z } from "zod";
import { CustomerSchema, type Customer } from "../types.js";
import { UpstreamServiceError } from "../lib/errors.js";
import type { FastifyInstance } from "fastify";
import type { AppConfig } from "../config.js";

const CorporateCustomerResponseSchema = CustomerSchema;

export interface CorporateClient {
  getCustomerById(id: string): Promise<Customer>;
}

declare module "fastify" {
  interface FastifyInstance {
    corporateClient: CorporateClient;
    appConfig: AppConfig;
  }
}

async function corporateClientPlugin(app: FastifyInstance): Promise<void> {
  const client: CorporateClient = {
    async getCustomerById(id: string): Promise<Customer> {
      const url = new URL(`/customers/${encodeURIComponent(id)}`, app.appConfig.CORPORATE_API_BASE_URL);

      const response = await request(url, {
        method: "GET",
        headers: {
          "authorization": `Bearer ${app.appConfig.CORPORATE_API_KEY}`,
          "accept": "application/json"
        }
      });

      if (response.statusCode === 404) {
        throw new UpstreamServiceError(`Customer not found: ${id}`, 404);
      }

      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw new UpstreamServiceError(
          `Corporate API error with status ${response.statusCode}`,
          502
        );
      }

      const body = await response.body.json();
      const parsed = CorporateCustomerResponseSchema.safeParse(body);

      if (!parsed.success) {
        throw new UpstreamServiceError("Invalid response from corporate API", 502);
      }

      return parsed.data;
    }
  };

  app.decorate("corporateClient", client);
}

export default fp(corporateClientPlugin, {
  name: "corporate-client"
});
```

> Note: this uses `fastify-plugin`, so add it to dependencies.

Update `package.json` dependencies:

```json
"fastify-plugin": "^5.0.0"
```

