import type { FastifyPluginAsync } from "fastify";
import { GetCustomerParamsSchema } from "../types.js";
import { UpstreamServiceError } from "../lib/errors.js";

const customersRoute: FastifyPluginAsync = async (app) => {
  app.get("/customers/:id", async (request, reply) => {
    const parsed = GetCustomerParamsSchema.safeParse(request.params);

    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid customer id"
      });
    }

    try {
      const customer = await app.corporateClient.getCustomerById(parsed.data.id);
      return reply.status(200).send(customer);
    } catch (error) {
      if (error instanceof UpstreamServiceError) {
        return reply.status(error.statusCode).send({
          error: error.message
        });
      }

      request.log.error({ err: error }, "Unhandled error in customers route");
      return reply.status(500).send({
        error: "Internal server error"
      });
    }
  });
};

export default customersRoute;
