# 11. App assembly

## src/app.ts

```ts
import Fastify, { type FastifyInstance } from "fastify";
import { loadConfig, type AppConfig } from "./config.js";
import corporateClientPlugin from "./plugins/corporate-client.js";
import healthRoute from "./routes/health.js";
import customersRoute from "./routes/customers.js";

export function buildApp(configOverride?: AppConfig): FastifyInstance {
  const config = configOverride ?? loadConfig(process.env);

  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL
    }
  });

  app.decorate("appConfig", config);

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Unhandled application error");
    void reply.status(500).send({
      error: "Internal server error"
    });
  });

  void app.register(corporateClientPlugin);
  void app.register(healthRoute);
  void app.register(customersRoute);

  return app;
}
```

