# 11. src/routes/customers.ts

This route uses typed params and response schemas.

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customerService.js";

const customerParamsSchema = z.object({
  id: z.string().min(1)
});

const customerResponseSchema = z.object({
  id: z.string(),
  firstName: z.string(),
  lastName: z.string(),
  email: z.string().email(),
  status: z.enum(["ACTIVE", "INACTIVE"])
});

const notFoundResponseSchema = z.object({
  message: z.string()
});

type CustomerParams = z.infer<typeof customerParamsSchema>;
type CustomerResponse = z.infer<typeof customerResponseSchema>;

export async function customerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.get<{ Params: CustomerParams }>(
    "/v1/customers/:id",
    async (request, reply): Promise<CustomerResponse | { message: string }> => {
      const params = customerParamsSchema.parse(request.params);
      const customer = await deps.customerService.getCustomerById(params.id);

      if (customer === null) {
        reply.code(404);
        return notFoundResponseSchema.parse({
          message: "Customer not found"
        });
      }

      return customerResponseSchema.parse(customer);
    }
  );
}
```

