# 12. src/app.ts

Application composition root.

```ts
import Fastify, { FastifyInstance } from "fastify";
import { AppConfig } from "./config.js";
import { HttpCorporateClient } from "./plugins/corporateClient.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { CustomerService } from "./services/customerService.js";
import { ZodError } from "zod";

export function buildApp(config: AppConfig): FastifyInstance {
  const app = Fastify({
    logger: true
  });

  const corporateClient = new HttpCorporateClient({
    baseUrl: config.CORPORATE_API_BASE_URL,
    timeoutMs: config.CORPORATE_API_TIMEOUT_MS
  });

  const customerService = new CustomerService(corporateClient);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ZodError) {
      reply.status(400).send({
        message: "Validation error",
        issues: error.issues
      });
      return;
    }

    app.log.error(error);
    reply.status(500).send({
      message: "Internal server error"
    });
  });

  void app.register(healthRoutes);
  void app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
```

