## `src/routes/customers.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CustomerSchema
} from "../domain/customer.js";
import { CustomerService } from "../services/customerService.js";

export async function customerRoutes(
  fastify: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  fastify.post(
    "/customers",
    async (request, reply) => {
      const bodyResult = CreateCustomerRequestSchema.safeParse(request.body);

      if (!bodyResult.success) {
        return reply.status(400).send({
          error: "VALIDATION_ERROR",
          message: bodyResult.error.message
        });
      }

      const customer = await customerService.createCustomer(bodyResult.data);

      const responseResult = CustomerSchema.safeParse(customer);
      if (!responseResult.success) {
        request.log.error(
          { error: responseResult.error },
          "Invalid customer response from service"
        );

        return reply.status(500).send({
          error: "INTERNAL_ERROR",
          message: "Invalid response generated by service"
        });
      }

      return reply.status(201).send(responseResult.data);
    }
  );
}
```

