import { healthRoutes } from "./routes/health.js";
import { DefaultCustomerService } from "./services/customerService.js";

export function buildApp(env: Env): FastifyInstance {
  const app = Fastify({
    logger: true
  });

  const authClient = new HttpCorporateAuthClient(
    env.CORPORATE_AUTH_URL,
    env.CORPORATE_API_KEY
  );

  const crmClient = new HttpCorporateCrmClient(env.CORPORATE_CRM_URL);

  const customerService = new DefaultCustomerService(authClient, crmClient);

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Unhandled error");

    reply.status(500).send({
      error: "INTERNAL_ERROR",
      message: "An unexpected error occurred"
    });
  });

  void healthRoutes(app, env);
  void customerRoutes(app, customerService);

  return app;
}
