# 7. `src/services/corporateDirectory.ts`

A typed integration stub for an existing corporate system.

```ts
import { Customer } from "../schemas/customer.js";

export interface CorporateDirectoryClient {
  getCustomerById(id: string): Promise<Customer | null>;
  createCustomer(input: Omit<Customer, "id">): Promise<Customer>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  constructor(private readonly baseUrl: string) {}

  async getCustomerById(id: string): Promise<Customer | null> {
    const response = await fetch(`${this.baseUrl}/customers/${id}`, {
      headers: {
        "Accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate API error: ${response.status}`);
    }

    const data: unknown = await response.json();

    // In a real implementation, validate with Zod before returning.
    return data as Customer;
  }

  async createCustomer(input: Omit<Customer, "id">): Promise<Customer> {
    const response = await fetch(`${this.baseUrl}/customers`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify(input)
    });

    if (!response.ok) {
      throw new Error(`Corporate API error: ${response.status}`);
    }

    const data: unknown = await response.json();
    return data as Customer;
  }
}
