import Fastify, { FastifyInstance } from "fastify";
import { config } from "./config.js";
import { HealthResponse } from "./types/common.js";
import { customerRoutes } from "./routes/customers.js";
import { HttpCorporateDirectoryClient } from "./services/corporateDirectory.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger: {
      level: config.NODE_ENV === "production" ? "info" : "debug"
    }
  });

  const corporateClient = new HttpCorporateDirectoryClient(
    config.CORPORATE_API_BASE_URL
  );

  app.decorate("corporateClient", corporateClient);

  app.get("/health", async (): Promise<HealthResponse> => {
    return {
      status: "ok",
      service: config.SERVICE_NAME,
      version: config.SERVICE_VERSION,
      timestamp: new Date().toISOString()
    };
  });

  app.register(customerRoutes, { prefix: "/customers" });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Unhandled error");

    reply.status(500).send({
      error: "InternalServerError",
      message: "An unexpected error occurred"
    });
  });

  return app;
}
