import { FastifyPluginAsync } from "fastify";
import { randomUUID } from "node:crypto";
import {
  createCustomerSchema,
  customerIdParamsSchema,
  customerSchema
} from "../schemas/customer.js";

export const customerRoutes: FastifyPluginAsync = async (app) => {
  app.get(
    "/:id",
    async (request, reply) => {
      const params = customerIdParamsSchema.parse(request.params);
      const customer = await app.corporateClient.getCustomerById(params.id);

      if (!customer) {
        return reply.status(404).send({
          error: "NotFound",
          message: "Customer not found"
        });
      }

      const validated = customerSchema.parse(customer);
      return reply.status(200).send(validated);
    }
  );

  app.post(
    "/",
    async (request, reply) => {
      const body = createCustomerSchema.parse(request.body);

      const created = await app.corporateClient.createCustomer({
        id: randomUUID(),
        ...body
      });

      const validated = customerSchema.parse(created);
      return reply.status(201).send(validated);
    }
  );
};
