Business logic layer.

```ts
import crypto from "node:crypto";
import type { Customer, CreateCustomerBody } from "../schemas/customer.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { CorporateClient } from "../plugins/corporateClient.js";
import { NotFoundError } from "../errors.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateClient: CorporateClient
  ) {}

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }
    return customer;
  }

  async createCustomer(input: CreateCustomerBody): Promise<Customer> {
    const integrationResult = await this.corporateClient.registerCustomer(input);

    const customer: Customer = {
      id: crypto.randomUUID(),
      name: input.name,
      email: input.email,
      externalRef: integrationResult.externalRef
    };

    return this.repository.create(customer);
  }
}
