# 15. src/routes/customers.ts

Typed routes with validation.

```ts
import type { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { createCustomerBodySchema, customerSchema } from "../schemas/customer.js";
import { CustomerService } from "../services/customerService.js";
import { InMemoryCustomerRepository } from "../repositories/customerRepository.js";
import { NotFoundError } from "../errors.js";

const paramsSchema = z.object({
  id: z.string().uuid()
});

const customerRoutes: FastifyPluginAsync = async (fastify) => {
  const repository = new InMemoryCustomerRepository();
  const service = new CustomerService(repository, fastify.corporateClient);

  fastify.get("/v1/customers/:id", async (request, reply) => {
    const parsedParams = paramsSchema.safeParse(request.params);
    if (!parsedParams.success) {
      return reply.status(400).send({
        error: "Bad Request",
        details: parsedParams.error.flatten()
      });
    }

    try {
      const customer = await service.getCustomer(parsedParams.data.id);
      const validated = customerSchema.parse(customer);
      return reply.status(200).send(validated);
    } catch (error) {
      if (error instanceof NotFoundError) {
        return reply.status(404).send({ error: error.message });
      }
      throw error;
    }
  });

  fastify.post("/v1/customers", async (request, reply) => {
    const parsedBody = createCustomerBodySchema.safeParse(request.body);
    if (!parsedBody.success) {
      return reply.status(400).send({
        error: "Bad Request",
        details: parsedBody.error.flatten()
      });
    }

    const customer = await service.createCustomer(parsedBody.data);
    const validated = customerSchema.parse(customer);
    return reply.status(201).send(validated);
  });
};

export default customerRoutes;
```

