# 7) `src/clients/corporateCrmClient.ts`

A typed client for an existing corporate system.

```ts
import { Customer, CustomerSchema } from "../types.js";
import { UpstreamServiceError } from "../utils/errors.js";

export interface CorporateCrmClient {
  getCustomerById(
    id: string,
    context: { userId: string; correlationId: string }
  ): Promise<Customer | null>;
}

export class HttpCorporateCrmClient implements CorporateCrmClient {
  constructor(private readonly baseUrl: string) {}

  async getCustomerById(
    id: string,
    context: { userId: string; correlationId: string }
  ): Promise<Customer | null> {
    const response = await fetch(`${this.baseUrl}/customers/${encodeURIComponent(id)}`, {
      method: "GET",
      headers: {
        "x-user-id": context.userId,
        "x-correlation-id": context.correlationId,
        "accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new UpstreamServiceError(`CRM returned status ${response.status}`);
    }

    const json: unknown = await response.json();
    return CustomerSchema.parse(json);
  }
}
```

