# 9) `src/plugins/corporateContext.ts`

This simulates enterprise integration with identity/correlation headers.

```ts
import fp from "fastify-plugin";
import { FastifyReply, FastifyRequest } from "fastify";
import { UnauthorizedError } from "../utils/errors.js";

declare module "fastify" {
  interface FastifyRequest {
    corporateContext: {
      userId: string;
      correlationId: string;
    };
  }
}

function getHeaderValue(value: string | string[] | undefined): string | undefined {
  if (Array.isArray(value)) return value[0];
  return value;
}

export default fp(async function corporateContextPlugin(fastify) {
  fastify.addHook("preHandler", async (request: FastifyRequest, _reply: FastifyReply) => {
    const userId = getHeaderValue(request.headers["x-user-id"]);
    const correlationId =
      getHeaderValue(request.headers["x-correlation-id"]) ?? request.id;

    if (!userId) {
      throw new UnauthorizedError("Missing x-user-id header");
    }

    request.corporateContext = {
      userId,
      correlationId
    };
  });
});
```

