import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customerService.js";
import { CustomerSchema, GetCustomerParamsSchema } from "../types.js";

const ParamsJsonSchema = {
  type: "object",
  required: ["id"],
  properties: {
    id: { type: "string", minLength: 1 }
  }
} as const;

const CustomerJsonSchema = {
  type: "object",
  required: ["id", "name", "email", "status"],
  properties: {
    id: { type: "string" },
    name: { type: "string" },
    email: { type: "string", format: "email" },
    status: { type: "string", enum: ["ACTIVE", "INACTIVE"] }
  }
} as const;

export async function customerRoutes(
  fastify: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  fastify.get(
    "/customers/:id",
    {
      schema: {
        params: ParamsJsonSchema,
        response: {
          200: CustomerJsonSchema
        }
      }
    },
    async (request, reply) => {
      const params = GetCustomerParamsSchema.parse(request.params);
      const customer = await deps.customerService.getCustomer(
        params.id,
        request.corporateContext
      );

      const validated = CustomerSchema.parse(customer);
      return reply.status(200).send(validated);
    }
  );
}
```

