# 12) `src/app.ts`

Application composition root.

```ts
import Fastify, { FastifyInstance } from "fastify";
import corporateContextPlugin from "./plugins/corporateContext.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { loadConfig } from "./config.js";
import { HttpCorporateCrmClient } from "./clients/corporateCrmClient.js";
import { CustomerService } from "./services/customerService.js";
import { AppError } from "./utils/errors.js";

export function buildApp(env: NodeJS.ProcessEnv): FastifyInstance {
  const config = loadConfig(env);

  const app = Fastify({
    logger: {
      level: config.NODE_ENV === "production" ? "info" : "debug"
    }
  });

  const crmClient = new HttpCorporateCrmClient(config.CRM_BASE_URL);
  const customerService = new CustomerService(crmClient);

  app.register(corporateContextPlugin);
  app.register(healthRoutes);
  app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "request failed");

    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message,
        requestId: request.id
      });
    }

    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred",
      requestId: request.id
    });
  });

  return app;
}
```

