# 8. Corporate auth middleware

In many enterprises, services sit behind API gateways or SSO proxies that inject headers. This example trusts a corporate header for simplicity.

## `src/middleware/corporate-auth.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";

export async function corporateAuth(
  request: FastifyRequest,
  reply: FastifyReply
): Promise<void> {
  const userIdHeader = request.headers["x-corporate-user-id"];
  const rolesHeader = request.headers["x-corporate-roles"];

  const userId =
    typeof userIdHeader === "string" && userIdHeader.length > 0
      ? userIdHeader
      : undefined;

  const roles =
    typeof rolesHeader === "string" && rolesHeader.length > 0
      ? rolesHeader.split(",").map((r) => r.trim()).filter(Boolean)
      : [];

  if (!userId) {
    reply.code(401).send({
      error: "Unauthorized",
      message: "Missing x-corporate-user-id header"
    });
    return;
  }

  request.corporateUser = {
    userId,
    roles
  };
}
```

