# 11. Service layer

This is where business logic lives.

## `src/services/customer-service.ts`

```ts
import { randomUUID } from "node:crypto";
import {
  CreateCustomerInput,
  Customer,
  CustomerId
} from "../domain/customer.js";
import { EventBus } from "../integrations/event-bus.js";
import { ErpClient } from "../integrations/erp-client.js";
import { CustomerRepository } from "../repositories/customer-repository.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly erpClient: ErpClient,
    private readonly eventBus: EventBus,
    private readonly customerCreatedTopic: string
  ) {}

  async createCustomer(
    input: CreateCustomerInput,
    createdBy: string
  ): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      email: input.email,
      name: input.name,
      createdBy
    };

    await this.repository.create(customer);
    await this.erpClient.notifyCustomerCreated(customer.id, customer.email);
    await this.eventBus.publish(this.customerCreatedTopic, {
      customerId: customer.id,
      email: customer.email,
      createdBy: customer.createdBy
    });

    return customer;
  }

  async getCustomerById(id: CustomerId): Promise<Customer | null> {
    return this.repository.findById(id);
  }
}
```

