## `src/routes/customers.ts`

```ts
import { FastifyInstance } from "fastify";
import {
  CreateCustomerInputSchema,
  CustomerIdSchema,
  CustomerSchema
} from "../domain/customer.js";
import { z } from "zod";

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  app.post("/customers", {
    preHandler: app.di.corporateAuth,
    schema: {
      tags: ["customers"],
      body: {
        type: "object",
        properties: {
          email: { type: "string", format: "email" },
          name: { type: "string", minLength: 1 }
        },
        required: ["email", "name"]
      },
      response: {
        201: {
          type: "object",
          properties: {
            id: { type: "string", format: "uuid" },
            email: { type: "string", format: "email" },
            name: { type: "string" },
            createdBy: { type: "string" }
          },
          required: ["id", "email", "name", "createdBy"]
        }
      }
    }
  }, async (request, reply) => {
    const body = CreateCustomerInputSchema.parse(request.body);
    const user = request.corporateUser;

    if (!user) {
      return reply.code(401).send({
        error: "Unauthorized"
      });
    }

    const customer = await app.di.customerService.createCustomer(body, user.userId);
    return reply.code(201).send(customer);
  });

  app.get("/customers/:id", {
    preHandler: app.di.corporateAuth,
    schema: {
      tags: ["customers"],
      params: {
        type: "object",
        properties: {
          id: { type: "string", format: "uuid" }
        },
        required: ["id"]
      },
      response: {
        200: {
          type: "object",
          properties: {
            id: { type: "string", format: "uuid" },
            email: { type: "string", format: "email" },
            name: { type: "string" },
            createdBy: { type: "string" }
          },
          required: ["id", "email", "name", "createdBy"]
        },
        404: {
          type: "object",
          properties: {
            error: { type: "string" }
          },
          required: ["error"]
        }
      }
    }
  }, async (request, reply) => {
    const params = z.object({ id: CustomerIdSchema }).parse(request.params);
    const customer = await app.di.customerService.getCustomerById(params.id);

    if (!customer) {
      return reply.code(404).send({ error: "Customer not found" });
    }

    return reply.send(customer);
  });
}
```

