# 13. App composition

## `src/app.ts`

```ts
import Fastify, { FastifyInstance } from "fastify";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { loadEnv, Env } from "./config/env.js";
import { customerRoutes } from "./routes/customers.js";
import { healthRoutes } from "./routes/health.js";
import { MockErpClient } from "./integrations/erp-client.js";
import { ConsoleEventBus } from "./integrations/event-bus.js";
import { InMemoryCustomerRepository } from "./repositories/customer-repository.js";
import { CustomerService } from "./services/customer-service.js";
import { corporateAuth } from "./middleware/corporate-auth.js";

export interface AppDependencies {
  env: Env;
  customerService: CustomerService;
  corporateAuth: typeof corporateAuth;
}

declare module "fastify" {
  interface FastifyInstance {
    di: AppDependencies;
  }
}

export function buildApp(): FastifyInstance {
  const env = loadEnv(process.env);

  const app = Fastify({
    logger: true
  });

  const repository = new InMemoryCustomerRepository();
  const erpClient = new MockErpClient();
  const eventBus = new ConsoleEventBus();
  const customerService = new CustomerService(
    repository,
    erpClient,
    eventBus,
    env.EVENT_BUS_TOPIC
  );

  app.decorate("di", {
    env,
    customerService,
    corporateAuth
  });

  app.register(swagger, {
    openapi: {
      info: {
        title: env.SERVICE_NAME,
        version: "1.0.0"
      }
    }
  });

  app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  app.register(healthRoutes);
  app.register(customerRoutes);

  return app;
}
```

