# 12. src/plugins/auth.ts

JWT auth middleware stub for corporate SSO.

```ts
import fp from "fastify-plugin";
import jwt from "jsonwebtoken";
import { FastifyReply, FastifyRequest } from "fastify";
import { config } from "../config.js";
import { AuthenticatedUser } from "../types.js";

function extractBearerToken(authHeader?: string): string | null {
  if (!authHeader) return null;
  const [scheme, token] = authHeader.split(" ");
  if (scheme !== "Bearer" || !token) return null;
  return token;
}

async function verifyAuth(request: FastifyRequest, reply: FastifyReply): Promise<void> {
  const token = extractBearerToken(request.headers.authorization);

  if (!token) {
    reply.code(401).send({
      error: "Unauthorized",
      message: "Missing or invalid bearer token"
    });
    return;
  }

  try {
    const decoded = jwt.verify(token, config.JWT_PUBLIC_KEY, {
      algorithms: ["HS256", "RS256"],
      issuer: config.JWT_ISSUER,
      audience: config.JWT_AUDIENCE
    }) as jwt.JwtPayload;

    const user: AuthenticatedUser = {
      sub: String(decoded.sub),
      email: typeof decoded.email === "string" ? decoded.email : undefined,
      roles: Array.isArray(decoded.roles)
        ? decoded.roles.filter((r): r is string => typeof r === "string")
        : []
    };

    request.user = user;
  } catch {
    reply.code(401).send({
      error: "Unauthorized",
      message: "Token verification failed"
    });
  }
}

export default fp(async (fastify) => {
  fastify.decorate("verifyAuth", verifyAuth);
});

declare module "fastify" {
  interface FastifyInstance {
    verifyAuth: (request: FastifyRequest, reply: FastifyReply) => Promise<void>;
  }
}
```

> Note: in a real enterprise setup, you would usually validate against the corporate IdP JWKS endpoint rather than a static key.

