```ts
import { FastifyPluginAsync } from "fastify";
import {
  createCustomerRequestSchema,
  customerIdSchema,
  customerSchema,
  errorResponseSchema
} from "../schemas/customer.js";
import { CustomerService } from "../services/customer-service.js";

interface CustomersRouteOptions {
  customerService: CustomerService;
}

const customerRoutes: FastifyPluginAsync<CustomersRouteOptions> = async (
  fastify,
  options
) => {
  fastify.get(
    "/v1/customers/:id",
    {
      preHandler: fastify.verifyAuth
    },
    async (request, reply) => {
      const params = customerIdSchema.parse((request.params as { id?: unknown }).id);
      const customer = await options.customerService.getCustomerById(params);

      if (!customer) {
        reply.status(404).send({
          error: "Not Found",
          message: "Customer not found"
        });
        return;
      }

      return customerSchema.parse(customer);
    }
  );

  fastify.post(
    "/v1/customers",
    {
      preHandler: fastify.verifyAuth
    },
    async (request, reply) => {
      const body = createCustomerRequestSchema.parse(request.body);
      const customer = await options.customerService.createCustomer(body);

      reply.status(201);
      return customerSchema.parse(customer);
    }
  );
};

export default customerRoutes;
```

