# 7. `src/plugins/corporateClient.ts`

A minimal integration client for an existing corporate system.

```ts
import { FastifyInstance } from "fastify";
import { config } from "../config.js";
import { Customer, CustomerSchema } from "../types.js";
import { UpstreamError } from "../utils/errors.js";

export interface CorporateClient {
  createCustomer(input: { name: string; email: string }): Promise<Customer>;
}

class HttpCorporateClient implements CorporateClient {
  async createCustomer(input: { name: string; email: string }): Promise<Customer> {
    const response = await fetch(`${config.CORPORATE_API_BASE_URL}/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${config.CORPORATE_API_TOKEN}`
      },
      body: JSON.stringify(input)
    });

    if (!response.ok) {
      throw new UpstreamError(`Corporate API returned ${response.status}`);
    }

    const json: unknown = await response.json();
    return CustomerSchema.parse(json);
  }
}

declare module "fastify" {
  interface FastifyInstance {
    corporateClient: CorporateClient;
  }
}

export async function registerCorporateClient(app: FastifyInstance): Promise<void> {
  app.decorate("corporateClient", new HttpCorporateClient());
}
```

