# 8. `src/plugins/corporateClient.ts`

A typed wrapper for an existing corporate system.

```ts
import axios, { AxiosInstance } from "axios";
import { FastifyInstance } from "fastify";
import { Employee } from "../types.js";

export interface CorporateClient {
  createEmployee(input: Omit<Employee, "id">): Promise<Employee>;
  getEmployeeById(id: string): Promise<Employee | null>;
}

class CorporateHttpClient implements CorporateClient {
  private readonly client: AxiosInstance;

  constructor(baseURL: string, token: string) {
    this.client = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      }
    });
  }

  async createEmployee(input: Omit<Employee, "id">): Promise<Employee> {
    const response = await this.client.post("/employees", input);
    return response.data as Employee;
  }

  async getEmployeeById(id: string): Promise<Employee | null> {
    try {
      const response = await this.client.get(`/employees/${encodeURIComponent(id)}`);
      return response.data as Employee;
    } catch (error: unknown) {
      if (axios.isAxiosError(error) && error.response?.status === 404) {
        return null;
      }
      throw error;
    }
  }
}

declare module "fastify" {
  interface FastifyInstance {
    corporateClient: CorporateClient;
  }
}

export async function registerCorporateClient(
  app: FastifyInstance,
  options: { baseURL: string; token: string }
): Promise<void> {
  const client = new CorporateHttpClient(options.baseURL, options.token);
  app.decorate("corporateClient", client);
}
```

