# 11. `src/routes/employees.ts`

Typed request handling with validation.

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { createEmployeeSchema } from "../schemas/employee.js";
import { EmployeeService } from "../services/employeeService.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function employeeRoutes(app: FastifyInstance): Promise<void> {
  const employeeService = new EmployeeService(app.corporateClient);

  app.post("/employees", async (request, reply) => {
    const body = createEmployeeSchema.parse(request.body);
    const employee = await employeeService.createEmployee(body);

    return reply.code(201).send(employee);
  });

  app.get("/employees/:id", async (request, reply) => {
    const params = paramsSchema.parse(request.params);
    const employee = await employeeService.getEmployee(params.id);

    if (employee === null) {
      return reply.code(404).send({
        message: "Employee not found"
      });
    }

    return reply.send(employee);
  });
}
```

