# 12. Customer route: `src/routes/customers.ts`

```ts
import { Router, Request, Response, NextFunction } from "express";
import { z } from "zod";
import { CorporateCustomerService } from "../services/corporateCustomerService";
import { CreateCustomerResponse } from "../types";

const router = Router();

const requestSchema = z.object({
  name: z.string().min(1).max(200),
  email: z.string().email()
});

export function createCustomerRouter(
  customerService: CorporateCustomerService
): Router {
  router.post(
    "/",
    async (
      req: Request,
      res: Response<CreateCustomerResponse>,
      next: NextFunction
    ) => {
      try {
        const body = requestSchema.parse(req.body);
        const customer = await customerService.createCustomer(body);
        res.status(201).json({ customer });
      } catch (error) {
        next(error);
      }
    }
  );

  return router;
}
```

