# 21. One important fix

There is a subtle issue in the `customers.ts` route as written: the router is declared once at module scope, which can cause duplicate route registration if `createCustomerRouter()` is called multiple times in tests or app composition.

Use this corrected version instead:

## Replace `src/routes/customers.ts` with:

```ts
import { Router, Request, Response, NextFunction } from "express";
import { z } from "zod";
import { CorporateCustomerService } from "../services/corporateCustomerService";
import { CreateCustomerResponse } from "../types";

const requestSchema = z.object({
  name: z.string().min(1).max(200),
  email: z.string().email()
});

export function createCustomerRouter(
  customerService: CorporateCustomerService
): Router {
  const router = Router();

  router.post(
    "/",
    async (
      req: Request,
      res: Response<CreateCustomerResponse>,
      next: NextFunction
    ) => {
      try {
        const body = requestSchema.parse(req.body);
        const customer = await customerService.createCustomer(body);
        res.status(201).json({ customer });
      } catch (error) {
        next(error);
      }
    }
  );

  return router;
}
```

