# src/services/corporateDirectoryClient.ts

A typed client for an existing corporate system.

```ts
import { request } from "undici";
import { z } from "zod";
import type { AppConfig } from "../config.js";
import type { Logger } from "pino";

const CorporateCreateUserResponseSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  first_name: z.string(),
  last_name: z.string(),
  department: z.string()
});

type CorporateCreateUserResponse = z.infer<typeof CorporateCreateUserResponseSchema>;

export class CorporateDirectoryClient {
  constructor(
    private readonly config: AppConfig,
    private readonly logger: Logger
  ) {}

  async createUser(input: {
    email: string;
    firstName: string;
    lastName: string;
    department: string;
  }): Promise<CorporateCreateUserResponse> {
    const url = `${this.config.CORP_DIRECTORY_BASE_URL}/api/users`;

    this.logger.info({ url, email: input.email }, "Creating user in corporate directory");

    const response = await request(url, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.config.CORP_DIRECTORY_API_KEY
      },
      body: JSON.stringify({
        email: input.email,
        first_name: input.firstName,
        last_name: input.lastName,
        department: input.department
      })
    });

    if (response.statusCode < 200 || response.statusCode >= 300) {
      const bodyText = await response.body.text();
      this.logger.error(
        { statusCode: response.statusCode, bodyText },
        "Corporate directory returned error"
      );
      throw new Error("Corporate directory integration failed");
    }

    const json = await response.body.json();
    return CorporateCreateUserResponseSchema.parse(json);
  }
}
```

