Typed route with runtime validation.

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CreateCustomerResponseSchema,
  ErrorResponseSchema
} from "../types.js";
import { CustomerService } from "../services/customerService.js";

const BodySchema = CreateCustomerRequestSchema;

export async function customerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.post(
    "/customers",
    async (request, reply) => {
      const body = BodySchema.parse(request.body);
      const customer = await deps.customerService.createCustomer(body);

      const response = CreateCustomerResponseSchema.parse({ customer });

      reply.status(201).send(response);
    }
  );

  app.get(
    "/customers/:id",
    async (request, reply) => {
      const ParamsSchema = z.object({
        id: z.string().uuid()
      });

      const params = ParamsSchema.parse(request.params);

      reply.status(200).send({
        customer: {
          id: params.id,
          email: "placeholder@example.com",
          firstName: "Jane",
          lastName: "Doe",
          department: "Engineering"
        }
      });
    }
  );

  void ErrorResponseSchema;
}
