```ts
import Fastify, { type FastifyInstance } from "fastify";
import { loadConfig } from "./config.js";
import { createLogger } from "./logger.js";
import { registerErrorHandler } from "./plugins/errorHandler.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { CorporateDirectoryClient } from "./services/corporateDirectoryClient.js";
import { CustomerService } from "./services/customerService.js";

export function buildApp(): FastifyInstance {
  const config = loadConfig(process.env);
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  registerErrorHandler(app);

  const corporateDirectoryClient = new CorporateDirectoryClient(config, logger);
  const customerService = new CustomerService(corporateDirectoryClient);

  void app.register(healthRoutes);
  void app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
