# 13. Service layer

## `src/services/customerService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { CreateCustomerInput, Customer } from "../domain/customer.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { ErpClient } from "../infrastructure/erpClient.js";
import type { EventBus } from "../infrastructure/eventBus.js";
import type { Logger } from "../infrastructure/logger.js";
import type { RequestContext } from "../types/requestContext.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly erpClient: ErpClient,
    private readonly eventBus: EventBus,
    private readonly logger: Logger
  ) {}

  async getCustomerById(id: string, ctx: RequestContext): Promise<Customer | null> {
    this.logger.info("Fetching customer", {
      correlationId: ctx.correlationId,
      customerId: id
    });

    return this.repository.findById(id);
  }

  async createCustomer(input: CreateCustomerInput, ctx: RequestContext): Promise<Customer> {
    this.logger.info("Creating customer", {
      correlationId: ctx.correlationId,
      userId: ctx.userId,
      email: input.email
    });

    const erpRecord = await this.erpClient.validateCustomerEligibility(input.email);

    if (erpRecord.status !== "ACTIVE") {
      throw new Error("Customer is not eligible according to ERP");
    }

    const customer: Customer = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString()
    };

    const created = await this.repository.create(customer);
    await this.eventBus.publishCustomerCreated(created);

    return created;
  }
}
```

