## `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance, FastifyRequest } from "fastify";
import {
  CreateCustomerInputSchema,
  CustomerIdSchema
} from "../domain/customer.js";
import type { CustomerService } from "../services/customerService.js";
import type { RequestContext } from "../types/requestContext.js";

interface GetCustomerParams {
  id: string;
}

export async function customerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get(
    "/api/v1/customers/:id",
    async (request: FastifyRequest<{ Params: GetCustomerParams }>, reply) => {
      const parsedId = CustomerIdSchema.safeParse(request.params.id);
      if (!parsedId.success) {
        return reply.status(400).send({ message: "Invalid customer id" });
      }

      const ctx: RequestContext = {
        correlationId: String(request.headers["x-correlation-id"] ?? "unknown"),
        userId: request.headers["x-user-id"]
          ? String(request.headers["x-user-id"])
          : null
      };

      const customer = await customerService.getCustomerById(parsedId.data, ctx);

      if (customer === null) {
        return reply.status(404).send({ message: "Customer not found" });
      }

      return reply.status(200).send(customer);
    }
  );

  app.post(
    "/api/v1/customers",
    async (request: FastifyRequest, reply) => {
      const parsedBody = CreateCustomerInputSchema.safeParse(request.body);

      if (!parsedBody.success) {
        return reply.status(400).send({
          message: "Invalid request body",
          issues: parsedBody.error.issues
        });
      }

      const ctx: RequestContext = {
        correlationId: String(request.headers["x-correlation-id"] ?? "unknown"),
        userId: request.headers["x-user-id"]
          ? String(request.headers["x-user-id"])
          : null
      };

      const customer = await customerService.createCustomer(parsedBody.data, ctx);
      return reply.status(201).send(customer);
    }
  );
}
```

