# 15. App wiring

## `src/app.ts`

```ts
import Fastify, { type FastifyInstance } from "fastify";
import { env } from "./config/env.js";
import { logger } from "./infrastructure/logger.js";
import { MockErpClient } from "./infrastructure/erpClient.js";
import { MockEventBus } from "./infrastructure/eventBus.js";
import { InMemoryCustomerRepository } from "./repositories/customerRepository.js";
import { CustomerService } from "./services/customerService.js";
import { healthRoutes } from "./routes/healthRoutes.js";
import { customerRoutes } from "./routes/customerRoutes.js";

export function buildApp(): FastifyInstance {
  const app = Fastify();

  const repository = new InMemoryCustomerRepository();
  const erpClient = new MockErpClient(env.ERP_BASE_URL, logger);
  const eventBus = new MockEventBus(env.EVENT_BUS_TOPIC, logger);
  const customerService = new CustomerService(
    repository,
    erpClient,
    eventBus,
    logger
  );

  app.setErrorHandler((error, request, reply) => {
    logger.error("Unhandled error", {
      message: error.message,
      correlationId: String(request.headers["x-correlation-id"] ?? "unknown")
    });

    reply.status(500).send({
      message: "Internal server error"
    });
  });

  app.register(healthRoutes);
  app.register(async (instance) => {
    await customerRoutes(instance, customerService);
  });

  return app;
}
```

