using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<OrderService> _logger;

    public OrderService(AppDbContext dbContext, ILogger<OrderService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var entity = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName,
            Description = request.Description,
            Amount = request.Amount,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Orders.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerName}", entity.Id, entity.CustomerName);

        return Map(entity);
    }

    public async Task<OrderResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var entity = await _dbContext.Orders
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

        return entity is null ? null : Map(entity);
    }

    public async Task<IReadOnlyCollection<OrderResponse>> GetAllAsync(CancellationToken cancellationToken)
    {
        var orders = await _dbContext.Orders
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .ToListAsync(cancellationToken);

        return orders.Select(Map).ToArray();
    }

    private static OrderResponse Map(Order entity) => new()
    {
        Id = entity.Id,
        CustomerName = entity.CustomerName,
        Description = entity.Description,
        Amount = entity.Amount,
        CreatedUtc = entity.CreatedUtc
    };
}
```

