using EnterpriseBackend.Api.Contracts;
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(AppDbContext dbContext, ILogger<CustomerService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IReadOnlyCollection<CustomerDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        var customers = await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .Select(x => new CustomerDto(x.Id, x.Name, x.Email, x.CreatedUtc))
            .ToListAsync(cancellationToken);

        return customers;
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new CustomerDto(x.Id, x.Name, x.Email, x.CreatedUtc))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken)
    {
        var existing = await _dbContext.Customers
            .AnyAsync(x => x.Email == request.Email, cancellationToken);

        if (existing)
        {
            throw new InvalidOperationException("A customer with this email already exists.");
        }

        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            Name = request.Name.Trim(),
            Email = request.Email.Trim().ToLowerInvariant(),
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Customers.Add(customer);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Customer created with ID {CustomerId}", customer.Id);

        return new CustomerDto(customer.Id, customer.Name, customer.Email, customer.CreatedUtc);
    }
}
```

