## Services/OrderService.cs

```csharp
using EnterpriseBackend.Data;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<OrderService> _logger;

    public OrderService(AppDbContext dbContext, ILogger<OrderService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<OrderResponse> CreateOrderAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerId = request.CustomerId,
            ProductCode = request.ProductCode,
            Quantity = request.Quantity,
            UnitPrice = request.UnitPrice,
            CreatedUtc = DateTime.UtcNow,
            Status = "Pending"
        };

        _dbContext.Orders.Add(order);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerId}", order.Id, order.CustomerId);

        return Map(order);
    }

    public async Task<OrderResponse?> GetOrderByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var order = await _dbContext.Orders
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

        return order is null ? null : Map(order);
    }

    public async Task<IReadOnlyList<OrderResponse>> GetOrdersAsync(CancellationToken cancellationToken)
    {
        var orders = await _dbContext.Orders
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .Take(500)
            .ToListAsync(cancellationToken);

        return orders.Select(Map).ToList();
    }

    private static OrderResponse Map(Order order) => new()
    {
        Id = order.Id,
        CustomerId = order.CustomerId,
        ProductCode = order.ProductCode,
        Quantity = order.Quantity,
        UnitPrice = order.UnitPrice,
        TotalPrice = order.Quantity * order.UnitPrice,
        Status = order.Status,
        CreatedUtc = order.CreatedUtc
    };
}
```

