                .HasMaxLength(200);

            entity.Property(x => x.Email)
                .IsRequired()
                .HasMaxLength(200);

            entity.Property(x => x.CreatedUtc)
                .IsRequired();

            entity.HasIndex(x => x.CustomerNumber)
                .IsUnique();
        });
    }
}
