## `CustomerService.cs`

```csharp
using EnterpriseBackend.Api.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(AppDbContext dbContext, ILogger<CustomerService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IEnumerable<CustomerDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        var customers = await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(c => c.Name)
            .Select(c => new CustomerDto
            {
                Id = c.Id,
                CustomerNumber = c.CustomerNumber,
                Name = c.Name,
                Email = c.Email
            })
            .ToListAsync(cancellationToken);

        return customers;
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .Where(c => c.Id == id)
            .Select(c => new CustomerDto
            {
                Id = c.Id,
                CustomerNumber = c.CustomerNumber,
                Name = c.Name,
                Email = c.Email
            })
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken)
    {
        var exists = await _dbContext.Customers
            .AnyAsync(c => c.CustomerNumber == request.CustomerNumber, cancellationToken);

        if (exists)
        {
            throw new InvalidOperationException($"Customer with number '{request.CustomerNumber}' already exists.");
        }

        var entity = new Customer
        {
            Id = Guid.NewGuid(),
            CustomerNumber = request.CustomerNumber,
            Name = request.Name,
            Email = request.Email,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Customers.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Customer created with ID {CustomerId} and number {CustomerNumber}", entity.Id, entity.CustomerNumber);

        return new CustomerDto
        {
            Id = entity.Id,
            CustomerNumber = entity.CustomerNumber,
            Name = entity.Name,
            Email = entity.Email
        };
    }
}
```

