using EnterpriseBackend.Application.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/v1/[controller]")]
[Authorize]
public class CustomersController : ControllerBase
{
    private readonly ICustomerService _customerService;

    public CustomersController(ICustomerService customerService)
    {
        _customerService = customerService;
    }

    [HttpGet]
    [ProducesResponseType(typeof(IEnumerable<CustomerResponse>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAll(CancellationToken cancellationToken)
    {
        var customers = await _customerService.GetCustomersAsync(cancellationToken);

        var response = customers.Select(c =>
            new CustomerResponse(c.Id, c.ExternalId, c.Name, c.Email, c.CreatedUtc));

        return Ok(response);
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(CustomerResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var customer = await _customerService.GetCustomerAsync(id, cancellationToken);

        if (customer is null)
            return NotFound();

        return Ok(new CustomerResponse(
            customer.Id,
            customer.ExternalId,
            customer.Name,
            customer.Email,
            customer.CreatedUtc));
    }

    [HttpPost]
    [ProducesResponseType(typeof(CustomerResponse), StatusCodes.Status201Created)]
    public async Task<IActionResult> Create(
        [FromBody] CreateCustomerRequest request,
        CancellationToken cancellationToken)
    {
        var customer = await _customerService.CreateCustomerAsync(
            request.ExternalId,
            request.Name,
            request.Email,
            cancellationToken);

        var response = new CustomerResponse(
            customer.Id,
            customer.ExternalId,
            customer.Name,
            customer.Email,
            customer.CreatedUtc);

        return CreatedAtAction(nameof(GetById), new { id = customer.Id }, response);
    }
}
