# 7. Application service layer

## `EnterpriseBackend.Application/Services/EmployeeService.cs`

```csharp
using EnterpriseBackend.Contracts.Employees;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Repositories;

namespace EnterpriseBackend.Application.Services;

public class EmployeeService
{
    private readonly EmployeeRepository _repository;

    public EmployeeService(EmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<List<EmployeeResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _repository.GetAllAsync(cancellationToken);

        return employees.Select(MapToResponse).ToList();
    }

    public async Task<EmployeeResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        return employee is null ? null : MapToResponse(employee);
    }

    public async Task<EmployeeResponse> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        if (await _repository.ExistsByEmployeeNumberAsync(request.EmployeeNumber, cancellationToken))
        {
            throw new InvalidOperationException("Employee number already exists.");
        }

        if (await _repository.ExistsByEmailAsync(request.Email, cancellationToken))
        {
            throw new InvalidOperationException("Email already exists.");
        }

        var employee = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = request.EmployeeNumber,
            FirstName = request.FirstName,
            LastName = request.LastName,
            Email = request.Email,
            Department = request.Department,
            CreatedUtc = DateTime.UtcNow
        };

        await _repository.AddAsync(employee, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return MapToResponse(employee);
    }

    public async Task<EmployeeResponse?> UpdateAsync(Guid id, UpdateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetTrackedByIdAsync(id, cancellationToken);
        if (employee is null)
        {
            return null;
        }

        employee.FirstName = request.FirstName;
        employee.LastName = request.LastName;
        employee.Email = request.Email;
        employee.Department = request.Department;
        employee.UpdatedUtc = DateTime.UtcNow;

        await _repository.SaveChangesAsync(cancellationToken);

        return MapToResponse(employee);
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetTrackedByIdAsync(id, cancellationToken);
        if (employee is null)
        {
            return false;
        }

        _repository.Remove(employee);
        await _repository.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static EmployeeResponse MapToResponse(Employee employee)
    {
        return new EmployeeResponse
        {
            Id = employee.Id,
            EmployeeNumber = employee.EmployeeNumber,
            FirstName = employee.FirstName,
            LastName = employee.LastName,
            Email = employee.Email,
            Department = employee.Department,
            CreatedUtc = employee.CreatedUtc,
            UpdatedUtc = employee.UpdatedUtc
        };
    }
}
```

