        return customers.Select(Map);
    }

    public async Task<CustomerResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var customer = await _customerRepository.GetByIdAsync(id, cancellationToken);
        return customer is null ? null : Map(customer);
    }

    public async Task<CustomerResponse> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        var existing = await _customerRepository.GetByExternalIdAsync(request.ExternalId, cancellationToken);
        if (existing is not null)
        {
            throw new InvalidOperationException($"Customer with ExternalId '{request.ExternalId}' already exists.");
        }

        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = request.ExternalId,
            Name = request.Name,
            Email = request.Email,
            CreatedUtc = DateTime.UtcNow,
            IsActive = true
        };

        var created = await _customerRepository.AddAsync(customer, cancellationToken);

        _logger.LogInformation("Customer created with Id {CustomerId} and ExternalId {ExternalId}", created.Id, created.ExternalId);

        return Map(created);
    }

    private static CustomerResponse Map(Customer customer) =>
        new()
        {
            Id = customer.Id,
            ExternalId = customer.ExternalId,
            Name = customer.Name,
            Email = customer.Email,
            CreatedUtc = customer.CreatedUtc,
            IsActive = customer.IsActive
        };
}
