    public DbSet<Employee> Employees => Set<Employee>();

    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var employee = modelBuilder.Entity<Employee>();

        employee.ToTable("Employees");
        employee.HasKey(x => x.Id);

        employee.Property(x => x.EmployeeNumber)
            .HasMaxLength(50)
            .IsRequired();

        employee.Property(x => x.FirstName)
            .HasMaxLength(100)
            .IsRequired();

        employee.Property(x => x.LastName)
            .HasMaxLength(100)
            .IsRequired();

        employee.Property(x => x.Email)
            .HasMaxLength(256)
            .IsRequired();

        employee.Property(x => x.Department)
            .HasMaxLength(100)
            .IsRequired();

        employee.HasIndex(x => x.EmployeeNumber).IsUnique();
        employee.HasIndex(x => x.Email).IsUnique();
    }

    public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        var now = DateTimeOffset.UtcNow;

        foreach (var entry in ChangeTracker.Entries<Employee>())
        {
            if (entry.State == EntityState.Added)
            {
                entry.Entity.CreatedAtUtc = now;
                entry.Entity.UpdatedAtUtc = now;
            }
            else if (entry.State == EntityState.Modified)
            {
                entry.Entity.UpdatedAtUtc = now;
            }
        }

        return await base.SaveChangesAsync(cancellationToken);
    }
}
