```csharp
using Enterprise.Backend.Api.Contracts;
using Enterprise.Backend.Api.Data;
using Enterprise.Backend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Api.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<EmployeeService> _logger;

    public EmployeeService(AppDbContext dbContext, ILogger<EmployeeService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await _dbContext.Employees
            .AsNoTracking()
            .OrderBy(x => x.LastName)
            .ThenBy(x => x.FirstName)
            .Select(MapToDto())
            .ToListAsync(cancellationToken);
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        return await _dbContext.Employees
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(MapToDto())
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken)
    {
        ValidateCreateRequest(request);

        var employee = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = request.EmployeeNumber.Trim(),
            FirstName = request.FirstName.Trim(),
            LastName = request.LastName.Trim(),
            Email = request.Email.Trim(),
            Department = request.Department.Trim()
        };

        _dbContext.Employees.Add(employee);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Employee created: {EmployeeId} {EmployeeNumber}", employee.Id, employee.EmployeeNumber);

        return ToDto(employee);
    }

    public async Task<EmployeeDto?> UpdateAsync(Guid id, UpdateEmployeeRequest request, CancellationToken cancellationToken)
    {
        ValidateUpdateRequest(request);

        var employee = await _dbContext.Employees.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (employee is null)
        {
            return null;
        }

        employee.FirstName = request.FirstName.Trim();
        employee.LastName = request.LastName.Trim();
        employee.Email = request.Email.Trim();
        employee.Department = request.Department.Trim();

        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Employee updated: {EmployeeId}", employee.Id);

        return ToDto(employee);
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken)
    {
        var employee = await _dbContext.Employees.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (employee is null)
        {
            return false;
        }

        _dbContext.Employees.Remove(employee);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Employee deleted: {EmployeeId}", employee.Id);

        return true;
    }

    private static void ValidateCreateRequest(CreateEmployeeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.EmployeeNumber))
            throw new ArgumentException("EmployeeNumber is required.");

        if (string.IsNullOrWhiteSpace(request.FirstName))
            throw new ArgumentException("FirstName is required.");

        if (string.IsNullOrWhiteSpace(request.LastName))
            throw new ArgumentException("LastName is required.");

        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.");

        if (string.IsNullOrWhiteSpace(request.Department))
            throw new ArgumentException("Department is required.");
    }

    private static void ValidateUpdateRequest(UpdateEmployeeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.FirstName))
            throw new ArgumentException("FirstName is required.");

        if (string.IsNullOrWhiteSpace(request.LastName))
            throw new ArgumentException("LastName is required.");

        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.");

        if (string.IsNullOrWhiteSpace(request.Department))
            throw new ArgumentException("Department is required.");
    }

    private static EmployeeDto ToDto(Employee employee) =>
        new(
            employee.Id,
            employee.EmployeeNumber,
            employee.FirstName,
            employee.LastName,
            employee.Email,
            employee.Department,
            employee.CreatedAtUtc,
            employee.UpdatedAtUtc
        );

    private static System.Linq.Expressions.Expression<Func<Employee, EmployeeDto>> MapToDto() =>
        employee => new EmployeeDto(
            employee.Id,
            employee.EmployeeNumber,
            employee.FirstName,
            employee.LastName,
            employee.Email,
            employee.Department,
            employee.CreatedAtUtc,
            employee.UpdatedAtUtc
        );
}
