**`src/Enterprise.Backend.Infrastructure/Repositories/ServiceBusEventPublisher.cs`**
```csharp
using System.Text.Json;
using Azure.Messaging.ServiceBus;
using Enterprise.Backend.Application.Interfaces;
using Microsoft.Extensions.Configuration;

namespace Enterprise.Backend.Infrastructure.Repositories;

public class ServiceBusEventPublisher : IEventPublisher
{
    private readonly ServiceBusClient _client;
    private readonly IConfiguration _configuration;

    public ServiceBusEventPublisher(ServiceBusClient client, IConfiguration configuration)
    {
        _client = client;
        _configuration = configuration;
    }

    public async Task PublishCustomerCreatedAsync(Guid customerId, string externalId, CancellationToken cancellationToken)
    {
        var topicName = _configuration["ServiceBus:CustomerTopic"]!;
        var sender = _client.CreateSender(topicName);

        var payload = new
        {
            EventType = "CustomerCreated",
            CustomerId = customerId,
            ExternalId = externalId,
            OccurredUtc = DateTime.UtcNow
        };

        var message = new ServiceBusMessage(JsonSerializer.Serialize(payload))
        {
            ContentType = "application/json",
            Subject = "CustomerCreated"
        };

        await sender.SendMessageAsync(message, cancellationToken);
    }
}
```

Register it in `Program.cs`:

```csharp
builder.Services.AddSingleton(_ =>
{
    var fullyQualifiedNamespace = builder.Configuration["ServiceBus:FullyQualifiedNamespace"];
    return new Azure.Messaging.ServiceBus.ServiceBusClient(
        fullyQualifiedNamespace,
        new Azure.Identity.DefaultAzureCredential());
});

builder.Services.AddScoped<IEventPublisher, ServiceBusEventPublisher>();
```

