# 6. API controller

## `Controllers/CustomersController.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class CustomersController : ControllerBase
    {
        private readonly AppDbContext _db;
        private readonly ILogger<CustomersController> _logger;

        public CustomersController(AppDbContext db, ILogger<CustomersController> logger)
        {
            _db = db;
            _logger = logger;
        }

        [HttpGet]
        [Authorize(Policy = "Api.Read")]
        public async Task<ActionResult<IEnumerable<Customer>>> GetAll(CancellationToken cancellationToken)
        {
            var customers = await _db.Customers
                .OrderBy(x => x.Name)
                .ToListAsync(cancellationToken);

            return Ok(customers);
        }

        [HttpGet("{id:guid}")]
        [Authorize(Policy = "Api.Read")]
        public async Task<ActionResult<Customer>> GetById(Guid id, CancellationToken cancellationToken)
        {
            var customer = await _db.Customers.FindAsync(new object[] { id }, cancellationToken);

            if (customer == null)
                return NotFound();

            return Ok(customer);
        }

        [HttpPost]
        [Authorize(Policy = "Api.Write")]
        public async Task<ActionResult<Customer>> Create([FromBody] CreateCustomerRequest request, CancellationToken cancellationToken)
        {
            var customer = new Customer
            {
                Id = Guid.NewGuid(),
                Name = request.Name,
                Email = request.Email,
                CreatedUtc = DateTime.UtcNow
            };

            _db.Customers.Add(customer);
            await _db.SaveChangesAsync(cancellationToken);

            _logger.LogInformation("Customer created: {CustomerId}", customer.Id);

            return CreatedAtAction(nameof(GetById), new { id = customer.Id }, customer);
        }
    }

    public class CreateCustomerRequest
    {
        public string Name { get; set; } = default!;
        public string? Email { get; set; }
    }
}
```

