```csharp
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Domain.Interfaces;

namespace EnterpriseBackend.Application.Services;

public class CustomerService
{
    private readonly ICustomerRepository _customerRepository;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(
        ICustomerRepository customerRepository,
        ILogger<CustomerService> logger)
    {
        _customerRepository = customerRepository;
        _logger = logger;
    }

    public async Task<IReadOnlyList<Customer>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _customerRepository.GetAllAsync(cancellationToken);
    }

    public async Task<Customer?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _customerRepository.GetByIdAsync(id, cancellationToken);
    }

    public async Task<Customer> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(request.ExternalId))
            throw new ArgumentException("ExternalId is required.");

        if (string.IsNullOrWhiteSpace(request.Name))
            throw new ArgumentException("Name is required.");

        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.");

        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = request.ExternalId,
            Name = request.Name,
            Email = request.Email,
            CreatedUtc = DateTime.UtcNow
        };

        _logger.LogInformation("Creating customer with ExternalId {ExternalId}", request.ExternalId);

        return await _customerRepository.CreateAsync(customer, cancellationToken);
    }
}
