# 8. Sample controller

## Controllers/v1/EmployeesController.cs

```csharp
using Asp.Versioning;
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using EnterpriseBackend.Api.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers.v1;

[ApiController]
[ApiVersion("1.0")]
[Route("api/v{version:apiVersion}/[controller]")]
[Authorize(Policy = "ApiAccess")]
public class EmployeesController : ControllerBase
{
    private readonly AppDbContext _dbContext;
    private readonly ICurrentUserService _currentUserService;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(
        AppDbContext dbContext,
        ICurrentUserService currentUserService,
        ILogger<EmployeesController> logger)
    {
        _dbContext = dbContext;
        _currentUserService = currentUserService;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Employee>>> GetAll(CancellationToken cancellationToken)
    {
        _logger.LogInformation("User {User} requested all employees", _currentUserService.GetUserName());

        var employees = await _dbContext.Employees
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync(cancellationToken);

        return Ok(employees);
    }

    [HttpGet("{id:int}")]
    public async Task<ActionResult<Employee>> GetById(int id, CancellationToken cancellationToken)
    {
        var employee = await _dbContext.Employees.FindAsync(new object[] { id }, cancellationToken);

        if (employee == null)
            return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public async Task<ActionResult<Employee>> Create(Employee employee, CancellationToken cancellationToken)
    {
        _dbContext.Employees.Add(employee);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("User {User} created employee {EmployeeNumber}",
            _currentUserService.GetUserName(),
            employee.EmployeeNumber);

        return CreatedAtAction(nameof(GetById), new { id = employee.Id, version = "1.0" }, employee);
    }
}
```

