# 5. Service layer

## `Services/ICustomerService.cs`

```csharp
using Enterprise.Backend.Api.Models;

namespace Enterprise.Backend.Api.Services;

public interface ICustomerService
{
    Task<IReadOnlyList<CustomerDto>> GetCustomersAsync(CancellationToken cancellationToken);
    Task<CustomerDto?> GetCustomerByIdAsync(int id, CancellationToken cancellationToken);
}
```

## `Services/CustomerService.cs`

```csharp
using Enterprise.Backend.Api.Data;
using Enterprise.Backend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Api.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(AppDbContext dbContext, ILogger<CustomerService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IReadOnlyList<CustomerDto>> GetCustomersAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Retrieving customers");

        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .Select(x => new CustomerDto
            {
                Id = x.Id,
                ExternalId = x.ExternalId,
                Name = x.Name,
                Email = x.Email
            })
            .ToListAsync(cancellationToken);
    }

    public async Task<CustomerDto?> GetCustomerByIdAsync(int id, CancellationToken cancellationToken)
    {
        _logger.LogInformation("Retrieving customer with id {CustomerId}", id);

        return await _dbContext.Customers
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new CustomerDto
            {
                Id = x.Id,
                ExternalId = x.ExternalId,
                Name = x.Name,
                Email = x.Email
            })
            .FirstOrDefaultAsync(cancellationToken);
    }
}
```

