public interface IOrderService
{
    IEnumerable<OrderDto> GetOrders();
}

public class OrderService : IOrderService
{
    public IEnumerable<OrderDto> GetOrders() =>
        new[]
        {
            new OrderDto(1, "Contoso Ltd", 1250.00m, DateTime.UtcNow)
        };
}

public record OrderDto(int Id, string CustomerName, decimal Total, DateTime CreatedUtc);
