## `Controllers/StatusController.cs`

```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

namespace EnterpriseBackend.Controllers;

[ApiController]
[Route("api/[controller]")]
public class StatusController : ControllerBase
{
    private readonly ILogger<StatusController> _logger;

    public StatusController(ILogger<StatusController> logger)
    {
        _logger = logger;
    }

    [HttpGet("public")]
    [AllowAnonymous]
    public IActionResult Public()
    {
        _logger.LogInformation("Public status endpoint called");
        return Ok(new
        {
            service = "EnterpriseBackend",
            status = "ok",
            timeUtc = DateTime.UtcNow
        });
    }

    [HttpGet("secure")]
    [Authorize(Policy = "ApiAccess")]
    public IActionResult Secure()
    {
        var userName = User.Identity?.Name ?? "unknown";
        var objectId = User.FindFirstValue("http://schemas.microsoft.com/identity/claims/objectidentifier")
                      ?? User.FindFirstValue("oid")
                      ?? "unknown";

        _logger.LogInformation("Secure status endpoint called by {UserName} ({ObjectId})", userName, objectId);

        return Ok(new
        {
            service = "EnterpriseBackend",
            status = "secure-ok",
            user = userName,
            objectId = objectId,
            timeUtc = DateTime.UtcNow
        });
    }
}
```

