## `Controllers/StatusController.cs`

```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class StatusController : ControllerBase
{
    private readonly AppDbContext _db;
    private readonly ILogger<StatusController> _logger;

    public StatusController(AppDbContext db, ILogger<StatusController> logger)
    {
        _db = db;
        _logger = logger;
    }

    [HttpGet("public-ping")]
    [AllowAnonymous]
    public IActionResult PublicPing()
    {
        return Ok(new
        {
            status = "ok",
            service = "EnterpriseBackend.Api",
            timeUtc = DateTime.UtcNow
        });
    }

    [HttpGet("secure-ping")]
    [Authorize]
    public IActionResult SecurePing()
    {
        return Ok(new
        {
            status = "authorized",
            user = User.Identity?.Name ?? "unknown",
            timeUtc = DateTime.UtcNow
        });
    }

    [HttpPost("record")]
    [Authorize]
    public async Task<IActionResult> RecordPing([FromBody] string message)
    {
        var record = new PingRecord
        {
            Message = message,
            CreatedUtc = DateTime.UtcNow
        };

        _db.PingRecords.Add(record);
        await _db.SaveChangesAsync();

        _logger.LogInformation("Ping record saved with id {Id}", record.Id);

        return Ok(record);
    }

    [HttpGet("records")]
    [Authorize]
    public async Task<IActionResult> GetRecords()
    {
        var records = await _db.PingRecords
            .OrderByDescending(x => x.CreatedUtc)
            .Take(50)
            .ToListAsync();

        return Ok(records);
    }
}
```

