use axum::{
    extract::State,
    http::{header, HeaderValue, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde_json::json;
use std::{net::SocketAddr, sync::Arc, time::Duration};
use tokio::{net::TcpListener, signal};
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    message: Arc<String>,
}

async fn health() -> impl IntoResponse {
    (StatusCode::OK, "OK")
}

async fn json_handler(State(state): State<AppState>) -> impl IntoResponse {
    let body = json!({
        "status": "success",
        "message": state.message.as_str()
    });

    let mut response = Json(body).into_response();
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    response
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState {
        message: Arc::new("Hello from a high-performance Rust server".to_string()),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/json", get(json_handler))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();

    let listener = TcpListener::bind(addr).await.unwrap();

    if let Err(e) = listener.set_ttl(64) {
        error!("failed to set TTL: {}", e);
    }

    info!("listening on {}", addr);

    let server = axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .tcp_nodelay(true);

    if let Err(err) = server.await {
        error!("server error: {}", err);
    }
}
```

