### `src/main.rs`

```rust
use std::{convert::Infallible, net::SocketAddr, sync::Arc};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

type RespBody = Full<Bytes>;

#[derive(Clone)]
struct AppState {
    hello_message: Arc<String>,
}

async fn handle_request(
    req: Request<Incoming>,
    state: AppState,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => {
            Response::new(Full::new(Bytes::from(state.hello_message.as_str().to_owned())))
        }
        (&Method::GET, "/health") => {
            Response::new(Full::new(Bytes::from_static(b"OK")))
        }
        (&Method::GET, "/json") => {
            let mut resp = Response::new(Full::new(Bytes::from_static(
                br#"{"status":"success","message":"hello"}"#,
            )));
            resp.headers_mut().insert(
                hyper::header::CONTENT_TYPE,
                hyper::header::HeaderValue::from_static("application/json"),
            );
            resp
        }
        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = ([0, 0, 0, 0], 8080).into();

    let listener = TcpListener::bind(addr).await?;
    println!("Listening on http://{}", addr);

    let state = AppState {
        hello_message: Arc::new("Hello, high-performance world!".to_string()),
    };

    loop {
        let (stream, _) = listener.accept().await?;
        let io = TokioIo::new(stream);
        let state = state.clone();

        tokio::spawn(async move {
            let service = service_fn(move |req| {
                let state = state.clone();
                handle_request(req, state)
            });

            if let Err(err) = hyper::server::conn::http1::Builder::new()
                .keep_alive(true)
                .serve_connection(io, service)
                .await
            {
                eprintln!("connection error: {}", err);
            }
        });
    }
}
```

