```rust
use axum::{
    extract::State,
    http::{HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Duration,
};
use tokio::{net::TcpListener, signal};
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    requests_served: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
    requests_served: u64,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    init_tracing();

    let worker_threads = num_cpus::get();
    info!("starting server with {} worker threads", worker_threads);

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/hello", get(hello))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();

    let listener = TcpListener::bind(addr).await.unwrap();

    info!("listening on {}", addr);

    let server = axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .tcp_nodelay(true);

    if let Err(err) = server.await {
        error!("server error: {}", err);
    }
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    let count = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = HealthResponse {
        status: "ok",
        requests_served: count,
    };

    Json(body)
}

async fn hello(State(state): State<AppState>) -> Response {
    let count = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = MessageResponse {
        message: "hello, world",
        requests_served: count,
    };

    let mut response = Json(body).into_response();
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    response
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
```

