        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{SystemTime, UNIX_EPOCH},
};
use tokio::signal;
use tower_http::{
    compression::CompressionLayer,
    trace::TraceLayer,
};
use tracing::{info, Level};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    timestamp: u64,
    requests_served: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
    requests_served: u64,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "high_perf_server=info,tower_http=info".to_string()),
        )
        .init();

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/hello", get(hello))
        .with_state(state)
        .layer(CompressionLayer::new())
        .layer(TraceLayer::new_for_http());

    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(8080);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    info!("starting server on {}", addr);
    info!("logical CPUs available: {}", num_cpus::get());

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind TCP listener");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    let count = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();

    let body = HealthResponse {
        status: "ok",
        timestamp: now,
        requests_served: count,
    };

    (StatusCode::OK, Json(body))
}

async fn hello(State(state): State<AppState>) -> impl IntoResponse {
    let count = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = MessageResponse {
        message: "Hello, world!",
        requests_served: count,
    };

    (StatusCode::OK, Json(body))
}

