use std::{convert::Infallible, net::SocketAddr};

use bytes::Bytes;
use http_body_util::{BodyExt, Full};
use hyper::{
    body::Incoming,
    http::StatusCode,
    server::conn::http1,
    service::service_fn,
    Method, Request, Response,
};
use hyper_util::rt::TokioIo;
use tokio::{net::TcpListener, signal};

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = ([0, 0, 0, 0], 8080).into();
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            biased;

            _ = &mut shutdown => {
                println!("Shutdown signal received");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, peer_addr) = match accept_result {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("Accept error: {}", err);
                        continue;
                    }
                };

                stream.set_nodelay(true)?;

                tokio::spawn(async move {
                    let io = TokioIo::new(stream);

                    let service = service_fn(handle_request);

                    if let Err(err) = http1::Builder::new()
                        .keep_alive(true)
                        .serve_connection(io, service)
                        .await
                    {
                        eprintln!("Connection error ({}): {}", peer_addr, err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_request(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => {
            text_response(StatusCode::OK, "high-performance Rust server\n")
        }

        (&Method::GET, "/health") => {
            text_response(StatusCode::OK, "OK")
        }

        (&Method::POST, "/echo") => {
            match req.into_body().collect().await {
                Ok(collected) => {
                    let bytes = collected.to_bytes();
                    Response::builder()
                        .status(StatusCode::OK)
                        .header("content-type", "application/octet-stream")
                        .body(Full::new(bytes))
                        .unwrap()
                }
                Err(_) => {
                    text_response(StatusCode::BAD_REQUEST, "failed to read request body")
                }
            }
        }

        _ => {
            text_response(StatusCode::NOT_FOUND, "not found")
        }
    };

    Ok(response)
}

fn text_response(status: StatusCode, body: &str) -> Response<RespBody> {
    Response::builder()
        .status(status)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::copy_from_slice(body.as_bytes())))
        .unwrap()
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
