```rust
use axum::{
    extract::State,
    http::{HeaderValue, Method, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Instant,
};
use tokio::{net::TcpListener, signal};
use tower_http::trace::TraceLayer;
use tracing::{info, Level};

#[derive(Clone)]
struct AppState {
    started_at: Instant,
    request_count: Arc<AtomicU64>,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_secs: u64,
    requests: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
    requests: u64,
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let body = HealthResponse {
        status: "ok",
        uptime_secs: state.started_at.elapsed().as_secs(),
        requests: state.request_count.load(Ordering::Relaxed),
    };

    (StatusCode::OK, Json(body))
}

async fn hello(State(state): State<AppState>) -> impl IntoResponse {
    let requests = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = MessageResponse {
        message: "hello, world",
        requests,
    };

    let mut response = Json(body).into_response();
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    response
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .with_env_filter("info")
        .init();

    let state = AppState {
        started_at: Instant::now(),
        request_count: Arc::new(AtomicU64::new(0)),
    };

    let app = Router::new()
        .route("/", get(hello))
        .route("/health", get(health))
        .with_state(state)
        .layer(TraceLayer::new_for_http());

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();

    let listener = TcpListener::bind(addr)
        .await
        .expect("failed to bind address");

    info!("server listening on {}", addr);
    info!("logical CPUs available: {}", num_cpus::get());

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}
```

