## Alternative: ultra-minimal Hyper server

If you want a lower-level version with fewer abstractions, here is a raw Hyper-based server:

```rust
use hyper::{
    body::Body,
    service::service_fn,
    Request, Response, Server, StatusCode,
};
use std::{
    convert::Infallible,
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
};

async fn handle(
    _req: Request<Body>,
    counter: Arc<AtomicU64>,
) -> Result<Response<Body>, Infallible> {
    let n = counter.fetch_add(1, Ordering::Relaxed) + 1;
    let body = format!(r#"{{"message":"hello","requests":{}}}"#, n);

    let response = Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "application/json")
        .body(Body::from(body))
        .unwrap();

    Ok(response)
}

#[tokio::main]
async fn main() {
    let counter = Arc::new(AtomicU64::new(0));

    let make_svc = hyper::service::make_service_fn(move |_| {
        let counter = counter.clone();
        async move {
            Ok::<_, Infallible>(service_fn(move |req| {
                handle(req, counter.clone())
            }))
        }
    });

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    let server = Server::bind(&addr).serve(make_svc);

    println!("listening on {}", addr);

    if let Err(err) = server.await {
        eprintln!("server error: {}", err);
    }
}
```

