## `src/main.rs`

```rust
use axum::{
    extract::State,
    http::{Request, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Json, Response},
    routing::get,
    Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Instant,
};
use tokio::signal;
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    started_at: Instant,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_secs: u64,
    total_requests: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    init_tracing();

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        started_at: Instant::now(),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/hello", get(hello))
        .route("/metrics", get(metrics))
        .layer(middleware::from_fn_with_state(
            state.clone(),
            request_middleware,
        ))
        .with_state(state);

    let port = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse::<u16>().ok())
        .unwrap_or(8080);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));

    info!("starting server on {}", addr);
    info!("logical CPUs available: {}", num_cpus::get());

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind TCP listener");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}

fn init_tracing() {
    let filter = std::env::var("RUST_LOG")
        .unwrap_or_else(|_| "info,tower_http=info,axum=info".to_string());

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    let uptime_secs = state.started_at.elapsed().as_secs();
    let total_requests = state.request_count.load(Ordering::Relaxed);

    let body = HealthResponse {
        status: "ok",
        uptime_secs,
        total_requests,
    };

    (StatusCode::OK, Json(body))
}

async fn hello() -> impl IntoResponse {
    let body = MessageResponse {
        message: "hello, world",
    };

    (StatusCode::OK, Json(body))
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    let total_requests = state.request_count.load(Ordering::Relaxed);
    let uptime_secs = state.started_at.elapsed().as_secs();

    let body = format!(
        "requests_total {}\nuptime_seconds {}\n",
        total_requests, uptime_secs
    );

    (StatusCode::OK, body)
}

async fn request_middleware(
    State(state): State<AppState>,
    req: Request<axum::body::Body>,
    next: Next,
) -> Response {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let method = req.method().clone();
    let path = req.uri().path().to_string();
    let start = Instant::now();

    let response = next.run(req).await;

    let status = response.status();
    let elapsed = start.elapsed();

    info!(
        method = %method,
        path = %path,
        status = %status,
        latency_ms = elapsed.as_millis(),
        "request completed"
    );

    response
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("received Ctrl+C, shutting down");
        }
        _ = terminate => {
            info!("received terminate signal, shutting down");
        }
    }
}
```

