```rust
use std::{convert::Infallible, net::SocketAddr};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

async fn router(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => ok("High-performance Rust server\n"),
        (&Method::GET, "/health") => ok("OK\n"),
        (&Method::GET, "/hello") => ok("Hello, world!\n"),
        _ => not_found(),
    };

    Ok(response)
}

fn ok(body: &'static str) -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(body)))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from("Not Found\n")))
        .unwrap()
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = ([0, 0, 0, 0], 8080).into();
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            biased;

            _ = &mut shutdown => {
                println!("Shutdown signal received");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, _peer) = match accept_result {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("Accept error: {}", err);
                        continue;
                    }
                };

                tokio::spawn(async move {
                    let io = TokioIo::new(stream);

                    let service = service_fn(router);

                    if let Err(err) = hyper::server::conn::http1::Builder::new()
                        .keep_alive(true)
                        .serve_connection(io, service)
                        .await
                    {
                        eprintln!("Connection error: {}", err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
