## `src/main.rs`

```rust
use std::{convert::Infallible, net::SocketAddr, time::Duration};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;
use tokio::signal;
use tokio::time::timeout;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    println!("listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            _ = &mut shutdown => {
                println!("shutdown signal received");
                break;
            }
            accept_result = listener.accept() => {
                let (stream, peer_addr) = match accept_result {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("accept error: {}", err);
                        continue;
                    }
                };

                stream.set_nodelay(true)?;

                tokio::spawn(async move {
                    let io = TokioIo::new(stream);

                    let service = service_fn(handle_request);

                    let conn = http1::Builder::new()
                        .keep_alive(true)
                        .max_buf_size(16 * 1024)
                        .serve_connection(io, service);

                    if let Err(err) = timeout(Duration::from_secs(30), conn).await {
                        eprintln!("connection timeout from {}: {}", peer_addr, err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_request(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => ok("hello"),
        (&Method::GET, "/health") => ok("ok"),
        (&Method::GET, "/ready") => ok("ready"),
        _ => not_found(),
    };

    Ok(response)
}

fn ok(body: &'static str) -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from_static(body.as_bytes())))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from_static(b"not found")))
        .unwrap()
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
```

