use axum::{
    extract::State,
    http::{HeaderMap, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{SystemTime, UNIX_EPOCH},
};
use tokio::net::TcpListener;
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    started_at_unix: u64,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_seconds: u64,
    total_requests: u64,
}

#[derive(Serialize)]
struct HelloResponse {
    message: &'static str,
    total_requests: u64,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    init_tracing();

    let worker_threads = std::env::var("WORKER_THREADS")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .filter(|&n| n > 0)
        .unwrap_or_else(num_cpus::get);

    info!("starting runtime with {} worker threads", worker_threads);

    let started_at_unix = now_unix();
    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        started_at_unix,
    };

    let app = Router::new()
        .route("/", get(root))
        .route("/health", get(health))
        .route("/ready", get(ready))
        .with_state(state);

    let addr: SocketAddr = std::env::var("BIND_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:8080".to_string())
        .parse()
        .expect("invalid BIND_ADDR");

    let listener = TcpListener::bind(addr)
        .await
        .expect("failed to bind TCP listener");

    info!("listening on {}", addr);

    let shutdown = shutdown_signal();

    if let Err(err) = axum::serve(listener, app)
        .with_graceful_shutdown(shutdown)
        .await
    {
        error!("server error: {}", err);
    }
}

async fn root(State(state): State<AppState>, headers: HeaderMap) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let user_agent = headers
        .get("user-agent")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("unknown");

    let total_requests = state.request_count.load(Ordering::Relaxed);

    (
        StatusCode::OK,
        Json(HelloResponse {
            message: if user_agent.contains("curl") {
                "hello, curl client"
            } else {
                "hello, world"
            },
            total_requests,
        }),
    )
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let uptime_seconds = now_unix().saturating_sub(state.started_at_unix);
    let total_requests = state.request_count.load(Ordering::Relaxed);

    (
        StatusCode::OK,
        Json(HealthResponse {
            status: "ok",
            uptime_seconds,
            total_requests,
        }),
    )
}

async fn ready() -> impl IntoResponse {
    StatusCode::OK
}

async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("received Ctrl+C, shutting down");
        }
        _ = terminate => {
            info!("received SIGTERM, shutting down");
        }
    }
}

fn init_tracing() {
    let filter = std::env::var("RUST_LOG")
        .unwrap_or_else(|_| "info,tower_http=info,axum=info".to_string());

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("system clock before UNIX_EPOCH")
        .as_secs()
}
```

